INSERT INTO `listenings` VALUES (1, NULL, '[{\"q\":\"Where does this conversation take place?\",\"options\":[\"Classroom\",\"Library\",\"Dormitory\",\"Cafeteria\"],\"answer\":1},{\"q\":\"How long can undergraduate students borrow books?\",\"options\":[\"Two weeks\",\"Three weeks\",\"Four weeks\",\"Five weeks\"],\"answer\":2},{\"q\":\"How can books be renewed?\",\"options\":[\"By phone\",\"In person\",\"Online\",\"By email\"],\"answer\":2}]', 'Campus Life Conversation', 'A: Hi, welcome to the university library. Can I help you find something? B: Yes, I am looking for books on English literature. A: They are on the third floor, section C. You can also use the online catalog. B: Thank you. How long can I borrow books? A: For undergraduate students, up to four weeks. You can renew online.', 1);
INSERT INTO `readings` VALUES (1, 'English is used in business, science, technology, and education around the world. Learning English opens up opportunities for personal and professional growth. In many countries, English is taught as a second language from an early age.', b'1', '[{\"q\":\"Why is English useful worldwide?\",\"options\":[\"It is used in many fields\",\"It has no grammar\",\"It is the oldest language\",\"It is only used in schools\"],\"answer\":0},{\"q\":\"What can learning English create?\",\"options\":[\"Fewer choices\",\"New opportunities\",\"Less communication\",\"Only exams\"],\"answer\":1}]', 'The Importance of Learning English', 1);
INSERT INTO `readings` VALUES (2, 'Environmental protection has become a pressing global issue. Climate change, pollution, and loss of biodiversity threaten the planet. Individuals can help by reducing waste, conserving energy, and supporting sustainable practices.', b'1', '[{\"q\":\"What threatens the planet?\",\"options\":[\"Climate change and pollution\",\"Better schools\",\"Longer holidays\",\"New books\"],\"answer\":0},{\"q\":\"How can individuals help?\",\"options\":[\"By wasting energy\",\"By reducing waste\",\"By buying more goods\",\"By ignoring nature\"],\"answer\":1}]', 'Environmental Protection', 1);
INSERT INTO `readings` VALUES (3, 'Climate change is one of the major challenges of the twenty-first century. Scientific evidence shows that global temperatures have risen substantially, largely because of human activity such as burning fossil fuels and cutting down forests.', b'1', '[{\"q\":\"What is a major cause of climate change in the passage?\",\"options\":[\"Human activity\",\"Ocean tides\",\"Old books\",\"Moonlight\"],\"answer\":0},{\"q\":\"What has happened to global temperatures?\",\"options\":[\"They have risen\",\"They have disappeared\",\"They never change\",\"They are unknown\"],\"answer\":0}]', 'Climate Change and Its Impact', 3);
