INSERT INTO `words` VALUES (1, 'We have a problem.', 'art. 一(个)；每一(个)', '/ə; eɪ | ə; e/', 'a', 1);
INSERT INTO `words` VALUES (2, 'How could she abandon her own child?', 'v. 丢弃；放弃，抛弃', '/ə\'bænd(ə)n | ə\'bændən/', 'abandon', 1);
INSERT INTO `words` VALUES (3, 'The test measures your mathematical ability.', 'n. 能力；能耐，本领', '/ə\'biliti | ə\'bɪlɪtɪ | ə\'bɪləti/', 'ability', 1);
INSERT INTO `words` VALUES (4, 'one of my more able students', 'adj. 有能力的；出色的', '/\'eibl | \'eɪb(ə)l | \'ebl/', 'able', 1);
INSERT INTO `words` VALUES (5, 'abnormal behaviour', 'adj. 不正常的；变态的', '/æb\'nɔ:məl | æb\'nɔːml | æbˈnɔːrml/', 'abnormal', 1);
INSERT INTO `words` VALUES (6, 'The plane crashed, killing all 200 people aboard.', 'adv. 在船(车)上；上船', '/ə\'bɔ:d | ə\'bɔːd | ə\'bɔrd/', 'aboard', 1);
INSERT INTO `words` VALUES (7, 'a book about politics', 'prep. 关于；在…周围', '/ə\'baut | ə\'baʊt/', 'about', 1);
INSERT INTO `words` VALUES (8, 'He lived in a flat above the shop.', 'prep. 在…上面；高于', '/ə\'bʌv/', 'above', 1);
INSERT INTO `words` VALUES (9, 'I’ve never lived abroad before.', 'adv. (在)国外；到处', '/ə\'brɔ:d | ə\'brɔːd | ə\'brɔd/', 'abroad', 1);
INSERT INTO `words` VALUES (10, 'The path ends off abruptly.', 'adv. 突然地', '/ə\'brʌptli | ə\'brʌptlɪ/', 'abruptly', 1);
INSERT INTO `words` VALUES (11, 'In the absence of any evidence, the police had to let Myers go.', 'n. 缺席，不在场；缺乏', '/\'æbsəns | \'æbs(ə)ns | \'æbsns/', 'absence', 1);
INSERT INTO `words` VALUES (12, 'He has been absent from his desk for two weeks.', 'adj. 缺席的', '/\'æbsənt, æb\'sent | \'æbs(ə)nt | ˈæbsənt/', 'absent', 1);
INSERT INTO `words` VALUES (13, 'Some of the stuff on TV is absolute rubbish.', 'adj. 绝对的；纯粹的', '/\'æbsəlju:t, ,æbsə\'lju:t | \'æbsəluːt | \'æbsəlut/', 'absolute', 1);
INSERT INTO `words` VALUES (14, 'He made his reasons for resigning absolutely clear.', 'adv. 完全地；绝对地', '/\'æbsəlju:tli, ,æbsə\'lju:tli | \'æbsəluːtlɪ | \'æbsəlutli/', 'absolutely', 1);
INSERT INTO `words` VALUES (15, 'Plants absorb nutrients from the soil.', 'v. 吸收（液体、气体等）', '/əb\'sɔ:b, -\'zɔ:b | əb\'sɔ:b | æbˈsɔrb; æbˈzɔrb; əbˈsɔrb/', 'absorb', 1);
INSERT INTO `words` VALUES (16, 'By the age of seven, children are capable of thinking in abstract terms .', 'adj. 抽象的', '/ˈæbstrækt | \'æbstrækt/', 'abstract', 1);
INSERT INTO `words` VALUES (17, 'an abundant supply of fresh water', 'adj. 大量的，丰富的', '/ə\'bʌndənt/', 'abundant', 1);
INSERT INTO `words` VALUES (18, 'Williams abused his position as Mayor to give jobs to his friends.', 'v. 滥用，虐待', '/ə\'bju:z, ə\'bju:s | ə\'bjuːz | ə\'bjus/', 'abuse', 1);
INSERT INTO `words` VALUES (19, 'He possessed no academic qualifications.', 'adj. 学校(院)的，学术的', '/,ækə\'demik | ,ækə\'dɛmɪk/', 'academic', 1);
INSERT INTO `words` VALUES (20, 'a military academy', 'n. 私立中学；专科院校', '/ə\'kædəmi | ə\'kædəmɪ/', 'academy', 1);
INSERT INTO `words` VALUES (21, 'measures to accelerate the rate of economic growth', 'v. 加速', '/ək\'seləreit | ək\'seləreɪt | əkˈsɛləˌret/', 'accelerate', 1);
INSERT INTO `words` VALUES (22, 'The latest model has excellent acceleration.', 'n. 加速；加速度', '/ək,selə\'reiʃən | əkselə\'reɪʃ(ə)n | ək\'sɛlə\'reʃən/', 'acceleration', 1);
INSERT INTO `words` VALUES (23, 'He had a strong Irish accent', 'n. 口音，腔调；重音', '/\'æksənt, æk\'sent | \'æks(ə)nt; -sent | \'æksɛnt/', 'accent', 1);
INSERT INTO `words` VALUES (24, 'Rick accepted her offer of coffee.', 'v. 接受；同意', '/ək\'sept | ə\'ksept | ækˈsɛpt; əkˈsɛpt/', 'accept', 1);
INSERT INTO `words` VALUES (25, 'Students who achieve an acceptable standard will progress to degree studies.', 'adj. 可接受的，合意的', '/ək\'septəbl | ək\'septəb(ə)l | ək\'sɛptəbl/', 'acceptable', 1);
INSERT INTO `words` VALUES (26, 'He wrote a letter of acceptance (= a letter in which you agree to accept a job, university place etc ) to the university.', 'n. 接受，验收；承认', '/ək\'septəns | ək\'sept(ə)ns | ək\'sɛptəns/', 'acceptance', 1);
INSERT INTO `words` VALUES (27, 'Users can access their voice mail remotely.', 'v. 获取; n. 接近，入口', '/\'ækses, \'æksəs, æk\'ses | \'ækses | \'æksɛs/', 'access', 1);
INSERT INTO `words` VALUES (28, NULL, 'n. 同谋，从犯', '/ək\'sesəri | ək\'sesərɪ | æk\'sɛsəri/', 'accessary', 1);
INSERT INTO `words` VALUES (29, 'The island is only accessible by boat.', 'adj. 易接近的', '/ək\'sesəbl | əkˈsesəbl | ək\'sɛsəbl/', 'accessible', 1);
INSERT INTO `words` VALUES (30, 'Over 70,000 people are seriously injured every year in road accidents.', 'n. 意外的；事故', '/\'æksidənt | \'æksɪdənt | \'æksədənt/', 'accident', 1);
INSERT INTO `words` VALUES (31, 'an accidental discharge of toxic waste', 'adj. 偶然的；非本质的', '/,æksi\'dentəl | æksɪ\'dent(ə)l | ,æksɪ\'dɛntl/', 'accidental', 1);
INSERT INTO `words` VALUES (32, 'The island was used to accommodate child refugees.', 'v. 适合， 提供住宿', '/ə\'kɔmədeit | ə\'kɒmədeɪt | ə\'kɑmədet/', 'accommodate', 1);
INSERT INTO `words` VALUES (33, '...people rented accommodation from a service that offers 250...', 'n. 招待设备；预定铺位', '/ə,kɔmə\'deiʃən | əkɒmə\'deɪʃ(ə)n | ə,kɑmə\'deʃən/', 'accommodation', 1);
INSERT INTO `words` VALUES (34, 'Children under 14 must be accompanied by an adult.', 'v. 陪伴', '/ə\'kʌmpəni | əˈkʌmpəni/', 'accompany', 1);
INSERT INTO `words` VALUES (35, 'We have accomplished all we set out to do.', 'v. 完成', '/ə\'kʌmpliʃ, ə\'kɔm- | ə\'kʌmplɪʃ | ə\'kɑmplɪʃ/', 'accomplish', 1);
INSERT INTO `words` VALUES (36, 'You will not be accorded any special treatment.', 'v. 使一致；给予', '/ə\'kɔ:d | ə\'kɔːd | ə\'kɔrd/', 'accord', 1);
INSERT INTO `words` VALUES (37, 'I am in accordance with him in this matter.', 'n. 一致；和谐；授予', '/ə\'kɔ:dəns | ə\'kɔːd(ə)ns | ə\'kɔrdns/', 'accordance', 1);
INSERT INTO `words` VALUES (38, '...according to a new report...', 'adj. 相等的， 一致的， 依…而定的', '/ə\'kɔːdɪŋ | ə\'kɔrdɪŋ/', 'according', 1);
INSERT INTO `words` VALUES (39, 'Some of the laws were contradictory. Accordingly, measures were taken to clarify them.', 'adv. 因此，所以；照着', '/ə\'kɔ:diŋli | ə\'kɔːdɪŋlɪ | ə\'kɔrdɪŋli/', 'accordingly', 1);
INSERT INTO `words` VALUES (40, 'The accounts for last year showed a profit of $2 million.', 'n. 记述；解释；帐目', '/ə\'kaʊnt/', 'account', 1);
INSERT INTO `words` VALUES (41, 'He is studying accountancy or he is an accountancy student.', 'n. 会计工作； 会计学', '/ə\'kauntənsi | ə\'kaʊntənsi/', 'accountancy', 1);
INSERT INTO `words` VALUES (42, 'Do you want me to invite your accountant to this meeting?', 'n. 会计人员， 会计师', '/ə\'kauntənt | ə\'kaʊntənt/', 'accountant', 1);
INSERT INTO `words` VALUES (43, 'It is unjust that a privileged few should continue to accumulate wealth.', 'v. 积累，增加', '/ə\'kju:mjuleit | ə\'kju:mjəleɪt | ə\'kjumjəlet/', 'accumulate', 1);
INSERT INTO `words` VALUES (44, 'He passes the ball with unerring accuracy.', 'n. 准确(性)；准确度', '/\'ækjurəsi | \'ækjʊrəsɪ | \'ækjərəsi/', 'accuracy', 1);
INSERT INTO `words` VALUES (45, 'The brochure tries to give a fair and accurate description of each hotel.', 'adj. 精确的，准确的', '/\'ækjurət | \'ækjʊrət | \'ækjərət/', 'accurate', 1);
INSERT INTO `words` VALUES (46, 'The main accusation levelled against him was that he tried to avoid military service.', 'n. 谴责； 【律】 指控', '/ˌækju\'zeɪʃn | ,ækju\'zeʃən/', 'accusation', 1);
INSERT INTO `words` VALUES (47, 'The professor stands accused of (= has been accused of ) stealing his student’s ideas and publishing them.', 'v. 指责；归咎于', '/ə\'kju:z | ə\'kjuːz | ə\'kjuz/', 'accuse', 1);
INSERT INTO `words` VALUES (48, 'She tried to accustom herself to the tight bandages.', 'v. 使习惯', '/ə\'kʌstəm/', 'accustom', 1);
INSERT INTO `words` VALUES (49, 'The pans were in their accustomed places.', 'adj. 惯常的；习惯的', '/ə\'kʌstəmd/', 'accustomed', 1);
INSERT INTO `words` VALUES (50, 'His feet were aching from standing so long.', 'v. 痛；想念; n. 疼痛', '/eik | eɪk | ek/', 'ache', 1);
INSERT INTO `words` VALUES (51, 'Frances achieved very good exam results.', 'v. 完成，实现', '/ə\'tʃiːv | ə\'tʃiv/', 'achieve', 1);
INSERT INTO `words` VALUES (52, 'His great achievement is to make all the players into a united team.', 'n. 完成；成就，成绩', '/ə\'tʃiːvm(ə)nt | ə\'tʃivmənt/', 'achievement', 1);
INSERT INTO `words` VALUES (53, 'sulphuric acid', 'n. 酸；酸的，酸性的', '/\'æsid | \'æsɪd/', 'acid', 1);
INSERT INTO `words` VALUES (54, 'The family acknowledge the need for change.', 'v. 承认(…的权威)', '/ək\'nɔlidʒ | ək\'nɑlɪdʒ/', 'acknowledge', 1);
INSERT INTO `words` VALUES (55, 'Have steps been taken to acquaint breeders with their right to apply for licenses?', 'vt. 使认识， 使了解', '/ə\'kweɪnt | ə\'kwent/', 'acquaint', 1);
INSERT INTO `words` VALUES (56, 'She was a casual acquaintance of my family in Vienna.', 'n. 认识；了解；熟人', '/ə\'kweintəns | ə\'kweɪnt(ə)ns | ə\'kwentəns/', 'acquaintance', 1);
INSERT INTO `words` VALUES (57, 'Manning hoped to acquire valuable works of art as cheaply as possible.', 'v. 获得', '/ə\'kwaiə | ə\'kwaɪə | ə\'kwaɪr/', 'acquire', 1);
INSERT INTO `words` VALUES (58, 'the acquisition of language', 'n. 取得， 获得， 习得； 获得物， 增添的人', '/ˌækwɪ\'zɪʃn | ,ækwɪ\'zɪʃən/', 'acquisition', 1);
INSERT INTO `words` VALUES (59, 'They own 200 acres of farmland.', 'n. 英亩(=607亩)', '/\'eikə | \'eɪkə | \'ekɚ/', 'acre', 1);
INSERT INTO `words` VALUES (60, '...The company\'s self-driving cars have done well over a million miles across various states in the US...', 'prep. 横过；在…对面', '/ə\'krɔs, ə\'krɔ:s | ə\'krɒs | ə\'krɔs/', 'across', 1);
INSERT INTO `words` VALUES (61, 'The company acted correctly in sacking him.', 'v. 行动；见效; n. 行为', '/ækt/', 'act', 1);
INSERT INTO `words` VALUES (62, 'The government must take action (= do something ) now to stop the rise in violent crime.', 'n. 行动；作用；功能', '/\'ækʃən | \'ækʃ(ə)n/', 'action', 1);
INSERT INTO `words` VALUES (63, 'games for active youngsters', 'adj. 活跃的；积极的', '/\'æktiv | \'æktɪv/', 'active', 1);
INSERT INTO `words` VALUES (64, 'Everyone is free to engage in peaceful political activity.', 'n. 活动；活力；行动', '/æk\'tivəti | æk\'tɪvɪtɪ | æk\'tɪviti/', 'activity', 1);
INSERT INTO `words` VALUES (65, 'His father was an actor in the Cantonese Opera Company.', 'n. 男演员；演剧的人', '/\'æktə | \'æktɚ/', 'actor', 1);
INSERT INTO `words` VALUES (66, 'She\'s not only a great dramatic actress but she\'s also very funny.', 'n. 女演员', '/\'æktris | \'æktrɪs/', 'actress', 1);
INSERT INTO `words` VALUES (67, 'I’m not joking. Those were his actual words.', 'adj. 实际的；现行的', '/\'æktʃuəl | \'æktʃʊəl; -tjʊəl/', 'actual', 1);
INSERT INTO `words` VALUES (68, 'I’ve known Barbara for years. Since we were babies, actually.', 'adv. 实际上；竟然', '/\'æktjʊəlɪ; -tʃʊ- | \'æktʃuəli/', 'actually', 1);
INSERT INTO `words` VALUES (69, 'Young children have a particularly acute sense of smell.', 'adj. 敏锐的', '/ə\'kju:t | ə\'kjuːt | ə\'kjut/', 'acute', 1);
INSERT INTO `words` VALUES (70, 'She replied to a lonely hearts ad she spotted in the New York Times.', 'n. 广告', '/æd | \'e \'di/', 'ad', 1);
INSERT INTO `words` VALUES (71, 'The ability to adapt is a definite asset in this job.', 'v. 适应于', '/ə\'dæpt/', 'adapt', 1);
INSERT INTO `words` VALUES (72, 'If the mixture seems dry, add water.', 'v. 添加，附加，掺加', '/æd/', 'add', 1);
INSERT INTO `words` VALUES (73, 'She helped him fight his drug addiction.', 'n. 上瘾', '/ə\'dikʃən | ə\'dɪkʃən/', 'addiction', 1);
INSERT INTO `words` VALUES (74, 'This is a fine book; a worthy addition to the series.', 'n. 加，加法；附加物', '/ə\'diʃən | ə\'dɪʃ(ə)n | ə\'dɪʃən/', 'addition', 1);
INSERT INTO `words` VALUES (75, 'Additional information can be obtained from the centre.', 'adj. 额外的', '/ə\'diʃənəl | ə\'dɪʃənl/', 'additional', 1);
INSERT INTO `words` VALUES (76, '...some countries have taken measures to address the effects of the global crisis...', 'v. 解决', '/ə\'dres | ə\'drɛs/', 'address', 1);
INSERT INTO `words` VALUES (77, 'Farmers have been slow to make adequate provision for their retirement.', 'adj. 足够的', '/\'ædikwit | ˈædɪkwət/', 'adequate', 1);
INSERT INTO `words` VALUES (78, 'In “the black cat” the adjective “black”modifies the noun “cat”.', 'n. 形容词; adj. 形容词的', '/\'ædʒiktiv | \'ædʒɪktɪv/', 'adjective', 1);
INSERT INTO `words` VALUES (79, 'Check and adjust the brakes regularly.', 'v. 调整，调节；校正', '/ə\'dʒʌst/', 'adjust', 1);
INSERT INTO `words` VALUES (80, 'We’re looking for someone with experience in administration.', 'n. 管理，政府', '/əd,mini\'streiʃən | ədmɪnɪ\'streɪʃ(ə)n | əd,mɪnɪ\'streʃən/', 'administration', 1);
INSERT INTO `words` VALUES (81, 'The job is mainly administrative.', 'adj. 管理的', '/əd\'ministrətiv | ədˈmɪnɪstrətɪv | əd\'mɪnɪstretɪv/', 'administrative', 1);
INSERT INTO `words` VALUES (82, 'Daniel gazed at her in admiration .', 'n. 钦佩，称赞', '/,ædmə\'reiʃən | ædmə\'reɪʃ(ə)n | ,ædmə\'reʃən/', 'admiration', 1);
INSERT INTO `words` VALUES (83, 'I really admire the way she brings up those kids all on her own.', 'v. 钦佩，称赞', '/əd\'maiə | ədˈmaɪr/', 'admire', 1);
INSERT INTO `words` VALUES (84, 'Reese, by his own admission , lacks the necessary experience.', 'n. 准许进(加)入；入场费；承认', '/əd\'miʃən | əd\'mɪʃən/', 'admission', 1);
INSERT INTO `words` VALUES (85, '‘Okay, so maybe I was a little bit scared,’ Jenny admitted.', 'v. 承认，容许', '/əd\'mit | əd\'mɪt/', 'admit', 1);
INSERT INTO `words` VALUES (86, 'Sally was adopted when she was four.', 'v. 收养；采用；采取', '/ə\'dɔpt | ə\'dɒpt | ə\'dɑpt/', 'adopt', 1);
INSERT INTO `words` VALUES (87, 'He was brought up by adoptive parents in Kentucky.', 'adj. 收养关系的； 采用的', '/ə\'dɒptɪv | ə\'dɑptɪv/', 'adoptive', 1);
INSERT INTO `words` VALUES (88, 'Some children find it difficult to talk to adults.', 'n. 成年人; adj. 成年的', '/\'ædʌlt, ə\'dʌlt | \'ædʌlt; ə\'dʌlt | \'ædʌlt/', 'adult', 1);
INSERT INTO `words` VALUES (89, 'I should warn you in advance that I’m not a very good dancer.', 'v & n. 前进，提前', '/əd\'vɑ:ns, əd\'væns | əd\'vɑ:ns | əd\'væns/', 'advance', 1);
INSERT INTO `words` VALUES (90, 'advanced learners of English', 'adj. 高级的', '/əd\'vɑ:nst, -\'vænst | ədˈvɑ:nst | əd\'vænst/', 'advanced', 1);
