INSERT INTO `words` VALUES (96, 'They no longer advertise alcohol or cigarettes at sporting events.', 'vt. 为…做广告， 宣传； 公告； 登广告', '/\'ædvətaɪz | \'ædvɚtaɪz/', 'advertise', 1);
