INSERT INTO `words` VALUES (209, 'We could not reason out which way the robbers escaped, because we were unable to find any trace of them.', 'adj. 什么，一些；任何的', '/\'eni | \'enɪ | \'ɛni/', 'any', 1);
INSERT INTO `words` VALUES (210, 'You should have a try, don\'t swallow anybody.', 'prep. 任何人', NULL, 'anybody', 1);
