INSERT INTO `words` VALUES (826, 'a debt collection agency', 'n. 搜集，收集；收藏品', '/kə\'lekʃən | kə\'lekʃ(ə)n | kə\'lɛkʃən/', 'collection', 1);
INSERT INTO `words` VALUES (827, 'a collective decision made by all board members', 'adj. 集体的；集合性的', '/kə\'lektiv | kə\'lektɪv | kə\'lɛktɪv/', 'collective', 1);
INSERT INTO `words` VALUES (828, 'a teacher training college', 'n. 学院；大学', '/\'kɔlidʒ | \'kɒlɪdʒ | \'kɑlɪdʒ/', 'college', 1);
INSERT INTO `words` VALUES (829, 'They were on their way to the airport when their van was involved in a collision with a car.', 'n. 撞击；冲突', '/kəˈlɪʒn | kə\'lɪʒən/', 'collision', 1);
INSERT INTO `words` VALUES (830, NULL, 'n. 陆军上校；中校', '/\'kə:nəl | \'kɜːn(ə)l | \'kɝnl/', 'colonel', 1);
INSERT INTO `words` VALUES (831, 'Algeria was formerly a French colony.', 'n. 殖民地；侨居地', '/\'kɒlənɪ | \'kɑləni/', 'colony', 1);
INSERT INTO `words` VALUES (832, '...yellow is an important color because of its unique symbolic meaning...', 'n. 颜色，彩色；颜料', '/\'kʌlə | \'kʌlə(r) | \'kʌlɚ/', 'color', 1);
INSERT INTO `words` VALUES (833, 'He writes a weekly column for ‘The Times’.', 'n. 专栏', '/\'kɔləm | ˈkɒləm | \'kɑləm/', 'column', 1);
INSERT INTO `words` VALUES (834, 'Your hair needs a good comb.', 'n. 梳子; v. 梳理', '/kəum | kəʊm | kom/', 'comb', 1);
INSERT INTO `words` VALUES (835, 'We flew over 200 combat missions in the war.', 'n. 战争，斗争，格斗; vt. 与…斗争， 与…战斗', '/\'kɒmbæt | \'kɑmbæt/', 'combat', 1);
INSERT INTO `words` VALUES (836, 'a combination nightclub and café', 'n. 联合，结合', '/,kɔmbi\'neiʃən | kɒmbɪ\'neɪʃ(ə)n | ,kɑmbɪ\'neʃən/', 'combination', 1);
INSERT INTO `words` VALUES (837, 'Diets are most effective when combined with exercise.', 'v. 联合，结合', '/kəm\'bain | kəm\'baɪn/', 'combine', 1);
INSERT INTO `words` VALUES (838, 'Let me know when they come.', 'v. 来，来到；出现', '/kʌm/', 'come', 1);
INSERT INTO `words` VALUES (839, 'a career in stand-up comedy', 'n. 喜剧， 喜剧性', '/\'kɒmədi | \'kɑmədi/', 'comedy', 1);
INSERT INTO `words` VALUES (840, 'I dress for comfort, not fashion.', 'n. 舒适；安慰; v. 安慰', '/\'kʌmfət | \'kʌmfɚt/', 'comfort', 1);
INSERT INTO `words` VALUES (841, 'I was so comfortable and warm in bed I didn’t want to get up.', 'adj. 舒适的，安慰的', '/\'kʌmfətəbl | ˈkʌmftəbl | \'kʌmftəbl/', 'comfortable', 1);
INSERT INTO `words` VALUES (842, 'He commands the 4th Battalion.', 'v. 命令，指挥；控制', '/kə\'mɑ:nd | kə\'mɑːnd | kə\'mænd/', 'command', 1);
INSERT INTO `words` VALUES (843, 'the American Commander, General Otis', 'n. 司令官，指挥员', '/kə\'mɑ:ndə | kə\'mɑːndə | kə\'mændɚ/', 'commander', 1);
INSERT INTO `words` VALUES (844, 'President Bush gave the commencement address today at the University of Notre Dame.', 'n. 毕业典礼', '/kə\'mensmənt | kə\'mensm(ə)nt | kə\'mɛnsmənt/', 'commencement', 1);
INSERT INTO `words` VALUES (845, 'He was fined for making abusive comments to the referee.', 'n. 评论', '/\'kɔment | \'kɒment | \'kɑmɛnt/', 'comment', 1);
INSERT INTO `words` VALUES (846, 'measures promoting local commerce and industry', 'n. 商业，贸易；社交', '/\'kɒmɜːs | \'kɑmɝs/', 'commerce', 1);
INSERT INTO `words` VALUES (847, 'Our top priorities must be profit and commercial growth.', 'adj. 商业的；商品化的', '/kə\'mə:ʃəl | kə\'mɜːʃ(ə)l | kə\'mɝʃəl/', 'commercial', 1);
INSERT INTO `words` VALUES (848, 'The Government set up a commission to investigate allegations of police violence.', 'n. 委任状；委员会', '/kə\'miʃən | kə\'mɪʃ(ə)n | kə\'mɪʃən/', 'commission', 1);
INSERT INTO `words` VALUES (849, 'Women commit fewer crimes than men.', 'v. 犯罪，承担义务', '/kə\'mit | kə\'mɪt/', 'commit', 1);
INSERT INTO `words` VALUES (850, 'Are you ready to make a long-term commitment ?', 'n. 承诺，保证', '/kə\'mitmənt | kə\'mɪtm(ə)nt | kə\'mɪtmənt/', 'commitment', 1);
INSERT INTO `words` VALUES (851, 'a committee meeting', 'n. 委员会', '/kə\'miti | kəˈmɪti | kə\'mɪti/', 'committee', 1);
INSERT INTO `words` VALUES (852, 'Heart disease is one of the commonest causes of death.', 'adj. 普通的；共同的', '/\'kɔmən | \'kɒmən | \'kɑmən/', 'common', 1);
INSERT INTO `words` VALUES (853, 'Sodium chloride is more commonly known as salt.', 'adv. 普通地，一般地', '/\'kɔmənli | \'kɒmənlɪ | \'kɑmənli/', 'commonly', 1);
INSERT INTO `words` VALUES (854, 'A baby communicates its needs by crying.', 'v. 通讯；传达；传播', '/kə\'mjuːnɪkeɪt | kə\'mjunɪket/', 'communicate', 1);
INSERT INTO `words` VALUES (855, 'a week’s course in improving communication skills', 'n. 通讯；传达；交通', '/kəmjuːnɪ\'keɪʃ(ə)n | kə,mjunɪ\'keʃən/', 'communication', 1);
INSERT INTO `words` VALUES (856, '...the ultimate triumph of communism in the world.', 'n. 共产主义', '/\'kɔmjunizəm | \'kɒmjʊnɪz(ə)m | \'kɑmjʊ\'nɪzəm/', 'communism', 1);
INSERT INTO `words` VALUES (857, 'Without the communists in France, the resistance might not have succeeded in World War II.', 'n. 共产党员', '/\'kɔmjunist | \'kɒmjʊnɪst | \'kɑmjənɪst/', 'communist', 1);
INSERT INTO `words` VALUES (858, 'The new arts centre will serve the whole community.', 'n. 社区；社会；公社', '/kə\'mju:niti | kə\'mjuːnɪtɪ | kə\'mjʊnəti/', 'community', 1);
INSERT INTO `words` VALUES (859, 'For ten years he had been her constant companion .', 'n. 同伴；共事者；伴侣', '/kəm\'pænjən | kəm\'pænɪən/', 'companion', 1);
INSERT INTO `words` VALUES (860, 'Which company do you work for?', 'n. 公司，商号；同伴', '/\'kʌmp(ə)ni | \'kʌmp(ə)nɪ | \'kʌmpəni/', 'company', 1);
INSERT INTO `words` VALUES (861, 'A car of comparable size would cost far more abroad.', 'adj. 可比较的； 类似的； 比得上的', '/\'kɒmpərəbl | \'kɑmpərəbl/', 'comparable', 1);
INSERT INTO `words` VALUES (862, 'After a lifetime of poverty, his last few years were spent in comparable comfort.', 'adj. 比较的，相对的', '/kəm\'pærətiv | kəm\'pærətɪv/', 'comparative', 1);
INSERT INTO `words` VALUES (863, 'The report compares the different types of home computer available.', 'v. 比较，对照', '/kəm\'peə(r) | kəm\'pɛr/', 'compare', 1);
INSERT INTO `words` VALUES (864, 'Her paintings invite comparison with those of the early Impressionists (= they remind you of them ) .', 'n. 比较，对照；比似', '/kəm\'pærisən | kəm\'pærɪs(ə)n | kəm\'pærɪsn/', 'comparison', 1);
INSERT INTO `words` VALUES (865, 'a map and compass', 'n. 罗盘，指南针；圆规', '/\'kʌmpəs/', 'compass', 1);
INSERT INTO `words` VALUES (866, 'I was shocked by the doctor’s lack of compassion .', 'n. 同情， 怜悯', '/kəm\'pæʃn | kəm\'pæʃən/', 'compassion', 1);
INSERT INTO `words` VALUES (867, '...the introduction of legislation to compel cyclists to wear a helmet.', 'v. 强迫', '/kəm\'pel | kəm\'pɛl/', 'compel', 1);
INSERT INTO `words` VALUES (868, 'Because my left eye is so weak, my right eye has to work harder to compensate.', 'v. 弥补，补偿', '/\'kɔmpenseit | \'kɒmpenseɪt | \'kɑmpɛnset/', 'compensate', 1);
INSERT INTO `words` VALUES (869, 'People who are wrongly arrested may be paid compensation .', 'n. 弥补，补偿', '/,kɔmpen\'seiʃən | ˌkɒmpenˈseɪʃn | ,kɑmpɛn\'seʃən/', 'compensation', 1);
INSERT INTO `words` VALUES (870, 'Me: What do you mean \"compete\"?', 'v. 竞争', '/kəm\'pi:t | kəm\'piːt | kəm\'pit/', 'compete', 1);
INSERT INTO `words` VALUES (871, 'A competent mechanic should be able to fix the problem.', 'adj. 胜任的，有能力的', '/\'kɔmpitənt | ˈkɒmpɪtənt | \'kɑmpɪtənt/', 'competent', 1);
INSERT INTO `words` VALUES (872, 'Going to trade fairs is an ideal opportunity to size up the competition .', 'n. 竞争，比赛', '/,kɔmpi\'tiʃən | kɒmpɪ\'tɪʃ(ə)n | ,kɑmpə\'tɪʃən/', 'competition', 1);
INSERT INTO `words` VALUES (873, 'Some US industries are not as competitive as they have been in the past.', 'adj. 竞争的， 比赛的； 好竞争的， 求胜心切的； 有竞争力的', '/kəm\'petətɪv | kəm\'pɛtətɪv/', 'competitive', 1);
INSERT INTO `words` VALUES (874, 'New machinery has enhanced the company’s productivity and competitiveness.', 'n. 竞争力', '/kəm\'petitivnis | kəm\'petətɪvnɪs | kəm\'pɛtətɪvnɪs/', 'competitiveness', 1);
INSERT INTO `words` VALUES (875, 'Last year they sold twice as many computers as their competitors.', 'n. 竞争者，对手', '/kəm\'petitə | kəm\'pɛtɪtɚ/', 'competitor', 1);
INSERT INTO `words` VALUES (876, 'The document was compiled by the Department of Health.', 'v. 编辑，编制，搜集', '/kəm\'pail | kəm\'paɪl/', 'compile', 1);
INSERT INTO `words` VALUES (877, 'Doctors have warned against complacency in fighting common diseases.', 'n. 自满，满足', '/kəm\'pleisənsi | kəmˈpleɪsnsi | kəm\'plesnsi/', 'complacency', 1);
INSERT INTO `words` VALUES (878, 'Residents are complaining because traffic in the area has increased.', 'v. 抱怨', '/kəm\'plein | kəm\'pleɪn | kəm\'plen/', 'complain', 1);
INSERT INTO `words` VALUES (879, 'If you wish to make a complaint, you should see the manager.', 'n. 抱怨; 投诉', '/kəm\'pleint | kəm\'plent/', 'complaint', 1);
INSERT INTO `words` VALUES (880, 'John and Bob complemented each other well.', 'v. 补充', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪment/', 'complement', 1);
INSERT INTO `words` VALUES (881, 'Students must complete the course.', 'v. 完成; adj. 完整的，彻底的', '/kəm\'pli:t | kəm\'plit/', 'complete', 1);
INSERT INTO `words` VALUES (882, 'I completely forgot that it’s his birthday today.', 'adv. 十分，完全地', '/kəm\'pli:tli | kəm\'pliːtlɪ | kəm\'plitli/', 'completely', 1);
INSERT INTO `words` VALUES (883, 'a complex system of highways', 'adj. 复杂的', '/\'kɔmpleks | ˈkɒmpleks | kəm\'plɛks; \'kɑm,plɛks/', 'complex', 1);
INSERT INTO `words` VALUES (884, 'If the answer to all of these questions is no, a framework will only complicate matters.', 'vt. 使复杂；使陷入', NULL, 'complicate', 1);
INSERT INTO `words` VALUES (885, 'a complicated voting system', 'adj. 复杂的，难懂的', '/\'kɔmplikeitid | \'kɑmplɪketɪd/', 'complicated', 1);
INSERT INTO `words` VALUES (886, 'The newspaper was asked by federal agents for assistance and agreed to comply.', 'v. 遵从', '/kəm\'plai | kəm\'plaɪ/', 'comply', 1);
INSERT INTO `words` VALUES (887, 'companies that make electronic components for computer products', 'n. 成分', '/kəm\'pəunənt | kəmˈpəʊnənt | kəm\'ponənt/', 'component', 1);
INSERT INTO `words` VALUES (888, 'Barrington has composed the music for a new production of ‘A Midsummer Night’s Dream’.', 'v. 组成，构成；创作', '/kəm\'pəuz | kəm\'pəʊz | kəm\'poz/', 'compose', 1);
INSERT INTO `words` VALUES (889, 'Some minerals have complex chemical compositions.', 'n. 构成；作品；写作', '/kɒmpə\'zɪʃ(ə)n | ,kɑmpə\'zɪʃən/', 'composition', 1);
INSERT INTO `words` VALUES (890, 'man-made organic compounds', 'n. 化合物；复合词', '/\'kɒmpaʊnd | \'kɑmpaʊnd/', 'compound', 1);
INSERT INTO `words` VALUES (891, 'Why you let her talk you into doing such a foolish thing is beyond my comprehension (= impossible for me to understand ) .', 'n. 理解，理解力；领悟', '/,kɔmpri\'henʃən | kɒmprɪ\'henʃ(ə)n | ,kɑmprɪ\'hɛnʃən/', 'comprehension', 1);
INSERT INTO `words` VALUES (892, 'We offer our customers a comprehensive range of financial products.', 'adj. 综合的，全面的', '/,kɔmpri\'hensiv | ˌkɒmprɪˈhensɪv | ˌkɑːmprɪˈhensɪv/', 'comprehensive', 1);
INSERT INTO `words` VALUES (893, 'Light silk is best for parachutes, as it compresses well and then expands rapidly.', 'v. 压紧，压缩', '/kəm\'pres, \'kɔmpres | kəm\'pres | kəm\'prɛs/', 'compress', 1);
INSERT INTO `words` VALUES (894, 'The house comprises two bedrooms, a kitchen, and a living room.', 'v. 包含，包括；构成', '/kəm\'praiz | kəm\'praɪz/', 'comprise', 1);
INSERT INTO `words` VALUES (895, 'Compromise is an inevitable part of marriage.', 'n. 妥协，和解', '/\'kɔmprəmaiz | \'kɒmprəmaɪz | \'kɑmprəmaɪz/', 'compromise', 1);
INSERT INTO `words` VALUES (896, 'Final results had not yet been computed.', 'v. 计算，估计，估算', '/kəm\'pju:t | kəm\'pjuːt | kəm\'pjʊt/', 'compute', 1);
INSERT INTO `words` VALUES (897, 'a huge global computer network', 'n. 计算机，电脑', '/kəm\'pju:tə | kəm\'pjuːtə | kəm\'pjutɚ/', 'computer', 1);
INSERT INTO `words` VALUES (898, 'Comrades, please support this motion.', 'n. 同志，亲密的同伴', '/\'kɔmrid | \'kɒmreɪd | \'kɑmræd/', 'comrade', 1);
INSERT INTO `words` VALUES (899, 'The shadows concealed her as she crept up to the house.', 'v. 把…隐藏起来', '/kən\'si:l | kən\'siːl | kən\'sil/', 'conceal', 1);
INSERT INTO `words` VALUES (900, '‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.', 'vt. 承认， 承认…为真； 承认失败； 允许， 让予； 让步， 认输', '/kən\'siːd | kən\'sid/', 'concede', 1);
INSERT INTO `words` VALUES (901, 'Now please concentrate.', 'v. 集中；聚集；浓缩', '/\'kɔnsəntreit | \'kɒns(ə)ntreɪt | \'kɑnsn\'tret/', 'concentrate', 1);
INSERT INTO `words` VALUES (902, 'The area has one of the world\'s greatest concentrations of wildlife.', 'n. 集中', '/,kɔnsən\'treiʃən | kɒns(ə)n\'treɪʃ(ə)n | \'kɑnsn\'treʃən/', 'concentration', 1);
INSERT INTO `words` VALUES (903, 'a new concept in business travel', 'n. 观点，观念', '/\'kɔnsept | \'kɑnsɛpt/', 'concept', 1);
INSERT INTO `words` VALUES (904, 'His main concern is to be able to provide for his family.', 'v & n. 涉及，关系到', '/kənˈsɜ:n | kən\'sɝn/', 'concern', 1);
INSERT INTO `words` VALUES (905, 'calls from young children concerning lost pets', 'prep. 关于', '/kən\'sə:niŋ | kən\'sɜːnɪŋ | kən\'sɝnɪŋ/', 'concerning', 1);
INSERT INTO `words` VALUES (906, 'a rock concert', 'n. 音乐会，演奏会', '/kən\'sə:t, \'kɔnsə:t | \'kɒnsət | \'kɑnsɚt/', 'concert', 1);
INSERT INTO `words` VALUES (907, 'The British were not prepared to make any concessions .', 'n. 让步， 妥协； 特许， 特许权； 承认， 认可', '/kən\'seʃn | kən\'sɛʃən/', 'concession', 1);
INSERT INTO `words` VALUES (908, 'When the investigation is concluded, the results will be sent to the US Attorney’s office.', 'v. 推断出；结束', '/kən\'klu:d | kən\'kluːd | kən\'klud/', 'conclude', 1);
INSERT INTO `words` VALUES (909, 'These are the report’s main conclusions.', 'n. 结论', '/kən\'klu:ʒən | kən\'kluːʒ(ə)n | kən\'kluʒn/', 'conclusion', 1);
INSERT INTO `words` VALUES (910, 'What does that mean in concrete terms ?', 'adj. 具体的', '/kən\'kri:t, \'kɔnkri:t | \'kɒŋkriːt | \'kɑŋkrit/', 'concrete', 1);
INSERT INTO `words` VALUES (911, 'Politicians were quick to condemn the bombing.', 'v. 谴责，指责；判刑', '/kən\'dem | kən\'dɛm/', 'condemn', 1);
INSERT INTO `words` VALUES (912, 'the mist which condensed on every cold surface', 'v. 压缩，使缩短', '/kən\'dens | kən\'dɛns/', 'condense', 1);
INSERT INTO `words` VALUES (913, 'Profits increased by £1.5m, despite the difficult economic conditions.', 'n. 状况，状态；环境', '/kən\'diʃən | kən\'dɪʃ(ə)n | kən\'dɪʃən/', 'condition', 1);
INSERT INTO `words` VALUES (914, 'The Senator’s conduct is being investigated by the Ethics Committee.', 'n. 举止，行为；指导', '/\'kɔndʌkt, kən\'dʌkt | \'kɒndʌkt | kən\'dʌkt/', 'conduct', 1);
INSERT INTO `words` VALUES (915, 'Graphite is a highly efficient conductor of electricity.', 'n. 售票员；(乐队)指挥', '/kən\'dʌktə | kən\'dʌktɚ/', 'conductor', 1);
INSERT INTO `words` VALUES (916, 'Representatives from over 100 countries attended the International Peace Conference in Geneva.', 'n. 会议，讨论会', '/\'kɒnf(ə)r(ə)ns | \'kɑnfərəns/', 'conference', 1);
INSERT INTO `words` VALUES (917, 'Occasionally people confess to crimes they haven’t committed just to get attention.', 'v. 供认，承认；坦白', '/kən\'fes | kən\'fɛs/', 'confess', 1);
INSERT INTO `words` VALUES (918, 'I felt I was doing well and my confidence began to grow.', 'n. 信心', '/\'kɔnfidəns | \'kɒnfɪdəns | \'kɑnfɪdəns/', 'confidence', 1);
INSERT INTO `words` VALUES (919, 'Despite her disability, Philippa is very confident.', 'adj. 确信的，自信的', '/\'kɔnfidənt | \'kɒnfɪd(ə)nt | \'kɑnfɪdənt/', 'confident', 1);
INSERT INTO `words` VALUES (920, 'a confidential government report', 'adj. 秘密的， 机密的； 亲信的', '/ˌkɒnfɪ\'denʃl | ,kɑnfɪ\'dɛnʃl/', 'confidential', 1);
INSERT INTO `words` VALUES (921, 'Vaughan is confined to a wheelchair .', 'v. 限制；禁闭', '/kən\'faɪn/', 'confine', 1);
INSERT INTO `words` VALUES (922, 'New evidence has confirmed the first witness’s story.', 'v. 确认；证实；批准', '/kən\'fə:m | kən\'fɝm/', 'confirm', 1);
INSERT INTO `words` VALUES (923, 'Personal ethics and professional ethics sometimes conflict.', 'v. 冲突', '/kən\'flikt, \'kɔnflikt | \'kɒnflɪkt | \'kɑnflɪkt/', 'conflict', 1);
INSERT INTO `words` VALUES (924, 'It is a solid, proven solution for adopting multiple standards -- whether your goal is to conform to the law or to improve your business practices.', 'v. 相一致，遵守', '/kən\'fɔ:m | kən\'fɔrm/', 'conform', 1);
INSERT INTO `words` VALUES (925, 'The problems confronting the new government were enormous.', 'v. 面对', '/kən\'frʌnt/', 'confront', 1);
INSERT INTO `words` VALUES (926, 'She had stayed in her room to avoid another confrontation.', 'n. 冲突，对抗', '/,kɔnfrʌn\'teiʃən | ,kɒnfrʌn\'teɪʃn | ,kɑnfrən\'teʃən/', 'confrontation', 1);
INSERT INTO `words` VALUES (927, 'People might well confuse the two products.', 'v. 使混淆，迷惑', '/kən\'fju:z | kənˈfju:z | kən\'fjʊz/', 'confuse', 1);
INSERT INTO `words` VALUES (928, 'To avoid confusion, the teams wore different colours.', 'n. 混乱；骚乱；混淆', '/kən\'fju:ʒən | kən\'fjuːʒ(ə)n | kən\'fjʊʒən/', 'confusion', 1);
INSERT INTO `words` VALUES (929, 'He never even stopped to congratulate me.', 'v. 祝贺，向…道喜', '/kən\'ɡrætʃu,leit | kən\'grætjʊleɪt | kən\'ɡrætʃulet/', 'congratulate', 1);
INSERT INTO `words` VALUES (930, 'letters of congratulation', 'n. 祝贺；祝贺词', '/kən,ɡrætʃu\'leiʃən | kəngrætjʊ\'leɪʃ(ə)n | kən,ɡrætʃu\'leʃən/', 'congratulation', 1);
INSERT INTO `words` VALUES (931, 'a congress of the ruling Labor Party', 'n. 大会；国会，议会', '/\'kɔŋɡres, kən\'ɡres | \'kɒŋgres | \'kɑŋɡrəs/', 'congress', 1);
INSERT INTO `words` VALUES (932, 'The worksheets are designed to be used in conjunction with the new course books.', 'n. 接合，连接；连接词', '/kən\'dʒʌŋkʃən | kən\'dʒʌŋ(k)ʃ(ə)n/', 'conjunction', 1);
INSERT INTO `words` VALUES (933, 'We’d like two rooms with connecting doors (= doors that join the rooms ) .', 'v. 连接，连结；联系', '/kə\'nekt | kə\'nɛkt/', 'connect', 1);
