INSERT INTO `words` VALUES (939, 'Well, at least I can face them all with a clear conscience (= the knowledge that you have done nothing wrong ) .', 'n. 良心', '/\'kɔnʃəns | ˈkɑːnʃəns/', 'conscience', 1);
INSERT INTO `words` VALUES (940, 'The driver was still conscious when the ambulance arrived.', 'adj. 意识到的；有意的', '/\'kɔnʃəs | \'kɒnʃəs | \'kɑnʃəs/', 'conscious', 1);
