INSERT INTO `words` VALUES (1277, 'The new property tax law won’t directly affect us.', 'adv. 直接地；立即', '/英 [dəˈrektli] 美 [dɪˈrɛktli, daɪ-] | dɪ\'rektlɪ; daɪ- | dəˈrektli/', 'directly', 1);
INSERT INTO `words` VALUES (1278, 'The company is run by a board of directors (= a group of directors ) .', 'n. 指导者；理事；导演', '/di\'rektə | dɪ\'rektə; daɪ- | dɪˈrɛktɚ; daɪˈrɛktɚ/', 'director', 1);
INSERT INTO `words` VALUES (1279, 'You should have seen the dirt on that car!', 'n. 尘，土；污物，污垢', '/də:t | dɜːt | dɝt/', 'dirt', 1);
INSERT INTO `words` VALUES (1280, 'a stack of dirty dishes in the sink', 'adj. 脏的；下流的', '/\'də:ti | \'dɜːtɪ | ˈdɝ​tɪ/', 'dirty', 1);
INSERT INTO `words` VALUES (1281, 'Carter was permanently disabled in the war.', 'v. 使无能，使伤残', '/dis\'eib | dɪs\'eɪb(ə)l | dɪs\'ebl/', 'disable', 1);
INSERT INTO `words` VALUES (1282, 'Criminal behaviour can be linked to economic disadvantage.', 'n. 不利情况，缺点', '/disəd\'vɑ:ntidʒ | dɪsəd\'vɑːntɪdʒ | ,dɪsəd\'væntɪdʒ/', 'disadvantage', 1);
INSERT INTO `words` VALUES (1283, 'Barr strongly disagreed with Kronfeld’s statement.', 'v. 有分歧；不一致', '/,disə\'ɡri: | dɪsə\'griː | ,dɪsə\'ɡri/', 'disagree', 1);
INSERT INTO `words` VALUES (1284, 'At this point the path seemed to disappear altogether (= disappear completely ) .', 'v. 不见，消失', '/,disə\'piə | ˌdɪsə\'pɪə(r) | \'dɪsə\'pɪr/', 'disappear', 1);
INSERT INTO `words` VALUES (1285, 'I hated to disappoint her.', 'v. 使失望，使受挫折', '/,disə\'pɔint | dɪsə\'pɒɪnt | \'dɪsə\'pɔɪnt/', 'disappoint', 1);
INSERT INTO `words` VALUES (1286, 'disappointing profit figures', 'adj. 令人失望的', '/,disə\'pɔintiɡ | dɪsə\'pɒɪntɪŋ | ,dɪsə\'pɔɪntɪŋ/', 'disappointing', 1);
INSERT INTO `words` VALUES (1287, 'One hundred and twenty people died in China’s worst air disaster .', 'n. 灾难，灾祸；天灾', '/,di\'zɑ:stə | dɪ\'zɑːstə | dɪ\'zæstɚ/', 'disaster', 1);
INSERT INTO `words` VALUES (1288, 'Read the manufacturer\'s guidelines before discarding the box.', 'v. 丢弃，抛弃，遗弃', '/dis\'kɑ:d, \'diskɑ:d | dɪ\'skɑːd | dɪsˈkɑːrd/', 'discard', 1);
INSERT INTO `words` VALUES (1289, 'Hospitals now tend to discharge patients earlier than in the past.', 'v. 释放；排出 解雇', '/dis\'tʃɑ:dʒ, \'distʃɑ:dʒ, dis\'tʃ- | dis\'tʃɑ:dʒ | dɪs\'tʃɑrdʒ/', 'discharge', 1);
INSERT INTO `words` VALUES (1290, 'The book gives parents advice on discipline.', 'n. 纪律；训练; v. 训练', '/\'disiplin | \'dɪsɪplɪn | \'dɪsəplɪn/', 'discipline', 1);
INSERT INTO `words` VALUES (1291, 'Some companies have already voluntarily disclosed similar information .', 'v. 揭开，揭发；透露', '/dis\'kləuz | dɪs\'kləʊz | dɪs\'kloz/', 'disclose', 1);
