INSERT INTO `words` VALUES (1295, 'I felt I\'d made an incredible discovery.', 'n. 发现；被发现的事物', '/dis\'kʌvəri | dɪ\'skʌv(ə)rɪ | dɪ\'skʌvəri/', 'discovery', 1);
INSERT INTO `words` VALUES (1296, 'laws to prevent discrimination', 'n. 歧视', '/dis,krimi\'neiʃən | dɪ,skrɪmɪ\'neɪʃ(ə)n | dɪ,skrɪmɪ\'neʃən/', 'discrimination', 1);
INSERT INTO `words` VALUES (1297, 'Littman refused to discuss the case publicly.', 'v. 讨论，谈论；论述', '/dis\'kʌs | dɪ\'skʌs/', 'discuss', 1);
INSERT INTO `words` VALUES (1298, 'class discussions', 'n. 讨论，谈论；论述', '/dis\'kʌʃən | dɪ\'skʌʃ(ə)n | dɪ\'skʌʃən/', 'discussion', 1);
INSERT INTO `words` VALUES (1299, 'His father died of heart disease.', 'n. 病，疾病；病害', '/di\'zi:z | dɪ\'ziːz | dɪ\'ziz/', 'disease', 1);
INSERT INTO `words` VALUES (1300, 'He made no attempt to disguise his agitation.', 'v. 隐瞒，掩埋; n. 假装', '/dis\'ɡaiz | dɪs\'gaɪz | dɪs\'ɡaɪz/', 'disguise', 1);
INSERT INTO `words` VALUES (1301, 'He reached into the bin with a look of disgust on his face.', 'n. 厌恶，憎恶', '/dis\'ɡʌst | dɪs\'gʌst | dɪs\'ɡʌst/', 'disgust', 1);
INSERT INTO `words` VALUES (1302, 'a serving dish', 'n. 碟，盘子；菜肴', '/dɪʃ/', 'dish', 1);
INSERT INTO `words` VALUES (1303, 'dishonest traders', 'adj. 不诚实的', '/dis\'ɔnist | dɪsˈɒnɪst | dɪs\'ɑnɪst/', 'dishonest', 1);
INSERT INTO `words` VALUES (1304, 'I dare not quit my post, though an unfaithful sentinel, whose sure reward is death and dishonour, when his dreary watch shall come to an end!', 'n. 不光彩；丢脸的人', '/dis\'ɔnə | dɪs\'ɑnɚ/', 'dishonour', 1);
