INSERT INTO `words` VALUES (1312, 'If there are aspects of your life that displease you make you feel regret, this is an opportunity to change direction.', 'v. 使不愉快，使生气', '/dis\'pli:z | dɪs\'pliːz | dɪs\'pliz/', 'displease', 1);
