INSERT INTO `words` VALUES (1314, 'Chinese vases are disposed around the gallery.', 'v. 去掉，丢掉；销毁', '/dis\'pəuz | dɪ\'spəʊz | dɪ\'spoz/', 'dispose', 1);
INSERT INTO `words` VALUES (1315, 'It is beyond dispute that advances in medicine have enabled people to live longer.', 'n & v. 辩论，争论', '/dis\'pju:t, \'dis- | dɪ\'spju:t | \'dɪs\'pjʊt/', 'dispute', 1);
INSERT INTO `words` VALUES (1316, 'More or other, they still dissatisfy.', 'v. 不满意', '/,dis\'sætisfai | dɪ(s)\'sætɪsfaɪ | dɪs\'sætɪs,fai/', 'dissatisfy', 1);
INSERT INTO `words` VALUES (1317, 'He said the protesters were doing a disservice to the nation.', 'n. 伤害，帮倒忙', '/,dis\'sə:vis | dɪsˈsɜ:vɪs | dɪs\'sɝvɪs/', 'disservice', 1);
