INSERT INTO `words` VALUES (1324, 'Could he distinguish right from wrong?', 'v. 区别，区分', '/dis\'tiŋɡwiʃ | di\'stiŋgwiʃ | dɪ\'stɪŋɡwɪʃ/', 'distinguish', 1);
