INSERT INTO `words` VALUES (1505, 'Smoking during pregnancy endangers your baby’s life.', 'v. 危及，危害，濒临危险', '/in\'deindʒə | ɪnˈdeɪndʒə(r) | ɪn\'dendʒɚ/', 'endanger', 1);
