INSERT INTO `words` VALUES (1507, 'an endless stream of visitors', 'adj. 无止境的', '/\'endlis | \'endlɪs | \'ɛndləs/', 'endless', 1);
INSERT INTO `words` VALUES (1508, 'She was pushed beyond her powers of endurance.', 'n. 耐力', '/in\'djuərəns | ɪn\'dʊrəns/', 'endurance', 1);
INSERT INTO `words` VALUES (1509, 'It seemed impossible that anyone could endure such pain.', 'v. 忍耐；容忍', '/in\'djuə | ɪn\'djʊə | ɪn\'dʊr/', 'endure', 1);
INSERT INTO `words` VALUES (1510, 'She’s a dangerous enemy to have.', 'n. 敌人；仇敌；敌兵', '/\'enimi | \'enəmɪ | \'ɛnəmi/', 'enemy', 1);
INSERT INTO `words` VALUES (1511, 'an energetic man', 'adj. 精力充沛的', '/,enə\'dʒetik | ˌenəˈdʒetɪk | ,ɛnɚ\'dʒɛtɪk/', 'energetic', 1);
INSERT INTO `words` VALUES (1512, 'The water is heated using energy from the sun.', 'n. 活力；精力；能', '/\'enədʒi | \'enədʒɪ | \'ɛnɚdʒi/', 'energy', 1);
INSERT INTO `words` VALUES (1513, 'Parking restrictions will be strictly enforced.', 'v. 实施，执行；强制', '/in\'fɔ:s | ɪn\'fɔːs; en- | ɪn\'fɔrs/', 'enforce', 1);
INSERT INTO `words` VALUES (1514, 'I have never engaged in drug trafficking.', 'v. 忙于，从事；吸引', '/in\'ɡeidʒ | ɪn\'geɪdʒ | ɪn\'ɡedʒ/', 'engage', 1);
INSERT INTO `words` VALUES (1515, 'Their engagement was announced in the paper.', 'n. 约会', '/ɪnˈgeɪdʒmənt | ɪn\'ɡedʒmənt/', 'engagement', 1);
INSERT INTO `words` VALUES (1516, 'Is the engine running smoothly?', 'n. 引擎，发动机', '/\'endʒin | ˈendʒɪn | \'ɛndʒɪn/', 'engine', 1);
INSERT INTO `words` VALUES (1517, 'He trained as a civil engineer (= one who designs and builds roads, bridges etc ).', 'n. 工程师，技师', '/,endʒi\'niə | endʒɪ\'nɪə | ,ɛndʒɪ\'nɪr/', 'engineer', 1);
INSERT INTO `words` VALUES (1518, 'Their inventions have contributed to the development of electrical engineering.', 'n. 工程，工程学', '/,endʒi\'niəriŋ | endʒɪ\'nɪərɪŋ | \'ɛndʒə\'nɪrɪŋ/', 'engineering', 1);
INSERT INTO `words` VALUES (1519, '...I\'d like to get back to the 18th century and perhaps in colonial America in Yankee new England where one of my ancestors lived...', 'n. 英格兰；英国', '/ˈɪŋɡlənd | \'iŋɡlənd/', 'England', 1);
INSERT INTO `words` VALUES (1520, 'Do you speak English?', 'n. 英语; adj. 英国人的', '/\'iŋɡliʃ | \'ɪŋɡlɪʃ | ɪŋɡlɪʃ/', 'English', 1);
INSERT INTO `words` VALUES (1521, 'He was the only Englishman present.', 'n. 英国男子', '/\'iŋɡliʃmən/', 'Englishman', 1);
INSERT INTO `words` VALUES (1522, 'Good lighting will enhance any room.', 'v. 提高；加强；增加', '/in\'hɑ:ns, -hæns | in\'hɑ:ns | ɪn\'hæns/', 'enhance', 1);
INSERT INTO `words` VALUES (1523, 'Sandra enjoys her job in the city.', 'v. 享受；欣赏，喜爱', '/in\'dʒɔi | ɪn\'dʒɒɪ; en- | ɪn\'dʒɔɪ/', 'enjoy', 1);
INSERT INTO `words` VALUES (1524, 'an operation to enlarge her breasts', 'v. 扩大，扩展；放大', '/in\'lɑ:dʒ | ɪn\'lɑːdʒ; en- | ɪn\'lɑrdʒ/', 'enlarge', 1);
INSERT INTO `words` VALUES (1525, 'an enormous bunch of flowers', 'adj. 巨大的', '/i\'nɔ:məs | ɪ\'nɔrməs/', 'enormous', 1);
INSERT INTO `words` VALUES (1526, 'Her disappearance and death would give proof enough of Charles\' guilt.', 'adj. 足够的; adv. 足够地', '/i\'nʌf | ɪ\'nʌf/', 'enough', 1);
INSERT INTO `words` VALUES (1527, 'Day and day I take pains to enquire myself my reason for doing so, in no time will I stoop so low as to beg you sympathy, though I can feel your scoff all the time.', 'v. 询问', '/ɪn\'kwaɪə | ɪn\'kwaɪr/', 'enquire', 1);
INSERT INTO `words` VALUES (1528, 'We are pleased to receive your enquiry.', 'n. 询问', '/ɪn\'kwaɪəri | ɛnˈkwaɪri, ˈɛnkwəri/', 'enquiry', 1);
INSERT INTO `words` VALUES (1529, 'Add fertilizer to enrich the soil.', 'v. 丰富；使富有', '/in\'ritʃ | ɪn\'rɪtʃ/', 'enrich', 1);
INSERT INTO `words` VALUES (1530, '...They enroll in different kinds of classes...', 'v. 注册', '/in\'rəul | inˈrəul | ɪn\'rol/', 'enroll', 1);
INSERT INTO `words` VALUES (1531, 'Class enrollment, where each student has all of the course schedule selections, each student having his own bucket in the CGTT.', 'n. 入学人数', '/in\'rəulmənt | ɪn\'rəʊlmənt | ɪn\'rolmənt/', 'enrollment', 1);
INSERT INTO `words` VALUES (1532, 'facilities to ensure the safety of cyclists', 'v. 确保', '/in\'ʃuə | ɪn\'ʃʊə(r) | ɪn\'ʃʊr/', 'ensure', 1);
INSERT INTO `words` VALUES (1533, 'He entered the election as the clear favourite.', 'v. 走进，进入；参加', '/\'entə | \'ɛntɚ/', 'enter', 1);
INSERT INTO `words` VALUES (1534, 'Mark usually does the cooking when we entertain.', 'v. 使欢乐；招待', '/,entə\'tein | entə\'teɪn | ,ɛntɚ\'ten/', 'entertain', 1);
INSERT INTO `words` VALUES (1535, 'Children’s TV nowadays is much more entertaining.', 'adj. 有趣的，使人愉快的', '/,entə\'teiniŋ | ˌentəˈteɪnɪŋ | ,ɛntɚ\'tenɪŋ/', 'entertaining', 1);
INSERT INTO `words` VALUES (1536, 'The town provides a wide choice of entertainment.', 'n. 娱乐', '/,entə\'teinmənt | ˌentəˈteɪnmənt | \'ɛntɚ\'tenmənt/', 'entertainment', 1);
INSERT INTO `words` VALUES (1537, 'Gillian and Darren greeted the speakers with great enthusiasm.', 'n. 热情，热心，热忱', '/in\'θju:ziæzəm, in\'θu:- | ɪn\'θjuːzɪæz(ə)m; en- | ɪn\'θuzɪæzəm/', 'enthusiasm', 1);
INSERT INTO `words` VALUES (1538, 'an enthusiastic supporter of reform', 'adj. 热情的，热心的', '/in,θju:zi\'æstik | ɪn,θjuːzɪ\'æstɪk; en- | ɪn,θuzɪ\'æstɪk/', 'enthusiastic', 1);
INSERT INTO `words` VALUES (1539, 'It was the worst day in my entire life.', 'adj. 全部的，整个的', '/in\'taiə | ɪn\'taɪə; en- | ɪn\'taɪɚ/', 'entire', 1);
INSERT INTO `words` VALUES (1540, 'If the warranty is limited, the terms may entitle you to a replacement or refund.', 'v. 使具有权利，使具有资格', '/in\'taitl | ɪnˈtaɪtl | ɪn\'taɪtl/', 'entitle', 1);
INSERT INTO `words` VALUES (1541, 'the station entrance', 'n. 入口，门口；进入', '/\'entrəns | \'entr(ə)ns | \'ɛntrəns/', 'entrance', 1);
INSERT INTO `words` VALUES (1542, 'There was no sign of a forced entry.', 'n. 入口处；登记；进入', '/\'entri | ˈɒntreɪ | \'ɛntri/', 'entry', 1);
INSERT INTO `words` VALUES (1543, 'envelopes and stamps', 'n. 信封；封套；封皮', '/\'envələup | \'envələʊp; \'ɒn-/', 'envelope', 1);
INSERT INTO `words` VALUES (1544, 'Some of these chemicals are very damaging to the environment.', 'n. 环境，外界；围绕', '/in\'vaiərənmənt | ɪn\'vaɪrənm(ə)nt; en- | ɪn\'vaɪrənmənt/', 'environment', 1);
INSERT INTO `words` VALUES (1545, 'I really envy you and Ian, you seem so happy together.', 'vt&n. 妒忌；羡慕', '/\'envi | \'envɪ | \'ɛnvi/', 'envy', 1);
INSERT INTO `words` VALUES (1546, 'Over 500 people died during last year’s flu epidemic.', 'adj. 流行性的；传染的; n. 流行病； 传播', '/ˌepɪ\'demɪk | ,ɛpɪ\'dɛmɪk/', 'epidemic', 1);
INSERT INTO `words` VALUES (1547, 'Watch next week’s thrilling episode!', 'n. 一个事件； 插曲， 片段； 连续剧的一集', '/\'epɪsəud | \'ɛpɪsod/', 'episode', 1);
INSERT INTO `words` VALUES (1548, 'Our constitution states that all men are equal.', 'adj. 相等的，平等的', '/\'i:kwəl | \'ikwəl/', 'equal', 1);
INSERT INTO `words` VALUES (1549, '...equality of the sexes.', 'n. 平等', '/i:\'kwɔləti | ɪ\'kwɒlətɪ | ɪ\'kwɑləti/', 'equality', 1);
INSERT INTO `words` VALUES (1550, 'In the equation 2x + 1 = 7, what is x?', 'n. 方程(式)；等式', '/i\'kweiʒən, -ʃən | ɪ\'kweɪʒ(ə)n | ɪ\'kweʒn/', 'equation', 1);
INSERT INTO `words` VALUES (1551, 'They try to equip their vehicles with gadgets to deal with every possible contingency.', 'v. 装备，配备', '/i\'kwip | ɪ\'kwɪp/', 'equip', 1);
INSERT INTO `words` VALUES (1552, 'a shop selling camping equipment', 'n. 装备，设备，配备', '/i\'kwipmənt | ɪ\'kwɪpm(ə)nt | ɪ\'kwɪpmənt/', 'equipment', 1);
INSERT INTO `words` VALUES (1553, '...the equivalence of science and rationality.', 'n. 等值，相等', '/i\'kwivələns | ɪ\'kwɪv(ə)l(ə)ns | ɪ\'kwɪvələns/', 'equivalence', 1);
INSERT INTO `words` VALUES (1554, 'I had no dollars, but offered him an equivalent amount of sterling.', 'adj. 相等的，相当的', '/i\'kwivələnt | ɪ\'kwɪvələnt/', 'equivalent', 1);
INSERT INTO `words` VALUES (1555, 'His death marked the end of an era.', 'n. 纪元，年代', '/\'iərə, \'εərə | \'ɪərə | \'ɪrə/', 'era', 1);
INSERT INTO `words` VALUES (1556, 'an imposing town hall, erected in 1892', 'v. 建造；使竖立', '/i\'rekt | ɪ\'rekt | ɪ\'rɛkt/', 'erect', 1);
INSERT INTO `words` VALUES (1557, 'His economic predictions are based on some erroneous assumptions.', 'adj. 错误的， 不正确的', '/ɪ\'rəuniəs | ɪ\'ronɪəs/', 'erroneous', 1);
INSERT INTO `words` VALUES (1558, 'an error message', 'n. 错误，谬误；差错', '/\'erə | \'ɛrɚ/', 'error', 1);
INSERT INTO `words` VALUES (1559, 'Vents allow any steam to escape if the system overheats.', 'v. 逃跑；逸出; n. 逃跑', '/ɪ\'skeɪp; e- | ɪˈskep/', 'escape', 1);
INSERT INTO `words` VALUES (1560, 'I never liked long walks, especially in winter.', 'adv. 特别，尤其，格外', '/i\'speʃəli | ɪ\'speʃ(ə)lɪ; e- | ɪ\'spɛʃəli/', 'especially', 1);
INSERT INTO `words` VALUES (1561, 'We asked Jason to write an essay about his hometown.', 'n. 散文，文章', '/\'esei, e\'sei | \'eseɪ | \'ɛse/', 'essay', 1);
INSERT INTO `words` VALUES (1562, 'Window locks are fairly cheap and absolutely essential.', 'adj. 本质的，必须的', '/i\'senʃəl | ɪˈsenʃl | ɪ\'sɛnʃl/', 'essential', 1);
INSERT INTO `words` VALUES (1563, 'Ballet is essentially a middle-class interest.', 'adv. 本质上地；必须的', '/i\'senʃəli | ɪ\'senʃ(ə)lɪ | ɪ\'sɛnʃəli/', 'essentially', 1);
INSERT INTO `words` VALUES (1564, 'The city of Boerne was established by German settlers in the 1840s.', 'v. 建立，创办，设立', '/i\'stæbliʃ | ɪˈstæblɪʃ/', 'establish', 1);
INSERT INTO `words` VALUES (1565, '...there have been signs that the medical establishment is trying to sound the alarm...', 'n. 确立，制定；公司；设施', '/i\'stæbliʃmənt | ɪ\'stæblɪʃm(ə)nt | ɪ\'stæblɪʃmənt/', 'establishment', 1);
INSERT INTO `words` VALUES (1566, 'a country estate', 'n. 土地， 住宅区， 地产； 财产， 遗产； 庄园， 种植园', '/ɪ\'steɪt | ɪ\'stet/', 'estate', 1);
INSERT INTO `words` VALUES (1567, 'After that, we could go for esteem and respect.', 'n. 自尊', '/i\'sti:m | is\'ti:m | ɪ\'stim/', 'esteem', 1);
INSERT INTO `words` VALUES (1568, 'Try to estimate how many steps it will take to get to a close object.', 'v. 估计', '/\'estimeit | \'estɪmeɪt | \'ɛstə,met/', 'estimate', 1);
INSERT INTO `words` VALUES (1569, 'eastern Europe', 'n. 欧洲', '/\'juərəp | \'jʊrəp/', 'Europe', 1);
INSERT INTO `words` VALUES (1570, 'European languages', 'adj. 欧洲的; n. 欧洲人', '/,juərə\'pi:ən | jʊərə\'piːən | \'jʊrə\'piən/', 'European', 1);
INSERT INTO `words` VALUES (1571, 'You should be able to evaluate your own work.', 'v. 评价', '/i\'væljueit | ɪˈvæljueɪt | ɪ\'væljʊ\'et/', 'evaluate', 1);
INSERT INTO `words` VALUES (1572, 'We need to carry out a proper evaluation of the new system.', 'n. 评价，评估', '/i,vælju\'eiʃən | ɪˌvæljuˈeɪʃn | ɪ,væljʊ\'eʃən/', 'evaluation', 1);
INSERT INTO `words` VALUES (1573, 'Most of the water had evaporated.', 'v. 使蒸发; v. 蒸发', '/i\'væpəreit | ɪ\'væpəreɪt | ɪ\'væpəret/', 'evaporate', 1);
INSERT INTO `words` VALUES (1574, 'We’re arriving on Christmas Eve.', 'n. 前夜，前夕，前一刻', '/iːv/', 'eve', 1);
INSERT INTO `words` VALUES (1575, 'Most companies have suffered a drop in their profits, even very large companies.', 'adv. 甚至；甚至更，还', '/\'i:vən | \'iːv(ə)n | \'ivən/', 'even', 1);
INSERT INTO `words` VALUES (1576, 'I do most of my studying in the evening.', 'n. 傍晚，黄昏，晚上', '/\'i:vniŋ | \'iːv(ə)nɪŋ | \'ivnɪŋ/', 'evening', 1);
INSERT INTO `words` VALUES (1577, 'one of the most important events in the history of mankind', 'n. 事件，大事；事变', '/i\'vent | ɪ\'vent | ɪ\'vɛnt/', 'event', 1);
INSERT INTO `words` VALUES (1578, 'He eventually escaped and made his way back to England.', 'adv. 终于；最后', '/i\'ventʃuəli | ɪ\'ventʃʊəlɪ | ɪ\'vɛntʃuəli/', 'eventually', 1);
INSERT INTO `words` VALUES (1579, 'Nothing ever seems to upset him.', 'adv. 在任何时候；曾经', '/\'evə | \'ɛvɚ/', 'ever', 1);
INSERT INTO `words` VALUES (1580, 'everlasting fame', 'adj. 永恒的', '/,eveə\'lɑ:stiŋ | ˌevəˈlɑ:stɪŋ | ,ɛvɚ\'læstɪŋ/', 'everlasting', 1);
INSERT INTO `words` VALUES (1581, 'His every utterance will be scrutinized.', 'adj. 每一的；每隔…的', '/\'evri | \'evrɪ | \'ɛvri/', 'every', 1);
INSERT INTO `words` VALUES (1582, '...I did what everybody else thought looked successful...', 'pron. 每人，人人', '/\'evrɪbɒdɪ | \'ɛvrɪbɑdi/', 'everybody', 1);
INSERT INTO `words` VALUES (1583, 'the problems of everyday life', 'adj. 每天的，日常的', '/\'evridei | \'evrɪdeɪ; -\'deɪ | \'ɛvrɪde/', 'everyday', 1);
INSERT INTO `words` VALUES (1584, 'If everyone is ready, I’ll begin.', 'pron. 每人，人人', '/\'evrɪwʌn | \'ɛvrɪwʌn/', 'everyone', 1);
INSERT INTO `words` VALUES (1585, 'Everything was covered in a thick layer of dust.', 'pron. 每件事，事事', '/\'evrɪθɪŋ | \'ɛvrɪ\'θɪŋ/', 'everything', 1);
INSERT INTO `words` VALUES (1586, 'I’ve looked everywhere but I can’t find the map.', 'adv. 到处，处处', '/\'evrihwεə | \'evrɪweə | \'ɛvrɪwɛr/', 'everywhere', 1);
INSERT INTO `words` VALUES (1587, 'Murrow’s evidence was enough to convict Hayes of murder.', 'n. 根据，证据，迹象', '/\'evidəns | \'ɛvɪdəns/', 'evidence', 1);
INSERT INTO `words` VALUES (1588, 'Bob ate his lunch with evident enjoyment.', 'adj. 明显的', '/\'evidənt | \'evɪd(ə)nt | \'ɛvɪdənt/', 'evident', 1);
INSERT INTO `words` VALUES (1589, 'She was evidently a heavy smoker.', 'adv. 明显地， 显然', '/\'evɪdəntli | \'ɛvɪdəntli/', 'evidently', 1);
INSERT INTO `words` VALUES (1590, 'She wanted to protect her children from the evils of the outside world.', 'n. 邪恶，罪恶', '/\'i:vəl | \'i:vl | \'ivl/', 'evil', 1);
INSERT INTO `words` VALUES (1591, 'the theory of evolution', 'n. 演变，进化', '/,i:və\'lu:ʃən, ,ev- | ivəˈluʃən | ˌɛvəˈluʃən; (occas.) ˌ ivəˈluʃən/', 'evolution', 1);
INSERT INTO `words` VALUES (1592, 'the evolutionary development of birds', 'adj. 演变的，进化的', '/,i:və\'lu:ʃənəri | ˌi:vəˈlu:ʃənri | ,ivə\'luʃənɛri/', 'evolutionary', 1);
INSERT INTO `words` VALUES (1593, 'The school has evolved its own style of teaching.', 'v. 使发展', '/i\'vɔlv | ɪ\'vɒlv | ɪ\'vɑlv/', 'evolve', 1);
INSERT INTO `words` VALUES (1594, 'Police are still investigating the exact cause of the accident.', 'adj. 确切的；精确的', '/ɪg\'zækt; eg- | ɪɡ\'zækt/', 'exact', 1);
INSERT INTO `words` VALUES (1595, 'It’s exactly half past five.', 'adv. 确切地；恰恰正是', '/iɡ\'zæktli | ɪg\'zæk(t)lɪ; eg- | ɪɡ\'zæktli/', 'exactly', 1);
INSERT INTO `words` VALUES (1596, 'I couldn’t sleep for three days – I’m not exaggerating.', 'v. 夸张', '/iɡ\'zædʒəreit | ɪg\'zædʒəreɪt | ɪɡ\'zædʒəret/', 'exaggerate', 1);
INSERT INTO `words` VALUES (1597, 'At the end of each level, there’s an exam.', 'n. 考试；检查，细查', '/iɡ\'zæm | ɪg\'zæm; eg- | ɪg\'zæm/', 'exam', 1);
INSERT INTO `words` VALUES (1598, 'The examination results will be announced in September.', 'n. 考试；检查，细查', '/iɡ,zæmi\'neiʃən | ɪg,zæmɪ\'neɪʃ(ə)n; eg- | ɪg\'zæmə\'neʃən/', 'examination', 1);
INSERT INTO `words` VALUES (1599, 'A team of divers was sent down to examine the wreck.', 'v. 检查，仔细观察', '/iɡ\'zæmin | ɪg\'zæmɪn; eg- | ɪg\'zæmɪn/', 'examine', 1);
INSERT INTO `words` VALUES (1600, 'Many countries, for example Mexico and Japan, have a lot of earthquakes.', 'n. 例子，实例；模范', '/iɡ\'zɑ:mpl | ɪg\'zɑːmp(ə)l; eg- | ɪg\'zæmpl/', 'example', 1);
INSERT INTO `words` VALUES (1601, 'Working hours must not exceed 42 hours a week.', 'v. 超过，胜过；超出', '/ik\'si:d | ɪk\'siːd; ek- | ɪk\'sid/', 'exceed', 1);
INSERT INTO `words` VALUES (1602, 'Thank you. You’ve been exceedingly kind.', 'adv. 极端地，非常', '/ik\'si:diŋli | ɪk\'siːdɪŋlɪ; ek- | ɪk\'sidɪŋli/', 'exceedingly', 1);
INSERT INTO `words` VALUES (1603, 'an excellent suggestion', 'adj. 卓越的，杰出的，极好的', '/\'eksələnt | \'ɛksələnt/', 'excellent', 1);
INSERT INTO `words` VALUES (1604, 'They were all there except me.', 'prep. 除…之外', '/ik\'sept | ɪk\'sept; ek- | ɪk\'sɛpt/', 'except', 1);
INSERT INTO `words` VALUES (1605, 'It’s been cold, but today’s an exception.', 'n. 例外', '/ik\'sepʃən | ɪkˈsepʃn | ɪk\'sɛpʃən/', 'exception', 1);
INSERT INTO `words` VALUES (1606, 'After you apply the oil, wait 20 minutes before wiping off any excess.', 'n. 过量，过度', '/ik\'ses, \'ek-, \'ekses, ik\'s- | ɪkˈses | \'ɛk\'sɛs/', 'excess', 1);
INSERT INTO `words` VALUES (1607, 'his excessive drinking', 'adj. 过度的', '/ik\'sesiv | ɪkˈsesɪv | ɪkˈsɛsɪv/', 'excessive', 1);
INSERT INTO `words` VALUES (1608, 'Four of my cassettes for your Madonna CD is a fair exchange.', 'n & v. 交换，交流', '/iks\'tʃeindʒ | ɪks\'tʃeɪndʒ | ɪks\'tʃendʒ/', 'exchange', 1);
INSERT INTO `words` VALUES (1609, 'His playing is technically brilliant, but it doesn’t excite me.', 'v. 使激动；引起', '/ik\'sait | ɪk\'saɪt; ek- | ɪk\'saɪt/', 'excite', 1);
INSERT INTO `words` VALUES (1610, 'We were both new to the excitements of life in the big city.', 'n. 刺激， 激动， 兴奋； 令人兴奋的事， 刺激的因素', '/ɪk\'saɪtmənt/', 'excitement', 1);
INSERT INTO `words` VALUES (1611, 'an exciting discovery', 'adj. 令人兴奋的', '/ik\'saitiŋ | ɪk\'saɪtɪŋ; ek- | ɪk\'saɪtɪŋ/', 'exciting', 1);
INSERT INTO `words` VALUES (1612, '‘No!’ she exclaimed in shock.', 'v. 呼喊；惊叫', '/ik\'skleim | ɪk\'skleɪm; ek- | ɪk\'sklem/', 'exclaim', 1);
INSERT INTO `words` VALUES (1613, 'a special diet that excludes dairy products', 'v. 排除，不包括', '/iks\'klu:d | ɪk\'sklu:d | ɪk\'sklʊd/', 'exclude', 1);
INSERT INTO `words` VALUES (1614, 'Bel Air is an exclusive suburb of Los Angeles.', 'adj. 奢华的，高级的；独有的，独享的；排斥的，排他的；不包括…的，不把…计算在内的; n. 独家新闻', '/ɪk\'skluːsɪv | ɪk\'sklusɪv/', 'exclusive', 1);
INSERT INTO `words` VALUES (1615, 'These are not involved as exclusively as ministers in \"soul-work,\" but they certainly cultivate the inner life more than the third group.', 'adv. 专门地', '/ik\'sklu:sivli | ɪk\'skluːsɪvlɪ | ɪk\'sklʊsɪvli/', 'exclusively', 1);
INSERT INTO `words` VALUES (1616, 'a shopping excursion', 'n. 远足；短途旅行', '/ɪk\'skɜːʃ(ə)n; ek- | ɪk\'skɝʒn/', 'excursion', 1);
INSERT INTO `words` VALUES (1617, 'I’ll excuse you this time, but don’t be late again.', 'v. 原谅；免除; n. 借口', '/ik\'skju:z, ik\'skju:s | ɪk\'skjuːz; ek- | ɪk\'skjʊs/', 'excuse', 1);
INSERT INTO `words` VALUES (1618, '13 people were summarily executed (= killed without any trial or legal process ) by the guerrillas.', 'v. 将…处死；实施', '/\'eksikju:t | \'eksɪkjuːt | \'ɛksɪkjut/', 'execute', 1);
INSERT INTO `words` VALUES (1619, 'a commission with executive powers', 'adj. 执行的; n. 执行者', '/ɪg\'zekjʊtɪv; eg- | ɪɡ\'zɛkjətɪv/', 'executive', 1);
INSERT INTO `words` VALUES (1620, 'Try to fit some regular exercise into your daily routine.', 'n. 锻炼，训练; v. 练习', '/\'eksəsaiz | \'eksəsaɪz | \'ɛksɚsaɪz/', 'exercise', 1);
INSERT INTO `words` VALUES (1621, 'They exerted considerable influence within the school.', 'v. 尽(力)，运用', '/iɡ\'zə:t | ɪg\'zɜːt; eg- | ɪɡ\'zɝt/', 'exert', 1);
INSERT INTO `words` VALUES (1622, 'A full day’s teaching exhausts me.', 'v. 使筋疲力尽', '/iɡ\'zɔ:st | ɪgˈzɔ:st | ɪɡ\'zɔst/', 'exhaust', 1);
INSERT INTO `words` VALUES (1623, 'Her paintings have been exhibited all over the world.', 'v. 显示；陈列，展览', '/iɡ\'zibit | ɪg\'zɪbɪt; eg- | ɪɡ\'zɪbɪt/', 'exhibit', 1);
INSERT INTO `words` VALUES (1624, '...an exhibition of expressionist art.', 'n. 展览', '/,eksi\'biʃən | ˌeksɪˈbɪʃn | ,ɛksɪ\'bɪʃən/', 'exhibition', 1);
INSERT INTO `words` VALUES (1625, 'political exiles', 'n. 流放，放逐', '/\'eɡzail, \'eksail | \'eksaɪl | \'ɛksaɪl/', 'exile', 1);
INSERT INTO `words` VALUES (1626, 'The custom of arranged marriages still exists in many countries.', 'v. 存在；生存，生活', '/iɡ\'zist | ɪg\'zɪst; eg- | ɪɡ\'zɪst/', 'exist', 1);
INSERT INTO `words` VALUES (1627, 'Scientists have many theories about how the universe first came into existence (= started to exist ).', 'n. 存在，实在；生存', '/iɡ\'zistəns | ɪg\'zɪst(ə)ns; eg- | ɪɡ\'zɪstəns/', 'existence', 1);
INSERT INTO `words` VALUES (1628, 'We made for the nearest exit.', 'n. 出口；退场; v. 退出', '/\'eksit, \'eɡ zit | \'eksɪt; \'egzɪt | \'ɛɡzɪt/', 'exit', 1);
INSERT INTO `words` VALUES (1629, 'Water expands as it freezes.', 'v. 扩大', '/ik\'spænd | ɪk\'spænd/', 'expand', 1);
INSERT INTO `words` VALUES (1630, 'The industry underwent a period of rapid expansion.', 'n. 扩大，扩充；扩张', '/ik\'spænʃən | ɪk\'spænʃ(ə)n; ek- | ɪk\'spænʃən/', 'expansion', 1);
INSERT INTO `words` VALUES (1631, 'He will be hard to beat. I fully expect (= am completely sure about ) that and I’m ready.', 'v. 预料，预期；等待', '/ik\'spekt | ɪk\'spekt; ek- | ɪk\'spɛkt/', 'expect', 1);
INSERT INTO `words` VALUES (1632, 'Having raised expectations (= made people more hopeful ), he went on to help only a few people.', 'n. 期望', '/,ekspek\'teiʃən | ˌekspekˈteɪʃn | ,ɛkspɛk\'teʃən/', 'expectation', 1);
INSERT INTO `words` VALUES (1633, 'He borrowed £150,000 and used the money for legal expenses.', 'n. 花费，消费；费用', '/ik\'spens | ɪk\'spens; ek- | ɪk\'spɛns/', 'expense', 1);
INSERT INTO `words` VALUES (1634, 'the most expensive restaurant in town', 'adj. 昂贵的，花钱多的', '/ik\'spensiv | ɪk\'spensɪv; ek- | ɪk\'spɛnsɪv/', 'expensive', 1);
INSERT INTO `words` VALUES (1635, 'The advice in the booklet reflects the practical experience we have gained (= experience gained by actually doing something, rather than knowledge from books etc ).', 'n. 经验，感受；经历', '/ik\'spiəriəns | ɪk\'spɪərɪəns; ek- | ɪk\'spɪrɪəns/', 'experience', 1);
INSERT INTO `words` VALUES (1636, 'The astronauts are conducting a series of experiments to learn more about how the body adapts to weightlessness.', 'n. 实验；试验', '/ik\'speriment, ek\'s- | ɪk\'sperɪm(ə)nt; ek- | ɪk\'sperɪmənt/', 'experiment', 1);
INSERT INTO `words` VALUES (1637, 'experimental animals', 'adj. 实验的，试验的', '/ek,speri\'mentəl, ek\'s- | ɪk,sperɪ\'ment(ə)l; ek- | ɛk\'spɛrɪ\'mɛntəl/', 'experimental', 1);
INSERT INTO `words` VALUES (1638, 'He cast his expert eye on the gardener’s work.', 'adj. 熟练的，内行的', '/\'ekspə:t, ek\'spə:t | \'ekspɜːt | \'ɛkspɝt; (for adj., also) ɛksˈpɝt ; ɪkˈspɝt/', 'expert', 1);
INSERT INTO `words` VALUES (1639, 'He carefully explained the procedure.', 'v. 解释；为…辩解', '/ik\'splein | ɪk\'spleɪn | ɪk\'splen/', 'explain', 1);
INSERT INTO `words` VALUES (1640, 'She told the court she would give a full explanation of the prosecution\'s decision on Monday.', 'n. 解释，说明；辩解', '/,eksplə\'neiʃən | eksplə\'neɪʃ(ə)n | ,ɛksplə\'neʃən/', 'explanation', 1);
INSERT INTO `words` VALUES (1641, 'You have to grant us control explicitly.', 'adv. 直接地，明确地', '/ik\'splisitli | ɪk\'splɪsɪtli/', 'explicitly', 1);
INSERT INTO `words` VALUES (1642, 'The device was thrown at an army patrol but failed to explode.', 'v. 使爆炸; v. 爆炸', '/ik\'spləud | ɪk\'spləʊd; ek- | ɪk\'splod/', 'explode', 1);
INSERT INTO `words` VALUES (1643, 'the urgent need to exploit the resources of the Irish Sea', 'v. 开采', '/\'eksplɔit, ik\'s- | ɪk\'splɔɪt/', 'exploit', 1);
INSERT INTO `words` VALUES (1644, 'Management need to explore ways of improving office security.', 'v. 探索', '/ik\'splɔ: | ɪk\'splɔ:(r) | ɪk\'splɔr/', 'explore', 1);
INSERT INTO `words` VALUES (1645, 'We heard a loud explosion.', 'n. 爆炸', '/ik\'spləuʒən | ɪkˈspləʊʒn | ɪk\'sploʒən/', 'explosion', 1);
INSERT INTO `words` VALUES (1646, '...one-hundred-and-fifty pounds of Semtex explosive.', 'n. 炸药; adj. 爆炸的', '/ik\'spləusiv | ɪk\'spləʊsɪv; ek- | ɪk\'splosɪv; ɪk\'splozɪv/', 'explosive', 1);
INSERT INTO `words` VALUES (1647, 'Italian food has been exported all over the world.', 'v. 输出，出口；运走', '/ik\'spɔ:t, \'eks-, \'ekspɔ:t | ˈekspɔːt；ɪkˈ- | ˈekspɔːrt；ɪkˈ-/', 'export', 1);
INSERT INTO `words` VALUES (1648, 'He lifted his T-shirt to expose a jagged scar across his chest.', 'v. 暴露', '/ik\'spəuz | ɪk\'spoz；ek-/', 'expose', 1);
INSERT INTO `words` VALUES (1649, 'Exposure to lead is known to damage the brains of young children.', 'n. 暴露；揭露', '/ik\'spəuʒə | ɪk\'spəʊʒə | ɪk\'spoʒɚ/', 'exposure', 1);
INSERT INTO `words` VALUES (1650, 'Parents have expressed their concerns about their children’s safety.', 'v. 表示; n. 快车，快递', '/ik\'spres | ɪk\'spres; ek- | ɪk\'sprɛs/', 'express', 1);
INSERT INTO `words` VALUES (1651, 'Student leaders are demanding greater freedom of expression (= the right to say what you think without being punished ).', 'n. 词句；表达；表情', '/英 [ɪk\'spreʃn] 美 [ɪkˈsprɛʃən | ɪkˈspreʃn | ɪk\'sprɛʃən/', 'expression', 1);
INSERT INTO `words` VALUES (1652, 'Moreover, it offers the expressiveness which helps to “simplify complex tasks”.', 'n. 表达', '/ik\'spresivnis/', 'expressiveness', 1);
INSERT INTO `words` VALUES (1653, 'Management have agreed to extend the deadline.', 'v. 延长；扩大；致', '/ik\'stend | ɪk\'stend; ek- | ɪk\'stɛnd/', 'extend', 1);
INSERT INTO `words` VALUES (1654, 'a loft extension', 'n. 分机', '/ik\'stenʃən | ɪk\'stenʃn | ɪk\'stɛnʃən/', 'extension', 1);
INSERT INTO `words` VALUES (1655, 'The house stands in extensive grounds.', 'adj. 广阔的；广泛的', '/ik\'stensiv | ɪk\'stensɪv; ek- | ɪk\'stɛnsɪv/', 'extensive', 1);
INSERT INTO `words` VALUES (1656, 'The new rocket was extensively tested and debugged by the army.', 'adv. 广泛地', '/ik\'stensivli | ɪk\'stensɪvlɪ/', 'extensively', 1);
INSERT INTO `words` VALUES (1657, '...To what extent are Americans really willing to endure the environmental impacts of domestic energy production in order to cut back imports...', 'n. 广度；范围；程度', '/ɪk\'stent | ɪk\'stɛnt/', 'extent', 1);
INSERT INTO `words` VALUES (1658, 'The exterior walls need a new coat of paint.', 'adj. 外部的；对外的', '/ik\'stiəriə | ɪk\'stɪərɪə; ek- | ɪk\'stɪrɪɚ/', 'exterior', 1);
INSERT INTO `words` VALUES (1659, 'the external appearance of the building', 'adj. 外部的，外面的', '/ik\'stə:nəl | ɪk\'stɜːn(ə)l; ek- | ɪk\'stɝnl/', 'external', 1);
INSERT INTO `words` VALUES (1660, 'Could you get an extra loaf of bread?', 'adj. 额外的; adv. 特别地', '/\'ekstrə | \'ɛkstrə/', 'extra', 1);
INSERT INTO `words` VALUES (1661, 'Each child had participated in extracurricular activities at school.', 'adj. 课外的', '/,ekstrəkə\'rikjulə | ekstrəkə\'rɪkjʊlə | ,ɛkstrəkə\'rɪkjəlɚ/', 'extracurricular', 1);
INSERT INTO `words` VALUES (1662, 'a woman of extraordinary beauty', 'adj. 非凡的', '/ik\'strɔ:dənəri, ,ekstrə\'ɔ:di- | ɪkˈstrɔːdnri | ɛkˈstrɔrdənˌɛri; ɪkˈstrɔrdəˌnɛri; ˌɛkstrəˈɔrdəˌnɛri/', 'extraordinary', 1);
INSERT INTO `words` VALUES (1663, 'Extreme poverty still exists in many rural areas.', 'adj. 极度的；尽头的', '/ik\'stri:m | ɪk\'striːm; ek- | ɪk\'strim/', 'extreme', 1);
INSERT INTO `words` VALUES (1664, 'Earthquakes are extremely difficult to predict.', 'adv. 极端，极其，非常', '/ik\'stri:mli | ɪk\'striːmlɪ; ek- | ɪk\'strimli/', 'extremely', 1);
INSERT INTO `words` VALUES (1665, 'He’s got beautiful eyes.', 'n. 眼睛；眼力；鉴赏力', '/ai | aɪ/', 'eye', 1);
INSERT INTO `words` VALUES (1666, 'He had a problem with his eyesight.', 'n. 视力，目力', '/\'aisait | \'aɪsaɪt/', 'eyesight', 1);
INSERT INTO `words` VALUES (1667, 'the fable of the fox and the crow', 'n. 寓言；虚构的故事', '/\'feibl | \'feɪb(ə)l | \'febl/', 'fable', 1);
INSERT INTO `words` VALUES (1668, 'our new range of fabrics and wallpapers', 'n. 织物，纺织品；结构', '/\'fæbrik | \'fæbrɪk/', 'fabric', 1);
INSERT INTO `words` VALUES (1669, 'She had a beautiful face.', 'n. 脸；表面；外表', '/feis | feɪs | fes/', 'face', 1);
INSERT INTO `words` VALUES (1670, 'The new airport will facilitate the development of tourism.', 'v. 使便利，促进', '/fə\'siliteit | fəˈsɪlɪteɪt | fə\'sɪlə\'tet/', 'facilitate', 1);
INSERT INTO `words` VALUES (1671, 'What recreational facilities are now available?', 'n. 设施', '/fə\'siliti | fə\'sɪləti/', 'facility', 1);
INSERT INTO `words` VALUES (1672, 'Our decision to build the museum in Hartlepool was influenced by the fact that there were no national museums in the North East.', 'n. 事实；实际，实情', '/fækt/', 'fact', 1);
INSERT INTO `words` VALUES (1673, 'The rise in crime is mainly due to social and economic factors.', 'n. 因素；因子，系数', '/\'fæktə | \'fæktɚ/', 'factor', 1);
INSERT INTO `words` VALUES (1674, 'a car factory', 'n. 工厂，制造厂', '/\'fæktəri | \'fækt(ə)rɪ | \'fæktri/', 'factory', 1);
INSERT INTO `words` VALUES (1675, 'the Engineering Faculty', 'n. 才能，能力；系，科', '/\'fækəlti | \'fæk(ə)ltɪ | \'fæklti/', 'faculty', 1);
INSERT INTO `words` VALUES (1676, 'Hopes of a peace settlement are beginning to fade.', 'v. 逐渐消失', '/feid, fad | feɪd | fed/', 'fade', 1);
INSERT INTO `words` VALUES (1677, '72˚ Fahrenheit (= 72 degrees on the Fahrenheit scale )', 'n. 华氏温度计', '/\'færəhait | \'fær(ə)nhaɪt; \'fɑː- | \'færən\'haɪt/', 'Fahrenheit', 1);
INSERT INTO `words` VALUES (1678, 'It looks likely that the peace talks will fail.', 'v. 失败；失灵；不能', '/feil | feɪl | fel/', 'fail', 1);
INSERT INTO `words` VALUES (1679, 'Successful people often aren’t very good at dealing with failure.', 'n. 失败；失败的人', '/\'feiljə | \'feɪljə | \'feljɚ/', 'failure', 1);
INSERT INTO `words` VALUES (1680, 'a faint hope that they might be alive', 'adj. 微弱的；虚弱的', '/\'feint | feɪnt | fent/', 'faint', 1);
INSERT INTO `words` VALUES (1681, 'a horse fair', 'n. 集市', '/fεə | feə(r) | fɛr/', 'fair', 1);
INSERT INTO `words` VALUES (1682, 'The house had a fairly large garden.', 'adv. 相当；公平地', '/\'fεəli | \'feəlɪ | \'fɛrli/', 'fairly', 1);
INSERT INTO `words` VALUES (1683, 'In his dream, he became a fairy.', 'n. 小精灵， 小仙子', '/\'feəri | \'fɛri/', 'fairy', 1);
INSERT INTO `words` VALUES (1684, 'People have lost faith in the government.', 'n. 信任', '/feiθ | feɪθ | feθ/', 'faith', 1);
INSERT INTO `words` VALUES (1685, 'a faithful friend', 'adj. 忠诚的；如实的', '/\'feiθful | \'feɪθfʊl; -f(ə)l | \'feθfəl/', 'faithful', 1);
INSERT INTO `words` VALUES (1686, 'The tree was about to fall.', 'v. 落下；跌倒；陷落', '/fɔ:l | fɔːl | fɔl/', 'fall', 1);
INSERT INTO `words` VALUES (1687, '...a set of false teeth.', 'adj. 不真实的；伪造的', '/fɔ:ls | fɔːls; fɒls | fɔls/', 'FALSE', 1);
INSERT INTO `words` VALUES (1688, 'He claims he is not really interested in fame.', 'n. 名声，名望', '/feim | feɪm | fem/', 'fame', 1);
INSERT INTO `words` VALUES (1689, 'a familiar tune', 'adj. 熟悉的', '/fə\'miljə | fəˈmɪliə(r) | fə\'mɪljɚ/', 'familiar', 1);
INSERT INTO `words` VALUES (1690, 'Do you know the family next door?', 'n. 家，家庭；家族', '/\'fæmɪlɪ; -m(ə)l- | \'fæməli/', 'family', 1);
INSERT INTO `words` VALUES (1691, 'the great potato famine in Ireland', 'n. 饥荒；严重的缺乏', '/\'fæmin | \'fæmɪn/', 'famine', 1);
INSERT INTO `words` VALUES (1692, 'a famous actor', 'adj. 著名的，出名的', '/\'feiməs | \'feɪməs | \'feməs/', 'famous', 1);
INSERT INTO `words` VALUES (1693, 'Groups of football fans began heading towards the ground.', 'n. (运动等)狂热爱好者', '/fæn/', 'fan', 1);
INSERT INTO `words` VALUES (1694, 'Harry took me to a fancy restaurant for our anniversary.', 'adj. 华丽的，别致的', '/\'fænsɪ | \'fænsi/', 'fancy', 1);
INSERT INTO `words` VALUES (1695, 'I fantasized about writing music.', 'v. 想象，幻想', '/\'fæntəsaiz | \'fæntəsaɪz/', 'fantasize', 1);
INSERT INTO `words` VALUES (1696, 'You look fantastic!', 'adj. 极好的， 极出色的， 了不起的； 极大的； 难以相信的； 异想天开的， 不实际的； 奇异的， 古怪的', '/fæn\'tæstɪk/', 'fantastic', 1);
INSERT INTO `words` VALUES (1697, 'I used to have fantasies about living in Paris with an artist.', 'n. 想象， 幻想； 想象的产物', '/\'fæntəsi/', 'fantasy', 1);
INSERT INTO `words` VALUES (1698, 'We can walk to my house from here. It isn’t far.', 'adj. 远的; adv. 远，遥远', '/fɑ: | fɑː | fɑr/', 'far', 1);
INSERT INTO `words` VALUES (1699, 'He could barely afford the fare.', 'n. 车费，船费，票价', '/fεə | feə | fɛr/', 'fare', 1);
INSERT INTO `words` VALUES (1700, '40 of her colleagues gathered for her farewell presentation.', 'int. 再会; n. 告别', '/\'fεə\'wel | feə\'wel | ,fɛr\'wɛl/', 'farewell', 1);
INSERT INTO `words` VALUES (1701, 'a 300-hectare farm', 'n. 农场，农庄；饲养场', '/fɑ:m | fɑːm | fɑrm/', 'farm', 1);
INSERT INTO `words` VALUES (1702, NULL, 'n. 农民，农夫；农场主', '/\'fɑ:mə | \'fɑːmə | \'fɑmɚ/', 'farmer', 1);
INSERT INTO `words` VALUES (1703, 'We decided not to go any farther.', 'adv. 更远地; adj. 更远的', '/\'fɑ:ðə | \'fɑːðə | \'fɑrðɚ/', 'farther', 1);
INSERT INTO `words` VALUES (1704, 'The idea of travelling through time fascinates me.', 'v. 强烈地吸引，迷住', '/\'fæsineit | \'fæsə\'net/', 'fascinate', 1);
INSERT INTO `words` VALUES (1705, 'a fascinating book', 'adj. 迷人的， 有极大吸引力的', '/\'fæsɪneɪtɪŋ | \'fæsɪnetɪŋ/', 'fascinating', 1);
INSERT INTO `words` VALUES (1706, 'The fascination lay in the mystery of what was inside the box.', 'n. 魅力；入迷', '/fæsi\'neiʃən | ,fæsɪ\'neɪʃ(ə)n | ,fæsɪ\'neʃən/', 'fascination', 1);
INSERT INTO `words` VALUES (1707, 'Please leave the building in an orderly fashion.', 'n. 样子，方式；风尚', '/\'fæʃən | \'fæʃ(ə)n/', 'fashion', 1);
INSERT INTO `words` VALUES (1708, 'Strong colours are very fashionable at the moment.', 'adj. 流行的，时髦的', '/\'fæʃənəbl | \'fæʃ(ə)nəb(ə)l | \'fæʃnəbl/', 'fashionable', 1);
INSERT INTO `words` VALUES (1709, 'a fast car', 'adj. 快的；偏快的; adv. 快', '/fɑ:st, fæst | fɑːst | fæst/', 'fast', 1);
INSERT INTO `words` VALUES (1710, 'Make sure all the windows are securely fastened before you leave.', 'v. 扎牢，扣住', '/\'fɑ:sən, \'fæ- | \'fɑːs(ə)n | \'fæsən/', 'fasten', 1);
INSERT INTO `words` VALUES (1711, 'potentially fatal diseases', 'adj. 致命的，攸关的', '/\'feitl | \'feɪtl | \'fetl/', 'fatal', 1);
INSERT INTO `words` VALUES (1712, 'I wouldn’t wish such a fate on my worst enemy.', 'n. 命运', '/\'feit | feɪt | fet/', 'fate', 1);
INSERT INTO `words` VALUES (1713, 'Ask your father to help you.', 'n. 父亲；神父；创始人', '/\'fɑ:ðə | \'fɑːðə | \'fɑðɚ/', 'father', 1);
INSERT INTO `words` VALUES (1714, '{\"COLLOINEXA\":[\"metal fatigue\"]}', 'n. 疲劳，疲乏', '/fə\'ti:ɡ | fə\'tig/', 'fatigue', 1);
INSERT INTO `words` VALUES (1715, 'His worst fault is his arrogance.', 'n. 缺点；过失；故障', '/fɔ:lt | fɔːlt; fɒlt | fɔlt/', 'fault', 1);
INSERT INTO `words` VALUES (1716, 'Customers may ask for a refund if the goods are faulty.', 'adj. 有错误的，有缺点的', '/\'fɔ:lti | \'fɔːltɪ; \'fɒltɪ | \'fɔlti/', 'faulty', 1);
INSERT INTO `words` VALUES (1717, '...Some people are still in favor of printed books because of the sense of touch they can provide...', 'v. 偏好, 赞同', '/\'feivə | \'feɪvə | \'fevɚ/', 'favor', 1);
INSERT INTO `words` VALUES (1718, '...America has a social environment that is particularly favorable to innovation...', 'adj. 赞同的', '/\'feivərəbl | \'feɪvərəbl | \'fevərəbl/', 'favorable', 1);
INSERT INTO `words` VALUES (1719, 'Could you do me a favour and tell Kelly I can’t make it?', 'n. 好感；赞同；恩惠', '/\'feivə | \'feɪvə | ˈfevɚ/', 'favour', 1);
INSERT INTO `words` VALUES (1720, 'favourable film reviews', 'adj. 有利的；赞成的', '/\'feivərəbl | \'feɪv(ə)rəb(ə)l/', 'favourable', 1);
