INSERT INTO `words` VALUES (2225, 'I’m not a hundred percent sure where she lives.', 'num. 百，百个; n. 许多', '/\'hʌndrəd/', 'hundred', 1);
INSERT INTO `words` VALUES (2226, 'Try to satisfy your hunger by eating some fruit.', 'n. 饿，饥饿；渴望', '/\'hʌŋɡə | \'hʌŋgə | \'hʌŋɡɚ/', 'hunger', 1);
INSERT INTO `words` VALUES (2227, 'I was cold, tired, and hungry.', 'adj. 饥饿的；渴望的', '/\'hʌŋɡri | \'hʌŋgrɪ/', 'hungry', 1);
INSERT INTO `words` VALUES (2228, 'The couple had helped in the hunt for the toddlers.', 'n. 打猎；搜寻; v. 追猎', '/hʌnt/', 'hunt', 1);
INSERT INTO `words` VALUES (2229, 'If we hurry, we’ll get there in time.', 'v. 赶紧; v. 催促', '/\'hʌrɪ | \'hɝrɪ/', 'hurry', 1);
