INSERT INTO `words` VALUES (2239, 'Do you have any identification?', 'n. 鉴定，识别；认同；身份证明', '/ai,dentifi\'keiʃən | aɪ,dentɪfɪ\'keɪʃ(ə)n | aɪˌdentɪfɪ\'keʃn/', 'identification', 1);
INSERT INTO `words` VALUES (2240, 'He was too far away to be able to identify faces.', 'v. 认出，识别；视为', '/aɪ\'dentifai | aɪ\'dɛntɪfaɪ/', 'identify', 1);
INSERT INTO `words` VALUES (2241, 'The identity of the killer is still unknown.', 'n. 身份', '/ai\'dentəti | aɪ\'dentɪtɪ | aɪ\'dɛntəti/', 'identity', 1);
INSERT INTO `words` VALUES (2242, 'the new musical idiom', 'n. 习语，成语', '/\'idiəm | \'ɪdɪəm/', 'idiom', 1);
INSERT INTO `words` VALUES (2243, 'I cannot afford to leave the land lying idle.', 'adj. 空闲的；懒散的', '/\'aidl | \'aɪd(ə)l | \'aɪdl/', 'idle', 1);
INSERT INTO `words` VALUES (2244, 'We’ll stay at home if it rains.', 'conj. 假如，如果', '/ɪf/', 'if', 1);
INSERT INTO `words` VALUES (2245, 'Excuse my ignorance, but how does it actually work?', 'n. 无知，愚昧', '/\'iɡnərəns | \'ɪɡnərəns/', 'ignorance', 1);
INSERT INTO `words` VALUES (2246, 'an ignorant and uneducated man', 'adj. 无知的', '/\'iɡnərənt | \'ɪgn(ə)r(ə)nt | \'ɪɡnərənt/', 'ignorant', 1);
INSERT INTO `words` VALUES (2247, 'The phone rang, but she ignored it.', 'v. 忽视，不顾', '/iɡ\'nɔ: | ɪɡ\'nɔ:(r) | ɪɡ\'nɔr/', 'ignore', 1);
INSERT INTO `words` VALUES (2248, 'Bridget can’t come – she’s ill.', 'adj. 有病的；坏的; adv. 坏', '/il | ɪl/', 'ill', 1);
INSERT INTO `words` VALUES (2249, 'illegal drugs', 'adj. 非法的', '/ɪ\'li:ɡl | ɪ\'ligl/', 'illegal', 1);
INSERT INTO `words` VALUES (2250, 'She had all the normal childhood illnesses.', 'n. 病，疾病', '/\'ilnis | ˈɪlnəs | \'ɪlnəs/', 'illness', 1);
INSERT INTO `words` VALUES (2251, 'Let me give an example to illustrate the point.', 'v. 说明,阐明', '/\'iləstreit | \'ɪləstreɪt | \'ɪləstret/', 'illustrate', 1);
INSERT INTO `words` VALUES (2252, 'The book contains 62 pages of illustrations.', 'n. 说明，图解；例证', '/,ilə\'streiʃən | ɪlə\'streɪʃ(ə)n | ,ɪlə\'streʃən/', 'illustration', 1);
INSERT INTO `words` VALUES (2253, 'He had the clearest image in his mind of his mother and father.', 'n. 形象，声誉，印象', '/\'imidʒ | \'ɪmɪdʒ/', 'image', 1);
INSERT INTO `words` VALUES (2254, 'As she listened, she played an imaginary piano on her knees.', 'adj. 虚构的，想象的', '/i\'mædʒinəri | ɪ\'mædʒɪn(ə)rɪ | ɪ\'mædʒɪnɛri/', 'imaginary', 1);
INSERT INTO `words` VALUES (2255, 'a storyteller with an incredible imagination', 'n. 想象；想象力；空想', '/i,mædʒi\'neiʃən | ɪ,mædʒɪ\'neɪʃ(ə)n | ɪ,mædʒɪ\'neʃən/', 'imagination', 1);
INSERT INTO `words` VALUES (2256, 'Perhaps she’d never really been there at all – perhaps she’d just imagined it.', 'v. 想象，设想；料想', '/i\'mædʒin | ɪ\'mædʒɪn/', 'imagine', 1);
INSERT INTO `words` VALUES (2257, 'She was a splendid mimic and loved to imitate Winston Churchill.', 'v. 模仿', '/\'imiteit | \'ɪmɪteɪt | \'ɪmɪtet/', 'imitate', 1);
INSERT INTO `words` VALUES (2258, 'The refugee problem has now reached immeasurable proportions.', 'adj. 无法估量的', '/i\'meʒərəbl | ɪ\'meʒ(ə)rəb(ə)l | ɪ\'mɛʒərəbl/', 'immeasurable', 1);
