INSERT INTO `words` VALUES (2260, 'Those most immediately involved in the disaster will be given support.', 'adv. 立即；直接地', '/i\'mi:diətli | ɪ\'miːdɪətlɪ | ɪ\'midɪətli/', 'immediately', 1);
INSERT INTO `words` VALUES (2261, 'People who travel by rail still read an immense amount.', 'adj. 巨大的；极好的', '/i\'mens | ɪ\'mens | ɪ\'mɛns/', 'immense', 1);
INSERT INTO `words` VALUES (2262, 'an illegal immigrant', 'n. 移民; adj. 移民的', '/\'imiɡrənt | \'ɪmɪgr(ə)nt | \'ɪmɪɡrənt/', 'immigrant', 1);
INSERT INTO `words` VALUES (2263, 'She could see a figure sitting immobile, facing the sea.', 'adj. 稳定的，不变的', '/i\'məubail, -bi:l | ɪ\'məʊbaɪl | ɪ\'mobl/', 'immobile', 1);
