INSERT INTO `words` VALUES (2266, NULL, 'n. 非永久性', '/im\'pə:mənəns,-nənsi | im\'pə:mənənsi/', 'impermanency', 1);
INSERT INTO `words` VALUES (2267, 'single-storey structures, built from cheap and impermanent materials', 'adj. 非永久（性）的；不持久的，暂时的', '/im\'pə:mənənt | ɪm\'pɝmənənt/', 'impermanent', 1);
INSERT INTO `words` VALUES (2268, 'The government promised to implement a new system to control financial loan institutions.', 'v. 实施，执行', '/\'implimənt, \'impliment | \'ɪmplɪmənt | \'ɪmplɪmɛnt/', 'implement', 1);
INSERT INTO `words` VALUES (2269, 'They do, however, greatly affect the implementation of those patterns.', 'n. 实现，履行', '/,implimen\'teiʃən | ɪmplɪmen\'teɪʃ(ə)n/', 'implementation', 1);
INSERT INTO `words` VALUES (2270, 'They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.', 'n. 含义，暗示', '/ˌɪmplɪˈkeɪʃn | \'ɪmplɪ\'keʃən/', 'implication', 1);
INSERT INTO `words` VALUES (2271, 'an implied threat', 'v. 意味；暗示', '/im\'plai | ɪm\'plai/', 'imply', 1);
INSERT INTO `words` VALUES (2272, '...The most import advantage of the school meeting is that it shows the children that the school is really their’s...', 'n & v. 进口', '/im\'pɔ:t, \'impɔ:t | ɪm\'pɔːt | \'ɪmpɔt/', 'import', 1);
INSERT INTO `words` VALUES (2273, 'He was full of his own importance (= he behaved in an annoying way which showed that he thought he was very important ).', 'n. 重要；重要性', '/im\'pɔ:təns | ɪm\'pɔːt(ə)ns | ɪm\'pɔrtns/', 'importance', 1);
INSERT INTO `words` VALUES (2274, 'a very important meeting', 'adj. 重要的；有势力的', '/im\'pɔ:tənt | ɪm\'pɔːt(ə)nt | ɪm\'pɔrtnt/', 'important', 1);
INSERT INTO `words` VALUES (2275, 'The court can impose a fine.', 'v. 强加', '/im\'pəuz | ɪm\'pəʊz | ɪm\'poz/', 'impose', 1);
INSERT INTO `words` VALUES (2276, '‘I want to speak to Mr Franks.’ ‘I’m afraid that’s impossible.’', 'adj. 不可能的，办不到的', '/im\'pɔsəbl | ɪm\'pɒsɪb(ə)l | ɪm\'pɑsəbl/', 'impossible', 1);
INSERT INTO `words` VALUES (2277, 'Steve borrowed his dad’s sports car to impress his girlfriend.', 'v. 给…深刻印象', '/im\'pres, \'impres | ɪm\'pres | ɪm\'prɛs/', 'impress', 1);
INSERT INTO `words` VALUES (2278, 'When we looked around the school we got a very good impression.', 'n. 印；印象；印记', '/ɪm\'preʃ(ə)n | ɪm\'prɛʃən/', 'impression', 1);
