INSERT INTO `words` VALUES (2280, 'The government imprisoned all opposition leaders.', 'v. 关押，监禁；限制', '/im\'prizən | ɪm\'prɪz(ə)n | ɪm\'prɪzn/', 'imprison', 1);
INSERT INTO `words` VALUES (2281, '25 officers were investigated following allegations of improper conduct.', 'adj. 不合适的，不适当的', '/im\'prɔpə | ɪmˈprɒpə(r) | ɪm\'prɑpɚ/', 'improper', 1);
INSERT INTO `words` VALUES (2282, 'a course for students wishing to improve their English', 'v. 使更好; v. 改善', '/im\'pru:v | ɪm\'pruːv | ɪm\'pruv/', 'improve', 1);
INSERT INTO `words` VALUES (2283, 'Our results have shown some improvement this month.', 'n. 改进，改善；改进处', '/ɪm\'pruːvm(ə)nt | ɪm\'prʊvmənt/', 'improvement', 1);
