INSERT INTO `words` VALUES (2285, 'Unemployment can cause feelings of inadequacy and low self-esteem.', 'n. 不足', '/in\'ædikwəsi | ɪn\'ædɪkwəsɪ | ɪn\'ædɪkwəsi/', 'inadequacy', 1);
INSERT INTO `words` VALUES (2286, 'inadequate resources', 'adj. 不足的，不够的', '/in\'ædikwit | ɪn\'ædɪkwət/', 'inadequate', 1);
INSERT INTO `words` VALUES (2287, 'There is no suggestion that clients have been sold inappropriate policies.', 'adj. 不合适的', '/,inə\'prəupriət | ɪnə\'prəʊprɪət | \'ɪnə\'proprɪət/', 'inappropriate', 1);
INSERT INTO `words` VALUES (2288, 'As an added incentive, there’s a bottle of champagne for the best team.', 'n. 动机，刺激', '/in\'sentiv | ɪn\'sentɪv | ɪn\'sɛntɪv/', 'incentive', 1);
