INSERT INTO `words` VALUES (2292, '...the factors that incline us toward particular beliefs.', 'v. 倾向于', '/in\'klain | ɪnˈklaɪn | ɪn\'klaɪn/', 'incline', 1);
INSERT INTO `words` VALUES (2293, 'Does the price include postage?', 'v. 包含', '/in\'klu:d | ɪn\'kluːd | ɪn\'klud/', 'include', 1);
INSERT INTO `words` VALUES (2294, 'low-income families', 'n. 收入；收益；进款', '/\'inkʌm | \'ɪnkʌm/', 'income', 1);
INSERT INTO `words` VALUES (2295, 'an incomparable view of San Marco', 'adj. 无比的，无可匹敌的', '/in\'kɔmpərəbl | ɪn\'kɒmp(ə)rəb(ə)l | ɪn\'kɑmprəbl/', 'incomparable', 1);
INSERT INTO `words` VALUES (2296, 'The information you gave us was incorrect.', 'adj. 不正确的，错误的', '/,inkə\'rekt | ɪnkə\'rekt | ,ɪnkə\'rɛkt/', 'incorrect', 1);
INSERT INTO `words` VALUES (2297, 'The population increased dramatically in the first half of the century.', 'vt&vi&n. 增加', '/in\'kri:s, \'inkri:s | ɪn\'kriːs | \'ɪnkris/', 'increase', 1);
INSERT INTO `words` VALUES (2298, 'Marketing techniques are becoming increasingly sophisticated.', 'adv. 日益，越来越多地', '/in\'kri:siŋli | ɪn\'kriːsɪŋlɪ | ɪn\'krisɪŋli/', 'increasingly', 1);
INSERT INTO `words` VALUES (2299, 'It’s incredible that he survived the fall.', 'adj. 不可思议的', '/in\'kredəbl | ɪn\'krɛdəbl/', 'incredible', 1);
INSERT INTO `words` VALUES (2300, 'The blood tests prove that Vince is indeed the father.', 'adv. 真正地；确实', '/in\'di:d | ɪn\'diːd | ɪn\'did/', 'indeed', 1);
INSERT INTO `words` VALUES (2301, 'Teachers find the report’s terminology so indefinite that it is confusing.', 'adj. 不明确的；不定的', '/in\'definət | ɪn\'defɪnɪt | ɪn\'dɛfɪnət/', 'indefinite', 1);
INSERT INTO `words` VALUES (2302, 'The country has made great advances since independence.', 'n. 独立，自主，自立', '/,indi\'pendəns | ɪndɪ\'pend(ə)ns | ,ɪndɪ\'pɛndəns/', 'independence', 1);
INSERT INTO `words` VALUES (2303, 'There are plans to split the corporation into a number of smaller independent companies.', 'adj. 独立的；自主的', '/,indi\'pendənt | ,ɪndɪ\'pendənt | \'ɪndɪ\'pɛndənt/', 'independent', 1);
INSERT INTO `words` VALUES (2304, 'In each of these cases, one of the models evolved independently of the other.', 'adv. 独立地', '/,indi\'pendəntli | ˌɪndɪ\'pendəntlɪ | ,ɪndɪ\'pɛndəntli/', 'independently', 1);
INSERT INTO `words` VALUES (2305, '...the consumer price index.', 'n. 索引；指数；指标', '/\'indeks | \'ɪndeks | \'ɪndɛks/', 'index', 1);
INSERT INTO `words` VALUES (2306, 'Burma borders on India.', 'n. 印度', '/\'indiə | \'ɪndɪə/', 'India', 1);
INSERT INTO `words` VALUES (2307, '...the Indian government.', 'adj. 印度的; n. 印度人', '/\'indiən | \'ɪndɪən/', 'Indian', 1);
INSERT INTO `words` VALUES (2308, 'The study indicates a connection between poverty and crime.', 'v. 表明', '/\'indikeit | \'ɪndɪkeɪt | \'ɪndɪket/', 'indicate', 1);
INSERT INTO `words` VALUES (2309, 'Could you give me some indication as to when I am likely to receive a reply?', 'n. 指示；表示；表明', '/,indi\'keiʃən | ɪndɪ\'keɪʃ(ə)n | ,ɪndɪ\'keʃən/', 'indication', 1);
INSERT INTO `words` VALUES (2310, 'People have become indifferent to the suffering of others.', 'adj. 冷漠的', '/in\'difərənt | ɪn\'dɪf(ə)r(ə)nt | ɪn\'dɪfrənt/', 'indifferent', 1);
INSERT INTO `words` VALUES (2311, 'an indignant reply', 'adj. 愤慨的，义愤的', '/in\'diɡnənt | ɪn\'dɪgnənt | ɪn\'dɪɡnənt/', 'indignant', 1);
INSERT INTO `words` VALUES (2312, 'Losing weight is an indirect result of smoking cigarettes.', 'adj. 间接的；不坦率的', '/,indi\'rekt, -dai- | ɪndɪ\'rekt; ɪndaɪ- | ,ɪndə\'rɛkt/', 'indirect', 1);
INSERT INTO `words` VALUES (2313, 'Mobile phones have become an indispensable part of our lives.', 'adj. 必不可少的', '/,indis\'pensəbl | ,ɪndɪs\'pɛnsəb! | \'ɪndɪ\'spɛnsəbl/', 'indispensable', 1);
INSERT INTO `words` VALUES (2314, 'the rights of the individual', 'n. 个人', '/,indi\'vidjuəl, -dʒəl | ˌɪndɪˈvɪdʒuəl | ,ɪndɪ\'vɪdʒuəl/', 'individual', 1);
INSERT INTO `words` VALUES (2315, 'an indoor swimming pool', 'adv. 在室内， 在户内; adj. 室内的', '/\'ɪndɔː | \'ɪndɔr/', 'indoor', 1);
INSERT INTO `words` VALUES (2316, 'Let’s go indoors and have something to eat.', 'adv. 在室内，在屋里', '/\'indɔ:z | ɪn\'dɔːz | ,ɪn\'dɔrz/', 'indoors', 1);
INSERT INTO `words` VALUES (2317, 'She had to be induced because the baby was four weeks late.', 'v. 引诱', '/in\'dju:s, in\'du:s | ɪn\'djuːs | ɪn\'dus/', 'induce', 1);
INSERT INTO `words` VALUES (2318, 'By 1900, Britain was a mainly industrial society.', 'adj. 工业的；产业的', '/in\'dʌstriəl | ɪn\'dʌstrɪəl/', 'industrial', 1);
INSERT INTO `words` VALUES (2319, 'Energy consumption rises as countries industrialize.', 'v. 使工业化', '/in\'dʌtriəlaiz | ɪnˈdʌstrɪəlʌɪz | ɪn\'dʌstrɪəlaɪz/', 'industrialize', 1);
INSERT INTO `words` VALUES (2320, 'I work in the oil industry.', 'n. 工业，产业；勤劳', '/\'indəstri | \'ɪndəstrɪ | \'ɪndəstri/', 'industry', 1);
INSERT INTO `words` VALUES (2321, 'an inefficient use of resources', 'adj. 效率低的，无能的', '/,ini\'fiʃənt | ɪnɪ\'fɪʃ(ə)nt | ,ɪnɪ\'fɪʃnt/', 'inefficient', 1);
INSERT INTO `words` VALUES (2322, 'A further escalation of the crisis now seems inevitable.', 'adj. 不可避免的', '/in\'evitəbl | ɪnˈevɪtəbl | ɪn\'ɛvɪtəbl/', 'inevitable', 1);
INSERT INTO `words` VALUES (2323, 'a good selection of inexpensive wines', 'adj. 花费不多的，廉价的', '/,inik\'spensiv | ɪnɪk\'spensɪv; ɪnek- | ,ɪnɪk\'spɛnsɪv/', 'inexpensive', 1);
INSERT INTO `words` VALUES (2324, 'An infant’s skin is very sensitive.', 'n. 婴儿; adj. 婴儿的', '/\'infənt | \'ɪnf(ə)nt | \'ɪnfənt/', 'infant', 1);
INSERT INTO `words` VALUES (2325, 'People with the virus may feel perfectly well, but they can still infect others.', 'v. 传染；感染', '/in\'fekt | ɪn\'fekt | ɪn\'fɛkt/', 'infect', 1);
INSERT INTO `words` VALUES (2326, 'I inferred from what she said that you have not been well.', 'v. 推论，推断；猜想', '/in\'fə: | ɪn\'fɜː | ɪn\'fɝ/', 'infer', 1);
INSERT INTO `words` VALUES (2327, 'There were two inferences to be drawn from her letter.', 'n. 推断结果， 结论； 推论， 推理， 推断', '/\'ɪnfərəns/', 'inference', 1);
INSERT INTO `words` VALUES (2328, 'I felt very inferior among all those academics.', 'adj. 下等的；劣等的', '/in\'fiəriə | ɪn\'fɪərɪə | ɪn\'fɪrɪɚ/', 'inferior', 1);
INSERT INTO `words` VALUES (2329, 'The universe is infinite.', 'adj. 无限的', '/\'infinət | \'ɪnfɪnət/', 'infinite', 1);
INSERT INTO `words` VALUES (2330, 'It took us half an hour to inflate the dinghy.', 'v. 膨胀', '/in\'fleit | ɪn\'fleɪt | ɪn\'flet/', 'inflate', 1);
INSERT INTO `words` VALUES (2331, 'Inflation is now at over 16%.', 'n. 通货膨胀', '/in\'fleiʃən | ɪn\'fleʃən/', 'inflation', 1);
INSERT INTO `words` VALUES (2332, 'As a scientist, his influence was immense.', 'v & n. 影响', '/\'influəns | \'ɪnflʊəns | \'ɪnfluəns/', 'influence', 1);
INSERT INTO `words` VALUES (2333, 'He had influential friends.', 'adj. 有影响力的', '/ˌɪnfluˈenʃl | ,ɪnflu\'ɛnʃl/', 'influential', 1);
INSERT INTO `words` VALUES (2334, 'They decided to inform the police.', 'v. 通知，向…报告', '/in\'fɔ:m | ɪn\'fɔːm | ɪn\'fɔrm/', 'inform', 1);
