INSERT INTO `words` VALUES (2336, 'Combine all the ingredients in a large bowl.', 'n. 成分，原料', '/in\'ɡri:diənt | ɪnˈgri:diənt | ɪn\'ɡridɪənt/', 'ingredient', 1);
INSERT INTO `words` VALUES (2337, 'The woods are inhabited by many wild animals.', 'v. 居住于，栖息于', '/in\'hæbit | ɪn\'hæbɪt/', 'inhabit', 1);
INSERT INTO `words` VALUES (2338, 'a city of six million inhabitants', 'n. 居民，住户', '/in\'hæbitənt | ɪn\'hæbɪt(ə)nt | ɪn\'hæbɪtənt/', 'inhabitant', 1);
INSERT INTO `words` VALUES (2339, 'inherited wealth', 'v. 继承', '/in\'herit | ɪn\'herɪt | ɪn\'hɛrɪt/', 'inherit', 1);
INSERT INTO `words` VALUES (2340, 'an initial investment of £5,000', 'adj. 最初的；词首的', '/i\'niʃəl | ɪ\'nɪʃəl/', 'initial', 1);
INSERT INTO `words` VALUES (2341, 'Stan initially wanted to go to medical school.', 'adv. 最初，起初', '/i\'niʃəli | ɪ\'nɪʃ(ə)lɪ | ɪ\'nɪʃəli/', 'initially', 1);
INSERT INTO `words` VALUES (2342, 'They have decided to initiate legal proceedings against the newspaper.', 'v. 开始，发起', '/i\'niʃieit, i\'niʃiət, -eit | ɪ\'nɪʃɪeɪt | ɪ\'nɪʃɪet/', 'initiate', 1);
INSERT INTO `words` VALUES (2343, 'I wish my son would show more initiative.', 'n. 主动权，自主权', '/i\'niʃiətiv, -ʃətiv | i\'niʃətiv | ɪ\'nɪʃətɪv/', 'initiative', 1);
INSERT INTO `words` VALUES (2344, 'The nurse gave me a tetanus injection.', 'n. 注射，注入；充满', '/in\'dʒekʃən | ɪn\'dʒekʃ(ə)n | ɪn\'dʒɛkʃən/', 'injection', 1);
INSERT INTO `words` VALUES (2345, 'Angus injured his leg playing rugby.', 'v. 使受伤', '/\'indʒə | \'ɪndʒə(r) | \'ɪndʒɚ/', 'injure', 1);
INSERT INTO `words` VALUES (2346, 'She was taken to hospital with serious head injuries.', 'n. 损害，伤害；受伤处', '/\'ɪndʒəri/', 'injury', 1);
INSERT INTO `words` VALUES (2347, 'Please write in black ink.', 'n. 墨水，油墨', '/iŋk | ɪŋk/', 'ink', 1);
INSERT INTO `words` VALUES (2348, 'We’re staying at the Holiday Inn.', 'n. 小旅店；小酒店', '/in | ɪn/', 'inn', 1);
INSERT INTO `words` VALUES (2349, 'an inner room', 'adj. 内部的；内心的', '/\'inə | ɪnə | \'ɪnɚ/', 'inner', 1);
INSERT INTO `words` VALUES (2350, 'Nobody would believe that I was innocent.', 'adj. 无辜的，天真的；', '/\'inəsənt | \'ɪnəs(ə)nt | \'ɪnəsnt/', 'innocent', 1);
INSERT INTO `words` VALUES (2351, 'the need for large businesses to innovate', 'v. 创新，革新', '/\'inəuveit | \'ɪnəveɪt | \'ɪnəvet/', 'innovate', 1);
INSERT INTO `words` VALUES (2352, 'We must encourage innovation if the company is to remain competitive.', 'n. 改革，创新', '/,inəu\'veiʃən | ˌɪnəˈveɪʃn | ,ɪnə\'veʃən/', 'innovation', 1);
INSERT INTO `words` VALUES (2353, 'an innovative approach to language teaching', 'adj. 创新的， 革新的', '/\'ɪnəveɪtɪv | \'ɪnəvetɪv/', 'innovative', 1);
INSERT INTO `words` VALUES (2354, 'If the input data specified it, the file will close and the process terminates.', 'n. 输入；投入的资金', '/\'input | \'ɪnpʊt | \'ɪn\'pʊt/', 'input', 1);
INSERT INTO `words` VALUES (2355, '‘Why are you doing that?’ the boy inquired.', 'v. 询问', '/in\'kwaiə | ɪn\'kwaɪə | ɪn\'kwaɪr/', 'inquire', 1);
INSERT INTO `words` VALUES (2356, 'I don’t know who sent the gift, but I’ll make some inquiries.', 'n. 询问', '/in\'kwaiəri | ɪn\'kwaɪərɪ | ɪn\'kwaɪri; \'ɪn,kwaɪri; \'ɪnkwəri; \'ɪŋkwaɪri/', 'inquiry', 1);
INSERT INTO `words` VALUES (2357, 'an insect bite', 'n. 昆虫，虫', '/\'insekt | \'ɪnsekt | \'ɪnsɛkt/', 'insect', 1);
INSERT INTO `words` VALUES (2358, 'Many of them work in low-paid insecure jobs.', 'adj. 不安全的', '/,insi\'kujə | ,ɪnsɪ\'kjʊə; | ,ɪnsɪ\'kjʊr/', 'insecure', 1);
INSERT INTO `words` VALUES (2359, 'He took a small key from his pocket and slowly inserted it into the lock.', 'v. 插入；嵌入；登载', '/ɪn\'sɜːt | \'ɪnsɝt/', 'insert', 1);
INSERT INTO `words` VALUES (2360, 'He concealed the key inside his tie.', 'prep. 在…里面; n. 内部', '/,in\'said, \'in- | ɪn\'saɪd | \'ɪn\'saɪd/', 'inside', 1);
INSERT INTO `words` VALUES (2361, 'a woman of great insight', 'n. 洞察力，洞悉', '/\'insait | \'ɪnsaɪt | \'ɪn\'saɪt/', 'insight', 1);
INSERT INTO `words` VALUES (2362, 'Stay for supper – I insist!', 'v. 主张，坚持', '/in\'sist | ɪn\'sɪst/', 'insist', 1);
INSERT INTO `words` VALUES (2363, 'I got out of the car to inspect the damage.', 'v. 检查，审查；检阅', '/in\'spekt | ɪn\'spekt | ɪn\'spɛkt/', 'inspect', 1);
INSERT INTO `words` VALUES (2364, 'An inspection was carried out at the school.', 'n. 检查，审查；检阅', '/in\'spekʃən | ɪn\'spekʃn | ɪn\'spɛkʃən/', 'inspection', 1);
INSERT INTO `words` VALUES (2365, 'ticket inspectors', 'n. 检查员', '/in\'spektə | ɪn\'spektə | ɪn\'spɛktɚ/', 'inspector', 1);
INSERT INTO `words` VALUES (2366, 'The Malvern Hills have provided inspiration for many artists and musicians over the decades.', 'n. 灵感', '/,inspə\'reiʃən | ˌɪnspə\'reɪʃn | ˌɪnspəˈreʃən/', 'inspiration', 1);
INSERT INTO `words` VALUES (2367, 'We need someone who can inspire the team.', 'v. 激发；鼓舞；使产生灵感', '/in\'spaiə | in\'spaɪə | ɪn\'spaɪɚ/', 'inspire', 1);
INSERT INTO `words` VALUES (2368, 'They’ve installed the new computer network at last.', 'v. 安装', '/in\'stɔ:l | ɪnˈstɔ:l | ɪn\'stɔl/', 'install', 1);
INSERT INTO `words` VALUES (2369, 'the installation and maintenance of alarm systems', 'n. 安装，就任', '/,instə\'leiʃən | ,ɪnstə\'leɪʃən | \'ɪnstə\'leʃən/', 'installation', 1);
INSERT INTO `words` VALUES (2370, NULL, 'n. 安装，分期付款', '/in\'stɔ:lmənt | ɪn\'stɔ:lmənt | ɪn\'stɔlmənt/', 'installment', 1);
INSERT INTO `words` VALUES (2371, 'We need to rethink the way we consume energy. Take, for instance, our approach to transport.', 'n. 情况，例子', '/\'instəns | ˈɪnstəns | \'ɪnstəns/', 'instance', 1);
INSERT INTO `words` VALUES (2372, 'an instant success', 'adj. 立即的；紧急的；速溶的，方便的', '/\'instənt | \'ɪnstənt/', 'instant', 1);
INSERT INTO `words` VALUES (2373, 'All four victims died instantly.', 'adv. 立即，即刻', '/\'instəntli | \'ɪnst(ə)ntlɪ | \'ɪnstəntli/', 'instantly', 1);
INSERT INTO `words` VALUES (2374, 'You probably picked up my keys instead of yours.', 'adv. 代替，顶替；反而', '/ɪn\'sted | ɪn\'stɛd/', 'instead', 1);
INSERT INTO `words` VALUES (2375, 'Her instinct told her that something was wrong.', 'n. 本能；直觉；生性', '/\'instiŋkt | \'ɪnstɪŋ(k)t | \'ɪnstɪŋkt/', 'instinct', 1);
INSERT INTO `words` VALUES (2376, 'We will institute a number of measures to better safeguard the public.', 'n & v. 建立', '/\'institjut, -tu:t | \'ɪnstɪtju:t | \'ɪnstɪtut/', 'institute', 1);
INSERT INTO `words` VALUES (2377, 'powerful institutions such as world banks', 'n. 社会公共机构；制度，习俗；设立，制定', '/,insti\'tju:ʃən | ,ɪnstɪ\'tuʃən/', 'institution', 1);
INSERT INTO `words` VALUES (2378, 'Eva went straight to the hotel, as instructed (= as she had been told ).', 'v. 指导；通知；命令；教授', '/in\'strʌkt | ɪn\'strʌkt/', 'instruct', 1);
INSERT INTO `words` VALUES (2379, 'Press ‘Enter’ and follow the on-screen instructions.', 'n. 命令，指示，用法说明', '/in\'strʌkʃən | ɪn\'strʌkʃən/', 'instruction', 1);
INSERT INTO `words` VALUES (2380, 'surgical instruments', 'n. 仪器，器械，工具', '/\'instrumənt, \'instrə-, -ment | \'ɪnstrumənt | \'ɪnstrəmənt/', 'instrument', 1);
INSERT INTO `words` VALUES (2381, 'Insufficient resources have been devoted to the health service.', 'adj. 不足的；不适当的', '/ɪnsə\'fɪʃ(ə)nt | ,ɪnsə\'fɪʃnt/', 'insufficient', 1);
INSERT INTO `words` VALUES (2382, 'Nobody insults my family and gets away with it!', 'v. 侮辱', '/in\'sʌlt | ɪn\'sʌlt/', 'insult', 1);
INSERT INTO `words` VALUES (2383, 'Your father took out insurance to cover the mortgage.', 'n. 保险；保险费', '/in\'ʃuərəns | ɪn\'ʃʊər(ə)ns | ɪn\'ʃʊrəns/', 'insurance', 1);
INSERT INTO `words` VALUES (2384, 'Have you insured the contents of your home?', 'v. 给…保险；确保', '/in\'ʃuə | ɪn\'ʃɔː; ɪn\'ʃʊə | ɪn\'ʃʊr/', 'insure', 1);
INSERT INTO `words` VALUES (2385, 'Your intake of alcohol should not exceed two units per day.', 'n. 摄入', '/\'inteik | ˈɪnteɪk | \'ɪn\'tek/', 'intake', 1);
INSERT INTO `words` VALUES (2386, 'He didn\'t integrate successfully into the Italian way of life.', 'v. 成为一体， 合并', '/\'ɪntɪgreɪt | \'ɪntɪɡret/', 'integrate', 1);
INSERT INTO `words` VALUES (2387, 'problems of racial integration', 'n. 综合', '/ˌɪntɪ\'greɪʃn | \'ɪntə\'greʃən/', 'integration', 1);
INSERT INTO `words` VALUES (2388, 'the territorial integrity of the country', 'n. 完整，综合', '/in\'teɡrəti | ɪn\'tegrɪtɪ | ɪn\'tɛɡrəti/', 'integrity', 1);
INSERT INTO `words` VALUES (2389, 'a leading British intellectual', 'n. 知识分子; adj. 智力的', '/,intə\'lektjuəl, -tʃuəl | ,ɪntə\'lektʃʊəl; -tjʊəl | ,ɪntə\'lɛktʃuəl/', 'intellectual', 1);
INSERT INTO `words` VALUES (2390, 'To be good at the game, you need a reasonable level of intelligence.', 'n. 智力，智慧，理解力', '/in\'telidʒəns | ɪn\'tɛlɪdʒəns/', 'intelligence', 1);
INSERT INTO `words` VALUES (2391, 'a group of highly intelligent (= very intelligent )students', 'adj. 智能的', '/in\'telidʒent | ɪn\'telɪdʒ(ə)nt | ɪn\'tɛlɪdʒənt/', 'intelligent', 1);
INSERT INTO `words` VALUES (2392, 'Oddly enough, that is precisely what I intend.', 'v. 打算', '/in\'tend | ɪn\'tend | ɪn\'tɛnd/', 'intend', 1);
INSERT INTO `words` VALUES (2393, 'Young people today are under intense pressure to succeed.', 'adj. 强烈的', '/in\'tens | ɪn\'tens | ɪn\'tɛns/', 'intense', 1);
INSERT INTO `words` VALUES (2394, 'The intensity of the hurricane was frightening.', 'n. 强烈，剧烈；强度', '/in\'tensəti | ɪn\'tensɪtɪ | ɪn\'tɛnsəti/', 'intensity', 1);
INSERT INTO `words` VALUES (2395, 'a one-week intensive course in English', 'adj. 加强的；精耕细作的', '/in\'tensiv | ɪn\'tensɪv | ɪn\'tɛnsɪv/', 'intensive', 1);
INSERT INTO `words` VALUES (2396, 'They went into town with the intention of visiting the library.', 'n. 打算，意图', '/in\'tenʃən | ɪnˈtenʃn | ɪn\'tɛnʃən/', 'intention', 1);
INSERT INTO `words` VALUES (2397, 'I did trip him, but it wasn’t intentional.', 'adj. 故意的，有意识的', '/in\'tenʃənəl | ɪn\'tenʃ(ə)n(ə)l | ɪn\'tɛnʃənl/', 'intentional', 1);
INSERT INTO `words` VALUES (2398, 'But you only get the maximum benefit if you implement all of them, because their power comes from their interaction.', 'n. 相互作用；干扰', '/,intər\'ækʃən | ɪntər\'ækʃ(ə)n | ,ɪntə\'rækʃən/', 'interaction', 1);
INSERT INTO `words` VALUES (2399, 'In Freud’s theory, the two areas of sexuality and violence are interconnected.', 'v. 相互联系', '/,intəkə\'nekt | ɪntəkə\'nekt | ,ɪntɚkə\'nɛkt/', 'interconnect', 1);
INSERT INTO `words` VALUES (2400, '...the interdependence of nations.', 'n. 相互依靠', '/,intədi\'pendəns,-dənsi | ,ɪntədɪ\'pendəns | ,ɪntɚdɪ\'pɛndəns/', 'interdependence', 1);
INSERT INTO `words` VALUES (2401, 'I watched the first few episodes, but soon lost interest.', 'n. 兴趣；利益；利息', '/\'intrist, \'intər- | \'ɪnt(ə)rɪst | \'ɪntrəst/', 'interest', 1);
INSERT INTO `words` VALUES (2402, 'That’s an interesting question.', 'adj. 有趣的，引人入胜的', '/ˈɪntrɪstɪŋ，ˈɪntrəstɪŋ | \'ɪnt(ə)rɪstɪŋ | \'ɪntrəstɪŋ/', 'interesting', 1);
INSERT INTO `words` VALUES (2403, 'My daughter-in-law said that I was interfering, but I was only trying to help.', 'v. 干涉，干预；妨碍', '/,intə\'fiə | ɪntə\'fɪə | ,ɪntɚ\'fɪr/', 'interfere', 1);
INSERT INTO `words` VALUES (2404, 'Industrial relations should be free from state interference.', 'n. 干涉，干预；阻碍', '/,intə\'fiərəns | ɪntə\'fɪər(ə)ns | ,ɪntɚ\'fɪrəns/', 'interference', 1);
INSERT INTO `words` VALUES (2405, 'The interior walls are all painted white.', 'adj. 内的；内地的n内部', '/in\'tiəriə | ɪn\'tɪɜːrɪə | ɪn\'tɪrɪɚ/', 'interior', 1);
INSERT INTO `words` VALUES (2406, 'an intermediate stage during which the disease is dormant', 'adj. 中间的；中级的', '/,intə\'mi:djət, -dieit | ,ɪntə\'miːdɪət | ,ɪntɚ\'midɪət/', 'intermediate', 1);
INSERT INTO `words` VALUES (2407, 'We have no interest in interfering in the internal affairs of other countries.', 'adj. 内的；国内的', '/in\'tə:nəl | ɪn\'tɜːn(ə)l | ɪn\'tɝnl/', 'internal', 1);
INSERT INTO `words` VALUES (2408, 'the response of the international community', 'adj. 国际的，世界(性)的', '/ɪntə\'næʃ(ə)n(ə)l | ,ɪntɚ\'næʃnəl/', 'international', 1);
INSERT INTO `words` VALUES (2409, '...an internship in surgery in New York.', 'n. 实习生身份； 实习医师期', '/\'ɪntɜːnʃɪp | \'ɪntɝnʃɪp/', 'internship', 1);
INSERT INTO `words` VALUES (2410, 'Freud’s attempts to interpret the meaning of dreams', 'v. 解释', '/in\'tə:prit | ɪn\'tɜ:prɪt | ɪn\'tɝprɪt/', 'interpret', 1);
INSERT INTO `words` VALUES (2411, 'One possible interpretation is that they want you to resign.', 'n. 阐释，说明', '/in,tə:pri\'teiʃən | ɪn\'tɜːprɪ\'teʃən | ɪn\'tɝprɪ\'teʃən/', 'interpretation', 1);
INSERT INTO `words` VALUES (2412, 'Speaking through an interpreter (= using an interpreter ), Ahmed said, ‘I’m very worried about my wife and children.’', 'n. 译员，口译者', '/in\'tə:pritə | ɪn\'tɜːprɪtə | ɪn\'tɝprɪtɚ/', 'interpreter', 1);
INSERT INTO `words` VALUES (2413, 'interracial marriage', 'adj. 种族间的', '/,intə\'reiʃiəl | ɪntə\'reɪʃ(ə)l | ,ɪntə\'reʃl/', 'interracial', 1);
INSERT INTO `words` VALUES (2414, 'Will you stop interrupting me!', 'v. 打断，打扰；中止', '/,intə\'rʌpt | ɪntə\'rʌpt | \'ɪntə\'rʌpt/', 'interrupt', 1);
INSERT INTO `words` VALUES (2415, 'For tasks that execute code in a loop, it is common to check for interruption only once per loop iteration.', 'n. 打扰，中断', '/,intə\'rʌpʃən | ˌɪntəˈrʌpʃn | ,ɪntə\'rʌpʃən/', 'interruption', 1);
INSERT INTO `words` VALUES (2416, 'He left the room, returning after a short interval with a message.', 'n. 间隔；休息；间距', '/\'intəvəl | \'ɪntəv(ə)l | \'ɪntɚvl/', 'interval', 1);
INSERT INTO `words` VALUES (2417, 'The army will have to intervene to prevent further fighting.', 'vi. 干涉， 调停， 干预； 插入， 介入； 干扰， 打扰', '/ˌɪntə\'viːn | ,ɪntɚ\'vin/', 'intervene', 1);
INSERT INTO `words` VALUES (2418, 'government intervention to regulate prices', 'n. 干涉', '/,intə\'venʃən | ˌɪntə\'venʃn | ,ɪntɚ\'vɛnʃən/', 'intervention', 1);
