INSERT INTO `words` VALUES (2786, 'We’re having a meeting next week to discuss the matter.', 'n. 聚集，会合，会见', '/\'mi:tiŋ | \'miːtɪŋ | \'mitɪŋ/', 'meeting', 1);
INSERT INTO `words` VALUES (2787, '...some juicy slices of melon.', 'n. 瓜，甜瓜', '/\'melən | \'mɛlən/', 'melon', 1);
INSERT INTO `words` VALUES (2788, 'It was warmer now, and the snow was beginning to melt.', 'v. 融化', '/melt | mɛlt/', 'melt', 1);
INSERT INTO `words` VALUES (2789, 'The majority of union members voted in favour of a strike.', 'n. 成员，会员', '/\'membə | \'mɛmbɚ/', 'member', 1);
INSERT INTO `words` VALUES (2790, 'You should carry your membership card with you at all times.', 'n. 会员身份， 会籍； 全体会员， 会员数', '/\'membəʃɪp | \'mɛmbɚʃɪp/', 'membership', 1);
INSERT INTO `words` VALUES (2791, 'A memorial service is being held for her at St. Paul\'s Church.', 'adj. 纪念的；记忆的', '/英 [mə\'mɔ:rɪəl] 美 [məˈmɔriəl, -ˈmor | mə\'mɔːrɪəl | mə\'morɪəl/', 'memorial', 1);
INSERT INTO `words` VALUES (2792, 'He studied his map, trying to memorize the way to Rose\'s street.', 'v. 熟记，牢记', '/\'meməraiz | \'meməraɪz | \'mɛmə\'raɪz/', 'memorize', 1);
INSERT INTO `words` VALUES (2793, 'He has lots of happy memories of his stay in Japan.', 'n. 记忆；回忆；存储', '/\'meməri | \'mem(ə)rɪ | \'mɛməri/', 'memory', 1);
INSERT INTO `words` VALUES (2794, 'My father used to mend our shoes.', 'v. 修理，修补，缝补', '/mend | mɛnd/', 'mend', 1);
INSERT INTO `words` VALUES (2795, 'The centre provides help for people suffering from mental illness .', 'adj. 智力的；精神的', '/\'mentəl | \'ment(ə)l | \'mɛntl/', 'mental', 1);
INSERT INTO `words` VALUES (2796, 'Was my name mentioned at all?', 'vt&n. 提及，说起', '/\'menʃən | \'menʃ(ə)n | \'mɛnʃən/', 'mention', 1);
INSERT INTO `words` VALUES (2797, 'Could we have the menu, please?', 'n. 菜单', '/\'menju:, mə\'nju: | ˈmenju: | \'mɛnju/', 'menu', 1);
INSERT INTO `words` VALUES (2798, 'the son of a wealthy merchant', 'n. 商人；零售商', '/\'mə:tʃənt | \'mɜːtʃ(ə)nt | \'mɝtʃənt/', 'merchant', 1);
INSERT INTO `words` VALUES (2799, 'Some thieves have eaten off their irons with mercury water.', 'n. 水银，汞', NULL, 'mercury', 1);
INSERT INTO `words` VALUES (2800, 'He showed no mercy to his enemies.', 'n. 仁慈，慈悲，恩惠', '/\'mə:si | \'mɜːsɪ | \'mɝsi/', 'mercy', 1);
INSERT INTO `words` VALUES (2801, 'She lost the election by a mere 20 votes.', 'adj. 仅仅的；纯粹的', '/miə | mɪə | mɪr/', 'mere', 1);
INSERT INTO `words` VALUES (2802, 'He’s merely a boy – you can’t expect him to understand.', 'adv. 仅仅，只不过', '/\'miəli | \'mɪəlɪ | \'mɪrli/', 'merely', 1);
INSERT INTO `words` VALUES (2803, 'The merit of the report is its realistic assessment of the changes required.', 'n. 优点，成绩; v. 值得', '/\'merit | \'mɛrɪt/', 'merit', 1);
INSERT INTO `words` VALUES (2804, 'He marched off, whistling a merry tune.', 'adj. 欢乐的，愉快的', '/\'meri | \'merɪ | \'mɛri/', 'merry', 1);
INSERT INTO `words` VALUES (2805, 'What a mess!', 'n. 混乱，混杂，肮脏', '/mes | mɛs/', 'mess', 1);
INSERT INTO `words` VALUES (2806, 'He left a message saying he would probably be a little late.', 'n. 信息，消息；启示', '/\'mesidʒ | \'mesɪdʒ | \'mɛsɪdʒ/', 'message', 1);
INSERT INTO `words` VALUES (2807, 'There will be a messenger at the airport to collect the photographs from our courier.', 'n. 送信者，信使', '/\'mesindʒə | \'mesɪn(d)ʒə | \'mɛsndʒɚ/', 'messenger', 1);
INSERT INTO `words` VALUES (2808, 'The gate is made of metal.', 'n. 金属，金属制品', '/\'metəl | \'met(ə)l | \'mɛtl/', 'metal', 1);
INSERT INTO `words` VALUES (2809, 'A man came to read the electricity meter .', 'n. 计量器，计，表', '/mi:tə | \'mitɚ | \'mitɚr/', 'meter', 1);
INSERT INTO `words` VALUES (2810, 'traditional teaching methods', 'n. 方法，办法；教学法', '/\'meθəd | \'mɛθəd/', 'method', 1);
INSERT INTO `words` VALUES (2811, 'She\'s running the 1,500 metres here.', 'n. 米，公尺', '/\'mi:tə | \'mi:tə(r) | ˈmitɚ/', 'metre', 1);
INSERT INTO `words` VALUES (2812, 'a metric tonne', 'adj. 公制的，米制的', '/\'metrik | \'metrɪk | \'mɛtrɪk/', 'metric', 1);
INSERT INTO `words` VALUES (2813, 'The merchant sold electrical appliances, such as microcomputer, microphone, microprocessor and microwave ovens.', 'n. 微型计算机，微机', '/,maikrəukəm\'pju:tə | \'maɪkrə(ʊ)kɒm,pjuːtə | \'maɪkrokəm\'pjʊtɚ/', 'microcomputer', 1);
INSERT INTO `words` VALUES (2814, 'She spoke confidently into the microphone.', 'n. 话筒，麦克风', '/\'maikrəfəun | \'maɪkrəfəʊn | \'maɪkrə\'fon/', 'microphone', 1);
INSERT INTO `words` VALUES (2815, 'The slightest movement will defocus the microscope.', 'n. 显微镜', '/\'maikrəskəup | \'maɪkrəskəʊp | \'maɪkrəskop/', 'microscope', 1);
INSERT INTO `words` VALUES (2816, 'We stopped off in Colchester for our midday meal .', 'n. 正午，中午', '/\'middei | mɪd\'deɪ | ,mɪd\'de/', 'midday', 1);
INSERT INTO `words` VALUES (2817, 'There are plenty of small houses for sale, and quite a lot of very large ones, but very little in the middle.', 'n. 中部; adj. 中部的', '/\'mɪd(ə)l | \'mɪdl/', 'middle', 1);
INSERT INTO `words` VALUES (2818, 'You can’t phone her now – it’s gone midnight (= after midnight ) !', 'n. 午夜，子夜，夜半', '/\'midnait | \'mɪdnaɪt/', 'midnight', 1);
INSERT INTO `words` VALUES (2819, 'I fear we have an enemy in our midst.', 'n. 中部，中间，当中', '/midst | mɪdst/', 'midst', 1);
INSERT INTO `words` VALUES (2820, 'If you need more information, you might try the Internet.', 'v. aux可能，会，也许', '/mait | maɪt/', 'might', 1);
INSERT INTO `words` VALUES (2821, 'What does this migration not do?', 'n. 迁移，移民', '/mai\'ɡreiʃən | maɪˈgreɪʃn | maɪ\'ɡreʃən/', 'migration', 1);
INSERT INTO `words` VALUES (2822, 'We had an exceptionally mild winter last year.', 'adj. 和缓的；温柔的', '/maild | maɪld/', 'mild', 1);
INSERT INTO `words` VALUES (2823, 'It’s 40 miles from here to the Polish border.', 'n. 英里', '/mail | maɪl/', 'mile', 1);
INSERT INTO `words` VALUES (2824, 'a military helicopter', 'adj. 军队的，军事的', '/\'militəri | \'mɪlətrɪ | \'mɪlətɛri/', 'military', 1);
INSERT INTO `words` VALUES (2825, 'a bottle of milk', 'n. 乳，牛奶; v. 挤(奶)', '/milk | mɪlk/', 'milk', 1);
INSERT INTO `words` VALUES (2826, '...a steel mill.', 'n. 工厂', '/mil | mɪl/', 'mill', 1);
INSERT INTO `words` VALUES (2827, 'The creature is a tiny centipede, just 10 millimetres long.', 'n. 毫米', '/\'mili,mi:tə/', 'millimetre', 1);
INSERT INTO `words` VALUES (2828, 'The book sold more than a million copies.', 'num. 百万; n. 许多', '/\'miljən | \'mɪljən/', 'million', 1);
INSERT INTO `words` VALUES (2829, 'It is impossible to understand the complex nature of the human mind .', 'n. 头脑；理智；记忆', '/maind | maɪnd/', 'mind', 1);
INSERT INTO `words` VALUES (2830, 'It was Glen’s idea, not mine.', 'pron. 我的', '/main | maɪn/', 'mine', 1);
INSERT INTO `words` VALUES (2831, 'Therefore, we should be more like a miner to stand in reality, excavate off wastes, and get gold mines.', 'n. 矿工', '/\'mainə | \'maɪnə | \'maɪnɚ/', 'miner', 1);
INSERT INTO `words` VALUES (2832, 'Or they could be trained to use weeds as indicators of the soil\'s mineral properties to help them manage nutrients.', 'adj. 矿物的，似矿物的', '/\'minərəl | \'mɪnərəl/', 'mineral', 1);
INSERT INTO `words` VALUES (2833, 'Every effort is being made to minimize civilian casualties.', 'vt. 将…减少； 最小化', '/\'mɪnɪmaɪz/', 'minimize', 1);
INSERT INTO `words` VALUES (2834, 'This will take a minimum of one hour.', 'n. 最小量; adj. 最小的', '/\'miniməm | \'mɪnɪməm/', 'minimum', 1);
INSERT INTO `words` VALUES (2835, 'a senior Cabinet minister', 'n. 部长，大臣；公使', '/\'ministə | \'mɪnɪstə | \'mɪnɪstɚ/', 'minister', 1);
INSERT INTO `words` VALUES (2836, '...the Ministry of Justice.', 'n. (政府的)部', '/\'ministri | \'mɪnɪstrɪ | \'mɪnɪstri/', 'ministry', 1);
INSERT INTO `words` VALUES (2837, 'We have made some minor changes to the program.', 'adj. 小的', '/\'mainə | ˈmaɪnə(r) | \'maɪnɚ/', 'minor', 1);
INSERT INTO `words` VALUES (2838, 'Gaelic is still spoken in Ireland by a tiny minority.', 'n. 少数；少数民族', '/mai\'nɔrəti, mi- | maɪ\'nɒrɪtɪ; mɪ- | maɪ\'nɔrəti/', 'minority', 1);
INSERT INTO `words` VALUES (2839, '‘Any minus points ?’ ‘Well, the engine is rather noisy.’', 'adj. 负的; prep. 减(去)', '/\'mainəs | \'maɪnəs/', 'minus', 1);
INSERT INTO `words` VALUES (2840, 'It takes me ten minutes to walk to work.', 'n. 分，分钟；一会儿', '/\'mɪnɪt/', 'minute', 1);
INSERT INTO `words` VALUES (2841, 'It’s a miracle you weren’t killed!', 'n. 奇迹，令人惊奇的人', '/\'mirəkl | \'mɪrək(ə)l | \'mɪrəkl/', 'miracle', 1);
INSERT INTO `words` VALUES (2842, 'He spends hours in front of the mirror !', 'n. 镜子; v. 反映，反射', '/\'mirə | \'mɪrə | \'mɪrɚ/', 'mirror', 1);
INSERT INTO `words` VALUES (2843, 'KAPLAN: Well, there\'s always the risk of a miscalculation or an accident at sea.', 'n. 算错，误算', '/\'mis,kælkju\'leiʃən | ˌmɪskælkjʊ\'leɪʃn/', 'miscalculation', 1);
INSERT INTO `words` VALUES (2844, 'It is a misconception that Peggy was fabulously wealthy.', 'n. 误解', '/ˌmɪskən\'sepʃn | \'mɪskən\'sɛpʃən/', 'misconception', 1);
INSERT INTO `words` VALUES (2845, 'I’ve been so miserable since Pat left me.', 'adj. 痛苦的', '/\'mizərəbl | ˈmɪzrəbl | \'mɪzrəbl/', 'miserable', 1);
INSERT INTO `words` VALUES (2846, 'In addition, they will also misguide the innocent, which becomes a vicious circle.', 'v. 误导', '/,mis\'ɡaid | mɪs\'gaɪd/', 'misguide', 1);
INSERT INTO `words` VALUES (2847, 'His parents still clung to the misguided belief that his common sense would keep him out of serious trouble.', 'adj. 被误导的', '/,mis\'ɡaidid | ˌmɪs\'ɡaɪdɪd | ,mɪs\'ɡaɪdɪd/', 'misguided', 1);
INSERT INTO `words` VALUES (2848, 'Don’t be misled by appearances, he’s a good worker.', 'v. 误导', '/,mis\'li:d | ˌmɪs\'li:d | \'mɪs\'lid/', 'mislead', 1);
INSERT INTO `words` VALUES (2849, 'I’d like to make an appointment with Miss Taylor.', 'n. 小姐', '/mɪs/', 'miss', 1);
INSERT INTO `words` VALUES (2850, 'a nuclear missile', 'n. 发射物；导弹', '/\'misail, -səl | \'mɪsaɪl | \'mɪsl/', 'missile', 1);
INSERT INTO `words` VALUES (2851, 'We found the missing piece of the jigsaw under the chair.', 'adj. 缺掉的，失去的', '/\'misiŋ | \'mɪsɪŋ/', 'missing', 1);
INSERT INTO `words` VALUES (2852, 'He was sent on over 200 missions before being killed in action.', 'n. 使命，任务；代表团', '/\'miʃən | \'mɪʃən/', 'mission', 1);
INSERT INTO `words` VALUES (2853, 'We could just see the outline of the house through the mist.', 'n. 薄雾', '/mist | mɪst/', 'mist', 1);
INSERT INTO `words` VALUES (2854, 'The most common mistake is to plant them too deep.', 'n. 错误; v. 误解，弄错', '/mi\'steik | mɪ\'steɪk | mɪ\'stek/', 'mistake', 1);
INSERT INTO `words` VALUES (2855, 'Look, Mister, we know our job, so don\'t try to tell us what to do.', 'n. 先生', '/\'mistə/', 'Mister', 1);
INSERT INTO `words` VALUES (2856, 'The maid looked nervously at her mistress.', 'n. 女主人；夫人', '/\'mistris | \'mɪstrɪs | \'mɪstrəs/', 'mistress', 1);
INSERT INTO `words` VALUES (2857, 'Rachel, you must have misunderstood her! Ellie would never say something like that.', 'v. 误解', '/,misʌndə\'stænd | ,mɪsʌndə\'stænd | ,mɪsʌndɚ\'stænd/', 'misunderstand', 1);
INSERT INTO `words` VALUES (2858, 'Oil and water don’t mix.', 'v. 使混合，混淆', '/miks | mɪks/', 'mix', 1);
INSERT INTO `words` VALUES (2859, 'Pour the mixture into four small dishes.', 'n. 混合；混合物', '/\'mikstʃə | \'mɪkstʃə | \'mɪkstʃɚ/', 'mixture', 1);
INSERT INTO `words` VALUES (2860, 'She gave a little moan of pleasure.', 'n. 呻吟声; v. 呻吟', '/məun | məʊn | mon/', 'moan', 1);
INSERT INTO `words` VALUES (2861, 'mobile air-conditioners', 'adj. 运动的；流动的', '/ˈməʊbaɪl | ˈmobəl; ˈmoˌbaɪl; ˈmoˌbil/', 'mobile', 1);
INSERT INTO `words` VALUES (2862, 'Set the monitor to 256 colour mode.', 'n. 方式，样式', '/məud | məʊd | mod/', 'mode', 1);
INSERT INTO `words` VALUES (2863, 'a working model (= one with parts which move ) of a steam engine', 'n. 模型；模式；模特儿', '/\'mɔdəl | \'mɒdl | \'mɑdl/', 'model', 1);
INSERT INTO `words` VALUES (2864, 'the more moderate members of the party', 'adj. 温和的；有节制的', '/\'mɔdərət, \'mɔdəreit | \'mɒd(ə)rət | ˈmɑdərɪt; (for v.,) ˈmɑdərˌeɪt/', 'moderate', 1);
INSERT INTO `words` VALUES (2865, 'Such companies must change if they are to compete in the modern world .', 'adj. 现代的，近代的', '/\'mɔdən | \'mɒd(ə)n | \'mɑdɚn/', 'modern', 1);
INSERT INTO `words` VALUES (2866, 'We should all make contributions to the modernization of our country.', 'n. 现代化', '/ˌmɒdənaɪ\'zeɪʃn | ,mɑdɚnə\'zeʃən/', 'modernization', 1);
INSERT INTO `words` VALUES (2867, 'You’re too modest! You’ve been a huge help to us.', 'adj. 有节制的；谦虚的', '/\'mɔdist | \'mɒdɪst | \'mɑdɪst/', 'modest', 1);
INSERT INTO `words` VALUES (2868, 'The feedback will be used to modify the course for next year.', 'v. 更改，修改；修饰', '/\'mɔdifai | \'mɒdɪfaɪ | \'mɑdɪfaɪ/', 'modify', 1);
INSERT INTO `words` VALUES (2869, 'Make sure the soil is moist before planting the seeds.', 'adj. 湿润的；多雨的', '/mɔist | mɒɪst | mɔɪst/', 'moist', 1);
INSERT INTO `words` VALUES (2870, 'When the soil is dry, more moisture is lost from the plant.', 'n. 潮湿，湿气；温度', '/\'mɔistʃə | \'mɒɪstʃə | \'mɔɪstʃɚ/', 'moisture', 1);
INSERT INTO `words` VALUES (2871, NULL, 'n. 霉，霉菌；模型，铸模；性格; vt. 用模子制作， 塑造； 使形成， 影响…的形成', '/məuld | mold/', 'mold', 1);
INSERT INTO `words` VALUES (2872, 'The molecules of oxygen gas contain just two atoms.', 'n. 分子，克分子', '/\'mɔlikjul | \'mɒlɪkjuːl | \'mɑlɪkjul/', 'molecule', 1);
INSERT INTO `words` VALUES (2873, 'It was one of the most exciting moments in his life.', 'n. 片刻，瞬间，时刻', '/\'məʊm(ə)nt | \'momənt/', 'moment', 1);
INSERT INTO `words` VALUES (2874, 'The president announced Monday that he would cancel the debt.', 'n. 星期一', '/\'mʌndi | ˈmʌndeɪ; ˈmʌndi | ˈmʌnde; ˈmʌndɪ/', 'Monday', 1);
INSERT INTO `words` VALUES (2875, 'Don’t spend all your money on the first day of your holiday!', 'n. 货币；金钱，财富', '/\'mʌni | \'mʌnɪ/', 'money', 1);
INSERT INTO `words` VALUES (2876, 'Patients who are given the new drug will be asked to monitor their progress.', 'v. 监控，监听', '/\'mɒnɪtə(r) | \'mɔnɪtɚ/', 'monitor', 1);
INSERT INTO `words` VALUES (2877, 'The monkey is beating up and down.', 'n. 猴子，猿', '/\'mʌŋki | \'mʌŋkɪ/', 'monkey', 1);
INSERT INTO `words` VALUES (2878, 'I hope I’ll have finished the work by the end of the month .', 'n. 月，月份', '/mʌnθ/', 'month', 1);
INSERT INTO `words` VALUES (2879, 'The mortgage is payable in monthly instalments.', 'adj. 每月的; adv. 每月', '/\'mʌnθli | \'mʌnθlɪ/', 'monthly', 1);
INSERT INTO `words` VALUES (2880, 'He erected a monument on the spot where his daughter was killed.', 'n. 纪念碑；纪念馆', '/\'mɔnjumənt | \'mɒnjʊm(ə)nt | \'mɑnjumənt/', 'monument', 1);
INSERT INTO `words` VALUES (2881, 'You’re in a good mood this morning!', 'n. 心情', '/mu:d | muːd | mud/', 'mood', 1);
INSERT INTO `words` VALUES (2882, 'the craters on the surface of the moon', 'n. 月球，月亮；卫星', '/mu:n | muːn | mun/', 'moon', 1);
INSERT INTO `words` VALUES (2883, 'It is easy to have an opinion on a moral issue like the death penalty for murder.', 'adj. 精神上的, 道德的', '/\'mɔrəl, \'mɔ:- | \'mɒr(ə)l | \'mɔrəl/', 'moral', 1);
INSERT INTO `words` VALUES (2884, 'The accident taught him to be more careful.', 'adj. 更多的; adv. 更', '/mɔ: | mɔː | mɔr/', 'more', 1);
INSERT INTO `words` VALUES (2885, 'The rent is reasonable and, moreover, the location is perfect.', 'adv. 再者，加之，此外', '/mɔ:\'rəuvə | mɔːr\'əʊvə | mɔr\'ovɚ/', 'moreover', 1);
INSERT INTO `words` VALUES (2886, 'I hated those cold winter mornings.', 'n. 早晨，上午', '/\'mɔ:niŋ | \'mɔːnɪŋ | \'mɔrnɪŋ/', 'morning', 1);
INSERT INTO `words` VALUES (2887, 'Her father’s death reminded her that she was mortal.', 'adj. 终有一死的；致死的', '/\'mɔ:təl | \'mɔːt(ə)l | \'mɔrtl/', 'mortal', 1);
INSERT INTO `words` VALUES (2888, 'The male mosquito never stings.', 'n. 蚊子', '/mə\'ski:təu | mɒ\'skiːtəʊ | məˈskiːtoʊ/', 'mosquito', 1);
INSERT INTO `words` VALUES (2889, 'The president himself won the most votes.', 'adj. 最多的; adv. 最，很', '/məust | məʊst | most/', 'most', 1);
INSERT INTO `words` VALUES (2890, 'Green teas are mostly from China or Japan.', 'adv. 主要的，大部分', '/\'məustli | \'məʊs(t)lɪ | \'mostli/', 'mostly', 1);
INSERT INTO `words` VALUES (2891, 'His mother and father are both doctors.', 'n. 母亲，妈妈', '/\'mʌðə | \'mʌðɚ/', 'mother', 1);
INSERT INTO `words` VALUES (2892, 'Newton’s first law of motion', 'n. 运动；手势；提议', '/\'məʊʃ(ə)n | \'moʃən/', 'motion', 1);
INSERT INTO `words` VALUES (2893, 'A good teacher has to be able to motivate her students.', 'v. 促动，激发，诱导', '/\'məutiveit | \'məʊtɪveɪt | \'motə\'vet/', 'motivate', 1);
INSERT INTO `words` VALUES (2894, NULL, 'n. 激励，刺激', '/,məuti\'veiʃən | ˌməʊtɪ\'veɪʃn | ,motə\'veʃən/', 'motivation', 1);
INSERT INTO `words` VALUES (2895, 'What do you suppose the killer’s motive was?', 'n. 动机，目的', '/\'məutiv | \'məʊtɪv | \'motɪv/', 'motive', 1);
INSERT INTO `words` VALUES (2896, 'an electric motor', 'n. 发动机；机动车', '/\'məutə | \'məʊtə | \'motɚ/', 'motor', 1);
INSERT INTO `words` VALUES (2897, 'Another method, used especially for figures, was to pour the clay into a mould.', 'n. 模子，模型; v. 浇铸', '/məuld | məʊld/', 'mould', 1);
INSERT INTO `words` VALUES (2898, 'He mounted his horse and rode on.', 'v. 登上，爬上; n. …山', '/maʊnt/', 'mount', 1);
INSERT INTO `words` VALUES (2899, 'the highest mountain in Austria', 'n. 山，山岳；山脉', '/ˈmauntin，ˈmaʊntən | ˈmaʊntən | ˈmaʊntn/', 'mountain', 1);
INSERT INTO `words` VALUES (2900, 'Hundreds of people gathered to mourn the slain president.', 'v. 哀痛，哀悼', '/mɔ:n, məun | mɔːn | mɔrn/', 'mourn', 1);
INSERT INTO `words` VALUES (2901, 'The cat laid a dead mouse at my feet.', 'n. 鼠，耗子', '/maus, mauz | maʊs/', 'mouse', 1);
INSERT INTO `words` VALUES (2902, 'He lifted his glass to his mouth.', 'n. 嘴，口，口腔', '/mauθ | maʊθ/', 'mouth', 1);
INSERT INTO `words` VALUES (2903, 'Michael told his story between mouthfuls.', 'n. 满口，一口，少量', '/\'mauθful | \'maʊθfʊl; -f(ə)l | \'maʊθ\'fʊl/', 'mouthful', 1);
