INSERT INTO `words` VALUES (2905, 'It\'s part of a broader nationalist movement that\'s gaining strength throughout the country.', 'n. 动作，活动；移动', '/\'mu:vmənt | \'muːvm(ə)nt | \'muvmənt/', 'movement', 1);
INSERT INTO `words` VALUES (2906, 'It was like one of those old John Wayne movies.', 'n. 电影；电影院', '/\'mu:vi | \'muːvɪ | \'muvi/', 'movie', 1);
