INSERT INTO `words` VALUES (2927, 'Note that different users of the system have different goals, and that these goals are often mutually exclusive.', 'adv. 互相地', '/\'mju:tʃuəli, -tjuəli | ˈmjuːtʃuəli | \'mjutʃuəli/', 'mutually', 1);
