INSERT INTO `words` VALUES (3020, 'She had no notion what he meant.', 'n. 概念， 观念； 意图， 想法， 念头', '/\'nəuʃn | \'noʃən/', 'notion', 1);
INSERT INTO `words` VALUES (3021, 'An adjective must agree with its noun in mumber and case.', 'n. 名词', '/naun | naʊn/', 'noun', 1);
INSERT INTO `words` VALUES (3022, 'The food she eats nourishes both her and the baby.', 'vt. 提供养分， 养育', '/\'nʌrɪʃ | \'nɜrɪʃ/', 'nourish', 1);
INSERT INTO `words` VALUES (3023, 'a novel by Jane Austen', 'n. 小说; adj. 新的', '/\'nɔvəl | \'nɒv(ə)l | ˈnɑːvl/', 'novel', 1);
INSERT INTO `words` VALUES (3024, 'And again in November.', 'n. 十一月', '/nəu\'vembə | nə(ʊ)\'vembə | no\'vɛmbɚ/', 'November', 1);
INSERT INTO `words` VALUES (3025, 'She\'s a widow now.', 'adv. 现在；立刻；于是', '/nau | naʊ/', 'now', 1);
INSERT INTO `words` VALUES (3026, 'Nowadays people are rarely shocked by the sex they see on television.', 'adv. 现今，现在', '/\'nauədeiz | \'naʊədeɪz | \'naʊədez/', 'nowadays', 1);
INSERT INTO `words` VALUES (3027, 'Nowhere is drug abuse more of a problem than in the US.', 'adv. 任何地方都不', '/\'nəuhwεə | \'nəʊhweə | \'no\'wɛr/', 'nowhere', 1);
INSERT INTO `words` VALUES (3028, 'France’s reliance on nuclear energy', 'adj. 原子核的；核心的', '/\'nju:kliə, \'nu:- | \'njuːklɪə | \'nuklɪɚ/', 'nuclear', 1);
INSERT INTO `words` VALUES (3029, 'Neutrons and protons are bound together in the nucleus of an atom.', 'n. 核，核心；(原子)核', '/\'nju:kliəs | \'njuːklɪəs | \'nuklɪəs/', 'nucleus', 1);
INSERT INTO `words` VALUES (3030, 'He could be a bit of a nuisance when he was drunk.', 'n. 讨厌的东西', '/\'nju:səns | \'njuːs(ə)ns | \'nusns/', 'nuisance', 1);
INSERT INTO `words` VALUES (3031, 'They wrote various numbers on a large sheet of paper.', 'n. 数，数字；号码', '/\'nʌmbə | \'nʌmbɚ/', 'number', 1);
INSERT INTO `words` VALUES (3032, 'Numerous attempts have been made to hide the truth.', 'adj. 为数众多的；许多', '/\'nju:mərəs | \'njuːm(ə)rəs | \'numərəs/', 'numerous', 1);
INSERT INTO `words` VALUES (3033, 'The nurse is coming to give you an injection.', 'n. 保姆；护士; v. 看护', '/nə:s | nɜːs | nɝs/', 'nurse', 1);
INSERT INTO `words` VALUES (3034, 'She puts her baby in this nursery and then goes back to work.', 'n. 托儿所；苗圃', '/\'nə:səri | \'nɜːs(ə)rɪ | \'nɝsəri/', 'nursery', 1);
INSERT INTO `words` VALUES (3035, 'a pine nut', 'n. 坚果，干果；螺母', '/nʌt/', 'nut', 1);
INSERT INTO `words` VALUES (3036, 'Wholemeal bread is more nutritious than white bread.', 'adj. 营养的', '/nju:\'triʃəs | njʊ\'trɪʃəs | nʊ\'trɪʃəs/', 'nutritious', 1);
INSERT INTO `words` VALUES (3037, 'nylon fabric', 'n. 尼龙，耐纶', '/\'nailɔn | \'naɪlɒn | \'naɪlɑn/', 'nylon', 1);
INSERT INTO `words` VALUES (3038, 'an oak door', 'n. 栎属植物；栎木', '/əuk | əʊk | ok/', 'oak', 1);
INSERT INTO `words` VALUES (3039, NULL, 'n. 浆，橹', '/ɔ:, əu | ɔː | ɔr/', 'oar', 1);
INSERT INTO `words` VALUES (3040, 'The little boy made no effort to obey.', 'v. 顺从; v. 服从', '/əu\'bei | ə(ʊ)\'beɪ | ə\'be/', 'obey', 1);
INSERT INTO `words` VALUES (3041, 'an everyday object such as a spoon', 'n. 物，物体；目的', '/\'ɔbdʒikt, -dʒekt, əb\'dʒekt | \'ɒbdʒɪkt; -dʒekt | \'ɑbdʒɛkt/', 'object', 1);
INSERT INTO `words` VALUES (3042, 'Her objection was that he was too young.', 'n. 反对', '/əb\'dʒekʃən, ɔb- | əb\'dʒekʃ(ə)n | əb\'dʒɛkʃən/', 'objection', 1);
INSERT INTO `words` VALUES (3043, 'Scientists need to be objective when doing research.', 'adj. 客观的；无偏见的', '/əb\'dʒektiv, ɔb- | əb\'dʒektɪv | əb\'dʒɛktɪv/', 'objective', 1);
INSERT INTO `words` VALUES (3044, 'Employers have an obligation to treat all employees equally.', 'n. 义务， 责任', '/ˌɒblɪ\'geɪʃn | ,ɑblɪ\'ɡeʃən/', 'obligation', 1);
INSERT INTO `words` VALUES (3045, 'The storm got worse and worse. Finally, I was obliged to abandon the car and continue on foot.', 'v. 迫使；施恩惠于', '/ə\'blaɪdʒ/', 'oblige', 1);
INSERT INTO `words` VALUES (3046, 'He spent two nights under close observation in hospital.', 'n. 注意；观察；观察力', '/,ɔbzə:\'veiʃən | ɒbzə\'veɪʃ(ə)n | ,ɑbzɚ\'veʃən/', 'observation', 1);
INSERT INTO `words` VALUES (3047, 'So far the ceasefire has been observed by both sides.', 'v. 遵守', '/əbˈzɜ:v | əb\'zɝv/', 'observe', 1);
INSERT INTO `words` VALUES (3048, 'political observers', 'n. 观察员，观测者', '/əb\'zə:və, ɔb- | əb\'zɜːvə | əb\'zɝvɚ/', 'observer', 1);
INSERT INTO `words` VALUES (3049, 'The tax puts obstacles in the way of companies trying to develop trade overseas.', 'n. 阻碍', '/\'ɔbstəkl | ˈɒbstəkl | \'ɑbstəkl/', 'obstacle', 1);
INSERT INTO `words` VALUES (3050, 'Evans was trying to obtain a false passport and other documents.', 'v. 获得', '/əb\'tein, ɔb- | əb\'teɪn | əb\'ten/', 'obtain', 1);
INSERT INTO `words` VALUES (3051, 'The obvious way of reducing pollution is to use cars less.', 'adj. 明显的，显而易见的', '/\'ɔbviəs | \'ɒbvɪəs | \'ɑbvɪəs/', 'obvious', 1);
INSERT INTO `words` VALUES (3052, 'We’re obviously going to need more help.', 'adv. 明显地，显然地', '/\'ɔbviəsli | \'ɒbvɪəslɪ | \'ɑbvɪəsli/', 'obviously', 1);
INSERT INTO `words` VALUES (3053, 'I often think fondly of an occasion some years ago in New Orleans.', 'n. 场合', '/ə\'keiʒən, əu- | əˈkeɪʒn | ə\'keʒn/', 'occasion', 1);
INSERT INTO `words` VALUES (3054, 'He made occasional visits to London.', 'adj. 偶然的；临时的', '/ə\'keiʒənəl, əu- | ə\'keɪʒ(ə)n(ə)l | ə\'keʒənl/', 'occasional', 1);
INSERT INTO `words` VALUES (3055, '...Very special books are still occasionally produced on vellum...', 'adv. 偶然；非经常地', NULL, 'occasionally', 1);
INSERT INTO `words` VALUES (3056, 'Please state your name, address and occupation.', 'n. 职业，工作', '/,ɔkju\'peiʃən | ˌɒkjuˈpeɪʃn | ,ɑkju\'peʃən/', 'occupation', 1);
INSERT INTO `words` VALUES (3057, 'Football occupies most of my leisure time.', 'v. 占领；占，占有', '/\'ɔkjupai | \'ɒkjʊpaɪ | \'ɑkjupaɪ/', 'occupy', 1);
INSERT INTO `words` VALUES (3058, 'A third of accidental deaths occur in the home.', 'v. 发生；出现，存在', '/ə\'kə: | ə\'kɜː | ə\'kɝ/', 'occur', 1);
INSERT INTO `words` VALUES (3059, 'Complaints seemed to be an everyday occurrence.', 'n. 发生，出现；事件', '/ə\'kə:rəns, -\'kʌ- | ə\'kʌr(ə)ns | ə\'kʌrəns/', 'occurrence', 1);
INSERT INTO `words` VALUES (3060, 'The cape extends far into the ocean.', 'n. 海洋；洋', NULL, 'ocean', 1);
INSERT INTO `words` VALUES (3061, 'The Mummies Of The World exhibition brings together a collection of mummies and related artefacts from South America, Europe, Asia, Oceania and Egypt.', 'n. 大洋洲', '/,əuʃi\'einiə; -\'ɑ:n-; -\'æn- | ,əʊsɪ\'ɑːnɪə; -ʃɪ- | ,oʃɪ\'ænɪə/', 'Oceania', 1);
INSERT INTO `words` VALUES (3062, 'Most seasonal hiring is done in early October.', 'n. 十月', '/ɔk\'təubə | ɒk\'təʊbə | ɑk\'tobɚ/', 'October', 1);
INSERT INTO `words` VALUES (3063, 'It was an odd thing to say.', 'adj. 奇数的；单只的', '/ɔd | ɒd | ɑd/', 'odd', 1);
INSERT INTO `words` VALUES (3064, '...the lingering odour of car exhaust.', 'n. 气味，香气；味道', '/\'əudə | \'əʊdə/', 'odour', 1);
INSERT INTO `words` VALUES (3065, 'the back of the house', 'prep. …的；由于', '/ɒv; (ə)v | ʌv; əv/', 'of', 1);
INSERT INTO `words` VALUES (3066, 'How are you off for sports equipment? (= do you have enough? )', 'adv. (离)开；(停)止', '/ɔ:f, ɔf | ɒf | ɔf/', 'off', 1);
INSERT INTO `words` VALUES (3067, 'His remarks deeply offended many Scottish people.', 'v. 冒犯; v. 犯过错', '/ə\'fend | ə\'fɛnd/', 'offend', 1);
INSERT INTO `words` VALUES (3068, 'These efforts have led to a growing confidence among the public that corruption is a serious punishable offense in Albania.', 'n. 过错，犯罪', '/ə\'fens | ə\'fɛns/', 'offense', 1);
INSERT INTO `words` VALUES (3069, 'I found her remarks deeply offensive.', 'adj. 冒犯的，无礼的；进攻的，攻击性的; n. 进攻， 攻势', '/ə\'fensɪv | ə\'fɛnsɪv/', 'offensive', 1);
INSERT INTO `words` VALUES (3070, 'A number of groups offer their services free of charge.', 'v. 提供；提出; n. 提供', '/ˈɒfə | \'ɒfə | \'ɔfɚ/', 'offer', 1);
INSERT INTO `words` VALUES (3071, 'The department occupies an office just a mile from the White House.', 'n. 办公室；处，局，社', '/\'ɔfis, \'ɔ:- | \'ɒfɪs | \'ɔfɪs/', 'office', 1);
INSERT INTO `words` VALUES (3072, 'a commanding officer of the SAS', 'n. 官员；干事；军官', '/\'ɔfisə, \'ɔ:- | \'ɒfɪsə | \'ɔfɪsɚ/', 'officer', 1);
INSERT INTO `words` VALUES (3073, '...Kodak\'s decision not to pursue the role of official film for the 1984Los Angeles Olympics was a major miscalculation...', 'adj. 官员的；官方的', '/ə\'fɪʃl | əˈfɪʃəl; oʊˈfɪʃəl/', 'official', 1);
INSERT INTO `words` VALUES (3074, 'She often works at the weekend.', 'adv. 经常，常常', '/\'ɔfən, \'ɔftən, \'ɔ:- | \'ɒf(tə)n | \'ɔf(tə)n; \'ɑf(tə)n/', 'often', 1);
INSERT INTO `words` VALUES (3075, 'Oh, look, I think that’s Harry over there.', 'int. 嗬，哦，唉呀', '/əu | əʊ | o/', 'oh', 1);
INSERT INTO `words` VALUES (3076, 'a rise in the price of oil', 'n. 油；石油; v. 加油于', '/ɔil | ɒɪl | ɔɪl/', 'oil', 1);
INSERT INTO `words` VALUES (3077, NULL, '(缩作OK)a&ad. 对，好', '/\'əu\'kei, ,əu\'kei, \'əukei | \'əʊ\'keɪ | ,o\'kɛi/', 'okay', 1);
INSERT INTO `words` VALUES (3078, 'How old are you?', 'adj. 老的；…岁的', '/əuld | əʊld | old/', 'old', 1);
INSERT INTO `words` VALUES (3079, 'Please don’t omit any details, no matter how trivial they may seem.', 'v. 省略，省去；遗漏', '/əu\'mit | ə(ʊ)\'mɪt | ə\'mɪt/', 'omit', 1);
INSERT INTO `words` VALUES (3080, 'I wanted to punch him on the nose.', 'prep. 在…上；在…旁', '/ɔn, ɔ:n, ən, n | ɒn | ɑn/', 'on', 1);
INSERT INTO `words` VALUES (3081, 'I’ve only met her once.', 'adv. 一次；曾经; n. 一次', '/wʌns/', 'once', 1);
INSERT INTO `words` VALUES (3082, 'They had one daughter.', 'num. 一; pron. 一个人', '/wʌn/', 'one', 1);
INSERT INTO `words` VALUES (3083, 'It is only through study that one really begins to know oneself.', 'pron. 自己；亲自', '/wʌn\'self | wʌn\'sɛlf/', 'oneself', 1);
INSERT INTO `words` VALUES (3084, 'Chop the onions finely.', 'n. 洋葱，洋葱头', '/\'ʌnjən/', 'onion', 1);
INSERT INTO `words` VALUES (3085, 'Naomi was only 17 when she got married.', 'adv. 只，仅仅; adj. 唯一的', '/\'əunli | \'əʊnlɪ | \'onli/', 'only', 1);
INSERT INTO `words` VALUES (3086, 'She watched him walk onto the platform.', 'prep. 到…上', '/\'ɒntuː | ˈɑnˌtu, -tə, ˈɔn-/', 'onto', 1);
INSERT INTO `words` VALUES (3087, 'He threw the door open and ran down the stairs.', 'adj. 开的；开放的; v. 开', '/\'əupən | \'əʊp(ə)n | \'opən/', 'open', 1);
INSERT INTO `words` VALUES (3088, 'the opening match of the season', 'adj. 开始的; n. 开始', '/\'əupəniŋ | \'əʊp(ə)nɪŋ | \'opənɪŋ/', 'opening', 1);
INSERT INTO `words` VALUES (3089, 'We go to the opera (= go to a performance of opera ) regularly.', 'n. 歌剧', '/\'ɔpərə | \'ɒp(ə)rə | \'ɑprə/', 'opera', 1);
INSERT INTO `words` VALUES (3090, 'The Lewis family operated a number of boats on the canal.', 'v. 操作；施行手术', '/\'ɒpəreɪt | \'ɑpə\'ret/', 'operate', 1);
INSERT INTO `words` VALUES (3091, 'The UN rescue operation started shortly after dawn.', 'n. 手术；行动', '/,ɔpə\'reiʃən | ˌɒpəˈreɪʃn | ,ɑpə\'reʃən/', 'operation', 1);
INSERT INTO `words` VALUES (3092, 'The boat should be operational by this afternoon.', 'adj. 操作上的；可使用的', '/,ɔpə\'reiʃənəl | ɒpə\'reɪʃ(ə)n(ə)l | \'ɑpə\'reʃənl/', 'operational', 1);
INSERT INTO `words` VALUES (3093, 'Hello, operator? Could you put me through to Room 31?', 'n. 操作人员，接线员', '/\'ɔpəreitə | \'ɒpəreɪtə | \'ɑpəretɚ/', 'operator', 1);
INSERT INTO `words` VALUES (3094, 'When choosing an insurance policy it’s best to get an independent opinion.', 'n. 意见，看法，主张', '/ə\'pinjən | ə\'pɪnjən/', 'opinion', 1);
INSERT INTO `words` VALUES (3095, 'Graf’s opponent in today’s final will be Sukova.', 'n. 对手', '/ə\'pəunənt | ə\'pəʊnənt | ə\'ponənt/', 'opponent', 1);
INSERT INTO `words` VALUES (3096, 'There are fewer opportunities for new graduates this year.', 'n. 机会，良机', '/,ɔpə\'tju:niti | ɒpə\'tjuːnɪtɪ | ˌɑpɚˈtunɪti, -ˈtju-/', 'opportunity', 1);
INSERT INTO `words` VALUES (3097, 'Congress is continuing to oppose the President’s health care budget.', 'v. 反对；反抗', '/ə\'pəuz | ə\'pəʊz | ə\'poz/', 'oppose', 1);
INSERT INTO `words` VALUES (3098, 'I thought the medicine would make him sleep, but it had the opposite effect.', 'adj. 相反的', '/\'ɔpəzit, -sit | ˈɔpəzɪt | ˈɑpəzɪt; ˈɑpəsɪt/', 'opposite', 1);
INSERT INTO `words` VALUES (3099, 'native tribes oppressed by the authorities', 'v. 压迫，压制；压抑', '/ə\'pres | ə\'prɛs/', 'oppress', 1);
INSERT INTO `words` VALUES (3100, 'microscopes and other optical instruments', 'adj. 眼的；光学的', '/\'ɔptikəl | \'ɒptɪk(ə)l | \'ɑptɪkl/', 'optical', 1);
INSERT INTO `words` VALUES (3101, 'Andrew took a more optimistic view.', 'adj. 乐观的', '/,ɔpti\'mistik | ˌɒptɪˈmɪstɪk | ,ɑptɪ\'mɪstɪk/', 'optimistic', 1);
INSERT INTO `words` VALUES (3102, 'There are a number of options available.', 'n. 选择', '/\'ɔpʃən | \'ɒpʃ(ə)n | \'ɑpʃən/', 'option', 1);
INSERT INTO `words` VALUES (3103, 'three optional courses', 'adj. 可以任意选择的', '/\'ɔpʃənəl | \'ɒpʃ(ə)n(ə)l | \'ɑpʃənl/', 'optional', 1);
INSERT INTO `words` VALUES (3104, 'Shall we go out to the cinema or stay at home?', 'conj. 或，或者；即', '/ɔ:, ə | ɔː | ɔr/', 'or', 1);
INSERT INTO `words` VALUES (3105, 'oral history', 'adj. 口头的；口的', '/\'ɔ:rəl, \'ɔ- | \'ɔːr(ə)l | \'ɔrəl/', 'oral', 1);
INSERT INTO `words` VALUES (3106, 'orange juice', 'n. 橙(树)；柑(树)', '/\'ɔrindʒ, \'ɔ:- | \'ɒrɪn(d)ʒ | \'ɔrɪndʒ/', 'orange', 1);
INSERT INTO `words` VALUES (3107, 'Mars and Earth have orbits which change with time.', 'n. 运行轨道; v. 环绕', '/\'ɔ:bit | \'ɔːbɪt | \'ɔrbɪt/', 'orbit', 1);
INSERT INTO `words` VALUES (3108, 'He directed an orchestra.', 'n. 管弦乐队', '/\'ɔːkɪstrə | \'ɔrkɪstrə/', 'orchestra', 1);
INSERT INTO `words` VALUES (3109, 'There seemed to be no logical order to the sections.', 'n. 次序；整齐; v. 命令', '/\'ɔ:də | \'ɔːdə | \'ɔrdɚ/', 'order', 1);
INSERT INTO `words` VALUES (3110, 'She needs to organize her ideas in a more orderly way.', 'adj. 整洁的；有秩序的', '/\'ɔ:dəli | \'ɔːd(ə)lɪ | \'ɔrdɚli/', 'orderly', 1);
INSERT INTO `words` VALUES (3111, 'It’s just an ordinary camera.', 'adj. 平常的；平凡的', '/\'ɔ:dinəri, -neri- | \'ɔːdɪn(ə)rɪ; -d(ə)n- | \'ɔrdnɛri/', 'ordinary', 1);
INSERT INTO `words` VALUES (3112, 'iron ore', 'n. 矿，矿石，矿砂', '/ɔ: | ɔː | ɔr/', 'ore', 1);
INSERT INTO `words` VALUES (3113, 'the liver, heart, and other internal organs', 'n. 器官', '/\'ɔ:ɡən | \'ɔrɡən/', 'organ', 1);
INSERT INTO `words` VALUES (3114, 'Organic farming is better for the environment.', 'adj. 有机体的；器官的', '/ɔ:\'ɡænik | ɔː\'gænɪk | ɔr\'gænɪk/', 'organic', 1);
INSERT INTO `words` VALUES (3115, 'All living organisms have to adapt to changes in environmental conditions.', 'n. 生物体；有机体', '/\'ɔ:ɡənizəm | \'ɔːg(ə)nɪz(ə)m | \'ɔrɡənɪzəm/', 'organism', 1);
INSERT INTO `words` VALUES (3116, 'The public expect high standards from any large organization.', 'n. 组织；团体，机构', '/,ɔ:ɡənai\'zeiʃən, -ni\'z- | ˌɔːɡənaɪ\'zeɪʃn | ,ɔrɡənə\'zeʃən/', 'organization', 1);
INSERT INTO `words` VALUES (3117, 'The course was organized by a training company.', 'v. 组织，编组', '/\'ɔ:ɡənaiz | ˈɔ:gənaɪz | ɔrɡənˌaɪz/', 'organize', 1);
INSERT INTO `words` VALUES (3118, 'a beautiful oriental rug', 'adj. 东方的；东方国家的', '/,ɔ:ri\'entəl, ,əu- | ɔːrɪ\'ent(ə)l; ɒr- | ,orɪ\'ɛntəl/', 'oriental', 1);
INSERT INTO `words` VALUES (3119, 'The tradition has its origins in the Middle Ages.', 'n. 起源', '/\'ɔridʒin, \'ɔ:- | \'ɒrɪdʒɪn | \'ɔrɪdʒɪn/', 'origin', 1);
INSERT INTO `words` VALUES (3120, 'The land was returned to its original owner.', 'adj. 原始的，最初的', '/ə\'ridʒənəl | ə\'ridʒənl | ə\'rɪdʒənl/', 'original', 1);
INSERT INTO `words` VALUES (3121, 'How did the plan originate?', 'v. 开始', '/ə\'ridʒəneit | ə\'rɪdʒɪneɪt | əˈrɪdʒəˌnet/', 'originate', 1);
INSERT INTO `words` VALUES (3122, 'a shelf covered with books and ornaments', 'n. 装饰物；装饰', '/\'ɔ:nəmənt, \'ɔ:nəment | \'ɔːnəm(ə)nt | \'ɔrnəmənt/', 'ornament', 1);
INSERT INTO `words` VALUES (3123, 'The war has left thousands of children as orphans.', 'n. 孤儿', '/\'ɔ:fən | \'ɔːf(ə)n | \'ɔrfn/', 'orphan', 1);
INSERT INTO `words` VALUES (3124, 'They were just like any other young couple.', 'adj. 另外的；其余的', '/\'ʌðə | \'ʌðɚ/', 'other', 1);
INSERT INTO `words` VALUES (3125, 'You’ll have to go now, otherwise you’ll miss your bus.', 'adv. 另外；要不然', '/\'ʌðəwaɪz | \'ʌðɚwaɪz/', 'otherwise', 1);
INSERT INTO `words` VALUES (3126, '...You ought to try to reserve the “Super Saver” seats...', 'v. aux应当，应该', '/ɔːt | ɔt/', 'ought', 1);
INSERT INTO `words` VALUES (3127, 'One ounce of almonds contains nearly half the recommended daily amount.', 'n. 盎司，英两', '/auns | aʊns/', 'ounce', 1);
INSERT INTO `words` VALUES (3128, 'They partook of our triumph.', 'pron. 我们的', '/aʊə | aʊr/', 'our', 1);
INSERT INTO `words` VALUES (3129, 'I’ll show you to your room. Ours is next door.', 'pron. 我们的', '/aʊəz | ɑrz/', 'ours', 1);
INSERT INTO `words` VALUES (3130, 'We prepared ourselves for the long journey ahead.', 'pron. 我们自己', '/aʊə\'selvz | ɑr\'sɛlvz/', 'ourselves', 1);
INSERT INTO `words` VALUES (3131, 'She opened her suitcase and took out a pair of shoes.', 'adv. 出，在外；现出来', '/aut | aʊt/', 'out', 1);
INSERT INTO `words` VALUES (3132, 'People who had heard the evidence at the trial were surprised at the outcome.', 'n. 结果', '/\'autkʌm | \'aʊtkʌm | \'aʊt\'kʌm/', 'outcome', 1);
INSERT INTO `words` VALUES (3133, 'a huge outdoor market', 'adj. 户外的，室外的', '/\'əutdɔ: | \'aʊtdɔː | \'aʊt\'dɔr/', 'outdoor', 1);
