INSERT INTO `words` VALUES (3607, 'The book will appeal to young readers.', 'n. 读者；读物，读本', '/\'ri:də | \'riːdə | \'ridɚ/', 'reader', 1);
INSERT INTO `words` VALUES (3608, 'Boats are readily available to visitors.', 'adv. 乐意地， 欣然地； 容易地； 很快地， 立即', '/\'redɪli | \'rɛdɪli/', 'readily', 1);
INSERT INTO `words` VALUES (3609, 'She loves reading.', 'n. 读，阅读；读书', '/\'ri:diŋ | \'riːdɪŋ | \'ridɪŋ/', 'reading', 1);
INSERT INTO `words` VALUES (3610, 'Come on. Aren’t you ready yet?', 'adj. 准备好的；愿意的', '/\'redi | \'redɪ | \'rɛdi/', 'ready', 1);
INSERT INTO `words` VALUES (3611, 'There is a real danger that the disease might spread.', 'adj. 真的；现实的', '/\'riəl, ri:l | riːl | \'riəl/', 'real', 1);
INSERT INTO `words` VALUES (3612, 'Is this a realistic target?', 'adj. 现实的，实际的', '/,riə\'listik, ,ri:- | ˌri:əˈlɪstɪk | ,riə\'lɪstɪk/', 'realistic', 1);
INSERT INTO `words` VALUES (3613, 'the distinction between fantasy and reality', 'n. 现实；真实', '/ri\'æləti, ri:- | rɪ\'ælɪtɪ | rɪ\'æləti/', 'reality', 1);
INSERT INTO `words` VALUES (3614, 'It took us a while to realize the extent of the tragedy.', 'v. 实现；认识到', '/\'riːəlaɪz | rɪəˌlaɪz/', 'realize', 1);
INSERT INTO `words` VALUES (3615, '...and you really felt anything was possible...', 'adv. 真正地；实在', NULL, 'really', 1);
