INSERT INTO `words` VALUES (3617, 'Carole was left to bring up the rear.', 'n. 后部，后面；背面', '/riə | rɪə | rɪr/', 'rear', 1);
INSERT INTO `words` VALUES (3618, 'She set about rearranging the furniture in the living room.', 'v. 重新安排', '/,ri:ə\'reindʒ | ˌri:ə\'reɪndʒ | ,riə\'rendʒ/', 'rearrange', 1);
INSERT INTO `words` VALUES (3619, 'She has reason to feel guilty.', 'n. 理由；理性; v. 推理', '/\'ri:zən | \'riːz(ə)n | ˈrizən/', 'reason', 1);
INSERT INTO `words` VALUES (3620, 'a reasonable request', 'adj. 合情合理的；公道的', '/\'ri:zənəbl | \'riːz(ə)nəb(ə)l | \'riznəbl/', 'reasonable', 1);
INSERT INTO `words` VALUES (3621, 'This has caused us to reassess the way we approach our planning.', 'v. 重新评估', '/,ri:ə\'ses | ˌri:əˈses | \'riə\'sɛs/', 'reassess', 1);
INSERT INTO `words` VALUES (3622, 'Voters rebelled against high property taxes.', 'v. 造反; n. 造反者', '/\'rebəl, ri\'bel | \'reb(ə)l | rɪ\'bɛl/', 'rebel', 1);
INSERT INTO `words` VALUES (3623, 'The church was completely rebuilt in the last century.', 'v. 重建， 改造； 复原', '/ˌriː\'bɪld | ,ri\'bɪld/', 'rebuild', 1);
INSERT INTO `words` VALUES (3624, 'You don’t happen to recall his name, do you?', 'v. 回想；叫回；收回', '/ri\'kɔ:l, \'ri:kɔ:l | rɪ\'kɔːl | \'rikɔl/', 'recall', 1);
INSERT INTO `words` VALUES (3625, 'Keep your receipt in case you want to bring it back.', 'n. 收到；收条，收据', '/ri\'si:t | rɪ\'siːt | rɪ\'sit/', 'receipt', 1);
INSERT INTO `words` VALUES (3626, 'All the children will receive a small gift.', 'v. 收到；得到；接待', '/ri\'si:v | rɪ\'siːv | rɪ\'siv/', 'receive', 1);
