INSERT INTO `words` VALUES (3628, 'Irving’s most recent book', 'adj. 新近的，最近的', '/\'ri:sənt | \'riːs(ə)nt | \'risnt/', 'recent', 1);
INSERT INTO `words` VALUES (3629, 'He has recently been promoted to Assistant Manager.', 'adv. 最近，新近', '/\'ri:səntli | \'riːsntlɪ | \'risntli/', 'recently', 1);
INSERT INTO `words` VALUES (3630, 'She was unsure of her reception after everything that had happened.', 'n. 接待', '/ri\'sepʃən | rɪˈsepʃn | rɪ\'sɛpʃən/', 'reception', 1);
INSERT INTO `words` VALUES (3631, 'the economic recession of the early 1980s', 'n. 衰退', '/ri\'seʃən | rɪ\'sɛʃən/', 'recession', 1);
INSERT INTO `words` VALUES (3632, 'The device can recharge a battery in about 25 minutes.', 'v. 再充电', '/ri:\'tʃɑ:dʒ, \'ri:tʃɑ:dʒ | ˌri:\'tʃɑ:dʒ/', 'recharge', 1);
INSERT INTO `words` VALUES (3633, '‘There’s nothing we can do about it.’ ‘You reckon (= used to express doubt or disagreement ) ?’', 'vt. 认为， 估计； 指望， 盼望； 测算， 测量', '/\'rekən | \'rɛkən/', 'reckon', 1);
INSERT INTO `words` VALUES (3634, 'He stared at her, but there was no sign of recognition .', 'n. 认出，识别；承认', '/,rekəg\'niʃən | rekəg\'nɪʃ(ə)n | ,rɛkəɡ\'nɪʃən/', 'recognition', 1);
INSERT INTO `words` VALUES (3635, 'I didn’t recognize you in your uniform.', 'v. 认识，认出；承认', '/\'rekəɡnaiz | \'rekəɡnaɪz | ˈrɛkəɡˌnaɪz/', 'recognize', 1);
INSERT INTO `words` VALUES (3636, 'Doctors strongly recommend that fathers should be present at their baby’s birth.', 'v. 推荐，劝告，使受欢迎', '/,rekə\'mend | \'rɛkə\'mɛnd/', 'recommend', 1);
