INSERT INTO `words` VALUES (3638, 'According to official records, five people were killed last year near that road junction.', 'n. 记录；履历; v. 记录', '/ri\'kɔ:d, \'rekɔ:d | (for v.)rɪˈkɔːd; (for n.) ˈrekɔːd | (for v.) rɪˈkɔrd; (for n. adj.) ˈrɛkɚd/', 'record', 1);
INSERT INTO `words` VALUES (3639, 'Rodney put the recorder on the desk top and pushed the play button.', 'n. 记录者；录音机', '/ri\'kɔ:də | rɪ\'kɔːdə | rɪ\'kɔrdɚ/', 'recorder', 1);
INSERT INTO `words` VALUES (3640, 'After a few days of fever, she began to recover.', 'v. 恢复，重新获得', '/ri\'kʌvə | rɪ\'kʌvə(r) | rɪ\'kʌvɚ/', 'recover', 1);
