INSERT INTO `words` VALUES (3643, '...parks and other recreational facilities.', 'adj. 休养的； 娱乐的', '/ˌrekri\'eɪʃənl | ,rɛkri\'eʃənəl/', 'recreational', 1);
INSERT INTO `words` VALUES (3644, 'We’re having difficulty recruiting enough qualified staff.', 'v. 招募，吸收; n. 新兵，新成员', '/ri\'kru:t | rikru:t | rɪ\'krut/', 'recruit', 1);
