INSERT INTO `words` VALUES (3646, 'We painted the door bright red .', 'adj. 红色的; n. 红色', '/red | rɛd/', 'red', 1);
INSERT INTO `words` VALUES (3647, 'The governor announced a new plan to reduce crime.', 'v. 减少', '/ri\'dju:s, -\'du:s | rɪ\'djuːs | rɪ\'dʊs/', 'reduce', 1);
INSERT INTO `words` VALUES (3648, 'strategies for noise reduction', 'n. 减少，减小，缩减', '/rɪ\'dʌkʃ(ə)n | rɪ\'dʌkʃən/', 'reduction', 1);
INSERT INTO `words` VALUES (3649, 'In his speech, he referred to a recent trip to Canada.', 'v. 使求助于; v. 谈到', '/ri\'fə: | rɪ\'fɜː | rɪ\'fɝ/', 'refer', 1);
INSERT INTO `words` VALUES (3650, '...a reference from the Koran.', 'n. 参考；出处；提及', '/\'refərəns | \'ref(ə)r(ə)ns | \'rɛfrəns/', 'reference', 1);
