INSERT INTO `words` VALUES (3654, 'Maxwell equations: Lorentz force, plane electromagnetic waves, radiation, light waves, reflexion, refraction, Huyghens principle, diffraction, interference phenomena.', 'n. 反射；映象；反映', '/ri\'flekʃən | rɪ\'flekʃ(ə)n | rɪ\'flɛkʃən/', 'reflexion', 1);
INSERT INTO `words` VALUES (3655, 'plans to radically reform the tax system', 'vt&n. 改革，改良', '/ri\'fɔ:m | rɪ\'fɔːm | rɪ\'fɔrm/', 'reform', 1);
