INSERT INTO `words` VALUES (3659, '...but that noise in your refrigerator doesn’t sound right...', 'n. 冰箱，冷藏库', '/ri\'fridʒəreitə, ri:- | rɪ\'frɪdʒəreɪtə | rɪ\'frɪdʒəretɚ/', 'refrigerator', 1);
INSERT INTO `words` VALUES (3660, 'The plane was refuelled in Dubai.', 'v. （给）加油，加燃料', '/,ri:\'fjuəl | ˌri:\'fju:əl | ri\'fjʊəl/', 'refuel', 1);
