INSERT INTO `words` VALUES (3668, 'Have you signed the hotel register ?', 'n&vt. 登记，注册', '/\'redʒistə | \'redʒɪstə | \'rɛdʒɪstɚ/', 'register', 1);
INSERT INTO `words` VALUES (3669, 'We regret any inconvenience caused to our customers.', 'v. 懊悔；抱歉; n. 懊悔', '/ri\'ɡret | rɪ\'gret | rɪ\'ɡrɛt/', 'regret', 1);
