INSERT INTO `words` VALUES (3678, 'He’s never had a sexual relationship before.', 'n. 关系，联系', '/ri\'leiʃənʃip | rɪ\'leɪʃ(ə)nʃɪp | rɪ\'leʃən\'ʃɪp/', 'relationship', 1);
