INSERT INTO `words` VALUES (3707, 'Therefore, lots of pavements need to repair in large. scale even repave wholly after using a long time, which will bring large numbers of waste asphalt mixture.', 'v. 再铺，重新铺砌', '/ri:\'peiv | ri:\'peɪv/', 'repave', 1);
