INSERT INTO `words` VALUES (3717, 'a union representative', 'n. 代表', '/,repri\'zentətiv | ˌreprɪˈzentətɪv | \'rɛprɪ\'zɛntətɪv/', 'representative', 1);
INSERT INTO `words` VALUES (3718, 'Klimt’s artwork is reproduced in this exquisite book.', 'v. 复制, 再生', '/,ri:prə\'dju:s | riːprə\'djuːs | ,riprə\'dus/', 'reproduce', 1);
INSERT INTO `words` VALUES (3719, 'the human reproductive system', 'adj. 生殖的，再生的', '/,ri:prə\'dʌktiv | ˌri:prəˈdʌktɪv | ,riprə\'dʌktɪv/', 'reproductive', 1);
INSERT INTO `words` VALUES (3720, 'the former Federal Republic of Germany', 'n. 共和国，共和政体', '/ri\'pʌblik | rɪ\'pʌblɪk/', 'republic', 1);
INSERT INTO `words` VALUES (3721, 'Lower taxes made Republican voters happier with their party.', 'adj. 共和政体的；共和党的; n. 共和党人', '/rɪ\'pʌblɪkən/', 'republican', 1);
INSERT INTO `words` VALUES (3722, 'Alice Munro has a reputation for being a very depressing writer.', 'n. 名气，名声，名誉', '/,repju\'teiʃən | ,rɛpju\'teʃən/', 'reputation', 1);
