INSERT INTO `words` VALUES (3735, 'He resisted pressure to resign.', 'v. 抵抗，抗拒', '/ri\'zist | rɪ\'zɪst/', 'resist', 1);
INSERT INTO `words` VALUES (3736, 'disease resistance', 'n. 抵制, 抵抗力', '/ri\'zistəns | rɪ\'zɪst(ə)ns | rɪ\'zɪstəns/', 'resistance', 1);
