INSERT INTO `words` VALUES (3738, 'a resolution calling for a ban on dumping nuclear waste', 'n. 坚决，坚定；决定', '/,rezə\'lu:ʃən, -,lju:- | rezə\'luːʃ(ə)n | ,rɛzə\'luʃən/', 'resolution', 1);
INSERT INTO `words` VALUES (3739, 'Barnet was desperate for money to resolve his financial problems.', 'v. 解决，下决心', '/ri\'zɔlv | rɪ\'zɒlv | rɪ\'zɑlv/', 'resolve', 1);
INSERT INTO `words` VALUES (3740, 'His punishing work schedule had made him resort to drugs.', 'vi&n. 求助，凭借;诉诸于', '/ri\'zɔ:t | rɪ\'zɔːt | rɪ\'zɔrt/', 'resort', 1);
INSERT INTO `words` VALUES (3741, 'Canada’s vast mineral resources', 'n. 资源； 财力； 应付办法， 谋略', '/rɪ\'sɔːs; rɪ\'zɔːs | \'risɔrs/', 'resource', 1);
INSERT INTO `words` VALUES (3742, 'a woman who is energetic and resourceful', 'adj. 机智的；资源丰富的', '/ri\'sɔ:sful, -\'zɔ:-, \'ri:s, \'ri:z- | rɪ\'sɔːsfl | rɪ\'sɔrsfl/', 'resourceful', 1);
INSERT INTO `words` VALUES (3743, 'The boys showed a complete lack of respect for authority.', 'n. 尊敬；尊重；问候；方面; vt. 尊敬； 尊重', '/rɪ\'spekt | rɪ\'spɛkt/', 'respect', 1);
INSERT INTO `words` VALUES (3744, 'They listened in respectful silence.', 'adj. 有礼貌的，尊重的', '/ri\'spektful | rɪˈspektfl | rɪ\'spɛktfəl/', 'respectful', 1);
INSERT INTO `words` VALUES (3745, 'We all went back to our respective homes to wait for news.', 'adj. 各自的，各个的', '/ri\'spektiv | rɪ\'spektɪv | rɪ\'spɛktɪv/', 'respective', 1);
INSERT INTO `words` VALUES (3746, 'The cups and saucers cost £5 and £3 respectively.', 'adv. 各自地', '/ri\'spektivli | rɪ\'spɛktɪvli/', 'respectively', 1);
