INSERT INTO `words` VALUES (3748, 'Only 62 percent of respondents said they were satisfied.', 'n. 回答者； 响应者； 被告', '/rɪ\'spɒndənt | rɪ\'spɑndənt/', 'respondent', 1);
INSERT INTO `words` VALUES (3749, 'His immediate response was one of disbelief.', 'n. 反应', '/ri\'spɔns | rɪˈspɒns | rɪ\'spɑns/', 'response', 1);
INSERT INTO `words` VALUES (3750, 'Kelly’s promotion means more money and more responsibility.', 'n. 责任', '/ri.spɔnsə\'biliti | ri,spɔnsə\'biliti | rɪˌspɑːnsəˈbɪləti/', 'responsibility', 1);
INSERT INTO `words` VALUES (3751, 'We are determined to bring the people responsible to justice.', 'adj. 负责的，有责任的', '/ri\'spɔnsəbl | rɪ\'spɑnsəbl/', 'responsible', 1);
INSERT INTO `words` VALUES (3752, 'a car with highly responsive steering', 'adj. 响应的； 敏感的， 易受影响的', '/rɪ\'spɒnsɪv | rɪ\'spɑnsɪv/', 'responsive', 1);
INSERT INTO `words` VALUES (3753, 'After a few weeks in Marseille, I grew restless and decided to move on.', 'adj. 不安定的，焦虑的', '/\'restlis | ˈrestləs | \'rɛstləs/', 'restless', 1);
