INSERT INTO `words` VALUES (4161, 'Dr. Hanson is in surgery.', 'n. 外科，外科手术', '/\'sə:dʒəri | \'sɜːdʒ(ə)rɪ | \'sɝdʒəri/', 'surgery', 1);
