INSERT INTO `words` VALUES (4311, 'Will someone take out the trash (= take it outside the house ) ?', 'n. 垃圾，废物；拙劣的文学作品；没用的人，社会渣滓，败类; vt. 捣毁， 破坏', '/træʃ/', 'trash', 1);
INSERT INTO `words` VALUES (4312, 'The waiter brought drinks on a tray.', 'n. (浅)盘，托盘，碟', '/trei | treɪ | tre/', 'tray', 1);
