INSERT INTO `words` VALUES (4314, 'sewage treated so that it can be used as fertilizer', 'v. 对待；处理; n. 款待', '/tri:t | triːt | trit/', 'treat', 1);
INSERT INTO `words` VALUES (4315, 'Just lately, Kyra has been giving me the silent treatment (= refusing to speak to me because she is angry with me ) .', 'n. 治疗，对待', '/\'tri:tmənt | ˈtri:tmənt | \'tritmənt/', 'treatment', 1);
INSERT INTO `words` VALUES (4316, 'Both sides have agreed to sign the treaty .', 'n. 条约；协议，协定', '/\'tri:ti | \'triːtɪ | \'triti/', 'treaty', 1);
INSERT INTO `words` VALUES (4317, 'His lip started to tremble and then he started to cry.', 'v. 颤抖', '/\'trembl | \'trɛmbl/', 'tremble', 1);
INSERT INTO `words` VALUES (4318, 'Suddenly, there was a tremendous bang, and the whole station shook.', 'adj. 巨大的', '/trəˈmendəs | trə\'mɛndəs/', 'tremendous', 1);
INSERT INTO `words` VALUES (4319, 'He characterized briefly the main trend in the world today.', 'v. 伸向；倾向; n. 倾向', '/trend | trɛnd/', 'trend', 1);
INSERT INTO `words` VALUES (4320, 'The trial is due to start next week.', 'n. 试，试验；审判', '/\'traiəl | \'traɪəl/', 'trial', 1);
INSERT INTO `words` VALUES (4321, 'a triangle of land', 'n. 三角(形)', '/\'traiæŋɡl | \'traɪæŋg(ə)l | \'traɪæŋɡl/', 'triangle', 1);
INSERT INTO `words` VALUES (4322, 'Pretending he doesn’t remember is an old trick of his.', 'n. 诡计；窍门; v. 哄骗', '/trik | trɪk/', 'trick', 1);
INSERT INTO `words` VALUES (4323, 'The assassination triggered off a wave of rioting.', 'v. 引发，引起', '/\'triɡə | \'trɪgə | \'trɪɡɚ/', 'trigger', 1);
INSERT INTO `words` VALUES (4324, 'trim suburban gardens', 'adj. 整齐的; v. 使整齐', '/trim | trɪm/', 'trim', 1);
INSERT INTO `words` VALUES (4325, 'Winning the championship is a great personal triumph .', 'n. 胜利', '/\'traiəmf, -ʌmf | \'traɪʌmf/', 'triumph', 1);
INSERT INTO `words` VALUES (4326, 'Both countries agreed to withdraw their troops .', 'n. 军队；一群，大量', '/tru:p | truːp | trʊp/', 'troop', 1);
