INSERT INTO `words` VALUES (4328, 'a troublesome child', 'adj. 令人烦恼的；麻烦的', '/\'trʌblsəm | \'trʌb(ə)ls(ə)m/', 'troublesome', 1);
INSERT INTO `words` VALUES (4329, 'His work is truly original.', 'adv. 真正地； 忠实地', '/\'truːli | ˈtruːli/', 'truly', 1);
INSERT INTO `words` VALUES (4330, 'I played the trumpet in the school orchestra.', 'n. 喇叭，小号', '/\'trʌmpit | \'trʌmpɪt/', 'trumpet', 1);
INSERT INTO `words` VALUES (4331, 'He left his bicycle leaning against a tree trunk .', 'n. 树干；大衣箱，皮箱', '/trʌŋk/', 'trunk', 1);
INSERT INTO `words` VALUES (4332, 'At first there was a lack of trust between them.', 'n. 信任; v. 相信；委托', '/\'trʌst | trʌst/', 'trust', 1);
