INSERT INTO `words` VALUES (4335, 'I had to have extra tuition in maths.', 'n. 学费', '/tju:\'iʃən | tjuˈɪʃn | tʊ\'ɪʃən/', 'tuition', 1);
INSERT INTO `words` VALUES (4336, 'The tumor will soon be resolved.', 'n. 瘤', '/\'tju:mə | \'tjʊmɚ/', 'tumor', 1);
INSERT INTO `words` VALUES (4337, 'That’s a nice tune.', 'n. 调子；和谐; v. 调谐', '/tju:n, tu:n | tjuːn | tun/', 'tune', 1);
INSERT INTO `words` VALUES (4338, 'a railway tunnel', 'n. 隧道，坑道，地道', '/\'tʌnəl | \'tʌnl/', 'tunnel', 1);
INSERT INTO `words` VALUES (4339, 'The new ship will be powered by two gas turbines and four diesel engines.', 'n. 叶轮机，汽轮机', '/\'tə:bain, -bin | \'tɜːbaɪn; -ɪn | \'tɝbaɪn/', 'turbine', 1);
INSERT INTO `words` VALUES (4340, 'He was privately tutored.', 'v. 当…导师， 当…家庭教师; n. 导师；家庭教师，私人教师', '/\'tjuːtə | \'tʊtɚ/', 'tutor', 1);
