INSERT INTO `words` VALUES (4342, 'Her hands began to twist the handles of the bag she carried.', 'v. 扭曲，使弯曲', '/twist | twɪst/', 'twist', 1);
INSERT INTO `words` VALUES (4343, 'Jo’s not really the sporty type.', 'n. 型，类型; v. 打字', '/taip | taɪp/', 'type', 1);
INSERT INTO `words` VALUES (4344, 'She tapped out a letter on the typewriter.', 'n. 打字机', '/\'taip,raitə | \'taɪpraɪtə | \'taɪpraɪtɚ/', 'typewriter', 1);
