INSERT INTO `words` VALUES (4346, 'I’m a slow typist.', 'n. 打字员', '/\'taipist | \'taɪpɪst/', 'typist', 1);
INSERT INTO `words` VALUES (4347, 'I had a flat tyre (= all the air went out of it ) on the way home.', 'n. 轮胎，车胎', '/\'taiə | \'taɪə | \'taɪɚ/', 'tyre', 1);
INSERT INTO `words` VALUES (4348, 'a very ugly man', 'adj. 丑陋的； 可怕的', '/\'ʌgli | \'ʌɡli/', 'ugly', 1);
INSERT INTO `words` VALUES (4349, 'The ultimate outcome of the experiment cannot be predicted.', 'adj. 最后的，最终的', '/\'ʌltimət | \'ʌltɪmət | \'ʌltəmət/', 'ultimate', 1);
INSERT INTO `words` VALUES (4350, 'Ultimately, the decision rests with the child’s parents.', 'adv. 最后，最终', '/\'ʌltimətli | ˈʌltɪmətli | \'ʌltɪmətli/', 'ultimately', 1);
INSERT INTO `words` VALUES (4351, 'It started to rain, so Tricia stopped to put up her umbrella.', 'n. 伞， 雨伞', '/ʌm\'brelə | ʌm\'brɛlə/', 'umbrella', 1);
INSERT INTO `words` VALUES (4352, 'You have to become awfully large to be unaffordable -- there\'s lots of cash, lots of capital out there for acquisitions.', 'adj. 买不起的，负担不起的', '/,ʌnə\'fɔ:dəbl | ˌʌnə\'fɔ:dəbl/', 'unaffordable', 1);
INSERT INTO `words` VALUES (4353, 'The pain was almost unbearable.', 'adj. 无法忍受的', '/,ʌn\'bεərəbl | ʌnˈbeərəbl | ʌn\'bɛrəbl/', 'unbearable', 1);
INSERT INTO `words` VALUES (4354, 'My whole future now seemed uncertain.', 'adj. 不确定的', '/,ʌn\'sə:tən | ʌnˈsɜ:tn | ʌn\'sɝtn/', 'uncertain', 1);
INSERT INTO `words` VALUES (4355, 'She was found alive but unconscious.', 'adj. 不省人事的', '/,ʌn\'kɔnʃəs | ʌn\'kɒnʃəs | ʌn\'kɑnʃəs/', 'unconscious', 1);
INSERT INTO `words` VALUES (4356, 'When the seedlings sprout, uncover the tray.', 'v. 揭开…的盖子', '/,ʌn\'kʌvə | ʌn\'kʌvə | ʌn\'kʌvɚ/', 'uncover', 1);
INSERT INTO `words` VALUES (4357, 'The country has undergone massive changes recently.', 'v. 承受', '/,ʌndə\'ɡəu | ˌʌndəˈgəʊ | ,ʌndɚ\'ɡo/', 'undergo', 1);
INSERT INTO `words` VALUES (4358, 'second-year undergraduates', 'n. 大学在校生', '/,ʌndə\'ɡrædjuət | ʌndə\'grædjʊət | ,ʌndɚ\'ɡrædʒuət/', 'undergraduate', 1);
INSERT INTO `words` VALUES (4359, 'This animal spends most of its life underground.', 'adv. 在地下，往地下；秘密地，不公开地; adj. 地下的；秘密的，不公开的; n. 地铁； 地下组织', '/\'ʌndəgraund | ʌndɚˈɡraʊnd/', 'underground', 1);
INSERT INTO `words` VALUES (4360, 'This tragic incident underlines the need for immediate action.', 'v. 强调', '/,ʌndə\'lain, \'ʌndəlain | ˌʌndəˈlaɪn | \'ʌndəlaɪn/', 'underline', 1);
INSERT INTO `words` VALUES (4361, 'The continued fighting threatens to undermine efforts to negotiate an agreement.', 'v. 暗中破坏', '/,ʌndə\'main | ʌndə\'maɪn | \'ʌndɚ\'maɪn/', 'undermine', 1);
INSERT INTO `words` VALUES (4362, 'He has on his jeans and a long-sleeved blue denim shirt with a white T-shirt underneath.', 'adv. 在下面，在底下', '/,ʌndə\'ni:θ | ʌndə\'niːθ | ,ʌndɚ\'niθ/', 'underneath', 1);
INSERT INTO `words` VALUES (4363, 'Luckily, I have a very under­standing boss.', 'adj. 体谅的， 宽容的， 通情达理的; n. 理解，理解力；谅解；协议；相互理解，融洽', '/ˌʌndə\'stændɪŋ | ,ʌndɚ\'stændɪŋ/', 'understanding', 1);
INSERT INTO `words` VALUES (4364, 'He undertook to pay the money back in six months.', 'v. 承担', '/,ʌndə\'teik | ˌʌndəˈteɪk | ,ʌndɚ\'tek/', 'undertake', 1);
INSERT INTO `words` VALUES (4365, 'Society undervalues staying at home and looking after children.', 'v. 低估', '/,ʌndə\'vælju: | ʌndə\'væljuː | ,ʌndɚ\'vælju/', 'undervalue', 1);
INSERT INTO `words` VALUES (4366, 'The screws can be undone by hand.', 'v. 解开，打开；取消', '/,ʌn\'du: | ʌn\'duː | ʌn\'du/', 'undo', 1);
INSERT INTO `words` VALUES (4367, 'This is undoubtedly important.', 'adv. 无疑', '/ʌn\'daʊtɪdlɪ | ʌn\'daʊtɪdli/', 'undoubtedly', 1);
INSERT INTO `words` VALUES (4368, 'She eventually fell into an uneasy sleep.', 'adj. 心神不安的，忧虑的', '/,ʌn\'i:zi | ʌn\'iːzɪ | ʌn\'izi/', 'uneasy', 1);
INSERT INTO `words` VALUES (4369, 'The experiment produced some unexpected results.', 'adj. 想不到的，意外的', '/,ʌnik\'spektid | ʌnɪk\'spektɪd; ʌnek- | \'ʌnɪk\'spɛktɪd/', 'unexpected', 1);
INSERT INTO `words` VALUES (4370, 'Unfortunately, you were out when we called.', 'adv. 不幸地', '/ʌn\'fɔːtʃənətli | ʌn\'fɔrtʃənətli/', 'unfortunately', 1);
INSERT INTO `words` VALUES (4371, 'Grade A eggs must be of uniform size.', 'adj. 一样的; n. 制服', '/\'ju:nifɔ:m | \'juːnɪfɔːm | \'junɪfɔrm/', 'uniform', 1);
INSERT INTO `words` VALUES (4372, '...the unintended consequences of human action.', 'adj. 意想不到的', '/,ʌnin\'tendid | ˌʌnɪnˈtendɪd | ,ʌnɪn\'tɛndɪd/', 'unintended', 1);
INSERT INTO `words` VALUES (4373, 'Are you planning to join the union?', 'n. 联合；团结；协会', '/\'ju:niən | \'juːnjən; -ɪən | \'junɪən/', 'union', 1);
