INSERT INTO `words` VALUES (4377, 'economic unity', 'n. 单一；统一；团结', '/\'ju:niti | ˈjuːnəti | \'junəti/', 'unity', 1);
INSERT INTO `words` VALUES (4378, 'free universal healthcare', 'adj. 普遍的，宇宙的，全世界的', '/,ju:ni\'və:səl | \'jʊnə\'vɝsl/', 'universal', 1);
INSERT INTO `words` VALUES (4379, 'Einstein\'s equations showed the universe to be expanding.', 'n. 宇宙， 世界； 领域， 范围', '/\'juːnɪvɜːs | \'junɪvɝs/', 'universe', 1);
