INSERT INTO `words` VALUES (4387, 'an unwilling helper', 'adj. 不愿意的', '/,ʌn\'wiliŋ | ʌnˈwɪlɪŋ | ʌn\'wɪlɪŋ/', 'unwilling', 1);
INSERT INTO `words` VALUES (4388, '...the most up-to-date information available on foods today.', 'adj. 直到最近的， 现代的； 跟上时代的', '/ˌʌptə\'deɪt | \'ʌptə \'det/', 'up-to-date', 1);
INSERT INTO `words` VALUES (4389, 'Mike had had a strict upbringing.', 'n. 养育，培养，教养', '/\'ʌp,briŋiŋ | ˈʌpbrɪŋɪŋ | \'ʌpbrɪŋɪŋ/', 'upbringing', 1);
INSERT INTO `words` VALUES (4390, 'The files need updating.', 'v. 更新，使现代化', '/ʌp\'deit, \'ʌpdeit | ˌʌpˈdeɪt | ,ʌp\'det/', 'update', 1);
