INSERT INTO `words` VALUES (4396, 'The charity urged quick action.', 'v. 推进；催促; n. 冲动', '/ə:dʒ | \'ɜːdʒ | ɝdʒ/', 'urge', 1);
INSERT INTO `words` VALUES (4397, 'He was in urgent need of medical attention.', 'adj. 紧急的；强求的', '/\'ə:dʒənt | ˈɜːdʒənt | \'ɝdʒənt/', 'urgent', 1);
INSERT INTO `words` VALUES (4398, 'a book on modern English usage', 'n. 使用，对待；惯用法', '/\'ju:zidʒ | \'juːsɪdʒ | \'jusɪdʒ/', 'usage', 1);
INSERT INTO `words` VALUES (4399, 'Does your rent include utilities?', 'n. 使用，公共设施', '/ju:\'tiləti | ju:ˈtɪləti | ju\'tɪləti/', 'utility', 1);
INSERT INTO `words` VALUES (4400, 'We must consider how best to utilize what resources we have.', 'v. 利用', '/\'ju:tilaiz | ˈjuːtɪˌlaɪz | \'juːtəlaɪz/', 'utilize', 1);
INSERT INTO `words` VALUES (4401, 'It is a matter of the utmost urgency to find out what has happened to these people.', 'adj. 最远的; n. 极限', '/\'ʌtməust | \'ʌtməʊst | \'ʌt\'most/', 'utmost', 1);
INSERT INTO `words` VALUES (4402, 'That’s utter nonsense!', 'adj. 完全的，彻底的', '/\'ʌtə | \'ʌtɚ/', 'utter', 1);
