INSERT INTO `words` VALUES (4407, 'Men can be just as vain as women.', 'adj. 徒劳的；自负的', '/英[veɪn] 美[ven] | veɪn | ven/', 'vain', 1);
INSERT INTO `words` VALUES (4408, 'a valid credit card', 'adj. 有效的', '/\'vælɪd/', 'valid', 1);
INSERT INTO `words` VALUES (4409, 'Shelley valued her privacy.', 'v. 重视', '/\'vælju: | \'vælju/', 'value', 1);
INSERT INTO `words` VALUES (4410, 'a delivery van', 'n. 大篷车，运货车', '/væn/', 'van', 1);
INSERT INTO `words` VALUES (4411, 'My keys were here a minute ago but now they’ve vanished.', 'v. 消失', '/\'væniʃ | \'vænɪʃ/', 'vanish', 1);
INSERT INTO `words` VALUES (4412, 'water vapour', 'n. 汽，蒸气', '/\'veipə | \'veɪpə | \'vepɚ/', 'vapour', 1);
