INSERT INTO `words` VALUES (4414, 'Most of his poems are variations on the theme of love.', 'n. 变化，变动；变异', '/,vεəri\'eiʃən | veərɪ\'eɪʃ(ə)n | ,vɛrɪ\'eʃən/', 'variation', 1);
INSERT INTO `words` VALUES (4415, 'The girls come from a variety of different backgrounds.', 'n. 多样', '/英 [vəˈraɪəti] 美 [vəˈraɪɪti | və\'raɪətɪ | və\'raɪəti/', 'variety', 1);
INSERT INTO `words` VALUES (4416, 'The jacket is available in various colours.', 'adj. 各种各样的，不同的', '/\'vεəriəs | \'veərɪəs | \'vɛrɪəs/', 'various', 1);
