INSERT INTO `words` VALUES (4545, 'How could she abandon her own child?', 'vt. 离弃， 丢弃； 遗弃； 抛弃； 放弃', '/ə\'bændən/', 'abandon', 2);
INSERT INTO `words` VALUES (4546, '...memories of her father\'s complete abandonment of her.', 'n. 放弃', '/ə\'bændənmənt | əˈbændənmənt/', 'abandonment', 2);
INSERT INTO `words` VALUES (4547, '‘Dr’ is the written abbreviation of ‘Doctor’.', 'n. 节略，缩写，缩短', '/ə,bri:vi\'eiʃən | əbriːvɪ\'eɪʃ(ə)n | əˌbrivɪ\'eʃən/', 'abbreviation', 2);
INSERT INTO `words` VALUES (4548, 'I can\'t abide people with no sense of humour.', 'v. 忍受；遵守', '/ə\'baɪd/', 'abide', 2);
INSERT INTO `words` VALUES (4549, 'abnormal behaviour', 'adj. 反常的， 异常的', '/æb\'nɔːml | æbˈnɔːrml/', 'abnormal', 2);
INSERT INTO `words` VALUES (4550, 'Both were big at birth but were not abnormally large.', 'adv. 不正常的', '/æb\'nɔ:məli | æb\'nɔ:məlɪ/', 'abnormally', 2);
INSERT INTO `words` VALUES (4551, 'Slavery was abolished in the US in the 19th century.', 'v. 废除，取消', '/ə\'bɔliʃ | ə\'bɒlɪʃ | ə\'bɑlɪʃ/', 'abolish', 2);
INSERT INTO `words` VALUES (4552, 'The abolition of slavery in Brazil and the Caribbean closely followed the pattern of the United States.', 'n. 废除', '/,æbəu\'liʃən | ˌæbəˈlɪʃn | ,æbə\'lɪʃən/', 'abolition', 2);
INSERT INTO `words` VALUES (4553, 'She decided to have an abortion .', 'n. 流产， 堕胎', '/ə\'bɔːʃn | ə\'bɔrʃən/', 'abortion', 2);
INSERT INTO `words` VALUES (4554, 'an abrupt change of plan', 'adj. 突然的， 意外的； 唐突的， 鲁莽的', '/ə\'brʌpt/', 'abrupt', 2);
INSERT INTO `words` VALUES (4555, 'In the absence of any evidence, the police had to let Myers go.', 'n. 缺席， 不在； 缺席的时间， 外出期； 缺乏， 不存在', '/\'æbsəns | \'æbsns/', 'absence', 2);
INSERT INTO `words` VALUES (4556, 'students who are regularly absent from school', 'adj. 不在的', '/\'æbsənt, æb\'sent | \'æbs(ə)nt | ˈæbsənt/', 'absent', 2);
INSERT INTO `words` VALUES (4557, '‘Do you let your kids travel alone at night?’ ‘Absolutely not!’', 'adv. 当然', '/\'æbsəlju:tli, ,æbsə\'lju:tli | ˈæbsəlu:tli | \'æbsəlutli/', 'absolutely', 2);
INSERT INTO `words` VALUES (4558, 'Plants absorb nutrients from the soil.', 'vt. 吸收； 吸引…的注意， 使全神贯注； 把…并入， 同化', '/əb\'sɔːb | æbˈsɔrb; æbˈzɔrb; əbˈsɔrb/', 'absorb', 2);
INSERT INTO `words` VALUES (4559, 'the body’s absorption of iron', 'n. 吸收；专注', '/əb\'sɔ:pʃən | əb\'zɔːpʃ(ə)n; -\'sɔːp- | əbˈsɔrpʃən, -ˈzɔrp-/', 'absorption', 2);
INSERT INTO `words` VALUES (4560, 'By the age of seven, children are capable of thinking in abstract terms .', 'adj. 抽象的', '/\'æbstrækt/', 'abstract', 2);
INSERT INTO `words` VALUES (4561, 'It seems an absurd idea.', 'adj. 不合理的，荒唐的', '/əb\'sə:d | əb\'sɜːd | əbˈsɚd, -ˈzɚd/', 'absurd', 2);
INSERT INTO `words` VALUES (4562, 'an abundance of wavy red hair', 'n. 丰富，充裕', '/ə\'bʌndəns | ə\'bʌnd(ə)ns/', 'abundance', 2);
INSERT INTO `words` VALUES (4563, 'an abundant supply of fresh water', 'adj. 丰富的， 富裕的； 大量的， 充足的', '/ə\'bʌndənt/', 'abundant', 2);
INSERT INTO `words` VALUES (4564, 'several cases of child abuse', 'n. 虐待; v. 滥用', '/ə\'bju:z, ə\'bju:s | ə\'bju:s | ə\'bjus/', 'abuse', 2);
INSERT INTO `words` VALUES (4565, 'He possessed no academic qualifications.', 'adj. 学院的；学术的；纯理论的，不切实际的; n. 大学教师', '/ˌækə\'demɪk | ,ækə\'dɛmɪk/', 'academic', 2);
INSERT INTO `words` VALUES (4566, 'measures to accelerate the rate of economic growth', 'v. 加速', '/ək\'seləreit | ək\'seləreɪt | əkˈsɛləˌret/', 'accelerate', 2);
INSERT INTO `words` VALUES (4567, 'He wrote a letter of acceptance (= a letter in which you agree to accept a job, university place etc ) to the university.', 'n. 接受， 承认； 容忍', '/ək\'septəns | ək\'sɛptəns/', 'acceptance', 2);
INSERT INTO `words` VALUES (4568, 'Users can access their voice mail remotely.', 'v. 取得，获取', '/\'ækses, \'æksəs, æk\'ses | ˈækses | \'æksɛs/', 'access', 2);
INSERT INTO `words` VALUES (4569, 'an accessory to murder', 'n. 同谋，帮凶; adj. 附属的', '/ək\'sesəri | ək\'ses(ə)rɪ | ək\'sɛsəri/', 'accessory', 2);
INSERT INTO `words` VALUES (4570, 'I met her quite by accident (= completely by accident ) .', 'n. 意外， 事故', '/\'æksɪdənt | \'æksədənt/', 'accident', 2);
INSERT INTO `words` VALUES (4571, 'She accidentally erased the tape.', 'adv. 偶然地，意外地', '/,æksi\'dentli | ˌæksɪˈdentəli | ,æksə\'dɛntli/', 'accidentally', 2);
INSERT INTO `words` VALUES (4572, 'He bought a huge house to accommodate his library.', 'v. 适应，容纳', '/ə\'kɔmədeit | əˈkɒmədeɪt | ə\'kɑmədet/', 'accommodate', 2);
INSERT INTO `words` VALUES (4573, 'The price for the holiday includes flights and accommodation.', 'n. 住处， 膳宿', '/əˌkɒmə\'deɪʃn | ə,kɑmə\'deʃən/', 'accommodation', 2);
INSERT INTO `words` VALUES (4574, 'Children under 14 must be accompanied by an adult.', 'v. 陪同， 伴随； 为…伴奏', '/ə\'kʌmpəni/', 'accompany', 2);
INSERT INTO `words` VALUES (4575, 'We have accomplished all we set out to do.', 'v. 实现', '/ə\'kʌmpliʃ, ə\'kɔm- | ə\'kʌmplɪʃ | ə\'kɑmplɪʃ/', 'accomplish', 2);
INSERT INTO `words` VALUES (4576, 'These results are in accord with earlier research.', 'n. 符合；协议', '/ə\'kɔ:d | ə\'kɔːd | ə\'kɔrd/', 'accord', 2);
INSERT INTO `words` VALUES (4577, 'If your pursuit of personal career and ideal are in accordance with ours, if you are seeking for the pleasure from sharing the same ambitions, please join us!', 'n. 一致， 和谐， 符合', '/ə\'kɔːdns | ə\'kɔrdns/', 'accordance', 2);
INSERT INTO `words` VALUES (4578, 'My salary is paid into my bank account.', 'vi. 说明…的原因； 占…; n. 记述；解释；账目', '/ə\'kaunt | ə\'kaʊnt/', 'account', 2);
INSERT INTO `words` VALUES (4579, 'The hospital should be held accountable for the quality of care it gives.', 'adj. 应负责的，有责任的', '/ə\'kauntəbl | ə\'kaʊntəbl/', 'accountable', 2);
INSERT INTO `words` VALUES (4580, 'The boss dropped an accountant from the payroll.', 'n. 会计', '/ə\'kauntənt | əˈkaʊntənt | ə\'kaʊntənt/', 'accountant', 2);
INSERT INTO `words` VALUES (4581, 'Interest will accrue until payment is made.', 'v. 积累', '/ə\'kru: | ə\'kru/', 'accrue', 2);
INSERT INTO `words` VALUES (4582, 'It is unjust that a privileged few should continue to accumulate wealth.', 'v. 积累', '/ə\'kju:mjuleit | əˈkju:mjəleɪt | ə\'kjumjəlet/', 'accumulate', 2);
INSERT INTO `words` VALUES (4583, 'The brochure tries to give a fair and accurate description of each hotel.', 'adj. 精确的', '/\'ækjurət | ˈækjərət | \'ækjərət/', 'accurate', 2);
INSERT INTO `words` VALUES (4584, 'The professor stands accused of (= has been accused of ) stealing his student’s ideas and publishing them.', 'v. 指控', '/ə\'kju:z | ə\'kjuz/', 'accuse', 2);
INSERT INTO `words` VALUES (4585, 'She tried to accustom herself to the tight bandages.', 'v. 使习惯', '/ə\'kʌstəm/', 'accustom', 2);
INSERT INTO `words` VALUES (4586, 'The pans were in their accustomed places.', 'adj. 惯常的， 习惯的', '/ə\'kʌstəmd/', 'accustomed', 2);
INSERT INTO `words` VALUES (4587, 'Frances achieved very good exam results.', 'v. 达到，实现', '/ə\'tʃi:v | ə\'tʃiv/', 'achieve', 2);
INSERT INTO `words` VALUES (4588, 'His great achievement is to make all the players into a united team.', 'n. 完成； 成就， 成绩', '/ə\'tʃiːvmənt | ə\'tʃivmənt/', 'achievement', 2);
INSERT INTO `words` VALUES (4589, 'a juicy apple with a slightly acid flavour', 'adj. 酸的， 酸性的； 尖刻的， 刻薄的; n. 酸', '/\'æsɪd/', 'acid', 2);
INSERT INTO `words` VALUES (4590, 'The family acknowledge the need for change.', 'v. 承认；告知收到', '/ək\'nɔlidʒ | ək\'nɒlɪdʒ | ək\'nɑlɪdʒ/', 'acknowledge', 2);
INSERT INTO `words` VALUES (4591, 'Have steps been taken to acquaint breeders with their right to apply for licenses?', 'v. 使认识，使了解', '/ə\'kweint | ə\'kweɪnt | ə\'kwent/', 'acquaint', 2);
INSERT INTO `words` VALUES (4592, 'She was a casual acquaintance of my family in Vienna.', 'n. 熟人', '/ə\'kweintəns | ə\'kweɪntəns | ə\'kwentəns/', 'acquaintance', 2);
INSERT INTO `words` VALUES (4593, 'Manning hoped to acquire valuable works of art as cheaply as possible.', 'vt. 取得， 获得； 学到', '/ə\'kwaɪə | ə\'kwaɪr/', 'acquire', 2);
INSERT INTO `words` VALUES (4594, 'The government must take action (=do something) now to stop the rise in violent crime.', 'n. 行动', '/\'ækʃən | \'ækʃ(ə)n/', 'action', 2);
INSERT INTO `words` VALUES (4595, 'Cooking fumes may activate the alarm.', 'v. 激活', '/\'æktiveit | \'æktɪveɪt | \'æktə\'vet/', 'activate', 2);
INSERT INTO `words` VALUES (4596, 'The housing shortage is more acute than first thought.', 'adj. 严重的； 急性的； 灵敏的， 敏锐的； 精明的', '/ə\'kjuːt | ə\'kjut/', 'acute', 2);
INSERT INTO `words` VALUES (4597, 'We continue to conduct tests, but increasingly, we conduct long conversations with her, acutely aware that our creation will raise many ethical questions on the part of the public.', 'adv. 敏锐地', '/ə\'kju:tli | əˈkju:tli | ə\'kjutli/', 'acutely', 2);
INSERT INTO `words` VALUES (4598, 'The ability to adapt is a definite asset in this job.', 'vt. 使适应； 改编', '/ə\'dæpt/', 'adapt', 2);
INSERT INTO `words` VALUES (4599, 'Branagh won two awards for his screen adaptation of Shakespeare\'s Henry the Fifth.', 'n. 适应；改编', '/,ədæp\'teiʃən | ædəp\'teɪʃ(ə)n | ,ædæp\'teʃən/', 'adaptation', 2);
INSERT INTO `words` VALUES (4600, 'Meanwhile, Walt\'s meth-business partner, the addict Jesse, is still recovering from the drug-related death of his girlfriend Jane at the end of last season.', 'v. 上瘾，沉溺', '/ə\'dikt,\'ædikt | \'ædɪkt | \'ædɪkt (for n.); əˈdɪkt (for v.)/', 'addict', 2);
INSERT INTO `words` VALUES (4601, 'This is a fine book; a worthy addition to the series.', 'n. 加， 加法； 附加物', '/ə\'dɪʃn | ə\'dɪʃən/', 'addition', 2);
INSERT INTO `words` VALUES (4602, 'Additional information can be obtained from the centre.', 'adj. 附加的， 追加的', '/ə\'dɪʃənl/', 'additional', 2);
INSERT INTO `words` VALUES (4603, '...We need very broad participation to fully address global tragedy that results when countries fail to take into account the negative impact of their carbon emissions on the rest of the world...', 'v. 解决', '/ə\'dres | ə\'drɛs/', 'address', 2);
INSERT INTO `words` VALUES (4604, 'Farmers have been slow to make adequate provision for their retirement.', 'adj. 足够的； 可以胜任的', '/\'ædɪkwət | ˈædɪkwət/', 'adequate', 2);
INSERT INTO `words` VALUES (4605, 'Small particles adhere to the seed.', 'v. 粘附；追随；坚持', '/əd\'hiə | əd\'hɪə | əd\'hɪr/', 'adhere', 2);
INSERT INTO `words` VALUES (4606, 'We stayed in adjacent rooms.', 'adj. 毗连的；紧接着的', '/ə\'dʒeisənt | ə\'dʒeɪs(ə)nt | ə\'dʒesnt/', 'adjacent', 2);
INSERT INTO `words` VALUES (4607, 'A vacant plot of land adjoins his house.', 'v. 贴近，毗连；靠近', '/ə\'dʒɔin | ə\'dʒɒɪn | ə\'dʒɔɪn/', 'adjoin', 2);
INSERT INTO `words` VALUES (4608, 'They’ll soon settle in – kids are very good at adjusting.', 'vi. 适应; vt. 调整，调节；校正', '/ə\'dʒʌst/', 'adjust', 2);
INSERT INTO `words` VALUES (4609, 'an adjustable spanner', 'adj. 可调整的，可校准的', '/ə\'dʒʌstəbl/', 'adjustable', 2);
INSERT INTO `words` VALUES (4610, 'We’re looking for someone with experience in administration.', 'n. 管理，政府', '/əd,mini\'streiʃən | ədˌmɪnɪˈstreɪʃn | əd,mɪnɪ\'streʃən/', 'administration', 2);
INSERT INTO `words` VALUES (4611, 'Daniel gazed at her in admiration .', 'n. 钦佩；赞美，羡慕', '/,ædmə\'reiʃən | ædmə\'reɪʃ(ə)n | ,ædmə\'reʃən/', 'admiration', 2);
INSERT INTO `words` VALUES (4612, '‘Okay, so maybe I was a little bit scared,’ Jenny admitted.', 'vi. 承认; vt. 承认，供认；准许…进入', '/əd\'mɪt/', 'admit', 2);
INSERT INTO `words` VALUES (4613, 'It is important that an adolescent boy should have an adult in whom he can confide.', 'adj. 青春期的； 青少年的; n. 青少年', '/ˌædə\'lesnt | ,ædə\'lɛsnt/', 'adolescent', 2);
INSERT INTO `words` VALUES (4614, 'The courts were asked to adopt a more flexible approach to young offenders.', 'v. 采纳', '/ə\'dɔpt | ə\'dɒpt | ə\'dɑpt/', 'adopt', 2);
INSERT INTO `words` VALUES (4615, 'She decided to put the baby up for adoption.', 'n. 收养；采纳，采取', '/ə\'dɔpʃən | ə\'dɒpʃ(ə)n | ə\'dɑpʃən/', 'adoption', 2);
INSERT INTO `words` VALUES (4616, 'It\'s obvious that she adores him.', 'v. 崇拜，爱慕；很喜欢', '/ə\'dɔ: | ə\'dɔː | ə\'dɔr/', 'adore', 2);
INSERT INTO `words` VALUES (4617, 'Younger workers tend to be at an advantage (= have an advantage ) when applying for jobs.', 'n. 优点， 优势； 好处', '/əd\'vɑːntɪdʒ | əd\'væntɪdʒ/', 'advantage', 2);
INSERT INTO `words` VALUES (4618, 'He was now in a more advantageous position.', 'adj. 有利的，有助的', '/,ædvən\'teidʒəs | ædvən\'teɪdʒəs | \'ædvən\'tedʒəs/', 'advantageous', 2);
INSERT INTO `words` VALUES (4619, 'a great adventure', 'n. 冒险', '/əd\'ventʃə, æd- | əd\'ventʃə(r) | əd\'vɛntʃɚ/', 'adventure', 2);
INSERT INTO `words` VALUES (4620, 'an adventurer travelling the world', 'n. 冒险者', '/əd\'ventʃərə | ədˈventʃərə(r) | əd\'vɛntʃərɚ/', 'adventurer', 2);
INSERT INTO `words` VALUES (4621, 'They fear it could have an adverse effect on global financial markets.', 'adj. 相反的，敌对的', '/\'ædvə:s, æd\'və:s | ˈædvɜ:s | ædˈvɚs, ˈædˌvɚs/', 'adverse', 2);
INSERT INTO `words` VALUES (4622, 'I think everyone has something from their past that they\'re worried might adversely affect how they raise their children.', 'adv. 不利地', '/æd\'və:sli | əd\'vɜ:slɪ | æd\'vɝsli/', 'adversely', 2);
INSERT INTO `words` VALUES (4623, 'his courage in the face of adversity', 'n. 逆境', '/əd\'və:səti | ədˈvɜːsəti | əd\'vɝsəti/', 'adversity', 2);
INSERT INTO `words` VALUES (4624, 'They no longer advertise alcohol or cigarettes at sporting events.', 'v. 登广告', '/\'ædvətaiz | \'ædvətaɪz | \'ædvɚtaɪz/', 'advertise', 2);
INSERT INTO `words` VALUES (4625, 'Regular medical check-ups are advisable.', 'adj. 可取的； 适当的', '/əd\'vaɪzəbl/', 'advisable', 2);
INSERT INTO `words` VALUES (4626, 'Extremists were openly advocating violence.', 'v. 拥护; n. 辩护律师', '/\'ædvəkeit, \'ædvəkət | \'ædvəkeɪt；-ət | ˈædvəkeɪt；-et/', 'advocate', 2);
INSERT INTO `words` VALUES (4627, 'The banyan tree has aerial roots.', 'adj. 空气的；航空的', '/\'εəriəl | \'eərɪəl | \'ɛrɪəl/', 'aerial', 2);
INSERT INTO `words` VALUES (4628, 'employment in the aerospace industry', 'n. 航空航天工业', '/\'εərəuspeis | \'eərəspeɪs | \'ɛrospes/', 'aerospace', 2);
INSERT INTO `words` VALUES (4629, 'From an esthetic point of view, it’s a nice design.', 'adj. 美学的， 审美的； 悦目的， 雅致的', '/iːs\'θetɪk | esˈθetɪk; ɛsˈθɛtɪk/', 'aesthetic', 2);
INSERT INTO `words` VALUES (4630, 'She looked back on those days with affection .', 'n. 喜爱', '/ə\'fekʃən | əˈfekʃn | ə\'fɛkʃən/', 'affection', 2);
INSERT INTO `words` VALUES (4631, 'He wanted to affiliate with a U.S. firm because he needed expert advice in legal affairs.', 'v. 使隶属于', '/ə\'filieit, ə\'filiit, -eit | əˈfɪlieɪt | ə\'fɪlɪet/', 'affiliate', 2);
INSERT INTO `words` VALUES (4632, NULL, 'n. 隶属关系，单位团体', '/ə,fili\'eiʃən | ə,fɪlɪ\'eʃən/', 'affiliation', 2);
INSERT INTO `words` VALUES (4633, 'The general affirmed rumors of an attack.', 'v. 断言，证实', '/ə\'fə:m | ə\'fɜːm | ə\'fɝm/', 'affirm', 2);
INSERT INTO `words` VALUES (4634, NULL, 'vt. 使苦恼， 折磨', '/ə\'flɪkt/', 'afflict', 2);
INSERT INTO `words` VALUES (4635, 'The room affords a beautiful view over the city.', 'vt. 担负得起； 提供', '/ə\'fɔːd | ə\'fɔrd/', 'afford', 2);
INSERT INTO `words` VALUES (4636, 'The Republicans have stuck to their conservative agenda.', 'n. 议程', '/ə\'dʒendə | ə\'dʒɛndə/', 'agenda', 2);
INSERT INTO `words` VALUES (4637, 'Our agent in Rio deals with all our Brazilian business.', 'n. 代理人， 代理商； 政府代表； 动因， 原因； 剂', '/\'eɪdʒənt | \'edʒənt/', 'agent', 2);
INSERT INTO `words` VALUES (4638, 'Their money problems were further aggravated by a rise in interest rates.', 'v. 加重，加剧', '/\'æɡrəveit | \'æɡrəveɪt | \'æɡrəvet/', 'aggravate', 2);
INSERT INTO `words` VALUES (4639, 'an increase in the aggregate production', 'adj. 总计的， 合计的; n. 总数，合计; vt. 总计达， 合计； 使聚集， 使积聚', '/\'ægrɪgət; (for v.) ˈægrɪgeɪt | \'æɡrɪɡət; (for v.) æɡrɪˌɡet/', 'aggregate', 2);
INSERT INTO `words` VALUES (4640, 'Jim’s voice became aggressive.', 'adj. 挑衅的', '/ə\'ɡresiv | əˈgresɪv | ə\'ɡrɛsɪv/', 'aggressive', 2);
INSERT INTO `words` VALUES (4641, 'mass agitation for political reform', 'n. 鼓动，煸动；搅动', '/,ædʒi\'teiʃən | ædʒɪ\'teɪʃ(ə)n | ,ædʒɪ\'teʃən/', 'agitation', 2);
INSERT INTO `words` VALUES (4642, 'As a mother, I agonize over what my children will inherit.', 'v. 使痛苦', '/\'æɡənaiz | \'æɡənaɪz/', 'agonize', 2);
INSERT INTO `words` VALUES (4643, 'the agony of arthritis', 'n. 痛苦', '/\'æɡəni | \'ægənɪ/', 'agony', 2);
INSERT INTO `words` VALUES (4644, 'We spent a most agreeable couple of hours.', 'adj. 惬意的；同意的', '/ə\'ɡri:əbl | ə\'griːəb(ə)l | ə\'ɡriəbl/', 'agreeable', 2);
INSERT INTO `words` VALUES (4645, 'an index to aid the reader', 'v. 援助，有助于', '/eid | eɪd | ed/', 'aid', 2);
INSERT INTO `words` VALUES (4646, 'The two chief function of any air-conditioning system are the regulation of air temperature and humidity.', 'n. 空调设备， 空调系统', '/\'eəkən,diʃθniŋ | \'eəkənˌdɪʃənɪŋ/', 'air-conditioning', 2);
INSERT INTO `words` VALUES (4647, 'Would you like a window seat or an aisle seat (= seat next to the aisle ) ?', 'n. 过道， 通道', '/aɪl/', 'aisle', 2);
INSERT INTO `words` VALUES (4648, 'I forgot to set the burglar alarm.', 'n. 惊恐，忧虑，警报; vt. 使惊恐， 使担心', '/ə\'lɑːm | ə\'lɑrm/', 'alarm', 2);
INSERT INTO `words` VALUES (4649, 'For many people, alas, hunger is part of everyday life.', 'int. 唉，哎呀', '/ə\'læs | ə\'læs; ə\'lɑːs/', 'alas', 2);
INSERT INTO `words` VALUES (4650, 'a photograph album', 'n. （收存照片或邮票的） 册子', '/\'ælbəm/', 'album', 2);
INSERT INTO `words` VALUES (4651, 'I don’t drink alcohol anymore.', 'n. 酒精， 乙醇', '/\'ælkəhɒl | \'ælkəhɔl/', 'alcohol', 2);
INSERT INTO `words` VALUES (4652, 'The animal raised its head, suddenly alert.', 'adj. 机警的; v. 提醒', '/ə\'lə:t | ə\'lɜ:t | ə\'lɝt/', 'alert', 2);
INSERT INTO `words` VALUES (4653, 'He was not good at algebra in middle school.', 'n. 代数学', '/\'ældʒibrə | \'ældʒɪbrə/', 'algebra', 2);
INSERT INTO `words` VALUES (4654, 'the alien environment of the city', 'adj. 陌生的', '/\'eiljən | \'eɪlɪən | ˈeliən,ˈeljən/', 'alien', 2);
