INSERT INTO `words` VALUES (4659, 'an allergic reaction to nuts', 'adj. 过敏的', '/ə\'lə:dʒik | əˈlɜ:dʒɪk | ə\'lɝdʒɪk/', 'allergic', 2);
INSERT INTO `words` VALUES (4660, 'measures to alleviate poverty', 'v. 减轻，缓解', '/ə\'li:vieit | əˈliːvieɪt | ə\'livɪ\'et/', 'alleviate', 2);
