INSERT INTO `words` VALUES (4667, 'He crossed the street and walked alongside Central Park.', 'prep. 在…旁边', '/ə\'lɔŋ\'said | əlɒŋ\'saɪd | ə\'lɔŋ\'saɪd/', 'alongside', 2);
INSERT INTO `words` VALUES (4668, 'The files are arranged in alphabetical order .', 'adj. 按字母表顺序的', '/,ælfə\'betikəl, ,ælfə\'betik | ˌælfəˈbetɪkl | ,ælfə\'bɛtɪkl/', 'alphabetical', 2);
INSERT INTO `words` VALUES (4669, 'Her face hadn’t altered much over the years.', 'vt. 改变， 变更， 变动', '/\'ɔːltə | \'ɔltɚ/', 'alter', 2);
INSERT INTO `words` VALUES (4670, 'If you make alterations to the Windows setup, save the new settings before closing.', 'n. 变更，改变', '/,ɔ:ltə\'reiʃən | ɔːltə\'reɪʃ(ə)n; \'ɒl- | ,ɔltə\'reʃən/', 'alteration', 2);
INSERT INTO `words` VALUES (4671, 'Alternate cubes of meat and slices of red pepper.', 'v. 使交替; adj. 交替的', '/ɔ:l\'tə:nət, \'ɔ:ltə-, \'ɔ:ltəneit | \'ɔːltəneɪt; \'ɒl- | \'ɔltɚnət/', 'alternate', 2);
INSERT INTO `words` VALUES (4672, 'New ways to treat arthritis may provide an alternative to painkillers.', 'n. 代替品', '/ɔ:l\'tə:nətiv | ɔ:lˈtɜ:nətɪv | ɔl\'tɝnətɪv/', 'alternative', 2);
