INSERT INTO `words` VALUES (4674, '...professional athletes and amateur runners.', 'adj. 业余的; n. 业余爱好者', '/\'æmətə, ,æmə\'tə: | \'æmətə; -tʃə; -tjʊə; ,æmə\'tɜː | ˈæmətər/', 'amateur', 2);
INSERT INTO `words` VALUES (4675, 'the US ambassador to Spain', 'n. 大使，使节', '/æm\'bæsədə | æm\'bæsədɚ/', 'ambassador', 2);
