INSERT INTO `words` VALUES (4684, 'As we fall asleep the amplitude of brain waves slowly becomes greater.', 'n. 振幅；广大；充足', '/\'æmplitju:d | \'æmplɪtjuːd | \'æmplə\'tʊd/', 'amplitude', 2);
INSERT INTO `words` VALUES (4685, 'Steve couldn’t hide his amusement.', 'n. 乐趣；娱乐，消遣', '/ə\'mju:zmənt | ə\'mjuːzm(ə)nt | ə\'mjuzmənt/', 'amusement', 2);
INSERT INTO `words` VALUES (4686, 'Marine construction technology like this is very complex, somewhat analogous to trying to build a bridge under water.', 'adj. 类似的， 相似的； 可比拟的', '/ə\'næləgəs | ə\'næləɡəs/', 'analogous', 2);
