INSERT INTO `words` VALUES (4689, 'She still needs to analyse the data.', 'vt. 分析； 分解， 解析', '/\'ænəlaɪz | \'æn(ə)laɪz/', 'analyse', 2);
INSERT INTO `words` VALUES (4690, 'She’s been in analysis for three years.', 'n. 分析， 分析报告； 分解， 解析', '/ə\'næləsɪs/', 'analysis', 2);
INSERT INTO `words` VALUES (4691, 'She’s got an analytical mind.', 'adj. 分析的', '/,ænə\'litik,-kəl | ˌænəˈlɪtɪkl | ,ænə\'lɪtɪkl/', 'analytical', 2);
