INSERT INTO `words` VALUES (4694, 'slender ankles', 'n. 脚踝', '/\'æŋkl | ˈæŋkl/', 'ankle', 2);
INSERT INTO `words` VALUES (4695, 'Jack and Kim celebrated their twentieth wedding anniversary in January.', 'n. 周年纪念日', '/,æni\'və:səri | ænɪ\'vɜːs(ə)rɪ | ,ænɪ\'vɝsəri/', 'anniversary', 2);
