INSERT INTO `words` VALUES (4729, 'There is a murmur of appreciative laughter.', 'adj. 表示赞赏的，感谢的', '/ə\'pri:ʃiətiv | əˈpri:ʃətɪv | ə\'priʃətɪv/', 'appreciative', 2);
