INSERT INTO `words` VALUES (4755, 'bright, articulate 17-year-olds', 'adj. 善于表达的， 发音清晰的； 表达得清楚有力的; vt. 明确有力地表达； 清楚地吐， 清晰地发', '/ɑ:\'tɪkjʊleɪt | ɑr\'tɪkjulet/', 'articulate', 2);
INSERT INTO `words` VALUES (4756, 'artificial flowers', 'adj. 人造的，虚伪的', '/,ɑ:ti\'fiʃəl | ˌɑ:tɪ\'fɪʃl | ,ɑrtɪ\'fɪʃl/', 'artificial', 2);
