INSERT INTO `words` VALUES (5152, '‘I’m going to Appleby tomorrow.’ ‘ What a coincidence ! I’m going there too.’', 'n. 巧合， 巧事； 一致， 符合', '/kəu\'ɪnsɪdəns | ko\'ɪnsɪdəns/', 'coincidence', 2);
INSERT INTO `words` VALUES (5153, '...a coke-burning stove.', 'n. 焦炭', '/kəʊk | kok/', 'coke', 2);
INSERT INTO `words` VALUES (5154, 'Much later he collaborated with his son Michael on the English translation of a text on food production.', 'v. 合作', '/kə\'læbəreit | kəˈlæbəreɪt | kə\'læbəret/', 'collaborate', 2);
INSERT INTO `words` VALUES (5155, 'The company is building the centre in collaboration with the Institute of Offshore Engineering.', 'n. 合作， 协作； 勾结', '/kəˌlæbə\'reɪʃn | kə,læbə\'reʃən/', 'collaboration', 2);
INSERT INTO `words` VALUES (5156, '...a collaborative research project.', 'adj. 合作的', '/kə\'læbərətiv | kəˈlæbərətɪv | kə\'læbəretɪv/', 'collaborative', 2);
INSERT INTO `words` VALUES (5157, 'Uncle Ted’s chair collapsed under his weight.', 'v. 坍塌，崩塌', '/kə\'læps/', 'collapse', 2);
