INSERT INTO `words` VALUES (5161, 'Two people were killed in a head-on collision (= between two vehicles that are moving directly towards each other ) on highway 218.', 'n. 碰撞； 冲突， 抵触', '/kə\'lɪʒn | kə\'lɪʒən/', 'collision', 2);
INSERT INTO `words` VALUES (5162, 'the struggle against colonial rule', 'adj. 殖民地的，殖民的', '/kə\'ləunjəl | kə\'ləʊnɪəl | kə\'lonɪəl/', 'colonial', 2);
INSERT INTO `words` VALUES (5163, 'The colonists struggled through their first winter.', 'n. 移民；殖民地居民', '/\'kɔlənist | \'kɒlənɪst | \'kɑlənɪst/', 'colonist', 2);
