INSERT INTO `words` VALUES (5165, 'to combat crime/terrorism/inflation/disease', 'v. 跟…战斗，格斗', '/\'kɔmbæt, kəm\'bæt | \'kɒmbæt; \'kʌm- | \'kɑmbæt/', 'combat', 2);
INSERT INTO `words` VALUES (5166, 'a combination nightclub and café', 'n. 组合，结合', '/,kɔmbi\'neiʃən | kɒmbɪ\'neɪʃ(ə)n | ,kɑmbɪ\'neʃən/', 'combination', 2);
INSERT INTO `words` VALUES (5167, 'Diets are most effective when combined with exercise.', 'v. 结合，联合；化合; n. 联合企业； 联合收割机', '/kəm\'baɪn/', 'combine', 2);
INSERT INTO `words` VALUES (5168, 'The energy is released by combustion on the application of a match.', 'n. 燃烧', '/kəm\'bʌstʃən | kəm\'bʌstʃ(ə)n/', 'combustion', 2);
INSERT INTO `words` VALUES (5169, 'a career in stand-up comedy', 'n. 喜剧；喜剧场面', '/英[\'kɒmɪdɪ] 美[\'kɑmədi] | \'kɒmɪdɪ | \'kɑmədi/', 'comedy', 2);
INSERT INTO `words` VALUES (5170, 'Halley’s comet', 'n. 彗星', '/\'kɒmɪt | \'kɑmət/', 'comet', 2);
INSERT INTO `words` VALUES (5171, 'a comic novel', 'adj. 喜剧的，滑稽的; n. 连环漫画； 喜剧演员', '/\'kɒmɪk | \'kɑmɪk/', 'comic', 2);
INSERT INTO `words` VALUES (5172, 'By 1944, Fletcher had command of a B-17 bomber and a ten-man crew.', 'n&vt. 命令， 指挥； 控制', '/kə\'mɑːnd | kə\'mænd/', 'command', 2);
INSERT INTO `words` VALUES (5173, 'a parade to commemorate the town’s bicentenary', 'vt. 纪念， 庆祝', '/kə\'meməreɪt | kə\'mɛməret/', 'commemorate', 2);
INSERT INTO `words` VALUES (5174, 'Work will commence on the new building immediately.', 'v. 开始；获得学位', '/kə\'mens | kə\'mɛns/', 'commence', 2);
