INSERT INTO `words` VALUES (5176, 'Commentary is by Tom Ferris.', 'n. 实况报道， 解说词； 评论， 评论文章', '/\'kɒməntri | \'kɑməntɛri/', 'commentary', 2);
INSERT INTO `words` VALUES (5177, 'political commentators', 'n. 评论员', '/\'kɔmenteitə | ˈkɒmənteɪtə(r) | \'kɑmən\'tetɚ/', 'commentator', 2);
INSERT INTO `words` VALUES (5178, 'measures promoting local commerce and industry', 'n. 商业', '/\'kɒmɜ:s | \'kɑmɝs/', 'commerce', 2);
