INSERT INTO `words` VALUES (5180, 'a commission from the Academy for a new sculpture', 'n. 委托，委任；委托状', '/kə\'miʃən | kə\'mɪʃ(ə)n | kə\'mɪʃən/', 'commission', 2);
INSERT INTO `words` VALUES (5181, 'Women commit fewer crimes than men.', 'vt. 犯， 干； 使承诺； 把…托付给； 调拨…供使用， 拨出', '/kə\'mɪt/', 'commit', 2);
INSERT INTO `words` VALUES (5182, 'Are you ready to make a long-term commitment ?', 'n. 承诺', '/kə\'mitmənt | kə\'mɪtmənt/', 'commitment', 2);
INSERT INTO `words` VALUES (5183, 'a committee meeting', 'n. 委员会， 全体委员', '/kə\'mɪti/', 'committee', 2);
INSERT INTO `words` VALUES (5184, 'agricultural commodities', 'n. 商品', '/kə\'mɔditi | kə\'mɒdətɪ | kə\'mɑdəti/', 'commodity', 2);
INSERT INTO `words` VALUES (5185, 'Car thefts are commonplace in this part of town.', 'adj. 平凡的; n. 平常话', '/\'kɔmənpleis | \'kɒmənpleɪs | \'kɑmən\'ples/', 'commonplace', 2);
INSERT INTO `words` VALUES (5186, 'The judge\'s ruling was based on the simple commonsense tenet that no man is above the law.', 'adj. 有常识的', '/\'kɔmən\'sens/', 'commonsense', 2);
INSERT INTO `words` VALUES (5187, '...the Commonwealth of Australia.', 'n. 联邦', '/\'kɔmənwelθ | \'kɒmənwelθ | \'kɑmən\'wɛlθ/', 'commonwealth', 2);
INSERT INTO `words` VALUES (5188, 'A baby communicates its needs by crying.', 'v. 通讯， 交际， 交流； 连接， 相通； 传达， 传播； 传染', '/kə\'mjuːnɪkeɪt | kə\'mjunɪket/', 'communicate', 2);
INSERT INTO `words` VALUES (5189, 'Good communication is vital in a large organization.', 'n. 通讯， 交流， 交际； 通信工具， 交通联系', '/kəˌmjuːnɪ\'keɪʃn | kə,mjunɪ\'keʃən/', 'communication', 2);
INSERT INTO `words` VALUES (5190, 'The new arts centre will serve the whole community.', 'n. 社区， 社会， 公社； 团体， 界； 群落', '/kə\'mjuːnəti | kəˈmjunətɪ/', 'community', 2);
INSERT INTO `words` VALUES (5191, 'Baldry’s 20-year prison sentence was commuted to three years.', 'vi. 乘公交车上下班，经常乘车往返于两地; vt. 减； 折合， 折偿； 上下班交通', '/kə\'mjuːt | kə\'mjʊt/', 'commute', 2);
INSERT INTO `words` VALUES (5192, 'The bushes grew in a compact mass.', 'adj. 紧密的，紧凑的', '/kəm\'pækt, \'kɔmpækt | kəm\'pækt | \'kɑmpækt/', 'compact', 2);
INSERT INTO `words` VALUES (5193, 'For ten years he had been her constant companion .', 'n. 同伴， 共事者； 伴侣', '/kəm\'pæniən | kəm\'pænɪən/', 'companion', 2);
INSERT INTO `words` VALUES (5194, 'A car of comparable size would cost far more abroad.', 'adj. 可比较的；类似的', '/\'kɔmpərəbl | \'kɒmp(ə)rəb(ə)l | \'kɑmpərəbl/', 'comparable', 2);
INSERT INTO `words` VALUES (5195, 'The report compares the different types of home computer available.', 'vt. 比较， 对照； 把…比作', '/kəm\'peə | kəm\'pɛr/', 'compare', 2);
INSERT INTO `words` VALUES (5196, 'Her paintings invite comparison with those of the early Impressionists (= they remind you of them ) .', 'n. 比较， 对照； 比拟， 比喻', '/kəm\'pærɪsn/', 'comparison', 2);
INSERT INTO `words` VALUES (5197, 'The bag is divided into separate compartments .', 'n. 车厢, 隔间', '/kəm\'pɑ:tmənt | kəm\'pɑrtmənt/', 'compartment', 2);
INSERT INTO `words` VALUES (5198, 'The new software is IBM compatible (= can be used with IBM computers ) .', 'adj. 兼容的', '/kəm\'pætəbl | kəm\'pætɪb(ə)l/', 'compatible', 2);
INSERT INTO `words` VALUES (5199, '...the introduction of legislation to compel cyclists to wear a helmet.', 'v. 强迫', '/kəm\'pel | kəm\'pɛl/', 'compel', 2);
INSERT INTO `words` VALUES (5200, 'His life makes a compelling story .', 'adj. 引人注目的', '/kəm\'peliŋ | kəmˈpelɪŋ | kəm\'pɛlɪŋ/', 'compelling', 2);
INSERT INTO `words` VALUES (5201, 'Because my left eye is so weak, my right eye has to work harder to compensate.', 'v. 弥补', '/\'kɔmpenseit | \'kɒmpenseɪt | \'kɑmpɛnset/', 'compensate', 2);
INSERT INTO `words` VALUES (5202, 'People who are wrongly arrested may be paid compensation .', 'n. 补偿，赔偿，赔偿费', '/,kɔmpen\'seiʃən | kɒmpen\'seɪʃ(ə)n | ,kɑmpɛn\'seʃən/', 'compensation', 2);
INSERT INTO `words` VALUES (5203, 'The banks have long competed with American Express\'s charge cards and various shop cards.', 'vi. 比赛， 竞争， 对抗', '/kəm\'piːt | kəm\'pit/', 'compete', 2);
INSERT INTO `words` VALUES (5204, 'Typing is considered by most employers to be a basic competence.', 'n. 能力', '/\'kɔmpitəns | ˈkɒmpɪtəns | \'kɑmpɪtəns/', 'competence', 2);
INSERT INTO `words` VALUES (5205, 'A competent mechanic should be able to fix the problem.', 'adj. 能胜任的，有能力的', '/\'kɔmpitənt | ˈkɒmpɪtənt | \'kɑmpɪtənt/', 'competent', 2);
INSERT INTO `words` VALUES (5206, 'Going to trade fairs is an ideal opportunity to size up the competition .', 'n. 比赛； 竞争', '/ˌkɒmpə\'tɪʃn | ,kɑmpə\'tɪʃən/', 'competition', 2);
INSERT INTO `words` VALUES (5207, 'Competitive sports encourage children to work together as a team.', 'adj. 竞争的，比赛的', '/kəm\'petitiv | kəm\'petɪtɪv | kəm\'pɛtətɪv/', 'competitive', 2);
INSERT INTO `words` VALUES (5208, 'Last year they sold twice as many computers as their competitors.', 'n. 竞争者，敌手', '/kəm\'petitə | kəm\'petɪtə | kəm\'pɛtɪtɚ/', 'competitor', 2);
INSERT INTO `words` VALUES (5209, 'The document was compiled by the Department of Health.', 'vt. 汇编； 编制， 编纂', '/kəm\'paɪl/', 'compile', 2);
INSERT INTO `words` VALUES (5210, 'Miners have complained bitterly that the government did not fulfil their promises.', 'vi. 抱怨， 诉苦； 控告， 投诉', '/kəm\'pleɪn | kəm\'plen/', 'complain', 2);
INSERT INTO `words` VALUES (5211, 'If you wish to make a complaint, you should see the manager.', 'n. 抱怨，投诉', '/kəm\'pleint | kəmˈpleɪnt | kəm\'plent/', 'complaint', 2);
INSERT INTO `words` VALUES (5212, 'The green wallpaper is the perfect complement to the old pine of the dresser.', 'n. 补充', '/\'kɔmplimənt | ˈkɒmplɪment | ˈkɑːmplɪment/', 'complement', 2);
INSERT INTO `words` VALUES (5213, 'The house is nearing completion (= almost finished ) .', 'n. 完成，结束，完满', '/kəm\'pli:ʃən | kəm\'pliːʃn | kəm\'pliʃən/', 'completion', 2);
INSERT INTO `words` VALUES (5214, 'a complex system of highways', 'adj. 由许多部分组成的，复合的；复杂的，难懂的; n. 综合体， 集合体； 情结， 夸大的情绪反应', '/\'kɒmpleks | ˈkɑmplɛks;kəmˈplɛks/', 'complex', 2);
INSERT INTO `words` VALUES (5215, 'Drinking water is good for the complexion.', 'n. 肤色， 面色； 局面； 性质', '/kəm\'plekʃn | kəm\'plɛkʃən/', 'complexion', 2);
INSERT INTO `words` VALUES (5216, 'a design of great complexity', 'n. 复杂（性）', '/kəm\'pleksiti | kəm\'pleksətɪ | kəm\'plɛksəti/', 'complexity', 2);
INSERT INTO `words` VALUES (5217, 'a complicated pattern', 'adj. 复杂的', '/\'kɔmplikeitid | \'kɒmplɪkeɪtɪd | \'kɑmplɪketɪd/', 'complicated', 2);
INSERT INTO `words` VALUES (5218, 'The fact that the plane was late added a further complication to our journey.', 'n. 复杂，混乱；并发症', '/,kɔmpli\'keiʃən | kɒmplɪ\'keɪʃ(ə)n | ,kɑmplɪ\'keʃən/', 'complication', 2);
INSERT INTO `words` VALUES (5219, 'Compliments of the season! (= for Christmas or the New Year)', 'n. 致意，问候; v. 赞美，祝贺', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪmənt/', 'compliment', 2);
INSERT INTO `words` VALUES (5220, 'The commander said that the army would comply with the ceasefire.', 'v. 应允，遵照，照做', '/kəm\'plai | kəm\'plaɪ/', 'comply', 2);
INSERT INTO `words` VALUES (5221, 'Gorbachev failed to keep the component parts of the Soviet Union together.', 'adj. 组成的， 构成的; n. 组成部分，部件，组件', '/kəm\'pəunənt | kəm\'ponənt/', 'component', 2);
INSERT INTO `words` VALUES (5222, 'Barrington has composed the music for a new production of ‘A Midsummer Night’s Dream’.', 'vt. 组成， 构成； 创作， 为…谱曲； 使平静， 使镇静', '/kəm\'pəuz | kəm\'poz/', 'compose', 2);
INSERT INTO `words` VALUES (5223, '...music by Strauss, Mozart, Beethoven, and other great composers.', 'n. 作曲家', '/kəm\'pəuzə | kəm\'pəʊzə | kəm\'pozɚ/', 'composer', 2);
INSERT INTO `words` VALUES (5224, 'composite metals', 'adj. 合成的; n. 合成物', '/\'kɔmpəzit | \'kɒmpəzɪt | kɑm\'pɑzɪt/', 'composite', 2);
INSERT INTO `words` VALUES (5225, 'I had to write a composition about the Royal visit.', 'n. 作文', '/ˌkɒmpəˈzɪʃn | ,kɑmpə\'zɪʃən/', 'composition', 2);
INSERT INTO `words` VALUES (5226, '...the big compound eyes of dragonflies.', 'adj. 复合的，化合的; n. 化合物，复合物；复合词; vt. 使恶化， 加重； 使化合， 使合成', '/\'kɒmpaund | \'kɑmpaʊnd/', 'compound', 2);
INSERT INTO `words` VALUES (5227, 'She cannot comprehend the extent of the disaster.', 'v. 了解，理解，领会', '/,kɔmpri\'hend | kɒmprɪ\'hend | ,kɑmprɪ\'hɛnd/', 'comprehend', 2);
INSERT INTO `words` VALUES (5228, 'Why you let her talk you into doing such a foolish thing is beyond my comprehension (= impossible for me to understand ) .', 'n. 理解， 理解力， 领悟； 理解力测验', '/ˌkɒmprɪ\'henʃn | ,kɑmprɪ\'hɛnʃən/', 'comprehension', 2);
INSERT INTO `words` VALUES (5229, 'We offer our customers a comprehensive range of financial products.', 'adj. 综合的，全面的', '/,kɔmpri\'hensiv | ˌkɒmprɪˈhensɪv | ˌkɑːmprɪˈhensɪv/', 'comprehensive', 2);
INSERT INTO `words` VALUES (5230, 'the compression of air', 'n. 压缩，压紧，浓缩', '/kəm\'preʃən | kəm\'preʃ(ə)n | kəm\'prɛʃən/', 'compression', 2);
INSERT INTO `words` VALUES (5231, 'She admitted that she was unable to compromise.', 'v. 妥协；危害', '/\'kɔmprəmaiz | ˈkɒmprəmaɪz | \'kɑmprəmaɪz/', 'compromise', 2);
INSERT INTO `words` VALUES (5232, 'the threat of compulsory redundancies', 'adj. 强迫的，义务的', '/kəm\'pʌlsəri | kəm\'pʌls(ə)rɪ/', 'compulsory', 2);
INSERT INTO `words` VALUES (5233, 'Final results had not yet been computed.', 'v. 计算， 估算', '/kəm\'pjuːt | kəm\'pjʊt/', 'compute', 2);
INSERT INTO `words` VALUES (5234, '‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.', 'vi. 让步， 认输; vt. 承认，承认…为真；承认失败；允许，让予', '/kən\'siːd | kən\'sid/', 'concede', 2);
INSERT INTO `words` VALUES (5235, 'The conceit of the woman!', 'n. 自负，自高自大', '/kən\'si:t | kən\'siːt | kən\'sit/', 'conceit', 2);
INSERT INTO `words` VALUES (5236, 'He conceived the idea of transforming the old power station into an arts centre.', 'v. 设想，以为；怀孕', '/kən\'si:v | kən\'siːv | kən\'siv/', 'conceive', 2);
INSERT INTO `words` VALUES (5237, '...Although calls to share data often concentrate on the moral advantages of sharing...', 'v. 浓缩，提浓', '/\'kɔnsəntreit | \'kɒns(ə)ntreɪt | \'kɑnsn\'tret/', 'concentrate', 2);
INSERT INTO `words` VALUES (5238, 'She needed all her powers of concentration to stop herself from slipping on the icy road.', 'n. 集中； 专注， 专心； 浓缩； 浓度', '/ˌkɒnsn\'treɪʃn | \'kɑnsn\'treʃən/', 'concentration', 2);
INSERT INTO `words` VALUES (5239, 'a new concept in business travel', 'n. 概念， 观念； 设想', '/\'kɒnsept | \'kɑnsɛpt/', 'concept', 2);
INSERT INTO `words` VALUES (5240, 'the conception of parliamentary democracy', 'n. 概念，观念，想法', '/kən\'sepʃən | kən\'sepʃ(ə)n | kən\'sɛpʃən/', 'conception', 2);
INSERT INTO `words` VALUES (5241, 'One of the concerns that people have is the side effects of treatment.', 'n. 所关切的事；商行', '/kən\'sɜːn | kən\'sɝn/', 'concern', 2);
INSERT INTO `words` VALUES (5242, 'Britain has to pursue policies in concert with other EU members.', 'n. 一齐，一致，协作', '/kən\'sə:t, \'kɔnsə:t | \'kɒnsət | \'kɑnsɚt/', 'concert', 2);
INSERT INTO `words` VALUES (5243, 'He took off his jacket as a concession to the heat.', 'n. 妥协', '/kən\'seʃən | kən\'seʃn | kən\'sɛʃən/', 'concession', 2);
INSERT INTO `words` VALUES (5244, 'Your summary should be as clear and concise as possible.', 'adj. 简明的， 简要的', '/kən\'saɪs/', 'concise', 2);
INSERT INTO `words` VALUES (5245, 'When the investigation is concluded, the results will be sent to the US Attorney’s office.', 'vi. 结束， 终了; vt. 推断出，推论出；缔结，议定', '/kən\'kluːd | kən\'klud/', 'conclude', 2);
INSERT INTO `words` VALUES (5246, '...Recording ThreeA new study has failed to find any conclusive evidence that lifestyle changes can prevent cognitive decline in older adults...', 'adj. 得出结论的', '/kən\'klu:siv | kənˈklu:sɪv | kən\'klusɪv/', 'conclusive', 2);
INSERT INTO `words` VALUES (5247, 'What does that mean in concrete terms ?', 'adj. 具体的', '/kən\'kri:t, \'kɔnkri:t | \'kɒŋkri:t | \'kɑŋkrit/', 'concrete', 2);
INSERT INTO `words` VALUES (5248, 'Politicians were quick to condemn the bombing.', 'vt. 谴责， 指责； 判…刑， 宣告…有罪', '/kən\'dem | kən\'dɛm/', 'condemn', 2);
INSERT INTO `words` VALUES (5249, 'the mist which condensed on every cold surface', 'vt. 使冷凝， 使凝结； 浓缩， 压缩， 简缩', '/kən\'dens | kən\'dɛns/', 'condense', 2);
INSERT INTO `words` VALUES (5250, 'Aluminium, being a metal, readily conducts heat .', 'v. 引导，管理', '/\'kɔndʌkt, kən\'dʌkt | kən\'dʌkt/', 'conduct', 2);
INSERT INTO `words` VALUES (5251, 'The constitution also confers large powers on Brazil\'s 25 constituent states.', 'v. 授予', '/kən\'fə: | kənˈfɜ:(r) | kən\'fɝ/', 'confer', 2);
INSERT INTO `words` VALUES (5252, 'Representatives from over 100 countries attended the International Peace Conference in Geneva.', 'n. 会议， 讨论会； 讨论， 商谈', '/\'kɒnfərəns | \'kɑnfərəns/', 'conference', 2);
INSERT INTO `words` VALUES (5253, 'Occasionally people confess to crimes they haven’t committed just to get attention.', 'v. 承认', '/kən\'fes | kənˈfes | kən\'fɛs/', 'confess', 2);
INSERT INTO `words` VALUES (5254, 'I have never betrayed a confidence.', 'n. 私房话，秘密，机密', '/\'kɔnfidəns | \'kɒnfɪd(ə)ns | \'kɑnfɪdəns/', 'confidence', 2);
INSERT INTO `words` VALUES (5255, 'Despite her disability, Philippa is very confident.', 'adj. 确信的， 肯定的； 自信的', '/\'kɒnfɪdənt | \'kɑnfɪdənt/', 'confident', 2);
INSERT INTO `words` VALUES (5256, 'a confidential government report', 'adj. 机密的', '/,kɔnfi\'denʃəl | ˌkɒnfɪˈdenʃl | ,kɑnfɪ\'dɛnʃl/', 'confidential', 2);
INSERT INTO `words` VALUES (5257, '...Stonehenge, in southwestern England, an ancient configuration of giant stones.', 'n. 配置， 布局， 构造', '/kənˌfɪgə\'reɪʃn | kən,fɪɡjə\'reʃən/', 'configuration', 2);
INSERT INTO `words` VALUES (5258, 'Vaughan is confined to a wheelchair .', 'v. 限制', '/kənˈfaɪn | kən\'faɪn/', 'confine', 2);
INSERT INTO `words` VALUES (5259, 'New evidence has confirmed the first witness’s story.', 'vt. 证实， 肯定； 确认； 批准', '/kən\'fɜːm | kən\'fɝm/', 'confirm', 2);
INSERT INTO `words` VALUES (5260, 'There has still been no official confirmation of the report.', 'n. 证实，确定；确认', '/,kɔnfə\'meiʃən | kɒnfə\'meɪʃ(ə)n | ,kɑnfɚ\'meʃən/', 'confirmation', 2);
INSERT INTO `words` VALUES (5261, 'the threat of industrial conflict in the coalfields', 'n. 冲突', '/kən\'flikt, \'kɔnflikt | \'kɒnflɪkt | \'kɑnflɪkt/', 'conflict', 2);
INSERT INTO `words` VALUES (5262, 'The building does not conform with safety regulations.', 'v. 使遵守；一致', '/kən\'fɔ:m | kən\'fɔːm | kən\'fɔrm/', 'conform', 2);
INSERT INTO `words` VALUES (5263, 'We must act in conformity with local regulations.', 'n. 一致', '/kən\'fɔ:miti | kən\'fɔ:mɪtɪ | kən\'fɔrməti/', 'conformity', 2);
INSERT INTO `words` VALUES (5264, 'The problems confronting the new government were enormous.', 'v. 使面对；使对证', '/kən\'frʌnt/', 'confront', 2);
INSERT INTO `words` VALUES (5265, 'The committee\'s confrontational style of campaigning has made it unpopular.', 'adj. 对抗的，有敌意的', '/,kənfrən\'teiʃənl | ˌkɒnfrʌnˈteɪʃnl/', 'confrontational', 2);
INSERT INTO `words` VALUES (5266, 'To avoid confusion, the teams wore different colours.', 'n. 困惑， 糊涂； 混淆； 骚乱', '/kən\'fjuːʒn | kən\'fjʊʒən/', 'confusion', 2);
INSERT INTO `words` VALUES (5267, 'a congress of the ruling Labor Party', 'n. 代表大会； 国会， 议会', '/\'kɒŋgres | \'kɑŋɡrəs/', 'congress', 2);
INSERT INTO `words` VALUES (5268, 'Police have so far failed to establish a connection between the two murders.', 'n. 连接； 联系； 连接物， 连接点； 亲戚', '/kə\'nekʃn | kə\'nɛkʃən/', 'connection', 2);
INSERT INTO `words` VALUES (5269, 'The Normans conquered England in 1066.', 'v. 征服', '/\'kɔŋkə | ˈkɒŋkə(r) | \'kɑŋkɚ/', 'conquer', 2);
INSERT INTO `words` VALUES (5270, 'The people of an oppressed country obey their conquerors because they want to go on living.', 'n. 征服者，胜利者', '/\'kɔŋkərə | \'kɒŋk(ə)rə(r) | \'kɑŋkərɚ/', 'conqueror', 2);
INSERT INTO `words` VALUES (5271, 'A conscientious teacher may feel inclined to take work home.', 'adj. 有良心的，认真负责的', '/,kɔnʃi\'enʃəs | ,kɒnʃɪ\'enʃəs | \'kɑnʃɪ\'ɛnʃəs/', 'conscientious', 2);
INSERT INTO `words` VALUES (5272, 'The driver was still conscious when the ambulance arrived.', 'adj. 意识到的， 自觉的； 神志清醒的； 有意的， 存心的', '/\'kɒnʃəs | \'kɑnʃəs/', 'conscious', 2);
INSERT INTO `words` VALUES (5273, 'The painful memories eventually faded from her consciousness.', 'n. 意识；知觉', '/\'kɔnʃəsnis | \'kɒnʃəsnɪs | \'kɑnʃəsnəs/', 'consciousness', 2);
INSERT INTO `words` VALUES (5274, 'It had rained for four consecutive days.', 'adj. 连续的， 连贯的', '/kən\'sekjətɪv | kən\'sɛkjətɪv/', 'consecutive', 2);
INSERT INTO `words` VALUES (5275, 'The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.', 'n. 共识，一致', '/kən\'sensəs | kənˈsensəs | kən\'sɛnsəs/', 'consensus', 2);
INSERT INTO `words` VALUES (5276, 'The chairman was elected by common consent (= with most people agreeing ) .', 'n. 同意', '/kən\'sent | kənˈsent | kən\'sɛnt/', 'consent', 2);
INSERT INTO `words` VALUES (5277, 'I don’t suppose it is of any consequence now.', 'n. 重要（性），重大意义', '/\'kɔnsi,kwəns | \'kɒnsɪkw(ə)ns | \'kɑnsəkwɛns/', 'consequence', 2);
INSERT INTO `words` VALUES (5278, 'the rise in inflation and consequent fall in demand', 'adj. 作为结果的；必然的', '/\'kɔnsi,kwənt | \'kɒnsɪkw(ə)nt | \'kɑnsəkwənt/', 'consequent', 2);
INSERT INTO `words` VALUES (5279, 'Most computer users have never received any formal keyboard training. Consequently, their keyboard skills are inefficient.', 'adv. 因此， 因而， 所以', '/\'kɒnsɪkwəntli | \'kɑnsəkwɛntli/', 'consequently', 2);
INSERT INTO `words` VALUES (5280, 'wildlife conservation', 'n. 保护', '/,kɔnsə\'veiʃən | ˌkɒnsəˈveɪʃn | ,kɑnsɚ\'veʃən/', 'conservation', 2);
INSERT INTO `words` VALUES (5281, 'a very conservative attitude to education', 'adj. 保守的', '/kən\'sə:vətiv | kənˈsɜ:vətɪv | kən\'sɝvətɪv/', 'conservative', 2);
INSERT INTO `words` VALUES (5282, 'We must conserve our woodlands for future generations.', 'v. 保留，保护', '/kən\'sə:v, \'kɔnsə:v | kənˈsɜːv | kən\'sɝv/', 'conserve', 2);
INSERT INTO `words` VALUES (5283, 'Michael has already spent considerable time in Barcelona.', 'adj. 相当多的', '/kən\'sidərəbl | kənˈsɪdərəbl | kən\'sɪdərəbl/', 'considerable', 2);
INSERT INTO `words` VALUES (5284, 'I think he\'s the most charming, most considerate man I\'ve ever known.', 'adj. 考虑周到的， 体贴的， 体谅的', '/kən\'sɪdərət | kənˈsɪdərɪt/', 'considerate', 2);
INSERT INTO `words` VALUES (5285, 'My diet consisted almost exclusively of chocolate-covered cookies and glasses of milk.', 'vi. 由…组成； 在于； 一致', '/kən\'sɪst/', 'consist', 2);
INSERT INTO `words` VALUES (5286, 'She’s the team’s most consistent player.', 'adj. 一致的', '/kən\'sistənt | kənˈsɪstənt | kən\'sɪstənt/', 'consistent', 2);
INSERT INTO `words` VALUES (5287, 'No one could console her when Peter died.', 'v. 安慰', '/kən\'səul | kən\'səʊl | \'kɑnsol/', 'console', 2);
INSERT INTO `words` VALUES (5288, 'The company has consolidated its position as the country’s leading gas supplier.', 'v. 巩固；合并', '/kən\'sɔlideit | kən\'sɒlɪdeɪt | kən\'sɑlɪdet/', 'consolidate', 2);
INSERT INTO `words` VALUES (5289, 'The notice must be displayed in a conspicuous place.', 'adj. 显著的', '/kən\'spikjuəs | kənˈspɪkjuəs | kən\'spɪkjʊəs/', 'conspicuous', 2);
INSERT INTO `words` VALUES (5290, 'There was a constant stream of visitors to the house.', 'adj. 不断的', '/\'kɔnstənt | \'kɒnstənt | \'kɑnstənt/', 'constant', 2);
INSERT INTO `words` VALUES (5291, 'the EU and its constituent members', 'adj. 构成的; n. 选民', '/kən\'stitjuənt | kən\'stɪtjʊənt | kən\'stɪtʃuənt/', 'constituent', 2);
INSERT INTO `words` VALUES (5292, 'We must redefine what constitutes a family.', 'v. 构成，组成', '/\'kɔnstitju:t | \'kɒnstɪtjuːt | \'kɑnstətut/', 'constitute', 2);
INSERT INTO `words` VALUES (5293, 'She’s got a strong constitution – she’ll recover in no time.', 'n. （人的）体格，素质', '/kɒnstɪ\'tjuːʃ(ə)n | \'kɑnstə\'tʊʃən/', 'constitution', 2);
INSERT INTO `words` VALUES (5294, 'Poor soil has constrained the level of crop production.', 'v. 限制', '/kən\'strein | kən\'streɪn | kən\'stren/', 'constrain', 2);
INSERT INTO `words` VALUES (5295, 'the constraints of family life', 'n. 限制，束缚，约束', '/kən\'streint | kən\'streɪnt | kən\'strent/', 'constraint', 2);
INSERT INTO `words` VALUES (5296, 'There are plans to construct a new road bridge across the river.', 'vt. 建造； 构思; n. 建筑物； 构想； 观念', '/kən\'strʌkt/', 'construct', 2);
INSERT INTO `words` VALUES (5297, 'a road construction project', 'n. 建筑', '/kən\'strʌkʃən | kən\'strʌkʃn/', 'construction', 2);
INSERT INTO `words` VALUES (5298, 'the British Consul in Paris', 'n. 领事', '/\'kɔnsəl | \'kɒns(ə)l | \'kɑnsl/', 'consul', 2);
INSERT INTO `words` VALUES (5299, 'If symptoms persist, consult a doctor without delay.', 'v. 咨询', '/kɔn\'sʌlt, \'kɔnsʌlt | kən\'sʌlt/', 'consult', 2);
INSERT INTO `words` VALUES (5300, 'a management consultancy', 'n. 咨询', '/kən\'sʌltənsi | kən\'sʌltənsɪ/', 'consultancy', 2);
INSERT INTO `words` VALUES (5301, 'a management consultant', 'n. 顾问； 会诊医师， 专科医生', '/kən\'sʌltənt/', 'consultant', 2);
INSERT INTO `words` VALUES (5302, 'They retired to another room for private consultation.', 'n. 商议', '/,kɔnsəl\'teiʃən | ˌkɒnslˈteɪʃn | ,kɑnsl\'teʃən/', 'consultation', 2);
INSERT INTO `words` VALUES (5303, 'Some of the most efficient refrigerators consume 70 percent less electricity than traditional models.', 'vi. 消灭， 毁灭; vt. 消费；吃完，喝光', '/kən\'sjuːm | kənˈsum/', 'consume', 2);
INSERT INTO `words` VALUES (5304, 'Consumers will soon be paying higher airfares.', 'n. 消费者，用户', '/kən\'sju:mə | kən\'sjuːmə | kən\'sumɚ/', 'consumer', 2);
INSERT INTO `words` VALUES (5305, 'Vigorous exercise increases oxygen consumption.', 'n. 消费, 消耗', '/kən\'sʌmpʃən | kənˈsʌmpʃn/', 'consumption', 2);
INSERT INTO `words` VALUES (5306, 'The town is cut off from contact with the outside world.', 'n. 接触，联系，交往; vt. 与…接触， 与…取得联系', '/\'kɒntækt | \'kɑntækt/', 'contact', 2);
INSERT INTO `words` VALUES (5307, 'Drinking water supplies are believed to have been contaminated.', 'v. 污染，弄脏', '/kən\'tæmɪneɪt | kən\'tæmɪnet/', 'contaminate', 2);
INSERT INTO `words` VALUES (5308, 'However, contamination can occur at any point along the food chain, from field to table.', 'n. 污染', '/kən,tæmi\'neiʃən | kənˌtæmɪ\'neɪʃən/', 'contamination', 2);
INSERT INTO `words` VALUES (5309, 'He had even contemplated suicide.', 'vt. 盘算， 计议； 思量， 对…周密考虑； 注视， 凝视', '/\'kɒntempleɪt | \'kɑntəmplet/', 'contemplate', 2);
INSERT INTO `words` VALUES (5310, 'She writes a lot of contemporary music for people like Whitney Houston.', 'adj. 现代的， 当代的； 同时代的', '/kən\'temprəri | kən\'tɛmpərɛri/', 'contemporary', 2);
INSERT INTO `words` VALUES (5311, 'The public is treated with contempt by broadcasters.', 'n. 轻视， 蔑视', '/kən\'tempt | kən\'tɛmpt/', 'contempt', 2);
INSERT INTO `words` VALUES (5312, 'Inevitably, fights break out between the members of contending groups.', 'v. 竞争；坚决主张', '/kən\'tend | kən\'tɛnd/', 'contend', 2);
INSERT INTO `words` VALUES (5313, 'Andy was a good husband, and Nicky was clearly very content.', 'adj. 满意的', '/\'kɔntent | \'kɒntent | \'kɑntɛnt/', 'content', 2);
INSERT INTO `words` VALUES (5314, 'His case has become a source of contention between civil liberties activists and the government.', 'n. 争论', '/kən\'tenʃən | kənˈtenʃn | kən\'tɛnʃən/', 'contention', 2);
INSERT INTO `words` VALUES (5315, 'Stone decided to hold a contest to see who could write the best song.', 'n. 竞赛， 争夺; vt. 争夺， 与…竞争； 对…提出质疑， 辩驳', '/\'kɒntest | kən\'tɛst/', 'contest', 2);
INSERT INTO `words` VALUES (5316, 'Later he applied to be a contestant on the television show.', 'n. 参赛者', '/kən\'testənt | kənˈtestənt | kən\'tɛstənt/', 'contestant', 2);
INSERT INTO `words` VALUES (5317, 'The meaning of ‘mad’ depends on its context.', 'n. 上下文；来龙去脉', '/\'kɔntekst | \'kɒntekst | \'kɑntɛkst/', 'context', 2);
INSERT INTO `words` VALUES (5318, 'the warming-up of continental interiors', 'adj. 大陆的，大陆性的', '/,kɔnti\'nentəl | kɒntɪ\'nent(ə)l | ,kɑntɪ\'nɛntl/', 'continental', 2);
INSERT INTO `words` VALUES (5319, 'five weeks of continual rain', 'adj. 连续的； 频频的', '/kən\'tɪnjuəl/', 'continual', 2);
INSERT INTO `words` VALUES (5320, 'We should ensure continuity of care between hospital and home.', 'n. 连续， 持续', '/ˌkɒntɪ\'njuːəti | \'kɑntə\'nʊəti/', 'continuity', 2);
INSERT INTO `words` VALUES (5321, 'Metal contracts as it cools.', 'v. 缩小； 订合同； 感染， 染上; n. 契约， 合同', '/\'kɒntrækt | \'kɑntrækt/', 'contract', 2);
INSERT INTO `words` VALUES (5322, 'Deborah opened her mouth to contradict, but closed it again.', 'v. 反驳，否认', '/,kɔntrə\'dikt | kɒntrə\'dɪkt | \'kɑntrə\'dɪkt/', 'contradict', 2);
INSERT INTO `words` VALUES (5323, 'apparent contradictions in the defendant’s testimony', 'n. 矛盾， 不一致； 否认， 反驳', '/ˌkɒntrə\'dɪkʃn | ,kɑntrə\'dɪkʃən/', 'contradiction', 2);
INSERT INTO `words` VALUES (5324, 'Two contrary views emerged.', 'adj. 相反的', '/\'kɔntrəri | \'kɒntrərɪ | \'kɑntrɛri/', 'contrary', 2);
INSERT INTO `words` VALUES (5325, 'an essay comparing and contrasting (= showing how two things are similar and different ) Verdi and Wagner and their operas', 'v. 使对比；形成对比', '/kən\'trɑ:st, -\'træst, \'kɔntrɑ:st, -træst | \'kɒntrɑːst | \'kɑntræst/', 'contrast', 2);
INSERT INTO `words` VALUES (5326, 'The U.S. is contributing $4 billion in loans, credits, and grants.', 'v. 有助于', '/kən\'trɪbju:t | kən\'trɪbjut/', 'contribute', 2);
INSERT INTO `words` VALUES (5327, 'All the money has been raised by voluntary contribution.', 'n. 贡献', '/,kəntri\'bju:ʃən | ˌkɒntrɪˈbju:ʃn | ,kɑntrɪ\'bjuʃən/', 'contribution', 2);
INSERT INTO `words` VALUES (5328, 'The lawsuit says oil companies contrived the oil shortage in the 1970s.', 'vt. 谋划， 策划； 设法做到； 设计， 想出', '/kən\'traɪv/', 'contrive', 2);
INSERT INTO `words` VALUES (5329, 'the controversial issue of welfare reform', 'adj. 受到争议的', '/,kɔntrə\'və:ʃəl | kɒntrə\'vɜːʃ(ə)l | ,kɑntrə\'vɝʃl/', 'controversial', 2);
