INSERT INTO `words` VALUES (5480, 'Women who are dieting can become iron deficient.', 'adj. 不足的，缺乏的', '/di\'fiʃənt | dɪˈfɪʃnt | dɪ\'fɪʃnt/', 'deficient', 2);
