INSERT INTO `words` VALUES (5494, 'Instead, if you do not use your mental faculties, you accelerate the degeneration of cells and the loss of your cognitive abilities.', 'n. 退化，变质', '/di,dʒenə\'reiʃən | dɪ,dʒɛnə\'reʃən/', 'degeneration', 2);
