INSERT INTO `words` VALUES (5555, 'She hired a detective to find out if her husband was having an affair.', 'n. 侦探', '/di\'tektiv | dɪˈtektɪv | dɪ\'tɛktɪv/', 'detective', 2);
INSERT INTO `words` VALUES (5556, 'a smoke detector', 'n. 发觉者，探测器', '/dɪ\'tektə | dɪ\'tɛktɚ/', 'detector', 2);
INSERT INTO `words` VALUES (5557, 'Ethel’s health has deteriorated.', 'v. 恶化', '/di\'tiəriəreit | dɪˈtɪəriəreɪt | dɪ\'tɪrɪəret/', 'deteriorate', 2);
INSERT INTO `words` VALUES (5558, 'A reading over 50 indicates an expansion of activity in the manufacturing sector, while one below 50 suggests a deterioration.', 'n. 恶化，退化', '/di,tiəriə\'reiʃən | dɪ,tɪərɪə\'reɪʃn | dɪ,tɪrɪə\'reʃən/', 'deterioration', 2);
INSERT INTO `words` VALUES (5559, 'Investigators are still trying to determine the cause of the fire.', 'v. 决定', '/dɪˈtɜ:mɪn | dɪ\'tɝmɪn/', 'determine', 2);
INSERT INTO `words` VALUES (5560, 'Did you ever get the pictures developed ?', 'v. 使（底片）显影', '/di\'veləp | dɪ\'veləp | dɪ\'vɛləp/', 'develop', 2);
INSERT INTO `words` VALUES (5561, 'They stopped you as soon as you deviated from the script.', 'v. 偏离', '/\'di:vieit, \'di:viət | ˈdi:vieɪt | \'divɪet/', 'deviate', 2);
INSERT INTO `words` VALUES (5562, 'deviation from the normal procedure', 'n. 背离，偏离；偏差', '/,di:vi\'eiʃən | diːvɪ\'eɪʃ(ə)n | \'divɪ\'eʃən/', 'deviation', 2);
INSERT INTO `words` VALUES (5563, 'modern labour-saving devices', 'n. 器械， 装置； 设计； 手段， 策略', '/dɪ\'vaɪs/', 'device', 2);
INSERT INTO `words` VALUES (5564, 'She devised a method for quicker communications between offices.', 'vt. 设计， 发明', '/dɪ\'vaɪz/', 'devise', 2);
INSERT INTO `words` VALUES (5565, 'He decided to devote the rest of his life to scientific investigation.', 'vt. 将…奉献给， 把…专用', '/dɪ\'vəut | dɪ\'vot/', 'devote', 2);
INSERT INTO `words` VALUES (5566, 'her devotion to duty', 'n. 献身，热诚，专心', '/di\'vəuʃən | dɪ\'vəʊʃ(ə)n | dɪ\'voʃən/', 'devotion', 2);
INSERT INTO `words` VALUES (5567, 'The boys devoured their pancakes.', 'v. 吞食；吞灭，毁灭', '/dɪ\'vaʊə | dɪ\'vaʊɚ/', 'devour', 2);
INSERT INTO `words` VALUES (5568, 'How did they diagnose you?', 'v. 诊断', '/\'daiəɡnəuz, ,daiəɡ\'nəuz | ˈdaɪəgnəʊz | ,daɪəɡ\'nos/', 'diagnose', 2);
INSERT INTO `words` VALUES (5569, 'Federal funds have to be used as dictated by Washington.', 'v. [\'dIkteIt]; n. 口授； 命令， 规定， 要求', '/dɪk\'teɪt | \'dɪktet/', 'dictate', 2);
INSERT INTO `words` VALUES (5570, 'the downfall of the hated dictator', 'n. 独裁者，专政者', '/dik\'teitə, \'dikteitə | dɪk\'teɪtə | \'dɪktetɚ/', 'dictator', 2);
INSERT INTO `words` VALUES (5571, 'Our new car is a diesel.', 'n. 柴油发动机，内燃机', '/\'diːz(ə)l | \'dizl/', 'diesel', 2);
INSERT INTO `words` VALUES (5572, 'She doesn’t eat a very healthy diet.', 'n. 日常饮食，日常食物', '/\'daiət | \'daɪət/', 'diet', 2);
INSERT INTO `words` VALUES (5573, 'What differentiates these two periods of history?', 'vi. 区分，区别; vt. 区分， 区别； 使不同， 使有差异', '/ˌdɪfə\'renʃieɪt | ,dɪfə\'rɛnʃɪet/', 'differentiate', 2);
INSERT INTO `words` VALUES (5574, 'Excuse me each other a debate on the web, the virtual space, the interaction between people often with a mask, this month, the mirror with water flowers have what differentiation?', 'n. 区别', '/ˌdɪfəˌrenʃi\'eɪʃn | ,dɪfə,rɛnʃi\'eʃən/', 'differentiation', 2);
INSERT INTO `words` VALUES (5575, 'Don’t be so difficult!', 'adj. 难以满足的', '/\'difikəlt | \'dɪfɪk(ə)lt | \'dɪfɪkəlt/', 'difficult', 2);
INSERT INTO `words` VALUES (5576, 'Their ideas diffused quickly across Europe.', 'v. 扩散， 弥漫； 传播， 散布; adj. 冗长的， 漫无边际的； 四散的， 弥漫的', '/dɪ\'fjuːz | dɪ\'fjus/', 'diffuse', 2);
INSERT INTO `words` VALUES (5577, 'Most babies can digest a wide range of food easily.', 'vt. 消化， 领会; n. 文摘', '/daɪ\'dʒest; dɪ- | daɪ\'dʒɛst/', 'digest', 2);
INSERT INTO `words` VALUES (5578, 'We do this because we believe in the dignity and value of every person.', 'n. 庄重；尊严；体面', '/\'diɡnəti | \'dɪgnɪtɪ | \'dɪɡnəti/', 'dignity', 2);
INSERT INTO `words` VALUES (5579, 'a moral dilemma', 'n. 窘境， 困境', '/dɪ\'lemə | dəˈlɛmə, daɪ-/', 'dilemma', 2);
INSERT INTO `words` VALUES (5580, 'Genius is nothing but labor and diligence.', 'n. 勤奋', '/\'dilidʒəns | ˈdɪlɪdʒəns | \'dɪlɪdʒəns/', 'diligence', 2);
INSERT INTO `words` VALUES (5581, 'a diligent student', 'adj. 勤勉的， 勤奋的', '/\'dɪlɪdʒənt/', 'diligent', 2);
INSERT INTO `words` VALUES (5582, 'diluted fruit juice', 'v. 稀释，冲淡', '/dai\'lju:t, di- | daɪ\'l(j)ut/', 'dilute', 2);
INSERT INTO `words` VALUES (5583, 'in the dim light of the early dawn', 'adj. 暗淡的；愚蠢的', '/dim | dɪm/', 'dim', 2);
INSERT INTO `words` VALUES (5584, 'a rectangle with the dimensions 5cm × 2cm', 'n. 尺寸；维', '/daɪˈmenʃn | dɪ\'mɛnʃ(ə)n; daɪ-/', 'dimension', 2);
INSERT INTO `words` VALUES (5585, 'The party’s share of the electorate has diminished steadily.', 'v. 减少', '/di\'miniʃ | dɪ\'mɪnɪʃ/', 'diminish', 2);
INSERT INTO `words` VALUES (5586, 'He was dining with friends at the Ritz.', 'v. 吃饭', '/dain | daɪn/', 'dine', 2);
INSERT INTO `words` VALUES (5587, 'carbon/sulphur dioxide', 'n. 二氧化物', '/dai\'ɔksaid | daɪ\'ɒksaɪd | daɪ\'ɑksaɪd/', 'dioxide', 2);
INSERT INTO `words` VALUES (5588, 'a High School diploma', 'n. 毕业文凭，学位证书', '/di\'pləumə | dɪ\'pləʊmə | dɪ\'plomə/', 'diploma', 2);
INSERT INTO `words` VALUES (5589, 'French diplomats', 'n. 外交官， 外交家； 有交际手腕的人， 圆滑的人', '/\'dɪpləmæt/', 'diplomat', 2);
INSERT INTO `words` VALUES (5590, 'Diplomatic efforts to end the fighting began on October 25.', 'adj. 外交的；有策略的', '/,diplə\'mætik | dɪplə\'mætɪk | ,dɪplə\'mætɪk/', 'diplomatic', 2);
INSERT INTO `words` VALUES (5591, 'I couldn’t find your number in the telephone directory.', 'n. 姓名地址录', '/di\'rektəri, dai- | dɪ\'rekt(ə)rɪ; daɪ- | dəˈrɛktəri; (also) daɪˈrɛktəri/', 'directory', 2);
INSERT INTO `words` VALUES (5592, 'She did all this tendon damage and it really disabled her.', 'vt. 丧失能力， 伤残', '/dɪs\'eɪbl | dɪs\'ebl/', 'disable', 2);
INSERT INTO `words` VALUES (5593, 'Criminal behaviour can be linked to economic disadvantage.', 'n. 缺点，不利条件', '/disəd\'vɑ:ntidʒ | ˌdɪsəd\'vɑ:ntɪdʒ | ,dɪsəd\'væntɪdʒ/', 'disadvantage', 2);
INSERT INTO `words` VALUES (5594, 'We’ve had a few disagreements , but we’re still good friends.', 'n. 争论；不一致', '/,disə\'ɡri:mənt | dɪsə\'ɡriːmənt | ,dɪsə\'ɡrimənt/', 'disagreement', 2);
INSERT INTO `words` VALUES (5595, 'At this point the path seemed to disappear altogether (= disappear completely ) .', 'v. 消失', '/,disə\'piə | ˌdɪsə\'pɪə(r) | \'dɪsə\'pɪr/', 'disappear', 2);
INSERT INTO `words` VALUES (5596, 'Police are investigating the woman’s disappearance.', 'n. 消失，消散；失踪', '/,disə\'piərəns | dɪsə\'pɪərəns | ,dɪsə\'pɪrəns/', 'disappearance', 2);
INSERT INTO `words` VALUES (5597, 'His action had been greeted with almost universal disapproval.', 'n. 不赞成', '/ˌdɪsə\'pruːvl | \'dɪsə\'prʊvl/', 'disapproval', 2);
INSERT INTO `words` VALUES (5598, 'Getting the rebels to disarm will not be easy.', 'v. 解除，消除', '/dis\'ɑ:m | dɪs\'ɑ:m | dɪs\'ɑrm/', 'disarm', 2);
INSERT INTO `words` VALUES (5599, 'One hundred and twenty people died in China’s worst air disaster .', 'n. 灾难， 灾祸， 天灾； 彻底的失败', '/dɪ\'zɑːstə | dɪ\'zæstɚ/', 'disaster', 2);
INSERT INTO `words` VALUES (5600, 'a disastrous first marriage', 'adj. 灾难性的；悲惨的', '/di\'zɑ:strəs | dɪ\'zɑːstrəs | dɪ\'zæstrəs/', 'disastrous', 2);
INSERT INTO `words` VALUES (5601, 'Read the manufacturer\'s guidelines before discarding the box.', 'vt. 丢弃， 抛弃， 遗弃', '/dɪs\'kɑːd | dɪsˈkɑːrd/', 'discard', 2);
INSERT INTO `words` VALUES (5602, 'You need a long series of data to be able to discern such a trend.', 'v. 识别', '/di\'sə:n, -\'zə:n | dɪˈsɜ:n | dɪ\'sɝn/', 'discern', 2);
INSERT INTO `words` VALUES (5603, 'Hospitals now tend to discharge patients earlier than in the past.', 'v. 释放，排出；卸货; n. 释放， 放电', '/dɪs\'tʃɑːdʒ | dɪs\'tʃɑrdʒ/', 'discharge', 2);
INSERT INTO `words` VALUES (5604, 'We\'re looking for people from a wide range of disciplines.', 'n. 学科', '/\'disiplin | \'dɪsəplɪn/', 'discipline', 2);
INSERT INTO `words` VALUES (5605, 'Some companies have already voluntarily disclosed similar information .', 'vt. 揭露， 泄露， 透露', '/dɪs\'kləuz | dɪs\'kloz/', 'disclose', 2);
INSERT INTO `words` VALUES (5606, 'The family agreed to disconnect her life support system.', 'v. 断开', '/,diskə\'nekt | ˌdɪskə\'nekt | ,dɪskə\'nɛkt/', 'disconnect', 2);
INSERT INTO `words` VALUES (5607, 'They are often available at a discount.', 'n. 折扣; v. 打折扣卖', '/[\'diskaunt, dis\'k-] | \'dɪskaʊnt | dɪs\'kaʊnt/', 'discount', 2);
INSERT INTO `words` VALUES (5608, 'Aspirin may discourage tumour growth in some types of cancer.', 'v. 阻止；使气馁', '/dis\'kʌridʒ | dɪs\'kʌrɪdʒ | dɪs\'kɝɪdʒ/', 'discourage', 2);
INSERT INTO `words` VALUES (5609, 'a discourse on art', 'n. 讲话，演说，讲道', '/\'diskɔ:s, dis\'kɔ:s | \'dɪskɔːs; -\'kɔːs | \'dɪskɔrs/', 'discourse', 2);
INSERT INTO `words` VALUES (5610, 'He assured her that he would be discreet.', 'adj. 谨慎的， 慎重的， 审慎的', '/dɪ\'skriːt | dɪ\'skrit/', 'discreet', 2);
INSERT INTO `words` VALUES (5611, 'A modification of the common-origin theory accounts for the density discrepancy .', 'n. 不符合， 不一致', '/dɪs\'krepənsi | dɪs\'krɛpənsi/', 'discrepancy', 2);
INSERT INTO `words` VALUES (5612, 'The change happens in a series of discrete steps.', 'adj. 分离的， 不相关联的', '/dɪ\'skriːt | dɪ\'skrit/', 'discrete', 2);
INSERT INTO `words` VALUES (5613, 'He is incapable of discriminating between a good idea and a terrible one.', 'v. 歧视；区别', '/dɪ\'skrɪmɪneɪt | dɪ\'skrɪmɪnet/', 'discriminate', 2);
INSERT INTO `words` VALUES (5614, 'laws to prevent discrimination', 'n. 歧视', '/dis,krimi\'neiʃən | dɪˌskrɪmɪˈneɪʃn | dɪ,skrɪmɪ\'neʃən/', 'discrimination', 2);
INSERT INTO `words` VALUES (5615, 'His father died of heart disease.', 'n. 病， 疾病； 不健全， 弊端', '/dɪ\'ziːz | dɪ\'ziz/', 'disease', 2);
INSERT INTO `words` VALUES (5616, 'This policy of disengagement from the European war had its critics.', 'n. 分离，疏离感', '/disin\'ɡeidʒmənt | ˌdɪsɪn\'ɡeɪdʒmənt | ,dɪsɪn\'gedʒmənt/', 'disengagement', 2);
INSERT INTO `words` VALUES (5617, 'Smith faced total public disgrace after the incident.', 'n. 失宠，耻辱，丢脸', '/dis\'ɡreis | dɪs\'greɪs | dɪs\'ɡres/', 'disgrace', 2);
INSERT INTO `words` VALUES (5618, 'He escaped across the border disguised as a priest.', 'vt. 假扮，化装，伪装；掩盖，掩饰; n. 用来伪装的东西； 伪装， 掩饰', '/dɪs\'gaɪz | dɪs\'ɡaɪz/', 'disguise', 2);
INSERT INTO `words` VALUES (5619, 'He reached into the bin with a look of disgust on his face.', 'n&vt. 厌恶， 憎恶', '/dɪs\'gʌst | dɪs\'ɡʌst/', 'disgust', 2);
INSERT INTO `words` VALUES (5620, 'dishonest traders', 'adj. 不诚实的', '/dis\'ɔnist | dɪsˈɒnɪst | dɪs\'ɑnɪst/', 'dishonest', 2);
INSERT INTO `words` VALUES (5621, 'I hate to disillusion you, but I don’t think she’s coming back.', 'v. 觉醒，使觉醒', '/,disi\'lju:ʒən | ,dɪsɪ\'l(j)uːʒ(ə)n | ,dɪsɪ\'luʒn/', 'disillusion', 2);
INSERT INTO `words` VALUES (5622, 'The act or an instance of breaking up, as a division, dispersal, or disintegration.', 'n. 破裂， 分裂； 瓦解', '/dɪsˌɪntɪ\'greɪʃn | dɪs,ɪntə\'greʃən/', 'disintegration', 2);
INSERT INTO `words` VALUES (5623, 'Chris dismantled the bike in five minutes.', 'vt. 拆开， 拆卸', '/dɪs\'mæntl/', 'dismantle', 2);
INSERT INTO `words` VALUES (5624, 'The thought of leaving filled him with dismay .', 'n. 惊慌，沮丧，灰心', '/dis\'mei | dɪs\'meɪ | dɪs\'me/', 'dismay', 2);
INSERT INTO `words` VALUES (5625, 'Bryant was unfairly dismissed from his post.', 'v. 忽视', '/dɪs\'mɪs/', 'dismiss', 2);
INSERT INTO `words` VALUES (5626, 'severe eating disorders such as bulimia and anorexia', 'n. 疾病，小病', '/dɪs\'ɔːdə | dɪs\'ɔrdɚ/', 'disorder', 2);
INSERT INTO `words` VALUES (5627, 'Goods are normally dispatched within 24 hours.', 'v. 发送，派遣', '/dis\'pætʃ | dɪˈspætʃ | dɪ\'spætʃ/', 'dispatch', 2);
INSERT INTO `words` VALUES (5628, 'Part-time workers are considered dispensable.', 'adj. 可有可无的', '/dis\'pensəbl | dɪˈspensəbl | dɪ\'spɛnsəbl/', 'dispensable', 2);
INSERT INTO `words` VALUES (5629, 'Police used tear gas to disperse the crowd.', 'v. （使）分散；驱散', '/dis\'pə:s | dɪ\'spɜːs | dɪ\'spɝs/', 'disperse', 2);
INSERT INTO `words` VALUES (5630, 'Coal has been displaced by natural gas as a major source of energy.', 'v. 取代', '/dis\'pleis | dɪsˈpleɪs | dɪs\'ples/', 'displace', 2);
INSERT INTO `words` VALUES (5631, 'the displacement of traditional agriculture by industrial crops', 'n. 移置；免职；置换', '/dɪs\'pleɪsm(ə)nt | dɪs\'plesmənt/', 'displacement', 2);
INSERT INTO `words` VALUES (5632, 'a dazzling display (= very good display ) of flowers', 'n&vt. 陈列， 展览； 显示', '/dɪ\'spleɪ | dɪ\'sple/', 'display', 2);
INSERT INTO `words` VALUES (5633, 'disposable resources', 'adj. 可任意使用的; n. 一次性物品， 不回收物品', '/dɪ\'spəuzəbl | dɪ\'spozəbl/', 'disposable', 2);
INSERT INTO `words` VALUES (5634, 'bomb disposal experts', 'n. 支配；处理', '/dis\'pəuzəl | dɪˈspəʊzl | dɪ\'spozl/', 'disposal', 2);
INSERT INTO `words` VALUES (5635, 'Chinese vases are disposed around the gallery.', 'v. 去掉， 销毁； 处理， 解决； 使倾向于', '/dɪ\'spəuz | dɪ\'spoz/', 'dispose', 2);
INSERT INTO `words` VALUES (5636, 'the disposition of assets on death', 'n. 性情， 性格； 意向， 倾向； 排列， 部署', '/ˌdɪspə\'zɪʃn | \'dɪspə\'zɪʃən/', 'disposition', 2);
INSERT INTO `words` VALUES (5637, 'Johnson’s aversion to this tax was part of his reluctance to ask for any sacrifices for the Vietnam War -- except from the disproportionately blue-collar army that was fighting it.', 'adv. 比例不均地，不成比例地', '/,disprə\'pɔ:ʃənitli | ˌdɪsprə\'pɔ:ʃənətlɪ/', 'disproportionately', 2);
INSERT INTO `words` VALUES (5638, 'He ordered the jury to disregard the witness’s last statement.', 'v. 不管，不顾; n. 忽视', '/disri\'ɡɑ:d | dɪsrɪ\'gɑːd | ,dɪsrɪ\'ɡɑrd/', 'disregard', 2);
INSERT INTO `words` VALUES (5639, 'Traffic was disrupted by a hoax bomb.', 'vt. 使中断； 扰乱', '/dɪs\'rʌpt/', 'disrupt', 2);
INSERT INTO `words` VALUES (5640, '30% of customers expressed dissatisfaction with the service.', 'n. 不满，不平', '/\'dis,sætis\'fækʃən | dɪssætɪs\'fækʃn | dɪs\'sætɪs\'fækʃən/', 'dissatisfaction', 2);
INSERT INTO `words` VALUES (5641, 'He said the protesters were doing a disservice to the nation.', 'n. 帮倒忙，危害', '/,dis\'sə:vis | dɪsˈsɜ:vɪs | dɪs\'sɝvɪs/', 'disservice', 2);
INSERT INTO `words` VALUES (5642, 'As he thought it over, his anger gradually dissipated.', 'v. 驱散；消散；浪费', '/\'disipeit | \'dɪsɪpeɪt | \'dɪsɪpet/', 'dissipate', 2);
INSERT INTO `words` VALUES (5643, 'The monarch had the power to dissolve parliament.', 'v. 解除（婚约等）', '/di\'zɔlv | dɪ\'zɒlv | dɪ\'zɑlv/', 'dissolve', 2);
INSERT INTO `words` VALUES (5644, 'distilled water', 'vt. 蒸馏， 用蒸馏法提取； 吸取， 提炼', '/dɪ\'stɪl | dɪs\'tɪl/', 'distill', 2);
INSERT INTO `words` VALUES (5645, 'The outline of the ship became more distinct.', 'adj. 清楚的', '/dis\'tiŋkt | dɪ\'stɪŋ(k)t | dɪ\'stɪŋkt/', 'distinct', 2);
INSERT INTO `words` VALUES (5646, 'There are obvious distinctions between the two wine-making areas.', 'n. 区分', '/dis\'tiŋkʃən | dɪ\'stɪŋkʃən/', 'distinction', 2);
INSERT INTO `words` VALUES (5647, 'a rock band with a distinctive sound', 'adj. 与众不同的', '/dis\'tiŋktiv | dɪˈstɪŋktɪv | dɪ\'stɪŋktɪv/', 'distinctive', 2);
INSERT INTO `words` VALUES (5648, 'Speak clearly and distinctly.', 'adv. 显然，清楚地', '/dis\'tiŋktli | dɪ\'stɪŋ(k)tlɪ | dɪ\'stɪŋktli/', 'distinctly', 2);
INSERT INTO `words` VALUES (5649, 'The factor that distinguishes this company from the competition is customer service.', 'v. 使显出特色，使杰出', '/dis\'tiŋɡwiʃ | dɪ\'stɪŋgwɪʃ | dɪ\'stɪŋɡwɪʃ/', 'distinguish', 2);
INSERT INTO `words` VALUES (5650, 'His account was badly distorted by the press.', 'v. 扭曲', '/dis\'tɔ:t | dɪ\'stɔ:t | dɪ\'stɔrt/', 'distort', 2);
INSERT INTO `words` VALUES (5651, 'a distortion of the facts', 'n. 歪曲；畸变', '/dis\'tɔ:ʃən | dɪ\'stɔːʃ(ə)n | dɪs\'tɔrʃən/', 'distortion', 2);
INSERT INTO `words` VALUES (5652, 'Try not to distract the other students.', 'v. 分心，分散注意', '/dis\'trækt | dɪ\'strækt/', 'distract', 2);
INSERT INTO `words` VALUES (5653, 'a distribution centre', 'n. 分布，分配', '/,distri\'bju:ʃən | ˌdɪstrɪ\'bju:ʃn | \'dɪstrə\'bjʊʃən/', 'distribution', 2);
INSERT INTO `words` VALUES (5654, 'There were disturbances in the crowd as fans left the stadium.', 'n. 动乱；干扰', '/di\'stə:bəns | dɪ\'stɜːb(ə)ns | dɪ\'stɝbəns/', 'disturbance', 2);
INSERT INTO `words` VALUES (5655, 'The parallel lines appear to diverge.', 'v. 分岔；分歧', '/dai\'və:dʒ, di- | daɪ\'vɜːdʒ; dɪ- | daɪ\'vɝdʒ/', 'diverge', 2);
INSERT INTO `words` VALUES (5656, 'subjects as diverse as pop music and archaeology', 'adj. 各种各样的', '/dai\'və:s, di- | daɪˈvɜ:s | daɪ\'vɝs/', 'diverse', 2);
INSERT INTO `words` VALUES (5657, '...the illegal diversion of profits from secret arms sales.', 'n. 转移；娱乐', '/dai\'və:ʃən, di- | daɪˈvɜ:ʃn | dəˈvɝʒən; dəˈvɝʃən; daɪˈvɝʒən; daɪˈvɝʃən/', 'diversion', 2);
INSERT INTO `words` VALUES (5658, '...the cultural diversity of Latin America.', 'n. 多样性', '/dai\'və:səti | daɪ\'vɜ:sətɪ | dɪˈvəsɪti/', 'diversity', 2);
INSERT INTO `words` VALUES (5659, 'The high street is closed and traffic is being diverted .', 'v. 转移', '/dai\'və:t, di- | daɪ\'vɜ:t | dɪˈvɚt/', 'divert', 2);
INSERT INTO `words` VALUES (5660, 'You may get the dividend, but possibly not the capital appreciation.', 'n. 分红，红利', '/\'dɪvɪdend | \'dɪvɪdɛnd/', 'dividend', 2);
INSERT INTO `words` VALUES (5661, 'divine power', 'adj. 神的；敬神的', '/di\'vain | dɪ\'vaɪn/', 'divine', 2);
INSERT INTO `words` VALUES (5662, 'the traditional division of labour (= the way that particular tasks are shared ) between husband and wife', 'n. 分歧', '/dɪ\'vɪʒ(ə)n | də\'vɪʒən/', 'division', 2);
INSERT INTO `words` VALUES (5663, 'Why doesn’t she get a divorce ?', 'n. 离婚，离异; vt. 离婚； 分离， 脱离', '/dɪ\'vɔːs | dɪ\'vɔrs/', 'divorce', 2);
INSERT INTO `words` VALUES (5664, 'The heat and the champagne made him feel dizzy .', 'adj. 头晕眼花的，眩晕的', '/\'dizi | \'dɪzɪ | \'dɪzi/', 'dizzy', 2);
INSERT INTO `words` VALUES (5665, 'We docked at Rangoon the next morning.', 'v. 把…引入船坞', '/dɔk | dɒk | dɑk/', 'dock', 2);
INSERT INTO `words` VALUES (5666, 'traditional doctrines of divine power', 'n. 教义，主义；学说', '/\'dɔktrin | \'dɒktrɪn | \'dɑktrɪn/', 'doctrine', 2);
INSERT INTO `words` VALUES (5667, '...a TV documentary on homelessness.', 'n. 纪录片', '/,dɔkju\'mentəri | ˌdɒkjuˈmentri | \'dɑkjə\'mɛntri/', 'documentary', 2);
INSERT INTO `words` VALUES (5668, 'He ran across the courtyard, dodging a storm of bullets.', 'vi. 闪身躲开; vt. 回避，逃避; n. 托辞， 伎俩； 躲闪， 躲避', '/dɒdʒ | dɑdʒ/', 'dodge', 2);
INSERT INTO `words` VALUES (5669, 'The number claiming dole went up by 3,500.', 'n. 救济，救济金; vt. 发放， 发给', '/dəul | dol/', 'dole', 2);
INSERT INTO `words` VALUES (5670, 'By hunting or gathering away from the group, both chimpanzee and dolphin moms ensure that what they find goes to their young.', 'n. 海豚', '/\'dɔlfin | \'dɒlfɪn | \'dɑlfɪn/', 'dolphin', 2);
INSERT INTO `words` VALUES (5671, 'Looking after the house was viewed as a woman’s domain.', 'n. 领域', '/dəu\'mein | dəˈmeɪn | do\'men/', 'domain', 2);
INSERT INTO `words` VALUES (5672, '...the dome of the Capitol.', 'n. 圆屋顶，拱顶', '/dəum | dəʊm | dom/', 'dome', 2);
INSERT INTO `words` VALUES (5673, '...over 100 domestic flights a day to 30 leading U.S. destinations.', 'adj. 国内的', '/dəu\'mestik | dəˈmestɪk | də\'mɛstɪk/', 'domestic', 2);
INSERT INTO `words` VALUES (5674, 'The firm has achieved a dominant position in the world market.', 'adj. 统治的; n. 主因', '/\'dɔminənt | \'dɒmɪnənt | \'dɑmɪnənt/', 'dominant', 2);
INSERT INTO `words` VALUES (5675, 'The industry is dominated by five multinational companies.', 'v. 主导，主宰', '/\'dɔmineit | \'dɒmɪneɪt | \'dɑmɪnet/', 'dominate', 2);
INSERT INTO `words` VALUES (5676, 'people who volunteer to donate blood', 'vt. 捐赠， 赠送', '/dəu\'neɪt | \'donet/', 'donate', 2);
INSERT INTO `words` VALUES (5677, 'There have been generous donations from EU funds.', 'n. 捐款， 捐赠物； 捐赠， 赠送', '/dəu\'neɪʃn | do\'neʃən/', 'donation', 2);
INSERT INTO `words` VALUES (5678, 'We urgently need more assistance from donor countries (= countries that give money, food etc to help in poor countries or disaster areas ) .', 'n. 捐赠者', '/\'dəunə | ˈdəʊnə(r) | \'donɚ/', 'donor', 2);
INSERT INTO `words` VALUES (5679, 'A sense of impending doom (= coming very soon ) gripped her.', 'n. 厄运，毁灭; v. 注定', '/du:m | duːm | dʊm/', 'doom', 2);
INSERT INTO `words` VALUES (5680, 'But I had no food in my dorm, so I had to go to canteen.', 'n. 宿舍', '/dɔ:m | dɔrm/', 'dorm', 2);
INSERT INTO `words` VALUES (5681, 'Doubtless there would be lots of rumours.', 'adv. 无疑地；很可能', '/\'dautlis | \'daʊtlɪs | \'daʊtləs/', 'doubtless', 2);
INSERT INTO `words` VALUES (5682, 'A dove cooed softly.', 'n. 鸽子，斑鸠', '/dʌv | dʌv; dov/', 'dove', 2);
INSERT INTO `words` VALUES (5683, 'the rough draft of his new novel', 'n. 草稿；汇票；征兵；通风; vt. 起草； 征募', '/drɑːft | dræft/', 'draft', 2);
INSERT INTO `words` VALUES (5684, 'He grabbed her arm and dragged her into the room.', 'v. 拖，拉；迫使，硬拉；拖着脚步走; n. 累赘； 一吸， 一抽', '/dræg/', 'drag', 2);
INSERT INTO `words` VALUES (5685, 'I watched the bath water drain away.', 'v. （水等）流掉', '/drein | dreɪn | dren/', 'drain', 2);
INSERT INTO `words` VALUES (5686, 'A handful of pebbles in the bottom of a flowerpot will help drainage.', 'n. 排水；下水道', '/\'dreinidʒ | \'dreɪnɪdʒ | \'drenɪdʒ/', 'drainage', 2);
INSERT INTO `words` VALUES (5687, 'Maggie’s life is always full of drama.', 'n. 戏剧性事件；戏剧性', NULL, 'drama', 2);
INSERT INTO `words` VALUES (5688, 'A superb goal by Owen earned United a dramatic victory yesterday.', 'adj. 引人注目的， 激动人心的； 戏剧的', '/drə\'mætɪk/', 'dramatic', 2);
INSERT INTO `words` VALUES (5689, '...cities and homes will dramatically improve our quality of life in the years ahead...', 'adv. 大幅度地；戏剧性地', '/drə\'mætɪklɪ | drə\'mætɪkli/', 'dramatically', 2);
INSERT INTO `words` VALUES (5690, 'drastic cuts in government spending', 'adj. 激烈的；严厉的', '/\'dræstik | \'dræstɪk; \'drɑː- | \'dræstɪk/', 'drastic', 2);
INSERT INTO `words` VALUES (5691, NULL, 'adv. 激烈地，猛烈地', '/\'dræstikəli | \'drɑ:stɪklɪ/', 'drastically', 2);
INSERT INTO `words` VALUES (5692, 'It’s a great city – the only drawback is the weather.', 'n. 妨碍；弊端', '/\'drɔ:bæk | \'drɔːbæk | \'drɔbæk/', 'drawback', 2);
INSERT INTO `words` VALUES (5693, 'I’ve got an interview tomorrow and I’m dreading it.', 'vt. 担忧，忧虑；惧怕; n. 担忧， 畏惧', '/dred | drɛd/', 'dread', 2);
INSERT INTO `words` VALUES (5694, 'a dreadful accident', 'adj. 可怕的；令人畏惧的', '/\'dredful | \'dredfʊl; -f(ə)l | \'drɛdfəl/', 'dreadful', 2);
INSERT INTO `words` VALUES (5695, 'Smoke drifted up from the jungle ahead of us.', 'v. 漂流', '/drift | drɪft/', 'drift', 2);
INSERT INTO `words` VALUES (5696, 'Drill a hole in each corner.', 'v. 钻， 打； 训练; n. 钻头；操练，训练', '/drɪl/', 'drill', 2);
INSERT INTO `words` VALUES (5697, 'a high school dropout', 'n. 辍学', '/\'drɔpaut | ˈdrɒpaʊt | \'drɑpaʊt/', 'dropout', 2);
INSERT INTO `words` VALUES (5698, '...a country where drought and famines have killed up to two million people during the last eighteen years.', 'n. 干旱', '/draut | draʊt/', 'drought', 2);
INSERT INTO `words` VALUES (5699, 'Many people drowned when the boat overturned.', 'v. 溺水', '/draun | draʊn/', 'drown', 2);
INSERT INTO `words` VALUES (5700, 'He was a drummer in a rock band.', 'n. 鼓手', '/\'drʌmə | ˈdrʌmə(r) | \'drʌmɚ/', 'drummer', 2);
INSERT INTO `words` VALUES (5701, 'Government reports tend to make dry reading.', 'adj. 干巴巴的，枯燥的', '/drai | draɪ/', 'dry', 2);
INSERT INTO `words` VALUES (5702, 'a dual system of education', 'adj. 双的， 两重的', '/\'djuːəl | \'dʊəl/', 'dual', 2);
INSERT INTO `words` VALUES (5703, 'Today\'s session has been widely dubbed as a \"make or break\" meeting.', 'vt. 给…起绰号， 把…称为； 为配音， 译制', '/dʌb/', 'dub', 2);
INSERT INTO `words` VALUES (5704, 'The firm was accused of dubious accounting practices.', 'adj. 怀疑的， 犹豫不决的， 无把握的； 有问题的； 靠不住的', '/\'djuːbjəs | \'dubɪəs/', 'dubious', 2);
INSERT INTO `words` VALUES (5705, 'the Duke of Edinburgh', 'n. 公爵；君主', '/dju:k, du:k | djuːk | dʊk/', 'duke', 2);
INSERT INTO `words` VALUES (5706, 'She kept both the duplicate and the original.', 'n. 副本，复制品', '/\'dju:plikət, \'dju:plikeit | ˈdjuːplɪkeɪt | \'duplɪket/', 'duplicate', 2);
INSERT INTO `words` VALUES (5707, 'There could be a serious loss of efficiency through unnecessary duplication of resources.', 'n. 复制品', '/,dju:pli\'keiʃən | ˌdjuːplɪˈkeɪʃn | ,djʊplɪ\'keʃən/', 'duplication', 2);
INSERT INTO `words` VALUES (5708, 'All the furniture was covered in dust.', 'n. 灰尘', '/dʌst/', 'dust', 2);
INSERT INTO `words` VALUES (5709, 'a dutiful son', 'adj. 恭敬顺从的； 尽职的', '/\'djuːtɪfl | \'dʊtɪfəl/', 'dutiful', 2);
INSERT INTO `words` VALUES (5710, 'a dwarf conifer', 'n. 矮子，侏儒', '/dwɔ:f | dwɔːf | dwɔrf/', 'dwarf', 2);
INSERT INTO `words` VALUES (5711, 'They dwelt in the forest.', 'v. 居住；凝思，细想', '/dwel | dwɛl/', 'dwell', 2);
INSERT INTO `words` VALUES (5712, 'City dwellers suffer higher pollution levels.', 'n. 居住者', '/\'dwelə | ˈdwelə(r) | \'dwɛlɚ/', 'dweller', 2);
INSERT INTO `words` VALUES (5713, 'dynamic and ambitious people', 'adj. 动力的， 动力学的； 动态的； 有活力的， 有生气的', '/daɪ\'næmɪk/', 'dynamic', 2);
INSERT INTO `words` VALUES (5714, 'And our goal is to find out the time, the dynamics of this problem.', 'n. 动力学', '/dai\'næmiks | daɪ\'næmɪks/', 'dynamics', 2);
INSERT INTO `words` VALUES (5715, 'bicycle lights powered by a dynamo', 'n. 发电机', '/\'dainəməu | \'daɪnəməʊ | \'daɪnəmo/', 'dynamo', 2);
INSERT INTO `words` VALUES (5716, NULL, 'n. 失灵', '/dis\'fʌŋkʃən | dɪs\'fʌŋkʃn | dɪs\'fʌŋkʃən/', 'dysfunction', 2);
INSERT INTO `words` VALUES (5717, 'The eagle plumed its wing.', 'n. 鹰', '/\'iːgl | \'igl/', 'eagle', 2);
INSERT INTO `words` VALUES (5718, 'an ear of corn', 'n. （稻麦等的）穗', '/iə | ɪə | ɪr/', 'ear', 2);
INSERT INTO `words` VALUES (5719, 'an employee’s average weekly earnings', 'n. 工资，收入；收益', '/\'ə:niŋz | \'ɜːnɪŋz | \'ɝnɪŋz/', 'earnings', 2);
INSERT INTO `words` VALUES (5720, '...colourful Italian china and earthenware.', 'n. 陶器', '/\'ə:θənwεə | \'ɜːθ(ə)nweə | \'ɝθnwɛr/', 'earthenware', 2);
INSERT INTO `words` VALUES (5721, 'on Easter Sunday', 'n. 复活节', '/\'iːstə | istəʳ/', 'Easter', 2);
INSERT INTO `words` VALUES (5722, 'A powerful snow storm is moving eastward.', 'adv. 向东', '/\'i:stwəd | \'iːstwəd | \'istwɚdz/', 'eastward', 2);
INSERT INTO `words` VALUES (5723, 'His eccentric behaviour lost him his job.', 'adj. 古怪的', '/ik\'sentrik | ɪkˈsentrɪk | ɪk\'sɛntrɪk/', 'eccentric', 2);
INSERT INTO `words` VALUES (5724, 'The sound of an engine echoed back from the thick forest.', 'v. 随声附和，发出回声', '/\'ekəu | \'ekəʊ | \'ɛko/', 'echo', 2);
INSERT INTO `words` VALUES (5725, 'an eclipse of the sun', 'n. （日，月）食', '/ɪk\'lɪps | ɪ\'klɪps/', 'eclipse', 2);
INSERT INTO `words` VALUES (5726, 'an ecological disaster', 'adj. 生态学的', '/,i:kə\'lɔdʒikəl, ,ekə-,-\'lɔdʒik | ˌi:kəˈlɒdʒɪkl | \'ikə\'lɑdʒɪkl/', 'ecological', 2);
INSERT INTO `words` VALUES (5727, 'the natural ecology of the Earth', 'n. 生态学；个体生态学', '/i:\'kɔlədʒi | ɪ\'kɒlədʒɪ; e- | ɪ\'kɑlədʒi/', 'ecology', 2);
INSERT INTO `words` VALUES (5728, 'Economic growth is slow.', 'adj. 经济的；经济学的; n. 经济学； 经济状况', '/ˌiːkə\'nɒmɪk | ˌikəˈnɑmɪk, ˌɛkəˈ-nɑmɪk/', 'economic', 2);
INSERT INTO `words` VALUES (5729, 'A small car is more economical to run.', 'adj. 节约的； 经济学的', '/ˌiːkə\'nɒmɪkl | ,ɛkə\'nɑmɪkl/', 'economical', 2);
INSERT INTO `words` VALUES (5730, 'In economically advanced countries, women marry later.', 'adv. 在经济上；节约地', '/,i:kə\'nɔmikəli | iːkə\'nɒmɪklɪ | ,ikə\'nɑmɪkli/', 'economically', 2);
INSERT INTO `words` VALUES (5731, 'a Harvard professor of economics', 'n. 经济学；经济', '/,i:kə\'nɔmiks | iːkə\'nɒmɪks; ek- | \'ikə\'nɑmɪks; \'ɛkə\'nɑmɪks/', 'economics', 2);
INSERT INTO `words` VALUES (5732, 'The council must make economies to meet government spending targets.', 'n. 经济； 节约， 节省', '/i\'kɒnəmi | ɪˈkɑnəmɪ/', 'economy', 2);
INSERT INTO `words` VALUES (5733, '...the forest ecosystem.', 'n. 生态系统', '/\'i:kəu,sistəm, \'ekəu- | \'iːkəʊsɪstəm | \'ɛko,sɪstəm/', 'ecosystem', 2);
INSERT INTO `words` VALUES (5734, 'These berries are edible, but those are poisonous.', 'adj. 可以吃的， 可食用的', '/\'edəbl | \'ɛdəbl/', 'edible', 2);
INSERT INTO `words` VALUES (5735, 'The newspaper edits letters before printing them.', 'v. 剪辑，编辑', '/\'edit | \'edɪt | \'ɛdɪt/', 'edit', 2);
INSERT INTO `words` VALUES (5736, 'In an editorial, The New York Times suggests the victory could turn nasty.', 'n. 社论，期刊的社论', '/,edi\'tɔ:riəl | edɪ\'tɔːrɪəl | ,ɛdɪ\'tɔrɪəl/', 'editorial', 2);
INSERT INTO `words` VALUES (5737, 'the educational development of children', 'adj. 教育的， 教育性的', '/ˌedʒu\'keɪʃənl | ,ɛdʒu\'keʃənl/', 'educational', 2);
INSERT INTO `words` VALUES (5738, 'The cheaper drugs are just as effective in treating arthritis.', 'adj. 有效的； 有影响的', '/ɪ\'fektɪv | ɪ\'fɛktɪv/', 'effective', 2);
INSERT INTO `words` VALUES (5739, 'considerable advancements in energy efficiency', 'n. 效率； 功效， 效能', '/ɪ\'fɪʃnsi | ɪˈfɪʃənsɪ/', 'efficiency', 2);
INSERT INTO `words` VALUES (5740, 'a very efficient secretary', 'adj. 效率高的； 有能力的', '/ɪ\'fɪʃnt/', 'efficient', 2);
INSERT INTO `words` VALUES (5741, 'That promotion really boosted her ego (= made her feel better about herself ).', 'n. 自我， 自己， 自尊', '/\'iːgəu | \'iɡo/', 'ego', 2);
INSERT INTO `words` VALUES (5742, '...the Egyptian pharaoh.', 'adj. 埃及的; n. 埃及人', '/i\'dʒipʃən | ɪ\'dʒɪpʃ(ə)n/', 'Egyptian', 2);
INSERT INTO `words` VALUES (5743, 'The demonstrators were ejected from the hall.', 'v. 逐出，排斥；喷射', '/i\'dʒekt, \'i:dʒekt | ɪ\'dʒekt | ɪ\'dʒɛkt/', 'eject', 2);
INSERT INTO `words` VALUES (5744, 'pure silks embroidered with elaborate patterns', 'adj. 复杂的； 精心制作的; v. 详述， 详细制定', '/ɪ\'læb(ə)rət | ɪ\'læbəret/', 'elaborate', 2);
INSERT INTO `words` VALUES (5745, 'He elaborately devised a new computer.', 'adv. 复杂地，精心设计地', '/i\'læbərətli | ɪ\'læbərətlɪ | ɪ\'læbərɪtli/', 'elaborately', 2);
INSERT INTO `words` VALUES (5746, 'Several months elapsed before his case was brought to trial.', 'v. （时间）过去，消逝', '/i\'læps | ɪ\'læps/', 'elapse', 2);
INSERT INTO `words` VALUES (5747, 'the horny elastic pad in a horse’s hoof', 'adj. 有弹性的； 灵活的; n. 松紧带', '/ɪ\'læstɪk/', 'elastic', 2);
INSERT INTO `words` VALUES (5748, 'She pushed through the crowd, elbowing people out of the way.', 'v. 用肘挤，挤进', '/\'elbəu | \'elbəʊ | \'ɛlbo/', 'elbow', 2);
INSERT INTO `words` VALUES (5749, 'The Labour Party won the 2001 election by a huge majority.', 'n. 选举', '/i\'lekʃən | ɪ\'lekʃn | ɪ\'lɛkʃən/', 'election', 2);
INSERT INTO `words` VALUES (5750, 'an electric blanket', 'adj. 电的， 电动的', '/ɪ\'lektrɪk | ɪ\'lɛktrɪk/', 'electric', 2);
INSERT INTO `words` VALUES (5751, 'The fire was caused by an electrical fault.', 'adj. 电的； 电气科学的', '/ɪ\'lektrɪkl | ɪ\'lɛktrɪkl/', 'electrical', 2);
INSERT INTO `words` VALUES (5752, 'The electrician refitted my old radio set.', 'n. 电工，电气技师', '/,ilek\'triʃən | ,ɪlek\'trɪʃ(ə)n; ,el-; ,iːl- | ɪ\'lɛk\'trɪʃən/', 'electrician', 2);
INSERT INTO `words` VALUES (5753, 'The farm was very isolated, but it had electricity.', 'n. 电', '/ɪˌlek\'trɪsəti | ɪ\'lɛk\'trɪsəti/', 'electricity', 2);
INSERT INTO `words` VALUES (5754, 'She would sit at the piano and sing, electrifying us all.', 'vt. 使充电， 使电气化； 使激动， 使兴奋', '/ɪ\'lektrɪfaɪ | ɪ\'lɛktrə\'fai/', 'electrify', 2);
INSERT INTO `words` VALUES (5755, 'The monkeys have electrodes implanted into the brain to measure their brain activity.', 'n. 电极；电焊条', '/ɪ\'lektrəʊd | ɪ\'lɛktrod/', 'electrode', 2);
INSERT INTO `words` VALUES (5756, 'Most things are balanced - with equal numbers of electrons and protons.', 'n. 电子', '/ɪ\'lektrɒn | ɪ\'lɛktrɑn/', 'electron', 2);
INSERT INTO `words` VALUES (5757, 'electronic games', 'adj. 电子的; n. 电子学； 电子设备', '/ɪˌlek\'trɒnɪk | ɪˌlɛkˈtrɑnɪk/', 'electronic', 2);
INSERT INTO `words` VALUES (5758, 'an electronics engineer', 'n. 电子学', '/,ilek\'trɔniks | ɪlek\'trɒnɪks; el- | ɪ,lɛk\'trɑnɪks/', 'electronics', 2);
INSERT INTO `words` VALUES (5759, 'a tall, elegant young woman', 'adj. 高雅的，雅致的', '/\'elɪg(ə)nt | \'ɛləgənt/', 'elegant', 2);
INSERT INTO `words` VALUES (5760, 'Business and management elements are built into the course.', 'n. 成分， 要素， 元素； 基础， 纲要； 自然力', '/\'elɪmənt | \'ɛləmənt/', 'element', 2);
INSERT INTO `words` VALUES (5761, 'Love and fear are two of the most elemental human emotions.', 'adj. 基本的；自然力的', '/,eli\'mentəl | ,elɪ\'ment(ə)l | ,ɛlɪ\'mɛntl/', 'elemental', 2);
INSERT INTO `words` VALUES (5762, 'the elementary principles of justice and democracy', 'adj. 基本的， 初级的', '/ˌelɪ\'mentri | ,ɛlɪ\'mɛntri/', 'elementary', 2);
INSERT INTO `words` VALUES (5763, 'Language has elevated humans above the other animals.', 'v. 提升，举起；使高兴', '/\'eliveit | \'elɪveɪt | \'ɛlɪvet/', 'elevate', 2);
INSERT INTO `words` VALUES (5764, 'The city is at an elevation of 2 000 metres.', 'n. 高度，海拔', '/,eli\'veiʃən | ,elɪ\'veɪʃ(ə)n | ,ɛlɪ\'veʃən/', 'elevation', 2);
INSERT INTO `words` VALUES (5765, 'My letters to her have elicited no response.', 'vt. 诱出， 探出', '/i\'lɪsɪt | ɪ\'lɪsɪt/', 'elicit', 2);
INSERT INTO `words` VALUES (5766, 'Stephen was regarded as an eligible bachelor.', 'adj. 适合的；胜任的', '/\'elidʒəbl | ˈelɪdʒəbl | \'ɛlɪdʒəbl/', 'eligible', 2);
INSERT INTO `words` VALUES (5767, 'a ruthless dictator who eliminated all his rivals', 'v. 消除', '/i\'limineit | ɪ\'lɪmɪneɪt | ɪ\'lɪmɪnet/', 'eliminate', 2);
INSERT INTO `words` VALUES (5768, 'If you need to remove an agent you will have to do it by a process of elimination.', 'n. 消除，淘汰', '/i,limi\'neiʃən | ɪ,lɪmɪ\'neɪʃən | ɪ,lɪmə\'neʃən/', 'elimination', 2);
INSERT INTO `words` VALUES (5769, 'a struggle for power within the ruling elite', 'n. 精英', '/ei\'li:t, i\'li:t | eɪ\'li:t | ɪˈliːt/', 'elite', 2);
INSERT INTO `words` VALUES (5770, 'Kepler published his discovery of the elliptical orbits of planets in 1609. 1609', 'adj. 椭圆的；省略的', '/i\'liptik,-kəl | ɪ\'lɪptɪk(ə)l | ɪ\'lɪptɪkl/', 'elliptical', 2);
INSERT INTO `words` VALUES (5771, 'a speech of passionate eloquence', 'n. 雄辩；口才，修辞', '/\'eləkwəns | \'ɛləkwəns/', 'eloquence', 2);
INSERT INTO `words` VALUES (5772, 'an eloquent appeal for support', 'adj. 口才好的，雄辩的', '/\'eləkwənt | ˈeləkwənt | \'ɛləkwənt/', 'eloquent', 2);
INSERT INTO `words` VALUES (5773, 'He\'s embarking on a new career as a writer.', 'vi. 上船； 着手， 开始工作', '/ɪm\'bɑːk | ɪm\'bɑrk/', 'embark', 2);
INSERT INTO `words` VALUES (5774, 'The speech was deliberately designed to embarrass the prime minister.', 'v. 使…陷入困境', '/im\'bærəs | ɪm\'bærəs; em- | ɪm\'bærəs/', 'embarrass', 2);
INSERT INTO `words` VALUES (5775, 'the American Embassy in Paris', 'n. 大使馆；大使的职务', '/\'embəsi | \'embəsɪ | \'ɛmbəsi/', 'embassy', 2);
INSERT INTO `words` VALUES (5776, 'Feelings of guilt are deeply embedded in her personality.', 'vt. 把…嵌入， 扎牢； 使深留脑中', '/ɪm\'bed | ɪm\'bɛd/', 'embed', 2);
INSERT INTO `words` VALUES (5777, 'She embodies everything I admire in a teacher.', 'v. 体现', '/im\'bɔdi | ɪmˈbɒdi | ɪm\'bɑdi/', 'embody', 2);
INSERT INTO `words` VALUES (5778, 'We hope these regions will embrace democratic reforms.', 'v. 采纳，接受', '/im\'breis | ɪmˈbreɪs | ɪm\'bres/', 'embrace', 2);
INSERT INTO `words` VALUES (5779, 'The shorts had blue embroidery over the pockets.', 'n. 绣花，刺绣；绣制品', '/im\'brɔidəri | ɪm\'brɒɪd(ə)rɪ; em- | ɪm\'brɔɪdəri/', 'embroidery', 2);
INSERT INTO `words` VALUES (5780, 'The flowers emerge in the spring.', 'v. 出现', '/i\'mə:dʒ | ɪ\'mɜ:dʒ | ɪ\'mɝdʒ/', 'emerge', 2);
INSERT INTO `words` VALUES (5781, 'Lifeguards are trained to deal with emergencies.', 'n. 紧急情况， 突然事件', '/i\'mɜːdʒənsi | ɪ\'mɝdʒənsi/', 'emergency', 2);
INSERT INTO `words` VALUES (5782, 'He emigrated to Belgium.', 'v. 永久移居国外', '/\'emiɡreit | \'emɪgreɪt | \'ɛmɪɡret/', 'emigrate', 2);
INSERT INTO `words` VALUES (5783, 'the emission of carbon dioxide into the atmosphere', 'n. 散发；传播；发出物', '/i\'miʃən | ɪ\'mɪʃ(ə)n | ɪ\'mɪʃən/', 'emission', 2);
INSERT INTO `words` VALUES (5784, 'Her voice was full of emotion.', 'n. 情感， 感情； 激动', '/ɪ\'məuʃn | ɪ\'moʃən/', 'emotion', 2);
INSERT INTO `words` VALUES (5785, 'a change of emphasis in government policy', 'n. 强调； 重视； 重要性', '/\'emfəsɪs | \'ɛmfəsɪs/', 'emphasis', 2);
INSERT INTO `words` VALUES (5786, 'The report emphasizes the importance of improving safety standards.', 'v. 强调', '/\'emfəsaiz | \'emfəsaɪz | \'ɛmfəsaɪz/', 'emphasize', 2);
INSERT INTO `words` VALUES (5787, 'empirical evidence', 'adj. 经验主义的', '/em\'pɪrɪk(ə)l; ɪm- | ɪm\'pɪrɪkl/', 'empirical', 2);
INSERT INTO `words` VALUES (5788, 'She was offered employment in the sales office.', 'n. 工作； 雇用； 使用', '/ɪm\'plɔɪmənt/', 'employment', 2);
INSERT INTO `words` VALUES (5789, 'I was enchanted by the way she smiled.', 'v. 迷住；用魔法迷惑', '/in\'tʃɑ:nt, en- | ɪn\'tʃɑːnt; en- | ɪn\'tʃænt/', 'enchant', 2);
INSERT INTO `words` VALUES (5790, 'the bear enclosure at the zoo', 'n. 围场，围栏；围绕', '/in\'kləuʒə | ɪn\'kləʊʒə; en- | ɪn\'kloʒɚ/', 'enclosure', 2);
INSERT INTO `words` VALUES (5791, 'The doctor had encountered several similar cases in the past.', 'v. 遭遇', '/in\'kauntə | ɪn\'kaʊntə(r) | ɪn\'kaʊntɚ/', 'encounter', 2);
INSERT INTO `words` VALUES (5792, 'I want to thank everyone who has encouraged and supported me.', 'v. 鼓励', '/in\'kʌridʒ | ɪn\'kʌrɪdʒ | ɪn\'kɝrɪdʒ/', 'encourage', 2);
INSERT INTO `words` VALUES (5793, 'She’ll do anything to achieve her own ends.', 'n. 目标，目的', '/end | ɛnd/', 'end', 2);
INSERT INTO `words` VALUES (5794, 'Smoking during pregnancy endangers your baby’s life.', 'v. 使……危险', '/in\'deindʒə | ɪnˈdeɪndʒə(r) | ɪn\'dendʒɚ/', 'endanger', 2);
INSERT INTO `words` VALUES (5795, 'We always endeavor to please our customers.', 'v. 努力，尽力; n. 努力，尝试', '/in\'devə | ɪn\'devə | ɪn\'dɛvɚ/', 'endeavor', 2);
INSERT INTO `words` VALUES (5796, 'an endless stream of visitors', 'adj. 无限的，没完没了的', '/\'endlis | ˈendləs | \'ɛndləs/', 'endless', 2);
INSERT INTO `words` VALUES (5797, 'There should be no suggestion of endorsement of the product or the company by WHO.', 'n. 支持', '/in\'dɔ:smənt | ɪnˈdɔ:smənt | ɪn\'dɔrsmənt/', 'endorsement', 2);
INSERT INTO `words` VALUES (5798, 'The ambassador has endowed a $1 million public-service fellowships programme.', 'v. 资助；赋予', '/in\'dau | ɪn\'daʊ; en- | ɪn\'daʊ/', 'endow', 2);
INSERT INTO `words` VALUES (5799, 'She was pushed beyond her powers of endurance.', 'n. 耐久力，持久力', '/in\'djuərəns | ɪn\'djʊər(ə)ns; en- | ɪn\'dʊrəns/', 'endurance', 2);
INSERT INTO `words` VALUES (5800, 'It seemed impossible that anyone could endure such pain.', 'v. 忍受', '/in\'djuə | ɪnˈdjʊə(r) | ɪn\'dʊr/', 'endure', 2);
INSERT INTO `words` VALUES (5801, 'an energetic man', 'adj. 积极的；精力旺盛的', '/,enə\'dʒetik | ,enə\'dʒetɪk | ,ɛnɚ\'dʒɛtɪk/', 'energetic', 2);
INSERT INTO `words` VALUES (5802, NULL, 'v. 供给…能量', '/\'enədʒaiz | \'enədʒaɪz | \'ɛnɚdʒaɪz/', 'energize', 2);
INSERT INTO `words` VALUES (5803, 'Parking restrictions will be strictly enforced.', 'v. 强迫，迫使', '/in\'fɔ:s | ɪn\'fɔ:s | ɪn\'fɔrs/', 'enforce', 2);
INSERT INTO `words` VALUES (5804, 'I have never engaged in drug trafficking.', 'v. 忙于，从事；雇佣', '/in\'ɡeidʒ | ɪn\'ɡeɪdʒ | ɪn\'ɡedʒ/', 'engage', 2);
INSERT INTO `words` VALUES (5805, 'Their engagement was announced in the paper.', 'n. 婚约；约会', '/ɪn\'geɪdʒm(ə)nt; en- | ɪn\'ɡedʒmənt/', 'engagement', 2);
INSERT INTO `words` VALUES (5806, 'Is the engine running smoothly?', 'n. 引擎， 发动机； 机车', '/\'endʒɪn | \'ɛndʒɪn/', 'engine', 2);
INSERT INTO `words` VALUES (5807, 'Good lighting will enhance any room.', 'v. 提高，增加；改进', '/in\'hɑ:ns, -hæns | ɪn\'hɑːns; -hæns; en- | ɪn\'hæns/', 'enhance', 2);
INSERT INTO `words` VALUES (5808, 'Baldwin enlightened her as to the nature of the experiment.', 'v. 启发，开导；启蒙', '/in\'laitən | ɪn\'laɪt(ə)n; en- | ɪn\'laɪtn/', 'enlighten', 2);
INSERT INTO `words` VALUES (5809, 'Isabel looked to Ron for enlightenment.', 'n. 启发， 开导； 开明， 文明', '/ɪn\'laɪtnmənt/', 'enlightenment', 2);
INSERT INTO `words` VALUES (5810, 'an enormous bunch of flowers', 'adj. 巨大的', '/i\'nɔ:məs | ɪˈnɔ:məs | ɪ\'nɔrməs/', 'enormous', 2);
INSERT INTO `words` VALUES (5811, 'Add fertilizer to enrich the soil.', 'v. 丰富，使富裕', '/in\'ritʃ | ɪn\'rɪtʃ/', 'enrich', 2);
INSERT INTO `words` VALUES (5812, 'You need to enroll before the end of August.', 'v. 登记，招收，参军', '/in\'rəul | ɪn\'rəʊl | ɪn\'rol/', 'enroll', 2);
INSERT INTO `words` VALUES (5813, 'Class enrollment, where each student has all of the course schedule selections, each student having his own bucket in the CGTT.', 'n. 入学人数', '/in\'rəulmənt | ɪn\'rəʊlmənt | ɪn\'rolmənt/', 'enrollment', 2);
INSERT INTO `words` VALUES (5814, 'If the Europeans did not reduce subsidies, a trade war would ensue.', 'vi. 接着发生， 接踵而来， 因而产生', '/ɪn\'sjuː | ɪn\'su/', 'ensue', 2);
INSERT INTO `words` VALUES (5815, 'A new computer system entails a lot of re-training.', 'v. 使需要，使必须', '/in\'teil | ɪn\'tel/', 'entail', 2);
INSERT INTO `words` VALUES (5816, 'The programme is a joint enterprise with the London Business School.', 'n. 艰巨的事业；事业心', '/\'entəpraiz | \'entəpraɪz | \'ɛntɚ\'praɪz/', 'enterprise', 2);
INSERT INTO `words` VALUES (5817, 'the entertainment of friends', 'n. 招待，招待会', '/,entə\'teinmənt | entə\'teɪnm(ə)nt | \'ɛntɚ\'tenmənt/', 'entertainment', 2);
INSERT INTO `words` VALUES (5818, 'Gillian and Darren greeted the speakers with great enthusiasm.', 'n. 热情， 热心， 热忱； 巨大兴趣', '/ɪn\'θjuːziæzəm | ɪn\'θuzɪæzəm/', 'enthusiasm', 2);
INSERT INTO `words` VALUES (5819, 'an enthusiastic supporter of reform', 'adj. 热情的', '/in,θju:zi\'æstik | ɪnˌθju:ziˈæstɪk | ɪn,θuzɪ\'æstɪk/', 'enthusiastic', 2);
INSERT INTO `words` VALUES (5820, 'If the warranty is limited, the terms may entitle you to a replacement or refund.', 'v. 使具有资格', '/in\'taitl | ɪnˈtaɪtl | ɪn\'taɪtl/', 'entitle', 2);
INSERT INTO `words` VALUES (5821, 'The mind exists as a separate entity.', 'n. 实体， 独立存在体， 实际存在物', '/\'entəti | \'ɛntəti/', 'entity', 2);
INSERT INTO `words` VALUES (5822, 'His friends entreated him not to go.', 'v. 恳求', '/in\'tri:t | ɪn\'triːt; en- | ɪn\'trit/', 'entreat', 2);
INSERT INTO `words` VALUES (5823, '“You have to be an optimist to be an inventor or entrepreneur, ” he concludes.', 'n. 企业家', '/,ɔntrəprə\'nə: | ˌɒntrəprəˈnɜː(r) | ˌɑntrəprəˈnɝ​/', 'entrepreneur', 2);
INSERT INTO `words` VALUES (5824, 'They, like other necessity entrepreneurs, may have resorted to entrepreneurship due to a lack of better options.', 'n. 企业管理', '/,ɒntrəprə\'nɜːʃɪp | ,ɑntrəprə\'nɝʃɪp/', 'entrepreneurship', 2);
INSERT INTO `words` VALUES (5825, 'You can leave your umbrella in the entry.', 'n. 入口，通道；条目', '/\'entri | ˈɒntreɪ | \'ɛntri/', 'entry', 2);
INSERT INTO `words` VALUES (5826, 'Now he was in the enviable position of not having to work for a living.', 'adj. 值得羡慕的', '/\'enviəbl | ˈenviəbl | \'ɛnvɪəbl/', 'enviable', 2);
INSERT INTO `words` VALUES (5827, 'Some of these chemicals are very damaging to the environment.', 'n. 环境； 外界； 围绕', '/ɪn\'vaɪrənmənt/', 'environment', 2);
INSERT INTO `words` VALUES (5828, 'the environmental damage caused by the chemical industry', 'adj. 环境的，环境产生的', '/in,vaiərən\'mentəl | ɪnvaɪrən\'ment(ə)l; en- | ɪn,vaɪrən\'mɛntl/', 'environmental', 2);
INSERT INTO `words` VALUES (5829, 'The scheme cost a lot more than we had originally envisaged.', 'vt. 想象， 设想', '/ɪn\'vɪzɪdʒ/', 'envisage', 2);
INSERT INTO `words` VALUES (5830, 'Over 500 people died during last year’s flu epidemic.', 'n. 流行病', '/,epi\'demik | ˌepɪ\'demɪk | ,ɛpɪ\'dɛmɪk/', 'epidemic', 2);
INSERT INTO `words` VALUES (5831, 'I\'d like to try and forget the whole episode.', 'n. （人生的）一段经历；（小说的）片段，插曲', '/\'episəud | \'epɪsəʊd | \'ɛpɪsod/', 'episode', 2);
INSERT INTO `words` VALUES (5832, 'the Victorian epoch', 'n. （新）时代；历元', '/\'i:pɔk, \'epək | \'iːpɒk; \'epɒk | \'ɛpək/', 'epoch', 2);
INSERT INTO `words` VALUES (5833, '...equality of the sexes.', 'n. 等同； 平等； 相等', '/i\'kwɒləti | ɪ\'kwɑləti/', 'equality', 2);
INSERT INTO `words` VALUES (5834, 'When children enter the equation , further tensions may arise within a marriage.', 'n. 平衡；反应式', '/i\'kweiʒən, -ʃən | ɪ\'kweɪʒ(ə)n | ɪ\'kweʒn/', 'equation', 2);
INSERT INTO `words` VALUES (5835, 'a small village near the equator', 'n. 赤道，天球赤道', '/i\'kweitə | ɪ\'kweɪtə | ɪ\'kwetɚ/', 'equator', 2);
INSERT INTO `words` VALUES (5836, 'The government is anxious not to upset the economic equilibrium.', 'n. 平衡，均衡；均衡论', '/,i:kwi\'libriəm | ,iːkwɪ\'lɪbrɪəm; ,ekwɪ- | ,ikwɪ\'lɪbrɪəm/', 'equilibrium', 2);
INSERT INTO `words` VALUES (5837, 'They try to equip their vehicles with gadgets to deal with every possible contingency.', 'vt. 装备， 配备； 使有准备', '/ɪ\'kwɪp/', 'equip', 2);
INSERT INTO `words` VALUES (5838, '...roughly equivalent to one month\'s supply...', 'adj. 等面（体）积的', '/i\'kwivələnt | ɪ\'kwɪv(ə)l(ə)nt | ɪ\'kwɪvələnt/', 'equivalent', 2);
INSERT INTO `words` VALUES (5839, 'an attempt to eradicate inflation', 'v. 根除', '/i\'rædikeit | ɪ\'rædɪkeɪt | ɪ\'rædɪket/', 'eradicate', 2);
INSERT INTO `words` VALUES (5840, 'an imposing town hall, erected in 1892', 'v. 建立', '/i\'rekt | ɪ\'rekt | ɪ\'rɛkt/', 'erect', 2);
INSERT INTO `words` VALUES (5841, 'the problem of soil erosion', 'n. 腐蚀，侵蚀；糜烂', '/i\'rəuʒən | ɪ\'rəʊʒ(ə)n | ɪ\'roʒən/', 'erosion', 2);
INSERT INTO `words` VALUES (5842, 'I seemed to spend my life running errands for people.', 'n. 差使，差事', NULL, 'errand', 2);
INSERT INTO `words` VALUES (5843, 'His economic predictions are based on some erroneous assumptions.', 'adj. 错误的', '/i\'rəuniəs | ɪˈrəʊnɪəs | ɪ\'ronɪəs/', 'erroneous', 2);
INSERT INTO `words` VALUES (5844, 'Violence erupted after police shot a student during the demonstration.', 'v. 喷出, 爆发', '/i\'rʌpt | ɪ\'rʌpt/', 'erupt', 2);
INSERT INTO `words` VALUES (5845, 'The shipment was escorted by guards.', 'v. 护卫，护送; n. 护卫者，护送车辆', '/\'eskɔ:t, i\'skɔ:t | \'eskɔːt | ˈeskɔːrt/', 'escort', 2);
INSERT INTO `words` VALUES (5846, 'In essence his message was very simple.', 'n. 本质，本体', '/\'esəns | \'es(ə)ns | \'ɛsns/', 'essence', 2);
INSERT INTO `words` VALUES (5847, 'Window locks are fairly cheap and absolutely essential.', 'adj. 本质的，必须的', '/i\'senʃəl | ɪ\'senʃl | ɪ\'sɛnʃl/', 'essential', 2);
INSERT INTO `words` VALUES (5848, 'He’d already begun to establish quite a reputation as a journalist.', 'v. 使…被接受', '/i\'stæbliʃ | ɪ\'stæblɪʃ; e- | ɪˈstæblɪʃ/', 'establish', 2);
INSERT INTO `words` VALUES (5849, 'The property is part of the deceased’s estate.', 'n. 财产，产业；房地产', '/ɪ\'steɪt; e- | ɪ\'stet/', 'estate', 2);
INSERT INTO `words` VALUES (5850, 'Peden was greatly esteemed by the people of Ayrshire.', 'v. 尊重', '/i\'sti:m | ɪ\'sti:m | ɪ\'stim/', 'esteem', 2);
INSERT INTO `words` VALUES (5851, NULL, 'adj. 美学的， 审美的； 悦目的， 雅致的', '/iːs\'θetɪk | ɛs\'θɛtɪk/', 'esthetic', 2);
INSERT INTO `words` VALUES (5852, 'Try to estimate how many steps it will take to get to a close object.', 'vt. 估计； 评价; n. 估计； 评价； 看法', '/\'estɪmeɪt | \'ɛstə,met/', 'estimate', 2);
INSERT INTO `words` VALUES (5853, 'the Christian promise of eternal life', 'adj. 永久的；不朽的', '/i\'tə:nəl | ɪ\'tɜːn(ə)l; iː- | ɪ\'tɝnl/', 'eternal', 2);
INSERT INTO `words` VALUES (5854, 'The school teaches pupils from different ethnic groups.', 'adj. 种族的', '/\'eθnik | ˈeθnɪk | \'ɛθnɪk/', 'ethnic', 2);
INSERT INTO `words` VALUES (5855, 'You should be able to evaluate your own work.', 'v. 评价', '/i\'væljueit | ɪˈvæljueɪt | ɪ\'væljʊ\'et/', 'evaluate', 2);
INSERT INTO `words` VALUES (5856, 'We need to carry out a proper evaluation of the new system.', 'n. 评价', '/i,vælju\'eiʃən | ɪˌvæljʊ\'eɪʃn | ɪ,væljʊ\'eʃən/', 'evaluation', 2);
INSERT INTO `words` VALUES (5857, 'Most of the water had evaporated.', 'v. 使脱水，发散蒸气', '/i\'væpəreit | ɪ\'væpəreɪt | ɪ\'væpəret/', 'evaporate', 2);
INSERT INTO `words` VALUES (5858, 'The room is kept at an even temperature.', 'adj. 平稳的，均匀的', '/\'i:vən | \'iːv(ə)n | \'ivən/', 'even', 2);
INSERT INTO `words` VALUES (5859, 'The profits will be split evenly between the three of us.', 'adv. 一致地；平静地', '/\'i:vənli | \'i:vənlɪ | \'ivnli/', 'evenly', 2);
INSERT INTO `words` VALUES (5860, 'everlasting fame', 'adj. 永久的；持久的', '/,eveə\'lɑ:stiŋ | evə\'lɑːstɪŋ | ,ɛvɚ\'læstɪŋ/', 'everlasting', 2);
INSERT INTO `words` VALUES (5861, 'Murrow’s evidence was enough to convict Hayes of murder.', 'n. 根据， 证据； 证人', '/\'evɪdəns | \'ɛvɪdəns/', 'evidence', 2);
INSERT INTO `words` VALUES (5862, 'Bob ate his lunch with evident enjoyment.', 'adj. 明显的， 明白的', '/\'evɪdənt | \'ɛvɪdənt/', 'evident', 2);
INSERT INTO `words` VALUES (5863, 'She wanted to protect her children from the evils of the outside world.', 'n. 邪恶，罪恶；祸害', '/\'i:vəl | \'iːv(ə)l; -vɪl | \'ivl/', 'evil', 2);
INSERT INTO `words` VALUES (5864, 'The photographs evoked strong memories of our holidays in France.', 'vt. 唤起， 引起， 使人想起', '/ɪ\'vəuk | ɪ\'vok/', 'evoke', 2);
INSERT INTO `words` VALUES (5865, 'the theory of evolution', 'n. 演变；进化；发展', '/,i:və\'lu:ʃən, ,ev- | ˌi:və\'lu:ʃn | ˌɛvəˈluʃən; (occas.) ˌ ivəˈluʃən/', 'evolution', 2);
INSERT INTO `words` VALUES (5866, 'Animals have evolved camouflage to protect themselves from predators.', 'v. 进化', '/i\'vɔlv | iˈvɒlv | ɪ\'vɑlv/', 'evolve', 2);
INSERT INTO `words` VALUES (5867, 'I couldn’t sleep for three days – I’m not exaggerating.', 'v. 夸张', '/iɡ\'zædʒəreit | ɪgˈzædʒəreɪt | ɪɡ\'zædʒəret/', 'exaggerate', 2);
INSERT INTO `words` VALUES (5868, 'It would be an exaggeration to say that we were close friends.', 'n. 夸张； 夸大之词', '/ɪgˌzædʒə\'reɪʃn | ɪɡ,zædʒə\'reʃən/', 'exaggeration', 2);
INSERT INTO `words` VALUES (5869, 'Working hours must not exceed 42 hours a week.', 'v. 超过', '/ik\'si:d | ɪk\'si:d | ɪk\'sid/', 'exceed', 2);
INSERT INTO `words` VALUES (5870, 'Thank you. You’ve been exceedingly kind.', 'adv. 极端地， 非常', '/ɪk\'siːdɪŋli | ɪk\'sidɪŋli/', 'exceedingly', 2);
INSERT INTO `words` VALUES (5871, 'Rick has always excelled at foreign languages.', 'v. 胜过，杰出', '/ik\'sel | ɪk\'sel; ek- | ɪk\'sɛl/', 'excel', 2);
INSERT INTO `words` VALUES (5872, 'High technology equipment would be excepted from any trade agreement.', 'v. 把…除外，除去', '/ik\'sept | ɪk\'sept; ek- | ɪk\'sɛpt/', 'except', 2);
INSERT INTO `words` VALUES (5873, 'It’s been cold, but today’s an exception.', 'n. 例外， 除外', '/ɪk\'sepʃn | ɪk\'sɛpʃən/', 'exception', 2);
INSERT INTO `words` VALUES (5874, 'A review panel concluded that there were no exceptional circumstances that would warrant a lesser penalty for him.', 'adj. 例外的', '/ik\'sepʃənəl | ɪkˈsepʃənl | ɪk\'sɛpʃənl/', 'exceptional', 2);
INSERT INTO `words` VALUES (5875, 'After you apply the oil, wait 20 minutes before wiping off any excess.', 'n. 过量，过度', '/ik\'ses, \'ek-, \'ekses, ik\'s- | \'ekses | \'ɛk\'sɛs/', 'excess', 2);
INSERT INTO `words` VALUES (5876, 'his excessive drinking', 'adj. 过度的', '/ik\'sesiv | ɪkˈsesɪv | ɪkˈsɛsɪv/', 'excessive', 2);
INSERT INTO `words` VALUES (5877, 'excessively high prices', 'adv. 过分，极端地', '/ik\'sesivli | ek\'sesɪvlɪ | ɪk\'sɛsɪvli/', 'excessively', 2);
INSERT INTO `words` VALUES (5878, 'Four of my cassettes for your Madonna CD is a fair exchange.', 'n&vt. 交换； 交流； 兑换', '/ɪks\'tʃeɪndʒ | ɪks\'tʃendʒ/', 'exchange', 2);
