INSERT INTO `words` VALUES (5883, 'Included in the tour is an excursion to the Grand Canyon.', 'n. （尤指集体）远足，短途旅行', '/ɪk\'skɜːʃ(ə)n; ek- | ɪk\'skɝʒn/', 'excursion', 2);
INSERT INTO `words` VALUES (5884, 'He excused himself by saying he was \'forced to rob to maintain my wife and cat.\'', 'v. 为…辩解；使免除', '/ik\'skju:z, ik\'skju:s | ɪk\'skjuːz; ek- | ɪk\'skjʊs/', 'excuse', 2);
