INSERT INTO `words` VALUES (5910, '...a yoga expert.', 'adj. 熟练的; n. 专家', '/\'ekspɜːt | \'ɛkspɝt; (for adj., also) ɛksˈpɝt ; ɪkˈspɝt/', 'expert', 2);
