INSERT INTO `words` VALUES (6111, 'Add a crushed clove of garlic (= single section of it ).', 'n. 蒜，大蒜', '/\'ɡɑ:lik | \'gɑːlɪk | \'ɡɑrlɪk/', 'garlic', 2);
INSERT INTO `words` VALUES (6112, 'She pulled the garment on and zipped it up.', 'n. 衣服；服装，衣着', '/\'ɡɑ:mənt | \'gɑːm(ə)nt | \'gɑrmənt/', 'garment', 2);
INSERT INTO `words` VALUES (6113, '‘My leg!’ he gasped. ‘I think it’s broken!’', 'vi. 喘气，倒抽气; vt. 喘着气说出; n. 喘气， 倒抽气', '/gɑːsp | ɡæsp/', 'gasp', 2);
