INSERT INTO `words` VALUES (6120, 'You can’t make generalizations about what men and women are like.', 'n. 一般化；概括，综合', '/,dʒenərəlai\'zeiʃən, -li\'z- | ,dʒenrələ\'zeɪʃən | ,dʒɛnrələ\'zeʃən/', 'generalization', 2);
INSERT INTO `words` VALUES (6121, 'She has a tendency to generalize from her husband to all men.', 'v. 概括出', '/\'dʒenərəlaiz | ˈdʒɛnrəˌlaɪz | \'dʒɛnrəlaɪz/', 'generalize', 2);
