INSERT INTO `words` VALUES (6195, 'Fortunately my suspicions proved groundless .', 'adj. 无理由的，无根据的', '/\'ɡraundlis | \'graʊn(d)lɪs | \'ɡraʊndləs/', 'groundless', 2);
