INSERT INTO `words` VALUES (6335, 'The phone rang, but she ignored it.', 'v. 忽视', '/iɡ\'nɔ: | ɪɡ\'nɔ:(r) | ɪɡ\'nɔr/', 'ignore', 2);
INSERT INTO `words` VALUES (6336, 'illegal drugs', 'adj. 不合法的， 非法的', '/ɪ\'liːgl | ɪ\'ligl/', 'illegal', 2);
INSERT INTO `words` VALUES (6337, 'A large percentage of the population is illiterate.', 'adj. 文盲的; n. 文盲', '/i\'litərət | ɪ\'lɪt(ə)rət | ɪ\'lɪtərət/', 'illiterate', 2);
INSERT INTO `words` VALUES (6338, 'The report illuminated the difficult issues at the heart of science policy.', 'v. 阐释，阐明', '/i\'lju:mineit | ɪˈluːmɪneɪt | ɪ\'lumɪnet/', 'illuminate', 2);
INSERT INTO `words` VALUES (6339, 'She was under no illusion that he loved her.', 'n. 幻想；错觉；假象', '/i\'lju:ʒən | ɪ\'l(j)uːʒ(ə)n | ɪ\'luʒn/', 'illusion', 2);
INSERT INTO `words` VALUES (6340, 'Let me give an example to illustrate the point.', 'v. 阐明，说明', '/\'iləstreit | \'ɪləstreɪt | \'ɪləstret/', 'illustrate', 2);
INSERT INTO `words` VALUES (6341, 'As she listened, she played an imaginary piano on her knees.', 'adj. 想象中的， 假想的', '/ɪ\'mædʒɪnəri | ɪ\'mædʒɪnɛri/', 'imaginary', 2);
INSERT INTO `words` VALUES (6342, 'an imaginative use of computer technology', 'adj. 富有想象力的， 爱想象的', '/ɪ\'mædʒɪnətɪv/', 'imaginative', 2);
INSERT INTO `words` VALUES (6343, 'a hormonal imbalance', 'n. 不平衡', '/,im\'bæləns | ɪm\'bæləns/', 'imbalance', 2);
INSERT INTO `words` VALUES (6344, 'She was a splendid mimic and loved to imitate Winston Churchill.', 'v. 模仿', '/\'imiteit | ˈɪmɪteɪt | \'ɪmɪtet/', 'imitate', 2);
INSERT INTO `words` VALUES (6345, 'She wore an imitation of a sailor’s hat.', 'n. 仿制品，伪制物', '/,imi\'teiʃən | ɪmɪ\'teɪʃ(ə)n | ,ɪmɪ\'teʃən/', 'imitation', 2);
INSERT INTO `words` VALUES (6346, 'People who travel by rail still read an immense amount.', 'adj. 巨大的', '/i\'mens | ɪˈmens | ɪ\'mɛns/', 'immense', 2);
INSERT INTO `words` VALUES (6347, 'Champagne wines became immensely popular in the 18th century.', 'adv. 非常，极大地', '/i\'mensli | ɪˈmensli/', 'immensely', 2);
INSERT INTO `words` VALUES (6348, 'She immersed herself in her work.', 'v. 沉浸；给…施洗礼', '/i\'mə:s | ɪ\'mɜːs | ɪ\'mɝs/', 'immerse', 2);
INSERT INTO `words` VALUES (6349, NULL, 'adj. 沉浸的，身临其境的', '/ɪˈmɜ:sɪv/', 'immersive', 2);
INSERT INTO `words` VALUES (6350, 'an illegal immigrant', 'n. 移民', '/\'imiɡrənt | ˈɪmɪgrənt | \'ɪmɪɡrənt/', 'immigrant', 2);
INSERT INTO `words` VALUES (6351, 'His father and mother immigrated when he was two.', 'v. （使）移居入境', '/\'imiɡreit | \'ɪmɪgreɪt | \'ɪmɪɡret/', 'immigrate', 2);
INSERT INTO `words` VALUES (6352, 'He called for a common European policy on immigration.', 'n. 移民', '/,imi\'ɡreiʃən | ˌɪmɪˈgreɪʃn | ,ɪmɪ\'ɡreʃən/', 'immigration', 2);
INSERT INTO `words` VALUES (6353, 'A new trade agreement is imminent.', 'adj. 即将来临的', '/\'iminənt | \'ɪmɪnənt/', 'imminent', 2);
INSERT INTO `words` VALUES (6354, 'Plato believed that the soul is immortal.', 'adj. 不朽的；永生的', '/i\'mɔ:təl | ɪ\'mɔːt(ə)l | ɪ\'mɔrtl/', 'immortal', 2);
INSERT INTO `words` VALUES (6355, 'Once we’ve had the disease, we’re immune for life.', 'adj. 免疫的， 有免疫力的， 不受影响的； 免除的， 豁免的', '/ɪ\'mjuːn | ɪ\'mjʊn/', 'immune', 2);
INSERT INTO `words` VALUES (6356, 'They say they expect the meeting to have a marked impact on the future of the country.', 'n. 影响', '/\'ɪmpækt | ɪm\'pækt/', 'impact', 2);
INSERT INTO `words` VALUES (6357, 'The illness had impaired his ability to think and concentrate.', 'v. 损害', '/im\'pεə | ɪmˈpeə(r) | ɪm\'pɛr/', 'impair', 2);
INSERT INTO `words` VALUES (6358, 'She had information that she couldn’t wait to impart.', 'v. 传授，教授', '/im\'pɑ:t | ɪmˈpɑːt | ɪm\'pɑrt/', 'impart', 2);
INSERT INTO `words` VALUES (6359, 'We offer impartial advice on tax and insurance.', 'adj. 公正的，无偏见的', '/im\'pɑ:ʃəl | ɪm\'pɑːʃ(ə)l | ɪm\'pɑrʃəl/', 'impartial', 2);
INSERT INTO `words` VALUES (6360, 'He turned away with an impatient gesture.', 'adj. 不耐烦的， 急躁的； 热切的， 急切的', '/ɪm\'peɪʃnt | ɪm\'peʃnt/', 'impatient', 2);
INSERT INTO `words` VALUES (6361, 'It is imperative that politicians should be good communicators.', 'adj. 必须的,必要的', '/ɪm\'perətɪv | ɪm\'pɛrətɪv/', 'imperative', 2);
INSERT INTO `words` VALUES (6362, 'Britain’s imperial expansion in the 19th century', 'adj. 帝国的', '/im\'piəriəl | ɪm\'pɪərɪəl | ɪm\'pɪrɪəl/', 'imperial', 2);
INSERT INTO `words` VALUES (6363, 'The discovery gave fresh impetus to the research.', 'n. 推动， 促进， 刺激； 推动力', '/\'ɪmpɪtəs/', 'impetus', 2);
INSERT INTO `words` VALUES (6364, '...writing implements.', 'n. 工具; v. 贯彻', '/\'implimənt, \'impliment | \'ɪmplɪm(ə)nt | \'ɪmplɪmɛnt/', 'implement', 2);
INSERT INTO `words` VALUES (6365, 'They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.', 'n. 含意， 暗示， 暗指； 卷入， 牵连', '/ˌɪmplɪ\'keɪʃn | \'ɪmplɪ\'keʃən/', 'implication', 2);
INSERT INTO `words` VALUES (6366, '...an implicit warning to the Moroccans not to continue or repeat the military actions they began a week ago.', 'adj. 不言明的， 含蓄的； 内含的， 固有的； 无疑问的', '/ɪm\'plɪsɪt/', 'implicit', 2);
INSERT INTO `words` VALUES (6367, '‘Don’t go,’ I implored her.', 'v. 乞求，恳求，哀求', '/im\'plɔ: | ɪm\'plɔː | ɪm\'plɔr/', 'implore', 2);
INSERT INTO `words` VALUES (6368, 'an implied threat', 'vt. 暗示， 意指', '/ɪm\'plaɪ | ɪm\'plai/', 'imply', 2);
INSERT INTO `words` VALUES (6369, 'Parents should beware of imposing their own tastes on their children.', 'v. 强加于', '/im\'pəuz | ɪm\'pəʊz | ɪm\'poz/', 'impose', 2);
INSERT INTO `words` VALUES (6370, 'patterns impressed in the clay', 'v. 盖印，在…打记号', '/im\'pres, \'impres | ɪm\'pres | ɪm\'prɛs/', 'impress', 2);
INSERT INTO `words` VALUES (6371, 'The government imprisoned all opposition leaders.', 'v. 监禁', '/im\'prizən | ɪm\'prɪzn/', 'imprison', 2);
INSERT INTO `words` VALUES (6372, 'It would be improper of me to comment before the election outcome is known.', 'adj. 不适当的；不合理的', '/im\'prɔpə | ɪm\'prɒpə | ɪm\'prɑpɚ/', 'improper', 2);
INSERT INTO `words` VALUES (6373, 'a sudden impulse to laugh', 'n. 冲动；推动', '/\'impʌls | \'ɪmpʌls/', 'impulse', 2);
INSERT INTO `words` VALUES (6374, 'Rosa was impulsive and sometimes regretted things she’d done.', 'adj. 冲动的', '/ɪm\'pʌlsɪv/', 'impulsive', 2);
INSERT INTO `words` VALUES (6375, 'All natural minerals contain impurities.', 'n. 杂质；不纯', '/im\'pjuərəti | ɪm\'pjʊərɪtɪ | ɪm\'pjʊrəti/', 'impurity', 2);
INSERT INTO `words` VALUES (6376, 'In winter, the villages are inaccessible by road.', 'adj. 达不到的，难接近的', '/,inæk\'sesəbl | ɪnək\'sesɪb(ə)l | ,ɪnæk\'sɛsəbl/', 'inaccessible', 2);
INSERT INTO `words` VALUES (6377, 'A lot of what has been written about him is inaccurate.', 'adj. 不精密的，不准确的', '/in\'ækjurət | ɪn\'ækjʊrət | ɪn\'ækjərət/', 'inaccurate', 2);
INSERT INTO `words` VALUES (6378, 'He is bitter about the inaction of the other political parties.', 'n. 不作为', '/in\'ækʃən | ɪnˈækʃn | ɪn\'ækʃən/', 'inaction', 2);
INSERT INTO `words` VALUES (6379, 'inadequate resources', 'adj. 不足的', '/in\'ædikwit | ɪnˈædɪkwət | ɪn\'ædɪkwət/', 'inadequate', 2);
INSERT INTO `words` VALUES (6380, 'an inanimate object', 'adj. 无生命的', '/in\'ænimət | ɪnˈænɪmət | ɪn\'ænɪmət/', 'inanimate', 2);
INSERT INTO `words` VALUES (6381, 'Forgive them inasmuch as they are young.', 'adv. 因为，由于', '/ɪnəz\'mʌtʃ | ,ɪnəz\'mʌtʃ/', 'inasmuch', 2);
INSERT INTO `words` VALUES (6382, 'He will be inaugurated (as) President in January.', 'v. 使就职；开始', '/i\'nɔ:ɡjureit | ɪ\'nɔːgjʊreɪt | ɪ\'nɔɡjəret/', 'inaugurate', 2);
INSERT INTO `words` VALUES (6383, 'Her contribution to our work is incalculable.', 'adj. 不可估量的，无法计算的', '/in\'kælkjuləbl | ɪnˈkælkjələbl | ɪn\'kælkjələbl/', 'incalculable', 2);
INSERT INTO `words` VALUES (6384, 'He seemed incapable of understanding how she felt.', 'adj. 无能力的；无资格的', '/in\'keipəbl | ɪn\'keɪpəb(ə)l | ɪn\'kepəbl/', 'incapable', 2);
INSERT INTO `words` VALUES (6385, 'a church filled with the smell of incense', 'n. 香，熏香；香气', '/\'insens | \'ɪnsens | \'ɪnsɛns/', 'incense', 2);
INSERT INTO `words` VALUES (6386, 'As an added incentive, there’s a bottle of champagne for the best team.', 'n. 刺激', '/in\'sentiv | ɪnˈsentɪv | ɪn\'sɛntɪv/', 'incentive', 2);
INSERT INTO `words` VALUES (6387, 'The incidence of breast cancer increases with age.', 'n. 发生率', '/\'insidəns | ˈɪnsɪdəns | \'ɪnsɪdəns/', 'incidence', 2);
INSERT INTO `words` VALUES (6388, 'Am I at risk because of some incident in my sexual past?', 'n. 发生的事， 事件', '/\'ɪnsɪdənt/', 'incident', 2);
INSERT INTO `words` VALUES (6389, '\"I didn\'t ask you to come. Incidentally, why have you come?\"', 'adv. 顺便地，附带', '/,insi\'dentəli | ɪnsɪ\'dent(ə)lɪ | ,ɪnsɪ\'dɛntli/', 'incidentally', 2);
INSERT INTO `words` VALUES (6390, 'She greeted Maggie with an inclination of the head.', 'n. 倾斜，点头；斜坡', '/,inkli\'neiʃən | ɪnklɪ\'neɪʃ(ə)n | \'ɪnklə\'neʃən/', 'inclination', 2);
INSERT INTO `words` VALUES (6391, 'a steep incline', 'n. 坡度', '/in\'klain | ɪn\'klaɪn/', 'incline', 2);
INSERT INTO `words` VALUES (6392, 'The fully inclusive fare for the trip is £22.', 'adj. 包括的', '/in\'klu:siv | ɪn\'kluːsɪv | ɪn\'klusɪv/', 'inclusive', 2);
INSERT INTO `words` VALUES (6393, 'A standardized programming model should be introduced to avoid technology incompatibility problems.', 'n. 不兼容', '/\'inkəm,pætə\'biləti | ˌɪnkəmˌpætə\'bɪlətɪ | \'ɪnkəm,pætə\'bɪləti/', 'incompatibility', 2);
INSERT INTO `words` VALUES (6394, 'Politeness and truth are often mutually incompatible.', 'adj. 不相容的', '/,inkəm\'pætəbl | ɪnkəm\'pætɪb(ə)l | ,ɪnkəm\'pætəbl/', 'incompatible', 2);
INSERT INTO `words` VALUES (6395, 'The incompetence of government officials is appalling.', 'n. 无能', '/in\'kɔmpitəns,-tənsi | ɪnˈkɒmpɪtəns | ɪn\'kɑmpɪtəns/', 'incompetence', 2);
INSERT INTO `words` VALUES (6396, 'an incompetent manager', 'adj. 无能力的，不胜任的', '/in\'kɔmpitənt | ɪn\'kɒmpɪt(ə)nt | ɪn\'kɑmpɪtənt/', 'incompetent', 2);
INSERT INTO `words` VALUES (6397, 'Unfortunately, I do not have the information because our records are incomplete.', 'adj. 不完全的，未完成的', '/,inkəm\'pli:t | ɪnkəm\'pliːt | \'ɪnkəm\'plit/', 'incomplete', 2);
INSERT INTO `words` VALUES (6398, 'It allows you to harness existing technologies and incorporate them into one application.', 'v. 合并；体现', '/in\'kɔ:pəreit, in\'kɔ:pərət | ɪn\'kɔːpəreɪt/', 'incorporate', 2);
INSERT INTO `words` VALUES (6399, 'It’s incredible that he survived the fall.', 'adj. 难以置信的，惊人的', '/in\'kredəbl | ɪn\'kredɪb(ə)l | ɪn\'krɛdəbl/', 'incredible', 2);
INSERT INTO `words` VALUES (6400, 'And operational downtime caused by reliability or performance problems can incur opportunity costs if customers are unable to access your system or the business is unable to do its work.', 'v. 引起，导致', '/in\'kə: | ɪnˈkɜː(r) | ɪn\'kɝ/', 'incur', 2);
INSERT INTO `words` VALUES (6401, 'The next day the union voted to begin an indefinite strike.', 'adj. 无限期的', '/in\'definət | ɪn\'defɪnɪt | ɪn\'dɛfɪnət/', 'indefinite', 2);
INSERT INTO `words` VALUES (6402, 'The country has made great advances since independence.', 'n. 独立； 自主； 自立', '/ˌɪndɪ\'pendəns | ,ɪndɪ\'pɛndəns/', 'independence', 2);
INSERT INTO `words` VALUES (6403, '...the consumer price index.', 'n. 指数', '/\'indeks | \'ɪndeks | \'ɪndɛks/', 'index', 2);
INSERT INTO `words` VALUES (6404, 'The study indicates a connection between poverty and crime.', 'v. 表明', '/\'indikeit | \'ɪndɪkeɪt | \'ɪndɪket/', 'indicate', 2);
INSERT INTO `words` VALUES (6405, 'Could you give me some indication as to when I am likely to receive a reply?', 'n. 指出， 指示； 迹象， 暗示', '/ˌɪndɪ\'keɪʃn | ,ɪndɪ\'keʃən/', 'indication', 2);
INSERT INTO `words` VALUES (6406, 'This behaviour is indicative of her whole attitude, I’m afraid.', 'adj. 指示的', '/in\'dikətiv | ɪnˈdɪkətɪv | ɪn\'dɪkətɪv/', 'indicative', 2);
INSERT INTO `words` VALUES (6407, 'People have become indifferent to the suffering of others.', 'adj. 冷漠的', '/in\'difərənt | ɪnˈdɪfrənt | ɪn\'dɪfrənt/', 'indifferent', 2);
INSERT INTO `words` VALUES (6408, 'an indignant reply', 'adj. 愤怒的， 愤慨的， 义愤的', '/ɪn\'dɪgnənt | ɪn\'dɪɡnənt/', 'indignant', 2);
INSERT INTO `words` VALUES (6409, 'To his indignation, Charles found that his name was not on the list.', 'n. 愤怒，愤慨，义愤', '/,indiɡ\'neiʃən | ɪndɪg\'neɪʃ(ə)n | ,ɪndɪɡ\'neʃən/', 'indignation', 2);
INSERT INTO `words` VALUES (6410, 'Thatis, should you agree to share your private information with other people moreor less indiscriminately?', 'adv. 不加选择地，不加区分地', '/indi\'skriminitli | ˌɪndɪ\'skrɪmɪnətlɪ/', 'indiscriminately', 2);
INSERT INTO `words` VALUES (6411, 'Mobile phones have become an indispensable part of our lives.', 'adj. 必不可少的', '/,indis\'pensəbl | ˌɪndɪˈspensəbl | \'ɪndɪ\'spɛnsəbl/', 'indispensable', 2);
INSERT INTO `words` VALUES (6412, 'a tennis player with a highly individual style', 'adj. 特殊的', '/,indi\'vidjuəl, -dʒəl | ɪndɪ\'vɪdjʊ(ə)l | ,ɪndɪ\'vɪdʒuəl/', 'individual', 2);
INSERT INTO `words` VALUES (6413, 'an indoor swimming pool', 'adj. 室内的；室内进行的', '/\'indɔ: | \'ɪndɔː | \'ɪndɔr/', 'indoor', 2);
INSERT INTO `words` VALUES (6414, 'Nothing would induce me to vote for him again.', 'v. 劝诱；引起', '/in\'dju:s, in\'du:s | ɪn\'djuːs | ɪn\'dus/', 'induce', 2);
INSERT INTO `words` VALUES (6415, 'Mrs Simpson is responsible for the induction of new library staff.', 'n. 就职；归纳推理', '/ɪn\'dʌkʃ(ə)n | ɪn\'dʌkʃən/', 'induction', 2);
INSERT INTO `words` VALUES (6416, 'His mother spoiled him, indulging his every whim.', 'v. 放纵', '/in\'dʌldʒ | ɪn\'dʌldʒ/', 'indulge', 2);
INSERT INTO `words` VALUES (6417, 'By 1900, Britain was a mainly industrial society.', 'adj. 工业的， 产业的', '/ɪn\'dʌstriəl | ɪn\'dʌstrɪəl/', 'industrial', 2);
INSERT INTO `words` VALUES (6418, 'She was an industrious and willing worker.', 'adj. 勤奋的', '/in\'dʌstriəs | ɪnˈdʌstriəs | ɪn\'dʌstrɪəs/', 'industrious', 2);
INSERT INTO `words` VALUES (6419, 'an ineffective marketing campaign', 'adj. 无效的', '/,ini\'fektiv | ˌɪnɪˈfektɪv | ,ɪnɪ\'fɛktɪv/', 'ineffective', 2);
INSERT INTO `words` VALUES (6420, 'Inertia carried the plane onto the ground.', 'n. 惯性；无力', '/i\'nə:ʃiə | ɪ\'nɜːʃə | ɪ\'nɝʃə/', 'inertia', 2);
INSERT INTO `words` VALUES (6421, 'She didn’t want to confront the inescapable fact that she would have to sell the house.', 'adj. 不可避免的', '/,ini\'skeipəbl | ˌɪnɪˈskeɪpəbl | \'ɪnə\'skepəbl/', 'inescapable', 2);
INSERT INTO `words` VALUES (6422, 'A further escalation of the crisis now seems inevitable.', 'adj. 不可避免的', '/in\'evitəbl | ɪnˈevɪtəbl | ɪn\'ɛvɪtəbl/', 'inevitable', 2);
INSERT INTO `words` VALUES (6423, 'The decision will inevitably lead to political tensions.', 'adv. 不可避免地', '/in\'evitəbli | ɪ\'nevɪtəblɪ; ɪn\'evɪtəblɪ | ɪn\'ɛvɪtəbli/', 'inevitably', 2);
INSERT INTO `words` VALUES (6424, 'She has an inexhaustible supply of funny stories.', 'adj. 用不完的，无穷无尽的', '/,iniɡ\'zɔ:stəbl | ˌɪnɪgˈzɔ:stəbl | ,ɪnɪɡ\'zɔstəbl/', 'inexhaustible', 2);
INSERT INTO `words` VALUES (6425, 'An infant’s skin is very sensitive.', 'n. 婴儿', '/\'infənt | \'ɪnfənt/', 'infant', 2);
INSERT INTO `words` VALUES (6426, 'People with the virus may feel perfectly well, but they can still infect others.', 'v. 感染', '/in\'fekt | ɪn\'fekt | ɪn\'fɛkt/', 'infect', 2);
INSERT INTO `words` VALUES (6427, 'infectious diseases', 'adj. 感染的，传染的', '/in\'fekʃəs | ɪnˈfekʃəs | ɪn\'fɛkʃəs/', 'infectious', 2);
INSERT INTO `words` VALUES (6428, 'A lot can be inferred from these statistics.', 'v. 推断', '/in\'fə: | ɪn\'fɜː | ɪn\'fɝ/', 'infer', 2);
INSERT INTO `words` VALUES (6429, 'There were two inferences to be drawn from her letter.', 'n. 推论；推断的结果', '/\'infərəns | \'ɪnf(ə)r(ə)ns | \'ɪnfərəns/', 'inference', 2);
INSERT INTO `words` VALUES (6430, 'I felt very inferior among all those academics.', 'adj. 比……差', '/in\'fiəriə | ɪnˈfɪəriə(r) | ɪn\'fɪrɪɚ/', 'inferior', 2);
INSERT INTO `words` VALUES (6431, 'moral inferiority', 'n. 自卑； 次等', '/ɪnˌfɪəri\'ɒrəti | ɪn,fɪrɪ\'ɔrəti/', 'inferiority', 2);
INSERT INTO `words` VALUES (6432, '...An investigation found that many of the super-rich were baffled by the infinite choices their money made available...', 'n. 无限；无穷（大）', '/\'infinət | \'ɪnfɪnət/', 'infinite', 2);
INSERT INTO `words` VALUES (6433, 'Human beings are infinitely adaptable.', 'adv. 无限地，无边地', '/\'infinitli | \'ɪnfɪnɪtlɪ | \'ɪnfɪnətli/', 'infinitely', 2);
INSERT INTO `words` VALUES (6434, 'In the equation below, as E goes to zero, n approaches infinity.', 'n. 无穷大', '/in\'finəti | ɪn\'fɪnɪtɪ | ɪn\'fɪnəti/', 'infinity', 2);
INSERT INTO `words` VALUES (6435, 'Inflation is now at over 16%.', 'n. 通货膨胀', '/in\'fleiʃən | ɪn\'fleɪʃn | ɪn\'fleʃən/', 'inflation', 2);
INSERT INTO `words` VALUES (6436, '...the damage being inflicted on industries by the recession.', 'vt. 把…强加给； 使…遭受， 使…承担', '/ɪn\'flɪkt/', 'inflict', 2);
INSERT INTO `words` VALUES (6437, 'He used his influence to get his son into medical school.', 'n. 势力，权势', '/\'influəns | \'ɪnflʊəns | \'ɪnfluəns/', 'influence', 2);
INSERT INTO `words` VALUES (6438, 'He had influential friends.', 'adj. 有影响力的', '/ˌɪnfluˈenʃl | ,ɪnflu\'ɛnʃl/', 'influential', 2);
INSERT INTO `words` VALUES (6439, 'an ingenious device', 'adj. 精巧制成的；机灵的', '/in\'dʒi:njəs | ɪn\'dʒiːnɪəs | ɪn\'dʒinɪəs/', 'ingenious', 2);
INSERT INTO `words` VALUES (6440, 'They suppress the ingenuity of our people and businesses.', 'n. 创造力', '/ˌɪndʒəˈnju:əti | ,ɪndʒə\'nuəti/', 'ingenuity', 2);
INSERT INTO `words` VALUES (6441, 'Combine all the ingredients in a large bowl.', 'n. 配料，成分', '/in\'ɡri:diənt | ɪn\'griːdɪənt | ɪn\'ɡridɪənt/', 'ingredient', 2);
INSERT INTO `words` VALUES (6442, 'The woods are inhabited by many wild animals.', 'vt. 居住于， 栖居于', '/ɪn\'hæbɪt/', 'inhabit', 2);
