INSERT INTO `words` VALUES (6470, 'Dreams can be a rich source of inspiration for an artist.', 'n. 灵感；妙想；鼓舞', '/,inspə\'reiʃən | ˌɪnspəˈreɪʃn | ˌɪnspəˈreʃən/', 'inspiration', 2);
