INSERT INTO `words` VALUES (6532, '...intolerant attitudes toward non-Catholics.', 'adj. 无法容忍的', '/in\'tɔlərənt | ɪn\'tɒl(ə)r(ə)nt | ɪn\'tɑlərənt/', 'intolerant', 2);
