INSERT INTO `words` VALUES (6542, 'I hate being treated as an invalid.', 'n. 病人', '/\'invəli:d, -lid, ,invə\'li:d, \'in- | ˈɪnvəlɪd；ɪnˈvælɪd/', 'invalid', 2);
