INSERT INTO `words` VALUES (6668, 'I spent a week at Kandersteg and could happily have lingered on.', 'v. 逗留，徘徊', '/\'liŋɡə | ˈlɪŋgə(r) | \'lɪŋɡɚ/', 'linger', 2);
