INSERT INTO `words` VALUES (6680, 'The main problem for engineers was the location of underground rivers in the area.', 'n. 定位，测位', '/ləu\'keiʃən | lə(ʊ)\'keɪʃ(ə)n | lo\'keʃən/', 'location', 2);
INSERT INTO `words` VALUES (6681, 'an increase in locomotive power', 'adj. 运动的；机动', '/\'ləukə,məutiv, ,ləukə\'m- | ləʊkə\'məʊtɪv | ,lokə\'motɪv/', 'locomotive', 2);
