INSERT INTO `words` VALUES (6687, 'The ancient Chinese claimed that garlic promoted longevity.', 'n. 长寿， 寿命', '/lɒn\'dʒevəti | lɔn\'dʒɛvəti/', 'longevity', 2);
INSERT INTO `words` VALUES (6688, 'She looked back with longing on the good old days.', 'n. 渴望; adj. 显示渴望的', '/\'lɔŋiŋ, \'lɔ:ŋ- | \'lɒŋɪŋ | \'lɔŋɪŋ/', 'longing', 2);
