INSERT INTO `words` VALUES (6699, NULL, 'v. （使）成团，结块', '/lʌmp/', 'lump', 2);
INSERT INTO `words` VALUES (6700, 'studies of the lunar surface', 'adj. 月亮的', '/\'lju:nə | \'luːnə | \'lunɚ/', 'lunar', 2);
INSERT INTO `words` VALUES (6701, 'Earlier this month, a luncheon for former U.N. staff was held in Vienna.', 'n. 午宴，午餐，便宴', '/\'lʌntʃən | \'lʌn(t)ʃ(ə)n/', 'luncheon', 2);
INSERT INTO `words` VALUES (6702, 'He lured her to his home and shot her with his father\'s gun.', 'vt. 吸引，引诱，诱惑; n. 吸引力， 诱惑物； 诱饵， 鱼饵', '/luə | lʊr/', 'lure', 2);
INSERT INTO `words` VALUES (6703, 'a luxurious 30-room villa', 'adj. 奢侈的，豪华的', '/lʌk\'zjuəriəs, -\'ʒuə- | lʌgˈʒʊəriəs | lʌɡ\'ʒʊrɪəs/', 'luxurious', 2);
