INSERT INTO `words` VALUES (6705, '...quality tools and machinery.', 'n. 机器， 机械', '/mə\'ʃiːnəri | mə\'ʃinəri/', 'machinery', 2);
INSERT INTO `words` VALUES (6706, 'There\'ll be a magician at the kids\' Christmas party.', 'n. 魔法师；变戏法的人', '/mə\'dʒiʃən | mə\'dʒɪʃ(ə)n | mə\'dʒɪʃən/', 'magician', 2);
INSERT INTO `words` VALUES (6707, 'She will face a local magistrate on Tuesday.', 'n. 地方法官', '/\'mædʒistreit | \'mædʒɪstrət; -streɪt | \'mædʒɪs\'tret/', 'magistrate', 2);
INSERT INTO `words` VALUES (6708, 'Prospect Park, with its vast lake, is a magnet for all health freaks.', 'n. 有吸引力的人（或物）', '/\'mæɡnit | ˈmæɡnɪt | \'mægnɪt/', 'magnet', 2);
