INSERT INTO `words` VALUES (6721, 'Normally she wore little makeup, but this evening was clearly an exception.', 'n. 化妆品；性格；构造；组成', '/\'meikʌp | meɪkʌp | \'mek,ʌp/', 'makeup', 2);
