INSERT INTO `words` VALUES (6733, 'Read the manufacturer’s instructions before using your new dishwasher.', 'n. 制造商， 制造厂', '/ˌmænju\'fæktʃərə | ,mænju\'fæktʃərɚ/', 'manufacturer', 2);
