INSERT INTO `words` VALUES (6744, 'Marshal Zhukov', 'n. 元帅；陆军元帅', '/\'mɑ:ʃəl | \'mɑːʃ(ə)l | \'mɑrʃəl/', 'marshal', 2);
INSERT INTO `words` VALUES (6745, 'St. Stephen, the first Christian martyr', 'n. 烈士，殉难者', '/\'mɑ:tə | \'mɑːtə | \'mɑrtɚ/', 'martyr', 2);
