INSERT INTO `words` VALUES (6756, 'Problems were expected, but they never materialized.', 'v. 实现', '/mə\'tiəriəlaiz | mə\'tɪərɪəlaɪz | mə\'tɪrɪəlaɪz/', 'materialize', 2);
INSERT INTO `words` VALUES (6757, 'If I have to stay late at work tonight, it won’t matter because we can go out another night.', 'v. 重要；要紧', '/\'mætə(r) | \'mætɚ/', 'matter', 2);
INSERT INTO `words` VALUES (6758, 'As the fish matures, its colours and patternings change.', 'v. 使成熟，成熟', '/mə\'tjuə | mə\'tʃʊə | mə\'tʃʊr/', 'mature', 2);
