INSERT INTO `words` VALUES (6760, 'The car has a maximum speed of 120 mph.', 'adj. 最大的； 最高的； 顶点的; n. 最大量；顶点', '/\'mæksɪməm | ˈmæksəməm/', 'maximum', 2);
INSERT INTO `words` VALUES (6761, 'Lambs gamboled in the meadow.', 'n. 草地', '/\'medəu | \'mɛdo/', 'meadow', 2);
