INSERT INTO `words` VALUES (6764, 'The flight has been cancelled due to mechanical failure .', 'adj. 机械的， 机械制造的， 机械学的， 力学的； 呆板的', '/mə\'kænɪkl | mɪ\'kænɪkəl/', 'mechanical', 2);
INSERT INTO `words` VALUES (6765, 'He has not studied mechanics or engineering.', 'n. 力学，机械学', '/mi\'kæniks | mɪ\'kænɪks | mə\'kænɪks/', 'mechanics', 2);
