INSERT INTO `words` VALUES (6767, 'The former president has agreed to mediate the peace talks.', 'vi. 调解，斡旋; vt. 经调解解决； 经斡旋促成', '/\'miːdieɪt | \'midɪet/', 'mediate', 2);
INSERT INTO `words` VALUES (6768, 'When somebody comes for treatment I always ask them if they are on any medication.', 'n. 药物治疗； 药物', '/ˌmedɪ\'keɪʃn | \'mɛdɪ\'keʃən/', 'medication', 2);
INSERT INTO `words` VALUES (6769, 'These spices were first brought to Italy from the East in medieval times.', 'adj. 中世纪的； 中古的', '/ˌmedɪ\'iːvl | ,midɪ\'ivəl/', 'medieval', 2);
INSERT INTO `words` VALUES (6770, 'She sat quietly, meditating on the day’s events.', 'v. 沉思；冥想', '/\'mediteit | \'medɪteɪt | \'mɛdɪtet/', 'meditate', 2);
