INSERT INTO `words` VALUES (6772, 'He sank into deep melancholy.', 'n. 忧郁的; adj. 忧郁，悲伤', '/\'melənkəli | \'melənkəlɪ | \'mɛlənkɑli/', 'melancholy', 2);
