INSERT INTO `words` VALUES (6775, 'You should carry your membership card with you at all times.', 'n. 成员资格；会员人数', '/\'membəʃɪp | \'mɛmbɚʃɪp/', 'membership', 2);
INSERT INTO `words` VALUES (6776, 'I sent him a memo reminding him about the meeting.', 'n. 备忘录', '/\'meməu | \'meməʊ | \'mɛmo/', 'memo', 2);
INSERT INTO `words` VALUES (6777, 'We want to make this a truly memorable day for the children.', 'adj. 值得纪念的', '/\'memərəbl | ˈmemərəbl | \'mɛmərəbl/', 'memorable', 2);
INSERT INTO `words` VALUES (6778, '...a memorandum from the Department of Defense on its role.', 'n. 备忘录', '/,memə\'rændəm | ˌmeməˈrændəm | ,mɛmə\'rændəm/', 'memorandum', 2);
INSERT INTO `words` VALUES (6779, 'He studied his map, trying to memorize the way to Rose\'s street.', 'v. 熟记', '/\'meməraiz | ˈmeməraɪz | \'mɛmə\'raɪz/', 'memorize', 2);
INSERT INTO `words` VALUES (6780, 'There was menace in his voice.', 'n. 威胁; v. （进行）威胁', '/\'menəs | \'mɛnəs/', 'menace', 2);
INSERT INTO `words` VALUES (6781, 'Could you mend my bike for me?', 'v. 修理；改正', '/mend | mɛnd/', 'mend', 2);
INSERT INTO `words` VALUES (6782, 'The centre provides help for people suffering from mental illness .', 'adj. 心理的， 精神的， 思想上的； 精神病的； 智力的', '/\'mentl | \'mɛntl/', 'mental', 2);
INSERT INTO `words` VALUES (6783, 'Was my name mentioned at all?', 'v. 提及', '/\'menʃən | \'menʃn | \'mɛnʃən/', 'mention', 2);
INSERT INTO `words` VALUES (6784, 'A range of official Disney merchandise was on sale.', 'n. 商品，货物', '/\'mə:tʃəndaiz, -dais | \'mɜːtʃ(ə)ndaɪs; -z | \'mɝtʃəndaɪs/', 'merchandise', 2);
INSERT INTO `words` VALUES (6785, 'Merciful God, save us.', 'adj. 仁慈的，宽大的', '/\'mə:siful | \'mɜːsɪfʊl; -f(ə)l | \'mɝsɪfl/', 'merciful', 2);
INSERT INTO `words` VALUES (6786, 'Mercury is used in batteries, pesticides, and thermometers.', 'n. 汞，水银', '/\'mɝkjəri | \'mɜːkjəri/', 'mercury', 2);
INSERT INTO `words` VALUES (6787, 'She lost the election by a mere 20 votes.', 'adj. 仅仅的， 纯粹的', '/mɪə | mɪr/', 'mere', 2);
INSERT INTO `words` VALUES (6788, 'He’s merely a boy – you can’t expect him to understand.', 'adv. 仅仅， 只不过', '/\'mɪəli | \'mɪrli/', 'merely', 2);
INSERT INTO `words` VALUES (6789, 'The company plans to merge its subsidiaries in the US.', 'v. 合并', '/mə:dʒ | mɜːdʒ | mɝdʒ/', 'merge', 2);
INSERT INTO `words` VALUES (6790, 'The results have been encouraging enough to merit further investigation.', 'v. 值得; n. 优点', '/\'merit | \'merɪt | \'mɛrɪt/', 'merit', 2);
INSERT INTO `words` VALUES (6791, 'The windows were covered in wire mesh to keep out flies.', 'n. 网眼，筛孔，网络', '/meʃ | mɛʃ/', 'mesh', 2);
INSERT INTO `words` VALUES (6792, 'He scratched his head and messed his hair even more.', 'v. 弄脏，弄乱，搞糟', '/mes | mɛs/', 'mess', 2);
INSERT INTO `words` VALUES (6793, 'The message of the film is that good always triumphs over evil.', 'n. 启示，要旨，教训', '/\'mesidʒ | \'mesɪdʒ | \'mɛsɪdʒ/', 'message', 2);
INSERT INTO `words` VALUES (6794, 'There will be a messenger at the airport to collect the photographs from our courier.', 'n. 送信人， 信使', '/\'mesɪndʒə | \'mɛsndʒɚ/', 'messenger', 2);
INSERT INTO `words` VALUES (6795, 'Exercise can increase your metabolic rate.', 'adj. 代谢作用的， 新陈代谢的', '/ˌmetə\'bɒlɪk | ,mɛtə\'bɑlɪk/', 'metabolic', 2);
INSERT INTO `words` VALUES (6796, 'metallic particles', 'adj. 金属的', '/mi\'tælik, me- | mɪ\'tælɪk | mə\'tælɪk/', 'metallic', 2);
INSERT INTO `words` VALUES (6797, 'He studied metallurgy as a mature student, having spent ten years working in a foundry.', 'n. 冶金学，冶金术', '/me\'tælədʒi, \'metələ:dʒi | mɪ\'tælədʒɪ; \'met(ə),lɜːdʒɪ | \'mɛtəlɝdʒi/', 'metallurgy', 2);
INSERT INTO `words` VALUES (6798, 'a metropolitan area of South Australia', 'adj. 大都市的', '/,metrə\'pɔlitən | metrə\'pɒlɪt(ə)n | ,mɛtrə\'pɑlɪtən/', 'metropolitan', 2);
INSERT INTO `words` VALUES (6799, 'I\'ve got a typerwriter with a microprocessor.', 'n. 微信息处理机', '/,maikrəu\'prəusesə, -\'prɔ- | maɪkrə(ʊ)\'prəʊsesə | ,maɪkro\'prosɛsɚ/', 'microprocessor', 2);
INSERT INTO `words` VALUES (6800, 'The cells were identified through microscopic analysis.', 'adj. 显微镜的；微观的，极小的', '/,maikrə\'skɔpik | maɪkrə\'skɒpɪk | ,maɪkrə\'skɑpɪk/', 'microscopic', 2);
INSERT INTO `words` VALUES (6801, 'Its molecules can be agitated by microwave energy.', 'n. 微波', '/\'maikrəuweiv | \'maɪkrə(ʊ)weɪv | \'maɪkrə\'wev/', 'microwave', 2);
INSERT INTO `words` VALUES (6802, 'We were sitting in the midst of an elegant and well-dressed audience.', 'n. 中部； 中间； 当中', '/\'mɪdst | mɪdst/', 'midst', 2);
INSERT INTO `words` VALUES (6803, 'the mighty Mississippi river', 'adj. 强大的；巨大的', '/\'maiti | \'maɪtɪ | \'maɪti/', 'mighty', 2);
INSERT INTO `words` VALUES (6804, 'The government divides asylum seekers into economic migrants and genuine refugees.', 'n. 移居者， 移民； 候鸟， 迁移动物', '/\'maɪgrənt | \'maɪɡrənt/', 'migrant', 2);
INSERT INTO `words` VALUES (6805, 'People migrate to cities like Jakarta in search of work.', 'v. 移民，迁徙', '/mai\'ɡreit, \'maiɡ- | maɪ\'ɡreɪt | \'maɪɡret/', 'migrate', 2);
INSERT INTO `words` VALUES (6806, 'What does this migration not do?', 'n. 迁徙，移居', '/mai\'ɡreiʃən | maɪ\'greɪʃ(ə)n | maɪ\'ɡreʃən/', 'migration', 2);
INSERT INTO `words` VALUES (6807, 'a mild curry', 'adj. 味淡的', '/maild | maɪld/', 'mild', 2);
INSERT INTO `words` VALUES (6808, 'He said the launch of the party represented a milestone in Zambian history.', 'n. 里程碑', '/\'mailstəun | \'maɪlstəʊn | \'maɪlston/', 'milestone', 2);
INSERT INTO `words` VALUES (6809, 'militant political activists', 'adj. 激进的；好斗的; n. 激进分子， 斗士', '/\'mɪlɪtənt/', 'militant', 2);
INSERT INTO `words` VALUES (6810, 'a military helicopter', 'adj. 军事的；军用的; n. 军队， 武装力量', '/\'mɪlətri | \'mɪlətɛri/', 'military', 2);
INSERT INTO `words` VALUES (6811, 'a cup of milky coffee', 'adj. 牛奶的；乳白色的', '/\'milki | \'mɪlkɪ | \'mɪlki/', 'milky', 2);
INSERT INTO `words` VALUES (6812, 'an American millionaire', 'n. 百分富翁，巨富', '/,miljə\'nεə | mɪljə\'neə | ,mɪljə\'nɛr/', 'millionaire', 2);
INSERT INTO `words` VALUES (6813, 'The sounds of laughter and singing mingled in the evening air.', 'vt. 使混合，混合起来', '/\'mɪŋgl | \'mɪŋɡl/', 'mingle', 2);
INSERT INTO `words` VALUES (6814, 'miniature roses', 'adj. 微型的', '/\'miniətʃə | ˈmɪnətʃə(r) | ˈmɪniətʃɚ; ˈmɪnɪtʃɚ/', 'miniature', 2);
INSERT INTO `words` VALUES (6815, 'He was then taken by minibus to the military base.', 'n. 小型公共汽车', '/\'mɪnibʌs | \'mɪnɪbʌs/', 'minibus', 2);
INSERT INTO `words` VALUES (6816, 'The storm caused only minimal damage.', 'adj. 最低的，最小限度的', '/\'miniməl | ˈmɪnɪməl | \'mɪnɪməl/', 'minimal', 2);
INSERT INTO `words` VALUES (6817, 'Every effort is being made to minimize civilian casualties.', 'v. 使减到最小', '/\'minimaiz | ˈmɪnɪˌmaɪz | \'mɪnɪmaɪz/', 'minimize', 2);
INSERT INTO `words` VALUES (6818, 'The minimum number of students we need to run the course is fifteen.', 'adj. 最低的， 最小的; n. 最低限度，最小量', '/\'mɪnɪməm/', 'minimum', 2);
INSERT INTO `words` VALUES (6819, '...traditional industries such as coal mining and steel making.', 'n. 矿产', '/\'mainiŋ | ˈmaɪnɪŋ | \'maɪnɪŋ/', 'mining', 2);
INSERT INTO `words` VALUES (6820, 'We have made some minor changes to the program.', 'adj. 次要的，小的', '/\'mainə | \'maɪnə(r) | \'maɪnɚ/', 'minor', 2);
INSERT INTO `words` VALUES (6821, 'Gaelic is still spoken in Ireland by a tiny minority.', 'n. 少数，少数民族', '/mai\'nɔrəti, mi- | maɪ\'nɒrətɪ | maɪ\'nɔrəti/', 'minority', 2);
INSERT INTO `words` VALUES (6822, 'coins issued by the Royal Mint', 'n. 造币厂；巨额钱财', '/mɪnt/', 'mint', 2);
INSERT INTO `words` VALUES (6823, 'It’s a miracle you weren’t killed!', 'n. 奇迹', '/\'mirəkl | \'mɪrəkl/', 'miracle', 2);
INSERT INTO `words` VALUES (6824, 'We believe the polls are an accurate mirror of public opinion.', 'n. 反映，借鉴', '/\'mirə | \'mɪrə | \'mɪrɚ/', 'mirror', 2);
INSERT INTO `words` VALUES (6825, 'Now run along, and don’t get into mischief .', 'n. 调皮，捣蛋，胡闹', '/\'mistʃif | \'mɪstʃɪf/', 'mischief', 2);
INSERT INTO `words` VALUES (6826, 'I\'m married to a miser.', 'n. 守财奴，吝啬鬼', '/\'maizə | \'maɪzə | \'maɪzɚ/', 'miser', 2);
INSERT INTO `words` VALUES (6827, 'What we are witnessing here is human misery on a vast scale.', 'n. 痛苦，悲惨，不幸', '/\'mizəri | \'mɪz(ə)rɪ | \'mɪzəri/', 'misery', 2);
INSERT INTO `words` VALUES (6828, 'It seems the banks always profit from farmers’ misfortunes.', 'n. 不幸地', '/mis\'fɔ:tʃən | ˌmɪsˈfɔ:tʃu:n | \'mɪs\'fɔrtʃən/', 'misfortune', 2);
INSERT INTO `words` VALUES (6829, 'Some parts of the report could be misinterpreted.', 'v. 误解', '/,misin\'tə:prit | ˌmɪsɪn\'tɜ:prɪt | \'mɪsɪn\'tɝprɪt/', 'misinterpret', 2);
INSERT INTO `words` VALUES (6830, 'He noted that a Scientologist hearing this would feel, with some justification, that he had misled his auditors about his progress.', '(mislead过去式)误导', '/,mɪs\'led | mis\'led/', 'misled', 2);
INSERT INTO `words` VALUES (6831, 'His gross mismanagement left the company desperately in need of restructuring.', 'n. 管理不当', '/\'mis\'mænidʒmənt | mɪs\'mænɪdʒmənt/', 'mismanagement', 2);
INSERT INTO `words` VALUES (6832, 'He was sent on over 200 missions before being killed in action.', 'n. 使命， 任务； 使团', '/\'mɪʃn | \'mɪʃən/', 'mission', 2);
INSERT INTO `words` VALUES (6833, 'My mother would still like me to be a missionary in Africa.', 'n. 传教士', '/\'miʃənəri | \'mɪʃ(ə)n(ə)rɪ | \'mɪʃənɛri/', 'missionary', 2);
INSERT INTO `words` VALUES (6834, 'We could just see the outline of the house through the mist.', 'n. 薄雾; v. 下薄雾', '/mist | mɪst/', 'mist', 2);
INSERT INTO `words` VALUES (6835, 'The Prince had shocked society by living openly with his mistress.', 'n. 情妇，情人', '/\'mistris | \'mɪstrɪs | \'mɪstrəs/', 'mistress', 2);
INSERT INTO `words` VALUES (6836, 'sheepskin mittens', 'n. 连指手套', '/\'mitən | \'mɪt(ə)n | \'mɪtn/', 'mitten', 2);
INSERT INTO `words` VALUES (6837, 'an electric food mixer', 'n. 搅拌器', '/\'miksə | \'mɪksə | \'mɪksɚ/', 'mixer', 2);
INSERT INTO `words` VALUES (6838, '‘I feel seasick already,’ she moaned.', 'vi. 呻吟，呜咽；抱怨，发牢骚; vt. 抱怨; n. 呻吟声， 呜咽声； 怨声， 牢骚', '/məun | mon/', 'moan', 2);
INSERT INTO `words` VALUES (6839, 'Fans ran onto the pitch and mobbed the batsman.', 'v. 团团围住（名人等）', '/mɔb | mɒb | mɑb/', 'mob', 2);
INSERT INTO `words` VALUES (6840, 'a more mobile workforce', 'adj. 运动的；流动的；多变的; n. 移动电话', '/\'məubaɪl | ˈməʊbl;mobil/', 'mobile', 2);
INSERT INTO `words` VALUES (6841, 'It improves the strength and mobility of joints.', 'n. 活动', '/məu\'biləti | məʊˈbɪləti | mo\'bɪləti/', 'mobility', 2);
INSERT INTO `words` VALUES (6842, 'an attempt to mobilize popular opinion', 'v. 动员，动员起来', '/\'məubilaiz | \'məʊbəlaɪz | \'mobəlaɪz/', 'mobilize', 2);
INSERT INTO `words` VALUES (6843, 'Opposition MPs mocked the government’s decision.', 'v. 嘲弄，挖苦', '/mɒk | mɑk/', 'mock', 2);
INSERT INTO `words` VALUES (6844, 'He drinks moderately.', 'adv. 适度地，适中', '/\'mɔdərətli | \'mɒd(ə)rətlɪ | \'mɑdərətli/', 'moderately', 2);
INSERT INTO `words` VALUES (6845, 'They need more funds to modernize the country’s telephone system.', 'v. 现代化', '/\'mɔdənaiz | \'mɒdənaɪz | mɑdɚnˌaɪz/', 'modernize', 2);
INSERT INTO `words` VALUES (6846, 'You’re too modest! You’ve been a huge help to us.', 'adj. 谦虚的； 适中的； 羞怯的', '/\'mɒdɪst | \'mɑdɪst/', 'modest', 2);
INSERT INTO `words` VALUES (6847, '‘Anyone else would have done the same thing,’ he said with typical modesty.', 'n. 谦逊；端庄', '/\'mɔdisti | \'mɒdɪstɪ | \'mɑdəsti/', 'modesty', 2);
INSERT INTO `words` VALUES (6848, 'They have used the same process for almost 50 years with only minor modifications.', 'n. 修改', '/,mɔdifi\'keiʃən | ,mɒdɪfɪ\'keɪʃ(ə)n | ,mɑdɪfɪ\'keʃən/', 'modification', 2);
INSERT INTO `words` VALUES (6849, 'The feedback will be used to modify the course for next year.', 'v. 改变', '/\'mɔdifai | ˈmɒdɪfaɪ | \'mɑdɪfaɪ/', 'modify', 2);
INSERT INTO `words` VALUES (6850, 'He carefully modulated his voice.', 'v. 调整，调节（声音）', '/\'mɔdjuleit, -dʒu- | \'mɒdjʊleɪt | \'mɑdʒəlet/', 'modulate', 2);
INSERT INTO `words` VALUES (6851, 'A rescue plan could be achieved by sending an unmanned module to the space station.', 'n. 模块；组件', '/\'mɔdju:l, -dʒu:l | \'mɒdjuːl | \'mɑdʒul/', 'module', 2);
INSERT INTO `words` VALUES (6852, 'Make sure the soil is moist before planting the seeds.', 'adj. 潮湿的', '/mɔist | mɔɪst/', 'moist', 2);
INSERT INTO `words` VALUES (6853, '...the molecular structure of fuel.', 'adj. 分子的；克分子的', '/məu\'lekjulə | mə\'lekjʊlə | mə\'lɛkjəlɚ/', 'molecular', 2);
INSERT INTO `words` VALUES (6854, 'The molecules of oxygen gas contain just two atoms.', 'n. 分子', '/\'mɒlɪkjuːl | \'mɑlɪkjul/', 'molecule', 2);
INSERT INTO `words` VALUES (6855, 'There was a momentary pause.', 'adj. 瞬息间的，片刻的', '/\'məuməntəri | \'məʊm(ə)nt(ə)rɪ | \'moməntɛri/', 'momentary', 2);
INSERT INTO `words` VALUES (6856, 'incentives to maintain the momentum of European integration', 'n. 动力，势头', '/məu\'mentəm | mə\'mentəm | mo\'mɛntəm/', 'momentum', 2);
INSERT INTO `words` VALUES (6857, 'Britain\'s head of state is a constitutional monarch.', 'n. 君主，最高统治者', '/\'mɔnək, -ɑ:k | \'mɒnək | \'mɑnɚk/', 'monarch', 2);
INSERT INTO `words` VALUES (6858, 'the government’s tight monetary policy', 'adj. 货币的', '/\'mʌnitəri | \'mʌnɪt(ə)rɪ | \'mʌnɪtɛri/', 'monetary', 2);
INSERT INTO `words` VALUES (6859, 'a heart monitor', 'n. 班长；监视器，检测器；显示器; vt. 监听， 检测', '/\'mɒnɪtə | \'mɔnɪtɚ/', 'monitor', 2);
INSERT INTO `words` VALUES (6860, '...saffron-robed Buddhist monks.', 'n. 和尚，僧侣，修道士', '/mʌŋk/', 'monk', 2);
INSERT INTO `words` VALUES (6861, 'The company has monopolized the soft drinks market.', 'v. 垄断', '/mə\'nɔpəlaiz | mə\'nɑpə\'laɪz/', 'monopolize', 2);
INSERT INTO `words` VALUES (6862, 'a monopoly in copper trading', 'n. 垄断', '/mə\'nɔpəli | mə\'nɒpəlɪ | mə\'nɑpəli/', 'monopoly', 2);
INSERT INTO `words` VALUES (6863, 'the remains of a prehistoric monster', 'n. 怪物；畸形的动植物', '/\'mɔnstə | \'mɒnstə | \'mɑnstɚ/', 'monster', 2);
INSERT INTO `words` VALUES (6864, 'a monstrous nose', 'adj. 极大的；可怕的', '/\'mɔnstrəs | \'mɒnstrəs | \'mɑnstrəs/', 'monstrous', 2);
INSERT INTO `words` VALUES (6865, 'Two or three fishing boats were moored alongside the pier.', 'v. 使停泊；使固定', '/muə, mɔ: | mɔː; mʊə/', 'moor', 2);
INSERT INTO `words` VALUES (6866, 'a mop and bucket', 'n. 拖把，墩布；洗碗刷', '/mɔp | mɒp | mɑp/', 'mop', 2);
INSERT INTO `words` VALUES (6867, 'It is easy to have an opinion on a moral issue like the death penalty for murder.', 'adj. 道德的，有道德的; n. 品行， 道德规范； 寓意', '/\'mɒrəl | \'mɔrəl/', 'moral', 2);
INSERT INTO `words` VALUES (6868, 'the decline in standards of personal morality', 'n. 道德，美德，品行', '/mə\'ræləti, mɔ:- | məˈræləti/', 'morality', 2);
INSERT INTO `words` VALUES (6869, 'The rent is reasonable and, moreover, the location is perfect.', 'adv. 而且， 再者， 此外', '/mɔːr\'əuvə | mɔr\'ovɚ/', 'moreover', 2);
INSERT INTO `words` VALUES (6870, 'Her father’s death reminded her that she was mortal.', 'adj. 终有一死的；致命的；你死我活的，不共戴天的; n. 凡人， 人类', '/\'mɔːtl | \'mɔrtl/', 'mortal', 2);
INSERT INTO `words` VALUES (6871, 'Mortality from heart disease varies widely across the world.', 'n. 死亡率', '/mɔ:\'tæləti | mɔ:ˈtæləti | mɔr\'tæləti/', 'mortality', 2);
INSERT INTO `words` VALUES (6872, 'Your building society or bank will help arrange a mortgage.', 'n. 抵押贷款; v. 抵押', '/\'mɔːgɪdʒ | \'mɔrɡɪdʒ/', 'mortgage', 2);
INSERT INTO `words` VALUES (6873, NULL, 'n. 穆斯林; adj. 穆斯林的', '/\'mɔzləm | \'mɒzləm | \'mɑzləm/', 'Moslem', 2);
INSERT INTO `words` VALUES (6874, 'Would you go to church or the synagogue or the mosque?', 'n. 清真寺', '/mɔsk | mɒsk | mɑsk/', 'mosque', 2);
INSERT INTO `words` VALUES (6875, '...ground covered over with moss.', 'n. 苔藓，地衣', '/mɔs | mɒs/', 'moss', 2);
INSERT INTO `words` VALUES (6876, 'The gas station just neighbours to the motel.', 'n. 汽车旅馆', '/məu\'tel | məʊ\'tel | mo\'tɛl/', 'motel', 2);
INSERT INTO `words` VALUES (6877, 'Was he motivated solely by a desire for power?', 'vt. 作为…的动机； 激励， 激发', '/\'məutɪveɪt | \'motə\'vet/', 'motivate', 2);
INSERT INTO `words` VALUES (6878, '...For both passion and motivation are derived from interest...', 'n. 激励，刺激', '/,məuti\'veiʃən | ˌməʊtɪ\'veɪʃn | ,motə\'veʃən/', 'motivation', 2);
INSERT INTO `words` VALUES (6879, 'Water provided the motive power for the mill.', 'adj. 发动的，运动的', '/\'məutiv | \'məʊtɪv | \'motɪv/', 'motive', 2);
INSERT INTO `words` VALUES (6880, 'busy/congested motorways', 'n. 汽车道，快车路', '/\'məutəwei | \'məʊtəweɪ | \'motɚwe/', 'motorway', 2);
INSERT INTO `words` VALUES (6881, 'Tension here is mounting , as we await the final result.', 'v. 增加', '/maʊnt/', 'mount', 2);
INSERT INTO `words` VALUES (6882, 'the mountainous coast of Wales', 'adj. 多山的；山一般的', '/\'mauntinəs | \'maʊntɪnəs | \'maʊntənəs/', 'mountainous', 2);
INSERT INTO `words` VALUES (6883, 'Hundreds of people gathered to mourn the slain president.', 'v. 哀悼', '/mɔ:n, məun | mɔ:n | mɔrn/', 'mourn', 2);
INSERT INTO `words` VALUES (6884, 'He looked mournful, even near to tears.', 'adj. 悲哀的；令人惋惜的', '/\'mɔ:nful, \'məun- | \'mɔrnfl/', 'mournful', 2);
INSERT INTO `words` VALUES (6885, 'She’s still thinking about her next move.', 'n. 行动，步骤', '/muːv | muv/', 'move', 2);
INSERT INTO `words` VALUES (6886, 'Take your boots off outside if they’re muddy.', 'adj. 泥泞的，沾满烂泥的；灰暗的，暗淡的；模糊的，糊涂的; vt. 使沾上烂泥； 使显得扑朔迷离', '/\'mʌdi/', 'muddy', 2);
INSERT INTO `words` VALUES (6887, 'Baxter was rushed to the hospital with multiple stab wounds.', 'adj. 复合的；多重的，多样的; n. 倍数', '/\'mʌltɪpl | \'mʌltəpl/', 'multiple', 2);
INSERT INTO `words` VALUES (6888, 'There will be simple tests in addition, subtraction, multiplication, and division.', 'n. 乘法；增加', '/,mʌltipli\'keiʃən | ,mʌltɪplɪ\'keɪʃ(ə)n | \'mʌltəplə\'keʃən/', 'multiplication', 2);
INSERT INTO `words` VALUES (6889, 'Bacteria multiply quickly in warm food.', 'v. 增加， 繁殖； 乘', '/\'mʌltɪplaɪ/', 'multiply', 2);
INSERT INTO `words` VALUES (6890, 'I had never seen such a multitude of stars before.', 'n. 大批，大群；大量', '/\'mʌlti,tju:d, -,tu:d | \'mʌltɪtjuːd | ˈmʌltɪˌtud, -ˌtjud/', 'multitude', 2);
INSERT INTO `words` VALUES (6891, 'the municipal waste dump', 'adj. 政府的', '/mju:\'nisipəl | mju:ˈnɪsɪpl | mju\'nɪsɪpl/', 'municipal', 2);
INSERT INTO `words` VALUES (6892, 'The piano music mixes with the murmur of conversation.', 'n. 低沉连续的声音', '/\'mə:mə | \'mɜːmə | \'mɝmɚ/', 'murmur', 2);
INSERT INTO `words` VALUES (6893, 'She was fast and strong, with a slender, muscular body.', 'adj. 肌肉发达的，强健的', '/\'mʌskjulə | \'mʌskjʊlə | \'mʌskjəlɚ/', 'muscular', 2);
INSERT INTO `words` VALUES (6894, 'He mused on how different his life would have been, had he not met Louisa.', 'v. 沉思，默想，冥想', '/mju:z | mjuːz | mjuz/', 'muse', 2);
INSERT INTO `words` VALUES (6895, 'a jar of mustard', 'n. 芥子，芥末', '/\'mʌstəd | \'mʌstɚd/', 'mustard', 2);
INSERT INTO `words` VALUES (6896, 'He was playing his trumpet with a mute.', 'n. 弱音器', '/mju:t | mjuːt | mjut/', 'mute', 2);
INSERT INTO `words` VALUES (6897, 'Elsie muttered something I couldn’t catch and walked off.', 'n&v. 轻声低语； 小声抱怨', '/\'mʌtə | \'mʌtɚ/', 'mutter', 2);
INSERT INTO `words` VALUES (6898, 'I didn’t like Dev, and the feeling seemed to be mutual.', 'adj. 相互的； 共同的', '/\'mjuːtʃuəl | \'mjutʃuəl/', 'mutual', 2);
INSERT INTO `words` VALUES (6899, 'So what can we do to get more of this marvelous, mysteriously restorative sleep stage?', 'adv. 神秘地', '/mis\'tiəriəsli | mɪ\'stɪərɪəslɪ | mɪs\'tɪrɪəsli/', 'mysteriously', 2);
INSERT INTO `words` VALUES (6900, 'an Agatha Christie mystery', 'n. 神秘小说，侦探小说', '/英 [ˈmɪstri] 美 [ˈmɪstəri] | ˈmɪstri/', 'mystery', 2);
INSERT INTO `words` VALUES (6901, 'a book of Greek myths', 'n. 杜撰出来的人； 神话', '/mɪθ/', 'myth', 2);
INSERT INTO `words` VALUES (6902, 'a naive young girl', 'adj. 幼稚的； 天真的； 轻信的', '/naɪ\'iːv | naɪ\'iv/', 'naive', 2);
INSERT INTO `words` VALUES (6903, 'an afternoon nap', 'n. 小睡', '/næp/', 'nap', 2);
INSERT INTO `words` VALUES (6904, '...taking tiny bites of a hot dog and daintily wiping my lips with a napkin.', 'n. 餐巾（纸）', '/\'næpkin | \'næpkɪn/', 'napkin', 2);
INSERT INTO `words` VALUES (6905, NULL, 'n. 叙述；故事；叙述法', '/nə\'reiʃən | nə\'reɪʃ(ə)n | nə\'reʃən/', 'narration', 2);
INSERT INTO `words` VALUES (6906, 'At several points in the narrative the two stories cross.', 'n. 叙述文， 故事； 叙述， 讲述', '/\'nærətɪv/', 'narrative', 2);
INSERT INTO `words` VALUES (6907, 'He narrowed his eyes and gazed at the horizon.', 'v. 变窄，缩小', '/\'nærəu | \'nærəʊ | \'næro/', 'narrow', 2);
INSERT INTO `words` VALUES (6908, 'Life has a nasty habit of repeating itself.', 'adj. 令人讨厌的， 令人厌恶的； 难弄的， 困难的； 严重的， 恶劣的， 险恶的； 下流的， 道德败坏的', '/\'nɑːsti | \'næsti/', 'nasty', 2);
INSERT INTO `words` VALUES (6909, 'The river is too dangerous to navigate.', 'v. 航行，驾驶', '/\'næviɡeit | ˈnævɪgeɪt | \'nævə\'get/', 'navigate', 2);
INSERT INTO `words` VALUES (6910, 'compasses and other instruments of navigation', 'n. 航行， 航海， 航空； 导航， 领航', '/ˌnævɪ\'geɪʃn | \'nævə\'geʃən/', 'navigation', 2);
INSERT INTO `words` VALUES (6911, 'Lack of money necessitated a change of plan.', 'vt. 成为必要， 需要', '/nə\'sesɪteɪt | nə\'sɛsɪtet/', 'necessitate', 2);
INSERT INTO `words` VALUES (6912, 'I’m afraid it’s become a matter of economic necessity.', 'n. 必须，必要性', '/ni\'sesəti, nə- | nəˈsesəti | nə\'sɛsəti/', 'necessity', 2);
INSERT INTO `words` VALUES (6913, 'She carried hypodermic needles and syringes in her bag.', 'n. 指针，针', '/\'ni:dl | \'nidl/', 'needle', 2);
INSERT INTO `words` VALUES (6914, 'a needy family', 'adj. 贫穷的', '/\'ni:di | \'ni:dɪ | \'nidi/', 'needy', 2);
INSERT INTO `words` VALUES (6915, 'a negative trade balance', 'adj. 负的；（结果）阴性的', '/\'neɡətiv | \'negətɪv | \'nɛɡətɪv/', 'negative', 2);
INSERT INTO `words` VALUES (6916, 'She smoked and drank, neglected the children, and left the clothes unmended.', 'v. 忽视', '/ni\'ɡlekt | nɪ\'ɡlekt | nɪ\'glɛkt/', 'neglect', 2);
INSERT INTO `words` VALUES (6917, 'The damage done to his property was negligible.', 'adj. 微不足道的', '/\'neɡlidʒəbl | \'neglɪdʒɪb(ə)l | \'nɛɡlɪdʒəbl/', 'negligible', 2);
INSERT INTO `words` VALUES (6918, 'His first aim is to get the warring parties back to the negotiating table (= discussing something ).', 'v. 谈判，交涉，议定', '/ni\'ɡəuʃieit, -si- | nɪ\'gəʊʃɪeɪt | nɪ\'ɡoʃɪet/', 'negotiate', 2);
INSERT INTO `words` VALUES (6919, 'The trader was obstinate in the negotiation.', 'n. 协商', '/ni,ɡəuʃi\'eiʃən, -si- | nɪˌgəʊʃiˈeɪʃn | nɪ,ɡoʃɪ\'eʃən/', 'negotiation', 2);
INSERT INTO `words` VALUES (6920, 'What happened in the factory is being whispered about the neighborhood.', 'n. 附近', '/\'neɪbəhʊd | \'nebɚ,hʊd/', 'neighborhood', 2);
INSERT INTO `words` VALUES (6921, 'The fair attracted hundreds of people from the neighbouring towns and villages.', 'adj. 邻近的，接壤的', '/\'neibəriŋ | \'neɪb(ə)rɪŋ/', 'neighbouring', 2);
INSERT INTO `words` VALUES (6922, 'They say eagles used to nest in those rocks.', 'v. 筑巢，为…筑巢', '/nest | nɛst/', 'nest', 2);
INSERT INTO `words` VALUES (6923, 'We netted three fish in under an hour.', 'v. 用网捕；用网覆盖', '/net | nɛt/', 'net', 2);
INSERT INTO `words` VALUES (6924, 'a high-speed European rail network', 'n. 网络；广播网', '/\'netwə:k | \'netwɜːk | \'nɛtwɝk/', 'network', 2);
INSERT INTO `words` VALUES (6925, 'I always tried to remain neutral when they started arguing.', 'adj. 中立的， 中性的', '/\'njuːtrəl | \'nʊtrəl/', 'neutral', 2);
INSERT INTO `words` VALUES (6926, 'Net neutrality, or not?', 'n. 中立', '/nju:\'træləti | nju:ˈtræləti | nu\'træləti/', 'neutrality', 2);
INSERT INTO `words` VALUES (6927, 'Each atomic cluster is made up of neutrons and protons.', 'n. 中子', '/\'nju:trɔn | \'njuːtrɒn | \'nʊtrɑn/', 'neutron', 2);
INSERT INTO `words` VALUES (6928, 'a nice point of law', 'adj. 细微的，微妙的', '/nais | naɪs/', 'nice', 2);
INSERT INTO `words` VALUES (6929, 'a nickel alloy', 'n. 镍；镍币', '/\'nikəl | \'nɪk(ə)l | \'nɪkl/', 'nickel', 2);
INSERT INTO `words` VALUES (6930, 'Stephen earned himself the nickname Hawkeye.', 'n. 绰号，诨号', '/\'nikneim | \'nɪkneɪm | \'nɪk\'nem/', 'nickname', 2);
INSERT INTO `words` VALUES (6931, 'a recurring nightmare', 'n. 噩梦', '/\'naitmεə | ˈnaɪtmeə(r) | \'naɪt\'mɛr/', 'nightmare', 2);
INSERT INTO `words` VALUES (6932, 'The new machine reduced labour costs to almost nil.', 'n. 无， 零', '/nɪl/', 'nil', 2);
INSERT INTO `words` VALUES (6933, 'the nominal head of the rebellion', 'adj. 名义上的， 有名无实的； 很少的， 象征性的； 名词性的', '/\'nɒmɪnl | \'nɑmɪnl/', 'nominal', 2);
INSERT INTO `words` VALUES (6934, 'This week one of them will be nominated by the Democratic Party for the presidency of the United States.', 'v. 提名', '/\'nɔmineit, \'nɔminət, -neit | \'nɒmɪneɪt | \'nɑmɪnet/', 'nominate', 2);
INSERT INTO `words` VALUES (6935, 'The region was extremely beautiful. Nonetheless Gerard could not imagine spending the rest of his life there.', 'adv. 尽管如此， 依然， 然而', '/ˌnʌnðə\'les | \'nʌnðə\'lɛs/', 'nonetheless', 2);
INSERT INTO `words` VALUES (6936, 'Joyce’s style of writing was a striking departure from the literary norm.', 'n. 标准，规范；平均数', '/nɔːm | nɔrm/', 'norm', 2);
INSERT INTO `words` VALUES (6937, 'the normalization of relations', 'n. 正常化，标准化', '/,nɔ:məlai\'zeiʃən, -li\'z | ,nɔːməlaɪ\'zeɪʃən | nɔrmləˈzeʃən/', 'normalization', 2);
INSERT INTO `words` VALUES (6938, 'They went over to the aeroplane and stood near its nose.', 'n. 突出部分（如船头等）', '/nəuz | nəʊz | noz/', 'nose', 2);
INSERT INTO `words` VALUES (6939, 'The town is notable for its busy open-air market.', 'adj. 值得注意的；著名的', '/\'nəutəbl | \'nəʊtəb(ə)l | \'notəbl/', 'notable', 2);
INSERT INTO `words` VALUES (6940, 'Emigration has notably increased over the past five years.', 'adv. 显著地，尤其', '/\'nəutəbli | \'nəʊtəblɪ | \'notəbli/', 'notably', 2);
INSERT INTO `words` VALUES (6941, 'Musical notation was conceived for the C major scale and each line and space represents a note in this scale.', 'n. 记号， 标记法', '/nəu\'teɪʃn | no\'teʃən/', 'notation', 2);
INSERT INTO `words` VALUES (6942, 'a noted author', 'adj. 著名的', '/\'nəutid | \'nəʊtɪd | \'notɪd/', 'noted', 2);
INSERT INTO `words` VALUES (6943, 'Names of the dead and injured are being withheld pending notification of relatives.', 'n. 通知， 告示； 通知书', '/ˌnəutɪfɪ\'keɪʃn | \'notəfə\'keʃən/', 'notification', 2);
INSERT INTO `words` VALUES (6944, 'You will be notified of any changes in the system.', 'v. 通知，告知；报告', '/\'nəutifai | \'nəʊtɪfaɪ | \'notə\'fai/', 'notify', 2);
INSERT INTO `words` VALUES (6945, 'She had no notion what he meant.', 'n. 想法，观点', '/\'nəuʃən | ˈnəuʃən | \'noʃən/', 'notion', 2);
INSERT INTO `words` VALUES (6946, 'a notorious computer hacker', 'adj. 臭名昭著的', '/nəu\'tɔ:riəs | nə(ʊ)\'tɔːrɪəs | no\'tɔrɪəs/', 'notorious', 2);
INSERT INTO `words` VALUES (6947, 'Derrida famously, notoriously, said \"there is nothing outside the text,\" right? What he meant by that, of course, is that there\'s nothing but text.', 'adv. 臭名昭著地', '/nəu\'tɔ:riəsli | nəʊ\'tɔ:rɪəslɪ | noˈtɔːriəsli/', 'notoriously', 2);
INSERT INTO `words` VALUES (6948, 'Notwithstanding differences, there are clear similarities in all of the world’s religions.', 'prep. 尽管，虽然', '/,nɔtwiθ\'stændiŋ, -wið- | nɒtwɪð\'stændɪŋ; -wɪθ- | ,nɑtwɪθ\'stændɪŋ/', 'notwithstanding', 2);
INSERT INTO `words` VALUES (6949, 'A billion is 1 with 9 noughts after it.', 'n. 无，零', '/nɔ:t | nɔːt | nɔt/', 'nought', 2);
INSERT INTO `words` VALUES (6950, 'The cream contains vitamin A to nourish the skin.', 'v. 提供养分，养育', '/\'nʌriʃ, \'nə:- | \'nʌrɪʃ | \'nɜrɪʃ/', 'nourish', 2);
INSERT INTO `words` VALUES (6951, 'lack of proper nourishment', 'n. 食物；营养（情况）', '/\'nʌriʃmənt, \'nə:- | \'nʌrɪʃm(ə)nt | \'nɝɪʃmənt/', 'nourishment', 2);
INSERT INTO `words` VALUES (6952, 'Protesters found a novel way of demonstrating against steeply rising oil prices.', 'adj. 新颖的', '/\'nɔvəl | \'nɒv(ə)l | ˈnɑːvl/', 'novel', 2);
INSERT INTO `words` VALUES (6953, 'Many toys have no attraction beyond their novelty value.', 'n. 新颖；新奇的事物', '/\'nɔvəlti | \'nɒv(ə)ltɪ | \'nɑvlti/', 'novelty', 2);
INSERT INTO `words` VALUES (6954, 'Neutrons and protons are bound together in the nucleus of an atom.', 'n. 原子核，细胞核', '/\'nju:kliəs | \'njuːklɪəs | \'nuklɪəs/', 'nucleus', 2);
INSERT INTO `words` VALUES (6955, 'He could be a bit of a nuisance when he was drunk.', 'n. 讨厌的人； 麻烦事', '/\'njuːsns | \'nusns/', 'nuisance', 2);
INSERT INTO `words` VALUES (6956, 'The crowd numbered more than a thousand.', 'v. 共计，达…之数', '/\'nʌmbə | \'nʌmbɚ/', 'number', 2);
INSERT INTO `words` VALUES (6957, 'a numerical code', 'adj. 数字的，数值的', '/nju:\'merikəl | njuː\'merɪk(ə)l | nʊ\'mɛrɪkl/', 'numerical', 2);
INSERT INTO `words` VALUES (6958, '...every summer sees numerous visitors come here to watch the Qinghai lake...', 'adj. 无数的', '/\'nju:mərəs | ˈnju:mərəs | \'numərəs/', 'numerous', 2);
INSERT INTO `words` VALUES (6959, 'Mr. Thomas was taught by the Catholic nuns whose school he attended to work and study hard.', 'n. 修女，尼姑', '/nʌn/', 'nun', 2);
INSERT INTO `words` VALUES (6960, 'The garden, developed over the past 35 years, includes a nursery.', 'n. 苗圃', '/\'nə:səri | \'nɜːs(ə)rɪ | \'nɝsəri/', 'nursery', 2);
INSERT INTO `words` VALUES (6961, 'plants nurtured in the greenhouse', 'n&vt. 养育， 培育， 滋养', '/\'nɜːtʃə | \'nɝtʃɚ/', 'nurture', 2);
INSERT INTO `words` VALUES (6962, 'Use a wrench to loosen the nut.', 'n. 螺帽，螺母', '/nʌt/', 'nut', 2);
INSERT INTO `words` VALUES (6963, 'Nutrition and exercise are essential to fitness and health.', 'n. 营养', '/nju\'trɪʃn | nu\'trɪʃən/', 'nutrition', 2);
INSERT INTO `words` VALUES (6964, 'Wholemeal bread is more nutritious than white bread.', 'adj. 有营养的', '/nju:\'triʃəs | njuˈtrɪʃəs | nʊ\'trɪʃəs/', 'nutritious', 2);
INSERT INTO `words` VALUES (6965, 'an oak door', 'n. 栎树， 橡树； 栎木， 橡木', '/əuk | ok/', 'oak', 2);
INSERT INTO `words` VALUES (6966, 'He pulled as hard as he could on the oars.', 'n. 桨', '/ɔ:, əu | ɔː | ɔr/', 'oar', 2);
INSERT INTO `words` VALUES (6967, 'The president took the oath of office (= made the official public promises that every president makes when starting their job ) .', 'n. 誓言，誓约，宣誓', '/əuθ | əʊθ | oθ/', 'oath', 2);
INSERT INTO `words` VALUES (6968, 'obedience classes for dogs and their owners', 'n. 服从，顺从', '/ə\'biːdiəns | ə\'biːdɪəns | ə\'bidjəns/', 'obedience', 2);
INSERT INTO `words` VALUES (6969, 'an obedient child', 'adj. 服从的，顺从的', '/əu\'bi:diənt | ə\'biːdɪənt | oˈbidiənt/', 'obedient', 2);
INSERT INTO `words` VALUES (6970, 'So, what of the future of obesity in America?', 'n. 肥胖', '/əu\'bi:səti, -\'be- | əʊ\'bi:sətɪ | o\'bisəti/', 'obesity', 2);
INSERT INTO `words` VALUES (6971, 'If no one objects, I would like Mrs Harrison to be present.', 'vi. 反对， 不赞成; n. 实物， 物体； 目的， 目标； 对象， 客体； 宾语', '/\'ɒbdʒɪkt; -dʒekt | \'ɑbdʒɛkt/', 'object', 2);
INSERT INTO `words` VALUES (6972, 'Her objection was that he was too young.', 'n. 反对， 异议； 反对的理由', '/əb\'dʒekʃn | əb\'dʒɛkʃən/', 'objection', 2);
INSERT INTO `words` VALUES (6973, 'He vowed to achieve certain objectives before the end of his presidency.', 'n. 目标，目的', '/əb\'dʒektiv, ɔb- | əbˈdʒektɪv | əb\'dʒɛktɪv/', 'objective', 2);
INSERT INTO `words` VALUES (6974, 'Employers have an obligation to treat all employees equally.', 'n. 义务，职责，责任', '/,ɔbli\'ɡeiʃən | ɒblɪ\'geɪʃ(ə)n | ,ɑblɪ\'ɡeʃən/', 'obligation', 2);
INSERT INTO `words` VALUES (6975, 'The storm got worse and worse. Finally, I was obliged to abandon the car and continue on foot.', 'v. 迫使', '/ə\'blaɪdʒ/', 'oblige', 2);
INSERT INTO `words` VALUES (6976, 'Bradford made an obscene gesture.', 'adj. 淫秽的， 下流的； 可憎的， 可恶的', '/əb\'siːn | əb\'sin/', 'obscene', 2);
INSERT INTO `words` VALUES (6977, 'an obscure poet', 'adj. 无名的；鲜为人知的', '/əb\'skjʊə | əb\'skjʊr/', 'obscure', 2);
INSERT INTO `words` VALUES (6978, 'Now, on the eve of the bicentenary of the independence movements, he sets out to rescue San Martín from his relative obscurity.', 'n. 默默无闻', '/əb\'skjuriti | əb\'skjʊrəti/', 'obscurity', 2);
INSERT INTO `words` VALUES (6979, 'Darwin’s observations on the habits of certain birds', 'n. 意见，短评，按语', '/,ɔbzə:\'veiʃən | ɒbzə\'veɪʃ(ə)n | ,ɑbzɚ\'veʃən/', 'observation', 2);
INSERT INTO `words` VALUES (6980, '‘Sid looks ill,’ Doherty observed.', 'v. 说，评述，评论', '/əb\'zɜːv | əb\'zɝv/', 'observe', 2);
INSERT INTO `words` VALUES (6981, 'The tax puts obstacles in the way of companies trying to develop trade overseas.', 'n. 阻碍', '/\'ɔbstəkl | ˈɒbstəkl | \'ɑbstəkl/', 'obstacle', 2);
INSERT INTO `words` VALUES (6982, 'He was the most obstinate man I’ve ever met.', 'adj. 固执的；顽强的', '/\'ɔbstinit, -nət | \'ɒbstɪnət | \'ɑbstɪnət/', 'obstinate', 2);
INSERT INTO `words` VALUES (6983, 'These conditions no longer obtain.', 'vi. 通用， 流行； 存在; vt. 获得', '/əb\'teɪn | əb\'ten/', 'obtain', 2);
INSERT INTO `words` VALUES (6984, 'He made occasional visits to London.', 'adj. 偶尔的， 间或发生的', '/ə\'keɪʒənl | ə\'keʒənl/', 'occasional', 2);
INSERT INTO `words` VALUES (6985, 'Please state your name, address and occupation.', 'n. 职业', '/,ɔkju\'peiʃən | ɒkjʊ\'peɪʃ(ə)n | ,ɑkju\'peʃən/', 'occupation', 2);
INSERT INTO `words` VALUES (6986, 'Football occupies most of my leisure time.', 'vt. 占领； 占； 占有', '/\'ɒkjupaɪ | \'ɑkjupaɪ/', 'occupy', 2);
INSERT INTO `words` VALUES (6987, 'A third of accidental deaths occur in the home.', 'v. 发生', '/ə\'kə: | əˈkɜ:(r) | ə\'kɝ/', 'occur', 2);
INSERT INTO `words` VALUES (6988, 'Laughter was a rare occurrence in his classroom.', 'n. 发生的事', '/ə\'kə:rəns, -\'kʌ- | ə\'kʌr(ə)ns | ə\'kʌrəns/', 'occurrence', 2);
INSERT INTO `words` VALUES (6989, '(= it is likely ) that he will commit the same crime again.', 'n. 可能性', '/ɔdz | ɒdz | ɑdz/', 'odds', 2);
INSERT INTO `words` VALUES (6990, 'An odor of corruption hangs about him.', 'n. 气味', '/\'əudə | \'oʊdə/', 'odor', 2);
INSERT INTO `words` VALUES (6991, 'His solicitor said he committed the offence because he was heavily in debt.', 'n. 犯罪，犯规；冒犯', '/ə\'fens | ə\'fɛns/', 'offence', 2);
INSERT INTO `words` VALUES (6992, 'His words gave great offense to everybody present.', 'n. 冒犯', '/ə\'fens | əˈfens | ə\'fɛns/', 'offense', 2);
INSERT INTO `words` VALUES (6993, 'I found her remarks deeply offensive.', 'adj. 冒犯的；进攻的', '/ə\'fensiv | ə\'fensɪv | ə\'fɛnsɪv/', 'offensive', 2);
INSERT INTO `words` VALUES (6994, 'I’ll raise the subject when a suitable occasion offers itself.', 'v. 出现', '/ˈɒfə | \'ɒfə | \'ɔfɚ/', 'offer', 2);
INSERT INTO `words` VALUES (6995, 'He was able to offset his travel expenses against tax.', 'v. 抵销', '/,ɔf\'set, ,ɔ:-, \'ɔfset, \'ɔ:- | \'ɒfset | ,ɔf\'sɛt/', 'offset', 2);
