INSERT INTO `words` VALUES (7002, 'an opium addict', 'n. 鸦片；麻醉剂', '/\'əupiəm | \'əʊpɪəm | \'opɪəm/', 'opium', 2);
INSERT INTO `words` VALUES (7003, 'Norris twice knocked down his opponent in the early rounds of the fight.', 'n. 反对者', '/ə\'pəunənt | ə\'pəʊnənt | ə\'ponənt/', 'opponent', 2);
