INSERT INTO `words` VALUES (7009, 'Andrew took a more optimistic view.', 'adj. 乐观的', '/,ɔpti\'mistik | ˌɒptɪˈmɪstɪk | ,ɑptɪ\'mɪstɪk/', 'optimistic', 2);
INSERT INTO `words` VALUES (7010, 'optimum conditions for growth', 'adj. 最优的，最适宜的', '/\'ɔptiməm | \'ɒptɪməm | \'ɑptəməm/', 'optimum', 2);
INSERT INTO `words` VALUES (7011, 'There are a number of options available.', 'n. 选择，取舍', '/\'ɔpʃən | \'ɒpʃ(ə)n | \'ɑpʃən/', 'option', 2);
