INSERT INTO `words` VALUES (7015, 'Ordinarily, he didn’t like to go to the movies.', 'adv. 通常，大概', '/,ɔ:di\'nεərəli, \'ɔ:dinərəli | \'ɔːd(ə),n(ə)rɪlɪ; ,ɔːdɪ\'nerɪlɪ | ,ɔrdn\'ɛrəli/', 'ordinarily', 2);
INSERT INTO `words` VALUES (7016, 'iron ore', 'n. 矿， 矿石', '/ɔː | ɔr/', 'ore', 2);
INSERT INTO `words` VALUES (7017, 'Organic farming is better for the environment.', 'adj. 有机的', '/ɔ:\'ɡænik | ɔ:ˈgænɪk | ɔr\'gænɪk/', 'organic', 2);
INSERT INTO `words` VALUES (7018, 'She looked at the street names, trying to orient herself.', 'v. 使适应，使确定方向', '/\'ɔ:riənt, \'əu-, \'ɔ:rient | \'ɔ:rɪənt | \'orɪənt/', 'orient', 2);
