INSERT INTO `words` VALUES (7020, 'The company needs to develop a stronger orientation towards marketing its products.', 'n. 定位；方向', '/,ɔ:rien\'teiʃən, əu- | ,ɔːrɪən\'teɪʃ(ə)n; ,ɒr- | orɪɛn\'teʃən/', 'orientation', 2);
INSERT INTO `words` VALUES (7021, 'The tradition has its origins in the Middle Ages.', 'n. 起源， 起因； 出身， 血统', '/\'ɒrɪdʒɪn | \'ɔrɪdʒɪn/', 'origin', 2);
INSERT INTO `words` VALUES (7022, 'The land was returned to its original owner.', 'adj. 最初的；新颖的；原版的; n. 原件， 原作', '/ə\'rɪdʒənl/', 'original', 2);
