INSERT INTO `words` VALUES (7024, 'a shelf covered with books and ornaments', 'n. 装饰物', '/\'ɔ:nəmənt, \'ɔ:nəment | \'ɔːnəm(ə)nt | \'ɔrnəmənt/', 'ornament', 2);
