INSERT INTO `words` VALUES (7035, 'Jesse was an outlaw, a bandit, a criminal.', 'n. 逃犯，歹徒', '/\'autlɔ: | \'aʊtlɔː | \'aʊtlɔ/', 'outlaw', 2);
INSERT INTO `words` VALUES (7036, 'Is football a good outlet for men’s aggression?', 'n. 发泄（感情等）的方法', '/\'autlet, -lit | \'aʊtlet | \'aʊtlɛt/', 'outlet', 2);
INSERT INTO `words` VALUES (7037, 'The new president outlined plans to deal with crime, drugs, and education.', 'v. 概述，概括', '/\'autlain | \'aʊtlaɪn/', 'outline', 2);
INSERT INTO `words` VALUES (7038, 'She outlived her husband by 20 years.', 'v. 比……活的时间长', '/,aut\'liv | ˌaʊt\'lɪv | ,aʊt\'lɪv/', 'outlive', 2);
INSERT INTO `words` VALUES (7039, 'Flats outnumber houses in this area.', 'v. 超过', '/,aut\'nʌmbə | ˌaʊt\'nʌmbə(r) | \'aʊt\'nʌmbɚ/', 'outnumber', 2);
INSERT INTO `words` VALUES (7040, 'Stocks generally outperform other investments.', 'v. 胜过', '/,autpə\'fɔ:m | ˌaʊtpəˈfɔ:m | ,aʊtpɚ\'fɔrm/', 'outperform', 2);
INSERT INTO `words` VALUES (7041, 'Output is up 30% on last year.', 'n. 产量；输出，输出功率; vt. 输出', '/\'autput | \'aʊtpʊt/', 'output', 2);
INSERT INTO `words` VALUES (7042, 'The response to the jury’s verdict was one of outrage.', 'n. 义愤，愤慨；暴行，骇人听闻的事件; vt. 激起…的义愤， 激怒', '/\'autreɪdʒ | \'aʊtredʒ/', 'outrage', 2);
