INSERT INTO `words` VALUES (7048, 'an oval face', 'adj. 卵形的; n. 卵形', '/\'əuvəl | \'əʊv(ə)l | \'ovl/', 'oval', 2);
INSERT INTO `words` VALUES (7049, 'Will you be home over the summer vacation?', 'prep. 在（做）…时', '/\'əuvə | \'əʊvə | \'ovɚ/', 'over', 2);
INSERT INTO `words` VALUES (7050, '...the overall rise in unemployment.', 'adj. 总的', '/\'əuvərɔ:l, ,əuvə\'rɔ:l | \'əʊvərɔːl | ,ovə\'rɔl/', 'overall', 2);
INSERT INTO `words` VALUES (7051, 'Sometimes, they overcharge or don’t build those parts I have been paying for.', 'v. 多收钱', '/,əuvə\'tʃɑ:dʒ, \'əuvətʃɑ:dʒ | ˌəʊvə\'tʃɑ:dʒ | ,ovɚ\'tʃɑrdʒ/', 'overcharge', 2);
INSERT INTO `words` VALUES (7052, 'Australia overcame the Netherlands 2-1.', 'vt. 战胜， 克服； 压倒， 使受不了', '/ˌəuvə\'kʌm | ,ovɚ\'kʌm/', 'overcome', 2);
INSERT INTO `words` VALUES (7053, 'He tends to overestimate his own abilities.', 'v. 高估', '/,əuvər\'estimeit, -\'estimət | əʊvər\'estɪmeɪt | ,ovər\'ɛstɪmət/', 'overestimate', 2);
