INSERT INTO `words` VALUES (7059, 'When the bag is folded, the bottom overlaps one side.', 'v. 重叠', '/,əuvə\'læp, \'əuvəlæp | ˌəʊvəˈlæp | \'ovəlæp/', 'overlap', 2);
