INSERT INTO `words` VALUES (7067, 'Rebels were already making plans to overthrow the government.', 'v. 推翻; n. 推翻，瓦解', '/,əuvə\'θrəu, \'əuvəθrəu | əʊvə\'θrəʊ | ,ovɚ\'θro/', 'overthrow', 2);
