INSERT INTO `words` VALUES (7100, 'You can bet that would truly paralyze the flow of credit: Does anyone believe Washington can manage banks?', 'v. 瘫痪，麻痹', '/\'pærəlaiz | \'pærəlaɪz | \'pærə,laɪz/', 'paralyze', 2);
