INSERT INTO `words` VALUES (7447, 'In the dining room, team photographs were ranged along the wall.', 'v. 排列', '/reɪn(d)ʒ | rendʒ/', 'range', 2);
INSERT INTO `words` VALUES (7448, 'There were several pairs of riding boots ranked neatly in the hall.', 'v. 排列，分级', '/ræŋk/', 'rank', 2);
INSERT INTO `words` VALUES (7449, 'She was woken by a sharp rap on the door.', 'n. 轻敲击声; v. 敲击', '/ræp/', 'rap', 2);
INSERT INTO `words` VALUES (7450, 'Police are investigating a series of violent rapes in the town.', 'n. 强奸', '/reip | reɪp | rep/', 'rape', 2);
INSERT INTO `words` VALUES (7451, 'the rapidity of economic growth', 'n. 快，迅速；陡，险峻', '/rə\'pidəti | rə\'pɪdɪtɪ | rə\'pɪdəti/', 'rapidity', 2);
INSERT INTO `words` VALUES (7452, 'The boys gazed up at him in rapture.', 'n. 狂喜，欢天喜地', '/\'ræptʃə | \'ræptʃɚ/', 'rapture', 2);
INSERT INTO `words` VALUES (7453, 'This species of plant is becoming increasingly rare.', 'adj. 罕见的，稀少的', '/reə(r) | rɛr/', 'rare', 2);
INSERT INTO `words` VALUES (7454, '...we tend to create an image that rarely looks like us...', 'adv. 不常， 难得', '/\'reəli | \'rɛrli/', 'rarely', 2);
INSERT INTO `words` VALUES (7455, 'What\'s that old rascal been telling you?', 'n. 流氓，恶棍，无赖', '/\'rɑ:skəl, \'ræ- | \'rɑːsk(ə)l | \'ræskl/', 'rascal', 2);
INSERT INTO `words` VALUES (7456, 'Please Jessie, don’t do anything rash.', 'adj. 轻率的；鲁莽的', '/ræʃ/', 'rash', 2);
INSERT INTO `words` VALUES (7457, '$20 an hour is the going rate (= the usual amount paid ) for private tuition.', 'n. 费用', '/reit | reɪt | ret/', 'rate', 2);
INSERT INTO `words` VALUES (7458, 'By the end of the year the Prime Minister’s approval rating (= how many people agreed with his policies ) had fallen as low as 12 percent.', 'n. 等级， 品级， 评定结果； 收视率， 收听率', '/\'reɪtɪŋ | \'retɪŋ/', 'rating', 2);
INSERT INTO `words` VALUES (7459, 'Parents need to be fully informed so they can make a rational decision.', 'adj. 合理的；适度的', '/\'ræʃənəl | \'ræʃ(ə)n(ə)l | \'ræʃnəl/', 'rational', 2);
INSERT INTO `words` VALUES (7460, 'Every time a bus went past, the windows rattled.', 'v. 发出格格声', '/\'rætl | \'ræt(ə)l/', 'rattle', 2);
INSERT INTO `words` VALUES (7461, 'What was Jeff’s reaction when you told him about the job?', 'n. 反应， 反作用', '/ri\'ækʃn | rɪ\'ækʃən/', 'reaction', 2);
INSERT INTO `words` VALUES (7462, 'They shut down the nuclear reactor for safety reasons.', 'n. 反应堆', '/ri\'æktə, ri:- | rɪ\'æktə | rɪ\'æktɚ/', 'reactor', 2);
INSERT INTO `words` VALUES (7463, 'Boats are readily available to visitors.', 'adv. 乐意地， 欣然地； 容易地； 很快地， 立即', '/\'redɪli | \'rɛdɪli/', 'readily', 2);
INSERT INTO `words` VALUES (7464, 'It takes time to readjust after a divorce.', 'v. 重新调整，再调整', '/,ri:ə\'dʒʌst | riːə\'dʒʌst | ,riə\'dʒʌst/', 'readjust', 2);
INSERT INTO `words` VALUES (7465, 'She was ready and willing to work hard.', 'adj. 乐意的，愿意的', '/\'redi | \'redɪ | \'rɛdi/', 'ready', 2);
INSERT INTO `words` VALUES (7466, 'The party reaffirmed its commitment to nuclear disarmament.', 'vt. 重申； 再确认', '/ˌriːə\'fɜːm | \'riə\'fɝm/', 'reaffirm', 2);
INSERT INTO `words` VALUES (7467, 'It’s just not realistic to expect a promotion so soon.', 'adj. 现实的；现实主义的', '/,riə\'listik, ,ri:- | rɪə\'lɪstɪk | ,riə\'lɪstɪk/', 'realistic', 2);
INSERT INTO `words` VALUES (7468, 'the realization of his dreams', 'n. （理想等的）实现', '/,riəlai\'zeiʃən, ,ri:-, -li\'z- | riːəlaɪ\'zeɪʃn | ,riələ\'zeʃən/', 'realization', 2);
INSERT INTO `words` VALUES (7469, 'the spiritual realm', 'n. 领域，方面', '/relm | rɛlm/', 'realm', 2);
INSERT INTO `words` VALUES (7470, 'The peasants leaned down to reap wheat.', 'v. 收割，收货', '/ri:p | rip/', 'reap', 2);
INSERT INTO `words` VALUES (7471, 'It’s a good place to rear young children.', 'v. 饲养，培植；抚养', '/riə | rɪə | rɪr/', 'rear', 2);
INSERT INTO `words` VALUES (7472, 'They reasoned that other businesses would soon copy the idea.', 'v. 论证，推断', '/\'ri:zən | \'riːz(ə)n | ˈrizən/', 'reason', 2);
INSERT INTO `words` VALUES (7473, 'This has caused us to reassess the way we approach our planning.', 'vt. 再评价', '/ˌriːə\'ses | \'riə\'sɛs/', 'reassess', 2);
INSERT INTO `words` VALUES (7474, 'Teachers reassured anxious parents.', 'vt. 使放心', '/ˌriːə\'ʃuə | ,riə\'ʃʊr/', 'reassure', 2);
INSERT INTO `words` VALUES (7475, 'Voters rebelled against high property taxes.', 'vi. 反叛， 造反； 反对， 不服从; n. 反叛分子，反对者', '/\'rebl | rɪ\'bɛl/', 'rebel', 2);
INSERT INTO `words` VALUES (7476, 'an armed rebellion', 'n. 叛逆', '/ri\'beljən | rɪ\'beljən | rɪ\'bɛljən/', 'rebellion', 2);
INSERT INTO `words` VALUES (7477, 'The president rebuked the House and Senate for not passing those bills within 100 days.', 'v. 指责，非难，斥责', '/ri\'bju:k | rɪ\'bjuːk | rɪ\'bjʊk/', 'rebuke', 2);
INSERT INTO `words` VALUES (7478, 'You don’t happen to recall his name, do you?', 'v. 回忆起，想起', '/ri\'kɔ:l, \'ri:kɔ:l | rɪ\'kɔ:l | \'rikɔl/', 'recall', 2);
INSERT INTO `words` VALUES (7479, 'The pain in his head gradually receded.', 'vi. 退， 退去， 渐渐远去； 向后倾斜， 缩进', '/rɪ\'siːd | rɪ\'sid/', 'recede', 2);
INSERT INTO `words` VALUES (7480, 'Keep your receipt in case you want to bring it back.', 'n. 发票', '/ri\'si:t | rɪ\'si:t | rɪ\'sit/', 'receipt', 2);
INSERT INTO `words` VALUES (7481, 'Molly\'s more of a giver than a receiver.', 'n. 接待者；收受者', '/ri\'si:və | rɪ\'siːvə | rɪ\'sivɚ/', 'receiver', 2);
INSERT INTO `words` VALUES (7482, 'She was unsure of her reception after everything that had happened.', 'n. 接待', '/ri\'sepʃən | rɪˈsepʃn | rɪ\'sɛpʃən/', 'reception', 2);
INSERT INTO `words` VALUES (7483, 'You tell the receptionist that you are expecting a call from this client and to put them through.', 'n. 接待员', '/ri\'sepʃənist | rɪˈsepʃənɪst | rɪ\'sɛpʃənɪst/', 'receptionist', 2);
INSERT INTO `words` VALUES (7484, 'the economic recession of the early 1980s', 'n. 衰退， 衰退期', '/rɪ\'seʃn | rɪ\'sɛʃən/', 'recession', 2);
INSERT INTO `words` VALUES (7485, 'a recipe book', 'n. 秘方，食谱', '/\'resəpɪ | \'rɛsəpi/', 'recipe', 2);
INSERT INTO `words` VALUES (7486, '...the largest recipient of U.S. foreign aid.', 'n. 接受者， 接收者', '/rɪ\'sɪpiənt | rɪ\'sɪpɪənt/', 'recipient', 2);
INSERT INTO `words` VALUES (7487, 'He spoke of the necessity for a reciprocal relationship that would be useful for all sides.', 'adj. 相互的；互利的', '/ri\'siprəkəl | rɪ\'sɪprək(ə)l | rɪ\'sɪprəkl/', 'reciprocal', 2);
INSERT INTO `words` VALUES (7488, 'She recited a poem that she had learnt at school.', 'v. 背诵， 朗诵； 列举， 一一说出', '/rɪ\'saɪt/', 'recite', 2);
INSERT INTO `words` VALUES (7489, 'He was accused of causing death by reckless driving .', 'adj. 鲁莽的', '/\'reklis | \'rekləs | \'rɛkləs/', 'reckless', 2);
INSERT INTO `words` VALUES (7490, '‘There’s nothing we can do about it.’ ‘You reckon (= used to express doubt or disagreement ) ?’', 'v. 认为，评价', '/\'rekən | \'rɛkən/', 'reckon', 2);
INSERT INTO `words` VALUES (7491, 'This land will be reclaimed for a new airport.', 'v. 开垦，开拓；回收', '/ri\'kleim | rɪ\'kleɪm | rɪ\'klem/', 'reclaim', 2);
INSERT INTO `words` VALUES (7492, 'He stared at her, but there was no sign of recognition .', 'n. 认出，识别', '/,rekəg\'niʃən | rekəg\'nɪʃ(ə)n | ,rɛkəɡ\'nɪʃən/', 'recognition', 2);
INSERT INTO `words` VALUES (7493, 'I didn’t recognize you in your uniform.', 'vt. 认出， 识别； 承认， 确认， 认可； 赏识， 表彰， 报偿', '/\'rekəgnaɪz | ˈrɛkəɡˌnaɪz/', 'recognize', 2);
INSERT INTO `words` VALUES (7494, 'I recommend the butter chicken - it’s delicious.', 'v. 推荐', '/,rekə\'mend | ˌrekəˈmend | \'rɛkə\'mɛnd/', 'recommend', 2);
INSERT INTO `words` VALUES (7495, 'We chose the hotel on their recommendation (= because they recommended it).', 'n. 推荐，介绍；建议', '/,rekəmen\'deiʃən | ,rekəmen\'deɪʃ(ə)n | ,rɛkəmɛn\'deʃən/', 'recommendation', 2);
INSERT INTO `words` VALUES (7496, 'The possibility remains that the two theories may be reconciled.', 'v. 使和解，使一致；调解', '/\'rekənsail | \'rekənsaɪl | \'rɛkənsaɪl/', 'reconcile', 2);
INSERT INTO `words` VALUES (7497, 'Her ex-husband had always hoped for a reconciliation.', 'n. 和解， 调和', '/ˌrekənsɪli\'eɪʃn | ,rɛkənsɪlɪ\'eʃən/', 'reconciliation', 2);
INSERT INTO `words` VALUES (7498, 'Four paintings stolen from the gallery have been recovered.', 'v. 重新获得， 挽回； 恢复', '/ˌriː\'kʌvə | rɪ\'kʌvɚ/', 'recover', 2);
INSERT INTO `words` VALUES (7499, 'Hopes of economic recovery are fading.', 'n. 恢复， 痊愈； 追回， 寻回， 收复', '/rɪ\'kʌvəri/', 'recovery', 2);
INSERT INTO `words` VALUES (7500, 'His only recreations are drinking beer and watching football.', 'n. 消遣，娱乐活动', '/,rekri\'eiʃən, -kri:- | ,rekrɪ\'eɪʃ(ə)n | ,rɛkrɪ\'eʃən/', 'recreation', 2);
INSERT INTO `words` VALUES (7501, 'We’re having difficulty recruiting enough qualified staff.', 'v. 招聘', '/ri\'kru:t | rɪ\'kru:t | rɪ\'krut/', 'recruit', 2);
INSERT INTO `words` VALUES (7502, 'If that doesn\'t work, do a Web search on the term \"recruiter\" or \"HR director\" along with the name of your employer of choice.', 'n. 招聘者', '/ri\'kru:tə | rɪ\'kruːtə | rɪ\'krʊtɚ/', 'recruiter', 2);
INSERT INTO `words` VALUES (7503, 'Suppose the width of a rectangle is x metres.', 'n. 矩形，长方形', '/\'rek,tæŋɡl | \'rektæŋg(ə)l | \'rɛktæŋɡl/', 'rectangle', 2);
INSERT INTO `words` VALUES (7504, '...a rectangular table.', 'adj. 长方形的， 矩形的', '/rek\'tæŋgjələ | rɛk\'tæŋgjəlɚ/', 'rectangular', 2);
INSERT INTO `words` VALUES (7505, 'I did my best to rectify the situation, but the damage was already done.', 'v. 纠正；调整', '/\'rektifai | \'rektɪfaɪ | \'rɛktɪfaɪ/', 'rectify', 2);
INSERT INTO `words` VALUES (7506, 'There is a danger that the disease may recur.', 'vi. 再发生， 重现', '/rɪ\'kɜː | rɪ\'kɝ/', 'recur', 2);
INSERT INTO `words` VALUES (7507, 'Police are out in force to prevent a recurrence of the violence.', 'n. 再次发生', '/ri\'kʌrəns, -\'kə:- | rɪˈkʌrəns | rɪ\'kɝəns/', 'recurrence', 2);
INSERT INTO `words` VALUES (7508, 'recyclable cardboard packaging', 'adj. 可回收利用的', '/ri:\'saikləbl | riː\'saɪkləbl | ,ri\'saɪkləbl/', 'recyclable', 2);
INSERT INTO `words` VALUES (7509, 'We take all our bottles to be recycled.', 'vt. 回收利用', '/ˌriː\'saɪkl | ,ri\'saɪkl/', 'recycle', 2);
INSERT INTO `words` VALUES (7510, 'Feminists have redefined the role of women.', 'v. 重新定义', '/,ri:di\'fain | riːdɪ\'faɪn | ,ridɪ\'faɪn/', 'redefine', 2);
INSERT INTO `words` VALUES (7511, 'Seventy factory workers were made redundant in the resulting cuts.', 'adj. 过剩的；失业的，被解雇的', '/ri\'dʌndənt | rɪ\'dʌnd(ə)nt | rɪ\'dʌndənt/', 'redundant', 2);
INSERT INTO `words` VALUES (7512, NULL, 'n. 芦笛，牧笛', '/ri:d | riːd | rid/', 'reed', 2);
INSERT INTO `words` VALUES (7513, 'a proposal to protect several miles of thousand-year-old coral reef', 'n. 礁，礁石，暗礁', '/ri:f | riːf | rif/', 'reef', 2);
INSERT INTO `words` VALUES (7514, 'I slowly reeled the fish in.', 'v. 卷，绕', '/ri:l, riəl | riːl | ril/', 'reel', 2);
INSERT INTO `words` VALUES (7515, 'He was sent off for arguing with the referee.', 'n. （足球等）裁判员', '/,refə\'ri: | refə\'riː | ,rɛfə\'ri/', 'referee', 2);
INSERT INTO `words` VALUES (7516, 'a comprehensive list of references', 'n. 参考文献；参照物', '/\'refərəns | \'ref(ə)r(ə)ns | \'rɛfrəns/', 'reference', 2);
INSERT INTO `words` VALUES (7517, 'Oil is refined to remove naturally occurring impurities.', 'v. 精炼；使……文雅', '/ri\'fain | rɪˈfaɪn | rɪ\'faɪn/', 'refine', 2);
INSERT INTO `words` VALUES (7518, '...an oil refinery.', 'n. 精炼厂，提炼厂', '/ri\'fainəri | rɪ\'faɪn(ə)rɪ | rɪ\'faɪnəri/', 'refinery', 2);
INSERT INTO `words` VALUES (7519, 'The drop in consumer spending reflects concern about the economy.', 'v. 思考，反映，反射', '/rɪ\'flekt | rɪ\'flɛkt/', 'reflect', 2);
INSERT INTO `words` VALUES (7520, 'Stick reflective tape on your school bag.', 'adj. 深思熟虑的；反映的，反射的', '/ri\'flektiv | rɪ\'flektɪv | rɪ\'flɛktɪv/', 'reflective', 2);
INSERT INTO `words` VALUES (7521, 'plans to radically reform the tax system', 'n&v. 改革， 改良， 改造； 改正， 改过自新', '/rɪ\'fɔːm | rɪ\'fɔrm/', 'reform', 2);
INSERT INTO `words` VALUES (7522, 'Although I advise that you refrain from decoding XML documents with ad hoc routines, I have no qualms about writing.', 'v. 抑制，避免', '/,ri:\'frein | rɪ\'freɪn | rɪ\'fren/', 'refrain', 2);
INSERT INTO `words` VALUES (7523, 'A shower will refresh you.', 'v. 振作精神， 恢复活力', '/rɪ\'freʃ | ri\'frɛʃ/', 'refresh', 2);
INSERT INTO `words` VALUES (7524, 'It made a refreshing change to talk to someone new.', 'adj. 新鲜的', '/ri\'freʃiŋ, ri:- | rɪˈfreʃɪŋ | ri\'frɛʃɪŋ/', 'refreshing', 2);
INSERT INTO `words` VALUES (7525, 'a place to rest and find refreshment for mind and body', 'n. （精力的）恢复，爽快', '/ri\'freʃmənt, ri:- | rɪ\'freʃm(ə)nt | ri\'frɛʃmənt/', 'refreshment', 2);
INSERT INTO `words` VALUES (7526, 'a wildlife refuge', 'n. 庇护所， 避难处； 庇护', '/\'refjuːdʒ | \'rɛfjʊdʒ/', 'refuge', 2);
INSERT INTO `words` VALUES (7527, 'Refugees were streaming across the border.', 'n. 难民，流亡者', '/,refju\'dʒi:, \'refjudʒi: | refjʊ\'dʒiː | \'rɛfjʊdʒi/', 'refugee', 2);
INSERT INTO `words` VALUES (7528, 'They refused to give me a refund .', 'n. 退款; vt. 退还', '/ˈriːfʌnd | ˈrifʌnd/', 'refund', 2);
INSERT INTO `words` VALUES (7529, 'Her country suffered through her refusal to accept change.', 'n. 拒绝', '/rɪ\'fjuːzl | rɪ\'fjuzl/', 'refusal', 2);
INSERT INTO `words` VALUES (7530, 'It was the kind of rumour that it is impossible to refute.', 'vt. 驳斥， 驳倒', '/rɪ\'fjuːt | ri\'fjʊt/', 'refute', 2);
INSERT INTO `words` VALUES (7531, 'The family never quite regained its former influence.', 'v. 重新获得', '/ri\'ɡein, ri:- | rɪ\'ɡeɪn | rɪ\'ɡen/', 'regain', 2);
INSERT INTO `words` VALUES (7532, 'Regarding your recent inquiry, I have enclosed a copy of our new brochure.', 'prep. 关于', '/ri\'ɡɑ:diŋ, ri:- | rɪ\'gɑːdɪŋ | rɪ\'ɡɑrdɪŋ/', 'regarding', 2);
INSERT INTO `words` VALUES (7533, 'The fields give high and stable yields regardless of climatic circumstances.', 'adj. 不管，不顾', '/rɪˈɡɑːdləs | rɪ\'ɡɑrdləs/', 'regardless', 2);
INSERT INTO `words` VALUES (7534, 'Small nodules form as the liver cells regenerate.', 'vi. 新生， 再生， 起革新作用; vt. 使新生，重建，改革，革新', '/rɪ\'dʒenər3ɪt | rɪ\'dʒɛnəret/', 'regenerate', 2);
INSERT INTO `words` VALUES (7535, '...the regenerative power of nature.', 'adj. 回授的；再生的', '/rɪ\'dʒen(ə)rətɪv | rə\'dʒɛnəretɪv/', 'regenerative', 2);
INSERT INTO `words` VALUES (7536, 'The authorities moved him to the less rigid regime of an open prison.', 'n. 制度，管理体制', '/rei\'ʒi:m, ri-, ri\'dʒi:m | reɪˈʒiːm | re\'ʒim/', 'regime', 2);
INSERT INTO `words` VALUES (7537, 'They deserted from their regiment.', 'n. 团，军团；一大群', '/\'redʒimənt | \'redʒɪm(ə)nt | \'rɛdʒɪmənt/', 'regiment', 2);
INSERT INTO `words` VALUES (7538, 'efforts to bring peace to the region', 'n. 地区， 地带， 区域； 范围， 幅度', '/\'riːdʒən | \'ridʒən/', 'region', 2);
INSERT INTO `words` VALUES (7539, 'The tanker is registered in Rotterdam.', 'v. 登记， 注册； 指示， 自动记下； 表示， 表达； 注意到， 记住； 把挂号; n. 登记，注册；登记表，注册簿', '/\'redʒɪstə | \'rɛdʒɪstɚ/', 'register', 2);
INSERT INTO `words` VALUES (7540, 'Student registration (= for a course of study ) starts the first week in September.', 'n. 注册，登记', '/,redʒi\'streiʃən | ˌredʒɪˈstreɪʃn | \'rɛdʒɪ\'streʃən/', 'registration', 2);
INSERT INTO `words` VALUES (7541, 'Climate change is disrupting the regularity of the seasons.', 'n. 规则性；整齐，端正', '/,reɡju\'lærəti | reɡjʊ\'lærətɪ | ˌrɛɡjəˈlærətɪ/', 'regularity', 2);
INSERT INTO `words` VALUES (7542, 'People sweat to regulate their body heat.', 'v. 调整，调节，校准', '/\'reɡjuleit | \'regjʊleɪt | \'rɛɡjulet/', 'regulate', 2);
INSERT INTO `words` VALUES (7543, 'There seem to be so many rules and regulations these days.', 'n. 管理，规则', '/,reɡju\'leiʃən | ˌregjuˈleɪʃn | ˌrɛɡjəˈleʃən/', 'regulation', 2);
INSERT INTO `words` VALUES (7544, 'a wedding rehearsal', 'n. 排练， 排演', '/rɪ\'hɜːsl | rɪ\'hɝsl/', 'rehearsal', 2);
INSERT INTO `words` VALUES (7545, 'changes that took place during Charlemagne’s reign', 'n. （某君主的）统治时期', '/rein | reɪn | ren/', 'reign', 2);
INSERT INTO `words` VALUES (7546, '...They see how heavily the reimbursement deck is stacked against primary care...', 'n. 返还费用', '/,ri:im\'bə:smənt | ˌri:ɪm\'bɜ:smənt | ,riɪm\'bɝsmənt/', 'reimbursement', 2);
INSERT INTO `words` VALUES (7547, 'Cord held the reins while the stallion tugged and snorted.', 'n. 缰绳; vt. 勒缰使停步； 控制， 约束', '/reɪn | ren/', 'rein', 2);
INSERT INTO `words` VALUES (7548, 'The film reinforces the idea that women should be pretty and dumb.', 'v. 增强，提高', '/,ri:in\'fɔ:s | ˌri:ɪnˈfɔ:s | ,riɪn\'fɔrs/', 'reinforce', 2);
INSERT INTO `words` VALUES (7549, 'If inspectors find a defective can, the batch is rejected.', 'v. 舍弃，抛弃；排斥', '/ri\'dʒekt | rɪ\'dʒekt | rɪ\'dʒɛkt/', 'reject', 2);
INSERT INTO `words` VALUES (7550, 'They sent me a rejection letter.', 'n. 拒绝', '/rɪ\'dʒekʃn | rɪ\'dʒɛkʃən/', 'rejection', 2);
INSERT INTO `words` VALUES (7551, 'Garbo plays the queen, rejoicing in the love she has found with Antonio.', 'vi. 感到高兴， 充满喜悦', '/rɪ\'dʒɔɪs/', 'rejoice', 2);
INSERT INTO `words` VALUES (7552, 'The relative merits of both approaches have to be considered.', 'adj. 有关系的，相对的; n. 亲属， 亲戚', '/\'relətɪv | \'rɛlətɪv/', 'relative', 2);
INSERT INTO `words` VALUES (7553, 'The broadcasts were relayed by satellite.', 'v. 接替，转播', '/\'ri:lei, ri\'lei | \'riːleɪ | rɪ\'le/', 'relay', 2);
INSERT INTO `words` VALUES (7554, 'Police arrested several men, who were later released.', 'v. 释放，发布', '/ri\'li:s | rɪ\'li:s | rɪ\'lis/', 'release', 2);
INSERT INTO `words` VALUES (7555, 'Might it not be better to relegate the king to a purely ceremonial function?', 'vt. 使降位， 使降级； 把…委托给', '/\'relɪgeɪt | \'rɛlɪɡet/', 'relegate', 2);
INSERT INTO `words` VALUES (7556, 'Relevant documents were presented in court.', 'adj. 相关的', '/ˈreləvənt | \'rɛləvənt/', 'relevant', 2);
INSERT INTO `words` VALUES (7557, 'a birth control method that is cheap and reliable', 'adj. 可靠的', '/ri\'laiəbl | rɪˈlaɪəbl | rɪ\'laɪəbl/', 'reliable', 2);
INSERT INTO `words` VALUES (7558, 'the country’s heavy reliance on trade', 'n. 依靠， 依赖', '/rɪ\'laɪəns/', 'reliance', 2);
INSERT INTO `words` VALUES (7559, 'I felt a huge surge of relief and happiness.', 'n. 轻松， 宽慰； 缓解， 减轻， 解除； 使得到调剂； 接替， 替下', '/rɪ\'liːf | rɪ\'lif/', 'relief', 2);
INSERT INTO `words` VALUES (7560, 'Drugs helped to relieve the pain.', 'v. 减轻，缓解', '/ri\'li:v | rɪ\'li:v | rɪ\'liv/', 'relieve', 2);
INSERT INTO `words` VALUES (7561, 'A relieved smile spread over his face.', 'adj. 轻松的，缓解的', '/ri\'li:vd | rɪˈli:vd | rɪ\'livd/', 'relieved', 2);
INSERT INTO `words` VALUES (7562, 'people of different religions', 'n. 宗教', '/ri\'lidʒən | rɪ\'lɪdʒ(ə)n | rɪ\'lɪdʒən/', 'religion', 2);
INSERT INTO `words` VALUES (7563, 'I don’t share her religious beliefs .', 'adj. 宗教的； 笃信宗教的， 虔诚的', '/rɪ\'lɪdʒəs/', 'religious', 2);
INSERT INTO `words` VALUES (7564, 'a hot dog with mustard and relish', 'vt. 享受，从…中获得乐趣; n. 享受， 滋味， 乐趣； 调味品', '/\'relɪʃ | \'rɛlɪʃ/', 'relish', 2);
INSERT INTO `words` VALUES (7565, 'Wells finally agreed, but with reluctance.', 'n. 勉强，不情愿', '/ri\'lʌktəns | rɪ\'lʌktəns/', 'reluctance', 2);
INSERT INTO `words` VALUES (7566, 'She gave a reluctant smile.', 'adj. 不情愿的， 勉强的', '/rɪ\'lʌktənt/', 'reluctant', 2);
INSERT INTO `words` VALUES (7567, 'They relied heavily on the advice of their professional advisers.', 'vi. 依靠， 依赖； 信赖， 指望', '/rɪ\'laɪ/', 'rely', 2);
INSERT INTO `words` VALUES (7568, 'The refugees were allowed to remain in the UK.', 'vi. 剩下，余留，保持；仍然是; n. 残余； 残骸； 遗迹', '/rɪ\'meɪn | rɪ\'men/', 'remain', 2);
INSERT INTO `words` VALUES (7569, 'The remainder must be paid by the end of June.', 'n. 剩余（物）；余数', '/ri\'meində | rɪ\'meɪndə | rɪ\'mendɚ/', 'remainder', 2);
INSERT INTO `words` VALUES (7570, 'She has made remarkable progress.', 'adj. 显著的，杰出的', '/ri\'mɑ:kəbl | rɪˈmɑ:kəbl | rɪ\'mɑrkəbl/', 'remarkable', 2);
INSERT INTO `words` VALUES (7571, 'The problems in our schools do not have a simple remedy.', 'n. 补救办法，纠正办法；药品，治疗法; vt. 补救， 纠正； 医治， 治疗', '/\'remədi | \'rɛmədi/', 'remedy', 2);
INSERT INTO `words` VALUES (7572, 'Beneath the present church were remnants of Roman flooring.', 'n. 残留部分', '/\'remnənt | \'rɛmnənt/', 'remnant', 2);
INSERT INTO `words` VALUES (7573, 'a remote border town', 'adj. 遥远的， 偏僻的； 关系疏远的； 脱离的； 绝少的； 微乎其微的； 孤高的， 冷淡的', '/rɪ\'məut | rɪ\'mot/', 'remote', 2);
INSERT INTO `words` VALUES (7574, 'a cleaner that will remove wine stains', 'v. 消除，移除；更新', '/ri\'mu:v | rɪˈmu:v | rɪ\'muv/', 'remove', 2);
INSERT INTO `words` VALUES (7575, '...the Renaissance masterpieces in London\'s galleries.', 'n. 文艺复兴， 文艺复兴时期； 复兴， 再生', '/rɪ\'neɪsns | ˈrenəsɑ:ns; ˌrɛnəˈsɑns/', 'renaissance', 2);
INSERT INTO `words` VALUES (7576, 'an obligation to render assistance to those in need', 'v. 给予', '/\'rendə | \'rɛndɚ/', 'render', 2);
INSERT INTO `words` VALUES (7577, 'It’s a six-month lease but it’s renewable.', 'adj. 可再生的', '/ri\'nju:əbl | rɪˈnjuːəbl | rɪ\'nuəbl/', 'renewable', 2);
INSERT INTO `words` VALUES (7578, 'Your mortgage will be repaid over 25 years.', 'v. 偿还；报答', '/ri:\'pei, ri- | riː\'peɪ; rɪ- | ri\'pɛi/', 'repay', 2);
INSERT INTO `words` VALUES (7579, 'The government has just repealed the law segregating public facilities.', 'v. 撤销', '/ri\'pi:l | rɪ\'piːl | rɪ\'pil/', 'repeal', 2);
INSERT INTO `words` VALUES (7580, 'The smell repelled him.', 'v. 使厌恶；拒绝', '/ri\'pel | rɪ\'pel | rɪ\'pɛl/', 'repel', 2);
INSERT INTO `words` VALUES (7581, 'the behavioural repertoire of infants', 'n. 全部节目', '/\'repətwɑː | \'rɛpɚ\'twɑr/', 'repertoire', 2);
INSERT INTO `words` VALUES (7582, 'The song was dreary and repetitive.', 'adj. 重复的， 反复性的', '/rɪ\'petətɪv | rɪ\'pɛtətɪv/', 'repetitive', 2);
INSERT INTO `words` VALUES (7583, 'He replaced the book on the shelf.', 'v. 把...放回原处', '/ri\'pleis | rɪ\'pleɪs | rɪ\'ples/', 'replace', 2);
INSERT INTO `words` VALUES (7584, 'Our old car is badly in need of replacement.', 'n. 代替', '/ri\'pleismənt | rɪ\'pleɪsmənt | rɪ\'plesmənt/', 'replacement', 2);
INSERT INTO `words` VALUES (7585, 'Government officials have denied reports of rebel advances.', 'n. 传说，议论', '/ri\'pɔ:t | rɪ\'pɔːt | rɪ\'pɔrt/', 'report', 2);
INSERT INTO `words` VALUES (7586, 'Mr Kobayashi was chosen to represent the company at the conference.', 'vt. 作为…的代表， 表示， 象征； 描绘， 表现', '/ˌreprɪ\'zent | ,rɛprɪ\'zɛnt/', 'represent', 2);
INSERT INTO `words` VALUES (7587, 'The clock in the painting is a symbolic representation of the passage of time.', 'n. 描写；陈述；代表', '/,reprizen\'teiʃən | ,reprɪzen\'teɪʃ(ə)n | \'rɛprɪzɛn\'teʃən/', 'representation', 2);
INSERT INTO `words` VALUES (7588, 'a union representative', 'n. 代表', '/,repri\'zentətiv | ˌreprɪˈzentətɪv | \'rɛprɪ\'zɛntətɪv/', 'representative', 2);
INSERT INTO `words` VALUES (7589, '{\"COLLOINEXA\":[\"sexual repression\"]}', 'n. 压抑， 压制， 镇压', '/rɪ\'preʃn | rɪ\'prɛʃən/', 'repression', 2);
INSERT INTO `words` VALUES (7590, '‘You don’t need me,’ she said quietly, without reproach.', 'n&vt. 责备， 批评', '/rɪ\'prəutʃ | rɪ\'protʃ/', 'reproach', 2);
INSERT INTO `words` VALUES (7591, 'The effect has proved hard to reproduce.', 'v. 仿造', '/,ri:prə\'dju:s | riːprə\'djuːs | ,riprə\'dus/', 'reproduce', 2);
INSERT INTO `words` VALUES (7592, 'Scientists studied the reproduction, diet, and health of the dolphins.', 'n. 繁殖', '/,ri:prə\'dʌkʃən | ˌri:prəˈdʌkʃn | ,riprə\'dʌkʃən/', 'reproduction', 2);
INSERT INTO `words` VALUES (7593, 'This small reptile, which measures just 10 centimeters long, can swim through the sand dunes at up to 15 centimeters per second.', 'n. 爬行动物', NULL, 'reptile', 2);
INSERT INTO `words` VALUES (7594, 'Alice Munro has a reputation for being a very depressing writer.', 'n. 名誉， 名气， 名声', '/ˌrepju\'teɪʃn | ,rɛpju\'teʃən/', 'reputation', 2);
INSERT INTO `words` VALUES (7595, 'He lacks the requisite qualifications.', 'adj. 需要的，必要的; n. 必需品', '/\'rekwizit | \'rekwɪzɪt | \'rɛkwəzɪt/', 'requisite', 2);
INSERT INTO `words` VALUES (7596, 'The resemblance between Susan and her sister was remarkable.', 'n. 相似，相似性', '/ri\'zembləns | rɪ\'zembl(ə)ns | rɪ\'zɛmbləns/', 'resemblance', 2);
INSERT INTO `words` VALUES (7597, 'Paul resented the fact that Carol didn’t trust him.', 'v. 对…不满，怨恨', '/ri\'zent | rɪ\'zent | rɪ\'zɛnt/', 'resent', 2);
INSERT INTO `words` VALUES (7598, 'a dinner reservation', 'n. 预定', '/,rezə\'veiʃən | ˌrezə\'veɪʃn | ,rɛzɚ\'veʃən/', 'reservation', 2);
INSERT INTO `words` VALUES (7599, 'She overcame her own natural reserve.', 'n. 缄默，自我克制', '/rɪ\'zɜːv | rɪ\'zɝv/', 'reserve', 2);
INSERT INTO `words` VALUES (7600, 'He was unemotional, quiet, and reserved.', 'adj. 保留意见的；矜持的', '/rɪˈzɜ:vd | rɪ\'zɝvd/', 'reserved', 2);
INSERT INTO `words` VALUES (7601, 'He spent most of his time in Rutherglen, where his family resided.', 'v. 居住，驻扎；属于', '/rɪ\'zaɪd/', 'reside', 2);
INSERT INTO `words` VALUES (7602, 'As one local resident put it in May, \"By day there is government.', 'n. 居民', '/ˈrezɪdənt | \'rɛzɪdənt/', 'resident', 2);
INSERT INTO `words` VALUES (7603, 'a quiet residential neighbourhood', 'adj. 居住的， 住宅的； 寄宿的， 住在住所的', '/ˌrezɪ\'denʃl | ,rɛzɪ\'dɛnʃl/', 'residential', 2);
INSERT INTO `words` VALUES (7604, 'the residual effects of drug treatment', 'adj. 剩余的；残余的', '/ri\'zidjuəl, -dʒu- | rɪ\'zɪdjʊəl | rɪ\'zɪdʒuəl/', 'residual', 2);
INSERT INTO `words` VALUES (7605, 'A hospital administrator has resigned over claims he lied to get the job.', 'v. 辞职', '/ri\'zain | rɪ\'zaɪn/', 'resign', 2);
INSERT INTO `words` VALUES (7606, 'She gave a sigh of resignation.', 'n. 听从，屈从，顺从', '/,reziɡ\'neiʃən | rezɪg\'neɪʃ(ə)n | ,rɛzɪɡ\'neʃən/', 'resignation', 2);
INSERT INTO `words` VALUES (7607, 'He was charged with trying to resist arrest .', 'v. 抵制', '/ri\'zist | rɪ\'zɪst/', 'resist', 2);
INSERT INTO `words` VALUES (7608, 'Some people are very resistant to the idea of exercise.', 'adj. 抵抗的； 抗…的， 耐…的', '/rɪ\'zɪstənt/', 'resistant', 2);
INSERT INTO `words` VALUES (7609, 'resolute opposition', 'adj. 坚定的', '/\'rezəlju:t, -lət | \'rezəlu:t | \'rɛzəlut/', 'resolute', 2);
INSERT INTO `words` VALUES (7610, 'Barnet was desperate for money to resolve his financial problems.', 'v. 决定；解决；分解; n. 决心', '/rɪ\'zɒlv | rɪ\'zɑlv/', 'resolve', 2);
INSERT INTO `words` VALUES (7611, 'Lagoon Reef is one of the best resort hotels.', 'n. 度假胜地', '/ri\'zɔ:t | rɪ\'zɔ:t | rɪ\'zɔrt/', 'resort', 2);
INSERT INTO `words` VALUES (7612, 'hard-working, respectable people', 'adj. 可敬的；人格高尚的', '/ri\'spektəbl | rɪ\'spektəb(ə)l | rɪ\'spɛktəbl/', 'respectable', 2);
INSERT INTO `words` VALUES (7613, 'We all went back to our respective homes to wait for news.', 'adj. 各自的', '/ri\'spektiv | rɪˈspektɪv | rɪ\'spɛktɪv/', 'respective', 2);
INSERT INTO `words` VALUES (7614, 'They are likely to respond positively to the president\'s request for aid.', 'vi. 回答， 答复； 作出反应， 响应', '/rɪ\'spɒnd | rɪ\'spɑnd/', 'respond', 2);
INSERT INTO `words` VALUES (7615, 'Carl made no response, and carried on with his meal.', 'n. 回应', '/ri\'spɔns | rɪ\'spɒns | rɪ\'spɑns/', 'response', 2);
INSERT INTO `words` VALUES (7616, 'Kelly’s promotion means more money and more responsibility.', 'n. 责任', '/ri.spɔnsə\'biliti | rɪˌspɒnsə\'bɪlətɪ | rɪˌspɑːnsəˈbɪləti/', 'responsibility', 2);
INSERT INTO `words` VALUES (7617, 'You can leave the children with Billy – he’s very responsible.', 'adj. 可靠的；责任重大的', '/ri\'spɔnsəbl | rɪ\'spɒnsɪb(ə)l | rɪ\'spɑnsəbl/', 'responsible', 2);
INSERT INTO `words` VALUES (7618, 'a car with highly responsive steering', 'adj. 灵敏的，反应的', '/ri\'spɔnsiv | rɪˈspɒnsɪv | rɪ\'spɑnsɪv/', 'responsive', 2);
INSERT INTO `words` VALUES (7619, 'She was hoping that the Mediterranean climate would restore her to full health.', 'vt. 恢复， 使恢复； 修复， 整修； 归还， 交还', '/rɪ\'stɔː | rɪ\'stɔr/', 'restore', 2);
INSERT INTO `words` VALUES (7620, 'I had to restrain her from running out into the street.', 'v. 制止；抑制', '/ri\'strein | rɪ\'streɪn | rɪ\'stren/', 'restrain', 2);
INSERT INTO `words` VALUES (7621, 'The police were praised for their restraint in handling the demonstrators.', 'n. 抑制， 限制， 克制； 约束措施， 约束条件', '/rɪ\'streɪnt | rɪ\'strent/', 'restraint', 2);
INSERT INTO `words` VALUES (7622, 'The new law restricts the sale of hand guns.', 'v. 限制', '/ri\'strikt | rɪ\'strɪkt/', 'restrict', 2);
INSERT INTO `words` VALUES (7623, 'proposals to radically restructure Britain’s electronics industry', 'v. 调整，重建', '/ri:\'strʌktʃə | riː\'strʌktʃə | ri\'strʌktʃɚ/', 'restructure', 2);
INSERT INTO `words` VALUES (7624, 'She is still trying to get over the attack and the resultant injuries.', 'adj. 作为结果而发生的', '/rɪ\'zʌltənt/', 'resultant', 2);
INSERT INTO `words` VALUES (7625, 'Don\'t push for an interview on the spot, but rather explain that you want to let them know of your interest, drop off your resume, and complete an application while you\'re there if possible.', 'n. 简历', '/rezju:\'mei, ri\'zju:m; -\'zu:m | ˈrezəmeɪ/', 'resume', 2);
INSERT INTO `words` VALUES (7626, 'a retail price of £8.99', 'n. 零售', '/\'ri:teil | \'riːteɪl | \'ritel/', 'retail', 2);
INSERT INTO `words` VALUES (7627, 'Furniture and carpet retailers are among those reporting the sharpest annual decline in sales.', 'n. 零售商', '/\'ri:teilə | ˈri:teɪlə(r)/', 'retailer', 2);
INSERT INTO `words` VALUES (7628, 'You have the right to retain possession of the goods.', 'vt. 保留， 保持', '/rɪ\'teɪn | rɪ\'ten/', 'retain', 2);
INSERT INTO `words` VALUES (7629, 'Cold weather retards the growth of many plants.', 'v. 阻碍；减缓；放慢', '/ri\'tɑ:d | \'rɪtɑːd | \'rɪtɑrd/', 'retard', 2);
INSERT INTO `words` VALUES (7630, 'The Citizens\' Forum supported special powers for Quebec but also argued for the retention of a strong central government.', 'n. 保留， 保持', '/rɪ\'tenʃn | rɪ\'tɛnʃən/', 'retention', 2);
INSERT INTO `words` VALUES (7631, 'She took early retirement (= retired at an earlier age than usual ) last year.', 'n. 退休，引退；退隐', '/ri\'taiəmənt | rɪ\'taɪəm(ə)nt | rɪ\'taɪɚmənt/', 'retirement', 2);
INSERT INTO `words` VALUES (7632, '‘It’s all your fault!’ he retorted.', 'v. 反击；反驳', '/ri\'tɔ:t | rɪ\'tɔːt | rɪ\'tɔrt/', 'retort', 2);
INSERT INTO `words` VALUES (7633, 'She bent down to retrieve her earring.', 'vi. 重新得到， 取回， 收回； 挽回， 补救； 检索', '/rɪ\'triːv | rɪ\'triv/', 'retrieve', 2);
INSERT INTO `words` VALUES (7634, 'In retrospect, I wonder if we should have done more.', 'n. 回顾', '/\'retrəspekt | \'rɛtrəspɛkt/', 'retrospect', 2);
INSERT INTO `words` VALUES (7635, 'an annual reunion', 'n. 团聚', '/ˌri:\'ju:nɪən/', 'reunion', 2);
INSERT INTO `words` VALUES (7636, 'He may be prosecuted for revealing secrets about the security agency.', 'v. 揭露', '/ri\'vi:l | rɪ\'vi:l | rɪ\'vil/', 'reveal', 2);
INSERT INTO `words` VALUES (7637, '...the seemingly everlasting revelations about his private life.', 'n. 被提示的真相， 新发现； 揭示， 透露， 显示', '/ˌrevə\'leɪʃn | \'rɛvə\'leʃən/', 'revelation', 2);
INSERT INTO `words` VALUES (7638, 'The attackers were said to be taking revenge on the 14-year-old, claiming he was a school bully.', 'n. 报复，报仇; vt. 为…报仇， 报…之仇', '/rɪ\'vendʒ | rɪ\'vɛndʒ/', 'revenge', 2);
INSERT INTO `words` VALUES (7639, 'advertising revenue', 'n. 收入', '/\'revənju:, -nu: | \'revənju: | \'rɛvənu/', 'revenue', 2);
INSERT INTO `words` VALUES (7640, 'The results were read out in reverse order (= with the worst first and the best last ) .', 'adj. 相反的', '/ri\'və:s | rɪ\'vɜ:s | rɪ\'vɝs/', 'reverse', 2);
INSERT INTO `words` VALUES (7641, 'Local people have decided to revive this centuries-old tradition.', 'v. 复苏', '/ri\'vaiv | rɪ\'vaɪv/', 'revive', 2);
INSERT INTO `words` VALUES (7642, 'The new cancer drug is a revolutionary breakthrough.', 'adj. 革命的；革新的; n. 革命者', '/ˌrevə\'luːʃənəri | \'rɛvə\'lʊʃə\'nɛri/', 'revolutionary', 2);
INSERT INTO `words` VALUES (7643, 'New technology is going to revolutionize everything we do.', 'v. 革命化', '/,revə\'lju:ʃənaiz | ˌrevə\'lu:ʃənaɪz | \'rɛvə\'lʊʃə\'naɪz/', 'revolutionize', 2);
INSERT INTO `words` VALUES (7644, 'The wheel began to revolve.', 'v. （使）旋转', '/ri\'vɔlv, -\'vɔ:lv | rɪ\'vɒlv | rɪ\'vɔlv/', 'revolve', 2);
INSERT INTO `words` VALUES (7645, 'The school has a system of rewards and punishments to encourage good behaviour.', 'n. 报答，奖赏；报酬，酬金; vt. 报答， 酬谢， 奖励', '/rɪ\'wɔːd | rɪ\'wɔrd/', 'reward', 2);
INSERT INTO `words` VALUES (7646, 'Teaching can be a very rewarding career.', 'adj. 有回报的', '/ri\'wɔ:diŋ | rɪˈwɔ:dɪŋ | rɪ\'wɔrdɪŋ/', 'rewarding', 2);
INSERT INTO `words` VALUES (7647, 'a speech full of rhetorical phrases', 'adj. 修辞的', '/ri\'tɔrikəl, -\'tɔ:- | rɪˈtɒrɪkl | rɪ\'tɔrɪkl/', 'rhetorical', 2);
INSERT INTO `words` VALUES (7648, 'Drums are basic to African rhythm.', 'n. 节奏', '/\'riðəm, \'riθəm | ˈrɪðəm | \'rɪðəm/', 'rhythm', 2);
INSERT INTO `words` VALUES (7649, 'At the time, his ideas were ridiculed.', 'v. 嘲弄，挖苦; n. 嘲弄，挖苦', '/\'ridikju:l | \'rɪdɪkjuːl | \'rɪdɪ\'kjʊl/', 'ridicule', 2);
INSERT INTO `words` VALUES (7650, 'That’s a ridiculous idea!', 'adj. 滑稽的，可笑的', '/ri\'dikjuləs | rɪˈdɪkjələs | rɪ\'dɪkjələs/', 'ridiculous', 2);
INSERT INTO `words` VALUES (7651, 'Some international observers have claimed the election was rigged.', 'vt. 操纵，垄断；给装配帆及索具；用临时替代材料迅速搭起; n. 船桅的装置， 成套器械', '/rɪg | rɪɡ/', 'rig', 2);
INSERT INTO `words` VALUES (7652, 'rigid and authoritarian methods of education', 'adj. 严格的', '/\'ridʒid | \'rɪdʒɪd/', 'rigid', 2);
INSERT INTO `words` VALUES (7653, 'We are not so much testing as proposal-thinning, and we can add rigor such as traceability and other documentation as the leading architectural candidates emerge.', 'n. 严格', '/\'riɡə | \'rɪgɚ/', 'rigor', 2);
INSERT INTO `words` VALUES (7654, 'a rigorous analysis of defence needs', 'adj. 严格的', '/\'riɡərəs | ˈrɪgərəs | \'rɪɡərəs/', 'rigorous', 2);
INSERT INTO `words` VALUES (7655, 'the rim of a glass', 'n. 边；边缘，（眼镜）框', '/rim | rɪm/', 'rim', 2);
INSERT INTO `words` VALUES (7656, 'Let me just rinse my hands.', 'v. 冲洗；嗽（口）', '/rins | rɪns/', 'rinse', 2);
INSERT INTO `words` VALUES (7657, 'urban riots', 'n. 骚乱，暴乱; v. 发动骚乱', '/\'raiət | \'raɪət/', 'riot', 2);
INSERT INTO `words` VALUES (7658, 'Her clothes had all been ripped.', 'v. 撕，扯破，划破', '/rip | rɪp/', 'rip', 2);
INSERT INTO `words` VALUES (7659, 'ripples on the surface of the pond', 'n. 涟漪，细浪，波纹', '/\'ripl | \'rɪp(ə)l | \'rɪpl/', 'ripple', 2);
INSERT INTO `words` VALUES (7660, 'ancient pagan rituals', 'n. 仪式', '/\'ritjuəl, -tʃu- | \'rɪtʃʊəl | \'rɪtʃuəl/', 'ritual', 2);
INSERT INTO `words` VALUES (7661, 'This gives the company a competitive advantage over its rivals.', 'n. 对手', '/\'raivəl | ˈraɪvl | \'raɪvl/', 'rival', 2);
INSERT INTO `words` VALUES (7662, 'The two players have developed a friendly rivalry .', 'n. 竞争， 竞赛； 对抗', '/\'raɪvlri/', 'rivalry', 2);
INSERT INTO `words` VALUES (7663, 'Chickens and geese roam freely in the back yard.', 'v. 在…漫步，漫游', '/rəum | rəʊm | rom/', 'roam', 2);
INSERT INTO `words` VALUES (7664, 'Police are investigating a series of bank robberies in South Wales.', 'n. 抢劫', '/\'rɔbəri | \'rɒbərɪ | \'rɑbəri/', 'robbery', 2);
INSERT INTO `words` VALUES (7665, 'a robust man of six feet four', 'adj. 强健的', '/rəu\'bʌst, \'rəubʌst | rə(ʊ)\'bʌst | ro\'bʌst/', 'robust', 2);
INSERT INTO `words` VALUES (7666, 'a paint roller', 'n. 滚筒；滚柱', '/\'rəulə | \'rəʊlə | \'rolɚ/', 'roller', 2);
INSERT INTO `words` VALUES (7667, 'When they conquered Britain, the Romans brought this custom with them.', 'n. 古罗马人；罗马人', '/\'rəumən | \'rəʊmən | \'romən/', 'Roman', 2);
INSERT INTO `words` VALUES (7668, 'a Medieval romance', 'n. 传奇；浪漫文学', '/rəu\'mæns, \'rəumæns, rə\'mæns | rə(ʊ)\'mæns; \'rəʊmæns | ro\'mæns/', 'romance', 2);
INSERT INTO `words` VALUES (7669, '‘Tom always sends me red roses on my birthday.’ ‘How romantic!’', 'adj. 爱情的', '/rəu\'mæntik | rəʊˈmæntɪk | ro\'mæntɪk/', 'romantic', 2);
INSERT INTO `words` VALUES (7670, 'I heard a rooster crow.', 'n. 公鸡', '/\'ru:stə | \'ruːstə | \'rustɚ/', 'rooster', 2);
INSERT INTO `words` VALUES (7671, 'Candy will rot your teeth.', 'v. 腐烂，腐朽; n. 腐烂， 腐朽', '/rɒt | rɑt/', 'rot', 2);
INSERT INTO `words` VALUES (7672, 'the rotary movement of the helicopter blades', 'adj. 旋转的， 转动的', '/\'rəutəri | \'rotəri/', 'rotary', 2);
INSERT INTO `words` VALUES (7673, 'The Earth rotates on its axis once every 24 hours.', 'v. （使）旋转', '/rəu\'teit, \'rəut-, \'rəuteit | rə(ʊ)\'teɪt | \'rotet/', 'rotate', 2);
INSERT INTO `words` VALUES (7674, 'He told us, in a very roundabout way, that he was thinking of leaving.', 'adj. 转弯抹角的；迂回的', '/\'raundə,baut | \'raʊndəbaʊt/', 'roundabout', 2);
INSERT INTO `words` VALUES (7675, 'You mustn’t worry. These are just routine enquiries.', 'adj. 日常的; n. 常规', '/ru:\'ti:n | ruː\'tiːn | rʊ\'tin/', 'routine', 2);
INSERT INTO `words` VALUES (7676, 'Jenny used to row at college (= as a sport ) .', 'v. 划船', '/rəu | rəʊ | ro/', 'row', 2);
INSERT INTO `words` VALUES (7677, 'At school the other children treated them like royalty.', 'n. 皇家，王族，皇族', '/\'rɔiəlti | \'rɒɪəltɪ | \'rɔɪəlti/', 'royalty', 2);
INSERT INTO `words` VALUES (7678, '...a ruby and diamond ring.', 'n. 红宝石', '/\'ru:bi | \'ruːbɪ | \'rubi/', 'ruby', 2);
INSERT INTO `words` VALUES (7679, 'This illness has ruined my life.', 'v. 毁坏', '/\'ruin, \'ru:- | \'ru:ɪn | \'ruɪn/', 'ruin', 2);
INSERT INTO `words` VALUES (7680, 'The judge ruled that she should have custody of the children.', 'v. 裁决，裁定', '/ru:l | ruːl | rul/', 'rule', 2);
INSERT INTO `words` VALUES (7681, 'Goodwin tried to have the court ruling overturned.', 'n. 裁定', '/\'ru:liŋ | ˈru:lɪŋ | \'rulɪŋ/', 'ruling', 2);
INSERT INTO `words` VALUES (7682, 'The pipe will rupture at its weakest point.', 'v. 破裂; n. 破裂，裂开；决裂，断绝', '/\'rʌptʃə | \'rʌptʃɚ/', 'rupture', 2);
INSERT INTO `words` VALUES (7683, 'She moved nearer, her long silk skirt rustling around her.', 'v. 发出沙沙声', '/\'rʌsl/', 'rustle', 2);
INSERT INTO `words` VALUES (7684, 'a ruthless dictator', 'adj. 无情的，冷酷的', '/\'ru:θlis | \'ruːθlɪs | \'rʊθləs/', 'ruthless', 2);
INSERT INTO `words` VALUES (7685, 'a sacred vow', 'adj. 神圣的； 宗教的； 神圣不可侵犯的', '/\'seɪkrɪd | \'sekrɪd/', 'sacred', 2);
INSERT INTO `words` VALUES (7686, 'The minister stressed the need for economic sacrifice.', 'n&v. 牺牲， 舍身； 献祭， 供奉； 祭品', '/\'sækrɪfaɪs/', 'sacrifice', 2);
INSERT INTO `words` VALUES (7687, 'International safeguards prevent the increase of nuclear weapons.', 'n. 保护措施', '/\'seifɡɑ:d | \'seɪfgɑːd | \'sefɡɑrd/', 'safeguard', 2);
INSERT INTO `words` VALUES (7688, 'He moved to the seaside for the sake of his health.', 'n. 缘故， 理由', '/seɪk | sek/', 'sake', 2);
INSERT INTO `words` VALUES (7689, 'a saleable commodity', 'adj. 适合销售的', '/\'seɪləbl | \'seləbl/', 'saleable', 2);
INSERT INTO `words` VALUES (7690, 'a whole salmon', 'n. 鲑，大马哈鱼', '/\'sæmən/', 'salmon', 2);
INSERT INTO `words` VALUES (7691, 'The two soldiers saluted Lieutenant Cecil.', 'v. （向…）行军礼，（向…）致敬', '/sə\'lju:t, sɑ:\'lu:te | sə\'l(j)uːt | sə\'lut/', 'salute', 2);
INSERT INTO `words` VALUES (7692, 'The church\'s message of salvation has changed the lives of many.', 'n. 拯救， 解救； 解救措施', '/sæl\'veɪʃn | sæl\'veʃən/', 'salvation', 2);
INSERT INTO `words` VALUES (7693, 'They took a blood sample to test for hepatitis.', 'n. 样本，样品', '/\'sɑ:mpl, \'sæ- | \'sɑ:mpl | \'sæmpl/', 'sample', 2);
INSERT INTO `words` VALUES (7694, 'The church refused to sanction the king’s second marriage.', 'vt. 批准，认可; n. 批准， 认可； 约束因素， 约束力； 国际制裁', '/\'sæŋkʃn | \'sæŋkʃən/', 'sanction', 2);
INSERT INTO `words` VALUES (7695, 'Carefully split the sponge ring, then sandwich the two halves together with whipped cream.', 'v. 夹入，挤进', '/\'sænwidʒ | \'sæn(d)wɪdʒ; -wɪtʃ | \'sænwɪtʃ/', 'sandwich', 2);
INSERT INTO `words` VALUES (7696, 'Overcrowding and poor sanitation are common problems in prisons.', 'n. 卫生环境，卫生设备', '/,sæni\'teiʃən | sænɪ\'teɪʃ(ə)n | ,sænɪ\'teʃən/', 'sanitation', 2);
INSERT INTO `words` VALUES (7697, 'commuters packed like sardines on the evening train', 'n. 沙丁鱼', '/\'sɑ:di:n, sɑ:\'di:n | sɑː\'diːn | ,sɑr\'din/', 'sardine', 2);
INSERT INTO `words` VALUES (7698, 'a satellite country', 'n. 附属国', '/\'sætəlait | \'sætəlaɪt/', 'satellite', 2);
INSERT INTO `words` VALUES (7699, 'She got great satisfaction from helping people to learn.', 'n. 满足，愉快', '/,sætis\'fækʃən | sætɪs\'fækʃ(ə)n | ,sætɪs\'fækʃən/', 'satisfaction', 2);
INSERT INTO `words` VALUES (7700, 'Her disappearance has never been satisfactorily explained.', 'adv. 圆满地', '/,sætis\'fæktərəli | ,sætɪs\'fæktərəlɪ | ˌsætɪs\'fæktərɪlɪ/', 'satisfactorily', 2);
INSERT INTO `words` VALUES (7701, 'Water poured through the hole, saturating the carpet.', 'vt. 使湿透， 浸透； 使充满， 使饱和', '/\'sætʃəreɪt | \'sætʃərɪt/', 'saturate', 2);
INSERT INTO `words` VALUES (7702, 'a business beset by price wars and market saturation (= the fact that no new customers can be found)', 'n. 饱和（状态）；浸透', '/,sætʃə\'reiʃən | sætʃə\'reɪʃ(ə)n | \'sætʃə\'reʃən/', 'saturation', 2);
INSERT INTO `words` VALUES (7703, 'Saturn is the second biggest planet in the solar system.', 'n. 土星', NULL, 'Saturn', 2);
INSERT INTO `words` VALUES (7704, 'a savage dog', 'adj. 残暴的，凶猛的，粗鲁的；未开化的，野蛮的; n. 野蛮人，粗鲁的人; vt. 乱咬； 激烈抨击', '/\'sævɪdʒ/', 'savage', 2);
INSERT INTO `words` VALUES (7705, 'Workers have erected scaffolding around the base of the tower below the roadway.', 'n. 脚手架', '/\'skæfəldiŋ, -fəu- | ˈskæfəldɪŋ | \'skæfəldɪŋ/', 'scaffolding', 2);
INSERT INTO `words` VALUES (7706, 'A structural survey revealed the full scale of the damage.', 'n. 大小，规模；等级，级别；天平，磅秤；比例；刻度，标度；鳞; vt. 攀登， 爬越', '/skeɪl | skel/', 'scale', 2);
INSERT INTO `words` VALUES (7707, 'The scan showed that she was expecting twins.', 'n. 扫描', '/skæn/', 'scan', 2);
INSERT INTO `words` VALUES (7708, 'It caused quite a scandal when he left his wife.', 'n. 丑闻', '/\'skændəl | \'skændl/', 'scandal', 2);
INSERT INTO `words` VALUES (7709, 'a deep cut that could leave a permanent scar', 'n. 瘢痕', '/skɑ: | skɑː | skɑr/', 'scar', 2);
INSERT INTO `words` VALUES (7710, '...an ever increasing scarcity of water.', 'n. 缺乏', '/\'skεəsəti | \'skeəsətɪ | \'skɛrsəti/', 'scarcity', 2);
INSERT INTO `words` VALUES (7711, 'You really gave us a scare !', 'n. 恐吓，惊恐', '/skεə | skeə(r) | skɛr/', 'scare', 2);
INSERT INTO `words` VALUES (7712, 'scarlet berries', 'n. 猩红色; adj. 猩红的', '/\'skɑ:lət | \'skɑːlət | \'skɑrlɪt/', 'scarlet', 2);
INSERT INTO `words` VALUES (7713, 'a scary moment', 'adj. 可怕的， 骇人的； 惊慌的， 害怕的； 胆小的， 易受惊的', '/\'skeəri | \'skɛri/', 'scary', 2);
INSERT INTO `words` VALUES (7714, 'The sound of gunfire made the crowd scatter in all directions.', 'vt. 撒， 散播； 使散开， 驱散', '/\'skætə | \'skætɚ/', 'scatter', 2);
INSERT INTO `words` VALUES (7715, 'a yellow rose with a lovely scent', 'n. 味道', '/sent | sɛnt/', 'scent', 2);
INSERT INTO `words` VALUES (7716, 'A tight schedule means we can\'t delay any longer.', 'n. 时间表', '/\'ʃədju:əl, -dʒu:əl, \'skedʒu:əl, -dʒuəl | \'ʃedjuːl | \'skɛdʒul; (canadian) ˈʃɛdʒʊl; ˈʃɛdjʊl/', 'schedule', 2);
INSERT INTO `words` VALUES (7717, 'Everyone\'s always scheming and plotting.', 'v. 计划，搞阴谋', '/ski:m | skiːm | skim/', 'scheme', 2);
INSERT INTO `words` VALUES (7718, 'She won a scholarship to Iowa State University.', 'n. 奖学金；学问，学识', '/\'skɔləʃip | \'skɒləʃɪp | \'skɑlɚʃɪp/', 'scholarship', 2);
INSERT INTO `words` VALUES (7719, '‘You, a scientist!’ he scoffed.', 'v. 嘲笑，嘲弄', '/skɔf, skɔ:f | skɒf | skɔf/', 'scoff', 2);
INSERT INTO `words` VALUES (7720, 'Time and again we have scooped our rivals.', 'v. 舀出； 抢在之前报道新闻; n. 勺子；抢先报道的新闻', '/skuːp | skup/', 'scoop', 2);
