INSERT INTO `words` VALUES (7722, 'I scorched my dress when I was ironing it.', 'v. 烧焦；枯萎', '/skɔ:tʃ | skɔːtʃ | skɔrtʃ/', 'scorch', 2);
INSERT INTO `words` VALUES (7723, 'At half-time the score was one all.', 'n. 得分，比数，成绩；二十; vt. 分， 给…打分； 画线于； 获胜', '/skɔː | skɔ/', 'score', 2);
INSERT INTO `words` VALUES (7724, 'Researchers greeted the proposal with scorn.', 'n. 轻蔑，鄙视; vt. 轻蔑， 鄙视； 拒绝， 不屑', '/skɔːn | skɔrn/', 'scorn', 2);
INSERT INTO `words` VALUES (7725, 'They scouted the area for somewhere to stay the night.', 'v. 搜索，侦察', '/skaut | skaʊt/', 'scout', 2);
INSERT INTO `words` VALUES (7726, 'They tried to scramble up the cliff.', 'v. 爬行，攀登; n. 爬行，攀登', '/\'skræmbl | \'skræmb(ə)l/', 'scramble', 2);
INSERT INTO `words` VALUES (7727, 'a rug made out of old scraps of material', 'n. 碎片；废料; v. 废弃', '/skræp/', 'scrap', 2);
INSERT INTO `words` VALUES (7728, 'Scrape the carrots and slice them thinly.', 'v. 刮，擦；勉强过日子; n. 刮， 擦； 刮擦声', '/skreɪp | skrep/', 'scrape', 2);
INSERT INTO `words` VALUES (7729, 'There were deep scratches all over her face.', 'n. （某人皮肤上的）划痕，划伤', '/skrætʃ/', 'scratch', 2);
INSERT INTO `words` VALUES (7730, 'Fix the frame in position and tighten the screws .', 'n. 螺丝; vt. 用螺钉固定， 拧， 拧紧', '/skruː | skru/', 'screw', 2);
INSERT INTO `words` VALUES (7731, 'They write all their own scripts.', 'n. 脚本，剧本', '/skript | skrɪpt/', 'script', 2);
INSERT INTO `words` VALUES (7732, 'the way God is portrayed in Scripture', 'n. 《圣经》；圣书', '/\'skriptʃə | \'skrɪptʃə | \'skrɪptʃɚ/', 'scripture', 2);
INSERT INTO `words` VALUES (7733, 'She was on her hands and knees scrubbing the floor.', 'v. 擦洗，擦净; n. 擦洗', '/skrʌb/', 'scrub', 2);
INSERT INTO `words` VALUES (7734, 'Their activities have come under police scrutiny .', 'n. 详细检查， 仔细观察', '/\'skruːtəni | \'skrutəni/', 'scrutiny', 2);
INSERT INTO `words` VALUES (7735, '...stone sculptures of figures and animals.', 'n. 雕塑', '/\'skʌlptʃə | \'skʌlptʃə(r) | \'skʌlptʃɚ/', 'sculpture', 2);
INSERT INTO `words` VALUES (7736, 'She was repairing Billy’s trousers, where the seam had come undone.', 'n. 缝口；接缝；骨缝', '/si:m | siːm | sim/', 'seam', 2);
