INSERT INTO `words` VALUES (7738, 'It was quite rough at times, and she was seasick.', 'adj. 晕船的', '/\'si:sik | ˈsiːsɪk | \'sisɪk/', 'seasick', 2);
INSERT INTO `words` VALUES (7739, 'a trip to the seaside', 'n. 海滨（胜地）；海边', '/\'si:said | \'siːsaɪd | \'sisaɪd/', 'seaside', 2);
INSERT INTO `words` VALUES (7740, 'Any proposal must be seconded by two other members of the committee.', 'v. 支持', '/\'sekənd | \'sek(ə)nd | \'sɛkənd/', 'second', 2);
INSERT INTO `words` VALUES (7741, 'The plane’s tail section was found in a cornfield.', 'n. 部分', '/\'sekʃ(ə)n | \'sɛkʃən/', 'section', 2);
INSERT INTO `words` VALUES (7742, '...the nation\'s manufacturing sector.', 'n. 部门', '/\'sektə | \'sektə(r) | \'sɛktɚ/', 'sector', 2);
INSERT INTO `words` VALUES (7743, 'Parenting is about giving your child security and love.', 'n. 安全， 保障； 抵押品； 证券', '/sɪ\'kjuərəti | sə\'kjʊrəti/', 'security', 2);
INSERT INTO `words` VALUES (7744, 'seemingly unrelated bits of information', 'adv. 表面上，外表上', '/\'si:miŋli | \'siːmɪŋlɪ | \'simɪŋli/', 'seemingly', 2);
INSERT INTO `words` VALUES (7745, 'segments of the population', 'n. 切片，部分；段，节', '/\'seɡmənt, seɡ\'ment, \'seɡment | \'segm(ə)nt | \'sɛɡmənt/', 'segment', 2);
INSERT INTO `words` VALUES (7746, 'A large detachment of police was used to segregate the two rival camps of protesters.', 'vt. 使隔离， 使分开', '/\'segrɪgeɪt | \'sɛɡrɪɡet/', 'segregate', 2);
INSERT INTO `words` VALUES (7747, 'The Supreme Court unanimously ruled that racial segregation in schools was unconstitutional.', 'n. 隔离', '/,seɡri\'ɡeiʃən | ˌseɡrɪˈɡeɪʃn | \'sɛgrɪ\'geʃən/', 'segregation', 2);
INSERT INTO `words` VALUES (7748, 'The judges have made their final selection.', 'n. 选择；精选的东西', '/si\'lekʃən | sɪ\'lekʃ(ə)n | sɪ\'lɛkʃən/', 'selection', 2);
INSERT INTO `words` VALUES (7749, 'the fall semester', 'n. 学期', '/sɪ\'mestə | səˈmɛstɚ/', 'semester', 2);
INSERT INTO `words` VALUES (7750, 'a Shakespeare seminar', 'n. 研究班， 研讨会', '/\'semɪnɑː | \'sɛmɪnɑr/', 'seminar', 2);
INSERT INTO `words` VALUES (7751, 'Senator Kennedy', 'n. 参议员', '/\'senətə | \'sɛnətɚ/', 'senator', 2);
INSERT INTO `words` VALUES (7752, 'One sign of a heart attack is a tingling sensation in the left arm.', 'n. 感觉，知觉；轰动', '/sen\'seiʃən | sen\'seɪʃ(ə)n | sɛn\'seʃən/', 'sensation', 2);
INSERT INTO `words` VALUES (7753, 'a sensational discovery', 'adj. 轰动的， 耸人听闻的； 使人感动的， 非常好的', '/sen\'seɪʃənl | sɛn\'seʃənl/', 'sensational', 2);
INSERT INTO `words` VALUES (7754, 'Her death seemed such a senseless waste of life.', 'adj. 愚蠢的，无意义的', '/\'senslis | \'senslɪs | \'sɛnsləs/', 'senseless', 2);
INSERT INTO `words` VALUES (7755, 'She seems very sensible.', 'adj. 理智的', '/ˈsensəbl | \'sɛnsəbl/', 'sensible', 2);
INSERT INTO `words` VALUES (7756, 'a very sensitive child', 'adj. 敏感的， 灵敏的； 神经过敏的， 容易生气的； 易受伤害的', '/\'sensətɪv | \'sɛnsətɪv/', 'sensitive', 2);
INSERT INTO `words` VALUES (7757, 'It’s a matter of great political sensitivity.', 'n. 敏感（性）；灵敏性', NULL, 'sensitivity', 2);
INSERT INTO `words` VALUES (7758, 'The latest Japanese vacuum cleaners contain sensors that detect the amount of dust and type of floor.', 'n. 传感器，灵敏元件', '/\'sensə, -sɔ: | \'sensə | \'sɛnsɚ/', 'sensor', 2);
INSERT INTO `words` VALUES (7759, 'the spread of nationalist sentiments', 'n. 感情；情绪', '/\'sentimənt | \'sentɪm(ə)nt | \'sɛntɪmənt/', 'sentiment', 2);
INSERT INTO `words` VALUES (7760, 'Be careful to perform the actions in the correct sequence.', 'n. 序列，顺序', '/\'si:kwəns | \'siːkw(ə)ns | \'sikwəns/', 'sequence', 2);
INSERT INTO `words` VALUES (7761, 'Right, but how do you know there\'s a sergeant there?', 'n. 中士， 警官', '/\'sɑːdʒənt | \'sɑrdʒənt/', 'sergeant', 2);
INSERT INTO `words` VALUES (7762, 'Keep the questions in the same serial order .', 'adj. 连续的， 顺序排列的; n. 连续剧，连载故事', '/\'sɪəriəl | \'sɪrɪəl/', 'serial', 2);
INSERT INTO `words` VALUES (7763, 'the series of events that led to the outbreak of war', 'n. 一系列， 连续； 丛书， 连续剧', '/\'sɪəriːz | \'sɪriz/', 'series', 2);
INSERT INTO `words` VALUES (7764, 'The vicar gave a sermon on charity.', 'n. 布道，讲道；说教', '/\'sə:mən | \'sɜːmən | \'sɝmən/', 'sermon', 2);
INSERT INTO `words` VALUES (7765, '...the serpent in the Garden of Eden.', 'n. 蛇（尤指大蛇或毒蛇）', '/\'sə:pənt | \'sɜːp(ə)nt | \'sɝpənt/', 'serpent', 2);
INSERT INTO `words` VALUES (7766, 'Well, only the server can do that.', 'n. 服务器', '/\'sə:və | \'sɜ:və(r) | \'sɝvɚ/', 'server', 2);
INSERT INTO `words` VALUES (7767, 'Board members met in closed session (= with nobody else present ) .', 'n. 会议，学年', '/\'seʃən | ˈseʃn | \'sɛʃən/', 'session', 2);
INSERT INTO `words` VALUES (7768, 'The set (x, y) has two members.', 'n. 集（合）', '/set | sɛt/', 'set', 2);
