INSERT INTO `words` VALUES (7771, 'the search for a peaceful settlement of the Northern Ireland conflict', 'n. 调停；（尤指拓荒者居住的）定居点，村落', '/\'setlmənt | \'set(ə)lm(ə)nt | \'sɛtlmənt/', 'settlement', 2);
INSERT INTO `words` VALUES (7772, 'The negotiations will be a severe test of his abilities.', 'adj. 艰难的；简朴的', '/si\'viə | sɪ\'vɪə | sɪ\'vɪr/', 'severe', 2);
INSERT INTO `words` VALUES (7773, 'This does not prevent disease altogether, but can reduce its severity.', 'n. 严重性', '/si\'veriti | sɪ\'verətɪ | sə\'vɛrəti/', 'severity', 2);
