INSERT INTO `words` VALUES (8015, 'The government has promised that the army will be called in to help if there is a firemen’s strike.', 'n. 罢工', '/straik | straɪk/', 'strike', 2);
INSERT INTO `words` VALUES (8016, 'a striking contrast between wealth and poverty', 'adj. 显著的，惊人的', '/\'straikiŋ | \'straɪkɪŋ/', 'striking', 2);
INSERT INTO `words` VALUES (8017, 'Her key hung on a string around her neck.', 'n. 线， 细绳； 一串， 一行', '/strɪŋ/', 'string', 2);
INSERT INTO `words` VALUES (8018, 'a strip of sand between the cliffs and the sea', 'n. 狭长的一块', '/strip | strɪp/', 'strip', 2);
INSERT INTO `words` VALUES (8019, 'I was still striving to be successful.', 'v. 努力，奋斗，力求', '/straiv | straɪv/', 'strive', 2);
INSERT INTO `words` VALUES (8020, 'She died following a massive stroke.', 'n. 中风；一举，一次努力；划桨，划水；击，敲；报时的钟声；笔画，一笔；抚摸; vt. 抚摸', '/strəuk | strok/', 'stroke', 2);
INSERT INTO `words` VALUES (8021, 'After dinner, I took a stroll round the city.', 'n. 散步，溜达，闲逛', '/strəul | strəʊl | strol/', 'stroll', 2);
INSERT INTO `words` VALUES (8022, 'Why are you so stubborn?', 'adj. 顽固的；顽强的', '/\'stʌbən | \'stʌbɚn/', 'stubborn', 2);
INSERT INTO `words` VALUES (8023, 'a recording studio in Nashville', 'n. 播音室；工作室', '/\'stju:diəu, \'stu:- | \'stjuːdɪəʊ | \'studɪo/', 'studio', 2);
INSERT INTO `words` VALUES (8024, 'I’ve got some sticky stuff on my shoe.', 'n. 材料，东西', '/stʌf/', 'stuff', 2);
INSERT INTO `words` VALUES (8025, 'It’s getting stuffy in here – do you mind if I open the window?', 'adj. 不透气的，闷热的', '/\'stʌfi | \'stʌfɪ/', 'stuffy', 2);
INSERT INTO `words` VALUES (8026, 'In her hurry, she stumbled and spilled the milk all over the floor.', 'vi. 绊脚， 绊倒； 跌跌撞撞地走； 结结巴巴', '/\'stʌmbl/', 'stumble', 2);
INSERT INTO `words` VALUES (8027, 'an old tree stump', 'vi. 脚步沉重地走; n. 树桩；残根，残余部分; vt. 把…难住，使为难；在…做巡回演说', '/stʌmp/', 'stump', 2);
INSERT INTO `words` VALUES (8028, 'Redfern stunned the crowd with a last-minute goal.', 'vt. 使震惊， 使目瞪口呆； 把…打昏， 使昏迷', '/stʌn/', 'stun', 2);
INSERT INTO `words` VALUES (8029, 'That chair doesn’t look very sturdy.', 'adj. 牢固的；坚定的', '/\'stə:di | \'stɜːdɪ | \'stɝdi/', 'sturdy', 2);
INSERT INTO `words` VALUES (8030, 'a subconscious fear of failure', 'adj. 下意识的，潜意识的', '/,sʌb\'kɔnʃəs | sʌb\'kɒnʃəs | ,sʌb\'kɑnʃəs/', 'subconscious', 2);
INSERT INTO `words` VALUES (8031, 'the drug subculture of the inner city', 'n. 亚文化', '/\'sʌbkʌltʃə | \'sʌbkʌltʃɚ/', 'subculture', 2);
INSERT INTO `words` VALUES (8032, 'Over time, developers subdivided the land.', 'v. 把…再分', '/,sʌbdi\'vaid, \'sʌbdivaid | sʌbdɪ\'vaɪd | \'sʌbdɪvaɪd/', 'subdivide', 2);
INSERT INTO `words` VALUES (8033, 'Senior government officials admit they have not been able to subdue the rebels.', 'v. 使屈服，征服', '/səb\'dju: | səb\'djuː | səb\'du/', 'subdue', 2);
INSERT INTO `words` VALUES (8034, 'The Roman Empire subjected most of Europe to its rule.', 'v. 使隶属', '/\'sʌbdʒikt, -dʒe-, səb\'dʒekt | ˈsʌbdʒɪkt | ˈsʌbdʒekt/', 'subject', 2);
INSERT INTO `words` VALUES (8035, 'As a critic, he is far too subjective.', 'adj. 主观的， 个人的', '/səb\'dʒektɪv | səb\'dʒɛktɪv/', 'subjective', 2);
INSERT INTO `words` VALUES (8036, 'submarine plant life', 'adj. 水底的， 海底的; n. 潜水艇', '/ˌsʌbmə\'riːn | ,sʌbmə\'rin/', 'submarine', 2);
INSERT INTO `words` VALUES (8037, 'The tunnel entrance was submerged by rising sea water.', 'v. 淹没', '/səb\'mə:dʒ | səb\'mɜ:dʒ | səb\'mɝdʒ/', 'submerge', 2);
INSERT INTO `words` VALUES (8038, 'They submitted their reports to the chancellor yesterday.', 'v. 提交', '/səb\'mit | səb\'mɪt/', 'submit', 2);
INSERT INTO `words` VALUES (8039, 'a subordinate officer', 'adj. 次要的，从属的', '/sə\'bɔ:dinət, -neit, sə\'bɔ:dineit | səˈbɔːdɪnət | səˈbɔːdɪnɪt (for n. &adj.) ; səˈbɔːdɪˌnet (for v.)/', 'subordinate', 2);
INSERT INTO `words` VALUES (8040, 'My main reason for subscribing to New Scientist is to keep abreast of advances in science.', 'v. 订购；认购；预订', '/səb\'skraib | səb\'skraɪb/', 'subscribe', 2);
INSERT INTO `words` VALUES (8041, 'The subscript operator must be defined as a class member function.', 'adj. 写在下方的; n. 下标', '/\'sʌbskript | \'sʌbskrɪpt/', 'subscript', 2);
INSERT INTO `words` VALUES (8042, 'You may cancel your subscription at any time.', 'n. 订阅（费）；用户费（的缴纳）', '/səb\'skripʃən | səb\'skrɪpʃ(ə)n | səb\'skrɪpʃən/', 'subscription', 2);
INSERT INTO `words` VALUES (8043, 'These skills were passed on to subsequent generations.', 'adj. 尔后的', '/\'sʌbsikwənt | \'sʌbsɪkw(ə)nt | \'sʌbsɪkwənt/', 'subsequent', 2);
INSERT INTO `words` VALUES (8044, 'The book was subsequently translated into 15 languages.', 'adv. 随后', '/\'sʌbsikwəntli | \'sʌbsɪkwəntlɪ | \'sʌbsɪkwəntli/', 'subsequently', 2);
INSERT INTO `words` VALUES (8045, 'The marketing department has always played a subsidiary role to the sales department.', 'adj. 辅助的，补充的', '/səb\'sidiəri | səb\'sɪdɪərɪ | səb\'sɪdɪɛri/', 'subsidiary', 2);
INSERT INTO `words` VALUES (8046, 'European farmers are planning a massive demonstration against farm subsidy cuts.', 'n. 补助', '/\'sʌbsidi | \'sʌbsədɪ | \'sʌbsədi/', 'subsidy', 2);
INSERT INTO `words` VALUES (8047, 'The leaves were covered with a strange sticky substance.', 'n. 物质', '/\'sʌbstəns/', 'substance', 2);
INSERT INTO `words` VALUES (8048, 'a substantial piece of furniture', 'adj. 大而坚固的', '/səb\'stænʃəl | səb\'stænʃ(ə)l | səbˈstænʃəl/', 'substantial', 2);
INSERT INTO `words` VALUES (8049, 'Germany brought on a substitute at half time.', 'n. 代替人，代用品; vt. 用…代替', '/\'sʌbstɪtjuːt | \'sʌbstɪtut/', 'substitute', 2);
INSERT INTO `words` VALUES (8050, 'The pictures are similar, but there are subtle differences between them.', 'adj. 微妙的', '/\'sʌtl/', 'subtle', 2);
INSERT INTO `words` VALUES (8051, 'Mandy subtracted the date of birth from the date of death.', 'vt. 减， 减去； 去掉', '/səb\'trækt/', 'subtract', 2);
INSERT INTO `words` VALUES (8052, 'a London suburb', 'n. 郊区， 郊外， 近郊', '/\'sʌbɜːb | \'sʌbɝb/', 'suburb', 2);
INSERT INTO `words` VALUES (8053, 'a quiet, suburban street', 'adj. 郊区的', '/sə\'bə:bən | səˈbɜ:bən | sə\'bɝbən/', 'suburban', 2);
INSERT INTO `words` VALUES (8054, 'If the prince dies, the succession passes to his son.', 'n. 继承（权）', '/sək\'seʃən | sək\'seʃ(ə)n | sək\'sɛʃən/', 'succession', 2);
INSERT INTO `words` VALUES (8055, 'The team has had five successive victories.', 'adj. 连续的， 接连的', '/sək\'sesɪv | sək\'sɛsɪv/', 'successive', 2);
INSERT INTO `words` VALUES (8056, NULL, 'adv. 接连着地，继续地', '/sək\'sesivli | sək\'sesɪvlɪ | sək\'sɛsɪvli/', 'successively', 2);
INSERT INTO `words` VALUES (8057, 'His successor died after only 15 months in office.', 'n. 继承人，继任者', '/sək\'sesə | sək\'sɛsɚ/', 'successor', 2);
INSERT INTO `words` VALUES (8058, 'If the builders don’t fulfil their side of the contract, we’ll sue.', 'v. 控告， 起诉； 要求， 请求', '/suː | su/', 'sue', 2);
INSERT INTO `words` VALUES (8059, 'A light lunch will suffice.', 'v. 足够', '/sə\'fais | sə\'faɪs/', 'suffice', 2);
INSERT INTO `words` VALUES (8060, 'We can only prosecute if there is sufficient evidence.', 'adj. 足够的， 充分的', '/sə\'fɪʃnt | səˈfɪʃənt/', 'sufficient', 2);
INSERT INTO `words` VALUES (8061, 'More people commit suicide at Christmas than at any other time.', 'n. 自杀', '/\'sjuisaid | ˈsu:ɪsaɪd | \'suɪsaɪd/', 'suicide', 2);
INSERT INTO `words` VALUES (8062, 'Whatever your reason for borrowing, we have the loan that suits your needs.', 'v. 使配合，彼此协调', '/sju:t; su:t | sut/', 'suit', 2);
INSERT INTO `words` VALUES (8063, 'It did not take Andrew long to pack a suitcase.', 'n. 手提箱，衣箱', '/\'sju:tkeis | \'suːtkeɪs | \'sutkes/', 'suitcase', 2);
INSERT INTO `words` VALUES (8064, 'a honeymoon suite', 'n. 套间； 一套家具； 套， 组， 系列', '/swiːt | sut; swit/', 'suite', 2);
INSERT INTO `words` VALUES (8065, 'She knelt down, hands on the thighs, breathe in the smell of sulfur.', 'n. 硫', '/\'sʌlfə | \'sʌlfɚ/', 'sulfur', 2);
INSERT INTO `words` VALUES (8066, 'Bill sat in sullen silence and refused to eat his lunch.', 'adj. 绷着脸不高兴的', '/\'sʌlən/', 'sullen', 2);
INSERT INTO `words` VALUES (8067, 'a summary financial statement', 'adj. 概括的；速决的', '/\'sʌm(ə)rɪ | \'sʌməri/', 'summary', 2);
INSERT INTO `words` VALUES (8068, 'His election as President represented the summit of his career.', 'n. 顶点，最高点；极度', '/\'sʌmɪt/', 'summit', 2);
INSERT INTO `words` VALUES (8069, 'Robert summoned the waiter for the bill.', 'v. 召唤；鼓起（勇气）', '/\'sʌmən/', 'summon', 2);
INSERT INTO `words` VALUES (8070, 'The food was superb.', 'adj. 壮丽的；超等的', '/sju\'pə:b, sə- | suː\'pɜːb; sjuː- | /suːˈpɜːrb//', 'superb', 2);
INSERT INTO `words` VALUES (8071, 'Beneath his refined manners and superficial elegance lay something treacherous.', 'adj. 表面的', '/ˌsu:pəˈfɪʃl | ,supɚ\'fɪʃl/', 'superficial', 2);
INSERT INTO `words` VALUES (8072, 'a young park superintendent', 'n. 主管人， 监管人， 负责人； 警长', '/ˌsuːpərɪn\'tendənt | ,supərɪn\'tɛndənt/', 'superintendent', 2);
INSERT INTO `words` VALUES (8073, 'She had that superior tone of voice.', 'adj. 上级的，较高的；优越的；有优越感的，高傲的; n. 上级， 长官', '/suː\'pɪəriə | sʊˈpɪrɪɚ/', 'superior', 2);
INSERT INTO `words` VALUES (8074, 'the intellectual superiority of humans over other animals', 'n. 优越（性），优势', '/sju:,piəri\'ɔriti, sə- | suː,pɪərɪ\'ɒrɪtɪ; sjuː- | su,pɪrɪ\'ɔrəti/', 'superiority', 2);
INSERT INTO `words` VALUES (8075, 'supersonic aircraft', 'adj. 超声的，超声速的', '/,sju:pə\'sɔnik | suːpə\'sɒnɪk; sjuː- | ,supɚ\'sɑnɪk/', 'supersonic', 2);
INSERT INTO `words` VALUES (8076, 'the old superstition that walking under a ladder is unlucky', 'n. 迷信，迷信行为', '/,sju:pə\'stiʃən | ,suːpə\'stɪʃ(ə)n; ,sjuː- | ,supɚ\'stɪʃən/', 'superstition', 2);
INSERT INTO `words` VALUES (8077, 'Griffiths closely supervised the research.', 'v. 监督，监视', '/\'sju:pəvaiz | \'suːpəvaɪz; \'sjuː- | \'sʊpɚ\'vaɪz/', 'supervise', 2);
INSERT INTO `words` VALUES (8078, '...a full-time job as a supervisor at a factory.', 'n. 督导', '/\'sju:pəvaizə | ˈsu:pəvaɪzə(r) | \'supɚvaɪzɚ/', 'supervisor', 2);
INSERT INTO `words` VALUES (8079, '...He used a strangely potent ingredient in a food supplement...', 'n. 补角', '/英[\'sʌplɪm(ə)nt] 美[\'sʌplɪmənt] | \'sʌplɪm(ə)nt | \'sʌplɪmənt/', 'supplement', 2);
INSERT INTO `words` VALUES (8080, 'supplementary information', 'adj. 增补的， 补充的', '/ˌsʌplɪ\'mentri | ,sʌplɪ\'mɛntri/', 'supplementary', 2);
INSERT INTO `words` VALUES (8081, 'The middle part of the bridge is supported by two huge towers.', 'v. 经受，承受', '/sə\'pɔ:t | sə\'pɔːt | sə\'pɔrt/', 'support', 2);
INSERT INTO `words` VALUES (8082, 'The uprising was ruthlessly suppressed.', 'v. 镇压，压制', '/sə\'pres | səˈpres | sə\'prɛs/', 'suppress', 2);
INSERT INTO `words` VALUES (8083, 'the Supreme Allied Commander in Europe', 'adj. 最高的， 最大的； 极度的， 最重要的', '/suː\'priːm | suˈprim/', 'supreme', 2);
INSERT INTO `words` VALUES (8084, 'The photographers and cameramen surged forward.', 'vi. 蜂拥而出；洋溢，奔放；汹涌，奔腾; n. 洋溢， 奔放； 急剧上升， 猛增； 浪涛般汹涌奔腾', '/sɜːdʒ | sɝdʒ/', 'surge', 2);
INSERT INTO `words` VALUES (8085, '...a heart surgeon.', 'n. 外科医生', '/\'sɜːdʒən | \'sɝdʒən/', 'surgeon', 2);
INSERT INTO `words` VALUES (8086, 'Dr. Hanson is in surgery.', 'n. 外科， 外科手术； 手术室', '/\'sɜːdʒəri | \'sɝdʒəri/', 'surgery', 2);
INSERT INTO `words` VALUES (8087, 'surgical techniques', 'adj. 手术的', '/\'sə:dʒikəl | ˈsɜ:dʒɪkl | \'sɝdʒɪkl/', 'surgical', 2);
INSERT INTO `words` VALUES (8088, 'He had surpassed all our expectations .', 'v. 超过', '/sə\'pɑ:s, -\'pæs | sə\'pɑːs | sə\'pæs/', 'surpass', 2);
INSERT INTO `words` VALUES (8089, 'Any surplus can be trimmed away.', 'n. 过剩，剩余（物资）', '/\'sə:plʌs, -pləs | \'sɜːpləs | \'sɝpləs/', 'surplus', 2);
INSERT INTO `words` VALUES (8090, 'Of the 100 companies surveyed, 10% had a turnover of £50 m to £99 m.', 'v. 俯瞰， 眺望； 全面审视， 调查； 测量， 勘定; n. [sə\'veɪ]', '/\'sɜːveɪ | ˈsɝˌve; (for v.) sɝˈve/', 'survey', 2);
INSERT INTO `words` VALUES (8091, 'The doctors gave him a one in ten chance of survival .', 'n. 幸存；残存；幸存者', '/sə\'vaivəl | sə\'vaɪv(ə)l | sɚ\'vaɪvl/', 'survival', 2);
INSERT INTO `words` VALUES (8092, 'Only 12 of the 140 passengers survived.', 'vi. 活下来，继续存在；幸免于; vt. 从中挺过来； 从…逃出； 比…活得长', '/sə\'vaɪv | sɚ\'vaɪv/', 'survive', 2);
INSERT INTO `words` VALUES (8093, 'A lot of TV advertising is aimed at susceptible young children.', 'adj. 易受影响的； 过敏的； 能经受的， 容许的', '/sə\'septəbl | sə\'sɛptəbl/', 'susceptible', 2);
INSERT INTO `words` VALUES (8094, 'She strongly suspected he was lying to her.', 'v. 怀疑; n. 嫌疑犯', '/sə\'spekt, \'sʌspekt | sə\'spekt | sʌspɛkt; (for v.) səˈspɛkt/', 'suspect', 2);
INSERT INTO `words` VALUES (8095, 'Sales of the drug will be suspended until more tests are completed.', 'v. 暂停', '/sə\'spend | səˈspend | sə\'spɛnd/', 'suspend', 2);
INSERT INTO `words` VALUES (8096, 'He received a six-month suspension for unprofessional behaviour.', 'n. 暂停， 中止； 暂令停止参加， 暂时剥夺； 悬架， 悬置机构； 悬浮液； 悬， 挂， 吊', '/sə\'spenʃn | sə\'spɛnʃən/', 'suspension', 2);
INSERT INTO `words` VALUES (8097, 'I can’t say for definite who did it, but I certainly have my suspicions .', 'n. 怀疑， 疑心， 猜疑； 一点儿， 少量', '/sə\'spɪʃn | sə\'spɪʃən/', 'suspicion', 2);
INSERT INTO `words` VALUES (8098, 'His reluctance to answer my questions made me suspicious .', 'adj. 怀疑的', '/sə\'spiʃəs | səˈspɪʃəs | sə\'spɪʃəs/', 'suspicious', 2);
INSERT INTO `words` VALUES (8099, 'She found it difficult to sustain the children’s interest.', 'vt. 保持， 使持续下去； 供养， 维持； 支持， 支撑； 经受， 遭受', '/sə\'steɪn | sə\'sten/', 'sustain', 2);
INSERT INTO `words` VALUES (8100, 'I spent one whole night by a swamp behind the road listening to frogs.', 'n. 沼泽; vt. 淹没， 浸没； 难倒， 压倒', '/swɒmp | swɑmp/', 'swamp', 2);
INSERT INTO `words` VALUES (8101, 'Do you want to swap umbrellas?', 'n&v. 交换', '/swɒp | swɑp/', 'swap', 2);
INSERT INTO `words` VALUES (8102, 'Don’t allow yourself to be swayed by his promises.', 'v. 影响', '/swei | sweɪ | swe/', 'sway', 2);
INSERT INTO `words` VALUES (8103, 'Bert swept the path in front of the house.', 'v. 扫除，清除', '/swi:p | swip/', 'sweep', 2);
INSERT INTO `words` VALUES (8104, 'Sweeten the mixture with a little honey.', 'v. 使变甜，变甜', '/\'swi:tən | \'swiːt(ə)n | \'switn/', 'sweeten', 2);
INSERT INTO `words` VALUES (8105, 'the sweetness of the wild rose', 'n. 甜蜜，芬芳；愉悦，美好', '/\'swi:tnis | \'switnəs/', 'sweetness', 2);
INSERT INTO `words` VALUES (8106, 'Her ankle was already starting to swell.', 'v. 使膨胀；隆起', '/swel | swɛl/', 'swell', 2);
INSERT INTO `words` VALUES (8107, 'The terrorists will switch tactics .', 'v. 转换', '/switʃ | swɪtʃ/', 'switch', 2);
INSERT INTO `words` VALUES (8108, 'The symbol on the packet is a guarantee that the food has been produced organically.', 'n. 象征； 符号， 标志', '/\'sɪmbl/', 'symbol', 2);
INSERT INTO `words` VALUES (8109, 'Each element of the ceremony has a symbolic meaning .', 'adj. 符号的； 象征性的', '/sɪm\'bɒlɪk | sɪm\'bɑlɪk/', 'symbolic', 2);
INSERT INTO `words` VALUES (8110, 'The pattern was perfectly symmetrical.', 'adj. 对称的，匀称的', '/si\'metrikəl | sɪ\'metrɪk(ə)l | sɪ\'mɛtrɪkl/', 'symmetrical', 2);
INSERT INTO `words` VALUES (8111, 'the symmetry of the design', 'n. 对称（性），匀称', '/\'simitri | \'sɪmɪtrɪ | \'sɪmətri/', 'symmetry', 2);
INSERT INTO `words` VALUES (8112, 'a sympathetic friend', 'adj. 同情的', '/,simpə\'θetik | ˌsɪmpəˈθetɪk | ,sɪmpə\'θɛtɪk/', 'sympathetic', 2);
INSERT INTO `words` VALUES (8113, 'Our sympathies are with the families of the victims.', 'n. 同情； 一致； 支持， 赞同', '/\'sɪmpəθi/', 'sympathy', 2);
INSERT INTO `words` VALUES (8114, 'Bruckner’s Fifth Symphony', 'n. 交响乐；交响乐团', '/\'simfəni | \'sɪmf(ə)nɪ | \'sɪmfəni/', 'symphony', 2);
INSERT INTO `words` VALUES (8115, 'a symposium on women’s health', 'n. 座谈会', '/sim\'pəuziəm | sɪm\'pəʊzɪəm | sɪm\'pozɪəm/', 'symposium', 2);
INSERT INTO `words` VALUES (8116, 'One of the most common symptoms of schizophrenia is hearing imaginary voices.', 'n. 症状', '/\'simptəm | \'sɪmptəm/', 'symptom', 2);
INSERT INTO `words` VALUES (8117, 'people who suffer from irritable bowel syndrome', 'n. 综合病症， 综合症状； 一系列表现', '/\'sɪndrəum | \'sɪndrəm/', 'syndrome', 2);
INSERT INTO `words` VALUES (8118, 'a synthesis of Eastern and Western philosophical ideas', 'n. 综合，综合物；（化学或生物学物质的）合成；（用电子方式对声音、语音或音乐的）合成', '/\'sinθisis | \'sɪnθɪsɪs | \'sɪnθəsɪs/', 'synthesis', 2);
INSERT INTO `words` VALUES (8119, 'a systematic approach to solving the problem', 'adj. 成体系的', '/sɪstə\'mætɪk | \'sɪstə\'mætɪk/', 'systematic', 2);
INSERT INTO `words` VALUES (8120, 'The search was carried out systematically.', 'adv. 系统地，有规则地', '/,sistə\'mætikəli | ,sɪstə\'mætɪklɪ | ,sɪstə\'mætɪkl/', 'systematically', 2);
INSERT INTO `words` VALUES (8121, 'Results for the test programme haven\'t been tabulated.', 'v. 把…制成表', '/\'tæbjuleit, \'tæbju-lit, -leit | \'tæbjʊleɪt | \'tæbjulet/', 'tabulate', 2);
INSERT INTO `words` VALUES (8122, '...a box of carpet tacks.', 'n. 平头钉; v. 钉住', '/tæk/', 'tack', 2);
INSERT INTO `words` VALUES (8123, 'There is more than one way to tackle the problem.', 'v. 解决，处理', '/\'tækl/', 'tackle', 2);
