INSERT INTO `words` VALUES (8562, 'Only spontaneous love flowing with sincere generosity and self-abnegation can fertilize the soul of others.', 'n. 放弃', '/,æbni\'ɡeiʃən | æbnɪ\'geɪʃ(ə)n | ,æbnɪ\'ɡeʃən/', 'abnegation', 6);
