INSERT INTO `words` VALUES (8569, '...Aboriginal art.', 'adj. 土著的, 原来的', '/,æbə\'ridʒənəl | æbə\'rɪdʒɪn(ə)l | ,æbə\'rɪdʒənl/', 'aboriginal', 6);
