INSERT INTO `words` VALUES (8583, 'an abrupt change of plan', 'adj. 突然的， 意外的； 唐突的', '/ə\'brʌpt/', 'abrupt', 6);
INSERT INTO `words` VALUES (8584, 'He was ordered to appear the following day, but absconded.', 'v. 潜逃, 避债', '/əb\'skɔnd | əb\'skɒnd; æb- | əb\'skɑnd/', 'abscond', 6);
INSERT INTO `words` VALUES (8585, 'He has been absent from his desk for two weeks.', 'v. 缺席，不参加away); adj. 缺席的', '/æb\'s3nt | ˈæbsnt;(for v.)əbˈsɛnt/', 'absent', 6);
