INSERT INTO `words` VALUES (8587, 'Pope Leo gave him absolution.', 'n. 免罪, 赦免', '/,æbsə\'lju:ʃən | æbsə\'luːʃ(ə)n | ,æbsə\'luʃən/', 'absolution', 6);
INSERT INTO `words` VALUES (8588, 'A police investigation yesterday absolved the police of all blame in the incident.', 'v. 赦免， 免除', '/əb\'zɑːlv | əb\'zɑlv/', 'absolve', 6);
INSERT INTO `words` VALUES (8589, 'Three countries abstained in the vote.', 'v. 禁绝, 放弃', '/əb\'stein | əb\'steɪn | əb\'sten/', 'abstain', 6);
INSERT INTO `words` VALUES (8590, 'The Norwegian adolescents who said they regularly use alcohol and cigarettes were no more likely to report acne than those who were abstemious.', 'adj. 有节制的, 节约的', '/æb\'sti:mjəs | əb\'stiːmɪəs | əb\'stimɪəs/', 'abstemious', 6);
INSERT INTO `words` VALUES (8591, 'The draft law was passed by 134 votes to 19, with 5 abstentions.', 'n. 戒除； 弃权', '/əb\'stenʃn | əb\'stɛnʃən/', 'abstention', 6);
INSERT INTO `words` VALUES (8592, 'They are abstemious and abstain from most of the modern things that other English people, who are now rarely abstentious, enjoy.', 'adj. 有节制的', '/æb\'stenʃəs/', 'abstentious', 6);
INSERT INTO `words` VALUES (8593, NULL, 'adj. 饮食有度的， 有节制的， 禁欲的', '/\'æbstinənt | \'æbstɪnənt/', 'abstinent', 6);
INSERT INTO `words` VALUES (8594, 'Talking about crime in the abstract just isn’t enough.', 'n. 摘要, 概要, 抽象', '/\'æbstrækt/', 'abstract', 6);
INSERT INTO `words` VALUES (8595, 'The same abstracted look was still on his face.', 'adj. 心不在焉的, 出神的', '/æb\'stræktid | əb\'stræktɪd | æb\'stræktɪd/', 'abstracted', 6);
INSERT INTO `words` VALUES (8596, 'Maths is a mix of abstruse theory and detailed calculations.', 'adj. 奥妙的, 深奥的', '/æb\'stru:s | əb\'struːs; æb- | əbˈstruːs; æb-/', 'abstruse', 6);
INSERT INTO `words` VALUES (8597, 'It seems an absurd idea.', 'adj. 荒谬的, 可笑的', '/əb\'sə:d | əb\'sɜːd | əbˈsɚd, -ˈzɚd/', 'absurd', 6);
INSERT INTO `words` VALUES (8598, 'What are we when confronted with the interior vortex which swallows us into absurdity?', 'n. 荒谬, 谬论', '/əb\'sə:dəti | əb\'sɜːdɪtɪ | əb\'sɝdəti/', 'absurdity', 6);
INSERT INTO `words` VALUES (8599, 'This area of Mexico has an abundance of safe beaches and a pleasing climate.', 'n. 丰富, 充裕, 丰富充裕', '/ə\'bʌndəns | ə\'bʌnd(ə)ns/', 'abundance', 6);
INSERT INTO `words` VALUES (8600, 'several cases of child abuse', 'n. 滥用, 虐待, 辱骂, 陋习, 弊端', '/ə\'bju:z, ə\'bju:s | ə\'bjuːz | ə\'bjus/', 'abuse', 6);
INSERT INTO `words` VALUES (8601, 'Smith denies using abusive language to the referee.', 'adj. 谩骂的， 毁谤的； 虐待的', '/ə\'bjuːsɪv | ə\'bjʊsɪv/', 'abusive', 6);
INSERT INTO `words` VALUES (8602, 'The castles abut a natural forest.', 'v. 邻接, 毗邻', '/ə\'bʌt/', 'abut', 6);
INSERT INTO `words` VALUES (8603, 'The reunion was an abysmal failure.', 'adj. 深不可测的, 无底的', '/ə\'bizməl | ə\'bɪzm(ə)l | ə\'bɪzməl/', 'abysmal', 6);
INSERT INTO `words` VALUES (8604, 'The torrent, swollen by the melting snow, plunges into a tremendous abyss.', 'n. 深渊', '/ə\'bis | ə\'bɪs/', 'abyss', 6);
INSERT INTO `words` VALUES (8605, 'He possessed no academic qualifications.', 'adj. 学院的， 学术的； 理论的', '/ˌækə\'demɪk | ,ækə\'dɛmɪk/', 'academic', 6);
INSERT INTO `words` VALUES (8606, 'In addition, the enzyme activity of high yield female plant, low yield female plant and acarpous female plant were compared.', 'adj. [植]不结果的,无果实的', '/ei\'kɑ:pəs | eɪ\'kɑːpəs | e\'kɑrpəs/', 'acarpous', 6);
INSERT INTO `words` VALUES (8607, 'Other countries could accede to the deal if they wanted.', 'v. 同意, 加入, 同意', '/æk\'si:d | ək\'siːd | ək\'sid/', 'accede', 6);
INSERT INTO `words` VALUES (8608, 'measures to accelerate the rate of economic growth', 'v. 加速, 促进', '/ək\'seləreit | ək\'seləreɪt | əkˈsɛləˌret/', 'accelerate', 6);
INSERT INTO `words` VALUES (8609, 'The photograph seemed to accentuate his large nose.', 'v. 重读, 强调, 着重强调', '/æk\'sentjueit | ək\'sentʃʊeɪt; -tjʊ- | ək\'sɛntʃuet/', 'accentuate', 6);
INSERT INTO `words` VALUES (8610, 'Access is by means of a small door on the right.', 'n. 通路, 访问, 入门', '/\'ækses, \'æksəs, æk\'ses | \'ækses | \'æksɛs/', 'access', 6);
INSERT INTO `words` VALUES (8611, 'The island is only accessible by boat.', 'adj. 易接近的, 可到达的, 易受影响的, 可理解的', '/ək\'sesəbl | ək\'sesɪb(ə)l | ək\'sɛsəbl/', 'accessible', 6);
