INSERT INTO `words` VALUES (8614, NULL, 'adj. 鹰的, 鹰似的, 贪婪凶猛的', '/æk\'sipitrəl/', 'accipitral', 6);
INSERT INTO `words` VALUES (8615, 'His work was acclaimed by art critics.', 'v. 欢呼， 称赞', '/ə\'kleɪm | ə\'klem/', 'acclaim', 6);
INSERT INTO `words` VALUES (8616, 'The news was greeted with considerable popular acclamation.', 'n. 欢呼, 喝彩, (以欢呼、鼓掌等表示的)拥护, 赞成', '/,æklə\'meiʃən | ,æklə\'meɪʃ(ə)n | ,æklə\'meʃən/', 'acclamation', 6);
