INSERT INTO `words` VALUES (8618, 'As soon as we descend down the slope of sadness, we accelerate over the ever-feel-good acclivity of happiness.', 'n. [地]向上的斜坡', '/ə\'klivəti | ə\'klɪvɪtɪ | ə\'klɪvəti/', 'acclivity', 6);
INSERT INTO `words` VALUES (8619, NULL, 'n. 赞美, 骑士爵位的授予, 连谱号', '/\'ækəuleid, ækəu\'leid | \'ækəleɪd; ,ækə\'leɪd | \'ækəled/', 'accolade', 6);
INSERT INTO `words` VALUES (8620, 'The island was used to accommodate child refugees.', 'v. 与…一致； 提供住宿； 顺应， 使适应', '/ə\'kɑːmədeɪt | ə\'kɑmədet/', 'accommodate', 6);
INSERT INTO `words` VALUES (8621, 'an accommodating child', 'adj. 乐于助人的, 随和的, 善于适应新环境的', '/ə\'kɔmədeitiŋ | ə\'kɒmədeɪtɪŋ | ə\'kɑmədetɪŋ/', 'accommodating', 6);
INSERT INTO `words` VALUES (8622, 'Children under 14 must be accompanied by an adult.', 'v. 伴随， 陪伴', '/ə\'kʌmpəni/', 'accompany', 6);
INSERT INTO `words` VALUES (8623, 'Witnesses said the gunman immediately ran to a motorcycle being ridden by an accomplice.', 'n. 同谋者, 帮凶', '/ə\'kʌmplis | ə\'kʌmplɪs; ə\'kɒm- | ə\'kɑmplɪs/', 'accomplice', 6);
INSERT INTO `words` VALUES (8624, 'We have accomplished all we set out to do.', 'v. 完成， 做成功', '/ə\'kɑːmplɪʃ | ə\'kɑmplɪʃ/', 'accomplish', 6);
INSERT INTO `words` VALUES (8625, 'However, we also must look at what was not accomplished.', 'adj. 完成了的； 有技巧的', '/ə\'kɑːmplɪʃt | ə\'kɑmplɪʃt/', 'accomplished', 6);
INSERT INTO `words` VALUES (8626, 'There was a silence as the women turned with one accord to stare at Doreen.', 'n. 一致, 符合, 调和, 协定', '/ə\'kɔ:d | ə\'kɔːd | ə\'kɔrd/', 'accord', 6);
INSERT INTO `words` VALUES (8627, 'But my fancy accordion might as well have been a cardboard box that afternoon.', 'n. 手风琴', '/ə\'kɔ:djən | ə\'kɔːdɪən | ə\'kɔrdɪən/', 'accordion', 6);
INSERT INTO `words` VALUES (8628, 'He was accosted by four youths and forced to give them all his money.', 'v. 搭话', '/ə\'kɔːst | ə\'kɔst/', 'accost', 6);
