INSERT INTO `words` VALUES (8635, 'It is unjust that a privileged few should continue to accumulate wealth.', 'v. 积聚, 堆积', '/ə\'kju:mjuleit | ə\'kjuːmjʊleɪt | ə\'kjumjəlet/', 'accumulate', 6);
INSERT INTO `words` VALUES (8636, 'He passes the ball with unerring accuracy.', 'n. 精确， 准确', '/\'ækjərəsi/', 'accuracy', 6);
INSERT INTO `words` VALUES (8637, 'The brochure tries to give a fair and accurate description of each hotel.', 'adj. 精确的， 准确的', '/\'ækjərət/', 'accurate', 6);
