INSERT INTO `words` VALUES (8642, 'The town, the old grey twilight towers enveloped in dark yellow amber. In the evening, the black acerbity to bury the newborn, expand the trip.', 'n. 涩, 酸, 刻薄', '/ə\'sə:bəti | ə\'sɜːbətɪ | ə\'sɝbəti/', 'acerbity', 6);
INSERT INTO `words` VALUES (8643, 'Some fruit juices taste a bit acidic.', 'adj. 酸的， 酸性的', '/ə\'sɪdɪk/', 'acidic', 6);
