INSERT INTO `words` VALUES (8645, 'The family acknowledge the need for change.', 'v. 承认； 致谢', '/ək\'nɑːlɪdʒ | ək\'nɑlɪdʒ/', 'acknowledge', 6);
INSERT INTO `words` VALUES (8646, 'the acme of perfection', 'n. 顶点, 极致', '/\'ækmi | \'ækmɪ/', 'acme', 6);
INSERT INTO `words` VALUES (8647, 'She wore no makeup, and her face was dotted with acne.', 'n. 痤疮, 粉刺', '/\'ækni | \'æknɪ/', 'acne', 6);
INSERT INTO `words` VALUES (8648, '\"He wouldn\'t have come near us because of his closeness to the Gaddafi regime, because he was an acolyte, \" Mr Shamis says.', 'n. 侍僧, 助手', '/\'ækəulait | \'ækəlaɪt/', 'acolyte', 6);
INSERT INTO `words` VALUES (8649, 'First an acorn; then an oak tree forest.', 'n. [植]橡树果, 橡子', '/\'eikɔ:n | \'eɪkɔːn | \'ekɔrn/', 'acorn', 6);
INSERT INTO `words` VALUES (8650, 'It was in this context, led with the Plantronics acoustic songs Seoul cooperation.', 'adj. 有关声音的, 声学的, 音响学的', '/ə\'ku:stik | ə\'kuːstɪk | ə\'kʊstɪk/', 'acoustic', 6);
INSERT INTO `words` VALUES (8651, 'The hall has excellent acoustics.', 'n. 声学', '/ə\'ku:stiks | ə\'kuːstɪks | ə\'kustɪks/', 'acoustics', 6);
INSERT INTO `words` VALUES (8652, 'She was a casual acquaintance of my family in Vienna.', 'n. 相识, 熟人', '/ə\'kweintəns | ə\'kweɪnt(ə)ns | ə\'kwentəns/', 'acquaintance', 6);
INSERT INTO `words` VALUES (8653, 'Steve seemed to acquiesce in the decision.', 'v. 默许, 勉强同意', '/,ækwi\'es | ,ækwɪ\'es/', 'acquiesce', 6);
