INSERT INTO `words` VALUES (8656, NULL, 'adj. 已获得的, 已成习惯的, 后天通过自己的努力得到的', '/ə\'kwaiəd | ə\'kwaɪəd | ə\'kwaɪrd/', 'acquired', 6);
