INSERT INTO `words` VALUES (8659, '...the acquittal of six police officers charged with beating up a suspect.', 'n. 宣判无罪', '/ə\'kwitəl | ə\'kwɪtəl | ə\'kwɪtl/', 'acquittal', 6);
INSERT INTO `words` VALUES (8660, 'a cloud of acrid smoke', 'adj. 辛辣的， 刻薄的', '/\'ækrɪd/', 'acrid', 6);
