INSERT INTO `words` VALUES (8662, 'Now, with an agreement put on the table, talks have broken down in acrimony .', 'n. 言谈举止上的刻毒, 讽刺, 毒辣', '/\'ækriməni | \'ækrɪmənɪ | ækrɪmoni/', 'acrimony', 6);
INSERT INTO `words` VALUES (8663, 'The acrobat turned a somersault.', 'n. (走钢丝的)杂技演员, 随机应变者, 翻云覆雨者', '/\'ækrəbæt/', 'acrobat', 6);
INSERT INTO `words` VALUES (8664, NULL, 'n. 只取首字母的缩写词', '/\'ækrəunim | \'ækrənɪm/', 'acronym', 6);
INSERT INTO `words` VALUES (8665, 'Many people suffer from very serious acrophobia.', 'n. [医]恐高症', '/,ækrəu\'fəubjə | ,ækrə\'fəʊbɪə | ,ækrə\'fobɪə/', 'acrophobia', 6);
INSERT INTO `words` VALUES (8666, 'Look at what do Ifind?. actinia.', 'n. [动]海葵', '/æk\'tiniə | æk\'tɪnɪə/', 'actinia', 6);
INSERT INTO `words` VALUES (8667, 'Cooking fumes may activate the alarm.', 'v. 刺激, 使活动', '/\'æktiveit | \'æktɪveɪt | \'æktə\'vet/', 'activate', 6);
INSERT INTO `words` VALUES (8668, 'The flow of current actuates the signal.', 'v. 开动， 促使', '/\'æktʃueɪt | \'æktʃuet/', 'actuate', 6);
INSERT INTO `words` VALUES (8669, 'A motorist needs good visual acuity .', 'n. 敏锐', '/ə\'kjuːəti | ə\'kjuəti/', 'acuity', 6);
INSERT INTO `words` VALUES (8670, 'His business acumen helped him to succeed where others had failed.', 'n. 敏锐, 聪明', '/ə\'kju:men | \'ækjʊmən; ə\'kjuːmən | ˈækjʊˌmɛn/', 'acumen', 6);
INSERT INTO `words` VALUES (8671, '{\"COLLOINEXA\":[\"acute pain\"]}', 'adj. 敏锐的, [医]急性的, 剧烈', '/ə\'kju:t | ə\'kjuːt | ə\'kjut/', 'acute', 6);
INSERT INTO `words` VALUES (8672, 'the old adage that a picture is worth a thousand words', 'n. 格言, 谚语', '/\'ædidʒ | \'ædɪdʒ/', 'adage', 6);
