INSERT INTO `words` VALUES (8676, 'Where supreme adaptability is required , out-of- control swarmware is what you want .', 'n. 适应性', '/ə\'dæptəbɪləti | ə,dæptə\'bɪləti/', 'adaptability', 6);
INSERT INTO `words` VALUES (8677, 'The American Constitution has proved adaptable in changing political conditions.', 'adj. 能适应的, 可修改的', '/ə\'dæptəbl | ə\'dæptəb(ə)l/', 'adaptable', 6);
INSERT INTO `words` VALUES (8678, 'Societies need to develop highly adaptive behavioural rules for survival.', 'adj. 适应的', '/ə\'dæptɪv/', 'adaptive', 6);
