INSERT INTO `words` VALUES (8680, 'What do gambling, sex, heroin and cocaine — and the other things that can addict us — have in common?', 'v. 沉溺； 上瘾', '/\'ædɪkt | \'ædɪkt (for n.); əˈdɪkt (for v.)/', 'addict', 6);
INSERT INTO `words` VALUES (8681, 'She helped him fight his drug addiction.', 'n. 沉溺, 上瘾', '/ə\'dikʃən | ə\'dɪkʃ(ə)n | ə\'dɪkʃən/', 'addiction', 6);
INSERT INTO `words` VALUES (8682, 'Tobacco is highly addictive .', 'adj. 上瘾的', '/ə\'dɪktɪv/', 'addictive', 6);
INSERT INTO `words` VALUES (8683, 'permitted food additives', 'n. 添加剂', '/\'ædətɪv/', 'additive', 6);
INSERT INTO `words` VALUES (8684, 'I suppose the shock had addled his poor old brain.', 'v. 使腐坏, 使糊涂', '/\'ædl | \'æd(ə)l/', 'addle', 6);
INSERT INTO `words` VALUES (8685, 'HIS memories are addled, but the young member of Cocaine Anonymous can just about recall his formal drug education.', 'adj. 腐坏的, 混乱的', '/\'ædld/', 'addled', 6);
INSERT INTO `words` VALUES (8686, 'Applications should be addressed to: The business affairs editor.', 'v. 处理， 对付， 设法解决； 致辞', '/ə\'dres | əˈdrɛs;(for n)ˈædres; ædrɛs/', 'address', 6);
INSERT INTO `words` VALUES (8687, 'Let me adduce more evidence.', 'v. 引证, 举出(例证、理由、证据)', '/ə\'dju:s | ə\'djuːs | ə\'dus/', 'adduce', 6);
INSERT INTO `words` VALUES (8688, 'I’m afraid she’s also an adept liar.', 'adj. 熟练的, 拿手的', '/\'ædept, ə\'dept | ə\'dept; \'ædept | ə\'dɛpt/', 'adept', 6);
INSERT INTO `words` VALUES (8689, 'Farmers have been slow to make adequate provision for their retirement.', 'adj. 足够的', '/\'ædɪkwət | ˈædɪkwət/', 'adequate', 6);
INSERT INTO `words` VALUES (8690, 'But this means they cannot always adhere to the strict codes of practice dictated in UN headquarters.', 'v. 粘附, 胶着, 坚持', '/əd\'hiə | əd\'hɪə | əd\'hɪr/', 'adhere', 6);
INSERT INTO `words` VALUES (8691, 'This idea is gaining adherents.', 'n. 信徒, 追随者, 拥护者', '/əd\'hiərənt | əd\'hɪər(ə)nt | əd\'hɪrənt/', 'adherent', 6);
INSERT INTO `words` VALUES (8692, '...adhesive tape.', 'adj. 黏着的，带黏性的; n. 黏合剂', '/əd\'hiːsɪv | əd\'hisɪv/', 'adhesive', 6);
INSERT INTO `words` VALUES (8693, 'The authors found that brown adipose tissue, a kind of fat, plays a very significant role in burning energy when exposed to cold.', 'adj. 脂肪的, 肥胖的', '/\'ædipəus | \'ædɪpəʊs; -z | \'ædə\'pos; \'ædə\'poz/', 'adipose', 6);
INSERT INTO `words` VALUES (8694, 'We stayed in adjacent rooms.', 'adj. 邻近的, 接近的', '/ə\'dʒeisənt | ə\'dʒeɪs(ə)nt | ə\'dʒesnt/', 'adjacent', 6);
INSERT INTO `words` VALUES (8695, 'It was almost noon when the meeting adjourned.', 'v. 延期， 推迟； 休会', '/ə\'dʒɜːrn | ə\'dʒɝn/', 'adjourn', 6);
INSERT INTO `words` VALUES (8696, 'The Dean adjudicates any faculty disputes.', 'v. 判决, 宣判, 裁定', '/ə\'dʒu:dikeit | ə\'dʒuːdɪkeɪt | ə\'dʒudɪket/', 'adjudicate', 6);
INSERT INTO `words` VALUES (8697, NULL, 'n. 附加物， 附件', '/\'ædʒʌŋkt/', 'adjunct', 6);
INSERT INTO `words` VALUES (8698, NULL, 'v. 起誓, 恳请, (以起誓或诅咒等形式)命令', '/ə\'dʒuə | ə\'dʒʊə; ə\'dʒɔː | ə\'dʒʊr/', 'adjure', 6);
INSERT INTO `words` VALUES (8699, NULL, 'adj. 补助的', '/\'ædʒutənt | \'ædʒʊt(ə)nt | \'ædʒʊtənt/', 'adjutant', 6);
INSERT INTO `words` VALUES (8700, NULL, 'v. 使混合', '/æd\'miks | \'ædmɪks | æd\'mɪks/', 'admix', 6);
INSERT INTO `words` VALUES (8701, 'They admonished me for taking risks with my health.', 'v. 劝告, 训诫, 警告', '/əd\'mɔniʃ | əd\'mɒnɪʃ | əd\'mɑnɪʃ/', 'admonish', 6);
INSERT INTO `words` VALUES (8702, 'Accordingly, the literature in English that has come down to us from this period (1150-1250) is almost exclusively religious or admonitory.', 'adj. 劝告的', '/əd\'mɔnitəri | əd\'mɒnɪt(ə)rɪ/', 'admonitory', 6);
INSERT INTO `words` VALUES (8703, 'Without much ado just start typing or writing down what type of life you really want to live.', 'n. 纷扰, 忙乱', '/ə\'du: | ə\'duː | ə\'du/', 'ado', 6);
INSERT INTO `words` VALUES (8704, '...a few blocks of adobe houses.', 'n. 砖坯, 土砖美国Adobe公司, 是著名的图形图像和排版软件的生产商', '/ə\'dəubi | ə\'dəʊbɪ; ə\'dəʊb | \'ədobɪ/', 'adobe', 6);
INSERT INTO `words` VALUES (8705, 'It is important that an adolescent boy should have an adult in whom he can confide.', 'adj. 青春期的; n. 青少年', '/ˌædə\'lesnt | ,ædə\'lɛsnt/', 'adolescent', 6);
INSERT INTO `words` VALUES (8706, 'Sally was adopted when she was four.', 'v. 采用, 收养', '/ə\'dɔpt | ə\'dɒpt | ə\'dɑpt/', 'adopt', 6);
INSERT INTO `words` VALUES (8707, 'Oh what an adorable little baby!', 'adj. 可崇拜的, 可爱的', '/ə\'dɔ:rəbl | ə\'dɔːrəb(ə)l | ə\'dɔrəbl/', 'adorable', 6);
INSERT INTO `words` VALUES (8708, 'the look of adoration in his eyes', 'n. 崇拜, 爱慕, 受崇拜(或爱慕)的对象', '/,ædə\'reiʃən | ædə\'reɪʃ(ə)n | ,ædə\'reʃən/', 'adoration', 6);
INSERT INTO `words` VALUES (8709, 'Betty adores her grandchildren.', 'v. 崇拜, 爱慕, (口语)喜爱', '/ə\'dɔ: | ə\'dɔː | ə\'dɔr/', 'adore', 6);
INSERT INTO `words` VALUES (8710, 'His watercolour designs adorn a wide range of books.', 'v. 装饰', '/ə\'dɔ:n | ə\'dɔːn | ə\'dɔrn/', 'adorn', 6);
INSERT INTO `words` VALUES (8711, 'It was a building without any adornment or decoration.', 'n. 装饰, 装饰品', '/ə\'dɔ:nmənt | ə\'dɔːnm(ə)nt/', 'adornment', 6);
INSERT INTO `words` VALUES (8712, 'an adroit negotiator', 'adj. 熟练的, 机捷的', '/ə\'drɔit | ə\'drɒɪt | ə\'drɔɪt/', 'adroit', 6);
INSERT INTO `words` VALUES (8713, 'What is there to adulate in her!', 'v. 奉承, 谄媚, 奉承', '/\'ædjuleit | \'ædjʊleɪt/', 'adulate', 6);
INSERT INTO `words` VALUES (8714, 'He basks in other people\'s adulation.', 'n. 奉承， 谄媚', '/ˌædʒə\'leɪʃn | ,ædʒə\'leʃən/', 'adulation', 6);
INSERT INTO `words` VALUES (8715, '...adulatory reviews.', 'adj. 奉承的', '/\'ædʒələtɔːrɪ | \'ædʒələ,tori/', 'adulatory', 6);
INSERT INTO `words` VALUES (8716, 'The food had been adulterated to increase its weight.', 'v. 掺杂', '/ə\'dʌltəreɪt | ə\'dʌltəret/', 'adulterate', 6);
INSERT INTO `words` VALUES (8717, 'Lung cancer has what symptom, have adumbrate?', 'v. 画轮廓, 预示', '/\'ædʌmbreit, æd\'ʌm- | ˈædəmbreɪt/', 'adumbrate', 6);
INSERT INTO `words` VALUES (8718, 'Younger workers tend to be at an advantage (= have an advantage ) when applying for jobs.', 'v. 有利于， 有益于; n. 利益，益处', '/əd\'væntɪdʒ/', 'advantage', 6);
INSERT INTO `words` VALUES (8719, 'the advent of the computer', 'n. (尤指不寻常的人或事)出现, 到来', '/\'ædvənt/', 'advent', 6);
INSERT INTO `words` VALUES (8720, 'It was then that the ecstasy and the dream began, in which emotion was the matter of the universe, and matter but an adventitious intrusion likely to hinder you from spinning where you wanted to spin.', 'adj. 偶然的, 外来的', '/,ædven\'tiʃəs | ,ædv(ə)n\'tɪʃəs | ,ædvɛn\'tɪʃəs/', 'adventitious', 6);
INSERT INTO `words` VALUES (8721, 'Andy isn’t a very adventurous cook.', 'adj. 爱冒险的， 大胆的, 充满危险的', '/əd\'ventʃərəs | əd\'vɛntʃərəs/', 'adventurous', 6);
INSERT INTO `words` VALUES (8722, 'his old adversary', 'n. 敌手, 对手', '/\'ædvəsəri | \'ædvəs(ə)rɪ | \'ædvɚsɛri/', 'adversary', 6);
INSERT INTO `words` VALUES (8723, 'They fear it could have an adverse effect on global financial markets.', 'adj. 有害的， 不利的； 敌对的， 相反的', '/\'ædvɜːrs | ædˈvɚs, ˈædˌvɚs/', 'adverse', 6);
INSERT INTO `words` VALUES (8724, 'his courage in the face of adversity', 'n. 不幸, 灾祸, 逆境', '/əd\'və:səti | əd\'vɜːsɪtɪ | əd\'vɝsəti/', 'adversity', 6);
INSERT INTO `words` VALUES (8725, NULL, 'v. 注意， 留意； 提及', '/\'ædvɜːrt | ædˈvɚt/', 'advert', 6);
INSERT INTO `words` VALUES (8726, 'They no longer advertise alcohol or cigarettes at sporting events.', 'v. 做广告； 通知', '/\'ædvərtaɪz | \'ædvɚtaɪz/', 'advertise', 6);
INSERT INTO `words` VALUES (8727, 'Regular medical check-ups are advisable.', 'adj. 可取的, 明智的', '/əd\'vaizəbl | əd\'vaɪzəb(ə)l | əd\'vaɪzəbl/', 'advisable', 6);
INSERT INTO `words` VALUES (8728, '...members of the advisory committee on the safety of nuclear installations.', 'adj. 顾问的, 咨询的, 劝告的', '/əd\'vaizəri | əd\'vaɪz(ə)rɪ | əd\'vaɪzəri/', 'advisory', 6);
INSERT INTO `words` VALUES (8729, 'The study has also been cited as compelling evidence for screening by the patient advocacy group Lung Cancer Alliance.', 'n. 拥护， 支持', '/\'ædvəkəsi/', 'advocacy', 6);
INSERT INTO `words` VALUES (8730, 'Extremists were openly advocating violence.', 'v. 提倡， 主张， 拥护; n. 支持者， 拥护者', '/\'ædvəkeɪt；-ət | ˈædvəkeɪt；-et/', 'advocate', 6);
INSERT INTO `words` VALUES (8731, NULL, 'adj. 衰弱的', '/,ædai\'næmik/', 'adynamic', 6);
INSERT INTO `words` VALUES (8732, 'a refugee camp operating under the aegis of the UN', 'n. [希神]羊皮盾, 保护, 庇护, 支持', '/\'i:dʒis | \'iːdʒɪs | \'idʒɪs/', 'aegis', 6);
INSERT INTO `words` VALUES (8733, NULL, 'n. 永世, 万古', '/\'i:ən | \'iːən | \'iən/', 'aeon', 6);
INSERT INTO `words` VALUES (8734, 'Aerate your lawn to allow it to breathe and absorb water better.', 'v. 使暴露于空气中, 使充满气体', '/\'eiəreit | \'eəreɪt | \'ɛret/', 'aerate', 6);
INSERT INTO `words` VALUES (8735, 'Weeks of aerial bombardment had destroyed factories and motorways.', 'adj. 空中的， 空气的', '/\'eriəl | \'ɛrɪəl/', 'aerial', 6);
INSERT INTO `words` VALUES (8736, 'If we in fact had the right level of investment in aeronautics, we would not currently be competing with Airbus.', 'n. 航空学, 航空术', '/,εərə\'nɔ:tiks | eərə\'nɔːtɪks | ,ɛrə\'nɔtɪks/', 'aeronautics', 6);
INSERT INTO `words` VALUES (8737, 'She has played both a religious aesthete who abandons all possessions, as well as a serial killer, and her first starring role in “Aap Kaa Surroor- The Real Luv Story”.', 'n. 审美家, 唯美主义者', '/\'i:sθi:t | \'iːsθiːt; \'es- | \'ɛsθit/', 'aesthete', 6);
INSERT INTO `words` VALUES (8738, 'From an esthetic point of view, it’s a nice design.', 'adj. 美学的， 审美的', '/es\'θetɪk | esˈθetɪk; ɛsˈθɛtɪk/', 'aesthetic', 6);
INSERT INTO `words` VALUES (8739, NULL, 'adv. 审美地； 美学观点上地', '/es\'θetɪkli | ɛs\'θɛtɪkli/', 'aesthetically', 6);
INSERT INTO `words` VALUES (8740, NULL, 'n. 美学, 美术理论, 审美学, 美的哲学', '/i:s\'θetiks | iːs\'θetɪks; es- | ɛs\'θɛtɪks/', 'aesthetics', 6);
INSERT INTO `words` VALUES (8741, 'The difference of the accuracy of three interpolation methods for the aestival relative humidity was not significant.', 'adj. 夏季的', '/i:\'staivəl | \'iːstɪv(ə)l; iː\'staɪv(ə)l; \'est-; e\'staɪv(ə)l | \'ɛstəvəl/', 'aestival', 6);
INSERT INTO `words` VALUES (8742, 'an affable guy', 'adj. 和蔼可亲的', '/\'æfəbl | \'æfəb(ə)l/', 'affable', 6);
INSERT INTO `words` VALUES (8743, 'I wore sunglasses all the time and people thought it was an affectation.', 'n. 假装, 虚饰, 做作', '/,æfek\'teiʃən | æfek\'teɪʃ(ə)n | ,æfɛk\'teʃən/', 'affectation', 6);
INSERT INTO `words` VALUES (8744, 'an affected laugh', 'adj. 受到影响的, 受(疾病)侵袭的, 假装的, 做作的', '/ə\'fektid | ə\'fektɪd | ə\'fɛktɪd/', 'affected', 6);
INSERT INTO `words` VALUES (8745, 'She thought of him with affection.', 'n. 友爱, 爱情, 影响, 疾病, 倾向', '/ə\'fekʃən | ə\'fekʃ(ə)n | ə\'fɛkʃən/', 'affection', 6);
INSERT INTO `words` VALUES (8746, 'an affectionate hug', 'adj. 亲爱的, 挚爱的', '/ə\'fekʃ(ə)nət | ə\'fɛkʃənət/', 'affectionate', 6);
INSERT INTO `words` VALUES (8747, 'affective disorders', 'adj. 感情的， 表达感情的', '/ə\'fektɪv | ə\'fɛktɪv/', 'affective', 6);
INSERT INTO `words` VALUES (8748, 'In his sworn affidavit, Roche outlined a history of actions against him by the church.', 'n. <美>[律]宣誓书, (经陈诉者宣誓在法律上可采作证据的)书面陈述', '/,æfi\'deivit | ,æfɪ\'deɪvɪt | ,æfə\'devɪt/', 'affidavit', 6);
INSERT INTO `words` VALUES (8749, 'He wanted to affiliate with a U.S. firm because he needed expert advice in legal affairs.', 'v. 使隶属于； 追溯…的来源； 联合; n. 成员， 附属机构', '/ə\'fɪlɪeɪt | ə\'fɪlɪet/', 'affiliate', 6);
INSERT INTO `words` VALUES (8750, 'The kidnappers had no affiliation with any militant group.', 'n. 联系, 从属关系', '/ə,fili\'eiʃən | əfɪlɪ\'eɪʃ(ə)n | ə,fɪlɪ\'eʃən/', 'affiliation', 6);
INSERT INTO `words` VALUES (8751, 'He has a close affinity with the landscape and people he knew when he was growing up.', 'n. 密切关系, 吸引力, 姻亲关系, 亲合力', '/ə\'finəti | ə\'fɪnɪtɪ | ə\'fɪnəti/', 'affinity', 6);
INSERT INTO `words` VALUES (8752, 'In other words, we must return attention to the affirmation.', 'n. 肯定； 断言', '/ˌæfər\'meɪʃn | ,æfɚ\'meʃən/', 'affirmation', 6);
INSERT INTO `words` VALUES (8753, 'an affirmative nod', 'adj. 肯定的, (对正式辩论中的问题)表示赞成的, (态度, 方法等)积极的, 乐观的, 怀有希望的', '/ə\'fə:mətiv | ə\'fɜːmətɪv | ə\'fɝmətɪv/', 'affirmative', 6);
INSERT INTO `words` VALUES (8754, 'Will discuss concepts such as phoneme, morpheme , affix, rules and constraints.', 'v. 黏上， 贴上； 添上; n. 词缀', '/ə\'fɪks/', 'affix', 6);
INSERT INTO `words` VALUES (8755, NULL, 'n. 一阵风, 灵感, 神的启示', '/ə\'fleitəs | ə\'fleɪtəs | ə\'fletəs/', 'afflatus', 6);
INSERT INTO `words` VALUES (8756, NULL, 'v. 折磨； 使痛苦', '/ə\'flɪkt/', 'afflict', 6);
INSERT INTO `words` VALUES (8757, 'the afflictions of old age', 'n. 痛苦, 苦恼', '/ə\'flikʃən | ə\'flɪkʃ(ə)n/', 'affliction', 6);
INSERT INTO `words` VALUES (8758, 'affluent families', 'adj. 富有的， 丰富的', '/\'æfluənt/', 'affluent', 6);
INSERT INTO `words` VALUES (8759, '...the availability of affordable housing.', 'adj. 负担得起的', '/ə\'fɔːrdəbl | ə\'fɔrdəbl/', 'affordable', 6);
INSERT INTO `words` VALUES (8760, 'It\'s an affront to human dignity to keep someone alive like this.', 'n. 公开侮辱, 轻蔑', '/ə\'frʌnt/', 'affront', 6);
INSERT INTO `words` VALUES (8761, 'I happen to be an aficionado of the opera, and I love art museums.', 'n. <西班牙>狂热爱好者, 迷', '/ə,fisjə\'nɑ:dəu | ə,fɪsjə\'nɑːdəʊ; -,fɪʃjə- | ə,fɪʃə\'nɑdo/', 'aficionado', 6);
INSERT INTO `words` VALUES (8762, 'In the aftermath of the coup, the troops opened fire on the demonstrators.', 'n. 结果, 后果', '/\'ɑ:ftəmæθ, \'æf- | \'ɑːftəmæθ | \'æftəmæθ/', 'aftermath', 6);
INSERT INTO `words` VALUES (8763, 'Vince watched, his mouth agape in horror.', 'adj&adv. 大张着的', '/ə\'geɪp | ə\'ɡep/', 'agape', 6);
INSERT INTO `words` VALUES (8764, 'The Republicans have stuck to their conservative agenda.', 'n. 议程', '/ə\'dʒendə | ə\'dʒɛndə/', 'agenda', 6);
INSERT INTO `words` VALUES (8765, NULL, 'n. 大团, 大块', '/ə\'ɡlɔmərət, -reit, ə\'ɡlɔməreit | ə\'glɒməreɪt | ə\'ɡlɑməret/', 'agglomerate', 6);
INSERT INTO `words` VALUES (8766, 'At the dinner table, my father would go on and on, showing off, aggrandizing himself.', 'v. 增加, 夸大', '/ə\'ɡrændaiz | ə\'grændaɪz | əˈɡrænˌdaɪz, ˈæɡrən-/', 'aggrandize', 6);
INSERT INTO `words` VALUES (8767, 'Their money problems were further aggravated by a rise in interest rates.', 'v. 使恶化, 加重', '/\'æɡrəveit | \'ægrəveɪt | \'æɡrəvet/', 'aggravate', 6);
INSERT INTO `words` VALUES (8768, '(= as a group or in total ) , women outlive men by 7 or more years.', 'n. 合计, 总计, 集合体', '/\'æɡriɡət, \'æɡriɡeit | \'ægrɪgət; (for v.) ˈægrɪgeɪt | \'æɡrɪɡət; (for v.) æɡrɪˌɡet/', 'aggregate', 6);
INSERT INTO `words` VALUES (8769, NULL, 'n. 集合, 集合体, 聚合', '/,æɡri\'ɡeiʃən | ,æɡrɪ\'ɡeɪʃən | ,ægrɪ\'geʃən/', 'aggregation', 6);
INSERT INTO `words` VALUES (8770, 'Jim’s voice became aggressive.', 'adj. 好斗的, 敢作敢为的, 有闯劲的, 侵略性的', '/ə\'ɡresiv | ə\'gresɪv | ə\'ɡrɛsɪv/', 'aggressive', 6);
INSERT INTO `words` VALUES (8771, 'it aggrieved her much that she could not go', 'v. 使受委屈， 使痛苦', '/ə\'griːv | ə\'griv/', 'aggrieve', 6);
INSERT INTO `words` VALUES (8772, 'the aggrieved party (= the person who has suffered )', 'adj. 受虐待的, 权利受到不法侵害的, 抱不平的', '/ə\'ɡri:vd | ə\'griːvd | ə\'ɡrivd/', 'aggrieved', 6);
INSERT INTO `words` VALUES (8773, 'Hank looked at her aghast.', 'adj. 惊骇的, 吓呆的', '/ə\'ɡɑ:st, -\'ɡæst | ə\'gɑːst | ə\'ɡæst/', 'aghast', 6);
INSERT INTO `words` VALUES (8774, 'Dogs are surprisingly agile.', 'adj. 敏捷的， 灵活的', '/\'ædʒl/', 'agile', 6);
INSERT INTO `words` VALUES (8775, 'If for some reason you don\'t have or cannot adopt these values, then you should not worry about agility.', 'n. 敏捷', '/ə\'dʒɪləti | ə\'dʒiləti/', 'agility', 6);
INSERT INTO `words` VALUES (8776, 'I must warn you that any mention of Clare agitates your grandmother.', 'v. 鼓动， 煽动； 使不安， 使焦虑', '/\'ædʒɪteɪt | ˈædʒɪˌteɪt/', 'agitate', 6);
INSERT INTO `words` VALUES (8777, 'Amanda was getting visibly agitated.', 'adj. 激动的,表现不安的', '/\'ædʒiteitid | \'ædʒɪteɪtɪd | \'ædʒɪtetɪd/', 'agitated', 6);
INSERT INTO `words` VALUES (8778, 'She was in a state of considerable agitation.', 'n. 激动, 兴奋, 煽动, 搅动', '/,ædʒi\'teiʃən | ædʒɪ\'teɪʃ(ə)n | ,ædʒɪ\'teʃən/', 'agitation', 6);
INSERT INTO `words` VALUES (8779, 'When an atheist or agnostic asks me about Sunday School for their children, I recommend exposing their children to a religion.', 'n. [哲]不可知论者', '/æɡ\'nɔstik | æg\'nɒstɪk | æg\'nɑstɪk/', 'agnostic', 6);
INSERT INTO `words` VALUES (8780, 'I’ve been agog all afternoon, waiting for the next part of your story.', 'adj. 兴奋的, 热切的', '/ə\'ɡɔɡ | ə\'gɒg/', 'agog', 6);
INSERT INTO `words` VALUES (8781, 'And when it was done, when her agonal struggles had ceased, you left us a calling card.', 'adj. (尤指临死时)痛苦的', '/\'æɡənəl/', 'agonal', 6);
INSERT INTO `words` VALUES (8782, 'the agony of arthritis', 'n. 苦恼, 极大的痛苦', '/\'æɡəni | \'ægənɪ/', 'agony', 6);
INSERT INTO `words` VALUES (8783, 'The avid comic book reader considers himself a borderline agoraphobic with mild-to-severe anxiety issues who wishes he were a superhero himself.', 'n&adj. 患旷野恐惧症的', '/ˌægərə\'foubɪk | ,æɡərə\'fobɪk/', 'agoraphobic', 6);
INSERT INTO `words` VALUES (8784, 'This was a feature of agrarian development in Britain.', 'adj. 土地的', '/ə\'greriən | ə\'ɡrɛrɪən/', 'agrarian', 6);
INSERT INTO `words` VALUES (8785, 'We spent a most agreeable couple of hours.', 'adj. 令人愉快的； 欣然同意的', '/ə\'griːəbl | ə\'ɡriəbl/', 'agreeable', 6);
INSERT INTO `words` VALUES (8786, 'It is easier for two parties to reach agreement than for three.', 'n. 同意, 一致, 协定, 协议', '/ə\'ɡri:mənt | ə\'griːm(ə)nt | ə\'grimənt/', 'agreement', 6);
INSERT INTO `words` VALUES (8787, NULL, 'n. 农艺学家, 农学家', '/ə\'ɡrɔnəmist | ə\'ɡrɑnəmɪst/', 'agronomist', 6);
INSERT INTO `words` VALUES (8788, NULL, 'n. 冷颤， 发冷', '/\'eɪgjuː | \'egjʊ/', 'ague', 6);
INSERT INTO `words` VALUES (8789, NULL, 'v. 生病', '/eɪl | el/', 'ail', 6);
