INSERT INTO `words` VALUES (8791, 'airborne pollutants', 'adj. 空运的, 空气传播的, 空降的', '/\'εəbɔ:n | \'eəbɔːn | \'ɛr\'bɔrn/', 'airborne', 6);
INSERT INTO `words` VALUES (8792, 'airtight containers', 'adj. 密封的, 无懈可击的', '/\'εətait | \'eətaɪt | \'ɛrtaɪt/', 'airtight', 6);
INSERT INTO `words` VALUES (8793, 'Something akin to panic overwhelmed him.', 'adj. 同族的； 类似的', '/ə\'kɪn/', 'akin', 6);
INSERT INTO `words` VALUES (8794, 'The walls were of white alabaster, set here and there with blue and green tiles.', 'n. 雪花石膏', '/\'æləbɑ:stə | \'æləbɑːstə; -bæstə; ,ælə\'bɑːstə; -\'bæstə | \'æləbæstɚ/', 'alabaster', 6);
INSERT INTO `words` VALUES (8795, 'He accepted the job, albeit with some hesitation.', 'conj. 虽然， 尽管', '/ˌɔːl\'biːɪt | ,ɔl\'biɪt/', 'albeit', 6);
INSERT INTO `words` VALUES (8796, 'Religion had an intimate association with alchemy during the Middle Ages.', 'n. 炼金术, 魔力', '/\'ælkimi | \'ælkɪmɪ | \'ælkəmi/', 'alchemy', 6);
INSERT INTO `words` VALUES (8797, 'In the alcoves on either side of the fire were bookshelves.', 'n. 凹室, 壁橱, <古>凉亭, 避暑别墅', '/\'ælkəuv | \'ælkəʊv | \'ælkov/', 'alcove', 6);
INSERT INTO `words` VALUES (8798, 'Your experience of speculation makes you have aleatory thought.', 'adj. 侥幸的， 偶然的', '/\'elɪəːtərɪ | \'elɪə\'tɔri/', 'aleatory', 6);
INSERT INTO `words` VALUES (8799, 'The animal raised its head, suddenly alert.', 'adj. 警惕的，机警的; n. 警报', '/ə\'lɜːrt | ə\'lɝt/', 'alert', 6);
INSERT INTO `words` VALUES (8800, 'a spy operating under the alias Barsad', 'n. 别名, 化名', '/\'eiliæs | ˈeɪliəs/', 'alias', 6);
INSERT INTO `words` VALUES (8801, 'The latest tax proposals will alienate many voters.', 'v. 使疏远， 离间', '/\'eɪliəneɪt | \'eiljəneit/', 'alienate', 6);
INSERT INTO `words` VALUES (8802, 'His behavior alienated him and his brother.', 'adj. 疏离的', '/\'eiljəneitid | \'eljənetɪd/', 'alienated', 6);
INSERT INTO `words` VALUES (8803, NULL, 'n. 疏远， 离间', '/ˌeɪliə\'neɪʃn | ,eiljə\'neiʃən/', 'alienation', 6);
INSERT INTO `words` VALUES (8804, 'A thrush alighted on a branch of the pine tree.', 'v. 落下', '/ə\'lait | ə\'laɪt/', 'alight', 6);
INSERT INTO `words` VALUES (8805, 'The extremely salty, alkali lake holds little life, but its waters are a favorite spot for wading birds.', 'n. [化]碱', '/\'ælkəlai | \'ælkəlaɪ | \'ælkə\'lai/', 'alkali', 6);
INSERT INTO `words` VALUES (8806, 'The president made a statement to allay public anxiety.', 'v. 减轻， 缓和', '/ə\'leɪ | ə\'le/', 'allay', 6);
INSERT INTO `words` VALUES (8807, NULL, 'n. 主张，断言, 辩解', '/ælɪ\'geɪʃ(ə)n | \'ælə\'geʃən/', 'allegation', 6);
INSERT INTO `words` VALUES (8808, 'an oath of allegiance', 'n. 忠贞, 效忠', '/ə\'li:dʒəns | ə\'liːdʒ(ə)ns | ə\'lidʒəns/', 'allegiance', 6);
INSERT INTO `words` VALUES (8809, 'The poem\'s comic allegory was transparent.', 'n. 寓言', '/\'æləgɔːri | \'æləɡɔri/', 'allegory', 6);
INSERT INTO `words` VALUES (8810, NULL, 'adv. 急速地', '/ə\'leiɡrəu | ə\'legrəʊ; -\'leɪg- | ə\'lɛgro/', 'allegro', 6);
INSERT INTO `words` VALUES (8811, 'an allergic reaction to nuts', 'adj. [医]过敏的, 患过敏症的', '/ə\'lə:dʒik | ə\'lɜːdʒɪk | ə\'lɝdʒɪk/', 'allergic', 6);
INSERT INTO `words` VALUES (8812, 'a food allergy', 'n. [医]敏感症, <口>反感', '/\'ælədʒi | \'ælədʒɪ | \'ælɚdʒi/', 'allergy', 6);
INSERT INTO `words` VALUES (8813, 'measures to alleviate poverty', 'v. 使(痛苦等)易于忍受, 减轻', '/ə\'li:vieit | ə\'liːvɪeɪt | ə\'livɪ\'et/', 'alleviate', 6);
INSERT INTO `words` VALUES (8814, 'The alley led to the railway bridge.', 'n. 小路, 巷, (花园里两边有树篱的)小径', '/\'æli | \'ælɪ/', 'alley', 6);
INSERT INTO `words` VALUES (8815, NULL, 'n. 产于美洲的鳄鱼', '/\'æliɡeitə | \'ælɪgeɪtə | \'ælɪɡetɚ/', 'alligator', 6);
INSERT INTO `words` VALUES (8816, 'Tickets are limited and will be allocated to those who apply first.', 'v. 配给， 分配', '/\'æləkeɪt | \'æləket/', 'allocate', 6);
INSERT INTO `words` VALUES (8817, 'A State Department spokeswoman said that the aid allocation for Pakistan was still under review.', 'n. 分配, 安置', '/,æləu\'keiʃən | ælə\'keɪʃ(ə)n | ,ælə\'keʃən/', 'allocation', 6);
INSERT INTO `words` VALUES (8818, 'One who practices or advocates allopathy.', 'n. [医]对抗疗法', '/ə\'lɔpəθi | ə\'lɒpəθɪ | ə\'lɑpəθi/', 'allopathy', 6);
INSERT INTO `words` VALUES (8819, 'The seats are allotted to the candidates who have won the most votes.', 'v. 分配； 拨出', '/ə\'lɑːt | ə\'lɑt/', 'allot', 6);
INSERT INTO `words` VALUES (8820, 'Sales staff get a generous mileage allowance or a company car.', 'n. 津贴， 补助； 承认， 允许', '/ə\'lauəns | ə\'laʊəns/', 'allowance', 6);
INSERT INTO `words` VALUES (8821, 'Brass is an alloy of copper and zinc.', 'n. 合金', '/\'ælɔi, ə\'lɔi | \'ælɒɪ | \'ælɔɪ/', 'alloy', 6);
INSERT INTO `words` VALUES (8822, 'With friends, she sometimes alluded to a feeling that she herself was to blame for her son\'s predicament.', 'v. 暗指, 影射, 间接提到', '/ə\'lju:d | ə\'l(j)uːd | ə\'lʊd/', 'allude', 6);
INSERT INTO `words` VALUES (8823, 'The allure and charm of Paris excite all who visit there.', 'v. 吸引', '/ə\'ljuə | əˈlʊə(r) | əˈlʊr/', 'allure', 6);
INSERT INTO `words` VALUES (8824, 'Here the rewards of his industry follow-- with equal steps the progress of his labour; his labour is founded on the basis of nature, self-interest; can it want a stronger allurement?', 'n. 诱惑物，魅力', '/ə\'ljuəmənt | ə\'ljʊəmənt | ə\'lʊrmənt/', 'allurement', 6);
INSERT INTO `words` VALUES (8825, '...the most alluring city in Southeast Asia.', 'adj. 吸引人的， 迷人的', '/ə\'lurɪŋ | \'ə\'ljuəriŋ/', 'alluring', 6);
INSERT INTO `words` VALUES (8826, 'This last point was understood to be an allusion to the long-standing hostility between the two leaders.', 'n. 提及, 暗示', '/ə\'lju:ʒən | ə\'luːʒ(ə)n; -\'ljuː- | ə\'lʊʒən/', 'allusion', 6);
INSERT INTO `words` VALUES (8827, 'His new play, Arcadia, is as intricate, elaborate and allusive as anything he has yet written.', 'adj. 暗指的， 间接提到的', '/ə\'luːsɪv | ə\'lju:siv/', 'allusive', 6);
INSERT INTO `words` VALUES (8828, 'alluvial flood plains', 'adj. 冲积的, 淤积的', '/ə\'lju:viəl | ə\'l(j)uːvɪəl | ə\'lʊvɪəl/', 'alluvial', 6);
INSERT INTO `words` VALUES (8829, 'He will have no choice but to ally himself with the new movement.', 'v. 结盟， 联合; n. 同盟者， 伙伴', '/\'ælaɪ/', 'ally', 6);
INSERT INTO `words` VALUES (8830, '...sponge cake flavoured with almonds.', 'n. [植]杏树, 杏仁, 杏仁壮物', '/\'ɑ:mənd | \'ɑːmənd | ˈɑːmənd/', 'almond', 6);
INSERT INTO `words` VALUES (8831, NULL, 'n. 施舍, 救济物(钱,食物,衣物等)', '/ɑ:mz | ɑːmz/', 'alms', 6);
INSERT INTO `words` VALUES (8832, 'Beneath that aloof exterior, Gayle is a warm, sympathetic person.', 'adj. 远离的； 冷淡的， 冷漠的', '/ə\'luːf | ə\'luf/', 'aloof', 6);
INSERT INTO `words` VALUES (8833, 'Ten months ago he was just an also-ran for the Democratic nomination.', 'n. 落选者； 不重要的参与者', '/\'ɔːlsou ræn | \'ɔ:lsəuræn/', 'also-ran', 6);
INSERT INTO `words` VALUES (8834, 'a crucifix above the high altar', 'n. 祭坛, (基督教教堂内的)圣坛, 祈祷祭拜的地方', '/\'ɔ:ltə | \'ɔːltə; \'ɒl- | \'ɔltɚ/', 'altar', 6);
INSERT INTO `words` VALUES (8835, 'Her face hadn’t altered much over the years.', 'v. 改变， 更改', '/\'ɔːltər | \'ɔltɚ/', 'alter', 6);
INSERT INTO `words` VALUES (8836, 'Making some simple alterations to your diet will make you feel fitter.', 'n. 变更, 改造', '/,ɔ:ltə\'reiʃən | ɔːltə\'reɪʃ(ə)n; \'ɒl- | ,ɔltə\'reʃən/', 'alteration', 6);
INSERT INTO `words` VALUES (8837, 'I had a slight altercation with some people who objected to our filming.', 'n. 争论, 口角', '/,ɔ:ltə\'keiʃən | ɒltə\'keɪʃ(ə)n | ,ɔltɚ\'keʃən/', 'altercation', 6);
INSERT INTO `words` VALUES (8838, 'alternate blue and red stripes', 'adj. 轮流的， 交替的; v. 轮流， 交替; n. 候选人， 代替者', '/ˈɔ:ltəneɪt;(for adj.)ɔ:lˈtɜ:nət | ˈɔltɚˌnet;(for adj.)ˈɔ:ltərnət/', 'alternate', 6);
INSERT INTO `words` VALUES (8839, 'An alternative route is along the Via Unione.', 'adj. 轮流的， 交替的； 两者择一的', '/ɔːl\'tɜːrnətɪv | ɔl\'tɝnətɪv/', 'alternative', 6);
INSERT INTO `words` VALUES (8840, 'And that is where the altimeter stayed for most of the 14-hour journey.', 'n. 高度计', '/\'æltimi:tə, æl\'timitə | \'æltɪmiːtə | æl\'tɪmətɚ/', 'altimeter', 6);
INSERT INTO `words` VALUES (8841, 'Many choose to work in developing countries out of altruism.', 'n. 利他主义, 利他', '/\'æltruizəm | \'æltrʊɪz(ə)m | \'æltruɪzəm/', 'altruism', 6);
INSERT INTO `words` VALUES (8842, 'recycled aluminium cans', 'n. [化]铝', '/,ælju\'minjəm | æl(j)ʊ\'mɪnɪəm | ,æljə\'mɪnɪəm/', 'aluminium', 6);
INSERT INTO `words` VALUES (8843, 'Millions of people have received amalgam fillings, although their popularity has dropped off in recent years.', 'n. [采矿]汞合金, 汞齐', '/ə\'mælɡəm | ə\'mælgəm/', 'amalgam', 6);
INSERT INTO `words` VALUES (8844, 'Stir until the ingredients are amalgamated.', 'v. 使与汞混合, 合并', '/ə\'mælɡəmeit | ə\'mælgəmeɪt | ə\'mælɡəmet/', 'amalgamate', 6);
INSERT INTO `words` VALUES (8845, 'For 25 years, Darwin amassed evidence to support his theories.', 'v. 收集, 积聚(尤指财富)', '/ə\'mæs/', 'amass', 6);
INSERT INTO `words` VALUES (8846, 'a gifted amateur', 'n. 业余爱好者', '/\'æmətər | ˈæmətər/', 'amateur', 6);
INSERT INTO `words` VALUES (8847, 'His paintings are rather amateurish.', 'adj. 业余的, 非职业的, 不熟练的', '/,æmə\'tə:riʃ | \'æmətərɪʃ/', 'amateurish', 6);
INSERT INTO `words` VALUES (8848, 'Dave amazed his friends by suddenly getting married.', 'v. 使大为吃惊， 使惊奇', '/ə\'meɪz | ə\'mez/', 'amaze', 6);
INSERT INTO `words` VALUES (8849, NULL, 'adj. 迂远的, 迂曲的', '/æm\'beidʒəs/', 'ambagious', 6);
INSERT INTO `words` VALUES (8850, 'Jack is an ambidextrous hitter; he can bat right - handed or left - handed.', 'adj. 怀有二心的, 非常灵巧的', '/,æmbi\'dekstrəs | ,æmbɪ\'dekstrəs | \'æmbə\'dɛkstrəs/', 'ambidextrous', 6);
INSERT INTO `words` VALUES (8851, 'The overall ambience of the room is cosy.', 'n. 环境， 气氛', '/\'æmbiəns | \'æmbɪəns/', 'ambience', 6);
INSERT INTO `words` VALUES (8852, 'legal ambiguities', 'n. 含糊, 不明确', '/,æmbi\'ɡju:iti | æmbɪ\'gjuːɪtɪ | ,æmbɪ\'ɡjuəti/', 'ambiguity', 6);
INSERT INTO `words` VALUES (8853, 'The language in the Minister’s statement is highly ambiguous.', 'adj. 暧昧的, 不明确的', '/æm\'biɡjuəs | æm\'bɪgjʊəs | æm\'bɪɡjuəs/', 'ambiguous', 6);
INSERT INTO `words` VALUES (8854, 'Alfred was intensely ambitious, obsessed with the idea of becoming rich.', 'adj. 有抱负的， 雄心勃勃的', '/æm\'bɪʃəs/', 'ambitious', 6);
INSERT INTO `words` VALUES (8855, NULL, 'n. 正反感情并存', '/,æmbi\'veiləns, æm\'bivə-,-lənsi | æm\'bɪv(ə)l(ə)ns; æm\'bɪvəl(ə)ns; æm\'bɪvələns | æm\'bɪvələns/', 'ambivalence', 6);
INSERT INTO `words` VALUES (8856, 'As a group, they are ambivalent about whether the quality of online content would suffer if companies could not charge for it—34% think so while 30% do not; and the remaining 36% have no firm opinion.', 'adj. 矛盾的, 好恶相克的', '/,æmbi\'veilənt, æm\'bivə- | æm\'bɪv(ə)l(ə)nt | æm\'bɪvələnt/', 'ambivalent', 6);
INSERT INTO `words` VALUES (8857, 'An old man came out and ambled over for a chat.', 'v. 缓行, 溜蹄', '/\'æmbl | \'æmb(ə)l/', 'amble', 6);
INSERT INTO `words` VALUES (8858, NULL, 'n. 神的食物, 特别美味的食物', '/æm\'brəuzjə | æm\'brəʊzɪə | æm\'brozɪə/', 'ambrosia', 6);
INSERT INTO `words` VALUES (8859, 'The soldiers were killed in an ambush.', 'n. 埋伏, 伏兵', '/\'æmbuʃ | \'æmbʊʃ/', 'ambush', 6);
INSERT INTO `words` VALUES (8860, 'It is not clear what can be done to ameliorate the situation.', 'v. 改善， 改良', '/ə\'miːliəreɪt | ə\'milɪə\'ret/', 'ameliorate', 6);
INSERT INTO `words` VALUES (8861, 'She was always a very amenable child.', 'adj. 应服从的, 有服从义务的, 有责任的', '/ə\'miːnəb(ə)l | ə\'minəbl/', 'amenable', 6);
INSERT INTO `words` VALUES (8862, 'The law was amended to include women.', 'v. 改正， 修正； 改善', '/ə\'mend | ə\'mɛnd/', 'amend', 6);
INSERT INTO `words` VALUES (8863, 'constitutional amendments', 'n. 改善, 改正', '/ə\'mendmənt | ə\'men(d)m(ə)nt | ə\'mɛndmənt/', 'amendment', 6);
INSERT INTO `words` VALUES (8864, NULL, 'n. 宜人, 礼仪', '/ə\'mi:nəti, ə\'men- | ə\'miːnɪtɪ; -\'men- | ə\'mɛnəti/', 'amenity', 6);
INSERT INTO `words` VALUES (8865, 'The thing that you touch is too much also, return amerce!', 'v. 罚款, 惩罚', '/ə\'mə:s | ə\'mɜːs/', 'amerce', 6);
INSERT INTO `words` VALUES (8866, 'The necklace consisted of amethysts set in gold.', 'n. [矿]紫水晶, 紫色', '/\'æmiθist | \'æməθɪst/', 'amethyst', 6);
INSERT INTO `words` VALUES (8867, NULL, 'n. 亲切， 友善', '/ˌeɪmiə\'bɪlətɪ | ,emɪə\'bɪləti/', 'amiability', 6);
INSERT INTO `words` VALUES (8868, 'The driver was an amiable young man.', 'adj. 亲切的, 和蔼可亲的', '/\'eimjəbl | \'eɪmɪəb(ə)l | \'emɪəbl/', 'amiable', 6);
INSERT INTO `words` VALUES (8869, 'Their relationship hasn’t always been amicable.', 'adj. 友善的, 和平的', '/\'æmikəbl | \'æmɪkəb(ə)l | \'æmɪkəbl/', 'amicable', 6);
INSERT INTO `words` VALUES (8870, 'Our only choice in the matter is whether to accept it amicably, or be dragged, kicking and screaming, into the next chapter of our existence.', 'adv. 友善地', '/\'æmɪkəbli/', 'amicably', 6);
INSERT INTO `words` VALUES (8871, 'a spirit of perfect amity', 'n. 友好关系', '/\'æməti/', 'amity', 6);
INSERT INTO `words` VALUES (8872, 'We tend to think that a person who is a complete victim of amnesia is still the same person as before.', 'n. 健忘症', '/æm\'ni:zjə | æm\'niːzɪə | æm\'niʒə/', 'amnesia', 6);
INSERT INTO `words` VALUES (8873, 'Activists who were involved in crimes of violence will not automatically be granted amnesty.', 'n. (尤指对反政府政治犯的)特赦', '/\'æmnisti | \'æmnɪstɪ | \'æmnəsti/', 'amnesty', 6);
INSERT INTO `words` VALUES (8874, 'a completely amoral person', 'adj. 与道德无关的, 超道德的', '/ei\'mɔrəl | eɪ\'mɒr(ə)l | \'e\'mɔrəl/', 'amoral', 6);
INSERT INTO `words` VALUES (8875, 'She resisted his amorous advances .', 'adj. 多情的, 恋爱的, 表示爱情的', '/\'æmərəs | \'æm(ə)rəs/', 'amorous', 6);
INSERT INTO `words` VALUES (8876, 'an amorphous mass of twisted metal', 'adj. 无定形的, 无组织的', '/ə\'mɔ:fəs | ə\'mɔːfəs | ə\'mɔrfəs/', 'amorphous', 6);
INSERT INTO `words` VALUES (8877, 'There\'s little advantage to amortizing the loan, especially on a 30 or 40-year basis.', 'v. 分期清偿', '/ə\'mɔ:taiz, \'æmə- | ə\'mɔ:taɪz | \'æmɚtaɪz/', 'amortize', 6);
INSERT INTO `words` VALUES (8878, 'an ample bosom', 'adj. 充足的, 丰富的', '/\'æmpl | \'æmp(ə)l/', 'ample', 6);
INSERT INTO `words` VALUES (8879, 'an amplified guitar', 'v. 放大, 增强', '/\'æmplifai | \'æmplɪfaɪ/', 'amplify', 6);
INSERT INTO `words` VALUES (8880, 'Two of her toes were amputated because of frostbite.', 'v. 切除(手臂,腿等)', '/\'æmpjuteit | \'æmpjʊteɪt | \'æmpjutet/', 'amputate', 6);
INSERT INTO `words` VALUES (8881, 'When the farmer opened the tightly sealed amulet a dog jumped out and ran away, along with his successful crops.', 'n. 护身符', '/\'æmjulit | \'æmjʊlɪt | \'æmjʊlət/', 'amulet', 6);
INSERT INTO `words` VALUES (8882, 'He made funny faces to amuse the children.', 'v. 使愉快， 逗某人笑', '/ə\'mjuːz | ə\'mjuz/', 'amuse', 6);
INSERT INTO `words` VALUES (8883, 'When do you think Euramerican market can anabiosis ?', 'n. [医]回生, 复苏', '/,ænəbai\'əusis | ,ænəbaɪ\'əʊsɪs | ,ænəbaɪ\'osɪs/', 'anabiosis', 6);
INSERT INTO `words` VALUES (8884, 'The film is full of anachronisms.', 'n. 时代错误', '/ə\'nækrənizəm | ə\'nækrə,nɪz(ə)m | ə\'nækrənɪzəm/', 'anachronism', 6);
INSERT INTO `words` VALUES (8885, 'Many of its practices seem anachronistic.', 'adj. 时代错误的', '/əˌnækrə\'nɪstɪk | ə,nækrə\'nistik,-kəl/', 'anachronistic', 6);
INSERT INTO `words` VALUES (8886, 'anaerobic bacteria', 'adj. 厌氧的; n. 厌氧微生物', '/ˌæne\'roubɪk | ,ænɛ\'robɪk/', 'anaerobic', 6);
INSERT INTO `words` VALUES (8887, NULL, 'n. 无痛觉， 痛觉丧失', '/ˌænəl\'dʒiːʒə | \'ænl\'dʒiʒə/', 'analgesia', 6);
INSERT INTO `words` VALUES (8888, 'If approved, the FDA said Cymbalta would be the first nontraditional analgesic approved for chronic pain.', 'adj. 止痛的, 不痛的', '/,ænæl\'dʒi:sik | ,æn(ə)l\'dʒiːzɪk; -sɪk | \'ænl\'dʒizɪk/', 'analgesic', 6);
INSERT INTO `words` VALUES (8889, 'Marine construction technology like this is very complex, somewhat analogous to trying to build a bridge under water.', 'adj. 类似的, 相似的, 可比拟的', '/ə\'næləɡəs | ə\'næləgəs/', 'analogous', 6);
INSERT INTO `words` VALUES (8890, 'The analogy between music and fragrance has stuck.', 'n. 类似, 类推', '/ə\'nælədʒi | ə\'nælədʒɪ/', 'analogy', 6);
INSERT INTO `words` VALUES (8891, 'a lawless, anarchic city', 'adj. 无政府主义的, 无法无天的', '/æ\'nɑ:kik,-kəl | ə\'nɑːkɪk | ən\'ɑrkɪk/', 'anarchic', 6);
INSERT INTO `words` VALUES (8892, 'The prison is close to anarchy.', 'n. 无政府状态, 政治混乱', '/\'ænəki | \'ænəkɪ | \'ænɚki/', 'anarchy', 6);
INSERT INTO `words` VALUES (8893, 'Violence was anathema to them.', 'n. 诅咒, 咒逐, [宗]革出教门, 被咒逐的人(物)', '/ə\'næθəmə/', 'anathema', 6);
INSERT INTO `words` VALUES (8894, 'an anatomical examination', 'adj. 解剖学的', '/ˌænə\'tɑːmɪkl | ,ænə\'tɑmɪkl/', 'anatomical', 6);
INSERT INTO `words` VALUES (8895, 'My ancestors were French.', 'n. 祖先， 祖宗', '/\'ænsestər | \'ænsɛstɚ/', 'ancestor', 6);
INSERT INTO `words` VALUES (8896, '...the family\'s ancestral home in southern Germany.', 'adj. 祖先的， 祖传的', '/æn\'sestrəl | æn\'sɛstrəl/', 'ancestral', 6);
INSERT INTO `words` VALUES (8897, 'Animal and man come unto me, the anchorite.', 'n. 隐者, 隐士', '/\'æŋkərait | \'æŋkəraɪt/', 'anchorite', 6);
INSERT INTO `words` VALUES (8898, 'Agreement was reached on several ancillary matters.', 'adj. 补助的, 副的', '/æn\'siləri | æn\'sɪlərɪ | \'ænsəlɛri/', 'ancillary', 6);
INSERT INTO `words` VALUES (8899, 'His findings are based on anecdotal evidence rather than serious research.', 'adj. 轶事的， 趣闻的', '/ˌænɪk\'doutl | ,ænɪk\'dotl/', 'anecdotal', 6);
INSERT INTO `words` VALUES (8900, 'The book is full of amusing anecdotes about his life in Japan.', 'n. 轶事, 奇闻', '/\'ænikdəut | \'ænɪkdəʊt | \'ænɪkdot/', 'anecdote', 6);
INSERT INTO `words` VALUES (8901, 'Interference with the normal production of heme or globin leads to anemia.', 'n. 贫血, 贫血症', '/ə\'ni:miə | ə\'nimɪə/', 'anemia', 6);
INSERT INTO `words` VALUES (8902, 'What type of anesthetic will be used? How will it affect me?', 'n. 麻醉剂, 麻药', '/,ænis\'θetik | ænɪsθetɪk | ,ænɪs\'θɛtɪk/', 'anesthetic', 6);
INSERT INTO `words` VALUES (8903, 'the anguish of not knowing what had happened to her', 'n. 痛苦, 苦恼', '/\'æŋɡwiʃ | \'æŋgwɪʃ | \'æŋɡwɪʃ/', 'anguish', 6);
INSERT INTO `words` VALUES (8904, 'She let out an anguished cry.', 'adj. 痛苦的, 苦恼的', '/\'æŋɡwiʃt | \'æŋgwɪʃt/', 'anguished', 6);
INSERT INTO `words` VALUES (8905, 'a cubist painting with angular shapes', 'adj. 生硬的， 笨拙的； 有角的； 瘦削的', '/\'æŋgjələr | \'æŋɡjəlɚ/', 'angular', 6);
INSERT INTO `words` VALUES (8906, 'More serious consequence is to cause the joint layer between derma and skin to become thinner and thinner, skin can present anile evidence very quickly.', 'adj. 衰老的, 似老妪的', '/\'einail | \'eɪnaɪl/', 'anile', 6);
INSERT INTO `words` VALUES (8907, 'Doubt and animadvert are inner motive force of innovation of science and culture.', 'v. 批判, 非难', '/,ænimæd\'və:t | ,ænɪməd\'vɜːt | ,ænəmæd\'vɝt/', 'animadvert', 6);
INSERT INTO `words` VALUES (8908, 'animate beings', 'adj. 活的， 有生命的; v. 赋予生命', '/\'ænɪmeɪt | \'ænɪmet/', 'animate', 6);
INSERT INTO `words` VALUES (8909, 'Disney has returned to what it does best: making full-length animated feature films.', 'adj. 活生生的， 生动的', '/\'ænɪmeɪtɪd | \'ænə\'metɪd/', 'animated', 6);
INSERT INTO `words` VALUES (8910, NULL, 'n. 活泼, 有生气', '/,æni\'meiʃən | ænɪ\'meɪʃ(ə)n | ,ænɪ\'meʃən/', 'animation', 6);
INSERT INTO `words` VALUES (8911, 'When I came to have feelings just like those foreigners, I realized that on the inside, it felt more like animosity.', 'n. 仇恨, 憎恶', '/,æni\'mɔsəti | ,ænɪ\'mɒsɪtɪ | \'ænə\'mɑsəti/', 'animosity', 6);
INSERT INTO `words` VALUES (8912, 'Your animus toward him suggests that you are the wrong man for the job.', 'n. 敌意, 意图', '/\'æniməs | \'ænɪməs/', 'animus', 6);
INSERT INTO `words` VALUES (8913, 'slender ankles', 'n. [解]踝', '/\'æŋkl | \'æŋk(ə)l/', 'ankle', 6);
INSERT INTO `words` VALUES (8914, NULL, 'v. 使退火； 使加强， 使变硬', '/ə\'niːl | ə\'nil/', 'anneal', 6);
INSERT INTO `words` VALUES (8915, 'The Baltic republics were annexed by the Soviet Union in 1940.', 'v. 兼并， 附加', '/ə\'neks | əˈnɛks; æˈnɛks; (for n.) ˈænˌɛks/', 'annex', 6);
INSERT INTO `words` VALUES (8916, 'Just one of these bombs could annihilate a city the size of New York.', 'v. 消灭, 歼灭', '/ə\'naiə,leit | ə\'naɪɪleɪt | ə\'naɪəlet/', 'annihilate', 6);
INSERT INTO `words` VALUES (8917, 'an annotated edition of ‘Othello’', 'v. 注释, 评注', '/\'ænəuteit | \'ænəteɪt | \'ænə\'tet/', 'annotate', 6);
INSERT INTO `words` VALUES (8918, 'She retained a number of copies for further annotation.', 'n. 注解, 评注注解,注释', '/,ænəu\'teiʃən | ænə\'teɪʃ(ə)n | ˌænəˈteʃən/', 'annotation', 6);
INSERT INTO `words` VALUES (8919, 'All visitors to the apartment building must be announced.', 'v. 宣布， 发表； 通报…的到来', '/ə\'nauns | ə\'naʊns/', 'announce', 6);
INSERT INTO `words` VALUES (8920, 'What annoyed him most was that he had received no apology.', 'v. 惹恼； 打搅， 骚扰', '/ə\'nɔɪ/', 'annoy', 6);
INSERT INTO `words` VALUES (8921, 'Their marriage was annulled last year.', 'v. 废除, 取消, 废止', '/ə\'nʌl/', 'annul', 6);
INSERT INTO `words` VALUES (8922, 'So the left electrode will be the cathode as I have configured it, and the right electrode will be anode.', 'n. [电]阳极, 正极', '/\'ænəʊd | \'ænod/', 'anode', 6);
INSERT INTO `words` VALUES (8923, NULL, 'n. 止痛剂, 镇痛剂', '/\'ænəudain | \'ænədaɪn/', 'anodyne', 6);
INSERT INTO `words` VALUES (8924, 'a highly anomalous situation', 'adj. 不规则的, 反常的', '/ə\'nɔmələs | ə\'nɒm(ə)ləs | ə\'nɑmələs/', 'anomalous', 6);
INSERT INTO `words` VALUES (8925, 'The space shuttle had stopped transmitting data, a very serious anomaly for the mission.', 'n. 不规则, 异常的人或物', '/ə\'nɔməli | ə\'nɒm(ə)lɪ | ə\'nɑməli/', 'anomaly', 6);
INSERT INTO `words` VALUES (8926, 'Every step will be taken to preserve your anonymity.', 'n. 匿名, 作者不明(或不详)', '/,ænə\'niməti | ænə\'nɪmɪtɪ | \'ænə\'nɪməti/', 'anonymity', 6);
INSERT INTO `words` VALUES (8927, 'the anonymous author of a collection of poems', 'adj. 匿名的', '/ə\'nɔniməs | ə\'nɒnɪməs | ə\'nɑnəməs/', 'anonymous', 6);
INSERT INTO `words` VALUES (8928, 'The impetus for its inclusion comes in part from a 2007 study which suggests that it is as common in the US as anorexia and bulimia combined.', 'n. 食欲减退, 厌食', '/,ænə\'reksiə | ,ænə\'reksɪə | \'ænə\'rɛksɪə/', 'anorexia', 6);
INSERT INTO `words` VALUES (8929, 'Conclusion EDT can protect PC12 cells from anoxia and ischemic injury.', 'n. [医]缺氧症', '/æ\'nɔksiə | æ\'nɒksɪə | æn\'ɑksɪə/', 'anoxia', 6);
INSERT INTO `words` VALUES (8930, 'There is still much antagonism between environmental groups and the oil companies.', 'n. 对抗(状态), 对抗性', '/æn\'tæɡənizəm | æn\'tæg(ə)nɪz(ə)m | æn\'tæɡənɪzəm/', 'antagonism', 6);
INSERT INTO `words` VALUES (8931, 'Spassky had never previously lost to his antagonist.', 'n. 敌手, 对手', '/æn\'tæɡənist | æn\'tæg(ə)nɪst | æn\'tæɡənɪst/', 'antagonist', 6);
INSERT INTO `words` VALUES (8932, 'an antagonistic attitude', 'adj. 敌对的， 对抗性的', '/ænˌtægə\'nɪstɪk | æn,tæɡə\'nɪstɪk/', 'antagonistic', 6);
INSERT INTO `words` VALUES (8933, 'Do not antagonize your customers.', 'v. 使…敌对； 与…对抗', '/æn\'tægənaɪz | æn\'tæɡənaɪz/', 'antagonize', 6);
INSERT INTO `words` VALUES (8934, 'Methods of GM(1,1) gray prediction, Bayesian and antecedence index were employed.', 'n. 先行, 先前', '/,ænti\'si:dəns,-dənsi | ,æntɪ\'siːdəns | ,æntə\'sidns/', 'antecedence', 6);
INSERT INTO `words` VALUES (8935, 'Some patients state that lesions develop at the site of antecedent trauma.', 'adj. 先行的; n. 前事；祖先', '/ˌæntɪ\'siːdnt | \'æntə\'sidnt/', 'antecedent', 6);
INSERT INTO `words` VALUES (8936, 'The economic troubles antedate the current administration.', 'n. 比正确日期早的日期', '/,ænti\'deit, \'æntideit | æntɪ\'deɪt; \'æntɪdeɪt | ,æntɪ\'det/', 'antedate', 6);
INSERT INTO `words` VALUES (8937, 'antediluvian ideas about women', 'adj. (《圣经》中所说的)大洪水前的, 上古的, 古风的', '/,æntidi\'lu:viən | ,æntɪdɪ\'luːvɪən | ,æntɪdɪ\'luvɪən/', 'antediluvian', 6);
INSERT INTO `words` VALUES (8938, 'an antenatal clinic', 'adj. [医]出生前的', '/,ænti\'neitəl | æntɪ\'neɪt(ə)l | \'æntə\'netl/', 'antenatal', 6);
INSERT INTO `words` VALUES (8939, 'television antennas', 'n. 天线', '/æn\'tenə | æn\'tɛnə/', 'antenna', 6);
INSERT INTO `words` VALUES (8940, 'anterior vertebrae', 'adj. 前面的, 在前的', '/æn\'tiəriə | æn\'tɪərɪə | æn\'tɪrɪɚ/', 'anterior', 6);
INSERT INTO `words` VALUES (8941, 'The band played the Czech anthem.', 'n. 圣歌, 赞美诗', '/\'ænθəm/', 'anthem', 6);
INSERT INTO `words` VALUES (8942, 'an anthology of American literature', 'n. 诗选, 文选', '/æn\'θɔlədʒi | æn\'θɒlədʒɪ | æn\'θɑlədʒi/', 'anthology', 6);
INSERT INTO `words` VALUES (8943, 'And it has been confirmed from invertebrates (like crayfish and beetles) till the anthropoid (man like) apes.', 'n. 类人猿', '/\'ænθrəupɔid | \'ænθrəpɒɪd/', 'anthropoid', 6);
INSERT INTO `words` VALUES (8944, '\"In anthropology, you can\'t equate third gender with homosexuality,\" he said.', 'n. 人类学', '/,ænθrə\'pɔlədʒi | ,ænθrə\'pɒlədʒɪ | \'ænθrə\'pɑlədʒi/', 'anthropology', 6);
INSERT INTO `words` VALUES (8945, 'Your doctor may prescribe antibiotics.', 'n. 抗生素', '/,æntibai\'ɔtik | ,æntɪbaɪ\'ɒtɪk | ,æntɪbaɪ\'ɑtɪk; ˌæntaɪ-/', 'antibiotic', 6);
INSERT INTO `words` VALUES (8946, 'Such women carry antibodies which make their blood more likely to clot during pregnancy.', 'n. 抗体', '/\'ænti,bɔdi | \'æntɪbɒdɪ | \'æntɪ\'bɑdi/', 'antibody', 6);
INSERT INTO `words` VALUES (8947, NULL, 'n. 丑角, 滑稽动作', '/\'æntɪk/', 'antic', 6);
INSERT INTO `words` VALUES (8948, 'Sales are better than anticipated.', 'v. 预期, 期望, 过早使用, 先人一着, 占先', '/æn\'tisipeit | æn\'tɪsɪpeɪt | æn\'tɪsə\'pet/', 'anticipate', 6);
INSERT INTO `words` VALUES (8949, 'Finally, Milton has revised and undone the anticipatory logic of the great career narrative.', 'adj. 预料的, 预想的', '/æn\'tisipeitəri | æn\'tɪsɪpə,t(ə)rɪ | æn\'tɪsəpə,tori/', 'anticipatory', 6);
INSERT INTO `words` VALUES (8950, NULL, 'adj. 突减的', '/ˌæntiklaɪ\'mæktɪk | ,æntɪklaɪ\'mæktɪk/', 'anticlimactic', 6);
INSERT INTO `words` VALUES (8951, 'We’re all growing tired of his childish antics.', 'n. 滑稽的动作, 古怪的姿态', '/\'æntiks | \'æntɪks/', 'antics', 6);
INSERT INTO `words` VALUES (8952, 'When he returned, he noticed their sickness and prepared an antidote.', 'n. [医]解毒剂, 矫正方法', '/\'æntidəut | \'æntɪdəʊt | \'æntɪdot/', 'antidote', 6);
INSERT INTO `words` VALUES (8953, 'Objective To explore the antifebrile effects and changes of toxicity after compatibility of both compound isatis leaf injection and compound amidopyrine injection.', 'adj. 退热的, 解热的', '/,æntɪ\'fiːbraɪl | ,æntɪ\'fibrɪl/', 'antifebrile', 6);
INSERT INTO `words` VALUES (8954, 'Lassa fever is diagnosed by detection of Lassa antigen, anti-Lassa antibodies, or virus isolation techniques.', 'n. <美>[免疫]抗原', '/\'æntidʒən | \'æntɪdʒ(ə)n | \'æntɪdʒən/', 'antigen', 6);
INSERT INTO `words` VALUES (8955, 'And the education that move and we exist in reality is antipathetic bewildering phenomenon.', 'adj. 讨厌的, 嫌恶的, 格格不入的', '/,æntipə\'θetik,-kəl | ,æntɪpə\'θetɪk | æn,tɪpə\'θɛtɪk/', 'antipathetic', 6);
INSERT INTO `words` VALUES (8956, '...the voting public\'s antipathy toward the president.', 'n. 反感， 厌恶', '/æn\'tɪpəθi/', 'antipathy', 6);
INSERT INTO `words` VALUES (8957, NULL, 'n. 古物研究， 好古癖', '/,ænti\'kwεəriənizəm | ˌænti\'kweəriənizəm/', 'antiquarianism', 6);
INSERT INTO `words` VALUES (8958, 'antiquated laws', 'adj. 陈旧的', '/\'æntikweitid | \'æntɪkweɪtɪd | \'æntɪkwetɪd/', 'antiquated', 6);
INSERT INTO `words` VALUES (8959, 'an antique rosewood desk', 'adj. 古时的，古老的; n. 古物， 古董', '/æn\'tiːk | æn\'tik/', 'antique', 6);
INSERT INTO `words` VALUES (8960, 'a building of great antiquity', 'n. 古老； 古人； 古迹', '/æn\'tɪkwəti/', 'antiquity', 6);
INSERT INTO `words` VALUES (8961, 'Turmeric -- the herb that gives a curry its distinctive yellow color -- is also an antiseptic with anti-inflammatory properties.', 'adj. 防腐的, 杀菌的, 消过毒的', '/,ænti\'septik | æntɪ\'septɪk | ˌæntiˈseptɪk/', 'antiseptic', 6);
INSERT INTO `words` VALUES (8962, 'The antithesis of the Middle Eastern buyer is the Japanese.', 'n. 对立面', '/æn\'tiθisis | æn\'tɪθəsɪs/', 'antithesis', 6);
INSERT INTO `words` VALUES (8963, NULL, 'adj. 正相反的, 对立的', '/,ænti\'θetik,-kəl/', 'antithetic', 6);
INSERT INTO `words` VALUES (8964, 'Their priorities are antithetical to those of environmentalists.', 'adj. 相反的； 对立的', '/ˌæntɪ\'θetɪkl | ,æntɪ\'θɛtɪkl/', 'antithetical', 6);
INSERT INTO `words` VALUES (8965, 'Each has a snug mezzanine area and an antler-fenced balcony about eight metres above ground.', 'n. 鹿角, 茸角', '/\'æntlə | \'æntlɚ/', 'antler', 6);
INSERT INTO `words` VALUES (8966, NULL, 'adj. [动]无尾的', '/ə\'njuərəs/', 'anurous', 6);
INSERT INTO `words` VALUES (8967, 'Scientists recently used a diamond anvil like this one to squeeze tiny samples of metallic glass.', 'n. [解]砧骨', '/\'ænvil | \'ænvɪl/', 'anvil', 6);
INSERT INTO `words` VALUES (8968, 'And because it is from a reconstituted aorta, the doctors do not need to administer anti-rejection drugs, which react to cancer treatments.', 'n. 大动脉', '/ei\'ɔ:tə | eɪ\'ɔːtə | e\'ɔrtə/', 'aorta', 6);
INSERT INTO `words` VALUES (8969, 'She felt too apathetic even to move.', 'adj. 缺乏兴趣的, 缺乏感情的, 无动于衷的', '/,æpə\'θetik | æpə\'θetɪk | ,æpə\'θɛtɪk/', 'apathetic', 6);
INSERT INTO `words` VALUES (8970, 'The campaign failed because of public apathy.', 'n. 缺乏感情或兴趣, 冷漠', '/\'æpəθi | \'æpəθɪ/', 'apathy', 6);
INSERT INTO `words` VALUES (8971, 'The rise of white wine as an aperitif can be traced to this date, and the co-operative of Plaimont – producers of this wine – were pioneers in the field.', 'n. 开胃酒', '/ə,peri\'ti:ʃ | ə\'perɪtiːf; ə,perɪ\'tiːf | ə,pɛrə\'tif/', 'aperitif', 6);
INSERT INTO `words` VALUES (8972, 'Through the aperture he could see daylight.', 'n. 孔, 穴, 缝隙, (照相机, 望远镜等的)光圈, 孔径', '/\'æpə,tjuə | \'æpətʃə; -tj(ʊ)ə | \'æpətʃɚ/', 'aperture', 6);
INSERT INTO `words` VALUES (8973, 'the apex of the roof', 'n. 顶点', '/\'eipeks | \'eɪpeks | \'epɛks/', 'apex', 6);
INSERT INTO `words` VALUES (8974, 'There are disorders of language like aphasia.', 'n. 失语症', '/ə\'feizjə | ə\'feɪzɪə | ə\'feʒɪə/', 'aphasia', 6);
INSERT INTO `words` VALUES (8975, 'That\'s more than a folksy aphorism when it comes to infectious diseases.', 'n. 格言, 警语, 谚语', '/\'æfərizəm | \'æfərɪz(ə)m | \'æfərɪzəm/', 'aphorism', 6);
INSERT INTO `words` VALUES (8976, 'We went to an apiary and got real sheets of used bees wax.', 'n. 养蜂场, 蜂房', '/\'eipjəri | \'eɪpɪərɪ | \'epɪɛri/', 'apiary', 6);
INSERT INTO `words` VALUES (8977, 'In Asia, apiculture is an important activity in Burma, Bangladesh and India.', 'n. 养蜂', '/\'eipikʌltʃə | \'eɪpɪ,kʌltʃə | \'epɪkʌltʃɚ/', 'apiculture', 6);
INSERT INTO `words` VALUES (8978, 'Ms Sharpe handled their questions with great aplomb.', 'n. 沉着, 泰然, 垂直', '/ə\'plɔm | ə\'plɒm | ə\'plɑm/', 'aplomb', 6);
INSERT INTO `words` VALUES (8979, '...a gloomy and apocalyptic vision of a world hastening toward ruin.', 'adj. 启示录的, 天启的', '/ə,pɔkə\'liptik | ə\'pɑkə\'lɪptɪk/', 'apocalyptic', 6);
INSERT INTO `words` VALUES (8980, 'Seafarers have long returned with tales — often dismissed as apocryphal — of the ocean abruptly reaching up and snatching at anything in its path.', 'adj. 伪经的,假冒的', '/ə\'pɔkrifəl | ə\'pɒkrɪf(ə)l | əˈpɒkrəfəl/', 'apocryphal', 6);
INSERT INTO `words` VALUES (8981, 'If this is an ellipse around the Earth, then this would be perigee and this would be apogee.', 'n. 远地点', '/\'æpəudʒi: | \'æpədʒiː | \'æpədʒi/', 'apogee', 6);
INSERT INTO `words` VALUES (8982, 'a group of apolitical young professional people', 'adj. 不关心政治的', '/,eipə\'litikəl | eɪpə\'lɪtɪk(ə)l | ,epə\'lɪtɪkl/', 'apolitical', 6);
INSERT INTO `words` VALUES (8983, 'She gave me an apologetic smile .', 'adj. 道歉的, 认错的, 辩护的', '/ə,pɔlə\'dʒetik | əpɒlə\'dʒetɪk | ə,pɑlə\'dʒɛtɪk/', 'apologetic', 6);
INSERT INTO `words` VALUES (8984, 'I’m so sorry, I do apologize.', 'v. 道歉； 辩解', '/ə\'pɑːlədʒaɪz | ə\'pɑlədʒaɪz/', 'apologize', 6);
INSERT INTO `words` VALUES (8985, 'Edward can’t be here today, but he sends his apologies .', 'n. (为某种思想, 宗教, 哲学等)辩解, 道歉', '/ə\'pɔlədʒi | ə\'pɒlədʒɪ | ə\'pɑlədʒi/', 'apology', 6);
INSERT INTO `words` VALUES (8986, 'More to the point, her father would be apoplectic at the idea.', 'n. 患中风者', '/,æpəu\'plektik,-kəl | ,æpə\'plektɪk | ,æpə\'plɛktɪk/', 'apoplectic', 6);
INSERT INTO `words` VALUES (8987, '...a charge of apostasy.', 'n. 变节, 背教, 脱党', '/ə\'pɔstəsi | ə\'pɒstəsɪ/', 'apostasy', 6);
INSERT INTO `words` VALUES (8988, 'Extremes meet. the most fur ious anarchist become the most barefaced apostate.', 'n. 变节者, 背教者, 脱党者', '/ə\'pɔsteit | /əˈpɒsteɪt/ | /əˈpɑːsteɪt//', 'apostate', 6);
INSERT INTO `words` VALUES (8989, NULL, 'n. 省略符号, 呼语', '/ə\'pɔstrəfi | ə\'pɒstrəfɪ | ə\'pɑstrəfi/', 'apostrophe', 6);
INSERT INTO `words` VALUES (8990, 'The Oriental in Bangkok is the apotheosis of the grand hotel.', 'n. 尊为神, 神化, 颂扬, 崇拜, 典范', '/ə,pɔθi\'əusis | ə,pɒθɪ\'əʊsɪs | ə,pɑθɪ\'osɪs/', 'apotheosis', 6);
INSERT INTO `words` VALUES (8991, 'The way we kill animals appals a lot of people.', 'v. 惊骇', '/ə\'pɔ:l | ə\'pɔːl | ə\'pɔl/', 'appal', 6);
INSERT INTO `words` VALUES (8992, NULL, 'v. 使惊骇， 使胆寒', '/ə\'pɔːl | ə\'pɔl/', 'appall', 6);
INSERT INTO `words` VALUES (8993, 'She suffered appalling injuries.', 'adj. 令人震惊的, 骇人听闻的', '/ə\'pɔ:liŋ | ə\'pɔːlɪŋ | ə\'pɔlɪŋ/', 'appalling', 6);
INSERT INTO `words` VALUES (8994, 'She looked lovely, despite her strange apparel.', 'n. 衣服, 装饰', '/ə\'pærəl | ə\'pær(ə)l/', 'apparel', 6);
INSERT INTO `words` VALUES (8995, 'He stared at the strange apparition before him.', 'n. 离奇出现的东西, (尤指)鬼怪, 幽灵, 幻影', '/,æpə\'riʃən | æpə\'rɪʃ(ə)n | ,æpə\'rɪʃən/', 'apparition', 6);
INSERT INTO `words` VALUES (8996, 'The girl’s family have made a public appeal for help to try and catch her killer.', 'n. 请求, 呼吁, 上诉, 吸引力, 要求', '/ə\'pi:l | ə\'piːl | ə\'pil/', 'appeal', 6);
INSERT INTO `words` VALUES (8997, 'The city offers an appealing combination of sporting and cultural events.', 'adj. 吸引人的, 哀诉似的, 恳求似的', '/ə\'pi:liŋ | ə\'piːlɪŋ | əˈpiːlɪŋ/', 'appealing', 6);
INSERT INTO `words` VALUES (8998, 'They attempted to appease international opposition by promising to hold talks.', 'v. 平息, 安抚, 缓和, 使满足', '/ə\'pi:z | ə\'piːz | ə\'piz/', 'appease', 6);
INSERT INTO `words` VALUES (8999, 'One suggestion is that blushing started out as a simple appeasement ritual: a way to show dominant members of the group that we submit to their authority.', 'n. 缓和', '/ə\'pi:zmənt | ə\'piːzm(ə)nt | ə\'pizmənt/', 'appeasement', 6);
INSERT INTO `words` VALUES (9000, 'He earned the appellation \"rebel priest.\"', 'n. 名称, 称呼', '/,æpə\'leiʃən | ,æpə\'leɪʃ(ə)n | ,æpə\'leʃən/', 'appellation', 6);
INSERT INTO `words` VALUES (9001, 'Upon marriage, a woman automatically lost most of her legal rights and became an appendage of her husband.', 'n. 附加物, 附属肢体', '/ə\'pendidʒ | ə\'pendɪdʒ | ə\'pɛndɪdʒ/', 'appendage', 6);
INSERT INTO `words` VALUES (9002, 'Her husband always had a huge appetite.', 'n. 食欲, 胃口, 欲望, 爱好', '/\'æpitait | \'æpɪtaɪt/', 'appetite', 6);
INSERT INTO `words` VALUES (9003, 'an appetizing aroma', 'adj. 美味可口的, 促进食欲的', '/\'æpitaiziŋ | \'æpə\'taɪzɪŋ/', 'appetizing', 6);
INSERT INTO `words` VALUES (9004, 'The audience applauded loudly.', 'v. 鼓掌； 称赞', '/ə\'plɔːd | ə\'plɔd/', 'applaud', 6);
INSERT INTO `words` VALUES (9005, 'Among which, separating degree and repeatability are more practical parameters in system applicability test.', 'n. 适用性， 适应性', '/əˌplɪkə\'bɪləti | ,æplɪkə\'bɪləti/', 'applicability', 6);
INSERT INTO `words` VALUES (9006, 'What is a reasonable standard for one family is not applicable for another.', 'adj. 可适用的, 可应用的', '/\'æplikəbl, ə\'plikə- | ə\'plɪkəb(ə)l; \'æplɪk- | \'æplɪkəbl/', 'applicable', 6);
INSERT INTO `words` VALUES (9007, 'We have had lots of applicants for these positions.', 'n. 申请人', '/\'æplɪkənt/', 'applicant', 6);
INSERT INTO `words` VALUES (9008, 'These ideas are often difficult to apply in practice.', 'v. 应用； 适用', '/ə\'plaɪ/', 'apply', 6);
INSERT INTO `words` VALUES (9009, 'officials appointed by the government', 'v. 任命， 指定； 约定', '/ə\'pɔɪnt/', 'appoint', 6);
INSERT INTO `words` VALUES (9010, 'It’s not easy to apportion blame (= say who deserves to be blamed ) when a marriage breaks up.', 'v. 分配', '/ə\'pɔːrʃn | ə\'pɔrʃən/', 'apportion', 6);
INSERT INTO `words` VALUES (9011, 'Recent events have made his central theme even more apposite.', 'adj. 适当的', '/\'æpəuzit | \'æpəzɪt/', 'apposite', 6);
INSERT INTO `words` VALUES (9012, 'Greenpeace has been invited to appraise the environmental costs of such an operation.', 'v. 评价， 鉴定', '/ə\'preɪz | ə\'prez/', 'appraise', 6);
INSERT INTO `words` VALUES (9013, 'There’s no appreciable change in the patient’s condition.', 'adj. 可感知的, 可评估的', '/ə\'pri:ʃiəbl | ə\'priːʃəb(ə)l; -ʃɪə- | ə\'priʃəbl/', 'appreciable', 6);
INSERT INTO `words` VALUES (9014, 'Thanks ever so much for your help, I really appreciate it.', 'v. 欣赏； 感激', '/ə\'priːʃieɪt | ə\'priʃɪet/', 'appreciate', 6);
INSERT INTO `words` VALUES (9015, 'There is a murmur of appreciative laughter.', 'adj. a欣赏的, 有欣赏力的, 表示感激的, 承认有价值的', '/ə\'pri:ʃiətiv | ə\'priːʃətɪv | ə\'priʃətɪv/', 'appreciative', 6);
INSERT INTO `words` VALUES (9016, 'She\'d love to tell Comus something about chastity, but he has neither ear nor soul to apprehend the sublime notion and high mystery.', 'v. 领会理解', '/,æpri\'hend | æprɪ\'hend | ,æprɪ\'hɛnd/', 'apprehend', 6);
INSERT INTO `words` VALUES (9017, 'It reflects real anger and apprehension about the future.', 'n. 理解, 忧惧, 拘捕', '/,æpri\'henʃən | æprɪ\'henʃ(ə)n | ,æprɪ\'hɛnʃən/', 'apprehension', 6);
INSERT INTO `words` VALUES (9018, 'Some had apprehensive looks on their faces.', 'adj. 有理解力的', '/,æpri\'hensiv | æprɪ\'hensɪv | ,æprɪ\'hɛnsɪv/', 'apprehensive', 6);
INSERT INTO `words` VALUES (9019, 'She works in the hairdresser’s as an apprentice.', 'n. 学徒', '/ə\'prentɪs | ə\'prɛntɪs/', 'apprentice', 6);
INSERT INTO `words` VALUES (9020, 'Have customers been fully apprised of the advantages?', 'v. 通知', '/ə\'praiz | ə\'praɪz/', 'apprise', 6);
INSERT INTO `words` VALUES (9021, 'As I approached the house, I noticed a light on upstairs.', 'v. 接近，靠近；着手处理; n. 方法', '/ə\'proutʃ | ə\'protʃ/', 'approach', 6);
INSERT INTO `words` VALUES (9022, 'The head teacher is very approachable.', 'adj. 可接近的, 平易近人的, 亲切的', '/ə\'prəutʃəbl | ə\'prəʊtʃəb(ə)l | ə\'protʃəbl/', 'approachable', 6);
INSERT INTO `words` VALUES (9023, 'Maybe he is shy, so why not show him your confidence and courage by approaching him first?', 'adj. 接近的， 逼近的', '/ə\'proutʃɪŋ | ə\'protʃ/', 'approaching', 6);
INSERT INTO `words` VALUES (9024, 'I anticipate nothing but grateful approbation .', 'n. 官方批准, 认可, 嘉许', '/,æprəu\'beiʃən | ,æprə\'beɪʃ(ə)n | \'æprə\'beʃən/', 'approbation', 6);
INSERT INTO `words` VALUES (9025, 'The result revealed the approbatory degree of teachers and students in English modular teaching to be quite high in vocational college, but the degree of value for each teaching module is different.', 'adj. 承认的, 认可的, 赞赏的', '/,æprəu\'beitəri, ə\'prəubətəri/', 'approbatory', 6);
INSERT INTO `words` VALUES (9026, 'The timing of the announcement was particularly appropriate .', 'adj. 适当的', '/ə\'prəʊprɪət | əˈpropriɪt/', 'appropriate', 6);
INSERT INTO `words` VALUES (9027, 'The government raised defence appropriations by 12 percent.', 'n. 据为己有, 占有, 挪用(只指定用途的一笔), 拨款', '/əprəupri\'eiʃən | ə,prəʊprɪ\'eɪʃ(ə)n | ə,proprɪ\'eʃən/', 'appropriation', 6);
INSERT INTO `words` VALUES (9028, 'What is the approximate number of students in each class?', 'adj. 近似的, 大约的', '/ə\'prɔksimit | ə\'prɒksɪmət | ə\'prɑksɪmət/', 'approximate', 6);
INSERT INTO `words` VALUES (9029, 'She wiped her eyes with her apron.', 'n. 围裙, 外表或作用类似围裙的东西, [机]挡板, 护坦', '/\'eiprən | \'eɪpr(ə)n | \'eprən/', 'apron', 6);
INSERT INTO `words` VALUES (9030, 'He had nothing to say apropos of the latest developments.', 'adj&adv. 适当的)； 有关(with reference to； regarding)', '/ˌæprə\'pou | ,æprə\'po/', 'apropos', 6);
INSERT INTO `words` VALUES (9031, '‘Love at first sight’ is a very apt description of how he felt when he saw her.', 'adj. 易于…的； 恰当的', '/æpt/', 'apt', 6);
INSERT INTO `words` VALUES (9032, 'He drifted into publishing and discovered an aptitude for working with accounts.', 'n. 适宜； 才能， 资质', '/\'æptɪtuːd | ˈæptɪˌtud, -ˌtjud/', 'aptitude', 6);
INSERT INTO `words` VALUES (9033, 'an aquatic plant', 'adj. 水的, 水上的, 水生的, 水栖的', '/ə\'kwætik | ə\'kwætɪk; -\'kwɒt- | ə\'kwætɪk/', 'aquatic', 6);
INSERT INTO `words` VALUES (9034, '...a nationwide system of aqueducts to carry water to the arid parts of this country.', 'n. 沟渠, 导水管', '/\'ækwidʌkt | \'ækwɪdʌkt | \'ækwɪ\'dʌkt/', 'aqueduct', 6);
INSERT INTO `words` VALUES (9035, 'He had a thin aquiline nose and deep-set brown eyes.', 'adj. 鹰的, 象鹰的, 弯曲的', '/\'ækwilain | \'ækwɪlaɪn/', 'aquiline', 6);
INSERT INTO `words` VALUES (9036, 'Not much has changed since the 1920s, and walking into the lobby, with ornate Ottoman furniture and arabesque tiles, is like stepping into an Agatha Christie novel.', 'n. 阿拉伯式图饰, 蔓藤花纹', '/,ærə\'besk | ,ærə\'bɛsk/', 'arabesque', 6);
INSERT INTO `words` VALUES (9037, 'arable farming', 'adj. 可耕的, 适于耕种的', '/\'ærəbl | \'ærəb(ə)l/', 'arable', 6);
INSERT INTO `words` VALUES (9038, 'The European Court of Justice will be the final arbiter (= make the final decision ) in the dispute.', 'n. 仲裁者, 判优器', '/\'ɑ:bitə | \'ɑːbɪtə | \'ɑrbɪtɚ/', 'arbiter', 6);
INSERT INTO `words` VALUES (9039, 'an arbitrary decision', 'adj. 任意的, 武断的, 独裁的, 专断的', '/\'ɑ:bitrəri | \'ɑːbɪt(rə)rɪ | ˈɑːrbətreri/', 'arbitrary', 6);
INSERT INTO `words` VALUES (9040, 'He arbitrates between investors and members of the association.', 'v. 作出公断', '/\'ɑ:bitreit | \'ɑːbɪtreɪt | \'ɑrbɪtret/', 'arbitrate', 6);
INSERT INTO `words` VALUES (9041, 'The award rendered by: the arbitrator (s) shall be final and binding upon both parties.', 'n. 仲裁人, 公断者', '/\'ɑ:bitreitə | \'ɑːbɪtreɪtə | \'ɑrbə\'tretɚ/', 'arbitrator', 6);
INSERT INTO `words` VALUES (9042, '...arboreal marsupials which resemble monkeys.', 'adj. 树的, 乔木的, 树栖的', '/ɑ:\'bɔ:riəl | ɑː\'bɔːrɪəl | ɑr\'bɔrɪəl/', 'arboreal', 6);
INSERT INTO `words` VALUES (9043, 'In fact, some people were assigned to walk in the arboretum during a Michigan winter.', 'n. 树园, 植物园', '/,ɑ:bə\'ri:təm | ,ɑːbə\'riːtəm | ,ɑrbə\'ritəm/', 'arboretum', 6);
INSERT INTO `words` VALUES (9044, 'Until a few months ago few people outside the arcane world of contemporary music had heard of Gorecki.', 'adj. 神秘的, 不可思议的', '/ɑ:\'kein | ɑː\'keɪn | ɑr\'ken/', 'arcane', 6);
INSERT INTO `words` VALUES (9045, 'Just who made the tools is unclear from the archaeological evidence alone, though our relative Homo erectus is identified as the likely creator of at least the Acheulian tools.', 'adj. 考古学的', '/,ɑ:kiə\'lɔdʒikəl | ˌɑːrkiə\'lɑːdʒɪkl/', 'archaeological', 6);
INSERT INTO `words` VALUES (9046, 'He specializes in archaeology.', 'n. 考古学', '/,ɑ:ki\'ɔlədʒi | ,ɑːkɪ\'ɒlədʒɪ | ,ɑrkɪ\'ɑlədʒi/', 'archaeology', 6);
INSERT INTO `words` VALUES (9047, 'archaic words', 'adj. 古老的', '/ɑːr\'keɪɪk | ɑr\'keɪk/', 'archaic', 6);
INSERT INTO `words` VALUES (9048, 'The best archer would be awarded a golden arrow.', 'n. 射手, 弓术家, [天]人马星座', '/\'ɑ:tʃə | \'ɑːtʃə | \'ɑrtʃɚ/', 'archer', 6);
INSERT INTO `words` VALUES (9049, NULL, 'adv. 典型地', '/\'ɑːrki\'taɪpəli/', 'archetypally', 6);
INSERT INTO `words` VALUES (9050, 'He came to this country 20 years ago and is the archetype of the successful Asian businessman.', 'n. 原型', '/\'ɑ:kitaip | \'ɑːkɪtaɪp | \'ɑrkə\'taɪp/', 'archetype', 6);
INSERT INTO `words` VALUES (9051, NULL, 'n. 群岛, 多岛海', '/,ɑ:ki\'peləɡəu | ,ɑːkɪ\'peləgəʊ | \'ɑrkə\'pɛlə\'go/', 'archipelago', 6);
INSERT INTO `words` VALUES (9052, 'James Madison was the principal architect of the constitution.', 'n. 建筑师', '/\'ɑːrkɪtekt | \'ɑrkɪtɛkt/', 'architect', 6);
INSERT INTO `words` VALUES (9053, '...Tibet\'s architectural heritage.', 'adj. 建筑上的； 建筑学的', '/ˌɑːrkɪ\'tektʃərəl | ,ɑrkɪ\'tɛktʃərəl/', 'architectural', 6);
INSERT INTO `words` VALUES (9054, 'an archive of the writer’s unpublished work', 'n. 档案室', '/\'ɑːrkaɪv | \'ɑrkaɪv/', 'archive', 6);
INSERT INTO `words` VALUES (9055, '...the State Library\'s archives.', 'n. 档案, 公文, 档案室, 案卷保管处', '/\'a:kaivz/', 'archives', 6);
INSERT INTO `words` VALUES (9056, 'an ardent supporter of free trade', 'adj. 热心的, 热情洋溢的, 激烈的, 燃烧般的', '/\'ɑ:dənt | \'ɑːd(ə)nt | \'ɑrdnt/', 'ardent', 6);
INSERT INTO `words` VALUES (9057, NULL, 'n. 热诚, 情欲, 激情, 热情, 炽热', '/\'ɑ:də | \'ɑːdə | \'ɑrdɚ/', 'ardor', 6);
INSERT INTO `words` VALUES (9058, '...a long, hot and arduous trip.', 'adj. 费劲的, 辛勤的, 险峻的', '/\'ɑ:djuəs | \'ɑːdjʊəs | \'ɑrdʒuəs/', 'arduous', 6);
INSERT INTO `words` VALUES (9059, 'a sports arena', 'n. 竞技场, 舞台', '/ə\'ri:nə | ə\'riːnə | ə\'rinə/', 'arena', 6);
INSERT INTO `words` VALUES (9060, 'He quickly becomes argumentative after a few drinks.', 'adj. 好争辩的， 好争吵的', '/ˌɑːrgju\'mentətɪv | ,ɑrɡju\'mɛntətɪv/', 'argumentative', 6);
INSERT INTO `words` VALUES (9061, 'Take any popular song and compare it to any aria by the Italian opera composer Vincenzo Bellini (1801-1835), for example.', 'n. 独唱曲, 咏叹调, 唱腔', '/\'ɑ:riə | \'ɑːrɪə | \'ɑrɪə/', 'aria', 6);
INSERT INTO `words` VALUES (9062, 'Water from the Great Lakes is pumped to arid regions .', 'adj. 干旱的； 枯燥的', '/\'ærɪd/', 'arid', 6);
INSERT INTO `words` VALUES (9063, 'dukes, earls, and other members of the aristocracy', 'n. 贵族； 贵族政府， 贵族统治', '/ˌærɪ\'stɑːkrəsi | ,ærɪ\'stɑkrəsi/', 'aristocracy', 6);
INSERT INTO `words` VALUES (9064, '...a wealthy southern aristocrat.', 'n. 贵族', '/\'æristəkræt, ə\'ristə- | \'ærɪstəkræt; ə\'rɪst- | ə\'rɪstəkræt/', 'aristocrat', 6);
INSERT INTO `words` VALUES (9065, 'an aristocratic family', 'adj. 贵族的', '/əˌrɪstə\'krætɪk | ə,rɪstə\'krætɪk/', 'aristocratic', 6);
INSERT INTO `words` VALUES (9066, '...teaching the basics of reading, writing and arithmetic.', 'n. 算术, 算法', '/ə\'riθmətik, ,æriθ\'metik | ə\'rɪθmətɪk/', 'arithmetic', 6);
INSERT INTO `words` VALUES (9067, NULL, 'n. 方舟, 约柜, 箱子', '/ɑ:k | ɑːk | ɑrk/', 'ark', 6);
INSERT INTO `words` VALUES (9068, 'This armada of robots will be our eyes, ears, arms and legs in space, in the air, and on the ground, capable of responding to their environment without us, to explore and embrace the unknown.', 'n. 舰队', '/ɑ:\'mɑ:də/', 'armada', 6);
INSERT INTO `words` VALUES (9069, 'Finally, the Bolsheviks signed an armistice with Germany.', 'n. 停战, 休战', '/\'ɑ:mistis | \'ɑːmɪstɪs | \'ɑrmɪstɪs/', 'armistice', 6);
INSERT INTO `words` VALUES (9070, 'Thee first \"standard\" battleship of the Tech Tree armored according to the \"all or nothing\" concept.', 'adj. 披甲的， 装甲的', '/\'ɑːrmərd | \'ɑrmɚd/', 'armored', 6);
INSERT INTO `words` VALUES (9071, 'the aroma of fresh coffee', 'n. 芳香, 香气, 香味', '/ə\'rəumə | ə\'rəʊmə | ə\'romə/', 'aroma', 6);
INSERT INTO `words` VALUES (9072, 'aromatic oils', 'adj. 芬芳的', '/,ærəu\'mætik | ærə\'mætɪk | ,ærə\'mætɪk/', 'aromatic', 6);
INSERT INTO `words` VALUES (9073, 'The smell of frying bacon aroused his hunger.', 'v. 唤醒； 激发', '/ə\'rauz | ə\'raʊz/', 'arouse', 6);
INSERT INTO `words` VALUES (9074, 'He was arraigned for criminally abetting a traitor.', 'v. 提问, 传讯, 责难', '/ə\'rein | ə\'reɪn/', 'arraign', 6);
INSERT INTO `words` VALUES (9075, 'What arrant nonsense!', 'adj. 完全的， 彻底的； 极坏的， 臭名昭著的', '/\'ærənt/', 'arrant', 6);
INSERT INTO `words` VALUES (9076, 'We visited the local markets and saw wonderful arrays of fruit and vegetables.', 'v. 部署; n. 陈列； 大批', '/ə\'reɪ | ə\'re/', 'array', 6);
INSERT INTO `words` VALUES (9077, 'Many people are in arrears with their rent.', 'n. 到期未付款, 欠帐', '/ə\'riəz | ə\'rɪəz | ə\'rɪrz/', 'arrears', 6);
INSERT INTO `words` VALUES (9078, 'He was arrested and charged with murder.', 'v. 逮捕； 阻止， 制止', '/ə\'rest | ə\'rɛst/', 'arrest', 6);
INSERT INTO `words` VALUES (9079, 'The most arresting feature is the painted wall decoration.', 'adj. 醒目的， 引人注意的', '/ə\'restɪŋ | ə\'rɛstɪŋ/', 'arresting', 6);
INSERT INTO `words` VALUES (9080, 'I couldn’t believe the arrogance of the man!', 'n. 傲慢态度, 自大', '/\'ærəɡəns,-si | \'ærəg(ə)ns | \'ærəgəns/', 'arrogance', 6);
INSERT INTO `words` VALUES (9081, 'He was unbearably arrogant.', 'adj. 傲慢的, 自大的', '/\'ærəɡənt | \'ærəg(ə)nt/', 'arrogant', 6);
INSERT INTO `words` VALUES (9082, NULL, 'v. 冒称', '/\'ærəuɡeit | \'ærəgeɪt | \'ærəɡet/', 'arrogate', 6);
INSERT INTO `words` VALUES (9083, 'He checked the sandy areas of the arroyo for any tracks.', 'n. 干枯的河床, 峡谷, 小河', '/ə\'rɔiəu | ə\'rɒɪəʊ | ə\'rɔɪo/', 'arroyo', 6);
INSERT INTO `words` VALUES (9084, 'His wife poisoned him with arsenic.', 'n. [化]砷, 砒霜', '/\'ɑ:sənik, ɑ:\'senik | \'ɑːs(ə)nɪk | \'ɑrsnɪk/', 'arsenic', 6);
INSERT INTO `words` VALUES (9085, 'The school was destroyed in an arson attack.', 'n. 纵火, 纵火罪', '/\'ɑ:sən | \'ɑːs(ə)n | \'ɑrsn/', 'arson', 6);
INSERT INTO `words` VALUES (9086, 'What makes an arsonist?', 'n. 纵火犯人', '/\'ɑ:sənist | \'ɑːs(ə)nɪst; \'ɑːsənɪst | \'ɑrsənɪst/', 'arsonist', 6);
INSERT INTO `words` VALUES (9087, 'Garlic aids in the digestion of fats and oils, lowers blood pressure, prevents arteriosclerosis, and lowers cholesterol levels.', 'n. 动脉硬化', '/ɑ:,tiəriəusklə\'rəusis | ɑː,tɪərɪəʊsklɪə\'rəʊsɪs; -sklə- | ɑr,tɪriosklə\'rosɪs/', 'arteriosclerosis', 6);
INSERT INTO `words` VALUES (9088, 'I have a touch of arthritis in the wrist.', 'n. 关节炎', '/ɑ:\'θraitis | ɑː\'θraɪtɪs | ɑr\'θraɪtɪs/', 'arthritis', 6);
INSERT INTO `words` VALUES (9089, 'bright, articulate 17-year-olds', 'adj. 有关节的, 发音清晰的', '/ɑ:\'tɪkjʊleɪt | ɑr\'tɪkjulet/', 'articulate', 6);
INSERT INTO `words` VALUES (9090, 'In the wrong hands this powerful artifact has the ability to unravel the soul.', 'n. 人工制品', '/\'ɑːrtɪfækt | \'ɑrtə,fækt/', 'artifact', 6);
INSERT INTO `words` VALUES (9091, 'Weegee\'s photographs are full of artfulness, and artifice.', 'n. 技巧', '/\'ɑ:tifis | \'ɑːtɪfɪs | \'ɑrtɪfɪs/', 'artifice', 6);
INSERT INTO `words` VALUES (9092, 'artificial flowers', 'adj. 人造的， 假的', '/ˌɑːrtɪ\'fɪʃl | ,ɑrtɪ\'fɪʃl/', 'artificial', 6);
INSERT INTO `words` VALUES (9093, 'Using tanks and heavy artillery, they seized the town.', 'n. 炮的总称, 炮兵的总称', '/ɑ:\'tiləri | ɑː\'tɪlərɪ | ɑr\'tɪləri/', 'artillery', 6);
INSERT INTO `words` VALUES (9094, 'The artisan can cut stones into various shapes.', 'n. 技工', '/\'ɑːrtəzn | \'ɑrtəzn/', 'artisan', 6);
INSERT INTO `words` VALUES (9095, 'the artistry of dance', 'n. 艺术技巧', '/\'ɑːrtɪstri | \'ɑrtɪstri/', 'artistry', 6);
INSERT INTO `words` VALUES (9096, 'artless sincerity', 'adj. 朴实的', '/\'ɑ:tlis | \'ɑːtlɪs | \'ɑrtləs/', 'artless', 6);
INSERT INTO `words` VALUES (9097, 'The plane ascended rapidly.', 'v. 攀登, 上升', '/ə\'send | ə\'sɛnd/', 'ascend', 6);
INSERT INTO `words` VALUES (9098, 'moral ascendancy', 'n. 优势, 支配(或统治)地位', '/ə\'sendənsi,-dəns | ə\'send(ə)nsɪ | ə\'sɛndənsi/', 'ascendancy', 6);
INSERT INTO `words` VALUES (9099, 'It occupies special position- joint of agriculture and nomadism civilization, and also it is the most important strategic field, so the whole area is still creative and ascensive.', 'adj. 上升的, 进步的, 强调的', '/ə\'sensiv | ə\'sensɪv | ɑs\'tɛnsɪv/', 'ascensive', 6);
INSERT INTO `words` VALUES (9100, 'the first ascent of Qomolangma', 'n. 上升, (地位, 声望等的)提高, 攀登, 上坡路', '/ə\'sent | ə\'sɛnt/', 'ascent', 6);
INSERT INTO `words` VALUES (9101, 'A postmortem was ordered to try to ascertain the cause of death.', 'v. 确定, 探知', '/,æsə\'tein | ,æsə\'teɪn | \'æsɚ\'ten/', 'ascertain', 6);
INSERT INTO `words` VALUES (9102, 'an ascetic life', 'n. 禁欲者, 苦行修道者', '/ə\'setik | ə\'setɪk | ə\'sɛtɪk/', 'ascetic', 6);
INSERT INTO `words` VALUES (9103, 'Puritanism is based on autonomy of local congregations, simplicity of worship, asceticism, egalitarianism, and a call to the past with restoration of original values through purification.', 'n. 禁欲主义, 苦行', '/ə\'setisizəm | ə\'setɪsɪz(ə)m | ə\'sɛtɪsɪzəm/', 'asceticism', 6);
INSERT INTO `words` VALUES (9104, 'An autopsy eventually ascribed the baby\'s death to sudden infant death syndrome.', 'v. 归因于， 归咎于', '/ə\'skraɪb/', 'ascribe', 6);
INSERT INTO `words` VALUES (9105, 'The aseptic design of centrifugal separator and its application are introduced.', 'n. 防腐剂', '/æ\'septik | eɪ\'septɪk | ,e\'sɛptɪk/', 'aseptic', 6);
INSERT INTO `words` VALUES (9106, 'His face was ashen.', 'adj. 灰色的， 苍白的, especially deadly pale)', '/\'æʃn | \'æʃən/', 'ashen', 6);
INSERT INTO `words` VALUES (9107, 'What an asinine remark!', 'adj. 驴的, 象驴一样的, 愚蠢的', '/\'æsinain | \'æsɪnaɪn/', 'asinine', 6);
INSERT INTO `words` VALUES (9108, 'Soon after, he dragged me to the Lower East Side where we met an old rabbi, who looked at us a bit askance and said wisely, \"You will have a sweet and crazy life together, \" which we did.', 'adv. 斜视地', '/ə\'skæns/', 'askance', 6);
INSERT INTO `words` VALUES (9109, 'There were no shutters at the windows, and some of the doors hung askew.', 'adj. 歪斜的', '/ə\'skju: | ə\'skjuː | ə\'skju/', 'askew', 6);
INSERT INTO `words` VALUES (9110, 'But then again, so does asparagus.', 'n. [植]芦笋', '/ə\'spærəɡəs | ə\'spærəgəs/', 'asparagus', 6);
INSERT INTO `words` VALUES (9111, 'a south-facing aspect', 'n. 方面； 面貌， 外表', '/\'æspekt | \'æspɛkt/', 'aspect', 6);
INSERT INTO `words` VALUES (9112, 'Groves of elderly aspen tremble in the wind, but no sprouts push up in the understory .', 'n. 白杨', '/\'æspən/', 'aspen', 6);
INSERT INTO `words` VALUES (9113, '\"I told you Preskel had no idea,\" remarked Kemp with some asperity.', 'n. 严酷, 粗暴, 刻薄', '/æ\'sperəti | ə\'sperɪtɪ | æ\'spɛrəti/', 'asperity', 6);
INSERT INTO `words` VALUES (9114, 'In aspermous Patients the reason is the obstruction of spermatogenesis, the most common obstruction occurs in the spermatid level.', 'adj. 无种子的', '/ə\'spə:məs/', 'aspermous', 6);
INSERT INTO `words` VALUES (9115, 'Should you hear my name blackened and maligned, will you credit the aspersion ?', 'n. 洒水, 诽谤, 中伤', '/ə\'spə:ʃən | ə\'spɜːʃ(ə)n | ə\'spɝʒən/', 'aspersion', 6);
INSERT INTO `words` VALUES (9116, 'These comprise asphalt, tar and waxes.', 'n. 沥青', '/\'æsfælt | \'æsfælt; -əlt | \'æsfɔlt/', 'asphalt', 6);
INSERT INTO `words` VALUES (9117, 'Death was due to asphyxia through smoke inhalation.', 'n. 窒息, 昏厥', '/æs\'fiksiə | əs\'fɪksɪə | æs\'fɪksɪə/', 'asphyxia', 6);
INSERT INTO `words` VALUES (9118, 'Three people were asphyxiated in the crush for last week\'s train.', 'v. 窒息', '/æs\'fiksieit | əs\'fɪksɪeɪt | əs\'fɪksɪet/', 'asphyxiate', 6);
INSERT INTO `words` VALUES (9119, '...the young aspirant to power.', 'n. 有抱负者, 有野心者', '/ə\'spaiərənt | ə\'spaɪər(ə)nt; \'æsp(ɪ)r- | ə\'spaɪərənt/', 'aspirant', 6);
