INSERT INTO `words` VALUES (9123, 'Protesters assailed the proposed fare increase.', 'v. 攻击, 质问', '/ə\'seil | ə\'seɪl | ə\'sel/', 'assail', 6);
INSERT INTO `words` VALUES (9124, 'The refugee camp came under assault again last night.', 'n. 攻击, 袭击', '/ə\'sɔ:lt | ə\'sɔːlt; ə\'sɒlt | ə\'sɔlt/', 'assault', 6);
