INSERT INTO `words` VALUES (9127, 'French cooking, she asserted, is the best in the world.', 'v. 断言, 声称', '/ə\'sə:t | ə\'sɜːt | ə\'sɝt/', 'assert', 6);
INSERT INTO `words` VALUES (9128, 'She makes very general assertions about marriage in the poem.', 'n. 断言， 声明； 主张', '/ə\'sɜːrʃn | ə\'sɝʃən/', 'assertion', 6);
INSERT INTO `words` VALUES (9129, 'Women have become more assertive in the past decade.', 'adj. 断定的, 过分自信的', '/ə\'sə:tiv | ə\'sɜːtɪv | ə\'sɝtɪv/', 'assertive', 6);
INSERT INTO `words` VALUES (9130, 'The test was to assess aptitude rather than academic achievement.', 'v. 评定， 核定； 估计， 估价', '/ə\'ses | ə\'sɛs/', 'assess', 6);
