INSERT INTO `words` VALUES (9134, NULL, 'n. 勤勉, 刻苦, 一丝不苟的作风', '/,æsi\'dju:əti | ,æsɪ\'djuːɪtɪ | ,æsə\'djʊəti/', 'assiduity', 6);
INSERT INTO `words` VALUES (9135, 'Podulski had been assiduous in learning his adopted language.', 'adj. 勤勉的, 刻苦的', '/ə\'sidjuəs | ə\'sɪdjʊəs/', 'assiduous', 6);
INSERT INTO `words` VALUES (9136, 'It will take time to assimilate all these facts.', 'v. 吸收', '/ə\'simileit | ə\'sɪmɪleɪt | ə\'sɪməlet/', 'assimilate', 6);
INSERT INTO `words` VALUES (9137, NULL, 'n. 立法会议, 法令', '/ə\'saiz | ə\'saɪz/', 'assize', 6);
INSERT INTO `words` VALUES (9138, 'Mr. Lin is associate director of the Institute.', 'adj. 联合的; v. 使发生联系， 使联合; n. 合伙人', '/ə\'səʊʃɪeɪt; -sɪeɪt | ə\'soʃɪet/', 'associate', 6);
INSERT INTO `words` VALUES (9139, NULL, 'v. 赦免, 释放, 补偿', '/ə\'sɔil | ə\'sɒɪl/', 'assoil', 6);
INSERT INTO `words` VALUES (9140, 'paintbrushes in assorted sizes', 'adj. 各式各样的； 混杂的', '/ə\'sɔːrtəd | ə\'sɔrtəd/', 'assorted', 6);
INSERT INTO `words` VALUES (9141, 'Nothing could assuage his guilt.', 'v. 缓和, 减轻, 镇定', '/ə\'sweidʒ | ə\'sweɪdʒ | ə\'swedʒ/', 'assuage', 6);
INSERT INTO `words` VALUES (9142, 'Whoever they appoint will assume responsibility for all financial matters.', 'v. 假定； 承担， 担任', '/ə\'suːm | ə\'sum/', 'assume', 6);
