INSERT INTO `words` VALUES (9145, 'The document is genuine, I can assure you .', 'v. 保证； 使确信', '/ə\'ʃur | ə\'ʃʊr/', 'assure', 6);
INSERT INTO `words` VALUES (9146, 'Her political future looks assured.', 'adj. 确实的, 确定的', '/ə\'ʃuəd | ə\'ʃʊəd | ə\'ʃʊrd/', 'assured', 6);
INSERT INTO `words` VALUES (9147, 'Say it with assuredness.', 'n. 确定； 自信', '/ə\'ʃuədnis | ə\'ʃurdnəs/', 'assuredness', 6);
INSERT INTO `words` VALUES (9148, 'Is it possible to declare variables in VHDL with an asterisk?', 'n. 星号', '/\'æstərɪsk/', 'asterisk', 6);
