INSERT INTO `words` VALUES (9150, 'We have only asthma.', 'n. [医]哮喘', '/\'æsmə, \'æz- | \'æsmə | \'æzmə/', 'asthma', 6);
INSERT INTO `words` VALUES (9151, 'When the astigmatic degree< 1.50D, mydriatic optometry is of help to found the axis of cylindrical lens.', 'adj. 乱视的, 散光的,纠正散光的', '/,æstiɡ\'mætik | ,æstɪɡ\'mætɪk | ,æstɪg\'mætɪk/', 'astigmatic', 6);
