INSERT INTO `words` VALUES (9159, 'Houses in the subdivision are going for astronomical prices.', 'adj. 极大的； 天文学的', '/ˌæstrə\'nɑːmɪkl | ,æstrə\'nɑmɪkl/', 'astronomical', 6);
