INSERT INTO `words` VALUES (9164, 'Together we developed the theory that cancer tumours are a type of atavism that appears in the adult form when something disrupts the silencing of ancestral genes.', 'n. [生]隔代遗传, 返祖现象', '/\'ætəvizəm | \'ætəvɪzəm | \'ætə,vɪzəm/', 'atavism', 6);
INSERT INTO `words` VALUES (9165, 'In 1666 the English parliament cited his atheism as the probably cause of the plague and the fire of London.', 'n. 无神论', '/\'eiθiizəm | \'eɪθɪɪz(ə)m | \'eθɪɪzəm/', 'atheism', 6);
