INSERT INTO `words` VALUES (9175, 'The killing was cold-blooded, and those who committed this atrocity should be tried and punished.', 'n. 残暴, 暴行, 凶恶', '/ə\'trɔsəti | ə\'trɒsɪtɪ | ə\'trɑsəti/', 'atrocity', 6);
