INSERT INTO `words` VALUES (9186, 'What attributes should a good manager possess?', 'n. 属性, 品质, 特征, 加于, 归结于', '/ə\'tribju:t, \'ætribju:t | ə\'trɪbjuːt | ə\'trɪbjut/', 'attribute', 6);
