INSERT INTO `words` VALUES (9201, 'However, it is more interesting and fun studying with digital textbooks, which has augmentation contents and videos.', 'n. 增加', '/,ɔ:ɡmen\'teiʃən | ɔːgmen\'teɪʃ(ə)n | ,ɔgmɛn\'teʃən/', 'augmentation', 6);
