INSERT INTO `words` VALUES (9208, 'The new boy had an auspicious first day in the elementary school.', 'n. 吉兆的, 幸运的', '/ɔ:\'spiʃəs | ɔː\'spɪʃəs | ɔ\'spɪʃəs/', 'auspicious', 6);
INSERT INTO `words` VALUES (9209, 'the church’s austere simplicity', 'adj. 严峻的, 严厉的, 操行上一丝不苟的, 简朴的', '/ɔ\'stiə | ɒ\'stɪə; ɔː- | ɔ\'stɪr/', 'austere', 6);
INSERT INTO `words` VALUES (9210, 'a life of austerity', 'n. 严峻, 严厉, 朴素, 节俭, 苦行', '/ɔ\'sterəti | ɒ\'sterɪtɪ; ɔː- | ɔ\'stɛrəti/', 'austerity', 6);
INSERT INTO `words` VALUES (9211, 'an authentic account', 'adj. 可信的', '/ɔ:\'θentik | ɔː\'θentɪk | ɔ\'θɛntɪk/', 'authentic', 6);
INSERT INTO `words` VALUES (9212, 'The painting has been authenticated by experts.', 'v. 鉴别', '/ɔ:\'θentikeit | ɔː\'θentɪkeɪt | ɔ\'θɛntɪket/', 'authenticate', 6);
INSERT INTO `words` VALUES (9213, 'the most authoritative work on English surnames', 'adj. 权威的, 有权威的, 命令的', '/ɔ:\'θɔritətiv | ɔː\'θɒrɪtətɪv; -,teɪtɪv | ə\'θɔrətetɪv/', 'authoritative', 6);
INSERT INTO `words` VALUES (9214, 'You need special authorization to park here.', 'n. 授权, 认可', '/,ɔ:θərai\'zeiʃən, -ri\'z- | ɔːθəraɪ\'zeɪʃ(ə)n | ,ɔθərɪ\'zeʃən/', 'authorization', 6);
INSERT INTO `words` VALUES (9215, 'an authorized biography', 'v. 批准', '/\'ɔ:θəraiz | \'ɔθəraɪz/', 'authorize', 6);
INSERT INTO `words` VALUES (9216, NULL, 'n. [心]自我中心主义, 孤独症', '/\'ɔ:tizəm | \'ɔːtɪz(ə)m | \'ɔtɪzəm/', 'autism', 6);
INSERT INTO `words` VALUES (9217, '...a highly autobiographical novel of a woman\'s search for identity.', 'adj. 自传的， 自传体的', '/ˌɔːtəˌbaɪə\'græfɪkl | ,ɔtə,baɪə\'græfɪkl/', 'autobiographical', 6);
INSERT INTO `words` VALUES (9218, 'He published his autobiography last autumn.', 'n. 自传', '/ˌɔːtəbaɪ\'ɑːgrəfi | ,ɔtəbaɪ\'ɑɡrəfi/', 'autobiography', 6);
INSERT INTO `words` VALUES (9219, 'Many poor countries are abandoning autocracy.', 'n. 独裁政治, 独裁政府', '/ɔ:\'tɔkrəsi | ɔː\'tɒkrəsɪ | ɔ\'tɑkrəsi/', 'autocracy', 6);
INSERT INTO `words` VALUES (9220, 'But this view misses the dark side of the bargain we made with the autocrat: we befriended him but enraged his population.', 'n. 独裁者', '/\'ɔ:təukræt | \'ɔːtəkræt | \'ɔtəkræt/', 'autocrat', 6);
INSERT INTO `words` VALUES (9221, 'a shirt autographed by the whole team', 'v. 在…上亲笔签名; adj. 亲笔的; n. 亲笔稿，手迹', '/\'ɔːtəgræf | \'ɔtəɡræf/', 'autograph', 6);
INSERT INTO `words` VALUES (9222, 'a highly automated factory', 'adj. 自动的', '/\'ɔːtəmeɪtɪd | ɔtəˌmetɪd/', 'automated', 6);
INSERT INTO `words` VALUES (9223, 'Then you could have your test automation read, parse, and use the data in this file.', 'n. 自动装置', '/ˌɔːtə\'meɪʃn | ,ɔtə\'meʃən/', 'automation', 6);
INSERT INTO `words` VALUES (9224, NULL, 'n. 自动化, 自动作用, 自动力', '/ɔ:\'tɔmətizəm | ɔː\'tɒmətɪz(ə)m | ɔ\'tɑmətɪzəm/', 'automatism', 6);
INSERT INTO `words` VALUES (9225, 'automotive technology', 'adj. 汽车的， 自动的', '/ˌɔːtə\'moutɪv | ,ɔtə\'motɪv/', 'automotive', 6);
INSERT INTO `words` VALUES (9226, 'They proudly declared themselves part of a new autonomous province.', 'adj. 自治的', '/ɔ:\'tɔnəməs | ɔː\'tɒnəməs | ɔ\'tɑnəməs/', 'autonomous', 6);
INSERT INTO `words` VALUES (9227, 'campaigners who want greater autonomy for Corsica', 'n. 自治', '/ɔ:\'tɔnəmi | ɔː\'tɒnəmɪ | ɔ\'tɑnəmi/', 'autonomy', 6);
INSERT INTO `words` VALUES (9228, 'an autopsy report', 'n. (为查明死因而做的)尸体解剖, 验尸', '/\'ɔ:təpsi | \'ɔːtɒpsɪ; ɔː\'tɒpsɪ | \'ɔtɑpsi/', 'autopsy', 6);
INSERT INTO `words` VALUES (9229, NULL, 'n. [摄](相片的)碳印法, 用碳印法印成的相片, 复写', '/\'ɔ:təutaip | \'ɔːtə(ʊ)taɪp | \'ɔtə,taɪp/', 'autotype', 6);
INSERT INTO `words` VALUES (9230, 'an auxiliary nurse', 'adj. 辅助的, 补助的', '/ɔ:ɡ\'ziljəri | ɔːg\'zɪlɪərɪ; ɒg- | ɔːɡ\'zɪlɪəri/', 'auxiliary', 6);
INSERT INTO `words` VALUES (9231, 'Scientists have found some clues, for example the effect of auxin in the process.', 'n. 茁长素, 植物激素', '/\'ɔ:ksin | \'ɔːksɪn | \'ɔksɪn/', 'auxin', 6);
INSERT INTO `words` VALUES (9232, 'Two skiers were killed in the avalanche.', 'n. 雪崩', '/\'ævəlɑ:ntʃ | \'ævəlɑːnʃ | \'ævəlæntʃ/', 'avalanche', 6);
INSERT INTO `words` VALUES (9233, 'He paid a month\'s rent in advance, just enough to satisfy the landlord\'s avarice.', 'n. 贪财, 贪婪', '/\'ævəris | \'æv(ə)rɪs | \'ævərɪs/', 'avarice', 6);
INSERT INTO `words` VALUES (9234, 'He sacrificed his own career so that his avaricious brother could succeed.', 'adj. 贪财的, 贪婪的', '/,ævə\'riʃəs | ævə\'rɪʃəs | ,ævə\'rɪʃəs/', 'avaricious', 6);
INSERT INTO `words` VALUES (9235, 'In this conflict of emotions all I dare aver is that it has been my faithful study to collect, my duty from a just appreciation of every circumstance by which it might be affected.', 'v. 断言, 主张', '/ə\'və: | ə\'vɜː/', 'aver', 6);
INSERT INTO `words` VALUES (9236, 'Some banks are risk averse (= do not like taking a risk ) .', 'adj. 不愿意的, 反对的', '/ə\'və:s | ə\'vɜːs | ə\'vɝs/', 'averse', 6);
INSERT INTO `words` VALUES (9237, 'Many people have a natural and emotional aversion to insects.', 'n. 厌恶, 讨厌的事和人', '/ə\'və:ʃən | ə\'vɜːʃ(ə)n | ə\'vɝʒn/', 'aversion', 6);
INSERT INTO `words` VALUES (9238, 'Henry averted his eyes as she undressed.', 'v. 转移', '/ə\'və:t | ə\'vɜːt | ə\'vɝt/', 'avert', 6);
INSERT INTO `words` VALUES (9239, 'Already he had begun to forget them, and Shepperton soon became an extraordinary aviary, filled with birds of every species.', 'n. (动物园的)大型鸟舍, 鸟类饲养场', '/\'eivjəri | \'eɪvɪərɪ | \'evɪɛri/', 'aviary', 6);
INSERT INTO `words` VALUES (9240, 'Meanwhile, time after time on other issues -- such as the economic stimulus package, health care and Iraq -- he has tacked to the center, much to the frustration of his most avid supporters.', 'adj. 渴望的', '/,ævid | \'ævɪd/', 'avid', 6);
INSERT INTO `words` VALUES (9241, 'He was a printer by trade and naturalist by avocation.', 'n. (个人)副业, 业余爱好', '/,ævəu\'keiʃən | ,ævə\'keɪʃ(ə)n | \'ævo\'keʃən/', 'avocation', 6);
INSERT INTO `words` VALUES (9242, NULL, 'adj. 副业的， 嗜好的', '/ˌævou\'keɪʃənl/', 'avocational', 6);
INSERT INTO `words` VALUES (9243, 'Everyone seemed to be avoiding Nick.', 'v. 避开， 躲避', '/ə\'vɔɪd/', 'avoid', 6);
INSERT INTO `words` VALUES (9244, 'He offered to avouch his innocence with his sword.', 'v. 确保', '/ə\'vautʃ | ə\'vaʊtʃ/', 'avouch', 6);
INSERT INTO `words` VALUES (9245, '...a public statement avowing neutrality.', 'v. 承认', '/ə\'vau | ə\'vaʊ/', 'avow', 6);
INSERT INTO `words` VALUES (9246, 'Set in small-town Iowa in 1956, Gilead is a quiet, slow-moving but ultimately majestic avowal of the redemptive power of love. LA', 'n. 声明', '/ə\'vauəl | ə\'vaʊəl | əˈvaʊəl/', 'avowal', 6);
INSERT INTO `words` VALUES (9247, 'an avuncular pat on the shoulder', 'adj. 伯父的, 伯父似的', '/ə\'vʌŋkjulə | ə\'vʌŋkjʊlə | ə\'vʌŋkjəlɚ/', 'avuncular', 6);
INSERT INTO `words` VALUES (9248, 'He felt great awe for the landscape.', 'n. 敬畏', '/ɔ: | ɔː | ɔ/', 'awe', 6);
INSERT INTO `words` VALUES (9249, 'a truly awe-inspiring achievement', 'adj. 令人敬畏的', '/\'ɔ:in,spaiəriŋ | ɔːɪn\'spaɪərɪŋ/', 'awe-inspiring', 6);
INSERT INTO `words` VALUES (9250, NULL, 'adj. 充满敬畏的', '/\'ɔːstrʌk | \'ɔ:strʌk/', 'awe-struck', 6);
INSERT INTO `words` VALUES (9251, 'It’ll be awkward getting cars in and out.', 'adj. 笨拙的； 难用的； 不便的', '/\'ɔːkwərd | \'ɔkwɚd/', 'awkward', 6);
INSERT INTO `words` VALUES (9252, 'Again he drove the awl and needle into her.', 'n. 锥子, 尖钻', '/ɔ:l | ɔːl | ɔl/', 'awl', 6);
INSERT INTO `words` VALUES (9253, 'Karen followed the pair onto the patio and watched as they settled at a round table under a burgundy window awning.', 'n. 遮阳篷, 雨篷', '/\'ɔ:niŋ | \'ɔːnɪŋ | \'ɔnɪŋ/', 'awning', 6);
INSERT INTO `words` VALUES (9254, 'He rushed out, hat awry.', 'adj. 歪曲的, 错误的', '/ə\'raɪ/', 'awry', 6);
INSERT INTO `words` VALUES (9255, '...the long-held axiom that education leads to higher income.', 'n. [数]公理', '/\'æksiəm | \'æksɪəm/', 'axiom', 6);
INSERT INTO `words` VALUES (9256, 'It was once regarded as axiomatic that globalisation would marginalise politics.', 'adj. 自明的', '/,æksiəu\'mætik | ,æksɪə\'mætɪk/', 'axiomatic', 6);
INSERT INTO `words` VALUES (9257, 'The Earth rotates on an axis between the north and south poles.', 'n. 轴', '/\'æksis | \'æksɪs/', 'axis', 6);
INSERT INTO `words` VALUES (9258, 'The axle doesn\'t work smoothly. It needs oiling.', 'n. 轮轴, 车轴', '/\'æksəl | \'æks(ə)l | \'æksl/', 'axle', 6);
