INSERT INTO `words` VALUES (9260, 'The apartment flag is gold lion rampant on a field of azure.', 'n. 天蓝色, 苍天, 碧空', '/\'æʒə | \'æʒə; -ʒj(ʊ)ə; \'eɪ- | \'æʒɚ/', 'azure', 6);
INSERT INTO `words` VALUES (9261, 'Momma babbled on and on about how he was ruining me.', 'v. 呀呀学语, 喋喋不休, 作潺潺声, 泄露(秘密)', '/\'bæbl | \'bæb(ə)l/', 'babble', 6);
