INSERT INTO `words` VALUES (9267, 'You re doing excellent work now I hope you wont backslide .', 'v. 故态复萌', '/\'bækslaɪd | ,bæk\'slaid/', 'backslide', 6);
INSERT INTO `words` VALUES (9268, 'bacon and eggs', 'n. 咸肉, 熏肉', '/\'beikən | \'beɪk(ə)n | \'bekən/', 'bacon', 6);
