INSERT INTO `words` VALUES (9271, 'We were each handed a badge with our name on it.', 'n. 徽章, 证章', '/\'bædʒ | bædʒ/', 'badge', 6);
INSERT INTO `words` VALUES (9272, 'She badgered me for weeks until I finally gave in.', 'n. 獾, 獾皮毛', '/英 [ˈbædʒə(r)] 美 [ˈbædʒɚ] | \'bædʒə | \'bædʒɚ/', 'badger', 6);
INSERT INTO `words` VALUES (9273, '...light-hearted badinage.', 'n. 开玩笑, 揶揄', '/bædinɑ:ʒ | \'bædɪnɑːʒ | ,bædən\'ɑʒ/', 'badinage', 6);
INSERT INTO `words` VALUES (9274, 'The question baffled me completely.', 'v. 困惑, 阻碍, 为难', '/\'bæfl | \'bæf(ə)l/', 'baffle', 6);
INSERT INTO `words` VALUES (9275, NULL, 'adj. 阻碍的, 令人丧气的, 使困惑的, 令人莫名其妙的, 变幻的, 不可理解的', '/\'bæfliŋ | \'bæf(ə)lɪŋ | \'bæflɪŋ/', 'baffling', 6);
INSERT INTO `words` VALUES (9276, NULL, 'n. 微不足道的东西, 琐事, 小事, 弹子球戏的一种, (指钢琴的)小曲', '/,bæɡə\'tel | ,bægə\'tel | ,bæɡə\'tɛl/', 'bagatelle', 6);
INSERT INTO `words` VALUES (9277, 'We used worms as bait.', 'n. 饵, 诱惑物', '/beit | beɪt | bet/', 'bait', 6);
INSERT INTO `words` VALUES (9278, 'a bald man', 'adj. 光秃的, 单调的, 枯燥的', '/bɔ:ld | bɔːld | bɔld/', 'bald', 6);
INSERT INTO `words` VALUES (9279, 'In this section, Katherine\'s terrible hysteria and balderdash feels she seems to be in a state of insanity.', 'n. 胡言乱语, 梦呓', '/\'bɔ:ldədæʃ | \'bɔːldədæʃ | \'bɔldɚdæʃ/', 'balderdash', 6);
INSERT INTO `words` VALUES (9280, 'a bale of straw', 'n. 大包, 大捆, (指标准量货物, 如稻草, 麦杆)货物', '/beɪl | bel/', 'bale', 6);
INSERT INTO `words` VALUES (9281, 'a baleful look', 'adj. 有害的, 恶意的', '/\'beilful | \'beɪlfʊl; -f(ə)l/', 'baleful', 6);
