INSERT INTO `words` VALUES (9283, '...an eighteenth century ballad about some lost children called the Babes in the Wood.', 'n. 民歌, 歌谣, 叙事歌, 流行歌曲, 情歌', '/\'bæləd/', 'ballad', 6);
