INSERT INTO `words` VALUES (9285, 'She became a ballerina.', 'n. 芭蕾舞女', '/,bælə\'ri:nə | bælə\'riːnə | ,bælə\'rinə/', 'ballerina', 6);
INSERT INTO `words` VALUES (9286, 'The party leader is elected by secret ballot .', 'n&v. 投票', '/\'bælət/', 'ballot', 6);
