INSERT INTO `words` VALUES (9288, 'After all the ballyhoo, the film was a flop.', 'n. 大肆宣传, 大吹大擂, 喧噪', '/,bæli\'hu:, \'bæli,hu: | bælɪ\'huː | \'bælɪhu/', 'ballyhoo', 6);
INSERT INTO `words` VALUES (9289, 'lip balm', 'n. (止痛或疗伤的)香油, 香膏, 安慰物', '/bɑ:m | bɑːm | bɑm/', 'balm', 6);
INSERT INTO `words` VALUES (9290, 'a balmy summer night', 'adj. 芳香的, 温和的, 止痛的, (空气)温和的', '/\'bɑ:mi | \'bɑːmɪ | \'bɑmi/', 'balmy', 6);
INSERT INTO `words` VALUES (9291, 'He bamboozled Mercer into defeat.', 'v. 欺骗, 迷惑', '/bæm\'bu:zəl | bæm\'buːz(ə)l | bæm\'buzl/', 'bamboozle', 6);
INSERT INTO `words` VALUES (9292, 'Smoking is banned in the building.', 'v. 禁止， 取缔; n. 禁令', '/bæn/', 'ban', 6);
INSERT INTO `words` VALUES (9293, 'conversations about the most banal subjects', 'adj. 平凡的, 陈腐的, 老一套的', '/bə\'nɑ:l, \'beinəl | bə\'nɑːl; -\'næl | bə\'nɑl/', 'banal', 6);
INSERT INTO `words` VALUES (9294, 'It is a mass-producer of banality.', 'n. 平凡, 陈腐', '/bə\'næləti | bə\'nælɪtɪ/', 'banality', 6);
INSERT INTO `words` VALUES (9295, 'Her brother is the bane of her life .', 'n. 毒药, 祸害', '/bein | beɪn | ben/', 'bane', 6);
INSERT INTO `words` VALUES (9296, NULL, 'adj. 有害的, 使人苦恼的', '/beinful | beɪnfʊl | \'benfl/', 'baneful', 6);
INSERT INTO `words` VALUES (9297, 'John was banished from England.', 'v. 流放, 驱逐, 消除', '/\'bæniʃ | \'bænɪʃ/', 'banish', 6);
INSERT INTO `words` VALUES (9298, NULL, 'n. 栏杆的支柱, 楼梯的扶栏', '/\'bænistə | \'bænɪstə | \'bænɪstɚ/', 'banister', 6);
INSERT INTO `words` VALUES (9299, 'In total, 80% of bankrupts are men.', 'n. 破产者', '/\'bæŋkrʌpt/', 'bankrupt', 6);
INSERT INTO `words` VALUES (9300, 'In 1999 it was revealed that he was close to bankruptcy.', 'n. 破产', '/\'bæŋkrəptsi | \'bæŋkrʌptsɪ | \'bæŋkrʌptsi/', 'bankruptcy', 6);
INSERT INTO `words` VALUES (9301, 'The onlookers were shouting, cheering, and waving banners.', 'n. 旗帜, 横幅, 标语', '/\'bænə | \'bænɚ/', 'banner', 6);
INSERT INTO `words` VALUES (9302, 'As she closed the door, she heard Tom exchanging good-natured banter with Jane.', 'n. 善意地取笑, 逗弄', '/ˈbantə | \'bæntə | \'bæntɚ/', 'banter', 6);
INSERT INTO `words` VALUES (9303, 'She ran back, but Francis barred her way .', 'v. 禁止，阻挡; n. 条， 棒', '/bɑːr | bɑr/', 'bar', 6);
INSERT INTO `words` VALUES (9304, 'The barb stung her exactly the way he hoped it would.', 'n. 鱼钩, 鱼叉的倒钩, 巴巴里鸽(一种类似信鸽的鸽子)', '/bɑ:b | bɑːb | bɑrb/', 'barb', 6);
INSERT INTO `words` VALUES (9305, 'the medieval barbarity of putting people in prison for debt', 'n. 残暴的行为, 残忍', '/bɑ:\'bærəti | bɑː\'bærɪtɪ | bɑr\'bærəti/', 'barbarity', 6);
