INSERT INTO `words` VALUES (9307, 'We had a barbecue on the beach.', 'n. 吃烤烧肉的野餐', '/\'bɑ:bikju: | \'bɑːbɪkjuː | \'bɑrbɪkju/', 'barbecue', 6);
INSERT INTO `words` VALUES (9308, 'a barbed comment on his appearance', 'adj. 有刺的, 具侧刺毛的, (话语)尖刻的, 尖锐的, 讽刺的', '/bɑ:bd | bɑːbd | bɑrbd/', 'barbed', 6);
INSERT INTO `words` VALUES (9309, 'Gnomeo and Juliet is directed and co-written by animation veteran Kelly Asbury, who makes no apologies to William Shakespeare or to the bard\'s, perhaps, most malleable tale.', 'n. 吟游诗人', '/bɑ:d | bɑːd | bɑrd/', 'bard', 6);
INSERT INTO `words` VALUES (9310, 'The dog bared its teeth .', 'v. 暴露; adj. 赤裸的', '/ber | bɛr/', 'bare', 6);
INSERT INTO `words` VALUES (9311, 'Why are you telling such barefaced lies ?', 'adj. 厚颜无耻的， 公然的', '/\'berfeɪst | \'bɛrfest/', 'barefaced', 6);
INSERT INTO `words` VALUES (9312, 'They prefer to bargain with individual clients, for cash.', 'v. 讨价还价; n. 交易；特价商品', '/\'bɑːrgən | ˈbɑrɡɪn/', 'bargain', 6);
INSERT INTO `words` VALUES (9313, 'Carrying goods by train costs nearly three times more than carrying them by barge.', 'n. 驳船, 游艇', '/bɑ:dʒ | bɑːdʒ | bɑrdʒ/', 'barge', 6);
INSERT INTO `words` VALUES (9314, 'The Doberman let out a string of roaring barks.', 'n. 树皮, 吠声', '/bɑ:k | bɑːk | bɑrk/', 'bark', 6);
INSERT INTO `words` VALUES (9315, 'The next morning I started trapping around the barn .', 'n. [农]谷仓, 畜棚, 畜舍, 机器房', '/bɑ:n | bɑːn | bɑrn/', 'barn', 6);
INSERT INTO `words` VALUES (9316, 'A man in camp took a barometer reading at half-hour intervals.', 'n. 气压计', '/bə\'rɒmɪtə | bə\'rɑmɪtɚ/', 'barometer', 6);
INSERT INTO `words` VALUES (9317, 'I once carried a letter to a baron of that sort.', 'n. 男爵(英国世袭的最低级的贵族爵位)', '/\'bærən | \'bær(ə)n/', 'baron', 6);
INSERT INTO `words` VALUES (9318, '...the seventeenth-century taste for the baroque.', 'n. 巴洛克时期艺术和建筑风格的, 巴洛克式', '/bə\'rɔk/', 'baroque', 6);
INSERT INTO `words` VALUES (9319, NULL, 'n. 三桅帆船, 船', '/bɑ:k | bɑːk | bɑrk/', 'barque', 6);
INSERT INTO `words` VALUES (9320, '...a hydro-electric tidal barrage.', 'n. 拦河坝, 堰, 阻塞, (敌军前进的)弹幕射击', '/\'bærɑ:ʒ, bə\'r- | \'bærɑːʒ | bə\'rɑʒ/', 'barrage', 6);
INSERT INTO `words` VALUES (9321, NULL, 'n. <美>美国西南部的峡谷, 悬崖, 峭壁, 陡岸', '/bə\'ræŋkə/', 'barranca', 6);
INSERT INTO `words` VALUES (9322, 'red barred tail feathers', 'adj. 有木栅的, 隔绝的, 被禁止的', '/bɑ:d | bɑːd | bɑrd/', 'barred', 6);
INSERT INTO `words` VALUES (9323, 'Thousands of years ago the surface was barren desert.', 'adj. 不生育的, 不孕的, 贫瘠的, 没有结果的, 无益的, 单调的, 无聊的, 空洞的', '/\'bærən | \'bær(ə)n/', 'barren', 6);
INSERT INTO `words` VALUES (9324, 'During the riots, some of the prisoners barricaded their cells.', 'v. 设路障', '/,bæri\'keid, \'bæri- | ,bærɪ\'keɪd | \'bærɪ\'ked/', 'barricade', 6);
INSERT INTO `words` VALUES (9325, 'He advocated the removal of trade barriers.', 'n. (阻碍通道的)障碍物, 栅栏, 屏障', '/\'bæriə | \'bærɪə | \'bærɪɚ/', 'barrier', 6);
INSERT INTO `words` VALUES (9326, NULL, 'n. 出庭律师； 律师', '/\'bærɪstər | \'bærɪstɚ/', 'barrister', 6);
INSERT INTO `words` VALUES (9327, 'Overall, barter is a very inefficient means of organizing transactions.', 'n. 物品交换, 实物交易', '/\'bɑ:tə | \'bɑːtə | \'bɑrtɚ/', 'barter', 6);
INSERT INTO `words` VALUES (9328, 'base attitudes and desires', 'adj. 卑鄙的', '/beɪs | bes/', 'base', 6);
INSERT INTO `words` VALUES (9329, 'a bashful grin', 'adj. 害羞的', '/\'bæʃful | \'bæʃfʊl; -f(ə)l | \'bæʃfl/', 'bashful', 6);
INSERT INTO `words` VALUES (9330, 'Though modesty be a virtue , yet bashfulness is a vice.', 'n. 羞怯', '/\'bæʃfulnis | \'bæʃflnəs/', 'bashfulness', 6);
INSERT INTO `words` VALUES (9331, 'All through the hot, still days of their holiday Amy basked in the sun.', 'v. 晒太阳(享受温暖), 感到温暖, 愉快或舒适', '/bɑ:sk, bæsk | bɑːsk | bæsk/', 'bask', 6);
INSERT INTO `words` VALUES (9332, 'A clarinet and bassoon and other instruments start playing.', 'n. 低音管, 巴颂管', '/bə\'su:n | bə\'suːn | bə\'sun/', 'bassoon', 6);
INSERT INTO `words` VALUES (9333, 'Baste the potatoes occasionally.', 'v. 粗缝, 润以油脂, (在烤肉上)涂油, 狠揍, 大骂', '/beist | beɪst | best/', 'baste', 6);
INSERT INTO `words` VALUES (9334, 'Pearl Harbor was the principal American bastion in the Pacific.', 'n. 保垒， 防御工事', '/\'bæstiən | \'bæstɪən/', 'bastion', 6);
INSERT INTO `words` VALUES (9335, 'an overnight batch file', 'n. (面包等)一炉, 一批', '/bætʃ/', 'batch', 6);
INSERT INTO `words` VALUES (9336, NULL, 'v. 减弱, 减少, 抑制', '/beit | beɪt | bet/', 'bate', 6);
INSERT INTO `words` VALUES (9337, 'The maestro raises his baton.', 'n. 司令棒, 指挥棒, 警棍', '/\'bætən | bə\'tɑ:n | bə\'tɑn/', 'baton', 6);
INSERT INTO `words` VALUES (9338, 'To David, this was not just one more bauble in an already overcrowded jewelry box. Rather, this was his love displayed on my arm for all the world to see.', 'n. 小玩意', '/\'bɔ:bl | \'bɔːb(ə)l | \'bɔbl/', 'bauble', 6);
INSERT INTO `words` VALUES (9339, 'The plant makes alumina -- a derivative of the metal ore bauxite that is used to make aluminum.', 'n. 矾土, 铁铝氧石', '/\'bɔ:ksait | \'bɔːksaɪt | \'bɔksaɪt/', 'bauxite', 6);
INSERT INTO `words` VALUES (9340, 'a bawdy new play', 'adj. 卖淫的, 妓女的, 好色的', '/\'bɔ:di | \'bɔːdɪ | \'bɔdi/', 'bawdy', 6);
INSERT INTO `words` VALUES (9341, '‘Tickets, please!’ bawled the conductor.', 'n. 叫骂声', '/bɔ:l | bɔːl | bɔl/', 'bawl', 6);
INSERT INTO `words` VALUES (9342, 'Kamal was a vendor in Cairo\'s open-air bazaar.', 'n. 集市, 市场, 杂货店, 百货店', '/bə\'zɑ: | bə\'zɑː | bə\'zɑr/', 'bazaar', 6);
INSERT INTO `words` VALUES (9343, '...a huge office tower with aircraft warning beacons on the roof.', 'n. 烟火, 灯塔', '/\'bi:kən | \'biːk(ə)n | \'bikən/', 'beacon', 6);
INSERT INTO `words` VALUES (9344, 'a beaded dress', 'adj. 以珠装饰的， 珠状的', '/\'biːdɪd | \'bidɪd/', 'beaded', 6);
INSERT INTO `words` VALUES (9345, NULL, 'n. 大口杯, 有倾口的烧杯', '/\'bi:kə | \'biːkə | \'bikɚ/', 'beaker', 6);
INSERT INTO `words` VALUES (9346, '...high-energy laser beams.', 'n. 梁, 桁条, (光线的)束, 柱, 电波, 横梁', '/bi:m | biːm | bim/', 'beam', 6);
INSERT INTO `words` VALUES (9347, NULL, 'n. 关系， 意义； 方位', '/\'berɪŋ | \'bɛrɪŋ/', 'bearing', 6);
INSERT INTO `words` VALUES (9348, 'journalists covering the Washington beat', 'n. 敲打, 拍子, 巡逻区域', '/bi:t | biːt | bit/', 'beat', 6);
INSERT INTO `words` VALUES (9349, 'an egg beater', 'n. 搅拌器', '/\'bi:tə | \'biːtə | \'bitɚ/', 'beater', 6);
INSERT INTO `words` VALUES (9350, '...a beatific smile.', 'adj. 祝福的, 快乐的, 幸福的', '/,bi:ə\'tifik,-kəl | biːə\'tɪfɪk | ,biə\'tɪfɪk/', 'beatific', 6);
INSERT INTO `words` VALUES (9351, 'This beatitude is as vast as the Bible itself.', 'n. 至福, 祝福', '/bi（:）\'ætitju:d | bɪ\'ætɪtjuːd | bɪ\'ætɪtud/', 'beatitude', 6);
INSERT INTO `words` VALUES (9352, NULL, 'n. 喜修饰者, 纨绔子弟, 情郎, 求爱者', '/bəu | bəʊ | bo/', 'beau', 6);
INSERT INTO `words` VALUES (9353, '...a coat with a huge beaver collar.', 'n. 海狸(毛皮)', '/\'bi:və | \'biːvə | \'bivɚ/', 'beaver', 6);
INSERT INTO `words` VALUES (9354, 'I could see my husband beckoning me.', 'v. 召唤， 示意', '/\'bekən | \'bɛkən/', 'beckon', 6);
INSERT INTO `words` VALUES (9355, NULL, 'v. 涂污, 俗气地装饰', '/bi\'dɔ:b | bɪ\'dɔːb | bɪ\'dɔb/', 'bedaub', 6);
INSERT INTO `words` VALUES (9356, 'When the bomb exploded, there was bedlam.', 'n. 混乱, 骚乱情景, <古语>疯人院', '/\'bedləm | \'bɛdləm/', 'bedlam', 6);
INSERT INTO `words` VALUES (9357, 'He looked weary and bedraggled.', 'adj. 全身泥污的, 湿透的, 荒废的', '/bi\'dræɡld | bɪ\'dræɡld/', 'bedraggled', 6);
INSERT INTO `words` VALUES (9358, '...a beefy red-faced Englishman.', 'adj. 象牛肉的, 健壮的, 结实的', '/\'biːfɪ | \'bifi/', 'beefy', 6);
INSERT INTO `words` VALUES (9359, '...fields of sweet corn and beet.', 'n. 甜菜, 甜菜根', '/bi:t | biːt | bit/', 'beet', 6);
INSERT INTO `words` VALUES (9360, NULL, 'v. 弄脏， 诽谤', '/bɪ\'faul | bɪ\'faʊl/', 'befoul', 6);
INSERT INTO `words` VALUES (9361, 'They befriended me when I first arrived in London as a student.', 'v. 以朋友态度对待', '/bɪ\'frend | bi\'frend/', 'befriend', 6);
INSERT INTO `words` VALUES (9362, '...problems that are befuddling them.', 'v. 使迷惑不解； 使酒醉昏迷', '/bɪ\'fʌdl/', 'befuddle', 6);
INSERT INTO `words` VALUES (9363, 'Hunger begets crime.', 'v. (书面语) 招致, 产生, 引起', '/bi\'ɡet | bɪ\'get | bɪ\'ɡɛt/', 'beget', 6);
INSERT INTO `words` VALUES (9364, NULL, 'v. 围绕, 缚, 以带子缠绕', '/bi\'ɡə:d | bɪ\'gərd/', 'begird', 6);
INSERT INTO `words` VALUES (9365, 'I certainly don\'t begrudge him the Nobel Prize.', 'v. 嫉妒, 羡慕, 舍不得给', '/bi\'ɡrʌdʒ | bɪ\'grʌdʒ | bɪ\'ɡrʌdʒ/', 'begrudge', 6);
INSERT INTO `words` VALUES (9366, 'He used his newspapers to beguile the readers into buying shares in his company.', 'v. 诱骗, 诱惑', '/bi\'ɡail | bɪ\'gaɪl | bɪ\'ɡaɪl/', 'beguile', 6);
INSERT INTO `words` VALUES (9367, 'It was the kind of goal that must have made Manchester United\'s supporters wish Nani could always be so beguiling.', 'adj. 欺骗的, 消遣的', '/bi\'ɡailiŋ/', 'beguiling', 6);
INSERT INTO `words` VALUES (9368, 'The committee was set up at the behest of the president.', 'n. [诗]命令, 吩咐, 要求', '/bi\'hest | bɪ\'hest | bɪ\'hɛst/', 'behest', 6);
INSERT INTO `words` VALUES (9369, 'She looked into his eyes and beheld madness.', 'v. 注视， 看见', '/bɪ\'hould | bɪ\'hold/', 'behold', 6);
INSERT INTO `words` VALUES (9370, 'We feel really beholden to them for what they\'ve done.', 'adj. 因受恩惠而心存感激，感谢；欠人情', '/bɪ\'houldən | bɪ\'holdən/', 'beholden', 6);
INSERT INTO `words` VALUES (9371, 'In some ways, clean code -- like beauty -- is in the eye of the beholder.', 'n. 目睹者, 旁观者', '/bi\'həuldə | bɪ\'həʊldə | bɪ\'holdɚ/', 'beholder', 6);
INSERT INTO `words` VALUES (9372, 'If the other side tells your tort behoove quote should have all limits of authority of this project.', 'v. 理应， 有必要', '/bɪ\'huːv | bi\'hu:v/', 'behoove', 6);
INSERT INTO `words` VALUES (9373, NULL, 'v. 过分冗长地做或说； 痛打', '/bɪ\'leɪbər | bi\'lebə/', 'belabor', 6);
INSERT INTO `words` VALUES (9374, 'a line of chimneys belching out smoke', 'v. 打嗝, (火山、炮等)冒烟、喷出', '/beltʃ | bɛltʃ/', 'belch', 6);
INSERT INTO `words` VALUES (9375, 'Curiger sees “a lot of commonalities between the Venetian master\'s quest and the eagerness of some contemporary artists to defy the conventions which beleaguer art in our time.”', 'v. 围, 围攻', '/bi\'li:ɡə | bɪ\'liːgə/', 'beleaguer', 6);
INSERT INTO `words` VALUES (9376, 'Her pleasant manner belied her true character.', 'v. 掩饰', '/bi\'lai | bɪ\'laɪ/', 'belie', 6);
INSERT INTO `words` VALUES (9377, 'a story with believable characters in it', 'adj. 可信的', '/bɪ\'liːvəbl | bi\'li:vəbl/', 'believable', 6);
INSERT INTO `words` VALUES (9378, 'He tends to belittle her efforts.', 'v. 轻视， 贬低', '/bɪ\'lɪtl/', 'belittle', 6);
INSERT INTO `words` VALUES (9379, 'bellicose criticism', 'adj. 好战的, 好斗的', '/\'belikəus | \'belɪkəʊs/', 'bellicose', 6);
INSERT INTO `words` VALUES (9380, NULL, 'n. 交战； 好战性， 斗争性', '/bə\'lɪdʒərəns/', 'belligerence', 6);
INSERT INTO `words` VALUES (9381, 'a belligerent attitude', 'adj. 好战的, 交战国的, 交战的', '/bi\'lidʒərənt | bə\'lɪdʒ(ə)r(ə)nt/', 'belligerent', 6);
INSERT INTO `words` VALUES (9382, '‘That’s your problem!’ bellowed Hurley.', 'v. 咆哮； 吼叫', '/\'belou | \'bɛlo/', 'bellow', 6);
INSERT INTO `words` VALUES (9383, 'an insurance policy that covers your personal belongings', 'n. 财产, 所有物, 相关事物, 亲戚', '/bi\'lɔŋiŋz | bə\'lɔŋɪŋz/', 'belongings', 6);
INSERT INTO `words` VALUES (9384, 'The sheer quantity of detail would bemuse even the most clear-headed author.', 'v. 使昏头昏脑， 使迷惑', '/bɪ\'mjuːz | bɪ\'mjuz/', 'bemuse', 6);
INSERT INTO `words` VALUES (9385, 'a bemused expression', 'adj. 茫然的， 困惑的', '/bɪ\'mjuːzd | bɪ\'mjuzd/', 'bemused', 6);
INSERT INTO `words` VALUES (9386, 'The minister pronounced the benediction.', 'n. 祝福', '/,beni\'dikʃən | ,benɪ\'dɪkʃ(ə)n | \'bɛnə\'dɪkʃən/', 'benediction', 6);
INSERT INTO `words` VALUES (9387, 'An anonymous benefactor donated $2 million.', 'n. 恩人, 捐助者, 赠送者, 赞助人', '/\'benifæktə | \'benɪfæktə | \'bɛnɪfæktɚ/', 'benefactor', 6);
INSERT INTO `words` VALUES (9388, 'the beneficent properties of natural remedies', 'adj. 慈善的， 仁爱的； 有益的', '/bɪ\'nefɪsnt | bɪ\'nɛfɪsnt/', 'beneficent', 6);
INSERT INTO `words` VALUES (9389, 'a drug that has a beneficial effect on the immune system', 'adj. 有益的, 受益的, [法律]有使用权的', '/,beni\'fiʃəl | benɪ\'fɪʃ(ə)l | ,bɛnɪ\'fɪʃl/', 'beneficial', 6);
INSERT INTO `words` VALUES (9390, 'One of the main beneficiaries of the early election is thought to be the former president.', 'n. 受惠者, 受益人', '/,beni\'fiʃəri | benɪ\'fɪʃ(ə)rɪ | ,bɛnɪ\'fɪʃɪɛri/', 'beneficiary', 6);
INSERT INTO `words` VALUES (9391, NULL, 'n. 仁爱心, 善行', '/bi\'nevələns | bɪ\'nev(ə)l(ə)ns; bɪ\'nevəl(ə)ns; bɪ\'nevələns | bə\'nɛvələns/', 'benevolence', 6);
INSERT INTO `words` VALUES (9392, 'A benevolent uncle paid for her to have music lessons.', 'adj. 慈善的', '/bi\'nevələnt | bɪ\'nev(ə)l(ə)nt | bə\'nɛvələnt/', 'benevolent', 6);
INSERT INTO `words` VALUES (9393, 'Famine hit that benighted country once more.', 'adj. 赶路到天黑的, 愚昧的', '/bi\'naitid | bɪ\'naɪtɪd/', 'benighted', 6);
INSERT INTO `words` VALUES (9394, 'He shook his head in benign amusement.', 'adj. (病)良性的, (气候)良好的, 仁慈的, 和蔼的', '/bi\'nain | bɪ\'naɪn/', 'benign', 6);
INSERT INTO `words` VALUES (9395, 'We now of no scripture which records the pure benignity of the gods on a New England winter night.', 'n. 仁慈, 善行', '/bi\'niɡnəti | bɪ\'nɪɡnətɪ | bɪ\'nɪgnəti/', 'benignity', 6);
INSERT INTO `words` VALUES (9396, 'a bequest of $5,000', 'n. 遗产, 遗赠', '/bi\'kwest | bɪ\'kwest/', 'bequest', 6);
INSERT INTO `words` VALUES (9397, 'Marion berated Joe for the noise he made.', 'v. 严厉指责, 申斥', '/bi\'reit | bɪ\'reɪt | bɪ\'ret/', 'berate', 6);
INSERT INTO `words` VALUES (9398, 'Sin can never quite bereave a saint of his jewel his grace; but it may steal away the key of the cabinet his assurance.', 'v. 剥夺, 使失去', '/bi\'ri:v | bɪ\'riːv | bɪ\'riv/', 'bereave', 6);
INSERT INTO `words` VALUES (9399, 'The place seemed to be utterly bereft of human life.', 'adj. 被剥夺的, 失去亲人的, 丧失的', '/bi\'reft | bɪ\'reft | bɪ\'rɛft/', 'bereft', 6);
INSERT INTO `words` VALUES (9400, 'Dad went berserk when he found out.', 'adj. 狂怒的， 狂暴的', '/bər\'zɜːrk | bə\'sə:k/', 'berserk', 6);
INSERT INTO `words` VALUES (9401, 'Goldring booked a berth on the first boat he could.', 'n. 停泊处, 卧铺(口语)职业', '/bə:θ | bɜːθ | bɝθ/', 'berth', 6);
INSERT INTO `words` VALUES (9402, 'She beseeched him to cut out his drinking and his smoking.', 'v. 恳求, 哀求', '/bi\'si:tʃ | bɪ\'siːtʃ | bɪ\'sitʃ/', 'beseech', 6);
INSERT INTO `words` VALUES (9403, 'the injuries which have beset the team all season', 'v. 镶嵌； 困扰', '/bɪ\'set | bɪ\'sɛt/', 'beset', 6);
INSERT INTO `words` VALUES (9404, NULL, 'v. [古]诅咒(主要用于温和的诅咒), 该死!', '/bi\'ʃru: | bɪ\'ʃruː/', 'beshrew', 6);
INSERT INTO `words` VALUES (9405, 'In April 655, Osman’s palace was besieged by rebels.', 'v. 围困, 围攻, 包围', '/bi\'si:dʒ | bɪ\'siːdʒ | bɪ\'sidʒ/', 'besiege', 6);
INSERT INTO `words` VALUES (9406, 'He has accused local people of trying to besmirch his reputation.', 'v. 弄污', '/bi\'smə:tʃ | bɪ\'smɜːtʃ/', 'besmirch', 6);
INSERT INTO `words` VALUES (9407, NULL, 'v. 使烂醉, 使迷糊, 使沉醉', '/bi\'sɔt | bɪ\'sɒt | bɪ\'sɑt/', 'besot', 6);
INSERT INTO `words` VALUES (9408, 'Today\'s events bespeak a bright future.', 'v. 预订', '/bi\'spi:k | bɪ\'spiːk | bɪ\'spik/', 'bespeak', 6);
INSERT INTO `words` VALUES (9409, 'The United States bestowed honorary citizenship upon England\'s World War II prime minister, Sir Winston Churchill.', 'v. 给予, 安放', '/bi\'stəu | bɪ\'stəʊ | bɪ\'sto/', 'bestow', 6);
INSERT INTO `words` VALUES (9410, 'The president alone betokened the national identity.', 'v. 预示， 表示', '/bɪ\'toukən | bɪ\'tokən/', 'betoken', 6);
INSERT INTO `words` VALUES (9411, 'He felt that she had betrayed him.', 'v. 背叛； 暴露', '/bɪ\'treɪ | bɪ\'tre/', 'betray', 6);
INSERT INTO `words` VALUES (9412, 'Beer is a beverage of the remotest time.', 'n. 饮料', '/\'bevəridʒ | \'bev(ə)rɪdʒ | \'bɛvərɪdʒ/', 'beverage', 6);
INSERT INTO `words` VALUES (9413, '...a bevy of bright young officers.', 'n. 一群鸟, 一群(少女或少妇), <俗>一堆东西, 一群人', '/\'bevi | \'bevɪ/', 'bevy', 6);
INSERT INTO `words` VALUES (9414, 'He was bewildered by his daughter’s reaction.', 'v. 使迷惑， 混乱', '/bɪ\'wɪldər | bɪ\'wɪldɚ/', 'bewilder', 6);
INSERT INTO `words` VALUES (9415, 'A glance along his bookshelves reveals a bewildering array of interests.', 'adj. 令人困惑的； 令人费解的', '/bɪ\'wɪldərɪŋ/', 'bewildering', 6);
INSERT INTO `words` VALUES (9416, NULL, 'v. <古>泄露, 暴露, 显示', '/bi\'rei | bɪ\'reɪ/', 'bewray', 6);
INSERT INTO `words` VALUES (9417, 'Several factors could have biased the results of the study.', 'v. 使有偏见; n. 偏见', '/\'baɪəs/', 'bias', 6);
INSERT INTO `words` VALUES (9418, '...a publisher of bibles and hymn books.', 'n. 《圣经》', '/\'baibl | \'baɪb(ə)l | \'baɪbl/', 'Bible', 6);
INSERT INTO `words` VALUES (9419, 'At the end of this chapter there is a select bibliography of useful books.', 'n. (有关一个题目或一个人的)书目, 参考书目', '/,bibli\'ɔɡrəfi | ,bɪblɪ\'ɒgrəfɪ | ,bɪblɪ\'ɑɡrəfi/', 'bibliography', 6);
INSERT INTO `words` VALUES (9420, NULL, 'n. 藏书癖', '/ˌbɪblɪə\'menɪə | ,bɪblɪə\'menɪə/', 'bibliomania', 6);
INSERT INTO `words` VALUES (9421, 'But it can control the bibulous of handsheet in the demanding range through accession suitable waterproof.', 'adj. 饮酒的, 嗜酒的, 吸水的', '/\'bibjuləs | \'bɪbjʊləs/', 'bibulous', 6);
INSERT INTO `words` VALUES (9422, 'I went into medicine to care for patients, not to waste time bickering over budgets.', 'v. 斗嘴, 流动, 闪动', '/\'bikə | \'bɪkə | \'bɪkɚ/', 'bicker', 6);
INSERT INTO `words` VALUES (9423, 'She wanted to bid for it.', 'v. 命令； 出价， 投标', '/bɪd/', 'bid', 6);
