INSERT INTO `words` VALUES (9425, 'They are stronger than us and can afford to bide their time.', 'v. 等待， 逗留', '/baɪd | baid/', 'bide', 6);
INSERT INTO `words` VALUES (9426, 'The blood supply bifurcates between eight and thirty times before reaching each particular location in the body.', 'v. (使)分叉', '/\'baifəkeit | \'baɪfəkeɪt | \'baɪfɚ\'ket/', 'bifurcate', 6);
INSERT INTO `words` VALUES (9427, 'racist bigots', 'n. 盲目信仰者, 顽固者', '/\'biɡət | \'bɪgət | \'bɪɡət/', 'bigot', 6);
INSERT INTO `words` VALUES (9428, 'He deplored religious bigotry.', 'n. 固执, 顽固', '/\'biɡətri | \'bɪgətrɪ | \'bɪɡətri/', 'bigotry', 6);
INSERT INTO `words` VALUES (9429, '...bilateral talks between Britain and America.', 'adj. 两边的； 双边的', '/ˌbaɪ\'lætərəl | ,baɪ\'lætərəl/', 'bilateral', 6);
INSERT INTO `words` VALUES (9430, 'He aims his bile at religion, drugs, and politics.', 'n. 胆汁, 愤怒', '/bail | baɪl/', 'bile', 6);
INSERT INTO `words` VALUES (9431, NULL, 'n. 舱底', '/bildʒ | bɪldʒ/', 'bilge', 6);
INSERT INTO `words` VALUES (9432, 'a bilingual dictionary', 'adj. 能说两种语言的', '/bai\'liŋɡwəl | baɪ\'lɪŋgw(ə)l | \'baɪ\'lɪŋgwəl/', 'bilingual', 6);
INSERT INTO `words` VALUES (9433, 'She felt a bilious attack coming on.', 'adj. 胆汁质的, 坏脾气的', '/\'biljəs | \'bɪlɪəs/', 'bilious', 6);
INSERT INTO `words` VALUES (9434, 'They are charged with bilking investors out of millions of dollars.', 'v. 躲债； 骗取', '/bɪlk | bilk/', 'bilk', 6);
INSERT INTO `words` VALUES (9435, 'The final cost could be as much as one billion dollars.', 'num. 十亿', '/\'bɪljən/', 'billion', 6);
INSERT INTO `words` VALUES (9436, 'Put your rubbish in the bin.', 'n. 大箱子', '/bɪn/', 'bin', 6);
INSERT INTO `words` VALUES (9437, 'This is especially important after a tough run or workout, when you may feel that a big-calorie binge is justified.', 'n. 狂闹, 狂欢', '/bindʒ | bɪn(d)ʒ | bɪndʒ/', 'binge', 6);
INSERT INTO `words` VALUES (9438, 'But what climate change shows us is that we are not in control, either of the biosphere or of the machine which is destroying it.', 'n. 生物圈', '/\'baiəsfiə | \'baɪə(ʊ)sfɪə | \'baɪosfɪr/', 'biosphere', 6);
INSERT INTO `words` VALUES (9439, 'In Finland purists insist that only birch bark should be added.', 'n. 桦树, 白桦', '/bə:tʃ | bɜːtʃ | bɝtʃ/', 'birch', 6);
INSERT INTO `words` VALUES (9440, 'Freedom of speech is every American’s birthright.', 'n. 与生俱来的权利', '/\'bɜːrθraɪt | \'bɝθraɪt/', 'birthright', 6);
INSERT INTO `words` VALUES (9441, 'Were they to throw together a bivouac on the moon\'s frozen surface, or simply wander the wastes like some misguided flock until the mechas\' power and life-support systems failed?', 'n. 露营, 野营, 露营地', '/\'bivuæk | \'bɪvʊæk; \'bɪvwæk | \'bɪvuæk/', 'bivouac', 6);
