INSERT INTO `words` VALUES (9448, 'Patrick visibly blanched.', 'v. 漂白, 使变白, 遮断阳光发白', '/blɑ:ntʃ, blæntʃ | blɑːn(t)ʃ | blæntʃ/', 'blanch', 6);
INSERT INTO `words` VALUES (9449, 'a few bland comments', 'adj. 温和的, 柔和的, 乏味的, 冷漠的, 刺激性少的', '/blænd/', 'bland', 6);
INSERT INTO `words` VALUES (9450, 'You know blandishment ceaselessly cannot be done by everyone.', 'n. 奉承， 讨好', '/\'blændɪʃmənt | \'blændiʃmənt/', 'blandishment', 6);
INSERT INTO `words` VALUES (9451, 'Influencing the local press has always been part of ISI operations, usually through bribes, blandishments or intimidation.', 'n. 哄骗，劝诱', '/\'blændiʃmənts | \'blændɪʃmənts/', 'blandishments', 6);
INSERT INTO `words` VALUES (9452, 'The blare of the car horn alerted the members of the Story family who realised 17-year-old Ben\'s Toyota was no longer parked in the driveway of their home in Larkspur near Denver.', 'n. 号声', '/blεə | bleə | blɛr/', 'blare', 6);
