INSERT INTO `words` VALUES (9454, 'They are blasé about their driving skills.', 'adj. 厌倦享乐的， 玩厌了的', '/blɑː\'zeɪ/', 'blasé', 6);
INSERT INTO `words` VALUES (9455, NULL, 'adj. 厌烦于享乐的', '/\'bla:zei/', 'blase', 6);
INSERT INTO `words` VALUES (9456, 'She was accused of being blasphemous.', 'adj. 亵渎神明的, 不敬神的', '/blæsfəməs | \'blæsfəməs | \'blæsfɪməs/', 'blasphemous', 6);
INSERT INTO `words` VALUES (9457, 'He has acted out every kind of blasphemy, including dressing up as the pope in Rome.', 'n. 亵渎(话)', '/\'blæsfəmi | \'blæsfəmɪ/', 'blasphemy', 6);
INSERT INTO `words` VALUES (9458, 'blatant discrimination', 'adj. 喧嚣的, 俗丽的, 吵闹的, 炫耀的', '/\'bleitənt | \'bleɪt(ə)nt/', 'blatant', 6);
INSERT INTO `words` VALUES (9459, 'The old men blather on and on.', 'v. 喋喋不休地胡说， 唠叨', '/\'blæðər | \'blæðɚ/', 'blather', 6);
INSERT INTO `words` VALUES (9460, 'a blazing August afternoon', 'adj. 炽烧的， 闪耀的', '/\'bleɪzɪŋ | \'blezɪŋ/', 'blazing', 6);
