INSERT INTO `words` VALUES (9467, 'The conflict among the interest groups is a political puzzle unable to blench for all the societies of all ages.', 'v. 畏缩, 回避', '/blentʃ | blen(t)ʃ | blɛntʃ/', 'blench', 6);
