INSERT INTO `words` VALUES (9481, 'His beautiful blocky head his wonderful overgrown puppy’s body his baritone bark filled every corner of house and heart.', 'adj. 短而结实的, 斑驳的', '/\'blɔki | \'blɒkɪ | \'blɑki/', 'blocky', 6);
