INSERT INTO `words` VALUES (9760, 'Our door knocker is cast in solid brass.', 'v. 扔； 铸造 by pouring in liquid into a mold); n. 演员阵容；剧团', '/kæst/', 'cast', 6);
INSERT INTO `words` VALUES (9761, 'the caste system', 'n. 印度的世袭阶级, (排他的)社会团体, 职业等级, (具有严格等级的)社会地位, 社会等级制度', '/kɑ:st, kæst | kɑːst | kæst/', 'caste', 6);
INSERT INTO `words` VALUES (9762, 'Marx never lost an opportunity to castigate colonialism.', 'v. 严惩', '/\'kæstiɡeit | \'kæstɪgeɪt/', 'castigate', 6);
INSERT INTO `words` VALUES (9763, NULL, 'n. 惩罚, 苛责, 修订', '/,kæsti\'geiʃən/', 'castigation', 6);
INSERT INTO `words` VALUES (9764, 'a casual manner', 'adj. 偶然的； 非正式的， 随便的', '/\'kæʒuəl | \'kæʒʊəl/', 'casual', 6);
INSERT INTO `words` VALUES (9765, NULL, 'n. 灾难, 大洪水, 地震, (社会政治的)大变动', '/\'kætəklizəm | \'kætə,klɪz(ə)m | \'kætəklɪzəm/', 'cataclysm', 6);
INSERT INTO `words` VALUES (9766, 'Can you catalog all these books?', 'n. 目录； 系列', '/\'kætəlɔːg | \'kætəlɔg/', 'catalog', 6);
INSERT INTO `words` VALUES (9767, 'He invented ammonia synthesis with catalysis by iron.', 'n. 催化作用', '/kə\'tælisis | kə\'tælɪsɪs/', 'catalysis', 6);
INSERT INTO `words` VALUES (9768, 'I very much hope that this case will prove to be a catalyst for change.', 'n. 催化剂', '/\'kætəlist | \'kæt(ə)lɪst | \'kætəlɪst/', 'catalyst', 6);
INSERT INTO `words` VALUES (9769, NULL, 'v. 促使； 激励', '/\'kætəlaɪz | \'kætə,laɪz/', 'catalyze', 6);
INSERT INTO `words` VALUES (9770, 'From all points of view, war would be a catastrophe.', 'n. 突如其来的大灾难', '/kə\'tæstrəfi/', 'catastrophe', 6);
INSERT INTO `words` VALUES (9771, 'With an almost catatonic concentration, almost without blinking or licking my lips, I read the entire book from first to last word without stopping.', 'n. 紧张性精神症患者', '/,kætə\'tɔnik | kætə\'tɒnɪk | ,kætə\'tɑnɪk/', 'catatonic', 6);
INSERT INTO `words` VALUES (9772, 'But the world is also scattered with tales of roof catchment failures — and academics who say its potential for ending water insecurity is oversold.', 'n. 集水, 集水处(水库或集水盆地)', '/\'kætʃmənt | \'kætʃm(ə)nt/', 'catchment', 6);
INSERT INTO `words` VALUES (9773, NULL, 'adj. 无条件的, 绝对的, 直接了当的(陈述、理论等)', '/kætɪ\'gɒrɪk(ə)l | ,kætə\'ɡɔrɪkl/', 'categorical', 6);
INSERT INTO `words` VALUES (9774, 'people in the over-45 age category', 'n. 种类, 别, [逻]范畴', '/\'kætiɡəri | \'kætɪg(ə)rɪ | \'kætəɡɔri/', 'category', 6);
INSERT INTO `words` VALUES (9775, 'The word \'concatenate\' is just a verbose synonym for \'catenate\'.', 'v. 连接, 使连续', '/\'kætineit | \'kætɪneɪt/', 'catenate', 6);
INSERT INTO `words` VALUES (9776, 'We cater to an exclusive clientele.', 'v. 备办食物, 满足(需要), 投合', '/\'keitə | \'keɪtə | \'ketɚ/', 'cater', 6);
INSERT INTO `words` VALUES (9777, 'A caterpillar transforms into a butterfly.', 'n. 毛虫', '/\'kætəpilə | \'kætəpɪlə | \'kætɚpɪlɚ/', 'caterpillar', 6);
INSERT INTO `words` VALUES (9778, 'Music is a means of catharsis for me.', 'n. [医]导泻(尤指通便), 泻法, [精神病](精神或心理)疏泄, 宣泄', '/kə\'θɑ:sis | kə\'θɑːsɪs | kə\'θɑrsɪs/', 'catharsis', 6);
INSERT INTO `words` VALUES (9779, NULL, 'n. 泻药, 通便药', '/kə\'θɑ:tik | kə\'θɑːtɪk | kə\'θɑrtɪk/', 'cathartic', 6);
INSERT INTO `words` VALUES (9780, 'And if I evacuate it, I have a cathode ray tube.', 'n. 阴极', '/\'kæθəʊd | \'kæθod/', 'cathode', 6);
INSERT INTO `words` VALUES (9781, 'At least nine out of ten Mexicans are baptized Catholics.', 'n. 天主教徒', '/\'kæθəlik | kæθəlɪk/', 'catholic', 6);
INSERT INTO `words` VALUES (9782, 'the chairman of the Congressional Black Caucus', 'n. (政党的)领导人秘密会议, 核心小组会议', '/\'kɔːkəs | \'kɔkəs/', 'caucus', 6);
INSERT INTO `words` VALUES (9783, 'Craig Dietz, a US man born armless and legless, took part in a swimming competition in Pennsylvania recently with the help of a manmade caudal fin and finished 275th out of 308 participants.', 'adj. 尾部的, 近尾部的', '/\'kɔ:dəl | \'kɔːd(ə)l | \'kɔdl/', 'caudal', 6);
INSERT INTO `words` VALUES (9784, 'The sailors couldn\'t find anything to caulk the seam in the boat.', 'v. 填塞使不漏水', '/kɔːk | kɔk/', 'caulk', 6);
INSERT INTO `words` VALUES (9785, 'Rawlins stresses that it is impossible to prove a causal link between the drug and the deaths.', 'adj. 原因的， 因果关系的', '/\'kɔːzl | \'kɔzl/', 'causal', 6);
INSERT INTO `words` VALUES (9786, 'caustic soda (= a chemical used for cleaning things )', 'adj. 腐蚀性的, 刻薄的', '/\'kɔ:stik | \'kɔːstɪk; \'kɒst- | \'kɔstɪk/', 'caustic', 6);
INSERT INTO `words` VALUES (9787, 'He cauterized the wound with a piece of red-hot iron.', 'v. 烧灼以消毒或止血', '/\'kɔːtəraɪz | \'kɔ:təraiz/', 'cauterize', 6);
INSERT INTO `words` VALUES (9788, 'Barely fifteen months later, it has become a cautionary tale of the pitfalls of international mergers and acquisitions.', 'adj. 劝人谨慎的， 警戒的', '/\'kɔːʃəneri | \'kɔʃənɛri/', 'cautionary', 6);
INSERT INTO `words` VALUES (9789, 'a cautious driver', 'adj. 小心的， 谨慎的', '/\'kɔːʃəs | \'kɔʃəs/', 'cautious', 6);
INSERT INTO `words` VALUES (9790, '...a cavalcade of limousines and police motorcycles.', 'n. 队伍', '/,kævəl\'keid | ,kæv(ə)l\'keɪd; \'kæv(ə)lkeɪd | \'kævl\'ked/', 'cavalcade', 6);
INSERT INTO `words` VALUES (9791, NULL, 'n. 骑士, 武士, 对女人献殷勤, 有礼貌的绅士', '/,kævə\'liə | ,kævə\'lɪə | ,kævə\'lɪr/', 'cavalier', 6);
INSERT INTO `words` VALUES (9792, 'The Black Prince led a cavalry charge against them.', 'n. 骑兵', '/\'kævəlri | \'kæv(ə)lrɪ | \'kævlri/', 'cavalry', 6);
INSERT INTO `words` VALUES (9793, NULL, 'n. 巨洞, 洞窟, 深处', '/\'kævən | \'kæv(ə)n | \'kævɚn/', 'cavern', 6);
INSERT INTO `words` VALUES (9794, 'Let us not cavil too much.', 'v. 挑剔, 找错', '/\'kævil | \'kæv(ə)l | \'kævl/', 'cavil', 6);
INSERT INTO `words` VALUES (9795, 'Put herbs inside the body cavity of the fish.', 'n. 洞, 空穴, [解剖]腔', '/\'kævəti | \'kævɪtɪ/', 'cavity', 6);
INSERT INTO `words` VALUES (9796, 'Satisfied, sun-warmed, we sprawl in the grass and watch our kites cavort.', 'v. 腾跃， 欢跃', '/kə\'vɔːrt/', 'cavort', 6);
INSERT INTO `words` VALUES (9797, 'That is what the regime fears most, because then it either has to shoot its own people or cede power.', 'v. 放弃', '/si:d | siːd | sid/', 'cede', 6);
INSERT INTO `words` VALUES (9798, 'a celebrated actress', 'adj. 著名的', '/\'selibreitid | \'selɪbreɪtɪd | \'sɛlə\'bretɪd/', 'celebrated', 6);
INSERT INTO `words` VALUES (9799, 'a sporting celebrity', 'n. 名声, 名人', '/si\'lebrəti | sɪ\'lebrɪtɪ | sə\'lɛbrəti/', 'celebrity', 6);
INSERT INTO `words` VALUES (9800, 'It is an effective liquid separation tool with advantages such as simpleness, celerity and veracity.', 'n. 敏捷, 快速', '/si\'lerəti | sɪ\'lerɪtɪ | sə\'lɛrəti/', 'celerity', 6);
INSERT INTO `words` VALUES (9801, '...the clusters of celestial bodies in the ever-expanding universe.', 'adj. 天上的', '/si\'lestjəl | sɪ\'lestɪəl | sə\'lɛstʃəl/', 'celestial', 6);
INSERT INTO `words` VALUES (9802, '...priests who violate their vows of celibacy.', 'n. 独身生活', '/\'selibəsi | \'selɪbəsɪ | \'sɛləbəsi/', 'celibacy', 6);
INSERT INTO `words` VALUES (9803, '...the U.S.A.\'s biggest group of celibates.', 'n. 独身者, 独身主义者', '/\'selibət | \'selɪbət | \'sɛlɪbət/', 'celibate', 6);
INSERT INTO `words` VALUES (9804, 'a coal cellar', 'n. 地窖, 地下室, 酒窖, 藏酒量', '/\'selə | \'sɛlɚ/', 'cellar', 6);
INSERT INTO `words` VALUES (9805, 'She plays the cello in an orchestra.', 'n. 大提琴', '/\'tʃelou | \'tʃɛlo/', 'cello', 6);
INSERT INTO `words` VALUES (9806, 'a cellular network', 'adj. 细胞的； 蜂窝式的', '/\'seljələr | \'sɛljəlɚ/', 'cellular', 6);
INSERT INTO `words` VALUES (9807, 'Nothing cements a friendship between countries so much as trade.', 'v. 黏合， 巩固; n. 水泥；黏合剂', '/sɪ\'ment | sə\'mɛnt/', 'cement', 6);
INSERT INTO `words` VALUES (9808, 'Her father was laid in a cemetery.', 'n. 墓地, 公墓', '/\'semitəri | \'semɪtrɪ | \'sɛmə\'tɛri/', 'cemetery', 6);
INSERT INTO `words` VALUES (9809, 'The report was cleared by the American military censors.', 'n. 检查员', '/\'sensə | \'sɛnsɚ/', 'censor', 6);
INSERT INTO `words` VALUES (9810, 'His tone was censorious.', 'adj. 受批判的, 挑剔的', '/sen\'sɔ:riəs | sen\'sɔːrɪəs | sɛn\'sɔrɪəs/', 'censorious', 6);
INSERT INTO `words` VALUES (9811, 'censorship of books', 'n. 审查机构, 审查制度', '/\'sensəʃip | \'sensəʃɪp | \'sɛnsɚ\'ʃɪp/', 'censorship', 6);
INSERT INTO `words` VALUES (9812, 'He was officially censured for his handling of the situation.', 'v. 责难', '/\'senʃə | \'sɛnʃɚ/', 'censure', 6);
INSERT INTO `words` VALUES (9813, 'Two of the most important dimensions of structure are centralization and departmentalization.', 'n. 集中； 集权化', '/英 [ˌsentrəlaɪ\'zeɪʃn] 美 [ˌsentrəlaɪ\'zeɪʃn] | ˌsentrələ\'zeɪʃn/', 'centralization', 6);
INSERT INTO `words` VALUES (9814, 'If the star spun just 20% faster, the centrifugal force would fling it apart.', 'adj. 离心的', '/sen\'trifjuɡəl | ,sentrɪ\'fjuːg(ə)l; sen\'trɪfjʊg(ə)l | sɛn\'trɪfjəgl/', 'centrifugal', 6);
INSERT INTO `words` VALUES (9815, 'The centripetal and centrifugal forces acting in opposition to each other keep our planet in her orbit.', 'adj. 向心的，利用向心力的', '/sen\'tripitəl | ,sentrɪ\'piːt(ə)l; sen\'trɪpɪt(ə)l | sɛn\'trɪpɪtl/', 'centripetal', 6);
INSERT INTO `words` VALUES (9816, 'Conclusion The cephalic vein or basilic vein in the elbow can be chosen for centripetal puncture during the early period of arteriovenous internal fistula in hemodialysis patients.', 'adj. [字尾]头的', '/si\'fælik, ke\'f- | sɪ\'fælɪk; ke- | sɪ\'fælɪk/', 'cephalic', 6);
INSERT INTO `words` VALUES (9817, 'I make ceramic cups there. Do you remember the gift I gave you for your last birthday? Those two cups?', 'adj. 陶器的; n. 陶瓷制品', '/sə\'ræmɪk/', 'ceramic', 6);
INSERT INTO `words` VALUES (9818, 'an exhibition of ceramics', 'n. 制陶术, 制陶业', '/si\'ræmiks | sə\'ræmɪks/', 'ceramics', 6);
INSERT INTO `words` VALUES (9819, 'a bowl of breakfast cereal', 'n. 谷类食品, 谷类', '/\'siəriəl | \'sɪərɪəl | \'sɪrɪəl/', 'cereal', 6);
INSERT INTO `words` VALUES (9820, 'a cerebral haemorrhage', 'adj. 脑的, 大脑的', '/\'seribrəl | \'serɪbr(ə)l; sə\'riːbr(ə)l | sə\'ribrəl/', 'cerebral', 6);
INSERT INTO `words` VALUES (9821, 'We should attend to the image in the expressional dimension has more abundant cerebration.', 'n. 用脑,思考', '/,seri\'breiʃən/', 'cerebration', 6);
INSERT INTO `words` VALUES (9822, 'While the cerebrum is unnecessary for basic survival responses, we still use far more than 10 percent of our brains.', 'n. 大脑', '/\'seribrəm | \'serɪbrəm | sə\'ribrəm/', 'cerebrum', 6);
INSERT INTO `words` VALUES (9823, 'Putting on a hat can be a ceremonious act, an elegant gesture in the ritual of dressing.', 'adj. 仪式隆重的', '/ˌserə\'mouniəs/', 'ceremonious', 6);
INSERT INTO `words` VALUES (9824, 'a wedding ceremony', 'n. 典礼， 仪式', '/\'serəmouni | ˈsɛrəˌmoʊni/', 'ceremony', 6);
INSERT INTO `words` VALUES (9825, 'He usually does quite well, but it’s not a certainty.', 'n. 确定的事情', '/\'sɜːrtnti | \'sɝtnti/', 'certainty', 6);
INSERT INTO `words` VALUES (9826, 'We successfully completed the certification for open water diving.', 'n. 证明', '/ˌsɜːrtɪfɪ\'keɪʃn | ,sɝtɪfɪ\'keʃən/', 'certification', 6);
INSERT INTO `words` VALUES (9827, 'Doubt and certitude are subjective reactions to the evidence.', 'n. 确定无疑', '/\'sɜːrtɪtuːd | \'sə:titju:d/', 'certitude', 6);
INSERT INTO `words` VALUES (9828, 'Future work should include: 1) isolating a large number of cervine microsatellite loci, 2) constructing genetic and physical maps of microsatellite loci.', 'adj. 鹿的, 鹿一样的', '/\'sə:vain | \'sɜːvaɪn | \'sɝvaɪn/', 'cervine', 6);
INSERT INTO `words` VALUES (9829, 'He would not agree to a cessation of hostilities.', 'n. 停止', '/se\'seiʃən | se\'seɪʃ(ə)n | sɛ\'seʃən/', 'cessation', 6);
INSERT INTO `words` VALUES (9830, 'Spanish cession of the territory in 1818', 'n. 割让, 转让, [律]让与(他人)债权', '/\'seʃən | \'seʃ(ə)n | \'sɛʃən/', 'cession', 6);
INSERT INTO `words` VALUES (9831, 'Based on what we know, I’d guess that cetacean culture is intermediate between humans and chimpanzees.', 'adj. 鲸类的, 鲸的', '/si\'teiʃjən | sɪ\'teɪʃn | sɪ\'teʃən/', 'cetacean', 6);
INSERT INTO `words` VALUES (9832, 'Wear a T-shirt under your wet suit to stop it chafing.', 'v. 擦热， 擦破； 激怒', '/tʃeɪf | tʃef/', 'chafe', 6);
INSERT INTO `words` VALUES (9833, NULL, 'n. 谷壳, 糠, 愚弄', '/tʃɑ:f, tʃæf | tʃɑːf; tʃæf | tʃæf/', 'chaff', 6);
INSERT INTO `words` VALUES (9834, NULL, 'adj. 玩笑的， 嘲弄的', '/\'tʃæfiŋ | \'tʃæfɪŋ/', 'chaffing', 6);
INSERT INTO `words` VALUES (9835, 'To the chagrin of their parents, neither Phil nor Pam went to church anymore.', 'n. 懊恼, 气愤, 委屈', '/\'ʃæɡrin | \'ʃægrɪn; ʃə\'grɪn | ʃə\'ɡrɪn/', 'chagrin', 6);
INSERT INTO `words` VALUES (9836, 'The chameleon survives by blending in with its background.', 'n. 变色龙', '/kə\'mi:liən | kə\'miːlɪən | kə\'miljən/', 'chameleon', 6);
INSERT INTO `words` VALUES (9837, 'Acting professionally is a chancy business.', 'adj. 不确定的， 不安的', '/\'tʃænsi | \'tʃɑ:nsi/', 'chancy', 6);
INSERT INTO `words` VALUES (9838, 'This gorgeous piece is our first attempt at building a very cool old style chandelier complete with crystals, but giving it quite a cutting edge look.', 'n. 树枝形的装饰灯', '/,ʃændə\'liə | ,ʃændə\'lɪə | ,ʃændə\'lɪr/', 'chandelier', 6);
INSERT INTO `words` VALUES (9839, 'a priest chanting the liturgy', 'v. 歌唱， 吟诵; n. 圣歌', '/tʃænt/', 'chant', 6);
INSERT INTO `words` VALUES (9840, NULL, 'n. 船歌', '/\'ʃæntɪ | \'ʃænti/', 'chantey', 6);
INSERT INTO `words` VALUES (9841, 'The country was plunged into economic chaos.', 'n. 混乱, 混沌(宇宙未形成前的情形)', '/\'keiɔs | \'keɪɒs | \'keɑs/', 'chaos', 6);
INSERT INTO `words` VALUES (9842, 'a chaotic mixture of images', 'adj. 混乱的, 无秩序的', '/kei\'ɔtik | keɪ\'ɒtɪk | ke\'ɑtɪk/', 'chaotic', 6);
INSERT INTO `words` VALUES (9843, 'a decent sort of chap', 'n. <俗>伙伴, 家伙, 小伙子, 颚, 颊', '/tʃæp/', 'chap', 6);
INSERT INTO `words` VALUES (9844, 'Every girl needs a chaperon. Cosette could not have come without M. Fauchelevent.', 'n. 女伴', '/\'ʃæpərɔn/', 'chaperon', 6);
INSERT INTO `words` VALUES (9845, NULL, 'n. 家伙', '/\'tʃæpi/', 'chappy', 6);
INSERT INTO `words` VALUES (9846, 'Roast the peppers until the skin begins to char and blister.', 'v. 烧焦； 把…烧成炭', '/tʃɑːr | tʃɑr/', 'char', 6);
INSERT INTO `words` VALUES (9847, 'the highly characteristic (= very typical ) flint walls of the local houses', 'adj. 有特色的；典型性的; n. 与众不同的特征', '/ˌkærəktə\'rɪstɪk | ,kærəktə\'rɪstɪk/', 'characteristic', 6);
INSERT INTO `words` VALUES (9848, 'Pilcher’s books have humour, good characterization, and lively dialogue.', 'n. 描述, 人物之创造', '/,kærəktərai\'zeiʃən, -ri\'z- | ,kærəktəraɪ\'zeʃən/', 'characterization', 6);
INSERT INTO `words` VALUES (9849, 'Bright colours characterize his paintings.', 'v. 表现…的特色， 刻画…的性格', '/\'kærəktəraɪz | \'kærəktə\'raɪz/', 'characterize', 6);
INSERT INTO `words` VALUES (9850, 'So we play out this charade of happy families and most of the time life trundles along much as before, more or less happily.', 'v. 凭动作猜字谜; n. 猜字谜游戏', '/ʃə\'reɪd | ʃə\'red/', 'charade', 6);
INSERT INTO `words` VALUES (9851, 'He lacks charisma.', 'n. 超凡魅力, 感召力, 教皇般的指导力', '/kə\'rizmə | kə\'rɪzmə/', 'charisma', 6);
INSERT INTO `words` VALUES (9852, 'Martin Luther King was a very charismatic speaker.', 'adj. 神赐能力的, 超凡魅力的', '/,kæriz\'mætik | kærɪz\'mætɪk | ,kærɪz\'mætɪk/', 'charismatic', 6);
INSERT INTO `words` VALUES (9853, 'charitable groups', 'adj. 仁慈的, (为)慈善事业的,宽恕的', '/\'tʃærətəbl | \'tʃærɪtəb(ə)l/', 'charitable', 6);
INSERT INTO `words` VALUES (9854, 'Several charities sent aid to the flood victims.', 'n. 慈善, 施舍, 慈善团体', '/\'tʃærəti | \'tʃærɪtɪ/', 'charity', 6);
INSERT INTO `words` VALUES (9855, 'The charlatan boasted that he could charm off any disease.', 'n. 江湖郎中， 骗子', '/\'ʃɑːrlətən | \'ʃɑrlətən/', 'charlatan', 6);
INSERT INTO `words` VALUES (9856, 'We were charmed by the friendliness of the local people.', 'v. 吸引， 迷住; n. 魅力；咒语，咒符', '/tʃɑːrm | tʃɑrm/', 'charm', 6);
INSERT INTO `words` VALUES (9857, 'Each team was responsible for making its own decisions and charting its own course.', 'v. 绘制地图， 制订计划; n. 图表', '/tʃɑːrt | tʃɑrt/', 'chart', 6);
INSERT INTO `words` VALUES (9858, 'We chartered a boat to take us to some of the smaller islands.', 'v. 租, 包(船、车等)', '/\'tʃɑ\'tə | \'tʃɑːtə | \'tʃɑrtɚ/', 'charter', 6);
INSERT INTO `words` VALUES (9859, 'I am chary of making too many idiotic mistakes.', 'adj. 仔细的, 谨慎的, 吝啬的', '/\'tʃεəri | \'tʃeərɪ | ˈtʃeri/', 'chary', 6);
INSERT INTO `words` VALUES (9860, 'a high-speed car chase', 'n. 追赶, 追击', '/tʃeis | tʃeɪs/', 'chase', 6);
INSERT INTO `words` VALUES (9861, 'a rope bridge across the chasm', 'n. 深坑, 裂口', '/\'kæzəm | \'kæz(ə)m/', 'chasm', 6);
INSERT INTO `words` VALUES (9862, 'The new Focus will be built on one platform and will have the same engine, transmission, chassis and main body in all the markets where it is sold.', 'n. 底盘', '/\'ʃæsi | \'ʃæsɪ; -iː/', 'chassis', 6);
INSERT INTO `words` VALUES (9863, 'She led a chaste decent life.', 'adj. 贞洁的, (思想, 言论, 尤其是性的节操)有道德的, 朴素的', '/tʃeist | tʃeɪst | tʃest/', 'chaste', 6);
INSERT INTO `words` VALUES (9864, 'Party workers have returned to their home towns, chastened by their overwhelming defeat.', 'v. 磨炼', '/\'tʃeisən | \'tʃeɪs(ə)n | \'tʃesn/', 'chasten', 6);
INSERT INTO `words` VALUES (9865, 'Thomas Rane chastised Peters for his cruelty.', 'v. 严惩, 惩罚', '/tʃæs\'taiz | tʃæ\'staɪz/', 'chastise', 6);
INSERT INTO `words` VALUES (9866, 'De Gankelaar: Who taught you that senseless self-chastisement?', 'n. 惩罚', '/tʃæ\'staizmənt | tʃæ\'staɪzmənt/', 'chastisement', 6);
INSERT INTO `words` VALUES (9867, 'He took a vow of chastity and celibacy.', 'n. 纯洁, 贞节, 简洁', '/\'tʃæstəti | \'tʃæstɪtɪ/', 'chastity', 6);
INSERT INTO `words` VALUES (9868, 'I followed him to this island chateau where he\'s holding a party.', 'n. 城堡', '/ʃæ\'təu | \'ʃætəʊ | ʃæ\'to/', 'chateau', 6);
INSERT INTO `words` VALUES (9869, 'national chauvinism', 'n. 盲目的爱国心, 沙文主义', '/\'ʃəuvinizəm | \'ʃəʊv(ɪ)nɪz(ə)m | \'ʃovɪ\'nɪzəm/', 'chauvinism', 6);
INSERT INTO `words` VALUES (9870, 'a chauvinistic dislike of foreigners', 'adj. 沙文主义的， 盲目爱国的', '/ˌʃouvɪ\'nɪstɪk | ,ʃovɪ\'nɪstɪk/', 'chauvinistic', 6);
INSERT INTO `words` VALUES (9871, NULL, 'adj. 多变的', '/\'tʃekərd | \'tʃɛkəd/', 'checkered', 6);
INSERT INTO `words` VALUES (9872, 'If we were to let these differences, and the Communists\' exploitation of them, break up the union that has stopped aggression in Korea the checkmate would be against us.', 'v. 阻止并败, (象棋)将死', '/\'tʃekmeit | \'tʃekmeɪt/', 'checkmate', 6);
INSERT INTO `words` VALUES (9873, 'Now don’t be cheeky to your elders, young woman.', 'adj. 无礼的， 厚颜无耻的', '/\'tʃiːki | \'tʃiki/', 'cheeky', 6);
INSERT INTO `words` VALUES (9874, NULL, 'n. [动]印度豹（一种似豹的动物, 产于南亚及非洲）', '/\'tʃi:tə | \'tʃiːtə | \'tʃitə/', 'cheetah', 6);
INSERT INTO `words` VALUES (9875, '...her beaming, cherubic face.', 'adj. 天使的， 无邪的， 可爱的', '/tʃə\'ruːbɪk | tʃɛ\'rʊbɪk/', 'cherubic', 6);
INSERT INTO `words` VALUES (9876, NULL, 'adj. 胸丰满的, 骄傲的', '/\'tʃesti | \'tʃestɪ | \'tʃɛsti/', 'chesty', 6);
INSERT INTO `words` VALUES (9877, 'The chevron or arrow road sign indicates a sharp bend to the left or right.', 'n. [军](军人佩戴以示军衔和军兵种的)v形臂章', '/\'ʃevrən | \'ʃɛvrən/', 'chevron', 6);
INSERT INTO `words` VALUES (9878, 'With simple supplies like scrap book paper and paint, you can easily convert them into chic and affordable gift boxes, flower vases or handy dispensers.', 'n. 别致的款式(尤指妇女的服饰)', '/ʃi:k, ʃik | ʃiːk | ʃɪk/', 'chic', 6);
INSERT INTO `words` VALUES (9879, 'Clearly there is some chicanery going on.', 'n. 强辩, 强词夺理, 狡辩, 欺骗', '/ʃi\'keinəri | ʃɪ\'keɪnərɪ/', 'chicanery', 6);
INSERT INTO `words` VALUES (9880, '‘Edward, you are naughty,’ Dorothy chided.', 'v. 斥责, 责骂', '/tʃaid | tʃaɪd/', 'chide', 6);
INSERT INTO `words` VALUES (9881, 'Religious unity remained as much a chimera as ever.', 'n. [希神]狮头, 羊身, 蛇尾的吐火怪物, 妖怪, 狂想', '/kai\'miərə/', 'chimera', 6);
INSERT INTO `words` VALUES (9882, 'He fell back from chimerical terrors to real terrors.', 'adj. 空想的', '/kai\'miərikəl | kaɪ\'mɪərɪkəl/', 'chimerical', 6);
INSERT INTO `words` VALUES (9883, NULL, 'n. 脊椎骨, 山脊', '/tʃain | tʃaɪn/', 'chine', 6);
