INSERT INTO `words` VALUES (9885, NULL, 'adj. 无下颚的, 优柔寡断的', '/\'tʃinlis | \'tʃɪnlɪs | \'tʃɪnləs/', 'chinless', 6);
INSERT INTO `words` VALUES (9886, 'the age of the silicon chip', 'n. 薄片， 碎片； 集成电路片', '/tʃɪp/', 'chip', 6);
INSERT INTO `words` VALUES (9887, 'The boy stood motionless, like a mouse or a chipmunk when it knows you\'re watching.', 'n. [动] 花栗鼠', '/\'tʃipmʌŋk | \'tʃɪpmʌŋk/', 'chipmunk', 6);
INSERT INTO `words` VALUES (9888, 'You’re looking very chipper this morning.', 'adj. 爽朗的, 活泼的, 爽快的', '/\'tʃipə | \'tʃɪpə | \'tʃɪpɚ/', 'chipper', 6);
