INSERT INTO `words` VALUES (9890, 'The chirps of the garden birds sounded distant.', 'n. 喳喳声, 唧唧声', '/tʃə:p | tʃɜːp | tʃɝp/', 'chirp', 6);
INSERT INTO `words` VALUES (9891, 'He set out to chisel a dog out of sandstone.', 'v. 凿; n. 凿子', '/\'tʃɪzl/', 'chisel', 6);
