INSERT INTO `words` VALUES (9893, 'He was handsome, upright, and chivalrous.', 'adj. 有武士风度的，侠义的', '/\'ʃivəlrəs | \'ʃɪv(ə)lrəs | \'ʃɪvəlrəs/', 'chivalrous', 6);
INSERT INTO `words` VALUES (9894, '...the age of chivalry.', 'n. 骑士精神, 骑士制度', '/\'ʃivəlri | \'ʃɪv(ə)lrɪ | \'ʃɪvəlri/', 'chivalry', 6);
INSERT INTO `words` VALUES (9895, 'choice steak', 'adj. 上等的； 精选的', '/tʃɔɪs/', 'choice', 6);
INSERT INTO `words` VALUES (9896, 'He joined a church choir at the age of eight.', 'n. 唱诗班, 唱诗班的席位', '/\'kwaiə | \'kwaɪə | \'kwaɪɚ/', 'choir', 6);
INSERT INTO `words` VALUES (9897, 'Six people choked to death on the fumes.', 'v. 窒息， 阻塞', '/tʃouk | tʃok/', 'choke', 6);
INSERT INTO `words` VALUES (9898, 'Paul was a choleric. Jeremiah was a melancholy.', 'adj. 易怒的', '/\'kɔlərik | \'kɒlərɪk | \'kɑlərɪk/', 'choleric', 6);
INSERT INTO `words` VALUES (9899, 'Skiers should be particularly choosy about the insurance policy they buy.', 'adj. 挑三拣四的， 挑剔的', '/\'tʃuːzi | \'tʃuzi/', 'choosy', 6);
INSERT INTO `words` VALUES (9900, 'a grilled pork/lamb chop', 'n. 砍, 排骨, 官印, 商标', '/[tʃɔp] | tʃɒp | tʃɑp/', 'chop', 6);
INSERT INTO `words` VALUES (9901, 'The small boat bobbed about on the choppy water.', 'adj. （海等）波浪起伏的, (指风)不断改变方向的', '/\'tʃɔpi | \'tʃɒpɪ | \'tʃɑpi/', 'choppy', 6);
