INSERT INTO `words` VALUES (9904, 'The choreography of Eric Hawkins is considered radical by ballet audiences.', 'n. 舞蹈术, 舞台舞蹈', '/,kɔri\'ɔɡrəfi | ,kɒrɪ\'ɒgrəfɪ | ,kɔrɪ\'ɑɡrəfi/', 'choreography', 6);
INSERT INTO `words` VALUES (9905, 'Harry chortled with delight.', 'v. 咯咯笑', '/\'tʃɔ:tl | \'tʃɔːt(ə)l | \'tʃɔrtl/', 'chortle', 6);
INSERT INTO `words` VALUES (9906, 'I sing with the university chorus.', 'n. 合唱, 合唱队, 齐声', '/\'kɔ:rəs | \'kɔːrəs | \'kɔrəs/', 'chorus', 6);
INSERT INTO `words` VALUES (9907, 'The light from the water-bottle was merely engaged in a chromatic problem.', 'adj. 彩色的', '/krəu\'mætik | krə\'mætɪk/', 'chromatic', 6);
INSERT INTO `words` VALUES (9908, 'Do we have a chromosome like that?', 'n. [生物]染色体', '/\'krəuməsəum | \'krəʊməsəʊm | \'kroməsom/', 'chromosome', 6);
INSERT INTO `words` VALUES (9909, 'chronic arthritis', 'adj. 慢性的， 长期的', '/\'krɑːnɪk | \'krɑnɪk/', 'chronic', 6);
INSERT INTO `words` VALUES (9910, 'We arranged the documents in chronological order .', 'adj. 按年代顺序排列的', '/ˌkrɑːnə\'lɑːdʒɪkl | ,krɑnə\'lɑdʒɪkl/', 'chronological', 6);
INSERT INTO `words` VALUES (9911, 'Solomon Gills is in the act of seeing what time it is by the unimpeachable chronometer.', 'n. 记时计', '/krə\'nɔmitə | krə\'nɒmɪtə | krə\'nɑmɪtɚ/', 'chronometer', 6);
INSERT INTO `words` VALUES (9912, 'The tea tasted faintly of chrysanthemum.', 'n. 菊花', '/kri\'sænθəməm | krɪ\'sænθɪməm; -z- | krɪ\'sænθəməm/', 'chrysanthemum', 6);
INSERT INTO `words` VALUES (9913, 'a chubby six-year-old', 'adj. 丰满的, 圆胖的', '/\'tʃʌbi | \'tʃʌbɪ/', 'chubby', 6);
INSERT INTO `words` VALUES (9914, 'I chucked a few things into a suitcase and left.', 'n. 抚弄, 赶走, 扔, 抛弃, （牛）颈肉, 咯咯声, 卡盘, 解雇', '/tʃʌk/', 'chuck', 6);
INSERT INTO `words` VALUES (9915, 'He gave a little chuckle.', 'n. 吃吃的笑声', '/\'tʃʌkl | \'tʃʌk(ə)l/', 'chuckle', 6);
INSERT INTO `words` VALUES (9916, '...his old chum Anthony.', 'n. <俗>(特指男孩子之间)密友, 室友', '/tʃʌm/', 'chum', 6);
INSERT INTO `words` VALUES (9917, NULL, 'n. 大木片, 大肉片, 木人', '/tʃʌmp/', 'chump', 6);
INSERT INTO `words` VALUES (9918, 'ice chunks', 'n. 大块, 矮胖的人或物', '/tʃʌŋk/', 'chunk', 6);
INSERT INTO `words` VALUES (9919, NULL, 'adj. 矮矮胖胖的', '/\'tʃʌŋki | \'tʃʌŋkɪ/', 'chunky', 6);
INSERT INTO `words` VALUES (9920, 'He must have had some ups and downs in life to make him such a churl.', 'n. 农业工人,乡下人,粗野的人, 吝啬鬼', '/tʃə:l | tʃɜːl | tʃɝl/', 'churl', 6);
