INSERT INTO `words` VALUES (9931, 'Swimming helps to get the blood circulating through the muscles.', 'v. 循环； 流通； 发行', '/\'sɜːrkjəleɪt | \'sɝkjəlet/', 'circulate', 6);
INSERT INTO `words` VALUES (9932, 'Exercise improves the circulation.', 'n. 循环， 流通； 发行量', '/ˌsɜːrkjə\'leɪʃn | ,sɝkjə\'leʃən/', 'circulation', 6);
INSERT INTO `words` VALUES (9933, NULL, 'n. 婉转曲折的陈述', '/,sə:kəmlə\'kju:ʃən | ,sɜːkəmlə\'kjuːʃ(ə)n | ,sɝkəmlə\'kjuʃən/', 'circumlocution', 6);
INSERT INTO `words` VALUES (9934, 'The President’s power is circumscribed by Congress and the Supreme Court.', 'v. 划界限； 限制', '/\'sɜːrkəmskraɪb | ,sɝkəm\'sraɪb/', 'circumscribe', 6);
