INSERT INTO `words` VALUES (9936, 'The book includes a long and circumstantial account of Empson’s conversation with the Queen.', 'adj. 不重要的， 偶然的； 描述详细的', '/ˌsɜːrkəm\'stænʃl | ,sɝkəm\'stænʃl/', 'circumstantial', 6);
INSERT INTO `words` VALUES (9937, 'Military planners tried to circumvent the treaty.', 'v. 围绕, 包围, 智取', '/sɜːkəm\'vent | ,sɝkəm\'vɛnt/', 'circumvent', 6);
