INSERT INTO `words` VALUES (9939, 'One day she put rocks in her pocket and stepped into a cistern where she drowned.', 'n. 水塔, 蓄水池', '/\'sistən | \'sɪstən | \'sɪstɚn/', 'cistern', 6);
INSERT INTO `words` VALUES (9940, 'The essay begins with a citation from ‘Hamlet’.', 'n. 引证； 引文； 传票', '/saɪ\'teɪʃn | saɪ\'teʃən/', 'citation', 6);
