INSERT INTO `words` VALUES (9944, 'Please have the civility to knock before you enter next time.', 'n. 礼貌, 端庄', '/si\'viləti | sɪ\'vɪlɪtɪ | sə\'vɪləti/', 'civility', 6);
INSERT INTO `words` VALUES (9945, 'Now they are returning to claim what was theirs.', 'v. 要求或索要; n. 声称拥有的权利', '/kleɪm | klem/', 'claim', 6);
