INSERT INTO `words` VALUES (9947, '...clairvoyant powers.', 'adj. 透视的， 有洞察力的', '/kler\'vɔɪənt | klɛr\'vɔɪənt/', 'clairvoyant', 6);
INSERT INTO `words` VALUES (9948, 'clam chowder (= a type of soup )', 'n. 蛤', '/klæm/', 'clam', 6);
INSERT INTO `words` VALUES (9949, 'We all clambered aboard and the boat pulled out.', 'v. 吃力地爬上， 攀登', '/\'klæmbər | \'klæmbɚ/', 'clamber', 6);
