INSERT INTO `words` VALUES (9951, NULL, 'n. 吵闹， 喧哗', '/\'klæmər | \'klæmə/', 'clamor', 6);
INSERT INTO `words` VALUES (9952, 'There is always a clamorous din when I go to visit my father.', 'adj. 大喊大叫的', '/\'klæmərəs/', 'clamorous', 6);
INSERT INTO `words` VALUES (9953, 'He shouted over the rising clamour of voices.', 'n. 喧闹', '/\'klæmə | \'klæmɚ/', 'clamour', 6);
