INSERT INTO `words` VALUES (9955, '...a clampdown on the employment of illegal immigrants.', 'n. 压制, 取缔', '/\'klæmpdaun | \'klæmpdaʊn/', 'clampdown', 6);
INSERT INTO `words` VALUES (9956, 'a clandestine affair', 'adj. 秘密的', '/klæn\'destin | klæn\'destɪn; \'klændestɪn | klæn\'dɛstɪn/', 'clandestine', 6);
INSERT INTO `words` VALUES (9957, 'a clannish community', 'adj. 氏族的, 宗族排外的, 团结心很强的', '/\'klæniʃ | \'klænɪʃ/', 'clannish', 6);
