INSERT INTO `words` VALUES (9961, 'Reporters asked him to clarify his position (= say exactly what his beliefs are ) on welfare reform.', 'v. 澄清', '/\'klærəfaɪ/', 'clarify', 6);
INSERT INTO `words` VALUES (9962, 'Letters may be edited for length and clarity.', 'n. 清楚, 透明', '/\'klærəti | \'klærɪtɪ/', 'clarity', 6);
INSERT INTO `words` VALUES (9963, 'a scheduling clash on TV', 'n. 冲突, 撞击声, 抵触', '/klæʃ/', 'clash', 6);
INSERT INTO `words` VALUES (9964, 'the firm clasp of her hand', 'n. 钩子， 扣子； 紧握', '/klæsp/', 'clasp', 6);
INSERT INTO `words` VALUES (9965, 'the classification of wines according to quality', 'n. 分类, 分级', '//,klæsifi\'keiʃən/ | ,klæsɪfɪ\'keɪʃ(ə)n | ,klæsɪfɪ\'keʃən/', 'classification', 6);
INSERT INTO `words` VALUES (9966, 'We’d classify Drabble’s novels under ‘Romance’.', 'v. 分类, 分等', '//\'klæsifai/ | \'klæsɪfaɪ/', 'classify', 6);
INSERT INTO `words` VALUES (9967, 'A confidentiality clause was added to the contract.', 'n. 子句, 条款', '/klɔ:z | klɔːz | klɔz/', 'clause', 6);
