INSERT INTO `words` VALUES (9975, 'The republican party has vociferously opposed any clemency for convicted terrorists.', 'n. 温和, 仁慈, 和蔼', '/\'klemənsi | \'klemənsɪ | \'klɛmənsi/', 'clemency', 6);
