INSERT INTO `words` VALUES (9977, 'Jody was pacing the sidelines, her fists clenched.', 'n. 牢牢抓住, 钉紧, 敲弯的钉头', '/klentʃ | klen(t)ʃ | klɛntʃ/', 'clench', 6);
INSERT INTO `words` VALUES (9978, 'There is plenty of truth in the cliché that a trouble shared is a trouble halved.', 'adj. 陈腐的usedsooftenthatithasbecomestaleormeaningless); n. 陈词滥调', '/kliː\'ʃeɪ/', 'cliché', 6);
INSERT INTO `words` VALUES (9979, 'His article is stuffed with cliche.', 'n. 陈词滥调', '/\'kli:ʃei | kliː\'ʃeɪ/', 'cliche', 6);
INSERT INTO `words` VALUES (9980, 'This pub had a mixed clientele.', 'n. 诉讼委托人, 客户', '/,kli:ɔn\'tel | ,kliːɒn\'tel | \'klaɪən\'tɛl/', 'clientele', 6);
INSERT INTO `words` VALUES (9981, NULL, 'n. 转变期, [医]更年期,绝经期,[植]呼吸峰', '/klai\'mæktərik | klaɪ\'mækt(ə)rɪk; ,klaɪmæk\'terɪk | ,klaɪmæk\'tɛrɪk/', 'climacteric', 6);
INSERT INTO `words` VALUES (9982, 'a climactic moment', 'adj. 高潮的', '/klaɪ\'mæktɪk/', 'climactic', 6);
