INSERT INTO `words` VALUES (9986, 'Another man was rescued as he clung to the riverbank.', 'v. 紧紧抓住； 坚持', '/klɪŋ/', 'cling', 6);
INSERT INTO `words` VALUES (9987, 'The drug has undergone extensive clinical trials (= tests to see if it is effective in treating people ) .', 'adj. 临床的； 冷静客观的', '/\'klɪnɪkl/', 'clinical', 6);
