INSERT INTO `words` VALUES (9994, 'What you beheld was the interior of a cloister.', 'n. 回廊, 修道院', '/\'klɔistə | \'klɒɪstə | \'klɔɪstɚ/', 'cloister', 6);
INSERT INTO `words` VALUES (9995, 'Academics lead a cloistered life.', 'adj. 住在修道院的, 隐居的', '/\'klɔistəd | \'klɔɪstɚd/', 'cloistered', 6);
INSERT INTO `words` VALUES (9996, 'a closet full of beautiful clothes', 'adj. 秘密的; n. 壁橱', '/\'klɑːzət | \'klɑzət/', 'closet', 6);
INSERT INTO `words` VALUES (9997, 'Several military bases are threatened with closure .', 'n. 关闭', '/\'kləuʒə | \'kləʊʒə | \'kloʒɚ/', 'closure', 6);
INSERT INTO `words` VALUES (9998, 'He developed a blood clot on his brain and died.', 'n. (血液等的)凝块', '/klɔt | klɒt | klɑt/', 'clot', 6);
INSERT INTO `words` VALUES (9999, 'All of a sudden a storm broke – a regular cloudburst.', 'n. 倾盆大雨, 豪雨', '/\'klaudbə:st | \'klaʊdbɜːst | \'klaʊdbɝst/', 'cloudburst', 6);
INSERT INTO `words` VALUES (10000, 'I was half tempted to give one of them a clout myself.', 'n. 敲打, 轻叩, 破布', '/klaut | klaʊt/', 'clout', 6);
INSERT INTO `words` VALUES (10001, 'Her sweet submissive smile began to cloy after a while.', 'v. 过饱, 使厌腻', '/klɔi | klɒɪ/', 'cloy', 6);
INSERT INTO `words` VALUES (10002, 'cloying sentimentality', 'adj. 因过量而厌烦的,倒胃口的', '/\'klɔiiŋ | \'klɔɪɪŋ/', 'cloying', 6);
INSERT INTO `words` VALUES (10003, 'A clumsy waiter spilled wine all over her new skirt.', 'adj. 笨拙的', '/\'klʌmzi | \'klʌmzɪ/', 'clumsy', 6);
INSERT INTO `words` VALUES (10004, 'a diamond cluster ring', 'n. 串, 丛', '/\'klʌstə | \'klʌstɚ/', 'cluster', 6);
INSERT INTO `words` VALUES (10005, 'Piles of books and papers cluttered his desk.', 'v. 弄乱; n. 零乱', '/\'klʌtər | \'klʌtɚ/', 'clutter', 6);
INSERT INTO `words` VALUES (10006, 'The result showed that solubilization of phenol in coacervate phase was related to the structure of surfactant micelle.', 'n. [化]凝聚层', '/kəu\'æsəveit, ,kəuə\'sə:vət/', 'coacervate', 6);
INSERT INTO `words` VALUES (10007, 'Therefore, people with bleeding disorders or taking anti-coagulant medication should consult with their doctor before taking fish oil supplements.', 'n. 凝结剂, 凝血剂', '/kəu\'æɡjulənt | kəʊ\'ægjʊlənt | ko\'ægjələnt/', 'coagulant', 6);
INSERT INTO `words` VALUES (10008, 'The blood had not coagulated.', 'v. 凝结', '/kəu\'æɡjuleit | kəʊ\'ægjʊleɪt | ko\'æɡjulet/', 'coagulate', 6);
INSERT INTO `words` VALUES (10009, 'Azoth is often associated with the alchemical principle of coagulation.', 'n. 凝结', '/kouˌægju\'leɪʃn | koægjə\'leʃən/', 'coagulation', 6);
INSERT INTO `words` VALUES (10010, 'As the number of moisture droplets increases, they begin to coalesce into small rivulets of fluid.', 'v. 接合', '/,kəuə\'les | ,kəʊə\'les | ,koə\'lɛs/', 'coalesce', 6);
INSERT INTO `words` VALUES (10011, 'the centre-right coalition government', 'n. 合并, 接合, 联合', '/,kəuə\'liʃən | ,kəʊə\'lɪʃ(ə)n | ˌkoʊəˈlɪʃn/', 'coalition', 6);
INSERT INTO `words` VALUES (10012, 'a jacket of coarse wool', 'adj. 粗糙的； 低劣的； 粗俗的', '/kɔːrs | kɔrs/', 'coarse', 6);
INSERT INTO `words` VALUES (10013, 'Hard work had coarsened his hands.', 'v. 变粗糙', '/\'kɔːrsn | \'kɔrsn/', 'coarsen', 6);
