INSERT INTO `words` VALUES (10015, 'The difference does not, for example, coincide with the difference between a manual and a mental job; a gardener or a cobbler may be a worker, a bank clerk a laborer.', 'n. 皮匠, 补鞋匠, 工匠', '/\'kɔblə | \'kɒblə | \'kɑblɚ/', 'cobbler', 6);
INSERT INTO `words` VALUES (10016, NULL, 'n. 平底小渔船(=cobble)', '/\'kəʊb(ə)l | \'kobəl/', 'coble', 6);
INSERT INTO `words` VALUES (10017, NULL, 'v. 娇养, 溺爱, 放纵', '/\'kɔkə | \'kɒkə/', 'cocker', 6);
INSERT INTO `words` VALUES (10018, 'He seemed rather too cocksure for my liking.', 'adj. 绝对可靠的, 深信的, 独断的', '/\'kɔk\'ʃuə | kɒk\'ʃɔː; kɒk\'ʃʊə | ,kɑk\'ʃʊr/', 'cocksure', 6);
INSERT INTO `words` VALUES (10019, NULL, 'n. 乐曲结尾部', '/\'koudə | \'kodə/', 'coda', 6);
INSERT INTO `words` VALUES (10020, 'She coddled her youngest son madly.', 'v. 溺爱； 悉心照料', '/\'kɑːdl | \'kɔdl/', 'coddle', 6);
INSERT INTO `words` VALUES (10021, 'Each path is coded to show the level of difficulty.', 'v. 将某事物编写成密码; n. 密码；法典', '/koud | kod/', 'code', 6);
