INSERT INTO `words` VALUES (10023, 'The latest draft of the agreement codifies the panel\'s decision.', 'v. 编成法典， 编辑成书', '/\'kɑːdɪfaɪ | \'kɔdifai/', 'codify', 6);
INSERT INTO `words` VALUES (10024, 'Potter had argued that the government coerced him into pleading guilty.', 'v. 强制, 强迫', '/kəu\'ə:s | kəʊ\'ɜːs | ko\'ɝs/', 'coerce', 6);
INSERT INTO `words` VALUES (10025, 'The defendant explained that he had been acting under coercion.', 'n. 强迫, 威压, 高压政治', '/kəu\'ə:ʃən | kəʊ\'ɜːʃ(ə)n | ko\'ɝʒən/', 'coercion', 6);
INSERT INTO `words` VALUES (10026, 'coercive measures to reduce absenteeism', 'adj. 强制的， 强迫性的', '/kou\'ɜːrsɪv | ko\'ɝsɪv/', 'coercive', 6);
INSERT INTO `words` VALUES (10027, 'Tang Xianzu, a playwright of Ming Dynasty in 16th Century, was the coeval of Shakespeare of Britain.', 'adj. 同时代的', '/\'kəu\'i:vəl | kəʊ\'iːv(ə)l | ko\'ivl/', 'coeval', 6);
INSERT INTO `words` VALUES (10028, 'A component might perform scientific calculations, collect performance data, count the number of milliseconds since January 1, 1970, or read the number of dollars in President Bush\'s campaign coffer.', 'n. 保险箱', '/\'kɔfə | \'kɒfə | \'kɔfɚ/', 'coffer', 6);
INSERT INTO `words` VALUES (10029, NULL, 'n. [机]嵌齿, 小船', '/kɔɡ | kɒg | kɑɡ/', 'cog', 6);
INSERT INTO `words` VALUES (10030, 'But Hamas says, with some cogency, that it has been illegal for Mr Abbas to retain his post as the PA’s president since January this year, when his four-year term should have run out.', 'n. 力量, 中肯, 肯切', '/\'kəudʒənsi | \'kəʊdʒ(ə)nsɪ/', 'cogency', 6);
