INSERT INTO `words` VALUES (10032, 'He sat silently cogitating.', 'v. 思考, 考虑', '/\'kɔdʒiteit | \'kɒdʒɪteɪt/', 'cogitate', 6);
INSERT INTO `words` VALUES (10033, NULL, 'n. 沉思, 思考', '/,kɔdʒi\'teiʃən/', 'cogitation', 6);
INSERT INTO `words` VALUES (10034, 'This one branch is the Liberty of Thought: from which it is impossible to separate the cognate liberty of speaking and of writing.', 'adj. 同词源的,同类的', '/\'kɔɡneit | \'kɒgneɪt | \'kɑɡnet/', 'cognate', 6);
