INSERT INTO `words` VALUES (10039, 'The three years of the course are planned as a coherent whole.', 'adj. 粘在一起的, 一致的, 连贯的', '/kə(ʊ)\'hɪər(ə)nt | ko\'hɪrənt/', 'coherent', 6);
INSERT INTO `words` VALUES (10040, 'a sense of community and social cohesion', 'n. 结合, 凝聚, [物理]内聚力', '/kəu\'hi:ʒən | kə(ʊ)\'hiːʒ(ə)n | ko\'hiʒən/', 'cohesion', 6);
INSERT INTO `words` VALUES (10041, 'a cohesive community', 'adj. 粘着的', '/kəʊ\'hiːsɪv | ko\'hisɪv/', 'cohesive', 6);
INSERT INTO `words` VALUES (10042, 'The interests of the US and those of the islanders may not coincide.', 'v. 一致, 符合', '/,kəʊɪn\'saɪd | ,koɪn\'saɪd/', 'coincide', 6);
INSERT INTO `words` VALUES (10043, '‘I’m going to Appleby tomorrow.’ ‘ What a coincidence ! I’m going there too.’', 'n. 一致, 相合, 同时发生或同时存在(尤指偶然)的事', '/kəu\'insidəns | kəʊ\'ɪnsɪd(ə)ns | ko\'ɪnsɪdəns/', 'coincidence', 6);
INSERT INTO `words` VALUES (10044, 'Any resemblance to actual persons, places, or events is purely coincidental.', 'adj. 巧合的； 同时发生的', '/kouˌɪnsɪ\'dentl | ko,ɪnsɪ\'dɛntl/', 'coincidental', 6);
