INSERT INTO `words` VALUES (10046, 'She took a colander and, of course, first of all we would wash the lettuce, that goes without saying.', 'n. 滤器, 漏锅', '/\'kʌləndə | \'kʌləndə; \'kɒl- | \'kɑləndɚ/', 'colander', 6);
INSERT INTO `words` VALUES (10047, 'a cold-blooded killer', 'adj. 冷血的； 残酷的', '/\'kəuld\'blʌdid | ˌkould\'blʌdɪd/', 'cold-blooded', 6);
INSERT INTO `words` VALUES (10048, 'Much later he collaborated with his son Michael on the English translation of a text on food production.', 'v. 合作， 协作； 通敌', '/kə\'læbəreɪt | kə\'læbəret/', 'collaborate', 6);
INSERT INTO `words` VALUES (10049, '...a collaborative research project.', 'adj. 协作的', '/kə\'læbəreɪtɪv | kə\'læbəretɪv/', 'collaborative', 6);
INSERT INTO `words` VALUES (10050, '...a collage of words and pictures from magazines.', 'n. 抽象拚贴画(用报纸、布、压平的花等碎片拼合而成的)', '/kə\'lɑ:ʒ | \'kɒlɑːʒ; kə\'lɑːʒ | kə\'lɑʒ/', 'collage', 6);
INSERT INTO `words` VALUES (10051, 'Uncle Ted’s chair collapsed under his weight.', 'v. 坍塌， 塌陷； 虚脱， 晕倒', '/kə\'læps/', 'collapse', 6);
