INSERT INTO `words` VALUES (10054, 'However, the collation would be wrong when the number of digits changed, so leading zeroes are provided.', 'n. 校勘,整理', '/kɔ\'leiʃən | kə\'leɪʃ(ə)n | kə\'leʃən/', 'collation', 6);
INSERT INTO `words` VALUES (10055, 'A car and a van collided on the motorway.', 'v. 碰撞, 抵触', '/kə\'laid | kə\'laɪd/', 'collide', 6);
