INSERT INTO `words` VALUES (10057, 'Two people were killed in a head-on collision (= between two vehicles that are moving directly towards each other ) on highway 218.', 'n. 碰撞, 冲突', '/kə\'lɪʒ(ə)n | kə\'lɪʒən/', 'collision', 6);
INSERT INTO `words` VALUES (10058, '...a colloquial expression.', 'adj. 口语的， 口头的', '/kə\'loukwiəl | kə\'lokwɪəl/', 'colloquial', 6);
INSERT INTO `words` VALUES (10059, 'In this context, I am very grateful to President Havel for having organized a colloquium for dialogue recently here in Prague.', 'n. 讨论会', '/kə\'ləukwiəm | kə\'ləʊkwɪəm | kə\'lokwɪəm/', 'colloquium', 6);
