INSERT INTO `words` VALUES (10061, 'Several local officials are in jail on charges of colluding with the Mafia.', 'v. 串通, 勾结, 共谋', '/kə\'lu:d | kə\'l(j)uːd | kə\'lʊd/', 'collude', 6);
INSERT INTO `words` VALUES (10062, 'He found no evidence of collusion between record companies and retailers.', 'n. 共谋, 勾结', '/kə\'lu:ʒən | kə\'l(j)uːʒ(ə)n | kə\'lʊʒən/', 'collusion', 6);
INSERT INTO `words` VALUES (10063, '...collusive business practices.', 'adj. 共谋的', '/kə\'luːsɪv | kə\'lʊsɪv/', 'collusive', 6);
INSERT INTO `words` VALUES (10064, 'a dead tree that has been colonized by ants', 'v. 建立殖民地， 拓殖； 定居， 居于', '/\'kɑːlənaɪz | \'kɑlənaɪz/', 'colonize', 6);
