INSERT INTO `words` VALUES (10084, 'You’ll get your comeuppance one day!', 'n. 应得的惩罚， 因果报应', '/kʌm\'ʌpəns/', 'comeuppance', 6);
INSERT INTO `words` VALUES (10085, 'a comic novel', 'adj. 可笑的；喜剧的; n. 喜剧演员', '/\'kɑːmɪk | \'kɑmɪk/', 'comic', 6);
INSERT INTO `words` VALUES (10086, 'How to extract string separated by comma with PHP?', 'n. 逗号', '/\'kɑːmə | \'kɑmə/', 'comma', 6);
INSERT INTO `words` VALUES (10087, 'So you would not break the third commandment.', 'n. 戒律', '/kə\'mɑ:ndmənt | kə\'mɑːndmənt | kə\'mændmənt/', 'commandment', 6);
INSERT INTO `words` VALUES (10088, 'a parade to commemorate the town’s bicentenary', 'v. 纪念； 庆祝', '/kə\'meməreɪt | kə\'mɛməret/', 'commemorate', 6);
INSERT INTO `words` VALUES (10089, 'Work will commence on the new building immediately.', 'v. 开始, 着手', '/kə\'mens | kə\'mɛns/', 'commence', 6);
INSERT INTO `words` VALUES (10090, 'All applicants should be at least 16 years of age at the commencement of this course.', 'n. 开始, 毕业典礼', '/kə\'mensmənt | kə\'mensm(ə)nt | kə\'mɛnsmənt/', 'commencement', 6);
INSERT INTO `words` VALUES (10091, 'The paper was highly commended in the UK Press Awards.', 'v. 称赞, 表扬, 推荐, 委托, 吸引', '/kə\'mend | kə\'mɛnd/', 'commend', 6);
INSERT INTO `words` VALUES (10092, 'Your enthusiasm is highly commendable .', 'adj. 值得表扬的', '/kə\'mendəbl | kə\'mendəb(ə)l | kə\'mɛndəbl/', 'commendable', 6);
INSERT INTO `words` VALUES (10093, 'Employees are paid salaries commensurate with those of teachers.', 'adj. 相称的, 相当的', '/kə\'menʃərit | kə\'menʃ(ə)rət; -sjə- | kəˈmɛnsərɪt, -ʃə-/', 'commensurate', 6);
INSERT INTO `words` VALUES (10094, 'Commentary is by Tom Ferris.', 'n. 实况报道； 集注', '/\'kɑːmənteri | \'kɑməntɛri/', 'commentary', 6);
INSERT INTO `words` VALUES (10095, 'political commentators', 'n. 评论员', '/\'kɑːmənteɪtər | \'kɑmən\'tetɚ/', 'commentator', 6);
INSERT INTO `words` VALUES (10096, 'Christmas has become so commercialized.', 'v. 使商业化， 使商品化', '/kə\'mɜːrʃlaɪz | kə\'mɝʃlaɪz/', 'commercialize', 6);
INSERT INTO `words` VALUES (10097, 'Many towns allow recyclable items to be commingled for collection in a single container.', 'v. 掺和， 混合', '/kə\'mɪŋgl | kə\'mɪŋɡl/', 'commingle', 6);
INSERT INTO `words` VALUES (10098, 'When I lost, he commiserated with me.', 'v. 怜悯, 同情', '/kə\'mizəreit | kə\'mɪzəreɪt | kə\'mɪzəret/', 'commiserate', 6);
INSERT INTO `words` VALUES (10099, 'The dealer takes a 20% commission on the sales he makes.', 'n. 委托； 佣金', '/kə\'mɪʃn | kə\'mɪʃən/', 'commission', 6);
INSERT INTO `words` VALUES (10100, 'Women commit fewer crimes than men.', 'v. 托付； 承诺； 犯罪', '/kə\'mɪt/', 'commit', 6);
INSERT INTO `words` VALUES (10101, 'Are you ready to make a long-term commitment ?', 'n. 委托事项, 许诺, 承担义务', '/kə\'mitmənt | kə\'mɪtm(ə)nt | kə\'mɪtmənt/', 'commitment', 6);
INSERT INTO `words` VALUES (10102, 'The party has a core of committed supporters.', 'adj. 尽忠的', '/kə\'mɪtɪd | kə\'mitid/', 'committed', 6);
INSERT INTO `words` VALUES (10103, 'Designed as cruisers, many ketches are heavier, more stable in sea conditions, and more commodious down below.', 'adj. 宽敞的', '/kə\'məudjəs | kə\'məʊdɪəs | kə\'modɪəs/', 'commodious', 6);
INSERT INTO `words` VALUES (10104, 'agricultural commodities', 'n. 日用品', '/kə\'mɔditi | kə\'mɒdɪtɪ | kə\'mɑdəti/', 'commodity', 6);
INSERT INTO `words` VALUES (10105, 'Car thefts are commonplace in this part of town.', 'adj. 普通的， 平庸的', '/\'kɑːmənpleɪs | \'kɑmən\'ples/', 'commonplace', 6);
INSERT INTO `words` VALUES (10106, 'You cant possibly be serious in using \'government\' and \'commonsense\' in the same sentence unless you include the word \"lacks\"!', 'adj. 有常识的', '/\'kɔmən\'sens | \'kɑːmənsens/', 'commonsense', 6);
INSERT INTO `words` VALUES (10107, 'He heard a commotion outside.', 'n. 骚动, 暴乱', '/kə\'məuʃən | kə\'məʊʃ(ə)n | kə\'moʃən/', 'commotion', 6);
INSERT INTO `words` VALUES (10108, 'a communal bathroom', 'adj. 全体共用的， 共享的', '/kə\'mjuːnl | kəˈmjunəl/', 'communal', 6);
INSERT INTO `words` VALUES (10109, 'The bushes grew in a compact mass.', 'adj. 紧凑的, 紧密的, 简洁的', '/kəm\'pækt, \'kɔmpækt | kəm\'pækt | \'kɑmpækt/', 'compact', 6);
INSERT INTO `words` VALUES (10110, 'This method can avoid the disfigurement of singleobjective optimization, thereby valuing the best compages of the aircraft configuration parameter more reasonably.', 'n. 组合, 构造', '/kəm\'peɪdʒiːz | kəm\'peidʒi:z/', 'compages', 6);
INSERT INTO `words` VALUES (10111, 'Her paintings invite comparison with those of the early Impressionists (= they remind you of them ) .', 'n. 比较， 对照； 比喻', '/kəm\'pærɪsn/', 'comparison', 6);
INSERT INTO `words` VALUES (10112, 'a map and compass', 'n. 指南针， 罗盘； 界限， 范围', '/\'kʌmpəs/', 'compass', 6);
INSERT INTO `words` VALUES (10113, 'I was shocked by the doctor’s lack of compassion .', 'n. 同情,怜悯', '/kəm\'pæʃən | kəm\'pæʃ(ə)n/', 'compassion', 6);
INSERT INTO `words` VALUES (10114, 'a caring, compassionate man', 'adj. 富于同情心的', '/kəm\'pæʃənit | kəm\'pæʃ(ə)nət | kəm\'pæʃənət/', 'compassionate', 6);
INSERT INTO `words` VALUES (10115, 'compatibility of flavours', 'n. [计]兼容性', '/kəm,pætə\'biləti | kəm,pætɪ\'bɪlɪtɪ | kəm,pætə\'bɪləti/', 'compatibility', 6);
INSERT INTO `words` VALUES (10116, 'The new software is IBM compatible (= can be used with IBM computers ) .', 'adj. 谐调的, 一致的, 兼容的', '/kəm\'pætəbl | kəm\'pætɪb(ə)l/', 'compatible', 6);
INSERT INTO `words` VALUES (10117, '...the introduction of legislation to compel cyclists to wear a helmet.', 'v. 强迫, 迫使', '/kəm\'pel | kəm\'pɛl/', 'compel', 6);
INSERT INTO `words` VALUES (10118, NULL, 'n. 称呼他人姓名, 姓名', '/,kɒmpə\'leɪʃən | ,kɔmpə\'leiʃən/', 'compellation', 6);
INSERT INTO `words` VALUES (10119, '...a frighteningly violent yet compelling film.', 'adj. 强制的, 强迫的, 引人注目的', '/kəm\'peliŋ | kəm\'pelɪŋ | kəm\'pɛlɪŋ/', 'compelling', 6);
INSERT INTO `words` VALUES (10120, NULL, 'adj. 扼要的, 简明的', '/kəm\'pendiəs | kəm\'pendɪəs | kəm\'pɛndɪəs/', 'compendious', 6);
INSERT INTO `words` VALUES (10121, 'The Roman Catholic Church has issued a compendium of its teachings.', 'n. 纲要, 概略', '/kəm\'pendiəm | kəm\'pendɪəm | kəm\'pɛndɪəm/', 'compendium', 6);
INSERT INTO `words` VALUES (10122, 'Because my left eye is so weak, my right eye has to work harder to compensate.', 'v. 偿还, 补偿, 付报酬', '/\'kɔmpenseit | \'kɒmpenseɪt | \'kɑmpɛnset/', 'compensate', 6);
INSERT INTO `words` VALUES (10123, 'She was awarded a large sum in compensatory damages .', 'adj. 补偿性的， 报酬的', '/kəm\'pensətɔːri | kəm\'pɛnsə,tori/', 'compensatory', 6);
INSERT INTO `words` VALUES (10124, 'Oscars organizers have already confirmed one change by announcing Australian actor Hugh Jackman as the host of the show, a departure from the recent tradition of popular comedians acting as compere.', 'n. 主持人, 指挥者', '/\'kɔmpɛə/', 'compere', 6);
INSERT INTO `words` VALUES (10125, 'Typing is considered by most employers to be a basic competence.', 'n. 胜任， 能力', '/\'kɑːmpɪtəns | \'kɑmpɪtəns/', 'competence', 6);
INSERT INTO `words` VALUES (10126, 'Several people gave competing accounts of the accident.', 'adj. 有竞争性的； 不相上下的', '/kəm\'piːtɪŋ | kəm\'pitɪŋ/', 'competing', 6);
INSERT INTO `words` VALUES (10127, 'The document was compiled by the Department of Health.', 'v. 编译, 编辑, 汇编', '/kəm\'pail | kəm\'paɪl/', 'compile', 6);
INSERT INTO `words` VALUES (10128, 'What you\'re hearing is the voice of complacence.', 'n. 自满', '/kəm\'pleɪsns | kəm\'plesns/', 'complacence', 6);
INSERT INTO `words` VALUES (10129, '...a worrying level of complacency about the risks of infection from AIDS.', 'n. 满足, 安心', '/kəm\'pleisənsi | kəm\'pleɪs(ə)nsɪ | kəm\'plesnsi/', 'complacency', 6);
INSERT INTO `words` VALUES (10130, 'There’s a danger of becoming complacent if you win a few games.', 'adj. 自满的, 得意的', '/kəm\'pleisənt | kəm\'pleɪs(ə)nt | kəm\'plesnt/', 'complacent', 6);
INSERT INTO `words` VALUES (10131, NULL, 'n. 彬彬有礼, 殷勤, 柔顺', '/kəm\'pleizəns | kəm\'pleɪzəns | kəm\'plezns/', 'complaisance', 6);
INSERT INTO `words` VALUES (10132, 'The courtier obeyed the king\'s orders in a complaisant manner.', 'adj. 彬彬有礼的, 殷勤的, 柔顺的', '/kəm\'pleizənt | kəm\'pleɪz(ə)nt | kəmpleɪsənt/', 'complaisant', 6);
INSERT INTO `words` VALUES (10133, 'The computer and the human mind have different but complementary abilities.', 'adj. 互补的', '/ˌkɑːmplɪ\'mentri | \'kɑmplə\'mɛntri/', 'complementary', 6);
INSERT INTO `words` VALUES (10134, 'Drinking water is good for the complexion.', 'n. 面色, 肤色, 情况, 局面', '/kəm\'plekʃən | kəm\'plekʃ(ə)n | kəm\'plɛkʃən/', 'complexion', 6);
INSERT INTO `words` VALUES (10135, 'Inspectors were sent to visit nuclear sites and verify compliance with the treaty.', 'n. 依从, 顺从', '/kəm\'plaiəns | kəm\'plaɪəns/', 'compliance', 6);
INSERT INTO `words` VALUES (10136, 'For years I had tried to be a compliant and dutiful wife.', 'adj. 顺从的, 适应的', '/kəm\'plaiənt | kəm\'plaɪənt/', 'compliant', 6);
INSERT INTO `words` VALUES (10137, 'The situation is complicated by the fact that I’ve got to work late on Friday.', 'v. 使复杂化', '/\'kɑːmplɪkeɪt | \'kɑmplɪket/', 'complicate', 6);
INSERT INTO `words` VALUES (10138, 'Recently a number of policemen were sentenced to death for their complicity in the murder.', 'n. 合谋， 串通', '/kəm\'plɪsəti/', 'complicity', 6);
INSERT INTO `words` VALUES (10139, 'All the guests paid her extravagant compliments.', 'n. 称赞, 恭维, 致意, 问候, 道贺', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪmənt/', 'compliment', 6);
INSERT INTO `words` VALUES (10140, 'There was a complimentary bottle of champagne in the hotel room.', 'adj. 问候的, 称赞的, 夸奖的, 免费赠送的', '/,kɔmpli\'mentəri | kɒmplɪ\'ment(ə)rɪ | ,kɑmplɪ\'mɛntri/', 'complimentary', 6);
INSERT INTO `words` VALUES (10141, 'The newspaper was asked by federal agents for assistance and agreed to comply.', 'v. 顺从, 答应, 遵守', '/kəm\'plai | kəm\'plaɪ/', 'comply', 6);
INSERT INTO `words` VALUES (10142, 'companies that make electronic components for computer products', 'n. 成分， 零部件', '/kəm\'pounənt | kəm\'ponənt/', 'component', 6);
INSERT INTO `words` VALUES (10143, 'His conduct did not comport with his high position.', 'v. 相称', '/kəm\'pɔ:t | kəm\'pɔːt/', 'comport', 6);
INSERT INTO `words` VALUES (10144, 'Another aspect of executive presence is comportment—your way of conducting yourself in interacting with others.', 'n. 举止, 态度, 动作', '/kəm\'pɔ:tmənt | kəm\'pɔːtm(ə)nt | kəm\'pɔrtmənt/', 'comportment', 6);
INSERT INTO `words` VALUES (10145, 'Laura was very calm and composed.', 'adj. 镇定的， 沉着的； 由…组成的', '/kəm\'pouzd | kəm\'pozd/', 'composed', 6);
INSERT INTO `words` VALUES (10146, 'The author builds up a useful compo-site picture of contemporary consumer culture.', 'adj. 合成的, 复合的', '/\'kɔmpəzit | \'kɒmpəzɪt | kɑm\'pɑzɪt/', 'composite', 6);
INSERT INTO `words` VALUES (10147, 'He has lost his composure under the pressure of the situation.', 'n. 镇静, 沉着', '/kəm\'pəuʒə | kəm\'pəʊʒə/', 'composure', 6);
INSERT INTO `words` VALUES (10148, 'The systematic name encodes the structure and composition of the caffeine molecule in some detail, and provides an unambiguous reference to this compound, whereas the name \"caffeine\" just names it.', 'v. 掺和; n. 复合物', '/kəm\'paund | \'kɑmpaʊnd/', 'compound', 6);
INSERT INTO `words` VALUES (10149, 'She cannot comprehend the extent of the disaster.', 'v. 理解； 包括', '/ˌkɑːmprɪ\'hend | ,kɑmprɪ\'hɛnd/', 'comprehend', 6);
INSERT INTO `words` VALUES (10150, 'Her speech was slurred and barely comprehensible.', 'adj. 可理解的， 易于理解的', '/ˌkɑːmprɪ\'hensəbl | \'kɑmprɪ\'hɛnsəbl/', 'comprehensible', 6);
INSERT INTO `words` VALUES (10151, 'We offer our customers a comprehensive range of financial products.', 'adj. 全面的, 广泛的, 能充分理解的, 包容的', '/,kɔmpri\'hensiv | kɒmprɪ\'hensɪv | ˌkɑːmprɪˈhensɪv/', 'comprehensive', 6);
INSERT INTO `words` VALUES (10152, NULL, 'adv. 包括地； 全面地', '/ˌkɑːmprɪ\'hensɪvli | ,kɑmprɪ\'hɛnsɪvli/', 'comprehensively', 6);
INSERT INTO `words` VALUES (10153, 'Light silk is best for parachutes, as it compresses well and then expands rapidly.', 'v. 压缩, 摘要叙述', '/kəm\'pres, \'kɔmpres | kəm\'pres | kəm\'prɛs/', 'compress', 6);
INSERT INTO `words` VALUES (10154, NULL, 'n. 压缩物, 压缩机, [医]收缩肌', '/kəm\'presə | kəm\'prɛsɚ/', 'compressor', 6);
INSERT INTO `words` VALUES (10155, 'Compromise is an inevitable part of marriage.', 'n. 妥协, 折衷', '/\'kɔmprəmaiz | \'kɒmprəmaɪz | \'kɑmprəmaɪz/', 'compromise', 6);
INSERT INTO `words` VALUES (10156, 'The desire to laugh became a compulsion.', 'n. 强迫, 强制, [心]强迫性冲动', '/kɔm\'pʌlʃən | kəm\'pʌlʃ(ə)n | kəm\'pʌlʃən/', 'compulsion', 6);
INSERT INTO `words` VALUES (10157, 'a help group for compulsive overeaters', 'adj. 强制的, 强迫的, 由强迫产生的, 禁不住的', '/kəm\'pʌlsiv | kəm\'pʌlsɪv/', 'compulsive', 6);
INSERT INTO `words` VALUES (10158, 'the threat of compulsory redundancies', 'adj. 必需做的, 必修的, 被强迫的, 被强制的, 义务的', '/kəm\'pʌlsəri | kəm\'pʌls(ə)rɪ/', 'compulsory', 6);
INSERT INTO `words` VALUES (10159, 'They used their tanks against the leftists without compunction .', 'n. 良心的谴责, 后悔, 悔恨', '/kəm\'pʌŋkʃən | kəm\'pʌŋkʃ(ə)n/', 'compunction', 6);
INSERT INTO `words` VALUES (10160, 'the computation of the monthly statistics', 'n. 计算, 估计', '/,kɔmpju\'teiʃən | kɒmpjʊ\'teɪʃ(ə)n | \'kɑmpjʊ\'teʃən/', 'computation', 6);
INSERT INTO `words` VALUES (10161, 'Final results had not yet been computed.', 'v. 计算, 估计, 用计算机计算(或确定)', '/kəm\'pju:t | kəm\'pjuːt | kəm\'pjʊt/', 'compute', 6);
INSERT INTO `words` VALUES (10162, 'He claimed that the businessman had conned him of $10,000.', 'v. 记诵, 精读', '/kɔn | kɒn | kɑn/', 'con', 6);
INSERT INTO `words` VALUES (10163, 'For the no-arguments case, we take the sequence [0 1] and concatenate it to an expression.', 'v. 连接', '/kɔn\'kætineit | kən\'kætɪneɪt | kɑn\'kætə,net/', 'concatenate', 6);
INSERT INTO `words` VALUES (10164, 'Listing 2 shows a sample algorithm which creates such a key by string concatenation.', 'n. 串联', '/kɔn,kæti\'neiʃən | kənkætə\'neɪʃn | kən\'kætə\'neʃən/', 'concatenation', 6);
INSERT INTO `words` VALUES (10165, 'a concave lens', 'adj. 凹的, 凹入的', '/kɔn\'keiv, \'kɔnkeiv | \'kɒnkeɪv | kɑn\'kev/', 'concave', 6);
INSERT INTO `words` VALUES (10166, '‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.', 'v. 勉强, 承认, 退让', '/kən\'si:d | kən\'siːd | kən\'sid/', 'concede', 6);
INSERT INTO `words` VALUES (10167, 'Reyes emits confidence without conceit.', 'n. 原义：想法, 意见, 自负, 幻想, 狂妄', '/kən\'si:t | kən\'siːt | kən\'sit/', 'conceit', 6);
INSERT INTO `words` VALUES (10168, 'You’re the most conceited, selfish person I’ve ever known.', 'adj. 自以为是的, 逞能的, 狂想的', '/kən\'si:tid | kən\'siːtɪd | kən\'sitɪd/', 'conceited', 6);
INSERT INTO `words` VALUES (10169, 'It is conceivable that you may get full compensation, but it’s not likely.', 'adj. 可能的, 想得到的, 可想像的', '/kən\'si:vəbl | kən\'siːvəb(ə)l | kən\'sivəbl/', 'conceivable', 6);
INSERT INTO `words` VALUES (10170, 'Scientists first conceived the idea of the atomic bomb in the 1930’s.', 'v. 构思, 以为, 持有', '/kən\'si:v | kən\'siːv | kən\'siv/', 'conceive', 6);
INSERT INTO `words` VALUES (10171, 'Now please concentrate.', 'v. 聚集， 浓缩', '/\'kɑːnsntreɪt | \'kɑnsn\'tret/', 'concentrate', 6);
INSERT INTO `words` VALUES (10172, 'She needed all her powers of concentration to stop herself from slipping on the icy road.', 'n. 专心， 专注； 集中； 浓度', '/ˌkɑːnsn\'treɪʃn | \'kɑnsn\'treʃən/', 'concentration', 6);
INSERT INTO `words` VALUES (10173, 'concentric circles', 'adj. 同心的', '/kən\'sentrɪk | kən\'sɛntrɪk/', 'concentric', 6);
INSERT INTO `words` VALUES (10174, 'the conceptual framework of the play', 'adj. 概念上的', '/kən\'septʃuəl | kən\'sɛptʃʊəl/', 'conceptual', 6);
INSERT INTO `words` VALUES (10175, 'Although more concerted action is required, its results bear out the need for the various sectors and stakeholders to work together.', 'adj. 商议定的, 协定的, [乐]协调的', '/kən\'sə:tid | kən\'sɜːtɪd | kən\'sɝtɪd/', 'concerted', 6);
INSERT INTO `words` VALUES (10176, '...Tchaikovsky\'s First Piano Concerto.', 'n. 协奏曲', '/kən\'tʃə:təu | kən\'tʃɜːtəʊ; -\'tʃeətəʊ | kən\'tʃɝto/', 'concerto', 6);
INSERT INTO `words` VALUES (10177, 'The British were not prepared to make any concessions .', 'n. 让步', '/kən\'seʃən | kən\'seʃ(ə)n | kən\'sɛʃən/', 'concession', 6);
INSERT INTO `words` VALUES (10178, NULL, 'n. 贝壳学, 贝类学', '/kɔŋ\'kɔlədʒi | kɒŋ\'kɒlədʒɪ | kɑŋ\'kɑlədʒi/', 'conchology', 6);
INSERT INTO `words` VALUES (10179, 'efforts to conciliate the unions', 'v. 安慰, 赢得, 调和', '/kən\'silieit | kən\'sɪlɪeɪt | kən\'sɪlɪet/', 'conciliate', 6);
INSERT INTO `words` VALUES (10180, NULL, 'n. 安抚, 抚慰', '/kɔn,sili\'eiʃən | kən,sɪlɪ\'eɪʃn | kən\'sɪlɪ\'eʃən/', 'conciliation', 6);
INSERT INTO `words` VALUES (10181, 'Brooks felt in no mood to be conciliatory.', 'adj. 抚慰的， 调和的', '/kən\'sɪliətɔːri | kən\'sɪlɪətɔri/', 'conciliatory', 6);
INSERT INTO `words` VALUES (10182, 'They are really not only beauty, loveliness, and winningness, in my opinions, but also cleanness, concinnity, and holiness just as I show the candock is.', 'n. 优美, 雅致', '/kən\'sɪnɪtɪ | kən\'sɪnəti/', 'concinnity', 6);
INSERT INTO `words` VALUES (10183, 'Your summary should be as clear and concise as possible.', 'adj. 简明的, 简练的', '/kən\'sais | kən\'saɪs/', 'concise', 6);
INSERT INTO `words` VALUES (10184, NULL, 'n. 切割, 分离, 简洁', '/kən\'siʒən | kən\'sɪʒən/', 'concision', 6);
INSERT INTO `words` VALUES (10185, 'Her attorneys claim there is no conclusive evidence that any murders took place.', 'adj. 最后的， 结论的， 决定性的； 确凿的， 消除怀疑的', '/kən\'kluːsɪv | kən\'klusɪv/', 'conclusive', 6);
INSERT INTO `words` VALUES (10186, 'Mr. Ferguson said the prisoner concocted the story to get a lighter sentence.', 'v. 调制, 调合, 编造', '/kən\'kɔkt | kən\'kɒkt | kən\'kɑkt/', 'concoct', 6);
INSERT INTO `words` VALUES (10187, 'He sipped the concoction cautiously.', 'n. 调合, 混合, 调合物', '/kən\'kɔkʃən | kən\'kɒkʃn | kən\'kɑkʃən/', 'concoction', 6);
INSERT INTO `words` VALUES (10188, 'war with all its concomitant sufferings', 'adj. 伴随的', '/kən\'kɔmitənt | kən\'kɒmɪt(ə)nt | kən\'kɑmətənt/', 'concomitant', 6);
INSERT INTO `words` VALUES (10189, 'They expressed the hope that he would pursue a neutral and balanced policy for the sake of national concord.', 'n. 和谐, 一致, 和睦', '/\'kɔŋkɔ:d, kən\'kɔ:d | \'kɒŋkɔːd | \'kɑŋkɔrd/', 'concord', 6);
INSERT INTO `words` VALUES (10190, 'But there\'s no reason that business can\'t be a major part of the climate change solution, or that profit isn\'t concordant with a desire to save the Earth.', 'adj. 协调的', '/kən\'kɔ:dənt | kən\'kɔːd(ə)nt | kən\'kɔrdnt/', 'concordant', 6);
INSERT INTO `words` VALUES (10191, NULL, 'n. 凝固, 凝固物, 具体化, [地]固结(作用), [医]结石', '/kən\'kri:ʃən | kən\'kriːʃ(ə)n | kən\'kriʃən/', 'concretion', 6);
INSERT INTO `words` VALUES (10192, 'When you mount the file system with this command, all its files use concurrent I/O.', 'n. 同时发生的事件', '/kən\'kʌrənt | kən\'kʌr(ə)nt | kən\'kɝənt/', 'concurrent', 6);
INSERT INTO `words` VALUES (10193, 'I had a concussion and a lot of scrapes and bruises.', 'n. 激动, 冲击, [医]震荡', '/kən\'kʌʃən | kən\'kʌʃ(ə)n/', 'concussion', 6);
INSERT INTO `words` VALUES (10194, 'Politicians were quick to condemn the bombing.', 'v. 判刑, 处刑, 声讨, 谴责', '/kən\'dem | kən\'dɛm/', 'condemn', 6);
INSERT INTO `words` VALUES (10195, 'There was widespread condemnation of Saturday\'s killings.', 'n. 谴责, 指责, 定罪', '/,kɔndem\'neiʃən | ,kɒndəm\'neɪʃn | ,kɑndɛm\'neʃən/', 'condemnation', 6);
INSERT INTO `words` VALUES (10196, 'condensed soup', 'v. 浓缩', '/kən\'dens | kən\'dɛns/', 'condense', 6);
INSERT INTO `words` VALUES (10197, 'When he condescended to speak, he contradicted himself three or four times in the space of half an hour.', 'v. 谦逊, 屈尊', '/kɒndɪ\'send | ,kɑndɪ\'sɛnd/', 'condescend', 6);
INSERT INTO `words` VALUES (10198, 'Professor Hutter’s manner is extremely conde-scending.', 'adj. 谦逊的， 故意屈尊的', '/ˌkɑːndɪ\'sendɪŋ | ,kɑndɪ\'sɛndɪŋ/', 'condescending', 6);
INSERT INTO `words` VALUES (10199, NULL, 'n. 谦虚, 硬要人家领情的态度', '/,kɒndɪ\'senʃn/', 'condescension', 6);
INSERT INTO `words` VALUES (10200, NULL, 'adj. 罪有应得的 severe and well deserved)； 适宜的', '/kən\'daɪn/', 'condign', 6);
INSERT INTO `words` VALUES (10201, 'Fact: Apparently this condiment can reinstate shine to your small change.', 'n. 调味品', '/\'kɔndimənt | \'kɒndɪm(ə)nt | \'kɑndɪmənt/', 'condiment', 6);
INSERT INTO `words` VALUES (10202, 'We condole with you on your misfortune.', 'v. 慰问', '/kən\'dəul | kən\'dəʊl/', 'condole', 6);
INSERT INTO `words` VALUES (10203, 'a letter of condolence', 'n. 哀悼, 吊唁', '/kən\'dəuləns | kən\'dəʊl(ə)ns | kən\'doləns/', 'condolence', 6);
INSERT INTO `words` VALUES (10204, 'I cannot condone the use of violence under any circumstances.', 'v. 宽恕， 原谅', '/kən\'doun | kən\'don/', 'condone', 6);
INSERT INTO `words` VALUES (10205, 'It is for psychologists to debate how far this method is likely to conduce to a better grasp of things.', 'v. 导致, 有利于', '/kən\'dju:s | kən\'djuːs/', 'conduce', 6);
INSERT INTO `words` VALUES (10206, 'But there’s nothing in [today’s] homes allowing them to do that in a healthy, safe or conducive way.', 'n. 有益于', '/kən\'dju:siv | kən\'djuːsɪv | kən\'dusɪv/', 'conducive', 6);
INSERT INTO `words` VALUES (10207, '...orange traffic cones.', 'n. 松果； 圆锥体', '/koun | kon/', 'cone', 6);
INSERT INTO `words` VALUES (10208, 'The sofa of ancient formula, can sit to also can lie, still perhaps can put down small tea table, drink confabulate .', 'v. 交谈', '/kən\'fæbjuleit | kən\'fæbjʊleɪt/', 'confabulate', 6);
INSERT INTO `words` VALUES (10209, '...a confection made with honey and nuts.', 'n. 糖果, 蜜饯, 调制, [药]糖膏(剂), 精制工艺品', '/kən\'fekʃən | kən\'fekʃ(ə)n | kən\'fɛkʃən/', 'confection', 6);
INSERT INTO `words` VALUES (10210, 'They\'ve entered this new confederacy because the central government\'s been unable to control the collapsing economy.', 'n. 联盟， 同盟', '/kən\'fedərəsi | kən\'fɛdərəsi/', 'confederacy', 6);
INSERT INTO `words` VALUES (10211, 'He conferred with Hill and the others in his office.', 'v. 商议， 商谈； 授予， 赋予', '/kən\'fɜːr | kən\'fɝ/', 'confer', 6);
INSERT INTO `words` VALUES (10212, 'Occasionally people confess to crimes they haven’t committed just to get attention.', 'v. 承认， 供认', '/kən\'fes | kən\'fɛs/', 'confess', 6);
INSERT INTO `words` VALUES (10213, '...a close confidant of the president.', 'n. 心腹朋友， 知己， 密友', '/\'kɑːnfɪdænt | \'kɑnfɪdænt/', 'confidant', 6);
INSERT INTO `words` VALUES (10214, 'I knew she had some fundamental problems in her marriage because she had confided in me a year earlier.', 'v. 倾诉, 委托, 信赖', '/kən\'faid | kən\'faɪd/', 'confide', 6);
INSERT INTO `words` VALUES (10215, 'a confidential government report', 'adj. 机密的', '/ˌkɑːnfɪ\'denʃl | ,kɑnfɪ\'dɛnʃl/', 'confidential', 6);
INSERT INTO `words` VALUES (10216, NULL, 'adv. 确信地； 肯定地', '/\'kɑːnfɪdəntli | \'kɑnfədəntli/', 'confidently', 6);
INSERT INTO `words` VALUES (10217, 'Prices range from $119 to $199, depending on the particular configuration.', 'n. 构造, 结构, 配置, 外形', '/kən,fiɡju\'reiʃən | kən,fɪgə\'reɪʃ(ə)n; -gjʊ- | kən,fɪɡjə\'reʃən/', 'configuration', 6);
INSERT INTO `words` VALUES (10218, 'Vaughan is confined to a wheelchair .', 'v. 限制， 禁闭', '/kən\'faɪn/', 'confine', 6);
INSERT INTO `words` VALUES (10219, 'I\'m a confirmed bachelor.', 'adj. 证实的, 惯常的, 慢性的', '/kən\'fə:md | kən\'fɜːmd | kən\'fɝmd/', 'confirmed', 6);
INSERT INTO `words` VALUES (10220, 'Miss Williams confiscated all our sweets.', 'v. 没收, 充公, 查抄, 征用', '/\'kɔnfis,keit | \'kɒnfɪskeɪt | \'kɑnfɪsket/', 'confiscate', 6);
INSERT INTO `words` VALUES (10221, 'Behind the gray walls there are human sparks, and yet never a conflagration.', 'n. 大火, 大火灾, 突发', '/,kɔnflə\'ɡreiʃən | ,kɒnflə\'greɪʃ(ə)n | ,kɑnflə\'ɡreʃən/', 'conflagration', 6);
INSERT INTO `words` VALUES (10222, 'He conflates two images from Kipling’s short stories in the film.', 'v. 合并', '/kən\'fleit | kən\'fleɪt/', 'conflate', 6);
INSERT INTO `words` VALUES (10223, 'Personal ethics and professional ethics sometimes conflict.', 'v. 斗争， 冲突， 抵触; n. 冲突', '/\'kɒnflɪkt | \'kɑnflɪkt/', 'conflict', 6);
INSERT INTO `words` VALUES (10224, 'The 160-metre falls mark the dramatic confluence of the rivers Nera and Velino.', 'n. 汇合', '/\'kɔnfluəns | \'kɒnflʊəns | \'kɑnfluəns/', 'confluence', 6);
INSERT INTO `words` VALUES (10225, 'an emphasis on conformity and control', 'n. 一致， 遵从； 顺从', '/kən\'fɔːrməti | kən\'fɔrməti/', 'conformity', 6);
INSERT INTO `words` VALUES (10226, 'His amazing recovery confounded the medical specialists.', 'v. 使迷惑， 搞混', '/kən\'faund | kən\'faʊnd/', 'confound', 6);
INSERT INTO `words` VALUES (10227, 'The problems confronting the new government were enormous.', 'v. 使面临, 对抗', '/kən\'frʌnt/', 'confront', 6);
INSERT INTO `words` VALUES (10228, 'She had stayed in her room to avoid another confrontation.', 'n. 面对, 面对面, 对质', '/,kɔnfrʌn\'teiʃən | ,kɒnfrʌn\'teɪʃn | ,kɑnfrən\'teʃən/', 'confrontation', 6);
INSERT INTO `words` VALUES (10229, 'To avoid confusion, the teams wore different colours.', 'n. 困惑， 糊涂； 混乱, 骚乱', '/kən\'fjuːʒn | kən\'fjʊʒən/', 'confusion', 6);
INSERT INTO `words` VALUES (10230, NULL, 'n. <法>撤职, 解任, 告辞', '/\'kɔ:nʒei/', 'conge', 6);
INSERT INTO `words` VALUES (10231, 'The fat had slowly congealed in the pan.', 'v. (使)冻结, (使)凝结', '/kən\'dʒi:l | kən\'dʒiːl | kən\'dʒil/', 'congeal', 6);
INSERT INTO `words` VALUES (10232, 'Compost provides congenial conditions for roots to develop.', 'adj. 性格相似的, 适意的', '/kən\'dʒi:njəl | kən\'dʒiːnɪəl | kən\'dʒinɪəl/', 'congenial', 6);
INSERT INTO `words` VALUES (10233, 'congenital abnormalities', 'adj. 先天的， 天生的', '/kən\'dʒenɪtl | kən\'dʒɛnɪtl/', 'congenital', 6);
INSERT INTO `words` VALUES (10234, NULL, 'v. 使充满, 使拥塞, [医]使充血', '/kən\'dʒest | kən\'dʒɛst/', 'congest', 6);
INSERT INTO `words` VALUES (10235, 'The problems of traffic congestion will not disappear in a hurry.', 'n. 拥塞, 充血', '/kən\'dʒestʃ(ə)n | kən\'dʒɛstʃən/', 'congestion', 6);
INSERT INTO `words` VALUES (10236, NULL, 'v. 聚结', '/kən\'ɡlɔmərət, -reit, kən\'ɡlɔməreit | kən\'glɒm(ə)rət | kən\'ɡlɑːmərət/', 'conglomerate', 6);
INSERT INTO `words` VALUES (10237, 'Crowds began to congregate to hear the President’s speech.', 'v. 聚集', '/\'kɔŋɡri,ɡeit | \'kɒŋgrɪgeɪt | \'kɑŋɡrɪɡet/', 'congregate', 6);
INSERT INTO `words` VALUES (10238, 'The congregation knelt to pray.', 'n. 集合, 集会, [宗]圣会', '/,kɔŋɡri\'ɡeiʃən | kɒŋgrɪ\'geɪʃ(ə)n | ,kɑŋɡrɪ\'ɡeʃən/', 'congregation', 6);
INSERT INTO `words` VALUES (10239, 'They want to work in an organization whose values are congruent with their own.', 'adj. 适合的', '/\'kɒŋgrʊənt | \'kɑŋɡruənt/', 'congruent', 6);
INSERT INTO `words` VALUES (10240, 'I could only envy her that sort of easy congruity — how wonderful, it seemed, to feel in accord with what others thought of you.', 'n. 一致, 适合, 调和', '/kɔŋ\'ɡru:iti | kɒŋ\'ɡruːɪtɪ/', 'congruity', 6);
INSERT INTO `words` VALUES (10241, 'In a word, love can bring us beautiful color to our life, while other people think love on campus is congruous.', 'adj. 一致的， 符合的；', '/\'kɒŋgrʊəs | \'kɔŋɡruəs/', 'congruous', 6);
INSERT INTO `words` VALUES (10242, 'Red squirrels cut conifer cones from trees and bury them in plant litter on the forest floor.', 'n. [植]松类, 针叶树', '/\'kəunifə | \'kɒnɪfə; \'kəʊn- | \'kɑnəfɚ/', 'conifer', 6);
INSERT INTO `words` VALUES (10243, 'What she said was pure conjecture .', 'v&n. 推测， 臆测', '/kən\'dʒektʃər | kən\'dʒɛktʃɚ/', 'conjecture', 6);
INSERT INTO `words` VALUES (10244, 'The wisdom of the retired generals and anti-war protesters conjoins.', 'v. 使结合', '/kən\'dʒɔɪn/', 'conjoin', 6);
INSERT INTO `words` VALUES (10245, 'conjugal love', 'adj. 结婚的, 夫妇间的', '/\'kɔndʒuɡəl | \'kɒndʒʊg(ə)l | \'kɑndʒəɡl/', 'conjugal', 6);
INSERT INTO `words` VALUES (10246, 'The magician conjured a rabbit out of his hat.', 'v. (以咒文)召唤, 变戏法, 想象', '/\'kʌndʒə, \'kɔn- | \'kʌndʒə | \'kʌndʒɚ/', 'conjure', 6);
INSERT INTO `words` VALUES (10247, 'They were watching me as they would watch a conjurer about to perform a trick.', 'n. 魔术师', '/\'kʌndʒərə/', 'conjurer', 6);
INSERT INTO `words` VALUES (10248, NULL, 'adj. 天生的, 先天的, 同族的', '/\'kɔneit | \'kɒneɪt/', 'connate', 6);
INSERT INTO `words` VALUES (10249, 'The deficit had grown with the connivance of the banks.', 'n. 假装不见, 纵容, 默许', '/kə\'naivəns | kə\'naɪv(ə)ns/', 'connivance', 6);
INSERT INTO `words` VALUES (10250, 'They connived with their mother to deceive me.', 'v. 默许, 纵容, 暗中合作, 密谋策划', '/kə\'naiv | kə\'naɪv/', 'connive', 6);
INSERT INTO `words` VALUES (10251, 'a wine connoisseur', 'n. (艺术品的)鉴赏家, 鉴定家, 内行', '/,kɔnə\'sə: | ,kɒnə\'sɜː | ,kɑnə\'sɝ/', 'connoisseur', 6);
INSERT INTO `words` VALUES (10252, 'It\'s just one of those words that\'s got so many negative connotations.', 'n. 含蓄, 储蓄的东西(词、语等), 内涵', '/,kɔnəu\'teiʃən | kɒnə\'teɪʃ(ə)n | ,kɑnə\'teʃən/', 'connotation', 6);
INSERT INTO `words` VALUES (10253, 'The most common tools for mapping semantically connotative URIs to internally structured ones simply perform replacements based on regular expressions.', 'adj. 隐含的, 内涵的', '/\'kɔnəuteitiv/', 'connotative', 6);
INSERT INTO `words` VALUES (10254, 'The Normans conquered England in 1066.', 'v. 以武力征服', '/\'kɑːŋkər | \'kɑŋkɚ/', 'conquer', 6);
INSERT INTO `words` VALUES (10255, 'Revivification of consanguinity for proper upbringing of the individuals and reformation of education on moderate and modern line are essential for instilling tolerance in the subjects.', 'n. 血亲, 血缘, 亲密关系', '/,kɔnsæŋ\'ɡwiniti | ,kɒnsæŋ\'ɡwɪnɪtɪ | ,kɑnsæŋ\'ɡwɪnəti/', 'consanguinity', 6);
INSERT INTO `words` VALUES (10256, 'Well, at least I can face them all with a clear conscience (= the knowledge that you have done nothing wrong ) .', 'n. 良心， 是非感', '/\'kɑːnʃəns | ˈkɑːnʃəns/', 'conscience', 6);
INSERT INTO `words` VALUES (10257, 'A conscientious teacher may feel inclined to take work home.', 'adj. 尽责的； 小心谨慎的', '/ˌkɑːnʃi\'enʃəs | \'kɑnʃɪ\'ɛnʃəs/', 'conscientious', 6);
INSERT INTO `words` VALUES (10258, 'David lost consciousness (= went into a deep sleep ) at eight o’clock and died a few hours later.', 'n. 意识， 观念； 清醒状态； 知觉', '/\'kɑːnʃəsnəs | \'kɑnʃəsnəs/', 'consciousness', 6);
INSERT INTO `words` VALUES (10259, 'a young army conscript', 'n. 被征入伍的士兵', '/kən\'skript | kən\'skrɪpt/', 'conscript', 6);
INSERT INTO `words` VALUES (10260, 'The bones will be reburied in consecrated ground .', 'v. 奉献， 使神圣', '/\'kɑːnsɪkreɪt | \'kɔnsi,kreit/', 'consecrate', 6);
INSERT INTO `words` VALUES (10261, 'It had rained for four consecutive days.', 'adj. 连续的', '/kən\'sekjətɪv | kən\'sɛkjətɪv/', 'consecutive', 6);
INSERT INTO `words` VALUES (10262, 'The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.', 'n. 意见一致', '/kən\'sensəs | kən\'sɛnsəs/', 'consensus', 6);
INSERT INTO `words` VALUES (10263, 'He finally consented to go.', 'v. 同意， 允许', '/kən\'sent | kən\'sɛnt/', 'consent', 6);
INSERT INTO `words` VALUES (10264, 'redundancy and the consequential loss of earnings', 'adj. 结果的, 相因而生的', '/,kɔnsi\'kwenʃəl | kɒnsɪ\'kwenʃ(ə)l | \'kɑnsə\'kwɛnʃəl/', 'consequential', 6);
INSERT INTO `words` VALUES (10265, NULL, 'n. 温室, 音乐学校', '/kən\'sə:və,tɔ:ri | kən\'sɜːvət(ə)rɪ | kən\'sɝvətɔri/', 'conservatory', 6);
INSERT INTO `words` VALUES (10266, 'We must conserve our woodlands for future generations.', 'v. 保存， 保藏', '/kən\'sɜːrv | kən\'sɝv/', 'conserve', 6);
INSERT INTO `words` VALUES (10267, 'Michael has already spent considerable time in Barcelona.', 'adj. 相当多的； 重要的； 值得考虑的', '/kən\'sɪdərəbl/', 'considerable', 6);
INSERT INTO `words` VALUES (10268, 'For decades, many of Malevich\'s works were consigned to the basements of Soviet museums.', 'v. 托运, 委托', '/kən\'sain | kən\'saɪn/', 'consign', 6);
INSERT INTO `words` VALUES (10269, 'The first consignment of food was flown in yesterday.', 'n. (货物的)交托, 交货, 发货, 运送, 托付物, 寄存物', '/kən\'sainmənt | kən\'saɪnm(ə)nt | kən\'saɪnmənt/', 'consignment', 6);
INSERT INTO `words` VALUES (10270, 'If it’s any consolation, things do get easier as the child gets older.', 'n. (被)安慰, 起安慰作用的人或事物', '/,kɔnsə\'leiʃən | ,kɒnsə\'leɪʃ(ə)n | ˌkɑnsəˈleʃən/', 'consolation', 6);
INSERT INTO `words` VALUES (10271, 'No one could console her when Peter died.', 'v. 安慰, 藉慰', '/kən\'səul | kən\'səʊl | \'kɑnsol/', 'console', 6);
INSERT INTO `words` VALUES (10272, 'The company has consolidated its position as the country’s leading gas supplier.', 'v. 巩固', '/kən\'sɔlideit | kən\'sɒlɪdeɪt | kən\'sɑlɪdet/', 'consolidate', 6);
INSERT INTO `words` VALUES (10273, 'Cognitive consonance is a consistency between the knowledge, ideas and beliefs.', 'n. 一致， 调和； 和音', '/\'kɑːnsənəns | \'kɑnsənəns/', 'consonance', 6);
INSERT INTO `words` VALUES (10274, 'This policy is scarcely consonant with the government’s declared aims.', 'adj. 协调的， 一致的', '/\'kɑːnsənənt | \'kɑnsənənt/', 'consonant', 6);
INSERT INTO `words` VALUES (10275, 'Aja The Babylonian dawn goddess and consort of the sun god.', 'v. 陪伴； 结交; n. 配偶', '/\'kɒnsɔːt | \'kɑn,sɔrt/', 'consort', 6);
INSERT INTO `words` VALUES (10276, 'The first part is conspectus, which including the definition of steel structure architecture and a general background knowledge.', 'n. 概论, 大纲', '/kən\'spektəs | kən\'spɛktəs/', 'conspectus', 6);
INSERT INTO `words` VALUES (10277, 'The notice must be displayed in a conspicuous place.', 'adj. 显著的', '/kən\'spikjuəs | kən\'spɪkjʊəs/', 'conspicuous', 6);
INSERT INTO `words` VALUES (10278, 'There were many conspiracy theories (= beliefs that something is the result of a conspiracy ) surrounding Princess Diana’s death.', 'n. 共谋, 阴谋', '/kən\'spirəsi | kən\'spɪrəsɪ | kən\'spɪrəsi/', 'conspiracy', 6);
INSERT INTO `words` VALUES (10279, 'Julius Caesar was murdered by a group of conspirators famously headed by Marcus Junius Brutus.', 'n. 同谋者, 阴谋者, 反叛者', '/kən\'spirətə | kən\'spɪrətə | kən\'spɪrətɚ/', 'conspirator', 6);
INSERT INTO `words` VALUES (10280, 'They\'d conspired to overthrow the government.', 'v. 共谋, 阴谋, (指事件)凑合起来', '/kən\'spaiɔ | kən\'spaɪə | kən\'spaɪɚ/', 'conspire', 6);
INSERT INTO `words` VALUES (10281, NULL, 'vt. 吵吵嚷嚷地反对, 唾弃', '/kən\'spjuː | kən\'spju:/', 'conspue', 6);
INSERT INTO `words` VALUES (10282, 'There was a constant stream of visitors to the house.', 'adj. 稳定的，不变的; n. 常数', '/\'kɑːnstənt | \'kɑnstənt/', 'constant', 6);
INSERT INTO `words` VALUES (10283, 'a star in the constellation of Orion', 'n. [天]星群, 星座, 灿烂的一群', '/,kɔnstə\'leiʃən | ,kɒnstə\'leɪʃ(ə)n | ,kɑnstə\'leʃən/', 'constellation', 6);
INSERT INTO `words` VALUES (10284, 'The government’s plans have caused considerable consternation among many Americans.', 'n. 惊愕, 恐怖, 惊惶失措', '/,kɔnstə\'neiʃən | kɒnstə\'neɪʃ(ə)n | ,kɑnstɚ\'neʃən/', 'consternation', 6);
INSERT INTO `words` VALUES (10285, 'He told his constituents that he would continue to represent them to the best of his ability.', 'n. 委托人, 要素', '/kən\'stitjuənt | kən\'stɪtjʊənt | kən\'stɪtʃuənt/', 'constituent', 6);
INSERT INTO `words` VALUES (10286, 'We must redefine what constitutes a family.', 'v. 组成， 构成； 建立', '/\'kɑːnstətuːt | \'kɑnstətut/', 'constitute', 6);
INSERT INTO `words` VALUES (10287, 'The right to speak freely is written into the Constitution of the United States.', 'n. 宪法； 体质', '/ˌkɑːnstə\'tuːʃn | \'kɑnstə\'tʊʃən/', 'constitution', 6);
INSERT INTO `words` VALUES (10288, 'Poor soil has constrained the level of crop production.', 'v. 束缚， 强迫； 限制', '/kən\'streɪn | kən\'stren/', 'constrain', 6);
INSERT INTO `words` VALUES (10289, 'Their decision to abandon the trip was made because of financial constraints.', 'n. 强制， 强迫； 对感情的压抑', '/kən\'streɪnt | kən\'strent/', 'constraint', 6);
INSERT INTO `words` VALUES (10290, 'Caffeine constricts the blood vessels in your body.', 'v. 约束； 收缩', '/kən\'strɪkt/', 'constrict', 6);
INSERT INTO `words` VALUES (10291, 'There are plans to construct a new road bridge across the river.', 'v. 建造， 构造', '/kən\'strʌkt/', 'construct', 6);
INSERT INTO `words` VALUES (10292, 'difficult grammatical constructions', 'n. 结构， 句法关系； 解释， 理解', '/kən\'strʌkʃn | kən\'strʌkʃən/', 'construction', 6);
INSERT INTO `words` VALUES (10293, 'The meeting was very constructive.', 'adj. 建设性的', '/kən\'strʌktɪv/', 'constructive', 6);
INSERT INTO `words` VALUES (10294, 'What may seem helpful behaviour to you can be construed as interference by others.', 'v. 解释, 分析, 直译', '/kən\'stru:, \'kɔnstru: | kən\'struː | kən\'stru/', 'construe', 6);
INSERT INTO `words` VALUES (10295, 'the British Consul in Paris', 'n. 领事', '/\'kɑːnsl | \'kɑnsl/', 'consul', 6);
INSERT INTO `words` VALUES (10296, 'If symptoms persist, consult a doctor without delay.', 'v. 请教，咨询，商量; n. 咨询', '/kən\'sʌlt/', 'consult', 6);
INSERT INTO `words` VALUES (10297, 'His wife divorced him for failing to consummate their marriage.', 'v. 完成, 使达到极点', '/\'kɔnsə,meit | \'kɒnsjʊmeɪt; -sə- | \'kɑnsəmət/', 'consummate', 6);
INSERT INTO `words` VALUES (10298, 'the consummation of his ambitions', 'n. 完成, 圆满成功, 成就', '/,kɔnsə\'meiʃən | kɒnsə\'meɪʃ(ə)n; -sjʊ- | ,kɑnsə\'meʃən/', 'consummation', 6);
INSERT INTO `words` VALUES (10299, 'Vigorous exercise increases oxygen consumption.', 'n. 消费， 消耗', '/kən\'sʌmpʃn | kən\'sʌmpʃən/', 'consumption', 6);
INSERT INTO `words` VALUES (10300, NULL, 'v. 接触； 互通信息', '/\'kɑːntækt | \'kɑntækt/', 'contact', 6);
INSERT INTO `words` VALUES (10301, 'There is some danger of contagion.', 'n. 传染, 传染病, 蔓延, 歪风, 腐化', '/kən\'teidʒən | kən\'teɪdʒ(ə)n | kən\'tedʒən/', 'contagion', 6);
INSERT INTO `words` VALUES (10302, 'The patient is still highly contagious.', 'adj. 传染性的, 会感染的', '/kən\'teidʒəs | kən\'teɪdʒəs | kən\'tedʒəs/', 'contagious', 6);
INSERT INTO `words` VALUES (10303, 'The letter contained information about Boulestin’s legal affairs.', 'v. 包含， 含有； 控制； 阻止， 遏制', '/kən\'teɪn | kən\'ten/', 'contain', 6);
INSERT INTO `words` VALUES (10304, 'Fire crews are hoping they can achieve full containment of the fire before the winds pick up.', 'n. 阻止， 遏制', '/kən\'teɪnmənt | kən\'tenmənt/', 'containment', 6);
INSERT INTO `words` VALUES (10305, 'Drinking water supplies are believed to have been contaminated.', 'v. 弄脏， 污染', '/kən\'tæmɪneɪt | kən\'tæmɪnet/', 'contaminate', 6);
INSERT INTO `words` VALUES (10306, NULL, 'n. 小故事', '/\'kənte | kon\'te/', 'conte', 6);
INSERT INTO `words` VALUES (10307, 'He contemplated her with a faint smile.', 'v. 凝视, 沉思, 预期, 企图', '/\'kɔntəm,pleit | \'kɒntempleɪt; -təm- | \'kɑntəmplet/', 'contemplate', 6);
INSERT INTO `words` VALUES (10308, 'The monks spend an hour in contemplation each morning.', 'n. 注视, 沉思, 预期, 企图, 打算', '/,kɔntem\'pleiʃən | ,kɒntem\'pleɪʃ(ə)n | ,kɑntəm\'pleʃən/', 'contemplation', 6);
INSERT INTO `words` VALUES (10309, 'a contemplative mood', 'adj. 沉思的; n. 沉思者', '/kən\'templətɪv | kən\'tɛmplətɪv/', 'contemplative', 6);
INSERT INTO `words` VALUES (10310, 'She writes a lot of contemporary music for people like Whitney Houston.', 'adj. 同时代的； 当代的； 现代的', '/kən\'tempəreri | kən\'tɛmpərɛri/', 'contemporary', 6);
INSERT INTO `words` VALUES (10311, 'The public is treated with contempt by broadcasters.', 'n. 轻视, 轻蔑, 耻辱, 不尊敬, [律]藐视法庭(或国会)', '/kən\'tempt | kən\'tem(p)t | kən\'tɛmpt/', 'contempt', 6);
INSERT INTO `words` VALUES (10312, 'They were portrayed as contemptible cowards.', 'adj. 可鄙的', '/kən\'temptəbl | kən\'tem(p)tɪb(ə)l | kən\'tɛmptəbl/', 'contemptible', 6);
