INSERT INTO `words` VALUES (10314, 'Inevitably, fights break out between the members of contending groups.', 'v. 竞争， 争夺； 争论， 争辩', '/kən\'tend | kən\'tɛnd/', 'contend', 6);
INSERT INTO `words` VALUES (10315, 'Andy was a good husband, and Nicky was clearly very content.', 'adj. 知足的，满意的; v. 满意；满足; n. 满意； 内容', '/kən\'tent | \'kɑntɛnt/', 'content', 6);
INSERT INTO `words` VALUES (10316, 'I felt warm, cosy, and contented.', 'adj. 心满意足的', '/kən\'tentɪd | kən\'tɛntɪd/', 'contented', 6);
INSERT INTO `words` VALUES (10317, 'It is my contention that death and murder always lurk as potentials in violent relationships.', 'n. 争夺, 争论, 争辩, 论点', '/kən\'tenʃən | kən\'tenʃ(ə)n | kən\'tɛnʃən/', 'contention', 6);
INSERT INTO `words` VALUES (10318, 'Sanctions are expected to be among the most contentious issues.', 'adj. 好争吵的, 争论的, 有异议的', '/kən\'tenʃəs | kənˈtenʃəs/', 'contentious', 6);
INSERT INTO `words` VALUES (10319, 'His brothers are contesting the will.', 'v. 竞争； 质疑', '/\'kɑːntest | kən\'tɛst/', 'contest', 6);
INSERT INTO `words` VALUES (10320, 'The meaning of ‘mad’ depends on its context. mad', 'n. 上下文', '/\'kɑːntekst | \'kɑntɛkst/', 'context', 6);
INSERT INTO `words` VALUES (10321, NULL, 'n. 接触, 接近, 邻近', '/,kɔnti\'ɡju:iti | ,kɒntɪ\'gjuːɪtɪ | ,kɑntə\'gjʊəti/', 'contiguity', 6);
INSERT INTO `words` VALUES (10322, 'America’s 48 contiguous states', 'adj. 邻近的, 接近的, 毗边的', '/kən\'tiɡjuəs | kən\'tɪgjʊəs | kən\'tɪɡjuəs/', 'contiguous', 6);
INSERT INTO `words` VALUES (10323, 'Now the word \"continence\" there is just referring to asceticism, but in this text it doesn\'t mean just controlling your sex life, it means not having sex entirely.', 'n. 自制, 克制, 节欲(尤指禁欲)', '/\'kɔntinəns | \'kɒntɪnəns | \'kɑntɪnəns/', 'continence', 6);
INSERT INTO `words` VALUES (10324, 'the continents of Asia and Africa', 'n. 大陆, 陆地', '/\'kɔntinənt | \'kɒntɪnənt | \'kɑntɪnənt/', 'continent', 6);
INSERT INTO `words` VALUES (10325, 'the warming-up of continental interiors', 'adj. 大陆的， 大陆性的', '/ˌkɑːntɪ\'nentl | ,kɑntɪ\'nɛntl/', 'continental', 6);
INSERT INTO `words` VALUES (10326, 'a contingency plan', 'n. 偶然, 可能性, 意外事故, 可能发生的附带事件', '/kən\'tɪndʒ(ə)nsɪ | kən\'tɪndʒənsi/', 'contingency', 6);
INSERT INTO `words` VALUES (10327, NULL, 'adj. 可能发生的, 附随的, 暂时的', '/kən\'tɪndʒ(ə)nt | kən\'tɪndʒənt/', 'contingent', 6);
INSERT INTO `words` VALUES (10328, 'It\'s the coalition forces who are to blame for the continuation of the war.', 'n. 继续， 延续', '/kənˌtɪnju\'eɪʃn | kən\'tɪnjʊ\'eʃən/', 'continuation', 6);
INSERT INTO `words` VALUES (10329, 'His face contorts as he screams out the lyrics.', 'v. 扭曲, 歪曲', '/kən\'tɔ:t | kən\'tɔːt | kən\'tɔrt/', 'contort', 6);
INSERT INTO `words` VALUES (10330, 'involuntary muscle contortion', 'n. 扭弯, 扭歪, 歪曲', '/kən\'tɔ:ʃən | kən\'tɔːʃən/', 'contortion', 6);
INSERT INTO `words` VALUES (10331, 'a cargo of contraband', 'n. 违法交易, 违禁品, 走私', '/\'kɔntrə,bænd | \'kɒntrəbænd | \'kɑntrə\'bænd/', 'contraband', 6);
INSERT INTO `words` VALUES (10332, 'Employees who refuse to relocate are in breach of contract (= have done something not allowed by their contracts ) .', 'n. 合同, 契约, 婚约', '/\'kɔntrækt, kən\'trækt | \'kɒntrækt | \'kɑntrækt/', 'contract', 6);
INSERT INTO `words` VALUES (10333, 'the contraction of metal as it cools', 'n. 收缩, 缩写式, 紧缩', '/kən\'trækʃən | kən\'trækʃ(ə)n/', 'contraction', 6);
INSERT INTO `words` VALUES (10334, 'Deborah opened her mouth to contradict, but closed it again.', 'v. 反驳， 驳斥', '/ˌkɑːntrə\'dɪkt | \'kɑntrə\'dɪkt/', 'contradict', 6);
INSERT INTO `words` VALUES (10335, 'Customs officials have made a series of contradictory statements about the equipment.', 'adj. 反驳的， 反对的， 抗辩的', '/ˌkɑːntrə\'dɪktəri | ,kɑntrə\'dɪktəri/', 'contradictory', 6);
INSERT INTO `words` VALUES (10336, 'Two contrary views emerged.', 'adj. 相反的； 对抗的', '/\'kɑːntreri | \'kɑntrɛri/', 'contrary', 6);
