INSERT INTO `words` VALUES (10340, 'Blankfein was clearly trying to placate the locals and show some kind of contrition.', 'n. 悔悟, 后悔', '/kən\'triʃən | kən\'trɪʃ(ə)n/', 'contrition', 6);
INSERT INTO `words` VALUES (10341, 'In 1862, a technique was contrived to take a series of photographs showing stages of movement.', 'v. 发明, 设计, 图谋', '/kən\'traiv | kən\'traɪv/', 'contrive', 6);
INSERT INTO `words` VALUES (10342, 'The characters are as contrived as the plot.', 'adj. 人为的, 做作的', '/kən\'traivd | kən\'traɪvd/', 'contrived', 6);
INSERT INTO `words` VALUES (10343, 'pest control', 'n. 对照标准， 对照物', '/kən\'troul | kən\'trol/', 'control', 6);
INSERT INTO `words` VALUES (10344, 'the controversial issue of welfare reform', 'adj. 引起或可能引起争论的', '/ˌkɑːntrə\'vɜːrʃl | ,kɑntrə\'vɝʃl/', 'controversial', 6);
INSERT INTO `words` VALUES (10345, 'a political controversy', 'n. 论争, 辩论, 论战', '/\'kɔntrə,və:si | \'kɒntrəvɜːsɪ; kən\'trɒvəsɪ | ˈkɑːntrəvɜːrsi/', 'controversy', 6);
INSERT INTO `words` VALUES (10346, 'Have taken part in academy controvert competition four times, and named as \"best debate student\" four times and \"best elegant demeanor\" one time.', 'v. 议论, 辩论', '/\'kɔntrə,və:t | \'kɒntrəvɜːt; ,kɒntrə\'vɜːt/', 'controvert', 6);
INSERT INTO `words` VALUES (10347, 'There is another efficacious method for subduing the most obstinate, contumacious sinner.', 'adj. 不听令的, 顽固的, 反抗法院命令的', '/,kɔntju:\'meiʃəs | ,kɒntjʊ\'meɪʃəs | ,kɑntu\'meʃəs/', 'contumacious', 6);
INSERT INTO `words` VALUES (10348, NULL, 'n. 拒不服从, 倔强', '/\'kɔntjuməsi | \'kɒntjʊməsɪ/', 'contumacy', 6);
INSERT INTO `words` VALUES (10349, 'Furthermore, the aggressor wrote contumelious words aft .', 'adj. 傲慢的, 侮辱性的', '/,kɔntju:\'mi:ljəs | ,kɒntjʊ\'miːlɪəs/', 'contumelious', 6);
INSERT INTO `words` VALUES (10350, NULL, 'n. 无礼, 傲慢, 侮辱', '/\'kɔntjumili | \'kɒntjuːmɪlɪ; -tjuːmlɪ/', 'contumely', 6);
INSERT INTO `words` VALUES (10351, 'The sports trauma not only damage their health, which contuse the enthusiasm of physical activity, but also effect normal study living, indeed the suffering of mentally and physical.', 'v. 打伤, 挫伤, 撞伤', '/kən\'tju:z | kən\'tjuːz | kən\'tjʊz/', 'contuse', 6);
INSERT INTO `words` VALUES (10352, 'the conundrum of our purpose on Earth', 'n. (答案有双关意义的)谜语, 难题', '/kə\'nʌndrəm/', 'conundrum', 6);
INSERT INTO `words` VALUES (10353, 'After two weeks, I was allowed home, where I convalesced for three months.', 'v. 渐渐康复, 渐愈', '/,kɔnvə\'les | ,kɒnvə\'les | ,kɑnvə\'lɛs/', 'convalesce', 6);
INSERT INTO `words` VALUES (10354, 'a long and painful convalescence', 'n. 逐渐康复', '/,kɔnvə\'lesəns | ,kɒnvə\'lesns | ,kɑnvə\'lɛsns/', 'convalescence', 6);
