INSERT INTO `words` VALUES (10359, NULL, 'v. 使按惯例， 使习俗化', '/kən\'venʃənəlaɪz | kən\'vɛnʃənl,aɪz/', 'conventionalize', 6);
INSERT INTO `words` VALUES (10360, 'The two rivers converge into one near Pittsburgh.', 'v. 聚合, 集中于一点', '/kən\'və:dʒ | kən\'vɜːdʒ | kən\'vɝdʒ/', 'converge', 6);
INSERT INTO `words` VALUES (10361, NULL, 'adj. 会聚的', '/kən\'vɜːrdʒənt | kən\'vɝdʒənt/', 'convergent', 6);
INSERT INTO `words` VALUES (10362, 'Those in business are not, on the whole, conversant with basic scientific principles.', 'adj. 亲近的, 有交情的, 熟悉的', '/kən\'və:sənt | kən\'vɜːs(ə)nt | kən\'vɝsnt/', 'conversant', 6);
INSERT INTO `words` VALUES (10363, 'Luke sat directly behind the pilot and conversed with him.', 'v. 谈话，交谈[\'kɑːnvɜːrs]; adj. 逆向的; n. 相反的事物', '/kən\'vɜːrs | kən\'vəʳs/', 'converse', 6);
INSERT INTO `words` VALUES (10364, '...the conversion of disused rail lines into cycle routes.', 'n. 变换, 转化', '/kən\'və:ʃən | kən\'vɜːʃ(ə)n | kən\'vɝʒn/', 'conversion', 6);
INSERT INTO `words` VALUES (10365, NULL, 'n. 皈依者', '/kən\'və:t | kən\'vɜːt | kən\'vɝt/', 'convert', 6);
INSERT INTO `words` VALUES (10366, 'a convertible sofa', 'adj. 可改变的, 自由兑换的', '/kən\'və:təbl | kən\'vɜːtɪb(ə)l | kən\'vɝtəbl/', 'convertible', 6);
INSERT INTO `words` VALUES (10367, 'a convex lens', 'adj. 表面弯曲如球的外侧, 凸起的', '/kɔn\'veks | \'kɒnveks | \'kɑnvɛks/', 'convex', 6);
INSERT INTO `words` VALUES (10368, 'a convicted murderer', 'v. 定罪[\'kɑːnvIkt]; n. 罪犯', '/kən\'vɪkt/', 'convict', 6);
INSERT INTO `words` VALUES (10369, 'It was a reasonable explanation, but his voice lacked conviction .', 'n. 深信, 确信, 定罪, 宣告有罪', '/kən\'vɪkʃ(ə)n | kən\'vɪkʃən/', 'conviction', 6);
INSERT INTO `words` VALUES (10370, 'Her arguments didn’t convince everyone, but changes were made.', 'v. 使某人确信； 说服', '/kən\'vɪns/', 'convince', 6);
