INSERT INTO `words` VALUES (10372, '...a convocation of the American Youth Congress.', 'n. 集会, 召集, 教士会议', '/,kɔnvəu\'keiʃən | ,kɒnvə\'keɪʃ(ə)n | ,kɑnvə\'keʃən/', 'convocation', 6);
INSERT INTO `words` VALUES (10373, 'Separate meetings had been convoked by the two opposing factions.', 'v. 召集', '/kən\'vəuk | kən\'vəʊk | kən\'vok/', 'convoke', 6);
