INSERT INTO `words` VALUES (10375, 'a military convoy', 'n. 护送, 护卫', '/\'kɔnvɔi, kən\'vɔi | \'kɒnvɒɪ | \'kɑnvɔɪ/', 'convoy', 6);
INSERT INTO `words` VALUES (10376, 'He sat down, his shoulders convulsing with sobs.', 'v. 震动, 震撼, 使抽筋', '/kən\'vʌls/', 'convulse', 6);
INSERT INTO `words` VALUES (10377, 'His temperature was very high and he went into convulsions .', 'n. 震撼, 动乱, 震动, 惊厥, 痉挛', '/kən\'vʌlʃən | kən\'vʌlʃ(ə)n/', 'convulsion', 6);
INSERT INTO `words` VALUES (10378, '...a chicken coop.', 'n. 小屋, 鸡(兔)笼, 拘留所, <俗>监狱', '/ku:p | kuːp | kʊp/', 'coop', 6);
INSERT INTO `words` VALUES (10379, 'The agencies are working together to co-ordinate policy on food safety.', 'v. 使各部分协调; adj. 同等的', '/kəʊ\'ɔ:dɪneɪt | ko\'ɔrdɪnet/', 'coordinate', 6);
INSERT INTO `words` VALUES (10380, 'He could drink copious amounts of beer without ill effect.', 'adj. 很多的, 广识的, 丰富的', '/\'kəupiəs | \'kəʊpɪəs | \'kopɪəs/', 'copious', 6);
INSERT INTO `words` VALUES (10381, 'During the time she is paired to a male, the female allows no other males to copulate with her.', 'v. 性交, 交配, 交尾', '/\'kɔpju,leit | \'kɒpjʊleɪt/', 'copulate', 6);
INSERT INTO `words` VALUES (10382, 'Who owns the copyright of this book?', 'n. 版权, 著作权', '/\'kɔpi,rait | \'kɒpɪraɪt | \'kɑpɪraɪt/', 'copyright', 6);
INSERT INTO `words` VALUES (10383, NULL, 'n. (女子)玩弄男人, 卖弄风骚, 撒娇, 献媚', '/\'kɔkitri | \'kɒkɪtrɪ; \'kəʊ- | \'kokɪtri/', 'coquetry', 6);
INSERT INTO `words` VALUES (10384, 'Of course she had a perfect right to suit herself about the kind of a man she took for a husband, but he certainly had not thought she was such an utter coquette.', 'n. 卖弄风情之女子', '/kɔ\'ket | kɒ\'ket | ko\'kɛt/', 'coquette', 6);
INSERT INTO `words` VALUES (10385, 'The talks were conducted in a cordial atmosphere.', 'adj. 热诚的; n. 兴奋剂', '/\'kɔːrdʒəl | \'kɔrdʒəl/', 'cordial', 6);
INSERT INTO `words` VALUES (10386, 'My hostess greeted me with unexpected cordiality.', 'n. 诚恳， 热诚', '/ˌkɔːr\'dʒɪlətɪ | kɔr\'dʒæləti/', 'cordiality', 6);
INSERT INTO `words` VALUES (10387, 'Police formed a cordon between the two crowds.', 'n. 哨兵线, 警戒线, 饰带', '/\'kɔ:dən | \'kɔːd(ə)n | \'kɔrdn/', 'cordon', 6);
INSERT INTO `words` VALUES (10388, '...machines for peeling and coring apples.', 'v. 去掉某物的中心部分; n. 果心；核心', '/kɔːr | kɔr/', 'core', 6);
INSERT INTO `words` VALUES (10389, NULL, 'n. 圆锥形纸袋, 短号', '/\'kɔ:nit | \'kɔːnɪt | \'kɔrnɪt/', 'cornet', 6);
INSERT INTO `words` VALUES (10390, NULL, 'n. (尤指沿山崖筑出视界开阔的)滨海路(亦作corniche road)', '/\'kɔːnɪʃ; kɔː\'niːʃ | \'kɔ:niʃ/', 'corniche', 6);
INSERT INTO `words` VALUES (10391, '...a table festooned with a cornucopia of fruit.', 'n. [希神]哺乳宙斯的羊角, 满装花果象征丰饶的羊角(通常用于绘画或雕刻中), 丰富, 丰饶', '/,kɔ:nju\'kəupjə | ,kɔːnjʊ\'kəʊpɪə | \'kɔrnjʊ\'kopɪə/', 'cornucopia', 6);
INSERT INTO `words` VALUES (10392, 'corny jokes', 'adj. 谷类的, 乡下味的, 粗野的, 有鸡眼的', '/\'kɔ:ni | \'kɔːnɪ | \'kɔrni/', 'corny', 6);
INSERT INTO `words` VALUES (10393, NULL, 'n. 冠壮物,王冠, 光环', '/kə\'rəunə | kə\'rəʊnə | kə\'ronə/', 'corona', 6);
INSERT INTO `words` VALUES (10394, 'When they first saw each other in royal clothing, the fine robes and shining crowns for their coronation, that was when they fell in love.', 'n. 加冕礼', '/,kɔ:rə\'neiʃən | kɒrə\'neɪʃ(ə)n | \'kɔrə\'neʃən/', 'coronation', 6);
INSERT INTO `words` VALUES (10395, 'He was demoted to the rank of corporal.', 'n. <美>下士', '/\'kɔ:pərəl | \'kɔːp(ə)r(ə)l | \'kɔrpərəl/', 'corporal', 6);
INSERT INTO `words` VALUES (10396, 'corporate responsibility', 'adj. 社团的, 法人的, 共同的, 全体的', '/\'kɔːp(ə)rət | ˈkɔːrpərət/', 'corporate', 6);
INSERT INTO `words` VALUES (10397, 'corporeal desires', 'adj. 肉体的， 身体的； 物质的', '/kɔːr\'pɔːriəl | kɔr\'pɔrɪəl/', 'corporeal', 6);
INSERT INTO `words` VALUES (10398, 'This article makes a deep analysis of corpulence affecting health from physiology, psychology and sociology and puts forward the effective preventing measures against corpulence.', 'n. 肥胖', '/\'kɔ:pjuləns | \'kɔːpjʊləns | \'kɔrpjələns/', 'corpulence', 6);
INSERT INTO `words` VALUES (10399, '...a rather corpulent farmer.', 'adj. 肥大的, 肥胖的', '/\'kɔ:pjulənt | \'kɔːpjʊl(ə)nt | \'kɔrpjələnt/', 'corpulent', 6);
INSERT INTO `words` VALUES (10400, 'the entire corpus of Shakespeare’s works', 'n. 尸体, 文集, (某项基金的)本金', '/\'kɔ:pəs | \'kɔːpəs | \'kɔrpəs/', 'corpus', 6);
INSERT INTO `words` VALUES (10401, 'He called this negative elemental particle the corpuscle.', 'n. 血球, <物理>微粒', '/\'kɔ:pʌsl | \'kɔːpʌs(ə)l | \'kɔrpʌsl/', 'corpuscle', 6);
INSERT INTO `words` VALUES (10402, NULL, 'n. 畜栏', '/kɔ:\'rɑ:l | kə\'rɑːl | kə\'ræl/', 'corral', 6);
INSERT INTO `words` VALUES (10403, 'Attempts to correlate specific language functions with particular parts of the brain have not advanced very far.', 'v. 使相互关联', '/\'kɔ:rə,leit | \'kɒrəleɪt; -rɪ- | \'kɔrəlet/', 'correlate', 6);
INSERT INTO `words` VALUES (10404, 'The amount of love you get from an investment in love is correlated, if only roughly, to the amount of yourself you invest in the relationship.', 'adj. 有相互关系的', '/\'kɔːrəleɪtɪd | \'kɔrə,letɪd/', 'correlated', 6);
INSERT INTO `words` VALUES (10405, 'Our correspondent in South Africa sent this report.', 'n. 通讯记者, 通信者', '/,kɔ:ri\'spɔndənt | kɒrɪ\'spɒnd(ə)nt | ,kɔrə\'spɑndənt/', 'correspondent', 6);
INSERT INTO `words` VALUES (10406, NULL, 'n. 勘误表', '/,kɔ:ri\'dʒendəm | ,kɒrɪ\'dʒendəm | ,kɔrɪ\'dʒɛndəm/', 'corrigendum', 6);
INSERT INTO `words` VALUES (10407, 'As a corroborant theory, what it mainly encounters is \"tracing argumentation\".', 'adj. 确证的, 使强固的', '/kə\'rɔbərənt | kə\'rɒbərənt | kə\'rɑbərənt/', 'corroborant', 6);
INSERT INTO `words` VALUES (10408, 'We now have new evidence to corroborate the defendant’s story.', 'v. 使坚固, 确证', '/kə\'rɔbə,reit | kə\'rɒbəreɪt | kə\'rɑbəret/', 'corroborate', 6);
INSERT INTO `words` VALUES (10409, 'Definitely more independent corroboration is necessary .', 'n. 使确实, 确证的事实, 确证', '/kə,rɔbə\'reiʃən/', 'corroboration', 6);
INSERT INTO `words` VALUES (10410, 'Acidic water will corrode the pipes.', 'v. 腐蚀， 侵蚀', '/kə\'roud | kə\'rod/', 'corrode', 6);
INSERT INTO `words` VALUES (10411, 'a highly corrosive substance', 'adj. 腐蚀性的， 腐蚀的， 蚀坏的', '/kə\'rousɪv | kə\'rosɪv/', 'corrosive', 6);
INSERT INTO `words` VALUES (10412, NULL, 'v. 弄皱, 起皱, (使)成波状', '/\'kɔ:ruɡeit | \'kɒrʊgeɪt | \'kɔrə,get/', 'corrugate', 6);
INSERT INTO `words` VALUES (10413, 'corrugated cardboard', 'adj. 起皱纹的', '/\'kɔːrəgeɪtɪd | \'kɔrə\'getɪd/', 'corrugated', 6);
INSERT INTO `words` VALUES (10414, 'The two kinds of flaws, namely breakage and corrugation, which were caused by the design proposal under initial condition were discovered by analyzing the forming limit chart after the simulation.', 'n. 成皱, 起皱, 皱状', '/,kɔ:ru\'ɡeiʃən | ,kɔːrʊ\'ɡeɪʃən | ,kɔrə\'geʃən/', 'corrugation', 6);
INSERT INTO `words` VALUES (10415, 'Corrupt judges have taken millions of dollars in bribes.', 'adj. 腐败的，堕落的；讹误的，走样的containingerrorsorchanges); v. 使腐败， 使堕落', '/kə\'rʌpt/', 'corrupt', 6);
INSERT INTO `words` VALUES (10416, 'officials charged with bribery and corruption', 'n. 腐败， 堕落', '/kə\'rʌpʃn | kə\'rʌpʃən/', 'corruption', 6);
INSERT INTO `words` VALUES (10417, '...the cerebral cortex.', 'n. (植物的)皮层, 树皮, (脑或肾的)皮层, 皮质', '/\'kɔ:teks | \'kɔːteks | \'kɔrtɛks/', 'cortex', 6);
INSERT INTO `words` VALUES (10418, 'What kind of mood can let person mind coruscate?', 'v. 闪烁, 焕发', '/\'kɔ:rəs,keit | \'kɒrəskeɪt | \'kɔrəsket/', 'coruscate', 6);
INSERT INTO `words` VALUES (10419, '...the cosmic laws governing our world.', 'adj. 宇宙的', '/\'kɔzmik | \'kɒzmɪk | \'kɑzmɪk/', 'cosmic', 6);
INSERT INTO `words` VALUES (10420, 'a vibrant, cosmopolitan city', 'adj. 世界性的，全球的; n. 世界主义者， 四海为家的人', '/ˌkɑːzmə\'pɑːlɪtən | \'kɑzmə\'pɑlətn/', 'cosmopolitan', 6);
INSERT INTO `words` VALUES (10421, 'A certain optimism adheres to the notion of a new cosmopolitanism.', 'n. 世界性， 世界主义', '/,kɔzmə\'pɔlitənizəm | ˌkɑːzmə\'pɑːlɪtənɪzəm/', 'cosmopolitanism', 6);
INSERT INTO `words` VALUES (10422, '...the natural laws of the cosmos.', 'n. 宇宙', '/\'kɑːzmous | \'kɑzmos/', 'cosmos', 6);
INSERT INTO `words` VALUES (10423, 'He cosseted her with flowers and champagne.', 'n. 亲手饲养的宠物, 宠儿', '/\'kɔsit | \'kɒsɪt | \'kɑsɪt/', 'cosset', 6);
INSERT INTO `words` VALUES (10424, 'the film’s lavish costumes and spectacular sets', 'n. 装束, 服装', '/\'kɔstju:m, kɔ\'stju:m | \'kɒstjuːm | \'kɑstum/', 'costume', 6);
INSERT INTO `words` VALUES (10425, 'The living room was warm and cosy .', 'adj. 舒适的, 安逸的', '/\'kəuzi | \'kəʊzɪ | ˈkozi/', 'cosy', 6);
INSERT INTO `words` VALUES (10426, NULL, 'adj. 温暖而舒适的', '/\'kouzi/', 'cosycozy', 6);
INSERT INTO `words` VALUES (10427, 'We three formed a little literary coterie.', 'n. 同行, 圈内人, 伙伴', '/\'kəutəri | \'kəʊt(ə)rɪ | \'kotəri/', 'coterie', 6);
INSERT INTO `words` VALUES (10428, NULL, 'adj. 相连的, 连接的', '/kəu\'tə:minəs | kəʊ\'tɜːmɪnəs | ko\'tɝmɪnəs/', 'coterminous', 6);
INSERT INTO `words` VALUES (10429, 'Between films he often winds up spending every single morning on his psychiatrist\'s couch.', 'n. (文学)床, 睡椅', '/kautʃ | kaʊtʃ/', 'couch', 6);
INSERT INTO `words` VALUES (10430, 'Then Mrs. McAlister grabbed a shovel in the yard and swung it at the cougar.', 'n. [动]美洲狮(尤指Felis concolor)', '/\'kuːgə | \'kuɡɚ/', 'cougar', 6);
INSERT INTO `words` VALUES (10431, 'All colour drained from her countenance.', 'n. 面容, 脸色, 支持', '/\'kauntənəns | \'kaʊnt(ə)nəns; -tɪn- | \'kaʊntənəns/', 'countenance', 6);
INSERT INTO `words` VALUES (10432, 'They gave him drugs to counteract his withdrawal symptoms.', 'v. 抵消, 中和, 阻碍', '/,kauntə\'rækt | kaʊntər\'ækt | ,kaʊntɚ\'ækt/', 'counteract', 6);
INSERT INTO `words` VALUES (10433, 'Add honey to counterbalance the acidity.', 'v. 起平衡作用', '/ˌkauntər\'bæləns | ,kaʊntɚ\'bæləns/', 'counterbalance', 6);
INSERT INTO `words` VALUES (10434, 'The dance moves in a counterclockwise direction.', 'adj&adv. 逆时针方向的', '/ˌkauntər\'klɑːkwaɪz | \'kaʊntɚ\'klɑk\'waɪz/', 'counterclockwise', 6);
INSERT INTO `words` VALUES (10435, 'They admitted counterfeiting documents.', 'v. 伪造，仿造; adj. 伪造的， 假冒的', '/\'kauntərfɪt | \'kaʊntɚ\'fɪt/', 'counterfeit', 6);
INSERT INTO `words` VALUES (10436, 'I can\'t countermand an order Winger\'s given.', 'v. 取消, 撤消, 下反对命令召回', '/,kauntə\'mɑ:nd, \'kauntəmɑ:nd | ,kaʊntə\'mɑːnd | \'kaʊntɚmænd/', 'countermand', 6);
INSERT INTO `words` VALUES (10437, 'As soon as he heard what was afoot, he telephoned his German and Italian counterparts to protest.', 'n. 相对应或具有相同功能的人或物', '/\'kauntərpɑːrt | \'kaʊntɚpɑrt/', 'counterpart', 6);
INSERT INTO `words` VALUES (10438, NULL, 'adj. 事与愿违的', '/ˌkauntərprə\'dʌktɪv | ,kaʊntɚprə\'dʌktɪv/', 'counterproductive', 6);
INSERT INTO `words` VALUES (10439, 'a famous film clip which has been shown countless times', 'adj. 无数的', '/\'kauntləs | \'kaʊntləs/', 'countless', 6);
INSERT INTO `words` VALUES (10440, 'the countrified existence of the newly rich', 'adj. 乡村的； 粗俗的', '/\'kʌntrifaɪd | \'kʌntrɪfaɪd/', 'countrified', 6);
INSERT INTO `words` VALUES (10441, 'Haiti’s first elected President was deposed in a violent military coup .', 'n. 砰然而有效的一击, 妙计, 出乎意料的行动, 政变', '/ku: | kuː | kʊ/', 'coup', 6);
INSERT INTO `words` VALUES (10442, 'It could not be proved in a court of law.', 'n. 法庭；', '/kɔːrt | kɔrt/', 'court', 6);
INSERT INTO `words` VALUES (10443, 'The staff are always courteous and helpful.', 'adj. 有礼貌的', '/\'kɜːrtiəs | \'kɝtɪəs/', 'courteous', 6);
INSERT INTO `words` VALUES (10444, 'Many picnics manage without this sophistication , but we like to be couth and feel that the delicacies of gracious living enhance the chancesJohn Gould.', 'adj. 文雅的, 有礼貌的', '/ku:θ | kuːθ | kʊθ/', 'couth', 6);
INSERT INTO `words` VALUES (10445, '...the International Covenant on Civil and Political Rights.', 'n. 契约, 盟约', '/\'kʌvənənt | \'kʌv(ə)nənt/', 'covenant', 6);
INSERT INTO `words` VALUES (10446, 'covert operations', 'adj. 隐蔽的, 偷偷摸摸的, [律]在丈夫保护下的', '/\'kʌvət | \'kʌvət; \'kəʊvɜːt | \'kovɝt/', 'covert', 6);
INSERT INTO `words` VALUES (10447, 'The Michelin Awards are coveted by restaurants all over the world.', 'v. 垂涎, 觊觎', '/\'kʌvit | \'kʌvɪt | \'kʌvət/', 'covet', 6);
INSERT INTO `words` VALUES (10448, 'They began to cast covetous eyes on their neighbours’ fields.', 'adj. 贪婪的, 妄羡的', '/\'kʌvitəs | ˈkʌvətəs | \'kʌvətəs/', 'covetous', 6);
INSERT INTO `words` VALUES (10449, NULL, 'n. ［古］欺诈', '/\'kʌvɪn | \'kovɪŋ/', 'covin', 6);
INSERT INTO `words` VALUES (10450, 'a herd of cows', 'n. 母牛, 大型母兽', '/kau | kaʊ/', 'cow', 6);
INSERT INTO `words` VALUES (10451, 'Try it. Don’t be such a coward.', 'n. 胆小鬼', '/\'kauərd | \'kaʊɚd/', 'coward', 6);
INSERT INTO `words` VALUES (10452, 'cowardice in the face of danger', 'n. 怯懦, 胆小', '/\'kauədis | \'kaʊədɪs | \'kaʊɚdɪs/', 'cowardice', 6);
INSERT INTO `words` VALUES (10453, 'The hostages cowered in their seats.', 'v. 畏缩, 退缩', '/\'kauə | \'kaʊə | \'kaʊɚ/', 'cower', 6);
INSERT INTO `words` VALUES (10454, 'I was sickened by the way Carol charmed all the men by turning coy.', 'adj. 腼腆的, 怕羞的, 卖弄风情的', '/kɔi | kɒɪ | kɔɪ/', 'coy', 6);
INSERT INTO `words` VALUES (10455, 'What devil was \'t that thus hath cozen\'d you at hoodman-blind?', 'v. 欺骗, 瞒', '/\'kʌzən | \'kʌz(ə)n/', 'cozen', 6);
INSERT INTO `words` VALUES (10456, 'Likewise, the good habit of doing exercises every day means repeatedly dragging oneself away from the TV series and cozy couch.', 'adj. 舒适的, 安逸的, 惬意的', '/ˈkəuzi | \'kozi/', 'cozy', 6);
INSERT INTO `words` VALUES (10457, 'crab meat', 'v. 抱怨， 发牢骚; n. 蟹，螃蟹', '/kræb/', 'crab', 6);
INSERT INTO `words` VALUES (10458, NULL, 'adj. 乖戾的, 易怒的, 难懂的, 潦草的', '/\'kræbid | \'kræbɪd; kræbd | \'kræbɪd/', 'crabbed', 6);
INSERT INTO `words` VALUES (10459, 'Don’t put boiling water in the glass or it will crack.', 'v. 裂开； 破解; n. 爆裂声；裂缝', '/kræk/', 'crack', 6);
INSERT INTO `words` VALUES (10460, 'She was no more a crackpot than the rest of us.', 'n. 怪人， 疯子； 狂想家', '/\'krækpɑːt | \'krækpɑt/', 'crackpot', 6);
INSERT INTO `words` VALUES (10461, 'traditional rural crafts', 'n. 行业； 手艺', '/kræft/', 'craft', 6);
INSERT INTO `words` VALUES (10462, 'He’s a crafty old devil.', 'adj. 狡诈的, 诡计多端的, 善于骗人的', '/\'krɑ:fti | \'krɑːftɪ | \'kræfti/', 'crafty', 6);
INSERT INTO `words` VALUES (10463, NULL, 'n. 峭壁', '/kræɡ | kræg/', 'crag', 6);
INSERT INTO `words` VALUES (10464, 'Thousands of people crammed the mall Sunday.', 'v. 填满', '/kræm/', 'cram', 6);
INSERT INTO `words` VALUES (10465, 'Several players were suffering from cramp.', 'n. 抽筋, 腹部绞痛, 月经痛', '/kræmp/', 'cramp', 6);
INSERT INTO `words` VALUES (10466, 'The kitchen was small and cramped.', 'adj. 狭促的, 难辨的, 难懂的', '/kræmpt/', 'cramped', 6);
INSERT INTO `words` VALUES (10467, NULL, 'adj. 脾气暴燥的, 易怒的', '/kræŋk/', 'crank', 6);
INSERT INTO `words` VALUES (10468, 'Organic farming is no longer thought of as cranky.', 'adj. 任性的, 暴躁的, [航海]摇荡不稳的, 怪僻的', '/\'kræŋki | \'kræŋkɪ/', 'cranky', 6);
INSERT INTO `words` VALUES (10469, NULL, 'adj. 饮(吃)过量的, 暴饮暴食的', '/\'kræpjulənt/', 'crapulent', 6);
INSERT INTO `words` VALUES (10470, 'We watched the waves crashing against the rocks.', 'v. 猛撞； 猛冲直闯； 撞碎', '/kræʃ/', 'crash', 6);
INSERT INTO `words` VALUES (10471, 'a crass remark', 'adj. 愚钝的； 粗糙的', '/kræs/', 'crass', 6);
INSERT INTO `words` VALUES (10472, '...a crate of oranges.', 'n. 板条箱, 柳条箱', '/kreit | kreɪt | kret/', 'crate', 6);
INSERT INTO `words` VALUES (10473, 'craters on the moon’s surface', 'n. 弹坑', '/\'kreitə | \'kreɪtə | \'kretɚ/', 'crater', 6);
INSERT INTO `words` VALUES (10474, NULL, 'n. 领结, 领巾, 围巾, 三角绷带', '/krə\'væt/', 'cravat', 6);
INSERT INTO `words` VALUES (10475, 'an insecure child who craves attention', 'v. 恳求, 渴望', '/kreiv | kreɪv | krev/', 'crave', 6);
INSERT INTO `words` VALUES (10476, 'He had a craven fear of flying.', 'n. 懦夫, 胆小鬼, 怯懦者', '/\'kreivən | \'kreɪv(ə)n | \'krevn/', 'craven', 6);
INSERT INTO `words` VALUES (10477, '\"I spent all my time craving some green space, something green to look at,\" she says.', 'n. 渴望', '/\'kreiviŋ | \'kreɪvɪŋ | \'krevɪŋ/', 'craving', 6);
INSERT INTO `words` VALUES (10478, 'We crawled into bed at 2 am.', 'v. 爬， 爬行', '/krɔːl | krɔl/', 'crawl', 6);
INSERT INTO `words` VALUES (10479, 'He coloured the picture with crayon.', 'n. 有色粉笔, 蜡笔, 粉笔画', '/\'kreiən | ˈkreɪən | ˈkreɪən; ˈkreɪˌɑn/', 'crayon', 6);
INSERT INTO `words` VALUES (10480, 'She stood up, frowning at the creases in her silk dress.', 'n. 折缝, 折痕', '/kri:s | kriːs | kris/', 'crease', 6);
INSERT INTO `words` VALUES (10481, 'Good studies are needed to lend credence to the notion that genuine progress can be made in this important field.', 'n. 信任', '/\'kri:dəns | \'kriːd(ə)ns | \'kridns/', 'credence', 6);
INSERT INTO `words` VALUES (10482, 'Her excuse was barely credible.', 'adj. 可信的， 可靠的', '/\'kredəbl | \'krɛdəbl/', 'credible', 6);
INSERT INTO `words` VALUES (10483, 'The team produced a creditable performance .', 'adj. 可信的', '/\'kreditəbl | \'kredɪtəb(ə)l | \'krɛdɪtəbl/', 'creditable', 6);
INSERT INTO `words` VALUES (10484, 'American Express is emphasizing its ‘the customer is first’ credo.', 'n. 信条', '/\'kriːdou | \'krido/', 'credo', 6);
INSERT INTO `words` VALUES (10485, 'Advertisers were accused of exploiting consumers’ credulity.', 'n. 易信, 轻信', '/kri\'du:liti | krɪ\'djuːlɪtɪ | krɪ\'duləti/', 'credulity', 6);
INSERT INTO `words` VALUES (10486, 'Quinn charmed credulous investors out of millions of dollars.', 'adj. 轻信的', '/\'kredjuləs | \'kredjʊləs | \'krɛdʒələs/', 'credulous', 6);
INSERT INTO `words` VALUES (10487, 'It has never been weaker as a political creed .', 'n. 信条', '/kri:d | kriːd | krid/', 'creed', 6);
INSERT INTO `words` VALUES (10488, 'Follow Austin Creek for a few miles.', 'n. 小溪, 小河, <主英>小港, 小湾', '/kri:k | kriːk | krik/', 'creek', 6);
INSERT INTO `words` VALUES (10489, 'He crept back up the stairs, trying to avoid the ones that creaked.', 'v. 匍匐前进； 悄悄地移动， 蹑手蹑脚地走', '/kriːp | krip/', 'creep', 6);
INSERT INTO `words` VALUES (10490, '...peering through the crepuscular gloom.', 'adj. 微光的, 拂晓的, 黄昏的', '/kri\'pʌskjulə | krɪ\'pʌskjʊlə; kre- | krɪ\'pʌskjəlɚ/', 'crepuscular', 6);
INSERT INTO `words` VALUES (10491, 'The shouting rose to a deafening crescendo .', 'n. 声音渐增', '/kri\'ʃendəu | krɪ\'ʃendəʊ | krə\'ʃɛndo/', 'crescendo', 6);
INSERT INTO `words` VALUES (10492, 'He came back looking crestfallen .', 'adj. 垂头丧气的', '/\'krest,fɔ:lən | \'krestfɔːl(ə)n | \'krɛstfɔlən/', 'crestfallen', 6);
INSERT INTO `words` VALUES (10493, 'No new young cretin has been found during or since the initiation of the Emergency Response Plan in 2007.', 'n. [医]白痴病患者', '/\'kri:tin | \'kretɪn | \'kritn/', 'cretin', 6);
