INSERT INTO `words` VALUES (10501, 'The first crinkles of age were beginning to appear round her eyes.', 'n. 皱纹', '/\'kriŋkl | \'krɪŋk(ə)l | \'krɪŋkl/', 'crinkle', 6);
INSERT INTO `words` VALUES (10502, 'I was abandoned by family and friends as a supposedly hopeless cripple.', 'n. 跛子', '/\'kripl | \'krɪp(ə)l | \'krɪpl/', 'cripple', 6);
