INSERT INTO `words` VALUES (10512, 'Befitting his ideology, Krugman has only one policy to propose, regardless of topic: Transfer more resources from the discipline and dynamism of markets to the inefficiency and cronyism of government.', 'n. 任用亲信', '/\'krəuniizəm | \'krəʊnɪɪz(ə)m | \'kronɪɪzəm/', 'cronyism', 6);
