INSERT INTO `words` VALUES (10604, 'the dappled shade of the trees', 'adj. 有斑点的', '/\'dæpld/', 'dappled', 6);
INSERT INTO `words` VALUES (10605, 'He was a daredevil when young.', 'n. 铤而走险的人, 蛮勇的人', '/\'dεə,devəl | \'deədev(ə)l | \'dɛrdɛvl/', 'daredevil', 6);
INSERT INTO `words` VALUES (10606, 'a poisoned dart', 'n. 标枪, 镖, (昆虫的)刺, 飞快的动作', '/英 [dɑ:t] 美 [dɑrt] | dɑːt | dɑrt/', 'dart', 6);
INSERT INTO `words` VALUES (10607, 'Olive dashed into the room, grabbed her bag, and ran out again.', 'v. 猛撞， 猛砸， 击碎； 使受挫， 挫败； 使羞愧， 使窘迫', '/dæʃ/', 'dash', 6);
INSERT INTO `words` VALUES (10608, 'a dashing young doctor', 'adj. 活跃的, 浮华的', '/\'dæʃɪŋ/', 'dashing', 6);
