INSERT INTO `words` VALUES (10610, 'soldiers’ faces daubed with black mud', 'v. 涂抹', '/dɔ:b | dɔːb | dɔb/', 'daub', 6);
INSERT INTO `words` VALUES (10611, 'John is a daubster who is known by their whole village.', 'n. 笨画匠', '/\'dɔ:bstə/', 'daubster', 6);
