INSERT INTO `words` VALUES (10613, 'dauntless optimism', 'adj. 不屈不挠的, 大胆的', '/\'dɔ:ntlis | \'dɔːntlɪs | \'dɔntləs/', 'dauntless', 6);
INSERT INTO `words` VALUES (10614, NULL, 'v. 游手好闲, 混日子', '/\'dɔ:dl | \'dɔːd(ə)l/', 'dawdle', 6);
INSERT INTO `words` VALUES (10615, 'She wandered round in a daze, not quite sure what to do.', 'v. 使茫然， 使眩晕; n. 迷乱，恍惚', '/deɪz | dez/', 'daze', 6);
INSERT INTO `words` VALUES (10616, 'He needs morphine to deaden the pain in his chest.', 'v. 减弱， 缓和', '/\'dedn | \'dɛdn/', 'deaden', 6);
INSERT INTO `words` VALUES (10617, 'The talks have reached a complete deadlock .', 'n. 死锁, 僵局', '/\'dedlɔk | \'dedlɒk | \'dɛdlɑk/', 'deadlock', 6);
INSERT INTO `words` VALUES (10618, NULL, 'v. 使除去空气, 从(液体)中除去气泡', '/di:\'εəreit/', 'deaerate', 6);
INSERT INTO `words` VALUES (10619, 'EXCEPT as Pearl, in the dearth of human playmates, was thrown more upon the visionary throng which she created.', 'n. 缺乏， 短缺', '/dɜːrθ | də:θ/', 'dearth', 6);
INSERT INTO `words` VALUES (10620, 'the debacle of the 1994 elections', 'n. 崩溃, 溃裂', '/dei\'bɑ:kl | dɪˈbɑːkəl | dɪˈbɑkəl/', 'debacle', 6);
INSERT INTO `words` VALUES (10621, '...the decision to debar particular immigrants.', 'v. 阻止', '/dɪ\'bɑːr | dɪ\'bɑr/', 'debar', 6);
INSERT INTO `words` VALUES (10622, NULL, 'v. 下船， 下飞机， 下车； 卸载', '/dɪ\'bɑːrk | dɪ\'bɑrk/', 'debark', 6);
INSERT INTO `words` VALUES (10623, 'The medical profession has been debased by these revelations.', 'v. 贬低, 降低', '/di\'beis | dɪ\'beɪs | dɪ\'bes/', 'debase', 6);
INSERT INTO `words` VALUES (10624, 'a debatable point', 'adj. 未决定的， 有争执的', '/dɪ\'beɪtəbl | dɪ\'betəbəl/', 'debatable', 6);
INSERT INTO `words` VALUES (10625, 'The issue will be debated on Tuesday.', 'v. 讨论， 辩论; n. 正式的辩论，讨论', '/dɪ\'beɪt | dɪ\'bet/', 'debate', 6);
INSERT INTO `words` VALUES (10626, NULL, 'v. 使堕落', '/di\'bɔ:tʃ | dɪ\'bɔːtʃ/', 'debauch', 6);
INSERT INTO `words` VALUES (10627, 'a life of debauchery', 'n. 放荡, 游荡', '/di\'bɔ:tʃəri | dɪ\'bɔːtʃ(ə)rɪ | dɪ\'bɔtʃəri/', 'debauchery', 6);
INSERT INTO `words` VALUES (10628, 'He was debilitated by his illness.', 'v. 使衰弱, 使虚弱', '/di\'biliteit | dɪ\'bɪlɪteɪt | dɪ\'bɪlɪtet/', 'debilitate', 6);
INSERT INTO `words` VALUES (10629, 'physical and mental debility', 'n. 衰弱, 无活力', '/di\'biləti | dɪ\'bɪlɪtɪ | dɪ\'bɪləti/', 'debility', 6);
INSERT INTO `words` VALUES (10630, 'Her father walked down the path, debonair in a three-piece suit, hat, and cane.', 'adj. 殷勤的, 高兴的, 快活的, 温文尔雅的', '/,debə\'nεə | ,debə\'neə | ,dɛbə\'nɛr/', 'debonair', 6);
INSERT INTO `words` VALUES (10631, NULL, 'v. 溢出, 流出', '/di\'bautʃ | dɪ\'baʊtʃ; -\'buːʃ | dɪ\'bʊʃ/', 'debouch', 6);
INSERT INTO `words` VALUES (10632, 'As you listen, consider the following questions. Then we’ll examine the answers in the debrief.', 'v. 听取报告, 听取汇报', '/di:\'bri:f | diː\'briːf | di\'brif/', 'debrief', 6);
INSERT INTO `words` VALUES (10633, 'She was hit by flying debris from the blast.', 'n. 碎片, 残骸', '/\'deibri: | \'debriː; \'deɪbriː | də\'bri/', 'debris', 6);
INSERT INTO `words` VALUES (10634, 'Historian Michael Beschloss debunks a few myths.', 'v. 揭穿, 拆穿假面具, 暴露', '/di:\'bʌŋk | diː\'bʌŋk | \'di\'bʌŋk/', 'debunk', 6);
INSERT INTO `words` VALUES (10635, NULL, 'n. 初次参加社交活动的', '/\'debjutɔŋt | \'debjʊtɑːnt; \'deɪ- | \'dɛbjutɑnt/', 'debutante', 6);
INSERT INTO `words` VALUES (10636, 'America is the only country that went from barbarism to decadence without civilization in between.', 'n. 颓废', '/\'dekədəns, di\'kei-,-dənsi | \'dekəd(ə)ns | \'dɛkədəns/', 'decadence', 6);
INSERT INTO `words` VALUES (10637, 'Pop music was condemned as decadent and crude.', 'adj. 颓废的', '/\'dekədənt, di\'kei- | \'dekəd(ə)nt | \'dɛkədənt/', 'decadent', 6);
INSERT INTO `words` VALUES (10638, 'The company is decamping to Asia with 1,700 jobs.', 'v. 秘密而匆忙地移居, 撤营, 逃走, 逃亡', '/di\'kæmp | dɪ\'kæmp/', 'decamp', 6);
INSERT INTO `words` VALUES (10639, 'Vintage ports must be decanted to remove natural sediments.', 'v. 轻轻倒出', '/dɪ\'kænt/', 'decant', 6);
INSERT INTO `words` VALUES (10640, 'an atmosphere of hypocrisy and deceit', 'n. 欺骗, 谎言', '/di\'si:t | dɪ\'siːt | dɪ\'sit/', 'deceit', 6);
INSERT INTO `words` VALUES (10641, '...the sensation of the train decelerating.', 'v. (使)减速', '/,di:\'seləreit | diː\'seləreɪt | ,di\'sɛləret/', 'decelerate', 6);
INSERT INTO `words` VALUES (10642, 'His sense of decency forced him to resign.', 'n. 正派， 端庄体面', '/\'diːsnsi | \'disnsi/', 'decency', 6);
INSERT INTO `words` VALUES (10643, 'Many firms are decentralizing their operations.', 'v. 分散， 权力下放 from central government to regional government)', '/ˌdiː\'sentrəlaɪz | di\'sɛntrə\'laɪz/', 'decentralize', 6);
INSERT INTO `words` VALUES (10644, 'She didn’t have the courage to admit to her deception.', 'n. 欺骗， 诡计', '/dɪ\'sepʃn | dɪ\'sɛpʃən/', 'deception', 6);
INSERT INTO `words` VALUES (10645, 'misleading and deceptive adverts', 'adj. 欺骗的， 导致误解的', '/dɪ\'septɪv | dɪ\'sɛptɪv/', 'deceptive', 6);
INSERT INTO `words` VALUES (10646, 'noise levels exceeding 85 decibels', 'n. 分贝', '/\'desibel | \'desɪbel | \'dɛsɪbɛl/', 'decibel', 6);
INSERT INTO `words` VALUES (10647, 'Deciduous antlers; deciduous leaves; deciduous teeth .', 'adj. 每年落叶的, 非永久性的', '/di\'sidjuəs | dɪ\'sɪdjʊəs | dɪ\'sɪdʒuəs/', 'deciduous', 6);
INSERT INTO `words` VALUES (10648, 'The population has been decimated by disease.', 'v. 每十人杀一人, 大批杀害', '/\'desimeit | \'desɪmeɪt | \'dɛsə,met/', 'decimate', 6);
INSERT INTO `words` VALUES (10649, 'She studied the envelope, trying to decipher the handwriting.', 'v. 译解(密码等), 解释', '/di\'saifə | dɪ\'saɪfə | dɪ\'saɪfɚ/', 'decipher', 6);
INSERT INTO `words` VALUES (10650, 'a decisive leader', 'adj. 决定性的； 坚定的， 果断的', '/dɪ\'saɪsɪv/', 'decisive', 6);
INSERT INTO `words` VALUES (10651, 'His supporters admire his decisiveness.', 'n. 坚决， 果断', '/dɪ\'saɪsɪvnəs/', 'decisiveness', 6);
INSERT INTO `words` VALUES (10652, NULL, 'v. 巧辩, 演讲, 高声朗读', '/di\'kleim | dɪ\'kleɪm | dɪ\'klem/', 'declaim', 6);
INSERT INTO `words` VALUES (10653, NULL, 'n. 雄辨', '/,deklə\'meiʃən | deklə\'meɪʃ(ə)n | \'dɛklə\'meʃən/', 'declamation', 6);
INSERT INTO `words` VALUES (10654, 'These reports were only declassified last year.', 'v. 不再当机密文件处理, 从机密表删除', '/di:\'klæsifai | diː\'klæsɪfaɪ | ,di\'klæsɪfaɪ/', 'declassify', 6);
INSERT INTO `words` VALUES (10655, 'The algorithm of dichotomy was applied to find the optimum declination value when the construction of inner and outer envelopment was designed.', 'n. 偏差', '/,deklɪ\'neɪʃ(ə)n | ,dɛklə\'neʃən/', 'declination', 6);
INSERT INTO `words` VALUES (10656, 'Offered the position of chairman, Smith declined, preferring to keep his current job.', 'v. 拒绝；变弱，变小; n. 消减', '/dɪ\'klaɪn/', 'decline', 6);
INSERT INTO `words` VALUES (10657, 'The south declivity of Yimeng Uplift and the slope places around Central Uplift are the important areas for surveying gas reservoirs in regional stratigraphic traps.', 'n. 倾斜, 下坡', '/di\'klivəti | dɪ\'klɪvɪtɪ | dɪ\'klɪvəti/', 'declivity', 6);
INSERT INTO `words` VALUES (10658, 'The software decodes the information embedded in the satellite broadcasts.', 'v. 解码, 译解', NULL, 'decode', 6);
