INSERT INTO `words` VALUES (10660, 'a partially decomposed body', 'v. 分解, (使)腐烂', '/diːkəm\'pəʊz | ,dikəm\'poz/', 'decompose', 6);
INSERT INTO `words` VALUES (10661, 'So no one decomposition is sufficient.', 'n. 分解, 腐烂', '/,di:kɔmpə\'ziʃən | ,diːkɒmpə\'zɪʃn | ,dikɑmpə\'zɪʃən/', 'decomposition', 6);
INSERT INTO `words` VALUES (10662, 'It\'s a very mannered, decorous language.', 'adj. 有礼貌的', '/\'dekərəs | \'dek(ə)rəs | \'dɛkərəs/', 'decorous', 6);
INSERT INTO `words` VALUES (10663, 'The person that decorticate says: 4 city gate, can attack only, attack which?', 'v. 剥皮', '/di:\'kɔ:tikeit | diː\'kɔːtɪkeɪt | di\'kɔrtə,ket/', 'decorticate', 6);
INSERT INTO `words` VALUES (10664, 'He was disciplined for breaching the Senate’s rules of decorum.', 'n. 礼貌', '/di\'kɔ:rəm | dɪ\'kɔːrəm | dɪ\'kɔrəm/', 'decorum', 6);
INSERT INTO `words` VALUES (10665, 'Officer Langley acted as a decoy to catch the rapist.', 'n. 猎鸟时以引诱别的鸟(特别是野鸭)集于一地的真鸟或假鸟, 圈套, 诱骗', '/\'di:kɔi, di\'kɔi | \'diːkɒɪ; dɪ\'kɒɪ | \'dikɔɪ/', 'decoy', 6);
INSERT INTO `words` VALUES (10666, 'The Emperor issued the decree repealing martial law.', 'n. 法令, 政令, 教令, 天命, 判决', '/di\'kri: | dɪ\'kriː | dɪ\'kri/', 'decree', 6);
INSERT INTO `words` VALUES (10667, 'The buildings were in a decrepit state.', 'adj. 衰老的', '/di\'krepit | dɪ\'krepɪt | dɪ\'krɛpɪt/', 'decrepit', 6);
INSERT INTO `words` VALUES (10668, NULL, 'n. 衰老, 老朽, 老耄', '/di\'krepitju:d | dɪ\'krepɪtʃuːd; dɪ\'krepɪtjuːd | dɪ\'krɛpɪtud/', 'decrepitude', 6);
INSERT INTO `words` VALUES (10669, 'It may be tempting for some to decry incentives as nothing but a poisonous fruit of Con-Lib responsibility thinking.', 'v. 谴责', '/di\'krai | dɪ\'kraɪ/', 'decry', 6);
