INSERT INTO `words` VALUES (10671, 'To reach a high level of skill requires talent, dedication, and a lot of hard work.', 'n. 奉献， 献身', '/ˌdedɪ\'keɪʃn | ,dɛdɪ\'keʃən/', 'dedication', 6);
INSERT INTO `words` VALUES (10672, 'Alison cleverly deduced that I was the author of the letter.', 'v. 演绎， 推断', '/dɪ\'duːs | dɪ\'dʊs/', 'deduce', 6);
INSERT INTO `words` VALUES (10673, 'The company deducted this payment from his compensation.', 'v. 减去， 扣除； 演绎', '/dɪ\'dʌkt/', 'deduct', 6);
INSERT INTO `words` VALUES (10674, 'deductive reasoning', 'adj. 推论的， 演绎的', '/dɪ\'dʌktɪv/', 'deductive', 6);
INSERT INTO `words` VALUES (10675, 'After the morning’s good deeds he deserved a rest.', 'n. 行为, 事实, 功绩, 实行, 契约', '/diːd | did/', 'deed', 6);
INSERT INTO `words` VALUES (10676, 'French and German were deemed essential.', 'v. 认为, 相信', '/di:m | diːm | dim/', 'deem', 6);
INSERT INTO `words` VALUES (10677, 'Most of the monuments had been broken or defaced.', 'v. 损坏', '/dɪ\'feɪs | dɪ\'fes/', 'deface', 6);
