INSERT INTO `words` VALUES (10679, 'He sued the newspaper for defamation of character .', 'n. 诽谤， 中伤', '/ˌdefə\'meɪʃn | ,dɛfə\'meʃən/', 'defamation', 6);
INSERT INTO `words` VALUES (10680, 'The article was highly defamatory.', 'adj. 破坏名誉的, 诽谤的', '/di\'fæmətəri | dɪ\'fæmət(ə)rɪ | dɪ\'fæmətɔri/', 'defamatory', 6);
INSERT INTO `words` VALUES (10681, 'Sgt. Norwood complained that the article defamed him.', 'v. 诽谤', '/di\'feim | dɪ\'feɪm/', 'defame', 6);
INSERT INTO `words` VALUES (10682, 'The corporation may be charged with default on its contract with the government.', 'n. 默认(值), 缺省(值), 食言, 不履行责任, [律]缺席', '/di\'fɔ:lt | dɪ\'fɔːlt; \'diːfɔːlt | dɪ\'fɔlt/', 'default', 6);
