INSERT INTO `words` VALUES (10684, 'Fills me with the urge to defecate!', 'v. 澄清', '/\'defikeit | \'defɪkeɪt; \'diːf- | \'dɛfəket/', 'defecate', 6);
INSERT INTO `words` VALUES (10685, 'All the cars are tested for defects before they leave the factory.', 'n. 过失, 缺点', '/\'di:fekt, di\'f-, di\'fekt | \'diːfekt; dɪ\'fekt | ‘dɪfɛkt/', 'defect', 6);
INSERT INTO `words` VALUES (10686, NULL, 'n. 缺点, 背信, 背叛, 变节', '/di\'fekʃən | dɪ\'fekʃn | dɪ\'fɛkʃən/', 'defection', 6);
INSERT INTO `words` VALUES (10687, 'We find the defendant not guilty.', 'n. 被告', '/di\'fendənt | dɪ\'fend(ə)nt | dɪ\'fɛndənt/', 'defendant', 6);
INSERT INTO `words` VALUES (10688, NULL, 'n. 防御， 防护', '/dɪ\'fens | dɪ\'fɛns/', 'defense', 6);
INSERT INTO `words` VALUES (10689, 'She despised herself for sounding so defensive.', 'adj. 自卫的; n. 戒备； 防御', '/dɪ\'fensɪv | dɪ\'fɛnsɪv/', 'defensive', 6);
INSERT INTO `words` VALUES (10690, 'The committee deferred their decision .', 'v. 遵从， 听从； 延期', '/dɪ\'fɜːr | dɪ\'fɝ/', 'defer', 6);
INSERT INTO `words` VALUES (10691, '...the older political tradition of deference to great leaders.', 'n. 顺从, 尊重', '/\'def(ə)r(ə)ns | \'dɛfərəns/', 'deference', 6);
INSERT INTO `words` VALUES (10692, 'They like five-star hotels and deferential treatment.', 'adj. 顺从的， 恭顺的', '/ˌdefə\'renʃl | ˌdefə\'rɛnʃl/', 'deferential', 6);
INSERT INTO `words` VALUES (10693, '...his courageous defiance of the government.', 'n. 挑战； 违抗， 反抗', '/dɪ\'faɪəns/', 'defiance', 6);
INSERT INTO `words` VALUES (10694, 'Mark smashed a fist on the desk in a defiant gesture.', 'adj. 反抗的， 挑衅的', '/dɪ\'faɪənt/', 'defiant', 6);
INSERT INTO `words` VALUES (10695, 'They did blood tests on him for signs of vitamin deficiency.', 'n. 缺乏, 不足', '/di\'fiʃənsi | dɪ\'fɪʃ(ə)nsɪ | dɪ\'fɪʃənsi/', 'deficiency', 6);
INSERT INTO `words` VALUES (10696, 'Women who are dieting can become iron deficient.', 'adj. 有缺点的； 缺少的； 不足的', '/dɪ\'fɪʃnt/', 'deficient', 6);
INSERT INTO `words` VALUES (10697, 'the country’s widening budget deficit', 'n. 赤字, 不足额', '/\'defisit | \'defɪsɪt; \'diː- | \'dɛfəsɪt/', 'deficit', 6);
INSERT INTO `words` VALUES (10698, 'The measurement and plotting of defilade angle is a very important training subject even if using real radar set.', 'vt. 遮蔽', '/,defi\'leid | ,defɪ\'leɪd | ,dɛfə\'led/', 'defilade', 6);
INSERT INTO `words` VALUES (10699, 'Hallam’s tomb had been defiled and looted.', 'v. 染污', '/di\'fail | dɪ\'faɪl/', 'defile', 6);
INSERT INTO `words` VALUES (10700, 'It’s impossible for me to give you a definite answer.', 'adj. 清楚的， 明确的', '/\'defɪnət | \'dɛfɪnət/', 'definite', 6);
INSERT INTO `words` VALUES (10701, 'a dictionary definition', 'n. 定义, 解说, 精确度, (轮廓影像等的)清晰度', '/,defi\'niʃən | defɪ\'nɪʃ(ə)n | ,dɛfɪ\'nɪʃən/', 'definition', 6);
INSERT INTO `words` VALUES (10702, 'a definitive agreement to buy the company', 'adj. 明确的， 有权威的； 最终的', '/dɪ\'fɪnətɪv/', 'definitive', 6);
INSERT INTO `words` VALUES (10703, 'He deflected the blow with his forearm.', 'v. (使)偏斜, (使)偏转', '/di\'flekt | dɪ\'flekt | dɪ\'flɛkt/', 'deflect', 6);
INSERT INTO `words` VALUES (10704, '...the deflection of light as it passes through the slits in the grating.', 'n. 偏斜, 偏转, 偏差', '/di\'flekʃən | dɪ\'flekʃ(ə)n | dɪ\'flɛkʃən/', 'deflection', 6);
INSERT INTO `words` VALUES (10705, 'He faces charges of theft and conspiracy to defraud (= a secret plan to cheat someone, made by two or more people ) .', 'v. 欺骗， 诈骗', '/dɪ\'frɔːd | dɪ\'frɔd/', 'defraud', 6);
INSERT INTO `words` VALUES (10706, 'The proceeds from the competition help to defray the expenses of the evening.', 'v. 支付, 支出', '/di\'frei | dɪ\'freɪ | dɪ\'fre/', 'defray', 6);
INSERT INTO `words` VALUES (10707, 'She has a microwave, but uses it mainly for defrosting bread.', 'v. 解冻； 将…除霜', '/ˌdiː\'frɔːst | ,di\'frɔst/', 'defrost', 6);
INSERT INTO `words` VALUES (10708, 'He sketched her with quick, deft strokes.', 'adj. 敏捷熟练的, 灵巧的', '/deft/', 'deft', 6);
INSERT INTO `words` VALUES (10709, 'Up a tower to a defunct revolving restaurant, where I snapped photos of the hazy skyline.', 'adj. 死了的', '/di\'fʌŋkt | dɪ\'fʌŋ(k)t | dɪ\'fʌŋkt/', 'defunct', 6);
INSERT INTO `words` VALUES (10710, 'Police have defused a bomb found in a downtown building.', 'v. 拆除引信， 使除去危险性；平息', '/ˌdiː\'fjuːz | ,di\'fjuz/', 'defuse', 6);
INSERT INTO `words` VALUES (10711, 'people who openly defy the law', 'v. 违抗， 藐视', '/dɪ\'faɪ | \'difaɪ/', 'defy', 6);
INSERT INTO `words` VALUES (10712, 'The painting was condemned as ‘degenerate’.', 'adj. 退化的', '/di\'dʒenəreit, di\'dʒenərət | dɪ\'dʒen(ə)rət | dɪ\'dʒɛnəret/', 'degenerate', 6);
INSERT INTO `words` VALUES (10713, 'The dolphin’s habitat is being rapidly degraded.', 'v. (使)降级, (使)堕落, (使)退化', '/\'di\'ɡreid | dɪ\'greɪd | dɪ\'ɡred/', 'degrade', 6);
INSERT INTO `words` VALUES (10714, 'War dehumanizes people.', 'v. 使失掉人性, 使成兽性', '/,di:\'hju:mənaiz | diː\'hjuːmənaɪz | ,di\'hjumənaɪz/', 'dehumanize', 6);
INSERT INTO `words` VALUES (10715, 'The substance is dehydrated and stored as powder.', 'v. (使)脱水', '/,di:\'haidreit | diːhaɪ\'dreɪt; diː\'haɪdreɪt | di\'haɪdret/', 'dehydrate', 6);
INSERT INTO `words` VALUES (10716, NULL, 'v. 防止结冰, 装以除冰装置, 除冰', '/,di:\'ais/', 'deice', 6);
INSERT INTO `words` VALUES (10717, '...the deification of science in the 1940s.', 'n. 祀为神, 神格化, 奉若神明', '/,di:ifi\'keiʃən | ,diːɪfɪ\'keɪʃən/', 'deification', 6);
INSERT INTO `words` VALUES (10718, 'Valentino was virtually deified by legions of female fans.', 'v. 神化', '/\'di:ifai | \'deɪɪfaɪ; \'diːɪ- | \'deɪfaɪ/', 'deify', 6);
INSERT INTO `words` VALUES (10719, 'Travis called after her, but she didn’t deign to answer.', 'v. 屈尊', '/dein | deɪn | den/', 'deign', 6);
INSERT INTO `words` VALUES (10720, 'the deities of ancient Greece', 'n. 神, 神性', '/\'di:iti | \'deɪɪtɪ; \'diːɪ- | \'deəti/', 'deity', 6);
INSERT INTO `words` VALUES (10721, 'The unemployed stood at street corners, dejected.', 'adj. 沮丧的, 灰心的', '/di\'dʒektid | dɪ\'dʒektɪd | dɪ\'dʒɛktɪd/', 'dejected', 6);
INSERT INTO `words` VALUES (10722, 'Over the past four years, I have seen his face evolve into picture of dejection.', 'n. 沮丧, 粪便', '/di\'dʒekʃən | dɪ\'dʒekʃ(ə)n | dɪ\'dʒɛkʃən/', 'dejection', 6);
INSERT INTO `words` VALUES (10723, '...delectable wine.', 'adj. 使人愉快的', '/di\'lektəbl | dɪ\'lektəb(ə)l | dɪ\'lɛktəbl/', 'delectable', 6);
INSERT INTO `words` VALUES (10724, 'Wish we cooperate the delectation!', 'n. 愉快, 款待', '/,di:lek\'teiʃən | ,diːlek\'teɪʃ(ə)n | ,dilɛk\'teʃən/', 'delectation', 6);
INSERT INTO `words` VALUES (10725, 'Around 350 delegates attended the conference.', 'n. 代表', '/\'deliɡət, -ɡeit, \'deliɡeit | ˈdɛlɪˌɡeɪt; -ɡɪt; (for v.,) ˈdɛlɪˌɡeɪt | ˈdɛləgɪt; (for v.,) ˈdɛləˌgeɪt/', 'delegate', 6);
INSERT INTO `words` VALUES (10726, 'His name was deleted from the list.', 'v. 删除', '/di\'li:t | dɪ\'liːt | dɪ\'lit/', 'delete', 6);
INSERT INTO `words` VALUES (10727, 'the deleterious effects of smoking', 'adj. 有害的, 有毒的', '/,deli\'tiəriəs | ,delɪ\'tɪərɪəs | \'dɛlə\'tɪrɪəs/', 'deleterious', 6);
INSERT INTO `words` VALUES (10728, 'a deliberate attempt to humiliate her', 'adj. 深思熟虑的, 故意的, 预有准备的', '/di\'libərət | dɪ\'lɪb(ə)rət | dɪ\'lɪbərət/', 'deliberate', 6);
INSERT INTO `words` VALUES (10729, 'After much deliberation, first prize was awarded to Derek Murray.', 'n. 细想， 考虑', '/dɪˌlɪbə\'reɪʃn | dɪ,lɪbə\'reʃən/', 'deliberation', 6);
INSERT INTO `words` VALUES (10730, 'a delicate child', 'adj. 娇弱的； 雅致的， 精美的', '/\'delɪkət | ˈdɛlɪkɪt/', 'delicate', 6);
INSERT INTO `words` VALUES (10731, 'Her fabulous recipes will delight anyone who loves chocolate.', 'v. 使高兴， 使欣喜; n. 快乐， 高兴， 乐事', '/dɪ\'laɪt/', 'delight', 6);
INSERT INTO `words` VALUES (10732, 'This is not meant to delimit what approaches social researchers can adopt.', 'v. 定界限, 划界', '/di\'limit | dɪ\'lɪmɪt/', 'delimit', 6);
INSERT INTO `words` VALUES (10733, 'The document delineates your rights and your obligations.', 'v. 描绘', '/di\'linieit | dɪ\'lɪnɪeɪt | dɪ\'lɪnɪet/', 'delineate', 6);
INSERT INTO `words` VALUES (10734, 'the ever-rising statistics of delinquency and crime', 'n. 行为不良, 错失', '/di\'liŋkwənsi | dɪ\'lɪŋkw(ə)nsɪ | dɪ\'lɪŋkwənsi/', 'delinquency', 6);
INSERT INTO `words` VALUES (10735, 'Deanes writes and lectures about teenage delinquents.', 'n. 失职者, 违法者', '/di\'liŋkwənt | dɪ\'lɪŋkw(ə)nt | dɪ\'lɪŋkwənt/', 'delinquent', 6);
INSERT INTO `words` VALUES (10736, 'I was delirious and blacked out several times.', 'adj. 神志昏迷的, 不省人事的, 发狂的', '/di\'liriəs | dɪ\'lɪrɪəs/', 'delirious', 6);
INSERT INTO `words` VALUES (10737, 'Before she died she had fits of delirium.', 'n. (暂时的)精神狂乱, 精神错乱, 说谵语状态, 狂语, 精神极度兴奋', '/di\'liriəm | dɪ\'lɪrɪəm/', 'delirium', 6);
INSERT INTO `words` VALUES (10738, 'The result showed: The capsule can obviously decrease the vomiting times and delay the vomiting delitescence (P<0.05, P<0.01 ) .', 'n. 潜伏期', '/,deli\'tesəns,-ənst/', 'delitescence', 6);
INSERT INTO `words` VALUES (10739, 'the Nile delta', 'n. 三角州, 德耳塔(希腊字母的第四个字)', '/\'deltə | \'dɛltə/', 'delta', 6);
INSERT INTO `words` VALUES (10740, 'Neither side should delude itself that it can avoid the harm caused by an increased mutual antagonism; both should understand that a crisis in one country can hurt the other.', 'v. 迷惑, 蛊惑', '/dɪ\'l(j)uːd/', 'delude', 6);
INSERT INTO `words` VALUES (10741, 'Even so, the data deluge is already starting to transform business, government, science and everyday life (see our special report in this issue).', 'n. 洪水, 豪雨', '/\'delju:dʒ | \'deljuːdʒ | \'dɛljʊdʒ/', 'deluge', 6);
INSERT INTO `words` VALUES (10742, 'I was under the delusion that he intended to marry me.', 'n. 错觉', '/di\'lu:ʒən | dɪ\'l(j)uːʒ(ə)n | dɪ\'luʒn/', 'delusion', 6);
INSERT INTO `words` VALUES (10743, 'a deluxe hotel', 'adj. 豪华的， 华丽的', '/ˌdə\'lʌks | dɪˈlʌks;/', 'deluxe', 6);
INSERT INTO `words` VALUES (10744, 'He had a considerable Elizabethan library to delve in.', 'v. 钻研', '/delv | dɛlv/', 'delve', 6);
INSERT INTO `words` VALUES (10745, 'When you rent or buy a DVD, the checkout clerk rubs it across a pad to demagnetize the metallic glass so it won\'t trigger an alarm when you leave.', 'v. 消磁， 使退磁', '/diː\'mægnətaɪz | ,di\'mægnət,aɪz/', 'demagnetize', 6);
INSERT INTO `words` VALUES (10746, NULL, 'n. 蛊惑民心的政客', '/\'deməgɑːg | ˈdɛməɡɑɡ/', 'demagogue', 6);
INSERT INTO `words` VALUES (10747, 'A special UN commission was formed to demarcate the border.', 'v. 划分界线', '/\'di:mɑ:keit | \'diːmɑːkeɪt | \'dimɑr\'ket/', 'demarcate', 6);
INSERT INTO `words` VALUES (10748, 'language that demeans women', 'v. 举止, 贬低身份', '/di\'mi:n | dɪ\'miːn/', 'demean', 6);
INSERT INTO `words` VALUES (10749, 'his quiet, reserved demeanour', 'n. 举止， 行为', '/dɪ\'miːnər | di\'mi:nə/', 'demeanour', 6);
INSERT INTO `words` VALUES (10750, 'She was almost demented with grief.', 'adj. 疯狂的', '/dɪ\'mentɪd | dɪ\'mɛntɪd/', 'demented', 6);
INSERT INTO `words` VALUES (10751, NULL, 'n. 土地之所有, 领地, 私有地', '/di\'mein | dɪ\'meɪn; dɪ\'miːn | də\'men/', 'demesne', 6);
INSERT INTO `words` VALUES (10752, 'programmes to help demobilized soldiers fit into civilian life', 'v. 复员', '/di:\'məubilaiz | di\'mobəlaɪz/', 'demobilize', 6);
INSERT INTO `words` VALUES (10753, 'This slow-motion disaster, demography insists, cannot be avoided without a major shift in resources.', 'n. 人口统计学', '/di:\'mɔɡrəfi | dɪ\'mɒgrəfɪ | dɪ\'mɑɡrəfi/', 'demography', 6);
INSERT INTO `words` VALUES (10754, 'He demolished my argument in minutes.', 'v. 毁坏, 破坏, 推翻, 粉碎', '/di\'mɔliʃ | dɪ\'mɒlɪʃ | dɪ\'mɑlɪʃ/', 'demolish', 6);
INSERT INTO `words` VALUES (10755, 'The project required the total demolition of the old bridge.', 'n. 破坏, 毁坏, 毁坏之遗迹', '/,demə\'liʃən | demə\'lɪʃn | ,dɛmə\'lɪʃən; ,dimə\'lɪʃən/', 'demolition', 6);
INSERT INTO `words` VALUES (10756, 'The study demonstrates the link between poverty and malnutrition.', 'v. 证明， 论证； 示威', '/\'demənstreɪt | \'dɛmən\'stret/', 'demonstrate', 6);
INSERT INTO `words` VALUES (10757, 'My mother wasn’t demonstrative; she never hugged me.', 'adj. 证明的， 论证的； 感情流露的', '/dɪ\'mɑːnstrətɪv | dɪ\'mɑnstrətɪv/', 'demonstrative', 6);
INSERT INTO `words` VALUES (10758, 'The illness demoralized him and recovery took several weeks.', 'v. 使士气低落', '/dɪ\'mɔːrəlaɪz | dɪ\'mɔrəlaɪz/', 'demoralize', 6);
INSERT INTO `words` VALUES (10759, 'The sergeant was demoted to private.', 'v. 使降级, 使降职', '/,di:\'məut | diː\'məʊt | ,di\'mot/', 'demote', 6);
INSERT INTO `words` VALUES (10760, '...television\'s demotic style of language.', 'adj. 民众的， 通俗的', '/dɪ\'mɑːtɪk | dɪ\'mɑtɪk/', 'demotic', 6);
INSERT INTO `words` VALUES (10761, 'What thing is the demulcent stick that uses after the operation? Why to use with respect to indolence? What principle?', 'adj. 缓和的, 镇痛的', '/di\'mʌlsənt | dɪ\'mʌls(ə)nt | dɪ\'mʌlsnt/', 'demulcent', 6);
INSERT INTO `words` VALUES (10762, 'They demurred politely, but finally agreed to stay.', 'v. 提出异议, 反对, 抗辩, 犹豫', '/di\'mə: | dɪ\'mɜː | dɪ\'mɝ/', 'demur', 6);
INSERT INTO `words` VALUES (10763, 'Old photos of Maggie show her young and demure.', 'adj. 端庄的', '/di\'mjuə | dɪ\'mjʊə; dɪ\'mjɔː | dɪ\'mjʊr/', 'demure', 6);
INSERT INTO `words` VALUES (10764, NULL, 'v. 减少…的神秘性', '/ˌdiː\'mɪstɪfaɪ | ,di\'mɪstɪfaɪ/', 'demystify', 6);
INSERT INTO `words` VALUES (10765, 'corrupt gambling dens', 'n. 兽穴， 窝', '/den | dɛn/', 'den', 6);
INSERT INTO `words` VALUES (10766, 'Plant taxonomy and plant systematics may more emphasize on the evolution of plants and their relationships. Its coverage is much broader than dendrology .', 'n. 树木学', '/den\'drɒlədʒɪ | dɛn\'drɑlədʒi/', 'dendrology', 6);
INSERT INTO `words` VALUES (10767, 'people who denigrate their own country', 'v. 毁誉', '/\'deniɡreit | \'denɪgreɪt | \'dɛnɪɡret/', 'denigrate', 6);
INSERT INTO `words` VALUES (10768, NULL, 'n. 居民', '/\'denizən | \'denɪz(ə)n/', 'denizen', 6);
INSERT INTO `words` VALUES (10769, NULL, 'v. 命名', '/di\'nɔmineit, di\'nɔminit | dɪ\'nɒmɪneɪt | dɪ\'nɑmɪnet/', 'denominate', 6);
INSERT INTO `words` VALUES (10770, 'There are 24 books in the Hebrew Bible, or Tanakh—and depending upon the denomination, between 66 and 84 more books in Christian Bibles, divided between the Old and New Testaments.', 'n. 命名', '/di,nɔmi\'neiʃən | dɪ,nɒmɪ\'neɪʃ(ə)n | dɪ,nɑmɪ\'neʃən/', 'denomination', 6);
INSERT INTO `words` VALUES (10771, 'What does the word ‘curriculum’ denote that ‘course’ does not?', 'v. 指示， 表示', '/dɪ\'nout | dɪ\'not/', 'denote', 6);
INSERT INTO `words` VALUES (10772, 'The plot takes us to Paris for the denouement of the story.', 'n. 结局', '/deinu:\'mɔŋ | deɪnuː\'mɒŋ/', 'denouement', 6);
INSERT INTO `words` VALUES (10773, 'The group denounced the failure by the authorities to take action.', 'v. 公开指责, 公然抨击, 谴责', '/di\'nauns | dɪ\'naʊns/', 'denounce', 6);
INSERT INTO `words` VALUES (10774, 'a dense rurally-based population', 'adj. 密集的， 浓密的', '/dens | dɛns/', 'dense', 6);
INSERT INTO `words` VALUES (10775, 'areas of high population density', 'n. 密集， 稠密', '/\'densəti | \'dɛnsəti/', 'density', 6);
INSERT INTO `words` VALUES (10776, 'I was convinced there was a dent in the hood which hadn\'t been there before.', 'n. 凹, 凹痕, (齿轮的)齿, 弱点', '/dent | dɛnt/', 'dent', 6);
INSERT INTO `words` VALUES (10777, 'Good oral hygiene and regular dental care are important, whatever your age.', 'adj. 牙齿的， 牙科的', '/\'dentl | \'dɛntl/', 'dental', 6);
INSERT INTO `words` VALUES (10778, NULL, 'n. 一副假牙, 一副牙齿', '/\'dentʃə | ˈdɛntʃɚ/', 'denture', 6);
INSERT INTO `words` VALUES (10779, 'People who wear dentures may sleep better if they leave them in overnight.', 'n. 假牙', '/\'dentʃərz | \'dɛntʃɚz/', 'dentures', 6);
INSERT INTO `words` VALUES (10780, 'a hillside denuded in a fire', 'v. 使裸露, 剥下, 剥夺, 脱毛', '/di\'nju:d | dɪ\'njuːd | dɪ\'nud/', 'denude', 6);
INSERT INTO `words` VALUES (10781, NULL, 'v. 公开指责， 公然抨击， 谴责', '/dɪˌnʌnsi\'eɪt/', 'denunciate', 6);
INSERT INTO `words` VALUES (10782, 'Maybe he should go without deodorant?', 'n. 除臭剂', '/di:\'əudərənt | dɪ\'əʊd(ə)r(ə)nt | dɪ\'odərənt/', 'deodorant', 6);
INSERT INTO `words` VALUES (10783, 'our most dependable ally', 'adj. 可靠的， 可信赖的', '/dɪ\'pendəbl | dɪ\'pɛndəbl/', 'dependable', 6);
INSERT INTO `words` VALUES (10784, 'a book depicting life in pre-revolutionary Russia', 'v. 描绘； 描写， 描述', '/dɪ\'pɪkt/', 'depict', 6);
INSERT INTO `words` VALUES (10785, '...substances that deplete the ozone layer.', 'v. 耗尽, 使衰竭', '/di\'pli:t | dɪ\'pliːt | dɪ\'plit/', 'deplete', 6);
INSERT INTO `words` VALUES (10786, 'Overfishing not only causes depletion in individual fish stocks, but also disruption to entire ecosystems and food webs in the ocean.', 'n. 损耗', '/di\'pli:ʃən | dɪ\'pliːʃn | dɪ\'pliʃən/', 'depletion', 6);
INSERT INTO `words` VALUES (10787, 'Muslim and Jewish leaders have issued statements deploring the violence and urging the United Nations to take action.', 'v. 悲悼， 哀叹； 谴责', '/dɪ\'plɔːr | dɪ\'plɔr/', 'deplore', 6);
INSERT INTO `words` VALUES (10788, 'The president said he had no intention of deploying ground troops.', 'v. 部署； 拉长， 展开 especially in width', '/dɪ\'plɔɪ/', 'deploy', 6);
INSERT INTO `words` VALUES (10789, 'One peculiarity of the child\'s deportment remains yet to be told.', 'n. 行为, 举止', '/di\'pɔ:tmənt | dɪ\'pɔːtm(ə)nt | dɪ\'pɔrtmənt/', 'deportment', 6);
INSERT INTO `words` VALUES (10790, 'Mr. Ben Bella was deposed in a coup in 1965.', 'v. 免职, 废(王位), 作证', '/di\'pəuz | dɪ\'pəʊz | dɪ\'poz/', 'depose', 6);
INSERT INTO `words` VALUES (10791, 'The female deposits her eggs directly into the water.', 'v. 存放； 使沉积)', '/dɪ\'pɑːzɪt | dɪ\'pɑzɪt/', 'deposit', 6);
INSERT INTO `words` VALUES (10792, 'the deposition of marine sediments', 'n. 沉积作用, 沉积物, 革职, 废王位, 免职', '/,depə\'zɪʃ(ə)n; diː- | ,dɛpə\'zɪʃən/', 'deposition', 6);
INSERT INTO `words` VALUES (10793, '...material likely to deprave or corrupt those who see it.', 'v. 使堕落， 使恶化', '/dɪ\'preɪv | dɪ\'prev/', 'deprave', 6);
INSERT INTO `words` VALUES (10794, 'a killer’s depraved mind', 'adj. 堕落的， 腐化的', '/dɪ\'preɪvd | dɪ\'prevd/', 'depraved', 6);
INSERT INTO `words` VALUES (10795, '...the absolute depravity that can exist in war.', 'n. 堕落', '/di\'prævəti | dɪ\'prævɪtɪ | dɪ\'prævəti/', 'depravity', 6);
INSERT INTO `words` VALUES (10796, 'As a lawyer, I would deprecate any sort of legal control on gene therapy at this stage.', 'v. 反对； 轻视', '/\'deprəkeɪt | \'dɛprəket/', 'deprecate', 6);
INSERT INTO `words` VALUES (10797, 'He merely lifted his eyebrows in placid deprecation of himself and everybody else.', 'n. 反对', '/,depri\'keiʃən | ˌdeprɪ\'keɪʃn/', 'deprecation', 6);
INSERT INTO `words` VALUES (10798, NULL, 'adj. 不赞成的， 反对的', '/\'deprɪkətɔːri | \'dɛprəkə,tori/', 'deprecatory', 6);
INSERT INTO `words` VALUES (10799, 'New cars depreciate in value quickly.', 'v. 折旧, (使)贬值, 降低, 贬低, 轻视', '/di\'pri:ʃieit | dɪ\'priːʃɪeɪt; -sɪ- | dɪ\'priʃɪet/', 'depreciate', 6);
INSERT INTO `words` VALUES (10800, 'Much of the region\'s environmental depredation is a result of poor planning.', 'n. 掠夺, 破坏痕迹', '/,depri\'deiʃən | ,deprɪ\'deɪʃ(ə)n | ,dɛprə\'deʃən/', 'depredation', 6);
INSERT INTO `words` VALUES (10801, 'She felt lonely and depressed .', 'adj. 消沉的； 凹陷的', '/dɪ\'prest | dɪ\'prɛst/', 'depressed', 6);
INSERT INTO `words` VALUES (10802, 'women who suffer from post-natal depression', 'n. 抑郁， 消沉', '/dɪ\'preʃn | dɪ\'prɛʃən/', 'depression', 6);
INSERT INTO `words` VALUES (10803, 'Millions more suffer from serious sleep deprivation caused by long work hours.', 'n. 剥夺', '/deprɪ\'veɪʃ(ə)n | ,dɛprɪ\'veʃən/', 'deprivation', 6);
INSERT INTO `words` VALUES (10804, 'They\'ve been deprived of the fuel necessary to heat their homes.', 'v. 剥夺， 使丧失', '/dɪ\'praɪv/', 'deprive', 6);
INSERT INTO `words` VALUES (10805, 'A subcommittee was deputed to investigate the claims.', 'v. 委托', '/di\'pju:t | dɪ\'pjuːt | dɪ\'pjut/', 'depute', 6);
INSERT INTO `words` VALUES (10806, 'The president said he could deputize the Florida National Guard to help with security.', 'v. 代理， 代表', '/\'depjutaɪz | \'dɛpjutaɪz/', 'deputize', 6);
INSERT INTO `words` VALUES (10807, 'His brother was acting as his deputy in America.', 'n. 代理人, 代表', '/\'depjuti | \'depjʊtɪ | \'dɛpjuti/', 'deputy', 6);
INSERT INTO `words` VALUES (10808, NULL, 'v. 根除， 灭绝', '/ˌdiː\'ræsɪneɪt | ,di\'ræsɪnet/', 'deracinate', 6);
INSERT INTO `words` VALUES (10809, NULL, 'n. 扰乱, 发狂', '/di\'reindʒmənt | dɪ\'rendʒmənt/', 'derangement', 6);
INSERT INTO `words` VALUES (10810, 'Her body was found dumped in a derelict warehouse less than a mile from her home.', 'adj. 被抛弃了的', '/\'derilikt | \'derəlɪkt | \'dɛrəlɪkt/', 'derelict', 6);
INSERT INTO `words` VALUES (10811, 'The previous owners had rescued the building from dereliction.', 'n. 遗弃； 玩忽职守的', '/ˌderə\'lɪkʃn | ,dɛrə\'lɪkʃən/', 'dereliction', 6);
INSERT INTO `words` VALUES (10812, 'You shouldn’t deride their efforts.', 'v. 嘲弄, 嘲笑', '/di\'raid | dɪ\'raɪd/', 'deride', 6);
INSERT INTO `words` VALUES (10813, 'derisive laughter', 'adj. 嘲笑的, 值得嘲笑的', '/di\'raisiv | dɪ\'raɪsɪv; -z- | dɪ\'raɪsɪv/', 'derisive', 6);
INSERT INTO `words` VALUES (10814, 'The derivation of its name is obscure.', 'n. 发展， 起源； 词源', '/ˌderɪ\'veɪʃn | \'dɛrə\'veʃən/', 'derivation', 6);
INSERT INTO `words` VALUES (10815, 'a derivative text', 'adj. 引出的, 系出的', '/dɪ\'rɪvətɪv | də\'rɪvətɪv/', 'derivative', 6);
INSERT INTO `words` VALUES (10816, NULL, 'n. 皮肤医学, 皮肤病学', '/,də:mə\'tɔlədʒi | ,dɜːmə\'tɒlədʒɪ | ,dɝmə\'tɑlədʒi/', 'dermatology', 6);
INSERT INTO `words` VALUES (10817, 'People often derogate others in social comparison and the past selves in temporal comparison so that they can achieve self-enhancement and ultimately get good self-feelings.', 'v. 贬损, 毁损', '/\'derəuɡeit, -git, -geit | \'derəgeɪt | \'dɛrəɡet/', 'derogate', 6);
INSERT INTO `words` VALUES (10818, 'Their conversation contained a number of derogatory racial remarks .', 'adj. 贬损的', '/di\'rɔɡətəri | dɪ\'rɒgət(ə)rɪ | dɪ\'rɑɡətɔri/', 'derogatory', 6);
INSERT INTO `words` VALUES (10819, NULL, 'v. 除去盐分, 淡化海水', '/di:\'sælinaiz | diː\'sælɪnaɪz | di\'selɪ,naɪz/', 'desalinize', 6);
INSERT INTO `words` VALUES (10820, 'Sing a descant on a main tune or melody.', 'v. 详论', '/de\'skænt, \'dis-, di\'skænt, \'des- | \'deskænt | \'dɛskænt/', 'descant', 6);
INSERT INTO `words` VALUES (10821, 'Our plane started to descend.', 'v. 下来, 下降, 遗传(指财产,气质,权利), 突击, 出其不意的拜访', '/di\'send | dɪ\'send | dɪ\'sɛnd/', 'descend', 6);
INSERT INTO `words` VALUES (10822, 'He was a direct descendant of Napoleon Bonaparte.', 'n. 子孙, 后裔, 后代', '/di\'sendənt | dɪ\'send(ə)nt | dɪ\'sɛndənt/', 'descendant', 6);
INSERT INTO `words` VALUES (10823, 'the descriptive passages in the novel', 'adj. 描述的', '/dɪ\'skrɪptɪv/', 'descriptive', 6);
INSERT INTO `words` VALUES (10824, NULL, 'v. 察看, 发现, 远远看到', '/di\'skrai | dɪ\'skraɪ/', 'descry', 6);
INSERT INTO `words` VALUES (10825, 'She shouldn\'t have desecrated the picture of a religious leader.', 'v. 亵渎, 污辱, 把(神物)供俗用', '/\'desikreit | \'desɪkreɪt | \'dɛsɪ\'kret/', 'desecrate', 6);
INSERT INTO `words` VALUES (10826, 'Helen was deserted by her husband.', 'v. 遗弃， 离弃', '/dɪ\'zɜːrt | (for v.) dɪˈzɝ​t; (for n.) \'dɛzɚt/', 'desert', 6);
INSERT INTO `words` VALUES (10827, 'Peters had two deserters followed and shot.', 'n. 背弃者； 逃兵', '/dɪ\'zɜːrtər | dɪ\'zɝtɚ/', 'deserter', 6);
INSERT INTO `words` VALUES (10828, 'amount of desiccant must be used to offset the wooden bracing if placed inside of the barrier', 'n. 干燥剂', '/\'desikənt | \'desɪk(ə)nt | \'dɛsəkənt/', 'desiccant', 6);
INSERT INTO `words` VALUES (10829, NULL, 'v. 使完全变干, 干贮(食物等)', '/\'desikeit | \'desɪkeɪt | \'dɛsɪ,ket/', 'desiccate', 6);
INSERT INTO `words` VALUES (10830, NULL, 'n. 所愿望之物, 迫切需要之物', '/di,zidə\'reitəm | dɪ,zɪdə\'rɑːtəm; -\'reɪtəm; -,sɪd- | dɪ\'zɪdə\'rɑtəm/', 'desideratum', 6);
INSERT INTO `words` VALUES (10831, 'Buildings are designated by red squares on the map.', 'v. 指定，任命；指明，指出; adj. 尚未上任的', '/\'dezɪgneɪt | \'dɛzɪɡnet/', 'designate', 6);
INSERT INTO `words` VALUES (10832, 'Her official designation is Systems Manager.', 'n. 指示, 指定, 选派, 名称', '/,deziɡ\'neiʃən | dezɪg\'neɪʃ(ə)n | ,dɛzɪɡ\'neʃən/', 'designation', 6);
INSERT INTO `words` VALUES (10833, 'The ability to speak a foreign language is highly desirable .', 'adj. 值得要的, 合意的, 令人想要的, 悦人心意的', '/di\'zaiərəbl | dɪ\'zaɪərəb(ə)l | dɪ\'zaɪərəbl/', 'desirable', 6);
INSERT INTO `words` VALUES (10834, 'We hope that the military regime will desist from its acts of violence.', 'v. 终止', '/di\'zist | dɪ\'zɪst; dɪ\'sɪst | dɪ\'zɪst/', 'desist', 6);
INSERT INTO `words` VALUES (10835, 'a desolate landscape', 'adj. 荒凉的, 无人烟的', '/\'desələt, \'desəleit | \'des(ə)lət | \'dɛsələt/', 'desolate', 6);
INSERT INTO `words` VALUES (10836, 'It’s despicable the way he treats those kids.', 'adj. 可鄙的, 卑劣的', '/\'despikəbl | dɪ\'spɪkəb(ə)l; \'despɪk- | dɪ\'spɪkəbl/', 'despicable', 6);
INSERT INTO `words` VALUES (10837, 'She despised her neighbours.', 'v. 鄙视， 蔑视', '/dɪ\'spaɪz/', 'despise', 6);
INSERT INTO `words` VALUES (10838, '...people who despoil the countryside.', 'v. 夺取, 掠夺', '/di\'spɔil | dɪ\'spɒɪl | dɪ\'spɔɪl/', 'despoil', 6);
INSERT INTO `words` VALUES (10839, 'Gill had been out of work for a year and was getting very despondent.', 'adj. 沮丧的', '/di\'spɔndənt | dɪ\'spɒnd(ə)nt | dɪ\'spɑndənt/', 'despondent', 6);
INSERT INTO `words` VALUES (10840, 'The country was ruled by a despotic tyrant.', 'adj. 专制的, 暴虐的', '/de\'spɔtik, des\'pɔtikəl | dɪ\'spɒtɪk | dɪ\'spɑtɪk/', 'despotic', 6);
INSERT INTO `words` VALUES (10841, 'EVEN if I granted all that I have been refuting, the friends of despotism would be no better off.', 'n. 专制', '/\'despətizəm | \'despətɪz(ə)m | \'dɛspətɪzəm/', 'despotism', 6);
INSERT INTO `words` VALUES (10842, NULL, 'v. 命运注定， 预定', '/\'destɪn | \'dɛstɪn/', 'destine', 6);
INSERT INTO `words` VALUES (10843, 'The floods left many people destitute .', 'adj. 困穷的, 缺乏的', '/\'destitju:t | \'destɪtjuːt | \'dɛstə\'tʊt/', 'destitute', 6);
INSERT INTO `words` VALUES (10844, 'Physical education in the western regions lags behind that in the east, which mainly is a destitution of an innovation of sports culture.', 'n. 缺乏， 穷困', '/ˌdestɪ\'tuːʃn | ,desti\'tju:ʃən/', 'destitution', 6);
INSERT INTO `words` VALUES (10845, 'The entire central command complex is still destructible, but there\'s a natural flow to it which means you can\'t just find a camping spot and snipe all the critical buildings with rockets.', 'adj. 可破坏的', '/dɪ\'strʌktəbl/', 'destructible', 6);
INSERT INTO `words` VALUES (10846, '{\"COLLOINEXA\":[\"weapons of mass destruction\"]}', 'n. 破坏, 毁灭', '/di\'strʌkʃən | dɪ\'strʌkʃ(ə)n | dɪ\'strʌkʃən/', 'destruction', 6);
INSERT INTO `words` VALUES (10847, 'those ceremonies had fallen into desuetude', 'n. 废止, 不用', '/di\'sju:itju:d | \'deswɪtjuːd; də\'sjuːətjuːd | \'dɛswɪ,tjʊd/', 'desuetude', 6);
INSERT INTO `words` VALUES (10848, 'They talked briefly in a desultory manner.', 'adj. 散漫的, 不连贯的, 断断续续的', '/\'desəltəri | \'des(ə)lt(ə)rɪ; -z- | \'dɛsəltɔri/', 'desultory', 6);
INSERT INTO `words` VALUES (10849, 'Please detach and fill out the application form.', 'v. 使分离， 使分开， 拆卸', '/dɪ\'tætʃ/', 'detach', 6);
INSERT INTO `words` VALUES (10850, 'Try to take a more detached view .', 'adj. 分开的, 分离的', '/di\'tætʃt | dɪ\'tætʃt/', 'detached', 6);
INSERT INTO `words` VALUES (10851, 'She did not care for the idea of socializing with her clients. It would detract from her professional detachment.', 'n. 分开, 拆开, 特遣部队, 超然, 分离, 分遣队', '/di\'tætʃmənt | dɪ\'tætʃm(ə)nt | dɪ\'tætʃmənt/', 'detachment', 6);
INSERT INTO `words` VALUES (10852, 'Two suspects have been detained by the police for questioning .', 'v. 拘留, 留住, 阻止', '/di\'tein | dɪ\'teɪn | dɪ\'ten/', 'detain', 6);
INSERT INTO `words` VALUES (10853, '...a sensitive piece of equipment used to detect radiation.', 'v. 洞察； 查明， 探测', '/dɪ\'tekt | dɪ\'tɛkt/', 'detect', 6);
INSERT INTO `words` VALUES (10854, '...the early detection of breast cancer.', 'n. 察觉, 发觉, 侦查, 探测, 发现', '/di\'tekʃən | dɪ\'tekʃ(ə)n | dɪ\'tɛkʃən/', 'detection', 6);
INSERT INTO `words` VALUES (10855, '...their desire to pursue a policy of detente.', 'n. （国际关系等的）缓和', '/dei\'tɔŋt | de\'tɑnt/', 'detente', 6);
INSERT INTO `words` VALUES (10856, 'The company’s financial difficulties have deterred potential investors.', 'v. 阻止', '/di\'tə: | dɪ\'tɜː | dɪ\'tɝ/', 'deter', 6);
INSERT INTO `words` VALUES (10857, '...a brand of detergent.', 'n. 清洁剂, 去垢剂', '/di\'tə:dʒənt | dɪ\'tɜːdʒ(ə)nt | dɪ\'tɝdʒənt/', 'detergent', 6);
INSERT INTO `words` VALUES (10858, 'Ethel’s health has deteriorated.', 'v. (使)恶化', '/di\'tiəriəreit | dɪ\'tɪərɪəreɪt | dɪ\'tɪrɪəret/', 'deteriorate', 6);
INSERT INTO `words` VALUES (10859, 'I used this to remember how to calculate the determinant of a matrix.', 'adj. 决定性的; n. 决定因素', '/dɪ\'tɜːrmɪnənt | dɪ\'tɝmɪnənt/', 'determinant', 6);
INSERT INTO `words` VALUES (10860, 'The small fines for this type of crime do not act as much of a deterrent .', 'n. 威慑', '/di\'terənt | dɪ\'ter(ə)nt | dɪ\'tɝənt/', 'deterrent', 6);
INSERT INTO `words` VALUES (10861, 'The two men detested each other.', 'v. 厌恶, 憎恨', '/di\'test | dɪ\'test | dɪ\'tɛst/', 'detest', 6);
INSERT INTO `words` VALUES (10862, 'France is expected to detonate its first nuclear device in the next few days.', 'v. 引爆', '/\'detəneit | \'detəneɪt | \'dɛtənet/', 'detonate', 6);
INSERT INTO `words` VALUES (10863, '...accidental detonation of nuclear weapons.', 'n. 爆炸, 爆炸声, 爆裂', '/,detə\'neiʃən | detə\'neɪʃ(ə)n | ,dɛtə\'neʃən/', 'detonation', 6);
INSERT INTO `words` VALUES (10864, 'He did not take the direct route to his home, but made a detour around the outskirts of the city.', 'n. 便道, 绕路', '/\'di:,tuə, di\'tuə | \'diːtʊə | \'ditʊr/', 'detour', 6);
INSERT INTO `words` VALUES (10865, 'Indications:Clear away heat, eliminate dampness, purge pathogenic fire, put out steam, detoxicate and cure furuncles .', 'v. 使解毒', '/di:\'tɔksikeit | diː\'tɒksɪkeɪt | di\'tɑksə,ket/', 'detoxicate', 6);
INSERT INTO `words` VALUES (10866, 'But if it is detraction, you might feel horrible, and you may self-deprecation.', 'n. 贬低， 诽谤', '/dɪ\'trækʃn | dɪ\'trækʃən/', 'detraction', 6);
INSERT INTO `words` VALUES (10867, NULL, 'n. 诽谤者, 恶意批评者', '/di\'træktə | dɪ\'træktɚ/', 'detractor', 6);
INSERT INTO `words` VALUES (10868, 'Nor is the detriment only to the US industry .', 'n. 损害, 损害物', '/\'detrimənt | \'detrɪm(ə)nt | \'dɛtrɪmənt/', 'detriment', 6);
INSERT INTO `words` VALUES (10869, 'the detrimental effect of pollution on the environment', 'adj. 有害的', '/,detri\'mentəl | ,detrɪ\'ment(ə)l | ,dɛtrɪ\'mɛntl/', 'detrimental', 6);
INSERT INTO `words` VALUES (10870, 'In the distance, the detritus of a century of oil exploration lines the horizon.', 'n. 碎石', '/di\'traitəs | dɪ\'traɪtəs/', 'detritus', 6);
INSERT INTO `words` VALUES (10871, NULL, 'vt. 推倒, 扔掉', '/dɪ\'truːd | di\'tru:d/', 'detrude', 6);
INSERT INTO `words` VALUES (10872, 'The city centre was devastated by the bomb.', 'v. 毁坏', '/\'devəsteit | \'devəsteɪt | \'dɛvəstet/', 'devastate', 6);
INSERT INTO `words` VALUES (10873, 'It will be a devastating blow for the town if the factory closes.', 'adj. 破坏性的, 全然的', '/\'devəsteitiŋ/', 'devastating', 6);
INSERT INTO `words` VALUES (10874, 'deviant behaviour', 'adj. 不正常的', '/\'di:viənt | \'diːvɪənt | \'divɪənt/', 'deviant', 6);
INSERT INTO `words` VALUES (10875, 'They stopped you as soon as you deviated from the script.', 'v. 背离, 偏离', '/\'di:vieit, \'di:viət | \'diːvɪeɪt | \'divɪet/', 'deviate', 6);
INSERT INTO `words` VALUES (10876, 'Deviation from the norm is not tolerated.', 'n. 背离', '/ˌdiːvi\'eɪʃn | \'divɪ\'eʃən/', 'deviation', 6);
INSERT INTO `words` VALUES (10877, 'a devious route', 'adj. 偏僻的, 迂回的, 曲折的', '/\'di:viəs | \'diːvɪəs | \'divɪəs/', 'devious', 6);
INSERT INTO `words` VALUES (10878, 'She devised a method for quicker communications between offices.', 'v. 发明， 设计； 图谋； 遗赠给', '/dɪ\'vaɪz/', 'devise', 6);
INSERT INTO `words` VALUES (10879, 'I have never looked on a face that was so devoid of feeling.', 'adj. 全无的, 缺乏的', '/di\'vɔid | dɪ\'vɒɪd | dɪ\'vɔɪd/', 'devoid', 6);
INSERT INTO `words` VALUES (10880, '...the devolution of power to the regions.', 'n. 滚下, 落下, 依次, 相传, 转移, 委付', '/,di:və\'lju:ʃən | ,diːvə\'luːʃ(ə)n; ,dev- | \'dɛvə\'lʊʃən/', 'devolution', 6);
INSERT INTO `words` VALUES (10881, 'One Sichuan devotee I know describes the ma la sensation as a \"tonguegasm. \" The pulse increases and the pupils dilate, often accompanied by a postnasal drip. The brain floats in a euphoric ether.', 'n. 爱好者， 献身者', '/ˌdevə\'tiː | ,dɛvə\'ti/', 'devotee', 6);
INSERT INTO `words` VALUES (10882, 'At first she was flattered by his devotion.', 'n. 热爱, 投入', '/di\'vəuʃən | dɪ\'vəʊʃ(ə)n | dɪ\'voʃən/', 'devotion', 6);
INSERT INTO `words` VALUES (10883, 'devotional music', 'adj. 献身的， 虔诚的', '/dɪ\'vouʃənl | dɪ\'voʃənl/', 'devotional', 6);
INSERT INTO `words` VALUES (10884, 'The boys devoured their pancakes.', 'v. (尤指动物)吞吃, 狼吞虎咽, 挥霍, (火灾等)毁灭, 破坏, 吞没, 贪看, 贪听', '/dɪ\'vaʊə | dɪ\'vaʊɚ/', 'devour', 6);
INSERT INTO `words` VALUES (10885, 'a devout Catholic', 'adj. 虔诚的； 忠诚的， 忠心的', '/dɪ\'vaut | dɪ\'vaʊt/', 'devout', 6);
INSERT INTO `words` VALUES (10886, 'Computer games can improve children’s manual dexterity .', 'n. 灵巧, 机敏', '/dek\'sterəti | dek\'sterɪtɪ | dɛk\'stɛrəti/', 'dexterity', 6);
INSERT INTO `words` VALUES (10887, 'dextrous use of the needle', 'adj. 灵巧的, 惯用右手的', '/\'dekstərəs | \'dekst(ə)rəs | \'dɛkstrəs/', 'dexterous', 6);
INSERT INTO `words` VALUES (10888, 'You have diabetes, or liver or kidney disease.', 'n. [医] 糖尿病, 多尿症', '/,daiə\'bi:ti:z | ,daɪə\'biːtiːz | ,daɪə\'bitiz/', 'diabetes', 6);
INSERT INTO `words` VALUES (10889, 'diabolical abuse', 'adj. 恶魔的', '/\'daiə\'bɔlik / -kəl | daɪə\'bɒlɪk(ə)l/', 'diabolical', 6);
INSERT INTO `words` VALUES (10890, 'The soldiers were diagnosed as having flu.', 'v. 判断， 诊断', '/ˌdaɪəg\'nous | ,daɪəɡ\'nos/', 'diagnose', 6);
INSERT INTO `words` VALUES (10891, '...X-rays and other diagnostic tools.', 'adj. 诊断的; n. 诊断', '/ˌdaɪəg\'nɑːstɪk | ,daɪəɡ\'nɑstɪk/', 'diagnostic', 6);
INSERT INTO `words` VALUES (10892, 'This diagram will illustrate what I mean.', 'n. 图解， 图表', '/\'daɪəgræm | \'daɪəɡræm/', 'diagram', 6);
INSERT INTO `words` VALUES (10893, 'the local dialect', 'n. 方言', '/\'daɪəlekt | \'daɪə\'lɛkt/', 'dialect', 6);
INSERT INTO `words` VALUES (10894, '...a diaphanous dress of pale gold.', 'adj. 透明的, 精致的', '/dai\'æfənəs | daɪ\'æf(ə)nəs | daɪ\'æfənəs/', 'diaphanous', 6);
INSERT INTO `words` VALUES (10895, 'I was overwhelmed with excitement, and became acutely aware of my own tachycardia and diaphoresis.', 'n. 发汗', '/,daiəfə\'ri:sis | ,daɪəfə\'riːsɪs/', 'diaphoresis', 6);
INSERT INTO `words` VALUES (10896, 'But the food itself was barely digestible, and many team members suffered from diarrhoea or constipation.', 'n. 腹泻', '/,daiə\'riə | ,daɪə\'rɪə/', 'diarrhoea', 6);
INSERT INTO `words` VALUES (10897, 'Well, simply, the point that those ways of thinking about literature, which they exempt from their diatribe against theory.', 'n. 恶骂, 诽谤', '/\'daiətraib | \'daɪətraɪb/', 'diatribe', 6);
INSERT INTO `words` VALUES (10898, NULL, 'n. 两分, 二分法, 分裂', '/dai\'kɔtəmi | daɪ\'kɒtəmɪ; dɪ- | daɪ\'kɑtəmi/', 'dichotomy', 6);
INSERT INTO `words` VALUES (10899, 'He would rather die than dicker over prices.', 'v. 讨价还价', '/\'dɪkər | \'dɪkɚ/', 'dicker', 6);
INSERT INTO `words` VALUES (10900, 'Federal funds have to be used as dictated by Washington.', 'v. 口述, 口授, 使听写, 指令, 指示, 命令, 规定', '/dik\'teit, \'dikteit | dɪk\'teɪt | \'dɪktet/', 'dictate', 6);
INSERT INTO `words` VALUES (10901, 'the downfall of the hated dictator', 'n. 独裁者, 独裁政权执政者, 口授令他人笔录者', '/dik\'teitə, \'dikteitə | dɪk\'teɪtə | \'dɪktetɚ/', 'dictator', 6);
INSERT INTO `words` VALUES (10902, 'Descartes’ famous dictum: ‘I think; therefore, I am’', 'n. 格言, [律] 法官的附带意见', '/\'diktəm | \'dɪktəm/', 'dictum', 6);
INSERT INTO `words` VALUES (10903, 'His novel has a didactic tone.', 'adj. 教诲的,说教的', '/di\'dæktik, dai\'d-,-kəl | dɪ\'dæktɪk; daɪ- | daɪ\'dæktɪk/', 'didactic', 6);
INSERT INTO `words` VALUES (10904, 'This article reviews the applications of heuristic didactics to pharmacology teaching.', 'n. 教授法', '/di\'dæktiks, dai\'d- | dɪ\'dæktɪks | daɪ\'dktɪks/', 'didactics', 6);
INSERT INTO `words` VALUES (10905, 'He died in 1985 at the age of 76.', 'v. 死亡, 消逝, 平息, 渴望, 漠然, 熄灭', '/dai | daɪ/', 'die', 6);
INSERT INTO `words` VALUES (10906, 'John is a diehard conservative and is completely against abortion.', 'n. 顽固分子', '/\'daɪhɑːrd | \'daɪhɑrd/', 'diehard', 6);
INSERT INTO `words` VALUES (10907, 'special dietary requirements', 'adj. 饮食的', '/\'daɪəteri | \'daɪə,tɛri/', 'dietary', 6);
INSERT INTO `words` VALUES (10908, 'Suggest you buy this book dietetics teaching material, there is detailed introduction inside.', 'n. 营养学', '/daiə\'tetiks | daɪə\'tetɪks/', 'dietetics', 6);
INSERT INTO `words` VALUES (10909, 'A registered dietitian can give you lots of other snack and menu ideas.', 'n. <美>营养学家, 营养学家', '/,daiə\'tiʃən | daɪə\'tɪʃ(ə)n | ,daɪə\'tɪʃən/', 'dietitian', 6);
INSERT INTO `words` VALUES (10910, 'What differentiates these two periods of history?', 'v. 辨别， 区别', '/ˌdɪfə\'renʃieɪt | ,dɪfə\'rɛnʃɪet/', 'differentiate', 6);
INSERT INTO `words` VALUES (10911, 'He was too diffident to express his opinion.', 'adj. 缺乏自信的', '/\'dɪfɪdənt/', 'diffident', 6);
INSERT INTO `words` VALUES (10912, 'Their ideas diffused quickly across Europe.', 'v. 散播, 传播, 漫射, 扩散, (使)慢慢混合', '/di\'fju:s | dɪ\'fjuːz | dɪ\'fjus/', 'diffuse', 6);
INSERT INTO `words` VALUES (10913, NULL, 'n. 扩散, 传播, 漫射', '/di\'fju:ʒən | dɪ\'fjuːʒ(ə)n | dɪ\'fjʊʒən/', 'diffusion', 6);
INSERT INTO `words` VALUES (10914, NULL, 'n. 再婚', '/\'dɪɡəmɪ/', 'digamy', 6);
INSERT INTO `words` VALUES (10915, 'Too much tea is bad for your digestion.', 'n. 消化， 吸收', '/daɪ\'dʒestʃən | daɪdʒɛstʃən/', 'digestion', 6);
INSERT INTO `words` VALUES (10916, 'an appearance of quiet dignity', 'n. 尊严， 尊贵', '/\'dɪgnəti | \'dɪɡnəti/', 'dignity', 6);
INSERT INTO `words` VALUES (10917, 'Do you mind if I digress for a moment?', 'v. 离题', '/dai\'ɡres | daɪ\'gres | daɪ\'ɡrɛs/', 'digress', 6);
INSERT INTO `words` VALUES (10918, 'Thee direct address of an absent or imaginary person or of a personified abstraction, especially as a digression in the course of a speech or composition.', 'n. 离题, 脱轨, 扯到枝节上', '/dai\'ɡreʃən | daɪ\'greʃ(ə)n | daɪ\'grɛʃən/', 'digression', 6);
INSERT INTO `words` VALUES (10919, NULL, 'adj. 离题的， 枝节的', '/daɪ\'gresɪv | daɪ\'ɡrɛsɪv; dɪ\'ɡrɛsɪv/', 'digressive', 6);
INSERT INTO `words` VALUES (10920, NULL, 'v. 荒废， 毁坏', '/dɪ\'læpɪdeɪt | di\'læpideit/', 'dilapidate', 6);
INSERT INTO `words` VALUES (10921, '...an old dilapidated barn.', 'adj. 毁坏的, 要塌似的, 荒废的', '/di\'læpideitid | dɪ\'læpɪdeɪtɪd/', 'dilapidated', 6);
INSERT INTO `words` VALUES (10922, NULL, 'n. 荒废, 崩塌, 破损', '/di,læpi\'deiʃən | dɪ,læpɪ\'deɪʃ(ə)n | də,læpə\'deʃən/', 'dilapidation', 6);
INSERT INTO `words` VALUES (10923, 'dilated pupils', 'v. 扩大, 详述, 膨胀', '/dai\'leit, di- | daɪ\'leɪt; dɪ- | daɪˈlet/', 'dilate', 6);
INSERT INTO `words` VALUES (10924, 'You might expect politicians to smooth things out when civil servants are being dilatory.', 'adj. 拖拉的, 不慌不忙的', '/\'dilətəri | \'dɪlət(ə)rɪ | \'dɪlətɔri/', 'dilatory', 6);
INSERT INTO `words` VALUES (10925, 'a moral dilemma', 'n. 进退两难的局面, 困难的选择', '/di\'lemə, ,dai- | dɪ\'lemə; daɪ- | dɪˈlemə/', 'dilemma', 6);
INSERT INTO `words` VALUES (10926, 'He tolerated the presence of an amateur, idler and dilettante and proved a perfect teacher and matchless travel companion.', 'n. 业余艺术爱好者', '/,dili\'tænti, \'dilitɑ:nt | ,dɪlɪ\'tænteɪ; -tɪ | ,dɪlə\'tænti/', 'dilettante', 6);
INSERT INTO `words` VALUES (10927, 'Genius is nothing but labor and diligence.', 'n. 勤勉， 勤奋', '/\'dɪlɪdʒəns/', 'diligence', 6);
INSERT INTO `words` VALUES (10928, 'a diligent student', 'adj. 勤奋的， 勤勉的', '/\'dɪlɪdʒənt/', 'diligent', 6);
INSERT INTO `words` VALUES (10929, NULL, 'v. 磨蹭， 浪费时间', '/\'dɪlidæli | \'dɪli,dæli/', 'dillydally', 6);
INSERT INTO `words` VALUES (10930, 'diluted fruit juice', 'v. 冲淡, 变淡, 变弱, 稀释', '/dai\'lju:t, di- | daɪ\'l(j)uːt; dɪ- | daɪ\'l(j)ut/', 'dilute', 6);
INSERT INTO `words` VALUES (10931, '\"Aromatherapy oils\" are not pure essential oils but dilutions.', 'n. 稀释, 稀释法,冲淡物', '/dai\'lju:ʃən, di- | daɪ\'luːʃn | dɪ\'ljʊʃən/', 'dilution', 6);
INSERT INTO `words` VALUES (10932, 'Their economic prospects have dimmed.', 'v. 使暗淡，使模糊; adj. 昏暗的， 暗淡的', '/dɪm/', 'dim', 6);
INSERT INTO `words` VALUES (10933, 'The party’s share of the electorate has diminished steadily.', 'v. 减少， 缩小', '/dɪ\'mɪnɪʃ/', 'diminish', 6);
INSERT INTO `words` VALUES (10934, NULL, 'n. [乐]渐弱演奏(部分)', '/di,minju\'endəu | dɪ,mɪnjʊ\'endəʊ | dɪ,mɪnju\'ɛndo/', 'diminuendo', 6);
INSERT INTO `words` VALUES (10935, '...despite a slight diminution in asset value.', 'n. 减少， 缩减', '/ˌdɪmɪ\'nuːʃn | /ˌdɪmɪˈnuːʃn//', 'diminution', 6);
INSERT INTO `words` VALUES (10936, 'a shy diminutive man', 'adj. 小的, 指小的, 小型的', '/di\'minjutiv | dɪ\'mɪnjʊtɪv | dɪ\'mɪnjətɪv/', 'diminutive', 6);
INSERT INTO `words` VALUES (10937, 'Bess spoke up, smiling so that her dimples showed.', 'n. 酒窝, 涟漪', '/dimpl | \'dɪmp(ə)l | \'dɪmpəl/', 'dimple', 6);
INSERT INTO `words` VALUES (10938, 'They tried to make themselves heard over the din of the crowd.', 'n. 喧嚣', '/din | dɪn/', 'din', 6);
INSERT INTO `words` VALUES (10939, '...a rubber dinghy.', 'n. 小舢板,小游艇', '/diŋɡi, diŋi | \'dɪŋgɪ; \'dɪŋɪ | dɪŋi/', 'dinghy', 6);
INSERT INTO `words` VALUES (10940, 'a dingy room', 'adj. 暗黑的, 邋遢的', '/dindʒi | \'dɪn(d)ʒɪ | \'dɪndʒi/', 'dingy', 6);
INSERT INTO `words` VALUES (10941, NULL, 'v. 击出凹痕', '/dɪnt/', 'dint', 6);
INSERT INTO `words` VALUES (10942, 'Diplomatic efforts to end the fighting began on October 25.', 'adj. 外交的, 老练的', '/,diplə\'mætik | dɪplə\'mætɪk | ,dɪplə\'mætɪk/', 'diplomatic', 6);
INSERT INTO `words` VALUES (10943, NULL, 'n. 耽酒症, 饮酒狂', '/,dipsəu\'meinjə | ,dɪpsə(ʊ)\'meɪnɪə/', 'dipsomania', 6);
INSERT INTO `words` VALUES (10944, 'warnings of dire consequences that often don’t come true', 'adj. 可怕的', '/\'daɪər | \'daiə/', 'dire', 6);
INSERT INTO `words` VALUES (10945, NULL, 'adj. 可怕的, 悲惨的', '/\'daiəful | \'daɪəfʊl; -f(ə)l/', 'direful', 6);
INSERT INTO `words` VALUES (10946, NULL, 'n. 挽歌, 哀悼歌', '/də:dʒ | dɜːdʒ | dɝdʒ/', 'dirge', 6);
INSERT INTO `words` VALUES (10947, NULL, 'n. 匕首', '/də:k | dɜːk/', 'dirk', 6);
INSERT INTO `words` VALUES (10948, 'Their view of country people was that they like to please strangers. I did not disabuse them of this notion.', 'v. 解惑, 释疑, 使省悟', '/,disə\'bju:z | ,dɪsə\'bjuːz | ,dɪsə\'bjuz/', 'disabuse', 6);
INSERT INTO `words` VALUES (10949, NULL, 'v. 使不满； 使疏远', '/ˌdɪsə\'fekt | ,dɪsə\'fɛkt/', 'disaffect', 6);
INSERT INTO `words` VALUES (10950, 'the disaffected youth from poor neighborhoods', 'adj. 抱不平的, 有叛意的, 不服的', '/disə\'fektid | ,dɪsə\'fɛktɪd/', 'disaffected', 6);
INSERT INTO `words` VALUES (10951, '...people\'s disaffection with their country and its leaders.', 'n. 不满', '/,disə\'fekʃən | ,dɪsə\'fɛkʃən/', 'disaffection', 6);
INSERT INTO `words` VALUES (10952, 'a disagreeable job', 'adj. 不愉快的, 不为人喜的, 厌恶的', '/disə\'ɡriəbl, -ɡri:ə- | dɪsə\'griːəb(ə)l | ,dɪsə\'ɡriəbl/', 'disagreeable', 6);
INSERT INTO `words` VALUES (10953, 'Captured soldiers were disarmed and put into camps.', 'v. 使缴械； 使缓和', '/dɪs\'ɑːrm | dɪs\'ɑrm/', 'disarm', 6);
INSERT INTO `words` VALUES (10954, 'If the Pope\'s initiative succeeds, the Church of England will be further weakened and plunged into even greater disarray.', 'v. 混乱', '/,disə\'rei | dɪsə\'reɪ/', 'disarray', 6);
INSERT INTO `words` VALUES (10955, 'One hundred and twenty people died in China’s worst air disaster .', 'n. 灾难, 天灾, 灾祸', '/,di\'zɑ:stə | dɪ\'zɑːstə | dɪ\'zæstɚ/', 'disaster', 6);
INSERT INTO `words` VALUES (10956, 'a disastrous first marriage', 'adj. 损失惨重的, 悲伤的', '/di\'zɑ:strəs | dɪ\'zɑːstrəs | dɪ\'zæstrəs/', 'disastrous', 6);
INSERT INTO `words` VALUES (10957, 'I deny, disaffirm and disavow that…', 'v. 否认， 否定， 抵赖', '/ˌdɪsə\'vau | ,dɪsə\'vaʊ/', 'disavow', 6);
INSERT INTO `words` VALUES (10958, '...a public disavowal of his beliefs.', 'n. 否认', '/ˌdɪsə\'vauəl | ,dɪsə\'vaʊəl/', 'disavowal', 6);
INSERT INTO `words` VALUES (10959, 'All the armed groups will be disbanded.', 'v. 解散, 裁减', '/dis\'bænd | dɪs\'bænd/', 'disband', 6);
INSERT INTO `words` VALUES (10960, 'Roy learns that his political opponents plan to disbar him for an ethical lapse, but he vows to remain a lawyer until he dies.', 'v. [律] 逐出法庭, 剥夺律师资格', '/dis\'bɑ: | dɪs\'bɑː | dɪs\'bɑr/', 'disbar', 6);
INSERT INTO `words` VALUES (10961, 'The aid will not be disbursed until next year.', 'v. 支付', '/dis\'bə:s | dɪs\'bɜːs/', 'disburse', 6);
INSERT INTO `words` VALUES (10962, 'Let\'s switch the talk to disbursement.', 'n. 支付, 支出', '/dis\'bə:smənt | dɪs\'bɜːsm(ə)nt | dɪs\'bɝsmənt/', 'disbursement', 6);
INSERT INTO `words` VALUES (10963, NULL, 'adj. 赤脚的, 仅穿拖鞋的', '/dis\'kælsd | dɪs\'kælst/', 'discalced', 6);
INSERT INTO `words` VALUES (10964, 'We could just discern a town in the distance.', 'v. 目睹, 认识, 洞悉, 辨别, 看清楚', '/di\'sə:n, -\'zə:n | dɪ\'sɜːn | dɪ\'sɝn/', 'discern', 6);
INSERT INTO `words` VALUES (10965, 'Far away the outline of the island is just discernible.', 'adj. 可识别的， 可辨的', '/dɪ\'sənəbl | dɪ\'zɝnəbl/', 'discernible', 6);
INSERT INTO `words` VALUES (10966, 'the woman’s taste and discernment', 'n. 识别力, 眼力,洞察力', '/di\'sə:nmənt, -\'zə:n- | dɪ\'sɜːnm(ə)nt | dɪ\'sɝnmənt/', 'discernment', 6);
INSERT INTO `words` VALUES (10967, 'Hospitals now tend to discharge patients earlier than in the past.', 'v. 卸下, 放出, 清偿(债务), 履行(义务), 解雇, 开(炮), 放(枪), 射(箭)', '/dis\'tʃɑ:dʒ, \'distʃɑ:dʒ, dis\'tʃ- | dɪs\'tʃɑːdʒ | dɪs\'tʃɑrdʒ/', 'discharge', 6);
INSERT INTO `words` VALUES (10968, '...a major intellectual figure with disciples throughout Europe.', 'n. 信徒, 弟子, 门徒', '/di\'saipl | dɪ\'saɪp(ə)l | dɪ\'saɪpl/', 'disciple', 6);
INSERT INTO `words` VALUES (10969, NULL, 'adj. 训练的, 规律的, 训育的', '/disipli\'nεəriən | ,dɪsɪplɪ\'neərɪən | ,dɪsəplɪ\'nɛrɪən/', 'disciplinarian', 6);
INSERT INTO `words` VALUES (10970, 'Different cultures have different ways of disciplining their children.', 'v. 训练， 训导; n. 纪律；惩罚，处分', '/\'dɪsəplɪn/', 'discipline', 6);
INSERT INTO `words` VALUES (10971, 'She disclaims any knowledge of her husband\'s business.', 'v. 放弃, 弃权, 拒绝', '/dis\'kleim | dɪs\'kleɪm | dɪs\'klem/', 'disclaim', 6);
INSERT INTO `words` VALUES (10972, 'Some companies have already voluntarily disclosed similar information .', 'v. 揭露', '/dɪs\'klouz | dɪs\'kloz/', 'disclose', 6);
INSERT INTO `words` VALUES (10973, NULL, 'n. 音乐唱片分类目录, 音乐唱片分类学(法),录音作品目录', '/dɪ\'skɒgrəfɪ | dɪs\'kɑɡrəfi/', 'discography', 6);
INSERT INTO `words` VALUES (10974, NULL, 'adj. 扰乱的， 打乱的', '/ˌdɪskəm\'bɑːbjuleitɪd | ,dɪskəm\'bɑbjə,let/', 'discombobulated', 6);
INSERT INTO `words` VALUES (10975, 'They fear the public ignoring their jobs so that city services are not maintained, a discomfit to the elite.', 'v. 扰乱', '/dis\'kʌmfit | dɪs\'kʌmfɪt/', 'discomfit', 6);
INSERT INTO `words` VALUES (10976, NULL, 'adj. 困惑的， 尴尬的', '/dɪs\'kʌmfɪtɪd | dɪs\'kʌmfɪt/', 'discomfited', 6);
INSERT INTO `words` VALUES (10977, 'People laugh not only from pleasure or affection, but also at the discomfiture of someone else.', 'n. 挫折, 失败,崩溃,尴尬', '/dis\'kʌmfitʃə | dɪs\'kʌmfɪtʃə/', 'discomfiture', 6);
INSERT INTO `words` VALUES (10978, 'Some people use marijuana to fight pain or discomfort caused by disease.', 'v. 使不适; n. 不适', '/dɪs\'kʌmfərt | dɪs\'kʌmfɚt/', 'discomfort', 6);
INSERT INTO `words` VALUES (10979, NULL, 'v. 使不方便, 使为难, 使不自由', '/,diskə\'məud | ,dɪskə\'məʊd/', 'discommode', 6);
INSERT INTO `words` VALUES (10980, NULL, 'v. 不安', '/,diskəm\'pəuz | dɪskəm\'pəʊz | ,dɪskəm\'poz/', 'discompose', 6);
INSERT INTO `words` VALUES (10981, 'THE discomposure of spirits which this extraordinary visit threw Elizabeth into, could not be easily overcome; nor could she, for many hours, learn to think of it less than incessantly.', 'n. 心乱, 狼狈, 不安', '/,diskəm\'pəuʒə/', 'discomposure', 6);
INSERT INTO `words` VALUES (10982, 'He did not have much success, but tried not to get too disconsolate.', 'adj. 闷闷不乐的， 郁郁寡欢的', '/dɪs\'kɑːnsələt | dɪs\'kɑnsələt/', 'disconsolate', 6);
INSERT INTO `words` VALUES (10983, 'Remember not to mention your discontent.', 'v. 使不满; adj. 不满的; n. 不满', '/ˌdɪskən\'tent | ,dɪskən\'tɛnt/', 'discontent', 6);
INSERT INTO `words` VALUES (10984, 'The black freedom struggle should be the model for all discontented Americans.', 'adj. 不满意的', '/,diskən\'tentid | dɪskən\'tentɪd | ,dɪskən\'tɛntɪd/', 'discontented', 6);
INSERT INTO `words` VALUES (10985, 'marital discord', 'n. 不和， 纷争', '/\'dɪskɔːrd | \'dɪskɔrd/', 'discord', 6);
INSERT INTO `words` VALUES (10986, 'The modern decor strikes a discordant note in this old building.', 'adj. 不调和的, 不和的, [乐]不悦耳的, 不和谐的', '/dis\'kɔ:dənt | dɪ\'skɔːd(ə)nt | dɪs\'kɔrdənt/', 'discordant', 6);
INSERT INTO `words` VALUES (10987, 'They are often available at a discount.', 'n. 折扣', '/\'dɪskaunt | dɪs\'kaʊnt/', 'discount', 6);
INSERT INTO `words` VALUES (10988, 'You should not let one failure discourage you.', 'v. 使气馁， 使沮丧； 阻碍', '/dɪs\'kɜːrɪdʒ | dɪs\'kɝɪdʒ/', 'discourage', 6);
INSERT INTO `words` VALUES (10989, 'The results were discouraging.', 'adj. 令人气馁的', '/dɪs\'kɜːrɪdʒɪŋ/', 'discouraging', 6);
INSERT INTO `words` VALUES (10990, 'Candidates should engage in serious political discourse.', 'n. 演讲, 论述, 论文, 讲道, 谈话, 谈论', '/\'diskɔ:s, dis\'kɔ:s | \'dɪskɔːs; -\'kɔːs | \'dɪskɔrs/', 'discourse', 6);
INSERT INTO `words` VALUES (10991, 'It would be discourteous to ignore his request.', 'adj. 失礼的, 无礼貌的', '/dis\'kə:tjəs, -ti- | dɪs\'kɜːtjəs | dɪs\'kɝtɪəs/', 'discourteous', 6);
INSERT INTO `words` VALUES (10992, 'However, I believe in questionings, doubtings, searchings, skepticism, and I discredit credulity or blind faith.', 'n. 无信用, 疑惑, 不名誉, 耻辱', '/dis\'kredit | dɪs\'kredɪt | dɪs\'krɛdɪt/', 'discredit', 6);
INSERT INTO `words` VALUES (10993, 'He assured her that he would be discreet.', 'adj. 小心的, 慎重的, 有思虑的, 贤明的', '/dis\'kri:t | dɪ\'skriːt | dɪ\'skrit/', 'discreet', 6);
INSERT INTO `words` VALUES (10994, '...the discrepancy between press and radio reports.', 'n. 相差, 差异, 矛盾', '/dis\'krepənsi | dɪs\'krep(ə)nsɪ | dɪs\'krɛpənsi/', 'discrepancy', 6);
INSERT INTO `words` VALUES (10995, 'The change happens in a series of discrete steps.', 'adj. 不连续的, 离散的', '/dis\'kri:t | dɪ\'skriːt | dɪ\'skrit/', 'discrete', 6);
INSERT INTO `words` VALUES (10996, 'Promotions are left to the discretion of the supervisor.', 'n. 判断力', '/dis\'kreʃən | dɪ\'skreʃ(ə)n | dɪ\'skrɛʃən/', 'discretion', 6);
INSERT INTO `words` VALUES (10997, 'the court’s discretionary powers', 'adj. 自由决定的', '/dɪ\'skreʃəneri | dɪ\'skrɛʃə\'nɛri/', 'discretionary', 6);
INSERT INTO `words` VALUES (10998, 'He is incapable of discriminating between a good idea and a terrible one.', 'v. 区别， 歧视', '/dɪ\'skrɪmɪneɪt | dɪ\'skrɪmɪnet/', 'discriminate', 6);
INSERT INTO `words` VALUES (10999, 'discriminating readers', 'adj. 识别的, 有差别的, 有识别力的', '/dis\'krimineitiŋ | dɪ\'skrɪmɪneɪtɪŋ | dɪ\'skrɪmɪnetɪŋ/', 'discriminating', 6);
INSERT INTO `words` VALUES (11000, 'discriminatory hiring practices', 'adj. 有辨识力的, 有差别的', '/dis\'kriminətəri | dɪ\'skrɪmɪnɪ,t(ə)rɪ; dɪ,skrɪmɪ\'neɪt(ə)rɪ | dɪ\'skrɪmɪnətɔri/', 'discriminatory', 6);
INSERT INTO `words` VALUES (11001, 'a long, discursive article', 'adj. 散漫的, 不得要领的', '/dis\'kə:siv | dɪs\'kɜːsɪv | dɪs\'kɝsɪv/', 'discursive', 6);
INSERT INTO `words` VALUES (11002, 'Janet looked at him with disdain.', 'n. 轻蔑, 以高傲的态度对待', '/dis\'dein | dɪs\'deɪn; -z- | dɪs\'den/', 'disdain', 6);
INSERT INTO `words` VALUES (11003, 'a disdainful look', 'adj. 轻蔑的, 倨傲的', '/dis\'deinful | dɪs\'deɪnfʊl; -f(ə)l; -z- | dɪs\'denfl/', 'disdainful', 6);
INSERT INTO `words` VALUES (11004, 'disembodied spirits', 'adj. 无实质的, 无实体的', '/,disim\'bɔdid | ,dɪsɪm\'bɑdɪd/', 'disembodied', 6);
INSERT INTO `words` VALUES (11005, NULL, 'vt. 吐露, 泄露', '/dɪsɪm\'bʊzəm | ,dɪsəm\'bʊzəm/', 'disembosom', 6);
INSERT INTO `words` VALUES (11006, 'she is disenchanted with the marriage', 'v. 使不抱幻想， 使清醒', '/ˌdɪsɪn\'tʃænt | ,dɪsɪn\'tʃænt/', 'disenchant', 6);
INSERT INTO `words` VALUES (11007, 'How can you disencumber Oh?', 'v. 摆脱烦恼, 不受妨碍', '/,disin\'kʌmbə | dɪsɪn\'kʌmbə; dɪsen-/', 'disencumber', 6);
INSERT INTO `words` VALUES (11008, '...fears of an organized attempt to disenfranchise supporters of Father Aristide.', 'v. 剥夺…的权利', '/ˌdɪsɪn\'fræntʃaɪz | ,dɪsɪn\'fræntʃaɪz/', 'disenfranchise', 6);
INSERT INTO `words` VALUES (11009, 'Disengage the gears when you park the car.', 'v. 脱离， 解开', '/ˌdɪsɪn\'geɪdʒ | \'dɪsɪn\'gedʒ/', 'disengage', 6);
INSERT INTO `words` VALUES (11010, 'teenagers who are depressed or disengaged from their families', 'adj. 自由的, 闲散的, 空闲的', '/,disin\'ɡeidʒd | dɪsɪn\'ɡeɪdʒd | ,dɪsɪn\'gedʒd/', 'disengaged', 6);
INSERT INTO `words` VALUES (11011, 'She had just disentangled herself from a long relationship.', 'v. 解决； 解脱， 解开', '/ˌdɪsɪn\'tæŋgl | ,dɪsɪn\'tæŋɡl/', 'disentangle', 6);
INSERT INTO `words` VALUES (11012, 'His face had been disfigured in an accident.', 'v. 损毁…的外形； 使变丑', '/dɪs\'fɪgjər | dɪs\'fɪɡjɚ/', 'disfigure', 6);
INSERT INTO `words` VALUES (11013, NULL, 'v. 剥夺公民权, 剥夺推举议员权, 剥夺权利', '/,dis\'fræntʃaiz | dɪs\'fræn(t)ʃaɪz/', 'disfranchise', 6);
INSERT INTO `words` VALUES (11014, 'Cars drew up to disgorge a wedding party.', 'v. 吐出', '/dis\'ɡɔ:dʒ | dɪs\'gɔːdʒ | dɪs\'ɡɔrdʒ/', 'disgorge', 6);
INSERT INTO `words` VALUES (11015, NULL, 'v. 使不高兴', '/dɪs\'grʌntl/', 'disgruntle', 6);
INSERT INTO `words` VALUES (11016, 'a disgruntled client', 'adj. 不满的, 不高兴的', '/dis\'ɡrʌntld | dɪs\'grʌnt(ə)ld | dɪs\'ɡrʌntld/', 'disgruntled', 6);
INSERT INTO `words` VALUES (11017, 'He escaped across the border disguised as a priest.', 'v. 假装, 伪装, 掩饰', '/dis\'ɡaiz | dɪs\'gaɪz | dɪs\'ɡaɪz/', 'disguise', 6);
INSERT INTO `words` VALUES (11018, 'He reached into the bin with a look of disgust on his face.', 'n. 反感， 厌恶', '/dɪs\'gʌst | dɪs\'ɡʌst/', 'disgust', 6);
INSERT INTO `words` VALUES (11019, NULL, 'v. 使蓬乱， 使凌乱', '/dɪ\'ʃevl/', 'dishevel', 6);
INSERT INTO `words` VALUES (11020, 'A disheveled pile of books on the library table.', 'adj. 不整的， 凌乱的', '/di\'ʃevəld | dɪ\'ʃevld/', 'disheveled', 6);
INSERT INTO `words` VALUES (11021, 'Pam arrived late, dishevelled and out of breath.', 'adj. 散乱的, 蓬乱的', '/di\'ʃevəld/', 'dishevelled', 6);
INSERT INTO `words` VALUES (11022, 'I hate to disillusion you, but I don’t think she’s coming back.', 'v. 使梦想破灭， 使醒悟', '/ˌdɪsɪ\'luːʒn | ,dɪsɪ\'luʒn/', 'disillusion', 6);
INSERT INTO `words` VALUES (11023, 'the increasing disinclination of farm workers’ children to consider a job in farming', 'n. 不愿意， 不情愿', '/ˌdɪsˌɪnklɪ\'neɪʃn | ,dɪs,ɪnklɪ\'neʃən/', 'disinclination', 6);
INSERT INTO `words` VALUES (11024, 'He was disinclined to talk about himself, especially to his students.', 'adj. 不愿的, 不想的', '/,disin\'klaind | dɪsɪn\'klaɪnd/', 'disinclined', 6);
INSERT INTO `words` VALUES (11025, 'Alcohol may be a medical disinfectant,but should not be relied upon to sterilize water.', 'n. 消毒剂', '/,disin\'fektənt | dɪsɪn\'fekt(ə)nt | \'dɪsɪn\'fɛktənt/', 'disinfectant', 6);
INSERT INTO `words` VALUES (11026, 'Keeping the details of the tax changes vague is disingenuous.', 'adj. 无诚意的', '/,disin\'dʒenjuəs | ,dɪsɪn\'dʒenjʊəs | ,dɪsɪn\'dʒɛnjuəs/', 'disingenuous', 6);
INSERT INTO `words` VALUES (11027, 'The plane just disintegrated in mid-air.', 'v. (使)分解, (使)碎裂', '/dis\'intiɡreit | dɪs\'ɪntɪgreɪt | dɪs\'ɪntɪɡret/', 'disintegrate', 6);
INSERT INTO `words` VALUES (11028, 'The bones were disinterred and moved to a burial site.', 'v. 掘出', '/,disin\'tə: | ,dɪsɪn\'tɜː | ,dɪsɪn\'tɝ/', 'disinter', 6);
INSERT INTO `words` VALUES (11029, 'His total disinterest in money puzzled his family.', 'v. 使失去兴趣; n. 无兴趣', '/dɪs\'ɪntrəst/', 'disinterest', 6);
INSERT INTO `words` VALUES (11030, 'A lawyer should provide disinterested advice.', 'adj. 无私的', '/dis\'intristid, -\'intəris- | dɪs\'ɪnt(ə)rɪstɪd | dɪs\'ɪntərɪsɪd/', 'disinterested', 6);
INSERT INTO `words` VALUES (11031, 'disjointed fragments of information', 'adj. 脱节的,杂乱的', '/dis\'dʒɔintid | dɪs\'dʒɒɪntɪd | dɪs\'dʒɔɪntɪd/', 'disjointed', 6);
INSERT INTO `words` VALUES (11032, 'Like society , it builds its unity on the disjunction.', 'n. 分离， 分裂', '/dɪs\'dʒʌŋkʃn | dɪs\'dʒʌŋkʃən/', 'disjunction', 6);
INSERT INTO `words` VALUES (11033, 'Disjunctive words coexistence refers to two disjunctive words being used in a sentence.', 'adj. 分离的； 转折的， 反意的', '/dɪs\'dʒʌŋktɪv/', 'disjunctive', 6);
INSERT INTO `words` VALUES (11034, 'I dislocated my shoulder playing football.', 'v. 使脱臼； 把…弄乱', '/\'dɪsloukeɪt | \'dɪsloket/', 'dislocate', 6);
INSERT INTO `words` VALUES (11035, 'Millions of refugees have suffered a total dislocation of their lives.', 'n. 混乱, 断层, 脱臼', '/,disləu\'keiʃən | ,dɪslə(ʊ)\'keɪʃ(ə)n | ,dɪslo\'keʃən/', 'dislocation', 6);
INSERT INTO `words` VALUES (11036, 'the revolution that failed to dislodge the British in 1919', 'v. 驱逐', '/dis\'lɔdʒ | dɪs\'lɒdʒ | dɪs\'lɑdʒ/', 'dislodge', 6);
INSERT INTO `words` VALUES (11037, 'The future looks pretty dismal right now.', 'adj. 沮丧的， 阴沉的', '/\'dɪzməl/', 'dismal', 6);
INSERT INTO `words` VALUES (11038, 'Chris dismantled the bike in five minutes.', 'v. 拆除', '/dɪs\'mæntl/', 'dismantle', 6);
INSERT INTO `words` VALUES (11039, 'The committee was dismayed by what it had been told.', 'v. 使气馁; n. 沮丧，气馁', '/dɪs\'meɪ | dɪs\'me/', 'dismay', 6);
INSERT INTO `words` VALUES (11040, 'She then dismembered him, hiding parts of his body in the cellar.', 'v. 肢解； 分割', '/dɪs\'membər | dɪs\'mɛmbɚ/', 'dismember', 6);
INSERT INTO `words` VALUES (11041, 'The class was dismissed early today.', 'v. 解散； 解雇', '/dɪs\'mɪs/', 'dismiss', 6);
INSERT INTO `words` VALUES (11042, NULL, 'v. 扰乱， 使混乱', '/dɪs\'ɔːgənaɪz | dis\'ɔ:ɡənaiz/', 'disorganize', 6);
INSERT INTO `words` VALUES (11043, 'Matcham’s theatres were widely disparaged by architects.', 'v. 蔑视, 贬损, 使失去信誉', '/dis\'pæridʒ | dɪ\'spærɪdʒ/', 'disparage', 6);
INSERT INTO `words` VALUES (11044, 'a meeting covering many disparate subjects', 'adj. 全异的', '/\'dispərət | \'dɪsp(ə)rət | \'dɪspərət/', 'disparate', 6);
INSERT INTO `words` VALUES (11045, '...the health disparities between ethnic and socio-economic groups in the U.S.', 'n. (职位、数量、质量等)不一致, 不同, 不等', '/dis\'pærəti | dɪ\'spærɪtɪ | dɪ\'spærəti/', 'disparity', 6);
INSERT INTO `words` VALUES (11046, 'a dispassionate view of the situation', 'adj. 冷静的, 不带感情的, 平心静气的', '/dis\'pæʃənət | dɪs\'pæʃ(ə)nət | dɪs\'pæʃənət/', 'dispassionate', 6);
INSERT INTO `words` VALUES (11047, 'Goods are normally dispatched within 24 hours.', 'v. 分派, 派遣', '/dis\'pætʃ | dɪˈspætʃ | dɪ\'spætʃ/', 'dispatch', 6);
INSERT INTO `words` VALUES (11048, 'We want to dispel the myth that you cannot eat well in Britain.', 'v. 驱散, 驱逐, 使消散', '/dis\'pel | dɪ\'spel | dɪ\'spɛl/', 'dispel', 6);
INSERT INTO `words` VALUES (11049, 'Part-time workers are considered dispensable.', 'adj. 不是必要的, 可有可无的', '/dis\'pensəbl | dɪs\'pensəbl | dɪ\'spɛnsəbl/', 'dispensable', 6);
INSERT INTO `words` VALUES (11050, 'a machine for dispensing cash', 'v. 分配， 分发', '/dɪ\'spens | dɪ\'spɛns/', 'dispense', 6);
INSERT INTO `words` VALUES (11051, 'Police used tear gas to disperse the crowd.', 'v. 消散， 驱散', '/dɪ\'spɜːrs | dɪ\'spɝs/', 'disperse', 6);
INSERT INTO `words` VALUES (11052, '...the rich and famous disporting themselves in glamorous places.', 'v. 玩耍, 娱乐', '/dis\'pɔ:t | dɪ\'spɔːt/', 'disport', 6);
INSERT INTO `words` VALUES (11053, 'disposable nappies', 'adj. 一次性的； 可自由使用的', '/dɪ\'spouzəbl | dɪ\'spozəbl/', 'disposable', 6);
INSERT INTO `words` VALUES (11054, 'Chinese vases are disposed around the gallery.', 'v. 使倾向于； 处理', '/dɪ\'spouz | dɪ\'spoz/', 'dispose', 6);
INSERT INTO `words` VALUES (11055, 'We passed one or two dwellings, but were not disposed to stop.', 'adj. 愿意的， 想干的', '/dɪ\'spouzd | dɪ\'spozd/', 'disposed', 6);
INSERT INTO `words` VALUES (11056, NULL, 'n. 部署', '/,dispə\'ziʃən | dɪspə\'zɪʃ(ə)n | \'dɪspə\'zɪʃən/', 'disposition', 6);
INSERT INTO `words` VALUES (11057, 'He has been unjustly dispossessed of his country.', 'adj. 无依无靠的, 被逐出的', '/,dispə\'zest/', 'dispossessed', 6);
INSERT INTO `words` VALUES (11058, 'He could not believe even with the disproof before his eyes.', 'n. 反证， 反驳', '/ˌdɪs\'pruːf | dɪs\'prʊf/', 'disproof', 6);
INSERT INTO `words` VALUES (11059, 'the disproportionate amount of money being spent on defence', 'adj. 不成比例的', '/ˌdɪsprə\'pɔːrʃənət | disprə\'pɔ:ʃənət/', 'disproportionate', 6);
INSERT INTO `words` VALUES (11060, 'These figures disproved Smith’s argument.', 'v. 证明…有误', '/ˌdɪs\'pruːv | ,dɪs\'pruv/', 'disprove', 6);
INSERT INTO `words` VALUES (11061, 'The referee\'s decision was disputable.', 'adj. 有争议的', '/dɪ\'spjuːtəbl | dɪ\'spjutəbl/', 'disputable', 6);
INSERT INTO `words` VALUES (11062, 'A mediator should not guarantee results, especially if such guarantee could be perceived as favoring one type of disputant or industry over another.', 'n. 争论者', '/dis\'pju:tənt | dɪs\'pjuːtənt | \'dɪspjʊtnt/', 'disputant', 6);
INSERT INTO `words` VALUES (11063, 'Mr. Frankfurt spent much of his childhood in Brooklyn, and still sees himself as a disputatious Brooklynite - one who still speaks of the Dodgers as \"having betrayed us.', 'adj. 好争辩的', '/,dispju\'teiʃəs | dɪspjuː\'teɪʃəs; -pjʊ\'t-/', 'disputatious', 6);
INSERT INTO `words` VALUES (11064, 'What happened next is hotly disputed .', 'v. 争论', '/dɪ\'spjuːt | \'dɪs\'pjʊt/', 'dispute', 6);
INSERT INTO `words` VALUES (11065, 'There is growing public disquiet about the cost of such policing.', 'n. 忧虑, 不安', '/dis\'kwaiət | dɪs\'kwaɪət/', 'disquiet', 6);
INSERT INTO `words` VALUES (11066, NULL, 'n. 专题论文', '/,diskwi\'ziʃən | ,dɪskwɪ\'zɪʃ(ə)n | ,dɪskwɪ\'zɪʃən/', 'disquisition', 6);
INSERT INTO `words` VALUES (11067, 'disreputable behavior', 'adj. 声名狼藉的, 破烂不堪的', '/dis\'repjutəbl | dɪs\'repjʊtəb(ə)l | dɪs\'rɛpjətəbl/', 'disreputable', 6);
INSERT INTO `words` VALUES (11068, 'Traffic was disrupted by a hoax bomb.', 'v. 使混乱； 使中断', '/dɪs\'rʌpt/', 'disrupt', 6);
INSERT INTO `words` VALUES (11069, 'Mike’s parents thought I was a disruptive influence (= a person who causes disruption ) .', 'adj. 制造混乱的', '/dɪs\'rʌptɪv/', 'disruptive', 6);
INSERT INTO `words` VALUES (11070, 'books in which the lives of famous people are dissected', 'v. 解剖； 剖析', '/dɪ\'sekt | dɪˈsɛkt, daɪ-, ˈdaɪˌsɛkt/', 'dissect', 6);
INSERT INTO `words` VALUES (11071, 'Henry was not slow to dissemble when it served his purposes.', 'v. 掩饰, 假装不知道', '/di\'sembl | dɪ\'semb(ə)l/', 'dissemble', 6);
INSERT INTO `words` VALUES (11072, 'Her findings have been widely disseminated .', 'v. 散布', '/di\'semineit | dɪ\'semɪneɪt | dɪ\'sɛmɪnet/', 'disseminate', 6);
INSERT INTO `words` VALUES (11073, 'There are some dissenting voices (= people who do not agree ) among the undergraduates.', 'v. 不同意', '/di\'sent | dɪ\'sent | dɪ\'sɛnt/', 'dissent', 6);
INSERT INTO `words` VALUES (11074, 'Political dissenters were imprisoned.', 'n. 不同意者, 非国教派的人, 反对者', '/di\'sentə | dɪ\'sentə/', 'dissenter', 6);
INSERT INTO `words` VALUES (11075, 'He is currently writing a dissertation on the Somali civil war.', 'n. 专题论文', '/dɪsər\'teɪʃn | \'dɪsɚ\'teʃən/', 'dissertation', 6);
INSERT INTO `words` VALUES (11076, 'Varroa mite is one of the most harmful vermin that disserve the beekeeping in the worldwide.', 'vt. 危害', '/dɪs\'sɜːv/', 'disserve', 6);
INSERT INTO `words` VALUES (11077, 'a political dissident', 'n. 持不同政见者', '/\'disidənt | \'dɪsɪd(ə)nt | \'dɪsɪdənt/', 'dissident', 6);
INSERT INTO `words` VALUES (11078, 'His methods were not dissimilar to those used by Freud.', 'adj. 不同的， 不相似的', '/dɪ\'sɪmɪlər | dɪ\'sɪmɪlɚ/', 'dissimilar', 6);
INSERT INTO `words` VALUES (11079, 'This man was too injured to dissimulate well.', 'v. 掩饰, 假装, 装糊涂', '/di\'simjuleit | dɪ\'sɪmjʊleɪt/', 'dissimulate', 6);
INSERT INTO `words` VALUES (11080, 'As he thought it over, his anger gradually dissipated.', 'v. 驱散, (使)(云、雾、疑虑等)消散, 浪费(金钱或时间)', '/\'disipeit | \'dɪsɪpeɪt | \'dɪsɪpet/', 'dissipate', 6);
INSERT INTO `words` VALUES (11081, 'Flynn was still handsome, though dissipated.', 'adj. 沉迷于酒色的, 消散的, 闲游浪荡的', '/\'disipeitid | \'dɪsɪpeɪtɪd | \'dɪsɪpetɪd/', 'dissipated', 6);
INSERT INTO `words` VALUES (11082, 'It seems harder and harder for the president to dissociate himself from the scandals that surround Mr. Galdos.', 'v. 分离， 游离， 分裂', '/dɪ\'souʃieɪt | dɪ\'soʃɪet/', 'dissociate', 6);
INSERT INTO `words` VALUES (11083, NULL, 'n. 分离， 脱离关系', '/dɪˌsouʃi\'eɪʃn | dɪ,sosɪ\'eʃən/', 'dissociation', 6);
INSERT INTO `words` VALUES (11084, NULL, 'adj. 放荡的, 风流的, 肆意挥霍的', '/\'disəlju:t | \'dɪsəluːt | \'dɪsəlut/', 'dissolute', 6);
INSERT INTO `words` VALUES (11085, 'Stir until the sugar dissolves.', 'v. 溶解', '/dɪ\'zɑːlv | dɪ\'zɑlv/', 'dissolve', 6);
INSERT INTO `words` VALUES (11086, NULL, 'n. 不一致, 不调和, 不谐和音', '/\'disənəns | \'dɪs(ə)nəns | \'dɪsənəns/', 'dissonance', 6);
INSERT INTO `words` VALUES (11087, 'The final movement, a robust and often dissonant fugue, is a precursor to Beethoven’s startling, gritty “Grosse Fuge,” composed as the final movement of his Opus 130 String Quartet.', 'adj. 不谐和的, 不调和的, 刺耳的', '/\'disənənt | \'dɪs(ə)nənt | \'dɪsənənt/', 'dissonant', 6);
INSERT INTO `words` VALUES (11088, 'Doctors had tried to dissuade patients from smoking.', 'v. 劝阻', '/di\'sweid | dɪ\'sweɪd | dɪ\'swed/', 'dissuade', 6);
INSERT INTO `words` VALUES (11089, NULL, 'v. 贬损， 伤害名誉', '/dɪs\'teɪn/', 'distain', 6);
INSERT INTO `words` VALUES (11090, 'the sound of distant gunfire', 'adj. 疏远的， 冷淡的', '/\'dɪstənt/', 'distant', 6);
INSERT INTO `words` VALUES (11091, 'She looked at his shabby clothes with distaste.', 'v. 厌恶; n. 厌恶， 不喜欢', '/dɪs\'teɪst | dɪs\'test/', 'distaste', 6);
INSERT INTO `words` VALUES (11092, 'What follows is John’s story. Parts of it may seem distasteful, even shocking.', 'adj. 不愉快的， 讨厌的', '/dɪs\'teɪstfl | dɪs\'testfl/', 'distasteful', 6);
INSERT INTO `words` VALUES (11093, 'Blood vessels in the lungs are filled and distend. Capillary changes have been observed in the animal model of simulated microgravity.', 'v. (使)扩大, (使)扩张', '/dis\'tend | dɪ\'stend | dɪ\'stɛnd/', 'distend', 6);
INSERT INTO `words` VALUES (11094, NULL, 'n. 膨胀, 延伸', '/dis\'tenʃən | dɪ\'stɛnʃən/', 'distension', 6);
INSERT INTO `words` VALUES (11095, 'The distent balloon exploded at last.', 'adj. 膨胀的； 扩张的', '/dɪs\'tent | dis\'tent/', 'distent', 6);
INSERT INTO `words` VALUES (11096, NULL, 'n. 蒸馏, 蒸馏法, 蒸馏物, 精华, 精髓', '/,dɪstɪ\'leɪʃn | ,dɪstl\'eʃən/', 'distillation', 6);
INSERT INTO `words` VALUES (11097, 'two entirely distinct languages', 'adj. 清楚的， 明显的', '/dɪ\'stɪŋkt/', 'distinct', 6);
INSERT INTO `words` VALUES (11098, 'There are obvious distinctions between the two wine-making areas.', 'n. 区别, 差别, 级别, 特性, 声望, 显赫', '/dis\'tiŋkʃən | dɪ\'stɪŋ(k)ʃ(ə)n | dɪ\'stɪŋkʃən/', 'distinction', 6);
INSERT INTO `words` VALUES (11099, 'a rock band with a distinctive sound', 'adj. 出众的， 有特色的', '/dɪ\'stɪŋktɪv/', 'distinctive', 6);
INSERT INTO `words` VALUES (11100, 'The light was too dim for me to distinguish anything clearly.', 'v. 成为…的特征， 使有别于； 把…分类； 区别， 辨别', '/dɪ\'stɪŋgwɪʃ | dɪ\'stɪŋɡwɪʃ/', 'distinguish', 6);
INSERT INTO `words` VALUES (11101, 'a long and distinguished career', 'adj. 卓著的, 著名的, 高贵的', '/dis\'tiŋɡwiʃt | dɪ\'stɪŋgwɪʃt/', 'distinguished', 6);
INSERT INTO `words` VALUES (11102, 'His account was badly distorted by the press.', 'v. 扭曲， 弄歪', '/dɪ\'stɔːrt | dɪ\'stɔrt/', 'distort', 6);
INSERT INTO `words` VALUES (11103, 'I think it would be a gross distortion of reality to say that they were motivated by self-interest.', 'n. 扭曲； 曲解', '/dɪ\'stɔːrʃn | dɪs\'tɔrʃən/', 'distortion', 6);
INSERT INTO `words` VALUES (11104, 'She had seemed curiously distracted.', 'adj. 心烦意乱的', '/dis\'træktid | dɪ\'stræktɪd/', 'distracted', 6);
INSERT INTO `words` VALUES (11105, 'The distrait actress fluffed her lines.', 'adj. 心不在焉的', '/dɪ\'stre | di:s\'tre/', 'distrait', 6);
INSERT INTO `words` VALUES (11106, 'If you see a guy looking distraught while comparing the active ingredients of various toothpastes, look again. That might be me.', 'adj. 发狂的', '/dis\'trɔ:t | dɪ\'strɔːt | dɪ\'strɔt/', 'distraught', 6);
INSERT INTO `words` VALUES (11107, 'Luke’s behaviour caused his parents great distress.', 'n. 悲痛, 穷困, 不幸, 危难, 忧伤', '/di\'stres | dɪ\'stres | dɪ\'strɛs/', 'distress', 6);
INSERT INTO `words` VALUES (11108, 'It is very distressing to see your baby attached to tubes and monitors.', 'adj. 悲伤的, 使痛苦的, 使烦恼的', '/di\'stresiŋ | dɪ\'stresɪŋ | dɪ\'strɛsɪŋ/', 'distressing', 6);
INSERT INTO `words` VALUES (11109, 'a man distributing leaflets to passers-by', 'v. 分发， 分配', '/dɪ\'strɪbjuːt | dɪ\'strɪbjut/', 'distribute', 6);
INSERT INTO `words` VALUES (11110, 'a postal district', 'n. 地区； 行政区； 区域', '/\'dɪstrɪkt/', 'district', 6);
INSERT INTO `words` VALUES (11111, 'There were disturbances in the crowd as fans left the stadium.', 'n. 骚动, 动乱, 打扰, 干扰, 骚乱, 搅动', '/di\'stə:bəns | dɪ\'stɜːb(ə)ns | dɪ\'stɝbəns/', 'disturbance', 6);
INSERT INTO `words` VALUES (11112, 'Yes, you can still find some photographers who dither on about grain in a photo, but they probably haven\'t dusted their specs in years.', 'n. 发抖', '/\'diðə | \'dɪðə | \'dɪðɚ/', 'dither', 6);
INSERT INTO `words` VALUES (11113, 'Kangaroos are diurnal animals.', 'adj. 每日的, 一日间的, 白天的', '/dai\'ə:nəl | daɪ\'ɜːn(ə)l | daɪ\'ɝnl/', 'diurnal', 6);
INSERT INTO `words` VALUES (11114, 'Solved the problems of the divagate teachers and the unfit teachers.', 'v. 流浪, 漫游,离题', '/\'daivəɡeit | \'daɪvəgeɪt/', 'divagate', 6);
INSERT INTO `words` VALUES (11115, 'At this location the two roads divaricate.', 'v. 分为两叉', '/dai\'værikit, -keit, dai\'værikeit | daɪ\'værɪkeɪt; dɪ- | daɪ\'værɪket/', 'divaricate', 6);
INSERT INTO `words` VALUES (11116, 'His interests increasingly diverged from those of his colleagues.', 'v. (道路等)分叉, (意见等)分歧, 脱离', '/dai\'və:dʒ, di- | daɪ\'vɜːdʒ; dɪ- | daɪ\'vɝdʒ/', 'diverge', 6);
INSERT INTO `words` VALUES (11117, 'There\'s a substantial divergence of opinion within the party.', 'n. 分歧', '/dai\'və:dʒəns, di- | daɪ\'vɜːdʒ(ə)ns | dəˈvɜrdʒəns; daɪˈvɜrdʒəns/', 'divergence', 6);
INSERT INTO `words` VALUES (11118, 'Two people who have divergent views on this question are George Watt and Bob Marr.', 'adj. 分叉的， 叉开的； 发散的， 扩散的； 不同的', '/daɪ\'vɜːrdʒənt | daɪ\'vɝdʒənt/', 'divergent', 6);
INSERT INTO `words` VALUES (11119, 'Albert Jones\' new style will inevitably put him in touch with a much more diverse and perhaps younger audience.', 'adj. 不同的, 变化多的', '/dai\'və:s, di- | daɪ\'vɜːs; \'daɪvɜːs | daɪ\'vɝs/', 'diverse', 6);
INSERT INTO `words` VALUES (11120, 'We need to diversify the economy.', 'v. 多样化', '/daɪ\'vɜːrsɪfaɪ | daɪˈvɜrsəˌfaɪ/', 'diversify', 6);
INSERT INTO `words` VALUES (11121, '...the cultural diversity of Latin America.', 'n. 差异, 多样性', '/dai\'və:səti | daɪ\'vɜːsɪtɪ; dɪ- | dɪˈvəsɪti/', 'diversity', 6);
INSERT INTO `words` VALUES (11122, 'Remember to divert your phone when you are out of the office.', 'v. 转移， 转向； 使娱乐', '/daɪ\'vɜːrt | dɪˈvɚt/', 'divert', 6);
INSERT INTO `words` VALUES (11123, '...in the 1960s, when sexual love had been divested of sin.', 'v. 剥夺', '/dai\'vest, di- | daɪ\'vest; dɪ- | daɪ\'vɛst/', 'divest', 6);
INSERT INTO `words` VALUES (11124, NULL, 'n. (头衔,财产权利等的)剥夺, 脱衣', '/dai\'vestitʃə, di- | daɪ\'vestɪtʃə; dɪ- | dɪ\'vɛstɪtʃɚ/', 'divestiture', 6);
