INSERT INTO `words` VALUES (11128, 'The strike was a divisive issue in the community.', 'adj. 引起分歧的， 导致分裂的', '/dɪ\'vaɪsɪv | di\'vaisiv/', 'divisive', 6);
INSERT INTO `words` VALUES (11129, 'Officials refuse to divulge details of the negotiations.', 'v. 泄露, 暴露', '/dai\'vʌldʒ, di- | daɪ\'vʌldʒ; dɪ- | dɪ\'vʌldʒ/', 'divulge', 6);
INSERT INTO `words` VALUES (11130, 'We’ve got to think first whether this plan is doable.', 'adj. 可做的, 可行的', '/\'du:əbl | \'duːəb(ə)l | \'duəbl/', 'doable', 6);
INSERT INTO `words` VALUES (11131, 'Labradors are gentle, docile dogs.', 'adj. 驯服的， 听话的 easy to control)', '/\'dɑːsl | ˈdoʊˌsaɪl/', 'docile', 6);
INSERT INTO `words` VALUES (11132, 'A crowd was waiting at the dock to greet them.', 'n. <美> 码头, 船坞, 被告席, 尾巴的骨肉部分', '/dɔk | dɒk | dɑk/', 'dock', 6);
