INSERT INTO `words` VALUES (11135, 'She produces legal documents for a downtown Seattle law firm.', 'v. 为…提供书面证明; n. 文件', '/\'dɒkjʊm(ə)nt | dɑkjəmənt/', 'document', 6);
INSERT INTO `words` VALUES (11136, 'The exam was a doddle!', 'n. 轻而易举的事；不费吹灰之力的事', '/\'dɔdl | \'dɑdl/', 'doddle', 6);
