INSERT INTO `words` VALUES (11140, '...fragments of meaningless doggerel.', 'n. 打油诗', '/\'dɔɡərəl | \'dɒg(ə)r(ə)l/', 'doggerel', 6);
INSERT INTO `words` VALUES (11141, 'Their political dogma has blinded them to the real needs of the country.', 'n. 教条， 信条', '/\'dɔːgmə | \'dɔɡmə/', 'dogma', 6);
INSERT INTO `words` VALUES (11142, 'Her staff find her bossy and dogmatic.', 'adj. 教条的, 独断的', '/dɔɡ\'mætik,-kəl | dɒg\'mætɪk | dɔɡ\'mætɪk/', 'dogmatic', 6);
INSERT INTO `words` VALUES (11143, 'We cannot allow dogmatism to stand in the way of progress.', 'n. 教条主义， 武断 being dogmatic)', '/\'dɔːgmətɪzəm | \'dɔɡmətɪzəm/', 'dogmatism', 6);
