INSERT INTO `words` VALUES (11148, 'They had heard so very little of this; yet it was enough to build up wretched dolorous dreams upon, there in the shade of the night.', 'adj. 忧伤的, 悲痛的', '/\'dɔlərəs | \'dɒl(ə)rəs | \'dolərəs/', 'dolorous', 6);
