INSERT INTO `words` VALUES (11156, 'The dominant male gorilla is the largest in the group.', 'adj. 支配的； 占优势的', '/\'dɑːmɪnənt | \'dɑmɪnənt/', 'dominant', 6);
INSERT INTO `words` VALUES (11157, 'The industry is dominated by five multinational companies.', 'v. 控制， 支配', '/\'dɑːmɪneɪt | \'dɑmɪnet/', 'dominate', 6);
