INSERT INTO `words` VALUES (11166, 'a huge dormant volcano', 'adj. 睡眠状态的, 静止的, 隐匿的', '/\'dɔ:mənt | \'dɔːm(ə)nt | \'dɔrmənt/', 'dormant', 6);
