INSERT INTO `words` VALUES (11238, 'Malcolm believed he was guilty of duplicity in his private dealings.', 'n. 奸诈, 狡猾, 搞两面派, 口是心非, 不诚实, 表里不一', '/dju:\'plisəti | djuː\'plɪsɪtɪ; djʊ- | du\'plɪsəti/', 'duplicity', 6);
INSERT INTO `words` VALUES (11239, 'Wood is a durable material.', 'adj. 持久的； 耐用的', '/\'durəbl | \'dʊrəbl/', 'durable', 6);
INSERT INTO `words` VALUES (11240, 'The course is of three years’ duration.', 'n. 持续时间, 为期', '/djʊ\'reɪʃ(ə)n | du\'reʃən/', 'duration', 6);
INSERT INTO `words` VALUES (11241, 'He thought her confession had been made under duress.', 'n. 强迫, 监禁', '/djuə\'res | djʊ(ə)\'res; \'djʊəres | du\'rɛs/', 'duress', 6);
