INSERT INTO `words` VALUES (11243, 'He might have been called the invulnerable dwarf of the fray.', 'n. 矮子, 侏儒', '/dwɔ:f | dwɔːf | dwɔrf/', 'dwarf', 6);
INSERT INTO `words` VALUES (11244, 'The elephant population is dwindling.', 'v. 缩小', '/\'dwindl | \'dwɪnd(ə)l | \'dwɪndl/', 'dwindle', 6);
