INSERT INTO `words` VALUES (11248, 'dysfunctional family relationships', 'adj. 功能失调的', '/dɪs\'fʌŋkʃənl | dɪsˈfʌŋkʃənl/', 'dysfunctional', 6);
INSERT INTO `words` VALUES (11249, 'Some children with dyslexia might only have one of these symptoms.', 'n. [医] 诵读困难', '/dis\'leksiə | dɪs\'leksɪə | dɪs\'lɛksɪə/', 'dyslexia', 6);
INSERT INTO `words` VALUES (11250, NULL, 'adj. 责难的', '/,dislə\'dʒistik | ,dɪslə\'dʒɪstɪk/', 'dyslogistic', 6);
INSERT INTO `words` VALUES (11251, 'Finally, it is possible that your symptoms may be caused by functional dyspepsia.', 'n. [医]消化不良, 胃弱', '/dis\'pepsiə | dɪs\'pepsɪə | dɪs\'pɛpʃə/', 'dyspepsia', 6);
INSERT INTO `words` VALUES (11252, NULL, 'adj. 消化不良的； 不高兴的', '/dɪs\'peptɪk | dis\'peptik,-kəl/', 'dyspeptic', 6);
INSERT INTO `words` VALUES (11253, '\"Temperdysregulation with dysphoria\" is the work group\'s proposed solution.', 'n. 烦躁不安', '/dis\'fɔ:riə | dɪs\'fɔːrɪə | dɪs\'fɔrɪə/', 'dysphoria', 6);
INSERT INTO `words` VALUES (11254, 'There\'s a time when eaglet becomes lanneret , you can buy it anon .', 'n. 小鹰', '/\'iːglət/', 'eaglet', 6);
INSERT INTO `words` VALUES (11255, 'a rather earnest young man', 'adj. 诚挚的， 认真的', '/\'ɜːrnɪst/', 'earnest', 6);
INSERT INTO `words` VALUES (11256, '...a pair of diamond earrings.', 'n. 耳环, 耳饰', '/\'iəriŋ | \'ɪərɪŋ | \'ɪrɪŋ/', 'earring', 6);
INSERT INTO `words` VALUES (11257, NULL, 'n. 土质， 土性', '/\'ɜːrθinəs | \'ə:θi:nis/', 'earthiness', 6);
INSERT INTO `words` VALUES (11258, NULL, 'adj. 极其重大或重要的', '/\'ɜːrθˌʃeɪkɪŋ | \'ɝθʃekɪŋ/', 'earthshaking', 6);
INSERT INTO `words` VALUES (11259, 'earthy colours', 'adj. 粗俗的， 土气的', '/\'ɜːrθi | \'ɝθi/', 'earthy', 6);
INSERT INTO `words` VALUES (11260, 'In this room you can also find Aleksandr’s easel and palettes.', 'n. 画架, 黑板架', '/\'i:zəl | \'iːz(ə)l | \'izl/', 'easel', 6);
INSERT INTO `words` VALUES (11261, 'Birds had nested under the eaves.', 'n. 屋檐', '/i:vz | iːvz | ivz/', 'eaves', 6);
INSERT INTO `words` VALUES (11262, 'There was Helena eavesdropping outside the door.', 'v. 偷听', '/\'i:vzdrɔp | \'iːvzdrɒp | \'ivzdrɑp/', 'eavesdrop', 6);
INSERT INTO `words` VALUES (11263, 'His confidence is at a low ebb.', 'n. 退, 弱, 退潮, 衰落', '/eb | ɛb/', 'ebb', 6);
