INSERT INTO `words` VALUES (11265, '...the ebullient Russian president.', 'adj. 冒泡的, 沸腾的, 热情的, 热情洋溢的', '/i\'bʌljənt | ɪ\'bʌljənt; -\'bʊl- | ɪ\'bʌlɪənt/', 'ebullient', 6);
INSERT INTO `words` VALUES (11266, NULL, 'adj. 似象牙般坚硬结实的', NULL, 'eburnated', 6);
INSERT INTO `words` VALUES (11267, 'His eccentric behaviour lost him his job.', 'adj. 古怪', '/ik\'sentrik | ɪk\'sentrɪk; ek- | ɪk\'sɛntrɪk/', 'eccentric', 6);
INSERT INTO `words` VALUES (11268, 'She is unusual to the point of eccentricity.', 'n. 偏心, 古怪, [数]离心率', '/,eksen\'trisəti | ,eksen\'trɪsɪtɪ | ,ɛksɛn\'trɪsəti/', 'eccentricity', 6);
INSERT INTO `words` VALUES (11269, 'The process of toads ecdysis was reported, and the significance of environmental protection and the commercialization of bufonic was discussed.', 'n. [动]蜕皮, 蜕化', '/\'ekdisis | \'ekdɪsɪs; ek\'daɪsɪs | \'ɛkdɪsɪs/', 'ecdysis', 6);
INSERT INTO `words` VALUES (11270, 'Their clients are drawn from the highest echelons of society.', 'n. [军]梯形, 梯阵, 梯次编队', '/\'eʃəlɔn | \'eʃəlɒn; \'eɪʃ- | \'ɛʃəlɑn/', 'echelon', 6);
INSERT INTO `words` VALUES (11271, 'The sound of an engine echoed back from the thick forest.', 'v. 回响， 回荡； 重复， 模仿; n. 回声；反响；共鸣', '/\'ekou | \'ɛko/', 'echo', 6);
INSERT INTO `words` VALUES (11272, 'galleries with an eclectic range of styles and artists', 'adj. 折衷的, 折衷学派的', '/ɪ\'klektɪk | ɪ\'klɛktɪk/', 'eclectic', 6);
INSERT INTO `words` VALUES (11273, '...her cultural eclecticism.', 'n. 折衷主义, 折衷主义的运动', '/e\'klektisizəm | ɪˈklektɪsɪzəm/', 'eclecticism', 6);
INSERT INTO `words` VALUES (11274, 'an eclipse of the sun', 'n. 食, 日蚀, 月蚀, 蒙蔽, 衰落', '/i\'klips | ɪ\'klɪps/', 'eclipse', 6);
INSERT INTO `words` VALUES (11275, NULL, 'n. 牧歌, 田园诗', '/\'eklɔɡ | \'eklɒg/', 'eclogue', 6);
INSERT INTO `words` VALUES (11276, 'an ecological disaster', 'adj. 生态的； 生态学的', '/ˌiːkə\'lɑːdʒɪkl | \'ikə\'lɑdʒɪkl/', 'ecological', 6);
INSERT INTO `words` VALUES (11277, 'We\'re going to have to economize from now on.', 'v. 节约, 节省, 有效地利用', '/i\'kɔnəmaiz | ɪ\'kɒnə\'maɪz | ɪ\'kɑnə\'maɪz/', 'economize', 6);
INSERT INTO `words` VALUES (11278, '...the limitations that come with economy travel.', 'adj. 经济的; n. 节约；经济', '/ɪ\'kɑːnəmi | ɪˈkɑnəmɪ/', 'economy', 6);
INSERT INTO `words` VALUES (11279, 'Achieving this moment of ecstasy easily validates all the pain and struggle of the art form by taking us (and possibly our audience) for a moment to a world beyond our own.', 'n. 入迷', '/\'ekstəsi | \'ekstəsɪ | \'ɛkstəsi/', 'ecstasy', 6);
INSERT INTO `words` VALUES (11280, 'And then an ecstatic scream of joy; and then , alas !', 'n. 狂喜的人', '/ik\'stætik | ɪk\'stætɪk; ek- | ɪk\'stætɪk/', 'ecstatic', 6);
INSERT INTO `words` VALUES (11281, NULL, 'n. 复制品, 副本', '/\'ektaɪp | \'ektaip/', 'ectype', 6);
INSERT INTO `words` VALUES (11282, '\"The colonnade is a highly allegorical artistic representation of an ecumenical embrace of the universal Church to all people, \" said the Vatican newspaper.', 'adj. 一般的, 普通的', '/,i:kju:\'menikəl, ,ekju-,-ik | ,iːkjʊ\'menɪk(ə)l; ek- | ,ikju\'mɛnɪkl/', 'ecumenical', 6);
INSERT INTO `words` VALUES (11283, 'The racing river caused swirling eddies.', 'n. 旋转, 漩涡', '/\'edi | \'edɪ | \'ɛdi/', 'eddy', 6);
INSERT INTO `words` VALUES (11284, 'Conclusion: The collapsible complete denture can restore the edentulous of the patient with microstomia.', 'adj. 缺齿的', '/i:\'dentʃuləs | ɪ\'dentjʊləs/', 'edentulous', 6);
INSERT INTO `words` VALUES (11285, 'She was nervous and edgy, still chain-smoking.', 'adj. 急躁的， 易怒的； 尖利的， 锐利的', '/\'edʒi | \'ɛdʒi/', 'edgy', 6);
INSERT INTO `words` VALUES (11286, 'The emperor issued an edict forbidding anyone to leave the city.', 'n. 布告, 法令', '/\'i:dikt | \'iːdɪkt | \'idɪkt/', 'edict', 6);
INSERT INTO `words` VALUES (11287, 'Demonstrations, films, and videotapes are shown for your edification.', 'n. (尤指道德或精神方面的)教诲, 启迪, 熏陶', '/,edifi\'keiʃən | ,edɪfɪ\'keɪʃ(ə)n | ,ɛdɪfɪ\'keʃən/', 'edification', 6);
INSERT INTO `words` VALUES (11288, 'Their head office was an imposing edifice.', 'n. 大厦, 大建筑物', '/\'edifis | \'edɪfɪs | \'ɛdɪfɪs/', 'edifice', 6);
INSERT INTO `words` VALUES (11289, 'If you study my project, it might edify your mind.', 'v. 启发', '/\'edifai | \'edɪfaɪ/', 'edify', 6);
INSERT INTO `words` VALUES (11290, 'the eerie sound of an owl hooting at night', 'adj. 怪诞的, 可怕的, 不安的, 奇异的', '/\'iəri | \'ɪərɪ/', 'eerie', 6);
INSERT INTO `words` VALUES (11291, 'Nothing can efface the last picture I have of them from my mind.', 'v. 抹掉', '/i\'feis | ɪ\'feɪs | ɪ\'fes/', 'efface', 6);
INSERT INTO `words` VALUES (11292, 'The cheaper drugs are just as effective in treating arthritis.', 'adj. 有效的， 生效的； 给人印象深刻的', '/ɪ\'fektɪv | ɪ\'fɛktɪv/', 'effective', 6);
