INSERT INTO `words` VALUES (11294, NULL, 'v. 冒泡, [化]泡腾, 兴奋', '/,efə\'ves/', 'effervesce', 6);
INSERT INTO `words` VALUES (11295, 'He wrote about Gillespie\'s effervescence, magnetism and commitment.', 'n. 冒泡； 活泼', '/ˌefər\'vesns/', 'effervescence', 6);
