INSERT INTO `words` VALUES (11297, 'an equally efficacious method of treatment', 'adj. 有效的', '/ˌefɪ\'keɪʃəs | ,efi\'keiʃəs/', 'efficacious', 6);
INSERT INTO `words` VALUES (11298, 'Recent medical studies confirm the efficacy of a healthier lifestyle.', 'n. 功效， 有效性', '/\'efɪkəsi | \'ɛfɪkəsi/', 'efficacy', 6);
INSERT INTO `words` VALUES (11299, 'a threat to burn the president in effigy', 'n. (被憎恨或蔑视的人的)肖像, 雕像', '/\'efidʒi | \'efɪdʒɪ | \'ɛfɪdʒi/', 'effigy', 6);
INSERT INTO `words` VALUES (11300, 'Alexei rose to his feet with a single effortless movement.', 'adj. 容易的, 不费力气的', '/\'efətlis | \'efətlɪs | \'ɛfɚtləs/', 'effortless', 6);
INSERT INTO `words` VALUES (11301, 'The man had the effrontery to be sarcastic.', 'n. 厚颜无耻, 厚颜无耻的行为', '/i\'frʌntəri | ɪ\'frʌnt(ə)rɪ | ɪ\'frʌntrɪ/', 'effrontery', 6);
INSERT INTO `words` VALUES (11302, 'Trust us! Work together, We\'ll be effulgence in the future path of cooperation.', 'n. 光辉, 灿烂', '/i\'fʌldʒəns | ɪ\'fʌldʒəns/', 'effulgence', 6);
INSERT INTO `words` VALUES (11303, 'Start from me, from now on, I think in the future of the Olympic Games, I will be able to get a real gold, realize I effulgent dream!', 'adj. 光辉灿烂的', '/i\'fʌldʒənt/', 'effulgent', 6);
INSERT INTO `words` VALUES (11304, 'Our host gave us an effusive welcome.', 'adj. 感情横溢的, 流出的', '/i\'fju:siv | ɪ\'fjuːsɪv | ɪ\'fjusɪv/', 'effusive', 6);
INSERT INTO `words` VALUES (11305, 'an egalitarian society', 'adj. 平等主义的', '/i,ɡæli\'tεəriən | ɪ,gælɪ\'teərɪən | ɪ\'gælə\'tɛrɪən/', 'egalitarian', 6);
INSERT INTO `words` VALUES (11306, 'Conclusion:The hypolipidemic mechanism of Yaobao Xuezhiqing capsules is related lowering LDL-C in blood-serum and increasing TC egest with excrement.', 'v. 排泄', '/i:\'dʒest | ɪ\'dʒest/', 'egest', 6);
INSERT INTO `words` VALUES (11307, 'Spinach and eggplant.', 'n. 茄子', '/\'eɡplɑ:nt,-plænt | \'egplɑːnt | \'ɛɡplænt/', 'eggplant', 6);
INSERT INTO `words` VALUES (11308, 'He was egocentric, a man of impulse who expected those around him to serve him.', 'adj. 自我中心的, 利己主义的', '/,i:ɡəu\'sentrik, ,eɡ- | ,egə(ʊ)\'sentrɪk; iː- | ,iɡo\'sɛntrɪk/', 'egocentric', 6);
INSERT INTO `words` VALUES (11309, 'They seemed to love the land and the people with a sort of fierce egoism.', 'n. 利己主义', '/\'egouɪzəm | \'ɛɡoɪzəm/', 'egoism', 6);
INSERT INTO `words` VALUES (11310, 'I never thought of myself as a bastard, an egoist .', 'n. 自我主义者', '/\'iːgouɪst | \'iɡoɪst/', 'egoist', 6);
INSERT INTO `words` VALUES (11311, 'They are busy carrying food, but the ant colony and egoistic.', 'adj. 自我中心的， 自私自利的', '/ˌegou\'ɪstɪk(l)/', 'egoistic', 6);
