INSERT INTO `words` VALUES (11313, NULL, 'n. 自私自利者； 自我主义者', '/\'egətɪst/', 'egotist', 6);
INSERT INTO `words` VALUES (11314, '...the most egregious abuses of human rights.', 'adj. 异乎寻常的, 过分的, 惊人的', '/i\'ɡri:dʒiəs | ɪ\'griːdʒəs | ɪ\'gridʒɪəs/', 'egregious', 6);
INSERT INTO `words` VALUES (11315, 'Traditionally, the physical infrastructure providers control the underlying hardware; they provide the cloud tenant with egress and ingress at the most fundamental level.', 'n. 出口, 外出', '/\'i:ɡres | \'iːgres | \'iɡrɛs/', 'egress', 6);
INSERT INTO `words` VALUES (11316, 'Your eidetic memory must be a blessing.', 'adj. (头脑中的印象)异常清晰的', '/ai\'detik | aɪ\'detɪk | aɪ\'dɛtɪk/', 'eidetic', 6);
INSERT INTO `words` VALUES (11317, '...a tendency to ejaculate quickly.', 'v. 突然说出, (从生物体中)射出', '/i\'dʒækjuleit, i\'dʒækjulət, -leit | ɪ\'dʒækjʊleɪt | ɪ\'dʒækjulet/', 'ejaculate', 6);
INSERT INTO `words` VALUES (11318, NULL, 'n. 突然说出, 射精, 射出', '/i,dʒækju\'leiʃən | ɪ,dʒækjʊ\'leɪʃ(ə)n | ɪ\'dʒækjʊ\'leʃən/', 'ejaculation', 6);
INSERT INTO `words` VALUES (11319, 'Two engines cut out and the plane started to eject fuel as it lost height.', 'v. 逐出, 撵出, 驱逐, 喷射', '/i\'dʒekt, \'i:dʒekt | ɪ\'dʒekt | ɪ\'dʒɛkt/', 'eject', 6);
INSERT INTO `words` VALUES (11320, 'pure silks embroidered with elaborate patterns', 'adj. 精心制作的, 详细阐述的, 精细', '/i\'læbərət, i\'læbəreit | ɪ\'læb(ə)rət | ɪ\'læbəret/', 'elaborate', 6);
INSERT INTO `words` VALUES (11321, NULL, 'n. 苦心经营, 苦心经营的结果, 详尽的细节', '/i,læbə\'reiʃən | ɪ,læbə\'reɪʃən | ɪ,læbə\'reʃən/', 'elaboration', 6);
INSERT INTO `words` VALUES (11322, 'Several months elapsed before his case was brought to trial.', 'v. (时间)过去, 消逝', '/i\'læps | ɪ\'læps/', 'elapse', 6);
INSERT INTO `words` VALUES (11323, 'an elastic cord', 'adj. 弹性的', '/i\'læstik | ɪ\'læstɪk/', 'elastic', 6);
INSERT INTO `words` VALUES (11324, 'the skin’s natural elasticity', 'n. 弹力, 弹性', '/,elæs\'tisəti | elæ\'stɪsɪtɪ; iː-; ɪ- | ,ilæ\'stɪsəti/', 'elasticity', 6);
INSERT INTO `words` VALUES (11325, NULL, 'v. 使高兴， 使得意', '/i\'leɪt | i\'leit/', 'elate', 6);
INSERT INTO `words` VALUES (11326, 'He felt elated and mildly drunk.', 'adj. 兴高采烈的, 得意洋洋', '/i\'leitid | ɪ\'leɪtɪd | ɪ\'letɪd/', 'elated', 6);
INSERT INTO `words` VALUES (11327, 'His supporters have reacted to the news with elation.', 'n. 得意洋洋, 兴高采烈', '/i\'leiʃən | ɪ\'leɪʃ(ə)n | ɪ\'leʃən/', 'elation', 6);
INSERT INTO `words` VALUES (11328, 'A majority of the electorate oppose the law.', 'n. 选民, 选区, 有选举权者', '/i\'lektərət | ɪ\'lekt(ə)rət | ɪ\'lɛktərət/', 'electorate', 6);
INSERT INTO `words` VALUES (11329, 'Last week a housewife was electrocuted by her washing machine.', 'v. <美>处电刑, 触电致死', '/i\'lektrəkju:t | ɪ\'lektrəkjuːt | ɪ\'lɛktrəkjut/', 'electrocute', 6);
INSERT INTO `words` VALUES (11330, 'electromagnetic waves', 'adj. 电磁的', '/ɪˌlektroumæg\'netɪk | ɪ,lɛktromæɡ\'nɛtɪk/', 'electromagnetic', 6);
INSERT INTO `words` VALUES (11331, 'He spoke of her in elegiac tones.', 'adj. 哀歌的，挽歌的; n. 哀歌， 挽歌', '/ˌelɪ\'dʒaɪək | ,eli\'dʒaiək/', 'elegiac', 6);
INSERT INTO `words` VALUES (11332, '...a touching elegy for a lost friend.', 'n. 悲歌, 挽歌', '/\'elidʒi | \'elɪdʒɪ | \'ɛlədʒi/', 'elegy', 6);
INSERT INTO `words` VALUES (11333, 'I’m only familiar with the subject at an elementary level.', 'adj. 初级的', '/ˌelɪ\'mentri | ,ɛlɪ\'mɛntri/', 'elementary', 6);
INSERT INTO `words` VALUES (11334, 'elephantine footsteps', 'adj. 象的, 粗笨的, 巨大的', '/,eli\'fæntain, -tin | elɪ\'fæntaɪn/', 'elephantine', 6);
INSERT INTO `words` VALUES (11335, 'Language has elevated humans above the other animals.', 'v. 举起； 提升', '/\'elɪveɪt | \'ɛlɪvet/', 'elevate', 6);
INSERT INTO `words` VALUES (11336, NULL, 'n. 小精灵, 矮人, 淘气鬼, 恶作剧的人, 恶人', '/elf | ɛlf/', 'elf', 6);
INSERT INTO `words` VALUES (11337, 'Mr. Norris said he was hopeful that his request would elicit a positive response.', 'v. 得出, 引出, 抽出, 引起', '/i\'lisit | ɪ\'lɪsɪt/', 'elicit', 6);
