INSERT INTO `words` VALUES (11339, 'Most English speakers elide the first ‘d’ in ‘Wednesday.’', 'v. 取消, 省略, 省略发音, 不予考虑删节', '/i\'laid | ɪ\'laɪd/', 'elide', 6);
INSERT INTO `words` VALUES (11340, 'Stephen was regarded as an eligible bachelor.', 'adj. 符合条件的, 合格的', '/\'elidʒəbl | \'elɪdʒɪb(ə)l | \'ɛlɪdʒəbl/', 'eligible', 6);
INSERT INTO `words` VALUES (11341, 'a ruthless dictator who eliminated all his rivals', 'v. 排除, 消除', '/i\'limineit | ɪ\'lɪmɪneɪt | ɪ\'lɪmɪnet/', 'eliminate', 6);
INSERT INTO `words` VALUES (11342, '...a government comprised mainly of the elite.', 'n. <法>[集合名词]精华, 精锐, 中坚分子', '/ei\'li:t, i\'li:t | [eɪˈliːt] | ɪˈliːt/', 'elite', 6);
INSERT INTO `words` VALUES (11343, NULL, 'n. 杰出人物统治论, 高人一等的优越感', '/ei\'li:tizəm, i\'- | eɪ\'liːtɪz(ə)m; ɪ- | e\'litɪzəm/', 'elitism', 6);
INSERT INTO `words` VALUES (11344, 'the search for the elixir of life', 'n. 炼金药, 不老长寿药, 万能药, [药]西也剂', '/i\'liksə | ɪ\'lɪksə; -sɪə | ɪ\'lɪksɚ/', 'elixir', 6);
INSERT INTO `words` VALUES (11345, 'The Earth orbits in an ellipse.', 'n. [数]椭圆, 椭圆形', '/i\'lips | ɪ\'lɪps/', 'ellipse', 6);
INSERT INTO `words` VALUES (11346, 'You no doubt noticed the ellipsis in the code above.', 'n. 省略, 省略符号', '/i\'lipsis | ɪ\'lɪpsɪs/', 'ellipsis', 6);
INSERT INTO `words` VALUES (11347, 'Kepler published his discovery of the elliptical orbits of planets in 1609. 1609', 'adj. 椭圆的； 晦涩的； 省略的', '/ɪ\'lɪptɪkl/', 'elliptical', 6);
INSERT INTO `words` VALUES (11348, 'It was a good table too, sturdily constructed of elm.', 'n. [植]榆树', '/elm | ɛlm/', 'elm', 6);
INSERT INTO `words` VALUES (11349, 'When I was 11 my mother sent me to elocution lessons.', 'n. 雄辩术, 演说法', '/,elə\'kju:ʃən | ,elə\'kjuːʃ(ə)n | ,ɛlə\'kjuʃən/', 'elocution', 6);
INSERT INTO `words` VALUES (11350, 'Her legs were elongated by the very high heels which she wore.', 'v. 拉长, (使)伸长, 延长', '/\'i:lɔŋɡeit, i\'lɔŋ- | \'iːlɒŋgeɪt | ɪ\'lɔŋɡet/', 'elongate', 6);
INSERT INTO `words` VALUES (11351, 'You must be auxin, cause you are causing me to have rapid stem elongation.', 'n. 延长', '/,i:lɔŋ\'ɡeiʃən, i,lɔŋ- | iːlɒŋ\'geɪʃ(ə)n | ɪ,lɔŋ\'ɡeʃən/', 'elongation', 6);
INSERT INTO `words` VALUES (11352, 'My parents didn’t approve of the marriage, so we eloped.', 'v. 私奔, 潜逃, 出走', '/i\'ləup | ɪ\'ləʊp | ɪ\'lop/', 'elope', 6);
INSERT INTO `words` VALUES (11353, 'He carried his audience along with his eloquence.', 'n. 雄辩, 口才, 修辞', '/\'eləkwəns | \'ɛləkwəns/', 'eloquence', 6);
INSERT INTO `words` VALUES (11354, 'an eloquent appeal for support', 'adj. 雄辩的, 有口才的, 动人的, 意味深长的', '/\'eləkwənt | \'ɛləkwənt/', 'eloquent', 6);
INSERT INTO `words` VALUES (11355, 'The full picture has not yet been elucidated.', 'v. 阐明, 说明', '/i\'lu:si,deit | ɪ\'l(j)uːsɪdeɪt | ɪ\'lusɪdet/', 'elucidate', 6);
INSERT INTO `words` VALUES (11356, 'He eluded his pursuers by escaping into a river.', 'v. 躲避', '/i\'lju:d | ɪ\'l(j)uːd | ɪ\'lud/', 'elude', 6);
INSERT INTO `words` VALUES (11357, 'She enjoys a firm reputation in this country but wider international success has been elusive.', 'adj. 难懂的, 难捉摸的, 易忘的', '/i\'lju:siv,-səri | ɪ\'l(j)uːsɪv | ɪ\'lusɪv/', 'elusive', 6);
INSERT INTO `words` VALUES (11358, 'To cause to become lean, usually by starvation; emaciate.', 'v. 使憔悴, 使消瘦', '/i\'meisieit | ɪ\'meɪsɪeɪt | ɪ\'meʃɪ,et/', 'emaciate', 6);
INSERT INTO `words` VALUES (11359, 'The prisoners were ill and emaciated.', 'adj. 瘦弱的, 衰弱的', '/i\'meisieitid | ɪ\'meʃɪ\'etɪd/', 'emaciated', 6);
INSERT INTO `words` VALUES (11360, NULL, 'n. 消瘦， 憔悴， 衰弱', '/i,meisi\'eiʃən | ɪˌmeɪsi\'eɪʃn/', 'emaciation', 6);
INSERT INTO `words` VALUES (11361, 'Intelligence and cunning emanated from him.', 'v. 散发, 发出, 发源', '/\'eməneit | \'eməneɪt | ˈɛməˌneɪt/', 'emanate', 6);
INSERT INTO `words` VALUES (11362, 'Slaves were emancipated in 1834.', 'v. 解放， 释放', '/ɪ\'mænsɪpeɪt | ɪ\'mænsɪpet/', 'emancipate', 6);
INSERT INTO `words` VALUES (11363, 'We must arouse them to fight for their own emancipation.', 'n. 释放, 解放', '/i,mænsi\'peiʃən | ɪ,mænsɪ\'peɪʃ(ə)n | ɪ,mænsə\'peʃən/', 'emancipation', 6);
INSERT INTO `words` VALUES (11364, 'The bill has been emasculated by Congress.', 'v. 阉割, 使柔弱, 删削, 使无力', '/i\'mæskjuleit, i\'mæskjulit, -leit | ɪ\'mæskjʊleɪt | ɪ\'mæskjʊlɪt/', 'emasculate', 6);
INSERT INTO `words` VALUES (11365, 'They climbed a steep embankment.', 'n. 堤防, 筑堤', '/im\'bæŋkmənt | ɪm\'bæŋkm(ə)nt; em- | ɪm\'bæŋkmənt/', 'embankment', 6);
INSERT INTO `words` VALUES (11366, 'The United Nations imposed an arms embargo against the country.', 'n. 禁止出入港口, 禁运', '/em\'bɑ:ɡəu, im- | em\'bɑːgəʊ; ɪm- | ɪm\'bɑrɡo/', 'embargo', 6);
INSERT INTO `words` VALUES (11367, 'He didn’t want to embarrass her by asking questions.', 'v. 使局促不安， 使窘迫', '/ɪm\'bærəs/', 'embarrass', 6);
INSERT INTO `words` VALUES (11368, 'One of the bullets passed through Andrea\'s chest before embedding itself in a wall.', 'v. 使插入, 使嵌入, 深留, 嵌入, [医]包埋', '/im\'bed | ɪm\'bed; em- | ɪm\'bɛd/', 'embed', 6);
INSERT INTO `words` VALUES (11369, 'The boat was embellished with carvings in red and blue.', 'v. 修饰', '/im\'beliʃ | ɪm\'belɪʃ; em-/', 'embellish', 6);
INSERT INTO `words` VALUES (11370, '...Renaissance embellishments.', 'n. 装饰； 装饰品', '/ɪm\'belɪʃmənt | ɪm\'bɛlɪʃmənt/', 'embellishment', 6);
INSERT INTO `words` VALUES (11371, 'Two managers were charged with embezzling $400,000.', 'v. 盗用, 挪用', '/im\'bezl | ɪm\'bez(ə)l; em- | ɪm\'bɛzl/', 'embezzle', 6);
INSERT INTO `words` VALUES (11372, 'He was later charged with embezzlement.', 'n. 盗用, 侵占, 挪用', '/im\'bezlmənt | em\'bezlm(ə)nt | ɪm\'bɛzlmənt/', 'embezzlement', 6);
INSERT INTO `words` VALUES (11373, NULL, 'v. 加苦味于, 使受苦, 使难受, 使怨恨, 加重', '/im\'bitə | ɪm\'bɪtə; em- | ɪm\'bɪtɚ/', 'embitter', 6);
INSERT INTO `words` VALUES (11374, '...the emblem of the Soviet Union.', 'n. 象征, 徽章, 符号, <古>寓意画', '/\'embləm | \'ɛmbləm/', 'emblem', 6);
INSERT INTO `words` VALUES (11375, 'Dogs are emblematic of faithfulness.', 'adj. 象征(性), 标记的', '/,embli\'mætik,-kəl | ,emblə\'mætɪk | ,ɛmblə\'mætɪk/', 'emblematic', 6);
INSERT INTO `words` VALUES (11376, 'He is the embodiment of evil.', 'n. 体现, 具体化, 化身', '/im\'bɔdimənt | ɪm\'bɒdɪmənt | ɪm\'bɑdɪmənt/', 'embodiment', 6);
INSERT INTO `words` VALUES (11377, 'She embodies everything I admire in a teacher.', 'v. 具体表达, 使具体化, 包含, 收录', '/im\'bɔdi | ɪm\'bɒdɪ; em- | ɪm\'bɑdi/', 'embody', 6);
INSERT INTO `words` VALUES (11378, 'Emboldened by her smile, he asked her to dance.', 'v. 使大胆, 使有胆量, 使勇敢', '/im\'bəuldən, em- | ɪm\'bəʊld(ə)n; em- | ɛm\'boldən/', 'embolden', 6);
INSERT INTO `words` VALUES (11379, NULL, 'v. 饰以浮饰, 使浮雕出来', '/im\'bɔs | ɪm\'bɒs; em- | ɪm\'bɔs/', 'emboss', 6);
INSERT INTO `words` VALUES (11380, 'Jack warmly embraced his son.', 'v. 拥抱； 包含', '/ɪm\'breɪs | ɪm\'bres/', 'embrace', 6);
INSERT INTO `words` VALUES (11381, 'a richly embroidered jacket', 'v. 刺绣， 镶边； 装饰', '/ɪm\'brɔɪdər | ɪm\'brɔɪdɚ/', 'embroider', 6);
INSERT INTO `words` VALUES (11382, 'The shorts had blue embroidery over the pockets.', 'n. 刺绣品, 粉饰, 刺绣, 装饰', '/im\'brɔidəri | ɪm\'brɒɪd(ə)rɪ; em- | ɪm\'brɔɪdəri/', 'embroidery', 6);
INSERT INTO `words` VALUES (11383, 'Any hostilities could result in retaliation and further embroil U.N. troops in fighting.', 'v. 使卷入, 牵连, 使纠缠', '/im\'brɔil | ɪm\'brɒɪl; em- | ɪm\'brɔɪl/', 'embroil', 6);
INSERT INTO `words` VALUES (11384, 'The system already exists in embryo.', 'n. 胚胎, 胎儿, 胚芽', '/\'embriəu | \'embrɪəʊ | \'ɛmbrɪo/', 'embryo', 6);
INSERT INTO `words` VALUES (11385, NULL, 'adj. 胚胎学的', '/,embrɪə\'lɒdʒɪkəl | ˌembriə\'lɑːdʒɪkl/', 'embryological', 6);
INSERT INTO `words` VALUES (11386, 'embryonic development', 'adj. [生]胚胎的, 开始的', '/,embri\'ɔnik | ,embrɪ\'ɒnɪk | ,ɛmbrɪ\'ɑnɪk/', 'embryonic', 6);
INSERT INTO `words` VALUES (11387, 'When they do, rule aficionados will say, “Well, we can emend it and make it more supple by adding to the circumstances it covers.', 'v. 修订, 校勘', '/i\'mend | ɪ\'mend | ɪ\'mɛnd/', 'emend', 6);
INSERT INTO `words` VALUES (11388, NULL, 'n. 修订, 校正, 修正', '/,i:men\'deiʃən | ,iːmen\'deɪʃ(ə)n/', 'emendation', 6);
INSERT INTO `words` VALUES (11389, 'As far as colors go, this year we will be seeing some brights like orange, yellow, fuchsia, apple green, emerald, and amethyst.', 'n. [矿]祖母绿, 翡翠, 绿宝石, 翠绿色', '/\'emərəld | \'em(ə)r(ə)ld | \'ɛmərəld/', 'emerald', 6);
INSERT INTO `words` VALUES (11390, 'The flowers emerge in the spring.', 'v. 显现, 浮现, 暴露, 形成, (由某种状态)脱出, (事实)显现出来', '/i\'mə:dʒ | ɪ\'mɜːdʒ | ɪ\'mɝdʒ/', 'emerge', 6);
INSERT INTO `words` VALUES (11391, NULL, 'n. 浮现, 露出, (植物)突出体, 出现', '/i\'mə:dʒəns | ɪ\'mɜːdʒ(ə)ns | ɪ\'mɝdʒəns/', 'emergence', 6);
INSERT INTO `words` VALUES (11392, 'Lifeguards are trained to deal with emergencies.', 'n. 紧急情况, 突然事件, 非常时刻, 紧急事件', '/i\'mə:dʒənsi | ɪ\'mɜːdʒ(ə)nsɪ | ɪ\'mɝdʒənsi/', 'emergency', 6);
INSERT INTO `words` VALUES (11393, NULL, 'n. [医]催吐剂', '/i\'metik | ɪ\'metɪk/', 'emetic', 6);
INSERT INTO `words` VALUES (11394, 'He emigrated to Belgium.', 'v. 永久(使)移居', '/\'emiɡreit | \'emɪgreɪt | \'ɛmɪɡret/', 'emigrate', 6);
INSERT INTO `words` VALUES (11395, 'Many of the pilots were to achieve eminence in the aeronautical world.', 'n. 出众, 显赫, 崇高', '/\'eminəns | \'emɪnəns | \'ɛmɪnəns/', 'eminence', 6);
INSERT INTO `words` VALUES (11396, 'an eminent lawyer', 'adj. 显赫的, 杰出的, 有名的, 优良的', '/\'eminənt | \'emɪnənt | \'ɛmɪnənt/', 'eminent', 6);
INSERT INTO `words` VALUES (11397, 'Japan is sending two emissaries to Washington to discuss trade issues.', 'n. 使者', '/\'emisəri | \'emɪs(ə)rɪ | \'ɛmɪsɛri/', 'emissary', 6);
INSERT INTO `words` VALUES (11398, 'Britain agreed to cut emissions of nitrogen oxide from power stations.', 'n. (光、热等的)散发, 发射, 喷射', '/i\'miʃən | ɪ\'mɪʃ(ə)n | ɪ\'mɪʃən/', 'emission', 6);
INSERT INTO `words` VALUES (11399, 'The kettle emitted a shrill whistle.', 'v. 发出, 放射, 吐露, 散发, 发表, 发行', '/i\'mit | ɪ\'mɪt/', 'emit', 6);
INSERT INTO `words` VALUES (11400, 'an emollient reply', 'adj. 使柔软的', '/i\'mɔliənt | ɪ\'mɒlɪənt | ɪ\'mɑlɪənt/', 'emollient', 6);
INSERT INTO `words` VALUES (11401, 'He could earn up to a million dollars a year in salary and emoluments from many directorships.', 'n. 薪水, 报酬', '/i\'mɔljumənt | ɪ\'mɒljʊm(ə)nt; e-/', 'emolument', 6);
INSERT INTO `words` VALUES (11402, 'Siskind encourages the children to emote to the music as they dance.', 'v. <美口>夸张地作为, 表现感情', '/i\'məut | ɪ\'məʊt | ɪ\'mot/', 'emote', 6);
INSERT INTO `words` VALUES (11403, 'Having begun my life in a children\'s home, I have great empathy with the little ones.', 'n. 移情作用, [心]神入', '/\'empəθɪ | \'ɛmpəθi/', 'empathy', 6);
INSERT INTO `words` VALUES (11404, 'an emphatic denial', 'adj. 重视的， 强调的', '/ɪm\'fætɪk/', 'emphatic', 6);
INSERT INTO `words` VALUES (11405, '{\"COLLOINEXA\":[\"empirical evidence\"]}', 'adj. 完全根据经验的, 经验主义的, [化]实验式', '/em\'pɪrɪk(ə)l; ɪm- | ɪm\'pɪrɪkl/', 'empirical', 6);
INSERT INTO `words` VALUES (11406, NULL, 'adv. 凭经验地', '/im\'pirikli | ɪm\'pɪrɪkli/', 'empirically', 6);
INSERT INTO `words` VALUES (11407, 'The opposite of empiricism is rationalism.', 'n. 经验主义, 经验论, 庸医的医术', '/em\'pirisizəm | em\'pɪrɪsɪz(ə)m | ɛm\'pɪrə\'sɪzəm/', 'empiricism', 6);
INSERT INTO `words` VALUES (11408, 'The factory employs over 2,000 people.', 'v. 雇用, 用, 使用', '/im\'plɔi | ɪm\'plɒɪ; em- | ɪm\'plɔɪ/', 'employ', 6);
INSERT INTO `words` VALUES (11409, 'Here in Menghai, the newly opened six-story emporium built to house hundreds of buyers and bundlers is a very lonely place.', 'n. 商场, 商业中心, 大百货商店', '/em\'pɔ:riəm | em\'pɔːrɪəm; ɪm- | ɛm\'pɔrɪəm/', 'emporium', 6);
INSERT INTO `words` VALUES (11410, 'The army is now empowered to operate on a shoot-to-kill basis.', 'v. 授权与, 使能够', '/im\'pauə | ɪm\'paʊə; em- | ɪm\'paʊɚ/', 'empower', 6);
INSERT INTO `words` VALUES (11411, 'an empty box', 'adj. 空的，缺乏的; v. 变空， 把…弄空', '/\'empti | ˈɛmptɪ/', 'empty', 6);
INSERT INTO `words` VALUES (11412, NULL, 'adj. 最高天的, 苍天的, 九天的', '/,empai\'ri,əl, em\'pririəl | ,empaɪ\'rɪ,əl/', 'empyreal', 6);
INSERT INTO `words` VALUES (11413, NULL, 'n. 最高天, 苍天, 九天', '/,empai\'ri:ən, em\'piriən | ,empaɪ\'riːən; -pɪ-; em\'pɪrɪən/', 'empyrean', 6);
INSERT INTO `words` VALUES (11414, 'Employees look to you to show them the behaviors that they should emulate.', 'n. 仿效', '/\'emjuleit, \'emjulit | \'emjʊleɪt | \'ɛmjulet/', 'emulate', 6);
INSERT INTO `words` VALUES (11415, 'His spirit of assiduous study is worthy of emulation.', 'n. 竞争, 效法', '/,emju\'leiʃən | ,emjʊ\'leɪʃən | ,ɛmjə\'leʃən/', 'emulation', 6);
INSERT INTO `words` VALUES (11416, 'It is the pressure which releases the coffee oils; these emulsify and give the coffee its rich, velvety texture.', 'v. 使乳化', '/i\'mʌlsifai | ɪ\'mʌlsɪfaɪ | ɪ\'mʌlsə\'fai/', 'emulsify', 6);
INSERT INTO `words` VALUES (11417, 'a drama enacted on a darkened stage', 'v. 制定法律, 颁布, 扮演', '/ɪ\'nækt; e- | ɪ\'nækt/', 'enact', 6);
INSERT INTO `words` VALUES (11418, 'We support the call for the enactment of a Bill of Rights.', 'n. 设定, 制定', '/i\'næktmənt | ɪ\'næktm(ə)nt; e- | ɪ\'næktmənt/', 'enactment', 6);
INSERT INTO `words` VALUES (11419, 'Most visitors to London are enamored with the city.', 'adj. 倾心的， 被迷住', '/en\'æməd | ɪ\'næmərd/', 'enamored', 6);
INSERT INTO `words` VALUES (11420, 'The words of the song neatly encapsulate the mood of the country at that time.', 'v. 装入胶囊, 压缩', '/ɪn\'kæpsjʊleɪt; en- | ɪn\'kæpsjə\'let/', 'encapsulate', 6);
INSERT INTO `words` VALUES (11421, 'These applications of encapsulation, modularity , and polymorphism are implemented by the patterns.', 'n. 包装', '/ɪn\'kæpsjuleɪʃən | ɪn,kæpsə\'leʃən/', 'encapsulation', 6);
INSERT INTO `words` VALUES (11422, 'Encephalitis still attacks one child in 1,000 who catches measles.', 'n. 脑炎', '/,ensefə\'laitis | en,sefə\'laɪtɪs; -,kefə- | ɛn,sɛfə\'laɪtəs/', 'encephalitis', 6);
INSERT INTO `words` VALUES (11423, '...Celtic stories of cauldrons and enchanted vessels.', 'v. 施魔法, 使迷惑', '/in\'tʃɑ:nt, en- | ɪn\'tʃɑːnt; en- | ɪn\'tʃænt/', 'enchant', 6);
INSERT INTO `words` VALUES (11424, 'an enchanting place', 'adj. 迷人的, 迷惑的, 妩媚的', '/in\'tʃɑ:ntiŋ, en- | ɪn\'tʃɑːntɪŋ | ɪn\'tʃæntɪŋ/', 'enchanting', 6);
INSERT INTO `words` VALUES (11425, 'the enchantment of poetry', 'n. 迷惑, 着迷, 魔法, 妖术, 魅力', '/in\'tʃɑ:ntmənt, en- | ɪn\'tʃɑːntm(ə)nt | ɪn\'tʃæntm(ə)nt/', 'enchantment', 6);
INSERT INTO `words` VALUES (11426, NULL, 'v. 译成密码', '/in\'saifə | ɪn\'saɪfə; en- | ɪn\'saɪfɚ/', 'encipher', 6);
INSERT INTO `words` VALUES (11427, 'the bear enclosure at the zoo', 'n. 围住, 围栏, 四周有篱笆或围墙的场地', '/in\'kləuʒə | ɪn\'kləʊʒə; en- | ɪn\'kloʒɚ/', 'enclosure', 6);
INSERT INTO `words` VALUES (11428, NULL, 'n. 宣读或写颂辞之人, 阿谀者, 赞美者', '/en\'kəʊmɪæst/', 'encomiast', 6);
INSERT INTO `words` VALUES (11429, NULL, 'n. 赞辞, 赞美, 称赞', '/en\'kəumiəm | en\'kəʊmɪəm | ɛn\'komɪəm/', 'encomium', 6);
INSERT INTO `words` VALUES (11430, 'The study encompasses the social, political, and economic aspects of the situation.', 'v. 包围, 环绕, 包含或包括某事物', '/in\'kʌmpəs | ɪn\'kʌmpəs; en- | ɪn\'kʌmpəs/', 'encompass', 6);
INSERT INTO `words` VALUES (11431, 'The doctor had encountered several similar cases in the past.', 'v. 遭遇； 邂逅', '/ɪn\'kauntər | ɪn\'kaʊntɚ/', 'encounter', 6);
INSERT INTO `words` VALUES (11432, 'The new institutions do not encroach on political power.', 'v. (逐步或暗中)侵占, 蚕食, 超出通常(或正常)界线', '/ɪnˈkrəʊtʃ | ɪn\'krəʊtʃ; en- | ɪn\'krotʃ/', 'encroach', 6);
INSERT INTO `words` VALUES (11433, 'It\'s a sign of the encroachment of commercialism in medicine.', 'n. 侵蚀, 侵犯', '/in\'krəutʃmənt | eŋ\'krəʊtʃm(ə)nt | ɪn\'krotʃmənt/', 'encroachment', 6);
INSERT INTO `words` VALUES (11434, 'He died in 1874, heavily encumbered by debt.', 'v. 阻碍', '/in\'kʌmbə | ɪn\'kʌmbə; en- | ɪn\'kʌmbɚ/', 'encumber', 6);
INSERT INTO `words` VALUES (11435, 'Magdalena considered the past an irrelevant encumbrance.', 'n. 阻碍, 累赘, 妨害物', '/in\'kʌmbrəns | ɪn\'kʌmbr(ə)ns; en- | ɪn\'kʌmbrəns/', 'encumbrance', 6);
INSERT INTO `words` VALUES (11436, 'the Encyclopedia of Music', 'n. 百科全书', '/ɪnˌsaɪklə\'piːdiə | ɪnˌsaɪkləˈpidiɚ/', 'encyclopedia', 6);
INSERT INTO `words` VALUES (11437, 'an encyclopedic knowledge of medieval literature', 'adj. 如百科辞典的, 百科全书式的', '/en,saikləu\'pi:dik,-kəl | en,saɪklə(ʊ)\'piːdɪk; ɪn- | ɪn\'saɪklə\'pidɪk/', 'encyclopedic', 6);
INSERT INTO `words` VALUES (11438, 'Their taste for gambling has endeared them to Las Vegas casino owners.', 'v. 使受喜爱', '/ɪn\'dɪr/', 'endear', 6);
INSERT INTO `words` VALUES (11439, 'an endearing smile', 'adj. 讨人喜欢的', '/ɪn\'dɪrɪŋ/', 'endearing', 6);
INSERT INTO `words` VALUES (11440, 'No term of endearment crossed their lips.', 'n. 亲爱, 钟爱', '/in\'diəmənt | ɪn\'dɪəm(ə)nt; en- | ɪn\'dɪrmənt/', 'endearment', 6);
INSERT INTO `words` VALUES (11441, 'Violent crime is now endemic in parts of Chicago.', 'adj. 地方性的', '/en\'demɪk | ɛn\'dɛmɪk/', 'endemic', 6);
INSERT INTO `words` VALUES (11442, 'Located near the base of the neck, the thyroid is a large endocrine gland that produces hormones that help control growth and metabolism.', 'n. 内分泌', '/\'endəukrain, -krin | \'endə(ʊ)kraɪn; -krɪn | \'ɛndəkrɪn/', 'endocrine', 6);
INSERT INTO `words` VALUES (11443, 'I can endorse their opinion wholeheartedly.', 'v. 赞同； 背书', '/ɪn\'dɔːrs | ɪn\'dɔrs/', 'endorse', 6);
INSERT INTO `words` VALUES (11444, 'This is a powerful endorsement for his softer style of government.', 'n. 背书, 签注(文件), 认可', '/in\'dɔ:smənt | ɪn\'dɔːsm(ə)nt; en- | ɪn\'dɔrsmənt/', 'endorsement', 6);
INSERT INTO `words` VALUES (11445, 'You are endowed with wealth, good health and a lively intellect.', 'v. 捐赠； 赋予', '/ɪn\'dau | ɪn\'daʊ/', 'endow', 6);
INSERT INTO `words` VALUES (11446, 'He prayed to God night and day endue him with the spirit of holiness.', 'v. 穿上, 授予, 赋予', '/in\'dju: | ɪn\'djuː; en-/', 'endue', 6);
INSERT INTO `words` VALUES (11447, 'It seemed impossible that anyone could endure such pain.', 'v. 忍受， 忍耐', '/ɪn\'dur | ɪn\'dʊr/', 'endure', 6);
INSERT INTO `words` VALUES (11448, 'the enduring appeal of Shakespeare’s plays', 'adj. 持久的； 不朽的', '/ɪn\'durɪŋ | ɪn\'dʊrɪŋ/', 'enduring', 6);
INSERT INTO `words` VALUES (11449, 'He helped energize and mobilize millions of people around the nation.', 'v. 给予…精力、 能量', '/\'enərdʒaɪz | \'ɛnɚdʒaɪz/', 'energize', 6);
INSERT INTO `words` VALUES (11450, NULL, 'n. 被恶魔附者,狂热者', '/,enə\'gjuːmən/', 'energumen', 6);
INSERT INTO `words` VALUES (11451, 'The hot sun enervated her to the point of collapse.', 'v. 削弱', '/\'enəveɪt;ɪˈnɜːveɪt | ˈenərveɪt;ɪˈnɜːveɪt/', 'enervate', 6);
INSERT INTO `words` VALUES (11452, NULL, 'v. 使衰弱', '/ɪn\'fiːbl/', 'enfeeble', 6);
INSERT INTO `words` VALUES (11453, NULL, 'v. 给…上脚镣； 束缚， 使受制于', '/ɪn\'fetər | in\'fetə/', 'enfetter', 6);
INSERT INTO `words` VALUES (11454, NULL, 'v. 燃烧', '/in\'fleim | ɪn\'fleɪm/', 'enflame', 6);
INSERT INTO `words` VALUES (11455, 'The company voted to enfranchise its 120 women members.', 'v. 给予选举权, 给予自治权, 解放', '/in\'fræntʃaiz | ɪn\'fræn(t)ʃaɪz; en- | ɪn\'fræntʃaɪz/', 'enfranchise', 6);
INSERT INTO `words` VALUES (11456, 'Are you so tired you don’t have the energy to engage with your kids?', 'v. 从事， 参加； 雇用， 聘用； 使参与； 引起…的注意', '/ɪn\'geɪdʒ | ɪn\'ɡedʒ/', 'engage', 6);
INSERT INTO `words` VALUES (11457, 'an engaging smile', 'adj. 动人的, 有魅力的, 迷人的', '/in\'ɡeidʒiŋ | ɪn\'geɪdʒɪŋ; en- | ɪn\'ɡedʒɪŋ/', 'engaging', 6);
INSERT INTO `words` VALUES (11458, 'In such circumstances, governments must do all they can to create and engender trust among its nation’s constituents and institutions.', 'v. 造成', '/in\'dʒendə | ɪn\'dʒendə; en- | ɪn\'dʒɛndɚ/', 'engender', 6);
INSERT INTO `words` VALUES (11459, NULL, 'vt. 使佩带, 围绕', '/ɪn\'ɡɜːd | in\'ɡə:d/', 'engird', 6);
INSERT INTO `words` VALUES (11460, 'Your wedding ring can be engraved with a personal inscription at no extra cost.', 'v. 雕刻， 铭刻； 牢记， 铭记', '/ɪn\'greɪv | ɪn\'ɡrev/', 'engrave', 6);
INSERT INTO `words` VALUES (11461, 'The scene was stunning, and for a time engrossed all our attention.', 'v. 用大字体书写, 吸引, 占用, 使全神贯注, 独占', '/in\'ɡrəus | ɪn\'grəʊs; en- | ɪn\'ɡros/', 'engross', 6);
INSERT INTO `words` VALUES (11462, 'He is an engrossing subject for a book.', 'adj. 引人入胜的, 极有趣的', '/in\'ɡrəusiŋ | ɪn\'ɡrəʊsɪŋ | ɛn\'grosɪŋ/', 'engrossing', 6);
INSERT INTO `words` VALUES (11463, 'despair so great it threatened to engulf him', 'v. 卷入, 吞没, 狼吞虎咽', '/in\'ɡʌlf | ɪn\'gʌlf; en- | ɛnˈɡʌlf/', 'engulf', 6);
INSERT INTO `words` VALUES (11464, 'Progressive enhancement helps us to do that because it forces us to focus on the content and build out from there.', 'n. 增进, 增加', '/in\'ha:nsmənt | ɪn\'hɑːnsm(ə)nt; en- | in\'hænsmənt/', 'enhancement', 6);
INSERT INTO `words` VALUES (11465, 'Iran remains an enigma for the outside world.', 'n. 谜, 不可思议的东西', '/i\'niɡmə | ɪ\'nɪgmə/', 'enigma', 6);
INSERT INTO `words` VALUES (11466, NULL, 'adj. 谜一般的, 高深莫测的', '/,eniɡ\'mætik,-kəl | ,enɪg\'mætɪk | \'ɛnɪg\'mætɪk/', 'enigmatic', 6);
INSERT INTO `words` VALUES (11467, 'She enjoined me strictly not to tell anyone else.', 'v. 吩咐, 命令, 嘱咐, <主美>禁止', '/in\'dʒɔin | ɪn\'dʒɒɪn; en- | ɪn\'dʒɔɪn/', 'enjoin', 6);
INSERT INTO `words` VALUES (11468, NULL, 'v. 点燃, 使燃烧, 激起(热情等), 挑起(战争等)', '/in\'kindl | ɪn\'kɪnd(ə)l; en-/', 'enkindle', 6);
INSERT INTO `words` VALUES (11469, 'She brought me to the field and enlightened me.', 'v. 启迪', '/in\'laitənd | ɪn\'laɪt(ə)nd | ɪn\'laɪtnd/', 'enlightened', 6);
INSERT INTO `words` VALUES (11470, NULL, 'adj. 有启迪作用的； 使人领悟的', '/ɪn\'laɪtnɪŋ | in\'laitəniŋ/', 'enlightening', 6);
INSERT INTO `words` VALUES (11471, 'Stella had a moment of enlightenment.', 'n. 启迪, 教化', '/in\'laitənmənt | ɪn\'laɪt(ə)nm(ə)nt; en- | ɪn\'laɪtnmənt/', 'enlightenment', 6);
INSERT INTO `words` VALUES (11472, NULL, 'v. 征募, 谋取(支持、赞助等), 应募, 赞助, 支持, 征召, 参军', '/in\'list | ɪn\'lɪst; en- | ɪn\'lɪst/', 'enlist', 6);
INSERT INTO `words` VALUES (11473, 'At the end of my term of enlistment I decided to return to civilian life.', 'n. 征募, 服役期间', '/in\'listmənt | ɪn\'lɪstmənt/', 'enlistment', 6);
INSERT INTO `words` VALUES (11474, 'Humour can help enliven a dull subject.', 'v. 使…更活跃或更愉快', '/ɪn\'laɪvn | ɪn\'laɪvən/', 'enliven', 6);
INSERT INTO `words` VALUES (11475, NULL, 'v. 使绊住, 使陷入', '/in\'meʃ | ɪn\'meʃ; en- | ɪn\'mɛʃ/', 'enmesh', 6);
INSERT INTO `words` VALUES (11476, 'I think there is an historic enmity between them.', 'n. 敌意, 憎恨', '/\'enməti | \'enmɪtɪ/', 'enmity', 6);
INSERT INTO `words` VALUES (11477, '...the enduring fundamental principles of life that ennoble mankind.', 'v. 授予爵位， 使高贵', '/ɪ\'noubl | ɪ\'nobl/', 'ennoble', 6);
INSERT INTO `words` VALUES (11478, 'The patient\'s cheerful smile was just a facade ; actually she was suffering from ennui.', 'n. 倦怠；', '/ɑːn\'wiː | ɑn\'wi/', 'ennui', 6);
INSERT INTO `words` VALUES (11479, 'I was numbed by the enormity of the responsibility.', 'n. 暴行, 巨大, 极恶', '/i\'nɔ:məti | ɪ\'nɔːmɪtɪ | ɪ\'nɔrməti/', 'enormity', 6);
INSERT INTO `words` VALUES (11480, 'an enormous bunch of flowers', 'adj. 巨大的, 庞大的, <古>极恶的, 凶暴的', '/i\'nɔ:məs | ɪ\'nɔːməs | ɪ\'nɔrməs/', 'enormous', 6);
INSERT INTO `words` VALUES (11481, 'Many readers were enraged by his article.', 'v. 激怒， 触怒', '/ɪn\'reɪdʒ | in\'reidʒ/', 'enrage', 6);
INSERT INTO `words` VALUES (11482, 'The starred delights will enrapture my soul to insanity.', 'v. 使狂喜', '/in\'ræptʃə | ɪn\'ræptʃə; en- | ɪn\'ræptʃɚ/', 'enrapture', 6);
INSERT INTO `words` VALUES (11483, 'ensconced in a chair', 'v. 隐藏, 安置', '/in\'skɔns | ɪn\'skɒns; en-/', 'ensconce', 6);
INSERT INTO `words` VALUES (11484, '...an ensemble of young musicians.', 'n. <法>全体, [音]合唱曲, 全体演出者', '/ɔŋ\'sɔŋblə | ɒn\'sɒmb(ə)l | ɑn\'sɑmbl/', 'ensemble', 6);
INSERT INTO `words` VALUES (11485, 'This system is enshrined in our Constitution.', 'v. 入庙祀奉, 铭记', '/in\'ʃrain | ɪn\'ʃraɪn; en- | ɪn\'ʃraɪn/', 'enshrine', 6);
INSERT INTO `words` VALUES (11486, 'the Russian ensign', 'n. 旗, 军舰旗, 军旗, 徽章, <美>海军少尉', '/\'ensain, -sən | [ˈensən] | [ˈɛnsən, -ˌsaɪn]/', 'ensign', 6);
INSERT INTO `words` VALUES (11487, 'The spider must wait for prey to be ensnared on its web.', 'v. 诱捕', '/in\'snεə | ɪn\'sneə; en-/', 'ensnare', 6);
INSERT INTO `words` VALUES (11488, 'If the Europeans did not reduce subsidies, a trade war would ensue.', 'v. 跟着发生, 继起', '/in\'sju: | ɪn\'sjuː; en- | ɪn\'su/', 'ensue', 6);
INSERT INTO `words` VALUES (11489, 'Bureaucracy can entangle applications for months.', 'v. 使缠上, 纠缠, 卷入, 连累, 使混乱', '/in\'tæŋɡl | ɪn\'tæŋg(ə)l; en- | ɪn\'tæŋɡl/', 'entangle', 6);
INSERT INTO `words` VALUES (11490, '...a military and political entanglement the president probably doesn\'t want.', 'n. 纠缠', '/in\'tæŋɡlmənt | ɪn\'tæŋg(ə)lm(ə)nt; en- | ɪn\'tæŋɡlmənt/', 'entanglement', 6);
INSERT INTO `words` VALUES (11491, 'commercial enterprises such as banks and food manufacturers', 'n. 公司， 企业； 进取心', '/\'entərpraɪz | \'ɛntɚ\'praɪz/', 'enterprise', 6);
INSERT INTO `words` VALUES (11492, 'Some enterprising students are designing software.', 'adj. 有事业心的, 有进取心的, 有魄力的, 有胆量的, 富有进取心', '/\'entəpraiziŋ | \'entəpraɪzɪŋ | \'ɛntɚpraɪzɪŋ/', 'enterprising', 6);
INSERT INTO `words` VALUES (11493, 'Mark usually does the cooking when we entertain.', 'v. 款待， 招待； 使欢乐， 娱乐', '/ˌentər\'teɪn | ,ɛntɚ\'ten/', 'entertain', 6);
INSERT INTO `words` VALUES (11494, 'The passengers were enthralled by the scenery.', 'v. 迷惑', '/ɪn\'θrɔːl | ɪn\'θrɔl/', 'enthral', 6);
INSERT INTO `words` VALUES (11495, 'Such trends do not enthrall neutrals, many of whom would prefer to see free-scoring Barcelona win tomorrow.', 'v. 迷惑, 迷住, 奴役', '/in\'θrɔ:l | ɪn\'θrɔːl/', 'enthrall', 6);
INSERT INTO `words` VALUES (11496, 'an enthralling experience', 'adj. 迷人的， 吸引人的', '/in\'θrɔ:liŋ | ɪn\'θrɔːlɪŋ/', 'enthralling', 6);
INSERT INTO `words` VALUES (11497, 'He tries to counterfeit all the good things God offers you, aiming at our weakness in order to exploit our vulnerabilities and entice us into the darkness.', 'v. 诱惑, 诱使', '/in\'tais | ɪn\'taɪs; en- | ɪn\'taɪs/', 'entice', 6);
INSERT INTO `words` VALUES (11498, '...a second disk that offers, among other enticements, an interactive tour of Hogwarts.', 'n. 诱惑, 怂恿, 引诱', '/in\'taismənt | ɪn\'taɪsmənt/', 'enticement', 6);
INSERT INTO `words` VALUES (11499, 'The film has been shown in its entirety for the first time.', 'n. 整体， 全面', '/ɪn\'taɪərəti/', 'entirety', 6);
INSERT INTO `words` VALUES (11500, 'If the warranty is limited, the terms may entitle you to a replacement or refund.', 'v. 使有权', '/ɪn\'taɪtl/', 'entitle', 6);
INSERT INTO `words` VALUES (11501, 'The mind exists as a separate entity.', 'n. 实体', '/\'entəti | \'entɪtɪ | \'ɛntəti/', 'entity', 6);
INSERT INTO `words` VALUES (11502, '“We’ve learned quite a lot, ” said K.A. Monney, a professor in the university’s entomology and wildlife department.', 'n. 昆虫学', '/,entə\'mɔlədʒi | ,entə\'mɒlədʒɪ | ,ɛntə\'mɑlədʒi/', 'entomology', 6);
INSERT INTO `words` VALUES (11503, 'the president and his entourage', 'n. 随从； 环境', '/\'ɑːnturɑːʒ | \'ɑnturɑʒ/', 'entourage', 6);
INSERT INTO `words` VALUES (11504, 'All the alien innards in the film were actually sheep brains, raspberry jam and chicken entrails.', 'n. 内脏, 肠, (物体的)内部', '/\'entreilz | \'entreɪlz | \'ɛntrelz/', 'entrails', 6);
INSERT INTO `words` VALUES (11505, NULL, 'vt. 束缚, 妨碍', '/ɪn\'træm(ə)l; en-/', 'entrammel', 6);
INSERT INTO `words` VALUES (11506, 'I was entranced by the sweetness of her voice.', 'v. 使出神， 使入迷', '/\'entrəns | (for v.)ɪnˈtræns; (for n.) ˈɛntrəns/', 'entrance', 6);
INSERT INTO `words` VALUES (11507, 'He entreated them to delay their departure.', 'v. 恳求, 乞求, <古>对待, 对付', '/in\'tri:t | ɪn\'triːt; en- | ɪn\'trit/', 'entreat', 6);
INSERT INTO `words` VALUES (11508, 'She declined the Republican Party\'s entreaties to run for his seat.', 'n. 恳求, 乞求', '/in\'tri:ti | ɪn\'triːtɪ; en- | ɪn\'triti/', 'entreaty', 6);
INSERT INTO `words` VALUES (11509, 'They hold that, once entrenched, only Lincoln\'s bellicose policy could have eradicated it.', 'adj. 确立的，不容易改的（风俗习惯）', '/ɪn\'tren(t)ʃt; en-/', 'entrenched', 6);
INSERT INTO `words` VALUES (11510, '“You have to be an optimist to be an inventor or entrepreneur, ” he concludes.', 'n. <法>企业家, 主办人', '/,ɔntrəprə\'nə: | ˌɒntrəprəˈnɜː(r) | ˌɑntrəprəˈnɝ​/', 'entrepreneur', 6);
INSERT INTO `words` VALUES (11511, 'He entrusted his cash to a business partner for investment in a series of projects.', 'v. 委托', '/in\'trʌst | ɪn\'trʌst; en- | ɪn\'trʌst/', 'entrust', 6);
INSERT INTO `words` VALUES (11512, 'They walked together with their arms entwined.', 'v. (使)缠住, (使)盘绕', '/in\'twain | ɪn\'twaɪn; en- | ɪn\'twaɪn/', 'entwine', 6);
INSERT INTO `words` VALUES (11513, 'I enumerate the work that will have to be done.', 'v. 列举', '/i\'nju:məreit | ɪ\'njuːməreɪt | ɪ\'numəret/', 'enumerate', 6);
INSERT INTO `words` VALUES (11514, 'ideas that he was to enunciate decades later', 'v. 阐明, 清晰发言', '/i\'nʌnsieit, -ʃieit | ɪ\'nʌnsɪeɪt | ɪ\'nʌnsɪet/', 'enunciate', 6);
INSERT INTO `words` VALUES (11515, 'And all those everyday consumer products, which owe their existence, in no small part, to manufacturing methods that wouldn’t work without Einstein’s enunciation of the atomic theory of matter.', 'n. 阐明', '/i,nʌnsi\'eiʃən, -ʃi-/', 'enunciation', 6);
INSERT INTO `words` VALUES (11516, 'Now he was in the enviable position of not having to work for a living.', 'adj. 令人羡慕的', '/\'enviəbl | \'ɛnvɪəbl/', 'enviable', 6);
INSERT INTO `words` VALUES (11517, NULL, 'v. 包围， 围绕', '/ɪn\'vaɪrən/', 'environ', 6);
INSERT INTO `words` VALUES (11518, NULL, 'n. 市郊, 郊外', '/in\'vaiərənz | ɪn\'vaɪrənz; en-; \'envɪrənz | ɪn\'vaɪrənz/', 'environs', 6);
INSERT INTO `words` VALUES (11519, 'You must envisage realities.', 'v. 正视', '/in\'vizidʒ | ɪn\'vɪzɪdʒ; en- | ɪn\'vɪzɪdʒ/', 'envisage', 6);
INSERT INTO `words` VALUES (11520, 'I envisioned a future of educational excellence.', 'v. 想象， 预想', '/ɪn\'vɪʒn/', 'envision', 6);
INSERT INTO `words` VALUES (11521, 'The United Nations is sending a special envoy to the area.', 'n. 外交使节, 特使', '/\'envɔi | \'envɒɪ | \'ɛnvɔɪ/', 'envoy', 6);
INSERT INTO `words` VALUES (11522, 'It is believed that it inhibits an enzyme that promotes cell proliferation in tumours.', 'n. [生化]酶', '/\'enzaim | \'enzaɪm | \'ɛnzaɪm/', 'enzyme', 6);
INSERT INTO `words` VALUES (11523, 'Functional epaulet at each shoulder.', 'n. [军]肩章, 肩饰', '/\'epəlet, ,epə\'let | \'epəlet/', 'epaulet', 6);
INSERT INTO `words` VALUES (11524, 'He talked about the country\'s ephemeral unity being shattered by the defeat.', 'adj. 朝生暮死的, 短暂的, 短命的', '/i\'femərəl | ɪ\'fem(ə)r(ə)l; -\'fiːm- | ə\'fɛmərəl/', 'ephemeral', 6);
INSERT INTO `words` VALUES (11525, 'an epic tale of mutiny on the high seas', 'adj. 史诗的， 叙事诗的； 英雄的； 大规模的; n. 叙事诗，史诗', '/\'epɪk | \'ɛpɪk/', 'epic', 6);
INSERT INTO `words` VALUES (11526, NULL, 'n. 美食家, 老饕, <古>享乐主义者', '/\'epi,kjuə | \'epɪkjʊə; \'epɪkjɔː | \'ɛpɪkjʊr/', 'epicure', 6);
INSERT INTO `words` VALUES (11527, 'The style will be critical in the delivery of epideictic speech, style is your word preference and syntax.', 'adj. (文体、演讲等)意在表现词藻技巧的富于词藻的', '/,epi\'daiktik | ,epɪ\'deɪktɪk; -\'daɪktɪk/', 'epideictic', 6);
INSERT INTO `words` VALUES (11528, NULL, 'adj. 流行的, 传染的, 流行性', '/,epi\'demik | epɪ\'demɪk | ,ɛpɪ\'dɛmɪk/', 'epidemic', 6);
INSERT INTO `words` VALUES (11529, 'The pigment in the upper layer of skin (epidermis) that gives your skin its normal color is called melanin.', 'n. [生]表皮, 上皮', '/,epi\'də:mis | ,epɪ\'dɜːmɪs | ,ɛpɪ\'dɝmɪs/', 'epidermis', 6);
INSERT INTO `words` VALUES (11530, 'We think, IT tycoon must hour is vigilant all sorts of competitors and epigone , avoid in-house error at the same time.', 'n. 追随者, 模仿者', '/\'epiɡəun | \'epɪgəʊn/', 'epigone', 6);
INSERT INTO `words` VALUES (11531, NULL, 'n. 警句, 讽刺短诗', '/\'epiɡræm | \'epɪgræm/', 'epigram', 6);
INSERT INTO `words` VALUES (11532, 'Even in his style there is something of a modern epigrammatic ring.', 'adj. 警句的, 讽刺的', '/,epiɡrə\'mætik,-kəl | ,epɪgrə\'mætɪk | ɛpɪgrə\'mætɪk/', 'epigrammatic', 6);
INSERT INTO `words` VALUES (11533, 'a disastrous epilogue to his career', 'n. 结语, 尾声, [戏]收场白', '/\'epilɔɡ | \'epɪlɒg | \'ɛpɪlɔɡ/', 'epilogue', 6);
INSERT INTO `words` VALUES (11534, 'Watch next week’s thrilling episode!', 'n. 一段情节； 插曲， 片断', '/\'epɪsoud | \'ɛpɪsod/', 'episode', 6);
INSERT INTO `words` VALUES (11535, 'his episodic involvement in politics', 'adj. 偶然发生的； 分散性的', '/ˌepɪ\'sɑːdɪk | ,ɛpɪ\'sɑdɪk/', 'episodic', 6);
INSERT INTO `words` VALUES (11536, 'The Republic and The Laws, written 2300 to 2400 years ago, dealt not only with philosophy, the theory of knowledge, epistemology, but also with social conditions.', 'n. [哲]认识论', '/e,pisti:\'mɔlədʒi | ɪ,pɪstɪ\'mɒlədʒɪ; e- | ɪ,pɪstə\'mɑlədʒi/', 'epistemology', 6);
INSERT INTO `words` VALUES (11537, NULL, 'n. 书信, 使徒书, 书信体诗文', '/i\'pisl | ɪ\'pɪs(ə)l | ɪ\'pɪsl/', 'epistle', 6);
INSERT INTO `words` VALUES (11538, 'His epitaph for himself would have well suited man as he wanted him to be.', 'n. 墓志铭, 碑文', '/\'epitɑ:f,-tæf | \'epɪtɑːf; -tæf | \'ɛpɪtæf/', 'epitaph', 6);
INSERT INTO `words` VALUES (11539, 'But it is impossible to predict the reaction of a man accosted by another with the words \"you rat\" without referring to the meaning that the man spoken to attaches to the epithet.', 'n. 绰号, 称号', '/\'epiθet | \'epɪθet | \'ɛpɪθɛt/', 'epithet', 6);
INSERT INTO `words` VALUES (11540, 'She looked the epitome of elegance.', 'n. 摘要', '/i\'pitəmi | ɪ\'pɪtəmɪ; e- | ɪ\'pɪtəmi/', 'epitome', 6);
INSERT INTO `words` VALUES (11541, NULL, 'v. 概括， 摘要', '/ɪ\'pɪtəmaɪz/', 'epitomize', 6);
INSERT INTO `words` VALUES (11542, 'the Victorian epoch', 'n. 新纪元, 时代, 时期, 时间上的一点, [地质]世', '/\'i:pɔk, \'epək | \'iːpɒk; \'epɒk | \'ɛpək/', 'epoch', 6);
INSERT INTO `words` VALUES (11543, 'a young man with a naturally equable temperament', 'adj. 变动小的, 平静的', '/\'ekwəbl | \'ekwəb(ə)l | \'ɛkwəbl/', 'equable', 6);
INSERT INTO `words` VALUES (11544, 'He received the news with surprising equanimity.', 'n. 镇定', '/,i:kwə\'niməti, ,e- | ,ekwə\'nɪmɪtɪ; iː- | ,ɛkwə\'nɪməti/', 'equanimity', 6);
INSERT INTO `words` VALUES (11545, 'I\'m always wary of men wearing suits, as I equate this with power and authority.', 'v. 认为…相等或相仿', '/i\'kweɪt | ɪ\'kwet/', 'equate', 6);
INSERT INTO `words` VALUES (11546, 'In the equation 2x + 1 = 7, what is x?', 'n. 等式； 等同， 相等', '/ɪ\'kweɪʒn | ɪ\'kweʒn/', 'equation', 6);
INSERT INTO `words` VALUES (11547, 'Knows(Those ) from south of the [ equator ] come to the United States during the northern winter .', 'n. 赤道', '/ɪ\'kweɪtər | ɪ\'kwetɚ/', 'equator', 6);
INSERT INTO `words` VALUES (11548, 'equestrian sports', 'adj. 骑马的；骑士阶层的; n. 骑师', '/ɪ\'kwestriən | ɪ\'kwɛstrɪən/', 'equestrian', 6);
INSERT INTO `words` VALUES (11549, 'The government is anxious not to upset the economic equilibrium.', 'n. 平衡, 平静, 均衡, 保持平衡的能力, 沉着, 安静', '/,i:kwi\'libriəm | ,iːkwɪ\'lɪbrɪəm; ,ekwɪ- | ,ikwɪ\'lɪbrɪəm/', 'equilibrium', 6);
INSERT INTO `words` VALUES (11550, '...an outbreak of equine influenza.', 'adj. 马的, 象马的', '/\'ekwain, \'i:- | \'iːkwaɪn; \'e- | \'ikwaɪn/', 'equine', 6);
INSERT INTO `words` VALUES (11551, 'an equitable distribution of food supplies', 'adj. 公平的, 公正的, 平衡法的', '/\'ekwitəbl | \'ekwɪtəb(ə)l/', 'equitable', 6);
INSERT INTO `words` VALUES (11552, 'We can admire the grassland scenery, equitation and watch the sunset.', 'n. 骑马, 骑术', '/,ekwi\'teiʃən | ,ekwɪ\'teɪʃ(ə)n/', 'equitation', 6);
INSERT INTO `words` VALUES (11553, 'a society run on the principles of equity and justice', 'n. 公平, 公正, 公平的事物, 资产净值, [律]平衡法', '/\'ekwəti | \'ekwɪtɪ | \'ɛkwəti/', 'equity', 6);
INSERT INTO `words` VALUES (11554, '...the equivalence of science and rationality.', 'n. 同等, [化]等价, 等值', '/i\'kwivələns | ɪ\'kwɪv(ə)l(ə)ns | ɪ\'kwɪvələns/', 'equivalence', 6);
INSERT INTO `words` VALUES (11555, 'I had no dollars, but offered him an equivalent amount of sterling.', 'adj. 相等的, 相当的, 同意义的', '/i\'kwivələnt | ɪ\'kwɪv(ə)l(ə)nt | ɪ\'kwɪvələnt/', 'equivalent', 6);
INSERT INTO `words` VALUES (11556, 'His answer was equivocal.', 'adj. 意义不明确的, 模棱两可的, 可疑的', '/i\'kwivəkəl | ɪ\'kwɪvək(ə)l | ɪ\'kwɪvəkl/', 'equivocal', 6);
INSERT INTO `words` VALUES (11557, 'He is equivocating a lot about what is going to happen if and when there are elections.', 'v. 说模棱两可的话, 支吾', '/ɪ\'kwɪvəkeɪt/', 'equivocate', 6);
INSERT INTO `words` VALUES (11558, NULL, 'n. 说模棱话的人， 说话支吾的人', '/i\'kwivəkeitə | ɪ\'kwɪvəkeɪtər/', 'equivocator', 6);
INSERT INTO `words` VALUES (11559, 'an attempt to eradicate inflation', 'v. 根除', '/i\'rædikeit | ɪ\'rædɪkeɪt | ɪ\'rædɪket/', 'eradicate', 6);
INSERT INTO `words` VALUES (11560, 'The computer crashed, and all our records were erased.', 'v. 抹去, 擦掉, 消磁, <俚>杀死', '/i\'reiz, i\'reis | ɪ\'reɪz | ɪ\'res/', 'erase', 6);
INSERT INTO `words` VALUES (11561, 'Martin stood erect on the platform.', 'adj. 竖立的， 笔直的', '/ɪ\'rekt | ɪ\'rɛkt/', 'erect', 6);
INSERT INTO `words` VALUES (11562, NULL, 'n. 遁世修行的人, 隐士', '/\'erimait | \'erɪmaɪt/', 'eremite', 6);
INSERT INTO `words` VALUES (11563, NULL, 'adj. 争论的, 好争论的', '/e\'ristik | e\'rɪstɪk/', 'eristic', 6);
INSERT INTO `words` VALUES (11564, 'The cliffs are being constantly eroded by heavy seas.', 'v. 侵蚀, 腐蚀, 使变化', '/i\'rəud | ɪ\'rəʊd | ɪ\'rod/', 'erode', 6);
INSERT INTO `words` VALUES (11565, 'the problem of soil erosion', 'n. 腐蚀, 侵蚀', '/i\'rəuʒən | ɪ\'rəʊʒ(ə)n | ɪ\'roʒən/', 'erosion', 6);
INSERT INTO `words` VALUES (11566, 'an erotic dream', 'adj. 性爱的, 性欲的, 色情的', '/i\'rɔtik | ɪ\'rɒtɪk | ɪ\'rɑtɪk/', 'erotic', 6);
INSERT INTO `words` VALUES (11567, 'They can view a list of errands that match their interest profile, and, by entering a price, can bid to perform the errand.', 'n. 差事, 差使, 使命', '/\'erənd | \'er(ə)nd | \'ɛrənd/', 'errand', 6);
INSERT INTO `words` VALUES (11568, 'Usually his cases involved errant husbands and wandering wives.', 'adj. 周游的, 不定的, 错误的', '/\'erənt | \'er(ə)nt | \'ɛrənt/', 'errant', 6);
INSERT INTO `words` VALUES (11569, 'His breathing was becoming erratic.', 'adj. 无确定路线, 不稳定的, 奇怪的', '/i\'rætik | ɪ\'rætɪk/', 'erratic', 6);
INSERT INTO `words` VALUES (11570, NULL, 'adv. 不规律地， 不定地', '/i\'rætikli | ɪ\'rætɪkli/', 'erratically', 6);
INSERT INTO `words` VALUES (11571, 'ersatz coffee', 'adj. 代用的,合成的,假的,人造的', '/\'εəzæts | \'ɜːsæts; \'eə- | \'ɛrsɑts/', 'ersatz', 6);
INSERT INTO `words` VALUES (11572, 'There’s also the intrinsic pleasure you get from boosting your knowledge and becoming more erudite.', 'adj. 博学的', '/\'eru:dait | \'erʊdaɪt | \'ɛrudaɪt/', 'erudite', 6);
INSERT INTO `words` VALUES (11573, 'His erudition was apparently endless.', 'n. 博学', '/,eru:\'diʃən | ,erʊ\'dɪʃ(ə)n | ,ɛru\'dɪʃən/', 'erudition', 6);
INSERT INTO `words` VALUES (11574, 'The volcano erupted in 1980, devastating a large area of Washington state.', 'v. 喷出', '/i\'rʌpt | ɪ\'rʌpt/', 'erupt', 6);
INSERT INTO `words` VALUES (11575, 'The last eruption of this volcano lasted over a year, so this cannot be ruled out.', 'n. 爆发, 火山灰, [医]出疹', '/i\'rʌpʃən | ɪ\'rʌpʃ(ə)n | ɪ\'rʌpʃən/', 'eruption', 6);
INSERT INTO `words` VALUES (11576, 'The costs were escalating alarmingly.', 'v. 逐步升高, 逐步增强', '/\'eskəleit | \'eskəleɪt | \'ɛskəlet/', 'escalate', 6);
INSERT INTO `words` VALUES (11577, NULL, 'n. 逐步上升， 逐步扩大', '/ˌeskə\'leɪʃn | ,ɛskə\'leʃən/', 'escalation', 6);
INSERT INTO `words` VALUES (11578, 'Books were a form of escapism from the real world.', 'n. 逃避现实', '/ɪ\'skeɪpɪzəm | ɪ\'skepɪzəm/', 'escapism', 6);
INSERT INTO `words` VALUES (11579, 'I had eschewed politics in favour of a life practising law.', 'v. 避开, 远避', '/is\'tʃu: | ɪs\'tʃuː; es- | ɪsˈtʃuː/', 'eschew', 6);
INSERT INTO `words` VALUES (11580, 'a police escort', 'n. 护卫(队), 护送, 陪同(人员), 护卫队', '/\'eskɔ:t, i\'skɔ:t | \'eskɔːt | ˈeskɔːrt/', 'escort', 6);
INSERT INTO `words` VALUES (11581, 'BHA Cell Differential Agent is extracted through botanic extraction technology of Japan macromolecule energy. It is a kind of esculent products with very strong ability to differentiate melanocyte .', 'adj. 可食用的', '/\'eskjʊlənt | \'eskjulənt/', 'esculent', 6);
INSERT INTO `words` VALUES (11582, 'the esoteric world of scientific supercomputing', 'adj. 深奥', '/,esəu\'terik | ,esə\'terɪk; ,iːsə- | ,ɛsə\'tɛrɪk/', 'esoteric', 6);
INSERT INTO `words` VALUES (11583, 'a campaign of industrial espionage against his main rival', 'n. 间谍, 侦探', '/,espiə\'nɑ:ʒ, \'espiənidʒ | \'espɪənɑːʒ; -ɪdʒ | \'ɛspɪənɑʒ/', 'espionage', 6);
INSERT INTO `words` VALUES (11584, '...the Slovene leadership\'s espousal of reform and nationalism.', 'n. 订婚, 婚礼, 拥护', '/i\'spauzəl | ɪ\'spaʊz(ə)l; e-/', 'espousal', 6);
INSERT INTO `words` VALUES (11585, 'She ran away with him to Mexico and espoused the revolutionary cause.', 'v. 嫁娶, 支持, 赞成', '/i\'spauz | ɪ\'spaʊz; e- | ɪ\'spaʊz/', 'espouse', 6);
INSERT INTO `words` VALUES (11586, 'Here, from a window, did Guinevere espy a knight standing in a woodman\'s cart.', 'v. 看到', '/i\'spai | ɪ\'spaɪ; e-/', 'espy', 6);
INSERT INTO `words` VALUES (11587, 'Ballet is essentially a middle-class interest.', 'adv. 本质上； 基本上', '/ɪ\'senʃəli | ɪ\'sɛnʃəli/', 'essentially', 6);
INSERT INTO `words` VALUES (11588, 'The establishment of the regional government in 1980 did not end terrorism.', 'n. 确立, 制定, 设施, 公司, 军事组织', '/i\'stæbliʃmənt | ɪ\'stæblɪʃm(ə)nt; e- | ɪ\'stæblɪʃmənt/', 'establishment', 6);
INSERT INTO `words` VALUES (11589, 'His estate was valued at $150,000.', 'n. 状态, 不动产, 时期, 阶层, 财产', '/ɪ\'steɪt; e- | ɪ\'stet/', 'estate', 6);
INSERT INTO `words` VALUES (11590, '...the estimable Miss Cartwright.', 'adj. 可尊敬的, 可估计的, <古>可贵的, 有价值的', '/\'estiməbl | \'estɪməb(ə)l | \'ɛstɪməbl/', 'estimable', 6);
INSERT INTO `words` VALUES (11591, 'As to her own life, those good friends for years gradually estrange since she\'s always on the run. And there\'s still a void in her love life.', 'v. 疏远', '/i\'streindʒ | ɪ\'streɪn(d)ʒ; e-/', 'estrange', 6);
INSERT INTO `words` VALUES (11592, 'Joanna spent most of her twenties virtually estranged from her father.', 'adj. 疏远的， 不和的', '/ɪ\'streɪndʒd | ɪ\'strendʒd/', 'estranged', 6);
INSERT INTO `words` VALUES (11593, 'The trip will bring to an end years of estrangement between the two countries.', 'n. 疏远', '/is\'treindʒmənt | ɪ\'streɪn(d)ʒm(ə)nt; e- | ɪ\'strendʒmənt/', 'estrangement', 6);
INSERT INTO `words` VALUES (11594, 'the Thames estuary', 'n. 河口, 江口', '/\'estjuəri | \'estjʊ(ə)rɪ | \'ɛstʃʊ\'ɛri/', 'estuary', 6);
INSERT INTO `words` VALUES (11595, NULL, 'n. 贪心,贪婪', '/i\'sjuəriəns,-ənsi/', 'esurience', 6);
INSERT INTO `words` VALUES (11596, 'A laser is used to etch a pattern in the smooth surface of the disc.', 'v. 蚀刻', '/etʃ | ɛtʃ/', 'etch', 6);
INSERT INTO `words` VALUES (11597, NULL, 'n. 蚀刻版画, 蚀刻术, 铜版画', '/\'etʃiŋ | \'etʃɪŋ | \'ɛtʃɪŋ/', 'etching', 6);
INSERT INTO `words` VALUES (11598, 'the Christian promise of eternal life', 'adj. 永久的， 永恒的', '/ɪ\'tɜːrnl | ɪ\'tɝnl/', 'eternal', 6);
INSERT INTO `words` VALUES (11599, 'ethereal beauty', 'adj. 轻的, 天上的, 象空气的', '/ɪ\'θɪərɪəl | ɪ\'θɪrɪəl/', 'ethereal', 6);
INSERT INTO `words` VALUES (11600, NULL, 'v. <美>[医]以醚麻醉, 化成为醚', '/\'i:θəraiz | \'iːθ(ə)raɪz/', 'etherize', 6);
INSERT INTO `words` VALUES (11601, 'Refugee workers said such action was a violation of medical ethics.', 'n. 伦理学； 道德规范', '/\'eθɪks | ‘ɛθɪks/', 'ethics', 6);
INSERT INTO `words` VALUES (11602, 'The school teaches pupils from different ethnic groups.', 'adj. 民族的， 种族的', '/\'eθnɪk | \'ɛθnɪk/', 'ethnic', 6);
INSERT INTO `words` VALUES (11603, NULL, 'n. 民族志学, 人种学, 人种志', '/eθ\'nɔɡrəfi | eθ\'nɒgrəfɪ | ɛθ\'nɑgrəfi/', 'ethnography', 6);
INSERT INTO `words` VALUES (11604, 'a community in which people lived according to an ethos of sharing and caring', 'n. 气质, 道义, 民族精神, 社会思潮, 风气', '/\'i:θɔs | \'iːθɒs | \'iθɑs/', 'ethos', 6);
INSERT INTO `words` VALUES (11605, 'strict rules of professional etiquette', 'n. 礼节', '/\'etiket | \'etɪket; etɪ\'ket | \'ɛtɪkɛt/', 'etiquette', 6);
INSERT INTO `words` VALUES (11606, 'From the etymology speaking, anthropology is the study of science.', 'n. 语源, 语源学', '/,eti\'mɔlədʒi | ,etɪ\'mɒlədʒɪ | ,ɛtɪ\'mɑlədʒi/', 'etymology', 6);
INSERT INTO `words` VALUES (11607, 'For skin under and around noses that are irritated by too much blowing, menthol and eucalyptus can relieve pain.', 'n. [植]桉树', '/,ju:kə\'liptəs | ,juːkə\'lɪptəs | ,jukə\'lɪptəs/', 'eucalyptus', 6);
INSERT INTO `words` VALUES (11608, 'The author thinks that chromosomal abnormality is of importance to causing spontaneous abortion and puts foward a series of proposals on eugenic.', 'adj. 优生的, 优生学的', '/ju:\'dʒenik,-kəl | juː\'dʒenɪk/', 'eugenic', 6);
INSERT INTO `words` VALUES (11609, NULL, 'adj. 颂扬的,歌功颂德', '/,ju:lə\'dʒistik,-kəl | ,juːlə\'dʒɪstɪk/', 'eulogistic', 6);
INSERT INTO `words` VALUES (11610, 'The poem does not eulogize the dead soldiers.', 'v. 称赞， 颂扬', '/\'juːlədʒaɪz | \'jʊlə\'dʒaɪz/', 'eulogize', 6);
INSERT INTO `words` VALUES (11611, 'The minister delivered a long eulogy.', 'n. 赞词, 颂词, 歌功颂德的话', '/\'ju:lədʒi | \'juːlədʒɪ | \'jʊlədʒi/', 'eulogy', 6);
INSERT INTO `words` VALUES (11612, '‘Pass away’ is a euphemism for ‘die’.', 'n. [语法]委婉的说法', '/\'ju:fimizəm | \'juːfəmɪz(ə)m | \'jufəmɪzəm/', 'euphemism', 6);
INSERT INTO `words` VALUES (11613, '...a euphemistic way of saying that someone has been lying.', 'adj. 委婉的', '/ˌjuːfə\'mɪstɪk | ,jʊfə\'mɪstɪk/', 'euphemistic', 6);
INSERT INTO `words` VALUES (11614, 'The sound of whistle is euphonious , emotional, and melodic.', 'adj. 悦耳', '/ju:\'fəuniəs | juː\'fəʊnɪəs | ju\'fonɪəs/', 'euphonious', 6);
INSERT INTO `words` VALUES (11615, 'Even the too-near table of boisterous boys contributes to its euphony.', 'n. 悦耳之音', '/\'ju:fəni | \'juːf(ə)nɪ | \'jʊfəni/', 'euphony', 6);
INSERT INTO `words` VALUES (11616, NULL, 'n. 愉快的心情', '/juː\'fɔːriə | jʊ\'fɔrɪə/', 'euphoria', 6);
INSERT INTO `words` VALUES (11617, NULL, 'adj. 欢欣的', '/juː\'fɔːrɪk | jʊ\'fɔrɪk/', 'euphoric', 6);
INSERT INTO `words` VALUES (11618, NULL, 'adj. 音乐舞蹈体操的', '/ju:\'riðmik,-kəl/', 'eurhythmic', 6);
INSERT INTO `words` VALUES (11619, 'They were planning to evacuate the seventy American officials still in the country.', 'v. 疏散, 撤出, 排泄', '/i\'vækjueit | ɪ\'vækjʊeɪt | ɪ\'vækjuet/', 'evacuate', 6);
INSERT INTO `words` VALUES (11620, 'You can’t go on evading your responsibilities in this way.', 'v. 规避, 逃避, 躲避', '/i\'veid | ɪ\'veɪd | ɪ\'ved/', 'evade', 6);
INSERT INTO `words` VALUES (11621, 'We need to carry out a proper evaluation of the new system.', 'n. 评价， 评估', '/ɪˌvælju\'eɪʃn | ɪ,væljʊ\'eʃən/', 'evaluation', 6);
INSERT INTO `words` VALUES (11622, '...the evanescent scents of summer herbs.', 'adj. 渐消失的, 易消散的, 会凋零的', '/,i:və\'nesənt | iːvə\'nes(ə)nt; ev- | ,ɛvə\'nɛsnt/', 'evanescent', 6);
INSERT INTO `words` VALUES (11623, 'I’m tired of his lies and evasions.', 'n. 躲避， 借口', '/ɪ\'veɪʒn | ɪ\'veʒn/', 'evasion', 6);
INSERT INTO `words` VALUES (11624, 'an evasive reply', 'adj. 逃避的, 推托的', '/i\'veisiv | ɪ\'veɪsɪv | ɪ\'vesɪv/', 'evasive', 6);
INSERT INTO `words` VALUES (11625, 'The floor must be completely even before we lay the tiles.', 'adj. 平的, 平滑的, 偶数的, 一致的, 平静的, 恰好的, 平均的, 连贯的', '/\'i:vən | \'iːv(ə)n | \'ivən/', 'even', 6);
INSERT INTO `words` VALUES (11626, 'Charles had been described as a gentle and even-tempered man.', 'adj. 性情平和的； 不易生气的', '/ˌiːvn\'tempərd | \'i:vən\'tempəd/', 'even-tempered', 6);
INSERT INTO `words` VALUES (11627, '...an evenhanded approach to the war on drugs.', 'adj. 公平的， 不偏不倚的', '/\'iːvn\'hændɪd | \'i:vən\'hændid/', 'evenhanded', 6);
INSERT INTO `words` VALUES (11628, 'She’s led an eventful life.', 'adj. 多事的； 重要的', '/ɪ\'ventfl | ɪ\'vɛntfl/', 'eventful', 6);
INSERT INTO `words` VALUES (11629, 'Sweden were the eventual winners of the tournament.', 'adj. 最终的', '/ɪ\'ventʃuəl | i\'ventʃuəl/', 'eventual', 6);
INSERT INTO `words` VALUES (11630, 'Plant evergreen shrubs around the end of the month.', 'adj. 常绿的', '/\'evərgriːn | \'ɛvɚɡrin/', 'evergreen', 6);
INSERT INTO `words` VALUES (11631, 'everlasting fame', 'adj. 永恒的， 永久的； 无休止的', '/ˌevər\'læstɪŋ | ,ɛvɚ\'læstɪŋ/', 'everlasting', 6);
INSERT INTO `words` VALUES (11632, 'They were evicted from their apartment after their mother became addicted to drugs.', 'v. 驱逐, 逐出(租户), 收回(租屋、租地等)', '/i\'vikt | ɪ\'vɪkt/', 'evict', 6);
INSERT INTO `words` VALUES (11633, 'an evil dictator responsible for the deaths of millions', 'adj. 邪恶的，罪恶的; n. 坏事， 恶行', '/\'iːvl | \'ivl/', 'evil', 6);
INSERT INTO `words` VALUES (11634, 'She evinced no surprise at seeing them together.', 'v. 表明, 表示', '/i\'vins | ɪ\'vɪns/', 'evince', 6);
INSERT INTO `words` VALUES (11635, '...strangling and eviscerating rabbits for the pot.', 'v. 取出内脏, 除去精华, 除去主要部分', '/i\'visəreit | ɪ\'vɪsəreɪt | ɪ\'vɪsəret/', 'eviscerate', 6);
INSERT INTO `words` VALUES (11636, 'evocative music', 'adj. 唤出的, 唤起的', '/i\'vɔkətiv | ɪ\'vɒkətɪv | ɪ\'vɑkətɪv/', 'evocative', 6);
INSERT INTO `words` VALUES (11637, 'The photographs evoked strong memories of our holidays in France.', 'v. 唤起, 引起, 博得', '/i\'vəuk | ɪ\'vəʊk | ɪ\'vok/', 'evoke', 6);
INSERT INTO `words` VALUES (11638, 'Through the open door you see a red-tiled floor, a large wooden bed, and on a deal table a ewer and a basin.', 'n. 大口水罐', '/\'ju（:）ə | \'juːə | \'jʊɚ/', 'ewer', 6);
INSERT INTO `words` VALUES (11639, 'The recession has exacerbated this problem.', 'v. 恶化, 增剧, 激怒, 使加剧, 使烦恼', '/ek\'sæsəbeit, iɡz- | ɪg\'zæsəbeɪt; ek\'sæs- | ɪɡ\'zæsɚbet/', 'exacerbate', 6);
INSERT INTO `words` VALUES (11640, 'She was an exacting woman to work for.', 'adj. 苛求的, 严格的, 吃力的, 需付出极大耐心', '/iɡ\'zæktiŋ | ɪg\'zæktɪŋ; eg-/', 'exacting', 6);
INSERT INTO `words` VALUES (11641, 'All was, alas, worse than vanity - injustice, punishment, exaction, death.', 'n. 勒索, 苛求', '/iɡ\'zækʃən | ɪg\'zækʃ(ə)n; eg-/', 'exaction', 6);
INSERT INTO `words` VALUES (11642, '...the precision and exactitude of current genetic mapping.', 'n. 正确， 精确， 严格', '/ɪg\'zæktɪtuːd | ɪɡ\'zæktɪtud/', 'exactitude', 6);
INSERT INTO `words` VALUES (11643, 'I couldn’t sleep for three days – I’m not exaggerating.', 'v. 夸大, 夸张', '/iɡ\'zædʒəreit | ɪg\'zædʒəreɪt; eg- | ɪɡ\'zædʒəret/', 'exaggerate', 6);
INSERT INTO `words` VALUES (11644, 'It would be an exaggeration to say that we were close friends.', 'n. 夸张, 夸大之词', '/iɡ,zædʒə\'reiʃən | ɪg,zædʒə\'reɪʃ(ə)n | ɪɡ,zædʒə\'reʃən/', 'exaggeration', 6);
INSERT INTO `words` VALUES (11645, 'But it can also inspire and uplift and exalt, because power can be used to help people accomplish marvelous things.', 'v. 晋升', '/iɡ\'zɔ:lt | ɪg\'zɔːlt; eg- | ɪɡ\'zɔlt/', 'exalt', 6);
INSERT INTO `words` VALUES (11646, 'The city was swept up in the mood of exaltation.', 'n. 提升, 提高, 兴奋, 得意洋洋', '/,eɡzɔ:l\'teiʃən | egzɔːl\'teɪʃ(ə)n; eks- | ,ɛɡzɔl\'teʃən/', 'exaltation', 6);
INSERT INTO `words` VALUES (11647, 'I felt shy in such exalted company.', 'adj. 崇高的， 高贵的', '/ɪg\'zɔːltɪd | ɪg\'zɔltɪd/', 'exalted', 6);
INSERT INTO `words` VALUES (11648, 'It exasperates me to hear comments like that.', 'v. 激怒', '/iɡ\'zæspəreit, -\'zɑ:s- | ɪg\'zæsp(ə)reɪt; eg- | ɪɡ\'zæspəret/', 'exasperate', 6);
INSERT INTO `words` VALUES (11649, 'Carol sighed in exasperation.', 'n. 恼怒', '/iɡ,zæspə\'reiʃən, -,zɑ:s- | ɪg,zæspə\'reɪʃ(ə)n | ɪg,zæspə\'reʃ(ə)n/', 'exasperation', 6);
INSERT INTO `words` VALUES (11650, 'Schliemann excavated the ancient city of Troy.', 'v. 挖掘, 开凿, 挖出, 挖空', '/\'ekskə,veit | \'ekskəveɪt | \'ɛkskə\'vet/', 'excavate', 6);
INSERT INTO `words` VALUES (11651, NULL, 'n. 挖掘, 发掘, 挖掘成的洞, 出土文物', '/,ekskə\'veiʃən | ekskə\'veɪʃ(ə)n | ,ɛkskə\'veʃən/', 'excavation', 6);
INSERT INTO `words` VALUES (11652, 'Working hours must not exceed 42 hours a week.', 'v. 超越, 胜过', '/ik\'si:d | ɪk\'siːd; ek- | ɪk\'sid/', 'exceed', 6);
INSERT INTO `words` VALUES (11653, 'Thank you. You’ve been exceedingly kind.', 'adv. 非常地, 极度地', '/ik\'si:diŋli | ɪk\'siːdɪŋlɪ; ek- | ɪk\'sidɪŋli/', 'exceedingly', 6);
INSERT INTO `words` VALUES (11654, 'You have excelled yourself with the new exhibition.', 'v. 优秀, 胜过他人', '/ik\'sel | ɪk\'sel; ek- | ɪk\'sɛl/', 'excel', 6);
INSERT INTO `words` VALUES (11655, 'It’s been cold, but today’s an exception.', 'n. 除外, 例外, 反对, 异议', '/ik\'sepʃən | ɪk\'sepʃ(ə)n; ek- | ɪk\'sɛpʃən/', 'exception', 6);
INSERT INTO `words` VALUES (11656, NULL, 'adj. 可反对的, 可抗议的, 要不得的', '/ik\'sepʃənəbl | ɪk\'sepʃ(ə)nəb(ə)l; ek-/', 'exceptionable', 6);
INSERT INTO `words` VALUES (11657, 'an exceptional student', 'adj. 例外的, 异常的', '/ik\'sepʃənəl | ɪk\'sepʃ(ə)n(ə)l; ek- | ɪk\'sɛpʃənl/', 'exceptional', 6);
INSERT INTO `words` VALUES (11658, '...an excerpt from Tchaikovsky\'s Nutcracker.', 'n. 摘录， 选录， 节录', '/\'eksɜːrpt | \'ɛksɝpt/', 'excerpt', 6);
INSERT INTO `words` VALUES (11659, 'After you apply the oil, wait 20 minutes before wiping off any excess.', 'n. 过分， 过度', '/ɪk\'ses | \'ɛk\'sɛs/', 'excess', 6);
INSERT INTO `words` VALUES (11660, 'his excessive drinking', 'adj. 过度的， 过分的', '/ɪk\'sesɪv | ɪkˈsɛsɪv/', 'excessive', 6);
INSERT INTO `words` VALUES (11661, 'Do not whine or complain excessively.', 'adv. 过度地', '/ɪk\'sesɪvli | ɪk\'sɛsɪvli/', 'excessively', 6);
INSERT INTO `words` VALUES (11662, NULL, 'n. [英史]财物署, 国库, 财源, 财政部', '/iks\'tʃekə, \'eks- | ɪks\'tʃekə; eks- | ɪks\'tʃɛkɚ/', 'exchequer', 6);
INSERT INTO `words` VALUES (11663, '...this year\'s rise in excise duties.', 'n. 消费税, 货物税, 国产税', '/\'eksaiz, ek\'s-, ek\'saiz | \'eksaɪz | ɛk\'saɪz/', 'excise', 6);
INSERT INTO `words` VALUES (11664, NULL, 'n. 切除, 删除, [医]切除(术), [宗]逐出教会', '/ek\'siʒən | ɪk\'sɪʒ(ə)n; ek- | ɪk\'sɪʒən/', 'excision', 6);
INSERT INTO `words` VALUES (11665, NULL, 'n. 易兴奋， 易激动', '/ɪkˌsaɪtə\'bɪləti | ɪk,saɪtə\'bɪləti/', 'excitability', 6);
INSERT INTO `words` VALUES (11666, 'His playing is technically brilliant, but it doesn’t excite me.', 'v. 激发； 使动感情， 使激动 ； 使增加能量', '/ɪk\'saɪt/', 'excite', 6);
INSERT INTO `words` VALUES (11667, '‘No!’ she exclaimed in shock.', 'v. 惊叫， 呼喊', '/ɪk\'skleɪm | ɪk\'sklem/', 'exclaim', 6);
INSERT INTO `words` VALUES (11668, 'Sue gave an exclamation as we got a clear sight of the house.', 'n. 惊叹词； 惊呼', '/ˌeksklə\'meɪʃn | ˌɛkskləˈmeʃən/', 'exclamation', 6);
INSERT INTO `words` VALUES (11669, 'Your essays tend to concentrate on one theme to the exclusion of everything else.', 'n. 排除, 除外, 被排除在外的事物', '/ik\'sklu:ʒən | ɪk\'skluːʒ(ə)n; ek- | ɪk\'skluʒn/', 'exclusion', 6);
INSERT INTO `words` VALUES (11670, 'Bel Air is an exclusive suburb of Los Angeles.', 'adj. 排外的, 孤高的, 唯我独尊的, 独占的, 唯一的, 高级的', '/ik\'sklu:siv | ɪk\'skluːsɪv; ek- | ɪk\'sklusɪv/', 'exclusive', 6);
INSERT INTO `words` VALUES (11671, NULL, 'v. 想出, 研究出, 设计, 发明', '/eks\'kɔdʒiteit | ɪks\'kɒdʒɪteɪt; eks- | ɛks\'kɑdʒə,tetɪv/', 'excogitate', 6);
INSERT INTO `words` VALUES (11672, 'an excoriating review in ‘The Times’', 'v. 批判', '/ek\'skɔ:rieit | ɪk\'skɔːrɪeɪt; eks- | ,ɛks\'kɔrɪet/', 'excoriate', 6);
INSERT INTO `words` VALUES (11673, 'Your open pores excrete sweat and dirt.', 'v. 排泄， 分泌', '/ɪk\'skriːt | ɪk\'skrit/', 'excrete', 6);
INSERT INTO `words` VALUES (11674, NULL, 'v. 施酷刑； 折磨', '/ɪk\'skruːʃieɪt | ik\'skru:ʃieit/', 'excruciate', 6);
INSERT INTO `words` VALUES (11675, 'When I bend my arm, the pain is excruciating.', 'adj. 极痛苦的, 折磨人的', '/ik\'skru:ʃieitiŋ | ɪk\'skruːʃɪeɪtɪŋ | ɪk\'skruʃɪetɪŋ/', 'excruciating', 6);
INSERT INTO `words` VALUES (11676, 'The writer of the news made all efforts to find some reasons to exculpate Yao Jiaxin.', 'v. 开脱', '/\'ekskʌlpeit | \'ekskʌlpeɪt/', 'exculpate', 6);
INSERT INTO `words` VALUES (11677, 'a shopping excursion', 'n. 远足, 游览, 短程旅行, 远足队, 离题, [物]偏移, 漂移', '/ɪk\'skɜːʃ(ə)n; ek- | ɪk\'skɝʒn/', 'excursion', 6);
INSERT INTO `words` VALUES (11678, NULL, 'adj. 离题的', '/ɪks\'kɜːrsɪv/', 'excursive', 6);
INSERT INTO `words` VALUES (11679, 'Accusing us of being disloyal to cover his own sorry behaviour is truly execrable.', 'adj. 该咒的, 可憎恨的, 讨厌的, 恶劣的, 坏透的', '/\'eksikrəbl | \'eksɪkrəb(ə)l | \'ɛksɪkrəbl/', 'execrable', 6);
INSERT INTO `words` VALUES (11680, NULL, 'v. 痛骂, 憎恨, 憎恶, 诅咒', '/\'eksikreit | \'eksɪkreɪt | \'ɛksɪˌkret/', 'execrate', 6);
INSERT INTO `words` VALUES (11681, '13 people were summarily executed (= killed without any trial or legal process ) by the guerrillas.', 'v. 执行， 履行； 将处死', '/\'eksɪkjuːt | \'ɛksɪkjut/', 'execute', 6);
INSERT INTO `words` VALUES (11682, NULL, 'n. 死刑执行人, 刽子手', '/,eksi\'kju:ʃənə | eksɪ\'kjuːʃ(ə)nə | \'ɛksɪ\'kjʊʃənɚ/', 'executioner', 6);
INSERT INTO `words` VALUES (11683, 'a commission with executive powers', 'adj. 实行的, 执行的, 行政的', '/ɪg\'zekjʊtɪv; eg- | ɪɡ\'zɛkjətɪv/', 'executive', 6);
INSERT INTO `words` VALUES (11684, 'You don’t have to be the executor of the full idea, but as a problem solver, you have some responsibility for implementing the solution.', 'n. 被指定遗嘱执行者, 执行者', '/\'eksikju:tə | ɪg\'zekjʊtə; eg- | ɪg\'zɛkjətɚ/', 'executor', 6);
INSERT INTO `words` VALUES (11685, '...the kind of academic exegesis at which Isaacs excels.', 'n. 注释, 解释', '/,eksi\'dʒi:sis | ,eksɪ\'dʒiːsɪs | \'ɛksə\'dʒisɪs/', 'exegesis', 6);
INSERT INTO `words` VALUES (11686, 'They viewed their new building as an exemplar of taste.', 'n. 模范， 榜样', '/ɪg\'zemplɑːr | ɪɡ\'zɛmplɑr/', 'exemplar', 6);
INSERT INTO `words` VALUES (11687, 'a company with an exemplary record on environmental issues', 'adj. 模范的， 典范的； 可仿效的', '/ɪg\'zempləri | ɪɡ\'zɛmpləri/', 'exemplary', 6);
INSERT INTO `words` VALUES (11688, 'The building exemplifies the style of architecture which was popular at the time.', 'v. 是…的典型， 作为…例子', '/ɪg\'zemplɪfaɪ | ɪɡ\'zɛmplɪfaɪ/', 'exemplify', 6);
INSERT INTO `words` VALUES (11689, 'So we have the current argument over how much of the derivative market will be exempt from regulation.', 'v. 免除', '/iɡ\'zempt | ɪg\'zem(p)t; eg- | ɪg\'zɛmpt/', 'exempt', 6);
INSERT INTO `words` VALUES (11690, 'You qualify for a tax exemption on the loan.', 'n. 解除, 免除, 免税', '/iɡ\'zempʃən | ɪɡ\'zempʃn | ɪg\'zɛmpʃən/', 'exemption', 6);
INSERT INTO `words` VALUES (11691, 'He has exerted himself tirelessly on behalf of the charity.', 'v. 尽(力), 施加(压力等), 努力', '/iɡ\'zə:t | ɪg\'zɜːt; eg- | ɪɡ\'zɝt/', 'exert', 6);
INSERT INTO `words` VALUES (11692, 'The afternoon’s exertions had left us feeling exhausted.', 'n. 尽力, 努力, 发挥, 行使, 运用', '/iɡ\'zə:ʃən | ɪɡ\'zɜːʃn | ɪɡ\'zɝʃən/', 'exertion', 6);
INSERT INTO `words` VALUES (11693, 'Take a deep breath, then exhale slowly.', 'v. 呼气, 发出, 发散, <古>使蒸发', '/eks\'heil | ɪks\'heɪl; eks- | ɛks\'hel/', 'exhale', 6);
INSERT INTO `words` VALUES (11694, 'A full day’s teaching exhausts me.', 'v. 耗尽；使筋疲力尽; n. 废气', '/ɪg\'zɔːst | ɪɡ\'zɔst/', 'exhaust', 6);
INSERT INTO `words` VALUES (11695, 'Sheer exhaustion forced him to give up.', 'n. 耗尽枯竭, 疲惫, 筋疲力尽, 竭尽, 详尽无遗的论述', '/iɡ\'zɔ:stʃən | ɪg\'zɔːstʃ(ə)n; eg- | ɪg\'zɔstʃən/', 'exhaustion', 6);
INSERT INTO `words` VALUES (11696, 'an exhaustive investigation', 'adj. 无遗漏的, 彻底的, 详尽的, 无遗的', '/iɡ\'zɔ:stiv | ɪg\'zɔːstɪv; eg- | ɪg\'zɔstɪv/', 'exhaustive', 6);
INSERT INTO `words` VALUES (11697, NULL, 'n. 全面, 详尽， 彻底', '/iɡ,zɔ:\'stivəti | ɪg\'zɔːstɪvnəs/', 'exhaustiveness', 6);
INSERT INTO `words` VALUES (11698, 'There is an element of exhibitionism in the parents\' performance too.', 'n. 自我宣传癖, 喜出风头癖, 裸露癖', '/,eksi\'biʃənizəm | eksɪ\'bɪʃ(ə)nɪz(ə)m | ,ɛksɪ\'bɪʃənɪzəm/', 'exhibitionism', 6);
INSERT INTO `words` VALUES (11699, 'It began with my attendance at fetish parties last September; because I’m an exhibitionist, I allowed the photographers there to capture me being wrapped in rope or strung up from the ceiling.', 'n. 倾向自我宣传的人, 裸露症患者', '/,eksi\'biʃənist | ,ɛksɪ\'bɪʃənɪst/', 'exhibitionist', 6);
INSERT INTO `words` VALUES (11700, NULL, 'v. 使高兴, 使愉快', '/iɡ\'ziləreit | ɪg\'zɪləreɪt; eg- | ɪɡ\'zɪləret/', 'exhilarate', 6);
INSERT INTO `words` VALUES (11701, 'an exhilarating experience', 'adj. 令人喜欢的, 爽快的, 使人愉快的', '/iɡ\'ziləreitiŋ | ɪg\'zɪləreɪtɪŋ; eg- | ɪɡ\'zɪləretɪŋ/', 'exhilarating', 6);
INSERT INTO `words` VALUES (11702, 'It might be the exhilaration of that potent cordial, which is distilled only in the furnace-glow of earnest and long-continued thought.', 'n. 高兴， 兴奋', '/ɪgˌzɪlə\'reɪʃn | ɪg,zɪlə\'reʃən/', 'exhilaration', 6);
INSERT INTO `words` VALUES (11703, 'Kennedy exhorted his listeners to turn away from violence.', 'v. 劝诫, 忠告', '/iɡ\'zɔ:t | ɪg\'zɔːt; eg- | ɪɡ\'zɔrt/', 'exhort', 6);
INSERT INTO `words` VALUES (11704, NULL, 'n. 劝告, 讲道词, 训词', '/,eɡzɔ:\'teiʃən | egzɔː\'teɪʃ(ə)n | ,ɛgzɔr\'teʃən/', 'exhortation', 6);
INSERT INTO `words` VALUES (11705, 'His remains have been exhumed from a cemetery in Queens.', 'v. 掘出, 发掘', '/eks\'hju:m | eks\'(h)juːm; ɪg\'zjuːm | ɪɡ\'zum/', 'exhume', 6);
INSERT INTO `words` VALUES (11706, NULL, 'n. 紧急要求， 迫切需要', '/\'eksɪdʒənsi | \'ɛksədʒənsi/', 'exigency', 6);
INSERT INTO `words` VALUES (11707, 'To explain the current tense physician-patient relationship is an exigent social problem.', 'adj. 迫切的， 紧急的', '/\'eksɪdʒənt | \'eksidʒənt/', 'exigent', 6);
INSERT INTO `words` VALUES (11708, 'exiguous earnings', 'adj. 稀少的, 细小的, 些须的', '/eɡ\'ziɡjuəs | ɪg\'zɪgjʊəs; eg- | ɛɡ\'zɪɡjuəs/', 'exiguous', 6);
INSERT INTO `words` VALUES (11709, 'political exiles', 'n. 放逐, 充军, 流放, 流犯, 被放逐者', '/\'eɡzail, \'eksail | \'eksaɪl; \'egz- | \'ɛksaɪl/', 'exile', 6);
INSERT INTO `words` VALUES (11710, 'The medical system is facing collapse because of an exodus of doctors.', 'n. 大批的离去, [the E-](古代以色列人)出埃及', '/\'eksədəs | \'ɛksədəs/', 'exodus', 6);
INSERT INTO `words` VALUES (11711, 'But, owing to the nature of ancient kinship, as we have seen it, exogamy afforded no proper security against the intermixture of persons near of kin.', 'n. 异族结婚', '/ek\'sɔɡəmi | ɪk\'sɒgəmɪ; ek- | ɛk\'sɑɡəmi/', 'exogamy', 6);
INSERT INTO `words` VALUES (11712, 'The official report basically exonerated everyone.', 'v. 免除, 证明无罪', '/iɡ\'zɔnəreit | ɪg\'zɒnəreɪt; eg- | ɪɡ\'zɑnəret/', 'exonerate', 6);
INSERT INTO `words` VALUES (11713, 'T-Bag wants exoneration for his help.', 'n. 免除', '/iɡ,zɔnə\'reiʃən | ɪgˌzɑːnə\'reɪʃn/', 'exoneration', 6);
INSERT INTO `words` VALUES (11714, NULL, 'adj. 可说服的, 可用恳求打动的', '/\'eksərəbl/', 'exorable', 6);
INSERT INTO `words` VALUES (11715, 'Exorbitant housing prices have created an acute shortage of affordable housing for the poor.', 'adj. 过度的, 过高的, 昂贵的', '/iɡ\'zɔ:bitənt | ɪg\'zɔːbɪt(ə)nt | ɪɡ\'zɔrbɪtənt/', 'exorbitant', 6);
INSERT INTO `words` VALUES (11716, NULL, 'v. 驱除妖魔； 去除', '/\'eksɔːrsaɪz | \'ɛksɔr,saɪz/', 'exorcise', 6);
INSERT INTO `words` VALUES (11717, 'The exorcism was broadcast on television.', 'n. 驱魔, 驱邪所用的咒语', '/\'eksɔ:sizəm | \'eksɔːsɪzəm | \'ɛksɔrsɪzəm/', 'exorcism', 6);
INSERT INTO `words` VALUES (11718, 'He confronted his childhood trauma and tried to exorcize the pain.', 'v. 驱邪, 除怪', '/\'eksɔ:saiz | \'ɛksɔrsaɪz/', 'exorcize', 6);
INSERT INTO `words` VALUES (11719, 'exotic birds', 'adj. 异国情调的, 外来的, 奇异的', '/,iɡ\'zɔtik | ɪg\'zɒtɪk; eg- | ɪɡ\'zɑtɪk/', 'exotic', 6);
INSERT INTO `words` VALUES (11720, 'The computer industry has expanded greatly over the last decade.', 'v. 使膨胀, 详述, 扩张', '/ik\'spænd | ɪk\'spænd; ek- | ɪk\'spænd/', 'expand', 6);
INSERT INTO `words` VALUES (11721, 'The industry underwent a period of rapid expansion.', 'n. 扩充, 开展, 膨胀, 扩张物, 辽阔, 浩瀚', '/ik\'spænʃən | ɪk\'spænʃ(ə)n; ek- | ɪk\'spænʃən/', 'expansion', 6);
INSERT INTO `words` VALUES (11722, 'I\'m in such a drive that I can\'t expatiate.', 'v. 细说， 详述', '/ɪk\'speɪʃieɪt/', 'expatiate', 6);
INSERT INTO `words` VALUES (11723, NULL, 'v. 逐出国外, 脱离国籍, 放逐', '/eks\'pætrieit, -\'pei- | ɪks\'pætrɪət; -\'peɪtrɪət; eks- | ,ɛks\'petrɪət/', 'expatriate', 6);
INSERT INTO `words` VALUES (11724, 'This was a matter less of morals than of expediency.', 'n. 方便, 私利, 权宜', '/ik\'spi:diənsi,-əns | ɪk\'spiːdɪənsɪ; ek- | ɪk\'spidɪənsi/', 'expediency', 6);
INSERT INTO `words` VALUES (11725, 'This solution is politically expedient but may well cause long-term problems.', 'adj. 有用的; n. 权宜之计，临时手段', '/ɪk\'spiːdiənt | ɪk\'spidɪənt/', 'expedient', 6);
INSERT INTO `words` VALUES (11726, 'We tried to help you expedite your plans.', 'v. 加速, 派出', '/\'ekspidait | \'ekspɪdaɪt | \'ɛkspədaɪt/', 'expedite', 6);
INSERT INTO `words` VALUES (11727, 'an expedition to the North Pole', 'n. 远征, 探险队, 迅速, 派遣', '/,ekspi\'diʃən | ekspɪ\'dɪʃ(ə)n | ,ɛkspə\'dɪʃən/', 'expedition', 6);
INSERT INTO `words` VALUES (11728, 'The judge said that arbitration was a fair and expeditious decision-making process.', 'adj. 迅速的, 敏捷的', '/,ekspi\'diʃəs | ,ekspɪ\'dɪʃəs | ,ɛkspə\'dɪʃəs/', 'expeditious', 6);
INSERT INTO `words` VALUES (11729, 'All issues presented to the court are considered as fairly and expeditiously as possible.', 'adv. 迅速地， 敏捷地', '/,ekspi\'diʃəsli | ˌekspə\'dɪʃəsli/', 'expeditiously', 6);
INSERT INTO `words` VALUES (11730, 'More than five-thousand high school students have been expelled for cheating.', 'v. 驱逐, 开除, 排出, 发射', '/ik\'spel | ɪk\'spel; ek- | ɪk\'spɛl/', 'expel', 6);
INSERT INTO `words` VALUES (11731, 'Children expend a lot of energy and may need more high-energy food than adults.', 'v. 花费, 消耗, 支出, [海]把(暂时不用的绳)绕在杆上', '/ik\'spend | ɪk\'spend; ek- | ɪk\'spɛnd/', 'expend', 6);
INSERT INTO `words` VALUES (11732, 'You may be doing what could just as easily be done by someone else, which means you’re highly expendable. You may be playing follow the follower.', 'n. 消耗品, 可牺牲的', '/ik\'spendəbl | ɪk\'spendəb(ə)l; ek- | ɪk\'spɛndəbl/', 'expendable', 6);
INSERT INTO `words` VALUES (11733, 'huge cuts in public expenditure', 'n. 支出, 花费', '/iks\'penditʃə | ɪk\'spendɪtʃə; ek- | ɪk\'spɛndɪtʃɚ/', 'expenditure', 6);
INSERT INTO `words` VALUES (11734, 'She was not an accountant and didn\'t have the expertise to verify all of the financial details.', 'n. 专家的意见, 专门技术', '/,ekspə:\'ti:z | ,ekspɜː\'tiːz | \'ɛkspɝ\'tiz/', 'expertise', 6);
INSERT INTO `words` VALUES (11735, 'It seemed that Alice was expiating her father\'s sins with her charity work.', 'v. 补偿, 赎', '/\'ekspieit | \'ekspɪeɪt | \'ɛkspɪet/', 'expiate', 6);
INSERT INTO `words` VALUES (11736, NULL, 'n. 满期, 呼出, 呼气, <古>终止', '/,ekspi\'reiʃən | ,ekspɪ\'reɪʃ(ə)n | ,ɛkspə\'reʃən/', 'expiration', 6);
INSERT INTO `words` VALUES (11737, 'The chairman’s term of office has already expired.', 'v. 期满, 终止, 呼气, 断气, 届满', '/ik\'spaiə, ek- | ɪk\'spaɪə; ek- | ɪk\'spaɪɚ/', 'expire', 6);
INSERT INTO `words` VALUES (11738, NULL, 'vt. <主苏格兰>查出,探明搜出', NULL, 'expiscate', 6);
INSERT INTO `words` VALUES (11739, 'There are explanatory notes at the end of each chapter.', 'adj. 说明的， 解释的', '/ɪk\'splænətɔːri | ɪk\'splænətɔri/', 'explanatory', 6);
INSERT INTO `words` VALUES (11740, 'The success of the Revolution is explicable in terms of the weakness of the king’s government.', 'adj. 可说明的, 可解释的', '/ik\'splikəbl, \'eks- | ɪk\'splɪkəb(ə)l; ek-; \'eksplɪ,kəb(ə)l | ɪk\'splɪkəbl/', 'explicable', 6);
INSERT INTO `words` VALUES (11741, 'We shall have to explicate its basic assumptions before we can assess its implications.', 'v. 说明', '/\'eksplikeit | \'eksplɪkeɪt | \'ɛksplɪket/', 'explicate', 6);
INSERT INTO `words` VALUES (11742, 'The contrast could not have been made more explicit.', 'adj. 外在的, 清楚的, 直率的, (租金等)直接付款的', '/ik\'splisit | ɪk\'splɪsɪt; ek- | ɪk\'splɪsɪt/', 'explicit', 6);
INSERT INTO `words` VALUES (11743, 'Without a parent style, your action bar will be without many style properties unless you explicitly declare them yourself.', 'adv. 明白地； 明确地', '/ɪk\'splɪsɪtli/', 'explicitly', 6);
INSERT INTO `words` VALUES (11744, 'Homeworkers can easily be exploited by employers.', 'v. 开拓, 开发, 开采, 剥削, 用以自肥', '/\'eksplɔit, ik\'s- | ɪk\'splɒɪt; ek- | ɪk\'splɔɪt/', 'exploit', 6);
INSERT INTO `words` VALUES (11745, 'oil exploration facilities in the North Sea', 'n. 探险, 踏勘, 探测, [医](伤处等的)探查, 探察术', '/,eksplɔ:\'reiʃən | eksplə\'reɪʃ(ə)n | ,ɛksplə\'reʃən/', 'exploration', 6);
INSERT INTO `words` VALUES (11746, 'Management need to explore ways of improving office security.', 'v. 探险, 探测, 探究', '/ik\'splɔ: | ɪk\'splɔː; ek- | ɪk\'splɔr/', 'explore', 6);
INSERT INTO `words` VALUES (11747, 'The Alvin Ailey American Dance Theatre was formed in the 1950s and quickly established itself as a leading exponent of progressive choreography and contemporary dance.', 'n. 解释者, 说明者, 代表者, 典型, 指数', '/ɪk\'spəʊnənt; ek- | ɪk\'sponənt/', 'exponent', 6);
INSERT INTO `words` VALUES (11748, '...an art exposition.', 'n. 博览会, 展览会, 说明, 曝露, [戏]展示部分, [音]呈示部', '/,ekspəu\'ziʃən | ekspə\'zɪʃ(ə)n | ,ɛkspə\'zɪʃən/', 'exposition', 6);
INSERT INTO `words` VALUES (11749, 'An expository treatise or series of annotations; an exegesis .', 'adj. 说明的', '/ɪk\'spɑːzətɔːri | ɪk\'spɑzətɔri/', 'expository', 6);
INSERT INTO `words` VALUES (11750, 'I expostulate with her on the impropriety.', 'v. 劝诫, 忠告', '/ik\'spɔstjuleit | ɪk\'spɒstjʊleɪt; ek- | ɪk\'spɑstʃulet/', 'expostulate', 6);
INSERT INTO `words` VALUES (11751, 'Exposure to lead is known to damage the brains of young children.', 'n. 暴露， 显露， 曝光', '/ɪk\'spouʒər | ɪk\'spoʒɚ/', 'exposure', 6);
INSERT INTO `words` VALUES (11752, 'Schmidt continued to expound his views on economics and politics.', 'v. 详细说明, 解释', '/ik\'spaund | ɪk\'spaʊnd; ek- | ɪk\'spaʊnd/', 'expound', 6);
INSERT INTO `words` VALUES (11753, 'He was expressly forbidden to speak to the girl.', 'adv. 明白地, 特别地, 清楚地', '/ik\'spresli | ɪk\'spreslɪ; ek- | ɪk\'sprɛsli/', 'expressly', 6);
INSERT INTO `words` VALUES (11754, 'The Bolsheviks expropriated the property of the landowners.', 'v. 没收, 征用, 剥夺', '/eks\'prəuprieit | ɪks\'prəʊprɪeɪt; eks- | ɛks\'proprɪet/', 'expropriate', 6);
INSERT INTO `words` VALUES (11755, 'The headmaster threatened the boys with expulsion.', 'n. 逐出, 开除', '/ik\'spʌlʃən | ɪk\'spʌlʃ(ə)n; ek- | ɪk\'spʌlʃən/', 'expulsion', 6);
INSERT INTO `words` VALUES (11756, 'The revolutionaries expunged domestic opposition.', 'v. 擦去', '/ik\'spʌndʒ | ɪk\'spʌn(d)ʒ; ek- | ɪk\'spʌndʒ/', 'expunge', 6);
INSERT INTO `words` VALUES (11757, 'He heavily expurgated the work in its second edition.', 'v. 删除', '/\'ekspə:ɡeit | \'ekspɜːgeɪt | \'ɛkspɚɡet/', 'expurgate', 6);
INSERT INTO `words` VALUES (11758, 'the most exquisite craftsmanship', 'adj. 优美的, 高雅的, 精致的, 剧烈的, 异常的, 细腻的, 敏锐的', '/\'ekskwizit, ek\'skwizit | \'ekskwɪzɪt; ɪk\'skwɪzɪt; ek- | ɪk\'skwɪzɪt/', 'exquisite', 6);
INSERT INTO `words` VALUES (11759, 'Few of the manuscripts are still extant.', 'adj. 现存的, 未毁的, <古>突出的, 显著的', '/ek\'stænt, \'ekstənt | ɪk\'stænt; ek-; \'ekst(ə)nt | ɛk\'stænt/', 'extant', 6);
INSERT INTO `words` VALUES (11760, 'He completely departed from the text and extemporized in a very energetic fashion.', 'v. 即席演说, 即兴演奏, 当场作成', '/ik\'stempəraiz | ɪk\'stempəraɪz; ek- | ɪk\'stɛmpəraɪz/', 'extemporize', 6);
INSERT INTO `words` VALUES (11761, 'Management have agreed to extend the deadline.', 'v. 延伸， 扩大； 舒展； 宽延， 延缓', '/ɪk\'stend | ɪk\'stɛnd/', 'extend', 6);
INSERT INTO `words` VALUES (11762, 'Donald’s been given an extension to finish his thesis.', 'n. 延伸， 扩展', '/ɪk\'stenʃn | ɪk\'stɛnʃən/', 'extension', 6);
INSERT INTO `words` VALUES (11763, 'The house stands in extensive grounds.', 'adj. 广大的， 广阔的； 多方面的， 广泛的', '/ɪk\'stensɪv | ɪk\'stɛnsɪv/', 'extensive', 6);
INSERT INTO `words` VALUES (11764, 'Nothing can extenuate his base conduct.', 'v. 掩饰, 减轻, 使人原谅, 低估, <古>使稀薄', '/ik\'stenjueit | ɪk\'stenjʊeɪt; ek- | ɪk\'stɛnjʊet/', 'extenuate', 6);
INSERT INTO `words` VALUES (11765, 'Staff use the poison to exterminate moles and rabbits.', 'v. 消除', '/ik\'stə:mineit | ɪk\'stɜːmɪneɪt; ek- | ɪk\'stɝmə\'net/', 'exterminate', 6);
INSERT INTO `words` VALUES (11766, 'These are some people who tend to externalize blame when anything goes wrong at work.', 'v. 使…表面化', '/ɪk\'stɜːrnəlaɪz | ik\'stə:nəlaiz/', 'externalize', 6);
INSERT INTO `words` VALUES (11767, 'Dinosaurs have been extinct for millions of years.', 'adj. 熄灭的, 灭绝的, 耗尽的', '/ik\'stiŋkt | ɪk\'stɪŋkt; ek- | ɪk\'stɪŋkt/', 'extinct', 6);
INSERT INTO `words` VALUES (11768, 'An operation is beginning to try to save a species of crocodile from extinction.', 'n. 消失, 消灭, 废止, [物]消光', '/ɪk\'stɪŋ(k)ʃ(ə)n; ek- | ɪk\'stɪŋkʃən/', 'extinction', 6);
INSERT INTO `words` VALUES (11769, 'Please extinguish all cigarettes.', 'v. 使…熄灭； 使…不复存在', '/ɪk\'stɪŋgwɪʃ | ɪk\'stɪŋɡwɪʃ/', 'extinguish', 6);
INSERT INTO `words` VALUES (11770, NULL, 'v. 消灭, 根除, 毁灭, [医]摘除(肿瘤等)', '/\'ekstə:peit | \'ekstɜːpeɪt/', 'extirpate', 6);
INSERT INTO `words` VALUES (11771, NULL, 'n. 消灭， 根除', '/,ekstə:\'peiʃən | ˌekstər\'peɪʃn/', 'extirpation', 6);
INSERT INTO `words` VALUES (11772, 'A customer reluctantly listens as awaitress and her inexplicable chorus of Vikings extol the virtues of the processed meat.', 'v. 赞美', '/ik\'stəul | ɪk\'stəʊl; ek- | ɪk\'stol/', 'extol', 6);
INSERT INTO `words` VALUES (11773, 'Corrupt government officials were extorting money from him.', 'v. 敲诈, 逼取, 强取, 勒索', '/ik\'stɔ:t | ɪk\'stɔːt; ek- | ɪk\'stɔrt/', 'extort', 6);
INSERT INTO `words` VALUES (11774, 'He has been charged with extortion and abusing his powers.', 'n. 勒索, 敲诈, 强取, 被勒索的财物', '/ik\'stɔ:ʃən | ɪk\'stɔːʃ(ə)n; ek- | ɪk\'stɔrʃən/', 'extortion', 6);
INSERT INTO `words` VALUES (11775, 'You’ll have to have that tooth extracted.', 'v. 拔出； 强索', '/ɪk\'strækt | \'ɛkstrækt/', 'extract', 6);
INSERT INTO `words` VALUES (11776, 'A judge agreed to extradite him to Texas.', 'v. 引渡', '/\'ekstrədaɪt | \'ekstrədait/', 'extradite', 6);
INSERT INTO `words` VALUES (11777, 'extraneous noises', 'adj. 无关系的, 外来的, [化]外部裂化, [化]新异反射', '/ek\'streinjəs | ɪk\'streɪnɪəs; ek- | ɪk\'strenɪəs/', 'extraneous', 6);
INSERT INTO `words` VALUES (11778, 'Extrapolating from his latest findings, he reckons about 80% of these deaths might be attributed to smoking.', 'v. 推断, [数]外推', '/ek\'stræpəleit | ɪk\'stræpəleɪt; ek- | ɪk\'stræpə\'let/', 'extrapolate', 6);
INSERT INTO `words` VALUES (11779, 'When the company went under, tales of his extravagance surged through the industry.', 'n. 奢侈， 挥霍', '/ɪk\'strævəgəns | ɪk\'strævəɡəns/', 'extravagance', 6);
INSERT INTO `words` VALUES (11780, 'Would it be too extravagant to buy both?', 'adj. 奢侈的, 浪费的, 过分的, 放纵的', '/ik\'strævəɡənt | ɪk\'strævəg(ə)nt; ek- | ɪk\'strævəgənt/', 'extravagant', 6);
INSERT INTO `words` VALUES (11781, 'The bomb was planted by right-wing extremists.', 'n. 极端主义者', '/ɪk\'striːmɪst | ɪk\'strimɪst/', 'extremist', 6);
INSERT INTO `words` VALUES (11782, 'The committee was uncomfortable about the extremity of the proposal.', 'n. 末端, 极端, 极度, 穷困, 绝境, 临死, 非常手段, 手足', '/ik\'stremiti | ɪk\'stremɪtɪ; ek- | ɪk\'strɛməti/', 'extremity', 6);
INSERT INTO `words` VALUES (11783, NULL, 'adj. 可解救的， 能脱险的', '/\'ekstrikəbl | \'ekstrɪkəbl/', 'extricable', 6);
INSERT INTO `words` VALUES (11784, 'It represents a last-ditch attempt by the country to extricate itself from its economic crisis.', 'v. 使解脱, 救出, 使(气体)游离, 放出', '/\'ekstrikeit | \'ekstrɪkeɪt | \'ɛkstrɪket/', 'extricate', 6);
INSERT INTO `words` VALUES (11785, 'Nowadays there are fewer extrinsic pressures to get married.', 'adj. 外在的, 外表的, 外来的', '/ek\'strinsik | ɪk\'strɪnsɪk; ek- | ɛks\'trɪnsɪk/', 'extrinsic', 6);
INSERT INTO `words` VALUES (11786, 'Her sister was always more of an extrovert.', 'n. 性格外向者', '/\'ekstrəuvə:t, ,ekstrə\'və:t | \'ekstrəvɜːt | ,ɛkstrə\'vɝt/', 'extrovert', 6);
INSERT INTO `words` VALUES (11787, 'These crystals are then embedded in a plastic, and the plastic is extruded as a wire.', 'v. 挤出， 推出， 逐出； 伸出， 突出', '/ɪk\'struːd | ɪk\'strʊd/', 'extrude', 6);
INSERT INTO `words` VALUES (11788, NULL, 'n. 愉快； 茁壮', '/ɪg\'zuːbərəns | ɪg\'zjʊbərəns/', 'exuberance', 6);
INSERT INTO `words` VALUES (11789, 'an exuberant personality', 'adj. 繁茂的, 丰富的, 非凡的, (语言等)华而不实的', '/iɡ\'zju:bərənt | ɪg\'z(j)uːb(ə)r(ə)nt; eg-/', 'exuberant', 6);
INSERT INTO `words` VALUES (11790, 'The plant exudes a sticky liquid.', 'v. (使)流出, (使)渗出, 发散开来', '/iɡ\'zju:d | ɪg\'zjuːd; eg- | ɪɡ\'zud/', 'exude', 6);
INSERT INTO `words` VALUES (11791, '‘We made the front page!’ Jos exulted.', 'v. 非常高兴, 欢跃', '/iɡ\'zʌlt | ɪg\'zʌlt; eg- | ɪɡ\'zʌlt/', 'exult', 6);
INSERT INTO `words` VALUES (11792, 'An exultant party leader said: \"He will be an excellent MP.\"', 'adj. 非常高兴的, 欢跃的', '/iɡ\'zʌltənt | ɪɡ\'zʌltənt/', 'exultant', 6);
INSERT INTO `words` VALUES (11793, 'Only a decade ago, the place was exurban rice paddies and lychee orchards.', 'adj. 城市远郊的', '/eks\'ə:bən/', 'exurban', 6);
INSERT INTO `words` VALUES (11794, 'The results showed that this contact kairomone was capable of eliciting the antennal searching behavior of A. nilaparvatae and existed in honeydew and exuviae of all BPH stages.', 'n. [动]脱落的皮, 空壳', '/iɡ\'zju:vii: | ɪg\'zjuːvɪiː; eg- | ɪg\'zʊvji/', 'exuviae', 6);
INSERT INTO `words` VALUES (11795, 'our new range of fabrics and wallpapers', 'n. 织品, 织物, 布, 结构, 建筑物, 构造', '/\'fæbrik | \'fæbrɪk/', 'fabric', 6);
INSERT INTO `words` VALUES (11796, 'The police were accused of fabricating evidence.', 'v. 制作, 构成, 捏造, 伪造, 虚构', '/\'fæbrikeit | \'fæbrɪkeɪt | \'fæbrɪket/', 'fabricate', 6);
INSERT INTO `words` VALUES (11797, 'You look fabulous!', 'adj. 寓言中的, 寓言般的, 神话般的, 传统上的, 惊人的, 难以置信的', '/\'fæbjuləs | \'fæbjʊləs | \'fæbjələs/', 'fabulous', 6);
INSERT INTO `words` VALUES (11798, 'an impressive building with a red brick facade', 'n. 正面', '/fə\'sɑ:d | fə\'sɑːd | fə\'sɑd/', 'facade', 6);
INSERT INTO `words` VALUES (11799, 'Don’t be so facetious!', 'adj. 幽默的, 滑稽的, 喜开玩笑的', '/fə\'siːʃəs | fə\'siʃəs/', 'facetious', 6);
INSERT INTO `words` VALUES (11800, 'a facile victory', 'adj. 易做到的, 易得到的, 不花力气的, 敏捷的, 流畅的, (性格)柔顺的, 温和的, 容易的', '/\'fæsaɪl; -sɪl | \'fæsl/', 'facile', 6);
INSERT INTO `words` VALUES (11801, 'The new airport will facilitate the development of tourism.', 'v. （不以人作主语的）使容易, 使便利, 推动, 帮助, 使容易, 促进', '/fə\'siliteit | fə\'sɪlɪteɪt | fə\'sɪlə\'tet/', 'facilitate', 6);
INSERT INTO `words` VALUES (11802, '...a facsimile edition of Beethoven\'s musical manuscripts.', 'n. 摹写, 传真', '/fæk\'simili | fæk\'sɪmɪlɪ | fæk\'sɪməli/', 'facsimile', 6);
INSERT INTO `words` VALUES (11803, 'struggles between the different factions within the party', 'n. 派别, 小集团, 派系斗争, 小派系, 内讧', '/fækʃən | \'fækʃ(ə)n | \'fækʃən/', 'faction', 6);
INSERT INTO `words` VALUES (11804, NULL, 'adj. 好搞派系的, 好捣乱的', '/\'fækʃəs/', 'factious', 6);
INSERT INTO `words` VALUES (11805, 'So we know that the right and wrong are factitious.', 'adj. 人为的, 做作的, 不自然的', '/fæk\'tiʃəs | fæk\'tɪʃəs/', 'factitious', 6);
INSERT INTO `words` VALUES (11806, NULL, 'adj. 能分解成因子的', '/\'fæktərəbl/', 'factorable', 6);
INSERT INTO `words` VALUES (11807, NULL, 'n. 家务总管, 杂役, 打杂的人, [印]特大型花体大写字母', '/\'fæktəutəm | fæk\'təʊtəm | fæk\'totəm/', 'factotum', 6);
INSERT INTO `words` VALUES (11808, 'Try to keep your account of events as factual as possible.', 'adj. 事实的， 实际的', '/\'fæktʃuəl/', 'factual', 6);
INSERT INTO `words` VALUES (11809, 'Both faculty and students oppose the measures.', 'n. 全体教员； 能力， 技能', '/\'fæklti/', 'faculty', 6);
INSERT INTO `words` VALUES (11810, 'Interest in organic food is not a fad, it’s here to stay.', 'n. 时尚, 一时流行的狂热, 一时的爱好', '/fæd/', 'fad', 6);
INSERT INTO `words` VALUES (11811, '...faddish footwear.', 'adj. 趋于时尚的, 流行的, 风行的', '/\'fædiʃ | \'fædɪʃ/', 'faddish', 6);
INSERT INTO `words` VALUES (11812, 'All colour fades – especially under the impact of direct sunlight.', 'v. 变暗， 褪色， 枯萎， 凋谢', '/feɪd | fed/', 'fade', 6);
INSERT INTO `words` VALUES (11813, NULL, 'n. 吃力的工作, 疲劳, 苦工', '/fæɡ | fæg/', 'fag', 6);
INSERT INTO `words` VALUES (11814, NULL, 'n. 仙女, 精灵, <美俚>漂亮姑娘', '/\'feərɪ | \'fɛri/', 'fairy', 6);
INSERT INTO `words` VALUES (11815, 'At night, the harbor is a fairyland.', 'n. 仙境, 乐园, 奇境', '/\'fεərilənd | \'feərɪlænd | \'fɛrɪlænd/', 'fairyland', 6);
INSERT INTO `words` VALUES (11816, 'The painting was judged a fake.', 'n. 假货, 欺骗', '/feik | feɪk/', 'fake', 6);
INSERT INTO `words` VALUES (11817, 'Animals representing mythical powers and military might surrounded him—pumas, a wolf, eagles, a falcon, an owl, and rattlesnakes—some buried alive in cages.', 'n. [动](猎鸟用的)猎鹰', '/\'fælkən | \'fɔː(l)k(ə)n; \'fɒlk(ə)n/', 'falcon', 6);
INSERT INTO `words` VALUES (11818, 'Such an argument is misleading, if not wholly fallacious.', 'adj. 谬误的, 靠不住的, 虚妄的, 令人失望的, 虚伪的, 使人误解的, 不合理的', '/fə\'leiʃəs | fə\'leɪʃəs | fə\'leʃəs/', 'fallacious', 6);
INSERT INTO `words` VALUES (11819, 'It’s a common fallacy that a neutered dog will become fat and lazy.', 'n. 谬误, 谬论', '/\'fæleisi | \'fæləsɪ | \'fæləsi/', 'fallacy', 6);
INSERT INTO `words` VALUES (11820, '\"Trump has exposed the inadequacy and fallibility of decades-old domestic political strategy of governing by polls and contrived expectations, \" she said.', 'n. 易出错， 不可靠', '/ˌfælə\'bɪləti | ,fælə\'bɪləti/', 'fallibility', 6);
INSERT INTO `words` VALUES (11821, 'Humans are fallible.', 'adj. 易错的, 可能犯错的', '/\'fæləbl | \'fælɪb(ə)l/', 'fallible', 6);
INSERT INTO `words` VALUES (11822, 'Farmers know that soil needs rest, so they rotate their crops and systematically leave a portion of their land fallow.', 'n. 休耕地', '/\'fæləu | \'fæləʊ | \'fælo/', 'fallow', 6);
INSERT INTO `words` VALUES (11823, 'Saunders is deliberately telling a falsehood.', 'n. 谎言', '/\'fɔːlshud | \'fɔlshʊd/', 'falsehood', 6);
INSERT INTO `words` VALUES (11824, NULL, 'n. 弄虚作假, 串改, 伪造, 歪曲', '/\'fɔ:lsifi\'keiʃən/', 'falsification', 6);
INSERT INTO `words` VALUES (11825, 'The file was altered to falsify the evidence.', 'v. 伪造', '/fɔ:lsifai | \'fɔːlsɪfaɪ; \'fɒls- | \'fɔlsɪfaɪ/', 'falsify', 6);
INSERT INTO `words` VALUES (11826, 'Laurie’s voice faltered as she tried to thank him.', 'v. 蹒跚； 支吾地说', '/\'fɔːltər | \'fɔltɚ/', 'falter', 6);
INSERT INTO `words` VALUES (11827, 'I miss the familiarity of home.', 'n. 熟悉, 通晓, 亲密, 熟悉, 精通', '/fə,mili\'æriti | fəmɪlɪ\'ærɪtɪ | fə,mɪlɪ\'ærəti/', 'familiarity', 6);
INSERT INTO `words` VALUES (11828, 'the great potato famine in Ireland', 'n. 饥荒', '/\'fæmɪn/', 'famine', 6);
INSERT INTO `words` VALUES (11829, NULL, 'v. (常用被动语态)使挨饿, <古>使饿死', '/\'feimiʃ | \'fæmɪʃ/', 'famish', 6);
INSERT INTO `words` VALUES (11830, 'fanatics who represent a real danger to democracy', 'n. 狂热者, 盲信者, 入迷者', '/fə\'nætik | fə\'nætɪk/', 'fanatic', 6);
INSERT INTO `words` VALUES (11831, 'The bombing symbolizes the worst of religious fanaticism .', 'n. 狂热, 盲信', '/fə\'nætisizəm | fə\'nætɪsɪz(ə)m | fə\'nætɪsɪzəm/', 'fanaticism', 6);
