INSERT INTO `words` VALUES (11833, 'a fanciful story', 'adj. 幻想的， 奇特的', '/\'fænsɪfl/', 'fanciful', 6);
INSERT INTO `words` VALUES (11834, 'The ceremony opened with a fanfare of trumpets.', 'n. 喇叭或号角嘹亮的吹奏声, 吹牛', '/\'fænfεə | \'fænfeə | \'fæn\'fɛr/', 'fanfare', 6);
INSERT INTO `words` VALUES (11835, 'The cobra sank its venomous fangs into his hand.', 'n. (犬, 狼等的)尖牙, 犬牙, (毒蛇的)毒牙, 牙根, 尖端', '/fæŋ/', 'fang', 6);
INSERT INTO `words` VALUES (11836, 'Magically, the words will start flowing. The inspiration will hit you like a Newtonian apple and fantabulous images and ideas will literally explode from your brain.', 'adj. <美俚>极出色的, 极妙的', '/fæn\'tæbjuləs | fæn\'tæbjʊləs/', 'fantabulous', 6);
