INSERT INTO `words` VALUES (11838, 'fantastic tales of dragons and fairy queens', 'adj. 幻想的, 奇异的, 稀奇古怪的, 荒谬的, 空想的', '/fæn\'tæstɪk/', 'fantastic', 6);
INSERT INTO `words` VALUES (11839, 'I used to have fantasies about living in Paris with an artist.', 'n. 想象， 幻想', '/\'fæntəsi/', 'fantasy', 6);
INSERT INTO `words` VALUES (11840, 'Objectives:To determine the effect of marriage treatment on fantod among married women with panic disorder.', 'n. 烦燥, 惊恐', '/\'fæntɒd | \'fæn,tɑd/', 'fantod', 6);
INSERT INTO `words` VALUES (11841, 'The economy is in danger of collapse unless far-reaching reforms are implemented.', 'adj. 影响深远的', '/ˌfɑː\'riːtʃɪŋ | \'fɑ:\'ri:tʃiŋ/', 'far-reaching', 6);
INSERT INTO `words` VALUES (11842, 'She admitted that the interview had been a complete farce from start to finish.', 'n. 笑剧, 闹剧, 滑稽剧, 胡闹', '/fɑ:s | fɑːs | fɑrs/', 'farce', 6);
INSERT INTO `words` VALUES (11843, 'He could barely afford the fare.', 'n. 费用, 旅客, 食物', '/fεə | feə | fɛr/', 'fare', 6);
INSERT INTO `words` VALUES (11844, 'Mourners gathered to bid farewell to the victims of the plane tragedy.', 'n. 辞行， 告别; interj. 再会，再见', '/ˌfer\'wel | ,fɛr\'wɛl/', 'farewell', 6);
INSERT INTO `words` VALUES (11845, NULL, 'n. 混杂, 混杂物', '/fæ\'rɑ:ɡəu | fə\'rɑːgəʊ | fə\'rɑɡo/', 'farrago', 6);
