INSERT INTO `words` VALUES (11848, 'Politics fascinated Franklin\'s father.', 'v. 使着迷, 使神魂颠倒', '/\'fæsineit | \'fæsɪneɪt | \'fæsə\'net/', 'fascinate', 6);
INSERT INTO `words` VALUES (11849, 'a fascinating book', 'adj. 迷人的, 醉人的, 着魔的', '/\'fæsineitiŋ | \'fæsɪneɪtɪŋ | \'fæsɪnetɪŋ/', 'fascinating', 6);
INSERT INTO `words` VALUES (11850, 'The fascination lay in the mystery of what was inside the box.', 'n. 魔力, 入迷, 魅力, 迷恋, 强烈爱好', '/fæsi\'neiʃən | ,fæsɪ\'neɪʃ(ə)n | ,fæsɪ\'neʃən/', 'fascination', 6);
INSERT INTO `words` VALUES (11851, 'Slow down – you’re driving too fast.', 'adv. 很快地； 紧紧地； 深沉地; n. 禁食，斋戒', '/fæst/', 'fast', 6);
INSERT INTO `words` VALUES (11852, 'What can I use to fasten on this clip?', 'v. 使固定', '/\'fæsn | \'fæsən/', 'fasten', 6);
INSERT INTO `words` VALUES (11853, 'people who are fastidious about personal hygiene', 'adj. 难取悦的, 挑剔的, 苛求的, (微生物等)需要复杂营养地', '/fæs\'tidiəs | fæ\'stɪdɪəs/', 'fastidious', 6);
INSERT INTO `words` VALUES (11854, 'They could have withdrawn into the mountain fastness of Eryri.', 'n. 牢固, 固定(性), 不褪色(性), 放荡, 僻静的处所, 抗(毒)性, 要塞, 巩固', '/\'fɑ:stnis, \'fæs- | \'fɑːs(t)nɪs | \'fæstnəs/', 'fastness', 6);
INSERT INTO `words` VALUES (11855, 'potentially fatal diseases', 'adj. 致命的； 灾难性的', '/\'feɪtl | \'fetl/', 'fatal', 6);
INSERT INTO `words` VALUES (11856, 'a 50% increase in the number of traffic fatalities', 'n. 命运决定的事物, 不幸, 灾祸, 天命', '/fæ\'tæliti | fə\'tælɪtɪ; feɪ- | fə\'tæləti/', 'fatality', 6);
INSERT INTO `words` VALUES (11857, 'I still can’t fathom out what she meant.', 'n. 长度单位(6英尺)', '/\'fæðəm | \'fæð(ə)m/', 'fathom', 6);
INSERT INTO `words` VALUES (11858, 'the fathomless depths of the sea', 'adj. 深不可测的, 无法计量, 无法了解的', '/\'fæð(ə)mləs | \'fæðəmlis/', 'fathomless', 6);
INSERT INTO `words` VALUES (11859, NULL, 'adj. (=prophetic)预言的, 预言性的', '/fæ\'tɪdɪk | fæ\'tidik/', 'fatidic', 6);
INSERT INTO `words` VALUES (11860, '{\"COLLOINEXA\":[\"metal fatigue\"]}', 'n. 疲乏, 疲劳, 累活, [军]杂役', '/fə\'ti:ɡ | fə\'tiːg | fə\'tig/', 'fatigue', 6);
INSERT INTO `words` VALUES (11861, 'They have kept the price of sugar artificially high and so fattened the company\'s profits.', 'v. 长胖， 变肥； 使…肥沃； 装满', '/\'fætn/', 'fatten', 6);
INSERT INTO `words` VALUES (11862, 'You have only to ask the questions to realise the fatuity of the idea.', 'n. 愚昧, 昏庸, 愚蠢的言行', '/fə\'tju(:)iti | fə\'tjʊ(ː)ɪtɪ/', 'fatuity', 6);
INSERT INTO `words` VALUES (11863, 'fatuous questions', 'adj. 愚昧的, 昏庸的, 发呆的, 愚笨的, 自满的', '/\'fætjuəs | \'fætjʊəs | \'fætʃuəs/', 'fatuous', 6);
INSERT INTO `words` VALUES (11864, NULL, 'n. 龙头, 旋塞, (连接管子的)插口', '/\'fɔːsɪt | \'fɔsɪt/', 'faucet', 6);
INSERT INTO `words` VALUES (11865, 'I’m really sorry - it’s all my fault.', 'n. 过错, 缺点, 故障, 毛病', '/fɔ:lt | fɔːlt; fɒlt | fɔlt/', 'fault', 6);
INSERT INTO `words` VALUES (11866, '...the flora and fauna of the African jungle.', 'n. 动物群, 动物区系, 动物志', '/\'fɔ:nə | \'fɔːnə | \'fɔnə/', 'fauna', 6);
INSERT INTO `words` VALUES (11867, 'We would be pleased if you would take full advantage of our services and favorable shopping conditions.', 'adj. 有利的； 赞成的', '/\'feɪvərəbl | \'fevərəbl/', 'favorable', 6);
INSERT INTO `words` VALUES (11868, 'The fawn ran to the top of the ridge.', 'n. (未满一岁的)小鹿, 小山羊, 小动物, 鹿毛色, 浅黄褐色', '/fɔ:n | fɔːn | fɔn/', 'fawn', 6);
INSERT INTO `words` VALUES (11869, 'The game is played out in endless fawning speeches, flattering remarks and fake smiles.', 'adj. 奉承的', '/\'fɔ:niŋ/', 'fawning', 6);
