INSERT INTO `words` VALUES (11887, 'a felicitous choice of candidate', 'adj. (措辞等)恰当的, 巧妙的, 极为适当的, 可喜的, 善于措词的, [罕]幸福的, 快乐的', '/fi\'lisitəs | fɪ\'lɪsɪtəs | fə\'lɪsɪtəs/', 'felicitous', 6);
INSERT INTO `words` VALUES (11888, 'domestic felicity', 'n. 幸福, 幸运, 福气, (措辞等)恰当, 巧妙, 幸福, 幸运', '/fəˈlɪsəti | fɪ\'lɪsɪtɪ | fə\'lɪsəti/', 'felicity', 6);
INSERT INTO `words` VALUES (11889, 'She moves with feline grace.', 'adj. 猫的, 猫科的, 猫一样的', '/\'fi:lain | \'fiːlaɪn | \'filaɪn/', 'feline', 6);
INSERT INTO `words` VALUES (11890, NULL, 'vbl. fall 的过去式', '/fel | fɛl/', 'fell', 6);
