INSERT INTO `words` VALUES (11897, 'Todd sat on the front fender, his legs dangling toward the ground.', 'n. 防卫物, 挡泥板', '/\'fendə | \'fɛndɚ/', 'fender', 6);
INSERT INTO `words` VALUES (11898, 'feral cats', 'adj. 凶猛的， 野性的', '/\'ferəl | \'fiərəl/', 'feral', 6);
