INSERT INTO `words` VALUES (11900, 'But thrumming underneath it is a deep layer of culinary funkreminiscent of fermentation.', 'n. 发酵', '/,fə:men\'teiʃən | fɜːmen\'teɪʃ(ə)n | ,fɝmɛn\'teʃən/', 'fermentation', 6);
INSERT INTO `words` VALUES (11901, 'A ladder fern springs from a crack in the 1979 lava flows from Kilauea Volcano on the Big Island of Hawaii.', 'n. [植]蕨类植物', '/fə:n | fɜːn | fɝn/', 'fern', 6);
INSERT INTO `words` VALUES (11902, 'a ferocious, hungry lion', 'adj. 凶恶的, 残忍的, 凶猛的, <口>十分强烈的, 极度的', '/fə\'rəuʃəs | fə\'rəʊʃəs | fə\'roʃəs/', 'ferocious', 6);
INSERT INTO `words` VALUES (11903, 'The armed forces seem to have been taken by surprise by the ferocity of the attack.', 'n. 凶猛, 残忍, 暴行', '/fə\'rɔsiti | fə\'rɒsɪtɪ | fə\'rɑsəti/', 'ferocity', 6);
INSERT INTO `words` VALUES (11904, NULL, 'n. 白鼬, 雪貂, 侦探, 细带', '/\'ferit | \'ferɪt | \'fɛrɪt/', 'ferret', 6);
