INSERT INTO `words` VALUES (11906, 'ferrous metals', 'adj. 铁的, 含铁的, [化]亚铁的', '/\'ferəs | \'fɛrəs/', 'ferrous', 6);
INSERT INTO `words` VALUES (11907, 'They had recrossed the River Gambia by ferry.', 'n. 摆渡, 渡船, 渡口', '/\'feri | \'ferɪ | \'fɛri/', 'ferry', 6);
INSERT INTO `words` VALUES (11908, '800 acres of fertile cropland', 'adj. 肥沃的, 富饶的, 能繁殖的', '/\'fɜːtaɪl | ˈfɝtəl; (canadian) ˈfɝˌtaɪl/', 'fertile', 6);
INSERT INTO `words` VALUES (11909, NULL, 'n. 肥沃, 丰产, 多产, 人口生产, 生产力', '/fə\'tiliti | fə\'tɪlɪtɪ; fɜː\'tɪlɪtɪ | fɚ\'tɪləti/', 'fertility', 6);
INSERT INTO `words` VALUES (11910, 'After the egg has been fertilized, it will hatch in about six weeks.', 'v. 使受精； 使肥沃', '/\'fɜːrtəlaɪz | \'fɝtəlaɪz/', 'fertilize', 6);
INSERT INTO `words` VALUES (11911, '...farming without any purchased chemical, fertilizer or pesticide.', 'n. 肥料， 化肥', '/\'fɜːrtəlaɪzər | \'fɝtəlaɪzɚ/', 'fertilizer', 6);
INSERT INTO `words` VALUES (11912, 'a fervent appeal for peace', 'adj. 炽热的', '/\'fə:vənt | \'fɜːv(ə)nt | \'fɝvənt/', 'fervent', 6);
INSERT INTO `words` VALUES (11913, 'It assailed her with all the violence of her fervid imagination.', 'adj. 炽热的； 热情的', '/\'fɜːrvɪd | \'fɝvɪd/', 'fervid', 6);
INSERT INTO `words` VALUES (11914, 'The non religious version, which reads strong excitement of feeling or something inspiring zeal or fervor.', 'n. 热情, 热烈, 炽热', '/\'fə:və | \'fɜːvə/', 'fervor', 6);
INSERT INTO `words` VALUES (11915, 'Happy is the house that shelters a friend! It might well be built, like a festal bower or arch, to entertain him a single day.', 'adj. 节日的, 欢乐的, 祭日的', '/\'festl | \'fest(ə)l/', 'festal', 6);
INSERT INTO `words` VALUES (11916, 'The atmosphere was festive and jolly.', 'adj. 庆祝的, 喜庆的, 欢乐的, 节日似', '/\'festiv | \'festɪv | \'fɛstɪv/', 'festive', 6);
INSERT INTO `words` VALUES (11917, 'the black fetid water of the lake', 'adj. 有恶臭的', '/fetid | \'fetɪd; \'fiːt- | \'fɛtɪd/', 'fetid', 6);
INSERT INTO `words` VALUES (11918, 'What began as a postwar fetish for sunbathing is rapidly developing into a world health crisis.', 'n. 物神, 迷信, 偶像', '/\'fi:tiʃ | \'fetɪʃ | \'fɛtɪʃ/', 'fetish', 6);
INSERT INTO `words` VALUES (11919, NULL, 'n. [常用复]脚镣, 羁绊, 束缚', '/\'fetə | \'fɛtɚ/', 'fetter', 6);
INSERT INTO `words` VALUES (11920, 'Pregnant women who are heavy drinkers risk damaging the unborn fetus.', 'n. 胎儿', '/\'fi:təs | \'fiːtəs | \'fitəs/', 'fetus', 6);
