INSERT INTO `words` VALUES (11922, 'The first lecture I ever gave was a complete fiasco .', 'n. 惨败, 大失败, 可耻的下场', '/fi\'æskəu | fɪ\'æskəʊ | fɪ\'æsko/', 'fiasco', 6);
INSERT INTO `words` VALUES (11923, 'He has tried to impose solutions to the country\'s problems by fiat.', 'n. 命令, 法令, 许可, 批准', '/\'fiːæt; \'faɪæt | ˈfiət, -ˌæt, -ˌɑt, ˈfaɪˌæt, -ət/', 'fiat', 6);
INSERT INTO `words` VALUES (11924, 'an unpredictable and fickle lover', 'adj. (在感情等方面)变幻无常的, 浮躁的, 薄情的', '/\'fikl | \'fɪk(ə)l | \'fɪkl/', 'fickle', 6);
INSERT INTO `words` VALUES (11925, 'His story became a parable for the fickleness of art and life.', 'n. 浮躁； 变化无常', '/\'fɪklnəs | \'fɪkəlnəs/', 'fickleness', 6);
