INSERT INTO `words` VALUES (11927, 'the importance of marital fidelity', 'n. 忠实, 诚实, 忠诚, 保真度, (收音机, 录音设备等的)逼真度, 保真度, 重现精度', '/fi\'deliti | fɪ\'delɪtɪ | fɪ\'dɛləti/', 'fidelity', 6);
INSERT INTO `words` VALUES (11928, 'The kids had started to fidget.', 'v. 坐立不安, 烦躁, 慌张, (不安地或心不在焉地)弄, 玩弄', '/\'fidʒit | \'fɪdʒɪt/', 'fidget', 6);
INSERT INTO `words` VALUES (11929, 'The boys get fidgety if they can’t play outside.', 'adj. 不安的, 不沉着的, 烦燥的, 难以取悦的', '/\'fidʒiti | \'fɪdʒɪtɪ | \'fɪdʒɪti/', 'fidgety', 6);
INSERT INTO `words` VALUES (11930, NULL, 'n. 封地, 采邑', '/fi:f | fiːf | fif/', 'fief', 6);
INSERT INTO `words` VALUES (11931, 'A tearful husband repeated calls for help in catching the fiend who battered his wife.', 'n. 魔鬼, 魔王, 撒旦, 邪神, 能手, 成癖者', '/fi:nd | fiːnd | find/', 'fiend', 6);
INSERT INTO `words` VALUES (11932, 'a particularly fiendish practical joke', 'adj. 恶魔似的, 残忍的, 极坏的', '/\'fi:ndiʃ | \'fiːndɪʃ | \'findɪʃ/', 'fiendish', 6);
INSERT INTO `words` VALUES (11933, 'fierce fighting in the city', 'adj. 凶猛的, 猛烈的, 热烈的, 暴躁的<美>极讨厌的, 难受的, <英方>精力旺盛的', '/fiəs | fɪəs | fɪrs/', 'fierce', 6);
INSERT INTO `words` VALUES (11934, NULL, 'n. [植]无花果, 无花果树, 无价值的东西, 少许, 一些, 服装', '/fiɡ | fɪg | fɪɡ/', 'fig', 6);
INSERT INTO `words` VALUES (11935, 'Being one myself, I know that they are not just some figment, but the truth of the matter is, gaming is male dominated, the same way knitting is dominated by females.', 'n. 臆造的事物, 虚构的事', '/\'fiɡmənt | \'fɪgm(ə)nt | \'fɪɡmənt/', 'figment', 6);
INSERT INTO `words` VALUES (11936, 'He’s my son, in the figurative sense of the word.', 'adj. 比喻的, 修饰丰富的, 形容多的', '/\'fiɡjurətiv | \'fɪg(ə)rətɪv; -gjʊ- | \'fɪgərətɪv/', 'figurative', 6);
INSERT INTO `words` VALUES (11937, 'The Queen is merely a figurehead.', 'n. 装饰船头的雕像, 破浪神, 有名无实的领袖', '/\'fiɡəhed | \'fɪgəhed | \'fɪgjɚ\'hɛd/', 'figurehead', 6);
INSERT INTO `words` VALUES (11938, 'Michelle and her mother once gave me a figurine of a beautiful black child sitting in a wheelchair.', 'n. 小雕像', '/\'fiɡjuri:n | \'fɪgəriːn; -gjʊ- | ,fɪɡjə\'rin/', 'figurine', 6);
INSERT INTO `words` VALUES (11939, 'an electric filament', 'n. 细丝, 灯丝', '/\'filəmənt | \'fɪləm(ə)nt | \'fɪləmənt/', 'filament', 6);
INSERT INTO `words` VALUES (11940, 'He filched a bottle of wine from the cellar.', 'v. 偷窃(不贵重的东西), 窃取', '/filtʃ | fɪltʃ/', 'filch', 6);
INSERT INTO `words` VALUES (11941, 'We will keep your details on file (= store them for later use ) .', 'n. 文件, 档案, 文件夹, 卷宗, 锉刀', '/faɪl/', 'file', 6);
INSERT INTO `words` VALUES (11942, '...a choice of filet of beef, grilled marinated chicken or broiled salmon.', 'n. 肉片, 鱼片', '/fi\'lei | \'fiːleɪ; \'fɪlɪt | fɪ\'le; \'fɪl,e/', 'filet', 6);
INSERT INTO `words` VALUES (11943, 'her filial duty', 'adj. 子女的, 孝顺的, 当做子女的', '/\'filjəl | \'fɪlɪəl/', 'filial', 6);
