INSERT INTO `words` VALUES (11951, 'The house was filthy, with clothes and newspapers strewn everywhere.', 'adj. 不洁的, 污秽的, 丑恶的', '/\'filθi | \'fɪlθɪ | \'fɪlθi/', 'filthy', 6);
INSERT INTO `words` VALUES (11952, 'It is a finable offence.', 'adj. 应罚款的, 可精制的, 可提炼的', '/\'fainəbl | \'faɪnəbl/', 'finable', 6);
INSERT INTO `words` VALUES (11953, NULL, 'v. 欺骗, 哄骗, 欺瞒', '/fi\'neiɡl | fɪ\'neɪg(ə)l/', 'finagle', 6);
INSERT INTO `words` VALUES (11954, 'the finale of a Broadway show', 'n. (戏剧的)最后一场, 结局, 终了, 最后的一个乐章, 终曲', '/fi\'nɑ:li | fɪ\'nɑːlɪ; -leɪ | fɪ\'næli/', 'finale', 6);
INSERT INTO `words` VALUES (11955, 'financial transactions', 'adj. 财政的， 金融的', '/faɪ\'nænʃl | faɪˈnænʃəl;fəˈnæ-/', 'financial', 6);
INSERT INTO `words` VALUES (11956, 'The scientists tried playing the same sound sample again with another group, and they got pissed, too -- virtually every finch that heard it, in fact.', 'n. [动]雀类(如燕雀,金翅雀等)', '/fintʃ | fɪn(t)ʃ | fɪntʃ/', 'finch', 6);
INSERT INTO `words` VALUES (11957, 'Dario played the sonata with great finesse.', 'n. 手腕, 精密技巧, 灵巧, 策略, 手段', '/fi\'nes | fɪ\'nes | fɪ\'nɛs/', 'finesse', 6);
INSERT INTO `words` VALUES (11958, 'She’s very finicky about what she eats.', 'adj. 过分注意的, 过分讲究的, 过分周到的', '/\'finiki | \'fɪnɪkɪ | \'fɪnɪki/', 'finicky', 6);
INSERT INTO `words` VALUES (11959, 'the earth’s finite resources', 'adj. 有限的', '/\'faɪnaɪt/', 'finite', 6);
