INSERT INTO `words` VALUES (11967, '...the fisheries off Newfoundland.', 'n. 渔业, 水产业, 渔场, 养鱼术', '/\'fiʃəri | \'fɪʃ(ə)rɪ | \'fɪʃəri/', 'fishery', 6);
INSERT INTO `words` VALUES (11968, 'Thus, we need to start getting rid of this material along with fissile material created for weapons use.', 'adj. 易分裂的, 易裂的, 分裂性的, 可分裂的, 裂变的', '/\'fisail | \'fɪsaɪl | \'fɪsl/', 'fissile', 6);
INSERT INTO `words` VALUES (11969, 'The state of being split or cleft; a fissure or division.', 'n. 裂缝, 裂沟, (思想, 观点等的)分歧', '/\'fiʃə | \'fɪʃə | \'fɪʃɚ/', 'fissure', 6);
INSERT INTO `words` VALUES (11970, 'John awoke from a fitful sleep .', 'adj. 断断续续的, 一阵阵的, 间歇的, 不定的, 不规则的', '/\'fitful | \'fɪtfʊl; -f(ə)l | \'fɪtfəl/', 'fitful', 6);
