INSERT INTO `words` VALUES (11973, 'a flabby stomach', 'adj. 优柔寡断的性格(或人), 软弱的, 没气力的, 不稳的, (肌肉等)不结实的, 松弛的', '/\'flæbi | \'flæbɪ/', 'flabby', 6);
