INSERT INTO `words` VALUES (11975, 'Children waving flags greeted the Russian leader.', 'n. 旗, 标记', '/flæɡ | flæg/', 'flag', 6);
INSERT INTO `words` VALUES (11976, NULL, 'v. 鞭打, 鞭挞', '/\'flædʒəleit | \'flædʒ(ə)leɪt | \'flædʒəlet/', 'flagellate', 6);
INSERT INTO `words` VALUES (11977, 'He presents himself as the man to revive the party’s flagging fortunes .', 'adj. 下垂的； 衰弱的', '/\'flægiŋ/', 'flagging', 6);
INSERT INTO `words` VALUES (11978, NULL, 'adj. 多扁石的, 多菖蒲的', '/\'flæɡi/', 'flaggy', 6);
INSERT INTO `words` VALUES (11979, 'His failure to turn his attention to flagrant wastes of public money is inexcusable.', 'adj. 非常的, 不能容忍的, 恶名昭著的, 公然的', '/\'fleɪgr(ə)nt | \'fleɡrənt/', 'flagrant', 6);
INSERT INTO `words` VALUES (11980, 'We don\'t know of any other species that uses its body like a flail.', 'n. 连枷', '/fleil | fleɪl | flel/', 'flail', 6);
INSERT INTO `words` VALUES (11981, 'Jo has a flair for languages.', 'n. 才能, 本领', '/fleə | flɛr/', 'flair', 6);
INSERT INTO `words` VALUES (11982, 'Lilley has taken a lot of flak for his views on drugs.', 'n. 高射炮火', '/fleik | flæk/', 'flak', 6);
INSERT INTO `words` VALUES (11983, 'Poach the fish until it flakes easily.', 'v. 使成薄片', '/fleɪk | flek/', 'flake', 6);
INSERT INTO `words` VALUES (11984, 'Therefore, its floral language is flamboyance.', 'n. 华丽, 火焰', '/flæm\'bɔiəns/', 'flamboyance', 6);
INSERT INTO `words` VALUES (11985, 'He lifted his arms in a flamboyant gesture .', 'adj. 辉耀的, 华丽的, 火焰似的, 艳丽的', '/\'flæm\'bɔiənt | flæm\'bɒɪənt | flæm\'bɔɪənt/', 'flamboyant', 6);
