INSERT INTO `words` VALUES (11991, 'He took out a metal flask from a canvas bag.', 'n. 瓶, 长颈瓶, 细颈瓶, 烧瓶, 小水瓶', '/flɑ:sk | flɑːsk | flæsk/', 'flask', 6);
INSERT INTO `words` VALUES (11992, NULL, 'n. 小细颈瓶, 小烧瓶', '/\'flɑːskɪt | \'flæskɪt/', 'flasket', 6);
INSERT INTO `words` VALUES (11993, 'One more detail: one of the railroad branch lines ran not far from the hospital. There was a heavy gun on a specially equipped open flatcar connected to a locomotive.', 'n. 无盖货车, 平台货车', '/\'flæt,kɑ: | \'flætkɑː | \'flætkɑr/', 'flatcar', 6);
INSERT INTO `words` VALUES (11994, 'Use a rolling pin to flatten the dough.', 'v. 变平； 彻底打败， 击倒', '/\'flætn/', 'flatten', 6);
INSERT INTO `words` VALUES (11995, 'Perry would always flatter Mrs. Mitchell by praising her cooking.', 'v. 恭维， 奉承', '/\'flætər | \'flætɚ/', 'flatter', 6);
INSERT INTO `words` VALUES (11996, 'It’s also problematic because of a high sodium content, extremely low protein, feelings of weakeness, and increased flatulence.', 'n. 肠胃气胀', '/\'flætjuləns | \'flætʃələns/', 'flatulence', 6);
INSERT INTO `words` VALUES (11997, NULL, 'adj. 自负的， 浮夸的', '/\'flætʃələnt/', 'flatulent', 6);
