INSERT INTO `words` VALUES (12001, 'A design flaw (= a mistake or weakness in the way something was made ) caused the engine to explode.', 'v. 生裂缝； 变得有缺陷; n. 瑕疵', '/flɔː | flɔ/', 'flaw', 6);
INSERT INTO `words` VALUES (12002, 'a flawed concept', 'adj. 有缺点的； 错误的', '/flɔːd | flɔd/', 'flawed', 6);
INSERT INTO `words` VALUES (12003, 'Adrian’s flawless French', 'adj. 无瑕疵的, 无缺点的, 无裂缝的', '/\'flɔ:lis | \'flɔːləs | \'flɔləs/', 'flawless', 6);
INSERT INTO `words` VALUES (12004, NULL, 'n. 亚麻, 麻布, 亚麻织品, 亚麻制的', '/flæks/', 'flax', 6);
INSERT INTO `words` VALUES (12005, 'She was well-known for flaying public officials in her daily column.', 'v. 剥皮, 去皮, 抢夺, 严厉批评', '/flei | fleɪ | fle/', 'flay', 6);
INSERT INTO `words` VALUES (12006, 'He went to the men\'s room to wash flecks of blood from his shirt.', 'n. (皮肤的)斑点, 雀斑, 斑纹, 微粒', '/flek | flɛk/', 'fleck', 6);
INSERT INTO `words` VALUES (12007, NULL, 'adj. 羽毛丰满的, 快会飞的, 随时能飞的', '/fledʒd | flɛdʒd/', 'fledged', 6);
INSERT INTO `words` VALUES (12008, '...when fledglings are almost ready to leave the nests.', 'n. 羽毛初长的雏鸟, 刚会飞的幼鸟, 无经验的人, 初出茅庐的人', '/\'fledʒliŋ | \'fledʒlɪŋ | \'flɛdʒlɪŋ/', 'fledgling', 6);
INSERT INTO `words` VALUES (12009, '...a special protein which triggers the animal to shed its fleece.', 'n. 羊毛(尤指未剪下的), 羊毛状之物, 绒头织物, 羊毛大衣呢', '/\'fli:s | fliːs | flis/', 'fleece', 6);
INSERT INTO `words` VALUES (12010, 'Atalanta was fleet of foot (= able to run quickly ) .', 'adj. 快速的; v. 消磨， 疾驰； 飞逝， 掠过', '/fliːt | flit/', 'fleet', 6);
INSERT INTO `words` VALUES (12011, 'Time is fleeting.; Time flies.', 'adj. 飞逝的；短暂的', '/\'fli:tiŋ | \'fliːtɪŋ | \'flitɪŋ/', 'fleeting', 6);
INSERT INTO `words` VALUES (12012, 'He slowly flexed his muscles and tried to stand.', 'v. 弯曲(四肢), 伸缩, 折曲vi折曲, 弯曲', '/\'fleks | fleks | flɛks/', 'flex', 6);
INSERT INTO `words` VALUES (12013, 'We can be flexible about your starting date.', 'adj. 柔韧性, 易曲的, 灵活的, 柔软的, 能变形的, 可通融的', '/\'fleksibl | \'fleksɪb(ə)l | \'flɛksəbl/', 'flexible', 6);
INSERT INTO `words` VALUES (12014, 'With a flick of the wrist , Frye sent the ball into the opposite court.', 'n. (用鞭)快速的轻打, 轻打声, 弹开', '/\'flik | flɪk/', 'flick', 6);
INSERT INTO `words` VALUES (12015, 'Looking through the window I saw the flicker of flames.', 'n. 扑动, 闪烁, 闪光, 颤动', '/\'flikə | \'flɪkə | \'flɪkɚ/', 'flicker', 6);
INSERT INTO `words` VALUES (12016, 'The flickering insect halo began to drift slowly away, keeping a constant six feet above the earth.', 'adj. 闪烁的， 摇曳的， 忽隐忽现的', '/\'flɪkərɪŋ | \'flikəriŋ/', 'flickering', 6);
INSERT INTO `words` VALUES (12017, 'Isabelle was a frivolous little fool, vain and flighty.', 'adj. 忽发奇想的, 反复无常的, 轻浮的, 轻狂的, 心情浮动的', '/\'flaiti | \'flaɪtɪ/', 'flighty', 6);
INSERT INTO `words` VALUES (12018, 'I was sick of his intellectual flimflam.', 'n. 欺骗； 胡言乱语', '/\'flɪmflæm | \'flimflæm/', 'flimflam', 6);
INSERT INTO `words` VALUES (12019, 'a flimsy cotton dress', 'adj. 易坏的, 脆弱的, 浅薄的, 没有价值的, 不足信的, (人)浮夸的', '/\'flimzi | \'flɪmzɪ | \'flɪmzi/', 'flimsy', 6);
INSERT INTO `words` VALUES (12020, 'Leo stared back at him without flinching.', 'v. 畏缩, 退缩, 畏首畏尾', '/flintʃ | \'flɪn(t)ʃ | flɪntʃ/', 'flinch', 6);
INSERT INTO `words` VALUES (12021, '...a flint arrowhead.', 'n. 打火石, 极硬的东西, 燧石', '/flint | flɪnt/', 'flint', 6);
INSERT INTO `words` VALUES (12022, '...her flinty stare.', 'adj. 坚硬的, 冷酷的, 强硬的, 严峻的, 含燧石的, 强硬的, 严峻的, 燧石似的', '/\'flinti | \'flɪntɪ | \'flɪnti/', 'flinty', 6);
INSERT INTO `words` VALUES (12023, 'I was fed up with his flip comments.', 'v. 用指轻弹；蹦蹦跳跳; adj. 无礼的； 冒失的； 轻率的', '/flɪp/', 'flip', 6);
INSERT INTO `words` VALUES (12024, NULL, 'adj. 无礼, 轻率, 浮躁', '/\'flipənsi | \'flɪp(ə)nsɪ | \'flɪpənsi/', 'flippancy', 6);
INSERT INTO `words` VALUES (12025, 'a rather flippant remark', 'adj. <古>能说会道的, 轻率的, 没礼貌的, 嘴碎的', '/\'flipənt | \'flɪp(ə)nt | \'flɪpənt/', 'flippant', 6);
INSERT INTO `words` VALUES (12026, NULL, 'v. 忽然弹出, 挥动', '/flə:t | flɜːt | flɝt/', 'flirt', 6);
INSERT INTO `words` VALUES (12027, 'He was dashing, self-confident and flirtatious.', 'adj. 爱调戏的, 轻浮的', '/flə:\'teiʃəs | flɜː\'teɪʃəs | flɝ\'teʃəs/', 'flirtatious', 6);
INSERT INTO `words` VALUES (12028, 'Birds flitted about in the trees above them.', 'v. 掠过， 迅速飞过', '/flɪt/', 'flit', 6);
INSERT INTO `words` VALUES (12029, 'They kept a small flock of sheep.', 'n. 羊群, (禽、畜等的)群, 大量, 众多', '/flɔk | flɒk | flɑk/', 'flock', 6);
INSERT INTO `words` VALUES (12030, 'a floppy hat', 'adj. 懒散的, 邋遢的, 松软的', '/\'flɔpi | \'flɒpɪ | \'flɑpi/', 'floppy', 6);
INSERT INTO `words` VALUES (12031, NULL, 'n. [罗神]花神', '/\'flɔrə/', 'flora', 6);
INSERT INTO `words` VALUES (12032, 'a scarf with a bold floral pattern', 'adj. 花的， 植物的', '/\'flɔːrəl | \'flɔrəl/', 'floral', 6);
INSERT INTO `words` VALUES (12033, 'a middle-aged man with a florid complexion', 'adj. 华丽的, 红润的, 炫耀的, 绚丽的', '/\'flɔ:rid | \'flɒrɪd | \'flɔrɪd/', 'florid', 6);
INSERT INTO `words` VALUES (12034, NULL, 'n. 选集, 作品集锦, 群芳谱', '/,flɔri\'lidʒiəm/', 'florilegium', 6);
INSERT INTO `words` VALUES (12035, NULL, 'adj. 华丽的， 时髦的； 丝棉般的， 柔软的', '/\'flɑːsi | \'flɑsi/', 'flossy', 6);
INSERT INTO `words` VALUES (12036, 'More and more firms are floundering because of the recession.', 'v. (在水中)挣扎, 困难地往前走, 踌躇, 发慌', '/\'flaundə | \'flaʊndə | \'flaʊndɚ/', 'flounder', 6);
INSERT INTO `words` VALUES (12037, 'The economy is booming and small businesses are flourishing.', 'v. 繁荣， 兴旺； 活跃而有影响力', '/\'flɜːrɪʃ | ˈflɜːrɪʃ/', 'flourish', 6);
INSERT INTO `words` VALUES (12038, '...illegal campers who persist in flouting the law.', 'v. 轻视, 嘲笑, 愚弄', '/\'flaut | flaʊt/', 'flout', 6);
INSERT INTO `words` VALUES (12039, 'Insect populations fluctuate wildly from year to year.', 'v. 变动, 波动, 涨落, 上下, 动摇', '/\'flʌktjueit | \'flʌktʃʊeɪt; -tjʊ- | \'flʌktʃʊ\'et/', 'fluctuate', 6);
INSERT INTO `words` VALUES (12040, 'Prices are subject to fluctuation.', 'n. 波动， 起伏， 涨落', '/ˌflʌktʃu\'eɪʃn | ,flʌktʃʊ\'eʃən/', 'fluctuation', 6);
INSERT INTO `words` VALUES (12041, 'Cream the butter and sugar until the mixture is light and fluffy.', 'adj. 绒毛似的, 披着绒毛的, 蓬松的, 愚蠢的', '/\'flʌfi | \'flʌfɪ/', 'fluffy', 6);
INSERT INTO `words` VALUES (12042, 'a loose, fluid style of dancing', 'adj. 流体的， 流动的； 易变的， 不固定的', '/\'fluːɪd | \'fluɪd/', 'fluid', 6);
INSERT INTO `words` VALUES (12043, 'As recently as a year ago people wondered whether M-PESA’s success was a fluke.', 'v. 侥幸成功, 意外受挫', '/fluk | fluːk/', 'fluke', 6);
INSERT INTO `words` VALUES (12044, 'The two leaders were flummoxed by the suggestion.', 'v. 使惶惑, 打乱, 使狼狈, 使混乱', '/\'flʌmɔks | \'flʌməks/', 'flummox', 6);
INSERT INTO `words` VALUES (12045, 'But let’s face it, life is filled with all kinds of tests — some you ace and some you flunk — so at some point you have to get used to it.', 'n. 失败, 不及格', '/flʌŋk/', 'flunk', 6);
INSERT INTO `words` VALUES (12046, '...a piece of fluorescent tape.', 'adj. 荧光的, 莹光的', '/fluə\'resnt | flʊə\'res(ə)nt; flɔː- | ,flɔ\'rɛsnt/', 'fluorescent', 6);
INSERT INTO `words` VALUES (12047, 'His words brought a warm flush to her face.', 'n. 奔流, 晕红, 激动, 萌芽, 活力旺盛, 发烧, 一手同花的五张牌, 惊鸟', '/flʌʃ/', 'flush', 6);
INSERT INTO `words` VALUES (12048, NULL, 'n. 慌乱, 狼狈, 混乱, 激动', '/\'flʌstə | \'flʌstɚ/', 'fluster', 6);
INSERT INTO `words` VALUES (12049, 'Paul was looking flustered and embarrassed.', 'adj. 慌张的， 激动不安的', '/\'flʌstərd | \'flʌstəd/', 'flustered', 6);
INSERT INTO `words` VALUES (12050, 'A small bird fluttered past the window.', 'v. 拍翅 to move lightly and quickly)', '/\'flʌtər | \'flʌtɚ/', 'flutter', 6);
INSERT INTO `words` VALUES (12051, NULL, 'adj. 河流的， 生长在河中的', '/\'fluːviəl | \'flʊvɪəl/', 'fluvial', 6);
INSERT INTO `words` VALUES (12052, 'So without having to repeat all those parameters just assume that when I write down flux it represents these variables.', 'n. 涨潮, 变迁, [物]流量, 通量', '/flʌks/', 'flux', 6);
INSERT INTO `words` VALUES (12053, '...fodder for horses.', 'n. 饲料, 草料, (创作的)素材, 弹药', '/\'fɔdə | \'fɒdə | \'fɑdɚ/', 'fodder', 6);
INSERT INTO `words` VALUES (12054, 'In this chapter we will look at what happens when a human foetus receives too much or too little male hormone.', 'n. 胎儿', '/\'fi:təs | \'fiːtəs | \'fitəs/', 'foetus', 6);
INSERT INTO `words` VALUES (12055, NULL, 'n. 过时的人,守旧的人', '/\'fəuɡrəm/', 'fogram', 6);
INSERT INTO `words` VALUES (12056, 'We all have our little foibles .', 'n. 弱点, (性格上的)缺点, 自负的地方, 怪癖, 癖好, (刀剑)自中部至尖端的部分', '/\'fɔibl | \'fɒɪb(ə)l/', 'foible', 6);
INSERT INTO `words` VALUES (12057, 'chocolates in foil wrappers', 'n. 箔, 金属薄片, [建]叶形片, 烘托, 衬托', '/fɔil | fɔɪl/', 'foil', 6);
INSERT INTO `words` VALUES (12058, NULL, 'v. 偷偷插入； 强加', '/fɔɪst/', 'foist', 6);
INSERT INTO `words` VALUES (12059, 'Bend back the card and cut along the fold.', 'n. 折, 羊栏, 折痕, 信徒', '/fəuld | fəʊld | fold/', 'fold', 6);
INSERT INTO `words` VALUES (12060, NULL, 'n. 废物, 废话, 不值钱的东西, 胡闹', '/\'fɔldərɔl | \'fɒldərɒl/', 'folderol', 6);
INSERT INTO `words` VALUES (12061, '...shrubs with grey or silver foliage.', 'n. 树叶, 植物', '/\'fəuliidʒ | \'fəʊlɪɪdʒ | \'folɪɪdʒ/', 'foliage', 6);
INSERT INTO `words` VALUES (12062, 'In Chinese folklore the bat is a symbol of good fortune.', 'n. 民间传说', '/\'fəuklɔ: | \'fəʊklɔː | \'foklɔr/', 'folklore', 6);
INSERT INTO `words` VALUES (12063, 'The town had a certain folksy charm.', 'adj. 亲切的， 友好的', '/\'fouksi | \'foksi/', 'folksy', 6);
INSERT INTO `words` VALUES (12064, 'It\'s sheer folly to build nuclear power stations in a country that has dozens of earthquakes every year.', 'n. 愚蠢； 愚蠢的想法或做法', '/\'fɑːli | \'fɑli/', 'folly', 6);
INSERT INTO `words` VALUES (12065, 'They accused strike leaders of fomenting violence.', 'v. [医]热敷, 热罨, 煽动', '/\'fəument | fə(ʊ)\'ment/', 'foment', 6);
INSERT INTO `words` VALUES (12066, NULL, 'n. 煽动', '/,fəumen\'teiʃən | ,fəʊmen\'teɪʃ(ə)n/', 'fomentation', 6);
INSERT INTO `words` VALUES (12067, 'She fondled his neck.', 'v. 抚弄', '/\'fɔndl | \'fɒnd(ə)l | \'fɑndl/', 'fondle', 6);
INSERT INTO `words` VALUES (12068, 'a shortage of basic foodstuffs', 'n. 食品, 粮食', '/\'fudstʌf | \'fuːdstʌf/', 'foodstuff', 6);
INSERT INTO `words` VALUES (12069, 'a foolhardy attempt to capture more territory', 'adj. 愚勇的, 有勇无谋的', '/\'fu:l,hɑ:di | \'fuːlhɑːdɪ | \'fulhɑrdi/', 'foolhardy', 6);
INSERT INTO `words` VALUES (12070, 'a foolproof way of preventing credit card fraud', 'adj. 十分简单的, 十分安全的, 极坚固的', '/\'fu:l,pru:f | \'fuːlpruːf | \'fulpruf/', 'foolproof', 6);
INSERT INTO `words` VALUES (12071, 'Businesses are investing millions of dollars to gain a foothold in this new market.', 'n. 立足处', '/\'fut,həuld | \'fʊthəʊld | \'fʊt\'hold/', 'foothold', 6);
INSERT INTO `words` VALUES (12072, 'Not arrogate to oneself professions9 see joke : My friendly mouth is stupid very , often say the footle that a few your people find both funny and annoying .', 'n. 呆话, 傻事', '/\'fu:tl | \'fuːt(ə)l/', 'footle', 6);
INSERT INTO `words` VALUES (12073, 'footloose students traveling around Europe', 'adj. 自由自在的, 到处走动的', '/\'fut,lu:s | \'fʊtluːs/', 'footloose', 6);
INSERT INTO `words` VALUES (12074, NULL, 'v. 笨拙地做', '/\'fuːz(ə)l | \'fʊzl/', 'foozle', 6);
INSERT INTO `words` VALUES (12075, NULL, 'n. 过分讲究衣饰或举动的人, 花花公子', '/fɔp | fɒp | fɑp/', 'fop', 6);
INSERT INTO `words` VALUES (12076, NULL, 'adj. 浮华的, 有纨绔习气的', '/\'fɔpiʃ | \'fɑpɪʃ/', 'foppish', 6);
INSERT INTO `words` VALUES (12077, 'Such forage fish already account for nearly a fifth of the world’s total annual catch; another fifth goes to feed pigs and poultry.', 'n. 草料', '/\'fɔridʒ | \'fɒrɪdʒ | \'fɔrɪdʒ/', 'forage', 6);
INSERT INTO `words` VALUES (12078, NULL, 'n. 强征队员, 抢劫者', NULL, 'forager', 6);
INSERT INTO `words` VALUES (12079, NULL, 'adj. 有小孔的', '/fə\'ræmineit/', 'foraminate', 6);
INSERT INTO `words` VALUES (12080, 'These base camps were used by the PKK guerrillas to make forays into Turkey.', 'v. <古>劫掠', '/\'fɒreɪ | \'fɔre/', 'foray', 6);
INSERT INTO `words` VALUES (12081, 'I forbore to comment on this.', 'v. 克制； 忍耐', '/fɔːr\'ber | fɔr\'bɛr/', 'forbear', 6);
INSERT INTO `words` VALUES (12082, NULL, 'n. 自制, 忍耐, [律]债务偿还期的延展', '/fɔ:bεərəns | fɔː\'beər(ə)ns | fɔr\'bɛrəns/', 'forbearance', 6);
INSERT INTO `words` VALUES (12083, 'By long forbearing is a prince persuaded, and a soft tongue breaketh the bone.', 'adj. 忍耐的, 宽容的', '/fɔ:\'bεəriŋ | fɔr\'bɛrɪŋ/', 'forbearing', 6);
INSERT INTO `words` VALUES (12084, 'His face was forbidding, even hostile.', 'adj. 可怕的, 令人难亲近的', '/fə\'bidiŋ | fə\'bɪdɪŋ | fɚ\'bɪdɪŋ/', 'forbidding', 6);
INSERT INTO `words` VALUES (12085, 'a pair of forceps', 'n. 镊子, 钳子', '/\'fɔ:seps | \'fɔːseps; -sɪps | \'fɔrsɛps/', 'forceps', 6);
INSERT INTO `words` VALUES (12086, NULL, 'n. 浅滩', '/fɔːd | fɔrd/', 'ford', 6);
INSERT INTO `words` VALUES (12087, 'can be, if I forebode aright, no power, short of the Divine mercy, to disclose, whether by uttered words, or by type or emblem, the secrets that may be buried with a human heart.', 'v. 预示, 预言, 预兆, 预感', '/fɔ:\'bəud | fɔː\'bəʊd/', 'forebode', 6);
INSERT INTO `words` VALUES (12088, 'She waited for news with a grim sense of foreboding .', 'n. 预感, 先兆, 预兆', '/fɔ:\'bəudiŋ | fɔː\'bəʊdɪŋ | fɔr\'bodɪŋ/', 'foreboding', 6);
INSERT INTO `words` VALUES (12089, 'Rain was forecast for the weekend.', 'v. 预报，预测; n. 预测', '/\'fɔːrkæst | \'fɔrkæst/', 'forecast', 6);
INSERT INTO `words` VALUES (12090, 'The bank foreclosed on the mortgage for his previous home.', 'v. 排除在外, 妨碍, 自称, 阻止, 预先处理, 取消抵押品赎回权', '/fɔ:\'kləuz | fɔː\'kləʊz | fɔr\'kloz/', 'foreclose', 6);
INSERT INTO `words` VALUES (12091, 'She has maintained that the General had foreknowledge of the plot.', 'n. 预知， 先见之明', '/fɔːr\'nɑːlɪdʒ/', 'foreknowledge', 6);
INSERT INTO `words` VALUES (12092, 'They were convicted on forensic evidence alone.', 'adj. 法院的, 适于法庭的, 公开辩论的', '/fɔ\'rensik | fə\'rensɪk | fə\'rɛnsɪk/', 'forensic', 6);
INSERT INTO `words` VALUES (12093, 'To foreordain or elect by divine will or decree.', 'v. 预先, 注定, 预定命运', '/,fɔ:rɔ:\'dein | ,fɔːrɔː\'deɪn/', 'foreordain', 6);
INSERT INTO `words` VALUES (12094, '...a machine which, in some respects, was the forerunner of the modern helicopter.', 'n. 先驱(者), 传令官, 预兆', '/\'fɔ:,rʌnə | \'fɔːrʌnə | \'fɔr\'rʌnɚ/', 'forerunner', 6);
INSERT INTO `words` VALUES (12095, 'The revolution foreshadowed an entirely new social order.', 'v. 成为先兆， 预示', '/fɔːr\'ʃædou | fɔr\'ʃædo/', 'foreshadow', 6);
INSERT INTO `words` VALUES (12096, 'It was an example of the authorities’ lack of foresight .', 'n. 远见， 深谋远虑', '/\'fɔːrsaɪt | \'fɔrsaɪt/', 'foresight', 6);
INSERT INTO `words` VALUES (12097, 'a measure intended to forestall further attacks', 'v. 预先阻止， 先发制人', '/fɔːr\'stɔːl/', 'forestall', 6);
INSERT INTO `words` VALUES (12098, '...a thickly forested valley.', 'adj. 树木丛生的', '/\'fɔːrɪstɪd | \'fɔrɪstɪd/', 'forested', 6);
INSERT INTO `words` VALUES (12099, 'It was a foretaste of things to come.', 'n. 预示', '/\'fɔ:teist | \'fɔːteɪst/', 'foretaste', 6);
INSERT INTO `words` VALUES (12100, 'She has written the foreword to a book of recipes.', 'n. 前言， 序', '/\'fɔːrwɜːrd | \'fɔrwɝd/', 'foreword', 6);
INSERT INTO `words` VALUES (12101, 'By being absent from the trial, he forfeited the right to appeal.', 'v. 丧失，被罚没收; n. 丧失的东西', '/\'fɔːrfət | \'fɔrfət/', 'forfeit', 6);
INSERT INTO `words` VALUES (12102, 'Refusal to sign meant forfeiture of property and exile.', 'n. 丧失, 没收物, 罚款', '/\'fɔ:fitʃə | \'fɔːfɪtʃə(r) | \'fɔrfətʃɚ/', 'forfeiture', 6);
INSERT INTO `words` VALUES (12103, 'Someone stole my credit card and forged my signature.', 'v. 稳步前进, 铸造, 伪造', '/fɔ:dʒ | fɔːdʒ | fɔrdʒ/', 'forge', 6);
INSERT INTO `words` VALUES (12104, 'Okay he is actually a convicted forger and embezzler but does that mean his books are worthless?', 'n. 伪造者, 铁匠, 赝造者', '/\'fɔ:dʒə | \'fɔːdʒə(r) | \'fɔrdʒɚ/', 'forger', 6);
INSERT INTO `words` VALUES (12105, 'The painting was a very clever forgery.', 'n. 伪造物, 伪造罪, 伪造', '/\'fɔ:dʒəri | \'fɔːdʒ(ə)rɪ | \'fɔrdʒəri/', 'forgery', 6);
INSERT INTO `words` VALUES (12106, 'I had to forgo lunch.', 'v. 作罢, 放弃', '/fɔːˈɡəʊ | fɔː\'gəʊ; fə- | fɔr\'ɡo/', 'forgo', 6);
INSERT INTO `words` VALUES (12107, 'a forlorn figure sitting all by herself', 'adj. 被遗弃的', '/fə\'lɔ:n | fə\'lɔːn | fɚ\'lɔrn/', 'forlorn', 6);
INSERT INTO `words` VALUES (12108, 'In the West, job interviews are highly formalized and systematic.', 'adj. 形式化的， 正式的', '/\'fɔːrməlaɪzd/', 'formalized', 6);
INSERT INTO `words` VALUES (12109, 'The courses were run to a consistent format.', 'n. 开本, 版式, 形式, 格式', '/\'fɔ:mæt | \'fɔːmæt | \'fɔrmæt/', 'format', 6);
INSERT INTO `words` VALUES (12110, 'We now know a lot more about the early stages of planetary formation.', 'n. 组成， 形成； 编队， 排列', '/fɔːr\'meɪʃn | fɔr\'meʃən/', 'formation', 6);
INSERT INTO `words` VALUES (12111, 'Any narrative, any model, that could embody the fundamental organizing principles of human affairs can only be vague in its formative stages.', 'adj. 格式化的', '/\'fɔ:mətiv | \'fɔːmətɪv | \'fɔrmətɪv/', 'formative', 6);
INSERT INTO `words` VALUES (12112, 'The building is grey, formidable, not at all picturesque.', 'adj. 强大的, 令人敬畏的, 可怕的, 艰难的', '/\'fɔ:midəbl | \'fɔːmɪdəb(ə)l; fɔː\'mɪd- | \'fɔrmɪdəbl/', 'formidable', 6);
INSERT INTO `words` VALUES (12113, NULL, 'adv. 可怕地， 难对付地， 强大地', '/\'fɔ:midəbli | \'fɔːrmɪdəbli/', 'formidably', 6);
INSERT INTO `words` VALUES (12114, 'Children love jokes and riddles that are heavily formulaic.', 'adj. 公式的， 刻板的', '/ˌfɔːrmju\'leɪɪk | ,fɔ:mju\'leiik/', 'formulaic', 6);
INSERT INTO `words` VALUES (12115, 'We are studying the situation but have not formulated any response yet.', 'v. 用公式表示, 明确地表达, 作简洁陈述', '/\'fɔ:mjuleit | \'fɔːmjʊleɪt | \'fɔrmjə\'let/', 'formulate', 6);
INSERT INTO `words` VALUES (12116, 'One of the soldiers chance upon a girl from a mysterious tribe, that is cursed such that its members who fornicate with outsiders will, together with them, transform into wolves.', 'v. 通奸', '/\'fɔ:nikeit | \'fɔːnɪkeɪt | \'fɔrnɪket/', 'fornicate', 6);
INSERT INTO `words` VALUES (12117, 'children forsaken by their parents', 'v. 放弃, 抛弃', '/fɔ\'seik | fə\'seɪk | fɔrˈsek, fə-/', 'forsake', 6);
INSERT INTO `words` VALUES (12118, 'The party was offered a share of government if it forswore violence.', 'v. 幸运', '/fɔ:\'swεə | fɔː\'sweə; fə- | fɔr\'swɛr/', 'forswear', 6);
INSERT INTO `words` VALUES (12119, NULL, 'n. 堡垒, 边界上的贸易站', '/fɔ:t | fɔːt | fɔrt/', 'fort', 6);
INSERT INTO `words` VALUES (12120, 'He found that running long distances was not his forte .', 'n. 长处', '/\'fɔ:t | \'fɔːteɪ; \'fɔːtɪ; fɔːt | \'fɔrte/', 'forte', 6);
INSERT INTO `words` VALUES (12121, 'She answered in her usual forthright manner .', 'adj. 直率的', '/\'fɔːrθraɪt | ,fɔ:θ\'rait/', 'forthright', 6);
INSERT INTO `words` VALUES (12122, 'Her position was fortified by election successes and economic recovery.', 'v. 加强， 巩固', '/\'fɔːrtɪfaɪ | \'fɔrtɪfaɪ/', 'fortify', 6);
INSERT INTO `words` VALUES (12123, 'Winnie is a woman of quiet fortitude who has endured a lot of suffering.', 'n. 坚韧', '/\'fɔ:titju:d | \'fɔːtɪtjuːd/', 'fortitude', 6);
INSERT INTO `words` VALUES (12124, '...a 13th-century fortress.', 'n. 堡垒, 要塞', '/\'fɔ:tris | \'fɔːtrɪs | \'fɔrtrəs/', 'fortress', 6);
INSERT INTO `words` VALUES (12125, 'The meeting with Jack was fortuitous.', 'adj. 偶然的, 幸运的', '/fɔ:\'tjuitəs | fɔː\'tjuːɪtəs | fɔr\'tuɪtəs/', 'fortuitous', 6);
INSERT INTO `words` VALUES (12126, 'Members of the council agreed that was an important forum for discussion.', 'n. 古罗马城镇的广场(或市场), 论坛, 法庭, 讨论会', '/\'fɔ:rəm | \'fɔːrəm | \'fɔrəm/', 'forum', 6);
INSERT INTO `words` VALUES (12127, 'My father thinks she’s far too forward for a young girl.', 'adj. 过激的； 莽撞的， 冒失的， 无礼的', '/\'fɔːrwərd | \'fɔrwɚd/', 'forward', 6);
INSERT INTO `words` VALUES (12128, NULL, 'n. 卤莽, 早熟, 热心', '/\'fɔ:wədnis/', 'forwardness', 6);
INSERT INTO `words` VALUES (12129, 'Most couples, however fossilized their relationship, have some interests in common.', 'v. 使成为化石； 使过时', '/\'fɑːsəlaɪz | \'fɔsilaiz/', 'fossilize', 6);
INSERT INTO `words` VALUES (12130, 'The notion of using fossilized dead forests to prevent the destruction of living forests and all that they hold, is apt.', 'adj. 变成化石的', '/\'fɔsilaizd | \'fɑːsəlaɪzd/', 'fossilized', 6);
INSERT INTO `words` VALUES (12131, 'The bishop helped foster the sense of a community embracing all classes.', 'v. 鼓励， 促进； 养育， 抚养', '/\'fɔːstər | \'fɔstɚ/', 'foster', 6);
INSERT INTO `words` VALUES (12132, 'Refugees in the camps are short of food and at risk from foul water.', 'adj. 污秽的, 邪恶的, 肮脏的, 淤塞的, 恶劣的', '/faul | faʊl/', 'foul', 6);
INSERT INTO `words` VALUES (12133, 'He was one of the founders of the university\'s medical faculty.', 'n. 铸工, 翻沙工, 创始人, 奠基人', '/\'faundə | \'faʊndə(r) | \'faʊndɚ/', 'founder', 6);
INSERT INTO `words` VALUES (12134, 'I went and waited in the foyer.', 'n. 休息室, 大厅', '/\'fɔiei | ˈfɔɪeɪ | ˈfɔɪər/', 'foyer', 6);
INSERT INTO `words` VALUES (12135, 'Eight people were injured in the fracas.', 'n. 喧噪, 吵闹', '/\'frækɑ: | \'frækɑː | \'frekəs/', 'fracas', 6);
INSERT INTO `words` VALUES (12136, 'The students had a grasp of decimals, percentages and fractions.', 'n. 小部分, 片断, 分数', '/\'frækʃən | \'frækʃ(ə)n/', 'fraction', 6);
INSERT INTO `words` VALUES (12137, 'a fractional increase', 'adj. 部分的, 碎片的, 分数的, 小数的, 分馏的', '/\'frækʃənl | \'frækʃ(ə)n(ə)l/', 'fractional', 6);
INSERT INTO `words` VALUES (12138, 'Children become fractious when they are tired.', 'adj. 易怒的, 倔强的, 脾气不好的', '/\'frækʃəs/', 'fractious', 6);
INSERT INTO `words` VALUES (12139, 'a stress fracture in his left knee', 'n. 破裂, 骨折', '/\'fræktʃə | \'fræktʃɚ/', 'fracture', 6);
INSERT INTO `words` VALUES (12140, 'Be careful with that vase – it’s very fragile.', 'adj. 易碎的, 脆的', '/\'frædʒail | \'frædʒaɪl | \'frædʒəl/', 'fragile', 6);
INSERT INTO `words` VALUES (12141, 'glass fragments', 'n. 碎片； 片段', '/\'frægmənt | \'fræɡmənt/', 'fragment', 6);
INSERT INTO `words` VALUES (12142, 'a fragmentary account', 'adj. 由碎片组成的, 断断续续的', '/fræɡ\'mentəri | \'frægm(ə)nt(ə)rɪ | \'frægmən\'tɛri/', 'fragmentary', 6);
INSERT INTO `words` VALUES (12143, '...a shrubby plant with a strong characteristic fragrance.', 'n. 香料； 香味', '/\'freɪgrəns | \'fregrəns/', 'fragrance', 6);
INSERT INTO `words` VALUES (12144, 'fragrant flowers', 'adj. 芳香的', '/\'freɪgrənt | \'fregrənt/', 'fragrant', 6);
INSERT INTO `words` VALUES (12145, '{\"COLLOINEXA\":[\"frail elderly people\"]}', 'adj. 虚弱的, 脆弱的, (意志)薄弱的', '/freil | freɪl | frel/', 'frail', 6);
INSERT INTO `words` VALUES (12146, '{\"COLLOINEXA\":[\"human frailties\"]}', 'n. 虚弱, 脆弱, 意志薄弱, 过失, 品德上的弱点', '/\'freilti | \'freɪltɪ | \'frelti/', 'frailty', 6);
INSERT INTO `words` VALUES (12147, 'I spent three frantic days trying to get everything ready.', 'adj. 狂乱的, 疯狂的', '/\'fræntik | \'fræntɪk/', 'frantic', 6);
INSERT INTO `words` VALUES (12148, 'fraternal loyalty', 'adj. 兄弟的, 兄弟般的, 友爱的', '/frə\'tə:nl | frə\'tɜːn(ə)l | frə\'tɝnl/', 'fraternal', 6);
INSERT INTO `words` VALUES (12149, 'fraternity between nations', 'n. 兄弟关系, 友爱, 互助会, 兄弟会', '/frə\'tə:niti | frə\'tɜːnɪtɪ | frə\'tɝnəti/', 'fraternity', 6);
INSERT INTO `words` VALUES (12150, '{\"COLLOINEXA\":[\"electoral fraud\"]}', 'n. 欺骗, 欺诈行为, 诡计, 骗子, 假货', '/frɔ:d | frɔːd | frɔd/', 'fraud', 6);
INSERT INTO `words` VALUES (12151, 'a fraudulent insurance claim', 'adj. 欺诈的, 欺骗性的, 骗得的', '/\'frɔ:djulənt | \'frɔːdjʊl(ə)nt | \'frɔdʒələnt/', 'fraudulent', 6);
INSERT INTO `words` VALUES (12152, 'Their marriage has been fraught with difficulties.', 'adj. 充满的', '/frɔːt | frɔt/', 'fraught', 6);
INSERT INTO `words` VALUES (12153, 'Three civilians were injured during the fray.', 'n. 冲突, 打架, 争论, (织物等)磨损处', '/frei | freɪ | fre/', 'fray', 6);
INSERT INTO `words` VALUES (12154, 'These glasses make me look like a freak.', 'n. 怪诞的思想、行动或事件, 畸形人, 畸形的动物或植物, 反复无常', '/fri:k | friːk/', 'freak', 6);
INSERT INTO `words` VALUES (12155, 'He had short ginger-coloured hair and freckles.', 'n. 雀斑, 斑点', '/\'frekl | \'frek(ə)l | \'frɛkl/', 'freckle', 6);
INSERT INTO `words` VALUES (12156, 'the Central Freeway', 'n. 高速公路', '/\'fri:wei | \'friːweɪ | \'friwe/', 'freeway', 6);
INSERT INTO `words` VALUES (12157, 'She rushes from job to job at a frenetic pace.', 'adj. 发狂的, 狂热的', '/fri\'netik | frə\'netɪk | frə\'nɛtɪk/', 'frenetic', 6);
INSERT INTO `words` VALUES (12158, 'Doreen had worked herself into a frenzy .', 'n. 狂乱， 狂暴； 暂时性疯狂', '/\'frenzi | \'frɛnzi/', 'frenzy', 6);
INSERT INTO `words` VALUES (12159, 'Side effects from prescribed drugs are being reported with increasing frequency (= more and more often ) .', 'n. 频率', '/\'friːkwənsi | \'frikwənsi/', 'frequency', 6);
INSERT INTO `words` VALUES (12160, NULL, 'n. 在灰泥的墙壁上作的水彩画, 壁画', '/\'freskəu | \'freskəʊ | \'frɛsko/', 'fresco', 6);
INSERT INTO `words` VALUES (12161, 'Don’t fret – everything will be all right.', 'v. (使)烦恼, (使)焦急, (使)腐蚀, (使)磨损', '/fret | frɛt/', 'fret', 6);
INSERT INTO `words` VALUES (12162, 'Don\'t assume your baby automatically needs feeding if she\'s fretful.', 'adj. 烦燥的, 起波纹的, 焦躁的', '/\'fretful | \'fretfʊl; -f(ə)l | \'frɛtfəl/', 'fretful', 6);
INSERT INTO `words` VALUES (12163, NULL, 'n. [建]浮雕细工', '/\'fretwə:k | \'fretwɜːk | \'frɛtwɝk/', 'fretwork', 6);
INSERT INTO `words` VALUES (12164, 'Should be chosen in wood materials, fabric, plastic, glass furniture and discard friable hard metal furniture.', 'adj. 易碎的, 脆的', '/\'fraiəbl | \'fraɪəb(ə)l | \'fraɪəbl/', 'friable', 6);
INSERT INTO `words` VALUES (12165, 'Putting oil on both surfaces reduces friction.', 'n. 摩擦； 矛盾， 冲突', '/\'frɪkʃn | \'frɪkʃən/', 'friction', 6);
INSERT INTO `words` VALUES (12166, NULL, 'n. 赞助者， 支持者', '/frend | frɛnd/', 'friend', 6);
INSERT INTO `words` VALUES (12167, NULL, 'n. 三帆快速战舰, 护卫舰', '/\'friɡit | \'frɪgət | \'frɪɡət/', 'frigate', 6);
INSERT INTO `words` VALUES (12168, 'The guard looked at us with a frigid stare.', 'adj. 寒冷的； 冷漠的， 冷淡的', '/\'frɪdʒɪd/', 'frigid', 6);
INSERT INTO `words` VALUES (12169, 'Doctor Simpson believes that Suzie \'s frigidity is due to some hang - up about men.', 'n. 寒冷, 冷淡, [医]性感缺失', '/fri\'dʒiditi/', 'frigidity', 6);
INSERT INTO `words` VALUES (12170, 'a tall girl with straight brown hair and a fringe', 'n. 边缘, 须边, 刘海', '/frindʒ | frɪn(d)ʒ | frɪndʒ/', 'fringe', 6);
INSERT INTO `words` VALUES (12171, NULL, 'n. 便宜而俗艳的服装, 无用的东西', '/\'fripəri | \'frɪp(ə)rɪ/', 'frippery', 6);
INSERT INTO `words` VALUES (12172, 'The lambs were frisking around the pen.', 'n. 快乐, 快乐的时刻, 搜身', '/frisk | frɪsk/', 'frisk', 6);
INSERT INTO `words` VALUES (12173, 'a frisky horse', 'adj. 活泼的, 欢闹的', '/\'friski | \'frɪskɪ/', 'frisky', 6);
INSERT INTO `words` VALUES (12174, 'I don’t think such frivolity helps the organization’s public image.', 'n. 轻薄, 轻率, 无聊的举动', '/fri\'vəliti | frɪ\'vɒlɪtɪ/', 'frivolity', 6);
INSERT INTO `words` VALUES (12175, 'I just decided I was a bit too frivolous to be a doctor.', 'adj. 轻佻的, 琐碎的, 妄动的', '/\'frivələs | \'frɪv(ə)ləs | \'frɪvələs/', 'frivolous', 6);
INSERT INTO `words` VALUES (12176, 'Manic brushing will only cause frizz.', 'n. 卷发, 卷毛, 吱吱响声', '/friz | frɪz/', 'frizz', 6);
INSERT INTO `words` VALUES (12177, 'Everyone joined in the Saturday night frolics.', 'n. 嬉闹', '/\'frɔlik | \'frɒlɪk | \'frɑlɪk/', 'frolic', 6);
INSERT INTO `words` VALUES (12178, 'In the not too distant future.When the pup had grown lanky and frolicsome—the wolf would return to the mountainside.', 'adj. 爱闹着玩的, 嬉戏的', '/\'frɔliksəm | \'frɒlɪks(ə)m | \'frɑlɪksəm/', 'frolicsome', 6);
INSERT INTO `words` VALUES (12179, '...palm fronds.', 'n. 叶, 植物体', '/frɔnd | frɒnd | frɑnd/', 'frond', 6);
INSERT INTO `words` VALUES (12180, 'a mug of frothy coffee', 'adj. 起泡的； 空洞的', '/\'frɔːθi | \'frɔθi/', 'frothy', 6);
INSERT INTO `words` VALUES (12181, NULL, 'adj. 不整洁的, 憋闷的, 有臭味的', '/\'frauzi | \'fraʊzɪ/', 'frowzy', 6);
INSERT INTO `words` VALUES (12182, NULL, 'v. 富有成果', '/\'frʌktifai | \'frʌktɪfaɪ/', 'fructify', 6);
INSERT INTO `words` VALUES (12183, 'As children we were taught to be frugal and hard-working.', 'adj. 节约的， 节俭的', '/\'fruːgl | \'fruɡl/', 'frugal', 6);
INSERT INTO `words` VALUES (12184, 'If your goal is frugality, then consider what things are not necessary, the long-term impact of the choice you make and whether you can afford it.', 'n. 节俭, 俭省', '/fru:\'ɡæləti | fruː\'gælɪtɪ | frʊ\'gæləti/', 'frugality', 6);
INSERT INTO `words` VALUES (12185, 'After months of hard work, our plans finally came to fruition .', 'n. 实现， 完成', '/fru\'ɪʃn | fru\'ɪʃən/', 'fruition', 6);
INSERT INTO `words` VALUES (12186, 'Others point out that politicians have long been interested mainly in their own well-being, fruitlessly debating a new constitution for the past seven years while paying little attention to governing.', 'adv. 徒劳地， 无益地', '/\'fru:tlisli | \'fruːtləsli/', 'fruitlessly', 6);
INSERT INTO `words` VALUES (12187, 'She got a reputation as a frump.', 'n. 守旧者, 邋遢的女人', '/frʌmp/', 'frump', 6);
INSERT INTO `words` VALUES (12188, NULL, 'adj. 邋遢的； 老式的， 过时的', '/\'frʌmpɪ | \'frʌmpi/', 'frumpy', 6);
INSERT INTO `words` VALUES (12189, 'Their attempts to speak to him were frustrated by the guards.', 'v. 挫败, 阻挠, 使感到灰心, 阻止', '/frʌs\'treit | frʌ\'streɪt; \'frʌs- | \'frʌstret/', 'frustrate', 6);
INSERT INTO `words` VALUES (12190, NULL, 'adj. 肥胖的, 矮胖的', '/\'fʌbzɪ | \'fʌbzi/', 'fubsy', 6);
INSERT INTO `words` VALUES (12191, NULL, 'adj. 短暂的, 易逃逸的, 难捕捉的, 无常的', '/fju:\'ɡeiʃəs | fjʊ\'geɪʃəs/', 'fugacious', 6);
INSERT INTO `words` VALUES (12192, 'Clay said a better law was needed for the return of fugitive slaves to their owners.', 'adj. 逃亡的, 无常的, 易变的', '/\'fju:dʒitiv | \'fjuːdʒɪtɪv | \'fjudʒətɪv/', 'fugitive', 6);
INSERT INTO `words` VALUES (12193, 'The decision is the strategic fulcrum of the Budget.', 'n. 杠杆的支点, 支点, 叶附属物', '/\'fu:lkrəm | \'fʊlkrəm; \'fʌl- | \'fʊlkrəm/', 'fulcrum', 6);
INSERT INTO `words` VALUES (12194, 'The drop in shares could develop into a full-blown crisis.', 'adj. 成熟的； 盛开的； 全面的， 完善的', '/ˌful\'bloun | ful\'bləun/', 'full-blown', 6);
INSERT INTO `words` VALUES (12195, '...a soft but full-bodied wine with concentrated blackcurrant flavour.', 'adj. 魁梧的； 浓烈的； 重要的', '/\'ful\'bɔdid | ˌful\'bɑːdid/', 'full-bodied', 6);
INSERT INTO `words` VALUES (12196, 'The newspapers fulminate against the crime.', 'v. 使爆发, 以严词谴责', '/\'fʌlmineit | \'fʊlmɪneɪt; \'fʌl- | \'fʊlmɪnet/', 'fulminate', 6);
INSERT INTO `words` VALUES (12197, NULL, 'n. 闪电, 爆发, 爆鸣', '/\'fʌlmə\'neiʃən/', 'fulmination', 6);
INSERT INTO `words` VALUES (12198, 'Newspapers have been fulsome in their praise of the former president.', 'adj. 过度的, 令人生厌的, 过分的', '/\'fulsʌm | \'fʊls(ə)m | \'fʊlsəm/', 'fulsome', 6);
INSERT INTO `words` VALUES (12199, 'She reached round to fumble the light on.', 'v. 摸索', '/\'fʌmbl | \'fʌmb(ə)l/', 'fumble', 6);
INSERT INTO `words` VALUES (12200, '...car exhaust fumes.', 'n. (浓烈或难闻的)烟, 气体, 一阵愤怒(或不安)', '/fju:m | fjuːm | fjum/', 'fume', 6);
INSERT INTO `words` VALUES (12201, '...fruit which has been treated with insecticide and fumigated.', 'v. 熏制, 使发香', '/\'fju:miɡeit | \'fjuːmɪgeɪt | \'fjumɪɡet/', 'fumigate', 6);
INSERT INTO `words` VALUES (12202, 'Her legs have now ceased to function .', 'v. 运行; n. 功能； 职责', '/\'fʌŋkʃn | \'fʌŋkʃən/', 'function', 6);
INSERT INTO `words` VALUES (12203, 'Liberal Party functionaries', 'n. 职员, 官员, 负责人员', '/\'fʌŋkʃənəri | \'fʌn(k)ʃ(ə)n(ə)rɪ | \'fʌŋkʃənɛri/', 'functionary', 6);
INSERT INTO `words` VALUES (12204, 'We have to tackle the fundamental cause of the problem.', 'adj. 根本的， 基本的； 十分重要的', '/ˌfʌndə\'mentl | ,fʌndə\'mɛntl/', 'fundamental', 6);
INSERT INTO `words` VALUES (12205, 'Despite these new relationships, the fungible nature of oil will limit the extent to which this economic shift eastward translates into a geopolitical one.', 'adj. 可互换的, 代替的', '/\'fʌndʒibl | \'fʌndʒɪbl | \'fʌndʒəbl/', 'fungible', 6);
INSERT INTO `words` VALUES (12206, 'She’s in a funk about giving her talk on Sunday.', 'n. 怯懦, 恐惧, 臭味, 恐怖', '/fʌŋk/', 'funk', 6);
INSERT INTO `words` VALUES (12207, 'Add a touch of style with these functional yet funky wall lights.', 'adj. 有霉臭味的， 有恶臭的', '/fʌŋki/', 'funky', 6);
INSERT INTO `words` VALUES (12208, NULL, 'v. 擦亮, 恢复, 磨光', '/\'fə:biʃ | \'fɜːbɪʃ | \'fɝbɪʃ/', 'furbish', 6);
INSERT INTO `words` VALUES (12209, 'a young soldier home on furlough', 'n. 休假, 暂时解雇, 放假', '/\'fə:lau | \'fɜːləʊ | \'fɝlo/', 'furlough', 6);
INSERT INTO `words` VALUES (12210, NULL, 'n. 喧闹， 轰动； 盛怒', '/\'fjurɔːr | \'fjʊrrɔr/', 'furor', 6);
INSERT INTO `words` VALUES (12211, 'A deep furrow appeared between his brows.', 'n. 犁沟, 皱纹', '/\'fərəu | \'fʌrəʊ | \'fɝo/', 'furrow', 6);
INSERT INTO `words` VALUES (12212, 'There was something furtive about his actions.', 'adj. 偷偷摸摸的, 鬼鬼祟祟的, 秘密的, 私下的, 隐密的', '/\'fə:tiv | \'fɜːtɪv/', 'furtive', 6);
INSERT INTO `words` VALUES (12213, 'I was shaking with fury .', 'n. 狂怒， 狂暴； 激烈， 猛烈； 狂怒的人； 复仇女神', '/\'fɜːri | \'fjʊri/', 'fury', 6);
INSERT INTO `words` VALUES (12214, 'Their music fuses elements as diverse as Cajun, bebop and Cuban waltzes.', 'v. 熔化； 融合', '/fjuːz | fjuz/', 'fuse', 6);
INSERT INTO `words` VALUES (12215, NULL, 'adj. 熔化的', '/fjuːzd | fjʊzd/', 'fused', 6);
INSERT INTO `words` VALUES (12216, 'Both were killed in a fusillade of bullets fired at close range.', 'n. 枪炮的齐射, 猛射, 连续射击', '/,fju:zi\'leid | ,fjuːzɪ\'leɪd; -\'lɑːd/', 'fusillade', 6);
INSERT INTO `words` VALUES (12217, 'Her work is a fusion of several different styles.', 'n. 融合； 核聚变', '/\'fjuːʒn | \'fjʊʒən/', 'fusion', 6);
INSERT INTO `words` VALUES (12218, 'James said he’d better be getting back or there’d be a fuss .', 'n. 忙乱, 大惊小怪, 大惊小怪的人', '/fʌs/', 'fuss', 6);
INSERT INTO `words` VALUES (12219, 'A lot of small children are fussy eaters (= they dislike many types of food ) .', 'adj. 为琐事而担忧的, 过分装饰的, 繁琐的, 急躁, 爱挑剔的, 难取悦的', '/\'fʌsi | \'fʌsɪ/', 'fussy', 6);
INSERT INTO `words` VALUES (12220, NULL, 'n. 粗斜条棉布, 夸大的话', '/\'fʌstiən | \'fʌstɪən/', 'fustian', 6);
INSERT INTO `words` VALUES (12221, 'fusty old academics', 'adj. 霉臭的； 陈腐的， 过时的', '/\'fʌsti/', 'fusty', 6);
INSERT INTO `words` VALUES (12222, 'My efforts to go back to sleep proved futile.', 'adj. 无效的， 无用的； 没出息的； 琐细的', '/\'fjuːtl | \'fjʊtaɪl/', 'futile', 6);
INSERT INTO `words` VALUES (12223, 'Brown\'s article tells of the tragedy and futility of war.', 'n. 无益, 无用, 轻浮的言行', '/fju:\'tiliti | fjʊ\'tɪlɪtɪ; fjuː\'tɪlɪtɪ | fjʊ\'tɪləti/', 'futility', 6);
INSERT INTO `words` VALUES (12224, 'Some of the photos were so fuzzy it was hard to tell who was who.', 'adj. 有绒毛的, 模糊的, 失真的', '/\'fʌzi | \'fʌzɪ/', 'fuzzy', 6);
INSERT INTO `words` VALUES (12225, 'You two were gabbing so much you didn’t even see me!', 'v. 空谈， 瞎扯； 闲逛， 游荡; n. 饶舌，爱说话', '/gæb/', 'gab', 6);
INSERT INTO `words` VALUES (12226, 'Just calm down, stop gabbling, and tell me what has happened.', 'v. 急促而不清楚地说话, 七嘴八嘴地说, 喋喋不休地说', '/\'ɡæbl | \'gæb(ə)l | \'gæbl/', 'gabble', 6);
INSERT INTO `words` VALUES (12227, 'Ted observed that her friends were a scream of a bunch - stuck - up gabby four - flushers.', 'adj. 饶舌的， 多嘴的', '/\'gæbi | \'ɡæbi/', 'gabby', 6);
INSERT INTO `words` VALUES (12228, NULL, 'n. 牛蝇, 形似苍蝇, 讨厌的人', '/\'ɡædflai | \'gædflaɪ/', 'gadfly', 6);
INSERT INTO `words` VALUES (12229, '...sales of kitchen gadgets including toasters, kettles, and percolators.', 'n. 小器具, 小配件, 小玩意, 诡计', '/\'ɡædʒit | \'gædʒɪt/', 'gadget', 6);
INSERT INTO `words` VALUES (12230, NULL, 'n. 大鱼钩， 鱼叉； 【海】斜桁', '/gæf/', 'gaff', 6);
INSERT INTO `words` VALUES (12231, 'The consul’s comments were a major diplomatic gaffe.', 'n. 过失, 出丑, 失态', '/ɡæf | gæf/', 'gaffe', 6);
INSERT INTO `words` VALUES (12232, 'a gaggle of teenage girls', 'n. 鹅群, 一群', '/\'ɡæɡl | \'gæg(ə)l | \'gægl/', 'gaggle', 6);
INSERT INTO `words` VALUES (12233, 'Lars enjoyed the warmth and gaiety of these occasions.', 'n. 欢乐的精神, 欢乐的气氛作乐, 乐事', '/\'ɡeiəti | \'geɪətɪ/', 'gaiety', 6);
INSERT INTO `words` VALUES (12234, 'The party made considerable gains at local elections.', 'n. 利润， 收获', '/geɪn | ɡen/', 'gain', 6);
INSERT INTO `words` VALUES (12235, 'No one dared to gainsay him.', 'v. 否认', '/ɡein\'sei | geɪn\'seɪ | ,ɡen\'se/', 'gainsay', 6);
INSERT INTO `words` VALUES (12236, 'These speedy electrons interact with photons in the galactic halo, boosting some of them up to the gamma-ray energies observed in the bubbles.', 'adj. 极大的, 银河的, 乳汁的', '/ɡə\'læktik | gə\'læktɪk/', 'galactic', 6);
INSERT INTO `words` VALUES (12237, 'Astronomers have discovered a distant galaxy.', 'n. 星系, 银河, 一群显赫的人, 一系列光彩夺目的东西', '/\'gæləksɪ | \'ɡæləksi/', 'galaxy', 6);
INSERT INTO `words` VALUES (12238, 'a severe gale', 'n. 大风, (突发的)一阵', '/ɡeil | geɪl | ɡel/', 'gale', 6);
INSERT INTO `words` VALUES (12239, 'He\'s as bitter as gall at your desertion and its consequences: don\'t expect thanks for this noble devotion.', 'n. 胆汁, 恶毒, 怨恨, 五倍子, 苦味, 磨伤(尤指马的), 肿痛, 恼怒', '/ɡɔ:l | gɔːl | ɡɔl/', 'gall', 6);
INSERT INTO `words` VALUES (12240, 'a gallant young man', 'adj. 英勇的, 豪侠的, 堂皇的, 壮丽的, 华丽的, 对妇女献殷勤的', '/\'ɡælənt | \'gæl(ə)nt; gə\'lænt/', 'gallant', 6);
INSERT INTO `words` VALUES (12241, 'a medal for gallantry', 'n. 勇敢', '/\'ɡæləntri | \'gæləntrɪ/', 'gallantry', 6);
INSERT INTO `words` VALUES (12242, NULL, 'n. 大型帆船', '/\'ɡæliən | \'gælɪən/', 'galleon', 6);
INSERT INTO `words` VALUES (12243, 'The fire extinguishers are stored in the galley.', 'n. 狭长船, 大型划船, 船上厨房, (印刷用的)长方活字盘, 军舰', '/\'ɡæli | \'gælɪ/', 'galley', 6);
INSERT INTO `words` VALUES (12244, 'I was forced to attempt a gallop.', 'n. 疾驰, 飞奔', '/\'ɡæləp | \'gæləp/', 'gallop', 6);
INSERT INTO `words` VALUES (12245, 'There\'s a thief hanging on the gallows out there, and I\'ll cut his hand off; which hand was it?', 'n. 绞架, 绞刑', '/\'ɡæləuz | \'gæləʊz | \'gæloz/', 'gallows', 6);
INSERT INTO `words` VALUES (12246, 'Does the lion return gally you?', 'vt. 吓唬', '/\'ɡælɪ | \'gæli/', 'gally', 6);
INSERT INTO `words` VALUES (12247, 'You can prepare as much as you like and amass material galore, but unless you come in fresh, like an athlete onto the track, you aren’t going to do the job required.', 'adv. 丰富地', '/gə\'lɔ: | gə\'lɔː | ɡə\'lɔr/', 'galore', 6);
INSERT INTO `words` VALUES (12248, 'The report galvanized world opinion.', 'v. 通电流于, 电镀', '/\'ɡælvənaiz | \'ɡælvənaɪz/', 'galvanize', 6);
INSERT INTO `words` VALUES (12249, '...the sight of newborn lambs gambolling in the fields.', 'n. 欢跳, 雀跃, 嬉戏', '/\'ɡæmbəl | \'gæmb(ə)l | \'ɡæmbl/', 'gambol', 6);
INSERT INTO `words` VALUES (12250, 'As the story unfolded throughout the past week, I experienced the gamut of emotions: shock, anger, sadness, disgust, confusion.', 'n. [音乐]全音阶, 长音阶, 全音域', '/\'ɡæmət | \'gæmət/', 'gamut', 6);
