INSERT INTO `words` VALUES (12252, 'an awkward gangling teenager', 'adj. (身体)瘦长的', '/\'ɡæŋɡliŋ | \'gæŋglɪŋ | \'ɡæŋɡlɪŋ/', 'gangling', 6);
