INSERT INTO `words` VALUES (12254, NULL, 'n. 过道, (剧场, 火车等)座间通道, (美国作aisle)舷侧门, 舷梯, 通路, 跳板', '/\'ɡæŋwei | \'gæŋweɪ | \'ɡæŋwe/', 'gangway', 6);
