INSERT INTO `words` VALUES (12256, 'You garble my words from their real meaning.', 'v. 断章取义, 混淆', '/\'ɡɑ:bl | \'gɑːb(ə)l/', 'garble', 6);
INSERT INTO `words` VALUES (12257, 'The papers had some garbled version of the story.', 'adj. 引起误解的； 窜改的', '/\'gɑːrbld | \'ɡɑrbld/', 'garbled', 6);
INSERT INTO `words` VALUES (12258, NULL, 'n. 〈植〉栀子栀子花', '/ɡɑ:\'di:njə | gɑː\'diːnɪə | ɡɑr\'dinɪə/', 'gardenia', 6);
INSERT INTO `words` VALUES (12259, 'a meal of gargantuan proportions', 'adj. 巨大的, 庞大的', '/ɡɑ:\'ɡæntjuən | gɑː\'gæntjʊən | ɡɑr\'ɡæntʃuən/', 'gargantuan', 6);
INSERT INTO `words` VALUES (12260, NULL, 'n. [建]怪兽状滴水嘴,(突出的)怪兽饰', '/\'ɡɑ:ɡɔil | \'gɑːgɒɪl | \'ɡɑrɡɔɪl/', 'gargoyle', 6);
INSERT INTO `words` VALUES (12261, 'They climbed the garish, purple-carpeted stairs.', 'adj. 炫耀的, 过分装饰的, (色彩、装饰、打扮等)俗气的', '/\'ɡεəriʃ | \'geərɪʃ | \'ɡɛrɪʃ/', 'garish', 6);
INSERT INTO `words` VALUES (12262, 'I saw that my garland of overnight was still hanging loose from your hair.', 'n. 花环', '/\'ɡɑ:lənd | \'gɑːlənd | \'gɑrlənd/', 'garland', 6);
INSERT INTO `words` VALUES (12263, 'She pulled the garment on and zipped it up.', 'n. 衣服, 外衣, 外表', '/\'ɡɑ:mənt | \'gɑːm(ə)nt | \'gɑrmənt/', 'garment', 6);
INSERT INTO `words` VALUES (12264, 'The party garnered 70 percent of the vote.', 'v. 储存', '/\'ɡɑ:nə | \'gɑːnə | \'ɡɑrnɚ/', 'garner', 6);
INSERT INTO `words` VALUES (12265, 'She had finished the vegetables and was garnishing the roast.', 'v. 装饰', '/\'ɡɑ:niʃ | \'gɑːnɪʃ | \'gɑrnɪʃ/', 'garnish', 6);
INSERT INTO `words` VALUES (12266, 'She made no stay at the stairs\'-head, but mounted farther, to the garret where Heathcliff was confined, and called him.', 'n. 顶楼', '/\'ɡærət | \'gærət; -ɪt/', 'garret', 6);
INSERT INTO `words` VALUES (12267, 'His love of conversation, his affection, his indifference to riches, even his garrulity, are interesting traits of character.', 'n. 饶舌, 多嘴', '/ɡə\'ru:liti/', 'garrulity', 6);
INSERT INTO `words` VALUES (12268, 'Ian isn’t normally this garrulous!', 'adj. 饶舌的, 啁啾的, 多嘴的', '/\'ɡærjuləs | \'gær(j)ʊləs | \'ɡærələs/', 'garrulous', 6);
INSERT INTO `words` VALUES (12269, 'Honesty and frankness do more for the public\'s confidence … than extravagant boasting or supercilious gasconade.', 'n. 吹牛', '/,ɡæskə\'neid | ,gæskə\'neɪd | ˌgæskən\'ed/', 'gasconade', 6);
INSERT INTO `words` VALUES (12270, 'Freon exists both in liquid and gaseous states.', 'adj. 气体的， 气态的', '/\'gæsiəs | \'ɡæsɪəs/', 'gaseous', 6);
INSERT INTO `words` VALUES (12271, 'Blood poured from a deep gash in her forehead.', 'n. 砍得很深的伤口, 很深的裂缝', '/ɡæʃ | gæʃ/', 'gash', 6);
INSERT INTO `words` VALUES (12272, 'gastric ulcers', 'adj. 胃的', '/\'ɡæstrik | \'gæstrɪk/', 'gastric', 6);
INSERT INTO `words` VALUES (12273, 'Don’t use if you have an ulcer or gastritis.', 'n. [医]胃炎', '/ɡæs\'traitis | gæ\'straɪtɪs | ɡæ\'straɪtɪs/', 'gastritis', 6);
INSERT INTO `words` VALUES (12274, 'Burgundy has always been considered a major centre of gastronomy.', 'n. 美食法, 烹饪法, 享乐主义', '/ɡæs\'trɔnəmi | gæ\'strɒnəmɪ | ɡæ\'strɑnəmi/', 'gastronomy', 6);
INSERT INTO `words` VALUES (12275, 'It would be gauche to mention the price.', 'adj. 笨拙的, 粗鲁的, 偏转的, 无礼的', '/ɡəuʃ | gəʊʃ | ɡoʃ/', 'gauche', 6);
INSERT INTO `words` VALUES (12276, 'First love is a little gaucherie with a lot of curious.', 'n. 笨拙', '/\'ɡəuʃəri:/', 'gaucherie', 6);
INSERT INTO `words` VALUES (12277, 'gaudy jewelry', 'adj. 华而不实的', '/\'ɡɔ:di | \'gɔːdɪ | \'gɔdi/', 'gaudy', 6);
INSERT INTO `words` VALUES (12278, 'The index is the government\'s chief gauge of future economic activity.', 'n. 标准尺, 规格, 量规, 量表', '/ɡeidʒ | geɪdʒ | gedʒ/', 'gauge', 6);
INSERT INTO `words` VALUES (12279, 'the old man’s gaunt face', 'adj. 憔悴的', '/ɡɔ:nt | gɔːnt/', 'gaunt', 6);
INSERT INTO `words` VALUES (12280, 'His hands were wrapped in gauze bandages.', 'n. 薄纱, [医]纱布, 薄雾', '/ɡɔ:z | gɔːz | gɔz/', 'gauze', 6);
INSERT INTO `words` VALUES (12281, 'A judge bangs his gavel.', 'n. 槌', '/\'ɡævəl | \'gæv(ə)l | \'gævl/', 'gavel', 6);
