INSERT INTO `words` VALUES (12286, NULL, 'adj. 有芽的', '/\'dʒemeɪt/', 'gemmate', 6);
INSERT INTO `words` VALUES (12287, 'human genes', 'n. 基因', '/dʒiːn | dʒin/', 'gene', 6);
INSERT INTO `words` VALUES (12288, 'Critics love to generalize, to formulate trends into which all new work must be fitted, however contradictory.', 'v. 概括， 归纳', '/\'dʒenrəlaɪz | \'dʒɛnrəlaɪz/', 'generalize', 6);
INSERT INTO `words` VALUES (12289, 'a useful technique for generating new ideas', 'v. 产生, 发生', '/\'dʒenəreɪt | \'dʒɛnəret/', 'generate', 6);
INSERT INTO `words` VALUES (12290, 'Like most of my generation, I had never known a war.', 'n. 一代人； 代； 产生， 发生', '/ˌdʒenə\'reɪʃn | \'dʒɛnə\'reʃən/', 'generation', 6);
INSERT INTO `words` VALUES (12291, 'an emergency generator', 'n. 发电机, 发生器', '/\'dʒenəreitə | \'dʒenəreɪtə | \'dʒɛnəretɚ/', 'generator', 6);
INSERT INTO `words` VALUES (12292, 'Parmesan is a generic term used to describe a family of hard Italian cheeses.', 'adj. [生物]属的, 类的, 一般的, 普通的, 非特殊的', '/dʒi\'nerik | dʒɪ\'nerɪk | dʒə\'nɛrɪk/', 'generic', 6);
INSERT INTO `words` VALUES (12293, 'an act of great generosity', 'n. 慷慨, 宽大', '/,dʒenə\'rɔsəti | dʒenə\'rɒsətɪ | ,dʒɛnə\'rɑsəti/', 'generosity', 6);
INSERT INTO `words` VALUES (12294, 'a generous glass of wine', 'adj. 慷慨的； 大量的', '/\'dʒenərəs | \'dʒɛnərəs/', 'generous', 6);
