INSERT INTO `words` VALUES (12297, 'Genetics is also bringing about dramatic changes in our understanding of cancer.', 'n. 遗传学', '/dʒi\'netiks | dʒɪ\'netɪks | dʒə\'nɛtɪks/', 'genetics', 6);
