INSERT INTO `words` VALUES (12299, 'These songs are full of cordiality and geniality towards children and juveniles evidencing the interests and imaginations of naïve children.', 'n. 亲切', '/,dʒi:ni\'æləti/', 'geniality', 6);
INSERT INTO `words` VALUES (12300, 'the human genome', 'n. [生]基因组,染色体组', '/\'dʒi:nəum | \'dʒiːnəʊm | \'dʒinom/', 'genome', 6);
INSERT INTO `words` VALUES (12301, 'a literary genre', 'n. 类型, 流派', '/ˈʒɒnrə | \'ʒɑnrə/', 'genre', 6);
