INSERT INTO `words` VALUES (12303, 'He genuflected in front of the altar.', 'v. 屈服', '/\'dʒenju:flekt | \'dʒenjʊflekt | \'dʒɛnjuflɛkt/', 'genuflect', 6);
INSERT INTO `words` VALUES (12304, '‘Did he really?’ Her surprise seemed genuine.', 'adj. 真的； 真诚的', '/\'dʒenjuɪn | \'dʒɛnjʊɪn/', 'genuine', 6);
INSERT INTO `words` VALUES (12305, '...a genus of plants called Sinningia.', 'n. 属， 类', '/\'dʒiːnəs | \'dʒinəs/', 'genus', 6);
INSERT INTO `words` VALUES (12306, 'Simulations of magnetic fields generated by the antarctic circumpolar current at satellite altitude: can geomagnetic measurements be used to monitor the flow?', 'adj. 地磁的', '/ˌdʒiːoumæg\'netɪk | ,dʒiomæg\'nɛtɪk/', 'geomagnetic', 6);
