INSERT INTO `words` VALUES (12309, 'Then, the whole spectacle gets even worse when you have to knead germicide into the contents.', 'n. 杀菌剂', '/\'dʒə:misaid | \'dʒɜːrmɪsaɪd/', 'germicide', 6);
