INSERT INTO `words` VALUES (12313, 'It was in ancient times that the thought of pedagogical pragmatics began to gestate and form.', 'v. 怀孕， 孕育； 构思', '/\'dʒesteɪt | \'dʒɛstet/', 'gestate', 6);
