INSERT INTO `words` VALUES (12315, 'Jane gesticulated wildly and shouted ‘Stop! Stop!’', 'v. 做姿势表达, 用手势谈话', '/dʒes\'tikjuleit | dʒe\'stɪkjʊleɪt | dʒɛ\'stɪkjulet/', 'gesticulate', 6);
INSERT INTO `words` VALUES (12316, 'Luke made an obscene gesture with his finger.', 'n. 姿势， 手势； 姿态， 表示', '/\'dʒestʃər | \'dʒɛstʃɚ/', 'gesture', 6);
INSERT INTO `words` VALUES (12317, 'Both oil and coal are there but not in getatable locations.', 'adj. 可接近的', '/\'ɡetætəbl | gɛt\'ætəbl/', 'getatable', 6);
INSERT INTO `words` VALUES (12318, NULL, 'n. 间歇泉, 烧水锅炉', '/\'ɡeizə | \'giːzə; \'gaɪ- | \'ɡaɪzɚ/', 'geyser', 6);
INSERT INTO `words` VALUES (12319, 'After the full moon and between the last quarter moon, the moon will be in its waning gibbous phase.', 'adj. 突起的', '/\'ɡibəs | \'gɪbəs/', 'gibbous', 6);
INSERT INTO `words` VALUES (12320, '“Please don’t gibe me,” Lydia said.', 'v. 嘲笑', '/dʒaib/', 'gibe', 6);
