INSERT INTO `words` VALUES (12326, 'The silver yo-yo that Jerry kept on his office desk was a gimcrack he had won as a carnival prize many years ago.', 'adj. 华而不实的', '/\'dʒimkræk | \'dʒɪmkræk | \'dʒɪm\'kræk/', 'gimcrack', 6);
