INSERT INTO `words` VALUES (12329, 'She was touching the dressing gingerly with both hands.', 'adj&adv. 小心的； 谨慎的', '/\'dʒɪndʒərli | \'dʒɪndʒɚli/', 'gingerly', 6);
INSERT INTO `words` VALUES (12330, 'Listen, when you start to feel weak, just tell yourself, ‘I’m as strong as a girder’ .', 'n. 梁, 钢桁的支架', '/\'ɡə:də | \'gɜːdə | \'ɡədɚ/', 'girder', 6);
