INSERT INTO `words` VALUES (12339, '...the glamour of show biz.', 'n. [亦作glamor] 魔力, 魅力', '/\'ɡlæmə/', 'glamour', 6);
INSERT INTO `words` VALUES (12340, 'Wyatt glanced around the restaurant.', 'v. 瞥见; n. 一瞥', '/glæns | ɡlæns/', 'glance', 6);
