INSERT INTO `words` VALUES (12344, 'The book’s most glaring omission is the lack of an index.', 'adj. 耀眼的', '/ɡlεəriŋ | \'gleərɪŋ | \'ɡlɛrɪŋ/', 'glaring', 6);
INSERT INTO `words` VALUES (12345, '...hand-painted French tiles with decorative glazes.', 'v. 上釉于；使光滑; n. 釉', '/gleɪz | ɡlez/', 'glaze', 6);
INSERT INTO `words` VALUES (12346, 'Rose looked at me with a furious gleam in her eyes.', 'n. 微弱的闪光, 一丝光线, 瞬息的一现', '/ɡli:m | gliːm | ɡlim/', 'gleam', 6);
INSERT INTO `words` VALUES (12347, 'At present we\'re gleaning information from all sources.', 'v. 拾落穗, 收集', '/ɡli:n | gliːn | ɡlin/', 'glean', 6);
INSERT INTO `words` VALUES (12348, 'And sometimes like a gleaner thou dost keep', 'n. 拾穗的人', '/\'ɡli:nə/', 'gleaner', 6);
INSERT INTO `words` VALUES (12349, NULL, 'n. 所拾得的落穗搜集到的情报或新闻', '/\'gliːnɪŋz | \'ɡlinɪŋz/', 'gleanings', 6);
INSERT INTO `words` VALUES (12350, 'Manufacturers are rubbing their hands with glee as they prepare to cash in.', 'n. 欢乐, 高兴', '/\'ɡli: | gliː | ɡli/', 'glee', 6);
INSERT INTO `words` VALUES (12351, NULL, 'adj. 愉快的', '/\'ɡli:ful | \'gliːfʊl; -f(ə)l/', 'gleeful', 6);
INSERT INTO `words` VALUES (12352, '...the glib talk of \"past misery.\"', 'adj. 口齿伶俐的, 油腔滑调的', '/ɡlib | glɪb/', 'glib', 6);
INSERT INTO `words` VALUES (12353, 'Waiters glide between tightly packed tables bearing trays of pasta.', 'v. 滑行, 悄悄地走, (时间)消逝, 滑翔', '/glaɪd | ɡlaɪd/', 'glide', 6);
INSERT INTO `words` VALUES (12354, 'And go for a ride on a glider airplane, because who says planes need motors?', 'n. 滑行(或物), 滑翔机', '/\'ɡlaidə | \'glaɪdə | \'ɡlaɪdɚ/', 'glider', 6);
INSERT INTO `words` VALUES (12355, 'The moon glimmered faintly through the mists.', 'v. 闪烁', '/\'ɡlimə | \'glɪmə | \'ɡlɪmɚ/', 'glimmer', 6);
INSERT INTO `words` VALUES (12356, 'Some of the fans had waited 24 hours outside the hotel to catch a glimpse of their heroine.', 'n. 一瞥, 一看', '/ɡlimps | glɪm(p)s | ɡlɪmps/', 'glimpse', 6);
INSERT INTO `words` VALUES (12357, 'glistening black hair', 'v. 闪光', '/\'ɡlisən | \'glɪs(ə)n | \'ɡlɪsn/', 'glisten', 6);
INSERT INTO `words` VALUES (12358, 'The river glittered in the sunlight.', 'v. 闪烁，闪耀; n. 灿烂的光华； 诱惑力， 魅力', '/\'glɪtər | \'ɡlɪtɚ/', 'glitter', 6);
INSERT INTO `words` VALUES (12359, NULL, 'n. 夕幕, 薄明, 黄昏', '/\'ɡləumiŋ | \'gləʊmɪŋ/', 'gloaming', 6);
INSERT INTO `words` VALUES (12360, 'Anti-abortionists are gloating over the court\'s decision.', 'v. 心满意足', '/ɡləut | gləʊt | ɡlot/', 'gloat', 6);
INSERT INTO `words` VALUES (12361, '...the gloom of a foggy November morning.', 'n. 阴暗, 阴沉', '/gluːm | ɡlum/', 'gloom', 6);
INSERT INTO `words` VALUES (12362, 'The report paints a gloomy picture of the economy.', 'adj. 黑暗的, 阴沉的, 令人沮丧的, 阴郁的', '/\'ɡlu:mi | \'gluːmɪ | \'ɡlumi/', 'gloomy', 6);
INSERT INTO `words` VALUES (12363, 'films which glorify violence', 'v. 吹捧， 美化', '/\'glɔːrɪfaɪ | \'ɡlɔrɪfaɪ/', 'glorify', 6);
INSERT INTO `words` VALUES (12364, 'This gel will add gloss to even the dullest hair.', 'n. 光泽的表面, 光彩, 欺人的表面, 假象, 注释', '/ɡlɔs | glɒs | ɡlɑs/', 'gloss', 6);
INSERT INTO `words` VALUES (12365, 'But avoid redundancy: Define an item in the glossary or in the domain model, but not in both.', 'n. 术语表', '/\'ɡlɔsəri | \'glɒs(ə)rɪ | \'ɡlɑsəri/', 'glossary', 6);
INSERT INTO `words` VALUES (12366, 'her glossy black hair', 'adj. 平滑的, 有光泽的', '/\'ɡlɔsi | \'glɒsɪ | \'ɡlɑsi/', 'glossy', 6);
INSERT INTO `words` VALUES (12367, 'The bedside lamp glowed dimly.', 'v. 发光，发热；发红; n. 发光； 兴高采烈', '/glou | ɡlo/', 'glow', 6);
INSERT INTO `words` VALUES (12368, 'He glowered at me but said nothing.', 'v. 怒目而视', '/ɡləuə | \'glaʊə | \'ɡlaʊɚ/', 'glower', 6);
INSERT INTO `words` VALUES (12369, 'I’ve had glowing reports from Neil about your work.', 'adj. 热情赞扬的', '/\'glouɪŋ | \'ɡləuiŋ/', 'glowing', 6);
INSERT INTO `words` VALUES (12370, 'The doctor injects glucose into the patient\'s vein.', 'n. 葡萄糖', '/\'ɡlu:kəus | \'gluːkəʊs; -z | \'ɡlukos/', 'glucose', 6);
INSERT INTO `words` VALUES (12371, 'Anna looked glum .', 'adj. 阴郁的, 阴沉的', '/ɡlʌm | glʌm/', 'glum', 6);
INSERT INTO `words` VALUES (12372, 'the glutted property market', 'v. 充斥', '/ɡlʌt | glʌt/', 'glut', 6);
INSERT INTO `words` VALUES (12373, 'glutinous mud', 'adj. 粘性的', '/\'ɡlu:tinəs | \'gluːtɪnəs | \'ɡlutənəs/', 'glutinous', 6);
INSERT INTO `words` VALUES (12374, '...a selfish, gluttonous and lazy person.', 'adj. 贪吃的， 暴食的', '/\'glʌtənəs | \'glʌtnəs/', 'gluttonous', 6);
INSERT INTO `words` VALUES (12375, 'In love, as in gluttony, pleasure is a matter of the utmost precision.', 'n. 暴食, 贪食', '/\'ɡlʌtəni | \'glʌt(ə)nɪ/', 'gluttony', 6);
INSERT INTO `words` VALUES (12376, 'The art of engraving or carving, especially on precious stones; glyptography.', 'n. 宝石雕刻术', NULL, 'glyptography', 6);
INSERT INTO `words` VALUES (12377, '...a large and beautiful garden full of ancient gnarled trees.', 'adj. 多瘤的, 粗糙的', '/nɑ:ld | nɑːld/', 'gnarled', 6);
INSERT INTO `words` VALUES (12378, 'When you write for a blog, your audience consists of internet users who have the attention span of a gnat.', 'n. 小昆虫, 小烦扰', '/næt/', 'gnat', 6);
INSERT INTO `words` VALUES (12379, 'Dexter gnawed his pen thoughtfully.', 'v. 咬, 啃, 啮, 使苦恼, 消耗, 折磨, 侵蚀', '/nɔ: | nɔː | nɔ/', 'gnaw', 6);
INSERT INTO `words` VALUES (12380, 'It was no worse, she said, on his birthday or the anniversary of his death – it was a constant, daily, gnawing sense of loss.', 'n. 咬, 苛责, 不断的苦痛', '/\'nɔ:iŋ | \'nɔː(r)ɪŋ | \'nɔɪŋ/', 'gnawing', 6);
INSERT INTO `words` VALUES (12381, 'Baby, you\'re so gneiss I\'ll never take you for granite.', 'n. [地质]片麻岩', '/nais | naɪs/', 'gneiss', 6);
INSERT INTO `words` VALUES (12382, 'a garden gnome', 'n. 格言, 箴言, 土地神, 侏儒', '/nəum | nəʊm/', 'gnome', 6);
INSERT INTO `words` VALUES (12383, NULL, 'adj. 格言的, 含格言的', '/\'nəumik | \'nəʊmɪk | \'nomɪk/', 'gnomic', 6);
INSERT INTO `words` VALUES (12384, 'The offer of economic aid was a goad to political change.', 'n. (赶牲口用的)刺棒, 激励物, 刺激物', '/ɡəud | gəʊd | ɡod/', 'goad', 6);
INSERT INTO `words` VALUES (12385, 'The gobble sound, from the male turkeys, on the other hand, sounds exactly like you’d expect from the name and they do this all the time.', 'n. 火鸡叫声', '/\'ɡɔbl | \'gɒb(ə)l | \'ɡɑbl/', 'gobble', 6);
INSERT INTO `words` VALUES (12386, 'The goblet was mantling with foam.', 'n. 高脚玻璃杯, 酒杯', '/\'ɡɔblit | \'gɒblɪt | \'ɡɑblət/', 'goblet', 6);
INSERT INTO `words` VALUES (12387, 'She goggled at me.', 'v. 瞪大眼睛看; n. 护目镜', '/\'gɑːgl | \'ɡɑɡl/', 'goggle', 6);
INSERT INTO `words` VALUES (12388, NULL, 'v. 逃避责任， 偷懒', '/\'gouldbrɪk/', 'goldbrick', 6);
INSERT INTO `words` VALUES (12389, 'Her humor is good, so the meal that she does is natural also more goluptious .', 'adj. 可口的, 香喷喷的, 好吃的', '/ɡə\'lʌpʃəs/', 'goluptious', 6);
INSERT INTO `words` VALUES (12390, 'Somebody goofed and entered the wrong amount.', 'v. 犯错误； 闲逛， 消磨时间', '/guːf | ɡuf/', 'goof', 6);
INSERT INTO `words` VALUES (12391, 'He likes movies with plenty of blood and gore (= violence ) .', 'n. 血块, 淤血, (帆或裙上缝的)三角形布', '/ɡɔ: | gɔː | ɡɔr/', 'gore', 6);
INSERT INTO `words` VALUES (12392, '...the deep gorge between these hills.', 'n. 咽喉, 胃, 暴食, 山峡, 峡谷, 障碍物', '/ɡɔ:dʒ | gɔːdʒ | ɡɔrdʒ/', 'gorge', 6);
INSERT INTO `words` VALUES (12393, '‘What do you think of my new flatmate?’ ‘He’s absolutely gorgeous !’', 'adj. 华丽的, 灿烂的', '/\'ɡɔ:dʒəs | \'gɔːdʒəs | \'ɡɔrdʒəs/', 'gorgeous', 6);
INSERT INTO `words` VALUES (12394, NULL, 'n. 丑陋可怕的女人', '/\'ɡɔ:ɡən/', 'gorgon', 6);
INSERT INTO `words` VALUES (12395, NULL, 'v. 狼吞虎咽', '/\'ɡɔ:məndaiz | \'ɡɔːməndaɪz/', 'gormandize', 6);
INSERT INTO `words` VALUES (12396, 'a gory horror movie', 'adj. 血淋淋的, 血污的, 满是血的', '/\'ɡɔ:ri | \'gɔːrɪ | \'ɡɔri/', 'gory', 6);
INSERT INTO `words` VALUES (12397, NULL, 'n. 小鹅, 愚蠢而无经验的人', '/\'ɡɔzliŋ | \'gɒzlɪŋ | \'ɡɑzlɪŋ/', 'gosling', 6);
INSERT INTO `words` VALUES (12398, 'the Gospel according to St Luke', 'n. 福音, <俗>信仰, 真理', '/\'ɡɔspəl | \'gɒsp(ə)l | \'ɡɑspl/', 'gospel', 6);
INSERT INTO `words` VALUES (12399, NULL, 'n. 小蜘蛛网, 蛛丝, 薄纱, 轻而弱者', '/\'ɡɔsəmə | \'gɒsəmə | \'ɡɑsəmɚ/', 'gossamer', 6);
INSERT INTO `words` VALUES (12400, 'He heard the heavy rounds gouge the ancient concrete, followed by the panicked cries of Grunts in the distance as they dove for cover—and into the semi-gelatinous, ankle-deep liquid.', 'n. 圆凿, 沟, 以圆凿刨', '/ɡaudʒ | gaʊdʒ; guːdʒ | ɡaʊdʒ/', 'gouge', 6);
INSERT INTO `words` VALUES (12401, 'I refused the last but washed down the fruit and vegetables with clear, cold water from a hollowed gourd.', 'n. 葫芦', '/ɡuəd | gʊəd; gɔːd | ɡʊrd/', 'gourd', 6);
INSERT INTO `words` VALUES (12402, 'Lyon is a gourmand\'s heaven, boasting perhaps more restaurants per square kilometre than anywhere else in Europe, and a galaxy of Michelin stars.', 'n. 美食者', '/\'ɡuəmənd | \'gʊəmənd; \'gɔː-/', 'gourmand', 6);
INSERT INTO `words` VALUES (12403, 'The seafood here is a gourmet\'s delight.', 'n. 能精选品评美食、美酒的人', '/\'ɡuəmei | \'gʊəmeɪ; \'gɔː- | \'ɡʊrme/', 'gourmet', 6);
INSERT INTO `words` VALUES (12404, '...he will meet with officials from several countries to discuss ways to promote good governance.', 'n. 统治, 管理, 统辖', '/\'ɡʌvənəns | \'gʌv(ə)nəns | \'gʌvɚnəns/', 'governance', 6);
INSERT INTO `words` VALUES (12405, NULL, 'adj. 细长的, 纤弱的', '/\'ɡræsail | \'græsɪl; \'græsaɪl/', 'gracile', 6);
INSERT INTO `words` VALUES (12406, 'Sibyl was the most gracious, helpful, and generous person to work with.', 'adj. 大方的， 和善的； 奢华的； 优美的， 雅致的', '/\'greɪʃəs | \'ɡreʃəs/', 'gracious', 6);
INSERT INTO `words` VALUES (12407, NULL, 'adj. 倾斜的', '/\'ɡreidiənt | \'greɪdɪənt | \'ɡredɪənt/', 'gradient', 6);
INSERT INTO `words` VALUES (12408, 'Martha had to have several skin grafts .', 'n. 嫁接, (接技用的)嫩枝, (皮肤等的)移植, 赎职', '/ɡrɑ:ft, ɡræft | grɑːft | ɡræft/', 'graft', 6);
INSERT INTO `words` VALUES (12409, 'There were crumbs and grains of sugar on the table.', 'n. 谷物； 小的硬粒', '/greɪn | ɡren/', 'grain', 6);
INSERT INTO `words` VALUES (12410, 'The application of RFLP Linkage genetic maps in the graminaceous crops; . 3)Following the tracks and appraisal of the chromosome or.', 'adj. 草(似),[植] 禾本的', '/,ɡræmi\'neiʃəs/', 'graminaceous', 6);
INSERT INTO `words` VALUES (12411, 'The Mid-West is the granary of the U.S.', 'n. 谷仓', '/\'ɡrænəri | \'græn(ə)rɪ | \'grænəri/', 'granary', 6);
INSERT INTO `words` VALUES (12412, 'The most visited city in the world, here is a capital whose great talent has been to interweave the grandeur of its official buildings with the everyday charm of its many quartiers.', 'n. 庄严, 伟大', '/\'ɡrændʒə | \'grændjə; -(d)ʒə | \'ɡrændʒɚ/', 'grandeur', 6);
INSERT INTO `words` VALUES (12413, 'A hero is more than one hundred times grandiloquence! ! ! ! !', 'n. 豪言壮语， 夸张之言', '/ɡræn\'diləkwəns | græn\'dɪləkwəns/', 'grandiloquence', 6);
INSERT INTO `words` VALUES (12414, NULL, 'adj. 夸张的, 浮夸的, 夸大的', '/ɡræn\'diləkwənt | græn\'dɪləkwənt/', 'grandiloquent', 6);
INSERT INTO `words` VALUES (12415, 'Chopin did not feel that his delicate technique and intricate melodies were as suited to the grandiose hall as they were to smaller environments and audiences.', 'adj. 宏伟的, 堂皇的, 宏大的', '/\'ɡrændiəus | \'grændɪəʊs | \'ɡrændɪos/', 'grandiose', 6);
INSERT INTO `words` VALUES (12416, 'The grandstand was filled with men in seersucker suits, braces and pocket squares.', 'n. 正面看台', '/\'ɡrændstænd | \'græn(d)stænd | \'ɡrænstænd/', 'grandstand', 6);
INSERT INTO `words` VALUES (12417, 'He was very skilled at pointing down the blocks of granite.', 'n. 花岗岩', '/\'ɡrænit | \'grænɪt/', 'granite', 6);
INSERT INTO `words` VALUES (12418, 'Britain could grant Spain’s request .', 'v. 同意给予； 授予', '/grænt | ɡrænt/', 'grant', 6);
INSERT INTO `words` VALUES (12419, '...a granular fertilizer.', 'adj. 由小粒而成的, 粒状的', '/\'ɡrænjulə | \'grænjʊlə | \'grænjəlɚ/', 'granular', 6);
INSERT INTO `words` VALUES (12420, NULL, 'v. 成为粒状', '/\'ɡrænjuleit | \'grænjʊleɪt | \'grænjə,let/', 'granulate', 6);
INSERT INTO `words` VALUES (12421, 'coffee granules', 'n. 小粒, 颗粒, 细粒', '/\'ɡrænju:l | \'grænjuːl | \'grænjʊl/', 'granule', 6);
INSERT INTO `words` VALUES (12422, 'a graphic artist', 'adj. 绘画似的, 图解的', '/\'ɡræfik | \'græfɪk/', 'graphic', 6);
INSERT INTO `words` VALUES (12423, 'Hanson was a hard grasping man.', 'adj. 抓的, 贪婪的, 握的', '/\'ɡrɑ:spiŋ | \'grɑːspɪŋ/', 'grasping', 6);
INSERT INTO `words` VALUES (12424, 'A wood fire burned in the grate.', 'n. 壁炉, 炉', '/ɡreit | greɪt | ɡret/', 'grate', 6);
INSERT INTO `words` VALUES (12425, 'Our grateful thanks go to all who participated.', 'adj. 感激的, 感谢的', '/\'ɡreitful | \'greɪtfʊl; -f(ə)l | \'ɡretfl/', 'grateful', 6);
INSERT INTO `words` VALUES (12426, 'So even to-day, when we fail to see the truth of religion, we seek in its observance an artistic gratification.', 'n. 满意', '/,ɡrætifi\'keiʃən | ɡrætɪfɪ\'keɪʃn | ,ɡrætɪfɪ\'keʃən/', 'gratification', 6);
INSERT INTO `words` VALUES (12427, 'He was gratified by Lucy’s response.', 'v. 使满足', '/\'ɡrætifai | \'grætɪfaɪ | \'grætə\'fai/', 'gratify', 6);
INSERT INTO `words` VALUES (12428, 'Leaves clogged the grating over the drain.', 'n. 门窗的栅栏, [物理]光栅, 摩擦, 摩擦声', '/\'greitiŋ | \'greɪtɪŋ | \'gretɪŋ/', 'grating', 6);
INSERT INTO `words` VALUES (12429, 'David gives the first consultation gratis.', 'adv. 免费, 白送', '/\'ɡreitis | \'grætɪs; \'grɑː-; \'greɪ-/', 'gratis', 6);
INSERT INTO `words` VALUES (12430, 'children’s books which include gratuitous violence', 'adj. 免费的, 无理由的', '/ɡrə\'tju:itəs | grə\'tjuːɪtəs | ɡrə\'tuɪtəs/', 'gratuitous', 6);
INSERT INTO `words` VALUES (12431, 'The porter expects a gratuity.', 'n. 赠物, 贺仪, 赏钱', '/ɡrə\'tju:əti | grə\'tjuːɪtɪ | ɡrə\'tuəti/', 'gratuity', 6);
INSERT INTO `words` VALUES (12432, NULL, 'n. 不平, 苦诉, [律]控诉要旨', '/grə\'veɪmen/', 'gravamen', 6);
INSERT INTO `words` VALUES (12433, 'Matthew’s life is in grave danger .', 'adj. 严肃的，庄重的; n. 墓穴', '/greɪv | ɡrev/', 'grave', 6);
INSERT INTO `words` VALUES (12434, 'a gravel path', 'n. 砂砾, 砂砾层', '/\'ɡrævəl | \'græv(ə)l | \'ɡrævl/', 'gravel', 6);
INSERT INTO `words` VALUES (12435, 'You naturally gravitate toward people with shared values.', 'v. 被强烈地吸引； 受引力作用而运动', '/\'grævɪteɪt | \'ɡrævɪtet/', 'gravitate', 6);
INSERT INTO `words` VALUES (12436, 'the Moon’s gravitational field', 'adj. 万有引力的， 重力的', '/ˌgrævɪ\'teɪʃənl | ,ɡrævɪ\'teʃənl/', 'gravitational', 6);
INSERT INTO `words` VALUES (12437, 'the force of gravity', 'n. 地心引力, 重力', '/\'ɡræviti | \'grævɪtɪ | \'ɡrævəti/', 'gravity', 6);
INSERT INTO `words` VALUES (12438, 'I fell on the gravel, severely grazing my knee.', 'v. 放牧, 吃草, 擦伤, 擦过', '/ɡreiz | greɪz | ɡrez/', 'graze', 6);
INSERT INTO `words` VALUES (12439, 'Sometimes green denotes lack of experience; for example, a \'greenhorn\' is a novice.', 'n. 生手, 缺乏经验的人, 不懂世故的人', '/\'ɡri:nhɔ:n | \'griːnhɔːn | \'grin,hɔrn/', 'greenhorn', 6);
INSERT INTO `words` VALUES (12440, 'But these two countries are responsible for almost half of all greenhouse gas emissions.', 'n. 温室, 花房', '/\'ɡri:nhaus | \'griːnhaʊs | \'ɡrinhaʊs/', 'greenhouse', 6);
INSERT INTO `words` VALUES (12441, 'She is such a gregarious and outgoing person.', 'adj. 社交的, 群居的', '/ɡri\'ɡεəriəs | grɪ\'geərɪəs | grɪ\'gɛrɪəs/', 'gregarious', 6);
INSERT INTO `words` VALUES (12442, NULL, 'n. 群居； 合群， 爱交友', '/gri\'gɛəriəsnis | grɪ\'geriəsnəs/', 'gregariousness', 6);
INSERT INTO `words` VALUES (12443, NULL, 'n. 煎饼用浅锅, 矿筛', '/\'ɡridl | \'grɪd(ə)l | \'ɡrɪdl/', 'griddle', 6);
INSERT INTO `words` VALUES (12444, NULL, 'n. 烤架, 格状物', '/\'ɡrid,aiən | \'grɪdaɪən/', 'gridiron', 6);
INSERT INTO `words` VALUES (12445, 'Every change in our lives brings with it griefs.', 'n. 忧伤， 悲伤', '/griːf | ɡrif/', 'grief', 6);
INSERT INTO `words` VALUES (12446, 'anyone who has a legitimate grievance against the company', 'n. 委屈, 冤情, 不平', '/\'ɡri:vəns | \'griːv(ə)ns | \'grivəns/', 'grievance', 6);
INSERT INTO `words` VALUES (12447, 'My aunt, it grieves me to say, gets things confused.', 'v. 使某人极为悲伤', '/griːv | griv/', 'grieve', 6);
INSERT INTO `words` VALUES (12448, 'Mr. Morris said the victims had suffered from a very grievous mistake.', 'adj. 令人忧伤的', '/\'ɡri:vəs | \'griːvəs | \'ɡrivəs/', 'grievous', 6);
INSERT INTO `words` VALUES (12449, NULL, 'n. 爽朗的人, 轻松愉快的人', '/grɪg/', 'grig', 6);
INSERT INTO `words` VALUES (12450, 'Pop it under the grill for five minutes.', 'n. 烤架, 铁格子, 烤肉', '/grɪl | ɡrɪl/', 'grill', 6);
INSERT INTO `words` VALUES (12451, NULL, 'n. 格子, 格子窗, 铁格子', '/ɡril | grɪl/', 'grille', 6);
INSERT INTO `words` VALUES (12452, '‘I’ll survive,’ he said with a grim smile.', 'adj. 严酷的', '/ɡrim | grɪm | ɡrɪm/', 'grim', 6);
INSERT INTO `words` VALUES (12453, 'His face twisted in a grimace of pain.', 'n. 面部的歪扭, 痛苦的表情, 鬼脸', '/ɡri\'meis | \'grɪməs; grɪ\'meɪs | ɡrɪ\'mes/', 'grimace', 6);
INSERT INTO `words` VALUES (12454, 'grimy windows', 'adj. 污秽的, 肮脏的', '/\'ɡraimi | \'graɪmɪ | \'ɡraɪmi/', 'grimy', 6);
INSERT INTO `words` VALUES (12455, 'He grins, delighted at the memory.', 'v. 露齿而笑； 眦牙咧嘴', '/grɪn | ɡrɪn/', 'grin', 6);
INSERT INTO `words` VALUES (12456, 'a stone for grinding knives and scissors', 'v. 磨(碎), 碾(碎), 折磨', '/ɡraind | graɪnd | ɡraɪnd/', 'grind', 6);
INSERT INTO `words` VALUES (12457, NULL, 'n. 旋转磨石, 旋转研磨机', '/\'ɡraindstəun | \'graɪn(d)stəʊn | \'ɡraɪndston/', 'grindstone', 6);
INSERT INTO `words` VALUES (12458, 'Why are football players griping when the average salary is half a million dollars?', 'n. 紧握, 柄, 把手, 控制, 苦恼', '/graɪp | ɡraɪp/', 'gripe', 6);
INSERT INTO `words` VALUES (12459, 'Collins’ gripping detective novel', 'adj. 引起人注意的；吸引人的', '/\'ɡripiŋ/', 'gripping', 6);
INSERT INTO `words` VALUES (12460, 'a series of grisly murders', 'adj. 恐怖的, 可怕的, 令人毛骨悚然的', '/\'ɡrizli | \'grɪzlɪ | \'grɪzli/', 'grisly', 6);
INSERT INTO `words` VALUES (12461, 'Chicken skin and gristle contain a good deal of Chondroitin Sulfate which can nourish the skin.', 'n. 软骨', '/\'ɡrisl | \'grɪs(ə)l | \'ɡrɪsl/', 'gristle', 6);
INSERT INTO `words` VALUES (12462, 'I want grits with my eggs instead of hash browns.', 'n. 粗砂', '/ɡrit | grɪt | ɡrɪt/', 'grit', 6);
INSERT INTO `words` VALUES (12463, 'The kids all groaned when I switched off the TV.', 'v. 呻吟，叹息; n. 呻吟， 叹息', '/groun | ɡron/', 'groan', 6);
INSERT INTO `words` VALUES (12464, 'I felt really groggy after 15 hours on the plane.', 'adj. 酒醉的, 东歪西倒的, 摇摇晃晃的, 头昏眼花的', '/\'ɡrɔɡi | \'grɒgɪ/', 'groggy', 6);
INSERT INTO `words` VALUES (12465, '...the bride and groom.', 'n. 马夫, 新郎, 男仆', '/gruːm | ɡrum/', 'groom', 6);
INSERT INTO `words` VALUES (12466, 'The bolt slid easily into the groove.', 'n. (唱片等的) 凹槽, 惯例, 最佳状态', '/ɡru:v | gruːv | ɡruv/', 'groove', 6);
INSERT INTO `words` VALUES (12467, 'With his left hand he groped for the knob, turned it, and pulled the door open.', 'v. 摸索， 探索', '/group | ɡrop/', 'grope', 6);
INSERT INTO `words` VALUES (12468, NULL, 'adv. 摸索着, 暗中摸索地', '/\'grəupiŋli/', 'gropingly', 6);
INSERT INTO `words` VALUES (12469, 'The company was guilty of gross negligence.', 'adj. 总的, 毛重的', '/ɡrəus | grəʊs | ɡros/', 'gross', 6);
INSERT INTO `words` VALUES (12470, 'It’s grotesque to portray peace campaigners as unpatriotic.', 'adj. 奇形怪状的, 奇异', '/ɡrəu\'tesk | grə(ʊ)\'tesk | gro\'tɛsk/', 'grotesque', 6);
INSERT INTO `words` VALUES (12471, 'Water trickles through an underground grotto.', 'n. 洞穴, 岩穴, 人工洞室', '/\'ɡrɔtəu | \'grɒtəʊ | \'ɡrɑto/', 'grotto', 6);
INSERT INTO `words` VALUES (12472, 'He\'s an old grouch but she puts up with him.', 'n. 不高兴的人, 心怀不满', '/ɡrautʃ | graʊtʃ | ɡraʊtʃ/', 'grouch', 6);
INSERT INTO `words` VALUES (12473, 'Fortunately my suspicions proved groundless .', 'adj. 无理由的， 无根据的', '/\'graundləs | \'ɡraʊndləs/', 'groundless', 6);
INSERT INTO `words` VALUES (12474, 'the grouse shooting season', 'n. 松鸡, 牢骚', '/ɡraus | graʊs | ɡraʊs/', 'grouse', 6);
INSERT INTO `words` VALUES (12475, '...an olive grove.', 'n. 小树林', '/ɡrəuv | grəʊv | ɡrov/', 'grove', 6);
INSERT INTO `words` VALUES (12476, 'I saw him grovelling in the road for his hat.', 'v. 趴, 匍匐, 卑躬屈膝, 五体投地的', '/\'ɡrɔvəl | \'ɡrɑvl/', 'grovel', 6);
INSERT INTO `words` VALUES (12477, NULL, 'n. 五体投地的人, 卑恭屈节的人', '/\'grɔvlə/', 'groveler', 6);
INSERT INTO `words` VALUES (12478, '‘Get out of my way,’ he growled.', 'v. 咆哮, 发牢骚地说', '/ɡraul | graʊl | ɡraʊl/', 'growl', 6);
INSERT INTO `words` VALUES (12479, NULL, 'v. 不给予', '/ɡrʌdʒ | grʌdʒ/', 'grudge', 6);
INSERT INTO `words` VALUES (12480, 'He even earned his opponents\' grudging respect.', 'adj. 不愿的, 勉强的, 吝啬的', '/\'ɡrʌdʒiŋ | \'grʌdʒɪŋ | \'ɡrʌdʒɪŋ/', 'grudging', 6);
INSERT INTO `words` VALUES (12481, NULL, 'n. 重罚, 严惩', '/\'ɡruəliŋ/', 'grueling', 6);
INSERT INTO `words` VALUES (12482, 'Police described it as a particularly gruesome attack.', 'adj. 可怕的, 可憎的, 令人厌恶的', '/\'ɡru:səm | \'gruːs(ə)m/', 'gruesome', 6);
INSERT INTO `words` VALUES (12483, 'His manner can be rather gruff.', 'adj. (说话、态度等) 粗暴的, 生硬的, 脾气坏的, (声音)粗哑的', '/grʌf | ɡrʌf/', 'gruff', 6);
INSERT INTO `words` VALUES (12484, '‘This is boring,’ Kathleen grumbled.', 'adj. 抱怨地表示, 嘟囔地说', '/\'grʌmb(ə)l | \'ɡrʌmbl/', 'grumble', 6);
INSERT INTO `words` VALUES (12485, 'Mina’s always a bit grumpy first thing in the morning.', 'adj. 脾气坏的, 性情乖戾的, 脾气暴躁的', '/\'ɡrʌmpi | \'grʌmpɪ/', 'grumpy', 6);
INSERT INTO `words` VALUES (12486, NULL, 'n. 小猪', '/\'ɡrʌntl/', 'gruntling', 6);
INSERT INTO `words` VALUES (12487, 'The bank will only lend me money if my parents guarantee the loan.', 'v. 保证， 担保', '/ˌgærən\'tiː | ,ɡærən\'ti/', 'guarantee', 6);
INSERT INTO `words` VALUES (12488, 'The minister was quite guarded in his comments.', 'adj. 被防护者的, 被看守着的, 被监视着的, 警戒着的', '/\'ɡɑ:did | \'gɑːdɪd | \'ɡɑrdɪd/', 'guarded', 6);
INSERT INTO `words` VALUES (12489, NULL, 'n. 易骗的人', '/\'ɡʌdʒən | \'gʌdʒ(ə)n/', 'gudgeon', 6);
INSERT INTO `words` VALUES (12490, 'We guffawed at what Graham had written.', 'v. 哄笑, 狂笑', '/ɡʌ\'fɔ: | gə\'fɔː | ɡə\'fɔ/', 'guffaw', 6);
INSERT INTO `words` VALUES (12491, 'I love children\'s innocence and lack of guile.', 'n. 欺骗， 欺诈； 狡猾', '/gaɪl | ɡaɪl/', 'guile', 6);
INSERT INTO `words` VALUES (12492, 'Joanne was so guileless that Claire had no option but to believe her.', 'adj. 厚道的， 老实的', '/\'gaɪlləs/', 'guileless', 6);
INSERT INTO `words` VALUES (12493, 'He ends it by pretending to end his life – with a guillotine.', 'n. 断头台, (切纸的)闸刀', '/\'ɡiləti:n | \'gɪlətiːn; ,gɪlə\'tiːn | \'ɡɪlətin/', 'guillotine', 6);
INSERT INTO `words` VALUES (12494, 'He used to buy them expensive presents, out of guilt.', 'n. 罪行, 内疚', '/ɡilt | gɪlt | ɡɪlt/', 'guilt', 6);
INSERT INTO `words` VALUES (12495, 'It’s the same idea in a different guise.', 'n. 外观， 装束； 伪装， 假装', '/gaɪz | ɡaɪz/', 'guise', 6);
INSERT INTO `words` VALUES (12496, '...California Gulch.', 'n. <美>干谷峡谷, 冲沟(尤指产金地的急流峡谷)', '/ɡʌltʃ | gʌltʃ/', 'gulch', 6);
INSERT INTO `words` VALUES (12497, NULL, 'n. [动] 鸥, 易受骗之人, 笨人', '/ɡʌl | gʌl/', 'gull', 6);
INSERT INTO `words` VALUES (12498, 'Plastic replicas of the Greek pottery are sold to gullible tourists.', 'adj. 易受骗的', '/\'ɡʌləbl | \'gʌlɪb(ə)l/', 'gullible', 6);
INSERT INTO `words` VALUES (12499, 'She gulped down her breakfast and ran for the bus.', 'v. 吞, 一口吞(下), 忍住, 抑制', '/ɡʌlp | gʌlp/', 'gulp', 6);
INSERT INTO `words` VALUES (12500, 'I do not chew gum in public.', 'n. 树胶， 树脂； 橡皮糖， 口香糖', '/gʌm | ɡʌm/', 'gum', 6);
INSERT INTO `words` VALUES (12501, 'In part, that\'s because the economic power of fuhyo — rumor — is a force that even gumption and initiative can\'t combat.', 'n. 进取心, 气概', '/\'ɡʌmpʃən | \'gʌm(p)ʃ(ə)n/', 'gumption', 6);
INSERT INTO `words` VALUES (12502, NULL, 'n. [印度教](个人的)宗教老师(或指导), (受下属崇敬的)领袖, 头头', '/\'ɡuru: | \'gʊruː | \'ɡʊru/', 'guru', 6);
INSERT INTO `words` VALUES (12503, 'All that pent-up frustration gushed out in a torrent of abuse.', 'v. 涌出', '/ɡʌʃ | gʌʃ/', 'gush', 6);
INSERT INTO `words` VALUES (12504, 'And, at this particular moment, we are confronted by the picture of an uncontrolled gusher of oil spewing destruction into the gulf.', 'n. 喷出物, 喷油井', '/\'ɡʌʃə | \'gʌʃə | \'ɡʌʃɚ/', 'gusher', 6);
INSERT INTO `words` VALUES (12505, 'A gust of wind drove down the valley.', 'n. 阵风, 一阵狂风, (雨、冰雹、烟、火、声音等的)突然一阵，（感情的）迸发，汹涌', '/ɡʌst | gʌst/', 'gust', 6);
INSERT INTO `words` VALUES (12506, 'Through Jia Bao-Yu\'s olfaction and gustation, his spiritual love and facultative desire was emphasized.', 'n. 尝味, 味觉', '/ɡʌ\'steiʃən | gʌ\'steɪʃ(ə)n/', 'gustation', 6);
INSERT INTO `words` VALUES (12507, 'A good dish, either smelly or tasty should be pleasant in gustatory sense, and thus stimulates the appetite.', 'adj. 味觉的， 品尝的', '/\'gʌstətəri | \'gʌstə,tori/', 'gustatory', 6);
INSERT INTO `words` VALUES (12508, NULL, 'n. 爱好, 嗜好, 趣味, 由衷的高兴', '/\'ɡʌstəu | \'gʌstəʊ | \'ɡʌsto/', 'gusto', 6);
INSERT INTO `words` VALUES (12509, 'I should have had the support of my team, but they were really gutless.', 'adj. 无胆量的, 没勇气的, 没有生气的', '/\'ɡʌtlis | \'gʌtlɪs | \'gʌtləs/', 'gutless', 6);
INSERT INTO `words` VALUES (12510, 'The gutters were blocked and overflowing.', 'n. 水槽, 檐槽, 排水沟, 槽, 贫民区', '/\'ɡʌtə | \'gʌtə | \'gʌtɚ/', 'gutter', 6);
INSERT INTO `words` VALUES (12511, NULL, 'v. 贪婪且出声响地吃喝', '/\'ɡʌtl | \'gʌtl/', 'guttle', 6);
INSERT INTO `words` VALUES (12512, 'Joe had a low, guttural voice with a Midwestern accent.', 'adj. 喉咙的, 喉音的, 咽喉的', '/\'ɡʌtərəl | \'gʌt(ə)r(ə)l | \'gʌtərəl/', 'guttural', 6);
INSERT INTO `words` VALUES (12513, 'Dave’s a nice guy when you get to know him.', 'n. 家伙, 人', '/ɡai | gaɪ/', 'guy', 6);
INSERT INTO `words` VALUES (12514, 'They’ve been guzzling beer all evening.', 'v. 狂饮, 暴食, 喝酒化掉(钱)', '/\'ɡʌzl | \'gʌz(ə)l/', 'guzzle', 6);
INSERT INTO `words` VALUES (12515, 'She passed her qualification for the Olympic gymnastic competition.', 'adj. 体操的， 体育的', '/dʒɪm\'næstɪk | dʒɪm\'næstɪks/', 'gymnastic', 6);
INSERT INTO `words` VALUES (12516, NULL, 'n. 妇女当政, 女权政治', '/,ɡaini\'kɔkrəsi/', 'gynaecocracy', 6);
INSERT INTO `words` VALUES (12517, NULL, 'adj. <美>= gynaecoid', '/\'ɡaɪnɪkɒɪd | \'ɡainikɔid/', 'gynecoid', 6);
INSERT INTO `words` VALUES (12518, 'The dancers gyrated wildly to the beat of the music.', 'v. 旋转, 不停地转动', '/,dʒaiə\'reit | dʒaɪ\'rəɪt | \'dʒaɪret/', 'gyrate', 6);
INSERT INTO `words` VALUES (12519, NULL, 'n. 陀螺仪, 回旋装置, 回转仪, 纵舵调整器', '/\'dʒaiərəskəup | \'dʒaɪrəskəʊp | \'dʒaɪrəskop/', 'gyroscope', 6);
INSERT INTO `words` VALUES (12520, NULL, 'adj. 熟练的, 灵巧的', '/\'hæbɪl/', 'habile', 6);
INSERT INTO `words` VALUES (12521, 'It would cost a fortune to make the place habitable.', 'adj. 可居住的', '/\'hæbɪtəbl/', 'habitable', 6);
INSERT INTO `words` VALUES (12522, 'watching monkeys in their natural habitat', 'n. (动植物的)生活环境, 产地、栖息地, 居留地, 自生地, 聚集处', '/\'hæbitæt | \'hæbɪtæt | \'hæbə\'tæt/', 'habitat', 6);
INSERT INTO `words` VALUES (12523, 'Over the centuries, these animals have become habituated to living in a dry environment.', 'v. 使习惯于, 使熟习于', '/hə\'bɪtʃʊeɪt; -tjʊ- | həˈbɪtʃʊˌet/', 'habituate', 6);
INSERT INTO `words` VALUES (12524, 'Both men had been hacked to death (= killed using large knives ).', 'v. 砍', '/hæk/', 'hack', 6);
INSERT INTO `words` VALUES (12525, 'Power corrupts and absolute power corrupts absolutely. That\'s the old hackneyed phrase, but it\'s true.', 'adj. 不新奇的, 陈腐的, 常见的', '/\'hæknid | \'hæknɪd/', 'hackneyed', 6);
INSERT INTO `words` VALUES (12526, NULL, 'adj. 血的', '/hi:\'mætik, he-/', 'haematic', 6);
INSERT INTO `words` VALUES (12527, 'Aspirin should be avoided if you have a stomach (peptic) ulcer, haemophilia or other bleeding disorder, or an allergy to aspirin or to other non-steroidal anti-inflammatory drugs (NSAID).', 'n. [医]血友病, 出血不止症', '/,hi:məu\'filiə, ,hem- | ,hɛmo\'fɪlɪr/', 'haemophilia', 6);
INSERT INTO `words` VALUES (12528, 'He died of a massive brain haemorrhage.', 'n. 出血(尤指大出血), 溢血', '/\'heməridʒ | \'hemərɪdʒ | \'hɛmərɪdʒ/', 'haemorrhage', 6);
INSERT INTO `words` VALUES (12529, 'Objective To prove the clinical effect of portable auto-haemostat machine on body\'s limbs.', 'n. (=hemostat][医)止血器, 止血药', NULL, 'haemostat', 6);
INSERT INTO `words` VALUES (12530, NULL, 'n. 柄, 把手', '/hɑ:ft, hæft | hɑːft | hæft/', 'haft', 6);
INSERT INTO `words` VALUES (12531, 'Sam looked tired and haggard.', 'n. 野鹰', '/\'hæɡəd | \'hægəd | \'hæɡɚd/', 'haggard', 6);
INSERT INTO `words` VALUES (12532, 'Ella showed her the best places to go for a good buy, and taught her how to haggle with used furniture dealers.', 'v. 争价', '/\'hæɡl | \'hæg(ə)l/', 'haggle', 6);
INSERT INTO `words` VALUES (12533, 'a skinny guy with hairy legs', 'adj. 多毛的, 毛似的', '/\'hεəri | \'heərɪ | \'hɛri/', 'hairy', 6);
INSERT INTO `words` VALUES (12534, 'It was all a far cry from those halcyon days in 1990, when he won three tournaments on the European tour.', 'n. （相传冬至时能使海平面平静的）翠鸟', '/\'hælsiən | \'hælsɪən; -ʃ(ə)n | \'hælsɪən/', 'halcyon', 6);
INSERT INTO `words` VALUES (12535, 'She’s still hale and hearty at 74.', 'adj. 强壮的, 健壮的（尤指老人）, 矍铄的', '/heil | heɪl/', 'hale', 6);
INSERT INTO `words` VALUES (12536, '...a halfhearted apology.', 'adj. 不认真的， 不热心的', '/ˌhæf\'hɑːrtɪd/', 'halfhearted', 6);
INSERT INTO `words` VALUES (12537, NULL, 'v. 把…视为神圣； 尊敬， 敬畏', '/\'hæləu | ˈhæləʊ/', 'hallow', 6);
INSERT INTO `words` VALUES (12538, 'The bones will be buried in hallowed ground.', 'adj. 神圣化的, 神圣的', '/\'hæləud | \'hæləʊd | \'hælod/', 'hallowed', 6);
INSERT INTO `words` VALUES (12539, 'The patients suffered hallucinations caused by the drug.', 'n. 幻觉', '/həˌluːsɪ\'neɪʃn | hə,lusɪ\'neʃən/', 'hallucination', 6);
INSERT INTO `words` VALUES (12540, NULL, 'n. （日月周围的）晕轮, 光环, 荣光', '/\'heiləu | \'heɪləʊ | \'helo/', 'halo', 6);
INSERT INTO `words` VALUES (12541, 'Heavy snowfalls brought traffic to a halt (= made it stop moving ).', 'n. 停止, 暂停, 中断', '/hɔ:lt | hɔːlt | hɔlt/', 'halt', 6);
INSERT INTO `words` VALUES (12542, 'We carried on a rather halting conversation.', 'adj. 跛的, 犹豫的, 蹒跚的', '/\'hɔ:ltiŋ | \'hɔːltɪŋ | \'hɔltɪŋ/', 'halting', 6);
INSERT INTO `words` VALUES (12543, 'the sound of hammering and sawing', 'v. 锤击， 锤打; n. 锤子，槌', '/\'hæmər | \'hæmɚ/', 'hammer', 6);
INSERT INTO `words` VALUES (12544, 'She tried to run, but was hampered by her heavy suitcase.', 'v. 妨碍, 牵制', '/\'hæmpə | \'hæmpɚ/', 'hamper', 6);
INSERT INTO `words` VALUES (12545, 'Then he turned the handle and went in.', 'n. 柄, 把手, 把柄, 口实, 手感', '/\'hændl | \'hænd(ə)l/', 'handle', 6);
INSERT INTO `words` VALUES (12546, 'Senator McCain and the former president came together in a hangar at Houston\'s Hobby airport and stood side by side with their wives as the 41st president offered his endorsement.', 'n. 飞机修理库, 飞机棚', '/\'hæŋə | \'hæŋɚ/', 'hangar', 6);
INSERT INTO `words` VALUES (12547, 'I could tell from his hangdog look that things had gone badly.', 'adj. 忧愁的； 低贱的', '/\'hæŋdɑːg | \'hæŋdɔɡ/', 'hangdog', 6);
INSERT INTO `words` VALUES (12548, 'She took off her jacket and hung it on a hanger.', 'n. 绞刑执行者, 衣架', '/\'hæŋə | \'hæŋɚ/', 'hanger', 6);
INSERT INTO `words` VALUES (12549, 'I had a terrible hangover the next day.', 'n. 残留, 遗物, 宿醉', '/\'hæŋəuvə | \'hæŋəʊvə | \'hæŋ\'ovɚ/', 'hangover', 6);
INSERT INTO `words` VALUES (12550, 'I hankered after a floor-length brown suede coat.', 'v. 渴望, 追求', '/\'hæŋkə | \'hæŋkɚ/', 'hanker', 6);
INSERT INTO `words` VALUES (12551, 'From time to time we all get a hankering for something a little different.', 'n. 渴望， 向往', '/\'hæŋkərɪŋ | \'hæŋkəriŋ/', 'hankering', 6);
INSERT INTO `words` VALUES (12552, 'Educational provision in the country is haphazard.', 'adj. 任意的， 偶然的， 无秩序的', '/hæp\'hæzərd | \'hæphæzəd/', 'haphazard', 6);
INSERT INTO `words` VALUES (12553, NULL, 'adv. 偶然地； 随意地； 杂乱地', '/,hæp\'hæzədli | hæp\'hæzərdli/', 'haphazardly', 6);
INSERT INTO `words` VALUES (12554, 'The hapless passengers were stranded at the airport for three days.', 'adj. 倒霉的, 不幸的', '/\'hæplis | \'hæplɪs/', 'hapless', 6);
INSERT INTO `words` VALUES (12555, NULL, 'n. 尤指指责性的, 长篇大论, 夸张的话', '/hə\'ræŋ/', 'harangue', 6);
INSERT INTO `words` VALUES (12556, 'A number of black youths have complained of being harassed by the police.', 'v. 烦恼', '/\'hærəs, hə\'ræs | \'hærəs; hə\'ræs | ˈhærəs, həˈræs/', 'harass', 6);
INSERT INTO `words` VALUES (12557, NULL, 'n. 折磨', '/\'hærəsmənt, hə\'ræsmənt | \'hærəsm(ə)nt; hə\'ræsm(ə)nt | hə\'ræsmənt/', 'harassment', 6);
INSERT INTO `words` VALUES (12558, 'The November air stung my cheeks, a harbinger of winter.', 'n. 先驱, 预兆', '/\'hɑ:bindʒə | \'hɑːbɪndʒə | \'hɑrbɪndʒɚ/', 'harbinger', 6);
INSERT INTO `words` VALUES (12559, 'All the battleships can refresh in this harbor.', 'n. 海港', '/\'hɑ:bə | \'hɑrbɚ/', 'harbor', 6);
INSERT INTO `words` VALUES (12560, NULL, 'adj. 不屈的， 顽强的', '/,ha:d\'bitn | ˌhɑːrd\'bɪtn/', 'hardbitten', 6);
INSERT INTO `words` VALUES (12561, '...a hardheaded and shrewd businesswoman.', 'adj. 冷静的, 脚踏实地的, 无懈可击的, 顽固的', '/\'hɑ:d\'hedid | \'hɑːd\'hedɪd/', 'hardheaded', 6);
INSERT INTO `words` VALUES (12562, NULL, 'n. 胆大无敌, 厚颜, 刚毅', '/\'hɑ:dihud | \'hɑːdɪhʊd | \'hɑrdɪ,hʊd/', 'hardihood', 6);
INSERT INTO `words` VALUES (12563, 'an economic policy that caused great hardship for many people', 'n. 困苦， 拮据', '/\'hɑːrdʃɪp | \'hɑrdʃɪp/', 'hardship', 6);
INSERT INTO `words` VALUES (12564, 'hardy mountain goats', 'adj. 难的, 艰苦的，勇敢的', '/\'hɑ:di | \'hɑːdɪ/', 'hardy', 6);
