INSERT INTO `words` VALUES (12566, 'How well all her garments harmonized with each other.', 'v. 协调', '/\'hɑ:mənaiz | \'hɑːmənaɪz | \'hɑrmənaɪz/', 'harmonize', 6);
INSERT INTO `words` VALUES (12567, 'a safety harness', 'n. (全套)马具, 系在身上的绳子, 甲胄', '/\'hɑːnɪs | \'hɑrnɪs/', 'harness', 6);
INSERT INTO `words` VALUES (12568, 'He played an Irish melody on the harp.', 'v. 弹竖琴； 喋喋不休地说或写; n. 竖琴', '/hɑːrp | hɑrp/', 'harp', 6);
INSERT INTO `words` VALUES (12569, 'A rifle and a harpoon gun were hanging from the wall of his rickety shack.', 'n. (捕鲸用)鱼叉', '/hɑ:\'pu:n | hɑː\'puːn | hɑr\'pun/', 'harpoon', 6);
INSERT INTO `words` VALUES (12570, 'One piece was the harpsichord part for the Concerto in G (molto allegro) and the other was the Prelude in G major.', 'n. 大键琴', '/\'hɑ:psikɔ:d | \'hɑːpsɪkɔːd/', 'harpsichord', 6);
INSERT INTO `words` VALUES (12571, 'She was a mean old harridan.', 'n. 形容枯槁(或脾气暴躁)的老妇人,名声不好的老泼妇', '/\'hæridən | \'hærɪd(ə)n | \'hærɪdən/', 'harridan', 6);
INSERT INTO `words` VALUES (12572, 'He is removing weeds with a harrow in the rice field.', 'n. 耙(地), 使精神痛苦', '/\'hærəu | \'hærəʊ/', 'harrow', 6);
INSERT INTO `words` VALUES (12573, 'a harrowing experience', 'adj. 痛心的, 悲惨的', '/\'hærəuiŋ | \'hærəʊɪŋ | \'hæroɪŋ/', 'harrowing', 6);
INSERT INTO `words` VALUES (12574, 'He is increasingly active in harrying the government in late-night debates.', 'v. 掠夺, 折磨', '/\'hæri | \'hærɪ/', 'harry', 6);
INSERT INTO `words` VALUES (12575, 'the harsh measures taken against the protesters', 'adj. 严厉的； 粗糙的； 刺耳的', '/hɑːrʃ | hɑrʃ/', 'harsh', 6);
INSERT INTO `words` VALUES (12576, 'Rather than judging the disciples too harshly, we would do well to examine the reason for their slumbers.', 'adv. 严酷地， 无情地', '/\'hɑːrʃli | \'ha:ʃli/', 'harshly', 6);
INSERT INTO `words` VALUES (12577, NULL, 'n. 杂乱， 混乱； 杂烩菜', '/hæʃ/', 'hash', 6);
INSERT INTO `words` VALUES (12578, NULL, 'n. 激战', '/\'hæsl | \'hæs(ə)l/', 'hassle', 6);
INSERT INTO `words` VALUES (12579, 'Their departure was hastened by an abnormally cold winter.', 'v. 催促, 赶紧, 促进, 加速', '/\'heisən | \'heɪs(ə)n | \'hesn/', 'hasten', 6);
INSERT INTO `words` VALUES (12580, 'Donald had overturned a chair in his hasty departure.', 'adj. 急急忙忙的', '/\'heɪsti | \'hesti/', 'hasty', 6);
INSERT INTO `words` VALUES (12581, 'He stuck his head up through the hatch.', 'n. 孵化, 舱口, 舱口盖, (门、墙壁、地板上的)开口', '/hætʃ/', 'hatch', 6);
INSERT INTO `words` VALUES (12582, 'Would I feel better if I took a hatchet to her, just to end this nightmare?', 'n. 短柄斧', '/\'hætʃit | \'hætʃɪt/', 'hatchet', 6);
INSERT INTO `words` VALUES (12583, 'She called him on his haughtiness.', 'n. 傲慢, 不逊', '/\'hɔ:tinis/', 'haughtiness', 6);
