INSERT INTO `words` VALUES (12586, 'a haunting melody', 'adj. 常浮现于脑海中的, 不易忘怀的', '/\'hɔ:ntiŋ | \'hɔːntɪŋ | \'hɔntɪŋ/', 'haunting', 6);
INSERT INTO `words` VALUES (12587, 'Once, she had been put off by his hauteur.', 'n. 傲慢, 自大', '/əu\'tə: | əʊ\'tɜː/', 'hauteur', 6);
