INSERT INTO `words` VALUES (12591, 'She watched his every move like a hawk.', 'n. 鹰, 掠夺他人的人, 鹰派成员', '/hɔ:k | hɔːk | hɔk/', 'hawk', 6);
INSERT INTO `words` VALUES (12592, NULL, 'n. 携鹰打猎者, 叫卖小贩', '/\'hɔ:kə | \'hɔːkə | \'hɔkɚ/', 'hawker', 6);
INSERT INTO `words` VALUES (12593, 'It is clearly to sec that sway motion is increased with the increasing of the length of hawser.', 'n. 大缆, 曳船索, 系船索', '/\'hɔ:zə | \'hɔːzə | \'hɔzɚ/', 'hawser', 6);
INSERT INTO `words` VALUES (12594, 'That pile of rubbish is a fire hazard (= something that is likely to cause a fire ).', 'n. 冒险, 危险, 冒险的事', '/\'hæzəd | \'hæzɚd/', 'hazard', 6);
INSERT INTO `words` VALUES (12595, 'the disposal of hazardous waste', 'adj. 危险的, 冒险的, 碰运气的', '/\'hæzədəs | \'hæzɚdəs/', 'hazardous', 6);
INSERT INTO `words` VALUES (12596, 'hazy sunshine', 'adj. 朦胧的， 不清楚的', '/\'heɪzi | \'hezi/', 'hazy', 6);
INSERT INTO `words` VALUES (12597, 'chapter headings', 'n. 标题', '/\'hediŋ | \'hedɪŋ | \'hɛdɪŋ/', 'heading', 6);
INSERT INTO `words` VALUES (12598, 'Mortimer almost ran headlong into a patrol.', 'adj&adv. 轻率的/地， 迅猛的/地', '/\'hedlɔːŋ | \'hɛdlɔŋ/', 'headlong', 6);
INSERT INTO `words` VALUES (12599, NULL, 'adj. 刚愎自用的', '/\'hedstrɔːŋ | \'hɛdstrɔŋ/', 'headstrong', 6);
INSERT INTO `words` VALUES (12600, 'You\'ll soon find that when you follow through with these steps one by one, you make serious headway and before you know it, you\'ve achieved your success.', 'n. 进步， 进展', '/\'hedweɪ | \'hɛd,we/', 'headway', 6);
INSERT INTO `words` VALUES (12601, 'a heady combination of wine and brandy', 'adj. 任性的； 鲁莽的', '/\'hedi/', 'heady', 6);
INSERT INTO `words` VALUES (12602, 'It took three months for my arm to heal properly.', 'v. 治愈', '/hiːl | hil/', 'heal', 6);
