INSERT INTO `words` VALUES (12604, 'Give ye ear, and hear my voice; hearken, and hear my speech.', 'v. 倾听', '/\'hɑ:kən | \'hɑːk(ə)n | \'hɑrkən/', 'hearken', 6);
INSERT INTO `words` VALUES (12605, 'I wouldn’t take any notice of it – it’s just hearsay.', 'n. 谣言, 传闻, 道听途说', '/\'hiəsei | \'hɪəseɪ | \'hɪrse/', 'hearsay', 6);
INSERT INTO `words` VALUES (12606, 'The news heartened everybody.', 'v. 鼓励， 激励', '/\'hɑːrtn | \'hɑrtn/', 'hearten', 6);
INSERT INTO `words` VALUES (12607, 'a heartfelt apology', 'adj. 衷心的， 诚挚的', '/\'hɑːrtfelt | \'hɑrtfɛlt/', 'heartfelt', 6);
INSERT INTO `words` VALUES (12608, 'heartrending stories of children being taken from their parents', 'adj. 令人心碎的', '/\'hɑ:t,rendiŋ | \'hɑːrtrendɪŋ/', 'heartrending', 6);
INSERT INTO `words` VALUES (12609, 'This feather was picked up from the heath, the bird was not shot: we saw its nest in the winter, full of little skeletons.', 'n. [植]石南, 石南树丛', '/hi:θ | hiːθ | hiθ/', 'heath', 6);
INSERT INTO `words` VALUES (12610, 'They first set out to convert the heathen.', 'n. 不信上帝者, 异教徒, 野蛮人, 粗野的人', '/\'hi:ðən | \'hiːð(ə)n | \'hiðn/', 'heathen', 6);
INSERT INTO `words` VALUES (12611, 'Michael’s shoulders heaved with silent laughter.', 'v. 举起', '/hi:v | hiːv | hiv/', 'heave', 6);
INSERT INTO `words` VALUES (12612, 'God’s heavenly kingdom', 'adj. 天空的， 天上的', '/\'hevnli | \'hɛvnli/', 'heavenly', 6);
