INSERT INTO `words` VALUES (12614, NULL, 'v. 以麻梳梳理, 激烈质问, 诘问, 集中质问', '/\'hekl | \'hek(ə)l | \'hɛkl/', 'heckle', 6);
INSERT INTO `words` VALUES (12615, 'When comic Michael Richards was unnerved by an African American heckler at a comedy club several years ago, he responded with a racial-slur-laced tirade.', 'n. 激烈质问者', '/\'heklə/', 'heckler', 6);
INSERT INTO `words` VALUES (12616, 'the hectic flush on her cheeks', 'adj. 脸上发红, 发热的, 兴奋的, 狂热的, 肺病的', '/\'hektik | \'hektɪk | \'hɛktɪk/', 'hectic', 6);
INSERT INTO `words` VALUES (12617, 'a hectoring tone of voice', 'n. 虚张声势的人,恃强凌弱的人', '/\'hektə | \'hɛktɚ/', 'hector', 6);
INSERT INTO `words` VALUES (12618, 'Gold is traditionally a hedge against inflation.', 'n. 树篱, 障碍物', '/hedʒ | hɛdʒ/', 'hedge', 6);
INSERT INTO `words` VALUES (12619, 'So she went in search of her hedgehog.', 'n. 猬', '/\'hedʒhɔɡ | \'hedʒ(h)ɒg | \'hɛdʒhɔɡ/', 'hedgehog', 6);
INSERT INTO `words` VALUES (12620, '...the life of hedonism that she embraced in her youth.', 'n. 快乐论, 快乐主义', '/\'hi:dəunizəm | \'hiːd(ə)nɪz(ə)m; \'he- | \'hidənɪzəm/', 'hedonism', 6);
INSERT INTO `words` VALUES (12621, 'He is at once a hedonist who preaches prudence and temperance, a theist who rejects divine intervention and the survival of the soul, and an atomist who upholds both mechanism and free will.', 'n. 享乐主义者', '/\'hiːdənɪst | \'hidənɪst/', 'hedonist', 6);
INSERT INTO `words` VALUES (12622, '...an eccentric and flamboyant nobleman with a hedonistic lifestyle.', 'adj. 快乐主义者的, 快乐论的, 快乐主义的', '/,hi:də\'nistik | ,hedə\'nɪstɪk; ,hiːdə\'nɪstɪk | ,hidə\'nɪstɪk/', 'hedonistic', 6);
INSERT INTO `words` VALUES (12623, 'The government was taking little heed of these threats.', 'n. 注意, 留意', '/hi:d | hiːd | hid/', 'heed', 6);
INSERT INTO `words` VALUES (12624, 'black boots with high heels', 'n. 脚后跟, 踵, 跟部', '/hi:l | hiːl | hil/', 'heel', 6);
INSERT INTO `words` VALUES (12625, 'a tall hefty man', 'adj. 重的, 肌肉发达的', '/\'hefti | \'heftɪ | \'hɛfti/', 'hefty', 6);
INSERT INTO `words` VALUES (12626, 'The Beijing model in this context seems like a natural counterweight to America’s ideological hegemony.', 'n. 霸权', '/hi\'ɡeməni, hi\'dʒem- | hɪ\'dʒemənɪ; -\'ge- | hɪ\'dʒɛmoni/', 'hegemony', 6);
INSERT INTO `words` VALUES (12627, 'a heinous crime', 'adj. 可憎的, 极恶的', '/\'hainəs | \'heɪnəs; \'hiːnəs | \'henəs/', 'heinous', 6);
INSERT INTO `words` VALUES (12628, 'Jonson was his political heir as leader of the party.', 'n. 继承人, 后嗣', '/εə | eə | ɛr/', 'heir', 6);
INSERT INTO `words` VALUES (12629, '...the heiress to a jewellery empire.', 'n. 女性继承人', '/\'εəris | \'eərɪs; eə\'res/', 'heiress', 6);
INSERT INTO `words` VALUES (12630, 'They are stabilized in a helical shape that stays active longer in the body.', 'adj. 螺旋状的', '/\'helikəl | \'helɪk(ə)l; \'hiː- | \'hɛlɪkl/', 'helical', 6);
INSERT INTO `words` VALUES (12631, NULL, 'n. [植] 向日葵, 天芥菜属植物, 该植物的花香, 淡紫色', '/\'hi:liətrəup, \'he- | \'hiːlɪətrəʊp; \'hel- | \'hɛlɪətrop/', 'heliotrope', 6);
INSERT INTO `words` VALUES (12632, 'With him at the helm, we are a hundred percent safe crossing these treacherous rapids.', 'n. 舵', '/helm | hɛlm/', 'helm', 6);
INSERT INTO `words` VALUES (12633, 'The Sword split the Knight\'s helmet and bit him fatally.', 'n. 头盔, 钢盔', '/\'helmit | \'helmɪt | \'hɛlmɪt/', 'helmet', 6);
INSERT INTO `words` VALUES (12634, NULL, 'n. 舵手', '/\'helmzmən | \'hɛlmzmən/', 'helmsman', 6);
INSERT INTO `words` VALUES (12635, 'For to be illegals would create what in Europe is called a “helot” population, helots in ancient Greece having had an ill-defined intermediate status between slaves and free citizens.', 'n. （古希腊斯巴达的）奴隶', '/\'helət/', 'helot', 6);
