INSERT INTO `words` VALUES (12637, NULL, 'n. 柄', '/helv | hɛlv/', 'helve', 6);
INSERT INTO `words` VALUES (12638, 'She lifted the hem of her dress and brushed her knees.', 'n. 边, 缘, 摺边', '/hem | hɛm/', 'hem', 6);
