INSERT INTO `words` VALUES (12640, 'a henpecked husband', 'adj. 惧内的', '/\'henpekt/', 'henpecked', 6);
INSERT INTO `words` VALUES (12641, 'Lead can cause a wide range of disorders, including anaemia and hepatic and neurological disorders and food can be a major route of exposure.', 'adj. 肝的', '/hi\'pætik | hɪ\'pætɪk/', 'hepatic', 6);
INSERT INTO `words` VALUES (12642, 'What is hepatitis?', 'n. [医]肝炎', '/,hepə\'taitis | ,hepə\'taɪtɪs | ,hɛpə\'taɪtɪs/', 'hepatitis', 6);
INSERT INTO `words` VALUES (12643, 'a bowl of daffodils, the first bright heralds of spring', 'n. 使者, 传令官, 通报者, 先驱, 预兆', '/\'her(ə)ld | \'hɛrəld/', 'herald', 6);
INSERT INTO `words` VALUES (12644, 'To their surprise, Ms Sagot and Dr Stevens found that all four of the most sociable species are among those forced to use herbaceous plants, and thus to build ramshackle homes.', 'adj. 草本的, 似绿叶的', '/hə:\'beiʃəs, ə:- | hɜː\'beɪʃəs | ɝ\'beʃəs/', 'herbaceous', 6);
INSERT INTO `words` VALUES (12645, '\" Cornett\'s attorney, Jack Johnston, said the tooth \"looks like it would be from a herbivorous rodent of some type.', 'adj. 食草的', '/hə:\'bivərəs, \'ə:bivərəs | hɜː\'bɪvərəs | \'hɝbɪvərəs/', 'herbivorous', 6);
INSERT INTO `words` VALUES (12646, 'Chobe is also renowned for its large herds of elephant and buffalo.', 'n. 兽群, 牧群', '/hə:d | hɜːd | hɝd/', 'herd', 6);
INSERT INTO `words` VALUES (12647, 'You don\'t need a humanistic education in order to become a herdsman.', 'n. 牧者, 牧人', '/\'hə:dzmən | \'hɜːdzmən | \'hɝdzmən/', 'herdsman', 6);
INSERT INTO `words` VALUES (12648, 'a hereditary peer', 'adj. 祖传的， 世袭的； 遗传的', '/hə\'redɪteri | hə\'rɛdə\'tɛri/', 'hereditary', 6);
INSERT INTO `words` VALUES (12649, 'He was executed for heresy.', 'n. 异端, 异教', '/\'herəsi | \'herɪsɪ | \'hɛrəsi/', 'heresy', 6);
INSERT INTO `words` VALUES (12650, 'Cranmer was put to death as a heretic.', 'n. 异教徒, 异端者', '/\'herətik | \'herɪtɪk | \'hɛrətɪk/', 'heretic', 6);
INSERT INTO `words` VALUES (12651, 'I made the then heretical suggestion that it might be cheaper to design new machines.', 'adj. 异教的, 异端的', '/hi\'retikəl | hɪ\'retɪk(ə)l | həˈrɛtɪkəl/', 'heretical', 6);
INSERT INTO `words` VALUES (12652, 'the importance of preserving the national heritage', 'n. 遗产, 继承权, 传统', '/\'heritidʒ | \'herɪtɪdʒ | \'hɛrɪtɪdʒ/', 'heritage', 6);
INSERT INTO `words` VALUES (12653, 'Its film industry operates in its own curiously hermetic way.', 'adj. 密封的, 与外界隔绝的', '/hə:\'metik | hɜː\'metɪk | hɝ\'mɛtɪk/', 'hermetic', 6);
INSERT INTO `words` VALUES (12654, 'I\'ve spent the past ten years living like a hermit.', 'n. 隐士, 隐居者', '/\'hə:mit | \'hɜːmɪt | \'hɝmɪt/', 'hermit', 6);
INSERT INTO `words` VALUES (12655, NULL, 'n. 偏僻的寺院', '/\'hə:mitidʒ | \'hɜːmɪtɪdʒ | \'hɝmɪtɪdʒ/', 'hermitage', 6);
INSERT INTO `words` VALUES (12656, 'America’s present need is not heroics, but calm diplomacy.', 'n. 装腔作势的豪言壮语', NULL, 'heroics', 6);
INSERT INTO `words` VALUES (12657, 'Gail gave me a hesitant little smile.', 'adj. 犹豫的', '/\'hezɪtənt | \'hɛzɪtənt/', 'hesitant', 6);
INSERT INTO `words` VALUES (12658, NULL, 'adj. 非正统的, 异端的', '/\'hetərəudɔks | \'het(ə)rə(ʊ)dɒks | \'hɛtərə\'dɑks/', 'heterodox', 6);
INSERT INTO `words` VALUES (12659, 'Despite his heterodoxy, faults, and weaknesses, Clare was a man with a conscience.', 'n. 非正统, 异端, 异说', '/\'hetərəu,dɔksi | \'hetərəʊ,dɒksɪ | \'hɛtərə,dɑksi/', 'heterodoxy', 6);
INSERT INTO `words` VALUES (12660, 'a heterogeneous collection of buildings', 'adj. 不同种类的异类的', '/,hetərəu\'dʒi:njəs | ,het(ə)rə(ʊ)\'dʒiːnɪəs; -\'dʒen- | \'hɛtərə\'dʒinɪəs/', 'heterogeneous', 6);
INSERT INTO `words` VALUES (12661, 'hewn stone', 'v. 砍', '/hju: | hjuː | hju/', 'hew', 6);
INSERT INTO `words` VALUES (12662, 'He presses the bolt against a small hexagon tattooed on his forearm. The sizes match.', 'n. 六角形, 六边形', '/\'heksəɡən | \'heksəg(ə)n | \'hɛksəɡɑn/', 'hexagon', 6);
INSERT INTO `words` VALUES (12663, NULL, 'int. 喜悦、惊奇时所发声音', '/\'heidei | \'heɪdeɪ | \'hede/', 'heyday', 6);
INSERT INTO `words` VALUES (12664, 'Diplomatic efforts to reach a settlement resume today after a two-week hiatus.', 'n. 裂缝, 脱落', '/hai\'eitəs | haɪ\'eɪtəs | haɪ\'etəs/', 'hiatus', 6);
