INSERT INTO `words` VALUES (12667, 'Our Galapagos tortoise are responsive to bright coloured, edible flowers and fruit, such as roses, hibiscus, grapes and watermelon.', 'n. 芙蓉属的植物', '/hai\'biskəs, hi- | hɪ\'bɪskəs/', 'hibiscus', 6);
