INSERT INTO `words` VALUES (12669, 'hidebound reactionaries', 'adj. 营养不良的, 量小的, 死板的', '/\'haidbaund | \'haɪdbaʊnd/', 'hidebound', 6);
INSERT INTO `words` VALUES (12670, 'Every article on the breakfast table was fetched away with a hideous crash.', 'v. 骇人听闻的, 可怕的', '/\'hidiəs | \'hɪdɪəs/', 'hideous', 6);
INSERT INTO `words` VALUES (12671, NULL, 'v. 疾走， 快速', '/haɪ/', 'hie', 6);
INSERT INTO `words` VALUES (12672, 'We need two new Classes at either end of the inheritance hierarchy to do this.', 'n. 层次层级', '/\'haiə,rɑ:ki | \'haɪərɑːkɪ | \'haɪərɑrki/', 'hierarchy', 6);
INSERT INTO `words` VALUES (12673, 'Initially the patterns I used were hieroglyph like symbols.', 'n. 象形文字, 图画文字', '/\'haiərəuɡlif | \'haɪ(ə)rəglɪf | \'haɪərəɡlɪf/', 'hieroglyph', 6);
INSERT INTO `words` VALUES (12674, 'An ancient mayan city of southern mexico southeast of villahermosa. the temple of inscriptions is noted for its hieroglyphic tablets.', 'n. 象形文字', '/ˌhaɪərə\'glɪfɪk | ,haɪərə\'glɪfɪk/', 'hieroglyphic', 6);
INSERT INTO `words` VALUES (12675, NULL, 'n. <美口>（自以为）有高度文化修养的人, 知识分子, 卖弄知识的人', '/\'haibrau | \'haɪbraʊ/', 'highbrow', 6);
INSERT INTO `words` VALUES (12676, 'a hike in the woods', 'v. 抬高，提高; n. 徒步旅行', '/haɪk/', 'hike', 6);
INSERT INTO `words` VALUES (12677, 'The focus is solely on the shirts and the hilarious design.', 'adj. 欢闹的', '/hi\'lεəriəs | hɪ\'leərɪəs | hɪ\'lɛrɪəs/', 'hilarious', 6);
INSERT INTO `words` VALUES (12678, 'Eva joined in the hilarity as much as anyone.', 'n. 欢闹', '/hi\'lærəti | hɪ\'lærɪtɪ | hɪ\'lærəti/', 'hilarity', 6);
INSERT INTO `words` VALUES (12679, NULL, 'n. 山地内部的贫农, 山地人', '/\'hil,bili | \'hɪlbɪlɪ | \'hɪlbɪli/', 'hillbilly', 6);
INSERT INTO `words` VALUES (12680, 'The golden hilt is ornamented with three large emeralds, topped by a golden watch with an emerald lid.', 'n. 柄, 刀把', '/hilt | hɪlt/', 'hilt', 6);
INSERT INTO `words` VALUES (12681, 'the hinder parts', 'adj. 后面的', '/\'hində | \'hɪndə | \'hɪndɚ/', 'hinder', 6);
INSERT INTO `words` VALUES (12682, 'A degree is more of a hindrance than a help in British industry.', 'n. 妨碍, 障碍', '/\'hindrəns | \'hɪndr(ə)ns | \'hɪndrəns/', 'hindrance', 6);
INSERT INTO `words` VALUES (12683, 'Your arm should hinge from the shoulder.', 'n. （门、盖等的）铰链, 枢纽, 关键', '/hɪn(d)ʒ | hɪndʒ/', 'hinge', 6);
INSERT INTO `words` VALUES (12684, 'the rural hinterland', 'n. 内地, 穷乡僻壤, 内地贸易区, 腹地', '/\'hintəlænd | \'hɪntəlænd | \'hɪntɚlænd/', 'hinterland', 6);
INSERT INTO `words` VALUES (12685, 'Still, now we knew for sure where whales came from and that the hippopotamus theory wasn\'t complete science fiction.', 'n. 河马', '/ˌhɪpəˈpɒtəməs | ˌhɪpəˈpɑtəməs/', 'hippopotamus', 6);
INSERT INTO `words` VALUES (12686, 'So what do you guys think — gay or maybe just the world\'s first (straight) hipster?', 'n. 世面灵通的人', '/\'hipstə | hɪpstə | \'hɪpstɚ/', 'hipster', 6);
INSERT INTO `words` VALUES (12687, 'Awarded to Manuel Barbeito at the Industrial Health and Safety Office in Maryland for scientific studies that found microbes cling to beards, making more hirsute men a potential laboratory hazard.', 'adj. 多毛的, 有粗毛的', '/\'hə:sju:t | \'hɜːsjuːt/', 'hirsute', 6);
INSERT INTO `words` VALUES (12688, 'The tyres of Lenny\'s bike hissed over the wet pavement as he slowed down.', 'v. 嘶嘶作声, 用嘘声表示', '/his | hɪs/', 'hiss', 6);
INSERT INTO `words` VALUES (12689, 'He was also partly responsible for the identification of the polio virus, and made numerous contributions to immunology, histology and anatomy.', 'n. [生物]组织学', '/his\'tɔlədʒi | hɪ\'stɒlədʒɪ | hɪ\'stɑlədʒi/', 'histology', 6);
INSERT INTO `words` VALUES (12690, 'Dorothea let out a histrionic groan.', 'adj. 戏剧的', '/,histri\'ɔnik | ,hɪstrɪ\'ɒnɪk | \'hɪstrɪ\'ɑnɪk/', 'histrionic', 6);
INSERT INTO `words` VALUES (12691, 'These squabbling Tolstoys and their stilted histrionics were conceited and exasperating.', 'n. 演戏, 表演', '/,histri\'ɔniks | ,hɪstrɪ\'ɒnɪks/', 'histrionics', 6);
INSERT INTO `words` VALUES (12692, 'The whole show went without a hitch .', 'n. 猛拉, 急推, 蹒跚, 故障', '/hitʃ | hɪtʃ/', 'hitch', 6);
INSERT INTO `words` VALUES (12693, 'That suggests the neurological changes which gave rise to humanity may have predated the brain\'s expansion—an event that had, hitherto, been regarded as crucial to the emergence of humans.', 'adv. 到目前为止', '/ˌhɪðər\'tuː | ,hɪðɚ\'tu/', 'hitherto', 6);
INSERT INTO `words` VALUES (12694, 'The most important member of any hive is the queen bee.', 'n. 蜂房, 蜂箱, 闹市', '/haiv | haɪv/', 'hive', 6);
INSERT INTO `words` VALUES (12695, 'families who hoarded food during the strike', 'v. 储藏', '/hɔ:d | hɔːd | hɔrd/', 'hoard', 6);
INSERT INTO `words` VALUES (12696, 'He was hoarse from laughing.', 'adj. 嘶哑的', '/hɔ:s | hɔːs | hɔrs/', 'hoarse', 6);
INSERT INTO `words` VALUES (12697, 'Not that hoary old chestnut (= old idea, joke, remark etc ) again.', 'adj. 灰白的, （因年迈而）头发灰白的, 古代的, 久远的', '/\'hɔ:ri | \'hɔːrɪ | \'hɔri/', 'hoary', 6);
INSERT INTO `words` VALUES (12698, 'a bomb hoax', 'v. 愚弄', '/həuks | həʊks | hoks/', 'hoax', 6);
INSERT INTO `words` VALUES (12699, 'The Spain midfielder missed the midweek Champions League victory over Porto because of the hamstring problem which had seen him hobble out of the win against Burnley.', 'v. 蹒跚', '/\'hɔbl | \'hɒb(ə)l | \'hɑbl/', 'hobble', 6);
INSERT INTO `words` VALUES (12700, 'You know, a hobgoblin.', 'n. 妖怪, 怪物', '/\'hɔbɡɔblin | \'hɒbgɒblɪn/', 'hobgoblin', 6);
INSERT INTO `words` VALUES (12701, 'This gave Bill an opportunity to hobnob with the company\'s president, board chairman, and leading executives.', 'v. 对酌, 共饮, (亲切)交谈', '/\'hɔbnɔb | \'hɒbnɒb | \'hɑbnɑb/', 'hobnob', 6);
INSERT INTO `words` VALUES (12702, 'I would rather hoe in the garden than run on the playground.', 'n. 锄头', '/hou | ho/', 'hoe', 6);
INSERT INTO `words` VALUES (12703, 'Give me a hoist onto your shoulders.', 'n. 提升间, 升起', '/hɔist | hɒɪst | hɔɪst/', 'hoist', 6);
INSERT INTO `words` VALUES (12704, 'I realized that the woman had a hold over my father.', 'n. 把握, 把持力, 柄, 控制, 监禁, 掌握, 货舱', '/həʊld | hold/', 'hold', 6);
INSERT INTO `words` VALUES (12705, NULL, 'n. 洞, 窟窿, 山谷', '/\'hɔləu | \'hɒləʊ | \'hɑlo/', 'hollow', 6);
INSERT INTO `words` VALUES (12706, 'A nuclear holocaust seemed a very real possibility in the \'50s.', 'n. 大毁灭, 大屠杀', '/\'hɔləkɔ:st | \'hɒləkɔːst | \'hɑləkɔst/', 'holocaust', 6);
INSERT INTO `words` VALUES (12707, NULL, 'n. 亲笔文件, [律] 亲笔信, [物] 全息图', '/\'hɔləuɡrɑ:f, -ɡræf | \'hɒləgrɑːf | \'hɑləɡræf/', 'holograph', 6);
INSERT INTO `words` VALUES (12708, 'So while fleeing vehicles sped away from Tatiana\'s Tavern, Jack drew the Browning Hi-Power from his shoulder holster and moved cautiously toward the building.', 'n. 手枪用的皮套', '/\'həulstə | \'həʊlstə; \'hɒl- | \'holstɚ/', 'holster', 6);
INSERT INTO `words` VALUES (12709, 'The film pays homage to Martin Scorsese’s ‘Mean Streets’.', 'n. 敬意', '/\'hɔmidʒ | \'hɒmɪdʒ | \'hɑmɪdʒ/', 'homage', 6);
INSERT INTO `words` VALUES (12710, 'Mrs Keane is a comfortable, homely person.', 'adj. 家常的', '/\'həumli | \'həʊmlɪ | \'homli/', 'homely', 6);
INSERT INTO `words` VALUES (12711, 'homemade cake', 'adj. 自制的， 家里做的', '/ˌhəum\'meid | \'hom\'med/', 'homemade', 6);
INSERT INTO `words` VALUES (12712, 'Do you think there\'s something to homeopathy as well?', 'n. 同种疗法', '/,həumi\'ɔpəθi | ,həʊmɪ\'ɒpəθɪ; hɒm- | ,homɪ\'ɑpəθi/', 'homeopathy', 6);
INSERT INTO `words` VALUES (12713, 'The book is simple homespun philosophy.', 'adj. 朴素的； 家织的', '/\'houmspʌn | \'homspʌn/', 'homespun', 6);
INSERT INTO `words` VALUES (12714, 'These programs develop students\' understanding of Hebrew Scripture and its commentary tradition, Jewish philosophy and ethics, liturgical traditions, counseling, and homiletics.', 'n. 说教术', '/,hɔmi\'letiks | ,hɒmɪ\'letɪks | ,hɑmə\'lɛtɪks/', 'homiletics', 6);
INSERT INTO `words` VALUES (12715, 'The theory is based on the assumption of labor homogeneity.', 'n. 同种， 同质', '/ˌhɑːmədʒə\'niːəti | ,hɑmədʒə\'niəti/', 'homogeneity', 6);
INSERT INTO `words` VALUES (12716, 'The unemployed are not a homogeneous group.', 'adj. 同类的, 相似的, 均一的, 均匀的', '/,hɒmə(ʊ)\'dʒiːnɪəs; -\'dʒen- | ,homə\'dʒinɪəs/', 'homogeneous', 6);
INSERT INTO `words` VALUES (12717, 'plans to homogenize the various school systems', 'v. 均质化', '/hɔ\'mɔdʒənaiz | hə\'mɒdʒənaɪz | ho\'mɑdʒə,naɪz/', 'homogenize', 6);
INSERT INTO `words` VALUES (12718, 'In the third chapter, identical words have been divided into synonymy and homograph from semanteme.', 'n. 同形异义字', '/\'hɔməuɡrɑ:f, -ɡræf | \'hɒməgrɑːf; \'həʊm- | \'hɑməɡræf/', 'homograph', 6);
INSERT INTO `words` VALUES (12719, NULL, 'v. 承认, 同意, [民法]确认, 批准', '/hə\'mɒləgeɪt | hɔ\'mɔləɡeit/', 'homologate', 6);
INSERT INTO `words` VALUES (12720, 'He set about honing his skills as a draughtsman.', 'n. （细）磨（刀）石, 油石, [方言]抱怨, 想念', '/həun | həʊn | hon/', 'hone', 6);
INSERT INTO `words` VALUES (12721, NULL, 'n. 雁叫声', '/hɔŋk | \'hɒŋk | hɑŋk/', 'honk', 6);
INSERT INTO `words` VALUES (12722, NULL, 'n. （对习俗或法律上不应取酬的服务的）酬劳（或答谢）', '/,ɔnə\'rεəriəm | ,ɒnə\'reərɪəm | ,ɑnə\'rɛrɪəm/', 'honorarium', 6);
INSERT INTO `words` VALUES (12723, 'She threw back the hood of her cloak.', 'n. 头巾, 兜帽, 车蓬, 引擎罩', '/hud | hʊd/', 'hood', 6);
INSERT INTO `words` VALUES (12724, NULL, 'n. 厄运； 招来不幸的人', '/\'huːduː | \'hudu/', 'hoodoo', 6);
INSERT INTO `words` VALUES (12725, 'People expect others to be honest, which is why conmen find it so easy to hoodwink people.', 'v. 遮眼, 欺骗, 蒙蔽', '/\'hudwiŋk | \'hʊdwɪŋk/', 'hoodwink', 6);
INSERT INTO `words` VALUES (12726, 'The horses\' hooves often could not get a proper grip.', 'n. 蹄', '/hu:f | huːf | huf/', 'hoof', 6);
INSERT INTO `words` VALUES (12727, 'Tom hung his coat on the hook behind the door.', 'n. 钩, 吊钩', '/huk | hʊk/', 'hook', 6);
INSERT INTO `words` VALUES (12728, 'a hooked nose', 'adj. 钩状的', '/hukt | \'hʊkt | hʊkt/', 'hooked', 6);
INSERT INTO `words` VALUES (12729, 'football hooligans', 'n. 小流氓', '/\'hu:liɡən | \'huːlɪg(ə)n | \'hulɪɡən/', 'hooligan', 6);
INSERT INTO `words` VALUES (12730, 'A boy came towards them, rolling an iron hoop.', 'n. 箍, 铁环, 戒指, 篮', '/hu:p | huːp | hup/', 'hoop', 6);
INSERT INTO `words` VALUES (12731, NULL, 'n. 游牧部落', '/hɔ:d | hɔːd | hɔrd/', 'horde', 6);
INSERT INTO `words` VALUES (12732, 'In the distance, the dot of a boat appeared on the horizon.', 'n. 地平线', '/hə\'raizən | hə\'raɪz(ə)n | hə\'raɪzn/', 'horizon', 6);
INSERT INTO `words` VALUES (12733, 'a horizontal surface', 'adj. 水平的', '/ˌhɔːrə\'zɑːntl | \'hɔrə\'zɑntl/', 'horizontal', 6);
INSERT INTO `words` VALUES (12734, '...the male sex hormone testosterone.', 'n. 荷尔蒙, 激素', '/\'hɔ:məun | \'hɔːməʊn | \'hɔrmon/', 'hormone', 6);
INSERT INTO `words` VALUES (12735, 'He sounded the car horn.', 'n. (牛、羊等的)角, 喇叭, 触角', '/hɔ:n | hɔːn | hɔrn/', 'horn', 6);
INSERT INTO `words` VALUES (12736, 'The appearance of radio-controlled clock is a revolution in the history of the horology.', 'n. 钟表学', '/hɔ\'rɔlədʒi | hɒ\'rɒlədʒɪ | hə\'rɑlədʒi/', 'horology', 6);
INSERT INTO `words` VALUES (12737, 'a horrendous experience', 'adj. 可怕的', '/hɔ\'rendəs | hɒ\'rendəs/', 'horrendous', 6);
INSERT INTO `words` VALUES (12738, 'His injuries were horrific.', 'adj. 可怕的', '/hə\'rɪfɪk/', 'horrific', 6);
INSERT INTO `words` VALUES (12739, 'You should have seen the look of horror on his face.', 'n. 惊骇, 恐怖, 惨事, 极端厌恶', '/\'hɔrə | \'hɒrə | \'hɔrɚ/', 'horror', 6);
INSERT INTO `words` VALUES (12740, 'The print is a hortative drawing. It tells us that everybody has shortcoming and the power of the individual is smaller than group.', 'adj. 劝告的, 鼓励的, 忠告的, 奖励的', '/\'hɔ:tətiv | \'hɔːtətɪv/', 'hortative', 6);
INSERT INTO `words` VALUES (12741, 'The area has a long tradition of horticulture.', 'n. 园艺', '/\'hɔ:tikʌltʃə | \'hɔːtɪ,kʌltʃə | \'hɔrtɪ\'kʌltʃɚ/', 'horticulture', 6);
INSERT INTO `words` VALUES (12742, 'Some prisoners have also been beaten with lengths of rubber hosepipe. Some have been burnt with cigarette ends and some have been put to what Americans call the \"water torture\".', 'n. 橡胶软管', '/\'həuzpaip | \'hozpaɪp/', 'hosepipe', 6);
INSERT INTO `words` VALUES (12743, 'The local people were very kind and hospitable.', 'adj. 热情好客的； 易接受的', '/hɑː\'spɪtəbl | hɑ\'spɪtəbl/', 'hospitable', 6);
INSERT INTO `words` VALUES (12744, 'Thanks for your hospitality over the past few weeks.', 'n. 好客, 宜人, 盛情', '/,hɔspi\'tæləti | hɒspɪ\'tælɪtɪ | ,hɑspɪ\'tæləti/', 'hospitality', 6);
INSERT INTO `words` VALUES (12745, 'Our host greeted us at the door.', 'n. 主人, 旅馆招待 许多', '/həust | həʊst | host/', 'host', 6);
INSERT INTO `words` VALUES (12746, 'The group are holding two tourists hostage (= keeping them as hostages ) .', 'n. 人质, 抵押品', '/\'hɔstidʒ | \'hɒstɪdʒ | \'hɑstɪdʒ/', 'hostage', 6);
INSERT INTO `words` VALUES (12747, 'Southampton fans gave their former coach a hostile reception .', 'adj. 敌对的, 敌方的', '/\'hɔstail, -təl | \'hɒstaɪl | ˈhɑstəl/', 'hostile', 6);
INSERT INTO `words` VALUES (12748, 'The reform program was greeted with hostility by conservatives.', 'n. 敌意, 恶意, 不友善, 敌对, 对抗, 反对', '/hɔ\'stiləti | hɒ\'stɪlɪtɪ | hɑ\'stɪləti/', 'hostility', 6);
INSERT INTO `words` VALUES (12749, 'a hot curry', 'adj. 热的, 热情的, 辣的, 激动的, 紧迫的, 节奏强的', '/hɔt | hɒt | hɑt/', 'hot', 6);
INSERT INTO `words` VALUES (12750, 'He is hot-tempered and equally hot-tempered is his wife.', 'adj. 性急的， 易怒的， 暴躁的', '/ˌhɔt\'tempərd | \'hɔt,tempəd/', 'hot-tempered', 6);
INSERT INTO `words` VALUES (12751, 'The university was a hotbed of radical protest.', 'n. 温床', '/\'hɔtbed | \'hɒtbed | \'hɑtbɛd/', 'hotbed', 6);
INSERT INTO `words` VALUES (12752, 'Rainey\'s chief interest in life is hunting with hounds.', 'n. 猎犬', '/haund | haʊnd/', 'hound', 6);
INSERT INTO `words` VALUES (12753, 'They lived in a squalid hovel for the next five years.', 'n. (简陋而不适于居住的)小屋, 杂物间, 家畜小屋', '/\'hɔvəl, \'hʌ- | \'hɒv(ə)l | \'hʌvl/', 'hovel', 6);
INSERT INTO `words` VALUES (12754, 'After rising through the air it stops to hover outside the window of a building several storeys high.', 'v. 盘旋', '/\'hɔvə, \'hʌ- | \'hɒvə | \'hʌvɚ/', 'hover', 6);
INSERT INTO `words` VALUES (12755, 'The dogs howled all night.', 'v. 嚎叫, 怒吼, 嚎啕大哭, 喝住, 号叫', '/haul | haʊl/', 'howl', 6);
INSERT INTO `words` VALUES (12756, 'I felt as if I had made an outrageous howler.', 'n. 大声叫喊者', '/\'haulə | \'haʊlə | \'haʊlɚ/', 'howler', 6);
INSERT INTO `words` VALUES (12757, NULL, 'n. 爱喧闹的顽皮女孩', '/\'hɔidən | \'hɒɪd(ə)n | \'hɔɪdn/', 'hoyden', 6);
INSERT INTO `words` VALUES (12758, 'the commercial hub of the region', 'n. 毂, 木片, 中心', '/hʌb/', 'hub', 6);
INSERT INTO `words` VALUES (12759, 'the hubbub from the market', 'n. 吵闹声, 呐喊声, 叫嚷声', '/\'hʌbʌb/', 'hubbub', 6);
INSERT INTO `words` VALUES (12760, '...a tale of how an honourable man pursuing honourable goals was afflicted with hubris and led his nation toward catastrophe.', 'n. 骄傲 , 傲慢, （狂妄自大）', '/\'hju:bris | \'hjuːbrɪs/', 'hubris', 6);
INSERT INTO `words` VALUES (12761, NULL, 'n. 小贩', '/\'hʌkstə | \'hʌkstɚ/', 'huckster', 6);
INSERT INTO `words` VALUES (12762, 'We lay huddled together for warmth.', 'v. 拥挤, 卷缩, 草率从事, 挤作一团', '/\'hʌdl | \'hʌd(ə)l/', 'huddle', 6);
INSERT INTO `words` VALUES (12763, 'a golden hue', 'n. 色调, 样子, 颜色, 色彩, 叫声, 大声叫喊, 大声反对', '/hjuː/', 'hue', 6);
INSERT INTO `words` VALUES (12764, NULL, 'adj. 生气的, 不高兴的, 发怒的, 傲慢的', '/\'hʌfiʃ | \'hʌfɪʃ/', 'huffish', 6);
INSERT INTO `words` VALUES (12765, 'Some customers get huffy when you ask them for their ID.', 'adj. 发怒的', '/\'hʌfi | \'hʌfɪ/', 'huffy', 6);
INSERT INTO `words` VALUES (12766, 'a hulk of a man', 'n. 笨重的船, 废船', '/hʌlk/', 'hulk', 6);
INSERT INTO `words` VALUES (12767, 'Two hulking figures guarded the entrance of the club.', 'adj. 笨重的, 粗陋的', '/\'hʌlkiŋ | \'hʌlkɪŋ/', 'hulking', 6);
INSERT INTO `words` VALUES (12768, 'The hull had suffered extensive damage to the starboard side.', 'n. (果实等的)外壳, 船体, Hull赫尔', '/hʌl/', 'hull', 6);
INSERT INTO `words` VALUES (12769, 'She looked up to see what all the hullabaloo was about.', 'n. 喧嚣, 喧哗, 吵闹（声）, （混乱, 骚动）声', '/,hʌləbə\'lu: | ,hʌləbə\'luː/', 'hullabaloo', 6);
INSERT INTO `words` VALUES (12770, 'the campaign for the humane treatment of criminals', 'adj. 仁慈的', '/hju:\'mein | hjʊ\'meɪn | hju\'men/', 'humane', 6);
INSERT INTO `words` VALUES (12771, 'Religious values can often differ greatly from humanistic morals.', 'adj. 人性的； 人文主义的', '/ˌhjuːmə\'nɪstɪk | ,hjʊmən\'ɪstɪk/', 'humanistic', 6);
INSERT INTO `words` VALUES (12772, 'He wants both sides, and their backers, to focus solely on this humanitarian issue for now.', 'n. 人道主义者', '/hjuːˌmænɪ\'teriən | hju,mænɪ\'tɛrɪən/', 'humanitarian', 6);
INSERT INTO `words` VALUES (12773, 'We want a clean healthy environment for all humanity .', 'n. 人性, 人类, 博爱, 仁慈', '/hju:\'mænəti | hjʊ\'mænɪtɪ | hjʊ\'mænəti/', 'humanity', 6);
INSERT INTO `words` VALUES (12774, 'a modest and humble man', 'adj. 卑下的, 微贱的, 谦逊的, 粗陋的', '/\'hʌmbl/', 'humble', 6);
INSERT INTO `words` VALUES (12775, '...her lawyer husband, trapped in a humdrum but well-paid job.', 'adj. 单调的', '/\'hʌmdrʌm/', 'humdrum', 6);
INSERT INTO `words` VALUES (12776, 'Tokyo is extremely humid in mid-summer.', 'adj. 充满潮湿的, 湿润的, 多湿气的', '/\'hju:mid | \'hjuːmɪd | \'hjumɪd/', 'humid', 6);
INSERT INTO `words` VALUES (12777, 'The room is kept at 72 degrees and 50% relative humidity.', 'n. 湿气, 潮湿, 湿度<美>沼泽中的肥沃高地', '/hju:\'midəti | hjʊ\'mɪdɪtɪ | hju\'mɪdəti/', 'humidity', 6);
INSERT INTO `words` VALUES (12778, 'Her boss humiliated her in front of all her colleagues.', 'v. 羞辱, 使丢脸, 耻辱', '/hju:\'milieit | hjʊ\'mɪlɪeɪt | hju\'mɪlɪet/', 'humiliate', 6);
INSERT INTO `words` VALUES (12779, '...a deep sense of humility.', 'n. 谦卑', '/hju:\'miləti | hjʊ\'mɪlɪtɪ | hju\'mɪləti/', 'humility', 6);
INSERT INTO `words` VALUES (12780, 'In a presumably posthumous voiceover, Bwana Beast says he would do it all again, in a hummingbird\'s heartbeat.', 'n. 蜂雀', '/\'hʌmiŋbə:d | \'hʌmɪŋbɜːd | \'hʌmɪŋbɝd/', 'hummingbird', 6);
INSERT INTO `words` VALUES (12781, NULL, 'n. 圆丘, 小丘, 山岗, 冰群（冰原上的）, <美>沼泽中的肥沃高地', '/\'hʌmək/', 'hummock', 6);
INSERT INTO `words` VALUES (12782, NULL, 'v. 纵容， 迁就', '/\'hjuːmər | \'hjʊmɚ/', 'humor', 6);
INSERT INTO `words` VALUES (12783, 'his humour and charm', 'n. 幽默, 诙谐', '/\'hju:mə | \'hjuːmə/', 'humour', 6);
INSERT INTO `words` VALUES (12784, 'The path goes over a large hump by a tree before running near a road.', 'n. 驼峰, 驼背, 小园丘, 峰丘', '/hʌmp/', 'hump', 6);
INSERT INTO `words` VALUES (12785, 'I had a hunch that Susan and I would work well together.', 'n. 圆形之隆起物, 肉峰, 预感, 大块', '/hʌntʃ | hʌn(t)ʃ/', 'hunch', 6);
INSERT INTO `words` VALUES (12786, '...a thick hunk of bread.', 'n. <俗>大块', '/hʌŋk/', 'hunk', 6);
INSERT INTO `words` VALUES (12787, NULL, 'v. 盘坐', '/\'hʌŋkə | \'hʌŋkɚ/', 'hunker', 6);
INSERT INTO `words` VALUES (12788, 'Finding enough money for the project was the first hurdle.', 'n. 篱笆, 栏, 障碍, 跨栏, 活动篱笆', '/\'hə:dl | \'hɜːd(ə)l | \'hɝdl/', 'hurdle', 6);
INSERT INTO `words` VALUES (12789, 'Demonstrators were hurling bricks through the windows.', 'n. <俚>[棒球]用力或猛烈的投掷', '/hə:l | hɜːl | hɝl/', 'hurl', 6);
INSERT INTO `words` VALUES (12790, 'The hurricane devastated a large section of the coast.', 'n. 飓风, 狂风', '/\'hʌrikən | \'hʌrɪk(ə)n; -keɪn | hʌrɪˌken/', 'hurricane', 6);
INSERT INTO `words` VALUES (12791, 'A pretty young girl came hurtling down the stairs.', 'v. 呼啸而过， 快速通过； 猛投， 用力投掷', '/\'hɜːrtl | \'hɝtl/', 'hurtle', 6);
INSERT INTO `words` VALUES (12792, NULL, 'v. 节省， 节约', '/\'hʌzbənd/', 'husband', 6);
INSERT INTO `words` VALUES (12793, 'animal husbandry', 'n. 管理', '/\'hʌzbəndri | \'hʌzbəndrɪ/', 'husbandry', 6);
INSERT INTO `words` VALUES (12794, 'Ella asked them to hush their voices.', 'v. 安静', '/hʌʃ/', 'hush', 6);
INSERT INTO `words` VALUES (12795, NULL, 'n. （果类或谷物的）外壳(通常用复数), 皮, 无价值之物', '/hʌsk/', 'husk', 6);
INSERT INTO `words` VALUES (12796, '‘Come quickly,’ she said in a husky whisper.', 'adj. 谷的, 像谷的, (声音)沙哑的, 嘶哑的', '/\'hʌski | \'hʌskɪ/', 'husky', 6);
INSERT INTO `words` VALUES (12797, NULL, 'n. 议员竞选演说坛, 选举程序', '/\'hʌstiŋz | \'hʌstɪŋz/', 'hustings', 6);
INSERT INTO `words` VALUES (12798, '...an insurance hustler.', 'n. 皮条客, 骗徒, 催促者', '/\'hʌslə | \'hʌslɚ/', 'hustler', 6);
INSERT INTO `words` VALUES (12799, 'Objective: To study the possibility of the amnion as hyaline cartilage cells scaffold in tissue - engineering.', 'adj. 透明的', '/\'haiəlain, -lin | \'haɪəlɪn; -iːn; -aɪn | \'haɪəlɪn/', 'hyaline', 6);
INSERT INTO `words` VALUES (12800, 'hybrid architecture', 'n. 杂种, 混血儿, 混合物', '/\'haibrid | \'haɪbrɪd/', 'hybrid', 6);
INSERT INTO `words` VALUES (12801, NULL, 'n. 消防栓, 消防龙头', '/\'haidrənt | \'haɪdr(ə)nt | \'haɪdrənt/', 'hydrant', 6);
INSERT INTO `words` VALUES (12802, '“The modeling of methane hydrate is frankly in its infancy,” but it seems “robust to conclude” that mankind could “melt a significant fraction of the methane hydrates in the ocean,” they wrote.', 'n. 氢氧化物', '/\'haidreit | \'haɪdreɪt | \'haɪdret/', 'hydrate', 6);
INSERT INTO `words` VALUES (12803, '\"Maybe a hyena chewed off the face soon after it died, \" White said.', 'n. [动]土狼, 鬣狗', '/hai\'i:nə | haɪ\'iːnə | haɪ\'inə/', 'hyena', 6);
INSERT INTO `words` VALUES (12804, 'the importance of personal hygiene', 'n. 卫生, 卫生学', '/\'haidʒi:n | \'haɪdʒiːn | \'haɪdʒin/', 'hygiene', 6);
INSERT INTO `words` VALUES (12805, '1 hygrometer (belonged to FitzRoy)', 'n. 湿度计', '/hai\'ɡrɔmitə | haɪ\'grɒmɪtə | haɪ\'grɑmətɚ/', 'hygrometer', 6);
INSERT INTO `words` VALUES (12806, 'Bentonite clay is also hygroscopic and absorbs water', 'adj. 吸湿的', '/,haiɡrə\'skɔpik | haɪgrə(ʊ)\'skɒpɪk | ,haɪgrə\'skɑpɪk/', 'hygroscopic', 6);
INSERT INTO `words` VALUES (12807, 'He liked to sing hymns as he worked.', 'n. 赞美诗, 圣歌', '/him | hɪm/', 'hymn', 6);
INSERT INTO `words` VALUES (12808, 'We are certainly seeing a lot of hype by some companies.', 'n. 夸大的广告宣传', '/haɪp/', 'hype', 6);
INSERT INTO `words` VALUES (12809, 'Simply getting a good night\'s sleep could reduce levels of hyperactivity and bad behaviour among children, a Finnish study reports.', 'n. 活动过度， 极度活跃', '/ˌhaɪpəræk\'tɪvəti | ,haɪpəræk\'tɪvəti/', 'hyperactivity', 6);
INSERT INTO `words` VALUES (12810, 'It was not hyperbole to call it the worst storm in twenty years.', 'n. [修辞]夸张法', '/hai\'pə:bəli | haɪ\'pɜːbəlɪ | haɪ\'pɝbəli/', 'hyperbole', 6);
INSERT INTO `words` VALUES (12811, 'The hyperbolic surface, which has so-called negative curvature because its surface curves up and down at the same time, like a saddle, just might represent the shape of the universe.', 'adj. 双曲线的', '/,haipə\'bɔlik | ,haɪpə\'bɒlɪk | ,haɪpɚ\'bɑlɪk/', 'hyperbolic', 6);
INSERT INTO `words` VALUES (12812, 'He\'s as big a geek as Zuckerberg, but of a different type: the hypercritical, even sometimes nasty type.', 'adj. 苛评的, 吹毛求疵的', '/,haipə\'kritikəl | haɪpə\'krɪtɪk(ə)l | \'haɪpɚ\'krɪtɪkl/', 'hypercritical', 6);
INSERT INTO `words` VALUES (12813, 'Student teachers were hypersensitive to any criticism of their performance.', 'adj. 非常敏感的, 敏感的', '/,haipə\'sensətiv | haɪpə\'sensɪtɪv | ,haɪpɚ\'sɛnsətɪv/', 'hypersensitive', 6);
INSERT INTO `words` VALUES (12814, 'When you described depression as a \"disease\" you might have spelled the word with a hyphen.', 'n. 连字号', '/\'haifən | \'haɪf(ə)n | \'haɪfn/', 'hyphen', 6);
INSERT INTO `words` VALUES (12815, 'Bevin is now an adult and has re-lived her birth experience under hypnosis.', 'n. 催眠状态, 催眠', '/hip\'nəusis | hɪp\'nəʊsɪs | hɪp\'nosɪs/', 'hypnosis', 6);
INSERT INTO `words` VALUES (12816, 'His voice had a smooth hypnotic effect .', 'adj. 催眠的, 易被催眠的', '/hip\'nɔtik | hɪp\'nɒtɪk | hɪp\'nɑtɪk/', 'hypnotic', 6);
INSERT INTO `words` VALUES (12817, 'In one of his last letters White defends his hypochondria: “I don\'t regret the time I spent worrying about myself.', 'n. 忧郁症, 臆想病', '/,haipəu\'kɔndriə | ,haɪpə\'kɒndrɪə | \'haɪpə\'kɑndrɪə/', 'hypochondria', 6);
INSERT INTO `words` VALUES (12818, 'Warhol and Gould would have roundly resisted applying the stigma “hypochondriac” to their own terrors; it would have seemed to them a humiliating admission that they were making a fuss about nothing.', 'n. 忧郁症患者', '/haɪpə(ʊ)\'kɒndrɪæk | ,haɪpə\'kɑndrɪæk/', 'hypochondriac', 6);
INSERT INTO `words` VALUES (12819, 'It would be sheer hypocrisy to pray for success, since I’ve never believed in God.', 'n. 伪善', '/hi\'pɔkrisi | hɪ\'pɒkrɪsɪ | hɪ\'pɑkrəsi/', 'hypocrisy', 6);
INSERT INTO `words` VALUES (12820, 'The magazine wrongly suggested he was a liar and a hypocrite.', 'n. 伪善者， 伪君子', '/\'hɪpəkrɪt | \'hɪpə\'krɪt/', 'hypocrite', 6);
INSERT INTO `words` VALUES (12821, 'It would be hypocritical to say I travel at 70 mph simply because that is the law.', 'adj. 虚伪的， 伪善的', '/\'hɪpəkrɪtɪkl | ,hɪpə\'krɪtɪkl/', 'hypocritical', 6);
INSERT INTO `words` VALUES (12822, 'a hypodermic needle', 'adj. 皮下的, 皮下注射用的, 皮下组织的', '/,haipəu\'də:mik | haɪpə(ʊ)\'dɜːmɪk | ,haɪpə\'dəmɪk/', 'hypodermic', 6);
INSERT INTO `words` VALUES (12823, 'I want to compute the length of the hypotenuse of a right triangle.', 'n. 直角三角形之斜边', '/hai\'pɔtənju:z | haɪ\'pɒtənjuːz; -s | haɪ\'pɑtənus/', 'hypotenuse', 6);
INSERT INTO `words` VALUES (12824, 'One hypothesis is that the victim fell asleep while driving.', 'n. 假设', '/hai\'pɔθisis | haɪ\'pɒθɪsɪs | haɪ\'pɑθəsɪs/', 'hypothesis', 6);
INSERT INTO `words` VALUES (12825, 'The question is purely hypothetical .', 'adj. 假设的, 假定的,爱猜想的', '/,haipəu\'θetikəl | ,haɪpə\'θetɪk(ə)l | ,haɪpə\'θɛtɪkl/', 'hypothetical', 6);
INSERT INTO `words` VALUES (12826, 'In a fit of hysteria, Silvia blamed me for causing her father’s death.', 'n. 歇斯底里, 不正常的兴奋, 癔病', '/his\'tiəriə | hɪ\'stɪərɪə | hɪ\'stɪrɪə/', 'hysteria', 6);
INSERT INTO `words` VALUES (12827, 'Janet became hysterical and began screaming.', 'adj. a歇斯底里的, 异常兴奋的', '/his\'terikəl | hɪ\'sterɪk(ə)l | hɪ\'stɛrɪkl/', 'hysterical', 6);
INSERT INTO `words` VALUES (12828, 'Missis walked in\', she said, `as chill as an icicle, and as high as a princess.', 'n. 垂冰, 冰柱', '/\'aisikl | \'aɪsɪk(ə)l | \'aɪsɪkl/', 'icicle', 6);
INSERT INTO `words` VALUES (12829, 'Paul made five-year-old Michelle a birthday cake with yellow icing.', 'n. 糖衣, 结冰', '/\'aisiŋ | \'aɪsɪŋ/', 'icing', 6);
INSERT INTO `words` VALUES (12830, 'To open a new file, click on the icon.', 'n. 图标, 肖像, 偶像', '/\'aikɔn | \'aɪkɒn; -k(ə)n | \'aɪkɑn/', 'icon', 6);
INSERT INTO `words` VALUES (12831, NULL, 'n. 破坏偶像的理论， 打破旧习', '/aɪ\'kɑːnəklæzəm/', 'iconoclasm', 6);
INSERT INTO `words` VALUES (12832, NULL, 'n. 偶像破坏者, 提倡打破旧习的人', '/ai\'kɔnəuklæst | aɪ\'kɒnəklæst | aɪ\'kɑnəklæst/', 'iconoclast', 6);
INSERT INTO `words` VALUES (12833, 'Wolfe’s theories were revolutionary and iconoclastic.', 'adj. 偶像破坏的， 打破旧习的', '/aɪˌkɑːnə\'klæstɪk | aɪ\'kɑnə\'klæstɪk/', 'iconoclastic', 6);
INSERT INTO `words` VALUES (12834, 'Your iconographic views seem to be revolving around an image of a us marine on a skateboard!', 'adj. 肖像的， 肖像学的； 图解的', '/ai,kɔnə\'ɡræfik | aiˌkɔnə\'græfik/', 'iconographic', 6);
INSERT INTO `words` VALUES (12835, 'the idealism of the younger generation', 'n. 理想主义； 唯心主义', '/aɪ\'diːəlɪzəm | \'aɪ\'diə\'lɪzəm/', 'idealism', 6);
INSERT INTO `words` VALUES (12836, 'In the corridor were four dirty, ragged bundles, just identifiable as human beings.', 'adj. 可辨认的', '/aɪˌdentɪ\'faɪəbl | aɪ,dɛntɪ\'faɪəbl/', 'identifiable', 6);
INSERT INTO `words` VALUES (12837, 'Do you have any identification?', 'n. 辨认, 鉴定, 证明, 视为同一', '/ai,dentifi\'keiʃən | aɪ,dentɪfɪ\'keɪʃ(ə)n | aɪˌdentɪfɪ\'keʃn/', 'identification', 6);
INSERT INTO `words` VALUES (12838, 'The party is split by ideological differences.', 'adj. 意识形态的， 思想体系的； 思想上的', '/ˌaɪdiə\'lɑːdʒɪkl | ,aɪdɪə\'lɑdʒɪkl/', 'ideological', 6);
INSERT INTO `words` VALUES (12839, 'the ideologies of fascism and terrorism', 'n. 意识形态', '/,aidi\'ɔlədʒi, ,idi- | ,aɪdɪ\'ɒlədʒɪ; ɪd-/', 'ideology', 6);
INSERT INTO `words` VALUES (12840, '...the idiocy of continuing government subsidies for environmentally damaging activities.', 'n. 白痴, 白痴的行为', '/\'idiəsi | \'ɪdɪəsɪ | \'ɪdɪəsi/', 'idiocy', 6);
INSERT INTO `words` VALUES (12841, 'the new musical idiom', 'n. 方言， 土语； 术语； 特有用语； 风格， 特色', '/\'ɪdiəm | \'ɪdɪəm/', 'idiom', 6);
INSERT INTO `words` VALUES (12842, 'He had the ability to write fluent and idiomatic English.', 'adj. 符合语言习惯的； 惯用的', '/ˌɪdiə\'mætɪk | ,ɪdɪə\'mætɪk/', 'idiomatic', 6);
INSERT INTO `words` VALUES (12843, 'Corporate culture is an important factor that decides the idiosyncracy of corporations.', 'n. 特质', '/ˌɪdiːəu\'sɪŋkrəsi/', 'idiosyncracy', 6);
INSERT INTO `words` VALUES (12844, 'one of the many idiosyncrasies of English spelling', 'n. 特质, 特性', '/,ɪdɪə(ʊ)\'sɪŋkrəsɪ | ,ɪdɪə\'sɪŋkrəsi/', 'idiosyncrasy', 6);
INSERT INTO `words` VALUES (12845, '...a highly idiosyncratic personality.', 'adj. 特殊物质的， 特殊的， 异质的', '/ˌɪdiəsɪŋ\'krætɪk | ,ɪdɪəsɪŋ\'krætɪk/', 'idiosyncratic', 6);
INSERT INTO `words` VALUES (12846, NULL, 'n. 白痴, 愚人, 傻瓜', '/\'idiət | \'ɪdɪət/', 'idiot', 6);
INSERT INTO `words` VALUES (12847, 'Go and wake up that idle brother of yours.', 'adj. 空闲的, 懒惰的, 停顿的, 无用的, 无价值的', '/\'aidl | \'aɪd(ə)l | \'aɪdl/', 'idle', 6);
INSERT INTO `words` VALUES (12848, 'a pop idol', 'n. 偶像, 崇拜物, 幻象, [逻]谬论', '/\'aidəl | \'aɪd(ə)l | \'aɪdl/', 'idol', 6);
INSERT INTO `words` VALUES (12849, NULL, 'n. 偶像崇拜者, 崇拜者, 皈依者, 追星族', '/ai\'dɔlətə | aɪ\'dɒlətə/', 'idolater', 6);
INSERT INTO `words` VALUES (12850, NULL, 'v. 奉为偶像， 盲目崇拜', '/aɪ\'dɔlətraɪz | aɪ\'dɑlə,traɪz/', 'idolatrize', 6);
INSERT INTO `words` VALUES (12851, 'He tells them that their gods are false and that worshipping more than one God is idolatrous .', 'adj. 崇拜偶像的, 盲目崇拜的', '/ai\'dɔlətrəs | aɪ\'dɒlətrəs | aɪ\'dɑlətrəs/', 'idolatrous', 6);
INSERT INTO `words` VALUES (12852, 'They had one child, a girl whom they idolized.', 'v. 将…当作偶像崇拜； 极度仰慕， 崇拜', '/\'aɪdəlaɪz | ˈaɪdəlˌaɪz/', 'idolize', 6);
INSERT INTO `words` VALUES (12853, 'She finds that the sleepy town she moves to isn\'t the rural idyll she imagined.', 'n. 田园诗, 牧歌', '/\'idil, \'aidil | \'aidil/', 'idyll', 6);
INSERT INTO `words` VALUES (12854, 'This idyllic pastoral scene is only part of the picture.', 'adj. 田园诗的', '/aɪ\'dɪlɪk/', 'idyllic', 6);
INSERT INTO `words` VALUES (12855, 'Defining the town center of Râmnicu Vâlcea is a towering shopping mall that looks like a giant glass igloo.', 'n. 圆顶建筑', '/\'iɡlu: | \'ɪgluː | \'ɪglʊ/', 'igloo', 6);
INSERT INTO `words` VALUES (12856, 'The Great Dyke of Zimbabwe is a layered mafic intrusion of igneous, metal-bearing rock that has been dated to approximately 2.5 billion years old.', 'adj. 火的, 似火的, [地]火成的', '/\'iɡniəs | \'ɪgnɪəs/', 'igneous', 6);
INSERT INTO `words` VALUES (12857, 'The petrol tank suddenly ignited.', 'v. 点火, 点燃', '/iɡ\'nait | ɪg\'naɪt | ɪɡ\'naɪt/', 'ignite', 6);
INSERT INTO `words` VALUES (12858, 'ignoble feelings of intense jealousy', 'adj. 不光彩的', '/iɡ\'nəubl | ɪg\'nəʊb(ə)l | ɪɡ\'nobl/', 'ignoble', 6);
INSERT INTO `words` VALUES (12859, 'an ignominious end to his career', 'adj. 可耻的, 不光彩的, 下流的', '/,iɡnəu\'miniəs | ,ɪgnə\'mɪnɪəs | ,ɪɡnə\'mɪnɪəs/', 'ignominious', 6);
INSERT INTO `words` VALUES (12860, '...the ignominy of being fired.', 'n. 耻辱', '/\'iɡnəmini | \'ɪgnəmɪnɪ | \'ɪɡnəmɪni/', 'ignominy', 6);
INSERT INTO `words` VALUES (12861, NULL, 'n. 不学无术的人, 无知识的人', '/,iɡnə\'reiməs | ,ɪgnə\'reɪməs | ,ɪɡnə\'reməs/', 'ignoramus', 6);
INSERT INTO `words` VALUES (12862, 'Excuse my ignorance, but how does it actually work?', 'n. 无知, 不知', '/\'iɡnərəns | \'ɪgn(ə)r(ə)ns | \'ɪɡnərəns/', 'ignorance', 6);
INSERT INTO `words` VALUES (12863, 'an ignorant and uneducated man', 'adj. 无知的， 愚昧的', '/\'ɪgnərənt | \'ɪɡnərənt/', 'ignorant', 6);
INSERT INTO `words` VALUES (12864, 'You can’t ignore the fact that many criminals never go to prison.', 'v. 不顾， 不理， 忽视', '/ɪg\'nɔːr | ɪɡ\'nɔr/', 'ignore', 6);
INSERT INTO `words` VALUES (12865, 'This iguana is one of the few lizards found in that cold climate.', 'n. [动]鬣蜥(一种产于南美洲和西印度群岛的大蜥蜴)', '/i\'ɡwɑ:nə | ɪ\'gwɑːnə | ɪ\'ɡwɑnə/', 'iguana', 6);
INSERT INTO `words` VALUES (12866, 'The Morgans, Warburgs, and their ilk amassed fortunes that gave them tremendous political power.', 'n. 类型， 种类', '/ɪlk/', 'ilk', 6);
INSERT INTO `words` VALUES (12867, NULL, 'adj. 工资低廉的', '/ˌɪl\'peɪɪŋ/', 'ill-paying', 6);
INSERT INTO `words` VALUES (12868, 'The government was ill-prepared for the problems it now faces.', 'adj. 准备不足的', '/,ilpri\'pεəd | ˌɪlprɪ\'perd/', 'ill-prepared', 6);
INSERT INTO `words` VALUES (12869, NULL, 'n. 名誉败坏', '/ˌɪlrɪ\'pjuːt/', 'ill-repute', 6);
INSERT INTO `words` VALUES (12870, 'He didn\'t bear anyone any ill will.', 'n. 敌意， 仇视， 恶感', '/ˌɪl\'wɪl/', 'ill-will', 6);
INSERT INTO `words` VALUES (12871, '\"The problem is: who do I talk to in a context of systematic illegality?\" says Cenni.', 'n. 非法行为, 犯规', '/,ili:\'ɡæləti | ,ɪliː\'ɡælətɪ | ,ɪlɪ\'ɡæləti/', 'illegality', 6);
INSERT INTO `words` VALUES (12872, 'His handwriting is totally illegible.', 'adj. 难辨认的, 字迹模糊的', '/i\'ledʒibl | ɪ\'ledʒɪb(ə)l | ɪ\'lɛdʒəbl/', 'illegible', 6);
INSERT INTO `words` VALUES (12873, 'his illegitimate son', 'adj. 违法的, 非嫡出的, 庶生的, 私生的, 不合理的, 不合逻辑的', '/,ili\'dʒitimət, ,ili\'dʒitimeit | ,ɪlɪ\'dʒɪtɪmət | ,ɪlɪ\'dʒɪtɪmet/', 'illegitimate', 6);
INSERT INTO `words` VALUES (12874, 'illiberal and undemocratic policies', 'adj. 狭碍的, 偏执的, 吝啬的, 缺乏文化素养的, 粗鄙的', '/ɪ\'lɪb(ə)r(ə)l | ɪ\'lɪbərəl/', 'illiberal', 6);
INSERT INTO `words` VALUES (12875, 'the illicit trade in stolen cattle', 'adj. 违法的', '/i\'lisit | ɪ\'lɪsɪt/', 'illicit', 6);
INSERT INTO `words` VALUES (12876, '...a subclass of illiterates.', 'n. 文盲', '/i\'litərət | ɪ\'lɪt(ə)rət | ɪ\'lɪtərət/', 'illiterate', 6);
INSERT INTO `words` VALUES (12877, 'A single candle illuminated his face.', 'v. 阐明， 解释； 照亮', '/ɪ\'luːmɪneɪt | ɪ\'lumɪnet/', 'illuminate', 6);
INSERT INTO `words` VALUES (12878, NULL, 'n. 先觉者， 先知', '/ɪˌluːmɪ\'nɑːti | ɪ,lʊmə\'netai/', 'illuminati', 6);
INSERT INTO `words` VALUES (12879, 'a very illuminating book', 'adj. 照亮的, 启蒙的, 照明的', '/i\'lju:mineitiŋ | ɪ\'ljuːmɪneɪtɪŋ | ɪ\'lʊmə\'netɪŋ/', 'illuminating', 6);
INSERT INTO `words` VALUES (12880, 'White candles, the only illumination, burned on the table.', 'n. 照明, 阐明, 启发, 灯彩(通常用复数)', '/i,lju:mi\'neiʃən | ɪ,ljuːmɪ\'neɪʃən | ɪ\'lʊmə\'neʃən/', 'illumination', 6);
INSERT INTO `words` VALUES (12881, 'He was fond of calling his detractor illiterate, denouncing his scientific theories as illegitimate and illusive.', 'adj. 迷惑人的， 迷幻的', '/ɪ\'luːsɪv | ɪ\'lusɪv/', 'illusive', 6);
INSERT INTO `words` VALUES (12882, 'First impressions can often prove illusory.', 'adj. 产生幻觉的, 幻影的, 错觉的, 虚假的, 不牢靠的', '/i\'lju:səri | ɪ\'l(j)uːs(ə)rɪ | ɪ\'lusəri/', 'illusory', 6);
INSERT INTO `words` VALUES (12883, 'Let me give an example to illustrate the point.', 'v. 举例说明， 用图表等说明； 阐明', '/\'ɪləstreɪt | \'ɪləstret/', 'illustrate', 6);
INSERT INTO `words` VALUES (12884, 'The book contains 62 pages of illustrations.', 'n. 说明, 例证, 例子, 图表, 插图插图,图解', '/,ilə\'streiʃən | ɪlə\'streɪʃ(ə)n | ,ɪlə\'streʃən/', 'illustration', 6);
INSERT INTO `words` VALUES (12885, 'graphics and other illustrative material', 'adj. 解说性的， 用作说明的', '/ɪ\'lʌstrətɪv/', 'illustrative', 6);
INSERT INTO `words` VALUES (12886, 'She has had an illustrious career.', 'adj. 杰出的', '/i\'lʌstriəs | ɪ\'lʌstrɪəs/', 'illustrious', 6);
INSERT INTO `words` VALUES (12887, 'As she listened, she played an imaginary piano on her knees.', 'adj. 假想的, 想象的, 虚构的', '/i\'mædʒinəri | ɪ\'mædʒɪn(ə)rɪ | ɪ\'mædʒɪnɛri/', 'imaginary', 6);
INSERT INTO `words` VALUES (12888, 'Colin, the theory of urban imago of Kevin.', 'n. 意象, 成虫', '/i\'meiɡəu | ɪ\'meɪgəʊ | ɪ\'mego/', 'imago', 6);
INSERT INTO `words` VALUES (12889, 'It was an imbecile thing to do.', 'adj. 低能的, 愚笨的, 虚弱的', '/\'imbisi:l,-sail | \'ɪmbɪsiːl | \'ɪmbɪsaɪl/', 'imbecile', 6);
INSERT INTO `words` VALUES (12890, NULL, 'n. 低能', '/,imbi\'siləti | ,ɪmbɪ\'sɪlətɪ | ,ɪmbə\'sɪləti/', 'imbecility', 6);
INSERT INTO `words` VALUES (12891, 'She had imbibed the traditions of her family.', 'v. 吸收', '/im\'baib | ɪm\'baɪb/', 'imbibe', 6);
INSERT INTO `words` VALUES (12892, 'a political imbroglio', 'n. 杂乱的一团, 纠葛, 纷扰, 误解', '/im\'brəuljəu | ɪm\'brəʊlɪəʊ | ɪm\'brolɪo/', 'imbroglio', 6);
INSERT INTO `words` VALUES (12893, 'The film is imbued with the star\'s rebellious spirit.', 'v. 浸透', '/im\'bju: | ɪm\'bjuː | ɪm\'bjʊ/', 'imbue', 6);
INSERT INTO `words` VALUES (12894, 'She was a splendid mimic and loved to imitate Winston Churchill.', 'v. 模仿', '/\'ɪmɪteɪt | \'ɪmɪtet/', 'imitate', 6);
INSERT INTO `words` VALUES (12895, 'her immaculate stage performances', 'adj. 完美的', '/i\'mækjulət | ɪ\'mækjʊlət | ɪ\'mækjələt/', 'immaculate', 6);
INSERT INTO `words` VALUES (12896, 'Love is a force immanent in the world.', 'adj. 内在的, 固有的, [宗](上帝)无所不在的', '/\'imənənt | \'ɪmənənt/', 'immanent', 6);
INSERT INTO `words` VALUES (12897, 'our immaterial soul', 'adj. 非实质的', '/,imə\'tiəriəl | ɪmə\'tɪərɪəl | ,ɪmə\'tɪrɪəl/', 'immaterial', 6);
INSERT INTO `words` VALUES (12898, 'measures to protect immature whales', 'adj. 未充分成长的， 未完全发展的； 不成熟的', '/ˌɪmə\'tʃur | ,ɪmə\'tʃʊr/', 'immature', 6);
INSERT INTO `words` VALUES (12899, 'It erects a barrier that severs the pleasure and immediacy of visceral experience.', 'n. 直接', '/i\'mi:diəsi | ɪ\'miːdɪəsɪ | ɪ\'midɪəsi/', 'immediacy', 6);
INSERT INTO `words` VALUES (12900, 'Since time immemorial, the whale has been wreathed in mystery—and of course it almost predates time itself, having existed long before the land around which it swims.', 'adj. 古老的, 远古的, 无法追忆的', '/,imi\'mɔ:riəl | ɪmɪ\'mɔːrɪəl | ,ɪmə\'mɔrɪəl/', 'immemorial', 6);
INSERT INTO `words` VALUES (12901, 'People who travel by rail still read an immense amount.', 'adj. 极广大的, 无边的, <口>非常好的', '/i\'mens | ɪ\'mens | ɪ\'mɛns/', 'immense', 6);
INSERT INTO `words` VALUES (12902, NULL, 'n. 广大, 巨大, 无限, 浩瀚', '/i\'mensəti | ɪ\'mensətɪ | ɪ\'mɛnsəti/', 'immensity', 6);
INSERT INTO `words` VALUES (12903, 'The electrodes are immersed in liquid.', 'v. 沉浸, 使陷入', '/i\'mə:s | ɪ\'mɜːs | ɪ\'mɝs/', 'immerse', 6);
INSERT INTO `words` VALUES (12904, '...long-term assignments that allowed them total immersion in their subjects.', 'n. 沉浸', '/i\'mə:ʃən | ɪ\'mɜːʃ(ə)n | ɪ\'mɝʃən/', 'immersion', 6);
INSERT INTO `words` VALUES (12905, NULL, 'n. 迫切, 急迫,迫近的危险(或祸患)', '/\'iminəns | \'ɪmɪnəns | \'ɪmənəns/', 'imminence', 6);
INSERT INTO `words` VALUES (12906, 'A new trade agreement is imminent.', 'adj. 即将来临的, 逼近的', '/\'iminənt | \'ɪmɪnənt/', 'imminent', 6);
INSERT INTO `words` VALUES (12907, 'She could see a figure sitting immobile, facing the sea.', 'adj. 稳定的， 不动的， 静止的', '/ɪ\'moubl | ɪ\'mobl/', 'immobile', 6);
INSERT INTO `words` VALUES (12908, 'The budget buffet attracted customers with immoderate appetites but limited pocket books.', 'adj. 不适中的', '/i\'mɔdərət | ɪ\'mɒd(ə)rət | ɪ\'mɑdərət/', 'immoderate', 6);
INSERT INTO `words` VALUES (12909, 'Webb was an immodest publicist of his own achievements.', 'adj. 不谦虚的 ； 不正派的', '/ɪ\'mɑːdɪst | ɪ\'mɑdɪst/', 'immodest', 6);
INSERT INTO `words` VALUES (12910, 'He would immolate himself for their noble cause .', 'v. 牺牲, 献出, 献祭', '/\'iməuleit | \'ɪməleɪt | \'ɪməlet/', 'immolate', 6);
INSERT INTO `words` VALUES (12911, NULL, 'n. 宰杀, 祭物', '/,iməu\'leiʃən/', 'immolation', 6);
INSERT INTO `words` VALUES (12912, 'Deliberately making people suffer is immoral.', 'adj. 不道德的, 邪恶的, 放荡的, 淫荡的', '/\'imɔrəl | ɪ\'mɒr(ə)l | ɪ\'mɔrəl/', 'immoral', 6);
INSERT INTO `words` VALUES (12913, 'Plato believed that the soul is immortal.', 'adj. 不朽的', '/i\'mɔ:təl | ɪ\'mɔːt(ə)l | ɪ\'mɔrtl/', 'immortal', 6);
INSERT INTO `words` VALUES (12914, 'Once we’ve had the disease, we’re immune for life.', 'adj. 免疫的', '/i\'mju:n | ɪ\'mjuːn | ɪ\'mjʊn/', 'immune', 6);
INSERT INTO `words` VALUES (12915, 'To protect you against small pox or diphtheria, you are vaccinated with a small amount of the toxin, and then your body develops immunity against that toxin.', 'n. 免疫性', '/i\'mju:nəti | ɪ\'mjuːnɪtɪ | ɪ\'mjʊnəti/', 'immunity', 6);
INSERT INTO `words` VALUES (12916, 'We should require that every student is immunized against hepatitis B.', 'v. 使免疫, 赋予免疫性, 使成为无害', '/\'imju:naiz | \'ɪmjʊ\'naɪz/', 'immunize', 6);
INSERT INTO `words` VALUES (12917, NULL, 'v. 监禁', '/ɪ\'mjur | i\'mjuə/', 'immure', 6);
INSERT INTO `words` VALUES (12918, NULL, 'n. 不变， 不变性', '/i,mjuitə\'biləti | ɪˌmjuːtə\'bɪləti/', 'immutability', 6);
INSERT INTO `words` VALUES (12919, 'This decision should not be seen as immutable.', 'adj. 不可变的, 不变的, 不能变的, 永恒的', '/i\'mju:təbl | ɪ\'mjuːtəb(ə)l | ɪ\'mjutəbl/', 'immutable', 6);
INSERT INTO `words` VALUES (12920, NULL, 'n. 小鬼, 小淘气, 顽童', '/imp | ɪmp/', 'imp', 6);
INSERT INTO `words` VALUES (12921, 'The force of the impact knocked the breath out of her.', 'n. 冲击， 影响', '/\'ɪmpækt | ɪm\'pækt/', 'impact', 6);
INSERT INTO `words` VALUES (12922, 'The illness had impaired his ability to think and concentrate.', 'v. 削弱', '/im\'pεə | ɪm\'peə | ɪm\'pɛr/', 'impair', 6);
INSERT INTO `words` VALUES (12923, 'Researchers observed one bird impale a rodent on a cactus.', 'v. 刺入， 刺穿', '/ɪm\'peɪl | im\'peil/', 'impale', 6);
INSERT INTO `words` VALUES (12924, 'To the untrue man, the whole universe is false- it is impalpable- it shrinks to nothing within his grasp.', 'adj. 感触不到的, 摸不到的, 难解的', '/im\'pælpəbl | ɪm\'pælpəb(ə)l/', 'impalpable', 6);
INSERT INTO `words` VALUES (12925, 'She had information that she couldn’t wait to impart.', 'v. 给予(尤指抽象事物), 传授, 告知, 透露', '/im\'pɑ:t | ɪm\'pɑːt | ɪm\'pɑrt/', 'impart', 6);
INSERT INTO `words` VALUES (12926, 'We offer impartial advice on tax and insurance.', 'adj. 公平的, 不偏不倚的', '/im\'pɑ:ʃəl | ɪm\'pɑːʃ(ə)l | ɪm\'pɑrʃəl/', 'impartial', 6);
INSERT INTO `words` VALUES (12927, 'Selection of auditors and conduct of audits shall ensure objectivity and impartiality of the audit process. Auditors shall not audit their own work.', 'n. 公平， 公正', '/ˌɪmˌpɑːrʃi\'æləti | ,ɪmpɑrʃɪ\'æləti/', 'impartiality', 6);
INSERT INTO `words` VALUES (12928, 'The mountains are impassable.', 'adj. 不能通行的， 无法通过的', '/ɪm\'pæsəbl/', 'impassable', 6);
INSERT INTO `words` VALUES (12929, 'Negotiations seemed to have reached an impasse.', 'n. 僵局', '/im\'pɑ:s | æm\'pɑːs; \'æmpɑːs | \'ɪmpæs/', 'impasse', 6);
INSERT INTO `words` VALUES (12930, 'She appeared on television to make an impassioned plea for help.', 'adj. 热情洋溢的', '/im\'pæʃənd | ɪm\'pæʃ(ə)nd | ɪm\'pæʃnd/', 'impassioned', 6);
INSERT INTO `words` VALUES (12931, 'Her impassive face showed no reaction at all.', 'adj. 冷漠的', '/im\'pæsiv | ɪm\'pæsɪv/', 'impassive', 6);
INSERT INTO `words` VALUES (12932, 'A note of impatience had entered his voice.', 'n. 不耐烦， 焦躁', '/ɪm\'peɪʃns | ɪm\'peʃəns/', 'impatience', 6);
INSERT INTO `words` VALUES (12933, NULL, 'adj. 无价的, 极贵重的, 无法清偿的, <口>无与伦比的, 极好的', '/im\'peiəbl/', 'impayable', 6);
INSERT INTO `words` VALUES (12934, 'The governor was impeached for using state funds improperly.', 'v. [律]控告, 检举, <主美>弹劾, 怀疑', '/im\'pi:tʃ | ɪm\'piːtʃ | ɪm\'pitʃ/', 'impeach', 6);
INSERT INTO `words` VALUES (12935, 'She has taught her children impeccable manners.', 'adj. 没有缺点的, 不会做坏事的', '/im\'pekəbl | ɪm\'pekəb(ə)l | ɪm\'pɛkəbl/', 'impeccable', 6);
INSERT INTO `words` VALUES (12936, 'He came from a respectable if impecunious family.', 'adj. (经常)没有钱的, 身无分文的, 贫穷的', '/,impi\'kju:njəs | ,ɪmpɪ\'kjuːnɪəs | ,ɪmpɪ\'kjunɪəs/', 'impecunious', 6);
INSERT INTO `words` VALUES (12937, 'Storms at sea impeded our progress.', 'v. 阻止', '/im\'pi:d | ɪm\'piːd | ɪm\'pid/', 'impede', 6);
INSERT INTO `words` VALUES (12938, 'a speech impediment', 'n. 妨碍, 阻碍, 障碍物, (言语)障碍, 口吃, 障碍物', '/im\'pedimənt | ɪm\'pedɪm(ə)nt | ɪm\'pɛdɪmənt/', 'impediment', 6);
INSERT INTO `words` VALUES (12939, NULL, 'n. 妨碍行进或运动的东西', '/im,pedi\'mentə | ɪm,pedɪ\'mentə | ɪm,pɛdɪ\'mɛntə/', 'impedimenta', 6);
INSERT INTO `words` VALUES (12940, '...the courage and competitiveness which impels him to take risks.', 'v. 推动, 推进, 激励, 驱使, 逼迫', '/im\'pel | ɪm\'pel | ɪm\'pɛl/', 'impel', 6);
INSERT INTO `words` VALUES (12941, 'Crucial events impend in Europe.', 'v. 威胁； 即将发生', '/ɪm\'pend | ɪmˈpɛnd/', 'impend', 6);
INSERT INTO `words` VALUES (12942, 'The town itself is believed to be largely deserted after many of its inhabitants fled the impending crackdown, some of them crossing the border to nearby Turkey.', 'n. 迫近', '/im\'pendiŋ | ɪm\'pendɪŋ | ɪm\'pɛndɪŋ/', 'impending', 6);
INSERT INTO `words` VALUES (12943, '...the Caucasus range, an almost impenetrable barrier between Europe and Asia.', 'adj. 难以渗透的', '/im\'penitrəbl | ɪm\'penɪtrəb(ə)l | ɪm\'pɛnɪtrəbl/', 'impenetrable', 6);
INSERT INTO `words` VALUES (12944, 'Endless, of the impenitent and unbelieving.', 'adj. 不悔悟的, 顽固的', '/im\'penitənt | ɪm\'penɪt(ə)nt | ɪm\'pɛnɪtənt/', 'impenitent', 6);
INSERT INTO `words` VALUES (12945, 'It is imperative that politicians should be good communicators.', 'n. 命令, 诫命, 需要, 规则, 祈使语气', '/ɪm\'perətɪv | ɪm\'pɛrətɪv/', 'imperative', 6);
INSERT INTO `words` VALUES (12946, 'Such changes are imperceptible to even the best-trained eye.', 'adj. 觉察不到的, 感觉不到的, 极细微的', '/,impə\'septəbl | ɪmpə\'septɪb(ə)l | ,ɪmpɚ\'sɛptəbl/', 'imperceptible', 6);
INSERT INTO `words` VALUES (12947, 'Britain’s imperial expansion in the 19th century', 'adj. 帝王的， 至尊的', '/ɪm\'pɪriəl | ɪm\'pɪrɪəl/', 'imperial', 6);
INSERT INTO `words` VALUES (12948, 'Tax increases now might imperil economic recovery.', 'v. 使处于危险, 危害', '/im\'peril | ɪm\'perɪl; -r(ə)l | ɪm\'pɛrəl/', 'imperil', 6);
INSERT INTO `words` VALUES (12949, 'She raised her hand in an imperious gesture.', 'adj. 专横的', '/im\'piəriəs | ɪm\'pɪərɪəs | ɪm\'pɪrɪəs/', 'imperious', 6);
INSERT INTO `words` VALUES (12950, 'single-storey structures, built from cheap and impermanent materials', 'adj. 暂时的', '/ɪm\'pɜːrmənənt | ɪm\'pɝmənənt/', 'impermanent', 6);
INSERT INTO `words` VALUES (12951, 'The effect of admixture on impermeability of concrete in frigid zone was studied the results of the test meet the requirements of design and construction.', 'n. 不渗透性', '/im,pə:miə\'biləti | ɪmˌpɜːrmiə\'bɪləti/', 'impermeability', 6);
INSERT INTO `words` VALUES (12952, 'No paint is impermeable to water vapour.', 'adj. 不能渗透的, 不渗透性的', '/im\'pə:miəbl | ɪm\'pɜːmɪəb(ə)l | ɪm\'pɝmɪəbl/', 'impermeable', 6);
INSERT INTO `words` VALUES (12953, 'Such a state of affairs is entirely impermissible.', 'adj. 不容许的', '/ˌɪmpɜːr\'mɪsəbl/', 'impermissible', 6);
INSERT INTO `words` VALUES (12954, 'Before then many children were cared for in large impersonal orphanages.', 'adj. 不受个人感情影响的', '/ɪm\'pɜːrsənl | ɪm\'pɝsnl/', 'impersonal', 6);
INSERT INTO `words` VALUES (12955, 'In the film he amusingly impersonates a woman.', 'v. 模仿, 扮演, 人格化, 拟人', '/im\'pə:səneit, im\'pə:sənit, -neit | ɪm\'pɜːs(ə)neɪt | ɪm\'pɝsənet/', 'impersonate', 6);
INSERT INTO `words` VALUES (12956, 'He was punished for his impertinence.', 'n. 无礼， 粗鲁', '/ɪm\'pɜːrtnəns | im\'pə:tinəns,-nənsi/', 'impertinence', 6);
INSERT INTO `words` VALUES (12957, 'He was always asking impertinent questions.', 'adj. 无关的, 鲁莽的, 不相干的', '/im\'pə:tinənt | ɪm\'pɜːtɪnənt | ɪm\'pɝtnənt/', 'impertinent', 6);
INSERT INTO `words` VALUES (12958, 'Thomas, of course, was cool and aloof and imperturbable.', 'adj. 沉着的, 冷静的', '/,impə\'tə:bəbl | ,ɪmpə\'tɜːbəb(ə)l/', 'imperturbable', 6);
INSERT INTO `words` VALUES (12959, 'impervious volcanic rock', 'adj. 不让进入, 不会受到损伤的, 密封的, 不受影响的', '/im\'pə:viəs | ɪm\'pɜːvɪəs | ɪm\'pɝvɪəs/', 'impervious', 6);
INSERT INTO `words` VALUES (12960, 'He was high-spirited and impetuous.', 'adj. 冲动的, 猛烈的, 激烈的', '/im\'petjuəs | ɪm\'petjʊəs | ɪm\'pɛtʃʊəs/', 'impetuous', 6);
INSERT INTO `words` VALUES (12961, 'The discovery gave fresh impetus to the research.', 'n. 推动力, 促进', '/\'impitəs | \'ɪmpɪtəs/', 'impetus', 6);
INSERT INTO `words` VALUES (12962, NULL, 'n. 不虔诚， 无信仰', '/ɪm\'paɪəti/', 'impiety', 6);
INSERT INTO `words` VALUES (12963, '...the cuts in defence spending that have impinged on two of the region\'s largest employers.', 'v. 侵犯； 撞击', '/ɪm\'pɪndʒ/', 'impinge', 6);
INSERT INTO `words` VALUES (12964, 'implacable enemies', 'adj. 不缓和的, 不安静的', '/im\'plækəbl, -\'plei | ɪm\'plækəb(ə)l | ɪm\'plækəbl/', 'implacable', 6);
INSERT INTO `words` VALUES (12965, 'The diagram implanted a dangerous prejudice firmly in the minds of countless economics students.', 'v. 灌输', '/im\'plɑ:nt, -\'plænt, \'implɑ:nt, -plænt | ɪm\'plɑːnt | ɪm\'plænt/', 'implant', 6);
INSERT INTO `words` VALUES (12966, 'It’s not entirely implausible that a galaxy could be identical to our own.', 'adj. 难以置信的', '/ɪm\'plɔːzəbl | ɪm\'plɔzəbl/', 'implausible', 6);
INSERT INTO `words` VALUES (12967, 'The government promised to implement a new system to control financial loan institutions.', 'n. 工具, 器具', '/\'implimənt, \'impliment | \'ɪmplɪm(ə)nt | \'ɪmplɪmɛnt/', 'implement', 6);
INSERT INTO `words` VALUES (12968, 'The allegations implicated Abe to such an extent he was forced to resign.', 'v. 使牵连其中, 含意, 暗示', '/\'implikeit | \'ɪmplɪkeɪt | \'ɪmplɪket/', 'implicate', 6);
INSERT INTO `words` VALUES (12969, 'They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.', 'n. 牵连, 含意, 暗示', '/ɪmplɪ\'keɪʃ(ə)n | \'ɪmplɪ\'keʃən/', 'implication', 6);
INSERT INTO `words` VALUES (12970, '...an implicit warning to the Moroccans not to continue or repeat the military actions they began a week ago.', 'adj. 暗示的, 盲从的, 含蓄的, 固有的, 不怀疑的, 绝对的', '/im\'plisit | ɪm\'plɪsɪt/', 'implicit', 6);
INSERT INTO `words` VALUES (12971, 'The windows on both sides of the room had imploded.', 'v. 向内破裂, 爆炸', '/ɪm\'pləʊd | ɪm\'plod/', 'implode', 6);
INSERT INTO `words` VALUES (12972, '‘Don’t go,’ I implored her.', 'v. 恳求, 哀求', '/im\'plɔ: | ɪm\'plɔː | ɪm\'plɔr/', 'implore', 6);
INSERT INTO `words` VALUES (12973, NULL, 'n. (音声)内破裂, 闭塞', '/im\'pləuʒən | ɪm\'pləʊʒən | ɪm\'ploʒən/', 'implosion', 6);
INSERT INTO `words` VALUES (12974, 'an implied threat', 'v. 暗示， 暗指', '/ɪm\'plaɪ | ɪm\'plai/', 'imply', 6);
INSERT INTO `words` VALUES (12975, 'It was considered impolitic of him to spend too much time with the party radicals.', 'adj. 失策的, 不得当的, 不审慎的, 没见识的', '/im\'pɔlətik | ɪm\'pɒlɪtɪk | ɪm\'pɑlətɪk/', 'impolitic', 6);
INSERT INTO `words` VALUES (12976, 'There can never be a definitive version of a myth, because it refers to the more imponderable aspects of life.', 'adj. 不可估计的', '/im\'pɔndərəbl | ɪm\'pɒnd(ə)rəb(ə)l | ɪm\'pɑndərəbl/', 'imponderable', 6);
INSERT INTO `words` VALUES (12977, 'importunate demands', 'adj. (人)缠扰不休的, 胡搅蛮缠的, (事务等)急切的, 讨厌的', '/ɪm\'pɔːtjʊnət | ɪm\'pɔrtʃənət/', 'importunate', 6);
INSERT INTO `words` VALUES (12978, 'One can no longer walk the streets without seeing beggars importuning passersby.', 'v. 强求', '/im\'pɔ:tju:n, ,impɔ:\'tju:n | ,ɪmpɔː\'tjuːn | ,ɪmpɔr\'tun/', 'importune', 6);
INSERT INTO `words` VALUES (12979, 'The court can impose a fine.', 'v. 征收； 强加', '/ɪm\'pouz | ɪm\'poz/', 'impose', 6);
INSERT INTO `words` VALUES (12980, 'an imposing building', 'adj. 使人难忘的, 壮丽的', '/im\'pəuziŋ | ɪm\'pəʊzɪŋ | ɪm\'pozɪŋ/', 'imposing', 6);
INSERT INTO `words` VALUES (12981, 'The nurse was soon discovered to be an impostor.', 'n. 冒名顶替者', '/im\'pɔstə | ɪm\'pɒstə | ɪm\'pɑstɚ/', 'impostor', 6);
INSERT INTO `words` VALUES (12982, 'This new resource discovery algorithm can effectively restrain the imposture and pseudo service of P2P network, improve the reliability and security and decrease network load.', 'n. 欺诈, 冒牌', '/im\'pɔstʃə | ɪm\'pɒstʃə | ɪm\'pɑstʃɚ/', 'imposture', 6);
INSERT INTO `words` VALUES (12983, 'Emergency services seem impotent in the face of such a disaster.', 'adj. 无力的, 虚弱的, 无效的, [医]阳萎的', '/\'impətənt | \'ɪmpət(ə)nt | \'ɪmpətənt/', 'impotent', 6);
INSERT INTO `words` VALUES (12984, 'He sued the police after they impounded his car.', 'v. 关在栏中, 拘留, 扣押, 没收', '/im\'paund | ɪm\'pəʊnd | ɪm\'paʊnd/', 'impound', 6);
INSERT INTO `words` VALUES (12985, 'Falling coffee prices have impoverished many developing economies.', 'v. 使贫穷, 使枯竭', '/im\'pɔvəriʃ | ɪm\'pɒv(ə)rɪʃ | ɪm\'pɑvərɪʃ/', 'impoverish', 6);
INSERT INTO `words` VALUES (12986, NULL, 'n. 无法实施； 不能实施的事项', '/im,præktikə\'biləti | ɪmˌpræktɪkə\'bɪləti/', 'impracticability', 6);
INSERT INTO `words` VALUES (12987, 'The road toll scheme was dismissed as impractical.', 'adj. 不切实际的', '/ɪm\'præktɪkl/', 'impractical', 6);
INSERT INTO `words` VALUES (12988, NULL, 'v. 祈求, 诅咒', '/\'imprikeit | \'ɪmprɪkeɪt/', 'imprecate', 6);
INSERT INTO `words` VALUES (12989, 'Let I not imprecation I of pain and sufferings will stop.', 'n. 祈求, 诅咒', '/,impri\'keiʃən | ɪmprɪ\'keɪʃ(ə)n | ,ɪmprɪ\'keʃən/', 'imprecation', 6);
INSERT INTO `words` VALUES (12990, 'vague imprecise estimates', 'adj. 不精确的', '/ˌɪmprɪ\'saɪs | \'ɪmprɪ\'saɪs/', 'imprecise', 6);
INSERT INTO `words` VALUES (12991, 'an impregnable fortress', 'adj. 无法攻取的, 要塞坚固的, 不受影响的, 可以受孕的的', '/ɪm\'pregnəb(ə)l | ɪm\'prɛɡnəbl/', 'impregnable', 6);
INSERT INTO `words` VALUES (12992, 'Undercover officers found drug-making equipment used to impregnate paper with LSD.', 'v. 使怀孕, 使受精, 使充满, 注入, 灌输', '/\'impreɡneit, im\'preɡ-, im\'preɡnit, -neit | \'ɪmpregneɪt | ɪm\'prɛɡnet/', 'impregnate', 6);
INSERT INTO `words` VALUES (12993, NULL, 'n. (剧团)经理, 乐队指挥, 演出者, 舞台监督', '/,impri\'sɑ:riəu | ,ɪmprɪ\'sɑːrɪəʊ | ,ɪmprə\'sɑrɪo/', 'impresario', 6);
INSERT INTO `words` VALUES (12994, NULL, 'adj. 被打动的， 被感动的', '/ɪm\'prest | ɪm\'prɛst/', 'impressed', 6);
INSERT INTO `words` VALUES (12995, 'The kids are at an impressionable age.', 'adj. 容易受感动的, 敏感的', '/im\'preʃənəbl | ɪm\'preʃ(ə)nəb(ə)l | ɪm\'prɛʃənəbl/', 'impressionable', 6);
INSERT INTO `words` VALUES (12996, 'The figures certainly look impressive.', 'adj. 给人印象深刻的， 感人的', '/ɪm\'presɪv | ɪm\'prɛsɪv/', 'impressive', 6);
INSERT INTO `words` VALUES (12997, 'The company carries a variety of binders that can be imprinted with your message or logo.', 'v. 留下烙印', '/im\'print, \'imprint | ɪm\'prɪnt | \'ɪmprɪnt/', 'imprint', 6);
INSERT INTO `words` VALUES (12998, 'Writing a 15-page analysis about their professor\'s movie, hundreds of impromptu speeches, reading a 150-page literature book are quite normal for them.', 'n. 即席演出, 即兴曲', '/im\'prɔmptju: | ɪm\'prɒm(p)tjuː | ɪm\'prɑmptu/', 'impromptu', 6);
INSERT INTO `words` VALUES (12999, '25 officers were investigated following allegations of improper conduct.', 'adj. 不合适的， 不适当的', '/ɪm\'prɑːpər | ɪm\'prɑpɚ/', 'improper', 6);
INSERT INTO `words` VALUES (13000, 'He resigned amid allegations of financial impropriety.', 'n. 不适当, 不适当的事物', '/,imprə\'praiəti | ,ɪmprə\'praɪətɪ | ,ɪmprə\'praɪəti/', 'impropriety', 6);
INSERT INTO `words` VALUES (13001, NULL, 'adj. 无远见的, 浪费的', '/im\'prɔvidənt | ɪm\'prɒvɪd(ə)nt | ɪm\'prɑvədənt/', 'improvident', 6);
INSERT INTO `words` VALUES (13002, 'It was the improvisation of the ebullition.', 'n. 即席创作', '/,imprəvai\'zeiʃən | ɪmprəvaɪ\'zeɪʃn | ,ɪmprəvaɪ\'zeʃən/', 'improvisation', 6);
INSERT INTO `words` VALUES (13003, 'I forgot to bring my notes, so I had to improvise.', 'v. 临时准备', '/\'imprəvaiz | \'ɪmprəvaɪz/', 'improvise', 6);
INSERT INTO `words` VALUES (13004, NULL, 'adj. 临时准备的， 即席而作的', '/\'imprəvaizd | \'ɪmprəvaɪzd/', 'improvised', 6);
INSERT INTO `words` VALUES (13005, 'The banks made hundreds of imprudent loans in the 1970s.', 'adj. 轻率的； 不理智的', '/ɪm\'pruːdnt | ɪm\'prudnt/', 'imprudent', 6);
INSERT INTO `words` VALUES (13006, 'Some of them spoke pleasantly and were well behaved, while others were impudent and insulting.', 'adj. 放肆无礼的, ,厚颜无耻的', '/\'impjudənt | \'ɪmpjʊd(ə)nt | \'ɪmpjədənt/', 'impudent', 6);
INSERT INTO `words` VALUES (13007, 'Overly proud people refuse to admit their mistakes — and sometimes even deny the fact that they make them — because they feel that it would impugn their image.', 'v. 打击', '/ɪm\'pjuːn/', 'impugn', 6);
INSERT INTO `words` VALUES (13008, NULL, 'n. 无力， 虚弱', '/ɪm\'pjuːɪsəns | im\'pju:isəns/', 'impuissance', 6);
INSERT INTO `words` VALUES (13009, 'It is the passions which provide the main impulse of music.', 'n. 推动, 刺激, 冲动, 推动力', '/\'impʌls | \'ɪmpʌls/', 'impulse', 6);
INSERT INTO `words` VALUES (13010, 'Rosa was impulsive and sometimes regretted things she’d done.', 'adj. 冲动的', '/im\'pʌlsiv | ɪm\'pʌlsɪv/', 'impulsive', 6);
INSERT INTO `words` VALUES (13011, 'It’s astonishing that these criminals are free to walk the streets with impunity.', 'n. 不受惩罚, 免罚, 无患', '/im\'pju:nəti | ɪm\'pjuːnɪtɪ | ɪm\'pjunəti/', 'impunity', 6);
INSERT INTO `words` VALUES (13012, NULL, 'n. 归罪, 归咎, 归因, 非难, 诋毁, 罪名, 污名', '/,impju:\'teiʃən | ,ɪmpjuː\'teɪʃən | ,ɪmpjʊ\'teʃən/', 'imputation', 6);
INSERT INTO `words` VALUES (13013, 'It is grossly unfair to impute blame to the United Nations.', 'v. 归罪于, 归咎于, 归因于', '/im\'pju:t | ɪm\'pjuːt/', 'impute', 6);
INSERT INTO `words` VALUES (13014, NULL, 'n. 粗心， 疏忽， 漫不经心', '/ˌɪnəd\'vɜːrtəns | ,inəd\'və:təns/', 'inadvertence', 6);
INSERT INTO `words` VALUES (13015, 'The government has said it was an inadvertent error.', 'adj. 不注意的, 疏忽的, 无意中做的', '/,inəd\'və:tənt | ,ɪnəd\'vɜːt(ə)nt | ɪnəd\'vɝtənt/', 'inadvertent', 6);
INSERT INTO `words` VALUES (13016, 'Viruses can be spread inadvertently by email users.', 'adv. 不小心地， 疏忽地', '/ˌɪnəd\'vɜːrtəntli | \'ɪnəd\'vɝtntli/', 'inadvertently', 6);
INSERT INTO `words` VALUES (13017, 'Changes in the patient’s condition may make surgery inadvisable.', 'adj. 不明智的， 不妥当的', '/ˌɪnəd\'vaɪzəbl | \'ɪnəd\'vaɪzəbl/', 'inadvisable', 6);
INSERT INTO `words` VALUES (13018, 'inalienable human rights', 'adj. (指权利等)不能让与的, 不能剥夺的', '/in\'eiljənəbl | ɪn\'eɪlɪənəb(ə)l | ɪn\'elɪənəbl/', 'inalienable', 6);
INSERT INTO `words` VALUES (13019, 'Most pop lyrics are pretty inane.', 'adj. 空洞的', '/i\'nein | ɪ\'neɪn | ɪ\'nen/', 'inane', 6);
INSERT INTO `words` VALUES (13020, 'an inanimate object', 'adj. 死气沉沉的, 没生命的, 单调的', '/in\'ænimət | ɪn\'ænɪmət/', 'inanimate', 6);
INSERT INTO `words` VALUES (13021, NULL, 'n. 空洞, 无意义, 浅薄, 愚蠢', '/,inə\'niʃən | ,ɪnə\'nɪʃ(ə)n | ,ɪnə\'nɪʃən/', 'inanition', 6);
INSERT INTO `words` VALUES (13022, 'Attempting to drown herself in inanity, she marries Peter Keating, only to leave him for newspaper tycoon Gail Wynand, publisher of the Banner, where Toohey\'s column appears.', 'n. 空虚, 愚蠢', '/i\'nænəti | ɪ\'nænətɪ/', 'inanity', 6);
INSERT INTO `words` VALUES (13023, NULL, 'adj. 微不足道的', '/ˌɪnə\'priːʃəbl | ,ɪnə\'priʃɪəbl/', 'inappreciable', 6);
INSERT INTO `words` VALUES (13024, 'There is no suggestion that clients have been sold inappropriate policies.', 'adj. 不恰当的， 不适宜的', '/ˌɪnə\'proupriət | \'ɪnə\'proprɪət/', 'inappropriate', 6);
INSERT INTO `words` VALUES (13025, 'The Turner Prize was inaugurated in 1984.', 'v. 举行就职典礼； 创始， 开创', '/ɪ\'nɔːgjəreɪt | ɪ\'nɔɡjəret/', 'inaugurate', 6);
INSERT INTO `words` VALUES (13026, 'Mammals have an inborn fear of snakes.', 'adj. 天生的, 生来的, 先天的', '/\'inbɔ:n | \'ɪnbɔːn; ɪn\'bɔːn | ,ɪn\'bɔrn/', 'inborn', 6);
INSERT INTO `words` VALUES (13027, '...a special inbound flight from Honduras.', 'adj. 内地的, 归航的', '/\'inbaund | \'ɪnbaʊnd/', 'inbound', 6);
INSERT INTO `words` VALUES (13028, 'the invention of the incandescent lamp', 'adj. 遇热发光的, 白炽的', '/,inkæn\'desənt | ɪnkæn\'des(ə)nt | \'ɪnkən\'dɛsnt/', 'incandescent', 6);
INSERT INTO `words` VALUES (13029, 'Her mother has been incapacitated by a fall.', 'v. 使无能力， 使不适合', '/ˌɪnkə\'pæsɪteɪt | ,ɪnkə\'pæsɪtet/', 'incapacitate', 6);
INSERT INTO `words` VALUES (13030, 'temporary incapacity through illness', 'n. 无能力', '/,inkə\'pæsəti | ɪnkə\'pæsɪtɪ | ,ɪnkə\'pæsəti/', 'incapacity', 6);
INSERT INTO `words` VALUES (13031, 'He spent 10 years incarcerated in prison.', 'v. 把…关进监狱， 监禁， 禁闭', '/ɪn\'kɑːrsəreɪt | ɪn\'kɑrsəret/', 'incarcerate', 6);
INSERT INTO `words` VALUES (13032, 'The iniquities of the regime are incarnated in one man.', 'v. 体现, 使具体化, 使成化身', '/in\'kɑ:nit, -neit, in\'kɑ:neit | ɪn\'kɑːnət | ɪn\'kɑrnət/', 'incarnate', 6);
INSERT INTO `words` VALUES (13033, 'She began recalling a series of previous incarnations.', 'n. 赋予肉体, 具人形, 化身', '/,inkɑ:\'neiʃən | ɪnkɑː\'neɪʃ(ə)n | ,ɪnkɑr\'neʃən/', 'incarnation', 6);
INSERT INTO `words` VALUES (13034, 'a hip-hop album with incendiary lyrics', 'adj. 纵火的, 煽动的', '/in\'sendjəri | ɪn\'sendɪərɪ | ɪn\'sɛndɪɛri/', 'incendiary', 6);
INSERT INTO `words` VALUES (13035, 'a church filled with the smell of incense', 'n. 熏香, 熏香的烟', '/\'insens | \'ɪnsens | \'ɪnsɛns/', 'incense', 6);
INSERT INTO `words` VALUES (13036, 'As an added incentive, there’s a bottle of champagne for the best team.', 'n. 动机', '/in\'sentiv | ɪn\'sentɪv | ɪn\'sɛntɪv/', 'incentive', 6);
INSERT INTO `words` VALUES (13037, NULL, 'n. 起初, 获得学位', '/in\'sepʃən | ɪn\'sepʃ(ə)n | ɪn\'sɛpʃən/', 'inception', 6);
INSERT INTO `words` VALUES (13038, NULL, 'n. 不肯定, 不确定, 无把握', '/in\'sə:titju:d | ɪn\'sɜːtɪtjuːd | ɪn\'sɝtə,tjʊd/', 'incertitude', 6);
INSERT INTO `words` VALUES (13039, 'The child’s incessant talking started to irritate her.', 'adj. 不断的, 不停的', '/in\'sesənt | ɪn\'ses(ə)nt | ɪn\'sɛsnt/', 'incessant', 6);
INSERT INTO `words` VALUES (13040, 'I inched forward along the ground.', 'v. 慢慢前进， 慢慢移动', '/ɪntʃ/', 'inch', 6);
INSERT INTO `words` VALUES (13041, 'His dreams were senseless and inchoate.', 'adj. 未形成的, 早期的, 不完全的', '/\'inkəueit, in\'kəuit | ɪn\'kəʊeɪt; \'ɪnk-; -ət | ɪn\'koɪt/', 'inchoate', 6);
INSERT INTO `words` VALUES (13042, 'The incidence of breast cancer increases with age.', 'n. 发生， 出现； 发生率', '/\'ɪnsɪdəns/', 'incidence', 6);
INSERT INTO `words` VALUES (13043, 'Increased motivation is more than an incidental benefit of reward schemes.', 'adj. 作为自然结果的， 伴随而来的； 偶然发生的', '/ˌɪnsɪ\'dentl | \'ɪnsə\'dɛntl/', 'incidental', 6);
INSERT INTO `words` VALUES (13044, 'Which is better to incinerate the rubbish from our towns or to tip it into disused quarries?', 'v. 焚化， 焚毁', '/ɪn\'sɪnəreɪt | in\'sinəreit/', 'incinerate', 6);
INSERT INTO `words` VALUES (13045, NULL, 'n. 起初, 发端', '/in\'sipiəns,-ənsi/', 'incipience', 6);
INSERT INTO `words` VALUES (13046, 'a sign of incipient madness', 'adj. 初始的', '/in\'sipiənt | ɪn\'sɪpɪənt/', 'incipient', 6);
INSERT INTO `words` VALUES (13047, 'an inscription incised in stone', 'v. 切割, 雕刻', '/in\'saiz | ɪn\'saɪz/', 'incise', 6);
INSERT INTO `words` VALUES (13048, 'The technique involves making a tiny incision in the skin.', 'n. 切割, 切开, 切口', '/in\'siʒən | ɪn\'sɪʒ(ə)n | ɪn\'sɪʒən/', 'incision', 6);
INSERT INTO `words` VALUES (13049, 'He is a very shrewd operator with an incisive mind.', 'adj. 深刻的, 尖锐的, 激烈的', '/in\'saisiv | ɪn\'saɪsɪv/', 'incisive', 6);
INSERT INTO `words` VALUES (13050, 'Hirst said the tooth, believed to be a child\'s incisor, may have come from incidents he had at school.', 'n. 门牙', '/in\'saizə | ɪn\'saɪzə | ɪn\'saɪzɚ/', 'incisor', 6);
INSERT INTO `words` VALUES (13051, 'They were charged with inciting racial hatred.', 'v. 激动, 煽动', '/in\'sait | ɪn\'saɪt/', 'incite', 6);
INSERT INTO `words` VALUES (13052, 'It is unclear how this fits with Mr Obama\'s oft-repeated pledges to bring a \"new tone\" to Washington, reach out to Republicans and work to end partisanship and incivility.', 'n. 粗野', '/,insi\'viləti | ɪnsɪ\'vɪlɪtɪ | ,ɪnsə\'vɪləti/', 'incivility', 6);
INSERT INTO `words` VALUES (13053, NULL, 'adj. 险恶的, 严酷的', '/in\'klemənt | ɪn\'klem(ə)nt | ɪn\'klɛmənt/', 'inclement', 6);
INSERT INTO `words` VALUES (13054, 'My natural inclination was to say no.', 'n. 倾斜, 弯曲, 倾度, 倾向, 爱好', '/,inkli\'neiʃən | ɪnklɪ\'neɪʃ(ə)n | \'ɪnklə\'neʃən/', 'inclination', 6);
INSERT INTO `words` VALUES (13055, 'a steep incline', 'n. 倾斜, 斜坡, 斜面', '/in\'klain | ɪn\'klaɪn/', 'incline', 6);
INSERT INTO `words` VALUES (13056, NULL, 'adj. 未经思考的， 考虑不周的', '/ɪn\'kɑːdʒɪtənt | ɪn\'kɑdʒətənt/', 'incogitant', 6);
INSERT INTO `words` VALUES (13057, 'That night, Lenin travelled incognito to the party headquarters.', 'adv. 隐名埋姓地, 化名地', '/,ɪnkɒg\'niːtəʊ; ɪn\'kɒgnɪtəʊ | ,ɪnkɑɡ\'nito/', 'incognito', 6);
INSERT INTO `words` VALUES (13058, 'Ben, drunk and incoherent, slumped in a chair.', 'adj. 不连贯的, 语无伦次的', '/,inkəu\'hiərənt | ɪnkə(ʊ)\'hɪər(ə)nt | \'ɪnko\'hɪrənt/', 'incoherent', 6);
INSERT INTO `words` VALUES (13059, 'This is my first time to face the pressure, and much of the pressure on you, even so, I still feel very incommensurate.', 'adj. 不相称的, 不适应的', '/\'inkə,menʃərət | ,ɪnkə\'menʃ(ə)rət; -sjə- | ,ɪnkə\'mɛnʃərət/', 'incommensurate', 6);
INSERT INTO `words` VALUES (13060, 'We do not ask others to be faultless , we only ask their faults should not incommode to our own .', 'v. 妨碍', '/,inkə\'məud | ɪnkə\'məʊd | ,ɪnkə\'mod/', 'incommode', 6);
INSERT INTO `words` VALUES (13061, NULL, 'a不便的, 偏促的,. 狭窄的', '/,inkə\'məudjəs | ,ɪnkə\'məʊdɪəs/', 'incommodious', 6);
INSERT INTO `words` VALUES (13062, 'He was held incommunicado in prison for ten days before being released without charge.', 'adj. 禁止通信的, 被单独囚禁的', '/\'inkə,mju:ni\'kɑ:dəu | ,ɪnkəmjuːnɪ\'kɑːdəʊ | ,ɪnkə,mjunɪ\'kɑdo/', 'incommunicado', 6);
INSERT INTO `words` VALUES (13063, NULL, 'adj. 不爱说话的, 沉默寡言的', '/,inkə\'mju:nikətiv | ɪnkə\'mjuːnɪkətɪv | ,ɪnkə\'mjʊnə,ketɪv/', 'incommunicative', 6);
INSERT INTO `words` VALUES (13064, 'It is the incompatibility of systems under such a circumstance that leads to the cancer.', 'n. 不相容', '/\'ɪnkəmˌpætə\'bɪləti | \'ɪnkəm,pætə\'bɪləti/', 'incompatibility', 6);
INSERT INTO `words` VALUES (13065, 'They feel strongly that their religion is incompatible with the political system.', 'adj. 性质相反的, 矛盾的, 不调和的', '/,inkəm\'pætəbl | ɪnkəm\'pætɪb(ə)l | ,ɪnkəm\'pætəbl/', 'incompatible', 6);
INSERT INTO `words` VALUES (13066, 'an incompetent manager', 'adj. 不合格的, 不胜任的', '/in\'kɔmpitənt | ɪn\'kɒmpɪt(ə)nt | ɪn\'kɑmpɪtənt/', 'incompetent', 6);
INSERT INTO `words` VALUES (13067, 'Unfortunately, I do not have the information because our records are incomplete.', 'adj. 不完全的， 不完整的', '/ˌɪnkəm\'pliːt | \'ɪnkəm\'plit/', 'incomplete', 6);
INSERT INTO `words` VALUES (13068, 'legal documents full of incomprehensible jargon', 'adj. 难以理解的， 难懂的', '/ɪnˌkɑːmprɪ\'hensəbl | ɪn,kɑmprɪ\'hɛnsəbl/', 'incomprehensible', 6);
INSERT INTO `words` VALUES (13069, 'A few years ago a car fuelled by solar energy would have been inconceivable.', 'adj. 不能想像的, 难以相信的', '/,inkən\'si:vəbl | ɪnkən\'siːvəb(ə)l | ,ɪnkən\'sivəbl/', 'inconceivable', 6);
INSERT INTO `words` VALUES (13070, 'The evidence against the two men was inconclusive.', 'adj. 非决定性的； 无定论的', '/ˌɪnkən\'kluːsɪv | ,ɪnkən\'klusɪv/', 'inconclusive', 6);
INSERT INTO `words` VALUES (13071, NULL, 'adj. 不协调的， 不和谐的， 不合适的', '/ɪn\'kɑːŋgruənt | ɪn\'kɑŋgrʊənt/', 'incongruent', 6);
INSERT INTO `words` VALUES (13072, 'The incongruity of her situation struck Gina with unpleasant force.', 'n. 不调和的, 不适宜的', '/,inkɔŋ\'ɡru:əti | ,ɪnkɒŋ\'gruːɪtɪ | ,ɪnkɑŋ\'grʊəti/', 'incongruity', 6);
INSERT INTO `words` VALUES (13073, 'The new theatre looks utterly incongruous in its setting.', 'adj. 不调和的, 不适宜的', '/in\'kɔŋɡruəs | ɪn\'kɒŋgrʊəs | ɪn\'kɑŋɡruəs/', 'incongruous', 6);
INSERT INTO `words` VALUES (13074, 'inconsequential but amusing chatter', 'adj. 不合逻辑的, 不合理的', '/,inkɔnsi\'kwenʃəl | ,ɪnkɒnsɪ\'kwenʃ(ə)l | ɪn\'kɑnsə\'kwɛnʃəl/', 'inconsequential', 6);
INSERT INTO `words` VALUES (13075, 'inconsiderate motorists', 'adj. 不顾及别人的, 轻率的', '/,inkən\'sidərət | ɪnkən\'sɪd(ə)rət | ,ɪnkən\'sɪdərət/', 'inconsiderate', 6);
INSERT INTO `words` VALUES (13076, 'The boy was inconsolable after the death of his dog.', 'adj. 无法安慰的, 极为伤心的', '/,inkən\'səuləbl | ɪnkən\'səʊləb(ə)l | \'ɪnkən\'soləbl/', 'inconsolable', 6);
INSERT INTO `words` VALUES (13077, 'The perfume of this passionate plant may turn a maiden\'s head, hence wild honeysuckle is a symbol of inconstancy in love.', 'n. 反复无常', '/in\'kɔnstənsi | ɪn\'kɑːnstənsi/', 'inconstancy', 6);
INSERT INTO `words` VALUES (13078, 'The theological critique is that Homer simply depicts the gods as false, as fickle, and inconstant.', 'adj. 变化无常的', '/in\'kɔnstənt | ɪn\'kɒnst(ə)nt | ɪn\'kɑnstənt/', 'inconstant', 6);
INSERT INTO `words` VALUES (13079, 'We had incontestable proof of her innocence.', 'adj. 无可争辩的, 无可置疑的, 不可否认的', '/,inkən\'testəbl | ɪnkən\'testəb(ə)l | \'ɪnkən\'tɛstəbl/', 'incontestable', 6);
INSERT INTO `words` VALUES (13080, 'His diseased bladder left him incontinent.', 'adj. 不能自制的, 无节制的, 荒淫的, [医]失禁的', '/in\'kɔntinənt | ɪn\'kɒntɪnənt/', 'incontinent', 6);
INSERT INTO `words` VALUES (13081, 'CCTV provided incontrovertible evidence that he was at the scene of the crime.', 'adj. 无可辩驳的， 不容置疑的', '/ˌɪnkɑːntrə\'vɜːrtəbl | ,ɪnkɑntrə\'vɝtəbl/', 'incontrovertible', 6);
INSERT INTO `words` VALUES (13082, 'Monday’s a bit inconvenient for me. How about Wednesday?', 'adj. 不便的， 打扰的， 造成麻烦的', '/ˌɪnkən\'viːniənt | ,ɪnkən\'vinɪənt/', 'inconvenient', 6);
INSERT INTO `words` VALUES (13083, 'The agreement would allow the rebels to be incorporated into a new national police force.', 'adj. 合并的, 结社的, 一体化的', '/in\'kɔ:pəreit, in\'kɔ:pərət | ɪn\'kɔːpəreɪt/', 'incorporate', 6);
INSERT INTO `words` VALUES (13084, 'Plato demonstrated the incorporeal nature of the soul.', 'adj. 非物质的, 无实体的, 灵魂的, 无形体的', '/,inkɔ:\'pɔ:riəl | ,ɪnkɔː\'pɔːrɪəl/', 'incorporeal', 6);
INSERT INTO `words` VALUES (13085, NULL, 'n. 无可救药', '/in,kɔridʒə\'biləti | ɪnˌkɔrɪdʒə\'bɪləti/', 'incorrigibility', 6);
INSERT INTO `words` VALUES (13086, '\"Sunita, you are incorrigible!\" he said.', 'adj. 无药可救的, 不能被纠正的', '/in\'kɔridʒəbl | ɪn\'kɒrɪdʒɪb(ə)l | ɪn\'kɔrɪdʒəbl/', 'incorrigible', 6);
INSERT INTO `words` VALUES (13087, 'A good judge must be incorruptible.', 'adj. 廉洁的， 不腐败的', '/ˌɪnkə\'rʌptəbl | ,ɪnkə\'rʌptəbl/', 'incorruptible', 6);
INSERT INTO `words` VALUES (13088, 'When she told her family she was gay, they reacted with a mixture of shock and incredulity.', 'n. 怀疑， 不相信', '/ˌɪnkrə\'duːləti | ,ɪnkrə\'djʊləti/', 'incredulity', 6);
INSERT INTO `words` VALUES (13089, 'The average yearly increment in productivity was 4.5 per cent.', 'n. 增加, 增量', '/\'inkrimənt | \'ɪŋkrɪm(ə)nt | \'ɪŋkrəmənt/', 'increment', 6);
INSERT INTO `words` VALUES (13090, NULL, 'v. 连累， 牵连', '/ɪn\'krɪmɪneɪt | ɪn\'krɪmɪnet/', 'incriminate', 6);
INSERT INTO `words` VALUES (13091, NULL, 'n. 结壳, 用覆盖物, 镶嵌, 硬壳', '/,inkrʌs\'teiʃən | ,ɪnkrʌs\'teɪʃən | ,ɪnkrʌ\'steʃən/', 'incrustation', 6);
INSERT INTO `words` VALUES (13092, NULL, 'n. 孵蛋, 抱蛋, 熟虑', '/,inkju\'beiʃən | ɪŋkjʊ\'beɪʃ(ə)n | ,ɪŋkju\'beʃən/', 'incubation', 6);
INSERT INTO `words` VALUES (13093, 'a high-tech incubator on the east coast', 'n. 培养的器具, 孵卵器, 早产儿保育器', '/\'inkjubeitə | \'ɪŋkjʊbeɪtə | \'ɪŋkjubetɚ/', 'incubator', 6);
INSERT INTO `words` VALUES (13094, 'Joyce regarded his US citizenship as a moral and political incubus.', 'n. 梦魇, 沉重的负担', '/\'iŋkjubəs | \'ɪŋkjʊbəs/', 'incubus', 6);
INSERT INTO `words` VALUES (13095, 'Not all schools manage to successfully inculcate a love of learning.', 'v. 谆谆劝导', '/\'inkʌlkeit, in\'kʌl- | \'ɪnkʌlkeɪt | ɪn\'kʌlket/', 'inculcate', 6);
INSERT INTO `words` VALUES (13096, NULL, 'v. 控告； 归咎于', '/\'ɪnkʌlpeɪt | \'inkʌlpeit/', 'inculpate', 6);
INSERT INTO `words` VALUES (13097, NULL, 'adj. 没有开垦的, 没有耕种的, 没有教养的', '/ɪn\'kʌlt/', 'incult', 6);
INSERT INTO `words` VALUES (13098, NULL, 'n. 责任, 义务, 任职, 压', '/in\'kʌmbənsi | ɪn\'kʌmb(ə)nsɪ/', 'incumbency', 6);
INSERT INTO `words` VALUES (13099, 'In the June elections, Morris easily defeated the incumbent, Tom Smith.', 'adj. 义不容辞的; n. 在职者，现任者', '/ɪn\'kʌmbənt/', 'incumbent', 6);
INSERT INTO `words` VALUES (13100, 'The government had also incurred huge debts.', 'v. 招致', '/in\'kə: | ɪn\'kɜː | ɪn\'kɝ/', 'incur', 6);
INSERT INTO `words` VALUES (13101, 'an incurable optimist', 'adj. 不能治愈的', '/in\'kjuərəbl | ɪn\'kjʊərəb(ə)l | ɪn\'kjʊrəbl/', 'incurable', 6);
INSERT INTO `words` VALUES (13102, '...armed incursions into border areas by rebel forces.', 'n. 袭击, 侵入', '/in\'kə:ʃən | ɪn\'kɜːʃ(ə)n | ɪn\'kɝʒn/', 'incursion', 6);
INSERT INTO `words` VALUES (13103, 'the 17 most heavily indebted nations', 'adj. 负债的, 感恩的', '/in\'detid | ɪn\'detɪd | ɪn\'dɛtɪd/', 'indebted', 6);
INSERT INTO `words` VALUES (13104, 'Majid\'s writing was virtually indecipherable.', 'adj. 无法破译的', '/ˌɪndɪ\'saɪfrəbl | \'ɪndɪ\'saɪfrəbl/', 'indecipherable', 6);
INSERT INTO `words` VALUES (13105, 'His indefatigable spirit helped him to cope with his illness.', 'adj. 不知疲倦的', '/,indi\'fætiɡəbl | ,ɪndɪ\'fætɪgəb(ə)l | ,ɪndɪ\'fætɪɡəbl/', 'indefatigable', 6);
INSERT INTO `words` VALUES (13106, 'Teachers find the report’s terminology so indefinite that it is confusing.', 'adj. 模糊的, 不确定的, [语]不定的', '/in\'definət | ɪn\'defɪnɪt | ɪn\'dɛfɪnət/', 'indefinite', 6);
INSERT INTO `words` VALUES (13107, 'It leaves indelible stains on clothes.', 'adj. 去不掉的, 不能拭除的', '/in\'deləbl | ɪn\'delɪb(ə)l | ɪn\'dɛləbl/', 'indelible', 6);
INSERT INTO `words` VALUES (13108, NULL, 'n. 保护, 保障, 补偿, 补偿物', '/in,demnifi\'keiʃən | ɪn,demnɪfɪ\'keɪʃən/', 'indemnification', 6);
INSERT INTO `words` VALUES (13109, 'They agreed to indemnify the taxpayers against any loss.', 'v. 赔偿', '/in\'demnifai | ɪn\'demnɪfaɪ | ɪn\'dɛmnɪfaɪ/', 'indemnify', 6);
INSERT INTO `words` VALUES (13110, NULL, 'n. 缩进, 契约, 订货单, 凹痕', '/in\'dent, \'indent | ɪn\'dent | ɪn\'dɛnt/', 'indent', 6);
INSERT INTO `words` VALUES (13111, 'Make an indentation in the center of each cookie.', 'n. 缩排, 呈锯齿状, 缺口, 印凹痕', '/,inden\'teiʃən | ɪnden\'teɪʃ(ə)n | ,ɪndɛn\'teʃən/', 'indentation', 6);
INSERT INTO `words` VALUES (13112, 'our deeply indented coastline', 'adj. 锯齿状的, 犬牙交错的', '/in\'dentid | ɪn\'dentɪd | ɪn\'dɛntɪd/', 'indented', 6);
INSERT INTO `words` VALUES (13113, 'Thirdly, the paper illustrates the life cycle of agriculture VR&DO and discusses the operating mode of it on the basis of dynamic network indenture.', 'n. 契约', '/in\'dentʃə | ɪn\'dentʃə | ɪn\'dɛntʃɚ/', 'indenture', 6);
INSERT INTO `words` VALUES (13114, 'a feeling of indescribable joy', 'adj. 难以形容的', '/,indi\'skraibəbl | ɪndɪ\'skraɪbəb(ə)l | ,ɪndɪ\'skraɪbəbl/', 'indescribable', 6);
INSERT INTO `words` VALUES (13115, 'her indestructible optimism', 'adj. 不能破坏的， 不可毁灭的', '/ˌɪndɪ\'strʌktəbl | ,ɪndɪ\'strʌktəbl/', 'indestructible', 6);
INSERT INTO `words` VALUES (13116, 'The study indicates a connection between poverty and crime.', 'v. 指示， 指出； 象征， 显示', '/\'ɪndɪkeɪt | \'ɪndɪket/', 'indicate', 6);
INSERT INTO `words` VALUES (13117, 'He was later indicted on corruption charges.', 'v. 起诉, 控告, 指控, 告发', '/in\'dait | ɪn\'daɪt/', 'indict', 6);
INSERT INTO `words` VALUES (13118, 'People have become indifferent to the suffering of others.', 'adj. 无关紧要的', '/in\'difərənt | ɪn\'dɪf(ə)r(ə)nt | ɪn\'dɪfrənt/', 'indifferent', 6);
INSERT INTO `words` VALUES (13119, 'For one of the poets has said, \'Application to business is the root of prosperity, but those who ask questions that do not concern them are steering the ship of folly towards the rock of indigence\'.', 'n. 贫穷， 贫困', '/\'ɪndɪdʒəns | \'indidʒəns,-dʒənsi/', 'indigence', 6);
INSERT INTO `words` VALUES (13120, 'the many indigenous cultures which existed in Siberia', 'adj. 本土的', '/in\'didʒinəs | ɪn\'dɪdʒɪnəs | ɪn\'dɪdʒənəs/', 'indigenous', 6);
INSERT INTO `words` VALUES (13121, 'Among them: How could the states afford to supply lawyers to all indigent defendants?', 'adj. 贫乏的, 穷困的', '/\'indidʒənt | \'ɪndɪdʒ(ə)nt | \'ɪndɪdʒənt/', 'indigent', 6);
INSERT INTO `words` VALUES (13122, 'an indignant reply', 'adj. 愤怒的, 愤慨的', '/in\'diɡnənt | ɪn\'dɪgnənt | ɪn\'dɪɡnənt/', 'indignant', 6);
INSERT INTO `words` VALUES (13123, 'To his indignation, Charles found that his name was not on the list.', 'n. 愤慨, 义愤', '/,indiɡ\'neiʃən | ɪndɪg\'neɪʃ(ə)n | ,ɪndɪɡ\'neʃən/', 'indignation', 6);
INSERT INTO `words` VALUES (13124, 'The prisoners were subjected to all sorts of indignities.', 'n. 侮辱， 轻蔑； 侮辱性的行为', '/ɪn\'dɪgnəti | ɪn\'dɪɡnəti/', 'indignity', 6);
INSERT INTO `words` VALUES (13125, NULL, 'n. 靛, 靛青', '/\'indiɡəu | \'ɪndɪgəʊ | \'ɪndɪɡo/', 'indigo', 6);
INSERT INTO `words` VALUES (13126, 'The path was almost indiscernible in the mist.', 'adj. 难识别的, 看不见的', '/,indi\'sə:nəbl | ,ɪndɪ\'sɜːnɪb(ə)l/', 'indiscernible', 6);
INSERT INTO `words` VALUES (13127, 'It was very indiscreet of Colin to tell them about our plan.', 'adj. 不慎重的, 轻率的', '/,indis\'kri:t | ɪndɪ\'skriːt | \'ɪndɪ\'skrit/', 'indiscreet', 6);
INSERT INTO `words` VALUES (13128, 'Earl describes his past links with the racist group as a youthful indiscretion.', 'n. 欠详虑, 不慎重, 轻率, 轻举妄动', '/,indis\'kreʃən | ɪndɪ\'skreʃ(ə)n | \'ɪndɪ\'skrɛʃən/', 'indiscretion', 6);
INSERT INTO `words` VALUES (13129, 'the indiscriminate use of chemical fertilizers', 'adj. 不分皂白的, 不加选择的', '/,indis\'kriminət | ,ɪndɪ\'skrɪmɪnət/', 'indiscriminate', 6);
INSERT INTO `words` VALUES (13130, NULL, 'adv. 随意地， 任意地', '/ˌɪndɪ\'skrɪmɪnətli | indi\'skriminitli/', 'indiscriminately', 6);
INSERT INTO `words` VALUES (13131, 'To be without some of the things you wan is an indispensable part of happiness.', 'n. 不可缺少之物', '/,indis\'pensəbl | ɪndɪ\'spensəb(ə)l | \'ɪndɪ\'spɛnsəbl/', 'indispensable', 6);
INSERT INTO `words` VALUES (13132, 'The speaker was regrettably indisposed.', 'adj. 不舒服的, 不合适的', '/,indis\'pəuzd | ɪndɪ\'spəʊzd | ,ɪndɪ\'spozd/', 'indisposed', 6);
INSERT INTO `words` VALUES (13133, 'Replica weapons are indistinguishable from the real thing.', 'adj. 无法区分的， 难以分辨的', '/ˌɪndɪ\'stɪŋgwɪʃəbl | \'ɪndɪ\'stɪŋgwɪʃəbl/', 'indistinguishable', 6);
INSERT INTO `words` VALUES (13134, 'The Xinluo students were accomplished in the Confucianism sutra, could compose in types of literature and indite many excellent Chinese writings.', 'v. 写(文章,信等)创作, 赋诗, 创作', '/in\'dait | ɪn\'daɪt/', 'indite', 6);
INSERT INTO `words` VALUES (13135, 'Each individual leaf on the tree is different.', 'adj. 单独的，单个的；特有的；个人的，个体的; n. 个人， 个体', '/ˌɪndɪ\'vɪdʒuəl | ˌɪndəˈvɪdʒʊəl/', 'individual', 6);
INSERT INTO `words` VALUES (13136, 'Capitalism encourages competition and individualism.', 'n. 个人主义', '/ˌɪndɪ\'vɪdʒuəlɪzəm | ,ɪndɪ\'vɪdʒuəlɪzəm/', 'individualism', 6);
INSERT INTO `words` VALUES (13137, 'Far from being separate, the mind and body form an indivisible whole.', 'adj. 不能分割的, 除不尽的', '/,indi\'vizəbl | ɪndɪ\'vɪzɪb(ə)l | \'ɪndə\'vɪzəbl/', 'indivisible', 6);
INSERT INTO `words` VALUES (13138, 'The student of average middle school is really indocile !', 'adj. 难驯服的', '/in\'dəusail | ɪn\'dəʊsaɪl/', 'indocile', 6);
INSERT INTO `words` VALUES (13139, 'People were indoctrinated not to question their leaders.', 'v. 灌输', '/in\'dɔktrineit | ɪn\'dɒktrɪneɪt | ɪn\'dɑktrɪnet/', 'indoctrinate', 6);
INSERT INTO `words` VALUES (13140, 'The former investment banker has not been indolent: his department has been a factory for acronyms since the crisis began.', 'adj. 懒惰的, 不痛的', '/\'indələnt | \'ɪnd(ə)l(ə)nt | \'ɪndələnt/', 'indolent', 6);
INSERT INTO `words` VALUES (13141, 'an indomitable old lady', 'adj. 不屈服的, 不屈不挠的', '/in\'dəumitəbl | ɪn\'dɒmɪtəb(ə)l | ɪn\'dɑmɪtəbl/', 'indomitable', 6);
INSERT INTO `words` VALUES (13142, 'His brilliance renders this film an indubitable classic.', 'adj. 不容置疑的, 确实的, 明白的', '/in\'dju:bitəbl | ɪn\'djuːbɪtəb(ə)l/', 'indubitable', 6);
INSERT INTO `words` VALUES (13143, 'Mr Sachs is indubitably charming.', 'adv. 无疑地， 确实地', '/in\'dju:bitəbli | ɪn\'duːbɪtəbli/', 'indubitably', 6);
INSERT INTO `words` VALUES (13144, 'Patients with eating disorders may use drugs to induce vomiting.', 'v. 劝诱, 促使, 导致, 引起, 感应', '/in\'dju:s, in\'du:s | ɪn\'djuːs | ɪn\'dus/', 'induce', 6);
INSERT INTO `words` VALUES (13145, 'financial inducements to attract good job candidates', 'n. 诱导, 诱因, 动机, 刺激物', '/in\'dju:smənt | ɪn\'djuːsm(ə)nt | ɪn\'dusmənt/', 'inducement', 6);
INSERT INTO `words` VALUES (13146, 'This diauxie curve is typical of inducible enzymes.', 'adj. 可诱导的', '/in\'dju:səbl | ɪn\'duːsəbl/', 'inducible', 6);
INSERT INTO `words` VALUES (13147, NULL, 'v. 感应', '/in\'dʌkt | ɪn\'dʌkt/', 'induct', 6);
INSERT INTO `words` VALUES (13148, 'Mrs Simpson is responsible for the induction of new library staff.', 'n. 感应, 感应现象, 归纳', '/ɪn\'dʌkʃ(ə)n | ɪn\'dʌkʃən/', 'induction', 6);
INSERT INTO `words` VALUES (13149, 'His mother spoiled him, indulging his every whim.', 'v. 放纵， 纵容； 满足', '/ɪn\'dʌldʒ/', 'indulge', 6);
INSERT INTO `words` VALUES (13150, 'toys bought by their indulgent grandparents', 'adj. 放纵的， 纵容的', '/ɪn\'dʌldʒənt/', 'indulgent', 6);
INSERT INTO `words` VALUES (13151, 'She was an industrious and willing worker.', 'adj. 勤劳的， 勤勉的', '/ɪn\'dʌstriəs | ɪn\'dʌstrɪəs/', 'industrious', 6);
INSERT INTO `words` VALUES (13152, 'To rise thither with my inebriate Soul!', 'v. 灌醉', '/i\'ni:briət | ɪ\'niːbrɪeɪt/', 'inebriate', 6);
INSERT INTO `words` VALUES (13153, 'The meat was so burnt that it was inedible.', 'adj. 不能吃的， 不可食的', '/ɪn\'edəbl | ɪn\'ɛdəbl/', 'inedible', 6);
INSERT INTO `words` VALUES (13154, 'ineffable joy', 'adj. 不能说的, 不应说出的, 避讳的', '/in\'efəbl | ɪn\'efəb(ə)l | ɪn\'ɛfəbl/', 'ineffable', 6);
INSERT INTO `words` VALUES (13155, NULL, 'adj. 不能除去的, 不能取消的', '/ɪnɪ\'feɪsəb(ə)l | ,ini\'feisəbl/', 'ineffaceable', 6);
INSERT INTO `words` VALUES (13156, 'an inefficient use of resources', 'adj. 无效率的； 无能的， 不称职的', '/ˌɪnɪ\'fɪʃnt | ,ɪnɪ\'fɪʃnt/', 'inefficient', 6);
INSERT INTO `words` VALUES (13157, 'Unitary elasticity is the coincidental case that is just on the borderline between elastic and inelastic .', 'adj. 无弹性的', '/ˌɪnɪ\'læstɪk | ɪnɪ\'læstɪk/', 'inelastic', 6);
INSERT INTO `words` VALUES (13158, NULL, 'n. 无弹性， 无伸缩性', '/,inilæs\'tisəti, in,elæs\'tisəti | ˌɪnɪlæ\'stɪsəti/', 'inelasticity', 6);
INSERT INTO `words` VALUES (13159, 'They were ineligible to remain in the U.S.', 'adj. 不合格的', '/in\'elidʒəbl | ɪn\'elɪdʒɪb(ə)l | ɪn\'ɛlɪdʒəbl/', 'ineligible', 6);
INSERT INTO `words` VALUES (13160, '...the ineluctable tendency of populations to exceed resources.', 'adj. 不可避免的, 无法逃避的', '/,ini\'lʌktəbl | ,ɪnɪ\'lʌktəb(ə)l | ,ɪnɪ\'lʌktəbl/', 'ineluctable', 6);
INSERT INTO `words` VALUES (13161, 'inept leadership', 'adj. 不适当的, 无能的, 不称职的', '/i\'nept | ɪ\'nept/', 'inept', 6);
INSERT INTO `words` VALUES (13162, 'the ineptitude of the people in charge', 'n. 不称职', '/i\'neptitju:d | ɪ\'neptɪtjuːd | ɪ\'nɛptə\'tʊd/', 'ineptitude', 6);
INSERT INTO `words` VALUES (13163, 'inert gases', 'adj. 无活动的, 惰性的, 迟钝的', '/i\'nə:t | ɪ\'nɜːt | ɪ\'nɝt/', 'inert', 6);
INSERT INTO `words` VALUES (13164, 'Galileo and Descartes replaced that with the idea of inertia.', 'n. 惯性, 惯量', '/i\'nə:ʃiə | ɪ\'nɜːʃə | ɪ\'nɝʃə/', 'inertia', 6);
INSERT INTO `words` VALUES (13165, 'a painting of inestimable value', 'adj. 无法估计的； 无价的， 极有价值的', '/ɪn\'estɪməbl | ɪn\'ɛstɪməbl/', 'inestimable', 6);
INSERT INTO `words` VALUES (13166, 'A further escalation of the crisis now seems inevitable.', 'adj. 不可避免的， 必然的', '/ɪn\'evɪtəbl | ɪn\'ɛvɪtəbl/', 'inevitable', 6);
INSERT INTO `words` VALUES (13167, 'an inexcusable act of aggression', 'adj. 不可原谅的， 不可宽恕的', '/ˌɪnɪk\'skjuːzəbl | ,ɪnɪk\'skjuzəbl/', 'inexcusable', 6);
INSERT INTO `words` VALUES (13168, 'She has an inexhaustible supply of funny stories.', 'adj. 无穷无尽的', '/,iniɡ\'zɔ:stəbl | ɪnɪg\'zɔːstɪb(ə)l; ɪneg- | ,ɪnɪɡ\'zɔstəbl/', 'inexhaustible', 6);
INSERT INTO `words` VALUES (13169, 'the inexorable decline of Britain’s manufacturing industry', 'adj. 无情的', '/in\'eksərəbl | ɪn\'eks(ə)rəb(ə)l | ɪn\'ɛksərəbl/', 'inexorable', 6);
INSERT INTO `words` VALUES (13170, 'The way to change the phases of slacken production, inexpedient circulation is to realize the limited austerity.', 'adj. 不适宜的', '/,inik\'spi:djəns | ɪnɪk\'spiːdɪənt; ɪnek- | ,ɪnɪk\'spidɪənt/', 'inexpedient', 6);
INSERT INTO `words` VALUES (13171, 'a good selection of inexpensive wines', 'adj. 廉价的， 便宜的', '/ˌɪnɪk\'spensɪv | ,ɪnɪk\'spɛnsɪv/', 'inexpensive', 6);
INSERT INTO `words` VALUES (13172, 'It is inexpiable because God\'s gift itself is of such transcendence and holiness that it cannot be paid off by finite animal beings such as we are.', 'adj. 不能抵偿的, 不能平息的', '/in\'ekspiəbl | ɪn\'ekspɪəb(ə)l | ɪn\'ɛkspɪəbl/', 'inexpiable', 6);
INSERT INTO `words` VALUES (13173, 'inexplicable behaviour', 'adj. 无法说明的', '/,inik\'splikəbl | ,ɪnɪk\'splɪkəb(ə)l; ,ɪnek-; ɪn\'eksplɪ- | ,ɪnɪk\'splɪkəbl/', 'inexplicable', 6);
INSERT INTO `words` VALUES (13174, 'the inextricable connection between language and culture', 'adj. 无法解脱的, 逃脱不掉的, 解不开的', '/in\'ekstrikəbl | ɪn\'ekstrɪkəb(ə)l; ,ɪnɪk\'strɪk-; ,ɪnek- | \'ɪnɪk\'strɪkəbl/', 'inextricable', 6);
INSERT INTO `words` VALUES (13175, NULL, 'n. 绝无错误, 绝对可靠性', '/in,fælə\'biləti/', 'infallibility', 6);
INSERT INTO `words` VALUES (13176, 'No expert is infallible.', 'adj. 没有错误的, 确实可靠的', '/in\'fæləbl | ɪn\'fælɪb(ə)l | ɪn\'fæləbl/', 'infallible', 6);
INSERT INTO `words` VALUES (13177, 'an infamous killer', 'adj. 声名狼籍的', '/\'infəməs | \'ɪnfəməs/', 'infamous', 6);
INSERT INTO `words` VALUES (13178, '...one of the greatest acts of infamy in history.', 'n. 声名狼藉, 丑名, 丑行', '/\'ɪnfəmɪ | \'ɪnfəmi/', 'infamy', 6);
INSERT INTO `words` VALUES (13179, 'An infant’s skin is very sensitive.', 'n. 婴儿', '/\'ɪnfənt/', 'infant', 6);
INSERT INTO `words` VALUES (13180, 'infantile jokes', 'adj. 婴儿的, 幼稚的, 适于婴儿的初期的', '/\'infəntail | \'ɪnf(ə)ntaɪl | \'ɪnfəntaɪl/', 'infantile', 6);
INSERT INTO `words` VALUES (13181, 'an infantry regiment', 'n. 步兵, 步兵团', '/\'infəntri | \'ɪnf(ə)ntrɪ | \'ɪnfəntri/', 'infantry', 6);
INSERT INTO `words` VALUES (13182, NULL, 'v. 使迷恋； 使糊涂', '/ɪn\'fætʃueɪt | ɪn\'fætjʊɪt/', 'infatuate', 6);
INSERT INTO `words` VALUES (13183, 'He was utterly infatuated with her.', 'adj. 昏头昏脑的, 入迷的', '/in\'fæfjueitid | ɪn\'fætjʊeɪtɪd | ɪn\'fætʃuetɪd/', 'infatuated', 6);
INSERT INTO `words` VALUES (13184, NULL, 'n. 愚蠢, 糊涂, 醉心', '/in,fætju\'eiʃən | ɪn,fætʃʊ\'eɪʃ(ə)n; -tjʊ- | ɪn,fætʃu\'eʃən/', 'infatuation', 6);
INSERT INTO `words` VALUES (13185, 'People with the virus may feel perfectly well, but they can still infect others.', 'v. 传染； 使感染， 侵染； 污染', '/ɪn\'fekt | ɪn\'fɛkt/', 'infect', 6);
INSERT INTO `words` VALUES (13186, 'The baby had an ear infection.', 'n. 传染； 感染', '/ɪn\'fekʃn | ɪn\'fɛkʃən/', 'infection', 6);
INSERT INTO `words` VALUES (13187, 'infectious diseases', 'adj. 传染的， 有传染性的', '/ɪn\'fekʃəs | ɪn\'fɛkʃəs/', 'infectious', 6);
INSERT INTO `words` VALUES (13188, 'Infelicitous remark; infelicitous phrasing infelicitous typesetting was due to illegiblecopy.', 'adj. 不吉利的, 不幸的, 不合适的', '/,infi\'lisitəs | ɪnfɪ\'lɪsɪtəs/', 'infelicitous', 6);
INSERT INTO `words` VALUES (13189, 'There is so much infelicity in the world.', 'n. 不幸； 不恰当的事物', '/ˌɪnfɪ\'lɪsɪti | ,ɪnfə\'lɪsəti/', 'infelicity', 6);
INSERT INTO `words` VALUES (13190, 'I inferred from what she said that you have not been well.', 'v. 推断， 推论， 推理', '/ɪn\'fɜːr | ɪn\'fɝ/', 'infer', 6);
INSERT INTO `words` VALUES (13191, NULL, 'adj. 能推理的， 能推论的', '/ɪn\'fɜːrəbl | ɪn\'fɝəbl/', 'inferable', 6);
INSERT INTO `words` VALUES (13192, 'I felt very inferior among all those academics.', 'adj. 下级的， 下属的； 低等的， 较差的', '/ɪn\'fɪriər | ɪn\'fɪrɪɚ/', 'inferior', 6);
INSERT INTO `words` VALUES (13193, 'I wish the children would stop that infernal noise.', 'adj. 阴间的, 恶魔的', '/in\'fə:nəl | ɪn\'fɜːn(ə)l/', 'infernal', 6);
INSERT INTO `words` VALUES (13194, NULL, 'n. 阴间, 地狱', '/in\'fə:nəu | ɪn\'fɜːnəʊ/', 'inferno', 6);
INSERT INTO `words` VALUES (13195, 'infertile couples', 'adj. 不肥沃的, 贫瘠的, 不毛的, 不结果实的', '/in\'fə:tail, -til | ɪn\'fɜːtaɪl | ɪn\'fɝtl/', 'infertile', 6);
INSERT INTO `words` VALUES (13196, '...pests like aphids which infest cereal crops.', 'v. 大批滋生', '/in\'fest | ɪn\'fest | ɪn\'fɛst/', 'infest', 6);
INSERT INTO `words` VALUES (13197, 'He promised to continue the fight against infidel forces.', 'adj. 不信宗教的, 异端的', '/\'infidəl | \'ɪnfɪd(ə)l | \'ɪnfədl/', 'infidel', 6);
INSERT INTO `words` VALUES (13198, NULL, 'n. 失真', '/,infi\'deləti | ɪnfɪ\'delɪtɪ | ,ɪnfɪ\'dɛləti/', 'infidelity', 6);
INSERT INTO `words` VALUES (13199, 'Police attempts to infiltrate neo-Nazi groups were largely unsuccessful.', 'v. 渗透', '/\'infiltreit, in\'fil- | \'ɪnfɪltreɪt | ɪn\'fɪltret/', 'infiltrate', 6);
INSERT INTO `words` VALUES (13200, 'infinitesimal changes in temperature', 'adj. 无穷小的, 极小的, 无限小的', '/,infini\'tesiməl | ,ɪnfɪnɪ\'tesɪm(ə)l | \'ɪnfɪnə\'tɛsəml/', 'infinitesimal', 6);
INSERT INTO `words` VALUES (13201, 'the infinity of space', 'n. 无限, 无穷大', '/in\'finəti | ɪn\'fɪnɪtɪ | ɪn\'fɪnəti/', 'infinity', 6);
INSERT INTO `words` VALUES (13202, 'Her grandmother is elderly and infirm.', 'adj. 虚弱的', '/ɪn\'fɜːrm | ɪn\'fɝm/', 'infirm', 6);
INSERT INTO `words` VALUES (13203, NULL, 'n. 虚弱, 衰弱, 缺点', '/in\'fə:məti | ɪn\'fɜːmətɪ | ɪn\'fɝməti/', 'infirmity', 6);
INSERT INTO `words` VALUES (13204, 'The shooting inflamed ethnic tensions.', 'v. 燃烧', '/in\'fleim | ɪn\'fleɪm | ɪn\'flem/', 'inflame', 6);
INSERT INTO `words` VALUES (13205, 'an inflamed eye', 'adj. 发炎的；红肿的', '/in\'fleimd | ɪn\'flemd/', 'inflamed', 6);
INSERT INTO `words` VALUES (13206, 'Petrol is highly inflammable.', 'adj. 易燃的, 易怒的', '/in\'flæməbl | ɪn\'flæməb(ə)l | ɪn\'flæməbl/', 'inflammable', 6);
INSERT INTO `words` VALUES (13207, 'The drug can cause inflammation of the liver.', 'n. 发炎； 炎症', '/ˌɪnflə\'meɪʃn | \'ɪnflə\'meʃən/', 'inflammation', 6);
INSERT INTO `words` VALUES (13208, 'It took us half an hour to inflate the dinghy.', 'v. 使充气， 使膨胀', '/ɪn\'fleɪt | ɪn\'flet/', 'inflate', 6);
INSERT INTO `words` VALUES (13209, 'He has a very inflated opinion of himself.', 'adj. 膨胀的, 夸张的, 通货膨胀的', '/in\'fleitid | ɪn\'fleɪtɪd | ɪn\'fletɪd/', 'inflated', 6);
INSERT INTO `words` VALUES (13210, 'Inflation is now at over 16%.', 'n. 胀大, 夸张, 通货膨胀, (物价)暴涨', '/in\'fleiʃən | ɪn\'fleɪʃ(ə)n | ɪn\'fleʃən/', 'inflation', 6);
INSERT INTO `words` VALUES (13211, 'This approach is too inflexible and too costly.', 'adj. 坚定的， 不屈不挠的', '/ɪn\'fleksəbl | ɪn\'flɛksəbl/', 'inflexible', 6);
INSERT INTO `words` VALUES (13212, 'Detectives warned that the men could inflict serious injury.', 'v. 使遭受', '/ɪn\'flɪkt/', 'inflict', 6);
INSERT INTO `words` VALUES (13213, NULL, 'n. 施加, 使负担', '/in\'flikʃən | ɪn\'flɪkʃ(ə)n/', 'infliction', 6);
INSERT INTO `words` VALUES (13214, 'As a scientist, his influence was immense.', 'n. 影响(力)，作用; v. 影响，对…起作用', '/\'ɪnfluəns/', 'influence', 6);
INSERT INTO `words` VALUES (13215, 'He had influential friends.', 'adj. 有影响力的', '/ˌɪnflu\'enʃl | ,ɪnflu\'ɛnʃl/', 'influential', 6);
INSERT INTO `words` VALUES (13216, '...problems caused by the influx of refugees.', 'n. 注入， 涌入', '/\'ɪnflʌks/', 'influx', 6);
INSERT INTO `words` VALUES (13217, 'Her experience as a refugee informs the content of her latest novel.', 'v. 对…有影响； 使活跃， 使有生气； 告诉， 通知', '/ɪn\'fɔːrm | ɪn\'fɔrm/', 'inform', 6);
INSERT INTO `words` VALUES (13218, 'The atmosphere at work is fairly informal.', 'adj. 随便的， 日常的； 不拘礼节的， 非正式的', '/ɪn\'fɔːrml | ɪn\'fɔrml/', 'informal', 6);
INSERT INTO `words` VALUES (13219, NULL, 'n. 非正式， 不拘礼节', '/ˌɪnfɔːr\'mæləti | ɪnfɔr\'mæləti/', 'informality', 6);
INSERT INTO `words` VALUES (13220, 'Both men termed the meeting friendly and informative.', 'adj. 提供信息的； 见闻广博的', '/ɪn\'fɔːrmətɪv | ɪn\'fɔrmətɪv/', 'informative', 6);
INSERT INTO `words` VALUES (13221, 'Informed sources said it was likely that the president would make a televised statement.', 'adj. 有学识的； 见多识广的， 消息灵通的', '/ɪn\'fɔːrmd | ɪn\'fɔrmd/', 'informed', 6);
INSERT INTO `words` VALUES (13222, '...two men suspected of being police informers.', 'n. 密告者, 控告的人, 通知的人', '/in\'fɔ:mə | ɪn\'fɔːmə | ɪn\'fɔrmɚ/', 'informer', 6);
INSERT INTO `words` VALUES (13223, '...an infraction of school rules.', 'n. 违反, 侵害', '/in\'frækʃən | ɪn\'frækʃ(ə)n | ɪn\'frækʃən/', 'infraction', 6);
INSERT INTO `words` VALUES (13224, '...searching with infrared scanners for weapons and artillery.', 'adj. 红外线的', '/ˌɪnfrə\'red | ,ɪnfrə\'rɛd/', 'infrared', 6);
INSERT INTO `words` VALUES (13225, 'Jeremy does play cricket, but very infrequently.', 'adv. 稀少地， 罕见地', '/in\'fri:kwəntli | ɪn\'friːkwəntli/', 'infrequently', 6);
INSERT INTO `words` VALUES (13226, 'A backup copy of a computer program does not infringe copyright.', 'v. 破坏, 侵犯, 违反', '/in\'frindʒ | ɪn\'frɪn(d)ʒ | ɪn\'frɪndʒ/', 'infringe', 6);
INSERT INTO `words` VALUES (13227, '...infringement of privacy.', 'n. 违反, 侵害', '/in\'frindʒmənt | ɪn\'frɪn(d)ʒm(ə)nt | ɪn\'frɪndʒmənt/', 'infringement', 6);
INSERT INTO `words` VALUES (13228, 'Yesterday\'s decision will infuriate Turkey and Brazil, who will see it as the established powers quashing a genuine attempt at mediation by two new voices on the world stage.', 'adj. 狂怒的', '/in\'fjuərieit | ɪn\'fjʊərɪeɪt | ɪn\'fjʊrɪet/', 'infuriate', 6);
INSERT INTO `words` VALUES (13229, 'Many of the girls seemed to be infused with excitement on seeing the snow.', 'v. 灌输, 注入, 沏或泡(茶、药等), 浸渍, 鼓舞', '/in\'fju:z | ɪn\'fjuːz | ɪn\'fjuz/', 'infuse', 6);
INSERT INTO `words` VALUES (13230, 'He brought a tremendous infusion of hope to the people.', 'n. 灌输', '/in\'fju:ʒən | ɪn\'fjuːʒ(ə)n | ɪn\'fjuʒn/', 'infusion', 6);
INSERT INTO `words` VALUES (13231, 'Many fish have ingenious ways of protecting their eggs from predators.', 'adj. 机灵的, 有独创性的, 精制的, 具有创造才能', '/in\'dʒi:njəs | ɪn\'dʒiːnɪəs | ɪn\'dʒinɪəs/', 'ingenious', 6);
INSERT INTO `words` VALUES (13232, NULL, 'n. 独创性', '/in\'dʒinjəsnis | ɪn\'dʒiːniəsnəs/', 'ingeniousness', 6);
INSERT INTO `words` VALUES (13233, NULL, 'n. 机灵, 独创性, 精巧, 灵活性', '/,ɪndʒɪ\'njuːɪtɪ | ,ɪndʒə\'nuəti/', 'ingenuity', 6);
INSERT INTO `words` VALUES (13234, 'He seemed too ingenuous for a reporter.', 'adj. 坦白的, 自然的, 直率的', '/in\'dʒenjuəs | ɪn\'dʒenjʊəs | ɪn\'dʒɛnjuəs/', 'ingenuous', 6);
INSERT INTO `words` VALUES (13235, NULL, 'adv. 纯真地； 坦率地', '/in\'dʒenjuəsli | ɪn\'dʒenjuəsli/', 'ingenuously', 6);
INSERT INTO `words` VALUES (13236, '...side effects occurring in fish that ingest this substance.', 'v. 摄取, 咽下, 吸收', '/in\'dʒest | ɪn\'dʒest | ɪn\'dʒɛst/', 'ingest', 6);
INSERT INTO `words` VALUES (13237, 'The processes of adherence and particle ingestion are two separate processes .', 'n. 摄取， 吸收', '/ɪn\'dʒestʃən | ɪn\'dʒɛstʃən/', 'ingestion', 6);
INSERT INTO `words` VALUES (13238, 'Training camp, he said, will quickly ingrain those principles.', 'adj. 根深蒂固的; n. 本质', '/ɪn\'greɪn | \'ɪngren/', 'ingrain', 6);
INSERT INTO `words` VALUES (13239, 'Morals tend to be deeply ingrained.', 'adj. 彻底的, 根深蒂固的, 生染的', '/,in\'ɡreind | ɪn\'greɪnd | ɪn\'ɡrend/', 'ingrained', 6);
INSERT INTO `words` VALUES (13240, 'She gathered her belongings and headed to the gate, refusing to look back at the ingrate thief.', 'n. 忘恩负义者', '/\'inɡreit, in\'ɡreit | \'ɪngreɪt; ɪn\'greɪt | ɪn\'ɡret/', 'ingrate', 6);
INSERT INTO `words` VALUES (13241, 'Many politicians are trying to ingratiate themselves with her.', 'v. 使迎合, 使讨好', '/in\'ɡreiʃieit | ɪn\'greɪʃɪeɪt | ɪn\'ɡreʃɪet/', 'ingratiate', 6);
INSERT INTO `words` VALUES (13242, 'It’s also possible that our experience was not at all representative of the charm and ingratiating qualities pit bulls can demonstrate.', 'adj. 逢迎的, 迷人的', '/in\'ɡreiʃieitiŋ | ɪn\'ɡreʃɪetɪŋ/', 'ingratiating', 6);
INSERT INTO `words` VALUES (13243, 'I’ve never seen such ingratitude!', 'n. 忘恩, 不知恩', '/in\'ɡrætitju:d | ɪn\'grætɪtjuːd | ɪn\'ɡrætɪtud/', 'ingratitude', 6);
INSERT INTO `words` VALUES (13244, 'Combine all the ingredients in a large bowl.', 'n. 成分, 因素', '/in\'ɡri:diənt | ɪn\'griːdɪənt | ɪn\'ɡridɪənt/', 'ingredient', 6);
INSERT INTO `words` VALUES (13245, 'A high seating position makes ingress and egress easy.', 'n. 进入, 入口处, 准许进入', '/\'inɡres | \'ɪngres | \'ɪnɡrɛs/', 'ingress', 6);
INSERT INTO `words` VALUES (13246, NULL, 'v. 狼吞虎咽, 大吃大喝', '/in\'ɡə:dʒiteit | ɪn\'gɜːdʒɪteɪt/', 'ingurgitate', 6);
INSERT INTO `words` VALUES (13247, 'The woods are inhabited by many wild animals.', 'v. 居住于； 占据', '/ɪn\'hæbɪt/', 'inhabit', 6);
INSERT INTO `words` VALUES (13248, 'a city of six million inhabitants', 'n. 居民, 居住者', '/in\'hæbitənt | ɪn\'hæbɪt(ə)nt | ɪn\'hæbɪtənt/', 'inhabitant', 6);
INSERT INTO `words` VALUES (13249, 'It is dangerous to inhale ammonia fumes.', 'v. 吸入', '/in\'heil | ɪn\'heɪl | ɪn\'hel/', 'inhale', 6);
INSERT INTO `words` VALUES (13250, 'Every business has its own inherent risks.', 'adj. 固有的, 内在的, 与生俱来的', '/in\'hiərənt | ɪn\'hɪər(ə)nt; -\'her(ə)nt | ɪn\'hɪrənt/', 'inherent', 6);
INSERT INTO `words` VALUES (13251, NULL, 'adv. 固有地， 天性地', '/ɪn\'hɪrəntli | ɪnˈhɪrəntlɪ/', 'inherently', 6);
INSERT INTO `words` VALUES (13252, 'inherited wealth', 'v. 继承', '/ɪn\'herɪt | ɪn\'hɛrɪt/', 'inherit', 6);
INSERT INTO `words` VALUES (13253, 'An unhappy family life may inhibit children’s learning.', 'v. 阻止； 抑制', '/ɪn\'hɪbɪt/', 'inhibit', 6);
INSERT INTO `words` VALUES (13254, 'Men are more inhibited about touching each other than women are.', 'adj. 羞怯的, 内向的', '/in\'hibitid | ɪn\'hɪbɪtɪd/', 'inhibited', 6);
INSERT INTO `words` VALUES (13255, 'a marked inhibition of cell growth', 'n. 阻止； 抑制； 抑制物', '/ˌɪn(h)ɪ\'bɪʃn | ˌɪnhɪˈbɪʃn/', 'inhibition', 6);
INSERT INTO `words` VALUES (13256, 'As far as wild animals and plants on the edge of extinction goes, we may not entirely believe in a reprieve but it would be inhuman of us not to try for one.', 'adj. 野蛮的', '/in\'hju:mən | ɪn\'hjuːmən | ɪn\'hjʊmən/', 'inhuman', 6);
INSERT INTO `words` VALUES (13257, 'the inhumane treatment of political prisoners', 'adj. 残忍的', '/,imhju:\'mein | ɪnhjʊ\'meɪn | \'ɪnhjʊ\'men/', 'inhumane', 6);
INSERT INTO `words` VALUES (13258, 'To the popular mind, science is completely inimical to religion: science embraces facts and evidence while religion professes blind faith.', 'adj. 敌意的', '/i\'nimikəl | ɪ\'nɪmɪk(ə)l | ɪ\'nɪmɪkl/', 'inimical', 6);
INSERT INTO `words` VALUES (13259, 'He makes his own point in his own inimitable way.', 'adj. 无法模仿的, 独特的, 无比的', '/i\'nimitəbl | ɪ\'nɪmɪtəb(ə)l | ɪ\'nɪmɪtəbl/', 'inimitable', 6);
INSERT INTO `words` VALUES (13260, 'an iniquitous system of taxation', 'adj. 不公正的', '/i\'nikwitəs | ɪ\'nɪkwətəs/', 'iniquitous', 6);
INSERT INTO `words` VALUES (13261, 'They were trying to protect their son from iniquity.', 'n. 不公正', '/i\'nikwəti | ɪ\'nɪkwɪtɪ | ɪ\'nɪkwəti/', 'iniquity', 6);
INSERT INTO `words` VALUES (13262, 'an initial investment of £5,000', 'adj. 开始的，最初的; n. 首字母', '/ɪ\'nɪʃl | ɪ\'nɪʃəl/', 'initial', 6);
INSERT INTO `words` VALUES (13263, 'They have decided to initiate legal proceedings against the newspaper.', 'v. 发起， 开始； 接纳', '/ɪ\'nɪʃieɪt | ɪ\'nɪʃɪet/', 'initiate', 6);
INSERT INTO `words` VALUES (13264, 'I wish my son would show more initiative.', 'n. 主动', '/i\'niʃiətiv, -ʃətiv | ɪ\'nɪʃɪətɪv; -ʃə- | ɪ\'nɪʃətɪv/', 'initiative', 6);
INSERT INTO `words` VALUES (13265, 'The judge refused to grant an injunction.', 'n. 命令, 指令, [律]禁令(法院强制被告从事或不得从事某项行为的正式命令)', '/in\'dʒʌŋkʃən | ɪn\'dʒʌŋ(k)ʃ(ə)n | ɪn\'dʒʌŋkʃən/', 'injunction', 6);
INSERT INTO `words` VALUES (13266, '...substances that are injurious to health.', 'adj. 有害的', '/ɪn\'dʒurəriəs | ɪn\'dʒʊrərɪəs/', 'injurious', 6);
INSERT INTO `words` VALUES (13267, 'I had an inkling that she was pregnant.', 'n. 暗示, 略微的提示, 略知, 模糊概念', '/\'iŋkliŋ | \'ɪŋklɪŋ/', 'inkling', 6);
INSERT INTO `words` VALUES (13268, '...education for prison inmates.', 'n. 同住者， 同居者', '/\'ɪnmeɪt | \'ɪnmet/', 'inmate', 6);
INSERT INTO `words` VALUES (13269, 'Children have an innate ability to learn language.', 'adj. 先天的, 天生的', '/,i\'neit | ɪ\'neɪt; \'ɪneɪt | ɪ\'net/', 'innate', 6);
INSERT INTO `words` VALUES (13270, 'the innermost depths of the cave', 'adj. 最里面的', '/\'ɪnərmoust | \'ɪnɚmost/', 'innermost', 6);
INSERT INTO `words` VALUES (13271, 'Can you prove your innocence?', 'n. 无辜， 清白', '/\'ɪnəsns/', 'innocence', 6);
INSERT INTO `words` VALUES (13272, 'an innocuous remark', 'adj. 无害的, 无毒的, 无伤大雅的, 不得罪人的', '/i\'nɔkjuəs | ɪ\'nɒkjʊəs | ɪ\'nɑkjuəs/', 'innocuous', 6);
INSERT INTO `words` VALUES (13273, 'an innovative approach to language teaching', 'adj. 革新的， 创新的', '/\'ɪnəveɪtɪv | \'ɪnəvetɪv/', 'innovative', 6);
INSERT INTO `words` VALUES (13274, 'His writing is full of sexual innuendoes.', 'n. 暗讽(的话), 影射(的话)', '/,inju:\'endəu | ,ɪnjʊ\'endəʊ | ,ɪnju\'ɛndo/', 'innuendo', 6);
INSERT INTO `words` VALUES (13275, '...a programme to inoculate every child in the country.', 'v. 接种, 嫁接', '/i\'nɔkjuleit | ɪ\'nɒkjʊleɪt | ɪ\'nɑkjə\'let/', 'inoculate', 6);
INSERT INTO `words` VALUES (13276, NULL, 'n. 接木, 接种, 接插芽', '/i\'nɔkju\'leiʃən | ɪ,nɒkjʊ\'leɪʃn | ɪˌnɒkju\'leɪʃn/', 'inoculation', 6);
INSERT INTO `words` VALUES (13277, 'Her husband was a small, inoffensive-looking man.', 'adj. 无害的； 不讨厌的', '/ˌɪnə\'fensɪv | ,ɪnə\'fɛnsɪv/', 'inoffensive', 6);
INSERT INTO `words` VALUES (13278, 'Testing is taking up an inordinate amount of teachers’ time.', 'adj. 紊乱的', '/i\'nɔ:dinət | ɪ\'nɔːdɪnət | ɪn\'ɔrdɪnət/', 'inordinate', 6);
INSERT INTO `words` VALUES (13279, 'Also, the apocalyptic and oracular tone provides the spectators with a glimpse of the anxiety and inquietude penetrating current Japanese society.', 'n. 不安', '/in\'kwaiətju:d | ɪn\'kwaɪətjuːd/', 'inquietude', 6);
INSERT INTO `words` VALUES (13280, 'I don’t know who sent the gift, but I’ll make some inquiries.', 'n. 询问', '/\'ɪnkwəri | ɪn\'kwaɪri; \'ɪn,kwaɪri; \'ɪnkwəri; \'ɪŋkwaɪri/', 'inquiry', 6);
INSERT INTO `words` VALUES (13281, 'I’d have asked more questions, but I didn’t want to seem inquisitive.', 'adj. 好奇的', '/in\'kwizətiv | ɪn\'kwɪzɪtɪv | ɪn\'kwɪzətɪv/', 'inquisitive', 6);
INSERT INTO `words` VALUES (13282, 'We haven’t made much of an inroad into the backlog of work.', 'n. 袭击', '/\'inrəud | \'ɪnrəʊd/', 'inroad', 6);
INSERT INTO `words` VALUES (13283, 'That’s an insane risk.', 'adj. 患精神病的, 精神病患者的, 极愚蠢的', '/in\'sein | ɪn\'seɪn | ɪn\'sen/', 'insane', 6);
INSERT INTO `words` VALUES (13284, 'The court acquitted Campbell on the grounds of temporary insanity.', 'n. 精神错乱, 疯狂, 愚顽', '/in\'sænəti | ɪn\'sænətɪ | ɪn\'sænəti/', 'insanity', 6);
INSERT INTO `words` VALUES (13285, 'A section of the reading public has an insatiable appetite for dirty stories about the famous.', 'adj. 不知足的， 贪得无厌的', '/ɪn\'seɪʃəbl | ɪn\'seʃəbl/', 'insatiable', 6);
INSERT INTO `words` VALUES (13286, NULL, 'adv. 不知足地， 贪得无厌地', '/in\'seiʃiəbli | ɪn\'seɪʃəbli/', 'insatiably', 6);
INSERT INTO `words` VALUES (13287, 'Inside the cover someone had inscribed the words ‘To Thomas, with love’.', 'v. 写、 题写', '/ɪn\'skraɪb/', 'inscribe', 6);
INSERT INTO `words` VALUES (13288, 'a Latin inscription on the memorial stone', 'n. 题字, 碑铭', '/in\'skripʃən | ɪn\'skrɪpʃ(ə)n | ɪn\'skrɪpʃən/', 'inscription', 6);
INSERT INTO `words` VALUES (13289, 'He stood silent and inscrutable.', 'adj. 难以了解的, 不能预测的', '/in\'skru:təbl | ɪn\'skruːtəb(ə)l | ɪn\'skrʊtəbl/', 'inscrutable', 6);
INSERT INTO `words` VALUES (13290, 'Many of them work in low-paid insecure jobs.', 'adj. 无保障的， 不安全的', '/ˌɪnsɪ\'kjur | ,ɪnsɪ\'kjʊr/', 'insecure', 6);
INSERT INTO `words` VALUES (13291, 'He took a small key from his pocket and slowly inserted it into the lock.', 'v. 插入, 嵌入', '/ɪn\'sɜːt | \'ɪnsɝt/', 'insert', 6);
INSERT INTO `words` VALUES (13292, 'Sometimes the insertion of one word can change the meaning of a whole sentence.', 'n. 插入', '/in\'sə:ʃən | ɪn\'sɜːʃ(ə)n | ɪn\'sɝʃən/', 'insertion', 6);
INSERT INTO `words` VALUES (13293, 'an insider’s view of the way that a Japanese company works', 'n. 内部的人, 会员, 知道内情的人, 权威人士', '/,in\'saidə | ɪn\'saɪdə | ɪn\'saɪdɚ/', 'insider', 6);
INSERT INTO `words` VALUES (13294, 'Another, more insidious form - is a lie .', 'adj. 阴险的', '/in\'sidiəs | ɪn\'sɪdɪəs/', 'insidious', 6);
INSERT INTO `words` VALUES (13295, 'a woman of great insight', 'n. 洞察力； 洞悉', '/\'ɪnsaɪt | \'ɪn\'saɪt/', 'insight', 6);
INSERT INTO `words` VALUES (13296, 'an insightful analysis', 'adj. 富有洞察力的， 有深刻见解的', '/\'ɪnsaɪtful | \'ɪnsaɪtfəl/', 'insightful', 6);
INSERT INTO `words` VALUES (13297, 'the royal insignia', 'n. 勋章, 徽章', '/in\'siɡniə | ɪn\'sɪgnɪə | ɪn\'sɪɡnɪə/', 'insignia', 6);
INSERT INTO `words` VALUES (13298, 'You realize that your problems are insignificant in comparison.', 'adj. 无价值的， 无意义的， 无用的', '/ˌɪnsɪg\'nɪfɪkənt | ,ɪnsɪɡ\'nɪfɪkənt/', 'insignificant', 6);
INSERT INTO `words` VALUES (13299, 'an insincere smile', 'adj. 不诚恳的， 虚伪的', '/ˌɪnsɪn\'sɪr | ,ɪnsɪn\'sɪr/', 'insincere', 6);
INSERT INTO `words` VALUES (13300, 'He gradually insinuated himself into her life.', 'v. 使逐步而巧妙地取得, 使迂回地潜入(或挤入), 使慢慢滋长, 含沙射影地说', '/in\'sinjueit | ɪn\'sɪnjʊeɪt | ɪn\'sɪnjuet/', 'insinuate', 6);
INSERT INTO `words` VALUES (13301, 'an insipid pasta dish', 'adj. 没有味道的, 平淡的', '/in\'sipid | ɪn\'sɪpɪd/', 'insipid', 6);
INSERT INTO `words` VALUES (13302, '...her insistence on personal privacy.', 'n. 坚持, 坚决主张', '/in\'sistəns | ɪn\'sɪst(ə)ns/', 'insistence', 6);
INSERT INTO `words` VALUES (13303, 'Defect: Compare enervated , do not easily, treat water or insolate wait to be out of shape possibly.', 'v. 曝晒', '/\'insəuleit | \'ɪnsəʊleɪt | \'ɪnsə\'let/', 'insolate', 6);
INSERT INTO `words` VALUES (13304, 'His manner partakes of insolence.', 'n. 傲慢， 无礼', '/\'ɪnsələns | \'insələns/', 'insolence', 6);
INSERT INTO `words` VALUES (13305, 'They proceeded in silence along the gravel walk that led to the copse; Elizabeth was determined to make no effort for conversation with a woman who was now more than usually insolent and disagreeable.', 'n. 侮慢无礼的人', '/\'insələnt | \'ɪns(ə)l(ə)nt | \'ɪnsələnt/', 'insolent', 6);
INSERT INTO `words` VALUES (13306, 'insoluble conflicts within the department', 'adj. 不能溶解的； 不能解决的', '/ɪn\'sɑːljəbl | ɪn\'sɑljəbl/', 'insoluble', 6);
INSERT INTO `words` VALUES (13307, '...eight mortgage companies, seven of which are on the brink of insolvency.', 'n. 无力偿还； 破产', '/ɪn\'sɑːlvənsi | ɪn\'sɑlvənsi/', 'insolvency', 6);
INSERT INTO `words` VALUES (13308, 'The company was later declared insolvent (= officially said to be insolvent ).', 'adj. 破产的', '/in\'sɔlvənt | ɪn\'sɒlv(ə)nt | ɪn\'sɑlvənt/', 'insolvent', 6);
INSERT INTO `words` VALUES (13309, 'If you have insomnia, try my simple cure.', 'n. 失眠, 失眠症', '/in\'sɔmniə | ɪn\'sɒmnɪə | ɪn\'sɑmnɪə/', 'insomnia', 6);
INSERT INTO `words` VALUES (13310, 'an air of insouciance', 'n. 漫不经心, 无忧无虑', '/in\'su:sjəns | ɪn\'susɪəns/', 'insouciance', 6);
INSERT INTO `words` VALUES (13311, 'Television producers seem irresponsibly insouciant about churning out violence.', 'adj. 漫不经心的', '/ɪn\'suːsiənt | ɪn\'sʊsiənt/', 'insouciant', 6);
INSERT INTO `words` VALUES (13312, 'An inspection was carried out at the school.', 'n. 检查, 视察', '/in\'spekʃən | ɪn\'spekʃn | ɪn\'spɛkʃən/', 'inspection', 6);
INSERT INTO `words` VALUES (13313, 'The Malvern Hills have provided inspiration for many artists and musicians over the decades.', 'n. 灵感', '/,inspə\'reiʃən | ˌɪnspəˈreɪʃn | ˌɪnspəˈreʃən/', 'inspiration', 6);
INSERT INTO `words` VALUES (13314, 'We need someone who can inspire the team.', 'v. 鼓舞， 激励', '/ɪn\'spaɪər | ɪn\'spaɪɚ/', 'inspire', 6);
INSERT INTO `words` VALUES (13315, 'an inspired leader', 'adj. 得到灵感的, 有灵感的, 权威人士(或官方)授意的', '/in\'spaiəd | ɪn\'spaɪəd | ɪn\'spaɪrd/', 'inspired', 6);
INSERT INTO `words` VALUES (13316, NULL, 'v. 浓缩', '/in\'spiseit, in\'spisit, -seit | ɪn\'spɪseɪt | ɪn\'spɪsɪt/', 'inspissate', 6);
INSERT INTO `words` VALUES (13317, 'They’ve installed the new computer network at last.', 'v. 安装， 装置； 使就职', '/ɪn\'stɔːl | ɪn\'stɔl/', 'install', 6);
INSERT INTO `words` VALUES (13318, 'the installation and maintenance of alarm systems', 'n. [计]安装, 装置, 就职', '/,instə\'leiʃən | ɪnstə\'leɪʃ(ə)n | \'ɪnstə\'leʃən/', 'installation', 6);
INSERT INTO `words` VALUES (13319, 'I will cover these transitions in the next installment.', 'n. 部分', '/in\'stɔ:lmənt | ɪn\'stɔ:lmənt | ɪn\'stɔlmənt/', 'installment', 6);
INSERT INTO `words` VALUES (13320, 'modern methods of instantaneous communication', 'adj. 瞬间的, 即刻的, 即时的', '/,instən\'teinjəs | ,ɪnst(ə)n\'teɪnɪəs | ,ɪnstən\'tenɪəs/', 'instantaneous', 6);
INSERT INTO `words` VALUES (13321, 'You will never instantiate this class directly, but always create an instance of its subclass.', 'v. 例示', '/in\'stænʃieit | ɪn\'stænʃɪeɪt | ɪns\'tænʃɪet/', 'instantiate', 6);
INSERT INTO `words` VALUES (13322, 'All four victims died instantly.', 'adv. 立即，即刻; conj. 一…就', '/\'ɪnstəntli/', 'instantly', 6);
INSERT INTO `words` VALUES (13323, 'He will instate Mason to a high position of power.', 'v. 任命', '/ɪn\'steɪt | in\'steit/', 'instate', 6);
INSERT INTO `words` VALUES (13324, 'He accused union leaders of instigating the disturbances.', 'v. 鼓动', '/\'instiɡeit | \'ɪnstɪgeɪt | \'ɪnstə\'get/', 'instigate', 6);
INSERT INTO `words` VALUES (13325, 'First, at my instigation, we repaired to an artists’ colony in France; then spent three months in Paris.', 'n, 教唆,. 鼓动, 煽动', '/,insti\'ɡeiʃən/', 'instigation', 6);
INSERT INTO `words` VALUES (13326, 'However, I do try to instill in them the ability to use sound engineering methods to analyze and design their programs and customize their practices.', 'v. 慢慢地灌输', '/in\'stil | ɪn\'stɪl/', 'instill', 6);
INSERT INTO `words` VALUES (13327, 'a mother’s instinctive love', 'adj. 本能的', '/ɪn\'stɪŋktɪv/', 'instinctive', 6);
INSERT INTO `words` VALUES (13328, 'research institutes', 'n. 学会, 学院, 协会', '/\'institjut, -tu:t | \'ɪnstɪtjuːt | \'ɪnstɪtut/', 'institute', 6);
INSERT INTO `words` VALUES (13329, 'powerful institutions such as world banks', 'n. 机构； 制度', '/ˌɪnstɪ\'tuːʃn | ,ɪnstɪ\'tuʃən/', 'institution', 6);
INSERT INTO `words` VALUES (13330, 'the struggle to institutionalize equality for women', 'v. 使制度化', '/ˌɪnstɪ\'tuːʃənəlaɪz | ,ɪnstɪ\'tuʃənəlaɪz/', 'institutionalize', 6);
INSERT INTO `words` VALUES (13331, 'institutionalised democracy', 'adj. 制度化的', '/ˌɪnstɪ\'tuːʃənəlaɪzd | ,ɪnstɪ\'tuʃənəlaɪzd/', 'institutionalized', 6);
INSERT INTO `words` VALUES (13332, 'Thank you, that was very instructive.', 'adj. 传授知识的， 教育的； 有益的', '/ɪn\'strʌktɪv/', 'instructive', 6);
INSERT INTO `words` VALUES (13333, '...a CD of vocal and instrumental music.', 'adj. 仪器的, 器械的, 乐器的', '/,instru\'mentəl, ,instrə- | ɪnstrʊ\'ment(ə)l | ,ɪnstrə\'mɛntl/', 'instrumental', 6);
INSERT INTO `words` VALUES (13334, 'In industry, a worker who is grossly insubordinate is threatened with discharge.', 'adj. 不顺从的, 不听话的', '/,insə\'bɔ:dinət | ,ɪnsə\'bɔːdɪnət | ,ɪnsə\'bɔrdnɪt/', 'insubordinate', 6);
INSERT INTO `words` VALUES (13335, 'The evidence seemed very insubstantial.', 'adj. 无实体的； 脆弱的', '/ˌɪnsəb\'stænʃl | ,ɪnsəb\'stænʃl/', 'insubstantial', 6);
INSERT INTO `words` VALUES (13336, 'He was an insufferable bore.', 'adj. 难以忍受的', '/in\'sʌfərəbl | ɪn\'sʌf(ə)rəb(ə)l | ɪn\'sʌfrəbl/', 'insufferable', 6);
INSERT INTO `words` VALUES (13337, 'Also called adrenal insufficiency or hypocortisolism, Addison\'s disease occurs in all age groups and affects both sexes. Addison\'s disease can be life-threatening.', 'n. 不足', '/,insə\'fiʃənsi | ɪnsə\'fɪʃ(ə)nsɪ | ,ɪnsə\'fɪʃənsi/', 'insufficiency', 6);
INSERT INTO `words` VALUES (13338, 'Insufficient resources have been devoted to the health service.', 'adj. 不足的, 不够的', '/ɪnsə\'fɪʃ(ə)nt | ,ɪnsə\'fɪʃnt/', 'insufficient', 6);
INSERT INTO `words` VALUES (13339, 'an insular community', 'adj. 海岛的, 岛民的, 岛特有的, 孤立的, 超然物外的', '/\'insjulə, \'insə- | \'ɪnsjʊlə | \'ɪnsəlɚ/', 'insular', 6);
INSERT INTO `words` VALUES (13340, NULL, 'n. 岛国性质(或状态), 岛屿生活状况, 与外界隔绝的生活状况, (思想, 观点等的)偏狭, 性僵化', '/,insju\'lærəti, \'insə-/', 'insularity', 6);
INSERT INTO `words` VALUES (13341, 'an insulated attic', 'v. 使绝缘, 隔离', '/\'insjuleit, \'insə- | \'ɪnsjʊleɪt | ˈɪnsəˌleɪt ; ˈɪnsjʊˌleɪt/', 'insulate', 6);
INSERT INTO `words` VALUES (13342, 'diabetic patients requiring insulin', 'n. 胰岛素', '/\'insjulin, \'insə- | \'ɪnsjʊlɪn | \'ɪnsəlɪn/', 'insulin', 6);
INSERT INTO `words` VALUES (13343, 'insulting remarks', 'adj. 侮辱的， 污蔑的', '/ɪn\'sʌltɪŋ/', 'insulting', 6);
INSERT INTO `words` VALUES (13344, 'There were insuperable obstacles, and the plan was abandoned.', 'adj. 不能制胜的, 不能克服的', '/in\'sju:pərəbl | ɪn\'suːp(ə)rəb(ə)l; ɪn\'sjuː | ɪn\'supərəbl/', 'insuperable', 6);
INSERT INTO `words` VALUES (13345, 'What was I? An insurgent.', 'adj. 起义的', '/in\'sə:dʒənt | ɪn\'sɜːdʒ(ə)nt | ɪn\'sɝdʒənt/', 'insurgent', 6);
INSERT INTO `words` VALUES (13346, 'The language difference proved an insurmountable barrier.', 'adj. 不能克服的， 不能超越的', '/ˌɪnsər\'mauntəbl | ,ɪnsɚ\'maʊntəbl/', 'insurmountable', 6);
INSERT INTO `words` VALUES (13347, 'I had to do it, because insurrection must have its discipline.', 'n. 起义', '/,insə\'rekʃən | ,ɪnsə\'rekʃ(ə)n/', 'insurrection', 6);
INSERT INTO `words` VALUES (13348, 'Only the medieval tower had remained intact.', 'adj. 完整无缺的, 尚未被人碰过的, (女子)保持童贞的, (家畜)未经阉割的', '/in\'tækt | ɪn\'tækt/', 'intact', 6);
INSERT INTO `words` VALUES (13349, NULL, 'n. 凹雕, 阴雕, 凹雕玉石', '/in\'tɑ:liəu | ɪn\'tælɪəʊ; -\'tɑːl-/', 'intaglio', 6);
INSERT INTO `words` VALUES (13350, 'IPR generally have the features of intangibility, exclusivity, territoriality and temporality.', 'n. 无形', '/in,tænkʒə\'biləti | ɪnˌtændʒə\'bɪləti/', 'intangibility', 6);
INSERT INTO `words` VALUES (13351, 'The island has an intangible quality of holiness.', 'adj. 难以明了的, 无形的', '/in\'tændʒəbl | ɪn\'tæn(d)ʒɪb(ə)l | ɪn\'tændʒəbl/', 'intangible', 6);
INSERT INTO `words` VALUES (13352, 'Vegetables are an integral part of our diet.', 'adj. 构成整体所必需的； 完整的', '/\'ɪntɪgrəl | \'ɪntɪɡrəl/', 'integral', 6);
INSERT INTO `words` VALUES (13353, 'He didn\'t integrate successfully into the Italian way of life.', 'v. 使成整体， 使一体化', '/\'ɪntɪgreɪt | \'ɪntɪɡret/', 'integrate', 6);
INSERT INTO `words` VALUES (13354, 'an integrated public transport system', 'adj. 综合的, 完整的', '/\'intiɡreitid | \'ɪntɪgreɪtɪd | \'ɪntɪɡretɪd/', 'integrated', 6);
INSERT INTO `words` VALUES (13355, 'Such initiatives require leadership, learning by doing and the ability to think and plan in an integrative manner.', 'adj. 综合的, 一体化的', '/\'intiɡreitiv | \'ɪntɪɡreɪtɪv | ,ɪntə\'ɡretɪv/', 'integrative', 6);
INSERT INTO `words` VALUES (13356, 'the territorial integrity of the country', 'n. 正直, 诚实, 完整, 完全, 完整性', '/in\'teɡrəti | ɪn\'tegrɪtɪ | ɪn\'tɛɡrəti/', 'integrity', 6);
INSERT INTO `words` VALUES (13357, NULL, 'n. 覆盖物', '/in\'teɡjumənt | ɪn\'tegjʊm(ə)nt | ɪn\'tɛgjəmənt/', 'integument', 6);
INSERT INTO `words` VALUES (13358, 'Mark’s very intellectual.', 'adj. 智力的；理性的; n. 知识分子', '/ˌɪntə\'lektʃuəl | ,ɪntə\'lɛktʃuəl/', 'intellectual', 6);
INSERT INTO `words` VALUES (13359, 'The language of Darwin was intelligible to experts and non-experts alike.', 'adj. 可理解的', '/in\'telidʒəbl | ɪn\'telɪdʒɪb(ə)l | ɪn\'tɛlɪdʒəbl/', 'intelligible', 6);
INSERT INTO `words` VALUES (13360, NULL, 'n. 放纵， 不节制， 过度', '/ɪn\'tempərəns | in\'tempərəns/', 'intemperance', 6);
INSERT INTO `words` VALUES (13361, 'the judge’s intemperate outburst', 'adj. 放纵的', '/in\'tempərət | ɪn\'temp(ə)rət | ɪn\'tɛmpərət/', 'intemperate', 6);
INSERT INTO `words` VALUES (13362, NULL, 'n. 增强， 加剧； 激烈化', '/ɪnˌtensɪfɪ\'keɪʃn | ɪn,tɛnsəfə\'keʃən/', 'intensification', 6);
INSERT INTO `words` VALUES (13363, 'In Junethe civil war intensified.', 'v. 使加剧', '/ɪn\'tensɪfaɪ | ɪn\'tɛnsɪfaɪ/', 'intensify', 6);
INSERT INTO `words` VALUES (13364, 'his intent gaze', 'adj. 专心的，专注的；热切的，渴望的; n. 目的， 意向', '/ɪn\'tent | ɪn\'tɛnt/', 'intent', 6);
INSERT INTO `words` VALUES (13365, 'I did trip him, but it wasn’t intentional.', 'adj. 存心的， 故意的', '/ɪn\'tenʃənl | ɪn\'tɛnʃənl/', 'intentional', 6);
INSERT INTO `words` VALUES (13366, 'The team of archaeologists found the spot where his bones were originally interred.', 'v. 埋葬, 葬, 埋', '/in\'tə: | ɪn\'tɜː | ɪn\'tə/', 'inter', 6);
INSERT INTO `words` VALUES (13367, 'But you only get the maximum benefit if you implement all of them, because their power comes from their interaction.', 'n. 交互作用, 交感', NULL, 'interaction', 6);
INSERT INTO `words` VALUES (13368, 'interactive computer systems', 'adj. 交互式的', '/ˌɪntər\'æktɪv | ,ɪntɚ\'æktɪv/', 'interactive', 6);
INSERT INTO `words` VALUES (13369, 'They asked my father to intercede with the king on their behalf.', 'v. 调解', '/,intə\'si:d | ,ɪntə\'siːd | ,ɪntɚ\'sid/', 'intercede', 6);
INSERT INTO `words` VALUES (13370, 'Gunmen intercepted him on his way to the airport.', 'v. 中途阻止, 截取', '/,intə\'sept | ,ɪntə\'sept | ,ɪntɚ\'sɛpt/', 'intercept', 6);
INSERT INTO `words` VALUES (13371, 'These two words are almost interchangeable.', 'adj. 可互换的', '/,intə\'tʃeindʒəbl | ɪntə\'tʃeɪn(d)ʒəbl | ,ɪntɚ\'tʃendʒəbl/', 'interchangeable', 6);
INSERT INTO `words` VALUES (13372, 'Despite the apparent clarity around the distinct origins and meaning of the caduceus and the staff of aesculapius, they are both used commonly, and of ten interchangeably, every day.', 'adv. 可互换地', '/ˌɪntər\'tʃeɪndʒəbli | ɪntɚ\'tʃendʒəbli/', 'interchangeably', 6);
INSERT INTO `words` VALUES (13373, 'The plates are bounded by an interconnected network of ridges, transform faults, and trenches.', 'adj. 相互连接的', '/ˌɪntərkə\'nektɪd | ,ɪntɚkə\'nɛkt/', 'interconnected', 6);
INSERT INTO `words` VALUES (13374, 'countries with interdependent economies', 'adj. 相互依赖的， 互助的', '/ˌɪntərdɪ\'pendənt | ,ɪntɚdɪ\'pɛndənt/', 'interdependent', 6);
INSERT INTO `words` VALUES (13375, 'Troops could be ferried in to interdict drug shipments.', 'v. 阻断', '/,intə\'dikt, \'intədikt | \'ɪntədɪkt | \'ɪntɚdɪkt/', 'interdict', 6);
INSERT INTO `words` VALUES (13376, 'an interdisciplinary research centre', 'adj. 跨学科的', '/ˌɪntər\'dɪsəplɪneri | ,ɪntɚ\'dɪsəplɪnɛri/', 'interdisciplinary', 6);
INSERT INTO `words` VALUES (13377, 'Industrial relations should be free from state interference.', 'n. 干涉， 妨碍', '/ˌɪntər\'fɪrəns | ,ɪntɚ\'fɪrəns/', 'interference', 6);
INSERT INTO `words` VALUES (13378, 'an interim report', 'adj. 中间的, 临时的, 间歇的', '/\'intərim | \'ɪnt(ə)rɪm | \'ɪntərɪm/', 'interim', 6);
INSERT INTO `words` VALUES (13379, '...the moronic and insensitive interjections of the disc jockey.', 'n. 插入语； 感叹词', '/ˌɪntər\'dʒekʃn | ,ɪntɚ\'dʒɛkʃən/', 'interjection', 6);
INSERT INTO `words` VALUES (13380, 'It is the interlace weave pattern of Universal Essence.', 'v. 使交织, 使交错', '/,intə\'leis | ɪntə\'leɪs | \'ɪntɚ\'les/', 'interlace', 6);
INSERT INTO `words` VALUES (13381, 'to interlard one\'s writing with foreign phrases', 'v. 使混杂， 混入', '/ˌɪntər\'lɑːrd | ,intə\'lɑ:d/', 'interlard', 6);
INSERT INTO `words` VALUES (13382, 'a puzzle with 500 interlocking pieces', 'v. 互锁', '/,intə\'lɔk, \'intəlɔk | ɪntə\'lɒk | \'ɪntɚlɑk/', 'interlock', 6);
INSERT INTO `words` VALUES (13383, 'Set inlcudes 8 interlocking blocks, a ball launcher, a catch funnel and 2 balls.', 'adj. 连锁的； 关联的', '/,intə\'lɔkiŋ | ˌɪntər\'lɑːkɪŋ/', 'interlocking', 6);
INSERT INTO `words` VALUES (13384, 'Orion had the habit of staring motionlessly at his interlocutor.', 'n. 对话者, 对谈者', '/,intə\'lɔkjutə | ,ɪntə\'lɒkjʊtə | ,ɪntɚ\'lɑkjətɚ/', 'interlocutor', 6);
INSERT INTO `words` VALUES (13385, 'She had no wish to share her father with any outsider and regarded us as interlopers.', 'n. 闯入者', '/\'ɪntərloupər | \'ɪntɚlopɚ/', 'interloper', 6);
INSERT INTO `words` VALUES (13386, 'a brief interlude of peace before a return to the battlefield', 'n. 两段时期中间之时间, 间隔的时间, 戏剧或歌剧两幕间, 圣诗等两段之间之间歇', '/\'intəlu:d | \'ɪntəl(j)uːd | \'ɪntɚ\'lʊd/', 'interlude', 6);
INSERT INTO `words` VALUES (13387, 'Jackson acted as an intermediary between the two parties.', 'n. 仲裁者, 调解者, 中间物', '/,intə\'mi:diəri | ,ɪntə\'miːdɪərɪ | ,ɪntɚ\'midɪɛri/', 'intermediary', 6);
INSERT INTO `words` VALUES (13388, 'interminable delays', 'adj. 无限的, 冗长的', '/in\'tə:minəbl | ɪn\'tɜːmɪnəb(ə)l | ɪn\'tɝmɪnəbl/', 'interminable', 6);
INSERT INTO `words` VALUES (13389, 'Salt and sugar intermingle with each other.', 'n. 混合', '/,intə\'miŋɡl | ɪntə\'mɪŋg(ə)l | ,ɪntɚ\'mɪŋɡl/', 'intermingle', 6);
INSERT INTO `words` VALUES (13390, 'It was the first time Hanna had been to the theater, and she loved all of it, from the performance to the champagne at intermission.', 'n. 间断', '/,intə\'miʃən | ɪntə\'mɪʃ(ə)n | \'ɪntɚ\'mɪʃən/', 'intermission', 6);
INSERT INTO `words` VALUES (13391, 'The weather forecast is for sun, with intermittent showers.', 'adj. 间歇的, 断断续续的', '/ɪntə\'mɪt(ə)nt | ,ɪntɚ\'mɪtənt/', 'intermittent', 6);
INSERT INTO `words` VALUES (13392, '...a medical intern.', 'n. 实习医师, 被拘留者', '/in\'tə:n, \'intə:n | \'ɪntɜːn | \'ɪntɝn/', 'intern', 6);
INSERT INTO `words` VALUES (13393, 'internecine warfare', 'adj. 互相残杀的, 两败俱伤的, 内部冲突的', '/,intə\'ni:sain | ,ɪntə\'niːsaɪn | \'ɪntɚ\'nisaɪn/', 'internecine', 6);
INSERT INTO `words` VALUES (13394, 'an internment camp', 'n. 扣留, 收容', '/in\'tə:nmənt | ɪn\'tɜːnmənt | ɪn\'tɝnmənt/', 'internment', 6);
INSERT INTO `words` VALUES (13395, 'The answer lies, yet again, in the interplay of population and technology.', 'v. 相互影响', '/\'intəplei, ,intə\'plei, \'in- | \'ɪntəpleɪ | ,ɪntɚ\'plɛi/', 'interplay', 6);
INSERT INTO `words` VALUES (13396, 'He started humming a tune, then interpolated the odd word as though having difficulty remembering.', 'v. 窜改, 添写进去, 插入新语句', '/in\'tə:pəuleit | ɪn\'tɜːpəleɪt | ɪn\'tɝpəlet/', 'interpolate', 6);
INSERT INTO `words` VALUES (13397, NULL, 'n. 篡改, 添写, 插补', '/ɪn,tɜːpəʊ\'leɪʃən | ɪn,tɚpə\'leʃən/', 'interpolation', 6);
INSERT INTO `words` VALUES (13398, 'At any point in the project where you don\'t interpose your own judgment, your people are more likely to make a mistake. So what?', 'v. 提出', '/,intə\'pəuz | ɪntə\'pəʊz | \'ɪntɚ\'poz/', 'interpose', 6);
INSERT INTO `words` VALUES (13399, 'The interposition of fresco art in the city environment can just satisfy with the requirement of people.', 'n. 插入', '/in,tə:pə\'ziʃən | ɪntəpə\'zɪʃ(ə)n/', 'interposition', 6);
INSERT INTO `words` VALUES (13400, 'Freud’s attempts to interpret the meaning of dreams', 'v. 解释， 说明； 演绎', '/ɪn\'tɜːrprɪt | ɪn\'tɝprɪt/', 'interpret', 6);
INSERT INTO `words` VALUES (13401, 'One possible interpretation is that they want you to resign.', 'n. 解释， 说明； 演绎', '/ɪnˌtɜːrprɪ\'teɪʃn | ɪn\'tɝprɪ\'teʃən/', 'interpretation', 6);
INSERT INTO `words` VALUES (13402, NULL, 'n. 空白期间, 空位期间, 中断', '/,intə\'reɡnəm | ,ɪntə\'regnəm | ,ɪntɚ\'rɛɡnəm/', 'interregnum', 6);
INSERT INTO `words` VALUES (13403, 'We will be discussing how the interests of state, parent and child interrelate.', 'v. (使)相互关连', '/,intəri\'leit | ɪntərɪ\'leɪt | \'ɪntɚrɪ\'let/', 'interrelate', 6);
INSERT INTO `words` VALUES (13404, 'The police interrogated the suspect for several hours.', 'v. 审问, 询问', '/in\'terəuɡeit | ɪn\'terəgeɪt | ɪn\'tɛrəɡet/', 'interrogate', 6);
INSERT INTO `words` VALUES (13405, '...the right to silence in police interrogations.', 'n. 审问， 质问； 疑问句', '/ɪnˌterə\'geɪʃn | ɪn,tɛrə\'geʃən/', 'interrogation', 6);
INSERT INTO `words` VALUES (13406, 'He made a further interrogative noise.', 'adj. 表示疑问的, 质问的', '/,intə\'rɔɡətiv | ,ɪntə\'rɒgətɪv | ,ɪntə\'rɑɡətɪv/', 'interrogative', 6);
INSERT INTO `words` VALUES (13407, 'Will you stop interrupting me!', 'v. 暂时中止； 打断， 打扰', '/ˌɪntə\'rʌpt | \'ɪntə\'rʌpt/', 'interrupt', 6);
INSERT INTO `words` VALUES (13408, 'Chinese civilization is the only one without interruption.', 'n. 中断， 打断', '/ˌɪntə\'rʌpʃn | ,ɪntə\'rʌpʃən/', 'interruption', 6);
INSERT INTO `words` VALUES (13409, 'The orbit of this comet intersects the orbit of the Earth.', 'v. 横断', '/,intə\'sekt | ɪntə\'sekt | \'ɪntɚ\'sɛkt/', 'intersect', 6);
INSERT INTO `words` VALUES (13410, 'We crossed at a busy intersection.', 'n. [数]交集, 十字路口, 交叉点', '/,intə\'sekʃən | ɪntə\'sekʃ(ə)n | ,ɪntɚ\'sɛkʃən/', 'intersection', 6);
INSERT INTO `words` VALUES (13411, 'sunny periods interspersed with showers', 'v. 散布, 点缀', '/,intə\'spə:s | ɪntə\'spɜːs | ,ɪntɚ\'spɝs/', 'intersperse', 6);
INSERT INTO `words` VALUES (13412, 'Any of the open spaces in a net or network; an interstice .', 'n. 空隙, 裂缝', '/in\'tə:stis | ɪn\'tɜːstɪs | ɪn\'tɝstɪs/', 'interstice', 6);
INSERT INTO `words` VALUES (13413, 'Trees, undergrowth and creepers intertwined, blocking our way.', 'v. (使)纠缠, (使)缠绕', '/,intə\'twain | ɪntə\'twaɪn | ,ɪntɚ\'twaɪn/', 'intertwine', 6);
INSERT INTO `words` VALUES (13414, 'The army will have to intervene to prevent further fighting.', 'v. 干涉, 干预, 插入, 介入, (指时间)介于其间', '/,intə\'vi:n | ɪntə\'viːn | ,ɪntɚ\'vin/', 'intervene', 6);
INSERT INTO `words` VALUES (13415, 'government intervention to regulate prices', 'n. 干涉', '/,intə\'venʃən | ɪntə\'venʃ(ə)n | ,ɪntɚ\'vɛnʃən/', 'intervention', 6);
INSERT INTO `words` VALUES (13416, 'For these people, land is inextricably interwoven with life itself.', 'v. (使)交织, 织进, (使)混杂', '/,intə\'wi:v, \'intə,wi:v | ɪntə\'wiːv | ,ɪntɚ\'wiv/', 'interweave', 6);
INSERT INTO `words` VALUES (13417, 'There are strict guidelines that must be followed if someone dies intestate – in other words without a will.', 'adj. 没有立下遗嘱的, 不能根据遗嘱处分的', '/in\'testeit | ɪn\'testeɪt | ɪn\'tɛstet/', 'intestate', 6);
INSERT INTO `words` VALUES (13418, NULL, 'adj. 肠的, 肠内的, (疾病)侵袭肠的', '/in\'testinəl | ɪnte\'staɪn(ə)l; ɪn\'testɪn(ə)l | ɪn\'tɛstɪnl/', 'intestinal', 6);
INSERT INTO `words` VALUES (13419, NULL, 'adj. 内部的, 国内的', '/in\'testin | ɪn\'testɪn | ɪn\'tɛstɪn/', 'intestine', 6);
INSERT INTO `words` VALUES (13420, 'She thought back over the intimacies they’d shared and the plans they’d made.', 'n. 亲密, 隐私, 亲昵行为(尤指不正当的性关系)', '/\'intiməsi | \'ɪntɪməsɪ | \'ɪntɪməsi/', 'intimacy', 6);
INSERT INTO `words` VALUES (13421, 'an intimate friend of Picasso’s', 'adj. 亲密的, 隐私的', '/英 [\'ɪntɪmət] 美 [ˈɪntəmɪt] | \'ɪntɪmət | ˈɪntəmɪt/', 'intimate', 6);
INSERT INTO `words` VALUES (13422, 'I did not have any intimation that he was going to resign.', 'n. 暗示', '/ˌɪntɪ\'meɪʃn | ,ɪntɪ\'meʃən/', 'intimation', 6);
INSERT INTO `words` VALUES (13423, 'Attempts to intimidate her failed.', 'v. 胁迫', '/in\'timideit | ɪn\'tɪmɪdeɪt | ɪn\'tɪmɪdet/', 'intimidate', 6);
INSERT INTO `words` VALUES (13424, 'She’s lactose-intolerant (= unable to drink particular types of milk ).', 'adj. 不宽容的, 偏狭的', '/in\'tɔlərənt | ɪn\'tɒl(ə)r(ə)nt | ɪn\'tɑlərənt/', 'intolerant', 6);
INSERT INTO `words` VALUES (13425, NULL, 'n. 使醉的东西', '/in\'tɔksikənt | ɪn\'tɒksɪk(ə)nt | ɪn\'tɑksəkənt/', 'intoxicant', 6);
INSERT INTO `words` VALUES (13426, 'Sea wind intoxicate.', 'v. 使陶醉, 醉人', '/in\'tɔksikeit, -kit, -keit | ɪn\'tɒksɪkeɪt/', 'intoxicate', 6);
INSERT INTO `words` VALUES (13427, 'the seemingly intractable problem of human greed', 'adj. 难处理的', '/in\'træktəbl | ɪn\'træktəb(ə)l | ɪn\'træktəbl/', 'intractable', 6);
INSERT INTO `words` VALUES (13428, 'an intramural softball competition', 'adj. 校内的, 内部的', '/,intrə\'mjuərəl | ,ɪntrə\'mjʊər(ə)l | ,ɪntrə\'mjʊrəl/', 'intramural', 6);
INSERT INTO `words` VALUES (13429, NULL, 'n. 不妥协态度, 不让步,不调和', '/in\'trænsidʒəns,-dʒənsi/', 'intransigence', 6);
INSERT INTO `words` VALUES (13430, 'an intransigent attitude', 'adj. 非妥协性的', '/in\'trænsidʒənt | ɪn\'trænsɪdʒ(ə)nt; -\'trɑː-; -nz- | ɪn\'trænzədʒənt/', 'intransigent', 6);
INSERT INTO `words` VALUES (13431, 'intrepid explorers', 'adj. 无畏的, 勇猛的', '/in\'trepid | ɪn\'trepɪd | ɪn\'trɛpɪd/', 'intrepid', 6);
INSERT INTO `words` VALUES (13432, 'Due to his intrepidity he may be the last hope of the village.', 'n. 无畏', '/,intri\'pidəti/', 'intrepidity', 6);
INSERT INTO `words` VALUES (13433, 'The intricacy of the structure may be caused in part by material ejected from a binary central star, but as yet, there is no direct evidence that the central star has a companion.', 'n. 复杂, 错综', '/\'intrikəsi | \'ɪntrɪkəsɪ | \'ɪntrɪkəsi/', 'intricacy', 6);
INSERT INTO `words` VALUES (13434, 'intricate patterns', 'adj. 复杂的, 错综的, 难以理解的', '/\'intrikət | \'ɪntrɪkət/', 'intricate', 6);
INSERT INTO `words` VALUES (13435, 'It’s an exciting story of political intrigue and murder.', 'n. 阴谋, 诡计', '/in\'tri:ɡ, \'in- | ɪn\'triːg | \'ɪn\'triɡ/', 'intrigue', 6);
INSERT INTO `words` VALUES (13436, 'The magazine carries an intriguing mixture of high fashion, gossip and racing.', 'adj. 迷人的, 有迷惑力的, 引起兴趣(或好奇心)的', '/in\'tri:ɡiŋ | \'ɪntriːgɪŋ; ɪn\'triːgɪŋ | ɪn\'triɡɪŋ/', 'intriguing', 6);
INSERT INTO `words` VALUES (13437, 'the intrinsic interest of the subject', 'adj. (指价值、性质)固有的, 内在的, 本质的', '/in\'trinsik,-kəl | ɪn\'trɪnsɪk/', 'intrinsic', 6);
INSERT INTO `words` VALUES (13438, 'The as each country government relaxation on international is control, open of celestial policy carry out, also the obstacle of intromit aviation industry is abate.', 'v. 使进入, 插入', '/,intrəu\'mit | ,ɪntrəʊ\'mɪt/', 'intromit', 6);
INSERT INTO `words` VALUES (13439, 'He had always had his moments of quiet introspection.', 'n. 内省, 反省, 自省', '/intrəu\'spekʃən | ɪntrə(ʊ)\'spekʃ(ə)n | \'ɪntrə\'spɛkʃən/', 'introspection', 6);
INSERT INTO `words` VALUES (13440, 'a shy and introspective person', 'adj. (好)内省的, (好)自省的, (好)反省的', '/,intrəu\'spektiv | ɪntrə\'spektɪv | \'ɪntrə\'spɛktɪv/', 'introspective', 6);
INSERT INTO `words` VALUES (13441, 'I sympathize with the introvert as I would with the sickly, but both are missing a lot of life.', 'n. 格性内向的人', '/,intrəu\'və:t, \'intrəuvə:t | \'ɪntrəvɜːt | \'ɪntrəvɝt/', 'introvert', 6);
INSERT INTO `words` VALUES (13442, 'The press has been blamed for intruding into people\'s personal lives in an unacceptable way.', 'v. 闯入, 侵入', '/in\'tru:d | ɪn\'truːd | ɪn\'trʊd/', 'intrude', 6);
INSERT INTO `words` VALUES (13443, NULL, 'adj. 入侵的， 入侵性的', '/ɪn\'truːdɪŋ | ɪn\'trʊd/', 'intruding', 6);
INSERT INTO `words` VALUES (13444, 'the unwelcome intrusion of the press', 'n. 闯入, 侵扰', '/in\'tru:ʒən | ɪn\'truːʒ(ə)n | ɪn\'truʒn/', 'intrusion', 6);
INSERT INTO `words` VALUES (13445, NULL, 'adv. 入侵地', '/in\'tru:sivli | ɪn\'truːsɪvli/', 'intrusively', 6);
INSERT INTO `words` VALUES (13446, 'feminine intuition', 'n. 直觉； 直觉知识', '/ˌɪntu\'ɪʃn | ,ɪntu\'ɪʃən/', 'intuition', 6);
INSERT INTO `words` VALUES (13447, 'He seemed to have an intuitive awareness of how I felt.', 'adj. 直觉的', '/in\'tju:itiv | ɪn\'tjuːɪtɪv | ɪn\'tuɪtɪv/', 'intuitive', 6);
INSERT INTO `words` VALUES (13448, 'Approximate solutions were found for the rate of growth of a bubble in the process of intumescence.', 'n. 膨胀, 肿大', '/,intju:\'mesəns, ,intju:\'mesənsi | ,ɪntjuː\'mesəns | ,ɪntjʊ\'mɛsns/', 'intumescence', 6);
INSERT INTO `words` VALUES (13449, 'The tidal wave inundated vast areas of cropland.', 'v. 淹没', '/\'inʌndeit, in\'ʌn- | \'ɪnʌndeɪt | \'ɪnʌndet/', 'inundate', 6);
INSERT INTO `words` VALUES (13450, 'Through these comparisons we can not only test to see if our experimental data are accurate, but find the most effective and efficient way to model tsunami inundation and loading.', 'n. 洪水', '/,inʌn\'deiʃən | ,ɪnʌn\'deɪʃn | ,ɪnʌn\'deʃən/', 'inundation', 6);
INSERT INTO `words` VALUES (13451, 'We should inure ourselves to hard life.', 'v. 使习惯于； 生效', '/ɪ\'njur | i\'njuə/', 'inure', 6);
INSERT INTO `words` VALUES (13452, 'The Romans invaded Britain 2,000 years ago.', 'v. 侵略， 侵入', '/ɪn\'veɪd | ɪn\'ved/', 'invade', 6);
INSERT INTO `words` VALUES (13453, 'I resented being treated as an invalid.', 'n. 病人, 残废者', '/\'invəli:d, -lid, ,invə\'li:d, \'in- | ˈɪnvəlɪd；ɪnˈvælɪd/', 'invalid', 6);
INSERT INTO `words` VALUES (13454, 'Failure to disclose all relevant changes may invalidate your policy.', 'v. 使无效', '/in\'vælideit | ɪn\'vælɪdeɪt | ɪn\'vælɪdet/', 'invalidate', 6);
INSERT INTO `words` VALUES (13455, 'His invariable answer was ‘Wait and see.’', 'adj. 恒定的， 不变的', '/ɪn\'verəriəbl | ɪn\'vɛrərɪəbl/', 'invariable', 6);
INSERT INTO `words` VALUES (13456, 'He let out a stream of invective.', 'n. 恶言漫骂', '/in\'vektiv | ɪn\'vektɪv | ɪn\'vɛktɪv/', 'invective', 6);
INSERT INTO `words` VALUES (13457, 'A lot of his writings inveigh against luxury and riches.', 'v. 痛骂， 猛烈抨击', '/ɪn\'veɪ | ɪn\'ve/', 'inveigh', 6);
INSERT INTO `words` VALUES (13458, 'She inveigles Paco into a plot to swindle Tania out of her savings.', 'v. 诱骗', '/in\'veiɡl, -\'vi:- | ɪn\'viːg(ə)l; ɪn\'veɪg(ə)l | ɪn\'viɡl/', 'inveigle', 6);
INSERT INTO `words` VALUES (13459, 'The dishwasher is a wonderful invention.', 'n. 发明， 创造； 发明才能， 创造力； 发现， 找到', '/ɪn\'venʃn | ɪn\'vɛnʃən/', 'invention', 6);
INSERT INTO `words` VALUES (13460, 'one of the most talented and inventive drummers in modern music', 'adj. 善于发明的， 有创造力的； 发明的', '/ɪn\'ventɪv | ɪn\'vɛntɪv/', 'inventive', 6);
INSERT INTO `words` VALUES (13461, '...one inventory of twelve sails for each yacht.', 'n. 详细目录, 存货, 财产清册, 总量', '/\'invəntəri, -tɔ:ri | \'ɪnv(ə)nt(ə)rɪ | \'ɪnvəntɔri/', 'inventory', 6);
INSERT INTO `words` VALUES (13462, 'Clearly, the amount of money people save increases in inverse proportion to the amount they spend.', 'adj. 倒转的, 反转的', '/\'invə:s, in\'v-, in\'və:s | \'ɪnvɜːs; ɪn\'vɜːs | ,ɪn\'vɝs/', 'inverse', 6);
INSERT INTO `words` VALUES (13463, 'The puzzle_scan_words() function has a $flip parameter that can invert the scan from horizontal to vertical.', 'adj. 转化的', '/in\'və:t, \'invə:t | ɪn\'vɜːt | \'ɪnvɝt/', 'invert', 6);
INSERT INTO `words` VALUES (13464, '...invertebrate creatures.', 'adj. 无脊椎的, 无骨气的', '/in\'və:tibrət, -breit | ɪn\'vɜːtɪbrət | ɪn\'vɝtɪbret/', 'invertebrate', 6);
INSERT INTO `words` VALUES (13465, 'The state police are investigating the incident.', 'v. 调查', '/ɪn\'vestɪgeɪt | ɪn\'vɛstɪɡet/', 'investigate', 6);
INSERT INTO `words` VALUES (13466, '...an investigative reporter.', 'adj. 调查的', '/ɪn\'vestɪgeɪtɪv | ɪn\'vɛstɪɡetɪv/', 'investigative', 6);
INSERT INTO `words` VALUES (13467, '...her investiture as a member of the National Institute for Arts and Letters.', 'n. 授职, 授权, 覆盖物', '/in\'vestitʃə | ɪn\'vestɪtjə; -tʃə | ɪn\'vɛstətʃɚ/', 'investiture', 6);
INSERT INTO `words` VALUES (13468, 'The main investor in the project is the French bank Credit National.', 'n. 投资者', '/ɪn\'vestər | ɪn\'vɛstɚ/', 'investor', 6);
INSERT INTO `words` VALUES (13469, '...an inveterate gambler.', 'adj. 根深的, 成癖的', '/in\'vetərət | ɪn\'vet(ə)rət | ɪn\'vɛtərət/', 'inveterate', 6);
INSERT INTO `words` VALUES (13470, 'Police officers fear invidious comparisons.', 'adj. 易招嫉妒的, 不公平的, 诽谤的', '/in\'vidiəs | ɪn\'vɪdɪəs/', 'invidious', 6);
INSERT INTO `words` VALUES (13471, 'Different is, the exam in the life often does not have person invigilate.', 'v. 看守, 监考', '/in\'vidʒileit | ɪn\'vɪdʒɪleɪt | ɪn\'vɪdʒɪlet/', 'invigilate', 6);
INSERT INTO `words` VALUES (13472, 'Carey’s hope was that the church would be renewed and invigorated.', 'v. 鼓舞', '/in\'viɡəreit | ɪn\'vɪgəreɪt | ɪn\'vɪɡəret/', 'invigorate', 6);
INSERT INTO `words` VALUES (13473, 'The might of the army is \"invincible,\" according to state media but the refugees are rather cynical about the ill equipped force.', 'adj. 不能征服的, 无敌的', '/in\'vinsəbl | ɪn\'vɪnsɪb(ə)l | ɪn\'vɪnsəbl/', 'invincible', 6);
INSERT INTO `words` VALUES (13474, 'The game had a single inviolable rule: obstacles were to be overcome, not circumvented.', 'adj. 神圣的, 不可亵渎的, 不可侵犯的', '/in\'vaiələbl | ɪn\'vaɪələb(ə)l | ɪn\'vaɪələbl/', 'inviolable', 6);
INSERT INTO `words` VALUES (13475, 'We believed our love was inviolate.', 'adj. 未亵渎的, 无污点的, 未受侵犯的', '/in\'vaiələt, -leit,-leitid | ɪn\'vaɪələt/', 'inviolate', 6);
INSERT INTO `words` VALUES (13476, 'The log fire looked warm and inviting.', 'adj. 引人动心的, 有魅力的', '/in\'vaitiŋ | ɪn\'vaɪtɪŋ/', 'inviting', 6);
INSERT INTO `words` VALUES (13477, '...an invocation for divine guidance.', 'n. 祈祷, 符咒', '/,ɪnvə(ʊ)\'keɪʃ(ə)n | ,ɪnvə\'keʃən/', 'invocation', 6);
INSERT INTO `words` VALUES (13478, 'We will then send you an invoice for the total course fees.', 'n. 发票, 发货单, 货物', '/\'ɪnvɒɪs | \'ɪnvɔɪs/', 'invoice', 6);
INSERT INTO `words` VALUES (13479, 'Should anyone be allowed to invoke any service?', 'v. 调用', '/in\'vəuk | ɪn\'vəʊk | ɪn\'vok/', 'invoke', 6);
INSERT INTO `words` VALUES (13480, 'When Willie tapped on the window, Miguel gave an involuntary jump.', 'adj. 自然而然的, 无意的, 不知不觉的, 偶然的, 不随意的', '/in\'vɔləntəri | ɪn\'vɒlənt(ə)rɪ | ɪn\'vɑləntɛri/', 'involuntary', 6);
INSERT INTO `words` VALUES (13481, 'The moves in chess are not only manifold, but involute.', 'adj. 纷乱的, 复杂的', '/\'invəlju:t, ,invə\'lju:t | \'ɪnvəl(j)uːt | ,ɪnvə\'ljʊt/', 'involute', 6);
INSERT INTO `words` VALUES (13482, 'What will the job involve?', 'v. 包含， 含有； 参与； 牵涉， 牵连', '/ɪn\'vɑːlv | ɪn\'vɑlv/', 'involve', 6);
INSERT INTO `words` VALUES (13483, 'During a visit to Kenya in 1928 he became romantically involved with a married woman.', 'adj. 棘手的,有关的', '/in\'vɔlvd | ɪn\'vɒlvd | ɪn\'vɑlvd/', 'involved', 6);
INSERT INTO `words` VALUES (13484, 'School officials say they welcome parental involvement.', 'n. 参与； 连累； 投入', '/ɪn\'vɑːlvmənt | ɪn\'vɔlvmənt/', 'involvement', 6);
INSERT INTO `words` VALUES (13485, 'Gerry’s confidence made him feel invulnerable.', 'adj. 不会受伤害的, 无懈可击的', '/in\'vʌlnərəbl | ɪn\'vʌln(ə)rəb(ə)l | ɪn\'vʌlnərəbl/', 'invulnerable', 6);
INSERT INTO `words` VALUES (13486, 'The cut burns from the iodine.', 'n. 碘, 碘酒', '/\'aiəudi:n | \'aɪədiːn; -aɪn; -ɪn | aɪədaɪn/', 'iodine', 6);
INSERT INTO `words` VALUES (13487, NULL, 'n. 希腊语字母第 9位, 极微小', '/ai\'əutə | aɪ\'əʊtə | aɪ\'otə/', 'iota', 6);
INSERT INTO `words` VALUES (13488, 'an irascible old man', 'adj. 易怒的, 暴躁的', '/i\'ræsəbl | ɪ\'ræsɪb(ə)l | ɪ\'ræsəbl/', 'irascible', 6);
INSERT INTO `words` VALUES (13489, 'The owner was so irate he almost threw me out of the place.', 'adj. 生气, 发怒的', '/ai\'reit, \'aireit | aɪ\'reɪt | aɪ\'ret/', 'irate', 6);
INSERT INTO `words` VALUES (13490, 'That of course raised my ire.', 'v. 激怒; n. 愤怒', '/\'aɪər | \'aɪɚ/', 'ire', 6);
INSERT INTO `words` VALUES (13491, NULL, 'adj. 忿怒的', '/\'aiəful/', 'ireful', 6);
INSERT INTO `words` VALUES (13492, 'You can see the iridescence on their faces.', 'n. 彩虹色', '/,iri\'desəns, \'aiəri- | ˌɪrɪ\'desns/', 'iridescence', 6);
INSERT INTO `words` VALUES (13493, 'small iridescent blue flies', 'adj. 彩虹色的, 闪光的', '/,iri\'desənt, \'aiəri- | ,ɪrɪ\'des(ə)nt | ,ɪrɪ\'dɛsnt/', 'iridescent', 6);
INSERT INTO `words` VALUES (13494, NULL, 'n. [解]虹膜, 鸢尾属植物, [希神]彩虹之女神, 虹, 虹彩', '/\'aiəris | \'aɪrɪs/', 'iris', 6);
INSERT INTO `words` VALUES (13495, 'The rehearsal process also irked him increasingly.', 'v. 使厌倦, 使苦恼', '/ə:k | ɜːk | ɝk/', 'irk', 6);
INSERT INTO `words` VALUES (13496, 'an irksome journey', 'adj. 令人厌恶的, 讨厌的, 令人厌烦的', '/\'ə:ksəm | \'ɜːks(ə)m | \'ɝksəm/', 'irksome', 6);
INSERT INTO `words` VALUES (13497, 'an ironclad battleship', 'adj. 装甲的, 打不破的', '/\'aiənklæd | aɪən\'klæd | \'aɪɚnklæd/', 'ironclad', 6);
INSERT INTO `words` VALUES (13498, 'Your car was stolen at the police station! How ironic!', 'adj. 说反话的, 讽刺的', '/ai\'rɔnik,-kəl | aɪ\'rɒnɪk | aɪ\'rɑnɪk/', 'ironic', 6);
INSERT INTO `words` VALUES (13499, 'Life is full of little ironies.', 'n. 反话, 讽刺, 讽刺之事', '/\'aiərəni | \'aɪrənɪ | \'aɪrəni/', 'irony', 6);
INSERT INTO `words` VALUES (13500, '...the Chernobyl disaster, which irradiated large parts of Europe.', 'v. 照射', '/ɪ\'reɪdɪeɪt | ɪ\'redɪɪt/', 'irradiate', 6);
INSERT INTO `words` VALUES (13501, NULL, 'adj. 无法根除的， 根深蒂固的', '/i\'rædikəbl | ɪ\'rædɪkəbl/', 'irradicable', 6);
INSERT INTO `words` VALUES (13502, 'an irrational fear of flying', 'adj. 不理智的； 失去理性的， 不合理的', '/ɪ\'ræʃənl/', 'irrational', 6);
INSERT INTO `words` VALUES (13503, 'Proponents of the urn: scheme argue that this tension is irreconcilable within the framework of HTTP and DNS.', 'adj. 不能协调的, 矛盾的', '/i\'rekənsailəbl | ɪ,rek(ə)n\'saɪləb(ə)l; ɪ\'rek(ə)nsaɪləb(ə)l | ɪ\'rɛkənsaɪləbl/', 'irreconcilable', 6);
INSERT INTO `words` VALUES (13504, 'Very few children are irredeemable.', 'adj. 无法挽回的， 不可救药的', '/ˌɪrɪ\'diːməbl | ,ɪrɪ\'diməbl/', 'irredeemable', 6);
INSERT INTO `words` VALUES (13505, 'The pictures provide irrefutable evidence of the incident.', 'adj. 无可辩驳的， 毋庸置疑的', '/ˌɪrɪ\'fjuːtəbl | \'ɪrɪ\'fjʊtəbl/', 'irrefutable', 6);
INSERT INTO `words` VALUES (13506, 'We’re focussing too much on irrelevant details.', 'adj. 不相关的； 不切题的', '/ɪ\'reləvənt | ɪ\'rɛləvənt/', 'irrelevant', 6);
INSERT INTO `words` VALUES (13507, 'His memory suffered irremediable damage.', 'adj. 无法治愈的， 无法纠正的', '/ˌɪrɪ\'miːdiəbl | ,ɪrɪ\'midɪəbl/', 'irremediable', 6);
INSERT INTO `words` VALUES (13508, 'Extensive mining will cause irreparable damage to the area.', 'adj. 不能挽回的', '/i\'repərəbl | ɪ\'rep(ə)rəb(ə)l | ɪ\'rɛpərəbl/', 'irreparable', 6);
INSERT INTO `words` VALUES (13509, 'an irrepressible optimist', 'adj. 抑制不住的， 压抑不住的', '/ˌɪrɪ\'presəbl | ,ɪrɪ\'prɛsəbl/', 'irrepressible', 6);
INSERT INTO `words` VALUES (13510, 'She welcomed her unexpected visitor with irreproachable politeness.', 'adj. 无可指责的, 不可非难的, 无缺点的, 无过失的', '/,iri\'prəutʃəbl | ɪrɪ\'prəʊtʃəb(ə)l | ,ɪrɪ\'protʃəbl/', 'irreproachable', 6);
INSERT INTO `words` VALUES (13511, 'I was overcome by an irresistible urge to cry.', 'adj. 不可抵抗的, 不能压制的', '/,iri\'zistəbl | ɪrɪ\'zɪstɪb(ə)l | ,ɪrɪ\'zɪstəbl/', 'irresistible', 6);
INSERT INTO `words` VALUES (13512, 'The worst reason to launch an attack would be a fear of seeming irresolute.', 'adj. 未决定的； 犹豫不决的', '/ɪ\'rezəluːt | ɪ\'rɛzə\'lʊt/', 'irresolute', 6);
INSERT INTO `words` VALUES (13513, 'It was highly irresponsible of him to leave the children on their own in the pool.', 'adj. 不对更高一级负责的；不承担责任的；无责任感的；无负责能力的; n. 不负责任的人， 无责任感的人', '/ˌɪrɪ\'spɑːnsəbl | ,ɪrɪ\'spɑnsəbl/', 'irresponsible', 6);
INSERT INTO `words` VALUES (13514, 'his irreverent sense of humour', 'adj. 不尊敬的', '/i\'revərənt | ɪ\'rev(ə)r(ə)nt | ɪ\'rɛvərənt/', 'irreverent', 6);
INSERT INTO `words` VALUES (13515, 'Fossil fuels have caused irreversible damage to the environment.', 'adj. 不能撤回的， 不能取消的', '/ˌɪrɪ\'vɜːrsəbl | ,ɪrɪ\'vɝsəbl/', 'irreversible', 6);
INSERT INTO `words` VALUES (13516, 'Think about the situation carefully before you take an irrevocable step.', 'adj. 不能取消的', '/i\'revəkəbl, iri\'vəukəbl | ɪ\'revəkəb(ə)l | ɪ\'rɛvəkəbl/', 'irrevocable', 6);
INSERT INTO `words` VALUES (13517, 'The water in Lake Powell is used to irrigate the area.', 'v. 灌溉, 修水利, 冲洗伤口, 使潮湿', '/\'iriɡeit | \'ɪrɪgeɪt | \'ɪrəget/', 'irrigate', 6);
INSERT INTO `words` VALUES (13518, 'Jo was tired, irritable, and depressed.', 'adj. 易怒的, 急躁的', '/\'iritəbl | \'ɪrɪtəb(ə)l | \'ɪrɪtəbl/', 'irritable', 6);
INSERT INTO `words` VALUES (13519, 'It really irritates me when he doesn’t help around the house.', 'v. 激怒, 使急躁', '/\'iriteit | \'ɪrɪteɪt | \'ɪrɪtet/', 'irritate', 6);
INSERT INTO `words` VALUES (13520, 'He’s the most irritating man I’ve ever met.', 'adj. 刺激的； 使人愤怒的， 气人的', '/\'ɪrɪteɪtɪŋ | \'iriteitiŋ/', 'irritating', 6);
INSERT INTO `words` VALUES (13521, 'The heavy traffic is a constant source of irritation.', 'n. 愤怒， 恼怒', '/ˌɪrɪ\'teɪʃn | ,ɪrə\'teʃən/', 'irritation', 6);
INSERT INTO `words` VALUES (13522, 'The town was isolated by the floods.', 'v. 孤立', '/\'aɪsəleɪt | aɪslˌet/', 'isolate', 6);
INSERT INTO `words` VALUES (13523, 'the Isthmus of Panama', 'n. [地理]地峡, 峡部', '/\'isməs | \'ɪsθməs; \'ɪstməs; \'ɪsməs | \'ɪsməs/', 'isthmus', 6);
INSERT INTO `words` VALUES (13524, NULL, 'v. 反复说, 重申, 重述', '/\'itəreit, -rət | \'ɪtəreɪt | \'ɪtərət/', 'iterate', 6);
INSERT INTO `words` VALUES (13525, 'itinerant labourers', 'adj. 巡回的', '/i\'tinərənt,ai- | ɪ\'tɪn(ə)r(ə)nt; aɪ- | aɪ\'tɪnərənt/', 'itinerant', 6);
INSERT INTO `words` VALUES (13526, 'I need your travel itinerary by end of day.', 'n. 路线', '/aɪˈtɪnəˌreri: | aɪ\'tɪn(ə)(rə)rɪ; ɪ- | aɪ\'tɪnərɛri/', 'itinerary', 6);
INSERT INTO `words` VALUES (13527, 'He saw her jab her thumb on a red button – a panic button.', 'v. 猛刺', '/dʒæb/', 'jab', 6);
INSERT INTO `words` VALUES (13528, 'The tourists were jabbering away on the bus.', 'v. 快而含糊地说, 吱吱喳喳地叫, 闲聊', '/\'dʒæbə | \'dʒæbɚ/', 'jabber', 6);
INSERT INTO `words` VALUES (13529, NULL, 'n. <法>（墨西哥和美国西部的）小茅屋', '/hə\'kɑːl | hɑ\'kɑl/', 'jacal', 6);
INSERT INTO `words` VALUES (13530, 'a jade necklace', 'n. 碧玉, 翡翠, 老马', '/dʒeid | dʒeɪd | dʒed/', 'jade', 6);
INSERT INTO `words` VALUES (13531, 'The concert should satisfy even the most jaded critic.', 'adj. 疲倦不堪的, 厌倦的', '/\'dʒeidid | \'dʒeɪdɪd | \'dʒedɪd/', 'jaded', 6);
INSERT INTO `words` VALUES (13532, 'the broken bottle’s jagged edge', 'adj. 锯齿状的，有凹口的，（外形）参差不齐的', '/\'dʒægid | \'dʒægɪd | \'dʒæɡɪd/', 'jagged', 6);
INSERT INTO `words` VALUES (13533, NULL, 'n. 美洲虎[军] (“美洲虎”) 英、法合作研制的超音速攻击机', '/\'dʒægjʊə | ˈdʒæɡˌwɑr, ˈdʒæɡjuˌɑr/', 'jaguar', 6);
INSERT INTO `words` VALUES (13534, NULL, 'n. 矿柱, 旁柱', '/dʒæm/', 'jamb', 6);
INSERT INTO `words` VALUES (13535, NULL, 'n. (尤指国际性或全国性的)少年团体大会,喧闹的娱乐会,狂欢活动', '/,dʒæmbə\'ri: | ,dʒæmbə\'riː | ,dʒæmbə\'ri/', 'jamboree', 6);
INSERT INTO `words` VALUES (13536, 'Ed Roberts had been a school janitor for a long time.', 'n. 看门人', '/\'dʒænɪtə | \'dʒænɪtɚ/', 'janitor', 6);
INSERT INTO `words` VALUES (13537, NULL, 'v. 开玩笑， 戏弄', '/dʒeɪp | dʒep/', 'jape', 6);
INSERT INTO `words` VALUES (13538, 'a jam jar', 'n. 震动, 刺耳声, 震惊, 争吵, 罐, 广口瓶', '/dʒɑ: | dʒɑː | dʒɑr/', 'jar', 6);
INSERT INTO `words` VALUES (13539, 'Keep it simple and avoid the use of jargon.', 'n. 行话', '/\'dʒɑ:ɡən, -ɡɔn | \'dʒɑːg(ə)n | \'dʒɑrɡən/', 'jargon', 6);
INSERT INTO `words` VALUES (13540, NULL, 'adj. 声音刺耳的', '/\'dʒɑːrɪŋ | \'dʒɑrɪŋ/', 'jarring', 6);
INSERT INTO `words` VALUES (13541, 'Leptospirosis causes severe jaundice, kidney failure and bleeding in the lungs.', 'n. 偏见； 黄疸', '/\'dʒɔːndɪs | \'dʒɔndɪs/', 'jaundice', 6);
INSERT INTO `words` VALUES (13542, 'He has a very jaundiced view of the world.', 'adj. 患黄疸病的, 敌视的, 有偏见的', '/\'dʒɔ:ndist | \'dʒɔndɪst/', 'jaundiced', 6);
INSERT INTO `words` VALUES (13543, 'a weekend jaunt', 'n. 远足, 短途旅游', '/dʒɔ:nt | dʒɔːnt/', 'jaunt', 6);
INSERT INTO `words` VALUES (13544, '...a jaunty little man.', 'adj. 感到自信和自满的, 洋洋得意的', '/\'dʒɔ:nti | \'dʒɔːntɪ | \'dʒɔnti/', 'jaunty', 6);
INSERT INTO `words` VALUES (13545, 'Sexual jealousy is a common motive for murder.', 'n. 嫉妒', '/\'dʒeləsi | \'dʒɛləsi/', 'jealousy', 6);
INSERT INTO `words` VALUES (13546, '‘You know I’m right!’ she jeered.', 'n. 嘲笑, 讥讽, 戏弄', '/dʒiə | dʒɪə | dʒɪr/', 'jeer', 6);
INSERT INTO `words` VALUES (13547, 'jejune political opinions', 'adj. 缺乏营养的, 贫瘠的, 无兴趣的, 不成熟的', '/dʒi\'dʒu:n | dʒɪ\'dʒuːn | dʒɪ\'dʒun/', 'jejune', 6);
INSERT INTO `words` VALUES (13548, 'large-scale military offensives which could jeopardize the UN peace process', 'v. 危害', '/\'dʒepədaɪz | \'dʒɛpɚdaɪz/', 'jeopardize', 6);
INSERT INTO `words` VALUES (13549, 'Thousands of jobs are in jeopardy.', 'n. 危险, 危险', '/\'dʒepədi | \'dʒepədɪ | \'dʒɛpɚdi/', 'jeopardy', 6);
INSERT INTO `words` VALUES (13550, NULL, 'n. 悲叹, 悲痛, 悲哀的故事', '/,dʒeri\'maiəd | ,dʒerɪ\'maɪæd | ,dʒɛrɪ\'maɪæd/', 'jeremiad', 6);
INSERT INTO `words` VALUES (13551, 'He gave a sudden jerk of his head.', 'n. 性情古怪的人, 急推, 猛拉, 肌肉抽搐, (生理)反射, 牛肉干', '/dʒə:k | dʒɜːk | dʒɝk/', 'jerk', 6);
INSERT INTO `words` VALUES (13552, 'I wasn’t sure whether to treat her words as a jest.', 'n. 笑话, 俏皮话', '/dʒest | dʒɛst/', 'jest', 6);
INSERT INTO `words` VALUES (13553, 'It was a jest rather than a reproach.', 'n. 笑话, 滑稽', '/\'dʒestiŋ/', 'jesting', 6);
INSERT INTO `words` VALUES (13554, NULL, 'adj. 阴险的；虚伪的', '/,dʒezju\'itik,-kəl/', 'jesuitical', 6);
INSERT INTO `words` VALUES (13555, 'We\'re going to jettison the cargo.', 'n. 投弃, 投弃货物', '/\'dʒetisən | \'dʒetɪs(ə)n; -z(ə)n | \'dʒɛtɪsn/', 'jettison', 6);
INSERT INTO `words` VALUES (13556, 'This is popularly called sailing under “jib and jigger”—the jigger being an old square-rigger term for the aft-most mast flying a triangular sail.', 'n. 船首三角帆, 起重机的臂, 挺杆', '/dʒib | dʒɪb/', 'jib', 6);
INSERT INTO `words` VALUES (13557, 'The numbers don\'t jibe.', 'v. 与…一致， 符合', '/dʒaɪb/', 'jibe', 6);
INSERT INTO `words` VALUES (13558, NULL, 'n. 竖锯', '/\'dʒiɡsɔ: | \'dʒɪgsɔː | \'dʒɪɡsɔ/', 'jigsaw', 6);
INSERT INTO `words` VALUES (13559, NULL, 'n. 抛弃情人的女子', '/dʒilt | dʒɪlt/', 'jilt', 6);
INSERT INTO `words` VALUES (13560, NULL, '[美]被遗弃的人', NULL, 'jiltee', 6);
INSERT INTO `words` VALUES (13561, 'a mood of warlike jingoism', 'n. 主战论, 武力外交政策,沙文主义,侵略主义', '/\'dʒiŋɡəuizəm | \'dʒɪŋɡoɪzəm/', 'jingoism', 6);
INSERT INTO `words` VALUES (13562, 'He jinked left, then right, throwing the plane into sudden turns.', 'v. 闪身, 急转, 逃走', '/dʒɪŋk/', 'jink', 6);
INSERT INTO `words` VALUES (13563, 'To overdo anything public may lead to jobbery, while appropriate selfishness may promote the growth.', 'n. 假公济私', '/\'dʒɔbəri | \'dʒɒb(ə)rɪ | \'dʒɑbəri/', 'jobbery', 6);
INSERT INTO `words` VALUES (13564, 'Falsehood is the jockey of misfortune.', 'n. 赛马骑师; v. 〔为获得最佳位置、最有利形势或最大权力而〕激烈竞争', '/\'dʒɑːki | \'dʒɑki/', 'jockey', 6);
INSERT INTO `words` VALUES (13565, NULL, 'adj. 诙谐的', '/dʒəu\'kəus | dʒə\'kəʊs | dʒə\'kos/', 'jocose', 6);
INSERT INTO `words` VALUES (13566, 'He sounded in a jocular mood.', 'adj. 滑稽的， 幽默的； 爱开玩笑的', '/\'dʒɑːkjələr | \'dʒɑkjəlɚ/', 'jocular', 6);
INSERT INTO `words` VALUES (13567, 'However, today the fog is unusually thin, through which the soft golden sunbeams filter and cloak everything on the ground with a jocund hue.', 'adj. 欢乐的, 高兴的', '/\'dʒɔkənd | \'dʒɒk(ə)nd; \'dʒəʊk- | \'dʒɑkənd/', 'jocund', 6);
INSERT INTO `words` VALUES (13568, 'I go jogging every morning.', 'n. 轻推, 轻撞, 漫步', '/dʒɔɡ | dʒɒg | dʒɑɡ/', 'jog', 6);
INSERT INTO `words` VALUES (13569, NULL, 'n. 高兴, 酒宴', '/\'dʒɔləti | \'dʒɒlɪtɪ/', 'jollity', 6);
INSERT INTO `words` VALUES (13570, 'Everybody was in a very relaxed and jolly mood.', 'adj. 欢乐的, 高兴的, 快活的', '/\'dʒɔli | \'dʒɒlɪ | \'dʒɑli/', 'jolly', 6);
INSERT INTO `words` VALUES (13571, 'We jolted along rough wet roads through an endless banana plantation.', 'v. 摇晃', '/dʒəult | dʒəʊlt; dʒɒlt | dʒolt/', 'jolt', 6);
INSERT INTO `words` VALUES (13572, NULL, 'adj. 令人震惊的', '/\'dʒəultiŋ | \'dʒoultɪŋ/', 'jolting', 6);
INSERT INTO `words` VALUES (13573, 'The guys josh him and call him an egghead.', 'v. 戏弄， 戏耍', '/dʒɑːʃ | dʒɑʃ/', 'josh', 6);
INSERT INTO `words` VALUES (13574, 'You get 2,000 people jostling each other and bumping into furniture.', 'v. 推挤； 挤开通路', '/\'dʒɑːsl | \'dʒɑsl/', 'jostle', 6);
INSERT INTO `words` VALUES (13575, 'Could you just jot his name on there?', 'v. 草草记下', '/dʒɑːt | dʒɑt/', 'jot', 6);
INSERT INTO `words` VALUES (13576, NULL, 'v. 颠簸地移动', '/dʒauns | dʒaʊns/', 'jounce', 6);
INSERT INTO `words` VALUES (13577, 'He began his journalistic career in the early eighties in Australia.', 'adj. 新闻业的， 新闻工作者的', '/ˌdʒɜːrnə\'lɪstɪk | \'dʒɝnl\'ɪstɪk/', 'journalistic', 6);
INSERT INTO `words` VALUES (13578, 'He addressed me in a jovial manner.', 'adj. 快活的, 高兴的, 愉快的, [宗](主神)朱庇特的', '/\'dʒəuviəl | \'dʒəʊvɪəl; -vj(ə)l | \'dʒovɪəl/', 'jovial', 6);
INSERT INTO `words` VALUES (13579, 'Radicals were jubilant at getting rid of him.', 'adj. 欢呼的, 喜悦的, 喜洋洋的', '/\'dʒu:bilənt | \'dʒuːbɪl(ə)nt | \'dʒubɪlənt/', 'jubilant', 6);
INSERT INTO `words` VALUES (13580, 'There was jubilation that a local team had come first.', 'n. 庆祝', '/,dʒu:bi\'leiʃən | dʒuːbɪ\'leɪʃn | ,dʒubɪ\'leʃən/', 'jubilation', 6);
INSERT INTO `words` VALUES (13581, '...an independent judicial system.', 'adj. 司法的, 法院的, 公正的, 明断的', '/dʒu:\'diʃəl | dʒuː\'dɪʃ(ə)l | dʒʊ\'dɪʃəl/', 'judicial', 6);
INSERT INTO `words` VALUES (13582, 'a judicious choice', 'adj. 明智的', '/dʒu:\'diʃəs | dʒʊ\'dɪʃəs | dʒu\'dɪʃəs/', 'judicious', 6);
INSERT INTO `words` VALUES (13583, NULL, 'n. 明智', '/dʒu(:)\'diʃəsnis | dʒu\'dɪʃəsnəs/', 'judiciousness', 6);
INSERT INTO `words` VALUES (13584, NULL, 'v. 用陶罐等炖 in an earthenware vessel)； 关押(to jail; imprison)', '/dʒʌg | dʒʌɡ/', 'jug', 6);
INSERT INTO `words` VALUES (13585, NULL, 'n. 使人盲目崇', '/\'dʒʌɡənɔ:t/', 'juggernaut', 6);
INSERT INTO `words` VALUES (13586, NULL, 'vt. [现罕] 刎颈自尽, 扼杀, [医]顿挫', '/\'dʒʌgjʊleɪt | \'dʒʌɡjuleit/', 'jugulate', 6);
INSERT INTO `words` VALUES (13587, 'The photographs were all jumbled up.', 'v. 混杂, 搞乱', '/\'dʒʌmbl | \'dʒʌmb(ə)l/', 'jumble', 6);
INSERT INTO `words` VALUES (13588, NULL, 'n. <美> 庞然大物', '/\'dʒʌmbəu | \'dʒʌmbəʊ | \'dʒʌmbo/', 'jumbo', 6);
INSERT INTO `words` VALUES (13589, 'I told myself not to be so jumpy.', 'adj. 紧张不安的， 心惊肉跳的', '/\'dʒʌmpi/', 'jumpy', 6);
INSERT INTO `words` VALUES (13590, 'the junction of Abbot Road and Mill Street', 'n. 交叉路口； 连接', '/\'dʒʌŋkʃn | \'dʒʌŋkʃən/', 'junction', 6);
INSERT INTO `words` VALUES (13591, 'Atthis juncture, I suggest we take a short break.', 'n. 关键时刻， 危急关头； 结合处， 接合点', '/\'dʒʌŋktʃər | \'dʒʌŋktʃɚ/', 'juncture', 6);
INSERT INTO `words` VALUES (13592, 'Raise you hands if you like junk food.', 'n. 垃圾, 舢板', '/dʒʌŋk/', 'junk', 6);
INSERT INTO `words` VALUES (13593, 'The British police have no jurisdiction over foreign bank accounts.', 'n. 司法权， 审判权， 裁判权', '/ˌdʒurɪs\'dɪkʃn | ,dʒʊrɪs\'dɪkʃən/', 'jurisdiction', 6);
INSERT INTO `words` VALUES (13594, NULL, 'n. 法学', '/,dʒuəris\'pru:dəns | ,dʒʊərɪs\'pruːd(ə)ns | ,dʒʊrɪs\'prudns/', 'jurisprudence', 6);
INSERT INTO `words` VALUES (13595, 'justifiable anger', 'adj. 有理由的', '/\'dʒʌstifaiəbl | \'dʒʌstɪ,faɪəb(ə)l | \'dʒʌstɪfaɪəbl/', 'justifiable', 6);
INSERT INTO `words` VALUES (13596, 'Hoggart felt, with some justification, that his colleagues had let him down.', 'n. 正当的理由； 辩护', '/ˌdʒʌstɪfɪ\'keɪʃn | ,dʒʌstɪfɪ\'keʃən/', 'justification', 6);
INSERT INTO `words` VALUES (13597, 'Nothing justifies murdering another human being.', 'v. 证明…是正当或合理的', '/\'dʒʌstɪfaɪ | \'dʒʌstə\'fai/', 'justify', 6);
INSERT INTO `words` VALUES (13598, 'Tall jagged rocks jutted out over the beach.', 'v. (使)突出, (使)伸出, 突击', '/dʒʌt/', 'jut', 6);
INSERT INTO `words` VALUES (13599, 'juvenile crime', 'adj. 青少年的, 幼稚的', '/\'dʒu:vənail, -nil | \'dʒuːvənaɪl | \'dʒʊvənaɪl/', 'juvenile', 6);
INSERT INTO `words` VALUES (13600, 'The technique Mr. Wilson uses most often is to juxtapose things for dramatic effect.', 'v. 并置, 并列', '/,dʒʌkstə\'pəuz | ,dʒʌkstə\'pəʊz | \'dʒʌkstə\'poz/', 'juxtapose', 6);
INSERT INTO `words` VALUES (13601, 'This juxtaposition of brutal reality and lyrical beauty runs through Park\'s stories.', 'n. 毗邻, 并置, 并列', '/,dʒʌkstəpə\'ziʃən | ,dʒʌkstəpə\'zɪʃ(ə)n | ,dʒʌkstəpə\'zɪʃən/', 'juxtaposition', 6);
INSERT INTO `words` VALUES (13602, NULL, 'adj. 万花筒的, 五花八门的', '/kə,laidə\'skɔpik,-kəl | kəlaɪdə\'skɒpɪk | kə,laɪdə\'skɑpɪk/', 'kaleidoscopic', 6);
INSERT INTO `words` VALUES (13603, 'The kangaroo has a problem.', 'n. [动]袋鼠', '/,kænɡə\'ru: | ,kæŋgə\'ruː | ,kæŋɡə\'ru/', 'kangaroo', 6);
INSERT INTO `words` VALUES (13604, 'The TV’s gone kaput.', 'adj. 过时的, 故障的, 失败了的', '/kæ\'put | kə\'pʊt/', 'kaput', 6);
INSERT INTO `words` VALUES (13605, 'No, I had it when I walked out the door. Dad picked me up to drive me to karate.', 'n. [日] 空手道(日本的一种徒手自卫武术)', '/kə\'rɑ:te/', 'karate', 6);
INSERT INTO `words` VALUES (13606, NULL, 'n. 爱斯基摩人用的皮船, 皮船', '/\'kaiæk | \'kaɪæk/', 'kayak', 6);
INSERT INTO `words` VALUES (13607, 'a keen photographer', 'adj. 锋利的, 敏锐的, 敏捷的, 热心的, 渴望的', '/ki:n | kiːn | kin/', 'keen', 6);
INSERT INTO `words` VALUES (13608, 'mysteries beyond our ken', 'n. 视野, 知识领域, 见地', '/ken | kɛn/', 'ken', 6);
INSERT INTO `words` VALUES (13609, 'I took my dingy volume by the scroop, and hurled it into the dog- kennel, vowing I hated a good book.', 'n. 狗窝, 狗屋, 阴沟', '/\'ken(ə)l | \'kɛnl/', 'kennel', 6);
INSERT INTO `words` VALUES (13610, 'A minor diplomatic kerfuffle ensued as it turned out the cream was being illegally imported from Vietnam.', 'n. 混乱, 动乱', '/kə\'fʌfl | kə\'fʌf(ə)l | kɚ\'fʌfl/', 'kerfuffle', 6);
INSERT INTO `words` VALUES (13611, 'The kernel of that message was that peace must not be a source of advantage or disadvantage for anyone.', 'n. (硬壳果)仁, (去壳的)麦粒, 谷粒, (事物、问题的)核心, 要点, 精髓, 内核', '/\'kə:nəl | \'kɜːn(ə)l | \'kɝnl/', 'kernel', 6);
INSERT INTO `words` VALUES (13612, 'a bottle of tomato ketchup', 'n. 调味蕃茄酱', '/\'ketʃəp; -ʌp | \'kɛtʃəp/', 'ketchup', 6);
INSERT INTO `words` VALUES (13613, 'Police appealed for wit­nesses after a woman was kidnapped at gunpoint.', 'v. 绑架', '/\'kɪdnæp/', 'kidnap', 6);
INSERT INTO `words` VALUES (13614, 'a kidney transplant', 'n. 肾', '/\'kɪdni/', 'kidney', 6);
INSERT INTO `words` VALUES (13615, 'Don\'t be such a killjoy!', 'n. 令人扫兴的人', '/\'kɪldʒɔɪ/', 'killjoy', 6);
INSERT INTO `words` VALUES (13616, 'We’ll have to notify the next of kin of his death.', 'n. 亲属', '/kɪn/', 'kin', 6);
INSERT INTO `words` VALUES (13617, 'I came in and kindled a fire in the stove.', 'v. 点燃, 使着火, 引起, 照亮', '/\'kindl | \'kɪnd(ə)l | \'kɪndl/', 'kindle', 6);
INSERT INTO `words` VALUES (13618, 'kinetic energy', 'adj. (运)动的, 动力(学)的', '/ki\'netik, kai- | kɪ\'netɪk; kaɪ- | kɪ\'nɛtɪk/', 'kinetic', 6);
INSERT INTO `words` VALUES (13619, NULL, 'adj. 卷曲的, 古怪的', '/\'kinki | \'kɪŋkɪ | \'kɪŋki/', 'kinky', 6);
INSERT INTO `words` VALUES (13620, '\"We went into a market and established a kiosk in that market out of a butcher\'s shop,\" Kalanda says.', 'n. 亭子', '/\'ki:ɔsk, ki\'ɔsk | \'kiːɒsk | \'kiɑsk/', 'kiosk', 6);
INSERT INTO `words` VALUES (13621, NULL, 'v. 腌制， 熏制 by salting and smoking)', '/\'kɪpər | \'kɪpɚ/', 'kipper', 6);
INSERT INTO `words` VALUES (13622, NULL, 'n. 粗劣作品或工艺品', '/kitʃ | kɪtʃ/', 'kitsch', 6);
INSERT INTO `words` VALUES (13623, 'That cute puppy or kitten is not like a stuffed toy that can be left alone when you are finished with it.', 'n. 小猫, 小动物', '/\'kitən | \'kɪt(ə)n | \'kɪtn/', 'kitten', 6);
INSERT INTO `words` VALUES (13624, 'Crossing the channel to nineteenth-century Paris, Shteir tracks the rise of the department store and the pathologizing of shoplifting as kleptomania.', 'n. 盗窃癖', '/,kleptəu\'meiniə | ,kleptə(ʊ)\'meɪnɪə | \'klɛptə\'menɪə/', 'kleptomania', 6);
INSERT INTO `words` VALUES (13625, 'He\'s got the knack of getting people to listen.', 'n. 诀窍', '/næk/', 'knack', 6);
INSERT INTO `words` VALUES (13626, 'Some of the nurses would come in knackered after a day on A&E, strip till two in the morning and then go home.', 'adj. 筋疲力尽的', '/\'nækəd | \'nækɚd/', 'knackered', 6);
INSERT INTO `words` VALUES (13627, 'A crafty knave needs no broker.', 'n. 流氓', '/neiv | neɪv | nev/', 'knave', 6);
INSERT INTO `words` VALUES (13628, 'Knead the dough for three minutes.', 'v. 揉成， 捏制', '/niːd | nid/', 'knead', 6);
INSERT INTO `words` VALUES (13629, 'Tom knelt down and patted the dog.', 'v. 跪下', '/ni:l | niːl | nil/', 'kneel', 6);
INSERT INTO `words` VALUES (13630, 'My grandmother taught me how to knit.', 'v. 编织, 密接, 结合', '/nit | nɪt/', 'knit', 6);
INSERT INTO `words` VALUES (13631, 'what you long to know about a house when you put your hand on the knocker.', 'n. 门环', '/\'nɔkə | \'nɒkə | \'nɑkɚ/', 'knocker', 6);
INSERT INTO `words` VALUES (13632, 'Right about here, Seidler said, pointing to a gap of sage between our knoll and the houses, is where most of the pronghorn seem to cross through.', 'n. 小山', '/nəul | nəʊl | nol/', 'knoll', 6);
INSERT INTO `words` VALUES (13633, 'a knotty problem', 'adj. (木材等)多结的, 多节的, 多瘤的, 棘手的, 困难多的', '/\'nɔti | \'nɒtɪ | \'nɑti/', 'knotty', 6);
INSERT INTO `words` VALUES (13634, 'Do you think you are more knowledgeable about life than your parents were at your age?', 'adj. 知识渊博的, 有见识的', '/\'nɔlidʒəbl | \'nɒlɪdʒəb(ə)l | \'nɑlɪdʒəbl/', 'knowledgeable', 6);
INSERT INTO `words` VALUES (13635, 'Applied to all the steam valves, steamer universal valves, expanded knurl, the easy crystallization pumps and valves with high temperature and low speed.', 'n. 硬节', '/nɜːl | nɝl/', 'knurl', 6);
INSERT INTO `words` VALUES (13636, 'He acquired kudos just by appearing on television.', 'n. 名望, 荣誉, 声誉', '/\'kju:dəuz | \'kjuːdɒs | \'kudɑs/', 'kudos', 6);
INSERT INTO `words` VALUES (13637, 'Sex is used by histrionics to prop up their self-esteem and to regulate their labile sense of self-worth.', 'adj. 不安定的, 易发生变化的', '/\'leibail, -bil | \'leɪbɪl; -aɪl | \'lebɪl/', 'labile', 6);
INSERT INTO `words` VALUES (13638, 'the laborious business of drying the crops', 'adj. (指工作)艰苦的, 费力的, (指人)勤劳的', '/lə\'bɔ:riəs | lə\'bɔːrɪəs | lə\'bɔrɪəs/', 'laborious', 6);
INSERT INTO `words` VALUES (13639, 'The garage charges £30 an hour for labour.', 'n. 劳动, 劳力, 劳工, 努力, 分娩, 工作', '/\'leibə | \'leɪbə/', 'labour', 6);
INSERT INTO `words` VALUES (13640, 'Some of the episodes are very laboured.', 'adj. 吃力的, 谨慎的', '/\'leibəd | \'lebɚd/', 'laboured', 6);
INSERT INTO `words` VALUES (13641, '...the labyrinth of corridors.', 'n. 迷路, 迷宫, 难解的事物', '/\'læbərinθ | \'læb(ə)rɪnθ | \'læbərɪnθ/', 'labyrinth', 6);
INSERT INTO `words` VALUES (13642, 'a handkerchief trimmed with lace', 'n. 饰带, 花边, 缎带, 鞋带', '/leis | leɪs | les/', 'lace', 6);
