INSERT INTO `words` VALUES (13646, 'I suppose Catherine fulfilled her project, for the next sentence took up another subject: she waxed lachrymose.', 'adj. 爱哭的, 悲哀的', '/\'lækriməus | \'lækrɪməʊs; -z | \'lækrɪmos/', 'lachrymose', 6);
INSERT INTO `words` VALUES (13647, 'David has a rather lackadaisical approach to his work.', 'adj. 懒洋洋的', '/,lækə\'deizikəl | ,lækə\'deɪzɪk(ə)l | ,lækə\'dezɪkl/', 'lackadaisical', 6);
INSERT INTO `words` VALUES (13648, NULL, 'n. (穿制服的) 男仆, 侍从, 马屁精', '/\'læki | \'lækɪ/', 'lackey', 6);
INSERT INTO `words` VALUES (13649, NULL, 'n. 无光泽, 暗淡', '/\'læk,lʌstə/', 'lackluster', 6);
INSERT INTO `words` VALUES (13650, 'Usually so laconic in the office, Dr. Lahey seemed less guarded, more relaxed.', 'adj. (用词)简洁的, 简明的', '/lə\'kɔnik | lə\'kɒnɪk/', 'laconic', 6);
INSERT INTO `words` VALUES (13651, 'Kimchi has antibiotic functions as lactic acid bacteria produced in the process of fermentation suppresses growth of harmful bacteria.', 'adj. 乳的, 乳汁的', '/\'læktik | \'læktɪk/', 'lactic', 6);
INSERT INTO `words` VALUES (13652, '...laggard product lines such as Jif peanut butter.', 'adj. 缓慢的 迟缓的, 落后的', '/\'læɡəd | \'lægəd/', 'laggard', 6);
INSERT INTO `words` VALUES (13653, '...a fox\'s lair.', 'n. 窝', '/lεə | leə | lɛr/', 'lair', 6);
INSERT INTO `words` VALUES (13654, 'Thus, his preaching was directed at not only the laity, but the clergy as well.', 'n. 俗人, 外行', '/\'leiəti | \'leɪɪtɪ | \'leəti/', 'laity', 6);
INSERT INTO `words` VALUES (13655, 'And you can be sure that when the referee cheats our boys, I\'ll be ready to lambaste him.', 'v. 痛打, 严责', '/læm\'beist | læm\'beɪst | læm\'best/', 'lambaste', 6);
INSERT INTO `words` VALUES (13656, NULL, 'n. 薄片薄层, 薄片,[动]瓣,鳃,壳层,[植]菌褶', '/lə\'melə | lə\'mɛlə/', 'lamella', 6);
INSERT INTO `words` VALUES (13657, 'A lone piper played a lament.', 'n. 悲伤, 哀悼, 恸哭, 挽诗, 悼词', '/lə\'ment | lə\'mɛnt/', 'lament', 6);
INSERT INTO `words` VALUES (13658, 'a lamentable state of affairs', 'adj. 不快的', '/\'læməntəbl, lə\'men- | \'læməntəb(ə)l | \'læməntəbl/', 'lamentable', 6);
INSERT INTO `words` VALUES (13659, 'If you plan to use a cart for food preparation, choose one with a tough top like butcher block, stainless steel or plastic laminate.', 'v. 碾压', '/\'læmineit, -nit | \'læmɪneɪt | \'læmɪnət/', 'laminate', 6);
INSERT INTO `words` VALUES (13660, '...his scathing lampoons of consumer culture.', 'n. （嘲讽个人的）强烈讽刺文', '/læm\'pu:n | læm\'puːn | læm\'pun/', 'lampoon', 6);
INSERT INTO `words` VALUES (13661, NULL, 'n. 讽刺文作家, 冷嘲热讽者', '/læm\'pu:nə/', 'lampooner', 6);
INSERT INTO `words` VALUES (13662, '...the clang of lances striking armour.', 'n. 标枪, 长矛, 矛状器具, 捕鲸枪', '/lɑ:ns, læns | lɑːns | læns/', 'lance', 6);
INSERT INTO `words` VALUES (13663, NULL, 'n. 柳叶刀', '/\'lænsɪt/', 'lancet', 6);
INSERT INTO `words` VALUES (13664, NULL, 'vt. （除医学外现罕用的）刺, 刺痛, 撕裂', '/\'lɑ:nsineit, \'læn-/', 'lancinate', 6);
INSERT INTO `words` VALUES (13665, '...the landlocked West African nation of Mali.', 'adj. 为陆地所包围的', '/\'lændlɔkt | \'lændlɒkt | \'lændlɑkt/', 'landlocked', 6);
INSERT INTO `words` VALUES (13666, 'He won last month\'s presidential election by a landslide.', 'n. [地]山崩, 崩塌的泥石', '/\'læn(d)slaɪd | \'lændslaɪd/', 'landslide', 6);
INSERT INTO `words` VALUES (13667, 'He greeted Charles with a languid wave of his hand.', 'adj. 疲倦的, 无力的, 没精打采的', '/\'læŋɡwid | \'læŋgwɪd/', 'languid', 6);
INSERT INTO `words` VALUES (13668, 'The housing market continues to languish.', 'v. 憔悴, 凋萎, 衰退, 苦思', '/\'læŋɡwiʃ | \'læŋgwɪʃ | \'læŋɡwɪʃ/', 'languish', 6);
INSERT INTO `words` VALUES (13669, NULL, 'n. 衰弱无力', '/\'læŋɡə | \'læŋgə/', 'languor', 6);
