INSERT INTO `words` VALUES (13783, 'When Summers travelled by limousine or airplane, Sandberg gave up her seat next to him to make sure that other officials and staffers got time with the boss.', 'n. 豪华轿车', '/\'liməzi:n, ,limə\'z- | \'lɪməziːn; ,lɪmə\'ziːn | \'lɪməzin/', 'limousine', 6);
