INSERT INTO `words` VALUES (13789, 'I spent a week at Kandersteg and could happily have lingered on.', 'v. 逗留, 闲荡, 拖延, 游移', '/\'liŋɡə | \'lɪŋgə | \'lɪŋɡɚ/', 'linger', 6);
INSERT INTO `words` VALUES (13790, 'Mr Wilkins suffered a lingering death.', 'adj. 延迟的, 逗留不去的', '/\'liŋɡəriŋ | \'lɪŋgərɪŋ/', 'lingering', 6);
INSERT INTO `words` VALUES (13791, 'I’d like to go to Greece, but I don’t speak the lingo.', 'n. （尤指）方言, 行话, 隐语', '/\'liŋɡəu | \'lɪŋgəʊ | \'lɪŋgo/', 'lingo', 6);
INSERT INTO `words` VALUES (13792, 'Label contents are a mixture of static and dynamic content. Static content is multi-lingual.', 'adj. 语言的', '/\'liŋɡwəl | \'lɪŋgw(ə)l | \'lɪŋɡwəl/', 'lingual', 6);
INSERT INTO `words` VALUES (13793, 'Out with every theory of human behavior, from linguistics to sociology.', 'n. 语言学', '/liŋ\'ɡwistiks | lɪŋ\'gwɪstɪks | lɪŋ\'ɡwɪstɪks/', 'linguistics', 6);
INSERT INTO `words` VALUES (13794, '...a grey linoleum floor.', 'n. 油布, 油毯', '/li\'nəuliəm | lɪ\'nəʊlɪəm | lɪ\'nolɪəm/', 'linoleum', 6);
