INSERT INTO `words` VALUES (13797, 'And it\'s not as if the U.S. would export the excess supply, since the country lacks the infrastructure to easily liquefy large amounts of the gas to sell abroad.', 'v. (使)溶解, (使)液化', '/\'likwifai | \'lɪkwɪfaɪ/', 'liquefy', 6);
INSERT INTO `words` VALUES (13798, 'The stock was sold to liquidate the loan.', 'v. 清算', '/\'likwideit | \'lɪkwɪdeɪt | \'lɪkwɪdet/', 'liquidate', 6);
INSERT INTO `words` VALUES (13799, 'Hundreds of small businesses went into liquidation (= were closed ).', 'n. 清算', '/,likwi\'deiʃən | lɪkwɪ\'deɪʃ(ə)n | ,lɪkwɪ\'deʃən/', 'liquidation', 6);
INSERT INTO `words` VALUES (13800, NULL, 'n. 液体, 汁，酒精饮料, [药]溶液', '/\'likə | \'lɪkə | \'lɪkɚ/', 'liquor', 6);
INSERT INTO `words` VALUES (13801, NULL, 'adj. 柔软的（人体）', '/\'lisəm/', 'lissom', 6);
INSERT INTO `words` VALUES (13802, NULL, 'adj. 柔软的', '/\'lisəm | \'lɪsəm/', 'lissome', 6);
INSERT INTO `words` VALUES (13803, 'We are making a list of the top ten men we would not want to be married to.', 'n. 目录, 名单, 列表, 序列, 数据清单, 明细表, 条纹, [总称]各种上市证券', '/list | lɪst/', 'list', 6);
INSERT INTO `words` VALUES (13804, 'The heat was making me listless.', 'adj. 倦怠的, 冷漠的，情绪低落的', '/\'listlis | \'lɪs(t)lɪs | \'lɪstləs/', 'listless', 6);
INSERT INTO `words` VALUES (13805, 'In many cases, the people there are fighting, in a literal sense, for their homes.', 'adj. 文字的, 照字面上的, 无夸张的', '/\'litərəl | \'lɪt(ə)r(ə)l | \'lɪtərəl/', 'literal', 6);
INSERT INTO `words` VALUES (13806, '...the Australian storyteller who was loved by readers but disdained by the literati.', 'n. 文人, 文学界', '/,litə\'rɑ:ti:, \'rɑ:ti:, -\'reitai | ,lɪtə\'rɑːtɪ | ,lɪtə\'rɑti/', 'literati', 6);
INSERT INTO `words` VALUES (13807, 'the strong lithe bodies of gymnasts', 'adj. (指人、身体)柔软的, 易弯的', '/laið | laɪð/', 'lithe', 6);
INSERT INTO `words` VALUES (13808, 'How can I as a private litigant seek redress for defamation that ruins my business?', 'n. 诉讼人', '/\'litiɡənt | \'lɪtɪg(ə)nt | \'lɪtɪɡənt/', 'litigant', 6);
