INSERT INTO `words` VALUES (13810, 'Find the right “litmus test”, though, and what is now being done with TB drugs could succeed with any of these as well.', 'n. [化]石蕊', '/\'litməs | \'lɪtməs/', 'litmus', 6);
INSERT INTO `words` VALUES (13811, 'People who drop litter can be fined in some cities.', 'n. 垃圾，（供动物睡眠或防冻用的）干草、树叶, (一)窝, 轿, 担架', '/\'litə | \'lɪtə | \'lɪtɚ/', 'litter', 6);
INSERT INTO `words` VALUES (13812, NULL, 'n. <英>(公共场所的)废物箱', '/\'litəbin | \'lɪtəbɪn/', 'litterbin', 6);
INSERT INTO `words` VALUES (13813, 'The Navy also plans to buy additional submarines, including nuclear subs, and Landing Dock Platform ships for littoral warfare.', 'adj. 海滨的, 沿海的', '/\'litərəl | \'lɪt(ə)r(ə)l | \'lɪtərəl/', 'littoral', 6);
INSERT INTO `words` VALUES (13814, 'He read it loudly, his hands on his ears, in a passionate voice, following a liturgical rhythm.', 'adj. 礼拜式的', '/li\'tə:dʒikəl | lɪ\'tɜːdʒɪk(ə)l/', 'liturgical', 6);
INSERT INTO `words` VALUES (13815, 'A clergyman read the liturgy from the prayer-book.', 'n. 圣餐仪式, 礼拜仪式', '/\'litədʒi | \'lɪtədʒɪ/', 'liturgy', 6);
INSERT INTO `words` VALUES (13816, 'In many neighborhoods, someone forgot to plan for that basic building block of livable cities, the sidewalk.', 'adj. (房子,气候等)适于居住的, 可住的', '/\'livəbl | \'lɪvəbl/', 'livable', 6);
INSERT INTO `words` VALUES (13817, 'a lively Spanish dance', 'adj. 活泼的, 活跃的, 栩栩如生的, 真实的', '/\'laivli | \'laɪvlɪ | \'laɪvli/', 'lively', 6);
INSERT INTO `words` VALUES (13818, 'Inevitably HSC will become a promising way for liverish treatment.', 'adj. <口>患肝病的, 坏脾气的', '/\'livəriʃ | \'lɪv(ə)rɪʃ | \'lɪvərɪʃ/', 'liverish', 6);
INSERT INTO `words` VALUES (13819, 'livid bruises', 'adj. 铅色的, （被打得）青紫色的', '/\'livid | \'lɪvɪd/', 'livid', 6);
INSERT INTO `words` VALUES (13820, 'a loaf of bread', 'n. 一条面包, 块, 游荡', '/ləuf | ləʊf | lof/', 'loaf', 6);
