INSERT INTO `words` VALUES (13829, 'Flight is the form of locomotion that puts the greatest demands on muscles.', 'n. 运动, 移动, 运动力, 移动力', '/\'ləukə\'məuʃən | ləʊkə\'məʊʃ(ə)n | ,lokə\'moʃən/', 'locomotion', 6);
INSERT INTO `words` VALUES (13830, NULL, 'n. 机车, 火车头', '/\'ləukə,məutiv, ,ləukə\'m- | ləʊkə\'məʊtɪv | ,lokə\'motɪv/', 'locomotive', 6);
