INSERT INTO `words` VALUES (13833, NULL, 'n. 独特的措辞，惯用语，说话风格', '/ləu\'kju:ʃən | lə\'kjuːʃ(ə)n | lo\'kjʊʃən/', 'locution', 6);
INSERT INTO `words` VALUES (13834, 'There, copper plates near the entrance bear snippets of Morse code, and a naturally magnetized lodestone sits by a compass rose etched in granite.', 'n. 天然磁石, 吸引人的东西', '/\'ləudstəun | \'ləʊdstəʊn | \'lodston/', 'lodestone', 6);
