INSERT INTO `words` VALUES (13841, 'The skills and logistics of getting such a big show on the road pose enormous practical problems.', 'n. 后勤学, 后勤', '/ləu\'dʒistiks | lə\'dʒɪstɪks/', 'logistics', 6);
INSERT INTO `words` VALUES (13842, 'A new initiative was needed to break the logjam.', 'n. <美>（水道）受圆木阻塞, 停滞状态, 僵局', '/\'lɔɡdʒæm | \'lɒgdʒæm/', 'logjam', 6);
INSERT INTO `words` VALUES (13843, 'Five or six teenagers were loitering in front of the newsagent’s.', 'v. 闲荡, 虚度, 徘徊', '/\'lɔitə | \'lɒɪtə | \'lɔɪtɚ/', 'loiter', 6);
INSERT INTO `words` VALUES (13844, 'He was lolling on the sofa in the shadows near the fire.', 'v. 懒洋洋地倚靠', '/lɔl | lɒl | lɑl/', 'loll', 6);
INSERT INTO `words` VALUES (13845, 'His speeches tend to be rather long-winded.', 'adj. 冗长的', '/ˌlɔːŋ\'wɪndɪd | \'lɔŋ\'wɪndɪd/', 'long-winded', 6);
INSERT INTO `words` VALUES (13846, 'The ancient Chinese claimed that garlic promoted longevity.', 'n. 长命, 寿命，供职期限，资历', '/lɔn\'dʒevəti | lɒn\'dʒevɪtɪ | lɔn\'dʒɛvəti/', 'longevity', 6);
