INSERT INTO `words` VALUES (13849, 'And then they pointed to the empty loom, for they believed the other could doubtless see the cloth.', 'n. 织布机, 织机', '/lu:m | luːm | lum/', 'loom', 6);
INSERT INTO `words` VALUES (13850, NULL, 'n. 懒人, 笨蛋, [动物]潜鸟', '/lu:n | luːn | lun/', 'loon', 6);
INSERT INTO `words` VALUES (13851, 'Mrs. Morrell reached for a loop of garden hose.', 'n. 环, 线(绳)圈, 弯曲部分, 回路, 回线, (铁路)让车道, (飞机)翻圈飞行', '/lu:p | luːp | lup/', 'loop', 6);
INSERT INTO `words` VALUES (13852, 'You’ll need a spanner to loosen that bolt.', 'v. 变松， 松开', '/\'luːsn | \'lusn/', 'loosen', 6);
