INSERT INTO `words` VALUES (13855, 'Hugo would lope along the Concourse with his daughter on his back—the entire boulevard her domain.', 'v. (使)大步慢跑', '/ləup | ləʊp | lop/', 'lope', 6);
INSERT INTO `words` VALUES (13856, 'a lopsided 8-0 victory', 'adj. 倾向一方的， 不平衡的', '/ˌlɑːp\'saɪdɪd | ,lɑp\'saɪdɪd/', 'lopsided', 6);
INSERT INTO `words` VALUES (13857, 'He said that despite older adults being less “loquacious” or talkative than their younger adult counterparts, they elicit much more vocal responses when calling.', 'adj. 多话的, 饶舌的, 潺潺的', '/ləu\'kweiʃəs | lə\'kweɪʃəs | lə\'kweʃəs/', 'loquacious', 6);
INSERT INTO `words` VALUES (13858, 'According to local lore, a ghost still haunts the castle.', 'n. 学问，知识，（动物的）眼光知识', '/lɔ: | lɔː | lɔr/', 'lore', 6);
INSERT INTO `words` VALUES (13859, 'She tried to accept her marriage as her lot in life but could not.', 'v. 抽签； 划分; n. 签；命运', '/lɑːt | lɑt/', 'lot', 6);
INSERT INTO `words` VALUES (13860, 'a lottery ticket', 'n. 抽彩给奖法', '/\'lɔtəri | \'lɒt(ə)rɪ | \'lɑtəri/', 'lottery', 6);
