INSERT INTO `words` VALUES (13869, 'Thousands of ex-army officers have found lucrative jobs in private security firms.', 'adj. 有利的', '/\'lju:krətiv | \'luːkrətɪv | \'lukrətɪv/', 'lucrative', 6);
INSERT INTO `words` VALUES (13870, '...so they can feel less guilty about their piles of filthy lucre.', 'n. 收益, 钱财', '/\'lju:kə | \'luːkə | \'lukɚ/', 'lucre', 6);
