INSERT INTO `words` VALUES (13986, 'Then slowly slide down the wall, falling forward from the waist—like a marionette with slack strings.', 'n. 牵线木偶', '/,mæriə\'net | ,mærɪə\'net | ,mærɪə\'nɛt/', 'marionette', 6);
INSERT INTO `words` VALUES (13987, 'marital problems', 'adj. 婚姻的', '/\'mæritəl | \'mærɪt(ə)l | \'mærɪtl/', 'marital', 6);
INSERT INTO `words` VALUES (13988, 'a marmoreal complexion', 'adj. (象)大理石的, 冰冷的', '/mɑ:\'məuriəl | mɑː\'mɔːrɪəl/', 'marmoreal', 6);
INSERT INTO `words` VALUES (13989, 'I wore a maroon velvet trouser suit that my daughter chose, and most of the village came to the reception.', 'n. 栗色', '/mə\'ruːn | mə\'run/', 'maroon', 6);
INSERT INTO `words` VALUES (13990, 'As with Hakone marquetry, cherry-bark goods involve the decorative veneer of the bark being affixed to different base woods.', 'n. 镶嵌细工', '/\'mɑ:kitri | \'mɑːkɪtrɪ/', 'marquetry', 6);
INSERT INTO `words` VALUES (13991, 'a bone marrow transplant', 'n. 髓, 骨髓, 精华, 活力, <苏格兰>配偶', '/\'mærəu | \'mærəʊ | \'mæro/', 'marrow', 6);
INSERT INTO `words` VALUES (13992, NULL, 'n. 湿地, 沼泽, 沼泽地', '/mɑ:ʃ | mɑːʃ | mɑrʃ/', 'marsh', 6);
INSERT INTO `words` VALUES (13993, 'The company turned its attention to marshalling its creditors\' approval.', 'v. 整理， 安排， 排列', '/\'mɑːrʃl | \'mɑrʃəl/', 'marshal', 6);
INSERT INTO `words` VALUES (13994, 'A University of Muenster team drew up a marsupial family tree based on DNA.', 'n. 有袋动物', '/mɑ:\'sju:piəl | mɑː\'suːpɪəl | mɑr\'supɪəl/', 'marsupial', 6);
INSERT INTO `words` VALUES (13995, 'martial music', 'adj. 战争的， 军事的', '/\'mɑːrʃl | \'mɑrʃəl/', 'martial', 6);
INSERT INTO `words` VALUES (13996, 'The woman in charge was a martinet who treated us like children.', 'n. 规律严肃的人, 严格的人', '/,mɑ:ti\'net | ,mɑːtɪ\'net | ,mɑrtn\'ɛt/', 'martinet', 6);
INSERT INTO `words` VALUES (13997, 'St. Stephen, the first Christian martyr', 'n. 烈士, 殉教者', '/\'mɑ:tə | \'mɑːtə | \'mɑrtɚ/', 'martyr', 6);
INSERT INTO `words` VALUES (13998, '‘The man is a genius,’ marvelled Claire.', 'v. 对…感到惊异; n. 奇迹', '/\'mɑːrvl | \'mɑrvl/', 'marvel', 6);
INSERT INTO `words` VALUES (13999, 'the official mascot of the 2002 World Cup', 'n. 福神, 吉祥的东西', '/\'mæskət | \'mæskɒt | \'mæskɑt/', 'mascot', 6);
INSERT INTO `words` VALUES (14000, 'Mash the bananas.', 'v. 捣碎', '/mæʃ/', 'mash', 6);
INSERT INTO `words` VALUES (14001, 'a surgical face mask', 'n. 面具, 掩饰, 石膏面像', '/mɑ:sk, mæsk | mɑːsk | mæsk/', 'mask', 6);
INSERT INTO `words` VALUES (14002, NULL, 'n. 泥瓦匠', '/\'meisən | \'meɪs(ə)n | \'mesn/', 'mason', 6);
INSERT INTO `words` VALUES (14003, 'Several people were buried under falling masonry.', 'n. 石工术, 石匠职业', '/\'meisənri | \'meɪs(ə)nrɪ | \'mesənri/', 'masonry', 6);
INSERT INTO `words` VALUES (14004, 'Many also attend the masquerade ball.', 'n. 化妆舞会', '/,mæskə\'reid | ,mɑːskə\'reɪd; ,mæs- | ,mæskə\'red/', 'masquerade', 6);
INSERT INTO `words` VALUES (14005, 'the only survivor of the massacre', 'n. 残杀, 大屠杀', '/\'mæsəkə | \'mæsəkɚ/', 'massacre', 6);
INSERT INTO `words` VALUES (14006, 'The bell is massive, weighing over 40 tons.', 'adj. 厚重的, 大块的, 魁伟的, 结实的', '/\'mæsiv | \'mæsɪv/', 'massive', 6);
INSERT INTO `words` VALUES (14007, 'a radio mast', 'n. 桅, 桅杆, 柱, 旗杆, 天线竿', '/mɑ:st, mæst | mɑːst | mæst/', 'mast', 6);
INSERT INTO `words` VALUES (14008, 'The project was masterminded by Morris, then aged 29.', 'v. 策划', '/\'mɑ:stəmaind, \'mæs- | \'mɑːstəmaɪnd | \'mæstəmaɪnd/', 'mastermind', 6);
INSERT INTO `words` VALUES (14009, 'Hines slowly masticated a shrimp.', 'v. 咀嚼', '/\'mæstikeit | \'mæstɪkeɪt/', 'masticate', 6);
INSERT INTO `words` VALUES (14010, NULL, 'n. [古生]乳齿象, 庞然大物', '/\'mæstədɔn | \'mæstədɒn | \'mæstə,dɑn/', 'mastodon', 6);
INSERT INTO `words` VALUES (14011, 'Wipe your feet on the mat.', 'n. 席子, 垫子', '/mæt/', 'mat', 6);
INSERT INTO `words` VALUES (14012, 'Apparently sensitive to criticism，the bull forgot all about the matador and charged at the drunk.', 'n. 斗牛士', '/\'mætədɔ: | \'mætədɔː | \'mætədɔr/', 'matador', 6);
INSERT INTO `words` VALUES (14013, 'The figure of a man suddenly materialized in the shadows.', 'v. 物化', '/mə\'tiəriəlaiz | mə\'tɪrɪəlaɪz/', 'materialize', 6);
INSERT INTO `words` VALUES (14014, NULL, 'adj. 平易近人的, 友好的', '/\'meiti | \'meɪtɪ | \'meti/', 'matey', 6);
INSERT INTO `words` VALUES (14015, 'She was the main authority-figure in the home. Jeb describes it as having been, \"A kind of matriarchy... when we were growing up, dad wasn\'t at home.', 'n. 女家长制, 女族长制', '/\'meitriɑ:ki | \'meɪtrɪɑːkɪ | \'metrɪɑrki/', 'matriarchy', 6);
INSERT INTO `words` VALUES (14016, 'He matriculated in the English Literature Department at the Tokyo Imperial University.', 'v. 录取', '/mə\'trɪkjuleɪt | mə\'trɪkjulet/', 'matriculate', 6);
INSERT INTO `words` VALUES (14017, 'a matrix table', 'n. 矩阵', '/\'meitriks | \'meɪtrɪks | \'metrɪks/', 'matrix', 6);
INSERT INTO `words` VALUES (14018, '...a creamy white matte emulsion.', 'adj. 无光泽的', '/mæt/', 'matte', 6);
INSERT INTO `words` VALUES (14019, 'The ten young people sleep between two hard, narrow beds and one large mattress on the floor with no privacy at all.', 'n. 床垫, 空气垫, (用以护堤等的)沉床', '/\'mætris | \'mætrɪs | \'mætrəs/', 'mattress', 6);
INSERT INTO `words` VALUES (14020, 'Laura is very mature for her age .', 'adj. 成熟的； 深思熟虑的', '/mə\'tʃur | mə\'tʃʊr/', 'mature', 6);
INSERT INTO `words` VALUES (14021, 'Beth shows a maturity way beyond her 16 years.', 'n. 成热, 完备, (票据)到期, 成熟', '/mə\'tjuəriti | mə\'tʃʊərətɪ | mə\'tʃʊrəti/', 'maturity', 6);
INSERT INTO `words` VALUES (14022, 'a song that is tender without being maudlin', 'adj. 感情脆弱的', '/\'mɔ:dlin | \'mɔːdlɪn | \'mɔdlɪn/', 'maudlin', 6);
INSERT INTO `words` VALUES (14023, 'A man that beareth false witness against his neighbour [is] a maul, and a sword, and a sharp arrow.', 'n. 大槌', '/mɔ:l | mɔːl | mɔl/', 'maul', 6);
INSERT INTO `words` VALUES (14024, NULL, 'v. 胡扯； 游荡', '/\'mɔːndər/', 'maunder', 6);
INSERT INTO `words` VALUES (14025, NULL, 'n. 没打烙印的动物', '/\'mæv(ə)rɪk | \'mævərɪk/', 'maverick', 6);
INSERT INTO `words` VALUES (14026, 'But, as a former war reporter myself, I recoil from the mawkish sentimentality with which we enshrine our casualties.', 'adj. 令人厌恶的', '/\'mɔ:kiʃ | \'mɔːkɪʃ/', 'mawkish', 6);
INSERT INTO `words` VALUES (14027, 'I believe in the maxim \"if it ain\'t broke, don\'t fix it.\"', 'n. 格言, 座右铭', '/\'mæksim | \'mæksɪm/', 'maxim', 6);
INSERT INTO `words` VALUES (14028, NULL, 'n. 伤害罪之一种, 故意的伤害罪', '/\'meihem | \'meɪhem | \'mehɛm/', 'mayhem', 6);
INSERT INTO `words` VALUES (14029, 'We got completely lost in the maze.', 'n. 曲径, 迷宫, 迷津, 迷惘, 迷惑, 糊涂', '/meiz | meɪz | mez/', 'maze', 6);
INSERT INTO `words` VALUES (14030, 'The meadow has been ploughed up.', 'n. 草地, 牧场', '/\'medəu | \'medəʊ | \'mɛdo/', 'meadow', 6);
INSERT INTO `words` VALUES (14031, NULL, 'n. 兆', '/\'mi:ɡə | \'migɚ/', 'meager', 6);
INSERT INTO `words` VALUES (14032, 'He’s too mean to buy a present for his wife.', 'adj. 吝啬的', '/miːn | min/', 'mean', 6);
INSERT INTO `words` VALUES (14033, 'We took a gravel road that meandered through farmland.', 'n. 漫步, 弯曲, 曲流', '/mi\'ændə | mɪ\'ændə | mɪ\'ændɚ/', 'meander', 6);
INSERT INTO `words` VALUES (14034, NULL, 'n. [医]麻疹, 风疹, 包虫病, 痧子', '/\'mi:zlz | \'miːz(ə)lz | \'mizəlz/', 'measles', 6);
INSERT INTO `words` VALUES (14035, 'All I got was a measly £5.', 'adj. 患麻疹的； 少得可怜的， 微不足道的', '/\'miːzli | \'mizli/', 'measly', 6);
INSERT INTO `words` VALUES (14036, 'a measured response to the problem', 'adj. 标准的, 整齐的, 有规则的', '/\'meʒəd | \'mɛʒɚd/', 'measured', 6);
INSERT INTO `words` VALUES (14037, 'Thailand has become the tourist mecca of Asia.', 'n. 众人渴望去的地方', '/\'mekə/', 'mecca', 6);
INSERT INTO `words` VALUES (14038, 'the brake mechanism', 'n. 结构， 机制', '/\'mekənɪzəm | \'mɛkənɪzəm/', 'mechanism', 6);
INSERT INTO `words` VALUES (14039, 'She won a gold medal at the last Olympics.', 'n. 奖章, 勋章, 纪念章', '/\'medəl | \'med(ə)l | \'mɛdl/', 'medal', 6);
INSERT INTO `words` VALUES (14040, 'He accused the US of meddling in China’s internal affairs .', 'v. 干涉， 干预', '/\'medl | \'mɛdl/', 'meddle', 6);
INSERT INTO `words` VALUES (14041, 'a meddlesome old woman', 'adj. 爱管闲事的, 好干涉的', '/\'medlsəm | \'med(ə)ls(ə)m | \'mɛdlsəm/', 'meddlesome', 6);
INSERT INTO `words` VALUES (14042, 'The median age of the group is 42.', 'adj. 中央的, [数学] 中线的, 中值的', '/\'miːdɪən | \'midɪən/', 'median', 6);
INSERT INTO `words` VALUES (14043, NULL, 'v. 用药物医治； 加药于', '/\'medɪkeɪt | \'mɛdɪ,ket/', 'medicate', 6);
INSERT INTO `words` VALUES (14044, 'These spices were first brought to Italy from the East in medieval times.', 'adj. 中世纪的, 仿中世纪的, 老式的, <贬>原始的', '/,medi\'i:vəl, ,mi:- | ˌmediˈi:vl | ,midɪ\'ivəl/', 'medieval', 6);
INSERT INTO `words` VALUES (14045, NULL, 'adj. 普普通通的', '/,mi:di\'əukə, \'mi:diəukə | ,miːdɪ\'əʊkə | ,midɪ\'okɚ/', 'mediocre', 6);
INSERT INTO `words` VALUES (14046, '...the mediocrity of most contemporary literature.', 'n. 平常, 平庸之才', '/,mi:di\'ɔkrəti, ,med- | miːdɪ\'ɒkrɪtɪ/', 'mediocrity', 6);
INSERT INTO `words` VALUES (14047, 'Yoga involves breathing exercises, stretching, and meditation.', 'n. 沉思， 冥想', '/ˌmedɪ\'teɪʃn | ,mɛdɪ\'teʃən/', 'meditation', 6);
INSERT INTO `words` VALUES (14048, 'She was in a meditative mood.', 'adj. 沉思的, 爱思考的, 冥想的', '/\'meditətiv, -teit- | \'medɪ,tətɪv; -,teɪtɪv | \'mɛdɪtetɪv/', 'meditative', 6);
INSERT INTO `words` VALUES (14049, 'Advertising is a powerful medium.', 'n. 媒体, 方法, 媒介', '/\'mi:diəm, -djəm | \'miːdɪəm | \'midɪəm/', 'medium', 6);
INSERT INTO `words` VALUES (14050, 'the 400 metres individual medley', 'n. 混杂的人群, 杂乱的一团, 混合物, 杂录, [音]集成曲', '/\'medli | \'medlɪ | \'mɛdli/', 'medley', 6);
INSERT INTO `words` VALUES (14051, 'He was always so meek and mild .', 'adj. 温顺的, 谦恭的, (河流等)和缓的, 驯服的', '/mi:k | miːk | mik/', 'meek', 6);
INSERT INTO `words` VALUES (14052, 'The reporter walks into park of relics of earthquake of Qing Chuandong bayou, engraving on megalith together \" 2008;\"', 'n. [考古](古建筑用的)巨石', '/\'meɡəliθ | \'megəlɪθ | \'mɛɡəlɪθ/', 'megalith', 6);
INSERT INTO `words` VALUES (14053, 'In Germany, the minister of justice, Sabine Leutheusser-Schnarrenberger, complained recently about Google’s instinct for “pressing ahead” and its “megalomania.”', 'n. [医]夸大狂, 妄自尊大', '/,meɡələu\'meiniə | ,meg(ə)lə(ʊ)\'meɪnɪə | ,mɛɡələ\'menɪə/', 'megalomania', 6);
INSERT INTO `words` VALUES (14054, 'He sank into deep melancholy.', 'n. 忧郁', '/\'melənkəli | \'melənkəlɪ | \'mɛlənkɑli/', 'melancholy', 6);
INSERT INTO `words` VALUES (14055, 'She sang the first verse again, listening to the way the words melded with the music.', 'v. 混合, 合并', '/meld/', 'meld', 6);
INSERT INTO `words` VALUES (14056, 'I grew up around people who had wonderful, mellifluous voices.', 'adj. 如蜜般的, 流畅的', '/mə\'lifluəs | me\'lɪflʊəs | mɛ\'lɪfluəs/', 'mellifluous', 6);
INSERT INTO `words` VALUES (14057, 'He spoke in a quiet melodious voice.', 'adj. 音调优美的', '/mi\'ləudjəs | mɪ\'ləʊdɪəs | mə\'lodɪəs/', 'melodious', 6);
INSERT INTO `words` VALUES (14058, 'He was behaving like a character in a Victorian melodrama.', 'n. 情节剧', '/\'melə,drɑ:mə, -dræmə | \'melə(ʊ)drɑːmə | \'mɛlədrɑmə/', 'melodrama', 6);
INSERT INTO `words` VALUES (14059, NULL, 'n. 悦耳的音调', '/\'melədi | \'melədɪ | \'mɛlədi/', 'melody', 6);
INSERT INTO `words` VALUES (14060, '...some juicy slices of melon.', 'n. (各种的)瓜', '/\'melən | \'mɛlən/', 'melon', 6);
INSERT INTO `words` VALUES (14061, 'Loud noise can damage the delicate membrane in the ear.', 'n. 膜, 隔膜', '/\'membrein | \'membreɪn | \'mɛmbren/', 'membrane', 6);
INSERT INTO `words` VALUES (14062, 'More anglers are taking cameras when they go fishing to provide a memento of catches.', 'n. 纪念品', '/me\'mentəu | mɪˈmentəʊ | mɪˈmɛnto/', 'memento', 6);
INSERT INTO `words` VALUES (14063, 'Building a memorial to Columbus has been his lifelong dream.', 'n. 纪念物, 纪念馆, 纪念议事, 请愿书', '/英 [mə\'mɔ:rɪəl] 美 [məˈmɔriəl, -ˈmor | mə\'mɔːrɪəl | mə\'morɪəl/', 'memorial', 6);
INSERT INTO `words` VALUES (14064, 'the growing menace of oil pollution at sea', 'n. 威胁, 危险物', '/\'menəs | \'mɛnəs/', 'menace', 6);
INSERT INTO `words` VALUES (14065, 'Hey, Beethoven: Get a full-time job, a part-time business, a spouse, a few kids, and a menagerie of pets and wait till you see how many symphonies you can crank out!', 'n. 动物园, 动物展览', '/mi\'nædʒəri | mə\'nædʒ(ə)rɪ | mə\'nædʒəri/', 'menagerie', 6);
INSERT INTO `words` VALUES (14066, 'When are you going to mend that light in the hall?', 'v. 修改， 改进', '/mend | mɛnd/', 'mend', 6);
INSERT INTO `words` VALUES (14067, 'mendacious propaganda', 'adj. 虚假的, 说谎的', '/men\'deiʃəs | men\'deɪʃəs/', 'mendacious', 6);
INSERT INTO `words` VALUES (14068, '...an astonishing display of cowardice and mendacity.', 'n. 撒谎癖, 虚假, 谎言', '/men\'dæsəti | men\'dæsətɪ | mɛn\'dæsəti/', 'mendacity', 6);
INSERT INTO `words` VALUES (14069, 'Long after this, in a street in Bolpur, a mendicant Baul was singing as he walked along', 'adj. 乞丐的', '/\'mendikənt | \'mendɪk(ə)nt | \'mɛndɪkənt/', 'mendicant', 6);
INSERT INTO `words` VALUES (14070, 'Jesus specialized in menial tasks that everyone else tried to avoid: washing feet, helping children, fixing breakfast, and serving lepers.', 'adj. 仆人的', '/\'mi:niəl, -njəl | \'miːnɪəl | \'minjəl/', 'menial', 6);
INSERT INTO `words` VALUES (14071, NULL, 'adj. <罕>每月一次的, 每月的, 餐桌的', '/\'mensəl/', 'mensal', 6);
INSERT INTO `words` VALUES (14072, 'They covered the affected parts with menthol.', 'n. 薄荷醇', '/\'menθɔːl | \'mɛnθɔl/', 'menthol', 6);
INSERT INTO `words` VALUES (14073, 'Leon Sullivan was my mentor and my friend.', 'n. [希神]门特(良师益友), 贤明的顾问, 导师, 指导者', '/\'mɛn\'tɔr | \'mentɔːr/', 'mentor', 6);
INSERT INTO `words` VALUES (14074, 'She did it for purely mercenary reasons.', 'adj. 唯利是图的', '/\'mə:sinəri | \'mɜːsɪn(ə)rɪ | \'mɝsənɛri/', 'mercenary', 6);
INSERT INTO `words` VALUES (14075, 'A range of official Disney merchandise was on sale.', 'n. 商品, 货物', '/\'mə:tʃəndaiz, -dais | \'mɜːtʃ(ə)ndaɪs; -z | \'mɝtʃəndaɪs/', 'merchandise', 6);
INSERT INTO `words` VALUES (14076, 'an actor noted for his mercurial temperament', 'adj. 墨丘利神的, 水星的, 雄辩机智的, 活泼善变的, 水银的', '/mə:\'kjuəriəl | mɜː\'kjʊərɪəl | mɝ\'kjʊrɪəl/', 'mercurial', 6);
INSERT INTO `words` VALUES (14077, 'She lost the election by a mere 20 votes.', 'adj. 仅仅的, 起码的, 纯粹的', '/miə | mɪə | mɪr/', 'mere', 6);
INSERT INTO `words` VALUES (14078, '...vulgar, meretricious, and shabby souvenirs.', 'adj. 华丽而庸俗的, 俗气的, 娼妓的, 适合娼妓的', '/,meri\'triʃəs | ,merɪ\'trɪʃəs | \'mɛrə\'trɪʃəs/', 'meretricious', 6);
INSERT INTO `words` VALUES (14079, 'The company plans to merge its subsidiaries in the US.', 'v. 合并, 并入, 结合, 吞没, 融合', '/mə:dʒ | mɜːdʒ | mɝdʒ/', 'merge', 6);
INSERT INTO `words` VALUES (14080, 'The results have been encouraging enough to merit further investigation.', 'v. 值得; n. 价值； 长处', '/\'merɪt | \'mɛrɪt/', 'merit', 6);
INSERT INTO `words` VALUES (14081, NULL, 'adj. 该得的， 理所当然的', '/\'merɪtɪd/', 'merited', 6);
INSERT INTO `words` VALUES (14082, 'The expected budget announcement today that meritorious teachers will be paid bonuses, based on NAPLAN test results and other criteria, is a step along the path.', 'adj. 有功的', '/,meri\'tɔ:riəs | ,merɪ\'tɔːrɪəs | \'mɛrə\'tɔrɪəs/', 'meritorious', 6);
INSERT INTO `words` VALUES (14083, NULL, 'n. (传说中的)美人鱼, <美>女子游泳健将', '/\'mə:meid | \'mɜːmeɪd | \'mɝmed/', 'mermaid', 6);
INSERT INTO `words` VALUES (14084, NULL, 'n. [地]台地, 岩石台地, 平顶山', '/\'meisə | \'meɪsə/', 'mesa', 6);
INSERT INTO `words` VALUES (14085, NULL, 'n. 催眠术， 催眠引导法', '/\'mezmərɪzəm | \'mɛzmə\'rɪzəm/', 'mesmerism', 6);
INSERT INTO `words` VALUES (14086, NULL, 'v. 施催眠术', '/\'mezməraiz, \'mes- | \'mɛzməraɪz/', 'mesmerize', 6);
INSERT INTO `words` VALUES (14087, 'From curtilage (messuage sits south, the gate is northern) the sitting room is unfavorable take too much space, draw on fire and lawsuit easily otherwise.', 'n. 家宅', '/\'meswidʒ | \'meswɪdʒ | \'mɛswɪdʒ/', 'messuage', 6);
INSERT INTO `words` VALUES (14088, 'This drug speeds up your metabolism.', 'n. 新陈代谢, 变形', '/mi\'tæbəlizəm, me- | mɪ\'tæbəlɪz(ə)m | mɛ\'tæbəlɪzəm/', 'metabolism', 6);
INSERT INTO `words` VALUES (14089, 'It took me some time to undergo the metamorphosis from teacher to lecturer.', 'n. 变形', '/,metə\'mɔ:fəsis | ,metə\'mɔːfəsɪs; ,metəmɔː\'fəʊsɪs | \'mɛtə\'mɔrfəsɪs/', 'metamorphosis', 6);
INSERT INTO `words` VALUES (14090, 'She uses some wonderful images and metaphors in her writing.', 'n. [修辞]隐喻, 暗喻, 比喻说话', '/\'metəfə | \'metəfə; -fɔː | \'mɛtəfɚ/', 'metaphor', 6);
INSERT INTO `words` VALUES (14091, 'The word has a metaphorical as well as a literal meaning.', 'adj. 隐喻性的, 比喻性的', '/,metə\'fɔrik-\'fɔ:,-kəl | ,metə\'fɒrɪkl | \'mɛtə\'fɔrɪkl/', 'metaphorical', 6);
INSERT INTO `words` VALUES (14092, 'If SNS wants to press the meaning of its metaphrase \" social network serves \" for, the history should be quite long.', 'v. 直译', '/\'metəfreɪz | \'mɛtə,frez/', 'metaphrase', 6);
