INSERT INTO `words` VALUES (14103, '...a type of bacteria that include the microbes responsible for tuberculosis and leprosy.', 'n. 微生物, 细菌', '/\'maikrəub | \'maɪkrəʊb | \'maɪkrob/', 'microbe', 6);
