INSERT INTO `words` VALUES (14108, 'the mighty Mississippi river', 'adj. 强有力的， 强大的； 巨大的', '/\'maɪti/', 'mighty', 6);
INSERT INTO `words` VALUES (14109, 'The government divides asylum seekers into economic migrants and genuine refugees.', 'n. 候鸟, 移居者', '/\'maiɡrənt | \'maɪgr(ə)nt | \'maɪɡrənt/', 'migrant', 6);
INSERT INTO `words` VALUES (14110, 'The room smelled of mildew.', 'n. 霉, 霉菌, (植物的)霉病', '/\'mildju:, -du: | \'mɪldjuː | \'mɪldu/', 'mildew', 6);
