INSERT INTO `words` VALUES (14120, 'One of his few strengths was his skill at mimicry.', 'n. 模仿', '/\'mimikri | \'mɪmɪkrɪ | \'mɪmɪkri/', 'mimicry', 6);
INSERT INTO `words` VALUES (14121, 'Do not look that powerful nation individual contestant impulse feet and so on Indonesia, Malaysia, their minacity and the destructive power are limited.', 'n. 威吓性,威胁性', '/mi\'næsəti/', 'minacity', 6);
INSERT INTO `words` VALUES (14122, 'They blasted a minaret too.', 'n. 尖塔', '/\'minəret, ,minə\'ret | \'mɪnəret; ,mɪnə\'ret | ,mɪnə\'rɛt/', 'minaret', 6);
INSERT INTO `words` VALUES (14123, 'How eliminate this kind of harmful information \" is content minatory \"?', 'adj. 威胁的', '/\'minətəri | \'mɪnə,t(ə)rɪ | \'mɪnə,təri/', 'minatory', 6);
