INSERT INTO `words` VALUES (14126, 'My godmother never gives me anything but mingy ten shillings at Christmas.', 'adj. 卑鄙的, 吝啬的', '/\'mindʒi | \'mɪn(d)ʒɪ/', 'mingy', 6);
INSERT INTO `words` VALUES (14127, 'She’s her mother in miniature.', 'n. 缩小的模型, 缩图, 缩影', '/\'miniətʃə | \'mɪnɪtʃə | ˈmɪniətʃɚ; ˈmɪnɪtʃɚ/', 'miniature', 6);
INSERT INTO `words` VALUES (14128, 'Don’t fall into the trap of becoming a mindless minion.', 'n. 奴才, 宠臣', '/\'mɪnjən | \'mɪnɪən/', 'minion', 6);
INSERT INTO `words` VALUES (14129, 'The ghastly minnow is part of the largest family of freshwater fish—but so far its fangs are unique.', 'n. 鲤科小鱼', '/\'minəu | \'mɪnəʊ | \'mɪno/', 'minnow', 6);
