INSERT INTO `words` VALUES (14135, 'Perhaps we are just chasing a mirage.', 'n. 海市蜃楼, 雾气, 幻想, 妄想', '/\'mirɑ:ʒ, mi\'rɑ:ʒ | \'mɪrɑːʒ; mɪ\'rɑːʒ | mə\'rɑʒ/', 'mirage', 6);
