INSERT INTO `words` VALUES (14138, 'But the miry places thereof and the marishes thereof shall not be healed; they shall be given to salt.', 'adj. 泥泞的', '/\'maiəri | \'maɪrɪ/', 'miry', 6);
INSERT INTO `words` VALUES (14139, 'It was a hopeless misalliance.', 'n. 不适当的结合', '/ˌmɪsə\'laɪəns | \'mɪsə\'laɪəns/', 'misalliance', 6);
INSERT INTO `words` VALUES (14140, 'If this all strikes you as fancy, handlebar moustache talk from an old misanthrope who doesn\'t get things like whatever the hell we\'re calling “conversations” this week, maybe you\'re on to something.', 'n. 厌恶人类的人, 不愿与人来往者', '/\'mizənθrəup, \'mis- | \'mɪz(ə)nθrəʊp; mɪs- | \'mɪsənθrop/', 'misanthrope', 6);
INSERT INTO `words` VALUES (14141, 'I think we should clear up this misapprehension.', 'n. 误会， 误解', '/\'mis,æpri\'henʃən | ˌmɪsæprɪ\'henʃn/', 'misapprehension', 6);
INSERT INTO `words` VALUES (14142, 'a miscellaneous assortment of books', 'adj. 各色各样混在一起, 混杂的, 多才多艺的', '/,misi\'leinjəs, \'misə\'leiniəs | ,mɪsə\'leɪnɪəs | \'mɪsə\'lenɪəs/', 'miscellaneous', 6);
INSERT INTO `words` VALUES (14143, '...glass cases filled with a miscellany of objects.', 'n. 杂物, (miscellanies)杂录, 杂记', '/mi\'seləni, \'misəleini | mɪ\'selənɪ | \'mɪsəleni/', 'miscellany', 6);
