INSERT INTO `words` VALUES (14146, 'His behaviour could easily be misconstrued.', 'v. 误解, 曲解', '/\'miskən\'stru: | mɪskən\'struː | ,mɪskən\'stru/', 'misconstrue', 6);
INSERT INTO `words` VALUES (14147, 'Local people demanded that the police apprehend the miscreants.', 'adj. 堕落的, 卑劣的, 异端的', '/\'miskriənt | \'mɪskrɪənt/', 'miscreant', 6);
