INSERT INTO `words` VALUES (14155, 'Nativism, xenophobia, racism, Islamophobia and misogyny are all on the rise. If the voices of intolerance prevail, the world risks entering a dark era.', 'n. 厌恶女人', '/mɪ\'sɑːdʒɪni | maɪ\'sɑdʒɪni/', 'misogyny', 6);
