INSERT INTO `words` VALUES (14162, 'An anonymous missive had been pushed under her door.', 'n. 信件， 公函', '/\'mɪsɪv/', 'missive', 6);
INSERT INTO `words` VALUES (14163, 'Along the Rh ? ne Valley, occasional strong , cold , dry , north - to - northwesterly wind known as the mistral .', 'n. 寒冷西北风', '/\'mistrəl, ,mis\'trɑ: | \'mɪstr(ə)l; mɪ\'strɑːl | \'mɪstrəl/', 'mistral', 6);
