INSERT INTO `words` VALUES (14167, 'The Canadian Oxford Dictionary also lists garbage mitt—a new one on me—that is supposedly a heavily padded deerskin mitten favoured by garbage men.', 'n. 棒球手套, 拳击手套', '/\'mitən | \'mɪt(ə)n | \'mɪtn/', 'mitten', 6);
INSERT INTO `words` VALUES (14168, 'When encountering information such as this, your goal should be to compress it. Find ways to group information into smaller chunks of memory through pictures or mnemonics.', 'n. 记忆术', '/ni:\'mɔniks | nɪ\'mɒnɪks; niː- | ni\'mɑnɪks/', 'mnemonics', 6);
INSERT INTO `words` VALUES (14169, 'She gave a little moan of pleasure.', 'n. 呻吟, 哀悼, 呼啸', '/məun | məʊn | mon/', 'moan', 6);
