INSERT INTO `words` VALUES (14173, 'Opposition MPs mocked the government’s decision.', 'v. 嘲笑, 骗, 挫败, 嘲弄', '/mɒk | mɑk/', 'mock', 6);
INSERT INTO `words` VALUES (14174, 'Set the monitor to 256 colour mode.', 'n. 样式； 模式； 方式， 形式； 时尚， 风尚', '/moud | mod/', 'mode', 6);
