INSERT INTO `words` VALUES (14176, 'He drinks moderately.', 'adv. 适度地， 有节制地', '/\'mɑːdərətli | \'mɑdərətli/', 'moderately', 6);
INSERT INTO `words` VALUES (14177, NULL, 'adj. 中板的', '/,mɔdə\'rɑ:təu | ,mɒdə\'rɑːtəʊ | ,mɑdə\'rɑto/', 'moderato', 6);
