INSERT INTO `words` VALUES (14182, 'a modicum of common sense', 'n. 少量, 一点点', '/\'mɔdikəm | \'mɒdɪkəm | \'mɑdɪkəm/', 'modicum', 6);
INSERT INTO `words` VALUES (14183, 'They have used the same process for almost 50 years with only minor modifications .', 'n. 更改, 修改, 修正', '/,mɔdifi\'keiʃən | ,mɒdɪfɪ\'keɪʃ(ə)n | ,mɑdɪfɪ\'keʃən/', 'modification', 6);
INSERT INTO `words` VALUES (14184, 'I circle a misplaced modifier and wait as they make the fix.', 'n. 修改者； 修饰语', '/\'mɑːdɪfaɪər | \'mɑdə\'faɪɚ/', 'modifier', 6);
