INSERT INTO `words` VALUES (14186, '...a short checklist of much that is modish at the moment.', 'adj. 流行的, 时髦的', '/\'məudiʃ | \'məʊdɪʃ | \'modɪʃ/', 'modish', 6);
INSERT INTO `words` VALUES (14187, 'He carefully modulated his voice.', 'v. 调整, 调节, (信号)调制', '/\'mɔdjuleit, -dʒu- | \'mɒdjʊleɪt | \'mɑdʒəlet/', 'modulate', 6);
