INSERT INTO `words` VALUES (14198, 'He had been mollycoddled as a young boy.', 'n. 娇惯的男人, 懦夫', '/\'mɔli,kɔdl | \'mɒlɪkɒd(ə)l | \'mɑlɪkɑdl/', 'mollycoddle', 6);
INSERT INTO `words` VALUES (14199, 'Like other penguins, it undergoes an annual molt, replacing all its feathers in a few weeks.', 'n. 换毛, 脱皮, 换毛期', '/məult | məʊlt | molt/', 'molt', 6);
