INSERT INTO `words` VALUES (14201, 'He was here a moment ago .', 'n. 瞬间； 重要', '/\'moumənt | \'momənt/', 'moment', 6);
INSERT INTO `words` VALUES (14202, 'She was momentarily lost for words.', 'adv. 暂时地； 片刻， 立刻', '/ˌmoumən\'terəli | ,momən\'tɛrəli/', 'momentarily', 6);
INSERT INTO `words` VALUES (14203, 'There was a momentary pause.', 'adj. 瞬间的, 刹那间的', '/\'məuməntəri | \'məʊm(ə)nt(ə)rɪ | \'moməntɛri/', 'momentary', 6);
INSERT INTO `words` VALUES (14204, 'a momentous decision', 'adj. 重大的, 重要的', '/məu\'mentəs | mə(ʊ)\'mentəs | mo\'mɛntəs/', 'momentous', 6);
INSERT INTO `words` VALUES (14205, 'incentives to maintain the momentum of European integration', 'n. 动力, 要素', '/məu\'mentəm | mə\'mentəm | mo\'mɛntəm/', 'momentum', 6);
INSERT INTO `words` VALUES (14206, 'The monarch was ousted by a military coup.', 'n. 君主', '/\'mɔnək, -ɑ:k | \'mɒnək | \'mɑnɚk/', 'monarch', 6);
INSERT INTO `words` VALUES (14207, 'He has cloistered himself in a monastery for more than thirty years.', 'n. 修道院, 僧侣', '/\'mɔnəstəri | \'mɒnəst(ə)rɪ | \'mɑnəstɛri/', 'monastery', 6);
INSERT INTO `words` VALUES (14208, NULL, 'n. 修道院生活, 修道院制度', '/mə\'næstisizəm | mə\'næstɪsɪzəm/', 'monasticism', 6);
INSERT INTO `words` VALUES (14209, 'Improved control circuit places monaural image in a stereo field.', 'adj. 单耳(听觉)的, 非立体声的', '/,mɔn\'ɔ:rəl | mɒn\'ɔːr(ə)l/', 'monaural', 6);
INSERT INTO `words` VALUES (14210, 'the government’s tight monetary policy', 'adj. 金钱的； 货币的', '/\'mʌnɪteri | \'mʌnɪtɛri/', 'monetary', 6);
INSERT INTO `words` VALUES (14211, NULL, 'n. 先天愚型病', '/\'mɔŋɡəlizəm; mɔn- | \'mɒŋg(ə)lɪz(ə)m/', 'mongolism', 6);
INSERT INTO `words` VALUES (14212, NULL, 'n. <贬>杂种(指人), 杂种狗, 混血儿', '/\'mʌŋɡrəl, \'mɔŋ- | \'mʌŋgr(ə)l | \'mʌŋɡrəl/', 'mongrel', 6);
INSERT INTO `words` VALUES (14213, 'This obviously is the limiting case of the idealized monochromatic wave .', 'adj. 单色的', '/ˌmɑːnəkrou\'mætɪk | ,mɑnəkrə\'mætɪk/', 'monochromatic', 6);
INSERT INTO `words` VALUES (14214, 'What about a monocle?', 'n. 单片眼镜', '/\'mɑːnəkl | \'mɑnəkl/', 'monocle', 6);
INSERT INTO `words` VALUES (14215, 'Monogamy is rare in most animal groups, but is common among birds.', 'n. 一夫一妻制, [动]单配偶, 单配性', '/mɔ\'nɔɡəmi, mə- | mə\'nɒgəmɪ | mə\'nɑɡəmi/', 'monogamy', 6);
INSERT INTO `words` VALUES (14216, '...a monograph on her favourite author, John Updike.', 'n. 专论', '/\'mɔnəɡrɑ:f, -ɡræf | \'mɒnəgrɑːf | \'mɑnəɡræf/', 'monograph', 6);
INSERT INTO `words` VALUES (14217, 'It is misleading to see the legal system as a monolith.', 'n. 单块巨石； 单一的庞大组织', '/\'mɑːnəlɪθ | \'mɑnə\'lɪθ/', 'monolith', 6);
INSERT INTO `words` VALUES (14218, 'This monolithic environment for an application eliminated any concern about which clock to use -- because there was only one clock.', 'n. 单片电路, 单块集成电路', '/,mɔnəu\'liθik | mɒnə\'lɪθɪk | ,mɑnə\'lɪθɪk/', 'monolithic', 6);
INSERT INTO `words` VALUES (14219, 'Henry looked up, then continued his monologue.', 'n. 独白, 独脚戏', '/\'mɔnəlɔɡ | \'mɒn(ə)lɒg | \'mɑnəlɔɡ/', 'monologue', 6);
INSERT INTO `words` VALUES (14220, 'The company has monopolized the soft drinks market.', 'v. 垄断， 独占', '/mə\'nɑːpəlaɪz | mə\'nɑpə\'laɪz/', 'monopolize', 6);
INSERT INTO `words` VALUES (14221, 'a monopoly in copper trading', 'n. 垄断, 垄断者, 专利权, 专利事业', '/mə\'nɔpəli | mə\'nɒp(ə)lɪ | mə\'nɑpəli/', 'monopoly', 6);
INSERT INTO `words` VALUES (14222, 'a monotonous diet', 'adj. 单调的, 无变化的', '/mə\'nɔtənəs | mə\'nɒt(ə)nəs | mə\'nɑtənəs/', 'monotonous', 6);
INSERT INTO `words` VALUES (14223, 'A night on the town may help to break the monotony of the week.', 'n. 单调， 千篇一律', '/mə\'nɑːtəni | mə\'nɑtəni/', 'monotony', 6);
INSERT INTO `words` VALUES (14224, '...the end of the monsoon.', 'n. 季候风, (印度等地的)雨季, 季风', '/mɔn\'su:n | mɒn\'suːn | ,mɑn\'sun/', 'monsoon', 6);
INSERT INTO `words` VALUES (14225, 'the remains of a prehistoric monster', 'n. 怪物, 妖怪', '/\'mɔnstə | \'mɒnstə | \'mɑnstɚ/', 'monster', 6);
INSERT INTO `words` VALUES (14226, 'A hard-money advocate, suspicious of personal debt, Jackson viewed the Bank as a monstrosity that gave power over the people\'s money to a few unelected private bankers.', 'n. 畸形', '/mɔn\'strɔsəti | mɒn\'strɒsɪtɪ/', 'monstrosity', 6);
INSERT INTO `words` VALUES (14227, 'a monstrous nose', 'adj. 巨大的, 畸形的, 怪异的, 恐怖的, 凶暴的', '/\'mɔnstrəs | \'mɒnstrəs | \'mɑnstrəs/', 'monstrous', 6);
INSERT INTO `words` VALUES (14228, 'a monumental contribution to the field of medicine', 'adj. 极大的； 纪念碑的', '/ˌmɑːnju\'mentl | ,mɑnju\'mɛntl/', 'monumental', 6);
INSERT INTO `words` VALUES (14229, NULL, 'v. 流浪, 缓行', '/mu:tʃ | muːtʃ | mutʃ/', 'mooch', 6);
INSERT INTO `words` VALUES (14230, 'a moody teenager', 'adj. 喜怒无常的； 抑郁的', '/\'muːdi | \'mudi/', 'moody', 6);
INSERT INTO `words` VALUES (14231, 'They went grouse shooting up on the moors.', 'n. 沼地, 荒野', '/muə, mɔ: | mɔː; mʊə/', 'moor', 6);
INSERT INTO `words` VALUES (14232, 'a temporary mooring', 'n. 停泊处', '/\'muəriŋ, \'mɔ:- | \'mɔːrɪŋ; \'mʊə- | \'mʊrɪŋ/', 'mooring', 6);
INSERT INTO `words` VALUES (14233, 'Don’t lie there moping on a lovely morning like this!', 'v. 闷闷不乐', '/məup | məʊp | mop/', 'mope', 6);
INSERT INTO `words` VALUES (14234, NULL, 'n. 闲荡', '/\'məʊp(ə)rɪ | \'məupəri/', 'mopery', 6);
INSERT INTO `words` VALUES (14235, 'This little blond moppet, gentle and kind and interested in the world.', 'n. 小孩, 娃娃, 宝宝', '/\'mɔpit | \'mɒpɪt | \'mɑpɪt/', 'moppet', 6);
INSERT INTO `words` VALUES (14236, 'A win is always good for morale.', 'n. 士气, 民心', '/mɔ\'rɑ:l, -\'ræl | mə\'rɑːl | mə\'ræl/', 'morale', 6);
INSERT INTO `words` VALUES (14237, 'a narrow-minded moralist', 'n. 道德家, 有道德的人, 伦理学者', '/\'mɔrəlist | \'mɒr(ə)lɪst | \'mɔrəlɪst/', 'moralist', 6);
INSERT INTO `words` VALUES (14238, 'It’s difficult to talk to teenagers about drugs without sounding too moralistic.', 'adj. 道学的, 说教的, 教训的', '/,mɔrə\'listik, ,mɔ:- | mɒrə\'lɪstɪk | ,mɔrə\'lɪstɪk/', 'moralistic', 6);
INSERT INTO `words` VALUES (14239, 'But in the morass of all this minutiae, we seem to be missing the point.', 'n. 沼泽', '/mə\'ræs, mɔ:- | mə\'ræs/', 'morass', 6);
INSERT INTO `words` VALUES (14240, 'a two-year moratorium on interest payments', 'n. 延期偿付, 延期偿付期间', '/,mɔrə\'tɔ:riəm, ,mɔ:- | ,mɒrə\'tɔːrɪəm | ,mɔrə\'tɔrɪəm/', 'moratorium', 6);
INSERT INTO `words` VALUES (14241, 'a morbid gene', 'adj. 病的, 由病引起的, 病态的, 恐怖的', '/\'mɔ:bid | \'mɔːbɪd | \'mɔrbɪd/', 'morbid', 6);
INSERT INTO `words` VALUES (14242, 'They do not need a third burden of high morbidity and mortality from crashes, accidents, injuries, and violence.', 'n. 病态, 不健全, 发病率', '/mɔ:\'bidəti | mɔː\'bɪdətɪ | mɔr\'bɪdəti/', 'morbidity', 6);
INSERT INTO `words` VALUES (14243, 'The play’s mordant comedy makes for compelling viewing.', 'n. 媒染, 媒染剂, 金属腐蚀剂, 金属箔粘着剂', '/\'mɔ:dənt | \'mɔːd(ə)nt | \'mɔrdnt/', 'mordant', 6);
INSERT INTO `words` VALUES (14244, 'contemporary social and sexual mores', 'n. 风俗, 习惯, 民德, 道德观念', '/\'mɔ:ri:z | \'mɔːreɪz; -riːz | \'mɔrez/', 'mores', 6);
INSERT INTO `words` VALUES (14245, 'The region’s heavy industry is still inefficient and moribund.', 'adj. 垂死的', '/\'mɔribʌnd | \'mɒrɪbʌnd | \'mɔrɪbʌnd/', 'moribund', 6);
INSERT INTO `words` VALUES (14246, 'Don’t leave it there, you moron!', 'n. <口>低能者, 笨人, [医]痴愚者(指智商在50-70之间的成年人), [心]性(欲)倒错者, 性反常者', '/\'mɔ:rɔn, \'məu- | \'mɔːrɒn | \'mɔrɑn/', 'moron', 6);
INSERT INTO `words` VALUES (14247, 'Daniel seems very morose and gloomy.', 'adj. 郁闷的, 乖僻的', '/mə\'rəus | mə\'rəʊs | mə\'ros/', 'morose', 6);
INSERT INTO `words` VALUES (14248, NULL, '[复]n. [用作单][语]语素学,词素学', '/mɔ:\'fi:miks | mɔː\'fiːmɪks | mɔr\'fimɪks/', 'morphemics', 6);
INSERT INTO `words` VALUES (14249, '...a delicious little morsel of meat.', 'n. (食物)一口, 少量', '/\'mɔ:sel | \'mɔːs(ə)l | \'mɔrsl/', 'morsel', 6);
INSERT INTO `words` VALUES (14250, NULL, 'n. 通知猎物已死的号角声, 大量, 许多', '/mɔːt/', 'mort', 6);
INSERT INTO `words` VALUES (14251, 'Mortality from heart disease varies widely across the world.', 'n. 死亡率', '/mɔːr\'tæləti | mɔr\'tæləti/', 'mortality', 6);
INSERT INTO `words` VALUES (14252, 'A cameraman was killed when his vehicle came under mortar fire .', 'n. 臼, 研钵, 灰泥, 迫击炮', '/\'mɔːtə | \'mɔrtɚ/', 'mortar', 6);
INSERT INTO `words` VALUES (14253, 'The bank refused to accept any mortgage on land.', 'n. 抵押', '/\'mɔ:ɡidʒ | \'mɔːgɪdʒ | \'mɔrɡɪdʒ/', 'mortgage', 6);
INSERT INTO `words` VALUES (14254, 'The chairman tried to disguise his mortification.', 'n. 羞辱, 禁欲, 动物体组织局部的坏死', '/,mɔ:tifi\'keiʃən | ,mɔːtɪfɪ\'keɪʃn/', 'mortification', 6);
INSERT INTO `words` VALUES (14255, 'Jane mortified her family by leaving her husband.', 'v. 克服, 苦修, 使苦恼', '/\'mɔ:tifai | \'mɔːtɪfaɪ | \'mɔrtɪfaɪ/', 'mortify', 6);
INSERT INTO `words` VALUES (14256, NULL, 'n. 榫眼, 印刷版穴', '/\'mɔ:tis | \'mɔːtɪs | \'mɔrtɪs/', 'mortise', 6);
INSERT INTO `words` VALUES (14257, 'If you try any monkey tricks with me, I will shoot you right away, and your family can come and collect your body in the mortuary.', 'n. 停尸房, 太平间', '/\'mɔ:tjuəri, -tʃuə- | \'mɔːtjʊərɪ; -tʃʊ- | \'mɔrtʃuɛri/', 'mortuary', 6);
INSERT INTO `words` VALUES (14258, 'rooms decorated with wall paintings and mosaics', 'n. 镶嵌, 镶嵌图案, 镶嵌工艺', '/məu\'zeiik | mə(ʊ)\'zeɪɪk | mo\'zeɪk/', 'mosaic', 6);
INSERT INTO `words` VALUES (14259, 'A tiny particle; a mote.', 'n. 尘埃, 微粒', '/məut | məʊt/', 'mote', 6);
INSERT INTO `words` VALUES (14260, NULL, 'n. 赞美诗, 圣歌, 赞歌', '/məu\'tet | məʊ\'tet | mo\'tɛt/', 'motet', 6);
INSERT INTO `words` VALUES (14261, NULL, 'n. 卫生球, 樟脑球', '/\'mɔθbɔ:l, \'mɔ:θbɔ:l | \'mɒθbɔːl | \'mɔθbɔl/', 'mothball', 6);
INSERT INTO `words` VALUES (14262, 'The theme of creation is a recurrent motif in Celtic mythology.', 'n. 主题, 主旨, 动机, 图形', '/məu\'ti:f, mɔ- | məʊ\'tiːf | mo\'tif/', 'motif', 6);
INSERT INTO `words` VALUES (14263, 'The spores and gametes could grow to new thalli independently, and the same to motile zygotes.', 'adj. 能动的', '/\'moutaɪl | \'motɪl/', 'motile', 6);
INSERT INTO `words` VALUES (14264, 'Marijuana can decrease sperm motility and increase the number of abnormal sperm.', 'n. 运动性', '/mou\'tɪləti | moʊˈtɪləti/', 'motility', 6);
INSERT INTO `words` VALUES (14265, 'A good teacher has to be able to motivate her students.', 'v. 激发', '/\'məutiveit | \'məʊtɪveɪt | \'motə\'vet/', 'motivate', 6);
INSERT INTO `words` VALUES (14266, 'Jack is an intelligent pupil, but he lacks motivation.', 'n. 动机', '/,məuti\'veiʃən | məʊtɪ\'veɪʃ(ə)n | ,motə\'veʃən/', 'motivation', 6);
INSERT INTO `words` VALUES (14267, '...a motley collection of vans, old buses, cattle trucks, and even a fire engine.', 'adj. 杂色的, 五颜六色的, 穿染色衣的, 混杂的', '/\'mɔtli | \'mɒtlɪ | \'mɑtli/', 'motley', 6);
INSERT INTO `words` VALUES (14268, 'His red, mottled face showed the effect of too much whisky.', 'adj. 杂色的, 斑驳的', '/\'mɔtld | \'mɑtld/', 'mottled', 6);
INSERT INTO `words` VALUES (14269, '‘Be prepared’ is the motto of the Boy Scouts.', 'n. 座右铭, 格言, 题词, 笺言', '/\'mɔtəu | \'mɒtəʊ | \'mɑto/', 'motto', 6);
INSERT INTO `words` VALUES (14270, 'Another method, used especially for figures, was to pour the clay into a mould.', 'n. [亦作mold] 肥土, 壤土, [亦作mold] 霉, 模具', '/məuld | məʊld/', 'mould', 6);
INSERT INTO `words` VALUES (14271, NULL, 'n. 制模工, 铸工', '/\'məuldə | \'məʊldə | \'moldɚ/', 'moulder', 6);
INSERT INTO `words` VALUES (14272, 'The catalytic oxidation ability of 13 metal ion-exchanged montmorillonites are investigated in oxidative removal of the sulfides which are the main pollutant in the moult and alkali swell waste water.', 'n. 换毛, 脱毛', '/məult | məʊlt | molt/', 'moult', 6);
INSERT INTO `words` VALUES (14273, 'The two children, picked up by some policeman and placed in the refuge, or stolen by some mountebank, or having simply strayed off in that immense Chinese puzzle of a Paris, did not return.', 'n. 江湖郎中, 骗子', '/\'mauntibæŋk | \'maʊntɪbæŋk/', 'mountebank', 6);
INSERT INTO `words` VALUES (14274, 'Hundreds of people gathered to mourn the slain president.', 'v. 哀悼, 忧伤, 服丧', '/mɔ:n, məun | mɔːn | mɔrn/', 'mourn', 6);
INSERT INTO `words` VALUES (14275, 'Durant was thin, mournful and silent.', 'adj. 悲哀的', '/\'mɔ:nful, \'məun- | \'mɔːnfʊl; -f(ə)l | \'mɔrnfl/', 'mournful', 6);
INSERT INTO `words` VALUES (14276, 'It\'s part of a broader nationalist movement that\'s gaining strength throughout the country.', 'n. 运动, 动作, 运转, 乐章', '/\'mu:vmənt | \'muːvm(ə)nt | \'muvmənt/', 'movement', 6);
INSERT INTO `words` VALUES (14277, 'He’s a small kid, but he has plenty of moxie.', 'n. 精力, 勇气, 胆量', '/\'mɔksi | \'mɒksɪ | \'mɑksi/', 'moxie', 6);
INSERT INTO `words` VALUES (14278, 'They tested two types of mucilage — a gelatinous substance produced by the cactus — in contaminated water.', 'n. (植物的)黏液, 胶水', '/\'mju:silidʒ | \'mjuːsɪlɪdʒ | \'mjʊsəlɪdʒ/', 'mucilage', 6);
INSERT INTO `words` VALUES (14279, 'special machinery for spreading muck onto the fields', 'n. 粪肥, 垃圾, 肥料', '/mʌk/', 'muck', 6);
INSERT INTO `words` VALUES (14280, NULL, 'n. 揭开丑闻的文章', '/\'mʌkreik | \'mʌkreɪk | \'mʌk,rek/', 'muckrake', 6);
INSERT INTO `words` VALUES (14281, 'The twins are so alike that it’s easy to muddle them up.', 'v. 混合, 使微醉, 使咬字不清晰, 鬼混', '/\'mʌdl | \'mʌd(ə)l/', 'muddle', 6);
INSERT INTO `words` VALUES (14282, 'Take your boots off outside if they’re muddy.', 'adj. 多泥的， 泥泞的； 浑浊的， 不清的', '/\'mʌdi/', 'muddy', 6);
INSERT INTO `words` VALUES (14283, NULL, 'adj. 皮手笼, 保温的, 笨拙的人, 接球失败', '/mʌf/', 'muff', 6);
INSERT INTO `words` VALUES (14284, 'The falling snow muffled the sound of our footsteps.', 'v. 包, 蒙住, 压抑(声音)', '/\'mʌfl | \'mʌf(ə)l/', 'muffle', 6);
INSERT INTO `words` VALUES (14285, 'He moved to Bogotá, where he lived with relatives and worked in an auto muffler shop.', 'n. 消声器', '/\'mʌflə | \'mʌflɚ/', 'muffler', 6);
INSERT INTO `words` VALUES (14286, 'a coffee mug', 'n. 杯子', '/mʌg | mʌɡ/', 'mug', 6);
INSERT INTO `words` VALUES (14287, 'It was muggy and overcast.', 'adj. 闷热的', '/\'mʌɡi | \'mʌgɪ/', 'muggy', 6);
INSERT INTO `words` VALUES (14288, NULL, 'n. 桑树, 桑葚, 深紫红色', '/\'mʌlbəri | \'mʌlb(ə)rɪ | \'mʌl\'bɛri/', 'mulberry', 6);
INSERT INTO `words` VALUES (14289, 'a mulish look', 'adj. 骡一样的， 执拗的', '/\'mjuːlɪʃ | \'mjulɪʃ/', 'mulish', 6);
INSERT INTO `words` VALUES (14290, 'He’s mulling over the proposals before making any changes.', 'v. 思考，思索; n. 混乱', '/mʌl/', 'mull', 6);
INSERT INTO `words` VALUES (14291, 'a multicellular organism', 'adj. 多细胞的', '/ˌmʌlti\'seljələr | ,mʌlti\'sɛljəlɚ; ,mʌltaɪsɛljəlɚ/', 'multicellular', 6);
INSERT INTO `words` VALUES (14292, 'a multifaceted campaign to reduce teen pregnancy', 'adj. 多方面的', '/ˌmʌlti\'fæsɪtɪd | ,mʌltɪ\'fæsɪtɪd/', 'multifaceted', 6);
INSERT INTO `words` VALUES (14293, 'multifarious business activities', 'adj. 种种的, 各式各样的', '/,mʌlti\'fεəriəs | ,mʌltɪ\'feərɪəs | ,mʌltɪ\'fɛrɪəs/', 'multifarious', 6);
INSERT INTO `words` VALUES (14294, 'Baxter was rushed to the hospital with multiple stab wounds.', 'adj. 多样的， 多重的', '/\'mʌltɪpl | \'mʌltəpl/', 'multiple', 6);
INSERT INTO `words` VALUES (14295, 'It also explains why we use a specific multiplicity in the correspondence.', 'n. 多样性', '/ˌmʌltɪ\'plɪsəti | ,mʌltɪ\'plɪsəti/', 'multiplicity', 6);
INSERT INTO `words` VALUES (14296, 'Bacteria multiply quickly in warm food.', 'v. 乘； 增加； 繁殖', '/\'mʌltɪplaɪ/', 'multiply', 6);
INSERT INTO `words` VALUES (14297, 'I had never seen such a multitude of stars before.', 'n. 多数, 群众', '/\'mʌlti,tju:d, -,tu:d | \'mʌltɪtjuːd | ˈmʌltɪˌtud, -ˌtjud/', 'multitude', 6);
