INSERT INTO `words` VALUES (14301, 'Luke munched the chicken sandwiches.', 'v. 用力咀嚼， 出声咀嚼', '/mʌntʃ/', 'munch', 6);
INSERT INTO `words` VALUES (14302, 'Initially, the work was pretty mundane.', 'adj. 世界的, 世俗的, 平凡的', '/,mʌn\'dein, \'mʌnd- | \'mʌndeɪn; mʌn\'deɪn | mʌn\'den/', 'mundane', 6);
INSERT INTO `words` VALUES (14303, 'the municipality of Berkeley', 'n. 自治市； 市政当局', '/mjuːˌnɪsɪ\'pæləti | mjʊ\'nɪsə\'pæləti/', 'municipality', 6);
INSERT INTO `words` VALUES (14304, 'The tolerance he that old daddy take into to my bug munificence have gets the man sort.', 'n. 慷慨给予， 宽宏大量', '/mju:\'nifisəns | mjuː\'nɪfɪsns/', 'munificence', 6);
INSERT INTO `words` VALUES (14305, 'a munificent gift', 'adj. 宽宏的, 慷慨的', '/mju:\'nifisənt | mjuːˈnɪfɪsnt | mju\'nɪfɪsnt/', 'munificent', 6);
INSERT INTO `words` VALUES (14306, NULL, 'n. 契据', '/\'mju:nimənts | \'mjuːnɪmənts/', 'muniments', 6);
