INSERT INTO `words` VALUES (14308, 'a munitions factory', 'n. 军需品(munition之复数)', '/mju:\'niʃnz/', 'munitions', 6);
INSERT INTO `words` VALUES (14309, 'Pour a little glue into some shallow containers, dip cotton balls in the glue and then stick onto the paper - you have a snow mural!', 'adj. 墙壁上的', '/\'mjuərəl | \'mjʊər(ə)l | \'mjʊrəl/', 'mural', 6);
INSERT INTO `words` VALUES (14310, 'This murderous lunatic could kill them both without a second thought.', 'adj. 蓄意谋杀的， 凶残的； 极厉害的， 要命的', '/\'mɜːrdərəs | \'mɝdərəs/', 'murderous', 6);
INSERT INTO `words` VALUES (14311, 'murky water', 'adj. 黑暗的', '/\'mə:ki | \'mɜːkɪ | \'mɝki/', 'murky', 6);
INSERT INTO `words` VALUES (14312, 'She replied in a low murmur.', 'n. 低沉连续的声音, 咕哝, 怨言, 低语', '/\'mə:mə | \'mɜːmə | \'mɝmɚ/', 'murmur', 6);
INSERT INTO `words` VALUES (14313, NULL, 'n. 苔藓植物学', '/mʌs\'kɔlədʒi/', 'muscology', 6);
INSERT INTO `words` VALUES (14314, '‘Somewhere,’ he mused, ‘I’ve heard your name before.’', 'v. 沉思', '/mju:z | mjuːz | mjuz/', 'muse', 6);
INSERT INTO `words` VALUES (14315, 'Cook for two minutes until soft but not mushy.', 'adj. 糊状的, 玉米粥状的', '/\'mʌʃi | \'mʌʃɪ/', 'mushy', 6);
INSERT INTO `words` VALUES (14316, NULL, 'n. 旧式步枪， 毛瑟枪', '/\'mʌskɪt/', 'musket', 6);
INSERT INTO `words` VALUES (14317, 'In April 1185, he began to muster an army .', 'n. 集合, 阅, 样品, 清单, 一群', '/\'mʌstə | \'mʌstɚ/', 'muster', 6);
INSERT INTO `words` VALUES (14318, 'Urban lifestyle retreats are in high demand and they are much more than mutable trends.', 'adj. 可变的； 易变的', '/\'mjuːtəbl | \'mjutəbl/', 'mutable', 6);
INSERT INTO `words` VALUES (14319, 'Simple organisms like bacteria mutate rapidly.', 'v. 变异', '/\'mjuːteɪt | \'mjutet/', 'mutate', 6);
INSERT INTO `words` VALUES (14320, NULL, 'n. 变化, 转变, 元音变化, (生物物种的)突变', '/mju:\'teiʃən | mjuː\'teɪʃ(ə)n | mju\'teʃən/', 'mutation', 6);
INSERT INTO `words` VALUES (14321, 'Billy continued to stand there, mute and defiant.', 'n. 哑巴, 哑音字母, [律]拒不答辩的被告, 弱音器', '/mju:t | mjuːt | mjut/', 'mute', 6);
INSERT INTO `words` VALUES (14322, 'Everyone was sitting round discussing the accident in muted voices.', 'adj. 减弱的， 变得轻柔的', '/\'mjuːtɪd | \'mju:tid/', 'muted', 6);
INSERT INTO `words` VALUES (14323, 'The prisoners had been tortured and mutilated.', 'v. 毁伤', '/\'mju:tileit | \'mjuːtɪleɪt | \'mjʊtl\'et/', 'mutilate', 6);
INSERT INTO `words` VALUES (14324, 'Mr Fini was ostensibly a high-minded mutineer.', 'n. 叛徒, 反抗者', '/,mju:ti\'niə | mjuːtɪ\'nɪə/', 'mutineer', 6);
INSERT INTO `words` VALUES (14325, 'There was a mutinous look in Rosie’s eyes.', 'adj. 暴动的, 反抗的', '/\'mju:tinəs | \'mjuːtɪnəs/', 'mutinous', 6);
INSERT INTO `words` VALUES (14326, 'Elsie muttered something I couldn’t catch and walked off.', 'v. 咕哝， 嘀咕', '/\'mʌtər | \'mʌtɚ/', 'mutter', 6);
INSERT INTO `words` VALUES (14327, '...a leg of mutton.', 'n. 羊肉, <谑>绵羊, <俚>女性生殖器, 性交', '/\'mʌt(ə)n | \'mʌtn/', 'mutton', 6);
INSERT INTO `words` VALUES (14328, 'The idea is create an organisation embracing mutuality as well as free market capitalism.', 'n. 相互关系, 相关', '/\'mju:tʃu\'æləti, -tju- | \'mjuːtʃʊ\'ælətɪ | ˌmjuːtʃuˈæləti/', 'mutuality', 6);
INSERT INTO `words` VALUES (14329, 'Juliet’s head felt muzzy , and she hoped she hadn’t a cold coming on.', 'adj. 头脑发昏的, 无精神的, 酩酊的', '/\'mʌzi | \'mʌzɪ/', 'muzzy', 6);
INSERT INTO `words` VALUES (14330, 'The main symptoms are fever, chills, headache, malaise and muscle pain (myalgia).', 'n. 肌痛', '/mai\'ældʒiə | maɪ\'ældʒə/', 'myalgia', 6);
INSERT INTO `words` VALUES (14331, 'It is active in under- and postgraduate training in the fields of botany, mycology , and plant physiology.', 'n. [植]真菌学', '/mai\'kɔlədʒi | maɪ\'kɒlədʒɪ | maɪ\'kɑlədʒi/', 'mycology', 6);
INSERT INTO `words` VALUES (14332, 'Serious eye strain can lead to persistent headaches, muscle pain in the head, neck and upper back, as well as long term problems like myopia.', 'n. 近视', '/mai\'əupiə | maɪ\'əʊpɪə | maɪ\'opɪə/', 'myopia', 6);
INSERT INTO `words` VALUES (14333, 'the government’s myopic attitude to environmental issues', 'adj. 近视眼的； 目光短浅的， 缺乏远见的', '/maɪ\'oupɪk | maɪ\'ɑpɪk/', 'myopic', 6);
INSERT INTO `words` VALUES (14334, 'We’re still studying a myriad of options.', 'n. 无数, 无数的人或物, <诗>一万', '/\'miriəd | \'mɪrɪəd/', 'myriad', 6);
INSERT INTO `words` VALUES (14335, '...mystic union with God.', 'adj. 神秘的；谜样的，难解的; n. 神秘主义者', '/\'mɪstɪk | \'mistik/', 'mystic', 6);
INSERT INTO `words` VALUES (14336, 'As a younger man Harrison was intrigued by Indian mysticism.', 'n. 神秘主义', '/\'mɪstɪsɪzəm/', 'mysticism', 6);
INSERT INTO `words` VALUES (14337, 'Some of the mystique surrounding the presidency has gone forever.', 'n. 神秘性, 奥秘, 秘法', '/mi\'sti:k | mɪ\'stiːk | mɪ\'stik/', 'mystique', 6);
INSERT INTO `words` VALUES (14338, 'a book of Greek myths', 'n. 神话, 神话式的人物(或事物), 虚构的故事, 荒诞的说法', '/miθ | mɪθ/', 'myth', 6);
INSERT INTO `words` VALUES (14339, '...the mythic figure of King Arthur.', 'adj. 神话的； 虚构的', '/\'miθik | \'mɪθɪk/', 'mythic', 6);
INSERT INTO `words` VALUES (14340, 'characters from classical mythology', 'n. 神话', '/mi\'θɔlɔdʒi | mɪ\'θɒlədʒɪ | mɪ\'θɑlədʒi/', 'mythology', 6);
INSERT INTO `words` VALUES (14341, 'M precedes N in the alphabet.', 'n. 字母n', '/en | ɛn/', 'n', 6);
INSERT INTO `words` VALUES (14342, 'The police nabbed him for speeding.', 'v. <口>捉住, 逮捕, 抢夺', '/næb/', 'nab', 6);
INSERT INTO `words` VALUES (14343, 'By 1932, the depression had reached its nadir.', 'n. [天] 天底, 最底点, 最低点', '/\'nei,diə, \'næ- | \'neɪdɪə; \'nædɪə | \'nedɪr/', 'nadir', 6);
INSERT INTO `words` VALUES (14344, 'Don’t be such a nag!', 'n. 老马, 驽马, 劣等竞赛马, (作坐骑的)矮小马, 唠叨', '/næɡ | næg/', 'nag', 6);
INSERT INTO `words` VALUES (14345, 'a naive young girl', 'adj. 天真的， 纯朴的', '/naɪ\'iːv | naɪ\'iv/', 'naive', 6);
INSERT INTO `words` VALUES (14346, NULL, 'n. 天真的言行举止； 天真无邪', '/naɪ\'iːvəti | na:\'i:vtei/', 'naivete', 6);
INSERT INTO `words` VALUES (14347, NULL, 'n. 天真烂漫, 无邪的行为', '/na:\'i:vti | naɪ\'iːvtɪ; nɑː\'iːvtɪ/', 'naivety', 6);
INSERT INTO `words` VALUES (14348, 'For some people soccer has a reputation as a rather namby-pamby sport.', 'adj. 乏味的；懦弱的; n. 懦弱的人', '/,næmbi\'pæmbi | ˌnæmbɪ\'pæmbɪ/', 'namby-pamby', 6);
INSERT INTO `words` VALUES (14349, NULL, 'n. [医]矮小, 侏儒症,[植]矮态', '/\'neinizəm | \'neɪnɪzəm/', 'nanism', 6);
INSERT INTO `words` VALUES (14350, 'an afternoon nap', 'n. (白天)小睡, 打盹, 细毛, 孤注一掷', '/næp/', 'nap', 6);
INSERT INTO `words` VALUES (14351, 'He went to the gym every day, driven purely by narcissism.', 'n. 自我陶醉, 自恋', '/nɑ:\'sisizəm | \'nɑːsɪsɪz(ə)m; nɑː\'sɪs- | \'nɑrsɪ\'sɪzəm/', 'narcissism', 6);
INSERT INTO `words` VALUES (14352, 'Sister Hibiscus says things as if she is living in a romance novel. Many call her a narcissist, but she prefers the term \"self- confidence. \"\"', 'n. 自恋狂， 自恋者', '/nɑːr\'sɪsɪst | nɑr\'sɪsɪst/', 'narcissist', 6);
INSERT INTO `words` VALUES (14353, 'the narcotics trade', 'n. 麻醉药, 致幻毒品, 镇静剂', '/nɑ:\'kɔtik | nɑː\'kɒtɪk | nɑr\'kɑtɪk/', 'narcotic', 6);
INSERT INTO `words` VALUES (14354, NULL, 'adj. 脾气坏的, 易生气的', '/\'nɑ:ki/', 'narky', 6);
INSERT INTO `words` VALUES (14355, 'The novel contains more narrative than dialogue.', 'adj. 叙述性的', '/\'nærətɪv/', 'narrative', 6);
INSERT INTO `words` VALUES (14356, 'The stairs were very narrow.', 'adj. 狭窄的；狭隘的; v. 变窄', '/\'nærou | \'næro/', 'narrow', 6);
INSERT INTO `words` VALUES (14357, 'the nasal passage', 'adj. 鼻的, 鼻音的, 护鼻的', '/\'neizəl | \'neɪz(ə)l | \'nezl/', 'nasal', 6);
INSERT INTO `words` VALUES (14358, 'the country’s nascent democracy', 'adj. 初生的', '/\'næsənt, \'nei- | \'næs(ə)nt; \'neɪ- | \'næsnt/', 'nascent', 6);
INSERT INTO `words` VALUES (14359, 'Green turtles return to their natal island to breed.', 'adj. 出生的， 诞生时的', '/\'neɪtl | \'netl/', 'natal', 6);
INSERT INTO `words` VALUES (14360, 'The broadcast will show the queen, wearing a green outfit, chatting to schoolchildren as she helps them make a collage of a nativity scene.', 'n. 出生, (the Nativity)基督降生', '/nə\'tiviti, nei- | nə\'tɪvɪtɪ | nə\'tɪvəti/', 'nativity', 6);
INSERT INTO `words` VALUES (14361, 'a natty suit', 'adj. 整洁的', '/\'næti | \'nætɪ/', 'natty', 6);
INSERT INTO `words` VALUES (14362, 'These drawings are among his most naturalistic.', 'adj. 自然主义的', '/ˌnætʃrə\'lɪstɪk | ,nætʃrə\'lɪstɪk/', 'naturalistic', 6);
INSERT INTO `words` VALUES (14363, 'All your code is for naught if users can\'t hop online and buy items from their favorite vendor or find out how much the newest abstract watercolor from their local gallery costs.', 'n. 零', '/nɔ:t | nɔːt | nɔt/', 'naught', 6);
INSERT INTO `words` VALUES (14364, 'I was overcome with a feeling of nausea.', 'n. 反胃, 晕船, 恶心, 作呕, 极度的不快', '/\'nɔ:ziə, -siə, -ʃə, -ʒə | ˈnɔ:ziə | \'nɔzɪə/', 'nausea', 6);
INSERT INTO `words` VALUES (14365, 'The smell of frying nauseated her.', 'v. 作呕, 产生恶感, 厌恶', '/\'nɔ:zieit, -si-, -ʃi- | \'nɔːsɪeɪt; -z- | \'nɔzɪet/', 'nauseate', 6);
INSERT INTO `words` VALUES (14366, 'nautical equipment', 'adj. 船员的, 船舶的, 海上的, 航海的, 海军的', '/\'nɔ:tikəl | \'nɔːtɪk(ə)l | \'nɔtɪkl/', 'nautical', 6);
INSERT INTO `words` VALUES (14367, NULL, 'n. 中央广场, 车轮的中心部', '/neiv | neɪv | nev/', 'nave', 6);
INSERT INTO `words` VALUES (14368, '...a girl with a ring in her navel.', 'n. [解]脐, 肚脐, 中央, 中心点', '/\'neivəl | \'neɪv(ə)l | \'nevl/', 'navel', 6);
INSERT INTO `words` VALUES (14369, 'The river is too dangerous to navigate.', 'v. 驾驶； 航行； 使通过', '/\'nævɪgeɪt | \'nævə\'get/', 'navigate', 6);
INSERT INTO `words` VALUES (14370, NULL, 'v. 拒绝， 否认， 反对', '/\'neisei | \'neɪseɪ/', 'naysay', 6);
INSERT INTO `words` VALUES (14371, 'Give up being a naysayer.', 'n. 怀疑者， 否定者', '/\'neɪseɪər/', 'naysayer', 6);
INSERT INTO `words` VALUES (14372, 'As the nebula collapsed because of its gravity, it spun faster and flattened into a disk.', 'n. 星云, 云翳', '/\'nebjulə | \'nebjʊlə | \'nɛbjələ/', 'nebula', 6);
INSERT INTO `words` VALUES (14373, '‘Normality’ is a rather nebulous concept.', 'adj. 星云的, 云雾状的, 模糊的, 朦胧的', '/\'nebjuləs | \'nebjʊləs | \'nɛbjələs/', 'nebulous', 6);
INSERT INTO `words` VALUES (14374, 'True individual freedom cannot exist without economic security and independence, and necessitous men are not free men.', 'adj. 贫困的', '/ni\'sesitəs, nə- | nɪ\'sesɪtəs | nə\'sɛsɪtəs/', 'necessitous', 6);
INSERT INTO `words` VALUES (14375, 'With his deadly sickle and necromancy, Dutin becomes one of the most dangerous warriors in Ruminater now.', 'n. 巫术', '/\'nekrəumænsi | \'nɛkromænsi/', 'necromancy', 6);
INSERT INTO `words` VALUES (14376, 'the extensive necropolis which served the Etruscan city of Caere', 'n. 大墓地, 古代的埋葬地', '/ne\'krɔpəlis | ne\'krɒpəlɪs | nə\'krɑpəlɪs/', 'necropolis', 6);
INSERT INTO `words` VALUES (14377, NULL, 'n. [希神] 神酒, 任何美味的饮料, 花蜜, 甘露', '/\'nektə | \'nɛktɚ/', 'nectar', 6);
INSERT INTO `words` VALUES (14378, 'She carried hypodermic needles and syringes in her bag.', 'n. 针', '/\'ni:dl | \'niːd(ə)l | \'nidl/', 'needle', 6);
INSERT INTO `words` VALUES (14379, 'nefarious activities such as drug trafficking and fraud', 'adj. 邪恶的, 穷凶极恶的', '/ni\'fεəriəs | nɪ\'feərɪəs/', 'nefarious', 6);
INSERT INTO `words` VALUES (14380, 'He warned that to negate the results of elections would only make things worse.', 'v. 否定, 打消', '/ni\'ɡeit, \'neɡeit, \'ni:- | nɪ\'geɪt | nɪˈɡet/', 'negate', 6);
INSERT INTO `words` VALUES (14381, 'Much of what passes for Christianity is a negation of Christ’s teachings.', 'n. 否定, 拒绝', '/ni\'ɡeiʃən | nɪ\'geɪʃ(ə)n | nɪ\'ɡeʃən/', 'negation', 6);
INSERT INTO `words` VALUES (14382, 'negligence in carrying out safety procedures', 'n. 疏忽', '/\'neɡlidʒəns | \'neglɪdʒ(ə)ns | \'nɛɡlɪdʒəns/', 'negligence', 6);
INSERT INTO `words` VALUES (14383, 'Mr Brown was found guilty of negligent driving.', 'adj. 疏忽的， 粗心大意的', '/\'neglɪdʒənt | \'nɛɡlɪdʒənt/', 'negligent', 6);
INSERT INTO `words` VALUES (14384, 'The damage done to his property was negligible.', 'adj. 可以忽略的, 不予重视的', '/\'neɡlidʒəbl | \'neglɪdʒɪb(ə)l | \'nɛɡlɪdʒəbl/', 'negligible', 6);
INSERT INTO `words` VALUES (14385, NULL, 'adv. 无足轻重地， 不值一提地', '/\'neglidʒibli | \'neglɪdʒəbli/', 'negligibly', 6);
INSERT INTO `words` VALUES (14386, 'Part-time barman required. Hours and salary negotiable.', 'adj. 可通过谈判解决的', '/ni\'ɡəuʃiəbl | nɪ\'gəʊʃəb(ə)l; -ʃɪə- | nɪ\'ɡoʃɪəbl/', 'negotiable', 6);
INSERT INTO `words` VALUES (14387, 'His first aim is to get the warring parties back to the negotiating table (= discussing something ).', 'v. 协商， 商定， 议定', '/nɪ\'gouʃieɪt | nɪ\'ɡoʃɪet/', 'negotiate', 6);
INSERT INTO `words` VALUES (14388, 'The horse gave a loud neigh.', 'n. 马嘶声', '/nei | neɪ | ne/', 'neigh', 6);
INSERT INTO `words` VALUES (14389, 'The new mathematics test will become the nemesis of teachers.', 'n. -ses(1)报应；公正的惩罚(2)[希神]报应女神', '/\'nemisis/', 'nemesis', 6);
INSERT INTO `words` VALUES (14390, NULL, 'n. 新学说, 新见解', '/,ni:əu\'dɔksi/', 'neodoxy', 6);
INSERT INTO `words` VALUES (14391, '...neolithic culture.', 'adj. 新石器时代的', '/,ni:əu\'liθik | ˌni:əˈlɪθɪk | ˌniəˈlɪθɪk/', 'neolithic', 6);
INSERT INTO `words` VALUES (14392, 'The newspaper used the neologism \"dinks,\" Double Income No Kids.', 'n. 新语, 创造或使用新语', '/ni:\'ɔlədʒizəm, ni- | nɪ\'ɒlədʒɪz(ə)m | nɪ\'ɑlədʒɪzəm/', 'neologism', 6);
INSERT INTO `words` VALUES (14393, '“Full, unabashed, total irradiation of a neonate,” Dr. Sclafani said, adding, “This poor, defenseless baby.', 'n. (尤指出生不满一个月的)婴儿', '/\'ni:əuneit | \'niːə(ʊ)neɪt | \'nionet/', 'neonate', 6);
INSERT INTO `words` VALUES (14394, '...the self-proclaimed political neophyte Ross Perot.', 'n. 新入教者, 新信徒', '/\'ni:əufait | \'niːə(ʊ)faɪt | \'niəfaɪt/', 'neophyte', 6);
INSERT INTO `words` VALUES (14395, NULL, 'n. (据传说古希腊人用的)忘忧药, 解忧烦之物', '/ne\'penθɪ | nɪ\'pɛnθi/', 'nepenthe', 6);
INSERT INTO `words` VALUES (14396, 'I have had nephritis, but that was five years ago.', 'n. 肾炎', '/ni\'fraitis | nɪ\'fraɪtɪs | nɛ\'fraɪtɪs/', 'nephritis', 6);
INSERT INTO `words` VALUES (14397, 'allegations of nepotism and corruption', 'n. 偏袒, 起用亲戚, 裙带关系', '/\'nepətizəm | \'nepətɪz(ə)m | \'nɛpə\'tɪzəm/', 'nepotism', 6);
INSERT INTO `words` VALUES (14398, 'She finally found the nerve to tell him she wanted a divorce.', 'v. 给予力量; n. 勇气', '/nɜːrv | nɝv/', 'nerve', 6);
INSERT INTO `words` VALUES (14399, 'The key fell from her suddenly nerveless fingers.', 'adj. 无力的, 松懈的', '/\'nə:vlis | \'nɜːvlɪs | \'nɝvləs/', 'nerveless', 6);
INSERT INTO `words` VALUES (14400, 'I wish you’d stop looking at me like that. You’re making me nervous.', 'adj. 神经紧张的, 不安的, 强健有力的', '/\'nə:vəs | \'nɜːvəs | \'nɝvəs/', 'nervous', 6);
INSERT INTO `words` VALUES (14401, 'She was all tired and nervy.', 'adj. 肌肉发达的, 有勇气的, 冷静的', '/\'nə:vi | \'nɜːvɪ | \'nɝvi/', 'nervy', 6);
INSERT INTO `words` VALUES (14402, NULL, 'adj. 无学的, 无知的', '/\'nesiənt | \'nesɪənt/', 'nescient', 6);
INSERT INTO `words` VALUES (14403, 'Sarah lay there peacefully, the child nestling by her side.', 'v. 舒适地坐定, 偎依', '/\'nesl | \'nes(ə)l | \'nɛsl/', 'nestle', 6);
INSERT INTO `words` VALUES (14404, NULL, 'n. 未离巢的雏鸟, 婴儿', '/\'nestliŋ | \'nes(t)lɪŋ | \'nɛstlɪŋ/', 'nestling', 6);
