INSERT INTO `words` VALUES (14406, 'Grandson Chu saw shelf\'s nethermost film, the wry smile wrote to shake to shake head and wished this store owner also enough bold.', 'adj. 最底下的, 最下面的', '/\'neðəməust | \'neðəməʊst/', 'nethermost', 6);
INSERT INTO `words` VALUES (14407, 'The nettles stung their legs.', 'n. 荨麻', '/\'net(ə)l | \'nɛtl/', 'nettle', 6);
