INSERT INTO `words` VALUES (14427, 'a recurring nightmare', 'n. 梦魇, 恶梦, 可怕的事物', '/\'naitmεə | \'naɪtmeə | \'naɪt\'mɛr/', 'nightmare', 6);
INSERT INTO `words` VALUES (14428, 'The negation of the infinite leads straight to nihilism.', 'n. [哲]虚无主义, 极端怀疑论', '/\'naiilizəm, \'ni:- | \'naɪ(h)ɪlɪz(ə)m | \'naɪɪlɪzəm/', 'nihilism', 6);
