INSERT INTO `words` VALUES (14446, 'the nominal head of the rebellion', 'adj. 名义上的, 有名无实的, 名字的, [语]名词性的', '/\'nɔminəl | \'nɒmɪn(ə)l | \'nɑmɪnl/', 'nominal', 6);
