INSERT INTO `words` VALUES (14468, 'This kind of type is characteristic of nonskid stops on wet roads.', 'adj. 不滑的', '/\'nɔn\'skid | \'nɒn\'skɪd | nɑn\'skɪd/', 'nonskid', 6);
INSERT INTO `words` VALUES (14469, 'I ever and Hao brother propose want help he cover mathematics and nature, butted Hao brother very fierce nonsuit, he say behave want dinkum, not can make breach oneself\'s conscience de matter.', 'n. 诉讼驳回', '/nɒn\'s(j)uːt | ,nɔn\'sju:t, \'nɔn\'sju:t/', 'nonsuit', 6);
INSERT INTO `words` VALUES (14470, 'This nonthreatening initial contact with the patient allows the physician to determine whether the patient has a regular or irregular rhythm.', 'adj. 不构成威胁的', '/nɑːn\'θretnɪŋ/', 'nonthreatening', 6);
