INSERT INTO `words` VALUES (14479, 'He might be influenced by nostalgia for the surroundings of his happy youth.', 'n. 思家病, 乡愁, 向往过去, 怀旧之情', '/nɔ\'stældʒiə, nə- | nɒ\'stældʒə | nə\'stældʒə/', 'nostalgia', 6);
INSERT INTO `words` VALUES (14480, '...yesterday\'s failed socialist nostrums.', 'n. 秘方', '/\'nɔstrəm | \'nɒstrəm | \'nɑstrəm/', 'nostrum', 6);
INSERT INTO `words` VALUES (14481, 'Since innovation throws open, the course of Urbanization develops rapidly, the visage of city changes with each passing day, demotic standard of living is improved notability.', 'n. 显要人物', '/,nəutə\'biləti | nəʊtə\'bɪlɪtɪ | ,notə\'bɪləti/', 'notability', 6);
