INSERT INTO `words` VALUES (14485, NULL, 'adj. 有凹口的, 有锯齿状的', '/nɔtʃt/', 'notched', 6);
INSERT INTO `words` VALUES (14486, 'The skipper notified the coastguard of the tragedy.', 'v. 通报', '/\'nəutifai | \'nəʊtɪfaɪ | \'notə\'fai/', 'notify', 6);
