INSERT INTO `words` VALUES (14488, 'a notorious computer hacker', 'adj. 声名狼籍的', '/nəu\'tɔ:riəs | nə(ʊ)\'tɔːrɪəs | no\'tɔrɪəs/', 'notorious', 6);
INSERT INTO `words` VALUES (14489, NULL, 'adv. 臭名昭著地', '/nou\'tɔːriəsli | noˈtɔːriəsli/', 'notoriously', 6);
INSERT INTO `words` VALUES (14490, 'Many toys have no attraction beyond their novelty value.', 'n. 新颖, 新奇, 新鲜, 新奇的事物', '/\'nɔvəlti | \'nɒv(ə)ltɪ | \'nɑvlti/', 'novelty', 6);
INSERT INTO `words` VALUES (14491, 'The computer course is ideal for novices.', 'n. 新手, 初学者', '/\'nɔvis | \'nɒvɪs | \'nɑvɪs/', 'novice', 6);
