INSERT INTO `words` VALUES (14495, 'They aim their advice squarely at nubile girls who have falsely equated romantic love with happiness.', 'adj. 适婚的', '/\'nju:bail, -bil | \'njuːbaɪl | \'njʊbɪl/', 'nubile', 6);
