INSERT INTO `words` VALUES (14497, 'I did some work as a nude model when I was in college.', 'adj. 裸体的, 裸的, 与生俱有的, 无装饰的', '/nju:d | njuːd | nud/', 'nude', 6);
INSERT INTO `words` VALUES (14498, 'She slipped her arm under his and gave him a nudge.', 'n. 用肘轻推, 轻推为引起注意', '/nʌdʒ/', 'nudge', 6);
