INSERT INTO `words` VALUES (14504, 'My fingers were so numb I could hardly write.', 'adj. 麻木的', '/nʌm/', 'numb', 6);
INSERT INTO `words` VALUES (14505, 'Still, Professor Carlson does concede there are two significant aspects about 11/11/11 that can be construed as lucky even by people like him who don\'t believe in numerology.', 'n. (根据出生日期等数字来解释人的性格或占卜祸福的)数字命理学', '/,nju:mə\'rɔlədʒi | ,njuːmə\'rɒlədʒɪ | ,numə\'rɑlədʒi/', 'numerology', 6);
INSERT INTO `words` VALUES (14506, 'Numerous attempts have been made to hide the truth.', 'adj. 许多的， 很多的', '/\'nuːmərəs | \'numərəs/', 'numerous', 6);
INSERT INTO `words` VALUES (14507, 'The account of spiritual struggle that follows has a humbling and numinous power.', 'adj. 精神上的, 超自然的', '/\'nju:minəs | \'njuːmɪnəs | \'nʊmɪnəs/', 'numinous', 6);
INSERT INTO `words` VALUES (14508, 'Combining knowledge of materials science with extensive numismatic experience, they strive to the fullest extent possible to return your coin to its original appearance.', 'adj. 钱币的, 奖章的, 钱币学的', '/,njuːmɪz\'mætɪk | ,numɪz\'mætɪks/', 'numismatic', 6);
INSERT INTO `words` VALUES (14509, 'His grandfather is a numismatist.', 'n. 钱币奖章收藏家', '/nju:\'mizmətist | njuː\'mɪzmətɪst | nu\'mɪzmətɪst/', 'numismatist', 6);
INSERT INTO `words` VALUES (14510, 'When the emergency situation is over and if the testator is able to make a will in writing or in the form of a sound-recording, the nuncupative will he has made shall be invalidated.', 'adj. 口述的', '/\'nʌŋkjʊ,pətɪv | nʌŋ\'kjʊpətɪv/', 'nuncupative', 6);
INSERT INTO `words` VALUES (14511, 'Unsure whether I have been understood, I put in a brisk spurt to the nunnery.', 'n. 女修道院, 尼姑庵', '/\'nʌnəri | \'nʌn(ə)rɪ/', 'nunnery', 6);
INSERT INTO `words` VALUES (14512, 'She became immersed in planning her nuptials.', 'n. 婚礼', '/\'nʌpʃəl | \'nʌpʃ(ə)l | \'nʌpʃl/', 'nuptial', 6);
INSERT INTO `words` VALUES (14513, 'plants nurtured in the greenhouse', 'v. 养育，教养; n. 养育； 营养物', '/\'nɜːrtʃər | \'nɝtʃɚ/', 'nurture', 6);
INSERT INTO `words` VALUES (14514, 'The plant absorbs nutrients from the soil.', 'n. 营养品， 滋养物', '/\'nuːtriənt | \'nutrɪənt/', 'nutrient', 6);
INSERT INTO `words` VALUES (14515, 'Cooking vegetables for too long lessens their nutritional value.', 'adj. 营养的， 滋养的', '/nu\'trɪʃnl | njʊ\'trɪʃənl/', 'nutritional', 6);
INSERT INTO `words` VALUES (14516, 'Wholemeal bread is more nutritious than white bread.', 'adj. 有营养的， 滋养的', '/nu\'trɪʃəs | nʊ\'trɪʃəs/', 'nutritious', 6);
INSERT INTO `words` VALUES (14517, 'Evan leaned forward and began nuzzling her shoulder.', 'v. 将鼻插入, 用鼻掘, 用鼻爱抚', '/\'nʌzl | \'nʌz(ə)l/', 'nuzzle', 6);
INSERT INTO `words` VALUES (14518, 'Is nyctalopia which kinds of vitamin airframe lacks ?', 'n. 夜盲症', '/,niktə\'ləupiə | ,nɪktə\'ləʊpɪə | ,nɪktə\'lopɪə/', 'nyctalopia', 6);
INSERT INTO `words` VALUES (14519, NULL, 'n. [希神][罗神]居于山林水泽的仙女, 美丽的少女', '/nimf | nɪmf/', 'nymph', 6);
INSERT INTO `words` VALUES (14520, 'The bodyguards, as usual, were brave but oafish.', 'adj. 痴呆的, 畸形的', '/\'əufiʃ | \'ofɪʃ/', 'oafish', 6);
INSERT INTO `words` VALUES (14521, 'an oak door', 'n. [植]橡树, 橡木', '/əuk | əʊk | ok/', 'oak', 6);
INSERT INTO `words` VALUES (14522, 'Cold worlds shake from the oar.', 'n. 桨, 橹', '/ɔ:, əu | ɔː | ɔr/', 'oar', 6);
INSERT INTO `words` VALUES (14523, 'The immaculately tended gardens are an oasis in the midst of Cairo\'s urban sprawl.', 'n. (沙漠中)绿洲,舒适的地方', '/əu\'eisis, \'əuəsis | əʊ\'eɪsɪs | o\'esɪs/', 'oasis', 6);
INSERT INTO `words` VALUES (14524, 'The president took the oath of office (= made the official public promises that every president makes when starting their job ) .', 'n. 誓言, 宣誓, 诅咒', '/əuθ | əʊθ | oθ/', 'oath', 6);
INSERT INTO `words` VALUES (14525, 'Soon his right arm reached around to the other side of the child and he added a running obbligato.', 'n. 伴奏', '/,ɔbli\'ɡɑ:təu | ,ɒblɪ\'gɑːtəʊ | ,ɑblɪ\'ɡɑto/', 'obbligato', 6);
INSERT INTO `words` VALUES (14526, 'They argued, but he remained obdurate.', 'adj. 冷酷无情的, 顽固的, 执拗的', '/\'ɔbdjurət | \'ɒbdjʊrət | \'ɑbdərət/', 'obdurate', 6);
INSERT INTO `words` VALUES (14527, 'an obedient child', 'adj. 服从的, 孝顺的', '/əu\'bi:diənt | ə\'biːdɪənt | oˈbidiənt/', 'obedient', 6);
INSERT INTO `words` VALUES (14528, 'While he was still young and strong all paid obeisance to him.', 'n. 敬礼, 鞠躬, 顿首, 服从', '/əu\'beisəns, -\'bi:- | ə(ʊ)\'beɪs(ə)ns | o\'bisns/', 'obeisance', 6);
INSERT INTO `words` VALUES (14529, 'Obese people tend to have higher blood pressure than lean people.', 'adj. 肥胖的, 肥大的', '/əu\'bi:s | ə(ʊ)\'biːs | o\'bis/', 'obese', 6);
INSERT INTO `words` VALUES (14530, 'So, what of the future of obesity in America?', 'n. 肥胖, 肥大', '/əu\'bi:səti, -\'be- | ə(ʊ)\'biːsɪtɪ | o\'bisəti/', 'obesity', 6);
INSERT INTO `words` VALUES (14531, 'They are obfuscating the issue, as only insurance companies can.', 'v. 使模糊, 使迷乱', '/ɔb\'fʌskeit, \'ɔbfʌskeit | \'ɒbfʌskeɪt | \'ɑbfʌsket/', 'obfuscate', 6);
INSERT INTO `words` VALUES (14532, 'Her objection was that he was too young.', 'n. 异议, 缺陷, 妨碍, 拒绝之理由', '/əb\'dʒekʃən, ɔb- | əb\'dʒekʃ(ə)n | əb\'dʒɛkʃən/', 'objection', 6);
INSERT INTO `words` VALUES (14533, 'objectionable odours', 'adj. 引起反对的, 讨厌的', '/əb\'dʒekʃənəbl, ɔb- | əb\'dʒekʃ(ə)nəb(ə)l/', 'objectionable', 6);
INSERT INTO `words` VALUES (14534, 'Scientists need to be objective when doing research.', 'adj. 客观的; n. 目标', '/əb\'dʒektɪv | əb\'dʒɛktɪv/', 'objective', 6);
INSERT INTO `words` VALUES (14535, NULL, 'v. 申斥, 非难', '/\'ɔbdʒəɡeit, əb\'dʒə:ɡeit | \'ɒbdʒəgeɪt | əb\'dʒɝɡet/', 'objurgate', 6);
INSERT INTO `words` VALUES (14536, 'Then the king Nebuchadnezzar fell upon his face, and worshipped Daniel, and commanded that they should offer an oblation and sweet odours unto him.', 'n. 祭品', '/ɔb\'leiʃən, əu- | ə\'bleɪʃ(ə)n | ob\'leʃən/', 'oblation', 6);
INSERT INTO `words` VALUES (14537, 'I felt obligated to let him read the letter.', 'adj. 有义务的， 有责任的', '/\'ɑːblɪgeɪtɪd | \'ɑblɪɡetɪd/', 'obligated', 6);
INSERT INTO `words` VALUES (14538, 'Employers have an obligation to treat all employees equally.', 'n. 义务, 职责, 债务', '/,ɔbli\'ɡeiʃən | ɒblɪ\'geɪʃ(ə)n | ,ɑblɪ\'ɡeʃən/', 'obligation', 6);
INSERT INTO `words` VALUES (14539, 'She offered him the obligatory cup of tea.', 'adj. 义不容辞的, 必须的', '/\'ɔbliɡətəri, ɔb\'liɡətɔ:ri, -təri | ə\'blɪgət(ə)rɪ | ə\'blɪɡətɔri/', 'obligatory', 6);
INSERT INTO `words` VALUES (14540, 'The storm got worse and worse. Finally, I was obliged to abandon the car and continue on foot.', 'v. 强迫， 强制； 施恩惠于…', '/ə\'blaɪdʒ/', 'oblige', 6);
INSERT INTO `words` VALUES (14541, 'The shop assistant was very obliging.', 'adj. 亲切的, 有礼貌的, 愿意帮人忙的', '/ə\'blaidʒiŋ | ə\'blaɪdʒɪŋ/', 'obliging', 6);
INSERT INTO `words` VALUES (14542, 'an oblique reference to his drinking problem', 'adj. 倾斜的, 间接的, 不坦率的, 无诚意的', '/ə\'bli:k, ə\'blaik | ə\'bliːk | ə\'blik/', 'oblique', 6);
INSERT INTO `words` VALUES (14543, NULL, 'n. 斜度； 倾斜', '/ə\'bliːknəs/', 'obliqueness', 6);
INSERT INTO `words` VALUES (14544, 'There was time enough to obliterate memories of how things once were for him.', 'v. 涂去, 删除, 使湮没', '/ə\'blitəreit | ə\'blɪtəreɪt | ə\'blɪtə\'ret/', 'obliterate', 6);
INSERT INTO `words` VALUES (14545, 'The loser’s name has been consigned to oblivion (= completely forgotten ).', 'n. 遗忘, 湮没, 赦免', '/ə\'bliviən, ɔ- | ə\'blɪvɪən/', 'oblivion', 6);
INSERT INTO `words` VALUES (14546, NULL, 'adj. 遗忘的, 忘却的, 健忘的', '/ə\'bliviəs, ɔ- | ə\'blɪvɪəs/', 'oblivious', 6);
INSERT INTO `words` VALUES (14547, 'Destroy the people\'s faith in their natural leaders by holding the latter up to contempt, ridicule and obloquy.', 'n. 漫骂, 毁谤', '/\'ɒbləkwɪ | \'ɑbləkwi/', 'obloquy', 6);
INSERT INTO `words` VALUES (14548, 'She’s really obnoxious.', 'adj. 不愉快的, 讨厌的', '/ɔb\'nɔkʃəs | əb\'nɒkʃəs | əb\'nɑkʃəs/', 'obnoxious', 6);
INSERT INTO `words` VALUES (14549, 'Bradford made an obscene gesture.', 'adj. 淫秽的, 猥亵的', '/əb\'si:n | əb\'siːn | əb\'sin/', 'obscene', 6);
INSERT INTO `words` VALUES (14550, 'obscure legal phrases', 'adj. 暗的, 朦胧的, 模糊的, 晦涩的', '/əb\'skjʊə | əb\'skjʊr/', 'obscure', 6);
INSERT INTO `words` VALUES (14551, 'obscurities in the text', 'n. 阴暗, 朦胧, 偏僻, 含糊, 隐匿, 晦涩, 身份低微', '/əb\'skjuriti | əb\'skjʊərɪtɪ | əb\'skjʊrəti/', 'obscurity', 6);
INSERT INTO `words` VALUES (14552, 'Hundreds paid their last respects at his obsequies.', 'n. 葬礼', '/\'ɒbsɪkwɪz | \'ɑbsəkwɪz/', 'obsequies', 6);
INSERT INTO `words` VALUES (14553, 'an obsequious smile', 'adj. 谄媚的, 奉承的, 拍马屁的', '/əb\'si:kwiəs, ɔb- | əb\'siːkwɪəs | əb\'sikwɪəs/', 'obsequious', 6);
INSERT INTO `words` VALUES (14554, 'He was free from all sycophancy or obsequiousness in the face of the reactionary ruling class.', 'n. 谄媚', '/əb\'si:kwiəsnis | əb\'siːkwiəsnəs/', 'obsequiousness', 6);
INSERT INTO `words` VALUES (14555, 'the Memorial Day observance', 'n. 遵守, 惯例, 仪式, 庆祝', '/əb\'zə:vəns | əb\'zɜːv(ə)ns | əb\'zɝvəns/', 'observance', 6);
INSERT INTO `words` VALUES (14556, 'a quiet and observant person', 'adj. 密切注意的， 警惕的； 遵守的， 遵从的)； 敏锐的(quick to perceive or apprehend； alert)', '/əb\'zɜːrvənt | əb\'zɝvənt/', 'observant', 6);
INSERT INTO `words` VALUES (14557, 'A string of scandals is obsessing America.', 'v. 迷住； 使…困扰， 使…烦扰', '/əb\'ses | əb\'sɛs/', 'obsess', 6);
INSERT INTO `words` VALUES (14558, 'He was obsessed with gangster movies.', 'adj. 着迷的， 沉迷的', '/əb\'sest/', 'obsessed', 6);
INSERT INTO `words` VALUES (14559, 'She would try to forget her obsession with Christopher.', 'n. 迷住, 困扰', '/əb\'seʃən, ɔb- | əb\'seʃ(ə)n | əb\'sɛʃ(ə)n/', 'obsession', 6);
INSERT INTO `words` VALUES (14560, 'Williams is obsessive about motor racing.', 'adj. 强迫性的， 急迫的； 使人着迷的', '/əb\'sesɪv | əb\'sesiv, ɔb-/', 'obsessive', 6);
INSERT INTO `words` VALUES (14561, '...outmoded, obsolescent equipment.', 'adj. 荒废的', '/,ɔbsəu\'lesənt | ,ɒbsə\'les(ə)nt | ,ɑbsə\'lɛsnt/', 'obsolescent', 6);
INSERT INTO `words` VALUES (14562, 'obsolete weapons', 'adj. 荒废的, 陈旧的', '/\'ɔbsəli:t, ,ɔbsə\'li:t | \'ɒbsəliːt | ɑbsəˌlit/', 'obsolete', 6);
INSERT INTO `words` VALUES (14563, 'The tax puts obstacles in the way of companies trying to develop trade overseas.', 'n. 障碍, 妨害物', '/\'ɔbstəkl | \'ɒbstək(ə)l | \'ɑbstəkl/', 'obstacle', 6);
INSERT INTO `words` VALUES (14564, '...the American College of Obstetrics and Gynecology.', 'n. 产科学', '/əb\'stetriks, ɔb- | əb\'stetrɪks | əb\'stɛtrɪks/', 'obstetrics', 6);
INSERT INTO `words` VALUES (14565, NULL, 'n. 固执， 倔强， 顽固', '/\'ɑːbstɪnəsi | \'ɑbstənəsi/', 'obstinacy', 6);
INSERT INTO `words` VALUES (14566, 'He was the most obstinate man I’ve ever met.', 'adj. 倔强的, 顽固的', '/\'ɔbstinit, -nət | \'ɒbstɪnət | \'ɑbstɪnət/', 'obstinate', 6);
INSERT INTO `words` VALUES (14567, NULL, 'n. 固执， 顽固', '/\'ɑːbstɪnətnəs/', 'obstinateness', 6);
INSERT INTO `words` VALUES (14568, 'You know I have no intention of being awkward and obstreperous.', 'adj. 喧嚣的, 任性的', '/əb\'strepərəs | əbˈstrɛpərəs | əb\'strɛpərəs/', 'obstreperous', 6);
INSERT INTO `words` VALUES (14569, 'A small aircraft was obstructing the runway.', 'v. 阻隔, 阻塞, 遮断(道路、通道等)', '/əb\'strʌkt, ɔb- | əb\'strʌkt/', 'obstruct', 6);
INSERT INTO `words` VALUES (14570, 'an operation to remove an obstruction from her throat', 'n. 阻塞, 妨碍, 障碍物', '/əb\'strʌkʃən, ɔb- | əb\'strʌkʃ(ə)n/', 'obstruction', 6);
INSERT INTO `words` VALUES (14571, 'The form is obtainable at your local post office.', 'adj. 能得到的', '/əb\'teinəbl, ɔb- | əb\'teɪnəbl/', 'obtainable', 6);
INSERT INTO `words` VALUES (14572, 'I should not obtrude my affairs so much on the notice of my readers if very particular inquiries had not been made by my townsmen concerning my mode of life.', 'v. 强迫, 冲出', '/əb\'tru:d, ɔb- | əb\'truːd/', 'obtrude', 6);
INSERT INTO `words` VALUES (14573, 'obtrusive TV antennas', 'adj. 强迫人的, 突出的, 鲁莽的, 令人厌恶的, 过分炫耀的', '/əb\'tru:siv, ɔb- | əb\'truːsɪv | əb\'trusɪv/', 'obtrusive', 6);
INSERT INTO `words` VALUES (14574, NULL, 'adj. 使缓和的', '/ɒb\'tʌndənt | ɔb\'tʌndənt/', 'obtundent', 6);
INSERT INTO `words` VALUES (14575, '‘But why?’ said Charles, being deliberately obtuse.', 'adj. 钝的, 圆头的, 愚蠢的, 迟钝的', '/əb\'tju:s, ɔb- | əbˈtju:s | əbˈtus/', 'obtuse', 6);
INSERT INTO `words` VALUES (14576, 'On the obverse, the traditional goddess of victory, holding a palm in her left hand and a winner\'s crown in her right.', 'adj. 正面的', '/\'ɔbvə:s, ɔb\'və:s, əb- | \'ɒbvɜːs | \'ɑbvɝs/', 'obverse', 6);
INSERT INTO `words` VALUES (14577, 'The new treatment obviates the need for surgery.', 'v. 消除, 排除(危险、障碍等), 回避, 预防, 避免', '/\'ɔbvieit | \'ɒbvɪeɪt | \'ɑbvɪet/', 'obviate', 6);
INSERT INTO `words` VALUES (14578, 'The obvious way of reducing pollution is to use cars less.', 'adj. 明显的， 显而易见的', '/\'ɑːbviəs | \'ɑbvɪəs/', 'obvious', 6);
INSERT INTO `words` VALUES (14579, 'He made occasional visits to London.', 'adj. 偶尔的； 特殊场合的； 不经常的', '/ə\'keɪʒənl | ə\'keʒənl/', 'occasional', 6);
INSERT INTO `words` VALUES (14580, NULL, 'n. 欧美人, 西方人', '/,ɔksi\'dentəl | ɒksɪ\'dent(ə)l | ,ɑksə\'dɛntl/', 'occidental', 6);
INSERT INTO `words` VALUES (14581, NULL, 'v. 使闭塞', '/ə\'kluːd | ə\'klud/', 'occlude', 6);
INSERT INTO `words` VALUES (14582, 'occult practices', 'adj. 神秘的, 玄妙的, 不可思议的, 超自然的', '/\'ɔkʌlt, ɔ\'kʌlt, ə- | ɒ\'kʌlt; \'ɒkʌlt | ə\'kʌlt/', 'occult', 6);
INSERT INTO `words` VALUES (14583, 'Please state your name, address and occupation.', 'n. 工作， 职业； 占有， 占领', '/ˌɑːkju\'peɪʃn | ,ɑkju\'peʃən/', 'occupation', 6);
INSERT INTO `words` VALUES (14584, 'Complaints seemed to be an everyday occurrence.', 'n. 发生, 出现, 事件, 发生的事情', '/ə\'kə:rəns, -\'kʌ- | ə\'kʌr(ə)ns | ə\'kʌrəns/', 'occurrence', 6);
INSERT INTO `words` VALUES (14585, 'Marius on that barricade after the octogenarian was the vision of the young revolution after the apparition of the old.', 'adj. 八十岁的, 八十多岁的', '/,ɔktədʒi\'nεəriən | ,ɒktə(ʊ)dʒɪ\'neərɪən | \'ɑktədʒə\'nɛrɪən/', 'octogenarian', 6);
INSERT INTO `words` VALUES (14586, 'ocular muscles', 'adj. 眼睛的, 视觉的', '/\'ɔkjulə | \'ɒkjʊlə | \'ɑkjəlɚ/', 'ocular', 6);
INSERT INTO `words` VALUES (14587, 'The father stood there with his son. Before the latter was the great oculist in the act of cutting away the last bandage.', 'n. 眼科医生', '/\'ɔkjulist | \'ɒkjʊlɪst | \'ɑkjəlɪst/', 'oculist', 6);
INSERT INTO `words` VALUES (14588, '...Keats\' \"Ode to a Nightingale.\"', 'n. 颂诗, 赋', '/əud | əʊd | od/', 'ode', 6);
INSERT INTO `words` VALUES (14589, 'an odious little man', 'adj. 可憎的, 讨厌的', '/\'əudiəs | \'əʊdɪəs | \'odɪəs/', 'odious', 6);
INSERT INTO `words` VALUES (14590, 'The complainant has been exposed to public odium, scandal, and contempt.', 'n. 憎恶, 讨厌', '/\'əudiəm | \'əʊdɪəm | \'odɪəm/', 'odium', 6);
INSERT INTO `words` VALUES (14591, 'The odometer shows now 140 miles per hour.', 'n. 里程表)', '/ou\'dɑːmɪtər | o\'dɑmətɚ/', 'odometer', 6);
INSERT INTO `words` VALUES (14592, 'You can remove the stench of onions, fish, garlic and other odoriferous foods from your skin by scrubbing briefly with toothpaste.', 'adj. 散发气味的, 臭的', '/,əudə\'rifərəs | ,əʊdə\'rɪf(ə)rəs | ,odə\'rɪfərəs/', 'odoriferous', 6);
INSERT INTO `words` VALUES (14593, 'Install a CO detector to alert you of the presence of the deadly, odorless, colorless gas.', 'adj. 无嗅的， 没有气味的', '/\'əudəlis | \'oudərləs/', 'odorless', 6);
INSERT INTO `words` VALUES (14594, '...cancer of the oesophagus.', 'n. [解]食管', '/i:\'sɔfəɡəs | ɪ\'sɒfəgəs | ɪ\'sɑfəɡəs/', 'oesophagus', 6);
INSERT INTO `words` VALUES (14595, 'The band sounded slightly off-key.', 'adj. 走调的， 不和谐的', '/ˌɔːf\'kiː | \'ɔfki/', 'off-key', 6);
INSERT INTO `words` VALUES (14596, '...all the blood and offal the butchers shove down in the gutters.', 'n. 碎屑, 残渣, 废弃物, 垃圾, (猪、牛、羊等屠宰后的)头, 尾, 下水', '/\'ɔfəl, \'ɔ:- | \'ɒf(ə)l | \'ɔfl/', 'offal', 6);
INSERT INTO `words` VALUES (14597, 'offbeat humour', 'adj. 不规则的， 不平常的', '/ˌɑːf\'biːt | ,ɔf\'bit/', 'offbeat', 6);
INSERT INTO `words` VALUES (14598, 'His remarks deeply offended many Scottish people.', 'v. 得罪， 冒犯', '/ə\'fend | ə\'fɛnd/', 'offend', 6);
INSERT INTO `words` VALUES (14599, 'The Bears are going to have to work on their offense this season.', 'n. 进攻', '/ə\'fens | ə\'fɛns/', 'offense', 6);
INSERT INTO `words` VALUES (14600, 'I found her remarks deeply offensive.', 'adj. 讨厌的, 无礼的, 攻击性的', '/ə\'fensiv | ə\'fensɪv | ə\'fɛnsɪv/', 'offensive', 6);
INSERT INTO `words` VALUES (14601, 'She said you were a bit offhand with her this afternoon.', 'adv. 无准备地， 即席地； 随便地; adj. 无准备的，即席的；随便的', '/ˌɔːf\'hænd | ,ɔf\'hænd/', 'offhand', 6);
INSERT INTO `words` VALUES (14602, 'an officious traffic warden', 'adj. 多管闲事的, 非官方的, 非正式的', '/ə\'fiʃəs | ə\'fɪʃəs/', 'officious', 6);
INSERT INTO `words` VALUES (14603, NULL, 'adj. 冷漠的', '/\'ɔfiʃ, \'ɔ:- | \'ɒfɪʃ | \'ɔfɪʃ/', 'offish', 6);
INSERT INTO `words` VALUES (14604, 'Cuts in food prices will be offset by direct payments to farmers.', 'n. 偏移量, 抵销, 弥补, 分支, 平版印刷, 胶印', '/,ɔf\'set, ,ɔ:-, \'ɔfset, \'ɔ:- | \'ɒfset | ,ɔf\'sɛt/', 'offset', 6);
INSERT INTO `words` VALUES (14605, 'a young mother trying to control her offspring', 'n. 〈总称〉后代； 儿女', '/\'ɔːfsprɪŋ | \'ɔfsprɪŋ/', 'offspring', 6);
