INSERT INTO `words` VALUES (14609, 'A range of ointments and creams is available for the treatment of eczema.', 'n. 药膏, 油膏', '/\'ɔintmənt | \'ɒɪntm(ə)nt | \'ɔɪntmənt/', 'ointment', 6);
