INSERT INTO `words` VALUES (14616, '...a cheese omelette.', 'n. 煎蛋卷', '/\'ɑːmlət/', 'omelet', 6);
INSERT INTO `words` VALUES (14617, 'The car won’t start. Do you think it’s an omen?', 'n. 预兆, 征兆', '/\'əumən | \'əʊmən | \'omən/', 'omen', 6);
INSERT INTO `words` VALUES (14618, '‘How long will she be ill?’ he asked. There was an ominous silence.', 'adj. 预兆的, 恶兆的, 不吉利的', '/\'ɔminəs | \'ɒmɪnəs | \'ɑmɪnəs/', 'ominous', 6);
