INSERT INTO `words` VALUES (14620, 'Please don’t omit any details, no matter how trivial they may seem.', 'v. 忽略， 遗漏； 不做， 未能做', '/ə\'mɪt/', 'omit', 6);
INSERT INTO `words` VALUES (14621, NULL, 'adj. <罕>创造一切的, 有无限创造力的', '/ɒm\'nɪfɪsənt/', 'omnificent', 6);
INSERT INTO `words` VALUES (14622, 'Doug lived in the shadow of his seemingly omnipotent father.', 'adj. 全能的, 无所不能的', '/ɔm\'nipətənt | ɒm\'nɪpət(ə)nt | ɑm\'nɪpətənt/', 'omnipotent', 6);
INSERT INTO `words` VALUES (14623, 'The sound of sirens was an omnipresent background noise in New York.', 'adj. 无处不在的', '/ˌɑːmnɪ\'preznt | ,ɑmnɪ\'prɛznt/', 'omnipresent', 6);
INSERT INTO `words` VALUES (14624, 'the book’s omniscient narrator', 'adj. 全知的, 无所不知的', '/ɔm\'nisiənt, -\'niʃənt | ɒm\'nɪsɪənt | ɑm\'nɪsɪənt/', 'omniscient', 6);
INSERT INTO `words` VALUES (14625, 'an omnivorous reader', 'adj. 杂食的, 什么都吃的, 什么都读的, 随手乱拿的', '/ɔm\'nivərəs | ɒm\'nɪv(ə)rəs | ɑm\'nɪvərəs/', 'omnivorous', 6);
