INSERT INTO `words` VALUES (14627, 'their ongoing search for a new director', 'adj. 进行中的； 前进的； 不间断的', '/\'ɑːngouɪŋ | \'ɑnɡoɪŋ/', 'ongoing', 6);
INSERT INTO `words` VALUES (14628, 'A crowd of onlookers had gathered at the scene of the accident.', 'n. 旁观者', '/\'ɔn,lukə, \'ɔ:n- | \'ɒnlʊkə | \'ɑnlʊkɚ/', 'onlooker', 6);
INSERT INTO `words` VALUES (14629, 'Most of the passes have been closed with the onset of winter.', 'n. 开始， 发作； 攻击， 袭击', '/\'ɑːnset | \'ɑnsɛt/', 'onset', 6);
INSERT INTO `words` VALUES (14630, 'plants that will survive the onslaught of winter', 'n. 冲击', '/\'ɔnslɔ:t | \'ɒnslɔːt | \'ɑnslɔt/', 'onslaught', 6);
INSERT INTO `words` VALUES (14631, 'So government publicity is government ontic being, but not public entity or idiographic publicity.', 'adj. 本体的, 实体的', '/\'ɒntɪk | \'ɑntɪk/', 'ontic', 6);
INSERT INTO `words` VALUES (14632, 'Forget taxonomy, ontology, and psychology. Who knows why people do what they do?', 'n. [哲]存在论', '/ɔn\'tɔlədʒi | ɒn\'tɒlədʒɪ | ɑn\'tɑlədʒi/', 'ontology', 6);
INSERT INTO `words` VALUES (14633, 'The onus is on companies and consumers to keep up with anti-virus updates.', 'n. 责任, 负担', '/\'əunəs | \'əʊnəs | \'onəs/', 'onus', 6);
INSERT INTO `words` VALUES (14634, 'It’s not a bad song, but it needs more oomph.', 'n. 性感, 性的魅力, 精神, 精力', '/ɔmf | ʊmf; uːmf | ʊmf/', 'oomph', 6);
INSERT INTO `words` VALUES (14635, 'A cut on his cheek was still oozing blood.', 'n. [地] 软泥', '/u:z | uːz | uz/', 'ooze', 6);
INSERT INTO `words` VALUES (14636, 'Opacity of the eye lens can be induced by deficiency of certain vitamins.', 'n. 不透明性', '/əu\'pæsiti | ə(ʊ)\'pæsɪtɪ | o\'pæsəti/', 'opacity', 6);
INSERT INTO `words` VALUES (14637, 'The color space charts , opalescence and reflected fluorescence spectra curve were plotted.', 'n. 乳白光', '/,əupə\'lesəns | ˌoupə\'lesns/', 'opalescence', 6);
INSERT INTO `words` VALUES (14638, 'an opalescent sky', 'adj. 乳白色的', '/,əupə\'lesənt | əʊpə\'les(ə)nt | \'opə\'lɛsnt/', 'opalescent', 6);
INSERT INTO `words` VALUES (14639, 'You can do that, but I find the syntax kind of opaque.', 'n. 不透明物', '/əu\'peik | ə(ʊ)\'peɪk | o\'pek/', 'opaque', 6);
INSERT INTO `words` VALUES (14640, 'Less than half the rail network was operable.', 'adj. 可操作的， 可使用的； 可手术治疗的', '/\'ɑːpərəbl | \'ɑpərəbl/', 'operable', 6);
INSERT INTO `words` VALUES (14641, 'patients undergoing operative procedures', 'adj. 运转着的, 有效验的, 手术的, 实施的', '/\'ɔpərətiv, -rei- | \'ɒp(ə)rətɪv | \'ɑpərətɪv/', 'operative', 6);
INSERT INTO `words` VALUES (14642, 'The operetta is about a girl named Bettina who is sent to take care of the turkeys of an unlucky farmer by the farmer\'s brother.', 'n. 小歌剧', '/,ɔpə\'retə | ɒpə\'retə | ,ɑpə\'rɛtə/', 'operetta', 6);
INSERT INTO `words` VALUES (14643, 'Among the people to whom Freud introduced cocaine was his colleague Carl Koller, a young doctor working in the department of ophthalmology.', 'n. [医]眼科学', '/,ɔfθæl\'mɔlədʒi, ,ɔp- | ,ɒfθæl\'mɒlədʒɪ; ,ɒpθæl\'mɒlədʒɪ | ,ɑfθæl\'mɑlədʒi/', 'ophthalmology', 6);
INSERT INTO `words` VALUES (14644, 'Our experiments used acetaminophen for the obvious reason that it’s safer and simpler for people to take on a daily basis than an opiate.', 'n. 鸦片剂', '/\'əupiət, -eit, \'əupieit | \'əʊpɪət | \'opɪət/', 'opiate', 6);
INSERT INTO `words` VALUES (14645, '\"A house is a machine for living,\" opined Le Corbusier.', 'v. 想， 以为', '/ou\'paɪn | o\'paɪn/', 'opine', 6);
INSERT INTO `words` VALUES (14646, 'I found him very arrogant and opinionated.', 'adj. 固执己见的, 武断的', '/ə\'pinjəneitid | ə\'pɪnjəneɪtɪd | ə\'pɪnjənetɪd/', 'opinionated', 6);
INSERT INTO `words` VALUES (14647, 'Graf’s opponent in today’s final will be Sukova.', 'adj. 对立的, 对抗的', '/ə\'pəunənt | ə\'pəʊnənt | ə\'ponənt/', 'opponent', 6);
INSERT INTO `words` VALUES (14648, 'an opportune remark', 'adj. (指时间)凑巧的、恰好的, (指行动或事件)及时、适宜的', '/\'ɔpətju:n, ,ɔpə\'tju:n | \'ɒpətjuːn; ,ɒpə\'tjuːn | ˌɔpə\'tun/', 'opportune', 6);
INSERT INTO `words` VALUES (14649, 'Congress is continuing to oppose the President’s health care budget.', 'v. 反对', '/ə\'pouz | ə\'poz/', 'oppose', 6);
INSERT INTO `words` VALUES (14650, 'Most of us are opposed to the death penalty.', 'adj. 反对的', '/ə\'pouzd | ə\'pozd/', 'opposed', 6);
INSERT INTO `words` VALUES (14651, 'I thought the medicine would make him sleep, but it had the opposite effect.', 'adj. 相反的， 对立的', '/\'ɑːpəzət | ˈɑpəzɪt; ˈɑpəsɪt/', 'opposite', 6);
INSERT INTO `words` VALUES (14652, 'native tribes oppressed by the authorities', 'v. 压迫， 压制', '/ə\'pres | ə\'prɛs/', 'oppress', 6);
INSERT INTO `words` VALUES (14653, 'The new laws will be just as oppressive as those they replace.', 'adj. 压制性的, 压迫的, 沉重的, 难以忍受的', '/ə\'presiv | ə\'presɪv | ə\'prɛsɪv/', 'oppressive', 6);
INSERT INTO `words` VALUES (14654, NULL, 'adj. 嘴不干净的, 无礼的, 粗野的, 该骂的, 可耻的', '/ə\'prəubriəs | ə\'prəʊbrɪəs/', 'opprobrious', 6);
INSERT INTO `words` VALUES (14655, 'His political opinions have attracted the opprobrium of the Left.', 'n. 不名誉, 耻辱, 责骂', '/ə\'prəubriəm | ə\'prəʊbrɪəm | ə\'probrɪəm/', 'opprobrium', 6);
INSERT INTO `words` VALUES (14656, 'microscopes and other optical instruments', 'adj. 视觉的； 光学的', '/\'ɑːptɪkl | \'ɑptɪkl/', 'optical', 6);
INSERT INTO `words` VALUES (14657, 'However, if you want optimal shadow quality and performance, there are some additional things to consider.', 'adj. 最佳的， 最理想的', '/\'ɑːptɪməl | \'ɑptəml/', 'optimal', 6);
INSERT INTO `words` VALUES (14658, 'There are grounds for cautious optimism.', 'n. 乐观, 乐观主义', '/\'ɔptimizəm | \'ɒptɪmɪz(ə)m | \'ɑptɪmɪzəm/', 'optimism', 6);
INSERT INTO `words` VALUES (14659, 'He’s an eternal optimist (= he always believes that good things will happen ).', 'n. 乐观主义者', '/\'ɑːptɪmɪst | \'ɑptɪmɪst/', 'optimist', 6);
INSERT INTO `words` VALUES (14660, 'Andrew took a more optimistic view.', 'adj. 乐观的', '/ˌɑːptɪ\'mɪstɪk | ,ɑptɪ\'mɪstɪk/', 'optimistic', 6);
INSERT INTO `words` VALUES (14661, 'If we treat good diet as a cornerstone of optimum nutrition and do regular exercise, we will have much bigger chance to do and enjoy something else.', 'n. 最适宜', '/\'ɔptiməm | \'ɒptɪməm | \'ɑptəməm/', 'optimum', 6);
INSERT INTO `words` VALUES (14662, 'three optional courses', 'adj. 可选择的, 随意的', '/\'ɔpʃənəl | \'ɒpʃ(ə)n(ə)l | \'ɑpʃənl/', 'optional', 6);
INSERT INTO `words` VALUES (14663, 'Money flowed into Rome and supported a growing bureaucracy and opulence, which ultimately led to the Reformation.', 'n. 富裕', '/\'ɔpjuləns | \'ɒpjʊl(ə)ns; \'ɒpjʊləns | \'ɑpjələns/', 'opulence', 6);
INSERT INTO `words` VALUES (14664, 'evening dresses in opulent fabrics', 'adj. 富裕的, 丰富的, 丰饶的, 繁茂的', '/\'ɔpjulənt | \'ɒpjʊl(ə)nt | \'ɑpjələnt/', 'opulent', 6);
INSERT INTO `words` VALUES (14665, NULL, 'n. [宗](古希腊)神谕, 预言, 神谕处, 神使, 哲人, 圣贤美国ORACLE公司, 主要生产数据库产品, 也是主要的网络计算机的倡导者', '/\'ɔrəkl, \'ɔ:- | \'ɒrək(ə)l | \'ɔrəkl/', 'oracle', 6);
INSERT INTO `words` VALUES (14666, 'From voting reform to CCTV, from Trident to the debates, there’s a perfect Orwell quotation, apposite, terse and oracular, just waiting to be plucked out and flourished.', 'adj. 神谕的, 谜似的', '/ɔ\'rækjulə, ɔ:- | ɒ\'rækjʊlə | ə\'rækjəlɚ/', 'oracular', 6);
INSERT INTO `words` VALUES (14667, '...a brief funeral oration.', 'n. 演说, 致辞, 叙述法[语]引语', '/ɔ:\'reiʃən, əu- | ɒ\'reɪʃ(ə)n | ɔ\'reʃən/', 'oration', 6);
INSERT INTO `words` VALUES (14668, NULL, 'n. 宗教剧', '/,ɔrə\'tɔ:riəu, ,ɔ:- | ,ɒrə\'tɔːrɪəʊ | ,ɔrə\'tɔrɪo/', 'oratorio', 6);
INSERT INTO `words` VALUES (14669, 'He displayed determination as well as powerful oratory.', 'n. 讲演术', '/\'ɔrətəri, \'ɔ:rətɔ:ri | \'ɒrət(ə)rɪ | \'ɔrətɔri/', 'oratory', 6);
INSERT INTO `words` VALUES (14670, 'the Earth’s orbital path', 'adj. 轨道的', '/\'ɔːrbɪtl | \'ɔrbɪtl/', 'orbital', 6);
INSERT INTO `words` VALUES (14671, 'a cherry orchard', 'n. 果园', '/\'ɔːrtʃərd | \'ɔrtʃɚd/', 'orchard', 6);
INSERT INTO `words` VALUES (14672, 'There are some relations between musical and orchestic symbols .', 'adj. 舞蹈的', '/ɔ:\'kestik/', 'orchestic', 6);
INSERT INTO `words` VALUES (14673, 'The riots were orchestrated by anti-government forces.', 'v. 给…配管弦乐； 精心安排， 组织', '/\'ɔːrkɪstreɪt | \'ɔrkɪstret/', 'orchestrate', 6);
INSERT INTO `words` VALUES (14674, 'Orchids and orchid bees are a classic example of this relationship.', 'n. [植] 兰, 兰花, 淡紫色', '/\'ɔ:kid | \'ɔːkɪd | \'ɔrkɪd/', 'orchid', 6);
INSERT INTO `words` VALUES (14675, 'Desmond Tutu was ordained in 1960.', 'v. 注定, 规定, 任命(牧师)', '/ɔ:\'dein | ɔː\'deɪn | ɔr\'den/', 'ordain', 6);
INSERT INTO `words` VALUES (14676, 'He was beginning to wonder if he would survive the ordeal.', 'n. 严酷的考验, 痛苦的经验, 折磨', '/ɔ:\'di:l, \'ɔ:di:l | ɔː\'diːəl | ɔr\'dil/', 'ordeal', 6);
