INSERT INTO `words` VALUES (14678, 'It’s just an ordinary camera.', 'adj. 普通的，平常的；拙劣的，质量差的; n. 惯例， 寻常情况', '/\'ɔːrdneri | \'ɔrdnɛri/', 'ordinary', 6);
INSERT INTO `words` VALUES (14679, '...supporters of the ordination of women.', 'n. 排成等级, 分类, 任命, [宗]神职授任, 颁布法令', '/,ɔ:di\'neiʃən | ɔːdɪ\'neɪʃ(ə)n | ,ɔrdn\'eʃən/', 'ordination', 6);
INSERT INTO `words` VALUES (14680, '...a team clearing an area littered with unexploded ordnance.', 'n. 军火', '/\'ɔ:dnəns | \'ɔːdnəns | \'ɔrdnəns/', 'ordnance', 6);
INSERT INTO `words` VALUES (14681, 'iron ore', 'n. 矿石, 含有金属的岩石', '/ɔ: | ɔː | ɔr/', 'ore', 6);
INSERT INTO `words` VALUES (14682, 'It is my orexis, without any aim.', 'n. 欲望, [医]食欲', '/ɔː\'reksɪs | o\'rɛksɪs/', 'orexis', 6);
INSERT INTO `words` VALUES (14683, 'All living organisms have to adapt to changes in environmental conditions.', 'n. 生物体, 有机体', '/\'ɔ:ɡənizəm | \'ɔːg(ə)nɪz(ə)m | \'ɔrɡənɪzəm/', 'organism', 6);
INSERT INTO `words` VALUES (14684, 'The boy court the girl greatly, but the orgulous girl could not make up her mind because she could not validate his promises.', 'adj. 骄傲的, 高傲的', '/\'ɔ:ɡjuləs/', 'orgulous', 6);
INSERT INTO `words` VALUES (14685, 'She looked at the street names, trying to orient herself.', 'n. 东方, 东方诸国(指地中海以东各国)', '/\'ɔ:riənt, \'əu-, \'ɔ:rient | \'ɔːrɪənt; \'ɒr- | \'orɪənt/', 'orient', 6);
INSERT INTO `words` VALUES (14686, 'The party has a broadly socialist orientation.', 'n. 方向, 方位, 定位, 倾向性, 向东方', '/,ɔ:rien\'teiʃən, əu- | ,ɔːrɪən\'teɪʃ(ə)n; ,ɒr- | orɪɛn\'teʃən/', 'orientation', 6);
INSERT INTO `words` VALUES (14687, 'various bodily orifices', 'n. 孔, 口', '/\'ɔrifis, \'ɔ:- | \'ɒrɪfɪs | \'ɔrɪfɪs/', 'orifice', 6);
INSERT INTO `words` VALUES (14688, 'The land was returned to its original owner.', 'adj. 最初的， 最早的； 有创意的， 有创造性的', '/ə\'rɪdʒənl/', 'original', 6);
INSERT INTO `words` VALUES (14689, 'Her earlier work shows a lot of originality.', 'n. 创意, 新奇', '/ə,ridʒə\'næləti | ə,rɪdʒɪ\'nælɪtɪ | ə\'rɪdʒə\'næləti/', 'originality', 6);
INSERT INTO `words` VALUES (14690, 'ornamental gardens', 'adj. 装饰性的', '/ˌɔːrnə\'mentl | ,ɔrnə\'mɛntl/', 'ornamental', 6);
INSERT INTO `words` VALUES (14691, 'an ornate gold mirror', 'adj. 装饰的, 华丽的, (文体)绚丽的', '/ɔ:\'neit | ɔː\'neɪt | ɔr\'net/', 'ornate', 6);
INSERT INTO `words` VALUES (14692, 'an ornery kid', 'adj. 爱争吵的, 卑下的, 一般的', '/\'ɔ:nəri | \'ɔːnərɪ | \'ɔrnəri/', 'ornery', 6);
INSERT INTO `words` VALUES (14693, 'After graduating from Cornell with a degree in ornithology in 1932, he went to work, at $17 a week, for Margaret Bourke-White, developing film and assisting on location.', 'n. 鸟类学, 鸟学论文', '/,ɔ:ni\'θɔlədʒi | ,ɔːnɪ\'θɒlədʒɪ | ,ɔrnɪ\'θɑlədʒi/', 'ornithology', 6);
INSERT INTO `words` VALUES (14694, NULL, 'adj. 响朗的, 洪亮的, 夸大的', '/\'ɔrəutʌnd, \'ɔ:- | \'ɒrə(ʊ)tʌnd; \'ɔː- | \'ɔrotʌnd/', 'orotund', 6);
INSERT INTO `words` VALUES (14695, 'If baby teeth are lost prematurely, the permanent teeth may erupt malpositioned and require orthodontics later on.', 'n. [医]畸齿矫正(术), 正牙学', '/,ɔ:θəu\'dɔntiks | ,ɔːθə\'dɒntɪks | ,ɔrθə\'dɑntɪks/', 'orthodontics', 6);
INSERT INTO `words` VALUES (14696, 'orthodox medical treatments', 'adj. 正统的, 传统的, 习惯的, 保守的, 东正教的', '/\'ɔːθədɒks | \'ɔrθədɑks/', 'orthodox', 6);
INSERT INTO `words` VALUES (14697, 'One consequence of this is that a number of pillars of business orthodoxy are being eroded.', 'adj. 正统的', '/\'ɔ:θədɔksi | \'ɔːθədɒksɪ | \'ɔrθədɑksi/', 'orthodoxy', 6);
INSERT INTO `words` VALUES (14698, 'If this description matches your behavior, you\'re probably a weekend warrior, said Jeffrey Spang, MD, an assistant professor of orthopedics at the University of North Carolina School of Medicine.', 'n. [医]整形外科, 整形术', '/,ɔ:θə\'pi:diks | ,ɔ:θə\'pi:dɪks | ,ɔrθə\'pidɪks/', 'orthopedics', 6);
INSERT INTO `words` VALUES (14699, 'The associated cross-peak amplitude also appears to oscillate.', 'v. 振荡', '/\'ɔsileit | \'ɒsɪleɪt | \'ɑsɪlet/', 'oscillate', 6);
INSERT INTO `words` VALUES (14700, 'the oscillations of a pendulum', 'n. 摆动, 振动', '/,ɔsi\'leiʃən | ,ɒsɪ\'leɪʃn | ,ɑsɪ\'leʃən/', 'oscillation', 6);
INSERT INTO `words` VALUES (14701, 'And so we would osculate (kiss).', 'v. 接吻, 接触', '/\'ɔskjuleit | \'ɒskjʊleɪt/', 'osculate', 6);
INSERT INTO `words` VALUES (14702, 'The concept of band osculation is presented by analyzing surface contact types.', 'n. 接吻, 密切, 接触', '/,ɔskju\'leiʃən/', 'osculation', 6);
INSERT INTO `words` VALUES (14703, '...the processes of diffusion and osmosis.', 'n. 渗透(作用), 渗透性', '/ɔz\'məusis, ɔs- | ɒz\'məʊsɪs/', 'osmosis', 6);
INSERT INTO `words` VALUES (14704, 'The majority of jawbone intra-osseous lipomas are found in adults, and of uncertain origin and etiology but are usually associated with molar teeth.', 'adj. [生化]骨的, 骨质的', '/\'ɔsiəs | \'ɒsɪəs | \'ɑsɪəs/', 'osseous', 6);
INSERT INTO `words` VALUES (14705, '...conventions that threatened to ossify art.', 'v. 使骨化, 使硬化', '/\'ɔsifai | \'ɒsɪfaɪ | \'ɑsɪfaɪ/', 'ossify', 6);
INSERT INTO `words` VALUES (14706, 'The ostensible purpose of these meetings was to gather information on financial strategies.', 'adj. 可公开得, (指理由等)表面的, 虚假的', '/ɔs\'tensəbl | ɒ\'stensɪb(ə)l | ɑ\'stɛnsəbl/', 'ostensible', 6);
INSERT INTO `words` VALUES (14707, 'Her lifestyle was remarkably free from ostentation.', 'n. 卖弄, 夸耀, 摆阔, 风头主义', '/,ɔsten\'teiʃən | ,ɒsten\'teɪʃ(ə)n | \'ɑstɛn\'teʃən/', 'ostentation', 6);
INSERT INTO `words` VALUES (14708, 'He was vain and ostentatious.', 'adj. 华美的； 炫耀的', '/ˌɑːsten\'teɪʃəs | ,ɑstɛn\'teʃəs/', 'ostentatious', 6);
INSERT INTO `words` VALUES (14709, '...those who have decided to risk social ostracism and stay on the wrong side of town.', 'n. 放逐， 排斥', '/\'ɑːstrəsɪzəm | \'ɑstrəsɪzəm/', 'ostracism', 6);
INSERT INTO `words` VALUES (14710, 'She claims she\'s being ostracized by some members of her local community.', 'v. (古希腊)贝壳放逐法, 放逐, 排斥', '/\'ɔstrəsaiz | \'ɑstrəsaɪz/', 'ostracize', 6);
INSERT INTO `words` VALUES (14711, NULL, 'n. 鸵鸟, 鸵鸟般的人', '/\'ɔ:stritʃ, \'ɔ- | \'ɒstrɪtʃ | \'ɔstrɪtʃ/', 'ostrich', 6);
INSERT INTO `words` VALUES (14712, 'Pisces is a water element. ruled by mystical neptune this sign is extremely receptive compassionate and other-directed .', 'adj. 受人支配的', '/\'ʌðədɪ\'rektɪd | \'ʌðədi\'rektid/', 'other-directed', 6);
INSERT INTO `words` VALUES (14713, 'They encourage an image of the region as an otherworldly sort of place.', 'adj. 来世的, 修来世的, 专注于精神方面的', '/\'ʌðə\'wə:ldli | \'ʌðə\'wɜːldlɪ | \'ʌðɚ\'wɝldli/', 'otherworldly', 6);
INSERT INTO `words` VALUES (14714, NULL, 'adj. 闲着的, 怠惰的, 没有用的, 多余的', '/\'əuʃiəus, -ti- | \'əʊtɪəʊs; \'əʊʃɪ-; -z | \'otɪos/', 'otiose', 6);
INSERT INTO `words` VALUES (14715, 'The leaders have been ousted from power by nationalists.', 'v. 驱逐， 把…赶走', '/aust | aʊst/', 'oust', 6);
INSERT INTO `words` VALUES (14716, 'He later apologized for his outburst.', 'n. 爆发， 迸发； 激增', '/\'autbɜːrst | \'aʊtbɝst/', 'outburst', 6);
INSERT INTO `words` VALUES (14717, NULL, 'adj. 被逐的, 被排斥的, 被遗弃的', '/\'autkɑ:st, -kæst, ,aut\'kɑ:st, -\'kæst | \'aʊtkɑːst | \'aʊtkæst/', 'outcast', 6);
INSERT INTO `words` VALUES (14718, 'outdated teaching methods', 'adj. 过时的', '/ˌaut\'deɪtɪd | \'aʊt\'detɪd/', 'outdated', 6);
INSERT INTO `words` VALUES (14719, 'Was it perhaps dropped by accident as the woman climbed up the 1500 stairs carved outface?', 'v. 睥睨, 蔑视', '/,aut\'feis | aʊt\'feɪs | ,aʊt\'fes/', 'outface', 6);
INSERT INTO `words` VALUES (14720, 'There is no greater thrill than to bluff a man, trap him, and outfox him.', 'v. 以计取胜', '/,aut\'fɔks | aʊt\'fɒks | ,aʊt\'fɑks/', 'outfox', 6);
INSERT INTO `words` VALUES (14721, 'the tray for outgoing mail', 'n. 外出, 开支, 流出', '/\'aʊtgəʊɪŋ | \'aʊt\'goɪŋ/', 'outgoing', 6);
INSERT INTO `words` VALUES (14722, 'a population outgrowing its resources', 'vt. 生长速度超过…， 长得比…快', '/ˌaut\'grou | ,aʊt\'ɡro/', 'outgrow', 6);
INSERT INTO `words` VALUES (14723, NULL, 'n. 结果； 副产品', '/\'autgrouθ | \'aʊtɡroθ/', 'outgrowth', 6);
INSERT INTO `words` VALUES (14724, 'outlandish clothes', 'adj. 外国气派的, 偏僻的, 古怪的, 奇异的', '/aut\'lændiʃ | aʊt\'lændɪʃ/', 'outlandish', 6);
INSERT INTO `words` VALUES (14725, 'Smith outlasted his rivals in the council to become leader in 1996.', 'v. 比…持久', '/ˌaut\'læst | ,aʊt\'læst/', 'outlast', 6);
