INSERT INTO `words` VALUES (14727, 'a research proposal outline', 'n. 轮廓； 概要', '/\'autlaɪn | \'aʊtlaɪn/', 'outline', 6);
INSERT INTO `words` VALUES (14728, 'one of the outlying suburbs', 'adj. 边远的， 偏僻的', '/\'autlaɪɪŋ | \'aʊtlaɪɪŋ/', 'outlying', 6);
INSERT INTO `words` VALUES (14729, NULL, 'v. 以策略制胜', '/ˌautmə\'nuːvər | ,aʊtmə\'nʊvɚ/', 'outmaneuver', 6);
INSERT INTO `words` VALUES (14730, 'outmoded ideas', 'adj. 过时的', '/\'aut\'məudid | aʊt\'məʊdɪd | ,aʊt\'modɪd/', 'outmoded', 6);
INSERT INTO `words` VALUES (14731, 'The response to the jury’s verdict was one of outrage.', 'n. 暴行, 侮辱, 愤怒', '/\'autreidʒ | \'aʊtreɪdʒ | \'aʊtredʒ/', 'outrage', 6);
INSERT INTO `words` VALUES (14732, 'outrageous prices', 'adj. 蛮横的, 残暴的, 无耻的, 可恶的, 令人不可容忍的', '/aut\'reidʒəs | aʊt\'reɪdʒəs | aʊt\'redʒəs/', 'outrageous', 6);
INSERT INTO `words` VALUES (14733, NULL, 'adj. 越出常轨的, 过度的', '/\'u:trei/', 'outre', 6);
INSERT INTO `words` VALUES (14734, 'It was clear from the outset that there were going to be problems.', 'n. 开端, 开始', '/\'autset | \'aʊtset | \'aʊtsɛt/', 'outset', 6);
INSERT INTO `words` VALUES (14735, 'Several new players outshone the veterans.', 'v. 比…光亮； 出色， 优异', '/ˌaut\'ʃaɪn | \'aʊt\'ʃaɪn/', 'outshine', 6);
INSERT INTO `words` VALUES (14736, 'Hours later we reached the outskirts of New York.', 'n. 边界, (尤指)市郊', '/\'autskə:ts | \'aʊtskɜːts | \'aʊt\'skɝts/', 'outskirts', 6);
INSERT INTO `words` VALUES (14737, 'an outspoken critic of the education reforms', 'adj. 坦率的， 直言不讳的', '/aut\'spoukən | aʊt\'spokən/', 'outspoken', 6);
INSERT INTO `words` VALUES (14738, 'We outstripped all our competitors in sales last year.', 'v. 超过', '/,aut\'strip | aʊt\'strɪp | ,aʊt\'strɪp/', 'outstrip', 6);
INSERT INTO `words` VALUES (14739, 'The benefits of the scheme outweigh the disadvantages.', 'v. 比…重， 比…更重要', '/ˌaut\'weɪ | \'aʊt\'we/', 'outweigh', 6);
INSERT INTO `words` VALUES (14740, 'a wolf that had outwitted hunters for years', 'v. 瞒骗, 以智取胜', '/,aut\'wit | aʊt\'wɪt | ,aʊt\'wɪt/', 'outwit', 6);
INSERT INTO `words` VALUES (14741, '...the small oval framed picture of a little boy.', 'adj. 卵形的， 椭圆形的', '/\'ouvl | \'ovl/', 'oval', 6);
INSERT INTO `words` VALUES (14742, 'The Chancellor’s entrance was greeted with a standing ovation (= everyone stood up ).', 'n. 热烈欢迎, 大喝采, 大受欢迎, 欢呼', '/əu\'veiʃən | ə(ʊ)\'veɪʃ(ə)n | o\'veʃən/', 'ovation', 6);
INSERT INTO `words` VALUES (14743, 'Preheat the oven to 200 degrees C.', 'n. 烤箱， 烤炉， 灶', '/\'ʌvn | ˈʌvən/', 'oven', 6);
INSERT INTO `words` VALUES (14744, 'Slender and decently built, Roberts has the look of a martial arts expert but this is one of those movies where he has a tendency to overact.', 'v. 夸张表演', '/,əuvə\'rækt | əʊvər\'ækt | \'ovɚ\'ækt/', 'overact', 6);
INSERT INTO `words` VALUES (14745, 'He was totally overawed by his father.', 'v. 威慑', '/ˌouvər\'ɔː | ,auvə\'rɔ:/', 'overawe', 6);
INSERT INTO `words` VALUES (14746, 'He overbalanced and fell head first.', 'v. 使失去平衡', '/ˌouvər\'bæləns | ,ovɚ\'bæləns/', 'overbalance', 6);
INSERT INTO `words` VALUES (14747, NULL, 'v. 压倒； 镇压； 比…更重要， 超过', '/ˌouvər\'ber | ,əuvə\'bεə/', 'overbear', 6);
INSERT INTO `words` VALUES (14748, 'a bossy overbearing wife', 'adj. 傲慢的, 专横的', '/,əuvə\'bεəriŋ | əʊvə\'beərɪŋ | ,ovɚ\'bɛrɪŋ/', 'overbearing', 6);
INSERT INTO `words` VALUES (14749, 'He’s not really a scientist; he’s just an overblown technician.', 'adj. 盛期已过的， 残败的； 夸张的', '/ˌouvər\'bloun | ,ovɚ\'blon/', 'overblown', 6);
INSERT INTO `words` VALUES (14750, 'Water overbrim med the vessel.', 'vi. 溢出, 满出', '/əʊvə\'brɪm | ,əuvə\'brim/', 'overbrim', 6);
INSERT INTO `words` VALUES (14751, 'a chilly overcast day', 'adj. 阴天的， 阴暗的', '/ˌouvər\'kæst | ,ovɚ\'kæst/', 'overcast', 6);
INSERT INTO `words` VALUES (14752, 'Are you overconfident that you can do the job even though you don\'t have enough experience?', 'adj. 过于自信的， 自负的', '/ˌouvər\'kɑːnfɪdənt/', 'overconfident', 6);
INSERT INTO `words` VALUES (14753, 'The manager of that theatre created a dangerous situation by allowing people to overcrowd the balcony.', 'v. 过度拥挤', '/ˌouvər\'kraud | ,əuvə\'kraud/', 'overcrowd', 6);
INSERT INTO `words` VALUES (14754, 'She took an overdose and died two days later.', 'n. 配药量过多', '/\'əuvədəus, ,əuvə\'dəus | \'əʊvədəʊs | \'ovɚdos/', 'overdose', 6);
INSERT INTO `words` VALUES (14755, NULL, 'v. 透支 for more than the balance； make an overgraft)； 夸大(to exaggerate)', '/ˌouvər\'drɔː | ,ovɚ\'drɔ/', 'overdraw', 6);
INSERT INTO `words` VALUES (14756, 'an overdue gas bill', 'adj. 到期未付的； 晚来的， 延误的', '/ˌouvər\'duː | \'ovɚ\'dʊ/', 'overdue', 6);
INSERT INTO `words` VALUES (14757, 'In the past the exam had been overemphasized.', 'v. 过分强调', '/ˌouvər\'emfəsaɪz | ,əuvər\'emfəsaiz/', 'overemphasize', 6);
INSERT INTO `words` VALUES (14758, 'He tends to overestimate his own abilities.', 'v. 评价过高', '/ˌouvər\'estɪmeɪt | ,ovər\'ɛstɪmət/', 'overestimate', 6);
INSERT INTO `words` VALUES (14759, 'The drains flooded and water overflowed down the main street.', 'v. 溢出； 充满', '/ˌouvər\'flou | ,ovɚ\'flo/', 'overflow', 6);
INSERT INTO `words` VALUES (14760, 'A mechanic is coming to overhaul the engine.', 'v. 检查', '/,əuvə\'hɔ:l, \'əuvəhɔ:l | əʊvə\'hɔːl | \'ovɚhɔl/', 'overhaul', 6);
INSERT INTO `words` VALUES (14761, NULL, 'adj. 过度充气的', '/ˌouvərɪn\'fleɪtɪd | ,ovərɪn\'fletɪd/', 'overinflated', 6);
INSERT INTO `words` VALUES (14762, 'When the bag is folded, the bottom overlaps one side.', 'v. 部分重叠', '/ˌouvər\'læp | \'ovəlæp/', 'overlap', 6);
INSERT INTO `words` VALUES (14763, 'Be careful not to overload the washing machine.', 'v. 使超载', '/ˌouvər\'loud | ,ovɚ\'lod/', 'overload', 6);
INSERT INTO `words` VALUES (14764, 'It is easy to overlook a small detail like that.', 'v. 俯视； 忽视', '/ˌouvər\'luk | ,ovɚ\'lʊk/', 'overlook', 6);
INSERT INTO `words` VALUES (14765, NULL, 'n. 强行剩余', '/\'əuvə,meʒə/', 'overmeasure', 6);
INSERT INTO `words` VALUES (14766, 'A delicate wine will be overpowered by strong food.', 'v. 压倒', '/ˌouvər\'pauər | \'ovɚ\'paʊɚ/', 'overpower', 6);
INSERT INTO `words` VALUES (14767, 'There was an overpowering smell of alcohol.', 'adj. 压倒性的， 不可抗拒的', '/ˌouvər\'pauərɪŋ | \'ovɚ\'paʊərɪŋ/', 'overpowering', 6);
INSERT INTO `words` VALUES (14768, 'More men are finding out that the joys of work have been overrated.', 'v. 对…估价过高， 对…评价过高', '/ˌouvər\'reɪt | ,ovɚ\'ret/', 'overrate', 6);
INSERT INTO `words` VALUES (14769, 'The company overreached itself financially.', 'v. 走过头', '/,əuvə\'ri:tʃ | əʊvə\'riːtʃ | ,ovɚ\'ritʃ/', 'overreach', 6);
INSERT INTO `words` VALUES (14770, 'The EU commission exercised its power to override British policy.', 'v. 制服, 践踏, 奔越过, 蹂躏, 不顾, 不考虑(某人的意见,决定,愿望等)', '/,əuvə\'raid | əʊvə\'raɪd | ,ovɚ\'raɪd/', 'override', 6);
INSERT INTO `words` VALUES (14771, 'a question of overriding importance', 'adj. 最重要的；高于一切的', '/,əuvə\'raidiŋ | əʊvə\'raɪdɪŋ | ,ovɚ\'raɪdɪŋ/', 'overriding', 6);
INSERT INTO `words` VALUES (14772, 'In 1991, the Court of Appeal overruled this decision.', 'v. 驳回, 否决, 支配, 制服', '/,əuvə\'ru:l | əʊvə\'ruːl | ,ovɚ\'rul/', 'overrule', 6);
INSERT INTO `words` VALUES (14773, 'A team leader was appointed to oversee the project.', 'v. 监督', '/ˌouvər\'siː | \'ovɚ\'si/', 'oversee', 6);
INSERT INTO `words` VALUES (14774, 'Fears for the president\'s safety could overshadow his peace-making mission.', 'v. 使蒙上阴影； 使黯然失色', '/ˌouvər\'ʃædou | \'ovɚ\'ʃædo/', 'overshadow', 6);
INSERT INTO `words` VALUES (14775, 'I assure you that this was purely an oversight on my part.', 'n. 疏忽， 失察， 勘漏', '/\'ouvərsaɪt | \'ovɚsaɪt/', 'oversight', 6);
INSERT INTO `words` VALUES (14776, 'To say that all motorists speed in residential areas is overstating the case.', 'v. 夸张， 对…言过其实', '/ˌouvər\'steɪt | ,ovɚ\'stet/', 'overstate', 6);
INSERT INTO `words` VALUES (14777, 'an overt attempt to silence their political opponents', 'adj. 明显的, 公然的', '/\'əuvə:t, əu\'və:t | əʊ\'vɜːt; \'əʊvət | o\'vɝt/', 'overt', 6);
INSERT INTO `words` VALUES (14778, 'You can\'t help a country by overtaxing its people.', 'v. 课税过重', '/ˌouvər\'tæks | \'ovɚ\'tæks/', 'overtax', 6);
INSERT INTO `words` VALUES (14779, 'Rebels were already making plans to overthrow the government.', 'v. 推翻；终止; n. 推翻； 终止', '/ˌouvər\'θrou | ,ovɚ\'θro/', 'overthrow', 6);
INSERT INTO `words` VALUES (14780, NULL, 'v. 使过度疲劳', '/,əuvə\'taiə | ˌouvər\'taɪər/', 'overtire', 6);
INSERT INTO `words` VALUES (14781, 'Meanwhile the conductor lifted his violin bow and the orchestra attacked the overture .', 'n. 建议', '/\'əuvə,tjuə, -tʃuə | \'əʊvətj(ʊ)ə | \'ovətʃʊr/', 'overture', 6);
INSERT INTO `words` VALUES (14782, 'Leslie jumped to her feet, overturning her chair.', 'v. 翻倒 turn over or capsize)； 推翻， 倾覆(to cause the ruin or destruction of； overthrow)', '/ˌouvər\'tɜːrn | \'ovətɝn/', 'overturn', 6);
INSERT INTO `words` VALUES (14783, 'overweening ambition', 'adj. 骄傲的, 自负的, 夸大了的', '/\'əuvə\'wi:niŋ | əʊvə\'wiːnɪŋ | ,ovɚ\'winɪŋ/', 'overweening', 6);
INSERT INTO `words` VALUES (14784, 'It was clear that one massive Allied offensive would overwhelm the weakened enemy.', 'v. 淹没, 覆没, 受打击, 制服, 压倒', '/əʊvə\'welm | ,ovɚ\'wɛlm/', 'overwhelm', 6);
INSERT INTO `words` VALUES (14785, 'There is overwhelming evidence that smoking damages your health.', 'adj. 压倒性的, 无法抵抗的', '/,əuvə\'hwelmiŋ | ,ovɚ\'wɛlmɪŋ/', 'overwhelming', 6);
INSERT INTO `words` VALUES (14786, 'Clara was tired and overwrought after all the problems of the last few days.', 'adj. 过度紧张的, 过劳的', '/,əuvə\'rɔ:t, \'əuvə\'rɔ:t | əʊvə\'rɔːt | ,ovɚ\'rɔt/', 'overwrought', 6);
INSERT INTO `words` VALUES (14787, NULL, 'n. [动]猫头鹰, 枭, 惯于晚上活动的人Object Window Library, Borland C++ 的类库', '/aul | aʊl/', 'owl', 6);
INSERT INTO `words` VALUES (14788, 'If the organic material decays or is oxidized, it will not form petroleum.', 'v. 氧化， 生锈', '/\'ɑːksɪdaɪz | \'ɑksə\'daɪz/', 'oxidize', 6);
INSERT INTO `words` VALUES (14789, NULL, 'n. [医]视觉锐敏', NULL, 'oxyopia', 6);
INSERT INTO `words` VALUES (14790, 'He had two dozen oysters and enjoyed every one of them.', 'n. [动]牡蛎, 蚝, 沉默者', '/\'ɔistə | \'ɒɪstə | \'ɔɪstɚ/', 'oyster', 6);
INSERT INTO `words` VALUES (14791, 'In the long history of inspirational pabulum, \"follow your passion\" has got to be the worst.', 'n. 食物, 营养, 精神食粮', '/\'pæbjuləm | \'pæbjʊləm | \'pæbjələm/', 'pabulum', 6);
INSERT INTO `words` VALUES (14792, 'A Thai architect took his love for elephants and designed a luxury residence and office building in the shape of a pachyderm.', 'n. 厚皮类动物, 迟钝的人', '/\'pækidə:m | \'pækɪdɜːm | \'pækɪdɝm/', 'pachyderm', 6);
INSERT INTO `words` VALUES (14793, NULL, 'n. 抚慰者', '/\'pæsɪfaɪə | \'pæsɪfaɪɚ/', 'pacifier', 6);
INSERT INTO `words` VALUES (14794, 'Many protesters insist they are pacifists, opposed to war in all forms.', 'n. 和平主义者， 反战主义者', '/\'pæsɪfɪst/', 'pacifist', 6);
INSERT INTO `words` VALUES (14795, '‘You’re right,’ Rita said, in order to pacify him.', 'v. 使安静， 抚慰', '/\'pæsɪfaɪ | \'pæsə\'fai/', 'pacify', 6);
INSERT INTO `words` VALUES (14796, 'a wolf pack', 'n. 兽群', '/pæk/', 'pack', 6);
INSERT INTO `words` VALUES (14797, 'a packed courtroom', 'adj. 压紧的， 压实的； 充满人的， 拥挤的', '/pækt/', 'packed', 6);
INSERT INTO `words` VALUES (14798, 'the Warsaw pact', 'n. 合同, 公约, 协定', '/pækt/', 'pact', 6);
INSERT INTO `words` VALUES (14799, '...a paean to deep, passionate love.', 'n. 欢乐歌, 赞美歌', '/\'pi:ən | \'piːən | \'piən/', 'paean', 6);
INSERT INTO `words` VALUES (14800, 'The pagans used torchlight parades and bonfires to celebrate important events.', 'n. 异教徒', '/\'peiɡən | \'peɪg(ə)n | \'pegən/', 'pagan', 6);
INSERT INTO `words` VALUES (14801, 'The country swayed precariously between Christianity and paganism.', 'n. 异教, 异教信仰, 不信教', '/\'peiɡənizəm | \'pegən,ɪzəm/', 'paganism', 6);
INSERT INTO `words` VALUES (14802, '...a historical pageant of kings and queens.', 'n. 盛会, 庆典, 游行, 虚饰, 露天表演', '/\'pædʒənt | \'pædʒ(ə)nt/', 'pageant', 6);
INSERT INTO `words` VALUES (14803, 'an overdose of painkillers', 'n. <美口>止痛药解痛物', '/\'pein,kilə | \'peɪnkɪlə | \'penkɪlɚ/', 'painkiller', 6);
INSERT INTO `words` VALUES (14804, 'The work had been done with painstaking attention to detail.', 'adj. 煞费苦心的', '/\'peɪnzteɪkɪŋ | \'penztekɪŋ/', 'painstaking', 6);
INSERT INTO `words` VALUES (14805, NULL, 'adv. 细心地， 专注地； 辛苦地', '/\'peɪnzteɪkɪŋli | \'peins,teikiŋli/', 'painstakingly', 6);
INSERT INTO `words` VALUES (14806, 'We’ve been pals since we were at school.', 'n. <口>好朋友, 伙伴, 同志', '/pæl/', 'pal', 6);
INSERT INTO `words` VALUES (14807, 'a very palatable wine', 'adj. 美味的', '/\'pælətəbl | \'pælətəb(ə)l/', 'palatable', 6);
INSERT INTO `words` VALUES (14808, 'It tasted very strange, at least to my untrained palate.', 'n. [解]上腭, 味觉, 趣味', '/\'pælit | \'pælət/', 'palate', 6);
INSERT INTO `words` VALUES (14809, 'a palatial country residence', 'adj. 富丽堂皇的', '/pə\'leiʃəl | pə\'leɪʃ(ə)l | pə\'leʃl/', 'palatial', 6);
INSERT INTO `words` VALUES (14810, 'No matter it is business palaver or vacation , we ll provide you the best service .', 'n. 谈判, 交涉, 闲聊', '/pə\'lævə | pə\'lɑːvə | pə\'lɑvɚ/', 'palaver', 6);
INSERT INTO `words` VALUES (14811, NULL, 'adj. (冰、海等)长期冻结的,古结晶的由古结晶冰组成的', NULL, 'paleocrystic', 6);
INSERT INTO `words` VALUES (14812, 'Courses include Latin, paleography, as well as courses in the history and literature of these periods.', 'n. 古文书, 古文书学', '/,peili\'ɔɡrəfi: | ,peɪlɪ\'ɒɡrəfiː | ,pelɪ\'ɑgrəfi/', 'paleography', 6);
INSERT INTO `words` VALUES (14813, 'a paleolithic axe', 'adj. 旧石器时代的', '/,pæliəu\'liθik, ,pei- | ,pælɪəʊ\'lɪθɪk | ,pelɪo\'lɪθɪk/', 'paleolithic', 6);
INSERT INTO `words` VALUES (14814, 'The painter\'s right hand holds the brush, the left the palette.', 'n. 调色板, 颜料', '/\'pælit | \'pælɪt | \'pælət/', 'palette', 6);
INSERT INTO `words` VALUES (14815, 'I never believe palingenesis, but this Ah Q was really the copy of the old one.', 'n. 新生, 转生, 轮回', '/,pælin\'dʒenisis | ,pælɪn\'dʒenɪsɪs/', 'palingenesis', 6);
INSERT INTO `words` VALUES (14816, 'protected from spring tides by a palisade', 'n. 木栅', '/,pæli\'seid | ,pælɪ\'seɪd | ,pælɪ\'sed/', 'palisade', 6);
INSERT INTO `words` VALUES (14817, 'Gradually, the novelty of city life began to pall.', 'v. 令人发腻， 失去吸引力', '/pɔːl | pɔl/', 'pall', 6);
INSERT INTO `words` VALUES (14818, 'Chosen carefully, the oils may not only palliate but also cure the condition.', 'v. 减轻', '/\'pælieit | \'pælɪeɪt | \'pælɪet/', 'palliate', 6);
INSERT INTO `words` VALUES (14819, 'Becausetumor response to cytotoxic chemotherapy has been poor, chemotherapy is used only for palliation.', 'n. 减轻', '/,pæli\'eiʃən/', 'palliation', 6);
INSERT INTO `words` VALUES (14820, 'Good palliative care does not rely on expensive technology, but it does need staff to clean, feed and wash people.', 'adj. 减轻的， 缓和的; n. 缓释剂', '/\'pæliətɪv | \'pælɪ\'etɪv/', 'palliative', 6);
INSERT INTO `words` VALUES (14821, 'pallid cheeks', 'adj. 苍白的, 暗淡的', '/\'pælid | \'pælɪd/', 'pallid', 6);
INSERT INTO `words` VALUES (14822, NULL, 'adj. 杰出的', '/\'pɑːlmərɪ | \'pælməri/', 'palmary', 6);
INSERT INTO `words` VALUES (14823, 'There was a palpable sense of relief among the crowd.', 'adj. 可触知的, 明显的', '/\'pælpəbl | \'pælpəb(ə)l/', 'palpable', 6);
INSERT INTO `words` VALUES (14824, 'He felt suddenly faint, and his heart began to palpitate.', 'v. 跳动', '/\'pælpiteit | \'pælpɪteɪt | \'pælpə\'tet/', 'palpitate', 6);
INSERT INTO `words` VALUES (14825, 'paltry sum of money', 'adj. 不足取的, 无价值的, 琐碎的, 下贱的', '/\'pɔ:ltri | \'pɔːltrɪ; \'pɒl- | \'pɔltri/', 'paltry', 6);
INSERT INTO `words` VALUES (14826, 'And, this Valentines Day, pamper yourself.', 'v. 纵容', '/\'pæmpə | \'pæmpɚ/', 'pamper', 6);
INSERT INTO `words` VALUES (14827, 'a political pamphlet', 'n. 小册子', '/\'pæmflit | ˈpæmflɪt/', 'pamphlet', 6);
INSERT INTO `words` VALUES (14828, 'a frying pan', 'n. 平底锅, 盘子, 面板', '/pæn/', 'pan', 6);
INSERT INTO `words` VALUES (14829, 'Trade is not a panacea for the world\'s economic or social ills.', 'n. 万能药', '/,pænə\'si:ə/', 'panacea', 6);
INSERT INTO `words` VALUES (14830, NULL, 'n. 羽饰, 华丽', '/pə\'næʃ/', 'panache', 6);
INSERT INTO `words` VALUES (14831, 'And actually it damages the pancreas itself, after a while.', 'n. [解]胰腺', '/\'pænkriəs | \'pæŋkrɪəs/', 'pancreas', 6);
INSERT INTO `words` VALUES (14832, 'The goal of recommended actions during these phases is to reduce the impact of the pandemic on society.', 'adj. 全国流行的', '/pæn\'demɪk | pæn\'dɛmɪk/', 'pandemic', 6);
INSERT INTO `words` VALUES (14833, 'There was complete pandemonium in the kitchen.', 'n. 喧嚣；大混乱；大吵大闹', '/,pændi\'məunjəm/', 'pandemonium', 6);
INSERT INTO `words` VALUES (14834, 'He has offended the party\'s traditional base by pandering to the rich and the middle classes.', 'v. 勾引, 拉皮条', '/\'pændə | \'pændɚ/', 'pander', 6);
INSERT INTO `words` VALUES (14835, 'a window pane', 'n. 窗格玻璃', '/peɪn | pen/', 'pane', 6);
INSERT INTO `words` VALUES (14836, 'The book is a panegyric on the intoxicating effects of marijuana.', 'n. 颂词, 推崇备至', '/,pæni\'dʒirik | ,pænɪ\'dʒɪrɪk | ˌpænə\'dʒɪrɪk/', 'panegyric', 6);
INSERT INTO `words` VALUES (14837, 'He assembled a panel of scholars to advise him.', 'n. 面板, 嵌板, 仪表板, 座谈小组, 全体陪审员', '/\'pænl | \'pæn(ə)l/', 'panel', 6);
INSERT INTO `words` VALUES (14838, 'For a moment she felt a pang of guilt about the way she was treating him.', 'n. 一阵剧痛', '/pæŋ/', 'pang', 6);
INSERT INTO `words` VALUES (14839, 'a feeling of sheer panic', 'n. 惊慌, 恐慌, 没有理由的', '/\'pænik | \'pænɪk/', 'panic', 6);
INSERT INTO `words` VALUES (14840, NULL, 'n. 全套甲胄, 华丽服饰', '/\'pænəpli | \'pænəplɪ/', 'panoply', 6);
INSERT INTO `words` VALUES (14841, 'Horton looked out over a panorama of fertile valleys and gentle hills.', 'n. 全景全景画,全景摄影', '/,pænə\'rɑ:mə | pænə\'rɑːmə | ,pænə\'ræmə/', 'panorama', 6);
INSERT INTO `words` VALUES (14842, 'The terrain\'s high points provide a panoramic view of Los Angeles.', 'adj. 全景的， 全貌的， 概论的', '/ˌpænə\'ræmɪk | ,pænə\'ræmɪk/', 'panoramic', 6);
INSERT INTO `words` VALUES (14843, 'the Roman pantheon', 'n. 万神殿, 罗马万神殿, 伟人祠', '/pæn\'θi:ən | \'pænθɪən/', 'pantheon', 6);
INSERT INTO `words` VALUES (14844, 'They were made welcome with the usual pantomime of exaggerated smiles and gestures.', 'n. 手势, 哑剧, 舞剧', '/\'pæntəmaim | \'pæntəmaɪm/', 'pantomime', 6);
INSERT INTO `words` VALUES (14845, NULL, 'n. 餐具室, 食品室', '/\'pæntri | \'pæntrɪ/', 'pantry', 6);
INSERT INTO `words` VALUES (14846, NULL, 'n. (北美土人的)幼儿, 婴儿', '/pə\'pu:s | pə\'puːs | pə\'pus/', 'papoose', 6);
INSERT INTO `words` VALUES (14847, 'Two types of mummification are known, the \"hematic\" type common to cattle and the \" papyraceous \" type of swine.', 'adj. 纸草的, 纸状的', '/,pæpɪ\'reɪʃəs | ,pæpə\'reʃəs/', 'papyraceous', 6);
INSERT INTO `words` VALUES (14848, 'In those days, paper was made from strips of the papyrus plant.', 'n. [植]纸草, 草制成之纸', '/pə\'paiərəs | pə\'paɪrəs/', 'papyrus', 6);
INSERT INTO `words` VALUES (14849, 'bonds sold at 97% of their par value', 'n. 同等, (股票等)票面价值', '/pɑ: | pɑː | pɑr/', 'par', 6);
INSERT INTO `words` VALUES (14850, '...the parable of the Good Samaritan.', 'n. 寓言, 比喻', '/\'pærəbl | \'pærəb(ə)l/', 'parable', 6);
INSERT INTO `words` VALUES (14851, 'So, we should draw maybe this downward parabola.', 'n. [数] 抛物线', '/pə\'ræbələ | pə\'ræb(ə)lə/', 'parabola', 6);
INSERT INTO `words` VALUES (14852, '...a new paradigm of production.', 'n. 范例', '/\'pærədim | \'pærədaɪm | \'pærə\'daɪm/', 'paradigm', 6);
INSERT INTO `words` VALUES (14853, 'This is very good paradigmatic.', 'adj. 例证的', '/,pærədiɡ\'mætik | pærədɪg\'mætɪk | ,pærədɪg\'mætɪk/', 'paradigmatic', 6);
INSERT INTO `words` VALUES (14854, 'It’s a paradox that in such a rich country there can be so much poverty.', 'n. 似非而是的论点, 自相矛盾的话', '/\'pærədɔks | \'pærədɒks | \'pærədɑks/', 'paradox', 6);
INSERT INTO `words` VALUES (14855, 'Some sedatives produce the paradoxical effect of making the person more anxious.', 'adj. 矛盾的； 不正常的', '/ˌpærə\'dɑːksɪkl | ,pærə\'dɑksɪkl/', 'paradoxical', 6);
INSERT INTO `words` VALUES (14856, 'We don\'t expect candidates to be paragons of virtue.', 'n. 模范', '/\'pærəɡən | \'pærəg(ə)n | \'pærəɡɑn/', 'paragon', 6);
INSERT INTO `words` VALUES (14857, 'There is a parallelism between fatigue and the ability to sleep.', 'n. 平行， 类似', '/\'pærəlelɪzəm | \'pærəlɛl\'ɪzəm/', 'parallelism', 6);
INSERT INTO `words` VALUES (14858, 'paralysis of the lower body', 'n. 瘫痪, 麻痹', '/pə\'rælisis | pə\'rælɪsɪs | pə\'ræləsɪs/', 'paralysis', 6);
INSERT INTO `words` VALUES (14859, 'You can bet that would truly paralyze the flow of credit: Does anyone believe Washington can manage banks?', 'v. 使瘫痪, 使麻痹', '/\'pærəlaiz | \'pærə,laɪz/', 'paralyze', 6);
INSERT INTO `words` VALUES (14860, 'During a war the interests of the state are paramount, and those of the individual come last.', 'adj. 极为重要的', '/\'pærəmaunt | \'pærəmaʊnt/', 'paramount', 6);
INSERT INTO `words` VALUES (14861, 'They capitalize on panic and paranoia.', 'n. [心]妄想狂, 偏执狂', '/,pærə\'nɔiə | ,pærə\'nɒɪə | ,pærə\'nɔɪə/', 'paranoia', 6);
INSERT INTO `words` VALUES (14862, '...these sad, deluded paranoids.', 'n. (=paranoiac)患妄想狂者', '/\'pærənɔid | \'pærənɒɪd | \'pærənɔɪd/', 'paranoid', 6);
INSERT INTO `words` VALUES (14863, 'To paraphrase Finkelstein, mathematics is a language, like English.', 'v. 释义， 解释， 改写; n. 释义，解释，改写', '/\'pærəfreɪz | ˈpærəfreɪz/', 'paraphrase', 6);
INSERT INTO `words` VALUES (14864, 'Kangaroos harbour a vast range of parasites.', 'n. 寄生虫, 食客', '/\'pærəsait | \'pærəsaɪt/', 'parasite', 6);
INSERT INTO `words` VALUES (14865, 'parasitic fungi', 'adj. 寄生的', '/ˌpærə\'sɪtɪk | ,pærə\'sɪtɪk/', 'parasitic', 6);
INSERT INTO `words` VALUES (14866, 'Then the branch wasbroken off for her, and she held it in her delicate hand, and sheltered it with her silk parasol.', 'n. (女用)阳伞', '/,pærə\'sɔ:l | \'pærəsɒl | \'pærəsɔl/', 'parasol', 6);
INSERT INTO `words` VALUES (14867, 'Skeletal remodeling is controlled by the actions of many different hormones, including vitamin D and parathyroid hormone (PTH).', 'adj. 副甲状腺的', '/,pærə\'θairɔid | pærə\'θaɪrɒɪd | ,pærə\'θaɪrɔɪd/', 'parathyroid', 6);
INSERT INTO `words` VALUES (14868, 'These grains may parch , but they will not pop.', 'v. 烤(干), 烘(干)', '/pɑ:tʃ | pɑːtʃ | pɑrtʃ/', 'parch', 6);
INSERT INTO `words` VALUES (14869, '...old manuscripts written on parchment.', 'n. 羊皮纸, 毕业文凭', '/\'pɑ:tʃmənt | \'pɑːtʃm(ə)nt | \'pɑrtʃmənt/', 'parchment', 6);
INSERT INTO `words` VALUES (14870, 'The governor\'s campaign fund could be pared down to $500.', 'v. 剥, 削, 修, 削减, 消灭', '/pεə | peə | pɛr/', 'pare', 6);
INSERT INTO `words` VALUES (14871, 'In parenthesis, I should add that the results have not yet been proven.', 'n. 插入语, 附带, 插曲, 圆括号', '/[pəˈrenθɪsɪs] | pə\'renθɪsɪs | pə\'rɛnθəsɪs/', 'parenthesis', 6);
INSERT INTO `words` VALUES (14872, 'First, simply, it was a matter of face, of reducing its pariah-state image —a tangible symbol of being welcomed back into the global community.', 'n. 贱民(印度的最下阶级)', '/\'pæriə | pə\'raɪə/', 'pariah', 6);
INSERT INTO `words` VALUES (14873, 'Women have yet to achieve wage or occupational parity in many fields.', 'n. 同等， 相等', '/\'pærəti/', 'parity', 6);
INSERT INTO `words` VALUES (14874, 'It’s a bit parky outside today.', 'adj. 寒冷的', '/\'pɑ:ki | \'pɑːkɪ | \'pɑrki/', 'parky', 6);
INSERT INTO `words` VALUES (14875, 'We must send our most trusted officer to parley with their leaders for an exchange of prisoners.', 'n. 会谈', '/\'pɑːlɪ | \'pɑrli/', 'parley', 6);
INSERT INTO `words` VALUES (14876, 'the world’s oldest parliamentary democracy', 'adj. 议会的', '/ˌpɑːrlə\'mentri | ,pɑrlə\'mɛntri/', 'parliamentary', 6);
INSERT INTO `words` VALUES (14877, 'The country’s police force was in a parlous state in 1990.', 'adj. 危险的, 不易对付的, 精明的, 狡猾的', '/\'pɑ:ləs | \'pɑːləs/', 'parlous', 6);
INSERT INTO `words` VALUES (14878, 'the parochial church council', 'adj. 教区的, 地方范围的, 狭小的', '/pə\'rəukjəl | pə\'rəʊkɪəl | pə\'rokɪəl/', 'parochial', 6);
INSERT INTO `words` VALUES (14879, 'Her performance contains a strong element of self-parody (= when someone makes fun of their own style ) .', 'n. 模仿滑稽作品, 拙劣的模仿', '/\'pærədi | \'pærədɪ/', 'parody', 6);
INSERT INTO `words` VALUES (14880, 'The doctor just have 50,000 diagnosis a month, artificial intelligence and parol professionals are part of that.', 'n. 口头言词', '/pə\'rəʊl; \'pær(ə)l | pə\'rol/', 'parol', 6);
INSERT INTO `words` VALUES (14881, 'He exploded in a paroxysm of rage.', 'n. 发作, 突发', '/\'pærəksizəm/', 'paroxysm', 6);
INSERT INTO `words` VALUES (14882, 'a parquet floor', 'n. 镶木地板, 正厅', '/\'pɑ:kei | \'pɑːkɪ; \'pɑːkeɪ | pɑr\'ke/', 'parquet', 6);
INSERT INTO `words` VALUES (14883, NULL, 'n. 镶花木细工, 镶木地板', '/\'pɑ:kitri | \'pɑːkɪtrɪ/', 'parquetry', 6);
INSERT INTO `words` VALUES (14884, 'It is far easier to parry a direct blow than to stop it forcibly.', 'n. 躲避', '/\'pæri | \'pærɪ/', 'parry', 6);
INSERT INTO `words` VALUES (14885, 'How would you parse it, then?', 'v. 解析', '/pɑ:z | pɑːz | pɑrs/', 'parse', 6);
INSERT INTO `words` VALUES (14886, 'Yet the big brewers have been parsimonious in their marketing budgets, typically investing just 10% or so of their revenues, compared with around 15% at companies like Unilever and Procter &Gamble.', 'adj. 吝啬的, 节俭的', '/,pɑ:si\'məunjəs | ,pɑːsɪ\'məʊnɪəs | ,pɑrsə\'monɪəs/', 'parsimonious', 6);
INSERT INTO `words` VALUES (14887, 'Due to official parsimony only the one machine was built.', 'n. 过分节俭， 吝啬', '/\'pɑːrsəmouni | \'pɑrsə\'moni/', 'parsimony', 6);
INSERT INTO `words` VALUES (14888, 'the problem of partiality in news reporting', 'n. 偏爱', '/,pɑ:ʃi\'æliti | pɑːʃɪ\'ælɪtɪ | \'pɑrʃɪ\'æləti/', 'partiality', 6);
INSERT INTO `words` VALUES (14889, 'Some members refused to participate.', 'v. 分担； 参与； 分享', '/pɑːr\'tɪsɪpeɪt | pɑr\'tɪsə\'pet/', 'participate', 6);
INSERT INTO `words` VALUES (14890, 'Thank you for your participation.', 'n. 参加， 参与', '/pɑːrˌtɪsɪ\'peɪʃn | pɑr,tɪsɪ\'peʃən/', 'participation', 6);
INSERT INTO `words` VALUES (14891, 'For further particulars , contact the College secretary.', 'n. 细节， 详情', '/pər\'tɪkjələr | pɚ\'tɪkjəlɚ/', 'particular', 6);
INSERT INTO `words` VALUES (14892, 'the particularity of her style of writing', 'n. 独特性', '/pərˌtɪkju\'lærəti | pɚ\'tɪkju\'lærəti/', 'particularity', 6);
INSERT INTO `words` VALUES (14893, 'Mr. Johnson particularizes the general points he wants to make.', 'v. 详述， 列举', '/pər\'tɪkjələraɪz | pɚ\'tɪkjələraɪz/', 'particularize', 6);
INSERT INTO `words` VALUES (14894, 'We tell you not only are they teeming with life, but the planets and stars and the space particulate between are themselves all conscious beings.', 'adj. 微粒的; n. 微粒', '/pɑːr\'tɪkjələt | pɚ\'tɪkjə,let/', 'particulate', 6);
INSERT INTO `words` VALUES (14895, 'a media campaign to represent Democrats as angry partisans', 'n. 游击队', '/,pɑ:ti\'zæn | \'pɑːtɪzæn; ,pɑːtɪ\'zæn | \'pɑrtəzn/', 'partisan', 6);
INSERT INTO `words` VALUES (14896, '...new offices divided only by glass partitions.', 'n. 分割, 划分, 瓜分, 分开, 隔离物', '/pɑ:\'tiʃən | pɑː\'tɪʃ(ə)n | pɑr\'tɪʃən/', 'partition', 6);
INSERT INTO `words` VALUES (14897, 'Did the parturition go well yesterday evening?', 'n. 分娩, 生产', '/,pɑ:tjuə\'riʃən | ,pɑːtjʊ\'rɪʃ(ə)n | ,pɑrtjʊ\'rɪʃən/', 'parturition', 6);
INSERT INTO `words` VALUES (14898, NULL, 'n. 暴发户', '/\'pɑ:vənju | \'pɑːvənuː; -njuː | \'pɑrvənu/', 'parvenu', 6);
INSERT INTO `words` VALUES (14899, 'To ridicule with a pasquinade;', 'n. 讽刺诗, 讽刺文', '/,pæskwi\'neid/', 'pasquinade', 6);
INSERT INTO `words` VALUES (14900, NULL, 'adj. 已过盛年的； 过时的', '/\'pa:sei | pæ\'seɪ/', 'passe', 6);
INSERT INTO `words` VALUES (14901, 'What you\'re seeing in the Alley is second- and third-generation entrepreneurs. You have a passel of more experienced investors.', 'n. 一批, 一群', '/\'pæs(ə)l | \'pæsəl/', 'passel', 6);
INSERT INTO `words` VALUES (14902, NULL, 'adj. 易动情的', '/\'pæsɪb(ə)l | \'pæsəbl/', 'passible', 6);
INSERT INTO `words` VALUES (14903, 'He had a brief but passionate love affair with an older woman.', 'adj. 充满激情的', '/\'pæʃənət/', 'passionate', 6);
INSERT INTO `words` VALUES (14904, 'Exploit activate and passivate for transient variables to enable pooling', 'vt. [冶]使钝化', '/\'pæsɪveɪt | \'pæsəvet/', 'passivate', 6);
INSERT INTO `words` VALUES (14905, 'Kathy seems to take a very passive role in the relationship.', 'adj. 被动的， 缺乏活力的', '/\'pæsɪv/', 'passive', 6);
INSERT INTO `words` VALUES (14906, 'No matter what caused the problems, we have no reason to passively accept them.', 'adv. 被动地， 顺从地', '/\'pæsɪvli/', 'passively', 6);
INSERT INTO `words` VALUES (14907, 'Mix the powder with enough water to make a smooth paste.', 'n. 糊, 面团, 黏土团', '/peist | peɪst | pest/', 'paste', 6);
INSERT INTO `words` VALUES (14908, 'The lobby is decorated in pastels.', 'n. 彩色蜡笔, 彩色蜡笔画', '/pæs\'tel | \'pæst(ə)l | pæ\'stɛl/', 'pastel', 6);
INSERT INTO `words` VALUES (14909, 'Finally, they pasteurize the milk with a special technique that heats it to about 144.5 degrees Fahrenheit, minimizing the destruction of antibodies while killing viruses and other pathogens.', 'v. 用巴氏法灭菌', '/\'pæstəraiz | \'pɑːstʃəraɪz; -stjə-; \'pæs- | \'pæstʃəraɪz/', 'pasteurize', 6);
INSERT INTO `words` VALUES (14910, 'His bathroom is a brilliant pastiche of expensive interior design.', 'n. 混成曲, 模仿画', '/pæs\'ti:ʃ, pɑ: | pæ\'stiːʃ/', 'pastiche', 6);
INSERT INTO `words` VALUES (14911, 'Reading was her favourite pastime.', 'n. 消遣, 娱乐', '/\'pɑ:staim | \'pɑːstaɪm | \'pæstaɪm/', 'pastime', 6);
INSERT INTO `words` VALUES (14912, 'the pastor of Carr’s Lane Congregational church', 'n. 牧师', '/\'pɑ:stə, \'pæs- | \'pɑːstə | \'pæstɚ/', 'pastor', 6);
INSERT INTO `words` VALUES (14913, 'a charming pastoral scene', 'n. 牧歌, 田园文学, 田园诗', '/\'pɑ:stərəl, \'pæs- | \'pɑːst(ə)r(ə)l | \'pæstərəl/', 'pastoral', 6);
INSERT INTO `words` VALUES (14914, 'a Danish pastry', 'n. 面粉糕饼, 馅饼皮', '/\'peistri | \'peɪstrɪ | \'pestri/', 'pastry', 6);
INSERT INTO `words` VALUES (14915, 'My complexion remained pale and pasty.', 'adj. 面糊似的, 浆状的, 苍白的', '/\'peisti | \'pæstɪ | \'pæsti/', 'pasty', 6);
INSERT INTO `words` VALUES (14916, 'Look out for icy patches on the road.', 'n. 片, 补缀, 碎片, 斑纹, 斑点, 小块地, 眼罩, 傻瓜', '/pætʃ/', 'patch', 6);
INSERT INTO `words` VALUES (14917, 'a patchwork quilt', 'n. 拼缝物, 拼缀物, 拼凑物', '/\'pætʃwə:k | \'pætʃwɜːk | \'pætʃ\'wɝk/', 'patchwork', 6);
INSERT INTO `words` VALUES (14918, 'He wants to take out a patent on his new type of dustbin.', 'n. 专利权, 执照, 专利品', '/\'pætnt | \'pæt(ə)nt; \'peɪt(ə)nt/', 'patent', 6);
INSERT INTO `words` VALUES (14919, 'The child looked a pathetic sight.', 'adj. 可怜的, 悲惨的', '/pə\'θetik | pə\'θetɪk | pə\'θɛtɪk/', 'pathetic', 6);
INSERT INTO `words` VALUES (14920, 'a pathological hatred of women', 'adj. 病态的， 不理智的； 病理学的', '/ˌpæθə\'lɑːdʒɪkl | \'pæθə\'lɑdʒɪkl/', 'pathological', 6);
INSERT INTO `words` VALUES (14921, 'One person may show lots of pathology in their brain while another shows very little, yet both may have had dementia.', 'n. 病理学', '/pə\'θɒlədʒɪ | pə\'θɑlədʒi/', 'pathology', 6);
INSERT INTO `words` VALUES (14922, 'the pathos of the woman trying to keep her lover', 'n. 痛苦, 感伤, 悲怅, 哀婉', '/\'peiθɔs | \'peɪθɒs | \'peθɑs/', 'pathos', 6);
INSERT INTO `words` VALUES (14923, 'He doesn\'t have the patience to wait.', 'n. 耐性', '/\'peɪʃns | \'peʃns/', 'patience', 6);
INSERT INTO `words` VALUES (14924, 'He allowed a fine patina of old coffee to develop around the inside of the mug.', 'n. 铜绿, 绿锈, 薄层, 光泽, 古色', '/\'pætinə | \'pætɪnə | pə\'tinə/', 'patina', 6);
INSERT INTO `words` VALUES (14925, 'With a pool and patio outside and a working fireplace and spiral staircases inside, the seven-bedroom house should have buyers lining up.', 'n. 天井, 院子', '/\'pætiəu | \'pætɪəʊ | \'pætɪo/', 'patio', 6);
INSERT INTO `words` VALUES (14926, 'a patriarchal society', 'adj. 家长的， 族长的； 父权制的', '/ˌpeɪtri\'ɑːrkl | ,petrɪ\'ɑrkl/', 'patriarchal', 6);
INSERT INTO `words` VALUES (14927, 'The main cause of women\'s and children\'s oppression is patriarchy.', 'n. 家长统治, 父权制', '/\'peitriɑ:ki | \'peɪtrɪɑːkɪ | \'petrɪɑrki/', 'patriarchy', 6);
INSERT INTO `words` VALUES (14928, 'Cameron was a rich man, a patrician.', 'n. 贵族', '/pə\'triʃən | pə\'trɪʃ(ə)n | pə\'trɪʃən/', 'patrician', 6);
INSERT INTO `words` VALUES (14929, 'It has been suggested the founders were not true patriots but men out to protect their own interests.', 'n. 爱国者， 爱国主义者', '/\'peɪtriət | \'petrɪət/', 'patriot', 6);
INSERT INTO `words` VALUES (14930, 'He was a country boy who had joined the army out of a sense of patriotism and adventure.', 'n. 爱国心, 爱国精神', '/\'pætriətizəm | \'peɪtrɪətɪz(ə)m | \'petrɪətɪzəm/', 'patriotism', 6);
INSERT INTO `words` VALUES (14931, 'Thank you for your patronage.', 'n. 保护人的身份, 保护, 赞助, 光顾', '/\'pætrənidʒ | ˈpeɪtrənɪdʒ | \'pætrənɪdʒ/', 'patronage', 6);
INSERT INTO `words` VALUES (14932, 'Don\'t you patronize me!.', 'v. 屈尊俯就； 光顾， 惠顾', '/\'peɪtrənaɪz | ˈpeɪtrəˌnaɪz;ˈpætrənˌaɪz/', 'patronize', 6);
INSERT INTO `words` VALUES (14933, 'a patronizing attitude', 'adj. 以恩惠态度对待的， 要人领情的', '/\'peɪtrənaɪzɪŋ | \'petrənaɪzɪŋ/', 'patronizing', 6);
INSERT INTO `words` VALUES (14934, 'Davis was nobody\'s patsy.', 'n. 容易受骗的人, 懦夫', '/\'pætsi | \'pætsɪ/', 'patsy', 6);
