INSERT INTO `words` VALUES (14936, 'Even the film\'s impressive finale can\'t hide the first hour\'s paucity of imagination.', 'n. 极小量', '/\'pɔ:siti | \'pɔːsɪtɪ/', 'paucity', 6);
INSERT INTO `words` VALUES (14937, 'The poor pauper paused on purpose to pawn a porpoise.', 'n. 贫民； 乞丐', '/\'pɔːpər | \'pɔpɚ/', 'pauper', 6);
INSERT INTO `words` VALUES (14938, 'Never be pavid to express yourself.', 'adj. 害怕的, 胆小的', '/\'pævɪd/', 'pavid', 6);
INSERT INTO `words` VALUES (14939, 'He is contemplating pawning his watch.', 'n. 典当, 抵押物, 人质, (象棋)兵、卒, 爪牙, 被人利用的人', '/pɔ:n | pɔːn | pɔn/', 'pawn', 6);
INSERT INTO `words` VALUES (14940, 'The best of the rest include “Octubre,” about a Peruvian pawnbroker who unwillingly finds himself the custodian of an infant daughter and a romantic foil for her nurse.', 'n. 典当商', '/\'pɔ:n,brəukə | \'pɔːnbrəʊkə | \'pɔnbrokɚ/', 'pawnbroker', 6);
