INSERT INTO `words` VALUES (14942, 'Anderton scored a peach of a goal.', 'n. 桃子, 桃树, 桃色, <美俚>受人喜欢的人(或物)', '/pi:tʃ | piːtʃ | pitʃ/', 'peach', 6);
INSERT INTO `words` VALUES (14943, 'a delicious peachy flavour', 'adj. 桃色的', '/\'piːtʃɪ | \'pitʃi/', 'peachy', 6);
INSERT INTO `words` VALUES (14944, 'Sales this month have reached a new peak .', 'n. 山顶, 顶点, 帽舌, (记录的)最高峰', '/pi:k | piːk | pik/', 'peak', 6);
INSERT INTO `words` VALUES (14945, 'He’s looking a bit peaky today.', 'adj. 尖峰的, 多峰的', '/\'pi:ki: | \'piːkɪ | \'piki/', 'peaky', 6);
INSERT INTO `words` VALUES (14946, NULL, 'adj. 有精神的, 快活的, 聪明的', '/pɪət; pjɜːt | piət/', 'peart', 6);
INSERT INTO `words` VALUES (14947, 'As the last Ice Age came to an end, somebody picked a pebble out of a small river not far from Bethlehem.', 'n. 小圆石, 小鹅卵石', '/\'pebl | \'peb(ə)l | \'pɛbl/', 'pebble', 6);
INSERT INTO `words` VALUES (14948, 'The aroma, butter pecan milk incense, and the lemon of the faint scent, rum the bouquet, four sweet fusion, challenge your taste buds.', 'n. [植]美洲山核桃树, 美洲山核桃', '/pi\'kæn | \'piːk(ə)n; pɪ\'kæn; pɪ\'kɑːn | pɪ\'kɑn/', 'pecan', 6);
INSERT INTO `words` VALUES (14949, 'The public is willing to forgive him for his peccadillos.', 'n. 轻罪, 小过失', '/,pekə\'diləu | ,pekə\'dɪləʊ/', 'peccadillo', 6);
INSERT INTO `words` VALUES (14950, 'It was winter and the sparrows were pecking at whatever they could find.', 'v. 啄食； 轻啄', '/pek | pɛk/', 'peck', 6);
INSERT INTO `words` VALUES (14951, 'She was feeling a bit peckish .', 'adj. 饥饿的, 唠叨的', '/\'pekiʃ | \'pekɪʃ | \'pɛkɪʃ/', 'peckish', 6);
INSERT INTO `words` VALUES (14952, 'This gold-and-glass pectoral amulet was discovered in the tomb of Tutankhamun near Luxor, Egypt.', 'adj. 胸的, 肺病的', '/\'pektərəl | \'pekt(ə)r(ə)l | \'pɛktərəl/', 'pectoral', 6);
INSERT INTO `words` VALUES (14953, 'It means that we can modify and peculate the code.', 'v. 挪用, 盗用', '/\'pekjuleit | \'pekjʊleɪt/', 'peculate', 6);
INSERT INTO `words` VALUES (14954, 'There was a peculiar smell in the kitchen.', 'adj. 独特的； 古怪的', '/pɪ\'kjuːliər | pɪ\'kjulɪɚ/', 'peculiar', 6);
INSERT INTO `words` VALUES (14955, 'He was trying to get a pecuniary advantage for himself.', 'adj. 金钱的, 金钱上的, 应罚款的', '/pi\'kju:njəri | pɪ\'kjuːnɪərɪ | pɪ\'kjunɪɛri/', 'pecuniary', 6);
INSERT INTO `words` VALUES (14956, 'The relationship to nature is an important part of the school\'s pedagogic concept.', 'adj. 教育学的', '/ˌpedə\'gɑːdʒɪk | ,pɛdə\'ɡɑdʒɪk/', 'pedagogic', 6);
INSERT INTO `words` VALUES (14957, 'I’ve learned as much about teaching from learning about marketing as I have from studying pedagogy – maybe more.', 'n. 教学, 教授, 教育学', '/\'pedəɡɔɡi | \'pedəgɒdʒɪ; -gɒgɪ | \'pɛdə\'godʒi/', 'pedagogy', 6);
INSERT INTO `words` VALUES (14958, 'She was pedalling furiously (= very fast ) .', 'v. 骑自行车; n. 踏板，脚蹬', '/\'pedl | \'pɛdl/', 'pedal', 6);
INSERT INTO `words` VALUES (14959, '‘That’s not exactly what it means.’ ‘Pedant.’', 'n. 学究式人物', '/\'pedənt | \'ped(ə)nt | \'pɛdnt/', 'pedant', 6);
INSERT INTO `words` VALUES (14960, 'If nothing else, having a few recondite words at your disposal can be a great defense against the pedantry of others.', 'n. 炫学, 假装学者, 卖弄学问', '/\'pedəntri | \'ped(ə)ntrɪ | \'pɛdntri/', 'pedantry', 6);
INSERT INTO `words` VALUES (14961, 'They were accused of peddling drugs .', 'v. 兜售', '/\'pedl | \'pɛdl/', 'peddle', 6);
INSERT INTO `words` VALUES (14962, NULL, 'adj. 忙于琐事的, 无关紧要的', '/\'pedliŋ | \'pedlɪŋ | \'pɛdlɪŋ/', 'peddling', 6);
INSERT INTO `words` VALUES (14963, '...a larger than life-sized bronze statue on a granite pedestal.', 'n. 基架, 底座, 基础', '/\'pedistəl | \'pedɪst(ə)l | \'pɛdɪstl/', 'pedestal', 6);
INSERT INTO `words` VALUES (14964, 'Ingrid was a walker, even in Los Angeles, where a pedestrian is a rare sight.', 'n. 步行者', '/pi\'destriən | pɪˈdestrɪən | pə\'dɛstrɪən/', 'pedestrian', 6);
INSERT INTO `words` VALUES (14965, NULL, 'n. [医]小儿科', '/,pi:di\'ætriks | ,piːdɪ\'ætrɪks | ,pidi\'ætrɪks/', 'pediatrics', 6);
INSERT INTO `words` VALUES (14966, 'The service pedigree helps to determine the importance of the service in context of all the services provided.', 'n. 血统, 家谱', '/\'pediɡri: | \'pedɪgriː | \'pɛdɪɡri/', 'pedigree', 6);
INSERT INTO `words` VALUES (14967, 'Companies have been paying outrageous fees for a peek at the technical data.', 'n. 一瞥, 匆忙看过', '/pi:k | piːk | pik/', 'peek', 6);
INSERT INTO `words` VALUES (14968, 'Peel and dice the potatoes.', 'v. 削去…的皮；剥落; n. 外皮', '/piːl | pil/', 'peel', 6);
