INSERT INTO `words` VALUES (14974, 'The kids were peevish after so long in the car.', 'adj. 易怒的, 暴躁的, 带怒气的, 倔强的', '/\'pi:viʃ | \'piːvɪʃ | \'pivɪʃ/', 'peevish', 6);
INSERT INTO `words` VALUES (14975, 'For hard-line Republicans, the word ‘liberal’ had become a pejorative term.', 'adj. 变坏的, 轻蔑的', '/\'pi:dʒərətive | pɪ\'dʒɒrətɪv | pɪ\'dʒɔrətɪv/', 'pejorative', 6);
INSERT INTO `words` VALUES (14976, 'pelagic fish', 'adj. 远洋的, 浮游的', '/pe\'lædʒik | pɪ\'lædʒɪk | pə\'lædʒɪk/', 'pelagic', 6);
INSERT INTO `words` VALUES (14977, 'After plundering enough pelf, he took a train bound for the border.', 'n. 钱财', '/pelf/', 'pelf', 6);
INSERT INTO `words` VALUES (14978, 'The children ran pell-mell out of school.', 'adv. 混乱地', '/ˌpel\'mel | \'pel\'mel/', 'pell-mell', 6);
INSERT INTO `words` VALUES (14979, 'a pellucid stream', 'adj. 透明的, 澄清的, 易懂的', '/pe\'lju:sid | pɪ\'luːsɪd; pe-; -\'ljuːsɪd/', 'pellucid', 6);
INSERT INTO `words` VALUES (14980, '...a bed covered with beaver pelts.', 'n. 投掷, 疾行, 毛皮', '/pelt | pɛlt/', 'pelt', 6);
INSERT INTO `words` VALUES (14981, 'a ballpoint pen', 'n. 钢笔, 围栏, 围圈, 作家', '/pen | pɛn/', 'pen', 6);
INSERT INTO `words` VALUES (14982, 'the penal system', 'adj. 惩罚的， 刑罚的', '/\'piːnl | \'pinl/', 'penal', 6);
INSERT INTO `words` VALUES (14983, 'Women feel professionally penalized for taking time off to raise children.', 'v. 处罚', '/\'pi:nəlaiz | \'pi:nəlaɪz | \'pinəlaɪz/', 'penalize', 6);
INSERT INTO `words` VALUES (14984, 'No littering. Penalty $500.', 'n. 处罚, 罚款', '/\'penəlti | \'pen(ə)ltɪ | \'pɛnəlti/', 'penalty', 6);
INSERT INTO `words` VALUES (14985, '...a time of fasting, penance, and pilgrimage.', 'n. [天主教]忏悔, 苦修', '/\'penəns | \'pɛnəns/', 'penance', 6);
INSERT INTO `words` VALUES (14986, 'There is also reason to think that our penchant for makingunhealthy choices might be enhanced by the abundance of particularfoods.', 'n. (强烈的)倾向, 趣味', '/\'pentʃənt,pā:ŋ\'ʃā:ŋ | ˈpɒŋʃɒŋ | \'pentʃənt/', 'penchant', 6);
INSERT INTO `words` VALUES (14987, 'a pendent lamp', 'adj. 悬而未决的, 未定的', '/\'pendənt | \'pend(ə)nt | \'pɛndənt/', 'pendent', 6);
