INSERT INTO `words` VALUES (14989, 'pendulous breasts', 'adj. 下垂的', '/\'pendjuləs, -dʒə- | \'pendjʊləs | \'pɛndʒələs/', 'pendulous', 6);
INSERT INTO `words` VALUES (14990, 'After several years of Republican government, the pendulum will undoubtedly swing back and voters will elect a Democrat.', 'n. 钟摆, 摇锤', '/\'pendjuləm, -dʒə- | \'pendjʊləm | \'pɛndʒələm/', 'pendulum', 6);
INSERT INTO `words` VALUES (14991, 'Countless mechanical equipment are adumbrative, in the future one day, we are in the murmur in penetralia , will as be in housetop proclaims aloud general.', 'n. 密室, 密事', '/,peni\'treiliə | ,penɪ\'treɪlɪə/', 'penetralia', 6);
INSERT INTO `words` VALUES (14992, 'bullets that penetrate thick armour plating', 'v. 穿透, 渗透, 看穿, 洞察', '/\'penitreit | \'penɪtreɪt | \'pɛnətret/', 'penetrate', 6);
INSERT INTO `words` VALUES (14993, 'questions that are intelligent and penetrating', 'adj. 敏锐的, 明察秋毫的, (指声音、喊叫等)尖锐的', '/\'penitreitiŋ | \'penɪtreɪtɪŋ | \'pɛnɪtretɪŋ/', 'penetrating', 6);
INSERT INTO `words` VALUES (14994, 'Cover the entire device to prevent water penetration.', 'n. 穿过, 渗透, 突破', '/,peni\'treiʃən | penɪ\'treɪʃ(ə)n | ,pɛnɪ\'treʃən/', 'penetration', 6);
INSERT INTO `words` VALUES (14995, 'I think we were fooled by penicillin.', 'n. 青霉素', '/ˌpenɪ\'sɪlɪn | ,pɛnɪ\'sɪlɪn/', 'penicillin', 6);
INSERT INTO `words` VALUES (14996, 'a penitent expression', 'adj. 悔过的', '/\'penitənt | \'penɪt(ə)nt | \'pɛnətənt/', 'penitent', 6);
INSERT INTO `words` VALUES (14997, 'the North Carolina state penitentiary', 'n. 监狱, 收容所, 教养所', '/,peni\'tenʃəri | ,penɪ\'tenʃ(ə)rɪ | ,pɛnɪ\'tɛnʃəri/', 'penitentiary', 6);
INSERT INTO `words` VALUES (14998, 'The second car was flying the Ghanaian pennant.', 'n. 细长三角旗, 短绳', '/\'penənt | \'pɛnənt/', 'pennant', 6);
INSERT INTO `words` VALUES (14999, 'At what age can you start drawing your pension ?', 'n. 养老金, 退休金', '/\'penʃən | \'penʃ(ə)n | \'pɛnʃən/', 'pension', 6);
INSERT INTO `words` VALUES (15000, 'Jan looked pensive.', 'adj. 沉思的', '/\'pensiv | \'pensɪv | \'pɛnsɪv/', 'pensive', 6);
INSERT INTO `words` VALUES (15001, 'Running it on a valid database file, like the penultimate command in Listing 4, gives a count of the records in the file.', 'n. 倒数第二音节', '/pi\'nʌltimit | peˈnʌltɪmət | pɪˈnʌltəmɪt/', 'penultimate', 6);
INSERT INTO `words` VALUES (15002, NULL, 'n. [天]（日蚀、月蚀或太阳黑子的）半影', '/pi\'nʌmbrə | pɪ\'nʌmbrə/', 'penumbra', 6);
INSERT INTO `words` VALUES (15003, 'Raised on a hog farm in Hunan Province, she laughs off the penurious ways of her parents and grandparents.', 'adj. 吝啬的, 缺乏的', '/pi\'njuəriəs | pɪ\'njʊərɪəs/', 'penurious', 6);
INSERT INTO `words` VALUES (15004, 'He died in penury in 1644.', 'n. 贫困, 贫穷', '/\'penjuri | \'penjʊrɪ | \'pɛnjəri/', 'penury', 6);
INSERT INTO `words` VALUES (15005, '...a crisp green salad with a few peppery radishes.', 'adj. 胡椒的, 辛辣的', '/\'pepəri | \'pep(ə)rɪ | \'pɛpəri/', 'peppery', 6);
INSERT INTO `words` VALUES (15006, 'The impressively named chief cells secrete pepsinogen which, when it mixes with stomach acid, becomes an enzyme called pepsin.', 'n. 胃蛋白酶, 胃液素', '/\'pepsin | \'pepsɪn | \'pɛpsɪn/', 'pepsin', 6);
INSERT INTO `words` VALUES (15007, 'As described above, antioxidants help prevent the destruction of cells in our body that can lead to cataracts, glaucoma, varicose veins, hemorrhoids, peptic ulcers, heart disease and cancer.', 'adj. 助消化的, 胃蛋白酶的', '/\'peptik | \'peptɪk | \'pɛptɪk/', 'peptic', 6);
INSERT INTO `words` VALUES (15008, 'According to traditions, the selectmen are required by law to perambulate the bounds every five years.', 'v. 巡行', '/pə\'ræmbjuleit | pə\'ræmbjʊleɪt/', 'perambulate', 6);
INSERT INTO `words` VALUES (15009, 'That morning, he perceived a change in Franca’s mood.', 'v. 察觉', '/pə\'si:v | pə\'siːv | pɚ\'siv/', 'perceive', 6);
INSERT INTO `words` VALUES (15010, 'a small but perceptible change', 'adj. 可察觉的, 显而易见的, 感觉得到的', '/pə\'septibl | pə\'septɪb(ə)l | pɚ\'sɛptəbl/', 'perceptible', 6);
INSERT INTO `words` VALUES (15011, 'He is interested in how our perceptions of death affect the way we live.', 'n. 理解感知,感觉DPS公司出的数字影像压缩卡', '/pə\'sepʃən | pə\'sepʃ(ə)n | pɚ\'sɛpʃən/', 'perception', 6);
INSERT INTO `words` VALUES (15012, 'He was one of the most perceptive U.S. political commentators.', 'adj. 有理解的', '/pə\'septiv | pə\'septɪv | pɚ\'sɛptɪv/', 'perceptive', 6);
INSERT INTO `words` VALUES (15013, 'She watched the parade from her perch on her father’s shoulders.', 'n. 栖木, 人所居的高位, 有利的地位, 杆, 河鲈', '/英[pɜːtʃ] 美[pɝtʃ] | pɜːtʃ | pɝtʃ/', 'perch', 6);
INSERT INTO `words` VALUES (15014, 'The Idea which is independent or for itself, when viewed on the point of this unity with itself, is Perception or Intuition, and the percipient Idea is Nature.', 'adj. 理解的', '/pə\'sipiənt | pə\'sɪpɪənt/', 'percipient', 6);
INSERT INTO `words` VALUES (15015, 'Rain water will only percolate through slowly.', 'n. 滤过之液体, 滤液', '/\'pə:kəleit | \'pɜːkəleɪt | \'pɝkəlet/', 'percolate', 6);
INSERT INTO `words` VALUES (15016, NULL, 'n. [音]打击乐器乐手,弹击乐器弹奏者', '/pə:\'kʌʃənist | pɜː\'kʌʃənɪst | pɚ\'kʌʃənɪst/', 'percussionist', 6);
INSERT INTO `words` VALUES (15017, 'His peregrinations took him to India.', 'n. 游历, 旅行', '/,periɡri\'neiʃən/', 'peregrination', 6);
INSERT INTO `words` VALUES (15018, 'I also have a feather from another species making a comeback against the odds, the peregrine falcon.', 'n. 隼', '/\'periɡrin, -ɡrain, -ɡri:n/', 'peregrine', 6);
