INSERT INTO `words` VALUES (15124, 'the phenomenal success of computer games in recent years', 'adj. 显著的， 非凡的', '/fə\'nɑːmɪnl/', 'phenomenal', 6);
INSERT INTO `words` VALUES (15125, 'I\'ve had people keep some of the ashes in a phial on a key-chain so they can keep their pet close to them.', 'n. 小玻璃瓶, 药瓶', '/\'faiəl | \'faɪəl/', 'phial', 6);
INSERT INTO `words` VALUES (15126, NULL, 'v. 追逐女人, 玩弄女性, 调情', '/fi\'lændə, fə- | fɪ\'lændə | fə\'lændɚ/', 'philander', 6);
INSERT INTO `words` VALUES (15127, 'Some of the best services for the seniors are sponsored by philanthropic organizations.', 'adj. 慈善的， 博爱的', '/fɪ\'lænθrəpik | ,fɪlən\'θrɑpɪk/', 'philanthropic', 6);
INSERT INTO `words` VALUES (15128, 'A philanthropist is someone who donates to charity. So Harper was admitting that he views \"the environment\" as a charity case.', 'n. 慈善家', '/fi\'lænθrəpist | fɪ\'lænθrəpɪst/', 'philanthropist', 6);
INSERT INTO `words` VALUES (15129, 'He is a philatelist; part of his collection is rare sets of postage stamps of the Qing Dynasty.', 'n. 集邮家', '/fi\'lætəlist | fɪ\'lætəlɪst/', 'philatelist', 6);
INSERT INTO `words` VALUES (15130, 'Varied ways and means of philately ii.', 'n. 集邮, 集邮的兴趣', '/fi\'lætəli | fɪ\'læt(ə)lɪ | fɪ\'lætəli/', 'philately', 6);
INSERT INTO `words` VALUES (15131, 'When it comes to art, the man’s a philistine.', 'n. (1)市侩；庸人(2)门外汉', '/\'filistain; fi\'listin | \'fɪlɪstin/', 'philistine', 6);
INSERT INTO `words` VALUES (15132, NULL, 'n. 对女人喜欢, 对女子的爱慕', '/fi\'lɔdʒəni, fə- | fɪ\'lɒdʒənɪ/', 'philogyny', 6);
INSERT INTO `words` VALUES (15133, 'I don\'t know the philology side, I don\'t know what disables to metaphysical questions.', 'n. 语言学, 文献学', '/fi\'lɔlədʒi, fə- | fɪ\'lɒlədʒɪ | fɪ\'lɑlədʒi/', 'philology', 6);
INSERT INTO `words` VALUES (15134, 'Further more the materialistic and dialectic viewpoints of mechanics are important philosophic ideas through the whole physics.', 'adj. 哲学的', '/ˌfɪlə\'sɑːfɪk | ,fɪlə\'sɑfɪkl/', 'philosophic', 6);
INSERT INTO `words` VALUES (15135, 'The taxi driver, a phlegmatic man in middle age, showed no surprise at this request.', 'adj. 冷静的,冷淡的', '/fleɡ\'mætik | fleg\'mætɪk | flɛɡ\'mætɪk/', 'phlegmatic', 6);
INSERT INTO `words` VALUES (15136, 'Some children suffer from school phobia .', 'n. 恐怖病, 恐怖症', '/\'fəubiə, -bjə | \'fəʊbɪə | \'fobɪə/', 'phobia', 6);
INSERT INTO `words` VALUES (15137, 'And let it direct your passion with reason, that your passion may live through its own daily resurrection, and like the phoenix rise above its own ashes.', 'n. 凤凰， 长生鸟', '/\'fiːnɪks | \'finɪks/', 'phoenix', 6);
INSERT INTO `words` VALUES (15138, 'a phonetic alphabet', 'adj. 语音的', '/fə\'netɪk | fə\'nɛtɪk/', 'phonetic', 6);
INSERT INTO `words` VALUES (15139, 'He\'d telephoned with some phony excuse she didn\'t believe for a minute.', 'adj. 假冒的', '/\'fəuni | \'fəʊnɪ | \'foni/', 'phony', 6);
INSERT INTO `words` VALUES (15140, 'Because scientists have found a bacterium that can do without phosphorus—live on arsenic instead.', 'n. 磷', '/\'fɔsfərəs | \'fɒsf(ə)rəs | \'fɑsfərəs/', 'phosphorus', 6);
INSERT INTO `words` VALUES (15141, NULL, 'adj. [生]喜光的,嗜光的,适光的', '/fəʊ\'tɒfɪləs | fəu\'tɔfiləs/', 'photophilous', 6);
INSERT INTO `words` VALUES (15142, 'photosensitive paper', 'adj. 感光性的', '/ˌfoutou\'sensətɪv | ,foto\'sɛnsətɪv/', 'photosensitive', 6);
INSERT INTO `words` VALUES (15143, 'It has at least one gene necessary for photosynthesis—so far it’s the only animal known with this ability.', 'n. 光合作用', '/,fəutə\'sinθəsis | ,fəʊtə(ʊ)\'sɪnθɪsɪs | ,foto\'sɪnθəsɪs/', 'photosynthesis', 6);
INSERT INTO `words` VALUES (15144, 'Who first used the phrase ‘survival of the fittest’?', 'n. 短语, 习语, 惯用语, 成语, 措词', '/freiz | freɪz | frez/', 'phrase', 6);
INSERT INTO `words` VALUES (15145, 'She was in constant physical pain.', 'adj. 实质的， 有形的； 身体的， 肉体的', '/\'fɪzɪkl/', 'physical', 6);
INSERT INTO `words` VALUES (15146, 'He was fascinated by her physiognomy – the prominent nose, brooding eyes, and thick hair.', 'n. 人相学, 人相, 脸, 相面术, 相貌, 地貌, 地势', '/,fizi\'ɔɡnəmi | ,fɪzɪ\'ɒ(g)nəmɪ | \'fɪzɪ\'ɑnəmi/', 'physiognomy', 6);
INSERT INTO `words` VALUES (15147, 'If so, this would add to a growing list of physiological and biological markers of sexual orientation.', 'adj. 生理的； 生理学的', '/ˌfɪziə\'lɑːdʒɪkl | ,fɪzɪə\'lɑdʒɪkl/', 'physiological', 6);
INSERT INTO `words` VALUES (15148, 'She didn’t have the physique to be a dancer.', 'n. (男子的)体格, 体形', '/fi\'zi:k | fɪ\'ziːk | fɪ\'zik/', 'physique', 6);
INSERT INTO `words` VALUES (15149, 'Jean accompanied her on the piano .', 'n. 钢琴', '/pi\'ænəu, pi\'ɑ:- | pɪ\'ænəʊ | pɪ\'æno/', 'piano', 6);
INSERT INTO `words` VALUES (15150, '...a piazza dotted with fountains.', 'n. 广场, 走廊, 露天市场', '/pi\'ætsə | pɪ\'ætsə | pɪ\'ɑzə/', 'piazza', 6);
