INSERT INTO `words` VALUES (15153, 'a pictorial record of their journey', 'adj. 绘画的； 用图片的', '/pɪk\'tɔːriəl | pɪk\'tɔrɪəl/', 'pictorial', 6);
INSERT INTO `words` VALUES (15154, 'a quiet fishing village with a picturesque harbour', 'adj. 如画的； 独特的， 别具风格的', '/ˌpɪktʃə\'resk | ,pɪktʃə\'rɛsk/', 'picturesque', 6);
INSERT INTO `words` VALUES (15155, NULL, 'v. 撒尿, 鬼混, 游荡', '/\'pidl | \'pɪd(ə)l | \'pɪdl/', 'piddle', 6);
INSERT INTO `words` VALUES (15156, '...arguing over piddling amounts of money.', 'adj. 琐碎的， 微不足道的', '/\'pɪdlɪŋ/', 'piddling', 6);
INSERT INTO `words` VALUES (15157, 'a piebald horse', 'adj. 花斑的， 黑白两色的', '/\'paɪbɔːld | \'paɪbɔld/', 'piebald', 6);
INSERT INTO `words` VALUES (15158, 'The buildings have been adapted in a piecemeal fashion .', 'adj. 一件一件的， 零碎的', '/\'piːsmiːl | \'pismil/', 'piecemeal', 6);
