INSERT INTO `words` VALUES (15160, 'a yacht moored at a pier', 'n. 码头, (桥)墩', '/piə | pɪə | pɪr/', 'pier', 6);
INSERT INTO `words` VALUES (15161, 'Steam the corn until it can easily be pierced with a fork.', 'v. 刺穿, 刺破, 穿透, 突破, 深深感动', '/piəs | pɪəs | pɪrs/', 'pierce', 6);
INSERT INTO `words` VALUES (15162, 'He grinned and let out a piercing whistle.', 'adj. 刺骨的, 刺穿的', '/\'piəsiŋ | \'pɪəsɪŋ | \'pɪrsɪŋ/', 'piercing', 6);
INSERT INTO `words` VALUES (15163, 'an act of Christian piety', 'n. 虔诚, 孝行', '/\'paiəti | \'paɪətɪ | \'paɪəti/', 'piety', 6);
INSERT INTO `words` VALUES (15164, 'Melanin is the dark brown pigment of the hair, skin and eyes.', 'n. [生]色素, 颜料', '/\'piɡmənt | \'pɪgm(ə)nt | \'pɪgmənt/', 'pigment', 6);
INSERT INTO `words` VALUES (15165, NULL, 'n. 猪舍, 脏房子', '/\'piɡstai | \'pɪgstaɪ | \'pɪɡstaɪ/', 'pigsty', 6);
INSERT INTO `words` VALUES (15166, 'The staff were pilfering behind the bar.', 'v. 盗, 偷, 窃', '/\'pilfə | \'pɪlfə/', 'pilfer', 6);
INSERT INTO `words` VALUES (15167, 'pilgrims visiting a holy shrine', 'n. 圣地朝拜者, 朝圣', '/\'pilɡrim | \'pɪlgrɪm | \'pɪlɡrɪm/', 'pilgrim', 6);
INSERT INTO `words` VALUES (15168, 'Soldiers went on a rampage, pillaging stores and shooting.', 'v. 掠夺', '/\'pilidʒ | \'pɪlɪdʒ/', 'pillage', 6);
INSERT INTO `words` VALUES (15169, NULL, 'n. （古刑具）颈手枷, 示众', '/\'piləri | \'pɪlərɪ | \'pɪləri/', 'pillory', 6);
INSERT INTO `words` VALUES (15170, 'an airline pilot', 'n. 飞行员； 领航员', '/\'paɪlət/', 'pilot', 6);
INSERT INTO `words` VALUES (15171, 'Compulsory pilotage, but no port communication station.', 'n. 领港', '/\'paɪlətɪdʒ/', 'pilotage', 6);
INSERT INTO `words` VALUES (15172, 'Crabs have two sharp and large pincers.', 'n. 钳子, 螯', '/\'pɪnsəz | \'pinsəz/', 'pincers', 6);
INSERT INTO `words` VALUES (15173, 'She gave him a playful pinch.', 'n. 捏, 撮, 收缩, 紧急关头, 匮乏, 压力', '/pintʃ | pɪn(t)ʃ | pɪntʃ/', 'pinch', 6);
INSERT INTO `words` VALUES (15174, 'an ancient pine forest', 'n. 松树, 树木', '/pain | paɪn/', 'pine', 6);
INSERT INTO `words` VALUES (15175, 'From the mightiest lever to the tiniest pinion', 'n. 小齿轮', '/\'pinjən | \'pɪnjən/', 'pinion', 6);
INSERT INTO `words` VALUES (15176, 'He pushes his glasses up his nose with his pinkie.', 'n. <口>小手指', '/\'piŋki | \'pɪŋkɪ/', 'pinkie', 6);
INSERT INTO `words` VALUES (15177, 'the pinnacle of academic achievement', 'n. 小尖塔, 山顶, 顶点', '/\'pinəkl | \'pɪnək(ə)l | \'pɪnəkl/', 'pinnacle', 6);
INSERT INTO `words` VALUES (15178, 'Rescue teams have now pinpointed the location of the ship.', 'v. 准确地确定；使突出，引起注意; adj. 极精确的', '/\'pɪnpɔɪnt/', 'pinpoint', 6);
INSERT INTO `words` VALUES (15179, 'He was a quiet, pious man.', 'adj. 虔诚的', '/\'paɪəs/', 'pious', 6);
INSERT INTO `words` VALUES (15180, NULL, 'n. 虔诚', '/\'paɪəsnəs/', 'piousness', 6);
INSERT INTO `words` VALUES (15181, 'a piquant wild mushroom sauce', 'adj. 开胃的, 辛辣的, 泼辣的, 兴奋的, 顽皮的, 淘气的', '/\'pi:kənt, pi- | \'piːk(ə)nt; -kɒnt | \'pikənt/', 'piquant', 6);
INSERT INTO `words` VALUES (15182, 'He stormed out in a fit of pique .', 'n. 不满, 生气, 愤怒', '/pi:k | piːk | pik/', 'pique', 6);
INSERT INTO `words` VALUES (15183, 'software piracy', 'n. 海盗行为, 侵犯版权, 非法翻印盗版', '/\'paiərəsi | \'paɪrəsɪ | \'paɪrəsi/', 'piracy', 6);
INSERT INTO `words` VALUES (15184, 'Computer game pirates cost the industry twenty million pounds a year.', 'n. 海盗, 盗印者, 盗版者, 侵犯专利权者', '/\'paɪrɪt | ˈpaɪərət | \'paɪrət/', 'pirate', 6);
INSERT INTO `words` VALUES (15185, 'He gotta go pole the pirogue down the bayou.', 'n. 独木舟', '/pi\'rəuɡ, \'pi:rəuɡ | pɪ\'rəʊg | \'piroɡ/', 'pirogue', 6);
INSERT INTO `words` VALUES (15186, 'To picture this, imagine an ice skater doing a pirouette.', 'n. 脚尖旋转', '/,piru\'et | ,pɪrʊ\'et | ,pɪru\'ɛt/', 'pirouette', 6);
INSERT INTO `words` VALUES (15187, 'In market economy moving mechanism falls, those who opened piscatorial resource development to use a climax is prelusive.', 'adj. 渔业的, 渔民的', '/,piskə\'tɔ:riəl | ,pɪskə\'tɔːrɪəl | ,pɪskə\'tɔriəl/', 'piscatorial', 6);
INSERT INTO `words` VALUES (15188, 'The officer buckled on his pistol.', 'n. 手枪', '/\'pistl | \'pɪst(ə)l | \'pɪstl/', 'pistol', 6);
INSERT INTO `words` VALUES (15189, 'His first pitch was high and wide.', 'n. 程度, 斜度, 树脂, 投掷, 定调, (船只)前后颠簸, 倾斜, 沥青', '/pɪtʃ/', 'pitch', 6);
INSERT INTO `words` VALUES (15190, 'a pitcher of water', 'n. (带柄和倾口的)大水罐, (棒球)投手', '/\'pitʃə | \'pɪtʃə | \'pɪtʃɚ/', 'pitcher', 6);
INSERT INTO `words` VALUES (15191, 'She gave a long piteous cry.', 'adj. 可怜的', '/\'pɪtiəs | \'pɪtɪəs/', 'piteous', 6);
INSERT INTO `words` VALUES (15192, 'the pitfalls associated with the purchase of a used car', 'n. 缺陷', '/\'pitfɔ:l | \'pɪtfɔːl | \'pɪt\'fɔl/', 'pitfall', 6);
INSERT INTO `words` VALUES (15193, 'Even oranges don\'t eat the whole peel, but keep the pith , that white stringy stuff; it\'s packed with flavonoids.', 'n. (植物的)木髓, 骨髓, 重要部分, 核心, 意义, 精华, 精力', '/piθ | pɪθ/', 'pith', 6);
INSERT INTO `words` VALUES (15194, 'Her work is known for pithiness of style.', 'n. 简洁', '/\'piθinis | \'pɪθɪnəs/', 'pithiness', 6);
INSERT INTO `words` VALUES (15195, 'Press releases must be short and pithy.', 'adj. 有髓的, 精练的', '/\'piθi | \'pɪθɪ | \'pɪθi/', 'pithy', 6);
INSERT INTO `words` VALUES (15196, 'The refugees were a pitiful sight .', 'adj. 值得同情的， 可怜的', '/\'pɪtɪfl | \'pɪtɪfəl/', 'pitiful', 6);
INSERT INTO `words` VALUES (15197, 'a pitiless tyrant', 'adj. 无情的， 冷酷的， 无同情心的', '/\'pɪtiləs | \'pitilis/', 'pitiless', 6);
INSERT INTO `words` VALUES (15198, 'She raised three children on a pittance.', 'n. 少量, 微薄的薪俸', '/\'pitəns | \'pɪt(ə)ns | \'pɪtns/', 'pittance', 6);
INSERT INTO `words` VALUES (15199, 'Instead, the team discovered that the pituitary does not lose its ability to respond to insulin.', 'n. [解]垂体', '/pi\'tju:itəri | pɪ\'tjuːɪt(ə)rɪ | pɪ\'tuətɛri/', 'pituitary', 6);
INSERT INTO `words` VALUES (15200, 'Forming the pivot of the exhibition is a large group of watercolours.', 'n. 枢轴, 支点, (讨论的)中心点, 重点', '/\'pivət | \'pɪvət/', 'pivot', 6);
INSERT INTO `words` VALUES (15201, 'The Bank of England has a pivotal role in the London money market.', 'adj. 中枢的， 枢轴的； 极其重要的， 关键的', '/\'pɪvətl/', 'pivotal', 6);
INSERT INTO `words` VALUES (15202, 'A long placard bore the names of all the new recruits.', 'v. 张贴布告; n. 招贴，布告', '/\'plækɑːrd | \'plækɑrd/', 'placard', 6);
INSERT INTO `words` VALUES (15203, 'These changes did little to placate the unions.', 'v. 安抚', '/plə\'keit, \'pleikeit, \'plæ- | plə\'keɪt; \'plækeɪt; \'pleɪ- | \'pleket/', 'placate', 6);
INSERT INTO `words` VALUES (15204, 'Or it could be that the needles caused a “super placebo” effect, triggering a real reaction in the brain that changes the way the body perceives and responds to pain.', 'n. 为死者所诵的晚祷词, 安慰剂', '/plə\'si:bəu | plə\'siːbəʊ | plə\'sibo/', 'placebo', 6);
INSERT INTO `words` VALUES (15205, 'a large, placid baby', 'adj. 平静的', '/\'plæsid | \'plæsɪd/', 'placid', 6);
INSERT INTO `words` VALUES (15206, 'The journal accused the professor of plagiarism.', 'n. 剽窃, 剽窃物', '/\'pleidʒjərizəm | \'pleɪdʒərɪz(ə)m | \'pledʒə\'rɪzəm/', 'plagiarism', 6);
INSERT INTO `words` VALUES (15207, 'He accused other scientists of plagiarizing his research.', 'v. 剽窃， 抄袭 and use them as if they were one\'s own)', '/\'pleɪdʒəraɪz | \'pledʒə\'raɪz/', 'plagiarize', 6);
INSERT INTO `words` VALUES (15208, 'drops in population levels due to plagues and famines', 'n. 瘟疫, 麻烦, 苦恼, 灾祸', '/pleiɡ | pleɪg | pleɡ/', 'plague', 6);
INSERT INTO `words` VALUES (15209, 'The advantages were plain to see.', 'adj. 简单的；清楚的；不漂亮的，不好看的; n. 平原', '/pleɪn | plen/', 'plain', 6);
INSERT INTO `words` VALUES (15210, 'a straightforward, plainspoken man', 'adj. 直言不讳的', '/\'plein\'spəukən | \'pleɪn\'spoukən/', 'plainspoken', 6);
INSERT INTO `words` VALUES (15211, 'The lead plaintiff of the lawsuit is the University of California.', 'n. [律]起诉人, 原告', '/\'pleintif | \'pleɪntɪf | \'plentɪf/', 'plaintiff', 6);
INSERT INTO `words` VALUES (15212, 'They lay on the firm sands, listening to the plaintive cry of the seagulls.', 'adj. 悲哀的, 哀伤的', '/\'pleintiv | \'pleɪntɪv | \'plentɪv/', 'plaintive', 6);
INSERT INTO `words` VALUES (15213, '...a short, energetic woman with her hair in plaits.', 'n. 辫子', '/plæt, pleit | plæt | plet, plæt/', 'plait', 6);
INSERT INTO `words` VALUES (15214, 'It is a big airline with a large fleet of planes.', 'n. 平面, 飞机, 水平, 程度, 刨', '/plein | pleɪn | plen/', 'plane', 6);
INSERT INTO `words` VALUES (15215, 'the plangent sound of the violin', 'adj. 轰鸣的, 凄切的', '/\'plændʒənt | \'plæn(d)ʒ(ə)nt/', 'plangent', 6);
INSERT INTO `words` VALUES (15216, 'a long plank of wood', 'n. 厚木板, 支架, (政党的)政纲条款', '/plæŋk/', 'plank', 6);
INSERT INTO `words` VALUES (15217, '...its usual diet of plankton and other small organisms.', 'n. 浮游生物', '/\'plæŋktən | \'plæŋ(k)t(ə)n; -tɒn/', 'plankton', 6);
INSERT INTO `words` VALUES (15218, 'The team’s coach was given a plaque.', 'n. 装在墙上作装饰或纪念用的薄金属板或瓷片', '/plɑ:k, plæk | plæk; plɑːk | plæk/', 'plaque', 6);
INSERT INTO `words` VALUES (15219, 'There were huge cracks in the plaster, and the green shutters were faded.', 'n. 石膏, 灰泥, 膏药, 橡皮膏', '/\'plɑ:stə, \'plæs- | \'plɑːstə | \'plæstɚ/', 'plaster', 6);
INSERT INTO `words` VALUES (15220, 'Chris was plastered after five beers.', 'adj. 醉醺醺的', '/\'plɑ:stəd, \'plæs- | \'plɑːstəd | \'plæstɚd/', 'plastered', 6);
INSERT INTO `words` VALUES (15221, 'children’s toys made of plastic', 'n. 塑胶, 可塑体, 塑料制品, 整形', '/\'plæstik,\'plɑ:s- | \'plæstɪk/', 'plastic', 6);
INSERT INTO `words` VALUES (15222, 'This kind of plasticity may play a vital role in evolution as well as during the lifetime of individuals.', 'n. 可塑性, 塑性', '/plæs\'tisiti | plæ\'stɪsɪtɪ | plæ\'stɪsəti/', 'plasticity', 6);
INSERT INTO `words` VALUES (15223, 'Inflation rates have reached a plateau.', 'n. 高地, 高原(上升后的)稳定水平(或时期、状态)', '/\'plætəʊ | plæ\'to/', 'plateau', 6);
INSERT INTO `words` VALUES (15224, 'His excuse was the platitude ‘boys will be boys.’', 'n. 陈词滥调', '/\'plætitju:d | \'plætɪtjuːd | \'plætɪtud/', 'platitude', 6);
INSERT INTO `words` VALUES (15225, 'It has lived because readers appreciate a refreshing stimulus, an irreverent reminder that they live in a world of platitudinous thinking, cheap moralizing, and foolish philosophy.', 'adj. 陈腐的', '/,plæti\'tju:dinəs | ˌplætɪ\'tuːdənəs/', 'platitudinous', 6);
INSERT INTO `words` VALUES (15226, 'She values the platonic friendship she has had with Chris for ten years.', 'adj. 柏拉图哲学的, 柏拉图主义的, 理想的, 不切实际的', '/plə\'tɔnik, plei-/', 'platonic', 6);
INSERT INTO `words` VALUES (15227, NULL, 'v. 喝彩， 赞扬', '/\'plɔːdɪt | \'plɔ:dit/', 'plaudit', 6);
INSERT INTO `words` VALUES (15228, 'His story certainly sounds plausible.', 'adj. 似是而非的', '/\'plɔ:zəble | \'plɔːzɪb(ə)l | \'plɔzəbl/', 'plausible', 6);
INSERT INTO `words` VALUES (15229, 'The playwright does something remarkable in this scene, but without any impression of straining after an effect.', 'n. 剧作家', '/\'pleirait | \'pleɪraɪt | \'pleraɪt/', 'playwright', 6);
INSERT INTO `words` VALUES (15230, 'Across the busy plaza, vendors sell hot dogs and croissant sandwiches.', 'n. 广场, 露天汽车停车场, 购物中心', '/\'plɑ:zə | \'plɑːzə | \'plæzə/', 'plaza', 6);
INSERT INTO `words` VALUES (15231, '‘Don’t go!’ Robert pleaded.', 'v. 辩护, 恳求', '/pli:d | pliːd | plid/', 'plead', 6);
INSERT INTO `words` VALUES (15232, 'Her skirt hangs in perfect wide pleats.', 'n. 褶, 褶状物', '/pli:t | pliːt | plit/', 'pleat', 6);
INSERT INTO `words` VALUES (15233, 'This displacement, which places the \"elegant\" name on the plebeian and the rustic name on the aristocrat, is nothing else than an eddy of equality.', 'n. 平民, 庶民', '/pli\'bi:jən, plə | plɪ\'biːən | plə\'biən/', 'plebeian', 6);
INSERT INTO `words` VALUES (15234, 'Employees were pledged to secrecy .', 'v. 发誓; n. 誓言，保证', '/pledʒ | plɛdʒ/', 'pledge', 6);
INSERT INTO `words` VALUES (15235, 'The conference ended with a plenary debate.', 'adj. 全体出席的； 完全的， 绝对的， 无限的', '/\'pliːnəri | \'plɛnəri/', 'plenary', 6);
INSERT INTO `words` VALUES (15236, 'Life breeds both plenitude and void, exuberance and depression.', 'n. 充分', '/\'plenitju:d | \'plenɪtjuːd | \'plɛnɪtud/', 'plenitude', 6);
INSERT INTO `words` VALUES (15237, NULL, 'n. 充分', '/\'pl3ntɪtʊːd | \'plentitju:d/', 'plentitude', 6);
INSERT INTO `words` VALUES (15238, NULL, 'n. 充实, 充满, 全体会议, 高压', '/\'pli:nəm, \'ple- | \'pliːnəm | \'plinəm/', 'plenum', 6);
INSERT INTO `words` VALUES (15239, NULL, 'adj. 冗言的, 重复的', '/,pli:ə\'næstik/', 'pleonastic', 6);
INSERT INTO `words` VALUES (15240, 'A plethora of new operators will be allowed to enter the market.', 'n. 过剩, 过多, 多血症', '/\'pleθərə | \'pleθ(ə)rə | \'plɛθərə/', 'plethora', 6);
INSERT INTO `words` VALUES (15241, 'a shoe made of soft pliable leather', 'adj. 易曲折的, 柔软的, 圆滑的, 柔韧的', '/\'plaiəbl | \'plaɪəb(ə)l | \'plaɪəbl/', 'pliable', 6);
INSERT INTO `words` VALUES (15242, 'Only flow .... The power is IN the flow, and each drop of water is pliant and soft.', 'n. 顺从', '/\'plaiənt | \'plaɪənt/', 'pliant', 6);
INSERT INTO `words` VALUES (15243, 'a pair of pliers', 'n. 钳子, 老虎钳', '/\'plaiəz | \'plaɪəz | \'plaɪɚz/', 'pliers', 6);
INSERT INTO `words` VALUES (15244, NULL, 'n. 柱基, 方形底座', '/plinθ | plɪnθ/', 'plinth', 6);
INSERT INTO `words` VALUES (15245, 'No, there aren’t, so in all likelihood I will have to plod across those green meadows with a herd of American tourists, disgruntled that everything is so ancient and small.', 'n. 沉重的脚步', '/plɔd | plɒd | plɑd/', 'plod', 6);
INSERT INTO `words` VALUES (15246, 'The minister was found guilty of plotting the downfall of the government.', 'v. 密谋， 策划; n. 情节；阴谋', '/plɑːt | plɑt/', 'plot', 6);
INSERT INTO `words` VALUES (15247, 'In those days the land was plowed by oxen.', 'v. 犁地; n. 犁', '/plau | plaʊ/', 'plough', 6);
INSERT INTO `words` VALUES (15248, 'Christmas should be a time of excitement and wonder, not a cynical marketing ploy.', 'n. 策略, 趣味, 工作', '/plɔi | plɒɪ | plɔɪ/', 'ploy', 6);
INSERT INTO `words` VALUES (15249, 'It takes a lot of pluck to stand up to a bully.', 'n. 勇气', '/plʌk/', 'pluck', 6);
INSERT INTO `words` VALUES (15250, 'the parrot’s brilliant blue plumage', 'n. 鸟类羽毛, 翅膀', '/\'plu:midʒ | \'pluːmɪdʒ | \'plumɪdʒ/', 'plumage', 6);
INSERT INTO `words` VALUES (15251, 'The bullet hit him plumb between the eyes.', 'n. 铅锤, 铅弹', '/plʌm/', 'plumb', 6);
INSERT INTO `words` VALUES (15252, 'The plumber lost his kit on the way home.', 'n. 管子工， 铅管工', '/\'plʌmər | \'plʌmɚ/', 'plumber', 6);
INSERT INTO `words` VALUES (15253, '...broad straw hats decorated with ostrich plumes.', 'n. 羽毛', '/plu:m | pluːm | plum/', 'plume', 6);
INSERT INTO `words` VALUES (15254, 'The plane plummeted towards the Earth.', 'n. 铅锤, 重荷', '/\'plʌmɪt/', 'plummet', 6);
INSERT INTO `words` VALUES (15255, 'The nurse was a cheerful plump woman.', 'adj. 圆胖的, 丰满的, 鼓起的', '/plʌmp/', 'plump', 6);
INSERT INTO `words` VALUES (15256, NULL, 'adj. 丰满的', '/\'plʌmpi/', 'plumpy', 6);
INSERT INTO `words` VALUES (15257, NULL, 'n. 幼芽, 棉毛', '/\'plu:mju:l | \'pluːmjuːl | \'plʊmjʊl/', 'plumule', 6);
INSERT INTO `words` VALUES (15258, 'The rich provinces of Asia Minor were plundered by the invaders.', 'v. 抢劫', '/\'plʌndə | \'plʌndɚ/', 'plunder', 6);
INSERT INTO `words` VALUES (15259, 'At least 50 people died when a bus plunged into a river.', 'v. 跳进， 陷入； 俯冲', '/plʌndʒ/', 'plunge', 6);
INSERT INTO `words` VALUES (15260, NULL, 'n. 兼任数个宗教职位者， 兼职者', '/\'plurəlɪst | \'pluərəlist/', 'pluralist', 6);
INSERT INTO `words` VALUES (15261, 'plush curtains', 'n. 长毛绒', '/plʌʃ/', 'plush', 6);
INSERT INTO `words` VALUES (15262, 'Financial plutocracy must give way to financial democracy – banking as if people mattered.', 'n. 富豪统治', '/plu:\'tɔkrəsi | pluː\'tɒkrəsɪ | plu\'tɑkrəsi/', 'plutocracy', 6);
INSERT INTO `words` VALUES (15263, 'pluvial insurance', 'adj. 雨的, 有雨的, 多雨的, 洪水的', '/\'pluːvɪəl | \'plʊvɪəl/', 'pluvial', 6);
INSERT INTO `words` VALUES (15264, 'a sweater in four-ply yarn', 'n. 厚度, 板层, 褶', '/plai | plaɪ/', 'ply', 6);
INSERT INTO `words` VALUES (15265, 'pneumatic tyres', 'adj. 装满空气的, 有气胎的, 汽力的, 风力的, 灵魂的', '/nju:\'mætik | njuː\'mætɪk | numætɪk/', 'pneumatic', 6);
INSERT INTO `words` VALUES (15266, 'She was taken to hospital, suffering from pneumonia.', 'n. [医] 肺炎', '/nju:\'məunjə | njuː\'məʊnɪə | nʊ\'monɪə/', 'pneumonia', 6);
INSERT INTO `words` VALUES (15267, 'Deer have been poached here for years.', 'v. 偷猎， 窃取', '/poutʃ | potʃ/', 'poach', 6);
INSERT INTO `words` VALUES (15268, NULL, 'adj. 冷漠的的, 漠不关心的', '/\'pəʊkəʊkjʊ\'ræntɪ | ,pokokʊ\'rænti/', 'pococurante', 6);
INSERT INTO `words` VALUES (15269, 'a pea pod', 'n. 密集小群, 扁豆层, 豆荚, 蚕茧', '/pɔd | pɒd | pɑd/', 'pod', 6);
INSERT INTO `words` VALUES (15270, 'He put a podgy arm round Harry\'s shoulder.', 'adj. 矮胖的, 短粗的', '/\'pɔdʒi | \'pɒdʒɪ | \'pɑdʒi/', 'podgy', 6);
INSERT INTO `words` VALUES (15271, NULL, 'n. 足病医生', '/pə\'daɪətrɪst/', 'podiatrist', 6);
INSERT INTO `words` VALUES (15272, NULL, 'n. 脚病学', '/pəu\'daiətri | pə(ʊ)\'daɪətrɪ | pə\'daɪətri/', 'podiatry', 6);
INSERT INTO `words` VALUES (15273, 'Unsteadily he mounted the podium, adjusted the microphone, coughed, and went completely blank.', 'n. 乐队指挥台, 墩座墙', '/\'pəudjəm | \'pəʊdɪəm | \'podɪəm/', 'podium', 6);
INSERT INTO `words` VALUES (15274, NULL, 'n. 打油诗人, 劣等诗人', '/,pəʊɪ\'tæstə | \'poɪ,tæstɚ/', 'poetaster', 6);
INSERT INTO `words` VALUES (15275, 'Street-fighting in Osh, the largest city in southern Kyrgyzstan, between ethnic Kyrgyz and minority Uzbeks escalated rapidly into a pogrom.', 'n. (尤指沙俄时对犹太人的) 大屠杀', '/\'pɔɡrəm, pəu\'ɡrɔm | \'pɒgrəm; \'pɒgrɒm | \'poɡrəm/', 'pogrom', 6);
INSERT INTO `words` VALUES (15276, 'The film contains moments of almost unbearable poignancy.', 'n. 辛酸(事) 强烈, 尖刻, 辛辣', '/\'pɔinjənsi, \'pɔiɡnənsi | \'pɔɪɡnənsi/', 'poignancy', 6);
INSERT INTO `words` VALUES (15277, '...a poignant combination of beautiful surroundings and tragic history.', 'adj. 令人痛苦的, (味觉、嗅觉方面)刺激的、辛辣的, 尖锐的, 剧烈的', '/\'pɔinjənt, \'pɔiɡnənt | \'pɒɪnjənt | \'pɔɪnjənt/', 'poignant', 6);
INSERT INTO `words` VALUES (15278, 'The pointer was between 35 and 40 pounds.', 'n. 指示器', '/\'pɔintə | \'pɒɪntə | \'pɔɪntɚ/', 'pointer', 6);
INSERT INTO `words` VALUES (15279, 'What amazed him even more than her appearance was her poise.', 'n. 平衡, 均衡, 姿势, 镇静, 砝码', '/pɔiz | pɒɪz | pɔɪz/', 'poise', 6);
INSERT INTO `words` VALUES (15280, 'Some mushrooms are extremely poisonous.', 'adj. 有毒的； 有害的', '/\'pɔɪzənəs/', 'poisonous', 6);
INSERT INTO `words` VALUES (15281, 'John smiled at them and gave Richard a playful poke.', 'n. 刺, 戳, 懒汉, 袋子', '/pəuk | pəʊk | pok/', 'poke', 6);
INSERT INTO `words` VALUES (15282, 'As our climate warms up, the polar ice caps will begin to melt.', 'adj. 极地的， 两极的， 近地极的； 磁极的', '/\'poulər | \'polɚ/', 'polar', 6);
INSERT INTO `words` VALUES (15283, 'Whether you want to call it magnetism, polarity,electricity, thought, intelligence or charisma, it\'s still attraction, and it invests everything—animal, vegetable or mineral.', 'n. 极性', '/pəu\'lærəti | pə(ʊ)\'lærɪtɪ | pə\'lærəti/', 'polarity', 6);
INSERT INTO `words` VALUES (15284, NULL, 'n. [物]偏振(现象),极化(作用),两极化,分化', '/,pəulərai\'zeiʃən, -ri\'z- | ,pəʊləraɪ\'zeɪʃən | ,polərɪ\'zeʃən/', 'polarization', 6);
INSERT INTO `words` VALUES (15285, 'The issue has polarized the country.', 'v. 两极化， 截然对立', '/\'pouləraɪz | \'polə\'raɪz/', 'polarize', 6);
INSERT INTO `words` VALUES (15286, 'You can compare it to the visual arts, to painting, to drawing; it can document reality, like still photographs. It can explain and record like journalism, and it can be a polemic, like a pamphlet.', 'adj. 争论的', '/pɔ\'lemik, pə- | pə\'lemɪk | pə\'lɛmɪk/', 'polemic', 6);
INSERT INTO `words` VALUES (15287, 'The reforms were attacked in a highly polemical piece in the ‘New Yorker’.', 'adj. 辩论法, 辩论术, 好辩的, 挑起争端的', '/pə\'lemikəl | pə\'lɛmɪkl/', 'polemical', 6);
INSERT INTO `words` VALUES (15288, 'An occasional polish will keep wall tiles looking good.', 'n. 磨光, 光泽, 上光剂, 优雅, 精良', '/\'pɒlɪʃ | \'pɑlɪʃ/', 'polish', 6);
INSERT INTO `words` VALUES (15289, 'Everyone around him was trying to be polite, but you could tell they were all bored.', 'adj. 文雅的， 有教养的', '/pə\'laɪt/', 'polite', 6);
INSERT INTO `words` VALUES (15290, 'Women were becoming more politically active.', 'adv. 政治上', '/pə\'lɪtɪkli/', 'politically', 6);
INSERT INTO `words` VALUES (15291, 'A recent poll found that 80% of Californians support the governor.', 'n. 民意调查； 投票选举', '/poul | pol/', 'poll', 6);
INSERT INTO `words` VALUES (15292, 'So how do you train them to respond to TNT the way they respond to pollen?', 'n. 花粉', '/\'pɔlin | \'pɒlən | \'pɑlən/', 'pollen', 6);
INSERT INTO `words` VALUES (15293, 'flowers pollinated by bees', 'v. 对…授粉', '/\'pɑːləneɪt | \'pɑlənet/', 'pollinate', 6);
INSERT INTO `words` VALUES (15294, 'Celinda Lake, an opinion pollster in Washington DC who carries out work for the Democrats, has a thumbnail sketch of that swing female voter.', 'n. 民意测验专家, 整理民意测验结果的人', '/\'pəulstə | \'pəʊlstə | \'polstɚ/', 'pollster', 6);
INSERT INTO `words` VALUES (15295, NULL, 'n. 胆小鬼', '/pɔl\'tru:n | pɒl\'truːn | pɑl\'trun/', 'poltroon', 6);
INSERT INTO `words` VALUES (15296, 'They practice what is known as fraternal polyandry -- where the brothers of one family marry the same woman.', 'n. 一妻多夫, [植]多雄蕊', '/\'pɔliændri, ,pɔli\'æ- | \'pɒlɪændrɪ | ,pɑlɪ\'ændri/', 'polyandry', 6);
INSERT INTO `words` VALUES (15297, 'In endorsing polygamy, these women, particularly those in remote rural areas without running water, may be less concerned with loneliness than with something more pragmatic: help with the chores.', 'n. 一夫多妻, 一妻多夫', '/pɔ\'liɡəmi | pə\'lɪgəmɪ | pə\'lɪɡəmi/', 'polygamy', 6);
INSERT INTO `words` VALUES (15298, 'a polyglot population', 'adj. 通晓数种语言, 数种语言的', '/\'pɔliɡlɔt | \'pɒlɪglɒt | \'pɑlɪɡlɑt/', 'polyglot', 6);
INSERT INTO `words` VALUES (15299, 'If Charles I owned a real Leonardo before he was executed in 1649, this means our national love affair with the Renaissance polymath has been going on for almost 400 years.', 'n. 博学者', '/\'pɔlimæθ | \'pɒlɪmæθ | ˈpɑːlimæθ/', 'polymath', 6);
INSERT INTO `words` VALUES (15300, 'Every linguistic category is a polysemous category, or it is one that contains several potential senses.', 'adj. [语]一词多义的,多义的', '/,pɔli\'si:məs/', 'polysemous', 6);
INSERT INTO `words` VALUES (15301, 'The Queen’s birthday was celebrated with great pomp and ceremony .', 'n. 壮丽, 盛况, 夸耀', '/pɔmp | pɒmp | pɑmp/', 'pomp', 6);
INSERT INTO `words` VALUES (15302, 'The Economist considers itself the enemy of privilege, pomposity and predictability.', 'n. 华丽, 夸耀', '/pɔm\'pɔsiti | pɒm\'pɒsɪtɪ/', 'pomposity', 6);
INSERT INTO `words` VALUES (15303, 'He seems rather pompous.', 'adj. 华而不实的', '/\'pɔmpəs | \'pɒmpəs | \'pɑmpəs/', 'pompous', 6);
INSERT INTO `words` VALUES (15304, 'The brightly polished granite surface depicts the poncho wearing riflemen as they climbed up a Korean hill.', 'n. 雨布', '/\'pɔntʃəu | \'pɒn(t)ʃəʊ | \'pɑntʃo/', 'poncho', 6);
INSERT INTO `words` VALUES (15305, 'He continued to ponder the problem as he walked home.', 'v. 沉思, 考虑', '/\'pɔndə | \'pɒndə | \'pɑndɚ/', 'ponder', 6);
INSERT INTO `words` VALUES (15306, NULL, 'adj. 可估量的', '/\'pɔndərəbl | \'pɑndərəbl/', 'ponderable', 6);
INSERT INTO `words` VALUES (15307, 'He had a dense, ponderous style.', 'adj. 沉重的, 笨重的, 冗长的, 沉闷的, (指问题等)呆板的', '/\'pɒnd(ə)rəs | \'pɑndərəs/', 'ponderous', 6);
INSERT INTO `words` VALUES (15308, '\'You are mistaken, monsieur, \'I replied; \'he has perished by the poniard. \'', 'n. 短剑, 匕首', '/\'pɔnjəd | \'pɒnjəd/', 'poniard', 6);
INSERT INTO `words` VALUES (15309, 'Under John Paul the Curia acquired a string of new “pontifical councils”, quasi-ministries that deal with everything from health workers to canon law.', 'adj. 罗马教皇的, 主教的, 大祭司的', '/pɔn\'tifikəl | pɒn\'tɪfɪk(ə)l | pɑn\'tɪfɪkl/', 'pontifical', 6);
INSERT INTO `words` VALUES (15310, 'Pope Formosus died after a pontificate of four and a half years.', 'n. 教皇的职位, 主教的地位', '/pɔn\'tifikit, -keit | pɒn\'tɪfɪkeɪt/', 'pontificate', 6);
INSERT INTO `words` VALUES (15311, 'Seeing him coming,the pony began to fling out.', 'n. 小型马', '/\'pəuni | \'pəʊnɪ | \'poni/', 'pony', 6);
INSERT INTO `words` VALUES (15312, NULL, 'adj. 疲倦的', '/pu:d/', 'poohed', 6);
INSERT INTO `words` VALUES (15313, 'The region has a large and talented labour pool .', 'n. 资源的集合； 可共享的物资', '/puːl | pul/', 'pool', 6);
INSERT INTO `words` VALUES (15314, 'A balloon popped.', 'v. 发出“砰”的一声； 突然出现', '/pɑːp | pɑp/', 'pop', 6);
INSERT INTO `words` VALUES (15315, 'the effects of the war on the local populace', 'n. 平民', '/\'pɔpjuləs | \'pɒpjʊləs | \'pɑpjələs/', 'populace', 6);
INSERT INTO `words` VALUES (15316, 'Hong Kong is one of the most populous areas in the world.', 'adj. 人口多的, 人口稠密的', '/\'pɔpjuləs | \'pɒpjʊləs | \'pɑpjələs/', 'populous', 6);
INSERT INTO `words` VALUES (15317, 'a porcelain vase', 'n. 瓷器, 瓷', '/\'pɔ:səlin, -lein | \'pɔːs(ə)lɪn | ˈpɔrsələn/', 'porcelain', 6);
INSERT INTO `words` VALUES (15318, 'It also became apparent that the new virus contains bits and pieces derived from avian and human strains of influenza, as well as porcine ones, further muddying its origins.', 'adj. 猪的', '/\'pɔ:sain, -sin | \'pɔːsaɪn | ˈpɔːrsaɪn/', 'porcine', 6);
INSERT INTO `words` VALUES (15319, 'In Maine, the most commonly counted roadkill species is the North American porcupine.', 'n. [动]豪猪, 箭猪', '/\'pɔ:kjupain | \'pɔːkjʊpaɪn | \'pɔrkjə\'paɪn/', 'porcupine', 6);
INSERT INTO `words` VALUES (15320, 'porous material', 'adj. 多孔渗水的', '/\'pɔ:rəs, \'pəu- | \'pɔːrəs | \'pɔrəs/', 'porous', 6);
INSERT INTO `words` VALUES (15321, 'a portable radio', 'adj. 轻便的, 手提(式)的, 便携式的', '/\'pɔ:təbl, \'pəu- | \'pɔːtəb(ə)l | \'pɔrtəbl/', 'portable', 6);
INSERT INTO `words` VALUES (15322, 'strange events that portend disaster', 'v. 预示', '/pɔ:\'tend, pəu- | pɔː\'tend | pɔr\'tɛnd/', 'portend', 6);
INSERT INTO `words` VALUES (15323, 'The savage civil war there could be a portent of what\'s to come in the rest of the region.', 'n. 征兆', '/\'pɔ:tent, \'pəu- | \'pɔːtent; -t(ə)nt | \'pɔrtɛnt/', 'portent', 6);
INSERT INTO `words` VALUES (15324, 'Recent developments are as portentous as the collapse of the Berlin Wall.', 'adj. 预示性的', '/pɔ:\'tentəs, \'pəu- | pɔː\'tentəs | pɔr\'tɛntəs/', 'portentous', 6);
INSERT INTO `words` VALUES (15325, 'the foreign affairs portfolio', 'n. 部长职务', '/pɔ:t\'fəuljəu, ,pəut- | pɔːt\'fəʊlɪəʊ | pɔrt\'folɪo/', 'portfolio', 6);
INSERT INTO `words` VALUES (15326, 'We stood on the North Lawn gazing with wonder at her grand portico.', 'n. [建](有圆柱的)门廊, 柱廊', '/\'pɔ:tikəu, \'pəu- | \'pɔːtɪkəʊ | \'pɔrtɪko/', 'portico', 6);
INSERT INTO `words` VALUES (15327, 'His most famous painting portrayed the death of Nelson.', 'v. 描述； 描绘， 描画', '/pɔːr\'treɪ | pɔr\'tre/', 'portray', 6);
INSERT INTO `words` VALUES (15328, 'Ann struck a pose (= stood or sat in a particular position ) and smiled for the camera.', 'n. 姿势, 姿态', '/pəʊz | poz/', 'pose', 6);
INSERT INTO `words` VALUES (15329, 'You meet a lot of posers in this job.', 'n. 装腔作势者, 难题', '/\'pəuzə | \'pəʊzə | \'pozɚ/', 'poser', 6);
INSERT INTO `words` VALUES (15330, 'I am sometimes accused of being a poseur.', 'n. 装模作样的人, 装腔作势的人', '/pəu\'zə: | po\'zɝ/', 'poseur', 6);
INSERT INTO `words` VALUES (15331, 'Several writers have posited the idea of a universal consciousness.', 'v. 安置', '/\'pɔzit | \'pɒzɪt | \'pɑzɪt/', 'posit', 6);
INSERT INTO `words` VALUES (15332, 'the power of positive thinking', 'adj. 积极的；明确的；有信心的；无条件的; n. 正片； 积极的要素或特点', '/\'pɑːzətɪv | \'pɑzətɪv/', 'positive', 6);
INSERT INTO `words` VALUES (15333, 'They are mostly lack of positiveness psychologically. The psychological source must be found so that they will stop wanting to command.', 'n. 肯定；信心', '/\'pɔzətivnis/', 'positiveness', 6);
INSERT INTO `words` VALUES (15334, 'Different workers possess different skills.', 'v. 拥有； 支配， 主宰； 受摆布， 缠住， 迷住', '/pə\'zes | pə\'zɛs/', 'possess', 6);
INSERT INTO `words` VALUES (15335, 'She was convinced he was possessed by the devil .', 'adj. 着魔的, 疯狂的', '/pə\'zest | pə\'zɛst/', 'possessed', 6);
INSERT INTO `words` VALUES (15336, NULL, 'v. 填迟…的日期 that is later than the actual date)', '/\'pɑːstdeɪt | \'post\'det/', 'postdate', 6);
