INSERT INTO `words` VALUES (15339, 'A photographer recorded the scene on video for posterity.', 'n. 子孙, 后裔', '/pɔs\'teriti | pɒ\'sterɪtɪ | pɑ\'stɛrəti/', 'posterity', 6);
INSERT INTO `words` VALUES (15340, 'a posthumous collection of his articles', 'adj. 死后的, 身后的, 作者死后出版的, 遗腹的', '/\'pɔstjuməs, -tʃu- | \'pɒstjʊməs | \'pɑstʃəməs/', 'posthumous', 6);
INSERT INTO `words` VALUES (15341, 'BEHEADED posthumously , as punishment for his part in the execution of Charles I in 1649, Oliver Cromwell\'s fate after death matches his grippingly controversial life.', 'adv. 死后地', '/\'pɑːstʃəməsli | \'pɔstjuməsli/', 'posthumously', 6);
INSERT INTO `words` VALUES (15342, NULL, 'adj. 伪造的，假的; n. 伪造品； 假发', '/pɔ\'stɪːʃ | pɔ\'sti:ʃ/', 'postiche', 6);
