INSERT INTO `words` VALUES (15344, 'a postprandial nap', 'adj. 正餐后的, 餐后的', '/pəust\'prændiəl | pəʊs(t)\'prændɪəl | ,post\'prændɪəl/', 'postprandial', 6);
INSERT INTO `words` VALUES (15345, 'He dismissed arguments postulating differing standards for human rights in different cultures and regions.', 'n. 假定, 基本条件, 基本原理', '/\'pɔstjuleit, -tʃə- | \'pɒstjʊleɪt | \'pɑstʃəlet/', 'postulate', 6);
INSERT INTO `words` VALUES (15346, 'Anaesthetics and bottle feeding were popular in the early postwar years.', 'adj. 战后的', '/\'pɑːstwɔːr | \'post\'wɔr/', 'postwar', 6);
INSERT INTO `words` VALUES (15347, 'There was a very small posy of flowers at my aunt\'s flat.', 'n. 花朵, 花束, 铭文', '/\'pəuzi | \'pəʊzɪ | \'pozi/', 'posy', 6);
INSERT INTO `words` VALUES (15348, 'In general, only one third of health facilities have potable water, and just one in four remain linked to the general sewerage system or to a power supply.', 'adj. 适于饮用的', '/\'pəutəbl | \'pəʊtəb(ə)l | \'potəbl/', 'potable', 6);
INSERT INTO `words` VALUES (15349, NULL, 'n. 饮料', '/pəu\'teiʃən | pə(ʊ)\'teɪʃ(ə)n/', 'potation', 6);
