INSERT INTO `words` VALUES (15357, '...a potpourri of architectural styles from all over the world.', 'n. 花香, 肉菜杂烩', '/,pəu\'puri, pəupu:\'ri: | pəʊ\'pʊərɪ; -\'riː; pɒt\'pʊərɪ | ,popʊ\'ri/', 'potpourri', 6);
INSERT INTO `words` VALUES (15358, NULL, 'v. 肆意抨击; n. 盲目射击；肆意抨击', '/\'pɑːtʃɑːt | \'pɑtʃɑt/', 'potshot', 6);
INSERT INTO `words` VALUES (15359, 'a potted plant', 'adj. 盆栽的； 瓶装的， 罐装的， 壶装的', '/\'pɑːtɪd | \'pɑtɪd/', 'potted', 6);
INSERT INTO `words` VALUES (15360, 'Native American pottery', 'n. 制陶； 制陶工艺； 陶器', '/\'pɑːtəri | \'pɑtəri/', 'pottery', 6);
INSERT INTO `words` VALUES (15361, 'a money pouch', 'n. 小袋, 烟草袋, 钱袋, 育儿袋', '/pautʃ | paʊtʃ/', 'pouch', 6);
INSERT INTO `words` VALUES (15362, 'The cat was hiding in the bushes, ready to pounce.', 'v. 猛扑； 突然袭击; n. 爪；猛扑', '/pauns | paʊns/', 'pounce', 6);
INSERT INTO `words` VALUES (15363, 'He began pounding the keyboard of his computer.', 'v. 猛击， 连续重击； 狂跳， 怦怦地跳', '/paund | paʊnd/', 'pound', 6);
INSERT INTO `words` VALUES (15364, 'She shot me a reproachful pout.', 'n. 撅嘴, 板脸, 生气, 大头鱼类', '/paut | paʊt/', 'pout', 6);
INSERT INTO `words` VALUES (15365, 'Williams took a more pragmatic approach to management problems.', 'adj. 国事的, 团体事务的, 实际的, 注重实效的', '/præɡ\'mætik | præg\'mætɪk/', 'pragmatic', 6);
INSERT INTO `words` VALUES (15366, 'a politician known for his pragmatism', 'n. 实用主义', '/\'præɡmətizəm | \'prægmətɪz(ə)m | \'prægmə\'tɪzəm/', 'pragmatism', 6);
INSERT INTO `words` VALUES (15367, NULL, 'n. (马)后足立地腾跃, 昂首阔步', '/prɑ:ns, præns | prɑːns | præns/', 'prance', 6);
INSERT INTO `words` VALUES (15368, 'a childish prank', 'n. 胡闹, 开玩笑, 恶作剧', '/præŋk/', 'prank', 6);
INSERT INTO `words` VALUES (15369, 'But he also felt that ultimately the whole of reality seemed to be constructed as if by some great cosmic prankster.', 'n. 顽皮的人, 爱开玩笑的人', '/\'præŋkstə/', 'prankster', 6);
INSERT INTO `words` VALUES (15370, 'You prate of sentences having subjects, but all that sort of talk is out of date.', 'v. 空谈', '/preit | preɪt | pret/', 'prate', 6);
INSERT INTO `words` VALUES (15371, 'Lou prattled on about various trivialities till I wanted to scream.', 'v. 说孩子气的话, 说半截话, 闲聊, 胡说, 唠叨', '/\'prætl | \'præt(ə)l/', 'prattle', 6);
