INSERT INTO `words` VALUES (15373, 'Alexander has been preaching patience.', 'v. 鼓吹', '/pri:tʃ | priːtʃ | pritʃ/', 'preach', 6);
INSERT INTO `words` VALUES (15374, 'Harding gave him the news without preamble (= without saying anything else before it ) .', 'n. 导言', '/pri:\'æmbl, \'pri:æ- | priː\'æmb(ə)l; \'priː- | \'priæmbl/', 'preamble', 6);
INSERT INTO `words` VALUES (15375, 'Her health remained precarious, despite the treatment.', 'adj. 不稳定的', '/pri\'kεəriəs | prɪ\'keərɪəs | prɪ\'kɛrərɪəs/', 'precarious', 6);
