INSERT INTO `words` VALUES (15381, NULL, 'n. 过分讲究, 过于细心', '/,preʃi\'ɔsiti | ,preʃɪ\'ɒsɪtɪ | ,prɛʃɪ\'ɑsɪti/', 'preciosity', 6);
INSERT INTO `words` VALUES (15382, 'A loose rock tumbled over the precipice.', 'n. 悬崖', '/\'presipis | \'presɪpɪs | \'prɛsəpɪs/', 'precipice', 6);
INSERT INTO `words` VALUES (15383, NULL, 'adj. 仓促的', '/pri\'sipitənt | prɪ\'sɪpɪt(ə)nt | prɪ\'sɪpətənt/', 'precipitant', 6);
INSERT INTO `words` VALUES (15384, 'The riot was precipitated when four black men were arrested.', 'n. 沉淀物', '/pri\'sipitit, -teit | prɪ\'sɪpɪteɪt | prɪ\'sɪpɪtet/', 'precipitate', 6);
INSERT INTO `words` VALUES (15385, NULL, 'n. 仓促', '/prɪ,sɪpɪ\'teɪʃ(ə)n | prɪ\'sɪpə\'teʃən/', 'precipitation', 6);
INSERT INTO `words` VALUES (15386, 'a precipitous decline in stock prices', 'adj. 陡峭的, 急躁的', '/pri\'sipitəs | prɪ\'sɪpɪtəs/', 'precipitous', 6);
INSERT INTO `words` VALUES (15387, 'I suppose further that you need a precis of the idea so you can decide whether the suggestion is feasible and warrants more exploration.', 'n. 大纲, 摘要', '/\'preɪsi/', 'precis', 6);
INSERT INTO `words` VALUES (15388, 'precise sales figures', 'adj. 精确的， 准确的， 确切的', '/prɪ\'saɪs/', 'precise', 6);
INSERT INTO `words` VALUES (15389, 'And although a modified waterfall approach does not preclude the use of feedback, it does not facilitate, accommodate, or encourage it.', 'n. 排除', '/pri\'klu:d | prɪ\'kluːd | prɪ\'klud/', 'preclude', 6);
INSERT INTO `words` VALUES (15390, 'a precocious child who walked and talked early', 'adj. 早熟的', '/pri\'kəuʃəs | prɪ\'kəʊʃəs | prɪ\'koʃəs/', 'precocious', 6);
INSERT INTO `words` VALUES (15391, 'It\'s long been regarded as pseudoscience, but precognition–that is, the ability to not just predict but to actually perceive the future–is getting a fair shake in some scientific circles lately.', 'n. 预知', '/,pri:kɔɡ\'niʃən | ,priːkɒg\'nɪʃ(ə)n | ,prikɑɡ\'nɪʃən/', 'precognition', 6);
INSERT INTO `words` VALUES (15392, 'Ann: There\'s no longer the preconception that men cannot arrange flowers.', 'n. 预想, 偏见', '/,pri:kən\'sepʃən | priːkən\'sepʃ(ə)n | ,prikən\'sɛpʃən/', 'preconception', 6);
INSERT INTO `words` VALUES (15393, 'Error is often the precursor of what is correct.', 'n. 先驱', '/pri:\'kə:sə, pri- | prɪ\'kɜːsə | pri\'kɝsɚ/', 'precursor', 6);
INSERT INTO `words` VALUES (15394, 'With no natural predators on the island, the herd increased rapidly.', 'n. 掠夺者, 食肉动物', '/\'predətə | \'prɛdətɚ/', 'predator', 6);
INSERT INTO `words` VALUES (15395, 'predatory pricing', 'adj. 掠夺的； 食肉的', '/\'predətɔːri | \'prɛdətɔri/', 'predatory', 6);
INSERT INTO `words` VALUES (15396, 'Kennedy’s predecessor as President was the war hero Dwight Eisenhower.', 'n. 前任， 前辈； 原有事物， 前身', '/\'predəsesər | \'prɛdəsɛsɚ/', 'predecessor', 6);
INSERT INTO `words` VALUES (15397, 'Today predestine a change not drive the fate of strong J?', 'v. 预定, 注定', '/pri:\'destin | priː\'destɪn/', 'predestine', 6);
INSERT INTO `words` VALUES (15398, NULL, 'v. 预先注定； 预先决定', '/ˌpriːdɪ\'tɜːrmɪn | ,pridɪ\'tɝmɪn/', 'predetermine', 6);
INSERT INTO `words` VALUES (15399, 'Actually predial servitude provides a common right mode of setting up usufruct on real estate for the convenience of new utilization becoming property right.', 'adj. 土地的,不动产的,乡村的', '/\'priːdɪəl | \'pridɪəl/', 'predial', 6);
INSERT INTO `words` VALUES (15400, 'the country’s economic predicament', 'n. 困境', '/pri\'dikəmənt | prɪ\'dɪkəm(ə)nt | prɪ\'dɪkəmənt/', 'predicament', 6);
INSERT INTO `words` VALUES (15401, 'The snow had a predictable effect on traffic.', 'adj. 可预言的', '/pri\'diktəbl | prɪ\'dɪktəb(ə)l | prɪ\'dɪktəbl/', 'predictable', 6);
INSERT INTO `words` VALUES (15402, 'Therefore , it is essential to study how to predigest actual circuit and achieve optimized design in V HDL .', 'v. 预先消化, 简化', '/,pri:di\'dʒest, -dai- | ,priːdɪ\'dʒest; -daɪ- | ,pridaɪ\'dʒɛst/', 'predigest', 6);
INSERT INTO `words` VALUES (15403, '...his predilection for fast cars and fast horses.', 'n. 爱好, 偏袒', '/,pri:di\'lekʃən | ,prɛdl\'ɛkʃən/', 'predilection', 6);
INSERT INTO `words` VALUES (15404, 'They take pains to hire people whose personalities predispose them to serve customers well.', 'v. 使预先有倾向； 易受感染', '/ˌpriːdɪ\'spouz | \'pridɪ\'spoz/', 'predispose', 6);
INSERT INTO `words` VALUES (15405, '...a genetic predisposition to lung cancer.', 'n. 易患病的体质', '/\'pri:,dispə\'ziʃən | priːdɪspə\'zɪʃn | \'pridɪspə\'zɪʃən/', 'predisposition', 6);
INSERT INTO `words` VALUES (15406, 'Mandy\'s predominant emotion was confusion.', 'adj. 卓越的, 支配的, 主要的, 突出的, 有影响的', '/,pri\'dɔminənt | prɪ\'dɒmɪnənt | prɪ\'dɑmənənt/', 'predominant', 6);
INSERT INTO `words` VALUES (15407, 'In older age groups women predominate because men tend to die younger.', 'v. 统治； 占优势， 以…为主', '/prɪ\'dɑːmɪneɪt | prɪ\'dɑmə\'net/', 'predominate', 6);
INSERT INTO `words` VALUES (15408, NULL, 'n. 初演日, 首映', '/pri:m/', 'preem', 6);
INSERT INTO `words` VALUES (15409, 'Bombastic boasts—\"We are positioned to become the preeminent provider of XYZ\"—do not constitute a position.', 'adj. 卓越的', '/pri\'eminənt, ,pri:- | prɪ\'emɪnənt | pri\'ɛmɪnənt/', 'preeminent', 6);
INSERT INTO `words` VALUES (15410, 'The law would preempt stronger local rules.', 'v. 先占', '/pri\'empt, ,pri:- | prɪ\'empt | ,primpt/', 'preempt', 6);
