INSERT INTO `words` VALUES (15412, '50% of men under 35 spend at least 20 minutes preening themselves every morning in the bathroom.', 'v. (鸟)用嘴整理, 打扮, 赞扬', '/pri:n | priːn | prin/', 'preen', 6);
