INSERT INTO `words` VALUES (15416, 'The wall through Berlin was finally ruptured, prefiguring the reunification of Germany.', 'v. 预示', '/pri:\'fiɡə, -ɡjuə | priː\'fɪgə | pri\'fɪɡjʊr/', 'prefigure', 6);
INSERT INTO `words` VALUES (15417, 'This drug should not be taken during pregnancy.', 'n. 怀孕', '/\'preɡnənsi | \'pregnənsɪ | \'prɛgnənsi/', 'pregnancy', 6);
INSERT INTO `words` VALUES (15418, 'care for pregnant women', 'adj. 怀孕的, 重要的, 富有意义的, 孕育的', '/\'preɡnənt | \'pregnənt | \'prɛɡnənt/', 'pregnant', 6);
INSERT INTO `words` VALUES (15419, 'The savanna browsing black rhino has a prehensile lip for feeding on shrubs.', 'adj. 能抓住东西的， 缠绕的', '/prɪ\'hensl | prɪ\'hɛnsl/', 'prehensile', 6);
INSERT INTO `words` VALUES (15420, 'prehistoric burial grounds', 'adj. 史前的', '/ˌpriːhɪ\'stɔːrɪk | ,prihɪ\'stɔrɪk/', 'prehistoric', 6);
INSERT INTO `words` VALUES (15421, 'There was concern that reports in the media would prejudice the jury.', 'v. 使产生偏见; n. 偏见，成见', '/\'predʒudɪs | \'prɛdʒədɪs/', 'prejudice', 6);
INSERT INTO `words` VALUES (15422, 'The judge declared a mistrial, saying that Christofferson-Titchbourne’s lawyers had presented prejudicial arguments.', 'adj. 引起偏见的', '/,predʒu\'diʃəl | predʒʊ\'dɪʃ(ə)l | ,prɛdʒu\'dɪʃl/', 'prejudicial', 6);
