INSERT INTO `words` VALUES (15425, 'When millions watch the same programs, the whole world becomes a village, and society is reduced to the condition which obtain in preliterate communities.', 'adj. 文字出现以前的', '/pri:\'litərət | priː\'lɪt(ə)rət | pri\'lɪtərɪt/', 'preliterate', 6);
INSERT INTO `words` VALUES (15426, 'Chopin’s Preludes', 'n. 先驱, 前奏, 序幕', '/\'prelju:d, \'prei- | \'preljuːd | \'prɛljud/', 'prelude', 6);
INSERT INTO `words` VALUES (15427, 'his premature death due to cancer', 'adj. 早熟的， 过早的', '/ˌpriːmə\'tʃur | ,primə\'tʃʊr/', 'premature', 6);
INSERT INTO `words` VALUES (15428, NULL, 'v. 预谋， 预先考虑或安排', '/ˌpriː\'medɪteɪt | pri\'mɛdɪtet/', 'premeditate', 6);
INSERT INTO `words` VALUES (15429, 'premeditated murder', 'adj. 预想的, 预谋的', '/pri\'mediteitid | ,pri\'mɛdɪtetɪd/', 'premeditated', 6);
INSERT INTO `words` VALUES (15430, 'The documentary premiered at the Jerusalem Film Festival.', 'v. 初次公演, 初演主角', '/pri\'miə, prə\'mjer | \'premɪeə | prɪ\'mɪr/', 'premiere', 6);
INSERT INTO `words` VALUES (15431, 'The idea that there is life on other planets is the central premise of the novel.', 'n. 前提', '/\'premɪs | ˈpremɪs/', 'premise', 6);
