INSERT INTO `words` VALUES (15435, 'What’s wrong with Cindy? She seems a little preoccupied.', 'adj. 被先占的, 全神贯注的', '/pri:\'ɔkjupaid | priː\'ɒkjʊpaɪd | pri\'ɑkjə\'paɪd/', 'preoccupied', 6);
INSERT INTO `words` VALUES (15436, 'There is a preponderance of female students in the music department.', 'n. 优势, 占优势', '/pri\'pɔndərəns | prɪ\'pɒnd(ə)r(ə)ns | prɪ\'pɑndərəns/', 'preponderance', 6);
