INSERT INTO `words` VALUES (15438, NULL, 'v. 以重量胜过, 占优势, 超过, 胜过', '/pri\'pɔndəreit | prɪ\'pɒndəreɪt/', 'preponderate', 6);
INSERT INTO `words` VALUES (15439, 'a prepossessing smile', 'adj. 引人注意的', '/,pri:pə\'zesiŋ, \'se- | priːpə\'zesɪŋ | ,pripə\'zɛsɪŋ/', 'prepossessing', 6);
INSERT INTO `words` VALUES (15440, 'The whole idea sounds absolutely preposterous!', 'adj. 荒谬的', '/pri\'pɔstərəs | prɪ\'pɒst(ə)rəs | prɪ\'pɑstərəs/', 'preposterous', 6);
INSERT INTO `words` VALUES (15441, '...preprandial drinks.', 'adj. 餐前的', '/pri:\'prændiəl | priː\'prændɪəl | ,pri\'prændɪəl/', 'preprandial', 6);
INSERT INTO `words` VALUES (15442, 'Good self-esteem is a prerequisite for a happy life.', 'n. 先决条件', '/\'pri:\'rekwizit | priː\'rekwɪzɪt | ,pri\'rɛkwəzɪt/', 'prerequisite', 6);
INSERT INTO `words` VALUES (15443, 'Arriving late is a woman’s prerogative .', 'n. 特权', '/pri\'rɔɡətiv | prɪ\'rɒgətɪv/', 'prerogative', 6);
INSERT INTO `words` VALUES (15444, 'In dreams one may presage the future.', 'n. 预兆', '/\'presidʒ, pri\'seidʒ | \'presɪdʒ | \'prɛsɪdʒ/', 'presage', 6);
INSERT INTO `words` VALUES (15445, 'Over the years he\'s demonstrated a certain prescience in foreign affairs.', 'n. 预知， 先见', '/\'presiəns | \'prɛʃɪəns/', 'prescience', 6);
INSERT INTO `words` VALUES (15446, '...an eerily prescient comedy about a populist multimillionaire political candidate.', 'adj. 预知的, 预见的', '/\'presiənt, \'preʃi-, pri:- | \'preʃɪənt | \'prɛsɪənt/', 'prescient', 6);
INSERT INTO `words` VALUES (15447, 'What punishment does the law prescribe for this crime?', 'v. 开处方； 规定', '/prɪ\'skraɪb/', 'prescribe', 6);
INSERT INTO `words` VALUES (15448, NULL, 'n. 命令', '/\'priskript, pri\'skript | \'priːskrɪpt | prɪ\'skrɪpt/', 'prescript', 6);
INSERT INTO `words` VALUES (15449, 'We are trying to cut the price of prescription drugs .', 'n. 指示, 规定, 命令, 处方, 药方', '/pris\'kripʃən | prɪ\'skrɪpʃ(ə)n | prɪ\'skrɪpʃən/', 'prescription', 6);
INSERT INTO `words` VALUES (15450, 'We will begin a series of presentations to help the public fully understand our system.', 'n. 介绍， 描述', '/ˌpriːzen\'teɪʃn | ,prizɛn\'teʃən/', 'presentation', 6);
INSERT INTO `words` VALUES (15451, NULL, 'n. 推荐者', '/prɪ\'zentə | prɪ\'zɛntɚ/', 'presenter', 6);
INSERT INTO `words` VALUES (15452, 'I had a presentiment that he represented a danger to me.', 'n. 预感', '/prɪ\'zentɪmənt | prɪ\'zɛntɪmənt/', 'presentiment', 6);
INSERT INTO `words` VALUES (15453, 'food that contains no artificial preservatives', 'n. 防腐剂', '/pri\'zə:vətiv | prɪ\'zɜːvətɪv | prɪ\'zɝvətɪv/', 'preservative', 6);
INSERT INTO `words` VALUES (15454, 'We must encourage the planting of new trees and preserve our existing woodlands.', 'v. 保护, 保持, 保存, 保藏', '/pri\'zə:v | prɪ\'zɜːv | prɪ\'zɝv/', 'preserve', 6);
INSERT INTO `words` VALUES (15455, 'I shall be pleased to preside at your meetings.', 'v. 主持', '/pri\'zaid | prɪ\'zaɪd/', 'preside', 6);
INSERT INTO `words` VALUES (15456, 'a trouser press', 'n. 压, 按, 印刷, 压力, 拥挤, 紧握, 新闻', '/pres | prɛs/', 'press', 6);
INSERT INTO `words` VALUES (15457, 'It is one of the most pressing problems facing this country.', 'adj. 紧迫的， 迫切的； 恳切要求的', '/\'presɪŋ | \'prɛsɪŋ/', 'pressing', 6);
INSERT INTO `words` VALUES (15458, 'Magic can be a lifetime hobby and card magic is the poetry of prestidigitation.', 'n. 变戏法', '/\'presti,didʒi\'teiʃən | ,prestɪ,dɪdʒɪ\'teɪʃ(ə)n/', 'prestidigitation', 6);
INSERT INTO `words` VALUES (15459, 'The king wanted to enhance his prestige through war.', 'n. 威信， 威望； 影响力', '/pre\'stiːʒ | prɛ\'stidʒ/', 'prestige', 6);
INSERT INTO `words` VALUES (15460, 'a prestigious literary award', 'adj. 享有声望的, 声望很高的', '/pre\'stidʒəs, -\'sti:- | pre\'stɪdʒəs | prɛ\'stɪdʒəs/', 'prestigious', 6);
INSERT INTO `words` VALUES (15461, NULL, 'n. 急板之乐曲或乐章', '/\'prestəu | \'prestəʊ | \'prɛsto/', 'presto', 6);
INSERT INTO `words` VALUES (15462, 'The answer presumable is gonna be that the best version of the personality theory doesn\'t require item for item, having the very same believes, memories, desires and so forth.', 'adj. 可假定的', '/pri\'zju:məbl, pri:- | prɪ\'zjuːməbl | pri\'zjʊməbl/', 'presumable', 6);
INSERT INTO `words` VALUES (15463, 'I presume you\'re here on business.', 'v. 推测， 假定； 认定', '/prɪ\'zuːm | prɪ\'zum/', 'presume', 6);
INSERT INTO `words` VALUES (15464, '...the presumption that a defendant is innocent until proved guilty.', 'n. 假定', '/pri\'zʌmpʃən, pri:- | prɪ\'zʌm(p)ʃ(ə)n | pri\'zʌmpʃən/', 'presumption', 6);
INSERT INTO `words` VALUES (15465, 'Clearly, it is presumptuous and immoral for a small group of individuals to keep these things under wraps while there is so much misery on the planet.', 'adj. 专横的', '/pri\'zʌmptjuəs, -tʃuəs | prɪ\'zʌm(p)tʃʊəs | prɪ\'zʌmptʃuəs/', 'presumptuous', 6);
INSERT INTO `words` VALUES (15466, 'The idea of heaven presupposes the existence of God.', 'vt. 预先假定； 以…为先决条件', '/ˌpriːsə\'pouz | ,prisə\'poz/', 'presuppose', 6);
INSERT INTO `words` VALUES (15467, '...the presupposition that human life must be sustained for as long as possible.', 'n. 预想, 假设', '/,pri:sʌpə\'ziʃən | \'prisʌpə\'zɪʃən/', 'presupposition', 6);
INSERT INTO `words` VALUES (15468, 'It was all an elaborate pretence .', 'n. 伪装', '/pri\'tens, \'pri:t- | prɪ\'tens/', 'pretence', 6);
INSERT INTO `words` VALUES (15469, 'Her eyes widened in pretended astonishment.', 'adj. 假装的, 虚假的', '/pri\'tendid, pri:- | prɪ\'tendɪd | pri\'tɛndɪd/', 'pretended', 6);
INSERT INTO `words` VALUES (15470, NULL, 'n. 妄称， 自称； 假装， 伪装， 假象； 借口， 托词', '/prɪ\'tens | \'pritɛns/', 'pretense', 6);
INSERT INTO `words` VALUES (15471, 'the humbleness and lack of pretension of Jordan’s cafe', 'n. 借口, 要求, 主张, 自负, 骄傲', '/pri\'tenʃən, pri:- | prɪ\'tenʃ(ə)n | prɪ\'tɛnʃən/', 'pretension', 6);
INSERT INTO `words` VALUES (15472, 'a pretentious film', 'adj. 自命不凡的', '/pri\'tenʃəs, pri:- | prɪ\'tenʃəs | prɪ\'tɛnʃəs/', 'pretentious', 6);
INSERT INTO `words` VALUES (15473, 'He felt possessed of a preternatural strength and fearlessness.', 'adj. 超自然的', '/,pri:tə\'nætʃərəl | ,priːtə\'nætʃ(ə)r(ə)l/', 'preternatural', 6);
INSERT INTO `words` VALUES (15474, 'He’ll phone on some pretext or other.', 'n. 借口, 托辞', '/\'pri:tekst | \'priːtekst | \'pritɛkst/', 'pretext', 6);
INSERT INTO `words` VALUES (15475, 'Justice will prevail.', 'v. 流行, 盛行, 获胜, 成功', '/pri\'veil, pri:- | prɪ\'veɪl | pri\'vel/', 'prevail', 6);
INSERT INTO `words` VALUES (15476, 'The prevailing mood of public opinion remained hostile.', 'adj. 占优势的, 主要的, 流行的', '/pri\'veiliŋ, pri:- | prɪ\'veɪlɪŋ | pri\'velɪŋ/', 'prevailing', 6);
INSERT INTO `words` VALUES (15477, 'the prevalent belief in astrology', 'adj. 普遍的, 流行的', '/\'prevələnt | \'prev(ə)l(ə)nt | \'prɛvələnt/', 'prevalent', 6);
INSERT INTO `words` VALUES (15478, '‘I’m not sure,’ he prevaricated.', 'v. 支吾搪塞', '/pri\'værikeit | prɪ\'værɪkeɪt | prɪ\'værə\'ket/', 'prevaricate', 6);
INSERT INTO `words` VALUES (15479, 'Journalists will be able to preview the exhibition tomorrow.', 'v. 预演， 预先查看; n. 预演，预展', '/\'priːvjuː | \'pri\'vjʊ/', 'preview', 6);
INSERT INTO `words` VALUES (15480, 'She has a teenage daughter from a previous marriage.', 'adj. 在先的， 以前的', '/\'priːviəs | \'privɪəs/', 'previous', 6);
INSERT INTO `words` VALUES (15481, 'The prevision , dissolving to the risk is the first quality that an entrepreneur should possess .', 'n. 先见, 预知', '/pri\'viʒən, ,pri:- | prɪ\'vɪʒən | ,privɪʒən/', 'prevision', 6);
INSERT INTO `words` VALUES (15482, 'a tiger stalking its prey', 'n. 被掠食者, 牺牲者, 掠食', '/prei | preɪ | pre/', 'prey', 6);
INSERT INTO `words` VALUES (15483, 'Prick the sausages before you grill them.', 'v. 刺, 戳, 刺痛, 竖起', '/prik | prɪk/', 'prick', 6);
INSERT INTO `words` VALUES (15484, 'I felt a prickle of disquiet.', 'n. 刺, 刺痛, 柳条篮子', '/\'prikl | \'prɪk(ə)l | \'prɪkl/', 'prickle', 6);
INSERT INTO `words` VALUES (15485, 'a plant with prickly leaves', 'adj. 多刺的', '/\'prikli | \'prɪklɪ/', 'prickly', 6);
INSERT INTO `words` VALUES (15486, NULL, 'n. 刺探者,窥探者', '/\'praɪə | \'praiə/', 'prier', 6);
INSERT INTO `words` VALUES (15487, 'Don’t be such a prig! It’s only a bit of harmless fun!', 'n. 一本正经的人', '/priɡ | prɪg | prɪɡ/', 'prig', 6);
INSERT INTO `words` VALUES (15488, 'a prim suit', 'adj. 整洁的', '/prim | prɪm/', 'prim', 6);
INSERT INTO `words` VALUES (15489, 'a primal fear of the unknown', 'adj. 原始的， 最初的； 首要的', '/\'praɪml/', 'primal', 6);
INSERT INTO `words` VALUES (15490, 'The woolly spider monkey is the largest primate in the Americas.', 'n. 首领, 大主教, 灵长类的动物', '/\'praimeit, -mit | \'praɪmeɪt; -mət | \'praɪmet/', 'primate', 6);
INSERT INTO `words` VALUES (15491, 'Smoking is the prime cause of lung disease.', 'adj. 首先的； 主要的； 最好的; n. 全盛时期', '/praɪm/', 'prime', 6);
INSERT INTO `words` VALUES (15492, '...the language used in reading primers.', 'n. 初级读本, 雷管', '/\'praimə, \'pri- | \'praɪmə | \'praɪmɚ/', 'primer', 6);
INSERT INTO `words` VALUES (15493, 'primeval forests', 'adj. 原始的', '/prai\'mi:vəl | praɪ\'miːv(ə)l/', 'primeval', 6);
INSERT INTO `words` VALUES (15494, 'a primitive society', 'adj. 原始的, 远古的, 粗糙的, 简单的', '/\'primitiv | \'prɪmɪtɪv | \'prɪmətɪv/', 'primitive', 6);
INSERT INTO `words` VALUES (15495, 'the primordial seas', 'adj. 原始的', '/prai\'mɔ:djəl | praɪ\'mɔːdɪəl | praɪ\'mɔrdɪəl/', 'primordial', 6);
INSERT INTO `words` VALUES (15496, 'She spends hours primping in front of the mirror.', 'v. 打扮, 装饰', '/primp | prɪmp/', 'primp', 6);
INSERT INTO `words` VALUES (15497, 'Still, there is the reassuring uplift of fairy tales like Hans Christian Andersen\'s duckling turned swan, with its metamorphosis from plain to princely.', 'adj. 高贵的', '/\'prinsli | \'prɪnslɪ | \'prɪnsli/', 'princely', 6);
INSERT INTO `words` VALUES (15498, NULL, 'v. 化妆, 打扮', '/priŋk | prɪŋk/', 'prink', 6);
INSERT INTO `words` VALUES (15499, 'You do not need any prior knowledge of the subject.', 'adj. 在前的； 优先的', '/\'praɪər | \'praɪɚ/', 'prior', 6);
INSERT INTO `words` VALUES (15500, 'The club’s priority is to win the League.', 'n. 先, 前, 优先, 优先权', '/prai\'ɔrəti | praɪ\'ɒrɪtɪ | praɪ\'ɔrəti/', 'priority', 6);
INSERT INTO `words` VALUES (15501, 'On the monolayer in the absence of additives, the tri-dimensional prismy COM crystals precipitated.', 'adj. 棱柱的, 五光十色的', '/\'prizmi/', 'prismy', 6);
INSERT INTO `words` VALUES (15502, 'I grew to dislike the people from my background – they were uptight and prissy.', 'adj. 谨小慎微的', '/\'prisi | \'prɪsɪ | \'prɪsi/', 'prissy', 6);
INSERT INTO `words` VALUES (15503, 'Walking through the alleys of this venerable water town, one cannot fail to appreciate its pristine and intoxicating atmosphere.', 'adj. 质朴的', '/\'pristain, -ti:n | \'prɪstiːn; -staɪn | \'prɪstin/', 'pristine', 6);
INSERT INTO `words` VALUES (15504, 'each individual’s right to privacy', 'n. 隐居， 隐退； 隐私； 秘密', '/\'praɪvəsi/', 'privacy', 6);
INSERT INTO `words` VALUES (15505, 'the privations of wartime', 'n. 缺乏, 穷困, 丧失, 被剥夺了某物的状态', '/prai\'veiʃən | praɪ\'veɪʃ(ə)n | praɪ\'veʃən/', 'privation', 6);
INSERT INTO `words` VALUES (15506, 'He had no special privileges and was treated just like every other prisoner.', 'n. 特权, 特别待遇, 基本公民权力, 特免', '/ˈprɪvəlɪdʒ/', 'privilege', 6);
INSERT INTO `words` VALUES (15507, NULL, 'n. 奖金, 价格', '/priː | pri/', 'prix', 6);
INSERT INTO `words` VALUES (15508, 'The judge sentenced Jennings to three years’ probation.', 'n. 试用, 见习, 鉴定, 查验, 证明, 察看, 缓刑', '/prəu\'beiʃən | prə\'beɪʃ(ə)n | pro\'beʃən/', 'probation', 6);
INSERT INTO `words` VALUES (15509, '...a federal grand-jury probe into corruption within the FDA.', 'n. 探针, 探测器', '/prəub | prəʊb | prob/', 'probe', 6);
INSERT INTO `words` VALUES (15510, '...a fibre-optic probe.', 'n. 探通术', '/\'prəubiŋ | \'prəʊbɪŋ | \'probɪŋ/', 'probing', 6);
INSERT INTO `words` VALUES (15511, 'I have always found Bentner to be a model of probity in our dealings.', 'n. 正直', '/\'prəubiti | \'prəʊbɪtɪ; \'prɒb- | \'probəti/', 'probity', 6);
INSERT INTO `words` VALUES (15512, 'The reforms could turn out to be highly problematic .', 'adj. 成问题的； 有疑问的， 值得怀疑的； 未知的， 未解决的', '/ˌprɑːblə\'mætɪk | \'prɑblə\'mætɪk/', 'problematic', 6);
INSERT INTO `words` VALUES (15513, 'At least they didn\'t give me a butterfly\'s proboscis, or crab mandibles.', 'n. 鼻子, 长鼻', '/prəu\'bɔsis | prə\'bɒsɪs | pro\'bɑsɪs/', 'proboscis', 6);
INSERT INTO `words` VALUES (15514, 'On board, we were given the usual talk on safety procedures (= what to do if an accident happens, or to prevent an accident ) .', 'n. 程序， 手续', '/prə\'siːdʒər | prə\'sidʒɚ/', 'procedure', 6);
INSERT INTO `words` VALUES (15515, 'We sold the business and bought a villa in Spain with the proceeds.', 'n. 收益', '/\'prəusi:dz | \'prəʊsiːdz | \'prosidz/', 'proceeds', 6);
INSERT INTO `words` VALUES (15516, 'They marched in procession to the Capitol building.', 'n. 行列, 队伍', '/prəu\'seʃən | prə\'seʃ(ə)n | prə\'sɛʃən/', 'procession', 6);
INSERT INTO `words` VALUES (15517, 'The President proclaimed the republic’s independence.', 'v. 宣告， 公布； 显示， 表明', '/prə\'kleɪm | prə\'klem/', 'proclaim', 6);
INSERT INTO `words` VALUES (15518, 'The authorities issued a proclamation forbidding public meetings.', 'n. 宣布， 公布', '/ˌprɑːklə\'meɪʃn | ,prɑklə\'meʃən/', 'proclamation', 6);
INSERT INTO `words` VALUES (15519, 'his sexual proclivities', 'n. 倾向', '/prəu\'kliviti | prə\'klɪvɪtɪ | prə\'klɪvəti/', 'proclivity', 6);
INSERT INTO `words` VALUES (15520, 'People often procrastinate when it comes to paperwork.', 'v. 延迟, 耽搁', '/prəu\'kræstineit | prə(ʊ)\'kræstɪneɪt | pro\'kræstɪnet/', 'procrastinate', 6);
INSERT INTO `words` VALUES (15521, 'Most young women feel a biological need to procreate.', 'v. 生(儿,女), 生殖, 产生', '/\'prəukrieit | \'prəʊkrɪeɪt/', 'procreate', 6);
INSERT INTO `words` VALUES (15522, 'The martinet governed his classroom with procrustean discipline, assigning a week\'s detention to all offenders, no matter what the offense.', 'adj. 残暴的, 强求一致的', '/prəu\'krʌstiən/', 'procrustean', 6);
INSERT INTO `words` VALUES (15523, NULL, 'n. 代理人, 代书, [律]代诉人', '/\'prɔktə | \'prɒktə | \'prɑktɚ/', 'proctor', 6);
INSERT INTO `words` VALUES (15524, 'Russia was cutting procurement of new weapons \"by about 80 percent,\" he said.', 'n. 获得, 取得', '/prəu\'kjuəmənt | prə\'kjʊəmənt | prə\'kjʊrmənt/', 'procurement', 6);
INSERT INTO `words` VALUES (15525, '‘Don’t go to sleep,’ she said, prodding me in the ribs.', 'v. 戳， 刺； 刺激， 激励', '/prɑːd | prɑd/', 'prod', 6);
INSERT INTO `words` VALUES (15526, 'a prodigal lifestyle', 'adj. 浪费的', '/\'prɔdiɡəl | \'prɒdɪg(ə)l | \'prɑdɪɡl/', 'prodigal', 6);
INSERT INTO `words` VALUES (15527, 'the artist’s prodigious output', 'adj. 巨大的', '/prəu\'didʒəs | prə\'dɪdʒəs/', 'prodigious', 6);
INSERT INTO `words` VALUES (15528, 'The Russian tennis prodigy is well on the way to becoming the youngest world champion of all time.', 'n. 惊人的事物, 天才(特指神童), 奇观, 奇事', '/\'prɔdidʒi | \'prɒdɪdʒɪ | \'prɑdədʒi/', 'prodigy', 6);
INSERT INTO `words` VALUES (15529, 'It is prodrome respectively period, foreboding period, convulsion period, atony lethargy period and recognizant convalescence.', 'n. 前驱症状, 序论', '/\'prəudrəum | \'prəʊdrəʊm; \'prɒdrəʊm | \'prodrom/', 'prodrome', 6);
INSERT INTO `words` VALUES (15530, 'profane language', 'adj. 亵渎的', '/prəu\'fein | prə\'feɪn | prə\'fen/', 'profane', 6);
INSERT INTO `words` VALUES (15531, 'To desecrate a holy spring is considered profanity.', 'n. 亵渎', '/prə\'fæniti | prə\'fænɪtɪ | prə\'fænəti/', 'profanity', 6);
INSERT INTO `words` VALUES (15532, 'the proffered invitation', 'v. 提供', '/\'prɔfə | \'prɒfə | \'prɑfɚ/', 'proffer', 6);
INSERT INTO `words` VALUES (15533, NULL, 'n. 进步； 熟练， 精通', '/prə\'fɪʃnsi | prə\'fɪʃənsi/', 'proficiency', 6);
INSERT INTO `words` VALUES (15534, 'As with the transition from competent to proficient, the transition to Expert is also non-linear.', 'n. 精通', '/prəu\'fiʃənt | prə\'fɪʃ(ə)nt | prə\'fɪʃnt/', 'proficient', 6);
INSERT INTO `words` VALUES (15535, 'Dani has a lovely profile.', 'n. 剖面, 侧面, 外形, 轮廓', '/\'prəufail | \'prəʊfaɪl | \'profaɪl/', 'profile', 6);
INSERT INTO `words` VALUES (15536, 'The advertising campaign proved very profitable.', 'adj. 有利可图的', '/\'prɑːfɪtəbl | \'prɑfɪtəbl/', 'profitable', 6);
INSERT INTO `words` VALUES (15537, '...a new social class composed largely of war profiteers and gangsters.', 'n. 奸商', '/,prɔfi\'tiə | prɒfɪ\'tɪə | ,prɑfə\'tɪə/', 'profiteer', 6);
INSERT INTO `words` VALUES (15538, '...the continuing profligacy of certain states.', 'n. 放荡； 肆意挥霍', '/\'prɔfliɡəsi | \'prɑːflɪgəsi/', 'profligacy', 6);
INSERT INTO `words` VALUES (15539, 'profligate spending', 'adj. 放荡的, 不检点的, 肆意挥霍的', '/\'prɔfliɡət, -ɡeit | \'prɒflɪgət | prɑfləɡɪt/', 'profligate', 6);
INSERT INTO `words` VALUES (15540, 'a profound sense of guilt', 'adj. 深的； 深刻的， 深远的； 渊博的； 深奥的', '/prə\'faund | prə\'faʊnd/', 'profound', 6);
INSERT INTO `words` VALUES (15541, 'The profundity of this book is achieved with breathtaking lightness.', 'n. 深度, 深处, 深奥, 深刻', '/prəu\'fʌndəti | prə\'fʌndətɪ | prə\'fʌndəti/', 'profundity', 6);
INSERT INTO `words` VALUES (15542, 'He made profuse apologies .', 'adj. 极其丰富的', '/prəu\'fju:s | prə\'fjuːs | prə\'fjus/', 'profuse', 6);
INSERT INTO `words` VALUES (15543, '...a delightful river with a profusion of wild flowers along its banks.', 'n. 丰富', '/prəu\'fju:ʒən | prə\'fjuːʒ(ə)n | prəˈfjuʒən/', 'profusion', 6);
INSERT INTO `words` VALUES (15544, 'He was also a progenitor of seven presidents of Nicaragua.', 'n. 祖先, 起源', '/prəu\'dʒenitə | prə(ʊ)\'dʒenɪtə | pro\'dʒɛnɪtɚ/', 'progenitor', 6);
INSERT INTO `words` VALUES (15545, '...the freed slaves and their progeny.', 'n. 后裔', '/\'prɔdʒini | \'prɒdʒənɪ | \'prɑdʒəni/', 'progeny', 6);
INSERT INTO `words` VALUES (15546, 'The doctor\'s prognosis was that Laurence might walk within 12 months.', 'n. 【医】预断， 预后', '/prɑːg\'nousɪs | prɑg\'nosɪs/', 'prognosis', 6);
INSERT INTO `words` VALUES (15547, 'Unfortunately, I am not able to prognosticate how everything will eventually shake out.', 'v. 预言', '/prəɡ\'nɔstikeit | prɒg\'nɒstɪkeɪt/', 'prognosticate', 6);
INSERT INTO `words` VALUES (15548, 'Smoking is strictly prohibited inside the factory.', 'v. 禁止； 阻止', '/prou\'hɪbɪt | prə\'hɪbɪt/', 'prohibit', 6);
INSERT INTO `words` VALUES (15549, 'prohibitive regulations', 'adj. 禁止的, 抑制的', '/prəu\'hibitiv | prə(ʊ)\'hɪbɪtɪv | prə\'hɪbətɪv/', 'prohibitive', 6);
INSERT INTO `words` VALUES (15550, 'Then they started to look and discovered that it was some kind of projectile, but they didn\'t know what it was.', 'n. 射弹', '/prəu\'dʒektail, -til | prə(ʊ)\'dʒektaɪl; -tɪl | prə\'dʒɛktl/', 'projectile', 6);
INSERT INTO `words` VALUES (15551, 'projection equipment', 'n. 突起物， 隆起物； 设计， 规划； 发射， 投射', '/prə\'dʒekʃn | prə\'dʒɛkʃən/', 'projection', 6);
INSERT INTO `words` VALUES (15552, '...a slide projector.', 'n. 电影放映机， 幻灯机', '/prə\'dʒektər | prə\'dʒɛktɚ/', 'projector', 6);
INSERT INTO `words` VALUES (15553, 'Passive energy dissipation existing in the spinner of prolate dual-spin satellite will lead to nutation divergence.', 'adj. 扁长的', '/\'prəuleit | \'prəʊleɪt | \'prolet/', 'prolate', 6);
INSERT INTO `words` VALUES (15554, '...a proletarian revolution.', 'adj. 无产阶级的', '/,prəule\'tεəriən | ,prəʊlɪ\'teərɪən | ,prolə\'tɛrɪən/', 'proletarian', 6);
INSERT INTO `words` VALUES (15555, 'Computer courses continue to proliferate.', 'v. 增生扩散', '/prəu\'lifəreit | prə\'lɪfəreɪt | prə\'lɪfə\'ret/', 'proliferate', 6);
INSERT INTO `words` VALUES (15556, 'Handel’s prolific output of opera', 'adj. 多产的, 丰富的, 大量繁殖的', '/prəu\'lifik | prə\'lɪfɪk/', 'prolific', 6);
INSERT INTO `words` VALUES (15557, 'Everyone hates the prolix Gadaffi, particularly Arab despots who he routinely blasts as “old women in robes,” “Zionist lackeys,” and “cowards and thieves.', 'adj. 冗长的, 说话罗嗦的', '/\'prəuliks, prəu\'l- | \'prəʊlɪks; prə\'lɪks | \'prolɪks/', 'prolix', 6);
INSERT INTO `words` VALUES (15558, 'The prologue to the novel is written in the form of a newspaper account.', 'n. 序言', '/\'prəulɔɡ, -lɔ:ɡ | \'prəʊlɒg | \'prolɔɡ/', 'prologue', 6);
INSERT INTO `words` VALUES (15559, 'I was trying to think of some way to prolong the conversation.', 'v. 延长, 拖延', '/prə\'lɔŋ, \'lɔ:ŋ | prə\'lɒŋ | prəˈlɑːŋ/', 'prolong', 6);
INSERT INTO `words` VALUES (15560, 'prolonged exposure to the sun', 'adj. 延长的, 拖延的', '/prəu\'lɔŋd, -\'lɔ:- | prə\'lɒŋd | pro\'lɔŋd/', 'prolonged', 6);
INSERT INTO `words` VALUES (15561, 'an evening promenade', 'n. 散步', '/,prɔmi\'nɑ:d, -\'neid | ,prɒmə\'nɑːd; -\'neɪd; \'prɒm- | ,prɑmə\'ned/', 'promenade', 6);
INSERT INTO `words` VALUES (15562, 'He came to prominence during the World Cup.', 'n. 突出物； 突出， 显著', '/\'prɑːmɪnəns | \'prɑmɪnəns/', 'prominence', 6);
