INSERT INTO `words` VALUES (15570, 'The decision prompted an outcry among prominent US campaigners.', 'n. 提示, 付款期限', '/prɔmpt | prɒm(p)t | prɑmpt/', 'prompt', 6);
INSERT INTO `words` VALUES (15571, 'The New York team needed little prompting from their coach Bill Parcells.', 'n. 促进, 激励, 提示', '/\'prɔmptiŋ | \'prɒm(p)tɪŋ | \'prɑmptɪŋ/', 'prompting', 6);
