INSERT INTO `words` VALUES (15573, 'The shipping industry promulgated a voluntary code.', 'v. 发布, 公布, 传播', '/\'prɔməlɡeit, prəu\'mʌl- | \'prɒm(ə)lgeɪt | \'prɑmlɡet/', 'promulgate', 6);
INSERT INTO `words` VALUES (15574, 'His eyes shifted to the prone body on the floor.', 'adj. 倾向于', '/prəun | prəʊn | pron/', 'prone', 6);
INSERT INTO `words` VALUES (15575, 'sticking out like the prongs of a garden fork', 'v. 刺，贯穿; n. 叉子， 尖齿； 齿状物', '/prɔːŋ | prɔŋ/', 'prong', 6);
