INSERT INTO `words` VALUES (15580, 'The group launched a website to propagate its ideas .', 'v. 繁殖, 传播, 宣传', '/\'prɔpəɡeit | \'prɒpəgeɪt | \'prɑpə\'get/', 'propagate', 6);
INSERT INTO `words` VALUES (15581, 'a boat propelled by a small motor', 'v. 推进, 驱使', '/prəu\'pel | prə\'pel | prə\'pɛl/', 'propel', 6);
INSERT INTO `words` VALUES (15582, '...a fixed three-bladed propeller.', 'n. 推进者, 推进物, 尤指轮船, 飞机上的螺旋推进器', '/prəu\'pelə | prə\'pelə | prə\'pɛlɚ/', 'propeller', 6);
INSERT INTO `words` VALUES (15583, 'Mr. Bint has a propensity to put off decisions to the last minute.', 'n. 倾向', '/prəu\'pensiti | prə\'pensɪtɪ | prə\'pɛnsəti/', 'propensity', 6);
INSERT INTO `words` VALUES (15584, 'She had the gift of prophecy.', 'n. 预言', '/\'prɑːfəsi | \'prɑfəsi/', 'prophecy', 6);
INSERT INTO `words` VALUES (15585, 'There was a great war between the countries, just as the elders had prophesied.', 'v. 预言', '/\'prɑːfəsaɪ | \'prɑfəsaɪ/', 'prophesy', 6);
