INSERT INTO `words` VALUES (15588, 'prophylactic antibiotics', 'adj. 预防疾病的', '/,prɔfi\'læktik, ,prəu- | ,prɒfɪ\'læktɪk | ,profə\'læktɪk/', 'prophylactic', 6);
