INSERT INTO `words` VALUES (15590, 'I\'ve never gone out of my way to propitiate people.', 'v. 劝解', '/prəu\'piʃieit | prə\'pɪʃɪeɪt | prə\'pɪʃɪet/', 'propitiate', 6);
