INSERT INTO `words` VALUES (15593, 'Halsey was identified as a leading proponent of the values of progressive education.', 'n. 建议者, 支持者, [律]提出认证遗嘱者', '/prəu\'pəunənt | prə\'pəʊnənt | prə\'ponənt/', 'proponent', 6);
INSERT INTO `words` VALUES (15594, 'He telephoned Stuart with a proposition.', 'n. 看法， 主张； 提议', '/ˌprɑːpə\'zɪʃn | ,prɑpə\'zɪʃən/', 'proposition', 6);
INSERT INTO `words` VALUES (15595, 'They have proprietary rights to the data.', 'adj. 所有的, 私人拥有的', '/prəu\'praiətəri | prə\'praɪət(ə)rɪ | prə\'praɪətɛri/', 'proprietary', 6);
INSERT INTO `words` VALUES (15596, 'strict in observing the proprieties', 'n. 适当', '/prəu\'praiəti | prə\'praɪətɪ | prə\'praɪəti/', 'propriety', 6);
INSERT INTO `words` VALUES (15597, 'But magnetic propulsion has some drawbacks.', 'n. 推进, 推进力', '/prəu\'pʌlʃən | prə\'pʌlʃ(ə)n | prə\'pʌlʃən/', 'propulsion', 6);
INSERT INTO `words` VALUES (15598, 'Mr Harper turned a customary recess into prorogation .', 'n. 休会', '/,prəurəu\'ɡeiʃən, ,prɔ:- | ,prəʊrəʊ\'ɡeɪʃən | ,prɔro\'ɡeʃən/', 'prorogation', 6);
INSERT INTO `words` VALUES (15599, 'It was the third time the prime minister had employed the prorogue in as many years.', 'n. 休会', '/prəu\'rəuɡ | prə\'rəʊg/', 'prorogue', 6);
