INSERT INTO `words` VALUES (15601, 'The Act proscribes discrimination on the grounds of race.', 'v. 禁止', '/prou\'skraɪb | pro\'skraɪb/', 'proscribe', 6);
INSERT INTO `words` VALUES (15602, 'Shute\'s prose is stark and chillingly unsentimental.', 'n. 散文', '/prouz | proz/', 'prose', 6);
INSERT INTO `words` VALUES (15603, 'Shoplifters will be prosecuted.', 'v. 实行, 从事, 告发, 起诉', '/\'prɔsikju:t | \'prɒsɪkjuːt | \'prɑsɪ\'kjʊt/', 'prosecute', 6);
INSERT INTO `words` VALUES (15604, 'a criminal prosecution', 'n. 起诉， 检举； 进行， 经营', '/ˌprɑːsɪ\'kjuːʃn | ,prɑsɪ\'kjuʃən/', 'prosecution', 6);
INSERT INTO `words` VALUES (15605, 'I was the first to go before the prosecutor.', 'n. 检举人', '/\'prɔsikju:tə | \'prɒsɪkjuːtə | \'prɑsɪ\'kjʊtɚ/', 'prosecutor', 6);
