INSERT INTO `words` VALUES (15607, 'I assured him we didn\'t come here to proselytize.', 'v. 使改宗', '/\'prɔsilitaiz | \'prɒsələtaɪz | \'prɑsələtaɪz/', 'proselytize', 6);
INSERT INTO `words` VALUES (15608, 'I used also to recite to her the scraps of poetry used as illustrations in the chapter on prosody or rhetoric of our Bengali grammar.', 'n. 诗体论, 作诗法, 韵律学', '/\'prɔsədi | \'prɒsədɪ | \'prɑsədi/', 'prosody', 6);
INSERT INTO `words` VALUES (15609, 'He had prospected for minerals everywhere from the Gobi Desert to the Transvaal.', 'v. 勘探; n. 期望； 前景', '/\'prɑːspekt | \'prɑspɛkt/', 'prospect', 6);
INSERT INTO `words` VALUES (15610, 'The story should act as a warning to other prospective buyers.', 'adj. 预期的', '/prəu\'spektiv | prə\'spektɪv | prə\'spɛktɪv/', 'prospective', 6);
INSERT INTO `words` VALUES (15611, '...a prospectus for a new issue of stock.', 'n. 内容说明书, 样张', '/prə\'spektəs | prə\'spɛktəs/', 'prospectus', 6);
INSERT INTO `words` VALUES (15612, 'a time of economic prosperity', 'n. 繁荣', '/prɔs\'periti | prɒ\'sperɪtɪ | prɑ\'spɛrəti/', 'prosperity', 6);
INSERT INTO `words` VALUES (15613, 'a prosperous landowner', 'adj. 繁荣的', '/\'prɔspərəs | \'prɒsp(ə)rəs | \'prɑspərəs/', 'prosperous', 6);
INSERT INTO `words` VALUES (15614, 'They found him lying prostrate on the floor.', 'adj. 降伏的, 沮丧的, 衰竭的, 俯卧的', '/\'prɔstreit | \'prɒstreɪt | \'prɑstret/', 'prostrate', 6);
INSERT INTO `words` VALUES (15615, 'the main protagonists in the conflict', 'n. (戏剧, 故事, 小说中的)主角, 领导者, 积极参加者', '/prəu\'tæɡənist | prə\'tæg(ə)nɪst | prə\'tæɡənɪst/', 'protagonist', 6);
INSERT INTO `words` VALUES (15616, 'He is a protean stylist who can move from blues to ballads and grand symphony.', 'adj. 变化多端的', '/prəu\'ti:ən, \'prəuti- | \'prəʊtɪən; prəʊ\'tiːən | \'protɪən/', 'protean', 6);
