INSERT INTO `words` VALUES (15618, 'Five thousand employees came out on strike in protest at the poor working conditions.', 'n. 主张, 断言, 抗议', '/prəu\'test, \'prəu- | \'prəʊtest | ˈproʊtest/', 'protest', 6);
INSERT INTO `words` VALUES (15619, '...a computer protocol which could communicate across different languages.', 'n. 草案, 协议', '/\'prəutəkɔl | \'prəʊtəkɒl | \'protə\'kɔl/', 'protocol', 6);
INSERT INTO `words` VALUES (15620, 'But how do you come up with the architecture for this evolutionary prototype?', 'n. 原型', '/\'prəutətaip | \'prəʊtətaɪp | \'protə\'taɪp/', 'prototype', 6);
