INSERT INTO `words` VALUES (15626, 'Luna turned her protuberant eyes upon him in surprise.', 'adj. 突起的, 凸出的, 隆起的', '/prəu\'tju:bərənt | prə\'tjuːb(ə)r(ə)nt | pro\'tubərənt/', 'protuberant', 6);
INSERT INTO `words` VALUES (15627, 'The provenance of the paintings is unknown.', 'n. 起源, 出处', '/\'prɔvənəns | \'prɒv(ə)nəns | \'prɑvənəns/', 'provenance', 6);
INSERT INTO `words` VALUES (15628, NULL, 'n. 粮草, 秣, [口]食物', '/\'prɔvində | \'prɒvɪndə | \'prɑvɪndɚ/', 'provender', 6);
INSERT INTO `words` VALUES (15629, 'An old Arab proverb says, \"The enemy of my enemy is my friend.\"', 'n. 谚语', '/\'prɑːvɜːrb | \'prɑvɝb/', 'proverb', 6);
