INSERT INTO `words` VALUES (15631, 'These women regard his death as an act of providence.', 'n. 深谋远虑, 天意, 上帝, 神的眷顾', '/\'prɔvidəns | \'prɒvɪd(ə)ns | \'prɑvɪdəns/', 'providence', 6);
INSERT INTO `words` VALUES (15632, NULL, 'adj. 有远见的', '/\'prɔvidənt | \'prɒvɪd(ə)nt | \'prɑvɪdənt/', 'provident', 6);
INSERT INTO `words` VALUES (15633, 'The pistols were loaded so our escape is indeed providential.', 'adj. 幸运的； 适时的', '/ˌprɑːvɪ\'denʃl | ,prɑvɪ\'dɛnʃl/', 'providential', 6);
INSERT INTO `words` VALUES (15634, 'a provincial election', 'adj. 省的', '/prəu\'vinʃəl | prə\'vɪnʃ(ə)l | prə\'vɪnʃl/', 'provincial', 6);
