INSERT INTO `words` VALUES (15636, 'a provisional government', 'adj. 临时的', '/prəu\'viʒənəl | prə\'vɪʒ(ə)n(ə)l | prə\'vɪʒənl/', 'provisional', 6);
INSERT INTO `words` VALUES (15637, 'He was accused of deliberate provocation .', 'n. 激怒, 刺激, 挑衅, 挑拨', '/,prɔvə\'keiʃən | ,prɒvə\'keɪʃ(ə)n | ,prɑvə\'keʃən/', 'provocation', 6);
INSERT INTO `words` VALUES (15638, 'a provocative act by a terrorist group', 'adj. 煽动的', '/prəu\'vɔkətiv | prə\'vɒkətɪv | prə\'vɑkətɪv/', 'provocative', 6);
INSERT INTO `words` VALUES (15639, 'The novel has provoked fierce debate in the US.', 'v. 激怒, 挑拨, 煽动, 惹起, 驱使', '/prəu\'vəuk | prə\'vəʊk | prə\'vok/', 'provoke', 6);
INSERT INTO `words` VALUES (15640, 'These forms of art are large, bold and bright and certainly make a poignant statement - regardless of what that public statement may be, it is powerful and thought provoking.', 'adj. 激怒的', '/prəu\'vəukiŋ | prə\'vəʊkɪŋ | prə\'vokɪŋ/', 'provoking', 6);
INSERT INTO `words` VALUES (15641, 'With its prowess, Hezbollah can now blackmail the government into giving it more political power.', 'n. 威力', '/\'prauis | \'praʊɪs | \'praʊəs/', 'prowess', 6);
INSERT INTO `words` VALUES (15642, 'gangs of teenagers prowling the streets', 'v. 潜行，悄悄踱步; n. 四处觅食， 徘徊', '/praul | praʊl/', 'prowl', 6);
INSERT INTO `words` VALUES (15643, 'However, this hypothesis is a proximate explanation and is perfectly compatible with the ultimate explanation we have focused on here.', 'adj. 最近的', '/\'prɔksimit | \'prɒksɪmət | \'prɑksəmət/', 'proximate', 6);
INSERT INTO `words` VALUES (15644, 'Here the rich and the poor live in close proximity (= very near to each other ) .', 'n. 接近, 亲近', '/prɒk\'sɪmɪtɪ | prɑk\'sɪməti/', 'proximity', 6);
INSERT INTO `words` VALUES (15645, 'Caroline was very much a prude. She wouldn\'t let me see her naked.', 'n. 装成规矩的女人, (尤指在性问题上)故做正经的女人', '/pru:d | pruːd | prud/', 'prude', 6);
INSERT INTO `words` VALUES (15646, 'financial prudence', 'n. 审慎', '/\'pru:dəns | \'pruːd(ə)ns | \'prʊdns/', 'prudence', 6);
