INSERT INTO `words` VALUES (15650, 'The roses need pruning.', 'v. 剪除', '/pru:n | pruːn | prun/', 'prune', 6);
INSERT INTO `words` VALUES (15651, 'Nobody ever lost money by overestimating the public\'s prurience.', 'n. 好色, 渴望', '/\'pruəriəns/', 'prurience', 6);
