INSERT INTO `words` VALUES (15759, '‘But why can’t I go?’ he said in a querulous voice.', 'adj. 鸣不平的, 发牢骚的, 易怒的, 暴躁的', '/\'kweruləs | \'kwerʊləs; \'kwerjʊləs | \'kwɛrələs/', 'querulous', 6);
INSERT INTO `words` VALUES (15760, 'Staff are always available to answer your queries.', 'n. 质问, 询问, 怀疑, 疑问', '/\'kwɪərɪ] | \'kwɪərɪ | \'kwɪri/', 'query', 6);
INSERT INTO `words` VALUES (15761, 'They journeyed to the distant Molucca islands in quest of spices.', 'n. 寻求', '/kwest | kwɛst/', 'quest', 6);
INSERT INTO `words` VALUES (15762, 'You’ll have to join the queue.', 'n. 行列, 长队, 队列', '/kju: | kjuː | kju/', 'queue', 6);
INSERT INTO `words` VALUES (15763, 'I’ve just got a few minor quibbles.', 'n. 双关语, 遁辞, 谬论', '/\'kwibl | \'kwɪb(ə)l | \'kwɪbl/', 'quibble', 6);
INSERT INTO `words` VALUES (15764, 'I’ve got a question for you – it’s just a quickie.', 'n. <俚>匆匆做成的事, 快饮', '/\'kwiki | \'kwɪkɪ | \'kwɪki/', 'quickie', 6);
INSERT INTO `words` VALUES (15765, NULL, 'n. 静止， 沉寂', '/kwai\'esns | kwi\'esns/', 'quiescence', 6);
INSERT INTO `words` VALUES (15766, '...a society which was politically quiescent and above all deferential.', 'adj. 静止的', '/kwai\'esənt | kwɪ\'es(ə)nt; kwaɪ- | kwɪ\'ɛsnt/', 'quiescent', 6);
INSERT INTO `words` VALUES (15767, NULL, 'n. 偿清, 解除, 寂灭, 死', '/kwai\'i:təs, -\'ei- | kwaɪ\'iːtəs | kwaɪ\'itəs/', 'quietus', 6);
INSERT INTO `words` VALUES (15768, 'She dipped a quill in ink, then began to write.', 'n. 羽茎, 大翎毛, （豪猪、刺猬的）刚毛', '/kwil | kwɪl/', 'quill', 6);
INSERT INTO `words` VALUES (15769, 'He was the quintessence of all that Eva most deeply loathed.', 'n. 精萃, 精华, 典范', '/kwin\'tesəns | kwɪn\'tes(ə)ns | kwɪn\'tɛsns/', 'quintessence', 6);
INSERT INTO `words` VALUES (15770, 'Like every computer, this one has its little quirks.', 'n. 急转, 遁词, 怪癖', '/kwə:k | kwɜːk | kwɝk/', 'quirk', 6);
INSERT INTO `words` VALUES (15771, 'He is a quisling.', 'n. 卖国贼', '/\'kwizliŋ | \'kwɪzlɪŋ/', 'quisling', 6);
INSERT INTO `words` VALUES (15772, 'He won\'t resign because he\'s not a quitter.', 'n. 轻易停止的人, 懦夫', '/\'kwitə | \'kwɪtə | \'kwɪtɚ/', 'quitter', 6);
INSERT INTO `words` VALUES (15773, 'I recognized it instantly and felt a quiver of panic.', 'n. 震动, 颤抖, 箭袋, 箭袋中的箭', '/\'kwivə | \'kwɪvə | \'kwɪvɚ/', 'quiver', 6);
INSERT INTO `words` VALUES (15774, 'This is a vast, exciting, and perhaps quixotic project.', 'adj. 唐吉诃德式的, 狂想家的', '/kwik\'sɔtik | kwɪk\'sɒtɪk/', 'quixotic', 6);
INSERT INTO `words` VALUES (15775, NULL, 'adj. 可挖苦的', NULL, 'quizzable', 6);
INSERT INTO `words` VALUES (15776, 'He gave Robin a mildly quizzical glance.', 'adj. 古怪的, 引人发笑的, 嘲弄的, 探询的', '/\'kwizikəl | \'kwɪzɪk(ə)l | \'kwɪzɪkl/', 'quizzical', 6);
INSERT INTO `words` VALUES (15777, 'her quondam lover', 'adj. 原来的， 以前的', '/\'kwɔndæm/', 'quondam', 6);
INSERT INTO `words` VALUES (15778, 'The government has decided to scrap quotas on car imports.', 'n. 定额， 配额', '/\'kwoutə | \'kwotə/', 'quota', 6);
INSERT INTO `words` VALUES (15779, 'He quoted a short passage from the Bible.', 'v. 引用， 引述', '/kwout | kwot/', 'quote', 6);
INSERT INTO `words` VALUES (15780, 'I had hopes of escaping my quotidian world.', 'adj. 每日的, 每日发作的, 平凡的, 日常的', '/kwəu\'tidiən, kwɔ- | kwɒ\'tɪdɪən; kwəʊ- | kwo\'tɪdɪən/', 'quotidian', 6);
INSERT INTO `words` VALUES (15781, 'He seems to attract a rabble of supporters more loyal to the man than to the cause.', 'n. 乌合之众, 下层社会, 拨火棍', '/\'ræbl | \'ræb(ə)l/', 'rabble', 6);
INSERT INTO `words` VALUES (15782, 'a group of rabid right-wing fanatics', 'adj. 狂暴的, 激烈的, 患有狂犬病的', '/\'ræbid | \'ræbɪd; \'reɪ-/', 'rabid', 6);
INSERT INTO `words` VALUES (15783, NULL, 'n. 生动活泼', '/\'reɪsɪnəs | \'reisinis/', 'raciness', 6);
INSERT INTO `words` VALUES (15784, 'a wine rack', 'n. 架, 行李架, 拷问台, 小步跑, 烧酒, 破坏', '/ræk/', 'rack', 6);
INSERT INTO `words` VALUES (15785, NULL, 'n. 敲诈者, 获取不正当钱财的人', '/,ræki\'tiə | rækɪ\'tɪə | ,rækə\'tɪr/', 'racketeer', 6);
INSERT INTO `words` VALUES (15786, NULL, 'adj. 喧扰的, 喜欢吵闹的, 摇晃的, 不牢固的', '/\'rækiti | \'rækɪtɪ | \'rækɪti/', 'rackety', 6);
INSERT INTO `words` VALUES (15787, 'He is a natural raconteur, good-looking, athletic, intellectually curious, financially successful, and wittily self-deprecating.', 'n. 健谈者, 善谈者', '/,rækɔn\'tə: | ,rækɒn\'tɜː | ,rækɑn\'tɝ/', 'raconteur', 6);
INSERT INTO `words` VALUES (15788, 'the moon’s radiance', 'n. 光辉, 闪烁, 辐射率, 深粉红色', '/\'reidiəns | \'reɪdɪəns | \'redɪəns/', 'radiance', 6);
INSERT INTO `words` VALUES (15789, 'She looked radiant in a white silk dress.', 'adj. 发光的； 容光焕发的', '/\'reɪdiənt | \'redɪənt/', 'radiant', 6);
INSERT INTO `words` VALUES (15790, 'Many kinds of woodland can be seen on the various walks which radiate from the Heritage Centre.', 'v. 放射, 辐射, 传播, 广播', '/\'reidieit | \'reɪdɪeɪt | \'redɪet/', 'radiate', 6);
INSERT INTO `words` VALUES (15791, 'An accident at the power station could result in large amounts of radiation being released.', 'n. 发散, 发光, 发热, 辐射, 放射, 放射线, 放射物', '/,reidi\'eiʃən | reɪdɪ\'eɪʃ(ə)n | ,redɪ\'eʃən/', 'radiation', 6);
INSERT INTO `words` VALUES (15792, 'Jones himself was a curious mixture of radicalism and conservatism.', 'n. 激进主义', '/\'rædɪkəlɪzəm/', 'radicalism', 6);
INSERT INTO `words` VALUES (15793, NULL, 'adv. 根本上； 以激进方式', '/\'rædɪkli/', 'radically', 6);
INSERT INTO `words` VALUES (15794, '10 is the radix of the decimal system', 'n. 根, 基数', '/\'reidiks | \'rædɪks; \'reɪ- | \'redɪks/', 'radix', 6);
INSERT INTO `words` VALUES (15795, NULL, 'n. 大量, (乱七八糟的)一大堆', '/ræf/', 'raff', 6);
INSERT INTO `words` VALUES (15796, 'an interesting character with a raffish air', 'adj. 名誉不好的, 卑鄙的, 艳俗的', '/\'ræfiʃ | \'ræfɪʃ/', 'raffish', 6);
INSERT INTO `words` VALUES (15797, 'The club was packed to the rafters (= very full ) .', 'n. 椽, 筏夫', '/\'rɑ:ftə, \'ræf- | \'rɑːftə | \'ræftɚ/', 'rafter', 6);
INSERT INTO `words` VALUES (15798, 'He wiped his boots dry with an old rag.', 'n. 旧布， 碎布； 破旧衣服', '/ræg | ræɡ/', 'rag', 6);
INSERT INTO `words` VALUES (15799, 'Sobbing with rage, Carol was taken to the hospital.', 'n. 愤怒, 情绪激动, 狂暴, 精神错乱', '/reidʒ | reɪdʒ | redʒ/', 'rage', 6);
INSERT INTO `words` VALUES (15800, 'O\'Brien formed the men into a ragged line.', 'adj. 粗糙的', '/\'ræɡid | \'rægɪd | \'ræɡɪd/', 'ragged', 6);
INSERT INTO `words` VALUES (15801, 'His music, which used most of the conventions of ragtime, also included improvisation and elements of the blues, two aspects that were widely influential in the development of jazz.', 'adj. 使人发笑的， 滑稽的; n. 雷格泰姆音乐', '/\'rægtaɪm | \'ræɡtaɪm/', 'ragtime', 6);
INSERT INTO `words` VALUES (15802, 'a bombing raid', 'n. 袭击, 搜捕', '/reid | reɪd | red/', 'raid', 6);
INSERT INTO `words` VALUES (15803, 'Several passengers were leaning against the ship’s rail.', 'n. 横杆, 围栏, 扶手, 铁轨', '/reil | reɪl | rel/', 'rail', 6);
INSERT INTO `words` VALUES (15804, 'affectionate raillery', 'n. 开玩笑, 逗趣', '/\'reiləri | \'reɪlərɪ | \'reləri/', 'raillery', 6);
INSERT INTO `words` VALUES (15805, '...homemade oatmeal with brown sugar and raisins.', 'n. 葡萄干', '/\'reizən | \'reɪz(ə)n | \'rezn/', 'raisin', 6);
INSERT INTO `words` VALUES (15806, 'a rakish uniform', 'adj. 潇洒的； 放荡的', '/\'reɪkɪʃ | \'rekɪʃ/', 'rakish', 6);
INSERT INTO `words` VALUES (15807, 'After a shaky start, he rallied and won the title in style.', 'v. 重整旗鼓, 给予新力量, (使)恢复健康, 力量, 决心, 集结', '/\'ræli | \'rælɪ/', 'rally', 6);
INSERT INTO `words` VALUES (15808, 'There’s plenty to discover as you ramble around this little island.', 'v. 漫游', '/\'ræmbl | \'ræmb(ə)l/', 'ramble', 6);
INSERT INTO `words` VALUES (15809, 'a long rambling letter', 'adj. 漫步的, 散漫的, 流浪性的', '/\'ræmbliŋ | \'ræmblɪŋ/', 'rambling', 6);
INSERT INTO `words` VALUES (15810, 'three rambunctious kids', 'adj. 粗暴的, 骚乱的, 难控制的', '/ræm\'bʌŋkʃəs | ræm\'bʌŋ(k)ʃəs/', 'rambunctious', 6);
INSERT INTO `words` VALUES (15811, 'an agreement which was to have significant ramifications for British politics', 'n. 分枝, 分叉, 衍生物, 支流', '/,ræmifi\'keiʃən | ,ræmɪfɪ\'keɪʃ(ə)n | \'ræməfə\'keʃən/', 'ramification', 6);
INSERT INTO `words` VALUES (15812, NULL, 'v. (使)分枝, (使)分叉, (使)成网状', '/\'ræmifai | \'ræmɪfaɪ | \'ræmə,fai/', 'ramify', 6);
INSERT INTO `words` VALUES (15813, 'While you might see something you think should be done differently, there might actually be a good reason for it. Before going off on an angry rampage, seek to understand the situation first.', 'n. 乱闹, 暴跳', '/ræm\'peidʒ, \'ræmpeidʒ | ræm\'peɪdʒ | \'ræmpedʒ/', 'rampage', 6);
INSERT INTO `words` VALUES (15814, 'Pickpocketing is rampant in the downtown area.', 'adj. 猖獗的, 蔓生的, 猛烈的, 狂暴的, 跛拱的', '/\'ræmpənt | \'ræmp(ə)nt/', 'rampant', 6);
INSERT INTO `words` VALUES (15815, '...a walk along the ramparts of the Old City.', 'n. 垒, 壁垒, 城墙', '/\'ræmpɑ:t/', 'rampart', 6);
INSERT INTO `words` VALUES (15816, 'They entered the shop, which was a curious ramshackle building.', 'adj. 摇摇欲坠的', '/\'ræm,ʃækl | \'ræmʃæk(ə)l/', 'ramshackle', 6);
INSERT INTO `words` VALUES (15817, 'cattle ranching', 'n. 大牧场', '/\'ræntʃɪŋ/', 'ranching', 6);
INSERT INTO `words` VALUES (15818, 'rancid butter', 'adj. 象油脂腐臭味的, 腐臭的', '/\'rænsid | \'rænsɪd/', 'rancid', 6);
INSERT INTO `words` VALUES (15819, 'Give us the ballot and we will quietly and nonviolently, without rancor or bitterness, implement the Supreme Court\'s decision of May 17, 1954.', 'n. 深仇, 怨恨', '/\'ræŋkə/', 'rancor', 6);
INSERT INTO `words` VALUES (15820, 'The deal ended after a series of rancorous disputes.', 'adj. 深恨的, 怀恶意的', '/\'ræŋkərəs/', 'rancorous', 6);
INSERT INTO `words` VALUES (15821, NULL, 'n. 狂欢, 三人划的小艇', '/\'rændæn, ræn\'d- | ræn\'dæn/', 'randan', 6);
INSERT INTO `words` VALUES (15822, NULL, 'adj. <主苏格兰>粗鲁的, 好色的', '/\'rændi | \'rændɪ/', 'randy', 6);
INSERT INTO `words` VALUES (15823, 'His comments still rankled.', 'v. 溃烂, 发炎, 怨恨', '/\'ræŋkl | \'ræŋk(ə)l/', 'rankle', 6);
INSERT INTO `words` VALUES (15824, 'The whole flat had been ransacked.', 'v. 到处搜索, 掠夺, 洗劫', '/\'rænsæk/', 'ransack', 6);
INSERT INTO `words` VALUES (15825, 'The police caught the man who tried to abduct the boy for ransom.', 'n. 敲诈, 勒索', '/\'rænsəm | \'ræns(ə)m/', 'ransom', 6);
INSERT INTO `words` VALUES (15826, 'Why don’t you stop ranting and raving for a minute and listen?', 'v. 大声责骂； 咆哮', '/rænt/', 'rant', 6);
INSERT INTO `words` VALUES (15827, 'She was woken by a sharp rap on the door.', 'n. 叩击, 轻拍, 轻敲, 斥责', '/ræp/', 'rap', 6);
INSERT INTO `words` VALUES (15828, 'rapacious landlords', 'adj. 掠夺的, 贪婪的', '/rə\'peiʃəs | rə\'peɪʃəs | rə\'peʃəs/', 'rapacious', 6);
INSERT INTO `words` VALUES (15829, 'He argued that the overcrowded cities were the product of a system based on \"selfishness\" and \"rapacity.\"', 'n. 贪婪, 掠夺', '/rə\'pæsəti/', 'rapacity', 6);
INSERT INTO `words` VALUES (15830, 'His canoe was there, on the river below the rapids.', 'n. 急流， 湍流', '/\'ræpɪdz/', 'rapids', 6);
INSERT INTO `words` VALUES (15831, 'It is not enough that ecclesiastical men abstain from violence and rapine and all manner of persecution.', 'n. 抢夺, 掠夺', '/\'ræpain, -pin | \'ræpaɪn; -pɪn | \'ræpɪn/', 'rapine', 6);
INSERT INTO `words` VALUES (15832, 'And last but not least, people with whom you can build a rapport and camaraderie with.', 'n. 和谐, 亲善', '/ræ\'pɔ:t | ræ\'pɔː | ræ\'pɔr/', 'rapport', 6);
INSERT INTO `words` VALUES (15833, 'There have been growing signs of a rapprochement with Vietnam.', 'n. 和睦, 亲善', '/,rɑ:prɔʃ\'mɔŋ | ,rɑːprɒʃ\'mɒŋ | ,ræproʃ\'mɑn/', 'rapprochement', 6);
INSERT INTO `words` VALUES (15834, 'They listened with rapt attention .', 'adj. 全神贯注的', '/ræpt/', 'rapt', 6);
INSERT INTO `words` VALUES (15835, 'Compared with omnivorous pheasants, insectivorous birds and raptorial birds Koklass\'s digestive system is similar to the typical phytophagous birds.', 'adj. 捕食生物的, 猛禽类的', '/,ræp\'tɔ:riəl | ræp\'tɔːrɪəl | ræp\'torɪəl/', 'raptorial', 6);
INSERT INTO `words` VALUES (15836, 'The boys gazed up at him in rapture.', 'n. 全神贯注, 兴高采烈, 欢天喜地', '/\'ræptʃə | \'ræptʃɚ/', 'rapture', 6);
INSERT INTO `words` VALUES (15837, 'She was greeted with rapturous applause .', 'adj. 兴高采烈的, 欢天喜地的', '/\'ræptʃərəs/', 'rapturous', 6);
INSERT INTO `words` VALUES (15838, 'This is called a rarefaction and is represented by widely spaced dots.', 'n. 稀薄', '/,rεəri\'fækʃən | ˌrerɪ\'fækʃn/', 'rarefaction', 6);
INSERT INTO `words` VALUES (15839, NULL, 'v. 使稀少， 使稀薄', '/\'rerəfaɪ | \'rɛrə,fai/', 'rarefy', 6);
INSERT INTO `words` VALUES (15840, 'He is raring to charge into the fray and lay down the law.', 'adj. 渴望的, 急切的', '/\'rεəriŋ | \'rɛrɪŋ/', 'raring', 6);
INSERT INTO `words` VALUES (15841, NULL, 'n. 轻率, 不瞻前顾后', '/\'ræʃnis/', 'rashness', 6);
INSERT INTO `words` VALUES (15842, 'my father’s rasping voice', 'v. 发出刺耳的声音； 锉， 刮削', '/ræsp/', 'rasp', 6);
INSERT INTO `words` VALUES (15843, 'Both men sang in a deep, raspy tone.', 'adj. 刺耳的； 易怒的', '/\'ræspi/', 'raspy', 6);
INSERT INTO `words` VALUES (15844, 'This was demonstrated in a laboratory experiment with rats.', 'n. 老鼠', '/ræt/', 'rat', 6);
INSERT INTO `words` VALUES (15845, 'We welcome this development and we look forward to early ratification of the treaty by China.', 'n. 正式批准', '/ˌrætɪfɪ\'keɪʃn | ,rætəfə\'keʃən/', 'ratification', 6);
INSERT INTO `words` VALUES (15846, 'The parliaments of Australia and Indonesia have yet to ratify the treaty.', 'v. 批准', '/\'rætɪfaɪ/', 'ratify', 6);
INSERT INTO `words` VALUES (15847, 'Mr Bush is a convert to an evangelical Christianity that emphasises emotion—particularly the intensely emotional experience of being born again—over ratiocination.', 'n. 推理, 推论', '/,rætiɔsi\'neiʃən, -ræʃi-/', 'ratiocination', 6);
INSERT INTO `words` VALUES (15848, 'Fuel was rationed during the war.', 'v. 定量配给; n. 配给', '/\'ræʃn | \'ræʃən/', 'ration', 6);
INSERT INTO `words` VALUES (15849, 'However, the rationale for such initiatives is not, of course, solely economic.', 'n. 基本原理', '/,ræʃə\'nɑ:li, -\'næ- | ,ræʃə\'nɑːl | ,ræʃə\'næl/', 'rationale', 6);
INSERT INTO `words` VALUES (15850, 'His mocking smile rattled her more than his anger.', 'v. 使发出咯咯声； 使慌乱', '/\'rætl/', 'rattle', 6);
INSERT INTO `words` VALUES (15851, 'He burst into raucous laughter .', 'adj. 沙哑的', '/\'rɔ:kəs | \'rɔːkəs | \'rɔkəs/', 'raucous', 6);
INSERT INTO `words` VALUES (15852, 'a raunchy magazine', 'adj. <美俚>邋遢的, 肮脏的, 淫秽的', '/\'rɔ:ntʃi, \'rɑ:, \'rau- | \'rɔːn(t)ʃɪ/', 'raunchy', 6);
INSERT INTO `words` VALUES (15853, 'The country has been ravaged by civil war.', 'v. 摧毁， 使荒废', '/\'rævɪdʒ/', 'ravage', 6);
INSERT INTO `words` VALUES (15854, 'He was still ranting and raving the next morning.', 'v. 咆哮', '/reiv | reɪv | rev/', 'rave', 6);
INSERT INTO `words` VALUES (15855, NULL, 'v. 使纠缠， 纠结； 拆开， 拆散', '/\'rævl/', 'ravel', 6);
INSERT INTO `words` VALUES (15856, 'A rapacious divorcee on the prowl; ravening creditors; paying taxes to voracious governments.', 'adj. 狼吞虎咽的； 贪婪的', '/\'rævənɪŋ/', 'ravening', 6);
INSERT INTO `words` VALUES (15857, 'Amy realized that she had eaten nothing since leaving home that morning, and she was ravenous.', 'adj. 贪婪的, 渴望的, 狼吞虎咽的', '/\'rævənəs | \'ræv(ə)nəs/', 'ravenous', 6);
INSERT INTO `words` VALUES (15858, 'The bus overturned and fell into a ravine.', 'n. 沟壑, 峡谷, 溪谷', '/rə\'vi:n | rə\'viːn | rə\'vin/', 'ravine', 6);
INSERT INTO `words` VALUES (15859, 'She\'ll never know how close she came to being dragged off and ravished.', 'v. 强夺', '/\'ræviʃ | \'rævɪʃ/', 'ravish', 6);
INSERT INTO `words` VALUES (15860, 'She looked ravishing.', 'adj. 引人入胜的', '/\'ræviʃiŋ | \'rævɪʃɪŋ/', 'ravishing', 6);
INSERT INTO `words` VALUES (15861, NULL, 'n. 强夺, 销魂', '/\'ræviʃmənt/', 'ravishment', 6);
INSERT INTO `words` VALUES (15862, 'At his belt he carried a rawhide whip.', 'n. 生牛皮, <美>生牛皮鞭', '/\'rɔ:haid | \'rɔːhaɪd | \'rɔhaɪd/', 'rawhide', 6);
INSERT INTO `words` VALUES (15863, 'In 1162 Milan was razed to the ground by imperial troops.', 'v. 夷为平地； 彻底破坏', '/reɪz | rez/', 'raze', 6);
INSERT INTO `words` VALUES (15864, 'an electric razor', 'n. 剃刀', '/\'reizə | \'reɪzə | \'rezɚ/', 'razor', 6);
INSERT INTO `words` VALUES (15865, NULL, 'n. 眼花缭乱, 喧闹, 旋转木马', '/\'ræzl/', 'razzle', 6);
INSERT INTO `words` VALUES (15866, 'reactionary attitudes', 'adj. 反作用的, 反动的', '/rɪ\'ækʃ(ə)n(ə)rɪ | rɪ\'ækʃənɛri/', 'reactionary', 6);
INSERT INTO `words` VALUES (15867, '...a series of economic reforms to reactivate the economy.', 'v. (使)恢复活动', '/ri\'æktiveit, ri:- | rɪ\'æktɪveɪt | rɪ\'æktɪvet/', 'reactivate', 6);
INSERT INTO `words` VALUES (15868, 'This is a well researched and very readable book.', 'adj. 易读的', '/\'riːdəbl | \'ridəbl/', 'readable', 6);
INSERT INTO `words` VALUES (15869, 'Jack readily agreed to help.', 'adv. 乐意地； 容易地', '/\'redɪli | \'rɛdɪli/', 'readily', 6);
INSERT INTO `words` VALUES (15870, 'They need to have ready access to police files.', 'adj. 敏捷的， 迅速的', '/\'redi | \'rɛdi/', 'ready', 6);
INSERT INTO `words` VALUES (15871, 'The party reaffirmed its commitment to nuclear disarmament.', 'v. 再次确定； 重申', '/ˌriːə\'fɜːrm | \'riə\'fɝm/', 'reaffirm', 6);
INSERT INTO `words` VALUES (15872, 'He mentioned the recent NDRC-World Bank Report as a positive reaffirmation of future policy directions which leading foreign investors hope to see realized.', 'n. 再肯定', '/ri\'əfə:meiʃən | ˌriːˌæfər\'meɪʃn/', 'reaffirmation', 6);
INSERT INTO `words` VALUES (15873, NULL, 'n. 反应力, 反应物, 试剂', '/ri:\'eidʒənt | rɪ\'eɪdʒ(ə)nt | rɪ\'edʒənt/', 'reagent', 6);
INSERT INTO `words` VALUES (15874, 'The company is planning to realign its sales operations.', 'v. 重新排列', '/ˌriːə\'laɪn | ,riə\'laɪn/', 'realign', 6);
INSERT INTO `words` VALUES (15875, 'Is this a realistic target?', 'adj. 现实主义的', '/ˌriːə\'lɪstɪk | ,riə\'lɪstɪk/', 'realistic', 6);
INSERT INTO `words` VALUES (15876, 'the spiritual realm', 'n. 王国； 领域， 范围', '/relm | rɛlm/', 'realm', 6);
INSERT INTO `words` VALUES (15877, 'Their specific task is to sort through the reams of information and try to determine what it means.', 'n. 令, 大量的纸', '/ri:m | riːm | rim/', 'ream', 6);
INSERT INTO `words` VALUES (15878, 'You\'ll soon begin to reap the benefits of being fitter.', 'v. 收割， 收获', '/riːp | rip/', 'reap', 6);
INSERT INTO `words` VALUES (15879, NULL, 'n. 收割者, 收割机', '/\'riːpə | \'ripɚ/', 'reaper', 6);
INSERT INTO `words` VALUES (15880, 'Parents are looking for reassurance about their children’s safety.', 'n. 放心', '/,ri:ə\'ʃuərəns | riːə\'ʃʊərəns | ,riə\'ʃʊrəns/', 'reassurance', 6);
INSERT INTO `words` VALUES (15881, 'Teachers reassured anxious parents.', 'v. 使恢复信心； 使确信', '/ˌriːə\'ʃur | ,riə\'ʃʊr/', 'reassure', 6);
INSERT INTO `words` VALUES (15882, 'For the moment no matter the business that it can reave how many KTV truly, sheet sees it swim to be not a net the consequence that players produce and appeal, already had great value.', 'v. 剥夺, 抢走', '/ri:v | riːv/', 'reave', 6);
INSERT INTO `words` VALUES (15883, 'My parents want me to stay here, this rebarbative city.', 'adj. 令人讨厌的', '/ri\'bɑ:bətiv | rɪ\'bɑːbətɪv/', 'rebarbative', 6);
INSERT INTO `words` VALUES (15884, 'Deposit any random checks you get - like rebate, rewards or reimbursement checks - into this fund.', 'n. 回扣, 折扣', '/\'ri:beit, ri\'beit | \'riːbeɪt | \'ribet/', 'rebate', 6);
INSERT INTO `words` VALUES (15885, 'rebellious teenagers', 'adj. 造反的, 反叛的, 反抗的, 难于对付的', '/ri\'beljəs | rɪ\'beljəs | rɪ\'bɛljəs/', 'rebellious', 6);
INSERT INTO `words` VALUES (15886, 'There\'s no rebroadcast of the soccer game tonight.', 'v. 重播', '/rɪ\'brɔːdkæst | ,ri\'brɔdkæst/', 'rebroadcast', 6);
INSERT INTO `words` VALUES (15887, 'He received a humiliating rebuff from his manager.', 'n. 回绝', '/ri\'bʌf | rɪ\'bʌf/', 'rebuff', 6);
INSERT INTO `words` VALUES (15888, 'His statements drew a stinging rebuke from the chairman.', 'n. 指责, 谴责, 非难', '/ri\'bju:k | rɪ\'bjuːk | rɪ\'bjʊk/', 'rebuke', 6);
INSERT INTO `words` VALUES (15889, 'It can be likened to a rebus, which uses pictures and single letters, or numbers to represent whole words (e.g, \"i <3 u\" means “I love you”, b4 means before, lol means laugh out loud, etc. ).', 'n. (猜字的)画谜', '/\'ri:bəs | \'riːbəs | \'ribəs/', 'rebus', 6);
INSERT INTO `words` VALUES (15890, 'He is conducting a point-by-point rebuttal of charges from former colleagues.', 'n. 辩驳, 举反证', '/ri\'bʌtəl | rɪ\'bʌtl/', 'rebuttal', 6);
INSERT INTO `words` VALUES (15891, 'They chastise Mr Netanyahu for his recalcitrance.', 'n. 反抗, 顽抗', '/ri\'kælsitrəns/', 'recalcitrance', 6);
INSERT INTO `words` VALUES (15892, 'a recalcitrant pupil', 'adj. 反抗的, 反对的, 顽抗的', '/ri\'kælsitrənt | rɪ\'kælsɪtr(ə)nt | rɪ\'kælsɪtrənt/', 'recalcitrant', 6);
INSERT INTO `words` VALUES (15893, 'You don’t happen to recall his name, do you?', 'v. 回想，回忆起；收回; n. 唤回', '/rɪ\'kɔːl | \'rikɔl/', 'recall', 6);
INSERT INTO `words` VALUES (15894, 'White House officials ordered Williams to recant.', 'v. 放弃', '/ri\'kænt | rɪ\'kænt/', 'recant', 6);
INSERT INTO `words` VALUES (15895, NULL, 'n. 取消前言, 改变论调', '/,ri:kæn\'teiʃən/', 'recantation', 6);
INSERT INTO `words` VALUES (15896, 'Let\'s just recapitulate the essential points.', 'v. 重述要点, 概括, 摘要', '/,ri:kæpitjuleit | ,riːkə\'pɪtjʊleɪt | \'rikə\'pɪtʃə\'let/', 'recapitulate', 6);
INSERT INTO `words` VALUES (15897, 'an attempt to recast the statement in less formal language', 'v. 重铸； 更换演员)', '/ˌriː\'kæst | ,ri\'kæst/', 'recast', 6);
INSERT INTO `words` VALUES (15898, 'The flood waters finally began to recede in November.', 'v. 后退', '/rɪ\'siːd | rɪ\'sid/', 'recede', 6);
INSERT INTO `words` VALUES (15899, 'Keep your receipt in case you want to bring it back.', 'n. 收到， 接到； 发票， 收据', '/rɪ\'siːt | rɪ\'sit/', 'receipt', 6);
INSERT INTO `words` VALUES (15900, 'a trash receptacle', 'n. 容器, [植]花托, [电工]插座', '/ri\'septəkl | rɪ\'septək(ə)l | rɪ\'sɛptəkl/', 'receptacle', 6);
INSERT INTO `words` VALUES (15901, 'You might find them in a more receptive mood tomorrow.', 'adj. 善于接受的, 能接纳的', '/ri\'septiv | rɪ\'septɪv | rɪ\'sɛptɪv/', 'receptive', 6);
INSERT INTO `words` VALUES (15902, 'the deep recesses of the cave', 'n. (墙壁等的)凹进处, [解]隐窝', '/ri\'ses, \'ri:ses | rɪ\'ses; \'riːses | \'risɛs/', 'recess', 6);
INSERT INTO `words` VALUES (15903, 'the economic recession of the early 1980s', 'n. 撤回, 退回, 退后, 工商业之衰退, 不景气', '/ri\'seʃən | rɪ\'seʃ(ə)n | rɪ\'sɛʃən/', 'recession', 6);
INSERT INTO `words` VALUES (15904, 'An example of negative eugenics would be the attempt to eradicate a harmful recessive gene.', 'adj. 退行的, 逆行的, [遗]隐性的', '/ri\'sesiv | rɪ\'sesɪv | rɪ\'sɛsɪv/', 'recessive', 6);
INSERT INTO `words` VALUES (15905, NULL, 'adj. 讲究的, 罕有的,异国风味的', '/rə\'ʃɛrʃe | ˌrəʃer\'ʃeɪ/', 'recherche', 6);
INSERT INTO `words` VALUES (15906, 'Depending on the recidivism rate, the government will pay investors in the first bond a return of 7.5-13%—or nothing, if the promised improvement is not achieved.', 'n. 累犯', '/ri\'sidivizəm | rɪ\'sɪdɪvɪzəm | rɪ\'sɪdə,vɪzəm/', 'recidivism', 6);
INSERT INTO `words` VALUES (15907, 'a recipe book', 'n. 食谱', '/\'resəpi | \'rɛsəpi/', 'recipe', 6);
INSERT INTO `words` VALUES (15908, '...the largest recipient of U.S. foreign aid.', 'n. 接受者， 收受者', '/rɪ\'sɪpiənt | rɪ\'sɪpɪənt/', 'recipient', 6);
INSERT INTO `words` VALUES (15909, 'He spoke of the necessity for a reciprocal relationship that would be useful for all sides.', 'adj. 互惠的, 相应的, 倒数的, 彼此相反的', '/ri\'siprəkəl | rɪ\'sɪprək(ə)l | rɪ\'sɪprəkl/', 'reciprocal', 6);
INSERT INTO `words` VALUES (15910, NULL, 'adv. 相互地； 相反地', '/ri\'siprəkli | rɪ\'sɪprəkli/', 'reciprocally', 6);
INSERT INTO `words` VALUES (15911, 'I would like to think the way I treat people is reciprocated.', 'v. 互给, 酬答, 互换, 报答', '/ri\'siprəkeit | rɪ\'sɪprəkeɪt | rɪ\'sɪprəket/', 'reciprocate', 6);
INSERT INTO `words` VALUES (15912, NULL, 'n. 互换； 报答； 往复运动', '/ri,siprə\'keiʃən | rɪˌsɪprə\'keɪʃn/', 'reciprocation', 6);
INSERT INTO `words` VALUES (15913, 'They said they would press for reciprocity with Greece in the issuing of visas.', 'n. 互惠', '/,resi\'prɔsəti | ,resɪ\'prɒsɪtɪ | ,rɛsɪ\'prɑsəti/', 'reciprocity', 6);
INSERT INTO `words` VALUES (15914, 'a piano recital', 'n. 朗诵, 背诵, 叙述, 独奏会, 独唱会', '/ri\'saitəl | rɪ\'saɪt(ə)l | rɪ\'saɪtl/', 'recital', 6);
INSERT INTO `words` VALUES (15915, 'He was accused of causing death by reckless driving .', 'adj. 不计后果的', '/\'reklis | \'reklɪs | \'rɛkləs/', 'reckless', 6);
INSERT INTO `words` VALUES (15916, 'He soon regretted his recklessness.', 'n. 鲁莽， 轻率', '/\'rekləsnəs | \'reklisnis/', 'recklessness', 6);
INSERT INTO `words` VALUES (15917, 'The expression ‘full moon’ means the fourteenth day of the moon reckoned from its first appearance.', 'v. 推断， 估计； 猜想， 设想', '/\'rekən | \'rɛkən/', 'reckon', 6);
INSERT INTO `words` VALUES (15918, 'You may be entitled to reclaim some tax.', 'v. 要求归还, 收回, 开垦', '/ri\'kleim | rɪ\'kleɪm | rɪ\'klem/', 'reclaim', 6);
INSERT INTO `words` VALUES (15919, 'She proceeded to recline on a chaise longue.', 'v. 斜倚， 躺卧', '/rɪ\'klaɪn/', 'recline', 6);
INSERT INTO `words` VALUES (15920, 'Stained glass windows, ceramic chimney and floral motifs adorn the house and make it an awe inspiring space for recluse.', 'adj. 隐遁的, 寂寞的', '/ri\'klu:s, \'reklu:s | rɪ\'kluːs | \'rɛklus/', 'recluse', 6);
INSERT INTO `words` VALUES (15921, 'All that neighbours knew about the reclusive man was that he had lived in the building for about 20 years.', 'adj. 隐遁的， 隐居的', '/rɪ\'kluːsɪv | rɪ\'klʊsɪv/', 'reclusive', 6);
INSERT INTO `words` VALUES (15922, '...his small body jerking in recoil from the volume of his shouting.', 'n. 畏缩, 后退, 弹回, 反作用, 后座力', '/ri\'kɔil, \'ri:kɔil | rɪ\'kɒɪl | \'rikɔɪl/', 'recoil', 6);
INSERT INTO `words` VALUES (15923, 'All I recollect is a grey sky.', 'v. 回忆； 想起', '/ˌrekə\'lekt | \'rɛkə\'lɛkt/', 'recollect', 6);
INSERT INTO `words` VALUES (15924, 'My earliest recollections are of my mother bending over my cot.', 'n. 记忆力； 往事', '/ˌrekə\'lekʃn | ,rɛkə\'lɛkʃən/', 'recollection', 6);
INSERT INTO `words` VALUES (15925, 'Then, if the mix of waste is correct, the carbon and oxygen atoms involved recombine to form carbon monoxide and the hydrogen atoms link up into diatomic hydrogen molecules.', 'v. 重组， 再结合', '/,ri:kəm\'bain | ˌriːkəm\'baɪn/', 'recombine', 6);
INSERT INTO `words` VALUES (15926, 'Try to get letters of recommendation from bosses and colleagues.', 'n. 推荐； 推荐信', '/ˌrekəmen\'deɪʃn | ,rɛkəmɛn\'deʃən/', 'recommendation', 6);
INSERT INTO `words` VALUES (15927, 'If they succeed in court, they will be fully recompensed for their loss.', 'v. 报偿', '/\'rekəmpens | \'rɛkəm\'pɛns/', 'recompense', 6);
INSERT INTO `words` VALUES (15928, NULL, 'v. 重写； 重新安排', '/ˌrɪkəm\'pouz | ,ri:kəm\'pəuz/', 'recompose', 6);
INSERT INTO `words` VALUES (15929, 'Jonah and his youngest son were, on the surface at least, reconciled.', 'v. 使和解, 使和谐, 使顺从', '/\'rekənsail | \'rek(ə)nsaɪl | \'rɛkənsaɪl/', 'reconcile', 6);
INSERT INTO `words` VALUES (15930, 'Her ex-husband had always hoped for a reconciliation.', 'n. 和解, 调和, 顺从', '/,rekənsili\'eiʃən | ,rek(ə)nsɪlɪ\'eɪʃ(ə)n | ,rɛkənsɪlɪ\'eʃən/', 'reconciliation', 6);
INSERT INTO `words` VALUES (15931, 'Her poems are modishly experimental in style and recondite in subject matter.', 'adj. 深奥的, 隐藏的, 晦涩的', '/ri\'kɔndait, \'rekən- | \'rek(ə)ndaɪt; rɪ\'kɒn- | \'rɛkəndaɪt/', 'recondite', 6);
INSERT INTO `words` VALUES (15932, 'a reconditioned engine', 'v. 修理, 使复原, 使正常', '/,ri:kən\'diʃən | riːkən\'dɪʃ(ə)n | \'rikən\'dɪʃən/', 'recondition', 6);
INSERT INTO `words` VALUES (15933, 'reconnaissance aircraft', 'n. 侦察, 搜索, 勘测', '/ri\'kɔnisəns | rɪ\'kɒnɪs(ə)ns | rɪ\'kɑnɪsns/', 'reconnaissance', 6);
INSERT INTO `words` VALUES (15934, 'Conceal, reconnoiter, assault!', 'v. 侦察， 勘察', '/ˌrekə\'nɔɪtər | ,rikə\'nɔɪtɚ/', 'reconnoiter', 6);
INSERT INTO `words` VALUES (15935, 'He then recounted the story of the interview for his first job.', 'v. 叙述', '/ri\'kaunt | rɪ\'kaʊnt/', 'recount', 6);
INSERT INTO `words` VALUES (15936, 'Insurance companies are trying to recoup their losses by increasing premiums.', 'v. 赔偿, 补偿, 扣除', '/ri\'ku:p | rɪ\'kuːp/', 'recoup', 6);
INSERT INTO `words` VALUES (15937, 'We may conclude that he never had recourse to this simple experiment.', 'n. 求援, 求助, [商][律]追索权', '/ri\'kɔ:s, \'ri:kɔ:s | rɪ\'kɔːs | \'rikɔrs/', 'recourse', 6);
INSERT INTO `words` VALUES (15938, 'I think I am a coward, a recreant and a fool. Even now I don\'t know how to react when he shows me his eyes and grin.', 'adj. 怯懦的', '/\'rekriənt | \'rekrɪənt | \'rɛkrɪənt/', 'recreant', 6);
INSERT INTO `words` VALUES (15939, 'His only recreations are drinking beer and watching football.', 'n. 消遣, 娱乐', '/,rekri\'eiʃən, -kri:- | ,rekrɪ\'eɪʃ(ə)n | ,rɛkrɪ\'eʃən/', 'recreation', 6);
INSERT INTO `words` VALUES (15940, '...parks and other recreational facilities.', 'adj. 娱乐的， 休闲的', '/ˌrekri\'eɪʃənl | ,rɛkri\'eʃənəl/', 'recreational', 6);
INSERT INTO `words` VALUES (15941, NULL, 'v. 反责, 反唇相讥, 反控诉', '/ri\'krimineit | rɪ\'krɪmɪneɪt/', 'recriminate', 6);
INSERT INTO `words` VALUES (15942, 'New recruits are sent to the Atlanta office for training.', 'n. 新兵, 新分子, 新会员', '/ri\'kru:t | rɪ\'kruːt | rɪ\'krut/', 'recruit', 6);
INSERT INTO `words` VALUES (15943, '...the rectification of an injustice.', 'n. 纠正, 整顿, 校正, 精馏, 整流', '/,rektifi\'keiʃən | ,rektɪfɪ\'keɪʃən | ,rɛktəfə\'keʃən/', 'rectification', 6);
INSERT INTO `words` VALUES (15944, 'I did my best to rectify the situation, but the damage was already done.', 'v. 矫正, 调整, [化]精馏', '/\'rektifai | \'rektɪfaɪ | \'rɛktɪfaɪ/', 'rectify', 6);
INSERT INTO `words` VALUES (15945, '...people of the utmost moral rectitude.', 'n. 正直, 公正, 清廉, 笔直', '/\'rektitju:d, -tu:d | \'rektɪtjuːd | \'rɛktɪtʊd/', 'rectitude', 6);
INSERT INTO `words` VALUES (15946, 'He looked down at the recumbent figure.', 'adj. 靠着的, 斜躺着的, 不活动的, 休息的', '/ri\'kʌmbənt | rɪ\'kʌmb(ə)nt | rɪ\'kʌmbənt/', 'recumbent', 6);
INSERT INTO `words` VALUES (15947, 'Winston proposed several ways for the industry to recuperate.', 'v. 复原', '/ri\'kju:pəreit | rɪ\'kuːpəreɪt | rɪ\'kupəret/', 'recuperate', 6);
INSERT INTO `words` VALUES (15948, 'a recuperative vacation', 'adj. 使恢复的, 有恢复力的', '/ri\'kju:pəreitiv | rɪ\'kʊpərətɪv/', 'recuperative', 6);
INSERT INTO `words` VALUES (15949, 'There is a danger that the disease may recur.', 'v. 重现， 再发生； 复发', '/rɪ\'kɜːr | rɪ\'kɝ/', 'recur', 6);
INSERT INTO `words` VALUES (15950, NULL, 'n. 复发, 重现, 循环', '/ri\'kʌrəns, -\'kə:- | rɪ\'kʌrəns | rɪ\'kɝəns/', 'recurrence', 6);
INSERT INTO `words` VALUES (15951, 'recurrent minor illnesses', 'adj. 循环的； 一再发生的', '/rɪ\'kɜːrənt | rɪ\'kɝənt/', 'recurrent', 6);
INSERT INTO `words` VALUES (15952, NULL, 'adj. 反复的； 再次发生的', '/rɪ\'kɜːrɪŋ | rɪ\'kɝɪŋ/', 'recurring', 6);
INSERT INTO `words` VALUES (15953, 'I come from a recusant family and was educated at Catholic schools.', 'adj. 不服权威的', '/\'rekjuzənt, ri\'kju:- | \'rekjʊz(ə)nt | rə\'kjuzənt/', 'recusant', 6);
INSERT INTO `words` VALUES (15954, 'Olivier’s performance redeemed an otherwise second-rate play.', 'v. 赎回, 挽回, 恢复, 补偿, 兑换', '/ri\'di:m | rɪ\'diːm | rɪ\'dim/', 'redeem', 6);
INSERT INTO `words` VALUES (15955, 'He craves redemption for his sins.', 'n. 赎回, 偿还, 拯救, 履行', '/ri\'dempʃən | rɪ\'dem(p)ʃ(ə)n | rɪ\'dɛmpʃən/', 'redemption', 6);
INSERT INTO `words` VALUES (15956, '...the redemptive power of Christ.', 'adj. 赎回的， 救赎的， 挽回的', '/rɪ\'demptɪv | rɪ\'dɛmptɪv/', 'redemptive', 6);
INSERT INTO `words` VALUES (15957, NULL, 'vt. 使恢复完整, 使更新, 重建', '/re\'dɪntɪgreɪt | rɛ\'dɪntə,gret/', 'redintegrate', 6);
INSERT INTO `words` VALUES (15958, 'The flight was redirected to Cleveland.', 'v. 改寄； 改变方向', '/ˌriːdə\'rekt | [ˌridɪˈrɛkt,-daɪ-]/', 'redirect', 6);
INSERT INTO `words` VALUES (15959, 'Sports motions can cause the redistribution of viscera blood flow.', 'n. 重新分配', '/,ri:distri\'bju:ʃən | ˌriːdɪ\'strɪbjuːʃn/', 'redistribution', 6);
INSERT INTO `words` VALUES (15960, 'Soon, patchouli redolent shawls become fashionable in the 19th century France, paralleling the rise of patchouli as a fragrance ingredient.', 'adj. 芬芳的', '/\'redəulənt | \'redəl(ə)nt | \'rɛdələnt/', 'redolent', 6);
INSERT INTO `words` VALUES (15961, 'He had never met a more redoubtable fighter.', 'adj. 可怕的', '/ri\'dautəbl | rɪ\'daʊtəb(ə)l | rɪ\'daʊtəbl/', 'redoubtable', 6);
INSERT INTO `words` VALUES (15962, 'The success in the Middle East redounds to his benefit.', 'v. 有助于', '/ri\'daund | rɪ\'daʊnd/', 'redound', 6);
INSERT INTO `words` VALUES (15963, 'The only hope of redress is in a lawsuit.', 'n. 赔偿, 救济, 矫正', '/ri\'dres | rɪ\'dres | rɪ\'drɛs/', 'redress', 6);
INSERT INTO `words` VALUES (15964, 'This means that they have no redundancy.', 'n. 冗余', '/ri\'dʌndənsi | rɪ\'dʌnd(ə)nsɪ | rɪ\'dʌndənsi/', 'redundancy', 6);
INSERT INTO `words` VALUES (15965, 'the removal of redundant information', 'adj. 多余的', '/ri\'dʌndənt | rɪ\'dʌnd(ə)nt | rɪ\'dʌndənt/', 'redundant', 6);
INSERT INTO `words` VALUES (15966, 'He smelled the reek of whisky.', 'n. <主苏格兰>烟, 水蒸汽, 雾, 臭气', '/ri:k | riːk | rik/', 'reek', 6);
INSERT INTO `words` VALUES (15967, NULL, 'adj. 烟雾弥漫的', NULL, 'reeky', 6);
INSERT INTO `words` VALUES (15968, 'a cotton reel', 'v. 卷…于轴上; n. 卷轴；旋转', '/riːl | ril/', 'reel', 6);
INSERT INTO `words` VALUES (15969, NULL, 'v. 再制定 again)', '/,ri:i\'nækt, -e\'n- | rɪɪ\'nækt/', 'reenact', 6);
INSERT INTO `words` VALUES (15970, NULL, 'n. 重考； 复试； 再检查', '/rɪɪgˌzæmɪ\'neɪʃn | \'riɪɡ,zæmɪ\'nɛɡʃən/', 'reexamination', 6);
INSERT INTO `words` VALUES (15971, 'Conclusions Using HACCP method in refectory obtained good effect.', 'n. 餐厅， 食堂', '/rɪ\'fektri | rɪ\'fɛktri/', 'refectory', 6);
INSERT INTO `words` VALUES (15972, 'His headmaster agreed to act as his referee.', 'n. 仲裁人, 调解人, [体]裁判员', '/,refə\'ri: | refə\'riː | ,rɛfə\'ri/', 'referee', 6);
INSERT INTO `words` VALUES (15973, 'Here, too, we see how this unverbalized visceral flow is used as a referent.', 'n. 指示对象', '/\'refərənt | \'rɛfərənt/', 'referent', 6);
INSERT INTO `words` VALUES (15974, 'Older cars inevitably lack the latest safety refinements.', 'n. 精致, (言谈, 举止等的)文雅, 精巧', '/ri\'fainmənt | rɪ\'faɪnm(ə)nt | rɪ\'faɪnmənt/', 'refinement', 6);
INSERT INTO `words` VALUES (15975, 'The drop in consumer spending reflects concern about the economy.', 'v. 反射, 反映, 表现, 反省, 细想', '/rɪ\'flekt | rɪ\'flɛkt/', 'reflect', 6);
INSERT INTO `words` VALUES (15976, 'Can you see your reflection in the glass?', 'n. 反射, 映象, 倒影, 反省, 沉思, 反映', '/re\'flekʃən | rɪ\'flekʃ(ə)n | rɪ\'flɛkʃən/', 'reflection', 6);
INSERT INTO `words` VALUES (15977, 'She was in a reflective mood.', 'adj. 沉思的', '/ri\'flektiv | rɪ\'flektɪv | rɪ\'flɛktɪv/', 'reflective', 6);
INSERT INTO `words` VALUES (15978, NULL, 'n. <法>(陶瓷器等表面的)光彩, 光泽', '/rə\'fle/', 'reflet', 6);
INSERT INTO `words` VALUES (15979, NULL, 'adj. 反射的, 反省的, 反作用的, 优角的', '/\'ri:fleks | \'riːfleks | \'riflɛks/', 'reflex', 6);
INSERT INTO `words` VALUES (15980, NULL, 'vt. 使振作精神', '/ri:\'fɔsileit/', 'refocillate', 6);
INSERT INTO `words` VALUES (15981, 'The sonobuoy permits recording a refraction profile with only one ship.', 'n. 折射', '/rɪ\'frækʃn | rɪ\'frækʃən/', 'refraction', 6);
INSERT INTO `words` VALUES (15982, '...refractory priests who refused to side with the king.', 'adj. 难控制的, 难熔的', '/ri\'fræktəri | rɪ\'frækt(ə)rɪ | rɪ\'fræktəri/', 'refractory', 6);
INSERT INTO `words` VALUES (15983, 'Our proposal met with the constant refrain that the company could not afford it.', 'n. 重复, 叠句, [乐]副歌', '/,ri:\'frein | rɪ\'freɪn | rɪ\'fren/', 'refrain', 6);
INSERT INTO `words` VALUES (15984, 'The lotion cools and refreshes the skin.', 'v. 消除…的疲劳， 使精神振作', '/rɪ\'freʃ | ri\'frɛʃ/', 'refresh', 6);
INSERT INTO `words` VALUES (15985, 'Refrigerate the mixture overnight.', 'v. 使冷却， 冷藏', '/rɪ\'frɪdʒəreɪt | rɪ\'frɪdʒəret/', 'refrigerate', 6);
INSERT INTO `words` VALUES (15986, 'By the reappearance of the different types, different symbols torii in Huizhou, it posts the refulgence and heaviness of the traditional culture of Huizhou.', 'n. 光辉', '/ri\'fʌldʒəns, ri:-/', 'refulgence', 6);
INSERT INTO `words` VALUES (15987, 'Answer: Anyone can use a happy feeling to wish a refulgent result.', 'adj. 辉煌的, 灿烂的', '/ri\'fʌldʒənt, ri:- | rɪ\'fʌldʒ(ə)nt | rɪ\'fʌldʒənt/', 'refulgent', 6);
INSERT INTO `words` VALUES (15988, 'We have spent money on refurbishing the offices.', 'v. 再磨光, 刷新', '/,ri:\'fə:biʃ | riː\'fɜːbɪʃ | ,ri\'fɝbɪʃ/', 'refurbish', 6);
INSERT INTO `words` VALUES (15989, 'It was the kind of rumour that it is impossible to refute.', 'v. 驳倒, 反驳', '/ri\'fju:t, ri:- | rɪ\'fjuːt | ri\'fjʊt/', 'refute', 6);
INSERT INTO `words` VALUES (15990, 'a ceremony of regal splendour', 'adj. 帝王的, 适于帝王的', '/\'ri:ɡəl | \'riːg(ə)l/', 'regal', 6);
INSERT INTO `words` VALUES (15991, 'Disclosure: This reporter also lives in New Haven and has heard Chua regale friends with parenting stories.', 'v. 享受', '/rɪ\'geɪl | rɪ\'ɡel/', 'regale', 6);
INSERT INTO `words` VALUES (15992, 'Small nodules form as the liver cells regenerate.', 'v. 使新生, 重建, 改革, 革新', '/ri\'dʒenəreit, ri:- | rɪ\'dʒenəreɪt | rɪ\'dʒɛnəret/', 'regenerate', 6);
INSERT INTO `words` VALUES (15993, NULL, 'n. 摄政者, 董事', '/\'ri:dʒənt | \'riːdʒ(ə)nt | \'ridʒənt/', 'regent', 6);
INSERT INTO `words` VALUES (15994, 'The regime got rid of most of its opponents.', 'n. 政体, 政权, 政权制度', '/rei\'ʒi:m, ri-, ri\'dʒi:m | reɪ\'ʒiːm | re\'ʒim/', 'regime', 6);
INSERT INTO `words` VALUES (15995, 'Patients maintain a strict dietary regimen.', 'n. 摄生法, 政权, 政体', '/\'redʒimen, -mən | \'redʒɪmən | \'rɛdʒɪmən/', 'regimen', 6);
INSERT INTO `words` VALUES (15996, NULL, 'n. 团, 大群', '/\'redʒimənt | \'redʒɪm(ə)nt | \'rɛdʒɪmənt/', 'regiment', 6);
INSERT INTO `words` VALUES (15997, 'Mills was regimental colonel.', 'adj. 团的， 团队的', '/ˌredʒɪ\'mentl | ,rɛdʒɪ\'mɛntl/', 'regimental', 6);
INSERT INTO `words` VALUES (15998, 'Democracy is incompatible with excessive, bureaucratic regimentation of social life.', 'n. 管辖', '/,redʒimen\'teiʃən/', 'regimentation', 6);
INSERT INTO `words` VALUES (15999, NULL, 'adj. 统治的, 占优势的, 居支配地位的', '/\'reɡnənt | \'regnənt/', 'regnant', 6);
INSERT INTO `words` VALUES (16000, 'If your child regresses to babyish behaviour, all you know for certain is that the child is under stress.', 'v. 倒退， 复归， 逆行', '/rɪ\'gres | rɪ\'ɡrɛs/', 'regress', 6);
INSERT INTO `words` VALUES (16001, 'There has been an increase in regressive autism, children who develop normally, have speech, and then lose it.', 'adj. 回归的', '/ri\'ɡresiv | rɪ\'gresɪv | rɪ\'ɡrɛsɪv/', 'regressive', 6);
INSERT INTO `words` VALUES (16002, NULL, 'adv. 懊悔地', '/rɪ\'gretfəli | rɪ\'ɡrɛtfəli/', 'regretfully', 6);
INSERT INTO `words` VALUES (16003, 'strict rules regulating the use of chemicals in food', 'v. 管制, 控制, 调节, 校准', '/\'reɡjuleit | \'regjʊleɪt | \'rɛɡjulet/', 'regulate', 6);
INSERT INTO `words` VALUES (16004, 'There seem to be so many rules and regulations these days.', 'n. 规则, 规章, 调节, 校准', '/,reɡju\'leiʃən | regjʊ\'leɪʃ(ə)n | ˌrɛɡjəˈleʃən/', 'regulation', 6);
INSERT INTO `words` VALUES (16005, NULL, 'adj. 按规矩来的， 依照规章的； 调整的', '/\'reɡjulətəri | \'regjələtɔːri/', 'regulatory', 6);
INSERT INTO `words` VALUES (16006, 'Some birds and animals regurgitate food to feed their young.', 'v. (使)涌回, (使)流回, (使)反刍', '/ri\'ɡə:dʒiteit, ri:- | rɪ\'gɜːdʒɪteɪt | rɪ\'ɡɝdʒɪtet/', 'regurgitate', 6);
INSERT INTO `words` VALUES (16007, 'The Prime Minister seems to be trying to rehabilitate the former defence secretary.', 'v. 使(身体)康复, 使复职, 使恢复名誉, 使复原', '/,ri:hə\'biliteit | riːə\'bɪlɪteɪt | ,riə\'bɪlə,tet/', 'rehabilitate', 6);
INSERT INTO `words` VALUES (16008, 'He simply rehashed the same story.', 'v. 改头换面地重复', '/,ri:\'hæʃ | riː\'hæʃ | ,ri\'hæʃ/', 'rehash', 6);
INSERT INTO `words` VALUES (16009, 'a wedding rehearsal', 'n. 排演, 演习, 预演, 试演', '/ri\'hə:səl | rɪ\'hɜːs(ə)l | rɪ\'hɝsl/', 'rehearsal', 6);
INSERT INTO `words` VALUES (16010, 'I think we need to rehearse the first scene again.', 'v. 排练， 预演； 详述', '/rɪ\'hɜːrs | rɪ\'hɝs/', 'rehearse', 6);
INSERT INTO `words` VALUES (16011, 'For several minutes confusion reigned .', 'v. 统治, 支配, 盛行, 占优势', '/rein | reɪn | ren/', 'reign', 6);
INSERT INTO `words` VALUES (16012, '...the reigning world champion.', 'adj. 统治的， 起支配作用的', '/\'reɪnɪŋ | \'reiniŋ/', 'reigning', 6);
INSERT INTO `words` VALUES (16013, 'I\'ll be happy to reimburse you for any expenses you\'ve had.', 'v. 偿还', '/,ri:im\'bə:s | ,riːɪm\'bɜːs | ,riɪm\'bɝs/', 'reimburse', 6);
INSERT INTO `words` VALUES (16014, 'She is demanding reimbursement for medical and other expenses.', 'n. 付还, 退还', '/,ri:im\'bə:smənt | ,ri:ɪm\'bɜ:smənt | ,riɪm\'bɝsmənt/', 'reimbursement', 6);
INSERT INTO `words` VALUES (16015, 'Cord held the reins while the stallion tugged and snorted.', 'n. 缰绳, 统治, 支配', '/rein | reɪn | ren/', 'rein', 6);
INSERT INTO `words` VALUES (16016, '...their belief that human souls were reincarnated in the bodies of turtles.', 'v. 赋予新肉体, 使转生', '/ri:\'inkɑ:neit, ,ri:in\'k- | ,riːɪn\'kɑːneɪt | ,riɪn\'kɑrnet/', 'reincarnate', 6);
INSERT INTO `words` VALUES (16017, 'Many African tribes believe in reincarnation.', 'n. 再投胎, 化身, 再生', '/,ri:inkɑ:\'neiʃən | ,riːɪnkɑː\'neɪʃ(ə)n | ,riɪnkɑr\'neʃən/', 'reincarnation', 6);
INSERT INTO `words` VALUES (16018, 'California reinstated the death penalty in 1977.', 'v. 恢复', '/,ri:in\'steit | riːɪn\'steɪt | ,riɪn\'stet/', 'reinstate', 6);
INSERT INTO `words` VALUES (16019, 'Let me reiterate the most important points.', 'v. 反复地说, 重申, 重做', '/ri:\'itəreit | riː\'ɪtəreɪt | rɪ\'ɪtəret/', 'reiterate', 6);
INSERT INTO `words` VALUES (16020, 'Garbo plays the queen, rejoicing in the love she has found with Antonio.', 'v. (使)欣喜, (使)高兴, 喜悦', '/ri\'dʒɔis | rɪ\'dʒɒɪs | rɪ\'dʒɔɪs/', 'rejoice', 6);
INSERT INTO `words` VALUES (16021, 'I personally haven\'t tasted any entomological specimens lately, but I am still rejoicing in the limitless curiosity, the draws me to books and people and places.I hope I never lose it.', 'n. 欣喜, 高兴', '/ri\'dʒɔisiŋ | rɪ\'dʒɒɪsɪŋ | rɪ\'dʒɔɪsɪŋ/', 'rejoicing', 6);
INSERT INTO `words` VALUES (16022, '‘I don’t care!’ she rejoined.', 'v. 使再结合, 再加入, 再回答', '/,ri:\'dʒɔin, ri- | riː\'dʒɒɪn | ,ri\'dʒɔɪn/', 'rejoin', 6);
INSERT INTO `words` VALUES (16023, 'But pause for a moment: if government will do a worse job running the banks, the rejoinder is \"worse than whom\"?', 'n. 反驳', '/ri\'dʒɔində | rɪ\'dʒɒɪndə | rɪ\'dʒɔɪndɚ/', 'rejoinder', 6);
INSERT INTO `words` VALUES (16024, 'plans to rejuvenate the inner city areas', 'v. 使年轻, 使复原, 使恢复精神, 使恢复活力, 使回春, 使更新', '/ri\'dʒu:vineit | rɪ\'dʒuːvəneɪt | rɪ\'dʒuvənet/', 'rejuvenate', 6);
INSERT INTO `words` VALUES (16025, 'The trial has rekindled painful memories of the war.', 'v. 重新点燃', '/,ri:\'kindl | riː\'kɪnd(ə)l | ,ri\'kɪndl/', 'rekindle', 6);
INSERT INTO `words` VALUES (16026, 'She had a relapse and died soon after.', 'n. 复发, 回复原状', '/ri:\'leæps, ri\'læps, \'ri:læps | rɪ\'læps/', 'relapse', 6);
INSERT INTO `words` VALUES (16027, 'I play the piano for relaxation.', 'n. 松弛, 放宽, 缓和, 减轻, 娱乐', '/,ri:læk\'seiʃən | riːlæk\'seɪʃ(ə)n | \'rilæk\'seʃən/', 'relaxation', 6);
INSERT INTO `words` VALUES (16028, 'Might it not be better to relegate the king to a purely ceremonial function?', 'v. 转移, 归入, 提交', '/\'reliɡeit | \'relɪgeɪt | \'rɛlɪɡet/', 'relegate', 6);
INSERT INTO `words` VALUES (16029, 'At last her father relented and came to visit her.', 'v. 变宽厚, 变温和', '/ri\'lent | rɪ\'lent | rɪ\'lɛnt/', 'relent', 6);
INSERT INTO `words` VALUES (16030, 'her relentless determination to succeed', 'adj. 无情的', '/ri\'lentlis | rɪ\'lentlɪs | rɪ\'lɛntləs/', 'relentless', 6);
INSERT INTO `words` VALUES (16031, 'I think we can all appreciate the relevance of that now.', 'n. 中肯, 适当', '/\'relivəns | \'reləvəns | \'rɛləvəns/', 'relevance', 6);
INSERT INTO `words` VALUES (16032, 'a birth control method that is cheap and reliable', 'adj. 可信赖的; n. 可信赖的人', '/rɪ\'laɪəbl/', 'reliable', 6);
INSERT INTO `words` VALUES (16033, 'the country’s heavy reliance on trade', 'n. 信任, 信心, 依靠, 依靠的人或物', '/ri\'laiəns | rɪ\'laɪəns/', 'reliance', 6);
INSERT INTO `words` VALUES (16034, 'Roman relics found in a field', 'n. 遗物, 遗迹, 废墟, 纪念物', '/\'relik | \'relɪk | \'rɛlɪk/', 'relic', 6);
INSERT INTO `words` VALUES (16035, NULL, 'n. [古]未亡人, 寡妇, 残余物, [生物, 生态]残余体', '/\'relikt, ri\'likt | \'relɪkt | \'rɛlɪkt/', 'relict', 6);
INSERT INTO `words` VALUES (16036, 'Drugs helped to relieve the pain.', 'v. 减轻， 解除', '/rɪ\'liːv | rɪ\'liv/', 'relieve', 6);
INSERT INTO `words` VALUES (16037, 'A relieved smile spread over his face.', 'adj. 宽慰的， 如释重负的', '/rɪ\'liːvd | rɪ\'livd/', 'relieved', 6);
INSERT INTO `words` VALUES (16038, 'The snow reprints it as it were in clear white type alto-relievo.', 'n. 浮雕', '/ri\'li:vəu, ril\'jevəu | rɪ\'liːvəʊ | rɪl\'jɛvo/', 'relievo', 6);
INSERT INTO `words` VALUES (16039, 'The U.S. Constitution promises freedom of religion.', 'n. 宗教； 宗教信仰', '/rɪ\'lɪdʒən/', 'religion', 6);
INSERT INTO `words` VALUES (16040, 'No one wants to relinquish power once they have it.', 'v. 放弃', '/ri\'liŋkwiʃ | rɪ\'lɪŋkwɪʃ/', 'relinquish', 6);
INSERT INTO `words` VALUES (16041, 'a hot dog with mustard and relish', 'n. 意味', '/\'relɪʃ | \'rɛlɪʃ/', 'relish', 6);
INSERT INTO `words` VALUES (16042, 'When come to the pure, clear, quiet, relucent and beauteous Lugu Lake, welcome you to A-pu Country House, and while you discover the splendor, share your sprightliness.', 'adj. 光辉的, 明亮的', '/rɪ\'ljuːsənt | rɪ\'lʊsənt/', 'relucent', 6);
INSERT INTO `words` VALUES (16043, 'Wells finally agreed, but with reluctance.', 'n. 勉强， 不情愿', '/rɪ\'lʌktəns/', 'reluctance', 6);
INSERT INTO `words` VALUES (16044, 'The remainder must be paid by the end of June.', 'n. 残余, 剩余物, 其他的人, [数]余数', '/ri\'meində | rɪ\'meɪndə | rɪ\'mendɚ/', 'remainder', 6);
INSERT INTO `words` VALUES (16045, 'extensive Roman remains (= of ancient buildings ) at Arles', 'n. 残余, 遗迹, 遗体', '/ri\'meinz | rɪ\'meɪnz | rɪ\'menz/', 'remains', 6);
INSERT INTO `words` VALUES (16046, 'Carter was remanded in custody for seven days.', 'v. 遣回； 召回', '/rɪ\'mænd/', 'remand', 6);
INSERT INTO `words` VALUES (16047, 'She has made remarkable progress.', 'adj. 值得注意的， 显著的', '/rɪ\'mɑːrkəbl | rɪ\'mɑrkəbl/', 'remarkable', 6);
INSERT INTO `words` VALUES (16048, 'remediable problems', 'adj. 可挽回的', '/ri\'mi:diəbl, -djə- | rɪ\'miːdɪəb(ə)l | rɪ\'midɪəbl/', 'remediable', 6);
INSERT INTO `words` VALUES (16049, 'The last thing you\'d want is a constant reminder of a bad experience.', 'n. 提醒物， 纪念品', '/rɪ\'maɪndər | rɪ\'maɪndɚ/', 'reminder', 6);
INSERT INTO `words` VALUES (16050, 'Drink a glass of wine, coffee, or tea, read a good book, or watch a good movie. Look at old photographs and reminisce.', 'v. 回忆', '/,remi\'nis | ,remɪ\'nɪs | ,rɛmɪ\'nɪs/', 'reminisce', 6);
INSERT INTO `words` VALUES (16051, 'Here I am boring you with my reminiscences.', 'n. 回想, 记忆力, 怀旧', '/,remi\'nisəns | remɪ\'nɪs(ə)ns | \'rɛmə\'nɪsns/', 'reminiscence', 6);
INSERT INTO `words` VALUES (16052, 'a style strongly reminiscent of Virginia Woolf’s novels', 'adj. 回忆的； 使人联想的', '/ˌremɪ\'nɪsnt | ,rɛmɪ\'nɪsnt/', 'reminiscent', 6);
INSERT INTO `words` VALUES (16053, 'I would be remiss if I did not do something about it.', 'adj. 玩忽职守的', '/ri\'mis | rɪ\'mɪs/', 'remiss', 6);
INSERT INTO `words` VALUES (16054, 'remission of debts', 'n. 免除', '/ri\'miʃən | rɪ\'mɪʃ(ə)n | rɪ\'mɪʃən/', 'remission', 6);
INSERT INTO `words` VALUES (16055, 'Please remit payment by cheque.', 'v. 宽恕, 赦免, 免除, 缓和, 推迟, 汇出, 传送, 使复职', '/ri\'mit, \'ri:mit | rɪ\'mɪt | \'rimɪt/', 'remit', 6);
INSERT INTO `words` VALUES (16056, 'Please enclose your remittance, making checks payable to Valley Technology Services.', 'n. 汇款, 汇寄之款, 汇款额', '/ri\'mitəns | rɪ\'mɪt(ə)ns | rɪ\'mɪtns/', 'remittance', 6);
INSERT INTO `words` VALUES (16057, NULL, 'adj. 间歇性的', '/ri\'mitənt | rɪ\'mɪt(ə)nt | rɪ\'mɪtnt/', 'remittent', 6);
INSERT INTO `words` VALUES (16058, 'Beneath the present church were remnants of Roman flooring.', 'n. 残余, 剩余, 零料, 残迹', '/\'remnənt | \'rɛmnənt/', 'remnant', 6);
INSERT INTO `words` VALUES (16059, 'The airport terminals have been extensively remodelled.', 'v. 重新塑造, 改造, 改变', '/,ri:\'mɔdəl | riː\'mɒd(ə)l | ,ri\'mɑdl/', 'remodel', 6);
INSERT INTO `words` VALUES (16060, 'angry remonstrances', 'n. 抗议', '/ri\'mɔnstrəns | rɪ\'mɒnstr(ə)ns | rɪ\'mɑnstrəns/', 'remonstrance', 6);
INSERT INTO `words` VALUES (16061, 'He remonstrated with the referee.', 'v. 抗议', '/\'remənstreit, ri\'mɔn- | \'remənstreɪt | rɪ\'mɑnstret/', 'remonstrate', 6);
INSERT INTO `words` VALUES (16062, 'Throughout the trial, he had shown no remorse .', 'n. 懊悔, 自责, 同情, 怜悯', '/ri\'mɔ:s | rɪ\'mɔːs | rɪ\'mɔrs/', 'remorse', 6);
INSERT INTO `words` VALUES (16063, NULL, 'adv. 冷酷地， 无悔意地', '/ri\'mɔ:slisli | rɪ\'mɔːrsləsli/', 'remorselessly', 6);
INSERT INTO `words` VALUES (16064, 'a remote border town', 'adj. 遥远的； 偏僻的', '/rɪ\'mout | rɪ\'mot/', 'remote', 6);
INSERT INTO `words` VALUES (16065, 'Its development represents man\'s triumph over remoteness and a harsh landscape.', 'n. 遥远； 偏僻', '/ri\'məutnis | rɪ\'moutnəs/', 'remoteness', 6);
INSERT INTO `words` VALUES (16066, 'You will be remunerated and so will your staff.', 'v. 酬劳', '/ri\'mju:nəreit | rɪ\'mjuːnəreɪt | rɪ\'mjunəret/', 'remunerate', 6);
INSERT INTO `words` VALUES (16067, 'A doctor advised her to seek remunerative employment.', 'adj. 有报酬的, 有利的', '/ri\'mju:nərətiv, -rei- | rɪ\'mjuːn(ə)rətɪv | rɪ\'mjunərətɪv/', 'remunerative', 6);
INSERT INTO `words` VALUES (16068, '...the Renaissance masterpieces in London\'s galleries.', 'n. 复兴, 复活, 新生, 文艺复兴, 文艺复兴时期', '/\'rɛnəsɑns | rɪ\'neɪsəns/', 'renaissance', 6);
INSERT INTO `words` VALUES (16069, 'acute renal failure', 'adj. 肾脏的, 肾的', '/\'ri:nəl | \'riːn(ə)l | \'rinl/', 'renal', 6);
INSERT INTO `words` VALUES (16070, 'Voters have come back to a renascent Labour Party.', 'adj. 新生的, 复活的, 复兴的', '/ri\'næsənt, -\'nei- | rɪ\'næs(ə)nt; \'neɪ- | rɪ\'nesənt/', 'renascent', 6);
INSERT INTO `words` VALUES (16071, '...pain that rends the heart.', 'v. 撕碎', '/rend | rɛnd/', 'rend', 6);
INSERT INTO `words` VALUES (16072, 'It contained so many errors as to render it worthless.', 'v. 呈递, 归还, 着色, 汇报, 致使, 放弃, 表演, 实施', '/\'rendə | \'rɛndɚ/', 'render', 6);
INSERT INTO `words` VALUES (16073, '...a rendering of Verdi\'s Requiem by the Chicago Symphony Orchestra.', 'n. 翻译, 表现, 描写, 透视图, 粉刷, 表演, 打底, 复制图', '/\'rendəriŋ | \'rend(ə)rɪŋ | \'rɛndərɪŋ/', 'rendering', 6);
INSERT INTO `words` VALUES (16074, NULL, 'n. 集合点', '/\'rɔndivu:, -dei- | \'rɒndɪvuː; -deɪvuː | \'rɑndevʊ/', 'rendezvous', 6);
INSERT INTO `words` VALUES (16075, 'He gave a moving rendition of Lennon’s ‘Imagine’.', 'n. 表演， 演唱', '/ren\'dɪʃn | rɛn\'dɪʃən/', 'rendition', 6);
INSERT INTO `words` VALUES (16076, 'a renegade army unit', 'n. 背教者, 变节者, 叛徒', '/\'reniɡeid | \'renɪgeɪd | \'rɛnɪɡed/', 'renegade', 6);
INSERT INTO `words` VALUES (16077, 'He reneged on a promise to leave his wife.', 'v. 食言, 违例出牌', '/ri\'ni:ɡ, -\'neiɡ, -\'niɡ, -\'neɡ | rɪ\'neɪg; rɪ\'niːg | rɪ\'niɡ/', 'renege', 6);
INSERT INTO `words` VALUES (16078, '...a political lobbyist concentrating on urban renewal and regeneration.', 'n. 更新； 复兴， 振兴', '/rɪ\'nuːəl | rɪ\'nuəl/', 'renewal', 6);
INSERT INTO `words` VALUES (16079, 'These groups must renounce violence if there is to be progress towards peace.', 'v. 断绝关系', '/ri\'nauns | rɪ\'naʊns/', 'renounce', 6);
INSERT INTO `words` VALUES (16080, 'The hotel has been renovated and redecorated.', 'v. 翻新， 修复， 整修', '/\'renəveɪt | \'rɛnəvet/', 'renovate', 6);
INSERT INTO `words` VALUES (16081, 'He achieved some renown as a football player.', 'n. 名声, 传闻, 谣传', '/ri\'naun | rɪ\'naʊn/', 'renown', 6);
INSERT INTO `words` VALUES (16082, 'The area is renowned for its Romanesque churches.', 'adj. 有名的, 有声誉的', '/ri\'naund | rɪ\'naʊnd/', 'renowned', 6);
INSERT INTO `words` VALUES (16083, 'Most students rent rooms in their second year.', 'v. 租, 租借, 出租', '/rent | rɛnt/', 'rent', 6);
INSERT INTO `words` VALUES (16084, NULL, 'v. 放弃', '/rɪ\'nʌnsɪ3ɪt | ri\'nʌnsieit/', 'renunciate', 6);
INSERT INTO `words` VALUES (16085, 'The talks were dependent on a renunciation of terrorism.', 'n. 放弃, 弃权, 脱离关系', '/ri,nʌnsi\'eiʃən | rɪnʌnsɪ\'eɪʃ(ə)n | rɪ,nʌnsɪ\'eʃən/', 'renunciation', 6);
INSERT INTO `words` VALUES (16086, 'a reparable loss', 'adj. 可修缮的, 可赔偿的, 可恢复的', '/\'repərəbl | \'rep(ə)rəb(ə)l | \'rɛpərəbl/', 'reparable', 6);
INSERT INTO `words` VALUES (16087, 'The government agreed to pay reparations to victims.', 'n. 赔偿, 弥补, 恢复, 修理', '/,repə\'reiʃən | ,repə\'reɪʃ(ə)n | ˌrepəˈreɪʃn/', 'reparation', 6);
INSERT INTO `words` VALUES (16088, 'witty repartee', 'n. 巧妙的应答, 巧妙应答之才能', '/,repɑ:\'ti:, -pə- | ,repɑː\'tiː | ,rɛpə\'ti/', 'repartee', 6);
INSERT INTO `words` VALUES (16089, 'After the war, prisoners were repatriated.', 'v. 遣返', '/ri:\'pætrieit, -\'pei- | riː\'pætrɪeɪt; -\'peɪ- | ,ri\'petrɪet/', 'repatriate', 6);
INSERT INTO `words` VALUES (16090, 'The government has just repealed the law segregating public facilities.', 'v. 废止, 撤销, 否定, 放弃, 废除', '/ri\'pi:l | rɪ\'piːl | rɪ\'pil/', 'repeal', 6);
INSERT INTO `words` VALUES (16091, 'The smell repelled him.', 'v. 击退, 抵制, 使厌恶, 使不愉快', '/ri\'pel | rɪ\'pel | rɪ\'pɛl/', 'repel', 6);
INSERT INTO `words` VALUES (16092, 'Why This Works: Talcum powder, an ingredient in both chalk and baby powder, is a natural ant repellent.', 'adj. 排斥的', '/ri\'pelənt | rɪ\'pel(ə)nt | rɪ\'pɛlənt/', 'repellent', 6);
INSERT INTO `words` VALUES (16093, 'Those who refuse to repent, he said, will be punished.', 'v. 后悔, 悔改, 忏悔, 悔悟', '/ri\'pent | rɪ\'pent | rɪ\'pɛnt/', 'repent', 6);
INSERT INTO `words` VALUES (16094, 'They showed no repentance during their trial.', 'n. 后悔, 悔改', '/ri\'pentəns | rɪ\'pent(ə)ns | rɪ\'pɛntəns/', 'repentance', 6);
INSERT INTO `words` VALUES (16095, 'He was feeling guilty and depressed, repentant and scared.', 'adj. 后悔的, 悔改的, 有悔改表现的', '/ri\'pentənt | rɪ\'pentənt | rɪ\'pɛntənt/', 'repentant', 6);
INSERT INTO `words` VALUES (16096, NULL, 'n. 弹回, 反响, (光、声等的)反射', '/riːpə\'kʌʃ(ə)n | ,ripɚ\'kʌʃən/', 'repercussion', 6);
INSERT INTO `words` VALUES (16097, 'the behavioural repertoire of infants', 'n. (准备好演出的)节目, 保留剧目, (计算机的)指令表, 指令系统, <美>(某个人的)全部技能', '/\'repətwɑ: | \'repətwɑː | \'rɛpɚ\'twɑr/', 'repertoire', 6);
INSERT INTO `words` VALUES (16098, 'Children used to learn by repetition.', 'n. 重复； 背诵', '/ˌrepə\'tɪʃn | \'rɛpə\'tɪʃən/', 'repetition', 6);
INSERT INTO `words` VALUES (16099, 'repetitious work', 'adj. 重复的', '/ˌrepə\'tɪʃəs | ,rɛpə\'tɪʃəs/', 'repetitious', 6);
INSERT INTO `words` VALUES (16100, 'The song was dreary and repetitive.', 'adj. 重复的； 反复性的', '/rɪ\'petətɪv | rɪ\'pɛtətɪv/', 'repetitive', 6);
INSERT INTO `words` VALUES (16101, 'This is the common fate of mortal men, useless it is to repine .', 'v. 抱怨', '/ri\'pain | rɪ\'paɪn/', 'repine', 6);
INSERT INTO `words` VALUES (16102, 'Our old car is badly in need of replacement.', 'n. 归还, 复位, 交换, 代替者, 补充兵员, 置换, 移位', '/ri\'pleismənt | rɪ\'pleɪsm(ə)nt | rɪ\'plesmənt/', 'replacement', 6);
INSERT INTO `words` VALUES (16103, 'More vaccines are needed to replenish our stocks.', 'v. 补充', '/ri\'pleniʃ | rɪ\'plenɪʃ | rɪ\'plɛnɪʃ/', 'replenish', 6);
INSERT INTO `words` VALUES (16104, 'The harbour was replete with boats.', 'adj. 充满的', '/ri\'pli:t | rɪ\'pliːt | rɪ\'plit/', 'replete', 6);
INSERT INTO `words` VALUES (16105, NULL, 'n. 充满, 饱满', '/ri\'pli:ʃən/', 'repletion', 6);
INSERT INTO `words` VALUES (16106, 'replica guns', 'n. 复制品', '/\'replikə | \'replɪkə | \'rɛplɪkə/', 'replica', 6);
INSERT INTO `words` VALUES (16107, 'There is a need for further research to replicate these findings.', 'v. 复制', '/\'replikit, \'replikeit | \'replɪkeɪt | \'rɛplɪket/', 'replicate', 6);
INSERT INTO `words` VALUES (16108, 'The astonishing distrust of the news media isn\'t rooted in inaccuracy or poor reportorial skills but in the daily clash of world views between reporters and their readers.', 'adj. 记者的； 报道的', '/,repə\'tɔ:riəl | ˌrepər\'tɔːriəl/', 'reportorial', 6);
INSERT INTO `words` VALUES (16109, 'He had a still, almost blank face in repose.', 'n. 休息, 睡眠, 静止', '/ri\'pəuz | rɪ\'pəʊz | rɪ\'poz/', 'repose', 6);
INSERT INTO `words` VALUES (16110, 'Its running is reposeful. The cutting is accurate, the production efficiency is high. It is assorted equipment of foam foaming machine.', 'adj. 平稳的, 沉着的', '/ri\'pəuzful | rɪ\'pəʊzfʊl/', 'reposeful', 6);
INSERT INTO `words` VALUES (16111, 'A church in Moscow became a repository for police files.', 'n. 贮藏室, 智囊团, 知识库, 仓库', '/ri\'pɔzitəri | rɪ\'pɒzɪt(ə)rɪ | rɪ\'pɑzə\'tɔri/', 'repository', 6);
INSERT INTO `words` VALUES (16112, 'Eventually the bailiffs came to repossess the flat.', 'v. 收回, 复得', '/,ri:pə\'zes | ,riːpə\'zes | ,ripə\'zɛs/', 'repossess', 6);
INSERT INTO `words` VALUES (16113, 'For if our heart reprehend us, God is greater than our heart, and knoweth all things.', 'n. 责备', '/,repri\'hend | ,reprɪ\'hend/', 'reprehend', 6);
INSERT INTO `words` VALUES (16114, 'I find their behaviour morally reprehensible .', 'adj. 应斥责的, 应该谴责的', '/,repri\'hensəbl | ,reprɪ\'hensɪb(ə)l | ,rɛprɪ\'hɛnsəbl/', 'reprehensible', 6);
INSERT INTO `words` VALUES (16115, 'Mr Kobayashi was chosen to represent the company at the conference.', 'v. 呈现； 代表； 体现', '/ˌreprɪ\'zent | ,rɛprɪ\'zɛnt/', 'represent', 6);
INSERT INTO `words` VALUES (16116, 'The police were widely criticized for their role in repressing the protest movement.', 'v. <美>再压, 补充加压', '/ri\'pres | rɪ\'pres | rɪ\'prɛs/', 'repress', 6);
INSERT INTO `words` VALUES (16117, 'a repressed middle-aged woman', 'adj. 被抑制的， 被压抑的', '/rɪ\'prest | rɪ\'prɛst/', 'repressed', 6);
INSERT INTO `words` VALUES (16118, 'a repressive regime', 'adj. 压抑的, 压制的', '/ri\'presiv | rɪ\'presɪv | rɪ\'prɛsɪv/', 'repressive', 6);
INSERT INTO `words` VALUES (16119, 'As for my unlikely allies, I think that I shall allow them a reprieve.', 'n. 缓刑(尤指缓期执行死刑), 缓刑令, (痛苦, 烦恼等的)暂缓', '/ri\'pri:v | rɪ\'priːv | rɪ\'priv/', 'reprieve', 6);
INSERT INTO `words` VALUES (16120, 'He has been fined five thousand dollars and given a severe reprimand.', 'n. 申斥', '/\'reprimɑ:nd, repri\'m-, -mænd, -\'mænd | \'reprɪmɑːnd | \'rɛprɪmænd/', 'reprimand', 6);
INSERT INTO `words` VALUES (16121, 'They didn’t tell the police for fear of reprisal .', 'n. 报复', '/ri\'praizəl | rɪ\'praɪz(ə)l | rɪ\'praɪzl/', 'reprisal', 6);
INSERT INTO `words` VALUES (16122, 'She is quick to reproach anyone who doesn\'t live up to her own high standards.', 'v. 责备', '/ri\'prəutʃ | rɪ\'prəʊtʃ | rɪ\'protʃ/', 'reproach', 6);
INSERT INTO `words` VALUES (16123, '...a drunken reprobate.', 'v. 非难', '/\'reprəubeit | \'reprəbeɪt | \'rɛprəbet/', 'reprobate', 6);
INSERT INTO `words` VALUES (16124, 'Scientists studied the reproduction, diet, and health of the dolphins.', 'n. 繁殖, 再现, 复制品', '/,ri:prə\'dʌkʃən | riːprə\'dʌkʃ(ə)n | ,riprə\'dʌkʃən/', 'reproduction', 6);
INSERT INTO `words` VALUES (16125, 'She raised her eyebrows in reproof.', 'n. 谴责, 非难', '/ri\'pru:f | rɪ\'pruːf | rɪ\'pruf/', 'reproof', 6);
INSERT INTO `words` VALUES (16126, '\"There\'s no call for talk like that,\" Mrs. Evans reproved him.', 'v. 责备', '/ri\'pru:v | rɪ\'pruːv | rɪ\'pruv/', 'reprove', 6);
INSERT INTO `words` VALUES (16127, '...a prehistoric jungle occupied by reptilian creatures.', 'adj. 象爬虫的', '/rep\'tiliən | rep\'tɪlɪən | rɛp\'tɪlɪən/', 'reptilian', 6);
INSERT INTO `words` VALUES (16128, 'Leaders urged people to turn out in large numbers to repudiate the violence.', 'v. 批判', '/ri\'pju:dieit | rɪ\'pjuːdɪeɪt | rɪ\'pjudɪet/', 'repudiate', 6);
INSERT INTO `words` VALUES (16129, NULL, 'n. 拒绝接受， 否认', '/rɪˌpjuːdi\'eɪʃn | rɪ,pjʊdɪ\'eʃən/', 'repudiation', 6);
INSERT INTO `words` VALUES (16130, NULL, 'v. 反对, 反抗', '/ri\'pju:n | rɪ\'pju:n | rɪ\'pjun/', 'repugn', 6);
INSERT INTO `words` VALUES (16131, 'If we gave the least expression to our natural repugnance for this meal, no sense of responsibility for our health could prompt him to press it on us a second time.', 'n. 不一致', '/ri\'pʌɡnəns | rɪ\'pʌgnəns | rɪ\'pʌɡnəns/', 'repugnance', 6);
INSERT INTO `words` VALUES (16132, 'I have never beaten my wife and never will. I find assault of others completely repugnant, and assault of women especially so.', 'adj. 不一致的', '/ri\'pʌɡnənt | rɪ\'pʌgnənt | rɪ\'pʌɡnənt/', 'repugnant', 6);
INSERT INTO `words` VALUES (16133, 'Government troops repulsed an attack by rebel forces.', 'v. 拒绝, 排斥, 反驳, 击退, 憎恶', '/ri\'pʌls | rɪ\'pʌls/', 'repulse', 6);
INSERT INTO `words` VALUES (16134, 'I felt a mixture of amazement and repulsion.', 'n. 厌恶， 反感； 排斥力', '/rɪ\'pʌlʃn | rɪ\'pʌlʃən/', 'repulsion', 6);
INSERT INTO `words` VALUES (16135, 'Many people find slugs repulsive.', 'adj. 推斥的, 排斥的, 严拒的, 令人厌恶的', '/ri\'pʌlsiv | rɪ\'pʌlsɪv/', 'repulsive', 6);
INSERT INTO `words` VALUES (16136, 'If the company is a member, it’s a good sign that they are reputable (but not always).', 'adj. 著名的', '/\'repjutəbl | \'repjʊtəb(ə)l | \'rɛpjətəbl/', 'reputable', 6);
INSERT INTO `words` VALUES (16137, 'Alice Munro has a reputation for being a very depressing writer.', 'n. 名誉, 名声', '/,repju\'teiʃən | repjʊ\'teɪʃ(ə)n | ,rɛpju\'teʃən/', 'reputation', 6);
INSERT INTO `words` VALUES (16138, 'Under his leadership, the U.N.\'s repute has risen immeasurably.', 'v. 认为，以为; n. 名声， 名誉', '/rɪ\'pjuːt | rɪ\'pjut/', 'repute', 6);
INSERT INTO `words` VALUES (16139, '...a performance of Verdi\'s Requiem.', 'n. [天主教]安灵祢撒, 安灵曲, 挽歌, 悲歌', '/\'rekwiəm, \'rei-, \'ri:-/', 'requiem', 6);
INSERT INTO `words` VALUES (16140, 'He lacks the requisite qualifications.', 'adj. 需要的, 必不可少的, 必备的', '/\'rekwizit | \'rekwɪzɪt | \'rɛkwəzɪt/', 'requisite', 6);
INSERT INTO `words` VALUES (16141, '...a requisition for a replacement photocopier.', 'n. 正式请求, 申请, 需要, 命令, 征用, 通知单', '/,rekwi\'ziʃən | ,rekwɪ\'zɪʃ(ə)n | \'rɛkwə\'zɪʃən/', 'requisition', 6);
INSERT INTO `words` VALUES (16142, 'He gave her in requital of all things else, which ye had taken from me.', 'n. 偿还', '/ri\'kwaitəl | rɪ\'kwaɪtəl/', 'requital', 6);
INSERT INTO `words` VALUES (16143, 'I thank you, and can but requite your good deeds with my prayers.', 'v. 报答, 酬谢', '/ri\'kwait | rɪ\'kwaɪt/', 'requite', 6);
INSERT INTO `words` VALUES (16144, 'The governor does not have the authority to rescind the ruling.', 'v. 废除', '/ri\'sind | rɪ\'sɪnd/', 'rescind', 6);
INSERT INTO `words` VALUES (16145, 'Finally, analyze that the right of rescission is discharged firstly.', 'n. 撤销， 废除', '/rɪ\'sɪʒn/', 'rescission', 6);
INSERT INTO `words` VALUES (16146, NULL, 'n. 官方命令, 抄件', '/\'ri:skript | \'riːskrɪpt/', 'rescript', 6);
INSERT INTO `words` VALUES (16147, 'Survivors of the crash were rescued by helicopter.', 'v. 解救；把…从法律监管下强行夺回; n. 解救', '/\'reskjuː | \'rɛskju/', 'rescue', 6);
INSERT INTO `words` VALUES (16148, 'There was a remarkable resemblance between him and Pete.', 'n. 类同之处', '/ri\'zembləns | rɪ\'zembl(ə)ns | rɪ\'zɛmbləns/', 'resemblance', 6);
INSERT INTO `words` VALUES (16149, 'It’s amazing how closely Brian and Steve resemble each other.', 'v. 与…相似， 像', '/rɪ\'zembl | rɪ\'zɛmbl/', 'resemble', 6);
INSERT INTO `words` VALUES (16150, 'Paul resented the fact that Carol didn’t trust him.', 'v. 愤恨, 怨恨', '/ri\'zent | rɪ\'zent | rɪ\'zɛnt/', 'resent', 6);
INSERT INTO `words` VALUES (16151, 'At first I felt very resentful and angry about losing my job.', 'adj. 忿恨的， 怨恨的', '/rɪ\'zentfl | rɪ\'zɛntfl/', 'resentful', 6);
INSERT INTO `words` VALUES (16152, 'She expressed resentment at being interviewed by a social worker.', 'n. 怨恨, 愤恨', '/ri\'zentmənt | rɪ\'zentm(ə)nt | rɪ\'zɛntmənt/', 'resentment', 6);
INSERT INTO `words` VALUES (16153, '$10 million in cash reserves', 'n. 储备(物), 储藏量, 预备队', '/rɪ\'zɜːv | rɪ\'zɝv/', 'reserve', 6);
INSERT INTO `words` VALUES (16154, 'Ellen was a shy, reserved girl.', 'adj. 保留的, 包租的', '/rɪ\'zɜːvd | rɪ\'zɝvd/', 'reserved', 6);
INSERT INTO `words` VALUES (16155, 'a Cabinet reshuffle', 'n. 改组', '/\'ri:\'ʃʌfl | riː\'ʃʌf(ə)l | ,ri\'ʃʌfl/', 'reshuffle', 6);
INSERT INTO `words` VALUES (16156, 'He spent most of his time in Rutherglen, where his family resided.', 'v. 居住', '/rɪ\'zaɪd/', 'reside', 6);
INSERT INTO `words` VALUES (16157, 'the ambassador’s official residence', 'n. 居住, 住处', '/\'rezidəns | \'rezɪd(ə)ns | \'rɛzɪdəns/', 'residence', 6);
INSERT INTO `words` VALUES (16158, 'a resident tutor', 'adj. 定居的， 常驻的; n. 居民', '/\'rezɪdənt | \'rɛzɪdənt/', 'resident', 6);
INSERT INTO `words` VALUES (16159, 'a quiet residential neighbourhood', 'adj. 住宅的， 与居住有关的', '/ˌrezɪ\'denʃl | ,rɛzɪ\'dɛnʃl/', 'residential', 6);
INSERT INTO `words` VALUES (16160, 'the residual effects of drug treatment', 'adj. 剩余的, 残留的', '/ri\'zidjuəl, -dʒu- | rɪ\'zɪdjʊəl | rɪ\'zɪdʒuəl/', 'residual', 6);
INSERT INTO `words` VALUES (16161, 'The flies leave a sticky residue on crops.', 'n. 残余, 渣滓, 滤渣, 残数, 剩余物', '/\'rezidju:,-du: | \'rezɪdjuː | \'rɛzɪdu/', 'residue', 6);
INSERT INTO `words` VALUES (16162, 'A hospital administrator has resigned over claims he lied to get the job.', 'v. 委托； 放弃； 辞职', '/rɪ\'zaɪn/', 'resign', 6);
INSERT INTO `words` VALUES (16163, 'Illness forced his resignation.', 'n. 辞职, 辞职书, 放弃, 顺从', '/,reziɡ\'neiʃən | rezɪg\'neɪʃ(ə)n | ,rɛzɪɡ\'neʃən/', 'resignation', 6);
INSERT INTO `words` VALUES (16164, '‘We’ll have to leave,’ she said with a resigned sigh.', 'adj. 顺从的, 听天由命的', '/ri\'zaind | rɪ\'zaɪnd/', 'resigned', 6);
INSERT INTO `words` VALUES (16165, 'People showed remarkable resilience during the war.', 'n. 弹回, 有弹力, 恢复力, 顺应力, 轻快, 达观, 愉快的心情', '/ri\'ziliəns, -jəns | rɪ\'zɪlɪəns | rɪˈzɪliəns/', 'resilience', 6);
INSERT INTO `words` VALUES (16166, 'Children are often very resilient.', 'adj. 有弹性的； 能恢复活力的， 适应力强的', '/rɪ\'zɪliənt | rɪ\'zɪlɪənt/', 'resilient', 6);
INSERT INTO `words` VALUES (16167, 'a tradition that has little resonance in the 21st century', 'n. 共鸣, 回声, 反响, 中介, 谐振, 共振, 共振子, 极短命的不稳定基本粒子', '/\'rezənəns | \'rez(ə)nəns | \'rɛznəns/', 'resonance', 6);
INSERT INTO `words` VALUES (16168, 'Every piece of glass has a natural resonant frequency—the speed at which it will vibrate if bumped or otherwise disturbed by some stimulus, such as a sound wave—as does every other material on Earth.', 'adj. 引起共鸣的', '/\'rezənənt | \'rez(ə)nənt | \'rɛznənt/', 'resonant', 6);
INSERT INTO `words` VALUES (16169, 'His punishing work schedule had made him resort to drugs.', 'v. 求助, 诉诸, 采取(某种手段等), 常去', '/ri\'zɔ:t | rɪ\'zɔːt | rɪ\'zɔrt/', 'resort', 6);
INSERT INTO `words` VALUES (16170, 'A roar of approval resounded through the legislature.', 'v. 回响； 鸣响', '/rɪ\'zaund | rɪ\'zaʊnd/', 'resound', 6);
INSERT INTO `words` VALUES (16171, 'a woman who is energetic and resourceful', 'adj. 机智的', '/rɪ\'sɔːrsfl | rɪ\'sɔrsfl/', 'resourceful', 6);
INSERT INTO `words` VALUES (16172, 'I respect his views, although I do not agree with them.', 'v. 尊敬; n. 尊敬', '/rɪ\'spekt | rɪ\'spɛkt/', 'respect', 6);
INSERT INTO `words` VALUES (16173, NULL, 'adj. 向后看的, 面对面的', '/ri\'spektənt/', 'respectant', 6);
INSERT INTO `words` VALUES (16174, 'Ford was a respecter of proprieties and liked to see things done properly.', 'n. 尊敬的人, 熟虑的人', '/ri\'spektə | rɪ\'spektə(r) | rɪ\'spɛktɚ/', 'respecter', 6);
INSERT INTO `words` VALUES (16175, 'We all went back to our respective homes to wait for news.', 'adj. 分别的, 各自的', '/ri\'spektiv | rɪ\'spektɪv | rɪ\'spɛktɪv/', 'respective', 6);
INSERT INTO `words` VALUES (16176, 'His respiration grew fainter throughout the day.', 'n. 呼吸, 呼吸作用', '/,respə\'reiʃən | respɪ\'reɪʃ(ə)n | ,rɛspə\'reʃən/', 'respiration', 6);
INSERT INTO `words` VALUES (16177, 'respiratory disease', 'adj. 呼吸的', '/\'respərətɔːri | rɪ\'spaɪərətɔːrɪ; rɪ\'spaɪrəˌtɔrɪ/', 'respiratory', 6);
INSERT INTO `words` VALUES (16178, 'a brief respite from persecution', 'n. 暂缓', '/\'respait, -pit, ri\'spait | \'respaɪt; -spɪt | \'rɛspɪt/', 'respite', 6);
INSERT INTO `words` VALUES (16179, 'We do not pursue one resplendence but development for ever.', 'n. 辉煌, 灿烂', '/ri\'splendəns/', 'resplendence', 6);
INSERT INTO `words` VALUES (16180, 'Bessie, resplendent in royal blue velvet, was hovering beside the table.', 'adj. 辉煌的, 灿烂的, 光辉的, 华丽的', '/ri\'splendənt | rɪ\'splend(ə)nt | rɪ\'splɛndənt/', 'resplendent', 6);
INSERT INTO `words` VALUES (16181, 'Upon receipt of a copy of the arbitration application, the respondent shall, within the time limit prescribed by the Arbitration Rules, submit its defence to the arbitration commission.', 'adj. 回答的', '/ri\'spɔndənt | rɪ\'spɒnd(ə)nt | rɪ\'spɑndənt/', 'respondent', 6);
INSERT INTO `words` VALUES (16182, 'a car with highly responsive steering', 'adj. 响应的, 作出响应的', '/ri\'spɔnsiv | rɪ\'spɒnsɪv | rɪ\'spɑnsɪv/', 'responsive', 6);
INSERT INTO `words` VALUES (16183, 'I hope this book is not yet another restatement of the prevailing wisdom.', 'n. 再声明， 重述', '/ri:\'steitmənt | ˌriː\'steɪtmənt/', 'restatement', 6);
INSERT INTO `words` VALUES (16184, 'The offender must make restitution for the hurt that he or she has caused.', 'n. 归还', '/,resti\'tju:ʃən | ,restɪ\'tjuːʃ(ə)n | \'rɛstə\'tʊʃən/', 'restitution', 6);
INSERT INTO `words` VALUES (16185, 'Republican leaders struggled to rule over increasingly restive populations.', 'adj. 难控制的', '/\'restiv | \'restɪv | \'rɛstɪv/', 'restive', 6);
INSERT INTO `words` VALUES (16186, NULL, 'n. 倔强， 难以驾驭', '/\'restivnis | \'restɪvnəs/', 'restiveness', 6);
INSERT INTO `words` VALUES (16187, 'After a few weeks in Marseille, I grew restless and decided to move on.', 'adj. 焦躁不安的， 静不下来的', '/\'restləs | \'rɛstləs/', 'restless', 6);
INSERT INTO `words` VALUES (16188, 'Major restoration work will begin in May.', 'n. 恢复， 复原', '/ˌrestə\'reɪʃn | \'rɛstə\'reʃən/', 'restoration', 6);
INSERT INTO `words` VALUES (16189, 'She opened the door to her bedroom, thinking how restorative a hot bath would feel tonight.', 'adj. 有助于复元的', '/ri\'stɔrətiv, -\'stɔ:- | rɪ\'stɒrətɪv | rɪ\'stɔrətɪv/', 'restorative', 6);
INSERT INTO `words` VALUES (16190, 'She was hoping that the Mediterranean climate would restore her to full health.', 'v. 使回复， 恢复； 修复， 修补', '/rɪ\'stɔːr | rɪ\'stɔr/', 'restore', 6);
INSERT INTO `words` VALUES (16191, 'After a cup of tea, she felt quite restored.', 'adj. 恢复的', '/rɪ\'stɔːrd | ri\'stɔ:d/', 'restored', 6);
INSERT INTO `words` VALUES (16192, 'Renwick restrained a feeling of annoyance.', 'v. 抑制, 制止', '/ri\'strein | rɪ\'streɪn | rɪ\'stren/', 'restrain', 6);
INSERT INTO `words` VALUES (16193, 'The police were praised for their restraint in handling the demonstrators.', 'n. 抑制, 制止, 克制', '/ri\'streint | rɪ\'streɪnt | rɪ\'strent/', 'restraint', 6);
INSERT INTO `words` VALUES (16194, 'The new law restricts the sale of hand guns.', 'v. 限制， 约束', '/rɪ\'strɪkt/', 'restrict', 6);
INSERT INTO `words` VALUES (16195, 'a brief résumé of the day’s events', 'n. 摘要, 概略, <美> 履历', '/rezju:\'mei, ri\'zju:m; -\'zu:m | rɪˈzjuːm; ˈrɛzjʊmeɪ/', 'resume', 6);
INSERT INTO `words` VALUES (16196, NULL, 'n. 取回, 恢复, 再开始, 重获, (中断后)再继续', '/ri\'zʌmpʃən | rɪ\'zʊm(p)ʃ(ə)n | rɪ\'zʌmpʃən/', 'resumption', 6);
INSERT INTO `words` VALUES (16197, 'The architect leaves washington with the democratic party resurge nt his own party reduced to an ageing and irascible core and the president with one of the lowest approval ratings in history.', 'v. 复活', '/rɪ\'sɜːrdʒ | ri\'sɝdʒ/', 'resurge', 6);
INSERT INTO `words` VALUES (16198, 'Police say drugs traffickers are behind the resurgence of violence.', 'n. 苏醒', '/ri\'sə:dʒəns | rɪ\'sɜːdʒ(ə)ns | rɪ\'sɝdʒəns/', 'resurgence', 6);
INSERT INTO `words` VALUES (16199, 'resurgent fascism', 'adj. 复活的', '/ri\'sə:dʒənt | rɪ\'sɜːdʒ(ə)nt | rɪ\'sɝdʒənt/', 'resurgent', 6);
INSERT INTO `words` VALUES (16200, 'The Home Office have resurrected plans to build a new prison just outside London.', 'v. 复兴', '/,rezə\'rekt | rezə\'rekt/', 'resurrect', 6);
INSERT INTO `words` VALUES (16201, 'a resurrection of old jealousies', 'n. 复苏', '/,rezə\'rekʃən | rezə\'rekʃ(ə)n | ,rɛzə\'rɛkʃən/', 'resurrection', 6);
INSERT INTO `words` VALUES (16202, 'Doctors managed to resuscitate him.', 'v. (使)复苏, (使)复兴', '/ri\'sʌsiteit | rɪ\'sʌsɪteɪt | rɪ\'sʌsɪtet/', 'resuscitate', 6);
INSERT INTO `words` VALUES (16203, 'a retail price of £8.99', 'n. 零售', '/\'ri:teil | \'riːteɪl | \'ritel/', 'retail', 6);
INSERT INTO `words` VALUES (16204, 'Furniture and carpet retailers are among those reporting the sharpest annual decline in sales.', 'n. 零售商人, 传播的人', '/\'ri:teilə | \'riːteɪlə/', 'retailer', 6);
INSERT INTO `words` VALUES (16205, 'I find it very difficult to retain facts.', 'v. 保留， 保持； 留住， 止住', '/rɪ\'teɪn | rɪ\'ten/', 'retain', 6);
INSERT INTO `words` VALUES (16206, 'I was sorely tempted to retaliate.', 'v. 报复', '/ri\'tælieit | rɪ\'tælɪeɪt | rɪ\'tælɪ\'et/', 'retaliate', 6);
INSERT INTO `words` VALUES (16207, 'Industry rivalry and the threat of retaliation.', 'n. 报复', '/rɪˌtæli\'eɪʃn | ri,tæli\'eiʃən/', 'retaliation', 6);
INSERT INTO `words` VALUES (16208, 'Cold weather retards the growth of many plants.', 'v. 延迟, 使减速, 阻止, 妨碍, 阻碍', '/ri\'tɑ:d | \'rɪtɑːd | \'rɪtɑrd/', 'retard', 6);
INSERT INTO `words` VALUES (16209, NULL, 'n. 延缓(作用)剂', '/ri\'tɑ:dənt | rɪ\'tɑːd(ə)nt | rɪ\'tɑrdənt/', 'retardant', 6);
INSERT INTO `words` VALUES (16210, '...a special school for mentally retarded children.', 'adj. 智力迟钝的, 发展迟缓的', '/ri\'tɑ:did | rɪ\'tɑːdɪd | rɪ\'tɑrdɪd/', 'retarded', 6);
INSERT INTO `words` VALUES (16211, 'The smell made her retch.', 'v. 作呕， 恶心', '/retʃ | ritʃ/', 'retch', 6);
INSERT INTO `words` VALUES (16212, 'The Citizens\' Forum supported special powers for Quebec but also argued for the retention of a strong central government.', 'n. 保留， 保持', '/rɪ\'tenʃn | rɪ\'tɛnʃən/', 'retention', 6);
INSERT INTO `words` VALUES (16213, 'Luke had an amazingly retentive memory.', 'adj. 保持的', '/ri\'tentiv | rɪ\'tentɪv | rɪ\'tɛntɪv/', 'retentive', 6);
INSERT INTO `words` VALUES (16214, 'She is so reticent about her achievements.', 'adj. 沉默寡言的', '/\'retisənt | \'retɪs(ə)nt | \'rɛtɪsnt/', 'reticent', 6);
INSERT INTO `words` VALUES (16215, 'EDI components will be a certain number of EDI unit with reticulation , forming strong water Chambers separated.', 'n. 网状物', '/ri,tikju\'leiʃən | rɪ,tɪkjʊ\'leɪʃ(ə)n | rɪ,tɪkjə\'leʃən/', 'reticulation', 6);
INSERT INTO `words` VALUES (16216, 'Mind trainers are now part of a tennis star\'s retinue.', 'n. (要人的一批)随行人员, 扈从', '/\'retinju:, -nu: | \'retɪnjuː | \'rɛtənu/', 'retinue', 6);
INSERT INTO `words` VALUES (16217, 'At the age when most people retire, he is ready to face a new career.', 'v. 撤退， 后退； 退休， 退役', '/rɪ\'taɪər | rɪ\'taɪɚ/', 'retire', 6);
INSERT INTO `words` VALUES (16218, 'With children independent in economy from home, the core of home economy assure will transfer from protection to the life saving after retiring.', 'adj. 退休的', '/ri\'taiəriŋ | rɪ\'taɪərɪŋ/', 'retiring', 6);
INSERT INTO `words` VALUES (16219, '‘It’s all your fault!’ he retorted.', 'v. 反驳, 反击, 回报', '/ri\'tɔ:t | rɪ\'tɔːt | rɪ\'tɔrt/', 'retort', 6);
INSERT INTO `words` VALUES (16220, 'postcards that have been retouched to cover the grey skies', 'v. 修描； 润色', '/ˌriː\'tʌtʃ | ,ri\'tʌtʃ/', 'retouch', 6);
INSERT INTO `words` VALUES (16221, 'After a few minutes, he turned around and began to retrace his steps.', 'v. 折回', '/ri\'treis, ri:-, \'ri:treis | rɪ\'treɪs | rɪ\'tres/', 'retrace', 6);
INSERT INTO `words` VALUES (16222, 'He confessed to the murder but later retracted his statement.', 'v. 缩回, 缩进, 所卷(舌等), 收回, 取消, 撤消', '/ri\'trækt | rɪ\'trækt/', 'retract', 6);
INSERT INTO `words` VALUES (16223, 'The rebels retreated to the mountains.', 'v. 撤退, 退却', '/ri\'tri:t | rɪ\'triːt | rɪ\'trit/', 'retreat', 6);
INSERT INTO `words` VALUES (16224, 'Shortly afterwards, cuts in defence spending forced the aerospace industry to retrench.', 'v. 节省， 紧缩开支', '/rɪ\'trentʃ | ri\'trɛntʃ/', 'retrench', 6);
INSERT INTO `words` VALUES (16225, 'He didn\'t want any further involvement for fear of retribution.', 'n. 报偿', '/,retri\'bju:ʃən | retrɪ\'bjuːʃ(ə)n | ,rɛtrɪ\'bjuʃən/', 'retribution', 6);
INSERT INTO `words` VALUES (16226, 'The onus is now on the Libyan people to show restraint and respect for the rule of law in dealing with regime officials and soldiers, and to refrain from vigilantism and retributive justice.', 'adj. 报应的', '/ri\'tribjutiv/', 'retributive', 6);
INSERT INTO `words` VALUES (16227, '...electronic storage and retrieval systems.', 'n. 取回, 恢复, 修补，重获，挽救，拯救', '/ri\'tri:vəl | rɪ\'triːvl | rɪ\'trivl/', 'retrieval', 6);
INSERT INTO `words` VALUES (16228, 'She bent down to retrieve her earring.', 'v. 重新得到', '/ri\'tri:v | rɪ\'triːv | rɪ\'triv/', 'retrieve', 6);
INSERT INTO `words` VALUES (16229, 'The closure of the factories is seen as a retrograde step .', 'adj. 倒退的', '/\'retrəuɡreid | \'retrəgreɪd | \'rɛtrəɡred/', 'retrograde', 6);
INSERT INTO `words` VALUES (16230, 'At present the moral belief crisis is the co-existence of expansibility crisis and the retrogress crisis.', 'v. 退步', '/,retrəu\'ɡres, \'retrəuɡres | ,retrə(ʊ)\'gres | \'rɛtroɡrɛs/', 'retrogress', 6);
INSERT INTO `words` VALUES (16231, 'In retrospect, I wonder if we should have done more.', 'n. 回顾', '/\'retrəuspekt | \'retrəspekt | \'rɛtrəspɛkt/', 'retrospect', 6);
INSERT INTO `words` VALUES (16232, 'a retrospective study of 110 patients', 'adj. 回顾的', '/,retrəu\'spektiv | retrə(ʊ)\'spektɪv | ,rɛtrə\'spɛktɪv/', 'retrospective', 6);
INSERT INTO `words` VALUES (16233, 'Please complete the enclosed application form and return it in the envelope attached.', 'v. 回复；归还；回答，反驳; adj. 返回的； 重现的; n. 回报', '/rɪ\'tɜːrn | rɪ\'tɝn/', 'return', 6);
INSERT INTO `words` VALUES (16234, 'Many older companies are revamping their image.', 'v. 修补', '/ri:\'væmp | riː\'væmp | ,ri\'væmp/', 'revamp', 6);
INSERT INTO `words` VALUES (16235, 'He may be prosecuted for revealing secrets about the security agency.', 'v. 启示； 揭露； 显示', '/rɪ\'viːl | rɪ\'vil/', 'reveal', 6);
INSERT INTO `words` VALUES (16236, '...the seemingly everlasting revelations about his private life.', 'n. 显示, 揭露, 被揭露的事, 新发现, 启示, 揭示', '/,revə\'leiʃən | revə\'leɪʃ(ə)n | \'rɛvə\'leʃən/', 'revelation', 6);
INSERT INTO `words` VALUES (16237, '...New Year revelries.', 'n. 狂欢', '/\'revəlri | \'revlrɪ | \'rɛvlri/', 'revelry', 6);
INSERT INTO `words` VALUES (16238, 'The attackers were said to be taking revenge on the 14-year-old, claiming he was a school bully.', 'n. 报仇, 复仇', '/ri\'vendʒ | rɪ\'ven(d)ʒ | rɪ\'vɛndʒ/', 'revenge', 6);
INSERT INTO `words` VALUES (16239, 'advertising revenue', 'n. 收入, 国家的收入, 税收', '/\'revənju:, -nu: | \'revənjuː | \'rɛvənu/', 'revenue', 6);
INSERT INTO `words` VALUES (16240, 'Some of the most reverberant recent studies were performed at Northwestern University’s Feinberg School of Medicine in Chicago.', 'adj. 回响的', '/ri\'və:bərənt | rɪ\'vɜːbərənt/', 'reverberant', 6);
INSERT INTO `words` VALUES (16241, 'Day in and day out, the flat crack of the tank guns reverberates through the little Bavarian town.', 'v. 反响', '/ri\'və:bəreit | rɪ\'vɜːbəreɪt | rɪ\'vɝbə\'ret/', 'reverberate', 6);
INSERT INTO `words` VALUES (16242, 'The Chinese revered corn as a gift from heaven.', 'v. 尊敬', '/rɪ\'vɪr/', 'revere', 6);
INSERT INTO `words` VALUES (16243, 'a hushed reverent voice', 'adj. 尊敬的, 虔诚的', '/\'revərənt | \'rev(ə)r(ə)nt | \'rɛvərənt/', 'reverent', 6);
INSERT INTO `words` VALUES (16244, 'He spoke in reverential tones.', 'adj. 表示尊敬的， 恭敬的', '/ˌrevə\'renʃl | ,rɛvə\'rɛnʃl/', 'reverential', 6);
INSERT INTO `words` VALUES (16245, 'She was startled out of her reverie by a loud crash.', 'n. 幻想', '/\'revəri | \'rev(ə)rɪ | \'rɛvəri/', 'reverie', 6);
INSERT INTO `words` VALUES (16246, 'I owe you nothing. If anything, the reverse is true (= you owe me ) .', 'n. 相反, 背面, 反面, 倒退', '/ri\'və:s | rɪ\'vɜːs | rɪ\'vɝs/', 'reverse', 6);
INSERT INTO `words` VALUES (16247, 'A lot of chemical reactions are reversible.', 'adj. 可逆的， 可反转的', '/rɪ\'vɜːrsəbl | rɪ\'vɝsəbl/', 'reversible', 6);
INSERT INTO `words` VALUES (16248, 'This looks like a reversion to Mexico\'s previous solidarity with the global left.', 'n. 反转, 逆转, 返祖, 隔代遗传, 回复, 复原, 归还, 继承权', '/ri\'və:ʃən, -ʒən | rɪ\'vɜːʃ(ə)n | rɪ\'vɝʒən/', 'reversion', 6);
INSERT INTO `words` VALUES (16249, 'Jackson said her boss became increasingly depressed and reverted to smoking heavily.', 'v. 恢复， 回复到； 重新考虑', '/rɪ\'vɜːrt | rɪ\'vɝt/', 'revert', 6);
INSERT INTO `words` VALUES (16250, 'The President was now reviled by the same party he had helped to lead.', 'v. 辱骂, 斥责', '/ri\'vail | rɪ\'vaɪl/', 'revile', 6);
INSERT INTO `words` VALUES (16251, 'The college has revised its plans because of local objections.', 'v. 校订， 修正', '/rɪ\'vaɪz/', 'revise', 6);
INSERT INTO `words` VALUES (16252, 'They hope to revitalize the neighborhood by providing better housing.', 'v. 新生', '/,ri:\'vaitəlaiz | ,ri\'vaɪtəlaɪz/', 'revitalize', 6);
INSERT INTO `words` VALUES (16253, 'The US and the UK have expectations of economic revival.', 'n. 苏醒； 恢复； 复兴', '/rɪ\'vaɪvl/', 'revival', 6);
INSERT INTO `words` VALUES (16254, 'She and a neighbour tried in vain to revive him.', 'v. 使苏醒； 使再流行', '/rɪ\'vaɪv/', 'revive', 6);
INSERT INTO `words` VALUES (16255, NULL, 'adj. 可废止的, 可取消的', '/\'revəkəbl, ri\'vəu- | \'revəkəb(ə)l | \'revəkəbəl/', 'revocable', 6);
INSERT INTO `words` VALUES (16256, 'However, this object lacks the methods needed for run-time role assignment and revocation.', 'n. 撤回', '/,revə\'keiʃən, ri,vəu-, ,ri:- | ,revə\'keɪʃən | ,rɛvə\'keʃən/', 'revocation', 6);
INSERT INTO `words` VALUES (16257, 'Their work permits have been revoked.', 'v. 撤回, 废除, 宣告无效', '/ri\'vəuk | rɪ\'vəʊk | rɪ\'vok/', 'revoke', 6);
INSERT INTO `words` VALUES (16258, 'He was revolted by the smell.', 'v. 反抗, 起义, 反叛, 反感, 厌恶', '/ri\'vəult, -\'vɔ:lt | rɪ\'vəʊlt | rɪ\'volt/', 'revolt', 6);
INSERT INTO `words` VALUES (16259, 'The food was revolting!', 'adj. 令人厌恶的', '/ri\'vəultiŋ, -\'vɔ:- | rɪ\'vəʊltɪŋ | rɪ\'voltɪŋ/', 'revolting', 6);
INSERT INTO `words` VALUES (16260, 'News of the atrocities produced a wave of anger and revulsion.', 'n. 抽回', '/ri\'vʌlʃən | rɪ\'vʌlʃ(ə)n | rɪ\'vʌlʃən/', 'revulsion', 6);
INSERT INTO `words` VALUES (16261, 'The team have worked hard and their efforts have been rewarded with success.', 'v. 酬谢， 奖赏; n. 报酬，奖赏', '/rɪ\'wɔːrd | rɪ\'wɔrd/', 'reward', 6);
INSERT INTO `words` VALUES (16262, 'Teaching can be a very rewarding career.', 'adj. 有益的， 值得的', '/rɪ\'wɔːrdɪŋ | rɪ\'wɔrdɪŋ/', 'rewarding', 6);
INSERT INTO `words` VALUES (16263, '...a rhapsodic letter about the birth of her first baby.', 'adj. 狂热的， 狂喜的； 狂想曲的', '/ræp\'sɑːdɪk | ræp\'sɔdik/', 'rhapsodic', 6);
INSERT INTO `words` VALUES (16264, 'The critics rhapsodized over her performance in \"Autumn Sonata.\"', 'v. 狂热地描述, 写狂想文, 作狂想曲', '/\'ræpsədaiz | \'ræpsədaɪz/', 'rhapsodize', 6);
INSERT INTO `words` VALUES (16265, 'Gershwin’s Rhapsody in Blue', 'n. 狂想曲', '/\'ræpsədi | \'ræpsədɪ/', 'rhapsody', 6);
INSERT INTO `words` VALUES (16266, 'The elections are over, the rhetoric should stop, it’s time to go back to work.', 'adj. 花言巧语的', '/\'retərik | \'retərɪk | \'rɛtərɪk/', 'rhetoric', 6);
INSERT INTO `words` VALUES (16267, 'a speech full of rhetorical phrases', 'adj. 修辞的， 修辞学的； 虚夸的， 辞藻华丽的', '/rɪ\'tɔːrɪkl | rɪ\'tɔrɪkl/', 'rhetorical', 6);
INSERT INTO `words` VALUES (16268, NULL, 'adj. 稀粘液的, 潮湿的', '/\'ru:mi/', 'rheumy', 6);
INSERT INTO `words` VALUES (16269, NULL, 'n. 水晶之一种, 人造钻石', '/\'rainstəun | \'raɪnstəʊn | \'raɪn\'ston/', 'rhinestone', 6);
INSERT INTO `words` VALUES (16270, 'From the low-growing Indian rhubarb to the mighty English maples, the plants in this region get ready for the winter with a cornucopia of colors.', 'n. 大黄, 大黄的叶柄', '/\'ruːbɑːb | \'rʊbɑrb/', 'rhubarb', 6);
INSERT INTO `words` VALUES (16271, 'the rhythmic thud of the bass drum', 'adj. 节奏的, 合拍的', '/\'riðmik, \'riθ-/', 'rhythmic', 6);
INSERT INTO `words` VALUES (16272, 'She was taken to hospital with a broken arm and ribs.', 'n. 肋骨', '/rib | rɪb/', 'rib', 6);
INSERT INTO `words` VALUES (16273, 'a ribald remark', 'adj. 下流的', '/\'ribəld, \'ribɔ:ld, \'raibɔ:ld | \'rɪb(ə)ld; \'raɪbɔːld | \'rɪbld/', 'ribald', 6);
INSERT INTO `words` VALUES (16274, NULL, 'n. 下流的语言， 粗鄙的幽默', '/\'rɪbldri/', 'ribaldry', 6);
INSERT INTO `words` VALUES (16275, 'a rickety old wooden chair', 'adj. [医]患佝偻病的, 驼背的, 摇摆的', '/\'rikəti | \'rɪkɪtɪ | \'rɪkəti/', 'rickety', 6);
INSERT INTO `words` VALUES (16276, 'We made our way carefully along the ridge.', 'n. 背脊, 山脊, 屋脊, 山脉, 犁垄', '/ridʒ | rɪdʒ/', 'ridge', 6);
INSERT INTO `words` VALUES (16277, 'the ridicule of his peers', 'n. 嘲笑， 奚落', '/\'rɪdɪkjuːl | \'rɪdɪ\'kjʊl/', 'ridicule', 6);
INSERT INTO `words` VALUES (16278, 'That’s a ridiculous idea!', 'adj. 荒谬的， 可笑的', '/rɪ\'dɪkjələs/', 'ridiculous', 6);
INSERT INTO `words` VALUES (16279, 'Violent crime is rife in our inner cities.', 'adj. 普遍的', '/raif | raɪf/', 'rife', 6);
INSERT INTO `words` VALUES (16280, NULL, 'n. 浅滩, 湍流, 涟漪, 洗牌动作', '/\'rifl | \'rɪf(ə)l | \'rɪfl/', 'riffle', 6);
INSERT INTO `words` VALUES (16281, 'They shot him at point blank range with an automatic rifle.', 'n. 来复枪, 步枪, 来复线, 膛线', '/\'raifl | \'raɪf(ə)l | \'raɪfl/', 'rifle', 6);
INSERT INTO `words` VALUES (16282, 'The interview reflected a growing rift between the president and Congress.', 'n. 裂缝, 裂口, 断裂, 长狭谷, 不和', '/rift | rɪft/', 'rift', 6);
INSERT INTO `words` VALUES (16283, '...a supply vessel for oil rigs in the Gulf of Mexico.', 'n. 索具装备, 钻探设备, 钻探平台, 钻塔', '/riɡ | rɪg | rɪɡ/', 'rig', 6);
INSERT INTO `words` VALUES (16284, 'No, no, we are not satisfied, and we will not be satisfied until justice rolls down like waters and righteousness like a mighty stream.', 'n. 正当， 正义， 正直', '/\'raɪtʃəsnəs | \'raɪtʃəsnɪs/', 'righteousness', 6);
INSERT INTO `words` VALUES (16285, 'rigid and authoritarian methods of education', 'adj. 严格的； 僵硬的， 刚硬的', '/\'rɪdʒɪd/', 'rigid', 6);
