INSERT INTO `words` VALUES (16315, 'A street- lamp faced him, and in its light he saw Julius Beaufort\'s compact English brougham, drawn by a big roan, and the banker descending from it, and helping out Madame Olenska.', 'adj. 花毛的, 杂色的', '/rəun | rəʊn | ron/', 'roan', 6);
