INSERT INTO `words` VALUES (16320, '...cod\'s roe.', 'n. [动](=roe deer)狍(分布于欧亚两洲), (3岁以上的)雌鹿, (还在雌鱼卵巢中的)鱼卵, (充满精液的)雄鱼生殖腺, (木材纵剖面的)鱼卵形黑色斑纹', '/rəu | rəʊ | ro/', 'roe', 6);
INSERT INTO `words` VALUES (16321, 'She was a mature lady with dyed red hair and a roguish grin.', 'adj. 流氓的, 无赖的', '/\'rəuɡiʃ | \'rəʊgɪʃ | \'roɡɪʃ/', 'roguish', 6);
INSERT INTO `words` VALUES (16322, 'The water roiled to his left as he climbed carefully at the edge of the waterfall.', 'v. 煽动, 激怒', '/rɔil | rɒɪl/', 'roil', 6);
