INSERT INTO `words` VALUES (16349, 'It has many of the same nutrients of the rubicund liquid we love to consume (iron, protein, electrolytes, and caffeine) and has a delectable fruit punch flavor.', 'adj. (脸色, 肤色等)红润的, 透红的', '/\'ru:bikənd | \'ruːbɪk(ə)nd/', 'rubicund', 6);
