INSERT INTO `words` VALUES (16351, 'You have to run five kilometers every morning, carrying a heavy rucksack and rifle.', 'n. (旅行用)帆布背包', '/\'rʌksæk, \'ruk- | \'rʌksæk; \'rʊk- | \'rʊksæk/', 'rucksack', 6);
