INSERT INTO `words` VALUES (16394, 'It is no surprise that she could saddle the horses.', 'n. 鞍, 鞍状物', '/\'sædl | \'sæd(ə)l/', 'saddle', 6);
INSERT INTO `words` VALUES (16395, 'He\'d like to go on safari to photograph snakes and tigers.', 'n. 旅行, 狩猎远征, 旅行队, 旅行队(狩猎远征队)及装备', '/sə\'fɑ:ri, -\'fæ- | sə\'fɑːrɪ | sə\'fɑri/', 'safari', 6);
INSERT INTO `words` VALUES (16396, 'technology that will safeguard the environment', 'v. 维护, 保护, 捍卫', '/\'seifɡɑ:d | \'seɪfgɑːd | \'sefɡɑrd/', 'safeguard', 6);
INSERT INTO `words` VALUES (16397, 'The branch sagged under the weight of the apples.', 'v. 松弛, 下陷, 下垂, (物价)下跌, 漂流', '/sæɡ | sæg | sɑɡ/', 'sag', 6);
INSERT INTO `words` VALUES (16398, 'Our saga, and my experiment, was over.', 'n. 传奇', '/\'sɑ:ɡə | \'sɑːgə | \'sɑɡə/', 'saga', 6);
INSERT INTO `words` VALUES (16399, '...a sagacious leader.', 'adj. 有洞察力的, 有远见的, 精明的, 敏锐的', '/sə\'ɡeiʃəs | sə\'geɪʃəs | sə\'ɡeʃəs/', 'sagacious', 6);
INSERT INTO `words` VALUES (16400, '...a man of great sagacity and immense experience.', 'n. 睿智, 聪敏', '/sə\'ɡæsiti | sə\'gæsɪtɪ | sə\'gæsəti/', 'sagacity', 6);
INSERT INTO `words` VALUES (16401, 'sage advice', 'adj. 贤明的, 明智的, 审慎的', '/seidʒ | seɪdʒ | sedʒ/', 'sage', 6);
INSERT INTO `words` VALUES (16402, NULL, 'n. (穆斯林的)额手礼, 问安, 敬礼', '/sə\'lɑ:m | sə\'lɑːm | sə\'lɑm/', 'salaam', 6);
INSERT INTO `words` VALUES (16403, 'the media’s love of salacious gossip', 'adj. 猥亵的, 好色的', '/sə\'leiʃəs | sə\'leɪʃəs | sə\'leʃəs/', 'salacious', 6);
INSERT INTO `words` VALUES (16404, 'The relationship between the old Duke and the young woman was put down to the salacity which is frequently found in rich old men. People imagined all manner of things, except the truth.', 'n. 好色, 猥亵', '/sə\'læsiti/', 'salacity', 6);
INSERT INTO `words` VALUES (16405, 'the salient points of the report', 'adj. 易见的, 显著的, 突出的, 跳跃的', '/\'seiljənt, -liənt | \'seɪlɪənt | \'selɪənt/', 'salient', 6);
INSERT INTO `words` VALUES (16406, 'By performing core displacement and micro pore model displacement experiments, the mechanism and changing law of saliferous reservoir parameters were studied.', 'adj. [地](岩层等)含盐的', '/sə\'lifərəs, sæ- | sə\'lɪf(ə)rəs | sæ\'lɪfərəs/', 'saliferous', 6);
INSERT INTO `words` VALUES (16407, 'saline solution', 'adj. 含盐的， 咸的', '/\'seɪliːn | \'selin/', 'saline', 6);
INSERT INTO `words` VALUES (16408, 'He noticed a lot of saliva settling in his mouth.', 'n. 口水, 唾液', '/sə\'laivə | sə\'laɪvə/', 'saliva', 6);
INSERT INTO `words` VALUES (16409, 'She had lank hair and sallow skin.', 'adj. 菜色', '/\'sæləu | \'sæləʊ | \'sælo/', 'sallow', 6);
INSERT INTO `words` VALUES (16410, 'He gave them a splendid lunch of smoked salmon.', 'n. [鱼]鲑鱼, 大麻哈鱼, 鲜肉色', '/\'sæmən/', 'salmon', 6);
INSERT INTO `words` VALUES (16411, 'His features were pretty yet, and his eye and complexion brighter than I remembered them, though with merely temporary lustre borrowed from the salubrious air and genial sun.', 'adj. 有益健康的', '/sə\'lju:briəs | sə\'luːbrɪəs | sə\'lubrɪəs/', 'salubrious', 6);
INSERT INTO `words` VALUES (16412, 'One can only hope that the result will be an equally salutary debate.', 'adj. 有益的', '/\'sæljutəri | \'sæljʊt(ə)rɪ | \'sæljə\'tɛri/', 'salutary', 6);
INSERT INTO `words` VALUES (16413, 'Jackson nodded a salutation.', 'n. 招呼', '/,sælju:\'teiʃən | ,sæljʊ\'teɪʃ(ə)n | \'sæljʊ\'teʃən/', 'salutation', 6);
INSERT INTO `words` VALUES (16414, 'The two soldiers saluted Lieutenant Cecil.', 'v. 行礼致敬；致意; n. 行军礼', '/sə\'luːt | sə\'lut/', 'salute', 6);
INSERT INTO `words` VALUES (16415, 'a massive salvage operation', 'n. 抢救财货, 获救的财货, 救难的奖金, 海上救助, 抢救, 打捞', '/\'sælvidʒ | \'sælvɪdʒ/', 'salvage', 6);
INSERT INTO `words` VALUES (16416, 'The church\'s message of salvation has changed the lives of many.', 'n. 拯救, 救助', '/sæl\'veiʃən | sæl\'veɪʃ(ə)n | sæl\'veʃən/', 'salvation', 6);
INSERT INTO `words` VALUES (16417, 'lip salve', 'n. 药膏', '/sælv | sæv/', 'salve', 6);
INSERT INTO `words` VALUES (16418, NULL, 'n. 保留条款', '/\'sælvəu | \'sælvəʊ | \'sælvo/', 'salvo', 6);
INSERT INTO `words` VALUES (16419, NULL, 'n. 样品检验员, 刺绣样品, 取样器', '/\'sɑ:mplə, \'sæ- | \'sɑːmplə | \'sæmplɚ/', 'sampler', 6);
INSERT INTO `words` VALUES (16420, 'The sanatorium stood on a large plot of land by the coast.', 'n. 疗养院, 休养地', '/\'sænə\'tɔ:riəm | ,sænə\'tɔrɪəm/', 'sanatorium', 6);
INSERT INTO `words` VALUES (16421, 'sanctimonious politicians preaching about family values', 'adj. 假装神圣的', '/,sæŋkti\'məuniəs | ,sæŋ(k)tɪ\'məʊnɪəs | ,sæŋktɪ\'monɪəs/', 'sanctimonious', 6);
INSERT INTO `words` VALUES (16422, 'a resolution to impose sanctions (= start using sanctions ) on DPRK', 'n. 批准, 同意, 支持, 制裁, 认可', '/\'sæŋ,kʃən | \'sæŋ(k)ʃ(ə)n | \'sæŋkʃən/', 'sanction', 6);
INSERT INTO `words` VALUES (16423, 'His church became a sanctuary for thousands of people who fled the civil war.', 'n. 避难所', '/\'sæŋktju\'ri, -tʃuə- | \'sæŋ(k)tjʊərɪ | \'sæŋktʃuɛri/', 'sanctuary', 6);
INSERT INTO `words` VALUES (16424, 'Occasionally she would be allowed into the inner sanctum of his office.', 'n. 圣地, 圣所, 密室, 私室, 书房', '/\'sæŋktəm | \'sæŋ(k)təm/', 'sanctum', 6);
INSERT INTO `words` VALUES (16425, 'He seems perfectly sane (= completely sane ) to me.', 'adj. 健全的', '/sein | seɪn | sen/', 'sane', 6);
INSERT INTO `words` VALUES (16426, 'The commander showed great sangfroid and acted without ever losing his composure.', 'n. 冷静, 泰然, 镇静或沉着', '/sɔŋ\'frwa:/', 'sangfroid', 6);
INSERT INTO `words` VALUES (16427, 'He is alike to datura, the dependence blood is a nutrient, has deadly perilous, cruel sanguinary, so, he is too standing single.', 'adj. 残暴的', '/\'sæ,ɡwinəri | \'sængwɪn(ə)rɪ/', 'sanguinary', 6);
INSERT INTO `words` VALUES (16428, 'a sanguine view', 'adj. 有望的, 乐天的, 面色红润的, 血红色的, 满怀希望的, 指望的', '/\'sæŋɡwin | \'sæŋgwɪn/', 'sanguine', 6);
INSERT INTO `words` VALUES (16429, 'Often, the camps were not very sanitary.', 'adj. (有关)卫生的, (保持)清洁的, 清洁卫生的', '/\'sænitəri | \'sænɪt(ə)rɪ | \'sænə\'tɛri/', 'sanitary', 6);
INSERT INTO `words` VALUES (16430, 'Overcrowding and poor sanitation are common problems in prisons.', 'n. 卫生, 卫生设施', '/,sæni\'teiʃən | sænɪ\'teɪʃ(ə)n | ,sænɪ\'teʃən/', 'sanitation', 6);
INSERT INTO `words` VALUES (16431, 'This is usually fine, unless they forget to sanitize, or check, the incoming data.', 'v. 清洁', '/\'sænitaiz | \'sænɪtaɪz/', 'sanitize', 6);
INSERT INTO `words` VALUES (16432, 'I began to doubt his sanity.', 'n. 心智健全', '/\'sænəti | \'sænɪtɪ/', 'sanity', 6);
INSERT INTO `words` VALUES (16433, 'The leaves, bark and sap are also common ingredients of local herbal remedies.', 'n. 树液, 体液, 活力, 坑道, 笨人, 傻子', '/sæp/', 'sap', 6);
INSERT INTO `words` VALUES (16434, 'Once there is a failed test then it requires sapience on the part of the tester to understand what really happened.', 'n. 贤明', '/\'seipiəns, \'sæ-/', 'sapience', 6);
INSERT INTO `words` VALUES (16435, NULL, 'adj. 装聪明样的, 自以为聪明的, 聪明的, 伶俐的, 有见识的', '/\'seipiənt, \'sæ- | \'seɪpɪənt | \'sepɪənt/', 'sapient', 6);
INSERT INTO `words` VALUES (16436, 'The tender shoots and the expanding flowers are nipped and withered, and of a vine that yearned to stretch its tendril round the world there is left but a sapless stump.', 'adj. 枯萎的', '/\'sæplis | \'sæplɪs/', 'sapless', 6);
INSERT INTO `words` VALUES (16437, 'It becomes a weak, frail sapling.', 'n. 树苗, 小树', '/\'sæpliŋ | \'sæplɪŋ/', 'sapling', 6);
INSERT INTO `words` VALUES (16438, '...a sapphire engagement ring.', 'n. 兰宝石', '/\'sæfaiə | \'sæfaɪə | \'sæfaɪɚ/', 'sapphire', 6);
INSERT INTO `words` VALUES (16439, '‘Good of you to arrive on time,’ George said, with heavy sarcasm (= very clear sarcasm ) .', 'n. 挖苦, 讽刺', '/\'sɑ:kæzəm | \'sɑːkæz(ə)m | \'sɑrkæzəm/', 'sarcasm', 6);
INSERT INTO `words` VALUES (16440, 'Was she being sarcastic?', 'adj. 讽刺的', '/sɑ:\'kæztik | sɑː\'kæstɪk | sɑr\'kæstɪk/', 'sarcastic', 6);
INSERT INTO `words` VALUES (16441, 'He looked at her with sardonic amusement.', 'adj. 讽刺的', '/sɑ:\'dɔnik | sɑː\'dɒnɪk | sɑːrˈdɑːnɪk/', 'sardonic', 6);
INSERT INTO `words` VALUES (16442, 'a man of great sartorial elegance', 'adj. 裁缝的, 缝纫的, [解]缝匠肌的', '/sɑ:\'tɔ:riəl, sə- | sɑː\'tɔːrɪəl | sɑr\'tɔrɪəl/', 'sartorial', 6);
INSERT INTO `words` VALUES (16443, 'She wore a white dress with a thin blue sash.', 'n. 框格, 肩带, 腰带, 飒饰, 窗扇', '/sæʃ/', 'sash', 6);
INSERT INTO `words` VALUES (16444, 'satanic laughter', 'adj. 邪恶的；恶魔的，魔鬼般的', '/sə\'tænik; sei-/', 'satanic', 6);
INSERT INTO `words` VALUES (16445, 'He rested his left handlightly but firmly on the half-opened flap of his satchel.', 'n. 书包, 小背包', '/\'sætʃəl | \'sætʃ(ə)l/', 'satchel', 6);
INSERT INTO `words` VALUES (16446, NULL, 'v. 使心满意足, 过分的给与', '/seɪt | set/', 'sate', 6);
