INSERT INTO `words` VALUES (16449, 'physical feelings of hunger and satiety', 'n. 过饱', '/sə\'taiəti, \'seiʃiəti | sə\'taɪɪtɪ | sə\'taɪəti/', 'satiety', 6);
INSERT INTO `words` VALUES (16450, 'women in tight, satiny dresses', 'adj. 光滑的', '/\'sætini/', 'satiny', 6);
INSERT INTO `words` VALUES (16451, 'the characteristic use of satire in Jonson’s work', 'n. 讽刺文学, 讽刺', '/\'sætaiə | \'sætaɪə | \'sætaɪɚ/', 'satire', 6);
INSERT INTO `words` VALUES (16452, '...a satirical novel about New York life in the late 80s.', 'adj. 好讽刺的, 爱挖苦人的', '/sə\'tirikəl | sə\'tɪrɪk(ə)l | sə\'tɪrɪkl/', 'satirical', 6);
INSERT INTO `words` VALUES (16453, 'a play satirizing the fashion industry', 'v. 讽刺', '/\'sætəraɪz | \'sætə\'raɪz/', 'satirize', 6);
INSERT INTO `words` VALUES (16454, 'Water poured through the hole, saturating the carpet.', 'v. 浸湿， 浸透； 使大量吸收或充满', '/\'sætʃəreɪt | \'sætʃərɪt/', 'saturate', 6);
INSERT INTO `words` VALUES (16455, '...foods rich in cholesterol and saturated fats.', 'adj. 渗透的； 饱和的； 深颜色的', '/\'sætʃəreɪtɪd | \'sætʃəretɪd/', 'saturated', 6);
