INSERT INTO `words` VALUES (16457, 'With Mr Heathcliff, grim and saturnine, on the one hand, and Hareton, absolutely dumb, on the other, I made a somewhat cheerless meal, and bid adieu early.', 'n. 阴郁', '/\'sætə(:)nain | \'sætənaɪn/', 'saturnine', 6);
INSERT INTO `words` VALUES (16458, 'saucy postcards', 'adj. 粗鲁的； 俏皮的； 漂亮的', '/\'sɔːsi | \'sɔsi/', 'saucy', 6);
INSERT INTO `words` VALUES (16459, 'We watched our fellow students saunter into the building.', 'n&v. 闲逛， 漫步', '/\'sɔːntər | \'sɔntɚ/', 'saunter', 6);
INSERT INTO `words` VALUES (16460, 'a savage dog', 'adj. 野蛮的, 未开化的, 凶猛的, 残忍的', '/\'sævɪdʒ/', 'savage', 6);
INSERT INTO `words` VALUES (16461, 'As they travel inland atspeeds in excess of 60 feet a year, they merge with the rich grass andscattered trees of the savanna.', 'n. 热带(或亚热带)稀树大草原', '/sə\'vænə/', 'savanna', 6);
