INSERT INTO `words` VALUES (16463, NULL, 'n. 滋味, 气味, 食欲, 特定的味道或气味, 一种有特色的性质', '/\'seɪvə | \'sevɚ/', 'savor', 6);
INSERT INTO `words` VALUES (16464, 'savvy consumers', 'adj. 有见识的， 精明的', '/\'sævi/', 'savvy', 6);
INSERT INTO `words` VALUES (16465, '...a layer of sawdust.', 'n. 锯屑', '/\'sɔ:dʌst | \'sɔːdʌst | \'sɔ\'dʌst/', 'sawdust', 6);
INSERT INTO `words` VALUES (16466, 'The area can be very painful until scabs form after about ten days.', 'n. 疤, 痂, 不参加罢工的工人, 恶棍, 工贼', '/skæb/', 'scab', 6);
INSERT INTO `words` VALUES (16467, 'David ran and stood over him. He took hold of the Philistine\'s sword and drew it from the scabbard.', 'n. 鞘', '/\'skæbəd | \'skæbɚd/', 'scabbard', 6);
INSERT INTO `words` VALUES (16468, 'It differs in the smaller size of all parts and rufous scabrous tomentum .', 'adj. 粗糙的', '/\'skeibrəs, \'skæ- | \'skeɪbrəs; \'skæbrəs | \'skæbrəs/', 'scabrous', 6);
INSERT INTO `words` VALUES (16469, NULL, 'n. 许多， 巨额', '/skædz/', 'scads', 6);
INSERT INTO `words` VALUES (16470, 'Ascending the shaky ladder to the scaffold, More addressed the executioner.', 'n. [建] 脚手架,绞刑台', '/\'skæfəld, -fəuld | \'skæfəʊld; -f(ə)ld | \'skæfold/', 'scaffold', 6);
INSERT INTO `words` VALUES (16471, 'Scalds, burns and poisoning can all be life-threatening.', 'n. 烫伤,烫洗', '/skɔ:ld | skɔːld | skɔld/', 'scald', 6);
INSERT INTO `words` VALUES (16472, 'a bowl of scalding water', 'adj. 滚烫的,尖刻的', '/\'skɔ:ldiŋ | \'skɔːldɪŋ | \'skɔldɪŋ/', 'scalding', 6);
INSERT INTO `words` VALUES (16473, 'A structural survey revealed the full scale of the damage.', 'n. 刻度,衡量,比例,数值范围,比例尺,天平,等级', '/skeil | skeɪl | skel/', 'scale', 6);
INSERT INTO `words` VALUES (16474, 'Sweat pricked across my back and scalp.', 'v. 剥头皮', '/skælp/', 'scalp', 6);
INSERT INTO `words` VALUES (16475, 'I pointed with my scalpel to the chest cavity, where nothing but a black lump of coal squatted in the lipstick-red center.', 'n. 解剖刀', '/\'skælpəl, skæl\'pel | \'skælp(ə)l | skæl\'pɛl/', 'scalpel', 6);
INSERT INTO `words` VALUES (16476, 'Ho, that Nathan, he is a scamp, no?', 'n. 流氓', '/skæmp/', 'scamp', 6);
INSERT INTO `words` VALUES (16477, 'Children scampered off the yellow school bus and into the playground.', 'v. 奔跳', '/\'skæmpə | \'skæmpɚ/', 'scamper', 6);
INSERT INTO `words` VALUES (16478, 'He scanned the horizon, but there was no sign of the ship.', 'v. 审视， 细看； 浏览， 扫描； 标出格律', '/skæn/', 'scan', 6);
INSERT INTO `words` VALUES (16479, 'It caused quite a scandal when he left his wife.', 'n. 丑行,丑闻,诽谤,耻辱,流言蜚语', '/\'skændəl | \'skænd(ə)l | \'skændl/', 'scandal', 6);
INSERT INTO `words` VALUES (16480, 'The scandalous, seditious and libelous books that need to be brought to justice in this remarkable sentence are suddenly revealed to have a soul.', 'adj. 诽谤性的', '/\'skændələs/', 'scandalous', 6);
INSERT INTO `words` VALUES (16481, 'The story has received scant attention in the press.', 'adj. 缺乏的,不足的,将近的,欠缺的', '/skænt/', 'scant', 6);
