INSERT INTO `words` VALUES (16483, 'He had a long, curved scar on his right cheek.', 'n. 伤痕， 伤疤', '/skɑːr | skɑr/', 'scar', 6);
INSERT INTO `words` VALUES (16484, '...an ever increasing scarcity of water.', 'n. 不足， 缺乏', '/\'skersəti | \'skɛrsəti/', 'scarcity', 6);
