INSERT INTO `words` VALUES (16486, 'At first, he was really scared.', 'adj. 恐惧的', '/skεəd | skeəd | skɛrd/', 'scared', 6);
INSERT INTO `words` VALUES (16487, 'He reached up to loosen the scarf around his neck.', 'n. 围巾, 头巾领巾, 嵌接, 嵌接处, 切口', '/skɑ:f | skɑːf | skɑrf/', 'scarf', 6);
INSERT INTO `words` VALUES (16488, NULL, 'n. 乱割, 乱刺, 松土', '/,skeərɪfɪ\'keɪʃən/', 'scarification', 6);
INSERT INTO `words` VALUES (16489, 'The jacket is of scarlet cloth of a very fine weave.', 'adj. 猩红的， 鲜红的', '/\'skɑːrlət | \'skɑrlɪt/', 'scarlet', 6);
INSERT INTO `words` VALUES (16490, NULL, 'n. 悬崖', '/skɑ:p | skɑːp | skɑrp/', 'scarp', 6);
INSERT INTO `words` VALUES (16491, 'Flood control decision supporting system is a non-project measure that can efficiently lessen the scathe of flood disaster and reduce the damage of flood, it is become more and more important .', 'n. 危害, 损害, 损伤', '/skeið | skeɪð/', 'scathe', 6);
INSERT INTO `words` VALUES (16492, 'If someone excessively flatters you for a minor success, you need to internalize it the same way you would internalize a scathing insult.', 'adj. 严厉的', '/\'skeiðiŋ | \'skeɪðɪŋ | \'skeðɪŋ/', 'scathing', 6);
INSERT INTO `words` VALUES (16493, 'The sound of gunfire made the crowd scatter in all directions.', 'v. 散开， 驱散', '/\'skætər | \'skætɚ/', 'scatter', 6);
INSERT INTO `words` VALUES (16494, 'Pigs scavenged among the rubbish.', 'v. 打扫, 以(腐肉)为食, 从废物中提取', '/\'skævindʒ | \'skævɪn(d)ʒ | \'skævɪndʒ/', 'scavenge', 6);
INSERT INTO `words` VALUES (16495, 'He struck at one with his knife lashed to the end of an oar and watched the scavenger sliding down into deep water.', 'n. 清道夫, 食腐动物', '/\'skævindʒə | \'skævɪn(d)ʒə | \'skævɪndʒɚ/', 'scavenger', 6);
INSERT INTO `words` VALUES (16496, 'Imagine a scenario where only 20% of people have a job.', 'n. 想定游戏的关,或是某一特定情节', '/sɪ\'nɑːrɪəʊ | sə\'nærɪo/', 'scenario', 6);
INSERT INTO `words` VALUES (16497, 'This is an extremely scenic part of America.', 'adj. 风景如画的', '/\'siːnɪk | ˈsinɪk/', 'scenic', 6);
INSERT INTO `words` VALUES (16498, 'a yellow rose with a lovely scent', 'n. 气味, 香味, 香水, 线索, 嗅觉, 臭迹', '/sent | sɛnt/', 'scent', 6);
INSERT INTO `words` VALUES (16499, 'Therefore, let me go, for I must wander again over the world, and may not tarry here, though ye bring me the crown and the sceptre.', 'n. 笏, 节杖, 王权(=scepter)', '/\'septə | \'sɛptɚ/', 'sceptre', 6);
INSERT INTO `words` VALUES (16500, 'Figure 4 shows the schematic of this version.', 'adj. 示意性的', '/ski:\'mætik | skiː\'mætɪk; skɪ- | ski\'mætɪk/', 'schematic', 6);
