INSERT INTO `words` VALUES (16611, 'a moment of self-doubt', 'n. 自我怀疑', '/ˌself\'daut | \'self\'daut/', 'self-doubt', 6);
INSERT INTO `words` VALUES (16612, 'He was modest to the point of self-effacement.', 'n. 自谦', '/ˌselfɪ\'fesmənt | \'selfə\'feismənt/', 'self-effacement', 6);
