INSERT INTO `words` VALUES (16614, 'The Topmost Degree of the Human Nature——A study of Maslow\'s theory of self-realization;', 'n. 自我实现， 自我完成', '/ˌselfˌriːələ\'zeɪʃn | \'sɛlf,rɪəlɪ\'zeʃən/', 'self-realization', 6);
