INSERT INTO `words` VALUES (16626, 'Only he, as seneschal, was granted that privilege, particularly while the master lay ill.', 'n. (中世纪贵族城堡中)管家', '/\'senəfəl, -ni- | \'senɪʃ(ə)l | \'sɛnɪfəl/', 'seneschal', 6);
INSERT INTO `words` VALUES (16627, 'a senile old man', 'adj. 老年的, 高龄的, 衰老的', '/\'si:nail, \'se- | \'siːnaɪl | \'sinaɪl/', 'senile', 6);
INSERT INTO `words` VALUES (16628, NULL, 'n. 高龄, 老迈年高, 老态龙钟', '/si\'niləti, se- | sɪ\'nɪlɪtɪ | sɛ\'nɪləti/', 'senility', 6);
INSERT INTO `words` VALUES (16629, 'Jerry realized that he had no sensation in his legs.', 'n. 感觉, 感情, 感动, 耸人听闻的', '/sen\'seiʃən | sen\'seɪʃ(ə)n | sɛn\'seʃən/', 'sensation', 6);
INSERT INTO `words` VALUES (16630, 'She looked sensational.', 'adj. 使人感动的, 非常好的', '/sen\'seiʃənəl | sen\'seɪʃ(ə)n(ə)l | sɛn\'seʃənl/', 'sensational', 6);
INSERT INTO `words` VALUES (16631, 'She seems very sensible.', 'adj. 明智的； 可感觉到的', '/\'sensəbl | \'sɛnsəbl/', 'sensible', 6);
