INSERT INTO `words` VALUES (16637, NULL, 'n. 好色,淫荡,感觉性', '/,sensju\'æliti, -ʃu- | sensjʊ\'ælɪtɪ; senʃʊ- | ,sɛnʃʊ\'ælɪti/', 'sensuality', 6);
INSERT INTO `words` VALUES (16638, 'sententious remarks', 'adj. 简洁的, 警句的, 富于格言的, 很多(过分)说教式的', '/sen\'tenʃəs | sɛn\'tɛnʃəs/', 'sententious', 6);
INSERT INTO `words` VALUES (16639, 'Man is a sentient being.', 'adj. 有感觉力的, 有感情的, 感觉灵敏的, 意识到的', '/\'senʃiənt, -tiə- | ˈsentiənt | \'sɛntɪənt/', 'sentient', 6);
INSERT INTO `words` VALUES (16640, 'There’s no place for sentiment in business!', 'n. 多愁善感； 思想感情', '/\'sentɪmənt | \'sɛntɪmənt/', 'sentiment', 6);
INSERT INTO `words` VALUES (16641, 'novels that sentimentalize the past', 'v. 感伤', '/ˌsentɪ\'mentəlaɪz | ,sɛntɪ\'mɛntəlaɪz/', 'sentimentalize', 6);
INSERT INTO `words` VALUES (16642, 'A sentinel struck the rings of his carbine against his left hand.', 'n. 哨兵， 岗哨', '/\'sentɪnl | \'sɛntɪnl/', 'sentinel', 6);
INSERT INTO `words` VALUES (16643, 'The sentry would not let her enter.', 'n. 岗哨', '/\'sentri | \'sentrɪ | \'sɛntri/', 'sentry', 6);
INSERT INTO `words` VALUES (16644, 'This will keep your dressing from separating.', 'v. 使分开; adj. 不同的； 独自的', '/(for v.) ˈsepəreɪt; (for adj.) ˈseprət | (for v.) sɛpəˌret; (for adj.) sɛprɪt/', 'separate', 6);
INSERT INTO `words` VALUES (16645, 'Treatment should be discontinued for serious infection or sepsis.', 'n. [医]脓毒病, 脓血症', '/\'sepsis | \'sepsɪs | \'sɛpsɪs/', 'sepsis', 6);
INSERT INTO `words` VALUES (16646, 'a cut that went septic', 'adj. 腐败的, 败血病的, 脓毒性的', '/\'septik | \'septɪk | \'sɛptɪk/', 'septic', 6);
