INSERT INTO `words` VALUES (16648, 'a sepulchral voice', 'adj. 坟墓的, 埋葬的', '/si\'pʌlkrəl, -\'pul- | sɪ\'pʌlkr(ə)l | sə\'pʌlkrəl/', 'sepulchral', 6);
INSERT INTO `words` VALUES (16649, 'Teenagers are very sequacious and they often emulate the behavior of their idols who are sometimes negative role models.', 'adj. 盲从的', '/sɪ\'kweɪʃəs | sɪ\'kweʃəs/', 'sequacious', 6);
