INSERT INTO `words` VALUES (16652, 'He tried to prevent union money from being sequestrated by the courts.', 'v. 扣押, 没收', '/si\'kwestreit | \'siːkwəstreɪt; \'siːkwes- | \'sikwəstret/', 'sequestrate', 6);
