INSERT INTO `words` VALUES (16654, 'The trees begin to proclaim the change. Soon the leaves will be discarded, the grass will sere.', 'adj. 干枯的', '/siə | sɪə | sɪr/', 'sere', 6);
INSERT INTO `words` VALUES (16655, 'Placido Domingo sang his serenade of love.', 'n. 小夜曲', '/,serə\'neid | serə\'neɪd | ,sɛrə\'ned/', 'serenade', 6);
INSERT INTO `words` VALUES (16656, 'Some of the best effects in my garden have been the result of serendipity.', 'n. 有意外发现珍宝的运气', '/,serən\'dipəti | ,ser(ə)n\'dɪpɪtɪ | ,sɛrən\'dɪpəti/', 'serendipity', 6);
INSERT INTO `words` VALUES (16657, 'The child’s face was serene and beautiful.', 'adj. 平静的， 安详的； 清澈的； 晴朗的', '/sə\'riːn | sə\'rin/', 'serene', 6);
INSERT INTO `words` VALUES (16658, 'It was their serenity which galled her most.', 'n. 平静', '/sə\'renəti | si\'renəti/', 'serenity', 6);
INSERT INTO `words` VALUES (16659, 'Keep the questions in the same serial order .', 'adj. 连续的， 一系列的', '/\'sɪriəl | \'sɪrɪəl/', 'serial', 6);
INSERT INTO `words` VALUES (16660, NULL, 'n. 认真， 严肃； 严重性， 严峻', '/\'sɪriəsnəs | \'sɪrɪəsnəs/', 'seriousness', 6);
INSERT INTO `words` VALUES (16661, 'Cardinal Murphy will deliver the sermon on Sunday.', 'n. 布道； 说教， 训诫', '/\'sɜːrmən | \'sɝmən/', 'sermon', 6);
