INSERT INTO `words` VALUES (16664, 'the serried ranks of reporters waiting outside', 'adj. 密集的, 林立的, 重叠罗列的', '/\'serid | \'serɪd | \'sɛrɪd/', 'serried', 6);
INSERT INTO `words` VALUES (16665, 'Some of these old tools are still serviceable.', 'adj. 可用的， 耐用的', '/\'sɜːrvɪsəbl | \'sɝvɪsəbl/', 'serviceable', 6);
