INSERT INTO `words` VALUES (16667, 'Nothing’s settled yet.', 'v. 安排； 决定； 栖息', '/\'setl | \'sɛtl/', 'settle', 6);
INSERT INTO `words` VALUES (16668, 'She was tired of moving around and longed for a more settled existence.', 'adj. 固定的', '/\'setld | \'sɛtld/', 'settled', 6);
