INSERT INTO `words` VALUES (16671, 'His injuries were quite severe.', 'adj. 严厉的； 剧烈的', '/sɪ\'vɪr | səˈvɪr/', 'severe', 6);
INSERT INTO `words` VALUES (16672, '...the city\'s sewer system.', 'n. 下水道, 缝具, 缝纫者', '/\'sjuə, \'su:ə | \'suːə; \'sjuːə | \'suɚ/', 'sewer', 6);
INSERT INTO `words` VALUES (16673, 'Unlike decimal coordinates, which you can determine using a sextant and a chronometer, you cannot determine UTM coordinates without calculations.', 'n. 六分仪, <罕>圆的六分之一', '/\'sekstənt | \'sekst(ə)nt | \'sɛkstənt/', 'sextant', 6);
INSERT INTO `words` VALUES (16674, 'Hugh’s jacket was old and shabby.', 'adj. 破旧的, 褴褛的, 低劣的, 卑鄙的, 不公平的', '/\'ʃæbi | \'ʃæbɪ | ˈʃæbi/', 'shabby', 6);
