INSERT INTO `words` VALUES (16688, 'Shareholders have been told to expect an even lower result next year.', 'n. 股东', '/\'ʃεə,həuldə | \'ʃeəhəʊldə | \'ʃɛrholdɚ/', 'shareholder', 6);
INSERT INTO `words` VALUES (16689, 'Her gaze sharpened, as if she had seen something unusual.', 'v. 削尖； 使敏锐， 使敏捷', '/\'ʃɑːrpən | \'ʃɑrpən/', 'sharpen', 6);
INSERT INTO `words` VALUES (16690, 'The explosion shattered the building.', 'v. 使落下， 使散开； 砸碎， 粉碎； 破坏， 毁坏', '/\'ʃætər | \'ʃætɚ/', 'shatter', 6);
INSERT INTO `words` VALUES (16691, 'We had one person who walked out of an interview straight into a glass door. The glass shattered.', 'adj. 破碎的', '/\'ʃætərd | \'ʃætɚd/', 'shattered', 6);
INSERT INTO `words` VALUES (16692, 'She muffled up her face in her shawl.', 'n. 披肩, 围巾', '/ʃɔ:l | ʃɔːl | ʃɔl/', 'shawl', 6);
