INSERT INTO `words` VALUES (16694, 'Competitors have six minutes to shear four sheep.', 'v. 剪, 修剪, 剪切', '/ʃiə | ʃɪə | ʃɪr/', 'shear', 6);
INSERT INTO `words` VALUES (16695, 'Sam was trimming the hedge with a pair of garden shears .', 'n. 大剪刀, 剪床', '/ʃiəz | ʃɪəz | ʃɪrz/', 'shears', 6);
