INSERT INTO `words` VALUES (16697, 'The company is planning to shed about a quarter of its workforce.', 'v. 流出, 发散, 散发, 脱落, 脱皮, 摆脱', '/ʃed | ʃɛd/', 'shed', 6);
INSERT INTO `words` VALUES (16698, 'Her hair had a lovely coppery sheen.', 'n. 光辉', '/ʃi:n | ʃiːn | ʃin/', 'sheen', 6);
INSERT INTO `words` VALUES (16699, 'sheer stockings', 'adj. 完全的； 陡峭的； 极薄的', '/ʃɪr/', 'sheer', 6);
INSERT INTO `words` VALUES (16700, 'Josie was shelling peas in the kitchen.', 'v. 剥去…的壳; n. 贝壳；炮弹', '/ʃel | ʃɛl/', 'shell', 6);
INSERT INTO `words` VALUES (16701, 'Collins was arrested for sheltering enemy soldiers.', 'v. 庇护， 保护; n. 避难所，遮蔽', '/\'ʃeltər | \'ʃɛltɚ/', 'shelter', 6);
INSERT INTO `words` VALUES (16702, 'The island is normally protected from extreme weather conditions by its sheltered location in the Inner Hebrides.', 'adj. 遮蔽的', '/\'ʃeltərd | \'ʃɛltɚd/', 'sheltered', 6);
INSERT INTO `words` VALUES (16703, 'King County has shelved plans to build a driving range.', 'v. 置于架子上, 缓议, 搁置, 解雇', '/ʃelv | ʃɛlv/', 'shelve', 6);
INSERT INTO `words` VALUES (16704, 'He took me out to the county fair to see the county sheriff, whose support Ron said we had to have to carry the county.', 'n. 郡治安官, 州长', '/\'ʃerif | \'ʃerɪf | \'ʃɛrɪf/', 'sheriff', 6);
INSERT INTO `words` VALUES (16705, 'Even their commitment to abolishing university tuition fees, a shibboleth in a party with a large student following, may be wavering.', 'n. 口令', '/\'ʃibəleθ, -liθ | \'ʃɪbəleθ | \'ʃɪbəlɛθ/', 'shibboleth', 6);
INSERT INTO `words` VALUES (16706, 'Women will often lie to shield even the most abusive partner.', 'v. 掩护， 保护; n. 盾', '/ʃiːld | ʃild/', 'shield', 6);
INSERT INTO `words` VALUES (16707, 'The Croatian town of Ilok is a classic case of shifting populations.', 'adj. 变动的； 运动的', '/\'ʃɪftɪŋ | ʃɪftɪŋ/', 'shifting', 6);
INSERT INTO `words` VALUES (16708, '...a shiftless husband.', 'adj. 想不出办法的, 偷懒的, 无能的', '/\'ʃiftlis | \'ʃɪftlɪs | \'ʃɪftləs/', 'shiftless', 6);
INSERT INTO `words` VALUES (16709, 'It\'s time for Brooke to stop shilly-shallying.', 'v. 犹豫不决； 虚度时光', '/\'ʃɪliʃæli | \'ʃili,ʃæli/', 'shilly-shally', 6);
INSERT INTO `words` VALUES (16710, '...a shimmer of starlight.', 'n. 微光', '/\'ʃimə | \'ʃɪmə | \'ʃɪmɚ/', 'shimmer', 6);
INSERT INTO `words` VALUES (16711, NULL, 'n. 喧哗, 奢华舞会, 大宴会', '/\'ʃindi | \'ʃɪndɪ | \'ʃɪndi/', 'shindy', 6);
INSERT INTO `words` VALUES (16712, 'the crash of waves on the shingle', 'n. 鹅卵石, <美口>小招牌(尤指医生或律师挂的营业招牌)', '/\'ʃiŋɡl | \'ʃɪŋg(ə)l | \'ʃɪŋɡl/', 'shingle', 6);
INSERT INTO `words` VALUES (16713, 'shiny black shoes', 'adj. 有光泽的； 发光的', '/\'ʃaɪni/', 'shiny', 6);
INSERT INTO `words` VALUES (16714, 'Let’s get this house shipshape.', 'adj. 井然有序的', '/\'ʃipʃeip | \'ʃɪpʃeɪp | \'ʃɪpʃep/', 'shipshape', 6);
INSERT INTO `words` VALUES (16715, 'What is he that builds stronger than either the mason, the shipwright, or the carpenter?', 'n. 造船工人, 造船木匠', '/\'ʃiprait | \'ʃɪpraɪt | \'ʃɪp,raɪt/', 'shipwright', 6);
INSERT INTO `words` VALUES (16716, 'He was fired for shirking.', 'v. 逃避, 推卸', '/ʃə:k | ʃɜːk/', 'shirk', 6);
