INSERT INTO `words` VALUES (16719, 'The salesman tried to palm us off with some shopsoiled sheets.', 'adj. 陈列[搁置]久了的，陈旧的', '/\'ʃɔp\'sɔild | \'ʃɒp\'sɒɪld | \'ʃɑp,sɔɪld/', 'shopsoiled', 6);
INSERT INTO `words` VALUES (16720, 'shopworn management techniques', 'adj. 在商店中陈列久了的； 陈旧的， 磨损的', '/\'ʃɑːpwɔːrn | \'ʃɑpwɔrn/', 'shopworn', 6);
INSERT INTO `words` VALUES (16721, NULL, 'n. 目光短浅； 近视', '/ˌʃɔːrt\'saɪtɪdnəs/', 'short-sightedness', 6);
INSERT INTO `words` VALUES (16722, NULL, 'adj. 近程的', '/ˌʃɔːrt\'reɪndʒ/', 'shortrange', 6);
INSERT INTO `words` VALUES (16723, 'As you get older, you may become long-sighted or shortsighted.', 'adj. 缺乏远见的； 近视的', '/ˌʃɔːrt\'saɪtɪd | \'ʃɔ:\'saitid/', 'shortsighted', 6);
INSERT INTO `words` VALUES (16724, 'Give the door a good shove .', 'n. <口>推, 挤', '/ʃʌv/', 'shove', 6);
INSERT INTO `words` VALUES (16725, '...a coal shovel.', 'n. 铲, 铁铲', '/\'ʃʌvəl | \'ʃʌv(ə)l | \'ʃʌvl/', 'shovel', 6);
INSERT INTO `words` VALUES (16726, 'The factory was to be a showpiece of Western investment in the East.', 'n. 展出品, 样品', '/\'ʃəupi:s | \'ʃəʊpiːs | \'ʃopis/', 'showpiece', 6);
INSERT INTO `words` VALUES (16727, 'an attractive shrub with showy flowers', 'adj. 浮华的, (过分)艳丽的, 炫耀的, 卖弄的', '/\'ʃəui | \'ʃəʊɪ | \'ʃoi/', 'showy', 6);
INSERT INTO `words` VALUES (16728, 'Cut the cabbage into fine long shreds.', 'n. 碎片, 破布, 少量剩余, 最少量', '/ʃred | ʃrɛd/', 'shred', 6);
INSERT INTO `words` VALUES (16729, 'Malcolm is a shrewd businessman.', 'adj. 精明', '/ʃru:d | ʃruːd | ʃrud/', 'shrewd', 6);
INSERT INTO `words` VALUES (16730, 'They were dragged from their homes, shrieking and weeping.', 'v. 尖声叫喊, 耸人听闻地报道, 尖声喊叫', '/ʃri:k | ʃriːk | ʃrik/', 'shriek', 6);
INSERT INTO `words` VALUES (16731, '‘That’s not true,’ she protested in a shrill voice.', 'adj. 尖声的', '/ʃril | ʃrɪl/', 'shrill', 6);
INSERT INTO `words` VALUES (16732, 'Elvis’ home has become a shrine for his fans.', 'n. 神龟, 神殿, 神祠, 圣地', '/ʃrain | ʃraɪn/', 'shrine', 6);
INSERT INTO `words` VALUES (16733, 'I’m worried about washing that shirt in case it shrinks.', 'v. 收缩, (使)皱缩, 缩短', '/ʃrɪŋk/', 'shrink', 6);
INSERT INTO `words` VALUES (16734, 'The leaves started to shrivel up.', 'v. (使)起皱纹, (使)枯萎, (使)束手无策', '/\'ʃrivəl | ʃrɪv(ə)l | \'ʃrɪvl/', 'shrivel', 6);
INSERT INTO `words` VALUES (16735, 'The fog rolled in, and a grey shroud covered the city.', 'n. 裹尸布, 寿衣, 覆盖物, 船的横桅索', '/ʃraud | ʃraʊd/', 'shroud', 6);
INSERT INTO `words` VALUES (16736, '\"I suppose so,\" said Anna with a shrug.', 'n. 耸肩', '/ʃrʌɡ | ʃrʌg/', 'shrug', 6);
INSERT INTO `words` VALUES (16737, '...corn shucks.', 'n. 壳', '/ʃʌk/', 'shuck', 6);
INSERT INTO `words` VALUES (16738, 'Maria shuddered as she stepped outside.', 'v. 战栗，发抖; n. 战栗， 发抖', '/\'ʃʌdər | \'ʃʌdɚ/', 'shudder', 6);
INSERT INTO `words` VALUES (16739, 'She noticed her own proud walk had become a shuffle.', 'n. 拖着脚走, 混乱, 蒙混, 洗纸牌', '/\'ʃʌfl | \'ʃʌf(ə)l/', 'shuffle', 6);
INSERT INTO `words` VALUES (16740, 'a shy woman who shunned publicity', 'v. 避开, 避免', '/ʃʌn/', 'shun', 6);
INSERT INTO `words` VALUES (16741, NULL, 'v. 逃避', '/ʃʌnt/', 'shunt', 6);
INSERT INTO `words` VALUES (16742, 'The passengers were shuttled to the hotel by bus.', 'v. 穿梭移动， 往返运送', '/\'ʃʌtl/', 'shuttle', 6);
INSERT INTO `words` VALUES (16743, NULL, 'n. 讼棍, 奸诈之徒(尤指政客)', '/\'ʃaistə | \'ʃaɪstə/', 'shyster', 6);
INSERT INTO `words` VALUES (16744, 'a sibilant whisper', 'adj. 咝咝作声的', '/\'sibilənt | \'sɪbɪl(ə)nt | \'sɪbɪlənt/', 'sibilant', 6);
INSERT INTO `words` VALUES (16745, 'Most young smokers are influenced by their friends’ and older siblings’ smoking habits.', 'n. 兄弟, 姐妹, 同胞, 同属', '/\'sibliŋ | \'sɪblɪŋ/', 'sibling', 6);
INSERT INTO `words` VALUES (16746, 'The sibyl prophesied victory.', 'n. 女巫, 女算命师, (古罗马或古希腊的)女预言家', '/\'sibil | \'sɪbɪl | \'sɪbl/', 'sibyl', 6);
INSERT INTO `words` VALUES (16747, 'In these sibylline leaves are gathered the scattered prophecies of the past upon the cases in which the axe will fall.', 'adj. 女巫的, 预言性的', '/\'sibilain, -li:n | \'sɪbɪlaɪn/', 'sibylline', 6);
INSERT INTO `words` VALUES (16748, 'It was quite a lucrative sideline.', 'n. 副业， 兼职', '/\'saɪdlaɪn/', 'sideline', 6);
INSERT INTO `words` VALUES (16749, 'Tropical year , and sidereal year are two different concepts .', 'adj. 恒星的', '/sai\'diəriəl, si- | saɪ\'dɪərɪəl | saɪ\'dɪrɪəl/', 'sidereal', 6);
INSERT INTO `words` VALUES (16750, NULL, 'n. 杂耍， 穿插表演', '/\'saɪdʃou | \'saɪdʃo/', 'sideshow', 6);
INSERT INTO `words` VALUES (16751, 'He told some sidesplitting jokes.', 'adj. 令人捧腹大笑的', '/\'said,splitiŋ | \'saɪd,splɪtɪŋ/', 'sidesplitting', 6);
INSERT INTO `words` VALUES (16752, 'The report sidesteps the environmental issues.', 'v. 横跨一步躲避； 回避', '/\'saɪdstep | \'saɪdstɛp/', 'sidestep', 6);
INSERT INTO `words` VALUES (16753, 'A young man sidled up to me and said, \"May I help you?\"', 'v. 横着走, 悄悄贴近, 侧身而行', '/saidl | \'saɪd(ə)l | \'saɪdl/', 'sidle', 6);
INSERT INTO `words` VALUES (16754, 'The siege lasted almost four months.', 'n. 包围, 围城, 长期努力, 不断袭击, 围攻', '/si:dʒ | siːdʒ | sidʒ/', 'siege', 6);
INSERT INTO `words` VALUES (16755, 'Press the raspberries through a fine sieve to form a puree.', 'n. 筛, 滤网, 不会保密的人', '/siv | sɪv/', 'sieve', 6);
INSERT INTO `words` VALUES (16756, 'Police are sifting through the evidence.', 'v. 详审', '/sift | sɪft/', 'sift', 6);
INSERT INTO `words` VALUES (16757, NULL, 'n. 负责筛选的人, 筛子', '/\'siftə/', 'sifter', 6);
INSERT INTO `words` VALUES (16758, 'The sailors gave a shout of joy when they sighted land .', 'v. 看到; n. 景象；视力；视野', '/saɪt/', 'sight', 6);
INSERT INTO `words` VALUES (16759, 'Her signature is totally illegible (= cannot be read ) .', 'n. 签名， 署名', '/\'sɪgnətʃər | \'sɪgnətʃɚ/', 'signature', 6);
INSERT INTO `words` VALUES (16760, 'A significant number of drivers fail to keep to speed limits.', 'adj. 相当数量的； 意义重大的', '/sɪg\'nɪfɪkənt | sɪɡ\'nɪfɪkənt/', 'significant', 6);
INSERT INTO `words` VALUES (16761, 'These figures don’t really signify in the overall results.', 'v. 表示； 有重要性', '/\'sɪgnɪfaɪ | \'sɪɡnɪfaɪ/', 'signify', 6);
INSERT INTO `words` VALUES (16762, 'silhouette pictures of snowmen and reindeer', 'n. 侧面影象, 轮廓', '/,silu:\'et, -lu- | ,sɪlʊ\'et | ,sɪlu\'ɛt/', 'silhouette', 6);
INSERT INTO `words` VALUES (16763, 'Whitlock was perched on the sill of the room\'s only window.', 'n. 基石,门槛,窗台,[地质]岩床', '/sil | sɪl/', 'sill', 6);
INSERT INTO `words` VALUES (16764, 'The lake was almost solid with silt and vegetation.', 'n. 淤泥, 残渣, 煤粉, 泥沙', '/silt | sɪlt/', 'silt', 6);
INSERT INTO `words` VALUES (16765, NULL, 'n. 森林里的树木, 森林, 森林志', '/\'silvə/', 'silva', 6);
INSERT INTO `words` VALUES (16766, 'Or perhaps the image came not from humans, but from some natural-history programme about our simian relatives, who spend much of their time literally nit-picking as part of grooming.', 'n. 猿', '/\'simiən | \'sɪmɪən/', 'simian', 6);
INSERT INTO `words` VALUES (16767, 'Lister said people should follow the 1946 advice of writer George Orwell: \"Never use a metaphor, simile, or other figure of speech which you are used to seeing in print.', 'n. [修辞]明喻, 明喻的说法, 明喻的词语用法', '/\'simili | \'sɪmɪlɪ | \'sɪməli/', 'simile', 6);
INSERT INTO `words` VALUES (16768, 'Bring the soup to the boil and allow it to simmer gently for about half an hour.', 'v. 炖，慢煮; n. 即将沸腾的状态， 即将发作', '/\'sɪmər | \'sɪmɚ/', 'simmer', 6);
INSERT INTO `words` VALUES (16769, NULL, 'v. 给…打蜡， 把…擦亮', '/\'saimənaiz | \'saɪmənaɪz/', 'simonize', 6);
INSERT INTO `words` VALUES (16770, 'We’re simpatico about most things.', 'adj. 和谐的, 讨人喜欢的, 令人亲近的', '/sɪm\'pætɪkəʊ/', 'simpatico', 6);
INSERT INTO `words` VALUES (16771, '\"Thank you doctor,\" said the nurse with a simper.', 'n. 痴笑, 假笑', '/\'simpə | \'sɪmpə | \'sɪmpɚ/', 'simper', 6);
INSERT INTO `words` VALUES (16772, 'This is a very simplistic approach to the problem.', 'adj. 过分简单化的', '/sɪm\'plɪstɪk/', 'simplistic', 6);
INSERT INTO `words` VALUES (16773, 'a machine that simulates conditions in space', 'v. 模拟, 模仿, 假装, 冒充', '/\'simjuleit | \'sɪmjʊleɪt | \'sɪmjulet/', 'simulate', 6);
INSERT INTO `words` VALUES (16774, 'a computer simulation used to train airline pilots', 'n. 模拟', '/ˌsɪmju\'leɪʃn | \'sɪmjə\'leʃən/', 'simulation', 6);
INSERT INTO `words` VALUES (16775, 'They grabbed each other’s hands in simultaneous panic.', 'adj. 同时的, 同时发生的', '/,siməl\'teiniəs | ,sɪm(ə)l\'teɪnɪəs | ,saɪml\'tenɪəs/', 'simultaneous', 6);
INSERT INTO `words` VALUES (16776, 'Please accept my sincere apologies .', 'adj. 诚实的， 坦率的； 诚挚的', '/sɪn\'sɪr/', 'sincere', 6);
INSERT INTO `words` VALUES (16777, 'I don’t doubt her sincerity, but I think she’s got her facts wrong.', 'n. 诚挚', '/sɪn\'serəti | sɪn\'sɪərəti/', 'sincerity', 6);
INSERT INTO `words` VALUES (16778, 'She found him an exalted sinecure as a Fellow of the Library of Congress.', 'n. 工作清闲而报酬丰厚的职位, 挂名职务, 闲职', '/\'saini,kjuə, \'sinu- | \'sɪnɪkjʊə(r) | \'saɪnɪkjʊr/', 'sinecure', 6);
INSERT INTO `words` VALUES (16779, 'The sinews on his neck stood out like knotted string.', 'n. 肌肉, 精力, 体力, 原动力, [解]腱', '/\'sinju: | \'sɪnjuː | \'sɪnju/', 'sinew', 6);
INSERT INTO `words` VALUES (16780, 'a big man with long, sinewy arms', 'adj. 强壮有力的', '/\'sinju:i | \'sɪnjuːɪ | \'sɪnjui/', 'sinewy', 6);
INSERT INTO `words` VALUES (16781, 'The flames had singed her hair.', 'v. 烧焦, 烤焦', '/sindʒ | sɪn(d)ʒ | sɪndʒ/', 'singe', 6);
INSERT INTO `words` VALUES (16782, 'He had an attractive singularity of viewpoint.', 'n. 单一, 异常, 奇异, 奇妙, 稀有', '/,siŋɡju\'læriti | sɪŋgjʊ\'lærɪtɪ | \'sɪŋgjə\'lærəti/', 'singularity', 6);
INSERT INTO `words` VALUES (16783, 'There is a sinister side to these events.', 'adj. 险恶的', '/\'sinistə | \'sɪnɪstə | \'sɪnɪstɚ/', 'sinister', 6);
INSERT INTO `words` VALUES (16784, 'The history never if, the history has sinuate fact only.', 'adj. 弯弯曲曲的, 波状的', '/\'sinjuəit, -eit, \'sinjueit | \'sɪnjʊət/', 'sinuate', 6);
INSERT INTO `words` VALUES (16785, 'the sinuous grace of a cat', 'adj. 蜿蜒的, 错综复杂的, 动作复杂的, 不老实的', '/\'sinjuəs | \'sɪnjʊəs/', 'sinuous', 6);
INSERT INTO `words` VALUES (16786, 'Bees sip honey from flowers and hum their thanks when they leave.', 'v. 吸吮', '/sip | sɪp/', 'sip', 6);
INSERT INTO `words` VALUES (16787, 'the wail of the ambulance sirens', 'n. 汽笛, 警报器, 空袭警报, 妖妇', '/\'saiərən | ˈsaɪərən | \'saɪrən/', 'siren', 6);
INSERT INTO `words` VALUES (16788, NULL, 'n. 极烫的东西, 炎热天', '/\'sɪzlə | \'sɪzlɚ/', 'sizzler', 6);
INSERT INTO `words` VALUES (16789, 'a skein of lies', 'n. (一)束, (一)群, 一团糟', '/\'skein | skeɪn | sken/', 'skein', 6);
INSERT INTO `words` VALUES (16790, 'Not all theory that we read in this course is skeptical.', 'adj. 怀疑性的,好怀疑的,<口>无神论的', '/\'skeptikəl | \'skeptɪkəl | \'skɛptɪkl/', 'skeptical', 6);
INSERT INTO `words` VALUES (16791, 'Holford sketched a 10-year programme for rebuilding the city.', 'v. 画草图， 写概略; n. 草图，概略', '/sketʃ | skɛtʃ/', 'sketch', 6);
INSERT INTO `words` VALUES (16792, 'Details of the accident are still sketchy .', 'adj. 粗略的', '/\'sketʃi | \'sketʃɪ/', 'sketchy', 6);
INSERT INTO `words` VALUES (16793, 'However there is some notable right skew.', 'adj. 歪斜的', '/skjuː | skju/', 'skew', 6);
INSERT INTO `words` VALUES (16794, NULL, 'n. (烤肉用的)串肉扦, 扦, 棒', '/\'skjuə | \'skjuːə | \'skjʊɚ/', 'skewer', 6);
INSERT INTO `words` VALUES (16795, 'May I have the use of your skiff?', 'n. 小船', '/skif | skɪf/', 'skiff', 6);
INSERT INTO `words` VALUES (16796, 'A chefs skillet, poêle, has sloping sides and is used for browning and tossing small pieces of food like mushrooms or chicken livers; the long handle makes it easy to toss rather than turn the food.', 'n. 煮锅, 长柄浅锅', '/\'skilit | \'skɪlɪt/', 'skillet', 6);
INSERT INTO `words` VALUES (16797, 'Julie skimmed the sports page.', 'v. 从液体表面撇去； 浏览， 略读', '/skɪm/', 'skim', 6);
