INSERT INTO `words` VALUES (16799, 'a skimpy meal', 'adj. 不足的, 吝啬的', '/\'skimpi | \'skɪmpɪ/', 'skimpy', 6);
INSERT INTO `words` VALUES (16800, 'A skinflint worships money.', 'n. 吝啬鬼', '/\'skinflint | \'skɪnflɪnt/', 'skinflint', 6);
INSERT INTO `words` VALUES (16801, 'Border skirmishes between India and Pakistan were common.', 'n. 小冲突', '/\'skə:miʃ | \'skɜːmɪʃ | \'skɝmɪʃ/', 'skirmish', 6);
INSERT INTO `words` VALUES (16802, 'a disappointing speech that skirted around all the main issues', 'v. 绕过， 回避', '/skɜːrt | skɝt/', 'skirt', 6);
INSERT INTO `words` VALUES (16803, '...clever skits on popular songs.', 'n. 讽刺话, 幽默故事, 若干, 一群', '/skit | skɪt/', 'skit', 6);
INSERT INTO `words` VALUES (16804, 'Some skittish Wall Street investors are staying away from the market.', 'adj. 轻浮的， 活泼的', '/\'skɪtɪʃ/', 'skittish', 6);
INSERT INTO `words` VALUES (16805, '...accusations of political skulduggery.', 'n. 欺骗, 作假, 使诈, 诡计', '/skʌl\'dʌɡəri, \'skʌld-/', 'skulduggery', 6);
INSERT INTO `words` VALUES (16806, 'You, meanwhile, will be skulking in the safety of the car.', 'v. 偷偷隐躲, 偷懒', '/skʌlk/', 'skulk', 6);
INSERT INTO `words` VALUES (16807, 'Her husband was later treated for a fractured skull.', 'n. 头脑, 头骨', '/skʌl/', 'skull', 6);
INSERT INTO `words` VALUES (16808, 'There must be political skullduggery afoot!', 'n. 欺骗， 使诈', '/skʌl\'dʌgərɪ | skʌl\'dʌɡəri/', 'skullduggery', 6);
INSERT INTO `words` VALUES (16809, NULL, 'n. [动]臭鼬, 臭鼬皮, 讨厌鬼', '/skʌŋk/', 'skunk', 6);
INSERT INTO `words` VALUES (16810, 'The trade deficit has skyrocketed.', 'n. 流星焰火', '/\'skai,rɔkit | \'skaɪrɒkɪt | \'skaɪ\'rɑkɪt/', 'skyrocket', 6);
INSERT INTO `words` VALUES (16811, 'a concrete slab', 'n. 厚平板, 厚片, 混凝土路面, 板层', '/slæb/', 'slab', 6);
INSERT INTO `words` VALUES (16812, 'Keep the rope slack until I tell you to pull it.', 'adj. 懈怠的，不活跃的；松弛的; v. 懈怠， 偷懒', '/slæk/', 'slack', 6);
INSERT INTO `words` VALUES (16813, 'The heavy rain showed no signs of slackening off.', 'v. 松弛, 放慢, 减弱, 减少, 减缓放慢', '/\'slækən | \'slæk(ə)n/', 'slacken', 6);
INSERT INTO `words` VALUES (16814, 'He\'s not a slacker, he\'s the best worker they\'ve got.', 'n. 懒鬼', '/\'slækə | \'slækɚ/', 'slacker', 6);
INSERT INTO `words` VALUES (16815, NULL, 'n. 矿渣, 炉渣, 火山岩渣', '/slæɡ | slæg/', 'slag', 6);
INSERT INTO `words` VALUES (16816, 'This is its chance to slake the insecurities built during the isolationist years of the Cultural Revolution.', 'v. 消除', '/sleɪk | slek/', 'slake', 6);
INSERT INTO `words` VALUES (16817, 'He accused me of slandering him and trying to undermine his position.', 'v. 诽谤，诋毁; n. 诽谤， 中伤', '/\'slændər | \'slændɚ/', 'slander', 6);
INSERT INTO `words` VALUES (16818, 'slanderous remarks', 'adj. 诽谤性的', '/\'slɑ:ndərəs, \'slæn- | \'slɑːnd(ə)rəs; \'slænd(ə)rəs | \'slændərəs/', 'slanderous', 6);
INSERT INTO `words` VALUES (16819, 'The sun’s rays slanted through the trees.', 'v. (使)倾斜, 歪向', '/slɑ:nt, slænt | slɑːnt | slænt/', 'slant', 6);
INSERT INTO `words` VALUES (16820, 'a very slapdash piece of work', 'adj. 匆促的', '/slæpdæʃ | \'slæpdæʃ/', 'slapdash', 6);
INSERT INTO `words` VALUES (16821, 'The workforce has been slashed by 50%.', 'v. 大量削减', '/slæʃ/', 'slash', 6);
INSERT INTO `words` VALUES (16822, 'There were several slates missing from the roof.', 'n. 板岩, 石板, 石片, 蓝色', '/sleit | sleɪt | slet/', 'slate', 6);
INSERT INTO `words` VALUES (16823, 'If your skin is dry, you have to slather on moisturizer to soften it.', 'v. 大量的用, 厚厚地涂', '/\'slɑ:ðə, \'slæðə | \'slæðə | \'slæðɚ/', 'slather', 6);
INSERT INTO `words` VALUES (16824, 'A woman regarded as slovenly OR untidy; a slattern.', 'n. 懒妇, 妓女', '/\'slætə:n, -tən | \'slæt(ə)n/', 'slattern', 6);
INSERT INTO `words` VALUES (16825, NULL, 'n. 奴隶贩子, 奴隶贩卖船, 诱骗女子为娼者, 唾液', '/\'sleivə | \'sleɪvə | \'slævɚ/', 'slaver', 6);
INSERT INTO `words` VALUES (16826, 'a slavish adherence to the rules', 'adj. 卑屈的； 效仿的， 无创造性的', '/\'sleɪvɪʃ | \'slevɪʃ/', 'slavish', 6);
INSERT INTO `words` VALUES (16827, '...the hill where St. George slew the dragon.', 'v. <书>杀, 杀死, 宰杀, 杀害, 宰杀, 杀死', '/slei | sleɪ | sle/', 'slay', 6);
INSERT INTO `words` VALUES (16828, NULL, 'n. 细丝, 乱丝', '/sliːv | sli:v/', 'sleave', 6);
INSERT INTO `words` VALUES (16829, NULL, 'n. 大锤, 猛烈的打击', '/\'sledʒ,hæmə | \'sledʒhæmə | \'slɛdʒhæmɚ/', 'sledgehammer', 6);
INSERT INTO `words` VALUES (16830, '...sleek black hair.', 'adj. 圆滑的', '/sli:k | sliːk | slik/', 'sleek', 6);
