INSERT INTO `words` VALUES (16847, 'I hate dogs that slobber everywhere.', 'v. 淌口水', '/\'slɒbə | \'slɑbɚ/', 'slobber', 6);
INSERT INTO `words` VALUES (16848, 'He’s been slogging round the streets delivering catalogues.', 'v. 艰难行进', '/slɔɡ | slɒg | slɑɡ/', 'slog', 6);
INSERT INTO `words` VALUES (16849, 'This means that the mainsail and head sail of a ketch are generally smaller than on a sloop, but the mizzen sail roughly makes up the difference.', 'n. 单桅帆船', '/slu:p | sluːp | slup/', 'sloop', 6);
