INSERT INTO `words` VALUES (16859, 'Those who an experiment studied 184 pass 60 years old is healthy but life sloven .', 'n. 懒散的人, 散漫的人', '/\'slʌvən | \'slʌv(ə)n | \'slʌvn/', 'sloven', 6);
