INSERT INTO `words` VALUES (17066, 'But the industry seems to be coming to terms with the fact that it is no longer as young and sprightly as it once was.', 'adj. 轻快的', '/\'spraitli | \'spraɪtlɪ | \'spraɪtli/', 'sprightly', 6);
INSERT INTO `words` VALUES (17067, NULL, 'n. 圈套', '/sprɪn(d)ʒ | sprindʒ/', 'springe', 6);
INSERT INTO `words` VALUES (17068, NULL, 'n. 洒水车, 洒水装置', '/\'spriŋklə | \'sprɪŋklə | \'sprɪŋklɚ/', 'sprinkler', 6);
INSERT INTO `words` VALUES (17069, 'Through faith he kept the passover, and the sprinkling of blood, lest he that destroyed the firstborn should touch them.', 'vbl. 洒水', '/\'spriŋkliŋ | \'sprɪŋklɪŋ/', 'sprinkling', 6);
INSERT INTO `words` VALUES (17070, 'Sergeant Horne sprinted to the car.', 'v. 疾跑美国著名的通讯公司', '/sprint | sprɪnt/', 'sprint', 6);
INSERT INTO `words` VALUES (17071, 'Move the pots outside when the seeds begin to sprout.', 'v. 萌芽', '/spraut | spraʊt/', 'sprout', 6);
INSERT INTO `words` VALUES (17072, 'Trees such as spruce, pine, and oak have been planted.', 'n. 云杉', '/spru:s | spruːs | sprʊs/', 'spruce', 6);
INSERT INTO `words` VALUES (17073, 'He’s still remarkably spry.', 'adj. 充满生气的, 活泼的, 敏捷的美国Spry在线服务公司', '/sprai | spraɪ/', 'spry', 6);
INSERT INTO `words` VALUES (17074, 'She had a lot of spunk.', 'n. 精神, 勇气, 胆量, 火星, 引火木柴', '/spʌŋk/', 'spunk', 6);
