INSERT INTO `words` VALUES (17078, 'A spurt of diesel came from one valve and none from the other.', 'n. 喷出， 迸发', '/spɜːrt | spɝt/', 'spurt', 6);
INSERT INTO `words` VALUES (17079, 'Mother is devoted to Dad although they squabble all the time.', 'v. 争论', '/\'skwɔbl | \'skwɒb(ə)l | \'skwɑbl/', 'squabble', 6);
INSERT INTO `words` VALUES (17080, 'How can anyone live in such squalid conditions?', 'adj. 肮脏的', '/\'skwɔlid, \'skɔ:- | \'skwɒlɪd | \'skɔlɪd/', 'squalid', 6);
INSERT INTO `words` VALUES (17081, 'The boat was hit by a squall north of the island.', 'n. 短暂、 突然且猛烈的风暴； 短暂的骚动', '/skwɔːl | skwɔl/', 'squall', 6);
INSERT INTO `words` VALUES (17082, 'We lived in squalor for a year and a half.', 'n. 肮脏, 悲惨, 贫穷', '/\'skwɔlə, \'skwɔ:- | \'skwɒlə | \'skwɔlɚ/', 'squalor', 6);
INSERT INTO `words` VALUES (17083, 'The home team squandered a number of chances in the first half.', 'v. 浪费', '/\'skwɔndə | \'skwɒndə | \'skwɑndɚ/', 'squander', 6);
INSERT INTO `words` VALUES (17084, NULL, 'v. 一致， 符合； 结清', '/skwer | skwɛr/', 'square', 6);
