INSERT INTO `words` VALUES (17086, 'We squatted beside the pool and watched the diver sink slowly down.', 'v. 蹲坐, 蹲伏', '/skwɔt | skwɒt | skwɑt/', 'squat', 6);
INSERT INTO `words` VALUES (17087, 'I bake them in the oven until they are crisp and then toss them in a wok with chilli and ginger as in my experience customers tend to be squeamish about anything that is soft and squidgy.', 'adj. 易受惊的； 易恶心的', '/\'skwiːmɪʃ | \'skwimɪʃ/', 'squeamish', 6);
INSERT INTO `words` VALUES (17088, 'She smiled as he squeezed her hand.', 'v. 压，挤; n. 压榨， 紧握', '/skwiːz | skwiz/', 'squeeze', 6);
INSERT INTO `words` VALUES (17089, 'Her creativity had been squelched.', 'v. 压制', '/skweltʃ | skwɛltʃ/', 'squelch', 6);
INSERT INTO `words` VALUES (17090, 'He also seems to be slightly blinded by the sun, causing him to squint.', 'v. 斜视', '/skwɪnt/', 'squint', 6);
INSERT INTO `words` VALUES (17091, 'Christine squirmed uncomfortably in her chair.', 'v. 蠕动', '/skwə:m | skwɜːm | skwɝm/', 'squirm', 6);
INSERT INTO `words` VALUES (17092, 'Norman cut open his pie and squirted tomato sauce into it.', 'v. 喷出， 溅进', '/skwɜːrt | skwɝt/', 'squirt', 6);
INSERT INTO `words` VALUES (17093, 'severe stab wounds', 'n. 刺, 刺伤的伤口, 一阵突然而强烈的感觉, 中伤, 伤痛', '/stæb/', 'stab', 6);
INSERT INTO `words` VALUES (17094, 'The patient’s condition has now stabilized.', 'v. 使稳定， 使坚固', '/\'steɪbəlaɪz | \'stebəlaɪz/', 'stabilize', 6);
INSERT INTO `words` VALUES (17095, 'His thinking, he said, has taken on a “staccato” quality, reflecting the way he quickly scans short passages of text from many sources online.', 'n. 断奏, 断唱', '/stə\'kɑ:təu | stə\'kɑːtəʊ | stə\'kɑto/', 'staccato', 6);
INSERT INTO `words` VALUES (17096, 'He managed to stagger home.', 'v. 摇晃, 蹒跚, 交错, 摇摇摆摆', '/\'stæɡə | \'stægə | \'stægɚ/', 'stagger', 6);
INSERT INTO `words` VALUES (17097, '...a staggering $900 million in short- and long-term debt.', 'adj. 蹒跚的, 摇晃的, 另人惊愕的', '/\'stæɡərɪŋ/', 'staggering', 6);
INSERT INTO `words` VALUES (17098, 'a government plan to revive the stagnant economy', 'adj. 停滞的, 迟钝的', '/\'stæɡnənt | \'stægnənt/', 'stagnant', 6);
INSERT INTO `words` VALUES (17099, 'Growth is expected to stagnate next year.', 'v. 停滞', '/\'stægneɪt | stæɡ\'net/', 'stagnate', 6);
INSERT INTO `words` VALUES (17100, 'Is there anything that could protect us from the dangers of stagnation or a double dip?', 'n. 停滞', '/stæg\'neɪʃn | stæg\'neʃən/', 'stagnation', 6);
INSERT INTO `words` VALUES (17101, 'a very stagy manner', 'adj. 做作的', '/\'steidʒi | \'steɪdʒɪ/', 'stagy', 6);
INSERT INTO `words` VALUES (17102, 'a staid old bachelor', 'adj. 沉静的', '/steɪd | sted/', 'staid', 6);
