INSERT INTO `words` VALUES (17115, 'He can be quite standoffish and rude, even to his friends.', 'adj. 冷淡的', '/stænd\'ɔfiʃ, -ɔ:f | stænd\'ɒfɪʃ/', 'standoffish', 6);
