INSERT INTO `words` VALUES (17119, '{\"GLOSS\":[\"people who love each other but cannot be together\"],\"COLLOINEXA\":[\"star-crossed lovers\"]}', 'adj. 时运不济的', '/\'stɑːrkrɔst | \'stɑ:krɔst, -krɔ:st/', 'star-crossed', 6);
INSERT INTO `words` VALUES (17120, '{\"COLLOINEXA\":[\"starchy foods\"]}', 'adj. 淀粉的, 拘泥的, 浆硬的, 含淀粉的', '/\'stɑ:tʃi | \'stɑːtʃɪ | \'stɑrtʃi/', 'starchy', 6);
INSERT INTO `words` VALUES (17121, 'In the cold dawn light, the castle looked stark and forbidding.', 'adj. 刻板的, 十足的, 赤裸的, 荒凉的', '/stɑ:k | stɑːk | stɑrk/', 'stark', 6);
INSERT INTO `words` VALUES (17122, 'Sorry, I didn’t mean to startle you.', 'v. 使吃惊', '/\'stɑːrtl | \'stɑrtl/', 'startle', 6);
INSERT INTO `words` VALUES (17123, 'We went for the bottle of whisky that we had stashed behind the bookcase.', 'v. 中断', '/stæʃ/', 'stash', 6);
