INSERT INTO `words` VALUES (17129, 'a fine collection of Greek statuary', 'n. 雕象', '/\'stætjuəri, -tʃu,eri | \'stætjʊərɪ; -tʃʊə- | \'stætʃuɛri/', 'statuary', 6);
INSERT INTO `words` VALUES (17130, 'The Prize consists of a statuette - “the Nkosi” - and 100,000 euros, which are to be awarded to a direct aid project in the spirit of the young winner’s efforts.', 'n. 小雕像', '/,stætju\'et, -tʃu- | stætjʊ\'et; -tʃʊ- | ,stʃʊjʊ\'ɛt/', 'statuette', 6);
