INSERT INTO `words` VALUES (17133, 'Protection for the consumer is laid down by statute (= established by law ) .', 'n. 法令, 条例', '/\'stætju:t, -tʃu:t | \'stætjuːt; -tʃuːt | \'stætʃut/', 'statute', 6);
