INSERT INTO `words` VALUES (17148, 'She knew no more shorthand than if she had been a graduate in stenography just let slip upon the world by a business college.', 'n. 速记, 速记法', '/stə\'nɔɡrəfi | stɪ\'nɒgrəfɪ | stə\'nɑɡrəfi/', 'stenography', 6);
INSERT INTO `words` VALUES (17149, 'He bellowed in a stentorian voice.', 'adj. 声音洪亮的', '/sten\'tɔ:riən | sten\'tɔːrɪən | stɛn\'tɔrɪən/', 'stentorian', 6);
INSERT INTO `words` VALUES (17150, 'Through stepwise refinement, I can drive the model to finer details, to a point where I can start generating concrete implementation artifacts from it.', 'adj. 楼梯式的, 逐步的', '/\'step,waiz | \'stepwaɪz | \'stɛpwaɪz/', 'stepwise', 6);
INSERT INTO `words` VALUES (17151, 'There\'s always been a stereotype about successful businessmen.', 'n. [印]铅版, 陈腔滥调, 老套', '/\'steriəutaip, \'stiə- | \'sterɪə(ʊ)taɪp; \'stɪərɪə(ʊ)- | \'stɛrɪətaɪp/', 'stereotype', 6);
INSERT INTO `words` VALUES (17152, 'The classrooms are sterile, with no artwork on the walls.', 'adj. 贫脊的, 不育的, 不结果的, 消过毒的, 毫无结果的', '/\'sterail, -rəl | \'steraɪl | \'stɛrəl/', 'sterile', 6);
