INSERT INTO `words` VALUES (17160, 'Regulations on children stifled creativity.', 'v. 使窒息, 抑制', '/\'staifl | \'staɪf(ə)l | \'staɪfl/', 'stifle', 6);
INSERT INTO `words` VALUES (17161, 'There is still a stigma attached to cancer.', 'n. 耻辱的标志， 污点', '/\'stɪgmə | \'stɪɡmə/', 'stigma', 6);
