INSERT INTO `words` VALUES (17176, 'Laws stipulate the maximum interest rate that banks can charge.', 'v. 规定, 保证', '/\'stipjuleit | \'stɪpjʊleɪt | \'stɪpjulet/', 'stipulate', 6);
