INSERT INTO `words` VALUES (17184, 'The company hasn\'t been able to shake off its image as stodgy and old-fashioned.', 'adj. 油腻的, 不易消化的, 乏味的, 暗淡的, 塞满的, 平凡的, 庸俗的, 笨重的', '/\'stɔdʒi | \'stɒdʒɪ | \'stɑdʒi/', 'stodgy', 6);
INSERT INTO `words` VALUES (17185, 'But, in most instances, people living in poverty respond to these societal ills with stoic resilience as they work to escape the degrading reality of their daily lives.', 'n. 高度自制者；坚忍克己之人', '/\'stoɪk | \'stouɪk/', 'stoic', 6);
INSERT INTO `words` VALUES (17186, 'Mostly produced in the last two years of his life, Cicero’s philosophy comprises a mixture of scepticism in the theory of knowledge and stoicism in ethics.', 'n. 斯多葛哲学，斯多葛学派', '/\'stəuisizəm/', 'stoicism', 6);
