INSERT INTO `words` VALUES (17188, 'He glanced furtively at the stolid faces of the two detectives.', 'adj. 不易激动的, 感觉迟钝的, 神经麻木的', '/\'stɔlid | \'stɒlɪd | \'stɑlɪd/', 'stolid', 6);
INSERT INTO `words` VALUES (17189, 'I was so hungry my stomach hurt.', 'n. 胃, 胃口, 胃部', '/\'stʌmək/', 'stomach', 6);
INSERT INTO `words` VALUES (17190, 'The administration is just stonewalling in an attempt to hide their political embarrassment.', 'v. 慎重的打球, 妨碍, 阻碍', '/,stəun\'wɔ:l | \'stəʊnwɔːl; stəʊn\'wɔːl | \'ston\'wɔl/', 'stonewall', 6);
