INSERT INTO `words` VALUES (17193, 'the storage of highly radioactive material', 'n. 仓库； 贮存', '/\'stɔːrɪdʒ | \'stɔrɪdʒ/', 'storage', 6);
INSERT INTO `words` VALUES (17194, 'The local archives service offers a storehouse of material.', 'n. 仓库', '/\'stɔ:haus | \'stɔːhaʊs | \'stɔrhaʊs/', 'storehouse', 6);
