INSERT INTO `words` VALUES (17197, 'Of course you also need others\' understanding, conciliation and support. But even at this moment, you\'re so silent, so peaceful, so stouthearted and so respectable!', 'adj. 刚毅的, 大胆的', '/\'staut\'hɑ:tid | \'staʊt\'hɑːtɪd | \'staʊt\'hɑrtɪd/', 'stouthearted', 6);
INSERT INTO `words` VALUES (17198, 'The crew discovered the stowaway about two days into their voyage.', 'n. 偷渡者, 匿身处', '/\'stəuə,wei | \'stəʊəweɪ | \'stoə\'we/', 'stowaway', 6);
