INSERT INTO `words` VALUES (17202, 'I couldn’t stand the strained atmosphere at dinner any more.', 'adj. 紧张的, 矫饰的, 做作的', '/streind | streɪnd | strend/', 'strained', 6);
INSERT INTO `words` VALUES (17203, 'the Bering Strait', 'adj. 艰难的, 苦恼的, 窘迫的', '/streit | streɪt | stret/', 'strait', 6);
INSERT INTO `words` VALUES (17204, NULL, 'v. 使穷困, 使为难, 限制', '/\'streitən | \'streɪt(ə)n/', 'straiten', 6);
