INSERT INTO `words` VALUES (17209, 'Trade discounts may be used as a competitive stratagem to secure customer loyalty.', 'n. 战略, 计谋', '/\'strætədʒəm/', 'stratagem', 6);
INSERT INTO `words` VALUES (17210, 'UN forces made a strategic withdrawal.', 'adj. 战略上的； 关键的， 重要的', '/strə\'tiːdʒɪk | strə\'tidʒɪk/', 'strategic', 6);
INSERT INTO `words` VALUES (17211, 'We currently use a large repository of data from our operational systems to help us stratify, or classify, members.', 'v. (使)成层', '/\'strætifai | \'strætɪfaɪ/', 'stratify', 6);
INSERT INTO `words` VALUES (17212, 'people of different social strata', 'n. [地] 地层, [生](组织的)层, 社会阶层', '/\'streitəm, \'stræ-, \'strɑ:- | \'strɑːtəm; \'streɪtəm | \'stretəm/', 'stratum', 6);
INSERT INTO `words` VALUES (17213, 'One man was hit by a stray bullet and taken to hospital.', 'v. 偏离，迷路; adj. 迷路的； 零落的', '/streɪ | stre/', 'stray', 6);
