INSERT INTO `words` VALUES (17228, 'stringent anti-noise regulations', 'adj. 严厉的, 迫切的, 银根紧的', '/\'strɪn(d)ʒ(ə)nt | \'strɪndʒənt/', 'stringent', 6);
