INSERT INTO `words` VALUES (17244, 'In her hurry, she stumbled and spilled the milk all over the floor.', 'v. 绊倒', '/\'stʌmbl/', 'stumble', 6);
INSERT INTO `words` VALUES (17245, 'He\'s stunned by today\'s resignation of his longtime ally.', 'v. 使晕倒, 使惊吓, 打晕', '/stʌn/', 'stun', 6);
