INSERT INTO `words` VALUES (17260, 'The clay minerals in 65 surface sediment samples from the Changjiang River subaqueous delta were analyzed by using X ray diffraction (XRD) analysis technique.', 'adj. 水中的, 水下用的', '/,sʌb\'eikwiəs, -\'ækw- | sʌb\'eɪkwɪəs | ,sʌb\'ækwɪəs/', 'subaqueous', 6);
