INSERT INTO `words` VALUES (17263, 'Police managed to subdue the angry crowd.', 'v. 征服', '/səb\'dju: | səb\'djuː | səb\'du/', 'subdue', 6);
INSERT INTO `words` VALUES (17264, 'Richard seems very subdued tonight.', 'adj. 柔和的， 缓和的； 温和的', '/səb\'duːd | səb\'dud/', 'subdued', 6);
