INSERT INTO `words` VALUES (17266, 'As a critic, he is far too subjective.', 'adj. 主观的， 想象的', '/səb\'dʒektɪv | səb\'dʒɛktɪv/', 'subjective', 6);
INSERT INTO `words` VALUES (17267, 'The native population was subjugated and exploited.', 'v. 使屈服, 征服, 使服从, 克制, 抑制', '/\'sʌbdʒəɡeit, -dʒu- | \'sʌbdʒʊgeɪt | \'sʌbdʒuɡet/', 'subjugate', 6);
