INSERT INTO `words` VALUES (17271, 'The tunnel entrance was submerged by rising sea water.', 'v. 浸没, 淹没, 掩没', '/səb\'mə:dʒ | səb\'mɜːdʒ | səb\'mɝdʒ/', 'submerge', 6);
