INSERT INTO `words` VALUES (17276, 'a subordinate officer', 'adj. 次要的, 从属的, 下级的', '/sə\'bɔ:dinət, -neit, sə\'bɔ:dineit | sə\'bɔːdɪnət | səˈbɔːdɪnɪt (for n. &adj.) ; səˈbɔːdɪˌnet (for v.)/', 'subordinate', 6);
INSERT INTO `words` VALUES (17277, 'an attempt to suborn a witness', 'v. 唆使', '/sʌ\'bɔ:n | sə\'bɔːn | sə\'bɔrn/', 'suborn', 6);
INSERT INTO `words` VALUES (17278, 'He has been served with a subpoena to answer the charges in court.', 'n. 传票', '/səb\'pi:nə | sə\'piːnə | sə\'pinə/', 'subpoena', 6);
