INSERT INTO `words` VALUES (17282, 'Her willingness to be subservient to her children isolated her.', 'adj. 屈从的, 有帮助的, 有用的, 奉承的', '/səb:sə:viənt | səb\'sɜːvɪənt/', 'subservient', 6);
INSERT INTO `words` VALUES (17283, 'After the heavy rains, part of the road subsided.', 'v. 下沉, 沉淀, 平息, 减退, 衰减', '/səb\'said | səb\'saɪd/', 'subside', 6);
INSERT INTO `words` VALUES (17284, 'The marketing department has always played a subsidiary role to the sales department.', 'adj. 辅助的, 补充的', '/səb\'sidiəri | səb\'sɪdɪərɪ | səb\'sɪdɪɛri/', 'subsidiary', 6);
INSERT INTO `words` VALUES (17285, 'Farming is heavily subsidized (= subsidized a lot ) by the government.', 'v. 津贴， 资助', '/\'sʌbsɪdaɪz | \'sʌbsə\'daɪz/', 'subsidize', 6);
INSERT INTO `words` VALUES (17286, 'European farmers are planning a massive demonstration against farm subsidy cuts.', 'n. 补助金, 津贴', '/\'sʌbsidi | \'sʌbsɪdɪ | \'sʌbsədi/', 'subsidy', 6);
INSERT INTO `words` VALUES (17287, 'The prisoners subsisted on one mug of the worst quality porridge three times a day.', 'v. 生存下去； 继续存在； 维持生活', '/səb\'sɪst/', 'subsist', 6);
INSERT INTO `words` VALUES (17288, 'Many of the families are forced to live at the subsistence level.', 'n. 生存， 生计； 存在', '/səb\'sɪstəns/', 'subsistence', 6);
INSERT INTO `words` VALUES (17289, 'The leaves were covered with a strange sticky substance.', 'n. 主旨， 实质； 物质', '/\'sʌbstəns/', 'substance', 6);
INSERT INTO `words` VALUES (17290, 'a substantial piece of furniture', 'adj. 坚固的， 结实的； 实质的', '/səb\'stænʃl | səbˈstænʃəl/', 'substantial', 6);
INSERT INTO `words` VALUES (17291, 'Katzen offered little evidence to substantiate his claims .', 'v. 使实体化, 证实', '/səb\'stænʃieit | səb\'stænʃɪeɪt | səb\'stænʃɪet/', 'substantiate', 6);
INSERT INTO `words` VALUES (17292, 'They plan to meet again in Rome very soon to begin substantive negotiations.', 'adj. 独立存在的, 真实的, 有实质的, 大量的, 巨额的', '/\'sʌbstəntiv | \'sʌbst(ə)ntɪv | səb\'stæntɪv/', 'substantive', 6);
INSERT INTO `words` VALUES (17293, 'Germany brought on a substitute at half time.', 'n. 代用品, 代替者, 替代品', '/\'sʌbstitju:t, -tu:t | \'sʌbstɪtjuːt | \'sʌbstɪtut/', 'substitute', 6);
INSERT INTO `words` VALUES (17294, 'a substratum of rock', 'n. 底土, 下层土壤地基', '/,sʌb\'streitəm, -\'strɑ:- | sʌb\'strɑːtəm; -\'streɪtəm | \'sʌbstretəm/', 'substratum', 6);
INSERT INTO `words` VALUES (17295, 'After that the two alliances might be subsumed into a new European security system.', 'v. 包容, 包含', '/səb\'sju:m | səb\'sjuːm | səb\'sʊm/', 'subsume', 6);
INSERT INTO `words` VALUES (17296, 'Most people can see right through that type of subterfuge.', 'n. 托词', '/\'sʌbtəfju:dʒ | \'sʌbtəfjuːdʒ | \'sʌbtɚfjudʒ/', 'subterfuge', 6);
INSERT INTO `words` VALUES (17297, 'subterranean passage', 'adj. 地下的', '/,sʌbtə\'reiniən | ,sʌbtə\'reɪnɪən | ,sʌbtə\'renɪən/', 'subterranean', 6);
INSERT INTO `words` VALUES (17298, 'The pictures are similar, but there are subtle differences between them.', 'adj. 微妙的， 精巧的', '/\'sʌtl/', 'subtle', 6);
INSERT INTO `words` VALUES (17299, 'The play lacks subtlety.', 'n. 稀薄, 微妙, 精明', '/\'sʌbtlti | \'sʌt(ə)ltɪ | \'sʌtlti/', 'subtlety', 6);
INSERT INTO `words` VALUES (17300, 'The impressive dissertation has subtly revealed a thought-provoking social phenomenon which is prevalent all over the world, which is __.', 'adv. 敏锐地， 巧妙地', '/\'sʌtli/', 'subtly', 6);
INSERT INTO `words` VALUES (17301, 'Mandy subtracted the date of birth from the date of death.', 'v. 减去， 减掉', '/səb\'trækt/', 'subtract', 6);
INSERT INTO `words` VALUES (17302, 'Magenta one of the subtractive primary colours. it is used in four-colour process printing . also referred to as process red.', 'adj. 减法的； 负的', '/səb\'træktɪv/', 'subtractive', 6);
INSERT INTO `words` VALUES (17303, 'The standard for medical subvention is to be set by people\'s government of province, autonomous region or municipality directly under the Central Government.', 'n. 补助金', '/səb\'venʃən | səb\'venʃ(ə)n | səb\'vɛnʃən/', 'subvention', 6);
INSERT INTO `words` VALUES (17304, 'He was engaged in subversive activities .', 'adj. 颠覆性的, 破坏性的', '/səb\'və:siv, sʌb- | səb\'vɜːsɪv | sʌb\'vɝsɪv/', 'subversive', 6);
INSERT INTO `words` VALUES (17305, 'an attempt to subvert the democratic process', 'v. 推翻, 暗中破坏, 搅乱', '/səb\'və:t, sʌb- | səb\'vɜːt | sʌb\'vɝt/', 'subvert', 6);
INSERT INTO `words` VALUES (17306, NULL, 'n. 代用品, 代理者, 代用药', '/,sʌksi\'deiniəm | ,sʌksɪ\'deɪnɪəm | ,sʌksɪ\'deniəm/', 'succedaneum', 6);
INSERT INTO `words` VALUES (17307, NULL, 'adv. 接连地， 继续地', '/sək\'sesɪvli | sək\'sɛsɪvli/', 'successively', 6);
INSERT INTO `words` VALUES (17308, 'The book gives an admirably succinct account of the technology and its history.', 'adj. 简洁的, 紧身的, 压缩在小范围内的', '/sək\'siŋkt, sə\'s- | sək\'sɪŋ(k)t | sək\'sɪŋkt/', 'succinct', 6);
INSERT INTO `words` VALUES (17309, 'Terseness or succinctness of style or expression.', 'n. 简明， 简洁', '/sək\'siŋktnis | sək\'sɪŋktnəs/', 'succinctness', 6);
INSERT INTO `words` VALUES (17310, 'These refugees are very grateful to the government\'s succor.', 'n. 救援, 援助者, 救援人员', '/\'sʌkə | \'sʌkɚ/', 'succor', 6);
INSERT INTO `words` VALUES (17311, 'The succubus is the female counterpart of the incubus. She is a demon seductress who preys on sleeping men, draining them of their “vitality.”', 'n. 女妖, 妓女, 魔鬼', '/\'sʌkjubəs | \'sʌkjʊbəs/', 'succubus', 6);
INSERT INTO `words` VALUES (17312, 'a succulent steak', 'adj. 多汁的, 多水分的, 多汁性的', '/\'sʌkjulənt | \'sʌkjʊl(ə)nt | \'sʌkjələnt/', 'succulent', 6);
INSERT INTO `words` VALUES (17313, 'Don\'t succumb to the temptation to have just one cigarette.', 'v. 屈服, 屈从, 死', '/sə\'kʌm/', 'succumb', 6);
INSERT INTO `words` VALUES (17314, 'a sheep suckling her lamb', 'v. 给…哺乳； 吮吸', '/\'sʌkl/', 'suckle', 6);
INSERT INTO `words` VALUES (17315, 'For half an hour, up and down the streets, around corners and into alleyways, Karen Lodrick, frightened but determined, pursued the woman with the suede coat.', 'n. 小山羊皮', '/sweid | sweɪd | swed/', 'suede', 6);
INSERT INTO `words` VALUES (17316, 'A light lunch will suffice .', 'v. 足够, 有能力', '/sə\'fais | sə\'faɪs/', 'suffice', 6);
INSERT INTO `words` VALUES (17317, 'We can only prosecute if there is sufficient evidence.', 'adj. 充分的, 足够的', '/sə\'fiʃənt | sə\'fɪʃ(ə)nt | səˈfɪʃənt/', 'sufficient', 6);
INSERT INTO `words` VALUES (17318, 'The animal seizes its prey by the throat and suffocates it to death.', 'v. 使窒息, 噎住, 闷熄', '/\'sʌfəkeit | \'sʌfəkeɪt | \'sʌfəket/', 'suffocate', 6);
INSERT INTO `words` VALUES (17319, '...the women\'s suffrage movement.', 'n. 投票, 选举权, 参政权, [宗]代祷', '/\'sʌfridʒ | \'sʌfrɪdʒ/', 'suffrage', 6);
INSERT INTO `words` VALUES (17320, NULL, 'n. 参政权扩大论者； 妇女政权论者', '/\'sʌfrədʒɪst/', 'suffragist', 6);
INSERT INTO `words` VALUES (17321, 'The light of the setting sun suffused the clouds.', 'v. 充满', '/sə\'fju:z | sə\'fjuːz | sə\'fjuz/', 'suffuse', 6);
INSERT INTO `words` VALUES (17322, '...highly suggestible and compliant individuals.', 'adj. 耳根软的, 可建议的, 容易受暗示影响的', '/səɡ\'dʒestəbl | sə\'dʒestɪb(ə)l | sə\'dʒɛstəbl/', 'suggestible', 6);
INSERT INTO `words` VALUES (17323, 'High spiking fever with chills is suggestive of a complicating pylephlebitis.', 'adj. 暗示的', '/sə\'dʒestɪv | sə\'dʒɛstɪv/', 'suggestive', 6);
INSERT INTO `words` VALUES (17324, 'My mother had a suitor who adored her.', 'n. 起诉者, 求婚者, 请愿者', '/\'sju:tə | \'suːtə | \'sʊtɚ/', 'suitor', 6);
INSERT INTO `words` VALUES (17325, 'a sulky child', 'adj. 生气的, 阴沉的', '/\'sʌlki | \'sʌlkɪ/', 'sulky', 6);
INSERT INTO `words` VALUES (17326, 'Bill sat in sullen silence and refused to eat his lunch.', 'adj. 愠怒的, 沉沉不乐的, (天气等)阴沉的', '/\'sʌlən/', 'sullen', 6);
INSERT INTO `words` VALUES (17327, 'a scandal that sullied his reputation', 'v. 玷污', '/\'sʌli | \'sʌlɪ/', 'sully', 6);
INSERT INTO `words` VALUES (17328, 'a hot and sultry day', 'adj. 闷热的, 粗暴的, 激烈的, 放荡的', '/sʌltri | \'sʌltrɪ | \'sʌltri/', 'sultry', 6);
INSERT INTO `words` VALUES (17329, 'He was summarily dismissed.', 'adv. 概要地, 概略地, 立刻, 草率地', '/\'sʌmərəli, sə\'mεərəli/', 'summarily', 6);
INSERT INTO `words` VALUES (17330, 'a summary execution', 'adj. 摘要的， 简略的; n. 摘要，概要', '/\'sʌməri/', 'summary', 6);
INSERT INTO `words` VALUES (17331, 'Her introduction is a model of fairness, a lively summation of Irish history.', 'n. 总结， 概要； 总数， 合计', '/sʌ\'meɪʃn | sʌ\'meʃən/', 'summation', 6);
INSERT INTO `words` VALUES (17332, 'Robert summoned the waiter for the bill.', 'v. 传唤； 召集', '/\'sʌmən/', 'summon', 6);
INSERT INTO `words` VALUES (17333, 'a sumptuous feast', 'adj. 奢侈的, 华丽的', '/\'sʌmptjuəs, -tʃu- | \'sʌm(p)tjʊəs | \'sʌmptʃuəs/', 'sumptuous', 6);
INSERT INTO `words` VALUES (17334, 'Nine younger sister mother see big sister to report, and hot plates sun-bronzed the four xi.', 'adj. 被太阳晒成古铜色的', '/\'sʌnbrɑːnzd/', 'sun-bronzed', 6);
INSERT INTO `words` VALUES (17335, 'The city is being sundered by racial tension.', 'v. 切开, 分离', '/\'sʌndə | \'sʌndɚ/', 'sunder', 6);
INSERT INTO `words` VALUES (17336, 'He makes films about animals, plants and sundry other subjects.', 'adj. 各式各样的', '/\'sʌndri | \'sʌndrɪ/', 'sundry', 6);
INSERT INTO `words` VALUES (17337, 'a sunlit garden', 'adj. 阳光照射的', '/\'sʌnlɪt/', 'sunlit', 6);
INSERT INTO `words` VALUES (17338, NULL, 'vi. 过剩, 有余', '/suːp(ə)rə\'baʊnd; sjuː- | ,sju:pərə\'baund/', 'superabound', 6);
INSERT INTO `words` VALUES (17339, NULL, 'v. 使退休领养老金', '/ˌsuːpər\'ænjueɪt | ,sju:pər\'ænjueit/', 'superannuate', 6);
INSERT INTO `words` VALUES (17340, 'superannuated sportsmen', 'adj. 退休的, 过时的', '/,sju:pər\'ænjueitid | suːpə\'rænjʊeɪtɪd; \'sjuː-/', 'superannuated', 6);
INSERT INTO `words` VALUES (17341, 'The food was superb.', 'adj. 庄重的, 堂堂的, 华丽的, 极好的', '/sju\'pə:b, sə- | suː\'pɜːb; sjuː- | /suːˈpɜːrb//', 'superb', 6);
INSERT INTO `words` VALUES (17342, 'supercilious wine waiters', 'adj. 自大的, 傲慢的, 目空一切的', '/,sju:pə\'siliəs | suːpə\'sɪlɪəs; sjuː- | ,supɚ\'sɪlɪəs/', 'supercilious', 6);
INSERT INTO `words` VALUES (17343, NULL, 'adj. 职责以外的； 多余的', '/ˌsjʊːprə\'rɔgətɔːrɪ | ,sju:prə\'rɔɡətɔ:ri, -təri/', 'supererogatory', 6);
INSERT INTO `words` VALUES (17344, 'They only have the most superficial understanding of prison life.', 'adj. 表面的, 肤浅的, 浅薄的', '/,suːpə\'fɪʃ(ə)l; ,sjuː- | ,supɚ\'fɪʃl/', 'superficial', 6);
INSERT INTO `words` VALUES (17345, 'Narcissists aren\'t just attractive to themselves. They are, at least superficially, attractive to other people.', 'adv. 表面上地', '/ˌsuːpər\'fɪʃəli | \'sʊpɚ\'fɪʃəli/', 'superficially', 6);
INSERT INTO `words` VALUES (17346, 'The city has a superfluity of five-star hotels.', 'n. 过剩', '/ˌsuːpər\'fluːəti | ,sʊpɚ\'flʊəti/', 'superfluity', 6);
INSERT INTO `words` VALUES (17347, 'a modern building with no superfluous decoration', 'adj. 多余的, 过剩的, 过量的', '/sju\'pə:fluəs | suː\'pɜːflʊəs; sjuː- | sʊ\'pɝflʊəs/', 'superfluous', 6);
INSERT INTO `words` VALUES (17348, NULL, '[罕]倾注, 浇盖', '/,sjuːpə\'fjuːz | ,sju:pə\'fju:z/', 'superfuse', 6);
INSERT INTO `words` VALUES (17349, 'The image of a seemingly tiny dancer was superimposed on the image of the table.', 'v. 添加, 双重', '/,sju:pərim\'pəuz | ,suːp(ə)rɪm\'pəʊz; ,sjuː- | ,supərɪm\'poz/', 'superimpose', 6);
INSERT INTO `words` VALUES (17350, 'Meese was to superintend the administration\'s entire domestic policy.', 'v. 主管, 指挥, 管理, 监督', '/,sju:pərin\'tend | suːp(ə)rɪn\'tend; sjuː- | ,supərɪn\'tɛnd/', 'superintend', 6);
INSERT INTO `words` VALUES (17351, 'Janet always spoke with an air of superiority.', 'n. 优越', '/suːˌpɪri\'ɔːrəti | su,pɪrɪ\'ɔrəti/', 'superiority', 6);
INSERT INTO `words` VALUES (17352, 'a superlative performance', 'adj. 最高的', '/sju:\'pə:lətiv, sə- | suːˈpəːlətɪv/', 'superlative', 6);
INSERT INTO `words` VALUES (17353, 'The soul, or the principle that we call the soul, is the supernal criticism of the deeds done in the body, which goes perpetually on in the waking mind.', 'adj. 天上的, 神的, 高的, 超自然的', '/sju:\'pə:nəl | suː\'pɜːn(ə)l; sjuː- | sʊ\'pɝnl/', 'supernal', 6);
INSERT INTO `words` VALUES (17354, 'At least one supernova occurs per decade in our galaxy.', 'n. 超新星', '/ˌsuːpər\'nouvə | ,supɚ\'novə/', 'supernova', 6);
INSERT INTO `words` VALUES (17355, 'Their map has since been superseded by photographic atlases.', 'v. 淘汰； 取代', '/ˌsuːpər\'siːd | ,supɚ\'sid/', 'supersede', 6);
INSERT INTO `words` VALUES (17356, 'the old superstition that walking under a ladder is unlucky', 'n. 迷信', '/,sju:pə\'stiʃən | ,suːpə\'stɪʃ(ə)n; ,sjuː- | ,supɚ\'stɪʃən/', 'superstition', 6);
INSERT INTO `words` VALUES (17357, 'the whole superstructure of capitalism', 'n. 上层建筑； 上层构造', '/\'suːpərstrʌktʃər | \'supɚstrʌktʃɚ/', 'superstructure', 6);
INSERT INTO `words` VALUES (17358, 'Griffiths closely supervised the research.', 'v. 监督， 管理', '/\'suːpərvaɪz | \'sʊpɚ\'vaɪz/', 'supervise', 6);
INSERT INTO `words` VALUES (17359, 'in a supine position', 'adj. 仰卧的, 掌心向上的, 懒散的, 向后靠的', '/sju:\'pain, \'sju:pain | \'s(j)uːpaɪn | \'supaɪn/', 'supine', 6);
INSERT INTO `words` VALUES (17360, 'Barker was soon supplanted as party leader.', 'v. 排挤掉, 代替', '/sə\'plɑ:nt, -\'plænt | sə\'plɑːnt | sə\'plænt/', 'supplant', 6);
INSERT INTO `words` VALUES (17361, 'She exercises every day to keep herself supple.', 'adj. 柔软的, 逢迎的, 顺从的', '/\'sʌpl | \'sʌp(ə)l/', 'supple', 6);
INSERT INTO `words` VALUES (17362, 'vitamins and other dietary supplements', 'n. 补遗, 补充, 附录, 增刊', '/英[\'sʌplɪm(ə)nt] 美[\'sʌplɪmənt] | \'sʌplɪm(ə)nt | \'sʌplɪmənt/', 'supplement', 6);
INSERT INTO `words` VALUES (17363, 'supplementary information', 'adj. 增补的， 补充的', '/ˌsʌplɪ\'mentri | ,sʌplɪ\'mɛntri/', 'supplementary', 6);
INSERT INTO `words` VALUES (17364, NULL, 'adj. 恳求的，哀求的; n. 恳求者， 哀求者', '/\'sʌpliənt/', 'suppliant', 6);
INSERT INTO `words` VALUES (17365, 'He flung himself down in the flat submissive posture of a mere supplicant.', 'n. (=suppliant)恳求者, 恳请者', '/\'sʌplikənt | \'sʌplɪkənt/', 'supplicant', 6);
INSERT INTO `words` VALUES (17366, 'A man can scarce allege his own merits with modesty, much less extol them; a man cannot sometimes brook to supplicate or beg; and a number of the like.', 'v. 恳求, 哀求, 恳请, 祈祷', '/\'sʌplikeit | \'sʌplɪkeɪt/', 'supplicate', 6);
INSERT INTO `words` VALUES (17367, 'My family were very supportive throughout the divorce.', 'adj. 支持的', '/sə\'pɔːrtɪv | sə\'pɔrtɪv/', 'supportive', 6);
INSERT INTO `words` VALUES (17368, 'His version of events is pure supposition .', 'n. 假定, 想象, 推测, 推想', '/,sʌpə\'ziʃən | ,sʌpə\'zɪʃ(ə)n | ,sʌpə\'zɪʃən/', 'supposition', 6);
INSERT INTO `words` VALUES (17369, 'The uprising was ruthlessly suppressed.', 'v. 镇压； 抑制', '/sə\'pres | sə\'prɛs/', 'suppress', 6);
INSERT INTO `words` VALUES (17370, 'Left untreated, the abscesses suppurate ; the pus cannot escape from the body, and the malady spreads throughout the organism.', 'v. [医]生脓, 化脓, 流脓', '/\'sʌpjuəreit | \'sʌpjʊreɪt | \'sʌpjə\'ret/', 'suppurate', 6);
INSERT INTO `words` VALUES (17371, 'the Supreme Allied Commander in Europe', 'adj. 最高的； 极度的', '/suː\'priːm | suˈprim/', 'supreme', 6);
INSERT INTO `words` VALUES (17372, NULL, 'n. 停止', '/sə:\'si:s | sɜː\'siːs/', 'surcease', 6);
INSERT INTO `words` VALUES (17373, 'Children soon learn that bad behaviour is a surefire way of getting attention.', 'adj. 准不会有错的, 一定能达到目的的', '/\'ʃuə\'faiə, \'ʃɔ:-/', 'surefire', 6);
INSERT INTO `words` VALUES (17374, 'Rationing had put an end to a surfeit of biscuits long ago.', 'n. 过食, 过度, 恶心', '/\'sə:fit | \'sɜːfɪt | \'sɝfɪt/', 'surfeit', 6);
INSERT INTO `words` VALUES (17375, 'a device that protects your computer against electrical surges', 'n. 巨涌, 汹涌, 澎湃', '/sɜːdʒ | sɝdʒ/', 'surge', 6);
INSERT INTO `words` VALUES (17376, 'He became surly and rude toward me.', 'adj. 粗暴的, 乖戾的, 阴沉的, 无礼的, 板面孔的', '/\'sə:li | \'sɜːlɪ/', 'surly', 6);
INSERT INTO `words` VALUES (17377, 'There\'s so little to go on, we can only surmise what happened.', 'v. 猜测', '/\'sə:maiz, sə:\'maiz | sə\'maɪz | sɝ\'maɪz/', 'surmise', 6);
INSERT INTO `words` VALUES (17378, 'He has had to surmount immense physical disabilities.', 'v. 克服， 战胜； 登上', '/sər\'maunt | sɚ\'maʊnt/', 'surmount', 6);
INSERT INTO `words` VALUES (17379, 'He had surpassed all our expectations .', 'v. 超过', '/sər\'pæs | sə\'pæs/', 'surpass', 6);
INSERT INTO `words` VALUES (17380, 'Any surplus can be trimmed away.', 'n. 剩余, 过剩, [会计]盈余', '/\'sə:plʌs, -pləs | \'sɜːpləs | \'sɝpləs/', 'surplus', 6);
INSERT INTO `words` VALUES (17381, 'Germany surrendered on May 7th, 1945.', 'v. 投降； 放弃； 归还', '/sə\'rendər | sə\'rɛndɚ/', 'surrender', 6);
INSERT INTO `words` VALUES (17382, 'Rory tried to sneak a surreptitious glance at Adam’s wristwatch.', 'adj. 暗中的, 秘密的, 偷偷摸摸的', '/,sʌrəp\'tiʃəs, ,sə:- | ,sʌrəp\'tɪʃəs | ,sɝrəp\'tɪʃəs/', 'surreptitious', 6);
INSERT INTO `words` VALUES (17383, 'Arms control should not be made into a surrogate for peace.', 'n. 代理, 代用品, 代理人', '/\'sʌrəɡeit, -ɡit, \'sə:- | \'sʌrəgət | ˈsərəgɪt; ˈsərəˌget; (for v.,) ˈsərəˌget/', 'surrogate', 6);
INSERT INTO `words` VALUES (17384, 'electronic surveillance equipment', 'n. 监视， 盯梢', '/sɜːr\'veɪləns | sɝ\'veləns/', 'surveillance', 6);
INSERT INTO `words` VALUES (17385, 'Only 12 of the 140 passengers survived.', 'v. 幸存', '/sər\'vaɪv | sɚ\'vaɪv/', 'survive', 6);
INSERT INTO `words` VALUES (17386, 'Don’t worry about Kurt; he’s a survivor.', 'n. 幸存者', '/sər\'vaɪvər | sɚ\'vaɪvɚ/', 'survivor', 6);
INSERT INTO `words` VALUES (17387, 'A lot of TV advertising is aimed at susceptible young children.', 'adj. 易受影响的， 敏感的', '/sə\'septəbl | sə\'sɛptəbl/', 'susceptible', 6);
INSERT INTO `words` VALUES (17388, 'The sensor system using this stabilization method is susceptive to the disturbance and has a high cost.', 'adj. 感受性强的, 敏感的, 有接受力的', '/sə\'septɪv | sə\'sɛptɪv/', 'susceptive', 6);
INSERT INTO `words` VALUES (17389, 'She strongly suspected he was lying to her.', 'v. 怀疑; adj. 可疑的; n. 嫌疑犯', '/sə\'spekt | sʌspɛkt; (for v.) səˈspɛkt/', 'suspect', 6);
INSERT INTO `words` VALUES (17390, 'Sales of the drug will be suspended until more tests are completed.', 'v. 暂停， 中止； 吊， 悬', '/sə\'spend | sə\'spɛnd/', 'suspend', 6);
INSERT INTO `words` VALUES (17391, 'Come on then, tell me what happened; the suspense is killing me (= I feel very excited or anxious because I do not know what will happen next ) .', 'n. 焦虑, 悬念, 悬而不决', '/sə\'spens | sə\'spɛns/', 'suspense', 6);
INSERT INTO `words` VALUES (17392, 'He received a six-month suspension for unprofessional behaviour.', 'n. 暂停； 悬浮', '/sə\'spenʃn | sə\'spɛnʃən/', 'suspension', 6);
INSERT INTO `words` VALUES (17393, 'I can’t say for definite who did it, but I certainly have my suspicions .', 'n. 怀疑， 嫌疑', '/sə\'spɪʃn | sə\'spɪʃən/', 'suspicion', 6);
INSERT INTO `words` VALUES (17394, 'His reluctance to answer my questions made me suspicious .', 'adj. 怀疑的', '/sə\'spɪʃəs/', 'suspicious', 6);
INSERT INTO `words` VALUES (17395, 'She found it difficult to sustain the children’s interest.', 'v. 支撑, 撑住, 维持, 持续', '/sə\'stein | sə\'steɪn | sə\'sten/', 'sustain', 6);
INSERT INTO `words` VALUES (17396, 'a period of sustained economic development', 'adj. 持续不变的, 相同的', '/sə\'steind | sə\'steɪnd | sə\'stend/', 'sustained', 6);
INSERT INTO `words` VALUES (17397, 'Without sustenance, the animals will soon die.', 'n. 食物, 生计, (受)支持', '/\'sʌstenəns | \'sʌst(ə)nəns; -tɪn- | \'sʌstənəns/', 'sustenance', 6);
INSERT INTO `words` VALUES (17398, 'It\'s suture.', 'n. [医]缝合, 缝合处, 缝合用的线', '/\'su:tʃə | \'suːtʃə | \'sutʃɚ/', 'suture', 6);
INSERT INTO `words` VALUES (17399, 'She was slim, svelte, and sophisticated.', 'adj. 苗条的, 体态娇美的', '/svelt, sfelt | svelt | sfɛlt/', 'svelte', 6);
INSERT INTO `words` VALUES (17400, 'He walked with something of a swagger.', 'n. 狂妄自大者, 大摇大摆, 吹牛', '/\'swæɡə | \'swægə | \'swæɡɚ/', 'swagger', 6);
INSERT INTO `words` VALUES (17401, 'He swallowed the last of his coffee and asked for the bill.', 'v. 吞下， 咽下； 忍受', '/\'swɑːlou | \'swɑlo/', 'swallow', 6);
INSERT INTO `words` VALUES (17402, 'Huge waves swamped the vessel.', 'v. 使陷入困境； 淹没; n. 沼泽', '/swɑːmp | swɑmp/', 'swamp', 6);
INSERT INTO `words` VALUES (17403, 'Malaria is still rampant in some swampy regions.', 'adj. 沼泽的， 湿地的', '/swɑːmpɪ | \'swɔmpi/', 'swampy', 6);
INSERT INTO `words` VALUES (17404, 'I wish you’d stop swanking!', 'adj. 打扮漂亮的', '/swæŋk/', 'swank', 6);
INSERT INTO `words` VALUES (17405, 'Do you want to swap umbrellas?', 'v. 交换', '/swɔp, swɔ:p | swɒp | swɑp/', 'swap', 6);
INSERT INTO `words` VALUES (17406, '...a swarm of locusts.', 'n. 蜂群, 一大群', '/swɔ:m | swɔːm | swɔrm/', 'swarm', 6);
INSERT INTO `words` VALUES (17407, NULL, 'adj. 黑黝黝的,有毒的,有害的,恶性的', '/swɔ:t | swɔːt/', 'swart', 6);
INSERT INTO `words` VALUES (17408, 'a small, swarthy man', 'adj. 黑黝黝的, 浅黑的', '/\'swɔ:ði, -θi | \'swɔːðɪ | \'swɔrði/', 'swarthy', 6);
INSERT INTO `words` VALUES (17409, 'women swathed in expensive furs', 'v. 包， 绑， 裹', '/sweɪð | sweið, swɔð/', 'swathe', 6);
INSERT INTO `words` VALUES (17410, 'The trees swayed gently in the breeze.', 'v. 摇动，摇摆；影响; n. 摇摆', '/sweɪ | swe/', 'sway', 6);
INSERT INTO `words` VALUES (17411, 'Don’t swear in front of the children.', 'v. 诅咒', '/swer | swɛr/', 'swear', 6);
INSERT INTO `words` VALUES (17412, 'Thunderstorms swept the country.', 'v. 席卷， 扫过', '/swiːp | swip/', 'sweep', 6);
INSERT INTO `words` VALUES (17413, 'The river was swollen with melted snow.', 'v. (使)膨胀, 增大', '/swel | swɛl/', 'swell', 6);
INSERT INTO `words` VALUES (17414, '...the sweltering heat of the St. Petersburg summer.', 'adj. 闷热的, 中暑的, 酷热的', '/\'sweltəriŋ | \'swelt(ə)rɪŋ | \'swɛltərɪŋ/', 'sweltering', 6);
INSERT INTO `words` VALUES (17415, 'Drivers coming in the opposite direction swerved to avoid the bodies.', 'v. 突然转向', '/swə:v | swɜːv | swɝv/', 'swerve', 6);
INSERT INTO `words` VALUES (17416, 'My letter received a swift reply.', 'adj. 迅速的； 敏捷的', '/swɪft/', 'swift', 6);
INSERT INTO `words` VALUES (17417, 'Brian took a swig of his beer.', 'n. 痛饮, 大喝(尤指从瓶口喝的)', '/swiɡ | swɪg | swɪɡ/', 'swig', 6);
INSERT INTO `words` VALUES (17418, 'He does nothing but swill beer all day.', 'v. 涮, 冲洗, 痛饮, 倒出', '/swil | swɪl/', 'swill', 6);
INSERT INTO `words` VALUES (17419, 'A businessman swindled investors out of millions of dollars.', 'v. 诈骗', '/\'swindl | \'swɪnd(ə)l | swɪndl/', 'swindle', 6);
INSERT INTO `words` VALUES (17420, 'Leave her alone, you filthy swine!', 'n. 猪, 卑贱的人', '/swain | swaɪn/', 'swine', 6);
INSERT INTO `words` VALUES (17421, 'Let your arms swing as you walk.', 'v. 摇摆；旋转; n. 秋千', '/swɪŋ/', 'swing', 6);
INSERT INTO `words` VALUES (17422, 'She swiped me across the face.', 'v. 猛击; n. 猛击', '/swaɪp/', 'swipe', 6);
INSERT INTO `words` VALUES (17423, '...small swirls of chocolate cream.', 'n. 漩涡, 涡状形', '/swə:l | swɜːl | swɝl/', 'swirl', 6);
INSERT INTO `words` VALUES (17424, 'This is known as the “switcheroo.”', 'n. [俚]突然变化', '/,switʃə\'ru: | ,swɪtʃə\'ruː/', 'switcheroo', 6);
INSERT INTO `words` VALUES (17425, 'The eagle hovered, ready to swoop at any moment.', 'v. 猛扑； 攫取', '/swuːp | swup/', 'swoop', 6);
INSERT INTO `words` VALUES (17426, 'While ten years ago design and style were unique selling propositions, nowadays they are minimum requirements to attract the sybaritic post-modern guest.', 'adj. 奢侈逸乐的, 柔弱的', '/,sibə\'ritik | ,sɪbə\'rɪtɪk/', 'sybaritic', 6);
INSERT INTO `words` VALUES (17427, 'a dictator surrounded by sycophants', 'n. 拍马屁的人, 谄媚者, 奉承者', '/\'sikəfənt, -fænt | \'sɪkəfænt/', 'sycophant', 6);
INSERT INTO `words` VALUES (17428, 'sycophantic journalists', 'adj. 说奉承话的, 阿谀的', '/,sikəu\'fæntik | ,sɪkə\'fæntɪk/', 'sycophantic', 6);
INSERT INTO `words` VALUES (17429, 'Which syllable does the stress of this word fall on?', 'n. 音节', '/\'sɪləbl/', 'syllable', 6);
INSERT INTO `words` VALUES (17430, 'The writers on the syllabus consistently try to imagine a way to make those claims, make those claims for the primacy and the importance of what they do.', 'n. 课程提纲', '/\'siləbəs | \'sɪləbəs/', 'syllabus', 6);
INSERT INTO `words` VALUES (17431, '...the link between bacteria, symbiosis, and the evolution of plants and animals.', 'n. [生]共生(现象), 合作(或互利,互依)关系', '/,simbi\'əusis, -bai- | ,sɪmbɪ\'əʊsɪs; -baɪ- | ,sɪmbaɪ\'osɪs/', 'symbiosis', 6);
INSERT INTO `words` VALUES (17432, 'Each element of the ceremony has a symbolic meaning .', 'adj. 符号的； 象征的', '/sɪm\'bɑːlɪk | sɪm\'bɑlɪk/', 'symbolic', 6);
INSERT INTO `words` VALUES (17433, 'Crime often symbolizes a wider social problem.', 'v. 象征', '/\'sɪmbəlaɪz/', 'symbolize', 6);
INSERT INTO `words` VALUES (17434, 'The pattern was perfectly symmetrical.', 'adj. 对称的, 均匀的', '/si\'metrikəl | sɪ\'metrɪk(ə)l | sɪ\'mɛtrɪkl/', 'symmetrical', 6);
INSERT INTO `words` VALUES (17435, '...the incredible beauty and symmetry of a snowflake.', 'n. 对称, 匀称', '/\'simitri | \'sɪmɪtrɪ | \'sɪmətri/', 'symmetry', 6);
INSERT INTO `words` VALUES (17436, 'a sympathetic friend', 'adj. 有同情心的', '/ˌsɪmpə\'θetɪk | ,sɪmpə\'θɛtɪk/', 'sympathetic', 6);
INSERT INTO `words` VALUES (17437, 'He had been taking part in an international symposium on population.', 'n. 讨论会, 座谈会', '/sim\'pəuziəm | sɪm\'pəʊzɪəm | sɪm\'pozɪəm/', 'symposium', 6);
INSERT INTO `words` VALUES (17438, 'Fever is symptomatic of illness.', 'adj. 有症状的', '/ˌsɪmptə\'mætɪk | \'sɪmptə\'mætɪk/', 'symptomatic', 6);
INSERT INTO `words` VALUES (17439, NULL, 'n. [解]神经原的神经线连接, 神经键', '/\'sainæps, \'si-, si\'næps | \'saɪnæps; \'sɪn- | ˈsɪnˌæps; sɪˈnæps/', 'synapse', 6);
INSERT INTO `words` VALUES (17440, 'I is the initial is less on your footsteps, or midway lost and you synchronization frequency?', 'n. 同步', '/ˌsɪŋkrənə\'zeɪʃn | ,sɪnkrənaɪ\'zeʃən/', 'synchronization', 6);
INSERT INTO `words` VALUES (17441, 'It was virtually impossible to synchronize our lives so as to take vacations and weekends together.', 'v. 同步', '/\'siŋkrənaiz | \'sɪŋkrənaɪz/', 'synchronize', 6);
INSERT INTO `words` VALUES (17442, 'Transitions within states should normally be synchronous, since there is no change of owner.', 'adj. 同时的, [物]同步的', '/\'siŋkrənəs | \'sɪŋkrənəs/', 'synchronous', 6);
INSERT INTO `words` VALUES (17443, NULL, 'v. [音]切分, [语]词中省略', '/\'siŋkəpeit, \'sin- | \'sɪŋkəpeɪt | \'sɪnkəpet/', 'syncopate', 6);
INSERT INTO `words` VALUES (17444, 'He tried to syncretize historical and logical empiricism view on scientific rationality.', 'v. 结合, 融合', '/\'siŋkritaiz, \'sin- | \'sɪŋkrɪtaɪz | \'sɪnkrɪtaɪz/', 'syncretize', 6);
INSERT INTO `words` VALUES (17445, 'people who suffer from irritable bowel syndrome', 'n. 综合症', '/\'sɪndroum | \'sɪndrəm/', 'syndrome', 6);
INSERT INTO `words` VALUES (17446, 'Good ability to solve problem; good attitude for work and good energy for solidify synergic , stronger responsibility for work.', 'adj. 协作的, 合作的', '/si\'nə:dʒik/', 'synergic', 6);
INSERT INTO `words` VALUES (17447, '\"Getting fit\" became synonymous not just with healthier living, but with a leaner, meaner body, and the ground was laid for a burgeoning gym industry.', 'adj. 同义的', '/si\'nɔniməs | sɪ\'nɒnɪməs | sɪ\'nɑnɪməs/', 'synonymous', 6);
INSERT INTO `words` VALUES (17448, 'If you’re speaking at a conference, people come to your session because of the synopsis – that’s what they’re interested in.', 'n. 大纲', '/si\'nɔpsis | sɪ\'nɒpsɪs | sɪ\'nɑpsɪs/', 'synopsis', 6);
INSERT INTO `words` VALUES (17449, 'The information based on bibliographical sources has not been included in the synoptic table because they were too heterogeneous.', 'adj. 概要的, [气]天气的, [宗]对观福音书的', '/si\'nɔptik | sɪ\'nɒptɪk | sɪ\'nɑptɪk/', 'synoptic', 6);
INSERT INTO `words` VALUES (17450, 'speech synthesis software', 'n. 综合， 合成', '/\'sɪnθəsɪs/', 'synthesis', 6);
INSERT INTO `words` VALUES (17451, 'DDT is a pesticide that was first synthesized in 1874.', 'v. 综合； 合成', '/\'sɪnθəsaɪz/', 'synthesize', 6);
INSERT INTO `words` VALUES (17452, 'synthetic chemicals', 'adj. 合成的, 人造的, 综合的', '/sin\'θetik | sɪn\'θetɪk | sɪn\'θɛtɪk/', 'synthetic', 6);
INSERT INTO `words` VALUES (17453, 'As he reached over, Azrak slid a hypodermic syringe into his left arm.', 'n. 注射器, 注油器, 洗涤器', '/\'sirindʒ, sə\'rindʒ | sɪ\'rɪn(d)ʒ; \'sɪ- | sɪ\'rɪndʒ/', 'syringe', 6);
INSERT INTO `words` VALUES (17454, 'I prefer the first one because this kind of learning is systematic and formal.', 'adj. 系统的， 体系的', '/ˌsɪstə\'mætɪk | \'sɪstə\'mætɪk/', 'systematic', 6);
INSERT INTO `words` VALUES (17455, 'a systemic disease', 'adj. 系统的, 身体组织的, 全身的', '/si\'stemik, -\'sti:- | sɪ\'stemɪk; -\'stiːm- | sɪ\'stɛmɪk/', 'systemic', 6);
INSERT INTO `words` VALUES (17456, NULL, 'n. 临时房屋, 帐篷, 身体, 壁龛, 礼拜堂, 神龛', '/\'tæbənækl | \'tæbə,næk(ə)l | \'tæbɚnækl/', 'tabernacle', 6);
INSERT INTO `words` VALUES (17457, 'The food was served on long tables.', 'n. 桌子, 餐桌, 工作台, 平地层, 石板, 表格', '/\'teibl | \'teɪb(ə)l | \'tebl/', 'table', 6);
INSERT INTO `words` VALUES (17458, '...Gaudi\'s luxuriant stone tableau of the Nativity on the cathedral\'s east face.', 'n. 生动的场面, 戏剧性局面', '/\'tæbləu, tæ\'bləu | \'tæbləʊ | tæ\'blo/', 'tableau', 6);
INSERT INTO `words` VALUES (17459, 'The northwestern tableland area has a continental plateau climate with long and chilly winter and cool humid summer.', 'n. 高原', '/teibllænd | \'teɪb(ə)llænd | \'tebllænd/', 'tableland', 6);
INSERT INTO `words` VALUES (17460, 'Thanks largely to some splendid muckraking by the Guardian, it is now clear how one tabloid obtained some of its headlines.', 'n. 小报, 药片', '/\'tæblɔid/', 'tabloid', 6);
INSERT INTO `words` VALUES (17461, 'The topic of addiction remains something of a taboo in our family.', 'n. (宗教)禁忌、避讳, 禁止接近, 禁止使用', '/tə\'bu:, tæ- | tə\'buː | tə\'bu/', 'taboo', 6);
INSERT INTO `words` VALUES (17462, NULL, 'n. [画]色彩, 斑点, 搭扣, 钩扣, 纽带, 环节', '/tætʃ, tɑ:ʃ/', 'tache', 6);
INSERT INTO `words` VALUES (17463, 'a tacit agreement between the three big companies', 'adj. 默许的', '/\'tæsɪt/', 'tacit', 6);
INSERT INTO `words` VALUES (17464, 'We took a floatplane to the trail head. Our taciturn guide pointed out that it was this robust aircraft that had helped to open up the wilderness in the Fifties.', 'adj. 沉默寡言的', '/\'tæsitə:n | \'tæsɪtɜːn | \'tæsɪtɝn/', 'taciturn', 6);
INSERT INTO `words` VALUES (17465, 'If that doesn’t work, we’ll try a different tack .', 'n. 大头钉, 粗缝, 行动方针, 食物', '/tæk/', 'tack', 6);
INSERT INTO `words` VALUES (17466, 'There is more than one way to tackle the problem.', 'v. 处理; n. 滑车', '/\'tækl/', 'tackle', 6);
INSERT INTO `words` VALUES (17467, 'tacky ornaments', 'adj. 有些粘的, 缺乏教养或风度的, 俗气的', '/\'tæki | \'tækɪ/', 'tacky', 6);
INSERT INTO `words` VALUES (17468, 'With great tact, Clive persuaded her to apologize.', 'n. 机智, 手法, 老练, 角觉', '/tækt/', 'tact', 6);
INSERT INTO `words` VALUES (17469, 'There was no tactful way of phrasing what he wanted to say.', 'adj. 机智的, 得体的, 圆滑的', '/\'tæktful | \'tæktfʊl; -f(ə)l | \'tæktfl/', 'tactful', 6);
INSERT INTO `words` VALUES (17470, 'You have probably heard of this tactic before.', 'n. 策略, 战略', '/\'tæktik | \'tæktɪk/', 'tactic', 6);
INSERT INTO `words` VALUES (17471, '{\"COLLOINEXA\":[\"tactile sensations\"]}', 'adj. 触觉的, 有触觉的, 能触知的', '/\'tæktail, -til | \'tæktaɪl | \'tæktl/', 'tactile', 6);
INSERT INTO `words` VALUES (17472, '‘Would you like some milk?’ ‘Just a tad.’', 'n. 小孩子(尤指男孩),微量,少量', '/tæd/', 'tad', 6);
INSERT INTO `words` VALUES (17473, 'The tadpole has become a frog.', 'n. [动]蝌蚪', '/\'tædpəul | \'tædpəʊl | \'tæd\'pol/', 'tadpole', 6);
INSERT INTO `words` VALUES (17474, 'His speed earned him the tag of ‘the runner’.', 'n. 标签, 鞋带、绳子等末端的金属物, 垂下物, 附属物, 名称, 标记符, 陈词滥调, 结束语', '/tæɡ | tæg/', 'tag', 6);
INSERT INTO `words` VALUES (17475, 'When performing taint flow analysis, the scanner models the flow of data within the system.', 'v. 感染', '/teint | teɪnt | tent/', 'taint', 6);
INSERT INTO `words` VALUES (17476, NULL, 'n. (用复数)营业收入, 取得, 捕获', '/\'teikiŋ | \'teɪkɪŋ | \'tekɪŋ/', 'taking', 6);
INSERT INTO `words` VALUES (17477, NULL, 'n. 揭人隐私者, 搬弄是非者, 散播谣言者, 告密者', '/\'teil,bεərə | \'teɪlbeərə | \'tel,bɛrɚ/', 'talebearer', 6);
INSERT INTO `words` VALUES (17478, 'He has a lot of talent , and his work is fresh and interesting.', 'n. 天赋； 天才', '/\'tælənt/', 'talent', 6);
INSERT INTO `words` VALUES (17479, 'a talented actor', 'adj. 天才的', '/\'tæləntɪd/', 'talented', 6);
INSERT INTO `words` VALUES (17480, NULL, 'n. 护身符, 辟邪物, 能产生奇迹的东西, 法宝', '/\'tælizmən, -lis- | \'tælɪzmən | \'tælɪsmən/', 'talisman', 6);
INSERT INTO `words` VALUES (17481, NULL, 'n. 冗长的讨论, 冗长的演说', '/\'tɔːkəθɒn | \'tɔkəθɑn/', 'talkathon', 6);
INSERT INTO `words` VALUES (17482, 'The final tally was $465,000.', 'n. 符木(古时用,上有刻痕记载交货、欠款等的数量), 记账, 得分, 标记牌, 标签, 符合, 对应物, 计数器', '/\'tæli | \'tælɪ/', 'tally', 6);
INSERT INTO `words` VALUES (17483, 'Deinonychus, or \"terrible claw\" after the sickle-shaped talon on each hind foot, stood about 11 feet from head to tail and was a lithe predator.', 'n. 爪, 魔爪', '/\'tælən/', 'talon', 6);
INSERT INTO `words` VALUES (17484, 'She stood biting her lip, watching, for nearly an hour, until Joseph put his tambourine down and opened his eyes.', 'n. 小手鼓', '/,tæmbə\'ri:n | ,tæmbə\'riːn | ,tæmbə\'rin/', 'tambourine', 6);
INSERT INTO `words` VALUES (17485, 'Most of the criticism has been pretty tame.', 'adj. 驯服的； 沉闷的， 平淡的', '/teɪm/', 'tame', 6);
INSERT INTO `words` VALUES (17486, 'The old man tamped down the tobacco with his thumb.', 'v. 填塞, 夯实', '/tæmp/', 'tamp', 6);
INSERT INTO `words` VALUES (17487, 'I don\'t want to be accused of tampering with the evidence.', 'v. 干预, 玩弄, 贿赂, 损害, 削弱, 篡改', '/\'tæmpə | \'tæmpɚ/', 'tamper', 6);
INSERT INTO `words` VALUES (17488, NULL, 'v. 有浓味', '/tæŋ/', 'tang', 6);
INSERT INTO `words` VALUES (17489, NULL, 'adj. 接触的, 切线的, 相切的, 离题的', '/\'tændʒənt | ˈtændʒənt/', 'tangent', 6);
INSERT INTO `words` VALUES (17490, 'He closed his office on the street tangential to the courthouse square and walked the two blocks to his house..', 'adj. 切线的', '/tæn\'dʒenʃəl | tæn\'dʒenʃ(ə)l | tæn\'dʒɛnʃl/', 'tangential', 6);
INSERT INTO `words` VALUES (17491, 'The scheme must have tangible benefits for the unemployed.', 'adj. 切实的', '/\'tændʒəbl | \'tæn(d)ʒɪb(ə)l/', 'tangible', 6);
INSERT INTO `words` VALUES (17492, 'My hair tangles easily.', 'v. 缠结; n. 纷乱', '/\'tæŋgl | \'tæŋɡl/', 'tangle', 6);
INSERT INTO `words` VALUES (17493, 'A tango was playing on the jukebox.', 'n. 探戈', '/\'tæŋɡəu | \'tæŋgəʊ | \'tæŋɡo/', 'tango', 6);
INSERT INTO `words` VALUES (17494, 'The smoky, tangy flavor associated with gutter oil can do wonders to simple, everyday dishes.', 'adj. 气味刺激的， 扑鼻的', '/\'tæŋi/', 'tangy', 6);
INSERT INTO `words` VALUES (17495, '...a tankard of ale.', 'n. 大啤酒杯, 一大杯', '/\'tæŋkəd | \'tæŋkɚd/', 'tankard', 6);
INSERT INTO `words` VALUES (17496, NULL, 'n. 制革工人, 六便士', '/\'tænə | \'tænɚ/', 'tanner', 6);
