INSERT INTO `words` VALUES (17511, 'Then saith he unto them, My soul is exceeding sorrowful, even unto death: tarry ye here, and watch with me.', 'v. 等候', '/\'tæri | \'tɑːrɪ/', 'tarry', 6);
