INSERT INTO `words` VALUES (17532, 'The work was tiring and tedious.', 'adj. 单调乏味的, 沉闷的, 冗长乏味的', '/\'ti:diəs, \'ti:dʒəs | \'tiːdɪəs | \'tidɪəs/', 'tedious', 6);
INSERT INTO `words` VALUES (17533, 'Cut out the tedium of converting your photos manually by using automation features in your photo editing software.', 'n. 厌烦, 沉闷', '/\'ti:diəm | \'tiːdɪəm | \'tidɪəm/', 'tedium', 6);
