INSERT INTO `words` VALUES (17537, 'You never tell me what you\'re thinking. Am I supposed to use telepathy?', 'n. 心灵感应, 感应', '/ti\'lepəθi, tə- | tɪ\'lepəθɪ | tə\'lɛpəθi/', 'telepathy', 6);
