INSERT INTO `words` VALUES (17539, 'He actually had the temerity to tell her to lose weight.', 'n. 卤莽, 蛮勇', '/ti\'merəti, tə- | tə\'merəti | tə\'mɛrəti/', 'temerity', 6);
INSERT INTO `words` VALUES (17540, 'She began working for the company as a temp.', 'n. 临时雇员', '/temp | tɛmp/', 'temp', 6);
INSERT INTO `words` VALUES (17541, 'I’ve never seen Vic lose his temper.', 'n. (钢等)韧度, 回火, 性情, 脾气, 情绪, 心情, 调剂, 趋向', '/\'tempə | \'tɛmpɚ/', 'temper', 6);
INSERT INTO `words` VALUES (17542, 'Preston is particularly good at handling temperamental people.', 'adj. 由气质引起的, 心情变化快的, 喜怒无常的', '/,tempərə\'mentəl | ,temp(ə)rə\'ment(ə)l | \'tɛmprə\'mɛntl/', 'temperamental', 6);
INSERT INTO `words` VALUES (17543, '...a reformed alcoholic extolling the joys of temperance.', 'n. 节欲, 戒酒, 禁酒, (气候等的)温和', '/\'tempərəns | \'temp(ə)r(ə)ns | \'tɛmpərəns/', 'temperance', 6);
INSERT INTO `words` VALUES (17544, 'The Nile Valley keeps a temperate climate throughout the year.', 'adj. 有节制的, 适度的, 戒酒的, (气候)温和的', '/\'tempərit | \'temp(ə)rət | \'tɛmpərət/', 'temperate', 6);
INSERT INTO `words` VALUES (17545, 'I hadn\'t foreseen the tempest my request would cause.', 'n. 暴风雨, 骚乱, 动乱', '/\'tempist | \'tempɪst | \'tɛmpɪst/', 'tempest', 6);
