INSERT INTO `words` VALUES (17549, 'temporary pain relief', 'adj. 暂时的, 临时的, 临时性', '/\'tempərəri | \'temp(ə)rərɪ | \'tɛmpə\'rɛri/', 'temporary', 6);
INSERT INTO `words` VALUES (17550, 'They are still temporizing in the face of what can only be described as a disaster.', 'v. 见风驶舵', '/\'tempəraiz | \'tempəraɪz | \'tɛmpə\'raɪz/', 'temporize', 6);
INSERT INTO `words` VALUES (17551, 'Resist the temptation to buy the item until you’re certain you need it.', 'n. 诱惑, 诱惑物', '/temp\'teiʃən | tem(p)\'teɪʃ(ə)n | tɛmp\'teʃən/', 'temptation', 6);
INSERT INTO `words` VALUES (17552, 'a tempting job offer', 'adj. 诱惑人的', '/\'temptɪŋ | \'tɛmptɪŋ/', 'tempting', 6);
INSERT INTO `words` VALUES (17553, 'The theory which is once again put forth, that the Germans as such are inherently vicious, is hardly tenable and not very creditable to those who hold it.', 'adj. 可维持的', '/\'tenəbl | \'tenəb(ə)l/', 'tenable', 6);
