INSERT INTO `words` VALUES (17566, 'While tentative, this science is telling us that each of us is a package composed of Mommy\'s genes, Daddy\'s genes and the bacterial genes that have moved in and stayed.', 'n. 试验, 假设', '/\'tentətiv | \'tentətɪv | \'tɛntətɪv/', 'tentative', 6);
INSERT INTO `words` VALUES (17567, 'The software tentatively assigns each click a letter based on its frequency , then tests the message created by this assignment using statistical models of the English language .', 'adv. 试验性地', '/\'tentətɪvli | \'tɛntətɪvli/', 'tentatively', 6);
INSERT INTO `words` VALUES (17568, 'In this method, the relationship of risk management and the key project measurements is tenuous.', 'adj. 纤细的', '/\'tenjuəs | \'tenjʊəs | \'tɛnjuəs/', 'tenuous', 6);
