INSERT INTO `words` VALUES (17577, 'computer terminology', 'n. 术语学', '/,tə:mi\'nɔlədʒi | ,tɜːmɪ\'nɒlədʒɪ | ,tɝmə\'nɑlədʒi/', 'terminology', 6);
INSERT INTO `words` VALUES (17578, 'What time does the train reach the terminus?', 'n. 终点, [建]界标, 终点站', '/\'tə:minəs | \'tɜːmɪnəs | \'tɝmɪnəs/', 'terminus', 6);
