INSERT INTO `words` VALUES (17590, 'The falsification of the testament [will] was discovered by them.', 'n. 遗嘱', '/\'testəmənt | \'testəm(ə)nt | \'tɛstəmənt/', 'testament', 6);
INSERT INTO `words` VALUES (17591, 'Mr Molto has agreed to testify at the trial.', 'v. 证明, 证实, 作证', '/\'testifai | \'testɪfaɪ | \'tɛstɪfaɪ/', 'testify', 6);
