INSERT INTO `words` VALUES (17593, 'Barker’s testimony is crucial to the prosecution’s case.', 'n. 证词(尤指在法庭所作的), 宣言, 陈述', '/\'testiməni | \'testɪmənɪ | \'tɛstə\'moni/', 'testimony', 6);
