INSERT INTO `words` VALUES (17599, 'In going 20 years, petrifaction industry also obtained swift and violent development in thalassic area, already became one of main force of international petrifaction course of study.', 'adj. 海的, 内海的, 海湾的', '/θə\'læsik | θə\'læsɪk/', 'thalassic', 6);
