INSERT INTO `words` VALUES (17606, NULL, 'n. 神权政治, 神政, 神治国', '/θi\'ɔkrəsi | θɪ\'ɒkrəsɪ | θɪ\'ɑkrəsi/', 'theocracy', 6);
INSERT INTO `words` VALUES (17607, 'He studied theology at college.', 'n. 神学', '/θi\'ɔlədʒi | θiː\'ɒlədʒɪ | θɪ\'ɑlədʒi/', 'theology', 6);
