INSERT INTO `words` VALUES (17610, 'Some claim that the herb has therapeutic value for treating pain.', 'adj. 治疗的, 治疗学的', '/,θerə\'pju:tik | ,θerə\'pjuːtɪk | ,θɛrə\'pjutɪk/', 'therapeutic', 6);
INSERT INTO `words` VALUES (17611, 'new drug therapies', 'n. 治疗', '/\'θerəpi | \'θerəpɪ | \'θɛrəpi/', 'therapy', 6);
INSERT INTO `words` VALUES (17612, 'thermal energy', 'adj. 热的，热量的；温暖的; n. 上升的暖气流', '/\'θɜːrml | \'θɝml/', 'thermal', 6);
INSERT INTO `words` VALUES (17613, 'There\'s a skeleton made of thermoplastic polymer, actuators that correspond to each muscle and kiteline as tendons.', 'adj. 热塑性的', '/,θə:məu\'plæstik | θɜːməʊ\'plæstɪk | ,θɝmo\'plæstɪk/', 'thermoplastic', 6);
INSERT INTO `words` VALUES (17614, 'Like compression molding, this method is used to form thermoset materials and involves permanently curing the plastic in a mold under heat and pressure.', 'n. 热固树脂,热固塑料', '/\'θə:məuset/', 'thermoset', 6);
INSERT INTO `words` VALUES (17615, 'The most extensive approach is a full thesaurus.', 'n. 辞典', '/θi\'sɔ:rəs | θɪ\'sɔːrəs | θɪ\'sɔrəs/', 'thesaurus', 6);
INSERT INTO `words` VALUES (17616, 'Cynthia’s still working on her thesis.', 'n. 论题， 论文', '/\'θiːsɪs | \'θisɪs/', 'thesis', 6);
