INSERT INTO `words` VALUES (17623, 'It\'shows a thousandfold selectivity for fluoride over other common anions.', 'adv. 千倍地; adj. 千倍的', '/\'θauzndfould | \'θaʊznd\'fold/', 'thousandfold', 6);
INSERT INTO `words` VALUES (17624, 'He is not in thrall to the media.', 'n. 奴隶, 束缚, 奴役', '/θrɔ:l | θrɔːl | θrɔl/', 'thrall', 6);
INSERT INTO `words` VALUES (17625, 'My poor brother used to get thrashed for all kinds of minor offences.', 'v. 打(谷), (用棍、鞭等)痛打, 打败, 使逆行, 胜过, 使颠簸, 推敲', '/θræʃ/', 'thrash', 6);
