INSERT INTO `words` VALUES (17635, 'Her mouth was making croaking, throaty sounds like the toneless cry when we make love.', 'adj. 喉音的, 喉部发出声音的, 嘶哑的', '/\'θrəuti | \'θrəʊtɪ | \'θroti/', 'throaty', 6);
INSERT INTO `words` VALUES (17636, 'The first impulse to write this novel is described as a throb.', 'n. 悸动, 脉搏', '/θrɔb | θrɒb | θrɑb/', 'throb', 6);
INSERT INTO `words` VALUES (17637, 'Transport is taught by throe.', 'n. 剧痛；', '/θrou | θrəu/', 'throe', 6);
