INSERT INTO `words` VALUES (17639, 'policies which are throttling many Asian economies', 'v. 扼杀', '/\'θrɔtl | \'θrɒt(ə)l | \'θrɑtl/', 'throttle', 6);
INSERT INTO `words` VALUES (17640, 'He jumped back to avoid another thrust of the knife.', 'n. 插, 戳, 刺, 推力, 猛推, 口头攻击', '/θrʌst/', 'thrust', 6);
INSERT INTO `words` VALUES (17641, 'If you don’t shut up, I’m going to thump you!', 'v. 重击， 捶击', '/θʌmp/', 'thump', 6);
