INSERT INTO `words` VALUES (17643, NULL, 'n. 记事本, 备忘录, 使人发痒的人', '/\'tiklə | \'tɪklə | \'tɪklɚ/', 'tickler', 6);
INSERT INTO `words` VALUES (17644, 'Handling awkward neighbours can be a ticklish business .', 'adj. 易痒的, 不稳定的, 难对付的, 忌讳的', '/\'tikliʃ | \'tɪklɪʃ/', 'ticklish', 6);
INSERT INTO `words` VALUES (17645, 'a tidy desk', 'adj. 整齐的， 整洁的； 相当好的', '/\'taɪdi/', 'tidy', 6);
