INSERT INTO `words` VALUES (17655, 'Even in the dim light the equipment looked old and timeworn.', 'adj. 陈旧的， 陈腐的', '/\'taɪmwɔːrn | \'taɪm,worn/', 'timeworn', 6);
INSERT INTO `words` VALUES (17656, 'I was a timid child.', 'adj. 羞怯的； 胆怯的， 怯懦的', '/\'tɪmɪd/', 'timid', 6);
