INSERT INTO `words` VALUES (17672, 'They work as drivers or nannies, or blend into a businessman\'s coterie looking like a secretary, a briefcase carrier or a toady.', 'n. 谄媚者, 拍马屁的人', '/\'təudi | \'təʊdɪ | \'todi/', 'toady', 6);
INSERT INTO `words` VALUES (17673, 'The Government, with an army in its hand, hesitated; the night was almost upon them, and the Saint-Merry tocsin began to make itself heard.', 'n. 警钟, 警报', '/\'tɔksin | \'tɒksɪn | \'tɑksɪn/', 'tocsin', 6);
