INSERT INTO `words` VALUES (17690, 'He left his room all topsy-turvy.', 'adj. 颠倒的， 相反的； 乱七八糟的， 混乱的', '/,tɔpsi\'tə:vi | ˌtɑːpsi\'tɜːrvi/', 'topsy-turvy', 6);
INSERT INTO `words` VALUES (17691, 'The journey must have been a torment for them.', 'n. 折磨， 痛苦', '/\'tɔːrment | \'tɔrmɛnt/', 'torment', 6);
INSERT INTO `words` VALUES (17692, NULL, 'n. 旋风, 龙卷风, 大雷雨, 具有巨大破坏性的人(或事物)[军] (“狂风”) 英国、德国、意大利三国合作研制的双座双发超音速变后掠翼战斗机', '/tɔ:\'neidəu | tɔː\'neɪdəʊ | tɔr\'nedo/', 'tornado', 6);
INSERT INTO `words` VALUES (17693, 'a torpid mind', 'adj. 麻痹的, 迟缓的, 迟钝的, [动]蛰伏的', '/\'tɔ:pid | \'tɔːpɪd | \'tɔrpɪd/', 'torpid', 6);
INSERT INTO `words` VALUES (17694, 'She tried to rouse him from the torpor into which he had sunk.', 'n. 迟钝, 无感觉, 不活泼', '/\'tɔ:pə | \'tɔːpə | \'tɔrpɚ/', 'torpor', 6);
