INSERT INTO `words` VALUES (17698, 'The storms and torrential rain caused traffic chaos across the country.', 'adj. 奔流的， 洪流的， 湍急的', '/tə\'renʃl | tə\'rɛnʃl/', 'torrential', 6);
INSERT INTO `words` VALUES (17699, 'a torrid love affair', 'adj. 热带的', '/\'tɔrid, \'tɔ:- | \'tɒrɪd | \'tɔrɪd/', 'torrid', 6);
INSERT INTO `words` VALUES (17700, 'Considering vertical and horizontal bending moment and tortile moment action together, equivalent bending moment is proposed in this paper to evaluate anti-bend capability of wall.', 'adj. 扭转的, 弯曲的', '/\'tɔːtaɪl | \'tɔt\'tɪl/', 'tortile', 6);
INSERT INTO `words` VALUES (17701, 'a tortuous path over the mountains to Kandahar', 'adj. 曲折的, 转弯抹角的', '/\'tɔ:tjuəs, -tʃu- | \'tɔːtʃʊəs; -jʊəs | \'tɔrtʃuəs/', 'tortuous', 6);
INSERT INTO `words` VALUES (17702, 'He died after five days of excruciating torture.', 'n. 折磨, 痛苦, 拷问, 拷打', '/\'tɔ:tʃə | \'tɔːtʃə | \'tɔrtʃɚ/', 'torture', 6);
INSERT INTO `words` VALUES (17703, 'Toss the carrots in some butter before serving.', 'v. 投， 掷； 使摇动， 使颠簸', '/tɑːs | tɔs/', 'toss', 6);
INSERT INTO `words` VALUES (17704, '...a brutal totalitarian regime.', 'adj. 极权主义的', '/,təutæli\'tεəriən | ,təʊtælɪ\'teərɪən; tə(ʊ),tælɪ- | to,tælə\'tɛrɪən/', 'totalitarian', 6);
INSERT INTO `words` VALUES (17705, '...a process of social, economic and political change which involves the totality of human experience.', 'n. 全体, 总数, [天]全食', '/təu\'tæləti | tə(ʊ)\'tælɪtɪ | to\'tæləti/', 'totality', 6);
INSERT INTO `words` VALUES (17706, 'This opera is one of the cultural totems of Western civilization.', 'n. 图腾, 标识, 徽章', '/\'təutəm | \'təʊtəm | \'totəm/', 'totem', 6);
