INSERT INTO `words` VALUES (17710, 'a touching reunion of father and son', 'adj. 动人的， 感人的； 令人同情的', '/\'tʌtʃɪŋ/', 'touching', 6);
INSERT INTO `words` VALUES (17711, 'She is very touchy about her past.', 'adj. 暴躁的, 难以处理的, 易起火的', '/\'tʌtʃi | \'tʌtʃɪ/', 'touchy', 6);
INSERT INTO `words` VALUES (17712, 'How much did you spend on that bad toupee?', 'n. 男子假发', '/\'tu:pei, tu:\'pei | \'tuːpeɪ | tu\'pe/', 'toupee', 6);
INSERT INTO `words` VALUES (17713, 'I feel I can win this tournament.', 'n. 比赛, 锦标赛, 联赛', '/\'tuənəmənt, \'tɔ:-, \'tə:- | \'tʊənəm(ə)nt | \'tɔnəmənt/', 'tournament', 6);
INSERT INTO `words` VALUES (17714, 'That will work as a tourniquet.', 'n. 止血带, 压脉器', '/\'tuənikei, -kit, -ket, \'tə:- | \'tʊənɪkeɪ; \'tɔː- | \'tɝnəkət/', 'tourniquet', 6);
INSERT INTO `words` VALUES (17715, NULL, 'n. 乱七八糟的一团, 糟乱', '/\'tauzl | \'taʊz(ə)l | \'taʊzl/', 'tousle', 6);
INSERT INTO `words` VALUES (17716, 'his much touted musical', 'v. 吹捧', '/taut | taʊt/', 'tout', 6);
INSERT INTO `words` VALUES (17717, 'great towering cliffs', 'adj. 高耸的, 杰出的, 激烈的', '/\'tauəriŋ | \'taʊərɪŋ/', 'towering', 6);
INSERT INTO `words` VALUES (17718, 'fumes from a toxic waste dump', 'adj. 有毒的, 中毒的', '/\'tɔksik | \'tɒksɪk | \'tɑksɪk/', 'toxic', 6);
INSERT INTO `words` VALUES (17719, 'Tests showed increased levels of toxin in shellfish.', 'n. [生化][生]毒素', '/\'tɔksin | \'tɒksɪn | \'tɑksɪn/', 'toxin', 6);
INSERT INTO `words` VALUES (17720, 'some toys for the baby', 'n. 玩具', '/tɔi | tɒɪ | tɔɪ/', 'toy', 6);
INSERT INTO `words` VALUES (17721, 'Sondheim’s book traces the changing nature of the relationship between men and women.', 'v. 追踪; n. 痕迹', '/treɪs | tres/', 'trace', 6);
INSERT INTO `words` VALUES (17722, 'To ensure reliable communication to take place over a network, data to be sent must be put in manageable traceable packages.', 'adj. 可追踪的', '/\'treɪsəbl | \'tresəbl/', 'traceable', 6);
INSERT INTO `words` VALUES (17723, 'Police have been tracking the four criminals all over Central America.', 'v. 跟踪， 追踪; n. 轨迹，踪迹；道路，路径；轨道', '/træk/', 'track', 6);
INSERT INTO `words` VALUES (17724, 'vast tracts of woodland', 'n. 传单； 大片土地', '/trækt/', 'tract', 6);
INSERT INTO `words` VALUES (17725, 'You will find the dog\'s tractability and friendliness.', 'n. 温顺', '/,træktə\'biləti | ˌtræktə\'bɪləti/', 'tractability', 6);
INSERT INTO `words` VALUES (17726, 'The issues have proved to be less tractable than expected.', 'adj. 易驾驭的, 驯良的, 易管教的, 易处理的', '/\'træktəbl | \'træktəb(ə)l/', 'tractable', 6);
INSERT INTO `words` VALUES (17727, 'Snap to one 100 words tractate in 30 minutes regarding mostly students of their class is very easy.', 'n. 论文, 短文', '/\'trækteɪt | \'trækteit/', 'tractate', 6);
INSERT INTO `words` VALUES (17728, 'This process gives your vehicle the best chance of holding traction on the steep hill, because both the gearbox and the brakes are locking you in place.', 'n. 牵引', '/\'trækʃən | \'trækʃ(ə)n/', 'traction', 6);
INSERT INTO `words` VALUES (17729, 'The striped T-shirt became the comedian’s trademark.', 'v. 保证商标权; n. 特征；商标', '/\'treɪdmɑːrk | \'tred\'mɑrk/', 'trademark', 6);
INSERT INTO `words` VALUES (17730, 'We have been traduced in the press as xenophobic bigots.', 'v. 中伤', '/trə\'dju:s | trə\'djuːs | trə\'dus/', 'traduce', 6);
INSERT INTO `words` VALUES (17731, NULL, 'n. 悲剧女演员', '/trə,dʒi:di\'en | trə,dʒiːdɪ\'en | trə,dʒidɪ\'ɛn/', 'tragedienne', 6);
INSERT INTO `words` VALUES (17732, 'The tragedy happened as they were returning home from a night out.', 'n. 惨剧， 惨事， 灾难', '/\'trædʒədi/', 'tragedy', 6);
INSERT INTO `words` VALUES (17733, 'The parents were not to blame for the tragic death of their son.', 'adj. 悲惨的', '/\'trædʒɪk/', 'tragic', 6);
INSERT INTO `words` VALUES (17734, NULL, 'n. 追踪者, 拖车', '/\'treilə | \'treɪlə | \'trelɚ/', 'trailer', 6);
INSERT INTO `words` VALUES (17735, 'A better tip still is to get off your bottom and strut ( or even traipse) around the office.', 'v. 漫步， 闲荡', '/treɪps | treps/', 'traipse', 6);
