INSERT INTO `words` VALUES (17738, 'The decision was certain to affect the trajectory of French politics for some time to come.', 'n. [物](射线的) 轨道, 弹道, 轨线', '/\'trædʒiktəri, trə\'dʒek- | trə\'dʒekt(ə)rɪ; \'trædʒɪkt(ə)rɪ | trə\'dʒɛktəri/', 'trajectory', 6);
INSERT INTO `words` VALUES (17739, NULL, 'n. 拘束, 阻碍物, 束缚物', '/\'træməl | \'træm(ə)l | \'træml/', 'trammel', 6);
INSERT INTO `words` VALUES (17740, NULL, 'adj. 野蛮的, 来自群山彼边的', '/trə\'mɔntein, \'træmən- | trə\'mɒnteɪn | \'træmənten/', 'tramontane', 6);
INSERT INTO `words` VALUES (17741, 'They put on their coats and tramped through the falling snow.', 'v. 重步行走, 踏, 践, 践踏', '/træmp/', 'tramp', 6);
INSERT INTO `words` VALUES (17742, 'When America is under stress, as is happening right now with debates about where to pare the budget, we sometimes trample the least powerful and most vulnerable among us.', 'n. 踩踏, 蹂躏', '/\'træmpl | \'træmp(ə)l/', 'trample', 6);
INSERT INTO `words` VALUES (17743, 'a small tranquil village', 'adj. 安静的', '/\'træŋkwil, \'træn- | \'træŋkwɪl | ˈtræŋkwəl/', 'tranquil', 6);
INSERT INTO `words` VALUES (17744, 'We all like the tranquility of the country life.', 'n. 宁静， 安静', '/træŋ\'kwiləti, træn- | træŋ\'kwɪləti/', 'tranquility', 6);
INSERT INTO `words` VALUES (17745, 'The cull of up to 500 animals using tranquillizer darts followed by lethal injection would begin within two weeks, military spokesman Brigadier Andrew Nikolic said.', 'n. [医]镇定剂, 使镇定的人或物', '/\'træŋkwi,laizə(r)/', 'tranquillizer', 6);
INSERT INTO `words` VALUES (17746, 'The bank charges a fixed rate for each transaction.', 'n. 办理, 处理, 会报, 学报, 交易, 事务, 处理事务', '/træn\'zækʃən, -\'sæk-, trɑ:n- | træn\'zækʃ(ə)n; trɑːn-; -\'sæk- | træn\'zækʃən/', 'transaction', 6);
INSERT INTO `words` VALUES (17747, 'The desire for peace transcended political differences.', 'v. 超越, 胜过', '/træn\'send, trɑ:n- | træn\'send; trɑːn- | træn\'sɛnd/', 'transcend', 6);
INSERT INTO `words` VALUES (17748, 'The Arab-American Society promotes the transcendence of racial and religious differences.', 'n. 卓越, 出类拔萃', '/træn\'sendəns/', 'transcendence', 6);
INSERT INTO `words` VALUES (17749, 'the transcendent genius of Mozart', 'adj. 超越的， 卓越的， 出众的', '/træn\'sendənt | træn\'sɛndənt/', 'transcendent', 6);
INSERT INTO `words` VALUES (17750, '...the transcendental nature of God.', 'adj. 先验的, 超越的, 超出人类经验的', '/,trænsen\'dentəl | ,trænsen\'dent(ə)l; ,trɑːn- | \'trænsɛn\'dɛntl/', 'transcendental', 6);
INSERT INTO `words` VALUES (17751, 'a transcontinental railway', 'adj. 横贯大陆的', '/ˌtrænzˌkɑːntɪ\'nentl | ,trænz,kɑntɪ\'nɛntl/', 'transcontinental', 6);
INSERT INTO `words` VALUES (17752, 'A secretary transcribed the witnesses’ statements.', 'v. 转录', '/træn\'skraib, trænz\'k-, trɑ:n- | træn\'skraɪb; trɑːn- | træn\'skraɪb/', 'transcribe', 6);
INSERT INTO `words` VALUES (17753, 'Pronunciation is shown by a system of phonetic transcription.', 'n. 誊写， 抄写； 抄本， 副本', '/træn\'skrɪpʃn | træn\'skrɪpʃən/', 'transcription', 6);
INSERT INTO `words` VALUES (17754, 'He was transferred for a fee of £8 million.', 'v. 转移， 传递； 转让； 调任， 调动', '/træns\'fɜːr | træns\'fɝ/', 'transfer', 6);
INSERT INTO `words` VALUES (17755, 'Use the transferable skills acquired from your previous working background.', 'adj. 可转移的', '/træns\'fɜːrəbl | trænz\'fərəbl/', 'transferable', 6);
INSERT INTO `words` VALUES (17756, 'Her face was transfigured with joy.', 'v. 使变形, 美化, 理想化', '/træns\'fiɡə, trænz-, trɑ:n, -ɡjuə | træns\'fɪgə; trɑːns-; -nz- | træns\'fɪɡjɚ/', 'transfigure', 6);
INSERT INTO `words` VALUES (17757, 'We were all transfixed by the images of the war.', 'v. 刺穿, 使呆住', '/træns\'fiks, trænz-, trɑ:n- | træns\'fɪks; trɑːns-; -nz- | træns\'fɪks/', 'transfix', 6);
INSERT INTO `words` VALUES (17758, 'Increased population has transformed the landscape.', 'v. 改变， 变化； 变换， 转换', '/træns\'fɔːrm | træns\'fɔrm/', 'transform', 6);
INSERT INTO `words` VALUES (17759, 'In recent years, the movie industry has undergone a dramatic transformation .', 'n. 转化， 转变', '/ˌtrænsfər\'meɪʃn | ,trænsfɚ\'meʃən/', 'transformation', 6);
INSERT INTO `words` VALUES (17760, NULL, 'v. 注入, 灌输, [医]输血', '/træns\'fju:z, trænz-, trɑ:n- | træns\'fjuːz; trɑːns-; -nz- | trænz\'fjʊz/', 'transfuse', 6);
INSERT INTO `words` VALUES (17761, 'Orton’s plays transgress accepted social norms.', 'v. 违反, 犯罪, 侵犯', '/træns\'ɡres, trænz-, trɑ:n- | trænz\'gres; trɑːnz-; -ns- | trænz\'ɡrɛs/', 'transgress', 6);
INSERT INTO `words` VALUES (17762, 'How many are mine iniquities and sins? make me to know my transgression and my sin.', 'n. 违法， 犯罪', '/trænz\'greʃn | trænz\'ɡrɛʃən/', 'transgression', 6);
INSERT INTO `words` VALUES (17763, '...the superficiality and transience of the club scene.', 'n. 短暂， 稍纵即逝', '/\'trænziəns, -si-, -ʃəns, \'trɑ:n- | \'trænʃəns/', 'transience', 6);
INSERT INTO `words` VALUES (17764, 'transient fashions', 'adj. 短暂的, 瞬时的', '/\'trænziənt, -si-, -ʃənt, \'trɑ:n- | \'trænzɪənt | ˈtrænʃnt; trænʃənt/', 'transient', 6);
INSERT INTO `words` VALUES (17765, 'The shortage you claimed might have occurred in the course of transit, which is out of our control.', 'v. 通过; n. 通过；改变；运输', '/\'trænzɪt | \'træzɪt/', 'transit', 6);
INSERT INTO `words` VALUES (17766, 'Making the transition from youth to adulthood can be very painful.', 'n. 转变, 转换, 跃迁, 过渡, 变调', '/træn\'siʒən, -\'ziʃən, trɑ:n- | træn\'zɪʃ(ə)n; trɑːn-; -\'sɪʃ- | træn\'zɪʃən/', 'transition', 6);
INSERT INTO `words` VALUES (17767, 'We live in the transitional age between that decision and its conclusion.', 'adj. 转变的， 变迁的', '/træn\'zɪʃənl/', 'transitional', 6);
INSERT INTO `words` VALUES (17768, 'But man\'s soul is most awake in his knowledge of the interchangeability of the term \"existence\" and \"transitoriness\".', 'n. 暂时， 短暂', '/\'trænzitərinis | \'trænsətɔːrinəs/', 'transitoriness', 6);
INSERT INTO `words` VALUES (17769, 'Most teenage romances are transitory.', 'adj. 短时间的', '/\'trænsitəri, -zi-, \'trɑ:n- | \'trænsɪt(ə)rɪ; \'trɑːns-; -nz- | \'trænsətɔri/', 'transitory', 6);
INSERT INTO `words` VALUES (17770, 'Blue veins showed through her translucent skin.', 'adj. 半透明的, 透明的', '/trænz\'lju:sənt, træns-, trɑ:n- | træns\'luːs(ə)nt; trɑːns-; -nz- | træns\'lusnt/', 'translucent', 6);
INSERT INTO `words` VALUES (17771, 'The US Open will be transmitted live via satellite.', 'v. 传输, 转送, 传达, 传导, 发射, 遗传, 传播', '/trænz\'mit, træns-, trɑ:n- | trænz\'mɪt; trɑːnz-; -ns- | trænzˈmɪt/', 'transmit', 6);
INSERT INTO `words` VALUES (17772, NULL, 'v. 使变形, 使变成奇形怪状', '/trænz\'mɔɡrifai, træns-, trɑ:n- | trænz\'mɒgrɪfaɪ; trɑːnz-; -ns-/', 'transmogrify', 6);
INSERT INTO `words` VALUES (17773, 'Ascension long ago served to transmute karma of the consensus known as Earth so that Earth could retain her vibration.', 'v. 改变', '/trænz\'mju:t, træns-, tra:n- | trænz\'mjuːt; trɑːnz-; -ns- | trænz\'mjut/', 'transmute', 6);
INSERT INTO `words` VALUES (17774, 'a transparent plastic container', 'adj. 透明的, 显然的, 明晰的', '/træns\'pærənt, -\'pεə-, trænz-, trɑ:n- | træn\'spær(ə)nt; trɑːn-; -\'speə- | træns\'pærənt/', 'transparent', 6);
INSERT INTO `words` VALUES (17775, 'Exactly what transpired remains unknown.', 'v. 发生, 得知, 使蒸发, 使排出', '/træn\'spaiə, trænz\'p-, trɑ:n- | træn\'spaɪə; trɑːn- | træn\'spaɪɚ/', 'transpire', 6);
INSERT INTO `words` VALUES (17776, 'The director transposes the action from sixteenth-century France to post-Civil War America.', 'v. 颠倒顺序， 调换', '/træn\'spouz | træn\'spoz/', 'transpose', 6);
INSERT INTO `words` VALUES (17777, NULL, 'v. [医](使)渗出', '/træn\'sju:d, -\'zju:d, trɑ:n- | træn\'sjuːd; trɑːn- | træn\'zjʊd/', 'transude', 6);
INSERT INTO `words` VALUES (17778, NULL, 'n. 高空秋千， 吊架', '/træ\'piːz | træ\'piz/', 'trapeze', 6);
INSERT INTO `words` VALUES (17779, 'This time the modules are rectangular but they also can be in a shape of a trapezium and letter L.', 'n. [数]不等边四边形, 梯形', '/trə\'pi:ziəm, træ- | trə\'piːzɪəm | træ\'pizɪəm/', 'trapezium', 6);
INSERT INTO `words` VALUES (17780, 'Will someone take out the trash (= take it outside the house ) ?', 'n. 无价值之物, 无聊的作品, 垃圾, 废物', '/træʃ/', 'trash', 6);
INSERT INTO `words` VALUES (17781, 'trashy novels', 'adj. 无价值的, 没有用的, 垃圾似的', '/\'træʃi | \'træʃɪ/', 'trashy', 6);
