INSERT INTO `words` VALUES (17783, 'His son’s death was the most traumatic event in Stan’s life.', 'adj. 外伤的, 创伤的', '/trɔː\'mætɪk; traʊ- | traʊ\'mætɪk/', 'traumatic', 6);
