INSERT INTO `words` VALUES (17786, 'two minutes to traverse the park', 'n. 横贯, 横断, 横木, 障碍, 否认, 反驳, (建筑)通廊', '/\'trævəs, -və:s, trə\'və:s, træ- | \'trævəs; trə\'vɜːs | trə\'vɝs/', 'traverse', 6);
INSERT INTO `words` VALUES (17787, NULL, 'n. 滑稽的转写, 漫画, 滑稽模仿', '/\'trævisti | \'trævɪstɪ | \'trævəsti/', 'travesty', 6);
INSERT INTO `words` VALUES (17788, 'The oil industry uses supercomputers to trawl seismic data before drilling wells.', 'n. [渔] 拖网', '/trɔ:l | trɔːl | trɔl/', 'trawl', 6);
INSERT INTO `words` VALUES (17789, 'a sly and treacherous woman', 'adj. 背叛的, 背信弃义的, 奸诈的, 叛逆的', '/\'tretʃərəs | \'tretʃ(ə)rəs | \'trɛtʃərəs/', 'treacherous', 6);
INSERT INTO `words` VALUES (17790, 'the treachery of those who plotted against the king', 'n. 背叛, 背信弃义, 变节, 叛逆行为', '/\'tretʃəri | \'tretʃ(ə)rɪ | \'trɛtʃəri/', 'treachery', 6);
INSERT INTO `words` VALUES (17791, NULL, 'n. 糖蜜, 甜蜜, 过分甜蜜的声调', '/\'tri:kl | \'triːk(ə)l/', 'treacle', 6);
INSERT INTO `words` VALUES (17792, 'If I wanted to keep my job, I knew I’d have to tread lightly.', 'v. 踏，践踏；行走; n. 步态； 车轮胎面', '/tred | trɛd/', 'tread', 6);
INSERT INTO `words` VALUES (17793, 'the treadmill of working in the office', 'n. 踏车, 单调的工作', '/\'tredmil | \'tredmɪl | \'trɛdmɪl/', 'treadmill', 6);
INSERT INTO `words` VALUES (17794, 'The defendant was convicted of high treason (= treason of the worst kind ) and sentenced to death.', 'n. 叛逆, 通敌, 背信, 叛国罪', '/\'tri:zən | \'triːz(ə)n | \'trizn/', 'treason', 6);
INSERT INTO `words` VALUES (17795, '...Locke\'s Treatise on Civil Government.', 'n. 论文, 论述', '/\'tri:tiz, -tis | \'triːtɪs; -ɪz | \'tritɪs/', 'treatise', 6);
INSERT INTO `words` VALUES (17796, 'Both sides have agreed to sign the treaty .', 'n. 条约； 协议', '/\'triːti | \'triti/', 'treaty', 6);
INSERT INTO `words` VALUES (17797, '...trekking through the jungles.', 'v. 牛拉车, 艰苦跋涉', '/trek | trɛk/', 'trek', 6);
INSERT INTO `words` VALUES (17798, 'Suddenly, there was a tremendous bang, and the whole station shook.', 'adj. 极大的, 巨大的', '/trɪ\'mendəs | trə\'mɛndəs/', 'tremendous', 6);
INSERT INTO `words` VALUES (17799, 'News of 160 lay-offs had sent tremors through the community.', 'n. 震动, 颤动', '/\'tremə | \'trɛmɚ/', 'tremor', 6);
INSERT INTO `words` VALUES (17800, 'a tremulous voice', 'adj. 震颤的', '/\'temjuləs | \'tremjʊləs | \'trɛmjələs/', 'tremulous', 6);
INSERT INTO `words` VALUES (17801, 'Workers dug a trench for gas lines.', 'n. 沟渠, 堑壕, 管沟, 电缆沟, 战壕', '/trentʃ | tren(t)ʃ | trɛntʃ/', 'trench', 6);
INSERT INTO `words` VALUES (17802, 'Stockman became one of the President’s most trenchant critics.', 'adj. 锋利的', '/\'trentʃənt | \'tren(t)ʃ(ə)nt | \'trɛntʃənt/', 'trenchant', 6);
INSERT INTO `words` VALUES (17803, 'The current trend is towards more part-time employment.', 'n. 倾向, 趋势', '/trend | trɛnd/', 'trend', 6);
INSERT INTO `words` VALUES (17804, 'With the unique combination, we underscore our position as a trendsetter in automation systems and bring this business into a new dimension, \" said Klaus Kleinfeld, President and CEO of Siemens AG.\"', 'n. 引领新潮的人', '/\'trendsetər | \'trɛndsɛtɚ/', 'trendsetter', 6);
