INSERT INTO `words` VALUES (17807, 'If those youths trespass on my land again, I shall be ready for them.', 'n. 过失, 罪过, 侵入', '/\'trespəs, -pæs | \'trespəs | \'trɛspəs/', 'trespass', 6);
INSERT INTO `words` VALUES (17808, 'The trial is due to start next week.', 'n. 试验, 考验, 审讯, 审判', '/\'traiəl | \'traɪəl/', 'trial', 6);
INSERT INTO `words` VALUES (17809, 'a tribal dance', 'adj. 部落的， 部族的', '/\'traɪbl/', 'tribal', 6);
INSERT INTO `words` VALUES (17810, 'Even close friends were unaware of the tribulations she faced.', 'n. 苦难, 忧患, 磨难', '/,tribju\'leiʃən | ,trɪbjʊ\'leɪʃ(ə)n | ,trɪbju\'leʃən/', 'tribulation', 6);
INSERT INTO `words` VALUES (17811, 'The case of your redundancy will be heard by an independent tribunal.', 'n. 法官席, 审判员席, (特等)法庭', '/trai\'bju:nəl, tri- | traɪ\'bjuːn(ə)l; trɪ- | traɪ\'bjunl/', 'tribunal', 6);
INSERT INTO `words` VALUES (17812, '...the Napo river, a tributary of the Amazon.', 'adj. 进贡的, 附庸的, 从属的, 辅助的, 支流的', '/\'tribjutəri | \'trɪbjʊt(ə)rɪ | \'trɪbjə\'tɛri/', 'tributary', 6);
INSERT INTO `words` VALUES (17813, 'The players wore black armbands as a tribute to their late teammate.', 'n. 贡品, 礼物, 颂词, 殷勤, 贡物', '/\'trɪbjuːt | \'trɪbjut/', 'tribute', 6);
INSERT INTO `words` VALUES (17814, 'He should be here in a trice.', 'n. 一刹那', '/trais | traɪs/', 'trice', 6);
INSERT INTO `words` VALUES (17815, 'Yet there is no cheating involved in any of the photographs. No steel rods, no magnets, no computer trickery. The only glue he uses is Nature\'s. Gravity.', 'n. 欺骗', '/\'trikəri | \'trɪk(ə)rɪ | \'trɪkəri/', 'trickery', 6);
INSERT INTO `words` VALUES (17816, 'A tear trickled down the old man\'s cheek.', 'v. 滴流', '/\'trikl | \'trɪk(ə)l | \'trɪkl/', 'trickle', 6);
INSERT INTO `words` VALUES (17817, 'If you know what their voice normally sounds like, and when they answer a tricky question their voice sounds higher than usual, something may be amiss.', 'adj. 狡猾的', '/\'trɪki | \'triki/', 'tricky', 6);
INSERT INTO `words` VALUES (17818, 'There’s no point in arguing over trifles.', 'n. 琐事, 少量, 蛋糕, 小事', '/\'traifl | \'traɪf(ə)l | \'traɪfl/', 'trifle', 6);
INSERT INTO `words` VALUES (17819, NULL, 'adj. 潇洒的', '/triɡ | trɪg/', 'trig', 6);
INSERT INTO `words` VALUES (17820, 'The assassination triggered off a wave of rioting.', 'v. 引发, 引起, 触发', '/\'triɡə | \'trɪgə | \'trɪɡɚ/', 'trigger', 6);
INSERT INTO `words` VALUES (17821, 'part 2 of a trilogy', 'n. 三部曲', '/\'trɪlədʒi/', 'trilogy', 6);
INSERT INTO `words` VALUES (17822, 'trim suburban gardens', 'adj. 整齐的, 整洁的', '/trim | trɪm/', 'trim', 6);
INSERT INTO `words` VALUES (17823, NULL, 'n. 小装饰品, 琐物,无关紧要的小事', '/\'triŋkit | \'trɪŋkɪt/', 'trinket', 6);
INSERT INTO `words` VALUES (17824, NULL, 'adj. <法>悲哀的', '/triːst | tri:st/', 'triste', 6);
INSERT INTO `words` VALUES (17825, 'Her remarks sounded trite and ill-informed.', 'adj. 陈腐的', '/trait | traɪt/', 'trite', 6);
INSERT INTO `words` VALUES (17826, NULL, 'vt. 弄成粉, 粉碎, 磨碎, 捣碎', '/\'trɪtjʊreɪt | \'tʃətjʊəret/', 'triturate', 6);
INSERT INTO `words` VALUES (17827, 'All her life, Kelly had stuck with difficult tasks and challenges, and triumphed.', 'v. 成功， 获胜; n. 成功，胜利', '/\'traɪʌmf | ˈtraɪəmf/', 'triumph', 6);
INSERT INTO `words` VALUES (17828, 'meaningless trivia', 'n. 琐事', '/\'triviə | \'trɪvɪə/', 'trivia', 6);
INSERT INTO `words` VALUES (17829, 'a trivial sum', 'adj. 琐细的, 价值不高的, 微不足道的', '/\'triviəl | \'trɪvɪəl/', 'trivial', 6);
INSERT INTO `words` VALUES (17830, NULL, 'n. 穴居人, 隐居者,老顽固,类人猿', '/\'trɔɡlədait | \'trɒglədaɪt/', 'troglodyte', 6);
INSERT INTO `words` VALUES (17831, 'Ships towing huge magnets trolled the ocean floor.', 'v. 用曳绳钓； 拖钓； 兴高采烈地唱', '/troul | trol/', 'troll', 6);
INSERT INTO `words` VALUES (17832, 'the trophic levels of a food chain', 'adj. 营养的, 有关营养的', '/\'trɔfik, \'trəu- | \'trəʊfɪk; \'trɒfɪk | \'trofɪk/', 'trophic', 6);
INSERT INTO `words` VALUES (17833, 'A lion’s head was among the trophies of his African trip.', 'n. 战利品, 奖品', '/\'trəufi | \'trəʊfɪ | trofɪ/', 'trophy', 6);
INSERT INTO `words` VALUES (17834, 'She came trotting down the steps from the library.', 'v. (使)小跑, (使)快步走, 骑马小跑, 疾走', '/trɔt | trɒt | trɑt/', 'trot', 6);
INSERT INTO `words` VALUES (17835, 'We were trounced 13-0.', 'v. 痛击', '/trauns | traʊns/', 'trounce', 6);
INSERT INTO `words` VALUES (17836, '...troupes of travelling actors.', 'n. 剧团', '/tru:p | truːp | trʊp/', 'troupe', 6);
INSERT INTO `words` VALUES (17837, NULL, 'n. <法>意外收获', NULL, 'trouvaille', 6);
INSERT INTO `words` VALUES (17838, NULL, 'n. 泥铲, 移植泥刀', '/\'trauəl | \'traʊəl/', 'trowel', 6);
INSERT INTO `words` VALUES (17839, 'the school’s truancy rate', 'n. 逃避', '/\'tru:ənsi | \'truːənsɪ | \'truənsi/', 'truancy', 6);
INSERT INTO `words` VALUES (17840, 'persistent truants', 'adj. 逃避责任的; n. 逃学者； 逃避者， 玩忽职守者', '/\'truːənt | \'tru:ənt/', 'truant', 6);
INSERT INTO `words` VALUES (17841, 'They agreed to call a truce .', 'n. 休战, 休战协定, 休止', '/tru:s | truːs/', 'truce', 6);
INSERT INTO `words` VALUES (17842, NULL, 'n. 野蛮, 粗野, 残酷, 好战, 致命性', '/\'trʌkjuləns, \'tru:-/', 'truculence', 6);
INSERT INTO `words` VALUES (17843, 'a truculent attitude', 'adj. 好战凶猛的', '/\'trʌkjulənt, \'tru:- | \'trʌkjʊl(ə)nt | \'trʊkjʊlənt/', 'truculent', 6);
INSERT INTO `words` VALUES (17844, 'Bent double, like old beggars under sacks Knock-kneed, coughing like hags, we cursed through sludge Till on the haunting flares we turned our backs And towards our distant rest began to trudge.', 'v. 跋涉', '/trʌdʒ/', 'trudge', 6);
INSERT INTO `words` VALUES (17845, 'And trust in rising home value as a truism as reliable as a sunrise was a major contributor to the catastrophic collapse of the economy.', 'n. 真实性', '/\'tru:izəm | \'truːɪz(ə)m/', 'truism', 6);
INSERT INTO `words` VALUES (17846, NULL, 'n. 零星杂物,中看不中用的东西没有价值的东西', '/\'trʌmpəri | \'trʌmp(ə)rɪ/', 'trumpery', 6);
INSERT INTO `words` VALUES (17847, 'If the list is too long, it will be truncated by the computer.', 'v. 截短， 缩短', '/\'trʌŋkeɪt | trʌŋ\'ket/', 'truncate', 6);
INSERT INTO `words` VALUES (17848, 'He left his bicycle leaning against a tree trunk .', 'n. 干线, 树干, 躯干, 箱子, 主干, 象鼻', '/trʌŋk/', 'trunk', 6);
INSERT INTO `words` VALUES (17849, 'He is a trustworthy and level-headed leader.', 'adj. 值得信赖的， 可靠的', '/\'trʌstwɜːrði | \'trʌstwɝði/', 'trustworthy', 6);
INSERT INTO `words` VALUES (17850, 'She lay back in the tub.', 'n. 浴盆', '/tʌb/', 'tub', 6);
INSERT INTO `words` VALUES (17851, NULL, 'adj. 桶状的, 肥胖的', '/\'tʌbiʃ/', 'tubbish', 6);
INSERT INTO `words` VALUES (17852, NULL, 'n. [植]块茎, 突起, [解]结节', '/\'tju:bə | \'tjuːbə | \'tʊbɚ/', 'tuber', 6);
INSERT INTO `words` VALUES (17853, 'the school tuck shop', 'n. 缝摺, 活力, 鼓声, 船尾突出部下方, 食物(尤指点心、蛋糕)', '/tʌk/', 'tuck', 6);
INSERT INTO `words` VALUES (17854, 'Further up the coast in Ofunato, the port’s tugboat still sits in someone’s backyard about a kilometer from the water.', 'n. 拖船, 拖轮', '/\'tʌɡbəut | \'tʌɡbəʊt | \'tʌg,bot/', 'tugboat', 6);
INSERT INTO `words` VALUES (17855, 'Oil prices have tumbled.', 'v. 突然跌倒， 突然下跌； 倒塌', '/\'tʌmbl/', 'tumble', 6);
INSERT INTO `words` VALUES (17856, 'Schoolboy how pouch of purify black, tumid ?', 'adj. 肿胀的, 肿大的', '/\'tju:mid | \'tjuːmɪd/', 'tumid', 6);
INSERT INTO `words` VALUES (17857, 'I could simply not be heard in the tumult.', 'n. 喧哗， 吵闹； 骚动， 骚乱', '/\'tuːmʌlt | \'tumʌlt/', 'tumult', 6);
INSERT INTO `words` VALUES (17858, 'He received a tumultuous welcome.', 'adj. 喧嚣的', '/tju:\'mʌltjuəs, -tʃuəs | tjʊ\'mʌltjʊəs | tu\'mʌltʃuəs/', 'tumultuous', 6);
INSERT INTO `words` VALUES (17859, 'Inside this directory are many tunable settings.', 'adj. 可调的', '/\'tjuːnəbl | \'tjʊnəbl/', 'tunable', 6);
INSERT INTO `words` VALUES (17860, NULL, 'adj. 混浊的, 不纯的, 脏的, 混乱的, 雾重的', '/\'tə:bid | \'tɜːbɪd | \'tɝbɪd/', 'turbid', 6);
INSERT INTO `words` VALUES (17861, 'the dark turbulent waters of the river', 'adj. 狂暴的, 吵闹的', '/\'tɜːbjʊl(ə)nt | \'tɝbjələnt/', 'turbulent', 6);
INSERT INTO `words` VALUES (17862, 'a turgid Social Science textbook', 'adj. 肿的, 浮夸的', '/\'tə:dʒid | \'tɜːdʒɪd | \'tɝdʒɪd/', 'turgid', 6);
INSERT INTO `words` VALUES (17863, 'She lived through the turmoil of the French Revolution.', 'n. 骚动, 混乱', '/\'tə:mɔil | \'tɜːmɒɪl | \'tɝmɔɪl/', 'turmoil', 6);
INSERT INTO `words` VALUES (17864, 'Casson was publicly criticized as a turncoat and a traitor.', 'n. 背叛者， 变节者', '/\'tɜːrnkout | \'tɝnkot/', 'turncoat', 6);
INSERT INTO `words` VALUES (17865, 'Let every declamation turn upon the beauty of liberty and virtue, and the deformity, turpitude, and malignity of slavery and vice.', 'n. 奸恶, 卑鄙', '/\'tə:pitju:d | \'tɜːpɪtjuːd | \'tɝpətud/', 'turpitude', 6);
INSERT INTO `words` VALUES (17866, 'turquoise earrings', 'n. [矿]绿宝石, 绿松石色, 青绿色', '/\'tə:kwɔiz, -kwɑ:z | \'tɜːkwɒɪz; -kwɑːz | \'tɝkwɔɪz/', 'turquoise', 6);
INSERT INTO `words` VALUES (17867, NULL, 'n. 小塔, 塔楼, 炮塔', '/\'tʌrit, \'tə:-, \'tuə- | \'tʌrɪt | ˈtərɪt/', 'turret', 6);
INSERT INTO `words` VALUES (17868, 'A huge tusk decorated the wall of his study.', 'n. 长牙, 獠牙, 尖牙', '/tʌsk/', 'tusk', 6);
INSERT INTO `words` VALUES (17869, 'his defeat in the leadership tussle', 'n. 格斗, 斗争, 争斗', '/\'tʌsl | \'tʌs(ə)l/', 'tussle', 6);
INSERT INTO `words` VALUES (17870, 'parental tutelage', 'n. 监护', '/\'tju:tilidʒ | \'tjuːtɪlɪdʒ | \'tʊtəlɪdʒ/', 'tutelage', 6);
INSERT INTO `words` VALUES (17871, NULL, 'n. 守护神, 守护圣徒', '/\'tju:tiləri | \'tjuːtɪlərɪ/', 'tutelary', 6);
INSERT INTO `words` VALUES (17872, 'He was privately tutored.', 'v. 辅导， 指导; n. 助教；导师，辅导教师；监护人', '/\'tuːtər | \'tʊtɚ/', 'tutor', 6);
INSERT INTO `words` VALUES (17873, NULL, 'n. 男士无尾半正式晚礼服', '/tʌk\'si:du | tʌk\'siːdəʊ | tʌk\'sido/', 'tuxedo', 6);
INSERT INTO `words` VALUES (17874, 'I don’t believe in all that twaddle about fate.', 'n. 废话, 闲聊', '/\'twɔdl | \'twɒd(ə)l | \'twɑdl/', 'twaddle', 6);
INSERT INTO `words` VALUES (17875, 'She leant forward and tweaked both ends of his moustache.', 'v. 扭， 拧， 揪； 调节， 微调', '/twiːk | twik/', 'tweak', 6);
INSERT INTO `words` VALUES (17876, 'She produced twee little flower paintings.', 'adj. 矫饰的, 可爱的', '/twi: | twiː | twi/', 'twee', 6);
INSERT INTO `words` VALUES (17877, 'There is the bird, sitting on a twig halfway up the tree.', 'n. 嫩枝, 小枝, 末梢', '/twiɡ | twɪg | twɪɡ/', 'twig', 6);
INSERT INTO `words` VALUES (17878, 'I felt a twinge of pain in my back.', 'n. 一阵一阵痛, 如刺一样痛, 剧痛', '/twindʒ | twɪn(d)ʒ | twɪndʒ/', 'twinge', 6);
INSERT INTO `words` VALUES (17879, 'Bonnie twirled her empty glass in her fingers.', 'v. (使)快速转动, 捻弄', '/twə:l | twɜːl | twɝl/', 'twirl', 6);
INSERT INTO `words` VALUES (17880, NULL, 'v. 嘲笑', '/twit | twɪt/', 'twit', 6);
INSERT INTO `words` VALUES (17881, '...a self-made Irish-American property tycoon.', 'n. 企业界大亨, 将军', '/tai\'ku:n | taɪ\'kuːn | taɪ\'kun/', 'tycoon', 6);
INSERT INTO `words` VALUES (17882, 'a sudden outbreak of typhoid', 'n. [医]伤寒症', '/\'taifɔid | \'taɪfɒɪd | \'taɪfɔɪd/', 'typhoid', 6);
INSERT INTO `words` VALUES (17883, 'They have received notice of a typhoon approaching.', 'n. 台风', '/taɪ\'fuːn | taɪ\'fʊn/', 'typhoon', 6);
INSERT INTO `words` VALUES (17884, 'the features which typify a Scottish Highland landscape', 'v. 代表， 是…的典型', '/\'tɪpɪfɑɪ | \'tɪpɪfaɪ/', 'typify', 6);
INSERT INTO `words` VALUES (17885, 'Because of a typographical error, the town of Longridge was spelt as Longbridge.', 'adj. 印刷上的', '/taɪ\'pɑːgrəfikl | taɪpə\'græfɪkl/', 'typographical', 6);
INSERT INTO `words` VALUES (17886, 'This is why display cases are rarely found in the world of digital typography, whereas they were once common in letterpress printing.', 'n. 凸版印刷术, 排印印刷样式', '/tai\'pɔɡrəfi | taɪ\'pɒgrəfɪ | taɪ\'pɑgrəfi/', 'typography', 6);
INSERT INTO `words` VALUES (17887, 'a tyrannical parent', 'adj. 残暴的', '/ti\'rænikəl, tai- | tɪ\'rænɪk(ə)l; taɪ- | tɪ\'rænɪkl/', 'tyrannical', 6);
INSERT INTO `words` VALUES (17888, 'Gorky was often the victim of his grandfather’s tyranny.', 'n. 暴政， 专制统治； 暴行', '/\'tɪrəni/', 'tyranny', 6);
INSERT INTO `words` VALUES (17889, 'The country had long been ruled by tyrants.', 'n. 暴君', '/\'tairənt | \'taɪr(ə)nt | \'taɪrənt/', 'tyrant', 6);
INSERT INTO `words` VALUES (17890, 'The scrutiny of investors, directors, regulators and media, may find out these tyro corporate leaders before they can do much damage.', 'n. 生手, 初学者, 新手', '/\'taiərəu | \'taɪrəʊ | \'taɪro/', 'tyro', 6);
INSERT INTO `words` VALUES (17891, 'Coffee shops are ubiquitous these days.', 'adj. 到处存在的, (同时)普遍存在的', '/ju:\'bikwitəs | juː\'bɪkwɪtəs | ju\'bɪkwɪtəs/', 'ubiquitous', 6);
INSERT INTO `words` VALUES (17892, 'a very ugly man', 'adj. 难看的； 令人不快的', '/\'ʌgli | \'ʌɡli/', 'ugly', 6);
INSERT INTO `words` VALUES (17893, 'stomach ulcers', 'n. 溃疡, 腐烂物', '/\'ʌlsə | \'ʌlsɚ/', 'ulcer', 6);
INSERT INTO `words` VALUES (17894, 'In advanced stages the opaque corneas may ulcerate and even perforate.', 'v. 溃烂', '/\'ʌlsəreit | \'ʌlsəreɪt | \'ʌlsəret/', 'ulcerate', 6);
INSERT INTO `words` VALUES (17895, 'He’s just being nice. I don’t think he has any ulterior motives.', 'adj. 在那边的, 较远的, 将来的, 隐蔽的', '/ʌl\'tiəriə | ʌl\'tɪərɪə | ʌl\'tɪrɪɚ/', 'ulterior', 6);
INSERT INTO `words` VALUES (17896, 'The ultimate outcome of the experiment cannot be predicted.', 'adj. 最后的, 最终的, 根本的', '/\'ʌltimət | \'ʌltɪmət | \'ʌltəmət/', 'ultimate', 6);
INSERT INTO `words` VALUES (17897, 'Ultimately, the decision rests with the child’s parents.', 'adv. 最后， 终于', '/\'ʌltɪmətli | \'ʌltəmɪtlɪ/', 'ultimately', 6);
INSERT INTO `words` VALUES (17898, 'The club gave him an ultimatum – either he apologized, or he would be expelled from the team.', 'n. 最后通牒', '/ˌʌltɪ\'meɪtəm | ,ʌltɪ\'metəm/', 'ultimatum', 6);
INSERT INTO `words` VALUES (17899, NULL, 'adj. 世界之外的,太阳系之外的,超俗的', '/,ʌltrə\'mʌndeɪn | ,ʌltrə\'mʌnden/', 'ultramundane', 6);
INSERT INTO `words` VALUES (17900, 'The construct, driving principle and output performances of the cylinder type ultrasonic motor with multi-degree of freedom were presented.', 'adj. 超音速的， 超声的', '/ˌʌltrə\'sɑːnɪk | ,ʌltrə\'sɑnɪk/', 'ultrasonic', 6);
INSERT INTO `words` VALUES (17901, 'The answers were kept confidential to prevent any partners taking umbrage.', 'n. 树荫, 不快', '/\'ʌmbridʒ | \'ʌmbrɪdʒ/', 'umbrage', 6);
INSERT INTO `words` VALUES (17902, 'The umpire\'s decision is final.', 'n. 仲裁人, 裁判员', '/\'ʌmpaiə | \'ʌmpaɪə | \'ʌmpaɪɚ/', 'umpire', 6);
INSERT INTO `words` VALUES (17903, 'I couldn\'t go beyond the doorway; that doorway that my father had told us umpteen times was the doorway of love. He had first glimpsed my mother through this door and fallen in love with her.', 'adj. 无数的', '/,ʌmp\'ti:n | ʌm(p)\'tiːn; \'ʌm(p)tiːn | ,ʌmp\'tin/', 'umpteen', 6);
INSERT INTO `words` VALUES (17904, 'She stared at him with unabashed curiosity.', 'adj. 不害羞的', '/,ʌnə\'bæʃt | ʌnə\'bæʃt/', 'unabashed', 6);
INSERT INTO `words` VALUES (17905, 'They liked their churches to be unadorned.', 'adj. 未装饰的， 朴素的', '/ˌʌnə\'dɔːrnd | \'ʌnə\'dɔ:nd/', 'unadorned', 6);
INSERT INTO `words` VALUES (17906, NULL, 'adj. 欠思虑的, 轻率的, 未曾受到劝告的', '/,ʌnəd\'vaizd | ,ʌnəd\'vaɪzd/', 'unadvised', 6);
INSERT INTO `words` VALUES (17907, 'Before this, she was called \"the hairy angel\" due to her thick bushy eyebrows and a flock of unaesthetic curly hair.', 'adj. 无美感的', '/,ʌni:s\'θetik | ˌʌnəs\'θetɪk/', 'unaesthetic', 6);
INSERT INTO `words` VALUES (17908, 'her easy unaffected manner', 'adj. 不矫揉造作的, 自然的, 真挚的, 未受影响的, 未被感动的', '/,ʌnə\'fektid | ʌnə\'fektɪd | ,ʌnə\'fɛktɪd/', 'unaffected', 6);
INSERT INTO `words` VALUES (17909, 'unalloyed joy', 'adj. 纯粹的', '/,ʌnə\'lɔid | ʌnə\'lɒɪd | ,ʌnə\'lɔɪd/', 'unalloyed', 6);
INSERT INTO `words` VALUES (17910, 'an unalterable fact', 'adj. 不能改变的', '/ʌn\'ɔːltərəbl | ʌn\'ɔltərəbl/', 'unalterable', 6);
INSERT INTO `words` VALUES (17911, 'It was decided by a unanimous vote that the school should close.', 'adj. 意见一致的, 无异议的', '/ju:\'næniməs | juː\'nænɪməs | jʊ\'nænəməs/', 'unanimous', 6);
INSERT INTO `words` VALUES (17912, 'To express certain emotions, especially mirth, delight, or derision, by a series of spontaneous, usually unarticulated sounds often accompanied by corresponding facial and bodily movements.', 'adj. 表达不清的', '/ˌʌnɑːr\'tɪkjələtɪd/', 'unarticulated', 6);
INSERT INTO `words` VALUES (17913, 'He\'s a man of few words, very polite and unassuming.', 'adj. 谦逊的, 不装腔作势的', '/,ʌnə\'sju:miŋ | ʌnə\'sjuːmɪŋ | \'ʌnə\'sʊmɪŋ/', 'unassuming', 6);
INSERT INTO `words` VALUES (17914, 'unavailing efforts to make her happy', 'adj. 无效的', '/,ʌnə\'veiliŋ | ʌnə\'veɪlɪŋ | ,ʌnə\'velɪŋ/', 'unavailing', 6);
INSERT INTO `words` VALUES (17915, 'There are now fears that war is unavoidable.', 'adj. 不可避免的', '/ˌʌnə\'vɔɪdəbl | ,ʌnə\'vɔɪdəbl/', 'unavoidable', 6);
INSERT INTO `words` VALUES (17916, 'We had walked unawares over the border.', 'adv. 不料, 不知不觉地', '/,ʌnə\'wεəz | ʌnə\'weəz | ,ʌnə\'wɛrz/', 'unawares', 6);
INSERT INTO `words` VALUES (17917, 'Austin displayed conduct unbecoming of an officer and a gentleman.', 'adj. 不合身的', '/,ʌnbi\'kʌmiŋ | ʌnbɪ\'kʌmɪŋ | ,ʌnbɪ\'kʌmɪŋ/', 'unbecoming', 6);
INSERT INTO `words` VALUES (17918, 'In her dying days the old queen unbent a little.', 'v. 变直； 轻松行事， 放松', '/ˌʌn\'bend | ,ʌn\'bɛnd/', 'unbend', 6);
INSERT INTO `words` VALUES (17919, 'We aim to provide a service that is balanced and unbiased.', 'adj. 没有偏见的', '/ʌn\'baɪəst/', 'unbiased', 6);
INSERT INTO `words` VALUES (17920, NULL, 'adj. 未受邀请的', '/ʌn\'bɪd(ə)n | ʌn\'bɪdn/', 'unbidden', 6);
INSERT INTO `words` VALUES (17921, NULL, 'adj. 未上栓的', '/,ʌn\'bəultid | ʌn\'bəʊltɪd | ʌn\'boltɪd/', 'unbolted', 6);
INSERT INTO `words` VALUES (17922, 'When isolating, she can follow grandpa unbosom, two people have dance lightly on ball even.', 'v. 倾诉， 吐露', '/ʌn\'buzəm | ʌn\'bʊzəm/', 'unbosom', 6);
INSERT INTO `words` VALUES (17923, '...the so-called unbridgeable gap between the world of humans and that of chimpanzees.', 'adj. 不能架桥的， 不能逾越的', '/\'ʌn\'bridʒəbl | ʌn\'brɪdʒəbl/', 'unbridgeable', 6);
INSERT INTO `words` VALUES (17924, 'unbridled greed', 'adj. 放纵的， 不受约束的', '/ʌn\'braɪdld/', 'unbridled', 6);
INSERT INTO `words` VALUES (17925, 'their unbroken record of success', 'adj. 完整的； 连续的', '/ʌn\'broukən | ʌn\'brokən/', 'unbroken', 6);
INSERT INTO `words` VALUES (17926, 'an uncanny coincidence', 'adj. 离奇的', '/,ʌn\'kæni | ʌn\'kænɪ | ʌn\'kæni/', 'uncanny', 6);
INSERT INTO `words` VALUES (17927, NULL, 'adj. 无慈悲心的', '/ʌn\'tʃærɪtəbl | ,ʌn\'tʃæritəbl/', 'uncharitable', 6);
INSERT INTO `words` VALUES (17928, 'an uncharted island', 'adj. 海图上未标明的, 未知的, 不详的', '/,ʌn\'tʃɑ:tid | ʌn\'tʃɑːtɪd | ,ʌn\'tʃɑrtɪd/', 'uncharted', 6);
INSERT INTO `words` VALUES (17929, 'She bore no clothing upon her body thus in this unclad state she could be seen to be dark green of complexion.', 'adj. 赤裸裸的, 没穿衣服的', '/,ʌn\'klæd | ʌn\'klæd/', 'unclad', 6);
INSERT INTO `words` VALUES (17930, 'uncommitted voters', 'adj. 不受约束的， 不承担责任的', '/ˌʌnkə\'mɪtɪd | \'ʌnkə\'mɪtɪd/', 'uncommitted', 6);
INSERT INTO `words` VALUES (17931, 'My daughter is very difficult, uncommunicative and moody.', 'adj. 不爱说话的， 拘谨的', '/ˌʌnkə\'mjuːnɪkətɪv | \'ʌnkə\'mjʊnəkətɪv/', 'uncommunicative', 6);
INSERT INTO `words` VALUES (17932, 'an uncompromising opponent of democratic reform', 'adj. 不妥协的', '/ʌn\'kɑːmprəmaɪzɪŋ | ʌn\'kɑmprəmaɪzɪŋ/', 'uncompromising', 6);
INSERT INTO `words` VALUES (17933, 'We’ve received unconfirmed reports of an explosion in central London.', 'adj. 未经证实的', '/ˌʌnkən\'fɜːrmd | ,ʌnkən\'fɝmd/', 'unconfirmed', 6);
INSERT INTO `words` VALUES (17934, 'The war caused an unconscionable amount of suffering.', 'adj. 不合理的, 不受良心节制的, 过度的', '/,ʌn\'kɔnʃənəbl | ʌn\'kɒnʃ(ə)nəb(ə)l | ʌn\'kɑnʃənəbl/', 'unconscionable', 6);
INSERT INTO `words` VALUES (17935, 'She was found alive but unconscious.', 'adj. 不省人事的； 未发觉的， 无意识的', '/ʌn\'kɑːnʃəs | ʌn\'kɑnʃəs/', 'unconscious', 6);
INSERT INTO `words` VALUES (17936, NULL, 'adj. 未引起争论的', '/ʌn,kantrə\'və:ʃəl; | ˌʌnkɑːntrə\'vɜːrʃl/', 'uncontroversial', 6);
INSERT INTO `words` VALUES (17937, 'I remain unconvinced that the idea will work.', 'adj. 不信服的', '/\'ʌnkən\'vinst | ˌʌnkən\'vɪnst/', 'unconvinced', 6);
INSERT INTO `words` VALUES (17938, 'The article says that this could be because women can ‘better appreciate the thought and expense’ that goes into buying and wrapping chocolates than the uncouth men who wolf them down.', 'adj. 笨拙的, 粗俗的, 不舒适的', '/,ʌn\'ku:θ | ʌn\'kuːθ | ʌn\'kʊθ/', 'uncouth', 6);
INSERT INTO `words` VALUES (17939, NULL, 'adj. 油似的, 油质的, 松软肥沃的', '/\'ʌŋktjuəs | \'ʌŋ(k)tjʊəs | \'ʌŋktʃuəs/', 'unctuous', 6);
INSERT INTO `words` VALUES (17940, 'But for those undaunted, here\'s our guide to circumventing internet censorship.', 'adj. 大无畏的, 勇敢的', '/,ʌn\'dɔ:ntid | ʌn\'dɔːntɪd | ,ʌn\'dɔntɪd/', 'undaunted', 6);
INSERT INTO `words` VALUES (17941, NULL, 'adj. 难破译的', '/\'ʌndi\'saifərəbl | ˌʌndɪ\'saɪfrəbl/', 'undecipherable', 6);
INSERT INTO `words` VALUES (17942, 'Over a tenth of the population have secure, undemanding jobs.', 'adj. 不严格的； 要求不高的', '/ˌʌndɪ\'mɑːndɪŋ | \'ʌndɪ\'mɑndɪŋ/', 'undemanding', 6);
INSERT INTO `words` VALUES (17943, NULL, 'adj. 无法证明的， 难以证明的', '/,ʌndi\'mɔnstrəbl | ˌʌndɪ\'mɑːnstrəbl/', 'undemonstrable', 6);
INSERT INTO `words` VALUES (17944, NULL, 'n. 缺乏, 久缺', '/,ʌndə\'eidʒ | \'ʌndər,eɪdʒ | \'ʌndəredʒ/', 'underage', 6);
INSERT INTO `words` VALUES (17945, 'Irena underbid the other dealers.', 'v. 叫价低于； 要价过低', '/ˌʌndər\'bɪd | ,ʌndɚ\'bɪd/', 'underbid', 6);
INSERT INTO `words` VALUES (17946, NULL, 'v. 削价抢生意', '/ˌʌndər\'kʌt | ,ʌndɚ\'kʌt/', 'undercut', 6);
INSERT INTO `words` VALUES (17947, 'a baby born with underdeveloped kidneys', 'adj. 不发达的', '/ˌʌndərdɪ\'veləpt | ,ʌndɚdɪ\'vɛləpt/', 'underdeveloped', 6);
INSERT INTO `words` VALUES (17948, 'Crowds often feel sympathy for the underdog.', 'n. 居于下风者； 受欺负者， 受欺压者', '/\'ʌndərdɑːg | \'ʌndɚdɔɡ/', 'underdog', 6);
INSERT INTO `words` VALUES (17949, 'None of us should ever underestimate the degree of difficulty women face in career advancement.', 'v. 低估； 看轻', '/ˌʌndər\'estɪmeɪt | /ˌʌndərˈestɪmeɪt//', 'underestimate', 6);
INSERT INTO `words` VALUES (17950, 'They underestimated the enemy\'s strength.', 'adj. 低估的', '/ˌʌndər\'estɪmeɪtɪd | /ˌʌndərˈestɪmeɪt//', 'underestimated', 6);
INSERT INTO `words` VALUES (17951, NULL, 'v. 从底层支持， 加固…的底部', '/ˌʌndər\'gɜːrd | ,ʌndə\'ɡə:d/', 'undergird', 6);
INSERT INTO `words` VALUES (17952, 'This animal spends most of its life underground.', 'adv. 在地下；秘密地; adj. 地下的； 秘密的', '/ˌʌndə\'graund | ʌndɚˈɡraʊnd/', 'underground', 6);
INSERT INTO `words` VALUES (17953, '...underhand financial deals.', 'adj. 秘密的', '/\'ʌndə\'hændid | ʌndə\'hændɪd | \'ʌndɚ\'hændɪd/', 'underhanded', 6);
INSERT INTO `words` VALUES (17954, 'the one basic principle that underlies all of the party’s policies', 'v. 位于…之下； 构成…的基础； 【经】优先于', '/ˌʌndər\'laɪ | ,ʌndɚ\'laɪ/', 'underlie', 6);
INSERT INTO `words` VALUES (17955, '...underlings who do the dirty work.', 'n. 部下, 下僚, 下属, 走卒', '/\'ʌndəliŋ | \'ʌndəlɪŋ | \'ʌndɚlɪŋ/', 'underling', 6);
INSERT INTO `words` VALUES (17956, 'To stop a problem you have to understand its underlying causes.', 'adj. 在下面的； 根本的； 潜在的', '/ˌʌndər\'laɪɪŋ | ,ʌndɚ\'laɪɪŋ/', 'underlying', 6);
INSERT INTO `words` VALUES (17957, 'The continued fighting threatens to undermine efforts to negotiate an agreement.', 'v. 破坏', '/,ʌndə\'main | ʌndə\'maɪn | \'ʌndɚ\'maɪn/', 'undermine', 6);
INSERT INTO `words` VALUES (17958, 'She underplays her achievements.', 'v. 弱化…的重要性； 表演不充分', '/ˌʌndər\'pleɪ | \'ʌndɚ,kle/', 'underplay', 6);
INSERT INTO `words` VALUES (17959, 'We women have a lot of good business skills, although we tend to underrate ourselves.', 'v. 低估， 轻视', '/ˌʌndə\'reɪt | ,ʌndə\'ret/', 'underrate', 6);
INSERT INTO `words` VALUES (17960, NULL, 'adj. 未被充分代表的', '/ˌʌndəˌreprɪ\'zentɪd | \'ʌndə,repri\'zentid/', 'underrepresented', 6);
INSERT INTO `words` VALUES (17961, 'The Labour Department figures underscore the shaky state of the economic recovery.', 'v. 在…下面画线； 强调', '/ˌʌndər\'skɔːr | ,ʌndɚ\'skɔr/', 'underscore', 6);
INSERT INTO `words` VALUES (17962, 'The press have tended to understate the extent of the problem.', 'v. 保守地说， 轻描淡写地说', '/ˌʌndər\'steɪt | \'ʌndɚ\'stet/', 'understate', 6);
INSERT INTO `words` VALUES (17963, 'the understated elegance of the Hotel Traiano', 'adj. 轻描淡写的， 低调的', '/ˌʌndər\'steɪtɪd | ,ʌndɚ\'stetɪd/', 'understated', 6);
INSERT INTO `words` VALUES (17964, 'When the play\'s star broke her leg her understudy wept crocodile tears.', 'v. 充当…的替角; n. 预备演员，替角', '/\'ʌndərstʌdi | \'ʌndə,stʌdi/', 'understudy', 6);
INSERT INTO `words` VALUES (17965, 'She undertook the task of monitoring the elections.', 'v. 承担； 担保， 保证', '/ˌʌndər\'teɪk | ,ʌndɚ\'tek/', 'undertake', 6);
INSERT INTO `words` VALUES (17966, 'They had to sell off 10 percent of all underutilized farmland.', 'adj. 未充分利用的', '/,ʌndə\'ju:tilaizd | ˌʌndər\'juːtəlaɪzd/', 'underutilized', 6);
INSERT INTO `words` VALUES (17967, 'an underwater camera', 'adj. 在水下的， 在水中的', '/ˌʌndər\'wɔːtər | ,ʌndɚ\'wɔtɚ/', 'underwater', 6);
INSERT INTO `words` VALUES (17968, 'The government has agreed to underwrite the project with a grant of £5 million.', 'v. 同意负担…的费用； 通过保单承担', '/ˌʌndər\'raɪt | ,ʌndɚ\'raɪt/', 'underwrite', 6);
INSERT INTO `words` VALUES (17969, 'In this world, nothing was undeserving of the French soldiers!', 'adj. 不值得的', '/ˌʌndɪ\'zɜːrvɪŋ | ,ʌndɪ\'zɝvɪŋ/', 'undeserving', 6);
INSERT INTO `words` VALUES (17970, 'punishment of undesirable behaviour', 'adj. 不合需要的, 不受欢迎的, 令人不快的', '/,ʌndi\'zaiərəbl | ʌndɪ\'zaɪərəb(ə)l | ,ʌndɪ\'zaɪərəbl/', 'undesirable', 6);
INSERT INTO `words` VALUES (17971, 'shows aimed at large undifferentiated groups of people', 'adj. 无差别的， 一致的', '/ˌʌndɪfə\'renʃieɪtɪd | \'ʌndɪfə\'rɛnʃɪ\'etɪd/', 'undifferentiated', 6);
INSERT INTO `words` VALUES (17972, NULL, 'adj. 未受指导的', '/ˌʌndaɪ\'rektɪd | ,ʌndə\'rɛktɪd/', 'undirected', 6);
INSERT INTO `words` VALUES (17973, 'The name Vulcan was given to the undiscovered planet.', 'adj. 未被发现的', '/ˌʌndɪs\'kʌvərd | \'ʌndis\'kʌvəd/', 'undiscovered', 6);
INSERT INTO `words` VALUES (17974, 'But how do we know we have the true, undistorted picture of reality?', 'adj. 未失真的', '/\'ʌndis\'tɔ:tid | ˌʌndɪ\'stɔːrtɪd/', 'undistorted', 6);
INSERT INTO `words` VALUES (17975, 'At last I was able to work undisturbed.', 'adj. 未受干扰的， 安静的', '/ˌʌndɪ\'stɜːrbd | ,ʌndɪ\'stɝbd/', 'undisturbed', 6);
INSERT INTO `words` VALUES (17976, 'This temptation to cover the distance between himself and the reader, to study his image in the sight of those who do not know him, can be his undoing: he has begun to write to please.', 'n. 解开, 复旧, 毁灭, 取消', '/,ʌn\'du:iŋ | ʌn\'duːɪŋ | ʌn\'duɪŋ/', 'undoing', 6);
INSERT INTO `words` VALUES (17977, 'undulating hills', 'v. 波动, 起伏, 成波浪形', '/\'ʌndjuleit | \'ʌndjʊleɪt | \'ʌndʒə\'let/', 'undulate', 6);
INSERT INTO `words` VALUES (17978, 'Farmers still sometimes unearth human bones here.', 'v. 掘出', '/,ʌn\'ə:θ | ʌn\'ɜːθ | ʌn\'ɝθ/', 'unearth', 6);
INSERT INTO `words` VALUES (17979, 'His eyes shone with an unearthly light.', 'adj. 奇异的', '/ʌn\'ɜːrθli | ʌn\'ɝθli/', 'unearthly', 6);
INSERT INTO `words` VALUES (17980, 'Milk fabric has been around since the 1930s but was always produced in unecological ways that used a lot of chemicals.', 'adj. 非生态的', '/ˌʌniːkə\'lɑːdʒɪkl/', 'unecological', 6);
INSERT INTO `words` VALUES (17981, 'But the problem here is that this draft appears to have been canonised, passing largely unedited into popular conscience.', 'adj. 未编辑的', '/ʌn\'edɪtɪd | \'ʌn\'editid/', 'unedited', 6);
INSERT INTO `words` VALUES (17982, 'Why not travel alone , in single blessedness , unencumbered and swiftly pursuing one\'s goal?', 'adj. 无阻碍的', '/ˌʌnɪn\'kʌmbərd | ,ʌnɪn\'kʌmbɚd/', 'unencumbered', 6);
INSERT INTO `words` VALUES (17983, 'a most backward, unenlightened nation', 'adj. 愚昧无知的； 不文明的', '/ˌʌnɪn\'laɪtnd | ,ʌnɪn\'laɪtnd/', 'unenlightened', 6);
INSERT INTO `words` VALUES (17984, 'His answer was an unequivocal ‘No.’', 'adj. 毫无疑问的', '/ˌʌnɪ\'kwɪvəkl | ,ʌnɪ\'kwɪvəkl/', 'unequivocal', 6);
INSERT INTO `words` VALUES (17985, 'We described how the golden plover manages to fly over thousands of miles of uncharted water each year directly and unerringly to Hawaii.', 'adv. 无过失地', '/ʌn\'ə:riŋli | ʌn\'ɜːrɪŋlɪ/', 'unerringly', 6);
INSERT INTO `words` VALUES (17986, 'She walked back carefully over the uneven ground.', 'adj. 不平坦的； 不一致的； 不对等的', '/ʌn\'iːvn | ʌn\'ivən/', 'uneven', 6);
INSERT INTO `words` VALUES (17987, 'Annie led a quiet uneventful life.', 'adj. 平凡的； 平安无事的', '/ˌʌnɪ\'ventfl | ,ʌnɪ\'vɛntfl/', 'uneventful', 6);
INSERT INTO `words` VALUES (17988, 'Hong Band is an important part of Ningbo Band. The plentiful achievements they have made in academic research are unexampled by other groups in Ningbo Band.', 'adj. 无前例的, 无可比拟的', '/,ʌniɡ\'zɑ:mpld | ʌnɪg\'zɑːmp(ə)ld; ʌneg-/', 'unexampled', 6);
INSERT INTO `words` VALUES (17989, 'The candidate was quite unexceptionable, a well-known travel writer and TV personality.', 'adj. 无可挑剔的', '/ˌʌnɪk\'sepʃənəbl | \'ʌnɪk\'sɛpʃənəbl/', 'unexceptionable', 6);
INSERT INTO `words` VALUES (17990, 'She battled against cancer with unfailing good humour.', 'adj. 经久不衰的,无穷尽的, 可靠的', '/,ʌn\'feiliŋ | ʌn\'feɪlɪŋ | ʌn\'felɪŋ/', 'unfailing', 6);
INSERT INTO `words` VALUES (17991, 'He unfastened the top button of his shirt.', 'v. 解开', '/ʌn\'fæsn | ,ʌn\'fæsən/', 'unfasten', 6);
INSERT INTO `words` VALUES (17992, NULL, 'adj. 未探测深度的, 无法了解的, 未解决的', '/,ʌn\'fæðəmd | ʌn\'fæð(ə)md/', 'unfathomed', 6);
INSERT INTO `words` VALUES (17993, 'Her interest in people was unfeigned.', 'adj. 真实的， 真诚的', '/ʌn\'feɪnd | ʌn\'fend/', 'unfeigned', 6);
INSERT INTO `words` VALUES (17994, 'an unfertilized ovum', 'adj. 未施肥的； 未受精的', '/ʌn\'fɜːrtəlaɪzd/', 'unfertilized', 6);
INSERT INTO `words` VALUES (17995, 'unfettered economic activity', 'adj. 被除去脚镣的,无拘无束的', '/\'ʌn\'fetəd | ʌn\'fetəd | ʌn\'fɛtɚd/', 'unfettered', 6);
INSERT INTO `words` VALUES (17996, 'Donald Duck - the irascible but unflappable waterfowl - prepared to be feted in grand fashion, as he turned 75 years old Tuesday.', 'adj. 不易惊慌的, 镇定的', '/,ʌn\'flæpəbl | ʌn\'flæpəb(ə)l/', 'unflappable', 6);
INSERT INTO `words` VALUES (17997, 'As the story unfolds, we learn more about Max’s childhood.', 'v. 展开， 打开； 逐渐呈现', '/ʌn\'fould | ʌn\'fold/', 'unfold', 6);
INSERT INTO `words` VALUES (17998, 'Unfounded rumours of accounting problems hit stocks of other companies.', 'adj. 没有理由的,未建立的', '/,ʌn\'faundid | ʌn\'faʊndɪd/', 'unfounded', 6);
INSERT INTO `words` VALUES (17999, 'an unfrequented spot', 'adj. 人迹罕到的', '/,ʌnfri\'kwentid | ʌnfrɪ\'kwentɪd | ,ʌnfrɪ\'kwɛntɪd/', 'unfrequented', 6);
INSERT INTO `words` VALUES (18000, 'Once outside the inner breakwater, we began to unfurl all the sails.', 'v. 展开, 展示, 公开, 使旗招展', '/,ʌn\'fə:l | ʌn\'fɜːl | \'ʌn\'fɝl/', 'unfurl', 6);
INSERT INTO `words` VALUES (18001, 'a tall ungainly teenager', 'adj. 难看的, 不象样的, 笨拙的', '/,ʌn\'ɡeinli | ʌn\'geɪnlɪ | ʌn\'ɡenli/', 'ungainly', 6);
INSERT INTO `words` VALUES (18002, 'Don’t be so ungrateful!', 'adj. 不感激的， 不领情的', '/ʌn\'greɪtfl | ʌn\'ɡretfl/', 'ungrateful', 6);
INSERT INTO `words` VALUES (18003, 'I have received ungrudging help from several friends.', 'adj. 慷慨的； 情愿的', '/ˌʌn\'grʌdʒɪŋ | ʌn\'grʌdʒɪŋ/', 'ungrudging', 6);
INSERT INTO `words` VALUES (18004, 'The photographers managed to capture Jane in an unguarded moment.', 'adj. 没有防备的', '/,ʌn\'ɡɑ:did | ʌn\'gɑːdɪd | ʌn\'ɡɑrdɪd/', 'unguarded', 6);
INSERT INTO `words` VALUES (18005, 'Objective To explore the anti-inflammatory and analgesic action of Yantongxiao unguent.', 'n. 油膏', '/\'ʌŋɡwənt | \'ʌŋgwənt/', 'unguent', 6);
INSERT INTO `words` VALUES (18006, 'an unheralded visit from his aunt', 'adj. 未预先通知的， 未预先警告过的', '/ʌn\'herəldɪd | ʌn\'hɛrəldɪd/', 'unheralded', 6);
INSERT INTO `words` VALUES (18007, 'The reason there are so few unicorn sightings today isn\'t because they are mythical creatures that never existed, but because of modern society\'s moral depravity.', 'n. 独角兽, 麒麟', '/\'ju:nikɔ:n | \'juːnɪkɔːn | \'junɪkɔrn/', 'unicorn', 6);
INSERT INTO `words` VALUES (18008, NULL, 'adj. 一维的', '/ˌjuːnɪdaɪ\'menʃənl | ,jʊnɪdɪ\'mɛnʃənəl; ,jʊnɪdaɪ\'mɛnʃənəl/', 'unidimensional', 6);
INSERT INTO `words` VALUES (18009, '...the process of European unification.', 'n. 统一， 一致', '/ˌjuːnɪfɪ\'keɪʃn | ,jʊnəfə\'keʃən/', 'unification', 6);
INSERT INTO `words` VALUES (18010, 'Grade A eggs must be of uniform size.', 'adj. 相同的， 一致的; n. 制服', '/\'juːnɪfɔːrm | junəˌfɔrm/', 'uniform', 6);
INSERT INTO `words` VALUES (18011, 'Strong support for the war has unified the nation.', 'v. 统一， 使成一体； 使相同', '/\'juːnɪfaɪ | \'junɪfaɪ/', 'unify', 6);
INSERT INTO `words` VALUES (18012, 'a unilateral declaration of independence', 'adj. 单方面的', '/ˌjuːnɪ\'lætrəl | \'jʊnɪ\'lætərəl/', 'unilateral', 6);
INSERT INTO `words` VALUES (18013, NULL, 'adj. 没有激情的', '/ˌʌnɪm\'pæʃnd | \'ʌnim\'pæʃənd/', 'unimpassioned', 6);
INSERT INTO `words` VALUES (18014, 'unimpeachable morals', 'adj. 无懈可击的, 无可指责的, 无过失的, 无可怀疑的', '/,ʌnim\'pi:tʃəbl | ʌnɪm\'piːtʃəb(ə)l | ,ʌnɪm\'pitʃəbl/', 'unimpeachable', 6);
INSERT INTO `words` VALUES (18015, 'He was also very unimpressed by his teachers.', 'adj. 没有印象的', '/ˌʌnɪm\'prest | ,ʌnɪm\'prɛst/', 'unimpressed', 6);
INSERT INTO `words` VALUES (18016, 'For those uninitiated in scientific ocean drilling, the previous record was a little over 4 km.', 'adj. 外行的， 缺乏经验的', '/ˌʌnɪ\'nɪʃieɪtɪd | ,ʌnɪ\'nɪʃɪetɪd/', 'uninitiated', 6);
INSERT INTO `words` VALUES (18017, 'an uninspired performance', 'adj. 无灵感的， 枯燥的', '/ˌʌnɪn\'spaɪərd | ,ʌnɪn\'spaɪɚd/', 'uninspired', 6);
INSERT INTO `words` VALUES (18018, 'Eva muttered something unintelligible.', 'adj. 不可能理解的， 难懂的', '/ˌʌnɪn\'telɪdʒəbl | \'ʌnɪn\'tɛlədʒəbl/', 'unintelligible', 6);
INSERT INTO `words` VALUES (18019, 'Each person’s fingerprints are unique.', 'adj. 独一无二的， 独特的； 无与伦比的', '/ju\'niːk | jʊ\'nik/', 'unique', 6);
INSERT INTO `words` VALUES (18020, '‘Good morning!’ the kids replied in unison.', 'n. 齐奏， 齐唱； 一致， 协调', '/\'juːnɪsn | \'jʊnəsn/', 'unison', 6);
INSERT INTO `words` VALUES (18021, 'free universal healthcare', 'adj. 全体的； 普遍的', '/ˌjuːnɪ\'vɜːrsl | \'jʊnə\'vɝsl/', 'universal', 6);
INSERT INTO `words` VALUES (18022, 'Secondly, the relationship between universality and specificity.', 'n. 普遍性； 广泛性', '/ˌjuːnɪvɜːr\'sæləti | ,jʊnəvɝ\'sæləti/', 'universality', 6);
INSERT INTO `words` VALUES (18023, 'LD: We think it is best to keep questions like these partially open, that there will never be an univocal answer.', 'adj. 单一意思的', '/juː\'nɪvəkl | jʊ\'nɪvəkl/', 'univocal', 6);
INSERT INTO `words` VALUES (18024, 'Poisoning the earth’s atmosphere is ecologically and morally unjustifiable.', 'adj. 不合道理的', '/ʌn\'dʒʌstɪfaɪəbl | ʌn\'dʒʌstifaiəbl/', 'unjustifiable', 6);
INSERT INTO `words` VALUES (18025, 'His hair was unkempt and filthy.', 'adj. 蓬乱的, 粗野的, 不整洁的', '/,ʌn\'kempt | ʌn\'kem(p)t | ,ʌn\'kɛmpt/', 'unkempt', 6);
INSERT INTO `words` VALUES (18026, 'Lefèvre’s comments unleashed a wave of protest.', 'v. 发泄， 释放', '/ʌn\'liːʃ | ʌnˈliʃ/', 'unleash', 6);
INSERT INTO `words` VALUES (18027, 'Donna might be able to come tomorrow, but it’s very unlikely.', 'adj. 不太可能的； 没有希望的', '/ʌn\'laɪkli/', 'unlikely', 6);
INSERT INTO `words` VALUES (18028, NULL, 'adj. 不矫揉造作的， 不咬文嚼字的', '/ʌn\'lɪtəreri/', 'unliterary', 6);
INSERT INTO `words` VALUES (18029, 'a woman of unmatched beauty', 'adj. 无可匹敌的', '/ˌʌn\'mætʃt | \'ʌn\'mætʃt/', 'unmatched', 6);
INSERT INTO `words` VALUES (18030, NULL, 'adj. 未缓和的， 未减轻的', '/ʌn\'mɪtɪgeɪtɪd | ʌn\'mɪtɪɡetɪd/', 'unmitigated', 6);
INSERT INTO `words` VALUES (18031, 'Mr. Bird remained unmoved by the corruption allegations.', 'adj. 无动于衷的， 冷漠的', '/ˌʌn\'muːvd | ,ʌn\'muvd/', 'unmoved', 6);
INSERT INTO `words` VALUES (18032, NULL, 'adj. 不显著的， 不值得注意的', '/ʌn\'nəut,wə:ði | ˌʌn\'noutwɜːrði/', 'unnoteworthy', 6);
INSERT INTO `words` VALUES (18033, 'an unobstructed view of the lake', 'adj. 没有阻碍的', '/ˌʌnəb\'strʌktɪd | ,ʌnəb\'strʌktɪd/', 'unobstructed', 6);
INSERT INTO `words` VALUES (18034, 'The staff are trained to be unobtrusive.', 'adj. 不引人注目的', '/ˌʌnəb\'truːsɪv | \'ʌnəb\'trʊsɪv/', 'unobtrusive', 6);
INSERT INTO `words` VALUES (18035, 'He unpacked his bag.', 'v. 打开包裹， 卸货', '/ˌʌn\'pæk | ,ʌn\'pæk/', 'unpack', 6);
INSERT INTO `words` VALUES (18036, 'The unpalatable truth is that the team isn’t getting any better.', 'adj. 味道差的， 不好吃的； 令人不快的', '/ʌn\'pælətəbl/', 'unpalatable', 6);
INSERT INTO `words` VALUES (18037, 'an achievement unparalleled in sporting history', 'adj. 无比的， 空前的', '/ʌn\'pærəleld | ʌn\'pærəlɛld/', 'unparalleled', 6);
INSERT INTO `words` VALUES (18038, 'He took the unprecedented step of stating that the rumours were false.', 'adj. 前所未有的', '/ʌn\'presɪdentɪd | ʌn\'prɛsɪdɛntɪd/', 'unprecedented', 6);
INSERT INTO `words` VALUES (18039, 'He is utterly unpredictable.', 'adj. 不可预知的', '/ˌʌnprɪ\'dɪktəbl | ,ʌnprɪ\'dɪktəbl/', 'unpredictable', 6);
INSERT INTO `words` VALUES (18040, 'This happy event--supposing it to be such--could only have occurred at an unpremeditated moment.', 'adj. 无预谋的， 非故意的', '/ˌʌnpriː\'medɪteɪtɪd | ,ʌnpri\'mɛdɪtetɪd/', 'unpremeditated', 6);
INSERT INTO `words` VALUES (18041, 'Despite his unprepossessing appearance, he was very popular with women.', 'adj. 不吸引人的', '/ˌʌnˌpriːpə\'zesɪŋ | ʌnpri:pə\'zesiŋ/', 'unprepossessing', 6);
INSERT INTO `words` VALUES (18042, 'an unpretentious hotel', 'adj. 不炫耀的', '/ˌʌnprɪ\'tenʃəs | ,ʌnprɪ\'tɛnʃəs/', 'unpretentious', 6);
INSERT INTO `words` VALUES (18043, 'In fact, his business career had distinctly unpromising beginnings.', 'adj. 无前途的， 没有希望的', '/ʌn\'prɑːmɪsɪŋ | ʌn\'prɑmɪsɪŋ/', 'unpromising', 6);
INSERT INTO `words` VALUES (18044, 'unproven allegations', 'adj. 未经证实的', '/ʌn\'pruːvn | ʌn\'prʊvən/', 'unproven', 6);
INSERT INTO `words` VALUES (18045, 'It was a totally unprovoked attack on an innocent man.', 'adj. 非因触犯而发生的, 无缘无故的', '/,ʌnprə\'vəukt | ʌnprə\'vəʊkt | \'ʌnprə\'vokt/', 'unprovoked', 6);
INSERT INTO `words` VALUES (18046, 'unqualified staff', 'adj. 无资格的， 不合格的； 无限制的， 绝对的', '/ˌʌn\'kwɑːlɪfaɪd | ,ʌn\'kwɑlɪfaɪd/', 'unqualified', 6);
INSERT INTO `words` VALUES (18047, 'He inspires affection and respect as a man of unquestionable integrity.', 'adj. 毫无疑问的， 无懈可击的', '/ʌn\'kwestʃənəbl | ʌn\'kwɛstʃənəbl/', 'unquestionable', 6);
INSERT INTO `words` VALUES (18048, 'an unquestioning belief in God', 'adj. 无异议的， 不犹豫的', '/ʌn\'kwestʃənɪŋ | ʌn\'kwɛstʃənɪŋ/', 'unquestioning', 6);
INSERT INTO `words` VALUES (18049, 'He could unravel a knot that others wouldn\'t even attempt.', 'v. 拆开', '/,ʌn\'rævəl | ʌn\'rævl/', 'unravel', 6);
INSERT INTO `words` VALUES (18050, 'I think he’s being unreasonable.', 'adj. 不讲道理的； 非理智的， 过分的', '/ʌn\'riːznəbl | ʌn\'riznəbl/', 'unreasonable', 6);
INSERT INTO `words` VALUES (18051, 'one of the great unrecognized jazzmen of the 1930s', 'adj. 未被承认的， 未被认出的', '/ʌn\'rekəgnaɪzd | ʌn\'rɛkəg\'naɪzd/', 'unrecognized', 6);
INSERT INTO `words` VALUES (18052, 'Being in a state regarded as primitive, uncivilized, or unregenerate.', 'adj. 不悔改的', '/ˌʌnrɪ\'dʒenərət | ,ʌnrɪ\'dʒɛnərət/', 'unregenerate', 6);
INSERT INTO `words` VALUES (18053, NULL, 'adj. 未受控制的， 未受约束的', '/ˌʌn\'regjuleɪtɪd | ,ʌn\'rɛɡjuletɪd/', 'unregulated', 6);
INSERT INTO `words` VALUES (18054, 'The car’s becoming very unreliable.', 'adj. 不可靠的', '/ˌʌnrɪ\'laɪəbl | ,ʌnrɪ\'laɪəbl/', 'unreliable', 6);
INSERT INTO `words` VALUES (18055, 'unremitting poverty', 'adj. 不懈的', '/,ʌnri\'mitiŋ | ʌnrɪ\'mɪtɪŋ | ,ʌnrɪ\'mɪtɪŋ/', 'unremitting', 6);
INSERT INTO `words` VALUES (18056, 'He remains unrepentant about his comments.', 'adj. 顽固不化的， 不后悔的', '/ˌʌnrɪ\'pentənt | ,ʌnrɪ\'pɛntənt/', 'unrepentant', 6);
INSERT INTO `words` VALUES (18057, 'The president denounced the demonstrators as unrepresentative of the people.', 'adj. 没有代表性的', '/ˌʌnˌreprɪ\'zentətɪv | ,ʌn,rɛprɪ\'zɛntətɪv/', 'unrepresentative', 6);
INSERT INTO `words` VALUES (18058, 'We found some unreserved seats on the train.', 'adj. 无限制的； 未被预订的', '/ˌʌnrɪ\'zɜːrvd | \'ʌnrɪ\'zɝvd/', 'unreserved', 6);
INSERT INTO `words` VALUES (18059, 'Freedom to pursue extracurricular activities is totally unrestricted.', 'adj. 无限制的， 自由的', '/ˌʌnrɪ\'strɪktɪd | ,ʌnrɪ\'strɪktɪd/', 'unrestricted', 6);
INSERT INTO `words` VALUES (18060, 'unruly children', 'adj. 不受拘束的, 不守规矩的, 蛮横的, 难驾驭的', '/,ʌn\'ru:li | ʌn\'ruːlɪ | ʌn\'ruli/', 'unruly', 6);
INSERT INTO `words` VALUES (18061, 'The government was relatively unscathed by the scandal.', 'adj. 没有受伤的, 未受伤的', '/,ʌn\'skeiðd | ʌn\'skeɪðd | ʌn\'skeðd/', 'unscathed', 6);
INSERT INTO `words` VALUES (18062, 'Use one tablespoon of unscented liquid bleach for every four liters of water. Use drinking water or the cleanest, clearest water available.', 'adj. 无气味的', '/ʌn\'sentid | ʌn\'sentɪd/', 'unscented', 6);
INSERT INTO `words` VALUES (18063, 'unscrupulous employers', 'adj. 肆无忌惮的, 无道德的, 不谨慎的', '/,ʌn\'skru:pjuləs | ʌn\'skruːpjʊləs | ʌn\'skrupjələs/', 'unscrupulous', 6);
INSERT INTO `words` VALUES (18064, NULL, 'n. 狂妄， 不择手段', '/ʌn\'skru:pjuləsnis | ʌn\'skruːpjələsnəs/', 'unscrupulousness', 6);
INSERT INTO `words` VALUES (18065, 'Ann thought it unseemly to kiss her husband in public.', 'adj. 不体面的, 不适宜的, 不恰当的', '/,ʌn\'si:mli | ʌn\'siːmlɪ | ʌn\'simli/', 'unseemly', 6);
INSERT INTO `words` VALUES (18066, 'The sudden changes unsettled Judy.', 'v. 使不安宁， 扰乱', '/ˌʌn\'setl | ,ʌn\'sɛtl/', 'unsettle', 6);
INSERT INTO `words` VALUES (18067, 'Phil had several unsettling dreams every night.', 'adj. 使人不安的， 扰乱的', '/ʌn\'setlɪŋ | ʌn\'sɛtlɪŋ/', 'unsettling', 6);
INSERT INTO `words` VALUES (18068, 'companies employing unskilled labour', 'adj. 不熟练的； 无需技能的', '/ˌʌn\'skɪld | ,ʌn\'skɪld/', 'unskilled', 6);
INSERT INTO `words` VALUES (18069, 'The houses are structurally unsound.', 'adj. 不健康的， 不健全的； 不结实的， 不坚固的； 无根据的', '/ˌʌn\'saund | ,ʌn\'saʊnd/', 'unsound', 6);
INSERT INTO `words` VALUES (18070, 'unspoiled countryside', 'adj. 未损坏的， 未宠坏的', '/ˌʌn\'spɔɪld | \'ʌn\'spɔɪld/', 'unspoiled', 6);
INSERT INTO `words` VALUES (18071, 'Pure religion and undefiled before our God and Father is this: to visit the orphan and the widow in their distress, and to keep oneself unspotted from the world.', 'adj. 清白的', '/,ʌn\'spɔtid | ʌn\'spɒtɪd/', 'unspotted', 6);
INSERT INTO `words` VALUES (18072, 'The political situation is still very unstable.', 'adj. 不稳定的', '/ʌn\'steɪbl | ʌn\'stebl/', 'unstable', 6);
INSERT INTO `words` VALUES (18073, '...her unstinting charity work.', 'adj. 慷慨的， 大方的', '/ʌn\'stɪntɪŋ | \'ʌn\'stintiŋ/', 'unstinting', 6);
INSERT INTO `words` VALUES (18074, NULL, 'adj. 非娇揉造作的,未学过的,不懂的', '/,ʌn\'stʌdid | ʌn\'stʌdɪd/', 'unstudied', 6);
INSERT INTO `words` VALUES (18075, 'unsubstantiated allegations of child abuse', 'adj. 未经证实的， 无事实根据的', '/ˌʌnsəb\'stænʃieɪtɪd | ,ʌnsəb\'stænʃɪetɪd/', 'unsubstantiated', 6);
INSERT INTO `words` VALUES (18076, 'Chris seemed nervous and unsure of herself.', 'adj. 缺乏自信的； 不确定的', '/ˌʌn\'ʃur | ,ʌn\'ʃʊr/', 'unsure', 6);
INSERT INTO `words` VALUES (18077, NULL, 'adj. 未被超越的', '/ˌʌnsər\'pæst | ,ʌnsɚ\'pæst/', 'unsurpassed', 6);
INSERT INTO `words` VALUES (18078, 'unsuspecting victims', 'adj. 不怀疑的， 无猜疑的， 可信任的', '/ˌʌnsə\'spektɪŋ | \'ʌnsə\'spɛktɪŋ/', 'unsuspecting', 6);
INSERT INTO `words` VALUES (18079, 'Organic food refers to food that is by - and - large untainted by pollution.', 'adj. 无污点的', '/ʌn\'teɪntɪd | ʌn\'tentɪd/', 'untainted', 6);
INSERT INTO `words` VALUES (18080, 'an untalented but gorgeous actress', 'adj. 没有天赋的', '/ʌn\'tæləntɪd/', 'untalented', 6);
INSERT INTO `words` VALUES (18081, 'This is the issue for Socrates, how to channel this wild and untamed passion of spirit or heart, how to channel this to some kind of common good.', 'adj. 未驯服的', '/ˌʌn\'teɪmd | ,ʌn\'temd/', 'untamed', 6);
INSERT INTO `words` VALUES (18082, 'Older people are an untapped resource in the employment market.', 'adj. 未开发的， 未利用的', '/ˌʌn\'tæpt | ,ʌn\'tæpt/', 'untapped', 6);
INSERT INTO `words` VALUES (18083, NULL, 'adj. 失去光泽的', '/ˌʌn\'tɑːrnɪʃt | ʌn\'tɑːnɪʃt/', 'untarnished', 6);
INSERT INTO `words` VALUES (18084, NULL, 'adj. 未尝过的， 未体验过的', '/ˌʌn\'teɪstɪd/', 'untasted', 6);
INSERT INTO `words` VALUES (18085, 'The scandal put the President in an untenable position.', 'adj. 难以防守的； 不能租赁的', '/ʌn\'tenəbl | ʌn\'tɛnəbl/', 'untenable', 6);
INSERT INTO `words` VALUES (18086, NULL, 'adj. 不危险的', '/ʌn\'θretənɪŋ/', 'unthreatening', 6);
INSERT INTO `words` VALUES (18087, 'the untimely death of a popular local man', 'adj. 过早的； 不合时宜的', '/ʌn\'taɪmli/', 'untimely', 6);
INSERT INTO `words` VALUES (18088, 'The rumours will do untold damage to his reputation.', 'adj. 无数的， 数不清的', '/ˌʌn\'tould | ,ʌn\'told/', 'untold', 6);
INSERT INTO `words` VALUES (18089, 'Several papers lay untouched on the desk.', 'adj. 未触动过的， 未改变的', '/ʌn\'tʌtʃt/', 'untouched', 6);
INSERT INTO `words` VALUES (18090, 'The surveyor\'s report didn\'t highlight anything untoward.', 'adj. 倔强的, 麻烦的, 困难的, 不幸的', '/,ʌntə\'wɔ:d | ʌntə\'wɔːd; ʌn\'təʊəd | ʌn\'tɔrd/', 'untoward', 6);
INSERT INTO `words` VALUES (18091, 'untreated sewage', 'adj. 未治疗的； 未经处理的', '/ˌʌn\'triːtɪd | ,ʌn\'tritɪd/', 'untreated', 6);
INSERT INTO `words` VALUES (18092, 'I think he is shallow, vain and untrustworthy.', 'adj. 不能信赖的， 靠不住的', '/ʌn\'trʌstwɜːrði | ʌn\'trʌstwɝði/', 'untrustworthy', 6);
INSERT INTO `words` VALUES (18093, 'This untutored mathematician had an obsession with numbers.', 'adj. 未受教育的', '/ˌʌn\'tuːtərd | ,ʌn\'tutɚd/', 'untutored', 6);
INSERT INTO `words` VALUES (18094, NULL, 'adj. 不精通的, 不熟练的, 无知的, 无经验的', '/,ʌn\'və:st | ʌn\'vɜːst | ,ʌn\'vɝst/', 'unversed', 6);
INSERT INTO `words` VALUES (18095, 'Any attempt to discuss the issue of human rights was rejected as an unwarranted interference in the country\'s internal affairs.', 'adj. 没有根据的', '/ʌn\'wɑːrəntɪd | ʌn\'wɔrəntɪd/', 'unwarranted', 6);
INSERT INTO `words` VALUES (18096, 'unwieldy bureaucracy', 'adj. 笨拙的, 不实用的, 难处理的, 难使用的, 笨重的', '/,ʌn\'wi:ldi | ʌn\'wiːldɪ | ʌn\'wildi/', 'unwieldy', 6);
INSERT INTO `words` VALUES (18097, 'More and more, health is the unwitting victim of policies made in the international systems that tie countries, economies, commerce, and trade together.', 'adj. 不知情的', '/,ʌn\'witiŋ | ʌn\'wɪtɪŋ/', 'unwitting', 6);
INSERT INTO `words` VALUES (18098, 'unwonted freedom', 'adj. 不寻常的， 不习惯的', '/ʌn\'wountɪd | ʌn\'wontɪd/', 'unwonted', 6);
INSERT INTO `words` VALUES (18099, 'unworldly beauty', 'adj. 非世俗的； 精神上的', '/ʌn\'wɜːrldli | ʌn\'wɝldli/', 'unworldly', 6);
INSERT INTO `words` VALUES (18100, 'an unyielding resistance to change', 'adj. 坚定的， 不屈的； 坚硬的， 不能弯曲的', '/ʌn\'jiːldɪŋ | ʌn\'jildɪŋ/', 'unyielding', 6);
INSERT INTO `words` VALUES (18101, 'His mother summoned him, upbraided him, wept and prayed.', 'v. 责备', '/ʌp\'breid | ʌp\'breɪd | ʌp\'bred/', 'upbraid', 6);
INSERT INTO `words` VALUES (18102, 'He upended the beer, and swallowed.', 'v. 颠倒, 倒放', '/ʌp\'end | ʌp\'ɛnd/', 'upend', 6);
INSERT INTO `words` VALUES (18103, 'Mo’s very upfront with him about their relationship.', 'adj. 坦率的', '/ˌʌp\'frʌnt | ,ʌp\'frʌnt/', 'upfront', 6);
INSERT INTO `words` VALUES (18104, 'political upheaval', 'n. 剧变', '/ʌp\'hi:vəl | ʌp\'hiːv(ə)l | ʌp\'hivl/', 'upheaval', 6);
INSERT INTO `words` VALUES (18105, 'a committee that aims to uphold educational standards', 'v. 支持, 赞成', '/ʌp\'həuld | ʌp\'həʊld | ʌpˈhoʊld/', 'uphold', 6);
INSERT INTO `words` VALUES (18106, NULL, 'n. 室内装潢, 室内装璜业', '/ʌp\'həulstəri | ʌp\'həʊlst(ə)rɪ; -\'hɒl- | ʌp\'holstəri/', 'upholstery', 6);
INSERT INTO `words` VALUES (18107, 'Katie was still awake, sitting bolt upright(= sitting with her back very straight ) staring at the television.', 'adj. 垂直的， 直立的； 正直的， 诚实的', '/\'ʌpraɪt/', 'upright', 6);
INSERT INTO `words` VALUES (18108, 'The announcement caused uproar in the crowd.', 'n. 喧嚣， 吵闹； 骚动， 骚乱', '/\'ʌprɔːr | \'ʌprɔr/', 'uproar', 6);
INSERT INTO `words` VALUES (18109, 'an uproarious party', 'adj. 骚动的； 喧嚣的； 令人捧腹大笑的', '/ʌp\'rɔːriəs | ʌp\'rɔrɪəs/', 'uproarious', 6);
INSERT INTO `words` VALUES (18110, NULL, 'v. 升高级， 升档', '/ˌʌp\'skeɪl | \'ʌpskeil/', 'upscale', 6);
INSERT INTO `words` VALUES (18111, NULL, 'v. (将)(汽车)调高速挡,(使)加速', '/\'ʌpʃift/', 'upshift', 6);
INSERT INTO `words` VALUES (18112, NULL, 'adj. 自负的', '/\'ʌp\'steidʒ, ,ʌp\'steidʒ, \'ʌpsteidʒ | ʌp\'steɪdʒ | ,ʌp\'stedʒ/', 'upstage', 6);
INSERT INTO `words` VALUES (18113, 'He tried to pass for a gentleman;but everyone knew he was an upstart.', 'n. 暴发户', '/\'ʌpstɑ:t, ʌp\'stɑ:t | \'ʌpstɑːt | \'ʌpstɑrt/', 'upstart', 6);
INSERT INTO `words` VALUES (18114, 'A new upsurge in construction is in the making.', 'n. 高潮', '/\'ʌpsə:dʒ, ʌp\'sə:dʒ | \'ʌpsɜːdʒ | \'ʌpsɝdʒ/', 'upsurge', 6);
INSERT INTO `words` VALUES (18115, '...an upswing in the economy.', 'n. 高涨, 向上摆动, 改进', '/\'ʌpswɪŋ/', 'upswing', 6);
INSERT INTO `words` VALUES (18116, NULL, 'n. 举起', '/\'ʌpteik | \'ʌpteɪk | \'ʌptek/', 'uptake', 6);
INSERT INTO `words` VALUES (18117, 'Penny never got uptight about exams.', 'adj. 经济情况不妙的, 拮据的, 紧张的, 心情焦躁的, 极端保守的', '/\'ʌp\'tait | ʌp\'taɪt; \'ʌptaɪt | \'ʌp\'taɪt/', 'uptight', 6);
INSERT INTO `words` VALUES (18118, 'Neil was urbane, witty, direct, and honest.', 'adj. 彬彬有礼的, 文雅的', '/ə:\'bein | ɜː\'beɪn | ɝ\'ben/', 'urbane', 6);
INSERT INTO `words` VALUES (18119, NULL, 'v. 使都市化， 使文雅', '/\'ɜːrbənaɪz | \'ə:bənaiz/', 'urbanize', 6);
INSERT INTO `words` VALUES (18120, 'In case of urgency, call the police.', 'n. 紧急', '/\'ɜːrdʒənsi | \'ɝdʒənsi/', 'urgency', 6);
INSERT INTO `words` VALUES (18121, 'The doctor took a urine sample and a blood sample.', 'n. 尿', '/\'juərin | \'jʊərɪn; -raɪn | \'jʊrən/', 'urine', 6);
INSERT INTO `words` VALUES (18122, 'Regrettablly is, be in ursine city commonly prices when, investor can be far from these pannikin.', 'adj. 熊的, 象熊的', '/\'ə:sain | \'ɜːsaɪn; -ɪn | \'ɝsaɪn/', 'ursine', 6);
INSERT INTO `words` VALUES (18123, 'The computer language involved was readily usable.', 'adj. 可用的； 好用的', '/\'juːzəbl | \'jʊzəbl/', 'usable', 6);
INSERT INTO `words` VALUES (18124, 'He did part-time work as an usher in a theatre.', 'n. 引座员, 招待员, 传达员, 前驱', '/\'ʌʃə | \'ʌʃɚ/', 'usher', 6);
