INSERT INTO `words` VALUES (18336, 'a voluptuous gesture', 'adj. 艳丽的, 奢侈逸乐的', '/və\'lʌptjuəs | və\'lʌptʃʊəs | və\'lʌptʃuəs/', 'voluptuous', 6);
INSERT INTO `words` VALUES (18337, 'Joseph Smith was a voracious book collector.', 'adj. 狼吞虎咽的, 贪婪的', '/vɔ\'reiʃəs | və\'reɪʃəs | və\'reʃəs/', 'voracious', 6);
INSERT INTO `words` VALUES (18338, 'For me, this value is to be sought on a much less elevated plane than might be supposed, namely, in that which is the true function of the organ of the eye, the eye filled with voracity, the evil eye.', 'n. 贪食, 贪婪', '/vɔ\'ræsəti/', 'voracity', 6);
INSERT INTO `words` VALUES (18339, 'The polar vortex is a system of wintertime winds.', 'n. 旋涡, 旋风, 涡流, (动乱, 争论等的)中心', '/\'vɔ:teks | \'vɔːteks | \'vɔrtɛks/', 'vortex', 6);
INSERT INTO `words` VALUES (18340, 'The organismic, \"what you can do for your country\" implies that government is the master or the deity, the citizen, the servant or the votary.', 'n. 信仰者', '/\'vəutəri | \'vəʊt(ə)rɪ | \'votəri/', 'votary', 6);
INSERT INTO `words` VALUES (18341, 'I can vouch for his honesty.', 'v. 担保， 保证', '/vautʃ | vaʊtʃ/', 'vouch', 6);
INSERT INTO `words` VALUES (18342, 'The voucher can be used at most major supermarkets.', 'n. 证件； 收据； 凭证； 代金券', '/\'vautʃər | \'vaʊtʃɚ/', 'voucher', 6);
INSERT INTO `words` VALUES (18343, NULL, 'n. <法>窥淫狂病人,偷看下流场面的人', '/vwɑ:\'jə: | vwʌ\'jɜː; vɒɪ- | vɔɪ\'jɝ/', 'voyeur', 6);
