INSERT INTO `words` VALUES (18346, 'He took advantage of me when I was at my most vulnerable.', 'adj. 易受伤的， 脆弱的', '/\'vʌlnərəbl/', 'vulnerable', 6);
INSERT INTO `words` VALUES (18347, 'She disliked his sly ways, but granted him certain vulpine intelligence.', 'adj. 狡猾的', '/\'vʌlpain | \'vʌlpaɪn/', 'vulpine', 6);
INSERT INTO `words` VALUES (18348, 'Although many more students are entering colleges and universities than was the case twenty years ago, there are also many more courses of study vying for their commitment.', 'adj. 竞争的', '/\'vaɪɪŋ/', 'vying', 6);
INSERT INTO `words` VALUES (18349, 'a wonderfully wacky idea', 'adj. <美俚>古怪的, 乖僻的, 疯疯癫癫的', '/\'wæki | \'wækɪ/', 'wacky', 6);
