INSERT INTO `words` VALUES (18356, 'Muskrat Castle, as the house had Been facetiously named By some waggish officer.', 'adj. 爱开玩笑的, 滑稽的', '/\'wæɡiʃ | \'wægɪʃ | \'wæɡɪʃ/', 'waggish', 6);
