INSERT INTO `words` VALUES (18359, 'She waived her right to a lawyer.', 'v. 放弃', '/weiv | weɪv | wev/', 'waive', 6);
INSERT INTO `words` VALUES (18360, 'Once, she walloped me over the head with a frying pan.', 'v. 乱窜, 猛冲, (车等)颠簸, 沸腾作用', '/\'wɔləp | \'wɒləp | \'wɑləp/', 'wallop', 6);
INSERT INTO `words` VALUES (18361, 'hippos wallowing in the mud', 'v. 打滚, <喻>沉迷, 颠簸', '/\'wɔləu | \'wɒləʊ | \'wɑlo/', 'wallow', 6);
INSERT INTO `words` VALUES (18362, 'Morse was yet another name that appeared before walrus and seems to have spread to other languages only to drop out of use in English.', 'n. [动]海象, 海象胡须', '/\'wɔ:lrəs, \'wɔl- | \'wɔːlrəs; \'wɒl- | \'wɔlrəs/', 'walrus', 6);
INSERT INTO `words` VALUES (18363, 'She gave a wan smile.', 'adj. 苍白的, 无血色的, 病态的, 暗淡的, 无力的', '/wɔn | wɒn | wɑn/', 'wan', 6);
INSERT INTO `words` VALUES (18364, 'His wanderlust would not allow him to stay long in one spot.', 'n. 旅行癖, 流浪癖', '/\'wɔndəlʌst | \'wɒndəlʌst | \'wɑndɚlʌst/', 'wanderlust', 6);
