INSERT INTO `words` VALUES (18367, 'an act of wanton aggression', 'adj. 荒唐的, 嬉戏的, 繁茂的, 肆意的, 不道德的, 不贞洁的', '/\'wɒntən | \'wɔntən/', 'wanton', 6);
INSERT INTO `words` VALUES (18368, 'Mills warbled a few notes.', 'v. 鸟鸣, 用柔和的颤声唱', '/\'wɔ:bl | \'wɔːb(ə)l | \'wɔrbl/', 'warble', 6);
INSERT INTO `words` VALUES (18369, 'He was a warden at the local parish church.', 'n. 典狱官, 看守人, 学监, 区长, (供煮食的)一种冬梨', '/\'wɔ:dən | \'wɔːd(ə)n | \'wɔrdn/', 'warden', 6);
INSERT INTO `words` VALUES (18370, 'Can you hang these in the wardrobe, please?', 'n. 衣柜, 衣厨, 衣室, 衣服, 行头, 剧装', '/\'wɔ:drəub | \'wɔːdrəʊb | \'wɔr\'drob/', 'wardrobe', 6);
INSERT INTO `words` VALUES (18371, 'The building opposite us is the warehouse.', 'n. 仓库， 货栈', '/\'werhaus | \'wɛrhaʊs/', 'warehouse', 6);
INSERT INTO `words` VALUES (18372, 'the realities of modern warfare', 'n. 战争, 作战, 冲突, 竞争', '/\'wɔ:fεə | \'wɔːfeə | \'wɔrfɛr/', 'warfare', 6);
INSERT INTO `words` VALUES (18373, 'To be fair, though, I understand from the Times that whenever I mention in my column that WWII ended the Great Depression, the paper gets a lot of mail accusing me of being a warmonger.', 'n. 好战者, 主战论者', NULL, 'warmonger', 6);
