INSERT INTO `words` VALUES (18380, 'The picnic was a total washout – nobody turned up!', 'n. 冲失, 冲失的区域', '/\'wɔʃaut, \'wɔ:ʃ- | \'wɒʃaʊt | \'wɑʃaʊt/', 'washout', 6);
INSERT INTO `words` VALUES (18381, 'waspish remarks', 'adj. 如黄蜂的, 腰细的, 易怒的, 尖刻的', '/\'wɔspiʃ, \'wɔ:- | \'wɒspɪʃ | \'wɑspɪʃ/', 'waspish', 6);
INSERT INTO `words` VALUES (18382, 'The government of luxembourg however has recently grown fed up with wastrel youths applying for unemployment benefits while still living with their parents.', 'n. 废物', '/\'weistrəl | \'weɪstr(ə)l | \'westrəl/', 'wastrel', 6);
