INSERT INTO `words` VALUES (18414, 'He heard the dog whimper.', 'v. 呜咽, 哀诉', '/\'hwimpə | \'wɪmpə | \'wɪmpɚ/', 'whimper', 6);
INSERT INTO `words` VALUES (18415, 'He has a wonderful whimsical sense of humour.', 'adj. 反复无常的, 古怪的', '/\'hwimzikəl | \'wɪmzɪk(ə)l | \'wɪmzɪkl/', 'whimsical', 6);
