INSERT INTO `words` VALUES (18421, 'Sara had not changed a whit.', 'n. 些微, 一点点', '/hwit | wɪt/', 'whit', 6);
INSERT INTO `words` VALUES (18422, 'We need to whittle down the list of guests for the party.', 'v. 切, 削, 削减, 损害', '/\'hwitl | \'wɪt(ə)l | \'wɪtl/', 'whittle', 6);
INSERT INTO `words` VALUES (18423, 'He does wholesale business, while his brother is engaged in retail business.', 'n. 批发, 趸售', '/\'həulseil | \'həʊlseɪl | \'holsel/', 'wholesale', 6);
INSERT INTO `words` VALUES (18424, 'good wholesome fun', 'adj. 有益健康的', '/\'houlsəm | \'holsəm/', 'wholesome', 6);
