INSERT INTO `words` VALUES (18434, 'There is a willful self-destructiveness in the air here as if America has all the time and money in the world for petty politics.', 'adj. 任性的, 故意的', '/\'wilful | \'wɪlfʊl | \'wɪlfəl/', 'willful', 6);
