INSERT INTO `words` VALUES (18472, 'He was scared of incurring his father’s wrath .', 'n. 愤怒', '/rɔθ, ræθ, rɑ:θ | rɒθ; rɔːθ | ræθ/', 'wrath', 6);
INSERT INTO `words` VALUES (18473, 'Violent storms wreaked havoc on the French Riviera, leaving three people dead and dozens injured.', 'v. 发泄(怒火), 报仇', '/riːk | rik/', 'wreak', 6);
