INSERT INTO `words` VALUES (18488, '...a just and tolerant society which rejects xenophobia and racism.', 'n. 仇外, 惧外者', '/,zenəu\'fəubiə, ,zi:- | zenə\'fəʊbɪə | ,zɛnə\'fobɪə/', 'xenophobia', 6);
INSERT INTO `words` VALUES (18489, 'Service in the armed forces gave many Americans a less xenophobic view of the world.', 'adj. 恐外的， 恐惧外国人的', '/,zenəu\'fəubik, ,zi:- | ˌzenə\'foubik/', 'xenophobic', 6);
