INSERT INTO `words` VALUES (18530, 'He remained fascinated by the Aboriginals\' tales.', 'n&a. 土著(的)；土生动植物(的)', '/,æbə\'ridʒənəl | æbə\'rɪdʒɪn(ə)l | ,æbə\'rɪdʒənl/', 'aboriginal', 4);
INSERT INTO `words` VALUES (18531, 'The disease causes pregnant animals to abort.', 'v. 取消；流产', '/ə\'bɔ:t | ə\'bɔːt | ə\'bɔrt/', 'abort', 4);
INSERT INTO `words` VALUES (18532, 'She decided to have an abortion .', 'n. 流产；(计划)失败', '/ə\'bɔːʃ(ə)n | ə\'bɔrʃən/', 'abortion', 4);
INSERT INTO `words` VALUES (18533, 'Rumors of such coordination abound, but as with many rumors, they have no basis in fact.', 'v. 多；富于', '/ə\'baund | ə\'baʊnd/', 'abound', 4);
