INSERT INTO `words` VALUES (18535, 'Article 33 A book publisher may alter or abridge a work with the permission of the copyright owner.', 'v. (书等)删节', '/ə\'bridʒ | ə\'brɪdʒ/', 'abridge', 4);
INSERT INTO `words` VALUES (18536, 'an abrupt change of plan', 'adj. 突然的，粗暴的', '/ə\'brʌpt/', 'abrupt', 4);
