INSERT INTO `words` VALUES (18538, 'Alcohol is associated with many serious social and developmental issues, including violence, child neglect and abuse, and absenteeism in the workplace.', 'n. 旷课； 旷工', '/ˌæbsən\'tiːɪzəm | ,æbsən\'tiɪzəm/', 'absenteeism', 4);
INSERT INTO `words` VALUES (18539, 'I have absolute confidence in her.', 'adj. 完全的， 绝对的， 纯粹的', '/\'æbsəluːt | \'æbsəlut/', 'absolute', 4);
INSERT INTO `words` VALUES (18540, 'Plants absorb nutrients from the soil.', 'v. 吸收；吸引', '/əb\'sɔ:b, -\'zɔ:b | əb\'zɔːb; -\'sɔːb | æbˈsɔrb; æbˈzɔrb; əbˈsɔrb/', 'absorb', 4);
INSERT INTO `words` VALUES (18541, 'By the age of seven, children are capable of thinking in abstract terms .', 'adj. 抽象的; n. (书籍、演说等的)摘要', '/\'æbstrækt/', 'abstract', 4);
INSERT INTO `words` VALUES (18542, 'He’s always talking in abstractions.', 'n. 抽象', '/æb\'strækʃn | æb\'strækʃən/', 'abstraction', 4);
