INSERT INTO `words` VALUES (18544, 'This area of Mexico has an abundance of safe beaches and a pleasing climate.', 'n. 丰富', '/ə\'bʌndəns | ə\'bʌnd(ə)ns/', 'abundance', 4);
INSERT INTO `words` VALUES (18545, 'A self-monitoring tax system is clearly open to abuse (= able to be used wrongly ) .', 'n&vt. 滥用；恶习；辱骂', '/ə\'bju:z, ə\'bju:s | ə\'bjuːz | ə\'bjus/', 'abuse', 4);
INSERT INTO `words` VALUES (18546, 'He possessed no academic qualifications.', 'adj. 学术的；学校的', '/,ækə\'demik | ækə\'demɪk | ,ækə\'dɛmɪk/', 'academic', 4);
INSERT INTO `words` VALUES (18547, 'measures to accelerate the rate of economic growth', 'v. 加速，变快', '/ək\'seləreit | ək\'seləreɪt | əkˈsɛləˌret/', 'accelerate', 4);
INSERT INTO `words` VALUES (18548, 'Students who achieve an acceptable standard will progress to degree studies.', 'adj. 可接受的', '/ək\'septəbl | ək\'sɛptəbl/', 'acceptable', 4);
