INSERT INTO `words` VALUES (18550, 'The island is only accessible by boat.', 'adj. 能接近的； 易达到的', '/ək\'sesəbl | ək\'sɛsəbl/', 'accessible', 4);
INSERT INTO `words` VALUES (18551, 'bathroom accessories such as mirrors and towel-rails', 'n. 同谋者；附件', '/ək\'sesəri | ək\'ses(ə)rɪ | ək\'sɛsəri/', 'accessory', 4);
INSERT INTO `words` VALUES (18552, 'Angela Bassett has won critical acclaim for her excellent performance.', 'vt. 向…欢呼，为…喝彩; n. 称赞； 欢迎', '/ə\'kleɪm | ə\'klem/', 'acclaim', 4);
