INSERT INTO `words` VALUES (18555, 'The price for the holiday includes flights and accommodation.', 'n. 住宿', '/ə,kɔmə\'deiʃən | əkɒmə\'deɪʃ(ə)n | ə,kɑmə\'deʃən/', 'accommodation', 4);
INSERT INTO `words` VALUES (18556, 'Children under 14 must be accompanied by an adult.', 'v. 陪伴，伴奏', '/ə\'kʌmpəni | ə\'kʌmpənɪ/', 'accompany', 4);
INSERT INTO `words` VALUES (18557, 'We have accomplished all we set out to do.', 'vt. 达到， 完成， 实现', '/ə\'kʌmplɪʃ | ə\'kɑmplɪʃ/', 'accomplish', 4);
