INSERT INTO `words` VALUES (18560, 'But I also believe that everyone who comments here should be accountable: in other words that the rest of us should be able to see who they are.', 'adj. for; 对. 应付责任', '/ə\'kauntəbl | ə\'kaʊntəb(ə)l | ə\'kaʊntəbl/', 'accountable', 4);
INSERT INTO `words` VALUES (18561, 'He is studying accountancy or he is an accountancy student.', 'n. 会计工作， 会计职业', '/ə\'kauntənsi | ə\'kaʊntənsi/', 'accountancy', 4);
INSERT INTO `words` VALUES (18562, 'The boss dropped an accountant from the payroll.', 'n. 会计员', '/ə\'kauntənt | ə\'kaʊnt(ə)nt | ə\'kaʊntənt/', 'accountant', 4);
INSERT INTO `words` VALUES (18563, NULL, 'vt. 信任， 相信， 委任， 授权； 把…归于', '/ə\'kredɪt | ə\'krɛdɪt/', 'accredit', 4);
INSERT INTO `words` VALUES (18564, NULL, 'n. 证明合格， 鉴定合格', '/əˌkredɪ\'teɪʃn | ə\'krɛdə\'teʃən/', 'accreditation', 4);
INSERT INTO `words` VALUES (18565, 'What is the moral of this fable? If you want to accumulate enduring wealth, do not lend to grasshoppers.', 'n. 积累，积聚', '/ə\'kju:mjuleit | ə\'kjuːmjʊleɪt | ə\'kjumjəlet/', 'accumulate', 4);
INSERT INTO `words` VALUES (18566, 'He passes the ball with unerring accuracy.', 'n. 准确， 精确', '/\'ækjərəsi/', 'accuracy', 4);
INSERT INTO `words` VALUES (18567, 'The brochure tries to give a fair and accurate description of each hotel.', 'adj. 正确无误的； 精确的', '/\'ækjərət/', 'accurate', 4);
INSERT INTO `words` VALUES (18568, 'The professor stands accused of (= has been accused of ) stealing his student’s ideas and publishing them.', 'v. 控告', '/ə\'kju:z | ə\'kjuːz | ə\'kjuz/', 'accuse', 4);
INSERT INTO `words` VALUES (18569, 'She tried to accustom herself to the tight bandages.', 'vt. 使习惯于', '/ə\'kʌstəm/', 'accustom', 4);
INSERT INTO `words` VALUES (18570, 'Frances achieved very good exam results.', 'v. 完成，达到', '/ə\'tʃiːv | ə\'tʃiv/', 'achieve', 4);
INSERT INTO `words` VALUES (18571, 'His great achievement is to make all the players into a united team.', 'n. 成就， 成绩； 达到， 完成， 实现', '/ə\'tʃiːvmənt | ə\'tʃivmənt/', 'achievement', 4);
INSERT INTO `words` VALUES (18572, 'a juicy apple with a slightly acid flavour', 'adj. 酸的；尖刻的; n. 酸', '/\'æsid | \'æsɪd/', 'acid', 4);
INSERT INTO `words` VALUES (18573, 'The family acknowledge the need for change.', 'v. 承认；表示收到信件，表示感谢', '/ək\'nɔlidʒ | ək\'nɒlɪdʒ | ək\'nɑlɪdʒ/', 'acknowledge', 4);
INSERT INTO `words` VALUES (18574, NULL, 'adj. 原声的； 声音的； 听觉的', '/ə\'kuːstɪk | ə\'kʊstɪk/', 'acoustic', 4);
INSERT INTO `words` VALUES (18575, 'I need to acquaint myself with the new regulations.', 'v. 使认识；使熟悉', '/ə\'kweint | ə\'kweɪnt | ə\'kwent/', 'acquaint', 4);
INSERT INTO `words` VALUES (18576, 'She was a casual acquaintance of my family in Vienna.', 'n. 熟人； 认识， 了解', '/ə\'kweɪntəns | ə\'kwentəns/', 'acquaintance', 4);
INSERT INTO `words` VALUES (18577, 'Manning hoped to acquire valuable works of art as cheaply as possible.', 'v. 取得；获得', '/ə\'kwaiə | ə\'kwaɪə | ə\'kwaɪr/', 'acquire', 4);
INSERT INTO `words` VALUES (18578, 'the acquisition of language', 'n. 获得，获得物', '/,ækwɪ\'zɪʃ(ə)n | ,ækwɪ\'zɪʃən/', 'acquisition', 4);
INSERT INTO `words` VALUES (18579, 'The acrobat turned a somersault.', 'n. 特技演员； 杂技演员', '/\'ækrəbæt/', 'acrobat', 4);
INSERT INTO `words` VALUES (18580, 'They performed some amazing acrobatic feats.', 'adj. 杂技的； 杂技般的； 杂技演员的', '/ˌækrə\'bætɪk | ,ækrə\'bætɪk/', 'acrobatic', 4);
INSERT INTO `words` VALUES (18581, 'Cooking fumes may activate the alarm.', 'v. 使活动，触发', '/\'æktiveit | \'æktɪveɪt | \'æktə\'vet/', 'activate', 4);
INSERT INTO `words` VALUES (18582, 'I’m not joking. Those were his actual words.', 'adj. 实际的； 真实的', '/\'æktʃʊəl | \'æktʃuəl/', 'actual', 4);
INSERT INTO `words` VALUES (18583, 'His business acumen helped him to succeed where others had failed.', 'n. 敏锐； 精明', '/\'ækjəmən | əˈkjumən/', 'acumen', 4);
INSERT INTO `words` VALUES (18584, 'the four main acupuncture points', 'n. 针刺疗法， 针灸', '/\'ækjʊpʌŋktʃə(r) | \'ækjupʌŋktʃɚ/', 'acupuncture', 4);
INSERT INTO `words` VALUES (18585, 'acute arthritis', 'adj. 厉害的，敏锐的，(疾病等)急性的', '/ə\'kju:t | ə\'kjuːt | ə\'kjut/', 'acute', 4);
INSERT INTO `words` VALUES (18586, 'The ability to adapt is a definite asset in this job.', 'v. 使适应，改编', '/ə\'dæpt/', 'adapt', 4);
INSERT INTO `words` VALUES (18587, 'Branagh won two awards for his screen adaptation of Shakespeare\'s Henry the Fifth.', 'n. 适应； 改编； 改制物', '/ˌædæp\'teɪʃn | ,ædæp\'teʃən/', 'adaptation', 4);
INSERT INTO `words` VALUES (18588, 'He\'s only 24 years old and a drug addict.', 'v. 使沉迷，使嗜好', '/ə\'dikt,\'ædikt | \'ædɪkt (for n.); əˈdɪkt (for v.)/', 'addict', 4);
INSERT INTO `words` VALUES (18589, 'She helped him fight his drug addiction.', 'n. 瘾； 沉溺', '/ə\'dɪkʃn | ə\'dɪkʃən/', 'addiction', 4);
INSERT INTO `words` VALUES (18590, '...simple addition and subtraction problems using whole numbers.', 'n. 加， 增加', '/ə\'dɪʃn | ə\'dɪʃən/', 'addition', 4);
INSERT INTO `words` VALUES (18591, 'Additional information can be obtained from the centre.', 'adj. 附加的； 追加的', '/ə\'dɪʃənl/', 'additional', 4);
INSERT INTO `words` VALUES (18592, 'What’s your new address?', 'n. 住址；致词; v. 向致词；在信封上写姓名', '/ə\'dres | ə\'drɛs/', 'address', 4);
INSERT INTO `words` VALUES (18593, 'Farmers have been slow to make adequate provision for their retirement.', 'adj. 充分的；可胜任的', '/\'ædikwit | \'ædɪkwət | ˈædɪkwət/', 'adequate', 4);
INSERT INTO `words` VALUES (18594, 'But this means they cannot always adhere to the strict codes of practice dictated in UN headquarters.', 'v. 粘着；忠于；坚持', '/əd\'hiə | əd\'hɪə | əd\'hɪr/', 'adhere', 4);
INSERT INTO `words` VALUES (18595, 'We stayed in adjacent rooms.', 'adj. 邻接的，邻近的', '/ə\'dʒeisənt | ə\'dʒeɪs(ə)nt | ə\'dʒesnt/', 'adjacent', 4);
INSERT INTO `words` VALUES (18596, 'A vacant plot of land adjoins his house.', 'v. 贴近，与毗连', '/ə\'dʒɔin | ə\'dʒɒɪn | ə\'dʒɔɪn/', 'adjoin', 4);
INSERT INTO `words` VALUES (18597, NULL, 'n. 附加物， 附件； 附加语， 修饰语', '/\'ædʒʌŋkt/', 'adjunct', 4);
INSERT INTO `words` VALUES (18598, 'Check and adjust the brakes regularly.', 'v. 校准，调整', '/ə\'dʒʌst/', 'adjust', 4);
INSERT INTO `words` VALUES (18599, 'The money will be administered by local charities.', 'v. 管理，支配；给予', '/əd\'ministə | əd\'mɪnɪstə | əd\'mɪnɪstɚ/', 'administer', 4);
INSERT INTO `words` VALUES (18600, 'We’re looking for someone with experience in administration.', 'n. 管理，经营；行政', '/əd,mini\'streiʃən | ədmɪnɪ\'streɪʃ(ə)n | əd,mɪnɪ\'streʃən/', 'administration', 4);
INSERT INTO `words` VALUES (18601, 'The job is mainly administrative.', 'adj. 管理的， 行政的', '/əd\'mɪnɪstrətɪv | əd\'mɪnɪstretɪv/', 'administrative', 4);
INSERT INTO `words` VALUES (18602, 'On Friday the company\'s administrators sought permission from a Melbourne court to keep operating.', 'n. 管理者， 管理人员； 行政人员', '/əd\'mɪnɪstreɪtə(r) | əd\'mɪnɪstretɚ/', 'administrator', 4);
INSERT INTO `words` VALUES (18603, 'Reese, by his own admission , lacks the necessary experience.', 'n. 准入，接纳，承认', '/əd\'miʃən | əd\'mɪʃ(ə)n | əd\'mɪʃən/', 'admission', 4);
INSERT INTO `words` VALUES (18604, '‘Okay, so maybe I was a little bit scared,’ Jenny admitted.', 'v. 承认； 准许…进入； 准许…加入', '/əd\'mit | əd\'mɪt/', 'admit', 4);
INSERT INTO `words` VALUES (18605, '...a few blocks of adobe houses.', 'n. 土坯， 泥砖', '/ə\'dəubi | \'ədobɪ/', 'adobe', 4);
INSERT INTO `words` VALUES (18606, 'Some young people suddenly become self-conscious and tongue-tied in early adolescence.', 'n. 青春，青春期', '/,ædəu\'lesəns,-sənsi | ædə\'les(ə)ns | ,ædə\'lɛsns/', 'adolescence', 4);
INSERT INTO `words` VALUES (18607, 'It is important that an adolescent boy should have an adult in whom he can confide.', 'adj. 青春期的； 青少年的; n. 青少年', '/ˌædə\'lesnt | ,ædə\'lɛsnt/', 'adolescent', 4);
INSERT INTO `words` VALUES (18608, 'Sally was adopted when she was four.', 'v. 收养；采用', '/ə\'dɔpt | ə\'dɒpt | ə\'dɑpt/', 'adopt', 4);
INSERT INTO `words` VALUES (18609, 'I simply adore chocolate.', 'v. 崇拜；非常喜爱', '/ə\'dɔ: | ə\'dɔː | ə\'dɔr/', 'adore', 4);
INSERT INTO `words` VALUES (18610, 'We received no advance warning of the storm.', 'adj. 预先的；; n. 前进， 前移； 增长， 提高； 预付', '/əd\'vɑːns | əd\'væns/', 'advance', 4);
INSERT INTO `words` VALUES (18611, 'advanced weapon systems', 'adj. 先进的', '/əd\'vɑːnst | əd\'vænst/', 'advanced', 4);
INSERT INTO `words` VALUES (18612, 'Younger workers tend to be at an advantage (= have an advantage ) when applying for jobs.', 'n. 优点， 优势', '/əd\'vɑːntɪdʒ | əd\'væntɪdʒ/', 'advantage', 4);
INSERT INTO `words` VALUES (18613, 'He was now in a more advantageous position.', 'adj. 有利的', '/ˌædvən\'teɪdʒəs | \'ædvən\'tedʒəs/', 'advantageous', 4);
INSERT INTO `words` VALUES (18614, 'the advent of the computer', 'n. 降临，出现', '/\'ædvənt/', 'advent', 4);
INSERT INTO `words` VALUES (18615, 'a great adventure', 'n. 冒险， 冒险活动； 异乎寻常的经历， 奇遇', '/əd\'ventʃə(r) | əd\'vɛntʃɚ/', 'adventure', 4);
INSERT INTO `words` VALUES (18616, 'Warren was an adventurous businessman.', 'adj. 喜欢冒险的， 敢作敢为的； 充满危险和刺激的， 惊险的', '/əd\'ventʃərəs | əd\'vɛntʃərəs/', 'adventurous', 4);
INSERT INTO `words` VALUES (18617, 'They fear it could have an adverse effect on global financial markets.', 'adj. 不利的；劣的', '/\'ædvə:s, æd\'və:s | \'ædvɜːs | ædˈvɚs, ˈædˌvɚs/', 'adverse', 4);
INSERT INTO `words` VALUES (18618, 'They no longer advertise alcohol or cigarettes at sporting events.', 'v. 做广告', '/\'ædvətaiz | \'ædvətaɪz | \'ædvɚtaɪz/', 'advertise', 4);
INSERT INTO `words` VALUES (18619, 'They put an advertisement in ‘The Morning News’, offering a high salary for the right person.', 'n. 广告， 公告； 广告活动， 宣传', '/əd\'vɜːtɪsmənt | ,ædvɚ\'taɪzmənt/', 'advertisement', 4);
INSERT INTO `words` VALUES (18620, 'You should have followed my advice.', 'n. 劝告， 忠告； 建议， 意见', '/əd\'vaɪs | ədˈvaɪs/', 'advice', 4);
INSERT INTO `words` VALUES (18621, 'Yet since the major task of students is study, it is advisable that they should focus on the teachers and textbooks in class and anyone using his or her cell phones in class should be punished.', 'n. 可取的， 适当的； 明智的', '/əd\'vaɪzəbl/', 'advisable', 4);
INSERT INTO `words` VALUES (18622, 'He was a strong advocate of free market policies and a multi-party system.', 'n. 辩护人；倡导者; v. 提倡，支持', '/\'ædvəkeit, \'ædvəkət | \'ædvəkeɪt；-ət | ˈædvəkeɪt；-et/', 'advocate', 4);
INSERT INTO `words` VALUES (18623, 'Stale. Lack of bouquet and freshness of a wine through too much aeration or infection with film yeasts.', 'n. 通风', '/ˌeə\'reɪʃn | ,eə\'reʃən/', 'aeration', 4);
INSERT INTO `words` VALUES (18624, 'Weeks of aerial bombardment had destroyed factories and motorways.', 'adj. 空气的；空中的 (无线电)天线', '/\'εəriəl | \'eərɪəl | \'ɛrɪəl/', 'aerial', 4);
INSERT INTO `words` VALUES (18625, 'Yoga has become the new aerobics and some people are getting it out of a book or video.', 'n. 有氧运动', '/eə\'rəubɪks | ɛ\'robɪks/', 'aerobics', 4);
INSERT INTO `words` VALUES (18626, 'If we in fact had the right level of investment in aeronautics, we would not currently be competing with Airbus.', 'n. 航空学', '/ˌeərə\'nɔːtɪks | ,ɛrə\'nɔtɪks/', 'aeronautics', 4);
INSERT INTO `words` VALUES (18627, 'The noise of the aeroplane deafened us.', 'n. 飞机', '/\'eərəpleɪn | ˈɛrəˌplen/', 'aeroplane', 4);
INSERT INTO `words` VALUES (18628, '...the U.S. aerospace industry.', 'n. 宇宙空间； 航空航天技术', '/\'eərəuspeɪs | \'ɛrospes/', 'aerospace', 4);
INSERT INTO `words` VALUES (18629, 'From an esthetic point of view, it’s a nice design.', 'adj. 美学的；艺术的', '/i:s\'θetik | iːs\'θetɪk; es- | ɛs\'θɛtɪk/', 'aesthetic', 4);
INSERT INTO `words` VALUES (18630, 'the areas affected by the hurricane', 'v. 影响', '/ə\'fekt, \'æfekt | ə\'fekt | ə\'fɛkt/', 'affect', 4);
INSERT INTO `words` VALUES (18631, 'She thought of him with affection.', 'n. 友好；爱情', '/ə\'fekʃən | ə\'fekʃ(ə)n | ə\'fɛkʃən/', 'affection', 4);
INSERT INTO `words` VALUES (18632, 'She affiliated herself with the Impressionist school of painting.', 'v. 使加入，接受为分支机构', '/ə\'filieit, ə\'filiit, -eit | ə\'fɪlɪeɪt | ə\'fɪlɪet/', 'affiliate', 4);
INSERT INTO `words` VALUES (18633, 'The court affirmed that the information can be made public under the Freedom of Information Act.', 'v. 断定，肯定', '/ə\'fə:m | ə\'fɜːm | ə\'fɝm/', 'affirm', 4);
INSERT INTO `words` VALUES (18634, 'We could reprint at a cost of X, or she had found a service that would affix stickers over the price to correct at a cost of X.', 'v. 附加；贴上；盖印; n. 词缀', '/ə\'fiks, \'æfiks | ə\'fɪks/', 'affix', 4);
INSERT INTO `words` VALUES (18635, NULL, 'v. 使痛苦，使苦恼', '/ə\'flikt | ə\'flɪkt/', 'afflict', 4);
INSERT INTO `words` VALUES (18636, 'Is verse 75 true of Joseph? Was the LORD afflicting him? Or was it Potiphar\'s wife who had afflicted him?', 'adj. 痛苦的', '/ə\'fliktiŋ | ə\'flɪktɪŋ/', 'afflicting', 4);
INSERT INTO `words` VALUES (18637, 'affluent families', 'adj. 丰富的， 富裕的', '/\'æflʊənt | \'æfluənt/', 'affluent', 4);
INSERT INTO `words` VALUES (18638, 'The room affords a beautiful view over the city.', 'v. 冒险；得起；供给', '/ə\'fɔ:d | ə\'fɔːd | ə\'fɔrd/', 'afford', 4);
INSERT INTO `words` VALUES (18639, 'They were exporting as far afield as Alexandria.', 'adv. 在野外， 在田中； 在战场上； 离乡背井地； 到远方， 在远处', '/ə\'fiːld | ə\'fild/', 'afield', 4);
INSERT INTO `words` VALUES (18640, 'We had to hire maids through an agency.', 'n. 代理商(社)', '/\'eidʒənsi | \'eɪdʒ(ə)nsɪ | \'edʒənsi/', 'agency', 4);
INSERT INTO `words` VALUES (18641, 'The Republicans have stuck to their conservative agenda.', 'n. 议事日程', '/ə\'dʒendə | ə\'dʒɛndə/', 'agenda', 4);
INSERT INTO `words` VALUES (18642, 'Their money problems were further aggravated by a rise in interest rates.', 'v. 使恶化；使加剧；使气恼', '/\'æɡrəveit | \'ægrəveɪt | \'æɡrəvet/', 'aggravate', 4);
INSERT INTO `words` VALUES (18643, NULL, 'n. 加重； 恶化； 愤怒， 恼怒', '/ˌægrə\'veɪʃn | ,ægrə\'veʃən/', 'aggravation', 4);
INSERT INTO `words` VALUES (18644, '(= as a group or in total ) , women outlive men by 7 or more years.', 'n. 共计，合计', '/\'æɡriɡət, \'æɡriɡeit | \'ægrɪgət; (for v.) ˈægrɪgeɪt | \'æɡrɪɡət; (for v.) æɡrɪˌɡet/', 'aggregate', 4);
INSERT INTO `words` VALUES (18645, 'A successful businessman has to be aggressive.', 'adj. 侵略的，有闯劲的', '/ə\'ɡresiv | ə\'gresɪv | ə\'ɡrɛsɪv/', 'aggressive', 4);
INSERT INTO `words` VALUES (18646, NULL, 'n. 侵略； 争斗； 攻击', '/ə\'gresɪvnɪs | ə\'grɛsɪvnɪs/', 'aggressiveness', 4);
INSERT INTO `words` VALUES (18647, 'Dogs are surprisingly agile.', 'adj. 敏捷的， 灵活的， 机敏的', '/\'ædʒaɪl | \'ædʒl/', 'agile', 4);
INSERT INTO `words` VALUES (18648, 'She was in a state of considerable agitation.', 'n. 摇动，焦虑', '/,ædʒi\'teiʃən | ædʒɪ\'teɪʃ(ə)n | ,ædʒɪ\'teʃən/', 'agitation', 4);
INSERT INTO `words` VALUES (18649, 'the agony of arthritis', 'n. 极度痛苦', '/\'æɡəni | \'ægənɪ/', 'agony', 4);
INSERT INTO `words` VALUES (18650, 'We spent a most agreeable couple of hours.', 'adj. 令人愉快的；乐于同意的', '/ə\'ɡri:əbl | ə\'griːəb(ə)l | ə\'ɡriəbl/', 'agreeable', 4);
INSERT INTO `words` VALUES (18651, 'Please read the agreement and sign it.', 'n. 同意；协议', '/ə\'ɡri:mənt | ə\'griːm(ə)nt | ə\'grimənt/', 'agreement', 4);
INSERT INTO `words` VALUES (18652, 'More than 75% of the land is used for agriculture.', 'n. 农业； 农学', '/\'ægrɪkʌltʃə(r) | \'æɡrɪkʌltʃɚ/', 'agriculture', 4);
INSERT INTO `words` VALUES (18653, 'minor ailments', 'n. 疾病', '/\'eɪlmənt | \'elmənt/', 'ailment', 4);
INSERT INTO `words` VALUES (18654, 'Let’s go outside and get some fresh air.', 'n. 空气', '/εə | eə | ɛr/', 'air', 4);
INSERT INTO `words` VALUES (18655, 'give them an airing.', 'n. 通风；讨论', '/\'εəriŋ | \'eərɪŋ | \'ɛrɪŋ/', 'airing', 4);
INSERT INTO `words` VALUES (18656, 'airtight containers', 'adj. 密闭的； 无懈可击的', '/\'eətaɪt | \'ɛrtaɪt/', 'airtight', 4);
INSERT INTO `words` VALUES (18657, 'Would you like a window seat or an aisle seat (= seat next to the aisle ) ?', 'n. 通道', '/ail | aɪl/', 'aisle', 4);
INSERT INTO `words` VALUES (18658, 'I forgot to set the burglar alarm.', 'n. 警报，惊慌; v. 使忧虑', '/ə\'lɑːm | ə\'lɑrm/', 'alarm', 4);
INSERT INTO `words` VALUES (18659, 'He accepted the job, albeit with some hesitation.', 'conj. 虽然， 尽管', '/ˌɔːl\'biːɪt | ,ɔl\'biɪt/', 'albeit', 4);
INSERT INTO `words` VALUES (18660, 'a photograph album', 'n. 集邮册；相片册', '/\'ælbəm/', 'album', 4);
INSERT INTO `words` VALUES (18661, 'Would you rather be an alchemist or a chemist?', 'n. 炼金术士', '/\'ælkəmɪst/', 'alchemist', 4);
INSERT INTO `words` VALUES (18662, 'I don’t drink alcohol anymore.', 'n. 含酒精饮料， 酒； 酒精', '/\'ælkəhɒl | \'ælkəhɔl/', 'alcohol', 4);
INSERT INTO `words` VALUES (18663, 'The animal raised its head, suddenly alert.', 'adj. 警惕的; n. 警戒；警报; vt. 警告', '/ə\'lɜːt | ə\'lɝt/', 'alert', 4);
INSERT INTO `words` VALUES (18664, 'On the basis of minimax algebra theory, this paper provides an algebra method of solving countable stages decision problems in the dynamic programming.', 'n. 代数', '/\'ældʒɪbrə/', 'algebra', 4);
INSERT INTO `words` VALUES (18665, 'illegal aliens entering the country.', 'n&a. 外侨；外国人的；不相容的', '/\'eiljən | \'eɪlɪən | ˈeliən,ˈeljən/', 'alien', 4);
INSERT INTO `words` VALUES (18666, 'The latest tax proposals will alienate many voters.', 'v. 离间，使疏远', '/\'eiljəneit | \'eɪlɪəneɪt/', 'alienate', 4);
