INSERT INTO `words` VALUES (19347, 'The new software is IBM compatible (= can be used with IBM computers ) .', 'adj. 可兼容的，可和谐共存的', '/kəm\'pætəbl | kəm\'pætɪb(ə)l/', 'compatible', 4);
INSERT INTO `words` VALUES (19348, 'Chris Robertson of Australia beat his compatriot Chris Dittmar in the final.', 'n. 同胞； 同国人', '/kəm\'pætriət | kəm\'petɪət/', 'compatriot', 4);
INSERT INTO `words` VALUES (19349, '...the introduction of legislation to compel cyclists to wear a helmet.', 'v. 强迫，迫使', '/kəm\'pel | kəm\'pɛl/', 'compel', 4);
INSERT INTO `words` VALUES (19350, 'The Roman Catholic Church has issued a compendium of its teachings.', 'n. 简要， 概略', '/kəm\'pendiəm | kəm\'pɛndɪəm/', 'compendium', 4);
INSERT INTO `words` VALUES (19351, 'Because my left eye is so weak, my right eye has to work harder to compensate.', 'v. 赔偿，补偿', '/\'kɔmpenseit | \'kɒmpenseɪt | \'kɑmpɛnset/', 'compensate', 4);
INSERT INTO `words` VALUES (19352, 'People who are wrongly arrested may be paid compensation .', 'n. 赔偿', '/,kɔmpen\'seiʃən | kɒmpen\'seɪʃ(ə)n | ,kɑmpɛn\'seʃən/', 'compensation', 4);
INSERT INTO `words` VALUES (19353, 'The banks have long competed with American Express\'s charge cards and various shop cards.', 'vi. 竞争； 比赛', '/kəm\'piːt | kəm\'pit/', 'compete', 4);
INSERT INTO `words` VALUES (19354, 'Typing is considered by most employers to be a basic competence.', 'n. 能力，胜任，权限', '/\'kɔmpitəns | \'kɒmpɪt(ə)ns | \'kɑmpɪtəns/', 'competence', 4);
INSERT INTO `words` VALUES (19355, 'A competent mechanic should be able to fix the problem.', 'adj. 有能力的； 能胜任的', '/\'kɒmpɪtnt | \'kɑmpɪtənt/', 'competent', 4);
INSERT INTO `words` VALUES (19356, 'Going to trade fairs is an ideal opportunity to size up the competition .', 'n. 比赛，比赛会', '/,kɔmpi\'tiʃən | kɒmpɪ\'tɪʃ(ə)n | ,kɑmpə\'tɪʃən/', 'competition', 4);
INSERT INTO `words` VALUES (19357, NULL, 'adj. 比赛的', '/kəm\'petitiv | kəm\'petɪtɪv | kəm\'pɛtətɪv/', 'competitive', 4);
INSERT INTO `words` VALUES (19358, 'The document was compiled by the Department of Health.', 'v. 编辑，编写', '/kəm\'pail | kəm\'paɪl/', 'compile', 4);
INSERT INTO `words` VALUES (19359, 'Residents are complaining because traffic in the area has increased.', 'v. 抱怨； 投诉', '/kəm\'pleɪn | kəm\'plen/', 'complain', 4);
INSERT INTO `words` VALUES (19360, 'If you wish to make a complaint, you should see the manager.', 'n. 抱怨； 投诉； 控告； 疾病', '/kəm\'pleɪnt | kəm\'plent/', 'complaint', 4);
INSERT INTO `words` VALUES (19361, 'The green wallpaper is the perfect complement to the old pine of the dresser.', 'n. 补足物，船上的定员；补语; v. 补充，补足', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪment/', 'complement', 4);
INSERT INTO `words` VALUES (19362, 'The computer and the human mind have different but complementary abilities.', 'adj. 互补的； 补充的， 补足的', '/ˌkɒmplɪ\'mentri | \'kɑmplə\'mɛntri/', 'complementary', 4);
INSERT INTO `words` VALUES (19363, 'The police were in complete control of the situation.', 'adj. 彻底的；完成的；绝对的; vt. 完成； 结束', '/kəm\'pliːt | kəm\'plit/', 'complete', 4);
INSERT INTO `words` VALUES (19364, 'a complex system of highways', 'adj. 复杂的; n. 复合体；变态心理', '/\'kɔmpleks | \'kɒmpleks | kəm\'plɛks; \'kɑm,plɛks/', 'complex', 4);
INSERT INTO `words` VALUES (19365, 'Drinking water is good for the complexion.', 'n. 肤色；情况；局面；气质', '/kəm\'plekʃən | kəm\'plekʃ(ə)n | kəm\'plɛkʃən/', 'complexion', 4);
INSERT INTO `words` VALUES (19366, 'a design of great complexity', 'n. 复杂， 复杂性； 复杂的事物', '/kəm\'pleksəti | kəm\'plɛksəti/', 'complexity', 4);
INSERT INTO `words` VALUES (19367, 'Inspectors were sent to visit nuclear sites and verify compliance with the treaty.', 'n. 遵守，依从', '/kəm\'plaiəns | kəm\'plaɪəns/', 'compliance', 4);
INSERT INTO `words` VALUES (19368, 'The situation is complicated by the fact that I’ve got to work late on Friday.', 'vt. 使变复杂', '/\'kɒmplɪkeɪt | \'kɑmplɪket/', 'complicate', 4);
INSERT INTO `words` VALUES (19369, 'a complicated pattern', 'adj. 结构复杂的；困难的', '/\'kɔmplikeitid | \'kɒmplɪkeɪtɪd | \'kɑmplɪketɪd/', 'complicated', 4);
INSERT INTO `words` VALUES (19370, 'The fact that the plane was late added a further complication to our journey.', 'n. 结构复杂，麻烦', '/,kɔmpli\'keiʃən | kɒmplɪ\'keɪʃ(ə)n | ,kɑmplɪ\'keʃən/', 'complication', 4);
INSERT INTO `words` VALUES (19371, 'With the compliments of J. Smith & Son. J.', 'n. 敬意，赞扬；问候; v. 恭维；称赞', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪmənt/', 'compliment', 4);
INSERT INTO `words` VALUES (19372, 'The newspaper was asked by federal agents for assistance and agreed to comply.', 'v. 遵守，照做', '/kəm\'plai | kəm\'plaɪ/', 'comply', 4);
INSERT INTO `words` VALUES (19373, 'companies that make electronic components for computer products', 'n. 组成部分；零件', '/kəm\'pəunənt | kəm\'pəʊnənt | kəm\'ponənt/', 'component', 4);
INSERT INTO `words` VALUES (19374, 'Barrington has composed the music for a new production of ‘A Midsummer Night’s Dream’.', 'v. 组成，构成；创作；排字；使安静', '/kəm\'pəuz | kəm\'pəʊz | kəm\'poz/', 'compose', 4);
INSERT INTO `words` VALUES (19375, 'The author builds up a useful compo-site picture of contemporary consumer culture.', 'adj. 合成的，复合的', '/\'kɔmpəzit | \'kɒmpəzɪt | kɑm\'pɑzɪt/', 'composite', 4);
INSERT INTO `words` VALUES (19376, 'Some minerals have complex chemical compositions.', 'n. 作品； 写作， 作曲； 结构， 组成， 成分', '/ˌkɒmpə\'zɪʃn | ,kɑmpə\'zɪʃən/', 'composition', 4);
INSERT INTO `words` VALUES (19377, 'man-made organic compounds', 'n&a. 混合物(的)，复合词(的)；院子(的)', '/\'kɒmpaʊnd | \'kɑmpaʊnd/', 'compound', 4);
INSERT INTO `words` VALUES (19378, 'Why you let her talk you into doing such a foolish thing is beyond my comprehension (= impossible for me to understand ) .', 'n. 理解； 理解力', '/ˌkɒmprɪ\'henʃn | ,kɑmprɪ\'hɛnʃən/', 'comprehension', 4);
INSERT INTO `words` VALUES (19379, 'We offer our customers a comprehensive range of financial products.', 'adj. 全面的， 广泛的； 综合的； 包容的', '/ˌkɒmprɪ\'hensɪv | ˌkɑːmprɪˈhensɪv/', 'comprehensive', 4);
INSERT INTO `words` VALUES (19380, 'Light silk is best for parachutes, as it compresses well and then expands rapidly.', 'v. 使语言精炼，压缩', '/kəm\'pres, \'kɔmpres | kəm\'pres | kəm\'prɛs/', 'compress', 4);
INSERT INTO `words` VALUES (19381, 'The house comprises two bedrooms, a kitchen, and a living room.', 'n. (止血用)敷布', '/kəm\'praiz | kəm\'praɪz/', 'comprise', 4);
INSERT INTO `words` VALUES (19382, 'Compromise is an inevitable part of marriage.', 'n. 妥协，折衷; v. 妥协；使遭受危害', '/\'kɔmprəmaiz | \'kɒmprəmaɪz | \'kɑmprəmaɪz/', 'compromise', 4);
INSERT INTO `words` VALUES (19383, NULL, 'adv. 强制地； 禁不住地', '/kəm\'pʌlsivli | kəm\'pʌlsɪvli/', 'compulsively', 4);
INSERT INTO `words` VALUES (19384, 'the threat of compulsory redundancies', 'adj. 义务的；强制的', '/kəm\'pʌlsəri | kəm\'pʌls(ə)rɪ/', 'compulsory', 4);
INSERT INTO `words` VALUES (19385, 'Final results had not yet been computed.', 'v. 计算，估计', '/kəm\'pju:t | kəm\'pjuːt | kəm\'pjʊt/', 'compute', 4);
INSERT INTO `words` VALUES (19386, 'a scheme to computerize the library service', 'vt. 使计算机化； 用计算机做； 用计算机储存', '/kəm\'pjuːtəraɪz | kəm\'pjutəraɪz/', 'computerize', 4);
INSERT INTO `words` VALUES (19387, 'The shadows concealed her as she crept up to the house.', 'v. 隐藏，隐蔽', '/kən\'si:l | kən\'siːl | kən\'sil/', 'conceal', 4);
INSERT INTO `words` VALUES (19388, '‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.', 'v. 承认; 给予', '/kən\'si:d | kən\'siːd | kən\'sid/', 'concede', 4);
INSERT INTO `words` VALUES (19389, 'Scientists first conceived the idea of the atomic bomb in the 1930’s.', 'v. 想出(主意)；怀孕', '/kən\'si:v | kən\'siːv | kən\'siv/', 'conceive', 4);
INSERT INTO `words` VALUES (19390, 'Now please concentrate.', 'v. 集中，全神贯注于；浓缩; n. 浓缩物', '/\'kɔnsəntreit | \'kɒns(ə)ntreɪt | \'kɑnsn\'tret/', 'concentrate', 4);
INSERT INTO `words` VALUES (19391, 'She needed all her powers of concentration to stop herself from slipping on the icy road.', 'n. 集中； 专心， 专注； 浓缩， 浓度', '/ˌkɒnsn\'treɪʃn | \'kɑnsn\'treʃən/', 'concentration', 4);
INSERT INTO `words` VALUES (19392, 'a new concept in business travel', 'n. 概念， 观念； 设想', '/\'kɒnsept | \'kɑnsɛpt/', 'concept', 4);
INSERT INTO `words` VALUES (19393, 'the original conception of the book', 'n. 概念的形成，概念，想法；怀孕', '/kən\'sepʃən | kən\'sepʃ(ə)n | kən\'sɛpʃən/', 'conception', 4);
INSERT INTO `words` VALUES (19394, 'the conceptual framework of the play', 'adj. 观念的， 概念的', '/kən\'septʃʊəl | kən\'sɛptʃʊəl/', 'conceptual', 4);
INSERT INTO `words` VALUES (19395, 'He was moved by her obvious concern.', '\"n. 所关切的事；企业；关心v影响,涉及,关心; n. \"', '/kən\'sɜːn | kən\'sɝn/', 'concern', 4);
INSERT INTO `words` VALUES (19396, 'a rock concert', 'n. 音乐会， 演奏会', '/\'kɒnsət | \'kɑnsɚt/', 'concert', 4);
INSERT INTO `words` VALUES (19397, 'Libraries have made a concerted effort to attract young people.', 'adj. 商定的，一致的', '/kən\'sə:tid | kən\'sɜːtɪd | kən\'sɝtɪd/', 'concerted', 4);
INSERT INTO `words` VALUES (19398, 'The British were not prepared to make any concessions .', 'n. 让步，让与物', '/kən\'seʃən | kən\'seʃ(ə)n | kən\'sɛʃən/', 'concession', 4);
INSERT INTO `words` VALUES (19399, 'Your summary should be as clear and concise as possible.', 'adj. 简明的，简要的', '/kən\'sais | kən\'saɪs/', 'concise', 4);
INSERT INTO `words` VALUES (19400, 'To conclude, I’d like to express my thanks to my family.', 'v. 推断出； 作结论', '/kən\'kluːd | kən\'klud/', 'conclude', 4);
INSERT INTO `words` VALUES (19401, 'These are the report’s main conclusions.', 'n. 结论， 推论； 结束， 结尾； 【法】 缔结， 议定', '/kən\'kluːʒn | kən\'kluʒn/', 'conclusion', 4);
INSERT INTO `words` VALUES (19402, 'John concocted an elaborate excuse for being late.', 'v. 调合；编造(故事等)', '/kən\'kɔkt | kən\'kɒkt | kən\'kɑkt/', 'concoct', 4);
INSERT INTO `words` VALUES (19403, 'The posts have to be set in concrete.', 'n. 混凝土; adj. 有形的；具体的; v. 浇混凝土于', '/kən\'kri:t, \'kɔnkri:t | \'kɒŋkriːt | \'kɑŋkrit/', 'concrete', 4);
INSERT INTO `words` VALUES (19404, 'Local feeling does not necessarily concur with the press.', 'v. 同时发生； 意见相同， 一致', '/kən\'kɜː(r) | kən\'kɝ/', 'concur', 4);
INSERT INTO `words` VALUES (19405, 'Politicians were quick to condemn the bombing.', 'v. 谴责，迫使；判刑；宣告(建筑)不宜使用', '/kən\'dem | kən\'dɛm/', 'condemn', 4);
INSERT INTO `words` VALUES (19406, 'He used his sleeve to wipe the condensation off the glass.', 'n. 浓缩， 凝结', '/ˌkɒnden\'seɪʃn | ,kɑndɛn\'seʃən/', 'condensation', 4);
INSERT INTO `words` VALUES (19407, 'the mist which condensed on every cold surface', 'v. 浓缩；冷凝；精简', '/kən\'dens | kən\'dɛns/', 'condense', 4);
INSERT INTO `words` VALUES (19408, 'Conditions in the prison were atrocious.', 'n. 条件，状况，环境; v. 决定；支配；训练', '/kən\'diʃən | kən\'dɪʃ(ə)n | kən\'dɪʃən/', 'condition', 4);
INSERT INTO `words` VALUES (19409, NULL, 'n. 护发素， 护发剂； 调节物； 调节器， 调节装置', '/kən\'dɪʃənə(r) | kən\'dɪʃənɚ/', 'conditioner', 4);
INSERT INTO `words` VALUES (19410, 'a letter of condolence', 'n. 吊唁，慰问；吊慰', '/kən\'dəuləns | kən\'dəʊl(ə)ns | kən\'doləns/', 'condolence', 4);
INSERT INTO `words` VALUES (19411, 'I cannot condone the use of violence under any circumstances.', 'v. 宽恕， 赦免； 纵容， 容忍', '/kən\'dəun | kən\'don/', 'condone', 4);
INSERT INTO `words` VALUES (19412, NULL, 'v. 有益于， 有助于； 导致', '/kən\'djuːs | kən\'dju:s/', 'conduce', 4);
INSERT INTO `words` VALUES (19413, 'an environment conducive to learning', 'adj. 有助于的；有益于的', '/kən\'dju:siv | kən\'djuːsɪv | kən\'dusɪv/', 'conducive', 4);
INSERT INTO `words` VALUES (19414, 'Who will be conducting?', 'v. 指导； 管理， 实施； 指挥; n. 举止；指导；管理[kən\'dʌkt]', '/\'kɒndʌkt | kən\'dʌkt/', 'conduct', 4);
INSERT INTO `words` VALUES (19415, 'Copper is a very conductive metal.', 'adj. 能传导电的， 导电的', '/kən\'dʌktɪv/', 'conductive', 4);
INSERT INTO `words` VALUES (19416, 'The constitution also confers large powers on Brazil\'s 25 constituent states.', 'v. 授予(称号，学位等)；协商', '/kən\'fə: | kən\'fɜː | kən\'fɝ/', 'confer', 4);
INSERT INTO `words` VALUES (19417, 'Representatives from over 100 countries attended the International Peace Conference in Geneva.', 'n. 会议', '/\'kɒnfərəns | \'kɑnfərəns/', 'conference', 4);
INSERT INTO `words` VALUES (19418, 'Occasionally people confess to crimes they haven’t committed just to get attention.', 'v. 承认；向祖父忏悔', '/kən\'fes | kən\'fɛs/', 'confess', 4);
INSERT INTO `words` VALUES (19419, 'I felt I was doing well and my confidence began to grow.', 'n. 信任，信心，自信; adj. 骗得信任的', '/\'kɔnfidəns | \'kɒnfɪd(ə)ns | \'kɑnfɪdəns/', 'confidence', 4);
INSERT INTO `words` VALUES (19420, 'Despite her disability, Philippa is very confident.', 'adj. 确信的，有把握的', '/\'kɔnfidənt | \'kɒnfɪd(ə)nt | \'kɑnfɪdənt/', 'confident', 4);
INSERT INTO `words` VALUES (19421, 'a confidential government report', 'adj. 机密的；信任的', '/,kɔnfi\'denʃəl | kɒnfɪ\'denʃ(ə)l | ,kɑnfɪ\'dɛnʃl/', 'confidential', 4);
INSERT INTO `words` VALUES (19422, '...Stonehenge, in southwestern England, an ancient configuration of giant stones.', 'n. 配置，布局；构造', '/kən,fiɡju\'reiʃən | kən,fɪgə\'reɪʃ(ə)n; -gjʊ- | kən,fɪɡjə\'reʃən/', 'configuration', 4);
INSERT INTO `words` VALUES (19423, 'Vaughan is confined to a wheelchair .', 'v. 限制，禁闭', '/kən\'faɪn/', 'confine', 4);
INSERT INTO `words` VALUES (19424, 'X-rays have confirmed that he has not broken any bones.', 'v. (权力)使巩固；认可(任命)', '/kən\'fə:m | kən\'fɜːm | kən\'fɝm/', 'confirm', 4);
INSERT INTO `words` VALUES (19425, 'Most hotels require confirmation from a prospective guest in writing.', 'n. 证实， 确认； 批准', '/ˌkɒnfə\'meɪʃn | ,kɑnfɚ\'meʃən/', 'confirmation', 4);
INSERT INTO `words` VALUES (19426, 'efforts to resolve the conflict', 'n. 战斗；斗争；意见(分歧)', '/kən\'flikt, \'kɔnflikt | \'kɒnflɪkt | \'kɑnflɪkt/', 'conflict', 4);
INSERT INTO `words` VALUES (19427, 'the pressure on schoolchildren to conform', 'v. 遵从，符合', '/kən\'fɔ:m | kən\'fɔːm | kən\'fɔrm/', 'conform', 4);
INSERT INTO `words` VALUES (19428, 'We must act in conformity with local regulations.', 'n. 符合， 一致', '/kən\'fɔːməti | kən\'fɔrməti/', 'conformity', 4);
INSERT INTO `words` VALUES (19429, 'The problems confronting the new government were enormous.', 'v. 使面对；面临', '/kən\'frʌnt/', 'confront', 4);
INSERT INTO `words` VALUES (19430, 'People might well confuse the two products.', 'v. 使混乱，弄错', '/kən\'fju:z | kən\'fjuːz | kən\'fjʊz/', 'confuse', 4);
INSERT INTO `words` VALUES (19431, 'To avoid confusion, the teams wore different colours.', 'n. 混乱，混同', '/kən\'fju:ʒən | kən\'fjuːʒ(ə)n | kən\'fjʊʒən/', 'confusion', 4);
INSERT INTO `words` VALUES (19432, 'congested airspace', 'adj. 拥挤不堪的； 充塞的', '/kən\'dʒestɪd | kən\'dʒɛstɪd/', 'congested', 4);
INSERT INTO `words` VALUES (19433, 'The problems of traffic congestion will not disappear in a hurry.', 'n. 拥挤，混杂', '/kən\'dʒestʃ(ə)n | kən\'dʒɛstʃən/', 'congestion', 4);
INSERT INTO `words` VALUES (19434, 'He never even stopped to congratulate me.', 'vt. 祝贺', '/kən\'grætʃʊleɪt | kən\'ɡrætʃulet/', 'congratulate', 4);
INSERT INTO `words` VALUES (19435, 'a congress of the ruling Labor Party', 'n. 代表会议，(C-)(美国等)议会', '/\'kɔŋɡres, kən\'ɡres | \'kɒŋgres | \'kɑŋɡrəs/', 'congress', 4);
INSERT INTO `words` VALUES (19436, 'They want to work in an organization whose values are congruent with their own.', 'adj. 适合的，一致的，全等的', '/\'kɒŋgrʊənt | \'kɑŋɡruənt/', 'congruent', 4);
INSERT INTO `words` VALUES (19437, 'The two clauses are joined by a conjunction.', 'n. 连词；联合；连接', '/kən\'dʒʌŋkʃən | kən\'dʒʌŋ(k)ʃ(ə)n/', 'conjunction', 4);
INSERT INTO `words` VALUES (19438, 'We’d like two rooms with connecting doors (= doors that join the rooms ) .', 'v. 连接， 衔接； 联合， 关联； 由…联想到； 给…接通电话', '/kə\'nekt | kə\'nɛkt/', 'connect', 4);
INSERT INTO `words` VALUES (19439, 'Police have so far failed to establish a connection between the two murders.', 'n. 连接； 关系', '/kə\'nekʃn | kə\'nɛkʃən/', 'connection', 4);
INSERT INTO `words` VALUES (19440, 'The Normans conquered England in 1066.', 'v. 征服；攻克', '/\'kɔŋkə | \'kɒŋkə | \'kɑŋkɚ/', 'conquer', 4);
INSERT INTO `words` VALUES (19441, 'the Norman Conquest (= the conquest of England by the Normans )', 'n. 征服，征服地，掠取物', '/\'kɔŋkwest | \'kɒŋkwest | \'kɑŋkwɛst/', 'conquest', 4);
INSERT INTO `words` VALUES (19442, 'Well, at least I can face them all with a clear conscience (= the knowledge that you have done nothing wrong ) .', 'n. 良心，犯罪感', '/\'kɔnʃəns | \'kɒnʃ(ə)ns | ˈkɑːnʃəns/', 'conscience', 4);
INSERT INTO `words` VALUES (19443, 'A conscientious teacher may feel inclined to take work home.', 'adj. 认真的，诚心诚意的', '/,kɔnʃi\'enʃəs | ,kɒnʃɪ\'enʃəs | \'kɑnʃɪ\'ɛnʃəs/', 'conscientious', 4);
INSERT INTO `words` VALUES (19444, 'The driver was still conscious when the ambulance arrived.', 'adj. 清醒的；故意的', '/\'kɔnʃəs | \'kɒnʃəs | \'kɑnʃəs/', 'conscious', 4);
INSERT INTO `words` VALUES (19445, 'It had rained for four consecutive days.', 'adj. 连续的，连贯的', '/kən\'sekjutiv | kən\'sekjʊtɪv | kən\'sɛkjətɪv/', 'consecutive', 4);
INSERT INTO `words` VALUES (19446, 'The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.', 'n. 一致，合意', '/kən\'sensəs | kən\'sɛnsəs/', 'consensus', 4);
INSERT INTO `words` VALUES (19447, 'He took the car without the owner’s consent .', 'vi&n. 同意，允许', '/kən\'sent | kən\'sɛnt/', 'consent', 4);
