INSERT INTO `words` VALUES (19761, 'It seems clear that despite official denials, differences of opinion lay behind the ambassador\'s decision to quit.', 'n. 拒绝，否认，否定', '/di\'naiəl | dɪ\'naɪ(ə)l | dɪ\'naɪəl/', 'denial', 4);
