INSERT INTO `words` VALUES (19763, 'What does the word ‘curriculum’ denote that ‘course’ does not?', 'v. 是的符号，提示，表示', '/di\'nəut | dɪ\'nəʊt | dɪ\'not/', 'denote', 4);
INSERT INTO `words` VALUES (19764, 'The group denounced the failure by the authorities to take action.', 'v. 谴责，斥责', '/di\'nauns | dɪ\'naʊns/', 'denounce', 4);
