INSERT INTO `words` VALUES (19869, 'Criminal behaviour can be linked to economic disadvantage.', 'n. 缺点， 不利', '/ˌdɪsəd\'vɑːntɪdʒ | ,dɪsəd\'væntɪdʒ/', 'disadvantage', 4);
INSERT INTO `words` VALUES (19870, 'Barr strongly disagreed with Kronfeld’s statement.', 'v. 不同意； 不一致', '/ˌdɪsə\'griː | ,dɪsə\'ɡri/', 'disagree', 4);
INSERT INTO `words` VALUES (19871, 'disappointing profit figures', 'adj. 令人失望的', '/ˌdɪsə\'pɔɪntɪŋ | ,dɪsə\'pɔɪntɪŋ/', 'disappointing', 4);
INSERT INTO `words` VALUES (19872, 'I knew my parents would disapprove, but I went anyway.', 'v. 不赞成， 反对', '/ˌdɪsə\'pruːv | \'dɪsə\'prʊv/', 'disapprove', 4);
INSERT INTO `words` VALUES (19873, 'The nation is in disarray following rioting led by the military.', 'n&vt. 弄乱，扰乱', '/,disə\'rei | dɪsə\'reɪ/', 'disarray', 4);
INSERT INTO `words` VALUES (19874, 'One hundred and twenty people died in China’s worst air disaster .', 'n. 灾难，祸患', '/,di\'zɑ:stə | dɪ\'zɑːstə | dɪ\'zæstɚ/', 'disaster', 4);
INSERT INTO `words` VALUES (19875, 'a disastrous first marriage', 'adj. 损失惨重的， 灾难性的； 极坏的', '/dɪ\'zɑːstrəs | dɪ\'zæstrəs/', 'disastrous', 4);
INSERT INTO `words` VALUES (19876, 'three keys attached to a metal disc', 'n. 圆盘，圆面，磁盘；椎间盘', '/disk | dɪsk/', 'disc', 4);
INSERT INTO `words` VALUES (19877, 'Read the manufacturer\'s guidelines before discarding the box.', 'v. 抛弃，遗弃', '/dis\'kɑ:d, \'diskɑ:d | dɪ\'skɑːd | dɪsˈkɑːrd/', 'discard', 4);
INSERT INTO `words` VALUES (19878, 'We could just discern a town in the distance.', 'v. 看出，辨出', '/di\'sə:n, -\'zə:n | dɪ\'sɜːn | dɪ\'sɝn/', 'discern', 4);
INSERT INTO `words` VALUES (19879, 'an ideal tour for the discerning traveller', 'adj. 有识别力的， 眼光敏锐的', '/dɪ\'sɜːnɪŋ | dɪ\'sɝnɪŋ/', 'discerning', 4);
INSERT INTO `words` VALUES (19880, 'Hospitals now tend to discharge patients earlier than in the past.', 'v&n. 卸货；排出(液体，气体)；释放', '/dis\'tʃɑ:dʒ, \'distʃɑ:dʒ, dis\'tʃ- | dɪs\'tʃɑːdʒ | dɪs\'tʃɑrdʒ/', 'discharge', 4);
INSERT INTO `words` VALUES (19881, 'The book gives parents advice on discipline.', 'n&vt. 训练，纪律，戒律，惩罚', '/\'disiplin | \'dɪsɪplɪn | \'dɪsəplɪn/', 'discipline', 4);
INSERT INTO `words` VALUES (19882, 'Some companies have already voluntarily disclosed similar information .', 'v. 透露，泄露', '/dis\'kləuz | dɪs\'kləʊz | dɪs\'kloz/', 'disclose', 4);
INSERT INTO `words` VALUES (19883, 'Bus route 51 is being discontinued.', 'v. 停止； 中断； 不连续', '/ˌdɪskən\'tɪnjuː | ,dɪskən\'tɪnju/', 'discontinue', 4);
INSERT INTO `words` VALUES (19884, 'marital discord', 'n. 不和，争吵，(声音)不和谐', '/\'diskɔ:d, dis\'kɔ:d | \'dɪskɔːd | \'dɪskɔrd/', 'discord', 4);
INSERT INTO `words` VALUES (19885, 'They are often available at a discount.', 'n. 折扣; v. 不全信，低估，漠视', '/[\'diskaunt, dis\'k-] | \'dɪskaʊnt | dɪs\'kaʊnt/', 'discount', 4);
INSERT INTO `words` VALUES (19886, 'You should not let one failure discourage you.', 'vt. 使泄气， 使灰心； 阻止， 劝阻', '/dɪs\'kʌrɪdʒ | dɪs\'kɝɪdʒ/', 'discourage', 4);
INSERT INTO `words` VALUES (19887, 'It would be discourteous to ignore his request.', 'adj. 无礼的， 粗鲁的', '/dɪs\'kɜːtɪəs | dɪs\'kɝtɪəs/', 'discourteous', 4);
INSERT INTO `words` VALUES (19888, 'The body was discovered in a field.', 'vt. 发现， 找到； 发觉', '/dɪ\'skʌvə(r) | dɪ\'skʌvɚ/', 'discover', 4);
INSERT INTO `words` VALUES (19889, 'I felt I\'d made an incredible discovery.', 'n. 发现', '/dɪ\'skʌvəri/', 'discovery', 4);
INSERT INTO `words` VALUES (19890, '...a secret unit within the company that had been set up to discredit its major rival.', 'vt. 使怀疑； 使丧失信誉， 使丢脸', '/dɪs\'kredɪt | dɪs\'krɛdɪt/', 'discredit', 4);
INSERT INTO `words` VALUES (19891, 'He assured her that he would be discreet.', 'adj. 谨慎的，思虑两全的', '/dis\'kri:t | dɪ\'skriːt | dɪ\'skrit/', 'discreet', 4);
INSERT INTO `words` VALUES (19892, '...the discrepancy between press and radio reports.', 'n. 不一致，差异，不符', '/dis\'krepənsi | dɪs\'krep(ə)nsɪ | dɪs\'krɛpənsi/', 'discrepancy', 4);
INSERT INTO `words` VALUES (19893, 'The change happens in a series of discrete steps.', 'adj. 分离的，不相关联的', '/dis\'kri:t | dɪ\'skriːt | dɪ\'skrit/', 'discrete', 4);
INSERT INTO `words` VALUES (19894, 'British newspapers no longer feel they must treat the royal family with discretion.', 'n. 判断力； 谨慎， 审慎； 明智', '/dɪ\'skreʃn | dɪ\'skrɛʃən/', 'discretion', 4);
INSERT INTO `words` VALUES (19895, 'He is incapable of discriminating between a good idea and a terrible one.', 'v. 区别，区分；岐视', '/dɪ\'skrɪmɪneɪt | dɪ\'skrɪmɪnet/', 'discriminate', 4);
INSERT INTO `words` VALUES (19896, 'a look of complete disdain', 'vt&n. 蔑视, 轻视 \"', '/dis\'dein | dɪs\'deɪn; -z- | dɪs\'den/', 'disdain', 4);
INSERT INTO `words` VALUES (19897, NULL, 'vt. 使失去权力或影响', '/disim\'pauə | ˌdɪsɪm\'pauə(r)/', 'disempower', 4);
INSERT INTO `words` VALUES (19898, 'There is growing public disenchantment with the educational system.', 'n. 失望， 不抱幻想', '/ˌdɪsɪn\'tʃɑːntmənt | ,dɪsɪn\'tʃæntmənt/', 'disenchantment', 4);
INSERT INTO `words` VALUES (19899, 'His face had been disfigured in an accident.', 'vt. 使毁容， 使变丑', '/dɪs\'fɪgə(r) | dɪs\'fɪɡjɚ/', 'disfigure', 4);
INSERT INTO `words` VALUES (19900, 'He escaped across the border disguised as a priest.', 'vt/n. 假扮；隐蔽；掩饰', '/dis\'ɡaiz | dɪs\'gaɪz | dɪs\'ɡaɪz/', 'disguise', 4);
INSERT INTO `words` VALUES (19901, 'He reached into the bin with a look of disgust on his face.', 'n&vt. 厌恶，讨厌', '/dis\'ɡʌst | dɪs\'gʌst | dɪs\'ɡʌst/', 'disgust', 4);
INSERT INTO `words` VALUES (19902, '...racial disharmony.', 'n. 不一致； 不和谐', '/ˌdɪs\'hɑːməni | dɪs\'hɑrməni/', 'disharmony', 4);
INSERT INTO `words` VALUES (19903, 'I hate to disillusion you, but I don’t think she’s coming back.', 'vt. 使醒悟', '/ˌdɪsɪ\'luːʒn | ,dɪsɪ\'luʒn/', 'disillusion', 4);
INSERT INTO `words` VALUES (19904, 'Polls have charted growing disillusionment with the campaign.', 'n. 幻灭； 觉醒， 醒悟', '/ˌdɪsɪ\'luːʒnmənt | ,dɪsɪ\'luʒnmənt/', 'disillusionment', 4);
INSERT INTO `words` VALUES (19905, 'The plane just disintegrated in mid-air.', 'v. 碎裂， 瓦解， 解体', '/dɪs\'ɪntɪgreɪt | dɪs\'ɪntɪɡret/', 'disintegrate', 4);
INSERT INTO `words` VALUES (19906, 'He asked for immediate help from the United States to dismantle the warheads.', 'vt. 拆除； 废除， 取消', '/dɪs\'mæntl/', 'dismantle', 4);
INSERT INTO `words` VALUES (19907, NULL, 'n&vt. 灰心丧气；惊愕', '/dis\'mei | dɪs\'meɪ | dɪs\'me/', 'dismay', 4);
INSERT INTO `words` VALUES (19908, 'The government has dismissed criticisms that the country’s health policy is a mess.', 'v. 解散；解雇；不考虑；消除', '/dɪs\'mɪs/', 'dismiss', 4);
INSERT INTO `words` VALUES (19909, 'You disobeyed my orders.', 'v. 不服从， 违抗', '/ˌdɪsə\'beɪ | \'dɪsə\'be/', 'disobey', 4);
INSERT INTO `words` VALUES (19910, 'severe eating disorders such as bulimia and anorexia', 'n&vt. 混乱，骚动，(身心)失调', '/dis\'ɔ:də | dɪs\'ɔːdə | dɪs\'ɔrdɚ/', 'disorder', 4);
INSERT INTO `words` VALUES (19911, 'An overnight stay at a friend\'s house disorientates me.', 'vt. 使失去方向感； 使迷茫， 使不知所措', '/dis\'ɔ:rienteit | dɪs\'ɔːriənteɪt/', 'disorientate', 4);
INSERT INTO `words` VALUES (19912, 'Matcham’s theatres were widely disparaged by architects.', 'vt. 贬抑， 贬低； 轻蔑， 轻视', '/dɪ\'spærɪdʒ/', 'disparage', 4);
INSERT INTO `words` VALUES (19913, 'Goods are normally dispatched within 24 hours.', 'v&n. 派遣，发送，迅速办理，急件', '/dis\'pætʃ | dɪˈspætʃ | dɪ\'spætʃ/', 'dispatch', 4);
INSERT INTO `words` VALUES (19914, 'We want to dispel the myth that you cannot eat well in Britain.', 'v. 驱逐，消除', '/dis\'pel | dɪ\'spel | dɪ\'spɛl/', 'dispel', 4);
INSERT INTO `words` VALUES (19915, 'a machine for dispensing cash', 'vt. 分发， 分配； 提供', '/dɪ\'spens | dɪ\'spɛns/', 'dispense', 4);
INSERT INTO `words` VALUES (19916, 'a paper towel dispenser', 'n. 药剂师， 配药师； 分配者， 施予者； 自动售货机', '/dɪs\'pensə(r) | dɪ\'spɛnsɚ/', 'dispenser', 4);
INSERT INTO `words` VALUES (19917, 'the role of birds in the dispersal of seeds', 'n. 散布， 分散； 消散， 疏散', '/dɪ\'spɜːsl | dɪ\'spɝsl/', 'dispersal', 4);
INSERT INTO `words` VALUES (19918, 'Police used tear gas to disperse the crowd.', 'v. (使)散开，使疏开，使分散', '/dis\'pə:s | dɪ\'spɜːs | dɪ\'spɝs/', 'disperse', 4);
INSERT INTO `words` VALUES (19919, 'It\'s very dispiriting for anyone to be out of a job.', 'adj. 令人沮丧的， 使人气馁的', '/dɪ\'spɪrɪtɪŋ/', 'dispiriting', 4);
INSERT INTO `words` VALUES (19920, 'Coal has been displaced by natural gas as a major source of energy.', 'v. 转移，取代', '/dis\'pleis | dɪs\'pleɪs | dɪs\'ples/', 'displace', 4);
INSERT INTO `words` VALUES (19921, 'a dazzling display (= very good display ) of flowers', 'vt&n. 展览，陈列', '/,dis\'plei | dɪ\'spleɪ | dɪ\'sple/', 'display', 4);
INSERT INTO `words` VALUES (19922, 'disposable nappies', 'adj. 一次性的； 可动用的', '/dɪ\'spəuzəbl | dɪ\'spozəbl/', 'disposable', 4);
INSERT INTO `words` VALUES (19923, 'bomb disposal experts', 'n. 处理， 处置； 布置， 安排', '/dɪ\'spəuzl | dɪ\'spozl/', 'disposal', 4);
INSERT INTO `words` VALUES (19924, 'Chinese vases are disposed around the gallery.', 'v. 处理，处置，除去', '/dis\'pəuz | dɪ\'spəʊz | dɪ\'spoz/', 'dispose', 4);
INSERT INTO `words` VALUES (19925, 'the disposition of assets on death', 'n. 性情，气质；布置；配置', '/,dispə\'ziʃən | dɪspə\'zɪʃ(ə)n | \'dɪspə\'zɪʃən/', 'disposition', 4);
INSERT INTO `words` VALUES (19926, 'It is beyond dispute that advances in medicine have enabled people to live longer.', 'v&n. 争论，争执，质疑', '/dis\'pju:t, \'dis- | dɪ\'spjuːt; \'dɪspjuːt | \'dɪs\'pjʊt/', 'dispute', 4);
INSERT INTO `words` VALUES (19927, 'Thomson was disqualified from the 400 metre freestyle.', 'vt. 使丧失资格', '/dɪs\'kwɒlɪfaɪ | dɪs\'kwɑlə\'fai/', 'disqualify', 4);
INSERT INTO `words` VALUES (19928, 'He ordered the jury to disregard the witness’s last statement.', 'vt&n. 不理，漠视', '/disri\'ɡɑ:d | dɪsrɪ\'gɑːd | ,dɪsrɪ\'ɡɑrd/', 'disregard', 4);
INSERT INTO `words` VALUES (19929, '...accusations that he had been disrespectful to a police officer.', 'adj. 失礼的， 无礼的', '/ˌdɪsrɪ\'spektfl | disri,spektful/', 'disrespectful', 4);
INSERT INTO `words` VALUES (19930, 'Traffic was disrupted by a hoax bomb.', 'v. 使分裂，瓦解', '/dis\'rʌpt | dɪs\'rʌpt/', 'disrupt', 4);
INSERT INTO `words` VALUES (19931, 'The strike caused widespread disruption .', 'n. 动乱； 打乱； 破坏', '/dɪs\'rʌpʃn | dɪs\'rʌpʃən/', 'disruption', 4);
INSERT INTO `words` VALUES (19932, 'Mike’s parents thought I was a disruptive influence (= a person who causes disruption ) .', 'adj. 制造混乱的； 分裂性的； 破坏性的', '/dɪs\'rʌptɪv/', 'disruptive', 4);
INSERT INTO `words` VALUES (19933, 'dissatisfied clients', 'adj. 不满意的， 不满足的', '/dɪs\'sætɪsfaɪd/', 'dissatisfied', 4);
INSERT INTO `words` VALUES (19934, 'Her findings have been widely disseminated .', 'v. 散布， 传播', '/dɪ\'semɪneɪt | dɪ\'sɛmɪnet/', 'disseminate', 4);
INSERT INTO `words` VALUES (19935, 'He had their own uniqueness and vitality, and dissemination of a value concept.', 'n. 散布， 传播', '/dɪˌsemɪ\'neɪʃn | dɪ,sɛmə\'neʃən/', 'dissemination', 4);
INSERT INTO `words` VALUES (19936, 'He is currently writing a dissertation on the Somali civil war.', 'n. (博士学位)论文，学术演讲，专题论文', '/,disə\'teiʃən | ,dɪsə\'teɪʃ(ə)n | \'dɪsɚ\'teʃən/', 'dissertation', 4);
INSERT INTO `words` VALUES (19937, 'As he thought it over, his anger gradually dissipated.', 'v. 消散，消失；浪费，挥霍', '/\'disipeit | \'dɪsɪpeɪt | \'dɪsɪpet/', 'dissipate', 4);
INSERT INTO `words` VALUES (19938, 'Stir until the sugar dissolves.', 'v. 使液化，融化；使解散', '/di\'zɔlv | dɪ\'zɒlv | dɪ\'zɑlv/', 'dissolve', 4);
INSERT INTO `words` VALUES (19939, 'Measure the distance between the two points.', 'n. 距离； 远方； 一长段时间', '/\'dɪstəns/', 'distance', 4);
INSERT INTO `words` VALUES (19940, 'Through this incision, the abdominal cavity is distended with carbon dioxide gas.', 'v. (使)扩张；膨胀', '/dis\'tend | dɪ\'stend | dɪ\'stɛnd/', 'distend', 4);
INSERT INTO `words` VALUES (19941, 'The whisky had been distilled in 1926 and sat quietly maturing until 1987.', 'v. 蒸馏', '/dis\'til/', 'distil', 4);
INSERT INTO `words` VALUES (19942, 'distilled water', 'vt. 蒸馏， 提取', '/dɪ\'stɪl | dɪs\'tɪl/', 'distill', 4);
INSERT INTO `words` VALUES (19943, 'two entirely distinct languages', 'adj. 不同的，清楚的，独特的', '/dis\'tiŋkt | dɪ\'stɪŋ(k)t | dɪ\'stɪŋkt/', 'distinct', 4);
INSERT INTO `words` VALUES (19944, 'Eliot’s distinction as a poet', 'n. 差别，区分；卓著，荣誉', '/dis\'tiŋkʃən | dɪ\'stɪŋ(k)ʃ(ə)n | dɪ\'stɪŋkʃən/', 'distinction', 4);
INSERT INTO `words` VALUES (19945, 'a rock band with a distinctive sound', 'adj. 出众的； 有特色的', '/dɪ\'stɪŋktɪv/', 'distinctive', 4);
INSERT INTO `words` VALUES (19946, 'Could he distinguish right from wrong?', 'v. 区别，识别；使显赫', '/dis\'tiŋɡwiʃ | dɪ\'stɪŋgwɪʃ | dɪ\'stɪŋɡwɪʃ/', 'distinguish', 4);
INSERT INTO `words` VALUES (19947, 'His account was badly distorted by the press.', 'v. 歪曲，弄歪，曲解', '/dis\'tɔ:t | dɪ\'stɔːt | dɪ\'stɔrt/', 'distort', 4);
INSERT INTO `words` VALUES (19948, 'I think it would be a gross distortion of reality to say that they were motivated by self-interest.', 'n. 扭曲， 变形； 曲解， 歪曲', '/dɪ\'stɔːʃn | dɪs\'tɔrʃən/', 'distortion', 4);
INSERT INTO `words` VALUES (19949, 'Try not to distract the other students.', 'v. 分散(注意力等)', '/dis\'trækt | dɪ\'strækt/', 'distract', 4);
INSERT INTO `words` VALUES (19950, 'I study in the library as there are too many distractions at home.', 'n. 消遣，娱乐，精神涣散', '/dis\'trækʃən | dɪ\'strækʃ(ə)n | dɪ\'strækʃən/', 'distraction', 4);
INSERT INTO `words` VALUES (19951, 'Luke’s behaviour caused his parents great distress.', 'n&vt. 悲痛，忧伤；贫苦；危难', '/di\'stres | dɪ\'stres | dɪ\'strɛs/', 'distress', 4);
INSERT INTO `words` VALUES (19952, 'a man distributing leaflets to passers-by', 'v. 分发，分配，散布', '/di\'stribju:t, \'dis- | dɪ\'strɪbjuːt; \'dɪstrɪbjuːt | dɪ\'strɪbjut/', 'distribute', 4);
INSERT INTO `words` VALUES (19953, 'a distribution centre', 'n. 分发， 分配； 配给物； 散布， 分布', '/ˌdɪstrɪ\'bjuːʃn | \'dɪstrə\'bjʊʃən/', 'distribution', 4);
INSERT INTO `words` VALUES (19954, 'a postal district', 'n. 区， 地区', '/\'dɪstrɪkt/', 'district', 4);
INSERT INTO `words` VALUES (19955, 'Sorry to disturb you, but I have an urgent message.', 'v. 打扰，扰乱', '/dis\'tə:b | dɪ\'stɜːb | dɪ\'stɝb/', 'disturb', 4);
INSERT INTO `words` VALUES (19956, 'There were disturbances in the crowd as fans left the stadium.', 'n. 打扰，骚动', '/di\'stə:bəns | dɪ\'stɜːb(ə)ns | dɪ\'stɝbəns/', 'disturbance', 4);
INSERT INTO `words` VALUES (19957, 'Both vehicles ended up in a ditch.', 'n. 排水沟，沟渠; v. 附入沟中，抛弃', '/ditʃ | dɪtʃ/', 'ditch', 4);
INSERT INTO `words` VALUES (19958, 'The two species diverged millions of years ago.', 'vi. 分开， 岔开； 分歧， 相异； 偏离， 违背', '/daɪ\'vɜːdʒ | daɪ\'vɝdʒ/', 'diverge', 4);
INSERT INTO `words` VALUES (19959, 'subjects as diverse as pop music and archaeology', 'adj. 多种多样的', '/dai\'və:s, di- | daɪ\'vɜːs; \'daɪvɜːs | daɪ\'vɝs/', 'diverse', 4);
INSERT INTO `words` VALUES (19960, 'We need to diversify the economy.', 'v. 多样化', '/daɪ\'vɜːsɪfaɪ | daɪˈvɜrsəˌfaɪ/', 'diversify', 4);
INSERT INTO `words` VALUES (19961, 'A slight diversion in the road is causing major headaches for businesses along El Camino Real.', 'n. 转向；水遣；改道', '/dai\'və:ʃən, di- | daɪ\'vɜːʃ(ə)n; dɪ- | dəˈvɝʒən; dəˈvɝʃən; daɪˈvɝʒən; daɪˈvɝʃən/', 'diversion', 4);
INSERT INTO `words` VALUES (19962, '...the cultural diversity of Latin America.', 'n. 多样性； 差异', '/daɪ\'vɜːsəti | dɪˈvəsɪti/', 'diversity', 4);
INSERT INTO `words` VALUES (19963, 'The high street is closed and traffic is being diverted .', 'v. 转向', '/dai\'və:t, di- | daɪ\'vɜːt; dɪ- | dɪˈvɚt/', 'divert', 4);
INSERT INTO `words` VALUES (19964, 'The Wall used to divide East and West Berlin.', 'v. 分开，分隔；分配，分享；除; n. 分歧， 差异； 分界线， 分水岭', '/dɪ\'vaɪd/', 'divide', 4);
INSERT INTO `words` VALUES (19965, 'The first quarter dividend has been increased by nearly 4 percent.', 'n. 红利，股息', '/\'dɪvɪdend | \'dɪvɪdɛnd/', 'dividend', 4);
INSERT INTO `words` VALUES (19966, 'divine power', 'adj. 神的，极好的; v. 占卜', '/di\'vain | dɪ\'vaɪn/', 'divine', 4);
INSERT INTO `words` VALUES (19967, 'the traditional division of labour (= the way that particular tasks are shared ) between husband and wife', 'n. 分开， 分隔； 分配； 分歧； 除； 部门， 科， 司', '/dɪ\'vɪʒn | də\'vɪʒən/', 'division', 4);
INSERT INTO `words` VALUES (19968, 'divisional headquarters', 'adj. 部门的', '/dɪ\'vɪʒənl | də\'vɪʒənl/', 'divisional', 4);
INSERT INTO `words` VALUES (19969, 'Do you lose your balance because of dizziness or do you ever lose consciousness?', 'n. 头昏眼花， 眩晕', '/\'dɪzinəs | \'dɪzənɪs/', 'dizziness', 4);
INSERT INTO `words` VALUES (19970, 'The heat and the champagne made him feel dizzy .', 'adj. 使人头晕的，眩晕的', '/\'dizi | \'dɪzɪ | \'dɪzi/', 'dizzy', 4);
INSERT INTO `words` VALUES (19971, 'A crowd was waiting at the dock to greet them.', 'n. 船坞；码头；刑事被告席; v. 引入船坞', '/dɔk | dɒk | dɑk/', 'dock', 4);
