INSERT INTO `words` VALUES (19985, 'The industry is dominated by five multinational companies.', 'v. 统治，支配，俯瞰，俯视', '/\'dɔmineit | \'dɒmɪneɪt | \'dɑmɪnet/', 'dominate', 4);
