INSERT INTO `words` VALUES (20087, 'a tall, elegant young woman', 'adj. 优美的，雅致的', '/\'elɪg(ə)nt | \'ɛləgənt/', 'elegant', 4);
INSERT INTO `words` VALUES (20088, 'Business and management elements are built into the course.', 'n. 要素； 元素； [the -s] 基本原理', '/\'elɪmənt | \'ɛləmənt/', 'element', 4);
INSERT INTO `words` VALUES (20089, 'the elementary principles of justice and democracy', 'adj. 基本的，初级的', '/,eli\'mentəri | elɪ\'ment(ə)rɪ | ,ɛlɪ\'mɛntri/', 'elementary', 4);
INSERT INTO `words` VALUES (20090, 'Gradually elevate the patient into anupright position.', 'v. 升高，抬起，提高', '/\'eliveit | \'elɪveɪt | \'ɛlɪvet/', 'elevate', 4);
INSERT INTO `words` VALUES (20091, 'We’ll have to take the elevator.', 'n. [美]电梯，升降机', '/\'eliveitə | \'elɪveɪtə | \'ɛlɪvetɚ/', 'elevator', 4);
INSERT INTO `words` VALUES (20092, 'When her knock elicited no response, she opened the door and peeped in.', 'v. 引出，诱出', '/i\'lisit | ɪ\'lɪsɪt/', 'elicit', 4);
INSERT INTO `words` VALUES (20093, NULL, 'n. 引出， 诱出', '/ɪˌlɪsɪ\'teɪʃn | ɪ,lɪsə\'teʃən/', 'elicitation', 4);
INSERT INTO `words` VALUES (20094, 'Stephen was regarded as an eligible bachelor.', 'adj. 合格的，适宜的', '/\'elidʒəbl | \'elɪdʒɪb(ə)l | \'ɛlɪdʒəbl/', 'eligible', 4);
INSERT INTO `words` VALUES (20095, 'a ruthless dictator who eliminated all his rivals', 'v. 消灭，消除', '/i\'limineit | ɪ\'lɪmɪneɪt | ɪ\'lɪmɪnet/', 'eliminate', 4);
INSERT INTO `words` VALUES (20096, '...a government comprised mainly of the elite.', 'n&a. 社会精华(的)，高贵者(的)', '/ei\'li:t, i\'li:t | [eɪˈliːt] | ɪˈliːt/', 'elite', 4);
INSERT INTO `words` VALUES (20097, 'an eloquent appeal for support', 'adj. 雄辩的', '/\'eləkwənt | \'ɛləkwənt/', 'eloquent', 4);
INSERT INTO `words` VALUES (20098, 'She is becoming famous in Australia and elsewhere.', 'adv. 在别处，向别处', '/,els\'hwεə | els\'weə; \'elsweə/', 'elsewhere', 4);
INSERT INTO `words` VALUES (20099, 'The full picture has not yet been elucidated.', 'vt. 阐明， 使…清楚', '/i\'luːsɪdeɪt | ɪ\'lusɪdet/', 'elucidate', 4);
INSERT INTO `words` VALUES (20100, 'She enjoys a firm reputation in this country but wider international success has been elusive.', 'adj. 难懂的， 难捉摸的； 易忘的', '/i\'luːsɪv | ɪ\'lusɪv/', 'elusive', 4);
INSERT INTO `words` VALUES (20101, 'They climbed a steep embankment.', 'n. 筑堤； 堤岸， 路基', '/ɪm\'bæŋkmənt/', 'embankment', 4);
INSERT INTO `words` VALUES (20102, 'Several countries embargoed arms shipments to Yugoslavia.', 'n&v. 禁止贸易', '/em\'bɑ:ɡəu, im- | em\'bɑːgəʊ; ɪm- | ɪm\'bɑrɡo/', 'embargo', 4);
INSERT INTO `words` VALUES (20103, 'He\'s embarking on a new career as a writer.', 'v. 上船；从事；开始', '/em\'bɑ:k, im- | ɪm\'bɑːk; em- | ɪm\'bɑrk/', 'embark', 4);
INSERT INTO `words` VALUES (20104, 'He didn’t want to embarrass her by asking questions.', 'v. 使为难，使尴尬', '/im\'bærəs | ɪm\'bærəs; em- | ɪm\'bærəs/', 'embarrass', 4);
INSERT INTO `words` VALUES (20105, 'the American Embassy in Paris', 'n. 大使馆', '/\'embəsi | \'embəsɪ | \'ɛmbəsi/', 'embassy', 4);
INSERT INTO `words` VALUES (20106, 'Feelings of guilt are deeply embedded in her personality.', 'v. 把嵌入，使扎根于社会，使深留脑中', '/im\'bed | ɪm\'bed; em- | ɪm\'bɛd/', 'embed', 4);
INSERT INTO `words` VALUES (20107, NULL, 'n. 贪污， 盗用', '/ɪm\'bezlmənt | ɪm\'bɛzlmənt/', 'embezzlement', 4);
INSERT INTO `words` VALUES (20108, 'She embodies everything I admire in a teacher.', 'v. 体现；使具体化', '/im\'bɔdi | ɪm\'bɒdɪ; em- | ɪm\'bɑdi/', 'embody', 4);
INSERT INTO `words` VALUES (20109, NULL, 'vt. 使…凸出； 压花', '/ɪm\'bɒs | ɪm\'bɔs/', 'emboss', 4);
INSERT INTO `words` VALUES (20110, 'Jack warmly embraced his son.', 'v&n. 拥抱；利用；包含', '/im\'breis | ɪm\'breɪs; em- | ɪm\'bres/', 'embrace', 4);
INSERT INTO `words` VALUES (20111, 'The system already exists in embryo.', 'n. 胚， 胚胎； 事物的萌芽期', '/\'embriəu | \'ɛmbrɪo/', 'embryo', 4);
INSERT INTO `words` VALUES (20112, 'The flowers emerge in the spring.', 'v. 出现，浮现，暴露', '/i\'mə:dʒ | ɪ\'mɜːdʒ | ɪ\'mɝdʒ/', 'emerge', 4);
INSERT INTO `words` VALUES (20113, 'Lifeguards are trained to deal with emergencies.', 'n. 紧急情况，突发事件', '/i\'mə:dʒənsi | ɪ\'mɜːdʒ(ə)nsɪ | ɪ\'mɝdʒənsi/', 'emergency', 4);
INSERT INTO `words` VALUES (20114, '...emeritus professor of physics.', 'adj. 保留头衔而退休的， 荣誉退休的', '/i\'merɪtəs | i\'meritəs/', 'emeritus', 4);
INSERT INTO `words` VALUES (20115, 'He emigrated to Belgium.', 'v. 移居国外', '/\'emiɡreit | \'emɪgreɪt | \'ɛmɪɡret/', 'emigrate', 4);
INSERT INTO `words` VALUES (20116, 'an eminent lawyer', 'adj. 著名的，卓越的', '/\'eminənt | \'emɪnənt | \'ɛmɪnənt/', 'eminent', 4);
INSERT INTO `words` VALUES (20117, 'Britain agreed to cut emissions of nitrogen oxide from power stations.', 'n. 散发； 散发物', '/i\'mɪʃn | ɪ\'mɪʃən/', 'emission', 4);
INSERT INTO `words` VALUES (20118, 'The kettle emitted a shrill whistle.', 'v. 散发；发射', '/i\'mit | ɪ\'mɪt/', 'emit', 4);
INSERT INTO `words` VALUES (20119, 'Her voice was full of emotion.', 'n. 感情；情绪；激动', '/i\'məuʃən | ɪ\'məʊʃ(ə)n | ɪ\'moʃən/', 'emotion', 4);
INSERT INTO `words` VALUES (20120, 'She provided emotional support at a very distressing time for me.', 'adj. 感情的， 情绪的； 引起情感的， 表示情感的； 情绪激动的， 易动感情的', '/ɪ\'məuʃənl | ɪ\'moʃənl/', 'emotional', 4);
INSERT INTO `words` VALUES (20121, 'I am napoleon, I am emperor… burned it!', 'n. 皇帝； 君主', '/\'empərə(r) | \'ɛmpərɚ/', 'emperor', 4);
INSERT INTO `words` VALUES (20122, 'a change of emphasis in government policy', 'n. 强调； 重要性', '/\'emfəsɪs | \'ɛmfəsɪs/', 'emphasis', 4);
INSERT INTO `words` VALUES (20123, 'The report emphasizes the importance of improving safety standards.', 'v. 强调，加强的语气', '/\'emfəsaiz | \'emfəsaɪz | \'ɛmfəsaɪz/', 'emphasize', 4);
INSERT INTO `words` VALUES (20124, 'the Roman empire', 'n. 帝国', '/\'empaɪə(r) | \'ɛmpaɪr/', 'empire', 4);
INSERT INTO `words` VALUES (20125, '{\"COLLOINEXA\":[\"empirical evidence\"]}', 'adj. 经验主义的', '/em\'pɪrɪk(ə)l; ɪm- | ɪm\'pɪrɪkl/', 'empirical', 4);
INSERT INTO `words` VALUES (20126, 'The factory employs over 2,000 people.', 'n&vt. 雇用； 用， 使用', '/ɪm\'plɔɪ/', 'employ', 4);
INSERT INTO `words` VALUES (20127, 'She was offered employment in the sales office.', 'n. 职业；雇用；使用', '/im\'plɔimənt | ɪm\'plɒɪm(ə)nt; em- | ɪm\'plɔɪmənt/', 'employment', 4);
INSERT INTO `words` VALUES (20128, 'He hoped to emulate the success of Wilder.', 'vt. 与…竞争， 赶上； 仿真， 模仿', '/\'emjuleɪt | \'ɛmjulet/', 'emulate', 4);
INSERT INTO `words` VALUES (20129, 'The new test should enable doctors to detect the disease early.', 'vt. 使能够， 使成为可能', '/ɪ\'neɪbl | ɪ\'nebl/', 'enable', 4);
INSERT INTO `words` VALUES (20130, 'a drama enacted on a darkened stage', 'v. 通过； 扮演', '/ɪ\'nækt/', 'enact', 4);
INSERT INTO `words` VALUES (20131, 'The words of the song neatly encapsulate the mood of the country at that time.', 'vt. 装入胶囊； 压缩； 总结， 概述', '/ɪn\'kæpsjʊleɪt | ɪn\'kæpsjə\'let/', 'encapsulate', 4);
INSERT INTO `words` VALUES (20132, 'When nuclear fuel is manufactured it is encased in metal cans.', 'vt. 装入， 包住', '/ɪn\'keɪs | ɪn\'kes/', 'encase', 4);
INSERT INTO `words` VALUES (20133, 'The pool area is enclosed by a six-foot wall.', 'v. 把围起来，把封入信封', '/in\'kləuz | ɪn\'kləʊz; en- | ɪn\'kloz/', 'enclose', 4);
INSERT INTO `words` VALUES (20134, 'the enclosure of arable land for pasture', 'n. 围栏；附件', '/in\'kləuʒə | ɪn\'kləʊʒə; en- | ɪn\'kloʒɚ/', 'enclosure', 4);
INSERT INTO `words` VALUES (20135, 'The two parties encode confidential data in a form that is not directly readable by the other party.', 'vt. 把译成电码， 把…编码', '/ɪn\'kəud | ɪn\'kod/', 'encode', 4);
INSERT INTO `words` VALUES (20136, 'The study encompasses the social, political, and economic aspects of the situation.', 'vt. 包含； 包围； 环绕', '/ɪn\'kʌmpəs/', 'encompass', 4);
INSERT INTO `words` VALUES (20137, 'The doctor had encountered several similar cases in the past.', 'vt&n. 遭遇，意外地遇到', '/in\'kauntə | ɪn\'kaʊntə; en- | ɪn\'kaʊntɚ/', 'encounter', 4);
INSERT INTO `words` VALUES (20138, 'I want to thank everyone who has encouraged and supported me.', 'v. 鼓励； 促进， 激发', '/ɪn\'kʌrɪdʒ | ɪn\'kɝrɪdʒ/', 'encourage', 4);
INSERT INTO `words` VALUES (20139, 'The new institutions do not encroach on political power.', 'vi. 侵入， 侵占， 侵犯； 侵蚀， 蚕食', '/ɪn\'krəutʃ | ɪn\'krotʃ/', 'encroach', 4);
INSERT INTO `words` VALUES (20140, 'the Encyclopedia of Music', 'n. 百科全书', '/ɪnˌsaɪkləˈpiːdiə | ɪnˌsaɪkləˈpidiɚ/', 'encyclopedia', 4);
INSERT INTO `words` VALUES (20141, 'At last it seemed the war might be coming to an end.', 'n&v. 末端，尽头，结束', '/end | ɛnd/', 'end', 4);
INSERT INTO `words` VALUES (20142, 'Smoking during pregnancy endangers your baby’s life.', 'vt. 危及， 危害', '/ɪn\'deɪndʒə(r) | ɪn\'dendʒɚ/', 'endanger', 4);
INSERT INTO `words` VALUES (20143, 'She improved visibly from day to day, until Martin wondered if he was doing right, for he knew that all her compliance and endeavor was for his sake.', 'n&vi. 努力，力图', '/in\'devə | ɪn\'devə | ɪn\'dɛvɚ/', 'endeavor', 4);
INSERT INTO `words` VALUES (20144, 'an outstanding example of human endeavor', 'n&vi. 努力， 尽力； 尝试', '/ɪn\'devə(r) | ɪndɛvəʳ/', 'endeavour', 4);
INSERT INTO `words` VALUES (20145, 'I can endorse their opinion wholeheartedly.', 'v. 背书，签署(姓名)，赞同', '/in\'dɔ:s | ɪn\'dɔːs; en- | ɪn\'dɔrs/', 'endorse', 4);
INSERT INTO `words` VALUES (20146, 'The ambassador has endowed a $1 million public-service fellowships programme.', 'v. 捐款，资助', '/in\'dau | ɪn\'daʊ; en- | ɪn\'daʊ/', 'endow', 4);
INSERT INTO `words` VALUES (20147, 'She was pushed beyond her powers of endurance.', 'n. 忍耐力，忍耐', '/in\'djuərəns | ɪn\'djʊər(ə)ns; en- | ɪn\'dʊrəns/', 'endurance', 4);
INSERT INTO `words` VALUES (20148, 'It seemed impossible that anyone could endure such pain.', 'v. 忍受； 持久， 持续', '/ɪn\'djuə(r) | ɪn\'dʊr/', 'endure', 4);
INSERT INTO `words` VALUES (20149, 'an energetic man', 'adj. 精力充沛的；精力旺盛的', '/,enə\'dʒetik | ,enə\'dʒetɪk | ,ɛnɚ\'dʒɛtɪk/', 'energetic', 4);
INSERT INTO `words` VALUES (20150, 'Parking restrictions will be strictly enforced.', 'v. 强迫服从；实施；加强', '/in\'fɔ:s | ɪn\'fɔːs; en- | ɪn\'fɔrs/', 'enforce', 4);
INSERT INTO `words` VALUES (20151, 'The company voted to enfranchise its 120 women members.', 'vt. 给予…政治权利； 解放', '/ɪn\'fræntʃaɪz/', 'enfranchise', 4);
INSERT INTO `words` VALUES (20152, 'She engaged the clutch and the car moved.', 'v. 雇用；从事；订婚；吸引；啮合', '/in\'ɡeidʒ | ɪn\'geɪdʒ; en- | ɪn\'ɡedʒ/', 'engage', 4);
INSERT INTO `words` VALUES (20153, 'Their engagement was announced in the paper.', 'n. 订婚；约会，交战', '/ɪn\'geɪdʒm(ə)nt; en- | ɪn\'ɡedʒmənt/', 'engagement', 4);
INSERT INTO `words` VALUES (20154, 'Your wedding ring can be engraved with a personal inscription at no extra cost.', 'v. 刻上；铭记', '/in\'ɡreiv | ɪn\'greɪv; en- | ɪn\'ɡrev/', 'engrave', 4);
INSERT INTO `words` VALUES (20155, 'The scene was stunning, and for a time engrossed all our attention.', 'v. 占用；吸引', '/in\'ɡrəus | ɪn\'grəʊs; en- | ɪn\'ɡros/', 'engross', 4);
INSERT INTO `words` VALUES (20156, 'Good lighting will enhance any room.', 'v. 提高(强度、力量、数量等)，增加(进)', '/in\'hɑ:ns, -hæns | ɪn\'hɑːns; -hæns; en- | ɪn\'hæns/', 'enhance', 4);
INSERT INTO `words` VALUES (20157, 'Cinnamon is an excellent flavour enhancer.', 'n. 增强剂； 放大器', '/ɪn\'hɑːnsə(r) | ɪn\'hænsɚ/', 'enhancer', 4);
INSERT INTO `words` VALUES (20158, 'The neighbours regarded him as something of an enigma.', 'n. 谜， 谜一样的人或事', '/ɪ\'nɪgmə/', 'enigma', 4);
INSERT INTO `words` VALUES (20159, 'Games can make learning more enjoyable.', 'adj. 令人愉快的， 使人快乐的', '/ɪn\'dʒɔɪəbl/', 'enjoyable', 4);
INSERT INTO `words` VALUES (20160, 'an operation to enlarge her breasts', 'v. 扩大， 放大， 扩充', '/ɪn\'lɑːdʒ | ɪn\'lɑrdʒ/', 'enlarge', 4);
INSERT INTO `words` VALUES (20161, 'A few dedicated doctors have fought for years to enlighten the profession.', 'v. 启发，开导', '/in\'laitən | ɪn\'laɪt(ə)n; en- | ɪn\'laɪtn/', 'enlighten', 4);
INSERT INTO `words` VALUES (20162, NULL, 'v. 征募； 从军， 参军； 谋取', '/ɪn\'lɪst/', 'enlist', 4);
INSERT INTO `words` VALUES (20163, 'an enormous bunch of flowers', 'adj. 巨大的，庞大的', '/i\'nɔ:məs | ɪ\'nɔːməs | ɪ\'nɔrməs/', 'enormous', 4);
INSERT INTO `words` VALUES (20164, 'I am writing to confirm /enquire/inform you…', 'v. 询问，打听', '/in\'kwaiə | ɪn\'kwaɪə | ɪn\'kwaɪr/', 'enquire', 4);
INSERT INTO `words` VALUES (20165, NULL, 'n. 询问，打听', '/in\'kwaiəri | ɪn\'kwaɪrɪ | ɛnˈkwaɪri, ˈɛnkwəri/', 'enquiry', 4);
INSERT INTO `words` VALUES (20166, 'Add fertilizer to enrich the soil.', 'v. 使丰富，加料于，增进', '/in\'ritʃ | ɪn\'rɪtʃ; en- | ɪn\'rɪtʃ/', 'enrich', 4);
INSERT INTO `words` VALUES (20167, 'The school will enroll new students in August.', 'v. 招收，入伍，入学', '/in\'rəul | ɪn\'rəʊl | ɪn\'rol/', 'enroll', 4);
INSERT INTO `words` VALUES (20168, 'Enrolment will take place in September.', 'n. 登记，入学', '/in\'rəulmənt | ɪn\'rəʊlm(ə)nt | ɪn\'rolmənt/', 'enrolment', 4);
INSERT INTO `words` VALUES (20169, '...an ensemble of young musicians.', 'n. 全体；演唱组', '/ɔŋ\'sɔŋblə | ɒn\'sɒmb(ə)l | ɑn\'sɑmbl/', 'ensemble', 4);
INSERT INTO `words` VALUES (20170, 'She seemed enslaved by hatred.', 'vt. 奴役， 征服， 使受控制', '/ɪn\'sleɪv | ɪn\'slev/', 'enslave', 4);
INSERT INTO `words` VALUES (20171, 'If the Europeans did not reduce subsidies, a trade war would ensue.', 'v. 跟着发生；结果是', '/in\'sju: | ɪn\'sjuː; en- | ɪn\'su/', 'ensue', 4);
INSERT INTO `words` VALUES (20172, 'facilities to ensure the safety of cyclists', 'vt. 确保， 保证； 担保； 赋予', '/ɪn\'ʃuə(r) | ɪn\'ʃʊr/', 'ensure', 4);
INSERT INTO `words` VALUES (20173, 'A new computer system entails a lot of re-training.', 'v. 使必需', '/in\'teil | ɪn\'teɪl; en- | ɪn\'tel/', 'entail', 4);
INSERT INTO `words` VALUES (20174, 'The blade of the oar had entangled itself with the strap of her bag.', 'v. 缠住，套住', '/in\'tæŋɡl | ɪn\'tæŋg(ə)l; en- | ɪn\'tæŋɡl/', 'entangle', 4);
INSERT INTO `words` VALUES (20175, 'commercial enterprises such as banks and food manufacturers', 'n. 艰巨的事业；事业心，企业', '/\'entəpraiz | \'entəpraɪz | \'ɛntɚ\'praɪz/', 'enterprise', 4);
INSERT INTO `words` VALUES (20176, 'They were entertained by top singers, dancers and celebrities.', 'v. 欢乐， 娱乐； 招待', '/ˌentə\'teɪn | ,ɛntɚ\'ten/', 'entertain', 4);
INSERT INTO `words` VALUES (20177, 'The town provides a wide choice of entertainment.', 'n. 娱乐，招待，表演', '/,entə\'teinmənt | entə\'teɪnm(ə)nt | \'ɛntɚ\'tenmənt/', 'entertainment', 4);
INSERT INTO `words` VALUES (20178, 'Gillian and Darren greeted the speakers with great enthusiasm.', 'n. 娱乐，招待，表演', '/in\'θju:ziæzəm, in\'θu:- | ɪn\'θjuːzɪæz(ə)m; en- | ɪn\'θuzɪæzəm/', 'enthusiasm', 4);
INSERT INTO `words` VALUES (20179, 'an enthusiastic supporter of reform', 'adj. 热情的，热心的', '/in,θju:zi\'æstik | ɪn,θjuːzɪ\'æstɪk; en- | ɪn,θuzɪ\'æstɪk/', 'enthusiastic', 4);
INSERT INTO `words` VALUES (20180, 'They\'ll entice thousands of doctors to move from the cities to the rural areas by paying them better salaries.', 'v. 怂恿， 引诱', '/ɪn\'taɪs/', 'entice', 4);
INSERT INTO `words` VALUES (20181, 'It was the worst day in my entire life.', 'adj. 全部的， 整个的', '/ɪn\'taɪə(r) | ɪn\'taɪɚ/', 'entire', 4);
INSERT INTO `words` VALUES (20182, '...a performance entitled \"United States.\"', 'v. 给(书)题名；给予权利', '/in\'taitl | ɪn\'taɪt(ə)l; en- | ɪn\'taɪtl/', 'entitle', 4);
INSERT INTO `words` VALUES (20183, 'The mind exists as a separate entity.', 'n. 实体；存在', '/\'entəti | \'entɪtɪ | \'ɛntəti/', 'entity', 4);
INSERT INTO `words` VALUES (20184, 'He entreated them to delay their departure.', 'v. 恳求，央求', '/in\'tri:t | ɪn\'triːt; en- | ɪn\'trit/', 'entreat', 4);
INSERT INTO `words` VALUES (20185, 'How would you define personal growth as an entrepreneur?', 'n. [法]企业家, 演出承包人 \"', '/,ɔntrəprə\'nə: | ˌɒntrəprəˈnɜː(r) | ˌɑntrəprəˈnɝ​/', 'entrepreneur', 4);
INSERT INTO `words` VALUES (20186, '...her prodigious entrepreneurial flair.', 'adj. 创业的', '/ˌɒntrəprə\'nɜːriəl | ,ɑntrəprə\'njʊrɪəl/', 'entrepreneurial', 4);
INSERT INTO `words` VALUES (20187, 'He entrusted his cash to a business partner for investment in a series of projects.', 'vt. 委托， 交付， 托付', '/ɪn\'trʌst/', 'entrust', 4);
INSERT INTO `words` VALUES (20188, 'There was no sign of a forced entry.', 'n. 进入，入口；条目，词条', '/\'entri | ˈɒntreɪ | \'ɛntri/', 'entry', 4);
INSERT INTO `words` VALUES (20189, 'They walked together with their arms entwined.', 'vt. 使缠住， 使盘绕', '/ɪn\'twaɪn/', 'entwine', 4);
INSERT INTO `words` VALUES (20190, 'Some of these chemicals are very damaging to the environment.', 'n. 环境', '/in\'vaiərənmənt | ɪn\'vaɪrənm(ə)nt; en- | ɪn\'vaɪrənmənt/', 'environment', 4);
INSERT INTO `words` VALUES (20191, 'The scheme cost a lot more than we had originally envisaged.', 'v. 想象；期望；设想', '/in\'vizidʒ | ɪn\'vɪzɪdʒ; en- | ɪn\'vɪzɪdʒ/', 'envisage', 4);
INSERT INTO `words` VALUES (20192, 'I really envy you and Ian, you seem so happy together.', 'n&vt. 忌妒，妒忌的对象；羡慕', '/\'envi | \'envɪ | \'ɛnvi/', 'envy', 4);
INSERT INTO `words` VALUES (20193, 'It is believed that it inhibits an enzyme that promotes cell proliferation in tumours.', 'n. 酶', '/\'enzaim | \'enzaɪm | \'ɛnzaɪm/', 'enzyme', 4);
INSERT INTO `words` VALUES (20194, 'Fashion is by nature ephemeral.', 'adj. 短暂的', '/i\'femərəl | ɪ\'fem(ə)r(ə)l; -\'fiːm- | ə\'fɛmərəl/', 'ephemeral', 4);
INSERT INTO `words` VALUES (20195, 'Over 500 people died during last year’s flu epidemic.', 'adj. (疾病)流行性的，传染的', '/,epi\'demik | epɪ\'demɪk | ,ɛpɪ\'dɛmɪk/', 'epidemic', 4);
INSERT INTO `words` VALUES (20196, 'Watch next week’s thrilling episode!', 'n. 一系列事件中的一个事件', '/\'episəud | \'epɪsəʊd | \'ɛpɪsod/', 'episode', 4);
INSERT INTO `words` VALUES (20197, 'his episodic involvement in politics', 'adj. 偶然发生的， 不定期的； 由许多片段组成的， 松散的', '/ˌepɪ\'sɒdɪk | ,ɛpɪ\'sɑdɪk/', 'episodic', 4);
INSERT INTO `words` VALUES (20198, NULL, 'vt. 集中体现； 概括', '/ɪ\'pɪtəmaɪz | i\'pitəmaiz/', 'epitomise', 4);
INSERT INTO `words` VALUES (20199, 'the Victorian epoch', 'n. 新纪元，新时代', '/\'i:pɔk, \'epək | \'iːpɒk; \'epɒk | \'ɛpək/', 'epoch', 4);
INSERT INTO `words` VALUES (20200, 'Two plus two equals four.', 'a&n&vt. 相等的，相等于，相等匹敌', '/\'i:kwəl | \'ikwəl/', 'equal', 4);
INSERT INTO `words` VALUES (20201, 'In the equation 2x + 1 = 7, what is x?', 'n. 方程式，等式', '/i\'kweiʒən, -ʃən | ɪ\'kweɪʒ(ə)n | ɪ\'kweʒn/', 'equation', 4);
INSERT INTO `words` VALUES (20202, 'The United States is north of the equator.', 'n. 赤道', '/i\'kweitə | ɪ\'kweɪtə | ɪ\'kwetɚ/', 'equator', 4);
INSERT INTO `words` VALUES (20203, 'The government is anxious not to upset the economic equilibrium.', 'n. 平衡，均衡', '/,i:kwi\'libriəm | ,iːkwɪ\'lɪbrɪəm; ,ekwɪ- | ,ikwɪ\'lɪbrɪəm/', 'equilibrium', 4);
INSERT INTO `words` VALUES (20204, 'They try to equip their vehicles with gadgets to deal with every possible contingency.', 'vt. 装备， 配备； 使有能力， 使有准备', '/ɪ\'kwɪp/', 'equip', 4);
INSERT INTO `words` VALUES (20205, 'a shop selling camping equipment', 'n. 设备， 装备', '/ɪ\'kwɪpmənt/', 'equipment', 4);
INSERT INTO `words` VALUES (20206, 'an equitable distribution of food supplies', 'adj. 公平的；公正的', '/\'ekwitəbl | \'ekwɪtəb(ə)l/', 'equitable', 4);
INSERT INTO `words` VALUES (20207, 'a society run on the principles of equity and justice', 'n. 公平；公正；无固定利息的股票', '/\'ekwəti | \'ekwɪtɪ | \'ɛkwəti/', 'equity', 4);
INSERT INTO `words` VALUES (20208, 'The word has no equivalent in English.', 'a&n. 相等的，相同', '/i\'kwivələnt | ɪ\'kwɪv(ə)l(ə)nt | ɪ\'kwɪvələnt/', 'equivalent', 4);
INSERT INTO `words` VALUES (20209, 'His answer was equivocal.', 'adj. 暧昧的，可疑的', '/i\'kwivəkəl | ɪ\'kwɪvək(ə)l | ɪ\'kwɪvəkl/', 'equivocal', 4);
INSERT INTO `words` VALUES (20210, 'His death marked the end of an era.', 'n. 纪元； 时代', '/\'ɪərə | \'ɪrə/', 'era', 4);
INSERT INTO `words` VALUES (20211, 'an attempt to eradicate inflation', 'v. 根除；消除', '/i\'rædikeit | ɪ\'rædɪkeɪt | ɪ\'rædɪket/', 'eradicate', 4);
INSERT INTO `words` VALUES (20212, 'Some of the names had been accidentally erased.', 'v. 擦掉，抹掉', '/i\'reiz, i\'reis | ɪ\'reɪz | ɪ\'res/', 'erase', 4);
INSERT INTO `words` VALUES (20213, 'an imposing town hall, erected in 1892', 'v. 建立，使竖立; adj. 直立的，竖直的', '/i\'rekt | ɪ\'rekt | ɪ\'rɛkt/', 'erect', 4);
INSERT INTO `words` VALUES (20214, 'The cliffs are being constantly eroded by heavy seas.', 'v. 侵蚀， 腐蚀； 削弱， 损害', '/ɪ\'rəud | ɪ\'rod/', 'erode', 4);
INSERT INTO `words` VALUES (20215, 'the problem of soil erosion', 'n. 腐蚀，侵蚀', '/i\'rəuʒən | ɪ\'rəʊʒ(ə)n | ɪ\'roʒən/', 'erosion', 4);
INSERT INTO `words` VALUES (20216, 'Everybody rushing about on some incomprehensible errand someone forced him to do at pain of death.', 'n. 差使；差事', '/\'erənd | \'er(ə)nd | \'ɛrənd/', 'errand', 4);
INSERT INTO `words` VALUES (20217, 'His breathing was becoming erratic.', 'adj. 古怪的，反复无常的，不稳定的', '/i\'rætik | ɪ\'rætɪk/', 'erratic', 4);
INSERT INTO `words` VALUES (20218, 'His economic predictions are based on some erroneous assumptions.', 'adj. 错误的，不正确的', '/i\'rəuniəs | ɪ\'rəʊnɪəs; e- | ɪ\'ronɪəs/', 'erroneous', 4);
INSERT INTO `words` VALUES (20219, 'Violence erupted after police shot a student during the demonstration.', 'v. 喷发，爆发', '/i\'rʌpt | ɪ\'rʌpt/', 'erupt', 4);
INSERT INTO `words` VALUES (20220, 'If a volcanic eruption wipes out all of the plain mice, the island will be repopulated by striped mice.', 'n. 爆发； 发作', '/ɪ\'rʌpʃn | ɪ\'rʌpʃən/', 'eruption', 4);
INSERT INTO `words` VALUES (20221, 'The fighting on the border is escalating.', 'v. 升级，逐渐发展', '/\'eskəleit | \'eskəleɪt | \'ɛskəlet/', 'escalate', 4);
INSERT INTO `words` VALUES (20222, 'Take the escalator to the third floor and it\'s the last office on the left.', 'n. 自动扶梯', '/\'eskəleitə | \'eskəleɪtə | \'ɛskə\'letɚ/', 'escalator', 4);
INSERT INTO `words` VALUES (20223, 'a police escort', 'n. 护卫者；护航舰; v. 护送，护卫', '/\'eskɔ:t, i\'skɔ:t | \'eskɔːt | ˈeskɔːrt/', 'escort', 4);
INSERT INTO `words` VALUES (20224, 'We asked Jason to write an essay about his hometown.', 'n. 文章，小品文，随笔', '/\'esei, e\'sei | \'eseɪ | \'ɛse/', 'essay', 4);
INSERT INTO `words` VALUES (20225, 'In essence his message was very simple.', 'n. 本质，香精', '/\'esəns | \'es(ə)ns | \'ɛsns/', 'essence', 4);
INSERT INTO `words` VALUES (20226, 'She packed a few essentials.', 'n&a. 本质(的)，必要(的)', '/i\'senʃəl | ɪ\'senʃ(ə)l | ɪ\'sɛnʃl/', 'essential', 4);
INSERT INTO `words` VALUES (20227, 'The city of Boerne was established by German settlers in the 1840s.', 'v. 建立，委任；安置；证实；确立', '/i\'stæbliʃ | ɪ\'stæblɪʃ; e- | ɪˈstæblɪʃ/', 'establish', 4);
INSERT INTO `words` VALUES (20228, 'His estate was valued at $150,000.', 'n. 房地产；财产', '/ɪ\'steɪt; e- | ɪ\'stet/', 'estate', 4);
INSERT INTO `words` VALUES (20229, 'Peden was greatly esteemed by the people of Ayrshire.', 'n&vt. 尊重，珍重', '/i\'sti:m | ɪ\'stiːm; e- | ɪ\'stim/', 'esteem', 4);
INSERT INTO `words` VALUES (20230, 'We just need an estimate of the number of people who will come.', 'n. n.; n. 估计，估价; v. 评价，估量', '/\'estimeit | \'estɪmeɪt | \'ɛstə,met/', 'estimate', 4);
INSERT INTO `words` VALUES (20231, 'he is estranged from his wife', 'vt. 使疏远， 使分离', '/ɪ\'streɪndʒ | i\'streindʒ/', 'estrange', 4);
INSERT INTO `words` VALUES (20232, 'the Thames estuary', 'n. 河口， 河口湾', '/\'estʃʊəri | \'ɛstʃʊ\'ɛri/', 'estuary', 4);
INSERT INTO `words` VALUES (20233, 'the Christian promise of eternal life', 'adj. 永久的，不朽的，不停的', '/i\'tə:nəl | ɪ\'tɜːn(ə)l; iː- | ɪ\'tɝnl/', 'eternal', 4);
INSERT INTO `words` VALUES (20234, 'ethereal beauty', 'adj. 太空的； 轻巧的', '/i\'θɪəriəl | ɪ\'θɪrɪəl/', 'ethereal', 4);
INSERT INTO `words` VALUES (20235, 'The president must have the highest ethical standards.', 'adj. 道德的； 伦理的', '/\'eθɪkl | \'ɛθɪkl/', 'ethical', 4);
INSERT INTO `words` VALUES (20236, 'The school teaches pupils from different ethnic groups.', 'adj. 种族的；人种学的', '/\'eθnik | \'eθnɪk | \'ɛθnɪk/', 'ethnic', 4);
INSERT INTO `words` VALUES (20237, 'strict rules of professional etiquette', 'n. 礼仪, 礼节 \"', '/\'etiket | \'etɪket; etɪ\'ket | \'ɛtɪkɛt/', 'etiquette', 4);
INSERT INTO `words` VALUES (20238, 'Police evacuated the area.', 'v. 撤离，疏散，排清', '/i\'vækjueit | ɪ\'vækjʊeɪt | ɪ\'vækjuet/', 'evacuate', 4);
INSERT INTO `words` VALUES (20239, 'I could tell that he was trying to evade the issue.', 'v. 回避, 躲避\"', '/i\'veid | ɪ\'veɪd | ɪ\'ved/', 'evade', 4);
INSERT INTO `words` VALUES (20240, 'You should be able to evaluate your own work.', 'v. 估的价，定的值', '/i\'væljueit | ɪ\'væljʊeɪt | ɪ\'væljʊ\'et/', 'evaluate', 4);
INSERT INTO `words` VALUES (20241, 'We need to carry out a proper evaluation of the new system.', 'n. 估价， 评价', '/ɪˌvæljʊ\'eɪʃn | ɪ,væljʊ\'eʃən/', 'evaluation', 4);
INSERT INTO `words` VALUES (20242, 'Most of the water had evaporated.', 'v. 使蒸发，使脱水，消失', '/i\'væpəreit | ɪ\'væpəreɪt | ɪ\'væpəret/', 'evaporate', 4);
INSERT INTO `words` VALUES (20243, 'Most companies have suffered a drop in their profits, even very large companies.', 'adv. 甚至还; adj. 平的，双数的; v. 使平坦', '/\'i:vən | \'iːv(ə)n | \'ivən/', 'even', 4);
INSERT INTO `words` VALUES (20244, 'one of the most important events in the history of mankind', 'n. 事件； 比赛项目', '/ɪ\'vent | ɪ\'vɛnt/', 'event', 4);
INSERT INTO `words` VALUES (20245, 'He eventually escaped and made his way back to England.', 'adv. 终于，最后', '/i\'ventʃuəli | ɪ\'ventʃʊəlɪ | ɪ\'vɛntʃuəli/', 'eventually', 4);
INSERT INTO `words` VALUES (20246, 'everlasting fame', 'adj. 永久的，永恒的', '/,eveə\'lɑ:stiŋ | evə\'lɑːstɪŋ | ,ɛvɚ\'læstɪŋ/', 'everlasting', 4);
INSERT INTO `words` VALUES (20247, 'One cleric resigned over plans to evict the protesters forcibly, arguing that the Church should have been more supportive of their cause.', 'v. 驱逐', '/i\'vikt | ɪ\'vɪkt/', 'evict', 4);
INSERT INTO `words` VALUES (20248, 'Murrow’s evidence was enough to convict Hayes of murder.', 'n. 根据， 证据； 形迹， 迹象', '/\'evɪdəns | \'ɛvɪdəns/', 'evidence', 4);
INSERT INTO `words` VALUES (20249, 'The photographs evoked strong memories of our holidays in France.', 'v. 唤起；引起', '/i\'vəuk | ɪ\'vəʊk | ɪ\'vok/', 'evoke', 4);
INSERT INTO `words` VALUES (20250, 'the theory of evolution', 'n. 演变，进展，进化', '/,i:və\'lu:ʃən, ,ev- | ,iːvə\'luːʃ(ə)n; \'ev- | ˌɛvəˈluʃən; (occas.) ˌ ivəˈluʃən/', 'evolution', 4);
INSERT INTO `words` VALUES (20251, 'Animals have evolved camouflage to protect themselves from predators.', 'v. 逐渐形成； 演变， 进化', '/i\'vɒlv | ɪ\'vɑlv/', 'evolve', 4);
INSERT INTO `words` VALUES (20252, 'The recession has exacerbated this problem.', 'v. 加重；恶化', '/ek\'sæsəbeit, iɡz- | ɪg\'zæsəbeɪt; ek\'sæs- | ɪɡ\'zæsɚbet/', 'exacerbate', 4);
INSERT INTO `words` VALUES (20253, 'Police are still investigating the exact cause of the accident.', 'adj. 精确的； 准确的', '/ɪg\'zækt | ɪɡ\'zækt/', 'exact', 4);
INSERT INTO `words` VALUES (20254, 'I couldn’t sleep for three days – I’m not exaggerating.', 'v. 夸大，夸张', '/iɡ\'zædʒəreit | ɪg\'zædʒəreɪt; eg- | ɪɡ\'zædʒəret/', 'exaggerate', 4);
INSERT INTO `words` VALUES (20255, 'A team of divers was sent down to examine the wreck.', 'vt. 检查； 调查， 研究； 测验', '/ɪg\'zæmɪn/', 'examine', 4);
INSERT INTO `words` VALUES (20256, 'It exasperates me to hear comments like that.', 'v. 激怒，使恼火', '/iɡ\'zæspəreit, -\'zɑ:s- | ɪg\'zæsp(ə)reɪt; eg- | ɪɡ\'zæspəret/', 'exasperate', 4);
INSERT INTO `words` VALUES (20257, 'Schliemann excavated the ancient city of Troy.', 'v. 挖掘，挖出', '/\'ekskə,veit | \'ekskəveɪt | \'ɛkskə\'vet/', 'excavate', 4);
INSERT INTO `words` VALUES (20258, 'Blue flags define the excavation perimeter, while yellow ones mark the location of fossils or stone tools.', 'n. 挖掘， 发掘； 出土文物', '/ˌekskə\'veɪʃn | ,ɛkskə\'veʃən/', 'excavation', 4);
INSERT INTO `words` VALUES (20259, 'Working hours must not exceed 42 hours a week.', 'v. 比大，超出', '/ik\'si:d | ɪk\'siːd; ek- | ɪk\'sid/', 'exceed', 4);
INSERT INTO `words` VALUES (20260, NULL, '\"ad. 非常, 极端地\"', '/ik\'si:diŋli | ɪk\'siːdɪŋlɪ; ek- | ɪk\'sidɪŋli/', 'exceedingly', 4);
INSERT INTO `words` VALUES (20261, 'You have excelled yourself with the new exhibition.', 'v. 杰出，胜过，优于', '/ik\'sel | ɪk\'sel; ek- | ɪk\'sɛl/', 'excel', 4);
INSERT INTO `words` VALUES (20262, 'an excellent suggestion', 'adj. 极好的； 杰出的', '/\'eksələnt | \'ɛksələnt/', 'excellent', 4);
INSERT INTO `words` VALUES (20263, 'They were all there except me.', 'prep. 除…外; vt. 将…除外', '/ɪk\'sept | ɪk\'sɛpt/', 'except', 4);
INSERT INTO `words` VALUES (20264, 'an exceptional student', 'adj. 异常的，优越的', '/ik\'sepʃənəl | ɪk\'sepʃ(ə)n(ə)l; ek- | ɪk\'sɛpʃənl/', 'exceptional', 4);
INSERT INTO `words` VALUES (20265, '...an excerpt from Tchaikovsky\'s Nutcracker.', 'n. 摘录，节录', '/ek\'sə:pt, \'eksə:pt | \'eksɜːpt | \'ɛksɝpt/', 'excerpt', 4);
INSERT INTO `words` VALUES (20266, 'The car reached speeds in excess of 100 miles per hour.', 'n. 超越；超过；暴行; adj. 额外的，附加的', '/ik\'ses, \'ek-, \'ekses, ik\'s- | ɪk\'ses; ek-; \'ekses | \'ɛk\'sɛs/', 'excess', 4);
INSERT INTO `words` VALUES (20267, 'his excessive drinking', 'adj. 过多的， 极度的， 过分的', '/ɪk\'sesɪv | ɪkˈsɛsɪv/', 'excessive', 4);
INSERT INTO `words` VALUES (20268, 'Four of my cassettes for your Madonna CD is a fair exchange.', 'v&n. 交换；兑换', '/iks\'tʃeindʒ | ɪks\'tʃeɪndʒ; eks- | ɪks\'tʃendʒ/', 'exchange', 4);
INSERT INTO `words` VALUES (20269, 'We were both new to the excitements of life in the big city.', 'n. 激动； 兴奋； 令人兴奋的事', '/ɪk\'saɪtmənt/', 'excitement', 4);
INSERT INTO `words` VALUES (20270, '‘No!’ she exclaimed in shock.', 'v. 呼叫，惊叫', '/ik\'skleim | ɪk\'skleɪm; ek- | ɪk\'sklem/', 'exclaim', 4);
INSERT INTO `words` VALUES (20271, 'a special diet that excludes dairy products', 'v. 把某人排除在外，排除(可能性等)', '/iks\'klu:d | ɪk\'skluːd; ek- | ɪk\'sklʊd/', 'exclude', 4);
INSERT INTO `words` VALUES (20272, 'Bel Air is an exclusive suburb of Los Angeles.', 'adj. 孤傲的；不愿吸收新会员的；索价高昂的', '/ik\'sklu:siv | ɪk\'skluːsɪv; ek- | ɪk\'sklusɪv/', 'exclusive', 4);
INSERT INTO `words` VALUES (20273, '...an exclusively male domain.', 'adv. 专门地，排除其他地', '/ik\'sklu:sivli | ɪk\'skluːsɪvlɪ | ɪk\'sklʊsɪvli/', 'exclusively', 4);
INSERT INTO `words` VALUES (20274, 'The cage smelled of excrement.', 'n. 排泄物，粪便', '/\'ekskrimənt | \'ekskrɪm(ə)nt | \'ɛkskrɪmənt/', 'excrement', 4);
INSERT INTO `words` VALUES (20275, 'The excreta of humans and land animals contain soluble refractory organic matter.', 'n. 排泄物', '/ɪk\'skriːtə | ɪk\'skritə/', 'excreta', 4);
INSERT INTO `words` VALUES (20276, 'a shopping excursion', 'n. 远足，短途旅行', '/ɪk\'skɜːʃ(ə)n; ek- | ɪk\'skɝʒn/', 'excursion', 4);
INSERT INTO `words` VALUES (20277, 'an excusable reaction of anger', 'adj. 可原谅的； 可谅解的； 可容许的', '/ɪk\'skjuːzəbl | ɪk\'skjuzəbl/', 'excusable', 4);
INSERT INTO `words` VALUES (20278, '13 people were summarily executed (= killed without any trial or legal process ) by the guerrillas.', 'v. 实行，贯彻，实施；处死；演奏', '/\'eksikju:t | \'eksɪkjuːt | \'ɛksɪkjut/', 'execute', 4);
INSERT INTO `words` VALUES (20279, 'a public execution', 'n. 演奏技巧；死刑', '/,eksi\'kju:ʃən | ,eksɪ\'kjuːʃ(ə)n | ,ɛksɪ\'kjuʃən/', 'execution', 4);
INSERT INTO `words` VALUES (20280, 'a commission with executive powers', 'adj. 执行的，行政的; n. 行政部门，行政人员', '/ɪg\'zekjʊtɪv; eg- | ɪɡ\'zɛkjətɪv/', 'executive', 4);
INSERT INTO `words` VALUES (20281, 'Problems are exemplified in the report.', 'v. 举例说明，作为的例证', '/iɡ\'zemplifai | ɪg\'zemplɪfaɪ; eg- | ɪɡ\'zɛmplɪfaɪ/', 'exemplify', 4);
INSERT INTO `words` VALUES (20282, 'So we have the current argument over how much of the derivative market will be exempt from regulation.', 'vt&a. 免除，被豁免的', '/iɡ\'zempt | ɪg\'zem(p)t; eg- | ɪg\'zɛmpt/', 'exempt', 4);
INSERT INTO `words` VALUES (20283, 'He has exerted himself tirelessly on behalf of the charity.', 'v. 发挥，行使，尽力', '/iɡ\'zə:t | ɪg\'zɜːt; eg- | ɪɡ\'zɝt/', 'exert', 4);
INSERT INTO `words` VALUES (20284, 'Take a deep breath, then exhale slowly.', 'v. 呼出； 散发', '/eks\'heɪl | ɛks\'hel/', 'exhale', 4);
INSERT INTO `words` VALUES (20285, 'exhaust fumes', 'n. 排气; v. 抽空，汲光', '/iɡ\'zɔ:st | ɪg\'zɔːst; eg- | ɪɡ\'zɔst/', 'exhaust', 4);
INSERT INTO `words` VALUES (20286, 'Your willpower is an exhaustible supply, so don\'t force yourself to finish tasks if you don\'t have to.', 'adj. 可耗尽的， 会枯竭的', '/ɪg\'zɔːstəbl | ɪg\'zɔstəbl/', 'exhaustible', 4);
INSERT INTO `words` VALUES (20287, 'Sheer exhaustion forced him to give up.', 'n. 精疲力竭； 耗尽', '/ɪg\'zɔːstʃən | ɪg\'zɔstʃən/', 'exhaustion', 4);
INSERT INTO `words` VALUES (20288, 'an exhaustive investigation', 'adj. 包揽无遗的， 彻底的， 详尽的', '/ɪg\'zɔːstɪv | ɪg\'zɔstɪv/', 'exhaustive', 4);
INSERT INTO `words` VALUES (20289, 'Her paintings have been exhibited all over the world.', 'v. 陈列， 展览； 显示; n. 展览品', '/ɪg\'zɪbɪt | ɪɡ\'zɪbɪt/', 'exhibit', 4);
INSERT INTO `words` VALUES (20290, '...an exhibition of expressionist art.', 'n. 展览； 陈列', '/ˌeksɪ\'bɪʃn | ˌɛksəˈbɪʃən/', 'exhibition', 4);
INSERT INTO `words` VALUES (20291, NULL, 'v. 使振奋，使高兴', '/iɡ\'ziləreit | ɪg\'zɪləreɪt; eg- | ɪɡ\'zɪləret/', 'exhilarate', 4);
INSERT INTO `words` VALUES (20292, 'It might be the exhilaration of that potent cordial, which is distilled only in the furnace-glow of earnest and long-continued thought.', 'n. 高兴； 兴奋', '/ɪgˌzɪlə\'reɪʃn | ɪg,zɪlə\'reʃən/', 'exhilaration', 4);
INSERT INTO `words` VALUES (20293, 'Kennedy exhorted his listeners to turn away from violence.', 'v. 劝告', '/iɡ\'zɔ:t | ɪg\'zɔːt; eg- | ɪɡ\'zɔrt/', 'exhort', 4);
INSERT INTO `words` VALUES (20294, 'political exiles', 'n&vt. 流放，离乡背井', '/\'eɡzail, \'eksail | \'eksaɪl; \'egz- | \'ɛksaɪl/', 'exile', 4);
INSERT INTO `words` VALUES (20295, 'The custom of arranged marriages still exists in many countries.', 'vi. 存在； 生存', '/ɪg\'zɪst | ɪɡ\'zɪst/', 'exist', 4);
INSERT INTO `words` VALUES (20296, 'Scientists have many theories about how the universe first came into existence (= started to exist ).', 'n. 存在； 生活', '/ɪg\'zɪstəns | ɪɡ\'zɪstəns/', 'existence', 4);
INSERT INTO `words` VALUES (20297, 'The medical system is facing collapse because of an exodus of doctors.', 'n. 大批离去， 成群外出', '/\'eksədəs | \'ɛksədəs/', 'exodus', 4);
INSERT INTO `words` VALUES (20298, 'Exorbitant housing prices have created an acute shortage of affordable housing for the poor.', 'adj. 要价过高的，过分的', '/iɡ\'zɔ:bitənt | ɪg\'zɔːbɪt(ə)nt | ɪɡ\'zɔrbɪtənt/', 'exorbitant', 4);
INSERT INTO `words` VALUES (20299, 'exotic birds', 'adj. 外国种的；奇异的', '/,iɡ\'zɔtik | ɪg\'zɒtɪk; eg- | ɪɡ\'zɑtɪk/', 'exotic', 4);
INSERT INTO `words` VALUES (20300, 'Water expands as it freezes.', 'v. 使扩大，展开，膨胀', '/ik\'spænd | ɪk\'spænd; ek- | ɪk\'spænd/', 'expand', 4);
INSERT INTO `words` VALUES (20301, 'The industry underwent a period of rapid expansion.', 'n. 扩大， 扩张', '/ɪk\'spænʃn | ɪk\'spænʃən/', 'expansion', 4);
INSERT INTO `words` VALUES (20302, 'I saw the look of expectancy in the children’s eyes.', 'n. 期待， 期望； 预期数额', '/ɪk\'spektənsi | ɪk\'spɛktənsi/', 'expectancy', 4);
INSERT INTO `words` VALUES (20303, 'Having raised expectations (= made people more hopeful ), he went on to help only a few people.', 'n. 期待，预期；', '/ˌekspek\'teɪʃn | ,ɛkspɛk\'teʃən/', 'expectation', 4);
INSERT INTO `words` VALUES (20304, 'This solution is politically expedient but may well cause long-term problems.', 'adj. 有用的，有利的; n. 紧急的办法，权宜之计', '/ik\'spi:diənt | ɪk\'spiːdɪənt; ek- | ɪk\'spidɪənt/', 'expedient', 4);
INSERT INTO `words` VALUES (20305, 'an expedition to the North Pole', 'n. 远征，探险(队)，考察(队)', '/,ekspi\'diʃən | ekspɪ\'dɪʃ(ə)n | ,ɛkspə\'dɪʃən/', 'expedition', 4);
INSERT INTO `words` VALUES (20306, 'More than five-thousand high school students have been expelled for cheating.', 'v. 驱逐，开除；排出', '/ik\'spel | ɪk\'spel; ek- | ɪk\'spɛl/', 'expel', 4);
INSERT INTO `words` VALUES (20307, 'Children expend a lot of energy and may need more high-energy food than adults.', 'v. 消费，用尽', '/ik\'spend | ɪk\'spend; ek- | ɪk\'spɛnd/', 'expend', 4);
INSERT INTO `words` VALUES (20308, 'huge cuts in public expenditure', 'n. 支出，花费，消费量', '/iks\'penditʃə | ɪk\'spendɪtʃə; ek- | ɪk\'spɛndɪtʃɚ/', 'expenditure', 4);
INSERT INTO `words` VALUES (20309, 'He borrowed £150,000 and used the money for legal expenses.', 'n. 花费， 开支； 消费， 消耗； 代价， 损失', '/ɪk\'spens | ɪk\'spɛns/', 'expense', 4);
INSERT INTO `words` VALUES (20310, 'She was not an accountant and didn\'t have the expertise to verify all of the financial details.', 'n. 专门知识，专门技能', '/,ekspə:\'ti:z | ,ekspɜː\'tiːz | \'ɛkspɝ\'tiz/', 'expertise', 4);
INSERT INTO `words` VALUES (20311, 'My passport expires next week.', 'v. 满期，到期', '/ik\'spaiə, ek- | ɪk\'spaɪə; ek- | ɪk\'spaɪɚ/', 'expire', 4);
INSERT INTO `words` VALUES (20312, 'Check the expiry date on your passport.', 'n. 满期， 终结', '/ɪk\'spaɪəri/', 'expiry', 4);
INSERT INTO `words` VALUES (20313, 'The contrast could not have been made more explicit.', 'adj. 清楚的，明确的', '/ik\'splisit | ɪk\'splɪsɪt; ek- | ɪk\'splɪsɪt/', 'explicit', 4);
INSERT INTO `words` VALUES (20314, 'The device was thrown at an army patrol but failed to explode.', 'v. (使)爆炸，爆发', '/ik\'spləud | ɪk\'spləʊd; ek- | ɪk\'splod/', 'explode', 4);
INSERT INTO `words` VALUES (20315, 'Homeworkers can easily be exploited by employers.', 'n. 英雄行为，辉煌功绩; v. 开拓，开采，剥削', '/\'eksplɔit, ik\'s- | ɪk\'splɒɪt; ek- | ɪk\'splɔɪt/', 'exploit', 4);
INSERT INTO `words` VALUES (20316, NULL, 'n. 开采， 开发； 剥削， 榨取； 自私的利用', '/ˌeksplɔɪ\'teɪʃn | ,ɛksplɔɪ\'teʃən/', 'exploitation', 4);
INSERT INTO `words` VALUES (20317, 'the exploitative nature of multinational companies', 'adj. 开发的， 利用的； 剥削的', '/ɪk\'splɔɪtətɪv/', 'exploitative', 4);
INSERT INTO `words` VALUES (20318, 'He’s going to have exploratory surgery on his knee.', 'adj. 探测的； 勘探的； 探索的', '/ɪk\'splɒrətri | ɪk\'splɔrətɔri/', 'exploratory', 4);
INSERT INTO `words` VALUES (20319, 'Venice is a wonderful city to explore.', 'v. 勘察，考查；探索', '/ik\'splɔ: | ɪk\'splɔː; ek- | ɪk\'splɔr/', 'explore', 4);
INSERT INTO `words` VALUES (20320, '...the travels of Columbus, Magellan, and many other explorers.', 'n. 勘探者， 探险者', '/ɪk\'splɔːrə(r) | ɪk\'splɔrɚ/', 'explorer', 4);
INSERT INTO `words` VALUES (20321, '...one-hundred-and-fifty pounds of Semtex explosive.', 'n&a. 爆炸(的)，爆发性(的)', '/ik\'spləusiv | ɪk\'spləʊsɪv; ek- | ɪk\'splosɪv; ɪk\'splozɪv/', 'explosive', 4);
INSERT INTO `words` VALUES (20322, 'Italian food has been exported all over the world.', 'v. 输出，出口; n. 出口，出口企业，出口品', '/ik\'spɔ:t, \'eks-, \'ekspɔ:t | ˈekspɔːt；ɪkˈ- | ˈekspɔːrt；ɪkˈ-/', 'export', 4);
INSERT INTO `words` VALUES (20323, 'The film exposes the utter horror of war.', 'v. 揭发, 使暴露，使曝光\"', '/ik\'spəuz | ɪk\'spəʊz; ek- | ɪk\'spoz；ek-/', 'expose', 4);
INSERT INTO `words` VALUES (20324, 'Aristotle was valued because of his clear exposition of rational thought.', 'n. 阐述，讲解；展览会', '/,ekspəu\'ziʃən | ekspə\'zɪʃ(ə)n | ,ɛkspə\'zɪʃən/', 'exposition', 4);
INSERT INTO `words` VALUES (20325, 'Exposure to lead is known to damage the brains of young children.', 'n. 暴露； 显露； 接触； 曝光', '/ɪk\'spəuʒə(r) | ɪk\'spoʒɚ/', 'exposure', 4);
INSERT INTO `words` VALUES (20326, 'Parents have expressed their concerns about their children’s safety.', 'vt. 表达，; n. 快车， 快运， 快递', '/ɪk\'spres | ɪk\'sprɛs/', 'express', 4);
INSERT INTO `words` VALUES (20327, 'The headmaster threatened the boys with expulsion.', 'n. 驱逐; 开除', '/ik\'spʌlʃən | ɪk\'spʌlʃ(ə)n; ek- | ɪk\'spʌlʃən/', 'expulsion', 4);
INSERT INTO `words` VALUES (20328, 'the most exquisite craftsmanship', 'adj. 优美的，精巧的', '/\'ekskwizit, ek\'skwizit | \'ekskwɪzɪt; ɪk\'skwɪzɪt; ek- | ɪk\'skwɪzɪt/', 'exquisite', 4);
INSERT INTO `words` VALUES (20329, 'Management have agreed to extend the deadline.', 'v. 伸出，延长；给予；扩大', '/ik\'stend | ɪk\'stend; ek- | ɪk\'stɛnd/', 'extend', 4);
INSERT INTO `words` VALUES (20330, 'These were hung in place with extendable rods.', 'adj. 可延伸的， 可展开的， 可扩张的', '/ɪk\'stendəbl | ɪk\'stɛndəbl/', 'extendable', 4);
INSERT INTO `words` VALUES (20331, 'a loft extension', 'n. 伸展； 延长部分； 电话分机', '/ɪk\'stenʃn | ɪk\'stɛnʃən/', 'extension', 4);
INSERT INTO `words` VALUES (20332, 'The house stands in extensive grounds.', 'adj. 广大的， 广阔的； 广泛的', '/ɪk\'stensɪv | ɪk\'stɛnsɪv/', 'extensive', 4);
INSERT INTO `words` VALUES (20333, 'It’s too early to assess the full extent of the damage.', 'n. 广度，长度，程度', '/ik\'stent | ɪk\'stent; ek- | ɪk\'stɛnt/', 'extent', 4);
INSERT INTO `words` VALUES (20334, 'The dome is tiled on the exterior.', 'a&n. 外部的；外来的，外表', '/ik\'stiəriə | ɪk\'stɪərɪə; ek- | ɪk\'stɪrɪɚ/', 'exterior', 4);
INSERT INTO `words` VALUES (20335, 'Staff use the poison to exterminate moles and rabbits.', 'v. 灭绝，根除', '/ik\'stə:mineit | ɪk\'stɜːmɪneɪt; ek- | ɪk\'stɝmə\'net/', 'exterminate', 4);
INSERT INTO `words` VALUES (20336, 'the external appearance of the building', 'adj. 外面的，外部的', '/ik\'stə:nəl | ɪk\'stɜːn(ə)l; ek- | ɪk\'stɝnl/', 'external', 4);
INSERT INTO `words` VALUES (20337, 'This action externally appears like the discharge of a capacitor.', 'adv. 外表上， 外形上', '/ɪk\'stɜːnəli | ɪk\'stɝnli/', 'externally', 4);
INSERT INTO `words` VALUES (20338, 'Dinosaurs have been extinct for millions of years.', 'adj. 消灭了的，熄灭了的，绝种的', '/ik\'stiŋkt | ɪk\'stɪŋkt; ek- | ɪk\'stɪŋkt/', 'extinct', 4);
INSERT INTO `words` VALUES (20339, 'species in danger of extinction', 'n. 灭绝， 绝种； 熄灭', '/ɪk\'stɪŋkʃn | ɪk\'stɪŋkʃən/', 'extinction', 4);
INSERT INTO `words` VALUES (20340, 'Please extinguish all cigarettes.', 'v. 熄灭，扑灭', '/ik\'stiŋɡwiʃ | ɪk\'stɪŋgwɪʃ; ek- | ɪk\'stɪŋɡwɪʃ/', 'extinguish', 4);
INSERT INTO `words` VALUES (20341, 'Check the expiry date for all foam extinguisher.', 'n. 灭火器； 灭火者', '/ɪk\'stɪŋgwɪʃə(r) | ɪk\'stɪŋɡwɪʃɚ/', 'extinguisher', 4);
INSERT INTO `words` VALUES (20342, 'Now experts are extolling the virtues of the humble potato.', 'vt. 赞颂， 赞美， 颂扬', '/ɪk\'stəul | ɪk\'stol/', 'extol', 4);
INSERT INTO `words` VALUES (20343, 'Corrupt government officials were extorting money from him.', 'v. 强取，勒索', '/ik\'stɔ:t | ɪk\'stɔːt; ek- | ɪk\'stɔrt/', 'extort', 4);
INSERT INTO `words` VALUES (20344, 'There are no hidden extras.', 'a&ad&n. 额外的/地，非常，另外；额外的人', '/\'ekstrə | \'ɛkstrə/', 'extra', 4);
INSERT INTO `words` VALUES (20345, 'You’ll have to have that tooth extracted.', 'v. 拔出；榨取；摘录; n. 抽出物，选录', '/ik\'strækt, \'ekstrækt | ˈekstrækt | \'ɛkstrækt/', 'extract', 4);
INSERT INTO `words` VALUES (20346, 'Each child had participated in extracurricular activities at school.', 'adj. 课外的', '/ˌekstrəkə\'rɪkjələ(r) | ,ɛkstrəkə\'rɪkjəlɚ/', 'extracurricular', 4);
INSERT INTO `words` VALUES (20347, 'It took an extraordinary amount of work.', 'adj. 不同寻常的， 非常的', '/ɪk\'strɔːdnri | ɪkˈstrɔrdənerɪ; ɪkˈstrɔrdnˌɛrɪ/', 'extraordinary', 4);
INSERT INTO `words` VALUES (20348, 'When the company went under, tales of his extravagance surged through the industry.', 'n. 奢侈， 挥霍； 放肆的言行', '/ɪk\'strævəgəns | ɪk\'strævəɡəns/', 'extravagance', 4);
INSERT INTO `words` VALUES (20349, 'Would it be too extravagant to buy both?', 'adj. 奢侈的，过分的', '/ik\'strævəɡənt | ɪk\'strævəg(ə)nt; ek- | ɪk\'strævəgənt/', 'extravagant', 4);
INSERT INTO `words` VALUES (20350, 'Extreme poverty still exists in many rural areas.', 'adj. 极度的，尽头的; n. 极端，相反的性质', '/ik\'stri:m | ɪk\'striːm; ek- | ɪk\'strim/', 'extreme', 4);
INSERT INTO `words` VALUES (20351, 'Her sister was always more of an extrovert.', 'n. 性格外向的人； 爱交际的人', '/\'ekstrəvɜːt | ,ɛkstrə\'vɝt/', 'extrovert', 4);
INSERT INTO `words` VALUES (20352, NULL, 'n. 挤出， 推出， 挤压', '/ɪk\'struːʒn/', 'extrusion', 4);
INSERT INTO `words` VALUES (20353, 'So the exuberant young girl with dark hair and blue eyes decided to become a screen actress.', 'adj. 茂盛的，精力充沛的', '/iɡ\'zju:bərənt | ɪg\'z(j)uːb(ə)r(ə)nt; eg-/', 'exuberant', 4);
INSERT INTO `words` VALUES (20354, 'He’s got beautiful eyes.', 'n&vt. 眼睛；看', '/ai | aɪ/', 'eye', 4);
INSERT INTO `words` VALUES (20355, 'He had a problem with his eyesight.', 'n. 视力', '/\'aɪsaɪt/', 'eyesight', 4);
INSERT INTO `words` VALUES (20356, 'our new range of fabrics and wallpapers', 'n. 织物，构造；结构', '/\'fæbrik | \'fæbrɪk/', 'fabric', 4);
INSERT INTO `words` VALUES (20357, 'The police were accused of fabricating evidence.', 'v. 装配，制造，捏造', '/\'fæbrikeit | \'fæbrɪkeɪt | \'fæbrɪket/', 'fabricate', 4);
INSERT INTO `words` VALUES (20358, 'For a manufacturer, these will be materials used in the fabrication of the products.', 'n. 捏造， 伪造； 制作； 构成', '/ˌfæbrɪ\'keɪʃn | ,fæbrɪ\'keʃən/', 'fabrication', 4);
INSERT INTO `words` VALUES (20359, 'Crystal clear waters, beautiful white sand beaches, swaying palm trees and fabulous dive sites – that’s why the Maldives, is known for being one of the best tropical holiday destinations in the world.', 'adj. 寓言般的；惊人的，难以置信的', '/\'fæbjuləs | \'fæbjʊləs | \'fæbjələs/', 'fabulous', 4);
INSERT INTO `words` VALUES (20360, 'While the project wants to open up the facade for a through ventilation, the different identities of various shops on the façade would have made the building appear to be fragmented.', 'n. 正面； 外表', '/fə\'sɑːd/', 'façade', 4);
INSERT INTO `words` VALUES (20361, 'She had a beautiful face.', 'n. 脸，表情; v. 面向，正视，承认，呈现前', '/feis | feɪs | fes/', 'face', 4);
INSERT INTO `words` VALUES (20362, 'The issues are complex and multi-faceted.', 'n. 刻面，(问题的)一个方面', '/\'fæsit | \'fæsɪt; -et | \'fæsɪt/', 'facet', 4);
INSERT INTO `words` VALUES (20363, 'Victor’s facial expression didn’t change.', 'adj. 面部的； 面部用的', '/\'feɪʃl | \'feʃl/', 'facial', 4);
INSERT INTO `words` VALUES (20364, 'Modern inventions facilitate housework.', 'v. 使便利', '/fə\'siliteit | fə\'sɪlɪteɪt | fə\'sɪlə\'tet/', 'facilitate', 4);
INSERT INTO `words` VALUES (20365, 'What recreational facilities are now available?', 'n. 灵巧，熟练；设备', '/fə\'siliti | fə\'sɪləti/', 'facility', 4);
INSERT INTO `words` VALUES (20366, '...a facsimile edition of Beethoven\'s musical manuscripts.', 'n. 复制品； 副本', '/fæk\'sɪməli/', 'facsimile', 4);
INSERT INTO `words` VALUES (20367, '...the institute\'s free fact sheet, Driving Abroad.', 'n. 情况简报，资料摘要', NULL, 'fact sheet', 4);
INSERT INTO `words` VALUES (20368, 'The rise in crime is mainly due to social and economic factors.', 'n. 因素，要素', '/\'fæktə | \'fæktɚ/', 'factor', 4);
INSERT INTO `words` VALUES (20369, 'Try to keep your account of events as factual as possible.', 'adj. 事实的； 真实的， 确凿的', '/\'fæktʃʊəl | \'fæktʃuəl/', 'factual', 4);
INSERT INTO `words` VALUES (20370, 'the Engineering Faculty', 'n. 才能；(大学的)系科；学院全体教员', '/\'fækəlti | \'fæk(ə)ltɪ | \'fæklti/', 'faculty', 4);
INSERT INTO `words` VALUES (20371, 'Hopes of a peace settlement are beginning to fade.', 'v. (使)褪色，逐渐消失', '/feid, fad | feɪd | fed/', 'fade', 4);
INSERT INTO `words` VALUES (20372, 'He was asked for the boiling point of water in Fahrenheit.', 'n. 华氏温度计', '/\'færəhait | \'færən\'haɪt/', 'fahrenheit', 4);
INSERT INTO `words` VALUES (20373, 'She gave a faint smile.', 'adj. 微弱的，不清楚的; n&vi. 昏晕', '/\'feint | feɪnt | fent/', 'faint', 4);
INSERT INTO `words` VALUES (20374, 'It should be fair.', 'a&ad. 公平的/地', '/feə(r) | fɛr/', 'fair', 4);
INSERT INTO `words` VALUES (20375, 'The house had a fairly large garden.', 'adv. 相当地； 公平地； 简直， 完全地', '/\'feəli | \'fɛrli/', 'fairly', 4);
INSERT INTO `words` VALUES (20376, 'People have lost faith in the government.', 'n. 信任，信仰', '/feiθ | feɪθ | feθ/', 'faith', 4);
INSERT INTO `words` VALUES (20377, 'The painting was judged a fake.', 'n. 假货，骗子; v. 伪造', '/feik | feɪk/', 'fake', 4);
INSERT INTO `words` VALUES (20378, 'The tree was about to fall.', 'n&vi. 落下，降落，倒坍，垂下', '/fɔ:l | fɔːl | fɔl/', 'fall', 4);
INSERT INTO `words` VALUES (20379, 'It’s a common fallacy that a neutered dog will become fat and lazy.', 'n. 谬论', '/\'fæleisi | \'fæləsɪ | \'fæləsi/', 'fallacy', 4);
INSERT INTO `words` VALUES (20380, 'Humans are fallible.', 'adj. 易犯错误的，错误难免的', '/\'fæləbl | \'fælɪb(ə)l/', 'fallible', 4);
INSERT INTO `words` VALUES (20381, 'They let the land lie fallow for a year.', 'adj. 休耕的； 休闲的', '/\'fæləu | \'fælo/', 'fallow', 4);
INSERT INTO `words` VALUES (20382, 'Laurie’s voice faltered as she tried to thank him.', 'v. 蹒跚；声音发抖；支吾', '/\'fɔ:ltə | \'fɔːltə; \'fɒl- | \'fɔltɚ/', 'falter', 4);
INSERT INTO `words` VALUES (20383, 'He claims he is not really interested in fame.', 'n. 名声，名誉', '/feim | feɪm | fem/', 'fame', 4);
INSERT INTO `words` VALUES (20384, 'a familiar tune', 'adj. 熟悉的，通晓的；亲密的，常见的', '/fə\'miljə | fə\'mɪlɪə | fə\'mɪljɚ/', 'familiar', 4);
INSERT INTO `words` VALUES (20385, NULL, 'vt. 使熟悉， 使通晓； 使家喻户晓', '/fə\'miljəraiz | fə\'mɪliəraɪz/', 'familiarise', 4);
INSERT INTO `words` VALUES (20386, 'the great potato famine in Ireland', 'n. 饥荒', '/\'fæmin | \'fæmɪn/', 'famine', 4);
INSERT INTO `words` VALUES (20387, 'fanatics who represent a real danger to democracy', 'a&n. 狂热的，狂热者', '/fə\'nætik | fə\'nætɪk/', 'fanatic', 4);
INSERT INTO `words` VALUES (20388, 'Harry took me to a fancy restaurant for our anniversary.', 'adj. 颜色鲜艳的;奇特的n&v想象力,设想,爱好', '/\'fænsɪ | \'fænsi/', 'fancy', 4);
INSERT INTO `words` VALUES (20389, 'You look fantastic!', 'adj. 奇异的；荒谬的，极好的', '/fæn\'tæstɪk/', 'fantastic', 4);
INSERT INTO `words` VALUES (20390, 'I used to have fantasies about living in Paris with an artist.', 'n. 幻想，怪念头', '/\'fæntəsi | \'fæntəsɪ; -zɪ/', 'fantasy', 4);
INSERT INTO `words` VALUES (20391, 'He could barely afford the fare.', 'n. 车(船)费', '/fεə | feə | fɛr/', 'fare', 4);
INSERT INTO `words` VALUES (20392, 'Mourners gathered to bid farewell to the victims of the plane tragedy.', 'lint&n&a. 再见；临别的，告别的', '/\'fεə\'wel | feə\'wel | ,fɛr\'wɛl/', 'farewell', 4);
INSERT INTO `words` VALUES (20393, 'The idea of travelling through time fascinates me.', 'v. 使神魂颠倒，迷住', '/\'fæsineit | \'fæsɪneɪt | \'fæsə\'net/', 'fascinate', 4);
INSERT INTO `words` VALUES (20394, 'a fascinating book', 'adj. 迷人的', '/\'fæsineitiŋ | \'fæsɪneɪtɪŋ | \'fæsɪnetɪŋ/', 'fascinating', 4);
INSERT INTO `words` VALUES (20395, 'Young people are very concerned with fashion', 'n. 方式； 流行款式； 时装', '/\'fæʃn | \'fæʃən/', 'fashion', 4);
INSERT INTO `words` VALUES (20396, 'Make sure all the windows are securely fastened before you leave.', 'v. 扎牢， 扣住', '/\'fɑːsn | \'fæsən/', 'fasten', 4);
INSERT INTO `words` VALUES (20397, 'people who are fastidious about personal hygiene', 'adj. 难讨好的，爱挑剔的', '/fæs\'tidiəs | fæ\'stɪdɪəs/', 'fastidious', 4);
INSERT INTO `words` VALUES (20398, 'potentially fatal diseases', 'adj. 致命的，命运的，注定的', '/\'feitl | \'feɪt(ə)l | \'fetl/', 'fatal', 4);
INSERT INTO `words` VALUES (20399, 'I wouldn’t wish such a fate on my worst enemy.', 'n. 命运， 天数', '/feɪt | fet/', 'fate', 4);
