INSERT INTO `words` VALUES (20520, 'The building is grey, formidable, not at all picturesque.', 'adj. 可怕的，难以对付的', '/\'fɔ:midəbl | \'fɔːmɪdəb(ə)l; fɔː\'mɪd- | \'fɔrmɪdəbl/', 'formidable', 4);
INSERT INTO `words` VALUES (20521, 'the formula for calculating distance', 'n. 俗套话；公式，程式', '/\'fɔ:mjulə | \'fɔːmjʊlə | \'fɔrmjələ/', 'formula', 4);
INSERT INTO `words` VALUES (20522, 'We are studying the situation but have not formulated any response yet.', 'v. 精确地表达；制订；用公式表示', '/\'fɔ:mjuleit | \'fɔːmjʊleɪt | \'fɔrmjə\'let/', 'formulate', 4);
INSERT INTO `words` VALUES (20523, 'This is a far weaker formulation than is in the draft resolution which is being proposed.', 'n. 公式化， 格式化； 确切的表达', '/ˌfɔːmjʊ\'leɪʃn | ,fɔrmjə\'leʃən/', 'formulation', 4);
INSERT INTO `words` VALUES (20524, 'The fort flanked on a swamp.', 'n. 要塞; 堡垒', '/fɔ:t | fɔːt | fɔrt/', 'fort', 4);
INSERT INTO `words` VALUES (20525, 'Moscow-based Kaspersky Lab has long been a magnet for Russia\'s young computer geniuses, luring them away from their usual forte, hacking, to viral analysis.', 'n. 长处，特长', '/\'fɔ:t | \'fɔːteɪ; \'fɔːtɪ; fɔːt | \'fɔrte/', 'forte', 4);
INSERT INTO `words` VALUES (20526, 'The house was still burning, pouring forth thick black smoke.', 'adv. 离去， 外出； 向前； 向某处', '/fɔːθ | fɔrθ/', 'forth', 4);
INSERT INTO `words` VALUES (20527, 'the forthcoming elections', 'adj. 即将出现的；现有的', '/\'fɔ:θ\'kʌmiŋ | fɔːθ\'kʌmɪŋ | ,fɔrθ\'kʌmɪŋ/', 'forthcoming', 4);
