INSERT INTO `words` VALUES (20529, 'a fortnight’s holiday', 'n. 两星期', '/\'fɔ:tnait | \'fɔːtnaɪt | \'fɔrtnaɪt/', 'fortnight', 4);
INSERT INTO `words` VALUES (20530, 'Members of the council agreed that was an important forum for discussion.', 'n. 论坛', '/\'fɔ:rəm | \'fɔːrəm | \'fɔrəm/', 'forum', 4);
INSERT INTO `words` VALUES (20531, 'fossils of early reptiles', 'n. 化石', '/\'fɔsəl | \'fɒs(ə)l; -sɪl | \'fɑsl/', 'fossil', 4);
INSERT INTO `words` VALUES (20532, 'The couple wanted to adopt a black child they had been fostering.', 'v. 养育，领养', '/\'fɔstə | \'fɒstə | \'fɔstɚ/', 'foster', 4);
INSERT INTO `words` VALUES (20533, 'He woke up with a foul taste in his mouth.', 'adj. 恶臭的；邪恶的；暴风雨的n犯规v弄脏', '/faul | faʊl/', 'foul', 4);
INSERT INTO `words` VALUES (20534, 'It took the builders three weeks to lay the foundations .', 'n. 基础； 地基； 创立', '/faun\'deɪʃn | faʊn\'deʃən/', 'foundation', 4);
INSERT INTO `words` VALUES (20535, 'He was a fountain of information on Asian affairs.', 'n. 泉水，喷泉；源泉', '/\'fauntin | ˈfaʊntən | \'faʊntn/', 'fountain', 4);
INSERT INTO `words` VALUES (20536, 'The students had a grasp of decimals, percentages and fractions.', 'n. 小部分；片断；分数', '/\'frækʃən | \'frækʃ(ə)n/', 'fraction', 4);
INSERT INTO `words` VALUES (20537, 'At least one-third of all women over ninety have sustained a hip fracture.', 'n. 碎片，片断；分数', '/\'fræktʃə | \'fræktʃɚ/', 'fracture', 4);
INSERT INTO `words` VALUES (20538, 'Be careful with that vase – it’s very fragile.', 'adj. 脆的；易断的', '/\'frædʒail | \'frædʒaɪl | \'frædʒəl/', 'fragile', 4);
INSERT INTO `words` VALUES (20539, 'glass fragments', 'n. 碎片，片断; v. 裂成碎片', '/\'fræɡmənt | \'frægm(ə)nt/', 'fragment', 4);
INSERT INTO `words` VALUES (20540, '...a shrubby plant with a strong characteristic fragrance.', 'n. 香味，香气', '/\'freiɡrəns | \'freɪgr(ə)ns | \'fregrəns/', 'fragrance', 4);
INSERT INTO `words` VALUES (20541, '{\"COLLOINEXA\":[\"frail elderly people\"]}', 'adj. 脆弱的；脆弱的', '/freil | freɪl | frel/', 'frail', 4);
INSERT INTO `words` VALUES (20542, 'They removed the picture from its wooden frame.', 'n. 框架; vt. 给…镶框', '/freɪm | frem/', 'frame', 4);
INSERT INTO `words` VALUES (20543, 'We have to act within the existing legal framework.', 'n. 构架，框架', '/\'freimwə:k | \'freɪmwɜːk | \'fremwɝk/', 'framework', 4);
INSERT INTO `words` VALUES (20544, 'To be perfectly frank, I think it’s a bad idea.', 'adj. 坦白的， 直率的', '/fræŋk/', 'frank', 4);
