INSERT INTO `words` VALUES (20546, '{\"COLLOINEXA\":[\"electoral fraud\"]}', 'n. 诈骗，骗子', '/frɔ:d | frɔːd | frɔd/', 'fraud', 4);
INSERT INTO `words` VALUES (20547, 'The earliest operations employing this technique were fraught with dangers.', 'adj. 充满的；伴随的', '/frɔ:t | frɔːt | frɔt/', 'fraught', 4);
INSERT INTO `words` VALUES (20548, 'These glasses make me look like a freak.', 'n. 怪诞的思想、行动或事件；畸形的', '/fri:k | friːk/', 'freak', 4);
