INSERT INTO `words` VALUES (20550, 'freight services', 'n. 运货，货物; v. 运输', '/freit | freɪt | fret/', 'freight', 4);
INSERT INTO `words` VALUES (20551, 'Side effects from prescribed drugs are being reported with increasing frequency (= more and more often ) .', 'n. 频繁； 频率', '/\'friːkwənsi | \'frikwənsi/', 'frequency', 4);
INSERT INTO `words` VALUES (20552, 'Trains rushed past at frequent intervals .', 'adj. 频繁的， 常见的， 常用的', '/\'friːkwənt | \'frikwənt/', 'frequent', 4);
INSERT INTO `words` VALUES (20553, 'Don’t fret – everything will be all right.', 'v&n. 烦恼，侵蚀', '/fret | frɛt/', 'fret', 4);
INSERT INTO `words` VALUES (20554, 'Putting oil on both surfaces reduces friction.', 'n. 摩擦，不和，倾轧', '/\'frikʃən | \'frɪkʃ(ə)n | \'frɪkʃən/', 'friction', 4);
INSERT INTO `words` VALUES (20555, 'Then all three of you sign the contract and post in on the fridge.', 'n. 冰箱', '/fridʒ | frɪdʒ/', 'fridge', 4);
INSERT INTO `words` VALUES (20556, 'Don’t be frightened. We’re not going to hurt you.', 'adj. 受惊的； 受恐吓的', '/\'fraɪtnd/', 'frightened', 4);
