INSERT INTO `words` VALUES (20558, 'a party frock', 'n. 上衣； 连衣裙', '/frɒk | frɑk/', 'frock', 4);
INSERT INTO `words` VALUES (20559, 'The issue of gays is distinct, therefore, from the almost-as-contentious issue of women in front-line combat roles.', 'adj. 前线的； 第一线的', '/\'frʌnt\'lain | frʌnt\'laɪn/', 'front-line', 4);
INSERT INTO `words` VALUES (20560, 'a novel about a family’s struggle on the American frontier', 'n. 国境；尖端；新领域', '/\'frʌntjə | \'frʌntɪə; frʌn\'tɪə | frʌn\'tɪr/', 'frontier', 4);
INSERT INTO `words` VALUES (20561, 'the risk of frost damage to crops', 'n. 严寒，霜v结霜;使(玻璃)具有光泽的表面', '/frɔst | frɒst/', 'frost', 4);
INSERT INTO `words` VALUES (20562, 'She frowned as she read the letter.', 'vi&n. 皱眉，不赞成', '/fraun | fraʊn/', 'frown', 4);
INSERT INTO `words` VALUES (20563, 'As children we were taught to be frugal and hard-working.', 'adj. 俭朴的，花钱少的', '/\'fru:ɡəl | \'fruːg(ə)l | \'fruɡl/', 'frugal', 4);
INSERT INTO `words` VALUES (20564, 'Today’s meeting proved more fruitful than last week’s.', 'adj. 多产的， 富饶的； 富有成效的', '/\'fruːtfl | \'frutfl/', 'fruitful', 4);
INSERT INTO `words` VALUES (20565, 'Some of the current FSA investigations are expected to reach fruition in the next six months, one person said.', 'n. 实现；完成', '/fru:\'iʃən | frʊ\'ɪʃ(ə)n | fru\'ɪʃən/', 'fruition', 4);
INSERT INTO `words` VALUES (20566, 'Their attempts to speak to him were frustrated by the guards.', 'v. 挫败；阻挠', '/frʌs\'treit | frʌ\'streɪt; \'frʌs- | \'frʌstret/', 'frustrate', 4);
INSERT INTO `words` VALUES (20567, 'My job can be very frustrating sometimes.', 'adj. 令人泄气的， 使人沮丧的', '/frʌ\'streɪtɪŋ | \'frʌstretɪŋ/', 'frustrating', 4);
INSERT INTO `words` VALUES (20568, 'People often feel a sense of frustration that they are not being promoted quickly enough.', 'n. 沮丧， 不满', '/frʌ\'streɪʃn | frʌ\'streʃən/', 'frustration', 4);
