INSERT INTO `words` VALUES (20573, '...car exhaust fumes.', 'n. 烟，汽; v. 熏，冒烟;; v. 发怒', '/fju:m | fjuːm | fjum/', 'fume', 4);
INSERT INTO `words` VALUES (20574, 'paint fumes', 'n. 烟， 气， 汽', '/fjuːmz | fjumz/', 'fumes', 4);
