INSERT INTO `words` VALUES (20578, 'The funeral will be held at St. Martin’s Church.', 'n. 葬礼，丧葬', '/\'fju:nərəl | \'fjuːn(ə)r(ə)l | \'fjunərəl/', 'funeral', 4);
INSERT INTO `words` VALUES (20579, '...a ship with three masts and two funnels.', 'n. 漏斗，烟囱; v. 汇集', '/\'fʌnl | \'fʌn(ə)l/', 'funnel', 4);
INSERT INTO `words` VALUES (20580, 'She was absolutely furious .', 'adj. 狂怒的', '/\'fju:riəs | \'fjʊərɪəs | \'fjʊrɪəs/', 'furious', 4);
INSERT INTO `words` VALUES (20581, 'We had better fire up the furnace.', 'n. 炉子，熔炉', '/\'fə:nis | \'fɜːnɪs | \'fɝnɪs/', 'furnace', 4);
