INSERT INTO `words` VALUES (20585, 'two 13 amp fuses', 'n. 导火线，引信，保险丝; v. 熔，烧断电路', '/fju:z | fjuːz | fjuz/', 'fuse', 4);
INSERT INTO `words` VALUES (20586, 'His previous fusions of jazz, pop and African melodies have proved highly successful.', 'n. 熔合，熔接', '/\'fjuːʒ(ə)n | \'fjʊʒən/', 'fusion', 4);
