INSERT INTO `words` VALUES (20593, 'an exhibition of African art at the Hayward Gallery', 'n. 画廊，美术品陈列室；剧场顶层', '/\'ɡæləri | \'gæl(ə)rɪ | \'gæləri/', 'gallery', 4);
INSERT INTO `words` VALUES (20594, 'A neighbour’s horse came galloping the road, riderless.', 'v&n. 奔驰， 飞跑， 飞驰', '/\'gæləp | \'ɡæləp/', 'gallop', 4);
INSERT INTO `words` VALUES (20595, 'Their religion forbids them to drink or gamble.', 'v&n. 赌博；投机', '/\'ɡæmbl | \'gæmb(ə)l/', 'gamble', 4);
INSERT INTO `words` VALUES (20596, 'Several gangs were operating in the area.', 'n. 一组，一队，(罪犯等)一帮，一群', '/ɡæŋ | gæŋ/', 'gang', 4);
INSERT INTO `words` VALUES (20597, NULL, 'n&vt. 监狱，监禁', '/dʒeil | dʒeɪl/', 'gaol', 4);
INSERT INTO `words` VALUES (20598, 'The front door was missing. A hole gaped in the roof.', 'v. 张口，张开，裂开; n. 目瞪口呆', '/ɡeip | geɪp/', 'gape', 4);
INSERT INTO `words` VALUES (20599, 'Can you take out the garbage when you go?', 'n. 垃圾，污物', '/\'ɡɑ:bidʒ | \'gɑːbɪdʒ | \'ɡɑrbɪdʒ/', 'garbage', 4);
INSERT INTO `words` VALUES (20600, 'She pulled the garment on and zipped it up.', 'n. (一件)衣服(长袍、外套)', '/\'ɡɑ:mənt | \'gɑːm(ə)nt | \'gɑrmənt/', 'garment', 4);
INSERT INTO `words` VALUES (20601, '‘My leg!’ he gasped. ‘I think it’s broken!’', 'n&v. 喘气，气喘吁吁地说', '/ɡɑ:sp, ɡæsp | gɑːsp | ɡæsp/', 'gasp', 4);
INSERT INTO `words` VALUES (20602, 'A crowd gathered to watch the fight.', 'v. 聚集， 集合， 聚拢； 收集， 采集； 逐渐增加； 猜想， 推测', '/\'gæðə(r) | \'ɡæðɚ/', 'gather', 4);
INSERT INTO `words` VALUES (20603, 'gaudy jewelry', 'adj. 绚丽的', '/\'ɡɔ:di | \'gɔːdɪ | \'gɔdi/', 'gaudy', 4);
INSERT INTO `words` VALUES (20604, 'a 12-gauge shotgun', '\"n. 标准尺寸,(铁道)轨矩;雨量器；(电线)直径 \"', '/ɡeidʒ | geɪdʒ | gedʒ/', 'gauge', 4);
