INSERT INTO `words` VALUES (20607, 'However, scientists do not believe that the new gelatin product would pose any risk.', 'n. 明胶', '/\'dʒelətɪn/', 'gelatin', 4);
INSERT INTO `words` VALUES (20608, 'people of the same gender', 'n. 性别； 性', '/\'dʒendə(r) | \'dʒɛndɚ/', 'gender', 4);
