INSERT INTO `words` VALUES (20610, 'a general introduction to computing', 'adj. 一般的，普通的；全体的，普遍的；大体的，概括的；首席的; n. 将军', '/\'dʒenrəl | \'dʒɛnrəl/', 'general', 4);
INSERT INTO `words` VALUES (20611, NULL, 'v. 概括； 推广', '/\'dʒenrəlaɪz | \'dʒenərəlaiz/', 'generalise', 4);
INSERT INTO `words` VALUES (20612, 'Critics love to generalize, to formulate trends into which all new work must be fitted, however contradictory.', 'v. 概括，归纳', '/\'dʒenərəlaiz | ˈdʒɛnrəˌlaɪz | \'dʒɛnrəlaɪz/', 'generalize', 4);
INSERT INTO `words` VALUES (20613, 'a useful technique for generating new ideas', 'v. 使产生，使发生', '/\'dʒenəreɪt | \'dʒɛnəret/', 'generate', 4);
INSERT INTO `words` VALUES (20614, 'the generative power of the life force', 'adj. 生殖的， 生产的； 有生产能力的', '/\'dʒenərətɪv | \'dʒɛnərətɪv/', 'generative', 4);
INSERT INTO `words` VALUES (20615, 'Parmesan is a generic term used to describe a family of hard Italian cheeses.', 'adj. 一般的，普通的', '/dʒi\'nerik | dʒɪ\'nerɪk | dʒə\'nɛrɪk/', 'generic', 4);
INSERT INTO `words` VALUES (20616, 'a generous glass of wine', 'adj. 慷慨的，丰盛的', '/\'dʒenərəs | \'dʒen(ə)rəs | \'dʒɛnərəs/', 'generous', 4);
INSERT INTO `words` VALUES (20617, 'genetic defects', 'adj. 遗传学的；发生的', '/dʒi\'netik | dʒɪ\'netɪk | dʒə\'nɛtɪk/', 'genetic', 4);
INSERT INTO `words` VALUES (20618, 'a genial smile', 'adj. 和蔼的，亲切的，温和的', '/\'dʒi:njəl | \'dʒiːnɪəl | \'dʒinɪəl/', 'genial', 4);
INSERT INTO `words` VALUES (20619, 'The film reveals Fellini’s genius.', 'n. 天才，天才人物，才华', '/\'dʒi:njəs | \'dʒiːnɪəs | \'dʒinjəs/', 'genius', 4);
INSERT INTO `words` VALUES (20620, 'Arthur was a very gentle, caring person.', 'adj. 文雅的；有礼貌的', '/\'dʒentl | \'dʒent(ə)l | \'dʒɛntl/', 'gentle', 4);
INSERT INTO `words` VALUES (20621, '‘Did he really?’ Her surprise seemed genuine.', 'adj. 真正的，名副其实的', '/\'dʒenjuin | \'dʒenjʊɪn | \'dʒɛnjʊɪn/', 'genuine', 4);
INSERT INTO `words` VALUES (20622, 'their geographical proximity to Japan (= nearness to Japan )', 'adj. 地理学的； 地理的', '/ˌdʒiːə\'græfɪkl | dʒɪə\'græfɪkl/', 'geographical', 4);
INSERT INTO `words` VALUES (20623, 'With geological maps, books, and atlases you can find out all the proven sites of precious minerals.', 'adj. 地质的， 地质学的', '/ˌdʒiːə\'lɒdʒɪkl | dʒɪə\'lɑdʒɪkl/', 'geological', 4);
INSERT INTO `words` VALUES (20624, 'He was visiting professor of geology at the University of Georgia.', 'n. 地质学；地质', '/dʒi\'ɔlədʒi | dʒɪ\'ɒlədʒɪ | dʒɪ\'ɑlədʒi/', 'geology', 4);
