INSERT INTO `words` VALUES (20844, '...the horror of this most bloody of civil wars.', 'n. 害怕， 恐怖', '/\'hɒrə(r) | \'hɔrɚ/', 'horror', 4);
INSERT INTO `words` VALUES (20845, 'The area has a long tradition of horticulture.', 'n. 园艺', '/\'hɔ:tikʌltʃə | \'hɔːtɪ,kʌltʃə | \'hɔrtɪ\'kʌltʃɚ/', 'horticulture', 4);
INSERT INTO `words` VALUES (20846, 'Water in the engine compartment is sucked away by a hose.', 'n. 输水软管；长统袜; v. 浇园子，用管冲洗', '/həʊz | hoz/', 'hose', 4);
INSERT INTO `words` VALUES (20847, 'The local people were very kind and hospitable.', 'adj. 好客的， 殷勤的， 热情友好的； 宜人的； 易接受的， 开通的', '/hɒ\'spɪtəbl | hɑ\'spɪtəbl/', 'hospitable', 4);
INSERT INTO `words` VALUES (20848, 'Thanks for your hospitality over the past few weeks.', 'n. 好客，殷勤', '/,hɔspi\'tæləti | hɒspɪ\'tælɪtɪ | ,hɑspɪ\'tæləti/', 'hospitality', 4);
INSERT INTO `words` VALUES (20849, 'Our host greeted us at the door.', 'n. 主人; 许多，一大群，旅店老板', '/həust | həʊst | host/', 'host', 4);
INSERT INTO `words` VALUES (20850, 'The group are holding two tourists hostage (= keeping them as hostages ) .', 'n. 人质', '/\'hɔstidʒ | \'hɒstɪdʒ | \'hɑstɪdʒ/', 'hostage', 4);
INSERT INTO `words` VALUES (20851, NULL, 'n. 招待所； 学生宿舍', '/\'hɒstl | \'hɑstl/', 'hostel', 4);
INSERT INTO `words` VALUES (20852, 'Southampton fans gave their former coach a hostile reception .', 'adj. 敌对的，敌方的，不友好的', '/\'hɔstail, -təl | \'hɒstaɪl | ˈhɑstəl/', 'hostile', 4);
INSERT INTO `words` VALUES (20853, 'The reform program was greeted with hostility by conservatives.', 'n. 敌意，敌对，对抗；抵制，反对，否决；', '/hɒ\'stɪləti | hɑ\'stɪləti/', 'hostility', 4);
INSERT INTO `words` VALUES (20854, 'A troubled hound was baying the moon.', 'n. 猎狗；卑鄙的人; v. 用猎狗追，追逐', '/haund | haʊnd/', 'hound', 4);
INSERT INTO `words` VALUES (20855, 'household chores', 'adj. 家庭的， 家用的， 普通的； 家喻户晓的; n. 家庭，户，全家人', '/\'haushəuld | \'haʊshold/', 'household', 4);
INSERT INTO `words` VALUES (20856, 'Judith was hovering in the doorway.', 'v. (鸟)盘旋，翱翔，(人)逗留在附近徘徊', '/\'hɔvə, \'hʌ- | \'hɒvə | \'hʌvɚ/', 'hover', 4);
INSERT INTO `words` VALUES (20857, 'You can do it however you like.', 'conj. 不管用什么方法，', '/hau\'evə(r) | haʊ\'ɛvɚ/', 'however', 4);
INSERT INTO `words` VALUES (20858, 'The dogs howled all night.', 'n&v. 嚎叫，怒吼', '/haul | haʊl/', 'howl', 4);
INSERT INTO `words` VALUES (20859, 'the hubbub from the market', 'n. 吵闹，喧哗', '/\'hʌbʌb/', 'hubbub', 4);
INSERT INTO `words` VALUES (20860, 'We lay huddled together for warmth.', 'v. 挤作一团，乱堆; n. 一堆，一团', '/\'hʌdl | \'hʌd(ə)l/', 'huddle', 4);
INSERT INTO `words` VALUES (20861, 'We stood there crying and hugging each other.', 'vt&n. 紧抱，拥抱', '/hʌɡ | hʌg/', 'hug', 4);
INSERT INTO `words` VALUES (20862, 'Machines hummed on the factory floor.', 'v&n. 嗡嗡叫，嘈杂声', '/hʌm/', 'hum', 4);
INSERT INTO `words` VALUES (20863, 'the campaign for the humane treatment of criminals', 'adj. 善良的， 人道的， 仁慈的， 慈悲的； 促进文明或教化的， 人文的', '/hjuː\'meɪn | hju\'men/', 'humane', 4);
INSERT INTO `words` VALUES (20864, 'Religious values can often differ greatly from humanistic morals.', 'adj. 人文主义的， 人性的', '/ˌhjuːmə\'nɪstɪk | ,hjʊmən\'ɪstɪk/', 'humanistic', 4);
INSERT INTO `words` VALUES (20865, 'We want a clean healthy environment for all humanity .', 'n. 人类；仁慈，仁爱', '/hju:\'mænəti | hjʊ\'mænɪtɪ | hjʊ\'mænəti/', 'humanity', 4);
INSERT INTO `words` VALUES (20866, 'a modest and humble man', 'adj. 谦卑的，恭顺的，简陋的; v. 使卑下，贬抑', '/\'hʌmbl/', 'humble', 4);
INSERT INTO `words` VALUES (20867, '...her lawyer husband, trapped in a humdrum but well-paid job.', 'adj. 单调的，枯燥的', '/\'hʌmdrʌm/', 'humdrum', 4);
INSERT INTO `words` VALUES (20868, 'Tokyo is extremely humid in mid-summer.', 'adj. 湿的， 潮湿的， 湿润的， 多潮气的', '/\'hjuːmɪd | \'hjumɪd/', 'humid', 4);
INSERT INTO `words` VALUES (20869, 'The room is kept at 72 degrees and 50% relative humidity.', 'n. 湿气，空气湿度', '/hju:\'midəti | hjʊ\'mɪdɪtɪ | hju\'mɪdəti/', 'humidity', 4);
INSERT INTO `words` VALUES (20870, 'Her boss humiliated her in front of all her colleagues.', 'v. 使羞辱，使丢脸', '/hju:\'milieit | hjʊ\'mɪlɪeɪt | hju\'mɪlɪet/', 'humiliate', 4);
INSERT INTO `words` VALUES (20871, 'his humour and charm', 'n. 幽默， 幽默感', '/\'hjuːmə(r) | \'hju:mə/', 'humour', 4);
INSERT INTO `words` VALUES (20872, 'Finding enough money for the project was the first hurdle.', 'n. 障碍；', '/\'hɜːdl | \'hɝdl/', 'hurdle', 4);
INSERT INTO `words` VALUES (20873, 'Demonstrators were hurling bricks through the windows.', 'vt&n. 猛掷，猛投', '/hə:l | hɜːl | hɝl/', 'hurl', 4);
INSERT INTO `words` VALUES (20874, 'The hurricane devastated a large section of the coast.', 'n. 飓风', '/\'hʌrikən | \'hʌrɪk(ə)n; -keɪn | hʌrɪˌken/', 'hurricane', 4);
INSERT INTO `words` VALUES (20875, '...the hybrid corn seed.', 'adj. 杂交产生的； 混合的， 合成的; n. 杂交生成的生物体，杂交植物；杂种，混血儿；混合物，合成物', '/\'haɪbrɪd/', 'hybrid', 4);
INSERT INTO `words` VALUES (20876, 'Water contains hydrogen and oxygen.', 'n. 氢气', '/\'haidrədʒən | \'haɪdrədʒ(ə)n | \'haɪdrədʒən/', 'hydrogen', 4);
INSERT INTO `words` VALUES (20877, 'the importance of personal hygiene', 'n. 卫生', '/\'haidʒi:n | \'haɪdʒiːn | \'haɪdʒin/', 'hygiene', 4);
INSERT INTO `words` VALUES (20878, 'His voice had a smooth hypnotic effect .', 'adj. 催眠的; n. 催眠药', '/hɪp\'nɒtɪk | hɪp\'nɑtɪk/', 'hypnotic', 4);
INSERT INTO `words` VALUES (20879, 'One hypothesis is that the victim fell asleep while driving.', 'n. (逻辑)前提，假说', '/hai\'pɔθisis | haɪ\'pɒθɪsɪs | haɪ\'pɑθəsɪs/', 'hypothesis', 4);
INSERT INTO `words` VALUES (20880, 'The question is purely hypothetical .', 'adj. 假设的， 假定的； 爱猜想的', '/ˌhaɪpə\'θetɪkl | ,haɪpə\'θɛtɪkl/', 'hypothetical', 4);
INSERT INTO `words` VALUES (20881, 'Janet became hysterical and began screaming.', 'adj. 歇斯底里的, 狂热的', '/his\'terikəl | hɪ\'sterɪk(ə)l | hɪ\'stɛrɪkl/', 'hysterical', 4);
INSERT INTO `words` VALUES (20882, 'Walt Disney stayed true to his ideals.', 'n. 理想的事物；理想; adj. 完美的，理想的', '/ai\'diəl | aɪ\'dɪəl; aɪ\'diːəl | aɪ\'diəl/', 'ideal', 4);
INSERT INTO `words` VALUES (20883, 'four identical houses', 'adj. 同一的，完全相似的', '/ai\'dentikəl | aɪ\'dentɪk(ə)l | aɪ\'dɛntɪkl/', 'identical', 4);
INSERT INTO `words` VALUES (20884, 'In the corridor were four dirty, ragged bundles, just identifiable as human beings.', 'adj. 可辨认的， 可识别的； 可确定的， 可证明是同一的', '/aɪ\'dentɪ\'faɪəbl | aɪ,dɛntɪ\'faɪəbl/', 'identifiable', 4);
INSERT INTO `words` VALUES (20885, 'Do you have any identification?', 'n. 认出，识别；身分证明', '/ai,dentifi\'keiʃən | aɪ,dentɪfɪ\'keɪʃ(ə)n | aɪˌdentɪfɪ\'keʃn/', 'identification', 4);
INSERT INTO `words` VALUES (20886, 'He was too far away to be able to identify faces.', 'v. 认出，认为与一致', '/aɪ\'dentɪfaɪ | aɪ\'dɛntɪfaɪ/', 'identify', 4);
INSERT INTO `words` VALUES (20887, 'The identity of the killer is still unknown.', 'n. 身份; 同一; 一致；特性', '/ai\'dentəti | aɪ\'dentɪtɪ | aɪ\'dɛntəti/', 'identity', 4);
INSERT INTO `words` VALUES (20888, 'the ideologies of fascism and terrorism', 'n. 思想，思想体系，意识形态', '/,aidi\'ɔlədʒi, ,idi- | ,aɪdɪ\'ɒlədʒɪ; ɪd-/', 'ideology', 4);
INSERT INTO `words` VALUES (20889, 'the new musical idiom', 'n. 习语，成语', '/\'idiəm | \'ɪdɪəm/', 'idiom', 4);
INSERT INTO `words` VALUES (20890, 'Are you an idiot?', 'n. 白痴', '/\'idiət | \'ɪdɪət/', 'idiot', 4);
INSERT INTO `words` VALUES (20891, 'Go and wake up that idle brother of yours.', 'adj. 闲着的，空闲的；懒的；无根据的; v. 虚度', '/\'aidl | \'aɪd(ə)l | \'aɪdl/', 'idle', 4);
INSERT INTO `words` VALUES (20892, 'The petrol tank suddenly ignited.', 'v. 点燃，使燃烧', '/iɡ\'nait | ɪg\'naɪt | ɪɡ\'naɪt/', 'ignite', 4);
INSERT INTO `words` VALUES (20893, 'Excuse my ignorance, but how does it actually work?', 'n. 无知，愚昧', '/\'iɡnərəns | \'ɪgn(ə)r(ə)ns | \'ɪɡnərəns/', 'ignorance', 4);
INSERT INTO `words` VALUES (20894, 'an ignorant and uneducated man', 'adj. 无知的； 愚昧的', '/\'ɪgnərənt | \'ɪɡnərənt/', 'ignorant', 4);
INSERT INTO `words` VALUES (20895, 'You can’t ignore the fact that many criminals never go to prison.', 'vt. 不顾， 不理， 忽视', '/ɪg\'nɔː(r) | ɪɡ\'nɔr/', 'ignore', 4);
INSERT INTO `words` VALUES (20896, 'illegal drugs', 'adj. 不合法的， 违法的', '/ɪ\'liːgl | ɪ\'ligl/', 'illegal', 4);
INSERT INTO `words` VALUES (20897, '...a subclass of illiterates.', 'n&a. 文盲(的)', '/i\'litərət | ɪ\'lɪt(ə)rət | ɪ\'lɪtərət/', 'illiterate', 4);
INSERT INTO `words` VALUES (20898, 'A single candle illuminated his face.', 'v. 照亮；用灯装饰；阐明', '/i\'lju:mineit | ɪ\'l(j)uːmɪneɪt | ɪ\'lumɪnet/', 'illuminate', 4);
INSERT INTO `words` VALUES (20899, 'She was under no illusion that he loved her.', 'n. 幻象，错觉', '/i\'lju:ʒən | ɪ\'l(j)uːʒ(ə)n | ɪ\'luʒn/', 'illusion', 4);
INSERT INTO `words` VALUES (20900, 'Let me give an example to illustrate the point.', 'v. 举例或以图表说明，配以插图', '/\'iləstreit | \'ɪləstreɪt | \'ɪləstret/', 'illustrate', 4);
INSERT INTO `words` VALUES (20901, 'The book contains 62 pages of illustrations.', 'n. 说明； 实例； 图解， 插图', '/ˌɪlə\'streɪʃn | ,ɪlə\'streʃən/', 'illustration', 4);
INSERT INTO `words` VALUES (20902, 'He had the clearest image in his mind of his mother and father.', 'n. 形象； 印象； 图像', '/\'ɪmɪdʒ/', 'image', 4);
INSERT INTO `words` VALUES (20903, 'a storyteller with an incredible imagination', 'n. 想象； 想象出来的事物', '/ɪˌmædʒɪ\'neɪʃn | ɪ,mædʒɪ\'neʃən/', 'imagination', 4);
INSERT INTO `words` VALUES (20904, 'an imaginative use of computer technology', 'adj. 想象的，有想象力的', '/ɪ\'mædʒɪnətɪv/', 'imaginative', 4);
INSERT INTO `words` VALUES (20905, 'Perhaps she’d never really been there at all – perhaps she’d just imagined it.', 'v. 想象； 猜想', '/ɪ\'mædʒɪn/', 'imagine', 4);
INSERT INTO `words` VALUES (20906, 'She was a splendid mimic and loved to imitate Winston Churchill.', 'v. 模仿，模拟，看似', '/\'imiteit | \'ɪmɪteɪt | \'ɪmɪtet/', 'imitate', 4);
INSERT INTO `words` VALUES (20907, 'The remake of ‘Casablanca’ was a pale imitation (= something that is much less good than the thing it imitates ) of the original movie.', 'n. 模仿，仿造，仿制品，人造', '/,imi\'teiʃən | ɪmɪ\'teɪʃ(ə)n | ,ɪmɪ\'teʃən/', 'imitation', 4);
INSERT INTO `words` VALUES (20908, 'Mix in the remaining ingredients and serve immediately.', 'adv. 立即， 马上； 紧接地； 直接地', '/ɪ\'miːdiətli | ɪ\'midɪətli/', 'immediately', 4);
INSERT INTO `words` VALUES (20909, 'People who travel by rail still read an immense amount.', 'adj. 广大的，巨大的', '/i\'mens | ɪ\'mens | ɪ\'mɛns/', 'immense', 4);
INSERT INTO `words` VALUES (20910, 'He left school at 16 and immersed himself in the Labour Party.', 'v. 沉浸，沉浸于', '/i\'mə:s | ɪ\'mɜːs | ɪ\'mɝs/', 'immerse', 4);
INSERT INTO `words` VALUES (20911, 'an illegal immigrant', 'n. 移民，侨民', '/\'imiɡrənt | \'ɪmɪgr(ə)nt | \'ɪmɪɡrənt/', 'immigrant', 4);
INSERT INTO `words` VALUES (20912, 'He called for a common European policy on immigration.', 'n. 外来的移民； 移居', '/ˌɪmɪ\'greɪʃn | ,ɪmɪ\'ɡreʃən/', 'immigration', 4);
INSERT INTO `words` VALUES (20913, 'A new trade agreement is imminent.', 'adj. 迫近的，紧迫的', '/\'iminənt | \'ɪmɪnənt/', 'imminent', 4);
INSERT INTO `words` VALUES (20914, 'Once we’ve had the disease, we’re immune for life.', 'adj. 免除的；安全的，不受影响的', '/i\'mju:n | ɪ\'mjuːn | ɪ\'mjʊn/', 'immune', 4);
INSERT INTO `words` VALUES (20915, 'The force of the impact knocked the breath out of her.', 'n. 碰撞，撞击，撞击力', '/\'ɪmpækt | ɪm\'pækt/', 'impact', 4);
INSERT INTO `words` VALUES (20916, 'The illness had impaired his ability to think and concentrate.', 'v. 损害，削弱', '/im\'pεə | ɪm\'peə | ɪm\'pɛr/', 'impair', 4);
INSERT INTO `words` VALUES (20917, 'She had information that she couldn’t wait to impart.', 'v. 告知，透露，给予', '/im\'pɑ:t | ɪm\'pɑːt | ɪm\'pɑrt/', 'impart', 4);
INSERT INTO `words` VALUES (20918, 'Storms at sea impeded our progress.', 'v. 妨碍；阻碍', '/im\'pi:d | ɪm\'piːd | ɪm\'pid/', 'impede', 4);
INSERT INTO `words` VALUES (20919, 'It is imperative that politicians should be good communicators.', 'adj. 紧急的，必要的，强制的，祈使语气', '/ɪm\'perətɪv | ɪm\'pɛrətɪv/', 'imperative', 4);
INSERT INTO `words` VALUES (20920, 'Britain’s imperial expansion in the 19th century', 'adj. 帝国的，皇帝的', '/im\'piəriəl | ɪm\'pɪərɪəl | ɪm\'pɪrɪəl/', 'imperial', 4);
INSERT INTO `words` VALUES (20921, 'Tax increases now might imperil economic recovery.', 'vt. 使陷于危险， 危及', '/ɪm\'perəl | ɪm\'pɛrəl/', 'imperil', 4);
INSERT INTO `words` VALUES (20922, 'The discovery gave fresh impetus to the research.', 'n. 动力，原动力，推动，激励', '/\'impitəs | \'ɪmpɪtəs/', 'impetus', 4);
INSERT INTO `words` VALUES (20923, 'The government promised to implement a new system to control financial loan institutions.', 'n. 工具，器具; v. 贯彻，履行', '/\'implimənt, \'impliment | \'ɪmplɪm(ə)nt | \'ɪmplɪmɛnt/', 'implement', 4);
INSERT INTO `words` VALUES (20924, 'They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.', 'n. 含意； 暗示， 暗指； 卷入， 牵连', '/ˌɪmplɪ\'keɪʃn | \'ɪmplɪ\'keʃən/', 'implication', 4);
INSERT INTO `words` VALUES (20925, '...an implicit warning to the Moroccans not to continue or repeat the military actions they began a week ago.', 'adj. 含蓄的，暗示的，无保留的', '/im\'plisit | ɪm\'plɪsɪt/', 'implicit', 4);
INSERT INTO `words` VALUES (20926, 'Parents should beware of imposing their own tastes on their children.', 'v. 把…强加于；征(税)，利用', '/im\'pəuz | ɪm\'pəʊz | ɪm\'poz/', 'impose', 4);
INSERT INTO `words` VALUES (20927, 'an imposing building', 'adj. 壮观的，气势雄伟的', '/im\'pəuziŋ | ɪm\'pəʊzɪŋ | ɪm\'pozɪŋ/', 'imposing', 4);
INSERT INTO `words` VALUES (20928, '‘I want to speak to Mr Franks.’ ‘I’m afraid that’s impossible.’', 'adj. 不可能的， 办不到的', '/ɪm\'pɒsəbl | ɪm\'pɑsəbl/', 'impossible', 4);
INSERT INTO `words` VALUES (20929, 'Falling coffee prices have impoverished many developing economies.', 'vt. 使贫困； 使枯竭， 使贫瘠', '/ɪm\'pɒvərɪʃ | ɪm\'pɑvərɪʃ/', 'impoverish', 4);
INSERT INTO `words` VALUES (20930, NULL, 'adj. 穷困的， 赤贫的； 贫乏的， 贫瘠的； 枯竭的', '/ɪm\'pɒvərɪʃt | ɪm\'pɑvərɪʃt/', 'impoverished', 4);
INSERT INTO `words` VALUES (20931, 'vague imprecise estimates', 'adj. 不精确的， 不严密的', '/ˌɪmprɪ\'saɪs | \'ɪmprɪ\'saɪs/', 'imprecise', 4);
INSERT INTO `words` VALUES (20932, 'Steve borrowed his dad’s sports car to impress his girlfriend.', 'vt. 给…留下深刻印象，使铭记；印，压印; n. 印记', '/ɪm\'pres | ɪm\'prɛs/', 'impress', 4);
INSERT INTO `words` VALUES (20933, 'When we looked around the school we got a very good impression.', 'n. 印象， 感想； 印记， 压痕', '/ɪm\'preʃn | ɪm\'prɛʃən/', 'impression', 4);
INSERT INTO `words` VALUES (20934, 'The figures certainly look impressive.', 'adj. 给人深刻印象的，惊人的', '/im\'presiv | ɪm\'presɪv | ɪm\'prɛsɪv/', 'impressive', 4);
INSERT INTO `words` VALUES (20935, NULL, 'a&ad. 无准备的(地)；即兴的(地)', '/im\'prɔmptju: | ɪm\'prɒm(p)tjuː | ɪm\'prɑmptu/', 'impromptu', 4);
INSERT INTO `words` VALUES (20936, 'a course for students wishing to improve their English', 'v. 改善， 改进', '/ɪm\'pruːv | ɪm\'pruv/', 'improve', 4);
INSERT INTO `words` VALUES (20937, 'Our results have shown some improvement this month.', 'n. 改进， 进步； 改进措施； 改进处', '/ɪm\'pruːvmənt | ɪm\'prʊvmənt/', 'improvement', 4);
INSERT INTO `words` VALUES (20938, 'I forgot to bring my notes, so I had to improvise.', 'v. 即席创作，临时凑成', '/\'imprəvaiz | \'ɪmprəvaɪz/', 'improvise', 4);
INSERT INTO `words` VALUES (20939, 'The eye converts light signals to nerve impulses.', 'n. 推动，冲力，冲动', '/\'impʌls | \'ɪmpʌls/', 'impulse', 4);
INSERT INTO `words` VALUES (20940, 'a room furnished in the modern style', 'prep. favour; of赞成，以. 为收款人', '/in | ɪn/', 'in', 4);
INSERT INTO `words` VALUES (20941, NULL, '依照；与…一致', NULL, 'in accordance with', 4);
INSERT INTO `words` VALUES (20942, NULL, '另外，此外', NULL, 'in addition', 4);
INSERT INTO `words` VALUES (20943, 'So what should we do to promote peace, in addition to the proposals mentioned above?', '除. 之外（还有，也）', NULL, 'in addition to', 4);
INSERT INTO `words` VALUES (20944, 'Alexander and Gaius and Pompeius, what are they in comparison with Diogenes and Heraclitus and Socrates?', '与…比较，同…比较起来', NULL, 'in comparison with', 4);
INSERT INTO `words` VALUES (20945, 'I am not in favour of the Arsenal system.', '支持，赞成', NULL, 'in favour of', 4);
INSERT INTO `words` VALUES (20946, 'Have ye suffered so many things in vain? if it be yet in vain.', '徒然；无效', NULL, 'in vain', 4);
INSERT INTO `words` VALUES (20947, 'The brain cells are inactive during sleep.', 'adj. 不活动的； 懒散的', '/ɪn\'æktɪv/', 'inactive', 4);
INSERT INTO `words` VALUES (20948, 'inadequate resources', 'adj. 不充分的； 不适当的', '/ɪn\'ædɪkwət/', 'inadequate', 4);
INSERT INTO `words` VALUES (20949, 'inalienable human rights', 'adj. 不可剥夺的， 不可分割的', '/ɪn\'eɪlɪənəbl | ɪn\'elɪənəbl/', 'inalienable', 4);
INSERT INTO `words` VALUES (20950, 'a very inapt comment', 'adj. 不适当的，不合适的', '/in\'æpt | ɪn\'æpt/', 'inapt', 4);
INSERT INTO `words` VALUES (20951, 'The Turner Prize was inaugurated in 1984.', 'v. 为举行就职典礼，为展览会揭幕，开创', '/i\'nɔ:ɡjureit | ɪ\'nɔːgjʊreɪt | ɪ\'nɔɡjəret/', 'inaugurate', 4);
INSERT INTO `words` VALUES (20952, 'Mammals have an inborn fear of snakes.', 'adj. 天生的， 先天的， 天赋的', '/ˌɪn\'bɔːn | ,ɪn\'bɔrn/', 'inborn', 4);
INSERT INTO `words` VALUES (20953, 'Her mother has been incapacitated by a fall.', 'vt. 使无能力； 使伤残； 使不适合； 使无资格', '/ˌɪnkə\'pæsɪteɪt | ,ɪnkə\'pæsɪtet/', 'incapacitate', 4);
INSERT INTO `words` VALUES (20954, 'a hip-hop album with incendiary lyrics', 'adj. 放火的， 能引起燃烧的； 煽动性的', '/ɪn\'sendɪəri | ɪn\'sɛndɪɛri/', 'incendiary', 4);
INSERT INTO `words` VALUES (20955, 'As an added incentive, there’s a bottle of champagne for the best team.', 'n. 鼓励，激励，动机', '/in\'sentiv | ɪn\'sentɪv | ɪn\'sɛntɪv/', 'incentive', 4);
INSERT INTO `words` VALUES (20956, 'The incidence of breast cancer increases with age.', 'n. 发生率，影响的方式', '/\'insidəns | \'ɪnsɪd(ə)ns | \'ɪnsɪdəns/', 'incidence', 4);
INSERT INTO `words` VALUES (20957, 'Am I at risk because of some incident in my sexual past?', 'n. 发生的事； 事件， 事变', '/\'ɪnsɪdənt/', 'incident', 4);
INSERT INTO `words` VALUES (20958, 'Quite incidentally, I got some useful information at the party.', 'adv. 偶然地，顺便地', '/,insi\'dentəli | ɪnsɪ\'dent(ə)lɪ | ,ɪnsɪ\'dɛntli/', 'incidentally', 4);
INSERT INTO `words` VALUES (20959, 'All the infected clothing was incinerated.', 'vt. 焚化， 焚毁， 把…烧成灰烬', '/ɪn\'sɪnəreɪt | in\'sinəreit/', 'incinerate', 4);
INSERT INTO `words` VALUES (20960, 'a sign of incipient madness', 'adj. 开始的；早期的', '/in\'sipiənt | ɪn\'sɪpɪənt/', 'incipient', 4);
INSERT INTO `words` VALUES (20961, 'They were charged with inciting racial hatred.', 'v. 激励；煽动', '/in\'sait | ɪn\'saɪt/', 'incite', 4);
INSERT INTO `words` VALUES (20962, 'My natural inclination was to say no.', 'n. 倾向，意愿', '/,inkli\'neiʃən | ɪnklɪ\'neɪʃ(ə)n | \'ɪnklə\'neʃən/', 'inclination', 4);
INSERT INTO `words` VALUES (20963, 'The telescope is inclined at an angle of 43 degrees.', 'v. 低头，屈身，倾斜，倾向于; n. 斜坡，斜面', '/in\'klain | ɪn\'klaɪn/', 'incline', 4);
INSERT INTO `words` VALUES (20964, 'Does the price include postage?', 'v. 包括， 包含； 计入', '/ɪn\'kluːd | ɪn\'klud/', 'include', 4);
INSERT INTO `words` VALUES (20965, 'Not everyone shares his vision of an inclusive America.', 'adj. 包括的，包含的', '/in\'klu:siv | ɪn\'kluːsɪv | ɪn\'klusɪv/', 'inclusive', 4);
INSERT INTO `words` VALUES (20966, 'incoming flights', 'adj. 进来的', '/\'ɪnkʌmɪŋ/', 'incoming', 4);
INSERT INTO `words` VALUES (20967, 'I don’t know why they ever got married. They’re totally incompatible.', 'adj. 不兼容的， 不能和谐共存的， 不协调的， 合不来的', '/ˌɪnkəm\'pætəbl | ,ɪnkəm\'pætəbl/', 'incompatible', 4);
INSERT INTO `words` VALUES (20968, 'The incongruity of her situation struck Gina with unpleasant force.', 'n. 不和谐， 不相称； 不协调或不一致的事物', '/ˌɪnkɒŋ\'gruːəti | ,ɪnkɑŋ\'grʊəti/', 'incongruity', 4);
INSERT INTO `words` VALUES (20969, 'The new theatre looks utterly incongruous in its setting.', 'adj. 不适宜的', '/in\'kɔŋɡruəs | ɪn\'kɒŋgrʊəs | ɪn\'kɑŋɡruəs/', 'incongruous', 4);
INSERT INTO `words` VALUES (20970, 'The new cars will incorporate a number of major improvements.', 'v. 结合，合并，组成公司', '/in\'kɔ:pəreit, in\'kɔ:pərət | ɪn\'kɔːpəreɪt/', 'incorporate', 4);
INSERT INTO `words` VALUES (20971, 'It’s incredible that he survived the fall.', 'adj. 难以置信的，惊人的', '/in\'kredəbl | ɪn\'kredɪb(ə)l | ɪn\'krɛdəbl/', 'incredible', 4);
INSERT INTO `words` VALUES (20972, 'Any time you want to add another test, just add another row to your datapool and increment the counter value in the loop.', 'n. 增值，增额', '/\'inkrimənt | \'ɪŋkrɪm(ə)nt | \'ɪŋkrəmənt/', 'increment', 4);
INSERT INTO `words` VALUES (20973, 'Not all schools manage to successfully inculcate a love of learning.', 'vt. 谆谆教诲， 反复灌输', '/\'ɪnkʌlkeɪt | ɪn\'kʌlket/', 'inculcate', 4);
INSERT INTO `words` VALUES (20974, 'The government had also incurred huge debts.', 'v. 招致; 遭受', '/in\'kə: | ɪn\'kɜː | ɪn\'kɝ/', 'incur', 4);
INSERT INTO `words` VALUES (20975, 'The next day the union voted to begin an indefinite strike.', 'adj. 模糊的，不明确的，无定限的', '/in\'definət | ɪn\'defɪnɪt | ɪn\'dɛfɪnət/', 'indefinite', 4);
INSERT INTO `words` VALUES (20976, 'Her words left an indelible impression on me for years to come.', 'adj. 去不掉的，擦不掉的', '/in\'deləbl | ɪn\'delɪb(ə)l | ɪn\'dɛləbl/', 'indelible', 4);
INSERT INTO `words` VALUES (20977, 'insurance providing indemnity against future liabilities', 'n. 保障，保护；赔偿', '/in\'demnəti | ɪn\'demnɪtɪ | ɪn\'dɛmnəti/', 'indemnity', 4);
INSERT INTO `words` VALUES (20978, 'The country has made great advances since independence.', 'n. 独立， 自主', '/ˌɪndɪ\'pendəns | ,ɪndɪ\'pɛndəns/', 'independence', 4);
INSERT INTO `words` VALUES (20979, 'There are plans to split the corporation into a number of smaller independent companies.', 'adj. 独立的，自主的，不受约束的; n. 中立派， 无党派议员', '/ˌɪndɪ\'pendənt | \'ɪndɪ\'pɛndənt/', 'independent', 4);
INSERT INTO `words` VALUES (20980, 'The study indicates a connection between poverty and crime.', 'v. 标示， 表示， 表明； 象征； 暗示， 示意', '/\'ɪndɪkeɪt | \'ɪndɪket/', 'indicate', 4);
INSERT INTO `words` VALUES (20981, 'Could you give me some indication as to when I am likely to receive a reply?', 'n. 指示， 象征', '/ˌɪndɪ\'keɪʃn | ,ɪndɪ\'keʃən/', 'indication', 4);
INSERT INTO `words` VALUES (20982, 'His action is indicative of growing concern about the shortage of skilled labour.', 'adj. 指示的；表示的', '/in\'dikətiv | ɪn\'dɪkətɪv/', 'indicative', 4);
INSERT INTO `words` VALUES (20983, 'All the main economic indicators suggest that trade is improving.', 'n. 指示者，指示物', '/\'indikeitə | \'ɪndɪkeɪtə | \'ɪndɪketɚ/', 'indicator', 4);
INSERT INTO `words` VALUES (20984, 'an indifferent cook', 'adj. 不感兴趣的，不关心的，质量不高的', '/in\'difərənt | ɪn\'dɪf(ə)r(ə)nt | ɪn\'dɪfrənt/', 'indifferent', 4);
INSERT INTO `words` VALUES (20985, 'the many indigenous cultures which existed in Siberia', 'adj. 土生土长的，本土的', '/in\'didʒinəs | ɪn\'dɪdʒɪnəs | ɪn\'dɪdʒənəs/', 'indigenous', 4);
INSERT INTO `words` VALUES (20986, 'an indignant reply', 'adj. 义愤的，愤慨的', '/in\'diɡnənt | ɪn\'dɪgnənt | ɪn\'dɪɡnənt/', 'indignant', 4);
INSERT INTO `words` VALUES (20987, 'Mobile phones have become an indispensable part of our lives.', 'adj. 必不可少的，必需的', '/,indis\'pensəbl | ɪndɪ\'spensəb(ə)l | \'ɪndɪ\'spɛnsəbl/', 'indispensable', 4);
INSERT INTO `words` VALUES (20988, 'Each individual leaf on the tree is different.', 'adj. 个人的，个别的；个体的; n. 个人，个体', '/,indi\'vidjuəl, -dʒəl | ɪndɪ\'vɪdjʊ(ə)l | ,ɪndɪ\'vɪdʒuəl/', 'individual', 4);
INSERT INTO `words` VALUES (20989, NULL, 'adj. 懒惰的， 倦怠的； 不活跃的， 无行动的', '/\'ɪndələnt/', 'indolent', 4);
INSERT INTO `words` VALUES (20990, 'Doctors said surgery could induce a heart attack.', 'v. 导致；引起', '/in\'dju:s, in\'du:s | ɪn\'djuːs | ɪn\'dus/', 'induce', 4);
INSERT INTO `words` VALUES (20991, 'Mrs Simpson is responsible for the induction of new library staff.', 'n. 就职； 归纳； 感应', '/ɪn\'dʌkʃn | ɪn\'dʌkʃən/', 'induction', 4);
INSERT INTO `words` VALUES (20992, 'inductive reasoning', 'adj. 诱导的， 归纳的', '/ɪn\'dʌktɪv/', 'inductive', 4);
INSERT INTO `words` VALUES (20993, 'A dynamic self-learning efficient intrusion detection model was proposed based on inductive reasoning.', '[计][数] 归纳推理；归纳法', NULL, 'inductive reasoning', 4);
INSERT INTO `words` VALUES (20994, 'His mother spoiled him, indulging his every whim.', 'v. 放纵，沉迷于', '/in\'dʌldʒ | ɪn\'dʌldʒ/', 'indulge', 4);
INSERT INTO `words` VALUES (20995, 'The way to bring cost down is to industrialise much of the process.', 'v. 工业化', '/in\'dʌstriəlaiz | ɪn\'dʌstrɪəlaɪz/', 'industrialise', 4);
INSERT INTO `words` VALUES (20996, 'She was an industrious and willing worker.', 'adj. 勤奋的， 勤勉的， 勤劳的', '/ɪn\'dʌstriəs | ɪn\'dʌstrɪəs/', 'industrious', 4);
INSERT INTO `words` VALUES (20997, NULL, 'adj. 不适当的', '/i\'nept | ɪ\'nept/', 'inept', 4);
INSERT INTO `words` VALUES (20998, 'inert gases', 'adj. 无活动能力的；惰性的', '/i\'nə:t | ɪ\'nɜːt | ɪ\'nɝt/', 'inert', 4);
INSERT INTO `words` VALUES (20999, 'political inertia', 'n. 呆滞，迟钝，惯性', '/i\'nə:ʃiə | ɪ\'nɜːʃə | ɪ\'nɝʃə/', 'inertia', 4);
INSERT INTO `words` VALUES (21000, 'She didn’t want to confront the inescapable fact that she would have to sell the house.', 'adj. 不可逃避的； 难免的', '/ˌɪnɪ\'skeɪpəbl | \'ɪnə\'skepəbl/', 'inescapable', 4);
INSERT INTO `words` VALUES (21001, 'A further escalation of the crisis now seems inevitable.', 'adj. 不可避免的，照例必有的', '/in\'evitəbl | ɪn\'evɪtəb(ə)l | ɪn\'ɛvɪtəbl/', 'inevitable', 4);
INSERT INTO `words` VALUES (21002, 'An infant’s skin is very sensitive.', 'n. 婴儿', '/\'infənt | \'ɪnf(ə)nt | \'ɪnfənt/', 'infant', 4);
INSERT INTO `words` VALUES (21003, 'People with the virus may feel perfectly well, but they can still infect others.', 'v. 传染，受影响，受感染', '/in\'fekt | ɪn\'fekt | ɪn\'fɛkt/', 'infect', 4);
INSERT INTO `words` VALUES (21004, 'The baby had an ear infection.', 'n. 传染， 感染， 侵染， 传播； 传染病', '/ɪn\'fekʃn | ɪn\'fɛkʃən/', 'infection', 4);
INSERT INTO `words` VALUES (21005, 'infectious diseases', 'adj. 传染的；感染性的', '/in\'fekʃəs | ɪn\'fekʃəs | ɪn\'fɛkʃəs/', 'infectious', 4);
INSERT INTO `words` VALUES (21006, 'I inferred from what she said that you have not been well.', 'v. 推断， 猜想', '/ɪn\'fɜː(r) | ɪn\'fɝ/', 'infer', 4);
INSERT INTO `words` VALUES (21007, 'There were two inferences to be drawn from her letter.', '\"n. 推论, 推断 \"', '/\'infərəns | \'ɪnf(ə)r(ə)ns | \'ɪnfərəns/', 'inference', 4);
INSERT INTO `words` VALUES (21008, 'Finally, people like to stereotype. This is an inferential process based on limited data.', 'adj. 可推断的， 推理的', '/ˌɪnfə\'renʃl | ,ɪnfə\'rɛnʃəl/', 'inferential', 4);
INSERT INTO `words` VALUES (21009, 'It was a gentleman\'s duty always to be civil, even to his inferiors.', 'n. 地位(能力)低的人; adj. 劣质的,差的,下等的\"', '/in\'fiəriə | ɪn\'fɪərɪə | ɪn\'fɪrɪɚ/', 'inferior', 4);
INSERT INTO `words` VALUES (21010, '...pests like aphids which infest cereal crops.', 'v. 大批出动，成群出现(鼠类及害虫)', '/in\'fest | ɪn\'fest | ɪn\'fɛst/', 'infest', 4);
INSERT INTO `words` VALUES (21011, 'Police attempts to infiltrate neo-Nazi groups were largely unsuccessful.', 'v. 悄悄进入， 潜入； 渗入， 渗透', '/\'ɪnfɪltreɪt | ɪn\'fɪltret/', 'infiltrate', 4);
INSERT INTO `words` VALUES (21012, 'The universe is infinite.', 'adj. 无限的，无穷的', '/\'infinət | \'ɪnfɪnət/', 'infinite', 4);
INSERT INTO `words` VALUES (21013, 'All they need now are the keys to the infirmary.', 'n. 医务，医务室', '/in\'fə:məri | ɪn\'fɜːm(ə)rɪ | ɪn\'fɝməri/', 'infirmary', 4);
INSERT INTO `words` VALUES (21014, 'Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity.', 'n. 虚弱， 衰弱', '/ɪn\'fɜːməti | ɪn\'fɝməti/', 'infirmity', 4);
INSERT INTO `words` VALUES (21015, 'Petrol is highly inflammable.', 'adj. 易燃的； 易怒的', '/ɪn\'flæməbl/', 'inflammable', 4);
INSERT INTO `words` VALUES (21016, 'It took us half an hour to inflate the dinghy.', 'v. 使充气， 使膨胀； 使得意， 使骄傲； 抬高， 使膨胀', '/ɪn\'fleɪt | ɪn\'flet/', 'inflate', 4);
INSERT INTO `words` VALUES (21017, 'Inflation is now at over 16%.', 'n. 通货膨胀', '/in\'fleiʃən | ɪn\'fleɪʃ(ə)n | ɪn\'fleʃən/', 'inflation', 4);
INSERT INTO `words` VALUES (21018, 'Detectives warned that the men could inflict serious injury.', 'v. 使遭受，强加', '/in\'flikt | ɪn\'flɪkt/', 'inflict', 4);
INSERT INTO `words` VALUES (21019, 'As a scientist, his influence was immense.', 'n&vt. 影响(力)，感化(力)，有影响的人或事', '/\'influəns | \'ɪnflʊəns | \'ɪnfluəns/', 'influence', 4);
INSERT INTO `words` VALUES (21020, 'He had influential friends.', 'adj. 有影响力的； 有权势的', '/ˌɪnflu\'enʃl | ,ɪnflu\'ɛnʃl/', 'influential', 4);
INSERT INTO `words` VALUES (21021, 'All the medical workers in the region helped to put down the influenza epidemic.', 'n. 流行性感冒', '/ˌɪnflu\'enzə | ,ɪnflu\'ɛnzə/', 'influenza', 4);
INSERT INTO `words` VALUES (21022, NULL, 'n. 汇集，流入', '/\'inflʌks | \'ɪnflʌks/', 'influx', 4);
INSERT INTO `words` VALUES (21023, 'They decided to inform the police.', 'v. 通知； 向…报告', '/ɪn\'fɔːm | ɪn\'fɔrm/', 'inform', 4);
INSERT INTO `words` VALUES (21024, 'One of the witnesses was a paid informant for the FBI.', 'n. 提供消息或情报的人， 线人； 提供资料的人', '/ɪn\'fɔːmənt | ɪn\'fɔrmənt/', 'informant', 4);
INSERT INTO `words` VALUES (21025, 'Some countries lack a suitable economic infrastructure.', 'n. 基础结构， 基础设施', '/\'ɪnfrəstrʌktʃə(r) | \'ɪnfrə\'strʌktʃɚ/', 'infrastructure', 4);
INSERT INTO `words` VALUES (21026, 'A backup copy of a computer program does not infringe copyright.', 'v. 触犯；违反，侵害', '/in\'frindʒ | ɪn\'frɪn(d)ʒ | ɪn\'frɪndʒ/', 'infringe', 4);
INSERT INTO `words` VALUES (21027, 'Many fish have ingenious ways of protecting their eggs from predators.', 'adj. 机灵的；制作精巧的，灵巧的', '/in\'dʒi:njəs | ɪn\'dʒiːnɪəs | ɪn\'dʒinɪəs/', 'ingenious', 4);
INSERT INTO `words` VALUES (21028, 'Combine all the ingredients in a large bowl.', 'n. (混合物的)组成部分，配料', '/in\'ɡri:diənt | ɪn\'griːdɪənt | ɪn\'ɡridɪənt/', 'ingredient', 4);
INSERT INTO `words` VALUES (21029, 'The woods are inhabited by many wild animals.', 'v. 居住于', '/in\'hæbit | ɪn\'hæbɪt/', 'inhabit', 4);
INSERT INTO `words` VALUES (21030, 'a city of six million inhabitants', 'n. 居民', '/in\'hæbitənt | ɪn\'hæbɪt(ə)nt | ɪn\'hæbɪtənt/', 'inhabitant', 4);
INSERT INTO `words` VALUES (21031, 'It is dangerous to inhale ammonia fumes.', 'v. 吸， 吸气', '/ɪn\'heɪl | ɪn\'hel/', 'inhale', 4);
INSERT INTO `words` VALUES (21032, 'Every business has its own inherent risks.', 'adj. 固有的', '/in\'hiərənt | ɪn\'hɪər(ə)nt; -\'her(ə)nt | ɪn\'hɪrənt/', 'inherent', 4);
INSERT INTO `words` VALUES (21033, 'inherited wealth', 'v. 继承，经遗传而得(特性等)', '/in\'herit | ɪn\'herɪt | ɪn\'hɛrɪt/', 'inherit', 4);
INSERT INTO `words` VALUES (21034, 'Lucinda has to fight for her life and her inheritance in this gripping novel.', 'n. 遗传； 继承， 继承物； 遗产， 遗赠', '/ɪn\'herɪtəns | ɪn\'hɛrɪtəns/', 'inheritance', 4);
INSERT INTO `words` VALUES (21035, 'An unhappy family life may inhibit children’s learning.', 'v. 禁止，抑制；阻止', '/in\'hibit | ɪn\'hɪbɪt/', 'inhibit', 4);
INSERT INTO `words` VALUES (21036, 'the inhumane treatment of political prisoners', 'adj. 不近人情的， 残忍的， 不人道的', '/ˌɪnhjuː\'meɪn | \'ɪnhjʊ\'men/', 'inhumane', 4);
INSERT INTO `words` VALUES (21037, 'an initial investment of £5,000', 'adj. 最初的; n. 人名的首字母; v. 签名首字母于', '/i\'niʃəl | ɪ\'nɪʃəl/', 'initial', 4);
INSERT INTO `words` VALUES (21038, 'They have decided to initiate legal proceedings against the newspaper.', 'v. 创始，着手，介绍某人为(会员等)', '/i\'niʃieit, i\'niʃiət, -eit | ɪ\'nɪʃɪeɪt | ɪ\'nɪʃɪet/', 'initiate', 4);
INSERT INTO `words` VALUES (21039, 'I wish my son would show more initiative.', 'n. 发端，创始，主动性', '/i\'niʃiətiv, -ʃətiv | ɪ\'nɪʃɪətɪv; -ʃə- | ɪ\'nɪʃətɪv/', 'initiative', 4);
INSERT INTO `words` VALUES (21040, 'His son was injected with strong drugs.', 'v. 注射；注入，灌入', '/in\'dʒekt | ɪn\'dʒekt | ɪn\'dʒɛkt/', 'inject', 4);
INSERT INTO `words` VALUES (21041, 'the largest area of inland water in the southeast', 'adj. 内地的，内陆的; adv. 在内地，向内地', '/\'inlənd, -lænd | \'ɪnlənd; -lænd | ,ɪn\'lænd/', 'inland', 4);
INSERT INTO `words` VALUES (21042, 'There are several sheltered inlets along the coast.', 'n. 入口； 进口， 水湾', '/\'ɪnlet | ɪnˌlɛt/', 'inlet', 4);
INSERT INTO `words` VALUES (21043, 'Nobody would believe that I was innocent.', 'adj. 无罪的，无害的，天真的; n. 天真无邪的人', '/\'inəsənt | \'ɪnəs(ə)nt | \'ɪnəsnt/', 'innocent', 4);
INSERT INTO `words` VALUES (21044, 'We must encourage innovation if the company is to remain competitive.', 'n. 创新，改革', '/,inəu\'veiʃən | ˌɪnəˈveɪʃn | ,ɪnə\'veʃən/', 'innovation', 4);
INSERT INTO `words` VALUES (21045, 'an innovative approach to language teaching', 'adj. 革新的， 创新的， 新颖的； 富有革新精神的', '/\'ɪnəveɪtɪv | \'ɪnəvetɪv/', 'innovative', 4);
INSERT INTO `words` VALUES (21046, 'She’s served on innumerable committees.', 'adj. 数不清的', '/i\'nuj:mərəbl | ɪ\'njuːm(ə)rəb(ə)l | ɪ\'nʊmərəbl/', 'innumerable', 4);
INSERT INTO `words` VALUES (21047, 'If the input data specified it, the file will close and the process terminates.', 'n. 投入，输入；输入的数据; vt. 把…输入计算机', '/\'ɪnput | \'ɪn\'pʊt/', 'input', 4);
INSERT INTO `words` VALUES (21048, '‘Why are you doing that?’ the boy inquired.', 'v. 打听，询问', '/in\'kwaiə | ɪn\'kwaɪə | ɪn\'kwaɪr/', 'inquire', 4);
INSERT INTO `words` VALUES (21049, 'That’s an insane risk.', 'adj. 愚蠢的; 疯狂的', '/in\'sein | ɪn\'seɪn | ɪn\'sen/', 'insane', 4);
INSERT INTO `words` VALUES (21050, 'Inside the cover someone had inscribed the words ‘To Thomas, with love’.', 'v. 写、 题、 铭刻； 牢记， 铭记', '/ɪn\'skraɪb/', 'inscribe', 4);
INSERT INTO `words` VALUES (21051, 'Many of them work in low-paid insecure jobs.', 'adj. 不安全的， 不可靠的', '/ˌɪnsɪ\'kjuə(r) | ,ɪnsɪ\'kjʊr/', 'insecure', 4);
INSERT INTO `words` VALUES (21052, 'He took a small key from his pocket and slowly inserted it into the lock.', 'v. 插入; n. 插入物，插页', '/ɪn\'sɜːt | \'ɪnsɝt/', 'insert', 4);
INSERT INTO `words` VALUES (21053, 'The changes are insidious, and will not produce a noticeable effect for 15 to 20 years.', 'adj. 潜伏的， 隐伏的', '/ɪn\'sɪdiəs | ɪn\'sɪdɪəs/', 'insidious', 4);
INSERT INTO `words` VALUES (21054, 'a woman of great insight', 'n. 洞察，洞悉，见识', '/\'insait | \'ɪnsaɪt | \'ɪn\'saɪt/', 'insight', 4);
INSERT INTO `words` VALUES (21055, 'You realize that your problems are insignificant in comparison.', 'adj. 无关紧要的， 无意义的', '/ˌɪnsɪg\'nɪfɪkənt | ,ɪnsɪɡ\'nɪfɪkənt/', 'insignificant', 4);
INSERT INTO `words` VALUES (21056, 'an insipid pasta dish', 'adj. 无味的，枯燥乏味的；单调的', '/in\'sipid | ɪn\'sɪpɪd/', 'insipid', 4);
INSERT INTO `words` VALUES (21057, 'Stay for supper – I insist!', 'v. 坚持， 坚决认为； 一定要', '/ɪn\'sɪst/', 'insist', 4);
INSERT INTO `words` VALUES (21058, 'an insolent tone of voice', 'adj. 蛮横的，粗鲁的', '/\'insələnt | \'ɪns(ə)l(ə)nt | \'ɪnsələnt/', 'insolent', 4);
INSERT INTO `words` VALUES (21059, 'The company was later declared insolvent (= officially said to be insolvent ).', 'adj. 无偿债能力的', '/in\'sɔlvənt | ɪn\'sɒlv(ə)nt | ɪn\'sɑlvənt/', 'insolvent', 4);
INSERT INTO `words` VALUES (21060, 'I got out of the car to inspect the damage.', 'vt. 检查， 检阅', '/ɪn\'spekt | ɪn\'spɛkt/', 'inspect', 4);
INSERT INTO `words` VALUES (21061, 'An inspection was carried out at the school.', 'n. 检查；审视，检阅', '/in\'spekʃən | ɪn\'spekʃn | ɪn\'spɛkʃən/', 'inspection', 4);
INSERT INTO `words` VALUES (21062, 'The Malvern Hills have provided inspiration for many artists and musicians over the decades.', 'n. 灵感，鼓舞人心的人或事，好主意', '/,inspə\'reiʃən | ˌɪnspəˈreɪʃn | ˌɪnspəˈreʃən/', 'inspiration', 4);
INSERT INTO `words` VALUES (21063, 'We need someone who can inspire the team.', 'v. 激励，鼓励，灌注以创造力', '/in\'spaiə | ɪn\'spaɪə | ɪn\'spaɪɚ/', 'inspire', 4);
INSERT INTO `words` VALUES (21064, 'inspiring music', 'adj. 令人振奋的', '/in\'spaiəriŋ | ɪn\'spaɪərɪŋ/', 'inspiring', 4);
INSERT INTO `words` VALUES (21065, 'They’ve installed the new computer network at last.', 'v. 任命；安装，安置', '/in\'stɔ:l | ɪnˈstɔ:l | ɪn\'stɔl/', 'install', 4);
INSERT INTO `words` VALUES (21066, 'Now she can reduce the installment size that she can afford to pay, by extending the loan period.', 'n. 分期付款； 一集', '/ɪn\'stɔːlmənt | ɪn\'stɔlmənt/', 'installment', 4);
INSERT INTO `words` VALUES (21067, 'the second instalment of a loan', 'n. 分期连载，分期支付的款子', '/in\'stɔ:lmənt | ɪn\'stɔːlm(ə)nt | ɪn\'stɔlm(ə)nt/', 'instalment', 4);
INSERT INTO `words` VALUES (21068, 'So, the second method is almost always combined with the first, by checking the fields in instantaneous and then doing a batch validation before the form is submitted.', 'adv. 瞬间，霎时', '/,instən\'teinjəs | ,ɪnst(ə)n\'teɪnɪəs | ,ɪnstən\'tenɪəs/', 'instantaneous', 4);
INSERT INTO `words` VALUES (21069, 'The tough thing is trying to instil a winning attitude in the kids.', 'vt. 滴注； 逐渐灌输； 逐步培养', '/in\'stil | ɪn\'stɪl/', 'instil', 4);
INSERT INTO `words` VALUES (21070, 'Her instinct told her that something was wrong.', 'n. 本能', '/\'instiŋkt | \'ɪnstɪŋ(k)t | \'ɪnstɪŋkt/', 'instinct', 4);
INSERT INTO `words` VALUES (21071, 'The relationship between a parent and a child is instinctual and stems from basic human nature.', 'adj. 本能的', '/ɪn\'stɪŋktʃʊəl | ɪn\'stɪŋktʃuəl/', 'instinctual', 4);
INSERT INTO `words` VALUES (21072, 'research institutes', 'n. 研究所，学院; vt. 建立， 设立', '/\'ɪnstɪtjuːt | \'ɪnstɪtut/', 'institute', 4);
INSERT INTO `words` VALUES (21073, 'powerful institutions such as world banks', 'n. 协会； 机构； 制度； 习俗； 团体； 设立， 制定', '/ˌɪnstɪ\'tjuːʃn | ,ɪnstɪ\'tuʃən/', 'institution', 4);
INSERT INTO `words` VALUES (21074, 'Eva went straight to the hotel, as instructed (= as she had been told ).', 'vt. 教导； 指示， 命令', '/ɪn\'strʌkt/', 'instruct', 4);
INSERT INTO `words` VALUES (21075, 'surgical instruments', 'n. 仪器；器具；乐器', '/\'instrumənt, \'instrə-, -ment | \'ɪnstrʊm(ə)nt | \'ɪnstrəmənt/', 'instrument', 4);
INSERT INTO `words` VALUES (21076, 'He was instrumental in developing links with European organizations.', 'adj. 起作用的，有助于，乐器的', '/,instru\'mentəl, ,instrə- | ɪnstrʊ\'ment(ə)l | ,ɪnstrə\'mɛntl/', 'instrumental', 4);
INSERT INTO `words` VALUES (21077, 'Insufficient resources have been devoted to the health service.', 'adj. 不足的， 不够的', '/ˌɪnsə\'fɪʃnt | ,ɪnsə\'fɪʃnt/', 'insufficient', 4);
INSERT INTO `words` VALUES (21078, NULL, 'n. 岛国； 与外界隔绝的生活状况； 褊狭', '/,insju\'lærəti, \'insə- | ˌɪnsju\'lærəti/', 'insularity', 4);
INSERT INTO `words` VALUES (21079, 'an insulated attic', 'v. 使绝缘，使绝热，隔离', '/\'insjuleit, \'insə- | \'ɪnsjʊleɪt | ˈɪnsəˌleɪt ; ˈɪnsjʊˌleɪt/', 'insulate', 4);
INSERT INTO `words` VALUES (21080, 'Good insulation can save you money on heating bills.', 'n. 隔绝， 隔绝状态； 绝缘， 隔热， 隔音', '/ˌɪnsjʊ\'leɪʃn | ,ɪnsə\'leʃən/', 'insulation', 4);
INSERT INTO `words` VALUES (21081, 'Nobody insults my family and gets away with it!', 'v. 侮辱，凌辱; n. 侮辱的言词或行为', '/in\'sʌlt | ɪn\'sʌlt/', 'insult', 4);
INSERT INTO `words` VALUES (21082, 'Your father took out insurance to cover the mortgage.', 'n. 保险', '/in\'ʃuərəns | ɪn\'ʃʊər(ə)ns | ɪn\'ʃʊrəns/', 'insurance', 4);
INSERT INTO `words` VALUES (21083, 'Have you insured the contents of your home?', 'v. 给…保险', '/in\'ʃuə | ɪn\'ʃɔː; ɪn\'ʃʊə | ɪn\'ʃʊr/', 'insure', 4);
INSERT INTO `words` VALUES (21084, 'Only the medieval tower had remained intact.', 'adj. 未受损的，完整的', '/in\'tækt | ɪn\'tækt/', 'intact', 4);
INSERT INTO `words` VALUES (21085, 'a leak on the air intake to the carburettor', 'n. 吸入， 纳入； 进气口， 入口', '/\'ɪnteɪk | \'ɪn\'tek/', 'intake', 4);
INSERT INTO `words` VALUES (21086, 'Vegetables are an integral part of our diet.', 'adj. 构成整体所必需的，完整的', '/ˈɪntɪɡrəl | \'ɪntɪɡrəl/', 'integral', 4);
INSERT INTO `words` VALUES (21087, 'He didn\'t integrate successfully into the Italian way of life.', 'v. 使一体化，取消种族隔离', '/\'intiɡreit, \'intiɡrit, -ɡreit | \'ɪntɪgreɪt | \'ɪntɪɡret/', 'integrate', 4);
INSERT INTO `words` VALUES (21088, 'I have always regarded him as a man of integrity.', 'n. 诚实，正直', '/in\'teɡrəti | ɪn\'tegrɪtɪ | ɪn\'tɛɡrəti/', 'integrity', 4);
INSERT INTO `words` VALUES (21089, 'Do the emotions develop in parallel with the intellect?', 'n. 智力，才智', '/\'intəlekt | \'ɪntəlekt | \'ɪntəlɛkt/', 'intellect', 4);
INSERT INTO `words` VALUES (21090, 'a leading British intellectual', 'n. 知识分子; adj. 智力的，理智的，有理解力的', '/,intə\'lektjuəl, -tʃuəl | ,ɪntə\'lektʃʊəl; -tjʊəl | ,ɪntə\'lɛktʃuəl/', 'intellectual', 4);
INSERT INTO `words` VALUES (21091, 'To be good at the game, you need a reasonable level of intelligence.', 'n. 智力， 理解力； 情报', '/ɪn\'telɪdʒəns | ɪn\'tɛlɪdʒəns/', 'intelligence', 4);
INSERT INTO `words` VALUES (21092, 'a group of highly intelligent (= very intelligent )students', 'adj. 聪明的， 理智的', '/ɪn\'telɪdʒənt | ɪn\'tɛlɪdʒənt/', 'intelligent', 4);
INSERT INTO `words` VALUES (21093, 'His reply was barely intelligible.', 'adj. 可理解的，明白的', '/in\'telidʒəbl | ɪn\'telɪdʒɪb(ə)l | ɪn\'tɛlɪdʒəbl/', 'intelligible', 4);
INSERT INTO `words` VALUES (21094, 'Maybe he intends to leave her.', 'v. 想要， 打算', '/ɪn\'tend | ɪn\'tɛnd/', 'intend', 4);
INSERT INTO `words` VALUES (21095, 'Young people today are under intense pressure to succeed.', 'adj. 强烈的，剧烈的，热情的', '/in\'tens | ɪn\'tens | ɪn\'tɛns/', 'intense', 4);
INSERT INTO `words` VALUES (21096, 'In Junethe civil war intensified.', 'v. 加强; 加剧', '/in\'tensifai | ɪn\'tensɪfaɪ | ɪn\'tɛnsɪfaɪ/', 'intensify', 4);
INSERT INTO `words` VALUES (21097, 'The intensity of the hurricane was frightening.', 'n. 强烈， 剧烈； 强度', '/ɪn\'tensəti | ɪn\'tɛnsəti/', 'intensity', 4);
INSERT INTO `words` VALUES (21098, 'a one-week intensive course in English', 'adj. 加强的； 密集的', '/ɪn\'tensɪv | ɪn\'tɛnsɪv/', 'intensive', 4);
INSERT INTO `words` VALUES (21099, 'his intent gaze', 'adj. (目光)不能移的，集中的，专心的，坚决的', '/in\'tent | ɪn\'tent | ɪn\'tɛnt/', 'intent', 4);
INSERT INTO `words` VALUES (21100, 'They went into town with the intention of visiting the library.', 'n. 意图， 目的', '/ɪn\'tenʃn | ɪn\'tɛnʃən/', 'intention', 4);
INSERT INTO `words` VALUES (21101, 'While the other children interacted and played together, Ted ignored them.', 'v. 干预，干涉，触犯，妨碍', '/,intə\'rækt | ɪntər\'ækt | ,ɪntɚ\'ækt/', 'interact', 4);
INSERT INTO `words` VALUES (21102, 'countries with interdependent economies', 'adj. 互相依赖的， 互助的', '/ˌɪntədɪ\'pendənt | ,ɪntɚdɪ\'pɛndənt/', 'interdependent', 4);
INSERT INTO `words` VALUES (21103, 'I watched the first few episodes, but soon lost interest.', 'n. 兴趣；利息；利益; vt. 使感兴趣', '/\'ɪntrəst/', 'interest', 4);
INSERT INTO `words` VALUES (21104, '...the development of better user interfaces.', 'n. 界面； 接口； 接合点', '/\'ɪntəfeɪs | \'ɪntɚ\'fes/', 'interface', 4);
INSERT INTO `words` VALUES (21105, 'My daughter-in-law said that I was interfering, but I was only trying to help.', 'vi. 干涉， 干扰， 妨碍', '/ˌɪntə\'fɪə(r) | ,ɪntɚ\'fɪr/', 'interfere', 4);
INSERT INTO `words` VALUES (21106, 'an interim report', 'adj. 临时的，暂时的', '/\'intərim | \'ɪnt(ə)rɪm | \'ɪntərɪm/', 'interim', 4);
INSERT INTO `words` VALUES (21107, 'The interior walls are all painted white.', 'adj. 在内的；内部的，内地的，国内的; n. 内部', '/in\'tiəriə | ɪn\'tɪɜːrɪə | ɪn\'tɪrɪɚ/', 'interior', 4);
INSERT INTO `words` VALUES (21108, 'If you must use descendant selectors, prefer child selectors, which at least only require evaluation of one additional node, not all the intermediate nodes up to an ancestor.', 'a&n. 中间的；中间物', '/,intə\'mi:djət, -dieit | ,ɪntə\'miːdɪət | ,ɪntɚ\'midɪət/', 'intermediate', 4);
INSERT INTO `words` VALUES (21109, 'The weather forecast is for sun, with intermittent showers.', 'adj. 间歇的，断断续续的', '/ɪntə\'mɪt(ə)nt | ,ɪntɚ\'mɪtənt/', 'intermittent', 4);
INSERT INTO `words` VALUES (21110, 'Why did another universe intermix itself with the universe of which Earth is a part?', 'v. 混入， 混杂', '/ˌɪntə\'mɪks | ,ɪntɚ\'mɪks/', 'intermix', 4);
INSERT INTO `words` VALUES (21111, '...a medical intern.', 'vt. 拘禁，软禁[\'Intɜːn]; n. 实习生', '/ɪn\'tɜːn | \'ɪntɝn/', 'intern', 4);
INSERT INTO `words` VALUES (21112, 'We have no interest in interfering in the internal affairs of other countries.', 'adj. 内部的； 国内的', '/ɪn\'tɜːnl | ɪn\'tɝnl/', 'internal', 4);
INSERT INTO `words` VALUES (21113, '...a more genuinely internationalist view of U.S. participation in peacekeeping.', 'adj. 国际主义者的; n. 国际主义者', '/ˌɪntə\'næʃnəlɪst | ,ɪntɚ\'næʃnəlɪst/', 'internationalist', 4);
INSERT INTO `words` VALUES (21114, 'I\'ve been to see an internist, a nutritionist, and a chiropractor.', 'n. 内科医师', '/ɪn\'tɜːnɪst | ɪn\'tɝnɪst/', 'internist', 4);
INSERT INTO `words` VALUES (21115, '...an internship in surgery in New York.', 'n. 实习生身份； 实习医师', '/\'ɪntɜːnʃɪp | \'ɪntɝnʃɪp/', 'internship', 4);
INSERT INTO `words` VALUES (21116, '...the interplay of political, economic, social and cultural factors.', 'vi&n. 相互作用， 相互影响', '/\'ɪntəpleɪ | ,ɪntɚ\'plɛi/', 'interplay', 4);
INSERT INTO `words` VALUES (21117, 'They spoke good Spanish, and promised to interpret for me.', 'v. 解释，说明，认为的意思；口译', '/in\'tə:prit | ɪn\'tɜːprɪt | ɪn\'tɝprɪt/', 'interpret', 4);
INSERT INTO `words` VALUES (21118, 'One possible interpretation is that they want you to resign.', 'n. 口译； 解释， 诠释； 艺术处理', '/ɪnˌtɜːprɪ\'teɪʃn | ɪn\'tɝprɪ\'teʃən/', 'interpretation', 4);
INSERT INTO `words` VALUES (21119, '...the interrelationships between unemployment, crime, and imprisonment.', 'n. 相互关联， 相互影响', '/ˌɪntərɪ\'leɪʃnʃɪp | ,ɪntərɪ\'leʃnʃɪp/', 'interrelationship', 4);
INSERT INTO `words` VALUES (21120, 'The police interrogated the suspect for several hours.', 'v. 询问，审问', '/in\'terəuɡeit | ɪn\'terəgeɪt | ɪn\'tɛrəɡet/', 'interrogate', 4);
INSERT INTO `words` VALUES (21121, 'Will you stop interrupting me!', 'v. 中断， 中止； 阻碍； 打断， 打扰', '/ˌɪntə\'rʌpt | \'ɪntə\'rʌpt/', 'interrupt', 4);
INSERT INTO `words` VALUES (21122, 'We crossed at a busy intersection.', 'n. 交**点，十字街口', '/,intə\'sekʃən | ɪntə\'sekʃ(ə)n | ,ɪntɚ\'sɛkʃən/', 'intersection', 4);
INSERT INTO `words` VALUES (21123, 'He left the room, returning after a short interval with a message.', 'n. 间隔的时间，间隔；间歇', '/\'intəvəl | \'ɪntəv(ə)l | \'ɪntɚvl/', 'interval', 4);
INSERT INTO `words` VALUES (21124, 'The army will have to intervene to prevent further fighting.', 'v. 插入，介入，干涉，(时间)介于', '/,intə\'vi:n | ɪntə\'viːn | ,ɪntɚ\'vin/', 'intervene', 4);
INSERT INTO `words` VALUES (21125, 'government intervention to regulate prices', 'n. 干涉， 干预， 介入', '/ˌɪntə\'venʃn | ,ɪntɚ\'vɛnʃən/', 'intervention', 4);
INSERT INTO `words` VALUES (21126, 'a portfolio of work presented at interview', 'v&n. 接见， 会见； 采访； 面试', '/\'ɪntəvjuː | \'ɪntɚvju/', 'interview', 4);
INSERT INTO `words` VALUES (21127, 'This area is always tender to the touch if the intestines are not functioning properly.', 'n. 【解】 肠', '/ɪn\'testɪn | ɪn\'tɛstɪn/', 'intestine', 4);
INSERT INTO `words` VALUES (21128, 'an intimate friend of Picasso’s', 'adj. 亲密的，私人的，秘密的，精湛的; v. 暗示', '/英 [\'ɪntɪmət] 美 [ˈɪntəmɪt] | \'ɪntɪmət | ˈɪntəmɪt/', 'intimate', 4);
INSERT INTO `words` VALUES (21129, 'Attempts to intimidate her failed.', 'v. 恫吓，威胁', '/in\'timideit | ɪn\'tɪmɪdeɪt | ɪn\'tɪmɪdet/', 'intimidate', 4);
INSERT INTO `words` VALUES (21130, 'intricate patterns', 'adj. 复杂的，错综的', '/\'intrikət | \'ɪntrɪkət/', 'intricate', 4);
INSERT INTO `words` VALUES (21131, 'Other people’s houses always intrigued her.', 'v. 用诡计取得；激起的兴趣; n. 阴谋', '/in\'tri:ɡ, \'in- | ɪn\'triːg | \'ɪn\'triɡ/', 'intrigue', 4);
INSERT INTO `words` VALUES (21132, 'the intrinsic interest of the subject', 'adj. 固有的，内在的', '/in\'trinsik,-kəl | ɪn\'trɪnsɪk/', 'intrinsic', 4);
INSERT INTO `words` VALUES (21133, 'They want to introduce a system of identity cards.', 'vt. 介绍； 传入， 引进； 提出； 采用， 推行', '/ˌɪntrə\'djuːs | ˌɪntrə\'dus/', 'introduce', 4);
INSERT INTO `words` VALUES (21134, 'Pete, are you going to make the introductions?', 'n. 介绍； 传入， 引进； 导言， 绪论', '/ˌɪntrə\'dʌkʃn | ,ɪntrə\'dʌkʃən/', 'introduction', 4);
INSERT INTO `words` VALUES (21135, 'He had always had his moments of quiet introspection.', 'n. 内省， 反省', '/ˌɪntrə\'spekʃn | \'ɪntrə\'spɛkʃən/', 'introspection', 4);
INSERT INTO `words` VALUES (21136, 'I sympathize with the introvert as I would with the sickly, but both are missing a lot of life.', 'n. 性格内向的人', '/\'ɪntrəvɜːt | \'ɪntrəvɝt/', 'introvert', 4);
INSERT INTO `words` VALUES (21137, 'the unwelcome intrusion of the press', 'n. 闯入； 打搅； 侵扰', '/ɪn\'truːʒn | ɪn\'truʒn/', 'intrusion', 4);
INSERT INTO `words` VALUES (21138, 'feminine intuition', 'n. 直觉，直觉知识', '/,intju:\'iʃən | ɪntjʊ\'ɪʃ(ə)n | ,ɪntu\'ɪʃən/', 'intuition', 4);
INSERT INTO `words` VALUES (21139, 'The tidal wave inundated vast areas of cropland.', 'v. 淹没，泛滥，压倒', '/\'inʌndeit, in\'ʌn- | \'ɪnʌndeɪt | \'ɪnʌndet/', 'inundate', 4);
INSERT INTO `words` VALUES (21140, 'The Romans invaded Britain 2,000 years ago.', 'v. 侵略；侵犯，蜂拥而至', '/in\'veid | ɪn\'veɪd | ɪn\'ved/', 'invade', 4);
INSERT INTO `words` VALUES (21141, 'Invaders ransacked the town.', 'n. 入侵者', '/ɪn\'veɪdə(r) | ɪn\'vedɚ/', 'invader', 4);
INSERT INTO `words` VALUES (21142, 'Without the right date stamped on it, your ticket will be invalid.', 'adj. 无效的，作废的; n. 病人，病弱者; adj. 病弱的', '/\'invəli:d, -lid, ,invə\'li:d, \'in- | ˈɪnvəlɪd；ɪnˈvælɪd/', 'invalid', 4);
INSERT INTO `words` VALUES (21143, 'The internet is an invaluable source of information.', 'adj. 无价的, 无法估价的 \"', '/in\'væljuəbl | ɪn\'væljʊ(ə)b(ə)l | ɪn\'væljʊəbl/', 'invaluable', 4);
INSERT INTO `words` VALUES (21144, 'It invariably rains when I go there.', 'adv. 不变地，永恒地', '/in\'vɛəriəbli | ɪn\'veərɪəblɪ | ɪn\'vɛrɪəbli/', 'invariably', 4);
INSERT INTO `words` VALUES (21145, '...seven years after the Roman invasion of Britain.', 'n. 入侵， 侵略', '/ɪn\'veɪʒn | ɪn\'veʒn/', 'invasion', 4);
INSERT INTO `words` VALUES (21146, 'invasive bladder cancers', 'adj. 侵略的， 入侵的； 侵袭的， 扩散的； 切入的， 开刀的', '/ɪn\'veɪsɪv | ɪn\'vesɪv/', 'invasive', 4);
INSERT INTO `words` VALUES (21147, 'one of the most talented and inventive drummers in modern music', 'adj. 发明的， 创造的； 善于发明创造的', '/ɪn\'ventɪv | ɪn\'vɛntɪv/', 'inventive', 4);
INSERT INTO `words` VALUES (21148, '...one inventory of twelve sails for each yacht.', 'n. 详细目录，存货清单；存货盘存', '/\'invəntəri, -tɔ:ri | \'ɪnv(ə)nt(ə)rɪ | \'ɪnvəntɔri/', 'inventory', 4);
INSERT INTO `words` VALUES (21149, '...a scandalous inversion of the truth.', 'n. 倒置， 颠倒', '/ɪn\'vɜːʃn | ɪn\'vɝʃən/', 'inversion', 4);
INSERT INTO `words` VALUES (21150, 'Invert the cake onto a serving plate.', 'v. 倒转，上下倒置', '/in\'və:t, \'invə:t | ɪn\'vɜːt | \'ɪnvɝt/', 'invert', 4);
INSERT INTO `words` VALUES (21151, 'I’ve got a few thousand dollars I’m looking to invest.', 'v. 投资，购买；授予', '/in\'vest | ɪn\'vest | ɪn\'vɛst/', 'invest', 4);
INSERT INTO `words` VALUES (21152, 'The state police are investigating the incident.', 'v. 调查，调查研究', '/in\'vestiɡeit | ɪn\'vestɪgeɪt | ɪn\'vɛstɪɡet/', 'investigate', 4);
INSERT INTO `words` VALUES (21153, 'Different is, the exam in the life often does not have person invigilate.', 'v. 监考', '/in\'vidʒileit | ɪn\'vɪdʒɪleɪt | ɪn\'vɪdʒɪlet/', 'invigilate', 4);
INSERT INTO `words` VALUES (21154, 'The might of the army is \"invincible,\" according to state media but the refugees are rather cynical about the ill equipped force.', 'adj. 无敌的，不能征服的', '/in\'vinsəbl | ɪn\'vɪnsɪb(ə)l | ɪn\'vɪnsəbl/', 'invincible', 4);
INSERT INTO `words` VALUES (21155, 'The game had a single inviolable rule: obstacles were to be overcome, not circumvented.', 'adj. 不可侵犯的， 不容亵渎的， 不容破坏的', '/ɪn\'vaɪələbl/', 'inviolable', 4);
INSERT INTO `words` VALUES (21156, 'The house was surrounded by trees, and invisible from the road.', 'adj. 看不见的，无形的', '/in\'vizəbl | ɪn\'vɪzɪb(ə)l | ɪn\'vɪzəbl/', 'invisible', 4);
INSERT INTO `words` VALUES (21157, 'The agency invoices the client who then pays the full amount to the agency.', 'v. 开发票; n. 发票，装货清单', '/\'ɪnvɒɪs | \'ɪnvɔɪs/', 'invoice', 4);
INSERT INTO `words` VALUES (21158, 'a painting that invokes images of the Rocky Mountains', 'vt. 恳求， 祈求； 援用， 援引； 使用， 应用', '/ɪn\'vəuk | ɪn\'vok/', 'invoke', 4);
INSERT INTO `words` VALUES (21159, 'What will the job involve?', 'v. 使陷入，使卷入，包含', '/in\'vɔlv | ɪn\'vɒlv | ɪn\'vɑlv/', 'involve', 4);
INSERT INTO `words` VALUES (21160, 'Both of these particles can produce ion pairs .', 'n. 离子', '/\'aɪən/', 'ion', 4);
INSERT INTO `words` VALUES (21161, 'The iris of the eye is photographed from up to one meter away.', 'n. 虹； 虹膜', '/\'aɪərɪs | \'aɪrɪs/', 'iris', 4);
