INSERT INTO `words` VALUES (21163, 'Life is full of little ironies.', 'n. 反话，冷嘲，讽刺性的事件、情况等', '/\'aiərəni | \'aɪrənɪ | \'aɪrəni/', 'irony', 4);
INSERT INTO `words` VALUES (21164, 'an irrational fear of flying', 'adj. 不合理的，不合逻辑的，荒谬的; n. 无理数', '/ɪ\'ræʃənl/', 'irrational', 4);
INSERT INTO `words` VALUES (21165, 'Its complexity degree can be quantitatively evaluated using fractal dimension that can describe geometrical irregularity.', 'n. 不规则， 无规律', '/ɪˌregjə\'lærəti | ɪ\'rɛgjə\'lærəti/', 'irregularity', 4);
INSERT INTO `words` VALUES (21166, 'We’re focussing too much on irrelevant details.', 'adj. 不相关的； 离题的', '/ɪ\'reləvənt | ɪ\'rɛləvənt/', 'irrelevant', 4);
INSERT INTO `words` VALUES (21167, 'Men find Natalie irresistible.', 'adj. 无法抵抗的， 不能压制的； 不能自已的', '/ˌɪrɪ\'zɪstəbl | ,ɪrɪ\'zɪstəbl/', 'irresistible', 4);
INSERT INTO `words` VALUES (21168, 'The modularity system can then match you with what you need irrespective of which module provides it.', 'adj. 不考虑的，不顾的', '/,iri\'spektiv | ɪrɪ\'spektɪv | ,ɪrɪ\'spɛktɪv/', 'irrespective', 4);
INSERT INTO `words` VALUES (21169, 'Think about the situation carefully before you take an irrevocable step.', 'adj. 无法取消的， 不能改变的', '/ɪ\'revəkəbl | ɪ\'rɛvəkəbl/', 'irrevocable', 4);
