INSERT INTO `words` VALUES (21177, 'Abortion is a highly controversial issue.', 'n. 出版，问题，发行; v. 分发，出版，发行', '/\'iʃju:, \'isju: | \'ɪʃuː; \'ɪsjuː | \'ɪʃu/', 'issue', 4);
