INSERT INTO `words` VALUES (21180, 'an ivory chess set', 'n. 象牙；象牙制品; adj. 象牙色的', '/\'aivəri | \'aɪv(ə)rɪ | \'aɪvəri/', 'ivory', 4);
INSERT INTO `words` VALUES (21181, 'the broken bottle’s jagged edge', 'adj. 边缘不整齐的，参差不齐的', '/\'dʒægid | \'dʒægɪd | \'dʒæɡɪd/', 'jagged', 4);
