INSERT INTO `words` VALUES (21406, NULL, 'v. 把…制成麦芽； 变成麦芽; n. 麦芽；麦芽酒', '/mɔːlt | mɔlt/', 'malt', 4);
INSERT INTO `words` VALUES (21407, 'The hostages said they were hungry but had not been maltreated.', 'v. 虐待', '/mæl\'tri:t | mæl\'triːt | ,mæl\'trit/', 'maltreat', 4);
