INSERT INTO `words` VALUES (21420, 'He was one of those men who manipulated people.', 'v. 熟练地使用；操纵', '/mə\'nipjuleit | mə\'nɪpjʊleɪt | mə\'nɪpjulet/', 'manipulate', 4);
INSERT INTO `words` VALUES (21421, 'Before a child can learn a musical instrument he or she first needs to acquire the necessary manipulative skills.', 'adj. 操纵别人的； 老于世故的', '/mə\'nɪpjələtɪv | mə\'nɪpjəletɪv/', 'manipulative', 4);
