INSERT INTO `words` VALUES (21446, 'St. Stephen, the first Christian martyr', 'n. 烈士，殉难者; v. 杀害，折磨，牺牲', '/\'mɑ:tə | \'mɑːtə | \'mɑrtɚ/', 'martyr', 4);
