INSERT INTO `words` VALUES (21450, 'They’re nice curtains, but I’d prefer something a little more masculine.', 'adj. 男性的，阳性的', '/\'mæskjulin | \'mæskjʊlɪn | \'mæskjəlɪn/', 'masculine', 4);
