INSERT INTO `words` VALUES (21457, NULL, 'n. 精通， 熟练； 控制', '/\'mɑːstəri | \'mæstəri/', 'mastery', 4);
INSERT INTO `words` VALUES (21458, 'It’s our last match of the season.', 'n. 火柴；比赛；对手；婚姻;相称v相当,相配', '/mætʃ/', 'match', 4);
INSERT INTO `words` VALUES (21459, 'Rabbits can be mated as early as six months old.', 'v. 交配，配种; n. 配偶； 伙伴； 大副', '/meɪt | met/', 'mate', 4);
INSERT INTO `words` VALUES (21460, 'a society that places high importance on material rewards', 'adj. 物质的； 重要的; n. 材料；素材', '/mə\'tɪəriəl | mə\'tɪrɪəl/', 'material', 4);
