INSERT INTO `words` VALUES (21466, 'Beth shows a maturity way beyond her 16 years.', 'n. 成熟； 完善， 完备， 准备就绪； 到期', '/mə\'tʃuərəti | mə\'tʃʊrəti/', 'maturity', 4);
