INSERT INTO `words` VALUES (21476, 'Cook the sauce over a medium heat until it thickens. Meanwhile start boiling the water for the pasta.', 'adv. 与此同时', '/\'miːnwaɪl | \'minwaɪl/', 'meanwhile', 4);
