INSERT INTO `words` VALUES (21478, 'a garage mechanic', 'n. 机修工； [-s] 力学， 机械学', '/mə\'kænɪk/', 'mechanic', 4);
INSERT INTO `words` VALUES (21479, 'The flight has been cancelled due to mechanical failure .', 'adj. 机械的， 机械制造的； 呆板的； 习惯性的； 体力的', '/mə\'kænɪkl | mɪ\'kænɪkəl/', 'mechanical', 4);
INSERT INTO `words` VALUES (21480, 'the brake mechanism', 'n. 机械装置；机构；机制', '/\'mekənizəm | \'mek(ə)nɪz(ə)m | \'mɛkənɪzəm/', 'mechanism', 4);
INSERT INTO `words` VALUES (21481, 'She won a gold medal at the last Olympics.', 'n. 奖章；纪念章', '/\'medəl | \'med(ə)l | \'mɛdl/', 'medal', 4);
INSERT INTO `words` VALUES (21482, 'He accused the US of meddling in China’s internal affairs .', 'v. 干涉(预)', '/\'medl | \'med(ə)l | \'mɛdl/', 'meddle', 4);
INSERT INTO `words` VALUES (21483, 'The former president has agreed to mediate the peace talks.', 'v. 调停；居间促成', '/\'mi:dieit | \'miːdɪeɪt | \'midɪet/', 'mediate', 4);
INSERT INTO `words` VALUES (21484, 'medical research', 'adj. 医学的， 医疗的； 内科的', '/\'medɪkl | \'mɛdɪkl/', 'medical', 4);
INSERT INTO `words` VALUES (21485, 'When somebody comes for treatment I always ask them if they are on any medication.', 'n. 药； 药物', '/ˌmedɪ\'keɪʃn | \'mɛdɪ\'keʃən/', 'medication', 4);
INSERT INTO `words` VALUES (21486, 'These spices were first brought to Italy from the East in medieval times.', 'adj. 中古的，中世纪的', '/,medi\'i:vəl, ,mi:- | ˌmediˈi:vl | ,midɪ\'ivəl/', 'medieval', 4);
INSERT INTO `words` VALUES (21487, 'I thought the book was pretty mediocre.', 'adj. 平庸的，平常的', '/,mi:di\'əukə, \'mi:diəukə | ,miːdɪ\'əʊkə | ,midɪ\'okɚ/', 'mediocre', 4);
INSERT INTO `words` VALUES (21488, 'On the day her son began school, she meditated on the uncertainties of his future.', 'v. 深思，仔细思考', '/\'mediteit | \'medɪteɪt | \'mɛdɪtet/', 'meditate', 4);
INSERT INTO `words` VALUES (21489, 'a Mediterranean country', 'adj. 地中海的; n. 地中海', '/ˌmedɪtə\'reɪniən | ,mɛdətə\'renɪən/', 'Mediterranean', 4);
INSERT INTO `words` VALUES (21490, 'Advertising is a powerful medium.', 'n. 媒介；中庸间，适中; adj. 中等的，中庸', '/\'mi:diəm, -djəm | \'miːdɪəm | \'midɪəm/', 'medium', 4);
INSERT INTO `words` VALUES (21491, 'He was always so meek and mild .', 'adj. 温顺的，谦逊的', '/mi:k | miːk | mik/', 'meek', 4);
INSERT INTO `words` VALUES (21492, 'The proposed \"megacity\" will be 82,000 square miles --roughly the size of Utah.', 'n. 大城市', '/\'megəsɪti/', 'megacity', 4);
INSERT INTO `words` VALUES (21493, 'He sank into deep melancholy.', 'n. 忧郁，悲哀; adj. 忧郁的，令人伤感的', '/\'melənkəli | \'melənkəlɪ | \'mɛlənkɑli/', 'melancholy', 4);
INSERT INTO `words` VALUES (21494, 'Sunlight can refrain the growth of melatonin in the body.', 'n. 褪黑激素', '/ˌmelə\'təunɪn | ,mɛlə\'tonɪn/', 'melatonin', 4);
INSERT INTO `words` VALUES (21495, 'He spoke in a quiet melodious voice.', 'adj. 音调悦耳的，旋律的', '/mi\'ləudjəs | mɪ\'ləʊdɪəs | mə\'lodɪəs/', 'melodious', 4);
INSERT INTO `words` VALUES (21496, 'They played some lovely melodies.', 'n. 音律；歌曲', '/\'melədi | \'melədɪ | \'mɛlədi/', 'melody', 4);
INSERT INTO `words` VALUES (21497, 'It was warmer now, and the snow was beginning to melt.', 'v. 融化； 消散', '/melt | mɛlt/', 'melt', 4);
INSERT INTO `words` VALUES (21498, 'You should carry your membership card with you at all times.', 'n. 会员身份； 全体会员', '/\'membəʃɪp | \'mɛmbɚʃɪp/', 'membership', 4);
INSERT INTO `words` VALUES (21499, 'We want to make this a truly memorable day for the children.', 'adj. 容易记住的； 难忘的', '/\'memərəbl | \'mɛmərəbl/', 'memorable', 4);
INSERT INTO `words` VALUES (21500, '...a memorandum from the Department of Defense on its role.', 'n. 备忘录；便函', '/,memə\'rændəm | memə\'rændəm | ,mɛmə\'rændəm/', 'memorandum', 4);
INSERT INTO `words` VALUES (21501, 'This involved being shown a picture of eight animals and being asked to memorise the order in which the creatures appeared.', 'vt. 记住， 熟记', '/\'meməraɪz/', 'memorise', 4);
INSERT INTO `words` VALUES (21502, 'the growing menace of oil pollution at sea', 'n&vt. 危险，威胁', '/\'menəs | \'mɛnəs/', 'menace', 4);
INSERT INTO `words` VALUES (21503, 'a child’s mental development', 'adj. 心理的， 精神的； 智力的', '/\'mentl | \'mɛntl/', 'mental', 4);
INSERT INTO `words` VALUES (21504, 'a get-rich-quick mentality', 'n. 智力，心理状态', '/men\'tæləti | men\'tælɪtɪ | mɛn\'tæləti/', 'mentality', 4);
INSERT INTO `words` VALUES (21505, 'Was my name mentioned at all?', 'n&v. 提及， 说起', '/\'menʃn | \'mɛnʃən/', 'mention', 4);
INSERT INTO `words` VALUES (21506, 'Leon Sullivan was my mentor and my friend.', 'n. 导师； 顾问， 指导者', '/\'mɛn\'tɔr | \'mentɔː(r)/', 'mentor', 4);
INSERT INTO `words` VALUES (21507, 'mercantile law', 'adj. 商业的；贸易的', '/\'mə:kəntail, -til | \'mɜːk(ə)ntaɪl | \'mɝkəntɪl/', 'mercantile', 4);
INSERT INTO `words` VALUES (21508, 'She did it for purely mercenary reasons.', 'adj. 唯利是图的，为钱的', '/\'mə:sinəri | \'mɜːsɪn(ə)rɪ | \'mɝsənɛri/', 'mercenary', 4);
INSERT INTO `words` VALUES (21509, 'Company executives say revamped merchandising should help Macy\'s earnings to grow.', 'n. 销售规划', '/\'mɜːtʃəndaɪzɪŋ | \'mɝtʃəndaɪzɪŋ/', 'merchandising', 4);
INSERT INTO `words` VALUES (21510, 'He said that all metals were composed of mercury and sulphur in different proportions .', 'n. 水银', '/\'mɝkjəri | \'mɜːkjəri/', 'mercury', 4);
INSERT INTO `words` VALUES (21511, 'He showed no mercy to his enemies.', 'n. 怜悯；宽恕', '/\'mə:si | \'mɜːsɪ | \'mɝsi/', 'mercy', 4);
INSERT INTO `words` VALUES (21512, 'She lost the election by a mere 20 votes.', 'adj. 仅仅的； 纯粹的', '/mɪə(r) | mɪr/', 'mere', 4);
INSERT INTO `words` VALUES (21513, 'He’s merely a boy – you can’t expect him to understand.', 'adv. 仅仅， 只不过', '/\'mɪəli | \'mɪrli/', 'merely', 4);
INSERT INTO `words` VALUES (21514, 'The company plans to merge its subsidiaries in the US.', 'vt&vi. (企业)兼并，合并', '/mə:dʒ | mɜːdʒ | mɝdʒ/', 'merge', 4);
INSERT INTO `words` VALUES (21515, 'The merit of the report is its realistic assessment of the changes required.', 'n. 价值，优点，功绩; v. 值得，应收', '/\'merit | \'merɪt | \'mɛrɪt/', 'merit', 4);
INSERT INTO `words` VALUES (21516, 'The windows were covered in wire mesh to keep out flies.', 'n. 网，筛孔', '/meʃ | mɛʃ/', 'mesh', 4);
INSERT INTO `words` VALUES (21517, 'What a mess!', 'n. 混乱，污垢，杂乱; vt&v. 瞎忙；草率处理', '/mes | mɛs/', 'mess', 4);
INSERT INTO `words` VALUES (21518, 'This drug speeds up your metabolism.', 'n. 新陈代谢', '/mi\'tæbəlizəm, me- | mɪ\'tæbəlɪz(ə)m | mɛ\'tæbəlɪzəm/', 'metabolism', 4);
INSERT INTO `words` VALUES (21519, 'The key turned in the lock with a loud metallic click.', 'adj. 金属的', '/mi\'tælik, me- | mɪ\'tælɪk | mə\'tælɪk/', 'metallic', 4);
INSERT INTO `words` VALUES (21520, 'She uses some wonderful images and metaphors in her writing.', 'n. 隐喻，暗喻', '/\'metəfə | \'metəfə; -fɔː | \'mɛtəfɚ/', 'metaphor', 4);
INSERT INTO `words` VALUES (21521, 'The word has a metaphorical as well as a literal meaning.', 'adj. 隐喻的', '/ˌmetə\'fɒrɪkl | \'mɛtə\'fɔrɪkl/', 'metaphorical', 4);
INSERT INTO `words` VALUES (21522, 'meteoric iron', 'adj. 流星的，转瞬即逝的，突然的', '/,mi:ti\'ɔrik | ,miːtɪ\'ɒrɪk | ,mitɪ\'ɔrɪk/', 'meteoric', 4);
INSERT INTO `words` VALUES (21523, 'This is a book about meteorology.', 'n. 气象学', '/,mi:tiə\'rɔlədʒi | ,miːtɪə\'rɒlədʒɪ | ,mitɪə\'rɑlədʒi/', 'meteorology', 4);
INSERT INTO `words` VALUES (21524, 'Methane is one of the principal gases contributing to the greenhouse effect.', 'n. 甲烷， 沼气', '/\'miːθeɪn | \'mɛθen/', 'methane', 4);
INSERT INTO `words` VALUES (21525, 'He was so meticulous about everything.', 'adj. 谨小慎微的；过细的', '/mi\'tikjuləs, mə- | mə\'tɪkjələs/', 'meticulous', 4);
INSERT INTO `words` VALUES (21526, 'a metric tonne', 'adj. 十进制的，公制的', '/\'metrik | \'metrɪk | \'mɛtrɪk/', 'metric', 4);
INSERT INTO `words` VALUES (21527, 'the Paris Metro', 'n. 地下铁路', '/\'metrəu | \'mɛtro/', 'metro', 4);
INSERT INTO `words` VALUES (21528, 'a metropolitan area of South Australia', 'adj. 大城市的，大都市的', '/,metrə\'pɔlitən | metrə\'pɒlɪt(ə)n | ,mɛtrə\'pɑlɪtən/', 'metropolitan', 4);
INSERT INTO `words` VALUES (21529, '...a type of bacteria that include the microbes responsible for tuberculosis and leprosy.', 'n. 微生物', '/\'maikrəub | \'maɪkrəʊb | \'maɪkrob/', 'microbe', 4);
INSERT INTO `words` VALUES (21530, '...a professor of microbiology and immunology.', 'n. 微生物学', '/ˌmaɪkrəubaɪ\'ɒlədʒi | ,maɪkrobaɪ\'ɑlədʒi/', 'microbiology', 4);
INSERT INTO `words` VALUES (21531, 'Kitchell says the city was a microcosm of all American culture during the \'60s.', 'n. 微观世界；缩影', '/\'maikrəukɔzəm | \'maɪkrə(ʊ)kɒz(ə)m | \'maɪkrokɑzəm/', 'microcosm', 4);
INSERT INTO `words` VALUES (21532, 'It was to harbor drawers brimming with reference books, microfilm and bibliographic cards.', 'n. 微缩胶片', '/\'maikrəufilm | \'maɪkrə(ʊ)fɪlm | \'maɪkrofɪlm/', 'microfilm', 4);
INSERT INTO `words` VALUES (21533, 'The invention of the microprocessor had made it possible for ordinary people like you and me to actually own a computer.', 'n. 微处理器', '/ˌmaɪkrəu\'prəusesə(r) | ,maɪkro\'prosɛsɚ/', 'microprocessor', 4);
INSERT INTO `words` VALUES (21534, 'Can I borrow your microscope?', 'n. 显微镜', '/\'maɪkrəskəup | \'maɪkrəskop/', 'microscope', 4);
INSERT INTO `words` VALUES (21535, 'I fear we have an enemy in our midst.', 'n. 中间', '/mɪdst/', 'midst', 4);
INSERT INTO `words` VALUES (21536, 'two individuals who took on the might of the English legal system', 'n. 力量，强权，势力', '/mait | maɪt/', 'might', 4);
INSERT INTO `words` VALUES (21537, 'the mighty Mississippi river', 'adj. 强大的，强有力的，巨大的，浩大的', '/\'maiti | \'maɪtɪ | \'maɪti/', 'mighty', 4);
INSERT INTO `words` VALUES (21538, 'The government divides asylum seekers into economic migrants and genuine refugees.', 'n. 移居者， 移民； 迁移动物， 候鸟', '/\'maɪgrənt | \'maɪɡrənt/', 'migrant', 4);
INSERT INTO `words` VALUES (21539, 'People migrate to cities like Jakarta in search of work.', 'v. 迁移；移居', '/mai\'ɡreit, \'maiɡ- | maɪ\'greɪt; \'maɪgreɪt | \'maɪɡret/', 'migrate', 4);
INSERT INTO `words` VALUES (21540, NULL, 'n. 迁徙， 移居， 移民', '/maɪ\'greɪʃn | maɪ\'ɡreʃən/', 'migration', 4);
INSERT INTO `words` VALUES (21541, 'migratory birds', 'adj. 迁徙的， 移居的； 流动的， 游牧的', '/\'maɪgrətri | \'maɪɡrətɔri/', 'migratory', 4);
INSERT INTO `words` VALUES (21542, 'We had an exceptionally mild winter last year.', 'adj. 温柔的； 温和的； 轻微的', '/maɪld/', 'mild', 4);
INSERT INTO `words` VALUES (21543, 'The room smelled of mildew.', 'n&v. 霉，发霉', '/\'mildju:, -du: | \'mɪldjuː | \'mɪldu/', 'mildew', 4);
INSERT INTO `words` VALUES (21544, 'He said the launch of the party represented a milestone in Zambian history.', 'n. 里程碑； 转折点', '/\'maɪlstəun | \'maɪlston/', 'milestone', 4);
INSERT INTO `words` VALUES (21545, 'militant political activists', 'adj. 好斗的', '/\'mɪlɪt(ə)nt | \'mɪlɪtənt/', 'militant', 4);
INSERT INTO `words` VALUES (21546, 'a military helicopter', 'adj. 军事的; n. [the ～] 军队', '/\'mɪlətri | \'mɪlətɛri/', 'military', 4);
INSERT INTO `words` VALUES (21547, 'people who have inhabited this land for millennia', 'n. 一千年，千禧年；太平盛世', '/mi\'leniəm | mɪˈlɛnɪəm | məˈlɛniəm/', 'millennium', 4);
INSERT INTO `words` VALUES (21548, 'The children learn through role-play, dance and mime.', 'v. 模拟，模仿; n. 哑剧表演； 哑剧演员', '/maɪm/', 'mime', 4);
INSERT INTO `words` VALUES (21549, NULL, 'adj. 假装的，模仿的，草拟的', '/\'mimik | \'mɪmɪk/', 'mimic', 4);
INSERT INTO `words` VALUES (21550, 'It is impossible to understand the complex nature of the human mind .', 'n. 想法', '/maind | maɪnd/', 'mind', 4);
INSERT INTO `words` VALUES (21551, 'The area is very rich in minerals .', 'n. 矿物， 矿石', '/\'mɪnərəl/', 'mineral', 4);
INSERT INTO `words` VALUES (21552, 'Add the mint and allow the flavours to mingle.', 'v. 使混合；交往', '/\'miŋɡl | \'mɪŋg(ə)l | \'mɪŋɡl/', 'mingle', 4);
INSERT INTO `words` VALUES (21553, 'The storm caused only minimal damage.', 'adj. 最小的；最低限度的', '/\'miniməl | \'mɪnɪm(ə)l | \'mɪnɪməl/', 'minimal', 4);
INSERT INTO `words` VALUES (21554, NULL, 'vt. 使减到最低限度； 最小化', '/\'mɪnɪmaɪz | \'minimaiz/', 'minimise', 4);
INSERT INTO `words` VALUES (21555, 'At a minimum, we must recruit two new teachers.', '\"n. [pl~s,-ma]最少量；最低限度\"', '/\'miniməm | \'mɪnɪməm/', 'minimum', 4);
INSERT INTO `words` VALUES (21556, 'a senior Cabinet minister', 'v. 照顾，给予帮助', '/\'ministə | \'mɪnɪstə | \'mɪnɪstɚ/', 'minister', 4);
INSERT INTO `words` VALUES (21557, '...the Ministry of Justice.', 'n. 部', '/\'mɪnɪstri/', 'ministry', 4);
INSERT INTO `words` VALUES (21558, 'Gaelic is still spoken in Ireland by a tiny minority.', 'n. 未成年；少数；少数民族', '/mai\'nɔrəti, mi- | maɪ\'nɒrɪtɪ; mɪ- | maɪ\'nɔrəti/', 'minority', 4);
INSERT INTO `words` VALUES (21559, 'new potatoes sprinkled with chopped mint', 'n. 薄荷；造币厂', '/mɪnt/', 'mint', 4);
INSERT INTO `words` VALUES (21560, '17 minus 5 is 12 (17–5=12).', 'a&n&prep. 负的，负号；减', '/\'mainəs | \'maɪnəs/', 'minus', 4);
INSERT INTO `words` VALUES (21561, 'It takes me ten minutes to walk to work.', 'n. 分，备忘录; adj. 微小的，细致的', '/\'mɪnɪt/', 'minute', 4);
INSERT INTO `words` VALUES (21562, 'It’s a miracle you weren’t killed!', 'n. 奇迹', '/\'mirəkl | \'mɪrək(ə)l | \'mɪrəkl/', 'miracle', 4);
INSERT INTO `words` VALUES (21563, 'Perhaps we are just chasing a mirage.', 'n. 海市蜃楼，幻想', '/\'mirɑ:ʒ, mi\'rɑ:ʒ | \'mɪrɑːʒ; mɪ\'rɑːʒ | mə\'rɑʒ/', 'mirage', 4);
INSERT INTO `words` VALUES (21564, 'The wheels got stuck in the mire.', 'n. 泥泞，沼泽地', '/\'maiə | maɪə | \'maɪɚ/', 'mire', 4);
INSERT INTO `words` VALUES (21565, 'He claimed the finance manager had misappropriated company funds.', 'v. 滥用，误用', '/,misə\'prəuprieit | mɪsə\'prəʊprɪeɪt | ,mɪsə\'proprɪet/', 'misappropriate', 4);
INSERT INTO `words` VALUES (21566, 'She had two miscarriages before she had her first child.', 'n. 误判，误罚；流产；失败', '/,mis\'kæridʒ | mɪs\'kærɪdʒ; \'mɪskærɪdʒ | \'mɪskærɪdʒ/', 'miscarriage', 4);
INSERT INTO `words` VALUES (21567, 'a miscellaneous assortment of books', 'adj. 各种各样的； 混杂的', '/ˌmɪsə\'leɪniəs | \'mɪsə\'lenɪəs/', 'miscellaneous', 4);
INSERT INTO `words` VALUES (21568, 'If by some mischance the government get elected again, I think taxes will rise.', 'n. 不幸，灾难', '/mis\'tʃɑ:ns, -\'tʃæns | mɪs\'tʃɑːns | ,mɪs\'tʃæns/', 'mischance', 4);
INSERT INTO `words` VALUES (21569, 'If you try to lift that box, you’ll do yourself a mischief.', 'n. 伤害，损害', '/\'mistʃif | \'mɪstʃɪf/', 'mischief', 4);
INSERT INTO `words` VALUES (21570, 'Since namely namely misconceive, that explanation clear nice.', 'vt&vi. 误解', '/,miskən\'si:v | mɪskən\'siːv | ,mɪskən\'siv/', 'misconceive', 4);
INSERT INTO `words` VALUES (21571, 'It is a misconception that Peggy was fabulously wealthy.', 'n. 误解， 错误想法', '/ˌmɪskən\'sepʃn | \'mɪskən\'sɛpʃən/', 'misconception', 4);
INSERT INTO `words` VALUES (21572, 'He now repents of his past misdeeds.', 'n. 不端行为', '/,mis\'di:d, \'mis- | mɪs\'diːd | ,mɪs\'did/', 'misdeed', 4);
INSERT INTO `words` VALUES (21573, 'They endured hours of backbreaking work in miserable conditions.', 'adj. 悲惨的，使人难受的', '/\'mizərəbl | \'mɪz(ə)rəb(ə)l | \'mɪzrəbl/', 'miserable', 4);
INSERT INTO `words` VALUES (21574, 'She looked away so that Tom wouldn’t see her misery.', 'n. 悲惨，痛苦的事', '/\'mizəri | \'mɪz(ə)rɪ | \'mɪzəri/', 'misery', 4);
INSERT INTO `words` VALUES (21575, 'It seems the banks always profit from farmers’ misfortunes.', 'n. 不幸，灾祸', '/mis\'fɔ:tʃən | mɪs\'fɔːtʃuːn; -tʃ(ə)n | \'mɪs\'fɔrtʃən/', 'misfortune', 4);
INSERT INTO `words` VALUES (21576, 'Opponents of nuclear energy have deep misgivings about its safety.', 'n. 怀疑，疑虑', '/,mis\'ɡiviŋ | mɪs\'gɪvɪŋ/', 'misgiving', 4);
INSERT INTO `words` VALUES (21577, 'His parents still clung to the misguided belief that his common sense would keep him out of serious trouble.', 'adj. 误入歧途的', '/,mis\'ɡaidid | ,mɪs\'ɡaɪdɪd/', 'misguided', 4);
INSERT INTO `words` VALUES (21578, 'The prime minister admitted that the crisis had been mishandled.', 'vt. 粗暴地对待； 错误地处理， 胡乱操作', '/ˌmɪs\'hændl | \'mɪs\'hændl/', 'mishandle', 4);
INSERT INTO `words` VALUES (21579, 'I had a slight mishap with one of the glasses.', 'n. 不幸的事，不幸；灾祸', '/\'mishæp, ,mis\'h- | \'mɪshæp/', 'mishap', 4);
INSERT INTO `words` VALUES (21580, 'The government misjudged the mood of the electorate.', 'vt. 判断错误', '/ˌmɪs\'dʒʌdʒ | ,mɪs\'dʒʌdʒ/', 'misjudge', 4);
INSERT INTO `words` VALUES (21581, 'These statistics grossly misrepresent the reality.', 'v. 误传，歪曲，曲解', '/\'mis,repri\'zent | ,mɪsreprɪ\'zent | ,mɪs,rɛprɪ\'zɛnt/', 'misrepresent', 4);
INSERT INTO `words` VALUES (21582, 'a nuclear missile', 'n. 发射物；导弹', '/\'misail, -səl | \'mɪsaɪl | \'mɪsl/', 'missile', 4);
INSERT INTO `words` VALUES (21583, 'He was sent on over 200 missions before being killed in action.', 'n. 代表团；使命', '/\'miʃən | \'mɪʃ(ə)n | \'mɪʃən/', 'mission', 4);
INSERT INTO `words` VALUES (21584, 'We could just see the outline of the house through the mist.', 'n. 薄雾；朦胧', '/mist | mɪst/', 'mist', 4);
