INSERT INTO `words` VALUES (21691, 'students with a negative attitude to school', 'adj. 否定的；消极的；负的；阴性的；底片的', '/\'neɡətiv | \'negətɪv | \'nɛɡətɪv/', 'negative', 4);
INSERT INTO `words` VALUES (21692, 'Many of these ideas have been neglected by modern historians.', 'v. 忽视，搁置未做; n. 忽略，疏忽', '/ni\'ɡlekt | nɪ\'glekt | nɪ\'glɛkt/', 'neglect', 4);
INSERT INTO `words` VALUES (21693, 'negligence in carrying out safety procedures', 'n. 疏忽，粗心大意', '/\'neɡlidʒəns | \'neglɪdʒ(ə)ns | \'nɛɡlɪdʒəns/', 'negligence', 4);
INSERT INTO `words` VALUES (21694, 'The damage done to his property was negligible.', 'adj. 微不足道的，可以忽视的', '/\'neɡlidʒəbl | \'neglɪdʒɪb(ə)l | \'nɛɡlɪdʒəbl/', 'negligible', 4);
INSERT INTO `words` VALUES (21695, 'Part-time barman required. Hours and salary negotiable.', 'adj. 可谈判的，可(通行)商议的；可兑换现金的', '/ni\'ɡəuʃiəbl | nɪ\'gəʊʃəb(ə)l; -ʃɪə- | nɪ\'ɡoʃɪəbl/', 'negotiable', 4);
INSERT INTO `words` VALUES (21696, 'His first aim is to get the warring parties back to the negotiating table (= discussing something ).', 'v. 洽谈， 协商； 商定， 达成； 顺利通过', '/nɪ\'gəuʃieɪt | nɪ\'ɡoʃɪet/', 'negotiate', 4);
INSERT INTO `words` VALUES (21697, 'a palace built in a neoclassical style', 'adj. 新古典主义的', '/ˌniːəu\'klæsɪkl | ,nio\'klæsɪkl/', 'neoclassical', 4);
INSERT INTO `words` VALUES (21698, 'a condition which affects the nerves in the back', 'n. 神经； 勇敢', '/nɜːv | nɝv/', 'nerve', 4);
INSERT INTO `words` VALUES (21699, 'He was anxious to the point of neurosis.', 'n. 神经官能病，精神性神经病', '/njuə\'rəusis | ,njʊə\'rəʊsɪs | nʊ\'rosɪs/', 'neurosis', 4);
INSERT INTO `words` VALUES (21700, 'He seemed a neurotic, self-obsessed man.', 'adj. 神经病的，神经过敏的; n. 神经过敏者', '/njuə\'rɔtik | njʊə\'rɒtɪk | nʊ\'rɑtɪk/', 'neurotic', 4);
INSERT INTO `words` VALUES (21701, 'I always tried to remain neutral when they started arguing.', 'adj. 中立的； 无明显特性的', '/\'njuːtrəl | \'nʊtrəl/', 'neutral', 4);
INSERT INTO `words` VALUES (21702, 'a medicine that neutralizes the acid in the stomach', 'v. 使中立；使无效', '/\'nju:trəlaiz | \'nʊtrə\'laɪz/', 'neutralize', 4);
INSERT INTO `words` VALUES (21703, 'What you said was true. It was, nevertheless, a little unkind.', 'adv. 然而，不过，仍然', '/,nevəðə\'les | nevəðə\'les | ,nɛvɚðə\'lɛs/', 'nevertheless', 4);
INSERT INTO `words` VALUES (21704, 'The society publishes a newsletter twice a year.', 'n. 时事通讯， 业务通讯', '/\'njuːzletə(r) | \'nuzlɛtɚ/', 'newsletter', 4);
INSERT INTO `words` VALUES (21705, 'He nibbled the biscuit cautiously.', 'v. 啃，一点一点咬', '/\'nibl | \'nɪb(ə)l | \'nɪbl/', 'nibble', 4);
INSERT INTO `words` VALUES (21706, 'social niceties', 'n. 细微的区别及差异', '/\'naisiti | \'naɪsɪtɪ | \'naɪsəti/', 'nicety', 4);
INSERT INTO `words` VALUES (21707, '...a large glass jar filled with pennies, nickels, dimes, and quarters.', 'n. [化]镍；美国五分镍币', '/\'nikəl | \'nɪk(ə)l | \'nɪkl/', 'nickel', 4);
INSERT INTO `words` VALUES (21708, 'Something’s been niggling her all day.', 'v. 拘泥小节； 挑剔， 吹毛求疵； 为小事操心； 不断地烦扰', '/\'nɪgl | \'nɪɡl/', 'niggle', 4);
INSERT INTO `words` VALUES (21709, 'All the victims still suffered nightmares.', 'n. 恶梦；可怕的经历', '/\'naitmεə | \'naɪtmeə | \'naɪt\'mɛr/', 'nightmare', 4);
INSERT INTO `words` VALUES (21710, 'The new machine reduced labour costs to almost nil.', 'n. 无；零', '/nil | nɪl/', 'nil', 4);
INSERT INTO `words` VALUES (21711, 'Well, we know nitrogen has what?', 'n. [化]氮', '/\'naitrədʒən | \'naɪtrədʒ(ə)n | \'naɪtrədʒən/', 'nitrogen', 4);
INSERT INTO `words` VALUES (21712, 'the nobility of his intentions', 'n. 高贵，高尚；贵族', '/nəu\'biləti | nə(ʊ)\'bɪlɪtɪ | no\'bɪləti/', 'nobility', 4);
INSERT INTO `words` VALUES (21713, 'Hamsters are nocturnal creatures.', 'adj. 夜晚的； 夜晚发生的； 夜晚活动的', '/nɒk\'tɜːnl | nɑk\'tɝnl/', 'nocturnal', 4);
INSERT INTO `words` VALUES (21714, 'A nominal charge is made for use of the tennis courts.', 'adj. 名义上的，有名无实的；极微的；象征性的', '/\'nɔminəl | \'nɒmɪn(ə)l | \'nɑmɪnl/', 'nominal', 4);
INSERT INTO `words` VALUES (21715, 'This week one of them will be nominated by the Democratic Party for the presidency of the United States.', 'v. 提名', '/\'nɔmineit, \'nɔminət, -neit | \'nɒmɪneɪt | \'nɑmɪnet/', 'nominate', 4);
INSERT INTO `words` VALUES (21716, 'the Democratic Party presidential nominee', 'n. 被提名者，被任命者', '/,nɔmi\'ni: | nɒmɪ\'niː | ,nɑmɪ\'ni/', 'nominee', 4);
INSERT INTO `words` VALUES (21717, 'the Nordic countries', 'adj. 北欧人的； 北欧国家的', '/\'nɔːdɪk | \'nɔ:dik/', 'Nordic', 4);
INSERT INTO `words` VALUES (21718, 'Joyce’s style of writing was a striking departure from the literary norm.', 'n. 标准，规范', '/nɔːm | nɔrm/', 'norm', 4);
INSERT INTO `words` VALUES (21719, 'A normal working week is 40 hours.', 'adj. 正常的， 平常的； 标准的， 规范的， 正规的', '/\'nɔːml | \'nɔrml/', 'normal', 4);
INSERT INTO `words` VALUES (21720, 'He looked back on his university days with a certain amount of nostalgia.', 'n. 怀乡病，留恋过去，怀旧', '/nɔ\'stældʒiə, nə- | nɒ\'stældʒə | nə\'stældʒə/', 'nostalgia', 4);
INSERT INTO `words` VALUES (21721, 'If there are any notable inconsistencies or discrepancies, think through how you are going to explain the situation.', 'n. 名人；显要人物; adj. 显著的；著名的', '/\'nəutəbl | \'nəʊtəb(ə)l | \'notəbl/', 'notable', 4);
INSERT INTO `words` VALUES (21722, 'Want to be an assistant judge or notary.', 'n. 公证人，公证员', '/\'nəutəri | \'nəʊt(ə)rɪ | \'notəri/', 'notary', 4);
INSERT INTO `words` VALUES (21723, 'Musical notation was conceived for the C major scale and each line and space represents a note in this scale.', 'n. (数学、音乐)的一套符号', '/nəu\'teiʃən | nəʊ\'teɪʃ(ə)n | no\'teʃən/', 'notation', 4);
INSERT INTO `words` VALUES (21724, 'Cut a notch near one end of the stick.', 'n. (V字形)槽口，缺口', '/nɔtʃ | nɒtʃ | nɑtʃ/', 'notch', 4);
INSERT INTO `words` VALUES (21725, 'I owe him nothing.', 'n&ad. 没有什么；毫不', '/\'nʌθiŋ | \'nʌθɪŋ/', 'nothing', 4);
INSERT INTO `words` VALUES (21726, 'Why don\'t you go and put it up on the college notice board?', '[管理] 布告牌；警告牌', NULL, 'notice board', 4);
INSERT INTO `words` VALUES (21727, 'Alcohol has a noticeable effect on the body.', 'adj. 显而易见的； 明显的', '/\'nəutɪsəbl | \'notɪsəbl/', 'noticeable', 4);
INSERT INTO `words` VALUES (21728, 'The skipper notified the coastguard of the tragedy.', 'v. 通知，报告', '/\'nəutifai | \'nəʊtɪfaɪ | \'notə\'fai/', 'notify', 4);
INSERT INTO `words` VALUES (21729, 'She had no notion what he meant.', 'n. 概念，观念', '/\'nəuʃən | \'nəʊʃ(ə)n | \'noʃən/', 'notion', 4);
INSERT INTO `words` VALUES (21730, 'He achieved notoriety as chief counsel to President Nixon in the Watergate break-in.', 'n. 声名狼藉， 臭名昭著', '/ˌnəutə\'raɪəti | ,notə\'raɪəti/', 'notoriety', 4);
INSERT INTO `words` VALUES (21731, 'a notorious computer hacker', 'adj. 自名昭著的，声名狼藉的', '/nəu\'tɔ:riəs | nə(ʊ)\'tɔːrɪəs | no\'tɔrɪəs/', 'notorious', 4);
INSERT INTO `words` VALUES (21732, 'We need to nourish our hopes and dreams.', 'v. 养育，怀有(希望)', '/\'nʌriʃ, \'nə:- | \'nʌrɪʃ | \'nɜrɪʃ/', 'nourish', 4);
INSERT INTO `words` VALUES (21733, 'His favorite fruits and vegetables as well as 55 lb. of bamboo will be on board for nourishment.', 'n. 食物', '/\'nʌriʃmənt, \'nə:- | \'nʌrɪʃm(ə)nt | \'nɝɪʃmənt/', 'nourishment', 4);
INSERT INTO `words` VALUES (21734, 'Protesters found a novel way of demonstrating against steeply rising oil prices.', 'adj. 新奇的; n. 小说', '/\'nɔvəl | \'nɒv(ə)l | ˈnɑːvl/', 'novel', 4);
INSERT INTO `words` VALUES (21735, 'Many toys have no attraction beyond their novelty value.', 'n. 新颖；新奇；新奇的事物', '/\'nɔvəlti | \'nɒv(ə)ltɪ | \'nɑvlti/', 'novelty', 4);
INSERT INTO `words` VALUES (21736, 'The computer course is ideal for novices.', 'n. 新手; 初学者', '/\'nɔvis | \'nɒvɪs | \'nɑvɪs/', 'novice', 4);
INSERT INTO `words` VALUES (21737, 'Nowhere is drug abuse more of a problem than in the US.', 'adv. 什么地方都没有', '/\'nəuhwεə | \'nəʊhweə | \'no\'wɛr/', 'nowhere', 4);
INSERT INTO `words` VALUES (21738, 'noxious fumes', 'adj. 有害的，有毒的', '/\'nɔkʃəs | \'nɒkʃəs | \'nɑkʃəs/', 'noxious', 4);
INSERT INTO `words` VALUES (21739, 'He was aware of every nuance in her voice.', 'n. (意义、意见、颜色)细微差别', '/\'nju:ɑ:ns, nju:\'ɑ:ns | \'njuːɑːns/', 'nuance', 4);
INSERT INTO `words` VALUES (21740, 'France’s reliance on nuclear energy', 'adj. 核能的， 原子能的', '/\'njuːklɪə(r) | \'nuklɪɚ/', 'nuclear', 4);
INSERT INTO `words` VALUES (21741, 'Neutrons and protons are bound together in the nucleus of an atom.', 'n. 核心；原子核', '/\'nju:kliəs | \'njuːklɪəs | \'nuklɪəs/', 'nucleus', 4);
INSERT INTO `words` VALUES (21742, 'He could be a bit of a nuisance when he was drunk.', 'n. 麻烦事，讨厌的人', '/\'nju:səns | \'njuːs(ə)ns | \'nusns/', 'nuisance', 4);
INSERT INTO `words` VALUES (21743, 'The contract was declared null and void.', 'adj. 无效的，无意义的', '/nʌl/', 'null', 4);
INSERT INTO `words` VALUES (21744, 'Recent inflation could nullify the economic growth of the last several years.', 'v. 使无效，废弃，取消', '/\'nʌlifai | \'nʌlɪfaɪ | \'nʌlɪ\'fai/', 'nullify', 4);
INSERT INTO `words` VALUES (21745, 'My fingers were so numb I could hardly write.', 'adj. 麻木的，失去知觉的', '/nʌm/', 'numb', 4);
INSERT INTO `words` VALUES (21746, 'Where children respect a parent and know that he or she demands good behavior in school, even mediocre or loutish teachers can pull off the trick④of producing modestly literate and numerate children.', 'adj. 数学基础好的', '/\'nju:məreit | \'njuːm(ə)rət | \'njʊmə,ret/', 'numerate', 4);
INSERT INTO `words` VALUES (21747, 'a numerical code', 'adj. 数字的，用数字表示的', '/nju:\'merikəl | njuː\'merɪk(ə)l | nʊ\'mɛrɪkl/', 'numerical', 4);
INSERT INTO `words` VALUES (21748, 'Numerous attempts have been made to hide the truth.', 'adj. 许许多多的', '/\'nju:mərəs | \'njuːm(ə)rəs | \'numərəs/', 'numerous', 4);
INSERT INTO `words` VALUES (21749, 'He has painted murals in his children\'s nursery.', 'n. 保育室，托儿所', '/\'nə:səri | \'nɜːs(ə)rɪ | \'nɝsəri/', 'nursery', 4);
INSERT INTO `words` VALUES (21750, 'plants nurtured in the greenhouse', 'n&vt. 养育，培育，教养', '/\'nə:tʃə | \'nɜːtʃə | \'nɝtʃɚ/', 'nurture', 4);
INSERT INTO `words` VALUES (21751, 'The plant absorbs nutrients from the soil.', 'n. 滋养物， 营养品', '/\'njuːtriənt | \'nutrɪənt/', 'nutrient', 4);
INSERT INTO `words` VALUES (21752, 'Nutrition and exercise are essential to fitness and health.', 'n. 营养，营养学', '/nju:\'triʃən | njʊ\'trɪʃ(ə)n | nu\'trɪʃən/', 'nutrition', 4);
INSERT INTO `words` VALUES (21753, 'Cooking vegetables for too long lessens their nutritional value.', 'adj. 营养的， 滋养的； 营养物的， 食物的', '/nju\'trɪʃənl | njʊ\'trɪʃənl/', 'nutritional', 4);
INSERT INTO `words` VALUES (21754, 'Wholemeal bread is more nutritious than white bread.', 'adj. 有营养的， 营养丰富的', '/nju\'trɪʃəs | nʊ\'trɪʃəs/', 'nutritious', 4);
INSERT INTO `words` VALUES (21755, 'nylon fabric', 'n. 尼龙；尼龙长袜', '/\'nailɔn | \'naɪlɒn | \'naɪlɑn/', 'nylon', 4);
INSERT INTO `words` VALUES (21756, 'an oak door', 'n. 橡树， 橡木', '/əuk | ok/', 'oak', 4);
INSERT INTO `words` VALUES (21757, 'Cold worlds shake from the oar.', 'n. 桨；橹', '/ɔ:, əu | ɔː | ɔr/', 'oar', 4);
INSERT INTO `words` VALUES (21758, 'The immaculately tended gardens are an oasis in the midst of Cairo\'s urban sprawl.', 'n. (沙漠中的)绿洲', '/əu\'eisis, \'əuəsis | əʊ\'eɪsɪs | o\'esɪs/', 'oasis', 4);
INSERT INTO `words` VALUES (21759, 'The president took the oath of office (= made the official public promises that every president makes when starting their job ) .', 'n. 誓言，誓约', '/əuθ | əʊθ | oθ/', 'oath', 4);
INSERT INTO `words` VALUES (21760, 'an obedient child', 'adj. 服从的，顺从的', '/əu\'bi:diənt | ə\'biːdɪənt | oˈbidiənt/', 'obedient', 4);
INSERT INTO `words` VALUES (21761, 'an everyday object such as a spoon', 'n. 物体，目标；目的; v. 反对', '/\'ɔbdʒikt, -dʒekt, əb\'dʒekt | \'ɒbdʒɪkt; -dʒekt | \'ɑbdʒɛkt/', 'object', 4);
INSERT INTO `words` VALUES (21762, 'a culture that objectifies women', 'vt. 使客观化； 使具体化； 物化', '/əb\'dʒektɪfaɪ | əb\'dʒɛktɪfaɪ/', 'objectify', 4);
INSERT INTO `words` VALUES (21763, 'Her objection was that he was too young.', 'n. 厌恶，反对；反对的理由', '/əb\'dʒekʃən, ɔb- | əb\'dʒekʃ(ə)n | əb\'dʒɛkʃən/', 'objection', 4);
INSERT INTO `words` VALUES (21764, 'Scientists need to be objective when doing research.', 'adj. 客观的；真实的; n. 目标，目的', '/əb\'dʒektiv, ɔb- | əb\'dʒektɪv | əb\'dʒɛktɪv/', 'objective', 4);
INSERT INTO `words` VALUES (21765, 'Employers have an obligation to treat all employees equally.', 'n. 义务，责任', '/,ɔbli\'ɡeiʃən | ɒblɪ\'geɪʃ(ə)n | ,ɑblɪ\'ɡeʃən/', 'obligation', 4);
INSERT INTO `words` VALUES (21766, 'She offered him the obligatory cup of tea.', 'adj. (法律或道义上)必须的，应尽的', '/\'ɔbliɡətəri, ɔb\'liɡətɔ:ri, -təri | ə\'blɪgət(ə)rɪ | ə\'blɪɡətɔri/', 'obligatory', 4);
INSERT INTO `words` VALUES (21767, 'It’s always a good idea to oblige important clients.', 'v. (以誓言或契约等)束缚某人；施惠', '/ə\'blaɪdʒ/', 'oblige', 4);
INSERT INTO `words` VALUES (21768, 'The shop assistant was very obliging.', 'adj. 乐于助人的', '/ə\'blaidʒiŋ | ə\'blaɪdʒɪŋ/', 'obliging', 4);
INSERT INTO `words` VALUES (21769, 'an oblique glance', 'adj. 斜的，偏斜的', '/ə\'bli:k, ə\'blaik | ə\'bliːk | ə\'blik/', 'oblique', 4);
INSERT INTO `words` VALUES (21770, 'She lay motionless where she was, oblivious to pain.', 'adj. 不在意的，忘却的', '/ə\'bliviəs, ɔ- | ə\'blɪvɪəs/', 'oblivious', 4);
INSERT INTO `words` VALUES (21771, '...an oblong table.', 'n&a. 长方形(的)', '/\'ɔblɔŋ, -lɔ:ŋ | \'ɒblɒŋ | \'ɑblɔŋ/', 'oblong', 4);
INSERT INTO `words` VALUES (21772, 'She’s really obnoxious.', 'adj. 非常讨厌的；可憎的', '/ɔb\'nɔkʃəs | əb\'nɒkʃəs | əb\'nɑkʃəs/', 'obnoxious', 4);
INSERT INTO `words` VALUES (21773, 'Bradford made an obscene gesture.', 'adj. (文学，图画)猥亵的，淫秽的', '/əb\'si:n | əb\'siːn | əb\'sin/', 'obscene', 4);
INSERT INTO `words` VALUES (21774, NULL, '\"a. 暗的，不清楚的；费解的vt使阴暗,使难解; adj. \"', '/əb\'skjʊə | əb\'skjʊr/', 'obscure', 4);
INSERT INTO `words` VALUES (21775, 'obscurities in the text', 'n. 模糊； 费解； 不出名', '/əb\'skjuərəti | əb\'skjʊrəti/', 'obscurity', 4);
INSERT INTO `words` VALUES (21776, 'the Memorial Day observance', 'n. (法律习俗等)遵守；奉行；礼仪，仪式', '/əb\'zə:vəns | əb\'zɜːv(ə)ns | əb\'zɝvəns/', 'observance', 4);
INSERT INTO `words` VALUES (21777, 'He spent two nights under close observation in hospital.', 'n. 观察， 观测； 监视； 评述， 评论', '/ˌɒbzə\'veɪʃn | ,ɑbzɚ\'veʃən/', 'observation', 4);
INSERT INTO `words` VALUES (21778, NULL, 'n. 天文台，气象台，了望台', '/əb\'zə:vitəri, ɔb- | əb\'zɜːvət(ə)rɪ | əb\'zɝvətɔri/', 'observatory', 4);
INSERT INTO `words` VALUES (21779, 'Scientists have observed a drop in ozone levels over the Antarctic.', 'v. 看到；遵守；评论', '/əb\'zɜːv | əb\'zɝv/', 'observe', 4);
INSERT INTO `words` VALUES (21780, NULL, 'v. 使着迷，使烦扰', '/ɔb\'ses | əb\'ses | əb\'sɛs/', 'obsess', 4);
INSERT INTO `words` VALUES (21781, 'She would try to forget her obsession with Christopher.', 'n. 缠住，被困扰；观念固执，死脑筋', '/əb\'seʃən, ɔb- | əb\'seʃ(ə)n | əb\'sɛʃ(ə)n/', 'obsession', 4);
INSERT INTO `words` VALUES (21782, 'obsolete weapons', 'adj. 已废弃的，过时的', '/\'ɔbsəli:t, ,ɔbsə\'li:t | \'ɒbsəliːt | ɑbsəˌlit/', 'obsolete', 4);
INSERT INTO `words` VALUES (21783, 'The tax puts obstacles in the way of companies trying to develop trade overseas.', 'n. 障碍', '/\'ɔbstəkl | \'ɒbstək(ə)l | \'ɑbstəkl/', 'obstacle', 4);
INSERT INTO `words` VALUES (21784, 'He was the most obstinate man I’ve ever met.', 'adj. 顽固的，倔强的，不易屈服的，较难治愈的', '/\'ɔbstinit, -nət | \'ɒbstɪnət | \'ɑbstɪnət/', 'obstinate', 4);
INSERT INTO `words` VALUES (21785, 'A small aircraft was obstructing the runway.', 'v. 阻塞，堵塞；妨碍', '/əb\'strʌkt, ɔb- | əb\'strʌkt/', 'obstruct', 4);
INSERT INTO `words` VALUES (21786, 'These conditions no longer obtain.', 'v. 获得， 得到； 通用， 流行', '/əb\'teɪn | əb\'ten/', 'obtain', 4);
INSERT INTO `words` VALUES (21787, 'The obvious way of reducing pollution is to use cars less.', 'adj. 明显的，清楚的', '/\'ɔbviəs | \'ɒbvɪəs | \'ɑbvɪəs/', 'obvious', 4);
INSERT INTO `words` VALUES (21788, 'I often think fondly of an occasion some years ago in New Orleans.', 'n. 的时刻；机会；需要; v. 引起，导致', '/ə\'keiʒən, əu- | ə\'keɪʒ(ə)n | ə\'keʒn/', 'occasion', 4);
INSERT INTO `words` VALUES (21789, 'He made occasional visits to London.', 'adj. 偶尔的， 间或发生的', '/ə\'keɪʒənl | ə\'keʒənl/', 'occasional', 4);
INSERT INTO `words` VALUES (21790, 'Please state your name, address and occupation.', 'n. 占领； 职业； 消遣', '/ˌɒkju\'peɪʃn | ,ɑkju\'peʃən/', 'occupation', 4);
INSERT INTO `words` VALUES (21791, 'He occupies the house without paying any rent.', 'v. 居住；占', '/\'ɔkjupai | \'ɒkjʊpaɪ | \'ɑkjupaɪ/', 'occupy', 4);
INSERT INTO `words` VALUES (21792, 'A third of accidental deaths occur in the home.', 'v. 发生；想起，想到；存在', '/ə\'kə: | ə\'kɜː | ə\'kɝ/', 'occur', 4);
INSERT INTO `words` VALUES (21793, 'Complaints seemed to be an everyday occurrence.', 'n. 发生；出现', '/ə\'kə:rəns, -\'kʌ- | ə\'kʌr(ə)ns | ə\'kʌrəns/', 'occurrence', 4);
INSERT INTO `words` VALUES (21794, 'It was an odd thing to say.', 'adj. 古怪的，奇数的；单独的；零头的；临时的', '/ɔd | ɒd | ɑd/', 'odd', 4);
INSERT INTO `words` VALUES (21795, '(= it is likely ) that he will commit the same crime again.', 'n. 可能，机会', '/ɔdz | ɒdz | ɑdz/', 'odds', 4);
INSERT INTO `words` VALUES (21796, 'The researchers demonstrate that it is possible to generate odor in a compact device that can fit on the back of a TV with potentially thousands of odors.', 'n. 气味，香气；臭气', '/\'əudə | \'əʊdə | \'oʊdə/', 'odor', 4);
INSERT INTO `words` VALUES (21797, '...the lingering odour of car exhaust.', 'n. 气味', '/\'əudə(r) | \'əudə/', 'odour', 4);
INSERT INTO `words` VALUES (21798, 'a spiritual odyssey', 'n. 长途冒险旅行；一连串的冒险', '/\'ɔdisi | \'ɑdəsi/', 'odyssey', 4);
INSERT INTO `words` VALUES (21799, 'His solicitor said he committed the offence because he was heavily in debt.', 'n. 犯罪，犯规；冒犯', '/ə\'fens | ə\'fɛns/', 'offence', 4);
INSERT INTO `words` VALUES (21800, 'His remarks deeply offended many Scottish people.', 'n. 犯罪；冒犯；攻击', '/ə\'fend | ə\'fɛnd/', 'offend', 4);
INSERT INTO `words` VALUES (21801, 'I found her remarks deeply offensive.', 'adj. 冒犯的；使人不快的；无礼的；攻击性的，进攻性的; n. 进攻， 攻击； 攻势', '/ə\'fensɪv | ə\'fɛnsɪv/', 'offensive', 4);
INSERT INTO `words` VALUES (21802, 'The offer of talks with Moscow marks a significant change from the previous Western position.', 'v. 违犯；伤害的感情; n. 提供；提议', '/ˈɒfə | \'ɒfə | \'ɔfɚ/', 'offer', 4);
INSERT INTO `words` VALUES (21803, '“By investing in it, we can count it as an offset,” she said.', 'n. 抵销；补偿', '/,ɔf\'set, ,ɔ:-, \'ɔfset, \'ɔ:- | \'ɒfset | ,ɔf\'sɛt/', 'offset', 4);
INSERT INTO `words` VALUES (21804, 'The building can accommodate all of the offshore workers and protect them from hurricane damage.', 'a&ad. 离岸的(地)；近海的(地)', '/\'ɔf\'ʃɔ:, \'ɔ:- | \'ɒfʃɔː; ɒf\'ʃɔː | ,ɔf\'ʃɔr/', 'offshore', 4);
INSERT INTO `words` VALUES (21805, 'a lion and its offspring', 'n. 子孙后代；动物的幼仔', '/\'ɔfspriŋ, \'ɔ:- | \'ɒfsprɪŋ | \'ɔfsprɪŋ/', 'offspring', 4);
INSERT INTO `words` VALUES (21806, 'The car won’t start. Do you think it’s an omen?', 'n. 预兆，征兆', '/\'əumən | \'əʊmən | \'omən/', 'omen', 4);
INSERT INTO `words` VALUES (21807, '‘How long will she be ill?’ he asked. There was an ominous silence.', 'adj. 不祥的，不吉利的', '/\'ɔminəs | \'ɒmɪnəs | \'ɑmɪnəs/', 'ominous', 4);
INSERT INTO `words` VALUES (21808, 'Please don’t omit any details, no matter how trivial they may seem.', 'v. 疏忽，忘记；省略；遗漏', '/əu\'mit | ə(ʊ)\'mɪt | ə\'mɪt/', 'omit', 4);
INSERT INTO `words` VALUES (21809, 'I wanted to punch him on the nose.', 'ad&prep. 在上', '/ɔn, ɔ:n, ən, n | ɒn | ɑn/', 'on', 4);
INSERT INTO `words` VALUES (21810, 'Once I get him a job, he’ll be fine.', 'conj. 一旦; adv. 一次；从前', '/wʌns/', 'once', 4);
INSERT INTO `words` VALUES (21811, 'He crashed into an oncoming car.', 'adj. 即将来临的；接近的', '/\'ɔn,kʌmiŋ, \'ɔ:n- | \'ɒnkʌmɪŋ | \'ɔn,kʌmɪŋ/', 'oncoming', 4);
INSERT INTO `words` VALUES (21812, 'I don’t have any ones.', 'a&n&porn. 一', '/wʌn/', 'one', 4);
INSERT INTO `words` VALUES (21813, 'their ongoing search for a new director', 'adj. 继续的', '/\'ɔn,ɡəuiŋ, \'ɔ:n- | \'ɒngəʊɪŋ | \'ɑnɡoɪŋ/', 'ongoing', 4);
INSERT INTO `words` VALUES (21814, 'A crowd of onlookers had gathered at the scene of the accident.', 'n. 旁观者', '/\'ɔn,lukə, \'ɔ:n- | \'ɒnlʊkə | \'ɑnlʊkɚ/', 'onlooker', 4);
INSERT INTO `words` VALUES (21815, 'the onset of winter', 'n. 进攻；开始，发作', '/\'ɔnset, \'ɔ:n- | \'ɒnset | \'ɑnsɛt/', 'onset', 4);
INSERT INTO `words` VALUES (21816, 'The press launched another vicious onslaught on the president.', 'n. 猛攻， 猛袭', '/\'ɒnslɔːt | \'ɑnslɔt/', 'onslaught', 4);
INSERT INTO `words` VALUES (21817, 'He walked onwards to the head of the lake.', 'adv. 向前地， 前进地', '/\'ɒnwədz | \'ɑnwɚdz/', 'onwards', 4);
INSERT INTO `words` VALUES (21818, 'a shower with an opaque glass door', 'adj. 不透光的，不透明的', '/əu\'peik | ə(ʊ)\'peɪk | o\'pek/', 'opaque', 4);
INSERT INTO `words` VALUES (21819, 'There are very few openings in scientific research.', 'n. 口，孔；开始；张开；职位空缺', '/\'əupəniŋ | \'əʊp(ə)nɪŋ | \'opənɪŋ/', 'opening', 4);
INSERT INTO `words` VALUES (21820, 'The whole tax system is now operating more efficiently.', 'v. 运转； 动手术； 起作用； 操作； 经营', '/\'ɒpəreɪt | \'ɑpə\'ret/', 'operate', 4);
INSERT INTO `words` VALUES (21821, 'Patco accepted full responsibility for operational management.', 'adj. 运转的； 操作的； 运营的， 业务的', '/ˌɒpə\'reɪʃənl | \'ɑpə\'reʃənl/', 'operational', 4);
INSERT INTO `words` VALUES (21822, 'When choosing an insurance policy it’s best to get an independent opinion.', 'n. 意见，鉴定', '/ə\'pinjən | ə\'pɪnjən/', 'opinion', 4);
INSERT INTO `words` VALUES (21823, 'Graf’s opponent in today’s final will be Sukova.', 'n. 对手，敌手，反对者', '/ə\'pəunənt | ə\'pəʊnənt | ə\'ponənt/', 'opponent', 4);
INSERT INTO `words` VALUES (21824, 'There are fewer opportunities for new graduates this year.', 'n. 机会', '/,ɔpə\'tju:niti | ɒpə\'tjuːnɪtɪ | ˌɑpɚˈtunɪti, -ˈtju-/', 'opportunity', 4);
INSERT INTO `words` VALUES (21825, 'Congress is continuing to oppose the President’s health care budget.', 'v. 反对，反抗', '/ə\'pəuz | ə\'pəʊz | ə\'poz/', 'oppose', 4);
INSERT INTO `words` VALUES (21826, 'I thought the medicine would make him sleep, but it had the opposite effect.', 'adj. 对面的；相反的，对立的; prep. 在对面', '/\'ɔpəzit, -sit | \'ɒpəzɪt; -sɪt | ˈɑpəzɪt; ˈɑpəsɪt/', 'opposite', 4);
INSERT INTO `words` VALUES (21827, 'native tribes oppressed by the authorities', 'v. 压迫，压制；压抑', '/ə\'pres | ə\'prɛs/', 'oppress', 4);
INSERT INTO `words` VALUES (21828, 'Depending on your circumstances you can opt for one method or the other.', 'v. 挑选，选择', '/ɔpt | ɒpt | ɑpt/', 'opt', 4);
INSERT INTO `words` VALUES (21829, 'the optic nerve', 'adj. 眼的，视觉的；光学的; n. 光学仪器', '/\'ɒptɪk | \'ɑptɪk/', 'optic', 4);
INSERT INTO `words` VALUES (21830, 'microscopes and other optical instruments', 'adj. 视觉的，眼睛的，光学的', '/\'ɔptikəl | \'ɒptɪk(ə)l | \'ɑptɪkl/', 'optical', 4);
INSERT INTO `words` VALUES (21831, 'There are grounds for cautious optimism.', 'n. 乐观，乐观主义', '/\'ɔptimizəm | \'ɒptɪmɪz(ə)m | \'ɑptɪmɪzəm/', 'optimism', 4);
INSERT INTO `words` VALUES (21832, 'Andrew took a more optimistic view.', 'adj. 乐观的， 乐观主义的', '/ˌɒptɪ\'mɪstɪk | ,ɑptɪ\'mɪstɪk/', 'optimistic', 4);
INSERT INTO `words` VALUES (21833, 'optimum conditions for growth', 'adj. 最适宜的', '/\'ɔptiməm | \'ɒptɪməm | \'ɑptəməm/', 'optimum', 4);
INSERT INTO `words` VALUES (21834, 'There are a number of options available.', 'n. 选择，可选择的事物', '/\'ɔpʃən | \'ɒpʃ(ə)n | \'ɑpʃən/', 'option', 4);
INSERT INTO `words` VALUES (21835, 'three optional courses', 'adj. 非强制的，自愿的，自发的', '/\'ɔpʃənəl | \'ɒpʃ(ə)n(ə)l | \'ɑpʃənl/', 'optional', 4);
INSERT INTO `words` VALUES (21836, '\"I see what I would consider a normal patient population, representative of the average experience most people are having, \" Brooklyn optometrist Justin Bazan, a paid consultant to the Vision Council.', 'n. 验光师， 视力测定者', '/ɒp\'tɒmətrɪst | ɑp\'tɑmətrɪst/', 'optometrist', 4);
INSERT INTO `words` VALUES (21837, NULL, 'n. 财富， 富裕； 丰富， 富饶', '/\'ɒpjələns | \'ɑpjələns/', 'opulence', 4);
INSERT INTO `words` VALUES (21838, 'evening dresses in opulent fabrics', 'adj. 豪华的， 华丽的， 富裕的； 丰富的， 丰饶的', '/\'ɒpjələnt | \'ɑpjələnt/', 'opulent', 4);
INSERT INTO `words` VALUES (21839, 'Mars and Earth have orbits which change with time.', 'n. 天体轨道；势力范围; v. 沿轨道运行', '/\'ɔ:bit | \'ɔːbɪt | \'ɔrbɪt/', 'orbit', 4);
INSERT INTO `words` VALUES (21840, 'a cherry orchard', 'n. 果园', '/\'ɔ:tʃəd | \'ɔːtʃəd | \'ɔrtʃɚd/', 'orchard', 4);
INSERT INTO `words` VALUES (21841, 'He directed an orchestra.', 'n. 管弦乐队', '/\'ɔ:kistrə, -kes- | \'ɔːkɪstrə | \'ɔrkɪstrə/', 'orchestra', 4);
INSERT INTO `words` VALUES (21842, 'They manned themselves for an ordeal.', 'n. (对品格或忍耐力的)严格考验', '/ɔ:\'di:l, \'ɔ:di:l | ɔː\'diːəl | ɔr\'dil/', 'ordeal', 4);
INSERT INTO `words` VALUES (21843, 'She needs to organize her ideas in a more orderly way.', 'adj. 整齐的；有秩序的；有条不紊的', '/\'ɔ:dəli | \'ɔːd(ə)lɪ | \'ɔrdɚli/', 'orderly', 4);
INSERT INTO `words` VALUES (21844, 'iron ore', 'n. 矿石', '/ɔ: | ɔː | ɔr/', 'ore', 4);
INSERT INTO `words` VALUES (21845, '...damage to the muscles and internal organs.', 'n. 器官；报刊；风琴', '/\'ɔ:ɡən | \'ɔːg(ə)n | \'ɔrɡən/', 'organ', 4);
INSERT INTO `words` VALUES (21846, 'Adding organic matter such as manure can improve the soil.', 'adj. 器官的； 有机的； 有机体的； 组织的', '/ɔː\'gænɪk | ɔr\'gænɪk/', 'organic', 4);
INSERT INTO `words` VALUES (21847, 'All living organisms have to adapt to changes in environmental conditions.', 'n. 生物；有机体；有机的组织', '/\'ɔ:ɡənizəm | \'ɔːg(ə)nɪz(ə)m | \'ɔrɡənɪzəm/', 'organism', 4);
INSERT INTO `words` VALUES (21848, 'The lawyer helped to organize a group of parents who took action for their children.', 'v. 组织， 使有条理； 成立', '/\'ɔːgənaɪz | ɔrɡənˌaɪz/', 'organize', 4);
INSERT INTO `words` VALUES (21849, NULL, 'a&n. 东方的；东方人', '/,ɔ:ri\'entəl, ,əu- | ɔːrɪ\'ent(ə)l; ɒr- | ,orɪ\'ɛntəl/', 'oriental', 4);
INSERT INTO `words` VALUES (21850, 'The reason for this was that he decided to orientate the map in the direction of the Pole Star since Polaris was the immovable guiding light in which the voyagers of that era placed their trust.', 'v. 定位；给定位', '/\'ɔ:rienteit, \'əu- | \'ɔːrɪənteɪt; \'ɒr- | \'orɪɛntet/', 'orientate', 4);
INSERT INTO `words` VALUES (21851, 'This is orientation week for all the new students.', 'n. 定位； 方向， 方位； 情况介绍； 培训， 训练', '/ˌɔːrien\'teɪʃn | orɪɛn\'teʃən/', 'orientation', 4);
INSERT INTO `words` VALUES (21852, 'The tradition has its origins in the Middle Ages.', 'n. 起源，血统', '/\'ɔridʒin, \'ɔ:- | \'ɒrɪdʒɪn | \'ɔrɪdʒɪn/', 'origin', 4);
INSERT INTO `words` VALUES (21853, 'The colours are much more striking in the original.', 'n. 起源；原件，原稿; adj. 最初的；有独创性的', '/ə\'ridʒənəl | ə\'rɪdʒɪn(ə)l; ɒ- | ə\'rɪdʒənl/', 'original', 4);
INSERT INTO `words` VALUES (21854, 'How did the plan originate?', 'v. 发生，发起；发明', '/ə\'ridʒəneit | ə\'rɪdʒɪneɪt; ɒ- | əˈrɪdʒəˌnet/', 'originate', 4);
INSERT INTO `words` VALUES (21855, 'a shelf covered with books and ornaments', 'n. 装饰(物)', '/\'ɔ:nəmənt, \'ɔ:nəment | \'ɔːnəm(ə)nt | \'ɔrnəmənt/', 'ornament', 4);
INSERT INTO `words` VALUES (21856, 'ornamental gardens', 'adj. 装饰性的， 装饰的', '/ˌɔːnə\'mentl | ,ɔrnə\'mɛntl/', 'ornamental', 4);
INSERT INTO `words` VALUES (21857, 'orthodox medical treatments', 'adj. 正(传)统的', '/\'ɔːθədɒks | \'ɔrθədɑks/', 'orthodox', 4);
INSERT INTO `words` VALUES (21858, 'The stock market is oscillating wildly at the moment.', 'v. 摆动，振动；踌躇，犹豫', '/\'ɔsileit | \'ɒsɪleɪt | \'ɑsɪlet/', 'oscillate', 4);
INSERT INTO `words` VALUES (21859, 'The ostensible purpose of these meetings was to gather information on financial strategies.', 'adj. (指理由)表面的；假装的', '/ɔs\'tensəbl | ɒ\'stensɪb(ə)l | ɑ\'stɛnsəbl/', 'ostensible', 4);
INSERT INTO `words` VALUES (21860, 'Her lifestyle was remarkably free from ostentation.', 'n. 夸耀，卖弄', '/,ɔsten\'teiʃən | ,ɒsten\'teɪʃ(ə)n | \'ɑstɛn\'teʃən/', 'ostentation', 4);
INSERT INTO `words` VALUES (21861, 'people who smoke or otherwise abuse their bodies', 'adv. 用其他方法；不同地; conj. 否则，不然', '/\'ʌðəwaɪz | \'ʌðɚwaɪz/', 'otherwise', 4);
INSERT INTO `words` VALUES (21862, 'How to pronounce the noun \"ounce\" in the announcement?', 'n. 盎司', '/auns | aʊns/', 'ounce', 4);
INSERT INTO `words` VALUES (21863, 'The leaders have been ousted from power by nationalists.', 'v. 驱赶，驱逐', '/aust | aʊst/', 'oust', 4);
INSERT INTO `words` VALUES (21864, NULL, 'adv. of; adv. line; with跟. 不一致', '/aut | aʊt/', 'out', 4);
INSERT INTO `words` VALUES (21865, 'a cholera outbreak', 'n. (战争、愤怒等)爆发', '/\'autbreik, ,aut\'breik | \'aʊtbreɪk | \'aʊtbrek/', 'outbreak', 4);
INSERT INTO `words` VALUES (21866, 'Smokers often feel as though they are being treated as social outcasts.', 'a&n. 被遗弃的；被遗弃者，被逐出者', '/\'autkɑ:st, -kæst, ,aut\'kɑ:st, -\'kæst | \'aʊtkɑːst | \'aʊtkæst/', 'outcast', 4);
INSERT INTO `words` VALUES (21867, 'People who had heard the evidence at the trial were surprised at the outcome.', 'n. 结果，后果', '/\'autkʌm | \'aʊtkʌm | \'aʊt\'kʌm/', 'outcome', 4);
INSERT INTO `words` VALUES (21868, 'The closure of the local hospital has caused a huge public outcry.', 'n. 公开反对', '/\'autkrai, ,aut\'krai | \'aʊtkraɪ/', 'outcry', 4);
INSERT INTO `words` VALUES (21869, 'outdated teaching methods', 'adj. 过时的，不流行的', '/,aut\'deitid | aʊt\'deɪtɪd | \'aʊt\'detɪd/', 'outdated', 4);
INSERT INTO `words` VALUES (21870, 'When it comes to speed of response, a small firm can outdo a big company.', 'v. 超过；胜过', '/,aut\'du | aʊt\'duː | ,aʊt\'du/', 'outdo', 4);
INSERT INTO `words` VALUES (21871, 'She bought a new outfit for the party.', 'n. 装备，全部用品', '/\'autfit | \'aʊtfɪt/', 'outfit', 4);
INSERT INTO `words` VALUES (21872, 'The bill would have outlawed several types of guns.', 'n. 被剥夺公民权者; v. 禁止', '/\'autlɔ: | \'aʊtlɔː | \'aʊtlɔ/', 'outlaw', 4);
INSERT INTO `words` VALUES (21873, 'Her father had found an outlet for his ambition in his work.', 'n. 河流等出口，出路；发泄(感情等)的方法', '/\'autlet, -lit | \'aʊtlet | \'aʊtlɛt/', 'outlet', 4);
INSERT INTO `words` VALUES (21874, 'a research proposal outline', 'n. 外形，轮廓；大纲，纲要', '/\'autlain | \'aʊtlaɪn/', 'outline', 4);
INSERT INTO `words` VALUES (21875, 'Exercise will improve your looks and your outlook.', 'n. 观点， 见解； 展望， 前景', '/\'autluk | \'aʊtlʊk/', 'outlook', 4);
