INSERT INTO `words` VALUES (21877, 'a remote outpost of the empire', 'n. 前哨； 偏远村落', '/\'autpəust | \'aʊtpost/', 'outpost', 4);
INSERT INTO `words` VALUES (21878, 'Output is up 30% on last year.', 'n. 产量；产出', '/\'autput, ,aut\'put | \'aʊtpʊt/', 'output', 4);
INSERT INTO `words` VALUES (21879, 'outrageous prices', 'adj. 残暴的，蛮横的', '/aut\'reidʒəs | aʊt\'reɪdʒəs | aʊt\'redʒəs/', 'outrageous', 4);
INSERT INTO `words` VALUES (21880, 'an outright refusal', 'adj. 断然的；明白无误的', '/\'autrait, aut\'rait, \'aut\'rait | aʊt\'raɪt | \'aʊtraɪt/', 'outright', 4);
INSERT INTO `words` VALUES (21881, 'It may outsell his previous novels.', 'vt. 卖得比…多', '/ˌaut\'sel | ,aʊt\'sɛl/', 'outsell', 4);
INSERT INTO `words` VALUES (21882, 'It was clear from the outset that there were going to be problems.', 'n. 开始，开端', '/\'autset | \'aʊtset | \'aʊtsɛt/', 'outset', 4);
INSERT INTO `words` VALUES (21883, 'Hours later we reached the outskirts of New York.', 'n. (尤指城市)郊区', '/\'autskə:ts | \'aʊtskɜːts | \'aʊt\'skɝts/', 'outskirts', 4);
INSERT INTO `words` VALUES (21884, 'an outspoken critic of the education reforms', 'adj. 直言的，坦率的', '/,aut\'spəukən | aʊt\'spəʊk(ə)n | aʊt\'spokən/', 'outspoken', 4);
INSERT INTO `words` VALUES (21885, 'We outstripped all our competitors in sales last year.', 'v. 胜过，超过', '/,aut\'strip | aʊt\'strɪp | ,aʊt\'strɪp/', 'outstrip', 4);
INSERT INTO `words` VALUES (21886, 'The economy and outward appearance of the area have changed considerably.', 'adj. 外面的； 外表的， 表面的', '/\'autwəd | \'aʊtwɚd/', 'outward', 4);
INSERT INTO `words` VALUES (21887, 'The benefits of the scheme outweigh the disadvantages.', 'v. 比更重，比更重要', '/,aut\'wei | aʊt\'weɪ | \'aʊt\'we/', 'outweigh', 4);
INSERT INTO `words` VALUES (21888, 'Using 2 spoons, form the cheese into small balls or ovals.', 'n&a. 卵形(的)，椭圆形(的)', '/\'əuvəl | \'əʊv(ə)l | \'ovl/', 'oval', 4);
INSERT INTO `words` VALUES (21889, 'The Chancellor’s entrance was greeted with a standing ovation (= everyone stood up ).', 'n. 热烈欢迎，欢呼', '/əu\'veiʃən | ə(ʊ)\'veɪʃ(ə)n | o\'veʃən/', 'ovation', 4);
INSERT INTO `words` VALUES (21890, 'The overall cost of the exhibition was £400,000.', 'adj. 包括一切的，全部的; n. 罩衫，工装裤', '/\'əuvərɔ:l, ,əuvə\'rɔ:l | \'əʊvərɔːl | ,ovə\'rɔl/', 'overall', 4);
INSERT INTO `words` VALUES (21891, 'He struggled to overcome his shyness.', 'v. 克服；压倒', '/,əuvə\'kʌm | əʊvə\'kʌm | ,ovɚ\'kʌm/', 'overcome', 4);
INSERT INTO `words` VALUES (21892, 'a £250 overdraft', 'n. 透支； 透支额', '/\'əuvədrɑːft | \'ovɚdræft/', 'overdraft', 4);
INSERT INTO `words` VALUES (21893, 'an overdue gas bill', 'adj. 过期未付的', '/\'əuvə\'dju: | əʊvə\'djuː | \'ovɚ\'dʊ/', 'overdue', 4);
INSERT INTO `words` VALUES (21894, 'He tends to overestimate his own abilities.', 'vt. 对…估计过高[ˌəuvər\'estImət]; n. 过高的估计', '/ˌəuvər\'estɪmeɪt | ,ovər\'ɛstɪmət/', 'overestimate', 4);
INSERT INTO `words` VALUES (21895, 'Hunger and poverty often compel the poor to overexploit the resources on which their own livelihoods depend.', 'vt. 过度开采', '/ˌəuvərɪk\'splɔɪt/', 'overexploit', 4);
INSERT INTO `words` VALUES (21896, 'He had overfilled the jug.', 'v. 装得太多， 装到满溢', '/,əuvə\'fil | \'əuvəˌfɪl/', 'overfill', 4);
