INSERT INTO `words` VALUES (21902, 'When the bag is folded, the bottom overlaps one side.', 'v. 与…互搭，与重叠，与部分相同', '/,əuvə\'læp, \'əuvəlæp | əʊvə\'læp | \'ovəlæp/', 'overlap', 4);
