INSERT INTO `words` VALUES (21904, 'Clay overlies chalk in the southern mountains.', 'v. 躺在…上面； 置于…上面', '/ˌəuvə\'laɪ | \'ovɚ\'lai/', 'overlie', 4);
INSERT INTO `words` VALUES (21905, 'It is easy to overlook a small detail like that.', 'v. 俯视；忽略；宽恕', '/,əuvə\'luk, \'əuvəluk | əʊvə\'lʊk | ,ovɚ\'lʊk/', 'overlook', 4);
