INSERT INTO `words` VALUES (21909, 'Chris is going to work overseas.', 'adv. 向国外；在海外，在外国; adj. 来自海外的，外国来的', '/ˌəuvə\'siːz | ,ovɚ\'siz/', 'overseas', 4);
