INSERT INTO `words` VALUES (21912, 'an overt attempt to silence their political opponents', 'adj. 公开的，明显的，公然的', '/\'əuvə:t, əu\'və:t | əʊ\'vɜːt; \'əʊvət | o\'vɝt/', 'overt', 4);
