INSERT INTO `words` VALUES (22028, 'Submarines are most vulnerable to detection when the submarine commander uses a periscope to assess the situation on the surface.', 'n. 潜望镜', '/\'periskəup | \'perɪskəʊp | \'pɛrɪskop/', 'periscope', 4);
