INSERT INTO `words` VALUES (22218, 'The data can be used to make useful economic predictions .', 'n. 预言， 预料， 预报', '/prɪ\'dɪkʃn | prɪ\'dɪkʃən/', 'prediction', 4);
INSERT INTO `words` VALUES (22219, 'They take pains to hire people whose personalities predispose them to serve customers well.', 'v. 事先影响某人； 偏爱； 易受感染', '/ˌpriːdɪ\'spəuz | \'pridɪ\'spoz/', 'predispose', 4);
INSERT INTO `words` VALUES (22220, 'There is a thin dividing line between educating the public and creating a predisposition to panic.', 'n. 倾向，趋势，偏好', '/\'pri:,dispə\'ziʃən | priːdɪspə\'zɪʃn | \'pridɪspə\'zɪʃən/', 'predisposition', 4);
INSERT INTO `words` VALUES (22221, 'the predominant group in society', 'adj. 主要的，占优势的', '/,pri\'dɔminənt | prɪ\'dɒmɪnənt | prɪ\'dɑmənənt/', 'predominant', 4);
INSERT INTO `words` VALUES (22222, 'In older age groups women predominate because men tend to die younger.', 'vi. 统治， 支配； 占优势', '/prɪ\'dɒmɪneɪt | prɪ\'dɑmə\'net/', 'predominate', 4);
