INSERT INTO `words` VALUES (22229, 'Women still face prejudice in the workplace.', 'n. 偏见，成见；(法律)损害，伤害', '/\'predʒudis | \'predʒʊdɪs | \'prɛdʒədɪs/', 'prejudice', 4);
