INSERT INTO `words` VALUES (22231, 'Living together as a prelude to marriage is now considered acceptable in many countries.', 'n. 序言，序幕', '/\'prelju:d, \'prei- | \'preljuːd | \'prɛljud/', 'prelude', 4);
