INSERT INTO `words` VALUES (22238, 'Arriving late is a woman’s prerogative .', 'n. 特权', '/pri\'rɔɡətiv | prɪ\'rɒgətɪv/', 'prerogative', 4);
INSERT INTO `words` VALUES (22239, 'Planning, as they employ the term, means: plans made by others will prescribe to me what I am to do and how to do it.', 'v. 吩咐使用', '/pris\'kraib | prɪ\'skraɪb/', 'prescribe', 4);
INSERT INTO `words` VALUES (22240, 'We are trying to cut the price of prescription drugs .', 'n. 规定，指定；药方，处方', '/pris\'kripʃən | prɪ\'skrɪpʃ(ə)n | prɪ\'skrɪpʃən/', 'prescription', 4);
INSERT INTO `words` VALUES (22241, 'Your presence is requested at the club meeting on Friday.', 'n. 出席，到场；风采，风度', '/\'prezəns | \'prez(ə)ns | \'prɛzns/', 'presence', 4);
INSERT INTO `words` VALUES (22242, 'We will begin a series of presentations to help the public fully understand our system.', 'n. 赠送；提出；显示；描述', '/prez(ə)n\'teɪʃ(ə)n | ,prizɛn\'teʃən/', 'presentation', 4);
INSERT INTO `words` VALUES (22243, 'We must encourage the planting of new trees and preserve our existing woodlands.', 'v. 保护；保存', '/pri\'zə:v | prɪ\'zɜːv | prɪ\'zɝv/', 'preserve', 4);
INSERT INTO `words` VALUES (22244, 'President Bush', 'n. 总统， 校长， 会长， 主席', '/\'prezɪdənt | \'prɛzɪdənt/', 'president', 4);
INSERT INTO `words` VALUES (22245, 'They are putting pressure on people to vote yes.', 'n. 压力，压强；强制，压迫; vt. 对…施加压力； 迫使， 说服', '/\'preʃə(r) | \'prɛʃɚ/', 'pressure', 4);
