INSERT INTO `words` VALUES (22247, 'a prestigious literary award', 'adj. 有威信的；有声望的', '/pre\'stidʒəs, -\'sti:- | pre\'stɪdʒəs | prɛ\'stɪdʒəs/', 'prestigious', 4);
INSERT INTO `words` VALUES (22248, 'It’s raining, which presumably means that your football match will be cancelled.', 'adv. 假定地；也许', '/pri\'zju:-məbli,pri:- | prɪ\'zjuːməblɪ | prɪ\'zuməbli/', 'presumably', 4);
INSERT INTO `words` VALUES (22249, 'She was enraged by his presumption.', 'n. 假定，推测；无理，傲慢', '/pri\'zʌmpʃən, pri:- | prɪ\'zʌm(p)ʃ(ə)n | pri\'zʌmpʃən/', 'presumption', 4);
INSERT INTO `words` VALUES (22250, 'The idea of heaven presupposes the existence of God.', 'vt. 预先假定…属实； 认为， 假设； 以…为先决条件， 以…为前提', '/ˌpriːsə\'pəuz | ,prisə\'poz/', 'presuppose', 4);
