INSERT INTO `words` VALUES (22253, 'a pretentious film', 'adj. 自负的，自命不凡的', '/pri\'tenʃəs, pri:- | prɪ\'tenʃəs | prɪ\'tɛnʃəs/', 'pretentious', 4);
