INSERT INTO `words` VALUES (22358, 'He punched me and knocked my teeth out.', 'v. 穿孔，打孔；重击，猛击; n. 猛击； 冲床， 穿孔机； 力量， 效力', '/pʌntʃ/', 'punch', 4);
