INSERT INTO `words` VALUES (22436, 'He was accused of causing death by reckless driving .', 'adj. 鲁莽的', '/\'reklis | \'reklɪs | \'rɛkləs/', 'reckless', 4);
INSERT INTO `words` VALUES (22437, 'The expression ‘full moon’ means the fourteenth day of the moon reckoned from its first appearance.', 'v. 计算', '/\'rekən | \'rek(ə)n | \'rɛkən/', 'reckon', 4);
INSERT INTO `words` VALUES (22438, 'This land will be reclaimed for a new airport.', 'v. 开垦，开拓；要求归还', '/ri\'kleim | rɪ\'kleɪm | rɪ\'klem/', 'reclaim', 4);
INSERT INTO `words` VALUES (22439, 'She proceeded to recline on a chaise longue.', 'vt&vi. 斜倚，躺', '/ri\'klain | rɪ\'klaɪn/', 'recline', 4);
INSERT INTO `words` VALUES (22440, 'He has achieved recognition and respect as a scientist.', 'n. 识别； 认出； 承认， 确认， 认可； 赏识， 表彰', '/ˌrekəg\'nɪʃn | ,rɛkəɡ\'nɪʃən/', 'recognition', 4);
INSERT INTO `words` VALUES (22441, 'I didn’t recognize you in your uniform.', 'vt. 认出； 承认， 认可', '/\'rekəgnaɪz | ˈrɛkəɡˌnaɪz/', 'recognize', 4);
INSERT INTO `words` VALUES (22442, 'Doctors strongly recommend that fathers should be present at their baby’s birth.', 'vt. 推荐； 劝告； 使受欢迎', '/ˌrekə\'mend | \'rɛkə\'mɛnd/', 'recommend', 4);
INSERT INTO `words` VALUES (22443, 'Try to get letters of recommendation from bosses and colleagues.', 'n. 推荐，介绍；推荐信', '/,rekəmen\'deiʃən | ,rekəmen\'deɪʃ(ə)n | ,rɛkəmɛn\'deʃən/', 'recommendation', 4);
INSERT INTO `words` VALUES (22444, 'Jonah and his youngest son were, on the surface at least, reconciled.', 'v. 使和解；使复交；调解，调停', '/\'rekənsail | \'rek(ə)nsaɪl | \'rɛkənsaɪl/', 'reconcile', 4);
INSERT INTO `words` VALUES (22445, 'a reconstruction of a Roman villa', 'n. 重建； 再现', '/ˌriːkən\'strʌkʃn | ,rikən\'strʌkʃən/', 'reconstruction', 4);
INSERT INTO `words` VALUES (22446, 'We may conclude that he never had recourse to this simple experiment.', 'n. 依靠； 求助， 求援', '/rɪ\'kɔːs | \'rikɔrs/', 'recourse', 4);
INSERT INTO `words` VALUES (22447, 'It was some hours before she recovered consciousness .', 'vt&vi. 重新找到；复原，痊愈', '/ri\'kʌvə | rɪ\'kʌvə | rɪ\'kʌvɚ/', 'recover', 4);
INSERT INTO `words` VALUES (22448, 'You can never recreate the feeling of winning for the first time.', 'vt. 再现， 再创造', '/ˌriːkrɪ\'eɪt | ,rikrɪ\'et/', 'recreate', 4);
INSERT INTO `words` VALUES (22449, 'His only recreations are drinking beer and watching football.', 'n. 娱乐， 消遣', '/ˌrekri\'eɪʃn | ,rɛkrɪ\'eʃən/', 'recreation', 4);
INSERT INTO `words` VALUES (22450, '...parks and other recreational facilities.', 'adj. 消遣的， 娱乐的； 游戏的', '/ˌrekri\'eɪʃənl | ,rɛkri\'eʃənəl/', 'recreational', 4);
INSERT INTO `words` VALUES (22451, 'We’re having difficulty recruiting enough qualified staff.', 'v&n. 招募，吸收', '/ri\'kru:t | rɪ\'kruːt | rɪ\'krut/', 'recruit', 4);
INSERT INTO `words` VALUES (22452, 'Suppose the width of a rectangle is x metres.', 'n. 矩形，长方形', '/\'rek,tæŋɡl | \'rektæŋg(ə)l | \'rɛktæŋɡl/', 'rectangle', 4);
INSERT INTO `words` VALUES (22453, '...a rectangular table.', 'adj. 长方形的， 矩形的', '/rek\'tæŋgjələ(r) | rɛk\'tæŋgjəlɚ/', 'rectangular', 4);
INSERT INTO `words` VALUES (22454, 'I did my best to rectify the situation, but the damage was already done.', 'v. 纠正；矫正', '/\'rektifai | \'rektɪfaɪ | \'rɛktɪfaɪ/', 'rectify', 4);
INSERT INTO `words` VALUES (22455, 'We take all our bottles to be recycled.', 'v. 使再循环；回收利用', '/,ri:\'saikl | riː\'saɪk(ə)l | ,ri\'saɪkl/', 'recycle', 4);
INSERT INTO `words` VALUES (22456, 'Olivier’s performance redeemed an otherwise second-rate play.', 'v. 买回，赎回；补偿；补救', '/ri\'di:m | rɪ\'diːm | rɪ\'dim/', 'redeem', 4);
