INSERT INTO `words` VALUES (22458, 'The governor announced a new plan to reduce crime.', 'v. 减少， 缩小； 简化', '/rɪ\'djuːs | rɪ\'dʊs/', 'reduce', 4);
INSERT INTO `words` VALUES (22459, 'the removal of redundant information', 'adj. 多余的，过剩的', '/ri\'dʌndənt | rɪ\'dʌnd(ə)nt | rɪ\'dʌndənt/', 'redundant', 4);
INSERT INTO `words` VALUES (22460, 'the final reel', 'n. 卷，轴；(胶片)一盘; v. 卷', '/ri:l, riəl | riːl | ril/', 'reel', 4);
INSERT INTO `words` VALUES (22461, 'Conclusions Using HACCP method in refectory obtained good effect.', 'n. 餐厅， 食堂', '/rɪ\'fektri | rɪ\'fɛktri/', 'refectory', 4);
INSERT INTO `words` VALUES (22462, 'In his speech, he referred to a recent trip to Canada.', 'v. 参考， 查阅， 查询； 提到， 谈及； 引用； 提交， 上呈', '/rɪ\'fɜː(r) | rɪ\'fɝ/', 'refer', 4);
INSERT INTO `words` VALUES (22463, 'Vautrot has refereed in two World Cups.', 'v. 裁判；仲裁，', '/ˌrefə\'riː | ,rɛfə\'ri/', 'referee', 4);
INSERT INTO `words` VALUES (22464, 'a list of towns, each with a map reference', 'n. 证明；出处；参照', '/\'refərəns | \'ref(ə)r(ə)ns | \'rɛfrəns/', 'reference', 4);
INSERT INTO `words` VALUES (22465, 'The city council agreed to hold a referendum on the issue in November.', 'n. 公民投票、复决权', '/,refə\'rendəm | ,rɛfə\'rɛndəm/', 'referendum', 4);
INSERT INTO `words` VALUES (22466, 'oil refining', 'v. 精炼，提纯；使文雅', '/ri\'fain | rɪ\'faɪn/', 'refine', 4);
INSERT INTO `words` VALUES (22467, 'Some further refinement is needed.', 'n. 精巧的附件， 精制的改良品； 精炼； 文雅', '/rɪ\'faɪnmənt/', 'refinement', 4);
INSERT INTO `words` VALUES (22468, 'Mrs. Hardie refrained from making any comment.', 'v. 抑制', '/,ri:\'frein | rɪ\'freɪn | rɪ\'fren/', 'refrain', 4);
INSERT INTO `words` VALUES (22469, 'A shower will refresh you.', 'v. 复原， 更新； 精神振作， 精力恢复', '/rɪ\'freʃ | ri\'frɛʃ/', 'refresh', 4);
INSERT INTO `words` VALUES (22470, NULL, 'n. 提神物； 帮助记忆的东西或人； 补习课程', '/ri\'freʃə, ri:- | rɪ\'freʃə(r)/', 'refresher', 4);
INSERT INTO `words` VALUES (22471, 'It made a refreshing change to talk to someone new.', 'adj. 使精力恢复的；使耳目一新的', '/ri\'freʃiŋ, ri:- | rɪ\'freʃɪŋ | ri\'frɛʃɪŋ/', 'refreshing', 4);
INSERT INTO `words` VALUES (22472, 'Refreshments will be served after the meeting.', 'n. 点心', '/ri\'freʃmənt, ri:- | rɪ\'freʃm(ə)nt | ri\'frɛʃmənt/', 'refreshment', 4);
INSERT INTO `words` VALUES (22473, NULL, 'n. 冰箱； 冷藏库', '/rɪ\'frɪdʒəreɪtə(r) | rɪ\'frɪdʒəretɚ/', 'refrigerator', 4);
INSERT INTO `words` VALUES (22474, 'Refugees were streaming across the border.', 'n. 避难者，难民', '/,refju\'dʒi:, \'refjudʒi: | refjʊ\'dʒiː | \'rɛfjʊdʒi/', 'refugee', 4);
INSERT INTO `words` VALUES (22475, 'I took the radio back, and they refunded my money .', 'v. 归还; n. 归还；归还额', '/ri\'fʌnd | ˈriːfʌnd | ˈrifʌnd/', 'refund', 4);
INSERT INTO `words` VALUES (22476, 'A refundable deposit is payable on arrival.', 'adj. 可退还的， 可归还的， 可偿还的', '/rɪ\'fʌndəbl | \'rifʌndəbl/', 'refundable', 4);
INSERT INTO `words` VALUES (22477, 'Her country suffered through her refusal to accept change.', 'n. 拒绝', '/ri\'fju:zəl, ri:- | rɪ\'fjuːz(ə)l | rɪ\'fjuzl/', 'refusal', 4);
INSERT INTO `words` VALUES (22478, 'Regarding your recent inquiry, I have enclosed a copy of our new brochure.', 'prep. 关于', '/ri\'ɡɑ:diŋ, ri:- | rɪ\'gɑːdɪŋ | rɪ\'ɡɑrdɪŋ/', 'regarding', 4);
INSERT INTO `words` VALUES (22479, 'The new tax laws were rammed through regardless of the opposition of the majority of the people.', 'adj. 不注意的，不顾的', '/rɪ\'gɑːdlɪs | rɪ\'ɡɑrdləs/', 'regardless', 4);
INSERT INTO `words` VALUES (22480, NULL, 'n. 新生，更新', '/ri,dʒenə\'reiʃən, ri:- | rɪdʒenə\'reɪʃn | ridʒɛnə\'reʃən/', 'regeneration', 4);
INSERT INTO `words` VALUES (22481, NULL, 'n. 摄政者', '/\'riːdʒənt | \'ridʒənt/', 'regent', 4);
INSERT INTO `words` VALUES (22482, 'The regime got rid of most of its opponents.', 'n. 政体，政权；政治制度', '/rei\'ʒi:m, ri-, ri\'dʒi:m | reɪ\'ʒiːm | re\'ʒim/', 'regime', 4);
INSERT INTO `words` VALUES (22483, 'efforts to bring peace to the region', 'n. 地区； 范围', '/\'riːdʒən | \'ridʒən/', 'region', 4);
