INSERT INTO `words` VALUES (22485, 'The tanker is registered in Rotterdam.', 'v. 登记，注册', '/\'redʒistə | \'redʒɪstə | \'rɛdʒɪstɚ/', 'register', 4);
INSERT INTO `words` VALUES (22486, 'The groom knew immediately that something was wrong when the registrar at Derry\'s Guildhall unexpectedly claimed that there was unfinished paperwork just before the ceremony began.', 'n. 登记员，记录员', '/,redʒi\'strɑ:, \'redʒis- | \'redʒɪstrɑː; ,redʒɪ\'strɑː | ,rɛdʒɪ\'strɑr/', 'registrar', 4);
INSERT INTO `words` VALUES (22487, 'Student registration (= for a course of study ) starts the first week in September.', 'n. 登记， 注册； 挂号； 登记或注册的项目', '/ˌredʒɪ\'streɪʃn | \'rɛdʒɪ\'streʃən/', 'registration', 4);
INSERT INTO `words` VALUES (22488, 'Climate change is disrupting the regularity of the seasons.', 'n. 规律性， 规则性； 整齐， 匀称', '/ˌregju\'lærəti | ˌrɛɡjəˈlærətɪ/', 'regularity', 4);
INSERT INTO `words` VALUES (22489, 'strict rules regulating the use of chemicals in food', 'v. 管理，控制；调整', '/\'reɡjuleit | \'regjʊleɪt | \'rɛɡjulet/', 'regulate', 4);
