INSERT INTO `words` VALUES (22492, 'George VI reigned from 1936 to 1952.', 'vi&n. (君主)统治，存在，现存', '/rein | reɪn | ren/', 'reign', 4);
INSERT INTO `words` VALUES (22493, 'I\'ll be happy to reimburse you for any expenses you\'ve had.', 'v. 偿还；付还', '/,ri:im\'bə:s | ,riːɪm\'bɜːs | ,riɪm\'bɝs/', 'reimburse', 4);
INSERT INTO `words` VALUES (22494, 'The film reinforces the idea that women should be pretty and dumb.', 'v. 增援；加强', '/,ri:in\'fɔ:s | riːɪn\'fɔːs | ,riɪn\'fɔrs/', 'reinforce', 4);
INSERT INTO `words` VALUES (22495, 'The bridge needs some structural reinforcement.', 'n. 增援， 加强， 加固', '/ˌriːɪn\'fɔːsmənt | ,riɪn\'fɔrsmənt/', 'reinforcement', 4);
INSERT INTO `words` VALUES (22496, 'The good news for committed shoppers is a so-called \'soft break\' – a few minutes rest grabbing a coffee, for example - can reinvigorate our senses, although only temporarily.', 'vt. 使重新振作； 使恢复活力', '/ˌriːɪn\'vɪgəreɪt | ,riɪn\'vɪɡəret/', 'reinvigorate', 4);
