INSERT INTO `words` VALUES (22498, 'Sarah rejected her brother’s offer of help.', 'vt. 拒绝[\'riːdʒ3kt]; n. 被拒货品， 不合格品', '/rɪ\'dʒ3kt | rɪ\'dʒɛkt/', 'reject', 4);
INSERT INTO `words` VALUES (22499, 'Garbo plays the queen, rejoicing in the love she has found with Antonio.', 'vt&vi. 欣喜，高兴', '/ri\'dʒɔis | rɪ\'dʒɒɪs | rɪ\'dʒɔɪs/', 'rejoice', 4);
INSERT INTO `words` VALUES (22500, 'Ben Brantley\'s article on Sir Ian McKellen rekindled many memories.', 'vt. 重新点燃； 使复苏', '/ˌriː\'kɪndl | ,ri\'kɪndl/', 'rekindle', 4);
