INSERT INTO `words` VALUES (22505, 'I just want to sit down and relax.', 'v. 放松', '/rɪ\'læks/', 'relax', 4);
INSERT INTO `words` VALUES (22506, 'the 100 metres relay', 'n. 替班；转播；接力赛跑; n. 转播；传递', '/\'ri:lei, ri\'lei | \'riːleɪ | rɪ\'le/', 'relay', 4);
INSERT INTO `words` VALUES (22507, 'Police arrested several men, who were later released.', 'vt&n. 释放；发表', '/ri\'li:s | rɪ\'liːs | rɪ\'lis/', 'release', 4);
