INSERT INTO `words` VALUES (22510, 'Relevant documents were presented in court.', 'adj. 有关的，切题的，中肯的', '/ˈreləvənt | \'rɛləvənt/', 'relevant', 4);
INSERT INTO `words` VALUES (22511, 'a birth control method that is cheap and reliable', 'adj. 可靠的，可信赖的', '/ri\'laiəbl | rɪ\'laɪəb(ə)l | rɪ\'laɪəbl/', 'reliable', 4);
INSERT INTO `words` VALUES (22512, 'the country’s heavy reliance on trade', 'n. 依靠， 依赖', '/rɪ\'laɪəns/', 'reliance', 4);
INSERT INTO `words` VALUES (22513, 'Marijuana can provide pain relief for some cancer patients.', 'n. 减轻；救济', '/rɪ\'liːf | rɪ\'lif/', 'relief', 4);
INSERT INTO `words` VALUES (22514, 'Drugs helped to relieve the pain.', 'vt. 救济； 缓解', '/rɪ\'liːv | rɪ\'liv/', 'relieve', 4);
