INSERT INTO `words` VALUES (22522, 'She has made remarkable progress.', 'adj. 不平常的；出色的', '/ri\'mɑ:kəbl | rɪ\'mɑːkəb(ə)l | rɪ\'mɑrkəbl/', 'remarkable', 4);
INSERT INTO `words` VALUES (22523, 'The problems in our schools do not have a simple remedy.', 'n. 治疗，补救；纠正', '/\'remidi | \'remɪdɪ | \'rɛmədi/', 'remedy', 4);
INSERT INTO `words` VALUES (22524, 'Yes, I’ll be there. Thanks for reminding me.', 'v. 提醒', '/ri\'maind | rɪ\'maɪnd/', 'remind', 4);
