INSERT INTO `words` VALUES (22528, 'a remote border town', 'adj. 远的， 长久的； 遥远的， 偏僻的； 远程的； 关系疏远的， 脱离的； 绝少的， 微乎其微的； 孤高的， 冷淡的', '/rɪ\'məut | rɪ\'mot/', 'remote', 4);
INSERT INTO `words` VALUES (22529, 'stain removal', 'n. 除去； 免职； 搬迁', '/rɪ\'muːvl | rɪ\'muvl/', 'removal', 4);
INSERT INTO `words` VALUES (22530, 'a cleaner that will remove wine stains', 'vt. 排除，消除；搬迁，移动；开除，解除; n. 距离， 间距', '/rɪ\'muːv | rɪ\'muv/', 'remove', 4);
INSERT INTO `words` VALUES (22531, 'high rates of remuneration', 'n. 报酬', '/rɪˌmjuːnə\'reɪʃn | rɪ,mjunə\'reʃən/', 'remuneration', 4);
INSERT INTO `words` VALUES (22532, '...the Renaissance masterpieces in London\'s galleries.', 'n. 文艺复兴；复兴，勃发', '/\'rɛnəsɑns | rɪ\'neɪsəns/', 'renaissance', 4);
INSERT INTO `words` VALUES (22533, 'an obligation to render assistance to those in need', 'v. 提供，报答；表演，演奏；翻译', '/\'rendə | \'rɛndɚ/', 'render', 4);
INSERT INTO `words` VALUES (22534, 'plans for a secret rendezvous', 'n. 约会；集会，聚会之地点', '/\'rɔndivu:, -dei- | \'rɒndɪvuː; -deɪvuː | \'rɑndevʊ/', 'rendezvous', 4);
INSERT INTO `words` VALUES (22535, 'He gave a moving rendition of Lennon’s ‘Imagine’.', 'n. 表演， 扮演， 演唱； 翻译； 视觉再现', '/ren\'dɪʃn | rɛn\'dɪʃən/', 'rendition', 4);
INSERT INTO `words` VALUES (22536, 'Local people have renewed their efforts to save the school.', 'v. 重新开始； 恢复； 更换， 更新； 续借', '/rɪ\'njuː | rɪ\'nʊ/', 'renew', 4);
INSERT INTO `words` VALUES (22537, 'It’s a six-month lease but it’s renewable.', 'adj. 可更新的， 可再生的， 可恢复的； 可延长有效期的， 可续期的', '/rɪ\'njuːəbl | rɪ\'nuəbl/', 'renewable', 4);
INSERT INTO `words` VALUES (22538, 'Mark’s contract comes up for renewal at the end of this year.', 'n. 更新， 恢复； 重新开始； 重建； 复兴； 续期； 重申', '/rɪ\'njuːəl | rɪ\'nuəl/', 'renewal', 4);
INSERT INTO `words` VALUES (22539, NULL, 'n. 修理，恢复', '/,renəu\'veiʃən | ,renə\'veɪʃn | ,rɛnə\'veʃən/', 'renovation', 4);
INSERT INTO `words` VALUES (22540, 'The area is renowned for its Romanesque churches.', 'adj. 有名望的，声誉鹊起的', '/ri\'naund | rɪ\'naʊnd/', 'renowned', 4);
INSERT INTO `words` VALUES (22541, 'Most students rent rooms in their second year.', 'v. 租借；出租; n. 租金', '/rent | rɛnt/', 'rent', 4);
INSERT INTO `words` VALUES (22542, 'A friend drove her to Atlanta, where she picked up a rental car.', 'adj. 租用的； 出租的; n. 租金额；出租，租赁', '/\'rentl | \'rɛntl/', 'rental', 4);
INSERT INTO `words` VALUES (22543, NULL, 'vt. 重新定方位； 重新定位； 使适应', '/ˌriː\'ɔːrient | ,ri\'ɔrɪɛnt/', 'reorient', 4);
INSERT INTO `words` VALUES (22544, NULL, 'vt. 重新包装； 重新填塞； 再装配； 拆修', '/ri:\'pæk | rɪ\'pæk/', 'repack', 4);
INSERT INTO `words` VALUES (22545, 'They hired a small company to repaint the dining room.', 'v. 重新油漆， 重画', '/ri:\'peint, \'ri:peint | rɪ\'peɪnt/', 'repaint', 4);
INSERT INTO `words` VALUES (22546, 'After the war, prisoners were repatriated.', 'v. 遣返；返回', '/ri:\'pætrieit, -\'pei- | riː\'pætrɪeɪt; -\'peɪ- | ,ri\'petrɪet/', 'repatriate', 4);
INSERT INTO `words` VALUES (22547, 'I’d like to buy them something to repay all their kindness.', 'v. 归还； 报答', '/ri\'peɪ | ri\'pɛi/', 'repay', 4);
INSERT INTO `words` VALUES (22548, 'The smell repelled him.', 'v. 击退；使厌恶', '/ri\'pel | rɪ\'pel | rɪ\'pɛl/', 'repel', 4);
INSERT INTO `words` VALUES (22549, 'Those who refuse to repent, he said, will be punished.', 'vi&vt. 悔悟，后悔', '/ri\'pent | rɪ\'pent | rɪ\'pɛnt/', 'repent', 4);
INSERT INTO `words` VALUES (22550, 'the behavioural repertoire of infants', 'n. 全部剧目，全部节目', '/\'repətwɑ: | \'repətwɑː | \'rɛpɚ\'twɑr/', 'repertoire', 4);
INSERT INTO `words` VALUES (22551, 'Children used to learn by repetition.', 'n. 重复', '/,repi\'tiʃən | repɪ\'tɪʃ(ə)n | \'rɛpə\'tɪʃən/', 'repetition', 4);
INSERT INTO `words` VALUES (22552, 'I’m replacing Sue on the team.', 'vt. 代替； 更换； 把…放回原处', '/rɪ\'pleɪs | rɪ\'ples/', 'replace', 4);
INSERT INTO `words` VALUES (22553, 'More vaccines are needed to replenish our stocks.', 'vt. 再斟满； 添加， 补充', '/rɪ\'plenɪʃ | rɪ\'plɛnɪʃ/', 'replenish', 4);
INSERT INTO `words` VALUES (22554, 'There is a need for further research to replicate these findings.', 'vt. 重复， 复现或复制； 再制造； 再生', '/\'replɪkɪt | \'rɛplɪket/', 'replicate', 4);
INSERT INTO `words` VALUES (22555, 'Mr Kobayashi was chosen to represent the company at the conference.', 'v. 代表；声称', '/,repri\'zent | reprɪ\'zent | ,rɛprɪ\'zɛnt/', 'represent', 4);
INSERT INTO `words` VALUES (22556, 'The pollsters asked a representative sample of New York residents for their opinions.', 'adj. 典型的， 有代表性的; n. 代表，代理人', '/ˌreprɪ\'zentətɪv | \'rɛprɪ\'zɛntətɪv/', 'representative', 4);
INSERT INTO `words` VALUES (22557, '‘You don’t need me,’ she said quietly, without reproach.', 'vt&n. 责备，指责', '/ri\'prəutʃ | rɪ\'prəʊtʃ | rɪ\'protʃ/', 'reproach', 4);
INSERT INTO `words` VALUES (22558, 'The turtles return to the coast to reproduce.', 'v. 繁殖， 生育； 复制， 仿造， 翻版； 再现， 使…在脑海中重现', '/ˌriːprə\'djuːs | ,riprə\'dus/', 'reproduce', 4);
INSERT INTO `words` VALUES (22559, 'Bird evolved from reptiles, so the first bird must have come out of an egg--laid by a reptile.', 'n. 爬行动物；爬虫', '/\'reptail, -til | \'reptaɪl | \'rɛptaɪl/', 'reptile', 4);
INSERT INTO `words` VALUES (22560, 'You are well advised to buy your car through a reputable dealer.', 'adj. 名声好的， 高尚的； 受尊敬的； 值得信赖的', '/\'repjətəbl | \'rɛpjətəbl/', 'reputable', 4);
INSERT INTO `words` VALUES (22561, 'Alice Munro has a reputation for being a very depressing writer.', 'n. 名誉，名声', '/,repju\'teiʃən | repjʊ\'teɪʃ(ə)n | ,rɛpju\'teʃən/', 'reputation', 4);
INSERT INTO `words` VALUES (22562, 'To request more information, please call our toll free number.', 'n&vt. 要求；请求', '/ri\'kwest | rɪ\'kwest | rɪ\'kwɛst/', 'request', 4);
INSERT INTO `words` VALUES (22563, 'Campbell’s broken leg will probably require surgery.', 'vt. 需要； 命令； 规定， 要求', '/rɪ\'kwaɪə(r) | rɪ\'kwaɪr/', 'require', 4);
INSERT INTO `words` VALUES (22564, 'The refugees’ main requirements are food and shelter.', 'n. 需要， 需求， 要求； 需要的东西； 必要条件', '/rɪ\'kwaɪəmənt | rɪ\'kwaɪɚmənt/', 'requirement', 4);
INSERT INTO `words` VALUES (22565, 'He lacks the requisite qualifications.', 'adj. 需要的；必要的; n. 必需品； 要素', '/\'rekwɪzɪt | \'rɛkwəzɪt/', 'requisite', 4);
INSERT INTO `words` VALUES (22566, 'The building was requisitioned as a military hospital for the duration of the war.', 'n&vt. 正式要求； 征用', '/ˌrekwɪ\'zɪʃn | \'rɛkwə\'zɪʃən/', 'requisition', 4);
INSERT INTO `words` VALUES (22567, 'Survivors of the crash were rescued by helicopter.', 'vt&n. 援救；营救', '/\'reskju: | \'reskjuː | \'rɛskju/', 'rescue', 4);
INSERT INTO `words` VALUES (22568, 'There was a remarkable resemblance between him and Pete.', 'n. 相似，类似', '/ri\'zembləns | rɪ\'zembl(ə)ns | rɪ\'zɛmbləns/', 'resemblance', 4);
INSERT INTO `words` VALUES (22569, 'It’s amazing how closely Brian and Steve resemble each other.', 'v. 类似，像', '/ri\'zembl | rɪ\'zemb(ə)l | rɪ\'zɛmbl/', 'resemble', 4);
INSERT INTO `words` VALUES (22570, 'Paul resented the fact that Carol didn’t trust him.', 'v. 怨恨', '/ri\'zent | rɪ\'zent | rɪ\'zɛnt/', 'resent', 4);
INSERT INTO `words` VALUES (22571, 'a dinner reservation', 'n. 保留意见， 存疑； 预定， 预订', '/ˌrezə\'veɪʃn | ,rɛzɚ\'veʃən/', 'reservation', 4);
INSERT INTO `words` VALUES (22572, 'Do you have to reserve tickets in advance?', 'n&vt. 保存；预定', '/rɪ\'zɜːv | rɪ\'zɝv/', 'reserve', 4);
INSERT INTO `words` VALUES (22573, 'Seats, or sometimes entire tables, were reserved.', 'adj. 说话不多的， 内向的； 有所保留的， 预订的', '/rɪ\'zɜːvd | rɪ\'zɝvd/', 'reserved', 4);
INSERT INTO `words` VALUES (22574, 'All these earthquakes happened when the water level in Zipingpu reservoir was low.', 'n. 水库；蓄水池', '/\'rezəvwɑ: | \'rezəvwɑ: (r) | \'rɛzɚ,vɔr/', 'reservoir', 4);
INSERT INTO `words` VALUES (22575, 'the ambassador’s official residence', 'n. 居住；住处；住宅', '/\'rezidəns | \'rezɪd(ə)ns | \'rɛzɪdəns/', 'residence', 4);
INSERT INTO `words` VALUES (22576, 'a resident tutor', 'adj. 常驻的， 居住的; n. 居民，住户', '/\'rezɪdənt | \'rɛzɪdənt/', 'resident', 4);
INSERT INTO `words` VALUES (22577, 'a quiet residential neighbourhood', 'adj. 居住的， 住宅的； 寄宿的', '/ˌrezɪ\'denʃl | ,rɛzɪ\'dɛnʃl/', 'residential', 4);
INSERT INTO `words` VALUES (22578, 'A hospital administrator has resigned over claims he lied to get the job.', 'v. 放弃；辞去', '/ri\'zain | rɪ\'zaɪn/', 'resign', 4);
INSERT INTO `words` VALUES (22579, 'She gave a sigh of resignation.', 'n. 辞职书；放弃；听从，顺从', '/,reziɡ\'neiʃən | rezɪg\'neɪʃ(ə)n | ,rɛzɪɡ\'neʃən/', 'resignation', 4);
INSERT INTO `words` VALUES (22580, 'And I think what we\'re seeing in the economy now is the inherent resilience of the American economy and the American people.', 'n. 回弹，弹性', '/ri\'ziliəns, -jəns | rɪ\'zɪlɪəns | rɪˈzɪliəns/', 'resilience', 4);
INSERT INTO `words` VALUES (22581, 'He resisted pressure to resign.', 'v. 抵抗； 抗； 耐', '/rɪ\'zɪst/', 'resist', 4);
INSERT INTO `words` VALUES (22582, 'disease resistance', 'n. 反抗， 抵制； 抵抗力， 抵抗性； 阻力； 电阻', '/rɪ\'zɪstəns/', 'resistance', 4);
INSERT INTO `words` VALUES (22583, 'Some people are very resistant to the idea of exercise.', 'adj. 抵抗的， 有抵抗力的', '/rɪ\'zɪstənt/', 'resistant', 4);
INSERT INTO `words` VALUES (22584, 'Those who fail can resit the exam in 60 days.', 'v&n. 重修， 补考', '/ˌrɪː\'sɪt | ˈriːsɪt/', 'resit', 4);
INSERT INTO `words` VALUES (22585, 'a resolution calling for a ban on dumping nuclear waste', 'n. 坚决，坚定；决定，决议；决心，解决', '/,rezə\'lu:ʃən, -,lju:- | rezə\'luːʃ(ə)n | ,rɛzə\'luʃən/', 'resolution', 4);
INSERT INTO `words` VALUES (22586, 'Barnet was desperate for money to resolve his financial problems.', 'v. 解决；决定', '/ri\'zɔlv | rɪ\'zɒlv | rɪ\'zɑlv/', 'resolve', 4);
INSERT INTO `words` VALUES (22587, 'the violin’s smooth, resonant tone', 'adj. 反响的；共鸣的', '/\'rezənənt | \'rez(ə)nənt | \'rɛznənt/', 'resonant', 4);
INSERT INTO `words` VALUES (22588, 'His punishing work schedule had made him resort to drugs.', 'vi&n. 求助', '/ri\'zɔ:t | rɪ\'zɔːt | rɪ\'zɔrt/', 'resort', 4);
INSERT INTO `words` VALUES (22589, 'Canada’s vast mineral resources', 'n. 资源；机智', '/ri\'sɔ:s, -\'zɔ:s, \'ri:s-, \'ri:z- | rɪ\'sɔːs; rɪ\'zɔːs | \'risɔrs/', 'resource', 4);
INSERT INTO `words` VALUES (22590, 'I respect his views, although I do not agree with them.', 'vt. 尊敬; n. 尊敬； 方面', '/rɪ\'spekt | rɪ\'spɛkt/', 'respect', 4);
INSERT INTO `words` VALUES (22591, 'His respiration grew fainter throughout the day.', 'n. 呼吸作用；一次呼吸；植物光合作用', '/,respə\'reiʃən | respɪ\'reɪʃ(ə)n | ,rɛspə\'reʃən/', 'respiration', 4);
INSERT INTO `words` VALUES (22592, 'They are likely to respond positively to the president\'s request for aid.', 'vi. 回答， 答复； 响应； 作出反应', '/rɪ\'spɒnd | rɪ\'spɑnd/', 'respond', 4);
INSERT INTO `words` VALUES (22593, 'Only 62 percent of respondents said they were satisfied.', 'n. 回答者， 响应者； 调查对象； 被告', '/rɪ\'spɒndənt | rɪ\'spɑndənt/', 'respondent', 4);
INSERT INTO `words` VALUES (22594, 'His immediate response was one of disbelief.', 'n. 回答， 答复； 反应， 响应', '/rɪ\'spɒns | rɪ\'spɑns/', 'response', 4);
INSERT INTO `words` VALUES (22595, 'Kelly’s promotion means more money and more responsibility.', 'n. 责任， 责任心； 职责， 任务', '/rɪˌspɒnsə\'bɪləti | rɪˌspɑːnsəˈbɪləti/', 'responsibility', 4);
INSERT INTO `words` VALUES (22596, 'We are determined to bring the people responsible to justice.', 'adj. 有责任感的； 可靠的', '/rɪ\'spɒnsəbl | rɪ\'spɑnsəbl/', 'responsible', 4);
INSERT INTO `words` VALUES (22597, 'With an election coming soon, your representative should be very responsive to your request.', 'adj. 易于做出迅速反应的', '/ri\'spɔnsiv | rɪ\'spɒnsɪv | rɪ\'spɑnsɪv/', 'responsive', 4);
INSERT INTO `words` VALUES (22598, 'After a few weeks in Marseille, I grew restless and decided to move on.', 'adj. 焦躁不安的', '/\'restlis | ˈrestləs | \'rɛstləs/', 'restless', 4);
INSERT INTO `words` VALUES (22599, 'She was hoping that the Mediterranean climate would restore her to full health.', 'v. 恢复；归还', '/ri\'stɔ: | rɪ\'stɔː | rɪ\'stɔr/', 'restore', 4);
INSERT INTO `words` VALUES (22600, 'Wally gripped my arm, partly to restrain me and partly to reassure me.', 'v. 限制，约束', '/ri\'strein | rɪ\'streɪn | rɪ\'stren/', 'restrain', 4);
INSERT INTO `words` VALUES (22601, 'The new law restricts the sale of hand guns.', 'vt. 限制， 约束', '/rɪ\'strɪkt/', 'restrict', 4);
INSERT INTO `words` VALUES (22602, 'a 50 mph speed restriction', 'n. 限制， 约束', '/rɪ\'strɪkʃn | rɪ\'strɪkʃən/', 'restriction', 4);
INSERT INTO `words` VALUES (22603, 'She hopes to resume work after the baby is born.', 'v. 重新开始；继续；重新占用', '/rezju:\'mei, ri\'zju:m; -\'zu:m | rɪˈzjuːm; ˈrɛzjʊmeɪ/', 'resume', 4);
INSERT INTO `words` VALUES (22604, 'a retail price of £8.99', 'n&v. 零售，零卖', '/\'ri:teil | \'riːteɪl | \'ritel/', 'retail', 4);
INSERT INTO `words` VALUES (22605, 'Furniture and carpet retailers are among those reporting the sharpest annual decline in sales.', 'n. 零售商人； 复述者， 传播者', '/\'riːteɪlə(r) | \'ri:teilə/', 'retailer', 4);
INSERT INTO `words` VALUES (22606, 'There may be many job losses in retailing.', 'n. 零售业', '/\'riːteɪlɪŋ | \'ritelɪŋ/', 'retailing', 4);
INSERT INTO `words` VALUES (22607, 'You have the right to retain possession of the goods.', 'v. 保持，保有；聘请(律师)', '/ri\'tein | rɪ\'teɪn | rɪ\'ten/', 'retain', 4);
INSERT INTO `words` VALUES (22608, 'I was sorely tempted to retaliate.', 'vi. 报复， 反击； 复仇', '/rɪ\'tælieɪt | rɪ\'tælɪ\'et/', 'retaliate', 4);
INSERT INTO `words` VALUES (22609, 'She is so reticent about her achievements.', 'adj. 沉默寡言的；言不如意的', '/\'retisənt | \'retɪs(ə)nt | \'rɛtɪsnt/', 'reticent', 4);
INSERT INTO `words` VALUES (22610, 'At the age when most people retire, he is ready to face a new career.', 'v. 退休； 引退， 退隐， 撤退', '/rɪ\'taɪə(r) | rɪ\'taɪɚ/', 'retire', 4);
INSERT INTO `words` VALUES (22611, '‘It’s all your fault!’ he retorted.', 'v&n. 反驳，反击', '/ri\'tɔ:t | rɪ\'tɔːt | rɪ\'tɔrt/', 'retort', 4);
INSERT INTO `words` VALUES (22612, 'The rebels retreated to the mountains.', 'vi&n. 撤退', '/ri\'tri:t | rɪ\'triːt | rɪ\'trit/', 'retreat', 4);
INSERT INTO `words` VALUES (22613, 'Defence planners predict an extended period of retrenchment.', 'n. 节省； 削减', '/rɪ\'trentʃmənt | ri\'trɛntʃmənt/', 'retrenchment', 4);
INSERT INTO `words` VALUES (22614, 'The general made one last desperate effort to retrieve the situation.', 'vt&vi. 再获得；挽回；挽救', '/ri\'tri:v | rɪ\'triːv | rɪ\'triv/', 'retrieve', 4);
INSERT INTO `words` VALUES (22615, 'In retrospect, I wonder if we should have done more.', 'n. 回顾；回想', '/\'retrəuspekt | \'retrəspekt | \'rɛtrəspɛkt/', 'retrospect', 4);
INSERT INTO `words` VALUES (22616, 'an annual reunion', 'n. 重聚， 团聚； 聚会， 联谊活动', '/riː\'juːniən/', 'reunion', 4);
INSERT INTO `words` VALUES (22617, 'The band will reunite for a US tour.', 'v. 结合； 重聚', '/ˌriːjuː\'naɪt | ,riju\'naɪt/', 'reunite', 4);
INSERT INTO `words` VALUES (22618, 'He may be prosecuted for revealing secrets about the security agency.', 'vt. 揭露； 泄露； 展现', '/rɪ\'viːl | rɪ\'vil/', 'reveal', 4);
INSERT INTO `words` VALUES (22619, NULL, 'v. 再生长， 再植', '/ri:\'vedʒiteit | riː\'vedʒəteɪt/', 'revegetate', 4);
INSERT INTO `words` VALUES (22620, '...following the revelation of his affair with a former secretary.', 'n. 揭示，揭露', '/,revə\'leiʃən | revə\'leɪʃ(ə)n | \'rɛvə\'leʃən/', 'revelation', 4);
INSERT INTO `words` VALUES (22621, 'The poor murdered girl must be revenged.', 'v. 报复，报仇', '/ri\'vendʒ | rɪ\'ven(d)ʒ | rɪ\'vɛndʒ/', 'revenge', 4);
INSERT INTO `words` VALUES (22622, 'advertising revenue', 'n. (国家的)年收入；税收', '/\'revənju:, -nu: | \'revənjuː | \'rɛvənu/', 'revenue', 4);
INSERT INTO `words` VALUES (22623, 'a hushed reverent voice', 'adj. 恭敬的，虔诚的', '/\'revərənt | \'rev(ə)r(ə)nt | \'rɛvərənt/', 'reverent', 4);
INSERT INTO `words` VALUES (22624, 'I owe you nothing. If anything, the reverse is true (= you owe me ) .', 'n&v&a. 相反(的)；颠倒(的)', '/ri\'və:s | rɪ\'vɜːs | rɪ\'vɝs/', 'reverse', 4);
INSERT INTO `words` VALUES (22625, 'The policy comes up for review (= will be reviewed ) in April.', 'v&n. 回顾；检查；评论', '/ri\'vju: | rɪ\'vjuː | rɪ\'vju/', 'review', 4);
INSERT INTO `words` VALUES (22626, 'The college has revised its plans because of local objections.', 'v. 修订；改正', '/ri\'vaiz, \'ri:vaiz | rɪ\'vaɪz/', 'revise', 4);
INSERT INTO `words` VALUES (22627, 'The US and the UK have expectations of economic revival.', 'n. 恢复， 复原； 苏醒， 复活； 复兴； 重新使用； 重新流行', '/rɪ\'vaɪvl/', 'revival', 4);
INSERT INTO `words` VALUES (22628, '...an attempt to revive the economy.', 'v. 苏醒，复活；复兴，再流行', '/ri\'vaiv | rɪ\'vaɪv/', 'revive', 4);
INSERT INTO `words` VALUES (22629, 'The prime minister is now facing a revolt by members of his own party.', 'v&n. 反抗；厌恶', '/ri\'vəult, -\'vɔ:lt | rɪ\'vəʊlt | rɪ\'volt/', 'revolt', 4);
INSERT INTO `words` VALUES (22630, 'the French Revolution of 1789', 'n. 革命； 巨变， 大变革', '/ˌrevə\'luːʃn | \'rɛvə\'lʊʃən/', 'revolution', 4);
INSERT INTO `words` VALUES (22631, 'The wheel began to revolve.', 'vt&vi. 使旋转；使绕转', '/ri\'vɔlv, -\'vɔ:lv | rɪ\'vɒlv | rɪ\'vɔlv/', 'revolve', 4);
INSERT INTO `words` VALUES (22632, 'The school has a system of rewards and punishments to encourage good behaviour.', 'n&v. 奖赏', '/ri\'wɔ:d | rɪ\'wɔːd | rɪ\'wɔrd/', 'reward', 4);
INSERT INTO `words` VALUES (22633, '...the noble institutions of political life, such as political rhetoric, public office, and public service.', 'n. 修辞学', '/\'retərik | \'retərɪk | \'rɛtərɪk/', 'rhetoric', 4);
INSERT INTO `words` VALUES (22634, 'Begin to listen to your own body rhythms.', 'n. 韵律，格律；有规律的反复(循环)，周期性', '/\'riðəm, \'riθəm | \'rɪð(ə)m | \'rɪðəm/', 'rhythm', 4);
INSERT INTO `words` VALUES (22635, 'little girls with ribbons in their hair', 'n. 缎带，丝带，带状物', '/\'ribən | \'rɪbən/', 'ribbon', 4);
INSERT INTO `words` VALUES (22636, 'We made our way carefully along the ridge.', 'n. 山脊，脊，岭', '/ridʒ | rɪdʒ/', 'ridge', 4);
INSERT INTO `words` VALUES (22637, 'That’s a ridiculous idea!', 'adj. 荒谬的，可笑的', '/ri\'dikjuləs | rɪ\'dɪkjʊləs | rɪ\'dɪkjələs/', 'ridiculous', 4);
INSERT INTO `words` VALUES (22638, 'The ship was fully rigged and ready to sail.', 'v. 给船装帆;为提供必要装备; n. 成套设备', '/riɡ | rɪg | rɪɡ/', 'rig', 4);
INSERT INTO `words` VALUES (22639, 'a righteous God', 'adj. 正直的，正当的，公正的', '/\'raitʃəs | \'raɪtʃəs/', 'righteous', 4);
INSERT INTO `words` VALUES (22640, 'rigid and authoritarian methods of education', 'adj. 僵硬的，不易弯的；严格的', '/\'ridʒid | \'rɪdʒɪd/', 'rigid', 4);
INSERT INTO `words` VALUES (22641, 'a rigorous analysis of defence needs', 'adj. 严格的，严厉的，严酷的(气候条件)', '/\'riɡərəs | \'rɪg(ə)rəs | \'rɪɡərəs/', 'rigorous', 4);
INSERT INTO `words` VALUES (22642, 'She looked at him over the rim of her glass.', 'n. 边；边缘，轮辋', '/rim | rɪm/', 'rim', 4);
