INSERT INTO `words` VALUES (23102, 'stringent anti-noise regulations', 'adj. 严格的， 苛刻的； 紧缩的， 短缺的， 银根紧的； 迫切的', '/\'strɪndʒənt/', 'stringent', 4);
INSERT INTO `words` VALUES (23103, 'Strip the beds and wash the sheets.', 'vt&vi. 剥去；除去；剥夺财产; n. 狭长一片', '/strip | strɪp/', 'strip', 4);
INSERT INTO `words` VALUES (23104, 'a shirt with black and white stripes', 'n. 条纹', '/straip | straɪp/', 'stripe', 4);
INSERT INTO `words` VALUES (23105, 'He strives hard to keep himself very fit.', 'v. 斗争，努力，奋斗', '/straiv | straɪv/', 'strive', 4);
INSERT INTO `words` VALUES (23106, 'She died following a massive stroke.', 'n. 击；划；一笔；中风', '/strəʊk | strok/', 'stroke', 4);
INSERT INTO `words` VALUES (23107, 'structural changes in the computer industry', 'adj. 结构的，构造的', '/\'strʌktʃərəl | \'strʌktʃ(ə)r(ə)l/', 'structural', 4);
INSERT INTO `words` VALUES (23108, 'challenges to the existing power structure', 'n. 结构；构造；建筑物; vt. 系统安排； 精心组织', '/\'strʌktʃə(r) | \'strʌktʃɚ/', 'structure', 4);
INSERT INTO `words` VALUES (23109, 'Why are you so stubborn?', 'adj. 顽固的，坚定的', '/\'stʌbən | \'stʌbɚn/', 'stubborn', 4);
INSERT INTO `words` VALUES (23110, 'a TV studio', 'n. 工作室；摄影棚；播音室', '/\'stju:diəu, \'stu:- | \'stjuːdɪəʊ | \'studɪo/', 'studio', 4);
INSERT INTO `words` VALUES (23111, 'a quiet, studious young man', 'adj. 好学的， 学习勤勉的； 专心的； 谨慎的， 认真的， 仔细的', '/\'stjuːdiəs | \'studɪəs/', 'studious', 4);
INSERT INTO `words` VALUES (23112, 'I’ve got some sticky stuff on my shoe.', 'n. 原料，材料；素质；东西; v. 把装满', '/stʌf/', 'stuff', 4);
INSERT INTO `words` VALUES (23113, 'sage and onion stuffing', 'n. 填料，填充物，填充剂', '/\'stʌfiŋ | \'stʌfɪŋ/', 'stuffing', 4);
INSERT INTO `words` VALUES (23114, 'It’s getting stuffy in here – do you mind if I open the window?', 'adj. 不透气的， 不新鲜的， 不通风的； 乏味的', '/\'stʌfi/', 'stuffy', 4);
INSERT INTO `words` VALUES (23115, 'In her hurry, she stumbled and spilled the milk all over the floor.', 'v. 绊跌，绊倒；结结巴巴说话', '/\'stʌmbl | \'stʌmb(ə)l/', 'stumble', 4);
INSERT INTO `words` VALUES (23116, 'Both Jacky Chan and Jet Li don\'t like to use stuntman in their films.', 'n. 替身演员', '/\'stʌntmæn/', 'stuntman', 4);
INSERT INTO `words` VALUES (23117, 'That chair doesn’t look very sturdy.', 'adj. 强健的，坚实的', '/\'stə:di | \'stɜːdɪ | \'stɝdi/', 'sturdy', 4);
INSERT INTO `words` VALUES (23118, 'an attempt to use Japanese management style in a European business', 'n. 风格；文体；式样', '/stail | staɪl/', 'style', 4);
INSERT INTO `words` VALUES (23119, 'a stylish woman in her forties', 'adj. 时髦的； 漂亮的', '/\'staɪlɪʃ/', 'stylish', 4);
INSERT INTO `words` VALUES (23120, 'Police managed to subdue the angry crowd.', 'v. 使屈服、征服，克制；使柔和，使安静', '/səb\'dju: | səb\'djuː | səb\'du/', 'subdue', 4);
INSERT INTO `words` VALUES (23121, 'Paul has strong opinions on most subjects.', 'n. 国民；主题; adj. 隶属的，受支配的; v. 征服', '/\'sʌbdʒikt, -dʒe-, səb\'dʒekt | ˈsʌbdʒɪkt | ˈsʌbdʒekt/', 'subject', 4);
INSERT INTO `words` VALUES (23122, 'As a critic, he is far too subjective.', 'adj. 主观的', '/səb\'dʒektiv | səb\'dʒektɪv | səb\'dʒɛktɪv/', 'subjective', 4);
INSERT INTO `words` VALUES (23123, 'a subliminal message', 'adj. 下意识的， 潜意识的', '/ˌsʌb\'lɪmɪnl | ,sʌb\'lɪmɪnl/', 'subliminal', 4);
INSERT INTO `words` VALUES (23124, 'The captain dived his submarine deep to escape from the destroyers.', 'adj. 水下的; n. 潜水艇', '/\'sʌbməri:n, ,sʌbmə\'ri:n | \'sʌbməriːn; sʌbmə\'riːn | ,sʌbmə\'rin/', 'submarine', 4);
INSERT INTO `words` VALUES (23125, 'Hippos are unable to submerge in the few remaining water holes.', 'v. 放于水下；使沉没', '/səb\'mə:dʒ | səb\'mɜːdʒ | səb\'mɝdʒ/', 'submerge', 4);
INSERT INTO `words` VALUES (23126, 'In desperation, Mrs. Jones submitted to an operation on her right knee to relieve the pain.', 'v. (使)服从；提交', '/səb\'mit | səb\'mɪt/', 'submit', 4);
INSERT INTO `words` VALUES (23127, 'a subordinate officer', 'adj. 下级的，次要的,从属的; n. 部下，下级职员', '/sə\'bɔ:dinət, -neit, sə\'bɔ:dineit | sə\'bɔːdɪnət | səˈbɔːdɪnɪt (for n. &adj.) ; səˈbɔːdɪˌnet (for v.)/', 'subordinate', 4);
INSERT INTO `words` VALUES (23128, 'My main reason for subscribing to New Scientist is to keep abreast of advances in science.', 'vt&vi. 捐款，捐助；订阅；同意，赞成', '/səb\'skraib | səb\'skraɪb/', 'subscribe', 4);
INSERT INTO `words` VALUES (23129, 'The church’s 120-foot Gothic spire was paid for by public subscription in 1939.', 'n. 订阅， 订购； 订阅费， 订购款； 捐赠， 捐助； 签字， 签署', '/səb\'skrɪpʃn | səb\'skrɪpʃən/', 'subscription', 4);
INSERT INTO `words` VALUES (23130, 'These skills were passed on to subsequent generations.', 'adj. 接着的，然后的', '/\'sʌbsikwənt | \'sʌbsɪkw(ə)nt | \'sʌbsɪkwənt/', 'subsequent', 4);
INSERT INTO `words` VALUES (23131, 'After the heavy rains, part of the road subsided.', 'v. 洪水退落；土地下沉；建筑物沉降', '/səb\'said | səb\'saɪd/', 'subside', 4);
INSERT INTO `words` VALUES (23132, 'a subsidiary hypothesis', 'adj. 辅助的；附属的; n. 子公司，附属机构', '/səb\'sidiəri | səb\'sɪdɪərɪ | səb\'sɪdɪɛri/', 'subsidiary', 4);
INSERT INTO `words` VALUES (23133, 'Now the questions are: why should northern European taxpayers be required to subsidise Greek voters given their failure to control their own government?', 'vt. 津贴， 资助', '/\'sʌbsɪdaɪz | \'sʌbsidaiz/', 'subsidise', 4);
INSERT INTO `words` VALUES (23134, 'European farmers are planning a massive demonstration against farm subsidy cuts.', 'n. 补助金；津贴费', '/\'sʌbsidi | \'sʌbsɪdɪ | \'sʌbsədi/', 'subsidy', 4);
INSERT INTO `words` VALUES (23135, '...the chalk subsoil on the site.', 'n. 底土， 下层土', '/\'sʌbsɔɪl | \'sʌb\'sɔɪl/', 'subsoil', 4);
INSERT INTO `words` VALUES (23136, 'The leaves were covered with a strange sticky substance.', 'n. 物质； 实质', '/\'sʌbstəns/', 'substance', 4);
INSERT INTO `words` VALUES (23137, 'We have the support of a substantial number of parents.', 'adj. 坚固的，巨大的；富有的', '/səb\'stænʃəl | səb\'stænʃ(ə)l | səbˈstænʃəl/', 'substantial', 4);
INSERT INTO `words` VALUES (23138, 'Katzen offered little evidence to substantiate his claims .', 'v. 证实；证明', '/səb\'stænʃieit | səb\'stænʃɪeɪt | səb\'stænʃɪet/', 'substantiate', 4);
INSERT INTO `words` VALUES (23139, 'Germany brought on a substitute at half time.', 'n. 代替人，代用品; v. 代替', '/\'sʌbstitju:t, -tu:t | \'sʌbstɪtjuːt | \'sʌbstɪtut/', 'substitute', 4);
INSERT INTO `words` VALUES (23140, 'Coach Ross made two substitutions in the second half.', 'n. 代替， 置换； 代入法', '/ˌsʌbstɪ\'tjuːʃn | ,sʌbstə\'tjʊʃən/', 'substitution', 4);
INSERT INTO `words` VALUES (23141, 'a French film with English subtitles', 'n. (书籍)副标题；译文字幕', '/\'sʌb,taitl | \'sʌbtaɪt(ə)l | \'sʌb\'taɪtl/', 'subtitle', 4);
INSERT INTO `words` VALUES (23142, 'The pictures are similar, but there are subtle differences between them.', 'adj. 微妙的；难以捉摸的；精明的', '/\'sʌtl | \'sʌt(ə)l/', 'subtle', 4);
INSERT INTO `words` VALUES (23143, 'The pupil could add and subtract but hadn\'t learned to divide.', 'v. 减去，扣除', '/səb\'trækt/', 'subtract', 4);
INSERT INTO `words` VALUES (23144, 'subtropical vegetation', 'adj. 亚热带的', '/ˌsʌb\'trɒpɪkl | ,sʌb\'trɑpɪkl/', 'subtropical', 4);
INSERT INTO `words` VALUES (23145, 'a London suburb', 'n. 郊区', '/\'sʌbɜːb | \'sʌbɝb/', 'suburb', 4);
INSERT INTO `words` VALUES (23146, 'She wanted to be the first woman to climb Mount Qomolangma, and she almost succeeded.', 'v. 成功； 接着发生', '/sək\'siːd | sək\'sid/', 'succeed', 4);
INSERT INTO `words` VALUES (23147, 'She won the championship four times in succession.', 'n. 连续；继续；一连串；继承权', '/sək\'seʃən | sək\'seʃ(ə)n | sək\'sɛʃən/', 'succession', 4);
INSERT INTO `words` VALUES (23148, 'The team has had five successive victories.', 'adj. 连续的', '/sək\'sesɪv | sək\'sɛsɪv/', 'successive', 4);
INSERT INTO `words` VALUES (23149, 'a succinct explanation', 'adj. 简明的，扼要的', '/sək\'siŋkt, sə\'s- | sək\'sɪŋ(k)t | sək\'sɪŋkt/', 'succinct', 4);
INSERT INTO `words` VALUES (23150, 'Don\'t succumb to the temptation to have just one cigarette.', 'v. 屈服，屈从，死', '/sə\'kʌm/', 'succumb', 4);
INSERT INTO `words` VALUES (23151, 'They waited in silence and sucked their sweets.', 'n&v. 吸，舔', '/sʌk/', 'suck', 4);
INSERT INTO `words` VALUES (23152, NULL, 'n. 吸盘； 吸根， 根出条', '/\'sʌkə(r) | \'sʌkɚ/', 'sucker', 4);
INSERT INTO `words` VALUES (23153, 'If the builders don’t fulfil their side of the contract, we’ll sue.', 'vt&vi. 控诉，控告；请求', '/sju:, su: | s(j)uː | su/', 'sue', 4);
INSERT INTO `words` VALUES (23154, 'At least he died suddenly and didn’t suffer.', 'v. 遭受， 忍受； 忍耐； 容许； 患病； 受损失', '/\'sʌfə(r) | \'sʌfɚ/', 'suffer', 4);
INSERT INTO `words` VALUES (23155, 'A light lunch will suffice .', 'v. 满足， 满意； 足够', '/sə\'faɪs/', 'suffice', 4);
INSERT INTO `words` VALUES (23156, 'We can only prosecute if there is sufficient evidence.', 'adj. 足够的，充分的', '/sə\'fiʃənt | sə\'fɪʃ(ə)nt | səˈfɪʃənt/', 'sufficient', 4);
INSERT INTO `words` VALUES (23157, 'The zoo asked its visitors to suggest a name for the new baby panda.', 'v. 建议， 提出； 暗示', '/sə\'dʒest | sə\'dʒɛst/', 'suggest', 4);
INSERT INTO `words` VALUES (23158, 'She was depressed and almost suicidal.', 'adj. 自杀的； 有自杀倾向的', '/sʊːɪ\'saɪdl | \'sʊə\'saɪdl/', 'suicidal', 4);
INSERT INTO `words` VALUES (23159, 'More people commit suicide at Christmas than at any other time.', 'n. 自杀', '/\'sjuisaid | \'s(j)uːɪsaɪd | \'suɪsaɪd/', 'suicide', 4);
INSERT INTO `words` VALUES (23160, 'We are hoping to find a suitable school.', 'adj. 适当的， 相配的； 合适的， 适宜的', '/\'suːtəbl | \'sutəbl/', 'suitable', 4);
INSERT INTO `words` VALUES (23161, 'It did not take Andrew long to pack a suitcase.', 'n. 衣箱', '/\'sju:tkeis | \'suːtkeɪs | \'sutkes/', 'suitcase', 4);
INSERT INTO `words` VALUES (23162, 'a honeymoon suite', 'n. 一套家具，一套房间，酒店套房', '/swi:t | swiːt | sut; swit/', 'suite', 4);
INSERT INTO `words` VALUES (23163, 'Burning sulphur creates poisonous fumes.', 'n. (化学)硫', '/\'sʌlfə/', 'sulphur', 4);
INSERT INTO `words` VALUES (23164, 'In the below we summarise annual World Steel Association crude steel production data.', 'v. 总结， 概括', '/\'sʌməraɪz | \'sʌməraiz/', 'summarise', 4);
INSERT INTO `words` VALUES (23165, 'A brief summary is given on a separate sheet.', 'n. 摘要，概要; adj. 概括的；即时的', '/\'sʌm(ə)rɪ | \'sʌməri/', 'summary', 4);
INSERT INTO `words` VALUES (23166, 'But are these the summit of our values, of our aspirations of society?', 'n. 顶点，高峰；峰会(最高级会谈)', '/\'sʌmit | \'sʌmɪt/', 'summit', 4);
INSERT INTO `words` VALUES (23167, 'Robert summoned the waiter for the bill.', 'v. 召唤，传唤；鼓起，聚集', '/\'sʌmən/', 'summon', 4);
INSERT INTO `words` VALUES (23168, 'The shadow on this sundial showed the time to the minute precisely!', 'n. 日规； 日晷', '/\'sʌndaɪəl | \'sʌn\'daɪəl/', 'sundial', 4);
INSERT INTO `words` VALUES (23169, 'The food was superb.', 'adj. 壮丽的，头等的', '/sju\'pə:b, sə- | suː\'pɜːb; sjuː- | /suːˈpɜːrb//', 'superb', 4);
INSERT INTO `words` VALUES (23170, 'They only have the most superficial understanding of prison life.', 'adj. 表面的；表皮的；肤浅的，一知半解的', '/,suːpə\'fɪʃ(ə)l; ,sjuː- | ,supɚ\'fɪʃl/', 'superficial', 4);
INSERT INTO `words` VALUES (23171, 'a modern building with no superfluous decoration', 'adj. 过剩的，多余的，不必要的', '/sju\'pə:fluəs | suː\'pɜːflʊəs; sjuː- | sʊ\'pɝflʊəs/', 'superfluous', 4);
INSERT INTO `words` VALUES (23172, 'Meese was to superintend the administration\'s entire domestic policy.', 'vt&vi. 监督，指挥(工作)', '/,sju:pərin\'tend | suːp(ə)rɪn\'tend; sjuː- | ,supərɪn\'tɛnd/', 'superintend', 4);
INSERT INTO `words` VALUES (23173, 'She had that superior tone of voice.', 'adj. 优越的；优良的，较高的', '/sju:\'piriə, sju:pə- | suːˈpɪərɪə | səˈpɪriər/', 'superior', 4);
INSERT INTO `words` VALUES (23174, 'Their map has since been superseded by photographic atlases.', 'v. 代替', '/,sju:pə\'si:d | ,suːpə\'siːd; ,sjuː- | ,supɚ\'sid/', 'supersede', 4);
INSERT INTO `words` VALUES (23175, 'supersonic aircraft', 'adj. 超声的，超声速的', '/,sju:pə\'sɔnik | suːpə\'sɒnɪk; sjuː- | ,supɚ\'sɑnɪk/', 'supersonic', 4);
INSERT INTO `words` VALUES (23176, 'the old superstition that walking under a ladder is unlucky', 'n. 迷信，迷信行为', '/,sju:pə\'stiʃən | ,suːpə\'stɪʃ(ə)n; ,sjuː- | ,supɚ\'stɪʃən/', 'superstition', 4);
INSERT INTO `words` VALUES (23177, 'a superstitious woman', 'adj. 迷信的； 根据迷信的， 由迷信引起的； 受迷信思想支配的', '/ˌsuːpə\'stɪʃəs | \'sʊpɚ\'stɪʃəs/', 'superstitious', 4);
INSERT INTO `words` VALUES (23178, 'the whole superstructure of capitalism', 'n. 上层建筑；统治阶层', '/\'sju:pə,strʌktʃə | \'suːpəstrʌktʃə; \'sjuː- | \'supɚstrʌktʃɚ/', 'superstructure', 4);
INSERT INTO `words` VALUES (23179, 'Griffiths closely supervised the research.', 'vt&vi. 监督，管理，指导', '/\'sju:pəvaiz | \'suːpəvaɪz; \'sjuː- | \'sʊpɚ\'vaɪz/', 'supervise', 4);
INSERT INTO `words` VALUES (23180, 'The baby needs constant supervision.', 'n. 监督， 管理； 指导', '/ˌsʊːpə\'vɪʒn | ,sʊpɚ\'vɪʒən/', 'supervision', 4);
INSERT INTO `words` VALUES (23181, '...a full-time job as a supervisor at a factory.', 'n. 监督人， 管理人， 指导者； 主管', '/\'suːpəvaɪzə(r) | \'supɚvaɪzɚ/', 'supervisor', 4);
INSERT INTO `words` VALUES (23182, '...people doing extra jobs outside their regular jobs to supplement their incomes.', 'vt. 补充，增补[\'sʌplɪmənt]; n. 增补， 补充； 补遗； 增刊； 附录', '/\'sʌplɪment | \'sʌplɪmənt/', 'supplement', 4);
INSERT INTO `words` VALUES (23183, 'supplementary information', 'adj. 补充的，附加的', '/,sʌpli\'mentəri | ,sʌplɪ\'ment(ə)rɪ | ,sʌplɪ\'mɛntri/', 'supplementary', 4);
INSERT INTO `words` VALUES (23184, 'The nation’s fuel supplies will not last forever.', 'n. 供给，供应；; vt. 供给， 供应； 满足， 弥补', '/sə\'plaɪ/', 'supply', 4);
INSERT INTO `words` VALUES (23185, 'My family were very supportive throughout the divorce.', 'adj. 支持的， 支援的； 赞助的； 鼓励的； 同情的', '/sə\'pɔːtɪv | sə\'pɔrtɪv/', 'supportive', 4);
INSERT INTO `words` VALUES (23186, 'There were many more deaths than was first supposed.', 'v. 假想， 假定， 猜想， 推测； [用于祈使句]假定， 让； [常用于被动语态]期望做， 认为应该做', '/sə\'pəuz | sə\'poz/', 'suppose', 4);
INSERT INTO `words` VALUES (23187, NULL, 'adv. 想象上，恐怕', '/sə\'pəuzidli | sə\'pəʊzɪdlɪ | sə\'pozɪdli/', 'supposedly', 4);
INSERT INTO `words` VALUES (23188, 'His version of events is pure supposition .', 'n. 假定，想象，猜测', '/,sʌpə\'ziʃən | ,sʌpə\'zɪʃ(ə)n | ,sʌpə\'zɪʃən/', 'supposition', 4);
INSERT INTO `words` VALUES (23189, 'The uprising was ruthlessly suppressed.', 'v. 镇压；平定；抑制；隐瞒', '/sə\'pres | sə\'prɛs/', 'suppress', 4);
INSERT INTO `words` VALUES (23190, NULL, 'n. 镇压， 压制， 抑制； 扑灭', '/sə\'preʃn | sə\'prɛʃən/', 'suppression', 4);
INSERT INTO `words` VALUES (23191, 'the Supreme Allied Commander in Europe', 'adj. 最高的；最大的，最重要的', '/sju\'pri:m, sə- | suː\'priːm | suˈprim/', 'supreme', 4);
INSERT INTO `words` VALUES (23192, NULL, 'n. 额外费用，过高的要价', '/sə:\'tʃɑ:dʒ, \'sə:tʃ- | \'sɜːtʃɑːdʒ | \'sɝtʃɑrdʒ/', 'surcharge', 4);
INSERT INTO `words` VALUES (23193, 'I\'m going to buy a surfboard and learn to surf.', 'v. 冲浪', '/sɜːf | sɝf/', 'surf', 4);
INSERT INTO `words` VALUES (23194, 'Last year Toole surfaced again in Cuba.', 'v. 浮出水面； 浮现， 显露； 在…上加表面; n. 表面；外表，外观', '/\'sɜːfɪs | \'sɝfɪs/', 'surface', 4);
INSERT INTO `words` VALUES (23195, 'A wave surged up towards them.', 'v. 波动，汹涌，澎湃', '/sɜːdʒ | sɝdʒ/', 'surge', 4);
INSERT INTO `words` VALUES (23196, '...a heart surgeon.', 'n. 外科医生', '/\'sə:dʒən | \'sɜːdʒ(ə)n | \'sɝdʒən/', 'surgeon', 4);
INSERT INTO `words` VALUES (23197, 'Dr. Hanson is in surgery.', 'n. 外科，外科手术', '/\'sə:dʒəri | \'sɜːdʒ(ə)rɪ | \'sɝdʒəri/', 'surgery', 4);
INSERT INTO `words` VALUES (23198, 'He has had to surmount immense physical disabilities.', 'v. 克服，越过', '/sə:\'maunt | sə\'maʊnt | sɚ\'maʊnt/', 'surmount', 4);
INSERT INTO `words` VALUES (23199, 'He had surpassed all our expectations .', 'v. 超过，超越，胜过', '/sə\'pɑ:s, -\'pæs | sə\'pɑːs | sə\'pæs/', 'surpass', 4);
INSERT INTO `words` VALUES (23200, 'Any surplus can be trimmed away.', 'n. 余款，盈余；过剩，剩余)', '/\'sə:plʌs, -pləs | \'sɜːpləs | \'sɝpləs/', 'surplus', 4);
INSERT INTO `words` VALUES (23201, 'Germany surrendered on May 7th, 1945.', 'v&n. 投降，自首；放弃；屈服', '/sə\'rendə | sə\'rɛndɚ/', 'surrender', 4);
INSERT INTO `words` VALUES (23202, 'He glared at the people who surrounded the tent.', 'vt. 围绕； 包围', '/sə\'raund | sə\'raʊnd/', 'surround', 4);
INSERT INTO `words` VALUES (23203, 'I need to work in pleasant surroundings.', 'n. 周围的事物， 环境', '/sə\'raundɪŋz | sə\'raʊndɪŋz/', 'surroundings', 4);
INSERT INTO `words` VALUES (23204, 'electronic surveillance equipment', 'n. 监视， 盯梢', '/sɜː\'veɪləns | sɝ\'veləns/', 'surveillance', 4);
INSERT INTO `words` VALUES (23205, 'a survey of modern English literature', 'vt&n. 环视，眺望；测量；勘定；检查；概述', '/sə:\'vei, \'sə:vei, sə- | ˈsəːveɪ; (for v.) səˈveɪ | ˈsɝˌve; (for v.) sɝˈve/', 'survey', 4);
INSERT INTO `words` VALUES (23206, 'The doctors gave him a one in ten chance of survival .', 'n. 幸存者，残存；幸存', '/sə\'vaivəl | sə\'vaɪv(ə)l | sɚ\'vaɪvl/', 'survival', 4);
INSERT INTO `words` VALUES (23207, 'Only 12 of the 140 passengers survived.', 'v. 活下来； 幸免于； 比…活得长， 比…长命', '/sə\'vaɪv | sɚ\'vaɪv/', 'survive', 4);
INSERT INTO `words` VALUES (23208, 'A lot of TV advertising is aimed at susceptible young children.', 'adj. 敏感的；易受感动的', '/sə\'septəbl | sə\'septɪb(ə)l | sə\'sɛptəbl/', 'susceptible', 4);
INSERT INTO `words` VALUES (23209, 'She strongly suspected he was lying to her.', 'v. 疑有,猜想;觉得可疑; n. 嫌疑犯; adj. 可疑的\"', '/sə\'spekt, \'sʌspekt | ˈsʌspekt; (for v.) səˈspekt | sʌspɛkt; (for v.) səˈspɛkt/', 'suspect', 4);
INSERT INTO `words` VALUES (23210, 'Sales of the drug will be suspended until more tests are completed.', 'v. 吊，悬挂，悬浮；暂停', '/sə\'spend | sə\'spɛnd/', 'suspend', 4);
INSERT INTO `words` VALUES (23211, 'The suspense over the two remaining hostages ended last night when the police discovered the bullet ridden bodies.', 'n. (新闻、决定)不确定，悬而未决', '/sə\'spens | sə\'spɛns/', 'suspense', 4);
INSERT INTO `words` VALUES (23212, 'He received a six-month suspension for unprofessional behaviour.', 'n. 悬挂，暂停', '/sə\'spenʃən | sə\'spenʃ(ə)n | sə\'spɛnʃən/', 'suspension', 4);
INSERT INTO `words` VALUES (23213, 'His reluctance to answer my questions made me suspicious .', 'adj. 可疑的，疑心的', '/sə\'spiʃəs | sə\'spɪʃəs/', 'suspicious', 4);
INSERT INTO `words` VALUES (23214, 'She found it difficult to sustain the children’s interest.', 'v. 支撑；支持，维持', '/sə\'stein | sə\'steɪn | sə\'sten/', 'sustain', 4);
INSERT INTO `words` VALUES (23215, 'The party is promising low inflation and sustainable economic growth.', 'adj. 可以忍受的； 足以支撑的； 养得起的', '/sə\'steɪnəbl | sə\'stenəbl/', 'sustainable', 4);
INSERT INTO `words` VALUES (23216, 'Without sustenance, the animals will soon die.', 'n. 食物，营养', '/\'sʌstenəns | \'sʌst(ə)nəns; -tɪn- | \'sʌstənəns/', 'sustenance', 4);
INSERT INTO `words` VALUES (23217, 'He swallowed the last of his coffee and asked for the bill.', 'v. 吞，咽', '/\'swɔləu | \'swɒləʊ | \'swɑlo/', 'swallow', 4);
INSERT INTO `words` VALUES (23218, 'I spent one whole night by a swamp behind the road listening to frogs.', 'n. 沼泽地，使淹没', '/swɔmp, swɔ:mp | swɒmp | swɑmp/', 'swamp', 4);
INSERT INTO `words` VALUES (23219, 'Do you want to swap umbrellas?', 'v&n. 交换', '/swɒp | swɑp/', 'swap', 4);
INSERT INTO `words` VALUES (23220, '...a swarm of locusts.', 'n. (昆虫)等一大群; v. 成群飞舞；蜂拥而入', '/swɔ:m | swɔːm | swɔrm/', 'swarm', 4);
INSERT INTO `words` VALUES (23221, 'The trees swayed gently in the breeze.', 'v&n. 摇摆；统治，支配', '/swei | sweɪ | swe/', 'sway', 4);
INSERT INTO `words` VALUES (23222, 'I never touched your purse, I swear!', 'vt&vi. 郑重地说；强调；发誓', '/swεə | sweə | swɛr/', 'swear', 4);
INSERT INTO `words` VALUES (23223, NULL, 'n. 厚运行衫，毛线衫', '/\'swetə | \'swɛtɚ/', 'sweater', 4);
INSERT INTO `words` VALUES (23224, 'The kitchen needs a good sweep.', 'n. 扫，扫除；连绵区域; v. 扫除；掠过；连绵', '/swi:p | swiːp | swip/', 'sweep', 4);
INSERT INTO `words` VALUES (23225, 'The wind swelled the sails.', 'vt&vi. 使膨胀；使增强，使壮大，使隆起', '/swel | swɛl/', 'swell', 4);
INSERT INTO `words` VALUES (23226, 'Drivers coming in the opposite direction swerved to avoid the bodies.', 'vt&vi. 突然转向', '/swə:v | swɜːv | swɝv/', 'swerve', 4);
INSERT INTO `words` VALUES (23227, 'My letter received a swift reply.', 'adj. 快的；迅速的，敏捷的', '/swɪft/', 'swift', 4);
INSERT INTO `words` VALUES (23228, 'Let your arms swing as you walk.', 'vt&vi. 摆动，摇动；旋转，转向', '/swiŋ | swɪŋ/', 'swing', 4);
INSERT INTO `words` VALUES (23229, 'The river had become a swirling torrent.', 'vt&vi. 打旋，旋动', '/swə:l | swɜːl | swɝl/', 'swirl', 4);
INSERT INTO `words` VALUES (23230, 'The terrorists will switch tactics .', 'v. 改变， 转变； 转换； 对调; n. 开关；转换', '/swɪtʃ/', 'switch', 4);
INSERT INTO `words` VALUES (23231, 'Anna swivelled round to face him.', 'v. 旋转; n. 转环， 转节', '/\'swɪvl/', 'swivel', 4);
INSERT INTO `words` VALUES (23232, 'The course syllabus consisted mainly of novels by African-American authors, male and female.', 'n. 教学大纲', '/\'siləbəs | \'sɪləbəs/', 'syllabus', 4);
INSERT INTO `words` VALUES (23233, 'The symbol on the packet is a guarantee that the food has been produced organically.', 'n. 象征； 符号', '/\'sɪmbl/', 'symbol', 4);
