INSERT INTO `words` VALUES (23235, 'Crime often symbolizes a wider social problem.', 'v. 用符号表示；作为象征', '/\'simbəlaiz | \'sɪmbəlaɪz/', 'symbolize', 4);
INSERT INTO `words` VALUES (23236, '...the incredible beauty and symmetry of a snowflake.', 'n. 对称；匀称', '/\'simitri | \'sɪmɪtrɪ | \'sɪmətri/', 'symmetry', 4);
INSERT INTO `words` VALUES (23237, 'a sympathetic friend', 'adj. 同情的，有同情心的', '/,simpə\'θetik | sɪmpə\'θetɪk | ,sɪmpə\'θɛtɪk/', 'sympathetic', 4);
INSERT INTO `words` VALUES (23238, 'If they want national freedom, of course we sympathise.', 'vi. 同情； 赞同', '/\'sɪmpəθaɪz | \'simpəθaiz/', 'sympathise', 4);
INSERT INTO `words` VALUES (23239, 'Our sympathies are with the families of the victims.', 'n. 同情； 赞同， 支持', '/\'sɪmpəθi/', 'sympathy', 4);
INSERT INTO `words` VALUES (23240, 'Bruckner’s Fifth Symphony', 'n. 交响乐曲', '/\'simfəni | \'sɪmf(ə)nɪ | \'sɪmfəni/', 'symphony', 4);
INSERT INTO `words` VALUES (23241, 'He had been taking part in an international symposium on population.', 'n. 专题论文集，讨论会', '/sim\'pəuziəm | sɪm\'pəʊzɪəm | sɪm\'pozɪəm/', 'symposium', 4);
INSERT INTO `words` VALUES (23242, 'One of the most common symptoms of schizophrenia is hearing imaginary voices.', 'n. 症状，症候，征兆', '/\'simptəm | \'sɪm(p)təm | \'sɪmptəm/', 'symptom', 4);
