INSERT INTO `words` VALUES (23244, 'It was virtually impossible to synchronize our lives so as to take vacations and weekends together.', 'v. 使同时发生，使同步发生', '/\'siŋkrənaiz | \'sɪŋkrənaɪz/', 'synchronize', 4);
INSERT INTO `words` VALUES (23245, 'The term \"industrial democracy\" is often used as a synonym for worker participation.', 'n. 同义词', '/\'sinənim | \'sɪnənɪm | ˈsɪnənɪm/', 'synonym', 4);
INSERT INTO `words` VALUES (23246, 'speech synthesis software', 'n. 合成法；综合，合成物', '/\'sinθisis | \'sɪnθɪsɪs | \'sɪnθəsɪs/', 'synthesis', 4);
INSERT INTO `words` VALUES (23247, 'synthetic chemicals', 'adj. 人工合成的', '/sin\'θetik | sɪn\'θetɪk | sɪn\'θɛtɪk/', 'synthetic', 4);
INSERT INTO `words` VALUES (23248, 'They went about their business in a systematic way.', 'adj. 有系统的，系统的；有计划有步骤的', '/sɪstə\'mætɪk | \'sɪstə\'mætɪk/', 'systematic', 4);
INSERT INTO `words` VALUES (23249, 'an index tab labeled ‘Expenses’', 'n. 标签', '/tæb/', 'tab', 4);
INSERT INTO `words` VALUES (23250, 'She took a couple of headache tablets .', 'n. 碑，书板；药片', '/\'tæblɪt | \'tæblət/', 'tablet', 4);
INSERT INTO `words` VALUES (23251, 'The topic of addiction remains something of a taboo in our family.', 'n. (宗教迷信)禁忌; adj. 禁忌的，禁止的', '/tə\'bu:, tæ- | tə\'buː | tə\'bu/', 'taboo', 4);
INSERT INTO `words` VALUES (23252, 'a tacit agreement between the three big companies', 'adj. 心照不宣的', '/\'tæsɪt/', 'tacit', 4);
