INSERT INTO `words` VALUES (23256, NULL, 'vt&vi. 紧跟，尾随', '/teɪk | tek/', 'take', 4);
INSERT INTO `words` VALUES (23257, 'a talented actor', 'adj. 有才能的，有才干的', '/\'tæləntid | \'tæləntɪd/', 'talented', 4);
INSERT INTO `words` VALUES (23258, 'If you have a tame doctor, he might give you a sick note.', 'adj. 驯服了的；(人)顺从的，听话的', '/teim | teɪm/', 'tame', 4);
INSERT INTO `words` VALUES (23259, 'Don\'t tamper with my business.', 'v. 干预，乱弄', '/\'tæmpə | \'tæmpɚ/', 'tamper', 4);
