INSERT INTO `words` VALUES (23267, 'There is no target date for completion of the new project.', 'n. 靶，标；批评对象；指标', '/\'tɑ:ɡit | \'tɑːgɪt | \'tɑrɡɪt/', 'target', 4);
INSERT INTO `words` VALUES (23268, 'America wants to eliminate tariffs on items such as electronics.', 'n. (酒店)价目表；关税税率', '/\'tærif | \'tærɪf/', 'tariff', 4);
INSERT INTO `words` VALUES (23269, 'His regime was tarnished by human rights abuses.', 'vt&vi. (尤指金属表面)失去光泽；玷污', '/\'tɑ:niʃ | \'tɑːnɪʃ | \'tɑrnɪʃ/', 'tarnish', 4);
INSERT INTO `words` VALUES (23270, 'A gang taunted a disabled man.', 'vt. 嘲笑，讥笑', '/tɔːnt | tɔnt/', 'taunt', 4);
