INSERT INTO `words` VALUES (23286, 'His impulsive temperament regularly got him into difficulties.', 'n. 性情，气质', '/\'tempərəmənt | \'temp(ə)rəm(ə)nt | \'tɛmprəmənt/', 'temperament', 4);
INSERT INTO `words` VALUES (23287, 'The Nile Valley keeps a temperate climate throughout the year.', 'adj. 有节制的，不过分的；(气候)温和的', '/\'tempərit | \'temp(ə)rət | \'tɛmpərət/', 'temperate', 4);
INSERT INTO `words` VALUES (23288, 'the easy tempo of island life', 'n. (行动，活动)速度；节拍；节奏', '/\'tempəu | \'tempəʊ | \'tɛmpo/', 'tempo', 4);
