INSERT INTO `words` VALUES (23290, 'If you leave valuables in your car it will tempt thieves.', 'vt. 引诱； 吸引', '/tempt | tɛmpt/', 'tempt', 4);
INSERT INTO `words` VALUES (23291, 'Resist the temptation to buy the item until you’re certain you need it.', 'n. 引诱，诱惑', '/temp\'teiʃən | tem(p)\'teɪʃ(ə)n | tɛmp\'teʃən/', 'temptation', 4);
