INSERT INTO `words` VALUES (23298, 'Continue cooking until the meat is tender.', 'adj. 脆弱的，娇嫩的；温柔的; v. 提供，投标', '/\'tendə | \'tɛndɚ/', 'tender', 4);
INSERT INTO `words` VALUES (23299, 'Is anything wrong? You look a little tense.', 'adj. 拉紧的; v. 拉紧', '/tens | tɛns/', 'tense', 4);
