INSERT INTO `words` VALUES (23301, 'The tension was becoming unbearable, and I wanted to scream.', 'n. 紧张局势；情绪紧张；不安状态', '/\'tenʃən | \'tenʃ(ə)n | \'tɛnʃən/', 'tension', 4);
INSERT INTO `words` VALUES (23302, 'Free speech is being gradually eroded year after year by new tentacles of government control.', 'n. (动物)触角', '/\'tentəkl | \'tentək(ə)l | \'tɛntəkl/', 'tentacle', 4);
