INSERT INTO `words` VALUES (23306, 'The court ruled that the contract must be terminated.', 'vt&vi. 终止，结束', '/\'tə:mineit | \'tɜːmɪneɪt | \'tɝmɪnet/', 'terminate', 4);
INSERT INTO `words` VALUES (23307, 'computer terminology', 'n. 专门用语， 术语', '/ˌtɜːmɪ\'nɒlədʒi | ,tɝmə\'nɑlədʒi/', 'terminology', 4);
INSERT INTO `words` VALUES (23308, '...massive terraces of corn and millet carved into the mountainside like giant steps.', 'n. 斜坡地，梯田；看台，大阶级', '/\'terəs, -is | \'terəs | ˈterəs/', 'terrace', 4);
