INSERT INTO `words` VALUES (23314, 'Hong Kong is a Chinese territory.', 'n. 领土，区域', '/\'teritəri | \'terɪt(ə)rɪ | \'tɛrətɔri/', 'territory', 4);
INSERT INTO `words` VALUES (23315, 'There was a look of sheer terror (= complete terror ) on his face.', 'n. 恐怖', '/\'terə | \'tɛrɚ/', 'terror', 4);
