INSERT INTO `words` VALUES (23317, 'Barker’s testimony is crucial to the prosecution’s case.', 'n. 证据，证言', '/\'testiməni | \'testɪmənɪ | \'tɛstə\'moni/', 'testimony', 4);
INSERT INTO `words` VALUES (23318, 'Their main exports are textiles, especially silk and cotton.', 'a&n. 纺织的，纺织品', '/\'tekstail, -til | \'tekstaɪl | \'tɛkstaɪl/', 'textile', 4);
INSERT INTO `words` VALUES (23319, 'Matured over 18 months, this cheese has an open, crumbly texture with a strong flavour.', 'n. (织物)组织，结构；(材料)构造，结构', '/\'tekstʃə | \'tɛkstʃɚ/', 'texture', 4);
INSERT INTO `words` VALUES (23320, 'The lake thawed in March.', 'vt&vi. (冰雪)融化；使变得友善; n. 解冻', '/θɔ: | θɔː | θɔ/', 'thaw', 4);
