INSERT INTO `words` VALUES (23338, 'The doctor gave him a thorough check-up.', 'adj. 彻底的；详尽的', '/\'θʌrə, \'θə:rəu | \'θʌrə | ˈθʌrəʊ; θʌro/', 'thorough', 4);
INSERT INTO `words` VALUES (23339, 'Paul is very thoughtful.', 'adj. 深思的，关心的', '/\'θɔ:tful | \'θɔːtfʊl; -f(ə)l | \'θɔtfl/', 'thoughtful', 4);
INSERT INTO `words` VALUES (23340, 'Postal workers are threatening a strike if they don’t receive a pay increase.', 'v. 威胁， 恐吓； 预示快要来临， 是…的征兆， 可能发生', '/\'θretn | \'θrɛtn/', 'threaten', 4);
INSERT INTO `words` VALUES (23341, 'She opened the door and stepped across the threshold.', 'n. 门槛；开始；开端，入门', '/\'θreʃhəuld | \'θreʃəʊld; \'θreʃ,həʊld | \'θrɛʃhold/', 'threshold', 4);
