INSERT INTO `words` VALUES (23346, 'I shall not be at peace,\' moaned Catherine, recalled to a sense of physical weakness by the violent, unequal throbbing of her heart, which beat visibly and audibly under this excess of agitation.', 'adj. 跳动的，悸动的', '/\'θrɔbiŋ | \'θrɒbɪŋ/', 'throbbing', 4);
INSERT INTO `words` VALUES (23347, 'She got lost in the throng.', 'n. 人群，群众; v. 拥挤，群集', '/θrɔŋ, θrɔ:ŋ | θrɒŋ | θrɔŋ/', 'throng', 4);
INSERT INTO `words` VALUES (23348, 'a large organization with offices throughout the world', 'prep. 遍及', '/θru:\'aut | θruː\'aʊt | θrʊ\'aʊt/', 'throughout', 4);
INSERT INTO `words` VALUES (23349, 'He jumped back to avoid another thrust of the knife.', 'n. 猛推；冲锋，突击；推力', '/θrʌst/', 'thrust', 4);
INSERT INTO `words` VALUES (23350, 'a baby sucking its thumb', 'n. 大拇指', '/θʌm/', 'thumb', 4);
