INSERT INTO `words` VALUES (23355, 'Is the tide going out or coming in ?', 'n. 潮汐，(舆论，公众情绪)潮流趋势', '/taid | taɪd/', 'tide', 4);
INSERT INTO `words` VALUES (23356, 'a tidy desk', 'adj. 整洁的；有条理的', '/\'taidi | \'taɪdɪ | \'taɪdi/', 'tidy', 4);
INSERT INTO `words` VALUES (23357, 'Tighten the screws firmly.', 'vt&vi. (使)变紧，(使)绷紧，扣紧', '/\'taitən | \'taɪt(ə)n | \'taɪtn/', 'tighten', 4);
INSERT INTO `words` VALUES (23358, '...a fine building, with a neat little porch and ornamental tiles on the roof.', 'n. 瓦，瓦片', '/tail | taɪl/', 'tile', 4);
INSERT INTO `words` VALUES (23359, NULL, 'adj. 适宜耕种的， 可耕种的', '/\'tiləbl | \'tɪləbl/', 'tillable', 4);
INSERT INTO `words` VALUES (23360, 'My mother tilted her head and smiled.', 'vt&vi. (使)倾斜; n. 倾斜，斜坡', '/tilt | tɪlt/', 'tilt', 4);
INSERT INTO `words` VALUES (23361, 'a bench made of timber', 'n. 木材，木料；树木，树林', '/\'timbə | \'tɪmbə | \'tɪmbɚ/', 'timber', 4);
INSERT INTO `words` VALUES (23362, 'Einstein changed the way we think about space and time.', 'n. 时间', '/taim | taɪm/', 'time', 4);
