INSERT INTO `words` VALUES (23368, '\"Patience and Sarah\" was first published in 1969 under the title \"A Place for Us.\"', 'n. 标题；题目；称号；法律权利，所有权', '/\'taitl | \'taɪt(ə)l | \'taɪtl/', 'title', 4);
