INSERT INTO `words` VALUES (23371, 'People who toiled in dim, dank factories were too exhausted to enjoy their family life.', 'v. 辛劳工作，艰难地行动; n. 苦工，难事', '/tɔil | tɒɪl | tɔɪl/', 'toil', 4);
INSERT INTO `words` VALUES (23372, 'After normalization of attributes, you can count on every token in an attribute being separated from its neighbors by whitespace.', 'n&a. 标专，记号；象征性的', '/\'təukən | \'təʊk(ə)n | \'tokən/', 'token', 4);
INSERT INTO `words` VALUES (23373, 'The apartment is really too small, but it’s tolerable for the time being.', 'adj. 可忍受的，可容许的，尚好的', '/\'tɔlərəbl | \'tɒl(ə)rəb(ə)l | \'tɑlərəbl/', 'tolerable', 4);
