INSERT INTO `words` VALUES (23375, 'We simply will not tolerate vigilante groups on our streets.', 'vt. 容忍， 宽容； 容许， 承认', '/\'tɒləreɪt | \'tɑləret/', 'tolerate', 4);
INSERT INTO `words` VALUES (23376, 'You can pay a toll to drive on Pike\'s Peak Highway or relax and take the Pike\'s Peak Cog Railway.', 'n. (道路，桥梁)通行费；损失，代价；税收', '/təʊl | tol/', 'toll', 4);
