INSERT INTO `words` VALUES (23378, '‘I’m sorry,’ he said, in a flat toneless voice.', 'adj. 单调的，沉闷的', '/\'təunlis | \'təʊnlɪs | \'tonləs/', 'toneless', 4);
INSERT INTO `words` VALUES (23379, 'Joe ran his tongue over his dry lips.', 'n. 舌头；语言；舌状物（火舌）', '/tʌŋ/', 'tongue', 4);
