INSERT INTO `words` VALUES (23381, 'This scandal could topple the government.', 'v. 倒塌， 倒下； 打倒， 推翻', '/\'tɒpl | \'tɑpl/', 'topple', 4);
INSERT INTO `words` VALUES (23382, 'The topsoil has been almost completely washed away.', 'n. 表层土', '/\'tɒpsɔɪl | \'tɑp\'sɔɪl/', 'topsoil', 4);
INSERT INTO `words` VALUES (23383, 'We shone our torches around the cavern.', 'n. 火把；手电筒', '/tɔ:tʃ | tɔːtʃ | tɔrtʃ/', 'torch', 4);
