INSERT INTO `words` VALUES (23385, 'The tornado rubbished the whole village.', 'n. 飓风，龙卷风', '/tɔ:\'neidəu | tɔː\'neɪdəʊ | tɔr\'nedo/', 'tornado', 4);
INSERT INTO `words` VALUES (23386, 'After five days of heavy rain the Telle river was a raging torrent (= a very violent torrent ) .', 'n. (湍，激，洪)流', '/\'tɔrənt, \'tɔ:- | \'tɒr(ə)nt | \'tɔrənt/', 'torrent', 4);
INSERT INTO `words` VALUES (23387, NULL, 'n. 龟， 陆龟； 行动迟缓的人', '/\'tɔːtəs | ˈtɔrtəs/', 'tortoise', 4);
INSERT INTO `words` VALUES (23388, 'He died after five days of excruciating torture.', 'vt&n. 拷打，折磨，使受剧烈痛苦', '/\'tɔ:tʃə | \'tɔːtʃə | \'tɔrtʃɚ/', 'torture', 4);
