INSERT INTO `words` VALUES (23394, 'The ship had to be towed into the harbor.', 'vt&n. 拖；拉', '/təu | təʊ | to/', 'tow', 4);
INSERT INTO `words` VALUES (23395, 'Have you got a clean towel I could use?', 'n. 毛巾，手巾', '/\'tauəl | \'taʊəl/', 'towel', 4);
