INSERT INTO `words` VALUES (23399, 'There was no trace of anyone having entered the room since then.', 'n. 痕迹；足迹；微量; v. 描绘，勾出轮廓', '/treis | treɪs | tres/', 'trace', 4);
INSERT INTO `words` VALUES (23400, 'The only evidence of pandas was their tracks in the snow.', 'n&v. 行迹；踪迹；跟踪', '/træk/', 'track', 4);
INSERT INTO `words` VALUES (23401, 'Fossils can only tell us so much about the shape of the vocal tract because much of it is soft tissue.', 'n. 地带；系统', '/trækt/', 'tract', 4);
INSERT INTO `words` VALUES (23402, 'This process gives your vehicle the best chance of holding traction on the steep hill, because both the gearbox and the brakes are locking you in place.', 'n. 拖，牵，牵引力', '/\'trækʃən | \'trækʃ(ə)n/', 'traction', 4);
INSERT INTO `words` VALUES (23403, 'the traditions of South East Asia', 'n. 传统； 惯例', '/trə\'dɪʃn | trə\'dɪʃən/', 'tradition', 4);
INSERT INTO `words` VALUES (23404, 'traditional Italian cooking', 'adj. 传统的， 惯例的； 口传的， 传说的', '/trə\'dɪʃənl/', 'traditional', 4);
INSERT INTO `words` VALUES (23405, 'The tragedy happened as they were returning home from a night out.', 'n. 悲剧；惨事', '/\'trædʒidi | \'trædʒɪdɪ | \'trædʒədi/', 'tragedy', 4);
INSERT INTO `words` VALUES (23406, 'The parents were not to blame for the tragic death of their son.', 'adj. 悲惨的； 悲剧的', '/\'trædʒɪk/', 'tragic', 4);
INSERT INTO `words` VALUES (23407, 'The trail led over Boulder Pass before descending to a lake.', 'n. 痕迹，足迹，小径; v. 拖，拉，蔓延', '/treɪl | trel/', 'trail', 4);
INSERT INTO `words` VALUES (23408, 'The study found that some alcoholics had clear personality traits showing up early in childhood.', 'n. 特征，品质', '/trei, treit | treɪt; treɪ | tret/', 'trait', 4);
INSERT INTO `words` VALUES (23409, '...rumours that there were traitors among us who were sending messages to the enemy.', 'n. 叛徒，卖国贼', '/\'treitə | \'treɪtə | \'tretɚ/', 'traitor', 4);
INSERT INTO `words` VALUES (23410, 'The tramp from the tram swamped the ham hamburge with shampoo.', 'v. 乘电车; n. 有轨电车，电车轨道', '/træm/', 'tram', 4);
INSERT INTO `words` VALUES (23411, 'They put on their coats and tramped through the falling snow.', 'v. 徒步远行；长途跋涉', '/træmp/', 'tramp', 4);
INSERT INTO `words` VALUES (23412, 'Their in-terests and rights had been trampled underfoot .', 'v. 踩，践踏；蔑视，粗暴对待', '/\'træmpl | \'træmp(ə)l/', 'trample', 4);
INSERT INTO `words` VALUES (23413, 'We all like the tranquility of the country life.', 'n. 安静，平静', '/træŋ\'kwiləti, træn-/', 'tranquility', 4);
INSERT INTO `words` VALUES (23414, 'The bank charges a fixed rate for each transaction.', 'n. 办理，处理；执行；事务，事项，交易', '/træn\'zækʃən, -\'sæk-, trɑ:n- | træn\'zækʃ(ə)n; trɑːn-; -\'sæk- | træn\'zækʃən/', 'transaction', 4);
INSERT INTO `words` VALUES (23415, 'The desire for peace transcended political differences.', 'v. 超出，超过', '/træn\'send, trɑ:n- | træn\'send; trɑːn- | træn\'sɛnd/', 'transcend', 4);
INSERT INTO `words` VALUES (23416, 'He had been asked to transcribe an ancient manuscript.', 'vt. 抄写， 誊写； 打印； 转录', '/træn\'skraɪb/', 'transcribe', 4);
INSERT INTO `words` VALUES (23417, 'A transcript of this PBS programme is available through our website, pbs.com.', 'n. 抄本，副本', '/\'trænskript, \'trænz-, \'trɑ:n- | \'trænskrɪpt; \'trɑːn- | \'trænskrɪpt/', 'transcript', 4);
INSERT INTO `words` VALUES (23418, 'Pronunciation is shown by a system of phonetic transcription.', 'n. 抄写， 誊写； 抄本， 誊本； 书面标注的事物； 改编', '/træn\'skrɪpʃn | træn\'skrɪpʃən/', 'transcription', 4);
INSERT INTO `words` VALUES (23419, 'Ideas that work well in one school often don’t transfer well to another.', 'v. 转让；转业；调任; n. 转移，传递', '/træns\'fə: | træns\'fɜː; trɑːns-; -nz- | træns\'fɝ/', 'transfer', 4);
INSERT INTO `words` VALUES (23420, 'Increased population has transformed the landscape.', 'v. 改变(形状性质等)', '/træns\'fɔ:m, trænz-, trɑ:n- | træns\'fɔːm; trɑːns-; -nz- | træns\'fɔrm/', 'transform', 4);
INSERT INTO `words` VALUES (23421, 'There are no rules about when to transfuse and who to do it to.', 'v. 给输血', '/træns\'fju:z, trænz-, trɑ:n- | træns\'fjuːz; trɑːns-; -nz- | trænz\'fjʊz/', 'transfuse', 4);
INSERT INTO `words` VALUES (23422, 'Orton’s plays transgress accepted social norms.', 'vt&vi. 越越限度；违反(法律规则)', '/træns\'ɡres, trænz-, trɑ:n- | trænz\'gres; trɑːnz-; -ns- | trænz\'ɡrɛs/', 'transgress', 4);
