INSERT INTO `words` VALUES (23527, 'This tragic incident underlines the need for immediate action.', 'v. 划线于之下，强调', '/,ʌndə\'lain, \'ʌndəlain | ʌndə\'laɪn | \'ʌndəlaɪn/', 'underline', 4);
INSERT INTO `words` VALUES (23528, '...underlings who do the dirty work.', 'n. 职位低的人， 下属', '/\'ʌndəlɪŋ | \'ʌndɚlɪŋ/', 'underling', 4);
INSERT INTO `words` VALUES (23529, 'To stop a problem you have to understand its underlying causes.', 'adj. 含蓄的，潜在的；在下面的', '/,ʌndə\'laiiŋ | ʌndə\'laɪɪŋ | ,ʌndɚ\'laɪɪŋ/', 'underlying', 4);
INSERT INTO `words` VALUES (23530, 'economic policies that threaten to undermine the health care system', 'v. (暗中)破坏；(逐渐)削弱', '/,ʌndə\'main | ʌndə\'maɪn | \'ʌndɚ\'maɪn/', 'undermine', 4);
INSERT INTO `words` VALUES (23531, 'He got out of the car and looked underneath.', 'prep&ad. 在下面，在底下', '/,ʌndə\'ni:θ | ʌndə\'niːθ | ,ʌndɚ\'niθ/', 'underneath', 4);
INSERT INTO `words` VALUES (23532, 'the theories that underpin his teaching method', 'vt. 加固…的基础； 加强， 巩固', '/ˌʌndə\'pɪn | ,ʌndɚ\'pɪn/', 'underpin', 4);
INSERT INTO `words` VALUES (23533, 'It is understandable that parents are angry, and looking for someone to blame.', 'adj. 可以理解的， 能懂的； 可同情的', '/ˌʌndə\'stændəbl | \'ʌndɚ\'stændəbl/', 'understandable', 4);
INSERT INTO `words` VALUES (23534, 'Luckily, I have a very under­standing boss.', 'adj. 体谅的； 宽容的; n. 理解；谅解', '/ˌʌndə\'stændɪŋ | ,ʌndɚ\'stændɪŋ/', 'understanding', 4);
INSERT INTO `words` VALUES (23535, 'He undertook to pay the money back in six months.', 'v. 同意，答应；着手做某事', '/,ʌndə\'teik | ʌndə\'teɪk | ,ʌndɚ\'tek/', 'undertake', 4);
INSERT INTO `words` VALUES (23536, 'The government has agreed to underwrite the project with a grant of £5 million.', 'v. 给保险；同意赔款(海上保险)', '/\'ʌndərait | ʌndə\'raɪt; \'ʌndəraɪt | ,ʌndɚ\'raɪt/', 'underwrite', 4);
INSERT INTO `words` VALUES (23537, 'The thieves escaped undetected through a basement window.', 'adj. 未被发现的', '/ˌʌndɪ\'tektɪd | \'ʌndɪ\'tɛktɪd/', 'undetected', 4);
INSERT INTO `words` VALUES (23538, 'There was undisguised contempt in his voice.', 'adj. 无伪装的； 坦率的', '/ˌʌndɪs\'gaɪzd | ,ʌndɪs\'ɡaɪzd/', 'undisguised', 4);
INSERT INTO `words` VALUES (23539, 'The screws can be undone by hand.', 'v. 解开，拨开；败坏(名声，成果)', '/,ʌn\'du: | ʌn\'duː | ʌn\'du/', 'undo', 4);
INSERT INTO `words` VALUES (23540, 'This is undoubtedly important.', 'adv. 无疑地，必是地', '/ʌn\'daʊtɪdlɪ | ʌn\'daʊtɪdli/', 'undoubtedly', 4);
INSERT INTO `words` VALUES (23541, 'De Gaulle felt that America had undue influence in Europe.', 'adj. 过分的，过度的', '/,ʌn\'dju: | ʌn\'djuː | ,ʌn\'du/', 'undue', 4);
INSERT INTO `words` VALUES (23542, 'She eventually fell into an uneasy sleep.', 'adj. 不自在的', '/,ʌn\'i:zi | ʌn\'iːzɪ | ʌn\'izi/', 'uneasy', 4);
INSERT INTO `words` VALUES (23543, 'a town where there is high unemployment', 'n. 失业', '/,ʌnim\'plɔimənt | ʌnɪm\'plɒɪm(ə)nt; -em- | ,ʌnɪm\'plɔɪmənt/', 'unemployment', 4);
INSERT INTO `words` VALUES (23544, 'She walked back carefully over the uneven ground.', 'adj. 不平坦的，不均匀的', '/,ʌn\'i:vən | ʌn\'iːv(ə)n | ʌn\'ivən/', 'uneven', 4);
INSERT INTO `words` VALUES (23545, 'The experiment produced some unexpected results.', 'adj. 想不到的， 意外的', '/ˌʌnɪk\'spektɪd | \'ʌnɪk\'spɛktɪd/', 'unexpected', 4);
INSERT INTO `words` VALUES (23546, 'He unfolded the map.', 'vt&vi. 展开，打开', '/,ʌn\'fəuld | ʌn\'fəʊld | ʌn\'fold/', 'unfold', 4);
INSERT INTO `words` VALUES (23547, 'Unfortunately, you were out when we called.', 'adv. 不幸地', '/ʌn\'fɔːtʃənətli | ʌn\'fɔrtʃənətli/', 'unfortunately', 4);
INSERT INTO `words` VALUES (23548, 'a tall ungainly teenager', 'adj. 笨拙的，难看的', '/,ʌn\'ɡeinli | ʌn\'geɪnlɪ | ʌn\'ɡenli/', 'ungainly', 4);
INSERT INTO `words` VALUES (23549, 'Grade A eggs must be of uniform size.', 'adj. 不变的，一贯的; n. 制服', '/\'ju:nifɔ:m | \'juːnɪfɔːm | \'junɪfɔrm/', 'uniform', 4);
INSERT INTO `words` VALUES (23550, 'Strong support for the war has unified the nation.', 'v. 使联合，统一，使相同，一致', '/\'ju:nifai | \'juːnɪfaɪ | \'junɪfaɪ/', 'unify', 4);
INSERT INTO `words` VALUES (23551, 'a unilateral declaration of independence', 'adj. 单方面的；片面的', '/,ju:ni\'lætərəl | juːnɪ\'læt(ə)r(ə)l | \'jʊnɪ\'lætərəl/', 'unilateral', 4);
INSERT INTO `words` VALUES (23552, 'Are you planning to join the union?', 'n. 协会， 工会， 同盟； 联合， 合并', '/\'juːniən | \'junɪən/', 'union', 4);
INSERT INTO `words` VALUES (23553, 'Each person’s fingerprints are unique.', 'adj. 唯一的，独一无二的', '/ju:\'ni:k | juː\'niːk | jʊ\'nik/', 'unique', 4);
INSERT INTO `words` VALUES (23554, 'free universal healthcare', 'adj. 全体的，普遍的；全球的', '/,ju:ni\'və:səl | juːnɪ\'vɜːs(ə)l | \'jʊnə\'vɝsl/', 'universal', 4);
INSERT INTO `words` VALUES (23555, 'Einstein\'s equations showed the universe to be expanding.', 'n. 宇宙， 天地万物； 世界； 领域', '/\'juːnɪvɜːs | \'junɪvɝs/', 'universe', 4);
INSERT INTO `words` VALUES (23556, 'Donna might be able to come tomorrow, but it’s very unlikely.', 'adj. 未必的，不大可能的', '/,ʌn\'laikli | ʌn\'laɪklɪ | ʌn\'laɪkli/', 'unlikely', 4);
INSERT INTO `words` VALUES (23557, 'Unload everything from the boat and clean it thoroughly.', 'v. 从…卸下货物； 摆脱', '/ˌʌn\'ləud | \'ʌn\'lod/', 'unload', 4);
INSERT INTO `words` VALUES (23558, 'The staff are trained to be unobtrusive.', 'adj. 不显著的， 不引人注目的； 不张扬的', '/ˌʌnəb\'truːsɪv | \'ʌnəb\'trʊsɪv/', 'unobtrusive', 4);
INSERT INTO `words` VALUES (23559, 'an achievement unparalleled in sporting history', 'adj. 无双的， 无比的， 空前的', '/ʌn\'pærəleld | ʌn\'pærəlɛld/', 'unparalleled', 4);
INSERT INTO `words` VALUES (23560, 'Narrator: This is a tale about an unprejudiced heart, and how it changed our valley forever.', 'adj. 无偏见的； 公正的', '/ˌʌn\'predʒədɪst | ʌn\'prɛdʒədɪst/', 'unprejudiced', 4);
INSERT INTO `words` VALUES (23561, NULL, 'v. 结束引语', '/ˌʌn\'kwəut | ,ʌn\'kwot/', 'unquote', 4);
INSERT INTO `words` VALUES (23562, 'Detectives are still trying to unravel the mystery surrounding his death.', 'v. 拆散(线团)；解决', '/,ʌn\'rævəl | ʌn\'rævl/', 'unravel', 4);
INSERT INTO `words` VALUES (23563, 'Some parents have totally unrealistic expectations of teachers.', 'adj. 不现实的， 不切实际的', '/ˌʌnrɪə\'lɪstɪk | ,ʌnriə\'lɪstɪk/', 'unrealistic', 4);
INSERT INTO `words` VALUES (23564, 'unregistered land', 'adj. 未注册的', '/ʌn\'redʒɪstəd | ʌn\'rɛdʒɪstɚd/', 'unregistered', 4);
INSERT INTO `words` VALUES (23565, 'There is growing unrest throughout the country.', 'n. 不安；动荡', '/,ʌn\'rest | ʌn\'rest | ʌn\'rɛst/', 'unrest', 4);
INSERT INTO `words` VALUES (23566, 'unsanitary conditions', 'adj. 不卫生的', '/ʌn\'sænətri | ʌn\'sænətɛri/', 'unsanitary', 4);
INSERT INTO `words` VALUES (23567, 'an unsatisfactory situation', 'adj. 不能令人满意的', '/ˌʌnˌsætɪs\'fæktəri | ,ʌn,sætɪs\'fæktəri/', 'unsatisfactory', 4);
INSERT INTO `words` VALUES (23568, 'The rumours will do untold damage to his reputation.', 'adj. 数不清的，无数的', '/,ʌn\'təuld | ʌn\'təʊld | ,ʌn\'told/', 'untold', 4);
INSERT INTO `words` VALUES (23569, 'I think he is shallow, vain and untrustworthy.', 'adj. 不值得信任的， 靠不住的', '/ʌn\'trʌstwəːðɪ | ʌn\'trʌstwɝði/', 'untrustworthy', 4);
INSERT INTO `words` VALUES (23570, 'The statue was unveiled by the Queen.', 'v. 揭去面纱或覆盖物； 揭幕； 首次公开、 揭露或展示', '/ˌʌn\'veɪl | ,ʌn\'vel/', 'unveil', 4);
INSERT INTO `words` VALUES (23571, 'Brigitte was unwrapping her birthday presents.', 'vt. 打开， 解开； 除去包装', '/ˌʌn\'ræp | ʌn\'ræp/', 'unwrap', 4);
INSERT INTO `words` VALUES (23572, 'an unyielding resistance to change', 'adj. 顽强的； 坚硬的； 不能弯曲的， 坚固的', '/ʌn\'jiːldɪŋ | ʌn\'jildɪŋ/', 'unyielding', 4);
INSERT INTO `words` VALUES (23573, '...the most up-to-date information available on foods today.', 'adj. 直到最近的； 现代的', '/ˌʌptə\'deɪt | \'ʌptə \'det/', 'up-to-date', 4);
INSERT INTO `words` VALUES (23574, 'Mike had had a strict upbringing.', 'n. 抚育，抚养；教养', '/\'ʌp,briŋiŋ | \'ʌpbrɪŋɪŋ/', 'upbringing', 4);
INSERT INTO `words` VALUES (23575, 'plans to update manufacturing procedures', 'v. 使现代化；使靠最近', '/ʌp\'deit, \'ʌpdeit | ʌp\'deɪt | ,ʌp\'det/', 'update', 4);
INSERT INTO `words` VALUES (23576, 'The hotel has recently been refurbished and upgraded.', 'n. 向上的斜坡；增加，改善; vt. 使升级， 提高， 改进； 提拔， 提升； 改善', '/ˌʌp\'greɪd | ,ʌp\'ɡred/', 'upgrade', 4);
INSERT INTO `words` VALUES (23577, 'The road twists uphill.', 'adv. 向上， 往上； 上坡； 艰难地', '/ˌʌp\'hɪl | ,ʌp\'hɪl/', 'uphill', 4);
INSERT INTO `words` VALUES (23578, 'a committee that aims to uphold educational standards', 'v. 支持；赞成；确认', '/ʌp\'həuld | ʌp\'həʊld | ʌpˈhoʊld/', 'uphold', 4);
INSERT INTO `words` VALUES (23579, 'Poorer people find it hard to pay for their pet’s upkeep.', 'n. 保养费，维修费', '/\'ʌpki:p | \'ʌpkiːp | \'ʌpkip/', 'upkeep', 4);
INSERT INTO `words` VALUES (23580, 'the upper lip', 'adj. 上面的； 地位较高的', '/\'ʌpə(r) | \'ʌpɚ/', 'upper', 4);
INSERT INTO `words` VALUES (23581, 'Katie was still awake, sitting bolt upright(= sitting with her back very straight ) staring at the television.', 'adj. 垂直的，直立的；正直的', '/\'ʌprait, ,ʌp\'r- | \'ʌpraɪt/', 'upright', 4);
INSERT INTO `words` VALUES (23582, NULL, 'n. 叛乱', '/\'ʌp,raiziŋ | \'ʌpraɪzɪŋ/', 'uprising', 4);
INSERT INTO `words` VALUES (23583, 'The chemicals upset the balance of the environment.', 'v&n. 倾覆，打乱', '/ʌp\'set | ʌp\'sɛt/', 'upset', 4);
INSERT INTO `words` VALUES (23584, 'unemployment in urban areas', 'adj. 都市的； 住在都市的', '/\'ɜːbən | \'ɝbən/', 'urban', 4);
INSERT INTO `words` VALUES (23585, 'In their own process of urbanization, every country will encounter the problem of land requisition and housing demolition.', 'n. 城市化， 都市化', '/ˌɜːbənaɪ\'zeɪʃn | ,ɝbənɪ\'zeʃən/', 'urbanization', 4);
INSERT INTO `words` VALUES (23586, 'The charity urged quick action.', 'v. 敦促， 力劝； 鼓励； 竭力主张', '/ɜːdʒ | ɝdʒ/', 'urge', 4);
INSERT INTO `words` VALUES (23587, 'He was in urgent need of medical attention.', 'adj. 紧急的， 紧迫的； 催促的， 急切的', '/\'ɜːdʒənt | \'ɝdʒənt/', 'urgent', 4);
INSERT INTO `words` VALUES (23588, 'The two sides have also pledged to enhance cooperation in tourism, and the protection and utilisation of cultural heritage.', 'n. 利用', '/ˌjuːtəlaɪ\'zeɪʃn | ,ju:tilai\'zeiʃən/', 'utilisation', 4);
INSERT INTO `words` VALUES (23589, 'The one thing that never crosses the minds of our elite is to utilise local talent, local enterprise, local money to build Pakistan.', 'vt. 利用， 运用', '/\'juːtəlaɪz | \'ju:tilaiz/', 'utilise', 4);
INSERT INTO `words` VALUES (23590, 'Does your rent include utilities?', 'n. 有用，实用；公用事业(煤气，水电)', '/ju:\'tiləti | juːˈtɪlɪtɪ | ju\'tɪləti/', 'utility', 4);
INSERT INTO `words` VALUES (23591, 'It is a matter of the utmost urgency to find out what has happened to these people.', 'adj. 最远的，最大的，极度的', '/\'ʌtməust | \'ʌtməʊst | \'ʌt\'most/', 'utmost', 4);
INSERT INTO `words` VALUES (23592, 'Politicians are judged by their public utterances.', 'n. 用言语表达， 讲话； 话语， 言语， 言论', '/\'ʌtərəns/', 'utterance', 4);
INSERT INTO `words` VALUES (23593, 'You look utterly miserable.', 'adv. 完全地，十足地', '/\'ʌtəli | \'ʌtəlɪ | \'ʌtɚli/', 'utterly', 4);
INSERT INTO `words` VALUES (23594, 'There are still two vacancies on the school board.', 'n. 空位， 空房间； 空缺， 空职； 无主意， 空虚， 茫然若失', '/\'veɪkənsi | \'vekənsi/', 'vacancy', 4);
INSERT INTO `words` VALUES (23595, 'Only a few apartments were still vacant.', 'adj. 空的；未被占用的；空虚的，无表情的', '/\'veikənt | \'veɪk(ə)nt | \'vekənt/', 'vacant', 4);
INSERT INTO `words` VALUES (23596, 'We’re planning a vacation in Europe.', 'n. 假期;休庭期;腾空', '/və\'keiʃən | vəˈkeɪʃn; veɪ-/', 'vacation', 4);
INSERT INTO `words` VALUES (23597, 'His presence should fill the power vacuum that has been developing over the past few days.', 'n. 真空', '/\'vækjuəm | \'vækjʊəm/', 'vacuum', 4);
INSERT INTO `words` VALUES (23598, 'The governor gave only a vague outline of his tax plan.', 'adj. 模糊的； 含糊的', '/veɪg | veɡ/', 'vague', 4);
INSERT INTO `words` VALUES (23599, 'Men can be just as vain as women.', 'adj. 徒劳的，无效果的；自负的；不尊敬的', '/英[veɪn] 美[ven] | veɪn | ven/', 'vain', 4);
INSERT INTO `words` VALUES (23600, 'a valid credit card', 'adj. 有效的， 具有法律效力的； 正当的； 有根据的， 有理的', '/\'vælɪd/', 'valid', 4);
INSERT INTO `words` VALUES (23601, 'So that satisfies the definition of validity.', 'n. 有效，正当', '/və\'lidəti | və\'lɪdɪtɪ | və\'lɪdəti/', 'validity', 4);
INSERT INTO `words` VALUES (23602, 'the San Fernando Valley', 'n. 深谷，山谷', '/\'væli | \'vælɪ/', 'valley', 4);
INSERT INTO `words` VALUES (23603, 'a valuable painting', 'adj. 贵重的，有价值的; n. 贵重物品， 财宝', '/\'væljuəbl | ˈvæljuəbəl; ˈvæljə-/', 'valuable', 4);
INSERT INTO `words` VALUES (23604, 'The property has a valuation of $1.6 billion.', 'n. 定价，估价；评定的价值', '/,vælju\'eiʃən | væljʊ\'eɪʃ(ə)n | ,vælju\'eʃən/', 'valuation', 4);
INSERT INTO `words` VALUES (23605, 'heart valves', 'n. 阀，活门', '/vælv/', 'valve', 4);
INSERT INTO `words` VALUES (23606, 'a delivery van', 'n. 运货车', '/væn/', 'van', 4);
INSERT INTO `words` VALUES (23607, 'My keys were here a minute ago but now they’ve vanished.', 'v. 消失', '/\'væniʃ | \'vænɪʃ/', 'vanish', 4);
INSERT INTO `words` VALUES (23608, 'Sabrina had none of the vanity so often associated with beautiful women.', 'n. 自大，虚荣；无价值，空虚', '/\'vænəti | ˈvænəti/', 'vanity', 4);
INSERT INTO `words` VALUES (23609, 'A happy ending is only possible because the hero has first vanquished the dragons.', 'v. 征服，击败', '/\'væŋkwiʃ | \'væŋkwɪʃ/', 'vanquish', 4);
INSERT INTO `words` VALUES (23610, 'In our world, not only do we have variability, we\'ve got unpredictability.', 'n. 可变性， 易变性', '/ˌveəriə\'bɪləti | ,vɛrɪə\'bɪləti/', 'variability', 4);
INSERT INTO `words` VALUES (23611, 'Expect variable cloudiness and fog tomorrow.', 'adj. 可变的，变化的; n. 可变物，变量', '/\'vεəriəbl | \'veərɪəb(ə)l | \'vɛrɪəbl/', 'variable', 4);
INSERT INTO `words` VALUES (23612, 'Note that you must use the same variant of this option for all compiler runs related to the same project.', 'adj. 不同的，变异的; n. 变体，异体', '/\'vεəriənt | \'veərɪənt | \'vɛrɪənt/', 'variant', 4);
INSERT INTO `words` VALUES (23613, 'Most of his poems are variations on the theme of love.', 'n. 变化，改变；变量；变异', '/,vεəri\'eiʃən | veərɪ\'eɪʃ(ə)n | ,vɛrɪ\'eʃən/', 'variation', 4);
INSERT INTO `words` VALUES (23614, 'a varied diet', 'adj. 各种各样的', '/\'vεərid | \'veərɪd | \'vɛrɪd/', 'varied', 4);
INSERT INTO `words` VALUES (23615, 'The girls come from a variety of different backgrounds.', 'n. 多样化；种；变种；综艺演出', '/英 [vəˈraɪəti] 美 [vəˈraɪɪti | və\'raɪətɪ | və\'raɪəti/', 'variety', 4);
INSERT INTO `words` VALUES (23616, 'The jacket is available in various colours.', 'adj. 各种各样的； 不同的； 多方面的', '/\'veəriəs | \'vɛrɪəs/', 'various', 4);
INSERT INTO `words` VALUES (23617, 'Quentin’s mood seems to vary according to the weather.', 'vt&vi. 变化', '/\'vεəri | \'veərɪ | ˈveri/', 'vary', 4);
INSERT INTO `words` VALUES (23618, 'The refugees come across the border in vast numbers.', 'adj. 巨大的； 大量的', '/vɑːst | væst/', 'vast', 4);
INSERT INTO `words` VALUES (23619, 'Our youngest daughter is a vegetarian.', 'n. 素食者', '/,vedʒi\'tεəriən | vɛdʒɪˈtɛːrɪən | ˌvedʒə\'teriən/', 'vegetarian', 4);
INSERT INTO `words` VALUES (23620, 'Lefkas has an abundance of lush green vegetation.', 'n. 植被', '/,vedʒi\'teiʃən | vedʒɪ\'teɪʃ(ə)n | \'vɛdʒə\'teʃən/', 'vegetation', 4);
INSERT INTO `words` VALUES (23621, 'She suddenly became very vehement and agitated, jumping around and shouting.', 'adj. 感情强烈的；热烈的；(人)有强烈感情的', '/\'vi:imənt | ˈvi:əmənt | viəmənt/', 'vehement', 4);
INSERT INTO `words` VALUES (23622, 'a description of the stolen vehicle', 'n. 车辆交通工具；思想媒介', '/\'viːɪk(ə)l | ˈviːɪk(ə)l | \'viːɪkl/', 'vehicle', 4);
INSERT INTO `words` VALUES (23623, 'She lifted her veil with both hands.', 'n. 面纱；掩饰物', '/veil | veɪl | vel/', 'veil', 4);
INSERT INTO `words` VALUES (23624, 'the pulmonary vein', 'n. 静脉，叶脉；(石头)纹理；矿脉', '/vein | veɪn | ven/', 'vein', 4);
INSERT INTO `words` VALUES (23625, 'the velocity of light', 'n. 速度，速率', '/vəˈlɒsəti | vəˈlɑsəti/', 'velocity', 4);
INSERT INTO `words` VALUES (23626, 'a symbol of Arab courage, to be venerated for generations', 'v. 崇敬，崇拜', '/\'venəreit | \'venəreɪt | \'vɛnəret/', 'venerate', 4);
INSERT INTO `words` VALUES (23627, 'a desire for vengeance', 'n. 报仇', '/\'vendʒəns | \'ven(d)ʒ(ə)ns | \'vɛndʒəns/', 'vengeance', 4);
INSERT INTO `words` VALUES (23628, 'Lisa shot him a venomous glance.', 'adj. 有毒的； 分泌毒液的； 恶意的， 狠毒的', '/\'venəməs | \'vɛnəməs/', 'venomous', 4);
INSERT INTO `words` VALUES (23629, 'Children give vent to their anger in various ways.', 'n&vt. 出口；发泄', '/vent | vɛnt/', 'vent', 4);
INSERT INTO `words` VALUES (23630, 'Ventilate the room properly when stripping paint.', 'v. 使空气流通；通风', '/\'ventileit | \'ventɪleɪt | \'vɛntɪlet/', 'ventilate', 4);
INSERT INTO `words` VALUES (23631, 'I see no ventilation to speak of, none from a window or a ventilator at least.', 'n. 空气流通； 通风设备， 通风方法', '/ˌventɪ\'leɪʃn | ,vɛntl\'eʃən/', 'ventilation', 4);
INSERT INTO `words` VALUES (23632, '...a Russian-American joint venture.', 'n. 冒险，冒险事业', '/\'ventʃə | \'vɛntʃɚ/', 'venture', 4);
