INSERT INTO `words` VALUES (23802, 'Slavery was abolished in the US in the 19th century.', 'v. 废除，废止；取消，革除', '/ə\'bɔliʃ | ə\'bɒlɪʃ | ə\'bɑlɪʃ/', 'abolish', 5);
INSERT INTO `words` VALUES (23803, 'Stories abound about when he was in charge.', 'v. 富于；充满', '/ə\'baund | ə\'baʊnd/', 'abound', 5);
INSERT INTO `words` VALUES (23804, 'I’ve never lived abroad before.', 'adv. 在国外；到海外; adj. 往国外的; n. 海外；异国', '/ə\'brɔ:d | ə\'brɔːd | ə\'brɔd/', 'abroad', 5);
INSERT INTO `words` VALUES (23805, 'an abrupt change of plan', 'adj. 生硬的；突然的；唐突的；陡峭的', '/ə\'brʌpt/', 'abrupt', 5);
