INSERT INTO `words` VALUES (23808, 'I have absolute confidence in her.', 'adj. 绝对的，完全的；确实的，肯定的', '/\'æbsəlju:t, ,æbsə\'lju:t | \'æbsəluːt | \'æbsəlut/', 'absolute', 5);
INSERT INTO `words` VALUES (23809, 'Plants absorb nutrients from the soil.', 'v. 吸收；吸引；承受；理解；使…全神贯注', '/əb\'sɔ:b, -\'zɔ:b | əb\'zɔːb; -\'sɔːb | æbˈsɔrb; æbˈzɔrb; əbˈsɔrb/', 'absorb', 5);
INSERT INTO `words` VALUES (23810, 'By the age of seven, children are capable of thinking in abstract terms .', 'adj. 抽象的; n. 摘要，梗概; v. 提取；摘录要点', '/\'æbstrækt/', 'abstract', 5);
INSERT INTO `words` VALUES (23811, 'It seems an absurd idea.', 'adj. 荒谬的；可笑的; n. 荒诞；荒诞作品', '/əb\'sə:d | əb\'sɜːd | əbˈsɚd, -ˈzɚd/', 'absurd', 5);
INSERT INTO `words` VALUES (23812, 'This area of Mexico has an abundance of safe beaches and a pleasing climate.', 'n. 充裕，丰富', '/ə\'bʌndəns | ə\'bʌnd(ə)ns/', 'abundance', 5);
INSERT INTO `words` VALUES (23813, 'an abundant supply of fresh water', 'adj. 丰富的；充裕的；盛产', '/ə\'bʌndənt | ə\'bʌnd(ə)nt/', 'abundant', 5);
INSERT INTO `words` VALUES (23814, 'Williams abused his position as Mayor to give jobs to his friends.', 'vt. 滥用；虐待；谩骂; n. 滥用；虐待', '/ə\'bjuːz | ə\'bjus/', 'abuse', 5);
INSERT INTO `words` VALUES (23815, 'He possessed no academic qualifications.', 'adj. 学术的；理论的；学院的; n. 大学生，大学教师；学者', '/,ækə\'demik | ækə\'demɪk | ,ækə\'dɛmɪk/', 'academic', 5);
