INSERT INTO `words` VALUES (23817, 'measures to accelerate the rate of economic growth', 'v. 使加速，使增速，促进; v. 加快，增加', '/ək\'seləreit | ək\'seləreɪt | əkˈsɛləˌret/', 'accelerate', 5);
INSERT INTO `words` VALUES (23818, 'He had a strong Irish accent', 'n. 口音；重音；强调；特点；重音符号; v. 强调；重读；带…口音讲话', '/\'æksənt, æk\'sent | \'æks(ə)nt; -sent | \'æksɛnt/', 'accent', 5);
INSERT INTO `words` VALUES (23819, 'Rick accepted her offer of coffee.', 'v. 接受，领受；认可，同意; v. 同意，认可', '/ək\'sept | ə\'ksept | ækˈsɛpt; əkˈsɛpt/', 'accept', 5);
INSERT INTO `words` VALUES (23820, 'He wrote a letter of acceptance (= a letter in which you agree to accept a job, university place etc ) to the university.', 'n. 接受，接收，验收，接纳；承认，认可', '/ək\'septəns | ək\'sept(ə)ns | ək\'sɛptəns/', 'acceptance', 5);
INSERT INTO `words` VALUES (23821, 'Access is by means of a small door on the right.', 'n. 进入；接入；到达；享用权；入口; v. 存取', '/\'ækses, \'æksəs, æk\'ses | \'ækses | \'æksɛs/', 'access', 5);
INSERT INTO `words` VALUES (23822, 'bathroom accessories such as mirrors and towel-rails', 'n. 附件,附属品;(全套衣服增加美感的)服饰', '/ək\'sesəri | ək\'ses(ə)rɪ | ək\'sɛsəri/', 'accessory', 5);
INSERT INTO `words` VALUES (23823, 'Ken had an accident at work and had to go to hospital.', 'n. 意外遭遇,事故；意外(因素)', '/\'æksidənt | \'æksɪdənt | \'æksədənt/', 'accident', 5);
INSERT INTO `words` VALUES (23824, 'an accidental discharge of toxic waste', 'adj. 偶然的；意外的；无意中的', '/,æksi\'dentəl | æksɪ\'dent(ə)l | ,æksɪ\'dɛntl/', 'accidental', 5);
INSERT INTO `words` VALUES (23825, 'His work was acclaimed by art critics.', 'v. 称赞；为…喝彩，向…欢呼; n. 欢呼，喝彩；称赞', '/ə\'kleɪm | ə\'klem/', 'acclaim', 5);
INSERT INTO `words` VALUES (23826, 'The island was used to accommodate child refugees.', 'v. 向…提供住处；对...予以照顾性考虑', '/ə\'kɔmədeit | ə\'kɒmədeɪt | ə\'kɑmədet/', 'accommodate', 5);
INSERT INTO `words` VALUES (23827, 'The government will provide temporary accommodation for up to three thousand homeless people.', 'n. 住宿，留宿；膳宿供应', '/ə,kɔmə\'deiʃən | əkɒmə\'deɪʃ(ə)n | ə,kɑmə\'deʃən/', 'accommodation', 5);
INSERT INTO `words` VALUES (23828, 'Children under 14 must be accompanied by an adult.', 'v. 陪伴，陪同；伴随，一起发生，伴奏', '/ə\'kʌmpəni | ə\'kʌmpənɪ/', 'accompany', 5);
INSERT INTO `words` VALUES (23829, 'We have accomplished all we set out to do.', 'v. 完成；实现；达到', '/ə\'kʌmpliʃ, ə\'kɔm- | ə\'kʌmplɪʃ; ə\'kɒm- | ə\'kɑmplɪʃ/', 'accomplish', 5);
INSERT INTO `words` VALUES (23830, 'The punishments accorded with the current code of discipline.', 'vi. 相符合， 相一致; n. 一致， 符合；协议， 条约; vt. 授予， 赠与', '/ə\'kɔːd | ə\'kɔrd/', 'accord', 5);
INSERT INTO `words` VALUES (23831, 'IT organizations working in an environment with compliance requirements must to be able to document that they have designed, implemented, and tested the application in accordance with these standards.', 'n. 一致；和谐', '/ə\'kɔ:dəns | ə\'kɔːd(ə)ns | ə\'kɔrdns/', 'accordance', 5);
INSERT INTO `words` VALUES (23832, 'Katherine still considered him a child and treated him accordingly.', 'adv. 因此，于是；相应地；照著', '/ə\'kɔ:diŋli | ə\'kɔːdɪŋlɪ | ə\'kɔrdɪŋli/', 'accordingly', 5);
INSERT INTO `words` VALUES (23833, 'His account contradicted itself.', 'adj. 叙述，说明；账目，账户; v. 说明，解释', '/ə\'kaʊnt/', 'account', 5);
INSERT INTO `words` VALUES (23834, 'The boss dropped an accountant from the payroll.', 'n. 会计人员，会计师', '/ə\'kauntənt | ə\'kaʊnt(ə)nt | ə\'kaʊntənt/', 'accountant', 5);
INSERT INTO `words` VALUES (23835, 'It is unjust that a privileged few should continue to accumulate wealth.', 'v. 累积；积聚', '/ə\'kju:mjuleit | ə\'kjuːmjʊleɪt | ə\'kjumjəlet/', 'accumulate', 5);
INSERT INTO `words` VALUES (23836, 'He passes the ball with unerring accuracy.', 'n. 准确（性）；精确；准确度', '/\'ækjurəsi | \'ækjʊrəsɪ | \'ækjərəsi/', 'accuracy', 5);
INSERT INTO `words` VALUES (23837, 'The brochure tries to give a fair and accurate description of each hotel.', 'adj. 正确无误的；准确的，精确的', '/\'ækjurət | \'ækjʊrət | \'ækjərət/', 'accurate', 5);
INSERT INTO `words` VALUES (23838, 'The professor stands accused of (= has been accused of ) stealing his student’s ideas and publishing them.', 'v. 控告，指控；谴责；归咎于', '/ə\'kju:z | ə\'kjuːz | ə\'kjuz/', 'accuse', 5);
INSERT INTO `words` VALUES (23839, 'She tried to accustom herself to the tight bandages.', 'vt. 使习惯于<', '/ə\'kʌstəm/', 'accustom', 5);
INSERT INTO `words` VALUES (23840, 'The pans were in their accustomed places.', 'adj. 惯常的；习惯的，适应的(一般作表语)', '/ə\'kʌstəmd/', 'accustomed', 5);
INSERT INTO `words` VALUES (23841, 'His feet were aching from standing so long.', 'v. 疼痛；渴望; n. 疼痛', '/eik | eɪk | ek/', 'ache', 5);
INSERT INTO `words` VALUES (23842, 'Frances achieved very good exam results.', 'v. 取得；获得；实现；成功', '/ə\'tʃiːv | ə\'tʃiv/', 'achieve', 5);
INSERT INTO `words` VALUES (23843, 'sulphuric acid', 'n. 酸,酸性物质a.酸的,酸味的；尖刻的', '/\'æsid | \'æsɪd/', 'acid', 5);
INSERT INTO `words` VALUES (23844, 'The family acknowledge the need for change.', 'v. 承认；答谢；报偿；告知已收到', '/ək\'nɔlidʒ | ək\'nɒlɪdʒ | ək\'nɑlɪdʒ/', 'acknowledge', 5);
INSERT INTO `words` VALUES (23845, 'I need to acquaint myself with the new regulations.', 'v. 使熟悉；使认识', '/ə\'kweint | ə\'kweɪnt | ə\'kwent/', 'acquaint', 5);
INSERT INTO `words` VALUES (23846, 'She was a casual acquaintance of my family in Vienna.', 'n. 熟人；相识；了解；知道', '/ə\'kweintəns | ə\'kweɪnt(ə)ns | ə\'kwentəns/', 'acquaintance', 5);
INSERT INTO `words` VALUES (23847, 'Manning hoped to acquire valuable works of art as cheaply as possible.', 'v. 获得；取得；学到；捕获', '/ə\'kwaiə | ə\'kwaɪə | ə\'kwaɪr/', 'acquire', 5);
INSERT INTO `words` VALUES (23848, 'the acquisition of language', 'n. 获得物，获得；收购', '/,ækwɪ\'zɪʃ(ə)n | ,ækwɪ\'zɪʃən/', 'acquisition', 5);
INSERT INTO `words` VALUES (23849, 'They own 200 acres of farmland.', 'n. 英亩；田地；地产', '/\'eikə | \'eɪkə | \'ekɚ/', 'acre', 5);
INSERT INTO `words` VALUES (23850, 'The acrobat balanced himself on the high rope.', 'n. 特技演员，杂技演员', '/\'ækrəbæt/', 'acrobat', 5);
