INSERT INTO `words` VALUES (23855, 'Everyone is free to engage in peaceful political activity.', 'n. 活动；活性； 活力', '/æk\'tɪvəti | ækˈtɪvətɪ/', 'activity', 5);
INSERT INTO `words` VALUES (23856, 'His father was an actor in the Cantonese Opera Company.', 'n. 男演员；行动者；作用物', '/\'æktə | \'æktɚ/', 'actor', 5);
INSERT INTO `words` VALUES (23857, 'She\'s not only a great dramatic actress but she\'s also very funny.', 'n. 女演员', '/\'æktris | \'æktrɪs/', 'actress', 5);
INSERT INTO `words` VALUES (23858, 'I’m not joking. Those were his actual words.', 'adj. 实际的；现实的，真实的，目前的', '/\'æktʃuəl | \'æktʃʊəl; -tjʊəl/', 'actual', 5);
INSERT INTO `words` VALUES (23859, 'The housing shortage is more acute than first thought.', 'adj. 严重的，[医] 急性的；敏锐的；激烈的；尖声的', '/ə\'kju:t | ə\'kjuːt | ə\'kjut/', 'acute', 5);
INSERT INTO `words` VALUES (23860, 'The ability to adapt is a definite asset in this job.', 'v. 使适应；改编', '/ə\'dæpt/', 'adapt', 5);
INSERT INTO `words` VALUES (23861, 'She is a TV addict and watches as much as she can.', 'v. 使沉溺；使上瘾; n. 沉溺于不良嗜好的人', '/ə\'dikt,\'ædikt | \'ædɪkt (for n.); əˈdɪkt (for v.)/', 'addict', 5);
INSERT INTO `words` VALUES (23862, 'They built a big addition onto the back of the house.', 'n. 加，加法；附加部分，增加(物)', '/ə\'diʃən | ə\'dɪʃ(ə)n | ə\'dɪʃən/', 'addition', 5);
INSERT INTO `words` VALUES (23863, 'Additional information can be obtained from the centre.', 'adj. 附加的，额外的', '/ə\'diʃənəl | ə\'dɪʃ(ə)n(ə)l | ə\'dɪʃənl/', 'additional', 5);
INSERT INTO `words` VALUES (23864, 'Send a stamped, self-addressed envelope (= with your address on it so it can be sent back to you ) .', 'v. 演说；从事；忙于；写姓名地址；向…致辞；与…说话；提出；处理; n. 地址；演讲；致辞；说话的技巧；称呼', '/ə\'dres | ə\'drɛs/', 'address', 5);
INSERT INTO `words` VALUES (23865, 'Farmers have been slow to make adequate provision for their retirement.', 'adj. 充足的，足够的；适当的，胜任的', '/\'ædikwit | \'ædɪkwət | ˈædɪkwət/', 'adequate', 5);
INSERT INTO `words` VALUES (23866, 'All members of the association adhere to a strict code of practice.', 'v. (to)粘着；坚持，遵守；依附，追随', '/əd\'hiə | əd\'hɪə | əd\'hɪr/', 'adhere', 5);
INSERT INTO `words` VALUES (23867, 'We stayed in adjacent rooms.', 'adj. 邻近的，毗连的', '/ə\'dʒeisənt | ə\'dʒeɪs(ə)nt | ə\'dʒesnt/', 'adjacent', 5);
INSERT INTO `words` VALUES (23868, 'In “the black cat” the adjective “black”modifies the noun “cat”.', 'adj. 形容词的；从属的; n. 形容词', '/\'ædʒiktiv | \'ædʒɪktɪv/', 'adjective', 5);
INSERT INTO `words` VALUES (23869, 'A vacant plot of land adjoins his house.', 'v. 毗连，邻接', '/ə\'dʒɔin | ə\'dʒɒɪn | ə\'dʒɔɪn/', 'adjoin', 5);
INSERT INTO `words` VALUES (23870, 'Check and adjust the brakes regularly.', 'v. 调整，使…适合；校准', '/ə\'dʒʌst/', 'adjust', 5);
INSERT INTO `words` VALUES (23871, 'The money will be administered by local charities.', 'v. 管理；执行；给予', '/əd\'ministə | əd\'mɪnɪstə | əd\'mɪnɪstɚ/', 'administer', 5);
INSERT INTO `words` VALUES (23872, 'We’re looking for someone with experience in administration.', 'n. 管理；行政；实施；行政机构', '/əd,mini\'streiʃən | ədmɪnɪ\'streɪʃ(ə)n | əd,mɪnɪ\'streʃən/', 'administration', 5);
INSERT INTO `words` VALUES (23873, 'I really admire the way she brings up those kids all on her own.', 'v. 钦佩,赞赏,羡慕；称赞,夸奖', '/əd\'maiə | əd\'maɪə | ədˈmaɪr/', 'admire', 5);
INSERT INTO `words` VALUES (23874, 'Reese, by his own admission , lacks the necessary experience.', 'n. 承认；入场费；进入许可；坦白；录用', '/əd\'miʃən | əd\'mɪʃ(ə)n | əd\'mɪʃən/', 'admission', 5);
INSERT INTO `words` VALUES (23875, '‘Okay, so maybe I was a little bit scared,’ Jenny admitted.', 'v. 承认；准许进入；可容纳', '/əd\'mit | əd\'mɪt/', 'admit', 5);
INSERT INTO `words` VALUES (23876, 'It is important that an adolescent boy should have an adult in whom he can confide.', 'adj. 青春期的；未成熟的; n. 青少年', '/,ædəu\'lesnt | ædə\'les(ə)nt | ,ædə\'lɛsnt/', 'adolescent', 5);
INSERT INTO `words` VALUES (23877, 'Sally was adopted when she was four.', 'v. 采取；接受；收养；正式通过', '/ə\'dɔpt | ə\'dɒpt | ə\'dɑpt/', 'adopt', 5);
INSERT INTO `words` VALUES (23878, 'Betty adores her grandchildren.', 'v. 崇拜；爱慕；喜爱；极喜欢; n. (Adore)人名；(法)阿多尔', '/ə\'dɔ: | ə\'dɔː | ə\'dɔr/', 'adore', 5);
INSERT INTO `words` VALUES (23879, 'an adult lion', 'adj. 成年的；成熟的; n. 成年人', '/\'ædʌlt, ə\'dʌlt | \'ædʌlt; ə\'dʌlt | \'ædʌlt/', 'adult', 5);
INSERT INTO `words` VALUES (23880, 'I should warn you in advance that I’m not a very good dancer.', 'n. 前进，预付; v. 前进，进展; v. 促进，推进', '/əd\'vɑ:ns, əd\'væns | əd\'vɑːns | əd\'væns/', 'advance', 5);
INSERT INTO `words` VALUES (23881, 'advanced weapon systems', 'adj. 先进的；高级的；晚期的；年老的; v. 前进；增加；上涨（advance的过去式和过去分词形式）', '/əd\'vɑ:nst, -\'vænst | æd\'vɑːnst | əd\'vænst/', 'advanced', 5);
INSERT INTO `words` VALUES (23882, 'Younger workers tend to be at an advantage (= have an advantage ) when applying for jobs.', 'n. 优点，长处，有利条件；利益，好处', '/əd\'vɑ:ntidʒ, əd\'væn- | əd\'vɑːntɪdʒ | əd\'væntɪdʒ/', 'advantage', 5);
INSERT INTO `words` VALUES (23883, 'the advent of the computer', 'n. (重要事件等的)到来，来临', '/\'ædvənt/', 'advent', 5);
INSERT INTO `words` VALUES (23884, 'a great adventure', 'n. 冒险，冒险活动，奇遇; v. 大胆进行', '/əd\'ventʃə, æd- | əd\'ventʃə | əd\'vɛntʃɚ/', 'adventure', 5);
INSERT INTO `words` VALUES (23885, 'Will you please compare the adverb “well”?', 'n. 副词; adj. 副词的', '/\'ædvə:b | \'ædvɜːb | \'ædvɝb/', 'adverb', 5);
INSERT INTO `words` VALUES (23886, 'They fear it could have an adverse effect on global financial markets.', 'adj. 逆的，相反的；敌对的；不利的；有害的', '/\'ædvə:s, æd\'və:s | \'ædvɜːs | ædˈvɚs, ˈædˌvɚs/', 'adverse', 5);
INSERT INTO `words` VALUES (23887, 'They no longer advertise alcohol or cigarettes at sporting events.', 'v. 公告，公布；为...做广告; v. 登广告', '/\'ædvətaiz | \'ædvətaɪz | \'ædvɚtaɪz/', 'advertise', 5);
INSERT INTO `words` VALUES (23888, 'You should have followed my advice.', 'n. 劝告，忠告，(医生等的)意见', '/əd\'vais | əd\'vaɪs | ædˈvaɪs; əd\'vaɪs/', 'advice', 5);
INSERT INTO `words` VALUES (23889, 'Regular medical check-ups are advisable.', 'adj. 可取的，适当的，明智的', '/əd\'vaizəbl | əd\'vaɪzəb(ə)l | əd\'vaɪzəbl/', 'advisable', 5);
INSERT INTO `words` VALUES (23890, 'She needed someone to advise her.', 'v. 忠告，劝告，建议；通知，告知', '/əd\'vaiz | əd\'vaɪz/', 'advise', 5);
INSERT INTO `words` VALUES (23891, 'Extremists were openly advocating violence.', 'n. 辩护者，拥护者，鼓吹者; v. 拥护，提倡', '/\'ædvəkeit, \'ædvəkət | \'ædvəkeɪt；-ət | ˈædvəkeɪt；-et/', 'advocate', 5);
INSERT INTO `words` VALUES (23892, 'Weeks of aerial bombardment had destroyed factories and motorways.', 'adj. 空中的，航空的；空气的；空想的; n. [电讯] 天线', '/\'εəriəl | \'eərɪəl | \'ɛrɪəl/', 'aerial', 5);
INSERT INTO `words` VALUES (23893, 'The aeroplane landed us at the airport in Barcelona.', 'n. 飞机（等于airplane）', '/\'εərəplein | \'eərəpleɪn | \'ɛrə\'plen/', 'aeroplane', 5);
INSERT INTO `words` VALUES (23894, 'From an esthetic point of view, it’s a nice design.', 'adj. 美的；美学的；审美的，具有审美趣味的', '/i:s\'θetik | iːs\'θetɪk; es- | ɛs\'θɛtɪk/', 'aesthetic', 5);
INSERT INTO `words` VALUES (23895, 'Are you interested in world affairs?', 'n. 事情；事务；私事；（尤指关系不长久的）风流韵事', '/ə\'fεə | ə\'feə | ə\'fɛr/', 'affair', 5);
INSERT INTO `words` VALUES (23896, 'the areas affected by the hurricane', 'v. 影响；(疾病)侵袭；感动; n. 情感，感情', '/ə\'fekt, \'æfekt | ə\'fekt | ə\'fɛkt/', 'affect', 5);
INSERT INTO `words` VALUES (23897, 'She looked back on those days with affection .', 'n. 爱，喜爱；爱慕之情；感情；疾病，不适', '/ə\'fekʃən | ə\'fekʃ(ə)n | ə\'fɛkʃən/', 'affection', 5);
INSERT INTO `words` VALUES (23898, 'He wanted to affiliate with a U.S. firm because he needed expert advice in legal affairs.', 'v. 隶属于; n. 附属机构， 分公司', '/ə\'fɪlɪeɪt | ə\'fɪlɪet/', 'affiliate', 5);
INSERT INTO `words` VALUES (23899, 'The general affirmed rumors of an attack.', 'v. 肯定；断言', '/ə\'fə:m | ə\'fɜːm | ə\'fɝm/', 'affirm', 5);
INSERT INTO `words` VALUES (23900, 'affluent families', 'adj. 富裕的；丰富的；流畅的; n. 支流；富人', '/\'æfluənt | \'æflʊənt/', 'affluent', 5);
INSERT INTO `words` VALUES (23901, 'The room affords a beautiful view over the city.', 'v. 给予，提供；买得起; n. (Afford)人名；(英)阿福德', '/ə\'fɔ:d | ə\'fɔːd | ə\'fɔrd/', 'afford', 5);
INSERT INTO `words` VALUES (23902, 'There’s no need to be afraid.', 'adj. 害怕的；恐怕；担心的', '/ə\'freid | ə\'freɪd | ə\'fred/', 'afraid', 5);
INSERT INTO `words` VALUES (23903, 'There’s a meeting on Thursday afternoon .', 'n. 午后，下午', '/,ɑ:ftə:\'nu:n, ,æf-, \'ɑ:ftə\'nu:n, \'æf- | ɑːftə\'nuːn | ,æftɚ\'nun/', 'afternoon', 5);
INSERT INTO `words` VALUES (23904, 'Shortly afterward, police arrested four suspects.', 'adv. 以后，后来', '/\'ɑ:ftəwəd, \'æf- | \'ɑːftəwəd | ˈæftərwərd/', 'afterward', 5);
INSERT INTO `words` VALUES (23905, 'Charles arrived shortly afterwards .', 'adv. 后来， 以后', '/\'ɑːftəwəd(z) | \'æftɚwɚdz/', 'afterwards', 5);
INSERT INTO `words` VALUES (23906, 'a UN agency responsible for helping refugees', 'n. 代理(处)；代办处；[美](政府的)机关，厅', '/\'eidʒənsi | \'eɪdʒ(ə)nsɪ | \'edʒənsi/', 'agency', 5);
INSERT INTO `words` VALUES (23907, 'The Republicans have stuck to their conservative agenda.', 'n. 议事日程，记事册', '/ə\'dʒendə | ə\'dʒɛndə/', 'agenda', 5);
INSERT INTO `words` VALUES (23908, 'Our agent in Rio deals with all our Brazilian business.', 'n. 代理人；代理商；产生作用的人或事物', '/\'eidʒənt | \'eɪdʒ(ə)nt | \'edʒənt/', 'agent', 5);
INSERT INTO `words` VALUES (23909, 'Their money problems were further aggravated by a rise in interest rates.', 'v. 加重；使恶化；激怒', '/\'æɡrəveit | \'ægrəveɪt | \'æɡrəvet/', 'aggravate', 5);
INSERT INTO `words` VALUES (23910, 'Jim’s voice became aggressive.', 'adj. 侵略的，好斗的，有进取心的，敢作敢为的', '/ə\'ɡresiv | ə\'gresɪv | ə\'ɡrɛsɪv/', 'aggressive', 5);
INSERT INTO `words` VALUES (23911, 'I must warn you that any mention of Clare agitates your grandmother.', 'v. 摇动(液体)；使焦虑不安；困扰；鼓动', '/\'ædʒiteit | \'ædʒɪteɪt | ˈædʒɪˌteɪt/', 'agitate', 5);
INSERT INTO `words` VALUES (23912, 'the agony of arthritis', 'n. (精神或肉体的)极大痛苦，创伤', '/\'æɡəni | \'ægənɪ/', 'agony', 5);
INSERT INTO `words` VALUES (23913, 'Teenagers and their parents rarely agree.', 'v. 同意，赞成；承认；约定，商定', '/ə\'griː | ə\'ɡri/', 'agree', 5);
INSERT INTO `words` VALUES (23914, 'We spent a most agreeable couple of hours.', 'adj. 令人愉快的；适合的；和蔼可亲的', '/ə\'ɡri:əbl | ə\'griːəb(ə)l | ə\'ɡriəbl/', 'agreeable', 5);
INSERT INTO `words` VALUES (23915, 'It is easier for two parties to reach agreement than for three.', 'n. 协议；同意，一致', '/ə\'ɡri:mənt | ə\'griːm(ə)nt | ə\'grimənt/', 'agreement', 5);
INSERT INTO `words` VALUES (23916, 'More than 75% of the land is used for agriculture.', 'n. 农业；农耕；农业生产；农艺，农学', '/\'ægrɪkʌltʃə | \'æɡrɪkʌltʃɚ/', 'agriculture', 5);
INSERT INTO `words` VALUES (23917, 'He kept his gaze fixed on the car ahead.', 'adj. 向前；在前的；领先; adv. 向前地；领先地；在（某人或某事物的）前面；预先；在将来，为未来', '/ə\'hed | ə\'hɛd/', 'ahead', 5);
INSERT INTO `words` VALUES (23918, 'Foreign aid from many countries poured into the famine area.', 'n. 援助；帮助；助手；帮助者; v. 援助；帮助；有助于', '/eid | eɪd | ed/', 'aid', 5);
INSERT INTO `words` VALUES (23919, 'Denver aimed his gun but did not shoot.', 'v. 目的在于；引导；把…对准; n. 目的；目标；对准', '/eɪm | em/', 'aim', 5);
INSERT INTO `words` VALUES (23920, 'The return flight of the aircraft was delayed.', 'n. 飞机，航空器', '/\'εəkrɑ:ft | \'eəkrɑːft | \'ɛr\'kræft/', 'aircraft', 5);
INSERT INTO `words` VALUES (23921, 'an airline pilot', 'n. 航空公司；航线; adj. 航线的', '/\'εəlain | \'eəlaɪn | \'ɛrlaɪn/', 'airline', 5);
INSERT INTO `words` VALUES (23922, 'The plane landed at Heathrow Airport.', 'n. 机场，航空站，航空港', '/\'εəpɔ:t | \'eəpɔːt | \'ɛr\'pɔrt/', 'airport', 5);
INSERT INTO `words` VALUES (23923, 'Would you like a window seat or an aisle seat (= seat next to the aisle ) ?', 'n. 通道，走道；侧廊', '/ail | aɪl/', 'aisle', 5);
INSERT INTO `words` VALUES (23924, 'I forgot to set the burglar alarm.', 'n. 闹钟；警报，警告器；惊慌; v. 警告；使惊恐', '/ə\'lɑːm | ə\'lɑrm/', 'alarm', 5);
INSERT INTO `words` VALUES (23925, 'a photograph album', 'n. 相簿；唱片集；集邮簿；签名纪念册', '/\'ælbəm/', 'album', 5);
INSERT INTO `words` VALUES (23926, 'I don’t drink alcohol anymore.', 'n. 酒精，乙醇', '/\'ælkəhɔl | \'ælkəhɒl/', 'alcohol', 5);
INSERT INTO `words` VALUES (23927, 'The school immediately alerted the police .', 'v. 警告；使警觉，使意识到; adj. 警惕的，警觉的；留心的; n. 警戒，警惕；警报', '/ə\'lə:t | ə\'lɜːt | ə\'lɝt/', 'alert', 5);
INSERT INTO `words` VALUES (23928, 'alien cultures', 'adj. 外国的；相异的，性质不同的；不相容的; n. 外国人，外侨；外星人; v. 让渡，转让', '/\'eiljən | \'eɪlɪən | ˈeliən,ˈeljən/', 'alien', 5);
INSERT INTO `words` VALUES (23929, 'The latest tax proposals will alienate many voters.', 'vt. 使疏远， 使格格不入；使不友好； 离间A', '/\'eɪliəneɪt | \'eiljəneit/', 'alienate', 5);
INSERT INTO `words` VALUES (23930, 'My mother and I are alike in many ways.', 'adj. 相似的；相同的; adv. 以同样的方式；类似于', '/ə\'laik | ə\'laɪk/', 'alike', 5);
INSERT INTO `words` VALUES (23931, 'It was a bad accident – they’re lucky to be alive.', 'adj. 活着的；活泼的；有生气的', '/ə\'laiv | ə\'laɪv/', 'alive', 5);
INSERT INTO `words` VALUES (23932, 'She alleged that there was rampant drug use among the male members of the group.', 'v. 宣称，断言；提出…作为理由', '/ə\'ledʒ | ə\'lɛdʒ/', 'allege', 5);
INSERT INTO `words` VALUES (23933, 'an oath of allegiance', 'n. 拥护； 忠诚', '/ə\'liːdʒəns | ə\'lidʒəns/', 'allegiance', 5);
INSERT INTO `words` VALUES (23934, 'measures to alleviate poverty', 'v. 减轻，缓和，缓解(痛苦等)', '/ə\'li:vieit | ə\'liːvɪeɪt | ə\'livɪ\'et/', 'alleviate', 5);
INSERT INTO `words` VALUES (23935, 'independent organizations and alliances', 'n. 联盟，联合；联姻', '/ə\'laiəns | ə\'laɪəns/', 'alliance', 5);
INSERT INTO `words` VALUES (23936, 'Tickets are limited and will be allocated to those who apply first.', 'v. 分配，分派；拨给；划归', '/\'æləukeit | \'æləkeɪt | \'æləket/', 'allocate', 5);
INSERT INTO `words` VALUES (23937, 'We don’t allow diving in the pool.', 'v. 允许，准许；承认；给予；(for)考虑到', '/ə\'lau | ə\'laʊ/', 'allow', 5);
INSERT INTO `words` VALUES (23938, 'Sales staff get a generous mileage allowance or a company car.', 'n. 补贴，津贴；零用钱；减价，折扣；允许', '/ə\'lauəns | ə\'laʊəns/', 'allowance', 5);
INSERT INTO `words` VALUES (23939, 'Brass is an alloy of copper and zinc.', 'v. 使成合金；使减低成色; n. 合金', '/\'ælɔi, ə\'lɔi | \'ælɒɪ | \'ælɔɪ/', 'alloy', 5);
INSERT INTO `words` VALUES (23940, 'a meeting of the European allies', 'n. 同盟国；伙伴；同盟者；助手; v. 使联盟；使联合', '/英 [ˈælaɪ] 美 [ˈælaɪ] | \'ælaɪ/', 'ally', 5);
INSERT INTO `words` VALUES (23941, 'A car drew up alongside .', 'adv. 在旁边; prep. 和...在一起；在...旁边', '/ə\'lɔŋ\'said | əlɒŋ\'saɪd | ə\'lɔŋ\'saɪd/', 'alongside', 5);
INSERT INTO `words` VALUES (23942, 'When we were children, our father read aloud to us.', 'adv. 大声地；出声地', '/ə\'laud | ə\'laʊd/', 'aloud', 5);
INSERT INTO `words` VALUES (23943, 'The modern Russian alphabet has 31 letters.', 'n. 字母表，字母系统；入门，初步', '/\'ælfəbet | \'ælfə\'bɛt/', 'alphabet', 5);
INSERT INTO `words` VALUES (23944, 'Her face hadn’t altered much over the years.', 'v. 改变，更改; n. (Alter)人名；(英)奥尔特；(德、捷、葡、爱沙、立陶、拉脱、俄、西、罗、瑞典)阿尔特', '/\'ɔ:ltə | \'ɔːltə; \'ɒl- | \'ɔltɚ/', 'alter', 5);
INSERT INTO `words` VALUES (23945, 'The two patterns alternate over periods of two to seven years in the tropical Pacific.', 'v. 交替；轮流; adj. 交替的；轮流的; n. 替换物', '/ɔ:l\'tə:nət, \'ɔ:ltə-, \'ɔ:ltəneit | \'ɔːltəneɪt; \'ɒl- | \'ɔltɚnət/', 'alternate', 5);
INSERT INTO `words` VALUES (23946, '...alternative health care.', 'adj. 供选择的；选择性的；交替的; n. 二中择一；供替代的选择', '/ɔ:l\'tə:nətiv | ɔːl\'tɜːnətɪv; ɒl- | ɔl\'tɝnətɪv/', 'alternative', 5);
INSERT INTO `words` VALUES (23947, 'The aircraft had reached its cruising altitude of about 39,000 feet.', 'n. 高度， 海拔', '/\'æltɪtjuːd | \'æltɪtud/', 'altitude', 5);
INSERT INTO `words` VALUES (23948, 'an old custom that has vanished altogether', 'adv. 完全地；总共；总而言之; n. 整个；裸体', '/,ɔ:ltə\'ɡeðə | ɔːltə\'geðə; ɒl- | ,ɔltə\'ɡɛðɚ/', 'altogether', 5);
INSERT INTO `words` VALUES (23949, 'recycled aluminium cans', 'n. 铝', '/ˌælju\'mɪniəm | ,æljə\'mɪnɪəm/', 'aluminium', 5);
INSERT INTO `words` VALUES (23950, 'To make an aluminum can, that takes energy.', 'n. 铝', '/ə\'lju:minəm | ˌæljʊˈmɪnɪəm | ə\'lʊmɪnəm/', 'aluminum', 5);
INSERT INTO `words` VALUES (23951, 'a gifted amateur', 'n. 爱好者；业余爱好者；外行; adj. 业余的；外行的', '/\'æmətə, ,æmə\'tə: | \'æmətə; -tʃə; -tjʊə; ,æmə\'tɜː | ˈæmətər/', 'amateur', 5);
INSERT INTO `words` VALUES (23952, 'Dave amazed his friends by suddenly getting married.', 'v. 使吃惊', '/ə\'meiz | ə\'meɪz | ə\'mez/', 'amaze', 5);
INSERT INTO `words` VALUES (23953, '...the German ambassador to Poland.', 'n. 大使；特使，(派驻国际组织的)代表', '/æm\'bæsədə | æm\'bæsədɚ/', 'ambassador', 5);
INSERT INTO `words` VALUES (23954, 'The language in the Minister’s statement is highly ambiguous.', 'adj. 模糊不清的；引起歧义的', '/æm\'biɡjuəs | æm\'bɪgjʊəs | æm\'bɪɡjuəs/', 'ambiguous', 5);
INSERT INTO `words` VALUES (23955, 'He was young and full of ambition.', 'n. 野心，雄心；抱负，志向; v. 追求；有…野心', '/æm\'biʃən | æm\'bɪʃ(ə)n | æm\'bɪʃən/', 'ambition', 5);
INSERT INTO `words` VALUES (23956, 'Alfred was intensely ambitious, obsessed with the idea of becoming rich.', 'adj. 野心勃勃的；有雄心的；热望的；炫耀的', '/æm\'biʃəs | æm\'bɪʃəs/', 'ambitious', 5);
INSERT INTO `words` VALUES (23957, 'the ambulance service', 'n. [车辆][医] 救护车；战时流动医院', '/\'æmbjuləns | \'æmbjʊl(ə)ns | \'æmbjələns/', 'ambulance', 5);
INSERT INTO `words` VALUES (23958, 'The law was amended to include women.', 'v. 修改；改善，改进; n. (Amend)人名；(德、英)阿门德', '/ə\'mend | ə\'mɛnd/', 'amend', 5);
INSERT INTO `words` VALUES (23959, 'The driver was an amiable young man.', 'adj. 和蔼可亲的，亲切的; n. (Amiable)人名；(法)阿米亚布勒；(英)阿米娅布尔', '/\'eimjəbl | \'eɪmɪəb(ə)l | \'emɪəbl/', 'amiable', 5);
INSERT INTO `words` VALUES (23960, 'He sat amid the trees.', 'prep. 在…中间，在…之中，被…围绕', '/ə\'mɪd/', 'amid', 5);
INSERT INTO `words` VALUES (23961, 'Jim relaxed, knowing he was among friends .', 'prep. 在…之中；在一群(组)之中；于…之间', '/ə\'mʌŋ/', 'among', 5);
INSERT INTO `words` VALUES (23962, 'Consumer spending on sports-related items amounted to $9.75 billion.', 'vi. 合计， 总共达；等于; n. 数量， 总额', '/ə\'maunt | ə\'maʊnt/', 'amount', 5);
INSERT INTO `words` VALUES (23963, 'an ample bosom', 'adj. 丰富的；足够的；宽敞的; n. (Ample)人名；(西)安普尔', '/\'æmpl | \'æmp(ə)l/', 'ample', 5);
INSERT INTO `words` VALUES (23964, 'The transistor is an amplifier.', 'n. [电子] 放大器，扩大器；扩音器', '/\'æmplifaiə | \'æmplɪfaɪə | \'æmplɪfaɪɚ/', 'amplifier', 5);
INSERT INTO `words` VALUES (23965, 'an amplified guitar', 'v. 放大，扩大；增强；详述', '/\'æmplifai | \'æmplɪfaɪ/', 'amplify', 5);
INSERT INTO `words` VALUES (23966, 'Doing jigsaws would amuse Amy for hours on end.', 'v. 娱乐；消遣；使发笑；使愉快', '/ə\'mju:z | ə\'mjuːz | ə\'mjuz/', 'amuse', 5);
INSERT INTO `words` VALUES (23967, NULL, 'n. 类似物； 模拟 A', '/\'ænəlɒg | \'ænəlɔg/', 'analog', 5);
INSERT INTO `words` VALUES (23968, 'These may either be the drug in question or some analogue of it that.', 'n. 类似物；相似体；模拟', '/\'ænəlɔɡ | \'ænəlɒg | \'ænəlɔ:g/', 'analogue', 5);
INSERT INTO `words` VALUES (23969, 'The analogy between music and fragrance has stuck.', 'n. 类似，相似，类比，类推', '/ə\'nælədʒi | ə\'nælədʒɪ/', 'analogy', 5);
INSERT INTO `words` VALUES (23970, 'She still needs to analyse the data.', 'v. 分析；分解；细察', '/\'ænəlaiz | \'æn(ə)laɪz/', 'analyse', 5);
INSERT INTO `words` VALUES (23971, 'She’s been in analysis for three years.', 'n. 分析；分解；验定', '/ə\'næləsis | ə\'nælɪsɪs | ə\'næləsɪs/', 'analysis', 5);
INSERT INTO `words` VALUES (23972, 'For the most part, these same forces have been a boon, so far, to Americans who have a good education and exceptional creative talents or analytic skills.', 'adj. 分析的；解析的；善于分析的', '/,ænə\'litik,-kəl | ænə\'lɪtɪk | ,ænə\'lɪtɪk/', 'analytic', 5);
INSERT INTO `words` VALUES (23973, 'She’s got an analytical mind.', 'adj. 分析的； 分解的', '/ˌænə\'lɪtɪk(l) | ,ænə\'lɪtɪkl/', 'analytical', 5);
INSERT INTO `words` VALUES (23974, 'We have to analyze and solve problems.', 'vt. 分析； 分解', '/\'ænəlaɪz | \'ænə,laɪz/', 'analyze', 5);
INSERT INTO `words` VALUES (23975, 'My ancestors were French.', 'n. 始祖，祖先；被继承人', '/\'ænsestə | \'ænsɛstɚ/', 'ancestor', 5);
INSERT INTO `words` VALUES (23976, 'We dropped anchor a few yards offshore.', 'n. 锚；抛锚停泊；靠山；新闻节目主播; v. 抛锚；使固定；主持节目; adj. 末棒的；最后一棒的', '/\'æŋkə | \'æŋkɚ/', 'anchor', 5);
INSERT INTO `words` VALUES (23977, 'the ancient civilizations of Asia', 'adj. 古代的；古老的，过时的；年老的; n. 古代人；老人', '/\'einʃənt | \'eɪnʃ(ə)nt | ˈeɪnʃənt/', 'ancient', 5);
INSERT INTO `words` VALUES (23978, 'The book is full of amusing anecdotes about his life in Japan.', 'n. 轶事；奇闻；秘史', '/\'ænikdəut | \'ænɪkdəʊt | \'ænɪkdot/', 'anecdote', 5);
INSERT INTO `words` VALUES (23979, 'the angel Gabriel', 'n. 天使；守护神；善人; vt. 出钱支持', '/\'eindʒəl | \'eɪndʒ(ə)l | \'endʒl/', 'angel', 5);
INSERT INTO `words` VALUES (23980, 'There is growing anger among the people against the government.', 'n. 怒，愤怒；忿怒; v. 使发怒，激怒；恼火', '/\'æŋɡə | \'æŋgə | \'æŋɡɚ/', 'anger', 5);
INSERT INTO `words` VALUES (23981, 'You didn’t measure the angle accurately.', 'v. 钓鱼；谋取; n. 角度，角，方面', '/\'æŋg(ə)l | \'æŋɡl/', 'angle', 5);
INSERT INTO `words` VALUES (23982, 'I was angry because he hadn’t told me his plans.', 'adj. 生气的；愤怒的；狂暴的；（伤口等）发炎的', '/\'æŋɡri | \'æŋgrɪ/', 'angry', 5);
INSERT INTO `words` VALUES (23983, 'the anguish of not knowing what had happened to her', 'n. 痛苦；苦恼; v. 使极度痛苦', '/\'æŋɡwiʃ | \'æŋgwɪʃ | \'æŋɡwɪʃ/', 'anguish', 5);
INSERT INTO `words` VALUES (23984, 'slender ankles', 'n. 踝关节，踝', '/\'æŋkl | \'æŋk(ə)l/', 'ankle', 5);
INSERT INTO `words` VALUES (23985, 'Jack and Kim celebrated their twentieth wedding anniversary in January.', 'n. 周年，周年纪念日', '/,æni\'və:səri | ænɪ\'vɜːs(ə)rɪ | ,ænɪ\'vɝsəri/', 'anniversary', 5);
INSERT INTO `words` VALUES (23986, 'They announced their engagement in ‘The Times’.', 'v. 正式宣布；发表；通告；广播（电台节目）', '/ə\'nauns | ə\'naʊns/', 'announce', 5);
INSERT INTO `words` VALUES (23987, 'He is not doing this to annoy you.', 'v. 骚扰；惹恼；打搅; n. 烦恼（等于annoyance）', '/ə\'nɔi | ə\'nɒɪ | ə\'nɔɪ/', 'annoy', 5);
INSERT INTO `words` VALUES (23988, 'The school trip has become an annual event.', 'adj. 年度的；每年的; n. 年刊，年鉴；一年生植物', '/\'ænjuəl | \'ænjʊəl/', 'annual', 5);
INSERT INTO `words` VALUES (23989, 'the anonymous author of a collection of poems', 'adj. 匿名的，无名的，姓氏不明的', '/ə\'nɔniməs | ə\'nɒnɪməs | ə\'nɑnəməs/', 'anonymous', 5);
INSERT INTO `words` VALUES (23990, 'television antennas', 'n. [电讯] 天线；[动] 触角，[昆] 触须', '/æn\'tenə | æn\'tɛnə/', 'antenna', 5);
INSERT INTO `words` VALUES (23991, 'Sales are better than anticipated.', 'v. 预料；期望；预先考虑；抢先；提前使用', '/æn\'tisipeit | æn\'tɪsɪpeɪt | æn\'tɪsə\'pet/', 'anticipate', 5);
INSERT INTO `words` VALUES (23992, 'an antique rosewood desk', 'adj. 古老的，年代久远的；过时的，古董的；古风的，古式的; n. 古董，古玩；古风，古希腊和古罗马艺术风格; v. 觅购古玩', '/æn\'ti:k | æn\'tiːk | æn\'tik/', 'antique', 5);
INSERT INTO `words` VALUES (23993, 'his feelings of anxiety', 'n. 焦虑；渴望；挂念；令人焦虑的事', '/æŋ\'zaiəti | æŋ\'zaɪətɪ | æŋ\'zaɪəti/', 'anxiety', 5);
INSERT INTO `words` VALUES (23994, 'She gave me an anxious look.', 'adj. 焦虑的；担忧的；渴望的；急切的', '/\'ænkʃəs | \'æŋ(k)ʃəs | \'æŋkʃəs/', 'anxious', 5);
INSERT INTO `words` VALUES (23995, 'The scandal could damage her reputation but the press reported it anyhow.', 'adv. 不管怎样， 无论如何； 不论用何种办法<', '/\'enɪhau | \'ɛnɪ\'haʊ/', 'anyhow', 5);
INSERT INTO `words` VALUES (23996, 'They have offices in countries as far apart as India and Peru.', 'adv. 分离，离开，隔开; adj. 分离的，分隔的', '/ə\'pɑ:t | ə\'pɑːt | ə\'pɑrt/', 'apart', 5);
INSERT INTO `words` VALUES (23997, 'She lives in a small apartment.', 'n. [英]房间，套间；[美]公寓', '/ə\'pɑ:tmənt | ə\'pɑːtm(ə)nt | ə\'pɑrtmənt/', 'apartment', 5);
INSERT INTO `words` VALUES (23998, '...chimpanzees and other apes.', 'n. 猿 <; vt. 模仿', '/eɪp | ep/', 'ape', 5);
INSERT INTO `words` VALUES (23999, 'When he received the letter he offered to apologise and to change his comments, but the club rejected this.', 'v. (to,for)道歉，认错', '/ə\'pɔlədʒaiz | ə\'pɒlədʒaɪz | ə\'pɔlədʒaɪz/', 'apologise', 5);
INSERT INTO `words` VALUES (24000, 'Edward can’t be here today, but he sends his apologies .', 'n. 道歉，认错，辩解，辩护', '/ə\'pɔlədʒi | ə\'pɒlədʒɪ | ə\'pɑlədʒi/', 'apology', 5);
INSERT INTO `words` VALUES (24001, 'The way we kill animals appals a lot of people.', 'v. 使惊骇，使恐怖', '/ə\'pɔ:l | ə\'pɔːl | ə\'pɔl/', 'appal', 5);
INSERT INTO `words` VALUES (24002, NULL, 'vt. 使惊骇， 使恐怖', '/ə\'pɔːl | ə\'pɔl/', 'appall', 5);
INSERT INTO `words` VALUES (24003, 'Astronauts have special breathing apparatus.', 'n. 器械，器具，仪器；机构，组织', '/ˌæpəˈreɪtəs | ˌæpəˈrætəs/', 'apparatus', 5);
INSERT INTO `words` VALUES (24004, 'The difference in quality was immediately apparent .', 'adj. 表面上的,貌似真实的；显然的,明明白白的', '/ə\'pærənt | ə\'pær(ə)nt/', 'apparent', 5);
INSERT INTO `words` VALUES (24005, 'She is not happy with the decision and plans to appeal.', 'v. 呼吁，恳求；上诉；诉诸，求助；有吸引力，迎合爱好；（体育比赛中）诉诸裁判; n. 呼吁，请求；吸引力，感染力；上诉；诉诸裁判', '/ə\'pi:l | ə\'piːl | ə\'pil/', 'appeal', 5);
INSERT INTO `words` VALUES (24006, 'He was always criticising his wife’s appearance.', 'n. 外貌，外观；出现，露面', '/ə\'piərəns | ə\'pɪər(ə)ns | ə\'pɪrəns/', 'appearance', 5);
INSERT INTO `words` VALUES (24007, 'Christine had to go into hospital to have her appendix out (= have it removed ) .', 'n. 附录；阑尾；附加物', '/ə\'pendiks | ə\'pendɪks | ə\'pɛndɪks/', 'appendix', 5);
INSERT INTO `words` VALUES (24008, 'Her husband always had a huge appetite.', 'n. 食欲，胃口；欲望，性欲；爱好，趣味', '/\'æpitait | \'æpɪtaɪt/', 'appetite', 5);
INSERT INTO `words` VALUES (24009, 'I applaud the decision to install more security cameras.', 'v. 赞同；称赞；向…喝彩', '/ə\'plɔːd | ə\'plɔd/', 'applaud', 5);
INSERT INTO `words` VALUES (24010, 'She got a round of applause (= a short period of applause ) when she finished.', 'n. 欢呼，喝采；鼓掌欢迎', '/ə\'plɔ:z | ə\'plɔːz | ə\'plɔz/', 'applause', 5);
INSERT INTO `words` VALUES (24011, 'apple pie', 'n. 苹果，苹果树，苹果似的东西；[美俚]炸弹，手榴弹，（棒球的）球；[美俚]人，家伙。', '/\'æp(ə)l | \'æpl/', 'apple', 5);
INSERT INTO `words` VALUES (24012, 'The device most often used to do this is a load balancer, which is an appliance that accepts requests from the outside world and hands them off to the next available application server.', 'n. 器具；器械；装置', '/ə\'plaiəns | ə\'plaɪəns/', 'appliance', 5);
INSERT INTO `words` VALUES (24013, 'What is a reasonable standard for one family is not applicable for another.', 'adj. 可适用的；可应用的；合适的', '/\'æplikəbl, ə\'plikə- | ə\'plɪkəb(ə)l; \'æplɪk- | \'æplɪkəbl/', 'applicable', 5);
INSERT INTO `words` VALUES (24014, 'We receive hundreds of job applications each year.', 'n. 应用；申请；应用程序；敷用', '/,æpli\'keiʃən | ˌæplɪ\'keɪʃ(ə)n | ˌæpləˈkeʃən/', 'application', 5);
INSERT INTO `words` VALUES (24015, 'We need to apply for planning permission to build a garage.', 'v. 申请；涂，敷；应用', '/ə\'plai | ə\'plaɪ/', 'apply', 5);
INSERT INTO `words` VALUES (24016, 'officials appointed by the government', 'v. 任命；指定；约定', '/ə\'pɔint | ə\'pɒɪnt | ə\'pɔɪnt/', 'appoint', 5);
INSERT INTO `words` VALUES (24017, 'All consultations are by appointment only .', 'n. 任命；约定；任命的职位', '/ə\'pɔintmənt | ə\'pɒɪntm(ə)nt | ə\'pɔɪntmənt/', 'appointment', 5);
INSERT INTO `words` VALUES (24018, 'What is needed in such cases is a calm appraisal of the situation.', 'n. 对...作出的评价；评价，鉴定，评估; v. 赞扬,歌颂;表扬; n. 称赞,赞美;赞美的话', '/ə\'preizəl | ə\'preɪz(ə)l | ə\'prezl/', 'appraisal', 5);
INSERT INTO `words` VALUES (24019, 'Thanks ever so much for your help, I really appreciate it.', 'v. 为...表示感激，感谢；欣赏，赏识，评价', '/ə\'pri:ʃieit | ə\'priːʃɪeɪt; -sɪ- | ə\'priʃɪet/', 'appreciate', 5);
INSERT INTO `words` VALUES (24020, 'As I approached the house, I noticed a light on upstairs.', 'v. 靠近， 接近， 邻近; n. 方法， 途径；探讨； 试探', '/ə\'prəutʃ | ə\'protʃ/', 'approach', 5);
INSERT INTO `words` VALUES (24021, 'The timing of the announcement was particularly appropriate .', 'adj. 适当的恰当的特有的vt.拨给,挪用,盗用', '/ə\'prəʊprɪət | əˈpropriɪt/', 'appropriate', 5);
INSERT INTO `words` VALUES (24022, 'The president has already given his approval to the plan.', 'n. 批准，通过；赞成，同意', '/ə\'pru:vəl | ə\'pruːv(ə)l | əˈpruvl/', 'approval', 5);
INSERT INTO `words` VALUES (24023, 'The conference approved a proposal for a referendum.', 'v. (of)赞成，赞许，同意；批准，审议，通过', '/ə\'pru:v | ə\'pruːv | ə\'prʊv/', 'approve', 5);
INSERT INTO `words` VALUES (24024, 'For each approximate solution of a parameterized problem, the app also displays the margin of error.', 'adj. 近似的; v. (to)接近; adj. sim', '/ə\'prɔksimit | ə\'prɒksɪmət | ə\'prɑksɪmət/', 'approximate', 5);
INSERT INTO `words` VALUES (24025, 'The changes will be introduced in April.', 'n. 四月', '/\'eiprəl | \'eɪprəl | \'eprəl/', 'april', 5);
INSERT INTO `words` VALUES (24026, '‘Love at first sight’ is a very apt description of how he felt when he saw her.', 'adj. 恰当的；有…倾向的；灵敏的; n. (Apt)人名；(法、波、英)阿普特', '/æpt/', 'apt', 5);
INSERT INTO `words` VALUES (24027, 'an arbitrary decision', 'adj. [数] 任意的；武断的；专制的', '/\'ɑ:bitrəri | \'ɑːbɪt(rə)rɪ | ˈɑːrbətreri/', 'arbitrary', 5);
INSERT INTO `words` VALUES (24028, 'When she passed under the arch leading out of the park, Mira whooped with delight.', 'n. 弓形，拱形；拱门; adj. 主要的; v. 使…弯成弓形；用拱连接', '/ɑ:tʃ | ɑːtʃ | ɑrtʃ/', 'arch', 5);
INSERT INTO `words` VALUES (24029, 'I have a passion for archaeology .', 'n. 考古学', '/ˌɑːki\'ɒlədʒi | ,ɑrkɪ\'ɑlədʒi/', 'archaeology', 5);
INSERT INTO `words` VALUES (24030, 'He has been studying archeology these thirty years.', 'n. 考古学', '/ˌɑːki\'ɒlədʒi | ,ɑrki\'ɑlədʒi/', 'archeology', 5);
INSERT INTO `words` VALUES (24031, 'Tinoco was one of the architects of the government’s economic reforms.', 'n. 建筑师；设计师；缔造者；创造者', '/\'ɑ:kitekt | \'ɑːkɪtekt | \'ɑrkɪtɛkt/', 'architect', 5);
INSERT INTO `words` VALUES (24032, 'He studied architecture at university.', 'n. 建筑，建筑学；建筑式样或风格，建筑物', '/\'ɑːkɪtektʃə | \'ɑrkə\'tɛktʃɚ/', 'architecture', 5);
INSERT INTO `words` VALUES (24033, 'We could hear the neighbours arguing.', 'v. 争论，辩论；提出理由; n. (Argue)人名；(英、法)阿格', '/\'ɑɡju: | \'ɑːgjuː | \'ɑrgjʊ/', 'argue', 5);
INSERT INTO `words` VALUES (24034, 'We need to provide a convincing argument as to why the system should be changed.', 'n. 论证；论据；争吵；内容提要', '/\'ɑ:ɡjumənt | \'ɑːgjʊm(ə)nt | \'ɑrɡjumənt/', 'argument', 5);
INSERT INTO `words` VALUES (24035, 'A crisis has arisen in the Foreign Office.', 'v. 出现；上升；起立; n. (Arise)人名；(西)阿里塞；(日)在濑(姓)', '/ə\'raiz | ə\'raɪz/', 'arise', 5);
INSERT INTO `words` VALUES (24036, '...teaching the basics of reading, writing and arithmetic.', 'n. 算术，四则运算', '/ə\'riθmətik, ,æriθ\'metik | ə\'rɪθmətɪk/', 'arithmetic', 5);
INSERT INTO `words` VALUES (24037, 'Dave has a broken arm .', 'n. 手臂；武器；袖子；装备；部门; v. 武装起来', '/ɑːm | ɑrm/', 'arm', 5);
INSERT INTO `words` VALUES (24038, 'The army are helping to clear up after the floods.', 'n. 陆军，军队', '/\'ɑ:mi | \'ɑːmɪ | \'ɑrmi/', 'army', 5);
INSERT INTO `words` VALUES (24039, 'Matt’s behavior was arousing the interest of the neighbors.', 'v. 引起；唤醒；鼓励', '/ə\'rəuz | ə\'raʊz/', 'arouse', 5);
INSERT INTO `words` VALUES (24040, 'Contact your local branch to arrange an appointment.', 'vt. 整理， 排列， 布置 A；安排， 筹备', '/ə\'reɪndʒ | ə\'rendʒ/', 'arrange', 5);
INSERT INTO `words` VALUES (24041, 'a bewildering array of options', 'n. 数组，阵列；排列，列阵；大批，一系列；衣服; v. 排列，部署；打扮', '/ə\'rei | ə\'reɪ | ə\'re/', 'array', 5);
INSERT INTO `words` VALUES (24042, 'He was arrested and charged with murder.', 'v. 逮捕；阻止；吸引; n. 逮捕；监禁', '/ə\'rest | ə\'rɛst/', 'arrest', 5);
INSERT INTO `words` VALUES (24043, 'Only the timely arrival of the police prevented the situation from becoming worse.', 'n. 到来；到达；到达者', '/ə\'raivəl | ə\'raɪv(ə)l | ə\'raɪvəl/', 'arrival', 5);
INSERT INTO `words` VALUES (24044, 'He was unbearably arrogant.', 'adj. 自大的，傲慢的', '/\'ærəɡənt | \'ærəg(ə)nt/', 'arrogant', 5);
INSERT INTO `words` VALUES (24045, 'Follow the arrows to the X-ray department.', 'n. 箭，箭头；箭状物；箭头记号; vt. 以箭头指示；箭一般地飞向', '/\'ærəu | \'ærəʊ | \'æro/', 'arrow', 5);
INSERT INTO `words` VALUES (24046, 'the Museum of Modern Art in New York', 'n. 艺术，美术；技术，技艺；文科，人文科学', '/ɑ:t | ɑːt | ɑrt/', 'art', 5);
INSERT INTO `words` VALUES (24047, '...Connecticut Ave., one of the main arteries of Washington.', 'n. 动脉；干线，要道', '/\'ɑːtərɪ | \'ɑrtəri/', 'artery', 5);
INSERT INTO `words` VALUES (24048, 'The paper’s leading article (= the main article ) described the government as weak.', 'n. 文章，论文；条款，条文；物件；冠词', '/\'ɑ:tikəl | \'ɑːtɪk(ə)l | \'ɑrtɪkl/', 'article', 5);
INSERT INTO `words` VALUES (24049, 'She is an articulate young woman.', 'adj. 善于表达的；有关节相连的; v. 清楚地讲话', '/ɑ:\'tɪkjʊleɪt | ɑr\'tɪkjulet/', 'articulate', 5);
INSERT INTO `words` VALUES (24050, 'artificial flowers', 'adj. 人工的，人造的，人为的；虚伪的，做作的', '/,ɑ:ti\'fiʃəl | ɑːtɪ\'fɪʃ(ə)l | ,ɑrtɪ\'fɪʃl/', 'artificial', 5);
INSERT INTO `words` VALUES (24051, 'an exhibition of paintings by local artists', 'n. 艺术家，美术家；(某方面的)能手', '/\'ɑ:tist | \'ɑːtɪst | \'ɑrtɪst/', 'artist', 5);
INSERT INTO `words` VALUES (24052, 'artistic work', 'adj. 艺术(家)的，美术(家)的；善于艺术创作的', '/ɑ:\'tistik | ɑː\'tɪstɪk | ɑr\'tɪstɪk/', 'artistic', 5);
INSERT INTO `words` VALUES (24053, 'The plane ascended rapidly.', 'v. 上升；登高；追溯', '/ə\'send | ə\'sɛnd/', 'ascend', 5);
INSERT INTO `words` VALUES (24054, 'A postmortem was ordered to try to ascertain the cause of death.', 'v. 确定，查明，弄清', '/,æsə\'tein | ,æsə\'teɪn | \'æsɚ\'ten/', 'ascertain', 5);
INSERT INTO `words` VALUES (24055, 'cigarette ash', 'n. 灰；灰烬', '/æʃ/', 'ash', 5);
INSERT INTO `words` VALUES (24056, 'Everyone cries sometimes – it’s nothing to be ashamed of.', 'adj. 惭愧的，感到难为情的；耻于……的', '/ə\'ʃeimd | ə\'ʃeɪmd | ə\'ʃemd/', 'ashamed', 5);
INSERT INTO `words` VALUES (24057, 'Several dead birds had been washed ashore.', 'adv. 在岸上；向岸; adj. 在岸上的；在陆上的', '/ə\'ʃɔ: | ə\'ʃɔː | ə\'ʃɔr/', 'ashore', 5);
INSERT INTO `words` VALUES (24058, 'He pushed his half-eaten salad aside and left.', 'adv. 在旁边，到一边; n. 旁白；离题的话', '/ə\'said | ə\'saɪd/', 'aside', 5);
INSERT INTO `words` VALUES (24059, 'Quiet! The baby’s asleep.', 'adj. 睡着的；麻木的；长眠的; adv. 熟睡地；进入睡眠状态', '/ə\'sli:p | ə\'sliːp | ə\'slip/', 'asleep', 5);
INSERT INTO `words` VALUES (24060, 'The storm outside gave the room a sinister aspect.', 'n. 样子, 外表, 面貌, (问题等的)方面', '/\'æspekt | \'æspɛkt/', 'aspect', 5);
