INSERT INTO `words` VALUES (24062, 'a plot to assassinate the President', 'v. 暗杀；行刺', '/ə\'sæsineit | ə\'sæsɪneɪt | ə\'sæsn\'et/', 'assassinate', 5);
INSERT INTO `words` VALUES (24063, 'The refugee camp came under assault again last night.', 'n. 攻击；袭击; v. 攻击；袭击', '/ə\'sɔ:lt | ə\'sɔːlt; ə\'sɒlt | ə\'sɔlt/', 'assault', 5);
INSERT INTO `words` VALUES (24064, 'A large crowd had assembled outside the American embassy.', 'v. 集合，聚集；装配；收集', '/ə\'sembl | ə\'semb(ə)l | ə\'sɛmbl/', 'assemble', 5);
INSERT INTO `words` VALUES (24065, 'Police have imposed conditions on public assemblies.', 'n. 集合；会议；装配；(美)洲议会的众议院', '/ə\'sembli | ə\'semblɪ | ə\'sɛmbli/', 'assembly', 5);
INSERT INTO `words` VALUES (24066, 'French cooking, she asserted, is the best in the world.', 'v. 维护，坚持；断言；主张；声称', '/ə\'sə:t | ə\'sɜːt | ə\'sɝt/', 'assert', 5);
INSERT INTO `words` VALUES (24067, 'The test was to assess aptitude rather than academic achievement.', 'v. 评定；估价；对…征税', '/ə\'ses | ə\'sɛs/', 'assess', 5);
INSERT INTO `words` VALUES (24068, 'the value of a company’s assets', 'n. 资产， 财产；优点； 有用的东西', '/\'æset | \'æsɛt/', 'asset', 5);
INSERT INTO `words` VALUES (24069, 'How much time have you assigned for the meeting?', 'v. 派给，分配；选定，指定(时间、地点等)', '/ə\'sain | ə\'saɪn/', 'assign', 5);
INSERT INTO `words` VALUES (24070, 'a history assignment', 'n. 分配，指派；(指定的)作业，任务', '/ə\'sainmənt | ə\'saɪnm(ə)nt | ə\'saɪnmənt/', 'assignment', 5);
INSERT INTO `words` VALUES (24071, 'It will take time to assimilate all these facts.', 'v. 吸收，消化；使同化; v. 被吸收；被同化', '/ə\'simileit | ə\'sɪmɪleɪt | ə\'sɪməlet/', 'assimilate', 5);
INSERT INTO `words` VALUES (24072, 'The family decided to assist me with my chores.', 'v. 协助，帮助，促进; v. 帮忙，参加', '/ə\'sist | ə\'sɪst/', 'assist', 5);
INSERT INTO `words` VALUES (24073, 'We offer financial assistance to students.', 'n. 协作; 援助; 帮助', '/ə\'sistəns | ə\'sɪst(ə)ns | ə\'sɪstəns/', 'assistance', 5);
INSERT INTO `words` VALUES (24074, '...the assistant secretary of defence.', 'adj. 帮助的，辅助的; n. 助手，助教；辅助物', '/ə\'sistənt | ə\'sɪst(ə)nt | ə\'sɪstənt/', 'assistant', 5);
INSERT INTO `words` VALUES (24075, 'I don’t like these layabouts you’re associating with.', 'v. 交往；结交; n. 同事，伙伴；关联的事物; adj. 副的；联合的', '/ə\'səuʃieit, ə\'səuʃiət, -eit | ə\'səʊʃɪeɪt; -sɪeɪt | ə\'soʃɪet/', 'associate', 5);
INSERT INTO `words` VALUES (24076, 'the Association of Master Builders', 'n. 协会，联盟，社团；联合；联想', '/ə,səusi\'eiʃən, ə,səuʃi\'ei- | əsəʊsɪ\'eɪʃ(ə)n; -ʃɪ- | ə,soʃɪ\'eʃən/', 'association', 5);
INSERT INTO `words` VALUES (24077, 'I think we can safely assume (= it is almost certain ) that interest rates will go up again soon.', 'v. 假装；假定，设想；承担；呈现，采取', '/ə\'sjuːm | ə\'sum/', 'assume', 5);
INSERT INTO `words` VALUES (24078, 'You would be making an assumption that\'s not based on any fact that you could report.', 'n. 假定，设想；采取；承担；推测；假装', '/ə\'sʌmpʃən | ə\'sʌm(p)ʃ(ə)n/', 'assumption', 5);
INSERT INTO `words` VALUES (24079, 'Despite my repeated assurances, Rob still looked very nervous.', 'n. 保证，担保；（人寿）保险；确信；断言；厚脸皮，无耻', '/ə\'ʃʊər(ə)ns | ə\'ʃʊrəns/', 'assurance', 5);
INSERT INTO `words` VALUES (24080, 'The document is genuine, I can assure you .', 'v. 保证；担保；使确信；弄清楚', '/ə\'ʃuə | ə\'ʃʊə; ə\'ʃɔː | ə\'ʃʊr/', 'assure', 5);
INSERT INTO `words` VALUES (24081, 'Her reply astonished me.', 'v. 使惊讶', '/ə\'stɔniʃ | ə\'stɒnɪʃ | ə\'stɑnɪʃ/', 'astonish', 5);
INSERT INTO `words` VALUES (24082, 'So why become an astronaut at all?', 'n. 宇航员，航天员；太空旅行者', '/\'æstrənɔ:t | \'æstrənɔːt | \'æstrə\'nɔt/', 'astronaut', 5);
INSERT INTO `words` VALUES (24083, 'Do you know anything about astronomy?', 'n. n．天文学', '/ə\'strɔnəmi | ə\'strɒnəmɪ | ə\'strɑnəmi/', 'astronomy', 5);
INSERT INTO `words` VALUES (24084, 'a professional athlete', 'n. 运动员，体育家；身强力壮的人', '/\'æθli:t | \'æθliːt | \'æθlit/', 'athlete', 5);
INSERT INTO `words` VALUES (24085, 'The hotel had a lovely relaxed atmosphere .', 'n. 气氛；大气；空气', '/\'ætməsfɪə | \'ætməsfɪr/', 'atmosphere', 5);
INSERT INTO `words` VALUES (24086, 'carbon atoms', 'n. 原子；微粒，微量', '/\'ætəm/', 'atom', 5);
