INSERT INTO `words` VALUES (24088, 'More women are attaining positions of power.', 'v. 达到；完成；获得; v. 达到', '/ə\'tein | ə\'teɪn | ə\'ten/', 'attain', 5);
INSERT INTO `words` VALUES (24089, 'Weather conditions prevented them from attempting the jump.', 'v. 企图，试图; n. 努力，尝试，企图', '/ə\'tempt | ə\'tem(p)t | ə\'tɛmpt/', 'attempt', 5);
INSERT INTO `words` VALUES (24090, 'Only 12 people attended the meeting.', 'v. 出席；上（大学等）；照料；招待；陪伴', '/ə\'tend | ə\'tɛnd/', 'attend', 5);
INSERT INTO `words` VALUES (24091, 'We have an average attendance of 4,000 fans per game.', 'n. 出席；到场；出席人数；考勤', '/ə\'tend(ə)ns | ə\'tɛndəns/', 'attendance', 5);
INSERT INTO `words` VALUES (24092, 'Such patients run an increased probability of hospitalization, with all the attendant costs to the patient and to the health care system that hospitalization entails.', 'adj. 伴随的；侍候的; n. 服务员，侍者；随员，陪从', '/ə\'tendənt | ə\'tend(ə)nt | ə\'tɛndənt/', 'attendant', 5);
INSERT INTO `words` VALUES (24093, 'My attention wasn’t really on the game.', 'n. 注意力；关心；立正！（口令）', '/ə\'tenʃən | ə\'tenʃ(ə)n | ə\'tɛnʃən/', 'attention', 5);
INSERT INTO `words` VALUES (24094, 'As soon as they found out I was a doctor, their whole attitude changed.', 'n. 态度；看法；意见；姿势', '/\'ætɪtjuːd, -tuːd | \'ætɪtjuːd | \'ætɪtʊd/', 'attitude', 5);
