INSERT INTO `words` VALUES (24096, 'I’m not usually attracted to blondes.', 'v. 引起的注意(或兴趣等),吸引；引起；激起', '/ə\'trækt/', 'attract', 5);
INSERT INTO `words` VALUES (24097, 'Kitchen utensils should be attractive as well as functional.', 'adj. 吸引人的，引人注意的；漂亮的，迷人的', '/ə\'træktiv | ə\'træktɪv/', 'attractive', 5);
INSERT INTO `words` VALUES (24098, 'What attributes should a good manager possess?', 'n. 属性；特质; v. 归属；把…归于', '/ə\'tribju:t, \'ætribju:t | ə\'trɪbjuːt | ə\'trɪbjut/', 'attribute', 5);
INSERT INTO `words` VALUES (24099, 'Eight drawings by French artist Jean Cocteau will be auctioned next week.', 'v. 拍卖；竞卖; n. 拍卖', '/\'ɔ:kʃən | \'ɔːkʃ(ə)n | \'ɔkʃən/', 'auction', 5);
INSERT INTO `words` VALUES (24100, 'The audience began clapping and cheering.', 'n. 观众；听众；读者；接见；正式会见；拜会', '/\'ɔːdɪəns | \'ɔdɪəns/', 'audience', 5);
INSERT INTO `words` VALUES (24101, 'audio and video equipment', 'adj. 声音的；[声] 音频的，[声] 声频的', '/\'ɔ:diəu | \'ɔːdɪəʊ | \'ɔdɪo/', 'audio', 5);
INSERT INTO `words` VALUES (24102, 'Each year they audit our accounts and certify them as being true and fair.', 'v. 审计；[审计] 查账; n. 审计；[审计] 查账', '/\'ɔːdɪt | \'ɔdɪt/', 'audit', 5);
