INSERT INTO `words` VALUES (24104, 'Any surplus was sold to augment their income.', 'v. 增加；增大; n. 增加；增大', '/ɔ:ɡ\'ment, \'ɔ:gmənt | ɔːg\'ment | ɔɡ\'mɛnt/', 'augment', 5);
