INSERT INTO `words` VALUES (24114, 'the automobile industry', 'n. 汽车', '/\'ɔːtəməbɪːl | ,ɔtəmə\'bil/', 'automobile', 5);
INSERT INTO `words` VALUES (24115, 'campaigners who want greater autonomy for Corsica', 'n. 自治，自治权；', '/ɔ:\'tɔnəmi | ɔː\'tɒnəmɪ | ɔ\'tɑnəmi/', 'autonomy', 5);
INSERT INTO `words` VALUES (24116, 'autumn mists', 'n. 秋天；成熟期；渐衰期，凋落期; adj. 秋天的，秋季的', '/\'ɔ:təm | \'ɔːtəm | \'ɔtəm/', 'autumn', 5);
INSERT INTO `words` VALUES (24117, 'a nursing auxiliary', 'n. 助动词；辅助者，辅助物；附属机构; adj. 辅助的；副的；附加的', '/ɔ:ɡ\'ziljəri | ɔːg\'zɪlɪərɪ; ɒg- | ɔːɡ\'zɪlɪəri/', 'auxiliary', 5);
INSERT INTO `words` VALUES (24118, 'We searched the whole area but all to no avail. Robbie had disappeared.', 'n. 效用，利益; v. 有益于，有益于；使对某人有利。', '/ə\'veɪl | ə\'vel/', 'avail', 5);
INSERT INTO `words` VALUES (24119, 'Tickets are available from the box office.', 'adj. 可用的， 可得到的；可以见到的， 随时可来的', '/ə\'veɪləbl | ə\'veləbl/', 'available', 5);
INSERT INTO `words` VALUES (24120, 'Fifth Avenue', 'n. 林荫路，大街；(比喻)途径，渠道，方法', '/\'æv(ə)njuː | \'ævənu/', 'avenue', 5);
INSERT INTO `words` VALUES (24121, 'The December figures brought the annual average for 2001 up to 10.6 per cent.', 'n. 平均,平均数; adj. 平均的；普通的; v. 平均', '/\'æv(ə)rɪdʒ | \'ævərɪdʒ/', 'average', 5);
INSERT INTO `words` VALUES (24122, 'The tragedy could have been averted if the crew had followed safety procedures.', 'v. 防止，避免 ；转移(目光、注意力等)', '/ə\'və:t | ə\'vɜːt | ə\'vɝt/', 'avert', 5);
INSERT INTO `words` VALUES (24123, '...the aviation industry.', 'n. 航空；飞行术；飞机制造业', '/,eivi\'eiʃən | eɪvɪ\'eɪʃ(ə)n | ,evɪ\'eʃən/', 'aviation', 5);
INSERT INTO `words` VALUES (24124, 'Road safety is taught to young children to avoid road accidents.', 'v. 防止，避免；逃避，避开', '/ə\'vɔid | ə\'vɒɪd | ə\'vɔɪd/', 'avoid', 5);
INSERT INTO `words` VALUES (24125, 'Several men are awaiting trial for robbery.', 'v. 等候，等待；期待', '/ə\'weit | ə\'weɪt | ə\'wet/', 'await', 5);
INSERT INTO `words` VALUES (24126, 'It was midday when she awoke.', 'v. 觉醒，意识到；醒来；被唤起; adj. 醒着的', '/ə\'weik | ə\'weɪk | ə\'wek/', 'awake', 5);
INSERT INTO `words` VALUES (24127, 'Moodie has been awarded a golf scholarship at the University of Hawaii.', 'v. 授予；判定; n. 奖品；判决', '/ə\'wɔ:d | ə\'wɔːd | ə\'wɔrd/', 'award', 5);
INSERT INTO `words` VALUES (24128, 'Mr Braley has been made aware of the need for absolute secrecy.', 'adj. 意识到的；知道的；有…方面知识的；懂世故的; n. (Aware)人名；(阿拉伯、索)阿瓦雷', '/ə\'wεə | ə\'weə | ə\'wɛr/', 'aware', 5);
INSERT INTO `words` VALUES (24129, 'The girls were awed by the splendour of the cathedral.', 'v. 使敬畏；使畏怯; n. 敬畏', '/ɔ: | ɔː | ɔ/', 'awe', 5);
