INSERT INTO `words` VALUES (24136, 'Students with a background in chemistry will probably find the course easier.', 'n. 背景；隐蔽的位置; v. 作…的背景; adj. 背景的；发布背景材料的', '/\'bækɡraund | \'bækgraʊnd | \'bækɡraʊnd/', 'background', 5);
INSERT INTO `words` VALUES (24137, 'She went without a backward glance.', 'adj. 向后的；反向的；发展迟缓的; adv. 向后地；相反地', '/\'bækwəd | \'bækwɚd/', 'backward', 5);
INSERT INTO `words` VALUES (24138, 'bacon and eggs', 'n. 咸肉；腌肉；熏猪肉', '/\'beikən | \'beɪk(ə)n | \'bekən/', 'bacon', 5);
INSERT INTO `words` VALUES (24139, 'It was so large and complex, they initially assumed it was a bacterium.', 'n. 细菌', '/bæk\'tiəriəm | bæk\'tɪərɪəm | bæk\'tɪrɪəm/', 'bacterium', 5);
INSERT INTO `words` VALUES (24140, 'We were each handed a badge with our name on it.', 'n. 徽章；证章；标记; v. 授给…徽章', '/\'bædʒ | bædʒ/', 'badge', 5);
INSERT INTO `words` VALUES (24141, 'Can I try you new badminton racket?', 'n. 羽毛球', '/\'bædmintən | \'bædmɪnt(ə)n | \'bædmɪntən/', 'badminton', 5);
