INSERT INTO `words` VALUES (24143, 'Check your baggage in at the desk.', 'n. 行李；[交] 辎重（军队的）', '/\'bæɡidʒ | \'bægɪdʒ | \'bæɡɪdʒ/', 'baggage', 5);
INSERT INTO `words` VALUES (24144, 'Carpenter is free on bail while he appeals his conviction.', 'n. 保释; vt. 保释 <；帮助脱离困境<', '/beɪl | bel/', 'bail', 5);
