INSERT INTO `words` VALUES (24146, 'I’m baking some bread.', 'v. 烤，烘焙; n. 烤；烘烤食品', '/beik | beɪk | bek/', 'bake', 5);
INSERT INTO `words` VALUES (24147, 'I lost my balance and fell on my face.', 'n. 平衡；余额；匀称; v. 使平衡；结算；使相称', '/\'bæləns | \'bæl(ə)ns/', 'balance', 5);
INSERT INTO `words` VALUES (24148, 'Has your flat got a balcony?', 'n. 阳台；包厢；戏院楼厅', '/\'bælkəni | \'bælkənɪ/', 'balcony', 5);
INSERT INTO `words` VALUES (24149, 'a bald man', 'adj. 秃顶的；光秃的；单调的；无装饰的; v. 变秃; n. (Bald)人名；(英)鲍尔德；(德、法、波)巴尔德', '/bɔ:ld | bɔːld | bɔld/', 'bald', 5);
INSERT INTO `words` VALUES (24150, 'We’re going to the ballet tomorrow evening.', 'n. 芭蕾舞剧；芭蕾舞乐曲', '/\'bælei, bæ\'lei | \'bæleɪ; -lɪ | bæ\'le/', 'ballet', 5);
INSERT INTO `words` VALUES (24151, 'The company’s debt has ballooned in the past year.', 'v. 激增；膨胀如气球; n. 气球; adj. 像气球般鼓起的', '/bə\'lu:n | bə\'luːn | bə\'lun/', 'balloon', 5);
INSERT INTO `words` VALUES (24152, 'The party leader is elected by secret ballot .', 'n. 投票；投票用纸；投票总数; v. 投票；抽签决定', '/\'bælət/', 'ballot', 5);
INSERT INTO `words` VALUES (24153, 'Smoking is banned in the building.', 'v. 取缔,查禁;(from)禁止; n. 禁止,禁令', '/bæn/', 'ban', 5);
INSERT INTO `words` VALUES (24154, '...a bunch of bananas.', 'n. 香蕉；喜剧演员；大鹰钩鼻', '/bə\'nɑ:nə, -\'næ- | bə\'nɑːnə | bə\'nænə/', 'banana', 5);
INSERT INTO `words` VALUES (24155, 'The band was playing old Beatles songs.', 'n. 条,带;乐队;波段;一群,一伙; v. 缚,绑扎', '/bænd/', 'band', 5);
INSERT INTO `words` VALUES (24156, 'We put some ointment and a bandage on his knee.', 'n. 绷带; v. 用绷带扎缚', '/\'bændidʒ | \'bændɪdʒ/', 'bandage', 5);
INSERT INTO `words` VALUES (24157, 'a bang on the head', 'n. 刘海；重击；突然巨响; adv. 直接地；砰然地；突然巨响地; v. 重击；发巨响', '/bæŋ/', 'bang', 5);
INSERT INTO `words` VALUES (24158, 'the river bank', 'n. 银行；岸,堤；', '/bæŋk/', 'bank', 5);
INSERT INTO `words` VALUES (24159, 'The firm went bankrupt before the building work was completed.', 'adj. 破产的；彻底缺乏的; v. 使破产n.破产者', '/\'bæŋkrʌpt/', 'bankrupt', 5);
INSERT INTO `words` VALUES (24160, 'The oil-producing countries joined together under the banner of OPEC.', 'n. 旗(帜)', '/\'bænə | \'bænɚ/', 'banner', 5);
INSERT INTO `words` VALUES (24161, 'a state banquet (= one attended by heads of government and other important people )', 'n. (正式的)宴会; v. 参加宴会; v. 宴情', '/\'bæŋkwit | \'bæŋkwɪt/', 'banquet', 5);
INSERT INTO `words` VALUES (24162, '...Devil\'s Herd, the city\'s most popular country and western bar.', 'n. 条,杆,闩;酒吧;栅,障碍(物); v. 闩上,阻拦', '/bɑː | bɑr/', 'bar', 5);
INSERT INTO `words` VALUES (24163, 'On New Year\'s Eve we had a barbecue on the beach.', 'n. 烤肉；烤肉用的台架; v. 炙烤(肉等)', '/\'bɑ:bikju: | \'bɑːbɪkjuː | \'bɑrbɪkju/', 'barbecue', 5);
INSERT INTO `words` VALUES (24164, 'My father marched me over to Otto, the local barber, to have my hair cut short.', 'n. 理发师', '/\'bɑ:bə | \'bɑːbə | \'bɑrbɚ/', 'barber', 5);
INSERT INTO `words` VALUES (24165, 'a ragged child with bare feet', 'adj. 赤裸的,空的;稀少的,仅有的; v. 露出,暴露', '/bεə | beə | bɛr/', 'bare', 5);
INSERT INTO `words` VALUES (24166, 'She was very old and barely able to walk.', 'adv. 赤裸裸地,无遮蔽地;仅仅,勉强,几乎没有', '/\'bεəli | \'beəlɪ | \'bɛrli/', 'barely', 5);
INSERT INTO `words` VALUES (24167, 'I’ve kept my side of the bargain and I expect you to keep yours.', 'n. 廉价货;交易,契约,合同; v. 议价,成交', '/ˈbɑːɡɪn/', 'bargain', 5);
INSERT INTO `words` VALUES (24168, 'Don\'t let the dogs bark.', 'vi. 吠叫， 咆哮; n. 吠声， 狗叫声', '/bɑːk | bɑrk/', 'bark', 5);
INSERT INTO `words` VALUES (24169, 'The barn was heaped with grain.', 'n. 谷仓,仓库', '/bɑ:n | bɑːn | bɑrn/', 'barn', 5);
INSERT INTO `words` VALUES (24170, 'The wine is aged in oak barrels.', 'n. 桶;枪管,炮管', '/\'bærəl | \'bær(ə)l/', 'barrel', 5);
