INSERT INTO `words` VALUES (24174, 'His cane answered for a baseball bat.', 'n. 棒球', '/\'beisbɔ:l | \'beɪsbɔːl | \'besbɔl/', 'baseball', 5);
INSERT INTO `words` VALUES (24175, 'They bought an old schoolhouse to live in and built a workshop in the basement.', 'n. 建筑物的底部,地下室,地窖', '/\'beismənt | \'beɪsm(ə)nt | \'besmənt/', 'basement', 5);
