INSERT INTO `words` VALUES (24179, 'a shopping basket', 'n. 筐，篮，篓', '/\'bɑ:skit, \'bæs- | \'bɑːskɪt | \'bæskɪt/', 'basket', 5);
INSERT INTO `words` VALUES (24180, NULL, 'n. 篮球；篮球运动', '/\'bɑ:skitbɔ:l, \'bæs- | \'bɑːskɪtbɔːl | \'bæskɪtbɔl/', 'basketball', 5);
INSERT INTO `words` VALUES (24181, '...a baseball bat.', 'n. 球拍,球棒,短棒;蝙蝠', '/bæt/', 'bat', 5);
INSERT INTO `words` VALUES (24182, 'an overnight batch file', 'n. 一批,一组,一群', '/bætʃ/', 'batch', 5);
INSERT INTO `words` VALUES (24183, 'After a week of camping, I really needed a bath.', 'n. 沐浴,洗澡;浴室(池,盆); v. (给…)洗澡', '/bɑ:θ/bæθ | bɑːθ/', 'bath', 5);
INSERT INTO `words` VALUES (24184, 'I bathed, washed my hair, and got dressed.', 'v. 游泳,洗澡,浸,弄湿', '/beið | beɪð | beð/', 'bathe', 5);
INSERT INTO `words` VALUES (24185, 'Where’s the bathroom?', 'n. 浴室;盥洗室,卫生间', '/\'bɑ:θrum | \'bɑːθruːm; -rʊm | \'bæθrum/', 'bathroom', 5);
INSERT INTO `words` VALUES (24186, 'You have to take the top off to change the batteries .', 'n. 电池(组)；(器具等的)一组，一套；炮兵连', '/\'bætri | \'bæt(ə)rɪ/', 'battery', 5);
INSERT INTO `words` VALUES (24187, 'the Battle of Trafalgar', 'n. 战役,战斗;斗争; v. 战斗,斗争,搏斗', '/\'bætl | \'bæt(ə)l/', 'battle', 5);
