INSERT INTO `words` VALUES (24194, 'You beast! Let go!', 'n. 兽， 牲畜 A；凶残的人； 举止粗鲁的人', '/biːst | bist/', 'beast', 5);
INSERT INTO `words` VALUES (24195, 'Brazil were beaten 2–1.', 'v. 打；打败; n. 拍子；敲击；有规律的一连串敲打; adj. 筋疲力尽的；疲惫不堪的', '/bi:t | biːt | bit/', 'beat', 5);
INSERT INTO `words` VALUES (24196, 'She was even more beautiful than I had remembered.', 'adj. 美丽的', '/\'bju:tiful | \'bjuːtɪfʊl; -f(ə)l | \'bjʊtəfəl/', 'beautiful', 5);
INSERT INTO `words` VALUES (24197, 'her beauty and grace', 'n. 美；美丽；美人；美好的东西', '/\'bju:ti | \'bjuːtɪ | \'bjuti/', 'beauty', 5);
INSERT INTO `words` VALUES (24198, 'a swarm of bees', 'n. 蜜蜂，蜂；勤劳的人', '/bi: | biː | bi/', 'bee', 5);
