INSERT INTO `words` VALUES (24200, 'a pint of beer', 'n. 啤酒; vi. 喝啤酒', '/biə | bɪə | bɪr/', 'beer', 5);
INSERT INTO `words` VALUES (24201, 'She begged and pleaded with them until they finally agreed.', 'v. 乞讨；恳求；回避正题; n. (Beg)人名；(德、塞、巴基)贝格', '/beɡ | beg | bɛɡ/', 'beg', 5);
INSERT INTO `words` VALUES (24202, 'She asked the doctor to speak to her parents on her behalf.', 'n. 代表；利益', '/bi\'hɑ:f | bɪ\'hɑːf | bɪ\'hæf/', 'behalf', 5);
