INSERT INTO `words` VALUES (24205, 'It is important to reward good behaviour.', 'n. 行为， 举止；特性； 运转情况 A', '/bɪ\'heɪvjə | bɪ\'hevjər/', 'behaviour', 5);
INSERT INTO `words` VALUES (24206, 'a law that first came into being in 1912', 'n. 生物；存在， 生存', '/\'biːɪŋ | \'biɪŋ/', 'being', 5);
