INSERT INTO `words` VALUES (24209, 'She laid her hands on her swollen belly.', 'n. 腹部；胃；食欲; v. 涨满；鼓起', '/\'beli | \'belɪ | \'bɛli/', 'belly', 5);
INSERT INTO `words` VALUES (24210, 'The house had belonged to her family for three or four generations.', 'v. 属于，应归入；居住；适宜；应被放置', '/bi\'lɔŋ | bɪ\'lɒŋ | bɪ\'lɔŋ/', 'belong', 5);
INSERT INTO `words` VALUES (24211, 'He never recovered from the death of his beloved daughter.', 'adj. 心爱的；挚爱的; n. 心爱的人；亲爱的教友', '/bi\'lʌvid, -\'lʌvd | bɪ\'lʌvɪd; -\'lʌvd | bɪ\'lʌvd/', 'beloved', 5);
INSERT INTO `words` VALUES (24212, 'an animal that lives below ground', 'prep. 在…下面，在…以下; adv. 在下面，向下', '/bi\'ləu | bɪ\'ləʊ | bɪ\'lo/', 'below', 5);
