INSERT INTO `words` VALUES (24217, 'a drug that has a beneficial effect on the immune system', 'adj. (to)有利的,有益的', '/,beni\'fiʃəl | benɪ\'fɪʃ(ə)l | ,bɛnɪ\'fɪʃl/', 'beneficial', 5);
INSERT INTO `words` VALUES (24218, 'I never had the benefit of a university education.', 'n. 利益,好处,恩惠; v. 有益于;(from,by)受益', '/\'benɪfɪt | \'bɛnɪfɪt/', 'benefit', 5);
INSERT INTO `words` VALUES (24219, 'He shook his head in benign amusement.', 'adj. 良性的；和蔼的，亲切的；吉利的; n. (Benign)人名；(俄)贝尼根', '/bi\'nain | bɪ\'naɪn/', 'benign', 5);
INSERT INTO `words` VALUES (24220, 'Wendy came up and sat beside me.', 'prep. 在...旁边，在...附近；和...相比', '/bɪ\'saɪd/', 'beside', 5);
