INSERT INTO `words` VALUES (24222, 'a £50 bet', 'n. 打赌，赌注；被打赌的事物; v. 打赌；敢断定，确信', '/bet | bɛt/', 'bet', 5);
INSERT INTO `words` VALUES (24223, 'He felt that she had betrayed him.', 'v. 背叛；出卖；泄露（秘密）；露出…迹象', '/bi\'trei | bɪ\'treɪ | bɪ\'tre/', 'betray', 5);
INSERT INTO `words` VALUES (24224, 'Beer is a beverage of the remotest time.', 'n. (水，酒等之外的)饮料', '/\'bevəridʒ | \'bev(ə)rɪdʒ | \'bɛvərɪdʒ/', 'beverage', 5);
INSERT INTO `words` VALUES (24225, 'Police warned drivers to beware.', 'v. 当心，小心', '/bi\'wεə | bɪ\'weə | bɪ\'wɛr/', 'beware', 5);
INSERT INTO `words` VALUES (24226, 'He was bewildered by his daughter’s reaction.', 'v. 使迷惑，使不知所措', '/bi\'wildə | bɪ\'wɪldə | bɪ\'wɪldɚ/', 'bewilder', 5);
INSERT INTO `words` VALUES (24227, 'Students were evaluated without bias.', 'n. 偏见；偏爱；斜纹；乖离率; v. 使存偏见; adj. 偏斜的; adv. 偏斜地', '/\'baiəs | \'baɪəs/', 'bias', 5);
INSERT INTO `words` VALUES (24228, 'Of course I’m biased, but I thought my daughter’s paintings were the best.', 'adj. 有偏见的； 结果偏倚的', '/\'baɪəst/', 'biased', 5);
INSERT INTO `words` VALUES (24229, '...a publisher of bibles and hymn books.', 'n. 有权威的书', '/\'baibl/', 'bible', 5);
INSERT INTO `words` VALUES (24230, 'At the end of this chapter there is a select bibliography of useful books.', 'n. 参考书目；文献目录', '/,bibli\'ɔɡrəfi | ,bɪblɪ\'ɒgrəfɪ | ,bɪblɪ\'ɑɡrəfi/', 'bibliography', 5);
INSERT INTO `words` VALUES (24231, 'Can James ride a bicycle yet?', 'n. (bike)自行车; v. 骑自行车', '/\'baisikl | \'baɪsɪkl/', 'bicycle', 5);
INSERT INTO `words` VALUES (24232, 'She wanted to bid for it.', 'v. 投标；出价；表示；吩咐; n. 出价；叫牌；努力争取', '/bid | bɪd/', 'bid', 5);
INSERT INTO `words` VALUES (24233, '...big steel storage bins.', 'n. 箱子，容器；二进制; v. 把…放入箱中', '/bin | bɪn/', 'bin', 5);
INSERT INTO `words` VALUES (24234, 'The monks are bound by vows of silence.', 'v. 结合；装订；有约束力；过紧; n. 捆绑；困境；讨厌的事情；植物的藤蔓', '/baind | baɪnd/', 'bind', 5);
INSERT INTO `words` VALUES (24235, '...recent biographies of Stalin.', 'n. 传记；档案；个人简介', '/bai\'ɔɡrəfi | baɪ\'ɒgrəfɪ | baɪ\'ɑɡrəfi/', 'biography', 5);
INSERT INTO `words` VALUES (24236, 'a degree in biology', 'n. 生物学', '/bai\'ɔlədʒi | baɪ\'ɒlədʒɪ | baɪ\'ɑlədʒi/', 'biology', 5);
INSERT INTO `words` VALUES (24237, 'Congratulations on the birth of your daughter!', 'n. 出生；血统，出身；起源', '/bɑ:θ | bɜːθ | bɝθ/', 'birth', 5);
