INSERT INTO `words` VALUES (24239, 'a packet of chocolate biscuits', 'n. 小点心，饼干', '/\'biskit | \'bɪskɪt/', 'biscuit', 5);
INSERT INTO `words` VALUES (24240, 'The dog bit him and made his hand bleed.', 'v. 咬；刺痛; n. 咬；一口；咬伤；刺痛; abbr. 机内测试设备（Built-In Test Equipment）', '/bait | baɪt/', 'bite', 5);
INSERT INTO `words` VALUES (24241, 'a bizarre coincidence', 'adj. 奇异的（指态度，容貌，款式等）', '/bi\'zɑ: | bɪ\'zɑː | bɪ\'zɑr/', 'bizarre', 5);
INSERT INTO `words` VALUES (24242, 'He chalked out a design on the blackboard.', 'n. 黑板', '/\'blækbɔ:d | \'blækbɔːd | \'blækbɔrd/', 'blackboard', 5);
INSERT INTO `words` VALUES (24243, 'She had already tried emotional blackmail (= tried to make him feel guilty ) to stop him leaving.', 'n. 勒索，敲诈；勒索所得之款; v. 勒索，敲诈', '/\'blækmeil | \'blækmeɪl | \'blækmel/', 'blackmail', 5);
INSERT INTO `words` VALUES (24244, 'a razor blade', 'n. 叶片；刀片，刀锋；剑', '/bleid | bleɪd | bled/', 'blade', 5);
INSERT INTO `words` VALUES (24245, 'Don’t blame me – it’s not my fault.', 'v. 责备；归咎于; n. 责备；责任；过失', '/\'bleim | bleɪm | blem/', 'blame', 5);
INSERT INTO `words` VALUES (24246, 'Leave the last page blank .', 'adj. 空白的， 空着的；失色的， 无表情的; n. 空白；表格', '/blæŋk/', 'blank', 5);
INSERT INTO `words` VALUES (24247, 'The mud disappeared under a blanket of snow.', 'n. 毛毯，毯子；毯状物，覆盖层; adj. 总括的，全体的；没有限制的; v. 覆盖，掩盖；用毯覆盖', '/\'blæŋkit | \'blæŋkɪt/', 'blanket', 5);
INSERT INTO `words` VALUES (24248, 'I had the gas fire going full blast .', 'n. 爆炸；冲击波；一阵; v. 猛攻', '/\'baiəu,blæst | blɑːst | blæst/', 'blast', 5);
INSERT INTO `words` VALUES (24249, 'an innovative young company that has blazed a trail for others to follow', 'v. 在树皮上刻路标；公开宣布; n. 火焰，烈火；光辉；情感爆发', '/bleiz | bleɪz | blez/', 'blaze', 5);
INSERT INTO `words` VALUES (24250, 'a bleak January afternoon', 'adj. 阴冷的；荒凉的，无遮蔽的；黯淡的，无希望的；冷酷的；单调的', '/bli:k | bliːk | blik/', 'bleak', 5);
INSERT INTO `words` VALUES (24251, 'His ex-wife clearly intends to bleed him for every last penny.', 'v. 使出血；榨取', '/bli:d | bliːd | blid/', 'bleed', 5);
INSERT INTO `words` VALUES (24252, 'a story that blends fact and legend', 'v. 混合; n. 混合；掺合物', '/blend | blɛnd/', 'blend', 5);
INSERT INTO `words` VALUES (24253, 'He’s always willing to help. Bless him!', 'v. 祝福；保佑；赞美; n. (Bless)人名；(英、意、德、匈)布莱斯', '/bles | blɛs/', 'bless', 5);
INSERT INTO `words` VALUES (24254, 'David\'s good looks and impeccable manners had always made her blind to his faults.', 'adj. 盲目的；瞎的; adv. 盲目地；看不见地; n. 掩饰，借口；百叶窗; v. 使失明；使失去理智', '/blaind | blaɪnd/', 'blind', 5);
INSERT INTO `words` VALUES (24255, 'a wall made of concrete blocks', 'n. 块；街区；大厦；障碍物; v. 阻止；阻塞；限制；封盖; adj. 成批的，大块的；交通堵塞的', '/blɒk | blɑk/', 'block', 5);
INSERT INTO `words` VALUES (24256, 'When Barbieux started his blog, his aspirations were small; he simply hoped to communicate with a few people.', 'n. 博客， 日志', '/blɒg | blɑg/', 'blog', 5);
INSERT INTO `words` VALUES (24257, 'Her body was found in a pool of blood.', 'n. 血，血液；血统; v. 从…抽血；使先取得经验', '/blʌd/', 'blood', 5);
INSERT INTO `words` VALUES (24258, 'It serves you bloody well right.', 'adj. 血腥的；非常的；嗜杀的，残忍的；血色的; v. 使流血; adv. 很', '/\'blʌdi | \'blʌdɪ/', 'bloody', 5);
INSERT INTO `words` VALUES (24259, 'beautiful red blooms', 'n. 花；青春；旺盛; v. 使开花；使茂盛', '/blu:m | bluːm | blum/', 'bloom', 5);
INSERT INTO `words` VALUES (24260, 'The apple trees are just beginning to blossom.', 'v. 开花；兴旺；发展成; n. 花；开花期；兴旺期；花开的状态', '/\'blɔsəm | \'blɒs(ə)m | \'blɑsəm/', 'blossom', 5);
INSERT INTO `words` VALUES (24261, 'a silk blouse', 'n. 宽松的上衣；女装衬衫; vt. 使…宽松下垂; vi. 宽松下垂', '/blauz | \'blaʊz | blaʊs/', 'blouse', 5);
INSERT INTO `words` VALUES (24262, 'A cold breeze was blowing hard .', 'v. 吹，吹气，打气；吹奏；爆炸；n.打,打击', '/bləu | bləʊ | blo/', 'blow', 5);
INSERT INTO `words` VALUES (24263, 'By changing the tomato’s genetic blueprint , scientists can alter the rate at which it ripens.', 'v. 计划；制成蓝图; n. 蓝图，设计图；计划', '/\'blu:print | \'bluːprɪnt | \'blʊ\'prɪnt/', 'blueprint', 5);
INSERT INTO `words` VALUES (24264, 'They blundered badly when they gave him the job.', 'v. 跌跌撞撞地走；犯大错; n. 大错', '/\'blʌndə | \'blʌndɚ/', 'blunder', 5);
INSERT INTO `words` VALUES (24265, 'Sharpen all your blunt knives.', 'adj. 钝的，不锋利的；生硬的；直率的; v. 使迟钝; n. (Blunt)人名；(英)布伦特', '/blʌnt/', 'blunt', 5);
INSERT INTO `words` VALUES (24266, 'The street lights were blurred by the fog.', 'v. 涂污；使…模糊不清；使暗淡；玷污; n. 污迹；模糊不清的事物', '/blə: | blɜː | blɝ/', 'blur', 5);
INSERT INTO `words` VALUES (24267, 'Wilson saw she was watching him and blushed.', 'v. 脸红；感到惭愧; n. 脸红；红色；羞愧', '/blʌʃ/', 'blush', 5);
INSERT INTO `words` VALUES (24268, 'Martha was chopping vegetables on a wooden board.', 'n. 董事会；木板；甲板；膳食; v. 上（飞机、车、船等）；用板盖上；给提供膳宿', '/bɔ:d | bɔːd | bɔrd/', 'board', 5);
INSERT INTO `words` VALUES (24269, '‘I wouldn’t be afraid,’ she boasted.', 'v. 夸口说，自吹自擂说；以有…而自豪; n. 自夸；值得夸耀的事物，引以为荣的事物', '/bəust | bəʊst | bost/', 'boast', 5);
INSERT INTO `words` VALUES (24270, 'a fishing boat', 'n. 小船；轮船; v. 划船', '/bəut | bəʊt | bot/', 'boat', 5);
INSERT INTO `words` VALUES (24271, 'Put the spaghetti into plenty of boiling salted water.', 'v. 煮沸，沸腾；激动，激昂; n. 沸腾，煮沸；疖子', '/bɔil | bɒɪl | bɔɪl/', 'boil', 5);
INSERT INTO `words` VALUES (24272, 'In a surprisingly bold move , he is threatening court action against the company.', 'adj. 大胆的，英勇的；黑体的；厚颜无耻的；险峻的; n. (Bold)人名；(英、德、罗、捷、瑞典)博尔德', '/bəuld | bəʊld | bold/', 'bold', 5);
INSERT INTO `words` VALUES (24273, 'Was this money a bolt from the blue or did you know you were going to get it?', 'n. 螺栓，螺钉；闪电，雷电；门闩；弩箭;（布的）一匹，一卷; v. 筛选；囫囵吞下；（把门、窗等）闩上；突然说出，脱口说出; adv. 突然地；像箭似地；直立地', '/bəʊlt | bolt/', 'bolt', 5);
INSERT INTO `words` VALUES (24274, 'The town was heavily bombed in World War II.', 'v. 轰炸，投弹于; n. 炸弹', '/bɔm | bɒm | bɑm/', 'bomb', 5);
INSERT INTO `words` VALUES (24275, 'My father put all his money into stock market bonds.', 'n. 债券；结合；约定；粘合剂；纽带; v. 结合，团结在一起', '/bɒnd | bɑnd/', 'bond', 5);
INSERT INTO `words` VALUES (24276, 'The X-ray showed that the bone was broken in two places.', 'n. 骨；骨骼; v. 剔去的骨；施骨肥于', '/英[bəʊn] 美[bon] | bəʊn | bon/', 'bone', 5);
INSERT INTO `words` VALUES (24277, 'Long-term savers qualify for a cash bonus.', 'n. 奖金；红利；额外津贴', '/\'bəunəs | \'bəʊnəs | \'bonəs/', 'bonus', 5);
INSERT INTO `words` VALUES (24278, 'Guns boomed in the distance.', 'v. 使兴旺；发隆隆声; n. 繁荣；吊杆；隆隆声', '/bu:m | buːm/', 'boom', 5);
INSERT INTO `words` VALUES (24279, 'The new resort area has boosted tourism.', 'v. 促进；增加；支援; n. 推动；帮助；宣扬', '/bu:st | buːst | bʊst/', 'boost', 5);
INSERT INTO `words` VALUES (24280, 'hiking boots', 'v. 引导；踢；解雇；使穿靴; n. 靴子；踢；汽车行李箱', '/bu:t | buːt | but/', 'boot', 5);
INSERT INTO `words` VALUES (24281, 'I called her from a public phone booth near the entrance to the bar.', 'n. 货摊；公用电话亭', '/bu:ð, bu:θ | buːð; buːθ | bʊθ/', 'booth', 5);
INSERT INTO `words` VALUES (24282, 'writing paper with a black border', 'n. 边界， 国界；边; vt. 交界， 与…接壤； 接近 <', '/\'bɔːdə | \'bɔrdɚ/', 'border', 5);
INSERT INTO `words` VALUES (24283, 'Get the special drill bit to bore the correct size hole for the job.', 'v. 钻孔; n. 孔；令人讨厌的人', '/bɔ: | bɔː | bɔr/', 'bore', 5);
INSERT INTO `words` VALUES (24284, 'Forty lambs were born this spring.', 'v. 出世（bear的过去分词）; adj. 天生的; n. (Born)人名；(柬)邦；(英、西、俄、捷、德、瑞典、匈)博恩', '/bɔ:n | bɔːn | bɔrn/', 'born', 5);
INSERT INTO `words` VALUES (24285, 'Can I borrow your pen for a minute?', 'v. 借；借用；从其他语言中引入; n. (Borrow)人名；(英)博罗', '/\'bɔrəu | \'bɒrəʊ | \'bɑro/', 'borrow', 5);
INSERT INTO `words` VALUES (24286, 'She cradled the child to her bosom.', 'n. 胸；胸怀；中间；胸襟；内心；乳房；内部; v. 怀抱；把…藏在心中; adj. 知心的；亲密的', '/\'buzəm | \'bʊz(ə)m | \'bʊzəm/', 'bosom', 5);
INSERT INTO `words` VALUES (24287, 'He studied botany at university.', 'n. 植物学', '/\'bɒtəni | \'bɑtəni/', 'botany', 5);
INSERT INTO `words` VALUES (24288, 'Danny, don’t bother Ellen while she’s reading.', 'v. 烦扰，打扰；使……不安；使……恼怒; n. 麻烦；烦恼', '/\'bɔðə | \'bɒðə | \'bɑðɚ/', 'bother', 5);
INSERT INTO `words` VALUES (24289, 'an empty bottle', 'n. 瓶子；一瓶的容量; v. 控制；把…装入瓶中', '/\'bɔtl | \'bɒt(ə)l | \'bɑtl/', 'bottle', 5);
INSERT INTO `words` VALUES (24290, 'The drugs had been hidden in a suitcase with a false bottom.', 'n. 底(部);基础,根基;海底,湖底,河床', '/\'bɔtəm | \'bɒtəm | \'bɑtəm/', 'bottom', 5);
INSERT INTO `words` VALUES (24291, 'Try to catch the ball on the second bounce.', 'n. 跳；弹力；活力; v. 弹跳；使弹起', '/bauns | baʊns/', 'bounce', 5);
INSERT INTO `words` VALUES (24292, 'You are legally bound to report the accident.', 'adj. 有义务的；必定的；受约束的；装有封面的; v. 束缚；使跳跃; n. 范围；跳跃', '/baʊnd/', 'bound', 5);
INSERT INTO `words` VALUES (24293, 'National boundaries are becoming increasingly meaningless in the global economy.', 'n. 边界；范围；分界线', '/\'baundəri | \'baʊnd(ə)rɪ | \'baʊndri/', 'boundary', 5);
INSERT INTO `words` VALUES (24294, 'This is done with a formal bow to the king or queen.', 'n. 弓；鞠躬；船首; v. 鞠躬；弯腰; adj. 弯曲的', '/bəu | baʊ/', 'bow', 5);
INSERT INTO `words` VALUES (24295, 'cancer of the bowel', 'n. 肠；内部；同情; vt. 将……的肚肠取出', '/\'bauəl | \'baʊəl/', 'bowel', 5);
INSERT INTO `words` VALUES (24296, 'Mix all the ingredients thoroughly in a large bowl.', 'n. 碗；木球；大酒杯; v. 玩保龄球；滑动；平稳快速移动', '/bəul | bəʊl | bol/', 'bowl', 5);
INSERT INTO `words` VALUES (24297, 'Do you want to go bowling with us Friday?', 'n. 滚木球戏；保龄球戏; v. 打保龄球（bowl的现在分词）', '/\'bəuliŋ | \'bəʊlɪŋ | \'bolɪŋ/', 'bowling', 5);
INSERT INTO `words` VALUES (24298, 'We boycott all products tested on animals.', 'v. 联合抵制；拒绝参加; n. 联合抵制', '/\'bɔikɔt | \'bɒɪkɒt | \'bɔɪkɑt/', 'boycott', 5);
INSERT INTO `words` VALUES (24299, 'Wait until we’ve braced the ladder.', 'vt. 使防备， 使受锻炼；支撑； 使绷紧; n. 托架， 支架', '/breɪs | bres/', 'brace', 5);
INSERT INTO `words` VALUES (24300, 'Fix the beam with the brackets and screws.', 'n. 支架；括号；墙上凸出的托架; v. 括在一起；把…归入同一类；排除', '/\'brækit | \'brækɪt/', 'bracket', 5);
INSERT INTO `words` VALUES (24301, 'Messages from the brain are carried by the central nervous system.', 'n. 头脑，智力；脑袋; v. 猛击…的头部', '/brein | breɪn | bren/', 'brain', 5);
INSERT INTO `words` VALUES (24302, 'He heard tyres squeal as the car braked to avoid a collision.', 'v. 刹车; n. 闸，刹车；阻碍', '/breik | breɪk | brek/', 'brake', 5);
INSERT INTO `words` VALUES (24303, 'When you reach the village green, the street branches into two .', 'v. 分支；出现分歧; n. 树枝，分枝；分部；支流', '/brɑ:ntʃ, bræntʃ | brɑːn(t)ʃ | bræntʃ/', 'branch', 5);
INSERT INTO `words` VALUES (24304, 'The owner couldn\'t be bothered to brand the cattle.', 'v. 铭刻于，铭记；打烙印于；印…商标于; n. 商标，牌子；烙印', '/brænd/', 'brand', 5);
INSERT INTO `words` VALUES (24305, 'After a couple of brandies Michael started telling me his life story.', 'n. 白兰地酒', '/\'brændi | \'brændɪ/', 'brandy', 5);
INSERT INTO `words` VALUES (24306, 'an old brass bedstead', 'n. 黄铜；黄铜制品；铜管乐器；厚脸皮', '/brɑ:s, bræs | brɑːs | bræs/', 'brass', 5);
INSERT INTO `words` VALUES (24307, 'The congressman was accused of a breach of secrecy rules.', 'n. 违背，违反；缺口; v. 违反，破坏；打破', '/bri:tʃ | briːtʃ | britʃ/', 'breach', 5);
INSERT INTO `words` VALUES (24308, 'Would you like some bread with your soup?', 'n. 面包；生计; v. 在…上洒面包屑', '/bred | brɛd/', 'bread', 5);
INSERT INTO `words` VALUES (24309, 'We need to provide more breadth in the college curriculum.', 'n. 宽度，幅度；宽宏', '/bredθ | bredθ; -t- | brɛdθ/', 'breadth', 5);
INSERT INTO `words` VALUES (24310, 'I was worried he might have a breakdown if he carried on working so hard.', 'n. 故障；崩溃；分解；分类；衰弱；跺脚曳步舞', '/\'breikdaun | \'breɪkdaʊn | \'brek\'daʊn/', 'breakdown', 5);
INSERT INTO `words` VALUES (24311, 'We had bacon and eggs for breakfast .', 'n. 早餐；早饭; v. 吃早餐', '/\'brekfəst | \'brɛkfəst/', 'breakfast', 5);
INSERT INTO `words` VALUES (24312, 'These bras are specially designed for women with large breasts.', 'n. 乳房，胸部；胸怀；心情; v. 以胸对着；与…搏斗', '/brest | brɛst/', 'breast', 5);
INSERT INTO `words` VALUES (24313, 'Slow down, I need to catch my breath.', 'n. 呼吸，气息；一口气，（呼吸的）一次；瞬间，瞬息；微风；迹象；无声音，气音', '/breθ | brɛθ/', 'breath', 5);
INSERT INTO `words` VALUES (24314, 'The room filled with smoke, and it was becoming difficult to breathe.', 'v. 呼吸；低语；松口气；（风）轻拂', '/bri:ð | briːð | brið/', 'breathe', 5);
INSERT INTO `words` VALUES (24315, 'Eagles breed during the cooler months of the year.', 'v. 繁殖；饲养；产生; n. [生物] 品种；种类，类型', '/bri:d | briːd | brid/', 'breed', 5);
INSERT INTO `words` VALUES (24316, 'flowers waving in the breeze', 'n. 微风；轻而易举的事；煤屑；焦炭渣；小风波; v. 吹微风；逃走', '/bri:z | briːz | briz/', 'breeze', 5);
INSERT INTO `words` VALUES (24317, 'The only way we could get into the country was by bribing the border officials.', 'v. 贿赂，收买; n. 贿赂', '/braib | braɪb/', 'bribe', 5);
INSERT INTO `words` VALUES (24318, 'a brick wall', 'n. 砖，砖块；砖形物；心肠好的人; v. 用砖砌; adj. 用砖做的；似砖的', '/brik | brɪk/', 'brick', 5);
INSERT INTO `words` VALUES (24319, 'Guests toasted the bride and groom with champagne.', 'n. 新娘；姑娘，女朋友', '/braid | braɪd/', 'bride', 5);
INSERT INTO `words` VALUES (24320, 'He walked back over the railway bridge.', 'n. 桥；桥牌；桥接器；船桥; v. 架桥；渡过', '/bridʒ | brɪdʒ/', 'bridge', 5);
INSERT INTO `words` VALUES (24321, 'We stopped by Alice’s house for a brief visit.', 'adj. 简短的， 简洁的; n. 简报; vt. 简短介绍， 简要汇报', '/briːf | brif/', 'brief', 5);
INSERT INTO `words` VALUES (24322, 'He popped a letter out of his briefcase.', 'n. 公文包', '/\'bri:fkeis | \'briːfkeɪs | \'brifkes/', 'briefcase', 5);
INSERT INTO `words` VALUES (24323, 'She closed her eyes against the brilliant light .', 'adj. 灿烂的，闪耀的；杰出的；有才气的；精彩的，绝妙的', '/\'brɪlj(ə)nt | \'brɪljənt/', 'brilliant', 5);
INSERT INTO `words` VALUES (24324, 'an old straw hat with a broad brim', 'n. 边；边缘; v. 满溢；溢出', '/brim | brɪm/', 'brim', 5);
INSERT INTO `words` VALUES (24325, 'The discovery of gold brought thousands of people to the Transvaal.', 'v. 带来；促使；引起；使某人处于某种情况或境地; n. (Bring)人名；(英、瑞典)布林', '/briŋ | brɪŋ/', 'bring', 5);
INSERT INTO `words` VALUES (24326, 'a brisk walk', 'adj. 敏锐的，活泼的，轻快的；凛冽的; v. 活跃起来；变得轻快; n. (Brisk)人名；(法、芬)布里斯克', '/brisk | brɪsk/', 'brisk', 5);
INSERT INTO `words` VALUES (24327, 'The branches were dry and brittle.', 'adj. 易碎的； 脆的', '/\'brɪtl/', 'brittle', 5);
INSERT INTO `words` VALUES (24328, 'The interview was broadcast live across Europe.', 'v. 播送，播放；（无线电或电视）广播；播撒（种子）; n. 广播；播音；广播节目; adj. 广播的', '/\'brɔ:dkɑ:st, -kæst | \'brɔːdkɑːst | \'brɔdkæst/', 'broadcast', 5);
INSERT INTO `words` VALUES (24329, 'a holiday brochure', 'n. 手册，小册子', '/bro\'ʃur | \'brəʊʃə; brɒ\'ʃʊə | bro\'ʃʊr/', 'brochure', 5);
INSERT INTO `words` VALUES (24330, 'a bell cast in bronze', 'n. 青铜；古铜色；青铜制品; adj. 青铜色的；青铜制的; v. 镀青铜于', '/brɔnz | brɒnz | brɑnz/', 'bronze', 5);
INSERT INTO `words` VALUES (24331, 'He would brook no criticism, even from his beloved daughter.', 'v. 忍受；容忍; n. 小溪；小河', '/bruk | brʊk/', 'brook', 5);
INSERT INTO `words` VALUES (24332, 'To the left of the port, a dry stone stairway leads to the ruins, through the mastic trees and broom.', 'n. 扫帚；金雀花; v. 扫除', '/bru:m | bruːm | brum/', 'broom', 5);
INSERT INTO `words` VALUES (24333, 'I have two brothers, William and Mark.', 'n. 兄弟；同事；战友; int. 我的老兄！', '/\'brʌðə | \'brʌðɚ/', 'brother', 5);
INSERT INTO `words` VALUES (24334, 'He wiped his brow with the back of his hand.', 'n. 眉，眉毛；额；表情', '/brau | braʊ/', 'brow', 5);
INSERT INTO `words` VALUES (24335, 'dark brown hair', 'adj. 棕色的，褐色的；太阳晒黑的; v. 变成褐色; n. 褐色，棕色', '/braun | braʊn/', 'brown', 5);
INSERT INTO `words` VALUES (24336, 'a feature that allows you to browse your hard drive and choose the graphic you want to display', 'v. 浏览；吃草; n. 浏览；吃草', '/brauz | braʊz/', 'browse', 5);
INSERT INTO `words` VALUES (24337, 'minor cuts and bruises', 'n. 擦伤；挫伤；青肿; v. 使受瘀伤；使受挫伤', '/bru:z | bruːz | bruz/', 'bruise', 5);
INSERT INTO `words` VALUES (24338, 'a brutal man', 'adj. 残忍的；野蛮的，不讲理的', '/\'bru:təl | \'bruːt(ə)l | \'brutl/', 'brutal', 5);
INSERT INTO `words` VALUES (24339, 'When water boils, bubbles rise to the surface.', 'n. 气泡，泡沫，泡状物；透明圆形罩，圆形顶; v. 沸腾，冒泡；发出气泡声', '/\'bʌbl | \'bʌb(ə)l/', 'bubble', 5);
INSERT INTO `words` VALUES (24340, 'They were drinking beer by the bucket.', 'n. 桶，水桶；铲斗；一桶的量; v. 倾盆而下；颠簸着行进', '/\'bʌkit | \'bʌkɪt/', 'bucket', 5);
INSERT INTO `words` VALUES (24341, 'rose buds', 'n. 芽，萌芽；蓓蕾; v. 发芽，萌芽', '/bʌd/', 'bud', 5);
INSERT INTO `words` VALUES (24342, 'We had a really tight budget .', 'n. 预算，预算费; v. 安排，预定；把…编入预算; adj. 廉价的', '/\'bʌdʒit | \'bʌdʒɪt/', 'budget', 5);
INSERT INTO `words` VALUES (24343, 'a cold buffet', 'n. 自助餐；小卖部；打击；猛烈冲击; v. 与…搏斗；连续猛击; adj. 自助的；自助餐的', '/\'bʌfit | \'bʊfeɪ; \'bʌfeɪ | bə\'fe/', 'buffet', 5);
INSERT INTO `words` VALUES (24344, 'There’s a nasty bug going round (= that a lot of people have caught ) .', 'n. 臭虫，小虫；故障；窃听器; v. 烦扰，打扰；装窃听器', '/bʌɡ | bʌg/', 'bug', 5);
INSERT INTO `words` VALUES (24345, 'The offices are on the top two floors of the building.', 'n. 建筑；建筑物; v. 建筑；建立；增加（build的ing形式）', '/\'bildiŋ | \'bɪldɪŋ/', 'building', 5);
INSERT INTO `words` VALUES (24346, 'a 100-watt bulb', 'n. 电灯泡；鳞茎；球状物; vi. 生球茎；膨胀成球状', '/bʌlb/', 'bulb', 5);
INSERT INTO `words` VALUES (24347, 'The dough will rise until it is double in bulk.', 'n. 体积，容量；大多数，大部分；大块; v. 使扩大，使形成大量；使显得重要', '/bʌlk/', 'bulk', 5);
INSERT INTO `words` VALUES (24348, 'a herd of cows with one bull', 'n. 公牛；看好股市者；粗壮如牛的人；胡说八道；印玺; adj. 大型的；公牛似的；雄性的; v. 企图抬高证券价格；吓唬；强力实现', '/bul | bʊl/', 'bull', 5);
INSERT INTO `words` VALUES (24349, 'He was killed by a single bullet.', 'n. 子弹；只选某党全部候选人的投票；豆子; vi. 射出；迅速行进', '/\'bulit | \'bʊlɪt/', 'bullet', 5);
INSERT INTO `words` VALUES (24350, 'At 3:30 p.m. a bulletin was released announcing that the president was out of immediate danger.', 'n. 公报,公告,告示', '/\'bulitin | \'bʊlɪtɪn | \'bʊlətɪn/', 'bulletin', 5);
INSERT INTO `words` VALUES (24351, 'Bullies are often cowards.', 'n. 欺凌弱小者；土霸; adj. 第一流的；特好的; v. 欺负；威吓; adv. 很；十分; int. 好；妙', '/\'buli | \'bʊlɪ | \'bʊli/', 'bully', 5);
INSERT INTO `words` VALUES (24352, 'She has a bump on the back of her head.', 'n. 肿块，隆起物；撞击; v. 碰撞，撞击；颠簸而行; adv. 突然地，猛烈地', '/bʌmp/', 'bump', 5);
INSERT INTO `words` VALUES (24353, 'Lili had fallen asleep clutching a fat bunch of grapes.', 'n. 群；串；突出物; v. 隆起；打褶；形成一串', '/\'bʌntʃ | bʌn(t)ʃ | bʌntʃ/', 'bunch', 5);
INSERT INTO `words` VALUES (24354, 'a small bundle containing mostly clothing', 'n. 束；捆; v. 捆', '/\'bʌndl | \'bʌnd(ə)l/', 'bundle', 5);
INSERT INTO `words` VALUES (24355, 'His family responsibilities had started to become a burden.', 'n. 负担；责任；船的载货量; v. 使负担；烦扰；装货于', '/\'bə:dən | \'bɜːd(ə)n | \'bɝdn/', 'burden', 5);
INSERT INTO `words` VALUES (24356, 'the Federal Bureau of Investigation', 'n. 局，处；衣柜；办公桌', '/\'bjuərəu | \'bjʊərəʊ | \'bjʊro/', 'bureau', 5);
INSERT INTO `words` VALUES (24357, 'the reduction of unnecessary bureaucracy', 'n. 官僚主义；官僚机构；官僚政治', '/bjuə\'rɔkrəsi | ,bjʊ(ə)\'rɒkrəsɪ | bjʊ\'rɑkrəsi/', 'bureaucracy', 5);
INSERT INTO `words` VALUES (24358, 'Burglars broke into their home.', 'n. 夜贼，窃贼', '/\'bə:ɡlə | \'bɜːglə | \'bɝɡlɚ/', 'burglar', 5);
INSERT INTO `words` VALUES (24359, 'I burnt all his old letters.', 'v. 燃烧；烧毁，灼伤；激起…的愤怒; n. 灼伤，烧伤；烙印', '/bə:n | bɜːn | bɝn/', 'burn', 5);
INSERT INTO `words` VALUES (24360, 'The pipes had burst and the house was under two feet of water.', 'v. 爆发，突发；爆炸; n. 爆发，突发；爆炸', '/bə:st | bɜːst | bɝst/', 'burst', 5);
INSERT INTO `words` VALUES (24361, 'Electric cables are buried beneath the streets.', 'v. 埋葬；隐藏; n. (Bury)人名；(法)比里；(英、西)伯里；(德、意、罗、波、捷、匈)布里；(俄)布雷', '/\'beri | \'berɪ | \'bɛri/', 'bury', 5);
INSERT INTO `words` VALUES (24362, 'a rose bush', 'n. 灌木；矮树丛; v. 以灌木装饰；使…精疲力竭; adj. 如灌木般长得低矮的；粗野的', '/buʃ | bʊʃ/', 'bush', 5);
INSERT INTO `words` VALUES (24363, 'She’s busy now – can you phone later?', 'adj. 忙碌的；热闹的；正被占用的; v. 使忙于; n. (Busy)人名；(匈)布希；(法)比西', '/\'bizi | \'bɪzɪ | \'bɪzi/', 'busy', 5);
INSERT INTO `words` VALUES (24364, 'Pigs were butchered, hams were hung to dry from the ceiling.', 'v. 屠杀; n. 屠夫', '/\'butʃə | ˈbʊtʃə(r) | ˈbʊtʃər/', 'butcher', 5);
INSERT INTO `words` VALUES (24365, 'buttered toast', 'v. 涂黄油于；讨好; n. 黄油；奶油；奉承话', '/\'bʌtə | \'bʌtɚ/', 'butter', 5);
INSERT INTO `words` VALUES (24366, 'Gwen’s a real social butterfly .', 'n. 蝴蝶；蝶泳；举止轻浮的人；追求享乐的人', '/\'bʌtəflai | \'bʌtəflaɪ | \'bʌtɚflaɪ/', 'butterfly', 5);
INSERT INTO `words` VALUES (24367, 'small pearl buttons', 'n. 按钮；纽扣; v. 扣住；扣紧；在…上装纽扣', '/[ˈbʌtn] | \'bʌtn/', 'button', 5);
INSERT INTO `words` VALUES (24368, 'a loud buzzing noise', 'vi. 发出嗡嗡声；充满兴奋; n. 嗡嗡声；嘈杂的谈话声', '/bʌz/', 'buzz', 5);
INSERT INTO `words` VALUES (24369, 'A new bypass around the city is being built.', 'n. 旁路， 迂回的旁道； 搭桥术； 旁通管', '/\'baipa:s | \'baɪpɑːs/', 'by-pass', 5);
INSERT INTO `words` VALUES (24370, 'Francis bypassed his manager and wrote straight to the director.', 'v. 绕开；忽视；设旁路；迂回; n. 旁路；[公路] 支路', '/\'baipɑ:s,-pæs | \'baɪpɑːs | \'baɪpæs/', 'bypass', 5);
INSERT INTO `words` VALUES (24371, 'New York’s yellow cabs', 'n. 驾驶室；出租汽车；出租马车; v. 乘出租马车（或汽车）', '/kæb/', 'cab', 5);
INSERT INTO `words` VALUES (24372, 'I like peas more than cabbage .', 'n. 卷心菜，甘蓝菜，洋白菜；（俚)脑袋；（非正式、侮辱）植物人（常用于英式英语）；（俚）钱，尤指纸币（常用于美式俚语）', '/ˈkæbɪdʒ/', 'cabbage', 5);
INSERT INTO `words` VALUES (24373, 'a log cabin', 'n. 客舱， 机舱；小屋', '/\'kæbɪn/', 'cabin', 5);
INSERT INTO `words` VALUES (24374, 'a cabinet meeting', 'n. 内阁；橱柜；展览艺术品的小陈列室; adj. 内阁的；私下的，秘密的', '/\'kæbinit | \'kæbɪnɪt | \'kæbɪnət/', 'cabinet', 5);
INSERT INTO `words` VALUES (24375, 'cables and switches for computers', 'n. 缆绳；电缆；海底电报; v. 打电报', '/\'keɪb(ə)l | \'kebl/', 'cable', 5);
INSERT INTO `words` VALUES (24376, 'the school cafeteria', 'n. 自助餐厅', '/,kæfi\'tiəriə | kæfɪ\'tɪərɪə | ,kæfə\'tɪrɪə/', 'cafeteria', 5);
INSERT INTO `words` VALUES (24377, 'I hate to see birds in cages.', 'n. 笼，兽笼；牢房，监狱; v. 把…关进笼子；把…囚禁起来', '/keidʒ | keɪdʒ | kedʒ/', 'cage', 5);
INSERT INTO `words` VALUES (24378, 'We had cake and ice cream.', 'n. 蛋糕；块状物；利益总额; v. 使结块', '/keik | keɪk | kek/', 'cake', 5);
INSERT INTO `words` VALUES (24379, 'Like fibre, calcium binds with fat molecules and helps flush them out through the intestine.', 'n. 钙(化学符号Ca)', '/\'kælsiəm | \'kælsɪəm/', 'calcium', 5);
INSERT INTO `words` VALUES (24380, 'These instruments calculate distances precisely.', 'v. 计算,推算;计划,打算', '/\'kælkjuleit | \'kælkjʊleɪt | \'kælkjulet/', 'calculate', 5);
INSERT INTO `words` VALUES (24381, 'There was a calendar on the wall above, with large squares around the dates.', 'n. 日历,月历', '/\'kælində | \'kælɪndə | \'kæləndɚ/', 'calendar', 5);
INSERT INTO `words` VALUES (24382, 'She calls her father every couple of days.', 'vt. 叫，喊；打电话; vi. 叫；访问; n. 叫；号召', '/kɔ:l | kɔːl | kɔl/', 'call', 5);
INSERT INTO `words` VALUES (24383, 'Glen was calm and composed at the funeral.', 'adj. 静的，平静的；沉着的; v. 使平静；使镇定; n. 风平浪静', '/kɑ:m, kɑ:lm | kɑːm | kɑm/', 'calm', 5);
INSERT INTO `words` VALUES (24384, 'A potato has about 90 calories.', 'n. 卡路里（热量单位）', '/\'kæləri | \'kælərɪ/', 'calorie', 5);
INSERT INTO `words` VALUES (24385, NULL, 'n. [畜牧][脊椎] 骆驼；打捞浮筒；工作作风官僚; adj. 驼色的；暗棕色的; vi. 工作刻板平庸', '/\'kæməl | \'kæm(ə)l | \'kæml/', 'camel', 5);
INSERT INTO `words` VALUES (24386, 'Her grandmother lent her a camera for a school trip to Venice and Egypt.', 'n. 照相机；摄影机', '/\'kæmərə | \'kæm(ə)rə/', 'camera', 5);
INSERT INTO `words` VALUES (24387, 'We’ll camp by the river for the night, and move on tomorrow.', 'v. 露营；扎营; n. 露营', '/kæmp/', 'camp', 5);
INSERT INTO `words` VALUES (24388, 'Jones ran a good campaign.', 'v. 作战；参加竞选；参加活动; n. 运动；活动；战役', '/kæm\'pein | kæm\'peɪn | kæm\'pen/', 'campaign', 5);
INSERT INTO `words` VALUES (24389, 'a beautiful campus in New England', 'n. （大学）校园；大学，大学生活；校园内的草地', '/\'kæmpəs/', 'campus', 5);
INSERT INTO `words` VALUES (24390, 'We walked along by the side of the canal.', 'n. 运河；[地理] 水道；[建] 管道；灌溉水渠; v. 在…开凿运河', '/kə\'næl/', 'canal', 5);
INSERT INTO `words` VALUES (24391, 'Our flight was cancelled.', 'v. 取消；删去; n. 取消，撤销', '/\'kæns(ə)l | \'kænsl/', 'cancel', 5);
INSERT INTO `words` VALUES (24392, 'A lot of cancers can now be treated successfully.', 'n. 癌症；恶性肿瘤', '/\'kænsə | \'kænsɚ/', 'cancer', 5);
