INSERT INTO `words` VALUES (24394, 'When the candle was only half an inch high it flickered out and the room became dark.', 'n. 蜡烛；烛光；烛形物; v. 对着光检查', '/\'kændl | \'kænd(ə)l/', 'candle', 5);
INSERT INTO `words` VALUES (24395, '...a piece of candy.', 'v. 用糖煮；使结晶为砂糖；美化; n. 糖果（等于sweets）；冰糖（等于sugar candy，rock candy）；毒品; adj. 新潮的（服饰）；甜言蜜语的', '/\'kændi | \'kændɪ/', 'candy', 5);
INSERT INTO `words` VALUES (24396, 'The cannons boom, the band plays.', 'n. 大炮；加农炮；榴弹炮；机关炮; v. 炮轰；开炮', '/\'kænən/', 'cannon', 5);
INSERT INTO `words` VALUES (24397, 'We saw the canoe overturn, throwing its passengers into the water.', 'n. 独木舟；轻舟; v. 乘独木舟', '/kə\'nu: | kə\'nuː | kə\'nu/', 'canoe', 5);
INSERT INTO `words` VALUES (24398, 'Rennie had eaten his supper in the canteen.', 'n. 食堂，小卖部；水壶', '/kæn\'ti:n | kæn\'tiːn | kænˈtiːn/', 'canteen', 5);
INSERT INTO `words` VALUES (24399, 'a canvas bag', 'n. 帆布; v. 用帆布覆盖，用帆布装备; adj. 帆布制的', '/\'kænvəs/', 'canvas', 5);
INSERT INTO `words` VALUES (24400, 'Make sure you put the cap back on the pen.', 'n. 便帽,军帽;盖,罩,套; v. 覆盖于…顶端', '/kæp/', 'cap', 5);
INSERT INTO `words` VALUES (24401, 'I don’t think he’s capable of murder.', 'adj. 有本领的,有能力的;(of)可以…的,能…的', '/\'keipəbl | \'keɪpəb(ə)l | \'kepəbl/', 'capable', 5);
INSERT INTO `words` VALUES (24402, 'The room had seating capacity for about 80.', 'n. 容量,容积;能量,能力;接受力', '/kə\'pæsəti | kə\'pæsɪtɪ/', 'capacity', 5);
INSERT INTO `words` VALUES (24403, 'Cape Cod', 'n. 海角，岬；披肩，短披风', '/keip | keɪp | kep/', 'cape', 5);
INSERT INTO `words` VALUES (24404, 'Washington D.C., the capital of the United States', 'n. 首都;大写字母;资本; adj. 主要的,大写字母的', '/\'kæpitəl | \'kæpɪt(ə)l | \'kæpɪtl/', 'capital', 5);
INSERT INTO `words` VALUES (24405, '...the two fundamentally opposed social systems, capitalism and socialism.', 'n. 资本主义', '/\'kæpitəlizəm | \'kæpɪt(ə)lɪz(ə)m | \'kæpɪtəlɪzəm/', 'capitalism', 5);
INSERT INTO `words` VALUES (24406, 'a space capsule orbiting the Earth', 'n. 胶囊;太空舱', '/\'kæpsju:l | \'kæpsjuːl; -sjʊl | ˈkæpsul/', 'capsule', 5);
INSERT INTO `words` VALUES (24407, 'The captain and crew welcome you aboard.', 'n. 首领,队长;船长;上尉; v. 做…的首领,指挥', '/\'kæptin | \'kæptɪn | ˈkæptən/', 'captain', 5);
INSERT INTO `words` VALUES (24408, 'During his six years in Ireland as a captive, he became deeply religious When he returned to England he became a priest.', 'n. 俘虏; adj. 被俘虏的,被监禁的', '/\'kæptiv | \'kæptɪv/', 'captive', 5);
INSERT INTO `words` VALUES (24409, 'Government troops have succeeded in capturing the rebel leader.', 'v&n. 捕获,俘虏;夺得,攻占', '/\'kæptʃə | \'kæptʃɚ/', 'capture', 5);
INSERT INTO `words` VALUES (24410, 'Dan got out of the car and locked the door.', 'n. 汽车，车辆，车；(火车)车厢', '/kɑ: | kɑː | kɑr/', 'car', 5);
INSERT INTO `words` VALUES (24411, 'You should not have too much carbohydrate in your diet.', 'n. 碳水化合物', '/ˌkɑːbəu\'haɪdreɪt | ,kɑrbo\'haɪdret/', 'carbohydrate', 5);
INSERT INTO `words` VALUES (24412, 'Across the world, forests and the soil beneath them absorb about a quarter of all carbon emissions.', 'n. [化学] 碳；碳棒；复写纸; adj. 碳的；碳处理的', '/\'kɑ:bən | \'kɑːb(ə)n | \'kɑrbən/', 'carbon', 5);
INSERT INTO `words` VALUES (24413, 'Employees must show their identity cards at the gate.', 'n. 卡片；纸牌；明信片; v. 记于卡片上', '/kɑ:d | kɑːd | kɑrd/', 'card', 5);
INSERT INTO `words` VALUES (24414, 'Having clean hands is one of the cardinal rules when preparing food.', 'n. 红衣主教；枢机主教；鲜红色；【鸟类】(北美)主红雀; adj. 主要的，基本的；深红色的', '/\'kɑːd(ɪ)n(ə)l | \'kɑrdɪnl/', 'cardinal', 5);
INSERT INTO `words` VALUES (24415, 'high standards of medical care', 'n. 小心;关怀,照料; v. (about)关心,介意,计较', '/kεə | keə | kɛr/', 'care', 5);
INSERT INTO `words` VALUES (24416, 'a teaching career', 'n. (个人的)事业；专业，生涯，职业，经历', '/kə\'rɪə | kə\'rɪr/', 'career', 5);
INSERT INTO `words` VALUES (24417, 'Be careful - the floor’s slippery.', 'adj. 小心的,仔细的;细致的,精心的', '/\'kεəful | \'keəfʊl; -f(ə)l | \'kɛrfl/', 'careful', 5);
INSERT INTO `words` VALUES (24418, 'His hands gently caressed her body.', 'vt&n. 爱抚，抚摸', '/kə\'res | kə\'rɛs/', 'caress', 5);
INSERT INTO `words` VALUES (24419, 'a cargo plane', 'n. 船货,货物', '/\'kɑ:ɡəu | \'kɑːgəʊ | \'kɑrɡo/', 'cargo', 5);
INSERT INTO `words` VALUES (24420, 'He is a carpenter by profession.', 'n. 木工,木匠', '/\'kɑ:pəntə | ˈkɑːpəntə(r) | ˈkɑːrpəntər/', 'carpenter', 5);
INSERT INTO `words` VALUES (24421, 'My bedroom carpet is green.', 'n. 地毯', '/\'kɑ:pit | \'kɑːpɪt | \'kɑrpɪt/', 'carpet', 5);
INSERT INTO `words` VALUES (24422, 'The president-elect followed in an open carriage drawn by six beautiful grey horses.', 'n. (四轮)马车;(火车)客车厢', '/\'kæridʒ | \'kærɪdʒ/', 'carriage', 5);
INSERT INTO `words` VALUES (24423, 'a baby carrier', 'n. 搬运人;载体', '/\'kæriə | \'kærɪə | \'kærɪɚ/', 'carrier', 5);
INSERT INTO `words` VALUES (24424, 'grated carrots', 'n. 胡萝卜', '/\'kærət/', 'carrot', 5);
INSERT INTO `words` VALUES (24425, 'The ship was carrying drugs.', 'v. 运送,搬运;传送,传播;领,带', '/\'kæri | \'kærɪ/', 'carry', 5);
INSERT INTO `words` VALUES (24426, 'The cart is piled high with straw.', 'n. (二轮货运)马车,手推车', '/kɑ:t | kɑːt | kɑrt/', 'cart', 5);
INSERT INTO `words` VALUES (24427, 'cartoon characters such as Donald Duck', 'n. 漫画,幽默画;动画片', '/kɑ:\'tu:n | kɑː\'tuːn | kɑr\'tun/', 'cartoon', 5);
