INSERT INTO `words` VALUES (24530, 'Draw a circle 10cm in diameter.', 'n. 圆,圆周;集团;周期,循环; v. 环绕,旋转', '/\'sə:kl | \'sɜːk(ə)l | \'sɝkl/', 'circle', 5);
