INSERT INTO `words` VALUES (24534, '...a scientist calculating the Earth\'s circumference.', 'n. 圆周,周围', '/sə\'kʌmfərəns | sə\'kʌmf(ə)r(ə)ns | sɚ\'kʌmfərəns/', 'circumference', 5);
INSERT INTO `words` VALUES (24535, 'The Soviet Union had been forced by circumstances to sign a pact with Nazi Germany.', 'n. 环境，情况；事件；境遇', '/\'sə:kəmstəns | ˈsɜːkəmstəns; ˈsɜːkəmstɑːns; ˈsɜːkəmstæns | \'sɝkəmstæns/', 'circumstance', 5);
