INSERT INTO `words` VALUES (24541, 'Perhaps intelligence and civilisation are not what we should be concentrating on.', 'n. 文明， 文化', '/ˌsɪvəlaɪ\'zeɪʃn | ,sivilai\'zeiʃən, -li\'z-/', 'civilisation', 5);
