INSERT INTO `words` VALUES (24550, 'the firm clasp of her hand', 'n. 扣子，钩子；握手; v. 紧抱；扣紧；紧紧缠绕', '/klɑ:sp, klæsp | klɑːsp | klæsp/', 'clasp', 5);
INSERT INTO `words` VALUES (24551, 'He had to spend about six months in a class with younger students.', 'n. 阶级；班级；种类；班；等级; v. 分类；把…分等级；把…归入某等级，把…看作（或分类、归类）；把…编入某一班级; adj. 极好的；很好的，优秀的，出色的', '/klɑːs | klæs/', 'class', 5);
INSERT INTO `words` VALUES (24552, 'The Coca-Cola bottle is one of the classic designs of the last century.', 'adj. 经典的；古典的，传统的；最优秀的; n. 名著；经典著作；大艺术家', '/\'klæsik | \'klæsɪk/', 'classic', 5);
