INSERT INTO `words` VALUES (24554, 'the classification of wines according to quality', 'n. 分类,分级', '//,klæsifi\'keiʃən/ | ,klæsɪfɪ\'keɪʃ(ə)n | ,klæsɪfɪ\'keʃən/', 'classification', 5);
