INSERT INTO `words` VALUES (24618, 'Two people were killed in a head-on collision (= between two vehicles that are moving directly towards each other ) on highway 218.', 'n. 碰撞；冲突；（意见，看法）的抵触；（政党等的）倾轧', '/kə\'lɪʒ(ə)n | kə\'lɪʒən/', 'collision', 5);
INSERT INTO `words` VALUES (24619, 'Nothing remained of the colonel.', 'n. 陆军上校', '/\'kə:nəl | \'kɜːn(ə)l | \'kɝnl/', 'colonel', 5);
INSERT INTO `words` VALUES (24620, 'In our freedom, we reject the colonial apartheid system that has caused genocide to our people, and to all Indigenous peoples.', 'n. 殖民地居民; adj. 殖民地的，殖民的', '/kə\'ləunjəl | kə\'ləʊnɪəl | kə\'lonɪəl/', 'colonial', 5);
INSERT INTO `words` VALUES (24621, 'Algeria was formerly a French colony.', 'n. 殖民地；移民队；种群；动物栖息地', '/\'kɒlənɪ | \'kɑləni/', 'colony', 5);
INSERT INTO `words` VALUES (24622, 'He writes a weekly column for ‘The Times’.', 'n. 纵队，列；专栏；圆柱，柱形物', '/\'kɔləm | \'kɒləm | \'kɑləm/', 'column', 5);
INSERT INTO `words` VALUES (24623, 'Your hair needs a good comb.', 'n. 梳子；蜂巢；鸡冠; v. 梳头发；梳毛', '/kəum | kəʊm | kom/', 'comb', 5);
INSERT INTO `words` VALUES (24624, 'We flew over 200 combat missions in the war.', 'v&n. 战斗,搏斗,格斗', '/\'kɔmbæt, kəm\'bæt | \'kɒmbæt; \'kʌm- | \'kɑmbæt/', 'combat', 5);
INSERT INTO `words` VALUES (24625, 'a combination nightclub and café', 'n. 结合；组合；联合；[化学] 化合', '/,kɔmbi\'neiʃən | kɒmbɪ\'neɪʃ(ə)n | ,kɑmbɪ\'neʃən/', 'combination', 5);
INSERT INTO `words` VALUES (24626, 'Diets are most effective when combined with exercise.', 'v. 使化合；使联合，使结合; n. 联合收割机；联合企业', '/kəm\'bain | kəm\'baɪn/', 'combine', 5);
INSERT INTO `words` VALUES (24627, 'a career in stand-up comedy', 'n. 喜剧;喜剧性事件', '/英[\'kɒmɪdɪ] 美[\'kɑmədi] | \'kɒmɪdɪ | \'kɑmədi/', 'comedy', 5);
INSERT INTO `words` VALUES (24628, 'Halley’s comet', 'n. 彗星', '/\'kɒmɪt | \'kɑmət/', 'comet', 5);
INSERT INTO `words` VALUES (24629, 'I dress for comfort, not fashion.', 'n. 安慰；舒适；安慰者; v. 安慰；使（痛苦等）缓和', '/\'kʌmfət | \'kʌmfɚt/', 'comfort', 5);
INSERT INTO `words` VALUES (24630, 'I was so comfortable and warm in bed I didn’t want to get up.', 'adj. 舒适的，舒服的; n. 盖被', '/\'kʌmfətəbl | ˈkʌmftəbl | \'kʌmftəbl/', 'comfortable', 5);
INSERT INTO `words` VALUES (24631, 'a comic novel', 'adj. 喜剧的；滑稽的；有趣的; n. 连环漫画；喜剧演员；滑稽人物', '/\'kɔmik | \'kɒmɪk | \'kɑmɪk/', 'comic', 5);
INSERT INTO `words` VALUES (24632, 'He commands the 4th Battalion.', 'v. 命令； 指挥， 统率; n. 命令， 指令；统帅； 指挥；掌握， 运用能力', '/kə\'mɑːnd | kə\'mænd/', 'command', 5);
INSERT INTO `words` VALUES (24633, 'a parade to commemorate the town’s bicentenary', 'v. 纪念，庆祝', '/kə\'meməreit | kə\'meməreɪt | kə\'mɛməret/', 'commemorate', 5);
INSERT INTO `words` VALUES (24634, 'Work will commence on the new building immediately.', 'v. 开始; v. 获得学位', '/kə\'mens | kə\'mɛns/', 'commence', 5);
INSERT INTO `words` VALUES (24635, 'The paper was highly commended in the UK Press Awards.', 'v. 推荐；称赞；把…委托', '/kə\'mend | kə\'mɛnd/', 'commend', 5);
INSERT INTO `words` VALUES (24636, 'So far, Mr. Cook has not commented on these reports.', 'v. 注释； 评论; n. 注释； 评论； 意见', '/\'kɒment | \'kɑmɛnt/', 'comment', 5);
INSERT INTO `words` VALUES (24637, 'measures promoting local commerce and industry', 'n. 商业，贸易；交际，交往', '/\'kɒmɜːs | \'kɑmɝs/', 'commerce', 5);
INSERT INTO `words` VALUES (24638, 'Our top priorities must be profit and commercial growth.', 'adj. 商业的；商务的；可获利的; n. 广告节目', '/kə\'mə:ʃəl | kə\'mɜːʃ(ə)l | kə\'mɝʃəl/', 'commercial', 5);
INSERT INTO `words` VALUES (24639, 'The Government set up a commission to investigate allegations of police violence.', 'n. 委员会；佣金；犯；委任；委任状; v. 委任；使服役；委托制作', '/kə\'miʃən | kə\'mɪʃ(ə)n | kə\'mɪʃən/', 'commission', 5);
INSERT INTO `words` VALUES (24640, 'Women commit fewer crimes than men.', 'v. 犯罪，做错事；把交托给；指派…作战；使…承担义务', '/kə\'mit | kə\'mɪt/', 'commit', 5);
INSERT INTO `words` VALUES (24641, 'a committee meeting', 'n. 委员会', '/kə\'miti | kə\'mɪtɪ | kə\'mɪti/', 'committee', 5);
INSERT INTO `words` VALUES (24642, 'agricultural commodities', 'n. 日用品；商品；农/矿产品；有用之物', '/kə\'mɔditi | kə\'mɒdɪtɪ | kə\'mɑdəti/', 'commodity', 5);
INSERT INTO `words` VALUES (24643, 'Heart disease is one of the commonest causes of death.', 'adj. 普通的；共同的；一般的；n.公有地', '/\'kɔmən | \'kɒmən | \'kɑmən/', 'common', 5);
INSERT INTO `words` VALUES (24644, 'Inter-racial marriages have become commonplace.', 'adj. 普通的n.寻常的事物，平庸的东西', '/\'kɔmənpleis | \'kɒmənpleɪs | \'kɑmən\'ples/', 'commonplace', 5);
INSERT INTO `words` VALUES (24645, '...the Asian, Caribbean and African members of the commonwealth.', 'n. 共和国,联邦,共同体', '/\'kɔmənwelθ | \'kɒmənwelθ | \'kɑmən\'wɛlθ/', 'commonwealth', 5);
INSERT INTO `words` VALUES (24646, 'We communicated mostly by e-mail.', 'v. 传达,传送;交流;通讯,通话', '/kə\'mjuːnɪkeɪt | kə\'mjunɪket/', 'communicate', 5);
INSERT INTO `words` VALUES (24647, 'a week’s course in improving communication skills', 'n. 通讯,传达;(pl.)通讯系统;交通', '/kəmjuːnɪ\'keɪʃ(ə)n | kə,mjunɪ\'keʃən/', 'communication', 5);
INSERT INTO `words` VALUES (24648, '...the ultimate triumph of communism in the world.', 'n. 共产主义', '/\'kɔmjunizəm | \'kɒmjʊnɪz(ə)m | \'kɑmjʊ\'nɪzəm/', 'communism', 5);
INSERT INTO `words` VALUES (24649, 'The new arts centre will serve the whole community.', 'n. 同一地区全体居民,社会,社区;共同体', '/kə\'mju:niti | kə\'mjuːnɪtɪ | kə\'mjʊnəti/', 'community', 5);
INSERT INTO `words` VALUES (24650, 'Baldry’s 20-year prison sentence was commuted to three years.', 'v. （搭乘车、船等）通勤；代偿; n. 通勤（口语）', '/kə\'mjuːt | kə\'mjʊt/', 'commute', 5);
INSERT INTO `words` VALUES (24651, 'The bushes grew in a compact mass.', 'n. 合同，契约；小粉盒; adj. 紧凑的，紧密的；简洁的; v. 使简洁；使紧密结合', '/kəm\'pækt, \'kɔmpækt | kəm\'pækt | \'kɑmpækt/', 'compact', 5);
INSERT INTO `words` VALUES (24652, 'For ten years he had been her constant companion .', 'n. 同伴,共事者;伴侣', '/kəm\'pænjən | kəm\'pænɪən/', 'companion', 5);
INSERT INTO `words` VALUES (24653, 'Which company do you work for?', 'n. 公司;陪伴;宾客;连(队),(一)群,队,伙', '/\'kʌmp(ə)ni | \'kʌmp(ə)nɪ | \'kʌmpəni/', 'company', 5);
INSERT INTO `words` VALUES (24654, 'A car of comparable size would cost far more abroad.', 'adj. (with,to)可比较的,比得上的', '/\'kɔmpərəbl | \'kɒmp(ə)rəb(ə)l | \'kɑmpərəbl/', 'comparable', 5);
INSERT INTO `words` VALUES (24655, 'After a lifetime of poverty, his last few years were spent in comparable comfort.', 'adj. 比较的,相当的', '/kəm\'pærətiv | kəm\'pærətɪv/', 'comparative', 5);
INSERT INTO `words` VALUES (24656, 'The report compares the different types of home computer available.', 'v. (to，with)比较；(to)把…比作vi.相比', '/kəm\'peə | kəm\'pɛr/', 'compare', 5);
INSERT INTO `words` VALUES (24657, 'Her paintings invite comparison with those of the early Impressionists (= they remind you of them ) .', 'n. 比较,对比,比喻,比拟', '/kəm\'pærisən | kəm\'pærɪs(ə)n | kəm\'pærɪsn/', 'comparison', 5);
INSERT INTO `words` VALUES (24658, 'The bag is divided into separate compartments .', 'n. 卧车包房,隔间;分隔的空间', '/kəm\'pɑ:tmənt | kəm\'pɑːtm(ə)nt | kəm\'pɑrtmənt/', 'compartment', 5);
INSERT INTO `words` VALUES (24659, 'a map and compass', 'n. 指南针，罗盘；圆规; v. 包围', '/\'kʌmpəs/', 'compass', 5);
INSERT INTO `words` VALUES (24660, 'I was shocked by the doctor’s lack of compassion .', 'n. 同情；怜悯', '/kəm\'pæʃən | kəm\'pæʃ(ə)n/', 'compassion', 5);
INSERT INTO `words` VALUES (24661, 'The new software is IBM compatible (= can be used with IBM computers ) .', 'adj. 兼容的；能共处的；可并立的', '/kəm\'pætəbl | kəm\'pætɪb(ə)l/', 'compatible', 5);
INSERT INTO `words` VALUES (24662, 'His performance compelled the audience’s attention .', 'v. 强迫，迫使；强使发生; n. (Compel)人名；(法)孔佩尔', '/kəm\'pel | kəm\'pɛl/', 'compel', 5);
INSERT INTO `words` VALUES (24663, 'Because my left eye is so weak, my right eye has to work harder to compensate.', 'v. (for)补偿,赔偿', '/\'kɔmpenseit | \'kɒmpenseɪt | \'kɑmpɛnset/', 'compensate', 5);
INSERT INTO `words` VALUES (24664, 'People who are wrongly arrested may be paid compensation .', 'n. 补偿(或赔偿)的款物；补偿，赔偿', '/,kɔmpen\'seiʃən | kɒmpen\'seɪʃ(ə)n | ,kɑmpɛn\'seʃən/', 'compensation', 5);
INSERT INTO `words` VALUES (24665, 'He will be competing in the 100-metre race.', 'v. 比赛；竞争；对抗', '/kəm\'pi:t | kəm\'piːt | kəm\'pit/', 'compete', 5);
INSERT INTO `words` VALUES (24666, 'A competent mechanic should be able to fix the problem.', 'adj. 有能力的，能胜任的；足够的', '/\'kɔmpitənt | \'kɒmpɪt(ə)nt | \'kɑmpɪtənt/', 'competent', 5);
INSERT INTO `words` VALUES (24667, 'Going to trade fairs is an ideal opportunity to size up the competition .', 'n. 竞争，比赛；角逐，较量；竞争者', '/,kɔmpi\'tiʃən | kɒmpɪ\'tɪʃ(ə)n | ,kɑmpə\'tɪʃən/', 'competition', 5);
INSERT INTO `words` VALUES (24668, 'Some US industries are not as competitive as they have been in the past.', 'adj. 竞争的；好竞争的；有竞争力的', '/kəm\'petitiv | kəm\'petɪtɪv | kəm\'pɛtətɪv/', 'competitive', 5);
INSERT INTO `words` VALUES (24669, 'The document was compiled by the Department of Health.', 'v. 编译；编制；编辑；[图情] 汇编', '/kəm\'pail | kəm\'paɪl/', 'compile', 5);
INSERT INTO `words` VALUES (24670, 'Residents are complaining because traffic in the area has increased.', 'v. 投诉；发牢骚；诉说', '/kəm\'plein | kəm\'pleɪn | kəm\'plen/', 'complain', 5);
INSERT INTO `words` VALUES (24671, 'If you wish to make a complaint, you should see the manager.', 'n. 抱怨；诉苦；疾病；委屈', '/kəm\'pleint | kəm\'pleɪnt | kəm\'plent/', 'complaint', 5);
INSERT INTO `words` VALUES (24672, 'The green wallpaper is the perfect complement to the old pine of the dresser.', 'n. 补语；余角；补足物; v. 补足，补助', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪment/', 'complement', 5);
INSERT INTO `words` VALUES (24673, 'The computer and the human mind have different but complementary abilities.', 'adj. 补充的； 辅助的', '/ˌkɒmplɪ\'mentri | \'kɑmplə\'mɛntri/', 'complementary', 5);
INSERT INTO `words` VALUES (24674, 'The police were in complete control of the situation.', 'adj. 完整的；完全的；彻底的; v. 完成', '/kəm\'pli:t | kəm\'pliːt | kəm\'plit/', 'complete', 5);
INSERT INTO `words` VALUES (24675, 'a complex system of highways', 'adj. 复杂的；合成的， 综合的; n. 综合体', '/\'kɒmpleks | ˈkɑmplɛks;kəmˈplɛks/', 'complex', 5);
INSERT INTO `words` VALUES (24676, 'The situation is complicated by the fact that I’ve got to work late on Friday.', 'v. 变复杂', '/\'kɒmplɪkeɪt | \'kɑmplɪket/', 'complicate', 5);
INSERT INTO `words` VALUES (24677, 'a complicated voting system', 'adj. 难懂的，复杂的', '/\'kɔmplikeitid | \'kɒmplɪkeɪtɪd | \'kɑmplɪketɪd/', 'complicated', 5);
INSERT INTO `words` VALUES (24678, 'The fact that the plane was late added a further complication to our journey.', 'n. 并发症；复杂；复杂化；混乱', '/,kɔmpli\'keiʃən | kɒmplɪ\'keɪʃ(ə)n | ,kɑmplɪ\'keʃən/', 'complication', 5);
INSERT INTO `words` VALUES (24679, 'All the guests paid her extravagant compliments.', 'n. 恭维；称赞；问候；致意；道贺; v. 恭维；称赞', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪmənt/', 'compliment', 5);
INSERT INTO `words` VALUES (24680, 'The newspaper was asked by federal agents for assistance and agreed to comply.', 'v. 遵守；顺从，遵从；答应', '/kəm\'plai | kəm\'plaɪ/', 'comply', 5);
INSERT INTO `words` VALUES (24681, 'Gorbachev failed to keep the component parts of the Soviet Union together.', 'adj. 组成的，构成的; n. 成分；组件；[电子] 元件', '/kəm\'pəunənt | kəm\'pəʊnənt | kəm\'ponənt/', 'component', 5);
INSERT INTO `words` VALUES (24682, 'Barrington has composed the music for a new production of ‘A Midsummer Night’s Dream’.', 'v. 组成,构成;(of)由…组成;创作(诗歌等)', '/kəm\'pəuz | kəm\'pəʊz | kəm\'poz/', 'compose', 5);
INSERT INTO `words` VALUES (24683, 'The author builds up a useful compo-site picture of contemporary consumer culture.', 'adj. 混合成的，综合成的n.合成物，复合材料', '/\'kɔmpəzit | \'kɒmpəzɪt | kɑm\'pɑzɪt/', 'composite', 5);
INSERT INTO `words` VALUES (24684, 'Some minerals have complex chemical compositions.', 'n. 作品,作文,乐曲;作曲;结构,组成,成分', '/kɒmpə\'zɪʃ(ə)n | ,kɑmpə\'zɪʃən/', 'composition', 5);
INSERT INTO `words` VALUES (24685, 'man-made organic compounds', 'n. [化学] 化合物；混合物；复合词; adj. 复合的；混合的; v. 合成；混合；恶化，加重；和解，妥协', '/\'kɒmpaʊnd | \'kɑmpaʊnd/', 'compound', 5);
INSERT INTO `words` VALUES (24686, 'She cannot comprehend the extent of the disaster.', 'v. 理解；包含；由…组成', '/,kɔmpri\'hend | kɒmprɪ\'hend | ,kɑmprɪ\'hɛnd/', 'comprehend', 5);
INSERT INTO `words` VALUES (24687, 'Why you let her talk you into doing such a foolish thing is beyond my comprehension (= impossible for me to understand ) .', 'n. 理解， 领悟', '/ˌkɒmprɪ\'henʃn | ,kɑmprɪ\'hɛnʃən/', 'comprehension', 5);
INSERT INTO `words` VALUES (24688, 'We offer our customers a comprehensive range of financial products.', 'adj. 综合的；广泛的；有理解力的; n. 综合学校；专业综合测验', '/,kɔmpri\'hensiv | kɒmprɪ\'hensɪv | ˌkɑːmprɪˈhensɪv/', 'comprehensive', 5);
INSERT INTO `words` VALUES (24689, 'Light silk is best for parachutes, as it compresses well and then expands rapidly.', 'v. 受压缩小', '/kəm\'pres, \'kɔmpres | kəm\'pres | kəm\'prɛs/', 'compress', 5);
INSERT INTO `words` VALUES (24690, 'The house comprises two bedrooms, a kitchen, and a living room.', 'v. 包含，包括，由...组成；构成，组成', '/kəm\'praiz | kəm\'praɪz/', 'comprise', 5);
INSERT INTO `words` VALUES (24691, 'She admitted that she was unable to compromise.', 'v. 妥协；危害; n. 妥协，和解；折衷', '/\'kɔmprəmaiz | \'kɒmprəmaɪz | \'kɑmprəmaɪz/', 'compromise', 5);
INSERT INTO `words` VALUES (24692, 'the threat of compulsory redundancies', 'adj. 义务的；必修的；被强制的; n. （花样滑冰、竞技体操等的）规定动作', '/kəm\'pʌlsəri | kəm\'pʌls(ə)rɪ/', 'compulsory', 5);
INSERT INTO `words` VALUES (24693, 'Final results had not yet been computed.', 'v. 计算；估算；用计算机计算; n. 计算；估计；推断', '/kəm\'pju:t | kəm\'pjuːt | kəm\'pjʊt/', 'compute', 5);
INSERT INTO `words` VALUES (24694, 'Comrades, please support this motion.', 'n. 同志；伙伴', '/\'kɔmrid | \'kɒmreɪd | \'kɑmræd/', 'comrade', 5);
INSERT INTO `words` VALUES (24695, 'The shadows concealed her as she crept up to the house.', 'v. 隐藏；隐瞒', '/kən\'si:l | kən\'siːl | kən\'sil/', 'conceal', 5);
INSERT INTO `words` VALUES (24696, '‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.', 'v. 承认；容许；(比赛结束前)认输；退让', '/kən\'si:d | kən\'siːd | kən\'sid/', 'concede', 5);
INSERT INTO `words` VALUES (24697, 'Scientists first conceived the idea of the atomic bomb in the 1930’s.', 'v. (of)设想,构思,想象;以为;怀胎,怀有', '/kən\'si:v | kən\'siːv | kən\'siv/', 'conceive', 5);
INSERT INTO `words` VALUES (24698, 'Now please concentrate.', 'v. 集中；浓缩；全神贯注；聚集; n. 浓缩，精选；浓缩液', '/\'kɔnsəntreit | \'kɒns(ə)ntreɪt | \'kɑnsn\'tret/', 'concentrate', 5);
INSERT INTO `words` VALUES (24699, 'She needed all her powers of concentration to stop herself from slipping on the icy road.', 'n. 浓度；集中；浓缩；专心；集合', '/,kɔnsən\'treiʃən | kɒns(ə)n\'treɪʃ(ə)n | \'kɑnsn\'treʃən/', 'concentration', 5);
INSERT INTO `words` VALUES (24700, 'a new concept in business travel', 'n. 概念，观念，设想', '/\'kɔnsept | \'kɒnsept | \'kɑnsɛpt/', 'concept', 5);
INSERT INTO `words` VALUES (24701, 'the original conception of the book', 'n. 概念， 观念；设想， 构想', '/kən\'sepʃn | kən\'sɛpʃən/', 'conception', 5);
INSERT INTO `words` VALUES (24702, 'Issues like food additives do concern me.', 'v. 涉及，关系到；使担心; n. 关系；关心；关心的事；忧虑', '/kən\'sɜːn | kən\'sɝn/', 'concern', 5);
INSERT INTO `words` VALUES (24703, 'calls from young children concerning lost pets', 'prep. 关于；就…而言; v. 涉及；使关心（concern的ing形式）；忧虑', '/kən\'sə:niŋ | kən\'sɜːnɪŋ | kən\'sɝnɪŋ/', 'concerning', 5);
INSERT INTO `words` VALUES (24704, 'a rock concert', 'n. 音乐会,演奏会;一齐,一致', '/kən\'sə:t, \'kɔnsə:t | \'kɒnsət | \'kɑnsɚt/', 'concert', 5);
INSERT INTO `words` VALUES (24705, 'The British were not prepared to make any concessions .', 'n. 让步，妥协；特许(权)；', '/kən\'seʃən | kən\'seʃ(ə)n | kən\'sɛʃən/', 'concession', 5);
INSERT INTO `words` VALUES (24706, 'Your summary should be as clear and concise as possible.', 'adj. 简明的,简洁的', '/kən\'sais | kən\'saɪs/', 'concise', 5);
INSERT INTO `words` VALUES (24707, 'When the investigation is concluded, the results will be sent to the US Attorney’s office.', 'v. 结束,终止;断定,下结论;缔结,议定', '/kən\'klu:d | kən\'kluːd | kən\'klud/', 'conclude', 5);
INSERT INTO `words` VALUES (24708, 'These are the report’s main conclusions.', 'n. 结论，推论；结尾；缔结，议定', '/kən\'klu:ʒən | kən\'kluːʒ(ə)n | kən\'kluʒn/', 'conclusion', 5);
INSERT INTO `words` VALUES (24709, 'a concrete floor', 'adj. 具体的,实质性的n.混凝土v.用混凝土修筑', '/kən\'kri:t, \'kɔnkri:t | \'kɒŋkriːt | \'kɑŋkrit/', 'concrete', 5);
INSERT INTO `words` VALUES (24710, 'Politicians were quick to condemn the bombing.', 'v. 谴责；判刑，定罪；声讨', '/kən\'dem | kən\'dɛm/', 'condemn', 5);
INSERT INTO `words` VALUES (24711, 'the mist which condensed on every cold surface', 'v. 浓缩；凝结', '/kən\'dens | kən\'dɛns/', 'condense', 5);
INSERT INTO `words` VALUES (24712, 'Conditions in the prison were atrocious.', 'n. 条件；情况；环境；身份; v. 决定；使适应；使健康；以…为条件', '/kən\'diʃən | kən\'dɪʃ(ə)n | kən\'dɪʃən/', 'condition', 5);
INSERT INTO `words` VALUES (24713, 'The Senator’s conduct is being investigated by the Ethics Committee.', 'n. 行为,品行; v. 引导;管理;指挥(乐队);传导', '/\'kɔndʌkt, kən\'dʌkt | \'kɒndʌkt | kən\'dʌkt/', 'conduct', 5);
INSERT INTO `words` VALUES (24714, 'Wood is a poor conductor of heat.', 'n. 管理者；售票员；领队，指挥；导体', '/kən\'dʌktə | kən\'dʌktɚ/', 'conductor', 5);
INSERT INTO `words` VALUES (24715, 'The constitution also confers large powers on Brazil\'s 25 constituent states.', 'v. 授予；给予; n. (Confer)人名；(英)康弗', '/kən\'fə: | kən\'fɜː | kən\'fɝ/', 'confer', 5);
INSERT INTO `words` VALUES (24716, 'Representatives from over 100 countries attended the International Peace Conference in Geneva.', 'n. 会议， 讨论会', '/\'kɒnfərəns | \'kɑnfərəns/', 'conference', 5);
INSERT INTO `words` VALUES (24717, 'Occasionally people confess to crimes they haven’t committed just to get attention.', 'v. 承认；坦白；忏悔；供认', '/kən\'fes | kən\'fɛs/', 'confess', 5);
INSERT INTO `words` VALUES (24718, 'I felt I was doing well and my confidence began to grow.', 'n. 信心；信任；秘密; adj. （美）诈骗的；骗得信任的', '/\'kɔnfidəns | \'kɒnfɪd(ə)ns | \'kɑnfɪdəns/', 'confidence', 5);
INSERT INTO `words` VALUES (24719, 'Despite her disability, Philippa is very confident.', 'adj. 确信的， 自信的', '/\'kɒnfɪdənt | \'kɑnfɪdənt/', 'confident', 5);
INSERT INTO `words` VALUES (24720, 'a confidential government report', 'adj. 机密的；表示信任的；获信任的', '/,kɔnfi\'denʃəl | kɒnfɪ\'denʃ(ə)l | ,kɑnfɪ\'dɛnʃl/', 'confidential', 5);
INSERT INTO `words` VALUES (24721, 'Vaughan is confined to a wheelchair .', 'v. 限制；使不外出，禁闭n.[pl.]界限，范围', '/kən\'faɪn/', 'confine', 5);
INSERT INTO `words` VALUES (24722, 'New evidence has confirmed the first witness’s story.', 'v. 确认；确定；证实；批准；使巩固', '/kən\'fə:m | kən\'fɜːm | kən\'fɝm/', 'confirm', 5);
INSERT INTO `words` VALUES (24723, 'the threat of industrial conflict in the coalfields', 'n. 冲突，矛盾；斗争；争执; v. 冲突，抵触；争执；战斗', '/kən\'flikt, \'kɔnflikt | \'kɒnflɪkt | \'kɑnflɪkt/', 'conflict', 5);
INSERT INTO `words` VALUES (24724, 'The lamp has been designed to conform to new safety standards.', 'v. (to)遵守，适应；相似，一致，符合', '/kən\'fɔ:m | kən\'fɔːm | kən\'fɔrm/', 'conform', 5);
INSERT INTO `words` VALUES (24725, 'The problems confronting the new government were enormous.', 'v. 面对；遭遇；比较', '/kən\'frʌnt/', 'confront', 5);
INSERT INTO `words` VALUES (24726, 'People might well confuse the two products.', 'v. 使混乱,混淆', '/kən\'fju:z | kən\'fjuːz | kən\'fjʊz/', 'confuse', 5);
INSERT INTO `words` VALUES (24727, 'To avoid confusion, the teams wore different colours.', 'n. 困惑，糊涂；混淆；混乱，骚乱', '/kən\'fju:ʒən | kən\'fjuːʒ(ə)n | kən\'fjʊʒən/', 'confusion', 5);
INSERT INTO `words` VALUES (24728, 'He never even stopped to congratulate me.', 'v. (on)祝贺,向…致贺词', '/kən\'ɡrætʃu,leit | kən\'grætjʊleɪt | kən\'ɡrætʃulet/', 'congratulate', 5);
INSERT INTO `words` VALUES (24729, 'letters of congratulation', 'n. (on)祝贺,(pl.)祝贺词', '/kən,ɡrætʃu\'leiʃən | kəngrætjʊ\'leɪʃ(ə)n | kən,ɡrætʃu\'leʃən/', 'congratulation', 5);
INSERT INTO `words` VALUES (24730, 'a congress of the ruling Labor Party', 'n. (代表)大会;(美国等国的)国会,议会', '/\'kɔŋɡres, kən\'ɡres | \'kɒŋgres | \'kɑŋɡrəs/', 'congress', 5);
INSERT INTO `words` VALUES (24731, 'The worksheets are designed to be used in conjunction with the new course books.', 'n. 结合；[语] 连接词；同时发生', '/kən\'dʒʌŋkʃən | kən\'dʒʌŋ(k)ʃ(ə)n/', 'conjunction', 5);
INSERT INTO `words` VALUES (24732, 'Police have so far failed to establish a connection between the two murders.', 'n. 连接；关系；人脉；连接件', '/kəˈnekʃn | kə\'nɛkʃən/', 'connection', 5);
INSERT INTO `words` VALUES (24733, 'The connexion is not a simple derivation.', 'n. 联系， 连接', '/kə\'nekʃn | kə\'nekʃən/', 'connexion', 5);
INSERT INTO `words` VALUES (24734, 'The Normans conquered England in 1066.', 'v. 战胜，征服；攻克，攻取', '/\'kɔŋkə | \'kɒŋkə | \'kɑŋkɚ/', 'conquer', 5);
INSERT INTO `words` VALUES (24735, 'the Norman Conquest (= the conquest of England by the Normans )', 'n. 征服，战胜；战利品', '/\'kɔŋkwest | \'kɒŋkwest | \'kɑŋkwɛst/', 'conquest', 5);
INSERT INTO `words` VALUES (24736, 'Well, at least I can face them all with a clear conscience (= the knowledge that you have done nothing wrong ) .', 'n. 道德心，良心', '/\'kɔnʃəns | \'kɒnʃ(ə)ns | ˈkɑːnʃəns/', 'conscience', 5);
INSERT INTO `words` VALUES (24737, 'A conscientious teacher may feel inclined to take work home.', 'adj. 认真的；尽责的；本着良心的；小心谨慎的', '/,kɔnʃi\'enʃəs | ,kɒnʃɪ\'enʃəs | \'kɑnʃɪ\'ɛnʃəs/', 'conscientious', 5);
INSERT INTO `words` VALUES (24738, 'The driver was still conscious when the ambulance arrived.', 'adj. 意识到的；故意的；神志清醒的', '/\'kɔnʃəs | \'kɒnʃəs | \'kɑnʃəs/', 'conscious', 5);
INSERT INTO `words` VALUES (24739, 'It had rained for four consecutive days.', 'adj. 连续的；连贯的；顺序的', '/kən\'sekjutiv | kən\'sekjʊtɪv | kən\'sɛkjətɪv/', 'consecutive', 5);
INSERT INTO `words` VALUES (24740, 'The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.', 'n. (意见等的)一致，一致同意，共识', '/kən\'sensəs | kən\'sɛnsəs/', 'consensus', 5);
INSERT INTO `words` VALUES (24741, 'The chairman was elected by common consent (= with most people agreeing ) .', 'v&n. (to)同意,赞成,答应', '/kən\'sent | kən\'sɛnt/', 'consent', 5);
INSERT INTO `words` VALUES (24742, 'I don’t suppose it is of any consequence now.', 'n. 结果,后果,影响;重要性', '/\'kɔnsi,kwəns | \'kɒnsɪkw(ə)ns | \'kɑnsəkwɛns/', 'consequence', 5);
INSERT INTO `words` VALUES (24743, 'Most computer users have never received any formal keyboard training. Consequently, their keyboard skills are inefficient.', 'adv. 结果，因此，所以', '/\'kɔnsi,kwəntli | \'kɒnsɪkw(ə)ntlɪ | \'kɑnsəkwɛntli/', 'consequently', 5);
INSERT INTO `words` VALUES (24744, 'wildlife conservation', 'n. 保存，保持；保护', '/,kɔnsə\'veiʃən | kɒnsə\'veɪʃ(ə)n | ,kɑnsɚ\'veʃən/', 'conservation', 5);
INSERT INTO `words` VALUES (24745, 'a very conservative attitude to education', 'adj. 保守的; n. 保守派，守旧者', '/kən\'sə:vətiv | kən\'sɜːvətɪv | kən\'sɝvətɪv/', 'conservative', 5);
INSERT INTO `words` VALUES (24746, 'We will have to consider your offer carefully .', 'v. 考虑，细想；体谅，顾及；认为，把…看作', '/kən\'sidə | kən\'sɪdə | kən\'sɪdɚ/', 'consider', 5);
INSERT INTO `words` VALUES (24747, 'Michael has already spent considerable time in Barcelona.', 'adj. 相当大(或多)的,可观的;值得考虑的', '/kən\'sidərəbl | kən\'sɪd(ə)rəb(ə)l | kən\'sɪdərəbl/', 'considerable', 5);
INSERT INTO `words` VALUES (24748, 'I think he\'s the most charming, most considerate man I\'ve ever known.', 'adj. 考虑周到的,体谅的', '/kən\'sidərit | kən\'sɪd(ə)rət | kənˈsɪdərɪt/', 'considerate', 5);
INSERT INTO `words` VALUES (24749, 'proposals put forward for consideration', 'n. 需要考虑的事;考虑,思考;体谅,照顾', '/kən,sidə\'reiʃən | kənsɪdə\'reɪʃ(ə)n | kən,sɪdə\'reʃən/', 'consideration', 5);
INSERT INTO `words` VALUES (24750, 'My diet consisted almost exclusively of chocolate-covered cookies and glasses of milk.', 'v. (in)在于,存在于;(of)由…组成,由…构成', '/kən\'sɪst/', 'consist', 5);
INSERT INTO `words` VALUES (24751, 'The evidence is not consistent.', 'adj. (in)前后一致的；（with）一致，符合', '/kən\'sistənt | kən\'sɪst(ə)nt | kən\'sɪstənt/', 'consistent', 5);
INSERT INTO `words` VALUES (24752, 'No one could console her when Peter died.', 'n. 控制台，仪表板；落地柜; v. 安慰，慰问', '/kən\'səul | kən\'səʊl | \'kɑnsol/', 'console', 5);
INSERT INTO `words` VALUES (24753, 'The company has consolidated its position as the country’s leading gas supplier.', 'v. 使加固，使加强；(把)联为一体，合并', '/kən\'sɔlideit | kən\'sɒlɪdeɪt | kən\'sɑlɪdet/', 'consolidate', 5);
INSERT INTO `words` VALUES (24754, 'The notice must be displayed in a conspicuous place.', 'adj. 显眼的,明显的', '/kən\'spikjuəs | kən\'spɪkjʊəs/', 'conspicuous', 5);
INSERT INTO `words` VALUES (24755, 'There were many conspiracy theories (= beliefs that something is the result of a conspiracy ) surrounding Princess Diana’s death.', 'n. 阴谋，密谋，共谋', '/kən\'spirəsi | kən\'spɪrəsɪ | kən\'spɪrəsi/', 'conspiracy', 5);
INSERT INTO `words` VALUES (24756, 'There was a constant stream of visitors to the house.', 'adj. 不变的；恒定的；经常的; n. [数] 常数；恒量', '/\'kɔnstənt | \'kɒnst(ə)nt | \'kɑnstənt/', 'constant', 5);
INSERT INTO `words` VALUES (24757, 'He told his constituents that he would continue to represent them to the best of his ability.', 'n. 成分；选民；委托人; adj. 构成的；选举的', '/kən\'stitjuənt | kən\'stɪtjʊənt | kən\'stɪtʃuənt/', 'constituent', 5);
INSERT INTO `words` VALUES (24758, 'We must redefine what constitutes a family.', 'v. 组成，构成；建立；任命', '/\'kɔnstitju:t | \'kɒnstɪtjuːt | \'kɑnstətut/', 'constitute', 5);
INSERT INTO `words` VALUES (24759, 'The right to speak freely is written into the Constitution of the United States.', 'n. 宪法；体制；章程；构造；建立，组成；体格', '/kɒnstɪ\'tjuːʃ(ə)n | \'kɑnstə\'tʊʃən/', 'constitution', 5);
INSERT INTO `words` VALUES (24760, 'Poor soil has constrained the level of crop production.', 'v. 驱使；强迫；束缚', '/kən\'strein | kən\'streɪn | kən\'stren/', 'constrain', 5);
INSERT INTO `words` VALUES (24761, 'There are plans to construct a new road bridge across the river.', 'v. 建造，构造；创立; n. 构想，概念', '/kən\'strʌkt/', 'construct', 5);
INSERT INTO `words` VALUES (24762, 'a road construction project', 'n. 建设；建筑物；解释；造句', '/kən\'strʌkʃən | kən\'strʌkʃ(ə)n/', 'construction', 5);
INSERT INTO `words` VALUES (24763, 'If symptoms persist, consult a doctor without delay.', 'v. 请教，向...咨询，找...商量；查阅，查看', '/kɔn\'sʌlt, \'kɔnsʌlt | kən\'sʌlt/', 'consult', 5);
INSERT INTO `words` VALUES (24764, 'a management consultant', 'n. 会诊医师,顾问医生;顾问', '/kən\'sʌltənt | kən\'sʌlt(ə)nt/', 'consultant', 5);
INSERT INTO `words` VALUES (24765, 'Only 27% of the paper we consume is recycled.', 'v. 消耗；吃完，喝光；(with)使着迷；烧毁', '/kən\'sju:m | kən\'sjuːm | kənˈsum/', 'consume', 5);
INSERT INTO `words` VALUES (24766, 'Vigorous exercise increases oxygen consumption.', 'n. 消费(量),消耗', '/kən\'sʌmpʃən | kən\'sʌm(p)ʃ(ə)n/', 'consumption', 5);
INSERT INTO `words` VALUES (24767, 'The town is cut off from contact with the outside world.', 'v&n. (使)接触,联系,交往', '/\'kɒntækt | \'kɑntækt/', 'contact', 5);
INSERT INTO `words` VALUES (24768, 'The patient is still highly contagious.', 'adj. 传染性的， 会蔓延的', '/kən\'teɪdʒəs | kən\'tedʒəs/', 'contagious', 5);
INSERT INTO `words` VALUES (24769, 'The thieves stole a purse containing bank-notes.', 'v. 包含，容纳；容忍，抑制；可被...除尽', '/kən\'tein | kən\'teɪn | kən\'ten/', 'contain', 5);
INSERT INTO `words` VALUES (24770, 'ice cream in plastic containers', 'n. 容器;集装箱', '/kən\'teinə | kən\'teɪnə | kən\'tenɚ/', 'container', 5);
INSERT INTO `words` VALUES (24771, 'Drinking water supplies are believed to have been contaminated.', 'v. 污染，弄脏', '/kən\'tæmɪneɪt | kən\'tæmɪnet/', 'contaminate', 5);
INSERT INTO `words` VALUES (24772, 'He had even contemplated suicide.', 'v. 盘算，计议；周密考虑；注视，凝视', '/\'kɔntəm,pleit | \'kɒntempleɪt; -təm- | \'kɑntəmplet/', 'contemplate', 5);
INSERT INTO `words` VALUES (24773, 'She writes a lot of contemporary music for people like Whitney Houston.', 'adj. 现代的,当代的;同时代的 time', '/kən\'tempərəri | kən\'temp(ə)r(ər)ɪ | kən\'tɛmpərɛri/', 'contemporary', 5);
INSERT INTO `words` VALUES (24774, 'The public is treated with contempt by broadcasters.', 'n. 轻视，藐视；受辱，丢脸', '/kən\'tempt | kən\'tem(p)t | kən\'tɛmpt/', 'contempt', 5);
INSERT INTO `words` VALUES (24775, 'Inevitably, fights break out between the members of contending groups.', 'v. 竞争；奋斗；斗争；争论', '/kən\'tend | kən\'tɛnd/', 'contend', 5);
INSERT INTO `words` VALUES (24776, 'His brothers are contesting the will.', 'v. 争辩；质疑; n. 竞赛；争夺；争论', '/\'kɒntest | kən\'tɛst/', 'contest', 5);
INSERT INTO `words` VALUES (24777, 'The meaning of ‘mad’ depends on its context. mad', 'n. 环境；上下文；来龙去脉', '/\'kɔntekst | \'kɒntekst | \'kɑntɛkst/', 'context', 5);
