INSERT INTO `words` VALUES (24779, 'five weeks of continual rain', 'adj. 不断的,连续的,频繁的', '/kən\'tinjuəl | kən\'tɪnjʊəl | kən\'tɪnjuəl/', 'continual', 5);
INSERT INTO `words` VALUES (24780, 'He will be continuing his education in the US.', 'v. 继续,连续,延伸', '/kən\'tinju: | kən\'tɪnjuː | kən\'tɪnju/', 'continue', 5);
INSERT INTO `words` VALUES (24781, 'continuous economic growth', 'adj. 连续的,持续的', '/kən\'tinjuəs | kən\'tɪnjʊəs/', 'continuous', 5);
INSERT INTO `words` VALUES (24782, 'Employees who refuse to relocate are in breach of contract (= have done something not allowed by their contracts ) .', 'n. (承包)合同/契约; v. 订合同/契约；使缩小', '/\'kɔntrækt, kən\'trækt | \'kɒntrækt | \'kɑntrækt/', 'contract', 5);
INSERT INTO `words` VALUES (24783, 'Deborah opened her mouth to contradict, but closed it again.', 'v. 反驳;同…矛盾,同…抵触', '/,kɔntrə\'dikt | kɒntrə\'dɪkt | \'kɑntrə\'dɪkt/', 'contradict', 5);
INSERT INTO `words` VALUES (24784, 'apparent contradictions in the defendant’s testimony', 'n. 反驳，否认；矛盾，不一致', '/,kɔntrə\'dikʃən | kɒntrə\'dɪkʃ(ə)n | ,kɑntrə\'dɪkʃən/', 'contradiction', 5);
INSERT INTO `words` VALUES (24785, 'Two contrary views emerged.', 'adj. 相反的；对立的; adv. 相反地; n. 相反；反面', '/\'kɔntrəri | \'kɒntrərɪ | \'kɑntrɛri/', 'contrary', 5);
INSERT INTO `words` VALUES (24786, 'an essay comparing and contrasting (= showing how two things are similar and different ) Verdi and Wagner and their operas', 'v. 对比；形成对照; n. 对比；差别；对照物', '/kən\'trɑ:st, -\'træst, \'kɔntrɑ:st, -træst | \'kɒntrɑːst | \'kɑntræst/', 'contrast', 5);
INSERT INTO `words` VALUES (24787, 'The three sons also contribute to the family business.', 'v. 贡献，出力；投稿；捐献', '/kən\'trɪbjuːt; \'kɒntrɪbjuːt | kən\'trɪbjut/', 'contribute', 5);
INSERT INTO `words` VALUES (24788, 'a campaign contribution', 'n. 贡献；捐献；投稿', '/,kəntri\'bju:ʃən | kɒntrɪ\'bjuːʃ(ə)n | ,kɑntrɪ\'bjuʃən/', 'contribution', 5);
INSERT INTO `words` VALUES (24789, 'In 1862, a technique was contrived to take a series of photographs showing stages of movement.', 'v. 设计；发明；图谋', '/kən\'traiv | kən\'traɪv/', 'contrive', 5);
INSERT INTO `words` VALUES (24790, 'the controversial issue of welfare reform', 'adj. 引起争论的,有争议的', '/,kɔntrə\'və:ʃəl | kɒntrə\'vɜːʃ(ə)l | ,kɑntrə\'vɝʃl/', 'controversial', 5);
INSERT INTO `words` VALUES (24791, 'a political controversy', 'n. 争论，辩论，争吵', '/\'kɔntrə,və:si | \'kɒntrəvɜːsɪ; kən\'trɒvəsɪ | ˈkɑːntrəvɜːrsi/', 'controversy', 5);
INSERT INTO `words` VALUES (24792, 'Ready meals sell well because of their convenience.', 'n. 便利,方便;(pl.)便利设备', '/kən\'vi:njəns | kən\'viːnɪəns | kən\'vinɪəns/', 'convenience', 5);
INSERT INTO `words` VALUES (24793, 'Mail-order catalogs are a convenient way to shop.', 'adj. (to)便利的,方便的', '/kən\'viːnɪənt | kən\'vinɪənt/', 'convenient', 5);
INSERT INTO `words` VALUES (24794, 'a teachers’ convention', 'n. 大会,会议;惯例,常规,习俗;公约,协定', '/kən\'venʃən | kən\'venʃ(ə)n | kən\'vɛnʃən/', 'convention', 5);
INSERT INTO `words` VALUES (24795, 'Internet connections through conventional phone lines are fairly slow.', 'adj. 惯例的,常规的', '/kən\'venʃənəl | kən\'venʃ(ə)n(ə)l | kən\'vɛnʃənl/', 'conventional', 5);
