INSERT INTO `words` VALUES (24797, 'a telephone conversation', 'n. 会话,谈话', '/kɒnvə\'seɪʃ(ə)n | ,kɑnvɚ\'seʃən/', 'conversation', 5);
INSERT INTO `words` VALUES (24798, 'American consumers prefer white eggs; conversely, British buyers like brown eggs.', 'adv. 相反地', '/\'kɔnvə:sli | \'kɒnvɜːslɪ; kən\'vɜːslɪ | \'kɑnvɝsli/', 'conversely', 5);
INSERT INTO `words` VALUES (24799, '...the conversion of disused rail lines into cycle routes.', 'n. 转变，转换；信仰的改变；', '/kən\'və:ʃən | kən\'vɜːʃ(ə)n | kən\'vɝʒn/', 'conversion', 5);
INSERT INTO `words` VALUES (24800, 'The signal will be converted into digital code.', 'v. 变换,转换；改变（信仰等）；兑换（钱）', '/kən\'və:t | kən\'vɜːt | kən\'vɝt/', 'convert', 5);
INSERT INTO `words` VALUES (24801, 'All this information can be conveyed in a simple diagram.', 'vt. 运送， 搬运， 转运；表达； 传播', '/kən\'veɪ | kən\'ve/', 'convey', 5);
INSERT INTO `words` VALUES (24802, 'a convicted murderer', 'v. (经审讯)证明…有罪,宣判…有罪; n. 囚犯', '/kən\'vikt | kən\'vɪkt/', 'convict', 5);
INSERT INTO `words` VALUES (24803, 'It was a reasonable explanation, but his voice lacked conviction .', 'n. 深信,确信；定罪，判罪；', '/kən\'vɪkʃ(ə)n | kən\'vɪkʃən/', 'conviction', 5);
INSERT INTO `words` VALUES (24804, 'Her arguments didn’t convince everyone, but changes were made.', 'v. 说服；使确信，使信服', '/kən\'vins | kən\'vɪns/', 'convince', 5);
INSERT INTO `words` VALUES (24805, 'Where did you learn to cook?', 'v. 烹调，煮; n. 厨师，厨子', '/kuk | kʊk/', 'cook', 5);
INSERT INTO `words` VALUES (24806, 'She swam out into the cool water.', 'adj. 凉爽的；冷静的；出色的; v. 使…冷却；使…平静下来; n. 凉爽；凉爽的空气; adv. 冷静地', '/ku:l | kuːl | kul/', 'cool', 5);
INSERT INTO `words` VALUES (24807, 'They agreed to co-operate with Brazil on a programme to protect the rain forests.', 'v. 合作，配合；协力', '/kəu\'ɔpəreit | kəʊ\'ɒpəreɪt | koʊˈɑːpəreɪt/', 'cooperate', 5);
INSERT INTO `words` VALUES (24808, 'He was doing his best to be cooperative.', 'adj. 合作的；合作社的; n. 合作社', '/kəu\'ɔpərətiv | kəʊ\'ɒpərətɪv | ko\'ɑpərətɪv/', 'cooperative', 5);
INSERT INTO `words` VALUES (24809, 'coordinate clauses joined by ‘and’', 'adj. 同等的; n. 同等者,坐标; v. 协作，协调', '/kəu\'ɔ:dinit, kəu\'ɔ:dineit | kəʊ\'ɔ:dɪneɪt | ko\'ɔrdɪnet/', 'coordinate', 5);
INSERT INTO `words` VALUES (24810, 'Cop hold of the other end, will you?', 'v. 抓住; n. 巡警，警官', '/kɔp | kɒp | kɑp/', 'cop', 5);
INSERT INTO `words` VALUES (24811, 'Sometimes I find it hard to cope.', 'v. 处理；对付；竞争; n. 长袍', '/kəup | kəʊp | kop/', 'cope', 5);
INSERT INTO `words` VALUES (24812, 'He offered to do the job for a few coppers.', 'n. 铜；铜币；警察; adj. 铜制的; v. 镀铜', '/\'kɒpə | \'kɑpɚ/', 'copper', 5);
INSERT INTO `words` VALUES (24813, 'Could you copy this letter and send it out, please?', 'v. 复制；复印；抄袭; n. 副本；一册；摹仿', '/\'kɔpi | \'kɒpɪ | \'kɑpi/', 'copy', 5);
INSERT INTO `words` VALUES (24814, 'Who owns the copyright of this book?', 'n. 版权，著作权; adj. 版权的；受版权保护的; v. 保护版权；为…取得版权', '/\'kɔpi,rait | \'kɒpɪraɪt | \'kɑpɪraɪt/', 'copyright', 5);
INSERT INTO `words` VALUES (24815, 'The robe was held at the waist by a cord.', 'n. 绳索；束缚; v. 用绳子捆绑', '/kɔ:d | kɔːd | kɔrd/', 'cord', 5);
INSERT INTO `words` VALUES (24816, 'The talks were conducted in a cordial atmosphere.', 'adj. 热忱的，诚恳的；兴奋的; n. 补品；兴奋剂；甜香酒，甘露酒', '/\'kɔ:djəl | \'kɔːdɪəl | \'kɔrdʒəl/', 'cordial', 5);
INSERT INTO `words` VALUES (24817, 'Remove the cores, and bake the apples for 40 minutes.', 'n. 核心；要点；果心；[计] 磁心; v. 挖的核', '/kɔ: | kɔː | kɔr/', 'core', 5);
INSERT INTO `words` VALUES (24818, 'fields of corn', 'n. （美）玉米；（英）谷物；[皮肤] 鸡眼; v. 腌；使成颗粒', '/kɔ:n | kɔːn | kɔrn/', 'corn', 5);
INSERT INTO `words` VALUES (24819, 'He pulled a dirty handkerchief out by its corner and waved it at me.', 'n. 角落，拐角处；地区，偏僻处；困境，窘境; v. 囤积；相交成角', '/\'kɔ:nə | \'kɔːnə | \'kɔrnɚ/', 'corner', 5);
INSERT INTO `words` VALUES (24820, 'He works for a large American corporation.', 'n. 市镇自治机关；法人；公司，企业', '/,kɔ:pə\'reiʃən | kɔːpə\'reɪʃ(ə)n | ,kɔrpə\'reʃən/', 'corporation', 5);
INSERT INTO `words` VALUES (24821, 'If my calculations are correct, we’re about ten miles from Exeter.', 'adj. 正确的,恰当的,端正的; v. 改正,纠正,矫正', '/kə\'rekt | kə\'rɛkt/', 'correct', 5);
INSERT INTO `words` VALUES (24822, 'Attempts to correlate specific language functions with particular parts of the brain have not advanced very far.', 'v. 关联; n. 相关物；相关联的人; adj. 关联的', '/\'kɔ:rə,leit | \'kɒrəleɪt; -rɪ- | \'kɔrəlet/', 'correlate', 5);
INSERT INTO `words` VALUES (24823, 'The two halves of the document did not correspond.', 'vi. 通信；符合， 一致；相当于， 对应', '/ˌkɒrə\'spɒnd | ,kɔrə\'spɑnd/', 'correspond', 5);
INSERT INTO `words` VALUES (24824, 'The magazine is unable to enter into any correspondence on medical matters.', 'n. 通信；一致；相当', '/,kɔ:ris\'pɔndəns | kɒrɪ\'spɒnd(ə)ns | ,kɔrə\'spɑndəns/', 'correspondence', 5);
INSERT INTO `words` VALUES (24825, 'Our correspondent in South Africa sent this report.', 'n. 通讯记者；客户；通信者；代理商行', '/,kɔ:ri\'spɔndənt | kɒrɪ\'spɒnd(ə)nt | ,kɔrə\'spɑndənt/', 'correspondent', 5);
INSERT INTO `words` VALUES (24826, 'The war and the corresponding fall in trade have had a devastating effect on the country.', 'adj. 相当的，相应的；一致的；通信的; v. 类似（correspond的ing形式）；相配', '/,kɔ:ri\'spɔndiŋ | ,kɒrɪ\'spɒndɪŋ | ,kɔrə\'spɑndɪŋ/', 'corresponding', 5);
INSERT INTO `words` VALUES (24827, 'Go down here and the bathroom’s at the end of the corridor.', 'n. 走廊', '/\'kɒrɪdɔː | \'kɔrɪdɔr/', 'corridor', 5);
INSERT INTO `words` VALUES (24828, 'Acidic water will corrode the pipes.', 'v. 侵蚀；损害', '/kə\'rəud | kə\'rəʊd | kə\'rod/', 'corrode', 5);
INSERT INTO `words` VALUES (24829, 'Corrupt judges have taken millions of dollars in bribes.', 'adj. 腐败的，贪污的；堕落的; v. 使腐烂；使堕落，使恶化', '/kə\'rʌpt/', 'corrupt', 5);
INSERT INTO `words` VALUES (24830, '...the cosmic laws governing our world.', 'adj. 宇宙的（等于cosmical）', '/\'kɔzmik | \'kɒzmɪk | \'kɑzmɪk/', 'cosmic', 5);
INSERT INTO `words` VALUES (24831, 'Such a database would be extremely costly to set up.', 'adj. 昂贵的；代价高的; n. (Costly)人名；(英)科斯特利', '/\'kɔstli | \'kɒs(t)lɪ/', 'costly', 5);
INSERT INTO `words` VALUES (24832, 'the film’s lavish costumes and spectacular sets', 'n. 服装，装束；戏装，剧装; v. 给…穿上服装', '/\'kɔstju:m, kɔ\'stju:m | \'kɒstjuːm | \'kɑstum/', 'costume', 5);
INSERT INTO `words` VALUES (24833, 'The living room was warm and cosy .', 'adj. 舒适的；惬意的; n. 保温罩', '/\'kəuzi | \'kəʊzɪ | ˈkozi/', 'cosy', 5);
INSERT INTO `words` VALUES (24834, 'a country cottage', 'n. 小屋；村舍；（农舍式的）小别墅', '/\'kɔtidʒ | \'kɒtɪdʒ | \'kɑtɪdʒ/', 'cottage', 5);
INSERT INTO `words` VALUES (24835, 'a white cotton shirt', 'n. 棉花；棉布；棉线; v. 一致；理解；和谐；亲近; adj. 棉的；棉制的', '/\'kɔtən | \'kɒt(ə)n | \'kɑtn/', 'cotton', 5);
INSERT INTO `words` VALUES (24836, 'Tom offered to sleep on the couch.', 'n. 睡椅，长沙发；床；卧榻; v. 蹲伏，埋伏；躺着', '/kautʃ | kaʊtʃ/', 'couch', 5);
INSERT INTO `words` VALUES (24837, 'He’s got a bad cough.', 'n. 咳嗽，咳嗽声；咳嗽病; v. 咳出', '/kɔ:f | kɒf | kɔf/', 'cough', 5);
INSERT INTO `words` VALUES (24838, 'the council for civil liberties', 'n. 委员会；会议；理事会；地方议会；顾问班子', '/\'kaunsəl | \'kaʊns(ə)l; -sɪl | \'kaʊnsl/', 'council', 5);
INSERT INTO `words` VALUES (24839, 'He had always been able to count on her wise counsel.', 'n. 法律顾问；忠告；商议；讨论；决策; v. 建议；劝告', '/\'kaunsəl | \'kaʊns(ə)l | \'kaʊnsl/', 'counsel', 5);
INSERT INTO `words` VALUES (24840, 'I was amazed at the number of plants - I counted 147.', 'v. 数,计算;算入;看作,认为; n. 计数,总数', '/kaunt | kaʊnt/', 'count', 5);
INSERT INTO `words` VALUES (24841, 'He wondered if the girl behind the counter recognised him.', 'n. 柜台;计数器; a&ad. 相反(的); v. 反对,反击', '/英 [ˈkaʊntə(r)] 美 [ˈkaʊntɚ | \'kaʊntə | \'kaʊntɚ/', 'counter', 5);
INSERT INTO `words` VALUES (24842, 'As soon as he heard what was afoot, he telephoned his German and Italian counterparts to protest.', 'n. 对应的人(或物)', '/\'kauntə,pɑ:t | \'kaʊntəpɑːt | \'kaʊntɚpɑrt/', 'counterpart', 5);
INSERT INTO `words` VALUES (24843, 'the Scandinavian countries', 'n. 国家;农村,乡下', '/\'kʌntrɪ | \'kʌntri/', 'country', 5);
INSERT INTO `words` VALUES (24844, 'The house had lovely views over open countryside .', 'n. 乡下,农村', '/\'kʌntri,said | \'kʌntrɪsaɪd/', 'countryside', 5);
INSERT INTO `words` VALUES (24845, 'Fairfax County, Virginia', 'n. (英国)郡,(美国)县', '/\'kaunti | \'kaʊntɪ | \'kaʊnti/', 'county', 5);
INSERT INTO `words` VALUES (24846, 'a newly married couple', 'n. 对；夫妇；数个; v. 结合；成婚', '/\'kʌpl | \'kʌp(ə)l/', 'couple', 5);
INSERT INTO `words` VALUES (24847, 'The coupon entitles you to ten cents off your next purchase.', 'n. 息票；赠券；联票；[经] 配给券', '/\'ku:pɔn | \'kuːpɒn | \'kupɑn/', 'coupon', 5);
INSERT INTO `words` VALUES (24848, 'Sue showed great courage throughout her illness.', 'n. 勇气；胆量', '/\'kʌridʒ | \'kʌrɪdʒ | \'kɝrɪdʒ/', 'courage', 5);
INSERT INTO `words` VALUES (24849, 'It could not be proved in a court of law.', 'n. 法院；球场；朝廷；奉承; v. 招致（失败、危险等）；向…献殷勤；设法获得', '/kɔ:t | kɔːt | kɔrt/', 'court', 5);
INSERT INTO `words` VALUES (24850, 'It’s a matter of common courtesy to acknowledge letters.', 'n. 谦恭有礼；有礼貌的举止', '/\'kɜːtəsi | \'kɝtəsi/', 'courtesy', 5);
INSERT INTO `words` VALUES (24851, 'the castle courtyard', 'n. 庭院，院子；天井', '/\'kɔ:t,jɑ:d | \'kɔːtjɑːd | \'kɔrtjɑrd/', 'courtyard', 5);
INSERT INTO `words` VALUES (24852, 'My cousin Mark helped me to bring in the bags.', 'n. 堂兄弟姊妹；表兄弟姊妹', '/\'kʌzən | \'kʌz(ə)n | \'kʌzn/', 'cousin', 5);
INSERT INTO `words` VALUES (24853, 'Grey mould covered the walls.', 'v. 覆盖,包括,涉及; n. 盖子,套子;(书的)封面', '/\'kʌvə | \'kʌvɚ/', 'cover', 5);
INSERT INTO `words` VALUES (24854, 'a herd of cows', 'n. 奶牛，母牛；母兽; v. 威胁，恐吓', '/kau | kaʊ/', 'cow', 5);
INSERT INTO `words` VALUES (24855, 'Try it. Don’t be such a coward.', 'n. 懦夫，懦弱的人; adj. 胆小的，懦怯的', '/\'kauəd | \'kaʊəd | \'kaʊɚd/', 'coward', 5);
INSERT INTO `words` VALUES (24856, 'And on that bed there is a granny, a snoring granny on a cozy bed in a napping house, where everyone is sleeping.', 'adj. 温暖而舒适的', '/\'kəuzi | \'kozi/', 'cozy', 5);
INSERT INTO `words` VALUES (24857, 'crab meat', 'n. 螃蟹；蟹肉；脾气乖戾的人；起重机; v. 抱怨；破坏；使偏航', '/kræb/', 'crab', 5);
INSERT INTO `words` VALUES (24858, 'Don’t put boiling water in the glass or it will crack.', 'v. 使破裂；打开；变声; n. 裂缝；声变；噼啪声; adj. 最好的；高明的', '/kræk/', 'crack', 5);
INSERT INTO `words` VALUES (24859, 'She rocked the cradle to quieten the child.', 'n. 摇篮；发源地；发祥地；支船架; v. 抚育；把搁在支架上；把放在摇篮内', '/\'kreidl | \'kreɪd(ə)l | \'kredl/', 'cradle', 5);
INSERT INTO `words` VALUES (24860, 'traditional rural crafts', 'n. 工艺；手艺；太空船; v. 精巧地制作', '/krɑ:ft, kræft | krɑːft | kræft/', 'craft', 5);
INSERT INTO `words` VALUES (24861, 'The little prefabricated hut was lifted away by a huge crane.', 'n. 吊车，起重机；鹤; v. 伸着脖子看；迟疑，踌躇', '/krein | kreɪn | kren/', 'crane', 5);
INSERT INTO `words` VALUES (24862, 'a crash victim', 'n. 撞碎；坠毁；破产；轰隆声；睡觉; v. 摔碎；坠落；发出隆隆声；(金融企业等)破产', '/kræʃ/', 'crash', 5);
INSERT INTO `words` VALUES (24863, 'The floor was crawling with ants.', 'v. 爬行；匍匐行进; n. 爬行；养鱼池；匍匐而行', '/krɔ:l | krɔːl | krɔl/', 'crawl', 5);
INSERT INTO `words` VALUES (24864, 'The neighbours must think we’re crazy.', 'adj. 疯狂的；狂热的，着迷的', '/\'kreizi | \'kreɪzɪ | \'krezi/', 'crazy', 5);
INSERT INTO `words` VALUES (24865, 'fresh cream', 'n. 乳脂,(鲜)奶油;奶油色', '/kri:m | kriːm | krim/', 'cream', 5);
INSERT INTO `words` VALUES (24866, 'Some people believe the universe was created by a big explosion.', 'v. 创造,创作;引起,造成,建立', '/kri\'eit | kriː\'eɪt | krɪ\'et/', 'create', 5);
INSERT INTO `words` VALUES (24867, 'This job is so boring. I wish I could do something more creative.', 'adj. 有创造力的,创造性的', '/kri\'eitiv | kriː\'eɪtɪv | krɪ\'etɪv/', 'creative', 5);
INSERT INTO `words` VALUES (24868, 'all the living creatures in the sea', 'n. 人,动物;生物', '/\'kri:tʃə | \'kriːtʃə | \'kritʃɚ/', 'creature', 5);
INSERT INTO `words` VALUES (24869, NULL, 'n. 证书；凭据；国书', '/kri\'denʃəl | krɪ\'denʃ(ə)l | krə\'dɛnʃl/', 'credential', 5);
INSERT INTO `words` VALUES (24870, 'Her academic credentials include an MA and a PhD.', 'n. 证明书； 证件；资格', '/krə\'denʃlz | krə\'dɛnʃlz/', 'credentials', 5);
INSERT INTO `words` VALUES (24871, 'The store agreed to let him have credit.', 'n. 信用，信誉；[金融] 贷款；学分；信任；声望; v. 相信，信任；把…归给，归功于；赞颂', '/\'kredit | \'kredɪt | \'krɛdɪt/', 'credit', 5);
INSERT INTO `words` VALUES (24872, 'He crept back up the stairs, trying to avoid the ones that creaked.', 'v. 爬行；蔓延；慢慢地移动；起鸡皮疙瘩; n. 爬行；毛骨悚然的感觉；谄媚者', '/kri:p | kriːp | krip/', 'creep', 5);
INSERT INTO `words` VALUES (24873, 'The plane crashed, killing two of the crew and four passengers.', 'n. 队，组；全体人员，全体船员; v. 一起工作', '/kru: | kruː | krʊ/', 'crew', 5);
INSERT INTO `words` VALUES (24874, 'Why should you spring my cricket bat?', 'n. 板球，板球运动；蟋蟀', '/\'krikit | \'krɪkɪt/', 'cricket', 5);
INSERT INTO `words` VALUES (24875, 'We moved here because there was very little crime.', 'n. 罪行,犯罪', '/kraim | kraɪm/', 'crime', 5);
INSERT INTO `words` VALUES (24876, 'Police have described the man as a violent and dangerous criminal.', 'n. 罪犯,刑事犯; adj. 犯罪的,刑事的', '/\'kriminəl | \'krɪmɪn(ə)l | \'krɪmɪnl/', 'criminal', 5);
INSERT INTO `words` VALUES (24877, 'She has gone from being a healthy, fit, and sporty young woman to being a cripple.', 'n. 跛子,残疾人; v. 使跛,使残疾', '/\'kripl | \'krɪp(ə)l | \'krɪpl/', 'cripple', 5);
INSERT INTO `words` VALUES (24878, 'The country now faces an economic crisis .', 'n. (pl.crises)危机,紧要关头', '/\'kraisis | \'kraɪsɪs/', 'crisis', 5);
INSERT INTO `words` VALUES (24879, 'She kicked at the crisp leaves at her feet.', 'adj. 脆的,易碎的;简明扼要的；（空气）清爽的', '/krisp | krɪsp/', 'crisp', 5);
INSERT INTO `words` VALUES (24880, 'the criteria we use to select candidates', 'n. (pl.criteria或s)标准，尺度', '/krai\'tiəriən | kraɪ\'tɪərɪən | kraɪˈtɪriən/', 'criterion', 5);
INSERT INTO `words` VALUES (24881, 'Mather was a film critic for many years.', 'n. 批评家,评论家', '/\'kritik | \'krɪtɪk/', 'critic', 5);
INSERT INTO `words` VALUES (24882, 'He made some highly critical remarks.', 'adj. 批评的,评论的;危急,紧要的;临界的', '/\'kritikəl | \'krɪtɪk(ə)l | \'krɪtɪkl/', 'critical', 5);
INSERT INTO `words` VALUES (24883, 'If you or your partner criticise each other habitually, you are attacking their personality.', 'v. 批评， 评论', '/\'krɪtɪsaɪz | \'kriti,saiz/', 'criticise', 5);
INSERT INTO `words` VALUES (24884, 'Despite strong criticism , the new system is still in place.', 'n. 评论性的文章，评论；批评，指责，非难', '/\'krɪtɪsɪzəm | \'krɪtɪsɪz(ə)m | \'krɪtə\'sɪzəm/', 'criticism', 5);
INSERT INTO `words` VALUES (24885, 'Ron does nothing but criticize and complain all the time.', 'v. (criticise)批评,评论', '/ˈkrɪtɪsaɪz | \'krɪtɪsaɪz | \'krɪtə\'saɪz/', 'criticize', 5);
INSERT INTO `words` VALUES (24886, 'The main crops were oats and barley.', 'n. 产量；农作物；庄稼；平头; v. 种植；收割；修剪；剪短', '/krɔp | krɒp | krɑp/', 'crop', 5);
INSERT INTO `words` VALUES (24887, 'Ben rushed to his father, crowing with pleasure.', 'v. 啼叫；报晓; n. [鸟] 乌鸦；鸡鸣；撬棍', '/krəu | krəʊ | kro/', 'crow', 5);
INSERT INTO `words` VALUES (24888, 'A vast crowd gathered in the main square.', 'n. 群众,一伙;一堆,许多,大众; v. 拥挤,挤满,挤进', '/[kraud] | kraʊd/', 'crowd', 5);
INSERT INTO `words` VALUES (24889, 'a hat with a high crown', 'n. 王冠；花冠；王权；顶点; v. 加冕；居…之顶；表彰；使圆满完成', '/kraun | kraʊn/', 'crown', 5);
INSERT INTO `words` VALUES (24890, 'The conservation of tropical forests is of crucial importance .', 'adj. 重要的；决定性的；定局的；决断的', '/\'kru:ʃəl | \'kruːʃ(ə)l | \'krʊʃəl/', 'crucial', 5);
INSERT INTO `words` VALUES (24891, 'a crude estimate of the population available for work', 'adj. 粗糙的；天然的，未加工的；粗鲁的; n. 原油；天然的物质', '/kru:d | kruːd | krud/', 'crude', 5);
INSERT INTO `words` VALUES (24892, 'His death was a cruel blow .', 'adj. 残酷的，残忍的；使人痛苦的，让人受难的；无情的，严酷的', '/英 [\'kru:əl] 美 [ˈkruəl] | krʊəl | \'kruəl/', 'cruel', 5);
INSERT INTO `words` VALUES (24893, 'She wants to cruise the canals of France in a barge.', 'v. 巡航，巡游；漫游; n. 巡航，巡游；乘船游览', '/kru:z | kruːz | krʊz/', 'cruise', 5);
INSERT INTO `words` VALUES (24894, 'His leg was crushed in the accident.', 'v. 压碎；弄皱，变形；使…挤入; n. 粉碎；迷恋；压榨；拥挤的人群', '/krʌʃ/', 'crush', 5);
INSERT INTO `words` VALUES (24895, 'sandwiches with the crusts cut off', 'n. 地壳；外壳；面包皮；坚硬外皮; v. 结硬皮；结成外壳', '/krʌst/', 'crust', 5);
INSERT INTO `words` VALUES (24896, 'a baby’s cry', 'n. &v.叫，喊，哭；(鸟兽)叫，啼，鸣，嗥', '/krai | kraɪ/', 'cry', 5);
INSERT INTO `words` VALUES (24897, 'a set of six crystal glasses', 'n. 水晶,水晶饰品;结晶; adj. 水晶的,透明的', '/\'kristəl | \'krɪst(ə)l | \'krɪstl/', 'crystal', 5);
INSERT INTO `words` VALUES (24898, 'a sugar cube', 'n. 立方；立方体；骰子; v. 使成立方形；使自乘二次；量…的体积', '/kju:b | kjuːb | kjʊb/', 'cube', 5);
INSERT INTO `words` VALUES (24899, 'The \"gurkophone\" is one of their classics, made from a hollowed cucumber, a pepper and a carrot.', 'n. 黄瓜；胡瓜', '/\'kju:kʌmbə | \'kjuːkʌmbə | \'kjʊ,kʌmbɚ/', 'cucumber', 5);
INSERT INTO `words` VALUES (24900, 'She stood nervously in the wings waiting for her cue.', 'n. 提示，暗示；线索; v. 给…暗示', '/kju: | kjuː | kju/', 'cue', 5);
INSERT INTO `words` VALUES (24901, 'Police finally managed to catch the culprit.', 'n. 罪犯', '/\'kʌlprɪt/', 'culprit', 5);
INSERT INTO `words` VALUES (24902, 'The land was too rocky to cultivate.', 'vt. 耕作， 栽培； 养殖；培养， 教养； 磨炼', '/\'kʌltɪveɪt | \'kʌltɪvet/', 'cultivate', 5);
INSERT INTO `words` VALUES (24903, 'a cunning opponent', 'adj. 狡猾的， 狡诈的；精巧的， 巧妙的; n. 狡猾， 狡诈', '/\'kʌnɪŋ/', 'cunning', 5);
INSERT INTO `words` VALUES (24904, 'Mathew picked up the cup and sipped his coffee.', 'n. 杯子；奖杯，优胜杯；(一)杯，一杯的容量', '/kʌp/', 'cup', 5);
INSERT INTO `words` VALUES (24905, 'It’s in the kitchen cupboard.', 'n. 碗柜,小橱', '/\'kʌbəd | \'kʌbɚd/', 'cupboard', 5);
INSERT INTO `words` VALUES (24906, 'He called for much stricter curbs on immigration.', 'n. 路边，场外证券市场，vt.制止，抑制', '/kə:b | kɜːb | kɝb/', 'curb', 5);
INSERT INTO `words` VALUES (24907, 'Many types of cancer can now be cured.', 'v. (of)治愈,医治;矫正; n. 治愈,痊愈;良药', '/kjuə | kjʊə; kjɔː | kjʊr/', 'cure', 5);
INSERT INTO `words` VALUES (24908, 'I opened the packet just to satisfy my curiosity .', 'n. 好奇心;古董,古玩', '/,kjuri\'ɔsiti | kjʊərɪ\'ɒsɪtɪ | ,kjʊrɪ\'ɑsəti/', 'curiosity', 5);
INSERT INTO `words` VALUES (24909, 'Puppies are naturally curious.', 'adj. 好奇的, 求知的, 古怪的, 爱挑剔的', '/\'kjuəriəs | \'kjʊərɪəs | \'kjʊrɪəs/', 'curious', 5);
INSERT INTO `words` VALUES (24910, 'She has hair that refuses to curl.', 'v. (使)卷曲,蜷缩; n. 卷发;卷曲状;卷曲物', '/kə:l | kɜːl | kɝl/', 'curl', 5);
INSERT INTO `words` VALUES (24911, 'The bank can supply you with foreign currency .', 'n. 流传,流通；通货,货币', '/\'kərənsi | \'kʌr(ə)nsɪ | ˈkɜrənsi/', 'currency', 5);
INSERT INTO `words` VALUES (24912, 'Strong currents can be very dangerous for swimmers.', 'n. 电流,水流;潮流,趋势; adj. 当前的;流通的', '/\'kʌrənt | \'kʌr(ə)nt | kɝ​ənt/', 'current', 5);
INSERT INTO `words` VALUES (24913, 'Languages are an essential part of the school curriculum.', 'n. 课程,(学校等的)全部课程', '/kə\'rikjuləm | kə\'rɪkjʊləm | kə\'rɪkjələm/', 'curriculum', 5);
INSERT INTO `words` VALUES (24914, 'He muttered a curse under his breath.', 'n. 诅咒；咒骂; v. 诅咒；咒骂', '/kə:s | kɜːs | kɝs/', 'curse', 5);
INSERT INTO `words` VALUES (24915, 'red velvet curtains', 'n. 窗帘,门帘;幕(布);结束； vt遮掩', '/\'kə:tən | \'kɜːt(ə)n | \'kɝtn/', 'curtain', 5);
INSERT INTO `words` VALUES (24916, 'The curve illustrates costs per capita.', 'n. 曲线,弯曲(物); v. 弄弯,成曲形', '/kə:v | kɜːv | kɝv/', 'curve', 5);
INSERT INTO `words` VALUES (24917, 'a velvet cushion', 'n. 垫子；起缓解作用之物；（猪等的）臀肉；银行储蓄; v. 给…安上垫子；把…安置在垫子上；缓和…的冲击', '/\'kuʃən | \'kʊʃ(ə)n | \'kʊʃən/', 'cushion', 5);
INSERT INTO `words` VALUES (24918, 'He awoke early, as was his custom.', 'n. 习惯,风俗,惯例;(pl.)海关,关税', '/\'kʌstəm/', 'custom', 5);
INSERT INTO `words` VALUES (24919, 'Barbara answered with her customary enthusiasm.', 'adj. 习惯的,惯例的', '/\'kʌstə,məri | \'kʌstəm(ə)rɪ | \'kʌstə\'mɛri/', 'customary', 5);
INSERT INTO `words` VALUES (24920, 'We aim to offer good value and service to all our customers.', 'n. 顾客,主顾', '/\'kʌstəmə | \'kʌstəmɚ/', 'customer', 5);
INSERT INTO `words` VALUES (24921, 'Do you want me to cut the cake?', 'n&v. 切，割，削;削减，删节; n. 切口，伤口', '/kʌt/', 'cut', 5);
INSERT INTO `words` VALUES (24922, 'Students are discovering the endless amount of information in cyberspace.', 'n. 网络空间；赛博空间', '/\'saibə,speis | \'saɪbəspeɪs | \'saɪbɚspes/', 'cyberspace', 5);
INSERT INTO `words` VALUES (24923, 'a woman’s menstrual cycle', 'n. 自行车;周期,循环; v. 骑自行车;循环', '/\'saikl | \'saɪk(ə)l | \'saɪkl/', 'cycle', 5);
INSERT INTO `words` VALUES (24924, 'The gases are stored in cylinders.', 'n. 圆筒；汽缸；[数] 柱面；圆柱状物', '/\'silində | \'sɪlɪndə | \'sɪlɪndɚ/', 'cylinder', 5);
INSERT INTO `words` VALUES (24925, 'daily flights to Miami', 'adj. 日常的；每日的; n. 日报；朝来夜去的女佣; adv. 日常地；每日；天天', '/\'deili | \'deɪlɪ | \'delɪ/', 'daily', 5);
INSERT INTO `words` VALUES (24926, 'In my childhood, local dairies bought milk from local farmers.', 'n. 奶制品；乳牛；制酪场；乳品店；牛奶及乳品业; adj. 乳品的；牛奶的；牛奶制的；产乳的', '/\'dεəri | \'deərɪ | \'dɛri/', 'dairy', 5);
INSERT INTO `words` VALUES (24927, 'They built a dam along the seashore to retain the seawater.', 'v. 控制；筑坝; n. [水利] 水坝；障碍', '/dæm/', 'dam', 5);
INSERT INTO `words` VALUES (24928, 'These chemicals have been found to cause serious environmental damage.', 'n. 损害；损毁；赔偿金; v. 损害；损毁', '/\'dæmɪdʒ/', 'damage', 5);
INSERT INTO `words` VALUES (24929, '...a sensational book in which she damns the ultraright party.', 'v. 谴责；罚…下地狱; n. 一点；诅咒; adj. 可恶的; adv. 非常; int. 讨厌', '/dæm/', 'damn', 5);
INSERT INTO `words` VALUES (24930, 'Damp had stained the walls.', 'v. 使潮湿；使阻尼；使沮丧，抑制; n. 潮湿，湿气; adj. 潮湿的', '/dæmp/', 'damp', 5);
INSERT INTO `words` VALUES (24931, 'Danger! No boats beyond this point.', 'n. 危险；危险物，威胁', '/\'deindʒə | \'deɪn(d)ʒə | \'dendʒɚ/', 'danger', 5);
INSERT INTO `words` VALUES (24932, 'laws about dangerous dogs', 'adj. 危险的', '/\'deindʒərəs | \'deɪn(d)ʒ(ə)rəs | \'dendʒərəs/', 'dangerous', 5);
INSERT INTO `words` VALUES (24933, 'Jones broke into a military base on a dare.', 'n. 挑战；挑动; v. 敢冒；不惧', '/dεə | deə | dɛr/', 'dare', 5);
INSERT INTO `words` VALUES (24934, 'The church was dark and quiet.', 'adj. 黑暗的，深色的；模糊的；无知的；忧郁的; n. 黑暗；夜；黄昏；模糊', '/\'dɑ:k | dɑːk | dɑrk/', 'dark', 5);
INSERT INTO `words` VALUES (24935, '...a 160-mile dash to the hospital.', 'n. 破折号；冲撞; v. 使…破灭；猛撞；泼溅', '/dæʃ/', 'dash', 5);
INSERT INTO `words` VALUES (24936, 'The research involves collecting data from two random samples.', 'n. 资料，数据', '/\'deɪtə | \'detə/', 'data', 5);
INSERT INTO `words` VALUES (24937, 'customer details held on a database', 'n. (databank)数据库', '/\'deitəbeis | \'deɪtəbeɪs | \'detəbes/', 'database', 5);
INSERT INTO `words` VALUES (24938, 'The date on the letter was 30th August 1962.', 'n. 日期；约会；年代；枣椰子; v. 过时；注明日期；始于（某一历史时期）', '/deit | deɪt | det/', 'date', 5);
INSERT INTO `words` VALUES (24939, 'She’s got two daughters and one son.', 'n. 女儿；[遗][农学] 子代; adj. 女儿的；子代的', '/\'dɔ:tə | \'dɔːtə | \'dɔtɚ/', 'daughter', 5);
INSERT INTO `words` VALUES (24940, 'He felt utterly daunted by the prospect of moving to another country.', 'vt. 使气馁， 使畏缩', '/dɔ:nt/', 'daunt', 5);
INSERT INTO `words` VALUES (24941, 'When dawn broke (= the first light of the day appeared ) , we were still 50 miles from Calcutta.', 'n. 黎明；开端; v. 破晓；出现；被领悟', '/dɔ:n | dɔːn | dɔn/', 'dawn', 5);
INSERT INTO `words` VALUES (24942, 'The park is open to the public during daylight hours .', 'n. 日光,白昼,黎明', '/\'deilait | \'deɪlaɪt | \'delaɪt/', 'daylight', 5);
INSERT INTO `words` VALUES (24943, 'Can I take your daytime telephone number (= the number of the telephone you use during the day ) ?', 'n. 白天,日间', '/\'deitaim | \'deɪtaɪm | \'detaɪm/', 'daytime', 5);
INSERT INTO `words` VALUES (24944, 'And, though the gleams blind and dazzle, yet do they convey a hint of beauty and serenity greater than we have known or imagined.', 'n. 耀眼的光；灿烂; v. 使……目眩；使……眼花', '/\'dæzl | \'dæz(ə)l/', 'dazzle', 5);
INSERT INTO `words` VALUES (24945, 'Her mother had been dead for ten years.', 'adj. 无生命的；呆板的；废弃了的; adv. 完全地; n. 死者', '/ded | dɛd/', 'dead', 5);
INSERT INTO `words` VALUES (24946, 'I’m always working under pressure to meet deadlines (= finish something on time ) .', 'n. 截止期限，最后期限', '/\'dedlain | \'dedlaɪn | ˈdedlaɪn/', 'deadline', 5);
INSERT INTO `words` VALUES (24947, 'a deadly poison', 'adj. 致命的；非常的；死一般的; adv. 非常；如死一般地', '/\'dedli | \'dedlɪ | \'dɛdli/', 'deadly', 5);
INSERT INTO `words` VALUES (24948, 'communication between deaf and hearing people', 'adj. 聋的', '/def | dɛf/', 'deaf', 5);
INSERT INTO `words` VALUES (24949, 'Whose turn is it to deal?', 'v. 处理；给予；分配；发牌; n. 交易；（美）政策；待遇；份量', '/di:l | diːl | dil/', 'deal', 5);
INSERT INTO `words` VALUES (24950, '...an antique dealer.', 'n. 经销商；商人', '/\'diːlə | \'dilɚ/', 'dealer', 5);
INSERT INTO `words` VALUES (24951, 'the admissions dean', 'n. 院长；系主任；教务长；主持牧师', '/diːn | din/', 'dean', 5);
INSERT INTO `words` VALUES (24952, 'Dear Sir or Madam, ...', 'adj. 亲爱的；尊敬的；昂贵的; adv. 高价地；疼爱地; int. 哎呀; n. 亲爱的人', '/diə | dɪə | dɪr/', 'dear', 5);
INSERT INTO `words` VALUES (24953, 'the gun-control debate in the US', 'v&n. 争论,辩论', '/di\'beit | dɪ\'beɪt | dɪ\'bet/', 'debate', 5);
INSERT INTO `words` VALUES (24954, 'He had enough money to pay off his outstanding debts.', 'n. 债务；借款；罪过', '/det | dɛt/', 'debt', 5);
INSERT INTO `words` VALUES (24955, 'She made her debut in a 1937 production of \"Hamlet.\"', 'n. 初次登台；处女作; vt. 面世， 首次推出', '/\'deɪbjuː ; \'debjuː | de\'bju/', 'debut', 5);
INSERT INTO `words` VALUES (24956, '...the last decade of the nineteenth century.', 'n. 十年，十年期；十', '/\'dekeid | \'dekeɪd; dɪ\'keɪd | \'dɛked/', 'decade', 5);
INSERT INTO `words` VALUES (24957, 'Her body was already starting to decay.', 'v. 衰退，[核] 衰减；腐烂，腐朽; n. 衰退，[核] 衰减；腐烂，腐朽', '/di\'kei | dɪ\'keɪ | dɪ\'ke/', 'decay', 5);
INSERT INTO `words` VALUES (24958, 'an atmosphere of hypocrisy and deceit', 'n. 欺骗,欺骗行为', '/di\'si:t | dɪ\'siːt | dɪ\'sit/', 'deceit', 5);
INSERT INTO `words` VALUES (24959, 'He had been deceived by a young man claiming to be the son of a millionaire.', 'v. 欺骗,蒙蔽', '/di\'si:v | dɪ\'siːv | dɪ\'siv/', 'deceive', 5);
INSERT INTO `words` VALUES (24960, NULL, 'n. 十二月', '/di\'sembə | dɪ\'sembə | dɪ\'sɛmbɚ/', 'december', 5);
INSERT INTO `words` VALUES (24961, 'a decent salary', 'adj. 正派的；得体的；相当好的', '/\'di:sənt | \'diːs(ə)nt | \'disnt/', 'decent', 5);
INSERT INTO `words` VALUES (24962, 'Has anything been decided yet?', 'v. 决定,下决心;解决,裁决', '/di\'said | dɪ\'saɪd/', 'decide', 5);
INSERT INTO `words` VALUES (24963, 'changing to a decimal system', 'adj. 小数的；十进位的; n. 小数', '/\'desiməl | \'desɪm(ə)l | \'dɛsɪml/', 'decimal', 5);
INSERT INTO `words` VALUES (24964, 'Do you ever wonder if you made the right decision?', 'n. 决定,决心;决议;决策', '/di\'siʒən | dɪ\'sɪʒ(ə)n | dɪ\'sɪʒn/', 'decision', 5);
INSERT INTO `words` VALUES (24965, 'a decisive leader', 'adj. 决定性的', '/di\'saisiv | dɪ\'saɪsɪv/', 'decisive', 5);
INSERT INTO `words` VALUES (24966, 'deck furniture', 'n. 甲板；行李仓；露天平台; v. 装饰；装甲板；打扮', '/dek | dɛk/', 'deck', 5);
INSERT INTO `words` VALUES (24967, 'a ceasefire declaration', 'n. （纳税品等的）申报；宣布；公告；申诉书', '/,deklə\'reiʃən | deklə\'reɪʃ(ə)n | ,dɛklə\'reʃən/', 'declaration', 5);
INSERT INTO `words` VALUES (24968, 'A state of emergency has been declared.', 'v. 宣布，声明；断言，宣称', '/di\'klεə | dɪ\'kleə | dɪ\'klɛr/', 'declare', 5);
INSERT INTO `words` VALUES (24969, 'Official figures show a sharp decline in the number of foreign tourists.', 'n. 下降；衰退；斜面; v. 下降；衰落；谢绝', '/di\'klain | dɪ\'klaɪn/', 'decline', 5);
INSERT INTO `words` VALUES (24970, 'Children’s pictures decorated the walls of the classroom.', 'v. 装饰；布置；授勋给', '/\'dekəreit | \'dekəreɪt | \'dɛkəret/', 'decorate', 5);
INSERT INTO `words` VALUES (24971, 'In Spain and Portugal there has been a decrease in the number of young people out of work.', 'n. 减少,减小;减少量; v. 减少,变少,降低', '/di\'kri:s, \'di:-, \'di:kri:s, di\'k- | dɪ\'kriːs | dɪ\'kris/', 'decrease', 5);
INSERT INTO `words` VALUES (24972, 'For the next few years, she dedicated herself to her work.', 'v. 奉献;献身于', '/\'dedikeit, \'dedikit, -keit | \'dedɪkeɪt | \'dɛdɪket/', 'dedicate', 5);
INSERT INTO `words` VALUES (24973, 'Alison cleverly deduced that I was the author of the letter.', 'v. (from)演绎,推断,推论', '/di\'dju:s | dɪ\'djuːs | dɪ\'dʊs/', 'deduce', 5);
INSERT INTO `words` VALUES (24974, 'The company deducted this payment from his compensation.', 'v. 扣除;演绎(推理)', '/di\'dʌkt | dɪ\'dʌkt/', 'deduct', 5);
INSERT INTO `words` VALUES (24975, 'French and German were deemed essential.', 'v. 认为，视作；相信; n. (Deem)人名；(英)迪姆', '/di:m | diːm | dim/', 'deem', 5);
INSERT INTO `words` VALUES (24976, 'a deep wound', 'n. 深处；深渊; adj. 深的；低沉的；深奥的; adv. 深入地；深深地；迟', '/di:p | diːp | dip/', 'deep', 5);
INSERT INTO `words` VALUES (24977, 'The hunter wounded the deer.', 'n. 鹿', '/diə | dɪə | dɪr/', 'deer', 5);
INSERT INTO `words` VALUES (24978, 'The credit card business is down, and more borrowers are defaulting on loans.', 'vi. 不履行义务；拖欠; n. 违约， 拖欠；弃权', '/dɪ\'fɔːlt;\'diːfɔːlt | dɪ\'fɔlt/', 'default', 5);
INSERT INTO `words` VALUES (24979, 'They hoped to defeat the enemy at sea.', 'v. 击败，战胜；挫败；使…失败; n. 失败的事实；击败的行为', '/dɪ\'fiːt | dɪ\'fit/', 'defeat', 5);
INSERT INTO `words` VALUES (24980, 'All the cars are tested for defects before they leave the factory.', 'n. 过失;缺点;不足', '/\'di:fekt, di\'f-, di\'fekt | \'diːfekt; dɪ\'fekt | ‘dɪfɛkt/', 'defect', 5);
INSERT INTO `words` VALUES (24981, 'Liz dropped her defences and began to relax.', 'n. 防御；防卫；答辩；防卫设备', '/di\'fens | dɪ\'fens/', 'defence', 5);
INSERT INTO `words` VALUES (24982, 'She was always defending her husband in front of their daughter.', 'v. 辩护；防护', '/di\'fend | dɪ\'fend | dɪ\'fɛnd/', 'defend', 5);
INSERT INTO `words` VALUES (24983, 'We find the defendant not guilty.', 'n. 被告', '/dɪ\'fendənt | dɪ\'fɛndənt/', 'defendant', 5);
INSERT INTO `words` VALUES (24984, 'The committee deferred their decision .', 'v. 推迟， 延期', '/dɪ\'fɜː | dɪ\'fɝ/', 'defer', 5);
INSERT INTO `words` VALUES (24985, 'They did blood tests on him for signs of vitamin deficiency.', 'n. 缺乏,不足;缺点,缺陷', '/di\'fiʃənsi | dɪ\'fɪʃ(ə)nsɪ | dɪ\'fɪʃənsi/', 'deficiency', 5);
INSERT INTO `words` VALUES (24986, 'the country’s widening budget deficit', 'n. 赤字,逆差;亏损,亏空;不足,缺乏', '/\'defisit | \'defɪsɪt; \'diː- | \'dɛfəsɪt/', 'deficit', 5);
INSERT INTO `words` VALUES (24987, 'I’ll now try to define the term ‘popular culture’.', 'v. 给…下定义;阐述;阐释;限定,规定', '/di\'fain | dɪ\'faɪn/', 'define', 5);
INSERT INTO `words` VALUES (24988, 'It’s impossible for me to give you a definite answer.', 'adj. 明确的;一定的;意志坚强的,立场坚定的', '/\'definit | \'defɪnɪt | \'dɛfɪnət/', 'definite', 5);
INSERT INTO `words` VALUES (24989, 'a dictionary definition', 'n. 定义,解释;(轮廓影像等的)清晰度;阐明;', '/,defi\'niʃən | defɪ\'nɪʃ(ə)n | ,dɛfɪ\'nɪʃən/', 'definition', 5);
INSERT INTO `words` VALUES (24990, 'This was the first (and last) time that I dared to defy my mother.', 'v. 藐视；公然反抗；挑衅；使落空; n. 挑战；对抗', '/di\'fai, \'di:- | dɪ\'faɪ | \'difaɪ/', 'defy', 5);
INSERT INTO `words` VALUES (24991, 'Inactivity can make your joints stiff, and the bones may begin to degenerate.', 'v. 衰退,堕落,蜕化; adj. 堕落的; n. 堕落者', '/di\'dʒenəreit, di\'dʒenərət | dɪ\'dʒen(ə)rət | dɪ\'dʒɛnəret/', 'degenerate', 5);
INSERT INTO `words` VALUES (24992, 'Don’t delay – send off for the information now.', 'v. 延期；耽搁; n. 延期；耽搁；被耽搁或推迟的时间', '/di\'lei | dɪ\'leɪ | dɪ\'le/', 'delay', 5);
INSERT INTO `words` VALUES (24993, 'Officials have now been delegated to start work on a draft settlement.', 'v. 委派…为代表; n. 代表', '/\'deliɡət, -ɡeit, \'deliɡeit | ˈdɛlɪˌɡeɪt; -ɡɪt; (for v.,) ˈdɛlɪˌɡeɪt | ˈdɛləgɪt; (for v.,) ˈdɛləˌgeɪt/', 'delegate', 5);
INSERT INTO `words` VALUES (24994, 'His name was deleted from the list.', 'v. 删除', '/di\'li:t | dɪ\'liːt | dɪ\'lit/', 'delete', 5);
INSERT INTO `words` VALUES (24995, 'a deliberate attempt to humiliate her', 'adj. 故意的；深思熟虑的；从容的; v. 仔细考虑；商议', '/di\'libərət | dɪ\'lɪb(ə)rət | dɪ\'lɪbərət/', 'deliberate', 5);
INSERT INTO `words` VALUES (24996, 'There’s something I have to speak to you about – it’s a delicate matter .', 'adj. 微妙的；精美的，雅致的；柔和的；易碎的；纤弱的；清淡可口的', '/\'delikət | \'delɪkət | ˈdɛlɪkɪt/', 'delicate', 5);
INSERT INTO `words` VALUES (24997, '‘The meal was absolutely delicious,’ she said politely.', 'adj. 美味的；可口的', '/di\'liʃəs | dɪ\'lɪʃəs/', 'delicious', 5);
INSERT INTO `words` VALUES (24998, 'Throughout the house, the views are a constant source of surprise and delight.', 'n. 快乐,高兴; v. (使)高兴,(使)欣喜', '/di\'lait | dɪ\'laɪt/', 'delight', 5);
INSERT INTO `words` VALUES (24999, 'The morning mail has just been delivered.', 'v. 交付， 递送； 释放；发表； 表达；接生', '/dɪ\'lɪvə | dɪ\'lɪvɚ/', 'deliver', 5);
INSERT INTO `words` VALUES (25000, 'Most Indian restaurants offer free delivery.', 'n. [贸易] 交付；分娩；递送', '/di\'livəri | dɪ\'lɪv(ə)rɪ | dɪ\'lɪvəri/', 'delivery', 5);
INSERT INTO `words` VALUES (25001, 'Angry demonstrators demanded the resignation of two senior officials.', 'v. 要求， 请求， 需要； 查问; n. 要求， 请求， 需要', '/dɪ\'mɑːnd | dɪ\'mænd/', 'demand', 5);
INSERT INTO `words` VALUES (25002, 'a return to democracy after 16 years of military rule', 'n. 民主,民主制,民主国家', '/di\'mɔkrəsi | dɪ\'mɒkrəsɪ | dɪˈmɑkrəsi/', 'democracy', 5);
INSERT INTO `words` VALUES (25003, 'a democratic government', 'adj. 民主的', '/,demə\'krætik,-kəl | demə\'krætɪk | \'dɛmə\'krætɪk/', 'democratic', 5);
INSERT INTO `words` VALUES (25004, 'The study demonstrates the link between poverty and malnutrition.', 'v. 论证,证实;演示,说明', '/\'demənstreit | \'demənstreɪt | \'dɛmən\'stret/', 'demonstrate', 5);
INSERT INTO `words` VALUES (25005, 'It seems clear that despite official denials, differences of opinion lay behind the ambassador\'s decision to quit.', 'n. 否认；拒绝；节制；背弃', '/di\'naiəl | dɪ\'naɪ(ə)l | dɪ\'naɪəl/', 'denial', 5);
INSERT INTO `words` VALUES (25006, 'What does the word ‘curriculum’ denote that ‘course’ does not?', 'v. 表示，指示', '/di\'nəut | dɪ\'nəʊt | dɪ\'not/', 'denote', 5);
INSERT INTO `words` VALUES (25007, 'The group denounced the failure by the authorities to take action.', 'v. 公开指责,公然抨击;谴责', '/di\'nauns | dɪ\'naʊns/', 'denounce', 5);
INSERT INTO `words` VALUES (25008, 'a dense rurally-based population', 'adj. 稠密的；浓厚的；愚钝的', '/dens | dɛns/', 'dense', 5);
INSERT INTO `words` VALUES (25009, 'areas of high population density', 'n. 密度', '/\'densəti | \'densɪtɪ | \'dɛnsəti/', 'density', 5);
INSERT INTO `words` VALUES (25010, 'Good oral hygiene and regular dental care are important, whatever your age.', 'adj. 牙科的；牙齿的，牙的; n. 齿音', '/\'dentəl | \'dent(ə)l | \'dɛntl/', 'dental', 5);
INSERT INTO `words` VALUES (25011, 'Visit your dentist twice a year for a checkup.', 'n. 牙科医生', '/\'dentist | \'dentɪst | \'dɛntɪst/', 'dentist', 5);
INSERT INTO `words` VALUES (25012, 'The government denied the existence of poverty among 16- and 17-year-olds.', 'v. 否定，否认；拒绝给予；拒绝…的要求', '/di\'nai | dɪ\'naɪ | dɪ\'nai/', 'deny', 5);
INSERT INTO `words` VALUES (25013, 'Flights by Air Europe depart Gatwick on Tuesdays.', 'v. 离开,起程; adj. 过去的,逝世的', '/di\'pɑ:t | dɪ\'pɑːt | dɪ\'pɑrt/', 'depart', 5);
INSERT INTO `words` VALUES (25014, 'the personnel department', 'n. 部,局,处,科,部门;系,学部', '/di\'pɑ:tmənt | dɪ\'pɑːtm(ə)nt | dɪ\'pɑrtmənt/', 'department', 5);
INSERT INTO `words` VALUES (25015, '...the president\'s departure for Helsinki.', 'n. 离开,起程', '/di\'pɑ:tʃə | dɪ\'pɑːtʃə | dɪ\'pɑrtʃɚ/', 'departure', 5);
INSERT INTO `words` VALUES (25016, 'He depended on his writing for his income.', 'v. 依赖，依靠；取决于；相信，信赖', '/di\'pend | dɪ\'pend | dɪ\'pɛnd/', 'depend', 5);
INSERT INTO `words` VALUES (25017, '...the city\'s traditional dependence on tourism.', 'n. 依靠， 依赖； 信任', '/dɪ\'pendəns | dɪ\'pɛndəns/', 'dependence', 5);
INSERT INTO `words` VALUES (25018, 'Jan’s mother was dependent on her for physical care.', 'adj. 依靠的；从属的；取决于…的; n. 依赖他人者；受赡养者', '/di\'pendənt | dɪ\'pɛndənt/', 'dependent', 5);
INSERT INTO `words` VALUES (25019, 'a book depicting life in pre-revolutionary Russia', 'v. 描述；描画', '/di\'pikt | dɪ\'pɪkt/', 'depict', 5);
INSERT INTO `words` VALUES (25020, 'The UN deplored the invasion as a ‘violation of international law’.', 'vt. 悲悼， 哀叹；谴责', '/dɪ\'plɔː | dɪ\'plɔr/', 'deplore', 5);
INSERT INTO `words` VALUES (25021, 'The female deposits her eggs directly into the water.', 'v. 存放;使沉淀;付(保证金); n. 存款;沉积物', '/dɪ\'pɒzɪt | dɪ\'pɑzɪt/', 'deposit', 5);
INSERT INTO `words` VALUES (25022, 'The thought of taking the exam again depressed him.', 'v. 压抑；使沮丧；使萧条', '/di\'pres | dɪ\'pres | dɪ\'prɛs/', 'depress', 5);
INSERT INTO `words` VALUES (25023, 'She felt lonely and depressed .', 'adj. 沮丧的； 降低的', '/dɪ\'prest | dɪ\'prɛst/', 'depressed', 5);
INSERT INTO `words` VALUES (25024, 'They\'ve been deprived of the fuel necessary to heat their homes.', 'v. 使丧失，剥夺', '/di\'praiv | dɪ\'praɪv/', 'deprive', 5);
INSERT INTO `words` VALUES (25025, 'Astronomers may one day travel to the depths of space.', 'n. [海洋] 深度；深奥', '/depθ | dɛpθ/', 'depth', 5);
INSERT INTO `words` VALUES (25026, 'His brother was acting as his deputy in America.', 'n. 代理人，代表; adj. 副的；代理的', '/\'depjuti | \'depjʊtɪ | \'dɛpjuti/', 'deputy', 5);
INSERT INTO `words` VALUES (25027, 'Mr. Ying is one of those happy people who derive pleasure from helping others.', 'v. 源于；得自；获得; n. (Derive)人名；(法)德里夫', '/dɪ\'raɪv/', 'derive', 5);
INSERT INTO `words` VALUES (25028, 'Our plane started to descend.', 'v. 下降；下去；下来；遗传；屈尊', '/di\'send | dɪ\'send | dɪ\'sɛnd/', 'descend', 5);
INSERT INTO `words` VALUES (25029, 'If you must use descendant selectors, prefer child selectors, which at least only require evaluation of one additional node, not all the intermediate nodes up to an ancestor.', 'adj. 下降的；祖传的; n. 后裔；子孙', '/di\'sendənt | dɪ\'send(ə)nt | dɪ\'sɛndənt/', 'descendant', 5);
INSERT INTO `words` VALUES (25030, 'Passengers must fasten their seat belts prior to descent.', 'n. 下降；血统；袭击; vt. 除去…的气味；使…失去香味', '/di\'sent | dɪ\'sent | dɪ\'sɛnt/', 'descent', 5);
INSERT INTO `words` VALUES (25031, 'The police asked her to describe the man.', 'v. 描述,形容', '/di\'skraib | dɪ\'skraɪb/', 'describe', 5);
INSERT INTO `words` VALUES (25032, 'The booklet gives a brief description of each place.', 'n. 描写,形容;种类', '/di\'skripʃən | dɪ\'skrɪpʃ(ə)n | dɪ\'skrɪpʃən/', 'description', 5);
INSERT INTO `words` VALUES (25033, 'Helen was deserted by her husband.', 'v. 遗弃；放弃；逃跑; n. 沙漠；荒原；应得的赏罚; adj. 沙漠的；荒凉的；不毛的', '/\'dezət | (for v.) dɪ\'zɜːt; (for n.) \'dezət | (for v.) dɪˈzɝ​t; (for n.) \'dɛzɚt/', 'desert', 5);
INSERT INTO `words` VALUES (25034, 'What have I done to deserve this?', 'v. 应受，应得', '/di\'zə:v | dɪ\'zɜːv | dɪ\'zɝv/', 'deserve', 5);
INSERT INTO `words` VALUES (25035, 'The tower was designed by Gilbert Scott.', 'v. 设计;构思;绘制;图案;企图; n. 设计,图样', '/di\'zain | dɪ\'zaɪn/', 'design', 5);
INSERT INTO `words` VALUES (25036, '...a man interviewed in one of our studies whom we shall designate as E.', 'v. 指明,指出;任命,指派', '/\'deziɡneit, \'deziɡnit, -neit | \'dezɪgneɪt | \'dɛzɪɡnet/', 'designate', 5);
INSERT INTO `words` VALUES (25037, 'The ability to speak a foreign language is highly desirable .', 'adj. 令人满意的；值得要的; n. 合意的人或事物', '/di\'zaiərəbl | dɪ\'zaɪərəb(ə)l | dɪ\'zaɪərəbl/', 'desirable', 5);
INSERT INTO `words` VALUES (25038, 'female sexual desire', 'n. 欲望；要求，心愿；性欲; v. 想要；要求；希望得到…', '/di\'zaiə | dɪ\'zaɪə | dɪ\'zaɪɚ/', 'desire', 5);
INSERT INTO `words` VALUES (25039, 'a desolate landscape', 'adj. 荒凉的;孤独的; v. 使荒芜', '/\'desələt, \'desəleit | \'des(ə)lət | \'dɛsələt/', 'desolate', 5);
INSERT INTO `words` VALUES (25040, 'The noise from the neighbours used to drive him to despair .', 'n. 绝望；令人绝望的人或事; v. 绝望，丧失信心', '/di\'spεə | dɪ\'speə | dɪ\'spɛr/', 'despair', 5);
INSERT INTO `words` VALUES (25041, NULL, 'v. 派遣；发送；匆匆吃下; n. 派遣；发送（等于dispatch）', '/di\'spætʃ | dɪ\'spætʃ/', 'despatch', 5);
INSERT INTO `words` VALUES (25042, 'I had no money left and was desperate.', 'adj. 不顾一切的，铤而走险的；绝望的，危急的', '/\'despərət | \'desp(ə)rət | \'dɛspərət/', 'desperate', 5);
INSERT INTO `words` VALUES (25043, 'She despised her neighbours.', 'v. 轻视，鄙视', '/di\'spaiz | dɪ\'spaɪz/', 'despise', 5);
INSERT INTO `words` VALUES (25044, 'Despite all our efforts to save the school, the authorities decided to close it.', 'prep. 不管， 尽管 <', '/dɪ\'spaɪt/', 'despite', 5);
INSERT INTO `words` VALUES (25045, 'She had homemade ice cream for dessert.', 'n. 餐后甜点；甜点心', '/di\'zə:t | dɪ\'zɜːt | dɪ\'zɝt/', 'dessert', 5);
INSERT INTO `words` VALUES (25046, 'Ellis Island has become one of America\'s most popular tourist destinations.', 'n. 目的地，终点', '/,desti\'neiʃən | ,destɪ\'neɪʃ(ə)n | ,dɛstɪ\'neʃən/', 'destination', 5);
INSERT INTO `words` VALUES (25047, 'She always had a strong sense of destiny .', 'n. 命运，定数，天命', '/\'destini | \'destɪnɪ | \'dɛstəni/', 'destiny', 5);
INSERT INTO `words` VALUES (25048, 'companies that are polluting and destroying the environment', 'v. 破坏；消灭；毁坏', '/di\'strɔi | dɪ\'strɒɪ | dɪ\'strɔɪ/', 'destroy', 5);
INSERT INTO `words` VALUES (25049, '{\"COLLOINEXA\":[\"weapons of mass destruction\"]}', 'n. 破坏，毁灭；摧毁', '/di\'strʌkʃən | dɪ\'strʌkʃ(ə)n | dɪ\'strʌkʃən/', 'destruction', 5);
INSERT INTO `words` VALUES (25050, 'the destructive power of modern weapons', 'adj. 破坏的；毁灭性的；有害的，消极的', '/di\'strʌktiv | dɪ\'strʌktɪv/', 'destructive', 5);
INSERT INTO `words` VALUES (25051, 'Please detach and fill out the application form.', 'v. 分开, 分离, 分遣, 派遣(军队)', '/di\'tætʃ | dɪ\'tætʃ/', 'detach', 5);
INSERT INTO `words` VALUES (25052, 'This issue will be discussed in more detail in Chapter 5.', 'n. 细节， 详情; vt. 详述', '/\'diːteɪl | dɪˈtel/', 'detail', 5);
INSERT INTO `words` VALUES (25053, 'Two suspects have been detained by the police for questioning .', 'v. 耽搁;扣押,拘留', '/di\'tein | dɪ\'teɪn | dɪ\'ten/', 'detain', 5);
INSERT INTO `words` VALUES (25054, 'Many forms of cancer can be cured if detected early.', 'v. 察觉,发觉,侦察,探测', '/di\'tekt | dɪ\'tekt | dɪ\'tɛkt/', 'detect', 5);
INSERT INTO `words` VALUES (25055, 'She hired a detective to find out if her husband was having an affair.', 'n. 侦探', '/di\'tektiv | dɪ\'tektɪv | dɪ\'tɛktɪv/', 'detective', 5);
INSERT INTO `words` VALUES (25056, 'a smoke detector', 'n. 发现者,侦察器,探测器,检波器,检电器', '/dɪ\'tektə | dɪ\'tɛktɚ/', 'detector', 5);
INSERT INTO `words` VALUES (25057, 'Ethel’s health has deteriorated.', 'v. 恶化，变坏', '/di\'tiəriəreit | dɪ\'tɪərɪəreɪt | dɪ\'tɪrɪəret/', 'deteriorate', 5);
INSERT INTO `words` VALUES (25058, 'Investigators are still trying to determine the cause of the fire.', 'v. 决心,决定;确定,限定', '/dɪ\'tɜːmɪn | dɪ\'tɝmɪn/', 'determine', 5);
INSERT INTO `words` VALUES (25059, 'They stopped you as soon as you deviated from the script.', 'v. 脱离；越轨', '/\'di:vieit, \'di:viət | \'diːvɪeɪt | \'divɪet/', 'deviate', 5);
INSERT INTO `words` VALUES (25060, 'modern labour-saving devices', 'n. 装置,设备,仪表;方法,设计', '/di\'vais | dɪ\'vaɪs/', 'device', 5);
INSERT INTO `words` VALUES (25061, 'What on earth is wrong with the poor devil?', 'n. 魔鬼；撒旦；家伙；恶棍；淘气鬼；冒失鬼; v. 虐待，折磨；（用扯碎机）扯碎；（替作家，律师等）做助手；抹辣味料烤制或煎煮', '/\'dev(ə)l | \'dɛvl/', 'devil', 5);
INSERT INTO `words` VALUES (25062, 'She devised a method for quicker communications between offices.', 'v. 设计;发明;图谋;作出(计划);想出(办法)', '/di\'vaiz | dɪ\'vaɪz/', 'devise', 5);
INSERT INTO `words` VALUES (25063, 'The dew gathered on the leaves.', 'n. 珠，滴；露水；清新; vt. （露水等）弄湿; vi. 结露水', '/dju:, du: | \'djuː | du/', 'dew', 5);
INSERT INTO `words` VALUES (25064, 'You have diabetes, or liver or kidney disease.', 'n. 糖尿病； 多尿症', '/ˌdaɪə\'biːtiːz | ,daɪə\'bitiz/', 'diabetes', 5);
INSERT INTO `words` VALUES (25065, 'What tools do you need to help you diagnose the problem, and where do you get them?', 'v. 诊断(疾病)；判断(问题)', '/\'daiəɡnəuz, ,daiəɡ\'nəuz | \'daɪəgnəʊz; -\'nəʊz | ,daɪəɡ\'nos/', 'diagnose', 5);
INSERT INTO `words` VALUES (25066, 'On our project, we gradually decomposed each of the areas within the context diagram.', 'n. 图表；图解; v. 用图解法表示', '/\'daiəɡræm | \'daɪəgræm | \'daɪəɡræm/', 'diagram', 5);
INSERT INTO `words` VALUES (25067, 'The lighted dial of her watch said 1.20.', 'n. 转盘；刻度盘；钟面; v. 拨号', '/\'daiəl, dail | \'daɪəl/', 'dial', 5);
INSERT INTO `words` VALUES (25068, 'the local dialect', 'n. 方言', '/\'daiəlekt | \'daɪəlekt | \'daɪə\'lɛkt/', 'dialect', 5);
INSERT INTO `words` VALUES (25069, 'In this dialog, you can only open an artifact in the editor.', 'n. (ue)对话,对白', '/\'daiəlɔɡ | \'daɪəlɒɡ | \'daɪə,lɑg/', 'dialog', 5);
INSERT INTO `words` VALUES (25070, '...a tube less than a fifth of the diameter of a human hair.', 'n. 直径', '/dai\'æmitə | daɪ\'æmɪtə | daɪ\'æmɪtɚ/', 'diameter', 5);
INSERT INTO `words` VALUES (25071, 'Inge kept a diary (= wrote in a diary ) during the war years.', 'n. 日志，日记；日记簿', '/\'daiəri | \'daɪərɪ | \'daɪəri/', 'diary', 5);
INSERT INTO `words` VALUES (25072, 'Federal funds have to be used as dictated by Washington.', 'v. 命令；口述；使听写; n. 命令；指示', '/dik\'teit, \'dikteit | dɪk\'teɪt | \'dɪktet/', 'dictate', 5);
INSERT INTO `words` VALUES (25073, 'There were no secretaries available to take dictation (= write down what someone is saying ) .', 'n. 听写,口述;命令', '/dik\'teiʃən | dɪk\'teɪʃ(ə)n | dɪk\'teʃən/', 'dictation', 5);
INSERT INTO `words` VALUES (25074, 'a German-English dictionary', 'n. 词典,字典', '/\'dikʃənəri | \'dɪkʃ(ə)n(ə)rɪ | \'dɪkʃə\'nɛri/', 'dictionary', 5);
INSERT INTO `words` VALUES (25075, 'He died in 1985 at the age of 76.', 'v. 死亡；凋零；熄灭; n. 冲模，钢模；骰子', '/dai | daɪ/', 'die', 5);
INSERT INTO `words` VALUES (25076, 'Lyn always seems to be on a diet.', 'n. 饮食；食物；规定饮食; v. 节食', '/\'daiət | \'daɪət/', 'diet', 5);
INSERT INTO `words` VALUES (25077, 'The story he told police differed from the one he told his mother.', 'v. 使…相异；使…不同; n. (Differ)人名；(法)迪费', '/\'difə | \'dɪfə | \'dɪfɚ/', 'differ', 5);
INSERT INTO `words` VALUES (25078, '(= there’s a very big difference ) between us.', 'n. 差异；不同；争执', '/\'dɪf(ə)r(ə)ns | \'dɪfrəns/', 'difference', 5);
INSERT INTO `words` VALUES (25079, 'What differentiates these two periods of history?', 'v. 区分，区别', '/,difə\'renʃieit | ,dɪfə\'renʃɪeɪt | ,dɪfə\'rɛnʃɪet/', 'differentiate', 5);
INSERT INTO `words` VALUES (25080, 'a difficult question', 'adj. 困难的,艰难的', '/\'difikəlt | \'dɪfɪk(ə)lt | \'dɪfɪkəlt/', 'difficult', 5);
INSERT INTO `words` VALUES (25081, 'If you have any difficulties, give me a call.', 'n. 困难,困境,难题', '/\'difikəlti | \'dɪfɪk(ə)ltɪ | \'dɪfɪkəlti/', 'difficulty', 5);
INSERT INTO `words` VALUES (25082, 'Their ideas diffused quickly across Europe.', 'v. 扩散;传播; adj. (文章等)冗长的,漫无边际的', '/di\'fju:s | dɪ\'fjuːz | dɪ\'fjus/', 'diffuse', 5);
INSERT INTO `words` VALUES (25083, 'freshly dug carrots', 'v. 挖，掘；探究; n. 戳，刺；挖苦', '/diɡ | dɪg | dɪɡ/', 'dig', 5);
INSERT INTO `words` VALUES (25084, 'Most babies can digest a wide range of food easily.', 'v. 消化；吸收；融会贯通; n. 文摘；摘要', '/di\'dʒest, dai-, \'daidʒest | daɪ\'dʒest; dɪ- | daɪ\'dʒɛst/', 'digest', 5);
INSERT INTO `words` VALUES (25085, 'digital TV', 'adj. 数字的；手指的; n. 数字；键', '/\'didʒitəl | \'dɪdʒɪt(ə)l | \'dɪdʒɪtl/', 'digital', 5);
INSERT INTO `words` VALUES (25086, 'an appearance of quiet dignity', 'n. (举止,态度等的)庄严,端庄;尊贵,高贵', '/\'diɡnəti | \'dɪgnɪtɪ | \'dɪɡnəti/', 'dignity', 5);
INSERT INTO `words` VALUES (25087, 'a moral dilemma', 'n. 困境；进退两难；', '/di\'lemə, ,dai- | dɪ\'lemə; daɪ- | dɪˈlemə/', 'dilemma', 5);
INSERT INTO `words` VALUES (25088, 'a diligent student', 'adj. 勤奋的,用功的', '/\'dilidʒənt | \'dɪlɪdʒ(ə)nt | \'dɪlɪdʒənt/', 'diligent', 5);
INSERT INTO `words` VALUES (25089, 'dilute hydrochloric acid', 'adj. 稀释的；淡的; v. 稀释；冲淡；削弱', '/dai\'lju:t, di- | daɪ\'l(j)uːt; dɪ- | daɪ\'l(j)ut/', 'dilute', 5);
INSERT INTO `words` VALUES (25090, 'in the dim light of the early dawn', 'adj. 暗淡的，昏暗的；模糊的，看不清的；悲观的，怀疑的; v. 使暗淡，使失去光泽；使变模糊; n. 笨蛋，傻子', '/dim | dɪm/', 'dim', 5);
INSERT INTO `words` VALUES (25091, 'You can have a spiritual dimension to your life without being religious.', 'n. 方面;[数] 维；尺寸；次元；容积 vt标出尺寸; adj. 规格的', '/dɪ\'menʃ(ə)n; daɪ- | dɪ\'mɛnʃ(ə)n; daɪ-/', 'dimension', 5);
INSERT INTO `words` VALUES (25092, 'The party’s share of the electorate has diminished steadily.', 'v. 使减少；使变小', '/di\'miniʃ | dɪ\'mɪnɪʃ/', 'diminish', 5);
INSERT INTO `words` VALUES (25093, 'He was dining with friends at the Ritz.', 'v. 进餐，用餐; n. (Dine)人名；(意、葡)迪内；(英)戴恩；(法)迪纳', '/dain | daɪn/', 'dine', 5);
INSERT INTO `words` VALUES (25094, 'What time do you usually have dinner?', 'n. 晚餐，晚宴；宴会；正餐', '/\'dinə | \'dɪnə | \'dɪnɚ/', 'dinner', 5);
INSERT INTO `words` VALUES (25095, 'lengthy speeches by some of the party’s dinosaurs', 'n. 恐龙；过时的人或事物', '/\'daɪnəsɔː | ˈdaɪnəˌsɔr/', 'dinosaur', 5);
INSERT INTO `words` VALUES (25096, 'She is your indispensable oxygen, carbon dioxide is not essential you me.', 'n. 二氧化物', '/daɪ\'ɒksaɪd | daɪ\'ɑksaɪd/', 'dioxide', 5);
INSERT INTO `words` VALUES (25097, 'Dip each apple in the syrup until thickly coated.', 'v. 浸，泡，蘸；舀取；把伸入; n. 下沉，下降；倾斜；浸渍，蘸湿', '/dip | dɪp/', 'dip', 5);
INSERT INTO `words` VALUES (25098, 'I’m hoping to get my teaching diploma this year.', 'n. 毕业证书，学位证书；公文，文书；奖状; vt. 发给…毕业文凭', '/di\'pləumə | dɪ\'pləʊmə | dɪ\'plomə/', 'diploma', 5);
INSERT INTO `words` VALUES (25099, 'Diplomatic efforts to end the fighting began on October 25.', 'adj. 外交的；外交上的；老练的', '/,diplə\'mætik | dɪplə\'mætɪk | ,dɪplə\'mætɪk/', 'diplomatic', 5);
INSERT INTO `words` VALUES (25100, 'All genuine knowledge originates in direct experience.', 'a&ad. 径直的(地); v. 管理,指导;(at,to)指向', '/di\'rekt, dai- | dəˈrekt; daɪˈrekt | dɪˈrɛkt; daɪˈrɛkt/', 'direct', 5);
INSERT INTO `words` VALUES (25101, NULL, 'n. 方向,方位;指令,说明', '/di\'rekʃən, dai- | dɪˈrɛkʃən; daɪ- | dəˈrɛkʃən; (also) daɪˈrɛkʃən/', 'direction', 5);
INSERT INTO `words` VALUES (25102, 'The new property tax law won’t directly affect us.', 'adv. 直接地,径直地;马上,立即', '/英 [dəˈrektli] 美 [dɪˈrɛktli, daɪ-] | dɪ\'rektlɪ; daɪ- | dəˈrektli/', 'directly', 5);
INSERT INTO `words` VALUES (25103, '\"Cut!\" the director yelled. \"That was perfect.\"', 'n. 指导者,主任,导演', '/di\'rektə | dɪ\'rektə; daɪ- | dɪˈrɛktɚ; daɪˈrɛktɚ/', 'director', 5);
INSERT INTO `words` VALUES (25104, 'I couldn’t find your number in the telephone directory.', 'n. 人名地址录,(电话)号码簿', '/di\'rektəri, dai- | dɪ\'rekt(ə)rɪ; daɪ- | dəˈrɛktəri; (also) daɪˈrɛktəri/', 'directory', 5);
INSERT INTO `words` VALUES (25105, 'You should have seen the dirt on that car!', 'n. 污垢，泥土；灰尘，尘土；下流话', '/də:t | dɜːt | dɝt/', 'dirt', 5);
INSERT INTO `words` VALUES (25106, 'a stack of dirty dishes in the sink', 'adj. 下流的，卑鄙的；肮脏的；恶劣的；暗淡的; v. 弄脏', '/\'də:ti | \'dɜːtɪ | ˈdɝ​tɪ/', 'dirty', 5);
INSERT INTO `words` VALUES (25107, 'Carter was permanently disabled in the war.', 'v. 使失去能力；使残废；使无资格', '/dis\'eib | dɪs\'eɪb(ə)l | dɪs\'ebl/', 'disable', 5);
INSERT INTO `words` VALUES (25108, 'At this point the path seemed to disappear altogether (= disappear completely ) .', 'v. 消失；失踪；不复存在', '/,disə\'piə | dɪsə\'pɪə | \'dɪsə\'pɪr/', 'disappear', 5);
INSERT INTO `words` VALUES (25109, 'One hundred and twenty people died in China’s worst air disaster .', 'n. 灾难，灾祸；不幸', '/,di\'zɑ:stə | dɪ\'zɑːstə | dɪ\'zæstɚ/', 'disaster', 5);
INSERT INTO `words` VALUES (25110, 'a disastrous first marriage', 'adj. 灾难性的；损失惨重的；悲伤的', '/di\'zɑ:strəs | dɪ\'zɑːstrəs | dɪ\'zæstrəs/', 'disastrous', 5);
INSERT INTO `words` VALUES (25111, 'three keys attached to a metal disc', 'n. 圆盘，[电子] 唱片（等于disk）; vt. 灌唱片', '/disk | dɪsk/', 'disc', 5);
INSERT INTO `words` VALUES (25112, 'Read the manufacturer\'s guidelines before discarding the box.', 'v. 抛弃；放弃；丢弃; n. 抛弃；被丢弃的东西或人', '/dis\'kɑ:d, \'diskɑ:d | dɪ\'skɑːd | dɪsˈkɑːrd/', 'discard', 5);
INSERT INTO `words` VALUES (25113, 'You need a long series of data to be able to discern such a trend.', 'v. 识别；领悟，认识', '/di\'sə:n, -\'zə:n | dɪ\'sɜːn | dɪ\'sɝn/', 'discern', 5);
INSERT INTO `words` VALUES (25114, 'Hospitals now tend to discharge patients earlier than in the past.', 'v. 解雇；卸下；放出；免除; n. 排放；卸货；解雇', '/dis\'tʃɑ:dʒ, \'distʃɑ:dʒ, dis\'tʃ- | dɪs\'tʃɑːdʒ | dɪs\'tʃɑrdʒ/', 'discharge', 5);
INSERT INTO `words` VALUES (25115, 'Martial arts teach respect, discipline, and cooperation.', 'n. 纪律,学科', '/\'disiplin | \'dɪsɪplɪn | \'dɪsəplɪn/', 'discipline', 5);
INSERT INTO `words` VALUES (25116, 'Some companies have already voluntarily disclosed similar information .', 'v. 揭示,泄露', '/dis\'kləuz | dɪs\'kləʊz | dɪs\'kloz/', 'disclose', 5);
INSERT INTO `words` VALUES (25117, 'They are often available at a discount.', 'n. 折扣；贴现(率); v. 打折扣;不重视', '/[\'diskaunt, dis\'k-] | \'dɪskaʊnt | dɪs\'kaʊnt/', 'discount', 5);
INSERT INTO `words` VALUES (25118, 'Aspirin may discourage tumour growth in some types of cancer.', 'v. 阻止；使气馁', '/dis\'kʌridʒ | dɪs\'kʌrɪdʒ | dɪs\'kɝɪdʒ/', 'discourage', 5);
INSERT INTO `words` VALUES (25119, 'Candidates should engage in serious political discourse.', 'n. 论文;演说;谈话;话语; v. 讲述,著述', '/\'diskɔ:s, dis\'kɔ:s | \'dɪskɔːs; -\'kɔːs | \'dɪskɔrs/', 'discourse', 5);
INSERT INTO `words` VALUES (25120, 'The body was discovered in a field.', 'v. 发现,显示', '/dis\'kʌvə | dɪ\'skʌvə | dɪ\'skʌvɚ/', 'discover', 5);
INSERT INTO `words` VALUES (25121, 'I felt I\'d made an incredible discovery.', 'n. 发现;被发现的事物', '/dis\'kʌvəri | dɪ\'skʌv(ə)rɪ | dɪ\'skʌvəri/', 'discovery', 5);
INSERT INTO `words` VALUES (25122, 'He assured her that he would be discreet.', 'adj. (言行)谨慎的；慎重的；有判断力的', '/dis\'kri:t | dɪ\'skriːt | dɪ\'skrit/', 'discreet', 5);
INSERT INTO `words` VALUES (25123, '...the discrepancy between press and radio reports.', 'n. 相差;差异;矛盾;', '/dis\'krepənsi | dɪs\'krep(ə)nsɪ | dɪs\'krɛpənsi/', 'discrepancy', 5);
INSERT INTO `words` VALUES (25124, 'He is incapable of discriminating between a good idea and a terrible one.', 'v. 区别,辨别;有差别地对待,歧视', '/dɪ\'skrɪmɪneɪt | dɪ\'skrɪmɪnet/', 'discriminate', 5);
INSERT INTO `words` VALUES (25125, 'His father died of heart disease.', 'n. 病，[医] 疾病；弊病; vt. 传染；使…有病', '/di\'zi:z | dɪ\'ziːz | dɪ\'ziz/', 'disease', 5);
INSERT INTO `words` VALUES (25126, 'Smith faced total public disgrace after the incident.', 'n. 失宠,耻辱; v. 使失宠;玷辱,使蒙羞', '/dis\'ɡreis | dɪs\'greɪs | dɪs\'ɡres/', 'disgrace', 5);
INSERT INTO `words` VALUES (25127, 'He escaped across the border disguised as a priest.', 'v. 掩饰；假装；隐瞒; n. 伪装；假装；用作伪装的东西', '/dis\'ɡaiz | dɪs\'gaɪz | dɪs\'ɡaɪz/', 'disguise', 5);
INSERT INTO `words` VALUES (25128, 'He reached into the bin with a look of disgust on his face.', 'n. 厌恶，嫌恶; v. 使厌恶；使作呕', '/dis\'ɡʌst | dɪs\'gʌst | dɪs\'ɡʌst/', 'disgust', 5);
INSERT INTO `words` VALUES (25129, 'a serving dish', 'n. 盘；餐具；一盘食物；外貌有吸引力的人; v. 盛于碟盘中；分发；使某人的希望破灭；说（某人）的闲话', '/dɪʃ/', 'dish', 5);
INSERT INTO `words` VALUES (25130, 'The food processor has thin, medium, and thick slicing discs.', 'n. 唱片； 圆盘， 盘状物', '/dɪsk/', 'disk', 5);
INSERT INTO `words` VALUES (25131, 'Why do you dislike her so much?', 'v. 不喜欢，厌恶; n. 嫌恶，反感，不喜爱', '/dis\'laik | dɪs\'laɪk/', 'dislike', 5);
INSERT INTO `words` VALUES (25132, 'The thought of leaving filled him with dismay .', 'n. 沮丧，灰心；惊慌; v. 使沮丧；使惊慌', '/dis\'mei | dɪs\'meɪ | dɪs\'me/', 'dismay', 5);
INSERT INTO `words` VALUES (25133, 'The government has dismissed criticisms that the country’s health policy is a mess.', 'v. 解散；解雇；开除；让离开；不予理会、不予考虑', '/dɪs\'mɪs/', 'dismiss', 5);
INSERT INTO `words` VALUES (25134, 'severe eating disorders such as bulimia and anorexia', 'n. 混乱,杂乱;骚乱;失调,疾病', '/dis\'ɔ:də | dɪs\'ɔːdə | dɪs\'ɔrdɚ/', 'disorder', 5);
INSERT INTO `words` VALUES (25135, 'Goods are normally dispatched within 24 hours.', 'vt. 派遣， 调遣； 发送; n. 急件， 快信；新闻报道', '/dɪ\'spætʃ/', 'dispatch', 5);
INSERT INTO `words` VALUES (25136, 'Police used tear gas to disperse the crowd.', 'v. (使)分散;(使)散开;疏散', '/dis\'pə:s | dɪ\'spɜːs | dɪ\'spɝs/', 'disperse', 5);
INSERT INTO `words` VALUES (25137, 'Coal has been displaced by natural gas as a major source of energy.', 'v. 取代；置换；转移；把…免职；排水', '/dis\'pleis | dɪs\'pleɪs | dɪs\'ples/', 'displace', 5);
INSERT INTO `words` VALUES (25138, '...the displacement of traditional agriculture by industrial crops.', 'n. 移置， 转移； 取代', '/dɪs\'pleɪsmənt | dɪs\'plesmənt/', 'displacement', 5);
INSERT INTO `words` VALUES (25139, 'This time the display flashed a red warning signal.', 'n. 显示；炫耀; v. 显示；表现；陈列; adj. 展览的；陈列用的', '/,dis\'plei | dɪ\'spleɪ | dɪ\'sple/', 'display', 5);
INSERT INTO `words` VALUES (25140, 'bomb disposal experts', 'n. 处理,处置;布置,安排', '/dis\'pəuzəl | dɪ\'spəʊz(ə)l | dɪ\'spozl/', 'disposal', 5);
INSERT INTO `words` VALUES (25141, 'Chinese vases are disposed around the gallery.', 'v. (of)处理,处置;(for)布置,安排', '/dis\'pəuz | dɪ\'spəʊz | dɪ\'spoz/', 'dispose', 5);
INSERT INTO `words` VALUES (25142, 'The rides are unsuitable for people of a nervous disposition.', 'n. 排列,部署;性格倾向;倾向,意向', '/,dispə\'ziʃən | dɪspə\'zɪʃ(ə)n | \'dɪspə\'zɪʃən/', 'disposition', 5);
INSERT INTO `words` VALUES (25143, 'What happened next is hotly disputed .', 'v. 辩论；怀疑；阻止；抗拒; n. 辩论；争吵', '/dis\'pju:t, \'dis- | dɪ\'spjuːt; \'dɪspjuːt | \'dɪs\'pjʊt/', 'dispute', 5);
INSERT INTO `words` VALUES (25144, 'He ordered the jury to disregard the witness’s last statement.', 'v. 忽视；不理；漠视；不顾; n. 忽视；不尊重', '/disri\'ɡɑ:d | dɪsrɪ\'gɑːd | ,dɪsrɪ\'ɡɑrd/', 'disregard', 5);
INSERT INTO `words` VALUES (25145, 'Traffic was disrupted by a hoax bomb.', 'v. 破坏；使瓦解；使分裂；使中断；使陷于混乱; adj. 分裂的，中断的；分散的', '/dis\'rʌpt | dɪs\'rʌpt/', 'disrupt', 5);
INSERT INTO `words` VALUES (25146, 'As he thought it over, his anger gradually dissipated.', 'v. 浪费；使…消散', '/\'disipeit | \'dɪsɪpeɪt | \'dɪsɪpet/', 'dissipate', 5);
INSERT INTO `words` VALUES (25147, 'Stir until the sugar dissolves.', 'v. (使)溶解,(使)融化;解散,取消', '/di\'zɔlv | dɪ\'zɒlv | dɪ\'zɑlv/', 'dissolve', 5);
INSERT INTO `words` VALUES (25148, 'the sound of distant gunfire', 'adj. 遥远的；冷漠的；远隔的；不友好的，冷淡的', '/\'dɪst(ə)nt | \'dɪstənt/', 'distant', 5);
INSERT INTO `words` VALUES (25149, 'distilled water', 'v. 提取；蒸馏；使滴下', '/dis\'til | dɪs\'tɪl/', 'distill', 5);
INSERT INTO `words` VALUES (25150, 'The outline of the ship became more distinct.', 'adj. 明显的；独特的；清楚的；有区别的', '/dis\'tiŋkt | dɪ\'stɪŋ(k)t | dɪ\'stɪŋkt/', 'distinct', 5);
INSERT INTO `words` VALUES (25151, 'There are obvious distinctions between the two wine-making areas.', 'n. 区别；差别；特性；荣誉、勋章', '/dis\'tiŋkʃən | dɪ\'stɪŋ(k)ʃ(ə)n | dɪ\'stɪŋkʃən/', 'distinction', 5);
INSERT INTO `words` VALUES (25152, 'The light was too dim for me to distinguish anything clearly.', 'v. 区分；辨别；使杰出，使表现突出', '/dis\'tiŋɡwiʃ | dɪ\'stɪŋgwɪʃ | dɪ\'stɪŋɡwɪʃ/', 'distinguish', 5);
INSERT INTO `words` VALUES (25153, 'His account was badly distorted by the press.', 'v. 扭曲；使失真；曲解', '/dis\'tɔ:t | dɪ\'stɔːt | dɪ\'stɔrt/', 'distort', 5);
INSERT INTO `words` VALUES (25154, 'Try not to distract the other students.', 'v. 分散;使分心;打扰;使心情烦乱', '/dis\'trækt | dɪ\'strækt/', 'distract', 5);
INSERT INTO `words` VALUES (25155, 'acute financial distress', 'n. 危难，不幸；贫困；悲痛; v. 使悲痛；使贫困', '/di\'stres | dɪ\'stres | dɪ\'strɛs/', 'distress', 5);
INSERT INTO `words` VALUES (25156, 'a man distributing leaflets to passers-by', 'v. 分配；散布；分开；把…分类', '/di\'stribju:t, \'dis- | dɪ\'strɪbjuːt; \'dɪstrɪbjuːt | dɪ\'strɪbjut/', 'distribute', 5);
INSERT INTO `words` VALUES (25157, 'a postal district', 'n. 区域；地方；行政区', '/\'distrikt | \'dɪstrɪkt/', 'district', 5);
INSERT INTO `words` VALUES (25158, 'My hormone balance is disturbed by my pregnancy.', 'vt. 扰乱， 妨碍；使不安； 使烦恼', '/dɪ\'stɜːb | dɪ\'stɝb/', 'disturb', 5);
INSERT INTO `words` VALUES (25159, 'There were disturbances in the crowd as fans left the stadium.', 'n. 干扰；骚乱；忧虑', '/di\'stə:bəns | dɪ\'stɜːb(ə)ns | dɪ\'stɝbəns/', 'disturbance', 5);
INSERT INTO `words` VALUES (25160, 'The government has ditched plans to privatise the prison.', 'v. 在…上掘沟；把…开入沟里；丢弃; n. 沟渠；壕沟', '/ditʃ | dɪtʃ/', 'ditch', 5);
INSERT INTO `words` VALUES (25161, 'Diving off the cliffs is dangerous.', 'v. 潜水；跳水；俯冲；急剧下降; n. 潜水；跳水；俯冲；扑', '/\'di:vei, daiv | daɪv/', 'dive', 5);
INSERT INTO `words` VALUES (25162, 'subjects as diverse as pop music and archaeology', 'adj. 多种多样的,(from)不同的', '/dai\'və:s, di- | daɪ\'vɜːs; \'daɪvɜːs | daɪ\'vɝs/', 'diverse', 5);
INSERT INTO `words` VALUES (25163, '...the illegal diversion of profits from secret arms sales.', 'n. 转向,转移;牵制;解闷;娱乐', '/dai\'və:ʃən, di- | daɪ\'vɜːʃ(ə)n; dɪ- | dəˈvɝʒən; dəˈvɝʃən; daɪˈvɝʒən; daɪˈvɝʃən/', 'diversion', 5);
INSERT INTO `words` VALUES (25164, 'The high street is closed and traffic is being diverted .', 'v. 使转向，使改道；转移(注意力)；使娱乐', '/dai\'və:t, di- | daɪ\'vɜːt; dɪ- | dɪˈvɚt/', 'divert', 5);
INSERT INTO `words` VALUES (25165, 'The physical benefits of exercise can be divided into three factors.', 'v. 分,划分,分开;分配;(by)除', '/di\'vaid | dɪ\'vaɪd/', 'divide', 5);
INSERT INTO `words` VALUES (25166, 'Good eating habits will pay dividends later on in life.', 'n. 红利，股息；回报，效益；被除数', '/\'dɪvɪdend | \'dɪvɪdɛnd/', 'dividend', 5);
INSERT INTO `words` VALUES (25167, 'divine power', 'adj. 神圣的；非凡的；天赐的；极好的; v. 占卜；预言；用占卜勘探; n. 牧师；神学家', '/di\'vain | dɪ\'vaɪn/', 'divine', 5);
INSERT INTO `words` VALUES (25168, 'the traditional division of labour (= the way that particular tasks are shared ) between husband and wife', 'n. 分,分割;部门,科,处;除法;分界线', '/dɪ\'vɪʒ(ə)n | də\'vɪʒən/', 'division', 5);
INSERT INTO `words` VALUES (25169, 'David’s parents divorced when he was six.', 'vt. 离婚； 分离; n. 离婚； 分离', '/dɪ\'vɔːs | dɪ\'vɔrs/', 'divorce', 5);
INSERT INTO `words` VALUES (25170, 'The heat and the champagne made him feel dizzy .', 'adj. 晕眩的；使人头晕的；昏乱的；心不在焉的；愚蠢的; v. 使头晕眼花；使混乱；使茫然; n. (Dizzy)人名；(英)迪齐', '/\'dizi | \'dɪzɪ | \'dɪzi/', 'dizzy', 5);
INSERT INTO `words` VALUES (25171, 'A crowd was waiting at the dock to greet them.', 'n. 码头；船坞；被告席；尾巴的骨肉部分; v. 使靠码头；剪短', '/dɔk | dɒk | dɑk/', 'dock', 5);
INSERT INTO `words` VALUES (25172, 'She was treated by her local doctor.', 'n. 医生;博士; v. 授以博士学位;诊断;修改', '/\'dɒktə | \'dɑktɚ/', 'doctor', 5);
INSERT INTO `words` VALUES (25173, 'Professor Lanphier obtained his doctorate in social psychology from the University of Michigan.', 'n. 博士学位;博士头衔', '/\'dɔktərit | \'dɒkt(ə)rət | \'dɑktərət/', 'doctorate', 5);
INSERT INTO `words` VALUES (25174, 'traditional doctrines of divine power', 'n. 教条， 主义， 学说', '/\'dɒktrɪn | \'dɑktrɪn/', 'doctrine', 5);
INSERT INTO `words` VALUES (25175, 'She produces legal documents for a downtown Seattle law firm.', 'n. 公文,文献', '/\'dɔkjumənt, \'dɔkjument | \'dɒkjʊm(ə)nt | dɑkjəmənt/', 'document', 5);
INSERT INTO `words` VALUES (25176, '...a TV documentary on homelessness.', 'adj. 文献的; n. 记录片', '/,dɔkju\'mentəri | dɒkjʊ\'ment(ə)rɪ | \'dɑkjə\'mɛntri/', 'documentary', 5);
INSERT INTO `words` VALUES (25177, 'Looking after the house was viewed as a woman’s domain.', 'n. (活动,思想等)领域,范围;领地', '/dəu\'mein | də(ʊ)\'meɪn | do\'men/', 'domain', 5);
INSERT INTO `words` VALUES (25178, '...the dome of the Capitol.', 'n. 圆屋顶', '/dəum | dəʊm | dom/', 'dome', 5);
INSERT INTO `words` VALUES (25179, 'Unfortunately his domestic life wasn’t very happy.', 'adj. 家里的;本国的;驯养的', '/dəu\'mestik | də\'mestɪk | də\'mɛstɪk/', 'domestic', 5);
INSERT INTO `words` VALUES (25180, 'The dominant male gorilla is the largest in the group.', 'adj. 支配的,统治的,占优势的', '/\'dɔminənt | \'dɒmɪnənt | \'dɑmɪnənt/', 'dominant', 5);
INSERT INTO `words` VALUES (25181, 'The industry is dominated by five multinational companies.', 'v. 支配,统治,控制;占优势', '/\'dɔmineit | \'dɒmɪneɪt | \'dɑmɪnet/', 'dominate', 5);
INSERT INTO `words` VALUES (25182, 'people who volunteer to donate blood', 'v. 捐赠；捐献; n. 捐赠；捐献', '/dəʊ\'neɪt | də(ʊ)\'neɪt | \'donet/', 'donate', 5);
INSERT INTO `words` VALUES (25183, 'A sense of impending doom (= coming very soon ) gripped her.', 'n. 厄运,劫数; v. 注定,命定', '/du:m | duːm | dʊm/', 'doom', 5);
INSERT INTO `words` VALUES (25184, 'Could you open the door for me?', 'n. 门；家，户；门口；通道', '/dɔ: | dɔː | dɔr/', 'door', 5);
INSERT INTO `words` VALUES (25185, 'Hannah looked up to see David and another man standing in the doorway.', 'n. 门口；途径', '/\'dɔ:wei | \'dɔːweɪ | \'dɔr\'we/', 'doorway', 5);
INSERT INTO `words` VALUES (25186, 'But I had no food in my dorm, so I had to go to canteen.', 'n. (itory)［美］［口］宿舍', '/dɔ:m | dɔːm | dɔrm/', 'dorm', 5);
INSERT INTO `words` VALUES (25187, 'She lived in a college dormitory.', 'n. 宿舍', '/\'dɔːmətri | \'dɔrmətɔri/', 'dormitory', 5);
INSERT INTO `words` VALUES (25188, 'I quite like Jamie in small doses (= in limited amounts but not a lot or often ) .', 'n. 剂量；一剂，一服; v. 服药', '/dəus | dəʊs | dos/', 'dose', 5);
INSERT INTO `words` VALUES (25189, 'a pattern of dots', 'n. 点， 圆点; vt. 在…上打点', '/dɒt | dɑt/', 'dot', 5);
INSERT INTO `words` VALUES (25190, 'There was still one little nagging doubt at the back of his mind.', 'n. 怀疑；疑问；疑惑; v. 怀疑；不信；恐怕；拿不准', '/daut | daʊt/', 'doubt', 5);
INSERT INTO `words` VALUES (25191, 'As part of the study, due to be unveiled later this month, participants were given the option of being a ‘dove’ and cooperating with others for shared benefit, or taking on the role of a ‘hawk’.', 'n. 鸽子；鸽派人士; v. 潜水（dive的过去式）', '/dʌv | dʌv; dov/', 'dove', 5);
INSERT INTO `words` VALUES (25192, 'By day he worked downtown for American Standard.', 'adv. 往闹市区；在市区; adj. 市中心的; n. 市中心区；三分线以外', '/\'daun\'taun | \'daʊntaʊn | \'daʊn\'taʊn/', 'downtown', 5);
INSERT INTO `words` VALUES (25193, 'a gentle downward slope', 'adj. 向下的，下降的; adv. 向下', '/\'daunwəd | \'daʊnwəd | \'daʊnwɚd/', 'downward', 5);
INSERT INTO `words` VALUES (25194, 'Grandad was dozing in his chair.', 'v. 打瞌睡；假寐; n. 瞌睡', '/dəuz | dəʊz | doz/', 'doze', 5);
INSERT INTO `words` VALUES (25195, 'a dozen eggs', 'n. 十二个，一打; adj. 一打的', '/\'dʌzən | \'dʌz(ə)n | \'dʌzn/', 'dozen', 5);
INSERT INTO `words` VALUES (25196, 'the rough draft of his new novel', 'n. 汇票；草稿；选派；（尤指房间、烟囱、炉子等供暖系统中的）（小股）气流; v. 起草；制定；征募; adj. 初步画出或（写出）的；（设计、草图、提纲或版本）正在起草中的，草拟的；以草稿形式的；草图的', '/drɑːft | dræft/', 'draft', 5);
INSERT INTO `words` VALUES (25197, 'He grabbed her arm and dragged her into the room.', 'v. 拖累；拖拉；缓慢而吃力地行进; n. 拖；拖累', '/dræɡ | dræg/', 'drag', 5);
INSERT INTO `words` VALUES (25198, NULL, 'n. 龙；凶暴的人，凶恶的人；严厉而有警觉性的女人', '/\'dræɡən | \'dræg(ə)n/', 'dragon', 5);
INSERT INTO `words` VALUES (25199, 'The swimming pool is drained and cleaned every winter.', 'v. 排水；流干; n. 排水；下水道，排水管；消耗', '/drein | dreɪn | dren/', 'drain', 5);
INSERT INTO `words` VALUES (25200, 'the great traditions of ancient Greek drama', 'n. 戏剧； 剧本；戏剧性事件或场面', '/\'drɑːmə | \'drɑmə/', 'drama', 5);
INSERT INTO `words` VALUES (25201, 'A superb goal by Owen earned United a dramatic victory yesterday.', 'adj. 戏剧的；急剧的；引人注目的；激动人心的', '/drə\'mætɪk/', 'dramatic', 5);
INSERT INTO `words` VALUES (25202, 'drastic cuts in government spending', 'adj. 激烈的；猛烈的; n. 烈性泻药', '/\'dræstik | \'dræstɪk; \'drɑː- | \'dræstɪk/', 'drastic', 5);
INSERT INTO `words` VALUES (25203, 'Katie had drawn a cottage with a little stream running next to it.', 'v. 画；拉；吸引; n. 平局；抽签', '/drɔ: | drɔː | drɔ/', 'draw', 5);
INSERT INTO `words` VALUES (25204, 'It’s a great city – the only drawback is the weather.', 'n. 缺点，不利条件；退税', '/\'drɔ:bæk | \'drɔːbæk | \'drɔbæk/', 'drawback', 5);
INSERT INTO `words` VALUES (25205, 'She took a file from her desk drawer .', 'n. 抽屉；开票人；出票人；起草者；酒馆侍', '/drɔ:(r) | drɔr/', 'drawer', 5);
INSERT INTO `words` VALUES (25206, 'I’ve never been very good at drawing.', 'n. 图画；牵引；素描术; v. 绘画；吸引（draw的ing形式）；拖曳', '/\'drɔ:iŋ | \'drɔː(r)ɪŋ | \'drɔɪŋ/', 'drawing', 5);
INSERT INTO `words` VALUES (25207, 'The prospect of flying filled me with dread .', 'n. 恐惧；可怕的人（或物）; v. 惧怕；担心; adj. 可怕的', '/dred | drɛd/', 'dread', 5);
INSERT INTO `words` VALUES (25208, 'Can you wait a minute? I’m just getting dressed .', 'v. 给…穿衣; n. 连衣裙；女装', '/dres | drɛs/', 'dress', 5);
INSERT INTO `words` VALUES (25209, 'Smoke drifted up from the jungle ahead of us.', 'n. 漂流，漂移；趋势；漂流物; v. 漂流，漂移；漂泊', '/drift | drɪft/', 'drift', 5);
INSERT INTO `words` VALUES (25210, 'an electric drill', 'n. 训练；钻孔机；钻子；播种机; v. 钻孔；训练', '/dril | drɪl/', 'drill', 5);
INSERT INTO `words` VALUES (25211, 'You should drink plenty of water.', 'v. 喝，饮；吸收；举杯庆贺; n. 酒，饮料；喝酒', '/driŋk | drɪŋk/', 'drink', 5);
INSERT INTO `words` VALUES (25212, 'The tap’s dripping .', 'v. 滴下；充满；漏下; n. 水滴，滴水声；静脉滴注；使人厌烦的人', '/drip | drɪp/', 'drip', 5);
INSERT INTO `words` VALUES (25213, 'the man driving the car', 'v. 开车；猛击；飞跑; n. 驱动器；驾车；[心理] 内驱力，推进力；快车道', '/draiv | draɪv/', 'drive', 5);
INSERT INTO `words` VALUES (25214, 'a taxi driver', 'n. 驾驶员；驱动程序；起子；传动器', '/draivə | \'draɪvə | \'draɪvɚ/', 'driver', 5);
INSERT INTO `words` VALUES (25215, 'Temperatures can drop to freezing at night.', 'v. 滴；使降低；使终止；随口漏出; n. 滴；落下；空投；微量；滴剂', '/drɔp | drɒp | drɑp/', 'drop', 5);
INSERT INTO `words` VALUES (25216, '...a country where drought and famines have killed up to two million people during the last eighteen years.', 'n. 干旱；缺乏', '/draut | draʊt/', 'drought', 5);
INSERT INTO `words` VALUES (25217, 'Many people drowned when the boat overturned.', 'v. 淹没；把…淹死; n. (Drown)人名；(英)德朗', '/draun | draʊn/', 'drown', 5);
INSERT INTO `words` VALUES (25218, 'A lot of young people start taking drugs at school.', 'n. 药；毒品；麻醉药；滞销货; v. 使服麻醉药；使服毒品；掺麻醉药于', '/drʌɡ | drʌg/', 'drug', 5);
INSERT INTO `words` VALUES (25219, 'I could hear the rain drumming against the windows.', 'v. 击鼓；大力争取; n. 鼓；鼓声', '/drʌm/', 'drum', 5);
INSERT INTO `words` VALUES (25220, 'He must be either mad or drunk.', 'v. 喝酒（drink的过去分词）; adj. 喝醉了的', '/drʌŋk/', 'drunk', 5);
INSERT INTO `words` VALUES (25221, 'The firm was accused of dubious accounting practices.', 'adj. 可疑的；暧昧的；无把握的；半信半疑的', '/\'dju:bjəs | \'djuːbɪəs | \'dubɪəs/', 'dubious', 5);
INSERT INTO `words` VALUES (25222, 'roast duck with orange sauce', 'n. 鸭子；鸭肉；（英）宝贝儿；零分; v. 闪避；没入水中', '/dʌk/', 'duck', 5);
INSERT INTO `words` VALUES (25223, 'Life is never dull when Elizabeth is here.', 'adj. 钝的；迟钝的；无趣的；呆滞的；阴暗的; v. 使迟钝；使阴暗；缓和; n. (Dull)人名；(罗、匈)杜尔；(柬)杜；(英)达尔', '/dʌl/', 'dull', 5);
INSERT INTO `words` VALUES (25224, 'He stared at the burnt-out car in dumb disbelief.', 'adj. 哑的，无说话能力的；不说话的，无声音的', '/dʌm/', 'dumb', 5);
INSERT INTO `words` VALUES (25225, 'Merrill dumped her suitcase down in the hall.', 'v. 倾倒；倾卸；丢下，卸下；摆脱，扔弃；倾销; n. 垃圾场；仓库；无秩序地累积', '/dʌmp/', 'dump', 5);
INSERT INTO `words` VALUES (25226, 'New copies of the form can be duplicated from a master copy.', 'v. 复制；使加倍; n. 副本；复制品; adj. 复制的；二重的', '/\'dju:plikət, \'dju:plikeit | ˈdjuːplɪkeɪt | \'duplɪket/', 'duplicate', 5);
INSERT INTO `words` VALUES (25227, 'Wood is a durable material.', 'adj. 耐用的，持久的; n. 耐用品', '/\'djuərəbl | \'djʊərəb(ə)l | \'dʊrəbl/', 'durable', 5);
INSERT INTO `words` VALUES (25228, 'The course is of three years’ duration.', 'n. 期间；持久， 持续时间', '/dju\'reɪʃn | du\'reʃən/', 'duration', 5);
INSERT INTO `words` VALUES (25229, 'The street lights go on at dusk.', 'n. 黄昏，薄暮；幽暗，昏暗; adj. 微暗的; v. 使变微暗', '/dʌsk/', 'dusk', 5);
INSERT INTO `words` VALUES (25230, 'All the furniture was covered in dust .', 'n. 灰尘；尘埃；尘土; v. 撒；拂去灰尘', '/dʌst/', 'dust', 5);
INSERT INTO `words` VALUES (25231, 'I promise I will do my duty .', 'n. 责任；[税收] 关税；职务', '/\'dju:ti, \'du:- | \'djuːtɪ | \'dʊti/', 'duty', 5);
INSERT INTO `words` VALUES (25232, 'The cathedral is dwarfed by the surrounding skyscrapers.', 'v. 变矮小; n. 侏儒，矮子; adj. 矮小的', '/dwɔ:f | dwɔːf | dwɔrf/', 'dwarf', 5);
INSERT INTO `words` VALUES (25233, 'They dwelt in the forest.', 'v. 居住；存在于；细想某事', '/dwel | dwɛl/', 'dwell', 5);
INSERT INTO `words` VALUES (25234, 'Some 3,500 new dwellings are planned for the area.', 'n. 住处；寓所; v. 居住（dwell的现在分词）', '/\'dweliŋ | \'dwelɪŋ | \'dwɛlɪŋ/', 'dwelling', 5);
INSERT INTO `words` VALUES (25235, 'hair dye', 'n. 染料；染色; v. 染；把…染上颜色', '/dai | daɪ/', 'dye', 5);
INSERT INTO `words` VALUES (25236, 'a dynamic and unstable process', 'adj. 动态的；动力的；动力学的；有活力的; n. 动态；动力', '/dai\'næmik | daɪ\'næmɪk/', 'dynamic', 5);
INSERT INTO `words` VALUES (25237, 'This article studies the dynamical action of a predator-prey system with age structure .', 'adj. 动力的， 电动的；有生气的', '/dai\'næmikəl | daɪ\'næmɪk(l)/', 'dynamical', 5);
INSERT INTO `words` VALUES (25238, 'The Habsburg dynasty ruled in Austria from 1278 to 1918.', 'n. 王朝，朝代', '/\'dinəsti, \'dai- | \'dɪnəstɪ | \'daɪnəsti/', 'dynasty', 5);
INSERT INTO `words` VALUES (25239, 'The eagle plumed its wing.', 'n. 鹰；鹰状标饰', '/\'i:ɡl | \'iːg(ə)l | \'igl/', 'eagle', 5);
INSERT INTO `words` VALUES (25240, 'She tucked her hair behind her ears.', 'n. 耳朵；穗；听觉；倾听; vi. （美俚）听见；抽穗', '/iə | ɪə | ɪr/', 'ear', 5);
INSERT INTO `words` VALUES (25241, 'He earns nearly £20,000 a year.', 'v. 赚，赚得；获得，挣得；使得到；博得; n. (Earn)人名；(泰)炎', '/ə:n | ɜːn | ɝn/', 'earn', 5);
INSERT INTO `words` VALUES (25242, 'a rather earnest young man', 'adj. 认真的，热心的；重要的; n. 认真；定金；诚挚', '/\'ə:nist | \'ɜːnɪst/', 'earnest', 5);
INSERT INTO `words` VALUES (25243, 'An earthquake measuring 6.1 on the Richter scale struck southern California on June 28.', 'n. 地震；大动荡', '/\'ə:θkweik | \'ɜːθkweɪk | \'ɝθ\'kwek/', 'earthquake', 5);
INSERT INTO `words` VALUES (25244, 'measures to ease congestion in the city', 'v. 减轻，缓和；使安心; n. 轻松，舒适；安逸，悠闲', '/i:z | iːz | iz/', 'ease', 5);
INSERT INTO `words` VALUES (25245, 'Which way is east?', 'n. 东方；东风；东方国家; adj. 东方的；向东的；从东方来的; adv. 向东方，在东方', '/i:st | iːst | ist/', 'east', 5);
INSERT INTO `words` VALUES (25246, '\"Happy Easter,\" he yelled.', 'n. 复活节', '/\'i:stə | istəʳ/', 'easter', 5);
INSERT INTO `words` VALUES (25247, 'Eastern religions', 'adj. 东方的；朝东的；东洋的; n. 东方人；（美国）东部地区的人', '/\'i:stən | \'iːst(ə)n | \'istɚn/', 'eastern', 5);
INSERT INTO `words` VALUES (25248, 'His confidence is at a low ebb.', 'n. 衰退；退潮；衰落; v. 衰退；减少；衰落；潮退', '/eb | ɛb/', 'ebb', 5);
INSERT INTO `words` VALUES (25249, 'His eccentric behaviour lost him his job.', 'adj. 古怪的，反常的; n. 古怪的人', '/ik\'sentrik | ɪk\'sentrɪk; ek- | ɪk\'sɛntrɪk/', 'eccentric', 5);
INSERT INTO `words` VALUES (25250, '‘You bet,’ she said, echoing his words.', 'v. 反射；重复; n. 回音；效仿', '/\'ekəu | \'ekəʊ | \'ɛko/', 'echo', 5);
INSERT INTO `words` VALUES (25251, 'an eclipse of the sun', 'n. 食', '/ɪ\'klɪps/', 'eclipse', 5);
INSERT INTO `words` VALUES (25252, 'the natural ecology of the Earth', 'n. 生态学', '/i:\'kɔlədʒi | ɪ\'kɒlədʒɪ; e- | ɪ\'kɑlədʒi/', 'ecology', 5);
INSERT INTO `words` VALUES (25253, 'Economic growth is slow.', 'adj. 经济(上)的,经济学的', '/,i:kə\'nɔmik | ,iːkə\'nɒmɪk; ek- | ˌikəˈnɑmɪk, ˌɛkəˈ-nɑmɪk/', 'economic', 5);
INSERT INTO `words` VALUES (25254, 'A small car is more economical to run.', 'adj. 节约的,经济的', '/,i:kə\'nɔmikəl | iːkə\'nɒmɪk(ə)l; ek- | ,ɛkə\'nɑmɪkl/', 'economical', 5);
INSERT INTO `words` VALUES (25255, 'a Harvard professor of economics', 'n. 经济学,经济情况', '/,i:kə\'nɔmiks | iːkə\'nɒmɪks; ek- | \'ikə\'nɑmɪks; \'ɛkə\'nɑmɪks/', 'economics', 5);
INSERT INTO `words` VALUES (25256, 'a successful economy', 'n. 节约;经济', '/i\'kɔnəmi | ɪ\'kɒnəmɪ | ɪ\'kɑnəmi/', 'economy', 5);
INSERT INTO `words` VALUES (25257, 'Put the eggs in the centre of the dish, with the vegetables and herbs around the edge.', 'n. 边缘；优势；刀刃；锋利; v. 使锐利；将…开刃；给…加上边', '/edʒ | ɛdʒ/', 'edge', 5);
INSERT INTO `words` VALUES (25258, 'These berries are edible, but those are poisonous.', 'adj. 可食用的; n. 食品；食物', '/\'edibl | \'edɪb(ə)l | \'ɛdəbl/', 'edible', 5);
INSERT INTO `words` VALUES (25259, 'The newspaper edits letters before printing them.', 'vt. 编辑， 校订', '/\'edɪt | \'ɛdɪt/', 'edit', 5);
INSERT INTO `words` VALUES (25260, 'a paperback edition', 'n. 版本', '/i\'diʃən | ɪ\'dɪʃ(ə)n | ɪ\'dɪʃən/', 'edition', 5);
INSERT INTO `words` VALUES (25261, 'the editor of a book of essays on modern poetry', 'n. 编者，编辑；社论撰写人；编辑装置', '/\'editə | \'edɪtə | \'ɛdɪtɚ/', 'editor', 5);
INSERT INTO `words` VALUES (25262, 'an editorial assistant', 'adj. 编辑的；社论的; n. 社论', '/,edi\'tɔ:riəl | edɪ\'tɔːrɪəl | ,ɛdɪ\'tɔrɪəl/', 'editorial', 5);
INSERT INTO `words` VALUES (25263, 'The Ormerod School educates handicapped children.', 'v. 教育,培养,训练', '/\'edju:keit | \'edjʊkeɪt | \'ɛdʒuket/', 'educate', 5);
INSERT INTO `words` VALUES (25264, 'She also hopes her children will get a good education.', 'n. 教育,培养,训练', '/,edju:\'keiʃən | edjʊ\'keɪʃ(ə)n | ,ɛdʒu\'keʃən/', 'education', 5);
INSERT INTO `words` VALUES (25265, 'the long-term effects of the drug', 'n. 结果;效果;影响;印象; v. 招致;实现;达到', '/i\'fekt | ɪ\'fekt | ɪ\'fɛkt/', 'effect', 5);
INSERT INTO `words` VALUES (25266, 'The cheaper drugs are just as effective in treating arthritis.', 'adj. 有效的,生效的;被实施的;给人深刻印象', '/i\'fektiv | ɪ\'fektɪv | ɪ\'fɛktɪv/', 'effective', 5);
INSERT INTO `words` VALUES (25267, 'considerable advancements in energy efficiency', 'n. 效率;功效', '/i\'fiʃənsi | ɪ\'fɪʃ(ə)nsɪ | ɪ\'fɪʃənsi/', 'efficiency', 5);
INSERT INTO `words` VALUES (25268, 'a very efficient secretary', 'adj. 有效的,效率高的;有能力的,能胜任的', '/i\'fiʃənt | ɪ\'fɪʃ(ə)nt | ɪ\'fɪʃnt/', 'efficient', 5);
INSERT INTO `words` VALUES (25269, 'please make an effort to be polite.', 'n. 努力；成就', '/\'efət | \'ɛfɚt/', 'effort', 5);
INSERT INTO `words` VALUES (25270, 'Blackbirds lay their eggs in March.', 'n. 蛋；卵子；家伙；鸡蛋; v. 煽动；怂恿', '/eg | ɛɡ/', 'egg', 5);
INSERT INTO `words` VALUES (25271, 'That promotion really boosted her ego (= made her feel better about herself ).', 'n. 自我；自负；自我意识', '/\'i:ɡəu, \'eɡəu | \'iːgəʊ; \'e- | \'iɡo/', 'ego', 5);
INSERT INTO `words` VALUES (25272, 'At least eighteen bullets were fired.', 'n. 十八，十八个; adj. 十八个的，十八的; num. 十八', '/\'ei\'ti:n | eɪ\'tiːn; \'eɪtiːn | ,e\'tin/', 'eighteen', 5);
INSERT INTO `words` VALUES (25273, 'Two engines cut out and the plane started to eject fuel as it lost height.', 'v. 喷射,排出;驱逐', '/i\'dʒekt, \'i:dʒekt | ɪ\'dʒekt | ɪ\'dʒɛkt/', 'eject', 5);
INSERT INTO `words` VALUES (25274, 'pure silks embroidered with elaborate patterns', 'adj. 精心制作的；详尽的；煞费苦心的; v. 精心制作；详细阐述；从简单成分合成（复杂有机物）', '/i\'læbərət, i\'læbəreit | ɪ\'læb(ə)rət | ɪ\'læbəret/', 'elaborate', 5);
