INSERT INTO `words` VALUES (25277, 'He slipped and fell, badly bruising an elbow.', 'n. 肘部；弯头；扶手; v. 推挤；用手肘推开', '/\'elbəu | \'elbəʊ | \'ɛlbo/', 'elbow', 5);
