INSERT INTO `words` VALUES (25280, 'the country’s first democratically elected government', 'v. 选举,推选;选择,作出选择', '/i\'lekt | ɪ\'lekt | ɪ\'lɛkt/', 'elect', 5);
INSERT INTO `words` VALUES (25281, 'an electric blanket', 'adj. 电的；电动的；发电的；导电的；令人震惊的; n. 电；电气车辆；带电体', '/i\'lektrik | ɪ\'lektrɪk | ɪ\'lɛktrɪk/', 'electric', 5);
