INSERT INTO `words` VALUES (25285, 'Most things are balanced - with equal numbers of electrons and protons.', 'n. 电子', '/i\'lektrɔn | ɪ\'lektrɒn | ɪ\'lɛktrɑn/', 'electron', 5);
