INSERT INTO `words` VALUES (25287, 'a tall, elegant young woman', 'adj. 优雅的;端庄的;雅致的', '/\'elɪg(ə)nt | \'ɛləgənt/', 'elegant', 5);
INSERT INTO `words` VALUES (25288, 'Business and management elements are built into the course.', 'n. 元素；要素；原理；成分；自然环境', '/\'elimənt | \'elɪm(ə)nt | \'ɛləmənt/', 'element', 5);
