INSERT INTO `words` VALUES (25290, 'Tom: No.Although 75% of its raw materials is elephant dung, it is light delicate fragrance instead of stink. This is due to its special fabrication technology.', 'n. 象；大号图画纸', '/\'elifənt | \'elɪf(ə)nt | \'ɛlɪfənt/', 'elephant', 5);
