INSERT INTO `words` VALUES (25294, 'a ruthless dictator who eliminated all his rivals', 'v. 消除；排除', '/i\'limineit | ɪ\'lɪmɪneɪt | ɪ\'lɪmɪnet/', 'eliminate', 5);
