INSERT INTO `words` VALUES (25299, 'He didn’t want to embarrass her by asking questions.', 'v. 使困窘,使局促不安;阻碍,麻烦', '/im\'bærəs | ɪm\'bærəs; em- | ɪm\'bærəs/', 'embarrass', 5);
INSERT INTO `words` VALUES (25300, 'the American Embassy in Paris', 'n. 大使馆;大使及其随员', '/\'embəsi | \'embəsɪ | \'ɛmbəsi/', 'embassy', 5);
INSERT INTO `words` VALUES (25301, 'One of the bullets passed through Andrea\'s chest before embedding itself in a wall.', 'v. 栽种；使嵌入，使插入；使深留脑中', '/im\'bed | ɪm\'bed; em- | ɪm\'bɛd/', 'embed', 5);
