INSERT INTO `words` VALUES (25303, 'Jack warmly embraced his son.', 'v. 拥抱；信奉，皈依；包含; n. 拥抱', '/im\'breis | ɪm\'breɪs; em- | ɪm\'bres/', 'embrace', 5);
INSERT INTO `words` VALUES (25304, 'The system already exists in embryo.', 'n. 胚， 胚胎 <；事物的萌芽期', '/\'embriəu | \'ɛmbrɪo/', 'embryo', 5);
INSERT INTO `words` VALUES (25305, 'The flowers emerge in the spring.', 'v. 显现,浮现;暴露;形成;', '/i\'mə:dʒ | ɪ\'mɜːdʒ | ɪ\'mɝdʒ/', 'emerge', 5);
INSERT INTO `words` VALUES (25306, 'Lifeguards are trained to deal with emergencies.', 'n. 紧急情况,突然事件,非常时刻', '/i\'mə:dʒənsi | ɪ\'mɜːdʒ(ə)nsɪ | ɪ\'mɝdʒənsi/', 'emergency', 5);
