INSERT INTO `words` VALUES (25313, 'I would emphasise three criteria.', 'vt. 强调， 着重', '/\'emfəsaɪz | \'emfəsaiz/', 'emphasise', 5);
INSERT INTO `words` VALUES (25314, 'The report emphasizes the importance of improving safety standards.', 'v. 强调，着重', '/\'emfəsaiz | \'emfəsaɪz | \'ɛmfəsaɪz/', 'emphasize', 5);
INSERT INTO `words` VALUES (25315, 'the Roman empire', 'n. 帝国；帝王统治，君权', '/\'empaiə | \'empaɪə | \'ɛmpaɪr/', 'empire', 5);
INSERT INTO `words` VALUES (25316, '{\"COLLOINEXA\":[\"empirical evidence\"]}', 'adj. 经验主义的，完全根据经验的；实证的', '/em\'pɪrɪk(ə)l; ɪm- | ɪm\'pɪrɪkl/', 'empirical', 5);
INSERT INTO `words` VALUES (25317, 'The shoe factory is the largest employer in this area.', 'n. 雇主，老板', '/im\'plɔiə | ɪm\'plɒɪə; em- | ɪm\'plɔɪɚ/', 'employer', 5);
INSERT INTO `words` VALUES (25318, 'She was offered employment in the sales office.', 'n. 使用；职业；雇用', '/im\'plɔimənt | ɪm\'plɒɪm(ə)nt; em- | ɪm\'plɔɪmənt/', 'employment', 5);
INSERT INTO `words` VALUES (25319, 'The new test should enable doctors to detect the disease early.', 'v. 使能够，使成为可能；授予权利或方法', '/i\'neibl | ɪn\'eɪb(ə)l; en- | ɪ\'nebl/', 'enable', 5);
