INSERT INTO `words` VALUES (25321, 'the enclosure of arable land for pasture', 'n. 围住,圈起,封入,附件', '/in\'kləuʒə | ɪn\'kləʊʒə; en- | ɪn\'kloʒɚ/', 'enclosure', 5);
