INSERT INTO `words` VALUES (25326, 'She improved visibly from day to day, until Martin wondered if he was doing right, for he knew that all her compliance and endeavor was for his sake.', 'n. 努力；尽力（等于endeavour）; v. 努力；尽力（等于endeavour）', '/in\'devə | ɪn\'devə | ɪn\'dɛvɚ/', 'endeavor', 5);
