INSERT INTO `words` VALUES (25329, 'I can endorse their opinion wholeheartedly.', 'vt. 赞同， 认可；代言；背书； 在背面签名<', '/ɪn\'dɔːs | ɪn\'dɔrs/', 'endorse', 5);
INSERT INTO `words` VALUES (25330, 'You are endowed with wealth, good health and a lively intellect.', 'v. 赋予；捐赠；天生具有', '/in\'dau | ɪn\'daʊ; en- | ɪn\'daʊ/', 'endow', 5);
