INSERT INTO `words` VALUES (25334, 'an energetic man', 'adj. 精力充沛的；积极的；有力的', '/,enə\'dʒetik | ,enə\'dʒetɪk | ,ɛnɚ\'dʒɛtɪk/', 'energetic', 5);
