INSERT INTO `words` VALUES (25343, 'an operation to enlarge her breasts', 'v. 扩大；放大；详述', '/in\'lɑ:dʒ | ɪn\'lɑːdʒ; en- | ɪn\'lɑrdʒ/', 'enlarge', 5);
