INSERT INTO `words` VALUES (25365, 'Some of these chemicals are very damaging to the environment.', 'n. 环境，外界', '/in\'vaiərənmənt | ɪn\'vaɪrənm(ə)nt; en- | ɪn\'vaɪrənmənt/', 'environment', 5);
INSERT INTO `words` VALUES (25366, 'The scheme cost a lot more than we had originally envisaged.', 'v. 想象，设想，展望，正视', '/in\'vizidʒ | ɪn\'vɪzɪdʒ; en- | ɪn\'vɪzɪdʒ/', 'envisage', 5);
INSERT INTO `words` VALUES (25367, 'She could see that all the other girls were green with envy(= feeling a lot of envy ).', 'n. 嫉妒，妒忌；羡慕; v. 嫉妒，妒忌；羡慕', '/\'envi | \'envɪ | \'ɛnvi/', 'envy', 5);
INSERT INTO `words` VALUES (25368, 'Over 500 people died during last year’s flu epidemic.', 'adj. 流行的；传染性的; n. 传染病；流行病；风尚等的流行', '/,epi\'demik | epɪ\'demɪk | ,ɛpɪ\'dɛmɪk/', 'epidemic', 5);
INSERT INTO `words` VALUES (25369, 'Watch next week’s thrilling episode!', 'n. 插曲；一段情节；插话；有趣的事件', '/\'episəud | \'epɪsəʊd | \'ɛpɪsod/', 'episode', 5);
INSERT INTO `words` VALUES (25370, 'the Victorian epoch', 'n. [地质] 世；新纪元；新时代；时间上的一点', '/\'i:pɔk, \'epək | \'iːpɒk; \'epɒk | \'ɛpək/', 'epoch', 5);
INSERT INTO `words` VALUES (25371, 'Our constitution states that all men are equal.', 'adj. 相等的;胜任的n.相等的事务;对手v.等于', '/\'i:kwəl | \'ikwəl/', 'equal', 5);
INSERT INTO `words` VALUES (25372, '...equality of the sexes.', 'n. 同等;平等;相等;等式;等同性', '/i:\'kwɔləti | ɪ\'kwɒlɪtɪ; iː- | ɪ\'kwɑləti/', 'equality', 5);
INSERT INTO `words` VALUES (25373, 'In the equation 2x + 1 = 7, what is x?', 'n. (数学)等式,方程式;(with)相等;均衡', '/i\'kweiʒən, -ʃən | ɪ\'kweɪʒ(ə)n | ɪ\'kweʒn/', 'equation', 5);
INSERT INTO `words` VALUES (25374, 'The United States is north of the equator.', 'n. 赤道', '/i\'kweitə | ɪ\'kweɪtə | ɪ\'kwetɚ/', 'equator', 5);
INSERT INTO `words` VALUES (25375, 'They try to equip their vehicles with gadgets to deal with every possible contingency.', 'v. (with)装备,配备;训练', '/i\'kwip | ɪ\'kwɪp/', 'equip', 5);
INSERT INTO `words` VALUES (25376, 'a shop selling camping equipment', 'n. 设备,器材,装置;才能', '/i\'kwipmənt | ɪ\'kwɪpm(ə)nt | ɪ\'kwɪpmənt/', 'equipment', 5);
INSERT INTO `words` VALUES (25377, 'I had no dollars, but offered him an equivalent amount of sterling.', 'adj. (to)相等的,等价的; n. 相等物,等价物', '/i\'kwivələnt | ɪ\'kwɪv(ə)l(ə)nt | ɪ\'kwɪvələnt/', 'equivalent', 5);
INSERT INTO `words` VALUES (25378, 'His death marked the end of an era.', 'n. 时代；年代；纪元', '/\'iərə, \'εərə | \'ɪərə | \'ɪrə/', 'era', 5);
INSERT INTO `words` VALUES (25379, 'The computer crashed, and all our records were erased.', 'v. 抹去；擦除', '/i\'reiz, i\'reis | ɪ\'reɪz | ɪ\'res/', 'erase', 5);
INSERT INTO `words` VALUES (25380, 'an imposing town hall, erected in 1892', 'v. 树立,建立,使竖立; adj. 直立的,垂直的', '/i\'rekt | ɪ\'rekt | ɪ\'rɛkt/', 'erect', 5);
INSERT INTO `words` VALUES (25381, 'the problem of soil erosion', 'n. 侵蚀，腐蚀', '/i\'rəuʒən | ɪ\'rəʊʒ(ə)n | ɪ\'roʒən/', 'erosion', 5);
INSERT INTO `words` VALUES (25382, 'His economic predictions are based on some erroneous assumptions.', 'adj. 错误的；不正确的', '/i\'rəuniəs | ɪ\'rəʊnɪəs; e- | ɪ\'ronɪəs/', 'erroneous', 5);
INSERT INTO `words` VALUES (25383, 'an error message', 'n. 错误， 过失； 误差', '/\'erə | \'ɛrɚ/', 'error', 5);
INSERT INTO `words` VALUES (25384, 'Violence erupted after police shot a student during the demonstration.', 'v. 爆发；喷出；发疹；长牙', '/i\'rʌpt | ɪ\'rʌpt/', 'erupt', 5);
INSERT INTO `words` VALUES (25385, 'The fighting on the border is escalating.', 'v. (使)逐步增长(或发展)，(使)逐步升级', '/\'eskəleit | \'eskəleɪt | \'ɛskəlet/', 'escalate', 5);
INSERT INTO `words` VALUES (25386, 'The girl had no chance of escape.', 'n. 逃跑,逃脱; v. 逃跑;避开,避免', '/ɪ\'skeɪp; e- | ɪˈskep/', 'escape', 5);
INSERT INTO `words` VALUES (25387, 'a police escort', 'n. 陪同；护航舰；护卫队；护送者; v. 护送；陪同；为…护航', '/\'eskɔ:t, i\'skɔ:t | \'eskɔːt | ˈeskɔːrt/', 'escort', 5);
INSERT INTO `words` VALUES (25388, 'I never liked long walks, especially in winter.', 'adv. 特别，尤其，格外；专门地，主要地', '/i\'speʃəli | ɪ\'speʃ(ə)lɪ; e- | ɪ\'spɛʃəli/', 'especially', 5);
INSERT INTO `words` VALUES (25389, 'We asked Jason to write an essay about his hometown.', 'n. 散文；试图；随笔; v. 尝试；对…做试验', '/\'esei, e\'sei | \'eseɪ | \'ɛse/', 'essay', 5);
INSERT INTO `words` VALUES (25390, 'In essence his message was very simple.', 'n. 本质,实质', '/\'esəns | \'es(ə)ns | \'ɛsns/', 'essence', 5);
INSERT INTO `words` VALUES (25391, 'The essential difference between Sam and me was the fact that I took life seriously.', 'adj. 本质的,基本的;净化的; n. 本质;要素', '/i\'senʃəl | ɪ\'senʃ(ə)l | ɪ\'sɛnʃl/', 'essential', 5);
INSERT INTO `words` VALUES (25392, 'The city of Boerne was established by German settlers in the 1840s.', 'v. 建立；创办；安置', '/i\'stæbliʃ | ɪ\'stæblɪʃ; e- | ɪˈstæblɪʃ/', 'establish', 5);
INSERT INTO `words` VALUES (25393, NULL, 'n. 确立，制定；公司；设施', '/i\'stæbliʃmənt | ɪ\'stæblɪʃm(ə)nt; e- | ɪ\'stæblɪʃmənt/', 'establishment', 5);
INSERT INTO `words` VALUES (25394, 'His estate was valued at $150,000.', 'n. 地产， 房地产', '/ɪ\'steɪt | ɪ\'stet/', 'estate', 5);
INSERT INTO `words` VALUES (25395, 'Peden was greatly esteemed by the people of Ayrshire.', 'v. 尊敬；认为；考虑；估价; n. 尊重；尊敬', '/i\'sti:m | ɪ\'stiːm; e- | ɪ\'stim/', 'esteem', 5);
INSERT INTO `words` VALUES (25396, 'We just need an estimate of the number of people who will come.', 'v&n. 估计,估价;评估', '/\'estimeit | \'estɪmeɪt | \'ɛstə,met/', 'estimate', 5);
INSERT INTO `words` VALUES (25397, 'the Christian promise of eternal life', 'adj. 永恒的；不朽的', '/i\'tə:nəl | ɪ\'tɜːn(ə)l; iː- | ɪ\'tɝnl/', 'eternal', 5);
INSERT INTO `words` VALUES (25398, 'The old ethic of hard work has given way to a new ethic of instant gratification.', 'n. 道德准则， 行为准则， 伦理标准；', '/\'eθɪk | \'ɛθɪk/', 'ethic', 5);
INSERT INTO `words` VALUES (25399, 'The school teaches pupils from different ethnic groups.', 'adj. 种族的；人种的', '/\'eθnik | \'eθnɪk | \'ɛθnɪk/', 'ethnic', 5);
INSERT INTO `words` VALUES (25400, 'Police evacuated the area.', 'v. 撤离，疏散，排泄，剥夺', '/i\'vækjueit | ɪ\'vækjʊeɪt | ɪ\'vækjuet/', 'evacuate', 5);
INSERT INTO `words` VALUES (25401, 'I could tell that he was trying to evade the issue.', 'v. 逃避，回避；避开，躲避', '/i\'veid | ɪ\'veɪd | ɪ\'ved/', 'evade', 5);
INSERT INTO `words` VALUES (25402, 'You should be able to evaluate your own work.', 'v. 估价,评价;求…的值', '/i\'væljueit | ɪ\'væljʊeɪt | ɪ\'væljʊ\'et/', 'evaluate', 5);
INSERT INTO `words` VALUES (25403, 'Most of the water had evaporated.', 'v. 蒸发,挥发;沉淀;发射;消失', '/i\'væpəreit | ɪ\'væpəreɪt | ɪ\'væpəret/', 'evaporate', 5);
INSERT INTO `words` VALUES (25404, 'one summer’s eve', 'n. 夏娃； 前夕；傍晚；重大事件关头', '/iːv/', 'eve', 5);
INSERT INTO `words` VALUES (25405, 'I do most of my studying in the evening.', 'n. 晚上；傍晚；（联欢性的）晚会；后期; adj. 在晚上的；为晚上的；晚上用的; int. 晚上好（等于good evening）', '/\'i:vniŋ | \'iːv(ə)nɪŋ | \'ivnɪŋ/', 'evening', 5);
INSERT INTO `words` VALUES (25406, 'one of the most important events in the history of mankind', 'n. 事件,事情', '/i\'vent | ɪ\'vent | ɪ\'vɛnt/', 'event', 5);
INSERT INTO `words` VALUES (25407, 'He eventually escaped and made his way back to England.', 'adv. 终于,最后', '/i\'ventʃuəli | ɪ\'ventʃʊəlɪ | ɪ\'vɛntʃuəli/', 'eventually', 5);
INSERT INTO `words` VALUES (25408, 'the problems of everyday life', 'adj. 每天的，日常的; n. 平时；寻常日子', '/\'evridei | \'evrɪdeɪ; -\'deɪ | \'ɛvrɪde/', 'everyday', 5);
INSERT INTO `words` VALUES (25409, 'Murrow’s evidence was enough to convict Hayes of murder.', 'n. 明显;显著;根据;证据;迹象', '/\'evidəns | \'evɪd(ə)ns | \'ɛvɪdəns/', 'evidence', 5);
INSERT INTO `words` VALUES (25410, 'Bob ate his lunch with evident enjoyment.', 'adj. 明显的,明白的', '/\'evidənt | \'evɪd(ə)nt | \'ɛvɪdənt/', 'evident', 5);
INSERT INTO `words` VALUES (25411, 'an evil dictator responsible for the deaths of millions', 'adj. 邪恶的；不幸的；有害的；讨厌的; n. 罪恶，邪恶；不幸', '/\'i:vəl | \'iːv(ə)l; -vɪl | \'ivl/', 'evil', 5);
INSERT INTO `words` VALUES (25412, 'The photographs evoked strong memories of our holidays in France.', 'v. 唤起(回忆、感情等)；引起', '/i\'vəuk | ɪ\'vəʊk | ɪ\'vok/', 'evoke', 5);
INSERT INTO `words` VALUES (25413, 'the theory of evolution', 'n. 进化,演变,发展,进展', '/,i:və\'lu:ʃən, ,ev- | ,iːvə\'luːʃ(ə)n; \'ev- | ˌɛvəˈluʃən; (occas.) ˌ ivəˈluʃən/', 'evolution', 5);
INSERT INTO `words` VALUES (25414, 'Animals have evolved camouflage to protect themselves from predators.', 'v. (使)发展;(使)进化;(使)进展', '/i\'vɔlv | ɪ\'vɒlv | ɪ\'vɑlv/', 'evolve', 5);
INSERT INTO `words` VALUES (25415, 'Police are still investigating the exact cause of the accident.', 'adj. 准确的，精密的；精确的; v. 要求；强求；急需', '/ɪg\'zækt; eg- | ɪɡ\'zækt/', 'exact', 5);
INSERT INTO `words` VALUES (25416, 'I couldn’t sleep for three days – I’m not exaggerating.', 'v. 夸大， 夸张', '/ɪg\'zædʒəreɪt | ɪɡ\'zædʒəret/', 'exaggerate', 5);
INSERT INTO `words` VALUES (25417, 'A team of divers was sent down to examine the wreck.', 'v. 检查；调查； 检测；考试', '/iɡ\'zæmin | ɪg\'zæmɪn; eg- | ɪg\'zæmɪn/', 'examine', 5);
INSERT INTO `words` VALUES (25418, 'Working hours must not exceed 42 hours a week.', 'v. 超过,胜过;越出', '/ik\'si:d | ɪk\'siːd; ek- | ɪk\'sid/', 'exceed', 5);
INSERT INTO `words` VALUES (25419, 'Thank you. You’ve been exceedingly kind.', 'adv. 极端地,非常', '/ik\'si:diŋli | ɪk\'siːdɪŋlɪ; ek- | ɪk\'sidɪŋli/', 'exceedingly', 5);
INSERT INTO `words` VALUES (25420, 'Mary was a better rider than either of them and she excelled at outdoor sports.', 'v. 超过；擅长', '/ik\'sel | ɪk\'sel; ek- | ɪk\'sɛl/', 'excel', 5);
INSERT INTO `words` VALUES (25421, 'an excellent suggestion', 'adj. 卓越的；极好的；杰出的', '/\'eksələnt | \'eks(ə)l(ə)nt | \'ɛksələnt/', 'excellent', 5);
INSERT INTO `words` VALUES (25422, 'They were all there except me.', 'prep. 除…之外; v. 除外;反对', '/ik\'sept | ɪk\'sept; ek- | ɪk\'sɛpt/', 'except', 5);
INSERT INTO `words` VALUES (25423, 'It’s been cold, but today’s an exception.', 'n. 例外,除外;反对;异议', '/ik\'sepʃən | ɪk\'sepʃ(ə)n; ek- | ɪk\'sɛpʃən/', 'exception', 5);
INSERT INTO `words` VALUES (25424, 'an exceptional student', 'adj. 例外的,异常的', '/ik\'sepʃənəl | ɪk\'sepʃ(ə)n(ə)l; ek- | ɪk\'sɛpʃənl/', 'exceptional', 5);
INSERT INTO `words` VALUES (25425, '...an excerpt from Tchaikovsky\'s Nutcracker.', 'n. 摘录，引用; v. 引用，摘录', '/ek\'sə:pt, \'eksə:pt | \'eksɜːpt | \'ɛksɝpt/', 'excerpt', 5);
INSERT INTO `words` VALUES (25426, 'Cut any excess fat from the meat.', 'adj. 过量的,额外的; n. 过量;过剩;超额;无节制', '/ik\'ses, \'ek-, \'ekses, ik\'s- | ɪk\'ses; ek-; \'ekses | \'ɛk\'sɛs/', 'excess', 5);
INSERT INTO `words` VALUES (25427, 'his excessive drinking', 'adj. 过多的;过分的;额外', '/ik\'sesiv | ɪk\'sesɪv; ek- | ɪkˈsɛsɪv/', 'excessive', 5);
INSERT INTO `words` VALUES (25428, 'Four of my cassettes for your Madonna CD is a fair exchange.', 'n. 交换；交流；交易所；兑换; v. 交换；交易；兑换', '/iks\'tʃeindʒ | ɪks\'tʃeɪndʒ; eks- | ɪks\'tʃendʒ/', 'exchange', 5);
INSERT INTO `words` VALUES (25429, 'His playing is technically brilliant, but it doesn’t excite me.', 'v. 激起；刺激…，使…兴奋', '/ik\'sait | ɪk\'saɪt; ek- | ɪk\'saɪt/', 'excite', 5);
INSERT INTO `words` VALUES (25430, 'We were both new to the excitements of life in the big city.', 'n. 兴奋；刺激；令人兴奋的事物', '/ik\'saitmənt | ɪk\'saɪtmənt/', 'excitement', 5);
INSERT INTO `words` VALUES (25431, 'an exciting discovery', 'adj. 令人兴奋的；使人激动的; v. 激动；刺激（excite的ing形式）；唤起', '/ik\'saitiŋ | ɪk\'saɪtɪŋ; ek- | ɪk\'saɪtɪŋ/', 'exciting', 5);
INSERT INTO `words` VALUES (25432, '‘No!’ she exclaimed in shock.', 'v. 呼喊，惊叫；大声叫嚷', '/ik\'skleim | ɪk\'skleɪm; ek- | ɪk\'sklem/', 'exclaim', 5);
INSERT INTO `words` VALUES (25433, 'a special diet that excludes dairy products', 'v. 拒绝,把…排除在外,排斥', '/iks\'klu:d | ɪk\'skluːd; ek- | ɪk\'sklʊd/', 'exclude', 5);
INSERT INTO `words` VALUES (25434, 'Bel Air is an exclusive suburb of Los Angeles.', 'adj. 独占的;排他的;孤高的;唯一的;高级的', '/ik\'sklu:siv | ɪk\'skluːsɪv; ek- | ɪk\'sklusɪv/', 'exclusive', 5);
INSERT INTO `words` VALUES (25435, 'a shopping excursion', 'n. 短途旅行,游览;离题;[物理]偏移,漂移', '/ɪk\'skɜːʃ(ə)n; ek- | ɪk\'skɝʒn/', 'excursion', 5);
INSERT INTO `words` VALUES (25436, 'I’m tired of listening to his excuses.', 'n. 借口；理由; v. 原谅；为…申辩；给…免去', '/ik\'skju:z, ik\'skju:s | ɪk\'skjuːz; ek- | ɪk\'skjʊs/', 'excuse', 5);
INSERT INTO `words` VALUES (25437, '13 people were summarily executed (= killed without any trial or legal process ) by the guerrillas.', 'v. 实行;实施;执行;完成;履行;处死', '/\'eksikju:t | \'eksɪkjuːt | \'ɛksɪkjut/', 'execute', 5);
INSERT INTO `words` VALUES (25438, 'a marketing executive', 'n. 总经理,董事,行政负责人; adj. 执行的,实施的', '/ɪg\'zekjʊtɪv; eg- | ɪɡ\'zɛkjətɪv/', 'executive', 5);
INSERT INTO `words` VALUES (25439, 'All these recipes exemplify my cooking: healthy, delicious and quick.', 'v. 例证；例示', '/iɡ\'zemplifai | ɪg\'zemplɪfaɪ; eg- | ɪɡ\'zɛmplɪfaɪ/', 'exemplify', 5);
INSERT INTO `words` VALUES (25440, 'Men in college were exempt from military service.', 'adj. 被免除的， 被豁免的; vt. 使…免除', '/ɪg\'zempt | ɪg\'zɛmpt/', 'exempt', 5);
INSERT INTO `words` VALUES (25441, 'Try to fit some regular exercise into your daily routine.', 'n. 运动；练习；运用；操练；礼拜；典礼; v. 锻炼；练习；使用；使忙碌；使惊恐', '/\'eksəsaiz | \'eksəsaɪz | \'ɛksɚsaɪz/', 'exercise', 5);
INSERT INTO `words` VALUES (25442, 'They exerted considerable influence within the school.', 'v. 运用，发挥；施以影响', '/iɡ\'zə:t | ɪg\'zɜːt; eg- | ɪɡ\'zɝt/', 'exert', 5);
INSERT INTO `words` VALUES (25443, 'A full day’s teaching exhausts me.', 'v. 排出；耗尽；使精疲力尽；彻底探讨; n. 排气；废气；排气装置', '/iɡ\'zɔ:st | ɪg\'zɔːst; eg- | ɪɡ\'zɔst/', 'exhaust', 5);
INSERT INTO `words` VALUES (25444, 'Her paintings have been exhibited all over the world.', 'v. 展览；显示；提出（证据等）; n. 展览品；证据；展示会', '/iɡ\'zibit | ɪg\'zɪbɪt; eg- | ɪɡ\'zɪbɪt/', 'exhibit', 5);
INSERT INTO `words` VALUES (25445, 'I’ve never seen such an exhibition of jealousy.', 'n. 展览，显示；展览会；展览品', '/,eksi\'biʃən | eksɪ\'bɪʃ(ə)n | ,ɛksɪ\'bɪʃən/', 'exhibition', 5);
INSERT INTO `words` VALUES (25446, 'political exiles', 'n. 流放，充军；放逐，被放逐者；流犯; v. 放逐，流放；使背井离乡', '/\'eɡzail, \'eksail | \'eksaɪl; \'egz- | \'ɛksaɪl/', 'exile', 5);
INSERT INTO `words` VALUES (25447, 'The custom of arranged marriages still exists in many countries.', 'v. 存在；生存；生活；继续存在', '/iɡ\'zist | ɪg\'zɪst; eg- | ɪɡ\'zɪst/', 'exist', 5);
INSERT INTO `words` VALUES (25448, 'Scientists have many theories about how the universe first came into existence (= started to exist ).', 'n. 存在，实在；生存，生活；存在物，实在物', '/iɡ\'zistəns | ɪg\'zɪst(ə)ns; eg- | ɪɡ\'zɪstəns/', 'existence', 5);
INSERT INTO `words` VALUES (25449, 'We made for the nearest exit.', 'n. 出口，通道；退场; v. 退出；离去', '/\'eksit, \'eɡ zit | \'eksɪt; \'egzɪt | \'ɛɡzɪt/', 'exit', 5);
INSERT INTO `words` VALUES (25450, 'exotic birds', 'adj. 异国的；外来的；异国情调的', '/,iɡ\'zɔtik | ɪg\'zɒtɪk; eg- | ɪɡ\'zɑtɪk/', 'exotic', 5);
INSERT INTO `words` VALUES (25451, 'The computer industry has expanded greatly over the last decade.', 'v. (使)膨胀,(使)扩张;张开,展开', '/ik\'spænd | ɪk\'spænd; ek- | ɪk\'spænd/', 'expand', 5);
INSERT INTO `words` VALUES (25452, 'The industry underwent a period of rapid expansion.', 'n. 扩张,膨胀;张开,伸展', '/ik\'spænʃən | ɪk\'spænʃ(ə)n; ek- | ɪk\'spænʃən/', 'expansion', 5);
INSERT INTO `words` VALUES (25453, 'He will be hard to beat. I fully expect (= am completely sure about ) that and I’m ready.', 'v. 预期;期望,指望', '/ik\'spekt | ɪk\'spekt; ek- | ɪk\'spɛkt/', 'expect', 5);
INSERT INTO `words` VALUES (25454, 'Having raised expectations (= made people more hopeful ), he went on to help only a few people.', 'n. 预期,期望,指望', '/,ekspek\'teiʃən | ekspek\'teɪʃ(ə)n | ,ɛkspɛk\'teʃən/', 'expectation', 5);
INSERT INTO `words` VALUES (25455, 'an expedition to the North Pole', 'n. 远征；探险队；迅速', '/,ekspi\'diʃən | ekspɪ\'dɪʃ(ə)n | ,ɛkspə\'dɪʃən/', 'expedition', 5);
INSERT INTO `words` VALUES (25456, 'More than five-thousand high school students have been expelled for cheating.', 'v. 驱逐；开除', '/ik\'spel | ɪk\'spel; ek- | ɪk\'spɛl/', 'expel', 5);
INSERT INTO `words` VALUES (25457, 'Children expend a lot of energy and may need more high-energy food than adults.', 'v. 花费；消耗；用光；耗尽', '/ik\'spend | ɪk\'spend; ek- | ɪk\'spɛnd/', 'expend', 5);
INSERT INTO `words` VALUES (25458, 'huge cuts in public expenditure', 'n. 支出，花费；经费，消费额', '/iks\'penditʃə | ɪk\'spendɪtʃə; ek- | ɪk\'spɛndɪtʃɚ/', 'expenditure', 5);
INSERT INTO `words` VALUES (25459, 'He borrowed £150,000 and used the money for legal expenses.', 'n. 花费,消费,消耗', '/ik\'spens | ɪk\'spens; ek- | ɪk\'spɛns/', 'expense', 5);
INSERT INTO `words` VALUES (25460, 'the most expensive restaurant in town', 'adj. 花费的,昂贵的', '/ik\'spensiv | ɪk\'spensɪv; ek- | ɪk\'spɛnsɪv/', 'expensive', 5);
INSERT INTO `words` VALUES (25461, 'The advice in the booklet reflects the practical experience we have gained (= experience gained by actually doing something, rather than knowledge from books etc ).', 'n. 经验；经历；体验; v. 经验；经历；体验', '/ik\'spiəriəns | ɪk\'spɪərɪəns; ek- | ɪk\'spɪrɪəns/', 'experience', 5);
INSERT INTO `words` VALUES (25462, 'The teacher provided some different materials and left the children to experiment.', 'v. 尝试；进行实验; n. 实验，试验；尝试', '/ik\'speriment, ek\'s- | ɪk\'sperɪm(ə)nt; ek- | ɪk\'sperɪmənt/', 'experiment', 5);
INSERT INTO `words` VALUES (25463, 'experimental animals', 'adj. 实验的；根据实验的；试验性的', '/ek,speri\'mentəl, ek\'s- | ɪk,sperɪ\'ment(ə)l; ek- | ɛk\'spɛrɪ\'mɛntəl/', 'experimental', 5);
INSERT INTO `words` VALUES (25464, 'He cast his expert eye on the gardener’s work.', 'adj. 熟练的；内行的；老练的; n. 专家；行家；能手; vt. 当专家；在…中当行家', '/\'ekspə:t, ek\'spə:t | \'ekspɜːt | \'ɛkspɝt; (for adj., also) ɛksˈpɝt ; ɪkˈspɝt/', 'expert', 5);
INSERT INTO `words` VALUES (25465, 'She was not an accountant and didn\'t have the expertise to verify all of the financial details.', 'n. 专门知识；专门技术；专家的意见', '/,ekspə:\'ti:z | ,ekspɜː\'tiːz | \'ɛkspɝ\'tiz/', 'expertise', 5);
INSERT INTO `words` VALUES (25466, 'The chairman’s term of office has already expired.', 'v. 期满；终止；死亡；呼气', '/ik\'spaiə, ek- | ɪk\'spaɪə; ek- | ɪk\'spaɪɚ/', 'expire', 5);
INSERT INTO `words` VALUES (25467, 'She told the court she would give a full explanation of the prosecution\'s decision on Monday.', 'n. 说明，解释；辩解', '/,eksplə\'neiʃən | eksplə\'neɪʃ(ə)n | ,ɛksplə\'neʃən/', 'explanation', 5);
INSERT INTO `words` VALUES (25468, 'The contrast could not have been made more explicit.', 'adj. 明确的；清楚的；直率的；详述的', '/ik\'splisit | ɪk\'splɪsɪt; ek- | ɪk\'splɪsɪt/', 'explicit', 5);
INSERT INTO `words` VALUES (25469, 'The device was thrown at an army patrol but failed to explode.', 'v. 爆炸，爆发；激增', '/ik\'spləud | ɪk\'spləʊd; ek- | ɪk\'splod/', 'explode', 5);
INSERT INTO `words` VALUES (25470, 'Homeworkers can easily be exploited by employers.', 'v. 开发，开拓；剥削；开采; n. 勋绩；功绩', '/\'eksplɔit, ik\'s- | ɪk\'splɒɪt; ek- | ɪk\'splɔɪt/', 'exploit', 5);
INSERT INTO `words` VALUES (25471, 'Management need to explore ways of improving office security.', 'v. 探索；探测；探险', '/ik\'splɔ: | ɪk\'splɔː; ek- | ɪk\'splɔr/', 'explore', 5);
INSERT INTO `words` VALUES (25472, 'We heard a loud explosion.', 'n. 爆炸；爆发；激增', '/ik\'spləuʒən | ɪk\'spləʊʒ(ə)n; ek- | ɪk\'sploʒən/', 'explosion', 5);
INSERT INTO `words` VALUES (25473, 'Because the gas is highly explosive, it needs to be kept in high-pressure containers.', 'adj. 爆炸的；爆炸性的；爆发性的; n. 炸药；爆炸物', '/ik\'spləusiv | ɪk\'spləʊsɪv; ek- | ɪk\'splosɪv; ɪk\'splozɪv/', 'explosive', 5);
INSERT INTO `words` VALUES (25474, 'Wheat is one of the country’s main exports.', 'v&n. 输出,出口; n. 出口商品', '/ik\'spɔ:t, \'eks-, \'ekspɔ:t | ˈekspɔːt；ɪkˈ- | ˈekspɔːrt；ɪkˈ-/', 'export', 5);
INSERT INTO `words` VALUES (25475, 'Lowered sea levels exposed the shallow continental shelf beneath the Bering Sea.', 'v. (to)使暴露,受到;使曝光', '/ik\'spəuz | ɪk\'spəʊz; ek- | ɪk\'spoz；ek-/', 'expose', 5);
INSERT INTO `words` VALUES (25476, 'Exposure to lead is known to damage the brains of young children.', 'n. 暴露,揭露;方向;陈列;遗弃;照射量', '/ik\'spəuʒə | ɪk\'spəʊʒə; ek- | ɪk\'spoʒɚ/', 'exposure', 5);
INSERT INTO `words` VALUES (25477, 'Parents have expressed their concerns about their children’s safety.', 'v. 表达；快递; adj. 明确的；迅速的；专门的; n. 快车，快递，专使；捷运公司', '/ik\'spres | ɪk\'spres; ek- | ɪk\'sprɛs/', 'express', 5);
INSERT INTO `words` VALUES (25478, 'Student leaders are demanding greater freedom of expression (= the right to say what you think without being punished ).', 'n. 表现，表示，表达；表情，脸色，态度，腔调，声调；式，符号；词句，语句，措辞，说法', '/英 [ɪk\'spreʃn] 美 [ɪkˈsprɛʃən | ɪkˈspreʃn | ɪk\'sprɛʃən/', 'expression', 5);
INSERT INTO `words` VALUES (25479, 'the most exquisite craftsmanship', 'adj. 精致的；细腻的；优美的，高雅的；异常的；剧烈的; n. 服饰过于讲究的男子', '/\'ekskwizit, ek\'skwizit | \'ekskwɪzɪt; ɪk\'skwɪzɪt; ek- | ɪk\'skwɪzɪt/', 'exquisite', 5);
INSERT INTO `words` VALUES (25480, 'Management have agreed to extend the deadline.', 'v. 延伸；扩大；推广；伸出；给予；使竭尽全力；对…估价', '/ik\'stend | ɪk\'stend; ek- | ɪk\'stɛnd/', 'extend', 5);
INSERT INTO `words` VALUES (25481, 'a loft extension', 'n. 延长；延期；扩大；伸展；电话分机', '/ik\'stenʃən | ɪk\'stenʃ(ə)n; ek- | ɪk\'stɛnʃən/', 'extension', 5);
INSERT INTO `words` VALUES (25482, 'The house stands in extensive grounds.', 'adj. 广泛的；大量的；广阔的', '/ik\'stensiv | ɪk\'stensɪv; ek- | ɪk\'stɛnsɪv/', 'extensive', 5);
INSERT INTO `words` VALUES (25483, 'It’s too early to assess the full extent of the damage.', 'n. 广度， 宽度， 长度；程度， 限度', '/ɪk\'stent | ɪk\'stɛnt/', 'extent', 5);
INSERT INTO `words` VALUES (25484, 'The exterior walls need a new coat of paint.', 'adj. 外部的；表面的；外在的; n. 外部；表面；外型；外貌', '/ik\'stiəriə | ɪk\'stɪərɪə; ek- | ɪk\'stɪrɪɚ/', 'exterior', 5);
INSERT INTO `words` VALUES (25485, 'the external appearance of the building', 'adj. 外部的；表面的；[药] 外用的；外国的；外面的; n. 外部；外观；外面', '/ik\'stə:nəl | ɪk\'stɜːn(ə)l; ek- | ɪk\'stɝnl/', 'external', 5);
INSERT INTO `words` VALUES (25486, 'Dinosaurs have been extinct for millions of years.', 'adj. 灭绝的，绝种的；熄灭的; vt. 使熄灭', '/ik\'stiŋkt | ɪk\'stɪŋkt; ek- | ɪk\'stɪŋkt/', 'extinct', 5);
INSERT INTO `words` VALUES (25487, 'Please extinguish all cigarettes.', 'v. 熄灭；压制；偿清', '/ik\'stiŋɡwiʃ | ɪk\'stɪŋgwɪʃ; ek- | ɪk\'stɪŋɡwɪʃ/', 'extinguish', 5);
INSERT INTO `words` VALUES (25488, 'They need to offer something extra to attract customers.', 'adv. 特别地，非常；另外; n. 临时演员；号外；额外的事物；上等产品; adj. 额外的，另外收费的；特大的', '/\'ekstrə | \'ɛkstrə/', 'extra', 5);
INSERT INTO `words` VALUES (25489, 'You’ll have to have that tooth extracted.', 'v&n. 拔出,抽出;摘录; n. 抽取物;精华;选集', '/ik\'strækt, \'ekstrækt | ˈekstrækt | \'ɛkstrækt/', 'extract', 5);
INSERT INTO `words` VALUES (25490, 'a woman of extraordinary beauty', 'adj. 非常的;格外的;意外的;离奇的;临时的', '/ik\'strɔ:dənəri, ,ekstrə\'ɔ:di- | ɪkˈstrɔːd(ə)n(ə)ri; ekˈstrɔːd(ə)n(ə)ri; ˌekstrəˈɔːdɪn(ə)ri | ɛkˈstrɔrdənˌɛri; ɪkˈstrɔrdəˌnɛri; ˌɛkstrəˈɔrdəˌnɛri/', 'extraordinary', 5);
INSERT INTO `words` VALUES (25491, 'Would it be too extravagant to buy both?', 'adj. 奢侈的;过分的;(言行等)放肆的', '/ik\'strævəɡənt | ɪk\'strævəg(ə)nt; ek- | ɪk\'strævəgənt/', 'extravagant', 5);
INSERT INTO `words` VALUES (25492, 'Extreme poverty still exists in many rural areas.', 'adj. 极端的；极度的；偏激的；尽头的; n. 极端；末端；最大程度；极端的事物', '/ik\'stri:m | ɪk\'striːm; ek- | ɪk\'strim/', 'extreme', 5);
INSERT INTO `words` VALUES (25493, 'thick bushy eyebrows', 'n. 眉毛; v. 为…描眉；用皱眉蹙额迫使', '/\'aibrau | \'aɪbraʊ/', 'eyebrow', 5);
INSERT INTO `words` VALUES (25494, 'He had a problem with his eyesight.', 'n. 视力', '/\'aɪsaɪt/', 'eyesight', 5);
INSERT INTO `words` VALUES (25495, 'the fable of the fox and the crow', 'n. 寓言；无稽之谈; vi. 编寓言；虚构; vt. 煞有介事地讲述；虚构', '/\'feibl | \'feɪb(ə)l | \'febl/', 'fable', 5);
INSERT INTO `words` VALUES (25496, 'our new range of fabrics and wallpapers', 'n. 织物；布；组织；构造；建筑物', '/\'fæbrik | \'fæbrɪk/', 'fabric', 5);
INSERT INTO `words` VALUES (25497, 'The police were accused of fabricating evidence.', 'v. 制造；伪造；装配', '/\'fæbrikeit | \'fæbrɪkeɪt | \'fæbrɪket/', 'fabricate', 5);
INSERT INTO `words` VALUES (25498, 'You look fabulous!', 'adj. 寓言式的；极为巨大的；极好的', '/\'fæbjələs/', 'fabulous', 5);
INSERT INTO `words` VALUES (25499, 'The new airport will facilitate the development of tourism.', 'v. 促进；帮助；使容易', '/fə\'siliteit | fə\'sɪlɪteɪt | fə\'sɪlə\'tet/', 'facilitate', 5);
INSERT INTO `words` VALUES (25500, 'What recreational facilities are now available?', 'n. 设施；设备；容易；灵巧', '/fə\'siliti | fə\'sɪləti/', 'facility', 5);
INSERT INTO `words` VALUES (25501, 'Our decision to build the museum in Hartlepool was influenced by the fact that there were no national museums in the North East.', 'n. 事实,实际', '/fækt/', 'fact', 5);
INSERT INTO `words` VALUES (25502, 'The rise in crime is mainly due to social and economic factors.', 'n. 因素,要素', '/\'fæktə | \'fæktɚ/', 'factor', 5);
INSERT INTO `words` VALUES (25503, 'a car factory', 'n. 工厂', '/\'fæktəri | \'fækt(ə)rɪ | \'fæktri/', 'factory', 5);
INSERT INTO `words` VALUES (25504, 'Both faculty and students oppose the measures.', 'n. 科，系；能力；全体教员', '/\'fækəlti | \'fæk(ə)ltɪ | \'fæklti/', 'faculty', 5);
INSERT INTO `words` VALUES (25505, 'Hopes of a peace settlement are beginning to fade.', 'v. 褪色；凋谢；逐渐消失; adj. 平淡的；乏味的; n. [电影][电视] 淡出；[电影][电视] 淡入', '/feid, fad | feɪd | fed/', 'fade', 5);
INSERT INTO `words` VALUES (25506, 'Successful people often aren’t very good at dealing with failure.', 'n. 失败；故障；失败者；破产', '/\'feiljə | \'feɪljə | \'feljɚ/', 'failure', 5);
INSERT INTO `words` VALUES (25507, 'She gave a faint smile.', 'adj. 模糊的；头晕的；虚弱的；[医] 衰弱的; v. 昏倒；变得微弱；变得没气力; n. [中医] 昏厥，昏倒', '/\'feint | feɪnt | fent/', 'faint', 5);
INSERT INTO `words` VALUES (25508, 'Why does Eric get to go and I don’t? It’s not fair!', 'adj. 公平的；美丽的，白皙的；[气象] 晴朗的; adv. 公平地；直接地；清楚地; v. 转晴; n. 展览会；市集；美人', '/fεə | feə | fɛr/', 'fair', 5);
INSERT INTO `words` VALUES (25509, 'In his dream, he became a fairy.', 'n. 仙女，小精灵；漂亮姑娘; adj. 虚构的；仙女的', '/\'feərɪ | \'fɛri/', 'fairy', 5);
INSERT INTO `words` VALUES (25510, 'People have lost faith in the government.', 'n. 信仰；信念；信任；忠实', '/feiθ | feɪθ | feθ/', 'faith', 5);
INSERT INTO `words` VALUES (25511, 'a faithful friend', 'adj. 守信的， 忠实的； 如实的', '/\'feɪθfl | \'feθfəl/', 'faithful', 5);
INSERT INTO `words` VALUES (25512, 'He had served the family faithfully for 40 years.', 'adv. 忠诚地， 如实地', '/\'feɪθfəli | \'feθfəli/', 'faithfully', 5);
INSERT INTO `words` VALUES (25513, 'fake fur', 'adj. 假的; n. 假货；骗子; vt. 伪装， 伪造 A', '/feɪk/', 'fake', 5);
INSERT INTO `words` VALUES (25514, 'The tree was about to fall.', 'v. 落下；变成；来临；减弱; n. 下降；秋天；瀑布; adj. 秋天的', '/fɔ:l | fɔːl | fɔl/', 'fall', 5);
INSERT INTO `words` VALUES (25515, 'I don’t want to give you any false hopes .', 'adj. 错误的；虚伪的；伪造的; adv. 欺诈地', '/fɔ:ls | fɔːls; fɒls | fɔls/', 'false', 5);
INSERT INTO `words` VALUES (25516, 'He claims he is not really interested in fame.', 'n. 名声，名望；传闻，传说; vt. 使闻名，使有名望', '/feim | feɪm | fem/', 'fame', 5);
INSERT INTO `words` VALUES (25517, 'a familiar tune', 'adj. 熟悉的；常见的；亲近的; n. 常客；密友', '/fə\'miljə | fə\'mɪlɪə | fə\'mɪljɚ/', 'familiar', 5);
INSERT INTO `words` VALUES (25518, 'the great potato famine in Ireland', 'n. 饥荒；饥饿，奇缺', '/\'fæmin | \'fæmɪn/', 'famine', 5);
INSERT INTO `words` VALUES (25519, 'a famous actor', 'adj. 著名的；极好的，非常令人满意的', '/\'feiməs | \'feɪməs | \'feməs/', 'famous', 5);
INSERT INTO `words` VALUES (25520, 'Her resistance only fanned his desire.', 'v. 煽动；刺激；吹拂; n. 迷；风扇；爱好者', '/fæn/', 'fan', 5);
INSERT INTO `words` VALUES (25521, 'Oh, that was just a fancy of his.', 'n. 幻想；想象力；爱好; adj. 想象的；奇特的；昂贵的；精选的; v. 想象；喜爱；设想；自负', '/\'fænsɪ | \'fænsi/', 'fancy', 5);
INSERT INTO `words` VALUES (25522, 'You look fantastic!', 'adj. 奇异的；空想的；异想天开的；古怪的；极好的，极出色的；不可思议的；不切实际的; n. 古怪的人', '/fæn\'tæstɪk/', 'fantastic', 5);
INSERT INTO `words` VALUES (25523, 'fantastical creatures with golden wings and lions’ faces', 'adj. 奇异的， 幻想的， 异想天开的；极好的', '/fæn\'tæstikəl | fæn\'tæstɪk/', 'fantastical', 5);
INSERT INTO `words` VALUES (25524, 'I used to have fantasies about living in Paris with an artist.', 'n. 幻想；白日梦；幻觉; adj. 虚幻的; v. 空想；想像', '/\'fæntəsi | \'fæntəsɪ; -zɪ/', 'fantasy', 5);
INSERT INTO `words` VALUES (25525, 'It is unlikely that the marine industry will fare any better in September.', 'v. 经营；进展；遭遇；过活; n. 票价；费用；旅客；食物', '/fεə | feə | fɛr/', 'fare', 5);
INSERT INTO `words` VALUES (25526, 'Mourners gathered to bid farewell to the victims of the plane tragedy.', 'n. 告别，辞别；再见；再会; int. 别了！（常含有永别或不容易再见面的意思）；再会！; adj. 告别的', '/\'fεə\'wel | feə\'wel | ,fɛr\'wɛl/', 'farewell', 5);
INSERT INTO `words` VALUES (25527, 'The family has farmed here for generations.', 'v. 种田，务农；经营农场; n. 农场；农家；畜牧场', '/fɑ:m | fɑːm | fɑrm/', 'farm', 5);
INSERT INTO `words` VALUES (25528, 'She dickered with the farmer for the best fruit.', 'n. 农夫，农民', '/\'fɑ:mə | \'fɑːmə | \'fɑmɚ/', 'farmer', 5);
INSERT INTO `words` VALUES (25529, 'We decided not to go any farther.', 'adv. 更远地；此外；更进一步地; adj. 进一步的；更远的（far的比较级）', '/\'fɑ:ðə | \'fɑːðə | \'fɑrðɚ/', 'farther', 5);
INSERT INTO `words` VALUES (25530, 'Politics fascinated Franklin\'s father.', 'v. 使着迷，使神魂颠倒', '/\'fæsineit | \'fæsɪneɪt | \'fæsə\'net/', 'fascinate', 5);
INSERT INTO `words` VALUES (25531, 'I was fascinated by her voice.', 'adj. 兴奋的， 着迷的', '/\'fæsɪneɪtɪd | \'fæsɪnetɪd/', 'fascinated', 5);
INSERT INTO `words` VALUES (25532, 'His ideas are coming back into fashion (= they are becoming popular again ) .', 'n. 时尚；时装；样式；时髦人物; v. 使用；改变；做成…的形状', '/\'fæʃən | \'fæʃ(ə)n/', 'fashion', 5);
INSERT INTO `words` VALUES (25533, 'Strong colours are very fashionable at the moment.', 'adj. 流行的；时髦的；上流社会的', '/\'fæʃənəbl | \'fæʃ(ə)nəb(ə)l | \'fæʃnəbl/', 'fashionable', 5);
INSERT INTO `words` VALUES (25534, NULL, 'v. 使固定；集中于；扎牢；强加于; n. (Fasten)人名；(英)法森', '/\'fɑ:sən, \'fæ- | \'fɑːs(ə)n | \'fæsən/', 'fasten', 5);
INSERT INTO `words` VALUES (25535, 'Are you suggesting I’m too fat?', 'adj. 肥的，胖的；油腻的；丰满的; n. 脂肪，肥肉; v. 养肥；在…中加入脂肪', '/fæt/', 'fat', 5);
INSERT INTO `words` VALUES (25536, 'potentially fatal diseases', 'adj. 致命的；重大的；毁灭性的；命中注定的; n. (Fatal)人名；(葡、芬)法塔尔', '/\'feitl | \'feɪt(ə)l | \'fetl/', 'fatal', 5);
INSERT INTO `words` VALUES (25537, 'I wouldn’t wish such a fate on my worst enemy.', 'n. 命运; v. 注定', '/\'feit | feɪt | fet/', 'fate', 5);
INSERT INTO `words` VALUES (25538, '{\"COLLOINEXA\":[\"metal fatigue\"]}', 'n. 疲劳，疲乏；杂役; v. 使疲劳；使心智衰弱; adj. 疲劳的', '/fə\'ti:ɡ | fə\'tiːg | fə\'tig/', 'fatigue', 5);
INSERT INTO `words` VALUES (25539, 'Sara looked white and fatigued.', 'adj. 疲乏的', '/fə\'tiːgd | fə\'tiɡd/', 'fatigued', 5);
INSERT INTO `words` VALUES (25540, 'His worst fault is his arrogance.', 'n. 故障；[地质] 断层；错误；缺点；毛病；（网球等）发球失误; v. 弄错；产生断层', '/fɔ:lt | fɔːlt; fɒlt | fɔlt/', 'fault', 5);
INSERT INTO `words` VALUES (25541, 'Customers may ask for a refund if the goods are faulty.', 'adj. 有错误的；有缺点的', '/\'fɔ:lti | \'fɔːltɪ; \'fɒltɪ | \'fɔlti/', 'faulty', 5);
INSERT INTO `words` VALUES (25542, NULL, 'v. 赞成；喜欢；像；赐予；证实; n. 喜爱；欢心；好感', '/\'feivə | \'feɪvə | \'fevɚ/', 'favor', 5);
INSERT INTO `words` VALUES (25543, 'Thus, for example, we should expect to see consumers in a positive mood state evaluate products in more of a favorable manner than they would when not in such a state.', 'adj. 有利的；良好的；赞成的，赞许的；讨人喜欢的', '/\'feivərəbl | \'feɪvərəbl | \'fevərəbl/', 'favorable', 5);
INSERT INTO `words` VALUES (25544, 'This anemone is one of my favorite plants.', 'adj. 特别喜欢的， 中意的; n. 最喜欢的人或物', '/\'feɪvərɪt | \'fevərɪt/', 'favorite', 5);
INSERT INTO `words` VALUES (25545, 'favourable film reviews', 'adj. 赞许的； 有利的， 顺利的', '/\'feɪvərəbl | \'feivərəbl/', 'favourable', 5);
INSERT INTO `words` VALUES (25546, 'a child’s favourite toy', 'adj. 特别喜欢的， 中意的; n. 最喜欢的人或物', '/\'feɪvərɪt | \'fevərɪt/', 'favourite', 5);
INSERT INTO `words` VALUES (25547, 'I faxed a copy of the agreement to each of the investors.', 'v. 传真; n. 传真', '/fæks/', 'fax', 5);
INSERT INTO `words` VALUES (25548, 'a shy and fearful child', 'adj. 可怕的；担心的；严重的', '/\'fiəful | \'fɪəfʊl; -f(ə)l | \'fɪrfəl/', 'fearful', 5);
INSERT INTO `words` VALUES (25549, 'a feasible solution', 'adj. 可行的；可能的；可实行的', '/\'fi:zəbl | \'fiːzɪb(ə)l | \'fizəbl/', 'feasible', 5);
INSERT INTO `words` VALUES (25550, 'Only a few feet away, their captors feasted in the castle\'s banqueting hall.', 'v. 享受；款待，宴请; n. 筵席，宴会；节日', '/fi:st | fiːst | fist/', 'feast', 5);
INSERT INTO `words` VALUES (25551, 'A racing car is an extraordinary feat of engineering.', 'n. 功绩，壮举；技艺表演; adj. 合适的；灵巧的', '/fi:t | fiːt | fit/', 'feat', 5);
INSERT INTO `words` VALUES (25552, 'an ostrich feather', 'n. 羽毛; v. 用羽毛装饰', '/\'feðə | \'fɛðɚ/', 'feather', 5);
INSERT INTO `words` VALUES (25553, 'Air bags are a standard feature in most new cars.', 'n. 特色，特征；容貌；特写或专题节目; v. 起重要作用', '/\'fi:tʃə | \'fiːtʃə | \'fitʃɚ/', 'feature', 5);
INSERT INTO `words` VALUES (25554, 'He joined the Army in February 1943.', 'n. 二月', '/\'februəri | \'febrʊərɪ; \'febjʊərɪ | \'fɛbrʊ\'ɛri/', 'february', 5);
INSERT INTO `words` VALUES (25555, 'Switzerland is a federal republic.', 'adj. 联邦的；同盟的；联邦政府的； 联邦制的; adv. 联邦政府地; n. (Federal)人名；(英)费德勒尔', '/\'fed(ə)r(ə)l | \'fɛdərəl/', 'federal', 5);
INSERT INTO `words` VALUES (25556, 'the National Federation of Women’s Institutes', 'n. 联合；联邦；联盟；联邦政府', '/\'fedəreiʃən | fedə\'reɪʃ(ə)n | \'fɛdə\'reʃən/', 'federation', 5);
INSERT INTO `words` VALUES (25557, 'You can use the gym and pool for a fee of £35 a month.', 'n. 费用；酬金；小费; v. 付费给……', '/fi: | fiː | fi/', 'fee', 5);
INSERT INTO `words` VALUES (25558, 'His voice sounded feeble and far away.', 'adj. 微弱的，无力的；虚弱的；薄弱的', '/\'fi:bl | \'fiːb(ə)l | \'fibl/', 'feeble', 5);
INSERT INTO `words` VALUES (25559, 'Feed the tomatoes once a week.', 'v. 喂养；供给；放牧；抚养（家庭等）；靠…为生; n. 饲料；饲养；（动物或婴儿的）一餐', '/fi:d | fiːd | fid/', 'feed', 5);
INSERT INTO `words` VALUES (25560, 'How can I provide feedback without making someone angry?', 'n. 反馈；成果，资料；回复', '/\'fi:dbæk | \'fiːdbæk | \'fidbæk/', 'feedback', 5);
INSERT INTO `words` VALUES (25561, 'Knowing we’d won was a wonderful feeling.', 'n. 感觉，触觉；感情，情绪；同情; adj. 有感觉的；有同情心的；富于感情的; v. 感觉；认为（feel的现在分词）；触摸', '/\'fi:liŋ | \'fiːlɪŋ | \'filɪŋ/', 'feeling', 5);
INSERT INTO `words` VALUES (25562, 'More than 100 trees were felled in just over an hour.', 'adj. 凶猛的；毁灭性的; v. 砍伐；打倒；击倒; n. [林] 一季所伐的木材；折缝；兽皮', '/fel | fɛl/', 'fell', 5);
INSERT INTO `words` VALUES (25563, 'Paul’s an easy-going sort of fellow.', 'n. 人,家伙;伙伴,同事; adj. 同样的,同事的', '/\'feləu | \'feləʊ | \'fɛlo/', 'fellow', 5);
INSERT INTO `words` VALUES (25564, '...the National Schizophrenia Fellowship.', 'n. 伙伴关系;联谊会,团体', '/\'felə(ʊ)ʃɪp | \'fɛloʃɪp/', 'fellowship', 5);
INSERT INTO `words` VALUES (25565, 'female voters', 'adj. 女性的；雌性的；柔弱的，柔和的; n. 女人；[动] 雌性动物', '/\'fi:meil | \'fiːmeɪl | \'fimel/', 'female', 5);
INSERT INTO `words` VALUES (25566, 'Dianne loved pretty feminine things.', 'adj. 女性的；妇女（似）的；阴性的；娇柔的', '/\'feminin | \'femɪnɪn | \'fɛmənɪn/', 'feminine', 5);
INSERT INTO `words` VALUES (25567, 'Villagers say the fence would restrict public access to the hills.', 'n. 栅栏；围墙；剑术; v. 防护；用篱笆围住；练习剑术', '/\'fens | fens | fɛns/', 'fence', 5);
INSERT INTO `words` VALUES (25568, 'They had recrossed the River Gambia by ferry.', 'n. 渡船；摆渡；渡口; v. （乘渡船）渡过；用渡船运送；空运', '/\'feri | \'ferɪ | \'fɛri/', 'ferry', 5);
INSERT INTO `words` VALUES (25569, '800 acres of fertile cropland', 'adj. 富饶的，肥沃的；能生育的', '/\'fɜːtaɪl | ˈfɝtəl; (canadian) ˈfɝˌtaɪl/', 'fertile', 5);
INSERT INTO `words` VALUES (25570, 'Why do Americans spend such huge amounts of time, money, water, fertiliser and fuel on growing a useless smooth expanse of grass?', 'n. 肥料', '/\'fɜːtəlaɪzə | \'fə:tilaisə/', 'fertiliser', 5);
INSERT INTO `words` VALUES (25571, '...farming without any purchased chemical, fertilizer or pesticide.', 'n. [肥料] 肥料；受精媒介物；促进发展者', '/\'fə:tilaizə | \'fɜːtɪlaɪzə | \'fɝtəlaɪzɚ/', 'fertilizer', 5);
INSERT INTO `words` VALUES (25572, 'Christmas is one of the main festivals in the Christian Calendar.', 'n. 节日；庆祝，纪念活动；欢乐; adj. 节日的，喜庆的；快乐的', '/\'festəvəl | \'festɪv(ə)l | ˈfɛstəvəl/', 'festival', 5);
INSERT INTO `words` VALUES (25573, 'the feudal system', 'adj. 封建制度的；领地的；世仇的', '/\'fju:dl | \'fjuːd(ə)l | \'fjudl/', 'feudal', 5);
INSERT INTO `words` VALUES (25574, 'Andy has a fever and won’t be coming into work today.', 'n. 发烧，发热；狂热; vt. 使发烧；使狂热；使患热病; vi. 发烧；狂热；患热病', '/\'fi:və | \'fiːvə | \'fivɚ/', 'fever', 5);
INSERT INTO `words` VALUES (25575, 'And remember nuts like almonds with their skins on have more fiber than those without.', 'n. 纤维；光纤（等于fibre）', '/\'faibə | \'faɪbɚ/', 'fiber', 5);
INSERT INTO `words` VALUES (25576, 'Fruit and vegetables are high in fibre content .', 'n. 纤维， 纤维质', '/\'faɪbə | \'faibə/', 'fibre', 5);
INSERT INTO `words` VALUES (25577, 'romantic fiction', 'n. 虚构,编造;小说', '/\'fikʃən | \'fɪkʃ(ə)n | \'fɪkʃən/', 'fiction', 5);
INSERT INTO `words` VALUES (25578, 'fierce fighting in the city', 'adj. 凶猛的,残忍的;狂热的,强烈的', '/fiəs | fɪəs | fɪrs/', 'fierce', 5);
INSERT INTO `words` VALUES (25579, 'Standards of living rose in the fifties.', 'n. 五十；五十个；编号为50的东西; adj. 五十的；五十个的；众多的', '/\'fifti | \'fɪftɪ | \'fɪfti/', 'fifty', 5);
INSERT INTO `words` VALUES (25580, 'Neither country is capable of fighting a long war .', 'v. 打架；与…打仗，与…斗争；反对…提案; n. 打架；战斗，斗志', '/fait | faɪt/', 'fight', 5);
INSERT INTO `words` VALUES (25581, 'A hexagon is a six-sided figure.', 'n. 数字；人物；图形；价格；（人的）体形；画像; v. 计算；出现；扮演角色', '/\'fiɡə | \'fɪgə | \'fɪɡjɚ/', 'figure', 5);
INSERT INTO `words` VALUES (25582, 'We will keep your details on file (= store them for later use ) .', 'n. 文件；档案；文件夹；锉刀; v. 提出；锉；琢磨；把…归档', '/faɪl/', 'file', 5);
INSERT INTO `words` VALUES (25583, 'Have you seen any good films recently?', 'n. 电影；薄膜；胶卷；轻烟; v. 在…上覆以薄膜；把…拍成电影', '/film | fɪlm/', 'film', 5);
INSERT INTO `words` VALUES (25584, 'The water in the tank is constantly filtered.', 'v. 滤过；渗入；慢慢传开; n. 滤波器；[化工] 过滤器；筛选；滤光器', '/filtə | \'fɪltə | \'fɪltɚ/', 'filter', 5);
INSERT INTO `words` VALUES (25585, NULL, 'n. 鱼鳍；鳍状物；尾翅；散热片', '/fin | fɪn/', 'fin', 5);
INSERT INTO `words` VALUES (25586, 'The final episode will be shown tonight.', 'adj. 最终的,决定性的; n. 结局;决赛;期末考试', '/\'fainl | \'faɪn(ə)l | \'faɪnl/', 'final', 5);
INSERT INTO `words` VALUES (25587, 'After several delays we finally took off at six o’clock.', 'adv. 最后,最终;决定性地', '/\'fainəli | \'faɪnəlɪ | \'faɪnəli/', 'finally', 5);
INSERT INTO `words` VALUES (25588, 'leasing and other forms of business finance', 'n. 财政,金融; v. 为…提供资金', '/fai\'næns | faɪ\'næns; fɪ-; \'faɪnæns | \'faɪnæns/', 'finance', 5);
INSERT INTO `words` VALUES (25589, 'financial transactions', 'adj. 财政的,金融的', '/fai\'nænʃəl | faɪ\'nænʃ(ə)l; fɪ- | faɪ\'nænʃl/', 'financial', 5);
INSERT INTO `words` VALUES (25590, 'Surveys conducted in other countries reported similar findings.', 'n. 发现；裁决；发现物; v. 找到；感到（find的ing形式）；遇到', '/\'faindiŋ | \'faɪndɪŋ/', 'finding', 5);
INSERT INTO `words` VALUES (25591, 'If it’s fine tomorrow we’ll go out.', 'adj. 晴朗的,美好的,细致的; v&n. 罚金,罚款', '/fain | faɪn/', 'fine', 5);
INSERT INTO `words` VALUES (25592, 'The woman had a ring on her finger, so I assumed she was married.', 'n. 手指;指状物;指针', '/\'fiŋɡə | \'fɪŋgə | \'fɪŋɡɚ/', 'finger', 5);
INSERT INTO `words` VALUES (25593, 'That table has a beautiful finish.', 'n. 完成;结束;磨光; v. 完成;结束;用完;毁掉', '/\'finiʃ | \'fɪnɪʃ/', 'finish', 5);
INSERT INTO `words` VALUES (25594, 'the earth’s finite resources', 'adj. 有限的；[数]有穷的,限定的', '/\'fainait | \'faɪnaɪt/', 'finite', 5);
INSERT INTO `words` VALUES (25595, 'Would you like to be a fireman?', 'n. 消防队员', '/\'faiəmən | \'faɪəmən | \'faɪrmən/', 'fireman', 5);
INSERT INTO `words` VALUES (25596, 'In the evenings, we gathered around the fireplace and talked in hushed whispers.', 'n. 壁炉', '/\'faiəpleis | \'faɪəpleɪs | \'faɪɚples/', 'fireplace', 5);
INSERT INTO `words` VALUES (25597, 'The sofa cushions are fairly firm.', 'adj. 坚定的；牢固的；严格的；结实的; v. 使坚定；使牢固; adv. 稳固地; n. 公司；商号', '/\'fə:m | fɜːm | fɝm/', 'firm', 5);
INSERT INTO `words` VALUES (25598, 'a fiscal crisis', 'adj. 财政的， 国库的', '/\'fɪskl/', 'fiscal', 5);
INSERT INTO `words` VALUES (25599, 'But there was a price below which they dared not go, for it had happened that a fisherman in despair had given his pearls to the church.', 'n. 渔夫，捕鱼人', '/\'fiʃəmən | \'fɪʃəmən | \'fɪʃɚmən/', 'fisherman', 5);
INSERT INTO `words` VALUES (25600, 'She held the money tightly in her fist.', 'n. 拳，拳头；〈口〉笔迹；掌握；[印]指标参见号; vt. 紧握；握成拳；用拳打', '/fɪst/', 'fist', 5);
INSERT INTO `words` VALUES (25601, 'a sink with chrome fittings (= handle and taps )', 'n. 装配，装置；试穿，试衣; adj. 适合的，适宜的；相称的', '/\'fitiŋ | \'fɪtɪŋ/', 'fitting', 5);
INSERT INTO `words` VALUES (25602, 'He’s outside fixing the brakes on the car.', 'v. 使固定；修理；安装；准备; n. 困境；方位；贿赂', '/fiks | fɪks/', 'fix', 5);
INSERT INTO `words` VALUES (25603, 'light fixtures', 'n. 设备；固定装置；固定于某处不大可能移动之物', '/\'fikstʃə | \'fɪkstʃə; -tjə | \'fɪkstʃɚ/', 'fixture', 5);
INSERT INTO `words` VALUES (25604, 'His enthusiasm was in no way flagging.', 'v. 标记；衰退；枯萎; n. 标志；旗子', '/flæɡ | flæg/', 'flag', 5);
INSERT INTO `words` VALUES (25605, 'A great fire flamed in an open fireplace.', 'vi. 发火焰， 燃烧 A; n. 火焰， 火苗；热情；光辉', '/fleɪm | flem/', 'flame', 5);
INSERT INTO `words` VALUES (25606, 'the flap of the sails', 'n. 拍打，拍打声；神经紧张；[航] 襟翼; v. 拍动；神经紧张；鼓翼而飞；（帽边等）垂下', '/flæp/', 'flap', 5);
INSERT INTO `words` VALUES (25607, 'Tempers flared and harsh words were exchanged.', 'v. 使闪耀；使张开；用发光信号发出；使外倾; n. 加剧，恶化；底部展开；（鼻孔）张开的意思；闪光，闪耀；耀斑；爆发；照明弹', '/fleə | flɛr/', 'flare', 5);
INSERT INTO `words` VALUES (25608, 'Lightning flashed overhead.', 'v. 使闪光；反射; n. 闪光，闪现；一瞬间; adj. 闪光的，火速的', '/flæʃ/', 'flash', 5);
INSERT INTO `words` VALUES (25609, 'houses with flat roofs', 'adj. 平的；单调的；不景气的；干脆的；平坦的；扁平的；浅的; adv. （尤指贴着另一表面）平直地；断然地；水平地；直接地，完全地; n. 平地；公寓；平面; vt. 使变平；[音乐]使（音调）下降，尤指降半音; vi. 逐渐变平；[音乐]以降调唱（或奏）', '/flæt/', 'flat', 5);
INSERT INTO `words` VALUES (25610, 'Perry would always flatter Mrs. Mitchell by praising her cooking.', 'v. 奉承；谄媚；使高兴', '/\'flætə | \'flætɚ/', 'flatter', 5);
INSERT INTO `words` VALUES (25611, NULL, 'n. 情味，风味；香料；滋味; v. 加味于', '/\'fleivə | \'fleɪvə | \'flevɚ/', 'flavor', 5);
INSERT INTO `words` VALUES (25612, 'A design flaw (= a mistake or weakness in the way something was made ) caused the engine to explode.', 'n. 瑕疵，缺点；一阵狂风；短暂的风暴；裂缝，裂纹; v. 使生裂缝，使有裂纹；使无效；使有缺陷', '/flɔː | flɔ/', 'flaw', 5);
INSERT INTO `words` VALUES (25613, 'His attackers turned and fled.', 'v. 逃走；消失，消散', '/fli: | fliː | fli/', 'flee', 5);
INSERT INTO `words` VALUES (25614, 'Atalanta was fleet of foot (= able to run quickly ) .', 'adj. 快速的，敏捷的; n. 舰队；港湾；小河; v. 飞逝；疾驰；掠过', '/fli:t | fliːt | flit/', 'fleet', 5);
INSERT INTO `words` VALUES (25615, 'a freshwater fish with firm white flesh', 'n. 肉；肉体; v. 喂肉给…；使发胖', '/fleʃ | flɛʃ/', 'flesh', 5);
INSERT INTO `words` VALUES (25616, 'We can be flexible about your starting date.', 'adj. 灵活的；柔韧的；易弯曲的', '/\'fleksibl | \'fleksɪb(ə)l | \'flɛksəbl/', 'flexible', 5);
INSERT INTO `words` VALUES (25617, 'He immediately booked a flight to Toulouse.', 'n. 飞行；班机；逃走; v. 射击；使惊飞', '/flait | flaɪt/', 'flight', 5);
INSERT INTO `words` VALUES (25618, 'He flung his coat over the back of a chair.', 'v. 掷，抛；嘲笑；使陷入；轻蔑地投射；猛动; n. 掷，抛；嘲弄；急冲', '/fliŋ | flɪŋ/', 'fling', 5);
INSERT INTO `words` VALUES (25619, 'I looked up at the clouds floating in the sky.', 'v. 使漂浮；实行; n. 彩车，花车；漂流物；浮舟；浮萍', '/fləut | fləʊt | flot/', 'float', 5);
INSERT INTO `words` VALUES (25620, 'They kept a small flock of sheep.', 'n. 群；棉束（等于floc）; v. 用棉束填满', '/flɔk | flɒk | flɑk/', 'flock', 5);
INSERT INTO `words` VALUES (25621, 'Towns and cities all over the country have been flooded.', 'v. 淹没；充满；溢出; n. 洪水；泛滥；一大批', '/flʌd/', 'flood', 5);
INSERT INTO `words` VALUES (25622, 'a polished wooden floor', 'n. 地板，地面；楼层；基底；议员席; v. 铺地板；打倒，击倒；（被困难）难倒', '/flɔ: | flɔː | flɔr/', 'floor', 5);
INSERT INTO `words` VALUES (25623, 'Roll the pastry out on a lightly floured board.', 'n. 面粉；粉状物质; v. 撒粉于；把…磨成粉', '/\'flauə | \'flaʊə | \'flaʊɚ/', 'flour', 5);
INSERT INTO `words` VALUES (25624, 'The economy is booming and small businesses are flourishing.', 'vi. 繁荣， 茂盛； 兴旺', '/\'flʌrɪʃ | ˈflɜːrɪʃ/', 'flourish', 5);
INSERT INTO `words` VALUES (25625, 'Money has been flowing into the country from Western aid agencies.', 'v. 流动，涌流；川流不息；飘扬; n. 流动；流量；涨潮，泛滥', '/fləu | fləʊ | flo/', 'flow', 5);
INSERT INTO `words` VALUES (25626, 'Steven’s still in bed with flu .', 'n. 流感', '/flu: | fluː | flu/', 'flu', 5);
INSERT INTO `words` VALUES (25627, 'Insect populations fluctuate wildly from year to year.', 'v. 波动；涨落；动摇', '/\'flʌktjueit | \'flʌktʃʊeɪt; -tjʊ- | \'flʌktʃʊ\'et/', 'fluctuate', 5);
INSERT INTO `words` VALUES (25628, 'He spoke in fluent Italian.', 'adj. 流畅的，流利的；液态的；畅流的', '/\'flu(:)ənt | \'fluːənt | \'fluənt/', 'fluent', 5);
INSERT INTO `words` VALUES (25629, 'a loose, fluid style of dancing', 'adj. 流动的；流畅的；不固定的; n. 流体；液体', '/\'flu(:)id | \'fluːɪd | \'fluɪd/', 'fluid', 5);
INSERT INTO `words` VALUES (25630, 'There was a slight flush on his cheeks.', 'n. 激动，洋溢；面红；萌芽；旺盛；奔流; v. 使齐平；发红，使发亮；用水冲洗；使激动; adj. 大量的；齐平的；丰足的，洋溢的；挥霍的', '/flʌʃ/', 'flush', 5);
INSERT INTO `words` VALUES (25631, 'a foam mattress', 'n. 泡沫；水沫；灭火泡沫; v. 起泡沫；吐白沫；起着泡沫流动', '/fəum | fəʊm | fom/', 'foam', 5);
INSERT INTO `words` VALUES (25632, 'The focus of recent research has been on environmental issues.', 'n. 焦点；中心；清晰；焦距; v. 使集中；使聚焦', '/\'fəukəs | \'fəʊkəs | \'fokəs/', 'focus', 5);
INSERT INTO `words` VALUES (25633, 'It will be a cold night, and there may be fog patches .', 'n. 雾；烟雾，尘雾；迷惑; v. 使模糊；使困惑；以雾笼罩', '/fɔɡ | fɒg/', 'fog', 5);
INSERT INTO `words` VALUES (25634, 'Fold the paper along the dotted line.', 'v. 折叠；合拢；抱住；笼罩; n. 折痕；信徒；羊栏', '/fəuld | fəʊld | fold/', 'fold', 5);
INSERT INTO `words` VALUES (25635, 'I’m sure there are some folk who would rather they weren’t here.', 'n. 民族；人们；亲属（复数）; adj. 民间的', '/fəuk | fəʊk | fok/', 'folk', 5);
INSERT INTO `words` VALUES (25636, 'Are those men following us?', 'v. 跟随,接着;领会;沿着…前进,遵循;结果是', '/\'fɔləu | \'fɒləʊ | \'fɑlo/', 'follow', 5);
INSERT INTO `words` VALUES (25637, 'The following day the picture appeared on the front pages of every newspaper in the world.', 'adj. 下列的，下述的，其次的，接着的', '/\'fɔləuiŋ | \'fɒləʊɪŋ | \'fɑloɪŋ/', 'following', 5);
INSERT INTO `words` VALUES (25638, 'Joe’s quite fond of her, isn’t he?', 'adj. 喜欢的；温柔的；宠爱的; n. (Fond)人名；(法)丰；(瑞典)丰德', '/fɔnd | fɒnd | fɑnd/', 'fond', 5);
INSERT INTO `words` VALUES (25639, 'Even art experts were fooled.', 'v. 欺骗；开玩笑；戏弄; n. 傻瓜；愚人；受骗者; adj. 傻的', '/fu:l | fuːl | ful/', 'fool', 5);
INSERT INTO `words` VALUES (25640, 'I’ve never heard anything so foolish in all my life.', 'adj. 愚蠢的；傻的', '/\'fu:liʃ | \'fuːlɪʃ | \'fulɪʃ/', 'foolish', 5);
INSERT INTO `words` VALUES (25641, 'My foot hurts.', 'n. 脚；英尺；步调；末尾; v. 步行；跳舞；总计', '/fut | fʊt/', 'foot', 5);
INSERT INTO `words` VALUES (25642, 'Which football team do you support?', 'n. 足球，橄榄球; vi. 踢足球；打橄榄球', '/\'fut,bɔ:l | \'fʊtbɔːl | \'fʊtbɔl/', 'football', 5);
INSERT INTO `words` VALUES (25643, 'He heard someone’s footsteps in the hall.', 'n. 脚步；脚步声；足迹', '/\'fut\'step | \'fʊtstep | \'fʊtstɛp/', 'footstep', 5);
INSERT INTO `words` VALUES (25644, 'Lack of space forbids listing the names of all those who contributed.', 'v. 禁止；不准；不允许；〈正式〉严禁', '/fə\'bɪd | fɚ\'bɪd/', 'forbid', 5);
INSERT INTO `words` VALUES (25645, 'Peace cannot be imposed by force .', 'n. 力量；武力；军队；魄力; v. 促使，推动；强迫；强加', '/fɔ:s | fɔːs | fɔrs/', 'force', 5);
INSERT INTO `words` VALUES (25646, 'There had been no direct damage in the fore part of the ship.', 'adj. 以前的；在前部的; n. 前部；船头; adv. 在前面；在船头; prep. 在前; int. （打高尔夫球者的叫声）让开！', '/fɔ: | fɔː | fɔr/', 'fore', 5);
INSERT INTO `words` VALUES (25647, 'Rain was forecast for the weekend.', 'v. 预报，预测；预示; n. 预测，预报；预想', '/\'fɔ:kɑ:st | \'fɔːkɑːst | \'fɔrkæst/', 'forecast', 5);
INSERT INTO `words` VALUES (25648, '...the lines on her forehead.', 'n. 额，前额', '/\'fɔːhed | \'fɔːhed; \'fɒrɪd | \'fɔr\'hɛd/', 'forehead', 5);
INSERT INTO `words` VALUES (25649, 'foreign students', 'adj. 外国的；外交的；异质的；不相关的', '/\'fɔrin | \'fɒrɪn | \'fɔrən/', 'foreign', 5);
INSERT INTO `words` VALUES (25650, 'Some of the local people are suspicious of foreigners.', 'n. 外地人，外国人', '/\'fɔrinə | \'fɒrɪnə | \'fɔrənɚ/', 'foreigner', 5);
INSERT INTO `words` VALUES (25651, 'one of the country’s foremost authorities on chemical warfare', 'adj. 最重要的；最先的; adv. 首先；居于首位地', '/\'fɔ:məust | \'fɔːməʊst | \'fɔr\'most/', 'foremost', 5);
INSERT INTO `words` VALUES (25652, 'I’ve put your name on the list and I don’t foresee any problems.', 'v. 预见；预知', '/fɔ:\'si: | fɔː\'siː | fɔr\'si/', 'foresee', 5);
INSERT INTO `words` VALUES (25653, 'a tropical forest', 'v. 植树于，使成为森林; n. 森林', '/\'fɔrist | \'fɒrɪst | \'fɔrɪst/', 'forest', 5);
INSERT INTO `words` VALUES (25654, 'I wanted that moment to last forever .', 'adv. 永远；不断地；常常', '/fə\'revə | fɚ\'ɛvɚ/', 'forever', 5);
INSERT INTO `words` VALUES (25655, 'Someone stole my credit card and forged my signature.', 'n. 熔炉，锻铁炉；铁工厂; v. 伪造；做锻工；前进', '/fɔ:dʒ | fɔːdʒ | fɔrdʒ/', 'forge', 5);
INSERT INTO `words` VALUES (25656, 'I’m sorry, I’ve forgotten your name.', 'v. 忘记；忽略; n. (Forget)人名；(法)福尔热', '/fə\'gɛt | fə\'get | fɚ\'ɡɛt/', 'forget', 5);
INSERT INTO `words` VALUES (25657, 'He didn’t look the sort of man to forgive and forget (= forgive someone and no longer think about it ) .', 'v. 原谅；免除（债务、义务等）', '/fə\'ɡiv | fə\'gɪv | fɚ\'ɡɪv/', 'forgive', 5);
INSERT INTO `words` VALUES (25658, 'Put the knives and forks on the table.', 'n. 叉；餐叉；耙; v. 叉起；使成叉状', '/fɔ:k | fɔːk | fɔrk/', 'fork', 5);
INSERT INTO `words` VALUES (25659, 'We oppose racism in all its forms.', 'n. 形状,形式;表格; v. 组成,构成;形成', '/fɔ:m | fɔːm | fɔrm/', 'form', 5);
INSERT INTO `words` VALUES (25660, 'formal recognition of the reformed church', 'adj. 正式的;形式的', '/\'fɔ:məl | \'fɔːm(ə)l | \'fɔrml/', 'formal', 5);
INSERT INTO `words` VALUES (25661, 'a large-format book for the partially-sighted', 'n. (出版物的)开本,版式,格式; v. 设计;安排', '/\'fɔ:mæt | \'fɔːmæt | \'fɔrmæt/', 'format', 5);
INSERT INTO `words` VALUES (25662, 'We now know a lot more about the early stages of planetary formation.', 'n. 形成;构成;组织;构造;编制;塑造', '/fɔ:\'meiʃən | fɔː\'meɪʃ(ə)n | fɔr\'meʃən/', 'formation', 5);
INSERT INTO `words` VALUES (25663, 'the former Soviet Union', 'adj. 以前的,在前的; pron. 前者', '/\'fɔ:mə | \'fɔːmə | \'fɔrmɚ/', 'former', 5);
INSERT INTO `words` VALUES (25664, 'The building is grey, formidable, not at all picturesque.', 'adj. 强大的;令人敬畏的;可怕的;艰难的', '/\'fɔ:midəbl | \'fɔːmɪdəb(ə)l; fɔː\'mɪd- | \'fɔrmɪdəbl/', 'formidable', 5);
INSERT INTO `words` VALUES (25665, 'We’re still searching for a peace formula.', 'n. (pl.e)公式;规则;分子式;药方', '/\'fɔ:mjulə | \'fɔːmjʊlə | \'fɔrmjələ/', 'formula', 5);
INSERT INTO `words` VALUES (25666, 'Little by little, he formulated his plan for escape.', 'v. 用公式表示;规划;设计;系统地阐述', '/\'fɔ:mjuleit | \'fɔːmjʊleɪt | \'fɔrmjə\'let/', 'formulate', 5);
INSERT INTO `words` VALUES (25667, 'The house was still burning, pouring forth thick black smoke.', 'adv. 向前； 向外', '/fɔːθ | fɔrθ/', 'forth', 5);
INSERT INTO `words` VALUES (25668, 'the forthcoming elections', 'adj. 即将来临的; n. 来临', '/\'fɔ:θ\'kʌmiŋ | fɔːθ\'kʌmɪŋ | ,fɔrθ\'kʌmɪŋ/', 'forthcoming', 5);
INSERT INTO `words` VALUES (25669, 'a fortnight’s holiday', 'n. 两星期', '/\'fɔ:tnait | \'fɔːtnaɪt | \'fɔrtnaɪt/', 'fortnight', 5);
INSERT INTO `words` VALUES (25670, 'I had the good fortune to work with a brilliant head of department.', 'n. 财富；命运；运气; vt. 给予财富; vi. 偶然发生', '/\'fɔ:tʃən, -tʃu:n | \'fɔːtʃuːn; -tʃ(ə)n | \'fɔrtʃən/', 'fortune', 5);
INSERT INTO `words` VALUES (25671, 'Members of the council agreed that was an important forum for discussion.', 'n. 论坛，讨论会；法庭；公开讨论的广场', '/\'fɔ:rəm | \'fɔːrəm | \'fɔrəm/', 'forum', 5);
INSERT INTO `words` VALUES (25672, 'Army roadblocks prevented any further forward movement .', 'adj. 向前的；早的；迅速的; adv. 向前地；向将来; v. 促进；转寄；运送; n. 前锋', '/\'fɔ:wəd | \'fɔːwəd | \'fɔrwɚd/', 'forward', 5);
INSERT INTO `words` VALUES (25673, 'fossils of early reptiles', 'n. 化石；僵化的事物；顽固不化的人; adj. 化石的；陈腐的，守旧的', '/\'fɔsəl | \'fɒs(ə)l; -sɪl | \'fɑsl/', 'fossil', 5);
INSERT INTO `words` VALUES (25674, 'The bishop helped foster the sense of a community embracing all classes.', 'v. 培养；养育，抚育；抱（希望等）; adj. 收养的，养育的; n. (Foster)人名；(英、捷、意、葡、法、德、俄、西)福斯特', '/\'fɔstə | \'fɒstə | \'fɔstɚ/', 'foster', 5);
INSERT INTO `words` VALUES (25675, 'Refugees in the camps are short of food and at risk from foul water.', 'adj. 犯规的；邪恶的；污秽的；淤塞的; v. 犯规；弄脏；淤塞；缠住，妨害; n. 犯规；缠绕; adv. 违反规则地，不正当地', '/faul | faʊl/', 'foul', 5);
INSERT INTO `words` VALUES (25676, 'It took the builders three weeks to lay the foundations .', 'n. 基础；地基；基金会；根据；创立', '/faun\'deiʃən | faʊn\'deɪʃ(ə)n | faʊn\'deʃən/', 'foundation', 5);
INSERT INTO `words` VALUES (25677, 'He was a fountain of information on Asian affairs.', 'n. 喷泉，泉水；源泉', '/\'fauntin | ˈfaʊntən | \'faʊntn/', 'fountain', 5);
INSERT INTO `words` VALUES (25678, 'He used to work fourteen hours a day.', 'num. 十四；十四个；第十四; n. 十四的记号；十四岁；十四点钟；十五世纪', '/fɔː\'tiːn; \'fɔːtiːn | ,fɔr\'tin/', 'fourteen', 5);
INSERT INTO `words` VALUES (25679, 'The students had a grasp of decimals, percentages and fractions.', 'n. 碎片,小部分,一点儿;分数', '/\'frækʃən | \'frækʃ(ə)n/', 'fraction', 5);
INSERT INTO `words` VALUES (25680, 'a stress fracture in his left knee', 'n. 裂缝(痕);骨折; v. (使)断裂,(使)折断', '/\'fræktʃə | \'fræktʃɚ/', 'fracture', 5);
INSERT INTO `words` VALUES (25681, 'Be careful with that vase – it’s very fragile.', 'adj. 易碎的，脆的，易损坏的；虚弱的，脆弱的', '/\'frædʒail | \'frædʒaɪl | \'frædʒəl/', 'fragile', 5);
INSERT INTO `words` VALUES (25682, 'glass fragments', 'n. 碎片,小部分,片断', '/\'fræɡmənt | \'frægm(ə)nt/', 'fragment', 5);
INSERT INTO `words` VALUES (25683, 'fragrant flowers', 'adj. 香的;芬芳的', '/\'freiɡrənt | \'freɪgr(ə)nt | \'fregrənt/', 'fragrant', 5);
INSERT INTO `words` VALUES (25684, 'They removed the picture from its wooden frame.', 'n. 框架；结构；[电影] 画面; v. 设计；建造；陷害；使…适合; adj. 有木架的；有构架的', '/freim | freɪm | frem/', 'frame', 5);
INSERT INTO `words` VALUES (25685, 'We have to act within the existing legal framework.', 'n. 框架，骨架；结构，构架', '/\'freimwə:k | \'freɪmwɜːk | \'fremwɝk/', 'framework', 5);
INSERT INTO `words` VALUES (25686, '...fast-food franchises.', 'n. 特许权；选举权；经销权; vt. 特许', '/\'fræntʃaɪz/', 'franchise', 5);
INSERT INTO `words` VALUES (25687, 'To be perfectly frank, I think it’s a bad idea.', 'adj. 坦白的，直率的；老实的; n. 免费邮寄特权; v. 免费邮寄', '/fræŋk/', 'frank', 5);
INSERT INTO `words` VALUES (25688, '{\"COLLOINEXA\":[\"electoral fraud\"]}', 'n. 欺骗；骗子；诡计', '/frɔ:d | frɔːd | frɔd/', 'fraud', 5);
INSERT INTO `words` VALUES (25689, 'People here like their freedom and privacy.', 'n. 自由，自主；直率', '/\'fri:dəm | \'friːdəm | \'fridəm/', 'freedom', 5);
INSERT INTO `words` VALUES (25690, 'She works freelance from home.', 'adj. 自由职业的', '/\'friːlɑːns | \'frilæns/', 'freelance', 5);
INSERT INTO `words` VALUES (25691, 'The lake had frozen overnight.', 'v. 冻结；冷冻；僵硬; n. 冻结；凝固', '/fri:z | friːz | friz/', 'freeze', 5);
INSERT INTO `words` VALUES (25692, 'freight services', 'v. 运送；装货；使充满; n. 货运；运费；船货', '/freit | freɪt | fret/', 'freight', 5);
INSERT INTO `words` VALUES (25693, 'Side effects from prescribed drugs are being reported with increasing frequency (= more and more often ) .', 'n. 频率；频繁', '/\'frikwənsi | \'friːkw(ə)nsɪ/', 'frequency', 5);
INSERT INTO `words` VALUES (25694, 'Trains rushed past at frequent intervals .', 'adj. 频繁的；时常发生的；惯常的; v. 常到，常去；时常出入于', '/\'fri:kwənt, fri\'kwent | \'friːkw(ə)nt | \'frikwənt/', 'frequent', 5);
INSERT INTO `words` VALUES (25695, 'I’ll just make some fresh coffee.', 'adj. 新鲜的；清新的；淡水的；无经验的; n. 开始；新生；泛滥; adv. 刚刚，才；最新地', '/freʃ | frɛʃ/', 'fresh', 5);
INSERT INTO `words` VALUES (25696, 'Putting oil on both surfaces reduces friction.', 'n. 摩擦，[力] 摩擦力', '/\'frikʃən | \'frɪkʃ(ə)n | \'frɪkʃən/', 'friction', 5);
INSERT INTO `words` VALUES (25697, 'Mr. Cook is intending to go to the Middle East on Friday.', 'n. 星期五；忠仆', '/\'fraidi | ˈfraɪde; (occas.,) ˈfraɪdi/', 'friday', 5);
INSERT INTO `words` VALUES (25698, 'Then all three of you sign the contract and post in on the fridge.', 'n. 电冰箱', '/fridʒ | frɪdʒ/', 'fridge', 5);
INSERT INTO `words` VALUES (25699, 'a friendly smile', 'adj. 友好的；亲切的；支持的；融洽的，和睦的; adv. 友善地；温和地; n. (Friendly)人名；(英)弗兰德利', '/\'frendli | \'fren(d)lɪ | \'frɛndli/', 'friendly', 5);
INSERT INTO `words` VALUES (25700, 'her close friendship with her aunt', 'n. 友谊；友爱；友善', '/\'frendʃip | \'fren(d)ʃɪp | \'frɛndʃɪp/', 'friendship', 5);
INSERT INTO `words` VALUES (25701, 'You gave me such a fright creeping up on me like that!', 'n. 惊吓；惊骇; v. 使惊恐', '/frait | fraɪt/', 'fright', 5);
INSERT INTO `words` VALUES (25702, 'Don’t stand so near the edge! You’re frightening me.', 'v. 使惊吓；吓唬…', '/\'fraitən | \'fraɪt(ə)n | \'fraɪtn/', 'frighten', 5);
INSERT INTO `words` VALUES (25703, 'a tall girl with straight brown hair and a fringe', 'n. 边缘；穗；刘海; adj. 边缘的；附加的; v. 加穗于', '/frindʒ | frɪn(d)ʒ | frɪndʒ/', 'fringe', 5);
INSERT INTO `words` VALUES (25704, 'The tadpole has become a frog.', 'n. 青蛙；[铁路] 辙叉；饰扣; v. 捕蛙', '/frɔɡ | frɒg/', 'frog', 5);
INSERT INTO `words` VALUES (25705, 'a novel about a family’s struggle on the American frontier', 'n. 前沿；边界；国境; adj. 边界的；开拓的', '/\'frʌntjə | \'frʌntɪə; frʌn\'tɪə | frʌn\'tɪr/', 'frontier', 5);
INSERT INTO `words` VALUES (25706, 'These seedlings were killed off by the severe frost.', 'v. 结霜于；冻坏; n. 霜；冰冻，严寒；冷淡', '/frɔst | frɒst/', 'frost', 5);
INSERT INTO `words` VALUES (25707, 'She frowned as she read the letter.', 'v. 皱眉；不同意; n. 皱眉，蹙额', '/fraun | fraʊn/', 'frown', 5);
INSERT INTO `words` VALUES (25708, 'Try to eat plenty of fresh fruit .', 'n. 水果；产物; v. 结果实', '/fru:t | fruːt | frut/', 'fruit', 5);
INSERT INTO `words` VALUES (25709, 'Today’s meeting proved more fruitful than last week’s.', 'adj. 富有成效的；多产的；果实结得多的', '/\'fru:tful | \'fruːtfʊl; -f(ə)l | \'frutfl/', 'fruitful', 5);
INSERT INTO `words` VALUES (25710, 'Their attempts to speak to him were frustrated by the guards.', 'v. 挫败；阻挠；使感到灰心; adj. 挫败的；无益的', '/frʌs\'treit | frʌ\'streɪt; \'frʌs- | \'frʌstret/', 'frustrate', 5);
INSERT INTO `words` VALUES (25711, 'So when you fry, bake, grill, or roast potatoes you could be generating potentially harmful carcinogens.', 'n. 鱼苗；油炸食物; v. 油炸；油煎', '/frai | fraɪ/', 'fry', 5);
INSERT INTO `words` VALUES (25712, 'We’d better fuel up at the next town.', 'v. 得到燃料; n. 燃料；刺激因素', '/\'fjuəl | fjʊəl/', 'fuel', 5);
INSERT INTO `words` VALUES (25713, 'Visiting Disneyland has fulfilled a boyhood dream .', 'vt. 完成； 实现， 履行； 符合', '/ful\'fɪl | ful\'fil/', 'fulfil', 5);
INSERT INTO `words` VALUES (25714, NULL, 'v. 履行；实现；满足；使结束（等于fulfil）', '/ful\'fil/', 'fulfill', 5);
INSERT INTO `words` VALUES (25715, '...car exhaust fumes.', 'v. 冒烟；发怒; n. 烟；愤怒，烦恼', '/fju:m | fjuːm | fjum/', 'fume', 5);
INSERT INTO `words` VALUES (25716, 'There’s plenty of fun for all the family.', 'n. 乐趣；玩笑；有趣的人或事; adj. 供娱乐用的; vi. 开玩笑', '/fʌn/', 'fun', 5);
INSERT INTO `words` VALUES (25717, 'The nervous system regulates our bodily functions (= eating, breathing, going to the toilet etc ) .', 'n. 功能；[数] 函数；职责；盛大的集会; v. 运行；活动；行使职责', '/\'fʌŋkʃən | \'fʌŋ(k)ʃ(ə)n/', 'function', 5);
INSERT INTO `words` VALUES (25718, 'The fund was set up to try to save the cathedral.', 'n. 基金；资金；存款; v. 投资；资助', '/fʌnd/', 'fund', 5);
INSERT INTO `words` VALUES (25719, 'We have to tackle the fundamental cause of the problem.', 'adj. 基本的，根本的; n. 基本原理；基本原则', '/,fʌndə\'mentəl | fʌndə\'ment(ə)l | ,fʌndə\'mɛntl/', 'fundamental', 5);
INSERT INTO `words` VALUES (25720, 'The funeral will be held at St. Martin’s Church.', 'n. 葬礼；麻烦事; adj. 丧葬的，出殡的', '/\'fju:nərəl | \'fjuːn(ə)r(ə)l | \'fjunərəl/', 'funeral', 5);
INSERT INTO `words` VALUES (25721, 'a fur coat', 'n. 毛,毛皮', '/fə | fɜː | fɝ/', 'fur', 5);
INSERT INTO `words` VALUES (25722, 'She was absolutely furious .', 'adj. 狂怒的,狂暴的,猛烈的', '/\'fju:riəs | \'fjʊərɪəs | \'fjʊrɪəs/', 'furious', 5);
INSERT INTO `words` VALUES (25723, 'We had better fire up the furnace.', 'n. 炉子,熔炉', '/\'fə:nis | \'fɜːnɪs | \'fɝnɪs/', 'furnace', 5);
INSERT INTO `words` VALUES (25724, 'Will these finds furnish more information on prehistoric man?', 'v. 供应,提供;装备,布置', '/\'fə:niʃ | \'fɜːnɪʃ | \'fɝnɪʃ/', 'furnish', 5);
INSERT INTO `words` VALUES (25725, 'I helped him choose the furniture for his house.', 'n. 家具', '/\'fə:nitʃə | \'fɜːnɪtʃə | \'fɝnɪtʃɚ/', 'furniture', 5);
INSERT INTO `words` VALUES (25726, 'He is old and unpopular. Furthermore, he has at best only two years of political life ahead of him.', 'adv. 此外；而且', '/\'fə:ðəmɔ: | fɜːðə\'mɔː | ,fɝðɚ\'mɔr/', 'furthermore', 5);
INSERT INTO `words` VALUES (25727, 'two 13 amp fuses', 'n. 保险丝,导火线,引信; v. 熔化,熔合', '/fju:z | fjuːz | fjuz/', 'fuse', 5);
INSERT INTO `words` VALUES (25728, 'I wish you’d stop fussing - I’ll be perfectly all right.', 'v. 小题大作；忙乱；焦燥；焦急；无事自扰; n. 大惊小怪，大惊小怪的人；小题大作；忙乱', '/fʌs/', 'fuss', 5);
INSERT INTO `words` VALUES (25729, 'My efforts to go back to sleep proved futile.', 'adj. 无用的；无效的；没有出息的；琐细的；不重要的', '/\'fju:tail | \'fjuːtaɪl | \'fjʊtaɪl/', 'futile', 5);
INSERT INTO `words` VALUES (25730, 'The islands should have the right to decide their own future.', 'n. 未来；前途；期货；将来时; adj. 将来的，未来的', '/\'fju:tʃə | \'fjuːtʃə | \'fjʊtʃɚ/', 'future', 5);
INSERT INTO `words` VALUES (25731, NULL, 'n. 标准尺寸， 规格； 量规， 量表', '/geɪdʒ | gedʒ/', 'gage', 5);
INSERT INTO `words` VALUES (25732, 'The Democratic Party needed a net gain of only 20 votes.', 'n. 增加；利润；收获; v. 获得；增加；赚到', '/ɡein | geɪn | ɡen/', 'gain', 5);
INSERT INTO `words` VALUES (25733, 'Astronomers have discovered a distant galaxy.', 'n. 银河；[天] 星系；银河系；一群显赫的人', '/\'gæləksɪ | \'ɡæləksi/', 'galaxy', 5);
