INSERT INTO `words` VALUES (25736, 'I was forced to attempt a gallop.', 'n. 疾驰；飞奔; v. 飞驰；急速进行；急急忙忙地说', '/\'ɡæləp | \'gæləp/', 'gallop', 5);
INSERT INTO `words` VALUES (25737, 'Their religion forbids them to drink or gamble.', 'v. 赌博；孤注一掷；投机；打赌; n. 赌博；冒险；打赌', '/\'ɡæmbl | \'gæmb(ə)l/', 'gamble', 5);
INSERT INTO `words` VALUES (25738, 'The boys were playing a game in the backyard.', 'n. 游戏；比赛; adj. 勇敢的; v. 赌博', '/ɡeim | geɪm | ɡem/', 'game', 5);
INSERT INTO `words` VALUES (25739, 'Several gangs were operating in the area.', 'n. 群；一伙；一组; v. 使成群结队；结伙伤害或恐吓某人', '/ɡæŋ | gæŋ/', 'gang', 5);
INSERT INTO `words` VALUES (25740, 'Hundreds and thousands of africans are thrown into gaol each year under pass laws.', 'v. 监禁; n. 监狱', '/dʒeil | dʒeɪl/', 'gaol', 5);
INSERT INTO `words` VALUES (25741, 'a gap in the traffic', 'n. 间隙；缺口；差距；分歧; v. 裂开', '/gæp | ɡæp/', 'gap', 5);
INSERT INTO `words` VALUES (25742, 'I’ll just go and put the car in the garage.', 'n. 车库；汽车修理厂；飞机库; v. 把……送入车库；把（汽车）开进车库', '/\'gærɑː(d)ʒ; -ɪdʒ; gə\'rɑːʒ | gəˈrɑʒ; gəˈrɑdʒ/', 'garage', 5);
INSERT INTO `words` VALUES (25743, 'Can you take out the garbage when you go?', 'n. 垃圾；废物', '/\'ɡɑ:bidʒ | \'gɑːbɪdʒ | \'ɡɑrbɪdʒ/', 'garbage', 5);
INSERT INTO `words` VALUES (25744, 'He’s outside in the garden.', 'n. 花园；菜园; v. 栽培花木', '/\'ɡɑ:dn | \'gɑːd(ə)n | \'ɡɑrdn/', 'garden', 5);
INSERT INTO `words` VALUES (25745, 'Add a crushed clove of garlic (= single section of it ).', 'n. 大蒜；蒜头', '/\'ɡɑ:lik | \'gɑːlɪk | \'ɡɑrlɪk/', 'garlic', 5);
INSERT INTO `words` VALUES (25746, 'She pulled the garment on and zipped it up.', 'n. 衣服，服装；外表，外观; v. 给…穿衣服', '/\'ɡɑ:mənt | \'gɑːm(ə)nt | \'gɑrmənt/', 'garment', 5);
INSERT INTO `words` VALUES (25747, 'hydrogen gas', 'n. 气体；[矿业] 瓦斯；汽油；毒气; v. 加油；毒（死）', '/ɡæs | gæs/', 'gas', 5);
