INSERT INTO `words` VALUES (25749, 'A gasoline engine drives the motorboat.', 'n. 汽油', '/\'ɡæsəli:n | \'gæsəliːn | \'gæsəlin/', 'gasoline', 5);
INSERT INTO `words` VALUES (25750, 'I’m gasping for a pint!', 'v. 喘气；喘息；渴望; n. 喘气', '/ɡɑ:sp, ɡæsp | gɑːsp | ɡæsp/', 'gasp', 5);
INSERT INTO `words` VALUES (25751, 'We went through the gate into the orchard.', 'n. 大门；出入口；门道; v. 给…装大门', '/ɡeit | geɪt | ɡet/', 'gate', 5);
INSERT INTO `words` VALUES (25752, 'A crowd gathered to watch the fight.', 'v. 收集；收割；使…聚集；使…皱起; n. 聚集；衣褶；收获量', '/\'ɡæðə | \'gæðə | \'ɡæðɚ/', 'gather', 5);
INSERT INTO `words` VALUES (25753, 'Retail sales are a gauge of consumer spending.', 'n. 计量器；标准尺寸；容量规格; v. 测量；估计；给…定规格', '/ɡeidʒ | geɪdʒ | gedʒ/', 'gauge', 5);
INSERT INTO `words` VALUES (25754, 'She felt excited and quite gay.', 'adj. 快乐的；放荡的；艳丽的; n. 同性恋者', '/ɡei | geɪ | ɡe/', 'gay', 5);
INSERT INTO `words` VALUES (25755, 'Patrick sat gazing into space (= looking straight in front, not at any particular person or thing ).', 'v. 凝视；注视; n. 凝视；注视', '/ɡeiz | geɪz | ɡeɪz/', 'gaze', 5);
INSERT INTO `words` VALUES (25756, 'He’s crazy about photography – he’s got all the gear.', 'n. 齿轮；装置，工具；传动装置; v. 适合；搭上齿轮；开始工作; adj. 好极了', '/ɡiə | gɪə | ɡɪr/', 'gear', 5);
INSERT INTO `words` VALUES (25757, 'people of the same gender', 'n. (生理上的)性；(名词、代词等的)性', '/\'dʒendə | \'dʒɛndɚ/', 'gender', 5);
INSERT INTO `words` VALUES (25758, 'human genes', 'n. 基因', '/dʒi:n | dʒiːn | dʒin/', 'gene', 5);
INSERT INTO `words` VALUES (25759, 'a general introduction to computing', 'adj. 一般的,普通的;总的,大体的; n. 将军', '/\'dʒen(ə)r(ə)l | \'dʒɛnrəl/', 'general', 5);
INSERT INTO `words` VALUES (25760, NULL, 'v. 归纳， 概括；推广， 普及', '/\'dʒenrəlaɪz | \'dʒenərəlaiz/', 'generalise', 5);
INSERT INTO `words` VALUES (25761, 'Can we generalise this principle?', 'v. (generalise)归纳,概括;推广,普及', '/\'dʒenərəlaiz | ˈdʒɛnrəˌlaɪz | \'dʒɛnrəlaɪz/', 'generalize', 5);
INSERT INTO `words` VALUES (25762, 'a useful technique for generating new ideas', 'v. 产生,发生;生殖', '/\'dʒenəreɪt | \'dʒɛnəret/', 'generate', 5);
