INSERT INTO `words` VALUES (25764, 'an emergency generator', 'n. 发电机,发生器', '/\'dʒenəreitə | \'dʒenəreɪtə | \'dʒɛnəretɚ/', 'generator', 5);
INSERT INTO `words` VALUES (25765, 'a generous glass of wine', 'adj. 宽宏大量的,慷慨的', '/\'dʒenərəs | \'dʒen(ə)rəs | \'dʒɛnərəs/', 'generous', 5);
INSERT INTO `words` VALUES (25766, 'genetic defects', 'adj. 遗传(学)的; n. [-s]遗传学', '/dʒi\'netik | dʒɪ\'netɪk | dʒə\'nɛtɪk/', 'genetic', 5);
INSERT INTO `words` VALUES (25767, 'Genetics is also bringing about dramatic changes in our understanding of cancer.', 'n. 遗传学', '/dʒə\'netɪks | dʒə\'nɛtɪks/', 'genetics', 5);
INSERT INTO `words` VALUES (25768, 'The film reveals Fellini’s genius.', 'n. 天才', '/\'dʒi:njəs | \'dʒiːnɪəs | \'dʒinjəs/', 'genius', 5);
INSERT INTO `words` VALUES (25769, 'a literary genre', 'n. 体载， 类型', '/\'ʒɒnrə | \'ʒɑnrə/', 'genre', 5);
INSERT INTO `words` VALUES (25770, 'Arthur was a very gentle, caring person.', 'adj. 和蔼的,文雅的,有礼貌的', '/\'dʒentl | \'dʒent(ə)l | \'dʒɛntl/', 'gentle', 5);
INSERT INTO `words` VALUES (25771, 'Could you serve this gentleman please, Miss Bath?', 'n. 绅士,先生', '/\'dʒent(ə)lmən | \'dʒɛntlmən/', 'gentleman', 5);
INSERT INTO `words` VALUES (25772, '‘You go back to bed now,’ he said gently.', 'adv. 文雅地,有礼貌地;轻轻地', '/\'dʒentli | \'dʒentlɪ | \'dʒɛntli/', 'gently', 5);
INSERT INTO `words` VALUES (25773, '‘Did he really?’ Her surprise seemed genuine.', 'adj. 真正的,名副其实的', '/\'dʒenjuin | \'dʒenjʊɪn | \'dʒɛnjʊɪn/', 'genuine', 5);
INSERT INTO `words` VALUES (25774, 'a geography lesson', 'n. 地理；地形', '/dʒi\'ɔɡrəfi | dʒɪ\'ɒgrəfɪ | dʒɪ\'ɑɡrəfi/', 'geography', 5);
INSERT INTO `words` VALUES (25775, 'He was visiting professor of geology at the University of Georgia.', 'n. 地质(学)', '/dʒi\'ɔlədʒi | dʒɪ\'ɒlədʒɪ | dʒɪ\'ɑlədʒi/', 'geology', 5);
INSERT INTO `words` VALUES (25776, '...the very ordered way in which mathematics and geometry describe nature.', 'n. 几何(学)', '/dʒi\'ɔmitri | dʒɪ\'ɒmɪtrɪ | dʒɪ\'ɑmətri/', 'geometry', 5);
INSERT INTO `words` VALUES (25777, 'Put disinfectant down the toilet to kill any germs.', 'n. [植] 胚芽，萌芽；细菌; vi. 萌芽', '/dʒə:m | dʒɜːm | dʒɝm/', 'germ', 5);
INSERT INTO `words` VALUES (25778, 'Luke made an obscene gesture with his finger.', 'n. 姿态；手势; v. 作手势；用动作示意', '/\'dʒestʃə | \'dʒɛstʃɚ/', 'gesture', 5);
INSERT INTO `words` VALUES (25779, 'They say the young girl’s ghost still haunts (= often appears in ) the house.', 'n. 鬼，幽灵; v. 作祟于；替…捉刀；为人代笔', '/ɡəust | gəʊst | ɡost/', 'ghost', 5);
INSERT INTO `words` VALUES (25780, 'the German chemicals giant, BASF', 'n. 巨人；伟人；[动] 巨大的动物; adj. 巨大的；巨人般的', '/\'dʒaiənt | \'dʒaɪənt/', 'giant', 5);
INSERT INTO `words` VALUES (25781, 'The earrings were a gift from my aunt.', 'n. 礼物；天赋；赠品; v. 赋予；向…赠送', '/ɡift | gɪft | ɡɪft/', 'gift', 5);
INSERT INTO `words` VALUES (25782, 'a gigantic skyscraper', 'adj. 巨大的，庞大的', '/,dʒai\'ɡæntik | dʒaɪ\'gæntɪk | dʒaɪ\'ɡæntɪk/', 'gigantic', 5);
INSERT INTO `words` VALUES (25783, 'If you can’t stop giggling you’ll have to leave the room.', 'v. 傻笑；咯咯地笑; n. 吃吃的笑', '/\'ɡiɡl | \'gɪg(ə)l | \'ɡɪɡl/', 'giggle', 5);
INSERT INTO `words` VALUES (25784, 'Do you think we can glide down this glacier?', 'n. 冰河， 冰川', '/\'glæsiə | \'ɡleʃɚ/', 'glacier', 5);
INSERT INTO `words` VALUES (25785, 'We’re so glad you came.', 'adj. 高兴的；乐意的；令人高兴的；灿烂美丽的; vt. 使高兴; n. (Glad)人名；(塞、瑞典)格拉德；(英)格莱德；(法、挪)格拉', '/ɡlæd | glæd/', 'glad', 5);
INSERT INTO `words` VALUES (25786, 'But when it comes down to it, we cannot ignore a film franchise that has been successfully thrilling us with action and glamor for over 40 years.', 'n. 魅力；魔法；迷人的美（等于glamour）; vt. 迷惑；使有魅力（等于glamour）', '/\'ɡlæmə | \'glæmɚ/', 'glamor', 5);
INSERT INTO `words` VALUES (25787, '...the glamour of show biz.', 'n. 魅力， 诱惑力', '/\'glæmə | \'ɡlæmə/', 'glamour', 5);
INSERT INTO `words` VALUES (25788, 'He gave her a quick glance and smiled.', 'n. 一瞥；一滑；闪光; v. 扫视，匆匆一看；反光；瞥闪，瞥见', '/ɡlɑ:ns, ɡlæns | glɑːns | ɡlæns/', 'glance', 5);
INSERT INTO `words` VALUES (25789, 'a special screen to reduce glare', 'n. 刺眼；耀眼的光；受公众注目; v. 瞪眼表示', '/ɡlεə | gleə | ɡlɛr/', 'glare', 5);
INSERT INTO `words` VALUES (25790, 'a glass bowl', 'n. 玻璃；玻璃制品；镜子; v. 反映；给某物加玻璃', '/ɡlɑ:s, ɡlæs | glɑːs | ɡlæs/', 'glass', 5);
INSERT INTO `words` VALUES (25791, 'Waiters glide between tightly packed tables bearing trays of pasta.', 'v. 滑翔；滑行；悄悄地走；消逝; n. 滑翔；滑行；滑移；滑音', '/glaɪd | ɡlaɪd/', 'glide', 5);
INSERT INTO `words` VALUES (25792, 'Some of the fans had waited 24 hours outside the hotel to catch a glimpse of their heroine.', 'n. 一瞥，一看; v. 瞥见', '/ɡlimps | glɪm(p)s | ɡlɪmps/', 'glimpse', 5);
INSERT INTO `words` VALUES (25793, 'The river glittered in the sunlight.', 'v. 闪光；闪烁; n. 闪光；灿烂', '/\'ɡlitə | \'glɪtə | \'ɡlɪtɚ/', 'glitter', 5);
INSERT INTO `words` VALUES (25794, 'global climate change', 'adj. 全球的；总体的；球形的', '/\'ɡləubəl | \'gləʊb(ə)l | \'ɡlobl/', 'global', 5);
