INSERT INTO `words` VALUES (25796, 'The report paints a gloomy picture of the economy.', 'adj. 黑暗的；沮丧的；阴郁的', '/\'ɡlu:mi | \'gluːmɪ | \'ɡlumi/', 'gloomy', 5);
