INSERT INTO `words` VALUES (25798, 'She dreamt of future glory as an Olympic champion.', 'n. 光荣，荣誉；赞颂; v. 自豪，骄傲；狂喜', '/\'ɡlɔ:ri | \'glɔːrɪ | \'ɡlɔri/', 'glory', 5);
INSERT INTO `words` VALUES (25799, 'a pair of gloves', 'n. 手套; vt. 给…戴手套', '/ɡlʌv | glʌv/', 'glove', 5);
INSERT INTO `words` VALUES (25800, 'The bedside lamp glowed dimly.', 'v. 发热；洋溢；绚丽夺目; n. 灼热；色彩鲜艳；兴高采烈', '/ɡləu | gləʊ | ɡlo/', 'glow', 5);
INSERT INTO `words` VALUES (25801, 'Glue the fabric around the window.', 'v. 粘合；似胶般固着于; n. 胶；各种胶合物', '/ɡlu: | gluː | ɡlu/', 'glue', 5);
INSERT INTO `words` VALUES (25802, 'Your goal as a parent is to help your child become an independent adult.', 'n. 目标；球门，得分数；终点; vi. 攻门，射门得分', '/ɡəul | gəʊl | ɡol/', 'goal', 5);
