INSERT INTO `words` VALUES (25804, 'Prayer is a way of talking to God.', 'n. 神；（大写首字母时）上帝; vt. 膜拜，崇拜', '/ɡɔd | ɡɒd | ɡɑd/', 'god', 5);
INSERT INTO `words` VALUES (25805, 'She came to the party dripping with gold (= wearing a lot of gold ) .', 'n. 金，黄金；金色；金币; adj. 金的，金制的；金色的', '/ɡəuld | gəʊld | ɡold/', 'gold', 5);
INSERT INTO `words` VALUES (25806, 'golden hair', 'adj. 金色的，黄金般的；珍贵的；金制的; n. (Golden)人名；(英、法、罗、德、瑞典)戈尔登', '/\'ɡəuldən | \'gəʊld(ə)n | \'ɡoldən/', 'golden', 5);
INSERT INTO `words` VALUES (25807, 'He plays golf on Sundays.', 'n. 高尔夫球', '/gɒlf | gɔlf/', 'golf', 5);
INSERT INTO `words` VALUES (25808, 'His teacher went on:” And when you come out, at the age of 21, you can kiss your dream of becoming a famous physicist, doing research into your favourite subject of kinetic energy goodby!', 'int. 再见（等于goodbye）; n. (Goodby)人名；(英)古德拜', '/,ɡud\'bai/', 'goodby', 5);
INSERT INTO `words` VALUES (25809, 'My goodness, you have spent a lot!', 'int. 天哪; n. 善良，优秀 ；精华，养分', '/英[\'gʊdnɪs] 美[\'ɡʊdnəs] | \'gʊdnɪs | \'ɡʊdnəs/', 'goodness', 5);
INSERT INTO `words` VALUES (25810, 'the large market for consumer goods', 'n. 商品；动产；合意的人；真本领', '/ɡudz | ɡʊdz/', 'goods', 5);
INSERT INTO `words` VALUES (25811, '...roast goose.', 'n. 鹅；鹅肉；傻瓜；雌鹅; v. 突然加大油门；嘘骂', '/ɡu:s | guːs | ɡus/', 'goose', 5);
INSERT INTO `words` VALUES (25812, '‘What do you think of my new flatmate?’ ‘He’s absolutely gorgeous !’', 'adj. 华丽的，灿烂的；极好的', '/\'ɡɔ:dʒəs | \'gɔːdʒəs | \'ɡɔrdʒəs/', 'gorgeous', 5);
INSERT INTO `words` VALUES (25813, 'Rick’s a terrible gossip.', 'n. 小道传闻；随笔；爱说长道短的人; v. 闲聊；传播流言蜚语', '/\'ɡɔsip | \'gɒsɪp | \'ɡɑsɪp/', 'gossip', 5);
INSERT INTO `words` VALUES (25814, 'the leaders who govern the country', 'v. 管理；支配；统治；控制; n. (Govern)人名；(英)戈文', '/\'ɡʌvən | \'gʌv(ə)n | \'ɡʌvɚn/', 'govern', 5);
INSERT INTO `words` VALUES (25815, 'the prison governor', 'n. 主管人员；统治者，管理者；[自] 调节器；地方长官', '/\'ɡʌvənə | \'gʌv(ə)nə | \'ɡʌvɚnɚ/', 'governor', 5);
INSERT INTO `words` VALUES (25816, 'a hospital gown', 'n. 长袍，长外衣；礼服；睡袍；法衣; v. 使穿睡衣', '/ɡaun | gaʊn | ɡaʊn/', 'gown', 5);
INSERT INTO `words` VALUES (25817, 'I grabbed my bag and ran off.', 'v. 抓； 夺 <; n. 抓； 夺', '/græb | ɡræb/', 'grab', 5);
INSERT INTO `words` VALUES (25818, 'Lena moved with the grace of a dancer.', 'n. 优美,文雅;恩惠,恩泽;宽限,缓刑;感恩祷告', '/ɡreis | greɪs | ɡres/', 'grace', 5);
INSERT INTO `words` VALUES (25819, 'Her movements were graceful and elegant.', 'adj. 优美的,文雅的,大方的', '/\'ɡreisful | \'greɪsfʊl; -f(ə)l | \'ɡresfl/', 'graceful', 5);
INSERT INTO `words` VALUES (25820, 'Sibyl was the most gracious, helpful, and generous person to work with.', 'adj. 亲切的,客气的;宽厚的,仁慈的', '/\'ɡreiʃəs | \'greɪʃəs | \'ɡreʃəs/', 'gracious', 5);
INSERT INTO `words` VALUES (25821, 'The best grades of tea are expensive.', 'n. 等级,级别;年级;分数; v. 分等,分级', '/ɡreid | greɪd | ɡred/', 'grade', 5);
INSERT INTO `words` VALUES (25822, 'There has been a gradual change in climate.', 'adj. 逐渐的,逐步的', '/\'ɡrædʒuəl | \'grædʒʊəl/', 'gradual', 5);
INSERT INTO `words` VALUES (25823, 'a Harvard graduate', 'n. 大学毕业生,研究生v.大学毕业a.毕了业的', '/\'ɡrædʒuət, -eit, \'ɡrædjueit, -dʒu- | ˈɡradʒʊeɪt | ˈɡrædʒuˌet/', 'graduate', 5);
INSERT INTO `words` VALUES (25824, '...a grain of wheat.', 'n. 粮食；颗粒；[作物] 谷物；纹理; v. 成谷粒', '/ɡrein | greɪn | ɡren/', 'grain', 5);
INSERT INTO `words` VALUES (25825, 'Then they chose one gram for weighing water in a cubic centimetre.', 'n. 克', '/græm | ɡræm/', 'gram', 5);
INSERT INTO `words` VALUES (25826, 'Check your spelling and grammar.', 'n. 语法,语法书', '/\'ɡræmə | \'græmə | \'græmɚ/', 'grammar', 5);
INSERT INTO `words` VALUES (25827, NULL, 'n. 克', '/ɡræm/', 'gramme', 5);
INSERT INTO `words` VALUES (25828, 'the Grand Hotel', 'adj. 盛大的,豪华的;重大的,主要的', '/ɡrænd | grænd/', 'grand', 5);
INSERT INTO `words` VALUES (25829, 'My grandmothers are both widows.', 'n. 祖母,外祖母', '/\'ɡrænd,mʌðə | \'græn(d)mʌðə | \'ɡrænmʌðɚ/', 'grandmother', 5);
INSERT INTO `words` VALUES (25830, 'Britain could grant Spain’s request .', 'v. 同意,准予;授予; n. 授予物;津贴;转让证书', '/ɡrɑ:nt, ɡrænt | grɑːnt | ɡrænt/', 'grant', 5);
INSERT INTO `words` VALUES (25831, 'a bunch of grapes', 'n. 葡萄；葡萄酒；葡萄树；葡萄色', '/ɡreip | greɪp | ɡrep/', 'grape', 5);
INSERT INTO `words` VALUES (25832, 'Martin showed me a graph of their recent sales.', 'n. 图表， 曲线图 A', '/grɑːf | ɡræf/', 'graph', 5);
INSERT INTO `words` VALUES (25833, 'a graphic artist', 'adj. 形象的；图表的；绘画似的', '/\'ɡræfik | \'græfɪk/', 'graphic', 5);
INSERT INTO `words` VALUES (25834, 'Luke took her arm in a firm grasp and led her through the gate.', 'n. 抓住；理解；控制; v. 抓住；领会', '/ɡrɑ:sp, ɡræsp | grɑːsp | ɡræsp/', 'grasp', 5);
INSERT INTO `words` VALUES (25835, 'I walked across the grass.', 'n. 草；草地，草坪; v. 放牧；使……长满草；使……吃草', '/ɡrɑ:s, ɡræs | grɑːs | ɡræs/', 'grass', 5);
INSERT INTO `words` VALUES (25836, 'Our grateful thanks go to all who participated.', 'adj. (to,for)感激的;感谢的', '/\'ɡreitful | \'greɪtfʊl; -f(ə)l | \'ɡretfl/', 'grateful', 5);
INSERT INTO `words` VALUES (25837, 'Tears of gratitude filled her eyes.', 'n. 感激,感谢', '/\'grætɪtjuːd | \'ɡrætɪtud/', 'gratitude', 5);
INSERT INTO `words` VALUES (25838, 'Matthew’s life is in grave danger .', 'adj. 重大的；严肃的；黯淡的; n. 墓穴，坟墓；死亡; v. 雕刻；铭记', '/ɡreiv | greɪv | ɡrev/', 'grave', 5);
INSERT INTO `words` VALUES (25839, 'the force of gravity', 'n. 重力， 引力；庄重； 严重', '/\'grævəti | ˈɡrævətɪ/', 'gravity', 5);
INSERT INTO `words` VALUES (25840, 'I fell on the gravel, severely grazing my knee.', 'v. 放牧；擦伤; n. 放牧；轻擦', '/ɡreiz | greɪz | ɡrez/', 'graze', 5);
INSERT INTO `words` VALUES (25841, 'His hair is thick with grease.', 'v. 涂脂于；贿赂; n. 油脂；贿赂', '/ɡri:s | griːs | gris/', 'grease', 5);
INSERT INTO `words` VALUES (25842, 'The movie was a great success.', 'adj. 伟大的；重要的；大量的；很好的；美好的', '/ɡreit | greɪt | ɡret/', 'great', 5);
INSERT INTO `words` VALUES (25843, 'a greedy and selfish society', 'adj. 贪婪的；贪吃的；渴望的', '/ɡri:di | \'griːdɪ | \'gridi/', 'greedy', 5);
INSERT INTO `words` VALUES (25844, 'beautiful green eyes', 'adj. 绿色的；青春的; n. 绿色；青春; v. 使…变绿色', '/ɡri:n | griːn | ɡrin/', 'green', 5);
INSERT INTO `words` VALUES (25845, 'What we are seeking, after all, is not simply an agreement to limit greenhouse gas emissions.', 'n. 温室', '/\'griːnhaus | \'ɡrinhaʊs/', 'greenhouse', 5);
INSERT INTO `words` VALUES (25846, 'Belinda greeted her warmly.', 'v. 致敬,敬意,迎接;扑(鼻),入(耳),触(目)', '/ɡri:t | griːt | ɡrit/', 'greet', 5);
INSERT INTO `words` VALUES (25847, 'I smiled a polite greeting, but the woman hardly acknowledged me.', 'n. 问候,致敬', '/\'ɡri:tiŋ | \'griːtɪŋ | \'ɡritɪŋ/', 'greeting', 5);
INSERT INTO `words` VALUES (25848, 'an old lady with grey hair', 'adj. 灰色的；灰白的; v. 使变成灰色；使变老; n. 灰色', '/ɡrei | greɪ | ɡre/', 'grey', 5);
INSERT INTO `words` VALUES (25849, 'Every change in our lives brings with it griefs.', 'n. 悲痛；忧伤；不幸', '/ɡri:f | griːf | ɡrif/', 'grief', 5);
INSERT INTO `words` VALUES (25850, 'My aunt, it grieves me to say, gets things confused.', 'v. 使悲伤，使苦恼; n. (Grieve)人名；(英)格里夫', '/ɡri:v | griːv | griv/', 'grieve', 5);
INSERT INTO `words` VALUES (25851, 'The weather forecast is pretty grim.', 'adj. 冷酷的；糟糕的；残忍的; n. (Grim)人名；(英、德、俄、捷、匈)格里姆', '/ɡrim | grɪm | ɡrɪm/', 'grim', 5);
INSERT INTO `words` VALUES (25852, 'He grins, delighted at the memory.', 'v. 露齿而笑，咧着嘴笑; n. 露齿笑', '/ɡrin | grɪn | ɡrɪn/', 'grin', 5);
INSERT INTO `words` VALUES (25853, 'a stone for grinding knives and scissors', 'v. 磨碎；磨快; n. 磨；苦工作', '/ɡraind | graɪnd | ɡraɪnd/', 'grind', 5);
INSERT INTO `words` VALUES (25854, 'Hold the microphone in a firm grip and keep it still.', 'n. 紧握；柄；支配；握拍方式；拍柄绷带; v. 紧握；夹紧', '/ɡrip | grɪp | ɡrɪp/', 'grip', 5);
INSERT INTO `words` VALUES (25855, 'The kids all groaned when I switched off the TV.', 'v. 呻吟；抱怨；发吱嘎声; n. 呻吟；叹息；吱嘎声', '/ɡrəun | grəʊn | ɡron/', 'groan', 5);
INSERT INTO `words` VALUES (25856, 'The cook and the grocer haggled over the price of eggs.', 'n. 杂货店；食品商', '/\'ɡrəusə | \'grəʊsə | ɡrosɚ/', 'grocer', 5);
INSERT INTO `words` VALUES (25857, 'With his left hand he groped for the knob, turned it, and pulled the door open.', 'v. 摸索；探索; n. 摸索；触摸', '/ɡrəup | grəʊp | ɡrop/', 'grope', 5);
INSERT INTO `words` VALUES (25858, 'He abused the Admiral in the grossest terms.', 'adj. 总共的；粗野的；恶劣的；显而易见的; v. 总共收入; n. 总额，总数', '/ɡrəus | grəʊs | ɡros/', 'gross', 5);
INSERT INTO `words` VALUES (25859, 'A group of us are going to London.', 'n. 组；团体; adj. 群的；团体的; v. 聚合', '/ɡru:p | gruːp | ɡrup/', 'group', 5);
INSERT INTO `words` VALUES (25860, 'Before you know it, the children will be grown-up and leaving home.', 'adj. 成长的； 成熟的； 成人的; n. 成年人', '/\'grəunʌp | \'ɡrəun\'ʌp/', 'grown-up', 5);
INSERT INTO `words` VALUES (25861, 'measures to stimulate economic growth', 'n. 增长；发展；生长；种植', '/ɡrəuθ | grəʊθ | ɡroθ/', 'growth', 5);
INSERT INTO `words` VALUES (25862, 'They offer a two-year guarantee on all their electrical goods.', 'n. 保证； 保证书 A; vt. 保证， 担保', '/ˌgærən\'tiː | ,ɡærən\'ti/', 'guarantee', 5);
INSERT INTO `words` VALUES (25863, 'I’d say he’s around 50, but I’m only guessing.', 'v. 猜测；认为；推测；猜中; n. 猜测；推测', '/ges | ɡɛs/', 'guess', 5);
INSERT INTO `words` VALUES (25864, 'a banquet for 250 distinguished guests', 'n. 客人，宾客；顾客; v. 款待，招待; adj. 客人的；特邀的，客座的', '/ɡest | gest | ɡɛst/', 'guest', 5);
INSERT INTO `words` VALUES (25865, 'a missile with a sophisticated electronic guidance system', 'n. 指导，引导；领导', '/\'ɡaidəns | \'gaɪd(ə)ns | \'gaɪdns/', 'guidance', 5);
INSERT INTO `words` VALUES (25866, 'a tour guide', 'n. 指南；向导；入门书; v. 引导；带领；操纵', '/ɡaid | gaɪd | ɡaɪd/', 'guide', 5);
INSERT INTO `words` VALUES (25867, 'This chapter gives you some guidelines to help you in your work.', 'n. 指导方针', '/\'ɡaidlain | \'gaɪdlaɪn | \'ɡaɪdlaɪn/', 'guideline', 5);
INSERT INTO `words` VALUES (25868, 'the Women’s Guild', 'n. 协会， 行会', '/gɪld | ɡɪld/', 'guild', 5);
INSERT INTO `words` VALUES (25869, 'He used to buy them expensive presents, out of guilt.', 'n. 犯罪，过失；内疚', '/ɡilt | gɪlt | ɡɪlt/', 'guilt', 5);
INSERT INTO `words` VALUES (25870, 'She looked self-conscious and guilty.', 'adj. 有罪的；内疚的', '/\'ɡilti | \'gɪltɪ | \'ɡɪlti/', 'guilty', 5);
INSERT INTO `words` VALUES (25871, NULL, 'n. 吉他， 六弦琴', '/gɪ\'tɑː | ɡɪ\'tɑr/', 'guitar', 5);
INSERT INTO `words` VALUES (25872, 'the Gulf of Mexico', 'n. 海湾；深渊；分歧；漩涡; vt. 吞没', '/ɡʌlf | gʌlf/', 'gulf', 5);
INSERT INTO `words` VALUES (25873, 'I do not chew gum in public.', 'n. 口香糖；树胶；橡皮; v. 用胶粘，涂以树胶；使…有粘性', '/ɡʌm | gʌm/', 'gum', 5);
INSERT INTO `words` VALUES (25874, 'I’ve never fired a gun in my life.', 'n. 枪支；枪状物；持枪歹徒; v. 用枪射击；加大油门快速前进', '/gʌn | ɡʌn/', 'gun', 5);
INSERT INTO `words` VALUES (25875, 'He had a gut feeling that Sarah was lying.', 'n. 内脏；肠子；剧情；胆量；海峡；勇气；直觉；肠; v. 取出内脏；摧毁（建筑物等）的内部; adj. 简单的；本质的，根本的；本能的，直觉的', '/gʌt | ɡʌt/', 'gut', 5);
INSERT INTO `words` VALUES (25876, 'Dave’s a nice guy when you get to know him.', 'n. 男人，家伙; v. 嘲弄，取笑', '/ɡai | gaɪ/', 'guy', 5);
INSERT INTO `words` VALUES (25877, 'I go to the gym as often as I can.', 'n. 体育馆， 健身房', '/dʒɪm\'n3ɪziəm | dʒɪm/', 'gym', 5);
INSERT INTO `words` VALUES (25878, 'I have found a new gymnasium.', 'n. 体育馆；健身房', '/dʒim\'neiziəm | dʒɪm\'neɪzɪəm | dʒɪm\'nezɪəm/', 'gymnasium', 5);
INSERT INTO `words` VALUES (25879, 'watching monkeys in their natural habitat', 'n. 栖息地； 住处', '/\'hæbɪtæt | \'hæbə\'tæt/', 'habitat', 5);
INSERT INTO `words` VALUES (25880, 'heavy showers of rain and hail', 'n. 冰雹；致敬；招呼；一阵; v. 致敬；招呼；向欢呼；猛发；使像下雹样落下（过去式hailed，过去分词hailed，现在分词hailing，第三人称单数hails）; int. 万岁；欢迎', '/heɪl | hel/', 'hail', 5);
INSERT INTO `words` VALUES (25881, 'Her hair was short and dark.', 'n. 头发；毛发；些微; vt. 除去…的毛发; vi. 生长毛发；形成毛状纤维; adj. 毛发的；护理毛发的；用毛发制成的', '/hεə | heə | hɛr/', 'hair', 5);
INSERT INTO `words` VALUES (25882, 'a huge tiled entrance hall', 'n. 过道，门厅，走廊；会堂；食堂；学生宿舍；大厅，前厅；娱乐中心，会所', '/hɔːl | hɔl/', 'hall', 5);
INSERT INTO `words` VALUES (25883, 'The government has failed to halt economic decline.', 'v. 停止；立定；踌躇，犹豫; n. 停止；立定；休息', '/hɔ:lt | hɔːlt | hɔlt/', 'halt', 5);
INSERT INTO `words` VALUES (25884, 'a ham sandwich', 'n. 火腿；业余无线电爱好者；蹩脚演员; v. 表演过火; adj. 过火的；做作的', '/hæm/', 'ham', 5);
INSERT INTO `words` VALUES (25885, 'I order a soda and a hamburger for myself. Then another person gets coffee for me.', 'n. 汉堡包，火腿汉堡；牛肉饼，肉饼；碎牛肉', '/ˈhæmbɜ:gə | hæmbɝ​ɡɚ/', 'hamburger', 5);
INSERT INTO `words` VALUES (25886, 'the sound of hammering and sawing', 'v. 锤击；敲打；重复; n. 铁锤；链球；[解剖] 锤骨；音锤', '/\'hæmə | \'hæmɚ/', 'hammer', 5);
INSERT INTO `words` VALUES (25887, 'She tried to run, but was hampered by her heavy suitcase.', 'v. 妨碍；束缚；使困累; n. 食盒，食篮；阻碍物', '/\'hæmpə | \'hæmpɚ/', 'hamper', 5);
INSERT INTO `words` VALUES (25888, 'the Fiction Writer’s Handbook', 'n. 手册；指南', '/\'hændbuk | \'hæn(d)bʊk | \'hændbʊk/', 'handbook', 5);
INSERT INTO `words` VALUES (25889, 'There were only a handful of people there.', 'n. 少数；一把；棘手事', '/\'hændful | \'hæn(d)fʊl; -f(ə)l | \'hænd,fʊl/', 'handful', 5);
INSERT INTO `words` VALUES (25890, 'The charity is handicapped by lack of funds.', 'v. 妨碍; n. (身体或智力方面的)缺陷;不利条件', '/\'hændikæp | \'hændɪkæp | \'hændɪ\'kæp/', 'handicap', 5);
INSERT INTO `words` VALUES (25891, 'Before sweeping the house she bound up her hair in a large handkerchief.', 'n. 手帕；头巾，围巾', '/\'hæŋkətʃif, -tʃi:f | \'hæŋkətʃɪf | \'hæŋkɚtʃɪf/', 'handkerchief', 5);
INSERT INTO `words` VALUES (25892, 'Then he turned the handle and went in.', 'n. 柄， 把手， 拉手; vt. 处理， 对待； 操纵 A；触， 摸', '/\'hændl/', 'handle', 5);
INSERT INTO `words` VALUES (25893, 'He managed to make a handsome profit out of the deal.', 'adj. （男子）英俊的；可观的；大方的，慷慨的；健美而端庄的', '/\'hænsəm | \'hæns(ə)m/', 'handsome', 5);
INSERT INTO `words` VALUES (25894, 'I recognised her handwriting on the envelope.', 'n. 笔迹；书法；书写；手稿; v. 亲手写（handwrite的ing形式）', '/\'hænd,raitiŋ | \'hændraɪtɪŋ | \'hænd\'raɪtɪŋ/', 'handwriting', 5);
INSERT INTO `words` VALUES (25895, 'I always keep my gun handy just in case.', 'adj. 便利的；手边的，就近的；容易取得的；敏捷的; n. (Handy)人名；(英)汉迪', '/\'hændi | \'hændɪ/', 'handy', 5);
INSERT INTO `words` VALUES (25896, 'If he is found guilty, he will almost certainly hang.', 'v. 悬挂，垂下；装饰；绞死；使悬而未决; n. 悬挂；暂停，中止', '/\'hæŋ | hæŋ/', 'hang', 5);
INSERT INTO `words` VALUES (25897, 'It’s a lovely house and we’ve been very happy here.', 'adj. 幸福的；高兴的；巧妙的; n. (Happy)人名；(英、瑞典、喀)哈皮', '/\'hæpi | \'hæpɪ/', 'happy', 5);
INSERT INTO `words` VALUES (25898, 'African-Americans have been complaining about police harassment for years.', 'n. 骚扰；烦恼', '/\'hærəsmənt, hə\'ræsmənt | \'hærəsm(ə)nt; hə\'ræsm(ə)nt | hə\'ræsmənt/', 'harassment', 5);
INSERT INTO `words` VALUES (25899, NULL, 'v. 庇护；怀有; n. 海港；避难所', '/\'hɑ:bə | \'hɑrbɚ/', 'harbor', 5);
INSERT INTO `words` VALUES (25900, 'as they sailed into Portsmouth Harbour', 'n. 港口， 海港；避难所， 藏身处; vt. 隐匿； 窝藏， 包庇', '/\'hɑːbə | hɑrbɚ/', 'harbour', 5);
INSERT INTO `words` VALUES (25901, 'It will take about 24 hours for the glue to harden.', 'v. 变硬，变坚固；变坚强；变冷酷; n. (Harden)人名；(英、德、罗、瑞典)哈登；(法)阿尔当', '/\'hɑ:dən | \'hɑːd(ə)n | \'hɑrdn/', 'harden', 5);
INSERT INTO `words` VALUES (25902, 'an economic policy that caused great hardship for many people', 'n. 困苦；苦难；艰难险阻', '/\'hɑ:dʃip | \'hɑːdʃɪp | \'hɑrdʃɪp/', 'hardship', 5);
INSERT INTO `words` VALUES (25903, '...a shop from which an uncle had sold hardware and timber.', 'n. 计算机硬件；五金器具', '/\'hɑ:dwεə | \'hɑːdweə | \'hɑrdwɛr/', 'hardware', 5);
INSERT INTO `words` VALUES (25904, 'The scandal did his career a lot of harm.', 'n. 伤害；损害; v. 伤害；危害；损害', '/hɑ:m | hɑːm | hɑrm/', 'harm', 5);
INSERT INTO `words` VALUES (25905, 'the gorgeous vocal harmonies on ‘Mexicali Rose’', 'n. 协调,和谐;融洽', '/\'hɑ:məni | \'hɑːmənɪ | \'hɑrməni/', 'harmony', 5);
INSERT INTO `words` VALUES (25906, 'We can harness the power of the wind to generate electricity.', 'v. 治理；套；驾驭；披上甲胄；利用; n. 马具；甲胄；挽具状带子；降落伞背带；日常工作', '/\'hɑːnɪs | \'hɑrnɪs/', 'harness', 5);
INSERT INTO `words` VALUES (25907, 'the harsh measures taken against the protesters', 'adj. 严厉的；严酷的；刺耳的；粗糙的；刺目的; n. (Harsh)人名；(英)哈什', '/hɑ:ʃ | hɑːʃ | hɑrʃ/', 'harsh', 5);
INSERT INTO `words` VALUES (25908, 'The company is now reaping the harvest of careful planning.', 'n. 收获；产量；结果; v. 收割；得到', '/\'hɑ:vist | \'hɑːvɪst | \'hɑrvɪst/', 'harvest', 5);
INSERT INTO `words` VALUES (25909, 'I soon regretted my haste.', 'n. 匆忙；急忙；轻率; vi. 匆忙；赶紧; vt. 赶快', '/heist | heɪst | hest/', 'haste', 5);
INSERT INTO `words` VALUES (25910, 'He soon regretted his hasty decision.', 'adj. 轻率的；匆忙的；草率的；懈怠的; n. (Hasty)人名；(英)黑斯蒂', '/\'heɪstɪ | \'hesti/', 'hasty', 5);
INSERT INTO `words` VALUES (25911, 'The problems do not end if crocodiles successfully hatch from the eggs.', 'n. 孵化；舱口; v. 孵；策划', '/hætʃ/', 'hatch', 5);
INSERT INTO `words` VALUES (25912, 'Why do you hate me so much?', 'v. 憎恨；厌恶；遗憾; n. 憎恨；反感', '/heit | heɪt | het/', 'hate', 5);
INSERT INTO `words` VALUES (25913, 'A look of pure hatred flashed across her face.', 'n. 憎恨；怨恨；敌意', '/\'heitrid | \'heɪtrɪd | \'hetrɪd/', 'hatred', 5);
INSERT INTO `words` VALUES (25914, 'The gang escaped with a haul worth hundreds of pounds.', 'n. 拖，拉；用力拖拉；努力得到的结果；捕获物；一网捕获的鱼量；拖运距离; v. 拖运；拖拉', '/hɔ:l | hɔːl | hɔl/', 'haul', 5);
