INSERT INTO `words` VALUES (26001, 'The hostess introduced them.', 'n. 女主人，女老板；女服务员；舞女；女房东', '/\'həustis | \'həʊstɪs; -es; həʊ\'stes | \'hostəs/', 'hostess', 5);
