INSERT INTO `words` VALUES (26008, 'Men are doing more housework nowadays.', 'n. 家务事', '/\'hauswə:k | \'haʊswɜːk | \'haʊs\'wɝk/', 'housework', 5);
INSERT INTO `words` VALUES (26009, 'government housing policy', 'n. 房屋；住房供给；[机] 外壳；遮盖物；机器等的防护外壳或外罩', '/\'hausiŋ | haʊzɪŋ | \'haʊzɪŋ/', 'housing', 5);
INSERT INTO `words` VALUES (26010, 'Her younger brother hovered in the background watching us.', 'v. 盘旋，翱翔；徘徊; n. 徘徊；盘旋；犹豫', '/\'hɔvə, \'hʌ- | \'hɒvə | \'hʌvɚ/', 'hover', 5);
INSERT INTO `words` VALUES (26011, 'Upstairs, one of the twins began to howl (= cry ) .', 'v. 咆哮；怒吼；狂吠; n. 嗥叫；怒号；嚎哭', '/haul | haʊl/', 'howl', 5);
INSERT INTO `words` VALUES (26012, 'We lay huddled together for warmth.', 'v. 把挤在一起；使缩成一团；草率了事; n. 拥挤；混乱；杂乱一团', '/\'hʌdl | \'hʌd(ə)l/', 'huddle', 5);
INSERT INTO `words` VALUES (26013, 'We stood there crying and hugging each other.', 'v. 拥抱；紧抱；抱有，坚持; n. 拥抱；紧抱；固执', '/hʌɡ | hʌg/', 'hug', 5);
INSERT INTO `words` VALUES (26014, 'a huge dog', 'adj. 巨大的；庞大的；无限的; n. (Huge)人名；(英)休奇', '/hju:dʒ | hjuːdʒ | hjudʒ/', 'huge', 5);
INSERT INTO `words` VALUES (26015, 'He began to hum a tune.', 'v. 发低哼声; n. 嗡嗡声；哼声；杂声; int. 哼；嗯', '/hʌm/', 'hum', 5);
INSERT INTO `words` VALUES (26016, 'There are many different cell types in the human body .', 'adj. 人的,人类的; n. 人', '/\'hju:mən | \'hjuːmən | \'hjumən/', 'human', 5);
INSERT INTO `words` VALUES (26017, 'We want a clean healthy environment for all humanity .', 'n. 人类,人性,人情;(pl.)人文科学', '/hju:\'mænəti | hjʊ\'mænɪtɪ | hjʊ\'mænəti/', 'humanity', 5);
INSERT INTO `words` VALUES (26018, 'a modest and humble man', 'adj. 谦逊的；简陋的；（级别或地位）低下的；不大的; v. 使谦恭；轻松打败（尤指强大的对手）；低声下气', '/\'hʌmbl/', 'humble', 5);
INSERT INTO `words` VALUES (26019, 'Tokyo is extremely humid in mid-summer.', 'adj. 湿的,湿气重的', '/\'hju:mid | \'hjuːmɪd | \'hjumɪd/', 'humid', 5);
INSERT INTO `words` VALUES (26020, 'The room is kept at 72 degrees and 50% relative humidity.', 'n. 湿气,湿度', '/hju:\'midəti | hjʊ\'mɪdɪtɪ | hju\'mɪdəti/', 'humidity', 5);
INSERT INTO `words` VALUES (26021, 'Her boss humiliated her in front of all her colleagues.', 'v. 羞辱；使…丢脸；耻辱', '/hju:\'milieit | hjʊ\'mɪlɪeɪt | hju\'mɪlɪet/', 'humiliate', 5);
INSERT INTO `words` VALUES (26022, 'Reading some books which contain humor or humorous stories is another.', 'n. 幽默，诙谐；心情; v. 迎合，迁就；顺应', '/\'hju:mə | ˈhjuːmə | \'hjʊmɚ/', 'humor', 5);
INSERT INTO `words` VALUES (26023, 'humorous stories', 'adj. 幽默的， 诙谐的', '/\'hjuːmərəs | \'hjumərəs/', 'humorous', 5);
INSERT INTO `words` VALUES (26024, 'his humour and charm', 'n. 幽默， 诙谐', '/\'hjuːmə | \'hju:mə/', 'humour', 5);
INSERT INTO `words` VALUES (26025, 'Try to satisfy your hunger by eating some fruit.', 'n. 饿，饥饿；渴望; v. 渴望；挨饿', '/\'hʌŋɡə | \'hʌŋgə | \'hʌŋɡɚ/', 'hunger', 5);
INSERT INTO `words` VALUES (26026, 'the slopes where I hunted deer as a kid', 'v. 打猎； 猎取；搜索； 寻找; n. 打猎， 猎取；搜索； 寻找', '/hʌnt/', 'hunt', 5);
INSERT INTO `words` VALUES (26027, 'Demonstrators were hurling bricks through the windows.', 'v. 丢下；用力投掷；愤慨地说出; n. 用力的投掷', '/hə:l | hɜːl | hɝl/', 'hurl', 5);
INSERT INTO `words` VALUES (26028, 'The hurricane devastated a large section of the coast.', 'n. 飓风，暴风', '/\'hʌrikən | \'hʌrɪk(ə)n; -keɪn | hʌrɪˌken/', 'hurricane', 5);
INSERT INTO `words` VALUES (26029, 'Sorry, I can’t stop, I’m in a hurry.', 'n. 匆忙，急忙; v. 仓促（做某事）；催促；（朝某方向）迅速移动；迅速处理', '/\'hʌrɪ | \'hɝrɪ/', 'hurry', 5);
INSERT INTO `words` VALUES (26030, 'Have you met my husband Roy?', 'n. 丈夫', '/\'hʌzbənd/', 'husband', 5);
INSERT INTO `words` VALUES (26031, 'a wooden hut', 'n. 小屋；临时营房; vt. 使住在小屋中；驻扎; vi. 住在小屋中；驻扎', '/hʌt/', 'hut', 5);
INSERT INTO `words` VALUES (26032, 'Water contains hydrogen and oxygen.', 'n. [化学] 氢', '/\'haidrədʒən | \'haɪdrədʒ(ə)n | \'haɪdrədʒən/', 'hydrogen', 5);
INSERT INTO `words` VALUES (26033, 'the importance of personal hygiene', 'n. 卫生', '/\'haɪdʒiːn | \'haɪdʒin/', 'hygiene', 5);
INSERT INTO `words` VALUES (26034, 'It would be sheer hypocrisy to pray for success, since I’ve never believed in God.', 'n. 虚伪；伪善', '/hi\'pɔkrisi | hɪ\'pɒkrɪsɪ | hɪ\'pɑkrəsi/', 'hypocrisy', 5);
INSERT INTO `words` VALUES (26035, 'One hypothesis is that the victim fell asleep while driving.', 'n. 假设', '/hai\'pɔθisis | haɪ\'pɒθɪsɪs | haɪ\'pɑθəsɪs/', 'hypothesis', 5);
INSERT INTO `words` VALUES (26036, 'Janet became hysterical and began screaming.', 'adj. 歇斯底里的；异常兴奋的', '/his\'terikəl | hɪ\'sterɪk(ə)l | hɪ\'stɛrɪkl/', 'hysterical', 5);
INSERT INTO `words` VALUES (26037, 'advice on how to reach your ideal weight', 'adj. 理想的；完美的；想象的；不切实际的; n. 理想；典范', '/ai\'diəl | aɪ\'dɪəl; aɪ\'diːəl | aɪ\'diəl/', 'ideal', 5);
INSERT INTO `words` VALUES (26038, 'four identical houses', 'adj. 同一的；完全相同的; n. 完全相同的事物', '/ai\'dentikəl | aɪ\'dentɪk(ə)l | aɪ\'dɛntɪkl/', 'identical', 5);
INSERT INTO `words` VALUES (26039, 'His body was taken to Brighton mortuary for identification.', 'n. 识别,鉴别;证件;认同', '/ai,dentifi\'keiʃən | aɪ,dentɪfɪ\'keɪʃ(ə)n | aɪˌdentɪfɪ\'keʃn/', 'identification', 5);
INSERT INTO `words` VALUES (26040, 'He was too far away to be able to identify faces.', 'v. 识别,鉴别;(with)把…和…看成一样', '/aɪ\'dentɪfaɪ | aɪ\'dɛntɪfaɪ/', 'identify', 5);
INSERT INTO `words` VALUES (26041, 'The identity of the killer is still unknown.', 'n. 身份；同一性，一致；特性；恒等式', '/ai\'dentəti | aɪ\'dentɪtɪ | aɪ\'dɛntəti/', 'identity', 5);
INSERT INTO `words` VALUES (26042, 'the ideologies of fascism and terrorism', 'n. 意识形态，(政治或社会的)思想意识', '/,aidi\'ɔlədʒi, ,idi- | ,aɪdɪ\'ɒlədʒɪ; ɪd-/', 'ideology', 5);
INSERT INTO `words` VALUES (26043, 'the new musical idiom', 'n. 成语，习语；土话', '/\'idiəm | \'ɪdɪəm/', 'idiom', 5);
INSERT INTO `words` VALUES (26044, 'It was all your fault, you idiot.', 'n. 笨蛋，傻瓜；白痴', '/\'idiət | \'ɪdɪət/', 'idiot', 5);
INSERT INTO `words` VALUES (26045, 'I cannot afford to leave the land lying idle.', 'adj. 空闲的， 闲置的；无用的， 无效的；懒散的; vt. 浪费， 虚度', '/\'aɪdl/', 'idle', 5);
INSERT INTO `words` VALUES (26046, 'The petrol tank suddenly ignited.', 'v. 点燃；使燃烧；使激动', '/iɡ\'nait | ɪg\'naɪt | ɪɡ\'naɪt/', 'ignite', 5);
INSERT INTO `words` VALUES (26047, 'Excuse my ignorance, but how does it actually work?', 'n. 无知，愚昧；不知，不懂', '/\'iɡnərəns | \'ɪgn(ə)r(ə)ns | \'ɪɡnərəns/', 'ignorance', 5);
INSERT INTO `words` VALUES (26048, 'an ignorant and uneducated man', 'adj. 无知的；愚昧的', '/\'iɡnərənt | \'ɪgn(ə)r(ə)nt | \'ɪɡnərənt/', 'ignorant', 5);
INSERT INTO `words` VALUES (26049, 'You can’t ignore the fact that many criminals never go to prison.', 'v. 驳回诉讼；忽视；不理睬', '/iɡ\'nɔ: | ɪg\'nɔː | ɪɡ\'nɔr/', 'ignore', 5);
INSERT INTO `words` VALUES (26050, 'illegal drugs', 'adj. [法] 非法的；违法的；违反规则的; n. 非法移民，非法劳工', '/ɪ\'liːg(ə)l | ɪ\'ligl/', 'illegal', 5);
INSERT INTO `words` VALUES (26051, 'It was an illiterate letter, full of mistakes.', 'adj. 文盲的；不识字的；没受教育的; n. 文盲', '/i\'litərət | ɪ\'lɪt(ə)rət | ɪ\'lɪtərət/', 'illiterate', 5);
INSERT INTO `words` VALUES (26052, 'She had all the normal childhood illnesses.', 'n. 病；疾病', '/\'ilnis | ˈɪlnəs | \'ɪlnəs/', 'illness', 5);
INSERT INTO `words` VALUES (26053, 'A single candle illuminated his face.', 'v. 照亮，照明；用灯光装饰；说明，阐释', '/i\'lju:mineit | ɪ\'l(j)uːmɪneɪt | ɪ\'lumɪnet/', 'illuminate', 5);
INSERT INTO `words` VALUES (26054, 'She was under no illusion that he loved her.', 'n. 幻想，错误的观念；错觉，幻觉，假象', '/i\'lju:ʒən | ɪ\'l(j)uːʒ(ə)n | ɪ\'luʒn/', 'illusion', 5);
INSERT INTO `words` VALUES (26055, 'Let me give an example to illustrate the point.', 'v. 举例说明,阐明;图解,加插图', '/\'iləstreit | \'ɪləstreɪt | \'ɪləstret/', 'illustrate', 5);
INSERT INTO `words` VALUES (26056, 'The book contains 62 pages of illustrations.', 'n. 说明；例证，插图；举例说明', '/,ilə\'streiʃən | ɪlə\'streɪʃ(ə)n | ,ɪlə\'streʃən/', 'illustration', 5);
INSERT INTO `words` VALUES (26057, 'She peered closely at her image in the mirror.', 'n. 影像；想象；肖像；偶像; v. 想象；反映；象征；作…的像', '/\'imidʒ | \'ɪmɪdʒ/', 'image', 5);
INSERT INTO `words` VALUES (26058, 'As she listened, she played an imaginary piano on her knees.', 'adj. 虚构的，假想的；想像的；虚数的', '/i\'mædʒinəri | ɪ\'mædʒɪn(ə)rɪ | ɪ\'mædʒɪnɛri/', 'imaginary', 5);
INSERT INTO `words` VALUES (26059, 'a storyteller with an incredible imagination', 'n. [心理] 想象力；空想；幻想物', '/i,mædʒi\'neiʃən | ɪ,mædʒɪ\'neɪʃ(ə)n | ɪ,mædʒɪ\'neʃən/', 'imagination', 5);
INSERT INTO `words` VALUES (26060, 'an imaginative use of computer technology', 'adj. 富于想象的；有创造力的', '/ɪ\'mædʒɪnətɪv/', 'imaginative', 5);
INSERT INTO `words` VALUES (26061, 'Perhaps she’d never really been there at all – perhaps she’d just imagined it.', 'v. 想像；猜想；臆断', '/i\'mædʒin | ɪ\'mædʒɪn/', 'imagine', 5);
INSERT INTO `words` VALUES (26062, 'She was a splendid mimic and loved to imitate Winston Churchill.', 'v. 模仿，仿效；仿造，仿制', '/\'imiteit | \'ɪmɪteɪt | \'ɪmɪtet/', 'imitate', 5);
INSERT INTO `words` VALUES (26063, 'The remake of ‘Casablanca’ was a pale imitation (= something that is much less good than the thing it imitates ) of the original movie.', 'n. 模仿，仿造；仿制品; adj. 人造的，仿制的', '/,imi\'teiʃən | ɪmɪ\'teɪʃ(ə)n | ,ɪmɪ\'teʃən/', 'imitation', 5);
INSERT INTO `words` VALUES (26064, 'Our immediate response to the attack was sheer horror.', 'adj. 立即的,即时的;直接的,最接近的', '/i\'mi:diət | ɪ\'miːdɪət | ɪ\'midɪət/', 'immediate', 5);
INSERT INTO `words` VALUES (26065, 'People who travel by rail still read an immense amount.', 'adj. 巨大的，广大的；无边无际的；非常好的', '/i\'mens | ɪ\'mens | ɪ\'mɛns/', 'immense', 5);
INSERT INTO `words` VALUES (26066, 'The electrodes are immersed in liquid.', 'v. 使沉浸在;使浸没', '/i\'mə:s | ɪ\'mɜːs | ɪ\'mɝs/', 'immerse', 5);
INSERT INTO `words` VALUES (26067, 'But “the hostile part can be mobilized from time to time,” by what he calls “anti-immigrant entrepreneurs.', 'adj. 移民的；迁入的; n. 移民，侨民', '/\'imiɡrənt | \'ɪmɪgr(ə)nt | \'ɪmɪɡrənt/', 'immigrant', 5);
INSERT INTO `words` VALUES (26068, 'Once we’ve had the disease, we’re immune for life.', 'adj. 免疫的,有免疫力的;有受影响的;豁免的', '/i\'mju:n | ɪ\'mjuːn | ɪ\'mjʊn/', 'immune', 5);
INSERT INTO `words` VALUES (26069, 'The force of the impact knocked the breath out of her.', 'n. 冲击， 碰撞；效果； 影响', '/\'ɪmpækt | ɪm\'pækt/', 'impact', 5);
INSERT INTO `words` VALUES (26070, 'The illness had impaired his ability to think and concentrate.', 'v. 损害；削弱；减少', '/im\'pεə | ɪm\'peə | ɪm\'pɛr/', 'impair', 5);
INSERT INTO `words` VALUES (26071, 'She had information that she couldn’t wait to impart.', 'v. 传授，给予；告知，通知', '/im\'pɑ:t | ɪm\'pɑːt | ɪm\'pɑrt/', 'impart', 5);
INSERT INTO `words` VALUES (26072, 'He turned away with an impatient gesture.', 'adj. 不耐烦的， 急躁的', '/ɪm\'peɪʃnt | ɪm\'peʃnt/', 'impatient', 5);
INSERT INTO `words` VALUES (26073, 'It is imperative that politicians should be good communicators.', 'adj. 必要的，不可避免的；紧急的；命令的，专横的；势在必行的；[语]祈使的; n. 必要的事；命令；需要；规则；[语]祈使语气', '/ɪm\'perətɪv | ɪm\'pɛrətɪv/', 'imperative', 5);
INSERT INTO `words` VALUES (26074, 'Britain’s imperial expansion in the 19th century', 'adj. 帝国的；皇帝的；至高无上的；威严的; n. 纸张尺寸；特等品', '/im\'piəriəl | ɪm\'pɪərɪəl | ɪm\'pɪrɪəl/', 'imperial', 5);
INSERT INTO `words` VALUES (26075, 'The discovery gave fresh impetus to the research.', 'n. 推动(力),促进', '/\'impitəs | \'ɪmpɪtəs/', 'impetus', 5);
INSERT INTO `words` VALUES (26076, 'The government promised to implement a new system to control financial loan institutions.', 'v. 实施，执行；实现，使生效; n. 工具，器具；手段', '/\'implimənt, \'impliment | \'ɪmplɪm(ə)nt | \'ɪmplɪmɛnt/', 'implement', 5);
INSERT INTO `words` VALUES (26077, 'This election has profound implications for the future of U.S. democracy.', 'n. 含义；暗示；牵连，卷入；可能的结果，影响', '/ɪmplɪ\'keɪʃ(ə)n | \'ɪmplɪ\'keʃən/', 'implication', 5);
INSERT INTO `words` VALUES (26078, '...an implicit warning to the Moroccans not to continue or repeat the military actions they began a week ago.', 'adj. 含蓄的；暗示的；盲从的', '/im\'plisit | ɪm\'plɪsɪt/', 'implicit', 5);
INSERT INTO `words` VALUES (26079, 'an implied threat', 'v. 意味；暗示；隐含', '/im\'plai | ɪm\'plaɪ | ɪm\'plai/', 'imply', 5);
INSERT INTO `words` VALUES (26080, 'In 2001, Britain exported more cars than it imported.', 'v&n. 进口,输入,(pl.)进口商品;要旨,含意', '/im\'pɔ:t, \'impɔ:t | ɪm\'pɔːt; \'ɪm- | \'ɪmpɔt/', 'import', 5);
INSERT INTO `words` VALUES (26081, 'He was full of his own importance (= he behaved in an annoying way which showed that he thought he was very important ).', 'n. 重要,重要性', '/im\'pɔ:təns | ɪm\'pɔːt(ə)ns | ɪm\'pɔrtns/', 'importance', 5);
INSERT INTO `words` VALUES (26082, 'a very important meeting', 'adj. 重要的,重大的;有地位的,有权力的', '/im\'pɔ:tənt | ɪm\'pɔːt(ə)nt | ɪm\'pɔrtnt/', 'important', 5);
INSERT INTO `words` VALUES (26083, 'Parents should beware of imposing their own tastes on their children.', 'v. 征(税);(on)把…强加给', '/im\'pəuz | ɪm\'pəʊz | ɪm\'poz/', 'impose', 5);
INSERT INTO `words` VALUES (26084, '‘I want to speak to Mr Franks.’ ‘I’m afraid that’s impossible.’', 'adj. 不可能的；难以忍受的，很难对付的', '/im\'pɔsəbl | ɪm\'pɒsɪb(ə)l | ɪm\'pɑsəbl/', 'impossible', 5);
INSERT INTO `words` VALUES (26085, 'Steve borrowed his dad’s sports car to impress his girlfriend.', 'v. 盖印；强征；传送；给予某人深刻印象; n. 印象，印记；特征，痕迹', '/im\'pres, \'impres | ɪm\'pres | ɪm\'prɛs/', 'impress', 5);
INSERT INTO `words` VALUES (26086, 'When we looked around the school we got a very good impression.', 'n. 印象；效果，影响；压痕，印记；感想；曝光（衡量广告被显示的次数。打开一个带有该广告的网页，则该广告的impression 次数增加一次）', '/ɪm\'preʃ(ə)n | ɪm\'prɛʃən/', 'impression', 5);
INSERT INTO `words` VALUES (26087, 'The figures certainly look impressive.', 'adj. 感人的；令人钦佩的；给人以深刻印象的', '/im\'presiv | ɪm\'presɪv | ɪm\'prɛsɪv/', 'impressive', 5);
INSERT INTO `words` VALUES (26088, 'a course for students wishing to improve their English', 'v. 改善,改进,增进;好转,进步', '/im\'pru:v | ɪm\'pruːv | ɪm\'pruv/', 'improve', 5);
INSERT INTO `words` VALUES (26089, 'Our results have shown some improvement this month.', 'n. 改进,进步,增进;改进措施', '/ɪm\'pruːvm(ə)nt | ɪm\'prʊvmənt/', 'improvement', 5);
INSERT INTO `words` VALUES (26090, 'The eye converts light signals to nerve impulses.', 'n. 冲动；[电子] 脉冲；刺激；神经冲动；推动力; vt. 推动', '/\'impʌls | \'ɪmpʌls/', 'impulse', 5);
INSERT INTO `words` VALUES (26091, 'The Turner Prize was inaugurated in 1984.', 'vt. 开始， 开展；为…举行就职典礼， 使正式就任；为…举行开幕式， 为…举行落成仪式', '/ɪ\'nɔːgjəreɪt | ɪ\'nɔɡjəret/', 'inaugurate', 5);
INSERT INTO `words` VALUES (26092, 'As an added incentive, there’s a bottle of champagne for the best team.', 'n. 动机；刺激; adj. 激励的；刺激的', '/in\'sentiv | ɪn\'sentɪv | ɪn\'sɛntɪv/', 'incentive', 5);
INSERT INTO `words` VALUES (26093, 'The curtains were an inch too short.', 'n. 英寸；身高；少许; v. 使缓慢地移动', '/intʃ | ɪn(t)ʃ | ɪntʃ/', 'inch', 5);
INSERT INTO `words` VALUES (26094, 'The incidence of breast cancer increases with age.', 'n. 影响程度，影响范围；发生率', '/\'insidəns | \'ɪnsɪd(ə)ns | \'ɪnsɪdəns/', 'incidence', 5);
INSERT INTO `words` VALUES (26095, 'Am I at risk because of some incident in my sexual past?', 'n. 事件,事变', '/\'insidənt | \'ɪnsɪd(ə)nt | \'ɪnsɪdənt/', 'incident', 5);
INSERT INTO `words` VALUES (26096, 'Incidentally, where were you born?', 'adv. 附带地,顺便提及', '/,insi\'dentəli | ɪnsɪ\'dent(ə)lɪ | ,ɪnsɪ\'dɛntli/', 'incidentally', 5);
INSERT INTO `words` VALUES (26097, 'The telescope is inclined at an angle of 43 degrees.', 'v. 倾斜；倾向；易于; n. 倾斜；斜面；斜坡', '/in\'klain | ɪn\'klaɪn/', 'incline', 5);
INSERT INTO `words` VALUES (26098, 'Does the price include postage?', 'v. 包括,包含,计入', '/in\'klu:d | ɪn\'kluːd | ɪn\'klud/', 'include', 5);
INSERT INTO `words` VALUES (26099, 'Not everyone shares his vision of an inclusive America.', 'adj. (of)包括的,包含的;范围广的', '/in\'klu:siv | ɪn\'kluːsɪv | ɪn\'klusɪv/', 'inclusive', 5);
INSERT INTO `words` VALUES (26100, 'The agreement would allow the rebels to be incorporated into a new national police force.', 'v. 合并,纳入,结合; adj. 合并的', '/in\'kɔ:pəreit, in\'kɔ:pərət | ɪn\'kɔːpəreɪt/', 'incorporate', 5);
INSERT INTO `words` VALUES (26101, 'The population increased dramatically in the first half of the century.', 'v&n. 增加,增长,增进', '/in\'kri:s, \'inkri:s | ɪn\'kriːs | \'ɪnkris/', 'increase', 5);
INSERT INTO `words` VALUES (26102, 'Marketing techniques are becoming increasingly sophisticated.', 'adv. 不断增加地,日益', '/in\'kri:siŋli | ɪn\'kriːsɪŋlɪ | ɪn\'krisɪŋli/', 'increasingly', 5);
INSERT INTO `words` VALUES (26103, 'It’s incredible that he survived the fall.', 'adj. 难以置信的，惊人的', '/in\'kredəbl | ɪn\'kredɪb(ə)l | ɪn\'krɛdəbl/', 'incredible', 5);
INSERT INTO `words` VALUES (26104, 'The government had also incurred huge debts.', 'v. 招致,惹起,遭受', '/in\'kə: | ɪn\'kɜː | ɪn\'kɝ/', 'incur', 5);
INSERT INTO `words` VALUES (26105, 'The country has made great advances since independence.', 'n. 独立， 自主', '/ˌɪndɪ\'pendəns | ,ɪndɪ\'pɛndəns/', 'independence', 5);
INSERT INTO `words` VALUES (26106, 'There are plans to split the corporation into a number of smaller independent companies.', 'adj. 独立的， 自主的', '/ˌɪndɪ\'pendənt | \'ɪndɪ\'pɛndənt/', 'independent', 5);
INSERT INTO `words` VALUES (26107, '...the consumer price index.', 'n. 指标；指数；索引；指针; v. 做索引', '/\'indeks | \'ɪndeks | \'ɪndɛks/', 'index', 5);
INSERT INTO `words` VALUES (26108, 'The study indicates a connection between poverty and crime.', 'v. 指出,指示;表明,暗示', '/\'indikeit | \'ɪndɪkeɪt | \'ɪndɪket/', 'indicate', 5);
INSERT INTO `words` VALUES (26109, 'Could you give me some indication as to when I am likely to receive a reply?', 'n. 指出,指示;表明,暗示', '/,indi\'keiʃən | ɪndɪ\'keɪʃ(ə)n | ,ɪndɪ\'keʃən/', 'indication', 5);
INSERT INTO `words` VALUES (26110, 'His action is indicative of growing concern about the shortage of skilled labour.', 'adj. (of)指示的,暗示的', '/in\'dikətiv | ɪn\'dɪkətɪv/', 'indicative', 5);
INSERT INTO `words` VALUES (26111, 'an indifferent cook', 'adj. 漠不关心的；无关紧要的；中性的，中立的', '/in\'difərənt | ɪn\'dɪf(ə)r(ə)nt | ɪn\'dɪfrənt/', 'indifferent', 5);
INSERT INTO `words` VALUES (26112, 'an indignant reply', 'adj. 愤慨的,愤慨不平的', '/in\'diɡnənt | ɪn\'dɪgnənt | ɪn\'dɪɡnənt/', 'indignant', 5);
INSERT INTO `words` VALUES (26113, 'To his indignation, Charles found that his name was not on the list.', 'n. 愤怒,愤慨', '/,indiɡ\'neiʃən | ɪndɪg\'neɪʃ(ə)n | ,ɪndɪɡ\'neʃən/', 'indignation', 5);
INSERT INTO `words` VALUES (26114, 'Mobile phones have become an indispensable part of our lives.', 'adj. (to,for)必不可少的,必需的', '/,indis\'pensəbl | ɪndɪ\'spensəb(ə)l | \'ɪndɪ\'spɛnsəbl/', 'indispensable', 5);
INSERT INTO `words` VALUES (26115, 'Each individual leaf on the tree is different.', 'adj. 个人的,单独的;独特的; n. 个人,个体', '/,indi\'vidjuəl, -dʒəl | ɪndɪ\'vɪdjʊ(ə)l | ,ɪndɪ\'vɪdʒuəl/', 'individual', 5);
INSERT INTO `words` VALUES (26116, 'an indoor swimming pool', 'adj. 室内的，户内的', '/\'indɔ: | \'ɪndɔː | \'ɪndɔr/', 'indoor', 5);
INSERT INTO `words` VALUES (26117, 'Patients with eating disorders may use drugs to induce vomiting.', 'v. 引诱,劝使;引起,导致;感应', '/in\'dju:s, in\'du:s | ɪn\'djuːs | ɪn\'dus/', 'induce', 5);
INSERT INTO `words` VALUES (26118, 'His mother spoiled him, indulging his every whim.', 'v. 满足；纵容；使高兴；使沉迷于…', '/in\'dʌldʒ | ɪn\'dʌldʒ/', 'indulge', 5);
INSERT INTO `words` VALUES (26119, 'By 1900, Britain was a mainly industrial society.', 'adj. 工业的； 产业的', '/ɪn\'dʌstriəl | ɪn\'dʌstrɪəl/', 'industrial', 5);
INSERT INTO `words` VALUES (26120, 'The way to bring cost down is to industrialise much of the process.', 'vt. 使工业化', '/in\'dʌstriəlaiz | ɪn\'dʌstriəlaɪz/', 'industrialise', 5);
INSERT INTO `words` VALUES (26121, 'Energy consumption rises as countries industrialize.', 'v. 使工业化', '/in\'dʌtriəlaiz | ɪnˈdʌstrɪəlʌɪz | ɪn\'dʌstrɪəlaɪz/', 'industrialize', 5);
INSERT INTO `words` VALUES (26122, 'political inertia', 'n. [力] 惯性；惰性，迟钝；不活动', '/i\'nə:ʃiə | ɪ\'nɜːʃə | ɪ\'nɝʃə/', 'inertia', 5);
INSERT INTO `words` VALUES (26123, 'A further escalation of the crisis now seems inevitable.', 'adj. 不可避免的,必然发生的', '/in\'evitəbl | ɪn\'evɪtəb(ə)l | ɪn\'ɛvɪtəbl/', 'inevitable', 5);
INSERT INTO `words` VALUES (26124, 'An infant’s skin is very sensitive.', 'n. 婴儿；幼儿；未成年人; adj. 婴儿的；幼稚的；初期的；未成年的', '/\'infənt | \'ɪnf(ə)nt | \'ɪnfənt/', 'infant', 5);
INSERT INTO `words` VALUES (26125, 'People with the virus may feel perfectly well, but they can still infect others.', 'v. 传染，感染；影响(思想等)', '/in\'fekt | ɪn\'fekt | ɪn\'fɛkt/', 'infect', 5);
INSERT INTO `words` VALUES (26126, 'infectious diseases', 'adj. 传染的,传染性的,有感染力的', '/in\'fekʃəs | ɪn\'fekʃəs | ɪn\'fɛkʃəs/', 'infectious', 5);
INSERT INTO `words` VALUES (26127, 'I inferred from what she said that you have not been well.', 'v. 推断；推论', '/in\'fə: | ɪn\'fɜː | ɪn\'fɝ/', 'infer', 5);
INSERT INTO `words` VALUES (26128, 'There were two inferences to be drawn from her letter.', 'n. 推理；推论；推断', '/\'infərəns | \'ɪnf(ə)r(ə)ns | \'ɪnfərəns/', 'inference', 5);
INSERT INTO `words` VALUES (26129, 'I felt very inferior among all those academics.', 'adj. 差的；自卑的；下级的，下等的; n. 下级；次品', '/in\'fiəriə | ɪn\'fɪərɪə | ɪn\'fɪrɪɚ/', 'inferior', 5);
INSERT INTO `words` VALUES (26130, 'The universe is infinite.', 'adj. 无限的,无穷的; n. 无限', '/\'infinət | \'ɪnfɪnət/', 'infinite', 5);
INSERT INTO `words` VALUES (26131, 'Inflation is now at over 16%.', 'n. 膨胀；通货膨胀；夸张；自命不凡', '/in\'fleiʃən | ɪn\'fleɪʃ(ə)n | ɪn\'fleʃən/', 'inflation', 5);
INSERT INTO `words` VALUES (26132, 'As a scientist, his influence was immense.', 'n. 影响；势力；感化；有影响的人或事; v. 影响；改变', '/\'influəns | \'ɪnflʊəns | \'ɪnfluəns/', 'influence', 5);
INSERT INTO `words` VALUES (26133, 'He had influential friends.', 'adj. 有影响的；有势力的; n. 有影响力的人物', '/,ɪnflʊ\'enʃ(ə)l | ,ɪnflu\'ɛnʃl/', 'influential', 5);
INSERT INTO `words` VALUES (26134, 'They would inform him of any progress they had made.', 'v. (of,about)通知,告诉,报告;告发,告密', '/in\'fɔ:m | ɪn\'fɔːm | ɪn\'fɔrm/', 'inform', 5);
INSERT INTO `words` VALUES (26135, 'I need more information.', 'n. 通知,报告;情报,资料,消息;信息', '/,infə\'meiʃən | ɪnfə\'meɪʃ(ə)n | \'ɪnfɚ\'meʃən/', 'information', 5);
INSERT INTO `words` VALUES (26136, 'Both the model and the satellite sensor use infrared energy to measure clouds.', 'n. 红外线; adj. 红外线的', '/,infrə\'red | ɪnfrə\'red | ,ɪnfrə\'rɛd/', 'infrared', 5);
INSERT INTO `words` VALUES (26137, 'Some countries lack a suitable economic infrastructure.', 'n. 基础设施；公共建设；下部构造', '/\'infrə,strʌktʃə | \'ɪnfrəstrʌktʃə | \'ɪnfrə\'strʌktʃɚ/', 'infrastructure', 5);
INSERT INTO `words` VALUES (26138, 'Many fish have ingenious ways of protecting their eggs from predators.', 'adj. 机敏的;有独创性的;精致的;精巧制成的', '/in\'dʒi:njəs | ɪn\'dʒiːnɪəs | ɪn\'dʒinɪəs/', 'ingenious', 5);
INSERT INTO `words` VALUES (26139, 'Combine all the ingredients in a large bowl.', 'n. 原料；要素；组成部分; adj. 构成组成部分的', '/in\'ɡri:diənt | ɪn\'griːdɪənt | ɪn\'ɡridɪənt/', 'ingredient', 5);
INSERT INTO `words` VALUES (26140, 'The woods are inhabited by many wild animals.', 'v. 栖息；居住于；占据', '/in\'hæbit | ɪn\'hæbɪt/', 'inhabit', 5);
INSERT INTO `words` VALUES (26141, 'a city of six million inhabitants', 'n. 居民；居住者', '/in\'hæbitənt | ɪn\'hæbɪt(ə)nt | ɪn\'hæbɪtənt/', 'inhabitant', 5);
INSERT INTO `words` VALUES (26142, 'It is dangerous to inhale ammonia fumes.', 'v. 吸入；猛吃猛喝', '/in\'heil | ɪn\'heɪl | ɪn\'hel/', 'inhale', 5);
INSERT INTO `words` VALUES (26143, 'Every business has its own inherent risks.', 'adj. 固有的,内在的,天生的', '/in\'hiərənt | ɪn\'hɪər(ə)nt; -\'her(ə)nt | ɪn\'hɪrənt/', 'inherent', 5);
INSERT INTO `words` VALUES (26144, 'inherited wealth', 'v. 继承(金钱等)，经遗传而得(性格、特征)', '/in\'herit | ɪn\'herɪt | ɪn\'hɛrɪt/', 'inherit', 5);
INSERT INTO `words` VALUES (26145, 'An unhappy family life may inhibit children’s learning.', 'v. 抑制；禁止', '/in\'hibit | ɪn\'hɪbɪt/', 'inhibit', 5);
INSERT INTO `words` VALUES (26146, 'an initial investment of £5,000', 'adj. 最初的；字首的; v. 用姓名的首字母签名; n. 词首大写字母', '/i\'niʃəl | ɪ\'nɪʃəl/', 'initial', 5);
INSERT INTO `words` VALUES (26147, 'They have decided to initiate legal proceedings against the newspaper.', 'v. 开始，创始；发起；使初步了解; n. 开始；新加入者，接受初步知识者; adj. 新加入的；接受初步知识的', '/i\'niʃieit, i\'niʃiət, -eit | ɪ\'nɪʃɪeɪt | ɪ\'nɪʃɪet/', 'initiate', 5);
INSERT INTO `words` VALUES (26148, 'Why don’t you take the initiative and ask him out?', 'n. 主动权；首创精神; adj. 主动的；自发的；起始的', '/i\'niʃiətiv, -ʃətiv | ɪ\'nɪʃɪətɪv; -ʃə- | ɪ\'nɪʃətɪv/', 'initiative', 5);
INSERT INTO `words` VALUES (26149, 'His son was injected with strong drugs.', 'v. 注射(药液等)；注入', '/in\'dʒekt | ɪn\'dʒekt | ɪn\'dʒɛkt/', 'inject', 5);
INSERT INTO `words` VALUES (26150, 'A number of bombs have exploded, seriously injuring at least five people.', 'v. 伤害，损害', '/\'indʒə | \'ɪndʒə | \'ɪndʒɚ/', 'injure', 5);
INSERT INTO `words` VALUES (26151, 'She was taken to hospital with serious head injuries.', 'n. 损伤， 损害， 毁坏', '/\'ɪndʒəri/', 'injury', 5);
INSERT INTO `words` VALUES (26152, 'The two companies have inked a deal.', 'v. 签署；涂墨水于; n. 墨水，墨汁；油墨', '/iŋk | ɪŋk/', 'ink', 5);
INSERT INTO `words` VALUES (26153, 'The next day, we drove inland.', 'n. 内地；内陆; adj. 内陆的；内地的；国内的; adv. 在内地；向内地；向内陆；在内陆', '/\'inlənd, -lænd | \'ɪnlənd; -lænd | ,ɪn\'lænd/', 'inland', 5);
INSERT INTO `words` VALUES (26154, 'There are several sheltered inlets along the coast.', 'n. 入口，进口；插入物；水湾; v. 引进; 嵌入; 插入;', '/\'ɪnlet | ɪnˌlɛt/', 'inlet', 5);
INSERT INTO `words` VALUES (26155, 'We’re staying at the Holiday Inn.', 'n. 小旅馆， 客栈', '/ɪn/', 'inn', 5);
INSERT INTO `words` VALUES (26156, 'an inner room', 'adj. 内部的， 里面的；内心的', '/\'ɪnə | \'ɪnɚ/', 'inner', 5);
INSERT INTO `words` VALUES (26157, 'Nobody would believe that I was innocent.', 'adj. 无辜的；无罪的；无知的; n. 天真的人；笨蛋', '/\'inəsənt | \'ɪnəs(ə)nt | \'ɪnəsnt/', 'innocent', 5);
INSERT INTO `words` VALUES (26158, 'We must encourage innovation if the company is to remain competitive.', 'n. 创新，革新；新方法', '/,inəu\'veiʃən | ˌɪnəˈveɪʃn | ,ɪnə\'veʃən/', 'innovation', 5);
INSERT INTO `words` VALUES (26159, 'She’s served on innumerable committees.', 'adj. 无数的，数不清的', '/i\'nuj:mərəbl | ɪ\'njuːm(ə)rəb(ə)l | ɪ\'nʊmərəbl/', 'innumerable', 5);
INSERT INTO `words` VALUES (26160, 'If the input data specified it, the file will close and the process terminates.', 'n. 投入；输入电路; v. [自][电子] 输入；将…输入电脑', '/\'input | \'ɪnpʊt | \'ɪn\'pʊt/', 'input', 5);
INSERT INTO `words` VALUES (26161, '‘Why are you doing that?’ the boy inquired.', 'v. 询问；打听；问好， 问候', '/ɪn\'kwaɪə | ɪn\'kwaɪr/', 'inquire', 5);
INSERT INTO `words` VALUES (26162, 'On further inquiry, it emerged that Malcolm had not been involved in the incident.', 'n. 探究；调查；质询', '/in\'kwaiəri | ɪn\'kwaɪrɪ | ɪn\'kwaɪri; \'ɪn,kwaɪri; \'ɪnkwəri; \'ɪŋkwaɪri/', 'inquiry', 5);
INSERT INTO `words` VALUES (26163, 'an insect bite', 'n. 昆虫；卑鄙的人', '/\'insekt | \'ɪnsekt | \'ɪnsɛkt/', 'insect', 5);
INSERT INTO `words` VALUES (26164, 'He took a small key from his pocket and slowly inserted it into the lock.', 'v. 插入；嵌入; n. 插入物；管芯；镶块；[机械]刀片', '/ɪn\'sɜːt | \'ɪnsɝt/', 'insert', 5);
INSERT INTO `words` VALUES (26165, 'the inside pages of the newspaper', 'adj. 里面的; adv. 在里面; n. 内部; prep. 在…里', '/,in\'said, \'in- | ɪn\'saɪd | \'ɪn\'saɪd/', 'inside', 5);
INSERT INTO `words` VALUES (26166, 'a woman of great insight', 'n. 洞察力；洞悉', '/\'insait | \'ɪnsaɪt | \'ɪn\'saɪt/', 'insight', 5);
INSERT INTO `words` VALUES (26167, 'Stay for supper – I insist!', 'v. (on)坚持要求,坚决主张,坚持', '/in\'sist | ɪn\'sɪst/', 'insist', 5);
INSERT INTO `words` VALUES (26168, 'I got out of the car to inspect the damage.', 'v. 检查,调查,视察', '/in\'spekt | ɪn\'spekt | ɪn\'spɛkt/', 'inspect', 5);
INSERT INTO `words` VALUES (26169, 'The Malvern Hills have provided inspiration for many artists and musicians over the decades.', 'n. 灵感;鼓舞,激励', '/,inspə\'reiʃən | ˌɪnspəˈreɪʃn | ˌɪnspəˈreʃən/', 'inspiration', 5);
INSERT INTO `words` VALUES (26170, 'We need someone who can inspire the team.', 'v. 鼓舞,激起;使产生灵感', '/in\'spaiə | ɪn\'spaɪə | ɪn\'spaɪɚ/', 'inspire', 5);
INSERT INTO `words` VALUES (26171, 'the instability of the market', 'n. 不稳定', '/ˌɪnstə\'bɪləti | ,ɪnstə\'bɪləti/', 'instability', 5);
INSERT INTO `words` VALUES (26172, 'They’ve installed the new computer network at last.', 'v. 安装；任命；安顿', '/in\'stɔ:l | ɪnˈstɔ:l | ɪn\'stɔl/', 'install', 5);
INSERT INTO `words` VALUES (26173, 'the installation and maintenance of alarm systems', 'n. 安装，装置；就职', '/,instə\'leiʃən | ɪnstə\'leɪʃ(ə)n | \'ɪnstə\'leʃən/', 'installation', 5);
INSERT INTO `words` VALUES (26174, 'Now she can reduce the installment size that she can afford to pay, by extending the loan period.', 'n. 安装；分期付款；部分；就职', '/in\'stɔ:lmənt | ɪn\'stɔ:lmənt | ɪn\'stɔlmənt/', 'installment', 5);
INSERT INTO `words` VALUES (26175, 'the second instalment of a loan', 'n. 分期付款， 分期交付；一集； 一期', '/ɪn\'stɔːlmənt | ɪn\'stɔlm(ə)nt/', 'instalment', 5);
INSERT INTO `words` VALUES (26176, 'We need to rethink the way we consume energy. Take, for instance, our approach to transport.', 'n. 实例；情况；建议; v. 举为例', '/\'instəns | \'ɪnst(ə)ns | \'ɪnstəns/', 'instance', 5);
INSERT INTO `words` VALUES (26177, 'an instant success', 'adj. 立即的；紧急的；紧迫的; n. 瞬间；立即；片刻', '/\'instənt | \'ɪnst(ə)nt | \'ɪnstənt/', 'instant', 5);
INSERT INTO `words` VALUES (26178, 'modern methods of instantaneous communication', 'adj. 瞬间的；即时的；猝发的', '/,instən\'teinjəs | ,ɪnst(ə)n\'teɪnɪəs | ,ɪnstən\'tenɪəs/', 'instantaneous', 5);
INSERT INTO `words` VALUES (26179, 'Her instinct told her that something was wrong.', 'n. 本能，直觉；天性; adj. 充满着的', '/\'instiŋkt | \'ɪnstɪŋ(k)t | \'ɪnstɪŋkt/', 'instinct', 5);
INSERT INTO `words` VALUES (26180, 'We had no choice but to institute court proceedings against the airline.', 'v. 开始（调查）；制定；创立；提起（诉讼）; n. 学会，协会；学院', '/\'institjut, -tu:t | \'ɪnstɪtjuːt | \'ɪnstɪtut/', 'institute', 5);
INSERT INTO `words` VALUES (26181, 'powerful institutions such as world banks', 'n. 制度；建立；（社会或宗教等）公共机构；习俗', '/,insti\'tju:ʃən | ɪnstɪ\'tjuːʃ(ə)n | ,ɪnstɪ\'tuʃən/', 'institution', 5);
INSERT INTO `words` VALUES (26182, 'Eva went straight to the hotel, as instructed (= as she had been told ).', 'v. 指导；通知；命令；教授', '/in\'strʌkt | ɪn\'strʌkt/', 'instruct', 5);
INSERT INTO `words` VALUES (26183, 'Press ‘Enter’ and follow the on-screen instructions.', 'n. 指令，命令；指示；教导；用法说明', '/in\'strʌkʃən | ɪn\'strʌkʃ(ə)n | ɪn\'strʌkʃən/', 'instruction', 5);
INSERT INTO `words` VALUES (26184, 'surgical instruments', 'n. 仪器；工具；乐器；手段；器械', '/\'instrumənt, \'instrə-, -ment | \'ɪnstrʊm(ə)nt | \'ɪnstrəmənt/', 'instrument', 5);
INSERT INTO `words` VALUES (26185, '...a CD of vocal and instrumental music.', 'adj. 乐器的；有帮助的；仪器的，器械的; n. 器乐曲；工具字，工具格', '/,instru\'mentəl, ,instrə- | ɪnstrʊ\'ment(ə)l | ,ɪnstrə\'mɛntl/', 'instrumental', 5);
INSERT INTO `words` VALUES (26186, 'an insulated attic', 'v. 隔离,孤立;使绝缘,使绝热', '/\'insjuleit, \'insə- | \'ɪnsjʊleɪt | ˈɪnsəˌleɪt ; ˈɪnsjʊˌleɪt/', 'insulate', 5);
INSERT INTO `words` VALUES (26187, 'Nobody insults my family and gets away with it!', 'v. /n.侮辱,凌辱', '/in\'sʌlt | ɪn\'sʌlt/', 'insult', 5);
INSERT INTO `words` VALUES (26188, 'Your father took out insurance to cover the mortgage.', 'n. 保险；保险费；保险契约；赔偿金', '/in\'ʃuərəns | ɪn\'ʃʊər(ə)ns | ɪn\'ʃʊrəns/', 'insurance', 5);
INSERT INTO `words` VALUES (26189, 'Have you insured the contents of your home?', 'v. 确保，保证；给…保险', '/in\'ʃuə | ɪn\'ʃɔː; ɪn\'ʃʊə | ɪn\'ʃʊr/', 'insure', 5);
INSERT INTO `words` VALUES (26190, 'Only the medieval tower had remained intact.', 'adj. 完整无缺的,未经触动的,未受损伤的', '/in\'tækt | ɪn\'tækt/', 'intact', 5);
INSERT INTO `words` VALUES (26191, 'Rituals, celebrations, and festivals form an integral part of every human society.', 'adj. 积分的；完整的，整体的；构成整体所必须的; n. 积分；部分；完整', '/ˈɪntɪɡrəl | \'ɪntɪɡrəl/', 'integral', 5);
INSERT INTO `words` VALUES (26192, 'The Marine Corps was the last service to integrate.', 'v. 使…完整；使…成整体；求…的积分；表示…的总和; adj. 整合的；完全的; n. 一体化；集成体', '/\'intiɡreit, \'intiɡrit, -ɡreit | \'ɪntɪgreɪt | \'ɪntɪɡret/', 'integrate', 5);
INSERT INTO `words` VALUES (26193, 'the territorial integrity of the country', 'n. 完整；正直；诚实；廉正', '/in\'teɡrəti | ɪn\'tegrɪtɪ | ɪn\'tɛɡrəti/', 'integrity', 5);
INSERT INTO `words` VALUES (26194, 'a leading British intellectual', 'n. 知识分子; adj. 智力的，理智的，有理解力的', '/,intə\'lektjuəl, -tʃuəl | ,ɪntə\'lektʃʊəl; -tjʊəl | ,ɪntə\'lɛktʃuəl/', 'intellectual', 5);
INSERT INTO `words` VALUES (26195, 'To be good at the game, you need a reasonable level of intelligence.', 'n. 智力,聪明;理解力;情报,消息,报导', '/ɪn\'telɪdʒ(ə)ns | ɪn\'tɛlɪdʒəns/', 'intelligence', 5);
INSERT INTO `words` VALUES (26196, 'a group of highly intelligent (= very intelligent )students', 'adj. 聪明的,明智的,理智的', '/in\'telidʒent | ɪn\'telɪdʒ(ə)nt | ɪn\'tɛlɪdʒənt/', 'intelligent', 5);
INSERT INTO `words` VALUES (26197, 'His reply was barely intelligible.', 'adj. 可理解的，明白易懂的，清楚的', '/in\'telidʒəbl | ɪn\'telɪdʒɪb(ə)l | ɪn\'tɛlɪdʒəbl/', 'intelligible', 5);
INSERT INTO `words` VALUES (26198, 'Maybe he intends to leave her.', 'v. 想要； 打算， 企图', '/ɪn\'tend | ɪn\'tɛnd/', 'intend', 5);
INSERT INTO `words` VALUES (26199, 'Young people today are under intense pressure to succeed.', 'adj. 强烈的；紧张的；非常的；热情的', '/in\'tens | ɪn\'tens | ɪn\'tɛns/', 'intense', 5);
INSERT INTO `words` VALUES (26200, 'The intensity of the hurricane was frightening.', 'n. 强度；强烈；[电子] 亮度；紧张', '/in\'tensəti | ɪn\'tensɪtɪ | ɪn\'tɛnsəti/', 'intensity', 5);
INSERT INTO `words` VALUES (26201, 'a one-week intensive course in English', 'adj. 加强的；集中的；透彻的；加强语气的; n. 加强器', '/in\'tensiv | ɪn\'tensɪv | ɪn\'tɛnsɪv/', 'intensive', 5);
INSERT INTO `words` VALUES (26202, 'They went into town with the intention of visiting the library.', 'n. 意图；目的；意向；愈合', '/in\'tenʃən | ɪn\'tenʃ(ə)n | ɪn\'tɛnʃən/', 'intention', 5);
INSERT INTO `words` VALUES (26203, 'While the other children interacted and played together, Ted ignored them.', 'v. 互相作用,互相影响', '/,intə\'rækt | ɪntər\'ækt | ,ɪntɚ\'ækt/', 'interact', 5);
INSERT INTO `words` VALUES (26204, 'social intercourse', 'n. 性交；交往；交流', '/\'intəkɔ:s | \'ɪntəkɔːs | \'ɪntɚkɔrs/', 'intercourse', 5);
INSERT INTO `words` VALUES (26205, 'That’s an interesting question.', 'adj. 有趣的；引起兴趣的，令人关注的', '/ˈɪntrɪstɪŋ，ˈɪntrəstɪŋ | \'ɪnt(ə)rɪstɪŋ | \'ɪntrəstɪŋ/', 'interesting', 5);
INSERT INTO `words` VALUES (26206, '...the development of better user interfaces.', 'n. 界面；<计>接口；交界面; v. （使通过界面或接口）接合，连接；[计算机]使联系', '/\'ɪntəfeɪs | \'ɪntɚ\'fes/', 'interface', 5);
INSERT INTO `words` VALUES (26207, 'My daughter-in-law said that I was interfering, but I was only trying to help.', 'v. 干涉；妨碍；打扰', '/,intə\'fiə | ɪntə\'fɪə | ,ɪntɚ\'fɪr/', 'interfere', 5);
INSERT INTO `words` VALUES (26208, 'Industrial relations should be free from state interference.', 'n. 干扰，冲突；干涉', '/,intə\'fiərəns | ɪntə\'fɪər(ə)ns | ,ɪntɚ\'fɪrəns/', 'interference', 5);
INSERT INTO `words` VALUES (26209, 'an interim report', 'adj. 临时的，暂时的；中间的；间歇的; n. 过渡时期，中间时期；暂定', '/\'intərim | \'ɪnt(ə)rɪm | \'ɪntərɪm/', 'interim', 5);
INSERT INTO `words` VALUES (26210, 'The interior of the church was dark.', 'n. 内部；本质; adj. 内部的；国内的；本质的', '/in\'tiəriə | ɪn\'tɪɜːrɪə | ɪn\'tɪrɪɚ/', 'interior', 5);
INSERT INTO `words` VALUES (26211, 'an intermediate stage during which the disease is dormant', 'v. 起媒介作用; adj. 中间的，中级的; n. [化学] 中间物；媒介', '/,intə\'mi:djət, -dieit | ,ɪntə\'miːdɪət | ,ɪntɚ\'midɪət/', 'intermediate', 5);
INSERT INTO `words` VALUES (26212, 'The weather forecast is for sun, with intermittent showers.', 'adj. 间歇的；断断续续的；间歇性', '/ɪntə\'mɪt(ə)nt | ,ɪntɚ\'mɪtənt/', 'intermittent', 5);
INSERT INTO `words` VALUES (26213, 'We have no interest in interfering in the internal affairs of other countries.', 'adj. 内部的；内在的；国内的', '/in\'tə:nəl | ɪn\'tɜːn(ə)l | ɪn\'tɝnl/', 'internal', 5);
INSERT INTO `words` VALUES (26214, 'the response of the international community', 'n. 国际组织；国际体育比赛；外国居留者；国际股票; adj. 国际的；两国（或以上）国家的；超越国界的；国际关系的；世界的', '/ɪntə\'næʃ(ə)n(ə)l | ,ɪntɚ\'næʃnəl/', 'international', 5);
INSERT INTO `words` VALUES (26215, NULL, 'n. 因特网', '/\'intənet | \'ɪntənet | \'ɪntɚnɛt/', 'internet', 5);
INSERT INTO `words` VALUES (26216, 'They spoke good Spanish, and promised to interpret for me.', 'v. 说明；口译', '/in\'tə:prit | ɪn\'tɜːprɪt | ɪn\'tɝprɪt/', 'interpret', 5);
INSERT INTO `words` VALUES (26217, 'Will you stop interrupting me!', 'v. 中断；打断；插嘴；妨碍; n. 中断', '/,intə\'rʌpt | ɪntə\'rʌpt | \'ɪntə\'rʌpt/', 'interrupt', 5);
INSERT INTO `words` VALUES (26218, 'We crossed at a busy intersection.', 'n. 交叉；十字路口；交集；交叉点', '/,intə\'sekʃən | ɪntə\'sekʃ(ə)n | ,ɪntɚ\'sɛkʃən/', 'intersection', 5);
INSERT INTO `words` VALUES (26219, 'He left the room, returning after a short interval with a message.', 'n. 间隔,间歇;(幕间或工间)休息', '/\'intəvəl | \'ɪntəv(ə)l | \'ɪntɚvl/', 'interval', 5);
INSERT INTO `words` VALUES (26220, 'The army will have to intervene to prevent further fighting.', 'v. (in)干涉,干预;插入,介入', '/,intə\'vi:n | ɪntə\'viːn | ,ɪntɚ\'vin/', 'intervene', 5);
INSERT INTO `words` VALUES (26221, 'a portfolio of work presented at interview', 'n. 接见，采访；面试，面谈; v. 采访；接见；对…进行面谈；对某人进行面试', '/\'intəvju: | \'ɪntəvjuː | \'ɪntɚvju/', 'interview', 5);
INSERT INTO `words` VALUES (26222, 'an intimate friend of Picasso’s', 'adj. 亲密的,密切的; n. 熟友,熟人', '/英 [\'ɪntɪmət] 美 [ˈɪntəmɪt] | \'ɪntɪmət | ˈɪntəmɪt/', 'intimate', 5);
INSERT INTO `words` VALUES (26223, 'Attempts to intimidate her failed.', 'v. 胁迫，威胁(某人做某事)', '/in\'timideit | ɪn\'tɪmɪdeɪt | ɪn\'tɪmɪdet/', 'intimidate', 5);
INSERT INTO `words` VALUES (26224, 'intricate patterns', 'adj. 复杂的；错综的，缠结的', '/\'intrikət | \'ɪntrɪkət/', 'intricate', 5);
INSERT INTO `words` VALUES (26225, 'It’s an exciting story of political intrigue and murder.', 'n. 阴谋；诡计；复杂的事；私通; v. 用诡计取得；激起的兴趣', '/in\'tri:ɡ, \'in- | ɪn\'triːg | \'ɪn\'triɡ/', 'intrigue', 5);
INSERT INTO `words` VALUES (26226, 'the intrinsic interest of the subject', 'adj. 本质的，固有的', '/in\'trinsik,-kəl | ɪn\'trɪnsɪk/', 'intrinsic', 5);
INSERT INTO `words` VALUES (26227, 'Have you two been introduced? Tom, this is Greg.', 'v. 介绍；引进，传入；提出(议案等)', '/,intrə\'dju:s | ɪntrə\'djuːs | ˌɪntrə\'dus/', 'introduce', 5);
INSERT INTO `words` VALUES (26228, 'Pete, are you going to make the introductions?', 'n. (to)介绍;传入,引进;导言,导论,绪论', '/,intrə\'dʌkʃən | ,ɪntrə\'dʌkʃ(ə)n | ,ɪntrə\'dʌkʃən/', 'introduction', 5);
INSERT INTO `words` VALUES (26229, 'Would I be intruding if I came with you?', 'v. 把…强加；把…硬挤', '/in\'tru:d | ɪn\'truːd | ɪn\'trʊd/', 'intrude', 5);
INSERT INTO `words` VALUES (26230, 'feminine intuition', 'n. 直觉；直觉力；直觉的知识', '/,intju:\'iʃən | ɪntjʊ\'ɪʃ(ə)n | ,ɪntu\'ɪʃən/', 'intuition', 5);
INSERT INTO `words` VALUES (26231, 'The Romans invaded Britain 2,000 years ago.', 'v. 入侵,侵略,侵袭,侵扰', '/in\'veid | ɪn\'veɪd | ɪn\'ved/', 'invade', 5);
INSERT INTO `words` VALUES (26232, 'I resented being treated as an invalid.', 'n. 病人,伤残人; adj. 有病的,伤残的;无效的', '/\'invəli:d, -lid, ,invə\'li:d, \'in- | ˈɪnvəlɪd；ɪnˈvælɪd/', 'invalid', 5);
INSERT INTO `words` VALUES (26233, 'I was able to gain invaluable experience over that year.', 'adj. 非常宝贵的,无价的', '/in\'væljuəbl | ɪn\'væljʊ(ə)b(ə)l | ɪn\'væljʊəbl/', 'invaluable', 5);
INSERT INTO `words` VALUES (26234, 'His invariable answer was ‘Wait and see.’', 'adj. 始终如一的， 不变的； 恒定的', '/ɪn\'veəriəbl | ɪn\'vɛrərɪəbl/', 'invariable', 5);
INSERT INTO `words` VALUES (26235, 'It invariably rains when I go there.', 'adv. 总是；不变地；一定地', '/in\'vɛəriəbli | ɪn\'veərɪəblɪ | ɪn\'vɛrɪəbli/', 'invariably', 5);
INSERT INTO `words` VALUES (26236, '...seven years after the Roman invasion of Britain.', 'n. 入侵,侵略,侵犯', '/in\'veiʒən | ɪn\'veɪʒ(ə)n | ɪn\'veʒn/', 'invasion', 5);
INSERT INTO `words` VALUES (26237, 'Alexander Graham Bell invented the telephone in 1876.', 'v. 发明,创造;捏造,虚构', '/in\'vent | ɪn\'vent | ɪn\'vɛnt/', 'invent', 5);
INSERT INTO `words` VALUES (26238, 'The dishwasher is a wonderful invention.', 'n. 发明,创造,发明物', '/in\'venʃən | ɪn\'venʃ(ə)n | ɪn\'vɛnʃən/', 'invention', 5);
INSERT INTO `words` VALUES (26239, '...one inventory of twelve sails for each yacht.', 'n. 详细目录,存货,财产清册,总量', '/\'invəntəri, -tɔ:ri | \'ɪnv(ə)nt(ə)rɪ | \'ɪnvəntɔri/', 'inventory', 5);
INSERT INTO `words` VALUES (26240, 'Clearly, the amount of money people save increases in inverse proportion to the amount they spend.', 'adj. 相反的,倒转的,反转的; n. 相反之物; v. 倒转', '/\'invə:s, in\'v-, in\'və:s | \'ɪnvɜːs; ɪn\'vɜːs | ,ɪn\'vɝs/', 'inverse', 5);
INSERT INTO `words` VALUES (26241, 'Invert the cake onto a serving plate.', 'v. 倒置,倒转,颠倒', '/in\'və:t, \'invə:t | ɪn\'vɜːt | \'ɪnvɝt/', 'invert', 5);
INSERT INTO `words` VALUES (26242, 'I’ve got a few thousand dollars I’m looking to invest.', 'v. 投资；覆盖；耗费；授予；包围', '/in\'vest | ɪn\'vest | ɪn\'vɛst/', 'invest', 5);
INSERT INTO `words` VALUES (26243, 'The state police are investigating the incident.', 'v. 调查；研究', '/in\'vestiɡeit | ɪn\'vestɪgeɪt | ɪn\'vɛstɪɡet/', 'investigate', 5);
INSERT INTO `words` VALUES (26244, 'We plan to buy some property as an investment.', 'n. 投资；投入；封锁', '/in\'vestmənt | ɪn\'ves(t)m(ə)nt | ɪn\'vɛstmənt/', 'investment', 5);
INSERT INTO `words` VALUES (26245, 'The house was surrounded by trees, and invisible from the road.', 'adj. 看不见的,无形的', '/in\'vizəbl | ɪn\'vɪzɪb(ə)l | ɪn\'vɪzəbl/', 'invisible', 5);
INSERT INTO `words` VALUES (26246, 'They were always dropping by, usually without invitation.', 'n. 邀请,招待;请柬', '/ɪnvɪ\'teɪʃ(ə)n | ˌɪnvɪˈteɪʃn/', 'invitation', 5);
INSERT INTO `words` VALUES (26247, 'I’m afraid I wasn’t invited.', 'v. 邀请,招待', '/in\'vait, \'invait | ɪn\'vaɪt/', 'invite', 5);
INSERT INTO `words` VALUES (26248, 'What will the job involve?', 'v. 卷入,陷入,连累;包含,含有,涉及', '/in\'vɔlv | ɪn\'vɒlv | ɪn\'vɑlv/', 'involve', 5);
INSERT INTO `words` VALUES (26249, 'He pushed open the front door, which swung inward with a groan.', 'adv. 向内， 在内; adj. 在内的， 里面的； 内心的 <', '/\'ɪnwəd | \'ɪnwɚd/', 'inward', 5);
INSERT INTO `words` VALUES (26250, 'the iron and steel industry', 'n. 熨斗；烙铁；坚强; v. 熨；用铁铸成; adj. 铁的；残酷的；刚强的', '/\'aiən | \'aɪən | \'aɪɚn/', 'iron', 5);
INSERT INTO `words` VALUES (26251, 'Life is full of little ironies.', 'n. 讽刺；反语；具有讽刺意味的事; adj. 铁的；似铁的', '/\'aiərəni | \'aɪrənɪ | \'aɪrəni/', 'irony', 5);
INSERT INTO `words` VALUES (26252, 'The modularity system can then match you with what you need irrespective of which module provides it.', 'adj. 不顾的,不考虑的,无关的', '/,iri\'spektiv | ɪrɪ\'spektɪv | ,ɪrɪ\'spɛktɪv/', 'irrespective', 5);
INSERT INTO `words` VALUES (26253, 'The water in Lake Powell is used to irrigate the area.', 'v. 灌溉；冲洗；使清新', '/\'iriɡeit | \'ɪrɪgeɪt | \'ɪrəget/', 'irrigate', 5);
INSERT INTO `words` VALUES (26254, 'It really irritates me when he doesn’t help around the house.', 'v. 刺激，使兴奋；激怒', '/\'iriteit | \'ɪrɪteɪt | \'ɪrɪtet/', 'irritate', 5);
INSERT INTO `words` VALUES (26255, 'The Cayman Islands', 'n. 岛，岛屿；(道路上的)交通安全岛', '/\'ailənd | \'aɪlənd/', 'island', 5);
INSERT INTO `words` VALUES (26256, 'the British Isles', 'n. 小岛(用于诗歌中)', '/ail | aɪl/', 'isle', 5);
INSERT INTO `words` VALUES (26257, 'The town was isolated by the floods.', 'v. 隔离,孤立', '/\'aisəleit, -lit | \'aɪsəleɪt | aɪslˌet/', 'isolate', 5);
INSERT INTO `words` VALUES (26258, 'Abortion is a highly controversial issue.', 'n. 问题；流出；期号；发行物; v. 发行，发布；发给；放出，排出', '/\'iʃju:, \'isju: | \'ɪʃuː; \'ɪsjuː | \'ɪʃu/', 'issue', 5);
INSERT INTO `words` VALUES (26259, 'He opened the cardboard box and took out each item.', 'n. 条款，项目；一则；一件商品（或物品）; adj. 又，同上; v. 记下；逐条列出', '/\'aɪtəm/', 'item', 5);
INSERT INTO `words` VALUES (26260, 'an ivory chess set', 'n. 象牙；象牙色， 乳白色', '/\'aɪvəri/', 'ivory', 5);
INSERT INTO `words` VALUES (26261, 'Gene has to wear a jacket and tie to work.', 'n. 羽绒滑雪衫；西装短外套；短上衣，夹克；土豆皮；书籍的护封；文件套，公文夹; v. 给…穿夹克；给…装护套；给…包上护封；〈口〉打', '/\'dʒækɪt/', 'jacket', 5);
INSERT INTO `words` VALUES (26262, 'He’s been in jail for three months already.', 'n. 监狱， 拘留所; vt. 监禁某人', '/dʒeɪl | dʒel/', 'jail', 5);
INSERT INTO `words` VALUES (26263, 'strawberry jam', 'n. 果酱；拥挤；困境；扣篮; v. 使堵塞；挤进，使塞满；混杂；压碎', '/dʒæm/', 'jam', 5);
INSERT INTO `words` VALUES (26264, 'We always have snow in January.', 'n. 一月', '/\'dʒænjuəri | \'dʒænjʊ(ə)rɪ | \'dʒænjʊ\'ɛri/', 'january', 5);
INSERT INTO `words` VALUES (26265, 'a jam jar', 'n. 罐， 坛； 广口瓶', '/dʒɑː | dʒɑr/', 'jar', 5);
INSERT INTO `words` VALUES (26266, 'Keep it simple and avoid the use of jargon.', 'n. 行话，术语；黄锆石', '/\'dʒɑ:ɡən, -ɡɔn | \'dʒɑːg(ə)n | \'dʒɑrɡən/', 'jargon', 5);
INSERT INTO `words` VALUES (26267, 'a broken jaw', 'n. 颌；下巴；狭窄入口；唠叨; v. 教训；唠叨', '/dʒɔ: | dʒɔː | dʒɔ/', 'jaw', 5);
INSERT INTO `words` VALUES (26268, 'a jazz band', 'n. 爵士乐，爵士舞；喧闹; v. 奏爵士乐，跳爵士舞；游荡; adj. 爵士乐的；喧吵的', '/dʒæz/', 'jazz', 5);
INSERT INTO `words` VALUES (26269, 'She got insanely jealous and there was a terrible fight.', 'adj. 妒忌的；猜疑的；唯恐失去的；戒备的', '/\'dʒeləs | \'dʒɛləs/', 'jealous', 5);
INSERT INTO `words` VALUES (26270, '...a young man in jeans and a worn T-shirt.', 'n. 牛仔裤；工装裤', '/dʒi:nz/', 'jeans', 5);
INSERT INTO `words` VALUES (26271, 'He owns a private jet.', 'n. 喷射，喷嘴；喷气式飞机；黑玉; adj. 墨黑的; v. 射出', '/dʒet | jɛt | dʒɛt/', 'jet', 5);
INSERT INTO `words` VALUES (26272, 'She loved dressing up and wearing priceless jewels.', 'n. 宝石；珠宝; v. 镶以宝石；饰以珠宝', '/\'dʒu:əl | \'dʒuːəl | \'dʒuəl/', 'jewel', 5);
INSERT INTO `words` VALUES (26273, 'She wears a lot of gold jewelry.', 'n. 珠宝', '/\'dʒuːəlri | \'dʒu:əlri/', 'jewellery', 5);
INSERT INTO `words` VALUES (26274, 'Do you have anything to declare, jewelry or cash?', 'n. 珠宝；珠宝类', '/\'dʒu:əlri | \'dʒuːəlrɪ | \'dʒʊəlri/', 'jewelry', 5);
INSERT INTO `words` VALUES (26275, 'I go jogging every morning.', 'v. 慢跑；轻推；蹒跚行进；使颠簸; n. 慢跑；轻推，轻撞', '/dʒɔɡ | dʒɒg | dʒɑɡ/', 'jog', 5);
INSERT INTO `words` VALUES (26276, 'Many sacrificed their weekend to join the hunt for the missing girl.', 'v. 参加；结合；连接; n. 结合；连接；接合点', '/dʒɔin | dʒɒɪn | dʒɔɪn/', 'join', 5);
INSERT INTO `words` VALUES (26277, 'What should I use to seal the joint between the carport roof and the house wall?', 'n. 关节；接缝；接合处，接合点；（牛，羊等的腿）大块肉; adj. 共同的；连接的；联合的，合办的; v. 连接，贴合；接合；使有接头', '/dʒɔint | dʒɒɪnt | dʒɔɪnt/', 'joint', 5);
