INSERT INTO `words` VALUES (26475, 'They searched his luggage for illegal drugs.', 'n. 行李；皮箱', '/\'lʌɡidʒ | \'lʌgɪdʒ | \'lʌɡɪdʒ/', 'luggage', 5);
INSERT INTO `words` VALUES (26476, 'A blue bus lumbered past.', 'v. 伐木；喧闹地向前走；笨重地行动，缓慢地移动; n. 木材；废物，无用的杂物；隆隆声', '/\'lʌmbə | \'lʌmbɚ/', 'lumber', 5);
INSERT INTO `words` VALUES (26477, 'Strain the custard to remove lumps.', 'n. 块，块状；肿块；瘤；很多；笨人; v. 混在一起；使成块状；忍耐；笨重地移动; adj. 成团的；总共的; adv. 很；非常', '/lʌmp/', 'lump', 5);
