INSERT INTO `words` VALUES (26479, 'Smoking can cause lung cancer.', 'n. 肺', '/lʌŋ/', 'lung', 5);
INSERT INTO `words` VALUES (26480, 'The excitement of hunting big game in Africa has been a lure to Europeans for 200 years.', 'n. 吸引力,魅力,诱惑物; v. 引诱，吸引', '/ljuə | l(j)ʊə | lʊr/', 'lure', 5);
INSERT INTO `words` VALUES (26481, 'He was leading a life of luxury in Australia.', 'n. 奢侈,华贵;奢侈品; adj. 奢华的,豪华的', '/\'lʌkʃəri, \'lʌɡʒəri | \'lʌkʃ(ə)rɪ | \'lʌɡʒəri/', 'luxury', 5);
