INSERT INTO `words` VALUES (26489, 'It\'s possible to hang a nail from a magnet and then use that nail to pick up another nail.', 'n. 磁铁；[电磁] 磁体；磁石', '/\'mæɡnit | ˈmæɡnɪt | \'mægnɪt/', 'magnet', 5);
