INSERT INTO `words` VALUES (26494, 'a kitchen maid', 'n. 女仆；少女; vt. 侍候；做新娘的女傧相; vi. 当女仆', '/meid | meɪd | med/', 'maid', 5);
INSERT INTO `words` VALUES (26495, 'In 1912, the Titanic sank on her maiden voyage.', 'adj. 未婚的，处女的；初次的; n. 少女；处女', '/\'meidən | \'meɪd(ə)n | \'medn/', 'maiden', 5);
INSERT INTO `words` VALUES (26496, 'flights between a Greek island and the mainland', 'n. 大陆；本土; adj. 大陆的；本土的', '/\'meinlənd | \'meɪnlənd; -lænd | \'menlænd/', 'mainland', 5);
INSERT INTO `words` VALUES (26497, 'Careers Officers maintain contact with young people when they have left school.', 'v. 维持；继续；维修；主张；供养', '/mein\'tein | meɪn\'teɪn; mən\'teɪn | men\'ten/', 'maintain', 5);
