INSERT INTO `words` VALUES (26499, 'Out of those experiences, everything from pomp to humor to erotic charisma to grief to majesty to the profoundly gruesome and monumentally spiritual worked its way into his tone.', 'n. 威严；最高权威，王权；雄伟；权威', '/\'mædʒisti | \'mædʒɪstɪ | \'mædʒəsti/', 'majesty', 5);
INSERT INTO `words` VALUES (26500, 'The Labour Party won a huge majority at the last general election.', 'n. 多数；成年', '/mə\'dʒɔriti | mə\'dʒɒrɪtɪ | mə\'dʒɔrəti/', 'majority', 5);
INSERT INTO `words` VALUES (26501, 'a deep male voice', 'adj. 男性的；雄性的；有力的; n. 男人；雄性动物', '/meil | meɪl | mel/', 'male', 5);
INSERT INTO `words` VALUES (26502, 'She developed a malignant tumour in her breast.', 'adj. 恶性的，致命的；恶意的，恶毒的', '/mə\'liɡnənt | mə\'lɪgnənt/', 'malignant', 5);
