INSERT INTO `words` VALUES (26504, 'There were two men and a woman in the car.', 'n. (pl.men)人；人类(单数，不加冠词)；男人', '/mæn/', 'man', 5);
INSERT INTO `words` VALUES (26505, 'He was asked to manage a new department.', 'v. 经营,管理,处理;设法,对付;操纵,运用', '/\'mænɪdʒ/', 'manage', 5);
INSERT INTO `words` VALUES (26506, 'a lack of management skills', 'n. 经营,管理;处理,操纵;管理部门', '/\'mænidʒmənt | \'mænɪdʒm(ə)nt | \'mænɪdʒmənt/', 'management', 5);
INSERT INTO `words` VALUES (26507, 'one of our regional managers', 'n. 经理,管理人', '/\'mænidʒə | \'mænɪdʒə | \'mænɪdʒɚ/', 'manager', 5);
INSERT INTO `words` VALUES (26508, 'All the fighters landed safely on the airport after the military maneuver.', 'n. (manoeuvre)机动;运用,操作;; v. 机动', '/mə\'nu:və | mə\'nʊvə | mə\'nʊvɚ; mə\'njʊvɚ/', 'maneuver', 5);
INSERT INTO `words` VALUES (26509, 'The shareholders have manifested their intention to sell the shares.', 'v. 表明,证明,显示; adj. 明白的,明了的', '/\'mænifest | \'mænɪfest | \'mænɪfɛst/', 'manifest', 5);
INSERT INTO `words` VALUES (26510, 'She was unable, for once, to control and manipulate events.', 'v. (熟练地)使用，操作；(巧妙地)处理', '/mə\'nipjuleit | mə\'nɪpjʊleɪt | mə\'nɪpjulet/', 'manipulate', 5);
INSERT INTO `words` VALUES (26511, 'Since earliest times, mankind has been fascinated by fire.', 'n. 人类', '/,mæn\'kaind | ,mæn\'kaɪnd | mæn\'kaɪnd/', 'mankind', 5);
INSERT INTO `words` VALUES (26512, 'He felt some guilt over the manner of her death.', 'n. 方式;举止;(pl.)风度,礼貌;规矩;风俗', '/\'mænə | \'mænɚ/', 'manner', 5);
INSERT INTO `words` VALUES (26513, 'She managed to manoeuvre expertly into the parking space.', 'v. 演习；谨慎地运用技巧移动， 运动；熟练而巧妙地引导某人', '/mə\'nuːvə | mə\'nu:və/', 'manoeuvre', 5);
