INSERT INTO `words` VALUES (26516, 'Unfortunately, parts of the original manuscript have been lost.', 'n. 手稿,原稿', '/\'mænjuskript | \'mænjʊskrɪpt | \'mænjuskrɪpt/', 'manuscript', 5);
INSERT INTO `words` VALUES (26517, 'a marathon round of negotiations', 'adj. 马拉松式的; n. 马拉松赛跑；马拉松式的活动', '/\'mærəθən | \'mærə,θɑn/', 'marathon', 5);
