INSERT INTO `words` VALUES (26519, 'An estimated 5,000 people marched through the city to demonstrate against the factory closures.', 'v. (使)行军,(使)行进; n. 行军,行程', '/mɑːtʃ | mɑrtʃ/', 'march', 5);
INSERT INTO `words` VALUES (26520, 'Someone had scribbled a note in the margin .', 'n. 页边空白;边缘;余地;幅度', '/\'mɑ:dʒin | \'mɑːdʒɪn | \'mɑrdʒən/', 'margin', 5);
INSERT INTO `words` VALUES (26521, 'marginal revenue', 'adj. 记在页边的,旁注的;(意识)边缘的', '/\'mɑ:dʒinəl | \'mɑːdʒɪn(ə)l | \'mɑrdʒɪnl/', 'marginal', 5);
