INSERT INTO `words` VALUES (26527, 'Are you married or single?', 'adj. 已婚的,夫妇的;(to)与…结婚的', '/\'mærid | \'mærɪd/', 'married', 5);
INSERT INTO `words` VALUES (26528, 'He married Bea in 1925.', 'v. 结婚,嫁,娶', '/\'mæri | \'mærɪ/', 'marry', 5);
