INSERT INTO `words` VALUES (26530, 'It is all the same God, and that God showed me that the universe in which we live is a beautiful and marvelous mystery that is connected together forever and for always.', 'adj. (marvellous)惊人的,奇迹般的,妙极的', '/\'mɑ:viləs | ˈmɑːvələs | \'mɑrvələs/', 'marvelous', 5);
INSERT INTO `words` VALUES (26531, '...a 78-year-old former Marxist.', 'n. 马克思主义者; adj. 马克思主义的', '/\'ma:ksist | \'mɑrksɪst/', 'marxist', 5);
