INSERT INTO `words` VALUES (26537, 'the skills needed to master a new language', 'v. 控制；精通；征服; n. 硕士；主人；大师；教师; adj. 主人的；主要的；熟练的', '/\'mɑ:stə, \'mæstə | \'mɑːstə | \'mæstɚ/', 'master', 5);
