INSERT INTO `words` VALUES (26539, 'Wipe your feet on the mat.', 'n. 垫；垫子；衬边; v. 缠结；铺席于……上; adj. 无光泽的', '/mæt/', 'mat', 5);
INSERT INTO `words` VALUES (26540, 'We painted the cabinets green to match the rug.', 'v. 使比赛；使相配；敌得过，比得上；相配；与…竞争; n. 比赛，竞赛；匹配；对手；火柴', '/mætʃ/', 'match', 5);
INSERT INTO `words` VALUES (26541, 'He has found his ideal mate.', 'n. 助手，大副；配偶；同事；配对物; v. 使配对；使一致；结伴', '/meit | meɪt | met/', 'mate', 5);
INSERT INTO `words` VALUES (26542, 'According to some, the material world is all that exists.', 'adj. 重要的；物质的，实质性的；肉体的; n. 材料，原料；物资；布料', '/mə\'tiəriəl | mə\'tɪərɪəl | mə\'tɪrɪəl/', 'material', 5);
INSERT INTO `words` VALUES (26543, 'mathematical analysis', 'adj. 数学的，数学上的；精确的', '/,mæθi\'mætikəl | mæθ(ə)\'mætɪk(ə)l | ,mæθə\'mætɪkl/', 'mathematical', 5);
INSERT INTO `words` VALUES (26544, 'the new maths teacher', 'n. 数学（等于mathematics）', '/mæθs/', 'maths', 5);
INSERT INTO `words` VALUES (26545, 'particles of matter', 'n. 物质；事件; v. 有关系；要紧', '/\'mætə | \'mætɚ/', 'matter', 5);
INSERT INTO `words` VALUES (26546, 'Laura is very mature for her age .', 'adj. 成熟的；充分考虑的；到期的；成年人的; v. 成熟；到期', '/mə\'tjuə | mə\'tʃʊə | mə\'tʃʊr/', 'mature', 5);
INSERT INTO `words` VALUES (26547, 'We might have a third child, but that’s the absolute maximum .', 'n. [数] 极大，最大限度；最大量; adj. 最高的；最多的；最大极限的', '/\'mæksiməm | \'mæksɪməm | ˈmæksəməm/', 'maximum', 5);
INSERT INTO `words` VALUES (26548, 'the election of the London mayor', 'n. 市长', '/\'mεə | ˈmeɪə | \'meɚ/', 'mayor', 5);
INSERT INTO `words` VALUES (26549, 'The meadow has been ploughed up.', 'n. 草地；牧场', '/\'medəu | \'medəʊ | \'mɛdo/', 'meadow', 5);
INSERT INTO `words` VALUES (26550, 'Life seemed to have lost its meaning since Janet’s death.', 'n. 意义；含义；意图; adj. 意味深长的; v. 意味；意思是（mean的ing形式）', '/\'mi:niŋ | \'miːnɪŋ | \'minɪŋ/', 'meaning', 5);
INSERT INTO `words` VALUES (26551, 'The only means of communication was sign language.', 'n. 方法， 手段', '/miːnz | minz/', 'means', 5);
INSERT INTO `words` VALUES (26552, 'The doctor will be here soon. In the meantime, try and relax.', 'n. 其时，其间; adv. 同时；其间', '/\'mi:n\'taim | \'miːntaɪm | \'min\'taɪm/', 'meantime', 5);
