INSERT INTO `words` VALUES (26556, 'The flight has been cancelled due to mechanical failure .', 'adj. 机械的；力学的；呆板的；无意识的；手工操作的', '/mi\'kænikəl | mɪ\'kænɪk(ə)l | mɪ\'kænɪkəl/', 'mechanical', 5);
INSERT INTO `words` VALUES (26557, 'the brake mechanism', 'n. 机制；原理，途径；进程；机械装置；技巧', '/\'mekənizəm | \'mek(ə)nɪz(ə)m | \'mɛkənɪzəm/', 'mechanism', 5);
INSERT INTO `words` VALUES (26558, 'She won a gold medal at the last Olympics.', 'n. 奖章,勋章,纪念章', '/\'medəl | \'med(ə)l | \'mɛdl/', 'medal', 5);
