INSERT INTO `words` VALUES (26560, 'Medicines should be kept out of the reach of children.', 'n. 内服药,医药;医术;医学,内科学', '/\'medisin | \'meds(ə)n; \'medɪsɪn | \'mɛdsn/', 'medicine', 5);
INSERT INTO `words` VALUES (26561, 'These spices were first brought to Italy from the East in medieval times.', 'adj. 中世纪的,中古(时代)的,老式的,原始的', '/,medi\'i:vəl, ,mi:- | ˌmediˈi:vl | ,midɪ\'ivəl/', 'medieval', 5);
INSERT INTO `words` VALUES (26562, 'I try to meditate for half an hour every evening.', 'v. 想,考虑,(尤指宗教上的)沉思,冥想', '/\'mediteit | \'medɪteɪt | \'mɛdɪtet/', 'meditate', 5);
INSERT INTO `words` VALUES (26563, 'Yoga involves breathing exercises, stretching, and meditation.', 'n. 熟虑;默想,沉思;(pl.)冥想录', '/,medi\'teiʃən | medɪ\'teɪʃ(ə)n | ,mɛdɪ\'teʃən/', 'meditation', 5);
INSERT INTO `words` VALUES (26564, 'Advertising is a powerful medium.', 'n. 媒体,方法,媒介,介质; adj. 中等的', '/\'mi:diəm, -djəm | \'miːdɪəm | \'midɪəm/', 'medium', 5);
INSERT INTO `words` VALUES (26565, 'We’re having a meeting next week to discuss the matter.', 'n. 会议；会见；集会；汇合点; v. 会面；会合（meet的ing形式）', '/\'mi:tiŋ | \'miːtɪŋ | \'mitɪŋ/', 'meeting', 5);
INSERT INTO `words` VALUES (26566, 'They played some lovely melodies.', 'n. 旋律；歌曲；美妙的音乐', '/\'melədi | \'melədɪ | \'mɛlədi/', 'melody', 5);
INSERT INTO `words` VALUES (26567, '...some juicy slices of melon.', 'n. 瓜；甜瓜；大肚子；圆鼓鼓像瓜似的东西', '/\'melən | \'mɛlən/', 'melon', 5);
INSERT INTO `words` VALUES (26568, 'It was warmer now, and the snow was beginning to melt.', 'v. 融化， 熔化', '/melt | mɛlt/', 'melt', 5);
INSERT INTO `words` VALUES (26569, 'The majority of union members voted in favour of a strike.', 'n. 成员,会员', '/\'membə | \'mɛmbɚ/', 'member', 5);
INSERT INTO `words` VALUES (26570, 'You should carry your membership card with you at all times.', 'n. 会员资格,成员资格', '/\'membəʃɪp | \'mɛmbɚʃɪp/', 'membership', 5);
INSERT INTO `words` VALUES (26571, 'I sent him a memo reminding him about the meeting.', 'n. (randum)备忘录', '/\'meməu | \'meməʊ | \'mɛmo/', 'memo', 5);
INSERT INTO `words` VALUES (26572, '...a memorandum from the Department of Defense on its role.', 'n. 备忘录', '/ˌmemə\'rændəm | ,mɛmə\'rændəm/', 'memorandum', 5);
INSERT INTO `words` VALUES (26573, 'A memorial service is being held for her at St. Paul\'s Church.', 'adj. 记忆的,纪念的; n. 纪念物,纪念碑,纪念馆', '/英 [mə\'mɔ:rɪəl] 美 [məˈmɔriəl, -ˈmor | mə\'mɔːrɪəl | mə\'morɪəl/', 'memorial', 5);
INSERT INTO `words` VALUES (26574, 'He has lots of happy memories of his stay in Japan.', 'n. 记忆,记忆力;回忆;存储(器)', '/\'meməri | \'mem(ə)rɪ | \'mɛməri/', 'memory', 5);
INSERT INTO `words` VALUES (26575, 'The elephants are still menaced by poachers.', 'v. /n.有危险性的人(或物)；威胁，威吓', '/\'menəs | \'mɛnəs/', 'menace', 5);
INSERT INTO `words` VALUES (26576, 'My father used to mend our shoes.', 'v. 修理，修补；改善；修改; n. 好转，改进；修补处', '/mend | mɛnd/', 'mend', 5);
INSERT INTO `words` VALUES (26577, 'The centre provides help for people suffering from mental illness .', 'adj. 精神的；脑力的；疯的; n. 精神病患者', '/\'mentəl | \'ment(ə)l | \'mɛntl/', 'mental', 5);
INSERT INTO `words` VALUES (26578, 'Was my name mentioned at all?', 'v. 提到，谈到；提及，论及；说起; n. 提及，说起', '/\'menʃən | \'menʃ(ə)n | \'mɛnʃən/', 'mention', 5);
INSERT INTO `words` VALUES (26579, 'Could we have the menu, please?', 'n. 菜单', '/\'menju:, mə\'nju: | \'menjuː | \'mɛnju/', 'menu', 5);
INSERT INTO `words` VALUES (26580, 'A range of official Disney merchandise was on sale.', 'n. 商品,货物', '/\'mə:tʃəndaiz, -dais | \'mɜːtʃ(ə)ndaɪs; -z | \'mɝtʃəndaɪs/', 'merchandise', 5);
INSERT INTO `words` VALUES (26581, 'the son of a wealthy merchant', 'n. 商人,零售商', '/\'mə:tʃənt | \'mɜːtʃ(ə)nt | \'mɝtʃənt/', 'merchant', 5);
INSERT INTO `words` VALUES (26582, 'Some thieves have eaten off their irons with mercury water.', 'n. 水银,汞', '/\'mɝkjəri | \'mɜːkjəri/', 'mercury', 5);
INSERT INTO `words` VALUES (26583, 'He showed no mercy to his enemies.', 'n. 仁慈,怜悯,宽恕', '/\'mə:si | \'mɜːsɪ | \'mɝsi/', 'mercy', 5);
INSERT INTO `words` VALUES (26584, 'She lost the election by a mere 20 votes.', 'adj. 纯粹的;仅仅,只不过', '/miə | mɪə | mɪr/', 'mere', 5);
INSERT INTO `words` VALUES (26585, 'He’s merely a boy – you can’t expect him to understand.', 'adv. 仅仅，只不过', '/\'miəli | \'mɪəlɪ | \'mɪrli/', 'merely', 5);
INSERT INTO `words` VALUES (26586, 'The company plans to merge its subsidiaries in the US.', 'v. (使)结合，(使)合并，(使)合为一体', '/mə:dʒ | mɜːdʒ | mɝdʒ/', 'merge', 5);
INSERT INTO `words` VALUES (26587, 'The merit of the report is its realistic assessment of the changes required.', 'n. 优点,价值,功绩; v. 值得,应得', '/\'merit | \'merɪt | \'mɛrɪt/', 'merit', 5);
INSERT INTO `words` VALUES (26588, 'He marched off, whistling a merry tune.', 'adj. 欢乐的,愉快的', '/\'meri | \'merɪ | \'mɛri/', 'merry', 5);
INSERT INTO `words` VALUES (26589, 'What a mess!', 'n. 混乱；食堂，伙食团；困境；脏乱的东西; v. 弄乱，弄脏；毁坏；使就餐', '/mes | mɛs/', 'mess', 5);
INSERT INTO `words` VALUES (26590, 'He left a message saying he would probably be a little late.', 'n. 消息；差使；启示；预言；广告词; v. 报信，报告；[通信] 报文', '/\'mesidʒ | \'mesɪdʒ | \'mɛsɪdʒ/', 'message', 5);
INSERT INTO `words` VALUES (26591, 'There will be a messenger at the airport to collect the photographs from our courier.', 'n. 报信者，送信者；先驱', '/\'mesindʒə | \'mesɪn(d)ʒə | \'mɛsndʒɚ/', 'messenger', 5);
INSERT INTO `words` VALUES (26592, 'The gate is made of metal.', 'n. 金属,金属制品', '/\'metəl | \'met(ə)l | \'mɛtl/', 'metal', 5);
INSERT INTO `words` VALUES (26593, 'She uses some wonderful images and metaphors in her writing.', 'n. 隐喻，暗喻', '/\'metəfə | \'metəfə; -fɔː | \'mɛtəfɚ/', 'metaphor', 5);
INSERT INTO `words` VALUES (26594, 'traditional teaching methods', 'n. 方法,办法', '/\'meθəd | \'mɛθəd/', 'method', 5);
INSERT INTO `words` VALUES (26595, 'She\'s running the 1,500 metres here.', 'n. (meter)米，公尺；仪表，计量器', '/\'mi:tə | \'mi:tə(r) | ˈmitɚ/', 'metre', 5);
INSERT INTO `words` VALUES (26596, 'a metric tonne', 'adj. 米制的,公制的', '/\'metrik | \'metrɪk | \'mɛtrɪk/', 'metric', 5);
INSERT INTO `words` VALUES (26597, 'The city has become a huge, bustling metropolis.', 'n. 大都市；首府；重要中心', '/mi\'trɔpəlis, me- | mɪ\'trɒp(ə)lɪs | mə\'trɑpəlɪs/', 'metropolis', 5);
INSERT INTO `words` VALUES (26598, 'a metropolitan area of South Australia', 'adj. 首都的,主要都市的,大城市', '/,metrə\'pɔlitən | metrə\'pɒlɪt(ə)n | ,mɛtrə\'pɑlɪtən/', 'metropolitan', 5);
INSERT INTO `words` VALUES (26599, 'She spoke confidently into the microphone.', 'n. 扩音器，麦克风', '/\'maikrəfəun | \'maɪkrəfəʊn | \'maɪkrə\'fon/', 'microphone', 5);
INSERT INTO `words` VALUES (26600, 'The slightest movement will defocus the microscope.', 'n. 显微镜', '/\'maikrəskəup | \'maɪkrəskəʊp | \'maɪkrəskop/', 'microscope', 5);
INSERT INTO `words` VALUES (26601, 'There are plenty of small houses for sale, and quite a lot of very large ones, but very little in the middle.', 'n. n&adj中间(的),当中(的)', '/\'mɪd(ə)l | \'mɪdl/', 'middle', 5);
INSERT INTO `words` VALUES (26602, 'I fear we have an enemy in our midst.', 'n. 中间,当中', '/midst | mɪdst/', 'midst', 5);
INSERT INTO `words` VALUES (26603, 'People migrate to cities like Jakarta in search of work.', 'v. 移动；随季节而移居；移往', '/mai\'ɡreit, \'maiɡ- | maɪ\'greɪt; \'maɪgreɪt | \'maɪɡret/', 'migrate', 5);
INSERT INTO `words` VALUES (26604, 'We had an exceptionally mild winter last year.', 'adj. 温和的；轻微的；淡味的；文雅的；不含有害物质的的; n. （英国的一种）淡味麦芽啤酒', '/maild | maɪld/', 'mild', 5);
INSERT INTO `words` VALUES (26605, 'militant political activists', 'adj. 好战的; n. 富有战斗性的人；好斗者；激进分子', '/\'mɪlɪt(ə)nt | \'mɪlɪtənt/', 'militant', 5);
INSERT INTO `words` VALUES (26606, 'a military helicopter', 'adj. 军事的；军人的；适于战争的; n. 军队；军人', '/\'militəri | \'mɪlɪt(ə)rɪ | \'mɪlətɛri/', 'military', 5);
INSERT INTO `words` VALUES (26607, 'a bottle of milk', 'n. 牛奶；乳状物; v. 榨取；挤…的奶', '/milk | mɪlk/', 'milk', 5);
INSERT INTO `words` VALUES (26608, 'He’s really been through the mill recently.', 'n. 磨粉机； 磨坊；作坊； 工厂', '/mɪl/', 'mill', 5);
INSERT INTO `words` VALUES (26609, 'A micrometer is one thousandth of one millimeter.', 'n. (millimetre)毫米', '/\'mili,mi:tə | \'mɪlɪˌmi:tə | \'mɪləˌmitə/', 'millimeter', 5);
INSERT INTO `words` VALUES (26610, 'The creature is a tiny centipede, just 10 millimetres long.', 'n. 毫米', '/\'mili,mi:tə | \'mɪlimiːtə/', 'millimetre', 5);
INSERT INTO `words` VALUES (26611, 'an American millionaire', 'n. 百万富翁；大富豪; adj. 100万以上人口的', '/,miljə\'nεə | mɪljə\'neə | ,mɪljə\'nɛr/', 'millionaire', 5);
INSERT INTO `words` VALUES (26612, 'The area is very rich in minerals .', 'n. 矿物；（英）矿泉水；无机物；苏打水（常用复数表示）; adj. 矿物的；矿质的', '/\'minərəl | \'mɪn(ə)r(ə)l | \'mɪnərəl/', 'mineral', 5);
INSERT INTO `words` VALUES (26613, 'Add the mint and allow the flavours to mingle.', 'vi. 混合起来， 相混合；相交往; vt. 使混合', '/\'mɪŋgl | \'mɪŋɡl/', 'mingle', 5);
INSERT INTO `words` VALUES (26614, 'miniature roses', 'adj. 微型的，小规模的; n. 缩图；微型画；微型图画绘画术; vt. 是…的缩影', '/\'miniətʃə | \'mɪnɪtʃə | ˈmɪniətʃɚ; ˈmɪnɪtʃɚ/', 'miniature', 5);
INSERT INTO `words` VALUES (26615, 'Concerned people want to minimize the risk of developing cancer.', 'vt. 使减到最少， 使降到最低', '/\'mɪnɪmaɪz/', 'minimize', 5);
INSERT INTO `words` VALUES (26616, 'At a minimum, we must recruit two new teachers.', 'n. 最小值；最低限度；最小化；最小量; adj. 最小的；最低的', '/\'miniməm | \'mɪnɪməm/', 'minimum', 5);
INSERT INTO `words` VALUES (26617, 'a senior Cabinet minister', 'n. 部长；大臣；牧师; v. 执行牧师职务；辅助或伺候某人', '/\'ministə | \'mɪnɪstə | \'mɪnɪstɚ/', 'minister', 5);
INSERT INTO `words` VALUES (26618, '...the Ministry of Justice.', 'n. （政府的）部门', '/\'ministri | \'mɪnɪstrɪ | \'mɪnɪstri/', 'ministry', 5);
INSERT INTO `words` VALUES (26619, 'What are your major subject and minor subject?', 'vi. 兼修; adj. 较小的， 较少的， 较次要的; n. 兼修学科', '/\'maɪnə | \'maɪnɚ/', 'minor', 5);
INSERT INTO `words` VALUES (26620, 'Gaelic is still spoken in Ireland by a tiny minority.', 'n. 少数民族；少数派；未成年; adj. 少数的；属于少数派的', '/mai\'nɔrəti, mi- | maɪ\'nɒrɪtɪ; mɪ- | maɪ\'nɔrəti/', 'minority', 5);
INSERT INTO `words` VALUES (26621, '‘Any minus points ?’ ‘Well, the engine is rather noisy.’', 'adj. 负的； 减的; prep. 减去; n. 负号； 减号', '/\'maɪnəs/', 'minus', 5);
INSERT INTO `words` VALUES (26622, 'It’s a miracle you weren’t killed!', 'n. 奇迹,令人惊奇的人(或事)', '/\'mirəkl | \'mɪrək(ə)l | \'mɪrəkl/', 'miracle', 5);
INSERT INTO `words` VALUES (26623, 'He spends hours in front of the mirror !', 'n. 镜子;反映,反射; v. 反映,反射', '/\'mirə | \'mɪrə | \'mɪrɚ/', 'mirror', 5);
INSERT INTO `words` VALUES (26624, 'Now run along, and don’t get into mischief .', 'n. 恶作剧；伤害；顽皮；不和', '/\'mistʃif | \'mɪstʃɪf/', 'mischief', 5);
INSERT INTO `words` VALUES (26625, 'I’ve been so miserable since Pat left me.', 'adj. 悲惨的；痛苦的；卑鄙的', '/\'mizərəbl | \'mɪz(ə)rəb(ə)l | \'mɪzrəbl/', 'miserable', 5);
INSERT INTO `words` VALUES (26626, 'What we are witnessing here is human misery on a vast scale.', 'n. 痛苦，悲惨；不幸；苦恼；穷困', '/\'mizəri | \'mɪz(ə)rɪ | \'mɪzəri/', 'misery', 5);
INSERT INTO `words` VALUES (26627, 'It seems the banks always profit from farmers’ misfortunes.', 'n. 不幸；灾祸，灾难', '/mis\'fɔ:tʃən | mɪs\'fɔːtʃuːn; -tʃ(ə)n | \'mɪs\'fɔrtʃən/', 'misfortune', 5);
INSERT INTO `words` VALUES (26628, 'Don’t be misled by appearances, he’s a good worker.', 'v. 误导；带错', '/,mis\'li:d | mɪs\'liːd | \'mɪs\'lid/', 'mislead', 5);
INSERT INTO `words` VALUES (26629, 'I’d like to make an appointment with Miss Taylor.', 'n. 女士，小姐，年轻未婚女子', '/mɪs/', 'miss', 5);
INSERT INTO `words` VALUES (26630, 'a nuclear missile', 'n. 导弹；投射物; adj. 导弹的；可投掷的；用以发射导弹的', '/\'misail, -səl | \'mɪsaɪl | \'mɪsl/', 'missile', 5);
INSERT INTO `words` VALUES (26631, 'We found the missing piece of the jigsaw under the chair.', 'adj. 失踪的；缺少的; v. 错过（miss的ing形式）；想念；漏掉; n. (Missing)人名；(德)米辛', '/\'misiŋ | \'mɪsɪŋ/', 'missing', 5);
INSERT INTO `words` VALUES (26632, 'He was sent on over 200 missions before being killed in action.', 'n. 使命，任务；代表团；布道; vt. 派遣；向……传教', '/\'miʃən | \'mɪʃ(ə)n | \'mɪʃən/', 'mission', 5);
INSERT INTO `words` VALUES (26633, 'missionary work', 'adj. 传教的；传教士的; n. 传教士', '/\'miʃənəri | \'mɪʃ(ə)n(ə)rɪ | \'mɪʃənɛri/', 'missionary', 5);
INSERT INTO `words` VALUES (26634, 'We could just see the outline of the house through the mist.', 'n. 薄雾；视线模糊不清；模糊不清之物; v. 下雾；变模糊', '/mist | mɪst/', 'mist', 5);
INSERT INTO `words` VALUES (26635, 'The most common mistake is to plant them too deep.', 'n. 错误；误会；过失; v. 弄错；误解', '/mi\'steik | mɪ\'steɪk | mɪ\'stek/', 'mistake', 5);
INSERT INTO `words` VALUES (26636, 'The Prince had shocked society by living openly with his mistress.', 'n. 情妇；女主人；主妇；女教师；女能人', '/\'mistris | \'mɪstrɪs | \'mɪstrəs/', 'mistress', 5);
INSERT INTO `words` VALUES (26637, 'Oil and water don’t mix.', 'v. 配制；混淆；使混和；使结交; n. 混合；混合物；混乱', '/miks | mɪks/', 'mix', 5);
INSERT INTO `words` VALUES (26638, 'Pour the mixture into four small dishes.', 'n. 混合；混合物；混合剂', '/\'mikstʃə | \'mɪkstʃə | \'mɪkstʃɚ/', 'mixture', 5);
INSERT INTO `words` VALUES (26639, '‘I feel seasick already,’ she moaned.', 'v. 抱怨，悲叹；呻吟; n. 呻吟声；悲叹', '/məun | məʊn | mon/', 'moan', 5);
INSERT INTO `words` VALUES (26640, 'They were immediately surrounded by the mob.', 'n. 乌合之众(尤指暴力者); v. 围攻，聚众闹事', '/mɔb | mɒb | mɑb/', 'mob', 5);
INSERT INTO `words` VALUES (26641, '...the four-hundred seat mobile theatre.', 'adj. 可动的,活动的,运动的', '/ˈməʊbaɪl | ˈmobəl; ˈmoˌbaɪl; ˈmoˌbil/', 'mobile', 5);
INSERT INTO `words` VALUES (26642, 'Israel, which has tried for years to mobilise international action against Iran , suddenly appears more sanguine.', 'vt. 动员', '/\'məubəlaɪz | \'məubilaiz/', 'mobilise', 5);
INSERT INTO `words` VALUES (26643, 'an attempt to mobilize popular opinion', 'v. (mobilise)动员,赋予可动性', '/\'məubilaiz | \'məʊbəlaɪz | \'mobəlaɪz/', 'mobilize', 5);
INSERT INTO `words` VALUES (26644, 'I’m revising for my mocks.', 'n. 英国模拟考试（mocks）; v. 愚弄，嘲弄; adj. 仿制的，模拟的，虚假的，不诚实的', '/mɒk | mɑk/', 'mock', 5);
INSERT INTO `words` VALUES (26645, 'Set the monitor to 256 colour mode.', 'n. 方式,式样', '/məud | məʊd | mod/', 'mode', 5);
INSERT INTO `words` VALUES (26646, 'a working model (= one with parts which move ) of a steam engine', 'n. 样式,型;模范;模型,原型;模特; v. 模仿', '/\'mɔdəl | \'mɒdl | \'mɑdl/', 'model', 5);
INSERT INTO `words` VALUES (26647, 'Even moderate amounts of alcohol can be dangerous.', 'adj. 有节制的,中等的,适度的,温和的,稳健的', '/\'mɔdərət, \'mɔdəreit | \'mɒd(ə)rət | ˈmɑdərɪt; (for v.,) ˈmɑdərˌeɪt/', 'moderate', 5);
INSERT INTO `words` VALUES (26648, 'Such companies must change if they are to compete in the modern world .', 'adj. 现代的,近代的,新式的', '/\'mɔdən | \'mɒd(ə)n | \'mɑdɚn/', 'modern', 5);
INSERT INTO `words` VALUES (26649, 'For these reasons, the bank chose it as their development tool for their modernization project.', 'n. (modernisation)现代化', '/,mɔdənai\'zeiʃən, -ni\'z- | ,mɒdənaɪ\'zeɪʃən | ,mɑdɚnə\'zeʃən/', 'modernization', 5);
INSERT INTO `words` VALUES (26650, 'You’re too modest! You’ve been a huge help to us.', 'adj. 谦虚的,有节制的', '/\'mɔdist | \'mɒdɪst | \'mɑdɪst/', 'modest', 5);
INSERT INTO `words` VALUES (26651, 'The feedback will be used to modify the course for next year.', 'v. 更改,修改,修饰', '/\'mɔdifai | \'mɒdɪfaɪ | \'mɑdɪfaɪ/', 'modify', 5);
INSERT INTO `words` VALUES (26652, 'A rescue plan could be achieved by sending an unmanned module to the space station.', 'n. 组件，模块，模件；(航天器的)舱', '/\'mɔdju:l, -dʒu:l | \'mɒdjuːl | \'mɑdʒul/', 'module', 5);
INSERT INTO `words` VALUES (26653, 'Make sure the soil is moist before planting the seeds.', 'adj. 潮湿的；多雨的；含泪的; n. 潮湿', '/mɔist | mɒɪst | mɔɪst/', 'moist', 5);
INSERT INTO `words` VALUES (26654, 'Plants use their roots to absorb moisture from the soil.', 'n. 水分；湿度；潮湿；降雨量', '/\'mɔistʃə | \'mɒɪstʃə | \'mɔɪstʃɚ/', 'moisture', 5);
INSERT INTO `words` VALUES (26655, 'And then you put them in a mold.', 'n. 模子， 铸型; vt. 浇铸， 造型； 塑造， 形成', '/məuld | mold/', 'mold', 5);
INSERT INTO `words` VALUES (26656, 'The molecules of oxygen gas contain just two atoms.', 'n. [化学] 分子；微小颗粒，微粒', '/\'mɔlikjul | \'mɒlɪkjuːl | \'mɑlɪkjul/', 'molecule', 5);
INSERT INTO `words` VALUES (26657, 'incentives to maintain the momentum of European integration', 'n. 势头；[物] 动量；动力；冲力', '/məu\'mentəm | mə\'mentəm | mo\'mɛntəm/', 'momentum', 5);
INSERT INTO `words` VALUES (26658, 'Revolutionary ideas are in the air, and at least one monarch meets a bloody end!', 'n. 帝王，君主，最高统治者', '/\'mɔnək, -ɑ:k | \'mɒnək | \'mɑnɚk/', 'monarch', 5);
INSERT INTO `words` VALUES (26659, 'The president announced Monday that he would cancel the debt.', 'n. 星期一', '/\'mʌndi | ˈmʌndeɪ; ˈmʌndi | ˈmʌnde; ˈmʌndɪ/', 'Monday', 5);
INSERT INTO `words` VALUES (26660, 'the government’s tight monetary policy', 'adj. 金融的,货币的', '/\'mʌnitəri | \'mʌnɪt(ə)rɪ | \'mʌnɪtɛri/', 'monetary', 5);
INSERT INTO `words` VALUES (26661, 'Don’t spend all your money on the first day of your holiday!', 'n. 货币,钱', '/\'mʌni | \'mʌnɪ/', 'money', 5);
INSERT INTO `words` VALUES (26662, 'a heart monitor', 'n. 班长;监听器,监视器; v. 监控,监测', '/\'mɒnɪtə | \'mɔnɪtɚ/', 'monitor', 5);
INSERT INTO `words` VALUES (26663, 'The monkey is beating up and down.', 'n. 猴子', '/\'mʌŋki | \'mʌŋkɪ/', 'monkey', 5);
INSERT INTO `words` VALUES (26664, 'a monopoly in copper trading', 'n. 垄断,专卖,专利权,专利事业', '/mə\'nɔpəli | mə\'nɒp(ə)lɪ | mə\'nɑpəli/', 'monopoly', 5);
INSERT INTO `words` VALUES (26665, 'a monotonous diet', 'adj. 单调的,无变化的', '/mə\'nɔtənəs | mə\'nɒt(ə)nəs | mə\'nɑtənəs/', 'monotonous', 5);
INSERT INTO `words` VALUES (26666, 'the remains of a prehistoric monster', 'n. 怪物,妖怪,畸形的动植物', '/\'mɔnstə | \'mɒnstə | \'mɑnstɚ/', 'monster', 5);
INSERT INTO `words` VALUES (26667, 'I hope I’ll have finished the work by the end of the month .', 'n. 月,月份', '/mʌnθ/', 'month', 5);
INSERT INTO `words` VALUES (26668, 'The mortgage is payable in monthly instalments.', 'adj. 每月的; adv. 每月一次,按月; n. 月刊', '/\'mʌnθli | \'mʌnθlɪ/', 'monthly', 5);
INSERT INTO `words` VALUES (26669, 'He erected a monument on the spot where his daughter was killed.', 'n. 纪念碑,纪念馆,遗迹,不朽的业绩', '/\'mɔnjumənt | \'mɒnjʊm(ə)nt | \'mɑnjumənt/', 'monument', 5);
INSERT INTO `words` VALUES (26670, 'You’re in a good mood this morning!', 'n. 心情,情绪;语气', '/mu:d | muːd | mud/', 'mood', 5);
INSERT INTO `words` VALUES (26671, 'the craters on the surface of the moon', 'n. (加the)月球，月亮；卫星', '/mu:n | muːn | mun/', 'moon', 5);
INSERT INTO `words` VALUES (26672, 'It is easy to have an opinion on a moral issue like the death penalty for murder.', 'adj. 道德的；精神上的；品性端正的; n. 道德；寓意', '/\'mɔrəl, \'mɔ:- | \'mɒr(ə)l | \'mɔrəl/', 'moral', 5);
INSERT INTO `words` VALUES (26673, '...standards of morality and justice in society.', 'n. 道德；品行，美德', '/mə\'ræləti, mɔ:- | məˈræləti/', 'morality', 5);
INSERT INTO `words` VALUES (26674, 'The rent is reasonable and, moreover, the location is perfect.', 'adv. 再者， 加之， 而且', '/mɔːr\'əuvə | mɔr\'ovɚ/', 'moreover', 5);
INSERT INTO `words` VALUES (26675, 'Her father’s death reminded her that she was mortal.', 'adj. 凡人的；致死的；终有一死的；不共戴天的; n. 人类，凡人', '/\'mɔ:təl | \'mɔːt(ə)l | \'mɔrtl/', 'mortal', 5);
INSERT INTO `words` VALUES (26676, 'Your building society or bank will help arrange a mortgage.', 'n. 抵押; vt. 抵押', '/\'mɔːgɪdʒ | \'mɔrɡɪdʒ/', 'mortgage', 5);
INSERT INTO `words` VALUES (26677, 'rooms decorated with wall paintings and mosaics', 'adj. 摩西的；拼成的；嵌花式的; n. 马赛克；镶嵌；镶嵌细工', '/məu\'zeiik | mə(ʊ)\'zeɪɪk | mo\'zeɪk/', 'mosaic', 5);
INSERT INTO `words` VALUES (26678, 'The male mosquito never stings.', 'n. 蚊子', '/mə\'ski:təu | mɒ\'skiːtəʊ | məˈskiːtoʊ/', 'mosquito', 5);
INSERT INTO `words` VALUES (26679, '...ground covered over with moss.', 'n. 苔藓；泥沼; vt. 使长满苔藓', '/mɔs | mɒs/', 'moss', 5);
INSERT INTO `words` VALUES (26680, 'Green teas are mostly from China or Japan.', 'adv. 主要地， 大部分， 通常', '/\'məustli | \'mostli/', 'mostly', 5);
