INSERT INTO `words` VALUES (26682, 'Newton’s first law of motion', 'n. 运动,动;提议,动议; v. 提议,动议', '/\'məʊʃ(ə)n | \'moʃən/', 'motion', 5);
INSERT INTO `words` VALUES (26683, 'Was he motivated solely by a desire for power?', 'v. 促动；激励，鼓励，作为…的动机', '/\'məutiveit | \'məʊtɪveɪt | \'motə\'vet/', 'motivate', 5);
INSERT INTO `words` VALUES (26684, 'What do you suppose the killer’s motive was?', 'n. 动机,目的; adj. 发动的,运动的', '/\'məutiv | \'məʊtɪv | \'motɪv/', 'motive', 5);
INSERT INTO `words` VALUES (26685, 'an electric motor', 'n. 发动机,电动机', '/\'məutə | \'məʊtə | \'motɚ/', 'motor', 5);
INSERT INTO `words` VALUES (26686, 'Clothes mould in wet weather.', 'v. 发霉; n. 模具；霉', '/məuld | məʊld/', 'mould', 5);
INSERT INTO `words` VALUES (26687, 'Tension here is mounting , as we await the final result.', 'v. 增加；爬上；使骑上马；安装，架置；镶嵌，嵌入；准备上演；成立（军队等）; n. 山峰；底座；乘骑用马；攀，登；运载工具；底座', '/maʊnt/', 'mount', 5);
INSERT INTO `words` VALUES (26688, 'the highest mountain in Austria', 'n. 山；山脉', '/ˈmauntin，ˈmaʊntən | ˈmaʊntən | ˈmaʊntn/', 'mountain', 5);
INSERT INTO `words` VALUES (26689, 'Hundreds of people gathered to mourn the slain president.', 'v. 哀悼；忧伤；服丧', '/mɔ:n, məun | mɔːn | mɔrn/', 'mourn', 5);
INSERT INTO `words` VALUES (26690, 'The cat laid a dead mouse at my feet.', 'n. 鼠标；老鼠；胆小羞怯的人; v. 探出', '/maus, mauz | maʊs/', 'mouse', 5);
INSERT INTO `words` VALUES (26691, 'He lifted his glass to his mouth.', 'n. 口，嘴；河口; v. 做作地说，装腔作势地说；喃喃地说出', '/mauθ | maʊθ/', 'mouth', 5);
INSERT INTO `words` VALUES (26692, 'Please keep the doors closed while the train is moving.', 'v. 移动,迁移;活动;感动; n. 移动,活动,行动', '/muːv | muv/', 'move', 5);
INSERT INTO `words` VALUES (26693, 'It\'s part of a broader nationalist movement that\'s gaining strength throughout the country.', 'n. 运动,活动;移动,迁移', '/\'mu:vmənt | \'muːvm(ə)nt | \'muvmənt/', 'movement', 5);
INSERT INTO `words` VALUES (26694, 'It was like one of those old John Wayne movies.', 'n. 电影,电影院', '/\'mu:vi | \'muːvɪ | \'muvi/', 'movie', 5);
INSERT INTO `words` VALUES (26695, 'They daubed mud all over themselves.', 'v. 弄脏；用泥涂; n. 泥；诽谤的话；无价值的东西', '/mʌd/', 'mud', 5);
INSERT INTO `words` VALUES (26696, 'Something scared him. Probably your ugly mug !', 'n. 杯子；脸；苦读者; v. 扮鬼脸，做怪相', '/mʌg | mʌɡ/', 'mug', 5);
INSERT INTO `words` VALUES (26697, 'Baxter was rushed to the hospital with multiple stab wounds.', 'adj. 多重的；多样的；许多的; n. 倍数；[电] 并联', '/\'mʌltipl | \'mʌltɪpl | \'mʌltəpl/', 'multiple', 5);
INSERT INTO `words` VALUES (26698, 'Children will learn to multiply in the second grade.', 'v. 乘；使增加；使繁殖；使相乘; adv. 多样地；复合地; adj. 多层的；多样的', '/\'mʌltiplai | \'mʌltɪplaɪ/', 'multiply', 5);
INSERT INTO `words` VALUES (26699, 'I had never seen such a multitude of stars before.', 'n. 群众；多数', '/\'mʌlti,tju:d, -,tu:d | \'mʌltɪtjuːd | ˈmʌltɪˌtud, -ˌtjud/', 'multitude', 5);
INSERT INTO `words` VALUES (26700, 'The municipal authorities gave the go-ahead for the march.', 'adj. 市(立,政)的;地方性的,地方自治的', '/mju:\'nisipəl | mjʊ\'nɪsɪp(ə)l | mju\'nɪsɪpl/', 'municipal', 5);
INSERT INTO `words` VALUES (26701, 'He was convicted of murdering a policeman.', 'v. 谋杀，凶杀; n. 谋杀，凶杀', '/\'mə:də | \'mɜːdə | \'mɝdɚ/', 'murder', 5);
INSERT INTO `words` VALUES (26702, 'She replied in a low murmur.', 'n. 低语；低语声；低声抱怨；潺潺声; v. 低声说；私下抱怨；发出轻柔持续的声音', '/\'mə:mə | \'mɜːmə | \'mɝmɚ/', 'murmur', 5);
INSERT INTO `words` VALUES (26703, 'Relax your stomach muscles , then stretch again.', 'n. 肌肉；力量; v. 加强；使劲搬动；使劲挤出', '/\'mʌsl | \'mʌs(ə)l/', 'muscle', 5);
INSERT INTO `words` VALUES (26704, 'She was fast and strong, with a slender, muscular body.', 'adj. 肌肉的；肌肉发达的；强健的', '/\'mʌskjulə | \'mʌskjʊlə | \'mʌskjəlɚ/', 'muscular', 5);
INSERT INTO `words` VALUES (26705, 'the Museum of Modern Art', 'n. 博物馆', '/mju:\'ziəm | mjuː\'zɪəm | mju\'ziəm/', 'museum', 5);
INSERT INTO `words` VALUES (26706, 'mushroom soup', 'n. 蘑菇，伞菌；蘑菇形物体；暴发户; adj. 蘑菇的；蘑菇形的；迅速生长的; v. 迅速增加；采蘑菇；迅速生长', '/\'mʌʃru:m, -rum | \'mʌʃruːm; -rʊm | \'mʌʃrʊm/', 'mushroom', 5);
INSERT INTO `words` VALUES (26707, 'a musical version of the fairy tale ‘Cinderella’', 'adj. 音乐的；悦耳的; n. 音乐片', '/\'mju:zikəl | \'mjuːzɪk(ə)l | \'mjuzɪkl/', 'musical', 5);
INSERT INTO `words` VALUES (26708, 'a talented young musician', 'n. 音乐家', '/mju:\'ziʃən | mjuː\'zɪʃ(ə)n | mjʊ\'zɪʃən/', 'musician', 5);
INSERT INTO `words` VALUES (26709, 'Billy continued to stand there, mute and defiant.', 'adj. 哑的；沉默的；无声的; v. 减弱……的声音；使……柔和; n. 哑巴；弱音器；闭锁音', '/mju:t | mjuːt | mjut/', 'mute', 5);
INSERT INTO `words` VALUES (26710, 'Elsie muttered something I couldn’t catch and walked off.', 'v. 咕哝；喃喃自语; n. 咕哝；喃喃低语', '/\'mʌtə | \'mʌtɚ/', 'mutter', 5);
INSERT INTO `words` VALUES (26711, '...a leg of mutton.', 'n. 羊肉', '/\'mʌt(ə)n | \'mʌtn/', 'mutton', 5);
INSERT INTO `words` VALUES (26712, 'I didn’t like Dev, and the feeling seemed to be mutual.', 'adj. 共同的；相互的，彼此的', '/\'mju:tʃuəl, -tjuəl | \'mjuːtʃʊəl; -tjʊəl | \'mjutʃuəl/', 'mutual', 5);
INSERT INTO `words` VALUES (26713, 'The police are investigating the mysterious deaths of children at the hospital.', 'adj. 神秘的；不可思议的；难解的', '/mi\'stiəriəs | mɪ\'stɪərɪəs | mɪ\'stɪrɪəs/', 'mysterious', 5);
INSERT INTO `words` VALUES (26714, 'Twenty years after the event, his death remains a mystery .', 'n. 秘密，谜；神秘，神秘的事物；推理小说，推理剧；常作 mysteries 秘技，秘诀', '/英 [ˈmɪstri] 美 [ˈmɪstəri] | ˈmɪstri/', 'mystery', 5);
INSERT INTO `words` VALUES (26715, 'a book of Greek myths', 'n. 神话；虚构的人，虚构的事', '/miθ | mɪθ/', 'myth', 5);
INSERT INTO `words` VALUES (26716, 'Frank put the first plank down and nailed it in place.', 'v. 钉；使固定；揭露; n. [解剖] 指甲；钉子', '/neil | neɪl | nel/', 'nail', 5);
INSERT INTO `words` VALUES (26717, 'a naive young girl', 'adj. 天真的,幼稚的', '/nɑ:\'i:v | naɪ\'iːv; nɑː\'iːv | naɪ\'iv/', 'naive', 5);
INSERT INTO `words` VALUES (26718, 'The children ran naked through the yard.', 'adj. 裸体的；无装饰的；无证据的；直率的', '/\'neikid | \'neɪkɪd | \'nekɪd/', 'naked', 5);
INSERT INTO `words` VALUES (26719, 'Her name is Mandy Wilson.', 'n. 名字(称/声/义); v. 给…取名；列举；提名', '/neɪm | nem/', 'name', 5);
INSERT INTO `words` VALUES (26720, 'Three students were mentioned, namely John, Sarah and Sylvia.', 'adv. 即,也就是', '/\'neimli | \'neɪmlɪ | \'nemli/', 'namely', 5);
INSERT INTO `words` VALUES (26721, 'an afternoon nap', 'n. 小睡，打盹儿；细毛；孤注一掷; v. 使拉毛', '/næp/', 'nap', 5);
INSERT INTO `words` VALUES (26722, '...taking tiny bites of a hot dog and daintily wiping my lips with a napkin.', 'n. 餐巾；餐巾纸；尿布', '/\'næpkin | \'næpkɪn/', 'napkin', 5);
INSERT INTO `words` VALUES (26723, 'At several points in the narrative the two stories cross.', 'n. 叙述；故事；讲述; adj. 叙事的，叙述的；叙事体的', '/\'nærətiv | \'nærətɪv/', 'narrative', 5);
INSERT INTO `words` VALUES (26724, 'The stairs were very narrow.', 'adj. 狭窄的，有限的；勉强的；精密的；度量小的; n. 海峡；狭窄部分，隘路; v. 使变狭窄', '/\'nærəu | \'nærəʊ | \'næro/', 'narrow', 5);
INSERT INTO `words` VALUES (26725, 'a nasty temper', 'adj. 下流的；肮脏的；脾气不好的；险恶的; n. 令人不快的事物', '/[\'nɑ:sti, \'næs-] | \'nɑːstɪ | \'næsti/', 'nasty', 5);
INSERT INTO `words` VALUES (26726, 'the President’s radio broadcast to the nation', 'n. 国家；民族；国民', '/\'neiʃən | \'neɪʃ(ə)n | \'neʃən/', 'nation', 5);
INSERT INTO `words` VALUES (26727, 'Religion matters very much at a national level.', 'adj. 国家的；国民的；民族的；国立的; n. 国民', '/\'næʃənəl | \'næʃ(ə)n(ə)l | \'næʃnəl/', 'national', 5);
INSERT INTO `words` VALUES (26728, 'people of the same nationality', 'n. 国籍，国家；民族；部落', '/,næʃən\'æliti | næʃə\'nælɪtɪ | ,næʃə\'næləti/', 'nationality', 5);
INSERT INTO `words` VALUES (26729, 'They never saw their native land again.', 'adj. 本国的；土著的；天然的；与生俱来的；天赋的; n. 本地人；土产；当地居民', '/\'neitiv | \'neɪtɪv | \'netɪv/', 'native', 5);
INSERT INTO `words` VALUES (26730, 'the study of the natural world', 'adj. 自然的；物质的；天生的；不做作的; n. 自然的事情；白痴；本位音', '/\'nætʃərəl | \'nætʃ(ə)r(ə)l | \'nætʃrəl/', 'natural', 5);
INSERT INTO `words` VALUES (26731, 'You’re a very naughty boy! Look what you’ve done!', 'adj. 顽皮的，淘气的；不听话的；没规矩的；不适当的；下流的', '/\'nɔ:ti | \'nɔːtɪ | \'nɔti/', 'naughty', 5);
INSERT INTO `words` VALUES (26732, 'a naval officer', 'adj. 海军的；军舰的; n. (Naval)人名；(西、德、印)纳瓦尔', '/\'neivəl | \'neɪv(ə)l | \'nevl/', 'naval', 5);
INSERT INTO `words` VALUES (26733, 'compasses and other instruments of navigation', 'n. 航行；航海', '/,nævi\'ɡeiʃən | nævɪ\'geɪʃ(ə)n | \'nævə\'geʃən/', 'navigation', 5);
INSERT INTO `words` VALUES (26734, 'the British Navy', 'n. 海军', '/\'neivi | \'neɪvɪ | \'nevi/', 'navy', 5);
INSERT INTO `words` VALUES (26735, 'Lucy was staying in the nearby town of Hamilton.', 'adj. 附近的，邻近的; adv. 在附近; prep. 在…附近', '/\'niə\'bai | \'nɪəbaɪ | ,nɪr\'baɪ/', 'nearby', 5);
INSERT INTO `words` VALUES (26736, 'neat handwriting', 'adj. 灵巧的；整洁的；优雅的；齐整的；未搀水的；平滑的', '/ni:t | niːt | nit/', 'neat', 5);
INSERT INTO `words` VALUES (26737, 'The booklet provides all the necessary information about the college.', 'adj. 必要的；必需的；必然的; n. 必需品', '/\'nesisəri | ˈnɛsɪsərɪ | ˈnɛsəˌsɛri/', 'necessary', 5);
INSERT INTO `words` VALUES (26738, 'Lack of money necessitated a change of plan.', 'v. 使成为必需，需要；迫使', '/ni\'sesi,teit, nə- | nɪ\'sesɪteɪt | nə\'sɛsɪtet/', 'necessitate', 5);
INSERT INTO `words` VALUES (26739, 'She saw books as a necessity, not a luxury.', 'n. 需要；必然性；必需品', '/ni\'sesəti, nə- | nɪ\'sesɪtɪ | nə\'sɛsəti/', 'necessity', 5);
INSERT INTO `words` VALUES (26740, 'Mike rubbed the back of his neck.', 'n. 脖子；衣领；海峡; v. 搂著脖子亲吻；变狭窄', '/nek | nɛk/', 'neck', 5);
INSERT INTO `words` VALUES (26741, '...a diamond necklace and matching earrings.', 'n. 项链', '/\'neklis | \'neklɪs | \'nɛkləs/', 'necklace', 5);
INSERT INTO `words` VALUES (26742, 'She carried hypodermic needles and syringes in her bag.', 'n. 针；指针；刺激；针状物; v. 缝纫；做针线', '/\'ni:dl | \'niːd(ə)l | \'nidl/', 'needle', 5);
INSERT INTO `words` VALUES (26743, 'students with a negative attitude to school', 'adj. [数] 负的；消极的；否定的；阴性的; n. 否定；负数；[摄] 底片; v. 否定；拒绝', '/\'neɡətiv | \'negətɪv | \'nɛɡətɪv/', 'negative', 5);
INSERT INTO `words` VALUES (26744, 'Many of these ideas have been neglected by modern historians.', 'v&n. 忽视;疏忽,漏做,忽略', '/ni\'ɡlekt | nɪ\'glekt | nɪ\'glɛkt/', 'neglect', 5);
INSERT INTO `words` VALUES (26745, 'The damage done to his property was negligible.', 'adj. 可忽略不计的，微不足道的', '/\'neɡlidʒəbl | \'neglɪdʒɪb(ə)l | \'nɛɡlɪdʒəbl/', 'negligible', 5);
INSERT INTO `words` VALUES (26746, 'His first aim is to get the warring parties back to the negotiating table (= discussing something ).', 'v. 谈判，商议；转让；越过', '/ni\'ɡəuʃieit, -si- | nɪ\'gəʊʃɪeɪt | nɪ\'ɡoʃɪet/', 'negotiate', 5);
INSERT INTO `words` VALUES (26747, 'Slavery was “an unqualified evil to the negro, the white man, and the State,” said Abraham Lincoln in the 1850s.', 'n. 黑人; adj. 黑人的', '/\'ni:grəu | \'niːgrəʊ | \'nigro/', 'negro', 5);
INSERT INTO `words` VALUES (26748, 'I parked my baby at the neighbor\'s house.', 'n. 邻居; adj. 邻近的; v. 友好；毗邻而居', '/\'neibə | \'neɪbə | \'nebɚ/', 'neighbor', 5);
INSERT INTO `words` VALUES (26749, NULL, 'n. 附近；街坊；接近；街区', '/\'neɪbə,hʊd | \'nebɚ,hʊd/', 'neighborhood', 5);
INSERT INTO `words` VALUES (26750, 'She grew up in a quiet neighborhood of Boston.', 'n. 邻居； 四邻； 街道， 住宅区', '/\'neɪbəhud | nebɚˌhʊd/', 'neighbourhood', 5);
INSERT INTO `words` VALUES (26751, 'I am planning a 25th birthday party for my nephew.', 'n. 侄子；外甥', '/\'nefju: | \'nefjuː; \'nevjuː | \'nɛfju/', 'nephew', 5);
INSERT INTO `words` VALUES (26752, 'a condition which affects the nerves in the back', 'n. 神经；勇气；[植] 叶脉; v. 鼓起勇气', '/nə:v | nɜːv | nɝv/', 'nerve', 5);
INSERT INTO `words` VALUES (26753, 'I wish you’d stop looking at me like that. You’re making me nervous.', 'adj. 神经的；紧张不安的；强健有力的', '/\'nə:vəs | \'nɜːvəs | \'nɝvəs/', 'nervous', 5);
INSERT INTO `words` VALUES (26754, 'a bird’s nest', 'n. 巢，窝；安乐窝；温床; v. 筑巢；嵌套', '/nest | nɛst/', 'nest', 5);
INSERT INTO `words` VALUES (26755, 'Hungary’s telephone network', 'n. 网络；广播网；网状物', '/\'netwə:k | \'netwɜːk | \'nɛtwɝk/', 'network', 5);
INSERT INTO `words` VALUES (26756, 'I always tried to remain neutral when they started arguing.', 'adj. 中立的，中性的；中立国的；非彩色的; n. 中立国；中立者；非彩色；齿轮的空档', '/\'nju:trəl | \'njuːtr(ə)l | \'nʊtrəl/', 'neutral', 5);
INSERT INTO `words` VALUES (26757, 'Each atomic cluster is made up of neutrons and protons.', 'n. 【核】 中子 <', '/\'njuːtrɒn | \'nʊtrɑn/', 'neutron', 5);
INSERT INTO `words` VALUES (26758, 'What you said was true. It was, nevertheless, a little unkind.', 'adv. 仍然， 不过; conj. 然而， 不过', '/ˌnevəðə\'les | ,nɛvɚðə\'lɛs/', 'nevertheless', 5);
INSERT INTO `words` VALUES (26759, 'She had read about it in the newspapers.', 'n. 报纸', '/\'nju:s,peipə, \'nju:z- | \'njuːzpeɪpə; \'njuːs- | \'nuzpepɚ/', 'newspaper', 5);
INSERT INTO `words` VALUES (26760, 'They’ve got a very nice house.', 'adj. 精密的；美好的；细微的；和蔼的; n. (Nice)人名；(英)尼斯', '/nais | naɪs/', 'nice', 5);
INSERT INTO `words` VALUES (26761, '...a large glass jar filled with pennies, nickels, dimes, and quarters.', 'n. 镍；镍币；五分镍币; v. 镀镍于', '/\'nikəl | \'nɪk(ə)l | \'nɪkl/', 'nickel', 5);
INSERT INTO `words` VALUES (26762, 'Stephen earned himself the nickname Hawkeye.', 'n. 绰号，浑名vt.给…起绰号', '/\'nikneim | \'nɪkneɪm | \'nɪk\'nem/', 'nickname', 5);
INSERT INTO `words` VALUES (26763, '...his niece, the daughter of his eldest sister.', 'n. 外甥女，侄女', '/ni:s | niːs | nis/', 'niece', 5);
INSERT INTO `words` VALUES (26764, 'All the victims still suffered nightmares.', 'n. 恶梦；可怕的事物，无法摆脱的恐惧', '/\'naitmεə | \'naɪtmeə | \'naɪt\'mɛr/', 'nightmare', 5);
INSERT INTO `words` VALUES (26765, 'It was nineteen minutes past seven.', 'num. 十九', '/,nain\'ti:n | naɪn\'tiːn; \'naɪntiːn | ,naɪn\'tin/', 'nineteen', 5);
INSERT INTO `words` VALUES (26766, 'Well, we know nitrogen has what?', 'n. [化学] 氮', '/\'naitrədʒən | \'naɪtrədʒ(ə)n | \'naɪtrədʒən/', 'nitrogen', 5);
INSERT INTO `words` VALUES (26767, 'It’s very noble of you to spend all your weekends helping the old folk.', 'adj. 高尚的；贵族的；惰性的；宏伟的; n. 贵族; vt. 抓住；逮捕', '/\'nəubl | \'nəʊb(ə)l | \'nobl/', 'noble', 5);
INSERT INTO `words` VALUES (26768, 'The woman greeted us with a nod of the head.', 'n. 点头；打盹；摆动; v. 点头；点头表示', '/nɔd | nɒd | nɑd/', 'nod', 5);
INSERT INTO `words` VALUES (26769, 'What’s that noise?', 'n. [环境] 噪音；响声；杂音; v. 谣传', '/nɔiz | nɒɪz | nɔɪz/', 'noise', 5);
INSERT INTO `words` VALUES (26770, 'The kids have been really noisy today.', 'adj. 嘈杂的；喧闹的；聒噪的', '/\'nɒɪzɪ | \'nɔɪzi/', 'noisy', 5);
INSERT INTO `words` VALUES (26771, 'the nominal head of the rebellion', 'adj. 名义上的;(金额,租金)微不足道的 name', '/\'nɔminəl | \'nɒmɪn(ə)l | \'nɑmɪnl/', 'nominal', 5);
INSERT INTO `words` VALUES (26772, 'This week one of them will be nominated by the Democratic Party for the presidency of the United States.', 'v. 提名,任命', '/\'nɔmineit, \'nɔminət, -neit | \'nɒmɪneɪt | \'nɑmɪnet/', 'nominate', 5);
INSERT INTO `words` VALUES (26773, 'The region was extremely beautiful. Nonetheless Gerard could not imagine spending the rest of his life there.', 'adv. 尽管如此，但是', '/nʌnðə\'les | \'nʌnðə\'lɛs/', 'nonetheless', 5);
INSERT INTO `words` VALUES (26774, '‘I’m a prisoner in my own home.’ ‘Nonsense!’', 'n. 胡说， 废话', '/\'nɒnsns | \'nɑnsɛns/', 'nonsense', 5);
INSERT INTO `words` VALUES (26775, 'We met at 12 noon.', 'n. 中午；正午；全盛期', '/nu:n | nuːn | nun/', 'noon', 5);
INSERT INTO `words` VALUES (26776, 'Joyce’s style of writing was a striking departure from the literary norm.', 'n. 标准，规范', '/nɔːm | nɔrm/', 'norm', 5);
INSERT INTO `words` VALUES (26777, 'A normal working week is 40 hours.', 'adj. 正常的；正规的，标准的; n. 正常；标准；常态', '/\'nɔ:məl | \'nɔːm(ə)l | \'nɔrml/', 'normal', 5);
INSERT INTO `words` VALUES (26778, 'The trend of half permanent enterprise management culture towards normalization direction.', 'n. 正常化；标准化；正规化；常态化', '/,nɔ:məlai\'zeiʃən, -li\'z | ,nɔːməlaɪ\'zeɪʃən | nɔrmləˈzeʃən/', 'normalization', 5);
INSERT INTO `words` VALUES (26779, 'Which way is north?', 'n. 北，北方; adj. 北方的；朝北的; adv. 在北方，向北方', '/nɔ:θ | nɔːθ | nɔrθ/', 'north', 5);
INSERT INTO `words` VALUES (26780, '...a climate like that of our northeast coast.', 'adj. 东北的；向东北的；来自东北的; n. 东北; adv. 向东北；来自东北', '/,nɔ:θ\'i:st | \'nɔrθ\'ist/', 'northeast', 5);
INSERT INTO `words` VALUES (26781, 'a man with a northern accent', 'adj. 北部的；北方的; n. 北部方言', '/\'nɔ:ðən | \'nɔːð(ə)n | \'nɔrðɚn/', 'northern', 5);
INSERT INTO `words` VALUES (26782, 'the northwest suburbs of the city', 'adj. 西北的；向西北的；来自西北的; n. 西北; adv. 在西北；向西北；来自西北', '/,nɔ:θ\'west | \'nɔrθ\'wɛst/', 'northwest', 5);
INSERT INTO `words` VALUES (26783, 'Someone punched him on the nose.', 'n. 鼻子；嗅觉；突出的部分；探问; v. 嗅；用鼻子触', '/nəuz | nəʊz | noz/', 'nose', 5);
INSERT INTO `words` VALUES (26784, 'Seeing those old school photographs has made me feel quite nostalgic.', 'adj. 怀旧的', '/nɒ\'stældʒɪk/', 'nostalgic', 5);
INSERT INTO `words` VALUES (26785, 'Every country in the world signed the treaty, with one notable exception - the United States.', 'adj. 值得注意的，显著的；著名的; n. 名人，显要人物', '/\'nəutəbl | \'nəʊtəb(ə)l | \'notəbl/', 'notable', 5);
INSERT INTO `words` VALUES (26786, 'He brought out a notebook and pen from his pocket.', 'n. 笔记本，笔记簿；手册', '/\'nəutbuk | \'nəʊtbʊk | \'notbʊk/', 'notebook', 5);
INSERT INTO `words` VALUES (26787, 'I waved but they took no notice.', 'n. 通知，布告；注意；公告; v. 通知；注意到；留心', '/\'nəutis | \'nəʊtɪs | \'notɪs/', 'notice', 5);
INSERT INTO `words` VALUES (26788, 'Alcohol has a noticeable effect on the body.', 'adj. 显而易见的，显著的；值得注意的', '/\'nəutisəbl | \'nəʊtɪsəb(ə)l | \'notɪsəbl/', 'noticeable', 5);
INSERT INTO `words` VALUES (26789, 'The skipper notified the coastguard of the tragedy.', 'v. 通告，通知；公布', '/\'nəutifai | \'nəʊtɪfaɪ | \'notə\'fai/', 'notify', 5);
INSERT INTO `words` VALUES (26790, 'She had no notion what he meant.', 'n. 概念；见解；打算', '/\'nəuʃən | \'nəʊʃ(ə)n | \'noʃən/', 'notion', 5);
INSERT INTO `words` VALUES (26791, 'a notorious computer hacker', 'adj. 声名狼藉的，臭名昭著的', '/nəu\'tɔ:riəs | nə(ʊ)\'tɔːrɪəs | no\'tɔrɪəs/', 'notorious', 5);
INSERT INTO `words` VALUES (26792, 'His relations with colleagues, differences of opinion notwithstanding, were unfailingly friendly.', 'adv. 尽管，仍然; prep. 尽管，虽然; conj. 虽然', '/,nɔtwiθ\'stændiŋ, -wið- | nɒtwɪð\'stændɪŋ; -wɪθ- | ,nɑtwɪθ\'stændɪŋ/', 'notwithstanding', 5);
INSERT INTO `words` VALUES (26793, 'An adjective must agree with its noun in mumber and case.', 'n. 名词', '/naun | naʊn/', 'noun', 5);
INSERT INTO `words` VALUES (26794, 'The cream contains vitamin A to nourish the skin.', 'v. 滋养；怀有；使健壮', '/\'nʌriʃ, \'nə:- | \'nʌrɪʃ | \'nɜrɪʃ/', 'nourish', 5);
INSERT INTO `words` VALUES (26795, 'Protesters found a novel way of demonstrating against steeply rising oil prices.', 'adj. 新奇的， 新颖的; n. 小说', '/\'nɒvl | ˈnɑːvl/', 'novel', 5);
INSERT INTO `words` VALUES (26796, 'Many toys have no attraction beyond their novelty value.', 'n. 新奇；新奇的事物；新颖小巧而廉价的物品', '/\'nɔvəlti | \'nɒv(ə)ltɪ | \'nɑvlti/', 'novelty', 5);
INSERT INTO `words` VALUES (26797, NULL, 'n. 十一月', '/nəu\'vembə | nə(ʊ)\'vembə | no\'vɛmbɚ/', 'november', 5);
INSERT INTO `words` VALUES (26798, 'Nowadays people are rarely shocked by the sex they see on television.', 'adv. 现今；时下; n. 当今', '/\'nauədeiz | \'naʊədeɪz | \'naʊədez/', 'nowadays', 5);
INSERT INTO `words` VALUES (26799, 'Nowhere is drug abuse more of a problem than in the US.', 'adv. 任何地方都不， 没有地方 <', '/\'nəuweə | \'no\'wɛr/', 'nowhere', 5);
INSERT INTO `words` VALUES (26800, 'France’s reliance on nuclear energy', 'adj. 原子能的；[细胞] 细胞核的；中心的；原子核的', '/\'nju:kliə, \'nu:- | \'njuːklɪə | \'nuklɪɚ/', 'nuclear', 5);
INSERT INTO `words` VALUES (26801, 'Neutrons and protons are bound together in the nucleus of an atom.', 'n. 核，核心；原子核', '/\'nju:kliəs | \'njuːklɪəs | \'nuklɪəs/', 'nucleus', 5);
INSERT INTO `words` VALUES (26802, 'The nightclub has been declared a public nuisance.', 'n. 讨厌的人；损害；麻烦事；讨厌的东西', '/\'nju:səns | \'njuːs(ə)ns | \'nusns/', 'nuisance', 5);
INSERT INTO `words` VALUES (26803, 'The cold had numbed her fingers.', 'v. 使麻木；使发愣；使失去感觉; adj. 麻木的；发愣的', '/nʌm/', 'numb', 5);
INSERT INTO `words` VALUES (26804, 'a numerical code', 'adj. 数值的；数字的；用数字表示的（等于numeric）', '/nju:\'merikəl | njuː\'merɪk(ə)l | nʊ\'mɛrɪkl/', 'numerical', 5);
INSERT INTO `words` VALUES (26805, 'Numerous attempts have been made to hide the truth.', 'adj. 许多的，很多的', '/\'nju:mərəs | \'njuːm(ə)rəs | \'numərəs/', 'numerous', 5);
INSERT INTO `words` VALUES (26806, 'Shaw has been nursing an injury, and will not play on Sunday.', 'v. 看护，护理；照顾；培养；给…喂奶; n. 护士；奶妈，保姆', '/nə:s | nɜːs | nɝs/', 'nurse', 5);
INSERT INTO `words` VALUES (26807, 'She puts her baby in this nursery and then goes back to work.', 'n. 苗圃；托儿所；温床', '/\'nə:səri | \'nɜːs(ə)rɪ | \'nɝsəri/', 'nursery', 5);
INSERT INTO `words` VALUES (26808, 'plants nurtured in the greenhouse', 'v. 养育；鼓励；培植; n. 养育；教养；营养物', '/\'nə:tʃə | \'nɜːtʃə | \'nɝtʃɚ/', 'nurture', 5);
INSERT INTO `words` VALUES (26809, 'a pine nut', 'n. 螺母，螺帽；坚果；难对付的人，难解的问题; v. 采坚果', '/nʌt/', 'nut', 5);
INSERT INTO `words` VALUES (26810, 'Nutrition and exercise are essential to fitness and health.', 'n. 营养，营养学；营养品', '/nju:\'triʃən | njʊ\'trɪʃ(ə)n | nu\'trɪʃən/', 'nutrition', 5);
INSERT INTO `words` VALUES (26811, 'nylon fabric', 'n. 尼龙，[纺] 聚酰胺纤维；尼龙袜', '/\'nailɔn | \'naɪlɒn | \'naɪlɑn/', 'nylon', 5);
INSERT INTO `words` VALUES (26812, 'an oak door', 'n. 橡树；橡木色；橡木家具; adj. 栎树的；栎木制的', '/əuk | əʊk | ok/', 'oak', 5);
INSERT INTO `words` VALUES (26813, 'We were getting along fine until you stuck your oar in.', 'n. 桨；橹；桨手; vt. 划（船）; vi. 划行', '/ɔ:, əu | ɔː | ɔr/', 'oar', 5);
INSERT INTO `words` VALUES (26814, 'The president took the oath of office (= made the official public promises that every president makes when starting their job ) .', 'n. 誓言，誓约；诅咒，咒骂', '/əuθ | əʊθ | oθ/', 'oath', 5);
INSERT INTO `words` VALUES (26815, 'obedience classes for dogs and their owners', 'n. 顺从；服从；遵守', '/ə\'biːdiəns | ə\'biːdɪəns | ə\'bidjəns/', 'obedience', 5);
INSERT INTO `words` VALUES (26816, 'an obedient child', 'adj. 顺从的，服从的；孝顺的', '/əu\'bi:diənt | ə\'biːdɪənt | oˈbidiənt/', 'obedient', 5);
INSERT INTO `words` VALUES (26817, 'But, it warns this progress could be set back if measures are not taken to reverse the rise in obesity among young people.', 'n. 肥大， 肥胖', '/əu\'biːsəti | o\'bisəti/', 'obesity', 5);
INSERT INTO `words` VALUES (26818, 'The little boy made no effort to obey.', 'v. 服从，听从；按照……行动; n. (Obey)人名；(英、法)奥贝', '/əu\'bei | ə(ʊ)\'beɪ | ə\'be/', 'obey', 5);
INSERT INTO `words` VALUES (26819, 'an everyday object such as a spoon', 'n. 物体;客体,对象;目标;宾语; v. (to)反对', '/\'ɔbdʒikt, -dʒekt, əb\'dʒekt | \'ɒbdʒɪkt; -dʒekt | \'ɑbdʒɛkt/', 'object', 5);
INSERT INTO `words` VALUES (26820, 'Her objection was that he was too young.', 'n. (to)反对,异议,不喜欢,反对的理由', '/əb\'dʒekʃən, ɔb- | əb\'dʒekʃ(ə)n | əb\'dʒɛkʃən/', 'objection', 5);
INSERT INTO `words` VALUES (26821, 'He vowed to achieve certain objectives before the end of his presidency.', 'n. 目标,目的; adj. 客观的,真实的', '/əb\'dʒektiv, ɔb- | əb\'dʒektɪv | əb\'dʒɛktɪv/', 'objective', 5);
INSERT INTO `words` VALUES (26822, 'Employers have an obligation to treat all employees equally.', 'n. 义务,责任', '/,ɔbli\'ɡeiʃən | ɒblɪ\'geɪʃ(ə)n | ,ɑblɪ\'ɡeʃən/', 'obligation', 5);
INSERT INTO `words` VALUES (26823, 'I’d be obliged if you’d treat this matter as strictly confidential.', 'v. 强迫,迫使;责成;(使)感激,施恩于', '/ə\'blaɪdʒ/', 'oblige', 5);
INSERT INTO `words` VALUES (26824, 'obscure legal phrases', 'adj. 暗的,朦胧的;模糊的,晦涩的', '/əb\'skjʊə | əb\'skjʊr/', 'obscure', 5);
INSERT INTO `words` VALUES (26825, 'He spent two nights under close observation in hospital.', 'n. 观察；监视；观察报告', '/,ɔbzə:\'veiʃən | ɒbzə\'veɪʃ(ə)n | ,ɑbzɚ\'veʃən/', 'observation', 5);
INSERT INTO `words` VALUES (26826, '...where he will observe Thanksgiving with family members.', 'v. 庆祝', '/əb\'zɜːv | əb\'zɝv/', 'observe', 5);
INSERT INTO `words` VALUES (26827, 'Gambling became an obsession, and he eventually lost everything.', 'n. 痴迷；困扰；[内科][心理] 强迫观念', '/əb\'seʃən, ɔb- | əb\'seʃ(ə)n | əb\'sɛʃ(ə)n/', 'obsession', 5);
INSERT INTO `words` VALUES (26828, 'obsolete weapons', 'adj. 已废弃的,过时的', '/\'ɔbsəli:t, ,ɔbsə\'li:t | \'ɒbsəliːt | ɑbsəˌlit/', 'obsolete', 5);
INSERT INTO `words` VALUES (26829, 'The tax puts obstacles in the way of companies trying to develop trade overseas.', 'n. 障碍，干扰；妨害物', '/\'ɔbstəkl | \'ɒbstək(ə)l | \'ɑbstəkl/', 'obstacle', 5);
INSERT INTO `words` VALUES (26830, 'A small aircraft was obstructing the runway.', 'v. 妨碍；阻塞；遮断', '/əb\'strʌkt, ɔb- | əb\'strʌkt/', 'obstruct', 5);
INSERT INTO `words` VALUES (26831, 'John was irritated by drivers parking near his house and causing an obstruction.', 'n. 障碍；阻碍；妨碍', '/əb\'strʌkʃən, ɔb- | əb\'strʌkʃ(ə)n/', 'obstruction', 5);
INSERT INTO `words` VALUES (26832, 'Evans was trying to obtain a false passport and other documents.', 'v. 获得,得到', '/əb\'tein, ɔb- | əb\'teɪn | əb\'ten/', 'obtain', 5);
INSERT INTO `words` VALUES (26833, 'The obvious way of reducing pollution is to use cars less.', 'adj. 明显的；显著的；平淡无奇的', '/\'ɔbviəs | \'ɒbvɪəs | \'ɑbvɪəs/', 'obvious', 5);
INSERT INTO `words` VALUES (26834, 'His remark was the occasion of a bitter quarrel.', 'n. 时机，机会；场合；理由; v. 引起，惹起', '/ə\'keiʒən, əu- | ə\'keɪʒ(ə)n | ə\'keʒn/', 'occasion', 5);
INSERT INTO `words` VALUES (26835, 'I\'ve had occasional mild headaches all my life.', 'adj. 偶然的；临时的；特殊场合的', '/ə\'keiʒənəl, əu- | ə\'keɪʒ(ə)n(ə)l | ə\'keʒənl/', 'occasional', 5);
INSERT INTO `words` VALUES (26836, 'Please state your name, address and occupation.', 'n. 占领,占据;占用;职业,工作', '/,ɔkju\'peiʃən | ɒkjʊ\'peɪʃ(ə)n | ,ɑkju\'peʃən/', 'occupation', 5);
INSERT INTO `words` VALUES (26837, 'He occupies the house without paying any rent.', 'v. 占,占用;占据,占领;使忙碌,使从事', '/\'ɔkjupai | \'ɒkjʊpaɪ | \'ɑkjupaɪ/', 'occupy', 5);
INSERT INTO `words` VALUES (26838, 'A third of accidental deaths occur in the home.', 'v. 发生,出现;存在;想起,想到', '/ə\'kə: | ə\'kɜː | ə\'kɝ/', 'occur', 5);
INSERT INTO `words` VALUES (26839, 'Complaints seemed to be an everyday occurrence.', 'n. 发生,出现;事件,事故,发生的事情', '/ə\'kə:rəns, -\'kʌ- | ə\'kʌr(ə)ns | ə\'kʌrəns/', 'occurrence', 5);
INSERT INTO `words` VALUES (26840, 'Most seasonal hiring is done in early October.', 'n. [天] 十月', '/ɔk\'təubə | ɒk\'təʊbə | ɑk\'tobɚ/', 'october', 5);
INSERT INTO `words` VALUES (26841, 'It was an odd thing to say.', 'adj. 奇数的；古怪的；剩余的；临时的；零散的; n. 奇数；怪人；奇特的事物', '/ɔd | ɒd | ɑd/', 'odd', 5);
INSERT INTO `words` VALUES (26842, 'We are offering odds of 6-1 on the fight ending in a knockout.', 'n. 几率；胜算；不平等；差别', '/ɔdz | ɒdz | ɑdz/', 'odds', 5);
INSERT INTO `words` VALUES (26843, 'The researchers demonstrate that it is possible to generate odor in a compact device that can fit on the back of a TV with potentially thousands of odors.', 'n. 气味；名声', '/\'əudə | \'əʊdə | \'oʊdə/', 'odor', 5);
INSERT INTO `words` VALUES (26844, '...the lingering odour of car exhaust.', 'n. 气味； 名声', '/\'əudə/', 'odour', 5);
INSERT INTO `words` VALUES (26845, 'His remarks deeply offended many Scottish people.', 'v. 冒犯；使…不愉快', '/ə\'fend | ə\'fɛnd/', 'offend', 5);
INSERT INTO `words` VALUES (26846, 'I found her remarks deeply offensive.', 'adj. 攻击的；冒犯的；无礼的；讨厌的; n. 攻势；攻击', '/ə\'fensiv | ə\'fensɪv | ə\'fɛnsɪv/', 'offensive', 5);
INSERT INTO `words` VALUES (26847, 'A number of groups offer their services free of charge.', 'v. 提供；出价；试图; n. 提议；出价；意图；录取通知书', '/ˈɒfə | \'ɒfə | \'ɔfɚ/', 'offer', 5);
INSERT INTO `words` VALUES (26848, 'The department occupies an office just a mile from the White House.', 'n. 办公室,办事处;职务,公职;部,局,处', '/\'ɔfis, \'ɔ:- | \'ɒfɪs | \'ɔfɪs/', 'office', 5);
INSERT INTO `words` VALUES (26849, 'a commanding officer of the SAS', 'n. 官员,办事员;工作人员;军官', '/\'ɔfisə, \'ɔ:- | \'ɒfɪsə | \'ɔfɪsɚ/', 'officer', 5);
INSERT INTO `words` VALUES (26850, NULL, 'n. 官员,行政官员; adj. 官方的,官方的,正式的', '/ə\'fɪʃ(ə)l | əˈfɪʃəl; oʊˈfɪʃəl/', 'official', 5);
INSERT INTO `words` VALUES (26851, 'Cuts in food prices will be offset by direct payments to farmers.', 'n. 抵消，补偿；平版印刷；支管; v. 抵消；弥补；用平版印刷术印刷', '/,ɔf\'set, ,ɔ:-, \'ɔfset, \'ɔ:- | \'ɒfset | ,ɔf\'sɛt/', 'offset', 5);
INSERT INTO `words` VALUES (26852, 'a young mother trying to control her offspring', 'n. 后代，子孙；产物', '/\'ɔfspriŋ, \'ɔ:- | \'ɒfsprɪŋ | \'ɔfsprɪŋ/', 'offspring', 5);
INSERT INTO `words` VALUES (26853, 'a rise in the price of oil', 'n. 油；石油；油画颜料; v. 加油；涂油；使融化', '/ɔil | ɒɪl | ɔɪl/', 'oil', 5);
