INSERT INTO `words` VALUES (26857, 'a shower with an opaque glass door', 'adj. 不透明的；不传热的；迟钝的; n. 不透明物; vt. 使不透明；使不反光', '/əu\'peik | ə(ʊ)\'peɪk | o\'pek/', 'opaque', 5);
INSERT INTO `words` VALUES (26858, 'There are very few openings in scientific research.', 'n. 开始；机会；通路；空缺的职位; adj. 开始的; v. 开放（open的ing形式）；打开；公开', '/\'əupəniŋ | \'əʊp(ə)nɪŋ | \'opənɪŋ/', 'opening', 5);
INSERT INTO `words` VALUES (26859, 'We go to the opera (= go to a performance of opera ) regularly.', 'n. 歌剧；歌剧院；歌剧团', '/\'ɔpərə | \'ɒp(ə)rə | \'ɑprə/', 'opera', 5);
INSERT INTO `words` VALUES (26860, 'Doctors had to operate to remove the bullet.', 'v. 运转；动手术；起作用', '/\'ɒpəreɪt | \'ɑpə\'ret/', 'operate', 5);
INSERT INTO `words` VALUES (26861, 'Many small businesses fail in the first year of operation.', 'n. 操作；经营；[外科] 手术；[数][计] 运算', '/,ɔpə\'reiʃən | ɒpə\'reɪʃ(ə)n | ,ɑpə\'reʃən/', 'operation', 5);
INSERT INTO `words` VALUES (26862, 'The boat should be operational by this afternoon.', 'adj. 操作的；运作的', '/,ɔpə\'reiʃənəl | ɒpə\'reɪʃ(ə)n(ə)l | \'ɑpə\'reʃənl/', 'operational', 5);
INSERT INTO `words` VALUES (26863, 'computers which can be used by untrained operators', 'n. 经营者；操作员；话务员；行家', '/\'ɔpəreitə | \'ɒpəreɪtə | \'ɑpəretɚ/', 'operator', 5);
INSERT INTO `words` VALUES (26864, 'When choosing an insurance policy it’s best to get an independent opinion.', 'n. 意见；主张', '/ə\'pinjən | ə\'pɪnjən/', 'opinion', 5);
INSERT INTO `words` VALUES (26865, 'Graf’s opponent in today’s final will be Sukova.', 'n. 对手；反对者；敌手; adj. 对立的；敌对的', '/ə\'pəunənt | ə\'pəʊnənt | ə\'ponənt/', 'opponent', 5);
INSERT INTO `words` VALUES (26866, 'There are fewer opportunities for new graduates this year.', 'n. 机会', '/,ɔpə\'tju:niti | ɒpə\'tjuːnɪtɪ | ˌɑpɚˈtunɪti, -ˈtju-/', 'opportunity', 5);
INSERT INTO `words` VALUES (26867, 'Congress is continuing to oppose the President’s health care budget.', 'v. 反对,使对立,使对抗,使相对', '/ə\'pəuz | ə\'pəʊz | ə\'poz/', 'oppose', 5);
INSERT INTO `words` VALUES (26868, 'I thought the medicine would make him sleep, but it had the opposite effect.', 'adj. 对面的,相对的,相反的; n. 对立面', '/\'ɔpəzit, -sit | \'ɒpəzɪt; -sɪt | ˈɑpəzɪt; ˈɑpəsɪt/', 'opposite', 5);
INSERT INTO `words` VALUES (26869, 'native tribes oppressed by the authorities', 'v. 压迫，压抑；使……烦恼；使……感到沉重', '/ə\'pres | ə\'prɛs/', 'oppress', 5);
INSERT INTO `words` VALUES (26870, 'Depending on your circumstances you can opt for one method or the other.', 'v. 选择', '/ɔpt | ɒpt | ɑpt/', 'opt', 5);
INSERT INTO `words` VALUES (26871, 'microscopes and other optical instruments', 'adj. 光学的；眼睛的，视觉的', '/\'ɔptikəl | \'ɒptɪk(ə)l | \'ɑptɪkl/', 'optical', 5);
INSERT INTO `words` VALUES (26872, 'Andrew took a more optimistic view.', 'adj. 乐观的；乐观主义的', '/,ɔpti\'mistik | ɒptɪ\'mɪstɪk | ,ɑptɪ\'mɪstɪk/', 'optimistic', 5);
INSERT INTO `words` VALUES (26873, 'optimum conditions for growth', 'adj. 最适宜的; n. 最佳效果；最适宜条件', '/\'ɔptiməm | \'ɒptɪməm | \'ɑptəməm/', 'optimum', 5);
INSERT INTO `words` VALUES (26874, 'There are a number of options available.', 'n. [计] 选项；选择权；买卖的特权', '/\'ɔpʃən | \'ɒpʃ(ə)n | \'ɑpʃən/', 'option', 5);
INSERT INTO `words` VALUES (26875, 'three optional courses', 'adj. 可选择的，随意的; n. 选修科目', '/\'ɔpʃənəl | \'ɒpʃ(ə)n(ə)l | \'ɑpʃənl/', 'optional', 5);
INSERT INTO `words` VALUES (26876, 'oral history', 'adj. 口头的，口述的; n. 口试', '/\'ɔ:rəl, \'ɔ- | \'ɔːr(ə)l | \'ɔrəl/', 'oral', 5);
