INSERT INTO `words` VALUES (26878, 'Mars and Earth have orbits which change with time.', 'n. 轨道；眼眶；势力范围；生活常规; v. 盘旋；绕轨道运行', '/\'ɔ:bit | \'ɔːbɪt | \'ɔrbɪt/', 'orbit', 5);
INSERT INTO `words` VALUES (26879, 'a cherry orchard', 'n. 果园；果树林', '/\'ɔ:tʃəd | \'ɔːtʃəd | \'ɔrtʃɚd/', 'orchard', 5);
INSERT INTO `words` VALUES (26880, 'the Berlin Symphony Orchestra', 'n. 管弦乐队', '/\'ɔːkɪstrə | \'ɔrkɪstrə/', 'orchestra', 5);
INSERT INTO `words` VALUES (26881, 'There seemed to be no logical order to the sections.', 'n. 命令;次序;整齐;定货单;等级; v. 定制,订购', '/\'ɔ:də | \'ɔːdə | \'ɔrdɚ/', 'order', 5);
INSERT INTO `words` VALUES (26882, 'She needs to organize her ideas in a more orderly way.', 'adj. 整齐的,有秩序的,有条理的; n. 勤务兵', '/\'ɔ:dəli | \'ɔːd(ə)lɪ | \'ɔrdɚli/', 'orderly', 5);
INSERT INTO `words` VALUES (26883, 'It’s just an ordinary camera.', 'adj. 普通的,平凡的,平常的;平庸的', '/\'ɔ:dinəri, -neri- | \'ɔːdɪn(ə)rɪ; -d(ə)n- | \'ɔrdnɛri/', 'ordinary', 5);
INSERT INTO `words` VALUES (26884, 'iron ore', 'n. 矿；矿石', '/ɔ: | ɔː | ɔr/', 'ore', 5);
INSERT INTO `words` VALUES (26885, 'the decision-making organs', 'n. [生物] 器官；机构；风琴；管风琴；嗓音', '/\'ɔ:ɡən | \'ɔːg(ə)n | \'ɔrɡən/', 'organ', 5);
INSERT INTO `words` VALUES (26886, 'Adding organic matter such as manure can improve the soil.', 'adj. [有化] 有机的；组织的；器官的；根本的', '/ɔ:\'ɡænik | ɔː\'gænɪk | ɔr\'gænɪk/', 'organic', 5);
INSERT INTO `words` VALUES (26887, NULL, 'n. 组织， 机构； 体制， 结构', '/ˌɔːgənaɪ\'zeɪʃn | ɔrɡənəˈzeʃən/', 'organisation', 5);
INSERT INTO `words` VALUES (26888, 'Do they organise words around a principle of syntax?', 'vt. 组织， 编组', '/\'ɔːgənaɪz | \'ɔrgə,naɪz/', 'organise', 5);
INSERT INTO `words` VALUES (26889, 'All living organisms have to adapt to changes in environmental conditions.', 'n. 有机体；生物体；微生物', '/\'ɔ:ɡənizəm | \'ɔːg(ə)nɪz(ə)m | \'ɔrɡənɪzəm/', 'organism', 5);
INSERT INTO `words` VALUES (26890, 'The public expect high standards from any large organization.', 'n. 组织；机构；体制；团体', '/,ɔ:ɡənai\'zeiʃən, -ni\'z- | ˌɔːɡənaɪ\'zeɪʃn | ,ɔrɡənə\'zeʃən/', 'organization', 5);
INSERT INTO `words` VALUES (26891, 'The course was organized by a training company.', 'v. 组织；使有系统化；给予生机；组织成立工会等', '/\'ɔ:ɡənaiz | ˈɔ:gənaɪz | ɔrɡənˌaɪz/', 'organize', 5);
INSERT INTO `words` VALUES (26892, 'She looked at the street names, trying to orient herself.', 'v. 使适应；确定方向；使朝东; n. 东方；东方诸国; adj. 东方的', '/\'ɔ:riənt, \'əu-, \'ɔ:rient | \'ɔːrɪənt; \'ɒr- | \'orɪənt/', 'orient', 5);
INSERT INTO `words` VALUES (26893, 'a beautiful oriental rug', 'adj. 东方的；东方人的; n. 东方人', '/,ɔ:ri\'entəl, ,əu- | ɔːrɪ\'ent(ə)l; ɒr- | ,orɪ\'ɛntəl/', 'oriental', 5);
INSERT INTO `words` VALUES (26894, 'The party has a broadly socialist orientation.', 'n. 方向；定向；适应；情况介绍；向东方', '/,ɔ:rien\'teiʃən, əu- | ,ɔːrɪən\'teɪʃ(ə)n; ,ɒr- | orɪɛn\'teʃən/', 'orientation', 5);
INSERT INTO `words` VALUES (26895, 'The tradition has its origins in the Middle Ages.', 'n. 起源；原点；出身；开端', '/\'ɔridʒin, \'ɔ:- | \'ɒrɪdʒɪn | \'ɔrɪdʒɪn/', 'origin', 5);
INSERT INTO `words` VALUES (26896, 'The colours are much more striking in the original.', 'n. 原件；原作；原物；原型; adj. 原始的；最初的；独创的；新颖的', '/ə\'ridʒənəl | ə\'rɪdʒɪn(ə)l; ɒ- | ə\'rɪdʒənl/', 'original', 5);
INSERT INTO `words` VALUES (26897, 'The technique was originated by an Italian artist.', 'v. 引起；创作', '/ə\'ridʒəneit | ə\'rɪdʒɪneɪt; ɒ- | əˈrɪdʒəˌnet/', 'originate', 5);
INSERT INTO `words` VALUES (26898, 'a silver goblet ornamented with pearls', 'v. 装饰,美化; n. 装饰,装饰物', '/\'ɔ:nəmənt, \'ɔ:nəment | \'ɔːnəm(ə)nt | \'ɔrnəmənt/', 'ornament', 5);
INSERT INTO `words` VALUES (26899, 'The war has left thousands of children as orphans.', 'adj. 孤儿的；无双亲的; n. 孤儿; v. 使成孤儿', '/\'ɔ:fən | \'ɔːf(ə)n | \'ɔrfn/', 'orphan', 5);
INSERT INTO `words` VALUES (26900, 'orthodox medical treatments', 'adj. 正统的；传统的；惯常的；东正教的; n. 正统的人；正统的事物', '/\'ɔːθədɒks | \'ɔrθədɑks/', 'orthodox', 5);
INSERT INTO `words` VALUES (26901, 'One ounce of almonds contains nearly half the recommended daily amount.', 'n. 盎司；少量；雪豹', '/auns | aʊns/', 'ounce', 5);
INSERT INTO `words` VALUES (26902, 'a cholera outbreak', 'n. （战争的）爆发；（疾病的）发作; vi. 爆发', '/\'autbreik, ,aut\'breik | \'aʊtbreɪk | \'aʊtbrek/', 'outbreak', 5);
INSERT INTO `words` VALUES (26903, 'People who had heard the evidence at the trial were surprised at the outcome.', 'n. 结果，结局；成果', '/\'autkʌm | \'aʊtkʌm | \'aʊt\'kʌm/', 'outcome', 5);
INSERT INTO `words` VALUES (26904, 'a huge outdoor market', 'adj. 户外的；露天的；野外的（等于out-of-door）', '/\'əutdɔ: | \'aʊtdɔː | \'aʊt\'dɔr/', 'outdoor', 5);
INSERT INTO `words` VALUES (26905, 'Remove the tough outer leaves before cooking.', 'adj. 外面的，外部的；远离中心的; n. 环外命中', '/\'autə | \'aʊtə | \'aʊtɚ/', 'outer', 5);
INSERT INTO `words` VALUES (26906, 'She bought a new outfit for the party.', 'n. 机构；用具；全套装备; v. 得到装备', '/\'autfit | \'aʊtfɪt/', 'outfit', 5);
INSERT INTO `words` VALUES (26907, 'One evening, she made a rare outing to the local night club.', 'n. 远足， 郊游， 短途旅行', '/\'autɪŋ | \'aʊtɪŋ/', 'outing', 5);
INSERT INTO `words` VALUES (26908, '...the largest retail outlet in the city.', 'n. 出口，排放孔；[电] 电源插座；销路；发泄的方法；批发商店', '/\'autlet, -lit | \'aʊtlet | \'aʊtlɛt/', 'outlet', 5);
INSERT INTO `words` VALUES (26909, 'a research proposal outline', 'n. 轮廓；大纲；概要；略图; v. 概述；略述；描画…轮廓', '/\'autlain | \'aʊtlaɪn/', 'outline', 5);
INSERT INTO `words` VALUES (26910, 'Exercise will improve your looks and your outlook.', 'n. 展望；观点；景色; vt. 比……好看；用目光压倒; vi. 朝外看', '/\'autluk, ,aut\'luk | \'aʊtlʊk/', 'outlook', 5);
INSERT INTO `words` VALUES (26911, 'Output is up 30% on last year.', 'n. 产量， 输出', '/\'autput | \'aʊtpʊt/', 'output', 5);
INSERT INTO `words` VALUES (26912, 'The response to the jury’s verdict was one of outrage.', 'n. 愤怒，愤慨；暴行；侮辱; v. 凌辱，强奸；对…施暴行；激起愤怒', '/\'autreidʒ | \'aʊtreɪdʒ | \'aʊtredʒ/', 'outrage', 5);
INSERT INTO `words` VALUES (26913, 'It was clear from the outset that there were going to be problems.', 'n. 开始；开端', '/\'autset | \'aʊtset | \'aʊtsɛt/', 'outset', 5);
INSERT INTO `words` VALUES (26914, 'When we got up, it was still dark outside.', 'adv. 向外面; n. 外部; adj. 外部的; prep. 在…外', '/,aut\'said, \'aut\'said | aʊt\'saɪd; \'aʊtsaɪd | ,aʊt\'saɪd/', 'outside', 5);
INSERT INTO `words` VALUES (26915, 'On the extreme northwestern outskirts of the city stands the Buddhist temple.', 'n. 市郊，郊区', '/\'autskə:ts | \'aʊtskɜːts | \'aʊt\'skɝts/', 'outskirts', 5);
INSERT INTO `words` VALUES (26916, 'The economy and outward appearance of the area have changed considerably.', 'adj. 向外的；外面的；公开的；外服的；肉体的; adv. 向外（等于outwards）；在外；显而易见地; n. 外表；外面；物质世界', '/\'autwəd | \'aʊtwəd | \'aʊtwɚd/', 'outward', 5);
INSERT INTO `words` VALUES (26917, '...the small oval framed picture of a little boy.', 'adj. 椭圆的；卵形的; n. 椭圆形；卵形', '/\'əuvəl | \'əʊv(ə)l | \'ovl/', 'oval', 5);
INSERT INTO `words` VALUES (26918, 'Preheat the oven to 200 degrees C.', 'n. 炉，灶；烤炉，烤箱', '/\'ʌvən | \'ʌv(ə)n | \'ʌvn/', 'oven', 5);
INSERT INTO `words` VALUES (26919, 'The overall cost of the exhibition was £400,000.', 'adj. 全面的， 综合的; n. 工作服； 工装裤', '/\'əʊvərɔːl | ,ovə\'rɔl/', 'overall', 5);
INSERT INTO `words` VALUES (26920, 'I sprang 400 pounds for her overcoat.', 'n. 大衣，外套', '/\'əuvəkəut | \'əʊvəkəʊt | \'ovɚkot/', 'overcoat', 5);
INSERT INTO `words` VALUES (26921, 'He struggled to overcome his shyness.', 'v. 克服；胜过', '/,əuvə\'kʌm | əʊvə\'kʌm | ,ovɚ\'kʌm/', 'overcome', 5);
INSERT INTO `words` VALUES (26922, 'The drains flooded and water overflowed down the main street.', 'v. 溢出；泛滥；充溢; n. 充满，洋溢；泛滥；超值；溢值', '/,əuvə\'fləu, \'əuvəfləu | əʊvə\'fləʊ | ,ovɚ\'flo/', 'overflow', 5);
INSERT INTO `words` VALUES (26923, 'The car needs a complete overhaul.', 'n. 彻底检修；改革A; vt. 彻底检修；赶上， 超过', '/əʊvə\'hɔːl | \'ovɚhɔl/', 'overhaul', 5);
INSERT INTO `words` VALUES (26924, 'Bullets whizzed overhead.', 'adv. 在头顶上， 在空中; adj. 在头顶上的； 架空的 A', '/\'əuvəhed | ,ovɚ\'hɛd/', 'overhead', 5);
INSERT INTO `words` VALUES (26925, 'I overheard part of their conversation.', 'v. 无意中听到；偷听', '/,əuvə\'hiə | əʊvə\'hɪə | ,ovɚ\'hɪr/', 'overhear', 5);
INSERT INTO `words` VALUES (26926, 'a large degree of overlap', 'n. 重叠；重复; v. 部分重叠；部分的同时发生', '/,əuvə\'læp, \'əuvəlæp | əʊvə\'læp | \'ovəlæp/', 'overlap', 5);
INSERT INTO `words` VALUES (26927, 'It is easy to overlook a small detail like that.', 'v. 忽略；俯瞰；远眺；检查；高耸于…之上; n. 忽视；眺望', '/,əuvə\'luk, \'əuvəluk | əʊvə\'lʊk | ,ovɚ\'lʊk/', 'overlook', 5);
INSERT INTO `words` VALUES (26928, 'He became a millionaire overnight.', 'adv. 通宵；突然；昨晚; adj. 晚上的；通宵的；前夜的; n. 头天晚上；一夜的逗留; vt. 连夜快递; vi. 过一夜', '/,əuvə\'nait, \'əuvənait | əʊvə\'naɪt | \'ovənaɪt/', 'overnight', 5);
INSERT INTO `words` VALUES (26929, 'An overpass is being put up at the corner of the street.', 'n. 过街天桥', '/\'əuvəpɑːs | \'ovɚpæs/', 'overpass', 5);
INSERT INTO `words` VALUES (26930, 'Chris is going to work overseas.', 'adv. 在海外，海外; adj. 海外的，国外的', '/\'əuvə\'si:z | əʊvə\'siːz | ,ovɚ\'siz/', 'overseas', 5);
INSERT INTO `words` VALUES (26931, 'He pulled out to overtake the van.', 'v. 赶上；压倒；突然来袭', '/,əuvə\'teik | əʊvə\'teɪk | ,ovɚ\'tek/', 'overtake', 5);
INSERT INTO `words` VALUES (26932, 'They were charged with plotting the overthrow of the state.', 'n. 推翻；倾覆；瓦解; v. 推翻；打倒；倾覆', '/,əuvə\'θrəu, \'əuvəθrəu | əʊvə\'θrəʊ | ,ovɚ\'θro/', 'overthrow', 5);
INSERT INTO `words` VALUES (26933, 'The firm wanted to chisel him out of his overtime pay.', 'adj. 超时的,加班的; adv. 加班', '/\'əuvətaim, ,əuvə\'taim | \'əʊvətaɪm | ,ovə\'taɪm/', 'overtime', 5);
INSERT INTO `words` VALUES (26934, 'Leslie jumped to her feet, overturning her chair.', 'v. 推翻；倾覆；破坏; n. 倾覆；周转；破灭', '/,əuvə\'tə:n, \'əuvətə:n | əʊvə\'tɜːn | \'ovətɝn/', 'overturn', 5);
INSERT INTO `words` VALUES (26935, 'It was clear that one massive Allied offensive would overwhelm the weakened enemy.', 'v. 淹没；压倒；受打击；覆盖；压垮', '/əʊvə\'welm | ,ovɚ\'wɛlm/', 'overwhelm', 5);
INSERT INTO `words` VALUES (26936, 'There is overwhelming evidence that smoking damages your health.', 'adj. 压倒性的；势不可挡的; v. 压倒；淹没（overwhelm的ing形式）；制服', '/,əuvə\'hwelmiŋ | ,ovɚ\'wɛlmɪŋ/', 'overwhelming', 5);
INSERT INTO `words` VALUES (26937, 'How much do I owe you (= often used to show that you want to pay for something )?', 'v. 欠；感激；应给予；应该把……归功于; n. (Owe)人名；(瑞典、挪)奥弗', '/əu | əʊ | o/', 'owe', 5);
INSERT INTO `words` VALUES (26938, 'You need to pay the amount owing, plus the interest.', 'adj. 未付的；欠着的; v. 欠；把…归功于（owe的ing形式）', '/\'əuiŋ | \'əʊɪŋ | \'oɪŋ/', 'owing', 5);
INSERT INTO `words` VALUES (26939, 'Rachael:Do you like our owl?', 'n. 猫头鹰；枭；惯于晚上活动的人', '/aul | aʊl/', 'owl', 5);
INSERT INTO `words` VALUES (26940, 'He was now the proud owner of a bright red sports car.', 'n. [经] 所有者；物主', '/\'əunə | \'əʊnə | \'onɚ/', 'owner', 5);
INSERT INTO `words` VALUES (26941, 'The price of home ownership is increasing.', 'n. 所有权；物主身份', '/\'əunəʃip | \'əʊnəʃɪp | \'onɚʃɪp/', 'ownership', 5);
INSERT INTO `words` VALUES (26942, NULL, 'n. 牛；公牛', '/ɔks | ɒks | ɑks/', 'ox', 5);
