INSERT INTO `words` VALUES (27044, 'salt and pepper', 'n. 胡椒；辣椒；胡椒粉; v. 加胡椒粉于；使布满', '/\'pepə | \'pɛpɚ/', 'pepper', 5);
INSERT INTO `words` VALUES (27045, 'The park attracts four million visitors per year.', 'prep. 每；经， 由', '/pɜː | pɚ/', 'per', 5);
INSERT INTO `words` VALUES (27046, 'That morning, he perceived a change in Franca’s mood.', 'v. 察觉,感知;理解,领悟', '/pə\'si:v | pə\'siːv | pɚ\'siv/', 'perceive', 5);
INSERT INTO `words` VALUES (27047, 'Interest rates fell by six percentage points (= 6% ) .', 'n. 百分比；百分率，百分数', '/pə\'sentidʒ | pə\'sentɪdʒ | pɚ\'sɛntɪdʒ/', 'percentage', 5);
INSERT INTO `words` VALUES (27048, 'His English was perfect.', 'adj. 完善的;完全的;(语法)完成的; v. 使完美', '/\'pə:fikt, pə\'fekt | ˈpəːfɪkt; (for v.) pəˈfekt | ˈpɝfɪkt; (for v.) pɝˈfɛkt/', 'perfect', 5);
INSERT INTO `words` VALUES (27049, 'My father expected perfection from all of us.', 'n. 尽善尽美,完美', '/pə\'fekʃən | pə\'fekʃ(ə)n | pɚ\'fɛkʃən/', 'perfection', 5);
INSERT INTO `words` VALUES (27050, 'Chenier and the band are performing at the Silver Palace tomorrow.', 'v. 履行,执行;表演,演出;完成(事业)', '/pə\'fɔ:m | pə\'fɔːm | pɚ\'fɔrm/', 'perform', 5);
INSERT INTO `words` VALUES (27051, 'This evening’s performance will begin at 8.00 pm.', 'n. 履行,执行;表演,演出;性能,特性;成绩', '/pə\'fɔːm(ə)ns | pɚ\'fɔrməns/', 'performance', 5);
INSERT INTO `words` VALUES (27052, 'She was wearing the perfume that he’d bought her.', 'n. 香水；香味; v. 洒香水于…；使…带香味', '/pə\'fju:m | \'pɜːfjuːm | pɚ\'fjum/', 'perfume', 5);
INSERT INTO `words` VALUES (27053, 'Tomorrow’s weather will be dry with sunny periods.', 'n. 周期，期间；时期；月经；课时；（语法学）句点，句号; adj. 某一时代的', '/\'pɪərɪəd | \'pɪrɪəd/', 'period', 5);
INSERT INTO `words` VALUES (27054, 'She made periodical visits to her dentist.', 'adj. [数] 周期的；定期的; n. 期刊；杂志', '/,piəri\'ɔdikəl | pɪərɪ\'ɒdɪk(ə)l | ,pɪrɪ\'ɑdɪkl/', 'periodical', 5);
INSERT INTO `words` VALUES (27055, 'Hundreds perished when the ship went down.', 'v. 使麻木；毁坏', '/\'periʃ | \'perɪʃ | \'pɛrɪʃ/', 'perish', 5);
INSERT INTO `words` VALUES (27056, 'He gave up a permanent job in order to freelance.', 'adj. 永久的,持久的', '/\'pɜːm(ə)nənt | \'pɝmənənt/', 'permanent', 5);
INSERT INTO `words` VALUES (27057, 'The smell of diesel oil permeated the air.', 'v. 渗透，透过；弥漫', '/\'pə:mieit | \'pɜːmɪeɪt | \'pɝmɪet/', 'permeate', 5);
INSERT INTO `words` VALUES (27058, 'He asked permission to leave the room.', 'n. 允许，许可', '/pə\'miʃən | pə\'mɪʃ(ə)n | pɚ\'mɪʃən/', 'permission', 5);
INSERT INTO `words` VALUES (27059, 'Smoking is only permitted in the public lounge.', 'v. 许可；允许; n. 许可证，执照', '/pə\'mit | pə\'mɪt | pɚ\'mɪt/', 'permit', 5);
INSERT INTO `words` VALUES (27060, 'the perpetual snows of the mountaintops', 'adj. 永久的,永恒的,长期的', '/pə\'petʃuəl, -tju- | pə\'petʃʊəl; -tjʊəl | pɚ\'pɛtʃuəl/', 'perpetual', 5);
INSERT INTO `words` VALUES (27061, 'Shea’s symptoms perplexed the doctors.', 'v. 使困惑，使为难；使复杂化', '/pə\'pleks | pɚ\'plɛks/', 'perplex', 5);
INSERT INTO `words` VALUES (27062, 'The Puritans left England to escape being persecuted.', 'v. 迫害', '/\'pə:sikju:t | \'pɜːsɪkjuːt | \'pɝsɪkjut/', 'persecute', 5);
INSERT INTO `words` VALUES (27063, 'It can be tricky at first, but persevere.', 'v. 坚持；不屈不挠；固执己见（在辩论中）', '/,pə:si\'viə | pɜːsɪ\'vɪə | ,pɝsə\'vɪr/', 'persevere', 5);
INSERT INTO `words` VALUES (27064, '‘I don’t think it’s right,’ John persisted.', 'v. (in)坚持,持续', '/pə\'sist, -\'zist | pə\'sɪst | pɚ\'sɪst/', 'persist', 5);
INSERT INTO `words` VALUES (27065, 'My personal view is that we shouldn’t offer him the job.', 'adj. 个人的；身体的；亲自的; n. 人事消息栏；人称代名词', '/\'pə:sənl | \'pɜːs(ə)n(ə)l | \'pɝsənl/', 'personal', 5);
INSERT INTO `words` VALUES (27066, 'Despite their different personalities, they became the best of friends.', 'n. 个性；品格；名人', '/,pə:sə\'næləti | pɜːsə\'nælɪtɪ | ,pɝsə\'næləti/', 'personality', 5);
INSERT INTO `words` VALUES (27067, 'A copy should then be sent to Personnel for our files.', 'n. 人事部门；全体人员; adj. 人员的；有关人事的', '/,pə:sə\'nel | pɜːsə\'nel | ,pɝsə\'nɛl/', 'personnel', 5);
INSERT INTO `words` VALUES (27068, 'the artist’s use of perspective', 'n. 透视画法,透视图;远景,前途;观点,看法', '/pə\'spektiv | pə\'spektɪv | pɚ\'spɛktɪv/', 'perspective', 5);
INSERT INTO `words` VALUES (27069, 'He was fairly easily persuaded .', 'v. 说服，劝说；使某人相信；劝某人做（不做）某事; adj. 空闲的，有闲的', '/pə\'sweid | pə\'sweɪd | pɚ\'swed/', 'persuade', 5);
INSERT INTO `words` VALUES (27070, 'After a little gentle persuasion , Debbie agreed to let us in.', 'n. 说服；说服力；信念；派别', '/pə\'sweiʒən | pə\'sweɪʒ(ə)n | pɚ\'sweʒn/', 'persuasion', 5);
INSERT INTO `words` VALUES (27071, 'a pessimistic view of life', 'adj. 悲观(主义)的', '/,pesi\'mistik | ,pesɪ\'mɪstɪk | ,pɛsɪ\'mɪstɪk/', 'pessimistic', 5);
INSERT INTO `words` VALUES (27072, 'a chemical used in pest control', 'n. 害虫；有害之物；讨厌的人', '/pest | pɛst/', 'pest', 5);
INSERT INTO `words` VALUES (27073, 'They have two pets – a cat and a dog.', 'n. 爱畜,宠儿; adj. 宠爱的,表示亲昵的', '/pet | pɛt/', 'pet', 5);
INSERT INTO `words` VALUES (27074, 'Local residents have drawn up a petition to protest the hospital closure.', 'n. 请愿书,申请书; v. (向…)请愿,正式请求', '/pi\'tiʃən | pɪ\'tɪʃ(ə)n | pə\'tɪʃən/', 'petition', 5);
INSERT INTO `words` VALUES (27075, 'unleaded petrol', 'n. （英）汽油', '/\'petrəl | \'petr(ə)l | \'pɛtrəl/', 'petrol', 5);
INSERT INTO `words` VALUES (27076, 'petroleum-based products', 'n. 石油', '/pi\'trəuliəm, pə- | pə\'trəʊlɪəm | pə\'trolɪəm/', 'petroleum', 5);
INSERT INTO `words` VALUES (27077, 'petty squabbles', 'adj. 小(器、规模)的,不重要的,细微的,卑鄙的', '/\'peti | \'petɪ | \'pɛti/', 'petty', 5);
INSERT INTO `words` VALUES (27078, 'an all-night pharmacy', 'n. 药房；配药学，药剂学；制药业；一批备用药品', '/\'fɑ:məsi | \'fɑːməsɪ | \'fɑrməsi/', 'pharmacy', 5);
INSERT INTO `words` VALUES (27079, 'We should phase the input and output of the machine.', 'n. 月相', '/feɪz | fez/', 'phase', 5);
INSERT INTO `words` VALUES (27080, 'Homelessness is not a new phenomenon .', 'n. 现象；奇迹；杰出的人才', '/fi\'nɔminən, fə- | fɪ\'nɒmɪnən | fə\'nɑmɪnən/', 'phenomenon', 5);
INSERT INTO `words` VALUES (27081, 'Plato, Aristotle, and other Greek philosophers', 'n. 哲学家；哲人', '/fi\'lɔsəfə, fə- | fɪ\'lɒsəfə | fə\'lɑsəfɚ/', 'philosopher', 5);
INSERT INTO `words` VALUES (27082, 'Emma studies philosophy at university.', 'n. 哲学；哲理；人生观', '/fi\'lɔsəfi, fə- | fɪ\'lɒsəfɪ | fə\'lɑsəfi/', 'philosophy', 5);
INSERT INTO `words` VALUES (27083, 'Much of his work is done by phone .', 'n. 电话；耳机，听筒; v. 打电话', '/fəun | fəʊn | fon/', 'phone', 5);
INSERT INTO `words` VALUES (27084, 'Can you take a photo of me and Rachel?', 'n. 照片', '/\'fəutəu | \'fəʊtəʊ | \'foto/', 'photo', 5);
INSERT INTO `words` VALUES (27085, 'Who first used the phrase ‘survival of the fittest’?', 'n. 短语, 习语, 措辞, 乐句; v. 措词, 将(乐曲)分成乐句', '/freiz | freɪz | frez/', 'phrase', 5);
INSERT INTO `words` VALUES (27086, 'She was in constant physical pain.', 'adj. [物] 物理的；身体的；物质的；根据自然规律的，符合自然法则的; n. 体格检查', '/\'fɪzɪk(ə)l | \'fɪzɪkl/', 'physical', 5);
INSERT INTO `words` VALUES (27087, '...your family physician.', 'n. [医] 医师；内科医师', '/fi\'ziʃən | fɪ\'zɪʃ(ə)n | fɪ\'zɪʃən/', 'physician', 5);
INSERT INTO `words` VALUES (27088, '...a nuclear physicist.', 'n. 物理学家；唯物论者', '/\'fizisist | \'fɪzɪsɪst/', 'physicist', 5);
INSERT INTO `words` VALUES (27089, 'If so, this would add to a growing list of physiological and biological markers of sexual orientation.', 'adj. 生理学的, 生理学上的', '/,fiziə\'lɔdʒikəl | ,fɪzɪə\'lɒdʒɪkəl | ,fɪzɪə\'lɑdʒɪkl/', 'physiological', 5);
INSERT INTO `words` VALUES (27090, 'a book on biochemistry and physiology', 'n. 生理学', '/ˌfɪzi\'ɒlədʒi | \'fɪzɪ\'ɑlədʒi/', 'physiology', 5);
INSERT INTO `words` VALUES (27091, NULL, 'n. 收集，整理；小卡车；拾起；搭车者；偶然结识者', '/\'pikʌp | \'pɪkʌp/', 'pickup', 5);
INSERT INTO `words` VALUES (27092, 'We decided to have a picnic down by the lake.', 'n. 野餐; v. 去野餐', '/\'piknik | \'pɪknɪk/', 'picnic', 5);
INSERT INTO `words` VALUES (27093, 'The room had several pictures on the walls.', 'n. 照片，图画；影片；景色；化身; v. 画；想像；描写', '/\'piktʃə | \'pɪktʃə | \'pɪktʃɚ/', 'picture', 5);
INSERT INTO `words` VALUES (27094, 'I had a steak and kidney pie with chips.', 'n. 馅饼；饼图；爱说话的人; vt. 使杂乱', '/pai | paɪ/', 'pie', 5);
INSERT INTO `words` VALUES (27095, 'Cut off a piece of wood 5 cm in length.', 'n. 块；件；篇；硬币; v. 修补；接合；凑合', '/pi:s | piːs | pis/', 'piece', 5);
INSERT INTO `words` VALUES (27096, 'Steam the corn until it can easily be pierced with a fork.', 'v. 刺穿；洞察；响彻；深深地打动', '/piəs | pɪəs | pɪrs/', 'pierce', 5);
INSERT INTO `words` VALUES (27097, 'He kept pigs and poultry.', 'n. 猪；猪肉; v. 生小猪；像猪一样过活', '/pɪg | pɪɡ/', 'pig', 5);
INSERT INTO `words` VALUES (27098, 'Many journalists here choose to pigeon all but the most innocuous of stories.', 'n. 鸽子', '/\'pidʒin | \'pɪdʒɪn; \'pɪdʒ(ə)n | \'pɪdʒɪn/', 'pigeon', 5);
INSERT INTO `words` VALUES (27099, 'He balanced the plate on the top of a pile of books.', 'n. 堆；大量；建筑群; v. 累积；打桩于', '/pail | paɪl/', 'pile', 5);
INSERT INTO `words` VALUES (27100, 'pilgrims visiting a holy shrine', 'n. 朝圣者；漫游者；（美）最初的移民; vi. 去朝圣；漫游', '/\'pilɡrim | \'pɪlgrɪm | \'pɪlɡrɪm/', 'pilgrim', 5);
INSERT INTO `words` VALUES (27101, 'He has to take pills to control his blood pressure.', 'n. 药丸；弹丸，子弹；口服避孕药; v. 把…制成丸剂；使服用药丸；抢劫，掠夺（古语）', '/pil | pɪl/', 'pill', 5);
INSERT INTO `words` VALUES (27102, 'Mr Fitzwilliam had been seen as a pillar of the community.', 'n. 柱子，柱形物；栋梁；墩; vt. 用柱支持', '/\'pilə | \'pɪlə | \'pɪlɚ/', 'pillar', 5);
INSERT INTO `words` VALUES (27103, 'I’ll be asleep as soon as my head hits the pillow.', 'n. 枕头', '/\'piləu | \'pɪləʊ | \'pɪlo/', 'pillow', 5);
INSERT INTO `words` VALUES (27104, 'an airline pilot', 'n. 飞行员；领航员; adj. 试点的; v. 驾驶；领航；试用', '/\'pailət | \'paɪlət/', 'pilot', 5);
INSERT INTO `words` VALUES (27105, 'We have to stop her pinching her baby brother.', 'v. 捏；勒索；使苦恼；掐掉某物，修剪; n. 匮乏；少量；夹痛', '/pintʃ | pɪn(t)ʃ | pɪntʃ/', 'pinch', 5);
INSERT INTO `words` VALUES (27106, 'I pine for the countryside.', 'v. 渴望，痛苦；憔悴; n. [林] 松树；凤梨，菠萝; adj. 松木的；似松的', '/pain | paɪn/', 'pine', 5);
INSERT INTO `words` VALUES (27107, 'Her room was decorated in bright pinks and purples.', 'n. 粉红色；化身，典范；石竹花；头面人物; v. 扎，刺，戳；使…变粉红色；使…面红耳赤; adj. 粉红的；比较激进的；石竹科的；脸色发红的', '/piŋk | pɪŋk/', 'pink', 5);
INSERT INTO `words` VALUES (27108, 'He’s gone down the pub for a quick pint.', 'n. 品脱；一品脱的量；一品脱牛奶或啤酒', '/paint | paɪnt/', 'pint', 5);
INSERT INTO `words` VALUES (27109, 'the early pioneers of the Dakota territory', 'n. 先锋；拓荒者; v. 开辟；倡导；提倡', '/,paiə\'niə | paɪə\'nɪə | ,paɪə\'nɪr/', 'pioneer', 5);
INSERT INTO `words` VALUES (27110, 'a water pipe', 'n. 管；烟斗；笛; v. 吹笛；尖叫', '/paip | paɪp/', 'pipe', 5);
INSERT INTO `words` VALUES (27111, 'Computer game pirates cost the industry twenty million pounds a year.', 'n. 海盗；盗版；侵犯专利权者; v. 掠夺；翻印；剽窃', '/\'paɪrɪt | ˈpaɪərət | \'paɪrət/', 'pirate', 5);
INSERT INTO `words` VALUES (27112, 'He threatened to pistol me.', 'n. 手枪；信号枪; vt. 用手枪射击', '/\'pistl | \'pɪst(ə)l | \'pɪstl/', 'pistol', 5);
INSERT INTO `words` VALUES (27113, 'Filling the cylinder with steam pushes the piston out.', 'n. 活塞', '/\'pistən | \'pɪst(ə)n | \'pɪstən/', 'piston', 5);
INSERT INTO `words` VALUES (27114, 'Dad first went down the pit (= worked in a coal mine ) when he was 15 years old.', 'n. 矿井；深坑；陷阱；（物体或人体表面上的）凹陷；（英国剧场的）正厅后排；正厅后排的观众; v. 使竞争；窖藏；使凹下；去…之核；使留疤痕', '/pit | pɪt/', 'pit', 5);
INSERT INTO `words` VALUES (27115, 'Try and pitch your tent on level ground.', 'v. 倾斜；投掷；搭帐篷；坠落; n. 沥青；音高；程度；树脂；倾斜；投掷；球场', '/pɪtʃ/', 'pitch', 5);
INSERT INTO `words` VALUES (27116, 'It’s a great pity Joyce wasn’t invited.', 'n. 怜悯，同情；遗憾; v. 对……表示怜悯；对……感到同情', '/\'piti | \'pɪtɪ | \'pɪti/', 'pity', 5);
INSERT INTO `words` VALUES (27117, 'drops in population levels due to plagues and famines', 'n. 瘟疫；灾祸；麻烦；讨厌的人; v. 折磨；使苦恼；使得灾祸', '/pleiɡ | pleɪg | pleɡ/', 'plague', 5);
INSERT INTO `words` VALUES (27118, 'The document, written in plain English, tells you about your new policy.', 'adj. 平的；简单的；朴素的；清晰的; n. 平原；无格式；朴实无华的东西; adv. 清楚地；平易地', '/plein | pleɪn | plen/', 'plain', 5);
INSERT INTO `words` VALUES (27119, 'The lead plaintiff of the lawsuit is the University of California.', 'n. 原告', '/\'pleɪntɪf | \'plentɪf/', 'plaintiff', 5);
INSERT INTO `words` VALUES (27120, 'It is a big airline with a large fleet of planes.', 'n. 飞机；平面；程度，水平; v. 刨；乘飞机旅行；翱翔; adj. 平的；平面的', '/plein | pleɪn | plen/', 'plane', 5);
INSERT INTO `words` VALUES (27121, 'The picture shows six of the nine planets in the solar system.', 'n. 行星', '/\'plænit | \'plænɪt/', 'planet', 5);
INSERT INTO `words` VALUES (27122, 'Don’t forget to water the plants.', 'n. 工厂，车间；植物；设备；庄稼; v. 种植；培养；栽培；安置', '/plɑ:nt, plænt | plɑːnt | plænt/', 'plant', 5);
INSERT INTO `words` VALUES (27123, 'a rubber plantation', 'n. 栽植；殖民；大农场; adj. 适用于种植园或热带、亚热带国家的', '/plæn\'teiʃən | plæn\'teɪʃ(ə)n; plɑːn- | plæn\'teʃən/', 'plantation', 5);
INSERT INTO `words` VALUES (27124, 'She gets sunburned even when she plasters herself from head to toe in factor 7 sun lotion.', 'n. 石膏；灰泥；膏药; v. 减轻；粘贴；涂以灰泥；敷以膏药；使平服', '/\'plɑ:stə, \'plæs- | \'plɑːstə | \'plæstɚ/', 'plaster', 5);
INSERT INTO `words` VALUES (27125, 'a plastic spoon', 'adj. 塑料的， 塑胶的；可塑的， 塑性的; n. 塑料； 塑料制品 <', '/\'plæstɪk/', 'plastic', 5);
INSERT INTO `words` VALUES (27126, 'The brass plate on the door said ‘Dr Rackman’.', 'n. 碟；金属板；金属牌；感光底片; v. 电镀；给…装甲', '/pleit | pleɪt/', 'plate', 5);
INSERT INTO `words` VALUES (27127, 'A broad valley opened up leading to a high, flat plateau of cultivated land.', 'n. 高原; adj. 高原印第安人的', '/\'plætəʊ | plæ\'to/', 'plateau', 5);
INSERT INTO `words` VALUES (27128, 'The Edinburgh train will depart from platform six.', 'n. 平台,台;站台,月台;政纲,党纲', '/\'plætfɔ:m | \'plætfɔːm | \'plæt\'fɔrm/', 'platform', 5);
INSERT INTO `words` VALUES (27129, 'His story certainly sounds plausible.', 'adj. 貌似可信的，花言巧语的；貌似真实的，貌似有理的', '/\'plɔ:zəble | \'plɔːzɪb(ə)l | \'plɔzəbl/', 'plausible', 5);
INSERT INTO `words` VALUES (27130, 'children shouting and running in the playground', 'n. 运动场，操场；游乐场', '/\'pleɪgraʊnd | \'ple\'graʊnd/', 'playground', 5);
INSERT INTO `words` VALUES (27131, 'Caldwell made a plea for donations.', 'n. 恳求，请求；辩解，辩护；借口，托辞', '/pli: | pliː | pli/', 'plea', 5);
INSERT INTO `words` VALUES (27132, 'She stayed home from work, pleading illness.', 'v. 借口；为辩护；托称', '/pli:d | pliːd | plid/', 'plead', 5);
INSERT INTO `words` VALUES (27133, 'It had been a pleasant evening.', 'adj. 令人愉快的，舒适的；讨人喜欢的，和蔼可亲的; n. (Pleasant)人名；(英)普莱曾特', '/\'plezənt | \'plez(ə)nt | \'plɛznt/', 'pleasant', 5);
INSERT INTO `words` VALUES (27134, 'the simple pleasures of life', 'n. 快乐；希望；娱乐；令人高兴的事; vt. 使高兴；使满意; vi. 高兴；寻欢作乐', '/\'pleʒə, \'plei- | \'pleʒə | ˈplɛʒɚ/', 'pleasure', 5);
INSERT INTO `words` VALUES (27135, 'The meeting ended with a pledge to step up cooperation between the six states of the region.', 'n. 保证，誓言；抵押；抵押品，典当物; v. 保证，许诺；用……抵押；举杯祝……健康', '/pledʒ | plɛdʒ/', 'pledge', 5);
INSERT INTO `words` VALUES (27136, 'a plentiful supply of food', 'adj. 丰富的；许多的；丰饶的；众多的', '/\'plentɪfʊl; -f(ə)l | \'plɛntɪfəl/', 'plentiful', 5);
INSERT INTO `words` VALUES (27137, 'a land of plenty', 'n. 丰富，大量；充足; adj. 足够的，很多的; adv. 足够', '/\'plenti | \'plentɪ | \'plɛnti/', 'plenty', 5);
INSERT INTO `words` VALUES (27138, 'the country’s economic plight', 'n. 困境；境况；誓约; v. 保证；约定', '/plait | plaɪt/', 'plight', 5);
INSERT INTO `words` VALUES (27139, 'The court heard how she and her lover hatched a plot (= planned a plot ) to kill her husband.', 'n. 情节；图；阴谋; v. 密谋；绘图；划分；标绘', '/plɔt | plɒt | plɑt/', 'plot', 5);
