INSERT INTO `words` VALUES (27141, 'the bath plug', 'n. 插头；塞子；栓; v. 塞住；用插头将与电源接通', '/plʌɡ | plʌg/', 'plug', 5);
INSERT INTO `words` VALUES (27142, 'Even without a high-school diploma, a black man can probably find a job if he looks. And some manual jobs, such as plumber or cable technician, pay quite well.', 'n. 水管工；堵漏人员', '/\'plʌmə | \'plʌmɚ/', 'plumber', 5);
INSERT INTO `words` VALUES (27143, '...a plunge into cold water.', 'n. 投入；跳进; v. 突然地下降；投入；陷入；跳进', '/plʌn(d)ʒ | plʌndʒ/', 'plunge', 5);
INSERT INTO `words` VALUES (27144, '\"Data\" is the Latin plural form of \"datum.\"', 'adj. 复数的; n. 复数', '/\'pluərəl | \'plʊər(ə)l | \'plʊrəl/', 'plural', 5);
INSERT INTO `words` VALUES (27145, 'Another of the Beach Club’s plus points is that it’s right in the middle of town.', 'adj. 正的， 加的; prep. 加上; n. 加号， 正号', '/plʌs/', 'plus', 5);
INSERT INTO `words` VALUES (27146, 'She was taken to hospital, suffering from pneumonia.', 'n. 肺炎', '/nju:\'məunjə | njuː\'məʊnɪə | nʊ\'monɪə/', 'pneumonia', 5);
INSERT INTO `words` VALUES (27147, 'Luke came in with his hands in his pockets.', 'n. 口袋；钱；容器; v. 隐藏；忍受；将…放入衣袋; adj. 小型的，袖珍的；金钱上的', '/\'pɔkit | \'pɒkɪt | \'pɑkɪt/', 'pocket', 5);
INSERT INTO `words` VALUES (27148, '...a book of love poems.', 'n. 诗', '/\'pəuim | \'pəʊɪm | \'poəm/', 'poem', 5);
INSERT INTO `words` VALUES (27149, 'He reads a lot of poetry.', 'n. 诗；诗意，诗情；诗歌艺术', '/\'pəuitri | \'pəʊɪtrɪ | \'poətri/', 'poetry', 5);
INSERT INTO `words` VALUES (27150, 'She was accused in 1974 of poisoning her second husband, Charles.', 'v. 污染；使中毒，放毒于；败坏；阻碍; n. 毒药，毒物；酒；有毒害的事物；[助剂] 抑制剂; adj. 有毒的', '/\'pɔizən | \'pɒɪz(ə)n | \'pɔɪzn/', 'poison', 5);
INSERT INTO `words` VALUES (27151, 'Some mushrooms are extremely poisonous.', 'adj. 有毒的；恶毒的；讨厌的', '/\'pɔizənəs | \'pɒɪzənəs | \'pɔɪzənəs/', 'poisonous', 5);
INSERT INTO `words` VALUES (27152, 'One of the nurses poked her head around the door.', 'v. 刺，捅；戳；伸出；刺探；闲荡; n. 戳；刺；袋子；懒汉', '/pəuk | pəʊk | pok/', 'poke', 5);
INSERT INTO `words` VALUES (27153, 'As our climate warms up, the polar ice caps will begin to melt.', 'adj. 极地的；两极的；正好相反的; n. 极面；极线', '/\'pəulə | \'pəʊlə | \'polɚ/', 'polar', 5);
INSERT INTO `words` VALUES (27154, 'a telephone pole', 'n. 杆；极点；电极; v. 用竿支撑', '/pəul | pəʊl | pol/', 'pole', 5);
INSERT INTO `words` VALUES (27155, 'Police surrounded the courthouse.', 'n. 警察,警察机关; adj. 警察的; v. 管辖', '/pə\'li:s | pə\'liːs | pə\'lis/', 'police', 5);
INSERT INTO `words` VALUES (27156, 'He tried to corrupt the policeman with money.', 'n. 警察', '/pə\'li:smən | pə\'liːsmən | pə\'lismən/', 'policeman', 5);
INSERT INTO `words` VALUES (27157, '...plans that include changes in foreign policy and economic reforms.', 'n. 政策,方针', '/\'pɔlisi | \'pɒləsɪ | \'pɑləsi/', 'policy', 5);
INSERT INTO `words` VALUES (27158, 'An occasional polish will keep wall tiles looking good.', 'n. 磨光，擦亮；擦亮剂；优雅，精良; v. 擦亮，变光滑; adj. 波兰的', '/\'pɒlɪʃ | \'pɑlɪʃ/', 'polish', 5);
INSERT INTO `words` VALUES (27159, 'She’s always very polite.', 'adj. 有礼貌的,客气的;有教养的,文雅的', '/pə\'lait | pə\'laɪt/', 'polite', 5);
INSERT INTO `words` VALUES (27160, 'All other political parties there have been completely banned.', 'adj. 政治的', '/pə\'litikəl | pə\'lɪtɪk(ə)l | pə\'lɪtɪkl/', 'political', 5);
INSERT INTO `words` VALUES (27161, 'politicians who are trying to get the minority vote', 'n. 政治家,政客', '/,pɔli\'tiʃən | pɒlɪ\'tɪʃ(ə)n | ,pɑlə\'tɪʃən/', 'politician', 5);
INSERT INTO `words` VALUES (27162, 'a good understanding of politics in China', 'n. 政治,政治学;政纲,政见', '/\'pɔlitiks | \'pɒlɪtɪks | \'pɑlətɪks/', 'politics', 5);
INSERT INTO `words` VALUES (27163, 'A recent poll found that 80% of Californians support the governor.', 'n. 民意测验;(pl.)政治选举; v. 获得…选票', '/pəul | pəʊl | pol/', 'poll', 5);
INSERT INTO `words` VALUES (27164, 'beaches polluted by raw sewage', 'v. 污染；玷污；败坏', '/pə\'lut | pə\'luːt/', 'pollute', 5);
INSERT INTO `words` VALUES (27165, 'California’s tough anti-pollution laws', 'n. 污染', '/pə:\'lju:ʃən | pə\'luːʃ(ə)n | pə\'luʃən/', 'pollution', 5);
INSERT INTO `words` VALUES (27166, 'The path descends to the pond.', 'vt. 筑成池塘; vi. 筑成池塘; n. 池塘', '/pɔnd | pɒnd | pɑnd/', 'pond', 5);
INSERT INTO `words` VALUES (27167, 'He continued to ponder the problem as he walked home.', 'v. 仔细考虑；衡量; n. (Ponder)人名；(英)庞德', '/\'pɔndə | \'pɒndə | \'pɑndɚ/', 'ponder', 5);
INSERT INTO `words` VALUES (27168, 'pools of water with tiny fish in them', 'n. 联营；撞球；水塘；共同资金; v. 联营，合伙经营', '/pu:l | puːl | pul/', 'pool', 5);
INSERT INTO `words` VALUES (27169, 'All at once an idea popped into her head.', 'abbr. 卖点广告（Point of Purchase）', '/pɒp | pɑp/', 'pop', 5);
INSERT INTO `words` VALUES (27170, 'The highlight of the pope\'s visit will be his message to the people.', 'n. 教皇，罗马教皇；权威，大师', '/pəup | pəʊp | pop/', 'pope', 5);
INSERT INTO `words` VALUES (27171, 'Hilary was popular at school.', 'adj. 流行的，通俗的；受欢迎的；大众的；普及的', '/\'pɔpjulə | \'pɒpjʊlə | \'pɑpjəlɚ/', 'popular', 5);
INSERT INTO `words` VALUES (27172, 'Nearly 70 percent of the population still live in the countryside.', 'n. 人口；[生物] 种群，[生物] 群体；全体居民', '/,pɔpju\'leiʃən | pɒpjʊ\'leɪʃ(ə)n | ,pɑpju\'leʃən/', 'population', 5);
