INSERT INTO `words` VALUES (27174, 'He was standing on the porch, waving as we drove away.', 'n. 门廊；走廊', '/pɔ:tʃ | pɔːtʃ | pɔrtʃ/', 'porch', 5);
INSERT INTO `words` VALUES (27175, 'pork chops', 'n. 猪肉; vt. 与女子性交', '/pɔ:k | pɔːk | pɔrk/', 'pork', 5);
INSERT INTO `words` VALUES (27176, 'Britain’s largest port', 'n. 港口', '/pɔ:t, pəut | pɔːt | pɔrt/', 'port', 5);
INSERT INTO `words` VALUES (27177, 'a portable radio', 'adj. 轻便的,手提(式)的,可移动的', '/\'pɔ:təbl, \'pəu- | \'pɔːtəb(ə)l | \'pɔrtəbl/', 'portable', 5);
INSERT INTO `words` VALUES (27178, 'Our taxi pulled up at Old Delhi station and a porter sprinted to the door.', 'n. 守门人,门房,行李搬运工,服务员', '/\'pɔ:tə, \'pəu- | \'pɔːtə | \'pɔrtɚ/', 'porter', 5);
INSERT INTO `words` VALUES (27179, 'You’ll need to prepare a portfolio of your work.', 'n. 公文包；文件夹； 作品集；投资组合', '/pɔːt\'fəuliəu | pɔrt\'folɪo/', 'portfolio', 5);
INSERT INTO `words` VALUES (27180, 'Do you have any children’s portions?', 'n. 一部分,一份', '/\'pɔ:ʃən, \'pəu- | \'pɔːʃ(ə)n | \'pɔrʃən/', 'portion', 5);
INSERT INTO `words` VALUES (27181, 'a family portrait', 'n. 肖像,画像', '/\'pɔ:trit, -treit, \'pəu- | \'pɔːtrɪt | \'pɔrtrɪt/', 'portrait', 5);
INSERT INTO `words` VALUES (27182, 'Romantic artists portrayed nature as wild and powerful.', 'v. 描写，描述；画(人物、景象等)', '/pɔ:\'trei, pəu- | pɔː\'treɪ | pɔr\'tre/', 'portray', 5);
INSERT INTO `words` VALUES (27183, 'Ann struck a pose (= stood or sat in a particular position ) and smiled for the camera.', 'n. 姿势,姿态; v. 造成,提出,摆姿势,佯装', '/pəʊz | poz/', 'pose', 5);
INSERT INTO `words` VALUES (27184, 'Lie in a comfortable position .', 'n. 位置;职位;姿势,姿态;见解,立场,形势', '/pə\'ziʃən | pə\'zɪʃ(ə)n | pə\'zɪʃən/', 'position', 5);
INSERT INTO `words` VALUES (27185, 'At least something positive has come out of the situation.', 'adj. 肯定的,积极的,绝对的,无疑的,正的', '/\'pɔzətiv, -zi- | \'pɒzɪtɪv | \'pɑzətɪv/', 'positive', 5);
INSERT INTO `words` VALUES (27186, 'Different workers possess different skills.', 'v. 占有,拥有', '/pə\'zes | pə\'zɛs/', 'possess', 5);
INSERT INTO `words` VALUES (27187, 'That information is not in our possession.', 'n. 持有,拥有;所有权;所有物;(pl.)财产,财富', '/pə\'zeʃən | pə\'zeʃ(ə)n | pə\'zɛʃən/', 'possession', 5);
INSERT INTO `words` VALUES (27188, 'There’s always a possibility that he might go back to Seattle.', 'n. 可能,可能性;可能的事,希望', '/,pɔsə\'biləti | ,pɒsɪ\'bɪlɪtɪ | ,pɑsə\'bɪləti/', 'possibility', 5);
INSERT INTO `words` VALUES (27189, 'Is it possible toget tickets for the game?', 'adj. 可能的,做得到的;合理的;可允许的', '/\'pɔsəbl | \'pɒsɪb(ə)l | \'pɑsəbl/', 'possible', 5);
INSERT INTO `words` VALUES (27190, 'This last task is possibly the most difficult.', 'adv. 可能地，也许；无论如何', '/\'pɔsəbli | \'pɒsɪblɪ | \'pɑsəbli/', 'possibly', 5);
INSERT INTO `words` VALUES (27191, 'How much is the postage for a postcard?', 'n. 邮资，邮费', '/\'pəustidʒ | \'pəʊstɪdʒ | \'postɪdʒ/', 'postage', 5);
INSERT INTO `words` VALUES (27192, 'Don’t forget to send us a postcard!', 'n. 明信片', '/\'pəustka:d | \'pəʊs(t)kɑːd | \'post\'kɑrd/', 'postcard', 5);
INSERT INTO `words` VALUES (27193, 'A team of volunteers were putting up posters .', 'n. 海报，广告；招贴', '/\'pəustə | \'pəʊstə | \'postɚ/', 'poster', 5);
INSERT INTO `words` VALUES (27194, 'That postman is in charge of this route.', 'n. 邮递员', '/\'pəustmən | \'pəʊs(t)mən | \'postmən/', 'postman', 5);
INSERT INTO `words` VALUES (27195, 'The match had to be postponed until next week.', 'v. 使…延期；把…放在次要地位；把…放在后面', '/pəust\'pəun, pə\'sp- | pəʊs(t)\'pəʊn; pə\'spəʊn | po\'spon/', 'postpone', 5);
INSERT INTO `words` VALUES (27196, 'her upright posture', 'n. 姿势；态度；情形; v. 摆姿势', '/\'pɔstʃə | \'pɒstʃə | \'pɑstʃɚ/', 'posture', 5);
INSERT INTO `words` VALUES (27197, 'herbs growing in pots', 'n. 壶；盆；罐; v. 把…装罐；射击；节略', '/pɔt | pɒt | pɑt/', 'pot', 5);
INSERT INTO `words` VALUES (27198, 'Marie stood at the sink, peeling potatoes (= cutting off the skin ) .', 'n. [作物] 土豆，[作物] 马铃薯', '/pə\'teitəu | pə\'teɪtəʊ | pə\'teto/', 'potato', 5);
INSERT INTO `words` VALUES (27199, 'The boy has great potential.', 'n. 潜能；可能性；[电] 电势; adj. 潜在的；可能的；势的', '/pəu\'tenʃəl | pəˈtenʃl | pə\'tɛnʃl/', 'potential', 5);
INSERT INTO `words` VALUES (27200, '...a poultry farm.', 'n. 家禽', '/\'pəultri | \'pəʊltrɪ | \'poltri/', 'poultry', 5);
INSERT INTO `words` VALUES (27201, 'They spent over a thousand pounds.', 'n. 英镑；重击，重击声；兽栏；拘留所; v. 捣烂；敲打；监禁，拘留', '/paund | paʊnd/', 'pound', 5);
INSERT INTO `words` VALUES (27202, 'She poured coffee for everyone.', 'n. 倾泻；流出；骤雨; v. 灌，注；倒；倾泻；倾吐', '/pɔ: | pɔː | pɔr/', 'pour', 5);
INSERT INTO `words` VALUES (27203, 'Millions of elderly people live in poverty .', 'n. 贫困；困难；缺少；低劣', '/\'pɔvəti | \'pɒvətɪ | \'pɑvɚti/', 'poverty', 5);
INSERT INTO `words` VALUES (27204, 'curry powder', 'n. 粉；粉末；[化工][军] 火药；尘土; v. 使成粉末；撒粉；搽粉于', '/\'paudə | \'paʊdə | \'paʊdɚ/', 'powder', 5);
INSERT INTO `words` VALUES (27205, 'They seized power in a military coup.', 'n. 力量，能力；电力，功率；政权，势力；[数] 幂; v. 激励；供以动力；使…有力量; adj. 借影响有权势人物以操纵权力的', '/\'paʊə | \'paʊɚ/', 'power', 5);
INSERT INTO `words` VALUES (27206, 'He was one of the most powerful men in Bohemia.', 'adj. 强大的；强有力的; adv. 很；非常', '/\'pauəful | \'paʊəfʊl; -f(ə)l | \'paʊɚfl/', 'powerful', 5);
INSERT INTO `words` VALUES (27207, 'Candidates should have training and practical experience in basic electronics.', 'adj. 实际的；实用性的', '/\'præktikəl | \'præktɪk(ə)l | \'præktɪkl/', 'practical', 5);
INSERT INTO `words` VALUES (27208, 'I’ve read practically all of his books.', 'adv. 实际地；几乎；事实上', '/\'præktikəli | \'præktɪk(ə)lɪ | \'præktɪkli/', 'practically', 5);
INSERT INTO `words` VALUES (27209, 'It takes hours of practice to learn to play the guitar.', 'n. 实践；练习；惯例; v. 练习；实习；实行', '/\'præktis | \'præktɪs/', 'practice', 5);
INSERT INTO `words` VALUES (27210, 'They moved the furniture back to practise their dance routine.', 'v. 练习，实践；实施，实行；从事', '/\'præktis | \'præktɪs/', 'practise', 5);
INSERT INTO `words` VALUES (27211, 'a practitioner of alternative medicine', 'n. 开业者，从业者，执业医生', '/præk\'tɪʃ(ə)nə | præk\'tɪʃənɚ/', 'practitioner', 5);
INSERT INTO `words` VALUES (27212, 'It’s important to give children plenty of praise and encouragement.', 'n. 赞扬；称赞；荣耀；崇拜; v. 赞美，歌颂；表扬', '/preiz | preɪz | prez/', 'praise', 5);
INSERT INTO `words` VALUES (27213, 'They went to the mosque to pray.', 'v. 请求,恳求;祈祷,祈求', '/prei | preɪ | pre/', 'pray', 5);
INSERT INTO `words` VALUES (27214, 'Our thoughts and prayers are with you at this difficult time.', 'n. 祈祷,祷告,祷文', '/preə | prɛr/', 'prayer', 5);
INSERT INTO `words` VALUES (27215, 'He traveled the southern states, preaching the gospel .', 'v. 说教；讲道；鼓吹；传道；反复灌输; n. 说教', '/pri:tʃ | priːtʃ | pritʃ/', 'preach', 5);
INSERT INTO `words` VALUES (27216, 'Fire precautions were neglected.', 'n. 预防，警惕；预防措施; vt. 警惕；预先警告', '/pri\'kɔ:ʃən | prɪ\'kɔːʃ(ə)n | prɪ\'kɔʃən/', 'precaution', 5);
INSERT INTO `words` VALUES (27217, 'a type of cloud that precedes rain', 'v. 领先(于),在(…之前);优先,先于', '/pri:\'si:d, pri- | prɪ\'siːd | prɪ\'sid/', 'precede', 5);
INSERT INTO `words` VALUES (27218, 'a legal precedent', 'n. 先例', '/pri\'si:dənt, \'presi- | \'presɪd(ə)nt | \'prɛsɪdənt/', 'precedent', 5);
INSERT INTO `words` VALUES (27219, 'As we saw in the preceding chapter, groups can be powerful agents of socialization.', 'adj. 在前的,在先的', '/pri\'si:diŋ, \'pri:- | prɪ\'siːdɪŋ | \'prisidɪŋ/', 'preceding', 5);
INSERT INTO `words` VALUES (27220, 'planes delivering precious supplies of medicine and food', 'adj. 珍贵的,贵重的', '/\'preʃəs | \'prɛʃəs/', 'precious', 5);
INSERT INTO `words` VALUES (27221, 'precise sales figures', 'adj. 精确的,准确的', '/pri\'sais | prɪ\'saɪs/', 'precise', 5);
INSERT INTO `words` VALUES (27222, 'The choir sang with precision.', 'n. 精确,精确度', '/pri\'siʒən | prɪ\'sɪʒ(ə)n | prɪ\'sɪʒn/', 'precision', 5);
INSERT INTO `words` VALUES (27223, 'rules that preclude experimentation in teaching methods', 'v. 排除,阻止,妨碍', '/pri\'klu:d | prɪ\'kluːd | prɪ\'klud/', 'preclude', 5);
INSERT INTO `words` VALUES (27224, 'Kennedy’s predecessor as President was the war hero Dwight Eisenhower.', 'n. 前辈，前任', '/\'pri:disesə, \'pre- | \'priːdɪsesə | \'prɛdəsɛsɚ/', 'predecessor', 5);
INSERT INTO `words` VALUES (27225, 'Sales were five percent lower than predicted.', 'v. 预言,预测,预告', '/pri\'dikt | prɪ\'dɪkt/', 'predict', 5);
INSERT INTO `words` VALUES (27226, 'the predominant group in society', 'adj. (over)占优势的;主要的,突出的', '/,pri\'dɔminənt | prɪ\'dɒmɪnənt | prɪ\'dɑmənənt/', 'predominant', 5);
INSERT INTO `words` VALUES (27227, '...the preface to Kelman\'s novel.', 'n. 前言；引语; v. 为…加序言；以…开始', '/\'prefis | \'prefəs | \'prɛfəs/', 'preface', 5);
INSERT INTO `words` VALUES (27228, 'This type of owl prefers a desert habitat.', 'v. 更喜欢；宁愿；提出；提升', '/pri\'fə: | prɪ\'fɜː | prɪ\'fɝ/', 'prefer', 5);
INSERT INTO `words` VALUES (27229, 'For this dish, fresh herbs and garlic are preferable.', 'adj. 更好的，更可取的；更合意的', '/\'prefərəbl | \'pref(ə)rəb(ə)l | \'prɛfrəbl/', 'preferable', 5);
INSERT INTO `words` VALUES (27230, 'Do you have a colour preference ?', 'n. 偏爱，倾向；优先权', '/\'prefərəns | \'pref(ə)r(ə)ns | \'prɛfrəns/', 'preference', 5);
INSERT INTO `words` VALUES (27231, 'care for pregnant women', 'adj. 怀孕的；富有意义的', '/\'preɡnənt | \'pregnənt | \'prɛɡnənt/', 'pregnant', 5);
INSERT INTO `words` VALUES (27232, 'Women still face prejudice in the workplace.', 'n. 偏见；侵害; v. 损害；使有偏见', '/\'predʒudis | \'predʒʊdɪs | \'prɛdʒədɪs/', 'prejudice', 5);
INSERT INTO `words` VALUES (27233, 'the preliminary stages of the competition', 'adj. 预备的,初步的', '/pri\'liminəri | prɪ\'lɪmɪn(ə)rɪ | prɪ\'lɪmɪnɛri/', 'preliminary', 5);
INSERT INTO `words` VALUES (27234, 'one of Dublin’s premier hotels', 'adj. 第一的；最初的; n. 总理，首相', '/\'premjə, pri\'miə, \'pri:m- | \'premɪə; \'priː- | prɪ\'mɪr/', 'premier', 5);
INSERT INTO `words` VALUES (27235, 'Schools may earn extra money by renting out their premises.', 'v. 引出，预先提出；作为…的前提; n. 前提；上述各项；房屋连地基', '/pri\'maiz, \'premis | \'premɪs | ˈpremɪs/', 'premise', 5);
INSERT INTO `words` VALUES (27236, 'insurance premiums', 'n. 额外费用；奖金；保险费;(商)溢价; adj. 高价的；优质的', '/\'priːmɪəm | \'primɪəm/', 'premium', 5);
INSERT INTO `words` VALUES (27237, 'This dish is good for dinner parties because much of the preparation can be done ahead of time.', 'n. 准备,预备;制剂,制备品', '/,prepə\'reiʃən | ,prepə\'reɪʃ(ə)n | ,prɛpə\'reʃən/', 'preparation', 5);
INSERT INTO `words` VALUES (27238, 'The prosecution wanted more time to prepare their case.', 'v. 准备,预备', '/pri\'pεə | prɪ\'peə | prɪ\'pɛr/', 'prepare', 5);
INSERT INTO `words` VALUES (27239, 'There is nothing in the rules of grammar to suggest that ending a sentence with a preposition is wrong.', 'n. 介词', '/,prepə\'ziʃən | ,prepə\'zɪʃ(ə)n | ,prɛpə\'zɪʃən/', 'preposition', 5);
INSERT INTO `words` VALUES (27240, 'What punishment does the law prescribe for this crime?', 'v. 指示,规定;处(方),开(药)', '/pris\'kraib | prɪ\'skraɪb/', 'prescribe', 5);
INSERT INTO `words` VALUES (27241, 'We are trying to cut the price of prescription drugs .', 'n. 药方,处方', '/pris\'kripʃən | prɪ\'skrɪpʃ(ə)n | prɪ\'skrɪpʃən/', 'prescription', 5);
INSERT INTO `words` VALUES (27242, 'Your presence is requested at the club meeting on Friday.', 'n. 出席,到场,存在,在', '/\'prezəns | \'prez(ə)ns | \'prɛzns/', 'presence', 5);
INSERT INTO `words` VALUES (27243, 'the present situation of the millions of people who are suffering poverty and disease', 'adj. 出席的,现在的; n. 现在,礼物; v. 赠送,提出', '/\'prezənt, pri\'zent | \'prez(ə)nt | \'prɛznt/', 'present', 5);
INSERT INTO `words` VALUES (27244, 'The doctor will be here presently.', 'adv. 一会儿,不久;现在,目前', '/\'prezəntli | \'prez(ə)ntlɪ | \'prɛzntli/', 'presently', 5);
INSERT INTO `words` VALUES (27245, 'We must encourage the planting of new trees and preserve our existing woodlands.', 'v. 保存；保护；维持；腌；禁猎; n. 保护区；禁猎地；加工成的食品', '/pri\'zə:v | prɪ\'zɜːv | prɪ\'zɝv/', 'preserve', 5);
INSERT INTO `words` VALUES (27246, 'I shall be pleased to preside at your meetings.', 'v. (at,over)主持', '/pri\'zaid | prɪ\'zaɪd/', 'preside', 5);
INSERT INTO `words` VALUES (27247, 'President Bush', 'n. 总统,校长,会长,主席', '/\'prezɪd(ə)nt | \'prɛzɪdənt/', 'president', 5);
INSERT INTO `words` VALUES (27248, 'They are putting pressure on people to vote yes.', 'n. 压力；压迫，[物] 压强; v. 迫使；密封；使……增压', '/\'preʃə | \'prɛʃɚ/', 'pressure', 5);
INSERT INTO `words` VALUES (27249, 'The king wanted to enhance his prestige through war.', 'n. 声望,威望,威信', '/pre\'sti:ʒ, -\'sti:dʒ, \'prestidʒ | pre\'stiː(d)ʒ | prɛ\'stidʒ/', 'prestige', 5);
INSERT INTO `words` VALUES (27250, 'It’s raining, which presumably means that your football match will be cancelled.', 'adv. 大概；推测起来；可假定', '/pri\'zju:-məbli,pri:- | prɪ\'zjuːməblɪ | prɪ\'zuməbli/', 'presumably', 5);
INSERT INTO `words` VALUES (27251, 'I presume you\'re here on business.', 'v. 假定,假设,认为,揣测,滥用,擅自行动', '/pri\'zju:m, -\'zu:m | prɪ\'zjuːm | prɪ\'zum/', 'presume', 5);
INSERT INTO `words` VALUES (27252, 'Let’s pretend we’re on the moon.', 'v. 假装，伪装，佯装; adj. 假装的', '/pri\'tend | prɪ\'tend | prɪ\'tɛnd/', 'pretend', 5);
INSERT INTO `words` VALUES (27253, 'He’ll phone on some pretext or other.', 'n. 借口；托辞; vt. 以…为借口', '/\'pri:tekst | \'priːtekst | \'pritɛkst/', 'pretext', 5);
INSERT INTO `words` VALUES (27254, 'a pretty little girl', 'adj. 漂亮的；可爱的；优美的; adv. 相当地；颇; n. 有吸引力的事物（尤指饰品）；漂亮的人', '/\'prɪtɪ | \'prɪti/', 'pretty', 5);
INSERT INTO `words` VALUES (27255, 'Justice will prevail.', 'v. 盛行，流行；战胜，获胜', '/pri\'veil, pri:- | prɪ\'veɪl | pri\'vel/', 'prevail', 5);
INSERT INTO `words` VALUES (27256, 'the prevalent belief in astrology', 'adj. 流行的,普遍的', '/\'prevələnt | \'prev(ə)l(ə)nt | \'prɛvələnt/', 'prevalent', 5);
INSERT INTO `words` VALUES (27257, 'The rules are intended to prevent accidents.', 'v. (from)预防,防止,阻止,制止,妨碍', '/pri\'vent, pri:- | prɪ\'vent | pri\'vɛnt/', 'prevent', 5);
INSERT INTO `words` VALUES (27258, 'She has a teenage daughter from a previous marriage.', 'adj. 以前的；早先的；过早的; adv. 在先；在…以前', '/\'pri:vjəs | \'priːvɪəs | \'privɪəs/', 'previous', 5);
INSERT INTO `words` VALUES (27259, 'The effect was to disrupt the food chain, starving many animals and those that preyed on them.', 'v. 捕食；掠夺；折磨; n. 捕食；牺牲者；被捕食的动物', '/prei | preɪ | pre/', 'prey', 5);
INSERT INTO `words` VALUES (27260, 'They may pay a high price for their few years of glory.', 'n. 价格,价钱;代价; v. 标价', '/prais | praɪs/', 'price', 5);
INSERT INTO `words` VALUES (27261, 'Prick the sausages before you grill them.', 'v. 刺，戳；刺伤，刺痛；竖起; n. 刺，扎；刺痛，刺伤；阴茎；锥; adj. 竖起的', '/prik | prɪk/', 'prick', 5);
INSERT INTO `words` VALUES (27262, 'He wore his medals with pride.', 'n. 自豪;自满；引以自豪的东西; v. 使自豪', '/praid | praɪd/', 'pride', 5);
INSERT INTO `words` VALUES (27263, 'He had trained to be a Catholic priest.', 'n. 教士,神父', '/pri:st | priːst | prist/', 'priest', 5);
INSERT INTO `words` VALUES (27264, 'Our primary concern is to provide the refugees with food and health care.', 'adj. 最初的,初级的;首要的,主要的,基本的', '/\'praiməri | \'praɪm(ə)rɪ | \'praɪmɛri/', 'primary', 5);
INSERT INTO `words` VALUES (27265, 'Smoking is the prime cause of lung disease.', 'adj. 首要的;最好的,第一流的; n. 青春,全盛期', '/praim | praɪm/', 'prime', 5);
INSERT INTO `words` VALUES (27266, 'a primitive society', 'adj. 原始的,远古的,早期的;粗糙的,简单的', '/\'primitiv | \'prɪmɪtɪv | \'prɪmətɪv/', 'primitive', 5);
INSERT INTO `words` VALUES (27267, 'Prince William', 'n. 王子,亲王', '/prins | prɪns/', 'prince', 5);
INSERT INTO `words` VALUES (27268, 'Princess Anne', 'n. 公主,王妃', '/prin\'ses, \'prinsis | prɪn\'ses | prɪnˌsɛs/', 'princess', 5);
INSERT INTO `words` VALUES (27269, 'His principal reason for making the journey was to visit his family.', 'adj. 最重要的,主要的n.负责人,校长;资本,本金', '/\'prinsəpəl | \'prɪnsəp(ə)l | \'prɪnsəpl/', 'principal', 5);
INSERT INTO `words` VALUES (27270, 'The general principle is that education should be available to all children up to the age of 16.', 'n. 原理,原则;主义,信念', '/\'prinsəpl | \'prɪnsɪp(ə)l | \'prɪnsəpl/', 'principle', 5);
INSERT INTO `words` VALUES (27271, 'There was no print at all on the backs of the tickets.', 'n. 印刷业；印花布；印刷字体；印章；印记; v. 印刷；打印；刊载；用印刷体写；在…印花样', '/print | prɪnt/', 'print', 5);
INSERT INTO `words` VALUES (27272, 'His own children have a prior claim to the business.', 'adj. 优先的,在前的;(to)在…之前', '/\'praiə | \'praɪə | \'praɪɚ/', 'prior', 5);
INSERT INTO `words` VALUES (27273, 'The club’s priority is to win the League.', 'n. 先,前;优先,重点,优先权', '/prai\'ɔrəti | praɪ\'ɒrɪtɪ | praɪ\'ɔrəti/', 'priority', 5);
INSERT INTO `words` VALUES (27274, 'He visits his dad in prison every week.', 'n. 监狱', '/\'prizən | \'prɪz(ə)n | \'prɪzn/', 'prison', 5);
INSERT INTO `words` VALUES (27275, 'Relationships between the staff and the prisoners are good.', 'n. 囚犯', '/\'prizənə | \'prɪz(ə)nə | \'prɪznɚ/', 'prisoner', 5);
INSERT INTO `words` VALUES (27276, 'With seven people squashed in one house, you don’t get much privacy.', 'n. (不受干扰的)独处，自由，隐私；私生活', '/\'praivəsi, \'pri-, \'prai- | \'prɪvəsɪ; \'praɪ- | \'praɪvəsi/', 'privacy', 5);
INSERT INTO `words` VALUES (27277, 'Morris has a private jet.', 'adj. 私人的,个人的,秘密的,私下的', '/\'praivit | \'praɪvət/', 'private', 5);
INSERT INTO `words` VALUES (27278, 'He had no special privileges and was treated just like every other prisoner.', 'n. 特权,优惠,特许; v. 给予优惠,给予特权', '/ˈprɪvəlɪdʒ/', 'privilege', 5);
INSERT INTO `words` VALUES (27279, 'In this month’s competition you could win a prize worth £3,000.', 'n. 奖赏,奖金,奖品; v. 珍视,珍惜', '/praiz | praɪz/', 'prize', 5);
INSERT INTO `words` VALUES (27280, 'You must decide whether, on the balance of probabilities , he committed the crime.', 'n. 可能性；机率；[数] 或然率', '/,prɔbə\'biləti | prɒbə\'bɪlɪtɪ | \'prɑbə\'bɪləti/', 'probability', 5);
INSERT INTO `words` VALUES (27281, 'The probable cause of the fire was faulty wiring.', 'adj. 很可能的；可信的; n. 很可能的事；大有希望的候选者', '/\'prɔbəbl | \'prɒbəb(ə)l | \'prɑbəbl/', 'probable', 5);
INSERT INTO `words` VALUES (27282, 'a police corruption probe', 'n. 探针；调查; v. 调查；探测', '/prəub | prəʊb | prob/', 'probe', 5);
INSERT INTO `words` VALUES (27283, 'On board, we were given the usual talk on safety procedures (= what to do if an accident happens, or to prevent an accident ) .', 'n. 程序,手续,步骤', '/prə\'si:dʒə | prə\'siːdʒə | prə\'sidʒɚ/', 'procedure', 5);
INSERT INTO `words` VALUES (27284, 'Before proceeding further, we must define our terms.', 'v. 进行,继续下去;发生', '/prəu\'si:d | prə\'siːd | pro\'sid/', 'proceed', 5);
INSERT INTO `words` VALUES (27285, 'The proceedings of the inquiry will take place in private.', 'n. 行动,进行,(pl.)会议录,学报', '/prəu\'si:diŋ | prəʊ\'siːdɪŋ | prə\'sidɪŋ/', 'proceeding', 5);
INSERT INTO `words` VALUES (27286, 'the Israeli-Egyptian peace process', 'n. 过程,进程;工序,制作法;工艺; v. 加工,处理', '/\'prəuses, \'prɔ- | \'prəʊses | \'prɑsɛs/', 'process', 5);
INSERT INTO `words` VALUES (27287, 'They marched in procession to the Capitol building.', 'n. 队伍,行列', '/prəu\'seʃən | prə\'seʃ(ə)n | prə\'sɛʃən/', 'procession', 5);
INSERT INTO `words` VALUES (27288, 'The President proclaimed the republic’s independence.', 'v. 宣告，公布；声明；表明；赞扬', '/prəu\'kleim | prə\'kleɪm | prə\'klem/', 'proclaim', 5);
INSERT INTO `words` VALUES (27289, 'New drugs are producing remarkable results .', 'v. 生产,制造,显示,演出,导致; n. 产品', '/prə\'djuːs | prə\'dus/', 'produce', 5);
INSERT INTO `words` VALUES (27290, 'The London factory assembles the finished product .', 'n. 产品,产物;乘积', '/\'prɔdəkt, -ʌkt | \'prɒdʌkt | \'prɑdʌkt/', 'product', 5);
INSERT INTO `words` VALUES (27291, 'That model won\'t go into production before late 2007.', 'n. 生产,产品,作品,(研究)成果,总产量', '/prəu\'dʌkʃən | prə\'dʌkʃ(ə)n | prə\'dʌkʃən/', 'production', 5);
INSERT INTO `words` VALUES (27292, 'Most of us are more productive in the morning.', 'adj. 生产(性)的,能产的,多产的', '/prəu\'dʌktiv | prə\'dʌktɪv/', 'productive', 5);
INSERT INTO `words` VALUES (27293, 'high productivity levels in manufacturing', 'n. 生产率', '/,prɔdʌk\'tivəti, ,prəu- | prɒdʌk\'tɪvɪtɪ | ,prodʌk\'tɪvəti/', 'productivity', 5);
INSERT INTO `words` VALUES (27294, 'people who work in the professions', 'n. 职业，专业；声明，宣布，表白', '/prəu\'feʃən | prə\'feʃ(ə)n | prə\'fɛʃən/', 'profession', 5);
INSERT INTO `words` VALUES (27295, 'This business plan looks very professional.', 'adj. 专业的；职业的；职业性的; n. 专业人员；职业运动员', '/prə\'feʃənəl | prə\'feʃ(ə)n(ə)l | prə\'fɛʃənl/', 'professional', 5);
INSERT INTO `words` VALUES (27296, 'I brought her proficiency up to the required level.', 'n. (in)熟练,精通', '/prəu\'fiʃənsi | prə\'fɪʃ(ə)nsɪ | prə\'fɪʃənsi/', 'proficiency', 5);
INSERT INTO `words` VALUES (27297, 'Dani has a lovely profile.', 'n. 侧面；轮廓；外形；剖面；简况; v. 描…的轮廓；扼要描述', '/\'prəufail | \'prəʊfaɪl | \'profaɪl/', 'profile', 5);
INSERT INTO `words` VALUES (27298, 'The shop’s daily profit is usually around $500.', 'n. 利润,收益; v. (by,from)得利,获益;有利于', '/\'prɔfit | \'prɒfɪt | \'prɑfɪt/', 'profit', 5);
INSERT INTO `words` VALUES (27299, 'The advertising campaign proved very profitable.', 'adj. 有利可图的,有益的', '/\'prɔfitəbl | \'prɒfɪtəb(ə)l | \'prɑfɪtəbl/', 'profitable', 5);
INSERT INTO `words` VALUES (27300, 'a profound sense of guilt', 'adj. 深厚的；意义深远的；渊博的', '/prəˈfaʊnd | prə\'faʊnd/', 'profound', 5);
INSERT INTO `words` VALUES (27301, 'the US space program', 'n. 计划，规划；节目；程序; v. 编程序；制作节目', '/\'prəuɡræm, -ɡrəm | \'prəʊgræm | proɡrəm/', 'programme', 5);
INSERT INTO `words` VALUES (27302, 'We made good progress despite the snow.', 'v&n. 进步，进展；前进', '/\'prəuɡres, \'prɔ-, prəu\'ɡres | \'prəʊgres | \'prɑɡrɛs/', 'progress', 5);
INSERT INTO `words` VALUES (27303, 'a progressive administration', 'adj. 进步的,先进的;前进的', '/prəu\'ɡresiv | prə\'gresɪv | prə\'ɡrɛsɪv/', 'progressive', 5);
INSERT INTO `words` VALUES (27304, 'Smoking is strictly prohibited inside the factory.', 'v. 阻止，禁止', '/prəu\'hibit | prə(ʊ)\'hɪbɪt | prə\'hɪbɪt/', 'prohibit', 5);
INSERT INTO `words` VALUES (27305, 'The project aims to provide an analysis of children’s emotions.', 'n. 方案,工程,项目v.投射,放映;设计,规划', '/英 [prəˈdʒekt] 美 [prəˈdʒɛkt | prəˈdʒekt; ˈprɒdʒekt | prəˈdʒɛkt; prɑdʒɛkt/', 'project', 5);
INSERT INTO `words` VALUES (27306, '...a slide projector.', 'n. 放映机,幻灯机,投影仪', '/prəu\'dʒektə | prə\'dʒektə | prə\'dʒɛktɚ/', 'projector', 5);
INSERT INTO `words` VALUES (27307, 'I was trying to think of some way to prolong the conversation.', 'v. 延长；拖延', '/prə\'lɔŋ, \'lɔ:ŋ | prə\'lɒŋ | prəˈlɑːŋ/', 'prolong', 5);
INSERT INTO `words` VALUES (27308, 'a prominent Russian scientist', 'adj. 突出的，显著的；杰出的；卓越的', '/\'prɔminənt | \'prɒmɪnənt | \'prɑmɪnənt/', 'prominent', 5);
INSERT INTO `words` VALUES (27309, 'If you make a promise, you should keep it.', 'n. 许诺，允诺；希望; v. 允诺，许诺；给人以…的指望或希望', '/\'prɔmis | \'prɒmɪs | \'prɑmɪs/', 'promise', 5);
INSERT INTO `words` VALUES (27310, 'a promising career in law', 'adj. 有希望的，有前途的; v. 许诺，答应（promise的现在分词形式）', '/\'prɔmisiŋ | \'prɒmɪsɪŋ | \'prɑmɪsɪŋ/', 'promising', 5);
INSERT INTO `words` VALUES (27311, 'You don\'t have to sacrifice environmental protection to promote economic growth.', 'v. 促进,发扬;提升,提拔;增进,助长', '/prəu\'məut | prə\'məʊt | prə\'mot/', 'promote', 5);
INSERT INTO `words` VALUES (27312, 'Prompt action must be taken.', 'adj. 敏捷的，迅速的；立刻的; v. 提示；促进；激起；（给演员）提白; n. 提示；付款期限；DOS命令：改变DOS系统提示符的风格; adv. 准时地', '/prɔmpt | prɒm(p)t | prɑmpt/', 'prompt', 5);
INSERT INTO `words` VALUES (27313, 'His eyes shifted to the prone body on the floor.', 'adj. 俯卧的；有…倾向的，易于…的; n. (Prone)人名；(意、法)普罗内', '/prəun | prəʊn | pron/', 'prone', 5);
INSERT INTO `words` VALUES (27314, 'Now if we could only figure out the pronoun problem.', 'n. 代词', '/\'prəunaun | \'prəʊnaʊn | \'pronaʊn/', 'pronoun', 5);
INSERT INTO `words` VALUES (27315, 'How do you pronounce your name?', 'v. 发…的音;宣布,宣判', '/prəu\'nauns | prə\'naʊns/', 'pronounce', 5);
INSERT INTO `words` VALUES (27316, 'She gave the word its French pronunciation.', 'n. 发音,发音方法', '/prəu,nʌnsi\'eiʃən | prə,nʌnsɪ\'eɪʃ(ə)n | prə,nʌnsɪ\'eʃən/', 'pronunciation', 5);
INSERT INTO `words` VALUES (27317, 'There is no proof that the document is authentic.', 'n. 证据,证明;校样,样张', '/pru:f | pruːf | pruf/', 'proof', 5);
INSERT INTO `words` VALUES (27318, 'the spreading of political propaganda', 'n. 宣传；传道总会', '/,prɔpə\'ɡændə | prɒpə\'gændə | \'prɑpə\'gændə/', 'propaganda', 5);
INSERT INTO `words` VALUES (27319, 'a boat propelled by a small motor', 'v. 推进；驱使；激励；驱策', '/prəu\'pel | prə\'pel | prə\'pɛl/', 'propel', 5);
INSERT INTO `words` VALUES (27320, 'Everything was in its proper place (= where it should be ) .', 'adj. 适当的；本身的；特有的；正派的; adv. 完全地; n. (Proper)人名；(英、德)普罗珀', '/\'prɔpə | \'prɒpə | \'prɑpɚ/', 'proper', 5);
INSERT INTO `words` VALUES (27321, 'The hotel is not responsible for any loss or damage to guests’ personal property .', 'n. 性质，性能；财产；所有权', '/\'prɔpəti | \'prɒpətɪ | \'prɑpɚti/', 'property', 5);
INSERT INTO `words` VALUES (27322, 'the prophet Elijah', 'n. 先知；预言者；提倡者', '/\'prɔfit | \'prɒfɪt | \'prɑfɪt/', 'prophet', 5);
INSERT INTO `words` VALUES (27323, 'A large proportion of the dolphins in that area will eventually die.', 'n. 比例;部分;均衡,相称', '/prə\'pɔːʃ(ə)n | prə\'pɔrʃən/', 'proportion', 5);
INSERT INTO `words` VALUES (27324, 'The president is to put forward new proposals for resolving the country\'s constitutional crisis.', 'n. 提议,建议;求婚', '/prəu\'pəuzəl | prə\'pəʊz(ə)l | prə\'pozl/', 'proposal', 5);
INSERT INTO `words` VALUES (27325, 'the changes currently proposed by the local planning authorities', 'v. 提议,建议;提名,推荐;求婚', '/prəu\'pəuz | prə\'pəʊz | prə\'poz/', 'propose', 5);
INSERT INTO `words` VALUES (27326, 'The theory is founded on two basic propositions.', 'n. 主张,建议;陈述,命题', '/,prɔpə\'ziʃən | prɒpə\'zɪʃ(ə)n | ,prɑpə\'zɪʃən/', 'proposition', 5);
INSERT INTO `words` VALUES (27327, 'Shute\'s prose is stark and chillingly unsentimental.', 'n. 散文；单调; adj. 散文的；平凡的；乏味的; vi. 写散文；乏味地讲话; vt. 把…写成散文', '/prəuz | prəʊz | proz/', 'prose', 5);
INSERT INTO `words` VALUES (27328, 'Mrs Lynn Smith, prosecuting, said the offence took place on January 27.', 'v. 实行，从事; v. 起诉，告发; v. 作检察官', '/\'prɔsikju:t | \'prɒsɪkjuːt | \'prɑsɪ\'kjʊt/', 'prosecute', 5);
INSERT INTO `words` VALUES (27329, 'I had no job, no education, and no prospects .', 'n. 景色;前景,前途,展望', '/\'prɔspekt | \'prɒspekt | \'prɑspɛkt/', 'prospect', 5);
INSERT INTO `words` VALUES (27330, 'The story should act as a warning to other prospective buyers.', 'adj. 预期的', '/prəu\'spektiv | prə\'spektɪv | prə\'spɛktɪv/', 'prospective', 5);
INSERT INTO `words` VALUES (27331, 'His business continued to prosper.', 'v. 成功,兴隆,昌盛,使成功,使昌隆,繁荣', '/\'prɔspə | \'prɒspə | \'prɑspɚ/', 'prosper', 5);
INSERT INTO `words` VALUES (27332, 'a time of economic prosperity', 'n. 繁荣,兴旺', '/prɔs\'periti | prɒ\'sperɪtɪ | prɑ\'spɛrəti/', 'prosperity', 5);
INSERT INTO `words` VALUES (27333, 'a prosperous landowner', 'adj. 繁荣的,兴旺的,茂盛的,顺利的', '/\'prɔspərəs | \'prɒsp(ə)rəs | \'prɑspərəs/', 'prosperous', 5);
INSERT INTO `words` VALUES (27334, 'Are we doing enough to protect the environment?', 'v. (from)保护,保卫', '/prəu\'tekt | prə\'tekt | prə\'tɛkt/', 'protect', 5);
INSERT INTO `words` VALUES (27335, 'Where do you get your protein?', 'n. 蛋白质；朊; adj. 蛋白质的', '/\'prəuti:n, -ti:in | \'prəʊtiːn | \'protin/', 'protein', 5);
INSERT INTO `words` VALUES (27336, '‘I don’t see why I should take the blame for this!’ she protested.', 'v. 抗议；断言; n. 抗议; adj. 表示抗议的；抗议性的', '/prəu\'test, \'prəu- | \'prəʊtest | ˈproʊtest/', 'protest', 5);
INSERT INTO `words` VALUES (27337, 'How do you test the prototype of the vending machine?', 'n. 原型；标准，模范', '/\'prəutətaip | \'prəʊtətaɪp | \'protə\'taɪp/', 'prototype', 5);
INSERT INTO `words` VALUES (27338, 'Seth was the proud owner of a new sports car.', 'adj. 自豪的；得意的；自负的; n. (Proud)人名；(英)普劳德', '/praud | praʊd/', 'proud', 5);
INSERT INTO `words` VALUES (27339, 'You’re wrong, and I can prove it.', 'v. 证明,证实;检验;考验;鉴定;结果是,表明是', '/pru:v | pruːv | pruv/', 'prove', 5);
INSERT INTO `words` VALUES (27340, 'Tea and biscuits will be provided.', 'v. 供应,供给,准备,预防,规定', '/prəu\'vaid | prə\'vaɪd/', 'provide', 5);
INSERT INTO `words` VALUES (27341, 'He can come with us, provided he pays for his own meals.', 'conj. 倘若,只要,假如', '/prə\'vaidid | prə\'vaɪdɪd/', 'provided', 5);
INSERT INTO `words` VALUES (27342, 'a Chinese province', 'n. 省；领域；职权', '/\'prɔvins | \'prɒvɪns | \'prɑvɪns/', 'province', 5);
INSERT INTO `words` VALUES (27343, 'He made provisions for his wife and his children in his will.', 'n. 供应,供应品;预备;条款;(pl.)给养', '/prəu\'viʒən | prə\'vɪʒ(ə)n | prə\'vɪʒn/', 'provision', 5);
INSERT INTO `words` VALUES (27344, 'The dog would not have attacked if it hadn’t been provoked.', 'v. 挑动;激发;招惹', '/prəu\'vəuk | prə\'vəʊk | prə\'vok/', 'provoke', 5);
INSERT INTO `words` VALUES (27345, 'prudent house buyers', 'adj. 谨慎的；精明的；节俭的; n. (Prudent)人名；(法)普吕当', '/\'pru:dənt | \'pruːd(ə)nt | \'prʊdnt/', 'prudent', 5);
INSERT INTO `words` VALUES (27346, NULL, 'n. 精神病学；精神病治疗法', '/psai\'kaiətri, psi- | saɪ\'kaɪətrɪ | saɪ\'kaɪətri/', 'psychiatry', 5);
INSERT INTO `words` VALUES (27347, 'the psychology of three-year-olds', 'n. 心理,心理学,心理状态', '/psai\'kɔlədʒi | saɪ\'kɒlədʒɪ | saɪ\'kɑlədʒi/', 'psychology', 5);
INSERT INTO `words` VALUES (27348, 'Do you fancy going to the pub?', 'n. 酒馆；客栈', '/pʌb/', 'pub', 5);
INSERT INTO `words` VALUES (27349, 'The guide is being translated into several languages for publication near Christmas.', 'n. 出版；出版物；发表', '/,pʌbli\'keiʃən | ,pʌblɪ\'keɪʃ(ə)n | ,pʌblɪ\'keʃən/', 'publication', 5);
INSERT INTO `words` VALUES (27350, 'Much advance publicity was given to the talks.', 'n. 宣传，宣扬；公开；广告；注意', '/pʌb\'lisiti | pʌb\'lɪsɪtɪ | pʌb\'lɪsəti/', 'publicity', 5);
INSERT INTO `words` VALUES (27351, 'The first edition was published in 1765.', 'v. 出版；发表；公布', '/\'pʌbliʃ | \'pʌblɪʃ/', 'publish', 5);
INSERT INTO `words` VALUES (27352, 'Steam puffed out of the chimney.', 'v. 喷出，张开；使膨胀；夸张；使骄傲自满; n. 粉扑；泡芙；蓬松；一阵喷烟；肿块；吹嘘，宣传广告', '/pʌf/', 'puff', 5);
INSERT INTO `words` VALUES (27353, 'His breathing was shallow and his pulse was weak .', 'n. [电子] 脉冲；脉搏; v. 使跳动', '/pʌls/', 'pulse', 5);
INSERT INTO `words` VALUES (27354, 'It\'s not enough to get rid of raw sewage by pumping it out to sea.', 'v. 打气；用抽水机抽…; n. 泵，抽水机；打气筒', '/pʌmp/', 'pump', 5);
INSERT INTO `words` VALUES (27355, 'Make two holes with a hole punch.', 'n. 冲压机；打洞器；钻孔机; v. 开洞；以拳重击', '/pʌntʃ | pʌn(t)ʃ/', 'punch', 5);
INSERT INTO `words` VALUES (27356, 'She’s always very punctual for appointments.', 'adj. 准时的，守时的；精确的', '/\'pʌŋktjuəl, -tʃuəl | \'pʌŋ(k)tʃʊəl; -tjʊəl | \'pʌŋtʃʊəl/', 'punctual', 5);
INSERT INTO `words` VALUES (27357, 'Smacking is not an acceptable way of punishing a child.', 'v. 惩罚；严厉对待；贪婪地吃喝', '/\'pʌniʃ | \'pʌnɪʃ/', 'punish', 5);
INSERT INTO `words` VALUES (27358, 'About 20 pupils study music here.', 'n. 学生；[解剖] 瞳孔；未成年人', '/\'pjupəl | \'pjuːpɪl; -p(ə)l | pjupl/', 'pupil', 5);
INSERT INTO `words` VALUES (27359, 'When the invasion occurred he seized power and ruled the country as a puppet of the occupiers.', 'n. 木偶,傀儡', '/\'pʌpit | \'pʌpɪt/', 'puppet', 5);
INSERT INTO `words` VALUES (27360, 'She paid for her purchases and left.', 'n. 购买；紧握；起重装置; v. 购买；赢得', '/\'pə:tʃəs | \'pɜ:tʃəs | \'pɝtʃəs/', 'purchase', 5);
INSERT INTO `words` VALUES (27361, 'rings made of pure gold', 'adj. 纯的；纯粹的；纯洁的；清白的；纯理论的; n. (Pure)人名；(俄)普雷', '/pjuə | pjʊə | pjʊr/', 'pure', 5);
INSERT INTO `words` VALUES (27362, 'chemicals used to purify the water', 'v. 净化；使纯净', '/\'pjuərifai | \'pjʊərɪfaɪ | \'pjʊrɪfaɪ/', 'purify', 5);
INSERT INTO `words` VALUES (27363, 'His face turned purple with rage.', 'adj. 紫色的；帝王的；华而不实的; n. 紫色；紫袍; v. 变成紫色', '/\'pə:pl | \'pɜːp(ə)l | \'pɝpl/', 'purple', 5);
INSERT INTO `words` VALUES (27364, 'Nick had no particular purpose in mind when he started.', 'n. 目的,意图;用途,效果', '/\'pə:pəs | \'pɜːpəs | \'pɝpəs/', 'purpose', 5);
INSERT INTO `words` VALUES (27365, 'I locked the door and dropped the keys in my purse.', 'n. (女士)手提袋；(国家、家庭、团体等的) 财力; v. （嘴巴）皱起，使缩拢；撅嘴', '/pɜːs | pɝs/', 'purse', 5);
INSERT INTO `words` VALUES (27366, 'She plans to pursue a career in politics.', 'v. 继续；从事；追赶；纠缠', '/pə\'sju:, -\'su: | pə\'sjuː | pə\'sʊ/', 'pursue', 5);
INSERT INTO `words` VALUES (27367, 'The quarterback sprinted toward the end zone with Jansen in hot pursuit (= following closely behind ) .', 'n. 追赶，追求；职业，工作', '/pə\'sju:t | pə\'sjuːt | pɚ\'sut/', 'pursuit', 5);
INSERT INTO `words` VALUES (27368, 'It didn’t move, so she pushed harder.', 'v. 推动，增加；对…施加压力，逼迫；按；说服; n. 推，决心；大规模攻势；矢志的追求', '/pʊʃ/', 'push', 5);
INSERT INTO `words` VALUES (27369, 'a question that continues to puzzle scientists', 'v. 使…困惑；使…为难；苦思而得出; n. 谜；难题；迷惑', '/\'pʌzl | \'pʌz(ə)l/', 'puzzle', 5);
INSERT INTO `words` VALUES (27370, 'different levels of the management pyramid', 'n. 金字塔', '/\'pirəmid | \'pɪrəmɪd/', 'pyramid', 5);
INSERT INTO `words` VALUES (27371, 'He left school without any qualifications.', 'n. 资格；条件；限制；赋予资格', '/,kwɔlifi\'keiʃən | ,kwɒlɪfɪ\'keɪʃ(ə)n | ,kwɑlɪfɪ\'keʃən/', 'qualification', 5);
INSERT INTO `words` VALUES (27372, 'Free school lunches are given to children who qualify.', 'v. 限制；使具有资格；证明…合格', '/\'kwɔlifai | \'kwɒlɪfaɪ | ˈkwɑləˌfaɪ/', 'qualify', 5);
INSERT INTO `words` VALUES (27373, 'There are qualitative differences in the way children of different ages and adults think.', 'adj. 定性的；质的，性质上的', '/\'kwɔlitətiv, -tei- | \'kwɒlɪtətɪv | \'kwɑlətetɪv/', 'qualitative', 5);
INSERT INTO `words` VALUES (27374, 'Much of the land was of poor quality.', 'n. 质量，[统计] 品质；特性；才能; adj. 优质的；高品质的；<英俚>棒极了', '/\'kwɒlɪtɪ | \'kwɑləti/', 'quality', 5);
INSERT INTO `words` VALUES (27375, 'an attempt to quantify the region’s social and economic decline', 'v. 量化；为…定量；确定数量', '/\'kwɔntifai | \'kwɒntɪfaɪ | \'kwɑntɪfaɪ/', 'quantify', 5);
INSERT INTO `words` VALUES (27376, '...the advantages of quantitative and qualitative research.', 'adj. 定量的；量的，数量的', '/\'kwɔntitətiv, -tei- | \'kwɒntɪ,tətɪv; -,teɪtɪv | \'kwɑntətetɪv/', 'quantitative', 5);
INSERT INTO `words` VALUES (27377, 'Your work has improved in quantity and quality this term.', 'n. 量，数量；大量；总量', '/\'kwɔntəti | \'kwɒntɪtɪ | \'kwɑntəti/', 'quantity', 5);
INSERT INTO `words` VALUES (27378, 'I wish you two would stop quarreling.', 'v. 争吵,争论; n. 争吵,争吵的原因', '/\'kwɔ:rəl | \'kwɒr(ə)l | \'kwɔrəl/', 'quarrel', 5);
INSERT INTO `words` VALUES (27379, 'As a gift, he brought a big fish and a quart of the largest oysters I had ever seen.', 'n. 夸脱（容量单位）；一夸脱的容器', '/kwɔ:t | kwɔːt | kwɔrt/', 'quart', 5);
INSERT INTO `words` VALUES (27380, 'It’s about a page and a quarter.', 'n. 四分之一；地区；季度；一刻钟；两角五分；节; v. 住宿；驻扎; num. 四分之一', '/\'kwɔ:tə | \'kwɔːtə | \'kwɔrtɚ/', 'quarter', 5);
INSERT INTO `words` VALUES (27381, 'We publish a quarterly journal.', 'adj. 季度的，按季度的；一年四次的; adv. 按季度，[农] 一季一次地；纵横四分地; n. 季刊', '/\'kwɔ:təli | \'kwɔːtəlɪ | \'kwɔrtɚli/', 'quarterly', 5);
INSERT INTO `words` VALUES (27382, 'quartz crystals', 'n. 石英', '/kwɔ:ts | kwɔːts | kwɔrts/', 'quartz', 5);
INSERT INTO `words` VALUES (27383, 'She gave a queer laugh.', 'adj. 奇怪的；同性恋的；不舒服的；心智不平衡的; v. 搞糟；使陷于不利地位; n. 同性恋者；怪人；伪造的货币', '/kwiə | kwɪə | kwɪr/', 'queer', 5);
INSERT INTO `words` VALUES (27384, 'We stopped at a small bar to quench our thirst.', 'v. 熄灭，[机] 淬火；解渴；结束；冷浸', '/kwentʃ | kwen(t)ʃ | kwɛntʃ/', 'quench', 5);
INSERT INTO `words` VALUES (27385, 'They journeyed to the distant Molucca islands in quest of spices.', 'n. 追求；寻找; v. 追求；寻找', '/kwest | kwɛst/', 'quest', 5);
INSERT INTO `words` VALUES (27386, 'Teachers will be asked to fill in a questionnaire.', 'n. 问卷；调查表', '/,kwestʃə\'nεə, ,kes- | ˌkwestʃəˈneə(r) | ˌkwɛstʃənˈɛr/', 'questionnaire', 5);
INSERT INTO `words` VALUES (27387, 'You’ll have to join the queue.', 'n. 队列；长队；辫子; v. 排队；排队等候', '/kju: | kjuː | kju/', 'queue', 5);
INSERT INTO `words` VALUES (27388, 'Her nails were bitten to the quick.', 'n. 核心；伤口的嫩肉; adj. 快的；迅速的，敏捷的；灵敏的; adv. 迅速地，快', '/kwik | kwɪk/', 'quick', 5);
INSERT INTO `words` VALUES (27389, 'We’ll have to be quiet so as not to wake the baby.', 'adj. 安静的；安定的；不动的；温顺的; n. 安静；和平; v. 使平息；安慰', '/\'kwaɪət/', 'quiet', 5);
INSERT INTO `words` VALUES (27390, '...an old patchwork quilt.', 'n. 被子；棉被; v. 东拼西凑地编；加软衬料后缝制', '/kwilt | kwɪlt/', 'quilt', 5);
INSERT INTO `words` VALUES (27391, 'He quit his job after an argument with a colleague.', 'v. 离开；放弃；停止；使…解除; n. 离开；[计] 退出; adj. 摆脱了…的；已经了结的', '/kwit | kwɪt/', 'quit', 5);
INSERT INTO `words` VALUES (27392, 'I recognized it instantly and felt a quiver of panic.', 'n. 颤抖；箭袋；震动; v. 颤抖；振动', '/\'kwivə | \'kwɪvə | \'kwɪvɚ/', 'quiver', 5);
INSERT INTO `words` VALUES (27393, 'a biology quiz', 'n. 考查；恶作剧；课堂测验; v. 挖苦；张望；对…进行测验', '/kwiz | kwɪz/', 'quiz', 5);
INSERT INTO `words` VALUES (27394, 'The government has decided to scrap quotas on car imports.', 'n. 配额；定额；限额', '/\'kwəutə | \'kwəʊtə | \'kwotə/', 'quota', 5);
INSERT INTO `words` VALUES (27395, 'He quoted a short passage from the Bible.', 'v. 报价；引述；举证; n. 引用', '/kwəut, kəut | kwəʊt | kwot/', 'quote', 5);
INSERT INTO `words` VALUES (27396, 'The rabbit disappeared in the bushes.', 'n. 兔子，野兔; v. 让…见鬼去吧', '/\'ræbit | \'ræbɪt/', 'rabbit', 5);
INSERT INTO `words` VALUES (27397, 'The school welcomes children of all races .', 'n. 属，种；种族，人种；家庭，门第; v. 使参加比赛；和…竞赛；使急走，使全速行进', '/reɪs | res/', 'race', 5);
INSERT INTO `words` VALUES (27398, 'a victim of racial discrimination', 'adj. 种的， 种族的', '/\'reɪʃl | \'reʃl/', 'racial', 5);
INSERT INTO `words` VALUES (27399, 'a wine rack', 'n. [机] 齿条；架子；拷问台; v. 变形；随风飘；小步跑', '/ræk/', 'rack', 5);
INSERT INTO `words` VALUES (27400, 'The old machine used to make an awful racket .', 'n. 球拍；吵闹，喧闹; v. 过着花天酒地的生活', '/\'rækit | \'rækɪt/', 'racket', 5);
INSERT INTO `words` VALUES (27401, 'The coastline can now be monitored by radar.', 'n. [雷达] 雷达，无线电探测器', '/\'reidə | \'reɪdɑː | \'redɑr/', 'radar', 5);
INSERT INTO `words` VALUES (27402, 'She looked radiant in a white silk dress.', 'adj. 辐射的；容光焕发的；光芒四射的; n. 光点；发光的物体', '/\'reidiənt | \'reɪdɪənt | \'redɪənt/', 'radiant', 5);
INSERT INTO `words` VALUES (27403, 'He radiated calm confidence.', 'v. 辐射；传播；流露；发射；广播; adj. 辐射状的，有射线的', '/\'reidieit | \'reɪdɪeɪt | \'redɪet/', 'radiate', 5);
INSERT INTO `words` VALUES (27404, 'They are proposing radical changes to the way the company is run.', 'adj. 基本的， 重要的， 根本的；激进的， 极端的', '/\'rædɪkl/', 'radical', 5);
INSERT INTO `words` VALUES (27405, 'The last 12 months have been difficult ones for local radio.', 'n. 收音机；无线电广播设备; v. 用无线电进行通信', '/\'reidiəu | \'reɪdɪəʊ | \'redɪo/', 'radio', 5);
INSERT INTO `words` VALUES (27406, 'the problem of how to dispose of radioactive waste', 'adj. 放射性,放射引起的', '/,reidiəu\'æktiv | ,reɪdɪəʊ\'æktɪv | \'redɪo\'æktɪv/', 'radioactive', 5);
INSERT INTO `words` VALUES (27407, 'The shock of the explosion was felt over a radius of forty miles.', 'n. 半径，半径范围；[解剖] 桡骨；辐射光线；有效航程', '/\'reidiəs | \'reɪdɪəs | \'redɪəs/', 'radius', 5);
INSERT INTO `words` VALUES (27408, 'He was wiping his hands on an oily rag.', 'n. 破布；碎屑; v. 戏弄；责骂', '/ræɡ | ræg/', 'rag', 5);
INSERT INTO `words` VALUES (27409, 'Sobbing with rage, Carol was taken to the hospital.', 'n. 愤怒；狂暴，肆虐；情绪激动; v. 大怒，发怒；流行，风行', '/reidʒ | reɪdʒ | redʒ/', 'rage', 5);
INSERT INTO `words` VALUES (27410, 'a bombing raid', 'n. 袭击；突袭；搜捕；抢劫; v. 对…进行突然袭击', '/reid | reɪd | red/', 'raid', 5);
INSERT INTO `words` VALUES (27411, 'Several passengers were leaning against the ship’s rail.', 'n. 铁轨；扶手；横杆；围栏; v. 抱怨；责骂', '/reil | reɪl | rel/', 'rail', 5);
INSERT INTO `words` VALUES (27412, 'The supplies were sent on the railroad.', 'v. 由铁道运输；铺设铁路；以捏造不实之罪使入狱; n. 铁路；铁路公司', '/\'reilrəud | \'reɪlrəʊd | \'relrod/', 'railroad', 5);
INSERT INTO `words` VALUES (27413, 'a railway company', 'n. 铁路; vt. 由铁道运输', '/\'reɪlweɪ | \'relwe/', 'railway', 5);
INSERT INTO `words` VALUES (27414, 'a night of wind and rain', 'n. 雨；下雨；雨天；雨季; v. 下雨；降雨', '/rein | reɪn/', 'rain', 5);
INSERT INTO `words` VALUES (27415, '...silk and satin in every shade of the rainbow.', 'n. 彩虹；五彩缤纷的排列；幻想; adj. 五彩缤纷的；彩虹状的; vt. 使呈彩虹状；如彩虹般装饰; vi. 呈彩虹状', '/\'reinbəu | \'reɪnbəʊ | \'renbo/', 'rainbow', 5);
INSERT INTO `words` VALUES (27416, 'The searchlight raked the open ground around the prison.', 'v. 搜索；用耙子耙；掠过，擦过; n. 耙子；斜度；钱耙；放荡的人，浪子', '/[reik] | reɪk | rek/', 'rake', 5);
INSERT INTO `words` VALUES (27417, 'After a shaky start, he rallied and won the title in style.', 'v. 团结；重整；恢复；（网球等）连续对打; n. 集会；回复；公路赛车会', '/\'ræli | \'rælɪ/', 'rally', 5);
INSERT INTO `words` VALUES (27418, 'The company has introduced random drug testing of its employees.', 'adj. [数] 随机的；任意的；胡乱的; n. 随意; adv. 胡乱地', '/\'rændəm/', 'random', 5);
INSERT INTO `words` VALUES (27419, 'a temperature range of 72-85˚', 'n. 范围；幅度；排；山脉; v. （在内）变动；平行，列为一行；延伸；漫游；射程达到', '/reɪn(d)ʒ | rendʒ/', 'range', 5);
INSERT INTO `words` VALUES (27420, 'He was sentenced to prison and stripped of his rank (= had his rank taken from him ) .', 'n. 排；等级；军衔；队列; adj. 讨厌的；恶臭的；繁茂的; v. 排列；把…分等', '/ræŋk/', 'rank', 5);
INSERT INTO `words` VALUES (27421, 'She was woken by a sharp rap on the door.', 'v. 抢走；轻敲；敲击致使；使着迷; n. 轻敲', '/ræp/', 'rap', 5);
INSERT INTO `words` VALUES (27422, 'Police are investigating a series of violent rapes in the town.', 'n. 强奸，掠夺；[园艺] 油菜；葡萄渣; v. 强奸；掠夺，抢夺', '/reip | reɪp | rep/', 'rape', 5);
INSERT INTO `words` VALUES (27423, 'The patient made a rapid recovery.', 'adj. 迅速的，急促的；飞快的；险峻的; n. 急流；高速交通工具，高速交通网', '/\'ræpid | \'ræpɪd/', 'rapid', 5);
INSERT INTO `words` VALUES (27424, 'This species of plant is becoming increasingly rare.', 'adj. 稀有的， 难得的， 珍奇的；稀薄的， 稀疏的', '/reə | rɛr/', 'rare', 5);
INSERT INTO `words` VALUES (27425, 'They battled against other Indian tribes, but rarely fought with the whites.', 'adv. 很少， 难得； 稀有地', '/\'reəli | \'rɛrli/', 'rarely', 5);
INSERT INTO `words` VALUES (27426, 'Please Jessie, don’t do anything rash.', 'adj. 轻率的；鲁莽的；不顾后果的; n. [皮肤] 皮疹；突然大量出现的事物', '/ræʃ/', 'rash', 5);
INSERT INTO `words` VALUES (27427, 'This was demonstrated in a laboratory experiment with rats.', 'n. 鼠 <', '/ræt/', 'rat', 5);
INSERT INTO `words` VALUES (27428, 'Immediately his heart rate (= the number of beats per minute ) increased.', 'n. 比率，率；速度；价格；等级; v. 认为；估价；责骂', '/reit | reɪt | ret/', 'rate', 5);
INSERT INTO `words` VALUES (27429, 'From the database snapshot, note the counters in Listing 3 and monitor the ratio among these counters.', 'n. 比率，比例', '/\'reiʃiəu, -ʃəu | \'reɪʃɪəʊ | \'reʃɪo/', 'ratio', 5);
INSERT INTO `words` VALUES (27430, 'Parents need to be fully informed so they can make a rational decision.', 'adj. 合理的；理性的; n. 有理数', '/\'ræʃənəl | \'ræʃ(ə)n(ə)l | \'ræʃnəl/', 'rational', 5);
INSERT INTO `words` VALUES (27431, 'raw meat', 'adj. 生的；未加工的；阴冷的；刺痛的；擦掉皮的；无经验的；（在艺术等方面）不成熟的; n. 擦伤处; vt. 擦伤', '/rɔ: | rɔː | rɔ/', 'raw', 5);
INSERT INTO `words` VALUES (27432, 'BATHROOMS: A man has five items in his bathroom: a toothbrush, shaving cream, razor, a bar of soap, and a towel from the Holiday Inn.', 'v. 剃，用剃刀刮; n. 剃刀', '/\'reizə | \'reɪzə | \'rezɚ/', 'razor', 5);
INSERT INTO `words` VALUES (27433, 'He reacted angrily to the suggestion that he had lied.', 'v. 反应,起作用;(against)反对,起反作用', '/ri\'ækt, ri:- | rɪ\'ækt | ri\'ækt/', 'react', 5);
INSERT INTO `words` VALUES (27434, 'The book will appeal to young readers.', 'n. 读者；阅读器；读物', '/\'ri:də | \'riːdə | \'ridɚ/', 'reader', 5);
INSERT INTO `words` VALUES (27435, 'Jack readily agreed to help.', 'adv. 容易地；乐意地；无困难地', '/\'redili | \'redɪlɪ | \'rɛdɪli/', 'readily', 5);
INSERT INTO `words` VALUES (27436, 'Come on. Aren’t you ready yet?', 'adj. 准备好；现成的；迅速的；情愿的；快要…的; n. 现款；预备好的状态; adv. 迅速地；预先; v. 使准备好', '/\'redi | \'redɪ | \'rɛdi/', 'ready', 5);
INSERT INTO `words` VALUES (27437, 'In the first half they realise their boss is exploiting them and begin to understand the theory of surplus value.', 'v. 认识到，明白', '/\'riəlaiz, \'ri:- | \'rɪəlaɪz/', 'realise', 5);
INSERT INTO `words` VALUES (27438, 'Is this a realistic target?', 'adj. 现实的；现实主义的；逼真的；实在论的', '/,riə\'listik, ,ri:- | rɪə\'lɪstɪk | ,riə\'lɪstɪk/', 'realistic', 5);
INSERT INTO `words` VALUES (27439, 'the distinction between fantasy and reality', 'n. 现实；实际；真实', '/ri\'æləti, ri:- | rɪ\'ælɪtɪ | rɪ\'æləti/', 'reality', 5);
INSERT INTO `words` VALUES (27440, 'the spiritual realm', 'n. 领域，范围；王国', '/relm | rɛlm/', 'realm', 5);
INSERT INTO `words` VALUES (27441, 'You\'ll soon begin to reap the benefits of being fitter.', 'v. 收获，获得；收割; n. (Reap)人名；(英)里普', '/ri:p | riːp | rip/', 'reap', 5);
INSERT INTO `words` VALUES (27442, 'She reared sixteen children, six her own and ten her husband\'s.', 'v. 培养；树立；栽种; adv. 向后；在后面; adj. 后方的；后面的；背面的; n. 后面；屁股；后方部队', '/riə | rɪə | rɪr/', 'rear', 5);
INSERT INTO `words` VALUES (27443, 'a reasonable request', 'adj. 合理的，公道的；通情达理的', '/\'ri:zənəbl | \'riːz(ə)nəb(ə)l | \'riznəbl/', 'reasonable', 5);
INSERT INTO `words` VALUES (27444, 'Teachers reassured anxious parents.', 'v. 使…安心，使消除疑虑', '/,ri:ə\'ʃuə | riːə\'ʃʊə | ,riə\'ʃʊr/', 'reassure', 5);
INSERT INTO `words` VALUES (27445, 'Voters rebelled against high property taxes.', 'v. 反叛；反抗；造反; n. 反叛者；叛徒; adj. 反抗的；造反的', '/\'rebəl, ri\'bel | \'reb(ə)l | rɪ\'bɛl/', 'rebel', 5);
INSERT INTO `words` VALUES (27446, 'an armed rebellion', 'n. 叛乱；反抗；谋反；不服从', '/ri\'beljən | rɪ\'beljən | rɪ\'bɛljən/', 'rebellion', 5);
INSERT INTO `words` VALUES (27447, 'You don’t happen to recall his name, do you?', 'v. 回忆,回想;撤消,收回', '/ri\'kɔ:l, \'ri:kɔ:l | rɪ\'kɔːl | \'rikɔl/', 'recall', 5);
INSERT INTO `words` VALUES (27448, 'The flood waters finally began to recede in November.', 'v. 退回,后退;收回,撤回;跌落,缩减,贬值', '/rɪ\'siːd | rɪ\'sid/', 'recede', 5);
INSERT INTO `words` VALUES (27449, 'Keep your receipt in case you want to bring it back.', 'n. 收据,收条;收到,接到', '/ri\'si:t | rɪ\'siːt | rɪ\'sit/', 'receipt', 5);
INSERT INTO `words` VALUES (27450, 'All the children will receive a small gift.', 'v. 收到,接到;遭受,受到;接待,接见', '/ri\'si:v | rɪ\'siːv | rɪ\'siv/', 'receive', 5);
INSERT INTO `words` VALUES (27451, 'Irving’s most recent book', 'adj. 最近的；近代的', '/\'ri:sənt | \'riːs(ə)nt | \'risnt/', 'recent', 5);
INSERT INTO `words` VALUES (27452, 'She was unsure of her reception after everything that had happened.', 'n. 接待,招待会;接收,接受,接收效果', '/ri\'sepʃən | rɪ\'sepʃ(ə)n | rɪ\'sɛpʃən/', 'reception', 5);
INSERT INTO `words` VALUES (27453, 'the economic recession of the early 1980s', 'n. 衰退， 衰退期A', '/rɪ\'seʃn | rɪ\'sɛʃən/', 'recession', 5);
INSERT INTO `words` VALUES (27454, 'a recipe book', 'n. 烹饪法,食谱;诀窍,方法', '/\'resɪpɪ | \'rɛsəpi/', 'recipe', 5);
INSERT INTO `words` VALUES (27455, '...the largest recipient of U.S. foreign aid.', 'adj. 接受的,感受性强的; n. 接受者,感受者,容器', '/ri\'sipiənt | rɪ\'sɪpɪənt/', 'recipient', 5);
INSERT INTO `words` VALUES (27456, 'He spoke of the necessity for a reciprocal relationship that would be useful for all sides.', 'adj. 相互的,往复的,互利的', '/ri\'siprəkəl | rɪ\'sɪprək(ə)l | rɪ\'sɪprəkl/', 'reciprocal', 5);
INSERT INTO `words` VALUES (27457, 'She recited a poem that she had learnt at school.', 'v. 背诵；叙述；列举', '/ri\'sait | rɪ\'saɪt/', 'recite', 5);
INSERT INTO `words` VALUES (27458, 'He was accused of causing death by reckless driving .', 'adj. 鲁莽的，不顾后果的；粗心大意的; n. (Reckless)人名；(英)雷克利斯', '/\'reklis | \'reklɪs | \'rɛkləs/', 'reckless', 5);
INSERT INTO `words` VALUES (27459, '‘There’s nothing we can do about it.’ ‘You reckon (= used to express doubt or disagreement ) ?’', 'v. 测算，估计；认为；计算', '/\'rekən | \'rek(ə)n | \'rɛkən/', 'reckon', 5);
INSERT INTO `words` VALUES (27460, 'You may be entitled to reclaim some tax.', 'v. 开拓；回收再利用；改造某人，使某人悔改; n. 改造，感化；再生胶', '/ri\'kleim | rɪ\'kleɪm | rɪ\'klem/', 'reclaim', 5);
INSERT INTO `words` VALUES (27461, NULL, 'vt. 认出， 识别；承认', '/\'rekəgnaɪz/', 'recognise', 5);
INSERT INTO `words` VALUES (27462, 'He stared at her, but there was no sign of recognition .', 'n. 认出,辨认;承认', '/,rekəg\'niʃən | rekəg\'nɪʃ(ə)n | ,rɛkəɡ\'nɪʃən/', 'recognition', 5);
INSERT INTO `words` VALUES (27463, 'I didn’t recognize you in your uniform.', 'v. (recognise)认出,承认,公认,赏识,表扬', '/\'rekəɡnaiz | \'rekəɡnaɪz | ˈrɛkəɡˌnaɪz/', 'recognize', 5);
INSERT INTO `words` VALUES (27464, 'All I recollect is a grey sky.', 'v. 回忆,想起,记起,忆起,记得', '/,rekə\'lekt | \'rɛkə\'lɛkt/', 'recollect', 5);
INSERT INTO `words` VALUES (27465, 'Doctors strongly recommend that fathers should be present at their baby’s birth.', 'vt. 推荐， 介绍；劝告， 建议', '/ˌrekə\'mend | \'rɛkə\'mɛnd/', 'recommend', 5);
INSERT INTO `words` VALUES (27466, 'The possibility remains that the two theories may be reconciled.', 'v. 使一致；使和解；调停，调解；使顺从', '/\'rekənsail | \'rek(ə)nsaɪl | \'rɛkənsaɪl/', 'reconcile', 5);
INSERT INTO `words` VALUES (27467, 'Her husband made her record every penny she spent.', 'v. 记录，记载；标明；将录音; n. 档案，履历；唱片；最高纪录; adj. 创纪录的', '/ri\'kɔ:d, \'rekɔ:d | (for v.)rɪˈkɔːd; (for n.) ˈrekɔːd | (for v.) rɪˈkɔrd; (for n. adj.) ˈrɛkɚd/', 'record', 5);
INSERT INTO `words` VALUES (27468, 'Rodney put the recorder on the desk top and pushed the play button.', 'n. 录音机；记录器；记录员；八孔直笛', '/ri\'kɔ:də | rɪ\'kɔːdə | rɪ\'kɔrdɚ/', 'recorder', 5);
INSERT INTO `words` VALUES (27469, 'Four paintings stolen from the gallery have been recovered.', 'v. 收回;(from)恢复,痊愈;重新获得', '/ri\'kʌvə | rɪ\'kʌvə | rɪ\'kʌvɚ/', 'recover', 5);
INSERT INTO `words` VALUES (27470, 'Hopes of economic recovery are fading.', 'n. 痊愈,复元;重获,恢复', '/ri\'kʌvəri | rɪ\'kʌv(ə)rɪ | rɪ\'kʌvəri/', 'recovery', 5);
INSERT INTO `words` VALUES (27471, 'His only recreations are drinking beer and watching football.', 'n. 娱乐,消遣', '/,rekri\'eiʃən, -kri:- | ,rekrɪ\'eɪʃ(ə)n | ,rɛkrɪ\'eʃən/', 'recreation', 5);
INSERT INTO `words` VALUES (27472, 'New recruits are sent to the Atlanta office for training.', 'n. 招聘；新兵；新成员; v. 补充；聘用；征募；使…恢复健康', '/ri\'kru:t | rɪ\'kruːt | rɪ\'krut/', 'recruit', 5);
INSERT INTO `words` VALUES (27473, 'Suppose the width of a rectangle is x metres.', 'n. [数]矩形, 长方形', '/\'rek,tæŋɡl | \'rektæŋg(ə)l | \'rɛktæŋɡl/', 'rectangle', 5);
INSERT INTO `words` VALUES (27474, 'I did my best to rectify the situation, but the damage was already done.', 'v. 纠正,整顿, [化]精馏', '/\'rektifai | \'rektɪfaɪ | \'rɛktɪfaɪ/', 'rectify', 5);
INSERT INTO `words` VALUES (27475, 'There is a danger that the disease may recur.', 'v. (尤指不好的事)一再发生；重现', '/ri\'kə: | rɪ\'kɜː | rɪ\'kɝ/', 'recur', 5);
INSERT INTO `words` VALUES (27476, 'The objective would be to recycle 98 percent of domestic waste.', 'v&n. 再循环,重复利用', '/,ri:\'saikl | riː\'saɪk(ə)l | ,ri\'saɪkl/', 'recycle', 5);
INSERT INTO `words` VALUES (27477, 'I like the way the artist uses red in this painting.', 'n. 红色，红颜料；赤字; adj. 红色的；红肿的，充血的', '/red | rɛd/', 'red', 5);
INSERT INTO `words` VALUES (27478, 'He spent the rest of the game trying to redeem himself after a first-minute mistake.', 'vt. 赎回；挽回；救赎', '/rɪ\'diːm | rɪ\'dim/', 'redeem', 5);
INSERT INTO `words` VALUES (27479, 'The governor announced a new plan to reduce crime.', 'v. 减少,缩小;简化,还原', '/ri\'dju:s, -\'du:s | rɪ\'djuːs | rɪ\'dʊs/', 'reduce', 5);
INSERT INTO `words` VALUES (27480, 'strategies for noise reduction', 'n. 减小,减少,缩小', '/rɪ\'dʌkʃ(ə)n | rɪ\'dʌkʃən/', 'reduction', 5);
INSERT INTO `words` VALUES (27481, 'Seventy factory workers were made redundant in the resulting cuts.', 'adj. 多余的，过剩的；被解雇的，失业的；冗长的，累赘的', '/ri\'dʌndənt | rɪ\'dʌnd(ə)nt | rɪ\'dʌndənt/', 'redundant', 5);
INSERT INTO `words` VALUES (27482, 'Reeds grew in clumps all along the river bank.', 'n. [作物] 芦苇；簧片；牧笛；不可依靠的人; vt. 用芦苇盖；用芦苇装饰', '/ri:d | riːd | rid/', 'reed', 5);
INSERT INTO `words` VALUES (27483, 'Andy reeled away from the bar and knocked over his stool.', 'v. 卷；眩晕；蹒跚地走；退缩; n. 蹒跚；眩晕；旋转', '/ri:l, riəl | riːl | ril/', 'reel', 5);
INSERT INTO `words` VALUES (27484, 'In his speech, he referred to a recent trip to Canada.', 'v. 参考；涉及；提到；查阅', '/ri\'fə: | rɪ\'fɜː | rɪ\'fɝ/', 'refer', 5);
INSERT INTO `words` VALUES (27485, 'The official at the American embassy asked me for two references.', 'n. 参考，参照；涉及，提及；参考书目；介绍信；证明书; v. 引用', '/\'refərəns | \'ref(ə)r(ə)ns | \'rɛfrəns/', 'reference', 5);
INSERT INTO `words` VALUES (27486, 'oil refining', 'v. 精炼,精制,提纯;使文雅,使高尚', '/ri\'fain | rɪ\'faɪn/', 'refine', 5);
INSERT INTO `words` VALUES (27487, 'The drop in consumer spending reflects concern about the economy.', 'v. 反映；反射，照出；表达；显示;反省', '/rɪ\'flekt | rɪ\'flɛkt/', 'reflect', 5);
INSERT INTO `words` VALUES (27488, 'Can you see your reflection in the glass?', 'n. 反射；沉思；映象', '/re\'flekʃən | rɪ\'flekʃ(ə)n | rɪ\'flɛkʃən/', 'reflection', 5);
INSERT INTO `words` VALUES (27489, NULL, 'n. 映像， 倒影；反省， 沉思', '/rɪ\'flekʃn | rɪ\'flɛkʃən/', 'reflexion', 5);
INSERT INTO `words` VALUES (27490, 'plans to radically reform the tax system', 'v&n. 改革,改造,改良', '/ri\'fɔ:m | rɪ\'fɔːm | rɪ\'fɔrm/', 'reform', 5);
INSERT INTO `words` VALUES (27491, 'Mrs. Hardie refrained from making any comment.', 'v. 节制，克制；避免；制止; n. 叠句，副歌；重复', '/,ri:\'frein | rɪ\'freɪn | rɪ\'fren/', 'refrain', 5);
INSERT INTO `words` VALUES (27492, 'A shower will refresh you.', 'v. 更新；使……恢复；使……清新；消除……的疲劳', '/ri\'freʃ, ri:- | rɪ\'freʃ | ri\'frɛʃ/', 'refresh', 5);
INSERT INTO `words` VALUES (27493, 'Refreshments will be served after the meeting.', 'n. 点心；起提神作用的东西；精力恢复', '/ri\'freʃmənt, ri:- | rɪ\'freʃm(ə)nt | ri\'frɛʃmənt/', 'refreshment', 5);
INSERT INTO `words` VALUES (27494, 'a wildlife refuge', 'n. 避难；避难所；庇护; vt. 给予…庇护；接纳…避难; vi. 避难；逃避', '/\'refju:dʒ | \'refjuːdʒ | \'rɛfjʊdʒ/', 'refuge', 5);
INSERT INTO `words` VALUES (27495, 'Refugees were streaming across the border.', 'n. 难民，避难者；流亡者，逃亡者', '/,refju\'dʒi:, \'refjudʒi: | refjʊ\'dʒiː | \'rɛfjʊdʒi/', 'refugee', 5);
INSERT INTO `words` VALUES (27496, 'I took the radio back, and they refunded my money .', 'v. 退还；偿还，归还; n. 退款；偿还，偿还额', '/ri\'fʌnd | ˈriːfʌnd | ˈrifʌnd/', 'refund', 5);
INSERT INTO `words` VALUES (27497, 'Her country suffered through her refusal to accept change.', 'n. 拒绝,回绝', '/ri\'fju:zəl, ri:- | rɪ\'fjuːz(ə)l | rɪ\'fjuzl/', 'refusal', 5);
INSERT INTO `words` VALUES (27498, 'She asked him to leave, but he refused.', 'v. 拒绝,谢绝; n. 废物,垃圾', '/ri\'fju:z, ri:- | rɪ\'fjuːz | ri\'fjʊz/', 'refuse', 5);
INSERT INTO `words` VALUES (27499, 'It was the kind of rumour that it is impossible to refute.', 'v. 反驳，驳斥；驳倒', '/ri\'fju:t, ri:- | rɪ\'fjuːt | ri\'fjʊt/', 'refute', 5);
INSERT INTO `words` VALUES (27500, 'My husband sends his regards .', 'n. 注意；尊重；问候；凝视; v. 注重，考虑；看待；尊敬；把…看作；与…有关', '/ri\'ɡɑ:d, ri:- | rɪ\'gɑːd | rɪ\'ɡɑrd/', 'regard', 5);
INSERT INTO `words` VALUES (27501, 'Regarding your recent inquiry, I have enclosed a copy of our new brochure.', 'prep. 关于，至于', '/ri\'ɡɑ:diŋ, ri:- | rɪ\'gɑːdɪŋ | rɪ\'ɡɑrdɪŋ/', 'regarding', 5);
INSERT INTO `words` VALUES (27502, 'Despite her recent surgery she has been carrying on regardless.', 'adj. 不管的；不顾的；不注意的; adv. 不顾后果地；不管怎样，无论如何；不惜费用地', '/rɪ\'gɑːdlɪs | rɪ\'ɡɑrdləs/', 'regardless', 5);
INSERT INTO `words` VALUES (27503, 'The regime got rid of most of its opponents.', 'n. 政权，政体；社会制度；管理体制', '/rei\'ʒi:m, ri-, ri\'dʒi:m | reɪ\'ʒiːm | re\'ʒim/', 'regime', 5);
INSERT INTO `words` VALUES (27504, 'efforts to bring peace to the region', 'n. 地区；范围；部位', '/\'ri:dʒən | \'riːdʒ(ə)n | \'ridʒən/', 'region', 5);
INSERT INTO `words` VALUES (27505, 'The tanker is registered in Rotterdam.', 'v. 登记；注册；记录；挂号邮寄；把…挂号；正式提出; n. 登记；注册；记录；寄存器；登记簿', '/\'redʒistə | \'redʒɪstə | \'rɛdʒɪstɚ/', 'register', 5);
INSERT INTO `words` VALUES (27506, 'It is with great regret that I must decline your offer.', 'n. 遗憾；抱歉；悲叹; v. 后悔；惋惜；哀悼', '/ri\'ɡret | rɪ\'gret | rɪ\'ɡrɛt/', 'regret', 5);
INSERT INTO `words` VALUES (27507, 'The company holds regular meetings with employees.', 'adj. 定期的；有规律的；合格的；整齐的；普通的; n. 常客；正式队员；中坚分子; adv. 定期地；经常地', '/\'reɡjulə | \'regjʊlə | \'rɛgjəlɚ/', 'regular', 5);
INSERT INTO `words` VALUES (27508, 'strict rules regulating the use of chemicals in food', 'v. 调节，规定；控制；校准；有系统的管理', '/\'reɡjuleit | \'regjʊleɪt | \'rɛɡjulet/', 'regulate', 5);
INSERT INTO `words` VALUES (27509, 'There seem to be so many rules and regulations these days.', 'n. 管理；规则；校准; adj. 规定的；平常的', '/,reɡju\'leiʃən | regjʊ\'leɪʃ(ə)n | ˌrɛɡjəˈleʃən/', 'regulation', 5);
INSERT INTO `words` VALUES (27510, 'a wedding rehearsal', 'n. 排演；预演；练习；训练；叙述', '/ri\'hə:səl | rɪ\'hɜːs(ə)l | rɪ\'hɝsl/', 'rehearsal', 5);
INSERT INTO `words` VALUES (27511, 'I think we need to rehearse the first scene again.', 'v. 排练；预演', '/rɪ\'hɜːs | rɪ\'hɝs/', 'rehearse', 5);
INSERT INTO `words` VALUES (27512, 'For several minutes confusion reigned .', 'v. 统治；支配；盛行；君临; n. 统治；统治时期；支配', '/rein | reɪn | ren/', 'reign', 5);
INSERT INTO `words` VALUES (27513, 'Cord held the reins while the stallion tugged and snorted.', 'n. 缰绳；驾驭；统治；支配; v. 控制；驾驭；勒住', '/rein | reɪn | ren/', 'rein', 5);
INSERT INTO `words` VALUES (27514, 'The film reinforces the idea that women should be pretty and dumb.', 'v. 加强，加固；强化；补充; n. 加强；加固物；加固材料', '/,ri:in\'fɔ:s | riːɪn\'fɔːs | ,riɪn\'fɔrs/', 'reinforce', 5);
INSERT INTO `words` VALUES (27515, 'Sarah rejected her brother’s offer of help.', 'v. 拒绝,抵制,丢弃,排斥,退掉; n. 落选者', '/ri\'dʒekt | rɪ\'dʒekt | rɪ\'dʒɛkt/', 'reject', 5);
INSERT INTO `words` VALUES (27516, 'This should be wonderful news for... well, for all women born in 1979 and 1980, who can rejoice in the realisation that they are – or are about to be – at their peak.', 'v. 高兴；庆祝', '/ri\'dʒɔis | rɪ\'dʒɒɪs | rɪ\'dʒɔɪs/', 'rejoice', 5);
INSERT INTO `words` VALUES (27517, 'I don’t understand how the two ideas relate.', 'vt. 叙述， 讲述；使联系', '/rɪ\'leɪt | rɪ\'let/', 'relate', 5);
INSERT INTO `words` VALUES (27518, 'The price the meat is sold for bears no relation to (= is not connected to ) the price the farmer receives.', 'n. 关系；叙述；故事；亲属关系', '/ri\'leiʃən | rɪ\'leɪʃ(ə)n | rɪ\'leʃən/', 'relation', 5);
INSERT INTO `words` VALUES (27519, 'He’s never had a sexual relationship before.', 'n. 关系；关联', '/ri\'leiʃənʃip | rɪ\'leɪʃ(ə)nʃɪp | rɪ\'leʃən\'ʃɪp/', 'relationship', 5);
INSERT INTO `words` VALUES (27520, 'The relative merits of both approaches have to be considered.', 'adj. 相对的；有关系的；成比例的; n. 亲戚；相关物；[语] 关系词；亲缘植物', '/\'relətiv | \'relətɪv | \'rɛlətɪv/', 'relative', 5);
INSERT INTO `words` VALUES (27521, 'Einstein put forward his new theory of relativity.', 'n. 相对论；相关性；相对性', '/,relə\'tivəti | relə\'tɪvɪtɪ | ,rɛlə\'tɪvəti/', 'relativity', 5);
INSERT INTO `words` VALUES (27522, 'I just want to sit down and relax.', 'v. 放松，休息；松懈，松弛；变从容；休养', '/ri\'læks | rɪ\'læks/', 'relax', 5);
INSERT INTO `words` VALUES (27523, 'The broadcasts were relayed by satellite.', 'v. 转播；接替; n. [电] 继电器；接替，接替人员；驿马', '/\'ri:lei, ri\'lei | \'riːleɪ | rɪ\'le/', 'relay', 5);
INSERT INTO `words` VALUES (27524, 'Police arrested several men, who were later released.', 'v. 释放；发射；让与；允许发表; n. 释放；发布；让与', '/ri\'li:s | rɪ\'liːs | rɪ\'lis/', 'release', 5);
INSERT INTO `words` VALUES (27525, 'Relevant documents were presented in court.', 'adj. 相关的；切题的；中肯的；有重大关系的；有意义的，目的明确的', '/ˈreləvənt | \'rɛləvənt/', 'relevant', 5);
INSERT INTO `words` VALUES (27526, 'a birth control method that is cheap and reliable', 'adj. 可靠的；可信赖的; n. 可靠的人', '/ri\'laiəbl | rɪ\'laɪəb(ə)l | rɪ\'laɪəbl/', 'reliable', 5);
INSERT INTO `words` VALUES (27527, 'the country’s heavy reliance on trade', 'n. 信赖；信心；受信赖的人或物', '/ri\'laiəns | rɪ\'laɪəns/', 'reliance', 5);
INSERT INTO `words` VALUES (27528, 'Marijuana can provide pain relief for some cancer patients.', 'n. 救济；减轻，解除；安慰；浮雕', '/rɪ\'liːf | rɪ\'lif/', 'relief', 5);
INSERT INTO `words` VALUES (27529, 'Drugs helped to relieve the pain.', 'v. 解除，减轻；使不单调乏味；换…的班；解围；使放心', '/ri\'li:v | rɪ\'liːv | rɪ\'liv/', 'relieve', 5);
INSERT INTO `words` VALUES (27530, 'The U.S. Constitution promises freedom of religion.', 'n. 宗教,信仰', '/ri\'lidʒən | rɪ\'lɪdʒ(ə)n | rɪ\'lɪdʒən/', 'religion', 5);
INSERT INTO `words` VALUES (27531, 'I don’t share her religious beliefs .', 'adj. 宗教的,信教的,虔诚的', '/ri\'lidʒəs | rɪ\'lɪdʒəs/', 'religious', 5);
INSERT INTO `words` VALUES (27532, 'a hot dog with mustard and relish', 'n. 滋味；风味；食欲；开胃小菜；含义；调味品; v. 盼望;期待;享受; 品味；喜爱；给…加佐料', '/\'relɪʃ | \'rɛlɪʃ/', 'relish', 5);
INSERT INTO `words` VALUES (27533, 'She gave a reluctant smile.', 'adj. 不情愿的；勉强的；顽抗的', '/ri\'lʌktənt | rɪ\'lʌkt(ə)nt | rɪ\'lʌktənt/', 'reluctant', 5);
INSERT INTO `words` VALUES (27534, 'They relied heavily on the advice of their professional advisers.', 'v. 依靠；信赖', '/ri\'lai | rɪ\'laɪ/', 'rely', 5);
INSERT INTO `words` VALUES (27535, 'Please remain seated until all the lights are on.', 'v. 保持；依然；留下；剩余；逗留；残存; n. 遗迹；剩余物，残骸', '/ri\'mein | rɪ\'meɪn | rɪ\'men/', 'remain', 5);
INSERT INTO `words` VALUES (27536, 'The remainder must be paid by the end of June.', 'n. [数] 余数，残余；剩余物；其余的人; adj. 剩余的；吃剩的; v. 廉价出售；削价出售', '/ri\'meində | rɪ\'meɪndə | rɪ\'mendɚ/', 'remainder', 5);
INSERT INTO `words` VALUES (27537, 'extensive Roman remains (= of ancient buildings ) at Arles', 'n. 残余；遗骸', '/ri\'meinz | rɪ\'meɪnz | rɪ\'menz/', 'remains', 5);
INSERT INTO `words` VALUES (27538, 'Unfortunately, a local journalist overheard the remark.', 'n. (about,on)评语,意见; v. (on)评论;注意到', '/ri\'mɑ:k | rɪ\'mɑːk | rɪ\'mɑrk/', 'remark', 5);
INSERT INTO `words` VALUES (27539, 'She has made remarkable progress.', 'adj. 值得注意的;显著的,异常的,非凡的', '/ri\'mɑ:kəbl | rɪ\'mɑːkəb(ə)l | rɪ\'mɑrkəbl/', 'remarkable', 5);
INSERT INTO `words` VALUES (27540, 'To remedy the situation, the water must be chemically treated.', 'v. 补救；治疗；纠正; n. 补救；治疗；赔偿', '/\'remidi | \'remɪdɪ | \'rɛmədi/', 'remedy', 5);
INSERT INTO `words` VALUES (27541, 'Do you remember Rosa Davies?', 'v. 记住;(to)转达问候,代…致意,代…问好', '/ri\'membə | rɪ\'membə | rɪ\'mɛmbɚ/', 'remember', 5);
INSERT INTO `words` VALUES (27542, 'Yes, I’ll be there. Thanks for reminding me.', 'v. 提醒；使想起', '/ri\'maind | rɪ\'maɪnd/', 'remind', 5);
INSERT INTO `words` VALUES (27543, 'Beneath the present church were remnants of Roman flooring.', 'n. 剩余; adj. 剩余的', '/\'remnənt | \'rɛmnənt/', 'remnant', 5);
INSERT INTO `words` VALUES (27544, 'a remote border town', 'adj. 远的,遥远的,疏远的,偏僻的,细微的', '/ri\'məut | rɪ\'məʊt | rɪ\'mot/', 'remote', 5);
INSERT INTO `words` VALUES (27545, 'stain removal', 'n. 移动,迁居;除去', '/ri\'mu:vəl | rɪ\'muːv(ə)l | rɪ\'muvl/', 'removal', 5);
INSERT INTO `words` VALUES (27546, 'He removed his hat and gloves.', 'v. 移动,脱掉,调动,免职', '/ri\'mu:v | rɪ\'muːv | rɪ\'muv/', 'remove', 5);
INSERT INTO `words` VALUES (27547, '...the Renaissance masterpieces in London\'s galleries.', 'n. 文艺复兴（欧洲14至17世纪）', '/\'rɛnəsɑns | rɪ\'neɪsəns/', 'renaissance', 5);
INSERT INTO `words` VALUES (27548, 'an obligation to render assistance to those in need', 'v. 致使；提出；实施；着色；以…回报; n. 打底；交纳；粉刷', '/\'rendə | \'rɛndɚ/', 'render', 5);
INSERT INTO `words` VALUES (27549, 'Local people have renewed their efforts to save the school.', 'v. 使更新；续借；续费；复兴；重申', '/rɪ\'njuː | rɪ\'nʊ/', 'renew', 5);
INSERT INTO `words` VALUES (27550, 'The hotel has been renovated and redecorated.', 'v. 更新；修复；革新；刷新', '/\'renəuveit | \'renəveɪt | \'rɛnəvet/', 'renovate', 5);
INSERT INTO `words` VALUES (27551, 'I pay the rent at the beginning of every month.', 'n. 租金; v. 出租；租用；租借', '/rent | rɛnt/', 'rent', 5);
INSERT INTO `words` VALUES (27552, 'Dad was up the ladder, repairing the roof.', 'v. 修理；修复; n. 修理，修补；修补部位', '/ri\'pεə | rɪ\'peə | rɪ\'pɛr/', 'repair', 5);
INSERT INTO `words` VALUES (27553, 'I’d like to buy them something to repay all their kindness.', 'v. 偿还；报答；报复', '/ri:\'pei, ri- | riː\'peɪ; rɪ- | ri\'pɛi/', 'repay', 5);
INSERT INTO `words` VALUES (27554, 'Repeat the exercises twice a day.', 'v. 重复；复制；背诵; n. 重复；副本', '/ri\'pi:t | rɪ\'piːt | rɪ\'pit/', 'repeat', 5);
INSERT INTO `words` VALUES (27555, 'repeated calls for change', 'adj. 重复的， 再三的 <', '/rɪ\'piːtɪd | ri\'pi:tid/', 'repeated', 5);
INSERT INTO `words` VALUES (27556, 'Graham was repeatedly warned not to work so hard.', 'adv. 反复地；再三地；屡次地', '/ri\'pi:tidli | rɪ\'piːtɪdlɪ | rɪ\'pitɪdli/', 'repeatedly', 5);
INSERT INTO `words` VALUES (27557, 'The smell repelled him.', 'v. 击退；抵制；使厌恶；使不愉快', '/ri\'pel | rɪ\'pel | rɪ\'pɛl/', 'repel', 5);
INSERT INTO `words` VALUES (27558, 'the behavioural repertoire of infants', 'n. 全部节目；计算机指令系统；（美）某人或机器的全部技能', '/\'repətwɑ: | \'repətwɑː | \'rɛpɚ\'twɑr/', 'repertoire', 5);
INSERT INTO `words` VALUES (27559, 'Children used to learn by repetition.', 'n. 重复,反复', '/,repi\'tiʃən | repɪ\'tɪʃ(ə)n | \'rɛpə\'tɪʃən/', 'repetition', 5);
INSERT INTO `words` VALUES (27560, 'I’m replacing Sue on the team.', 'v. 取代，代替；替换，更换；归还，偿还；把…放回原处', '/ri\'pleis | rɪ\'pleɪs | rɪ\'ples/', 'replace', 5);
INSERT INTO `words` VALUES (27561, 'Our old car is badly in need of replacement.', 'n. 更换；复位；代替者；补充兵员', '/ri\'pleismənt | rɪ\'pleɪsm(ə)nt | rɪ\'plesmənt/', 'replacement', 5);
INSERT INTO `words` VALUES (27562, 'I asked Clive where he was going, but he didn’t reply.', 'v. 回答；[法] 答辩；回击; n. 回答；[法] 答辩', '/ri\'plai | rɪ\'plaɪ | rɪ\'plai/', 'reply', 5);
INSERT INTO `words` VALUES (27563, 'Government officials have denied reports of rebel advances.', 'n&v. 报告,汇报;传说,传阅', '/ri\'pɔ:t | rɪ\'pɔːt | rɪ\'pɔrt/', 'report', 5);
INSERT INTO `words` VALUES (27564, 'a news reporter', 'n. 报告人,通讯员;记者,报导者', '/ri\'pɔ:tə | rɪ\'pɔːtə | rɪ\'pɔrtɚ/', 'reporter', 5);
INSERT INTO `words` VALUES (27565, 'Mr Kobayashi was chosen to represent the company at the conference.', 'v. 描述,表示;代表,代理;阐明,说明', '/,repri\'zent | reprɪ\'zent | ,rɛprɪ\'zɛnt/', 'represent', 5);
INSERT INTO `words` VALUES (27566, 'a union representative', 'n. 代表,代理人; adj. (of)典型的,有代表性的', '/,repri\'zentətiv | reprɪ\'zentətɪv | \'rɛprɪ\'zɛntətɪv/', 'representative', 5);
INSERT INTO `words` VALUES (27567, '{\"COLLOINEXA\":[\"sexual repression\"]}', 'n. 抑制，[心理] 压抑；镇压', '/ri\'preʃən | rɪ\'preʃən | rɪ\'prɛʃən/', 'repression', 5);
INSERT INTO `words` VALUES (27568, 'He argued that the reproaches were unfair.', 'n. 责备；耻辱; v. 责备；申斥', '/ri\'prəutʃ | rɪ\'prəʊtʃ | rɪ\'protʃ/', 'reproach', 5);
INSERT INTO `words` VALUES (27569, 'The turtles return to the coast to reproduce.', 'v. 生殖;翻版;繁殖;复制,仿造', '/,ri:prə\'dju:s | riːprə\'djuːs | ,riprə\'dus/', 'reproduce', 5);
INSERT INTO `words` VALUES (27570, 'No matter how dry your skin gets, you will never turn into an alligator or any other type of reptile.', 'n. 爬行动物', '/\'reptaɪl | \'rɛptaɪl/', 'reptile', 5);
INSERT INTO `words` VALUES (27571, 'the former Federal Republic of Germany', 'n. 共和国；共和政体', '/ri\'pʌblik | rɪ\'pʌblɪk/', 'republic', 5);
INSERT INTO `words` VALUES (27572, 'Lower taxes made Republican voters happier with their party.', 'adj. 共和国的；共和政体的；共和主义的；拥护共和政体的; n. 共和主义者', '/ri\'pʌblikən | rɪ\'pʌblɪk(ə)n | rɪ\'pʌblɪkən/', 'republican', 5);
INSERT INTO `words` VALUES (27573, 'Alice Munro has a reputation for being a very depressing writer.', 'n. 名声，名誉；声望', '/,repju\'teiʃən | repjʊ\'teɪʃ(ə)n | ,rɛpju\'teʃən/', 'reputation', 5);
INSERT INTO `words` VALUES (27574, 'Campbell’s broken leg will probably require surgery.', 'v. 需要；要求；命令', '/ri\'kwaiə | rɪ\'kwaɪə | rɪ\'kwaɪr/', 'require', 5);
INSERT INTO `words` VALUES (27575, 'The refugees’ main requirements are food and shelter.', 'n. 要求；必要条件；必需品', '/ri\'kwaiəmənt | rɪ\'kwaɪəm(ə)nt | rɪ\'kwaɪɚmənt/', 'requirement', 5);
INSERT INTO `words` VALUES (27576, 'Survivors of the crash were rescued by helicopter.', 'v. 营救；援救; n. 营救；援救；解救', '/\'reskju: | \'reskjuː | \'rɛskju/', 'rescue', 5);
INSERT INTO `words` VALUES (27577, 'There was a remarkable resemblance between him and Pete.', 'n. 相似,相似性[点,物]', '/ri\'zembləns | rɪ\'zembl(ə)ns | rɪ\'zɛmbləns/', 'resemblance', 5);
INSERT INTO `words` VALUES (27578, 'It’s amazing how closely Brian and Steve resemble each other.', 'v. 像,类似', '/ri\'zembl | rɪ\'zemb(ə)l | rɪ\'zɛmbl/', 'resemble', 5);
INSERT INTO `words` VALUES (27579, 'Paul resented the fact that Carol didn’t trust him.', 'v. 对…表示忿恨,怨恨', '/ri\'zent | rɪ\'zent | rɪ\'zɛnt/', 'resent', 5);
INSERT INTO `words` VALUES (27580, 'a dinner reservation', 'n. 预约，预订；保留', '/,rezə\'veiʃən | rezə\'veɪʃ(ə)n | ,rɛzɚ\'veʃən/', 'reservation', 5);
INSERT INTO `words` VALUES (27581, '$10 million in cash reserves', 'n. 储备，储存；自然保护区；预备队；缄默；[金融] 储备金; v. 储备；保留；预约', '/rɪ\'zɜːv | rɪ\'zɝv/', 'reserve', 5);
INSERT INTO `words` VALUES (27582, 'All these earthquakes happened when the water level in Zipingpu reservoir was low.', 'n. 水库；蓄水池', '/\'rezəvwɑ: | \'rezəvwɑ: (r) | \'rɛzɚ,vɔr/', 'reservoir', 5);
INSERT INTO `words` VALUES (27583, 'the ambassador’s official residence', 'n. 住处,住宅', '/\'rezidəns | \'rezɪd(ə)ns | \'rɛzɪdəns/', 'residence', 5);
INSERT INTO `words` VALUES (27584, 'A resident said, \"I think we should write it down on paper or tell our family members.', 'n. 居民,常住者; adj. 居住的', '/ˈrɛzɪdənt | \'rɛzɪdənt/', 'resident', 5);
INSERT INTO `words` VALUES (27585, 'Josh resigned himself to the long walk home.', 'v. 辞去,辞职,使听从(于),使顺从', '/ri\'zain | rɪ\'zaɪn/', 'resign', 5);
INSERT INTO `words` VALUES (27586, 'They only wanted 3 dollars for it, so how could I resist?', 'v. 抵抗,反抗;抗,忍得住,抵制', '/ri\'zist | rɪ\'zɪst/', 'resist', 5);
INSERT INTO `words` VALUES (27587, 'disease resistance', 'n. (to)抵抗,反抗;抵抗力,阻力;电阻', '/ri\'zistəns | rɪ\'zɪst(ə)ns | rɪ\'zɪstəns/', 'resistance', 5);
INSERT INTO `words` VALUES (27588, 'Some people are very resistant to the idea of exercise.', 'adj. (to)抵抗的,有抵抗力的', '/ri\'zistənt | rɪ\'zɪstənt/', 'resistant', 5);
INSERT INTO `words` VALUES (27589, 'resolute opposition', 'adj. 坚决的,果断的', '/\'rezəlju:t, -lət | \'rezəluːt | \'rɛzəlut/', 'resolute', 5);
INSERT INTO `words` VALUES (27590, 'a resolution calling for a ban on dumping nuclear waste', 'n. 坚决,决心;决定,决议', '/,rezə\'lu:ʃən, -,lju:- | rezə\'luːʃ(ə)n | ,rɛzə\'luʃən/', 'resolution', 5);
INSERT INTO `words` VALUES (27591, 'Barnet was desperate for money to resolve his financial problems.', 'v. 决心;(使)分解,溶解;决议; n. 解决;决心', '/ri\'zɔlv | rɪ\'zɒlv | rɪ\'zɑlv/', 'resolve', 5);
INSERT INTO `words` VALUES (27592, 'Lagoon Reef is one of the best resort hotels.', 'n. 凭借，手段；度假胜地；常去之地; v. 求助，诉诸；常去；采取某手段或方法', '/ri\'zɔ:t | rɪ\'zɔːt | rɪ\'zɔrt/', 'resort', 5);
INSERT INTO `words` VALUES (27593, 'Canada’s vast mineral resources', 'n. 资源，财力；办法；智谋', '/ri\'sɔ:s, -\'zɔ:s, \'ri:s-, \'ri:z- | rɪ\'sɔːs; rɪ\'zɔːs | \'risɔrs/', 'resource', 5);
INSERT INTO `words` VALUES (27594, 'With respect, I think you’re wrong.', 'n&v. 尊敬,尊重; n. 敬意,问候,关系,方面', '/ri\'spekt | rɪ\'spekt | rɪ\'spɛkt/', 'respect', 5);
INSERT INTO `words` VALUES (27595, 'We all went back to our respective homes to wait for news.', 'adj. 各自的,各个的', '/ri\'spektiv | rɪ\'spektɪv | rɪ\'spɛktɪv/', 'respective', 5);
INSERT INTO `words` VALUES (27596, 'They are likely to respond positively to the president\'s request for aid.', 'v. 回答；作出反应；承担责任; n. 应答；唱和', '/ri\'spɔnd | rɪ\'spɒnd | rɪ\'spɑnd/', 'respond', 5);
INSERT INTO `words` VALUES (27597, 'His immediate response was one of disbelief.', 'n. 响应；反应；回答', '/ri\'spɔns | rɪ\'spɒns | rɪ\'spɑns/', 'response', 5);
INSERT INTO `words` VALUES (27598, 'Kelly’s promotion means more money and more responsibility.', 'n. 责任，职责；义务', '/ri.spɔnsə\'biliti | rɪˌspɒnsəˈbɪlətɪ | rɪˌspɑːnsəˈbɪləti/', 'responsibility', 5);
INSERT INTO `words` VALUES (27599, 'We are determined to bring the people responsible to justice.', 'adj. 应负责的， 有责任的；可靠的， 可信赖的；责任重大的， 重要的', '/rɪ\'spɒnsəbl | rɪ\'spɑnsəbl/', 'responsible', 5);
INSERT INTO `words` VALUES (27600, 'If you’re tired, we’ll stop and rest for a while.', 'v. 使休息，使轻松；把…寄托于; n. 休息，静止；休息时间；剩余部分；支架', '/rest | rɛst/', 'rest', 5);
INSERT INTO `words` VALUES (27601, 'He took her out for a five-course dinner in a fancy restaurant.', 'n. 餐馆；[经] 饭店', '/\'restərɔŋ, -rɔnt, -rənt | ˈrɛstəˌrɒŋ; ˈrɛstrɒŋ; -rɒnt | ˈrɛstəˌrɑnt; ˈrɛstərənt; ˈrɛsˌtrɑnt/', 'restaurant', 5);
INSERT INTO `words` VALUES (27602, 'After a few weeks in Marseille, I grew restless and decided to move on.', 'adj. 得不到休息的；不平静的；不安的， 坐立不安的', '/\'restləs | \'rɛstləs/', 'restless', 5);
INSERT INTO `words` VALUES (27603, 'She was hoping that the Mediterranean climate would restore her to full health.', 'v. 恢复；修复；归还', '/ri\'stɔ: | rɪ\'stɔː | rɪ\'stɔr/', 'restore', 5);
INSERT INTO `words` VALUES (27604, 'Renwick restrained a feeling of annoyance.', 'v. 抑制，控制；约束；制止', '/ri\'strein | rɪ\'streɪn | rɪ\'stren/', 'restrain', 5);
INSERT INTO `words` VALUES (27605, 'The police were praised for their restraint in handling the demonstrators.', 'n. 抑制，克制；约束', '/ri\'streint | rɪ\'streɪnt | rɪ\'strent/', 'restraint', 5);
INSERT INTO `words` VALUES (27606, 'The new law restricts the sale of hand guns.', 'v. 限制；约束；限定', '/ri\'strikt | rɪ\'strɪkt/', 'restrict', 5);
INSERT INTO `words` VALUES (27607, 'High unemployment is a direct result of the recession.', 'n. 结果,成绩; v. 结果,致使,导致,由…而造成', '/ri\'zʌlt | rɪ\'zʌlt/', 'result', 5);
INSERT INTO `words` VALUES (27608, 'She is still trying to get over the attack and the resultant injuries.', 'adj. 作为结果而发生的;合成的', '/ri\'zʌltənt | rɪ\'zʌlt(ə)nt | rɪ\'zʌltənt/', 'resultant', 5);
INSERT INTO `words` VALUES (27609, 'What do you do after being a spy? Do you sell insurance? And how do you get a new career when your resumé is blank?', 'n. 简历', '/\'r3sjʊm3ɪ/', 'resumé', 5);
INSERT INTO `words` VALUES (27610, 'Don\'t push for an interview on the spot, but rather explain that you want to let them know of your interest, drop off your resume, and complete an application while you\'re there if possible.', 'n. 个人简历; v. 再继续,重新开始;再用;恢复', '/rezju:\'mei, ri\'zju:m; -\'zu:m | rɪˈzjuːm; ˈrɛzjʊmeɪ/', 'resume', 5);
INSERT INTO `words` VALUES (27611, 'Their products are retailed all over Britain.', 'v. 零售；转述; n. 零售; adv. 以零售方式; adj. 零售的', '/\'ri:teil | \'riːteɪl | \'ritel/', 'retail', 5);
INSERT INTO `words` VALUES (27612, 'You have the right to retain possession of the goods.', 'v. 保持,保留', '/ri\'tein | rɪ\'teɪn | rɪ\'ten/', 'retain', 5);
INSERT INTO `words` VALUES (27613, 'Many people with heart problems suffer from fluid retention.', 'n. 保留；扣留，滞留；记忆力；闭尿', '/ri\'tenʃən | rɪ\'tenʃ(ə)n | rɪ\'tɛnʃən/', 'retention', 5);
INSERT INTO `words` VALUES (27614, 'At the age when most people retire, he is ready to face a new career.', 'v. 退休；撤退；退却; n. 退休；退隐；退兵信号', '/ri\'taiə | rɪ\'taɪə | rɪ\'taɪɚ/', 'retire', 5);
INSERT INTO `words` VALUES (27615, 'He was about to make a sharp retort .', 'n. 反驳，顶嘴；曲颈瓶; v. 反驳，反击', '/ri\'tɔ:t | rɪ\'tɔːt | rɪ\'tɔrt/', 'retort', 5);
INSERT INTO `words` VALUES (27616, 'Napoleon’s retreat from Moscow', 'n. 撤退；休息寓所；撤退; v. 撤退；退避；向后倾', '/ri\'tri:t | rɪ\'triːt | rɪ\'trit/', 'retreat', 5);
INSERT INTO `words` VALUES (27617, 'The new version of the software automatically retrieves digital information.', 'v. [计] 检索；恢复；重新得到; n. [计] 检索；恢复，取回', '/ri\'tri:v | rɪ\'triːv | rɪ\'triv/', 'retrieve', 5);
INSERT INTO `words` VALUES (27618, 'In retrospect, I wonder if we should have done more.', 'v&n. 回顾，回想，追溯[反]foresee', '/\'retrəuspekt | \'retrəspekt | \'rɛtrəspɛkt/', 'retrospect', 5);
INSERT INTO `words` VALUES (27619, 'It was forty five minutes before she returned.', 'v. 返回；报答; n. 返回；归还；回球; adj. 报答的；回程的；返回的', '/ri\'tə:n | rɪ\'tɜːn | rɪ\'tɝn/', 'return', 5);
INSERT INTO `words` VALUES (27620, 'He may be prosecuted for revealing secrets about the security agency.', 'v. 显示；透露；揭露；泄露; n. 揭露；暴露；门侧，窗侧', '/ri\'vi:l | rɪ\'viːl | rɪ\'vil/', 'reveal', 5);
INSERT INTO `words` VALUES (27621, '...the seemingly everlasting revelations about his private life.', 'n. 启示；揭露；出乎意料的事；被揭露的真相', '/,revə\'leiʃən | revə\'leɪʃ(ə)n | \'rɛvə\'leʃən/', 'revelation', 5);
INSERT INTO `words` VALUES (27622, 'The attackers were said to be taking revenge on the 14-year-old, claiming he was a school bully.', 'n. 报复,复仇; v. 替…报仇', '/ri\'vendʒ | rɪ\'ven(d)ʒ | rɪ\'vɛndʒ/', 'revenge', 5);
INSERT INTO `words` VALUES (27623, 'advertising revenue', 'n. 财政收入,税收', '/\'revənju:, -nu: | \'revənjuː | \'rɛvənu/', 'revenue', 5);
INSERT INTO `words` VALUES (27624, 'I owe you nothing. If anything, the reverse is true (= you owe me ) .', 'n. 相反;背面; adj. 相反的; v. 颠倒,倒转', '/ri\'və:s | rɪ\'vɜːs | rɪ\'vɝs/', 'reverse', 5);
INSERT INTO `words` VALUES (27625, 'a journalist who will review the events of the past six months', 'v. 回顾,复习; n. 回顾,复习;评论', '/ri\'vju: | rɪ\'vjuː | rɪ\'vju/', 'review', 5);
INSERT INTO `words` VALUES (27626, 'The college has revised its plans because of local objections.', 'v. 修订,校订;修正,修改', '/ri\'vaiz, \'ri:vaiz | rɪ\'vaɪz/', 'revise', 5);
INSERT INTO `words` VALUES (27627, 'The economy is beginning to revive.', 'v. 恢复;(使)复苏', '/ri\'vaiv | rɪ\'vaɪv/', 'revive', 5);
INSERT INTO `words` VALUES (27628, 'The prime minister is now facing a revolt by members of his own party.', 'v&n. 反抗,起义', '/ri\'vəult, -\'vɔ:lt | rɪ\'vəʊlt | rɪ\'volt/', 'revolt', 5);
INSERT INTO `words` VALUES (27629, 'the French Revolution of 1789', 'n. 革命;旋转,转数', '/,revə\'lu:ʃən | revə\'luːʃ(ə)n | \'rɛvə\'lʊʃən/', 'revolution', 5);
INSERT INTO `words` VALUES (27630, 'The new cancer drug is a revolutionary breakthrough.', 'adj. 革命的,革新的; n. 革命者', '/,revə\'lju:ʃənəri | revə\'luːʃ(ə)n(ə)rɪ | \'rɛvə\'lʊʃə\'nɛri/', 'revolutionary', 5);
INSERT INTO `words` VALUES (27631, 'The wheel began to revolve.', 'v. (使)旋转;考虑;【天】公转,循环', '/ri\'vɔlv, -\'vɔ:lv | rɪ\'vɒlv | rɪ\'vɔlv/', 'revolve', 5);
INSERT INTO `words` VALUES (27632, 'The school has a system of rewards and punishments to encourage good behaviour.', 'n. [劳经] 报酬；报答；酬谢; v. [劳经] 奖励；奖赏', '/ri\'wɔ:d | rɪ\'wɔːd | rɪ\'wɔrd/', 'reward', 5);
INSERT INTO `words` VALUES (27633, 'Drums are basic to African rhythm.', 'n. 节奏；韵律', '/\'riðəm, \'riθəm | \'rɪð(ə)m | \'rɪðəm/', 'rhythm', 5);
INSERT INTO `words` VALUES (27634, 'She was taken to hospital with a broken arm and ribs.', 'n. 肋骨；排骨；肋状物; v. 戏弄；装肋于', '/rib | rɪb/', 'rib', 5);
INSERT INTO `words` VALUES (27635, 'little girls with ribbons in their hair', 'n. 带；缎带；（勋章等的）绶带；带状物；勋表; vi. 形成带状; vt. 把…撕成条带；用缎带装饰', '/\'ribən | \'rɪbən/', 'ribbon', 5);
INSERT INTO `words` VALUES (27636, 'a tasty sauce served with rice or pasta', 'n. 稻；米饭; v. 把…捣成米糊状', '/rais | raɪs/', 'rice', 5);
INSERT INTO `words` VALUES (27637, 'Rich mineral deposits have been found in the sea bed.', 'adj. 富有的；肥沃的；昂贵的; n. (Rich)人名；(丹)里克；(捷)里赫；(英、西)里奇；(葡、法)里什', '/rɪtʃ/', 'rich', 5);
INSERT INTO `words` VALUES (27638, 'The proposals are an attempt to rid the country of political corruption.', 'v. 使摆脱；使去掉; n. (Rid)人名；(英)里德', '/rid | rɪd/', 'rid', 5);
INSERT INTO `words` VALUES (27639, 'See if you can solve this riddle .', 'v. 解谜；给出谜；充满于; n. 谜语；粗筛；谜一般的人、东西、事情等', '/\'ridl | \'rɪd(ə)l | \'rɪdl/', 'riddle', 5);
INSERT INTO `words` VALUES (27640, 'She learned to ride when she was seven.', 'v. 骑马；乘车；依靠；漂浮; n. 骑；乘坐；交通工具；可供骑行的路；（乘坐汽车等的）旅行；乘骑；（乘车或骑车的）短途旅程；供乘骑的游乐设施', '/raɪd/', 'ride', 5);
INSERT INTO `words` VALUES (27641, 'We made our way carefully along the ridge.', 'n. 山脊；山脉；屋脊; v. 使成脊状；作垄', '/ridʒ | rɪdʒ/', 'ridge', 5);
INSERT INTO `words` VALUES (27642, 'That’s a ridiculous idea!', 'adj. 可笑的；荒谬的', '/ri\'dikjuləs | rɪ\'dɪkjʊləs | rɪ\'dɪkjələs/', 'ridiculous', 5);
INSERT INTO `words` VALUES (27643, 'They shot him at point blank range with an automatic rifle.', 'n. 步枪；来复枪; v. 用步枪射击；抢夺；偷走', '/\'raifl | \'raɪf(ə)l | \'raɪfl/', 'rifle', 5);
INSERT INTO `words` VALUES (27644, 'rigid and authoritarian methods of education', 'adj. 严格的；僵硬的，死板的；坚硬的；精确的', '/\'ridʒid | \'rɪdʒɪd/', 'rigid', 5);
INSERT INTO `words` VALUES (27645, 'a rigorous analysis of defence needs', 'adj. 严格的，严厉的；严密的；严酷的', '/\'riɡərəs | \'rɪg(ə)rəs | \'rɪɡərəs/', 'rigorous', 5);
INSERT INTO `words` VALUES (27646, 'She looked at him over the rim of her glass.', 'n. 边，边缘；轮辋；圆圈; v. 作…的边，装边于', '/rim | rɪm/', 'rim', 5);
INSERT INTO `words` VALUES (27647, 'He left Washington with the president’s praises ringing in his ears.', 'v. 按铃；敲钟；回响；成环形; n. 戒指；铃声，钟声；拳击场；环形物', '/riŋ | rɪŋ/', 'ring', 5);
INSERT INTO `words` VALUES (27648, 'urban riots', 'n. 暴乱；放纵；蔓延; v. 骚乱；放荡', '/\'raiət | \'raɪət/', 'riot', 5);
INSERT INTO `words` VALUES (27649, 'Her clothes had all been ripped.', 'v. 撕；锯; n. 裂口，裂缝', '/rip | rɪp/', 'rip', 5);
INSERT INTO `words` VALUES (27650, 'Those tomatoes aren’t ripe yet.', 'adj. 熟的，成熟的；时机成熟的; vt. 搜查；调查; vi. 进行搜查; n. (Ripe)人名；(意、瑞典)里佩', '/raip | raɪp/', 'ripe', 5);
INSERT INTO `words` VALUES (27651, 'The police seem unable to cope with the rising tide of (= large increase in ) car crime.', 'v. 上升；增强；起立；高耸; n. 上升；高地；增加；出现', '/raiz, rais | raɪz/', 'rise', 5);
INSERT INTO `words` VALUES (27652, 'It was a risk, sending a letter to my house.', 'n. 风险；危险；冒险; v. 冒…的危险', '/risk | rɪsk/', 'risk', 5);
INSERT INTO `words` VALUES (27653, 'ancient pagan rituals', 'n. 仪式；惯例；礼制; adj. 仪式的；例行的；礼节性的', '/\'ritjuəl, -tʃu- | \'rɪtʃʊəl | \'rɪtʃuəl/', 'ritual', 5);
INSERT INTO `words` VALUES (27654, 'This gives the company a competitive advantage over its rivals.', 'n. 对手；竞争者; v. 与…竞争；比得上某人; adj. 竞争的', '/\'raivəl | \'raɪvl/', 'rival', 5);
INSERT INTO `words` VALUES (27655, 'the Mississippi River', 'n. 河，江', '/\'rivə | \'rɪvə | \'rɪvɚ/', 'river', 5);
INSERT INTO `words` VALUES (27656, '65 Maple Road', 'n. 公路，马路；道路；手段; vt. （狗）沿臭迹追逐（猎物）; adj. （美）巡回的', '/rəud | rəʊd | rod/', 'road', 5);
INSERT INTO `words` VALUES (27657, 'the roar of the crowd', 'n. 咆哮；吼；轰鸣; v. 咆哮；吼叫；喧闹', '/rɔ: | rɔː | rɔr/', 'roar', 5);
INSERT INTO `words` VALUES (27658, 'Are you going to roast the chicken?', 'v. 烤，焙；烘，烘烤；暴露于某种热力下以得温暖; adj. 烘烤的；烤过的; n. 烤肉；烘烤', '/rəust | rəʊst | rost/', 'roast', 5);
INSERT INTO `words` VALUES (27659, 'They killed four policemen while robbing a bank.', 'v. 抢劫；使…丧失；非法剥夺', '/rɔb | rɒb | rɑb/', 'rob', 5);
INSERT INTO `words` VALUES (27660, 'a priest’s robes', 'n. 长袍，礼服；制服; v. 穿长袍', '/rəub | rəʊb | rob/', 'robe', 5);
INSERT INTO `words` VALUES (27661, 'cars built by robots', 'n. 机器人；遥控设备，自动机械；机械般工作的人', '/\'rəubɔt, -bət, \'rɔbət | \'rəʊbɒt | \'robɑt/', 'robot', 5);
INSERT INTO `words` VALUES (27662, 'a robust man of six feet four', 'adj. 强健的；健康的；粗野的；粗鲁的', '/rəu\'bʌst, \'rəubʌst | rə(ʊ)\'bʌst | ro\'bʌst/', 'robust', 5);
INSERT INTO `words` VALUES (27663, 'the late rock star, Freddie Mercury', 'n. 岩石；摇滚乐；暗礁; v. 摇动；使摇晃', '/rɔk | rɒk | rɑk/', 'rock', 5);
INSERT INTO `words` VALUES (27664, 'The train rocketed through the tunnel.', 'v. 飞驰，飞快地移动；迅速增加; n. 火箭', '/\'rɔkit | \'rɒkɪt | \'rɑkɪt/', 'rocket', 5);
INSERT INTO `words` VALUES (27665, 'a measuring rod', 'n. 棒；惩罚；枝条；权力', '/rɔd | rɒd | rɑd/', 'rod', 5);
INSERT INTO `words` VALUES (27666, 'His sleeves were rolled above his elbows.', 'v. 卷；滚动，转动；辗; n. 卷，卷形物；名单；摇晃', '/rəul | rəʊl | rol/', 'roll', 5);
INSERT INTO `words` VALUES (27667, 'The romance had gone out of their relationship.', 'n. 传奇,爱情故事', '/rəu\'mæns, \'rəumæns, rə\'mæns | rə(ʊ)\'mæns; \'rəʊmæns | ro\'mæns/', 'romance', 5);
INSERT INTO `words` VALUES (27668, '‘Tom always sends me red roses on my birthday.’ ‘How romantic!’', 'adj. 浪漫的,传奇式的;不切实际的,好幻想的', '/rəu\'mæntik | rə(ʊ)\'mæntɪk | ro\'mæntɪk/', 'romantic', 5);
INSERT INTO `words` VALUES (27669, 'They finally found the cat up on the roof.', 'n. 屋顶；最高处，顶部；最高限度; v. 给…盖屋顶，覆盖', '/ru:f, ruf | ruːf | ruf/', 'roof', 5);
INSERT INTO `words` VALUES (27670, 'I looked around the room.', 'n. 房间；空间；余地；机会；房间里所有的人; v. 为…提供住处；租房，合住；投宿，住宿；留…住宿', '/ruːm; rʊm | rum/', 'room', 5);
INSERT INTO `words` VALUES (27671, 'tree roots', 'n. 根；根源；词根；祖先; v. 生根；根除', '/ru:t, rut | ruːt | rut/', 'root', 5);
INSERT INTO `words` VALUES (27672, 'They tied a rope around my waist and pulled me up.', 'n. 绳，绳索; v. 捆，绑', '/rəup | rəʊp | rop/', 'rope', 5);
INSERT INTO `words` VALUES (27673, 'a dozen red roses', 'n. 玫瑰；粉红色；蔷薇（花）；粉红色的葡萄酒; adj. 玫瑰花的；玫瑰色的；粉红色的；带有玫瑰香味的; vt. 使成玫瑰色，使（面颊）发红；使有玫瑰香味; vi. 起义( rise的过去式)；升起；（数量）增加；休会', '/rəʊz | roz/', 'rose', 5);
INSERT INTO `words` VALUES (27674, 'the smell of rot', 'n. 腐烂；腐败；腐坏; v. 腐烂；腐败；堕落; int. （表示厌恶、蔑视、烦恼等）胡说；糟了', '/rɔt | rɒt | rɑt/', 'rot', 5);
INSERT INTO `words` VALUES (27675, 'the rotary movement of the helicopter blades', 'adj. 旋转的，转动的；轮流的; n. 旋转式机器；[动力] 转缸式发动机', '/\'rəutəri | \'rəʊt(ə)rɪ | \'rotəri/', 'rotary', 5);
INSERT INTO `words` VALUES (27676, 'The Earth rotates on its axis once every 24 hours.', 'v. 旋转；循环; adj. [植] 辐状的', '/rəu\'teit, \'rəut-, \'rəuteit | rə(ʊ)\'teɪt | \'rotet/', 'rotate', 5);
INSERT INTO `words` VALUES (27677, 'the smell of rotten eggs', 'adj. 腐烂的；堕落的；恶臭的；虚弱的；极坏的; adv. 非常; n. (Rotten)人名；(法、德)罗滕', '/\'rɔtən | \'rɒt(ə)n | \'rɑtn/', 'rotten', 5);
INSERT INTO `words` VALUES (27678, 'I played a round of golf on Sunday morning.', 'n. 圆；循环；一回合；圆形物; adj. 圆的；完全的；大概的；肥胖的; adv. 在周围；迂回地；朝反方向；挨个; v. 完成；围捕；绕行；弄圆; prep. 附近；绕过；大约；在…周围', '/raund | raʊnd/', 'round', 5);
INSERT INTO `words` VALUES (27679, 'The bus took a very long and roundabout route .', 'adj. 迂回的，绕道的；圆滚滚的; n. 迂回路线；环状交叉路口', '/\'raundə,baut | \'raʊndəbaʊt/', 'roundabout', 5);
INSERT INTO `words` VALUES (27680, 'His banging roused the neighbours.', 'v. 唤醒；激起，使振奋；惊起; n. 觉醒；奋起', '/rauz | raʊz/', 'rouse', 5);
INSERT INTO `words` VALUES (27681, 'Trains are taking a lot of freight that used to be routed via trucks.', 'v. 按某路线发送; n. 路线；航线；通道', '/ru:t, raut | ruːt | raʊt/', 'route', 5);
INSERT INTO `words` VALUES (27682, 'John’s departure had upset their daily routine .', 'n. [计] 程序；日常工作；例行公事; adj. 日常的；例行的', '/ru:\'ti:n | ruː\'tiːn | rʊ\'tin/', 'routine', 5);
INSERT INTO `words` VALUES (27683, '(= many rows ) of shelves stacked with books', 'n. 行，排；划船；街道；吵闹; v. 划船；使……成排', '/rəu | rəʊ | ro/', 'row', 5);
INSERT INTO `words` VALUES (27684, 'the royal palace', 'adj. 皇家的；盛大的；女王的；高贵的；第一流的; n. 王室；王室成员', '/\'rɔiəl | \'rɒɪəl | \'rɔɪəl/', 'royal', 5);
INSERT INTO `words` VALUES (27685, 'At school the other children treated them like royalty .', 'n. 皇室；版税；王权；专利税', '/\'rɔiəlti | \'rɒɪəltɪ | \'rɔɪəlti/', 'royalty', 5);
INSERT INTO `words` VALUES (27686, 'You’ll have to rub harder if you want to get it clean.', 'v. 擦；摩擦；惹怒; n. 摩擦；障碍；磨损处', '/rʌb/', 'rub', 5);
INSERT INTO `words` VALUES (27687, 'a rubber ball', 'n. 橡胶；橡皮；合成橡胶；按摩师; adj. 橡胶制成的; v. 涂橡胶于；用橡胶制造', '/\'rʌbə | \'rʌbɚ/', 'rubber', 5);
