INSERT INTO `words` VALUES (27689, '...a ruby and diamond ring.', 'n. 红宝石；红宝石色; adj. 红宝石色的; vt. 使带红宝石色', '/\'ru:bi | \'ruːbɪ | \'rubi/', 'ruby', 5);
INSERT INTO `words` VALUES (27690, 'a rude remark', 'adj. 粗鲁的；无礼的；狂暴的；未开化的; n. (Rude)人名；(英、西、瑞典)鲁德；(法)吕德', '/ru:d | ruːd | rud/', 'rude', 5);
INSERT INTO `words` VALUES (27691, 'The old lady was seated in her chair at the window, a rug over her knees.', 'n. 小地毯；毛皮地毯；男子假发', '/rʌɡ | rʌg/', 'rug', 5);
INSERT INTO `words` VALUES (27692, 'an interesting old ruin', 'n. 废墟；毁坏；灭亡; v. 毁灭；使破产', '/\'ruin, \'ru:- | \'ruːɪn | \'ruɪn/', 'ruin', 5);
INSERT INTO `words` VALUES (27693, 'a 12-inch ruler', 'n. 尺；统治者；[测] 划线板，划线的人', '/\'ru:lə | \'ruːlə | \'rulɚ/', 'ruler', 5);
INSERT INTO `words` VALUES (27694, 'The rumor rocked the whole city.', 'n. 谣言；传闻; v. 谣传；传说', '/\'ru:mə | ˈruːmə | \'rʊmɚ/', 'rumor', 5);
INSERT INTO `words` VALUES (27695, 'His name has come up in the rumour mill as a possible director for the project.', 'n. 传闻， 谣言', '/\'ruːmə | \'ru:mə/', 'rumour', 5);
INSERT INTO `words` VALUES (27696, 'a rural setting', 'adj. 农村的，乡下的；田园的，有乡村风味的', '/\'ruərəl | \'rʊər(ə)l | \'rʊrəl/', 'rural', 5);
INSERT INTO `words` VALUES (27697, 'At five past twelve there was a mad rush to the dinner hall.', 'n. 冲进；匆促；急流；灯心草; adj. 急需的; v. 使冲；突袭；匆忙地做；飞跃', '/rʌʃ/', 'rush', 5);
INSERT INTO `words` VALUES (27698, 'There were large patches of rust on the car.', 'n. 锈；生锈；[植保] 锈病; v. 使生锈；腐蚀', '/rʌst/', 'rust', 5);
INSERT INTO `words` VALUES (27699, 'a ruthless dictator', 'adj. 无情的，残忍的', '/\'ru:θlis | \'ruːθlɪs | \'rʊθləs/', 'ruthless', 5);
INSERT INTO `words` VALUES (27700, 'the sack of Rome in 1527', 'n. 麻布袋；洗劫; v. 解雇；把……装入袋；劫掠', '/sæk/', 'sack', 5);
INSERT INTO `words` VALUES (27701, 'a sacred vow', 'adj. 神的；神圣的；宗教的；庄严的', '/\'seikrid | \'seɪkrɪd | \'sekrɪd/', 'sacred', 5);
INSERT INTO `words` VALUES (27702, 'The minister stressed the need for economic sacrifice.', 'n. 牺牲；祭品；供奉; v. 牺牲；献祭；亏本出售', '/\'sækrifais | \'sækrɪfaɪs/', 'sacrifice', 5);
INSERT INTO `words` VALUES (27703, 'Sorry to hear the sad news .', 'adj. 难过的；悲哀的，令人悲痛的；凄惨的，阴郁的（形容颜色）', '/sæd/', 'sad', 5);
INSERT INTO `words` VALUES (27704, 'Why don\'t we saddle a couple of horses and go for a ride?', 'n. 鞍，鞍状物；车座；拖具; v. 承受；使负担；装以马鞍', '/\'sædl | \'sæd(ə)l/', 'saddle', 5);
INSERT INTO `words` VALUES (27705, 'She doesn’t feel safe in the house on her own.', 'adj. 安全的；可靠的；平安的; n. 保险箱；冷藏室；纱橱', '/seif | seɪf | sef/', 'safe', 5);
INSERT INTO `words` VALUES (27706, 'International safeguards prevent the increase of nuclear weapons.', 'n. [安全] 保护；保卫；保护措施; v. [安全] 保护，护卫', '/\'seifɡɑ:d | \'seɪfgɑːd | \'sefɡɑrd/', 'safeguard', 5);
INSERT INTO `words` VALUES (27707, 'You shouldn’t travel alone, for safety’s sake .', 'n. 安全；保险；安全设备；保险装置；安打', '/\'seifti | \'seɪftɪ | \'sefti/', 'safety', 5);
INSERT INTO `words` VALUES (27708, 'Three tall ships sailed past.', 'v. 航行；启航，开船; n. 帆，篷；航行', '/seil | seɪl | sel/', 'sail', 5);
INSERT INTO `words` VALUES (27709, 'Saint Patrick', 'n. 圣人；圣徒；道德崇高的人; adj. 神圣的; v. 成为圣徒', '/seint | seɪnt | sent/', 'saint', 5);
INSERT INTO `words` VALUES (27710, 'He moved to the seaside for the sake of his health.', 'n. 目的；利益；理由；日本米酒', '/seik | seɪk | [sek]/', 'sake', 5);
INSERT INTO `words` VALUES (27711, 'Would you like some salad with your pasta?', 'n. 色拉；尤指莴苣', '/\'sæləd/', 'salad', 5);
INSERT INTO `words` VALUES (27712, 'The average salary for a teacher is $39,000 a year.', 'vt. 给加薪；给薪水; n. 薪水', '/\'sæləri | \'sælərɪ/', 'salary', 5);
INSERT INTO `words` VALUES (27713, '...an insurance salesman.', 'n. 售货员,推销员', '/\'seilzmən | \'seɪlzmən | \'selzmən/', 'salesman', 5);
INSERT INTO `words` VALUES (27714, 'the salient points of the report', 'adj. 显著的， 突出的A', '/\'seɪliənt | \'selɪənt/', 'salient', 5);
INSERT INTO `words` VALUES (27715, 'This might need some salt and pepper.', 'n. 盐；风趣，刺激性; adj. 咸水的；含盐的，咸味的；盐腌的；猥亵的; v. 用盐腌；给…加盐；将盐撒在道路上使冰或雪融化', '/sɔ:lt | sɔːlt; sɒlt | sɔlt/', 'salt', 5);
INSERT INTO `words` VALUES (27716, 'As they left, the corporal gave them a respectful salute.', 'n. 致敬，欢迎；敬礼; v. 行礼致敬，欢迎', '/sə\'lju:t, sɑ:\'lu:te | sə\'l(j)uːt | sə\'lut/', 'salute', 5);
INSERT INTO `words` VALUES (27717, 'The church\'s message of salvation has changed the lives of many.', 'n. 拯救；救助', '/sæl\'veiʃən | sæl\'veɪʃ(ə)n | sæl\'veʃən/', 'salvation', 5);
INSERT INTO `words` VALUES (27718, 'Her perfume has always had the same effect on me.', 'adj. 相同的; pron. 相同的人(或物); adv. 同样地', '/seim | seɪm | sem/', 'same', 5);
INSERT INTO `words` VALUES (27719, 'They took a blood sample to test for hepatitis.', 'n. 样品,实例,标本,抽样检查; v. 取样,采样', '/\'sɑ:mpl, \'sæ- | \'sɑːmp(ə)l | \'sæmpl/', 'sample', 5);
INSERT INTO `words` VALUES (27720, 'Apparently, the aide had acted without White House sanction.', 'n&v. 批准,同意,支持,认可; n. 处罚,制裁', '/\'sæŋ,kʃən | \'sæŋ(k)ʃ(ə)n | \'sæŋkʃən/', 'sanction', 5);
INSERT INTO `words` VALUES (27721, 'a mixture of sand and cement', 'n. 沙；沙地；沙洲；沙滩；沙子; v. 撒沙于；以沙掩盖；用砂纸等擦平或磨光某物；使撒沙似地布满；给…掺沙子', '/sænd/', 'sand', 5);
INSERT INTO `words` VALUES (27722, 'Carefully split the sponge ring, then sandwich the two halves together with whipped cream.', 'v. 夹入；挤进；把做成三明治; n. 三明治；夹心面包', '/\'sænwidʒ | \'sæn(d)wɪdʒ; -wɪtʃ | \'sænwɪtʃ/', 'sandwich', 5);
INSERT INTO `words` VALUES (27723, 'He seems perfectly sane (= completely sane ) to me.', 'adj. 心智健全的,神志清醒的,明智的,稳健的', '/sein | seɪn | sen/', 'sane', 5);
INSERT INTO `words` VALUES (27724, 'Was she being sarcastic?', 'adj. 挖苦的；尖刻的，辛辣的', '/sɑ:\'kæztik | sɑː\'kæstɪk | sɑr\'kæstɪk/', 'sarcastic', 5);
INSERT INTO `words` VALUES (27725, 'the characteristic use of satire in Jonson’s work', 'n. 讽刺；讽刺文学，讽刺作品', '/\'sætaiə | \'sætaɪə | \'sætaɪɚ/', 'satire', 5);
INSERT INTO `words` VALUES (27726, 'She got great satisfaction from helping people to learn.', 'n. 满足,满意;乐事,愉快', '/,sætis\'fækʃən | sætɪs\'fækʃ(ə)n | ,sætɪs\'fækʃən/', 'satisfaction', 5);
INSERT INTO `words` VALUES (27727, 'His progress this term has been satisfactory.', 'adj. 令人满意的,圆满的,良好的,符合要求的', '/,sætis\'fæktəri | sætɪs\'fækt(ə)rɪ | ,sætɪs\'fæktəri/', 'satisfactory', 5);
INSERT INTO `words` VALUES (27728, 'Water poured through the hole, saturating the carpet.', 'v. 浸透，使湿透；使饱和，使充满; adj. 浸透的，饱和的；深颜色的', '/\'sætʃəreit, \'sætʃərit | \'sætʃəreɪt | \'sætʃərɪt/', 'saturate', 5);
INSERT INTO `words` VALUES (27729, 'He called her on Saturday morning at the studio.', 'n. 星期六', '/\'sætədi; -dei | ˈsætədɪ; -deɪ | sætɚdɪ; -de/', 'saturday', 5);
INSERT INTO `words` VALUES (27730, 'spaghetti sauces', 'n. 酱油；沙司；调味汁; v. 使增加趣味；给…调味', '/sɔ:s | sɔːs | sɔs/', 'sauce', 5);
INSERT INTO `words` VALUES (27731, 'a china cup and saucer', 'n. 茶托，浅碟；浅碟形物；眼睛', '/\'sɔ:sə | \'sɔːsə | \'sɔsɚ/', 'saucer', 5);
INSERT INTO `words` VALUES (27732, 'pork sausages', 'n. 香肠；腊肠；装香肠的碎肉', '/\'sɔsidʒ, \'sɔ:- | \'sɒsɪdʒ | \'sɔsɪdʒ/', 'sausage', 5);
INSERT INTO `words` VALUES (27733, 'a savage dog', 'adj. 野蛮的；残酷的；狂怒的；荒凉的; n. 未开化的人；粗鲁的人；残暴成性的人; v. 乱咬；粗暴的对待', '/\'sævɪdʒ/', 'savage', 5);
INSERT INTO `words` VALUES (27734, 'He managed to save enough to buy a small house.', 'v. 节省；保存；储蓄；解救; prep. 除之外; n. 救援', '/seɪv | sev/', 'save', 5);
INSERT INTO `words` VALUES (27735, 'Buying a house had taken all their savings.', 'n. 节约；挽救；存款; adj. 节约的；挽救的；补偿的；保留的; prep. 考虑到；除之外', '/\'seiviŋ | \'seɪvɪŋ | \'sevɪŋ/', 'saving', 5);
INSERT INTO `words` VALUES (27736, 'She was in the back yard sawing logs.', 'v. 锯， 锯开; n. 锯子； 锯床', '/sɔː | sɔ/', 'saw', 5);
INSERT INTO `words` VALUES (27737, 'A structural survey revealed the full scale of the damage.', 'n. 刻度;天平,磅秤;比例尺;规模;音阶;鱼鳞', '/skeil | skeɪl | skel/', 'scale', 5);
INSERT INTO `words` VALUES (27738, 'He scanned the horizon, but there was no sign of the ship.', 'v. 扫描；浏览；细看；详细调查；标出格律; n. 扫描；浏览；审视；细看', '/skæn/', 'scan', 5);
INSERT INTO `words` VALUES (27739, 'It caused quite a scandal when he left his wife.', 'n. 丑闻；流言蜚语；诽谤；公愤', '/\'skændəl | \'skænd(ə)l | \'skændl/', 'scandal', 5);
INSERT INTO `words` VALUES (27740, 'His hands were badly scarred by the fire.', 'v. 伤害；给留下伤痕; n. 创伤；伤痕', '/skɑ: | skɑː | skɑr/', 'scar', 5);
INSERT INTO `words` VALUES (27741, 'Food was often scarce in the winter.', 'adj. 缺乏的，不足的；稀有的; adv. 仅仅；几乎不；几乎没有', '/skεəs | skeəs | skɛrs/', 'scarce', 5);
INSERT INTO `words` VALUES (27742, 'The city had scarcely changed in 20 years.', 'adv. 几乎不，简直不；简直没有', '/\'skεəsli | \'skeəslɪ | \'skɛrsli/', 'scarcely', 5);
INSERT INTO `words` VALUES (27743, 'I don’t scare easily, you know.', 'v. 惊吓；把…吓跑; n. 恐慌；惊吓；惊恐; adj. （美）骇人的', '/skεə | skeə | skɛr/', 'scare', 5);
INSERT INTO `words` VALUES (27744, 'He reached up to loosen the scarf around his neck.', 'n. 围巾；嵌接，嵌接处；头巾领巾; v. 披嵌接；用围巾围', '/skɑ:f | skɑːf | skɑrf/', 'scarf', 5);
INSERT INTO `words` VALUES (27745, 'The sound of gunfire made the crowd scatter in all directions.', 'v. 分散，散开；散射; n. 分散；散播，撒播', '/\'skætə | \'skætɚ/', 'scatter', 5);
INSERT INTO `words` VALUES (27746, 'There will be some scattered showers (= short periods of rain ) in the afternoon.', 'adj. 离散的， 分散的', '/\'skætəd | \'skætɚd/', 'scattered', 5);
INSERT INTO `words` VALUES (27747, 'The conflict degenerating into civil war is everybody\'s nightmare scenario.', 'n. 情境 “；剧本', '/sə\'nɑːriəu | sə\'nærɪo/', 'scenario', 5);
INSERT INTO `words` VALUES (27748, 'He photographed a wide range of street scenes.', 'n. 场面；情景；景象；事件', '/si:n | siːn | sin/', 'scene', 5);
INSERT INTO `words` VALUES (27749, 'The best part of the trip was the fantastic scenery.', 'n. 风景；景色；舞台布景', '/\'si:nəri | \'siːn(ə)rɪ | \'sinəri/', 'scenery', 5);
INSERT INTO `words` VALUES (27750, 'a yellow rose with a lovely scent', 'n. 气味；嗅觉；痕迹；察觉能力; v. 闻到；发觉；使充满…的气味；循着遗臭追踪', '/sent | sɛnt/', 'scent', 5);
INSERT INTO `words` VALUES (27751, 'We will not cancel your holiday less than eight weeks before the scheduled departure date .', 'v. 安排，计划；编制目录；将……列入计划表; n. 时间表；计划表；一览表', '/\'ʃədju:əl, -dʒu:əl, \'skedʒu:əl, -dʒuəl | ˈʃɛdjuːl | \'skɛdʒul; (canadian) ˈʃɛdʒʊl; ˈʃɛdjʊl/', 'schedule', 5);
INSERT INTO `words` VALUES (27752, 'The money will be used for teacher training schemes.', 'n. 计划；组合；体制；诡计; v. 搞阴谋；拟订计划', '/ski:m | skiːm | skim/', 'scheme', 5);
INSERT INTO `words` VALUES (27753, 'a Shakespearean scholar', 'n. 学者；奖学金获得者', '/\'skɔlə | \'skɒlə | \'skɑlɚ/', 'scholar', 5);
INSERT INTO `words` VALUES (27754, 'Her latest publication is a fine piece of scholarship.', 'n. 奖学金；学识，学问', '/\'skɔləʃip | \'skɒləʃɪp | \'skɑlɚʃɪp/', 'scholarship', 5);
INSERT INTO `words` VALUES (27755, 'Many leading scientists do not consider that science can give absolutely reliable knowledge.', 'n. 科学；技术；学科；理科', '/\'saiəns | \'saɪəns/', 'science', 5);
INSERT INTO `words` VALUES (27756, 'We believe in investing in scientific research.', 'adj. 科学的，系统的', '/,saiən\'tifik | saɪən\'tɪfɪk | ,saɪən\'tɪfɪk/', 'scientific', 5);
INSERT INTO `words` VALUES (27757, 'Scientists say they\'ve already collected more data than had been expected.', 'n. 科学家', '/\'saiəntist | \'saɪəntɪst/', 'scientist', 5);
INSERT INTO `words` VALUES (27758, 'a pair of scissors', 'n. 剪刀；剪式跳法; v. 剪开；删除（scissor的第三人称单数）', '/\'sizəz | \'sɪzəz | \'sɪzɚz/', 'scissors', 5);
INSERT INTO `words` VALUES (27759, 'Do not scold the puppy, but simply and firmly say ‘no’.', 'v. 责骂；叱责; n. 责骂；爱责骂的人', '/skəuld | skəʊld | skold/', 'scold', 5);
INSERT INTO `words` VALUES (27760, 'measures to limit the scope of criminals’ activities', 'n. 范围；余地；视野；眼界；导弹射程; v. 审视', '/skəup | skəʊp | skop/', 'scope', 5);
INSERT INTO `words` VALUES (27761, 'a musical score', 'n. 分数；二十；配乐；刻痕; v. 获得；评价；划线，刻划；把…记下', '/skɔ: | skɔː | skɔ/', 'score', 5);
INSERT INTO `words` VALUES (27762, 'Researchers greeted the proposal with scorn.', 'n. 轻蔑；嘲笑；藐视的对象; v. 轻蔑；藐视；不屑做', '/skɔ:n | skɔːn | skɔrn/', 'scorn', 5);
INSERT INTO `words` VALUES (27763, 'He sent three scouts ahead to take a look at the bridge.', 'n. 搜索，侦察；侦察员；侦察机; v. 侦察；跟踪，监视；发现', '/skaut | skaʊt/', 'scout', 5);
INSERT INTO `words` VALUES (27764, 'Our conversation will be electronically scrambled.', 'v. 攀登；使混杂，仓促凑成；扰乱; n. 抢夺，争夺；混乱，混乱的一团；爬行，攀登', '/\'skræmbl | \'skræmb(ə)l/', 'scramble', 5);
INSERT INTO `words` VALUES (27765, 'He’s always getting into scraps with other dogs.', 'n. 碎片；残余物；打架；少量; v. 废弃；使解体；拆毁; adj. 废弃的；零碎的', '/skræp/', 'scrap', 5);
INSERT INTO `words` VALUES (27766, 'I came away from the accident with only cuts and scrapes.', 'n. 刮掉；擦痕；困境；刮擦声; v. 刮；擦伤；挖成', '/skreip | skreɪp | skrep/', 'scrape', 5);
INSERT INTO `words` VALUES (27767, 'There were deep scratches all over her face.', 'n. 擦伤；抓痕；刮擦声；乱写; adj. 打草稿用的；凑合的；碰巧的; v. 抓；刮；挖出；乱涂', '/skrætʃ/', 'scratch', 5);
INSERT INTO `words` VALUES (27768, 'After the first few shots, people started screaming.', 'v. 尖叫；呼啸；发出尖锐刺耳的声音；令人触目惊心; n. 尖叫声；尖锐刺耳的声音；极其滑稽可笑的人', '/skri:m | skriːm | skrim/', 'scream', 5);
INSERT INTO `words` VALUES (27769, 'a computer with an 18-inch colour screen', 'n. 屏，幕；屏风; v. 筛；拍摄；放映；掩蔽', '/skri:n | skriːn | skrin/', 'screen', 5);
INSERT INTO `words` VALUES (27770, '\"Yes, I know that,\" Kelly said, screwing the silencer onto the pistol.', 'v. 旋，拧；压榨；强迫; n. 螺旋；螺丝钉；吝啬鬼', '/skru: | skruː | skru/', 'screw', 5);
INSERT INTO `words` VALUES (27771, 'They write all their own scripts.', 'n. 剧本(原稿)；手稿，原稿；笔迹，手迹', '/skript | skrɪpt/', 'script', 5);
INSERT INTO `words` VALUES (27772, 'Their activities have come under police scrutiny .', 'n. 详细审查；监视；细看；选票复查', '/\'skru:tini | \'skruːtɪnɪ | \'skrutəni/', 'scrutiny', 5);
INSERT INTO `words` VALUES (27773, '...stone sculptures of figures and animals.', 'n. 雕塑；雕刻；刻蚀; v. 雕塑；雕刻；刻蚀', '/\'skʌlptʃə | \'skʌlptʃɚ/', 'sculpture', 5);
INSERT INTO `words` VALUES (27774, 'Jay stripped his clothes off and ran into the sea.', 'n. 海；海洋；许多；大量', '/si: | siː | si/', 'sea', 5);
INSERT INTO `words` VALUES (27775, 'Check seals on fridges and freezers regularly.', 'n. 密封；印章；海豹；封条；标志; v. 密封；盖章', '/si:l | sil/', 'seal', 5);
INSERT INTO `words` VALUES (27776, 'She was repairing Billy’s trousers, where the seam had come undone.', 'n. 缝；接缝; v. 缝合；接合；使留下伤痕', '/si:m | siːm | sim/', 'seam', 5);
INSERT INTO `words` VALUES (27777, 'It was too dark to search further.', 'v. 搜寻；调查；探求; n. 搜寻；探究，查究', '/sə:tʃ | sɜːtʃ | sɝtʃ/', 'search', 5);
INSERT INTO `words` VALUES (27778, 'a trip to the seaside', 'n. 海滨,海边', '/\'si:said | \'siːsaɪd | \'sisaɪd/', 'seaside', 5);
INSERT INTO `words` VALUES (27779, 'the effect on plants as the seasons start to change', 'n. 时期；季节；赛季; v. 给…调味；使适应', '/\'si:zən | \'siːz(ə)n | \'sizn/', 'season', 5);
INSERT INTO `words` VALUES (27780, 'I was in the back seat and Jo was driving.', 'n. 座位；所在地；职位; v. 使…坐下；可容纳…的；使就职', '/si:t | siːt | sit/', 'seat', 5);
INSERT INTO `words` VALUES (27781, 'the Second World War', 'adj. 第二;次等的,二等的; n. 秒; v. 赞成,附和', '/\'sekənd | \'sek(ə)nd | \'sɛkənd/', 'second', 5);
INSERT INTO `words` VALUES (27782, 'the novel’s secondary characters', 'adj. 次要的,二级的;中级的,第二的', '/\'sekəndəri | \'sek(ə)nd(ə)rɪ | \'sɛkəndɛri/', 'secondary', 5);
INSERT INTO `words` VALUES (27783, 'They kept their relationship secret from their parents.', 'adj. 秘密的,机密的; n. 秘密', '/\'si:krit | \'siːkrɪt | \'sikrɪt/', 'secret', 5);
INSERT INTO `words` VALUES (27784, 'My secretary will fax you all the details.', 'n. 秘书,书记;部长,大臣', '/\'sekrətəri | \'sekrɪt(ə)rɪ | \'sɛkrətɛrɪ/', 'secretary', 5);
INSERT INTO `words` VALUES (27785, 'The plane’s tail section was found in a cornfield.', 'n. 章节；部分；地区；部门， 科 A', '/\'sekʃn | \'sɛkʃən/', 'section', 5);
INSERT INTO `words` VALUES (27786, '...the nation\'s manufacturing sector.', 'n. 部门；扇形，扇区；象限仪；函数尺; vt. 把…分成扇形', '/\'sektə | \'sɛktɚ/', 'sector', 5);
INSERT INTO `words` VALUES (27787, 'Companies can offer secure credit card transactions over the Internet.', 'adj. (from,against)安全的,放心的v.得到;防护', '/si\'kjuə | sɪ\'kjʊə; sɪ\'kjɔː | sə\'kjʊr/', 'secure', 5);
INSERT INTO `words` VALUES (27788, 'One of the sales clerks called security.', 'n. 安全(感),防御(物),保证(人),(pl.)证券', '/si\'kjuəriti | sɪ\'kjʊərətɪ | sə\'kjʊrəti/', 'security', 5);
INSERT INTO `words` VALUES (27789, 'He’s been top seed for the past two years.', 'n. 种子；根据；精液；萌芽；子孙；原由; v. 播种；结实；成熟；去…籽', '/si:d | siːd | sid/', 'seed', 5);
INSERT INTO `words` VALUES (27790, 'Do you think the President will seek re-election ?', 'v. 寻求；寻找；探索；搜索', '/si:k | siːk | sik/', 'seek', 5);
INSERT INTO `words` VALUES (27791, 'There is seemingly nothing we can do to stop the plans going ahead.', 'adv. 看来似乎；表面上看来', '/\'si:miŋli | \'siːmɪŋlɪ | \'simɪŋli/', 'seemingly', 5);
INSERT INTO `words` VALUES (27792, '...the poorer segments of society.', 'v. 分割; n. 段；部分', '/\'seɡmənt, seɡ\'ment, \'seɡment | \'segm(ə)nt | \'sɛɡmənt/', 'segment', 5);
INSERT INTO `words` VALUES (27793, 'A large detachment of police was used to segregate the two rival camps of protesters.', 'v. 使隔离；使分离；在…实行种族隔离', '/\'seɡriɡit, -ɡeit | \'segrɪgeɪt | \'sɛɡrɪɡet/', 'segregate', 5);
INSERT INTO `words` VALUES (27794, 'Suddenly he seized my hand.', 'v. 抓住；夺取；理解；逮捕', '/si:z | siːz | siz/', 'seize', 5);
INSERT INTO `words` VALUES (27795, 'Karen had seldom seen him so angry.', 'adv. 很少，不常', '/\'seldəm | \'sɛldəm/', 'seldom', 5);
INSERT INTO `words` VALUES (27796, 'a group of students selected at random', 'v. 选择,挑选; adj. 精选的,选择的', '/si\'lekt | sɪ\'lekt | sə\'lɛkt/', 'select', 5);
INSERT INTO `words` VALUES (27797, 'The judges have made their final selection.', 'n. 选择,挑选;选集,精选物', '/si\'lekʃən | sɪ\'lekʃ(ə)n | sɪ\'lɛkʃən/', 'selection', 5);
INSERT INTO `words` VALUES (27798, 'How can you be so selfish?', 'adj. 自私的；利己主义的', '/\'selfiʃ | \'selfɪʃ | \'sɛlfɪʃ/', 'selfish', 5);
INSERT INTO `words` VALUES (27799, 'If you offer him another hundred, I think he’ll sell.', 'v. 销售；推销；出卖；欺骗; n. 销售；失望；推销术', '/sel | sɛl/', 'sell', 5);
INSERT INTO `words` VALUES (27800, 'the fall semester', 'n. 学期；半年', '/si\'mestə | sɪ\'mestə | səˈmɛstɚ/', 'semester', 5);
INSERT INTO `words` VALUES (27801, 'In semiconductor receivers transistors take the place of vacuum tubes.', 'n. 半导体', '/,semikən\'dɔktə, ,semai- | ,semɪkən\'dʌktə | ,sɛmɪkən\'dʌktɚ/', 'semiconductor', 5);
INSERT INTO `words` VALUES (27802, 'a Shakespeare seminar', 'n. 讨论会，研讨班', '/\'seminɑ: | \'semɪnɑː | \'sɛmɪnɑr/', 'seminar', 5);
INSERT INTO `words` VALUES (27803, 'The Senate approved the bill.', 'n. 参议院,上院', '/\'senit | \'senɪt | \'sɛnət/', 'senate', 5);
INSERT INTO `words` VALUES (27804, 'Senator Kennedy', 'n. 参议员', '/\'senətə | \'sɛnətɚ/', 'senator', 5);
INSERT INTO `words` VALUES (27805, 'the senior Democrat on the House committee', 'adj. 年长的;地位较高的; n. (大学)四年级学生', '/\'si:njə | \'siːnɪə; \'siːnjə | \'sinɪɚ/', 'senior', 5);
INSERT INTO `words` VALUES (27806, 'Jerry realized that he had no sensation in his legs.', 'n. 感觉,知觉;激动,轰动,轰动一时的事情', '/sen\'seiʃən | sen\'seɪʃ(ə)n | sɛn\'seʃən/', 'sensation', 5);
INSERT INTO `words` VALUES (27807, 'Cats have a very acute sense of hearing (= very good, so that they can hear even the smallest sound ) .', 'n. 感官;感觉;判断力;意义; v. 觉得,意识到', '/sens | sɛns/', 'sense', 5);
INSERT INTO `words` VALUES (27808, 'She seems very sensible.', 'adj. 明智的,达理的;可觉察的,明显的', '/\'sensɪb(ə)l | \'sɛnsəbl/', 'sensible', 5);
INSERT INTO `words` VALUES (27809, 'a very sensitive child', 'adj. (to)敏感的,易受伤害的;灵敏的', '/\'sensɪtɪv | \'sɛnsətɪv/', 'sensitive', 5);
INSERT INTO `words` VALUES (27810, 'His voice dropped at the end of the sentence.', 'n. 句子;判决,宣判; v. 宣判,判决', '/\'sentəns | \'sent(ə)ns | \'sɛntəns/', 'sentence', 5);
INSERT INTO `words` VALUES (27811, 'There’s no place for sentiment in business!', 'n. 感情，柔情；看法；感觉', '/\'sentimənt | \'sentɪm(ə)nt | \'sɛntɪmənt/', 'sentiment', 5);
INSERT INTO `words` VALUES (27812, 'The gym and the sauna are in separate buildings.', 'adj. (from)分离的,分开的', '/(for v.) ˈsepəreɪt; (for adj.) ˈseprət | (for v.) sɛpəˌret; (for adj.) sɛprɪt/', 'separate', 5);
INSERT INTO `words` VALUES (27813, 'Her son, Jerome, was born in September.', 'n. 九月', '/sep\'tembə | sɛp\'tɛmbɚ/', 'september', 5);
INSERT INTO `words` VALUES (27814, 'Be careful to perform the actions in the correct sequence .', 'n. 先后,次序;连续,数列', '/\'si:kwəns | \'siːkw(ə)ns | \'sikwəns/', 'sequence', 5);
INSERT INTO `words` VALUES (27815, 'Keep the questions in the same serial order .', 'adj. 连续的；连载的；分期偿还的; n. 电视连续剧；[图情] 期刊；连载小说', '/\'siəriəl, \'si:r- | \'sɪərɪəl | \'sɪrɪəl/', 'serial', 5);
INSERT INTO `words` VALUES (27816, 'the series of events that led to the outbreak of war', 'n. 系列，连续；[电] 串联；级数；丛书', '/\'siəri:z, -riz | \'sɪəriːz; -rɪz | \'sɪriz/', 'series', 5);
INSERT INTO `words` VALUES (27817, 'Many young girls became domestic servants .', 'n. 仆人，佣人；公务员；雇工', '/\'sə:vənt | \'sɜːv(ə)nt | \'sɝvənt/', 'servant', 5);
INSERT INTO `words` VALUES (27818, 'the health service', 'n. 服务，服侍；服役；仪式; adj. 服务性的；耐用的；服现役的; v. 维修，检修；保养', '/\'sə:vis | \'sɜːvɪs | \'sɝvɪs/', 'service', 5);
INSERT INTO `words` VALUES (27819, 'Board members met in closed session (= with nobody else present ) .', 'n. 会议；（法庭的）开庭；（议会等的）开会；学期；讲习会', '/\'seʃən | \'seʃ(ə)n | \'sɛʃən/', 'session', 5);
INSERT INTO `words` VALUES (27820, 'The team’s hopes of playing in Europe suffered a setback last night.', 'n. 挫折；退步；逆流', '/\'setbæk | \'sɛtbæk/', 'setback', 5);
INSERT INTO `words` VALUES (27821, 'I’ve worked with children in various settings, mainly in secondary school.', 'n. 环境；安装；布置；[天] 沉落; v. 放置；沉没；使…处于某位置（set的ing形式）', '/\'setiŋ | \'setɪŋ | \'sɛtɪŋ/', 'setting', 5);
INSERT INTO `words` VALUES (27822, 'We hope the factions will be able to settle their differences (= agree to stop arguing ) by peaceful means.', 'v. 解决；定居；沉淀；下陷; n. 有背长椅', '/\'setl | \'set(ə)l | \'sɛtl/', 'settle', 5);
INSERT INTO `words` VALUES (27823, 'Union leaders and company bosses will meet tomorrow in an attempt to reach a settlement .', 'n. 解决，处理；[会计] 结算；沉降；殖民', '/\'setlmənt | \'set(ə)lm(ə)nt | \'sɛtlmənt/', 'settlement', 5);
INSERT INTO `words` VALUES (27824, 'His injuries were quite severe.', 'adj. 严峻的；严厉的；剧烈的；苛刻的', '/si\'viə | sɪ\'vɪə | sɪ\'vɪr/', 'severe', 5);
INSERT INTO `words` VALUES (27825, 'I learned to sew at school.', 'v. 缝合，缝上；缝纫', '/səu | səʊ | so/', 'sew', 5);
INSERT INTO `words` VALUES (27826, 'All you see on TV is sex and violence these days.', 'n. 性；性别；性行为；色情; v. 引起…的性欲；区别…的性别', '/seks | sɛks/', 'sex', 5);
INSERT INTO `words` VALUES (27827, 'Hugh’s jacket was old and shabby.', 'adj. 破旧的；卑鄙的；吝啬的；低劣的', '/\'ʃæbi | \'ʃæbɪ | ˈʃæbi/', 'shabby', 5);
INSERT INTO `words` VALUES (27828, 'the long dark shadow of an old oak tree', 'n. 阴影；影子；幽灵；庇护；隐蔽处; v. 遮蔽；使朦胧；尾随；预示; adj. 影子内阁的', '/\'ʃædəʊ | \'ʃædo/', 'shadow', 5);
INSERT INTO `words` VALUES (27829, 'a shady street', 'adj. 成荫的；阴暗的；名声不好的; n. (Shady)人名；(阿拉伯)沙迪', '/\'ʃeidi | \'ʃeɪdɪ | \'ʃedi/', 'shady', 5);
INSERT INTO `words` VALUES (27830, 'a drive shaft', 'n. 拍杆；[机] 轴；箭杆；杆状物; v. 利用；在……上装杆', '/ʃɑ:ft, ʃæft | ʃɑːft | ʃæft/', 'shaft', 5);
INSERT INTO `words` VALUES (27831, 'She shook him to wake him up.', 'v. 动摇；摇动；震动；握手; n. 摇动；哆嗦', '/ʃeɪk | ʃek/', 'shake', 5);
INSERT INTO `words` VALUES (27832, 'a shallow river', 'adj. 浅的,浅薄的; n. 浅滩,浅处', '/\'ʃæləu | \'ʃæləʊ | \'ʃælo/', 'shallow', 5);
INSERT INTO `words` VALUES (27833, 'The elections were a complete sham.', 'n. 假装；骗子；赝品; v. 假装；冒充; adj. 假的；虚假的；假装的', '/ʃæm/', 'sham', 5);
INSERT INTO `words` VALUES (27834, 'What kind of shampoo do you use?', 'n. 洗发；洗发精; v. 洗发', '/ʃæm\'pu: | ʃæm\'puː | ʃæm\'pu/', 'shampoo', 5);
INSERT INTO `words` VALUES (27835, 'What shape is the table?', 'n. 形状；模型；身材；具体化; v. 形成；塑造，使成形；使符合', '/ʃeip | ʃeɪp | ʃep/', 'shape', 5);
INSERT INTO `words` VALUES (27836, 'As a kid he’d never share his toys.', 'v. 分享，分担；分配; n. 份额；股份', '/ʃεə | ʃeə | ʃɛr/', 'share', 5);
INSERT INTO `words` VALUES (27837, 'Sharks were circling around our boat.', 'n. 鲨鱼；骗子; v. 诈骗', '/ʃɑ:k | ʃɑːk | ʃɑrk/', 'shark', 5);
INSERT INTO `words` VALUES (27838, 'Make sure you use a good sharp knife.', 'adj. 急剧的；锋利的；强烈的；敏捷的；刺耳的; adv. 急剧地；锐利地；突然地; n. 尖头；骗子；内行; vt. 磨快；把音调升高; vi. 打扮；升音演奏', '/ʃɑ:p | ʃɑːp | ʃɑrp/', 'sharp', 5);
INSERT INTO `words` VALUES (27839, 'The explosion shattered the building.', 'v. 粉碎；打碎；破坏；破掉；使散开; n. 碎片；乱七八糟的状态', '/\'ʃætə | \'ʃætɚ/', 'shatter', 5);
INSERT INTO `words` VALUES (27840, 'He hadn’t shaved for days.', 'v. 剃须，剃毛; n. 刮脸，剃胡子；修面；<口>侥幸逃过，幸免；剃刀，刮刀', '/ʃeɪv | ʃev/', 'shave', 5);
INSERT INTO `words` VALUES (27841, 'Though shorn of some of its powers, the party remains in control.', 'v. 剪；修剪；剥夺; n. [力] 切变；修剪；大剪刀', '/ʃiə | ʃɪə | ʃɪr/', 'shear', 5);
INSERT INTO `words` VALUES (27842, 'The company is planning to shed about a quarter of its workforce.', 'vt. 流出；发散， 散发；脱落； 摆脱; n. 棚， 小屋', '/ʃed | ʃɛd/', 'shed', 5);
INSERT INTO `words` VALUES (27843, 'Sheep were grazing on the hillside.', 'n. 羊，绵羊；胆小鬼', '/ʃiːp | ʃip/', 'sheep', 5);
INSERT INTO `words` VALUES (27844, 'I’ll never forget the look of sheer joy on her face.', 'adj. 绝对的；透明的；峻峭的；纯粹的; adv. 完全；陡峭地; v. 偏航; n. 偏航；透明薄织物', '/ʃɪə | ʃɪr/', 'sheer', 5);
INSERT INTO `words` VALUES (27845, 'shelves of books', 'n. 架子；搁板；搁板状物；暗礁', '/ʃelf | ʃɛlf/', 'shelf', 5);
INSERT INTO `words` VALUES (27846, 'We ran for cover as shells dropped all around us.', 'n. 壳，贝壳；炮弹；外形; v. 剥落；设定命令行解释器的位置', '/ʃel | ʃɛl/', 'shell', 5);
INSERT INTO `words` VALUES (27847, 'The men took shelter in a bombed-out farmhouse.', 'n. 庇护；避难所；遮盖物; v. 保护；使掩蔽', '/\'ʃeltə | \'ʃɛltɚ/', 'shelter', 5);
INSERT INTO `words` VALUES (27848, 'The shepherd tended a flock.', 'n. 牧民,牧羊人', '/\'ʃepəd | \'ʃɛpɚd/', 'shepherd', 5);
INSERT INTO `words` VALUES (27849, 'He used his left hand as a shield against the reflecting sunlight.', 'n. 盾；防护物；保护者; v. 遮蔽；包庇；避开；保卫', '/ʃi:ld | ʃiːld | ʃild/', 'shield', 5);
INSERT INTO `words` VALUES (27850, 'I work shifts.', 'n. 移动；变化；手段；轮班; v. 移动；转变；转换', '/ʃift | ʃɪft/', 'shift', 5);
INSERT INTO `words` VALUES (27851, 'The prominent coin was called the shilling and it was a silver coin.', 'n. 先令', '/\'ʃiliŋ | \'ʃɪlɪŋ/', 'shilling', 5);
INSERT INTO `words` VALUES (27852, 'The sun was shining .', 'v. 发出光；反射光，闪耀；出类拔萃，表现突出；露出；照耀；显露；出众; n. 光亮，光泽；好天气；擦亮；晴天；擦皮鞋；鬼把戏或诡计', '/ʃaɪn/', 'shine', 5);
INSERT INTO `words` VALUES (27853, 'We\'ll ship your order to the address we print on your cheques.', 'v. 运送，乘船；以船运送; n. 船；舰；太空船', '/ʃip | ʃɪp/', 'ship', 5);
INSERT INTO `words` VALUES (27854, 'The goods are ready for shipment.', 'n. 装货；装载的货物', '/\'ʃipmənt | \'ʃɪpm(ə)nt | \'ʃɪpmənt/', 'shipment', 5);
INSERT INTO `words` VALUES (27855, 'I have to wear a shirt and tie to work.', 'n. 衬衫；汗衫，内衣', '/ʃə:t | ʃɜːt | ʃɝt/', 'shirt', 5);
INSERT INTO `words` VALUES (27856, 'Jake stood shivering in the cold air.', 'v&n. 战栗,发抖', '/\'ʃivə | \'ʃɪvə | \'ʃɪvɚ/', 'shiver', 5);
INSERT INTO `words` VALUES (27857, 'She was shaking with shock and humiliation.', 'n. 休克；震惊；震动；打击；禾束堆; v. 使休克；使震惊；使震动；使受电击；把…堆成禾束堆; adj. 浓密的；蓬乱的', '/ʃɔk | ʃɒk | ʃɑk/', 'shock', 5);
INSERT INTO `words` VALUES (27858, 'I sat down and took off my shoes and socks.', 'n. 鞋；蹄铁；外胎; v. 给……穿上鞋；穿……鞋', '/ʃu: | ʃuː | ʃu/', 'shoe', 5);
INSERT INTO `words` VALUES (27859, 'Police shot one suspect when he pulled a gun on them.', 'v. 射击，射中；拍摄；发芽；使爆炸；给…注射; n. 射击；摄影；狩猎；急流', '/ʃu:t | ʃuːt | ʃut/', 'shoot', 5);
INSERT INTO `words` VALUES (27860, 'a barber’s shop', 'n. 商店；店铺; v. 购物', '/ʃɔp | ʃɒp | ʃɑp/', 'shop', 5);
INSERT INTO `words` VALUES (27861, 'The girl had only worked for the shopkeeper for three days when she packed him in.', 'n. 店主，老板', '/\'ʃɔp,ki:pə | \'ʃɒpkiːpə | \'ʃɑp\'kipɚ/', 'shopkeeper', 5);
INSERT INTO `words` VALUES (27862, 'We could see a boat about a mile from shore.', 'v. 支撑，使稳住；用支柱撑住; n. 海滨；支柱', '/ʃɔ: | ʃɔː | ʃɔr/', 'shore', 5);
INSERT INTO `words` VALUES (27863, 'a short meeting', 'adj. 短的；不足的；矮的，低的; n. 短；缺乏；短路；短裤; adv. 不足；突然；唐突地', '/ʃɔ:t | ʃɔːt | ʃɔrt/', 'short', 5);
INSERT INTO `words` VALUES (27864, 'There is no heating available due to fuel shortages.', 'n. 缺乏，缺少；不足', '/\'ʃɔ:tidʒ | \'ʃɔːtɪdʒ | \'ʃɔrtɪdʒ/', 'shortage', 5);
INSERT INTO `words` VALUES (27865, 'Peter was painfully aware of his own shortcomings.', 'n. 缺点；短处', '/\'ʃɔ:t\'cʌmiŋ | \'ʃɔːtkʌmɪŋ | \'ʃɔrtkʌmɪŋ/', 'shortcoming', 5);
INSERT INTO `words` VALUES (27866, 'a secretary who takes shorthand (= writes in shorthand )', 'n. 速记；速记法; adj. 速记法的', '/\'ʃɔ:thænd | \'ʃɔːthænd | \'ʃɔrthænd/', 'shorthand', 5);
INSERT INTO `words` VALUES (27867, 'Ms Jones will be back shortly.', 'adv. 立刻；简短地；唐突地', '/\'ʃɔ:tli | \'ʃɔːtlɪ | \'ʃɔrtli/', 'shortly', 5);
INSERT INTO `words` VALUES (27868, 'In the opening shot, we see Travolta’s feet walking down the sidewalk.', 'n. 发射；炮弹；射手；镜头; adj. 用尽的；破旧的；杂色的，闪光的; v. 射击（shoot的过去式和过去分词）', '/ʃɒt | ʃɑt/', 'shot', 5);
INSERT INTO `words` VALUES (27869, 'She tapped the driver on the shoulder.', 'n. 肩，肩膀；肩部; v. 肩负，承担', '/\'ʃəuldə | \'ʃəʊldə | \'ʃoldɚ/', 'shoulder', 5);
INSERT INTO `words` VALUES (27870, 'There’s no need to shout! I can hear you!', 'v. 呼喊；喊叫；大声说; n. 呼喊；呼叫', '/ʃaut | ʃaʊt/', 'shout', 5);
INSERT INTO `words` VALUES (27871, 'He shoved her towards the car.', 'v. 挤；强使；撞；猛推; n. 推；挤', '/ʃʌv/', 'shove', 5);
INSERT INTO `words` VALUES (27872, 'Why does the phone always ring when I’m in the shower?', 'n. 淋浴；（倾泻般出现的）一阵，一大批；阵雨; v. 大量地给予；把……弄湿', '/\'ʃauə | \'ʃaʊə | \'ʃaʊɚ/', 'shower', 5);
INSERT INTO `words` VALUES (27873, 'Malcolm is a shrewd businessman.', 'adj. 精明的；狡猾的；机灵的; n. 精明（的人）；机灵（的人）', '/ʃru:d | ʃruːd | ʃrud/', 'shrewd', 5);
INSERT INTO `words` VALUES (27874, 'I’m worried about washing that shirt in case it shrinks.', 'v. 起皱； 收缩；退缩， 畏缩', '/ʃrɪŋk/', 'shrink', 5);
INSERT INTO `words` VALUES (27875, 'I just shrugged my shoulders and ignored him.', 'v. 耸肩，耸肩表示; n. 耸肩', '/ʃrʌɡ | ʃrʌg/', 'shrug', 5);
INSERT INTO `words` VALUES (27876, 'Shut the window, Ellen!', 'v. 关闭；停业；幽禁; n. 关闭; adj. 关闭的；围绕的', '/ʃʌt/', 'shut', 5);
INSERT INTO `words` VALUES (27877, 'There are a few things you should check before pressing the shutter release.', 'n. 快门；百叶窗；关闭物；遮板; v. 为…装百叶窗；以百叶窗遮闭', '/\'ʃʌtə | \'ʃʌtɚ/', 'shutter', 5);
INSERT INTO `words` VALUES (27878, 'He took the Washington - New York shuttle.', 'n. 航天飞机；穿梭；梭子；穿梭班机、公共汽车等; v. 使穿梭般来回移动；短程穿梭般运送', '/\'ʃʌtl | \'ʃʌt(ə)l/', 'shuttle', 5);
INSERT INTO `words` VALUES (27879, 'He was a quiet shy man.', 'adj. 害羞的；畏缩的，胆怯的; v. 投；畏缩；惊退；厌恶; n. 投掷；惊跳', '/ʃai | ʃaɪ/', 'shy', 5);
INSERT INTO `words` VALUES (27880, 'Fuel is cheaper on the French side of the border.', 'n. 旁边，侧面；坡，岸；一边/侧/方; v. 支持', '/said | saɪd/', 'side', 5);
INSERT INTO `words` VALUES (27881, 'A strong gust of wind blew the car sideways into the ditch.', 'adv&adj. 向旁边(的),侧身,横着(的),斜着(的)', '/\'saidweiz | \'saɪdweɪz | \'saɪdwez/', 'sideways', 5);
INSERT INTO `words` VALUES (27882, 'The siege lasted almost four months.', 'n. 围攻；包围；围城；不断袭击；长期努力; vt. 围攻；包围', '/si:dʒ | siːdʒ | sidʒ/', 'siege', 5);
INSERT INTO `words` VALUES (27883, '‘Well, there’s nothing we can do about it now,’ she sighed.', 'v. 叹息，叹气; n. 叹息，叹气', '/sai | saɪ/', 'sigh', 5);
INSERT INTO `words` VALUES (27884, 'Anne’s sight is very good for someone of her age.', 'n. 视力；景象；眼界；见解; v. 看见；瞄准; adj. 见票即付的；即席的', '/sait | saɪt/', 'sight', 5);
INSERT INTO `words` VALUES (27885, 'She swam and sunbathed, went sightseeing and relaxed.', 'n. 观光；游览; adj. 观光的；游览的; v. 观光（sightsee的ing形式）；游览', '/\'saitsi:iŋ | \'saɪtsiːɪŋ | \'saɪtsiɪŋ/', 'sightseeing', 5);
INSERT INTO `words` VALUES (27886, 'a sign on the door', 'n. 标记,招牌;征兆,迹象v.签名(于),署名(于)', '/saɪn/', 'sign', 5);
INSERT INTO `words` VALUES (27887, 'At a prearranged signal the lights went out.', 'n. 信号,暗号; v. 发信号,用信号通知', '/\'sɪgn(ə)l | \'sɪgnl/', 'signal', 5);
INSERT INTO `words` VALUES (27888, 'Her signature is totally illegible (= cannot be read ) .', 'n. 签名,署名,签字', '/\'signətʃə | \'sɪgnətʃə | \'sɪgnətʃɚ/', 'signature', 5);
INSERT INTO `words` VALUES (27889, 'Ideas about the social significance of religion have changed over time.', 'n. 意义,含义;重要性,重要的', '/siɡ\'nifikəns | sɪg\'nɪfɪk(ə)ns | sɪɡ\'nɪfɪkəns/', 'significance', 5);
INSERT INTO `words` VALUES (27890, 'His most significant political achievement was the abolition of the death penalty.', 'adj. 有意义的;重大的,重要的', '/sig\'nifikənt | sɪg\'nɪfɪk(ə)nt | sɪɡ\'nɪfɪkənt/', 'significant', 5);
INSERT INTO `words` VALUES (27891, 'Some tribes use special facial markings to signify status.', 'v. 表示,意味;要紧,有重要性', '/\'signifai | \'sɪgnɪfaɪ | \'sɪɡnɪfaɪ/', 'signify', 5);
INSERT INTO `words` VALUES (27892, 'There was a brief silence before anyone answered.', 'n. 沉默；寂静；缄默；不谈；无声状态; v. 使沉默；使安静；压制；消除噪音; int. 安静！；别作声！', '/\'sailəns | \'saɪləns/', 'silence', 5);
INSERT INTO `words` VALUES (27893, 'But the brittleness of silicon limits its uses.', 'n. [化学] 硅；硅元素', '/\'silikən, -kɔn | \'sɪlɪk(ə)n | \'sɪlɪkən/', 'silicon', 5);
INSERT INTO `words` VALUES (27894, 'pure silk stockings', 'n. 丝绸；蚕丝；丝织物; adj. 丝的；丝绸的；丝制的; vi. （玉米）处于长须的阶段中', '/silk | sɪlk/', 'silk', 5);
INSERT INTO `words` VALUES (27895, 'Stop asking silly questions.', 'adj. 愚蠢的；不明事理的；没头脑的; n. 傻瓜', '/\'sɪlɪ | \'sɪli/', 'silly', 5);
INSERT INTO `words` VALUES (27896, 'The silver spoon tarnished.', 'n. 银;银器;银币; v. 镀银', '/\'silvə | \'sɪlvə | \'sɪlvɚ/', 'silver', 5);
INSERT INTO `words` VALUES (27897, 'We have similar tastes in music.', 'adj. (to)相似的,类似的', '/\'similə | \'sɪmɪlə | \'sɪməlɚ/', 'similar', 5);
INSERT INTO `words` VALUES (27898, 'a simple but effective solution to the problem', 'adj. 简单的;单纯的,直率的;迟钝的,头脑简单的', '/\'simpl | \'sɪmp(ə)l | \'sɪmpl/', 'simple', 5);
INSERT INTO `words` VALUES (27899, 'Mona wrote with a beautiful simplicity of style.', 'n. 简单,简易;朴素;直率,单纯', '/sim\'plisiti | sɪm\'plɪsɪtɪ | sɪm\'plɪsəti/', 'simplicity', 5);
INSERT INTO `words` VALUES (27900, 'an attempt to simplify the tax system', 'v. 简化,使单纯', '/\'simplifai | \'sɪmplɪfaɪ/', 'simplify', 5);
INSERT INTO `words` VALUES (27901, 'Some students lose marks simply because they don’t read the question properly.', 'adv. 简单地;完全,简直;仅仅,只不过;朴素地', '/\'simpli | \'sɪmplɪ | \'sɪmpli/', 'simply', 5);
INSERT INTO `words` VALUES (27902, 'a machine that simulates conditions in space', 'v. 模仿,模拟;假装,冒充', '/\'simjuleit | \'sɪmjʊleɪt | \'sɪmjulet/', 'simulate', 5);
INSERT INTO `words` VALUES (27903, 'They grabbed each other’s hands in simultaneous panic.', 'adj. 同时的,同时存在的', '/,siməl\'teiniəs | ,sɪm(ə)l\'teɪnɪəs | ,saɪml\'tenɪəs/', 'simultaneous', 5);
INSERT INTO `words` VALUES (27904, 'She needed to confess her sins and ask for forgiveness.', 'n. 罪恶；罪孽；过失; v. 犯罪；犯过失', '/sin | sɪn/', 'sin', 5);
INSERT INTO `words` VALUES (27905, 'a warm-hearted, sincere man', 'adj. 诚挚的， 诚恳的； 忠实的， 忠诚的', '/sɪn\'sɪə | sɪn\'sɪr/', 'sincere', 5);
INSERT INTO `words` VALUES (27906, 'She can sing beautifully.', 'v. 唱歌；歌颂；鸣叫；呼号; n. 演唱；鸣声；呼啸声', '/sɪŋ/', 'sing', 5);
INSERT INTO `words` VALUES (27907, 'A single tree gave shade from the sun.', 'adj. 单一的；单身的；单程的; n. 一个；单打；单程票; v. 选出', '/\'siŋɡl | \'sɪŋg(ə)l | \'sɪŋɡl/', 'single', 5);
INSERT INTO `words` VALUES (27908, 'the singular form of the noun', 'adj. 单数的；单一的；非凡的；异常的; n. 单数', '/\'siŋɡjulə | \'sɪŋgjʊlə | \'sɪŋɡjəlɚ/', 'singular', 5);
INSERT INTO `words` VALUES (27909, 'Their motorboat struck a rock and began to sink.', 'v. 下沉；消沉；渗透; n. 水槽；洗涤槽；污水坑', '/siŋk | sɪŋk/', 'sink', 5);
INSERT INTO `words` VALUES (27910, 'She poured more wine and took a sip .', 'n. 抿；小口喝；单列直插式组件; v. 啜饮', '/sip | sɪp/', 'sip', 5);
INSERT INTO `words` VALUES (27911, '‘Report back to me in an hour, sergeant.’ ‘Yes, sir.’', 'n. 先生；（用于姓名前）爵士；阁下；（中小学生对男教师的称呼）先生；老师', '/sɜː | sɝ/', 'sir', 5);
INSERT INTO `words` VALUES (27912, 'the wail of the ambulance sirens', 'n. 警报声， 警报器 A', '/\'saɪrən/', 'siren', 5);
INSERT INTO `words` VALUES (27913, 'Janet and Abby are sisters.', 'n. 姐，妹；护士长；修女，女教士', '/\'sɪstə | \'sɪstɚ/', 'sister', 5);
INSERT INTO `words` VALUES (27914, 'The parliament building sits in a large square.', 'v. 坐；位于; n. (Sit)人名；(东南亚国家华语)硕；(罗)西特', '/sit | sɪt/', 'sit', 5);
INSERT INTO `words` VALUES (27915, 'an archaeological site', 'n. 地点；位置；场所; v. 设置；为…选址', '/sait | saɪt/', 'site', 5);
INSERT INTO `words` VALUES (27916, 'His hotel is situated in one of the loveliest places on the Loire.', 'adj. 位于…的；处于…境遇的; v. 使位于；使处于（situate的过去分词）', '/\'sitjueitid, -tʃu- | \'sɪtjʊeɪtɪd | \'sɪtʃuetɪd/', 'situated', 5);
INSERT INTO `words` VALUES (27917, 'I explained the situation to everyone.', 'n. 情况；形势；处境；位置', '/,sitju\'eiʃən, -tʃu- | sɪtjʊ\'eɪʃ(ə)n | ,sɪtʃu\'eʃən/', 'situation', 5);
INSERT INTO `words` VALUES (27918, 'He’s a small boy, about John’s size.', 'n. 大小；尺寸; adj. 一定尺寸的; v. 依大小排列', '/saiz | saɪz/', 'size', 5);
INSERT INTO `words` VALUES (27919, 'The children skated on the frozen pond.', 'v. 滑冰；滑过; n. 溜冰；冰鞋', '/skeit | skeɪt | sket/', 'skate', 5);
INSERT INTO `words` VALUES (27920, 'We agreed on a skeleton outline of the proposal.', 'n. 骨架，骨骼；纲要；骨瘦如柴的人; adj. 骨骼的；骨瘦如柴的；概略的', '/\'skelitən | \'skelɪt(ə)n | \'skɛlɪtn/', 'skeleton', 5);
INSERT INTO `words` VALUES (27921, 'Not all theory that we read in this course is skeptical.', 'adj. 怀疑的；怀疑论的，不可知论的', '/\'skeptikəl | \'skeptɪkəl | \'skɛptɪkl/', 'skeptical', 5);
INSERT INTO `words` VALUES (27922, '...thumbnail sketches of heads of state and political figures.', 'n. 素描；略图；梗概; v. 画素描或速写', '/sketʃ | skɛtʃ/', 'sketch', 5);
INSERT INTO `words` VALUES (27923, 'ski slopes', 'n. 滑雪橇; v. 滑雪; adj. 滑雪（用）的', '/ski:, ʃi: | skiː | ski/', 'ski', 5);
INSERT INTO `words` VALUES (27924, 'Skilled craftsmen, such as carpenters, are in great demand.', 'adj. 熟练的；有技能的；需要技能的', '/skild | skɪld/', 'skilled', 5);
INSERT INTO `words` VALUES (27925, 'I like making things by hand because my mother is very skillful, and I liked staying with her when I was young.', 'adj. 熟练的；巧妙的', '/\'skilful | \'skɪlfəl/', 'skillful', 5);
INSERT INTO `words` VALUES (27926, 'Julie skimmed the sports page.', 'v. 略读；撇去…的浮物；从…表面飞掠而过；去除；（为逃税而）隐瞒（部分收入）; n. 撇；撇去的东西；表层物；瞒报所得的收入; adj. 脱脂的；撇去浮沫的；表层的', '/skim | skɪm/', 'skim', 5);
INSERT INTO `words` VALUES (27927, 'She had thick black hair and smooth dark skin.', 'n. 皮肤；外皮; v. 剥皮', '/skin | skɪn/', 'skin', 5);
INSERT INTO `words` VALUES (27928, 'They saw the man with a little girl skipping along behind him.', 'v. 跳跃；跳绳；遗漏；跳读; n. 跳跃；跳读', '/skip | skɪp/', 'skip', 5);
INSERT INTO `words` VALUES (27929, 'She wore a white blouse and a plain black skirt.', 'n. 裙子; v. 绕过，回避；位于…边缘', '/skə:t | skɜːt | skɝt/', 'skirt', 5);
INSERT INTO `words` VALUES (27930, 'Her husband was later treated for a fractured skull.', 'n. 头盖骨，脑壳', '/skʌl/', 'skull', 5);
INSERT INTO `words` VALUES (27931, 'The skyscraper towers into the clouds.', 'n. 摩天楼，超高层大楼；特别高的东西', '/\'skai,skreipə | \'skaɪskreɪpə | \'skaɪ\'skrepɚ/', 'skyscraper', 5);
INSERT INTO `words` VALUES (27932, 'Keep the rope slack until I tell you to pull it.', 'adj. 松弛的；疏忽的；不流畅的; v. 松懈；减弱; n. 煤末；峡谷; adv. 马虎地；缓慢地', '/slæk/', 'slack', 5);
INSERT INTO `words` VALUES (27933, 'We heard a car door slam.', 'v. 砰地关上；猛力抨击; n. 猛击；砰然声', '/slæm/', 'slam', 5);
INSERT INTO `words` VALUES (27934, 'Sarah slapped Aaron across the face.', 'v. 拍击；侮辱；掌击；掴…的耳光; n. 掴；侮辱；掌击；拍打声; adv. 直接地；猛然地；恰好', '/slæp/', 'slap', 5);
INSERT INTO `words` VALUES (27935, 'Hundreds of innocent civilians had been slaughtered by government troops.', 'v. 屠宰，屠杀；杀戮；使惨败; n. 屠宰，屠杀；杀戮；消灭', '/\'slɔ:tə | \'slɔːtə | \'slɔtɚ/', 'slaughter', 5);
INSERT INTO `words` VALUES (27936, 'a slave to fashion', 'n. 奴隶；从动装置; v. 苦干；拼命工作', '/sleiv | sleɪv/', 'slave', 5);
INSERT INTO `words` VALUES (27937, 'I usually sleep on my back.', 'v. 睡，睡觉; n. 睡眠', '/sli:p | sliːp | slip/', 'sleep', 5);
INSERT INTO `words` VALUES (27938, 'a dress with long sleeves', 'n. [机] 套筒，[机] 套管；袖子，[服装] 袖套; vt. 给……装袖子；给……装套筒', '/sli:v | sliːv | sliv/', 'sleeve', 5);
INSERT INTO `words` VALUES (27939, 'She is slender and stylish.', 'adj. 细长的；苗条的；微薄的', '/\'slendə | \'slɛndɚ/', 'slender', 5);
INSERT INTO `words` VALUES (27940, 'pizza slices', 'n. 薄片；部分；菜刀，火铲; v. 切下；把…分成部分；将…切成薄片', '/slais | slaɪs/', 'slice', 5);
INSERT INTO `words` VALUES (27941, 'a slide show', 'n. 滑动；幻灯片；滑梯；雪崩; v. 滑动；滑落；不知不觉陷入', '/slaɪd/', 'slide', 5);
INSERT INTO `words` VALUES (27942, 'a slight improvement', 'adj. 轻微的，少量的；脆弱的；细长的；不重要的; v. 轻视，忽略；怠慢; n. 怠慢；轻蔑', '/slait | slaɪt/', 'slight', 5);
INSERT INTO `words` VALUES (27943, 'a slim young woman', 'adj. 苗条的；修长的；微小的；差的; v. 使…体重减轻；使…苗条; n. (Slim)人名；(阿拉伯)萨利姆；(英、西)斯利姆', '/slim | slɪm/', 'slim', 5);
INSERT INTO `words` VALUES (27944, 'Wright slipped but managed to keep hold of the ball.', 'v. 滑动；滑倒；犯错；失足；减退; n. 滑，滑倒；片，纸片；错误；下跌；事故; adj. 滑动的；有活结的；活络的; abbr. 串行线路接口协议，是旧式的协议（Serial Line Interface Protocol）', '/slip | slɪp/', 'slip', 5);
INSERT INTO `words` VALUES (27945, '...a pair of old slippers.', 'n. 拖鞋; vt. 用拖鞋打', '/\'slipə | \'slɪpə | \'slɪpɚ/', 'slipper', 5);
INSERT INTO `words` VALUES (27946, 'In places, the path can be wet and slippery.', 'adj. 滑的；狡猾的；不稳定的', '/\'slipəri | \'slɪp(ə)rɪ | \'slɪpəri/', 'slippery', 5);
INSERT INTO `words` VALUES (27947, 'Guy slit open the envelope.', 'v. 撕裂；使有狭缝; n. 裂缝；投币口', '/slit | slɪt/', 'slit', 5);
INSERT INTO `words` VALUES (27948, 'an advertising slogan', 'n. 标语；呐喊声', '/\'sləuɡən | \'sləʊg(ə)n | \'slogən/', 'slogan', 5);
INSERT INTO `words` VALUES (27949, 'a steep slope', 'n. 斜坡；倾斜；斜率；扛枪姿势; v. 倾斜；逃走', '/sləup | sləʊp | slop/', 'slope', 5);
INSERT INTO `words` VALUES (27950, 'He dropped a coin into the slot and dialled.', 'n. 位置；狭槽；水沟；硬币投币口; v. 跟踪；开槽于', '/slɔt | slɒt | slɑt/', 'slot', 5);
INSERT INTO `words` VALUES (27951, 'The car was travelling at a very slow speed.', 'adj. 慢的,不活跃的; v. (down)(使)放慢,减速', '/sləu | sləʊ | sloʊ/', 'slow', 5);
INSERT INTO `words` VALUES (27952, 'The slum must be inside you.', 'v. （为猎奇或救济等）去贫民窟; n. 贫民窟；陋巷；脏乱的地方', '/slʌm/', 'slum', 5);
INSERT INTO `words` VALUES (27953, 'He leaned forward with a sly smile.', 'adj. 狡猾的；淘气的；诡密的; n. (Sly)人名；(英)斯莱', '/slai | slaɪ/', 'sly', 5);
INSERT INTO `words` VALUES (27954, 'The smart kids get good grades and go off to college.', 'adj. 聪明的；巧妙的；敏捷的；厉害的；潇洒的；剧烈的；时髦的; n. (Smart)人名；(法)斯马尔；(英、德)斯马特', '/smɑːt | smɑrt/', 'smart', 5);
INSERT INTO `words` VALUES (27955, 'Vandals had smashed all the windows.', 'v. 粉碎；使破产；溃裂; n. 破碎；扣球；冲突；大败; adj. 了不起的；非常轰动的；出色的', '/smæʃ/', 'smash', 5);
INSERT INTO `words` VALUES (27956, 'I can smell burning.', 'v. 嗅，闻；有…气味; n. 气味，嗅觉；臭味', '/smel | smɛl/', 'smell', 5);
INSERT INTO `words` VALUES (27957, 'her smiling face', 'v. 微笑; n. 微笑；笑容；喜色', '/smail | smaɪl/', 'smile', 5);
INSERT INTO `words` VALUES (27958, 'Cars cause pollution, both smog and acid rain.', 'n. 烟雾', '/smɔɡ, smɔ:ɡ | smɒg | smɑːɡ/', 'smog', 5);
INSERT INTO `words` VALUES (27959, 'cigarette smoke', 'n. 烟；抽烟；无常的事物; v. 冒烟，吸烟；抽烟；弥漫', '/sməuk | sməʊk | smok/', 'smoke', 5);
INSERT INTO `words` VALUES (27960, 'My message is \"If you try to smuggle drugs you are stupid.\"', 'v. 走私；偷运', '/\'smʌɡl | \'smʌg(ə)l | \'smʌgl/', 'smuggle', 5);
INSERT INTO `words` VALUES (27961, 'I grabbed a quick snack.', 'n. 小吃，快餐；一份，部分; v. 吃快餐，吃点心', '/snæk/', 'snack', 5);
INSERT INTO `words` VALUES (27962, 'A snake slithered across our path.', 'n. 蛇；阴险的人; v. 迂回前进', '/sneik | sneɪk | snek/', 'snake', 5);
INSERT INTO `words` VALUES (27963, 'A twig snapped under my feet.', 'v. 突然折断，拉断；猛咬；啪地关上; n. 猛咬；劈啪声；突然折断; adj. 突然的', '/snæp/', 'snap', 5);
