INSERT INTO `words` VALUES (27965, 'You little sneak!', 'v. 溜；鬼鬼祟祟做事；向老师打小报告; n. 鬼鬼祟祟的人；偷偷摸摸的行为；告密者; adj. 暗中进行的', '/sni:k | sniːk | snik/', 'sneak', 5);
