INSERT INTO `words` VALUES (27967, 'He opened the milk and sniffed it.', 'v. 嗅；嗤之以鼻; n. 吸，闻；嗤之以鼻；气味；以鼻吸气；吸气声', '/snif | snɪf/', 'sniff', 5);
INSERT INTO `words` VALUES (27968, 'Her family seems snobbish.', 'adj. 势利的', '/\'snɒbɪʃ | \'snɑbɪʃ/', 'snobbish', 5);
