INSERT INTO `words` VALUES (27970, 'The snowstorm added to our difficulties.', 'n. 暴风雪；雪暴', '/\'snəustɔ:m | \'snəʊstɔːm | \'snostɔrm/', 'snowstorm', 5);
INSERT INTO `words` VALUES (27971, 'The so-called experts couldn’t tell us what was wrong.', 'adj. 所谓的， 号称的', '/ˌsəu\'kɔːld | ,so\'kɔld/', 'so-called', 5);
INSERT INTO `words` VALUES (27972, 'Soak the clothes in cold water.', 'v. 吸收，吸入；沉浸在（工作或学习中）；使……上下湿透; n. 浸；湿透；大雨', '/səuk | səʊk | sok/', 'soak', 5);
INSERT INTO `words` VALUES (27973, 'Wash thoroughly with soap and water .', 'n. 肥皂; v. 将肥皂涂在……上；对……拍马屁（俚语）', '/səup | səʊp | sop/', 'soap', 5);
INSERT INTO `words` VALUES (27974, 'Adam’s smile sent her spirits soaring .', 'v. 高飞；高耸；往上飞舞; n. 高飞；高涨', '/sɔ: | sɔː | sɔr/', 'soar', 5);
INSERT INTO `words` VALUES (27975, 'He began sobbing uncontrollably .', 'v. 啜泣，呜咽；（风等）发出呜咽声; n. 啜泣，呜咽', '/sɔb | sɒb | sɑb/', 'sob', 5);
INSERT INTO `words` VALUES (27976, 'He’s a nice guy when he’s sober.', 'adj. 冷静的，清醒的；未醉的; v. 使严肃；使醒酒，使清醒; n. (Sober)人名；(英)索伯', '/\'səubə | \'səʊbə | \'sobɚ/', 'sober', 5);
