INSERT INTO `words` VALUES (27987, 'Roses grow well in a clay soil.', 'n. 土地；土壤；国家；粪便；务农；温床; v. 弄脏；污辱', '/sɔil | sɒɪl | sɔɪl/', 'soil', 5);
