INSERT INTO `words` VALUES (28006, 'His daughter, Louise, is by now a college sophomore.', 'n. 大学二年级生；（美）有二年经验的人; adj. 二年级的；二年级学生的', '/\'sɔfəmɔ: | \'sɒfəmɔː | \'sɑfəmɔr/', 'sophomore', 5);
INSERT INTO `words` VALUES (28007, 'I had a sore throat and aching limbs.', 'adj. 疼痛的，痛心的；剧烈的，极度的；恼火的，发怒的；厉害的，迫切的; n. 溃疡，痛处；恨事，伤心事', '/sɔ: | sɔː | sɔr/', 'sore', 5);
INSERT INTO `words` VALUES (28008, 'the family’s joys and sorrows', 'n. 悲伤；懊悔；伤心事; v. 懊悔；遗憾；感到悲伤', '/\'sɔrəu, \'sɔ:- | \'sɒrəʊ | sɑro/', 'sorrow', 5);
INSERT INTO `words` VALUES (28009, 'Most of the victims developed psychological problems of one sort or another (= of various different types ) .', 'n. 种类；方式；品质; v. 分类；协调；交往', '/sɔ:t | sɔːt | sɔrt/', 'sort', 5);
