INSERT INTO `words` VALUES (28011, 'Several earlier studies had sounded similar warnings .', 'v. 听（诊）；测量，测…深；使发声；试探；宣告; n. 声音，语音；噪音；海峡；吵闹；听力范围；[医] 探条; adj. 健全的，健康的；合理的；可靠的；有效彻底的; adv. 彻底地，充分地', '/saund | saʊnd/', 'sound', 5);
INSERT INTO `words` VALUES (28012, 'homemade tomato soup', 'n. 汤，羹；马力; v. 加速；增加马力', '/su:p | suːp | sup/', 'soup', 5);
INSERT INTO `words` VALUES (28013, 'Rachel sampled the wine. It was sour.', 'adj. 酸的；发酵的；刺耳的；酸臭的；讨厌的; v. 发酵；变酸；厌烦; n. 酸味；苦事', '/\'sauə | saʊə | \'saʊɚ/', 'sour', 5);
INSERT INTO `words` VALUES (28014, 'They get their money from various sources.', 'n. 来源；水源；原始资料', '/sɔ:s | sɔːs | sɔrs/', 'source', 5);
INSERT INTO `words` VALUES (28015, 'Which way is south?', 'n. 南方，南边；南部; adv. 在南方，向南方; adj. 南的，南方的', '/sauθ, sauð | saʊθ/', 'south', 5);
