INSERT INTO `words` VALUES (28018, '...some 500 kilometres to the southwest of Johannesburg.', 'n. 西南方; adj. 西南的; adv. 往西南；来自西南', '/,sauθ\'west | ,saʊθ\'west | ,saʊθ\'wɛst/', 'southwest', 5);
INSERT INTO `words` VALUES (28019, 'Lithuania and Armenia signed a treaty in Vilnius recognizing each other as independent sovereign states.', 'adj. 至高无上的；有主权的；拥有最高统治权的；不折不扣的；极好的; n. 君主；独立国；最高统治者', '/\'sɔvərin, \'sʌv- | \'sɒvrɪn | sɑvrɪn/', 'sovereign', 5);
INSERT INTO `words` VALUES (28020, 'Sow the seeds in late March.', 'v. 播种；散布；使密布; n. 母猪', '/səu | səʊ | so/', 'sow', 5);
