INSERT INTO `words` VALUES (28027, 'She said that she could only spare 35 minutes for our meeting.', 'v. 节约，吝惜；饶恕；分出，分让; adj. 多余的；瘦的；少量的; n. 剩余；备用零件', '/spεə | speə | spɛr/', 'spare', 5);
INSERT INTO `words` VALUES (28028, 'sparks from the fire', 'n. 火花；朝气；闪光; v. 发动；鼓舞；求婚', '/spɑ:k | spɑːk | spɑrk/', 'spark', 5);
INSERT INTO `words` VALUES (28029, 'the sparkle of the diamonds', 'n. 闪耀；火花；活力; v. 使闪耀；使发光', '/\'spɑ:kl | \'spɑːk(ə)l | \'spɑrkl/', 'sparkle', 5);
