INSERT INTO `words` VALUES (28036, 'His speciality is international law.', 'n. (specialty)特性，性质；专业/长；特产', '/,speʃi\'æləti | ,speʃɪ\'ælɪtɪ | ,spɛʃɪ\'æləti/', 'speciality', 5);
INSERT INTO `words` VALUES (28037, '...a University professor who specializes in the history of the Russian empire.', 'v. (specialise)(in)专攻,专门研究,专业化', '/\'speʃəlaiz | \'spɛʃəlaɪz/', 'specialize', 5);
INSERT INTO `words` VALUES (28038, 'Our specialty is clam chowder.', 'n. 特产； 特色菜；专业； 专长', '/ˌspeʃi\'æləti | \'spɛʃəlti/', 'specialty', 5);
INSERT INTO `words` VALUES (28039, 'Seven species of birds of prey have been observed.', 'n. (物)种,种类', '/\'spi:ʃi:z, -si:z | \'spiːʃiːz; -ʃɪz; \'spiːs- | \'spiʃiz/', 'species', 5);
INSERT INTO `words` VALUES (28040, 'games suitable for specific age groups', 'adj. 明确的,具体的;特定的,特有的', '/spi\'sifik | spə\'sɪfɪk | spɪ\'sɪfɪk/', 'specific', 5);
INSERT INTO `words` VALUES (28041, 'The bolts met all the engineering specifications .', 'n. 详述;(常pl.)规格,说明书,规范', '/,spesifi\'keiʃən | ,spesɪfɪ\'keɪʃ(ə)n | \'spɛsəfə\'keʃən/', 'specification', 5);
INSERT INTO `words` VALUES (28042, 'Payments will be made for a specified number of months.', 'v. 指定,详细说明', '/\'spesəfai, -si- | \'spesɪfaɪ | \'spɛsɪfaɪ/', 'specify', 5);
INSERT INTO `words` VALUES (28043, 'a blood specimen', 'n. 标本,样本', '/\'spesimin, -əmən | \'spesɪmɪn | \'spɛsəmən/', 'specimen', 5);
INSERT INTO `words` VALUES (28044, 'a multimedia dance and opera spectacle', 'n. (pl.)眼镜;场面,景象;奇观,壮观', '/\'spektək(ə)l | \'spɛktəkl/', 'spectacle', 5);
