INSERT INTO `words` VALUES (28048, 'She refused to speculate.', 'v. 思索；推测vt.投机；思索，推测', '/\'spekjuleit | \'spekjʊleɪt | \'spɛkjə\'let/', 'speculate', 5);
INSERT INTO `words` VALUES (28049, 'He has to make a lot of after-dinner speeches .', 'n. 演讲；讲话；[语] 语音；演说', '/spi:tʃ | spiːtʃ | spitʃ/', 'speech', 5);
INSERT INTO `words` VALUES (28050, 'I got caught speeding on the A40 yesterday.', 'v. 超速，加速；加速，迅速前行；兴隆; n. 速度，速率；迅速，快速；昌盛，繁荣', '/spi:d | spiːd | spid/', 'speed', 5);
INSERT INTO `words` VALUES (28051, 'How do you spell ‘juice’?', 'v. 拼，拼写；意味着；招致；拼成；迷住；轮值; n. 符咒；一段时间；魅力', '/spel | spɛl/', 'spell', 5);
INSERT INTO `words` VALUES (28052, 'Her spelling has improved.', 'n. 拼写；拼字；拼法; v. 拼写；意味着（spell的ing形式）；迷住', '/\'speliŋ | \'spelɪŋ | \'spɛlɪŋ/', 'spelling', 5);
INSERT INTO `words` VALUES (28053, 'I can’t afford to spend any more money this week.', 'v. 度过，消磨（时光）；花费；浪费；用尽; n. 预算', '/spend | spɛnd/', 'spend', 5);
INSERT INTO `words` VALUES (28054, 'Because the earth spins, it is not a perfect sphere.', 'n. 范围；球体; vt. 包围；放入球内；使…成球形; adj. 球体的', '/sfiə | sfɪə | sfɪr/', 'sphere', 5);
INSERT INTO `words` VALUES (28055, 'a spicy tomato sauce', 'adj. 加很多香料的；(口味)浓郁的', '/\'spaisi | \'spaɪsɪ | \'spaɪsi/', 'spicy', 5);
