INSERT INTO `words` VALUES (28057, 'Katie almost spilled her milk.', 'v. 使溢出，使流出；使摔下; n. 溢出，溅出；溢出量；摔下；小塞子', '/spil | spɪl/', 'spill', 5);
INSERT INTO `words` VALUES (28058, 'The plane’s propellers were spinning.', 'v. 旋转；纺纱；吐丝；晕眩; n. 旋转；疾驰', '/spin | spɪn/', 'spin', 5);
