INSERT INTO `words` VALUES (28060, '...a spiral staircase.', 'adj. 螺旋形的; n. 螺旋，螺线; v. 螺旋上升；盘旋', '/\'spaiərəl | \'spaɪr(ə)l | \'spaɪrəl/', 'spiral', 5);
INSERT INTO `words` VALUES (28061, 'His spirits were so low (= he was so sad ) that he refused to answer his phone.', 'n. 精神;志气;(pl.)情绪,心情;(pl.)酒精', '/\'spirit | \'spɪrɪt/', 'spirit', 5);
