INSERT INTO `words` VALUES (28069, 'a White House spokesman', 'n. 发言人', '/\'spəuksmən | \'spəʊksmən | \'spoksmən/', 'spokesman', 5);
INSERT INTO `words` VALUES (28070, 'Clean the rug by sponging it gently.', 'v. 抹掉；用海绵擦拭；讨得; n. 海绵；海绵状物', '/spʌndʒ | spʌn(d)ʒ/', 'sponge', 5);
INSERT INTO `words` VALUES (28071, 'You cannot get a work visa without an American sponsor.', 'n. 赞助者；主办者；保证人; v. 赞助；发起', '/\'spɔnsə | \'spɒnsə | \'spɑnsɚ/', 'sponsor', 5);
