INSERT INTO `words` VALUES (28073, 'He spooned instant coffee into two of the mugs.', 'n. 匙，勺子；一杓的量; v. 用匙舀；使成匙状', '/spu:n | spuːn | spʊn/', 'spoon', 5);
INSERT INTO `words` VALUES (28074, 'the sport of falconry', 'n. 运动；游戏；娱乐；运动会；玩笑; v. 游戏; adj. 运动的', '/spɔ:t | spɔːt | spɔrt/', 'sport', 5);
