INSERT INTO `words` VALUES (28080, 'Sprinkle the meat with salt and place in the pan.', 'n. 撒，洒；少量; v. 洒；微雨；散置', '/\'spriŋkl | \'sprɪŋk(ə)l | \'sprɪŋkl/', 'sprinkle', 5);
INSERT INTO `words` VALUES (28081, 'Move the pots outside when the seeds begin to sprout.', 'v. 发芽；长芽; n. 芽；萌芽；苗芽', '/spraut | spraʊt/', 'sprout', 5);
INSERT INTO `words` VALUES (28082, 'The crowd’s reaction only acted as a spur.', 'n. 鼓舞，刺激；马刺；山坡; v. 骑马疾驰；给予刺激', '/spə: | spɜː | spɝ/', 'spur', 5);
