INSERT INTO `words` VALUES (28084, 'a large square room', 'adj. 平方的；正方形的；直角的；正直的; v. 使成方形；与…一致; n. 平方；广场；正方形; adv. 成直角地', '/skwεə | skweə | skwɛr/', 'square', 5);
INSERT INTO `words` VALUES (28085, 'She smiled as he squeezed her hand.', 'v. 挤；紧握；勒索; n. 压榨；紧握；拥挤；佣金', '/skwi:z | skwiːz | skwiz/', 'squeeze', 5);
INSERT INTO `words` VALUES (28086, 'It was moving fast like a squirrel, but it was as loud as a bear.', 'n. 松鼠；松鼠毛皮; v. 贮藏', '/\'skwə:rəl, \'skwi-, \'skwʌ- | \'skwɪr(ə)l | \'skwɝrəl/', 'squirrel', 5);
INSERT INTO `words` VALUES (28087, 'He was stabbed to death in a fight.', 'v. 刺；刺伤；戳；刺穿；直入; n. 刺；戳；尝试；突发的一阵', '/stæb/', 'stab', 5);
