INSERT INTO `words` VALUES (28089, 'Our stable abuts against his dwelling.', 'n. 马厩；牛棚; adj. 稳定的；牢固的；坚定的; v. 被关在马厩', '/\'steibl | \'steɪb(ə)l | \'stebl/', 'stable', 5);
