INSERT INTO `words` VALUES (28092, 'The entire staff has done an outstanding job this year.', 'n. 职员；参谋；棒；支撑; adj. 职员的；行政工作的; v. 供给人员；给…配备职员', '/stɑ:f, stæf | stɑːf | stæf/', 'staff', 5);
INSERT INTO `words` VALUES (28093, 'We’re getting to the stage where we hardly ever go out together.', 'n. 阶段；舞台；戏剧；驿站; v. 举行；上演；筹划', '/steidʒ | steɪdʒ | stedʒ/', 'stage', 5);
INSERT INTO `words` VALUES (28094, 'He managed to stagger home.', 'v. 蹒跚；使交错；使犹豫; n. 蹒跚；交错安排; adj. 交错的；错开的', '/\'stæɡə | \'stægə | \'stægɚ/', 'stagger', 5);
