INSERT INTO `words` VALUES (28100, 'For a dollar stake, you can win up to $1,000,000.', 'n. 桩，棍子；赌注；火刑；奖金; v. 资助，支持；系…于桩上；把…押下打赌', '/steik | steɪk | stek/', 'stake', 5);
INSERT INTO `words` VALUES (28101, 'French bread goes stale (= becomes stale ) very quickly.', 'adj. 陈腐的；不新鲜的; v. 变陈旧；撒尿；变得不新鲜; n. 尿', '/steil | steɪl | stel/', 'stale', 5);
INSERT INTO `words` VALUES (28102, 'celery stalks', 'n. （植物的）茎，秆；（支持叶子、果实和花的）梗，柄；追踪；高视阔步; v. 追踪，潜近；高视阔步', '/stɔ:k | stɔːk | stɔk/', 'stalk', 5);
INSERT INTO `words` VALUES (28103, 'a market stall', 'n. 货摊；畜栏；托辞; v. 停止，停转；拖延', '/stɔ:l | stɔːl | stɔl/', 'stall', 5);
INSERT INTO `words` VALUES (28104, 'a 29-cent stamp', 'n. 邮票；印记；标志；跺脚; v. 铭记；标出；盖章于…；贴邮票于…；用脚踩踏', '/stæmp/', 'stamp', 5);
