INSERT INTO `words` VALUES (28107, 'a discussion of marriage from the standpoint of women', 'n. 立场；观点', '/\'stændpɔint | \'stæn(d)pɒɪnt | \'stændpɔɪnt/', 'standpoint', 5);
INSERT INTO `words` VALUES (28108, 'staples like flour and rice', 'n. 主要产品；订书钉；主题；主食; adj. 主要的，大宗生产的；常用的；纺织纤维的; v. 把…分级；钉住', '/\'steipl | \'steɪp(ə)l | \'stepl/', 'staple', 5);
INSERT INTO `words` VALUES (28109, 'She sat there staring into space (= looking for a long time at nothing ) .', 'v. 凝视，盯着看；显眼; n. 凝视；注视', '/stεə | steə | stɛr/', 'stare', 5);
INSERT INTO `words` VALUES (28110, 'Sorry, I didn’t mean to startle you.', 'v. 使吓一跳；使惊奇; n. 惊愕；惊恐', '/\'stɑ:tl | \'stɑːt(ə)l | \'stɑrtl/', 'startle', 5);
INSERT INTO `words` VALUES (28111, 'Thousands of people will starve if food doesn’t reach the city.', 'v. 饿死；挨饿；渴望', '/stɑ:v | stɑːv | stɑrv/', 'starve', 5);
