INSERT INTO `words` VALUES (28118, 'How did you manage to drive into a stationary vehicle?', 'adj. 固定的；静止的；定居的；常备军的; n. 不动的人；驻军', '/\'steiʃənəri | \'steɪʃ(ə)n(ə)rɪ | \'steʃənɛri/', 'stationary', 5);
INSERT INTO `words` VALUES (28119, 'a letter on hotel stationery', 'n. 文具；信纸', '/\'steiʃənəri | \'steɪʃ(ə)n(ə)rɪ | \'steʃənɛri/', 'stationery', 5);
INSERT INTO `words` VALUES (28120, 'The report contains a great deal of statistical information.', 'adj. 统计的；统计学的', '/stə\'tistikəl | stə\'tɪstɪk(ə)l | stə\'tɪstɪkl/', 'statistical', 5);
INSERT INTO `words` VALUES (28121, 'statistics for earnings by different age groups', 'n. 统计数据； 统计学', '/stə\'tɪstɪks/', 'statistics', 5);
