INSERT INTO `words` VALUES (28134, 'long-stemmed wine glasses', 'n. 干；茎；船首；血统; v. 阻止；除去…的茎；给…装柄', '/stem | stɛm/', 'stem', 5);
INSERT INTO `words` VALUES (28135, 'a video of baby’s first steps', 'n. 步，脚步；步骤；步伐；梯级; v. 踏，踩；走', '/step | stɛp/', 'step', 5);
INSERT INTO `words` VALUES (28136, 'a stereo with good speakers', 'n. 立体声；立体声系统；铅版；立体照片; adj. 立体的；立体声的；立体感觉的', '/\'steri,əu, \'stiə-, \'sti:- | \'sterɪəʊ; \'stɪərɪəʊ | \'stɛrɪo/', 'stereo', 5);
INSERT INTO `words` VALUES (28137, 'There\'s always been a stereotype about successful businessmen.', 'v. 使用铅版；套用老套，使一成不变; n. 陈腔滥调，老套；铅版', '/\'steriəutaip, \'stiə- | \'sterɪə(ʊ)taɪp; \'stɪərɪə(ʊ)- | \'stɛrɪətaɪp/', 'stereotype', 5);
INSERT INTO `words` VALUES (28138, 'It is placed in the stern of a boat.', 'n. 船尾；末端; adj. 严厉的；坚定的', '/stə:n | stɜːn | stɝn/', 'stern', 5);
INSERT INTO `words` VALUES (28139, 'race stewards', 'n. 管家；乘务员；膳务员；工会管事; vi. 当服务员；当管事; vt. 管理', '/\'stju:əd, \'stjuəd | \'stjuːəd | \'stuɚd/', 'steward', 5);
INSERT INTO `words` VALUES (28140, 'This stamp won’t stick properly.', 'v. 刺，戳；伸出；粘贴; n. 棍；手杖；呆头呆脑的人', '/stɪk/', 'stick', 5);
INSERT INTO `words` VALUES (28141, 'There’s some sticky stuff in your hair.', 'adj. 粘的；粘性的', '/\'stiki | \'stɪkɪ | \'stɪki/', 'sticky', 5);
