INSERT INTO `words` VALUES (28143, 'Her interest in art was stimulated by her father.', 'v. 刺激；鼓舞，激励', '/\'stimjuleit | \'stɪmjʊleɪt | \'stɪmjə\'let/', 'stimulate', 5);
INSERT INTO `words` VALUES (28144, 'She felt the sting of tears in her eyes.', 'n. 刺痛；讽刺，刺激；刺毛; v. 刺；驱使；使…苦恼；使…疼痛', '/stiŋ | stɪŋ/', 'sting', 5);
