INSERT INTO `words` VALUES (28146, 'He had to have ten stitches in his head.', 'n. 针脚，线迹；一针; v. 缝，缝合', '/stitʃ | stɪtʃ/', 'stitch', 5);
INSERT INTO `words` VALUES (28147, 'We have a huge stock of quality carpets on sale.', 'n. 股份，股票；库存；血统；树干；家畜; adj. 存货的，常备的；平凡的; v. 进货；备有；装把手于…', '/stɒk | stɑk/', 'stock', 5);
INSERT INTO `words` VALUES (28148, 'I want you stuffed in my stocking.', 'n. 长袜', '/\'stɔkiŋ | \'stɒkɪŋ | \'stɑkɪŋ/', 'stocking', 5);
INSERT INTO `words` VALUES (28149, 'I was so hungry my stomach hurt.', 'n. 胃；腹部；胃口; v. 忍受；吃下', '/\'stʌmək/', 'stomach', 5);
INSERT INTO `words` VALUES (28150, 'a stone wall', 'n. 石头；结石；[宝] 宝石; adj. 石的，石制的; v. 向扔石块；用石头铺', '/stəun | stəʊn | ston/', 'stone', 5);
INSERT INTO `words` VALUES (28151, 'a bar stool', 'n. 凳子；粪便；厕所; v. 长新枝；分檗', '/stu:l | stuːl | stʊl/', 'stool', 5);
INSERT INTO `words` VALUES (28152, 'We had to stoop to pass through the low entrance.', 'v. 弯腰；屈服；堕落; n. 弯腰，屈背；屈服', '/stu:p | stuːp | stʊp/', 'stoop', 5);
INSERT INTO `words` VALUES (28153, 'Stop throwing those stones!', 'v. 停止；堵塞；断绝; n. 停止；车站；障碍；逗留', '/stɔp | stɒp | stɑp/', 'stop', 5);
INSERT INTO `words` VALUES (28154, 'the storage of highly radioactive material', 'n. 存储；仓库；贮藏所', '/\'stɔridʒ | \'stɔːrɪdʒ | \'stɔrɪdʒ/', 'storage', 5);
INSERT INTO `words` VALUES (28155, 'At Christmas the stores stay open late.', 'n. 商店；储备，贮藏；仓库; v. 贮藏，储存', '/stɔ: | stɔː | stɔr/', 'store', 5);
INSERT INTO `words` VALUES (28156, 'A staircase leads to the upper storey .', 'n. [建] 楼层；叠架的一层', '/\'stɔ:ri | \'stɔːrɪ | \'stɔri/', 'storey', 5);
INSERT INTO `words` VALUES (28157, 'The weather forecast is for severe storms tonight.', 'n. 暴风雨；大动荡; v. 起风暴；横冲直撞；狂怒咆哮', '/stɔ:m | stɔːm | stɔrm/', 'storm', 5);
INSERT INTO `words` VALUES (28158, 'a book of short stories', 'n. 故事；小说；新闻报道；来历；假话; vt. 用历史故事画装饰; vi. 说谎', '/\'stɔ:ri | \'stɔːrɪ | \'stɔri/', 'story', 5);
INSERT INTO `words` VALUES (28159, 'a wood-burning stove', 'n. 火炉；窑；温室; vt. 用火炉烤', '/stəuv | stəʊv | stov/', 'stove', 5);
INSERT INTO `words` VALUES (28160, 'a long, straight road', 'adj. 直的；连续的；笔直的；正直的；整齐的；异性恋的; adv. 直接地；不断地；立即；坦率地; n. 直；直线；直男，直女，异性恋者', '/streɪt | stret/', 'straight', 5);
INSERT INTO `words` VALUES (28161, 'This area of law is far from straightforward (= complicated ) .', 'adj. 简单的；坦率的；明确的；径直的; adv. 直截了当地；坦率地', '/,streit\'fɔ:wəd | streɪt\'fɔːwəd | ,stret\'fɔrwɚd/', 'straightforward', 5);
INSERT INTO `words` VALUES (28162, 'I couldn’t look after him any more; the strain was too much for me.', 'n. 张力；拉紧；负担；扭伤；血缘; v. 拉紧；尽力', '/streɪn | stren/', 'strain', 5);
INSERT INTO `words` VALUES (28163, 'strange noises', 'adj. 奇怪的；陌生的；外行的; adv. 奇怪地；陌生地，冷淡地; n. (Strange)人名；(英)斯特兰奇；(瑞典、塞)斯特朗格', '/streindʒ | streɪn(d)ʒ | strendʒ/', 'strange', 5);
INSERT INTO `words` VALUES (28164, 'Children must not talk to strangers.', 'n. 陌生人；外地人；局外人', '/\'streidʒə | \'streɪn(d)ʒə | \'strendʒɚ/', 'stranger', 5);
INSERT INTO `words` VALUES (28165, 'soldiers with grenades strapped to their belts', 'v. 用带捆绑；用皮条抽打；约束; n. 带；皮带；磨刀皮带；鞭打', '/stræp/', 'strap', 5);
INSERT INTO `words` VALUES (28166, 'the government’s long-term economic strategy', 'n. 战略，策略', '/\'strætidʒi | ˈstrætədʒɪ | \'strætədʒi/', 'strategy', 5);
INSERT INTO `words` VALUES (28167, 'She sipped her lemonade through a straw.', 'n. 稻草；吸管；一文不值的东西; adj. 稻草的；无价值的', '/strɔ: | strɔː | strɔ/', 'straw', 5);
INSERT INTO `words` VALUES (28168, '...strawberries and cream.', 'n. 草莓；草莓色', '/\'strɔ:bəri | \'strɔːb(ə)rɪ | \'strɔbɛri/', 'strawberry', 5);
INSERT INTO `words` VALUES (28169, 'A stream of cold air rushed through the open door.', 'n. 溪流；流动；潮流；光线; v. 流；涌进；飘扬', '/stri:m | striːm | strim/', 'stream', 5);
INSERT INTO `words` VALUES (28170, 'efforts to streamline the production process', 'v. 把…做成流线型；使现代化；组织；使合理化；使简单化; n. 流线；流线型; adj. 流线型的', '/\'striːmlaɪn | \'strimlaɪn/', 'streamline', 5);
INSERT INTO `words` VALUES (28171, 'I’m trying to build up my strength .', 'n. 力量；力气；兵力；长处', '/streŋθ, streŋkθ | streŋθ; streŋkθ | strɛŋθ/', 'strength', 5);
INSERT INTO `words` VALUES (28172, 'Our friendship has steadily strengthened over the years.', 'v. 加强；巩固', '/\'streŋθən, \'streŋkθən | \'streŋθ(ə)n; -ŋkθ(ə)n | \'strɛŋθn/', 'strengthen', 5);
INSERT INTO `words` VALUES (28173, 'a strenuous climb', 'adj. 紧张的；费力的；奋发的；艰苦的；热烈的', '/\'strenjuəs | \'strenjʊəs | \'strɛnjuəs/', 'strenuous', 5);
INSERT INTO `words` VALUES (28174, 'Your headaches are due to stress.', 'n. 压力；强调；紧张；重要性；重读; v. 强调；使紧张；加压力于；用重音读', '/stres | strɛs/', 'stress', 5);
INSERT INTO `words` VALUES (28175, 'Carl sat up in bed, yawned, and stretched.', 'v. 伸展,张开；（大量地）使用，消耗（金钱，时间）；使竭尽所能；使全力以赴；; n. 伸展，延伸', '/stretʃ | strɛtʃ/', 'stretch', 5);
INSERT INTO `words` VALUES (28176, 'a strict teacher', 'adj. 严格的；绝对的；精确的；详细的', '/strikt | strɪkt/', 'strict', 5);
INSERT INTO `words` VALUES (28177, 'Paco reached the door in only three strides.', 'n. 大步；步幅；进展; v. 跨过；大踏步走过；跨坐在…', '/straid | straɪd/', 'stride', 5);
INSERT INTO `words` VALUES (28178, 'Money is a major cause of strife in many marriages.', 'n. 冲突；争吵；不和', '/straif | straɪf/', 'strife', 5);
INSERT INTO `words` VALUES (28179, 'She fell heavily, striking her head against the side of the boat.', 'v. 打，打击；罢工；敲，敲击；抓；打动；穿透; n. 罢工；打击；殴打', '/straik | straɪk/', 'strike', 5);
INSERT INTO `words` VALUES (28180, 'a dark man with striking features', 'adj. 显著的，突出的，惊人的；打击的；罢工的; v. 打（strike的ing形式）', '/\'straikiŋ | \'straɪkɪŋ/', 'striking', 5);
INSERT INTO `words` VALUES (28181, 'Her key hung on a string around her neck.', 'n. 线，弦，细绳；一串，一行', '/strɪŋ/', 'string', 5);
INSERT INTO `words` VALUES (28182, 'Strip the beds and wash the sheets.', 'v. 剥夺；剥去；脱去衣服; n. 带；条状；脱衣舞', '/strip | strɪp/', 'strip', 5);
INSERT INTO `words` VALUES (28183, 'a shirt with black and white stripes', 'n. 条纹，斑纹；种类; v. 加条纹于…', '/straip | straɪp/', 'stripe', 5);
INSERT INTO `words` VALUES (28184, 'He strives hard to keep himself very fit.', 'v. 努力；奋斗；抗争', '/straiv | straɪv/', 'strive', 5);
INSERT INTO `words` VALUES (28185, 'She died following a massive stroke.', 'n. （游泳或划船的）划；中风；（打、击等的）一下；冲程；（成功的）举动；尝试；轻抚; v. （用笔等）画；轻抚；轻挪；敲击；划尾桨；划掉；（打字时）击打键盘', '/strəʊk | strok/', 'stroke', 5);
INSERT INTO `words` VALUES (28186, NULL, 'n. 漫步；闲逛；巡回演出; v. 散步；闲逛；巡回演出', '/strəul | strəʊl | strol/', 'stroll', 5);
INSERT INTO `words` VALUES (28187, 'He was a big strong man.', 'adj. 坚强的；强壮的；牢固的；擅长的; adv. 强劲地；猛烈地; n. (Strong)人名；(英)斯特朗', '/strɔŋ, strɔ:ŋ | strɒŋ | strɔŋ/', 'strong', 5);
INSERT INTO `words` VALUES (28188, 'challenges to the existing power structure', 'n. 结构；构造；建筑物; v. 组织；构成；建造', '/\'strʌktʃə | \'strʌktʃɚ/', 'structure', 5);
INSERT INTO `words` VALUES (28189, 'The team has been struggling all season.', 'v. 奋斗，努力；挣扎; n. 努力，奋斗；竞争', '/\'strʌɡl | \'strʌg(ə)l/', 'struggle', 5);
INSERT INTO `words` VALUES (28190, 'Why are you so stubborn?', 'adj. 顽固的；顽强的；难处理的', '/\'stʌbən | \'stʌbɚn/', 'stubborn', 5);
INSERT INTO `words` VALUES (28191, 'Warren\'s eldest son is an art student.', 'n. 学生；学者', '/\'stju:dənt, \'stu:- | \'stjuːd(ə)nt | \'studnt/', 'student', 5);
INSERT INTO `words` VALUES (28192, 'Depardieu is making a film with one of the big Hollywood studios.', 'n. 工作室；[广播][电视] 演播室；画室；电影制片厂', '/\'stju:diəu, \'stu:- | \'stjuːdɪəʊ | \'studɪo/', 'studio', 5);
INSERT INTO `words` VALUES (28193, 'I’ve got some sticky stuff on my shoe.', 'n. 东西；材料；填充物；素材资料; v. 塞满；填塞；让吃饱', '/stʌf/', 'stuff', 5);
INSERT INTO `words` VALUES (28194, 'In her hurry, she stumbled and spilled the milk all over the floor.', 'v. 踌躇，蹒跚；失足；犯错; n. 绊倒；蹒跚而行', '/\'stʌmbl | \'stʌmb(ə)l/', 'stumble', 5);
INSERT INTO `words` VALUES (28195, 'Redfern stunned the crowd with a last-minute goal.', 'v. 使震惊；打昏；给以深刻的印象; n. 昏迷；打昏；惊倒；令人惊叹的事物', '/stʌn/', 'stun', 5);
INSERT INTO `words` VALUES (28196, 'stupid mistakes', 'adj. 愚蠢的；麻木的；乏味的; n. 傻瓜，笨蛋', '/\'stju:pid, \'stu:- | \'stjuːpɪd | \'stupɪd/', 'stupid', 5);
INSERT INTO `words` VALUES (28197, 'a sturdy young man', 'adj. 坚定的；强健的；健全的; n. 羊晕倒病', '/\'stə:di | \'stɜːdɪ | \'stɝdi/', 'sturdy', 5);
INSERT INTO `words` VALUES (28198, 'an attempt to use Japanese management style in a European business', 'n. 风格；时尚；类型；字体; v. 设计；称呼；使合潮流', '/stail | staɪl/', 'style', 5);
INSERT INTO `words` VALUES (28199, 'Paul has strong opinions on most subjects.', 'n. 主题;学科; adj. 隶属的;易遭..的; v. 使隶属', '/\'sʌbdʒikt, -dʒe-, səb\'dʒekt | ˈsʌbdʒɪkt | ˈsʌbdʒekt/', 'subject', 5);
INSERT INTO `words` VALUES (28200, 'As a critic, he is far too subjective.', 'adj. 主观(上)的，个人的', '/səb\'dʒektiv | səb\'dʒektɪv | səb\'dʒɛktɪv/', 'subjective', 5);
INSERT INTO `words` VALUES (28201, 'a nuclear submarine', 'n. 潜水艇; adj. 水底的,海底的', '/\'sʌbməri:n, ,sʌbmə\'ri:n | \'sʌbməriːn; sʌbmə\'riːn | ,sʌbmə\'rin/', 'submarine', 5);
INSERT INTO `words` VALUES (28202, 'The tunnel entrance was submerged by rising sea water.', 'v. 沉没,淹没;潜入', '/səb\'mə:dʒ | səb\'mɜːdʒ | səb\'mɝdʒ/', 'submerge', 5);
INSERT INTO `words` VALUES (28203, 'In desperation, Mrs. Jones submitted to an operation on her right knee to relieve the pain.', 'v. 使服从；主张；呈递', '/səb\'mit | səb\'mɪt/', 'submit', 5);
INSERT INTO `words` VALUES (28204, 'a subordinate officer', 'adj. (to)次要的,从属的;下级的', '/sə\'bɔ:dinət, -neit, sə\'bɔ:dineit | sə\'bɔːdɪnət | səˈbɔːdɪnɪt (for n. &adj.) ; səˈbɔːdɪˌnet (for v.)/', 'subordinate', 5);
INSERT INTO `words` VALUES (28205, 'I\'ve personally never subscribed to the view that either sex is superior to the other.', 'v. (to)订阅，订购；同意vt.捐助，赞助', '/səb\'skraib | səb\'skraɪb/', 'subscribe', 5);
INSERT INTO `words` VALUES (28206, 'These skills were passed on to subsequent generations.', 'adj. 随后的,后来的', '/\'sʌbsikwənt | \'sʌbsɪkw(ə)nt | \'sʌbsɪkwənt/', 'subsequent', 5);
INSERT INTO `words` VALUES (28207, 'European farmers are planning a massive demonstration against farm subsidy cuts.', 'n. 补助金；津贴费', '/\'sʌbsidi | \'sʌbsɪdɪ | \'sʌbsədi/', 'subsidy', 5);
INSERT INTO `words` VALUES (28208, 'The leaves were covered with a strange sticky substance.', 'n. 物质；实质；资产；主旨', '/\'sʌbstəns | \'sʌbst(ə)ns/', 'substance', 5);
INSERT INTO `words` VALUES (28209, 'We have the support of a substantial number of parents.', 'adj. 大量的；实质的；内容充实的; n. 本质；重要材料', '/səb\'stænʃəl | səb\'stænʃ(ə)l | səbˈstænʃəl/', 'substantial', 5);
INSERT INTO `words` VALUES (28210, 'Germany brought on a substitute at half time.', 'n. 代用品；代替者; v. 替代', '/\'sʌbstitju:t, -tu:t | \'sʌbstɪtjuːt | \'sʌbstɪtut/', 'substitute', 5);
INSERT INTO `words` VALUES (28211, 'The pictures are similar, but there are subtle differences between them.', 'adj. 微妙的；精细的；敏感的；狡猾的；稀薄的', '/\'sʌtl | \'sʌt(ə)l/', 'subtle', 5);
INSERT INTO `words` VALUES (28212, 'Mandy subtracted the date of birth from the date of death.', 'v. (from)减(去)', '/səb\'trækt/', 'subtract', 5);
INSERT INTO `words` VALUES (28213, 'a London suburb', 'n. 郊区；边缘', '/\'sʌbə:b | \'sʌbɜːb | \'sʌbɝb/', 'suburb', 5);
INSERT INTO `words` VALUES (28214, 'the New York City subway', 'n. 地铁；地道; vi. 乘地铁', '/\'sʌbwei | \'sʌbweɪ | \'sʌbwe/', 'subway', 5);
INSERT INTO `words` VALUES (28215, 'She wanted to be the first woman to climb Mount Qomolangma, and she almost succeeded.', 'v. 成功；继承，接替; v. 接替；继…之后', '/sək\'si:d | sək\'siːd | sək\'sid/', 'succeed', 5);
INSERT INTO `words` VALUES (28216, 'The experiment was a big success.', 'n. 成就，成功；成功的事物，有成就的人', '/sək\'ses | sək\'sɛs/', 'success', 5);
INSERT INTO `words` VALUES (28217, 'The operation was successful.', 'adj. 圆满的；顺利的；成功的', '/sək\'sesful | sək\'sesfʊl; -f(ə)l | sək\'sɛsfl/', 'successful', 5);
INSERT INTO `words` VALUES (28218, 'She won the championship four times in succession.', 'n. 连续,系列;继任,继承', '/sək\'seʃən | sək\'seʃ(ə)n | sək\'sɛʃən/', 'succession', 5);
INSERT INTO `words` VALUES (28219, 'The team has had five successive victories.', 'adj. 接连的,连续的', '/sək\'sesiv | sək\'sesɪv | sək\'sɛsɪv/', 'successive', 5);
INSERT INTO `words` VALUES (28220, 'His successor died after only 15 months in office.', 'n. 接替的人或事物，继任者', '/sək\'sesə | sək\'sɛsɚ/', 'successor', 5);
INSERT INTO `words` VALUES (28221, 'They waited in silence and sucked their sweets.', 'v. 吸吮；吸取; n. 吮吸', '/sʌk/', 'suck', 5);
INSERT INTO `words` VALUES (28222, 'a sudden change in the weather', 'adj. 突然的，意外的；快速的; n. 突然发生的事', '/\'sʌdən | \'sʌd(ə)n | \'sʌdn/', 'sudden', 5);
INSERT INTO `words` VALUES (28223, 'If the builders don’t fulfil their side of the contract, we’ll sue.', 'v. 控告；请求; n. (Sue)人名；(日)末(名)；(法)休；(英)休(女子教名Susan、Susanna的昵称)', '/sju:, su: | s(j)uː | su/', 'sue', 5);
INSERT INTO `words` VALUES (28224, 'At least he died suddenly and didn’t suffer.', 'v. 遭受；忍受；经历; n. (Suffer)人名；(意)苏费尔', '/\'sʌfə | \'sʌfɚ/', 'suffer', 5);
INSERT INTO `words` VALUES (28225, 'A light lunch will suffice .', 'v. 充足，足够；vt.(食物等)使(某人)满足', '/sə\'fais | sə\'faɪs/', 'suffice', 5);
INSERT INTO `words` VALUES (28226, 'We can only prosecute if there is sufficient evidence.', 'adj. (for)足够的,充分的(比enough拘谨、正式)', '/sə\'fiʃənt | sə\'fɪʃ(ə)nt | səˈfɪʃənt/', 'sufficient', 5);
INSERT INTO `words` VALUES (28227, 'Do you take sugar in your coffee?', 'n. 糖；食糖；甜言蜜语; v. 加糖于；粉饰', '/\'ʃuɡə | \'ʃʊgə | \'ʃʊgɚ/', 'sugar', 5);
INSERT INTO `words` VALUES (28228, 'Any suggestions would be welcome.', 'n. 建议；示意；微量，细微的迹象', '/səɡ\'dʒestʃən | sə\'dʒestʃ(ə)n | sə\'dʒɛstʃən/', 'suggestion', 5);
INSERT INTO `words` VALUES (28229, 'More people commit suicide at Christmas than at any other time.', 'n. 自杀；给自己带来恶劣后果的行为', '/\'sjuisaid | \'s(j)uːɪsaɪd | \'suɪsaɪd/', 'suicide', 5);
INSERT INTO `words` VALUES (28230, 'Whatever your reason for borrowing, we have the loan that suits your needs .', 'v. 适合；使适应; n. 诉讼；恳求；套装，西装；一套外衣', '/sju:t; su:t | sut/', 'suit', 5);
INSERT INTO `words` VALUES (28231, 'We are hoping to find a suitable school.', 'adj. 适当的；相配的', '/\'sju:təbl | \'suːtəb(ə)l | \'sutəbl/', 'suitable', 5);
INSERT INTO `words` VALUES (28232, 'a honeymoon suite', 'n. （一套）家具；套房；组曲；（一批）随员，随从', '/swi:t | swiːt | sut; swit/', 'suite', 5);
INSERT INTO `words` VALUES (28233, 'She knelt down, hands on the thighs, breathe in the smell of sulfur.', 'v. 用硫磺处理; n. 硫磺；硫磺色', '/\'sʌlfə | \'sʌlfɚ/', 'sulfur', 5);
INSERT INTO `words` VALUES (28234, 'Burning sulphur creates poisonous fumes.', 'n. 硫', '/\'sʌlfə/', 'sulphur', 5);
INSERT INTO `words` VALUES (28235, 'He owes me a large sum of money .', 'v. 合计， 总计; n. 总数， 和；金额；算术题', '/sʌm/', 'sum', 5);
INSERT INTO `words` VALUES (28236, 'In the below we summarise annual World Steel Association crude steel production data.', 'v. 概括， 总结', '/\'sʌməraɪz | \'sʌməraiz/', 'summarise', 5);
INSERT INTO `words` VALUES (28237, 'The authors summarize their views in the introduction.', 'v. (summarise)概括,总结', '/\'sʌməraiz | \'sʌməraɪz/', 'summarize', 5);
INSERT INTO `words` VALUES (28238, 'A brief summary is given on a separate sheet.', 'n. 摘要,概要; adj. 概括的,简略的', '/\'sʌm(ə)rɪ | \'sʌməri/', 'summary', 5);
INSERT INTO `words` VALUES (28239, 'We tour by car every summer.', 'n. 夏天，夏季; adj. 夏季的', '/\'sʌmə | \'sʌmɚ/', 'summer', 5);
INSERT INTO `words` VALUES (28240, 'the European summit', 'n. 最高点， 峰顶， 极点；峰会', '/\'sʌmɪt/', 'summit', 5);
INSERT INTO `words` VALUES (28241, 'Robert summoned the waiter for the bill.', 'v. 召唤;传讯,传唤;鼓起(勇气),振作(精神)', '/\'sʌmən/', 'summon', 5);
INSERT INTO `words` VALUES (28242, 'The sky was blue and the sun was shining.', 'n. 太阳; v. 使晒', '/sʌn/', 'sun', 5);
INSERT INTO `words` VALUES (28243, 'I thought we might go for a drive on Sunday.', 'n. 星期日；礼拜日', '/\'sʌndei | ˈsʌndeɪ; ˈsʌndi | ˈsʌnde; ˈsʌndi/', 'sunday', 5);
INSERT INTO `words` VALUES (28244, 'a picture of sunrise over Mount Fuji', 'n. 日出；黎明', '/\'sʌnraiz | \'sʌnraɪz/', 'sunrise', 5);
INSERT INTO `words` VALUES (28245, 'a glorious sunset', 'n. 日落，傍晚', '/\'sʌnset | \'sʌnsɛt/', 'sunset', 5);
INSERT INTO `words` VALUES (28246, 'We had three days of spring sunshine.', 'n. 阳光；愉快；晴天；快活', '/\'sʌnʃain | \'sʌnʃaɪn/', 'sunshine', 5);
INSERT INTO `words` VALUES (28247, 'an old car in super condition', 'adj. 特级的；极好的; n. 特级品，特大号；临时雇员', '/\'sju:pə | \'suːpə; \'sjuː- | \'sʊpɚ/', 'super', 5);
INSERT INTO `words` VALUES (28248, 'The food was superb.', 'adj. 极好的；华丽的；宏伟的; n. (Superb)人名；(罗)苏佩尔布', '/sju\'pə:b, sə- | suː\'pɜːb; sjuː- | /suːˈpɜːrb//', 'superb', 5);
INSERT INTO `words` VALUES (28249, 'They only have the most superficial understanding of prison life.', 'adj. 表面的;肤浅的,浅薄的', '/,suːpə\'fɪʃ(ə)l; ,sjuː- | ,supɚ\'fɪʃl/', 'superficial', 5);
INSERT INTO `words` VALUES (28250, 'a modern building with no superfluous decoration', 'adj. 多余的；不必要的；奢侈的', '/sju\'pə:fluəs | suː\'pɜːflʊəs; sjuː- | sʊ\'pɝflʊəs/', 'superfluous', 5);
INSERT INTO `words` VALUES (28251, 'She had that superior tone of voice.', 'adj. 上级的；优秀的，出众的；高傲的; n. 上级，长官；优胜者，高手；长者', '/sju:\'piriə, sju:pə- | suːˈpɪərɪə | səˈpɪriər/', 'superior', 5);
INSERT INTO `words` VALUES (28252, 'Janet always spoke with an air of superiority.', 'n. 优越，优势；优越性', '/sju:,piəri\'ɔriti, sə- | suː,pɪərɪ\'ɒrɪtɪ; sjuː- | su,pɪrɪ\'ɔrəti/', 'superiority', 5);
INSERT INTO `words` VALUES (28253, 'Most of us do our food shopping in the supermarket.', 'n. 超级市场', '/\'sju:pə,mɑ:kit | \'suːpəmɑːkɪt; \'sjuː- | \'sʊpɚ\'mɑrkɪt/', 'supermarket', 5);
INSERT INTO `words` VALUES (28254, 'supersonic aircraft', 'adj. 超音速的；超声波的; n. 超音速；超声波', '/,sju:pə\'sɔnik | suːpə\'sɒnɪk; sjuː- | ,supɚ\'sɑnɪk/', 'supersonic', 5);
INSERT INTO `words` VALUES (28255, 'the old superstition that walking under a ladder is unlucky', 'n. 迷信', '/,sju:pə\'stiʃən | ,suːpə\'stɪʃ(ə)n; ,sjuː- | ,supɚ\'stɪʃən/', 'superstition', 5);
INSERT INTO `words` VALUES (28256, 'Griffiths closely supervised the research.', 'v. 管理,监督', '/\'sju:pəvaiz | \'suːpəvaɪz; \'sjuː- | \'sʊpɚ\'vaɪz/', 'supervise', 5);
INSERT INTO `words` VALUES (28257, 'Why don’t you come over for supper on Friday?', 'n. 晚餐，晚饭；夜宵', '/\'sʌpə | \'sʌpɚ/', 'supper', 5);
INSERT INTO `words` VALUES (28258, '...people doing extra jobs outside their regular jobs to supplement their incomes.', 'v. 增补，补充; n. 增补，补充；补充物；增刊，副刊', '/英[\'sʌplɪm(ə)nt] 美[\'sʌplɪmənt] | \'sʌplɪm(ə)nt | \'sʌplɪmənt/', 'supplement', 5);
INSERT INTO `words` VALUES (28259, 'The nation’s fuel supplies will not last forever.', 'n. 供给，补给；供应品; v. 供给，提供；补充', '/sə\'plai | sə\'plaɪ/', 'supply', 5);
INSERT INTO `words` VALUES (28260, 'Local people have given us a lot of support in our campaign.', 'n. /vt.支撑;支持;赡养;维持; n. 支持者;支柱', '/sə\'pɔ:t | sə\'pɔːt | sə\'pɔrt/', 'support', 5);
INSERT INTO `words` VALUES (28261, 'There were many more deaths than was first supposed.', 'v. 料想,猜想;假定;conj.假使...结果会怎样', '/sə\'pəuz | sə\'pəʊz | sə\'poz/', 'suppose', 5);
INSERT INTO `words` VALUES (28262, 'The uprising was ruthlessly suppressed.', 'v. 抑制；镇压；废止', '/sə\'pres | sə\'prɛs/', 'suppress', 5);
INSERT INTO `words` VALUES (28263, 'the Supreme Allied Commander in Europe', 'adj. 最高的；至高的；最重要的; n. 至高；霸权', '/sju\'pri:m, sə- | suː\'priːm | suˈprim/', 'supreme', 5);
INSERT INTO `words` VALUES (28264, 'Nearly 10% of the Earth’s surface is covered by ice.', 'n. 表面；表层；外观; adj. 表面的，肤浅的; v. 浮出水面', '/\'sə:fis | \'sɜːfɪs | \'sɝfɪs/', 'surface', 5);
INSERT INTO `words` VALUES (28265, 'a device that protects your computer against electrical surges', 'n. 汹涌；大浪，波涛；汹涌澎湃；巨涌; v. 汹涌；起大浪，蜂拥而来', '/sɜːdʒ | sɝdʒ/', 'surge', 5);
INSERT INTO `words` VALUES (28266, '...a heart surgeon.', 'n. 外科医生', '/\'sə:dʒən | \'sɜːdʒ(ə)n | \'sɝdʒən/', 'surgeon', 5);
INSERT INTO `words` VALUES (28267, 'Dr. Hanson is in surgery.', 'n. 外科；外科手术；手术室；诊疗室', '/\'sə:dʒəri | \'sɜːdʒ(ə)rɪ | \'sɝdʒəri/', 'surgery', 5);
INSERT INTO `words` VALUES (28268, 'He had surpassed all our expectations .', 'v. 超越；胜过，优于；非…所能办到或理解', '/sə\'pɑ:s, -\'pæs | sə\'pɑːs | sə\'pæs/', 'surpass', 5);
INSERT INTO `words` VALUES (28269, 'Any surplus can be trimmed away.', 'n. 剩余；[贸易] 顺差；盈余；过剩; adj. 剩余的；过剩的', '/\'sə:plʌs, -pləs | \'sɜːpləs | \'sɝpləs/', 'surplus', 5);
INSERT INTO `words` VALUES (28270, 'His strange question surprised her.', 'v. 使诧异,使惊异;奇袭; n. 诧异,惊异;奇袭', '/sə\'praiz | sə\'praɪz | sɚ\'praɪz/', 'surprise', 5);
INSERT INTO `words` VALUES (28271, 'Germany surrendered on May 7th, 1945.', 'v. 使投降；放弃；交出；听任; n. 投降；放弃；交出；屈服', '/sə\'rendə | sə\'rɛndɚ/', 'surrender', 5);
INSERT INTO `words` VALUES (28272, 'He glared at the people who surrounded the tent.', 'v. 围绕；包围; n. 围绕物; adj. 环绕立体声的', '/sə\'raund | sə\'raʊnd/', 'surround', 5);
INSERT INTO `words` VALUES (28273, 'I need to work in pleasant surroundings.', 'n. 环境；周围的事物', '/sə\'raundiŋz | sə\'raʊndɪŋz/', 'surroundings', 5);
INSERT INTO `words` VALUES (28274, 'The council conducted a survey of the uses to which farm buildings are put.', 'n. 调查；测量；审视；纵览; v. 调查；勘测；俯瞰', '/sə:\'vei, \'sə:vei, sə- | ˈsəːveɪ; (for v.) səˈveɪ | ˈsɝˌve; (for v.) sɝˈve/', 'survey', 5);
INSERT INTO `words` VALUES (28275, 'The doctors gave him a one in ten chance of survival .', 'n. 幸存,生存;幸存者,残存物', '/sə\'vaivəl | sə\'vaɪv(ə)l | sɚ\'vaɪvl/', 'survival', 5);
INSERT INTO `words` VALUES (28276, '...the sequence of events that left the eight pupils battling to survive in icy seas for over four hours.', 'v. 幸免于,幸存;比…长命', '/sə\'vaiv | sə\'vaɪv | sɚ\'vaɪv/', 'survive', 5);
INSERT INTO `words` VALUES (28277, 'A lot of TV advertising is aimed at susceptible young children.', 'adj. 易受影响的;易受感动的;易受感染的', '/sə\'septəbl | sə\'septɪb(ə)l | sə\'sɛptəbl/', 'susceptible', 5);
INSERT INTO `words` VALUES (28278, 'She strongly suspected he was lying to her.', 'v. 猜想；怀疑；察觉; adj. 可疑的; n. 嫌疑犯', '/sə\'spekt, \'sʌspekt | ˈsʌspekt; (for v.) səˈspekt | sʌspɛkt; (for v.) səˈspɛkt/', 'suspect', 5);
INSERT INTO `words` VALUES (28279, 'Sales of the drug will be suspended until more tests are completed.', 'v. 延缓，推迟；使暂停；使悬浮', '/sə\'spend | sə\'spɛnd/', 'suspend', 5);
INSERT INTO `words` VALUES (28280, 'I can’t say for definite who did it, but I certainly have my suspicions .', 'n. 怀疑，猜疑；一点儿，少量', '/sə\'spiʃən | sə\'spɪʃ(ə)n | sə\'spɪʃən/', 'suspicion', 5);
INSERT INTO `words` VALUES (28281, 'His reluctance to answer my questions made me suspicious .', 'adj. (of)可疑的,多疑的,疑心的', '/sə\'spiʃəs | sə\'spɪʃəs/', 'suspicious', 5);
INSERT INTO `words` VALUES (28282, 'She found it difficult to sustain the children’s interest.', 'v. 维持；支撑，承担；忍受；供养；证实', '/sə\'stein | sə\'steɪn | sə\'sten/', 'sustain', 5);
INSERT INTO `words` VALUES (28283, 'He downed his whisky in one swallow.', 'n. 燕子;吞咽vt.吞,咽;轻信;忍受;vi.咽口水', '/\'swɔləu | \'swɒləʊ | \'swɑlo/', 'swallow', 5);
INSERT INTO `words` VALUES (28284, 'I spent one whole night by a swamp behind the road listening to frogs.', 'n. 沼泽；湿地; v. 使陷于沼泽；使沉没；使陷入困境', '/swɔmp, swɔ:mp | swɒmp | swɑmp/', 'swamp', 5);
INSERT INTO `words` VALUES (28285, 'Toads pursuit of swans, swan disdain said: If I as long as you die!', 'n. 天鹅；天鹅星座; v. 游荡，闲荡', '/swɔn, swɔ:n | swɒn | swɑn/', 'swan', 5);
INSERT INTO `words` VALUES (28286, 'Within minutes the area was swarming with officers who began searching a nearby wood.', 'v. 挤满；成群浮游；云集; n. 蜂群；一大群', '/swɔ:m | swɔːm | swɔrm/', 'swarm', 5);
INSERT INTO `words` VALUES (28287, 'Don’t allow yourself to be swayed by his promises.', 'v. 影响；统治；使摇动; n. 影响；摇摆；统治', '/swei | sweɪ | swe/', 'sway', 5);
INSERT INTO `words` VALUES (28288, 'Don’t swear in front of the children.', 'v. 发誓；咒骂; n. 宣誓；诅咒', '/swεə | sweə | swɛr/', 'swear', 5);
INSERT INTO `words` VALUES (28289, 'I was sweating a lot despite the air conditioning.', 'v. 使出汗；流出；使干苦活；剥削；藉出汗减轻；焦急地期待; n. 汗；水珠；焦急；苦差使', '/swet | swɛt/', 'sweat', 5);
INSERT INTO `words` VALUES (28290, 'Somebody pinched my sweater.', 'n. 毛线衣，运动衫；大量出汗的人，发汗剂', '/\'swetə | \'swɛtɚ/', 'sweater', 5);
INSERT INTO `words` VALUES (28291, 'I swept the papers quickly into the drawer.', 'v. 扫除；猛拉；掸去; n. 打扫，扫除；范围；全胜', '/swi:p | swiːp | swip/', 'sweep', 5);
INSERT INTO `words` VALUES (28292, 'Her ankle was already starting to swell.', 'v. 膨胀；肿胀；隆起; n. 肿胀；隆起; adj. 漂亮的；一流的', '/swel | swɛl/', 'swell', 5);
INSERT INTO `words` VALUES (28293, 'My letter received a swift reply.', 'n. 褐雨燕; adj. 快的；迅速的；敏捷的；立刻的; adv. 迅速地', '/swɪft/', 'swift', 5);
INSERT INTO `words` VALUES (28294, 'Let’s go swimming this afternoon.', 'v. 游泳；漂浮；浸；眩晕; n. 游泳；漂浮；眩晕; adj. 游泳时穿戴的', '/swim | swɪm/', 'swim', 5);
INSERT INTO `words` VALUES (28295, 'kids playing on the swings', 'n. 摇摆；摆动；秋千；音律；涨落; v. 摇摆；转向；悬挂；大摇大摆地行走; adj. 旋转的；悬挂的；强节奏爵士音乐的', '/swiŋ | swɪŋ/', 'swing', 5);
INSERT INTO `words` VALUES (28296, 'The terrorists will switch tactics .', 'v. 转换；用鞭子等抽打; n. 开关；转换；鞭子', '/switʃ | swɪtʃ/', 'switch', 5);
INSERT INTO `words` VALUES (28297, 'The treaty hung like a sword of Damocles over French politics.', 'n. 刀，剑；武力，战争', '/sɔ:d | sɔːd | sɔːrd/', 'sword', 5);
INSERT INTO `words` VALUES (28298, 'The symbol on the packet is a guarantee that the food has been produced organically.', 'n. 象征；符号；标志', '/\'simbəl | \'sɪmb(ə)l | \'sɪmbl/', 'symbol', 5);
INSERT INTO `words` VALUES (28299, '...the incredible beauty and symmetry of a snowflake.', 'n. 对称(性);匀称,整齐', '/\'simitri | \'sɪmɪtrɪ | \'sɪmətri/', 'symmetry', 5);
INSERT INTO `words` VALUES (28300, 'a sympathetic friend', 'adj. 有同情心的；赞同的；n.交感神经', '/,simpə\'θetik | sɪmpə\'θetɪk | ,sɪmpə\'θɛtɪk/', 'sympathetic', 5);
INSERT INTO `words` VALUES (28301, NULL, 'vi. 同情， 体谅； 共鸣， 同感', '/\'sɪmpəθaɪz | \'simpəθaiz/', 'sympathise', 5);
INSERT INTO `words` VALUES (28302, 'I sympathize, but I don’t know how to help.', 'v. (sympathise)(with)同情;共鸣,同感;赞成', '/\'simpəθaiz | \'sɪmpə\'θaɪz/', 'sympathize', 5);
INSERT INTO `words` VALUES (28303, 'Our sympathies are with the families of the victims.', 'n. 同情，同情心；赞同，同感；慰问', '/\'simpəθi | \'sɪmpəθɪ | \'sɪmpəθi/', 'sympathy', 5);
INSERT INTO `words` VALUES (28304, 'Bruckner’s Fifth Symphony', 'n. 交响乐,交响曲', '/\'simfəni | \'sɪmf(ə)nɪ | \'sɪmfəni/', 'symphony', 5);
INSERT INTO `words` VALUES (28305, 'He had been taking part in an international symposium on population.', 'n. 讨论会,专题报告会;专题论文集', '/sim\'pəuziəm | sɪm\'pəʊzɪəm | sɪm\'pozɪəm/', 'symposium', 5);
INSERT INTO `words` VALUES (28306, 'One of the most common symptoms of schizophrenia is hearing imaginary voices.', 'n. (疾病的)症状；(不好事情的)征兆,表征', '/\'simptəm | \'sɪm(p)təm | \'sɪmptəm/', 'symptom', 5);
INSERT INTO `words` VALUES (28307, 'people who suffer from irritable bowel syndrome', 'n. 综合病征；并存特性', '/\'sɪndrəʊm | \'sɪndrəm/', 'syndrome', 5);
INSERT INTO `words` VALUES (28308, 'speech synthesis software', 'n. (pl.syntheses)综合,合成', '/\'sinθisis | \'sɪnθɪsɪs | \'sɪnθəsɪs/', 'synthesis', 5);
INSERT INTO `words` VALUES (28309, 'synthetic chemicals', 'adj. 合成的,人造的;综合的', '/sin\'θetik | sɪn\'θetɪk | sɪn\'θɛtɪk/', 'synthetic', 5);
INSERT INTO `words` VALUES (28310, 'an alarm system', 'n. 系统，体系；制度；方法，方式，步聚', '/\'sistəm | \'sɪstəm/', 'system', 5);
INSERT INTO `words` VALUES (28311, 'They went about their business in a systematic way.', 'adj. (al)系统的,有组织的', '/sɪstə\'mætɪk | \'sɪstə\'mætɪk/', 'systematic', 5);
INSERT INTO `words` VALUES (28312, 'The food was served on long tables.', 'n. 桌子；表格；平地层; v. 制表；搁置；嵌合; adj. 桌子的', '/\'teibl | \'teɪb(ə)l | \'tebl/', 'table', 5);
INSERT INTO `words` VALUES (28313, 'She took a couple of headache tablets .', 'n. 碑；药片；写字板；小块；平板电脑; vt. 用碑牌纪念；将(备忘录等)写在板上；将…制成小片或小块', '/\'tæblɪt | \'tæblət/', 'tablet', 5);
INSERT INTO `words` VALUES (28314, 'The topic of addiction remains something of a taboo in our family.', 'n. 禁忌， 忌讳；禁止 A', '/tə\'buː | tə\'bu/', 'taboo', 5);
INSERT INTO `words` VALUES (28315, '...fishing tackle.', 'n. 滑车；装备；用具；扭倒; v. 处理；抓住；固定；与…交涉', '/\'tækl | \'tæk(ə)l/', 'tackle', 5);
INSERT INTO `words` VALUES (28316, 'You have probably heard of this tactic before.', 'n. (s)策略,战术', '/\'tæktik | \'tæktɪk/', 'tactic', 5);
INSERT INTO `words` VALUES (28317, 'All these questions involve policy and tactics.', 'n. 策略， 战术', '/\'tæktɪks/', 'tactics', 5);
INSERT INTO `words` VALUES (28318, 'His speed earned him the tag of ‘the runner’.', 'n. 标签；名称；结束语；附属物; v. 尾随，紧随；连接；起浑名；添饰', '/tæɡ | tæg/', 'tag', 5);
INSERT INTO `words` VALUES (28319, 'In his youth his father bound him out to a tailor.', 'v. 剪裁；使合适; n. 裁缝', '/\'teilə | \'teɪlə | \'telɚ/', 'tailor', 5);
INSERT INTO `words` VALUES (28320, 'a book of old Japanese folk tales', 'n. 故事；传说；叙述；流言蜚语', '/teil | teɪl | tel/', 'tale', 5);
INSERT INTO `words` VALUES (28321, 'He has a lot of talent , and his work is fresh and interesting.', 'n. 才能；天才；天资', '/\'tælənt/', 'talent', 5);
INSERT INTO `words` VALUES (28322, 'He was young and tall.', 'adj. 高的；长的；过分的；夸大的; adv. 夸大地; n. (Tall)人名；(马里、阿拉伯)塔勒；(芬、罗、瑞典)塔尔；(英)托尔；(土)塔勒', '/tɔ:l | tɔːl | tɔl/', 'tall', 5);
INSERT INTO `words` VALUES (28323, 'Most of the criticism has been pretty tame.', 'adj. 驯服的；平淡的；乏味的；顺从的; v. 驯养；使变得平淡；制服; n. (Tame)人名；(捷)塔梅', '/teim | teɪm/', 'tame', 5);
INSERT INTO `words` VALUES (28324, 'I wish I could get a tan like that.', 'n. （日晒后皮肤的）黝黑色；棕褐色；鞣料；马戏团; v. 鞣（革）；晒成褐色; adj. 黄褐色的；鞣皮的', '/tæn/', 'tan', 5);
INSERT INTO `words` VALUES (28325, 'My hair tangles easily.', 'n. 纠纷；混乱状态; v. 使纠缠；处于混乱状态', '/\'tæŋɡl | \'tæŋg(ə)l/', 'tangle', 5);
INSERT INTO `words` VALUES (28326, 'The water tank is leaking.', 'n. 坦克 A；罐， 槽， 箱', '/tæŋk/', 'tank', 5);
INSERT INTO `words` VALUES (28327, 'A Greek oil tanker has run aground.', 'n. 油轮；运油飞机；油槽车；坦克手', '/\'tæŋkə | \'tæŋkɚ/', 'tanker', 5);
INSERT INTO `words` VALUES (28328, 'He tapped the table nervously with his fingers.', 'v. 轻敲；轻打；装上嘴子; n. 水龙头；轻打', '/tæp/', 'tap', 5);
INSERT INTO `words` VALUES (28329, 'a photo stuck to the wall with tape', 'n. 胶带；磁带；带子；卷尺; v. 录音；用带子捆扎；用胶布把…封住', '/teip | teɪp | tep/', 'tape', 5);
INSERT INTO `words` VALUES (28330, 'high tar cigarettes', 'n. 焦油；柏油；水手; v. 涂以焦油；玷污', '/tɑ: | tɑː | tɑr/', 'tar', 5);
INSERT INTO `words` VALUES (28331, 'There is no target date for completion of the new project.', 'n. 目标；靶子; v. 把……作为目标；规定……的指标；瞄准某物', '/\'tɑ:ɡit | \'tɑːgɪt | \'tɑrɡɪt/', 'target', 5);
