INSERT INTO `words` VALUES (28345, 'The work was tiring and tedious.', 'adj. 沉闷的；冗长乏味的', '/\'ti:diəs, \'ti:dʒəs | \'tiːdɪəs | \'tidɪəs/', 'tedious', 5);
