INSERT INTO `words` VALUES (28349, 'The telephone rang just as I was leaving.', 'n. （美）电话；电话机；电话耳机; v. 打电话', '/\'telifəun | \'telɪfəʊn | \'tɛlə\'fon/', 'telephone', 5);
