INSERT INTO `words` VALUES (28401, 'Paul is very thoughtful.', 'adj. 深思的；体贴的；关切的', '/\'θɔ:tful | \'θɔːtfʊl; -f(ə)l | \'θɔtfl/', 'thoughtful', 5);
