INSERT INTO `words` VALUES (28429, 'The fight ended only with the timely arrival of the police.', 'adj. 及时的,适时的', '/\'taimli | \'taɪmlɪ | \'taɪmli/', 'timely', 5);
INSERT INTO `words` VALUES (28430, 'I was a timid child.', 'adj. 胆怯的,怯懦的', '/\'timid | \'tɪmɪd/', 'timid', 5);
INSERT INTO `words` VALUES (28431, 'an old tin bath', 'n. 罐头；锡; adj. 锡制的; v. 镀锡于', '/tin | tɪn/', 'tin', 5);
INSERT INTO `words` VALUES (28432, 'a tiny community in the Midwest', 'adj. 极小的,微小的', '/\'taini | \'taɪnɪ | \'taɪni/', 'tiny', 5);
INSERT INTO `words` VALUES (28433, 'Did you tip the waiter?', 'v. 给小费；翻倒；倾覆; n. 小费；尖端；小建议，小窍门；轻拍', '/tɪp/', 'tip', 5);
INSERT INTO `words` VALUES (28434, 'As we neared the summit, we were tiring fast.', 'v. 疲劳；厌倦; n. 轮胎；头饰', '/\'taiə | taɪə | \'taɪɚ/', 'tire', 5);
INSERT INTO `words` VALUES (28435, 'He looks tired out (= very tired ) .', 'adj. 疲倦的；厌倦的，厌烦的; v. 疲倦；对…腻烦（tire的过去分词形式）', '/\'taiəd | taɪəd | \'taɪɚd/', 'tired', 5);
INSERT INTO `words` VALUES (28436, 'the whole tiresome business of filling out the forms', 'adj. 烦人的，无聊的；令人讨厌的', '/\'taiəsəm | \'taɪəs(ə)m | \'taɪɚsəm/', 'tiresome', 5);
INSERT INTO `words` VALUES (28437, 'a box of tissues', 'n. 组织；纸巾；薄纱；一套; v. 饰以薄纱；用化妆纸揩去', '/\'tɪʃuː; \'tɪsjuː | \'tɪʃu/', 'tissue', 5);
INSERT INTO `words` VALUES (28438, 'the UK’s 20 best-selling titles', 'n. 书名； 标题；头衔， 称号', '/\'taɪtl/', 'title', 5);
INSERT INTO `words` VALUES (28439, 'She stood up and walked to the window.', 'prep. (表示方向)到；向；(表示间接关系)给', '/tə;tu;tuː/', 'to', 5);
INSERT INTO `words` VALUES (28440, 'I had a piece of toast for breakfast.', 'n. 干杯；烤面包；接受敬酒的人；（在某领域）广受赞誉的人; v. 向…祝酒，为…干杯', '/təʊst | tost/', 'toast', 5);
INSERT INTO `words` VALUES (28441, '...Cuba\'s tobacco crop.', 'n. 烟草，烟叶；烟草制品；抽烟', '/tə\'bækəu | tə\'bækəʊ | tə\'bæko/', 'tobacco', 5);
INSERT INTO `words` VALUES (28442, 'He stubbed his toe (= hurt it by kicking it against something ) on a rock.', 'n. 脚趾；足尖; v. 用脚尖走；以趾踏触', '/təu | təʊ | to/', 'toe', 5);
INSERT INTO `words` VALUES (28443, 'a life of toil', 'v. 艰难地进行， 费力地做; n. 艰辛， 辛苦', '/tɔɪl/', 'toil', 5);
INSERT INTO `words` VALUES (28444, '...slot-machine tokens.', 'n. 表征；代币；记号; adj. 象征的；表意的；作为对某事的保证的; vt. 象征；代表', '/\'təukən | \'təʊk(ə)n | \'tokən/', 'token', 5);
INSERT INTO `words` VALUES (28445, '...his tolerance and understanding of diverse human nature.', 'n. 公差；宽容；容忍；公差', '/\'tɔlərəns | \'tɒl(ə)r(ə)ns | \'tɑlərəns/', 'tolerance', 5);
INSERT INTO `words` VALUES (28446, 'a tolerant society', 'adj. 宽容的；容忍的；有耐药力的', '/\'tɔlərənt | \'tɒl(ə)r(ə)nt | \'tɑlərənt/', 'tolerant', 5);
INSERT INTO `words` VALUES (28447, 'We simply will not tolerate vigilante groups on our streets.', 'v. 忍受；默许；宽恕', '/\'tɔləreit | \'tɒləreɪt | \'tɑləret/', 'tolerate', 5);
INSERT INTO `words` VALUES (28448, 'The death toll has risen to 83.', 'n. 通行费；代价；钟声；伤亡人数; v. 征收；敲钟', '/təʊl | tol/', 'toll', 5);
INSERT INTO `words` VALUES (28449, 'He staked his tomato vines with bamboo.', 'n. 西红柿', '/tə\'mɑ:təu, -\'mei- | tə\'mɑːtəʊ | tə\'meto/', 'tomato', 5);
INSERT INTO `words` VALUES (28450, 'the family tomb', 'n. 坟,冢', '/tu:m | tuːm | tum/', 'tomb', 5);
INSERT INTO `words` VALUES (28451, 'I’ll see you at tomorrow’s meeting.', 'n. 明天；未来; adv. 明天；未来地（等于to-morrow）', '/tə\'mɔrəu, -\'mɔ:- | tə\'mɒrəʊ | tə\'mɔro/', 'tomorrow', 5);
INSERT INTO `words` VALUES (28452, 'I’ve got tons of work to do.', 'n. 吨；很多，大量', '/tʌn, tuŋ | tʌn/', 'ton', 5);
INSERT INTO `words` VALUES (28453, 'Her tone was sharp with anger.', 'n. 语气；色调；音调；音色; v. 增强；用某种调子说', '/təun | təʊn | ton/', 'tone', 5);
INSERT INTO `words` VALUES (28454, 'Joe ran his tongue over his dry lips.', 'n. 舌头；语言; v. 舔；斥责；用舌吹', '/tʌŋ/', 'tongue', 5);
INSERT INTO `words` VALUES (28455, 'I think I’ll go to bed early tonight.', 'adv. 在今晚; n. 今晚', '/tə\'nait | tə\'naɪt/', 'tonight', 5);
INSERT INTO `words` VALUES (28456, 'The environment is a popular topic these days.', 'n. 主题（等于theme）；题目；一般规则；总论', '/\'tɔpik | \'tɒpɪk | \'tɑpɪk/', 'topic', 5);
INSERT INTO `words` VALUES (28457, 'We shone our torches around the cavern.', 'n. 火把，火炬；手电筒；启发之物; v. 像火炬一样燃烧', '/tɔ:tʃ | tɔːtʃ | tɔrtʃ/', 'torch', 5);
INSERT INTO `words` VALUES (28458, 'Seth was tormented by feelings of guilt.', 'v. 折磨，使痛苦；纠缠，作弄; n. 痛苦，苦恼；痛苦的根源', '/tɔ:\'ment, \'tɔ:m- | \'tɔːment | \'tɔrmɛnt/', 'torment', 5);
INSERT INTO `words` VALUES (28459, 'Torrents of water gushed into the reservoir.', 'n. 奔流；倾注；迸发；连续不断', '/\'tɔrənt, \'tɔ:- | \'tɒr(ə)nt | \'tɔrənt/', 'torrent', 5);
INSERT INTO `words` VALUES (28460, 'Political opponents of the regime may be tortured.', 'v. 折磨；拷问；歪曲; n. 折磨；拷问；歪曲', '/\'tɔ:tʃə | \'tɔːtʃə | \'tɔrtʃɚ/', 'torture', 5);
INSERT INTO `words` VALUES (28461, 'It would be better to decide it on the toss of a coin.', 'n. 投掷；摇荡；投掷的距离；掷币赌胜负; v. 投掷；使…不安；突然抬起；使…上下摇动；与…掷币打赌', '/tɔs, tɔ:s | tɒs | tɔs/', 'toss', 5);
INSERT INTO `words` VALUES (28462, 'a total ban on cigarette advertising', 'adj. 全部的；完全的；整个的; v. 总数达; n. 总数，合计', '/\'təutəl | \'təʊt(ə)l | \'totl/', 'total', 5);
INSERT INTO `words` VALUES (28463, 'The men who work on the oil rigs are a tough bunch.', 'adj. 艰苦的，困难的；坚强的，不屈不挠的；坚韧的，牢固的；强壮的，结实的; n. 恶棍; v. 坚持；忍受，忍耐; adv. 强硬地，顽强地', '/tʌf/', 'tough', 5);
INSERT INTO `words` VALUES (28464, 'Cambridge is always full of tourists in the summer.', 'n. 旅行者，观光客; adj. 旅游的; vt. 在旅行参观; vi. 旅游；观光; adv. 坐旅游车厢；坐经济舱', '/\'tuərist | \'tʊərɪst | \'tʊrɪst/', 'tourist', 5);
INSERT INTO `words` VALUES (28465, 'Can you give us a tow to the garage?', 'n. 拖；麻的粗纤维；拖曳所用之绳; v. 拖；牵引；曳', '/təu | təʊ | to/', 'tow', 5);
INSERT INTO `words` VALUES (28466, 'Have you got a clean towel I could use?', 'n. 毛巾，手巾；[纸] 纸巾; v. 用毛巾擦', '/\'tauəl | \'taʊəl/', 'towel', 5);
INSERT INTO `words` VALUES (28467, 'the Eiffel Tower', 'n. 塔；高楼；堡垒; v. 高耸；超越', '/\'tauə | \'taʊə | \'taʊɚ/', 'tower', 5);
INSERT INTO `words` VALUES (28468, 'an industrial town in the Midlands', 'n. 城镇，市镇；市内商业区', '/taun | taʊn/', 'town', 5);
INSERT INTO `words` VALUES (28469, 'fumes from a toxic waste dump', 'adj. 有毒的；中毒的', '/\'tɔksik | \'tɒksɪk | \'tɑksɪk/', 'toxic', 5);
INSERT INTO `words` VALUES (28470, 'some toys for the baby', 'n. 玩具；小装饰品；不值钱的东西; v. 玩弄；调情；随随便便地对待; adj. 作为玩具的；玩物似的', '/tɔi | tɒɪ | tɔɪ/', 'toy', 5);
INSERT INTO `words` VALUES (28471, 'Sondheim’s book traces the changing nature of the relationship between men and women.', 'v. 追溯；沿路走; n. 痕迹，踪迹；微量；[仪] 迹线；缰绳', '/treis | treɪs | tres/', 'trace', 5);
INSERT INTO `words` VALUES (28472, 'The road leading to the farm was little more than a dirt track .', 'n. 轨道；足迹，踪迹；小道; v. 追踪；通过；循路而行；用纤拉', '/træk/', 'track', 5);
INSERT INTO `words` VALUES (28473, 'Iron-ox is another name for tractor.', 'n. 拖拉机,牵引车', '/\'træktə | \'træktɚ/', 'tractor', 5);
INSERT INTO `words` VALUES (28474, 'international trade agreements', 'n. 贸易，交易；行业；职业; v. 交易，买卖；以物易物', '/treid | treɪd | tred/', 'trade', 5);
INSERT INTO `words` VALUES (28475, 'The striped T-shirt became the comedian’s trademark.', 'n. 商标；特征; vt. 注册的…商标', '/\'treidmɑ:k | \'treɪdmɑːk | \'tred\'mɑrk/', 'trademark', 5);
INSERT INTO `words` VALUES (28476, 'the traditions of South East Asia', 'n. 惯例，传统；传说', '/trə\'diʃən | trə\'dɪʃ(ə)n | trə\'dɪʃən/', 'tradition', 5);
INSERT INTO `words` VALUES (28477, 'There wasn’t much traffic on the roads.', 'n. 交通；运输；贸易；[通信] 通信量; v. 用…作交换；在…通行', '/\'træfik | \'træfɪk/', 'traffic', 5);
INSERT INTO `words` VALUES (28478, 'The tragedy happened as they were returning home from a night out.', 'n. 悲剧；灾难；惨案', '/\'trædʒidi | \'trædʒɪdɪ | \'trædʒədi/', 'tragedy', 5);
INSERT INTO `words` VALUES (28479, 'The parents were not to blame for the tragic death of their son.', 'adj. 悲剧的；悲痛的，不幸的', '/\'trædʒik | \'trædʒɪk/', 'tragic', 5);
INSERT INTO `words` VALUES (28480, 'A plane trailing a banner was circling overhead.', 'v. 追踪；拖；蔓延；落后于; n. 小径；痕迹；尾部；踪迹；一串，一系列', '/treɪl | trel/', 'trail', 5);
INSERT INTO `words` VALUES (28481, 'The study found that some alcoholics had clear personality traits showing up early in childhood.', 'n. 特性，特点；品质；少许', '/trei, treit | treɪt; treɪ | tret/', 'trait', 5);
INSERT INTO `words` VALUES (28482, 'Some say he\'s a traitor to the peace movement.', 'n. 叛徒；卖国贼；背信弃义的人', '/\'treitə | \'treɪtə | \'tretɚ/', 'traitor', 5);
INSERT INTO `words` VALUES (28483, 'You can get to the beach easily from the centre of town by tram.', 'n. 电车轨道；煤车; v. 用煤车运载', '/træm/', 'tram', 5);
INSERT INTO `words` VALUES (28484, 'He tramped the streets looking for work.', 'v. 流浪；践踏，踩；脚步沉重地行走; n. 流浪者；沉重的脚步声；徒步旅行', '/træmp/', 'tramp', 5);
INSERT INTO `words` VALUES (28485, 'The bank charges a fixed rate for each transaction.', 'n. 办理,处理;交易,事务;(pl.)会报,学报', '/træn\'zækʃən, -\'sæk-, trɑ:n- | træn\'zækʃ(ə)n; trɑːn-; -\'sæk- | træn\'zækʃən/', 'transaction', 5);
INSERT INTO `words` VALUES (28486, 'The desire for peace transcended political differences.', 'v. 胜过，超越', '/træn\'send, trɑ:n- | træn\'send; trɑːn- | træn\'sɛnd/', 'transcend', 5);
INSERT INTO `words` VALUES (28487, 'Getting there often means a couple of transfers on a bus line.', 'n. 转让；转移；传递；过户; v. 转让；转学；换车', '/træns\'fə: | træns\'fɜː; trɑːns-; -nz- | træns\'fɝ/', 'transfer', 5);
INSERT INTO `words` VALUES (28488, 'Increased population has transformed the landscape.', 'v. 改变,变换;变压;转化;改造,改造', '/træns\'fɔ:m, trænz-, trɑ:n- | træns\'fɔːm; trɑːns-; -nz- | træns\'fɔrm/', 'transform', 5);
INSERT INTO `words` VALUES (28489, 'transient fashions', 'adj. 短暂的；路过的; n. 瞬变现象；过往旅客；候鸟', '/\'trænziənt, -si-, -ʃənt, \'trɑ:n- | \'trænzɪənt | ˈtrænʃnt; trænʃənt/', 'transient', 5);
INSERT INTO `words` VALUES (28490, 'When you got a transistor radio, you could walk around with it, and today you can put your whole record collection in your pocket.', 'n. 晶体管；晶体管收音机', '/træn\'sistə, -\'zis-, trɑ:n- | træn\'zɪstə; trɑːn-; -\'sɪ- | træn\'zɪstɚ/', 'transistor', 5);
INSERT INTO `words` VALUES (28491, 'baggage that is lost or damaged in transit', 'n. 运输， 载运; vt. 通过， 经过', '/\'trænzɪt; \'trænsɪt | \'træzɪt/', 'transit', 5);
INSERT INTO `words` VALUES (28492, 'Making the transition from youth to adulthood can be very painful.', 'n. 过渡；转变；[分子生物] 转换；变调', '/træn\'siʒən, -\'ziʃən, trɑ:n- | træn\'zɪʃ(ə)n; trɑːn-; -\'sɪʃ- | træn\'zɪʃən/', 'transition', 5);
INSERT INTO `words` VALUES (28493, 'Poetry doesn’t usually translate well.', 'v. 翻译；转化；解释；转变为；调动', '/træns\'leɪt; trɑːns-; -nz- | træns\'let/', 'translate', 5);
INSERT INTO `words` VALUES (28494, 'She read the letter and gave us a rough translation (= she did not translate everything exactly ) .', 'n. 翻译；译文；转化；调任', '/træns\'leiʃən, trænz-, trɑ:n- | træns\'leɪʃ(ə)n; trɑːns-; -nz- | træns\'leʃən/', 'translation', 5);
INSERT INTO `words` VALUES (28495, 'worldwide data transmission', 'n. 传动装置，[机] 变速器；传递；传送；播送', '/trænz\'miʃən, træns-, trɑ:n- | trænz\'mɪʃ(ə)n; trɑːnz-; -ns- | træns\'mɪʃən/', 'transmission', 5);
INSERT INTO `words` VALUES (28496, 'The US Open will be transmitted live via satellite.', 'v. 传输；传播；发射；传达；遗传', '/trænz\'mit, træns-, trɑ:n- | trænz\'mɪt; trɑːnz-; -ns- | trænzˈmɪt/', 'transmit', 5);
INSERT INTO `words` VALUES (28497, 'a transparent plastic container', 'adj. 透明的，透光的；易理解的；明显的', '/træns\'pærənt, -\'pεə-, trænz-, trɑ:n- | træn\'spær(ə)nt; trɑːn-; -\'speə- | træns\'pærənt/', 'transparent', 5);
INSERT INTO `words` VALUES (28498, 'The operation to transplant a kidney is now fairly routine.', 'v. 移植；迁移；使移居; n. 移植；移植器官；被移植物；移居者', '/træns\'plɑ:nt, trænz-, trɑ:n-, -\'plænt | træns\'plɑːnt; trɑːns-; -nz- | træns\'plænt/', 'transplant', 5);
INSERT INTO `words` VALUES (28499, 'trucks used for transporting oil', 'v. 运输,运送,搬运n.运输;运输系统,运载工具', '/træns\'pɔ:t; trænz-træns\'pɔ:t, trænz-, trɑ:n-, \'trænspɔ:t, \'trænz-, \'trɑ:n- | træn\'spɔːt; trɑːn- | \'trænspɔrt/', 'transport', 5);
INSERT INTO `words` VALUES (28500, 'The police trapped the terrorists at a roadblock.', 'v. 诱捕；使…受限制；使…陷入困境; n. 陷阱；圈套；[建] 存水湾', '/træp/', 'trap', 5);
INSERT INTO `words` VALUES (28501, 'Will someone take out the trash (= take it outside the house ) ?', 'n. 垃圾；废物; v. 丢弃；修剪树枝', '/træʃ/', 'trash', 5);
INSERT INTO `words` VALUES (28502, 'The waiter brought drinks on a tray.', 'n. 托盘；文件盒；隔底匣；（无线电的）发射箱', '/trei | treɪ | tre/', 'tray', 5);
INSERT INTO `words` VALUES (28503, 'The defendant was convicted of high treason (= treason of the worst kind ) and sentenced to death.', 'n. [法] 叛国罪；不忠', '/\'tri:zən | \'triːz(ə)n | \'trizn/', 'treason', 5);
INSERT INTO `words` VALUES (28504, 'The Book of Kells is Trinity College’s greatest treasure.', 'n. 财富，财产；财宝；珍品; v. 珍爱；珍藏', '/\'treʒə, \'trei- | \'treʒə | \'trɛʒɚ/', 'treasure', 5);
INSERT INTO `words` VALUES (28505, 'It was difficult to treat patients because of a shortage of medicine.', 'v. 治疗；对待；探讨；视为; n. 请客；款待', '/tri:t | triːt | trit/', 'treat', 5);
INSERT INTO `words` VALUES (28506, 'Both sides have agreed to sign the treaty .', 'n. 条约，协议；谈判', '/\'tri:ti | \'triːtɪ | \'triti/', 'treaty', 5);
INSERT INTO `words` VALUES (28507, 'As a kid, I loved to climb trees.', 'n. 树；木料；树状物; v. 把赶上树', '/tri: | triː | tri/', 'tree', 5);
INSERT INTO `words` VALUES (28508, 'His lip started to tremble and then he started to cry.', 'v. 发抖；战栗；焦虑；摇晃; n. 颤抖；战栗；摇晃', '/\'trembl | \'tremb(ə)l | \'trɛmbl/', 'tremble', 5);
INSERT INTO `words` VALUES (28509, 'Suddenly, there was a tremendous bang, and the whole station shook.', 'adj. 极大的，巨大的；惊人的；极好的', '/trɪ\'mendəs | trə\'mɛndəs/', 'tremendous', 5);
INSERT INTO `words` VALUES (28510, 'Workers dug a trench for gas lines.', 'n. 沟，沟渠；战壕；堑壕; v. 掘沟', '/trentʃ | tren(t)ʃ | trɛntʃ/', 'trench', 5);
INSERT INTO `words` VALUES (28511, 'The current trend is towards more part-time employment.', 'n. 趋势，倾向；走向; v. 趋向，伸向', '/trend | trɛnd/', 'trend', 5);
INSERT INTO `words` VALUES (28512, 'a new drug that is undergoing clinical trials', 'n. 试验；审讯；努力；磨炼; adj. 试验的；审讯的', '/\'traiəl | \'traɪəl/', 'trial', 5);
INSERT INTO `words` VALUES (28513, 'a triangle of land', 'n. 三角（形）；三角关系；三角形之物；三人一组', '/\'traiæŋɡl | \'traɪæŋg(ə)l | \'traɪæŋɡl/', 'triangle', 5);
INSERT INTO `words` VALUES (28514, 'a tribe of Aborigines known as the Dolphin People', 'n. 部落；族；宗族；一伙', '/traib | traɪb/', 'tribe', 5);
INSERT INTO `words` VALUES (28515, 'The players wore black armbands as a tribute to their late teammate.', 'n. 礼物；[税收] 贡物；颂词；（尤指对死者的）致敬，悼念，吊唁礼物', '/\'trɪbjuːt | \'trɪbjut/', 'tribute', 5);
INSERT INTO `words` VALUES (28516, 'Pretending he doesn’t remember is an old trick of his.', 'n. 诡计；恶作剧；窍门；花招；骗局；欺诈; v. 欺骗；哄骗；装饰；打扮; adj. 特技的；欺诈的；有决窍的', '/trik | trɪk/', 'trick', 5);
INSERT INTO `words` VALUES (28517, 'There’s no point in arguing over trifles.', 'n. 琐事；蛋糕；少量; v. 开玩笑；闲混；嘲弄', '/\'traifl | \'traɪf(ə)l | \'traɪfl/', 'trifle', 5);
INSERT INTO `words` VALUES (28518, 'The assassination triggered off a wave of rioting.', 'v. 引发，引起；触发; n. 扳机；[电子] 触发器；制滑机', '/\'triɡə | \'trɪgə | \'trɪɡɚ/', 'trigger', 5);
INSERT INTO `words` VALUES (28519, 'Pete was trimming the lawn around the roses.', 'v. 修剪；整理；装点; n. 修剪；整齐；情形; adj. 整齐的', '/trim | trɪm/', 'trim', 5);
INSERT INTO `words` VALUES (28520, 'He tripped and fell .', 'v. 绊倒；远足；犯错误；轻快地走; n. 旅行；绊倒；差错', '/trip | trɪp/', 'trip', 5);
INSERT INTO `words` VALUES (28521, 'a triple murder investigation', 'adj. 三倍的；三方的; n. 三倍数；三个一组; v. 增至三倍', '/\'tripl | \'trɪp(ə)l | \'trɪpl/', 'triple', 5);
INSERT INTO `words` VALUES (28522, 'Winning the championship is a great personal triumph .', 'n. 胜利，凯旋；欢欣; v. 获得胜利，成功', '/\'traiəmf, -ʌmf | \'traɪʌmf/', 'triumph', 5);
INSERT INTO `words` VALUES (28523, 'a trivial sum', 'adj. 不重要的，琐碎的；琐细的', '/\'triviəl | \'trɪvɪəl/', 'trivial', 5);
