INSERT INTO `words` VALUES (28527, 'plant species found in the tropics', 'n. 热带；回归线; adj. 热带的', '/\'trɔpik | \'trɒpɪk | \'trɑpɪk/', 'tropic', 5);
INSERT INTO `words` VALUES (28528, 'the tropical rain forests', 'adj. 热带的；热情的；酷热的', '/\'trɔpikəl | \'trɒpɪk(ə)l | \'trɑpɪkl/', 'tropical', 5);
INSERT INTO `words` VALUES (28529, 'Recent stock market losses point to trouble ahead.', 'n. 麻烦；烦恼；故障；动乱; v. 麻烦；使烦恼；折磨', '/\'trʌbl | \'trʌb(ə)l/', 'trouble', 5);
INSERT INTO `words` VALUES (28530, 'a troublesome child', 'adj. 麻烦的；讨厌的；使人苦恼的', '/\'trʌblsəm | \'trʌb(ə)ls(ə)m/', 'troublesome', 5);
