INSERT INTO `words` VALUES (28534, 'At first there was a lack of trust between them.', 'n. 信任，信赖；责任；托拉斯; v. 信任，信赖；盼望；赊卖给', '/\'trʌst | trʌst/', 'trust', 5);
INSERT INTO `words` VALUES (28535, 'How do we know you’re telling us the truth?', 'n. 真理；事实；诚实；实质', '/tru:θ | truːθ | trʊθ/', 'truth', 5);
INSERT INTO `words` VALUES (28536, 'I had a long soak in the tub.', 'n. 浴盆；桶; vt. 把…装入桶；为…洗盆浴; vi. 洗盆浴；（衣服等）被放在桶里洗', '/tʌb/', 'tub', 5);
INSERT INTO `words` VALUES (28537, 'a tube of toothpaste', 'n. 管；电子管；隧道；电视机; v. 使成管状；把…装管；用管输送', '/tju:b, tu:b | tjuːb | tub/', 'tube', 5);
INSERT INTO `words` VALUES (28538, 'He tried to tuck his flapping shirt inside his trousers.', 'v. 卷起；挤进；用某物舒适地裹住；使有褶裥；收拢；大口吃；使隐藏; n. 食物；船尾突出部；缝摺；抱膝式跳水；活力；鼓声', '/tʌk/', 'tuck', 5);
INSERT INTO `words` VALUES (28539, 'He phoned on Tuesday, just before you came.', 'n. 星期二', '/\'tju:zdi; -dei | \'tjuːzdeɪ; -dɪ | ˈtuzdi, -ˌde, ˈtjuz-/', 'tuesday', 5);
INSERT INTO `words` VALUES (28540, '...a 76,000-ton barge pulled by five tug boats.', 'n. 拖船；拖曳；苦干; v. 用力拉；竞争；努力做', '/tʌɡ | tʌg/', 'tug', 5);
INSERT INTO `words` VALUES (28541, 'I had to have extra tuition in maths.', 'n. 学费；讲授', '/tju:\'iʃən | tjuː\'ɪʃ(ə)n | tʊ\'ɪʃən/', 'tuition', 5);
INSERT INTO `words` VALUES (28542, 'A small boy tumbled off the porch.', 'v. 摔倒；倒塌；滚动；打滚；仓惶地行动; n. 跌倒；翻筋斗；跌跤', '/\'tʌmb(ə)l | \'tʌmbl/', 'tumble', 5);
INSERT INTO `words` VALUES (28543, 'When do you think the patient can be operated on for the tumor?', 'n. 肿瘤， 肿块', '/\'tjuːmə | \'tjʊmɚ/', 'tumor', 5);
