INSERT INTO `words` VALUES (28546, 'a railway tunnel', 'n. 隧道；坑道；洞穴通道; v. 挖；在…打开通道；在…挖掘隧道', '/\'tʌnəl | \'tʌnl/', 'tunnel', 5);
