INSERT INTO `words` VALUES (28548, 'the turbulent times of the French Revolution', 'adj. 骚乱的，混乱的；狂暴的；吵闹的；激流的，湍流的', '/\'tɜːbjʊl(ə)nt | \'tɝbjələnt/', 'turbulent', 5);
INSERT INTO `words` VALUES (28549, 'roast turkey', 'n. 火鸡；笨蛋；失败之作', '/\'tə:ki | \'tɜːkɪ | \'tɝki/', 'turkey', 5);
INSERT INTO `words` VALUES (28550, 'She lived through the turmoil of the French Revolution.', 'n. 混乱， 骚动', '/\'tɜːmɔɪl | \'tɝmɔɪl/', 'turmoil', 5);
INSERT INTO `words` VALUES (28551, 'Ricky turned and walked away.', 'v. 转动，使旋转；转弯；翻过来；兑换; n. 转弯；变化；(损害或有益于别人的)行为，举动，举止', '/tɜːn | tɝn/', 'turn', 5);
INSERT INTO `words` VALUES (28552, 'The company had a turnover of $3.8 million.', 'n. 翻覆；[贸易] 营业额；流通量；半圆卷饼；失误; adj. 翻过来的；可翻转的', '/\'tə:n,əuvə | \'tɜːnəʊvə | \'tɝn\'ovɚ/', 'turnover', 5);
INSERT INTO `words` VALUES (28553, 'He was privately tutored.', 'v. 辅导；约束; n. 导师；家庭教师；助教', '/\'tju:tə | \'tjuːtə | \'tʊtɚ/', 'tutor', 5);
INSERT INTO `words` VALUES (28554, NULL, 'abbr. 电视（television）', '/\'ti:\'vi: | ˌti: ˈvi: | ˌti vi/', 'tv', 5);
INSERT INTO `words` VALUES (28555, 'The twins are now eight months old.', 'v. 使成对; n. 双胞胎中一人; adj. 双胞胎的', '/twin | twɪn/', 'twin', 5);
INSERT INTO `words` VALUES (28556, 'stars twinkling in the sky', 'v. 闪烁；发亮; n. 闪烁', '/\'twiŋkl | \'twɪŋk(ə)l | \'twɪŋkl/', 'twinkle', 5);
INSERT INTO `words` VALUES (28557, 'Her hands began to twist the handles of the bag she carried.', 'v. 捻；拧；扭伤；编织；使苦恼; n. 扭曲；拧；扭伤', '/twist | twɪst/', 'twist', 5);
INSERT INTO `words` VALUES (28558, 'She tapped out a letter on the typewriter.', 'n. 打字机', '/\'taip,raitə | \'taɪpraɪtə | \'taɪpraɪtɚ/', 'typewriter', 5);
INSERT INTO `words` VALUES (28559, 'The typhoon had spent its fury.', 'n. [气象] 台风', '/tai\'fu:n | taɪ\'fuːn | taɪ\'fʊn/', 'typhoon', 5);
INSERT INTO `words` VALUES (28560, 'typical British weather', 'adj. 典型的；特有的；象征性的', '/\'tipikəl | \'tɪpɪk(ə)l | \'tɪpɪkl/', 'typical', 5);
