INSERT INTO `words` VALUES (28563, 'The ultimate outcome of the experiment cannot be predicted.', 'adj. 最终的；极限的；根本的; n. 终极；根本；基本原则', '/\'ʌltimət | \'ʌltɪmət | \'ʌltəmət/', 'ultimate', 5);
INSERT INTO `words` VALUES (28564, 'Ozone in the stratosphere is important because it absorbs some of the Sun’s dangerous ultraviolet radiation.', 'adj. 紫外的；紫外线的; n. 紫外线辐射，紫外光', '/,ʌltrə\'vaiələt | ʌltrə\'vaɪələt | ,ʌltrə\'vaɪələt/', 'ultraviolet', 5);
INSERT INTO `words` VALUES (28565, 'It started to rain, so Tricia stopped to put up her umbrella.', 'n. 雨伞；保护伞；庇护；伞形结构', '/ʌm\'brelə | ʌm\'brɛlə/', 'umbrella', 5);
INSERT INTO `words` VALUES (28566, 'It was decided by a unanimous vote that the school should close.', 'adj. 全体一致的；意见一致的；无异议的', '/ju:\'næniməs | juː\'nænɪməs | jʊ\'nænəməs/', 'unanimous', 5);
INSERT INTO `words` VALUES (28567, 'Customs officials uncovered a plot to smuggle weapons into the country.', 'v. 揭开,揭露', '/,ʌn\'kʌvə | ʌn\'kʌvə | ʌn\'kʌvɚ/', 'uncover', 5);
INSERT INTO `words` VALUES (28568, 'None of us should ever underestimate the degree of difficulty women face in career advancement.', 'v. 低估，看轻', '/,ʌndə\'estimeit | ʌndər\'estɪmeɪt | /ˌʌndərˈestɪmeɪt//', 'underestimate', 5);
INSERT INTO `words` VALUES (28569, 'The country has undergone massive changes recently.', 'v. 经历，经受；忍受', '/,ʌndə\'ɡəu | ʌndə\'gəʊ | ,ʌndɚ\'ɡo/', 'undergo', 5);
INSERT INTO `words` VALUES (28570, 'second-year undergraduates', 'n. 大学生；大学肄业生; adj. 大学生的', '/,ʌndə\'ɡrædjuət | ʌndə\'grædjʊət | ,ʌndɚ\'ɡrædʒuət/', 'undergraduate', 5);
INSERT INTO `words` VALUES (28571, 'This animal spends most of its life underground.', 'adv. 在地下； 秘密地; adj. 地下的， 地面下的；秘密的; n. 地铁', '/ʌndə\'graʊnd | ʌndɚˈɡraʊnd/', 'underground', 5);
INSERT INTO `words` VALUES (28572, 'the one basic principle that underlies all of the party’s policies', 'v. 成为……的基础；位于……之下', '/,ʌndə\'lai | ʌndə\'laɪ | ,ʌndɚ\'laɪ/', 'underlie', 5);
INSERT INTO `words` VALUES (28573, 'This tragic incident underlines the need for immediate action.', 'v. 强调；在…下面划线；预告; n. 下划线；下期节目预告', '/,ʌndə\'lain, \'ʌndəlain | ʌndə\'laɪn | \'ʌndəlaɪn/', 'underline', 5);
INSERT INTO `words` VALUES (28574, 'the underlying causes of her depression', 'adj. 潜在的；根本的；在下面的；优先的; v. 放在…的下面；为…的基础；优先于（underlie的ing形式）', '/,ʌndə\'laiiŋ | ʌndə\'laɪɪŋ | ,ʌndɚ\'laɪɪŋ/', 'underlying', 5);
INSERT INTO `words` VALUES (28575, 'The continued fighting threatens to undermine efforts to negotiate an agreement.', 'v. 破坏，渐渐破坏；挖掘地基', '/,ʌndə\'main | ʌndə\'maɪn | \'ʌndɚ\'maɪn/', 'undermine', 5);
INSERT INTO `words` VALUES (28576, 'He got out of the car and looked underneath.', 'prep. 在…的下面；在…的形式下；在…的支配下; adv. 在下面；在底下; n. 下面；底部; adj. 下面的；底层的', '/,ʌndə\'ni:θ | ʌndə\'niːθ | ,ʌndɚ\'niθ/', 'underneath', 5);
INSERT INTO `words` VALUES (28577, 'She doesn’t understand English.', 'v. 理解；懂；获悉；推断；省略', '/,ʌndə\'stænd | ʌndə\'stænd | \'ʌndɚ\'stænd/', 'understand', 5);
INSERT INTO `words` VALUES (28578, 'We had an understanding that Jean-Claude should never be mentioned.', 'n. 谅解，理解；理解力；协议; adj. 了解的；聪明的；有理解力的; v. 理解；明白（understand的ing形式）', '/,ʌndə\'stændiŋ | ʌndə\'stændɪŋ | ,ʌndɚ\'stændɪŋ/', 'understanding', 5);
INSERT INTO `words` VALUES (28579, 'He undertook to pay the money back in six months.', 'v. 承担，保证；从事；同意；试图', '/,ʌndə\'teik | ʌndə\'teɪk | ,ʌndɚ\'tek/', 'undertake', 5);
INSERT INTO `words` VALUES (28580, 'punishment of undesirable behaviour', 'adj. 不受欢迎的， 令人不快的', '/ˌʌndɪ\'zaɪərəbl | ,ʌndɪ\'zaɪərəbl/', 'undesirable', 5);
INSERT INTO `words` VALUES (28581, 'The screws can be undone by hand.', 'v. 取消；解开；破坏；扰乱', '/,ʌn\'du: | ʌn\'duː | ʌn\'du/', 'undo', 5);
INSERT INTO `words` VALUES (28582, NULL, 'adv. 确实地，毋庸置疑的', '/ʌn\'daʊtɪdlɪ | ʌn\'daʊtɪdli/', 'undoubtedly', 5);
INSERT INTO `words` VALUES (28583, 'She eventually fell into an uneasy sleep.', 'adj. 不舒服的；心神不安的；不稳定的', '/,ʌn\'i:zi | ʌn\'iːzɪ | ʌn\'izi/', 'uneasy', 5);
INSERT INTO `words` VALUES (28584, 'a town where there is high unemployment', 'n. 失业；失业率；失业人数', '/,ʌnim\'plɔimənt | ʌnɪm\'plɒɪm(ə)nt; -em- | ,ʌnɪm\'plɔɪmənt/', 'unemployment', 5);
INSERT INTO `words` VALUES (28585, 'The experiment produced some unexpected results.', 'adj. 想不到的, 意外的, 未预料到', '/,ʌnik\'spektid | ʌnɪk\'spektɪd; ʌnek- | \'ʌnɪk\'spɛktɪd/', 'unexpected', 5);
INSERT INTO `words` VALUES (28586, 'As the story unfolds, we learn more about Max’s childhood.', 'v. 打开；呈现', '/,ʌn\'fəuld | ʌn\'fəʊld | ʌn\'fold/', 'unfold', 5);
INSERT INTO `words` VALUES (28587, 'Unfortunately, you were out when we called.', 'adv. 不幸地', '/ʌn\'fɔ:tʃənətli | ʌnˈfɔːtʃənətli | ʌn\'fɔrtʃənətli/', 'unfortunately', 5);
INSERT INTO `words` VALUES (28588, 'The police wear dark blue uniforms.', 'n. 制服,军服; adj. 相同的,一律的', '/\'ju:nifɔ:m | \'juːnɪfɔːm | \'junɪfɔrm/', 'uniform', 5);
INSERT INTO `words` VALUES (28589, 'Strong support for the war has unified the nation.', 'v. 统一；使相同，使一致', '/\'ju:nifai | \'juːnɪfaɪ | \'junɪfaɪ/', 'unify', 5);
INSERT INTO `words` VALUES (28590, 'Are you planning to join the union?', 'n. 联盟，协会；工会；联合', '/\'ju:niən | \'juːnjən; -ɪən | \'junɪən/', 'union', 5);
INSERT INTO `words` VALUES (28591, 'Each person’s fingerprints are unique.', 'adj. 独特的，稀罕的；[数] 唯一的，独一无二的; n. 独一无二的人或物', '/ju:\'ni:k | juː\'niːk | jʊ\'nik/', 'unique', 5);
INSERT INTO `words` VALUES (28592, 'The man is in the hospital’s intensive care unit.', 'n. 单位，单元；装置；[军] 部队；部件', '/\'ju:nit | \'juːnɪt | \'junɪt/', 'unit', 5);
