INSERT INTO `words` VALUES (28594, 'economic unity', 'n. 团结；一致；联合；个体', '/\'ju:niti | ˈjuːnəti | \'junəti/', 'unity', 5);
INSERT INTO `words` VALUES (28595, 'free universal healthcare', 'adj. 普遍的,全体的,通用的;宇宙的,世界的', '/,ju:ni\'və:səl | juːnɪ\'vɜːs(ə)l | \'jʊnə\'vɝsl/', 'universal', 5);
INSERT INTO `words` VALUES (28596, 'Einstein\'s equations showed the universe to be expanding.', 'n. 宇宙,万物', '/\'ju:nivə:s | \'juːnɪvɜːs | \'junɪvɝs/', 'universe', 5);
INSERT INTO `words` VALUES (28597, 'He teaches Esperanto at that university.', 'n. (综合)大学', '/,ju:ni\'və:səti | juːnɪ\'vɜːsɪtɪ | ,junɪ\'vɝsəti/', 'university', 5);
INSERT INTO `words` VALUES (28598, 'Tammy was unlike any other woman I have ever known.', 'adj. 不同的，不相似的; prep. 和…不同，不像', '/,ʌn\'laik | ʌn\'laɪk | \'ʌn\'laɪk/', 'unlike', 5);
INSERT INTO `words` VALUES (28599, 'Donna might be able to come tomorrow, but it’s very unlikely.', 'adj. 未必的； 不可能的； 靠不住的', '/ʌn\'laɪkli/', 'unlikely', 5);
INSERT INTO `words` VALUES (28600, 'Unload everything from the boat and clean it thoroughly.', 'v. 卸；摆脱…之负担；倾销', '/,ʌn\'ləud | ʌn\'ləʊd | \'ʌn\'lod/', 'unload', 5);
INSERT INTO `words` VALUES (28601, 'an unusual feature', 'adj. 不寻常的；与众不同的；不平常的', '/,ʌn\'ju:ʒuəl | ʌn\'juːʒʊəl | ʌn\'jʊʒʊəl/', 'unusual', 5);
INSERT INTO `words` VALUES (28602, '...the most up-to-date information available on foods today.', 'adj. 最新的，新式的', '/ˌʌptə\'deɪt | \'ʌptə \'det/', 'up-to-date', 5);
INSERT INTO `words` VALUES (28603, 'The files need updating.', 'vt. 更新； 使现代化', '/ˌʌp\'deɪt | ,ʌp\'det/', 'update', 5);
INSERT INTO `words` VALUES (28604, 'Helicopters have been upgraded and modernized.', 'v. 提升,使升级', '/\'ʌpɡreid, ʌp\'ɡreid | ʌp\'greɪd | ,ʌp\'ɡred/', 'upgrade', 5);
INSERT INTO `words` VALUES (28605, 'a committee that aims to uphold educational standards', 'v. 支撑；鼓励；赞成；举起', '/ʌp\'həuld | ʌp\'həʊld | ʌpˈhoʊld/', 'uphold', 5);
INSERT INTO `words` VALUES (28606, 'the upper lip', 'adj. 上面的，上部的；较高的; n. (Upper)人名；(英)厄珀', '/\'ʌpə | \'ʌpɚ/', 'upper', 5);
INSERT INTO `words` VALUES (28607, 'Katie was still awake, sitting bolt upright(= sitting with her back very straight ) staring at the television.', 'adj. 正直的，诚实的；垂直的，直立的；笔直的；合乎正道的; n. 垂直；竖立', '/\'ʌprait, ,ʌp\'r- | \'ʌpraɪt/', 'upright', 5);
INSERT INTO `words` VALUES (28608, 'The announcement caused uproar in the crowd.', 'n. 骚动；喧嚣', '/\'ʌprɔ: | \'ʌprɔː | \'ʌprɔr/', 'uproar', 5);
INSERT INTO `words` VALUES (28609, 'Don’t do anything that would upset him.', 'v. 使心烦；颠覆；扰乱; adj. 心烦的；混乱的；弄翻的; n. 混乱；翻倒；颠覆', '/ʌp\'set | ʌp\'sɛt/', 'upset', 5);
INSERT INTO `words` VALUES (28610, 'I went upstairs and had a shower.', 'adv. 在楼上，向楼上；上楼；往楼上; adj. 楼上的; n. 楼上', '/\'ʌp\'stεəz | ʌp\'steəz | ,ʌp\'stɛrz/', 'upstairs', 5);
