INSERT INTO `words` VALUES (28709, 'Workers are being encouraged to take voluntary redundancy.', 'adj. 自愿的,志愿的', '/\'vɔləntəri | \'vɒlənt(ə)rɪ | \'vɑləntɛri/', 'voluntary', 5);
INSERT INTO `words` VALUES (28710, 'The room was quiet; no one volunteered any further information.', 'n&v. 自愿(者,兵);自愿(提供)', '/,vɔlən\'tiə | ,vɒlən\'tɪə | ,vɑlən\'tɪr/', 'volunteer', 5);
INSERT INTO `words` VALUES (28711, 'A vote for us is not a wasted vote.', 'n. 投票，选举；选票；得票数; v. 提议，使投票；投票决定；公认', '/vəut | vəʊt | vot; voʊt/', 'vote', 5);
INSERT INTO `words` VALUES (28712, 'But he could say vowel clearly and began to learn vocabulary.', 'n. 元音；母音; adj. 元音的', '/\'vauəl | \'vaʊəl/', 'vowel', 5);
