INSERT INTO `words` VALUES (28717, 'The government, along with the three factions that had been waging a civil war, signed a peace agreement.', 'v. 进行；发动；从事; n. 工资；代价；报偿', '/weidʒ | weɪdʒ | wedʒ/', 'wage', 5);
