INSERT INTO `words` VALUES (28726, 'the Great Wall of China', 'n. 墙壁，围墙；似墙之物; v. 用墙围住，围以墙; adj. 墙壁的', '/wɔ:l | wɔːl | wɔl/', 'wall', 5);
INSERT INTO `words` VALUES (28727, 'He took a credit card out of his wallet.', 'n. 钱包，皮夹', '/\'wɔlit | \'wɒlɪt | \'wɑlɪt/', 'wallet', 5);
