INSERT INTO `words` VALUES (28730, 'Can you hang these in the wardrobe, please?', 'n. 衣柜；行头；全部戏装', '/\'wɔ:drəub | \'wɔːdrəʊb | \'wɔr\'drob/', 'wardrobe', 5);
