INSERT INTO `words` VALUES (28733, 'The house was lovely and warm.', 'adj. 温暖的；热情的; v. 同情；激动；变温暖; n. 取暖；加热', '/wɔ:m | wɔːm | wɔrm/', 'warm', 5);
INSERT INTO `words` VALUES (28734, 'She went further into the room, drawn by the warmth of the fire.', 'n. 温暖；热情；激动', '/wɔ:mθ | wɔːmθ | wɔrmθ/', 'warmth', 5);
INSERT INTO `words` VALUES (28735, '‘Be careful, the rocks are slippery,’ Alex warned.', 'v. 警告，提醒；通知; n. (Warn)人名；(英)沃恩；(德)瓦恩', '/wɔ:n | wɔːn | wɔrn/', 'warn', 5);
INSERT INTO `words` VALUES (28736, 'There is no warrant for copying other people’s work.', 'n. 根据；证明；正当理由；委任状; v. 保证；担保；批准；辩解', '/\'wɔrənt, \'wɔ:- | \'wɒr(ə)nt | \'wɔrənt/', 'warrant', 5);
INSERT INTO `words` VALUES (28737, 'Those jeans need a good wash (= a thorough wash ).', 'n. 洗涤；洗的衣服；化妆水；冲积物; v. 洗涤；洗刷；冲走；拍打', '/wɔʃ, wɔ:ʃ | wɒʃ | wɑːʃ/', 'wash', 5);
