INSERT INTO `words` VALUES (28740, '...Angel Falls, the world\'s highest waterfall.', 'n. 瀑布；瀑布似的东西', '/\'wɔ:təfɔ:l, \'wɔ- | \'wɔːtəfɔːl | \'wɔtɚfɔl/', 'waterfall', 5);
INSERT INTO `words` VALUES (28741, 'a waterproof jacket', 'adj. 防水的,耐水的', '/\'wɔ:təpru:f, \'wɔ- | \'wɔːtəpruːf | \'wɔtɚpruf/', 'waterproof', 5);
INSERT INTO `words` VALUES (28742, 'a 100-watt bulb', 'n. 瓦特', '/wɔt | wɒt | wɑt/', 'watt', 5);
