INSERT INTO `words` VALUES (28745, 'the wealthy nations of the world', 'adj. 富有的；充分的；丰裕的; n. 富人', '/\'welθi | \'welθɪ | \'wɛlθi/', 'wealthy', 5);
INSERT INTO `words` VALUES (28746, 'Replace your trainers when they start to show signs of wear.', 'n. 衣物；磨损；耐久性; v. 穿着；用旧；耗损；面露', '/weə | wɛr/', 'wear', 5);
