INSERT INTO `words` VALUES (28748, 'hand-woven scarves', 'v. 编织；编排；使迂回前进; n. 织物；织法；编织式样', '/wiːv | wiv/', 'weave', 5);
INSERT INTO `words` VALUES (28749, 'She’s busy planning her daughter’s wedding.', 'n. 婚礼，婚宴；结婚；结合; v. 与…结婚（wed的ing形式）', '/\'wediŋ | \'wedɪŋ | \'wɛdɪŋ/', 'wedding', 5);
INSERT INTO `words` VALUES (28750, 'The phone was wedged under his chin.', 'v. 楔入；挤进；楔住; n. 楔子；楔形物；导致分裂的东西', '/wedʒ | wɛdʒ/', 'wedge', 5);
INSERT INTO `words` VALUES (28751, 'Caspar was weeding the garden.', 'v. 除草；铲除; n. 杂草，野草；菸草', '/wi:d | wiːd | wid/', 'weed', 5);
