INSERT INTO `words` VALUES (28760, 'Our only concern is the children’s welfare.', 'n. 福利；幸福；福利事业；安宁; adj. 福利的；接受社会救济的', '/\'welfεə | \'welfeə | \'wɛl\'fɛr/', 'welfare', 5);
INSERT INTO `words` VALUES (28761, 'There’s a slight chance of some sunshine in the west.', 'n. 西；西方；西部; adj. 西方的；朝西的; adv. 在西方；向西方；自西方', '/west | wɛst/', 'west', 5);
