INSERT INTO `words` VALUES (28788, 'Soon it will be winter.', 'n. 冬季；年岁；萧条期; v. 过冬; adj. 冬天的；越冬的', '/\'wintə | \'wɪntə | \'wɪntɚ/', 'winter', 5);
