INSERT INTO `words` VALUES (28800, 'I was talking to a woman I met on the flight.', 'n. (pl.）women妇女，成年女子', '/\'wumən | \'wʊmən/', 'woman', 5);
INSERT INTO `words` VALUES (28801, 'It’s wonderful what doctors can do nowadays.', 'adj. 极好的，精彩的，绝妙的；奇妙的；美妙；胜；神妙', '/\'wʌndəfʊl; -f(ə)l | ˈwʌndərfl/', 'wonderful', 5);
INSERT INTO `words` VALUES (28802, 'Put some more wood on the fire.', 'n. 木材；木制品；树林; vi. 收集木材; vt. 植林于；给…添加木柴', '/wud | wʊd/', 'wood', 5);
INSERT INTO `words` VALUES (28803, 'a wooden bench', 'adj. 木制的；僵硬的，呆板的', '/\'wudən | \'wʊd(ə)n | \'wʊdn/', 'wooden', 5);
INSERT INTO `words` VALUES (28804, 'a pure wool skirt', 'n. 羊毛；毛线；绒线；毛织品；毛料衣物', '/wul | wʊl/', 'wool', 5);
INSERT INTO `words` VALUES (28805, 'Trumpeter Marcus Belgrave ran a jazz workshop for young artists.', 'n. 车间；研讨会；工场；讲习班', '/\'wə:kʃɔp | \'wɜːkʃɒp | \'wɝkʃɑp/', 'workshop', 5);
INSERT INTO `words` VALUES (28806, 'His books have sold more than 20 million copies worldwide.', 'adv. 遍及全世界; adj. 全世界的， 世界范围的', '/\'wɜːldwaɪd | \'wɝldwaɪd/', 'worldwide', 5);
INSERT INTO `words` VALUES (28807, '...a new computer worm that disables security software.', 'n. 虫，蠕虫；蜗杆；螺纹；小人物; v. 使蠕动；给除虫；使缓慢前进', '/wə:m | wɜːm | wɝm/', 'worm', 5);
INSERT INTO `words` VALUES (28808, 'The traffic is much worse after five o’clock.', 'adj. 更坏的；更差的；更恶劣的（bad的比较级）；（病情）更重的（ill的比较级）; adv. 更糟；更坏；更恶劣地；更坏地; n. 更坏的事；更恶劣的事', '/wə:s, \'wə:s | wəːs | wɜrs/', 'worse', 5);
INSERT INTO `words` VALUES (28809, '...the worship of the ancient Roman gods.', 'n. 崇拜；礼拜；尊敬; v. 崇拜；尊敬；爱慕', '/\'wə:ʃip | \'wɝʃɪp/', 'worship', 5);
INSERT INTO `words` VALUES (28810, 'This is the worst recession for fifty years.', 'adj. 最差的，最坏的；最不利的；效能最低的; n. 最坏；最坏的时候; adv. 最坏地；最不利地', '/wə:st, \'wə:st | wə:st | wɝst/', 'worst', 5);
INSERT INTO `words` VALUES (28811, 'You should not deprecate your own worth.', 'adj. 值…的; n. 价值；财产', '/wə:θ | wɜːθ | wɝθ/', 'worth', 5);
INSERT INTO `words` VALUES (28812, 'He wanted to do a worthwhile job.', 'adj. 值得做的，值得花时间的', '/\'wə:θ\'hwail | wɜːθ\'waɪl | \'wɝθ\'waɪl/', 'worthwhile', 5);
INSERT INTO `words` VALUES (28813, 'Leeds United were worthy winners of the competition.', 'adj. 值得的；有价值的；配得上的，相称的；可尊敬的；应…的; n. 杰出人物；知名人士', '/\'wə:ði | ˈwəːði | wɜði/', 'worthy', 5);
INSERT INTO `words` VALUES (28814, 'A nurse cleaned and bandaged the wound.', 'n. 创伤，伤口; v. 使受伤', '/waund | wuːnd | wund/', 'wound', 5);
INSERT INTO `words` VALUES (28815, 'I’ve still got a few Christmas presents to wrap up.', 'v. 包；缠绕；隐藏；掩护; n. 外套；围巾', '/ræp/', 'wrap', 5);
INSERT INTO `words` VALUES (28816, 'The prime minister laid a wreath at the war memorial.', 'n. 花冠；圈状物; v. 环绕（等于wreathe）', '/ri:θ | riːθ | riθ/', 'wreath', 5);
INSERT INTO `words` VALUES (28817, 'He was still alive when they pulled him from the wreck.', 'n. 破坏；失事；残骸；失去健康的人; v. 破坏；使失事；拆毁', '/rek | rɛk/', 'wreck', 5);
INSERT INTO `words` VALUES (28818, 'Leaving New York had been a terrible wrench.', 'n. 扳手，扳钳；扭伤；痛苦；歪曲；猛扭; v. 扭伤；猛扭；曲解；折磨', '/rentʃ | ren(t)ʃ | rɛntʃ/', 'wrench', 5);
INSERT INTO `words` VALUES (28819, 'Where is that wretched boy?', 'adj. 可怜的；卑鄙的；令人苦恼或难受的', '/\'retʃid | \'retʃɪd | \'rɛtʃɪd/', 'wretched', 5);
INSERT INTO `words` VALUES (28820, 'Her face was a mass of wrinkles.', 'n. 皱纹; v. 起皱', '/\'riŋkl | \'rɪŋkl/', 'wrinkle', 5);
INSERT INTO `words` VALUES (28821, 'He broke his wrist climbing rocks for a cigarette ad.', 'n. 手腕；腕关节; vt. 用腕力移动', '/rist | rɪst/', 'wrist', 5);
INSERT INTO `words` VALUES (28822, 'What does the writing on the back say?', 'n. 书写；作品；著作；[法] 笔迹; v. 书写（write的ing形式）', '/\'raitiŋ | \'raɪtɪŋ/', 'writing', 5);
INSERT INTO `words` VALUES (28823, 'You’ve spelt my name wrong.', 'adv. 错误地；邪恶地，不正当地; n. 坏事；不公正; adj. 错误的；失常的；不适当的; v. 委屈；无理地对待；诽谤', '/rɒŋ | rɔŋ/', 'wrong', 5);
INSERT INTO `words` VALUES (28824, 'The X-ray showed that her leg was not broken.', 'n. X射线，X光; v. 用X光拍照，给…照X光', '/\'eksreɪ/', 'X-ray', 5);
INSERT INTO `words` VALUES (28825, 'a hundred yards away', 'n. 院子；码（英制中丈量长度单位，1码=3英尺）；庭院；帆桁; vt. 把…关进或围在畜栏里', '/jɑ:d | jɑːd | jɑrd/', 'yard', 5);
INSERT INTO `words` VALUES (28826, 'Rosanna stifled a huge yawn.', 'n. 哈欠；裂口; v. 打哈欠；裂开', '/jɔːn | jɔn/', 'yawn', 5);
INSERT INTO `words` VALUES (28827, 'Salary levels are reviewed on a yearly basis.', 'adj. 每年的; adv. 每年；一年一次; n. 年刊；年鉴', '/\'jə:li, \'jiə- | \'jɪəlɪ; \'jɜː- | \'jɪrli/', 'yearly', 5);
INSERT INTO `words` VALUES (28828, '‘Help me!’ she yelled hysterically.', 'v. 大叫，叫喊; n. 喊声，叫声', '/jel | jɛl | yel/', 'yell', 5);
INSERT INTO `words` VALUES (28829, 'yellow flowers', 'adj. 黄的，黄色的; n. 黄色', '/\'jeləʊ | \'jeloʊ/', 'yellow', 5);
INSERT INTO `words` VALUES (28830, 'yesterday’s meeting', 'n. 昨天；往昔; adv. 昨天', '/\'jestədi,-dei | ˈjɛstədeɪ | ˈjɛstədi/', 'yesterday', 5);
INSERT INTO `words` VALUES (28831, 'Our research has only recently begun to yield important results.', 'v. 屈服；出产，产生；放弃; n. 产量；收益', '/jiːld | jild/', 'yield', 5);
INSERT INTO `words` VALUES (28832, 'Other youngsters are not so lucky.', 'n. 年轻人；少年', '/\'jʌŋstə | \'jʌŋstɚ/', 'youngster', 5);
INSERT INTO `words` VALUES (28833, 'a gang of youths', 'n. 青年；青春；年轻；青少年时期', '/ju:θ | juːθ | jʊθ/', 'youth', 5);
INSERT INTO `words` VALUES (28834, '...his zeal for teaching.', 'n. 热情；热心；热诚', '/zi:l | ziːl | zil/', 'zeal', 5);
INSERT INTO `words` VALUES (28835, 'The neck of the zebra was nipped by a lion.', 'n. [脊椎] 斑马; adj. 有斑纹的', '/\'zi:brə | \'zebrə; \'ziːbrə | \'zɛbrə; \'zi-/', 'zebra', 5);
INSERT INTO `words` VALUES (28836, 'Some species weave designs into their webs, creating zigzag patterns that can either attract prey, like bees, in bright sunlight, or camouflage the net in the shade.', 'adj. 曲折的；锯齿形的；之字形的; v. 使成之字形；使曲折行进; n. 之字形；Z字形; adv. 曲折地；之字形地；Z字形地', '/\'ziɡzæɡ | \'zɪgzæg | \'zɪɡzæɡ/', 'zigzag', 5);
INSERT INTO `words` VALUES (28837, 'Copper and zinc are fused to make brass.', 'v. 镀锌于…；涂锌于…；用锌处理; n. 锌', '/ziŋk | zɪŋk/', 'zinc', 5);
INSERT INTO `words` VALUES (28838, 'The zip on my skirt had broken.', 'n. 拉链; vt. 用拉链拉上或扣上', '/zɪp/', 'zip', 5);
INSERT INTO `words` VALUES (28839, 'San Francisco and Tokyo are both located in earthquake zones.', 'n. 地带；地区；联防; v. 分成区', '/zəun | zəʊn | zon/', 'zone', 5);
INSERT INTO `words` VALUES (28840, 'The road to the zoo turns off here.', 'n. 动物园', '/zu: | zuː | zu/', 'zoo', 5);
INSERT INTO `words` VALUES (28841, NULL, 'n. 急速上升；嗡嗡声；[摄] 变焦摄影; v. 急速上升；摄像机移动', '/zuːm | zum/', 'zoom', 5);
INSERT INTO `words` VALUES (28842, 'The highly reflective surface and the abalone shell made this photograph a real challenge to take.', 'n. [动]鲍鱼(软体动物)', '/æ,bə\'ləuni | ,æbə\'ləʊnɪ | ,æbə\'loni/', 'abalone', 3);
INSERT INTO `words` VALUES (28843, 'How could she abandon her own child?', 'v. 放弃,遗弃', '/ə\'bænd(ə)n | ə\'bændən/', 'abandon', 3);
INSERT INTO `words` VALUES (28844, '...memories of her father\'s complete abandonment of her.', 'n. 放弃', '/ə\'bændənmənt | ə\'bændənm(ə)nt/', 'abandonment', 3);
INSERT INTO `words` VALUES (28845, 'We waited for the storm to abate.', 'v. 减少， 减轻', '/ə\'beɪt | ə\'bet/', 'abate', 3);
INSERT INTO `words` VALUES (28846, 'Once upon a time, there was an abbess in a small abbey .', 'n. 修道院； 大教堂', '/\'æbi/', 'abbey', 3);
INSERT INTO `words` VALUES (28847, 'And, furthermore, he started to abbreviate.', 'v. 缩写, 简化', '/ə\'bri:vieit | ə\'briːvɪeɪt | ə\'brivɪ\'et/', 'abbreviate', 3);
INSERT INTO `words` VALUES (28848, 'aberrant behaviour', 'adj. 越轨的； 异常的', '/æ\'berənt | æ\'bɛrənt/', 'aberrant', 3);
INSERT INTO `words` VALUES (28849, 'I abhor discrimination of any kind.', 'vt. 憎恨， 厌恶', '/əb\'hɔːr | əb\'hɔr/', 'abhor', 3);
INSERT INTO `words` VALUES (28850, 'Phil has a deep and abiding love for his family.', 'adj. 持久的， 永久的', '/ə\'baɪdɪŋ/', 'abiding', 3);
INSERT INTO `words` VALUES (28851, NULL, 'n. (贵妇人的贴身)使女', '/\'æbi,ɡeil/', 'abigail', 3);
INSERT INTO `words` VALUES (28852, 'The test measures your mathematical ability.', 'n. 能力， 才干', '/ə\'bɪləti | əˈbɪlətɪ/', 'ability', 3);
INSERT INTO `words` VALUES (28853, 'Within minutes the whole house was ablaze.', 'adj. 着火的， 燃烧的； 闪耀的； 情绪激动的', '/ə\'bleɪz | ə\'blez/', 'ablaze', 3);
INSERT INTO `words` VALUES (28854, '...one of the brightest and ablest members of the government.', 'adj. 能够…的,得以…的', '/\'eibl | \'eɪb(ə)l | \'ebl/', 'able', 3);
INSERT INTO `words` VALUES (28855, 'abnormal behaviour', 'adj. 反常的, 变态的', '/æb\'nɔ:məl | æb\'nɔːml | æbˈnɔːrml/', 'abnormal', 3);
INSERT INTO `words` VALUES (28856, 'tests that can detect genetic abnormalities in the foetus', 'n. 变态 畸形', '/,æbnɔ:\'mæliti | æbnɔː\'mælɪtɪ; -nə\'mælɪtɪ | ,æbnɔr\'mæləti/', 'abnormality', 3);
INSERT INTO `words` VALUES (28857, 'They finally went aboard the plane.', 'prep&ad. 在(船、飞机、车)上，上船', '/ə\'bɔ:d | ə\'bɔːd | ə\'bɔrd/', 'aboard', 3);
INSERT INTO `words` VALUES (28858, 'Slavery was abolished in the US in the 19th century.', 'v. 废止, 废除', '/ə\'bɔliʃ | ə\'bɒlɪʃ | ə\'bɑlɪʃ/', 'abolish', 3);
INSERT INTO `words` VALUES (28859, 'The abolition of slavery in Brazil and the Caribbean closely followed the pattern of the United States.', 'n. 废除， 废止； 废奴运动', '/ˌæbə\'lɪʃn | ,æbə\'lɪʃən/', 'abolition', 3);
INSERT INTO `words` VALUES (28860, '...Aboriginal art.', 'adj. 土著的,原来的', '/,æbə\'ridʒənəl | æbə\'rɪdʒɪn(ə)l | ,æbə\'rɪdʒənl/', 'aboriginal', 3);
INSERT INTO `words` VALUES (28861, NULL, 'n. 土著居民', '/,æbə\'ridʒini: | æbə\'rɪdʒɪniː | \'æbə\'rɪdʒəni/', 'aborigine', 3);
INSERT INTO `words` VALUES (28862, 'The rescue mission had to be aborted.', 'v. 夭折， 中止； 使流产', '/ə\'bɔːrt | ə\'bɔrt/', 'abort', 3);
INSERT INTO `words` VALUES (28863, 'an abortive military coup', 'adj. 落空的， 失败的', '/ə\'bɔːrtɪv | ə\'bɔrtɪv/', 'abortive', 3);
INSERT INTO `words` VALUES (28864, 'Stories abound about when he was in charge.', 'v. 富于, 充满', '/ə\'baund | ə\'baʊnd/', 'abound', 3);
INSERT INTO `words` VALUES (28865, 'Our office is above the hairdresser’s.', 'prep. 在…上方,多(大,高)于; adv. 在上面', '/ə\'bʌv/', 'above', 3);
INSERT INTO `words` VALUES (28866, 'Where the water table is very high and contamination cannot be otherwise avoided, aboveground tanks may be needed.', 'adj. 在地面上的; adv. 地面上地', '/ə\'bʌv,ɡraund | ə\'bʌv,ɡraʊnd | ə\'bʌv,graʊnd/', 'aboveground', 3);
INSERT INTO `words` VALUES (28867, 'extra protection against abrasion', 'n. 磨损', '/ə\'breiʒən | ə\'breɪʒ(ə)n | ə\'breʒən/', 'abrasion', 3);
INSERT INTO `words` VALUES (28868, 'As the car drew abreast of him, Jack suddenly recognised the driver.', 'adv. 并肩地, 并排地', '/ə\'brest | ə\'brɛst/', 'abreast', 3);
INSERT INTO `words` VALUES (28869, NULL, 'vt. 缩短， 删节， 节略， 精简', '/ə\'brɪdʒ/', 'abridge', 3);
INSERT INTO `words` VALUES (28870, 'I’ve never lived abroad before.', 'adv. 到国外,在国外', '/ə\'brɔ:d | ə\'brɔːd | ə\'brɔd/', 'abroad', 3);
INSERT INTO `words` VALUES (28871, 'an abrupt change of plan', 'adj. 突然的,陡峭的,生硬的', '/ə\'brʌpt/', 'abrupt', 3);
INSERT INTO `words` VALUES (28872, 'The ground rises abruptly.', 'adv. 突然地；粗鲁地', '/ə\'brʌptli/', 'abruptly', 3);
INSERT INTO `words` VALUES (28873, NULL, 'n. 唐突,粗鲁', '/ə\'brʌptnis/', 'abruptness', 3);
INSERT INTO `words` VALUES (28874, 'In the absence of any evidence, the police had to let Myers go.', 'n. 不在, 缺席, 缺乏, 没有', '/\'æbsəns | \'æbs(ə)ns | \'æbsns/', 'absence', 3);
INSERT INTO `words` VALUES (28875, 'He has been absent from his desk for two weeks.', 'adj. 缺席的；缺乏的', '/\'æbsənt, æb\'sent | \'æbs(ə)nt | ˈæbsənt/', 'absent', 3);
INSERT INTO `words` VALUES (28876, 'His boss discharged him for habitual absenteeism.', 'n. 旷课, 旷工', '/,æbsən\'ti:izəm | æbs(ə)n\'tiːɪz(ə)m | ,æbsən\'tiɪzəm/', 'absenteeism', 3);
INSERT INTO `words` VALUES (28877, 'I have absolute confidence in her.', 'adj. 完全的, 绝对的', '/\'æbsəlju:t, ,æbsə\'lju:t | \'æbsəluːt | \'æbsəlut/', 'absolute', 3);
INSERT INTO `words` VALUES (28878, 'He made his reasons for resigning absolutely clear.', 'adv. 完全地, 绝对地', '/\'æbsəlju:tli, ,æbsə\'lju:tli | \'æbsəluːtlɪ | \'æbsəlutli/', 'absolutely', 3);
INSERT INTO `words` VALUES (28879, 'A police investigation yesterday absolved the police of all blame in the incident.', 'vt. 赦免； 免除； 宽恕', '/əb\'zɑːlv | əb\'zɑlv/', 'absolve', 3);
INSERT INTO `words` VALUES (28880, 'Plants absorb nutrients from the soil.', 'v. 吸收,吸引', '/əb\'sɔ:b, -\'zɔ:b | əb\'zɔːb; -\'sɔːb | æbˈsɔrb; æbˈzɔrb; əbˈsɔrb/', 'absorb', 3);
INSERT INTO `words` VALUES (28881, 'This controls the absorption of liquids.', 'n. 吸收', '/əb\'sɔ:pʃən | əb\'zɔːpʃ(ə)n; -\'sɔːp- | əbˈsɔrpʃən, -ˈzɔrp-/', 'absorption', 3);
INSERT INTO `words` VALUES (28882, 'Talking about crime in the abstract just isn’t enough.', 'n. 摘要,抽象', '/\'æbstrækt/', 'abstract', 3);
INSERT INTO `words` VALUES (28883, NULL, 'n. 提取', '/æb\'strækʃən | əb\'strækʃ(ə)n/', 'abstraction', 3);
INSERT INTO `words` VALUES (28884, 'It seems an absurd idea.', 'adj. 荒谬的, 可笑的', '/əb\'sə:d | əb\'sɜːd | əbˈsɚd, -ˈzɚd/', 'absurd', 3);
INSERT INTO `words` VALUES (28885, 'This area of Mexico has an abundance of safe beaches and a pleasing climate.', 'n. 丰富,充裕', '/ə\'bʌndəns | ə\'bʌnd(ə)ns/', 'abundance', 3);
INSERT INTO `words` VALUES (28886, 'an abundant supply of fresh water', 'adj. 丰富的,充裕的', '/ə\'bʌndənt | ə\'bʌnd(ə)nt/', 'abundant', 3);
INSERT INTO `words` VALUES (28887, 'Melons grow abundantly in this region.', 'adv. 大量地, 丰富地', '/ə\'bʌndəntli | ə\'bʌnd(ə)ntlɪ/', 'abundantly', 3);
INSERT INTO `words` VALUES (28888, 'several cases of child abuse', 'n&v. 滥用, 虐待,辱骂', '/ə\'bju:z, ə\'bju:s | ə\'bjuːz | ə\'bjus/', 'abuse', 3);
INSERT INTO `words` VALUES (28889, 'The castles abut a natural forest.', 'v. 邻接, 毗邻', '/ə\'bʌt/', 'abut', 3);
INSERT INTO `words` VALUES (28890, 'The reunion was an abysmal failure.', 'adj. 深不可测的； 极坏的， 糟透的', '/ə\'bɪzməl/', 'abysmal', 3);
INSERT INTO `words` VALUES (28891, 'He possessed no academic qualifications.', 'adj. 学院的, 理论的', '/,ækə\'demik | ækə\'demɪk | ,ækə\'dɛmɪk/', 'academic', 3);
INSERT INTO `words` VALUES (28892, 'Challenge yourself academically, but give yourself plenty of time for fun as well.', 'adv. 学业上', '/,ækə\'demikəli | ,ækə\'demɪkəlɪ | ,ækə\'dɛmɪkəli/', 'academically', 3);
INSERT INTO `words` VALUES (28893, 'I\'m the first academician in our family.', 'n. 院士, 大学生', '/ə,kædə\'miʃən | ə,kædə\'mɪʃ(ə)n | ,ækədə\'mɪʃən/', 'academician', 3);
INSERT INTO `words` VALUES (28894, 'the American Academy of Arts and Letters', 'n. 学院,学会,专科学校', '/ə\'kædəmi | ə\'kædəmɪ/', 'academy', 3);
INSERT INTO `words` VALUES (28895, NULL, 'vi. 即位， 就任； 同意', '/ək\'siːd | ək\'sid/', 'accede', 3);
INSERT INTO `words` VALUES (28896, 'measures to accelerate the rate of economic growth', 'v. 加速,促进', '/ək\'seləreit | ək\'seləreɪt | əkˈsɛləˌret/', 'accelerate', 3);
INSERT INTO `words` VALUES (28897, 'The latest model has excellent acceleration.', 'n. 加速度,加速', '/ək,selə\'reiʃən | əkselə\'reɪʃ(ə)n | ək\'sɛlə\'reʃən/', 'acceleration', 3);
INSERT INTO `words` VALUES (28898, 'He had a strong Irish accent', 'n. 重音； 口音； 重音符号; vt. 重读', '/\'æks(ə)nt; -sent | \'æksɛnt/', 'accent', 3);
INSERT INTO `words` VALUES (28899, 'Rick accepted her offer of coffee.', 'v. 接受,承认,同意', '/ək\'sept | ə\'ksept | ækˈsɛpt; əkˈsɛpt/', 'accept', 3);
INSERT INTO `words` VALUES (28900, 'Students who achieve an acceptable standard will progress to degree studies.', 'adj. 可接受的, 合意的', '/ək\'septəbl | ək\'septəb(ə)l | ək\'sɛptəbl/', 'acceptable', 3);
INSERT INTO `words` VALUES (28901, 'He wrote a letter of acceptance (= a letter in which you agree to accept a job, university place etc ) to the university.', 'n. 接受,接纳', '/ək\'septəns | ək\'sept(ə)ns | ək\'sɛptəns/', 'acceptance', 3);
INSERT INTO `words` VALUES (28902, 'Access is by means of a small door on the right.', 'n. 入口,通道; v. 进入', '/\'ækses, \'æksəs, æk\'ses | \'ækses | \'æksɛs/', 'access', 3);
INSERT INTO `words` VALUES (28903, NULL, 'n. 易接近, 可到达的', '/ək,sesə\'biləti | ək,sesə\'bɪlətɪ | æk,sɛsə\'bɪləti/', 'accessibility', 3);
INSERT INTO `words` VALUES (28904, 'The island is only accessible by boat.', 'adj. 可得到的,易接近的', '/ək\'sesəbl | ək\'sesɪb(ə)l | ək\'sɛsəbl/', 'accessible', 3);
INSERT INTO `words` VALUES (28905, 'bathroom accessories such as mirrors and towel-rails', 'n. 附件; adj. 辅助的', '/ək\'sesəri | ək\'ses(ə)rɪ | ək\'sɛsəri/', 'accessory', 3);
INSERT INTO `words` VALUES (28906, 'Over 70,000 people are seriously injured every year in road accidents.', 'n. 意外事件, 事故', '/\'æksidənt | \'æksɪdənt | \'æksədənt/', 'accident', 3);
INSERT INTO `words` VALUES (28907, 'an accidental discharge of toxic waste', 'adj. 意外的，偶然(发生)的', '/,æksi\'dentəl | æksɪ\'dent(ə)l | ,æksɪ\'dɛntl/', 'accidental', 3);
INSERT INTO `words` VALUES (28908, 'She accidentally erased the tape.', 'adj. 意外的,偶然(发生)的', '/,æksi\'dentli | æksɪ\'dent(ə)lɪ | ,æksə\'dɛntli/', 'accidentally', 3);
INSERT INTO `words` VALUES (28909, 'Blessed are those who have learned to acclaim you, who walk in the light of your presence, O Lord .', 'n&v. 喝采, 欢呼', '/ə\'kleɪm | ə\'klem/', 'acclaim', 3);
INSERT INTO `words` VALUES (28910, 'He bought a huge house to accommodate his library.', 'v. 容纳,提供(住处),适应', '/ə\'kɔmədeit | ə\'kɒmədeɪt | ə\'kɑmədet/', 'accommodate', 3);
INSERT INTO `words` VALUES (28911, 'White wine makes an excellent accompaniment to fish.', 'n. 陪伴物, 伴奏', '/ə\'kʌmpənimənt | ə\'kʌmp(ə)nɪm(ə)nt | ə\'kʌmpənɪmənt/', 'accompaniment', 3);
INSERT INTO `words` VALUES (28912, 'Children under 14 must be accompanied by an adult.', 'v. 陪伴,伴奏', '/ə\'kʌmpəni | ə\'kʌmpənɪ/', 'accompany', 3);
INSERT INTO `words` VALUES (28913, 'We have accomplished all we set out to do.', 'v. 完成,实现', '/ə\'kʌmpliʃ, ə\'kɔm- | ə\'kʌmplɪʃ; ə\'kɒm- | ə\'kɑmplɪʃ/', 'accomplish', 3);
INSERT INTO `words` VALUES (28914, 'It was a major accomplishment for a player who had been injured so recently.', 'n. 成就, 完成', '/ə\'kʌmpliʃmənt, ə\'kɔm- | ə\'kʌmplɪʃm(ə)nt; ə\'kɒm- | ə\'kɑmplɪʃmənt/', 'accomplishment', 3);
INSERT INTO `words` VALUES (28915, 'There was a silence as the women turned with one accord to stare at Doreen.', 'n&v. 一致, 协定', '/ə\'kɔ:d | ə\'kɔːd | ə\'kɔrd/', 'accord', 3);
INSERT INTO `words` VALUES (28916, 'Katherine still considered him a child and treated him accordingly.', 'adv. 因此, 相应地, 于是', '/ə\'kɔ:diŋli | ə\'kɔːdɪŋlɪ | ə\'kɔrdɪŋli/', 'accordingly', 3);
INSERT INTO `words` VALUES (28917, 'But my fancy accordion might as well have been a cardboard box that afternoon.', 'n. 手风琴', '/ə\'kɔ:djən | ə\'kɔːdɪən | ə\'kɔrdɪən/', 'accordion', 3);
INSERT INTO `words` VALUES (28918, 'Chomsky’s account of how children learn their first language', 'n. 记述,帐(户),解释; v. 说明,占', '/ə\'kaʊnt/', 'account', 3);
INSERT INTO `words` VALUES (28919, 'The boss dropped an accountant from the payroll.', 'n. 会计(员), 会计师', '/ə\'kauntənt | ə\'kaʊnt(ə)nt | ə\'kaʊntənt/', 'accountant', 3);
INSERT INTO `words` VALUES (28920, '...the accounting firm of Leventhal & Horwath.', 'n. 会计学； 会计', '/ə\'kauntɪŋ | ə\'kaʊntɪŋ/', 'accounting', 3);
INSERT INTO `words` VALUES (28921, 'This degree programme is fully accredited by the Institution of Electrical Engineers.', 'vt. 委任， 授权； 把…归于； 正式认可', '/ə\'kredɪt | ə\'krɛdɪt/', 'accredit', 3);
INSERT INTO `words` VALUES (28922, 'Over time, an implementation will accrete complexity as code is revisited for bug fixes and feature enhancements.', 'v. 共生, 附着, 增加', '/æ\'kri:t | ə\'kriːt | ə\'krit/', 'accrete', 3);
INSERT INTO `words` VALUES (28923, 'It is unjust that a privileged few should continue to accumulate wealth.', 'v. 积聚,堆积', '/ə\'kju:mjuleit | ə\'kjuːmjʊleɪt | ə\'kjumjəlet/', 'accumulate', 3);
INSERT INTO `words` VALUES (28924, '...an accumulation of experience and knowledge.', 'n. 积聚,堆积物', '/ə,kju:mju\'leiʃən | əkjuːmjʊ\'leɪʃ(ə)n | ə,kjʊmjə\'leʃən/', 'accumulation', 3);
INSERT INTO `words` VALUES (28925, 'Here is our accumulator which has that nitrogen overpressure which upon loss of pressure in the core would automatically insert coolant into the core should there be a break.', 'n. 蓄电池,积聚者', '/ə\'kju:mjuleitə | ə\'kjuːmjʊleɪtə | ə\'kjumjəletɚ/', 'accumulator', 3);
INSERT INTO `words` VALUES (28926, 'He passes the ball with unerring accuracy.', 'n. 精确性, 正确度', '/\'ækjurəsi | \'ækjʊrəsɪ | \'ækjərəsi/', 'accuracy', 3);
INSERT INTO `words` VALUES (28927, 'The brochure tries to give a fair and accurate description of each hotel.', 'adj. 准确的,精确的', '/\'ækjurət | \'ækjʊrət | \'ækjərət/', 'accurate', 3);
INSERT INTO `words` VALUES (28928, 'The main accusation levelled against him was that he tried to avoid military service.', 'n. 谴责, [律]指控', '/,ækju:\'zeiʃən | ækjʊ\'zeɪʃ(ə)n | ,ækju\'zeʃən/', 'accusation', 3);
INSERT INTO `words` VALUES (28929, 'The professor stands accused of (= has been accused of ) stealing his student’s ideas and publishing them.', 'v. 控告, 谴责', '/ə\'kju:z | ə\'kjuːz | ə\'kjuz/', 'accuse', 3);
INSERT INTO `words` VALUES (28930, 'She tried to accustom herself to the tight bandages.', 'v. 使习惯于', '/ə\'kʌstəm/', 'accustom', 3);
INSERT INTO `words` VALUES (28931, 'Y20 is a type of re-dispersible vinyl/acetate ethylene copolymerized emulsion powder.', 'n. [化]醋酸盐', '/\'æsiteit | \'æsɪteɪt | \'æsɪtet/', 'acetate', 3);
INSERT INTO `words` VALUES (28932, 'A 50% market share is achievable.', 'adj. 做得成的, 可完成的', '/ə\'tʃi:vəbəl | ə\'tʃivəbl/', 'achievable', 3);
INSERT INTO `words` VALUES (28933, 'Frances achieved very good exam results.', 'v. 完成,达到', '/ə\'tʃiːv | ə\'tʃiv/', 'achieve', 3);
INSERT INTO `words` VALUES (28934, 'His great achievement is to make all the players into a united team.', 'n. 成就,功绩', '/ə\'tʃiːvm(ə)nt | ə\'tʃivmənt/', 'achievement', 3);
INSERT INTO `words` VALUES (28935, '...three achingly beautiful ballads.', 'adv. 极其,非常痛地', '/\'ekɪŋli/', 'achingly', 3);
INSERT INTO `words` VALUES (28936, 'GR99027 meteorite from Blue Ice Area in Antarctica is an achondrite.', 'n. 不含球粒陨石', '/ei\'kɔndrait | ə\'kɒndraɪt | e\'kɑn,draɪt/', 'achondrite', 3);
INSERT INTO `words` VALUES (28937, 'sulphuric acid', 'n. 酸; adj. 酸的', '/\'æsid | \'æsɪd/', 'acid', 3);
INSERT INTO `words` VALUES (28938, 'Some fruit juices taste a bit acidic.', 'adj. 酸的,酸性的', '/ə\'sidik | ə\'sɪdɪk/', 'acidic', 3);
INSERT INTO `words` VALUES (28939, 'Blue cheese can be wrapped in foil, but remember to change the foil every few days as acidity will attack the foil.', 'n. 酸度, 酸性, [医]酸过多, 胃酸过多', '/ə\'sidəti | ə\'sɪdɪtɪ | ə\'sɪdəti/', 'acidity', 3);
INSERT INTO `words` VALUES (28940, 'The family acknowledge the need for change.', 'v. 承认, 答谢', '/ək\'nɔlidʒ | ək\'nɒlɪdʒ | ək\'nɑlɪdʒ/', 'acknowledge', 3);
INSERT INTO `words` VALUES (28941, 'First an acorn; then an oak tree forest.', 'n. 橡树果,橡子', '/\'eikɔ:n | \'eɪkɔːn | \'ekɔrn/', 'acorn', 3);
INSERT INTO `words` VALUES (28942, 'In our case, we have found the true acoustic echo beacon.', 'adj. 有关声音的, 声学的', '/ə\'ku:stik | ə\'kuːstɪk | ə\'kʊstɪk/', 'acoustic', 3);
INSERT INTO `words` VALUES (28943, 'The ancient Greeks were aware of other acoustical principles, at least empirically.', 'adj. 听觉的, 声学的', '/ə\'ku:stikəl | ə\'kuːstɪkəl | ə\'kʊstɪkl/', 'acoustical', 3);
INSERT INTO `words` VALUES (28944, 'Have steps been taken to acquaint breeders with their right to apply for licenses?', 'v. 使熟知, 通知', '/ə\'kweint | ə\'kweɪnt | ə\'kwent/', 'acquaint', 3);
INSERT INTO `words` VALUES (28945, 'She was a casual acquaintance of my family in Vienna.', 'n. 相识, 熟人', '/ə\'kweintəns | ə\'kweɪnt(ə)ns | ə\'kwentəns/', 'acquaintance', 3);
INSERT INTO `words` VALUES (28946, 'Steve seemed to acquiesce in the decision.', 'vi. 默许， 默认', '/ˌækwi\'es | ,ækwi\'es/', 'acquiesce', 3);
INSERT INTO `words` VALUES (28947, 'Manning hoped to acquire valuable works of art as cheaply as possible.', 'v. 获得,学到', '/ə\'kwaiə | ə\'kwaɪə | ə\'kwaɪr/', 'acquire', 3);
INSERT INTO `words` VALUES (28948, 'the acquisition of language', 'n. 获得(物)', '/,ækwɪ\'zɪʃ(ə)n | ,ækwɪ\'zɪʃən/', 'acquisition', 3);
INSERT INTO `words` VALUES (28949, 'All the defendants were acquitted.', 'vt. 宣告无罪； 表现', '/ə\'kwɪt/', 'acquit', 3);
INSERT INTO `words` VALUES (28950, 'They own 200 acres of farmland.', 'n. 英亩, 地产', '/\'eikə | \'eɪkə | \'ekɚ/', 'acre', 3);
INSERT INTO `words` VALUES (28951, 'The Palestinians would balk at that as far too much, even if they got the equivalent acreage back, perhaps adjacent to the Gaza Strip.', 'n. 英亩数, 面积', '/\'eikəridʒ | \'eɪk(ə)rɪdʒ | \'ekərɪdʒ/', 'acreage', 3);
INSERT INTO `words` VALUES (28952, 'Every new acronym I hear turns out to be another dirty trick designed to allow rich countries to go on with business as usual.', 'n. 只取首字母的缩写词', '/\'ækrəunim | \'ækrənɪm/', 'acronym', 3);
INSERT INTO `words` VALUES (28953, 'There’s Brendan. Why don’t you go across and say hello?', 'prep. 穿过,在对面', '/ə\'krɔs, ə\'krɔ:s | ə\'krɒs | ə\'krɔs/', 'across', 3);
INSERT INTO `words` VALUES (28954, 'The company acted correctly in sacking him.', 'v. 行动,表演; n. 行为', '/ækt/', 'act', 3);
INSERT INTO `words` VALUES (28955, 'The new acting president has a reputation of being someone who is independent.', 'adj. 代理的; n. 演戏， 表演', '/\'æktɪŋ/', 'acting', 3);
INSERT INTO `words` VALUES (28956, 'The government must take action (= do something ) now to stop the rise in violent crime.', 'n. 行动,行为,作用', '/\'ækʃən | \'ækʃ(ə)n/', 'action', 3);
INSERT INTO `words` VALUES (28957, 'Cooking fumes may activate the alarm.', 'v. 激活, 使活动', '/\'æktiveit | \'æktɪveɪt | \'æktə\'vet/', 'activate', 3);
INSERT INTO `words` VALUES (28958, 'games for active youngsters', 'adj. 积极的,活跃的,起作用的', '/\'æktiv | \'æktɪv/', 'active', 3);
INSERT INTO `words` VALUES (28959, 'You can actively argue with your mind.', 'adv. 活跃地, 积极地', '/\'æktivli/', 'actively', 3);
INSERT INTO `words` VALUES (28960, 'The police say they suspect the attack was carried out by animal rights activists.', 'n. 激进主义分子, 行动主义分子', '/\'æktivist | \'æktɪvɪst/', 'activist', 3);
INSERT INTO `words` VALUES (28961, 'His father was an actor in the Cantonese Opera Company.', 'n. 男演员,行动者', '/\'æktə | \'æktɚ/', 'actor', 3);
INSERT INTO `words` VALUES (28962, 'She\'s not only a great dramatic actress but she\'s also very funny.', 'n. 女演员', '/\'æktris | \'æktrɪs/', 'actress', 3);
INSERT INTO `words` VALUES (28963, 'I’m not joking. Those were his actual words.', 'adj. 实际的,真实的', '/\'æktʃuəl | \'æktʃʊəl; -tjʊəl/', 'actual', 3);
INSERT INTO `words` VALUES (28964, 'His business acumen helped him to succeed where others had failed.', 'n. 敏锐， 聪明', '/\'ækjəmən | əˈkjumən/', 'acumen', 3);
INSERT INTO `words` VALUES (28965, 'acute arthritis', 'adj. 敏锐的, 急性的', '/ə\'kju:t | ə\'kjuːt | ə\'kjut/', 'acute', 3);
INSERT INTO `words` VALUES (28966, 'She begged me to change my mind, but I remained adamant .', 'adj. 坚定不移的， 坚决的； 固执的', '/\'ædəmənt/', 'adamant', 3);
INSERT INTO `words` VALUES (28967, 'The ability to adapt is a definite asset in this job.', 'v. 适应,改编', '/ə\'dæpt/', 'adapt', 3);
INSERT INTO `words` VALUES (28968, 'You can achieve greater flexibility, adaptability, and independence when each layer is only loosely coupled to the layer above and below.', 'n. 适应性', '/ə,dæptə\'biləti | ə,dæptə\'bɪlətɪ | ə,dæptə\'bɪləti/', 'adaptability', 3);
INSERT INTO `words` VALUES (28969, 'The American Constitution has proved adaptable in changing political conditions.', 'adj. 能适应的,适应性强的', '/ə\'dæptəbl | ə\'dæptəb(ə)l/', 'adaptable', 3);
INSERT INTO `words` VALUES (28970, 'Branagh won two awards for his screen adaptation of Shakespeare\'s Henry the Fifth.', 'n. 适应, 改编, 改写本', '/,ədæp\'teiʃən | ædəp\'teɪʃ(ə)n | ,ædæp\'teʃən/', 'adaptation', 3);
INSERT INTO `words` VALUES (28971, 'Societies need to develop highly adaptive behavioural rules for survival.', 'adj. 适合的, 适应的', '/ə\'dæptiv | ə\'dæptɪv/', 'adaptive', 3);
INSERT INTO `words` VALUES (28972, 'Tobacco is highly addictive .', 'adj. 使人上瘾的； 使人沉醉的， 醉心的', '/ə\'dɪktɪv/', 'addictive', 3);
INSERT INTO `words` VALUES (28973, 'This is a fine book; a worthy addition to the series.', 'n. 加,增加,附加物', '/ə\'diʃən | ə\'dɪʃ(ə)n | ə\'dɪʃən/', 'addition', 3);
INSERT INTO `words` VALUES (28974, 'Additional information can be obtained from the centre.', 'adj. 另外的,附加的', '/ə\'diʃənəl | ə\'dɪʃ(ə)n(ə)l | ə\'dɪʃənl/', 'additional', 3);
INSERT INTO `words` VALUES (28975, 'All teachers are qualified to teach their native language. Additionally, we select our teachers for their engaging personalities.', 'adv. 另外, 同时', '/ə\'diʃənli | ə\'dɪʃənəlɪ | ə\'dɪʃənli/', 'additionally', 3);
INSERT INTO `words` VALUES (28976, 'As you build these kinds of simulations, or anything like this, you need to think through whether things should be multiplicative or additive.', 'adj. 附加的; n. 添加剂', '/\'æditiv | \'ædɪtɪv | \'ædətɪv/', 'additive', 3);
INSERT INTO `words` VALUES (28977, 'The address is 2025 M Street, NW, Washington, DC, 20036.', 'n. 地址,演说 vt写地址,演说', '/ə\'dres | ə\'drɛs/', 'address', 3);
INSERT INTO `words` VALUES (28978, 'I’m afraid she’s also an adept liar.', 'adj. 熟练的, 老练的 n老手, 擅长者', '/\'ædept, ə\'dept | ə\'dept; \'ædept | ə\'dɛpt/', 'adept', 3);
INSERT INTO `words` VALUES (28979, 'There are questions to be raised about the adequacy of the inmates\' legal representation.', 'n. 适当, 足够', '/\'ædikwəsi | \'ædɪkwəsɪ | \'ædəkwəsi/', 'adequacy', 3);
INSERT INTO `words` VALUES (28980, 'Farmers have been slow to make adequate provision for their retirement.', 'adj. 足够的,适当的', '/\'ædikwit | \'ædɪkwət | ˈædɪkwət/', 'adequate', 3);
INSERT INTO `words` VALUES (28981, 'They had equipped their workers adequately for such dangerous condition.', 'adv. 充分地', '/\'ædikwitli/', 'adequately', 3);
INSERT INTO `words` VALUES (28982, 'All members of the association adhere to a strict code of practice.', 'v. 粘附,遵守', '/əd\'hiə | əd\'hɪə | əd\'hɪr/', 'adhere', 3);
INSERT INTO `words` VALUES (28983, '...adhesive tape.', 'adj. 带黏性的; n. 胶合剂', '/əd\'hiːsɪv | əd\'hisɪv/', 'adhesive', 3);
INSERT INTO `words` VALUES (28984, 'We stayed in adjacent rooms.', 'adj. 邻近的,毗连的', '/ə\'dʒeisənt | ə\'dʒeɪs(ə)nt | ə\'dʒesnt/', 'adjacent', 3);
INSERT INTO `words` VALUES (28985, 'A vacant plot of land adjoins his house.', 'v. 邻接, 毗连', '/ə\'dʒɔin | ə\'dʒɒɪn | ə\'dʒɔɪn/', 'adjoin', 3);
INSERT INTO `words` VALUES (28986, 'For me, it represents a potent adjunct to antidepressant medications and, for some patients, it’s something you can take in lieu of pills.', 'n. 附件, 助手; adj. 附属的', '/\'ædʒʌŋkt | \'ædʒʌŋ(k)t/', 'adjunct', 3);
INSERT INTO `words` VALUES (28987, 'Check and adjust the brakes regularly.', 'v. 调整,校准', '/ə\'dʒʌst/', 'adjust', 3);
INSERT INTO `words` VALUES (28988, 'a period of adjustment', 'n. 调整, 调节', '/ə\'dʒʌstmənt | ə\'dʒʌs(t)m(ə)nt/', 'adjustment', 3);
INSERT INTO `words` VALUES (28989, 'The money will be administered by local charities.', 'v. 管理, 给予, 执行', '/əd\'ministə | əd\'mɪnɪstə | əd\'mɪnɪstɚ/', 'administer', 3);
INSERT INTO `words` VALUES (28990, 'We’re looking for someone with experience in administration.', 'n. 管理,经营', '/əd,mini\'streiʃən | ədmɪnɪ\'streɪʃ(ə)n | əd,mɪnɪ\'streʃən/', 'administration', 3);
INSERT INTO `words` VALUES (28991, 'The job is mainly administrative.', 'adj. 管理的，行政的', '/əd\'ministrətiv | əd\'mɪnɪstrətɪv | əd\'mɪnɪstretɪv/', 'administrative', 3);
INSERT INTO `words` VALUES (28992, 'On Friday the company\'s administrators sought permission from a Melbourne court to keep operating.', 'n. 管理人,行政官', '/əd\'ministreitə | əd\'mɪnɪstreɪtə | əd\'mɪnɪstretɚ/', 'administrator', 3);
INSERT INTO `words` VALUES (28993, 'an admirable achievement', 'adj. 令人钦佩的,令人赞赏的', '/\'ædmərəbl | \'ædm(ə)rəb(ə)l/', 'admirable', 3);
INSERT INTO `words` VALUES (28994, NULL, 'n. 海军上将, 舰队司令', '/\'ædmərəl | \'ædm(ə)r(ə)l/', 'admiral', 3);
INSERT INTO `words` VALUES (28995, 'Daniel gazed at her in admiration .', 'n. 钦佩, 赞美, 羡慕', '/,ædmə\'reiʃən | ædmə\'reɪʃ(ə)n | ,ædmə\'reʃən/', 'admiration', 3);
INSERT INTO `words` VALUES (28996, 'I really admire the way she brings up those kids all on her own.', 'v. 赞美,钦佩,羡慕', '/əd\'maiə | əd\'maɪə | ədˈmaɪr/', 'admire', 3);
INSERT INTO `words` VALUES (28997, 'Reese, by his own admission , lacks the necessary experience.', 'n. 允许进入, 承认, 许可', '/əd\'miʃən | əd\'mɪʃ(ə)n | əd\'mɪʃən/', 'admission', 3);
INSERT INTO `words` VALUES (28998, '‘Okay, so maybe I was a little bit scared,’ Jenny admitted.', 'v. 承认,准许', '/əd\'mit | əd\'mɪt/', 'admit', 3);
INSERT INTO `words` VALUES (28999, 'This has led to financial losses, though admittedly on a fairly small scale.', 'adv. 不可否认的, 公认地', '/əd\'mitidli | əd\'mɪtɪdlɪ | əd\'mɪtɪdli/', 'admittedly', 3);
INSERT INTO `words` VALUES (29000, '...a few blocks of adobe houses.', 'n. 泥砖，土坯', '/ə\'dəubi | ə\'dəʊbɪ; ə\'dəʊb | \'ədobɪ/', 'adobe', 3);
INSERT INTO `words` VALUES (29001, 'Some young people suddenly become self-conscious and tongue-tied in early adolescence.', 'n. 青春期', '/,ædəu\'lesəns,-sənsi | ædə\'les(ə)ns | ,ædə\'lɛsns/', 'adolescence', 3);
INSERT INTO `words` VALUES (29002, 'It is important that an adolescent boy should have an adult in whom he can confide.', 'adj. 青春期的; n. 青少年', '/,ædəu\'lesnt | ædə\'les(ə)nt | ,ædə\'lɛsnt/', 'adolescent', 3);
INSERT INTO `words` VALUES (29003, 'Sally was adopted when she was four.', 'v. 采用,收养', '/ə\'dɔpt | ə\'dɒpt | ə\'dɑpt/', 'adopt', 3);
INSERT INTO `words` VALUES (29004, 'She decided to put the baby up for adoption .', 'n. 采用, 收养', '/ə\'dɔpʃən | ə\'dɒpʃ(ə)n | ə\'dɑpʃən/', 'adoption', 3);
INSERT INTO `words` VALUES (29005, 'His watercolour designs adorn a wide range of books.', 'v. 装饰', '/ə\'dɔ:n | ə\'dɔːn | ə\'dɔrn/', 'adorn', 3);
INSERT INTO `words` VALUES (29006, 'It was a building without any adornment or decoration.', 'n. 装饰, 装饰品', '/ə\'dɔ:nmənt | ə\'dɔːnm(ə)nt/', 'adornment', 3);
INSERT INTO `words` VALUES (29007, 'But for some people merely imagining this scene creates an adrenaline surge.', 'n. 肾上腺素(使激动兴奋等)', '/ə\'drenəlin,-li:n, -lin | ə\'drenəlɪn | æˈdrɛnəˌlɪn/', 'adrenaline', 3);
INSERT INTO `words` VALUES (29008, NULL, 'a&ad. 漂流的,漫无目的', '/ə\'drift | ə\'drɪft/', 'adrift', 3);
INSERT INTO `words` VALUES (29009, 'She is a remarkably adroit and determined politician.', 'adj. 精明的， 干练的； 熟练的， 灵巧的', '/ə\'drɔɪt/', 'adroit', 3);
INSERT INTO `words` VALUES (29010, 'Some children find it difficult to talk to adults.', 'n. 成年人', '/\'ædʌlt, ə\'dʌlt | \'ædʌlt; ə\'dʌlt | \'ædʌlt/', 'adult', 3);
