INSERT INTO `words` VALUES (29120, 'Environmental issues such as noise and level of alertness may interfere with learning new behaviors.', 'n. 警戒, 机敏', '/ə\'lə:tnis | ə\'lɜːtnəs | ə\'lɝtnɪs/', 'alertness', 3);
