INSERT INTO `words` VALUES (29147, 'With friends, she sometimes alluded to a feeling that she herself was to blame for her son\'s predicament.', 'v. 暗指，提及', '/ə\'lju:d | ə\'l(j)uːd | ə\'lʊd/', 'allude', 3);
INSERT INTO `words` VALUES (29148, 'At 50, she had lost none of her sexual allure.', 'n&v. 诱惑， 吸引', '/ə\'lur | əˈlʊr/', 'allure', 3);
