INSERT INTO `words` VALUES (29150, 'alluvial flood plains', 'adj. 冲积的, 淤积的', '/ə\'lju:viəl | ə\'l(j)uːvɪəl | ə\'lʊvɪəl/', 'alluvial', 3);
