INSERT INTO `words` VALUES (29154, 'But in the stratosphere they can stay aloft for years, spread by fast winds known as jets, meaning the threat is global.', 'adv. 在高处, 在上', '/ə\'lɔft | ə\'lɒft/', 'aloft', 3);
