INSERT INTO `words` VALUES (29175, 'Methods outlined in the monograph include: use of crushed clay pots, bone charcoal, contact precipitation, or use of activated alumina (absorptive filter).', 'n. [化]氧化铝(亦称矾土)', '/ə\'lju:minə | ə\'luːmɪnə | ə\'lumɪnə/', 'alumina', 3);
