INSERT INTO `words` VALUES (29178, 'Always lock your bicycle to something secure.', 'adv. 总是,一直,始终,', '/\'ɔ:lweiz, -wiz | \'ɔːlweɪz; -ɪz | \'ɔlwez/', 'always', 3);
