INSERT INTO `words` VALUES (29249, 'Just one of these bombs could annihilate a city the size of New York.', 'v. 消灭,湮灭', '/ə\'naiə,leit | ə\'naɪɪleɪt | ə\'naɪəlet/', 'annihilate', 3);
