INSERT INTO `words` VALUES (29257, 'The space shuttle had stopped transmitting data, a very serious anomaly for the mission.', 'n. 不规则, 异常的人或物', '/ə\'nɔməli | ə\'nɒm(ə)lɪ | ə\'nɑməli/', 'anomaly', 3);
INSERT INTO `words` VALUES (29258, 'The moral management is a new concept derived from the social management. But which it faces is still the old problems of moral anomie and reconstruction of social order.', 'n. 社会道德沦丧， 失范； 混乱', '/\'ænəmi/', 'anomie', 3);
