INSERT INTO `words` VALUES (29271, 'This course examines computers anthropologically, as meaningful tools revealing the social and cultural orders that produce them.', 'adv. 人类学上', '/,ænθrəpə\'lɔdʒikəli/', 'anthropologically', 3);
INSERT INTO `words` VALUES (29272, 'This is something I learned as an anthropologist –people love to tell their stories.', 'n. 人类学家', '/,ænθrə\'pɔlədʒist | ,ænθrə\'pɒlədʒɪst | ,ænθrə\'pɑlədʒɪst/', 'anthropologist', 3);
INSERT INTO `words` VALUES (29273, '\"In anthropology, you can\'t equate third gender with homosexuality,\" he said.', 'n. 人类学', '/,ænθrə\'pɔlədʒi | ,ænθrə\'pɒlədʒɪ | \'ænθrə\'pɑlədʒi/', 'anthropology', 3);
INSERT INTO `words` VALUES (29274, 'The comments on webcam sites are rife with anthropomorphism, not surprisingly, and even when this is pointed out, the contributors are often undaunted.', 'n. 拟人论,拟人观', '/,ænθrəpəu\'mɔ:fizəm | ,ænθrəpə\'mɔːfɪz(ə)m | ,ænθrəpə\'mɔrfɪzəm/', 'anthropomorphism', 3);
