INSERT INTO `words` VALUES (29296, 'They have offices in countries as far apart as India and Peru.', 'adv. 相间隔,分离; adj. 分离(隔)的', '/ə\'pɑ:t | ə\'pɑːt | ə\'pɑrt/', 'apart', 3);
