INSERT INTO `words` VALUES (29315, 'We have had lots of applicants for these positions.', 'n. 申请者', '/\'æplɪkənt/', 'applicant', 3);
INSERT INTO `words` VALUES (29316, 'We receive hundreds of job applications each year.', 'n. 请求,申请,应用', '/,æpli\'keiʃən | ˌæplɪ\'keɪʃ(ə)n | ˌæpləˈkeʃən/', 'application', 3);
INSERT INTO `words` VALUES (29317, 'We need to apply for planning permission to build a garage.', 'v. 申请,应用', '/ə\'plai | ə\'plaɪ/', 'apply', 3);
