INSERT INTO `words` VALUES (29319, 'All consultations are by appointment only .', 'n. 约会, 指定', '/ə\'pɔintmənt | ə\'pɒɪntm(ə)nt | ə\'pɔɪntmənt/', 'appointment', 3);
