INSERT INTO `words` VALUES (30509, 'Widespread outbreaks of intestinal disease are so rare that the commensal bacteria face little danger of extermination.', 'adj. 共餐的; n. 共食伙伴, 共生物', '/kə\'mensəl | kə\'mens(ə)l | kə\'mɛnsl/', 'commensal', 3);
INSERT INTO `words` VALUES (30510, 'Some associations of species are almost a form of commensalism.', 'n. 共栖', '/kə\'mensəlizəm | kə\'mens(ə)lɪz(ə)m | kə\'mɛnsəlɪzəm/', 'commensalism', 3);
INSERT INTO `words` VALUES (30511, 'He was fined for making abusive comments to the referee.', 'n. 评论，意见 vt评论', '/\'kɔment | \'kɒment | \'kɑmɛnt/', 'comment', 3);
INSERT INTO `words` VALUES (30512, 'Commentary is by Tom Ferris.', 'n. 注释, 解说词', '/\'kɔməntəri | \'kɒmənt(ə)rɪ | \'kɑməntɛri/', 'commentary', 3);
INSERT INTO `words` VALUES (30513, 'political commentators', 'n. 评论员, 解说员', '/\'kɔmenteitə | \'kɒmənteɪtə | \'kɑmən\'tetɚ/', 'commentator', 3);
INSERT INTO `words` VALUES (30514, 'measures promoting local commerce and industry', 'n. 商业', '/\'kɒmɜːs | \'kɑmɝs/', 'commerce', 3);
INSERT INTO `words` VALUES (30515, 'Our top priorities must be profit and commercial growth.', 'adj. 商业的,贸易的', '/kə\'mə:ʃəl | kə\'mɜːʃ(ə)l | kə\'mɝʃəl/', 'commercial', 3);
INSERT INTO `words` VALUES (30516, 'Hardly anyone can escape the influence of commercialization.', 'n. 商品化', '/kə,mə:ʃəlai\'zeiʃən, -li\'z- | kə,mɜːʃəlaɪ\'zeɪʃən | kə,mɝʃəlɪ\'zeʃən/', 'commercialization', 3);
INSERT INTO `words` VALUES (30517, 'Christmas has become so commercialized.', 'v. 使商业化', '/kə\'mə:ʃəlaiz | kə\'mɝʃlaɪz/', 'commercialize', 3);
INSERT INTO `words` VALUES (30518, NULL, 'v. 使成粉末,粉碎', '/\'kɔminju:t | \'kɒmɪnjuːt | \'kɒməˌnjuːt/', 'comminute', 3);
INSERT INTO `words` VALUES (30519, 'a commission from the Academy for a new sculpture', 'n. 委员会 vt委任,委托', '/kə\'miʃən | kə\'mɪʃ(ə)n | kə\'mɪʃən/', 'commission', 3);
INSERT INTO `words` VALUES (30520, '...Alaska\'s commissioner of education.', 'n. 委员, 专员', '/kə\'miʃənə | kə\'mɪʃ(ə)nə | kə\'mɪʃənɚ/', 'commissioner', 3);
INSERT INTO `words` VALUES (30521, 'Women commit fewer crimes than men.', 'v. 犯罪, 承诺, 委托', '/kə\'mit | kə\'mɪt/', 'commit', 3);
INSERT INTO `words` VALUES (30522, 'Are you ready to make a long-term commitment ?', 'n. 委托事项,许诺', '/kə\'mitmənt | kə\'mɪtm(ə)nt | kə\'mɪtmənt/', 'commitment', 3);
