INSERT INTO `words` VALUES (30525, 'Women’s groups have become a commonplace.', 'n. 寻常的事物', '/\'kɔmənpleis | \'kɒmənpleɪs | \'kɑmən\'ples/', 'commonplace', 3);
INSERT INTO `words` VALUES (30526, 'I mean, in spite of this commonsense explanation, we are going to see how to prove this.', 'adj. 常识的,具有常识的', '/\'kɔmən\'sens/', 'commonsense', 3);
INSERT INTO `words` VALUES (30527, 'a communal bathroom', 'adj. 公共的，集体的', '/\'kɔmjunəl | \'kɒmjʊn(ə)l; kə\'mjuː- | kəˈmjunəl/', 'communal', 3);
INSERT INTO `words` VALUES (30528, NULL, 'adv. 共同地, 社区地', '/kə\'mjunəli/', 'communally', 3);
INSERT INTO `words` VALUES (30529, 'a hippie commune', 'vi. 与…亲密地交谈; n. 群体， 公社', '/\'kɒmjuːn | kə\'mju:n, \'kɔmju:n/', 'commune', 3);
INSERT INTO `words` VALUES (30530, 'We communicated mostly by e-mail.', 'v. 沟通,通信,传达', '/kə\'mjuːnɪkeɪt | kə\'mjunɪket/', 'communicate', 3);
INSERT INTO `words` VALUES (30531, 'Good communication is vital in a large organization.', 'n. 交流,通讯', '/kəmjuːnɪ\'keɪʃ(ə)n | kə,mjunɪ\'keʃən/', 'communication', 3);
INSERT INTO `words` VALUES (30532, 'Tom wasn’t very communicative, and kept himself to himself.', 'adj. 健谈的,交流的', '/kə\'mju:nikətiv | kə\'mjuːnɪkətɪv | kə\'mjunɪketɪv/', 'communicative', 3);
INSERT INTO `words` VALUES (30533, 'The new arts centre will serve the whole community.', 'n. 社会； 社团； 群落； 共同体', '/kə\'mjuːnəti | kəˈmjunətɪ/', 'community', 3);
INSERT INTO `words` VALUES (30534, 'Mike commutes to Miami every day.', 'v. 通勤, 折换; n. 乘车上下班', '/kə\'mjuːt | kə\'mjʊt/', 'commute', 3);
INSERT INTO `words` VALUES (30535, NULL, 'n. 通勤者, 每日往返上班者', '/kə\'mju:tə | kə\'mjuːtə(r) | kə\'mjʊtɚ/', 'commuter', 3);
INSERT INTO `words` VALUES (30536, 'The bushes grew in a compact mass.', 'v. 使坚实; n. 契约', '/kəm\'pækt, \'kɔmpækt | kəm\'pækt | \'kɑmpækt/', 'compact', 3);
INSERT INTO `words` VALUES (30537, NULL, 'n. 压紧,紧束之状态', '/kəm\'pækʃən/', 'compaction', 3);
INSERT INTO `words` VALUES (30538, 'This is gauged by the faithfulness of the implementation to the algorithm\'s specifications, the compactness of the algorithm, and the speed with which it encrypts.', 'n. 紧密, 简洁', '/kəm\'pæktnis/', 'compactness', 3);
INSERT INTO `words` VALUES (30539, 'For ten years he had been her constant companion .', 'n. 同伴, 共事者', '/kəm\'pænjən | kəm\'pænɪən/', 'companion', 3);
INSERT INTO `words` VALUES (30540, 'When Stan died, I missed his companionship.', 'n. 友谊', '/kəm\'pænjənʃip | kəm\'pænjənʃɪp | kəm\'pænjən\'ʃɪp/', 'companionship', 3);
INSERT INTO `words` VALUES (30541, 'Which company do you work for?', 'n. 公司', '/\'kʌmp(ə)ni | \'kʌmp(ə)nɪ | \'kʌmpəni/', 'company', 3);
INSERT INTO `words` VALUES (30542, 'A car of comparable size would cost far more abroad.', 'adj. 可比较的, 比得上的', '/\'kɔmpərəbl | \'kɒmp(ə)rəb(ə)l | \'kɑmpərəbl/', 'comparable', 3);
INSERT INTO `words` VALUES (30543, NULL, 'adv. 同等地,可比较地', '/\'kɔmpərəbli/', 'comparably', 3);
INSERT INTO `words` VALUES (30544, 'After a lifetime of poverty, his last few years were spent in comparable comfort.', 'adj. 比较的,相当的', '/kəm\'pærətiv | kəm\'pærətɪv/', 'comparative', 3);
INSERT INTO `words` VALUES (30545, 'The report compares the different types of home computer available.', 'v. 比较,对比,比喻; n. 比较', '/kəm\'peə | kəm\'pɛr/', 'compare', 3);
INSERT INTO `words` VALUES (30546, 'Her paintings invite comparison with those of the early Impressionists (= they remind you of them ) .', 'n. 比较,对照', '/kəm\'pærisən | kəm\'pærɪs(ə)n | kəm\'pærɪsn/', 'comparison', 3);
INSERT INTO `words` VALUES (30547, 'a map and compass', 'n. 罗盘,指南针', '/\'kʌmpəs/', 'compass', 3);
INSERT INTO `words` VALUES (30548, 'The new software is IBM compatible (= can be used with IBM computers ) .', 'adj. 谐调的,兼容的', '/kəm\'pætəbl | kəm\'pætɪb(ə)l/', 'compatible', 3);
INSERT INTO `words` VALUES (30549, '...the introduction of legislation to compel cyclists to wear a helmet.', 'v. 强迫, 迫使', '/kəm\'pel | kəm\'pɛl/', 'compel', 3);
INSERT INTO `words` VALUES (30550, 'Because my left eye is so weak, my right eye has to work harder to compensate.', 'v. 偿还, 补偿', '/\'kɔmpenseit | \'kɒmpenseɪt | \'kɑmpɛnset/', 'compensate', 3);
INSERT INTO `words` VALUES (30551, 'People who are wrongly arrested may be paid compensation .', 'n. 补偿, 赔偿', '/,kɔmpen\'seiʃən | kɒmpen\'seɪʃ(ə)n | ,kɑmpɛn\'seʃən/', 'compensation', 3);
INSERT INTO `words` VALUES (30552, 'She was awarded a large sum in compensatory damages .', 'adj. 赔偿的, 补偿的', '/kɒmpen\'seɪtərɪ | kəm\'pɛnsə,tori/', 'compensatory', 3);
INSERT INTO `words` VALUES (30553, 'He will be competing in the 100-metre race.', 'v. 竞争,比赛', '/kəm\'pi:t | kəm\'piːt | kəm\'pit/', 'compete', 3);
INSERT INTO `words` VALUES (30554, 'Typing is considered by most employers to be a basic competence.', 'n. 能力', '/\'kɔmpitəns | \'kɒmpɪt(ə)ns | \'kɑmpɪtəns/', 'competence', 3);
INSERT INTO `words` VALUES (30555, 'Going to trade fairs is an ideal opportunity to size up the competition .', 'n. 竞争,竞赛', '/,kɔmpi\'tiʃən | kɒmpɪ\'tɪʃ(ə)n | ,kɑmpə\'tɪʃən/', 'competition', 3);
INSERT INTO `words` VALUES (30556, 'Some US industries are not as competitive as they have been in the past.', 'adj. 竞争的', '/kəm\'petitiv | kəm\'petɪtɪv | kəm\'pɛtətɪv/', 'competitive', 3);
INSERT INTO `words` VALUES (30557, 'New machinery has enhanced the company’s productivity and competitiveness.', 'n. 竞争力,好竞争', '/kəm\'petitivnis | kəm\'petətɪvnɪs | kəm\'pɛtətɪvnɪs/', 'competitiveness', 3);
INSERT INTO `words` VALUES (30558, 'Last year they sold twice as many computers as their competitors.', 'n. 竞争者', '/kəm\'petitə | kəm\'petɪtə | kəm\'pɛtɪtɚ/', 'competitor', 3);
INSERT INTO `words` VALUES (30559, 'The document was compiled by the Department of Health.', 'v. 编译, 编辑', '/kəm\'pail | kəm\'paɪl/', 'compile', 3);
INSERT INTO `words` VALUES (30560, 'What you’re hearing is the voice of complacence.', 'n. 自满', '/kəm\'pleisns | kəm\'plesns/', 'complacence', 3);
INSERT INTO `words` VALUES (30561, 'Residents are complaining because traffic in the area has increased.', 'v. 抱怨,控诉', '/kəm\'plein | kəm\'pleɪn | kəm\'plen/', 'complain', 3);
INSERT INTO `words` VALUES (30562, 'If you wish to make a complaint, you should see the manager.', 'n. 诉苦, 抱怨', '/kəm\'pleint | kəm\'pleɪnt | kəm\'plent/', 'complaint', 3);
INSERT INTO `words` VALUES (30563, 'The green wallpaper is the perfect complement to the old pine of the dresser.', 'n. 补足物', '/\'kɔmplimənt | \'kɒmplɪm(ə)nt | ˈkɑːmplɪment/', 'complement', 3);
INSERT INTO `words` VALUES (30564, 'The computer and the human mind have different but complementary abilities.', 'adj. 补充的, 补足的', '/,kɔmpli\'mentəri | kɒmplɪ\'ment(ə)rɪ | \'kɑmplə\'mɛntri/', 'complementary', 3);
INSERT INTO `words` VALUES (30565, 'The house is nearing completion (= almost finished ) .', 'n. 完成', '/kəm\'pli:ʃən | kəm\'pliːʃn | kəm\'pliʃən/', 'completion', 3);
INSERT INTO `words` VALUES (30566, 'a complex system of highways', 'adj. 复杂的,复合的', '/\'kɔmpleks | \'kɒmpleks | kəm\'plɛks; \'kɑm,plɛks/', 'complex', 3);
INSERT INTO `words` VALUES (30567, 'a design of great complexity', 'n. 复杂(性),复杂的事物', '/kəm\'pleksiti | kəm\'pleksətɪ | kəm\'plɛksəti/', 'complexity', 3);
INSERT INTO `words` VALUES (30568, 'I think that is because we unnecessarily complicate it.', 'v. (使)变复杂', '/\'kɔmplikeit | \'kɒmplɪkeɪt | \'kɑmplɪket/', 'complicate', 3);
INSERT INTO `words` VALUES (30569, 'a complicated voting system', 'adj. 难懂的， 复杂的', '/\'kɑːmplɪkeɪtɪd | \'kɑmplɪketɪd/', 'complicated', 3);
INSERT INTO `words` VALUES (30570, 'The fact that the plane was late added a further complication to our journey.', 'n. 复杂化, (使复杂的)因素', '/,kɔmpli\'keiʃən | kɒmplɪ\'keɪʃ(ə)n | ,kɑmplɪ\'keʃən/', 'complication', 3);
INSERT INTO `words` VALUES (30571, 'The groom was so nervous he forgot to compliment the bridesmaids.', 'vt. 赞美， 称赞; n. 赞美；', '/\'kɒmplɪm(ə)nt | ˈkɑːmplɪmənt/', 'compliment', 3);
INSERT INTO `words` VALUES (30572, 'There was a complimentary bottle of champagne in the hotel room.', 'adj. 称赞的；免费的', '/,kɔmpli\'mentəri | kɒmplɪ\'ment(ə)rɪ | ,kɑmplɪ\'mɛntri/', 'complimentary', 3);
INSERT INTO `words` VALUES (30573, 'The commander said that the army would comply with the ceasefire.', 'v. 顺从,答应', '/kəm\'plai | kəm\'plaɪ/', 'comply', 3);
INSERT INTO `words` VALUES (30574, NULL, 'n. 组合物,混合涂料', '/\'kɒmpəʊ | \'kɑmpo/', 'compo', 3);
INSERT INTO `words` VALUES (30575, 'companies that make electronic components for computer products', 'n. 成分', '/kəm\'pəunənt | kəm\'pəʊnənt | kəm\'ponənt/', 'component', 3);
INSERT INTO `words` VALUES (30576, 'Barrington has composed the music for a new production of ‘A Midsummer Night’s Dream’.', 'v. 组成,写作', '/kəm\'pəuz | kəm\'pəʊz | kəm\'poz/', 'compose', 3);
INSERT INTO `words` VALUES (30577, '...music by Strauss, Mozart, Beethoven, and other great composers.', 'n. 作家,作曲家', '/kəm\'pəuzə | kəm\'pəʊzə | kəm\'pozɚ/', 'composer', 3);
INSERT INTO `words` VALUES (30578, 'The author builds up a useful compo-site picture of contemporary consumer culture.', 'adj. 合成的, 复合的 n合成物', '/\'kɔmpəzit | \'kɒmpəzɪt | kɑm\'pɑzɪt/', 'composite', 3);
INSERT INTO `words` VALUES (30579, 'Some minerals have complex chemical compositions.', 'n. 成分,作品,合成物', '/kɒmpə\'zɪʃ(ə)n | ,kɑmpə\'zɪʃən/', 'composition', 3);
INSERT INTO `words` VALUES (30580, NULL, 'adj. 合成的,组成的', '/,kɔmpə\'ziʃənəl | ,kɑmpə\'zɪʃənl/', 'compositional', 3);
INSERT INTO `words` VALUES (30581, '...a small compost heap.', 'n. 混合肥料', '/\'kɔmpɔst | \'kɒmpɒst | \'kɑmpost/', 'compost', 3);
INSERT INTO `words` VALUES (30582, 'man-made organic compounds', 'n. 混合物', '/\'kɒmpaʊnd | \'kɑmpaʊnd/', 'compound', 3);
INSERT INTO `words` VALUES (30583, 'She cannot comprehend the extent of the disaster.', 'v. 理解，领会', '/,kɔmpri\'hend | kɒmprɪ\'hend | ,kɑmprɪ\'hɛnd/', 'comprehend', 3);
INSERT INTO `words` VALUES (30584, 'Her speech was slurred and barely comprehensible.', 'adj. 可理解的', '/,kɔmpri\'hensəbl | kɒmprɪ\'hensɪb(ə)l | \'kɑmprɪ\'hɛnsəbl/', 'comprehensible', 3);
INSERT INTO `words` VALUES (30585, 'Why you let her talk you into doing such a foolish thing is beyond my comprehension (= impossible for me to understand ) .', 'n. 理解,包含', '/,kɔmpri\'henʃən | kɒmprɪ\'henʃ(ə)n | ,kɑmprɪ\'hɛnʃən/', 'comprehension', 3);
INSERT INTO `words` VALUES (30586, 'We offer our customers a comprehensive range of financial products.', 'adj. 全面的,能充分理解的', '/,kɔmpri\'hensiv | kɒmprɪ\'hensɪv | ˌkɑːmprɪˈhensɪv/', 'comprehensive', 3);
INSERT INTO `words` VALUES (30587, 'Light silk is best for parachutes, as it compresses well and then expands rapidly.', 'v. 压缩,摘要叙述', '/kəm\'pres, \'kɔmpres | kəm\'pres | kəm\'prɛs/', 'compress', 3);
INSERT INTO `words` VALUES (30588, 'As a group, multiplayer fabrics have the advantage of a large void volume in the non-compressible bade structure.', 'adj. 可压缩的', '/kəm\'presəbl | kəm\'presbl/', 'compressible', 3);
INSERT INTO `words` VALUES (30589, 'The following example shows how to create partition table with compression.', 'n. 浓缩, 压缩', '/kəm\'preʃən | kəm\'preʃ(ə)n | kəm\'prɛʃən/', 'compression', 3);
INSERT INTO `words` VALUES (30590, 'The house comprises two bedrooms, a kitchen, and a living room.', 'v. 包含, 由组成', '/kəm\'praiz | kəm\'praɪz/', 'comprise', 3);
INSERT INTO `words` VALUES (30591, 'Compromise is an inevitable part of marriage.', 'v&n. 妥协, 让步', '/\'kɔmprəmaiz | \'kɒmprəmaɪz | \'kɑmprəmaɪz/', 'compromise', 3);
INSERT INTO `words` VALUES (30592, 'the threat of compulsory redundancies', 'adj. 强制的, 义务的', '/kəm\'pʌlsəri | kəm\'pʌls(ə)rɪ/', 'compulsory', 3);
INSERT INTO `words` VALUES (30593, 'Final results had not yet been computed.', 'v. 计算, 估计', '/kəm\'pju:t | kəm\'pjuːt | kəm\'pjʊt/', 'compute', 3);
INSERT INTO `words` VALUES (30594, 'a huge global computer network', 'n. 计算机,电脑', '/kəm\'pju:tə | kəm\'pjuːtə | kəm\'pjutɚ/', 'computer', 3);
INSERT INTO `words` VALUES (30595, 'a concave lens', 'adj. 凹的 n凹(面)', '/kɔn\'keiv, \'kɔnkeiv | \'kɒnkeɪv | kɑn\'kev/', 'concave', 3);
INSERT INTO `words` VALUES (30596, 'The shadows concealed her as she crept up to the house.', 'v. 隐藏, 隐瞒', '/kən\'si:l | kən\'siːl | kən\'sil/', 'conceal', 3);
INSERT INTO `words` VALUES (30597, '‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.', 'v. 勉强, 承认, 退让 vi让步', '/kən\'si:d | kən\'siːd | kən\'sid/', 'concede', 3);
INSERT INTO `words` VALUES (30598, 'The conceit of the woman!', 'n. 自负， 自大', '/kən\'siːt | kən\'sit/', 'conceit', 3);
INSERT INTO `words` VALUES (30599, 'It is conceivable that you may get full compensation, but it’s not likely.', 'adj. 可能的,想得到的', '/kən\'si:vəbl | kən\'siːvəb(ə)l | kən\'sivəbl/', 'conceivable', 3);
INSERT INTO `words` VALUES (30600, NULL, 'adv. 可想到地, 想象中', '/kən\'si:vəbli | kən\'siːvəblɪ | kən\'sivəbli/', 'conceivably', 3);
INSERT INTO `words` VALUES (30601, 'Scientists first conceived the idea of the atomic bomb in the 1930’s.', 'v. 构想，设想', '/kən\'si:v | kən\'siːv | kən\'siv/', 'conceive', 3);
INSERT INTO `words` VALUES (30602, 'Now please concentrate.', 'v. 专心,集中,浓缩', '/\'kɔnsəntreit | \'kɒns(ə)ntreɪt | \'kɑnsn\'tret/', 'concentrate', 3);
INSERT INTO `words` VALUES (30603, 'She needed all her powers of concentration to stop herself from slipping on the icy road.', 'n. 集中,专心', '/,kɔnsən\'treiʃən | kɒns(ə)n\'treɪʃ(ə)n | \'kɑnsn\'treʃən/', 'concentration', 3);
INSERT INTO `words` VALUES (30604, 'concentric circles', 'adj. 同中心的, 同轴的', '/kən\'sentrik | kən\'sentrɪk | kən\'sɛntrɪk/', 'concentric', 3);
INSERT INTO `words` VALUES (30605, 'a new concept in business travel', 'n. 观念,概念', '/\'kɔnsept | \'kɒnsept | \'kɑnsɛpt/', 'concept', 3);
INSERT INTO `words` VALUES (30606, 'My conception of a garden was based on gardens I had visited in England.', 'n. 观念, 概念', '/kən\'sepʃən | kən\'sepʃ(ə)n | kən\'sɛpʃən/', 'conception', 3);
INSERT INTO `words` VALUES (30607, 'This study concerns couples’ expectations of marriage.', 'v. 有关于,使担心,', '/kən\'sɜːn | kən\'sɝn/', 'concern', 3);
INSERT INTO `words` VALUES (30608, 'a rock concert', 'n. 音乐会', '/kən\'sə:t, \'kɔnsə:t | \'kɒnsət | \'kɑnsɚt/', 'concert', 3);
INSERT INTO `words` VALUES (30609, NULL, 'n. 类似风琴的六角形的乐器', '/,kɔnsə\'ti:nə | ,kɒnsə\'tiːnə | ,kɑnsɚ\'tinə/', 'concertina', 3);
INSERT INTO `words` VALUES (30610, 'efforts to conciliate the unions', 'vt. 安抚， 抚慰； 调和', '/kən\'sɪlieɪt | kən\'sɪlɪet/', 'conciliate', 3);
INSERT INTO `words` VALUES (30611, 'Your summary should be as clear and concise as possible.', 'adj. 简明的,简练的', '/kən\'sais | kən\'saɪs/', 'concise', 3);
INSERT INTO `words` VALUES (30612, 'When the investigation is concluded, the results will be sent to the US Attorney’s office.', 'v. 推断出,结束,总结', '/kən\'klu:d | kən\'kluːd | kən\'klud/', 'conclude', 3);
INSERT INTO `words` VALUES (30613, 'These are the report’s main conclusions.', 'n. 结束,结论', '/kən\'klu:ʒən | kən\'kluːʒ(ə)n | kən\'kluʒn/', 'conclusion', 3);
INSERT INTO `words` VALUES (30614, 'If you want change in your life to be permanent, strong, and conclusive you need a support group.', 'adj. 决定性的,结论性的', '/kən\'klu:siv | kən\'kluːsɪv | kən\'klusɪv/', 'conclusive', 3);
INSERT INTO `words` VALUES (30615, NULL, 'adv. 最后地, 确定地', '/kən\'klu:sivli/', 'conclusively', 3);
INSERT INTO `words` VALUES (30616, 'John concocted an elaborate excuse for being late.', 'v. 编造；调制', '/kən\'kɔkt | kən\'kɒkt | kən\'kɑkt/', 'concoct', 3);
INSERT INTO `words` VALUES (30617, 'war with all its concomitant sufferings', 'adj. 伴随的; n. 伴随物', '/kən\'kɔmitənt | kən\'kɒmɪt(ə)nt | kən\'kɑmətənt/', 'concomitant', 3);
INSERT INTO `words` VALUES (30618, 'They expressed the hope that he would pursue a neutral and balanced policy for the sake of national concord.', 'n. 和睦； 公约', '/\'kɑːŋkɔːrd | \'kɑŋkɔrd/', 'concord', 3);
INSERT INTO `words` VALUES (30619, 'a concrete floor', 'adj. 实在的，具体的 n混凝土', '/kən\'kri:t, \'kɔnkri:t | \'kɒŋkriːt | \'kɑŋkrit/', 'concrete', 3);
INSERT INTO `words` VALUES (30620, 'Local feeling does not necessarily concur with the press.', 'v. 同时发生', '/kən\'kə: | kən\'kɜː | kən\'kɝ/', 'concur', 3);
INSERT INTO `words` VALUES (30621, 'The exhibition reflected concurrent developments abroad.', 'adj. 一致的；同时的', '/kən\'kʌrənt | kən\'kʌr(ə)nt | kən\'kɝənt/', 'concurrent', 3);
INSERT INTO `words` VALUES (30622, 'Politicians were quick to condemn the bombing.', 'v. 判刑,谴责', '/kən\'dem | kən\'dɛm/', 'condemn', 3);
INSERT INTO `words` VALUES (30623, NULL, 'n. 浓缩', '/kɒnden\'seɪʃ(ə)n | ,kɑndɛn\'seʃən/', 'condensation', 3);
INSERT INTO `words` VALUES (30624, 'condensed soup', 'v. (使)浓缩, 精简', '/kən\'dens | kən\'dɛns/', 'condense', 3);
INSERT INTO `words` VALUES (30625, 'You take that gas phase mixture, and you condense it in your condenser.', 'n. 冷凝器, 电容器', '/kən\'densə | kən\'dɛnsɚ/', 'condenser', 3);
INSERT INTO `words` VALUES (30626, 'When you summarize, you condense an extended idea or argument into a sentence or more in your own words.', 'v. 浓缩, 压缩', '/kən\'densiz/', 'condenses', 3);
INSERT INTO `words` VALUES (30627, 'Friendship is not only the condiment but also the anodyne of life.', 'n. 调味品', '/\'kɑːndɪmənt | \'kɑndɪmənt/', 'condiment', 3);
INSERT INTO `words` VALUES (30628, NULL, 'n. 调节者, 调节装置', '/kən\'diʃənə | kən\'dɪʃ(ə)nə | kən\'dɪʃənɚ/', 'conditioner', 3);
INSERT INTO `words` VALUES (30629, NULL, 'vi. 向…吊唁； 慰问', '/kən\'doul | kən\'dəul/', 'condole', 3);
INSERT INTO `words` VALUES (30630, 'Just like this California condor, which—though teetering on the edge of extinction—still soars near the Grand Canyon in Arizona and in the state it was named after.', 'n. [动]秃鹰, 秃鹫', '/\'kɔndɔ: | \'kɒndɔː | \'kɑndɔr/', 'condor', 3);
INSERT INTO `words` VALUES (30631, 'an environment conducive to learning', 'adj. 有助于…的， 有益于…的', '/kən\'duːsɪv | kən\'dusɪv/', 'conducive', 3);
INSERT INTO `words` VALUES (30632, 'The Senator’s conduct is being investigated by the Ethics Committee.', 'n. 行为; v. 引导,管理', '/\'kɔndʌkt, kən\'dʌkt | \'kɒndʌkt | kən\'dʌkt/', 'conduct', 3);
INSERT INTO `words` VALUES (30633, 'They measure skin conductance, or sweating response.', 'n. 电导, 导率', '/kən\'dʌktəns | kən\'dʌkt(ə)ns/', 'conductance', 3);
INSERT INTO `words` VALUES (30634, 'Temperature becomes uniform by heat conduction until finally a permanent state is reached.', 'n. 传导', '/kən\'dʌkʃən | kən\'dʌkʃ(ə)n/', 'conduction', 3);
INSERT INTO `words` VALUES (30635, 'It possesses incredible strength and elasticity, while its exceptionally high conductivity and use in flexible semiconductors could soup up computing.', 'n. 传导性, 传导率', '/,kɔndʌk\'tiviti | kɒndʌk\'tɪvɪtɪ | ,kɑndʌk\'tɪvəti/', 'conductivity', 3);
INSERT INTO `words` VALUES (30636, 'Wood is a poor conductor of heat.', 'n. 领导者, 经理', '/kən\'dʌktə | kən\'dʌktɚ/', 'conductor', 3);
INSERT INTO `words` VALUES (30637, '...orange traffic cones.', 'n. 圆锥体；', '/kəun | kəʊn | kon/', 'cone', 3);
INSERT INTO `words` VALUES (30638, NULL, 'n. 一种大篷马车', '/,kɔnis\'təugə/', 'conestoga', 3);
INSERT INTO `words` VALUES (30639, 'They\'ve entered this new confederacy because the central government\'s been unable to control the collapsing economy.', 'n. 联盟,邦联', '/kən\'fedərəsi | kən\'fed(ə)rəsɪ | kən\'fɛdərəsi/', 'confederacy', 3);
INSERT INTO `words` VALUES (30640, 'The young woman was his confederate, of course.', 'n. 同盟者,同盟国; adj. 同盟的; v. (使)联盟, 联合', '/kən\'fedərit, kən\'fedəreit | kən\'fed(ə)rət | kən\'fɛdəret/', 'confederate', 3);
INSERT INTO `words` VALUES (30641, 'The constitution also confers large powers on Brazil\'s 25 constituent states.', 'v. 授予, 协商', '/kən\'fə: | kən\'fɜː | kən\'fɝ/', 'confer', 3);
INSERT INTO `words` VALUES (30642, 'Representatives from over 100 countries attended the International Peace Conference in Geneva.', 'n. 会议, 讨论会', '/\'kɒnf(ə)r(ə)ns | \'kɑnfərəns/', 'conference', 3);
INSERT INTO `words` VALUES (30643, 'Sanchez’s confession was read out to the court.', 'n. 供认， 招供， 坦白； 供词； 承认', '/kən\'feʃn | kən\'fɛʃən/', 'confession', 3);
INSERT INTO `words` VALUES (30644, '...a close confidant of the president.', 'n. 知己， 密友', '/\'kɑːnfɪdænt | \'kɑnfɪdænt/', 'confidant', 3);
INSERT INTO `words` VALUES (30645, 'I felt I was doing well and my confidence began to grow.', 'n. 信心', '/\'kɔnfidəns | \'kɒnfɪd(ə)ns | \'kɑnfɪdəns/', 'confidence', 3);
INSERT INTO `words` VALUES (30646, 'Despite her disability, Philippa is very confident.', 'adj. 自信的, 确信的', '/\'kɔnfidənt | \'kɒnfɪd(ə)nt | \'kɑnfɪdənt/', 'confident', 3);
INSERT INTO `words` VALUES (30647, '...Stonehenge, in southwestern England, an ancient configuration of giant stones.', 'n. 构造, 结构', '/kən,fiɡju\'reiʃən | kən,fɪgə\'reɪʃ(ə)n; -gjʊ- | kən,fɪɡjə\'reʃən/', 'configuration', 3);
INSERT INTO `words` VALUES (30648, 'Vaughan is confined to a wheelchair .', 'v. 限制; n. 界限', '/kən\'faɪn/', 'confine', 3);
INSERT INTO `words` VALUES (30649, 'They were held in confinement for three weeks.', 'n. 限制, 禁闭', '/kən\'fainmənt | kən\'faɪnmənt/', 'confinement', 3);
INSERT INTO `words` VALUES (30650, 'Could you confirm the dates we discussed?', 'v. 确定,确认', '/kən\'fə:m | kən\'fɜːm | kən\'fɝm/', 'confirm', 3);
INSERT INTO `words` VALUES (30651, 'Miss Williams confiscated all our sweets.', 'vt. 没收， 充公， 征用', '/\'kɑːnfɪskeɪt | \'kɑnfɪsket/', 'confiscate', 3);
INSERT INTO `words` VALUES (30652, 'He conflates two images from Kipling’s short stories in the film.', 'v. 合并', '/kən\'fleit | kən\'fleɪt/', 'conflate', 3);
INSERT INTO `words` VALUES (30653, 'the threat of industrial conflict in the coalfields', 'n. 冲突,战斗; v. 冲突,抵触', '/kən\'flikt, \'kɔnflikt | \'kɒnflɪkt | \'kɑnflɪkt/', 'conflict', 3);
INSERT INTO `words` VALUES (30654, 'The 160-metre falls mark the dramatic confluence of the rivers Nera and Velino.', 'n. 汇合', '/\'kɔnfluəns | \'kɒnflʊəns | \'kɑnfluəns/', 'confluence', 3);
INSERT INTO `words` VALUES (30655, 'the pressure on schoolchildren to conform', 'v. 使一致, 遵从', '/kən\'fɔ:m | kən\'fɔːm | kən\'fɔrm/', 'conform', 3);
INSERT INTO `words` VALUES (30656, 'We must act in conformity with local regulations.', 'n. 一致, 符合', '/kən\'fɔ:miti | kən\'fɔːmɪtɪ | kən\'fɔrməti/', 'conformity', 3);
INSERT INTO `words` VALUES (30657, 'The problems confronting the new government were enormous.', 'v. 面临, 对抗', '/kən\'frʌnt/', 'confront', 3);
INSERT INTO `words` VALUES (30658, 'I understand the text but the diagrams are confusing me.', 'v. 搞乱,使糊涂', '/kən\'fju:z | kən\'fjuːz | kən\'fjʊz/', 'confuse', 3);
INSERT INTO `words` VALUES (30659, 'To avoid confusion, the teams wore different colours.', 'n. 混乱, 混淆', '/kən\'fju:ʒən | kən\'fjuːʒ(ə)n | kən\'fjʊʒən/', 'confusion', 3);
INSERT INTO `words` VALUES (30660, 'Frank was a very congenial colleague.', 'adj. 意气相投的,性格相似的', '/kən\'dʒi:njəl | kən\'dʒiːnɪəl | kən\'dʒinɪəl/', 'congenial', 3);
INSERT INTO `words` VALUES (30661, 'congenital abnormalities', 'adj. 先天的,天生的,天赋的', '/kən\'dʒenitəl | kən\'dʒenɪt(ə)l | kən\'dʒɛnɪtl/', 'congenital', 3);
INSERT INTO `words` VALUES (30662, NULL, 'v. 充满， 拥塞； 充血', '/kən\'dʒest | kən\'dʒɛst/', 'congest', 3);
INSERT INTO `words` VALUES (30663, 'The problems of traffic congestion will not disappear in a hurry.', 'n. 拥塞, 充血', '/kən\'dʒestʃ(ə)n | kən\'dʒɛstʃən/', 'congestion', 3);
