INSERT INTO `words` VALUES (30665, 'letters of congratulation', 'n. 祝贺， 道喜', '/kənˌgrætʃu\'leɪʃn | kən,ɡrætʃu\'leʃən/', 'congratulation', 3);
INSERT INTO `words` VALUES (30666, 'The President has lost the support of Congress.', 'n. (美国等国的)国会,议会', '/\'kɔŋɡres, kən\'ɡres | \'kɒŋgres | \'kɑŋɡrəs/', 'congress', 3);
INSERT INTO `words` VALUES (30667, 'The president explained his plans to congressional leaders.', 'adj. 会议的；国(议)会的', '/kən\'ɡreʃənəl | kən\'ɡrɛʃənl/', 'congressional', 3);
INSERT INTO `words` VALUES (30668, 'Red squirrels cut conifer cones from trees and bury them in plant litter on the forest floor.', 'n. [植]松类, 针叶树', '/\'kəunifə | \'kɒnɪfə; \'kəʊn- | \'kɑnəfɚ/', 'conifer', 3);
