INSERT INTO `words` VALUES (30670, 'There is something undeniably conjectural about such claims.', 'adj. 推测的,好推测的', '/kən\'dʒektʃərəl | kən\'dʒektʃ(ə)r(ə)l | kən\'dʒɛktʃərəl/', 'conjectural', 3);
INSERT INTO `words` VALUES (30671, 'In conjunction with LIFE.com, we bring you a list of the gifts that you should avoid as much as that next glass of eggnog you\'re considering right now.', 'n. 联合, 关联', '/kən\'dʒʌŋkʃən | kən\'dʒʌŋ(k)ʃ(ə)n/', 'conjunction', 3);
INSERT INTO `words` VALUES (30672, 'The magician conjured a rabbit out of his hat.', 'v. 变魔术， 变戏法； 召唤', '/\'kʌndʒər | \'kʌndʒɚ/', 'conjure', 3);
INSERT INTO `words` VALUES (30673, 'We’d like two rooms with connecting doors (= doors that join the rooms ) .', 'v. 连接,联系', '/kə\'nekt | kə\'nɛkt/', 'connect', 3);
