INSERT INTO `words` VALUES (30679, 'The Normans conquered England in 1066.', 'v. 征服, 战胜', '/\'kɔŋkə | \'kɒŋkə | \'kɑŋkɚ/', 'conquer', 3);
INSERT INTO `words` VALUES (30680, 'The people of an oppressed country obey their conquerors because they want to go on living.', 'n. 征服者, 胜利者', '/\'kɔŋkərə | \'kɒŋk(ə)rə(r) | \'kɑŋkərɚ/', 'conqueror', 3);
INSERT INTO `words` VALUES (30681, 'the Norman Conquest (= the conquest of England by the Normans )', 'n. 征服 战利品', '/\'kɔŋkwest | \'kɒŋkwest | \'kɑŋkwɛst/', 'conquest', 3);
INSERT INTO `words` VALUES (30682, 'A conscientious teacher may feel inclined to take work home.', 'adj. 认真的，勤勤恳恳的', '/,kɔnʃi\'enʃəs | ,kɒnʃɪ\'enʃəs | \'kɑnʃɪ\'ɛnʃəs/', 'conscientious', 3);
INSERT INTO `words` VALUES (30683, 'The driver was still conscious when the ambulance arrived.', 'adj. 意识到的，自觉的', '/\'kɔnʃəs | \'kɒnʃəs | \'kɑnʃəs/', 'conscious', 3);
INSERT INTO `words` VALUES (30684, 'They do not consciously think of themselves as a class.', 'adv. 有意识地, 自觉地', '/\'kɔnʃəsli | \'kɑnʃəsli/', 'consciously', 3);
INSERT INTO `words` VALUES (30685, 'The painful memories eventually faded from her consciousness.', 'n. 意识；觉悟,知觉', '/\'kɔnʃəsnis | \'kɒnʃəsnɪs | \'kɑnʃəsnəs/', 'consciousness', 3);
INSERT INTO `words` VALUES (30686, 'All adult males will be liable for conscription.', 'n. 征召', '/kən\'skripʃən | kən\'skrɪpʃ(ə)n | kən\'skrɪpʃən/', 'conscription', 3);
INSERT INTO `words` VALUES (30687, 'It had rained for four consecutive days.', 'adj. 连贯的,连续不断的', '/kən\'sekjutiv | kən\'sekjʊtɪv | kən\'sɛkjətɪv/', 'consecutive', 3);
INSERT INTO `words` VALUES (30688, 'The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.', 'n. 一致，同意', '/kən\'sensəs | kən\'sɛnsəs/', 'consensus', 3);
INSERT INTO `words` VALUES (30689, 'The chairman was elected by common consent (= with most people agreeing ) .', 'n& vi. 同意，赞成', '/kən\'sent | kən\'sɛnt/', 'consent', 3);
INSERT INTO `words` VALUES (30690, 'Her lawyer said she understood the consequences of her actions and was prepared to go to jail.', 'n. 结果', '/\'kɔnsi,kwəns | \'kɒnsɪkw(ə)ns | \'kɑnsəkwɛns/', 'consequence', 3);
INSERT INTO `words` VALUES (30691, 'If we got an if then statement are we asserting an antecedent, an if clause or the consequent, Q the then clause, or are we saying if P then Q.', 'n. 推论,结论', '/\'kɔnsi,kwənt | \'kɒnsɪkw(ə)nt | \'kɑnsəkwənt/', 'consequent', 3);
INSERT INTO `words` VALUES (30692, 'wildlife conservation', 'n. 保存,保持', '/,kɔnsə\'veiʃən | kɒnsə\'veɪʃ(ə)n | ,kɑnsɚ\'veʃən/', 'conservation', 3);
INSERT INTO `words` VALUES (30693, 'Conservationists say the law must be strengthened.', 'n. 自然环境保护论者', '/ˌkɑːnsər\'veɪʃənɪst | ,kɑnsɚ\'veʃənɪst/', 'conservationist', 3);
INSERT INTO `words` VALUES (30694, 'people’s innate conservatism in matters of language', 'n. 保守主义', '/kən\'sə:və,tizəm | kən\'sɜːvə,tɪzəm | kən\'sɝvətɪzəm/', 'conservatism', 3);
INSERT INTO `words` VALUES (30695, 'a very conservative attitude to education', 'adj. 保守的,守旧的', '/kən\'sə:vətiv | kən\'sɜːvətɪv | kən\'sɝvətɪv/', 'conservative', 3);
INSERT INTO `words` VALUES (30696, 'We must conserve our woodlands for future generations.', 'v. 保存,保藏', '/kən\'sə:v, \'kɔnsə:v | kən\'sɜːv | kən\'sɝv/', 'conserve', 3);
INSERT INTO `words` VALUES (30697, 'We will have to consider your offer carefully .', 'v. 考虑,认为', '/kən\'sidə | kən\'sɪdə | kən\'sɪdɚ/', 'consider', 3);
INSERT INTO `words` VALUES (30698, 'Michael has already spent considerable time in Barcelona.', 'adj. 重要的,相当大的,可观的', '/kən\'sidərəbl | kən\'sɪd(ə)rəb(ə)l | kən\'sɪdərəbl/', 'considerable', 3);
INSERT INTO `words` VALUES (30699, 'I think he\'s the most charming, most considerate man I\'ve ever known.', 'adj. 考虑周到的， 体贴的， 体谅的', '/kən\'sɪdərət | kənˈsɪdərɪt/', 'considerate', 3);
INSERT INTO `words` VALUES (30700, 'proposals put forward for consideration', 'n. 考虑, 体贴', '/kən,sidə\'reiʃən | kənsɪdə\'reɪʃ(ə)n | kən,sɪdə\'reʃən/', 'consideration', 3);
INSERT INTO `words` VALUES (30701, 'My diet consisted almost exclusively of chocolate-covered cookies and glasses of milk.', 'v. 由组成,在于', '/kən\'sɪst/', 'consist', 3);
INSERT INTO `words` VALUES (30702, 'She scores goals with remarkable consistency.', 'n. 坚固性, 浓度, 一致性', '/kən\'sistənsi | kən\'sɪst(ə)nsɪ | kən\'sɪstənsi/', 'consistency', 3);
INSERT INTO `words` VALUES (30703, 'She’s the team’s most consistent player.', 'adj. 一致的,调和的', '/kən\'sistənt | kən\'sɪst(ə)nt | kən\'sɪstənt/', 'consistent', 3);
INSERT INTO `words` VALUES (30704, 'Instead, we should be articulating guidelines that answer consistently the questions: Who should we support in the Middle East?', 'adv. 一致地；始终如一地', '/kən\'sistəntli | kən\'sɪstəntli/', 'consistently', 3);
INSERT INTO `words` VALUES (30705, 'No one could console her when Peter died.', 'vt. 安慰， 抚慰', '/kən\'soul | \'kɑnsol/', 'console', 3);
INSERT INTO `words` VALUES (30706, 'The company has consolidated its position as the country’s leading gas supplier.', 'v. 合并,统一,巩固', '/kən\'sɔlideit | kən\'sɒlɪdeɪt | kən\'sɑlɪdet/', 'consolidate', 3);
INSERT INTO `words` VALUES (30707, 'Enable users to submit consolidation nodes, even if not all leaf nodes have been opened.', 'n. 巩固, 合并', '/kən,sɔli\'deiʃən | kən,sɒlɪ\'deɪʃən | kən,sɑlə\'deʃən/', 'consolidation', 3);
INSERT INTO `words` VALUES (30708, 'This policy is scarcely consonant with the government’s declared aims.', 'adj. 和谐的，协调的，符合的; n. 辅音', '/\'kɑːnsənənt | \'kɑnsənənt/', 'consonant', 3);
INSERT INTO `words` VALUES (30709, 'The public has accepted Camilla, Prince Charles’s former mistress, as his consort.', 'v. 结交,符合; n. 配偶', '/\'kɔnsɔ:t | \'kɒnsɔːt | \'kɑn,sɔrt/', 'consort', 3);
INSERT INTO `words` VALUES (30710, 'a consortium of oil companies', 'n. 财团, 联合, 合伙', '/kən\'sɔ:tjəm | kən\'sɔːtɪəm | kənˈsɔrʃiəm/', 'consortium', 3);
INSERT INTO `words` VALUES (30711, 'The notice must be displayed in a conspicuous place.', 'adj. 显著的, 显眼的', '/kən\'spikjuəs | kən\'spɪkjʊəs/', 'conspicuous', 3);
INSERT INTO `words` VALUES (30712, 'There were many conspiracy theories (= beliefs that something is the result of a conspiracy ) surrounding Princess Diana’s death.', 'n. 共谋, 阴谋', '/kən\'spirəsi | kən\'spɪrəsɪ | kən\'spɪrəsi/', 'conspiracy', 3);
INSERT INTO `words` VALUES (30713, 'There was a constant stream of visitors to the house.', 'adj. 不变的,持续的', '/\'kɔnstənt | \'kɒnst(ə)nt | \'kɑnstənt/', 'constant', 3);
