INSERT INTO `words` VALUES (31120, 'She dedicated her first album to Woody Allen, who she says understands her obsession.', 'v. 献(身), 致力', '/\'dedikeit, \'dedikit, -keit | \'dedɪkeɪt | \'dɛdɪket/', 'dedicate', 3);
INSERT INTO `words` VALUES (31121, 'To reach a high level of skill requires talent, dedication, and a lot of hard work.', 'n. 贡献, 奉献', '/dedɪ\'keɪʃ(ə)n | ,dɛdɪ\'keʃən/', 'dedication', 3);
