INSERT INTO `words` VALUES (31150, 'What we need is a means to objectively evaluate code quality, something that can tell us, definitively, that the code we\'re looking at is risky.', 'adv. 决定性地, 最后地', '/\'definitivli/', 'definitively', 3);
INSERT INTO `words` VALUES (31151, 'He deflected the blow with his forearm.', 'v. (使)偏斜, (使)偏转', '/di\'flekt | dɪ\'flekt | dɪ\'flɛkt/', 'deflect', 3);
INSERT INTO `words` VALUES (31152, 'Wearing badly-fitting shoes can deform your feet.', 'v. (使)变形', '/di\'fɔ:m | dɪ\'fɔːm | dɪ\'fɔrm/', 'deform', 3);
