INSERT INTO `words` VALUES (31160, '...air pollution, traffic congestion, and the steady degradation of our quality of life.', 'n. 降级, 降格, 退化', '/,deɡrə\'deiʃən | ,degrə\'deɪʃ(ə)n | ,dɛɡrə\'deʃən/', 'degradation', 3);
