INSERT INTO `words` VALUES (31196, 'It seems clear that despite official denials, differences of opinion lay behind the ambassador\'s decision to quit.', 'n. 否认,谢绝', '/di\'naiəl | dɪ\'naɪ(ə)l | dɪ\'naɪəl/', 'denial', 3);
