INSERT INTO `words` VALUES (31199, 'What does the word ‘curriculum’ denote that ‘course’ does not?', 'v. 表示， 意指； 标示， 预示， 象征', '/dɪ\'nout | dɪ\'not/', 'denote', 3);
INSERT INTO `words` VALUES (31200, 'The group denounced the failure by the authorities to take action.', 'vt. 谴责， 公开指责， 抨击； 告发', '/dɪ\'nauns | dɪ\'naʊns/', 'denounce', 3);
