INSERT INTO `words` VALUES (31202, 'The most densely developed areas appear white and gray, while suburban areas appear grayish green—a mixture of houses, streets, and lawns.', 'adv. 浓密地', '/\'densli | \'dɛnsli/', 'densely', 3);
INSERT INTO `words` VALUES (31203, 'areas of high population density', 'n. 密度', '/\'densəti | \'densɪtɪ | \'dɛnsəti/', 'density', 3);
