INSERT INTO `words` VALUES (31248, 'The streets were deserted.', 'adj. 荒废的， 空无一人的； 被离弃的， 被遗弃的', '/dɪ\'zɜːrtɪd | dɪ\'zɝtɪd/', 'deserted', 3);
