INSERT INTO `words` VALUES (31256, 'The ability to speak a foreign language is highly desirable .', 'adj. 值得拥有的,可取的', '/di\'zaiərəbl | dɪ\'zaɪərəb(ə)l | dɪ\'zaɪərəbl/', 'desirable', 3);
