INSERT INTO `words` VALUES (31267, 'companies that are polluting and destroying the environment', 'v. 破坏,毁灭,消灭', '/di\'strɔi | dɪ\'strɒɪ | dɪ\'strɔɪ/', 'destroy', 3);
INSERT INTO `words` VALUES (31268, '{\"COLLOINEXA\":[\"weapons of mass destruction\"]}', 'n. 破坏,毁灭', '/di\'strʌkʃən | dɪ\'strʌkʃ(ə)n | dɪ\'strʌkʃən/', 'destruction', 3);
INSERT INTO `words` VALUES (31269, 'the destructive power of modern weapons', 'adj. 破坏(性)的', '/di\'strʌktiv | dɪ\'strʌktɪv/', 'destructive', 3);
INSERT INTO `words` VALUES (31270, 'Please detach and fill out the application form.', 'v. 拆卸,使分开', '/di\'tætʃ | dɪ\'tætʃ/', 'detach', 3);
INSERT INTO `words` VALUES (31271, 'The upright orientation is also the first step in surface detachment for bacteria.', 'n. 冷漠, 脱离', '/di\'tætʃmənt | dɪ\'tætʃm(ə)nt | dɪ\'tætʃmənt/', 'detachment', 3);
INSERT INTO `words` VALUES (31272, 'This issue will be discussed in more detail in Chapter 5.', 'n. 细节,详情; v. 详述', '/\'di:teil, di\'teil | \'diːteɪl | \'ditel/', 'detail', 3);
INSERT INTO `words` VALUES (31273, 'Many forms of cancer can be cured if detected early.', 'v. 察觉,侦查,发现', '/di\'tekt | dɪ\'tekt | dɪ\'tɛkt/', 'detect', 3);
INSERT INTO `words` VALUES (31274, 'Doctors say the disease is probably inherited but not detectable at birth.', 'adj. 可发现的,可察觉的', '/di\'tektəbl | dɪ\'tɛktəbl/', 'detectable', 3);
INSERT INTO `words` VALUES (31275, '...the early detection of breast cancer.', 'n. 察觉, 侦查', '/di\'tekʃən | dɪ\'tekʃ(ə)n | dɪ\'tɛkʃən/', 'detection', 3);
INSERT INTO `words` VALUES (31276, '...Arthur Conan Doyle\'s classic detective novel.', 'adj. 侦探的; n. 侦探，私人侦探', '/dɪ\'tektɪv | dɪ\'tɛktɪv/', 'detective', 3);
INSERT INTO `words` VALUES (31277, 'The company’s financial difficulties have deterred potential investors.', 'v. 阻止', '/di\'tə: | dɪ\'tɜː | dɪ\'tɝ/', 'deter', 3);
INSERT INTO `words` VALUES (31278, 'During dry place, keep within the new air circulation, avoid rain and insolate, also can use some detergent to remove odor.', 'adj. 净化的， 清洁的; n. 清洁剂', '/dɪ\'tɜːrdʒənt | dɪ\'tɝdʒənt/', 'detergent', 3);
INSERT INTO `words` VALUES (31279, 'Ethel’s health has deteriorated.', 'v. (使)恶化', '/di\'tiəriəreit | dɪ\'tɪərɪəreɪt | dɪ\'tɪrɪəret/', 'deteriorate', 3);
INSERT INTO `words` VALUES (31280, 'There are fears that the situation might deteriorate into full-scale war.', 'v. 恶化，变坏', '/di\'tiəriəreit | dɪ\'tɪərɪəreɪt | dɪ\'tɪrɪəret/', 'deteriorates', 3);
INSERT INTO `words` VALUES (31281, NULL, 'n. 变坏, 退化', '/di,tiəriə\'reiʃən | dɪ,tɪərɪə\'reɪʃn | dɪ,tɪrɪə\'reʃən/', 'deterioration', 3);
INSERT INTO `words` VALUES (31282, 'I used this to remember how to calculate the determinant of a matrix.', 'adj. 决定性的; n. 决定因素', '/di\'tə:minənt | dɪ\'tɜːmɪnənt | dɪ\'tɝmɪnənt/', 'determinant', 3);
INSERT INTO `words` VALUES (31283, 'his dogged determination (= very strong determination ) to succeed', 'n. 决心, 果断', '/dɪ,tɜːmɪ\'neɪʃ(ə)n | dɪˌtɜːrmɪˈneɪʃn/', 'determination', 3);
INSERT INTO `words` VALUES (31284, 'Investigators are still trying to determine the cause of the fire.', 'v. 查明， 确定； 决心， 决定； 支配， 影响', '/dɪ\'tɜːrmɪn | dɪ\'tɝmɪn/', 'determine', 3);
INSERT INTO `words` VALUES (31285, NULL, 'adv. 决然地,断然地', '/di\'tə:mindli/', 'determinedly', 3);
INSERT INTO `words` VALUES (31286, 'The small fines for this type of crime do not act as much of a deterrent .', 'n. 威慑 a遏制的', '/di\'terənt | dɪ\'ter(ə)nt | dɪ\'tɝənt/', 'deterrent', 3);
INSERT INTO `words` VALUES (31287, 'The two men detested each other.', 'v. 憎恶', '/dɪ\'test | dɪ\'tɛst/', 'detest', 3);
INSERT INTO `words` VALUES (31288, 'They feared that the publicity surrounding him would detract from their own election campaigns.', 'v. 转移', '/di\'trækt | dɪ\'trækt/', 'detract', 3);
INSERT INTO `words` VALUES (31289, 'The attack took many by surprise, because few had anticipated that the major detractor of the faith would be one of our own.', 'n. 诽谤者', '/di\'træktə | dɪ\'træktɚ/', 'detractor', 3);
INSERT INTO `words` VALUES (31290, 'In the distance, the detritus of a century of oil exploration lines the horizon.', 'n. 碎石', '/di\'traitəs | dɪ\'traɪtəs/', 'detritus', 3);
INSERT INTO `words` VALUES (31291, 'The city centre was devastated by the bomb.', 'v. 毁坏', '/\'devəsteit | \'devəsteɪt | \'dɛvəstet/', 'devastate', 3);
INSERT INTO `words` VALUES (31292, 'The war brought massive devastation and loss of life to the region.', 'n. 毁坏,荒废', '/,devə\'steiʃən | ,devə\'steɪʃn/', 'devastation', 3);
INSERT INTO `words` VALUES (31293, 'a Florida property developer', 'n. 开发者', '/di\'veləpə | dɪ\'veləpə(r) | dɪ\'vɛləpɚ/', 'developer', 3);
INSERT INTO `words` VALUES (31294, 'the developmental stages of childhood', 'adj. 发展的, 进化的', '/di,veləp\'mentəl | dɪ,veləp\'ment(ə)l | dɪ,vɛləp\'mɛntl/', 'developmental', 3);
INSERT INTO `words` VALUES (31295, 'deviant behaviour', 'adj. 不正常的，越出常规的; n. 不正常的人', '/\'diːviənt | \'divɪənt/', 'deviant', 3);
INSERT INTO `words` VALUES (31296, 'They stopped you as soon as you deviated from the script.', 'v. 偏离,偏轨', '/\'di:vieit, \'di:viət | \'diːvɪeɪt | \'divɪet/', 'deviate', 3);
INSERT INTO `words` VALUES (31297, 'Deviation from the norm is not tolerated.', 'n. 背离,偏离', '/,di:vi\'eiʃən | diːvɪ\'eɪʃ(ə)n | \'divɪ\'eʃən/', 'deviation', 3);
INSERT INTO `words` VALUES (31298, 'The recording device has activated.', 'n. 装置,设备', '/di\'vais | dɪ\'vaɪs/', 'device', 3);
INSERT INTO `words` VALUES (31299, 'She devised a method for quicker communications between offices.', 'v. 设计,发明', '/di\'vaiz | dɪ\'vaɪz/', 'devise', 3);
INSERT INTO `words` VALUES (31300, 'I have never looked on a face that was so devoid of feeling.', 'adj. 全无的, 缺乏的', '/di\'vɔid | dɪ\'vɒɪd | dɪ\'vɔɪd/', 'devoid', 3);
INSERT INTO `words` VALUES (31301, 'He decided to devote the rest of his life to scientific investigation.', 'v. 投入于, 献身', '/di\'vəut | dɪ\'vəʊt | dɪ\'vot/', 'devote', 3);
INSERT INTO `words` VALUES (31302, 'At first she was flattered by his devotion.', 'n. 献身, 热爱', '/di\'vəuʃən | dɪ\'vəʊʃ(ə)n | dɪ\'voʃən/', 'devotion', 3);
INSERT INTO `words` VALUES (31303, 'The boys devoured their pancakes.', 'v. 吞食,吞没', '/dɪ\'vaʊə | dɪ\'vaʊɚ/', 'devour', 3);
INSERT INTO `words` VALUES (31304, 'a devout Catholic', 'adj. 虔敬的； 诚恳的', '/dɪ\'vaut | dɪ\'vaʊt/', 'devout', 3);
INSERT INTO `words` VALUES (31305, 'The dew gathered on the leaves.', 'n. 露水', '/dju:, du: | \'djuː | du/', 'dew', 3);
INSERT INTO `words` VALUES (31306, 'dextrous use of the needle', 'adj. 惯用右手的； 灵巧的， 熟练的', '/\'dekstrəs | \'dɛkstrəs/', 'dexterous', 3);
INSERT INTO `words` VALUES (31307, 'The soldiers were diagnosed as having flu.', 'v. 诊断； 判断', '/ˌdaɪəg\'nous | ,daɪəɡ\'nos/', 'diagnose', 3);
INSERT INTO `words` VALUES (31308, 'Next, move to the diagonal section at the back-right side of the diamond.', 'n&a. 对角线(的)', '/dai\'æɡənəl | daɪ\'æg(ə)n(ə)l | daɪ\'æɡənl/', 'diagonal', 3);
INSERT INTO `words` VALUES (31309, 'Rising diagonally from the ground to the right of Venus is the band of our Milky Way Galaxy.', 'adv. 斜对地, 对角地', '/dai\'ægənəli | daɪ\'æg(ə)nəlɪ; daɪ\'ægən(ə)lɪ | daɪ\'ægənəli/', 'diagonally', 3);
INSERT INTO `words` VALUES (31310, '...a circuit diagram.', 'n. 图表', '/\'daiəɡræm | \'daɪəgræm | \'daɪəɡræm/', 'diagram', 3);
INSERT INTO `words` VALUES (31311, 'the local dialect', 'n. 方言', '/\'daiəlekt | \'daɪəlekt | \'daɪə\'lɛkt/', 'dialect', 3);
INSERT INTO `words` VALUES (31312, 'a boring movie full of bad dialog', 'n. 对话', '/\'daiə,lɔɡ | \'daɪəlɒg | \'daɪəlɑɡ/', 'dialogue', 3);
INSERT INTO `words` VALUES (31313, '...a tube less than a fifth of the diameter of a human hair.', 'n. 直径', '/dai\'æmitə | daɪ\'æmɪtə | daɪ\'æmɪtɚ/', 'diameter', 3);
INSERT INTO `words` VALUES (31314, 'a diamond engagement ring', 'n. 钻石,金钢石', '/\'daiəmənd | \'daɪəmənd/', 'diamond', 3);
INSERT INTO `words` VALUES (31315, 'There is a natural dichotomy between the two sides of one’s personality that is usually displayed between the different types of social groups with which an individual may identify oneself.', 'n. 两分, 二分法', '/dai\'kɔtəmi | daɪ\'kɒtəmɪ; dɪ- | daɪ\'kɑtəmi/', 'dichotomy', 3);
INSERT INTO `words` VALUES (31316, 'Or a dictaphone.', 'n. 录音电话机（商标名称） [商标名] 录音机', '/\'diktəfəun/', 'dictaphone', 3);
INSERT INTO `words` VALUES (31317, 'Federal funds have to be used as dictated by Washington.', 'v. 口授；命令', '/dik\'teit, \'dikteit | dɪk\'teɪt | \'dɪktet/', 'dictate', 3);
INSERT INTO `words` VALUES (31318, NULL, 'n. 措辞, 用语, 言语', '/\'dikʃən | \'dɪkʃ(ə)n | \'dɪkʃən/', 'diction', 3);
INSERT INTO `words` VALUES (31319, 'He died in 1985 at the age of 76.', 'v. 死亡', '/dai | daɪ/', 'die', 3);
INSERT INTO `words` VALUES (31320, 'She doesn’t eat a very healthy diet .', 'n. 通常所吃的食物,会议', '/\'daiət | \'daɪət/', 'diet', 3);
INSERT INTO `words` VALUES (31321, 'special dietary requirements', 'adj. 饮食的; n. 规定的食物', '/\'daɪət(ə)rɪ | \'daɪə,tɛri/', 'dietary', 3);
INSERT INTO `words` VALUES (31322, 'The two systems differ in many respects.', 'v. 不同,有区别; n. 区别', '/\'difə | \'dɪfə | \'dɪfɚ/', 'differ', 3);
INSERT INTO `words` VALUES (31323, 'differential rates of pay', 'adj. 差别的，有区别的；微分的; n. 差别， 差异； 微分', '/ˌdɪfə\'renʃl | \'dɪfə\'rɛnʃəl/', 'differential', 3);
INSERT INTO `words` VALUES (31324, 'A child may not differentiate between his imagination and the real world.', 'v. 区分 ,区别', '/,difə\'renʃieit | ,dɪfə\'renʃɪeɪt | ,dɪfə\'rɛnʃɪet/', 'differentiate', 3);
INSERT INTO `words` VALUES (31325, 'So it appears that banks do an unusually lousy job of differentiating themselves.', 'adj. 微分的', '/,dɪfə\'renʃɪ,eɪtɪŋ | ,dɪfə\'rɛnʃɪ,etɪŋ/', 'differentiating', 3);
INSERT INTO `words` VALUES (31326, NULL, 'adv. 不同地，有差别地', '/\'difərəntli | \'dɪfərəntlɪ | \'dɪfərəntli/', 'differently', 3);
INSERT INTO `words` VALUES (31327, 'If you have any difficulties, give me a call.', 'n. 困难,难点', '/\'difikəlti | \'dɪfɪk(ə)ltɪ | \'dɪfɪkəlti/', 'difficulty', 3);
INSERT INTO `words` VALUES (31328, 'Their ideas diffused quickly across Europe.', 'v. 散播,传播', '/di\'fju:s | dɪ\'fjuːz | dɪ\'fjus/', 'diffuse', 3);
INSERT INTO `words` VALUES (31329, NULL, 'adv. 广泛地,扩散地', '/di\'fju:zli/', 'diffusely', 3);
INSERT INTO `words` VALUES (31330, 'It allows nicotine to diffuse slowly and steadily into the bloodstream.', 'v. 扩散,弥漫', '/di\'fju:s | dɪ\'fjuːz | dɪ\'fjus/', 'diffuses', 3);
INSERT INTO `words` VALUES (31331, 'The invention of printing helped the diffusion of learning.', 'n. 传播，散布', '/di\'fju:ʒən | dɪ\'fjuːʒ(ə)n | dɪ\'fjʊʒən/', 'diffusion', 3);
INSERT INTO `words` VALUES (31332, 'It reacts violently with oxygen difluoride and barium peroxide .', 'n. 二氟化物', NULL, 'difluoride', 3);
INSERT INTO `words` VALUES (31333, 'freshly dug carrots', 'v. 挖', '/diɡ | dɪg | dɪɡ/', 'dig', 3);
INSERT INTO `words` VALUES (31334, 'Most babies can digest a wide range of food easily.', 'v. 消化,融会贯通', '/di\'dʒest, dai-, \'daidʒest | daɪ\'dʒest; dɪ- | daɪ\'dʒɛst/', 'digest', 3);
INSERT INTO `words` VALUES (31335, 'Too much tea is bad for your digestion.', 'n. 消化力, 领悟', '/di:dʒestʃən, dai- | daɪ\'dʒestʃ(ə)n; dɪ- | daɪdʒɛstʃən/', 'digestion', 3);
INSERT INTO `words` VALUES (31336, '...digestive juices that normally work on breaking down our food.', 'adj. 消化的', '/di\'dʒestiv, dai- | daɪ\'dʒestɪv; dɪ- | daɪ\'dʒɛstɪv/', 'digestive', 3);
INSERT INTO `words` VALUES (31337, 'The picture is digitized by a scanner.', 'vt. 数字化', '/\'dɪdʒɪtaɪz/', 'digitize', 3);
INSERT INTO `words` VALUES (31338, 'Tragic literature dignifies sorrow and disaster.', 'vt. 使有尊严， 使高贵； 美化', '/\'dɪgnɪfaɪ | \'dɪɡnɪfaɪ/', 'dignify', 3);
INSERT INTO `words` VALUES (31339, 'an appearance of quiet dignity', 'n. 尊严， 庄严； 高贵， 尊贵； 自尊， 自重', '/\'dɪgnəti | \'dɪɡnəti/', 'dignity', 3);
INSERT INTO `words` VALUES (31340, NULL, 'n. 离题， 扯到枝节上； 题外话， 枝节内容', '/daɪ\'greʃn | daɪ\'grɛʃən/', 'digression', 3);
INSERT INTO `words` VALUES (31341, 'When the river dike is completed, the crops will be safe against floods.', 'n. 堤防; v. 筑堤提防', '/daik | daɪk/', 'dike', 3);
INSERT INTO `words` VALUES (31342, 'dilated pupils', 'v. 膨胀， 扩大； 详述', '/daɪ\'leɪt | daɪˈlet/', 'dilate', 3);
INSERT INTO `words` VALUES (31343, 'a moral dilemma', 'n. 进退两难的局面, 困难的选择', '/di\'lemə, ,dai- | dɪ\'lemə; daɪ- | dɪˈlemə/', 'dilemma', 3);
INSERT INTO `words` VALUES (31344, 'Genius is nothing but labor and diligence.', 'n. 勤奋', '/\'dilidʒəns | \'dɪlɪdʒ(ə)ns | \'dɪlɪdʒəns/', 'diligence', 3);
INSERT INTO `words` VALUES (31345, 'a diligent student', 'adj. 勤奋的， 刻苦的， 勤勉的', '/\'dɪlɪdʒənt/', 'diligent', 3);
INSERT INTO `words` VALUES (31346, 'diluted fruit juice', 'v. 稀释，冲淡', '/dai\'lju:t, di- | daɪ\'l(j)uːt; dɪ- | daɪ\'l(j)ut/', 'dilute', 3);
INSERT INTO `words` VALUES (31347, '\"Aromatherapy oils\" are not pure essential oils but dilutions.', 'n. 稀释', '/dai\'lju:ʃən, di- | daɪ\'luːʃn | dɪ\'ljʊʃən/', 'dilution', 3);
INSERT INTO `words` VALUES (31348, 'The lights in the theatre began to dim.', 'v. (使)暗淡,(使)模糊', '/dim | dɪm/', 'dim', 3);
INSERT INTO `words` VALUES (31349, 'Filling stations have whacked as much as a dime off their regular prices.', 'n. <美> 一角硬币', '/daim | daɪm/', 'dime', 3);
INSERT INTO `words` VALUES (31350, 'a rectangle with the dimensions 5cm × 2cm', 'n. 尺寸, 尺度', '/dɪ\'menʃ(ə)n; daɪ- | dɪ\'mɛnʃ(ə)n; daɪ-/', 'dimension', 3);
INSERT INTO `words` VALUES (31351, 'Of particular note is the deviation threshold parameter and the dimensional shift parameters.', 'adj. 维度的, 空间的, 尺寸的', '/di\'menʃənəl, dai- | daɪ\'mɛnʃənl | dɪ\'menʃənəl/', 'dimensional', 3);
INSERT INTO `words` VALUES (31352, 'The party’s share of the electorate has diminished steadily.', 'v. (使)减少, (使)变小', '/di\'miniʃ | dɪ\'mɪnɪʃ/', 'diminish', 3);
INSERT INTO `words` VALUES (31353, '...despite a slight diminution in asset value.', 'n. 减少， 缩减', '/ˌdɪmɪ\'nuːʃn | /ˌdɪmɪˈnuːʃn//', 'diminution', 3);
INSERT INTO `words` VALUES (31354, 'Ecological sciences were only dimly understood in the late 19th century.', 'adv. 微暗, 朦胧', '/\'dimli | \'dɪmli/', 'dimly', 3);
INSERT INTO `words` VALUES (31355, 'The rough, dimply surfaces of Mentos encourage bubble growth because they efficiently disrupt the polar attractions between water molecules, creating bubble growth sites.', 'adj. 有酒窝的, 有凹处的', '/dimpli/', 'dimply', 3);
INSERT INTO `words` VALUES (31356, NULL, 'n. 吃饭', '/dainiŋ | daɪnɪŋ | \'daɪnɪŋ/', 'dining', 3);
INSERT INTO `words` VALUES (31357, 'What time do you usually have dinner?', 'n. 正餐, 宴会', '/\'dinə | \'dɪnə | \'dɪnɚ/', 'dinner', 3);
INSERT INTO `words` VALUES (31358, 'How then would this dinosaur have moved?', 'n. 恐龙', '/\'dainəsɔ: | \'daɪnəsɔː | \'daɪnə\'sɔr/', 'dinosaur', 3);
INSERT INTO `words` VALUES (31359, 'How much carbon dioxide you save, if any, depends on how far you live from work and how you get there, among other things.', 'n. 二氧化物', '/dai\'ɔksaid | daɪ\'ɒksaɪd | daɪ\'ɑksaɪd/', 'dioxide', 3);
INSERT INTO `words` VALUES (31360, 'French diplomats', 'n. 外交官； 有手腕的人', '/\'dɪpləmæt/', 'diplomat', 3);
INSERT INTO `words` VALUES (31361, 'Diplomatic efforts to end the fighting began on October 25.', 'adj. 外交的， 从事外交的； 有策略的， 有手腕的， 老练的', '/ˌdɪplə\'mætɪk | ,dɪplə\'mætɪk/', 'diplomatic', 3);
INSERT INTO `words` VALUES (31362, 'warnings of dire consequences that often don’t come true', 'adj. 可怕的,极端的', '/\'daiə | \'daɪə/', 'dire', 3);
INSERT INTO `words` VALUES (31363, 'All genuine knowledge originates in direct experience.', 'a&ad. 直接的; v. 对准,指导', '/di\'rekt, dai- | dəˈrekt; daɪˈrekt | dɪˈrɛkt; daɪˈrɛkt/', 'direct', 3);
INSERT INTO `words` VALUES (31364, 'Unless he was equipped with a directional microphone, he was out of earshot.', 'adj. 方向的', '/di\'rekʃənəl, dai- | dɪ\'rekʃ(ə)n(ə)l; daɪ- | də\'rɛkʃənl/', 'directional', 3);
INSERT INTO `words` VALUES (31365, 'Thanks to a new directive, food labelling will be more specific.', 'n. 指示; adj. 指导的', '/di\'rektiv, dai- | dɪ\'rektɪv; daɪ- | daɪ\'rɛktɪv/', 'directive', 3);
INSERT INTO `words` VALUES (31366, '\"Cut!\" the director yelled. \"That was perfect.\"', 'n. 主管,导演', '/di\'rektə | dɪ\'rektə; daɪ- | dɪˈrɛktɚ; daɪˈrɛktɚ/', 'director', 3);
INSERT INTO `words` VALUES (31367, 'I couldn’t find your number in the telephone directory.', 'n. 人名地址录， 电话号码簿； 目录', '/də\'rektəri | dəˈrɛktəri; (also) daɪˈrɛktəri/', 'directory', 3);
INSERT INTO `words` VALUES (31368, 'You should have seen the dirt on that car!', 'n. 污垢, 泥土', '/də:t | dɜːt | dɝt/', 'dirt', 3);
INSERT INTO `words` VALUES (31369, 'Facilities for people with disabilities are still insufficient.', 'n. 无力, 残疾', '/,disə\'biləti | dɪsə\'bɪlɪtɪ | ,dɪsə\'bɪləti/', 'disability', 3);
INSERT INTO `words` VALUES (31370, 'Criminal behaviour can be linked to economic disadvantage.', 'n. 不利,缺点,劣势', '/disəd\'vɑ:ntidʒ | dɪsəd\'vɑːntɪdʒ | ,dɪsəd\'væntɪdʒ/', 'disadvantage', 3);
INSERT INTO `words` VALUES (31371, 'The sale of part of the company could be disadvantageous to investors.', 'adj. 不利的', '/dis,ædvɑ:n\'teidʒəs | ,dɪsædv(ə)n\'teɪdʒəs | ,dɪsædvæn\'tedʒəs/', 'disadvantageous', 3);
INSERT INTO `words` VALUES (31372, '...people\'s disaffection with their country and its leaders.', 'n. 不满', '/,disə\'fekʃən | ,dɪsə\'fɛkʃən/', 'disaffection', 3);
INSERT INTO `words` VALUES (31373, 'The statements of several witnesses disagree.', 'v. 不一致, 不适宜', '/,disə\'ɡri: | dɪsə\'griː | ,dɪsə\'ɡri/', 'disagree', 3);
INSERT INTO `words` VALUES (31374, 'We’ve had a few disagreements , but we’re still good friends.', 'n. 不一致；争论', '/,disə\'ɡri:mənt | dɪsə\'ɡriːmənt | ,dɪsə\'ɡrimənt/', 'disagreement', 3);
INSERT INTO `words` VALUES (31375, 'At this point the path seemed to disappear altogether (= disappear completely ) .', 'v. 消失', '/,disə\'piə | dɪsə\'pɪə | \'dɪsə\'pɪr/', 'disappear', 3);
INSERT INTO `words` VALUES (31376, 'Police are investigating the woman’s disappearance.', 'n. 不见,消失', '/,disə\'piərəns | dɪsə\'pɪərəns | ,dɪsə\'pɪrəns/', 'disappearance', 3);
INSERT INTO `words` VALUES (31377, 'I hated to disappoint her.', 'v. 使失望', '/,disə\'pɔint | dɪsə\'pɒɪnt | \'dɪsə\'pɔɪnt/', 'disappoint', 3);
INSERT INTO `words` VALUES (31378, 'He could see the disappointment in her eyes.', 'n. 失望', '/disə\'pɔintmənt | dɪsə\'pɒɪntm(ə)nt | ,dɪsə\'pɔɪntmənt/', 'disappointment', 3);
INSERT INTO `words` VALUES (31379, 'His action had been greeted with almost universal disapproval.', 'n. 不赞成', '/,disə\'pru:vəl | dɪsə\'pruːvl | \'dɪsə\'prʊvl/', 'disapproval', 3);
INSERT INTO `words` VALUES (31380, 'Getting the rebels to disarm will not be easy.', 'v. 解除武装； 裁军； 消除， 消解', '/dɪs\'ɑːrm | dɪs\'ɑrm/', 'disarm', 3);
INSERT INTO `words` VALUES (31381, 'One hundred and twenty people died in China’s worst air disaster .', 'n. 灾难', '/,di\'zɑ:stə | dɪ\'zɑːstə | dɪ\'zæstɚ/', 'disaster', 3);
INSERT INTO `words` VALUES (31382, 'a disastrous first marriage', 'adj. 灾难性的, 极糟的', '/di\'zɑ:strəs | dɪ\'zɑːstrəs | dɪ\'zæstrəs/', 'disastrous', 3);
INSERT INTO `words` VALUES (31383, 'three keys attached to a metal disc', 'n. 圆盘, 唱片', '/disk | dɪsk/', 'disc', 3);
INSERT INTO `words` VALUES (31384, 'Read the manufacturer\'s guidelines before discarding the box.', 'v. 丢弃, 抛弃', '/dis\'kɑ:d, \'diskɑ:d | dɪ\'skɑːd | dɪsˈkɑːrd/', 'discard', 3);
INSERT INTO `words` VALUES (31385, 'You need a long series of data to be able to discern such a trend.', 'v. 察觉出,识别', '/di\'sə:n, -\'zə:n | dɪ\'sɜːn | dɪ\'sɝn/', 'discern', 3);
INSERT INTO `words` VALUES (31386, 'Far away the outline of the island is just discernible.', 'adj. 可辨别的', '/di\'sə:nəbl, -\'zə:- | dɪ\'sɜːnɪbl | dɪ\'zɝnəbl/', 'discernible', 3);
INSERT INTO `words` VALUES (31387, 'He was given a conditional discharge and ordered to pay Miss Smith $500 compensation.', 'v&n. 释放,排出', '/dis\'tʃɑ:dʒ, \'distʃɑ:dʒ, dis\'tʃ- | dɪs\'tʃɑːdʒ | dɪs\'tʃɑrdʒ/', 'discharge', 3);
INSERT INTO `words` VALUES (31388, '...a major intellectual figure with disciples throughout Europe.', 'n. 信徒, 弟子', '/di\'saipl | dɪ\'saɪp(ə)l | dɪ\'saɪpl/', 'disciple', 3);
INSERT INTO `words` VALUES (31389, 'Martial arts teach respect, discipline, and cooperation.', 'n. 纪律,学科; v. 训练', '/\'disiplin | \'dɪsɪplɪn | \'dɪsəplɪn/', 'discipline', 3);
INSERT INTO `words` VALUES (31390, 'However, that method comes with a disclaimer: Do not use it unless you are sure of the result.', 'n. 放弃, 弃权', '/dis\'kleimə | dɪs\'kleɪmə | dɪs\'klemɚ/', 'disclaimer', 3);
INSERT INTO `words` VALUES (31391, 'Some companies have already voluntarily disclosed similar information .', 'vt. 泄露， 透露； 揭发', '/dɪs\'klouz | dɪs\'kloz/', 'disclose', 3);
INSERT INTO `words` VALUES (31392, 'the school disco', 'n. 迪斯科舞厅', '/diskəu | \'dɪskəʊ | \'dɪsko/', 'disco', 3);
INSERT INTO `words` VALUES (31393, NULL, 'v. 使脱色, (使)变色,(使)退色', '/dis\'kʌlə | dɪs\'kʌlɚ/', 'discolor', 3);
INSERT INTO `words` VALUES (31394, 'Vitamin K is helpful in reducing discoloration and the appearance of capillaries.', 'n. 变色, 污点', '/dis,kʌlə\'reiʃən | ,dɪskʌlə\'reɪʃn | ,dɪs,kʌlə\'reʃən/', 'discoloration', 3);
INSERT INTO `words` VALUES (31395, 'His compliments disconcerted her a little.', 'vt. 使惊慌， 使不安； 使困惑', '/ˌdɪskən\'sɜːrt | \'dɪskən\'sɝt/', 'disconcert', 3);
INSERT INTO `words` VALUES (31396, 'Perhaps she sensed my growing discontent .', 'n. 不满a不满的vt使不满', '/,diskən\'tent | dɪskən\'tent | ,dɪskən\'tɛnt/', 'discontent', 3);
INSERT INTO `words` VALUES (31397, 'discontinuity in economic development', 'n. 不连续, 中断', '/,diskɔn\'tinju:əti | dɪs,kɒntɪ\'njuːɪtɪ | ,dɪs,kɑntə\'nuəti/', 'discontinuity', 3);
INSERT INTO `words` VALUES (31398, 'marital discord', 'n. 不一致； 不和， 纷争； 不和谐', '/\'dɪskɔːrd | \'dɪskɔrd/', 'discord', 3);
INSERT INTO `words` VALUES (31399, 'They are often available at a discount.', 'n. 折扣; vt. 把…打折扣； 不全信， 漠视， 低估', '/\'dɪskaʊnt | dɪs\'kaʊnt/', 'discount', 3);
INSERT INTO `words` VALUES (31400, 'It may be difficult to do at first. Don\'t let this discourage you.', 'v. 使气馁,阻碍', '/dis\'kʌridʒ | dɪs\'kʌrɪdʒ | dɪs\'kɝɪdʒ/', 'discourage', 3);
INSERT INTO `words` VALUES (31401, 'Candidates should engage in serious political discourse.', 'n&v. 谈话, 演讲', '/\'diskɔ:s, dis\'kɔ:s | \'dɪskɔːs; -\'kɔːs | \'dɪskɔrs/', 'discourse', 3);
INSERT INTO `words` VALUES (31402, 'Madame Curie will always be remembered as the discoverer of radium.', 'n. 发现者', '/dis\'kʌvərə/', 'discoverer', 3);
INSERT INTO `words` VALUES (31403, 'I felt I\'d made an incredible discovery.', 'n. 发现,发现物', '/dis\'kʌvəri | dɪ\'skʌv(ə)rɪ | dɪ\'skʌvəri/', 'discovery', 3);
INSERT INTO `words` VALUES (31404, '...a secret unit within the company that had been set up to discredit its major rival.', 'v. 怀疑 n丧失名誉', '/dis\'kredit | dɪs\'kredɪt | dɪs\'krɛdɪt/', 'discredit', 3);
INSERT INTO `words` VALUES (31405, 'The change happens in a series of discrete steps.', 'adj. 不连续的, 离散的', '/dis\'kri:t | dɪ\'skriːt | dɪ\'skrit/', 'discrete', 3);
INSERT INTO `words` VALUES (31406, 'He is incapable of discriminating between a good idea and a terrible one.', 'v. 歧视,区别待遇', '/dɪ\'skrɪmɪneɪt | dɪ\'skrɪmɪnet/', 'discriminate', 3);
INSERT INTO `words` VALUES (31407, 'laws to prevent discrimination', 'n. 歧视；辨别力', '/dis,krimi\'neiʃən | dɪ,skrɪmɪ\'neɪʃ(ə)n | dɪ,skrɪmɪ\'neʃən/', 'discrimination', 3);
INSERT INTO `words` VALUES (31408, 'class discussions', 'n. 讨论', '/dis\'kʌʃən | dɪ\'skʌʃ(ə)n | dɪ\'skʌʃən/', 'discussion', 3);
INSERT INTO `words` VALUES (31409, 'Janet looked at him with disdain.', 'n. 轻蔑 v蔑视', '/dis\'dein | dɪs\'deɪn; -z- | dɪs\'den/', 'disdain', 3);
INSERT INTO `words` VALUES (31410, 'His father died of heart disease.', 'n. 疾病', '/di\'zi:z | dɪ\'ziːz | dɪ\'ziz/', 'disease', 3);
INSERT INTO `words` VALUES (31411, 'There’s no way you can disguise that southern accent.', 'n&v. 伪装，掩饰', '/dis\'ɡaiz | dɪs\'gaɪz | dɪs\'ɡaɪz/', 'disguise', 3);
INSERT INTO `words` VALUES (31412, 'He reached into the bin with a look of disgust on his face.', 'n. 厌恶vi令人厌恶，作呕', '/dis\'ɡʌst | dɪs\'gʌst | dɪs\'ɡʌst/', 'disgust', 3);
INSERT INTO `words` VALUES (31413, 'a serving dish', 'n. 盘, 碟; v. 把…装盘', '/dɪʃ/', 'dish', 3);
INSERT INTO `words` VALUES (31414, NULL, 'vt. 使戒除(或放弃)习惯,使不习惯', '/,dɪshə\'bɪtjʊeɪt/', 'dishabituate', 3);
INSERT INTO `words` VALUES (31415, 'dishonest traders', 'adj. 不诚实的', '/dis\'ɔnist | dɪs\'ɒnɪst | dɪs\'ɑnɪst/', 'dishonest', 3);
INSERT INTO `words` VALUES (31416, 'I hate to disillusion you, but I don’t think she’s coming back.', 'v. 醒悟', '/,disi\'lju:ʒən | ,dɪsɪ\'l(j)uːʒ(ə)n | ,dɪsɪ\'luʒn/', 'disillusion', 3);
INSERT INTO `words` VALUES (31417, 'The plane just disintegrated in mid-air.', 'v. 分裂成小片，瓦解', '/dis\'intiɡreit | dɪs\'ɪntɪgreɪt | dɪs\'ɪntɪɡret/', 'disintegrate', 3);
INSERT INTO `words` VALUES (31418, 'The fact that Liberia has no oil seems to explain foreign disinterest in its internal affairs.', 'n. 无兴趣, 不关心', '/dis\'intrist, -\'intərist | dɪs\'ɪnt(ə)rɪst | dɪs\'ɪntrəst/', 'disinterest', 3);
INSERT INTO `words` VALUES (31419, 'A lawyer should provide disinterested advice.', 'adj. 客观的， 无私的， 公正的； 无兴趣的， 不关心的', '/dɪs\'ɪntrəstɪd | dɪs\'ɪntərɪsɪd/', 'disinterested', 3);
INSERT INTO `words` VALUES (31420, 'The program takes up 2.5 megabytes of disk space and can be run on a standard personal computer.', 'n. 磁盘,圆盘', '/disk | dɪsk/', 'disk', 3);
INSERT INTO `words` VALUES (31421, 'Why do you dislike her so much?', 'v. 讨厌, 不喜欢', '/dis\'laik | dɪs\'laɪk/', 'dislike', 3);
INSERT INTO `words` VALUES (31422, 'the revolution that failed to dislodge the British in 1919', 'v. 驱逐', '/dis\'lɔdʒ | dɪs\'lɒdʒ | dɪs\'lɑdʒ/', 'dislodge', 3);
INSERT INTO `words` VALUES (31423, 'Charges had already been made against certain officials suspected of disloyalty.', 'n. 不忠实', '/dis\'lɔiəlti | dɪs\'lɒɪ(ə)ltɪ/', 'disloyalty', 3);
INSERT INTO `words` VALUES (31424, 'The future looks pretty dismal right now.', 'adj. 阴沉的, 凄凉的n沼泽', '/\'dɪzm(ə)l | \'dɪzməl/', 'dismal', 3);
INSERT INTO `words` VALUES (31425, 'Chris dismantled the bike in five minutes.', 'v. 拆除', '/dis\'mæntl | dɪs\'mænt(ə)l | dɪs\'mæntl/', 'dismantle', 3);
INSERT INTO `words` VALUES (31426, 'The thought of leaving filled him with dismay .', 'n&v. 沮丧, 绝望', '/dis\'mei | dɪs\'meɪ | dɪs\'me/', 'dismay', 3);
INSERT INTO `words` VALUES (31427, 'She then dismembered him, hiding parts of his body in the cellar.', 'v. 肢解,割断手足', '/dis\'membə | dɪs\'membə | dɪs\'mɛmbɚ/', 'dismember', 3);
INSERT INTO `words` VALUES (31428, 'The class was dismissed early today.', 'v. 解散, 下课, 解职,', '/dɪs\'mɪs/', 'dismiss', 3);
INSERT INTO `words` VALUES (31429, 'His whole system was thrown into disorder .', 'n. 混乱 vt扰乱', '/dis\'ɔ:də | dɪs\'ɔːdə | dɪs\'ɔrdɚ/', 'disorder', 3);
INSERT INTO `words` VALUES (31430, NULL, 'v. 使失去方向感, 使迷惑', '/dis\'ɔ:rient | dɪs\'ɔ:rɪent | dɪsˈɔriˌɛnt, -ˈor-/', 'disorient', 3);
INSERT INTO `words` VALUES (31431, 'She was assigned a job to help Jews by talking to them and helping them cope with shock and disorientation at the train station.', 'n. 迷失方向, 迷惑', '/dis,ɔ:rien\'teiʃən/', 'disorientation', 3);
INSERT INTO `words` VALUES (31432, 'a meeting covering many disparate subjects', 'adj. 迥然不同的', '/\'dɪspərət/', 'disparate', 3);
INSERT INTO `words` VALUES (31433, 'Goods are normally dispatched within 24 hours.', 'v. 分派, 派遣', '/dis\'pætʃ | dɪˈspætʃ | dɪ\'spætʃ/', 'dispatch', 3);
INSERT INTO `words` VALUES (31434, 'We want to dispel the myth that you cannot eat well in Britain.', 'vt. 驱散， 驱逐； 消除', '/dɪ\'spel | dɪ\'spɛl/', 'dispel', 3);
INSERT INTO `words` VALUES (31435, 'a machine for dispensing cash', 'v. 分发, 分配', '/dis\'pens | dɪ\'spens | dɪ\'spɛns/', 'dispense', 3);
INSERT INTO `words` VALUES (31436, 'the role of birds in the dispersal of seeds', 'n. 散布,传播,分散', '/dai\'spə:səl | dɪ\'spɜːsl | dɪ\'spɝsl/', 'dispersal', 3);
INSERT INTO `words` VALUES (31437, 'Police used tear gas to disperse the crowd.', 'v. 分散, 疏散', '/dis\'pə:s | dɪ\'spɜːs | dɪ\'spɝs/', 'disperse', 3);
INSERT INTO `words` VALUES (31438, 'Coal has been displaced by natural gas as a major source of energy.', 'v. 转移, 取代', '/dis\'pleis | dɪs\'pleɪs | dɪs\'ples/', 'displace', 3);
INSERT INTO `words` VALUES (31439, '...the displacement of traditional agriculture by industrial crops.', 'n. 移置, 转移, 取代', '/dɪs\'pleɪsm(ə)nt | dɪs\'plesmənt/', 'displacement', 3);
INSERT INTO `words` VALUES (31440, 'a dazzling display (= very good display ) of flowers', 'n&vt. 陈列,展览,显示', '/,dis\'plei | dɪ\'spleɪ | dɪ\'sple/', 'display', 3);
INSERT INTO `words` VALUES (31441, 'bomb disposal experts', 'n. 处理, 处置', '/dis\'pəuzəl | dɪ\'spəʊz(ə)l | dɪ\'spozl/', 'disposal', 3);
INSERT INTO `words` VALUES (31442, 'Chinese vases are disposed around the gallery.', 'v. 处理,布置, 安排', '/dis\'pəuz | dɪ\'spəʊz | dɪ\'spoz/', 'dispose', 3);
INSERT INTO `words` VALUES (31443, 'the disproportionate amount of money being spent on defence', 'adj. 不成比例的', '/disprə\'pɔ:ʃənət | ,dɪsprə\'pɔːʃ(ə)nət/', 'disproportionate', 3);
INSERT INTO `words` VALUES (31444, 'These figures disproved Smith’s argument.', 'v. 反驳,证明为误', '/dis\'pru:v | dɪs\'pruːv | ,dɪs\'pruv/', 'disprove', 3);
INSERT INTO `words` VALUES (31445, 'The facts of the case are still in dispute.', 'n&v. 争论,争端', '/dis\'pju:t, \'dis- | dɪ\'spjuːt; \'dɪspjuːt | \'dɪs\'pjʊt/', 'dispute', 3);
INSERT INTO `words` VALUES (31446, 'The disquiet will boil over in the long run.', 'v. 不安，忧虑; n. 不安， 忧虑', '/dɪs\'kwaɪət/', 'disquiet', 3);
INSERT INTO `words` VALUES (31447, 'He faces six charges of bringing the game into disrepute .', 'n. 坏名声', '/,disri\'pju:t | ,dɪsrɪ\'pjuːt | ,dɪsrɪ\'pjut/', 'disrepute', 3);
INSERT INTO `words` VALUES (31448, 'Traffic was disrupted by a hoax bomb.', 'v. 使中断，扰乱', '/dis\'rʌpt | dɪs\'rʌpt/', 'disrupt', 3);
INSERT INTO `words` VALUES (31449, 'He could draw men round him and keep them bound to him; while his powerful attraction was there, disruption was out of the question.', 'n. 分裂', '/dis\'rʌpʃən | dɪs\'rʌpʃn | dɪs\'rʌpʃən/', 'disruption', 3);
INSERT INTO `words` VALUES (31450, 'Mike’s parents thought I was a disruptive influence (= a person who causes disruption ) .', 'adj. 使破裂的, 分裂性的', '/dis\'rʌptiv | dɪs\'rʌptɪv/', 'disruptive', 3);
INSERT INTO `words` VALUES (31451, 'She has already expressed her dissatisfaction with this aspect of the policy.', 'n. 不满', '/\'dis,sætis\'fækʃən | dɪssætɪs\'fækʃn | dɪs\'sætɪs\'fækʃən/', 'dissatisfaction', 3);
INSERT INTO `words` VALUES (31452, NULL, 'v. 使感觉不满, 不满足', '/,dis\'sætisfai | dɪ(s)\'sætɪsfaɪ | dɪs\'sætɪs,fai/', 'dissatisfy', 3);
INSERT INTO `words` VALUES (31453, 'Her findings have been widely disseminated .', 'v. 散布，传播', '/di\'semineit | dɪ\'semɪneɪt | dɪ\'sɛmɪnet/', 'disseminate', 3);
INSERT INTO `words` VALUES (31454, 'The Labour Party was torn by internal dissensions .', 'n. 意见不同, 纠纷', '/di\'senʃən | dɪ\'senʃ(ə)n | dɪ\'sɛnʃən/', 'dissension', 3);
INSERT INTO `words` VALUES (31455, 'There are some dissenting voices (= people who do not agree ) among the undergraduates.', 'vi. 不同意，持异议; n. 不同意见， 异议', '/dɪ\'sent | dɪ\'sɛnt/', 'dissent', 3);
INSERT INTO `words` VALUES (31456, 'Political dissenters were imprisoned.', 'n. 持异议者', '/di\'sentə | dɪ\'sentə/', 'dissenter', 3);
INSERT INTO `words` VALUES (31457, 'This man was too injured to dissimulate well.', 'v. 掩盖， 掩饰， 假装', '/dɪ\'sɪmjuleɪt | di\'simjuleit/', 'dissimulate', 3);
INSERT INTO `words` VALUES (31458, 'As he thought it over, his anger gradually dissipated.', 'v. 驱散, 消散', '/\'disipeit | \'dɪsɪpeɪt | \'dɪsɪpet/', 'dissipate', 3);
INSERT INTO `words` VALUES (31459, NULL, 'adj. 放荡的， 放纵的， 道德沦丧的', '/\'dɪsəluːt | \'dɪsəlut/', 'dissolute', 3);
INSERT INTO `words` VALUES (31460, 'The president announced the dissolution of the National Assembly.', 'n. 分解, 解散', '/,disə\'lju:ʃən | dɪsə\'luːʃ(ə)n | ,dɪsə\'luʃən/', 'dissolution', 3);
INSERT INTO `words` VALUES (31461, 'Stir until the sugar dissolves.', 'v. 溶解,解散', '/di\'zɔlv | dɪ\'zɒlv | dɪ\'zɑlv/', 'dissolve', 3);
INSERT INTO `words` VALUES (31462, 'Doctors had tried to dissuade patients from smoking.', 'vt. 劝阻， 阻止', '/dɪ\'sweɪd | dɪ\'swed/', 'dissuade', 3);
INSERT INTO `words` VALUES (31463, 'Measure the distance between the two points.', 'n. 距离,路程', '/\'distəns | \'dɪst(ə)ns | \'dɪstəns/', 'distance', 3);
INSERT INTO `words` VALUES (31464, 'the sound of distant gunfire', 'adj. 远的,疏远的', '/\'dɪst(ə)nt | \'dɪstənt/', 'distant', 3);
INSERT INTO `words` VALUES (31465, 'What these pictures demonstrate is that we do feel the pain of others, however distantly.', 'adj. 疏远的, 遥远的', '/\'distəntli/', 'distantly', 3);
INSERT INTO `words` VALUES (31466, 'What follows is John’s story. Parts of it may seem distasteful, even shocking.', 'adj. 味道差的,反感的', '/dis\'teistful | dɪs\'teɪstf(ʊ)l | dɪs\'testfl/', 'distasteful', 3);
INSERT INTO `words` VALUES (31467, 'Blood vessels in the lungs are filled and distend. Capillary changes have been observed in the animal model of simulated microgravity.', 'v. (使)扩大, (使)扩张', '/dis\'tend | dɪ\'stend | dɪ\'stɛnd/', 'distend', 3);
INSERT INTO `words` VALUES (31468, 'distilled water', 'v. 蒸馏, 滴下, 吸取', '/dis\'til | dɪs\'tɪl/', 'distill', 3);
INSERT INTO `words` VALUES (31469, 'two entirely distinct languages', 'adj. 清楚的,明显的,不同的', '/dis\'tiŋkt | dɪ\'stɪŋ(k)t | dɪ\'stɪŋkt/', 'distinct', 3);
INSERT INTO `words` VALUES (31470, 'Eliot’s distinction as a poet', 'n. 差别,区分,优秀', '/dis\'tiŋkʃən | dɪ\'stɪŋ(k)ʃ(ə)n | dɪ\'stɪŋkʃən/', 'distinction', 3);
INSERT INTO `words` VALUES (31471, 'a rock band with a distinctive sound', 'adj. 有区别的,独特的', '/dis\'tiŋktiv | dɪ\'stɪŋ(k)tɪv | dɪ\'stɪŋktɪv/', 'distinctive', 3);
INSERT INTO `words` VALUES (31472, NULL, 'adv. ad/ 区别地, 特殊地', '/dis\'tiŋktivli/', 'distinctively', 3);
INSERT INTO `words` VALUES (31473, 'Speak clearly and distinctly.', 'adv. 清楚地, 显然', '/dis\'tiŋktli | dɪ\'stɪŋ(k)tlɪ | dɪ\'stɪŋktli/', 'distinctly', 3);
INSERT INTO `words` VALUES (31474, 'Could he distinguish right from wrong?', 'v. 区别,辨别', '/dis\'tiŋɡwiʃ | dɪ\'stɪŋgwɪʃ | dɪ\'stɪŋɡwɪʃ/', 'distinguish', 3);
INSERT INTO `words` VALUES (31475, '...features that make their products distinguishable from those of their rivals.', 'adj. 可区别的, 可辨别的', '/dɪ\'stɪŋgwɪʃəbl/', 'distinguishable', 3);
INSERT INTO `words` VALUES (31476, 'Tall buildings can distort radio signals.', 'v. 歪曲, 扭曲,变形', '/dis\'tɔ:t | dɪ\'stɔːt | dɪ\'stɔrt/', 'distort', 3);
INSERT INTO `words` VALUES (31477, 'I think it would be a gross distortion of reality to say that they were motivated by self-interest.', 'n. 扭曲, 变形,曲解', '/dis\'tɔ:ʃən | dɪ\'stɔːʃ(ə)n | dɪs\'tɔrʃən/', 'distortion', 3);
INSERT INTO `words` VALUES (31478, 'Try not to distract the other students.', 'v. 转移,分散', '/dis\'trækt | dɪ\'strækt/', 'distract', 3);
INSERT INTO `words` VALUES (31479, 'Luke’s behaviour caused his parents great distress.', 'n. 痛苦，忧伤；贫困，窘迫；遇难; vt. 使痛苦， 使悲伤， 使忧虑', '/dɪ\'stres | dɪ\'strɛs/', 'distress', 3);
