INSERT INTO `words` VALUES (31927, 'Fashion is by nature ephemeral.', 'adj. 朝生暮死的, 短暂的', '/i\'femərəl | ɪ\'fem(ə)r(ə)l; -\'fiːm- | ə\'fɛmərəl/', 'ephemeral', 3);
INSERT INTO `words` VALUES (31928, 'a Hollywood epic', 'n. 史诗, 伟大事迹', '/\'epik | \'epɪk | \'ɛpɪk/', 'epic', 3);
INSERT INTO `words` VALUES (31929, 'Over 500 people died during last year’s flu epidemic.', 'adj. 流行性的， 传染性的; n. 流行；流行病', '/ˌepɪ\'demɪk | ,ɛpɪ\'dɛmɪk/', 'epidemic', 3);
INSERT INTO `words` VALUES (31930, 'The pigment in the upper layer of skin (epidermis) that gives your skin its normal color is called melanin.', 'n. [生]表皮, 上皮', '/,epi\'də:mis | ,epɪ\'dɜːmɪs | ,ɛpɪ\'dɝmɪs/', 'epidermis', 3);
INSERT INTO `words` VALUES (31931, 'She decided she would try to forget the episode by the lake.', 'n. 一段情节', '/\'episəud | \'epɪsəʊd | \'ɛpɪsod/', 'episode', 3);
INSERT INTO `words` VALUES (31932, '...episodic attacks of fever.', 'adj. 插曲式的,短暂的', '/,epɪ\'sɒdɪk | ,ɛpɪ\'sɑdɪk/', 'episodic', 3);
INSERT INTO `words` VALUES (31933, 'Now immediately we can see that this is an epistle which has a great deal to teach us as we live in the last times of the Gentiles.', 'n. 书信', '/i\'pisl | ɪ\'pɪs(ə)l | ɪ\'pɪsl/', 'epistle', 3);
INSERT INTO `words` VALUES (31934, 'But it is impossible to predict the reaction of a man accosted by another with the words \"you rat\" without referring to the meaning that the man spoken to attaches to the epithet.', 'n. 绰号, 称号', '/\'epiθet | \'epɪθet | \'ɛpɪθɛt/', 'epithet', 3);
INSERT INTO `words` VALUES (31935, 'Maureen was the epitome of sophistication.', 'n. 摘要', '/i\'pitəmi | ɪ\'pɪtəmɪ; e- | ɪ\'pɪtəmi/', 'epitome', 3);
INSERT INTO `words` VALUES (31936, 'This building epitomizes the spirit of the nineteenth century.', 'vt. 成为…的缩影； 摘要， 概括， 缩写', '/ɪ\'pɪtəmaɪz/', 'epitomize', 3);
INSERT INTO `words` VALUES (31937, 'the Victorian epoch', 'n. 新纪元, 时代', '/\'i:pɔk, \'epək | \'iːpɒk; \'epɒk | \'ɛpək/', 'epoch', 3);
INSERT INTO `words` VALUES (31938, 'Two plus two equals four.', 'adj. 同样的; v. 等于', '/\'i:kwəl | \'ikwəl/', 'equal', 3);
INSERT INTO `words` VALUES (31939, '...equality of the sexes.', 'n. 等同性, 平等', '/i:\'kwɔləti | ɪ\'kwɒlɪtɪ; iː- | ɪ\'kwɑləti/', 'equality', 3);
INSERT INTO `words` VALUES (31940, 'In the equation 2x + 1 = 7, what is x?', 'n. 等式， 方程式； 等同， 相等； 均衡', '/ɪ\'kweɪʒn | ɪ\'kweʒn/', 'equation', 3);
INSERT INTO `words` VALUES (31941, 'The United States is north of the equator.', 'n. 赤道', '/i\'kweitə | ɪ\'kweɪtə | ɪ\'kwetɚ/', 'equator', 3);
INSERT INTO `words` VALUES (31942, 'equatorial rain forests', 'adj. (近)赤道的', '/,ekwə\'tɔ:riəl | ,ekwə\'tɔːrɪəl | ,ɛkwə\'tɔrɪəl/', 'equatorial', 3);
INSERT INTO `words` VALUES (31943, 'equestrian sports', 'adj. 骑马的 n骑手', '/i\'kwestriən | ɪ\'kwestrɪən; e- | ɪ\'kwɛstrɪən/', 'equestrian', 3);
INSERT INTO `words` VALUES (31944, '...an equilateral triangle.', 'adj. 等边的 n等边形', '/,i:kwi\'lætərəl | ,iːkwɪ\'læt(ə)r(ə)l; ,ekwɪ- | \'ikwə\'lætərəl/', 'equilateral', 3);
INSERT INTO `words` VALUES (31945, 'The government is anxious not to upset the economic equilibrium.', 'n. 平衡', '/,i:kwi\'libriəm | ,iːkwɪ\'lɪbrɪəm; ,ekwɪ- | ,ikwɪ\'lɪbrɪəm/', 'equilibrium', 3);
INSERT INTO `words` VALUES (31946, 'They try to equip their vehicles with gadgets to deal with every possible contingency.', 'v. 装备, 配备', '/i\'kwip | ɪ\'kwɪp/', 'equip', 3);
INSERT INTO `words` VALUES (31947, 'a shop selling camping equipment', 'n. 装备,设备', '/i\'kwipmənt | ɪ\'kwɪpm(ə)nt | ɪ\'kwɪpmənt/', 'equipment', 3);
INSERT INTO `words` VALUES (31948, 'an equitable distribution of food supplies', 'adj. 公平的, 公正的', '/\'ekwitəbl | \'ekwɪtəb(ə)l/', 'equitable', 3);
INSERT INTO `words` VALUES (31949, 'I had no dollars, but offered him an equivalent amount of sterling.', 'adj. 相等的,相当的n等价物', '/i\'kwivələnt | ɪ\'kwɪv(ə)l(ə)nt | ɪ\'kwɪvələnt/', 'equivalent', 3);
INSERT INTO `words` VALUES (31950, 'His death marked the end of an era.', 'n. 时代,纪元', '/\'iərə, \'εərə | \'ɪərə | \'ɪrə/', 'era', 3);
INSERT INTO `words` VALUES (31951, 'an attempt to eradicate inflation', 'v. 根除', '/i\'rædikeit | ɪ\'rædɪkeɪt | ɪ\'rædɪket/', 'eradicate', 3);
INSERT INTO `words` VALUES (31952, NULL, 'n. 连根拔除, 根除', '/i,rædi\'keiʃən | ɪ,rædɪ\'keɪʃ(ə)n | ɪ,rædɪ\'keʃən/', 'eradication', 3);
INSERT INTO `words` VALUES (31953, 'Yet this we ask ere you leave us, that you speak to us and give us of your truth.', 'pron&conj. 在…之前', '/eə | ɛr/', 'ere', 3);
INSERT INTO `words` VALUES (31954, 'an imposing town hall, erected in 1892', 'v. 建造,竖立,使直立', '/i\'rekt | ɪ\'rekt | ɪ\'rɛkt/', 'erect', 3);
INSERT INTO `words` VALUES (31955, 'Her team is also interested in asking similar questions about human ancestors from East Africa, as well as later species of hominin, such as Homo erectus.', 'adj. [拉丁语]直立的', NULL, 'erectus', 3);
INSERT INTO `words` VALUES (31956, 'They drove north back home, where he would start chemotherapy at a cancer center in Erie.', 'n. 伊利(人)', '/\'iəri/', 'Erie', 3);
INSERT INTO `words` VALUES (31957, 'The cliffs are being constantly eroded by heavy seas.', 'v. 侵蚀,腐蚀', '/i\'rəud | ɪ\'rəʊd | ɪ\'rod/', 'erode', 3);
INSERT INTO `words` VALUES (31958, 'the problem of soil erosion', 'n. 腐蚀,侵蚀', '/i\'rəuʒən | ɪ\'rəʊʒ(ə)n | ɪ\'roʒən/', 'erosion', 3);
INSERT INTO `words` VALUES (31959, 'I seemed to spend my life running errands for people.', 'n. 差事， 差使', '/\'erənd | \'ɛrənd/', 'errand', 3);
INSERT INTO `words` VALUES (31960, 'His breathing was becoming erratic.', 'adj. 古怪的，飘忽不定的', '/i\'rætik | ɪ\'rætɪk/', 'erratic', 3);
INSERT INTO `words` VALUES (31961, 'an error message', 'n. 错误, 过失', '/\'erə | \'ɛrɚ/', 'error', 3);
INSERT INTO `words` VALUES (31962, 'Violence erupted after police shot a student during the demonstration.', 'v. 喷出 vi爆发', '/i\'rʌpt | ɪ\'rʌpt/', 'erupt', 3);
INSERT INTO `words` VALUES (31963, 'The last eruption of this volcano lasted over a year, so this cannot be ruled out.', 'n. 爆发,火山灰', '/i\'rʌpʃən | ɪ\'rʌpʃ(ə)n | ɪ\'rʌpʃən/', 'eruption', 3);
INSERT INTO `words` VALUES (31964, 'Take the escalator to the third floor and it\'s the last office on the left.', 'n. 电动扶梯', '/\'eskəleitə | \'eskəleɪtə | \'ɛskə\'letɚ/', 'escalator', 3);
INSERT INTO `words` VALUES (31965, 'He broke down the locked door and escaped.', 'v. 逃跑,逃脱', '/ɪ\'skeɪp; e- | ɪˈskep/', 'escape', 3);
INSERT INTO `words` VALUES (31966, 'I had eschewed politics in favour of a life practising law.', 'vt. 避开， 戒除， 回避', '/ɪs\'tʃuː | ɪsˈtʃuː/', 'eschew', 3);
INSERT INTO `words` VALUES (31967, NULL, 'n. 有花纹的盾, 锁眼盖, 孔罩', '/i\'skʌtʃən | ɪ\'skʌtʃ(ə)n; e- | ɪ\'skʌtʃən/', 'escutcheon', 3);
INSERT INTO `words` VALUES (31968, '...esoteric knowledge.', 'adj. 秘传的, 神秘的, 难懂的', '/,esəu\'terik | ,esə\'terɪk; ,iːsə- | ,ɛsə\'tɛrɪk/', 'esoteric', 3);
INSERT INTO `words` VALUES (31969, 'I never liked long walks, especially in winter.', 'adv. 特别,尤其', '/i\'speʃəli | ɪ\'speʃ(ə)lɪ; e- | ɪ\'spɛʃəli/', 'especially', 3);
INSERT INTO `words` VALUES (31970, 'She ran away with him to Mexico and espoused the revolutionary cause.', 'vt. 支持， 拥护， 赞成', '/ɪ\'spauz | ɪ\'spaʊz/', 'espouse', 3);
INSERT INTO `words` VALUES (31971, 'We asked Jason to write an essay about his hometown.', 'n. 散文', '/\'esei, e\'sei | \'eseɪ | \'ɛse/', 'essay', 3);
INSERT INTO `words` VALUES (31972, 'In essence his message was very simple.', 'n. 本质，实质', '/\'esəns | \'es(ə)ns | \'ɛsns/', 'essence', 3);
INSERT INTO `words` VALUES (31973, 'Window locks are fairly cheap and absolutely essential.', 'adj. 基本的，本质的；极其重要的，必不可少的; n. 要素， 实质； 必需品', '/ɪ\'senʃl | ɪ\'sɛnʃl/', 'essential', 3);
INSERT INTO `words` VALUES (31974, 'The city of Boerne was established by German settlers in the 1840s.', 'v. 建立,确立,创办', '/i\'stæbliʃ | ɪ\'stæblɪʃ; e- | ɪˈstæblɪʃ/', 'establish', 3);
INSERT INTO `words` VALUES (31975, NULL, 'n. 确立,制定', '/i\'stæbliʃmənt | ɪ\'stæblɪʃm(ə)nt; e- | ɪ\'stæblɪʃmənt/', 'establishment', 3);
INSERT INTO `words` VALUES (31976, 'His estate was valued at $150,000.', 'n. 财产, 地产', '/ɪ\'steɪt; e- | ɪ\'stet/', 'estate', 3);
INSERT INTO `words` VALUES (31977, 'He is held in high esteem by colleagues in the construction industry.', 'n. ／ vt尊重，敬重', '/i\'sti:m | ɪ\'stiːm; e- | ɪ\'stim/', 'esteem', 3);
INSERT INTO `words` VALUES (31978, 'We just need an estimate of the number of people who will come.', 'n&v. 估计,估价', '/\'estimeit | \'estɪmeɪt | \'ɛstə,met/', 'estimate', 3);
INSERT INTO `words` VALUES (31979, 'estuarine muds', 'adj. 入海的, 在入海口形成的', '/\'estjuərain, -rin | \'estjʊəraɪn | \'ɛstjʊərɪn/', 'estuarine', 3);
INSERT INTO `words` VALUES (31980, 'the Thames estuary', 'n. 河口, 江口', '/\'estjuəri | \'estjʊ(ə)rɪ | \'ɛstʃʊ\'ɛri/', 'estuary', 3);
INSERT INTO `words` VALUES (31981, 'A laser is used to etch a pattern in the smooth surface of the disc.', 'v. 蚀刻', '/etʃ | ɛtʃ/', 'etch', 3);
INSERT INTO `words` VALUES (31982, 'Mary is very keen on etching.', 'n. 蚀刻版画', '/\'etʃiŋ | \'etʃɪŋ | \'ɛtʃɪŋ/', 'etching', 3);
INSERT INTO `words` VALUES (31983, 'the Christian promise of eternal life', 'adj. 永恒的,永远的', '/i\'tə:nəl | ɪ\'tɜːn(ə)l; iː- | ɪ\'tɝnl/', 'eternal', 3);
INSERT INTO `words` VALUES (31984, '...a sweetish smell of ether and iodine.', 'n. 天空醚, 大气', '/\'i:θə | \'iːθə | \'iθɚ/', 'ether', 3);
INSERT INTO `words` VALUES (31985, 'The old ethic of hard work has given way to a new ethic of instant gratification.', 'n. 道德规范', '/\'eθik | \'eθɪk | \'ɛθɪk/', 'ethic', 3);
INSERT INTO `words` VALUES (31986, 'I don’t think it’s ethical for you to accept a job you know you can’t do.', 'adj. 道德的', '/\'eθɪkl | \'ɛθɪkl/', 'ethical', 3);
INSERT INTO `words` VALUES (31987, 'What is technically possible and what is ethically appropriate is a matter of heated debate.', 'adv. 伦理(学)上', '/\'eθikli | \'ɛθɪkli/', 'ethically', 3);
INSERT INTO `words` VALUES (31988, 'The school teaches pupils from different ethnic groups.', 'adj. 人种的, 种族的', '/\'eθnik | \'eθnɪk | \'ɛθnɪk/', 'ethnic', 3);
INSERT INTO `words` VALUES (31989, 'Near Amsterdam there is an ethnographic museum where one can trace the history of klomps development, to see the fully automated production process of this unique wooden shoes.', 'adj. 民族志学的, 人种志学的', '/,eθnə\'ɡræfik | ,eθnə\'ɡræfɪk/', 'ethnographic', 3);
INSERT INTO `words` VALUES (31990, 'The pattern of the Reindeer Industry in West Siberian of Russia is an important issue for ethnology.', 'n. 民族学， 文化人类学', '/eθ\'nɑːlədʒi/', 'ethnology', 3);
INSERT INTO `words` VALUES (31991, 'At Agile 2006, she examined the cooperative behavior of Bonobo apes from an ethological perspective and spoke about how “natural” the cooperative aspects of Agile are.', 'n. 行为性的, 行为学的', '/,i:θə\'lɔdʒikəl/', 'ethological', 3);
INSERT INTO `words` VALUES (31992, 'On the next page, we\'ll delve into the world of ethology .', 'n. 动物行动学, 人种学', '/i\'θɔlədʒi | iː\'θɒlədʒɪ/', 'ethology', 3);
INSERT INTO `words` VALUES (31993, 'strict rules of professional etiquette', 'n. 礼节， 礼仪', '/\'etɪket | \'ɛtɪkɛt/', 'etiquette', 3);
INSERT INTO `words` VALUES (31994, 'Scientists now know that this common ancestor, \'the first eukaryote\', was a lot more sophisticated than any known bacterium.', 'n. 〈生〉真核细胞', '/ju:\'kæriəut | juː\'kærɪəʊt | jʊ\'kæriot; jʊ\'kæriət/', 'eukaryote', 3);
INSERT INTO `words` VALUES (31995, 'These genes are needed for cell respiration, and without them eukaryotic cells die.', 'adj. 真核状态的', '/ju:,kæri\'ɔtik | juː,kærɪ\'ɒtɪk/', 'eukaryotic', 3);
INSERT INTO `words` VALUES (31996, 'These grew up in the world\'s great fertile river valleys, the Euphrates, the Tigris and the Indus, but I want to start with the most famous river of them all, the Nile.', 'n. 幼发拉底河', '/ju:\'freiti:z/', 'Euphrates', 3);
INSERT INTO `words` VALUES (31997, 'The lake is the largest spawning ground for red salmon in Eurasia and the best place for bears.', 'n. 欧亚大陆', '/juə\'reiʃə/', 'Eurasia', 3);
INSERT INTO `words` VALUES (31998, '...the whole of the Eurasian continent.', 'adj. 欧亚的, 欧亚人的', '/juə\'reiʃən/', 'Eurasian', 3);
INSERT INTO `words` VALUES (31999, 'eastern Europe', 'n. 欧洲', '/\'juərəp | \'jʊrəp/', 'Europe', 3);
INSERT INTO `words` VALUES (32000, 'European languages', 'adj. 欧洲的; n. 欧洲人', '/,juərə\'pi:ən | jʊərə\'piːən | \'jʊrə\'piən/', 'European', 3);
INSERT INTO `words` VALUES (32001, 'Some insects, such as ants and bees, live in \"eusocial\" groups, in which different members carry out specialized jobs to help maintain the colony.', 'adj. (昆虫)完全社会性的', '/ju:\'səuʃəl/', 'eusocial', 3);
INSERT INTO `words` VALUES (32002, 'Police evacuated the area.', 'v. 疏散， 撤离； 排空', '/ɪ\'vækjueɪt | ɪ\'vækjuet/', 'evacuate', 3);
INSERT INTO `words` VALUES (32003, 'I ordered the evacuation of all Americans and sent troops to guarantee their safety.', 'n. 撤离', '/ɪˌvækju\'eɪʃn | ɪ,vækjʊ\'eʃən/', 'evacuation', 3);
INSERT INTO `words` VALUES (32004, 'I could tell that he was trying to evade the issue.', 'v. 逃避， 回避； 躲开， 避开', '/ɪ\'veɪd | ɪ\'ved/', 'evade', 3);
INSERT INTO `words` VALUES (32005, 'You should be able to evaluate your own work.', 'v. 评价, 估计', '/i\'væljueit | ɪ\'væljʊeɪt | ɪ\'væljʊ\'et/', 'evaluate', 3);
INSERT INTO `words` VALUES (32006, 'We need to carry out a proper evaluation of the new system.', 'n. 估价, 评价', '/i,vælju\'eiʃən | ɪˌvæljuˈeɪʃn | ɪ,væljʊ\'eʃən/', 'evaluation', 3);
INSERT INTO `words` VALUES (32007, '...the evanescent scents of summer herbs.', 'adj. 迅速消失的, 短暂的', '/,i:və\'nesənt | iːvə\'nes(ə)nt; ev- | ,ɛvə\'nɛsnt/', 'evanescent', 3);
INSERT INTO `words` VALUES (32008, 'Most of the water had evaporated.', 'v. (使)蒸发,消失', '/i\'væpəreit | ɪ\'væpəreɪt | ɪ\'væpəret/', 'evaporate', 3);
INSERT INTO `words` VALUES (32009, 'Water enters air via evaporation.', 'n. 蒸发', '/i,væpə\'reiʃən | ɪ,væpə\'reɪʃən | ɪ,væpə\'reʃən/', 'evaporation', 3);
INSERT INTO `words` VALUES (32010, 'Most companies have suffered a drop in their profits, even very large companies.', 'adv. 甚至，连；甚至可以说; adj. 平滑的，平坦的；平稳的，均匀的；均衡的；平均的；偶数的; v. 平坦； 相等', '/\'iːvn | \'ivən/', 'even', 3);
INSERT INTO `words` VALUES (32011, 'I do most of my studying in the evening.', 'n. 傍晚, 晚间', '/\'i:vniŋ | \'iːv(ə)nɪŋ | \'ivnɪŋ/', 'evening', 3);
INSERT INTO `words` VALUES (32012, NULL, 'n. 平均, 平等, 平坦', '/\'i:vənnis/', 'evenness', 3);
INSERT INTO `words` VALUES (32013, 'Sweden were the eventual winners of the tournament.', 'adj. 最后的, 结局的', '/i\'ventʃuəl | ɪ\'ven(t)ʃʊəl/', 'eventual', 3);
INSERT INTO `words` VALUES (32014, 'He eventually escaped and made his way back to England.', 'adv. 最后,终于', '/i\'ventʃuəli | ɪ\'ventʃʊəlɪ | ɪ\'vɛntʃuəli/', 'eventually', 3);
INSERT INTO `words` VALUES (32015, 'Nothing lasts for ever.', 'adv. 曾经,永远', '/\'evə | \'ɛvɚ/', 'ever', 3);
INSERT INTO `words` VALUES (32016, NULL, 'n. 珠穆朗玛峰(世界最高峰)', '/\'evərist | \'evərɪst | ˈɛvərɪst/', 'everest', 3);
INSERT INTO `words` VALUES (32017, 'Holly, like ivy and mistletoe, is an evergreen.', 'n. 常绿树; adj. 常绿的', '/\'evəɡri:n | \'evəgriːn | \'ɛvɚɡrin/', 'evergreen', 3);
INSERT INTO `words` VALUES (32018, 'everlasting fame', 'adj. 永恒的, 持久的', '/,eveə\'lɑ:stiŋ | evə\'lɑːstɪŋ | ,ɛvɚ\'læstɪŋ/', 'everlasting', 3);
INSERT INTO `words` VALUES (32019, 'His every utterance will be scrutinized.', 'adj. 每个,一切的,每隔', '/\'evri | \'evrɪ | \'ɛvri/', 'every', 3);
INSERT INTO `words` VALUES (32020, 'the problems of everyday life', 'adj. 每天的，日常的', '/\'evridei | \'evrɪdeɪ; -\'deɪ | \'ɛvrɪde/', 'everyday', 3);
INSERT INTO `words` VALUES (32021, 'If everyone is ready, I’ll begin.', 'pron. 每个人', '/\'evrɪwʌn | \'ɛvrɪwʌn/', 'everyone', 3);
INSERT INTO `words` VALUES (32022, 'Everything was covered in a thick layer of dust.', 'pron. 每件事物', '/\'evrɪθɪŋ | \'ɛvrɪ\'θɪŋ/', 'everything', 3);
INSERT INTO `words` VALUES (32023, 'I’ve looked everywhere but I can’t find the map.', 'adv. 到处, 无论何处', '/\'evrihwεə | \'evrɪweə | \'ɛvrɪwɛr/', 'everywhere', 3);
INSERT INTO `words` VALUES (32024, 'The volcano is still active, as evidenced by the recent eruption.', 'vt. 证明; n. 证据； 迹象； 根据', '/\'evɪdəns | \'ɛvɪdəns/', 'evidence', 3);
INSERT INTO `words` VALUES (32025, 'Bob ate his lunch with evident enjoyment.', 'adj. 明显的, 显然的', '/\'evidənt | \'evɪd(ə)nt | \'ɛvɪdənt/', 'evident', 3);
INSERT INTO `words` VALUES (32026, 'She was evidently a heavy smoker.', 'adv. 显然,清楚地', '/\'evidəntli | \'evɪd(ə)ntlɪ | \'ɛvɪdəntli/', 'evidently', 3);
INSERT INTO `words` VALUES (32027, '...strangling and eviscerating rabbits for the pot.', 'v. 取出内脏, 除去精华', '/i\'visəreit | ɪ\'vɪsəreɪt | ɪ\'vɪsəret/', 'eviscerate', 3);
INSERT INTO `words` VALUES (32028, 'The photographs evoked strong memories of our holidays in France.', 'v. 唤起, 引起', '/i\'vəuk | ɪ\'vəʊk | ɪ\'vok/', 'evoke', 3);
INSERT INTO `words` VALUES (32029, 'the theory of evolution', 'n. 进化,发展,演变', '/,i:və\'lu:ʃən, ,ev- | ,iːvə\'luːʃ(ə)n; \'ev- | ˌɛvəˈluʃən; (occas.) ˌ ivəˈluʃən/', 'evolution', 3);
INSERT INTO `words` VALUES (32030, 'the evolutionary development of birds', 'adj. 进化的,发展的,演变的', '/,i:və\'lu:ʃənəri | ,iːvə\'luːʃənərɪ | ,ivə\'luʃənɛri/', 'evolutionary', 3);
INSERT INTO `words` VALUES (32031, 'Animals have evolved camouflage to protect themselves from predators.', 'v. 演变,进化,发展', '/i\'vɔlv | ɪ\'vɒlv | ɪ\'vɑlv/', 'evolve', 3);
INSERT INTO `words` VALUES (32032, 'Police are still investigating the exact cause of the accident.', 'adj. 精确的,准确的', '/ɪg\'zækt; eg- | ɪɡ\'zækt/', 'exact', 3);
INSERT INTO `words` VALUES (32033, 'I couldn’t sleep for three days – I’m not exaggerating.', 'v. 夸大,夸张', '/iɡ\'zædʒəreit | ɪg\'zædʒəreɪt; eg- | ɪɡ\'zædʒəret/', 'exaggerate', 3);
INSERT INTO `words` VALUES (32034, 'It would be an exaggeration to say that we were close friends.', 'n. 夸张', '/iɡ,zædʒə\'reiʃən | ɪg,zædʒə\'reɪʃ(ə)n | ɪɡ,zædʒə\'reʃən/', 'exaggeration', 3);
INSERT INTO `words` VALUES (32035, 'But it can also inspire and uplift and exalt, because power can be used to help people accomplish marvelous things.', 'v. 晋升', '/iɡ\'zɔ:lt | ɪg\'zɔːlt; eg- | ɪɡ\'zɔlt/', 'exalt', 3);
INSERT INTO `words` VALUES (32036, 'I felt shy in such exalted company.', 'adj. 崇高的， 高贵的， 显赫的', '/ɪg\'zɔːltɪd | ɪg\'zɔltɪd/', 'exalted', 3);
INSERT INTO `words` VALUES (32037, 'At the end of each level, there’s an exam.', 'n. 考试, 测验', '/iɡ\'zæm | ɪg\'zæm; eg- | ɪg\'zæm/', 'exam', 3);
INSERT INTO `words` VALUES (32038, 'The examination results will be announced in September.', 'n. 考试, 检查, 细查', '/iɡ,zæmi\'neiʃən | ɪg,zæmɪ\'neɪʃ(ə)n; eg- | ɪg\'zæmə\'neʃən/', 'examination', 3);
INSERT INTO `words` VALUES (32039, 'A team of divers was sent down to examine the wreck.', 'v. 检查,调查,考试', '/iɡ\'zæmin | ɪg\'zæmɪn; eg- | ɪg\'zæmɪn/', 'examine', 3);
INSERT INTO `words` VALUES (32040, 'Schliemann excavated the ancient city of Troy.', 'v. 挖掘,开凿', '/\'ekskə,veit | \'ekskəveɪt | \'ɛkskə\'vet/', 'excavate', 3);
INSERT INTO `words` VALUES (32041, 'A second excavation, in 1985, lasted a year and was cut short for technical reasons.', 'n. 挖掘, 发掘', '/,ekskə\'veiʃən | ekskə\'veɪʃ(ə)n | ,ɛkskə\'veʃən/', 'excavation', 3);
INSERT INTO `words` VALUES (32042, 'Working hours must not exceed 42 hours a week.', 'v. 超越, 胜过', '/ik\'si:d | ɪk\'siːd; ek- | ɪk\'sid/', 'exceed', 3);
INSERT INTO `words` VALUES (32043, 'Thank you. You’ve been exceedingly kind.', 'adv. 非常,极度地', '/ik\'si:diŋli | ɪk\'siːdɪŋlɪ; ek- | ɪk\'sidɪŋli/', 'exceedingly', 3);
INSERT INTO `words` VALUES (32044, 'You have excelled yourself with the new exhibition.', 'v. 优秀, 胜过他人', '/ik\'sel | ɪk\'sel; ek- | ɪk\'sɛl/', 'excel', 3);
INSERT INTO `words` VALUES (32045, 'centres of academic excellence', 'n. 优秀, 卓越', '/\'eksələns | \'eks(ə)l(ə)ns | \'ɛksləns/', 'excellence', 3);
INSERT INTO `words` VALUES (32046, 'an excellent suggestion', 'adj. 卓越的, 极好的', '/\'eksələnt | \'eks(ə)l(ə)nt | \'ɛksələnt/', 'excellent', 3);
INSERT INTO `words` VALUES (32047, 'It’s been cold, but today’s an exception.', 'n. 除外,例外', '/ik\'sepʃən | ɪk\'sepʃ(ə)n; ek- | ɪk\'sɛpʃən/', 'exception', 3);
INSERT INTO `words` VALUES (32048, NULL, 'adv. 格外地, 特别地', '/ik\'sepʃənəli | ɪk\'sepʃ(ə)nəlɪ | ɪk\'sɛpʃənəli/', 'exceptionally', 3);
INSERT INTO `words` VALUES (32049, 'After you apply the oil, wait 20 minutes before wiping off any excess.', 'n&a. 过量(的)', '/ik\'ses, \'ek-, \'ekses, ik\'s- | ɪk\'ses; ek-; \'ekses | \'ɛk\'sɛs/', 'excess', 3);
INSERT INTO `words` VALUES (32050, 'his excessive drinking', 'adj. 过多的,过分的', '/ik\'sesiv | ɪk\'sesɪv; ek- | ɪkˈsɛsɪv/', 'excessive', 3);
INSERT INTO `words` VALUES (32051, NULL, 'adv. 过分地, 过度地, 极度地', '/ik\'sesivli | ek\'sesɪvlɪ | ɪk\'sɛsɪvli/', 'excessively', 3);
INSERT INTO `words` VALUES (32052, 'Four of my cassettes for your Madonna CD is a fair exchange.', 'v&n. 交换,兑换', '/iks\'tʃeindʒ | ɪks\'tʃeɪndʒ; eks- | ɪks\'tʃendʒ/', 'exchange', 3);
INSERT INTO `words` VALUES (32053, 'The Zurich laboratory has already constructed a prototype that feeds the water from the chips into a heat-exchanger.', 'n. 交换器, 换热器', '/iks\'tʃeindʒə/', 'exchanger', 3);
INSERT INTO `words` VALUES (32054, 'The tumour was excised.', 'vt. 切除； 删去', '/\'eksaɪz | ɛk\'saɪz/', 'excise', 3);
INSERT INTO `words` VALUES (32055, NULL, 'n. 刺激,兴奋, 激动', '/,eksi\'teiʃən | ,eksaɪ\'teɪʃ(ə)n | ,ɛksaɪ\'teʃən/', 'excitation', 3);
INSERT INTO `words` VALUES (32056, 'His playing is technically brilliant, but it doesn’t excite me.', 'v. 使兴奋,激动', '/ik\'sait | ɪk\'saɪt; ek- | ɪk\'saɪt/', 'excite', 3);
INSERT INTO `words` VALUES (32057, 'We were both new to the excitements of life in the big city.', 'n. 刺激, 兴奋', '/ik\'saitmənt | ɪk\'saɪtmənt/', 'excitement', 3);
INSERT INTO `words` VALUES (32058, '‘No!’ she exclaimed in shock.', 'v. 呼喊, 惊叫', '/ik\'skleim | ɪk\'skleɪm; ek- | ɪk\'sklem/', 'exclaim', 3);
INSERT INTO `words` VALUES (32059, 'a special diet that excludes dairy products', 'v. 把排除在外, 排斥', '/iks\'klu:d | ɪk\'skluːd; ek- | ɪk\'sklʊd/', 'exclude', 3);
INSERT INTO `words` VALUES (32060, '...women\'s exclusion from political power.', 'n. 排除, 除外', '/ik\'sklu:ʒən | ɪk\'skluːʒ(ə)n; ek- | ɪk\'skluʒn/', 'exclusion', 3);
INSERT INTO `words` VALUES (32061, 'a racially exclusive hiring policy', 'adj. 排外的,独占的,唯一的', '/ik\'sklu:siv | ɪk\'skluːsɪv; ek- | ɪk\'sklusɪv/', 'exclusive', 3);
INSERT INTO `words` VALUES (32062, '...an exclusively male domain.', 'adv. 专门地，排除其他地', '/ik\'sklu:sivli | ɪk\'skluːsɪvlɪ | ɪk\'sklʊsɪvli/', 'exclusively', 3);
INSERT INTO `words` VALUES (32063, 'Your open pores excrete sweat and dirt.', 'v. 排泄, 分泌', '/ɪk\'skriːt; ek- | ɪk\'skrit/', 'excrete', 3);
INSERT INTO `words` VALUES (32064, 'a shopping excursion', 'n. 远足，短途旅行', '/ɪk\'skɜːʃ(ə)n; ek- | ɪk\'skɝʒn/', 'excursion', 3);
INSERT INTO `words` VALUES (32065, 'The job involves drawing up and executing a plan of nursing care.', 'v. 执行, 处决', '/\'eksikju:t | \'eksɪkjuːt | \'ɛksɪkjut/', 'execute', 3);
INSERT INTO `words` VALUES (32066, 'a public execution', 'n. 处决, 执行', '/,eksi\'kju:ʃən | ,eksɪ\'kjuːʃ(ə)n | ,ɛksɪ\'kjuʃən/', 'execution', 3);
INSERT INTO `words` VALUES (32067, 'a marketing executive', 'n. 主管，行政官a行政的', '/ɪg\'zekjʊtɪv; eg- | ɪɡ\'zɛkjətɪv/', 'executive', 3);
INSERT INTO `words` VALUES (32068, 'a company with an exemplary record on environmental issues', 'adj. 典范的,惩戒性的', '/iɡ\'zempləri | ɪg\'zemplərɪ; eg- | ɪɡ\'zɛmpləri/', 'exemplary', 3);
INSERT INTO `words` VALUES (32069, 'All these recipes exemplify my cooking: healthy, delicious and quick.', 'v. 例证, 例示', '/iɡ\'zemplifai | ɪg\'zemplɪfaɪ; eg- | ɪɡ\'zɛmplɪfaɪ/', 'exemplify', 3);
INSERT INTO `words` VALUES (32070, 'So we have the current argument over how much of the derivative market will be exempt from regulation.', 'v. 免除; adj. 被免除的', '/iɡ\'zempt | ɪg\'zem(p)t; eg- | ɪg\'zɛmpt/', 'exempt', 3);
INSERT INTO `words` VALUES (32071, 'Try to fit some regular exercise into your daily routine.', 'n&v. 运动,练习', '/\'eksəsaiz | \'eksəsaɪz | \'ɛksɚsaɪz/', 'exercise', 3);
INSERT INTO `words` VALUES (32072, 'He exerted considerable influence on the thinking of the scientific community on these issues.', 'v. 尽(力),发挥', '/iɡ\'zə:t | ɪg\'zɜːt; eg- | ɪɡ\'zɝt/', 'exert', 3);
INSERT INTO `words` VALUES (32073, 'the exertion of authority', 'n. 努力, 发挥,运用', '/iɡ\'zə:ʃən | ɪɡ\'zɜːʃn | ɪɡ\'zɝʃən/', 'exertion', 3);
INSERT INTO `words` VALUES (32074, 'Take a deep breath, then exhale slowly.', 'v. 呼气,发出', '/eks\'heil | ɪks\'heɪl; eks- | ɛks\'hel/', 'exhale', 3);
INSERT INTO `words` VALUES (32075, 'A full day’s teaching exhausts me.', 'v. 使筋疲力尽,耗尽', '/iɡ\'zɔ:st | ɪg\'zɔːst; eg- | ɪɡ\'zɔst/', 'exhaust', 3);
INSERT INTO `words` VALUES (32076, 'Sheer exhaustion forced him to give up.', 'n. 耗尽枯竭,疲惫,竭尽', '/iɡ\'zɔ:stʃən | ɪg\'zɔːstʃ(ə)n; eg- | ɪg\'zɔstʃən/', 'exhaustion', 3);
INSERT INTO `words` VALUES (32077, 'Her paintings have been exhibited all over the world.', 'n&v. 展览,陈列,展示', '/iɡ\'zibit | ɪg\'zɪbɪt; eg- | ɪɡ\'zɪbɪt/', 'exhibit', 3);
INSERT INTO `words` VALUES (32078, 'I’ve never seen such an exhibition of jealousy.', 'n. 表现,展览会', '/,eksi\'biʃən | eksɪ\'bɪʃ(ə)n | ,ɛksɪ\'bɪʃən/', 'exhibition', 3);
INSERT INTO `words` VALUES (32079, 'Schedules will be sent out to all exhibitors.', 'n. 展出者,显示者', '/iɡ\'zibitə | ɪg\'zɪbɪtə; eg- | ɪg\'zɪbɪtɚ/', 'exhibitor', 3);
INSERT INTO `words` VALUES (32080, NULL, 'v. 使高兴, 使愉快', '/iɡ\'ziləreit | ɪg\'zɪləreɪt; eg- | ɪɡ\'zɪləret/', 'exhilarate', 3);
INSERT INTO `words` VALUES (32081, 'an exhilarating experience', 'adj. 令人高兴的， 使人兴奋的', '/ɪg\'zɪləreɪtɪŋ | ɪɡ\'zɪləretɪŋ/', 'exhilarating', 3);
INSERT INTO `words` VALUES (32082, 'Kennedy exhorted his listeners to turn away from violence.', 'vt. 劝告， 规劝， 告诫', '/ɪg\'zɔːrt | ɪɡ\'zɔrt/', 'exhort', 3);
INSERT INTO `words` VALUES (32083, 'Scientists have many theories about how the universe first came into existence (= started to exist ).', 'n. 存在(物)', '/iɡ\'zistəns | ɪg\'zɪst(ə)ns; eg- | ɪɡ\'zɪstəns/', 'existence', 3);
INSERT INTO `words` VALUES (32084, 'They hitched the genes for these three factors onto a virus that infects another type of pancreatic cell, known as an exocrine cell.', 'adj. [医]外分泌的', '/\'eksəkrain | \'eksə(ʊ)kraɪn; -krɪn | \'ɛksəkrɪn/', 'exocrine', 3);
INSERT INTO `words` VALUES (32085, 'The medical system is facing collapse because of an exodus of doctors.', 'n. 大批离去， 成群外出', '/\'eksədəs | \'ɛksədəs/', 'exodus', 3);
INSERT INTO `words` VALUES (32086, NULL, 'adj. 外生的,外界产生的', '/ek\'sɔdʒənəs | ɪk\'sɒdʒɪnəs; ek- | ɛks\'ɑdʒɪnəs/', 'exogenous', 3);
INSERT INTO `words` VALUES (32087, 'Exorbitant housing prices have created an acute shortage of affordable housing for the poor.', 'adj. （要价等）过高的,（性格等）过分的', '/iɡ\'zɔ:bitənt | ɪg\'zɔːbɪt(ə)nt | ɪɡ\'zɔrbɪtənt/', 'exorbitant', 3);
INSERT INTO `words` VALUES (32088, 'An advanced onboard micro-computer ensures the exoskeleton moves in concert with the operator.', 'n. [动] 外骨骼', '/,eksəu\'skelitən | \'eksəʊ,skelɪt(ə)n | \'ɛksoskɛlɪtn/', 'exoskeleton', 3);
INSERT INTO `words` VALUES (32089, 'exotic birds', 'adj. 外来的', '/,iɡ\'zɔtik | ɪg\'zɒtɪk; eg- | ɪɡ\'zɑtɪk/', 'exotic', 3);
INSERT INTO `words` VALUES (32090, 'Water expands as it freezes.', 'v. 扩大,扩展,膨胀', '/ik\'spænd | ɪk\'spænd; ek- | ɪk\'spænd/', 'expand', 3);
INSERT INTO `words` VALUES (32091, 'The Mandarin Oriental\'s pool is small in real life, suitable only for a quick dip… nothing like the vast, blue expanse of water in the marketing photo.', 'n. 广阔；宽阔的区域', '/ik\'spæns | ɪk\'spæns; ek- | ɪk\'spæns/', 'expanse', 3);
INSERT INTO `words` VALUES (32092, 'The industry underwent a period of rapid expansion.', 'n. 膨胀,扩展,扩充', '/ik\'spænʃən | ɪk\'spænʃ(ə)n; ek- | ɪk\'spænʃən/', 'expansion', 3);
INSERT INTO `words` VALUES (32093, NULL, 'n&a. 扩张主义(的)', '/ik\'spænʃənist | ɪk\'spænʃənɪst/', 'expansionist', 3);
INSERT INTO `words` VALUES (32094, 'He will be hard to beat. I fully expect (= am completely sure about ) that and I’m ready.', 'v. 期待,预期', '/ik\'spekt | ɪk\'spekt; ek- | ɪk\'spɛkt/', 'expect', 3);
INSERT INTO `words` VALUES (32095, 'Having raised expectations (= made people more hopeful ), he went on to help only a few people.', 'n. 期待,预料', '/,ekspek\'teiʃən | ekspek\'teɪʃ(ə)n | ,ɛkspɛk\'teʃən/', 'expectation', 3);
INSERT INTO `words` VALUES (32096, 'This solution is politically expedient but may well cause long-term problems.', 'adj. 得当的， 可取的; n. 权宜之计，应急办法，临时手段', '/ɪk\'spiːdiənt | ɪk\'spidɪənt/', 'expedient', 3);
INSERT INTO `words` VALUES (32097, 'an expedition to the North Pole', 'n. 远征,探险队', '/,ekspi\'diʃən | ekspɪ\'dɪʃ(ə)n | ,ɛkspə\'dɪʃən/', 'expedition', 3);
INSERT INTO `words` VALUES (32098, 'The judge said that arbitration was a fair and expeditious decision-making process.', 'adj. 迅速而有效的， 迅速完成的', '/ˌekspə\'dɪʃəs | ,ɛkspə\'dɪʃəs/', 'expeditious', 3);
INSERT INTO `words` VALUES (32099, 'More than five-thousand high school students have been expelled for cheating.', 'vt. 开除； 驱逐； 排出', '/ɪk\'spel | ɪk\'spɛl/', 'expel', 3);
INSERT INTO `words` VALUES (32100, 'Children expend a lot of energy and may need more high-energy food than adults.', 'v. 花费,消耗,支出', '/ik\'spend | ɪk\'spend; ek- | ɪk\'spɛnd/', 'expend', 3);
INSERT INTO `words` VALUES (32101, 'You may be doing what could just as easily be done by someone else, which means you’re highly expendable. You may be playing follow the follower.', 'n. 消耗品, 可牺牲的', '/ik\'spendəbl | ɪk\'spendəb(ə)l; ek- | ɪk\'spɛndəbl/', 'expendable', 3);
INSERT INTO `words` VALUES (32102, 'huge cuts in public expenditure', 'n. 支出, 花费', '/iks\'penditʃə | ɪk\'spendɪtʃə; ek- | ɪk\'spɛndɪtʃɚ/', 'expenditure', 3);
INSERT INTO `words` VALUES (32103, 'He borrowed £150,000 and used the money for legal expenses.', 'n. 费用,代价', '/ik\'spens | ɪk\'spens; ek- | ɪk\'spɛns/', 'expense', 3);
INSERT INTO `words` VALUES (32104, 'the most expensive restaurant in town', 'adj. 昂贵的,高价的', '/ik\'spensiv | ɪk\'spensɪv; ek- | ɪk\'spɛnsɪv/', 'expensive', 3);
INSERT INTO `words` VALUES (32105, 'The advice in the booklet reflects the practical experience we have gained (= experience gained by actually doing something, rather than knowledge from books etc ).', 'n&vt. 经历,经验', '/ik\'spiəriəns | ɪk\'spɪərɪəns; ek- | ɪk\'spɪrɪəns/', 'experience', 3);
INSERT INTO `words` VALUES (32106, 'The astronauts are conducting a series of experiments to learn more about how the body adapts to weightlessness.', 'n. 试验; v. 尝试,做实验', '/ik\'speriment, ek\'s- | ɪk\'sperɪm(ə)nt; ek- | ɪk\'sperɪmənt/', 'experiment', 3);
INSERT INTO `words` VALUES (32107, 'experimental animals', 'adj. 实验(性)的，试验(性)的', '/ek,speri\'mentəl, ek\'s- | ɪk,sperɪ\'ment(ə)l; ek- | ɛk\'spɛrɪ\'mɛntəl/', 'experimental', 3);
INSERT INTO `words` VALUES (32108, 'The issue of animal experimentation is an emotive subject.', 'n. 实验', '/ik,sperimen\'teiʃən, ek,s- | ɪk,sperɪmen\'teɪʃən | ɪk,spɛrɪmɛn\'teʃən/', 'experimentation', 3);
INSERT INTO `words` VALUES (32109, 'The experimenter said “Look at my toy!', 'n. 实验者', '/ik\'sperimentə/', 'experimenter', 3);
INSERT INTO `words` VALUES (32110, '...a yoga expert.', 'n. 专家, 行家', '/\'ekspə:t, ek\'spə:t | \'ekspɜːt | \'ɛkspɝt; (for adj., also) ɛksˈpɝt ; ɪkˈspɝt/', 'expert', 3);
INSERT INTO `words` VALUES (32111, 'She was not an accountant and didn\'t have the expertise to verify all of the financial details.', 'n. 专门知识(或技能等)，专长', '/,ekspə:\'ti:z | ,ekspɜː\'tiːz | \'ɛkspɝ\'tiz/', 'expertise', 3);
INSERT INTO `words` VALUES (32112, 'The nurse dressed the wound expertly.', 'adv. 熟练地', '/\'ɛkspɚtli/', 'expertly', 3);
INSERT INTO `words` VALUES (32113, 'My passport expires next week.', 'vi. 到期， 期满， 失效； 断气， 去世', '/ɪk\'spaɪər | ɪk\'spaɪɚ/', 'expire', 3);
INSERT INTO `words` VALUES (32114, 'She told the court she would give a full explanation of the prosecution\'s decision on Monday.', 'n. 解释,说明', '/,eksplə\'neiʃən | eksplə\'neɪʃ(ə)n | ,ɛksplə\'neʃən/', 'explanation', 3);
INSERT INTO `words` VALUES (32115, 'The contrast could not have been made more explicit.', 'adj. 明确的,清晰的', '/ik\'splisit | ɪk\'splɪsɪt; ek- | ɪk\'splɪsɪt/', 'explicit', 3);
INSERT INTO `words` VALUES (32116, 'The device was thrown at an army patrol but failed to explode.', 'v. 爆炸；爆发', '/ik\'spləud | ɪk\'spləʊd; ek- | ɪk\'splod/', 'explode', 3);
INSERT INTO `words` VALUES (32117, 'the urgent need to exploit the resources of the Irish Sea', 'v. 开拓,开采', '/\'eksplɔit, ik\'s- | ɪk\'splɒɪt; ek- | ɪk\'splɔɪt/', 'exploit', 3);
INSERT INTO `words` VALUES (32118, NULL, 'n. 开发, 开采', '/eksplɒɪ\'teɪʃ(ə)n | ,ɛksplɔɪ\'teʃən/', 'exploitation', 3);
INSERT INTO `words` VALUES (32119, 'oil exploration facilities in the North Sea', 'n. 探险, 探测', '/,eksplɔ:\'reiʃən | eksplə\'reɪʃ(ə)n | ,ɛksplə\'reʃən/', 'exploration', 3);
INSERT INTO `words` VALUES (32120, 'He’s going to have exploratory surgery on his knee.', 'adj. 勘探的, 探索的', '/ik\'splɔrətəri | ɪk\'splɒrət(ə)rɪ; ek- | ɪk\'splɔrətɔri/', 'exploratory', 3);
INSERT INTO `words` VALUES (32121, 'Management need to explore ways of improving office security.', 'v. 探险,探测', '/ik\'splɔ: | ɪk\'splɔː; ek- | ɪk\'splɔr/', 'explore', 3);
INSERT INTO `words` VALUES (32122, '...the travels of Columbus, Magellan, and many other explorers.', 'n. 探险者', '/ek\'splɔːrə(r) | ɪk\'splɔrɚ/', 'explorer', 3);
INSERT INTO `words` VALUES (32123, 'We heard a loud explosion.', 'n. 爆炸,爆发', '/ik\'spləuʒən | ɪk\'spləʊʒ(ə)n; ek- | ɪk\'sploʒən/', 'explosion', 3);
INSERT INTO `words` VALUES (32124, 'Because the gas is highly explosive, it needs to be kept in high-pressure containers.', 'adj. 爆炸(性)的,暴露; n. 爆炸物', '/ik\'spləusiv | ɪk\'spləʊsɪv; ek- | ɪk\'splosɪv; ɪk\'splozɪv/', 'explosive', 3);
INSERT INTO `words` VALUES (32125, 'As grungy as the rock audience may have been, it wanted its music explosively amplified and expertly modulated; it wanted to hear the beat through its pores.', 'adv. 爆发地, 引起爆炸地', '/ik\'spləusivli/', 'explosively', 3);
INSERT INTO `words` VALUES (32126, '...the 1995 Queensland Computer Expo.', 'n. 博览会, 展览会', '/\'ekspəu | \'ekspəʊ | \'ɛkspoʊ/', 'expo', 3);
INSERT INTO `words` VALUES (32127, '...a leading exponent of test-tube baby techniques.', 'n. 阐述者,倡导者', '/ɪk\'spəʊnənt; ek- | ɪk\'sponənt/', 'exponent', 3);
INSERT INTO `words` VALUES (32128, 'This is an exponential function.', 'n. 指数; adj. 指数的, 幂数的', '/,ekspəu\'nenʃəl | ,ekspə\'nenʃ(ə)l | \'ɛkspə\'nɛnʃəl/', 'exponential', 3);
INSERT INTO `words` VALUES (32129, 'Wheat is one of the country’s main exports.', 'v&n. 输出,出口', '/ik\'spɔ:t, \'eks-, \'ekspɔ:t | ˈekspɔːt；ɪkˈ- | ˈekspɔːrt；ɪkˈ-/', 'export', 3);
INSERT INTO `words` VALUES (32130, '\"The laws prohibiting such exportation must be reinstated as soon as possible, \" he said.', 'n. 出口', '/,ekspɔ:\'teiʃən | ,ekspɔː\'teɪʃən | ,ɛkspɔr\'teʃən/', 'exportation', 3);
INSERT INTO `words` VALUES (32131, 'He lifted his T-shirt to expose a jagged scar across his chest.', 'v. 暴露,显露', '/ik\'spəuz | ɪk\'spəʊz; ek- | ɪk\'spoz；ek-/', 'expose', 3);
INSERT INTO `words` VALUES (32132, '...an art exposition.', 'n. 展览会, 说明', '/,ekspəu\'ziʃən | ekspə\'zɪʃ(ə)n | ,ɛkspə\'zɪʃən/', 'exposition', 3);
