INSERT INTO `words` VALUES (32134, 'Student leaders are demanding greater freedom of expression (= the right to say what you think without being punished ).', 'n. 措辞,表达', '/英 [ɪk\'spreʃn] 美 [ɪkˈsprɛʃən | ɪkˈspreʃn | ɪk\'sprɛʃən/', 'expression', 3);
INSERT INTO `words` VALUES (32135, 'a blank expressionless stare', 'adj. 无表情的', '/ik\'spreʃənlis | ɪk\'spreʃ(ə)nlɪs/', 'expressionless', 3);
INSERT INTO `words` VALUES (32136, 'her wonderfully expressive eyes', 'adj. 表达的,意味深长的', '/ik\'spresiv | ɪk\'spresɪv; ek- | ɪk\'sprɛsɪv/', 'expressive', 3);
INSERT INTO `words` VALUES (32137, 'Moreover, it offers the expressiveness which helps to “simplify complex tasks”.', 'n. 表现, 表示', '/ik\'spresivnis/', 'expressiveness', 3);
INSERT INTO `words` VALUES (32138, 'The Bolsheviks expropriated the property of the landowners.', 'vt. 征用， 没收', '/eks\'prouprieɪt | ɛks\'proprɪet/', 'expropriate', 3);
INSERT INTO `words` VALUES (32139, 'We plan to extend the kitchen by six feet.', 'v. 延伸,扩展', '/ik\'stend | ɪk\'stend; ek- | ɪk\'stɛnd/', 'extend', 3);
INSERT INTO `words` VALUES (32140, 'We are thinking of having an extension built, as we now require an extra bedroom.', 'n. 延长, 扩充', '/ik\'stenʃən | ɪk\'stenʃ(ə)n; ek- | ɪk\'stɛnʃən/', 'extension', 3);
INSERT INTO `words` VALUES (32141, 'The house stands in extensive grounds.', 'adj. 广泛的,广阔的', '/ik\'stensiv | ɪk\'stensɪv; ek- | ɪk\'stɛnsɪv/', 'extensive', 3);
