INSERT INTO `words` VALUES (32143, 'They examined the extent to which (= how much ) age affected language-learning ability.', 'n. 范围,程度,广度', '/ik\'stent | ɪk\'stent; ek- | ɪk\'stɛnt/', 'extent', 3);
