INSERT INTO `words` VALUES (32149, 'Dinosaurs have been extinct for millions of years.', 'adj. 熄灭的,灭绝的', '/ik\'stiŋkt | ɪk\'stɪŋkt; ek- | ɪk\'stɪŋkt/', 'extinct', 3);
