INSERT INTO `words` VALUES (32159, 'Extrapolating from his latest findings, he reckons about 80% of these deaths might be attributed to smoking.', 'v. 外推； 推断， 推知', '/ɪk\'stræpəleɪt | ɪk\'stræpə\'let/', 'extrapolate', 3);
INSERT INTO `words` VALUES (32160, 'Would it be too extravagant to buy both?', 'adj. 放肆的， 过分的； 奢侈的， 铺张的', '/ɪk\'strævəgənt/', 'extravagant', 3);
