INSERT INTO `words` VALUES (32163, 'In spite of the extremity of her seclusion she was sane.', 'n. 极度，绝境', '/ik\'stremiti | ɪk\'stremɪtɪ; ek- | ɪk\'strɛməti/', 'extremity', 3);
