INSERT INTO `words` VALUES (32702, 'Arthur was a very gentle, caring person.', 'adj. 温和的, 文雅的', '/\'dʒentl | \'dʒent(ə)l | \'dʒɛntl/', 'gentle', 3);
INSERT INTO `words` VALUES (32703, 'Could you serve this gentleman please, Miss Bath?', 'n. 阁下, 先生', '/\'dʒent(ə)lmən | \'dʒɛntlmən/', 'gentleman', 3);
INSERT INTO `words` VALUES (32704, 'He was respected by all who knew him for his kind and gentlemanly consideration.', 'adj. 绅士派头的', '/\'dʒentlmənli | \'dʒent(ə)lmənlɪ/', 'gentlemanly', 3);
INSERT INTO `words` VALUES (32705, '‘You go back to bed now,’ he said gently.', 'adv. 轻轻地, 温柔地', '/\'dʒentli | \'dʒentlɪ | \'dʒɛntli/', 'gently', 3);
INSERT INTO `words` VALUES (32706, 'Have on parental caress by every means, next issueless pester genu disturbing, everyday carefree, live easily comfortable.', 'n. 膝', '/\'dʒenju | \'dʒenjuː | ˈdʒɛnjuː/', 'genu', 3);
INSERT INTO `words` VALUES (32707, '‘Did he really?’ Her surprise seemed genuine.', 'adj. 真实的, 真正的, 诚恳的', '/\'dʒenjuin | \'dʒenjʊɪn | \'dʒɛnjʊɪn/', 'genuine', 3);
INSERT INTO `words` VALUES (32708, 'They must genuinely like one another, and work well together.', 'adv. 真正地, 由衷地', '/\'dʒenjuinli/', 'genuinely', 3);
INSERT INTO `words` VALUES (32709, 'But there’s very little doubt that if methane emissions are as large as this, there will be severe biological and geochemical impacts.', 'adj. 地球化学的', '/,dʒi:ə\'kemikəl/', 'geochemical', 3);
INSERT INTO `words` VALUES (32710, 'Another reason, says Peter Hopkins, a geographer at Newcastle University, is that Scotland’s cultural iconography is much more vivid and more popular than England’s.', 'n. 地理学者', '/dʒi\'ɔɡrəfə | dʒɪ\'ɒɡrəfə | dʒɪ\'ɑɡrəfɚ/', 'geographer', 3);
INSERT INTO `words` VALUES (32711, 'User community and geographic distribution of users.', 'adj. 地理(学)的', '/dʒiə\'græfik | ,dʒɪə\'græfɪk | ,dʒiə\'ɡræfɪk/', 'geographic', 3);
INSERT INTO `words` VALUES (32712, 'their geographical proximity to Japan (= nearness to Japan )', 'adj. 地理(学)的', '/dʒiə\'ɡræfikəl | dʒɪə\'græfɪk(ə)l | dʒɪə\'græfɪkl/', 'geographical', 3);
INSERT INTO `words` VALUES (32713, 'a geography lesson', 'n. 地理(学)', '/dʒi\'ɔɡrəfi | dʒɪ\'ɒgrəfɪ | dʒɪ\'ɑɡrəfi/', 'geography', 3);
INSERT INTO `words` VALUES (32714, 'The best gauge of quake risk is the geologic record.', 'adj. 地质的', '/,dʒiəu\'lɔdʒik | ,dʒɪəʊ\'lɒdʒɪk | dʒɪə\'lɑdʒɪk/', 'geologic', 3);
INSERT INTO `words` VALUES (32715, 'With geological maps, books, and atlases you can find out all the proven sites of precious minerals.', 'adj. 地质学的', '/dʒiə\'lɔdʒikəl | dʒɪə\'lɒdʒɪkl | dʒɪə\'lɑdʒɪkl/', 'geological', 3);
INSERT INTO `words` VALUES (32716, 'Apollo astronauts used seismometers during their visits to the Moon and discovered that the gray orb isn\'t a totally dead place, geologically speaking.', 'adv. 地质学上', '/,dʒiə\'lɔdʒikəli/', 'geologically', 3);
INSERT INTO `words` VALUES (32717, 'He is also a geologist.', 'n. 地质学者', '/dʒi\'ɔlədʒist | dʒɪ\'ɒlədʒɪst | dʒɪ\'ɑlədʒɪst/', 'geologist', 3);
INSERT INTO `words` VALUES (32718, 'He was visiting professor of geology at the University of Georgia.', 'n. 地质学,地质概况', '/dʒi\'ɔlədʒi | dʒɪ\'ɒlədʒɪ | dʒɪ\'ɑlədʒi/', 'geology', 3);
INSERT INTO `words` VALUES (32719, 'The resulting solar storm could cause a geomagnetic storm on Earth, knocking out electricity grids around the world for hours, days, or even months, bringing much of normal life grinding to a halt.', 'adj. 地磁的,地磁气的', '/,dʒɪ(ː)əʊmæɡ\'netɪk | ,dʒiomæg\'nɛtɪk/', 'geomagnetic', 3);
INSERT INTO `words` VALUES (32720, 'a geometric design', 'adj. 几何(学)的', '/dʒiəu\'metrik | ,dʒɪə\'metrɪk | ,dʒiə\'mɛtrɪk/', 'geometric', 3);
INSERT INTO `words` VALUES (32721, 'A geometrical wonder, DOME ECILE not only is a sight in and of itself, but it also sports beautiful beach views.', 'adj. 几何学的, 几何的', '/dʒiə\'metrikəl | dʒɪə\'metrɪkl | dʒɪə\'mɛtrɪkl/', 'geometrical', 3);
INSERT INTO `words` VALUES (32722, 'So, geometrically, my function can be represented by this graph, and I fix some point, .', 'adv. 成几何级数(图形)地', '/,dʒiə\'metrikəli/', 'geometrically', 3);
INSERT INTO `words` VALUES (32723, '...the very ordered way in which mathematics and geometry describe nature.', 'n. 几何， 几何学', '/dʒi\'ɑːmətri | dʒɪ\'ɑmətri/', 'geometry', 3);
INSERT INTO `words` VALUES (32724, 'These geophysical facts affect the use of language in discussions about water, and the ways in which to think about the problems of scarcity.', 'adj. 地球物理学的', '/dʒi:əu\'fizikəl | ,dʒio\'fɪzɪkl/', 'geophysical', 3);
INSERT INTO `words` VALUES (32725, 'In the past week alone we have lost about ten colleagues, in Georgia and in Afghanistan.', 'n. (美)乔治亚州', '/\'dʒɔ:dʒjə/', 'Georgia', 3);
INSERT INTO `words` VALUES (32726, 'a geothermal energy plant', 'adj. 地热的', '/,dʒi:əu\'θə:məl | dʒiːə(ʊ)\'θɜːm(ə)l | ,dʒio\'θɝml/', 'geothermal', 3);
INSERT INTO `words` VALUES (32727, 'The first geothermally generated electricity was produced in Larderello, Italy, in 1904.', 'adj. 地热的', NULL, 'geothermally', 3);
INSERT INTO `words` VALUES (32728, 'Put disinfectant down the toilet to kill any germs.', 'n. 微生物, 细菌', '/dʒə:m | dʒɜːm | dʒɝm/', 'germ', 3);
INSERT INTO `words` VALUES (32729, 'I heard a very angry man talking in German.', 'n. 德国人; adj. 德国的', '/\'dʒə:mən | \'dʒɜːmən/', 'German', 3);
INSERT INTO `words` VALUES (32730, 'It s also the first germanium laser to operate at room temperature.', 'n. 锗', '/dʒə:\'meiniəm | dʒɜː\'meɪnɪəm | dʒɝ\'menɪəm/', 'germanium', 3);
INSERT INTO `words` VALUES (32731, 'Germany borders on France.', 'n. 德国', '/\'dʒə:məni | \'dʒɜːmənɪ | \'dʒɝməni/', 'Germany', 3);
INSERT INTO `words` VALUES (32732, 'Some seed varieties germinate fast, so check every day or so.', 'v. 发芽,使生长', '/\'dʒə:mineit | \'dʒɜːmɪneɪt | \'dʒɝmɪnet/', 'germinate', 3);
INSERT INTO `words` VALUES (32733, 'In this way, postmodernism might be seen as the delayed germination of an older seed, planted by artists like Marcel Duchamp, during modernism’s high noon of the 1920s and 1930s.', 'n. 萌芽, 发生', '/,dʒə:mi\'neiʃən | ,dʒɝmə\'neʃən/', 'germination', 3);
INSERT INTO `words` VALUES (32734, 'Processing category:Various dry and wet materials that could be crushed, including chemical raw materials, gesso powders, hulls, grains, and plastics .', 'n. (雕刻、绘画用的)石膏, 石膏粉', '/\'dʒesəu | \'dʒesəʊ/', 'gesso', 3);
INSERT INTO `words` VALUES (32735, 'Luke made an obscene gesture with his finger.', 'n. 姿态, 手势', '/\'dʒestʃə | \'dʒɛstʃɚ/', 'gesture', 3);
INSERT INTO `words` VALUES (32736, 'We need to get help quickly!', 'v. 获得,得到', '/get | ɡɛt/', 'get', 3);
INSERT INTO `words` VALUES (32737, NULL, 'n. 天然热喷泉', '/\'ɡeizə | \'giːzə; \'gaɪ- | \'ɡaɪzɚ/', 'geyser', 3);
INSERT INTO `words` VALUES (32738, 'They say the young girl’s ghost still haunts (= often appears in ) the house.', 'n. 鬼, 幽灵', '/ɡəust | gəʊst | ɡost/', 'ghost', 3);
INSERT INTO `words` VALUES (32739, '...Sonia\'s ghostly laughter.', 'adj. 可怕的', '/\'ɡəustli | \'gəʊs(t)lɪ | \'ɡostli/', 'ghostly', 3);
INSERT INTO `words` VALUES (32740, '...a Nordic saga of giants.', 'n. 巨人,天才', '/\'dʒaiənt | \'dʒaɪənt/', 'giant', 3);
INSERT INTO `words` VALUES (32741, 'Beverly: Why else would you grow a pancreas in a teenaged gibbon?', 'n. 长臂猿', '/\'ɡibən | \'gɪb(ə)n | \'ɡɪbən/', 'gibbon', 3);
INSERT INTO `words` VALUES (32742, '“Please don’t gibe me,” Lydia said.', 'v. 嘲笑,讥笑; n. 嘲笑', '/dʒaib/', 'gibe', 3);
INSERT INTO `words` VALUES (32743, NULL, 'n. 直布罗陀(海峡)', '/dʒi\'brɔ:ltə/', 'gibraltar', 3);
INSERT INTO `words` VALUES (32744, 'As a youth he discovered a gift for teaching.', 'n. 赠品, 天赋', '/ɡift | gɪft | ɡɪft/', 'gift', 3);
INSERT INTO `words` VALUES (32745, 'a gigantic skyscraper', 'adj. 巨大的， 庞大的', '/dʒaɪ\'gæntɪk | dʒaɪ\'ɡæntɪk/', 'gigantic', 3);
INSERT INTO `words` VALUES (32746, 'a gilded frame', 'v. 镀金', '/gild | gɪld | ɡɪld/', 'gild', 3);
INSERT INTO `words` VALUES (32747, 'A thin layer of gold or something simulating gold that is applied in gilding.', 'n. 镀金； 贴金层， 镀金层； 金色涂层', '/\'gɪldɪŋ | \'ɡɪldɪŋ/', 'gilding', 3);
INSERT INTO `words` VALUES (32748, NULL, 'n. 鳃,及耳[液量单位]', '/gɪl | ɡɪl/', 'gill', 3);
INSERT INTO `words` VALUES (32749, '...another gin and tonic.', 'n. 杜松烧酒 v开始', '/dʒin | dʒɪn/', 'gin', 3);
INSERT INTO `words` VALUES (32750, 'a red and white gingham tablecloth', 'n. 条纹棉布', '/\'ɡiŋəm | \'gɪŋəm | \'ɡɪŋəm/', 'gingham', 3);
INSERT INTO `words` VALUES (32751, 'I/ you/ we/ they like giraffe.', 'n. 长颈鹿', '/dʒə\'ræf | dʒəˈræf; dʒəˈræf/', 'giraffe', 3);
INSERT INTO `words` VALUES (32752, 'Listen, when you start to feel weak, just tell yourself, ‘I’m as strong as a girder’ .', 'n. 梁', '/\'ɡə:də | \'gɜːdə | \'ɡədɚ/', 'girder', 3);
INSERT INTO `words` VALUES (32753, 'Both boys and girls can apply to join the choir.', 'n. 女孩', '/gɜːl | ɡɝl/', 'girl', 3);
INSERT INTO `words` VALUES (32754, 'Don’t worry about all the details as long as you get the gist (= understand the main meaning ) of it.', 'n. 要点, 要旨', '/dʒist | dʒɪst/', 'gist', 3);
INSERT INTO `words` VALUES (32755, 'On any given day in the Houston area, half the hospital beds are empty.', 'adj. 规定的，特定的；假定的; prep. 考虑到， 鉴于', '/\'gɪvn | \'ɡɪvn/', 'given', 3);
INSERT INTO `words` VALUES (32756, 'a glacial valley', 'adj. 冰川(期)的,非常冷的', '/\'ɡleisjəl | \'gleɪsɪəl; -ʃ(ə)l | \'ɡleʃl/', 'glacial', 3);
INSERT INTO `words` VALUES (32757, NULL, 'v. 使结冰, 以冰(或冰河)覆盖', '/\'ɡleisieit | \'ɡleɪsɪeɪt/', 'glaciate', 3);
INSERT INTO `words` VALUES (32758, 'These changes alter the intensity of sunlight hitting the Earth at high latitudes, and so affect the extent of glaciation.', 'n. 冻结成冰,冰河作用', '/,ɡleisi\'eiʃən | \'glesɪ\'eʃən/', 'glaciation', 3);
INSERT INTO `words` VALUES (32759, 'Do you think we can glide down this glacier?', 'n. 冰川， 冰河', '/\'gleɪʃər | \'ɡleʃɚ/', 'glacier', 3);
INSERT INTO `words` VALUES (32760, 'She led an exciting and glamorous life.', 'adj. 富有魅力的, 迷人的', '/\'ɡlæmərəs | \'glæmərəs/', 'glamorous', 3);
INSERT INTO `words` VALUES (32761, 'He gave her a quick glance and smiled.', 'n. /v一瞥,匆匆一看', '/ɡlɑ:ns, ɡlæns | glɑːns | ɡlæns/', 'glance', 3);
INSERT INTO `words` VALUES (32762, 'the pituitary gland', 'n. 腺', '/ɡlænd | glænd/', 'gland', 3);
INSERT INTO `words` VALUES (32763, '...the amount of fat and glandular tissue in the breasts.', 'adj. 腺的,腺状的', '/\'ɡlændjulə | \'glændjʊlə; \'glæn(d)ʒʊlə | \'glændʒəlɚ/', 'glandular', 3);
INSERT INTO `words` VALUES (32764, 'a special screen to reduce glare', 'n. 闪耀光, 刺眼 v发眩光, 瞪视', '/ɡlεə | gleə | ɡlɛr/', 'glare', 3);
INSERT INTO `words` VALUES (32765, 'a glass bowl', 'n. 玻璃,玻璃杯,[pl]眼镜', '/ɡlɑ:s, ɡlæs | glɑːs | ɡlæs/', 'glass', 3);
INSERT INTO `words` VALUES (32766, 'One animal captured on video looks like a flower, covered with glasslike needles, but scientists think it is probably a carnivorous sponge.', 'adj. 玻璃状的', NULL, 'glasslike', 3);
INSERT INTO `words` VALUES (32767, 'A glassmaker places a rounded piece of clay material on the end of a long metal stick.', 'n. 玻璃工人', '/\'ɡlɑ:s,meikə, \'ɡlæs- | \'ɡlɑːs,meɪkə | \'ɡlæs,mekɚ/', 'glassmaker', 3);
INSERT INTO `words` VALUES (32768, 'In 1868, when the industry was still struggling to re-establish other forms of glassmaking, 3,662 tons of beads were exported.', 'n. 玻璃(或玻璃器皿等)制造(术)', '/\'ɡlɑ:s,meikiŋ, \'ɡlæs-/', 'glassmaking', 3);
INSERT INTO `words` VALUES (32769, 'We have replaced the broken glassware.', 'n. 玻璃器具类', '/\'ɡlɑ:swεə, \'ɡlæs- | \'glɑːsweə/', 'glassware', 3);
INSERT INTO `words` VALUES (32770, 'Polymer clay pieces often mimic millefiori, a glasswork technique commonly seen in paperweights.', 'n. 玻璃制品; v. 制成玻璃状的', '/\'ɡlɑ:swə:k, \'ɡlæs- | \'glæs,wərk/', 'glasswork', 3);
INSERT INTO `words` VALUES (32771, 'The water was glassy.', 'adj. 象玻璃的', '/\'ɡlɑ:si, \'ɡlæs- | \'glɑːsɪ | \'ɡlæsi/', 'glassy', 3);
INSERT INTO `words` VALUES (32772, 'Sometimes his eyes would glaze over for a second or two.', 'v. 变呆滞; v. 上釉; n. 釉(料)', '/ɡleiz | gleɪz | ɡlez/', 'glaze', 3);
INSERT INTO `words` VALUES (32773, 'His teeth gleamed under his moustache.', 'vi. 闪光， 闪烁； 流露出; n. 微光；一丝，一线；表露', '/gliːm | ɡlim/', 'gleam', 3);
INSERT INTO `words` VALUES (32774, 'At present we\'re gleaning information from all sources.', 'v. 拾落穗, 收集', '/ɡli:n | gliːn | ɡlin/', 'glean', 3);
INSERT INTO `words` VALUES (32775, NULL, 'n. 峡谷, 溪谷', '/ɡlen | glen | ɡlɛn/', 'glen', 3);
INSERT INTO `words` VALUES (32776, 'The glial tissue is where the largest percentage of brain tumors begin.', 'adj. 神经胶质的', '/\'ɡlaiəl | \'ɡlaɪəl | \'ɡlaɪə/', 'glial', 3);
INSERT INTO `words` VALUES (32777, 'Waiters glide between tightly packed tables bearing trays of pasta.', 'v&n. 滑行', '/glaɪd | ɡlaɪd/', 'glide', 3);
INSERT INTO `words` VALUES (32778, 'And go for a ride on a glider airplane, because who says planes need motors?', 'n. 滑行(或物), 滑翔机', '/\'ɡlaidə | \'glaɪdə | \'ɡlaɪdɚ/', 'glider', 3);
INSERT INTO `words` VALUES (32779, 'a weak glimmering light', 'vi. 发微光； 隐约出现; n. 闪烁的微光；隐约的迹象；一丝，一线', '/\'glɪmər | \'ɡlɪmɚ/', 'glimmer', 3);
INSERT INTO `words` VALUES (32780, 'Some of the fans had waited 24 hours outside the hotel to catch a glimpse of their heroine.', 'n. 一瞥v瞥见', '/ɡlimps | glɪm(p)s | ɡlɪmps/', 'glimpse', 3);
INSERT INTO `words` VALUES (32781, 'glistening black hair', 'v. 闪光', '/\'ɡlisən | \'glɪs(ə)n | \'ɡlɪsn/', 'glisten', 3);
INSERT INTO `words` VALUES (32782, 'The river glittered in the sunlight.', 'vi. 闪烁，闪耀; n. 灿烂的光辉； 诱惑力， 魅力', '/\'glɪtər | \'ɡlɪtɚ/', 'glitter', 3);
INSERT INTO `words` VALUES (32783, 'global climate change', 'adj. 全球性的,总的', '/\'ɡləubəl | \'gləʊb(ə)l | \'ɡlobl/', 'global', 3);
