INSERT INTO `words` VALUES (32786, 'The report paints a gloomy picture of the economy.', 'adj. 忧郁的， 令人沮丧的； 昏暗的， 阴暗的， 阴沉的', '/\'gluːmi | \'ɡlumi/', 'gloomy', 3);
INSERT INTO `words` VALUES (32787, 'films which glorify violence', 'vt. 吹捧， 美化； 赞美， 赞扬', '/\'glɔːrɪfaɪ | \'ɡlɔrɪfaɪ/', 'glorify', 3);
INSERT INTO `words` VALUES (32788, 'a truly glorious future', 'adj. 壮丽的， 辉煌的； 光荣的； 令人愉快的， 极好的', '/\'glɔːriəs | \'ɡlɔriəs; \'ɡloriəs/', 'glorious', 3);
INSERT INTO `words` VALUES (32789, 'She dreamt of future glory as an Olympic champion.', 'n. 荣誉, 光荣', '/\'ɡlɔ:ri | \'glɔːrɪ | \'ɡlɔri/', 'glory', 3);
INSERT INTO `words` VALUES (32790, 'This gel will add gloss to even the dullest hair.', 'n. 光泽，注解', '/ɡlɔs | glɒs | ɡlɑs/', 'gloss', 3);
