INSERT INTO `words` VALUES (32792, 'The bedside lamp glowed dimly.', 'v. 发光, 发热', '/ɡləu | gləʊ | ɡlo/', 'glow', 3);
INSERT INTO `words` VALUES (32793, '...a tube of glue.', 'n. 胶(水) vt胶合', '/ɡlu: | gluː | ɡlu/', 'glue', 3);
INSERT INTO `words` VALUES (32794, 'Straight edge: The miracle fruit (Synsepalum dulcificum), native to West Africa, contains a glycoprotein called miraculin that binds to taste receptors on the tongue and makes sour foods taste sweet.', 'n. [化]糖蛋白类, 醣蛋白', '/,ɡlaikəu\'prəutin | ,glaɪkə(ʊ)\'prəʊtiːn/', 'glycoprotein', 3);
