INSERT INTO `words` VALUES (32796, 'Dexter gnawed his pen thoughtfully.', 'v. 啃，咬', '/nɔ: | nɔː | nɔ/', 'gnaw', 3);
INSERT INTO `words` VALUES (32797, 'The plate went crashing to the floor.', 'v. 去,离开,进行', '/gəʊ | go/', 'go', 3);
INSERT INTO `words` VALUES (32798, 'Your goal as a parent is to help your child become an independent adult.', 'n. 目的,目标', '/ɡəul | gəʊl | ɡol/', 'goal', 3);
INSERT INTO `words` VALUES (32799, 'The tiger sprang on the goat.', 'n. 山羊', '/ɡəut | gəʊt | ɡot/', 'goat', 3);
INSERT INTO `words` VALUES (32800, NULL, 'n. 戈壁', '/\'ɡəubi/', 'gobi', 3);
