INSERT INTO `words` VALUES (32805, 'They had safes in their shop and some people would say to the goldsmith I have some valuables.', 'n. 金匠', '/\'ɡəuldsmiθ | \'gəʊl(d)smɪθ | \'gold\'smɪθ/', 'goldsmith', 3);
