INSERT INTO `words` VALUES (33043, 'It was winter and there was a huge fire roaring in the hearth.', 'n. 壁炉地面, 家庭（生活）', '/hɑ:θ | hɑːθ | hɑrθ/', 'hearth', 3);
INSERT INTO `words` VALUES (33044, 'Did you turn the heater off?', 'n. 加热器', '/\'hi:tə | \'hiːtə | \'hitɚ/', 'heater', 3);
INSERT INTO `words` VALUES (33045, 'Michael’s shoulders heaved with silent laughter.', 'v. 举起; n. 举起,投掷', '/hi:v | hiːv | hiv/', 'heave', 3);
INSERT INTO `words` VALUES (33046, 'His heavy boots cumbered him in walking.', 'a&ad. 重的,大量的', '/\'hevɪ | \'hɛvi/', 'heavy', 3);
INSERT INTO `words` VALUES (33047, 'Mist rose from a nearby stand of thriving eucalyptus trees she planted after receiving title to more than a hectare of farmland.', 'n. 公顷（等于1万平方米）', '/\'hektɑ: | \'hekteə; -ɑː | \'hɛktɛr/', 'hectare', 3);
INSERT INTO `words` VALUES (33048, 'You’re hedging again - have you got the money or haven’t you?', 'v. 用篱笆围； 避免直接回答; n. 树篱；防止损失的措施；防备', '/hedʒ | hɛdʒ/', 'hedge', 3);
INSERT INTO `words` VALUES (33049, 'The government was taking little heed of these threats.', 'n. 注意,留意; v. 注意,留意', '/hi:d | hiːd | hid/', 'heed', 3);
INSERT INTO `words` VALUES (33050, 'black boots with high heels', 'n. 脚后跟', '/hi:l | hiːl | hil/', 'heel', 3);
INSERT INTO `words` VALUES (33051, 'Sam’s about the same height as his sister now.', 'n. 高度,海拔', '/hait | haɪt/', 'height', 3);
INSERT INTO `words` VALUES (33052, 'Both factors heighten the danger of a hacker break-in.', 'v. 提高, 升高', '/\'haitən | \'haɪt(ə)n | \'haɪtn/', 'heighten', 3);
INSERT INTO `words` VALUES (33053, 'You can helicopter to the island.', 'n. 直升(飞)机, 直升机', '/\'helikɔptə | \'helɪkɒptə | \'hɛlɪkɑptɚ/', 'helicopter', 3);
INSERT INTO `words` VALUES (33054, 'We have a helium nucleus and one electron.', 'n. 氦', '/\'hi:liəm | \'hiːlɪəm | \'hilɪəm/', 'helium', 3);
INSERT INTO `words` VALUES (33055, 'I was a classroom helper at the local primary school.', 'n. 帮忙者, 助手', '/\'helpə | \'helpə(r) | \'hɛlpɚ/', 'helper', 3);
INSERT INTO `words` VALUES (33056, 'Thank you for your advice; it’s been very helpful.', 'adj. 有益的；给予帮助的', '/\'helpful | \'helpfʊl; -f(ə)l | \'hɛlpfl/', 'helpful', 3);
INSERT INTO `words` VALUES (33057, 'He began to feel depressed and helpless.', 'adj. 无助的,没用的', '/\'helplis | \'helplɪs | \'hɛlpləs/', 'helpless', 3);
INSERT INTO `words` VALUES (33058, NULL, 'adv. 无能为力地', '/\'helplisli/', 'helplessly', 3);
INSERT INTO `words` VALUES (33059, 'When we look at the world around us, particularly as portrayed in the media, many of us feel a sense of helplessness at our perceived inability to manifest change.', 'n. 无能为力', NULL, 'helplessness', 3);
INSERT INTO `words` VALUES (33060, 'The seamstress bound the hem of the dress with a ruffle.', 'n. 边,缘 v给缝边', '/hem | hɛm/', 'hem', 3);
INSERT INTO `words` VALUES (33061, 'the Northern hemisphere', 'n. 半球', '/\'hemi,sfiə | \'hemɪsfɪə | \'hɛmɪsfɪr/', 'hemisphere', 3);
INSERT INTO `words` VALUES (33062, 'Soon a dark wall of trees—red spruce, balsam fir, beech, hemlock—surrounds you, and there\'s a sudden stony persistence.', 'n. 铁杉,毒芹', '/\'hemlɔk | \'hemlɒk | \'hɛmlɑk/', 'hemlock', 3);
INSERT INTO `words` VALUES (33063, NULL, 'n. 大麻； 由大麻制成的麻醉药', '/hemp | hɛmp/', 'hemp', 3);
INSERT INTO `words` VALUES (33064, 'The cost of transport is a major expense for an industry. Hence factory location is an important consideration.', 'adv. 因此,从此', '/hens | hɛns/', 'hence', 3);
INSERT INTO `words` VALUES (33065, 'multiple sclerosis (henceforth referred to as MS)', 'adv. 今后,自此以后', '/\'hens\'fɔ:θ | hens\'fɔːθ; \'hensfɔːθ | ,hɛns\'fɔrθ/', 'henceforth', 3);
INSERT INTO `words` VALUES (33066, 'It was built for one of the Henderson family, right?', 'n. 亨德森（姓氏）', '/\'hendəsn/', 'Henderson', 3);
INSERT INTO `words` VALUES (33067, 'Janet Jackson\'s new album has been heralded by a massive media campaign.', 'n. 使者; v. 预报, 标志', '/\'her(ə)ld | \'hɛrəld/', 'herald', 3);
INSERT INTO `words` VALUES (33068, 'Sprinkle the dish with chopped fresh herbs.', 'n. 药草, 香草', '/hə:b, ə:b | hɜːb | ɝb/', 'herb', 3);
INSERT INTO `words` VALUES (33069, 'To their surprise, Ms Sagot and Dr Stevens found that all four of the most sociable species are among those forced to use herbaceous plants, and thus to build ramshackle homes.', 'adj. 草本植物的', '/hə:\'beiʃəs, ə:- | hɜː\'beɪʃəs | ɝ\'beʃəs/', 'herbaceous', 3);
INSERT INTO `words` VALUES (33070, 'But water containing the herbicide cannot be released back into the river and it is known that low water levels can harm river ecosystems accustomed to higher levels.', 'n. 除草剂', '/\'hə:bisaid, \'ə:- | \'hɜːbɪsaɪd | \'ɝbɪsaɪd/', 'herbicide', 3);
INSERT INTO `words` VALUES (33071, 'The meat of the herbivore is, in comparison, far more edible , smellwise.', 'n. 草食动物', '/\'hə:bivɔ:, \'ə:- | \'hɜːbɪvɔː | ɝ​bəˌvɔr/', 'herbivore', 3);
INSERT INTO `words` VALUES (33072, 'a herculean task', 'adj. 极困难的,需要大力气的', '/,hə:kju\'li:ən; hə\'ku:liən/', 'herculean', 3);
INSERT INTO `words` VALUES (33073, 'Chobe is also renowned for its large herds of elephant and buffalo.', 'n. 兽群; v. 使集中，把…赶在一起', '/hə:d | hɜːd | hɝd/', 'herd', 3);
INSERT INTO `words` VALUES (33074, 'What are you doing here?', 'adv. 在这里,这时', '/hiə | hɪə | hɪr/', 'here', 3);
INSERT INTO `words` VALUES (33075, 'a hereditary peer', 'adj. 世袭的,遗传的', '/hi\'reditəri | hɪ\'redɪt(ə)rɪ | hə\'rɛdə\'tɛri/', 'hereditary', 3);
INSERT INTO `words` VALUES (33076, 'Heredity is not a factor in causing the cancer.', 'n. 遗传, 形质遗传', '/hi\'rediti | hɪ\'redɪtɪ | hə\'rɛdəti/', 'heredity', 3);
INSERT INTO `words` VALUES (33077, 'the conditions stated herein', 'adv. 在此处, 此中', '/hɪər\'ɪn | ,hɪr\'ɪn/', 'herein', 3);
INSERT INTO `words` VALUES (33078, 'the importance of preserving the national heritage', 'n. 遗产, 继承权', '/\'heritidʒ | \'herɪtɪdʒ | \'hɛrɪtɪdʒ/', 'heritage', 3);
INSERT INTO `words` VALUES (33079, 'Its film industry operates in its own curiously hermetic way.', 'adj. 密封的, 与外界隔绝的', '/hə:\'metik | hɜː\'metɪk | hɝ\'mɛtɪk/', 'hermetic', 3);
INSERT INTO `words` VALUES (33080, 'I\'ve spent the past ten years living like a hermit.', 'n. 隐士, 隐居者', '/\'hə:mit | \'hɜːmɪt | \'hɝmɪt/', 'hermit', 3);
INSERT INTO `words` VALUES (33081, 'He had dared to speak out against injustice, and overnight he became a national hero .', 'n. 英雄', '/\'hiərəu | \'hɪərəʊ | \'hɪro/', 'hero', 3);
INSERT INTO `words` VALUES (33082, 'her heroic efforts to save her family', 'adj. 英雄的, 英勇的', '/hi\'rəuik | hɪ\'rəʊɪk | hə\'roɪk/', 'heroic', 3);
INSERT INTO `words` VALUES (33083, '...individual acts of heroism.', 'n. 英雄品质, 英雄主义', '/\'herəuizəm | \'herəʊɪz(ə)m | \'hɛroɪzəm/', 'heroism', 3);
INSERT INTO `words` VALUES (33084, '...a can of herring.', 'n. 青鱼, 鲱', '/\'herɪŋ | \'hɛrɪŋ/', 'herring', 3);
INSERT INTO `words` VALUES (33085, 'She cut herself on some broken glass.', 'pron. 她自己', '/hɜː\'self | hɝ\'sɛlf/', 'herself', 3);
INSERT INTO `words` VALUES (33086, 'Gail gave me a hesitant little smile.', 'adj. 迟疑的, 犹豫不定的', '/\'hezitənt | \'hezɪt(ə)nt | \'hɛzɪtənt/', 'hesitant', 3);
INSERT INTO `words` VALUES (33087, 'Some parents hesitate to take these steps because they suspect that their child is exaggerating.', 'v. 犹豫, 踌躇', '/\'heziteit | \'hezɪteɪt | \'hɛzɪtet/', 'hesitate', 3);
INSERT INTO `words` VALUES (33088, 'a heterogeneous collection of buildings', 'adj. 异种的, 异质的', '/,hetərəu\'dʒi:njəs | ,het(ə)rə(ʊ)\'dʒiːnɪəs; -\'dʒen- | \'hɛtərə\'dʒinɪəs/', 'heterogeneous', 3);
INSERT INTO `words` VALUES (33089, 'He presses the bolt against a small hexagon tattooed on his forearm. The sizes match.', 'n. 六角形, 六边形', '/\'heksəɡən | \'heksəg(ə)n | \'hɛksəɡɑn/', 'hexagon', 3);
INSERT INTO `words` VALUES (33090, 'Instead it is the Desert Express that pulls in, its nine coaches in smart blue, orange and white livery with large hexagonal windows.', 'adj. 六角形的,六边的', '/hek\'sæɡənəl | hɛk\'sægənl/', 'hexagonal', 3);
INSERT INTO `words` VALUES (33091, 'In its heyday, the studio\'s boast was that it had more stars than there are in heaven.', 'n. 全盛时期', '/\'heidei | \'heɪdeɪ | \'hede/', 'heyday', 3);
INSERT INTO `words` VALUES (33092, 'Dormice hibernate from October to May.', 'v. 冬眠', '/\'haibəneit | \'haɪbəneɪt | \'haɪbɚnet/', 'hibernate', 3);
INSERT INTO `words` VALUES (33093, 'Heart rate tracking for three of the Alaska bears showed a drop from 55 beats per minute on average before hibernation to 14 erratic ones per minute in winter.', 'n. 过冬, 冬眠, 避寒', '/,haibə\'neiʃən/', 'hibernation', 3);
INSERT INTO `words` VALUES (33094, 'A baby may frequently get a bout of hiccups during or soon after a feeding.', 'n. 打嗝; v. 打嗝', '/\'hikʌp, -əp | \'hɪkʌp | \'hɪkəp/', 'hiccup', 3);
INSERT INTO `words` VALUES (33095, 'She keeps a bottle of gin hidden behind a stack of books.', 'v. 躲藏,隐瞒', '/haid | haɪd/', 'hide', 3);
INSERT INTO `words` VALUES (33096, 'a rigid social hierarchy', 'n. 等级制度', '/\'haiə,rɑ:ki | \'haɪərɑːkɪ | \'haɪərɑrki/', 'hierarchy', 3);
INSERT INTO `words` VALUES (33097, 'As for composers, modernists like Béla Bartók were hieratic and formalist, and postmodernists, like John Adams, were playful and interested in deconstructing.', 'adj. 僧侣的, 僧侣用的', '/,haiə\'rætik | ,haɪə\'rætɪk | \'haɪə\'rætɪk/', 'hieratic', 3);
INSERT INTO `words` VALUES (33098, 'Initially the patterns I used were hieroglyph like symbols.', 'n. 象形文字, 图画文字', '/\'haiərəuɡlif | \'haɪ(ə)rəglɪf | \'haɪərəɡlɪf/', 'hieroglyph', 3);
INSERT INTO `words` VALUES (33099, 'The Inca had no system of hieroglyphic writing, as the Maya did, and any portraits that Inca artists may have made of their rulers were lost.', 'n. 象形文字', '/,haiərəu\'ɡlifik | haɪrə\'glɪfɪk | ,haɪərə\'glɪfɪk/', 'hieroglyphic', 3);
INSERT INTO `words` VALUES (33100, 'Once an isolated highland, it has been the home shared by people of more than 10 nationalities, with pure blue sky, clear and beautiful lake as well as the legendary matriarchal community.', 'n. 高地,丘陵地带', '/\'hailənd | \'haɪlənd/', 'highland', 3);
INSERT INTO `words` VALUES (33101, 'Last year Collins wrote a moving ballad which highlighted the plight of the homeless.', 'vt. 强调，突出；以强烈光线照射; n. 最精彩部分', '/\'haɪlaɪt/', 'highlight', 3);
INSERT INTO `words` VALUES (33102, 'Interstate Highway 75', 'n. 公路', '/\'haiwei | \'haɪweɪ | \'haɪwe/', 'highway', 3);
INSERT INTO `words` VALUES (33103, 'a hike in the woods', 'n&v. 徒步旅行', '/haik | haɪk/', 'hike', 3);
INSERT INTO `words` VALUES (33104, 'Their house is on a hill overlooking the sea.', 'n. 小山,丘陵', '/hil | hɪl/', 'hill', 3);
INSERT INTO `words` VALUES (33105, 'Blinking in amazement, the hillbilly drawled, \"I should have brought my wife!', 'n. 山地内部的贫农,乡下人', '/\'hil,bili | \'hɪlbɪlɪ | \'hɪlbɪli/', 'hillbilly', 3);
INSERT INTO `words` VALUES (33106, 'The airplane crashed on a hillside.', 'n. 山腰', '/\'hilsaid | \'hɪlsaɪd | \'hɪl\'saɪd/', 'hillside', 3);
INSERT INTO `words` VALUES (33107, 'The areas where the fighting is taking place are hilly and densely wooded.', 'adj. 多小山的, 多坡的', '/\'hili | \'hɪlɪ | \'hɪli/', 'hilly', 3);
INSERT INTO `words` VALUES (33108, 'Are you in love with him?', 'pron. 他', '/hɪm/', 'him', 3);
INSERT INTO `words` VALUES (33109, 'From the deck of a ship, the island makes a startling apparition, like the Himalaya just emerged from the Flood.', 'n. 喜马拉雅山', '/,himə\'leiə/', 'Himalaya', 3);
INSERT INTO `words` VALUES (33110, 'He repossessed himself of his farm.', 'pron. 他自己', '/hɪm\'self | hɪm\'sɛlf/', 'himself', 3);
INSERT INTO `words` VALUES (33111, 'Suddenly the cow kicked up its hind legs.', 'adj. 后边的,后面的', '/haind | haɪnd/', 'hind', 3);
INSERT INTO `words` VALUES (33112, 'His career has been hindered by injury.', 'v. 阻碍, 打扰', '/\'hində | \'hɪndə | \'hɪndɚ/', 'hinder', 3);
INSERT INTO `words` VALUES (33113, 'The wider the hinge, the further it folds.', 'n. （门、盖等的）铰链', '/hɪn(d)ʒ | hɪndʒ/', 'hinge', 3);
INSERT INTO `words` VALUES (33114, 'There have been hints that he may take up coaching.', 'n. 暗示, 线索', '/hint | hɪnt/', 'hint', 3);
INSERT INTO `words` VALUES (33115, 'the rural hinterland', 'n. 内地, 穷乡僻壤', '/\'hintəlænd | \'hɪntəlænd | \'hɪntɚlænd/', 'hinterland', 3);
INSERT INTO `words` VALUES (33116, 'Still, now we knew for sure where whales came from and that the hippopotamus theory wasn\'t complete science fiction.', 'n. 河马', '/ˌhɪpəˈpɒtəməs | ˌhɪpəˈpɑtəməs/', 'hippopotamus', 3);
INSERT INTO `words` VALUES (33117, 'The best way to explore the island is to hire a car.', 'v. ／n租用，雇用', '/haiə | \'haɪə | \'haɪɚ/', 'hire', 3);
INSERT INTO `words` VALUES (33118, 'Miami’s Hispanic community', 'adj. 西班牙的', '/hi\'spænik/', 'Hispanic', 3);
INSERT INTO `words` VALUES (33119, 'The tyres of Lenny\'s bike hissed over the wet pavement as he slowed down.', 'v. 嘶嘶作声, 用嘘声表示', '/his | hɪs/', 'hiss', 3);
INSERT INTO `words` VALUES (33120, 'I am a historian, and I teach in an American university.', 'n. 历史学家', '/his\'tɔ:riən | hɪ\'stɔːrɪən | hɪ\'stɔrɪən/', 'historian', 3);
INSERT INTO `words` VALUES (33121, 'a historic meeting of world leaders', 'adj. 有历史意义的, 历史的', '/his\'tɔrik | hɪ\'stɒrɪk | hɪ\'stɔrɪk/', 'historic', 3);
INSERT INTO `words` VALUES (33122, 'And historically they acted with that sense of stewardship in mind, thinking of what was appropriate for the whole system and not simply for their firm.', 'adv. 历史上地', '/his\'tɔrikəli | hɪ\'stɒrɪklɪ/', 'historically', 3);
INSERT INTO `words` VALUES (33123, 'He raised the hammer and hit the bell.', 'v. 打，击', '/hit | hɪt/', 'hit', 3);
INSERT INTO `words` VALUES (33124, 'There was no garage in sight, so I hitched a lift into town.', 'v. 搭便车；提起，拉起；拴住; n. 故障， 障碍', '/hɪtʃ/', 'hitch', 3);
INSERT INTO `words` VALUES (33125, 'a species of fish hitherto unknown in the West', 'adv. 迄今,至今', '/,hiðə\'tu: | hɪðə\'tuː; \'hɪðətuː | ,hɪðɚ\'tu/', 'hitherto', 3);
INSERT INTO `words` VALUES (33126, 'The most important member of any hive is the queen bee.', 'n. 蜂房; v. (使)入蜂箱, 群居', '/haiv | haɪv/', 'hive', 3);
INSERT INTO `words` VALUES (33127, 'families who hoarded food during the strike', 'v. 贮藏，囤积; n. 储藏， 贮存', '/hɔːrd | hɔrd/', 'hoard', 3);
INSERT INTO `words` VALUES (33128, 'What are your hobbies?', 'n. 业余爱好', '/\'hɔbi | \'hɒbɪ | \'hɑbi/', 'hobby', 3);
INSERT INTO `words` VALUES (33129, '...a new hockey arena.', 'n. 曲棍球', '/\'hɑːki | \'hɑki/', 'hockey', 3);
INSERT INTO `words` VALUES (33130, 'I have to feed the chickens and hoe the potatoes.', 'vt. 用锄头锄; n. 锄头', '/hou | ho/', 'hoe', 3);
INSERT INTO `words` VALUES (33131, 'The hohokam culture disintegrated as they had difficulty maintaining the canals in the dry conditions of the drought.', 'adj. 霍霍坎文化的', '/həu\'həukɑ:m/', 'hohokam', 3);
INSERT INTO `words` VALUES (33132, 'the 800 m world record holder', 'n. 持有者, 占有者', '/\'həuldə | \'həʊldə | \'holdɚ/', 'holder', 3);
INSERT INTO `words` VALUES (33133, NULL, 'n. 保持，固定', '/\'həuldiŋ | \'həʊldɪŋ | \'holdɪŋ/', 'holding', 3);
INSERT INTO `words` VALUES (33134, 'I began digging a hole for the plant.', 'n. 洞,孔; v. 凿洞', '/həul | həʊl | hol/', 'hole', 3);
INSERT INTO `words` VALUES (33135, 'The school holidays start tomorrow.', 'n. 假日', '/\'hɔlədi | \'hɒlɪdeɪ; -dɪ | \'hɑləde/', 'holiday', 3);
INSERT INTO `words` VALUES (33136, 'a holistic approach to design', 'adj. 整体的， 全面的； 功能整体性的', '/hou\'lɪstɪk | ho\'lɪstɪk/', 'holistic', 3);
INSERT INTO `words` VALUES (33137, 'Have you ever been to Holland?', 'n. 荷兰', '/\'hɔlənd | \'hɒlənd | \'hɑlənd/', 'Holland', 3);
INSERT INTO `words` VALUES (33138, 'a hollow tree', 'n. 洞, 窟窿; v. 挖空,弄凹', '/\'hɔləu | \'hɒləʊ | \'hɑlo/', 'hollow', 3);
INSERT INTO `words` VALUES (33139, '...a major Hollywood studio.', 'n. 好莱坞', '/\'hɔliwud | ˈhɒlɪˌwʊd | ˈhɑliˌwʊd/', 'Hollywood', 3);
INSERT INTO `words` VALUES (33140, NULL, 'n. (河，湖中的)小岛', '/həʊm/', 'holm', 3);
INSERT INTO `words` VALUES (33141, NULL, 'n&a. [地]全新世(的)', '/\'hɔləsi:n/', 'holocene', 3);
INSERT INTO `words` VALUES (33142, 'the holy city of Varanasi', 'adj. 神圣的, 圣洁的', '/[\'həuli] | \'həʊlɪ | \'holi/', 'holy', 3);
INSERT INTO `words` VALUES (33143, 'The film pays homage to Martin Scorsese’s ‘Mean Streets’.', 'n. 尊敬， 敬意', '/\'hɑːmɪdʒ | \'hɑmɪdʒ/', 'homage', 3);
INSERT INTO `words` VALUES (33144, 'They have a beautiful home in California.', 'n. 家(乡)', '/həum | həʊm | hom/', 'home', 3);
INSERT INTO `words` VALUES (33145, 'Many are planning to return to their homeland.', 'n. 祖国,本国', '/\'həumlænd | \'həʊmlænd | \'homlænd/', 'homeland', 3);
INSERT INTO `words` VALUES (33146, 'Thousands of people have been made homeless .', 'adj. 无家的, 无家可归的', '/\'həumlis | \'həʊmlɪs | \'homləs/', 'homeless', 3);
INSERT INTO `words` VALUES (33147, 'Mrs Keane is a comfortable, homely person.', 'adj. 家常的,平凡的', '/\'həumli | \'həʊmlɪ | \'homli/', 'homely', 3);
INSERT INTO `words` VALUES (33148, 'Whether you are a carpenter or a therapist, a homemaker or a professor, it makes no difference.', 'n. 主妇', '/\'həum,meikə | \'həʊmmeɪkə(r) | \'hommekɚ/', 'homemaker', 3);
INSERT INTO `words` VALUES (33149, 'Titus 2 instructs older women to mentor younger women, and teach them to care for their husbands and children and homemaking responsibilities.', 'n. 家政', '/\'həum,meikiŋ/', 'homemaking', 3);
INSERT INTO `words` VALUES (33150, 'An organism that generates heat to maintain its body temperature, typically above the temperature of its surroundings; a homeotherm.', 'n. <主美>恒温动物', '/\'həumiəθə:m/', 'homeotherm', 3);
INSERT INTO `words` VALUES (33151, 'And all of us will pay an even steeper price if we allow this crisis to continue to deepen, a crisis which is unraveling homeownership, the middle class, and the American Dream itself.', 'n. 房主', NULL, 'homeownership', 3);
INSERT INTO `words` VALUES (33152, 'She\'s feeling a little homesick.', 'adj. 想家的,思乡病的', '/\'həumsik | \'həʊmsɪk | \'homsɪk/', 'homesick', 3);
INSERT INTO `words` VALUES (33153, NULL, 'n. 手织物', '/\'həumspʌn | \'həʊmspʌn | \'homspʌn/', 'homespun', 3);
INSERT INTO `words` VALUES (33154, 'He looked around, not just up the road but toward the homestead and edge of the woods.', 'n. 家宅，宅基', '/\'həumsted | \'həʊmsted | \'homstɛd/', 'homestead', 3);
