INSERT INTO `words` VALUES (33191, 'The local people were very kind and hospitable.', 'adj. 好客的, 宜人的', '/hɔ\'spitəbl, \'hɔspitəbl | hɒ\'spɪtəb(ə)l; \'hɒspɪt- | hɑ\'spɪtəbl/', 'hospitable', 3);
