INSERT INTO `words` VALUES (33193, 'Most people do not have to be hospitalized for asthma or pneumonia.', 'v. 就医, 使住院', '/\'hɔspitəlaiz | \'hɒspɪt(ə)laɪz | \'hɑspɪtə\'laɪz/', 'hospitalize', 3);
