INSERT INTO `words` VALUES (33229, 'Try to satisfy your hunger by eating some fruit.', 'n. 饥饿, 欲望', '/\'hʌŋɡə | \'hʌŋgə | \'hʌŋɡɚ/', 'hunger', 3);
