INSERT INTO `words` VALUES (33245, 'The team believes one of the most important factors is hydration - the way skin collects and retains moisture.', 'n. 水合作用', '/hai\'dreiʃən | haɪ\'dreɪʃən | haɪ\'dreʃən/', 'hydration', 3);
