INSERT INTO `words` VALUES (33251, 'While evaporation from the oceans is the primary vehicle for driving the surface-to-atmosphere portion of the hydrologic cycle, transpiration is also significant.', 'adj. 水文的', NULL, 'hydrologic', 3);
INSERT INTO `words` VALUES (33252, 'The theme addresses the role of forests and trees outside forests to help moderate soil, hydrological and aquatic systems.', 'adj. 水文学的', '/,haidrə\'lɔdʒikəl/', 'hydrological', 3);
INSERT INTO `words` VALUES (33253, 'And for those who prefer a healthier diet there is also a hydroponic greenhouse where fresh vegetables will grow all year round.', 'adj. 溶液培养的', '/,haidrəu\'pɔnik | ,haɪdrə\'pɑnɪk/', 'hydroponic', 3);
INSERT INTO `words` VALUES (33254, NULL, 'n. 水耕法, 水栽培', NULL, 'hydroponically', 3);
INSERT INTO `words` VALUES (33255, 'If we do it ourselves, only cheap energy from hydropower will do.', 'n. 水力发出的电力', '/\'haɪdrə(ʊ)paʊə | \'haɪdro,paʊɚ/', 'hydropower', 3);
INSERT INTO `words` VALUES (33256, 'Geosphere, hydrosphere and atmosphere are fluids in motion; their main difference is their viscosity.', 'n. 水圈, 水气', '/\'haidrəusfiə | \'haɪdrəsfɪə | \'haɪdrosfɪr/', 'hydrosphere', 3);
INSERT INTO `words` VALUES (33257, 'Banpo antimony deposit is a typical fracture - controlling and hydrothermal fluid filling deposit.', 'adj. 热液的', '/ˌhaɪdrə\'θɜːml | ,haɪdrə\'θɝml/', 'hydrothermal', 3);
INSERT INTO `words` VALUES (33258, 'Manufacturing the screws out of the hydroxyapatite composite also simplifies production.', 'n. [矿]羟磷灰石', '/hai,drɔksi\'æpətait/', 'hydroxyapatite', 3);
