INSERT INTO `words` VALUES (33262, 'Student teachers were hypersensitive to any criticism of their performance.', 'adj. 过份敏感的', '/,haipə\'sensətiv | haɪpə\'sensɪtɪv | ,haɪpɚ\'sɛnsətɪv/', 'hypersensitive', 3);
INSERT INTO `words` VALUES (33263, '...information embroidered with colourful graphics and tied together by hypertext links.', 'n. 超文本', '/\'haɪpərtekst | \'haɪpɚ\'tɛkst/', 'hypertext', 3);
INSERT INTO `words` VALUES (33264, 'The state in certain fungi in which each compartment of a hypha contains two nuclei, each derived from a different parent.', 'n. [植]菌丝', '/\'haifə | \'haɪfə/', 'hypha', 3);
INSERT INTO `words` VALUES (33265, 'It would be hypocritical to say I travel at 70 mph simply because that is the law.', 'adj. 伪善的， 虚伪的', '/ˌhɪpə\'krɪtɪkl | ,hɪpə\'krɪtɪkl/', 'hypocritical', 3);
