INSERT INTO `words` VALUES (33267, 'One hypothesis is that the victim fell asleep while driving.', 'n. 假设', '/hai\'pɔθisis | haɪ\'pɒθɪsɪs | haɪ\'pɑθəsɪs/', 'hypothesis', 3);
INSERT INTO `words` VALUES (33268, 'To explain this, they hypothesize that galaxies must contain a great deal of missing matter which cannot be detected.', 'v. 假设,猜测', '/hai\'pɔθisaiz | haɪ\'pɒθɪsaɪz | haɪ\'pɑθəsaɪz/', 'hypothesize', 3);
INSERT INTO `words` VALUES (33269, 'The question is purely hypothetical .', 'adj. 假说的，臆说的', '/,haipəu\'θetikəl | ,haɪpə\'θetɪk(ə)l | ,haɪpə\'θɛtɪkl/', 'hypothetical', 3);
INSERT INTO `words` VALUES (33270, 'Other common forms of synecdoche include two concentric circles or triangles (used as eyes in horse and bison paintings), ibex horns and the hump of a mammoth.', 'n. 野生山羊', '/\'aibeks | \'aɪbeks | \'aɪbɛks/', 'ibex', 3);
INSERT INTO `words` VALUES (33271, NULL, 'n. 冰山,冷若冰霜的人', '/\'aisbə:ɡ | \'aɪsbɜːg | \'aɪs\'bɝg/', 'iceberg', 3);
INSERT INTO `words` VALUES (33272, NULL, 'n. 冷藏库', '/\'aisbɔks | \'aɪsbɒks | \'aɪsbɑks/', 'icebox', 3);
INSERT INTO `words` VALUES (33273, 'WHICH country will be the next Iceland?', 'n. 冰岛(欧洲岛名,在大西洋北部,近北极圈)', '/\'aislənd/', 'Iceland', 3);
INSERT INTO `words` VALUES (33274, 'Fossil forensics has now identified the most likely culprit: another ichthyosaur.', 'n. 鱼龙', '/\'ikθiəsɔ:(r) | \'ɪkθɪəsɔː | \'ɪkθɪə,sɔr/', 'ichthyosaur', 3);
INSERT INTO `words` VALUES (33275, 'Missis walked in\', she said, `as chill as an icicle, and as high as a princess.', 'n. 冰柱', '/\'aisikl | \'aɪsɪk(ə)l | \'aɪsɪkl/', 'icicle', 3);
INSERT INTO `words` VALUES (33276, 'To open a new file, click on the icon.', 'n. 图标, 肖像', '/\'aikɔn | \'aɪkɒn; -k(ə)n | \'aɪkɑn/', 'icon', 3);
INSERT INTO `words` VALUES (33277, NULL, 'adj. 肖像的, 图像材料的', '/ai,kɔnə\'ɡræfik/', 'iconographic', 3);
INSERT INTO `words` VALUES (33278, NULL, 'n. 肖像学, 肖像画法', '/,aikɔ\'nɔɡrəfi | ,aɪkə\'nɒgrəfɪ | \'aɪkə\'nɑgrəfi/', 'iconography', 3);
INSERT INTO `words` VALUES (33279, 'an icy wind', 'adj. 冰冷的, 冷淡的', '/\'aisi | \'aɪsɪ | \'aɪsi/', 'icy', 3);
INSERT INTO `words` VALUES (33280, NULL, 'abbr. 身份 (identification, identity); n. 遗传素质', '/ɪd/', 'ID', 3);
INSERT INTO `words` VALUES (33281, 'Walt Disney stayed true to his ideals.', 'n. 理想; adj. 理想的,完美的', '/ai\'diəl | aɪ\'dɪəl; aɪ\'diːəl | aɪ\'diəl/', 'ideal', 3);
INSERT INTO `words` VALUES (33282, 'idealistic young doctors', 'adj. 理想主义的, 空想的', '/ai,diə\'listik,-kəl | ,aɪdɪə\'lɪstɪk; aɪ,dɪə\'lɪstɪk; aɪ,diːə\'lɪstɪk/', 'idealistic', 3);
INSERT INTO `words` VALUES (33283, 'Others — cosmology, for example — make hypotheses that are more remote from everyday causes, and involve a high level of mathematical abstraction and idealization.', 'n. 理想化, 理想化的事物', '/ai\'diəlai\'zeiʃən, -li\'z-/', 'idealization', 3);
INSERT INTO `words` VALUES (33284, 'Society continues to idealize the two-parent family.', 'vt. 将…理想化', '/aɪ\'diːəlaɪz | aɪ\'diə\'laɪz/', 'idealize', 3);
INSERT INTO `words` VALUES (33285, 'four identical houses', 'adj. 同一的,相同的', '/ai\'dentikəl | aɪ\'dentɪk(ə)l | aɪ\'dɛntɪkl/', 'identical', 3);
INSERT INTO `words` VALUES (33286, 'In the corridor were four dirty, ragged bundles, just identifiable as human beings.', 'adj. 可辨认的', '/ai\'dentifaiəbl | aɪdentɪ\'fæɪəb(ə)l | aɪ,dɛntɪ\'faɪəbl/', 'identifiable', 3);
INSERT INTO `words` VALUES (33287, 'His body was taken to Brighton mortuary for identification.', 'n. 辨认, 鉴定', '/ai,dentifi\'keiʃən | aɪ,dentɪfɪ\'keɪʃ(ə)n | aɪˌdentɪfɪ\'keʃn/', 'identification', 3);
INSERT INTO `words` VALUES (33288, 'He was too far away to be able to identify faces.', 'v. 识别,鉴定', '/aɪ\'dentɪfaɪ | aɪ\'dɛntɪfaɪ/', 'identify', 3);
INSERT INTO `words` VALUES (33289, 'The identity of the killer is still unknown.', 'n. 一致, 身份, 特征', '/ai\'dentəti | aɪ\'dentɪtɪ | aɪ\'dɛntəti/', 'identity', 3);
INSERT INTO `words` VALUES (33290, 'The party is split by ideological differences.', 'adj. 意识形态的', '/,aidiəu\'lɔdʒikəl, ,id:-,-ik | ,aɪdɪəʊ\'lɒdʒɪkəl | ,aɪdɪə\'lɑdʒɪkl/', 'ideological', 3);
INSERT INTO `words` VALUES (33291, NULL, 'adv. 意识形态上地, 思想上地', '/,aidiə\'lɔdʒikali/', 'ideologically', 3);
INSERT INTO `words` VALUES (33292, 'the ideologies of fascism and terrorism', 'n. 意识形态', '/,aidi\'ɔlədʒi, ,idi- | ,aɪdɪ\'ɒlədʒɪ; ɪd-/', 'ideology', 3);
INSERT INTO `words` VALUES (33293, NULL, 'adj. 观念运动的', '/ˌaɪdiə\'moutər | ɪdɪə\'motɚ/', 'ideomotor', 3);
INSERT INTO `words` VALUES (33294, 'the new musical idiom', 'n. 成语, 方言', '/\'idiəm | \'ɪdɪəm/', 'idiom', 3);
INSERT INTO `words` VALUES (33295, 'He had the ability to write fluent and idiomatic English.', 'adj. 地道的 成语的', '/,idiə\'mætik | ,ɪdɪə\'mætɪk/', 'idiomatic', 3);
INSERT INTO `words` VALUES (33296, 'I cannot afford to leave the land lying idle.', 'adj. 空闲的,懒惰的; v. 虚度, 闲散', '/\'aidl | \'aɪd(ə)l | \'aɪdl/', 'idle', 3);
INSERT INTO `words` VALUES (33297, 'It was an attractive hope that the high technology of our society might be wrested from the grip of benighted forces and used to restore us to an idyllic natural state.', 'adj. 田园短诗的, 牧歌的', '/ɪ\'dɪlɪk | aɪ\'dɪlɪk/', 'idyllic', 3);
INSERT INTO `words` VALUES (33298, 'Defining the town center of Râmnicu Vâlcea is a towering shopping mall that looks like a giant glass igloo.', 'n. 圆顶建筑', '/\'iɡlu: | \'ɪgluː | \'ɪglʊ/', 'igloo', 3);
INSERT INTO `words` VALUES (33299, 'The Great Dyke of Zimbabwe is a layered mafic intrusion of igneous, metal-bearing rock that has been dated to approximately 2.5 billion years old.', 'adj. (指岩石)火成的, 火的', '/\'iɡniəs | \'ɪgnɪəs/', 'igneous', 3);
INSERT INTO `words` VALUES (33300, 'The petrol tank suddenly ignited.', 'v. 点火', '/iɡ\'nait | ɪg\'naɪt | ɪɡ\'naɪt/', 'ignite', 3);
INSERT INTO `words` VALUES (33301, 'The device automatically disconnects the ignition.', 'n. 点火, 点燃', '/iɡ\'niʃən | ɪg\'nɪʃ(ə)n | ɪɡ\'nɪʃən/', 'ignition', 3);
INSERT INTO `words` VALUES (33302, 'Excuse my ignorance, but how does it actually work?', 'n. 无知', '/\'iɡnərəns | \'ɪgn(ə)r(ə)ns | \'ɪɡnərəns/', 'ignorance', 3);
INSERT INTO `words` VALUES (33303, 'an ignorant and uneducated man', 'adj. 无知的', '/\'iɡnərənt | \'ɪgn(ə)r(ə)nt | \'ɪɡnərənt/', 'ignorant', 3);
INSERT INTO `words` VALUES (33304, 'You can’t ignore the fact that many criminals never go to prison.', 'v. 不理睬, 忽视', '/iɡ\'nɔ: | ɪg\'nɔː | ɪɡ\'nɔr/', 'ignore', 3);
INSERT INTO `words` VALUES (33305, 'Bridget can’t come – she’s ill.', 'adj. 有病的,坏的', '/il | ɪl/', 'ill', 3);
INSERT INTO `words` VALUES (33306, 'His handwriting is totally illegible.', 'adj. 难以辨认的， 模糊的', '/ɪ\'ledʒəbl | ɪ\'lɛdʒəbl/', 'illegible', 3);
INSERT INTO `words` VALUES (33307, 'This year, No Child Left Behind requires 77.5 percent of Illinois students to meet or exceed standards.', 'n. 伊利诺斯州(美国州名)', '/,ili\'nɔi(z)/', 'Illinois', 3);
INSERT INTO `words` VALUES (33308, '...a subclass of illiterates.', 'n. 文盲 a不识字的', '/i\'litərət | ɪ\'lɪt(ə)rət | ɪ\'lɪtərət/', 'illiterate', 3);
INSERT INTO `words` VALUES (33309, 'She had all the normal childhood illnesses.', 'n. 疾病, 生病', '/\'ilnis | ˈɪlnəs | \'ɪlnəs/', 'illness', 3);
INSERT INTO `words` VALUES (33310, 'A single candle illuminated his face.', 'v. 照明,阐释, 说明', '/i\'lju:mineit | ɪ\'l(j)uːmɪneɪt | ɪ\'lumɪnet/', 'illuminate', 3);
INSERT INTO `words` VALUES (33311, 'The only illumination came from a small window high in the opposite wall.', 'n. 阐明, 启发', '/i,lju:mi\'neiʃən | ɪ,ljuːmɪ\'neɪʃən | ɪ\'lʊmə\'neʃən/', 'illumination', 3);
INSERT INTO `words` VALUES (33312, 'She was under no illusion that he loved her.', 'n. 幻想', '/i\'lju:ʒən | ɪ\'l(j)uːʒ(ə)n | ɪ\'luʒn/', 'illusion', 3);
INSERT INTO `words` VALUES (33313, 'First impressions can often prove illusory.', 'adj. 虚幻的', '/i\'lju:səri | ɪ\'l(j)uːs(ə)rɪ | ɪ\'lusəri/', 'illusory', 3);
INSERT INTO `words` VALUES (33314, 'Let me give an example to illustrate the point.', 'v. 说明,阐明', '/\'iləstreit | \'ɪləstreɪt | \'ɪləstret/', 'illustrate', 3);
INSERT INTO `words` VALUES (33315, 'An illustration of China\'s dynamism is that a new company is formed in Shanghai every 11 seconds.', 'n. 说明, 例证', '/,ilə\'streiʃən | ɪlə\'streɪʃ(ə)n | ,ɪlə\'streʃən/', 'illustration', 3);
INSERT INTO `words` VALUES (33316, 'graphics and other illustrative material', 'adj. 作为例证的； 用做说明的； 解释性的', '/ɪ\'ləstrətɪv | ɪ\'lʌstrətɪv/', 'illustrative', 3);
INSERT INTO `words` VALUES (33317, 'Called up for military service, Mr. Marokvia spent the war as an illustrator for the Wehrmacht, applying brush and pencil in Ukraine, Italy, Finland and Yugoslavia.', 'n. 插图画家,说明者', '/\'iləstreitə | \'ɪləstreɪtə | \'ɪləstretɚ/', 'illustrator', 3);
INSERT INTO `words` VALUES (33318, 'He had the clearest image in his mind of his mother and father.', 'n. 形象， 印象； 画像； 影像， 映像； 意象， 比喻', '/\'ɪmɪdʒ/', 'image', 3);
INSERT INTO `words` VALUES (33319, 'Their dreams commonly involved complex stories with visual imagery.', 'n. 意象, 肖像', '/\'imidʒəri | \'ɪmɪdʒ(ə)rɪ | \'ɪmɪdʒəri/', 'imagery', 3);
INSERT INTO `words` VALUES (33320, 'As she listened, she played an imaginary piano on her knees.', 'adj. 假想的,虚构的', '/i\'mædʒinəri | ɪ\'mædʒɪn(ə)rɪ | ɪ\'mædʒɪnɛri/', 'imaginary', 3);
INSERT INTO `words` VALUES (33321, 'a storyteller with an incredible imagination', 'n. 想象(力)', '/i,mædʒi\'neiʃən | ɪ,mædʒɪ\'neɪʃ(ə)n | ɪ,mædʒɪ\'neʃən/', 'imagination', 3);
INSERT INTO `words` VALUES (33322, 'an imaginative use of computer technology', 'adj. 富有想象力的', '/ɪ\'mædʒɪnətɪv/', 'imaginative', 3);
INSERT INTO `words` VALUES (33323, 'He could not imagine a more peaceful scene.', 'v. 想象,设想', '/i\'mædʒin | ɪ\'mædʒɪn/', 'imagine', 3);
INSERT INTO `words` VALUES (33324, 'Much subsequent poetry in england was influenced by imagist lord and practice .', 'n&a. 意像派者(的)', '/\'imidʒist/', 'imagist', 3);
INSERT INTO `words` VALUES (33325, 'a hormonal imbalance', 'n. 不平衡,不均衡', '/,im\'bæləns | ɪm\'bæl(ə)ns | ɪm\'bæləns/', 'imbalance', 3);
INSERT INTO `words` VALUES (33326, 'She had imbibed the traditions of her family.', 'v. 吸收', '/im\'baib | ɪm\'baɪb/', 'imbibe', 3);
INSERT INTO `words` VALUES (33327, 'She was a splendid mimic and loved to imitate Winston Churchill.', 'v. 模仿,仿制', '/\'imiteit | \'ɪmɪteɪt | \'ɪmɪtet/', 'imitate', 3);
INSERT INTO `words` VALUES (33328, 'The remake of ‘Casablanca’ was a pale imitation (= something that is much less good than the thing it imitates ) of the original movie.', 'n. 模仿, 效法', '/,imi\'teiʃən | ɪmɪ\'teɪʃ(ə)n | ,ɪmɪ\'teʃən/', 'imitation', 3);
INSERT INTO `words` VALUES (33329, 'Young people might be provoked into imitative crime by the exploits they see on TV.', 'adj. 仿制的,模仿的', '/\'imitətiv | \'ɪmɪtətɪv | \'ɪmɪtetɪv/', 'imitative', 3);
INSERT INTO `words` VALUES (33330, 'He doesn\'t take chances; that\'s why he\'s survived and most of his imitators haven\'t.', 'n. 模仿者', '/\'imiteitə（r） | \'ɪmɪtetɚ/', 'imitator', 3);
INSERT INTO `words` VALUES (33331, 'He forgave his son’s immature behaviour.', 'adj. 不成熟的, 未完全发展的', '/,imə\'tjuə | ,ɪmə\'tjʊə; ,ɪmə\'tjɔː | ,ɪmə\'tʃʊr/', 'immature', 3);
INSERT INTO `words` VALUES (33332, 'Photographs of the boy showed his physical immaturity.', 'n. 不成熟', '/imə\'tjuəriti | ,ɪmə\'tʃɔːrɪtɪ; ,ɪmə\'tʃʊərɪtɪ; ,ɪmə\'tjɔːrɪtɪ; ,ɪmə\'tjʊərɪtɪ | ɪmə\'tjʊrəti/', 'immaturity', 3);
INSERT INTO `words` VALUES (33333, 'They have improved immeasurably since their arrival.', 'adv. 无法计量地, 无限地', '/i\'meʒərəbli | ɪ\'mɛʒərəbli/', 'immeasurably', 3);
INSERT INTO `words` VALUES (33334, 'Our immediate response to the attack was sheer horror.', 'adj. 直接的, 立即的', '/i\'mi:diət | ɪ\'miːdɪət | ɪ\'midɪət/', 'immediate', 3);
INSERT INTO `words` VALUES (33335, 'People who travel by rail still read an immense amount.', 'adj. 极广大的, 无边的,', '/i\'mens | ɪ\'mens | ɪ\'mɛns/', 'immense', 3);
INSERT INTO `words` VALUES (33336, 'If you don\'t want to think about anything, just sit there silently and count your breaths - this will help you immensely as well.', 'adv. 极大地,无限地', '/i\'mensli | ɪ\'menslɪ/', 'immensely', 3);
INSERT INTO `words` VALUES (33337, 'The electrodes are immersed in liquid.', 'v. 沉浸, 使陷入', '/i\'mə:s | ɪ\'mɜːs | ɪ\'mɝs/', 'immerse', 3);
INSERT INTO `words` VALUES (33338, '...long-term assignments that allowed them total immersion in their subjects.', 'n. 沉浸,专心', '/i\'mə:ʃən | ɪ\'mɜːʃ(ə)n | ɪ\'mɝʃən/', 'immersion', 3);
INSERT INTO `words` VALUES (33339, 'an illegal immigrant', 'n. 移民,侨民', '/\'imiɡrənt | \'ɪmɪgr(ə)nt | \'ɪmɪɡrənt/', 'immigrant', 3);
INSERT INTO `words` VALUES (33340, 'His father and mother immigrated when he was two.', 'v. 移入', '/\'imiɡreit | \'ɪmɪgreɪt | \'ɪmɪɡret/', 'immigrate', 3);
INSERT INTO `words` VALUES (33341, 'He called for a common European policy on immigration.', 'n. 移民入境', '/,imi\'ɡreiʃən | ɪmɪ\'ɡreɪʃn | ,ɪmɪ\'ɡreʃən/', 'immigration', 3);
INSERT INTO `words` VALUES (33342, 'A new trade agreement is imminent.', 'adj. 逼近的, 即将发生的', '/\'iminənt | \'ɪmɪnənt/', 'imminent', 3);
INSERT INTO `words` VALUES (33343, 'She could see a figure sitting immobile, facing the sea.', 'adj. 不动的, 静止的', '/i\'məubail, -bi:l | ɪ\'məʊbaɪl | ɪ\'mobl/', 'immobile', 3);
INSERT INTO `words` VALUES (33344, 'This is due to a stagnation of blood in the veins caused by prolonged immobility, which can promote blood clot formation in veins.', 'n. 牢固,不动', '/i,məu\'biləti/', 'immobility', 3);
INSERT INTO `words` VALUES (33345, 'The broken limb must be immobilized immediately.', 'v. 固定不动', '/i\'məubilaiz | ɪ\'məʊbɪlaɪz | ɪ\'mobə\'laɪz/', 'immobilize', 3);
INSERT INTO `words` VALUES (33346, 'Once we’ve had the disease, we’re immune for life.', 'adj. 免疫的', '/i\'mju:n | ɪ\'mjuːn | ɪ\'mjʊn/', 'immune', 3);
INSERT INTO `words` VALUES (33347, 'To protect you against small pox or diphtheria, you are vaccinated with a small amount of the toxin, and then your body develops immunity against that toxin.', 'n. 免疫性', '/i\'mju:nəti | ɪ\'mjuːnɪtɪ | ɪ\'mjʊnəti/', 'immunity', 3);
INSERT INTO `words` VALUES (33348, 'This decision should not be seen as immutable.', 'adj. 不变的,不可变的', '/i\'mju:təbl | ɪ\'mjuːtəb(ə)l | ɪ\'mjutəbl/', 'immutable', 3);
INSERT INTO `words` VALUES (33349, 'Such schemes mean little unless they impact people.', 'v. 影响； 冲击， 撞击; n. 影响； 冲击， 撞击', '/\'ɪmpækt | ɪm\'pækt/', 'impact', 3);
INSERT INTO `words` VALUES (33350, 'The illness had impaired his ability to think and concentrate.', 'v. 损害,削弱', '/im\'pεə | ɪm\'peə | ɪm\'pɛr/', 'impair', 3);
INSERT INTO `words` VALUES (33351, 'She had information that she couldn’t wait to impart.', 'v. 传授, 赋予, 告知', '/im\'pɑ:t | ɪm\'pɑːt | ɪm\'pɑrt/', 'impart', 3);
INSERT INTO `words` VALUES (33352, 'If she gets the nod, Kagan says she will consider every case impartially and with commitment to principle.', 'adv. 公平地,无私地', '/im\'pa:ʃəli/', 'impartially', 3);
INSERT INTO `words` VALUES (33353, 'One thing I’ve noticed is that when people have to wait, they become impatient or uncomfortable.', 'adj. 焦躁的,不耐心的', '/im\'peiʃənt | ɪm\'peɪʃ(ə)nt | ɪm\'peʃnt/', 'impatient', 3);
INSERT INTO `words` VALUES (33354, 'Storms at sea impeded our progress.', 'vt. 妨碍， 阻碍， 阻止', '/ɪm\'piːd | ɪm\'pid/', 'impede', 3);
INSERT INTO `words` VALUES (33355, 'a speech impediment', 'n. 妨碍,口吃, 障碍物', '/im\'pedimənt | ɪm\'pedɪm(ə)nt | ɪm\'pɛdɪmənt/', 'impediment', 3);
INSERT INTO `words` VALUES (33356, '...the courage and competitiveness which impels him to take risks.', 'vt. 驱使， 促使', '/ɪm\'pel | ɪm\'pɛl/', 'impel', 3);
INSERT INTO `words` VALUES (33357, NULL, 'v. 迫近，逼近', '/im\'pend | ɪm\'pend | ɪmˈpɛnd/', 'impend', 3);
INSERT INTO `words` VALUES (33358, 'On the morning of the expedition, I awoke with a feeling of impending disaster.', 'adj. 即将发生的， 迫近的', '/ɪm\'pendɪŋ | ɪm\'pɛndɪŋ/', 'impending', 3);
INSERT INTO `words` VALUES (33359, 'The trees formed a dark and impenetrable barrier.', 'adj. 不能穿过的, 不可理喻的', '/im\'penitrəbl | ɪm\'penɪtrəb(ə)l | ɪm\'pɛnɪtrəbl/', 'impenetrable', 3);
INSERT INTO `words` VALUES (33360, 'It is imperative that politicians should be good communicators.', 'n. 命令,祈使语气; adj. 命令的,强制的', '/ɪm\'perətɪv | ɪm\'pɛrətɪv/', 'imperative', 3);
INSERT INTO `words` VALUES (33361, 'the imperfect world we live in', 'adj. 有缺点的,未完成的; n. 未完成体', '/im\'pə:fikt | ɪm\'pɜːfɪkt | ɪm\'pɝfɪkt/', 'imperfect', 3);
INSERT INTO `words` VALUES (33362, 'Britain’s imperial expansion in the 19th century', 'adj. 帝国的，帝王的', '/im\'piəriəl | ɪm\'pɪərɪəl | ɪm\'pɪrɪəl/', 'imperial', 3);
INSERT INTO `words` VALUES (33363, 'So why then do we reject the impermanence of the ever-changing universe when it comes to our own lives?', 'n. 暂时, 无常', '/im\'pə:mənəns,-nənsi/', 'impermanence', 3);
INSERT INTO `words` VALUES (33364, 'No paint is impermeable to water vapour.', 'adj. 不能渗透的', '/im\'pə:miəbl | ɪm\'pɜːmɪəb(ə)l | ɪm\'pɝmɪəbl/', 'impermeable', 3);
INSERT INTO `words` VALUES (33365, 'Business letters do not have to be impersonal and formal.', 'adj. 客观的,没有人情味的', '/im\'pə:sənəl | ɪm\'pɜːs(ə)n(ə)l | ɪm\'pɝsnl/', 'impersonal', 3);
INSERT INTO `words` VALUES (33366, 'Convinced of his own righteousness, he was the perfect impersonation of a man of rectitude.', 'n. 扮演', '/im,pə:sə\'neiʃən/', 'impersonation', 3);
INSERT INTO `words` VALUES (33367, 'impervious volcanic rock', 'adj. 不透的；不受影响的', '/im\'pə:viəs | ɪm\'pɜːvɪəs | ɪm\'pɝvɪəs/', 'impervious', 3);
INSERT INTO `words` VALUES (33368, 'The discovery gave fresh impetus to the research.', 'n. 推动力, 促进', '/\'impitəs | \'ɪmpɪtəs/', 'impetus', 3);
INSERT INTO `words` VALUES (33369, '...the cuts in defence spending that have impinged on two of the region\'s largest employers.', 'v. 撞击', '/im\'pindʒ | ɪm\'pɪn(d)ʒ | ɪm\'pɪndʒ/', 'impinge', 3);
INSERT INTO `words` VALUES (33370, 'It’s not entirely implausible that a galaxy could be identical to our own.', 'adj. 难信的, 似乎不合情理的', '/im\'plɔ:zəbl | ɪm\'plɔːzɪb(ə)l | ɪm\'plɔzəbl/', 'implausible', 3);
INSERT INTO `words` VALUES (33371, 'The government promised to implement a new system to control financial loan institutions.', 'v. 履行,实施; n. 工(器,用)具', '/\'implimənt, \'impliment | \'ɪmplɪm(ə)nt | \'ɪmplɪmɛnt/', 'implement', 3);
INSERT INTO `words` VALUES (33372, 'If I now scroll down to the actual implementation, now does this work or not work?', 'n. 执行', '/,implimen\'teiʃən | ɪmplɪmen\'teɪʃ(ə)n/', 'implementation', 3);
INSERT INTO `words` VALUES (33373, 'The allegations implicated Abe to such an extent he was forced to resign.', 'v. 含意, 暗示', '/\'implikeit | \'ɪmplɪkeɪt | \'ɪmplɪket/', 'implicate', 3);
INSERT INTO `words` VALUES (33374, 'They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.', 'n. 含意, 暗示', '/ɪmplɪ\'keɪʃ(ə)n | \'ɪmplɪ\'keʃən/', 'implication', 3);
INSERT INTO `words` VALUES (33375, '...an implicit warning to the Moroccans not to continue or repeat the military actions they began a week ago.', 'adj. 暗示的,盲从的', '/im\'plisit | ɪm\'plɪsɪt/', 'implicit', 3);
INSERT INTO `words` VALUES (33376, NULL, 'adv. 含蓄地, 暗中地', '/im\'plisitli | ɪm\'plɪsɪtlɪ/', 'implicitly', 3);
INSERT INTO `words` VALUES (33377, '‘Don’t go,’ I implored her.', 'v. 哀求， 恳求', '/ɪm\'plɔːr | ɪm\'plɔr/', 'implore', 3);
INSERT INTO `words` VALUES (33378, 'an implied threat', 'v. 暗示, 意味', '/im\'plai | ɪm\'plaɪ | ɪm\'plai/', 'imply', 3);
INSERT INTO `words` VALUES (33379, 'The beetle is thought to be a European import.', 'vt&n. 进口,输入,[pl]进口商品', '/im\'pɔ:t, \'impɔ:t | ɪm\'pɔːt; \'ɪm- | \'ɪmpɔt/', 'import', 3);
INSERT INTO `words` VALUES (33380, 'He was full of his own importance (= he behaved in an annoying way which showed that he thought he was very important ).', 'n. 重要(性)', '/im\'pɔ:təns | ɪm\'pɔːt(ə)ns | ɪm\'pɔrtns/', 'importance', 3);
INSERT INTO `words` VALUES (33381, 'We should stop the importation of these birds which are sold as commodities and endure lives of boredom in cages.', 'n. 进口, 输入品', '/,impɔ:\'teiʃən | ,ɪmpɔː\'teɪʃən/', 'importation', 3);
INSERT INTO `words` VALUES (33382, 'Japan is the biggest importer of U.S. beef.', 'n. 输入者, 进口商', '/im\'pɔ:tə | ɪm\'pɔrtɚ/', 'importer', 3);
INSERT INTO `words` VALUES (33383, 'Parents should beware of imposing their own tastes on their children.', 'v. 强加,征收(税款)', '/im\'pəuz | ɪm\'pəʊz | ɪm\'poz/', 'impose', 3);
INSERT INTO `words` VALUES (33384, NULL, 'n. 强迫接受', '/,impə\'ziʃən | ɪmpə\'zɪʃ(ə)n | ,ɪmpə\'zɪʃən/', 'imposition', 3);
INSERT INTO `words` VALUES (33385, '‘I want to speak to Mr Franks.’ ‘I’m afraid that’s impossible.’', 'adj. 不可能的', '/im\'pɔsəbl | ɪm\'pɒsɪb(ə)l | ɪm\'pɑsəbl/', 'impossible', 3);
INSERT INTO `words` VALUES (33386, 'The road toll scheme was dismissed as impractical.', 'adj. 不切实际的,不实用的', '/im\'præktikəl | ɪm\'præktɪk(ə)l | ɪm\'præktɪkl/', 'impractical', 3);
INSERT INTO `words` VALUES (33387, 'vague imprecise estimates', 'adj. 不精确的', '/,impri\'sais | ɪmprɪ\'saɪs | \'ɪmprɪ\'saɪs/', 'imprecise', 3);
INSERT INTO `words` VALUES (33388, 'Undercover officers found drug-making equipment used to impregnate paper with LSD.', 'v. 使怀孕, 使受精 a怀孕的, 充满的', '/\'impreɡneit, im\'preɡ-, im\'preɡnit, -neit | \'ɪmpregneɪt | ɪm\'prɛɡnet/', 'impregnate', 3);
INSERT INTO `words` VALUES (33389, 'Steve borrowed his dad’s sports car to impress his girlfriend.', 'v. 印,留下印象', '/im\'pres, \'impres | ɪm\'pres | ɪm\'prɛs/', 'impress', 3);
INSERT INTO `words` VALUES (33390, 'When we looked around the school we got a very good impression.', 'n. 印象, 感想', '/ɪm\'preʃ(ə)n | ɪm\'prɛʃən/', 'impression', 3);
INSERT INTO `words` VALUES (33391, 'Impressionism has long been one of the most popular art movements.', 'n. 印象派, 印象主义', '/im\'preʃənizəm | ɪm\'preʃənɪzəm | ɪm\'prɛʃən,ɪzəm/', 'Impressionism', 3);
INSERT INTO `words` VALUES (33392, 'impressionist painters', 'n. 印象主义者', '/im\'preʃənist | ɪm\'preʃənɪst | ɪm\'prɛʃənɪst/', 'impressionist', 3);
INSERT INTO `words` VALUES (33393, 'His paintings had become more impressionistic as his eyesight dimmed.', 'adj. 印象派的,给人深刻印象的', '/im,preʃə\'nistik | ɪm,preʃə\'nɪstɪk | ,ɪmprɛʃə\'nɪstɪk/', 'impressionistic', 3);
INSERT INTO `words` VALUES (33394, 'The figures certainly look impressive.', 'adj. 给人深刻印象的, 感人的', '/im\'presiv | ɪm\'presɪv | ɪm\'prɛsɪv/', 'impressive', 3);
INSERT INTO `words` VALUES (33395, NULL, 'adj. 令人难忘地, 令人印象深刻地', '/im\'presivli/', 'impressively', 3);
INSERT INTO `words` VALUES (33396, 'The company carries a variety of binders that can be imprinted with your message or logo.', 'v. 留下烙印', '/im\'print, \'imprint | ɪm\'prɪnt | \'ɪmprɪnt/', 'imprint', 3);
INSERT INTO `words` VALUES (33397, 'She was sentenced to seven years\' imprisonment.', 'n. 关押,监禁', '/im\'prizənmənt | ɪm\'prɪz(ə)nm(ə)nt | ɪm\'prɪznmənt/', 'imprisonment', 3);
INSERT INTO `words` VALUES (33398, NULL, 'adj. 不大可能的, 不像会发生的, 似不可信的', '/im\'prɔbəbl | ɪm\'prɒbəb(ə)l | ɪm\'prɑbəbl/', 'improbable', 3);
INSERT INTO `words` VALUES (33399, 'a course for students wishing to improve their English', 'v. 改善,改进', '/im\'pru:v | ɪm\'pruːv | ɪm\'pruv/', 'improve', 3);
INSERT INTO `words` VALUES (33400, 'Our results have shown some improvement this month.', 'n. 改进,进步', '/ɪm\'pruːvm(ə)nt | ɪm\'prʊvmənt/', 'improvement', 3);
INSERT INTO `words` VALUES (33401, 'It was the improvisation of the ebullition.', 'n. 即席创作', '/,imprəvai\'zeiʃən | ɪmprəvaɪ\'zeɪʃn | ,ɪmprəvaɪ\'zeʃən/', 'improvisation', 3);
INSERT INTO `words` VALUES (33402, 'I forgot to bring my notes, so I had to improvise.', 'v. 即兴创作', '/\'imprəvaiz | \'ɪmprəvaɪz/', 'improvise', 3);
INSERT INTO `words` VALUES (33403, 'The eye converts light signals to nerve impulses.', 'n. 冲动; vt. 推动', '/\'impʌls | \'ɪmpʌls/', 'impulse', 3);
INSERT INTO `words` VALUES (33404, 'All natural minerals contain impurities.', 'n. 不纯；杂质', '/im\'pjuərəti | ɪm\'pjʊərɪtɪ | ɪm\'pjʊrəti/', 'impurity', 3);
INSERT INTO `words` VALUES (33405, 'Her inability to concentrate could cause an accident.', 'n. 无能, 无力', '/,inə\'biləti | ɪnə\'bɪlɪtɪ | ,ɪnə\'bɪləti/', 'inability', 3);
INSERT INTO `words` VALUES (33406, 'In winter, the villages are inaccessible by road.', 'adj. 难接近的, 难达到的', '/,inæk\'sesəbl | ɪnək\'sesɪb(ə)l | ,ɪnæk\'sɛsəbl/', 'inaccessible', 3);
INSERT INTO `words` VALUES (33407, 'A lot of what has been written about him is inaccurate.', 'adj. 不准确的, 错误的', '/in\'ækjurət | ɪn\'ækjʊrət | ɪn\'ækjərət/', 'inaccurate', 3);
INSERT INTO `words` VALUES (33408, NULL, 'v. 使不活泼, 阻止活动', '/in\'æktiveit | ɪn\'æktɪveɪt | ɪn\'æktə,vet/', 'inactivate', 3);
INSERT INTO `words` VALUES (33409, 'The brain cells are inactive during sleep.', 'adj. 不活动的, 怠惰的', '/in\'æktiv | ɪn\'æktɪv/', 'inactive', 3);
INSERT INTO `words` VALUES (33410, 'Don’t suddenly take up violent exercise after years of inactivity.', 'n. 不活动, 迟钝', '/,inæk\'tiviti | ,ɪnæk\'tɪvɪtɪ | ,ɪnæk\'tɪvəti/', 'inactivity', 3);
INSERT INTO `words` VALUES (33411, NULL, 'n. 不充分', '/in\'ædikwəsi | ɪn\'ædɪkwəsɪ | ɪn\'ædɪkwəsi/', 'inadequacy', 3);
INSERT INTO `words` VALUES (33412, 'inadequate resources', 'adj. 不充分的,不适当的', '/in\'ædikwit | ɪn\'ædɪkwət/', 'inadequate', 3);
INSERT INTO `words` VALUES (33413, NULL, 'adv. 不够地, 不够好', '/in\'ædikwitli/', 'inadequately', 3);
INSERT INTO `words` VALUES (33414, 'Viruses can be spread inadvertently by email users.', 'adv. 非故意地,不注意地', '/,ɪnəd\'vɜːt(ə)ntlɪ | \'ɪnəd\'vɝtntli/', 'inadvertently', 3);
INSERT INTO `words` VALUES (33415, 'an inanimate object', 'adj. 无生命的', '/in\'ænimət | ɪn\'ænɪmət/', 'inanimate', 3);
INSERT INTO `words` VALUES (33416, 'Attempting to drown herself in inanity, she marries Peter Keating, only to leave him for newspaper tycoon Gail Wynand, publisher of the Banner, where Toohey\'s column appears.', 'n. 空虚, 愚蠢', '/i\'nænəti | ɪ\'nænətɪ/', 'inanity', 3);
INSERT INTO `words` VALUES (33417, 'There is no suggestion that clients have been sold inappropriate policies.', 'adj. 不适当的, 不合宜的', '/,inə\'prəupriət | ɪnə\'prəʊprɪət | \'ɪnə\'proprɪət/', 'inappropriate', 3);
INSERT INTO `words` VALUES (33418, 'The Turner Prize was inaugurated in 1984.', 'v. 开始；举行就职典礼', '/i\'nɔ:ɡjureit | ɪ\'nɔːgjʊreɪt | ɪ\'nɔɡjəret/', 'inaugurate', 3);
INSERT INTO `words` VALUES (33419, 'Mammals have an inborn fear of snakes.', 'adj. 天生的,生来的', '/\'inbɔ:n | \'ɪnbɔːn; ɪn\'bɔːn | ,ɪn\'bɔrn/', 'inborn', 3);
INSERT INTO `words` VALUES (33420, 'With this big stick, Inca kings began eyeing the lands and resources of others.', 'n. 印加人(古代秘鲁土著人)', '/\'iŋkə | \'ɪŋkə/', 'Inca', 3);
INSERT INTO `words` VALUES (33421, 'the invention of the incandescent lamp', 'adj. 遇热发光的, 白炽的', '/,inkæn\'desənt | ɪnkæn\'des(ə)nt | \'ɪnkən\'dɛsnt/', 'incandescent', 3);
INSERT INTO `words` VALUES (33422, 'She seemed incapable of making the decision.', 'adj. 无能力的', '/in\'keipəbl | ɪn\'keɪpəb(ə)l | ɪn\'kepəbl/', 'incapable', 3);
INSERT INTO `words` VALUES (33423, 'Her mother has been incapacitated by a fall.', 'vt. 使无资格； 使失去能力； 使不胜任', '/ˌɪnkə\'pæsɪteɪt | ,ɪnkə\'pæsɪtet/', 'incapacitate', 3);
INSERT INTO `words` VALUES (33424, 'A serious fall incapacitated the 68-year-old congressman.', 'vt. 使不能', '/,inkə\'pæsi,teitid/', 'incapacitated', 3);
INSERT INTO `words` VALUES (33425, 'a church filled with the smell of incense', 'n. 〔燃烧时发出怡人香味的〕香; v. 使〔某人〕十分愤怒', '/\'ɪnsens | \'ɪnsɛns/', 'incense', 3);
INSERT INTO `words` VALUES (33426, 'As an added incentive, there’s a bottle of champagne for the best team.', 'adj. 刺激的, 鼓励的 n动机', '/in\'sentiv | ɪn\'sentɪv | ɪn\'sɛntɪv/', 'incentive', 3);
INSERT INTO `words` VALUES (33427, 'a CD collection covering the band from its inception in 1994', 'n. 起初, 获得学位', '/in\'sepʃən | ɪn\'sepʃ(ə)n | ɪn\'sɛpʃən/', 'inception', 3);
INSERT INTO `words` VALUES (33428, 'The child’s incessant talking started to irritate her.', 'adj. 不断的, 无尽的', '/in\'sesənt | ɪn\'ses(ə)nt | ɪn\'sɛsnt/', 'incessant', 3);
INSERT INTO `words` VALUES (33429, 'And it can be frustrating to watch a beloved pet scratch incessantly—especially after you’ve tried everything to get rid of the pests.', 'adv. 不间断地', '/in\'sesntli | ɪn\'sesntlɪ/', 'incessantly', 3);
INSERT INTO `words` VALUES (33430, 'The curtains were an inch too short.', 'n. 英寸', '/intʃ | ɪn(t)ʃ | ɪntʃ/', 'inch', 3);
INSERT INTO `words` VALUES (33431, 'The adorable inchworm is really the caterpillar of the geometer moth.', 'n. [昆] 尺蠖', '/\'intʃwə:m | \'ɪn(t)ʃwɜːm | \'ɪntʃwɝm/', 'inchworm', 3);
INSERT INTO `words` VALUES (33432, 'Am I at risk because of some incident in my sexual past?', 'n. 事件; adj. 附带的, 易于发生的', '/\'insidənt | \'ɪnsɪd(ə)nt | \'ɪnsɪdənt/', 'incident', 3);
INSERT INTO `words` VALUES (33433, 'Increased motivation is more than an incidental benefit of reward schemes.', 'adj. 偶然的；附带的', '/,insi\'dentəl | ɪnsɪ\'dent(ə)l | \'ɪnsə\'dɛntl/', 'incidental', 3);
INSERT INTO `words` VALUES (33434, 'All the infected clothing was incinerated.', 'v. 把烧成灰,烧弃', '/in\'sinəreit | ɪn\'sɪnəreɪt/', 'incinerate', 3);
INSERT INTO `words` VALUES (33435, 'a sign of incipient madness', 'adj. 初期的,初始的', '/in\'sipiənt | ɪn\'sɪpɪənt/', 'incipient', 3);
INSERT INTO `words` VALUES (33436, 'In theory, the four axis tube-end incisory robot can incise round tubes\' ends of any form.', 'v. 切入, 切割', '/in\'saiz | ɪn\'saɪz/', 'incise', 3);
INSERT INTO `words` VALUES (33437, 'She greeted Maggie with an inclination of the head.', 'n. 倾斜, 弯曲', '/,inkli\'neiʃən | ɪnklɪ\'neɪʃ(ə)n | \'ɪnklə\'neʃən/', 'inclination', 3);
INSERT INTO `words` VALUES (33438, 'The telescope is inclined at an angle of 43 degrees.', 'v. (使)倾斜；倾向于， n斜面', '/in\'klain | ɪn\'klaɪn/', 'incline', 3);
INSERT INTO `words` VALUES (33439, 'With the recent inclusions, there will be 28 delegates in all.', 'n. 包含', '/in\'klu:ʒən | ɪn\'kluːʒ(ə)n | ɪn\'kluʒn/', 'inclusion', 3);
INSERT INTO `words` VALUES (33440, 'You are also invited to join us on our prayer days (this year, June 6 to June 14 inclusive).', 'adj. 包含在内的', '/in\'klu:siv | ɪn\'kluːsɪv | ɪn\'klusɪv/', 'inclusive', 3);
INSERT INTO `words` VALUES (33441, 'low-income families', 'n. 收入,收益,', '/\'inkʌm | \'ɪnkʌm/', 'income', 3);
INSERT INTO `words` VALUES (33442, 'When others check in their code, you will see it as incoming to your workspace.', 'adj. 引入的', '/\'ɪnkʌmɪŋ/', 'incoming', 3);
INSERT INTO `words` VALUES (33443, 'In a time when there is so much dispute about the compatibility or incompatibility of science with religion, it may be a good idea to revisit what Newton and Einstein had to say about God.', 'n. 不两立, 不相容', '/\'inkəm,pætə\'biləti | \'ɪnkəm,pætə\'bɪlətɪ | \'ɪnkəm,pætə\'bɪləti/', 'incompatibility', 3);
INSERT INTO `words` VALUES (33444, 'I don’t know why they ever got married. They’re totally incompatible.', 'adj. 不相容的 ,矛盾的', '/,inkəm\'pætəbl | ɪnkəm\'pætɪb(ə)l | ,ɪnkəm\'pætəbl/', 'incompatible', 3);
INSERT INTO `words` VALUES (33445, 'Unfortunately, I do not have the information because our records are incomplete.', 'adj. 不完全的, 不完整的', '/,inkəm\'pli:t | ɪnkəm\'pliːt | \'ɪnkəm\'plit/', 'incomplete', 3);
INSERT INTO `words` VALUES (33446, 'Carbon monoxide is released when carbon in fuel—both plants and fossil fuels like gasoline—burns incompletely.', 'adv. 不完全地', '/,inkəm\'pli:tli/', 'incompletely', 3);
INSERT INTO `words` VALUES (33447, 'legal documents full of incomprehensible jargon', 'adj. 费解的,不可思议的', '/in,kɔmpri\'hensəbl | ,ɪnkɒmprɪ\'hensɪb(ə)l | ɪn,kɑmprɪ\'hɛnsəbl/', 'incomprehensible', 3);
INSERT INTO `words` VALUES (33448, 'The evidence against the two men was inconclusive.', 'adj. 非决定性的,不确定的', '/,inkən\'klu:siv | ɪnkən\'kluːsɪv | ,ɪnkən\'klusɪv/', 'inconclusive', 3);
INSERT INTO `words` VALUES (33449, 'The incongruity of her situation struck Gina with unpleasant force.', 'n. 不调和的, 不适宜的', '/,inkɔŋ\'ɡru:əti | ,ɪnkɒŋ\'gruːɪtɪ | ,ɪnkɑŋ\'grʊəti/', 'incongruity', 3);
INSERT INTO `words` VALUES (33450, 'The new theatre looks utterly incongruous in its setting.', 'adj. 不协调的,不一致的', '/in\'kɔŋɡruəs | ɪn\'kɒŋgrʊəs | ɪn\'kɑŋɡruəs/', 'incongruous', 3);
INSERT INTO `words` VALUES (33451, 'There were several glaring inconsistencies (= very noticeable differences ) in his report.', 'n. 矛盾', '/,inkən\'sistənsi,-təns | ɪnkən\'sɪst(ə)nsɪ | ,ɪnkən\'sɪstənsi/', 'inconsistency', 3);
INSERT INTO `words` VALUES (33452, 'an inconspicuous little restaurant', 'adj. 不显眼的,不引人注意的', '/,inkən\'spikjuəs | ɪnkən\'spɪkjʊəs | \'ɪnkən\'spɪkjʊəs/', 'inconspicuous', 3);
INSERT INTO `words` VALUES (33453, NULL, 'adv. 难以觉察地, 不显著地', '/,inkəns\'pikjuəsli/', 'inconspicuously', 3);
INSERT INTO `words` VALUES (33454, 'Monday’s a bit inconvenient for me. How about Wednesday?', 'adj. 不便的,打扰的', '/,inkən\'vi:njənt | ɪnkən\'viːnɪənt | ,ɪnkən\'vinɪənt/', 'inconvenient', 3);
INSERT INTO `words` VALUES (33455, 'The new cars will incorporate a number of major improvements.', 'v. 合并,组成公司', '/in\'kɔ:pəreit, in\'kɔ:pərət | ɪn\'kɔːpəreɪt/', 'incorporate', 3);
INSERT INTO `words` VALUES (33456, NULL, 'n. 合并；组建公司', '/in,kɔ:pə\'reiʃən | ɪn,kɔːpə\'reɪʃən | ɪn,kɔrpə\'reʃən/', 'incorporation', 3);
INSERT INTO `words` VALUES (33457, 'The information you gave us was incorrect.', 'adj. 不正确的,错误的', '/,inkə\'rekt | ɪnkə\'rekt | ,ɪnkə\'rɛkt/', 'incorrect', 3);
INSERT INTO `words` VALUES (33458, NULL, 'adv. 错误地,不适当地', '/,inkə\'rektli | ˌɪnkə\'rektlɪ | ,ɪnkə\'rɛktli/', 'incorrectly', 3);
INSERT INTO `words` VALUES (33459, 'The commercial world is now being increasingly computerized.', 'adv. 日益,愈加', '/in\'kri:siŋli | ɪn\'kriːsɪŋlɪ | ɪn\'krisɪŋli/', 'increasingly', 3);
INSERT INTO `words` VALUES (33460, 'It’s incredible that he survived the fall.', 'adj. 不可信的；不可思议的', '/in\'kredəbl | ɪn\'kredɪb(ə)l | ɪn\'krɛdəbl/', 'incredible', 3);
INSERT INTO `words` VALUES (33461, '‘You sold the car?’ she asked, incredulous.', 'adj. 怀疑的， 不轻信的', '/ɪn\'kredʒələs | ɪn\'krɛdʒələs/', 'incredulous', 3);
INSERT INTO `words` VALUES (33462, 'a salary of £18,000, with annual increments of 2.5%', 'n. 增加； 增量； 定期的加薪', '/\'ɪŋkrəmənt/', 'increment', 3);
INSERT INTO `words` VALUES (33463, 'The birds returned to their nests and continued to incubate the eggs.', 'v. 孵卵', '/\'inkjubeit | \'ɪŋkjʊbeɪt | \'ɪŋkjubet/', 'incubate', 3);
INSERT INTO `words` VALUES (33464, 'Resourcing incubation has to be a part of planning – otherwise the natural tendency is to suck up all the resources for the critical activity of the day.', 'n. 孵化, 熟虑', '/,inkju\'beiʃən | ɪŋkjʊ\'beɪʃ(ə)n | ,ɪŋkju\'beʃən/', 'incubation', 3);
INSERT INTO `words` VALUES (33465, NULL, 'n. 培养的器具, 孵卵器', '/\'inkjubeitə | \'ɪŋkjʊbeɪtə | \'ɪŋkjubetɚ/', 'incubator', 3);
INSERT INTO `words` VALUES (33466, 'The government had also incurred huge debts.', 'v. 招致', '/in\'kə: | ɪn\'kɜː | ɪn\'kɝ/', 'incur', 3);
INSERT INTO `words` VALUES (33467, '...armed incursions into border areas by rebel forces.', 'n. 侵犯，入侵', '/in\'kə:ʃən | ɪn\'kɜːʃ(ə)n | ɪn\'kɝʒn/', 'incursion', 3);
INSERT INTO `words` VALUES (33468, 'the 17 most heavily indebted nations', 'adj. 受惠的, 负债的', '/in\'detid | ɪn\'detɪd | ɪn\'dɛtɪd/', 'indebted', 3);
INSERT INTO `words` VALUES (33469, 'an indecipherable signature', 'adj. 无法解释的,难辨认的', '/,indi\'saifərəbl | ,ɪndɪ\'saɪf(ə)rəb(ə)l | \'ɪndɪ\'saɪfrəbl/', 'indecipherable', 3);
INSERT INTO `words` VALUES (33470, 'The blood tests prove that Vince is indeed the father.', 'adv. 真正地,的确,事实上', '/in\'di:d | ɪn\'diːd | ɪn\'did/', 'indeed', 3);
INSERT INTO `words` VALUES (33471, 'Teachers find the report’s terminology so indefinite that it is confusing.', 'adj. 不明确的，含糊的', '/in\'definət | ɪn\'defɪnɪt | ɪn\'dɛfɪnət/', 'indefinite', 3);
INSERT INTO `words` VALUES (33472, 'It can give you the ability to store indefinitely your session data where it can be retrieved not only after a restart, but from any of a number of machines in a cluster.', 'adv. 不确定地', '/in\'defθnətli; in\'definitli; in\'definətli | ɪn\'defɪnɪtlɪ | ɪn\'dɛfɪnətli/', 'indefinitely', 3);
INSERT INTO `words` VALUES (33473, 'The country has made great advances since independence.', 'n. 独立,自主', '/,indi\'pendəns | ɪndɪ\'pend(ə)ns | ,ɪndɪ\'pɛndəns/', 'independence', 3);
INSERT INTO `words` VALUES (33474, 'Mr. Vassiliou, standing as an independent, succeeded in convincing a significant number of voters of his argument.', 'n. 中立派,无党派者', '/,indi\'pendənt | ,ɪndɪ\'pendənt | \'ɪndɪ\'pɛndənt/', 'independent', 3);
INSERT INTO `words` VALUES (33475, 'a girl of indeterminate age', 'adj. 不确定的, 含混的', '/,indi\'tə:minət | ,ɪndɪ\'tɜːmɪnət | \'ɪndɪ\'tɝmənət/', 'indeterminate', 3);
INSERT INTO `words` VALUES (33476, '...the consumer price index.', 'n. 索引, 指数', '/\'indeks | \'ɪndeks | \'ɪndɛks/', 'index', 3);
INSERT INTO `words` VALUES (33477, 'Burma borders on India.', 'n. 印度', '/\'indiə | \'ɪndɪə/', 'India', 3);
INSERT INTO `words` VALUES (33478, 'Do you fancy going out for an Indian?', 'n. 印度(人)', '/\'indiən | \'ɪndɪən/', 'Indian', 3);
INSERT INTO `words` VALUES (33479, 'I own a coffee shop in Southern Indiana. I have a room in the back where I spend most of the week.', 'n. 印地安那州', '/,indi\'ænə/', 'Indiana', 3);
INSERT INTO `words` VALUES (33480, 'The study indicates a connection between poverty and crime.', 'v. 表明， 显示； 指出， 指示； 象征， 预示； 暗示， 间接提及', '/\'ɪndɪkeɪt | \'ɪndɪket/', 'indicate', 3);
INSERT INTO `words` VALUES (33481, 'Could you give me some indication as to when I am likely to receive a reply?', 'n. 指示,表示,迹象', '/,indi\'keiʃən | ɪndɪ\'keɪʃ(ə)n | ,ɪndɪ\'keʃən/', 'indication', 3);
INSERT INTO `words` VALUES (33482, 'All the main economic indicators suggest that trade is improving.', 'n. 指示器', '/\'indikeitə | \'ɪndɪkeɪtə | \'ɪndɪketɚ/', 'indicator', 3);
INSERT INTO `words` VALUES (33483, 'He was later indicted on corruption charges.', 'vt. 控诉， 起诉， 控告', '/ɪn\'daɪt/', 'indict', 3);
INSERT INTO `words` VALUES (33484, 'Whether you stay or leave is a matter of total indifference to me (= I do not care ).', 'n. 不关心', '/in\'difərəns | ɪn\'dɪf(ə)r(ə)ns | ɪn\'dɪfrəns/', 'indifference', 3);
INSERT INTO `words` VALUES (33485, 'an indifferent cook', 'adj. 漠不关心的,中性的', '/in\'difərənt | ɪn\'dɪf(ə)r(ə)nt | ɪn\'dɪfrənt/', 'indifferent', 3);
INSERT INTO `words` VALUES (33486, 'the many indigenous cultures which existed in Siberia', 'adj. 本地的, 天生的', '/in\'didʒinəs | ɪn\'dɪdʒɪnəs | ɪn\'dɪdʒənəs/', 'indigenous', 3);
INSERT INTO `words` VALUES (33487, 'No where in the article does it mention her financial status. So…what is it that leads everyone to assume she was indigent?', 'adj. 贫困的， 贫穷的', '/\'ɪndɪdʒənt/', 'indigent', 3);
INSERT INTO `words` VALUES (33488, 'indigestible statistics', 'adj. 不吸收的,难理解的', '/,indi\'dʒestəbl, in\'dai- | ɪndɪ\'dʒestɪb(ə)l; -daɪ- | ,ɪndɪ\'dʒɛstəbl/', 'indigestible', 3);
INSERT INTO `words` VALUES (33489, 'These pills are for your fever and indigestion.', 'n. 消化不良', '/ˌɪndɪ\'dʒestʃən | ,ɪndɪ\'dʒɛstʃən/', 'indigestion', 3);
INSERT INTO `words` VALUES (33490, 'an indignant reply', 'adj. 愤慨的， 恼怒的', '/ɪn\'dɪgnənt | ɪn\'dɪɡnənt/', 'indignant', 3);
INSERT INTO `words` VALUES (33491, NULL, 'n. 靛, 靛青', '/\'indiɡəu | \'ɪndɪgəʊ | \'ɪndɪɡo/', 'indigo', 3);
INSERT INTO `words` VALUES (33492, 'Losing weight is an indirect result of smoking cigarettes.', 'adj. 间接的,迂回的', '/,indi\'rekt, -dai- | ɪndɪ\'rekt; ɪndaɪ- | ,ɪndə\'rɛkt/', 'indirect', 3);
INSERT INTO `words` VALUES (33493, 'I heard the news indirectly.', 'adv. 间接地', '/,indi\'rektli | ,ɪndɪ\'rek(t)lɪ | ,ɪndə\'rɛktli/', 'indirectly', 3);
INSERT INTO `words` VALUES (33494, 'The path was almost indiscernible in the mist.', 'adj. 看不清的', '/,indi\'sə:nəbl | ,ɪndɪ\'sɜːnɪb(ə)l/', 'indiscernible', 3);
INSERT INTO `words` VALUES (33495, 'To be without some of the things you wan is an indispensable part of happiness.', 'n. 不可缺少之物; adj. 不可缺少的', '/,indis\'pensəbl | ɪndɪ\'spensəb(ə)l | \'ɪndɪ\'spɛnsəbl/', 'indispensable', 3);
INSERT INTO `words` VALUES (33496, 'Photovoltaic cells rely on amorphous or crystalline silicon, cadmium telluride, or copper indium selenide and sulfide.', 'n. [化]铟', '/\'indiəm | \'ɪndɪəm | \'ɪndiəm/', 'indium', 3);
INSERT INTO `words` VALUES (33497, 'Each individual leaf on the tree is different.', 'adj. 单独的；独特的; n. 个人， 个体', '/ˌɪndɪ\'vɪdʒuəl | ˌɪndəˈvɪdʒʊəl/', 'individual', 3);
INSERT INTO `words` VALUES (33498, 'Capitalism encourages competition and individualism.', 'n. 个人主义, 利己主义', '/,indi\'vidjuəlizəm, -dʒu- | ɪndɪ\'vɪdjʊ(ə)lɪz(ə)m | ,ɪndɪ\'vɪdʒuəlɪzəm/', 'individualism', 3);
INSERT INTO `words` VALUES (33499, 'Most artists are very individualistic.', 'adj. 个人主义的', '/\'indi,vidjuə\'listik, -dʒu- | ,ɪndɪvɪdjʊə\'lɪstɪk | ˌɪndɪˌvɪdʒʊr\'lɪstɪk/', 'individualistic', 3);
INSERT INTO `words` VALUES (33500, 'We like our staff to show their individuality rather than wear a uniform.', 'n. 个性,(通常用复数)个人的嗜好', '/\'indi,vidju\'æləti, -dʒu- | ,ɪndɪvɪdjʊ\'ælɪtɪ | ,ɪndɪ,vɪdʒu\'æləti/', 'individuality', 3);
INSERT INTO `words` VALUES (33501, 'The bridegroom thanked them all individually.', 'adv. 个别地,单独地', '/,indi\'vidjuəli, -dʒu- | ɪndɪ\'vɪdjʊ(ə)lɪ | ˌɪndɪˈvɪdʒuəli/', 'individually', 3);
INSERT INTO `words` VALUES (33502, NULL, 'adj. 懒惰的， 懒散的； 不活跃的', '/\'ɪndələnt/', 'indolent', 3);
INSERT INTO `words` VALUES (33503, 'We have the example of Aceh, Indonesia, to guide us.', 'n. 印尼(东南亚岛国)', '/\'indəu\'ni:zjə,-ʒə/', 'Indonesia', 3);
INSERT INTO `words` VALUES (33504, 'an indoor swimming pool', 'adj. 户内的, 室内的', '/\'indɔ: | \'ɪndɔː | \'ɪndɔr/', 'indoor', 3);
INSERT INTO `words` VALUES (33505, 'Patients with eating disorders may use drugs to induce vomiting.', 'v. 促使,引诱', '/in\'dju:s, in\'du:s | ɪn\'djuːs | ɪn\'dus/', 'induce', 3);
INSERT INTO `words` VALUES (33506, 'financial inducements to attract good job candidates', 'n. 诱因, 刺激物', '/in\'dju:smənt | ɪn\'djuːsm(ə)nt | ɪn\'dusmənt/', 'inducement', 3);
INSERT INTO `words` VALUES (33507, 'In addition, plants have also evolved an adaptive inducible resistance mechanism in response to pathogen invasion.', 'adj. 可诱导的,可导致的', '/in\'dju:səbl/', 'inducible', 3);
INSERT INTO `words` VALUES (33508, 'The government shoulders ethic obligation, she has to induct and maintain the rationalization of the living world.', 'v. 感应,引导', '/in\'dʌkt | ɪn\'dʌkt/', 'induct', 3);
INSERT INTO `words` VALUES (33509, 'His mother spoiled him, indulging his every whim.', 'v. 纵容', '/in\'dʌldʒ | ɪn\'dʌldʒ/', 'indulge', 3);
INSERT INTO `words` VALUES (33510, 'One arrangement now under strain is the 1960 Indus Waters Treaty between India and Pakistan.', 'n. 印度河（印度西北部的河流）', '/\'indəs/', 'Indus', 3);
INSERT INTO `words` VALUES (33511, 'By 1900, Britain was a mainly industrial society.', 'adj. 工业的,产业的', '/in\'dʌstriəl | ɪn\'dʌstrɪəl/', 'industrial', 3);
INSERT INTO `words` VALUES (33512, 'Coal consumption in Manchester was measured in millions of tonnes, and its smoke became, as Lewis Mumford remarked, \"the very incense of the new industrialism\".', 'n. 产业主义,工业制度', '/in\'dʌstriəlizəm | ɪn\'dʌstrɪəlɪz(ə)m | ɪn\'dʌstrɪəlɪzəm/', 'industrialism', 3);
INSERT INTO `words` VALUES (33513, '...prominent Japanese industrialists.', 'n. 工业家, 实业家,', '/in\'dʌstriəlist | ɪn\'dʌstrɪəlɪst/', 'industrialist', 3);
INSERT INTO `words` VALUES (33514, 'And, at this point, traces of industrialization can only be found in sediments in Europe.', 'n. 工业化,产业化', '/in,dʌstriəlai\'zeiʃən, -li\'z-/', 'industrialization', 3);
INSERT INTO `words` VALUES (33515, 'Energy consumption rises as countries industrialize.', 'v. 使工业化', '/in\'dʌtriəlaiz | ɪnˈdʌstrɪəlʌɪz | ɪn\'dʌstrɪəlaɪz/', 'industrialize', 3);
INSERT INTO `words` VALUES (33516, 'He added: “You can imagine a situation when some of our industrially important but polluting processes are done in space and the finished products are brought back down to Earth.', 'adv. 企业[工业]地', '/in\'dʌstriəli/', 'industrially', 3);
INSERT INTO `words` VALUES (33517, 'She was an industrious and willing worker.', 'adj. 勤劳的, 勤奋的', '/in\'dʌstriəs | ɪn\'dʌstrɪəs/', 'industrious', 3);
INSERT INTO `words` VALUES (33518, 'I work in the oil industry.', 'n. 工业,产业', '/\'indəstri | \'ɪndəstrɪ | \'ɪndəstri/', 'industry', 3);
INSERT INTO `words` VALUES (33519, 'The meat was so burnt that it was inedible.', 'adj. 不能吃的，不宜食用的', '/in\'edibl | ɪn\'edɪb(ə)l | ɪn\'ɛdəbl/', 'inedible', 3);
INSERT INTO `words` VALUES (33520, 'an ineffective marketing campaign', 'adj. 无效的, (指人)工作效率低的', '/,ini\'fektiv | ɪnɪ\'fektɪv | ,ɪnɪ\'fɛktɪv/', 'ineffective', 3);
INSERT INTO `words` VALUES (33521, 'an inefficient use of resources', 'adj. 效率低的,效率差的', '/,ini\'fiʃənt | ɪnɪ\'fɪʃ(ə)nt | ,ɪnɪ\'fɪʃnt/', 'inefficient', 3);
INSERT INTO `words` VALUES (33522, 'People are concerned about corruption and social inequality.', 'n. 不平等, 不平均', '/,ini\'kwɔləti | ɪnɪ\'kwɒlɪtɪ | ,ɪnɪ\'kwɑləti/', 'inequality', 3);
INSERT INTO `words` VALUES (33523, 'inert gases', 'adj. 无活动的， 惰性的； 不活泼的， 迟钝的', '/ɪ\'nɜːrt | ɪ\'nɝt/', 'inert', 3);
INSERT INTO `words` VALUES (33524, 'political inertia', 'n. 惯性； 惰性', '/ɪ\'nɜːrʃə | ɪ\'nɝʃə/', 'inertia', 3);
INSERT INTO `words` VALUES (33525, 'A further escalation of the crisis now seems inevitable.', 'adj. 不可避免的, 必然的', '/in\'evitəbl | ɪn\'evɪtəb(ə)l | ɪn\'ɛvɪtəbl/', 'inevitable', 3);
INSERT INTO `words` VALUES (33526, 'The decision will inevitably lead to political tensions.', 'adv. 不可避免地；必然地', '/in\'evitəbli | ɪ\'nevɪtəblɪ; ɪn\'evɪtəblɪ | ɪn\'ɛvɪtəbli/', 'inevitably', 3);
INSERT INTO `words` VALUES (33527, 'a good selection of inexpensive wines', 'adj. 廉价的,便宜的', '/,inik\'spensiv | ɪnɪk\'spensɪv; ɪnek- | ,ɪnɪk\'spɛnsɪv/', 'inexpensive', 3);
INSERT INTO `words` VALUES (33528, 'inexplicable behaviour', 'adj. 无法解释的，难理解的', '/,inik\'splikəbl | ,ɪnɪk\'splɪkəb(ə)l; ,ɪnek-; ɪn\'eksplɪ- | ,ɪnɪk\'splɪkəbl/', 'inexplicable', 3);
INSERT INTO `words` VALUES (33529, 'Our survival is inextricably linked to the survival of the rainforest.', 'adv. 分不开地, 无法摆脱地', '/,inik\'strikəbli | ˌɪnɪkˈstrɪkəbli/', 'inextricably', 3);
INSERT INTO `words` VALUES (33530, 'the infancy of radio broadcasting', 'n. 幼年', '/\'infənsi | \'ɪnf(ə)nsɪ | \'ɪnfənsi/', 'infancy', 3);
INSERT INTO `words` VALUES (33531, 'An infant’s skin is very sensitive.', 'n. 婴儿', '/\'infənt | \'ɪnf(ə)nt | \'ɪnfənt/', 'infant', 3);
INSERT INTO `words` VALUES (33532, 'infantile jokes', 'adj. 幼稚的，幼儿的', '/\'infəntail | \'ɪnf(ə)ntaɪl | \'ɪnfəntaɪl/', 'infantile', 3);
INSERT INTO `words` VALUES (33533, NULL, 'vt. 使迷恋； 使糊涂', '/ɪn\'fætʃueɪt | ɪn\'fætjʊɪt/', 'infatuate', 3);
INSERT INTO `words` VALUES (33534, 'People with the virus may feel perfectly well, but they can still infect others.', 'v. [医] 传染, 感染', '/in\'fekt | ɪn\'fekt | ɪn\'fɛkt/', 'infect', 3);
INSERT INTO `words` VALUES (33535, 'The baby had an ear infection.', 'n. 传染病, 影响,', '/in\'fekʃən | ɪn\'fekʃ(ə)n | ɪn\'fɛkʃən/', 'infection', 3);
INSERT INTO `words` VALUES (33536, 'infectious diseases', 'adj. 传染性的， 传染病的； 有感染力的', '/ɪn\'fekʃəs | ɪn\'fɛkʃəs/', 'infectious', 3);
INSERT INTO `words` VALUES (33537, 'There were two inferences to be drawn from her letter.', 'n. 推论', '/\'infərəns | \'ɪnf(ə)r(ə)ns | \'ɪnfərəns/', 'inference', 3);
INSERT INTO `words` VALUES (33538, 'In this article I will focus on data collected using a nominal scale of measurement and the inferential techniques appropriate for nominal data.', 'adj. 推理的, 推论的', '/,infə\'renʃəl | ,ɪnfə\'renʃəl | ,ɪnfə\'rɛnʃəl/', 'inferential', 3);
INSERT INTO `words` VALUES (33539, 'I felt very inferior among all those academics.', 'adj. 下等的, 下级的', '/in\'fiəriə | ɪn\'fɪərɪə | ɪn\'fɪrɪɚ/', 'inferior', 3);
INSERT INTO `words` VALUES (33540, 'This kind of sentiment is a very interesting combination of superiority and inferiority.', 'n. 自卑, 次等', '/in,fiəri\'ɔrəti | ɪn,fɪərɪ\'ɒrɪtɪ | ɪn,fɪrɪ\'ɔrəti/', 'inferiority', 3);
INSERT INTO `words` VALUES (33541, 'infertile couples', 'adj. 贫瘠的, 不能生育的', '/in\'fə:tail, -til | ɪn\'fɜːtaɪl | ɪn\'fɝtl/', 'infertile', 3);
INSERT INTO `words` VALUES (33542, '...pests like aphids which infest cereal crops.', 'v. 骚扰,大批滋生', '/in\'fest | ɪn\'fest | ɪn\'fɛst/', 'infest', 3);
INSERT INTO `words` VALUES (33543, 'Police attempts to infiltrate neo-Nazi groups were largely unsuccessful.', 'v. 渗入， 渗透； 悄悄进入， 潜入', '/\'ɪnfɪltreɪt | ɪn\'fɪltret/', 'infiltrate', 3);
INSERT INTO `words` VALUES (33544, 'And what concerns do you have about their infiltration as we move forward?', 'n. 渗透', '/,infil\'treiʃən | ,ɪnfɪl\'treɪʃən | ,ɪnfɪl\'treʃən/', 'infiltration', 3);
INSERT INTO `words` VALUES (33545, 'The universe is infinite.', 'adj. 无限的，无穷的', '/\'infinət | \'ɪnfɪnət/', 'infinite', 3);
INSERT INTO `words` VALUES (33546, 'That may not seem like much, especially given the proton\'s infinitesimally tiny size.', 'adv. 极小地', '/infini\'tesiməli/', 'infinitesimally', 3);
INSERT INTO `words` VALUES (33547, '...her aging, infirm husband.', 'adj. 虚弱的； 不坚定的', '/ɪn\'fɜːrm | ɪn\'fɝm/', 'infirm', 3);
INSERT INTO `words` VALUES (33548, 'The drug can cause inflammation of the liver.', 'n. 炎症， 发炎', '/ˌɪnflə\'meɪʃn | \'ɪnflə\'meʃən/', 'inflammation', 3);
INSERT INTO `words` VALUES (33549, 'It took us half an hour to inflate the dinghy.', 'v. 充气， 膨胀； 鼓吹， 吹捧； 涨价', '/ɪn\'fleɪt | ɪn\'flet/', 'inflate', 3);
INSERT INTO `words` VALUES (33550, 'Inflation is now at over 16%.', 'n. 通货膨胀, 膨胀', '/in\'fleiʃən | ɪn\'fleɪʃ(ə)n | ɪn\'fleʃən/', 'inflation', 3);
INSERT INTO `words` VALUES (33551, '...the upward inflection of her voice.', 'n. 变形', '/in\'flekʃən | ɪn\'flekʃ(ə)n | ɪn\'flɛkʃən/', 'inflection', 3);
INSERT INTO `words` VALUES (33552, 'This approach is too inflexible and too costly.', 'adj. 不可弯曲的, 僵硬的', '/in\'fleksəbl | ɪn\'fleksɪb(ə)l | ɪn\'flɛksəbl/', 'inflexible', 3);
INSERT INTO `words` VALUES (33553, NULL, 'adv. 不弯曲地, 不屈地', '/in\'fleksəbli/', 'inflexibly', 3);
INSERT INTO `words` VALUES (33554, 'The Swiss wanted to discourage an inflow of foreign money.', 'n. 流入, 流入物', '/\'infləu, in\'fləu | \'ɪnfləʊ | \'ɪnflo/', 'inflow', 3);
INSERT INTO `words` VALUES (33555, 'He had influential friends.', 'adj. 有影响的, 有势力的', '/,ɪnflʊ\'enʃ(ə)l | ,ɪnflu\'ɛnʃl/', 'influential', 3);
INSERT INTO `words` VALUES (33556, 'All the medical workers in the region helped to put down the influenza epidemic.', 'n. 流行性感冒', '/ˌɪnflu\'enzə | ,ɪnflu\'ɛnzə/', 'influenza', 3);
INSERT INTO `words` VALUES (33557, '...problems caused by the influx of refugees.', 'n. 流入', '/\'inflʌks | \'ɪnflʌks/', 'influx', 3);
INSERT INTO `words` VALUES (33558, 'They decided to inform the police.', 'v. 通知, 告诉', '/in\'fɔ:m | ɪn\'fɔːm | ɪn\'fɔrm/', 'inform', 3);
INSERT INTO `words` VALUES (33559, 'The atmosphere at work is fairly informal.', 'adj. 不正式的', '/ɪn\'fɔːm(ə)l | ɪn\'fɔrml/', 'informal', 3);
INSERT INTO `words` VALUES (33560, 'One of the witnesses was a paid informant for the FBI.', 'n. 通知者, 告密者', '/in\'fɔ:mənt | ɪn\'fɔːmənt | ɪn\'fɔrmənt/', 'informant', 3);
INSERT INTO `words` VALUES (33561, 'Both men termed the meeting friendly and informative.', 'adj. 提供消息的, 情报的', '/in\'fɔ:mətiv | ɪn\'fɔːmətɪv | ɪn\'fɔrmətɪv/', 'informative', 3);
INSERT INTO `words` VALUES (33562, 'Informed sources said it was likely that the president would make a televised statement.', 'adj. 有学识的； 见多识广的， 有见识的', '/ɪn\'fɔːrmd | ɪn\'fɔrmd/', 'informed', 3);
INSERT INTO `words` VALUES (33563, '...searching with infrared scanners for weapons and artillery.', 'adj. 红外线的；产生红外线的; n. 红外线', '/ˌɪnfrə\'red | ,ɪnfrə\'rɛd/', 'infrared', 3);
INSERT INTO `words` VALUES (33564, 'Some countries lack a suitable economic infrastructure.', 'n. 下部构造,基础下部组织', '/\'infrə,strʌktʃə | \'ɪnfrəstrʌktʃə | \'ɪnfrə\'strʌktʃɚ/', 'infrastructure', 3);
INSERT INTO `words` VALUES (33565, 'They would make infrequent visits to the house.', 'adj. 不频发的,不常见的', '/in\'fri:kwənt | ɪn\'friːkw(ə)nt | ɪn\'frikwənt/', 'infrequent', 3);
INSERT INTO `words` VALUES (33566, 'Jeremy does play cricket, but very infrequently.', 'adv. 罕见地, 稀少的', '/in\'fri:kwəntli/', 'infrequently', 3);
INSERT INTO `words` VALUES (33567, 'Her actions infuriated her mother.', 'vt. 激怒', '/ɪn\'fjurieɪt | ɪn\'fjʊrɪet/', 'infuriate', 3);
INSERT INTO `words` VALUES (33568, 'He brought a tremendous infusion of hope to the people.', 'n. 灌输', '/in\'fju:ʒən | ɪn\'fjuːʒ(ə)n | ɪn\'fjuʒn/', 'infusion', 3);
INSERT INTO `words` VALUES (33569, 'Many fish have ingenious ways of protecting their eggs from predators.', 'adj. 设计独特的，巧妙的', '/in\'dʒi:njəs | ɪn\'dʒiːnɪəs | ɪn\'dʒinɪəs/', 'ingenious', 3);
