INSERT INTO `words` VALUES (33602, 'She’s served on innumerable committees.', 'adj. 无数的,数不清的', '/i\'nuj:mərəbl | ɪ\'njuːm(ə)rəb(ə)l | ɪ\'nʊmərəbl/', 'innumerable', 3);
