INSERT INTO `words` VALUES (33668, 'To be good at the game, you need a reasonable level of intelligence.', 'n. 智力, 聪明', '/ɪn\'telɪdʒ(ə)ns | ɪn\'tɛlɪdʒəns/', 'intelligence', 3);
