INSERT INTO `words` VALUES (33673, 'Young people today are under intense pressure to succeed.', 'adj. 强烈的,激烈的', '/in\'tens | ɪn\'tens | ɪn\'tɛns/', 'intense', 3);
INSERT INTO `words` VALUES (33674, NULL, 'adv. 激烈地；热切地', '/in\'tensli/', 'intensely', 3);
INSERT INTO `words` VALUES (33675, 'In Junethe civil war intensified.', 'v. 加强,强化', '/in\'tensifai | ɪn\'tensɪfaɪ | ɪn\'tɛnsɪfaɪ/', 'intensify', 3);
INSERT INTO `words` VALUES (33676, 'The intensity of the hurricane was frightening.', 'n. 强度,强烈', '/in\'tensəti | ɪn\'tensɪtɪ | ɪn\'tɛnsəti/', 'intensity', 3);
INSERT INTO `words` VALUES (33677, 'a one-week intensive course in English', 'adj. 强烈的, 精深的', '/in\'tensiv | ɪn\'tensɪv | ɪn\'tɛnsɪv/', 'intensive', 3);
INSERT INTO `words` VALUES (33678, NULL, 'adv. 加强地, 集中地', '/in\'tensivli/', 'intensively', 3);
INSERT INTO `words` VALUES (33679, 'She behaved foolishly but with good intent.', 'n. 意图, 目的', '/in\'tent | ɪn\'tent | ɪn\'tɛnt/', 'intent', 3);
INSERT INTO `words` VALUES (33680, 'They went into town with the intention of visiting the library.', 'n. 意图, 目的', '/in\'tenʃən | ɪn\'tenʃ(ə)n | ɪn\'tɛnʃən/', 'intention', 3);
INSERT INTO `words` VALUES (33681, 'I did trip him, but it wasn’t intentional.', 'adj. 故意的,策划的', '/in\'tenʃənəl | ɪn\'tenʃ(ə)n(ə)l | ɪn\'tɛnʃənl/', 'intentional', 3);
INSERT INTO `words` VALUES (33682, 'Or you can choose to accelerate your growth and intentionally devour life and all it offers.', 'adv. 有意地,故意地', '/in\'tenʃənli/', 'intentionally', 3);
INSERT INTO `words` VALUES (33683, 'As we walked alongside each other, she listened intently as I told her about you, about us, about the wonderful times we shared.', 'adv. 专心地, 集中地', '/in\'tentli | ɪn\'tentlɪ | ɪn\'tɛntli/', 'intently', 3);
INSERT INTO `words` VALUES (33684, 'The team of archaeologists found the spot where his bones were originally interred.', 'v. 埋葬', '/in\'tə: | ɪn\'tɜː | ɪn\'tə/', 'inter', 3);
INSERT INTO `words` VALUES (33685, 'While the other children interacted and played together, Ted ignored them.', 'v. 互相作用,互相影响', '/,intə\'rækt | ɪntər\'ækt | ,ɪntɚ\'ækt/', 'interact', 3);
INSERT INTO `words` VALUES (33686, 'But you only get the maximum benefit if you implement all of them, because their power comes from their interaction.', 'n. 交互作用', NULL, 'interaction', 3);
INSERT INTO `words` VALUES (33687, 'interactive computer systems', 'adj. 交互式的,相互作用的', '/,intər\'æktiv | ɪntər\'æktɪv | ,ɪntɚ\'æktɪv/', 'interactive', 3);
INSERT INTO `words` VALUES (33688, 'These two words are almost interchangeable.', 'adj. 可互换的,可交换的', '/,intə\'tʃeindʒəbl | ɪntə\'tʃeɪn(d)ʒəbl | ,ɪntɚ\'tʃendʒəbl/', 'interchangeable', 3);
INSERT INTO `words` VALUES (33689, 'intercity rivalry', 'adj. 城市间的', '/ɪntə\'sɪtɪ | ,ɪntɚ\'sɪti/', 'intercity', 3);
INSERT INTO `words` VALUES (33690, 'In this study, we examine how intercommunity relationships affect the growth of organizational communities.', 'n. 共同性, 共有', '/ɪntəkə\'mjuːnɪtɪ | ,ɪntɚkə\'mjʊnəti/', 'intercommunity', 3);
INSERT INTO `words` VALUES (33691, 'a series of interconnected lakes', 'v. 使互相连接', '/,intəkə\'nekt | ɪntəkə\'nekt | ,ɪntɚkə\'nɛkt/', 'interconnect', 3);
INSERT INTO `words` VALUES (33692, '...the interdependence of nations.', 'n. 互相依赖', '/,intədi\'pendəns,-dənsi | ,ɪntədɪ\'pendəns | ,ɪntɚdɪ\'pɛndəns/', 'interdependence', 3);
INSERT INTO `words` VALUES (33693, 'countries with interdependent economies', 'adj. 相互依赖的,互助的', '/,intədi\'pendənt | ɪntədɪ\'pendənt | ,ɪntɚdɪ\'pɛndənt/', 'interdependent', 3);
INSERT INTO `words` VALUES (33694, 'I watched the first few episodes, but soon lost interest.', 'n. 兴趣，关注；业余爱好；利息；利害关系; vt. 使感兴趣， 引起…关注', '/\'ɪntrəst/', 'interest', 3);
INSERT INTO `words` VALUES (33695, 'Interestingly, none of their three children ever married.', 'adv. 有趣地', '/\'intristiŋli | \'ɪntrəstɪŋlɪ/', 'interestingly', 3);
INSERT INTO `words` VALUES (33696, '...the development of better user interfaces.', 'n. 界面， 分界面； 接口', '/\'ɪntərfeɪs | \'ɪntɚ\'fes/', 'interface', 3);
INSERT INTO `words` VALUES (33697, 'My daughter-in-law said that I was interfering, but I was only trying to help.', 'v. 干涉,妨碍', '/,intə\'fiə | ɪntə\'fɪə | ,ɪntɚ\'fɪr/', 'interfere', 3);
INSERT INTO `words` VALUES (33698, 'Industrial relations should be free from state interference.', 'n. 冲突, 干涉', '/,intə\'fiərəns | ɪntə\'fɪər(ə)ns | ,ɪntɚ\'fɪrəns/', 'interference', 3);
INSERT INTO `words` VALUES (33699, 'One possibility, according to Hogan, would be to use a device called an atom interferometer.', 'n. 干涉计', '/,intəfə\'rɔmitə | ,ɪntəfə\'rɒmɪtə | ,ɪntɚfɪ\'rɑmətɚ/', 'interferometer', 3);
INSERT INTO `words` VALUES (33700, 'Intergalactic travel remains just a nice idea.', 'adj. 银河间的, 星际间的', '/,intəɡə\'læktik | ,ɪntəgə\'læktɪk | ,ɪntɚɡə\'læktɪk/', 'intergalactic', 3);
INSERT INTO `words` VALUES (33701, 'This new investigation shows temperature \'spikes\' within some of the interglacial periods over the last 340,000 years.', 'adj. 间冰期的', '/ɪntə\'gleɪsɪəl; -ʃ(ə)l | ,ɪntɚ\'gleʃəl/', 'interglacial', 3);
INSERT INTO `words` VALUES (33702, 'an interim report', 'adj. 暂时的， 过渡的; n. 间歇，过渡期间', '/\'ɪntərɪm/', 'interim', 3);
INSERT INTO `words` VALUES (33703, 'The interior walls are all painted white.', 'adj. 内部的', '/in\'tiəriə | ɪn\'tɪɜːrɪə | ɪn\'tɪrɪɚ/', 'interior', 3);
INSERT INTO `words` VALUES (33704, '‘That’s absolute rubbish!’ he interjected.', 'v. 插嘴, 突然插入', '/,intə\'dʒekt | ,ɪntə\'dʒekt | ,ɪntɚ\'dʒɛkt/', 'interject', 3);
INSERT INTO `words` VALUES (33705, 'a puzzle with 500 interlocking pieces', 'v. 互锁', '/,intə\'lɔk, \'intəlɔk | ɪntə\'lɒk | \'ɪntɚlɑk/', 'interlock', 3);
INSERT INTO `words` VALUES (33706, 'an intermediate stage during which the disease is dormant', 'adj. 中间的 n媒介', '/,intə\'mi:djət, -dieit | ,ɪntə\'miːdɪət | ,ɪntɚ\'midɪət/', 'intermediate', 3);
INSERT INTO `words` VALUES (33707, 'The weather forecast is for sun, with intermittent showers.', 'adj. 间歇的，断断续续的', '/ɪntə\'mɪt(ə)nt | ,ɪntɚ\'mɪtənt/', 'intermittent', 3);
INSERT INTO `words` VALUES (33708, 'The malaria victim fevers intermittently.', 'adv. 间歇地', '/intə\'mitəntli/', 'intermittently', 3);
INSERT INTO `words` VALUES (33709, '...a medical intern.', 'n. 实习生; vt. 拘禁， 软禁', '/\'ɪntɜːn | \'ɪntɝn/', 'intern', 3);
INSERT INTO `words` VALUES (33710, 'We have no interest in interfering in the internal affairs of other countries.', 'adj. 内在的,国内的', '/in\'tə:nəl | ɪn\'tɜːn(ə)l | ɪn\'tɝnl/', 'internal', 3);
INSERT INTO `words` VALUES (33711, 'There is an Afghan police force now and an Afghan army that are building up to be able to protect the people of Afghanistan internally like we all want them to.', 'adv. 内部地, 国内地', '/in\'tə:nəli/', 'internally', 3);
INSERT INTO `words` VALUES (33712, 'the response of the international community', 'adj. 国际的,世界的', '/ɪntə\'næʃ(ə)n(ə)l | ,ɪntɚ\'næʃnəl/', 'international', 3);
INSERT INTO `words` VALUES (33713, 'These days businesses have to be able to compete internationally.', 'adv. 国际性地, 在国际间', '/,intə\'næʃənəli/', 'internationally', 3);
INSERT INTO `words` VALUES (33714, NULL, 'n. 国际互联网，因特网', '/\'intənet | \'ɪntənet | \'ɪntɚnɛt/', 'internet', 3);
INSERT INTO `words` VALUES (33715, '...an internship in surgery in New York.', 'n. 实习期', '/\'ɪntɜːrnʃɪp | \'ɪntɝnʃɪp/', 'internship', 3);
INSERT INTO `words` VALUES (33716, 'interpersonal skills', 'adj. 人与人之间的, 人际关系的', '/,intə\'pə:sənəl | ɪntə\'pɜːs(ə)n(ə)l | \'ɪntɚ\'pɝsnl/', 'interpersonal', 3);
INSERT INTO `words` VALUES (33717, 'interplanetary space missions', 'adj. 太阳系内的,行星间的', '/,intə\'plænitəri | ɪntə\'plænɪt(ə)rɪ | ,ɪntɚ\'plænətɛri/', 'interplanetary', 3);
INSERT INTO `words` VALUES (33718, '...the interplay of political, economic, social and cultural factors.', 'n. 相互影响', '/\'intəplei, ,intə\'plei, \'in- | \'ɪntəpleɪ | ,ɪntɚ\'plɛi/', 'interplay', 3);
INSERT INTO `words` VALUES (33719, 'Freud’s attempts to interpret the meaning of dreams', 'v. 解释,说明', '/in\'tə:prit | ɪn\'tɜːprɪt | ɪn\'tɝprɪt/', 'interpret', 3);
INSERT INTO `words` VALUES (33720, 'One possible interpretation is that they want you to resign.', 'n. 解释,阐明', '/in,tə:pri\'teiʃən | ɪntɜːprɪ\'teɪʃ(ə)n | ɪn\'tɝprɪ\'teʃən/', 'interpretation', 3);
INSERT INTO `words` VALUES (33721, 'We will be discussing how the interests of state, parent and child interrelate.', 'v. 相互关联， 紧密联系', '/ˌɪntərɪ\'leɪt | \'ɪntɚrɪ\'let/', 'interrelate', 3);
INSERT INTO `words` VALUES (33722, '...the interrelationships between unemployment, crime, and imprisonment.', 'n. 相互关系', '/,intəri\'leiʃənʃip; ,intəri\'leiʃnʃip | ,ɪntərɪ\'leʃnʃɪp/', 'interrelationship', 3);
INSERT INTO `words` VALUES (33723, 'The police interrogated the suspect for several hours.', 'vt. 审问， 讯问， 盘问', '/ɪn\'terəgeɪt | ɪn\'tɛrəɡet/', 'interrogate', 3);
INSERT INTO `words` VALUES (33724, 'Will you stop interrupting me!', 'v. 打断, 妨碍, 插嘴', '/,intə\'rʌpt | ɪntə\'rʌpt | \'ɪntə\'rʌpt/', 'interrupt', 3);
INSERT INTO `words` VALUES (33725, 'For tasks that execute code in a loop, it is common to check for interruption only once per loop iteration.', 'n. 中断, 打断', '/,intə\'rʌpʃən | ɪntə\'rʌpʃn | ,ɪntə\'rʌpʃən/', 'interruption', 3);
INSERT INTO `words` VALUES (33726, 'So tell me about. You have done music, where do these things intersect for you?', 'v. 贯穿, 交叉', '/,intə\'sekt | ɪntə\'sekt | \'ɪntɚ\'sɛkt/', 'intersect', 3);
INSERT INTO `words` VALUES (33727, 'We crossed at a busy intersection.', 'n. 交集, 交叉点', '/,intə\'sekʃən | ɪntə\'sekʃ(ə)n | ,ɪntɚ\'sɛkʃən/', 'intersection', 3);
INSERT INTO `words` VALUES (33728, '...interstate commerce.', 'adj. 州际的', '/\'intəsteit, intə\'s- | ɪntə\'steɪt | \'ɪntɚstet/', 'Interstate', 3);
INSERT INTO `words` VALUES (33729, '...interstellar space.', 'adj. 星际的', '/,intə\'stelə | ,ɪntə\'stelə | ,ɪntɚ\'stɛlɚ/', 'interstellar', 3);
INSERT INTO `words` VALUES (33730, NULL, 'adj. 空隙的, 裂缝的,', '/,ɪntə\'stɪʃ(ə)l | ,ɪntɚ\'stɪʃl/', 'interstitial', 3);
INSERT INTO `words` VALUES (33731, 'Juveniledevelopment of intertidal creatures varies nearly as much as their physicalforms.', 'n&a. 潮间带(的)', '/,intə\'taidəl | ɪntə\'taɪd(ə)l | ,ɪntɚ\'taɪdl/', 'intertidal', 3);
INSERT INTO `words` VALUES (33732, 'Trees, undergrowth and creepers intertwined, blocking our way.', 'v. (使)纠缠,(使)缠绕', '/,intə\'twain | ɪntə\'twaɪn | ,ɪntɚ\'twaɪn/', 'intertwine', 3);
INSERT INTO `words` VALUES (33733, 'He left the room, returning after a short interval with a message.', 'n. 间隔,距离', '/\'intəvəl | \'ɪntəv(ə)l | \'ɪntɚvl/', 'interval', 3);
INSERT INTO `words` VALUES (33734, 'The army will have to intervene to prevent further fighting.', 'v. 干涉，干预', '/,intə\'vi:n | ɪntə\'viːn | ,ɪntɚ\'vin/', 'intervene', 3);
INSERT INTO `words` VALUES (33735, 'During those intervening years Bridget had married her husband Robert.', 'adj. 介于中间的， 发生于期间的', '/ˌɪntər\'viːnɪŋ | ,ɪntɚ\'vinɪŋ/', 'intervening', 3);
INSERT INTO `words` VALUES (33736, 'government intervention to regulate prices', 'n. 干涉', '/,intə\'venʃən | ɪntə\'venʃ(ə)n | ,ɪntɚ\'vɛnʃən/', 'intervention', 3);
INSERT INTO `words` VALUES (33737, 'a portfolio of work presented at interview', 'n. 接见，会见；面谈', '/\'intəvju: | \'ɪntəvjuː | \'ɪntɚvju/', 'interview', 3);
INSERT INTO `words` VALUES (33738, NULL, 'n. 会见者', '/\'ɪntɚvjuɚ/', 'interviewer', 3);
INSERT INTO `words` VALUES (33739, 'For these people, land is inextricably interwoven with life itself.', 'v. 交织， 编结', '/ˌɪntər\'wiːv | ,ɪntɚ\'wiv/', 'interweave', 3);
INSERT INTO `words` VALUES (33740, 'Cholera is an acute intestinal infection caused by ingestion of food or water contaminated with the bacterium Vibrio cholerae.', 'adj. 肠的', '/in\'testinəl | ɪnte\'staɪn(ə)l; ɪn\'testɪn(ə)l | ɪn\'tɛstɪnl/', 'intestinal', 3);
INSERT INTO `words` VALUES (33741, NULL, 'adj. 内部的,国内的', '/in\'testin | ɪn\'testɪn | ɪn\'tɛstɪn/', 'intestine', 3);
INSERT INTO `words` VALUES (33742, 'She thought back over the intimacies they’d shared and the plans they’d made.', 'n. 亲密, 隐私', '/\'intiməsi | \'ɪntɪməsɪ | \'ɪntɪməsi/', 'intimacy', 3);
INSERT INTO `words` VALUES (33743, 'an intimate friend of Picasso’s', 'adj. 亲密的,私人的', '/英 [\'ɪntɪmət] 美 [ˈɪntəmɪt] | \'ɪntɪmət | ˈɪntəmɪt/', 'intimate', 3);
INSERT INTO `words` VALUES (33744, 'Maybe your relationships will be your primary focus for a period of life, as well as learning how to cultivate them more intimately and intelligently.', 'adv. 密切地, 亲密地', '/\'intimitli | ˈɪntəmɪtlɪ/', 'intimately', 3);
INSERT INTO `words` VALUES (33745, 'Attempts to intimidate her failed.', 'v. 胁迫', '/in\'timideit | ɪn\'tɪmɪdeɪt | ɪn\'tɪmɪdet/', 'intimidate', 3);
INSERT INTO `words` VALUES (33746, 'She’s lactose-intolerant (= unable to drink particular types of milk ).', 'adj. 不宽容的, 偏狭的', '/in\'tɔlərənt | ɪn\'tɒl(ə)r(ə)nt | ɪn\'tɑlərənt/', 'intolerant', 3);
INSERT INTO `words` VALUES (33747, 'intonation patterns', 'n. 语调, 声调', '/,intəu\'neiʃən | ɪntə\'neɪʃ(ə)n | ,ɪntə\'neʃən/', 'intonation', 3);
INSERT INTO `words` VALUES (33748, 'Intoxication interferes with memory and thinking, speech and coordination.', 'n. 陶醉,中毒', '/in,tɔksi\'keiʃən | ɪn,tɒksɪ\'keɪʃn | ɪn,tɑksə\'keʃən/', 'intoxication', 3);
INSERT INTO `words` VALUES (33749, 'intrepid explorers', 'adj. 勇敢的， 无畏的', '/ɪn\'trepɪd | ɪn\'trɛpɪd/', 'intrepid', 3);
INSERT INTO `words` VALUES (33750, 'intricate patterns', 'adj. 复杂的,难懂的', '/\'intrikət | \'ɪntrɪkət/', 'intricate', 3);
INSERT INTO `words` VALUES (33751, 'In areas where river deltas inject organic material and dissolved trace elements into the sea, for instance, it’s not clear how all of the intricately related processes will affect water chemistry.', 'adv. 杂乱地, 复杂地', '/\'intrəkitli | \'ɪntrɪkətlɪ | ˈɪntrəkɪtlɪ/', 'intricately', 3);
INSERT INTO `words` VALUES (33752, 'Other people’s houses always intrigued her.', 'v. 激起兴趣,耍阴谋; n. 阴谋，密谋', '/in\'tri:ɡ, \'in- | ɪn\'triːg | \'ɪn\'triɡ/', 'intrigue', 3);
INSERT INTO `words` VALUES (33753, 'The magazine carries an intriguing mixture of high fashion, gossip and racing.', 'adj. 引起兴趣的， 吸引人的', '/ɪn\'triːgɪŋ | ɪn\'triɡɪŋ/', 'intriguing', 3);
INSERT INTO `words` VALUES (33754, 'the intrinsic interest of the subject', 'adj. 内在的, 固有的', '/in\'trinsik,-kəl | ɪn\'trɪnsɪk/', 'intrinsic', 3);
INSERT INTO `words` VALUES (33755, 'You enjoy being with the beloved just as much as, and often even more than, you like doing the intrinsically valuable activities.', 'adv. 内在地, 固有地', '/in\'trinsikəli | ɪn\'trɪnsɪkəlɪ | ɪn\'trɪnsɪkli/', 'intrinsically', 3);
INSERT INTO `words` VALUES (33756, 'Have you two been introduced? Tom, this is Greg.', 'v. 介绍,引进', '/,intrə\'dju:s | ɪntrə\'djuːs | ˌɪntrə\'dus/', 'introduce', 3);
INSERT INTO `words` VALUES (33757, 'Pete, are you going to make the introductions?', 'n. 介绍,传入', '/,intrə\'dʌkʃən | ,ɪntrə\'dʌkʃ(ə)n | ,ɪntrə\'dʌkʃən/', 'introduction', 3);
INSERT INTO `words` VALUES (33758, 'as the chairman said in his introductory remarks', 'adj. 引导的,介绍的', '/,intrə\'dʌktəri | ɪntrə\'dʌkt(ə)rɪ | ,ɪntrə\'dʌktəri/', 'introductory', 3);
INSERT INTO `words` VALUES (33759, 'a shy and introspective person', 'adj. 反省的', '/,intrəu\'spektiv | ɪntrə\'spektɪv | \'ɪntrə\'spɛktɪv/', 'introspective', 3);
INSERT INTO `words` VALUES (33760, 'The press has been blamed for intruding into people\'s personal lives in an unacceptable way.', 'v. 侵入,强挤入', '/in\'tru:d | ɪn\'truːd | ɪn\'trʊd/', 'intrude', 3);
INSERT INTO `words` VALUES (33761, 'The police think the intruder got in through an unlocked window.', 'n. 入侵者', '/in\'tru:də | ɪn\'truːdə | ɪn\'trudɚ/', 'intruder', 3);
INSERT INTO `words` VALUES (33762, 'the unwelcome intrusion of the press', 'n. 闯入, 侵扰', '/in\'tru:ʒən | ɪn\'truːʒ(ə)n | ɪn\'truʒn/', 'intrusion', 3);
INSERT INTO `words` VALUES (33763, 'He seemed to have an intuitive awareness of how I felt.', 'adj. 有直觉力的，直觉到的', '/in\'tju:itiv | ɪn\'tjuːɪtɪv | ɪn\'tuɪtɪv/', 'intuitive', 3);
INSERT INTO `words` VALUES (33764, 'He pays heed to the observations of the Inuit.', 'n. 因纽特人, 因纽特语', '/\'injuit/', 'Inuit', 3);
INSERT INTO `words` VALUES (33765, 'The tidal wave inundated vast areas of cropland.', 'v. 淹没', '/\'inʌndeit, in\'ʌn- | \'ɪnʌndeɪt | \'ɪnʌndet/', 'inundate', 3);
INSERT INTO `words` VALUES (33766, 'The Romans invaded Britain 2,000 years ago.', 'v. 侵略', '/in\'veid | ɪn\'veɪd | ɪn\'ved/', 'invade', 3);
INSERT INTO `words` VALUES (33767, 'Invaders ransacked the town.', 'n. 侵略者', '/in\'veidə | ɪn\'veɪdə(r) | ɪn\'vedɚ/', 'invader', 3);
INSERT INTO `words` VALUES (33768, 'Without the right date stamped on it, your ticket will be invalid.', 'adj. 无效的； 无可靠根据的， 站不住脚的; n. 病弱者， 残疾者', '/ˈɪnvəlɪd；ɪnˈvælɪd/', 'invalid', 3);
INSERT INTO `words` VALUES (33769, 'Eluding is the invariable game.', 'n&a. 不变的, 永恒的', '/in\'vεəriəbl | ɪn\'veərɪəb(ə)l | ɪn\'vɛrərɪəbl/', 'invariable', 3);
INSERT INTO `words` VALUES (33770, 'It invariably rains when I go there.', 'adv. 不变地，始终如一地', '/in\'vɛəriəbli | ɪn\'veərɪəblɪ | ɪn\'vɛrɪəbli/', 'invariably', 3);
INSERT INTO `words` VALUES (33771, 'the annual invasion of teenagers for the Glastonbury Festival', 'n. 入侵', '/in\'veiʒən | ɪn\'veɪʒ(ə)n | ɪn\'veʒn/', 'invasion', 3);
INSERT INTO `words` VALUES (33772, 'invasive bladder cancers', 'adj. 侵入的， 侵略的； 开刀的', '/ɪn\'veɪsɪv | ɪn\'vesɪv/', 'invasive', 3);
INSERT INTO `words` VALUES (33773, 'Alexander Graham Bell invented the telephone in 1876.', 'v. 发明,创造', '/in\'vent | ɪn\'vent | ɪn\'vɛnt/', 'invent', 3);
INSERT INTO `words` VALUES (33774, 'The dishwasher is a wonderful invention.', 'n. 发明,创造', '/in\'venʃən | ɪn\'venʃ(ə)n | ɪn\'vɛnʃən/', 'invention', 3);
INSERT INTO `words` VALUES (33775, '...Alexander Graham Bell, the inventor of the telephone.', 'n. 发明家', '/in\'ventə | ɪn\'ventə | ɪn\'vɛntɚ/', 'inventor', 3);
INSERT INTO `words` VALUES (33776, '...one inventory of twelve sails for each yacht.', 'n. 详细目录, 存货(清单)', '/\'invəntəri, -tɔ:ri | \'ɪnv(ə)nt(ə)rɪ | \'ɪnvəntɔri/', 'inventory', 3);
INSERT INTO `words` VALUES (33777, 'Clearly, the amount of money people save increases in inverse proportion to the amount they spend.', 'adj. 相反的，反向的; n. 反面； 倒数', '/ˌɪn\'vɜːrs | ,ɪn\'vɝs/', 'inverse', 3);
INSERT INTO `words` VALUES (33778, 'Invert the cake onto a serving plate.', 'vt. 使倒转， 使倒置， 使颠倒', '/ɪn\'vɜːrt | \'ɪnvɝt/', 'invert', 3);
INSERT INTO `words` VALUES (33779, 'The site of the proposed airport is incredibly important for native invertebrate animals … St Helena has about 400 species that occur nowhere else in the world.', 'a&n. 无脊椎的,无骨气的人', '/in\'və:tibrət, -breit | ɪn\'vɜːtɪbrət | ɪn\'vɝtɪbret/', 'invertebrate', 3);
INSERT INTO `words` VALUES (33780, 'I’ve got a few thousand dollars I’m looking to invest.', 'v. 投资，投入', '/in\'vest | ɪn\'vest | ɪn\'vɛst/', 'invest', 3);
INSERT INTO `words` VALUES (33781, 'The state police are investigating the incident.', 'v. 调查, 研究', '/in\'vestiɡeit | ɪn\'vestɪgeɪt | ɪn\'vɛstɪɡet/', 'investigate', 3);
INSERT INTO `words` VALUES (33782, 'The investigation continued for nearly three years.', 'n. 调查,研究', '/in,vesti\'ɡeiʃən | ɪn,vestɪ\'geɪʃ(ə)n | ɪn,vɛstɪ\'ɡeʃən/', 'investigation', 3);
INSERT INTO `words` VALUES (33783, 'police investigators', 'n. 调查人', '/in\'vestiɡeitə | ɪn\'vestɪgeɪtə(r) | ɪn\'vɛstɪɡetɚ/', 'investigator', 3);
INSERT INTO `words` VALUES (33784, 'We plan to buy some property as an investment.', 'n. 投资,可获利的东西', '/in\'vestmənt | ɪn\'ves(t)m(ə)nt | ɪn\'vɛstmənt/', 'investment', 3);
INSERT INTO `words` VALUES (33785, 'The main investor in the project is the French bank Credit National.', 'n. 投资者', '/in\'vestə | ɪn\'vestə | ɪn\'vɛstɚ/', 'investor', 3);
INSERT INTO `words` VALUES (33786, 'Carey’s hope was that the church would be renewed and invigorated.', 'v. 鼓舞', '/in\'viɡəreit | ɪn\'vɪgəreɪt | ɪn\'vɪɡəret/', 'invigorate', 3);
INSERT INTO `words` VALUES (33787, 'The house was surrounded by trees, and invisible from the road.', 'adj. 看不见的, 无形的', '/in\'vizəbl | ɪn\'vɪzɪb(ə)l | ɪn\'vɪzəbl/', 'invisible', 3);
INSERT INTO `words` VALUES (33788, NULL, 'adv. 看不见地, 看不出地', '/in\'vizəbli/', 'invisibly', 3);
INSERT INTO `words` VALUES (33789, 'They were always dropping by, usually without invitation.', 'n. 邀请； 请柬； 吸引， 诱惑', '/ˌɪnvɪ\'teɪʃn | ˌɪnvɪˈteɪʃn/', 'invitation', 3);
INSERT INTO `words` VALUES (33790, 'I’m afraid I wasn’t invited.', 'v. 邀请；征求', '/in\'vait, \'invait | ɪn\'vaɪt/', 'invite', 3);
INSERT INTO `words` VALUES (33791, 'The log fire looked warm and inviting.', 'adj. 动人的， 诱人的； 引人注目的', '/ɪn\'vaɪtɪŋ/', 'inviting', 3);
INSERT INTO `words` VALUES (33792, 'St. Genevieve is often invoked against plagues.', 'v. 恳求', '/in\'vəuk | ɪn\'vəʊk | ɪn\'vok/', 'invoke', 3);
INSERT INTO `words` VALUES (33793, 'What will the job involve?', 'vt. 包含； 牵涉， 牵连； 使参加', '/ɪn\'vɑːlv | ɪn\'vɑlv/', 'involve', 3);
INSERT INTO `words` VALUES (33794, NULL, 'n. 连累, 包含', '/in\'vɔlvmənt | ɪn\'vɒlvm(ə)nt | ɪn\'vɔlvmənt/', 'involvement', 3);
INSERT INTO `words` VALUES (33795, 'He pushed open the front door, which swung inward with a groan.', 'adv. 向内,在内; adj. 向内的,内在的', '/\'inwəd | \'ɪnwəd | \'ɪnwɚd/', 'inward', 3);
INSERT INTO `words` VALUES (33796, 'The cut burns from the iodine.', 'n. 碘, 碘酒', '/\'aiəudi:n | \'aɪədiːn; -aɪn; -ɪn | aɪədaɪn/', 'iodine', 3);
INSERT INTO `words` VALUES (33797, 'These vibrations turn the ion into a sort of superfast metronome.', 'n. 离子', '/\'aiən | \'aɪən/', 'ion', 3);
INSERT INTO `words` VALUES (33798, 'So if we can figure out the binding energy, we can also figure out how much energy we have to put into our atom in order to a eject or ionize an electron.', 'v. 使离子化 ,电离', '/\'aiənaiz | \'aɪənaɪz/', 'ionize', 3);
INSERT INTO `words` VALUES (33799, 'So why go to Iraq when you can go to Canada?', 'n. 伊拉克共和国', '/i\'rɑ:k; i\'ræk | ɪ\'rɑ:k | ɪ\'rɑk/', 'Iraq', 3);
INSERT INTO `words` VALUES (33800, 'small iridescent blue flies', 'adj. 闪光的，现晕光的', '/,iri\'desənt, \'aiəri- | ,ɪrɪ\'des(ə)nt | ,ɪrɪ\'dɛsnt/', 'iridescent', 3);
INSERT INTO `words` VALUES (33801, 'Analyzing the fossils at this small site, they counted 52 distinct species just below the iridium layer.', 'n. [化]铱', '/ai\'ridiəm, i\'ri- | ɪ\'rɪdɪəm; aɪ- | ɪ\'rɪdɪəm/', 'iridium', 3);
INSERT INTO `words` VALUES (33802, 'I am starting to sense that maybe I and people like me are to blame because it is we, the Irish people, who are paying with our jobs, livelihoods, health care and education.', 'n&a. 爱尔兰人(的),爱尔兰语（的）', '/\'aiəriʃ | ˈaɪrɪʃ/', 'Irish', 3);
INSERT INTO `words` VALUES (33803, 'Your car was stolen at the police station! How ironic!', 'adj. 说反话的， 讽刺的； 出乎意料的', '/aɪ\'rɑːnɪk | aɪ\'rɑnɪk/', 'ironic', 3);
INSERT INTO `words` VALUES (33804, 'Ironically, his cold got better on the last day of his holiday.', 'adv. 具有讽刺意味地；嘲讽地', '/ai\'rɔnikli | aɪ\'rɒnɪklɪ | aɪ\'rɑnɪkli/', 'ironically', 3);
INSERT INTO `words` VALUES (33805, '...the ironwork on the doors.', 'n. 铁制品', '/\'aiənwə:k | \'aɪənwɜːk/', 'ironwork', 3);
INSERT INTO `words` VALUES (33806, 'Life is full of little ironies.', 'n. 反话, 讽刺', '/\'aiərəni | \'aɪrənɪ | \'aɪrəni/', 'irony', 3);
INSERT INTO `words` VALUES (33807, 'Once before, Hutter had been in the hands of the Iroquois, and a few skins had readily effected his release.', 'n. 易洛魁族人', '/\'irəkwɔiz/', 'Iroquois', 3);
INSERT INTO `words` VALUES (33808, 'an irrational fear of flying', 'adj. 无理性的, 失去理性的; n. 无理数', '/i\'ræʃənəl | ɪ\'ræʃ(ə)n(ə)l | ɪ\'ræʃənl/', 'irrational', 3);
INSERT INTO `words` VALUES (33809, NULL, 'adv. 无理性地,不合理地', '/i\'ræʃənli/', 'irrationally', 3);
INSERT INTO `words` VALUES (33810, 'a jagged, irregular coastline', 'adj. 不规则的,无规律的', '/i\'reɡjulə | ɪ\'regjʊlə | ɪ\'rɛɡjəlɚ/', 'irregular', 3);
INSERT INTO `words` VALUES (33811, 'Good golfers do better if they give themselves little time to prepare for their shots--and even better if they are distracted by researchers asking them to count irregularly spaced sounds.', 'adv. 不规则地,不整齐地', '/i\'regjuləli/', 'irregularly', 3);
INSERT INTO `words` VALUES (33812, 'We’re focussing too much on irrelevant details.', 'adj. 不相干的,不切题的', '/i\'reləvənt | ɪ\'relɪv(ə)nt | ɪ\'rɛləvənt/', 'irrelevant', 3);
INSERT INTO `words` VALUES (33813, 'Extensive mining will cause irreparable damage to the area.', 'adj. 无法修复的，不能挽回的', '/i\'repərəbl | ɪ\'rep(ə)rəb(ə)l | ɪ\'rɛpərəbl/', 'irreparable', 3);
INSERT INTO `words` VALUES (33814, 'I was overcome by an irresistible urge to cry.', 'adj. 不可抵抗的,不能压制的', '/,iri\'zistəbl | ɪrɪ\'zɪstɪb(ə)l | ,ɪrɪ\'zɪstəbl/', 'irresistible', 3);
INSERT INTO `words` VALUES (33815, 'It was highly irresponsible of him to leave the children on their own in the pool.', 'adj. 不负责任的, 不可靠的', '/,iri\'spɔnsəbl | ˌɪrɪˈspɒnsəbl | ,ɪrɪ\'spɑnsəbl/', 'irresponsible', 3);
INSERT INTO `words` VALUES (33816, 'If a pastor doesn\'t bring up the cohabitation issue, they\'re acting irresponsibly.', 'adv. 不负责任地,不可靠地', '/,iri\'spɔnsəbli/', 'irresponsibly', 3);
INSERT INTO `words` VALUES (33817, 'He added humor, irreverence, and a strong speaking style that captivated the audience.', 'adj. 不尊敬的', '/i\'revərəns | ɪ\'rev(ə)r(ə)ns | ɪ\'rɛvərəns/', 'irreverence', 3);
INSERT INTO `words` VALUES (33818, 'his irreverent sense of humour', 'adj. 不敬的, 无礼的', '/i\'revərənt | ɪ\'rev(ə)r(ə)nt | ɪ\'rɛvərənt/', 'irreverent', 3);
INSERT INTO `words` VALUES (33819, 'Fossil fuels have caused irreversible damage to the environment.', 'adj. 不可逆的,不能取消的', '/,iri\'və:səbl | ɪrɪ\'vɜːsɪb(ə)l | ,ɪrɪ\'vɝsəbl/', 'irreversible', 3);
INSERT INTO `words` VALUES (33820, 'The water in Lake Powell is used to irrigate the area.', 'v. 灌溉', '/\'iriɡeit | \'ɪrɪgeɪt | \'ɪrəget/', 'irrigate', 3);
INSERT INTO `words` VALUES (33821, 'Rivers and lakes provide us with water transport and irrigation.', 'n. 灌溉', '/,iri\'ɡeiʃən | ˌɪrɪˈɡeʃn/', 'irrigation', 3);
INSERT INTO `words` VALUES (33822, NULL, 'n. 过敏性, 兴奋性', '/,iritə\'biləti | ,ɪrɪtə\'bɪlɪtɪ | ,ɪrətə\'bɪləti/', 'irritability', 3);
INSERT INTO `words` VALUES (33823, 'Jo was tired, irritable, and depressed.', 'adj. 急躁的， 易怒的； 易受刺激的； 过敏的', '/\'ɪrɪtəbl/', 'irritable', 3);
INSERT INTO `words` VALUES (33824, 'It really irritates me when he doesn’t help around the house.', 'v. 激怒, 使急躁', '/\'iriteit | \'ɪrɪteɪt | \'ɪrɪtet/', 'irritate', 3);
INSERT INTO `words` VALUES (33825, 'The islanders endured centuries of exploitation.', 'n. 岛上居民', '/\'ailəndə | \'aɪləndə | \'aɪləndɚ/', 'islander', 3);
INSERT INTO `words` VALUES (33826, 'We have looked at Lord Foster\'s plan and he appears to want to place his fantasy Isle of Grain airport on top of the LNG plant and a power station.', 'n. ( 小)岛', '/ail | aɪl/', 'Isle', 3);
INSERT INTO `words` VALUES (33827, 'The town was isolated by the floods.', 'v. 使隔离,使孤立', '/\'aisəleit, -lit | \'aɪsəleɪt | aɪslˌet/', 'isolate', 3);
INSERT INTO `words` VALUES (33828, 'Because of its geographical isolation, the area developed its own unique culture.', 'n. 隔离，孤立', '/\'aisə\'leiʃən | aɪsə\'leɪʃ(ə)n | ,aɪsə\'leʃən/', 'isolation', 3);
INSERT INTO `words` VALUES (33829, '...tritium, a radioactive isotope of hydrogen.', 'n. 同位素', '/\'aisəutəup | \'aɪsətəʊp | \'aɪsə\'top/', 'isotope', 3);
INSERT INTO `words` VALUES (33830, 'The variations in isotopic ratios take place on the right time scale, and they mirror those seen in modern corals, he notes.', 'adj. 同位素的,合痕的', '/,aisəu\'tɔpik/', 'isotopic', 3);
INSERT INTO `words` VALUES (33831, 'Our only problem is with Israel.', 'n. [地名] 以色列', '/\'izreiəl | ˈɪzreɪəl | ˈɪzrɪəl/', 'Israel', 3);
INSERT INTO `words` VALUES (33832, 'Abortion is a highly controversial issue.', 'n&v. 问题,分发,颁布', '/\'iʃju:, \'isju: | \'ɪʃuː; \'ɪsjuː | \'ɪʃu/', 'issue', 3);
INSERT INTO `words` VALUES (33833, NULL, 'n&a. 意大利人(的), 意大利语（的）', '/i\'tæljən | ɪˈtælɪən | ɪˈtæljən/', 'Italian', 3);
INSERT INTO `words` VALUES (33834, 'They decided to swan around Italy this summer.', 'n. 意大利(欧洲南部国家)', '/\'itəli | \'ɪtəlɪ/', 'Italy', 3);
INSERT INTO `words` VALUES (33835, 'He opened the cardboard box and took out each item.', 'n. 项目,条款', '/\'aɪtəm/', 'item', 3);
INSERT INTO `words` VALUES (33836, 'The cat lay on the sofa, washing itself.', 'pron. 它自己', '/ɪt\'self | ɪt\'sɛlf/', 'itself', 3);
INSERT INTO `words` VALUES (33837, 'an ivory chess set', 'n. 象牙； 象牙制品； 象牙色， 乳白色', '/\'aɪvəri/', 'ivory', 3);
INSERT INTO `words` VALUES (33838, '...a black leather jacket.', 'n. 夹克,护封; v. 给穿夹克', '/\'dʒækɪt/', 'jacket', 3);
INSERT INTO `words` VALUES (33839, 'a jade necklace', 'n. 玉，翡翠', '/dʒeid | dʒeɪd | dʒed/', 'jade', 3);
INSERT INTO `words` VALUES (33840, 'We always have snow in January.', 'n. 一月(略作Jan)', '/\'dʒænjuəri | \'dʒænjʊ(ə)rɪ | \'dʒænjʊ\'ɛri/', 'January', 3);
INSERT INTO `words` VALUES (33841, NULL, 'n. 日本', '/dʒə\'pæn/', 'Japan', 3);
INSERT INTO `words` VALUES (33842, 'The Japanese women salute the people with formal bows in welcome.', 'n&a. 日本人(的), 日语（的）', '/,dʒæpə\'ni:z | ˌdʒæpə\'ni:z | ,dʒæpə\'niz/', 'Japanese', 3);
INSERT INTO `words` VALUES (33843, 'a jam jar', 'n. 罐子 v刺激，震动', '/dʒɑ: | dʒɑː | dʒɑr/', 'jar', 3);
INSERT INTO `words` VALUES (33844, 'He punched him on the jaw.', 'n. 颚,下巴', '/dʒɔ: | dʒɔː | dʒɔ/', 'jaw', 3);
INSERT INTO `words` VALUES (33845, NULL, 'n. 颚骨, 下颚骨, 信用 v赊买', '/\'dʒɔ:bəun | \'dʒɔːbəʊn | \'dʒɔbon/', 'jawbone', 3);
INSERT INTO `words` VALUES (33846, NULL, 'n. 松鸡；鸟', '/dʒei | dʒeɪ | dʒe/', 'jay', 3);
INSERT INTO `words` VALUES (33847, 'a jazz band', 'n. 爵士乐', '/dʒæz/', 'jazz', 3);
INSERT INTO `words` VALUES (33848, 'Sexual jealousy is a common motive for murder.', 'n. 嫉妒,猜疑', '/\'dʒeləsi | \'dʒeləsɪ | \'dʒɛləsi/', 'jealousy', 3);
INSERT INTO `words` VALUES (33849, NULL, 'n. 牛仔裤', '/dʒi:n, dʒein | dʒiːn | dʒɪn/', 'jean', 3);
INSERT INTO `words` VALUES (33850, '...a young man in jeans and a worn T-shirt.', 'n. 牛仔裤', '/dʒi:nz | dʒɪːnz/', 'jeans', 3);
INSERT INTO `words` VALUES (33851, 'raspberry jelly', 'n. 果冻， 胶状物', '/\'dʒeli | \'dʒɛli/', 'jelly', 3);
INSERT INTO `words` VALUES (33852, 'But many marine experts have been saying for several years that we need to start loving jellyfish – because in the not too distant future, they may be the most plentiful marine species around.', 'n. 水母', '/\'dʒelifiʃ | \'dʒelɪfɪʃ | \'dʒɛlɪfɪʃ/', 'jellyfish', 3);
INSERT INTO `words` VALUES (33853, 'large-scale military offensives which could jeopardize the UN peace process', 'vt. 破坏， 危及', '/\'dʒepərdaɪz | \'dʒɛpɚdaɪz/', 'jeopardize', 3);
INSERT INTO `words` VALUES (33854, 'He owns a private jet.', 'n. 喷气式飞机', '/dʒet | jɛt | dʒɛt/', 'jet', 3);
INSERT INTO `words` VALUES (33855, 'She loved dressing up and wearing priceless jewels.', 'n. 宝石', '/\'dʒu:əl | \'dʒuːəl | \'dʒuəl/', 'jewel', 3);
INSERT INTO `words` VALUES (33856, 'She wears a lot of gold jewelry.', 'n. [总称]珠宝', '/\'dʒu:əlri | \'dʒuːəlrɪ/', 'jewellery', 3);
INSERT INTO `words` VALUES (33857, 'We have purchased some valuable jewelry.', 'n. 珠宝', '/\'dʒu:əlri | \'dʒuːəlrɪ | \'dʒʊəlri/', 'jewelry', 3);
INSERT INTO `words` VALUES (33858, 'Then, she took Sarah Orne Jewett\'s suggestion to write novels about Nebraska life.', 'n. 朱厄特（姓氏）', '/\'dʒu:it/', 'Jewett', 3);
INSERT INTO `words` VALUES (33859, '\"No doubt he\'ll give me the chance to fight him again,\" he jibed.', 'v. 嘲笑, 与一致, 使转向', '/dʒaɪb/', 'jibe', 3);
INSERT INTO `words` VALUES (33860, 'Do you enjoy your job?', 'n. 工作,职业', '/dʒɔb | dʒɒb/', 'job', 3);
INSERT INTO `words` VALUES (33861, 'These are the differences between the responsibilities of a broker and a jobber .', 'n. 临时工, 批发商', '/\'dʒɔbə | \'dʒɒbə | \'dʒɑbɚ/', 'jobber', 3);
INSERT INTO `words` VALUES (33862, 'I go jogging every morning.', 'vi. 慢跑； 轻轻触碰', '/dʒɑːg | dʒɑɡ/', 'jog', 3);
INSERT INTO `words` VALUES (33863, 'When did you join the Labour Party?', 'v. 参加,加入,连接', '/dʒɔin | dʒɒɪn | dʒɔɪn/', 'join', 3);
INSERT INTO `words` VALUES (33864, 'John Harrison, a working-class joiner with relatively little education eventually won the prize after building a series of clocks, each improving on the previous one.', 'n. 工匠', '/\'dʒɔinə | \'dʒɒɪnə | \'dʒɔɪnɚ/', 'joiner', 3);
INSERT INTO `words` VALUES (33865, 'It basically is from joinery board in release, also have in coating and paint a few.', 'n. 木工职业', '/\'dʒɔinəri | \'dʒɒɪnərɪ | \'dʒɔɪnəri/', 'joinery', 3);
INSERT INTO `words` VALUES (33866, 'What should I use to seal the joint between the carport roof and the house wall?', 'n. 关节；接头', '/dʒɔint | dʒɒɪnt | dʒɔɪnt/', 'joint', 3);
INSERT INTO `words` VALUES (33867, 'I couldn’t go out with someone for a joke, could you?', 'n. 笑话, 玩笑', '/dʒəuk | dʒəʊk | dʒok/', 'joke', 3);
INSERT INTO `words` VALUES (33868, 'We jolted along rough wet roads through an endless banana plantation.', 'v& n. (使)颠簸；震动', '/dʒəult | dʒəʊlt; dʒɒlt | dʒolt/', 'jolt', 3);
INSERT INTO `words` VALUES (33869, 'Could you just jot his name on there?', 'vt. 草草记下， 匆匆记下', '/dʒɑːt | dʒɑt/', 'jot', 3);
INSERT INTO `words` VALUES (33870, 'the British Medical Journal', 'n. 定期刊物, 杂志', '/\'dʒə:nəl | \'dʒɜːn(ə)l | \'dʒɝnl/', 'journal', 3);
INSERT INTO `words` VALUES (33871, 'a career in journalism', 'n. 新闻业；新闻工作', '/\'dʒə:nəlizəm | \'dʒɜːn(ə)lɪz(ə)m | \'dʒɝnl\'ɪzəm/', 'journalism', 3);
INSERT INTO `words` VALUES (33872, 'a well-known journalist and broadcaster', 'n. 新闻记者,从事新闻杂志业的人', '/\'dʒə:nəlist | \'dʒɜːn(ə)lɪst | \'dʒɝnəlɪst/', 'journalist', 3);
INSERT INTO `words` VALUES (33873, 'the friends they made on the journey', 'n. 旅行', '/\'dʒə:ni | \'dʒɜːnɪ | \'dʒɝni/', 'journey', 3);
INSERT INTO `words` VALUES (33874, 'The choice was to be a journeyman developer or become a manager, and I\'ve never wanted to be a manager -- at least not a manager who went for an MBA and had ambitions to be a captain of industry.', 'n. 熟练工人', '/\'dʒə:nimən | \'dʒɜːnɪmən | \'dʒɝnɪmən/', 'journeyman', 3);
INSERT INTO `words` VALUES (33875, 'the look of joy on her face', 'n. 欢乐, 喜悦', '/dʒɔi | dʒɒɪ | dʒɔɪ/', 'joy', 3);
INSERT INTO `words` VALUES (33876, 'a joyous occasion', 'adj. 快乐的, 高兴的', '/\'dʒɔiəs | \'dʒɒɪəs | \'dʒɔɪəs/', 'joyous', 3);
INSERT INTO `words` VALUES (33877, 'The trial judge specifies the number of years to be spent in prison.', 'n. 法官,裁判员 v断定,裁决', '/dʒʌdʒ/', 'judge', 3);
INSERT INTO `words` VALUES (33878, 'I’ve known him for years and I trust his judgment.', 'n. 判断', '/\'dʒʌdʒmənt/', 'judgment', 3);
INSERT INTO `words` VALUES (33879, 'Soon she was juggling five eggs.', 'v&n. 玩杂耍', '/\'dʒʌɡl | \'dʒʌg(ə)l/', 'juggle', 3);
