INSERT INTO `words` VALUES (34463, 'the mellow golden light of early evening', 'adj. 醇香的；柔和的；成熟的; v. 醇香； 柔和； 成熟', '/\'melou | \'mɛlo/', 'mellow', 3);
INSERT INTO `words` VALUES (34464, 'Their music is loud and not very melodic.', 'adj. 有旋律的,调子美妙的', '/me\'lɔdik | mɪ\'lɒdɪk | mə\'lɑdɪk/', 'melodic', 3);
INSERT INTO `words` VALUES (34465, 'He spoke in a quiet melodious voice.', 'adj. 旋律优美的， 悦耳的', '/mə\'loudiəs | mə\'lodɪəs/', 'melodious', 3);
INSERT INTO `words` VALUES (34466, 'He was behaving like a character in a Victorian melodrama.', 'n. 情节剧', '/\'melə,drɑ:mə, -dræmə | \'melə(ʊ)drɑːmə | \'mɛlədrɑmə/', 'melodrama', 3);
INSERT INTO `words` VALUES (34467, 'They played some lovely melodies.', 'n. 旋律，曲调', '/\'melədi | \'melədɪ | \'mɛlədi/', 'melody', 3);
INSERT INTO `words` VALUES (34468, 'It was warmer now, and the snow was beginning to melt.', 'v. (使)融化,(使)消散,(使)逐渐消失', '/melt | mɛlt/', 'melt', 3);
INSERT INTO `words` VALUES (34469, NULL, 'n. 彻底垮台', '/\'meltdaun | \'meltdaʊn | \'mɛltdaʊn/', 'meltdown', 3);
INSERT INTO `words` VALUES (34470, 'No one quite knows why glaciers and ice shelves are melting so fast, or how a meltwater lake on the Greenland ice sheet covering six square kilometres could drain away in 24 hours, as it did in 2006.', 'n. 冰雪融化成的水', '/\'melt,wɔ:tə | \'meltwɔːtə(r) | \'mɛlt,wɔtɚ/', 'meltwater', 3);
INSERT INTO `words` VALUES (34471, 'The majority of union members voted in favour of a strike.', 'n. 成员,会员', '/\'membə | \'mɛmbɚ/', 'member', 3);
INSERT INTO `words` VALUES (34472, 'You should carry your membership card with you at all times.', 'n. 成员资格,全体会员', '/\'membəʃɪp | \'mɛmbɚʃɪp/', 'membership', 3);
INSERT INTO `words` VALUES (34473, 'Loud noise can damage the delicate membrane in the ear.', 'n. 薄膜； 细胞膜', '/\'membreɪn | \'mɛmbren/', 'membrane', 3);
INSERT INTO `words` VALUES (34474, 'I sent him a memo reminding him about the meeting.', 'n. 备忘录', '/\'memou | \'mɛmo/', 'memo', 3);
INSERT INTO `words` VALUES (34475, 'We want to make this a truly memorable day for the children.', 'adj. 难忘的,重大的', '/\'memərəbl | \'mem(ə)rəb(ə)l | \'mɛmərəbl/', 'memorable', 3);
INSERT INTO `words` VALUES (34476, '...a memorandum from the Department of Defense on its role.', 'n. 备忘录, 便笺', '/,memə\'rændəm | memə\'rændəm | ,mɛmə\'rændəm/', 'memorandum', 3);
INSERT INTO `words` VALUES (34477, 'Building a memorial to Columbus has been his lifelong dream.', 'n. 纪念物, 纪念馆', '/英 [mə\'mɔ:rɪəl] 美 [məˈmɔriəl, -ˈmor | mə\'mɔːrɪəl | mə\'morɪəl/', 'memorial', 3);
INSERT INTO `words` VALUES (34478, 'He studied his map, trying to memorize the way to Rose\'s street.', 'v. 记住, 记忆', '/\'meməraiz | \'meməraɪz | \'mɛmə\'raɪz/', 'memorize', 3);
INSERT INTO `words` VALUES (34479, 'He has lots of happy memories of his stay in Japan.', 'n. 记忆(力),回忆', '/\'meməri | \'mem(ə)rɪ | \'mɛməri/', 'memory', 3);
INSERT INTO `words` VALUES (34480, NULL, 'n. 门诺派教徒', '/\'menənait | \'mɛnən,aɪt/', 'mennonite', 3);
INSERT INTO `words` VALUES (34481, 'The centre provides help for people suffering from mental illness .', 'adj. 精神的,智力的', '/\'mentəl | \'ment(ə)l | \'mɛntl/', 'mental', 3);
INSERT INTO `words` VALUES (34482, 'Above all be mentally prepared for the rigors of each trading day from the time you get up each morning until you go to bed at night.', 'adv. 精神上, 智力上', '/\'mentəli | \'ment(ə)lɪ | \'mɛntli/', 'mentally', 3);
INSERT INTO `words` VALUES (34483, 'Was my name mentioned at all?', 'v. 提及， 说起', '/\'menʃn | \'mɛnʃən/', 'mention', 3);
INSERT INTO `words` VALUES (34484, 'mercantile law', 'adj. 贸易的,商业的', '/\'mə:kəntail, -til | \'mɜːk(ə)ntaɪl | \'mɝkəntɪl/', 'mercantile', 3);
INSERT INTO `words` VALUES (34485, NULL, 'n. 商品,货物 v买卖', NULL, 'merchandis', 3);
INSERT INTO `words` VALUES (34486, 'A range of official Disney merchandise was on sale.', 'n. 商品, 货物', '/\'mə:tʃəndaiz, -dais | \'mɜːtʃ(ə)ndaɪs; -z | \'mɝtʃəndaɪs/', 'merchandise', 3);
INSERT INTO `words` VALUES (34487, 'He had a job with an Edinburgh wine merchant.', 'n. 商人', '/\'mə:tʃənt | \'mɜːtʃ(ə)nt | \'mɝtʃənt/', 'merchant', 3);
INSERT INTO `words` VALUES (34488, 'a merciless attack', 'adj. 残忍的；无情的', '/\'mə:silis | \'mɜːsɪlɪs/', 'merciless', 3);
INSERT INTO `words` VALUES (34489, 'Some thieves have eaten off their irons with mercury water.', 'n. 水银, 汞', '/\'mɝkjəri | \'mɜːrkjəri/', 'mercury', 3);
INSERT INTO `words` VALUES (34490, 'He showed no mercy to his enemies.', 'n. 仁慈,宽恕,怜悯', '/\'mə:si | \'mɜːsɪ | \'mɝsi/', 'mercy', 3);
INSERT INTO `words` VALUES (34491, 'She lost the election by a mere 20 votes.', 'adj. 仅仅的,起码的', '/miə | mɪə | mɪr/', 'mere', 3);
INSERT INTO `words` VALUES (34492, 'He’s merely a boy – you can’t expect him to understand.', 'adv. 仅仅, 只, 不过', '/\'miəli | \'mɪəlɪ | \'mɪrli/', 'merely', 3);
INSERT INTO `words` VALUES (34493, 'The company plans to merge its subsidiaries in the US.', 'v. 结合,合并', '/mə:dʒ | mɜːdʒ | mɝdʒ/', 'merge', 3);
INSERT INTO `words` VALUES (34494, 'Yes this is the…is the prime meridian if you like.', 'n. 子午线， 经线', '/mə\'rɪdiən | mə\'rɪdɪən/', 'meridian', 3);
INSERT INTO `words` VALUES (34495, 'The merit of the report is its realistic assessment of the changes required.', 'n. 优点，功绩; v. 值得', '/\'merit | \'merɪt | \'mɛrɪt/', 'merit', 3);
INSERT INTO `words` VALUES (34496, 'But the little mermaid had no occasion to do this, for the polypi sprang back in terror when they caught sight of the glittering draught, which shone in her hand like a twinkling star.', 'n. 美人鱼', '/\'mə:meid | \'mɜːmeɪd | \'mɝmed/', 'mermaid', 3);
INSERT INTO `words` VALUES (34497, 'The windows were covered in wire mesh to keep out flies.', 'n. 网，筛孔', '/meʃ | mɛʃ/', 'mesh', 3);
INSERT INTO `words` VALUES (34498, 'The first time I saw Diana I was mesmerized by her beauty.', 'v. 施催眠术', '/\'mezməraiz, \'mes- | \'mɛzməraɪz/', 'mesmerize', 3);
INSERT INTO `words` VALUES (34499, NULL, 'adj. 中石器时代的; n. 中石器时代', '/ˌmesə\'liθik | ˌmiːzə(ʊ)ˈlɪθɪk/', 'Mesolithic', 3);
INSERT INTO `words` VALUES (34500, NULL, 'n. 美索不达米亚（两河流域）', NULL, 'mesopotamian', 3);
INSERT INTO `words` VALUES (34501, NULL, 'n&a. 中生代(的)', '/,mesəu\'zəuik; ,mez-/', 'mesozoic', 3);
INSERT INTO `words` VALUES (34502, 'The mesquite common on North American deserts in both tree and shrub forms, does not begin to grow above ground until its root system is completely developed, ensuring the plant a supply of moisture.', 'n. 豆科灌木', '/\'meski:t | \'meskiːt; me\'skiːt/', 'mesquite', 3);
INSERT INTO `words` VALUES (34503, 'What a mess!', 'n. 混乱, 脏乱; v. 弄乱', '/mes | mɛs/', 'mess', 3);
INSERT INTO `words` VALUES (34504, 'He left a message saying he would probably be a little late.', 'n. 消息,信息', '/\'mesidʒ | \'mesɪdʒ | \'mɛsɪdʒ/', 'message', 3);
INSERT INTO `words` VALUES (34505, 'a messy room', 'adj. 肮脏的, 凌乱的', '/\'mesi | \'mesɪ | \'mɛsi/', 'messy', 3);
INSERT INTO `words` VALUES (34506, 'Exercise can increase your metabolic rate.', 'adj. 新陈代谢的', '/,metə\'bɔlik,-kəl | ,metə\'bɒlɪk | ,mɛtə\'bɑlɪk/', 'metabolic', 3);
INSERT INTO `words` VALUES (34507, 'This drug speeds up your metabolism.', 'n. 新陈代谢', '/mi\'tæbəlizəm, me- | mɪ\'tæbəlɪz(ə)m | mɛ\'tæbəlɪzəm/', 'metabolism', 3);
INSERT INTO `words` VALUES (34508, 'Diabetics cannot metabolize glucose properly.', 'v. 产生代谢变化', '/mi\'tæbəlaiz, me- | mɪ\'tæbəlaɪz | mɛ\'tæbəlaɪz/', 'metabolize', 3);
INSERT INTO `words` VALUES (34509, 'The gate is made of metal.', 'n. 金属; v. (以金属)覆盖、装配', '/\'metəl | \'met(ə)l | \'mɛtl/', 'metal', 3);
INSERT INTO `words` VALUES (34510, 'The key turned in the lock with a loud metallic click.', 'adj. 金属(性)的', '/mi\'tælik, me- | mɪ\'tælɪk | mə\'tælɪk/', 'metallic', 3);
INSERT INTO `words` VALUES (34511, NULL, 'n. 冶金, 冶金术', '/me\'tælədʒi, \'metələ:dʒi | mɪ\'tælədʒɪ; \'met(ə),lɜːdʒɪ | \'mɛtəlɝdʒi/', 'metallurgy', 3);
INSERT INTO `words` VALUES (34512, 'a huge collection of antique metalwork', 'n. 金属制品', '/\'metəlwə:k | \'met(ə)lwɜːk/', 'metalwork', 3);
INSERT INTO `words` VALUES (34513, 'Some scholars believe that this astrolabe was created by the prince in collaboration with an unnamed metalworker.', 'n. 金工工人', '/\'metəl,wə:kə/', 'metalworker', 3);
INSERT INTO `words` VALUES (34514, 'This metamorphic rock has been compressed for millions of years.', 'adj. 变质的,变性的', '/,metə\'mɔ:fik | metə\'mɔːfɪk | \'mɛtə\'mɔrfɪk/', 'metamorphic', 3);
INSERT INTO `words` VALUES (34515, 'She uses some wonderful images and metaphors in her writing.', 'n. 隐喻, 暗喻', '/\'metəfə | \'metəfə; -fɔː | \'mɛtəfɚ/', 'metaphor', 3);
INSERT INTO `words` VALUES (34516, 'A lot of scientists don’t like discussing metaphysical matters.', 'adj. 形而上学的, 纯粹哲学的', '/,metə\'fizikəl | metə\'fɪzɪk(ə)l | ,mɛtə\'fɪzɪkl/', 'metaphysical', 3);
INSERT INTO `words` VALUES (34517, 'As the scientists conclude: \"Our results expand the known metazoan bio-sphere and demonstrate that deep ecosystems are more complex than previously accepted.', 'n&a. [动]后生动物(的)', '/,metə\'zəuən | ,metə\'zəʊən | ,mɛtə\'zoən/', 'metazoan', 3);
INSERT INTO `words` VALUES (34518, 'Astronomers track large meteors using radar.', 'n. 流星, 大气现象', '/\'mi:tiə | \'miːtɪə; -tɪɔː | \'mitɪɚ/', 'meteor', 3);
INSERT INTO `words` VALUES (34519, 'meteoric iron', 'adj. 流星的,大气的', '/,mi:ti\'ɔrik | ,miːtɪ\'ɒrɪk | ,mitɪ\'ɔrɪk/', 'meteoric', 3);
INSERT INTO `words` VALUES (34520, 'I close the meteorite room and try the door across thecorridor.', 'n. 陨石, 流星', '/\'mi:tiərait | \'miːtɪəraɪt | \'mitɪəraɪt/', 'meteorite', 3);
INSERT INTO `words` VALUES (34521, 'Were they meteoritic matter from space, reflected light from polar icebergs or a high-altitude version of lightning?', 'adj. 陨星的,陨石的', '/,mi:tiə\'ritik/', 'meteoritic', 3);
INSERT INTO `words` VALUES (34522, 'Shortly before the uninhabited space station reached orbit in .May 1973,aeroaynamic pressure ripped off a meteoroid and heat shield.', 'n. 流星体', '/\'mi:tiərɔid | \'miːtɪərɒɪd | \'mitɪər,ɔɪd/', 'meteoroid', 3);
INSERT INTO `words` VALUES (34523, '...adverse meteorological conditions.', 'adj. 气象学的； 气象的', '/ˌmiːtiərə\'lɑːdʒɪkl | ,mitɪərə\'lɑdʒɪkl/', 'meteorological', 3);
INSERT INTO `words` VALUES (34524, '\"This is probably one of the worst storms since 1990,\" a meteorologist in Seattle said.', 'n. 气象学者', '/,mi:tiə\'rɔlədʒist | ,miːtɪə\'rɒlədʒɪst | \'mitɪə\'rɑlədʒɪst/', 'meteorologist', 3);
INSERT INTO `words` VALUES (34525, 'For example geography, meteorology, physics and history.', 'n. 气象学', '/ˌmiːtiə\'rɑːlədʒi | ,mitɪə\'rɑlədʒi/', 'meteorology', 3);
INSERT INTO `words` VALUES (34526, 'The iris of the eye is photographed from up to one meter away.', 'n. 米,公尺', '/mi:tə | \'mitɚ | \'mitɚr/', 'meter', 3);
INSERT INTO `words` VALUES (34527, 'Methane is one of the principal gases contributing to the greenhouse effect.', 'n. 甲烷,沼气', '/\'mi:θein | \'miːθeɪn; \'meθeɪn | \'mɛθen/', 'methane', 3);
INSERT INTO `words` VALUES (34528, '...so-called alternative fuels such as ethanol and methanol.', 'n. 甲醇', '/\'meθənɔːl | \'mɛθənɔl/', 'methanol', 3);
INSERT INTO `words` VALUES (34529, 'traditional teaching methods', 'n. 方法， 办法， 措施； 秩序', '/\'meθəd | \'mɛθəd/', 'method', 3);
INSERT INTO `words` VALUES (34530, 'He always checked every detail in a methodical way.', 'adj. 有条理的，井然的', '/mi\'θɔdikəl, me- | mɪ\'θɒdɪk(ə)l | mə\'θɑdɪkl/', 'methodical', 3);
INSERT INTO `words` VALUES (34531, 'As I methodically explained why each clue revealed too much, my husband dutifully crossed out the words.', 'adv. 有条不紊地, 有方法地', '/mi\'θɔdikəli | məˈθɒdɪkli | məˈθɑːdɪkli/', 'methodically', 3);
INSERT INTO `words` VALUES (34532, 'However, thiomersal, the preservative in some vaccines, contains ethyl mercury not methyl mercury.', 'n. 甲基, 木精', '/\'mi:θail, \'miθil | \'miːθaɪl; \'meθ-; -θɪl | \'mɪθɪl/', 'methyl', 3);
INSERT INTO `words` VALUES (34533, 'He kept meticulous accounts.', 'adj. 一丝不苟的, 缜密的', '/mi\'tikjuləs, mə- | mə\'tɪkjələs/', 'meticulous', 3);
INSERT INTO `words` VALUES (34534, NULL, 'adv. 仔细地,谨慎地', '/me\'tikjuləsli/', 'meticulously', 3);
INSERT INTO `words` VALUES (34535, 'a metric tonne', 'adj. 米制的, 公制的', '/\'metrik | \'metrɪk | \'mɛtrɪk/', 'metric', 3);
INSERT INTO `words` VALUES (34536, 'The city has become a huge, bustling metropolis.', 'n. 首都,大城市', '/mi\'trɔpəlis, me- | mɪ\'trɒp(ə)lɪs | mə\'trɑpəlɪs/', 'metropolis', 3);
INSERT INTO `words` VALUES (34537, 'a metropolitan area of South Australia', 'adj. 大城市的，大都会的', '/,metrə\'pɔlitən | metrə\'pɒlɪt(ə)n | ,mɛtrə\'pɑlɪtən/', 'metropolitan', 3);
INSERT INTO `words` VALUES (34538, 'In fact, some even joined the Mexican force that put down his rebellion.', 'n&a. 墨西哥(的)， 墨西哥人(的)', '/\'meksikən | \'meksɪkən | \'mɛksɪkən/', 'Mexican', 3);
INSERT INTO `words` VALUES (34539, 'We want to prove that in Mexico.', 'n. 墨西哥(拉丁美洲国家)', '/\'meksikəu | \'meksɪkəʊ | \'mɛksɪko/', 'Mexico', 3);
INSERT INTO `words` VALUES (34540, 'Do you have any flights to Miami?', 'n. 迈阿密(美国佛罗里州达东南部港市)', NULL, 'Miami', 3);
INSERT INTO `words` VALUES (34541, NULL, 'adj. 毒气的, 瘴气的', '/mai\'æzmik/', 'miasmic', 3);
INSERT INTO `words` VALUES (34542, 'He quotes some students from the University of Michigan.', 'n. 密歇根州(美国州名)', '/\'miʃigən/', 'Michigan', 3);
INSERT INTO `words` VALUES (34543, '...a type of bacteria that include the microbes responsible for tuberculosis and leprosy.', 'n. 微生物, 细菌', '/\'maikrəub | \'maɪkrəʊb | \'maɪkrob/', 'microbe', 3);
INSERT INTO `words` VALUES (34544, '...the question of whether microbial life exists, or once existed, on Mars.', 'adj. 微生物的, 由细菌引起的', '/mai\'krəubiəl | maɪ\'krəʊbɪəl | maɪ\'krobɪəl/', 'microbial', 3);
INSERT INTO `words` VALUES (34545, 'I remember when Jurassic Park came out, a microbiologist friend constantly told me how outlandish it was, but within a few years, he said it was interesting how far things have come.', 'n. 微生物学家', '/,maikrəu,bai\'ɔləgist/', 'microbiologist', 3);
INSERT INTO `words` VALUES (34546, 'In each one of these places you will find a microcosm of molecules which directly impact the look, smell, touch, and sound of everything that you see.', 'n. 微观世界', '/\'maikrəukɔzəm | \'maɪkrə(ʊ)kɒz(ə)m | \'maɪkrokɑzəm/', 'microcosm', 3);
INSERT INTO `words` VALUES (34547, 'This achievement provides the microfossil materials for the study of the lower ordovician in Northern Guizhou.', 'n. 微体化石,微化石', '/,maikrəu\'fɔsəl/', 'microfossil', 3);
INSERT INTO `words` VALUES (34548, 'For example, if you say that something is \"a few microns across\", explain that a micron is one-millionth of a metre, and \"about one hundredth the width of a human hair\".', 'n. 微米,百万分之一米', '/\'maikrɔn | \'maɪkrɒn | \'maɪkrɑn/', 'micron', 3);
INSERT INTO `words` VALUES (34549, NULL, 'n&a. 密克罗尼西亚人(的)', '/,maikrəu\'ni:ziən; -ʒən/', 'micronesian', 3);
INSERT INTO `words` VALUES (34550, 'It also recommends using multiple micronutrient powders to fortify foods for children aged between 6 and 23 months.', 'n. [生]微量营养素', '/,maikrəu\'nju:triənt | maɪkrə(ʊ)\'njuːtrɪənt | ,maɪkro\'njʊtrɪənt/', 'micronutrient', 3);
INSERT INTO `words` VALUES (34551, 'This is actually just a microorganism. But it has roughly 500 genes.', 'n. 微生物', '/,maikrəu\'ɔ:ɡənizəm | maɪkrəʊ\'ɔːg(ə)nɪz(ə)m | ,maɪkro\'ɔrgən,ɪzəm/', 'microorganism', 3);
INSERT INTO `words` VALUES (34552, 'The invention of the microprocessor had made it possible for ordinary people like you and me to actually own a computer.', 'n. 微处理器', '/ˌmaɪkrou\'prousesər | ,maɪkro\'prosɛsɚ/', 'microprocessor', 3);
INSERT INTO `words` VALUES (34553, 'The slightest movement will defocus the microscope.', 'n. 显微镜', '/\'maikrəskəup | \'maɪkrəskəʊp | \'maɪkrəskop/', 'microscope', 3);
INSERT INTO `words` VALUES (34554, 'a microscopic speck of dust', 'adj. 显微镜的,极小的', '/,maikrə\'skɔpik | maɪkrə\'skɒpɪk | ,maɪkrə\'skɑpɪk/', 'microscopic', 3);
INSERT INTO `words` VALUES (34555, 'Not only might it have applications in fields such as microscopy, but it apparently also has the ability to optically store data forever.', 'n. 显微镜检查,显微镜使用', '/mai\'krɔskəpi | maɪ\'krɒskəpɪ | maɪ\'krɑskəpi/', 'microscopy', 3);
INSERT INTO `words` VALUES (34556, 'I’ll heat it up in the microwave.', 'n. 微波(波长为1毫米至30厘米的高频电磁波)', '/\'maikrəuweiv | \'maɪkrə(ʊ)weɪv | \'maɪkrə\'wev/', 'microwave', 3);
INSERT INTO `words` VALUES (34557, 'The planes collided in midair.', 'n. 半空中', '/,mid\'εə | ,mɪd\'eə | mɪd\'ɛr/', 'midair', 3);
INSERT INTO `words` VALUES (34558, NULL, 'n. 大陆中部', NULL, 'midcontinent', 3);
INSERT INTO `words` VALUES (34559, 'We stopped off in Colchester for our midday meal .', 'n. 正午', '/\'middei | mɪd\'deɪ | ,mɪd\'de/', 'midday', 3);
INSERT INTO `words` VALUES (34560, 'There are plenty of small houses for sale, and quite a lot of very large ones, but very little in the middle.', 'n. 中部,中间; adj. 中部的,中间的', '/\'mɪd(ə)l | \'mɪdl/', 'middle', 3);
INSERT INTO `words` VALUES (34561, 'He acts as a middleman for British companies seeking contracts in the Gulf.', 'n. 中间人， 调解人； 经纪人', '/\'mɪdlmæn | \'mɪdl\'mæn/', 'middleman', 3);
INSERT INTO `words` VALUES (34562, 'Fig. 5 depicts the Southern Hemisphere midlatitude 300-hPa geopotential height field.', 'n. 中间纬度', NULL, 'midlatitude', 3);
INSERT INTO `words` VALUES (34563, 'You can’t phone her now – it’s gone midnight (= after midnight ) !', 'n. 午夜', '/\'midnait | \'mɪdnaɪt/', 'midnight', 3);
INSERT INTO `words` VALUES (34564, 'In fact, he wrote his dissertation on the midocean ridge.', 'n. 海洋中央', NULL, 'midocean', 3);
INSERT INTO `words` VALUES (34565, 'We were sitting in the midst of an elegant and well-dressed audience.', 'n. 中部，中间', '/midst | mɪdst/', 'midst', 3);
INSERT INTO `words` VALUES (34566, 'midterm elections', 'adj. 中间的，期中的; n. 期中考试； 中期； 期中', '/ˌmɪd\'tɜːrm | ,mɪd\'tɝm/', 'midterm', 3);
INSERT INTO `words` VALUES (34567, 'Fresno is close to the midway point between LA and San Francisco.', 'n. 中途,半路; adj. 中途的; adv. 在中途', '/\'mid\'wei | \'mɪdweɪ; mɪd\'weɪ | \'mɪd\'we/', 'midway', 3);
INSERT INTO `words` VALUES (34568, '...farmers in the Midwest.', 'n. 中西部', '/,mid\'west/', 'midwest', 3);
INSERT INTO `words` VALUES (34569, '...the Midwestern plains.', 'adj. 美国中西部的', '/ˌmɪd\'wɛstən/', 'midwestern', 3);
INSERT INTO `words` VALUES (34570, 'the mighty Mississippi river', 'n. 有势力的人; adj. 有势力的', '/\'maiti | \'maɪtɪ | \'maɪti/', 'mighty', 3);
INSERT INTO `words` VALUES (34571, 'The government divides asylum seekers into economic migrants and genuine refugees.', 'n. 移居者, 候鸟', '/\'maiɡrənt | \'maɪgr(ə)nt | \'maɪɡrənt/', 'migrant', 3);
INSERT INTO `words` VALUES (34572, 'People migrate to cities like Jakarta in search of work.', 'v. 迁移,转移', '/mai\'ɡreit, \'maiɡ- | maɪ\'greɪt; \'maɪgreɪt | \'maɪɡret/', 'migrate', 3);
INSERT INTO `words` VALUES (34573, 'What does this migration not do?', 'n. 移居,迁移', '/mai\'ɡreiʃən | maɪ\'greɪʃ(ə)n | maɪ\'ɡreʃən/', 'migration', 3);
INSERT INTO `words` VALUES (34574, 'migratory birds', 'adj. 迁移的,流浪的', '/\'maiɡrətəri | \'maɪgrət(ə)rɪ; maɪ\'greɪt(ə)rɪ | \'maɪɡrətɔri/', 'migratory', 3);
INSERT INTO `words` VALUES (34575, 'We had an exceptionally mild winter last year.', 'adj. 温和的, 轻微的,适度的', '/maild | maɪld/', 'mild', 3);
INSERT INTO `words` VALUES (34576, '‘Of course I don’t mind,’ she answered mildly.', 'adv. 温和地, 适度地', '/\'maildli | \'maɪldlɪ | \'maɪldli/', 'mildly', 3);
INSERT INTO `words` VALUES (34577, 'It’s 40 miles from here to the Polish border.', 'n. 英里', '/mail | maɪl/', 'mile', 3);
INSERT INTO `words` VALUES (34578, 'Proust’s work reflected his own social and cultural milieu.', 'n. 周围, 环境', '/\'mi:ljə:, mi:\'ljə: | \'miːljɜː; mɪ\'ljɜː | mi\'ljɜː/', 'milieu', 3);
INSERT INTO `words` VALUES (34579, 'militant political activists', 'adj. 好战的n好斗者', '/\'militənt | \'mɪlɪt(ə)nt | \'mɪlɪtənt/', 'Militant', 3);
INSERT INTO `words` VALUES (34580, NULL, 'adv. 以武力, 以军事行动', '/\'militərili, ,mili\'tεərili/', 'militarily', 3);
INSERT INTO `words` VALUES (34581, '...aggressive militaristic governments.', 'adj. 军国主义的', '/,militə\'ristik | ,mɪlɪtə\'rɪstɪk/', 'militaristic', 3);
INSERT INTO `words` VALUES (34582, 'a military helicopter', 'adj. 军事的; n. 军队', '/\'militəri | \'mɪlɪt(ə)rɪ | \'mɪlətɛri/', 'military', 3);
INSERT INTO `words` VALUES (34583, 'a bottle of milk', 'n. 乳, 牛奶', '/milk | mɪlk/', 'milk', 3);
INSERT INTO `words` VALUES (34584, 'This is because their staple food, milkweed, is being used more and more as a garden ornament.', 'n. 乳草属植物', '/\'milkwi:d | \'mɪlkwiːd | \'mɪlk,wid/', 'milkweed', 3);
INSERT INTO `words` VALUES (34585, 'a cup of milky coffee', 'adj. 牛奶的,乳白色的', '/\'milki | \'mɪlkɪ | \'mɪlki/', 'milky', 3);
INSERT INTO `words` VALUES (34586, 'All our flours are milled using traditional methods.', 'v. 碾磨,搅拌', '/mil | mɪl/', 'mill', 3);
INSERT INTO `words` VALUES (34587, 'people who have inhabited this land for millennia', 'n. 太平盛世,一千年', '/mi\'leniəm | mɪˈlɛnɪəm | məˈlɛniəm/', 'millennium', 3);
INSERT INTO `words` VALUES (34588, 'The maize and millet were just putting forth ears.', 'n. [植]稷, 粟', '/\'milit | \'mɪlɪt/', 'millet', 3);
INSERT INTO `words` VALUES (34589, '...0.5 milligrams of mercury.', 'n. 毫克', '/\'miliɡræm | \'mɪlɪɡræm/', 'milligram', 3);
INSERT INTO `words` VALUES (34590, 'A micrometer is one thousandth of one millimeter.', 'n. 毫米', '/\'mili,mi:tə | \'mɪlɪˌmi:tə | \'mɪləˌmitə/', 'millimeter', 3);
INSERT INTO `words` VALUES (34591, 'The children learn through role-play, dance and mime.', 'n. 哑剧; v. 做哑剧表演', '/maim | maɪm/', 'mime', 3);
INSERT INTO `words` VALUES (34592, 'Both realism and naturalism are mimetic systems or practices of representation.', 'adj. 模仿的,拟态的', '/mi\'metik, mai- | mɪ\'metɪk; maɪ- | mɪ\'mɛtɪk/', 'mimetic', 3);
INSERT INTO `words` VALUES (34593, 'He could mimic all the teachers’ accents.', 'v. 模仿, 模拟', '/\'mimik | \'mɪmɪk/', 'mimic', 3);
INSERT INTO `words` VALUES (34594, 'It is impossible to understand the complex nature of the human mind .', 'n. 头脑,意见; v. 介意,注意', '/maind | maɪnd/', 'mind', 3);
INSERT INTO `words` VALUES (34595, 'Copper has been mined here since the sixteenth century.', 'n. 矿; v. 采矿', '/main | maɪn/', 'mine', 3);
INSERT INTO `words` VALUES (34596, 'Therefore, we should be more like a miner to stand in reality, excavate off wastes, and get gold mines.', 'n. 矿工', '/\'mainə | \'maɪnə | \'maɪnɚ/', 'miner', 3);
INSERT INTO `words` VALUES (34597, 'The area is very rich in minerals .', 'n. 矿物,矿石', '/\'minərəl | \'mɪn(ə)r(ə)l | \'mɪnərəl/', 'mineral', 3);
INSERT INTO `words` VALUES (34598, NULL, 'n. 矿化作用,成矿作用', '/,minərəlai\'zeiʃən, -li\'z-/', 'mineralization', 3);
INSERT INTO `words` VALUES (34599, 'Using water softeners to de-mineralize drinking water may reduce some of the potentially helpful effects.', 'v. 使矿物化,采集矿物', '/\'minərəlaiz | \'mɪn(ə)rəlaɪz | \'mɪnrəl,aɪz/', 'mineralize', 3);
INSERT INTO `words` VALUES (34600, 'Add the mint and allow the flavours to mingle.', 'v. 混合； 交往', '/\'mɪŋgl | \'mɪŋɡl/', 'mingle', 3);
INSERT INTO `words` VALUES (34601, 'miniature roses', 'adj. 小型的，微小的 n微小的模型', '/\'miniətʃə | \'mɪnɪtʃə | ˈmɪniətʃɚ; ˈmɪnɪtʃɚ/', 'miniature', 3);
INSERT INTO `words` VALUES (34602, 'The storm caused only minimal damage.', 'adj. 最小的, 最小限度的', '/\'miniməl | \'mɪnɪm(ə)l | \'mɪnɪməl/', 'minimal', 3);
INSERT INTO `words` VALUES (34603, NULL, 'n. 最低限要求者', '/\'miniməlist | \'mɪnɪm(ə)lɪst | \'mɪnɪmlɪst/', 'minimalist', 3);
INSERT INTO `words` VALUES (34604, 'Click on the top of the window to minimize it.', 'v. 将减到最少', '/\'minimaiz | ˈmɪnɪˌmaɪz | \'mɪnɪmaɪz/', 'minimize', 3);
INSERT INTO `words` VALUES (34605, 'The minimum number of students we need to run the course is fifteen.', 'adj. 最小的; n. 最小值,', '/\'miniməm | \'mɪnɪməm/', 'minimum', 3);
INSERT INTO `words` VALUES (34606, '...the Ministry of Justice.', 'n. (政府的)部门', '/\'ministri | \'mɪnɪstrɪ | \'mɪnɪstri/', 'ministry', 3);
INSERT INTO `words` VALUES (34607, 'There are 57 police officers who are still on the streets of Minneapolis tonight because this plan prevented the layoffs their department was about to make.', 'n. 明尼苏达[美国州名]', '/,mini\'æpəlis/', 'Minneapolis', 3);
INSERT INTO `words` VALUES (34608, 'This is a picture of a weasel I found in Northern Minnesota.', 'n. 明尼苏达州(美国州名)', '/,mini\'səutə/', 'Minnesota', 3);
INSERT INTO `words` VALUES (34609, 'We have made some minor changes to the program.', 'adj. 较小的,次要的', '/\'mainə | \'maɪnə | \'maɪnɚ/', 'minor', 3);
INSERT INTO `words` VALUES (34610, 'Gaelic is still spoken in Ireland by a tiny minority.', 'n. 少数, 少数民族', '/mai\'nɔrəti, mi- | maɪ\'nɒrɪtɪ; mɪ- | maɪ\'nɔrəti/', 'minority', 3);
INSERT INTO `words` VALUES (34611, 'Alfred the Great acted his own spy, visiting Danish camps disguised as a minstrel.', 'n. 吟游诗人(或歌手)', '/\'minstrəl | \'mɪnstr(ə)l | \'mɪnstrəl/', 'minstrel', 3);
INSERT INTO `words` VALUES (34612, 'new potatoes sprinkled with chopped mint', 'n. 薄荷', '/mɪnt/', 'mint', 3);
INSERT INTO `words` VALUES (34613, '‘Any minus points ?’ ‘Well, the engine is rather noisy.’', 'adj. 减的，负的; prep. 减; n. 负数；减号；不足', '/\'maɪnəs/', 'minus', 3);
INSERT INTO `words` VALUES (34614, NULL, 'n&a. 草写小字(的)', '/\'minəskju:l, mi\'nʌs- | \'mɪnəskjuːl | \'mɪnəskjul/', 'minuscule', 3);
INSERT INTO `words` VALUES (34615, 'It takes me ten minutes to walk to work.', 'n. 分钟,片刻', '/\'mɪnɪt/', 'minute', 3);
INSERT INTO `words` VALUES (34616, 'Even the levels of carbon dioxide can be minutely altered.', 'adj. 每分钟的,持续的', '/\'minitli | maɪ\'njuːtlɪ | maɪ\'njutlɪ/', 'minutely', 3);
INSERT INTO `words` VALUES (34617, NULL, 'adj. 中新世的, 中新统的', '/\'maiəusi:n/', 'miocene', 3);
INSERT INTO `words` VALUES (34618, 'It’s a miracle you weren’t killed!', 'n. 奇迹, 奇事', '/\'mirəkl | \'mɪrək(ə)l | \'mɪrəkl/', 'miracle', 3);
INSERT INTO `words` VALUES (34619, 'She made a miraculous recovery from her injuries.', 'adj. 奇迹的,不可思议的', '/mi\'rækjuləs | mɪ\'rækjʊləs | mɪ\'rækjələs/', 'miraculous', 3);
INSERT INTO `words` VALUES (34620, 'Perhaps we are just chasing a mirage.', 'n. 海市蜃楼,幻想', '/\'mirɑ:ʒ, mi\'rɑ:ʒ | \'mɪrɑːʒ; mɪ\'rɑːʒ | mə\'rɑʒ/', 'mirage', 3);
INSERT INTO `words` VALUES (34621, 'He spends hours in front of the mirror !', 'n. 镜子; v. 反映,映出', '/\'mirə | \'mɪrə | \'mɪrɚ/', 'mirror', 3);
INSERT INTO `words` VALUES (34622, 'Their sons are noisy and mischievous.', 'adj. 恶作剧的， 顽皮的， 淘气的； 恶意的', '/\'mɪstʃɪvəs/', 'mischievous', 3);
INSERT INTO `words` VALUES (34623, 'It is a misconception that Peggy was fabulously wealthy.', 'n. 误解', '/,miskən\'sepʃən | mɪskən\'sepʃ(ə)n | \'mɪskən\'sɛpʃən/', 'misconception', 3);
INSERT INTO `words` VALUES (34624, '...the alleged financial misdeeds of his government.', 'n. 罪行, 犯罪', '/,mis\'di:d, \'mis- | mɪs\'diːd | ,mɪs\'did/', 'misdeed', 3);
INSERT INTO `words` VALUES (34625, 'I’ve been so miserable since Pat left me.', 'adj. 痛苦的； 可怜的； 令人不快的', '/\'mɪzrəbl/', 'miserable', 3);
INSERT INTO `words` VALUES (34626, 'What we are witnessing here is human misery on a vast scale.', 'n. 痛苦, 苦恼', '/\'mizəri | \'mɪz(ə)rɪ | \'mɪzəri/', 'misery', 3);
INSERT INTO `words` VALUES (34627, 'It seems the banks always profit from farmers’ misfortunes.', 'n. 不幸, 灾祸', '/mis\'fɔ:tʃən | mɪs\'fɔːtʃuːn; -tʃ(ə)n | \'mɪs\'fɔrtʃən/', 'misfortune', 3);
INSERT INTO `words` VALUES (34628, 'Some parts of the report could be misinterpreted.', 'v. 曲解', '/,misin\'tə:prit | mɪsɪn\'tɜːprɪt | \'mɪsɪn\'tɝprɪt/', 'misinterpret', 3);
INSERT INTO `words` VALUES (34629, NULL, 'v. 误解', NULL, 'misinterprete', 3);
INSERT INTO `words` VALUES (34630, 'Don’t be misled by appearances, he’s a good worker.', 'v. 误导', '/,mis\'li:d | mɪs\'liːd | \'mɪs\'lid/', 'mislead', 3);
INSERT INTO `words` VALUES (34631, 'The nation’s finances had been badly mismanaged.', 'vt. 对…管理不当， 处理不当', '/ˌmɪs\'mænɪdʒ | \'mɪs\'mænɪdʒ/', 'mismanage', 3);
INSERT INTO `words` VALUES (34632, 'There is a mismatch between the skills offered by people and the skills needed by industry.', 'n&v. 配错, 不相匹配', '/,mis\'mætʃ | \'mɪsmætʃ/', 'mismatch', 3);
INSERT INTO `words` VALUES (34633, 'I don\'t want to miss seeing that film on television tonight.', 'n. 过错; v. 错过,遗漏', '/mɪs/', 'miss', 3);
INSERT INTO `words` VALUES (34634, 'a nuclear missile', 'n. 发射物； 导弹， 飞弹', '/\'mɪsl/', 'missile', 3);
INSERT INTO `words` VALUES (34635, 'He was sent on over 200 missions before being killed in action.', 'n. 使命,任务', '/\'miʃən | \'mɪʃ(ə)n | \'mɪʃən/', 'mission', 3);
INSERT INTO `words` VALUES (34636, 'My mother would still like me to be a missionary in Africa.', 'n&a. 传教士(的) ,传教的,', '/\'miʃənəri | \'mɪʃ(ə)n(ə)rɪ | \'mɪʃənɛri/', 'missionary', 3);
INSERT INTO `words` VALUES (34637, 'That means the Arctic has lost an area greater than all the U.S. states east of the Mississippi.', 'n. 密西西比河,密西西比州(美国州名)', '/ˌmisiˈsipi/', 'Mississippi', 3);
INSERT INTO `words` VALUES (34638, 'Cahokia was one of the great centers of Mississippian culture and its largest settlement of Missippian.', 'adj. 密西西比河的 n密西西比州人', '/,misi\'sipiən | ,mɪsə\'sɪpɪən/', 'Mississippian', 3);
INSERT INTO `words` VALUES (34639, 'We live in Missouri.', 'n. 密苏里州(美国州名)', '/mi\'zuəri | mɪ\'zʊri/', 'Missouri', 3);
INSERT INTO `words` VALUES (34640, 'We could just see the outline of the house through the mist.', 'n. 薄雾', '/mist | mɪst/', 'mist', 3);
INSERT INTO `words` VALUES (34641, 'The most common mistake is to plant them too deep.', 'n. 错误; v. 弄错,误解', '/mi\'steik | mɪ\'steɪk | mɪ\'stek/', 'mistake', 3);
INSERT INTO `words` VALUES (34642, 'As a very small child she had learned to mistrust adults.', 'n&v. 不信任, 猜疑', '/,mis\'trʌst | mɪs\'trʌst | ,mɪs\'trʌst/', 'mistrust', 3);
INSERT INTO `words` VALUES (34643, 'a cold, misty morning', 'adj. 有薄雾的', '/\'misti | \'mɪstɪ | \'mɪsti/', 'misty', 3);
INSERT INTO `words` VALUES (34644, 'Rachel, you must have misunderstood her! Ellie would never say something like that.', 'v. 误解, 误会', '/,misʌndə\'stænd | ,mɪsʌndə\'stænd | ,mɪsʌndɚ\'stænd/', 'misunderstand', 3);
INSERT INTO `words` VALUES (34645, 'There must have been some misunderstanding. I didn’t order all these books.', 'n. 误会, 误解', '/,misʌndə\'stændiŋ | ,mɪsʌndə\'stændɪŋ | ,mɪsʌndɚ\'stændɪŋ/', 'misunderstanding', 3);
INSERT INTO `words` VALUES (34646, 'Poor mite! You must be starving!', 'n. 微小的东西,', '/mait | maɪt/', 'mite', 3);
INSERT INTO `words` VALUES (34647, 'Measures need to be taken to mitigate the environmental effects of burning more coal.', 'v. 减轻,缓和', '/\'mitiɡeit | \'mɪtɪgeɪt | \'mɪtɪɡet/', 'mitigate', 3);
INSERT INTO `words` VALUES (34648, 'Oil and water don’t mix.', 'v. 使混和,混淆', '/miks | mɪks/', 'mix', 3);
INSERT INTO `words` VALUES (34649, 'Pour the mixture into four small dishes.', 'n. 混合(物)', '/\'mikstʃə | \'mɪkstʃə | \'mɪkstʃɚ/', 'mixture', 3);
INSERT INTO `words` VALUES (34650, 'Certainly no one in the media would deny the attraction of living behind a deep moat, even if it is filled with sharks.', 'n. 护城河, 城壕', '/məut | məʊt | mot/', 'moat', 3);
INSERT INTO `words` VALUES (34651, 'They were immediately surrounded by the mob.', 'n. 暴民 vt成群围住,聚众袭击', '/mɔb | mɒb | mɑb/', 'mob', 3);
INSERT INTO `words` VALUES (34652, 'mobile air-conditioners', 'adj. 可移动的, 易变的', '/ˈməʊbaɪl | ˈmobəl; ˈmoˌbaɪl; ˈmoˌbil/', 'mobile', 3);
INSERT INTO `words` VALUES (34653, 'It improves the strength and mobility of joints.', 'n. 活动性, 灵活性', '/məu\'biləti | məʊ\'bɪlətɪ | mo\'bɪləti/', 'mobility', 3);
INSERT INTO `words` VALUES (34654, 'an attempt to mobilize popular opinion', 'v. 动员', '/\'məubilaiz | \'məʊbəlaɪz | \'mobəlaɪz/', 'mobilize', 3);
INSERT INTO `words` VALUES (34655, 'The soft shoe was made of wraparound leather, similar to a moccasin.', 'n. 鹿皮鞋, 软拖鞋', '/\'mɔkəsin | \'mɒkəsɪn | \'mɑkəsn/', 'moccasin', 3);
INSERT INTO `words` VALUES (34656, 'Opposition MPs mocked the government’s decision.', 'v. 嘲笑，嘲弄；模仿；蔑视，; n. 模拟考试', '/mɑːk | mɑk/', 'mock', 3);
INSERT INTO `words` VALUES (34657, 'The designers, unlike wizards, are non-modal and hence allow you the flexibility to simultaneously work on designing different database objects.', 'adj. 模态的, 形态上的', '/\'məudəl | \'məʊd(ə)l | \'modl/', 'modal', 3);
INSERT INTO `words` VALUES (34658, 'Set the monitor to 256 colour mode.', 'n. 方式,模式', '/məud | məʊd | mod/', 'mode', 3);
INSERT INTO `words` VALUES (34659, 'a working model (= one with parts which move ) of a steam engine', 'n. 模型; v. 模仿,展示', '/\'mɔdəl | \'mɒdl | \'mɑdl/', 'model', 3);
INSERT INTO `words` VALUES (34660, NULL, 'n. 立体感； 建模， 造型', '/\'mɑːdlɪŋ | \'mɑdlɪŋ/', 'modeling', 3);
INSERT INTO `words` VALUES (34661, 'He sent his work to his publishers by modem.', 'n. [计]调制解调器', '/\'məudem | \'məʊdem | \'mo\'dɛm/', 'modem', 3);
INSERT INTO `words` VALUES (34662, 'Even moderate amounts of alcohol can be dangerous.', 'adj. 中等的, 适度的', '/\'mɔdərət, \'mɔdəreit | \'mɒd(ə)rət | ˈmɑdərɪt; (for v.,) ˈmɑdərˌeɪt/', 'moderate', 3);
INSERT INTO `words` VALUES (34663, 'He drinks moderately.', 'adv. 适度地', '/\'mɔdərətli | \'mɒd(ə)rətlɪ | \'mɑdərətli/', 'moderately', 3);
INSERT INTO `words` VALUES (34664, 'There was a return to ornamentation—and there was a frivolity—something over and above the brutal structural form of the old modernist designs.', 'n. 现代主义者, 现代人', '/\'mɔdənist | \'mɑdɚnɪst/', 'modernist', 3);
INSERT INTO `words` VALUES (34665, 'a modernistic office building', 'adj. 现代的, 现代主义的', '/,mɔdə\'nistik | ,mɒdə\'nɪstɪk | ,mɑdɚ\'nɪstɪk/', 'modernistic', 3);
INSERT INTO `words` VALUES (34666, 'a conflict between tradition and modernity', 'n. 现代性', '/mə\'dɜːrnəti | mə\'dɝnəti/', 'modernity', 3);
INSERT INTO `words` VALUES (34667, 'For these reasons, the bank chose it as their development tool for their modernization project.', 'n. 现代化', '/,mɔdənai\'zeiʃən, -ni\'z- | ,mɒdənaɪ\'zeɪʃən | ,mɑdɚnə\'zeʃən/', 'modernization', 3);
INSERT INTO `words` VALUES (34668, 'They need more funds to modernize the country’s telephone system.', 'v. 使现代化', '/\'mɔdənaiz | ˈmɒdənaɪz | mɑdɚnˌaɪz/', 'modernize', 3);
INSERT INTO `words` VALUES (34669, 'You’re too modest! You’ve been a huge help to us.', 'adj. 谦虚的, 适度的', '/\'mɔdist | \'mɒdɪst | \'mɑdɪst/', 'modest', 3);
INSERT INTO `words` VALUES (34670, '‘And I think you’ve got to have an awful lot of talent to then go and do what the Beatles did – he says modestly.', 'adv. 谨慎地, 适当地', '/英[ˈmɒdɪst] 美[ˈmɑːdɪst] | ˈmɒdɪstlɪ | mɑdɪstlɪ/', 'modestly', 3);
INSERT INTO `words` VALUES (34671, 'a modicum of common sense', 'n. 少量, 一点点', '/\'mɔdikəm | \'mɒdɪkəm | \'mɑdɪkəm/', 'modicum', 3);
INSERT INTO `words` VALUES (34672, 'They have used the same process for almost 50 years with only minor modifications .', 'n. 更改, 修改', '/,mɔdifi\'keiʃən | ,mɒdɪfɪ\'keɪʃ(ə)n | ,mɑdɪfɪ\'keʃən/', 'modification', 3);
INSERT INTO `words` VALUES (34673, 'The feedback will be used to modify the course for next year.', 'v. 更改,修改', '/\'mɔdifai | \'mɒdɪfaɪ | \'mɑdɪfaɪ/', 'modify', 3);
INSERT INTO `words` VALUES (34674, 'He carefully modulated his voice.', 'v. 调整, 调节, (信号)调制', '/\'mɔdjuleit, -dʒu- | \'mɒdjʊleɪt | \'mɑdʒəlet/', 'modulate', 3);
INSERT INTO `words` VALUES (34675, 'Yawning seems to be involved in the modulation of arousal process across the whole life span.', 'n. 调制', '/,mɔdju\'leiʃən, -dʒu- | ,mɒdjʊ\'leɪʃən | ,mɑdʒu\'leʃən/', 'modulation', 3);
INSERT INTO `words` VALUES (34676, 'Switch from one module to another.', 'n. 模数, 模块', '/\'mɔdju:l, -dʒu:l | \'mɒdjuːl | \'mɑdʒul/', 'module', 3);
INSERT INTO `words` VALUES (34677, 'The problem is, I do not have any technique, process, or modus operandi.', 'n. 方法, 形式', '/\'məudus/', 'modus', 3);
INSERT INTO `words` VALUES (34678, 'Make sure the soil is moist before planting the seeds.', 'adj. 潮湿的，湿润的', '/mɔist | mɒɪst | mɔɪst/', 'moist', 3);
INSERT INTO `words` VALUES (34679, 'Moisten the clay if it seems too dry.', 'v. 弄湿 vi变潮湿', '/\'mɔisən | \'mɒɪs(ə)n | \'mɔɪsn/', 'moisten', 3);
INSERT INTO `words` VALUES (34680, 'Plants use their roots to absorb moisture from the soil.', 'n. 潮湿,湿气', '/\'mɔistʃə | \'mɒɪstʃə | \'mɔɪstʃɚ/', 'moisture', 3);
INSERT INTO `words` VALUES (34681, 'A better natural substitute would be Manuka honey or molasses but only in very small amounts.', 'n. <美>糖蜜', '/mə\'læsiz | mə\'læsɪz/', 'molasses', 3);
INSERT INTO `words` VALUES (34682, 'Because of its flexibility, we can mold software into any form to do almost anything.', 'n. 模子vt浇铸, 塑造', '/məuld | məʊld | mold/', 'mold', 3);
INSERT INTO `words` VALUES (34683, '...the molecular structure of fuel.', 'adj. 分子的', '/məu\'lekjulə | mə\'lekjʊlə | mə\'lɛkjəlɚ/', 'molecular', 3);
INSERT INTO `words` VALUES (34684, 'The molecules of oxygen gas contain just two atoms.', 'n. 分子', '/\'mɔlikjul | \'mɒlɪkjuːl | \'mɑlɪkjul/', 'molecule', 3);
INSERT INTO `words` VALUES (34685, 'Atype of mollusk, the lined chiton has colorful lines on its valves andwhite or yellow spots or bands on its girdle.', 'n. [动]软体动物', '/\'mɔləsk | \'mɒləsk/', 'mollusk', 3);
INSERT INTO `words` VALUES (34686, 'Like other penguins, it undergoes an annual molt, replacing all its feathers in a few weeks.', 'vi&n. 脱毛,换毛', '/məult | məʊlt | molt/', 'molt', 3);
INSERT INTO `words` VALUES (34687, 'molten iron', 'adj. 熔化的， 熔融的', '/\'moultən | \'moltən/', 'molten', 3);
INSERT INTO `words` VALUES (34688, 'He was here a moment ago .', 'n. 片刻，瞬间', '/\'məʊm(ə)nt | \'momənt/', 'moment', 3);
INSERT INTO `words` VALUES (34689, 'She was momentarily lost for words.', 'adv. 暂时地, 立刻地', '/\'məuməntərəli | \'məʊm(ə)nt(ə)rɪlɪ; ,məʊm(ə)n\'terɪlɪ | ,momən\'tɛrəli/', 'momentarily', 3);
INSERT INTO `words` VALUES (34690, 'There was a momentary pause.', 'adj. 片刻的， 瞬间的， 暂时的', '/\'moumənteri | \'moməntɛri/', 'momentary', 3);
INSERT INTO `words` VALUES (34691, 'a momentous decision', 'adj. 重要的, 重大的', '/məu\'mentəs | mə(ʊ)\'mentəs | mo\'mɛntəs/', 'momentous', 3);
INSERT INTO `words` VALUES (34692, 'incentives to maintain the momentum of European integration', 'n. 动力, 势头', '/məu\'mentəm | mə\'mentəm | mo\'mɛntəm/', 'momentum', 3);
INSERT INTO `words` VALUES (34693, 'The monarch was ousted by a military coup.', 'n. 君主', '/\'mɔnək, -ɑ:k | \'mɒnək | \'mɑnɚk/', 'monarch', 3);
INSERT INTO `words` VALUES (34694, 'the abolition of the monarchy', 'n. 君主政体, 君主国', '/\'mɔnəki | \'mɒnəkɪ | \'mɑnɚki/', 'monarchy', 3);
INSERT INTO `words` VALUES (34695, 'They found an icon in the monastery.', 'n. 男修道院， 寺院', '/\'mɑːnəsteri | \'mɑnəstɛri/', 'monastery', 3);
INSERT INTO `words` VALUES (34696, 'the government’s tight monetary policy', 'adj. 货币的, 金融的', '/\'mʌnitəri | \'mʌnɪt(ə)rɪ | \'mʌnɪtɛri/', 'monetary', 3);
INSERT INTO `words` VALUES (34697, 'Don’t spend all your money on the first day of your holiday!', 'n. 钱,货币', '/\'mʌni | \'mʌnɪ/', 'money', 3);
INSERT INTO `words` VALUES (34698, 'Mongolia really is the land of opportunity.', 'n. 蒙古', '/mɔŋ\'ɡəuliə; \'mɔn-/', 'Mongolia', 3);
INSERT INTO `words` VALUES (34699, 'Patients who are given the new drug will be asked to monitor their progress.', 'v. 监听(视；测) n检测器', '/\'mɒnɪtə | \'mɔnɪtɚ/', 'monitor', 3);
INSERT INTO `words` VALUES (34700, 'The monkey is beating up and down.', 'n. 猴子', '/\'mʌŋki | \'mʌŋkɪ/', 'monkey', 3);
INSERT INTO `words` VALUES (34701, 'However, if you want to wear a print, choose a print that\'s low in contrast and monochromatic in color.', 'adj. 单色的', '/,mɔnəukrəu\'mætik | mɒnə(ʊ)krə\'mætɪk | ,mɑnəkrə\'mætɪk/', 'monochromatic', 3);
INSERT INTO `words` VALUES (34702, NULL, 'n. 单色 单色的', '/\'mɔnəkrəum | \'mɒnəkrəʊm; mɒnə(ʊ)\'krəʊm | \'mɑnəkrom/', 'monochrome', 3);
INSERT INTO `words` VALUES (34703, 'So birds are monogamous but they cheat as well, within limits.', 'n. 一夫一妻的, 单配的', '/mɔ\'nɔɡəməs, mə- | mɒ\'nɒɡəməs | mə\'nɑɡəməs/', 'monogamous', 3);
INSERT INTO `words` VALUES (34704, 'People still opt for monogamy and marriage.', 'n. 一夫一妻制', '/mə\'nɑːgəmi | mə\'nɑɡəmi/', 'monogamy', 3);
INSERT INTO `words` VALUES (34705, NULL, 'n. 独异点', '/\'mɔnɔid/', 'monoid', 3);
INSERT INTO `words` VALUES (34706, 'This monolithic environment for an application eliminated any concern about which clock to use -- because there was only one clock.', 'n. 单片电路, 单块集成电路', '/,mɔnəu\'liθik | mɒnə\'lɪθɪk | ,mɑnə\'lɪθɪk/', 'monolithic', 3);
INSERT INTO `words` VALUES (34707, 'The company has monopolized the soft drinks market.', 'v. 独占, 垄断', '/mə\'nɔpəlaiz | mə\'nɑpə\'laɪz/', 'monopolize', 3);
INSERT INTO `words` VALUES (34708, 'a monopoly in copper trading', 'n. 垄断(者)', '/mə\'nɔpəli | mə\'nɒp(ə)lɪ | mə\'nɑpəli/', 'monopoly', 3);
INSERT INTO `words` VALUES (34709, 'a monotonous diet', 'adj. 单调的,无抑扬顿挫的', '/mə\'nɔtənəs | mə\'nɒt(ə)nəs | mə\'nɑtənəs/', 'monotonous', 3);
INSERT INTO `words` VALUES (34710, 'A night on the town may help to break the monotony of the week.', 'n. 单调， 千篇一律', '/mə\'nɑːtəni | mə\'nɑtəni/', 'monotony', 3);
INSERT INTO `words` VALUES (34711, 'Then, if the mix of waste is correct, the carbon and oxygen atoms involved recombine to form carbon monoxide and the hydrogen atoms link up into diatomic hydrogen molecules.', 'n. 一氧化物', '/mɔ\'nɔksaid, mə- | mə\'nɒksaɪd/', 'monoxide', 3);
INSERT INTO `words` VALUES (34712, 'Monroe followed Madison as president.', 'n. 门罗(m)', '/mən\'rəu/', 'Monroe', 3);
INSERT INTO `words` VALUES (34713, 'the remains of a prehistoric monster', 'n. 怪物', '/\'mɔnstə | \'mɒnstə | \'mɑnstɚ/', 'monster', 3);
INSERT INTO `words` VALUES (34714, 'I hope I’ll have finished the work by the end of the month .', 'n. 月', '/mʌnθ/', 'month', 3);
INSERT INTO `words` VALUES (34715, 'He erected a monument on the spot where his daughter was killed.', 'n. 纪念碑', '/\'mɔnjumənt | \'mɒnjʊm(ə)nt | \'mɑnjumənt/', 'monument', 3);
INSERT INTO `words` VALUES (34716, 'a monumental arch', 'adj. 纪念碑的,不朽的', '/,mɔnju\'mentəl | mɒnjʊ\'ment(ə)l | ,mɑnju\'mɛntl/', 'monumental', 3);
INSERT INTO `words` VALUES (34717, 'You’re in a good mood this morning!', 'n. 心情, 情绪', '/mu:d | muːd | mud/', 'mood', 3);
INSERT INTO `words` VALUES (34718, 'Keith had seemed moody all morning.', 'adj. 易怒的, 情绪化的', '/\'mu:di | \'muːdɪ | \'mudi/', 'moody', 3);
INSERT INTO `words` VALUES (34719, 'the craters on the surface of the moon', 'n. 月球,月亮', '/mu:n | muːn | mun/', 'moon', 3);
INSERT INTO `words` VALUES (34720, 'Two or three fishing boats were moored alongside the pier.', 'v. 停泊， 系泊; n. 沼泽；旷野，荒野', '/mur/', 'moor', 3);
INSERT INTO `words` VALUES (34721, 'So did we encounter our bear, or a moose?', 'n. [动] 驼鹿', '/muːs | mus/', 'moose', 3);
INSERT INTO `words` VALUES (34722, 'The ground is covered with moraine.', 'n. 冰碛', '/mɔ\'rein, mə- | mə\'reɪn | mə\'ren/', 'moraine', 3);
INSERT INTO `words` VALUES (34723, 'It is easy to have an opinion on a moral issue like the death penalty for murder.', 'adj. 道德(上)的,精神的', '/\'mɔrəl, \'mɔ:- | \'mɒr(ə)l | \'mɔrəl/', 'moral', 3);
INSERT INTO `words` VALUES (34724, 'A win is always good for morale.', 'n. 士气, 民心', '/mɔ\'rɑ:l, -\'ræl | mə\'rɑːl | mə\'ræl/', 'morale', 3);
INSERT INTO `words` VALUES (34725, 'His moralism is all-encompassing and as passionate as can be. He plans to replace state welfare provision with faith-based charitable organisations that would impose Christian family values.', 'n. 道德主义, 说教', '/\'mɔrəlizəm | \'mɒr(ə)lɪz(ə)m/', 'moralism', 3);
INSERT INTO `words` VALUES (34726, 'It’s difficult to talk to teenagers about drugs without sounding too moralistic.', 'adj. 狭隘道德观的, 说教的', '/,mɔrə\'listik, ,mɔ:- | mɒrə\'lɪstɪk | ,mɔrə\'lɪstɪk/', 'moralistic', 3);
INSERT INTO `words` VALUES (34727, '...standards of morality and justice in society.', 'n. 道德,品行', '/mə\'ræləti, mɔ:- | məˈræləti/', 'morality', 3);
INSERT INTO `words` VALUES (34728, 'politicians moralizing about people’s sexual behaviour', 'v. 教化 ,说教', '/\'mɔrəlaiz, \'mɔ:- | \'mɒr(ə)laɪz | \'mɔrəlaɪz/', 'moralize', 3);
INSERT INTO `words` VALUES (34729, 'What you did wasn’t illegal, but it was morally wrong .', 'adv. 道德上', '/\'mɔrəli, \'mɔ:- | \'mɒrəlɪ | \'mɔrəli/', 'morally', 3);
INSERT INTO `words` VALUES (34730, 'The rent is reasonable and, moreover, the location is perfect.', 'adv. 此外,而且', '/mɔ:\'rəuvə | mɔːr\'əʊvə | mɔr\'ovɚ/', 'moreover', 3);
INSERT INTO `words` VALUES (34731, 'Police came and took her gently aside and told her they would try to find the name of the morgue.', 'n. 停尸房， 太平间', '/mɔːrg | mɔrɡ/', 'morgue', 3);
INSERT INTO `words` VALUES (34732, NULL, 'n. 摩门教徒, 一夫多妻主义者', '/\'mɔ:mən/', 'mormon', 3);
INSERT INTO `words` VALUES (34733, 'I hated those cold winter mornings.', 'n. 早晨, 上午', '/\'mɔ:niŋ | \'mɔːnɪŋ | \'mɔrnɪŋ/', 'morning', 3);
INSERT INTO `words` VALUES (34734, 'Many scientists agree that the domestic dog displays more morphological variation than any other known species, thanks to selective breeding by humans.', 'adj. 形态学的', '/,mɔ:fə\'lɔdʒikəl | ,mɔːfə\'lɒdʒɪkəl | ,mɔrfə\'lɑdʒəkəl/', 'morphological', 3);
INSERT INTO `words` VALUES (34735, 'Morpheme is the basic unit in the study of morphology.', 'n. [生物]形态学, [语法]词法', '/mɔ:\'fɔlədʒi | mɔː\'fɒlədʒɪ | mɔr\'fɑlədʒi/', 'morphology', 3);
INSERT INTO `words` VALUES (34736, NULL, 'n. 莫理斯舞(英国传统民间舞蹈)', '/\'mɔris | \'mɒrɪs | \'mɔrɪs/', 'morris', 3);
INSERT INTO `words` VALUES (34737, 'Her father’s death reminded her that she was mortal.', 'n. 凡人,人类; adj. 必死的,致命的', '/\'mɔ:təl | \'mɔːt(ə)l | \'mɔrtl/', 'mortal', 3);
INSERT INTO `words` VALUES (34738, 'Mortality from heart disease varies widely across the world.', 'n. 死亡率', '/mɔːr\'tæləti | mɔr\'tæləti/', 'mortality', 3);
INSERT INTO `words` VALUES (34739, 'A cameraman was killed when his vehicle came under mortar fire .', 'n. 灰泥,迫击炮 vt用灰泥结合', '/\'mɔːtə | \'mɔrtɚ/', 'mortar', 3);
INSERT INTO `words` VALUES (34740, 'Your building society or bank will help arrange a mortgage.', 'n. 抵押贷款，按揭；抵押证书; vt. 用…作抵押', '/\'mɔːrgɪdʒ | \'mɔrɡɪdʒ/', 'mortgage', 3);
INSERT INTO `words` VALUES (34741, 'Jane mortified her family by leaving her husband.', 'vt. 使蒙受屈辱， 使难堪', '/\'mɔːrtɪfaɪ | \'mɔrtɪfaɪ/', 'mortify', 3);
INSERT INTO `words` VALUES (34742, 'And there are any metallic connectives on this bed, joggle is between bed leg and bedplate, craftsman certains ably good mortise, this bed combination is together.', 'n. 榫眼 v用榫接合', '/\'mɔ:tis | \'mɔːtɪs | \'mɔrtɪs/', 'mortise', 3);
INSERT INTO `words` VALUES (34743, 'rooms decorated with wall paintings and mosaics', 'n. 镶嵌细工，马赛克', '/məu\'zeiik | mə(ʊ)\'zeɪɪk | mo\'zeɪk/', 'mosaic', 3);
INSERT INTO `words` VALUES (34744, 'The male mosquito never stings.', 'n. 蚊子', '/mə\'ski:təu | mɒ\'skiːtəʊ | məˈskiːtoʊ/', 'mosquito', 3);
INSERT INTO `words` VALUES (34745, '...ground covered over with moss.', 'n. 苔, 藓', '/mɔs | mɒs/', 'moss', 3);
