INSERT INTO `words` VALUES (34747, 'What do a hummingbird, a moth, and a maple tree have in common?', 'n. 蛾, 蛀虫', '/mɔθ, mɔ:θ | mɒθ | mɔθ/', 'moth', 3);
INSERT INTO `words` VALUES (34748, 'His mother and father are both doctors.', 'n. 母亲', '/\'mʌðə | \'mʌðɚ/', 'mother', 3);
INSERT INTO `words` VALUES (34749, 'The theme of creation is a recurrent motif in Celtic mythology.', 'n. 主题,主旨', '/məu\'ti:f, mɔ- | məʊ\'tiːf | mo\'tif/', 'motif', 3);
INSERT INTO `words` VALUES (34750, 'Newton’s first law of motion', 'n. 运动,动作', '/\'məʊʃ(ə)n | \'moʃən/', 'motion', 3);
INSERT INTO `words` VALUES (34751, 'Graham remained motionless.', 'adj. 不动的, 静止的', '/\'məuʃənlis | \'məʊʃnləs | \'moʃnləs/', 'motionless', 3);
INSERT INTO `words` VALUES (34752, 'A good teacher has to be able to motivate her students.', 'v. 激发', '/\'məutiveit | \'məʊtɪveɪt | \'motə\'vet/', 'motivate', 3);
INSERT INTO `words` VALUES (34753, 'Jack is an intelligent pupil, but he lacks motivation.', 'n. 动机', '/,məuti\'veiʃən | məʊtɪ\'veɪʃ(ə)n | ,motə\'veʃən/', 'motivation', 3);
