INSERT INTO `words` VALUES (34755, 'an electric motor', 'n. 发动机', '/\'məutə | \'məʊtə | \'motɚ/', 'motor', 3);
INSERT INTO `words` VALUES (34756, 'You\'d better encash your motorcycle at once.', 'n. 摩托车, 机车', '/\'məutə,saikl | \'məʊtəsaɪk(ə)l | \'motɚ\'saɪkl/', 'motorcycle', 3);
INSERT INTO `words` VALUES (34757, NULL, 'v. 使有斑点 n杂色, 斑点', '/\'mɔtl | \'mɒt(ə)l | \'mɑtl/', 'mottle', 3);
INSERT INTO `words` VALUES (34758, 'His red, mottled face showed the effect of too much whisky.', 'adj. 有杂色的， 斑驳的', '/\'mɑːtld | \'mɑtld/', 'mottled', 3);
INSERT INTO `words` VALUES (34759, '‘Be prepared’ is the motto of the Boy Scouts.', 'n. 座右铭； 箴言， 格言', '/\'mɑːtou | \'mɑto/', 'motto', 3);
INSERT INTO `words` VALUES (34760, 'mouldy cheese', 'adj. 发霉的, 腐朽的, 旧式的', '/\'məuldi | \'moldi/', 'mouldy', 3);
INSERT INTO `words` VALUES (34761, 'an ancient burial mound', 'n. 土墩，沙土堆', '/maund | maʊnd/', 'mound', 3);
INSERT INTO `words` VALUES (34762, 'Larry was mounting the stairs up into the attic.', 'v. 登上 n山,峰', '/maʊnt/', 'mount', 3);
INSERT INTO `words` VALUES (34763, 'the mountainous coast of Wales', 'adj. 多山的, 巨大的', '/\'mauntinəs | \'maʊntɪnəs | \'maʊntənəs/', 'mountainous', 3);
INSERT INTO `words` VALUES (34764, 'Great rocks rolled down the mountainside.', 'n. 山腹, 山腰', '/\'mauntinsaid | \'maʊntɪnsaɪd | \'maʊntənsaɪd/', 'mountainside', 3);
INSERT INTO `words` VALUES (34765, 'The cat laid a dead mouse at my feet.', 'n. 鼠', '/maus, mauz | maʊs/', 'mouse', 3);
INSERT INTO `words` VALUES (34766, 'He lifted his glass to his mouth.', 'n. 口,嘴', '/mauθ | maʊθ/', 'mouth', 3);
INSERT INTO `words` VALUES (34767, 'a teddy bear with movable arms and legs', 'adj. 活动的，变动的', '/\'mu:vəbl | \'muːvəb(ə)l | \'mʊvəbl/', 'movable', 3);
INSERT INTO `words` VALUES (34768, 'It was like one of those old John Wayne movies.', 'n. 电影', '/\'mu:vi | \'muːvɪ | \'muvi/', 'movie', 3);
INSERT INTO `words` VALUES (34769, 'It’s time to mow the lawn again.', 'v. 割(草)', '/mau | məʊ | mo/', 'mow', 3);
INSERT INTO `words` VALUES (34770, 'By the end of the game, all the kids were covered in mud.', 'n. 泥,泥浆', '/mʌd/', 'mud', 3);
INSERT INTO `words` VALUES (34771, 'Take your boots off outside if they’re muddy.', 'adj. 多泥的, 泥泞的', '/\'mʌdi | \'mʌdɪ/', 'muddy', 3);
INSERT INTO `words` VALUES (34772, 'They feature a complex network of tidal waterways, mudflats and small islands of salt-tolerant mangrove forests.', 'n. 泥滩', '/´mʌdflæt/', 'mudflats', 3);
INSERT INTO `words` VALUES (34773, 'Rocks sculptured by erosion, richly tinted mudstone hills and canyons, luminous sand dunes, and lush oases populate Death Valley National Park.', 'n. [地]泥岩', '/\'mʌdstəʊn | \'mʌd,ston/', 'mudstone', 3);
INSERT INTO `words` VALUES (34774, 'It was muggy and overcast.', 'adj. 闷热的', '/\'mʌgi | \'mʌɡi/', 'muggy', 3);
INSERT INTO `words` VALUES (34775, 'He says the guy who lent Christ his mule on Palm Sunday.', 'n. 骡子,十分固执的人', '/mju:l | mjuːl | mjul/', 'mule', 3);
INSERT INTO `words` VALUES (34776, 'a multicellular organism', 'adj. 多细胞的', '/,mʌlti\'seljulə | mʌltɪ\'seljʊlə | ,mʌlti\'sɛljəlɚ; ,mʌltaɪsɛljəlɚ/', 'multicellular', 3);
INSERT INTO `words` VALUES (34777, 'A new nonlinear weighted average multidirectional morphological filtering algorithm is proposed, which is used in suppressing speckle noise.', 'adj. 多方向的', '/,mʌltɪdɪ\'rekʃ(ə)n(ə)l; -daɪ- | ,mʌltɪdaɪ\'rɛkʃənəl/', 'multidirectional', 3);
INSERT INTO `words` VALUES (34778, 'a multifaceted campaign to reduce teen pregnancy', 'adj. 多层面的', '/,mʌlti\'fæsitid | mʌltɪ\'fæsɪtɪd | ,mʌltɪ\'fæsɪtɪd/', 'multifaceted', 3);
INSERT INTO `words` VALUES (34779, 'This hormone is multifunctional, but one of its main tasks is to act as a neurotransmitter and regulate serotonin levels.', 'adj. 多功能的', '/,mʌlti\'fʌŋkʃənəl/', 'multifunctional', 3);
INSERT INTO `words` VALUES (34780, 'Baxter was rushed to the hospital with multiple stab wounds.', 'adj. 多样的; n. 倍数', '/\'mʌltipl | \'mʌltɪpl | \'mʌltəpl/', 'multiple', 3);
INSERT INTO `words` VALUES (34781, 'Like many similar programs, it can handle multiplicative scale changes.', 'adj. 倍增的； 乘法的', '/ˌmʌltɪplɪ\'keɪtɪv | \'mʌltɪplɪketɪv/', 'multiplicative', 3);
INSERT INTO `words` VALUES (34782, 'It also explains why we use a specific multiplicity in the correspondence.', 'n. 多样性', '/,mʌlti\'plisəti | ,mʌltɪ\'plɪsɪtɪ | ,mʌltɪ\'plɪsəti/', 'multiplicity', 3);
INSERT INTO `words` VALUES (34783, 'Bacteria multiply quickly in warm food.', 'v. 繁殖, 乘', '/\'mʌltiplai | \'mʌltɪplaɪ/', 'multiply', 3);
INSERT INTO `words` VALUES (34784, 'a multipurpose building', 'adj. 多种用途的, 多目标的', '/,mʌlti\'pə:pəs/', 'multipurpose', 3);
INSERT INTO `words` VALUES (34785, 'The abbey was a maze of multistory wings, each added in a differing century, the architecture conspiring to create a jumbled complex that now housed four hundred brothers.', 'adj. 多层的,有多层楼的', '/\'mʌlti,stɔ:ri/', 'multistory', 3);
INSERT INTO `words` VALUES (34786, 'I had never seen such a multitude of stars before.', 'n. 多数, 群众', '/\'mʌlti,tju:d, -,tu:d | \'mʌltɪtjuːd | ˈmʌltɪˌtud, -ˌtjud/', 'multitude', 3);
INSERT INTO `words` VALUES (34787, 'So he planned a comprehensive, multivolume work to convince scientists and the world.', 'adj. 多卷的', '/,mʌlti\'vɔlju:m/', 'multivolume', 3);
INSERT INTO `words` VALUES (34788, 'Initially, the work was pretty mundane.', 'adj. 平凡的, 世俗的', '/,mʌn\'dein, \'mʌnd- | \'mʌndeɪn; mʌn\'deɪn | mʌn\'den/', 'mundane', 3);
INSERT INTO `words` VALUES (34789, 'the municipal waste dump', 'adj. 市政的', '/mju:\'nisipəl | mjʊ\'nɪsɪp(ə)l | mju\'nɪsɪpl/', 'municipal', 3);
INSERT INTO `words` VALUES (34790, 'This work is clearly connected with The Last Supper: the Christ has the same ethereal and elusive quality as the faded figure at the centre of Leonardo\'s sublime mural.', 'adj. 墙壁的 n壁画', '/\'mjuərəl | \'mjʊər(ə)l | \'mjʊrəl/', 'mural', 3);
INSERT INTO `words` VALUES (34791, 'Relax your stomach muscles , then stretch again.', 'n. 肌肉', '/\'mʌsl | \'mʌs(ə)l/', 'muscle', 3);
INSERT INTO `words` VALUES (34792, 'She was fast and strong, with a slender, muscular body.', 'adj. 肌肉发达的，强壮的', '/\'mʌskjulə | \'mʌskjʊlə | \'mʌskjəlɚ/', 'muscular', 3);
INSERT INTO `words` VALUES (34793, 'The second tenet to help nourish the joints is to become still and muscularly soft, allowing gravity to have us.', 'adj. 肌肉的', NULL, 'muscularly', 3);
INSERT INTO `words` VALUES (34794, '‘Somewhere,’ he mused, ‘I’ve heard your name before.’', 'v. 沉思， 冥想; n. 灵感', '/mjuːz | mjuz/', 'muse', 3);
INSERT INTO `words` VALUES (34795, 'the Museum of Modern Art', 'n. 博物馆', '/mju:\'ziəm | mjuː\'zɪəm | mju\'ziəm/', 'museum', 3);
INSERT INTO `words` VALUES (34796, 'mushroom soup', 'n. 蘑菇', '/\'mʌʃru:m, -rum | \'mʌʃruːm; -rʊm | \'mʌʃrʊm/', 'mushroom', 3);
INSERT INTO `words` VALUES (34797, 'a musical version of the fairy tale ‘Cinderella’', 'adj. 音乐的,悦耳的', '/\'mju:zikəl | \'mjuːzɪk(ə)l | \'mjuzɪkl/', 'musical', 3);
INSERT INTO `words` VALUES (34798, 'a talented young musician', 'n. 音乐家', '/mju:\'ziʃən | mjuː\'zɪʃ(ə)n | mjʊ\'zɪʃən/', 'musician', 3);
INSERT INTO `words` VALUES (34799, 'Rakae Jamil, a musicologist with the Sanjan Nagar Institute of Philosophy and Arts in Lahore, says there is no doubt that Michael Jackson influenced the pop scene in Pakistan.', 'n. 音乐学者', '/,mju:zi\'kɔlədʒist/', 'musicologist', 3);
INSERT INTO `words` VALUES (34800, 'Paul is then left to choose one box to open to retrieve the mussel.', 'n. [动]贻贝, 蚌类', '/\'mʌsəl | \'mʌsl/', 'mussel', 3);
INSERT INTO `words` VALUES (34801, 'I\'m not especially fond of mustard.', 'n. 芥菜, 芥末', '/\'mʌstəd | \'mʌstɚd/', 'mustard', 3);
INSERT INTO `words` VALUES (34802, 'Marianna, the duke\'s daughter, became mute after a shock.', 'adj. 哑的,不发音的 vt消除(声音)', '/mju:t | mjuːt | mjut/', 'mute', 3);
INSERT INTO `words` VALUES (34803, NULL, 'n. (早期的)电影放映机', '/\'mju:təskəup/', 'mutoscope', 3);
INSERT INTO `words` VALUES (34804, 'I didn’t like Dev, and the feeling seemed to be mutual.', 'adj. 相互的,共有的', '/\'mju:tʃuəl, -tjuəl | \'mjuːtʃʊəl; -tjʊəl | \'mjutʃuəl/', 'mutual', 3);
INSERT INTO `words` VALUES (34805, 'The acacia and its ant army are a textbook example of mutualism between species.', 'n. 互助论,互利共生', '/\'mju:tʃuəlizəm, -tju- | \'mjuːtʃʊəlɪz(ə)m; -tjʊə- | ˈmjuːtʃʊəˌlɪzəm/', 'mutualism', 3);
INSERT INTO `words` VALUES (34806, 'Without honesty, your best efforts to resolve conflicts will be wasted because you will not understand each other well enough to find mutually acceptable solutions.', 'adv. 互相地, 互助', '/\'mju:tʃuəli, -tjuəli | ˈmjuːtʃuəli | \'mjutʃuəli/', 'mutually', 3);
INSERT INTO `words` VALUES (34807, 'All my friends do not smoke.', 'pron. 我的', '/maɪ/', 'my', 3);
INSERT INTO `words` VALUES (34808, 'It is active in under- and postgraduate training in the fields of botany, mycology , and plant physiology.', 'n. [植]真菌学', '/mai\'kɔlədʒi | maɪ\'kɒlədʒɪ | maɪ\'kɑlədʒi/', 'mycology', 3);
INSERT INTO `words` VALUES (34809, 'the government’s myopic attitude to environmental issues', 'adj. 近视的； 缺乏远见的', '/maɪ\'oupiə | maɪ\'ɑpɪk/', 'myopic', 3);
INSERT INTO `words` VALUES (34810, 'the myriad causes of homelessness', 'adj. 无数的 n无数', '/\'miriəd | \'mɪrɪəd/', 'myriad', 3);
INSERT INTO `words` VALUES (34811, 'The police are investigating the mysterious deaths of children at the hospital.', 'adj. 神秘的', '/mi\'stiəriəs | mɪ\'stɪərɪəs | mɪ\'stɪrɪəs/', 'mysterious', 3);
INSERT INTO `words` VALUES (34812, NULL, 'adv. 神秘地, 故弄玄虚地', '/mis\'tiəriəsli | mɪs\'tɪrɪəsli/', 'mysteriously', 3);
INSERT INTO `words` VALUES (34813, 'Twenty years after the event, his death remains a mystery .', 'n. 神秘,神秘的事物', '/英 [ˈmɪstri] 美 [ˈmɪstəri] | ˈmɪstri/', 'mystery', 3);
INSERT INTO `words` VALUES (34814, 'music’s spiritual and mystical powers', 'adj. 神秘的', '/\'mistikəl | \'mɪstɪk(ə)l | \'mɪstɪkl/', 'mystical', 3);
INSERT INTO `words` VALUES (34815, 'Her disappearance has mystified her friends and neighbors.', 'v. 迷惑', '/\'mistifai | \'mɪstɪfaɪ | \'mɪstə\'fai/', 'mystify', 3);
INSERT INTO `words` VALUES (34816, 'Some of the mystique surrounding the presidency has gone forever.', 'n. 神秘性,奥秘', '/mi\'sti:k | mɪ\'stiːk | mɪ\'stik/', 'mystique', 3);
INSERT INTO `words` VALUES (34817, 'a book of Greek myths', 'n. 神话', '/miθ | mɪθ/', 'myth', 3);
INSERT INTO `words` VALUES (34818, 'a mythical creature like the Minotaur', 'adj. 神话的, 虚构的', '/\'miθikəl | \'mɪθɪkəl | \'mɪθɪkl/', 'mythical', 3);
INSERT INTO `words` VALUES (34819, 'Plato describes in “Phaedrus,” in mythological language, why and how the souls take their birth upon this plane, either as human or animal.', 'adj. 神话(学)的', '/,miθə\'lɔdʒikəl | mɪθə\'lɒdʒɪk(ə)l | ,mɪθə\'lɑdʒɪkl/', 'mythological', 3);
INSERT INTO `words` VALUES (34820, 'characters from classical mythology', 'n. 神话', '/mi\'θɔlɔdʒi | mɪ\'θɒlədʒɪ | mɪ\'θɑlədʒi/', 'mythology', 3);
INSERT INTO `words` VALUES (34821, 'Objective To review the experience in the diagnosis and surgical treatment of cardiac myxoma.', 'n. [医]粘液瘤', '/mik\'səumə | mɪk\'səʊmə | mɪk\'somə/', 'myxoma', 3);
INSERT INTO `words` VALUES (34822, 'The key was hanging on a nail by the door.', 'n. 指甲,钉子; v. 将钉牢', '/neil | neɪl | nel/', 'nail', 3);
INSERT INTO `words` VALUES (34823, 'a naive young girl', 'adj. 天真的', '/nɑ:\'i:v | naɪ\'iːv; nɑː\'iːv | naɪ\'iv/', 'naive', 3);
INSERT INTO `words` VALUES (34824, 'The children ran naked through the yard.', 'adj. 裸体的, 无遮盖的', '/\'neikid | \'neɪkɪd | \'nekɪd/', 'naked', 3);
INSERT INTO `words` VALUES (34825, 'Her name is Mandy Wilson.', 'n. 名字; v. 命名', '/neɪm | nem/', 'name', 3);
INSERT INTO `words` VALUES (34826, 'Three students were mentioned, namely John, Sarah and Sylvia.', 'adv. 即,也就是', '/\'neimli | \'neɪmlɪ | \'nemli/', 'namely', 3);
INSERT INTO `words` VALUES (34827, 'an afternoon nap', 'n. 小睡， 打盹', '/næp/', 'nap', 3);
INSERT INTO `words` VALUES (34828, 'Patient faint shows narcosis , high fever, convulsions, the skin cadaverous or the purple that show blueness.', 'n. 昏迷状态, 麻醉', '/nɑ:\'kəusis | nɑː\'kəʊsɪs/', 'narcosis', 3);
INSERT INTO `words` VALUES (34829, 'The truth of Johnson’s comment was recently brought home to me by the serene calm of a resident who was treating a particularly complicated narcotic-dependent patient.', 'n. 麻醉药,镇静剂; adj. 麻醉的', '/nɑ:\'kɔtik | nɑː\'kɒtɪk | nɑr\'kɑtɪk/', 'narcotic', 3);
INSERT INTO `words` VALUES (34830, 'a wildlife film narrated by David Attenborough', 'v. 叙述,作解说', '/\'næreit, nə\'reit | nə\'reɪt | næret/', 'narrate', 3);
INSERT INTO `words` VALUES (34831, 'I need some good pictures for narration.', 'n. 叙述', '/nə\'reiʃən | nə\'reɪʃ(ə)n | nə\'reʃən/', 'narration', 3);
INSERT INTO `words` VALUES (34832, 'At several points in the narrative the two stories cross.', 'n. 故事,叙述; adj. 叙述的', '/\'nærətiv | \'nærətɪv/', 'narrative', 3);
INSERT INTO `words` VALUES (34833, '“I can never look now at the Milky Way”, said the narrator in “The Sentinel”, “without wondering from which of those banked clouds of stars the emissaries are coming.', 'n. 讲述者', '/nə\'reitə, næ- | nə\'reɪtə | næ\'retɚ/', 'narrator', 3);
INSERT INTO `words` VALUES (34834, 'The stairs were very narrow.', 'adj. 狭窄(隘)的,勉强的; v. 变窄,压缩', '/\'nærəu | \'nærəʊ | \'næro/', 'narrow', 3);
INSERT INTO `words` VALUES (34835, NULL, 'adj. 有限的, 精密的; n. 海峡', NULL, 'narrower', 3);
INSERT INTO `words` VALUES (34836, 'He was narrowly defeated in the election.', 'adv. 勉强地, 精细地', '/\'nærəuli | \'nærəʊlɪ | \'næroli/', 'narrowly', 3);
INSERT INTO `words` VALUES (34837, 'the President’s radio broadcast to the nation', 'n. 国家,民族', '/\'neiʃən | \'neɪʃ(ə)n | \'neʃən/', 'nation', 3);
INSERT INTO `words` VALUES (34838, 'Religion matters very much at a national level.', 'adj. 国家的,民族的', '/\'næʃənəl | \'næʃ(ə)n(ə)l | \'næʃnəl/', 'national', 3);
INSERT INTO `words` VALUES (34839, 'Scottish national­ism', 'n. 民族主义, 国家主义', '/\'næʃənəlizəm | \'næʃ(ə)n(ə)lɪz(ə)m | \'næʃnəlɪzəm/', 'nationalism', 3);
INSERT INTO `words` VALUES (34840, 'They were encouraging nationalistic sentiment among the students.', 'adj. 国家主义的', '/,næʃənə\'listik | ,næʃnə\'lɪstɪk/', 'nationalistic', 3);
INSERT INTO `words` VALUES (34841, 'a nationally recognised qualification', 'adv. 全国性地, 在全国范围内', '/\'næʃənəli/', 'nationally', 3);
INSERT INTO `words` VALUES (34842, 'a nationwide search for a missing British tourist', 'adj. 全国性的', '/\'neiʃənwaid | \'neɪʃ(ə)nwaɪd; -\'waɪd | ,neʃn\'waɪd/', 'nationwide', 3);
INSERT INTO `words` VALUES (34843, 'They never saw their native land again.', 'adj. 本国的,本土的,当地的; n. 本地人', '/\'neitiv | \'neɪtɪv | \'netɪv/', 'native', 3);
INSERT INTO `words` VALUES (34844, 'Still, I sympathize with one motive behind naturalism — the aspiration to think in a scientific spirit.', 'n. 自然主义', '/\'nætʃərəlizəm | \'nætʃ(ə)rəlɪz(ə)m | \'nætʃrəlɪzəm/', 'naturalism', 3);
INSERT INTO `words` VALUES (34845, 'I am sometimes described as a naturalist.', 'n. 自然主义者', '/\'nætʃərəlist | \'nætʃ(ə)rəlɪst | \'nætʃrəlɪst/', 'naturalist', 3);
INSERT INTO `words` VALUES (34846, 'These drawings are among his most naturalistic.', 'adj. 自然的, 自然主义的', '/,nætʃərə\'listik | nætʃ(ə)rə\'lɪstɪk | ,nætʃrə\'lɪstɪk/', 'naturalistic', 3);
INSERT INTO `words` VALUES (34847, 'We grew up in the countryside, surrounded by the beauties of nature.', 'n. 自然(界),本性', '/\'neitʃə | \'neɪtʃə | \'netʃɚ/', 'nature', 3);
INSERT INTO `words` VALUES (34848, 'I felt slightly nauseous.', 'adj. 恶心的； 令人作呕的， 令人厌恶的', '/\'nɔːʃəs | \'nɔʃəs/', 'nauseous', 3);
INSERT INTO `words` VALUES (34849, 'a naval officer', 'adj. 海军的', '/\'neɪvl | \'nevl/', 'naval', 3);
INSERT INTO `words` VALUES (34850, '...the navigable portion of the Nile.', 'adj. 可航行的,可操纵的', '/\'næviɡəbl | \'nævɪgəb(ə)l | \'nævɪɡəbl/', 'navigable', 3);
INSERT INTO `words` VALUES (34851, 'The river is too dangerous to navigate.', 'v. 航行,航海', '/\'næviɡeit | \'nævɪgeɪt | \'nævə\'get/', 'navigate', 3);
INSERT INTO `words` VALUES (34852, 'compasses and other instruments of navigation', 'n. 航海,航行', '/,nævi\'ɡeiʃən | nævɪ\'geɪʃ(ə)n | \'nævə\'geʃən/', 'navigation', 3);
INSERT INTO `words` VALUES (34853, 'The crash was a direct result of inadequate navigational aids.', 'adj. 导航的, 航行的', '/,nævi\'geiʃənəl | ,nævɪ\'geɪʃnəl | ,nævə\'geʃənəl/', 'navigational', 3);
INSERT INTO `words` VALUES (34854, 'That first citation is from 1557 and comes to us from a great navigator and map maker of the time.', 'n. 航海家', '/\'næviɡeitə | \'nævɪgeɪtə | \'nævɪɡetɚ/', 'navigator', 3);
INSERT INTO `words` VALUES (34855, NULL, 'adv. 穴居人的', '/ni\'ændətɑ:l; -θɔ:l/', 'neanderthal', 3);
INSERT INTO `words` VALUES (34856, 'I didn’t remember to phone until near the end of the week.', 'adv. 在近处; v&prep. 靠(接)近; adj. 接近的', '/niə | nɪə | nɪr/', 'near', 3);
INSERT INTO `words` VALUES (34857, 'Lucy was staying in the nearby town of Hamilton.', 'adj. 附近的,邻近的; adv. 在附近', '/\'niə\'bai | \'nɪəbaɪ | ,nɪr\'baɪ/', 'nearby', 3);
INSERT INTO `words` VALUES (34858, 'It took nearly two hours to get here.', 'adv. 几乎,差不多', '/\'niəli | \'nɪəlɪ | \'nɪrli/', 'nearly', 3);
INSERT INTO `words` VALUES (34859, 'God is nearer to me than I am to myself; my existence depends on the nearness and the presence of God.', 'n. 靠近, 接近', '/\'niənis/', 'nearness', 3);
INSERT INTO `words` VALUES (34860, 'neat handwriting', 'adj. 整洁的, 灵巧的, 优雅的', '/ni:t | niːt | nit/', 'neat', 3);
INSERT INTO `words` VALUES (34861, 'My sister has been preaching at me again about my lack of neatness.', 'n. 整洁, 干净', '/\'ni:tnis/', 'neatness', 3);
INSERT INTO `words` VALUES (34862, 'As the nebula collapsed because of its gravity, it spun faster and flattened into a disk.', 'n. 星云', '/\'nebjulə | \'nebjʊlə | \'nɛbjələ/', 'nebula', 3);
INSERT INTO `words` VALUES (34863, 'Ultraviolet radiation from the hot star powers the nebular glow.', 'adj. [天]星云的', '/\'nebjulə/', 'nebular', 3);
INSERT INTO `words` VALUES (34864, 'The booklet provides all the necessary information about the college.', 'adj. 必要的,必然的; n. 必需品', '/\'nesisəri | ˈnɛsɪsərɪ | ˈnɛsəˌsɛri/', 'necessary', 3);
INSERT INTO `words` VALUES (34865, 'Lack of money necessitated a change of plan.', 'v. 使成为必需,迫使', '/ni\'sesi,teit, nə- | nɪ\'sesɪteɪt | nə\'sɛsɪtet/', 'necessitate', 3);
INSERT INTO `words` VALUES (34866, 'She saw books as a necessity, not a luxury.', 'n. 需要,必需品', '/ni\'sesəti, nə- | nɪ\'sesɪtɪ | nə\'sɛsəti/', 'necessity', 3);
INSERT INTO `words` VALUES (34867, 'Mike rubbed the back of his neck.', 'n. 脖子, 颈', '/nek | nɛk/', 'neck', 3);
INSERT INTO `words` VALUES (34868, '...a diamond necklace and matching earrings.', 'n. 项链', '/\'neklis | \'neklɪs | \'nɛkləs/', 'necklace', 3);
INSERT INTO `words` VALUES (34869, '...liver necrosis.', 'n. 坏死', '/nə\'krəusis, ne- | ne\'krəʊsɪs | nɛ\'krosɪs/', 'necrosis', 3);
INSERT INTO `words` VALUES (34870, NULL, 'n. [希神] 神酒, 任何美味的饮料, 花蜜', '/\'nektə | \'nɛktɚ/', 'nectar', 3);
INSERT INTO `words` VALUES (34871, 'She carried hypodermic needles and syringes in her bag.', 'n. 针; v. 缝纫,刺激', '/\'ni:dl | \'niːd(ə)l | \'nidl/', 'needle', 3);
INSERT INTO `words` VALUES (34872, 'We report on an unusual case of penetrating tracheal injury caused by a needlefish.', 'n. [动] 颌针鱼(一种长嘴便鳞之海鱼)', '/\'ni:dlfiʃ | \'niːd(ə)lfɪʃ | \'nidl,fɪʃ/', 'needlefish', 3);
INSERT INTO `words` VALUES (34873, 'The Pacific viperfish has jagged, needlelike teeth so outsized it can\'t close its mouth.', 'adj. 针状的', '/\'ni:dllaik/', 'needlelike', 3);
INSERT INTO `words` VALUES (34874, 'The report caused needless anxiety to women who have attended the clinic.', 'adj. 不需要的, 不必要的', '/\'ni:dlis | \'niːdlɪs | \'nidləs/', 'needless', 3);
INSERT INTO `words` VALUES (34875, '...watching my mother and grandmothers doing needlework.', 'n. 刺绣, 缝纫', '/\'ni:dlwə:k | \'niːd(ə)lwɜːk | \'nidlwɝk/', 'needlework', 3);
INSERT INTO `words` VALUES (34876, 'a needy family', 'adj. 贫困的, 缺乏生活必需品的', '/\'ni:di | \'niːdɪ | \'nidi/', 'needy', 3);
INSERT INTO `words` VALUES (34877, 'He warned that to negate the results of elections would only make things worse.', 'v. 否定, 打消', '/ni\'ɡeit, \'neɡeit, \'ni:- | nɪ\'geɪt | nɪˈɡet/', 'negate', 3);
INSERT INTO `words` VALUES (34878, 'students with a negative attitude to school', 'adj. 否定的,消极的', '/\'neɡətiv | \'negətɪv | \'nɛɡətɪv/', 'negative', 3);
INSERT INTO `words` VALUES (34879, 'Many of these ideas have been neglected by modern historians.', 'vt&n. 忽视，忽略', '/ni\'ɡlekt | nɪ\'glekt | nɪ\'glɛkt/', 'neglect', 3);
INSERT INTO `words` VALUES (34880, 'Mr Brown was found guilty of negligent driving.', 'adj. 忽略的； 疏忽的； 粗心大意的', '/\'neglɪdʒənt | \'nɛɡlɪdʒənt/', 'negligent', 3);
INSERT INTO `words` VALUES (34881, 'The damage done to his property was negligible.', 'adj. 可以忽略的, 不予重视的', '/\'neɡlidʒəbl | \'neglɪdʒɪb(ə)l | \'nɛɡlɪdʒəbl/', 'negligible', 3);
INSERT INTO `words` VALUES (34882, 'But that can be ignored, is negligibly small.', 'adv. 可忽略不计地, 微不足道地, 极小地', '/\'neglidʒibli/', 'negligibly', 3);
INSERT INTO `words` VALUES (34883, 'His first aim is to get the warring parties back to the negotiating table (= discussing something ).', 'v. 商议, 谈判', '/ni\'ɡəuʃieit, -si- | nɪ\'gəʊʃɪeɪt | nɪ\'ɡoʃɪet/', 'negotiate', 3);
INSERT INTO `words` VALUES (34884, 'Warren said, \"We have had meaningful negotiations and I believe we are very close to a deal.\"', 'n. 商议, 谈判', '/ni,ɡəuʃi\'eiʃən, -si- | nɪgəʊʃɪ\'eɪʃ(ə)n | nɪ,ɡoʃɪ\'eʃən/', 'negotiation', 3);
INSERT INTO `words` VALUES (34885, 'I parked my baby at the neighbor\'s house.', 'n. 邻居,邻国', '/\'neibə | \'neɪbə | \'nebɚ/', 'neighbor', 3);
INSERT INTO `words` VALUES (34886, 'What happened in the factory is being whispered about the neighborhood.', 'n. 附近,邻近', '/\'neɪbə,hʊd | \'nebɚ,hʊd/', 'neighborhood', 3);
INSERT INTO `words` VALUES (34887, 'Neither Oleg’s mother nor his father spoke English.', 'a&pron. 两者都不; conj. 既不也不', '/ˈnaɪðə; ˈniːðə | ˈniðɚ; ˈnaɪðɚ/', 'neither', 3);
INSERT INTO `words` VALUES (34888, 'a palace built in a neoclassical style', 'adj. 新古典主义的', '/,ni:əu\'klæsikəl | niːəʊ\'klæsɪk(ə)l | ,nio\'klæsɪkl/', 'neoclassical', 3);
INSERT INTO `words` VALUES (34889, '...neolithic culture.', 'adj. 新石器时代的', '/,ni:əu\'liθik | ˌni:əˈlɪθɪk | ˌniəˈlɪθɪk/', 'neolithic', 3);
INSERT INTO `words` VALUES (34890, 'Inert gases like neon and argon have eight electrons in their outer shell.', 'n. [化]氖', '/\'ni:ɔn, -ən | \'niːɒn | \'niɑn/', 'neon', 3);
INSERT INTO `words` VALUES (34891, '“Full, unabashed, total irradiation of a neonate,” Dr. Sclafani said, adding, “This poor, defenseless baby.', 'n. 初生婴儿', '/\'ni:əuneit | \'niːə(ʊ)neɪt | \'nionet/', 'neonate', 3);
INSERT INTO `words` VALUES (34892, 'I am planning a 25th birthday party for my nephew.', 'n. 侄子, 外甥', '/\'nefju: | \'nefjuː; \'nevjuː | \'nɛfju/', 'nephew', 3);
