INSERT INTO `words` VALUES (34895, 'I wish you’d stop looking at me like that. You’re making me nervous.', 'adj. 紧张的,不安的', '/\'nə:vəs | \'nɜːvəs | \'nɝvəs/', 'nervous', 3);
