INSERT INTO `words` VALUES (34904, 'There are a certain number of neural stem cells, which can be potentially differentiated into the neurons or neuroglia, in the adult mammalian brain.', 'n. [解]神经胶(质)', '/njuə\'rɔɡliə | ,njʊə\'rɒglɪə | njʊ\'rɑglɪə/', 'neuroglia', 3);
INSERT INTO `words` VALUES (34905, 'What it does mean is that, for whatever reason, this particular neuron was activated by this particular scene, almost certainly with a network of other neurons across the brain.', 'n. [解]神经细胞,神经元', '/\'njuərɔn | \'njʊərɒn | \'nʊrɑn/', 'neuron', 3);
