INSERT INTO `words` VALUES (34907, 'All drugs of abuse stimulate the release of the neurotransmitter dopamine.', 'n. [生化]神经传递素', '/,njuərəutrænz\'mitə, -træns- | ,njʊərəʊtrænz\'mɪtə | \'nʊrotrænzmɪtɚ/', 'neurotransmitter', 3);
INSERT INTO `words` VALUES (34908, 'I always tried to remain neutral when they started arguing.', 'adj. 中立的, 中性的', '/\'nju:trəl | \'njuːtr(ə)l | \'nʊtrəl/', 'neutral', 3);
INSERT INTO `words` VALUES (34909, 'Net neutrality, or not?', 'n. 中立, 中性', '/nju:\'træləti | njuː\'trælɪtɪ | nu\'træləti/', 'neutrality', 3);
INSERT INTO `words` VALUES (34910, NULL, 'v. 压制', '/\'nju:trəlaiz | \'nʊtrə\'laɪz/', 'neutralize', 3);
