INSERT INTO `words` VALUES (34912, 'If you did all that and come from a broken home in Nevada, so much the better.', 'n. 内华达州(美国西部内陆州)', '/ni\'vædə; -\'vɑ:- | nə\'vædə/', 'Nevada', 3);
