INSERT INTO `words` VALUES (34944, 'the nobility of his intentions', 'n. 高贵,贵族', '/nəu\'biləti | nə(ʊ)\'bɪlɪtɪ | no\'bɪləti/', 'nobility', 3);
INSERT INTO `words` VALUES (34945, 'It’s very noble of you to spend all your weekends helping the old folk.', 'adj. 高尚的,贵族的', '/\'nəubl | \'nəʊb(ə)l | \'nobl/', 'noble', 3);
INSERT INTO `words` VALUES (34946, 'I knocked on the door but nobody answered.', 'pron. 无人, 没有任何人', '/\'nəubədi, -bɔdi | \'nəʊbədɪ/', 'nobody', 3);
INSERT INTO `words` VALUES (34947, 'Hamsters are nocturnal creatures.', 'adj. 夜行性的； 夜间发生的', '/nɑːk\'tɜːrnl | nɑk\'tɝnl/', 'nocturnal', 3);
INSERT INTO `words` VALUES (34948, 'A simple and rapid diagnostic field test for BU is urgently needed because early disease – nodule – can be treated locally and inexpensively.', 'n. 节结', '/\'nɔdju:l, -dʒu:l | \'nɒdjuːl | \'nɑdʒul/', 'nodule', 3);
INSERT INTO `words` VALUES (34949, 'What’s that noise?', 'n. 喧闹声, 噪声', '/nɔiz | nɒɪz | nɔɪz/', 'noise', 3);
