INSERT INTO `words` VALUES (34954, 'In particular, it will usher in a new version of a very old idea: nomadism.', 'n. 游牧,流浪', '/\'nəʊmædɪzəm | \'nəumædizəm, \'nɔ-/', 'nomadism', 3);
