INSERT INTO `words` VALUES (34956, 'This week one of them will be nominated by the Democratic Party for the presidency of the United States.', 'v. 提名, 推荐', '/\'nɔmineit, \'nɔminət, -neit | \'nɒmɪneɪt | \'nɑmɪnet/', 'nominate', 3);
INSERT INTO `words` VALUES (34957, 'the Democratic Party presidential nominee', 'n. 被提名者， 被任命者', '/ˌnɑːmɪ\'niː | ,nɑmɪ\'ni/', 'nominee', 3);
INSERT INTO `words` VALUES (34958, 'Many causes have been proposed for both the intelligence gap and the Flynn effect, including education, income, and even nonagricultural labor.', 'adj. 非农业的', '/,nɔnæɡri\'kʌltʃərəl/', 'nonagricultural', 3);
INSERT INTO `words` VALUES (34959, '‘Has he got a girlfriend?’ Jill asked, trying to sound nonchalant.', 'adj. 若无其事的, 不关心的, 冷淡的', '/\'nɔnʃələnt, ,nɔnʃə\'lɑ:nt | \'nɒnʃ(ə)l(ə)nt | ,nɑnʃə\'lɑnt/', 'nonchalant', 3);
INSERT INTO `words` VALUES (34960, 'Their views are nonconformist and their political opinions are extreme.', 'adj. 不信奉英国国教的 n非国教徒', '/,nɔnkən\'fɔ:mist | nɒnkən\'fɔːmɪst | ,nɑnkən\'fɔrmɪst/', 'nonconformist', 3);
