INSERT INTO `words` VALUES (34974, '‘I’m a prisoner in my own home.’ ‘Nonsense!’', 'n. 胡说, 废话', '/\'nɔnsəns | \'nɒns(ə)ns | \'nɑnsɛns/', 'nonsense', 3);
