INSERT INTO `words` VALUES (35009, NULL, 'adv. 显著地，显然', '/\'nəutisəbli | \'notɪsəbli/', 'noticeably', 3);
INSERT INTO `words` VALUES (35010, 'The skipper notified the coastguard of the tragedy.', 'vt. 通报', '/\'noutɪfaɪ | \'notə\'fai/', 'notify', 3);
