INSERT INTO `words` VALUES (35012, 'a notorious computer hacker', 'adj. 臭名昭著的', '/nəu\'tɔ:riəs | nə(ʊ)\'tɔːrɪəs | no\'tɔrɪəs/', 'notorious', 3);
INSERT INTO `words` VALUES (35013, 'Could some of the deaths have been prevented in this notoriously high-risk area?', 'adv. 臭名昭著地, 众所周知地', '/nəu\'tɔ:riəsli | noˈtɔːriəsli/', 'notoriously', 3);
INSERT INTO `words` VALUES (35014, 'Notwithstanding differences, there are clear similarities in all of the world’s religions.', 'prep. ／ ad尽管', '/,nɔtwiθ\'stændiŋ, -wið- | nɒtwɪð\'stændɪŋ; -wɪθ- | ,nɑtwɪθ\'stændɪŋ/', 'notwithstanding', 3);
INSERT INTO `words` VALUES (35015, 'The cream contains vitamin A to nourish the skin.', 'v. 滋养, 使健壮,', '/\'nʌriʃ, \'nə:- | \'nʌrɪʃ | \'nɜrɪʃ/', 'nourish', 3);
