INSERT INTO `words` VALUES (35019, 'The key to success as a romantic novelist is absolute belief in your story.', 'n. (长篇)小说家', '/\'nɔvəlist | \'nɒv(ə)lɪst | \'nɑvlɪst/', 'novelist', 3);
