INSERT INTO `words` VALUES (35036, 'Numerous attempts have been made to hide the truth.', 'adj. 众多的,许多的', '/\'nju:mərəs | \'njuːm(ə)rəs | \'numərəs/', 'numerous', 3);
INSERT INTO `words` VALUES (35037, 'The nurse is coming to give you an injection.', 'n. 护士,保姆; v. 护理,照料', '/nə:s | nɜːs | nɝs/', 'nurse', 3);
INSERT INTO `words` VALUES (35038, 'She puts her baby in this nursery and then goes back to work.', 'n. 托儿所', '/\'nə:səri | \'nɜːs(ə)rɪ | \'nɝsəri/', 'nursery', 3);
INSERT INTO `words` VALUES (35039, 'The elderly at the nursing home have some protections, but not much.', 'n. 看护, 养育', '/\'nə:siŋ | \'nɜːsɪŋ | \'nɝsɪŋ/', 'nursing', 3);
INSERT INTO `words` VALUES (35040, 'The human organism learns partly by nature, partly by nurture.', 'n. 养育,教育; v. 养育,给与营养物', '/\'nə:tʃə | \'nɜːtʃə | \'nɝtʃɚ/', 'nurture', 3);
