INSERT INTO `words` VALUES (35044, 'Cooking vegetables for too long lessens their nutritional value.', 'adj. 营养的,滋养的', '/nju:\'triʃənəl | njuː\'trɪʃənəl | njʊ\'trɪʃənl/', 'nutritional', 3);
