INSERT INTO `words` VALUES (35046, 'Nutritionists say only 33 percent of our calorie intake should be from fat.', 'n. 营养学家', '/njʊ\'trɪʃ(ə)nɪst | nu\'trɪʃənɪst/', 'nutritionist', 3);
