INSERT INTO `words` VALUES (35048, 'Coconut milk has little nutritive value.', 'adj. 营养的; n. 营养物', '/\'nju:tritiv | \'njuːtrɪtɪv | \'njʊtrətɪv/', 'nutritive', 3);
INSERT INTO `words` VALUES (35049, 'nylon fabric', 'n. 尼龙', '/\'nailɔn | \'naɪlɒn | \'naɪlɑn/', 'nylon', 3);
