INSERT INTO `words` VALUES (35057, 'The little boy made no effort to obey.', 'v. 服从, 顺从', '/əu\'bei | ə(ʊ)\'beɪ | ə\'be/', 'obey', 3);
INSERT INTO `words` VALUES (35058, 'His obituary was published in one edition of his own newspaper before it was discovered that he was alive.', 'n. 讣闻， 讣告', '/ou\'bɪtʃueri | o\'bɪtʃuɛri/', 'obituary', 3);
INSERT INTO `words` VALUES (35059, 'a culture that objectifies women', 'v. 使客观化,具体化', '/əb\'dʒektifai, ɔb- | ɒb\'dʒektɪfaɪ | əb\'dʒɛktɪfaɪ/', 'objectify', 3);
INSERT INTO `words` VALUES (35060, 'He vowed to achieve certain objectives before the end of his presidency.', 'n. 目标,目的a客观的', '/əb\'dʒektiv, ɔb- | əb\'dʒektɪv | əb\'dʒɛktɪv/', 'objective', 3);
