INSERT INTO `words` VALUES (35068, 'Bradford made an obscene gesture.', 'adj. 淫秽的， 下流的； 骇人听闻的； 可憎的， 可恶的', '/əb\'siːn | əb\'sin/', 'obscene', 3);
