INSERT INTO `words` VALUES (35071, 'An observatory on the back side of the Moon would be a giant leap for astronomy, but there is a for more important reason to return.', 'adj. 天文台,气象台', '/əb\'zə:vitəri, ɔb- | əb\'zɜːvət(ə)rɪ | əb\'zɝvətɔri/', 'observatory', 3);
