INSERT INTO `words` VALUES (35082, 'The obvious way of reducing pollution is to use cars less.', 'adj. 明显的,显而易见的', '/\'ɔbviəs | \'ɒbvɪəs | \'ɑbvɪəs/', 'obvious', 3);
