INSERT INTO `words` VALUES (35111, 'If inscribe, troublesome everybody. Favour, bit more specific. Thank! Read a language kind can you take an examination of officeholder?', 'n. 官员,公务员', '/\'ɔfis,həuldə, \'ɔ:- | \'ɒfɪs,həʊldə | \'ɔfɪs,holdɚ/', 'officeholder', 3);
INSERT INTO `words` VALUES (35112, 'You\'d better declare the camera to the official.', 'n. 官员; adj. 官方的,正式的', '/ə\'fɪʃ(ə)l | əˈfɪʃəl; oʊˈfɪʃəl/', 'official', 3);
INSERT INTO `words` VALUES (35113, 'The new church was officially opened on July 5th.', 'adv. 职务上, 正式', '/ə\'fiʃəli | ə\'fɪʃəlɪ | ə\'fɪʃəli/', 'officially', 3);
INSERT INTO `words` VALUES (35114, 'an officious traffic warden', 'adj. 爱发号施令的， 爱指手画脚的', '/ə\'fɪʃəs/', 'officious', 3);
INSERT INTO `words` VALUES (35115, 'Cuts in food prices will be offset by direct payments to farmers.', 'v. 补偿，抵消', '/,ɔf\'set, ,ɔ:-, \'ɔfset, \'ɔ:- | \'ɒfset | ,ɔf\'sɛt/', 'offset', 3);
INSERT INTO `words` VALUES (35116, 'the Mafia and its offshoots', 'n. 分支, 支流', '/\'ɔfʃu:t, \'ɔ:- | \'ɒfʃuːt | \'ɔfʃut/', 'offshoot', 3);
INSERT INTO `words` VALUES (35117, 'The building can accommodate all of the offshore workers and protect them from hurricane damage.', 'a&ad. 离岸的,近海的', '/\'ɔf\'ʃɔ:, \'ɔ:- | \'ɒfʃɔː; ɒf\'ʃɔː | ,ɔf\'ʃɔr/', 'offshore', 3);
INSERT INTO `words` VALUES (35118, 'a young mother trying to control her offspring', 'n. 儿女,子孙', '/\'ɔfspriŋ, \'ɔ:- | \'ɒfsprɪŋ | \'ɔfsprɪŋ/', 'offspring', 3);
INSERT INTO `words` VALUES (35119, 'Then came to him the disciples of John, saying, Why do we and the Pharisees fast oft, but thy disciples fast not?', 'adv. 常常, 再三', '/ɔft, ɔ:ft | ɒft | ɔft/', 'oft', 3);
