INSERT INTO `words` VALUES (35124, 'That leaves nothing for medical insurance for Baines or her husband, although the children get free cover from the state of Oklahoma. So she\'s at the free clinic to get blood tests.', 'n. 俄克拉荷马州', '/,əuklə\'həumə/', 'Oklahoma', 3);
