INSERT INTO `words` VALUES (35129, 'Please don’t omit any details, no matter how trivial they may seem.', 'v. 省略,遗漏', '/əu\'mit | ə(ʊ)\'mɪt | ə\'mɪt/', 'omit', 3);
INSERT INTO `words` VALUES (35130, 'the Saturday omnibus edition of ‘Brookside’', 'n. 公共汽车, 精选集 a综合性的', '/\'ɔmnibəs, -bʌs | \'ɒmnɪbəs | \'ɑmnɪbəs/', 'omnibus', 3);
INSERT INTO `words` VALUES (35131, 'Doug lived in the shadow of his seemingly omnipotent father.', 'adj. 全能的, 无所不能的', '/ɔm\'nipətənt | ɒm\'nɪpət(ə)nt | ɑm\'nɪpətənt/', 'omnipotent', 3);
INSERT INTO `words` VALUES (35132, 'I’ve only met her once.', 'adv. 一次,曾经; conj. 一旦…(就…)', '/wʌns/', 'once', 3);
INSERT INTO `words` VALUES (35133, 'Instead of trying to disidentify from the ego, we need to embrace the ego while merging it with a sense of oneness.', 'n. 单一, 统一', '/\'wʌnnis | \'wʌnnɪs | \'wʌnnəs/', 'oneness', 3);
INSERT INTO `words` VALUES (35134, 'The onetime heir apparent had played an instrumental role this year in propping up his father\'s rule and his crackdown against the rebellion that ultimately ended his 42-year grip on power.', 'adj. 从前的, 一度的; adv. 从前', '/\'wʌntaim/', 'onetime', 3);
INSERT INTO `words` VALUES (35135, 'their ongoing search for a new director', 'adj. 正在进行的', '/\'ɔn,ɡəuiŋ, \'ɔ:n- | \'ɒngəʊɪŋ | \'ɑnɡoɪŋ/', 'ongoing', 3);
INSERT INTO `words` VALUES (35136, 'Chop the onions finely.', 'n. 洋葱', '/\'ʌnjən/', 'onion', 3);
INSERT INTO `words` VALUES (35137, 'A crowd of onlookers had gathered at the scene of the accident.', 'n. 旁观者', '/\'ɔn,lukə, \'ɔ:n- | \'ɒnlʊkə | \'ɑnlʊkɚ/', 'onlooker', 3);
INSERT INTO `words` VALUES (35138, 'He was killed by an onrushing locomotive.', 'adj. 猛冲的', '/\'ɑn,rʌʃɪŋ/', 'onrushing', 3);
