INSERT INTO `words` VALUES (35141, 'Even today I get nervous before I go onstage.', 'adj. 台上的,舞台表演区的', '/\'ɔn\'steidʒ, \'ɔ:n- | ɒn\'steɪdʒ | \'ɔn\'stedʒ/', 'onstage', 3);
INSERT INTO `words` VALUES (35142, 'We’re going to see your mother, in Toronto, Ontario.', 'n. 安大略湖[北美洲]', '/ɔn\'tεəriəu/', 'Ontario', 3);
INSERT INTO `words` VALUES (35143, 'The boy emptied out all his pockets onto the table.', 'prep. 在之上', '/\'ɒntuː | ˈɑnˌtu, -tə, ˈɔn-/', 'onto', 3);
INSERT INTO `words` VALUES (35144, 'The company offers flights to Amsterdam with onward travel to The Hague.', 'adj. 向前的; adv. 向前,在前面', '/\'ɔnwəd | \'ɒnwəd | \'ɑnwɚd/', 'onward', 3);
