INSERT INTO `words` VALUES (35148, 'He threw the door open and ran down the stairs.', 'adj. 开的,开放的; v. 开', '/\'əupən | \'əʊp(ə)n | \'opən/', 'open', 3);
INSERT INTO `words` VALUES (35149, 'The opening of the scene depicts Akhnaten and his family in a moment of intimacy.', 'n. 开口, 开始', '/\'əupəniŋ | \'əʊp(ə)nɪŋ | \'opənɪŋ/', 'opening', 3);
INSERT INTO `words` VALUES (35150, 'Sarah talked openly about her problems.', 'adv. 不隐瞒地, 公然地', '/\'opənli/', 'openly', 3);
INSERT INTO `words` VALUES (35151, 'We go to the opera (= go to a performance of opera ) regularly.', 'n. 歌剧', '/\'ɔpərə | \'ɒp(ə)rə | \'ɑprə/', 'opera', 3);
INSERT INTO `words` VALUES (35152, 'The actual tests would employ the well-honed methods of operant conditioning, developed initially on pigeons, in which the test subject has first to work out what is going on by trial and error.', 'adj. 运转中的；生效的；操作性的; n. 起作用的人', '/\'ɑːpərænt | \'ɑpərənt/', 'operant', 3);
INSERT INTO `words` VALUES (35153, 'The whole tax system is now operating more efficiently.', 'v. 操作,运转', '/\'ɒpəreɪt | \'ɑpə\'ret/', 'operate', 3);
INSERT INTO `words` VALUES (35154, 'The aircraft’s engine operation was normal.', 'n. 运转,操作,实施', '/,ɔpə\'reiʃən | ɒpə\'reɪʃ(ə)n | ,ɑpə\'reʃən/', 'operation', 3);
INSERT INTO `words` VALUES (35155, 'The boat should be operational by this afternoon.', 'adj. 操作的, 运作的', '/,ɔpə\'reiʃənəl | ɒpə\'reɪʃ(ə)n(ə)l | \'ɑpə\'reʃənl/', 'operational', 3);
INSERT INTO `words` VALUES (35156, 'computers which can be used by untrained operators', 'n. 操作员, 技工', '/\'ɔpəreitə | \'ɒpəreɪtə | \'ɑpəretɚ/', 'operator', 3);
INSERT INTO `words` VALUES (35157, 'When choosing an insurance policy it’s best to get an independent opinion.', 'n. 意见,看法', '/ə\'pinjən | ə\'pɪnjən/', 'opinion', 3);
INSERT INTO `words` VALUES (35158, 'She bowled out her opponent.', 'adj. 对立的; n. 对手', '/ə\'pəunənt | ə\'pəʊnənt | ə\'ponənt/', 'opponent', 3);
INSERT INTO `words` VALUES (35159, 'Voters dislike opportunists – politicians who change their policies according to opinion polls.', 'n. 机会主义者,投机取巧者', '/ɒpə\'tjuːnɪst | ,ɑpɚ\'tunɪst/', 'opportunist', 3);
INSERT INTO `words` VALUES (35160, 'Many of the party\'s members joined only for opportunistic reasons.', 'adj. 机会主义的, 投机取巧的', '/,ɔpətju:\'nistik | ɒpətjuː\'nɪstɪk | ,ɑpɚtu\'nɪstɪk/', 'opportunistic', 3);
INSERT INTO `words` VALUES (35161, 'There are fewer opportunities for new graduates this year.', 'n. 机会', '/,ɔpə\'tju:niti | ɒpə\'tjuːnɪtɪ | ˌɑpɚˈtunɪti, -ˈtju-/', 'opportunity', 3);
INSERT INTO `words` VALUES (35162, 'Congress is continuing to oppose the President’s health care budget.', 'v. 反对,对抗', '/ə\'pəuz | ə\'pəʊz | ə\'poz/', 'oppose', 3);
INSERT INTO `words` VALUES (35163, 'The principles of capitalism and socialism are diametrically opposed (= completely opposite ).', 'adj. 反对的； 截然不同的', '/ə\'pouzd | ə\'pozd/', 'opposed', 3);
INSERT INTO `words` VALUES (35164, 'I thought the medicine would make him sleep, but it had the opposite effect.', 'adj. 相对的,对面的; n. 相反的事物', '/\'ɔpəzit, -sit | \'ɒpəzɪt; -sɪt | ˈɑpəzɪt; ˈɑpəsɪt/', 'opposite', 3);
INSERT INTO `words` VALUES (35165, NULL, 'adv. 相反地, 相对地', '/\'ɔpəzitli/', 'oppositely', 3);
INSERT INTO `words` VALUES (35166, 'He is confident in his ability to overcome all opposition with his personal charm.', 'n. 反对,相反', '/,ɔpə\'ziʃən | ɒpə\'zɪʃ(ə)n | \'ɑpə\'zɪʃən/', 'opposition', 3);
INSERT INTO `words` VALUES (35167, 'the oppressive heat of the afternoon', 'adj. 压迫的， 压制的； 令人焦虑的', '/ə\'presɪv | ə\'prɛsɪv/', 'oppressive', 3);
INSERT INTO `words` VALUES (35168, 'the optic nerve', 'adj. 眼的；视觉的；光学上的; n. 光学仪器', '/\'ɑːptɪk | \'ɑptɪk/', 'optic', 3);
INSERT INTO `words` VALUES (35169, 'microscopes and other optical instruments', 'adj. 视觉的, 光学的', '/\'ɔptikəl | \'ɒptɪk(ə)l | \'ɑptɪkl/', 'optical', 3);
INSERT INTO `words` VALUES (35170, 'If you find yourself waiting to be great, yearning for the optimal time when you can “afford” to do more, then you are saying at some level, if you can’t help everyone, you help no one.', 'adj. 最理想的', '/\'ɔptiməl | \'ɒptɪm(ə)l | \'ɑptəml/', 'optimal', 3);
INSERT INTO `words` VALUES (35171, 'Andrew took a more optimistic view.', 'adj. 乐观的', '/ˌɑːptɪ\'mɪstɪk | ,ɑptɪ\'mɪstɪk/', 'optimistic', 3);
INSERT INTO `words` VALUES (35172, 'These have focused on simplifying the development, automation, and optimization of applications.', 'n. 最佳化, 最优化', '/,ɔptimai\'zeiʃən, -mi\'z- | ,ɒptɪmaɪ\'zeɪʃən | ,ɑptəmɪ\'zeʃən/', 'optimization', 3);
INSERT INTO `words` VALUES (35173, 'They need to optimize the use of available resources.', 'vt. 使最优化； 充分利用', '/\'ɑːptɪmaɪz | \'ɑptɪmaɪz/', 'optimize', 3);
INSERT INTO `words` VALUES (35174, 'If we treat good diet as a cornerstone of optimum nutrition and do regular exercise, we will have much bigger chance to do and enjoy something else.', 'n&a. 最适宜(的)', '/\'ɔptiməm | \'ɒptɪməm | \'ɑptəməm/', 'optimum', 3);
INSERT INTO `words` VALUES (35175, 'There are a number of options available.', 'n. 选项, 选择权', '/\'ɔpʃən | \'ɒpʃ(ə)n | \'ɑpʃən/', 'option', 3);
INSERT INTO `words` VALUES (35176, 'three optional courses', 'adj. 可以任选的， 非强制的', '/\'ɑːpʃənl | \'ɑpʃənl/', 'optional', 3);
INSERT INTO `words` VALUES (35177, 'One evaluation has shown that 70% of the people who received the new glasses corrected their own vision at least as well, if not better, than a trained optometrist.', 'n. 验光师, 视力测定者', '/ɔp\'tɔmitrist | ɒp\'tɒmɪtrɪst | ɑp\'tɑmətrɪst/', 'optometrist', 3);
INSERT INTO `words` VALUES (35178, 'oral history', 'adj. 口头的', '/\'ɔ:rəl, \'ɔ- | \'ɔːr(ə)l | \'ɔrəl/', 'oral', 3);
INSERT INTO `words` VALUES (35179, 'orange juice', 'n. 橘子', '/\'ɔrindʒ, \'ɔ:- | \'ɒrɪn(d)ʒ | \'ɔrɪndʒ/', 'orange', 3);
INSERT INTO `words` VALUES (35180, 'Its peaks are the symphony and the oratorio.', 'n. 清唱剧， 宗教剧', '/ˌɔːrə\'tɔːriou | ,ɔrə\'tɔrɪo/', 'oratorio', 3);
INSERT INTO `words` VALUES (35181, 'Mars and Earth have orbits which change with time.', 'n. 轨道; v. (绕…)作轨道运行', '/\'ɔ:bit | \'ɔːbɪt | \'ɔrbɪt/', 'orbit', 3);
INSERT INTO `words` VALUES (35182, 'the Earth’s orbital path', 'adj. 轨道的', '/\'ɔ:bitəl | \'ɔːbɪt(ə)l | \'ɔrbɪtl/', 'orbital', 3);
INSERT INTO `words` VALUES (35183, 'He directed an orchestra.', 'n. 管弦乐队', '/\'ɔ:kistrə, -kes- | \'ɔːkɪstrə | \'ɔrkɪstrə/', 'orchestra', 3);
INSERT INTO `words` VALUES (35184, 'orchestral music', 'adj. 管弦乐的,管弦乐队的', '/ɔ:\'kestrəl | ɔː\'kestr(ə)l | ɔr\'kɛstrəl/', 'orchestral', 3);
INSERT INTO `words` VALUES (35185, 'Orchids and orchid bees are a classic example of this relationship.', 'n. 兰花', '/\'ɔ:kid | \'ɔːkɪd | \'ɔrkɪd/', 'orchid', 3);
INSERT INTO `words` VALUES (35186, 'He was beginning to wonder if he would survive the ordeal.', 'n. 折磨； 严峻考验', '/ɔːr\'diːl | ɔr\'dil/', 'ordeal', 3);
INSERT INTO `words` VALUES (35187, 'She needs to organize her ideas in a more orderly way.', 'adj. 整齐的，有秩序的', '/\'ɔ:dəli | \'ɔːd(ə)lɪ | \'ɔrdɚli/', 'orderly', 3);
INSERT INTO `words` VALUES (35188, 'Net of all the other variables included in the ordinal multiple regression equations, education is not significantly correlated with the frequency of binge drinking and getting drunk.', 'adj. 序数的；顺序的; n. 序数词', '/\'ɔːrdənl | \'ɔrdənl/', 'ordinal', 3);
INSERT INTO `words` VALUES (35189, 'a city ordinance that says parks must be closed at 11 p.m.', 'n. 法令，条例', '/\'ɔ:dinəns | \'ɔːdɪnəns | \'ɔrdnəns/', 'ordinance', 3);
INSERT INTO `words` VALUES (35190, 'Ordinarily, he didn’t like to go to the movies.', 'adv. 平常地；普通地', '/,ɔ:di\'nεərəli, \'ɔ:dinərəli | \'ɔːd(ə),n(ə)rɪlɪ; ,ɔːdɪ\'nerɪlɪ | ,ɔrdn\'ɛrəli/', 'ordinarily', 3);
INSERT INTO `words` VALUES (35191, 'It’s just an ordinary camera.', 'adj. 平常的,普通的', '/\'ɔ:dinəri, -neri- | \'ɔːdɪn(ə)rɪ; -d(ə)n- | \'ɔrdnɛri/', 'ordinary', 3);
INSERT INTO `words` VALUES (35192, 'Use a minimum of ordinate and abscissa values so they do not run together.', 'n. 纵坐标', '/\'ɔːrdɪnət | \'ɔrdɪnət/', 'ordinate', 3);
INSERT INTO `words` VALUES (35193, '...a team clearing an area littered with unexploded ordnance.', 'n. 军火', '/\'ɔ:dnəns | \'ɔːdnəns | \'ɔrdnəns/', 'ordnance', 3);
INSERT INTO `words` VALUES (35194, 'iron ore', 'n. 矿石', '/ɔ: | ɔː | ɔr/', 'ore', 3);
INSERT INTO `words` VALUES (35195, 'Her family was back in Oregon.', 'n. 俄勒冈州(美国州名)', '/\'ɔriɡən; -ɡɔn/', 'Oregon', 3);
INSERT INTO `words` VALUES (35196, 'the decision-making organs', 'n. 器官,机构', '/\'ɔ:ɡən | \'ɔːg(ə)n | \'ɔrɡən/', 'organ', 3);
INSERT INTO `words` VALUES (35197, 'Organic farming is better for the environment.', 'adj. 有机(体)的,有机物的', '/ɔ:\'ɡænik | ɔː\'gænɪk | ɔr\'gænɪk/', 'organic', 3);
INSERT INTO `words` VALUES (35198, NULL, 'adv. 器官上地, 有机地', '/ɔ:\'ɡænikli/', 'organically', 3);
INSERT INTO `words` VALUES (35199, 'All living organisms have to adapt to changes in environmental conditions.', 'n. 生物， 有机物； 有机体', '/\'ɔːrgənɪzəm | \'ɔrɡənɪzəm/', 'organism', 3);
INSERT INTO `words` VALUES (35200, 'The public expect high standards from any large organization.', 'n. 组织,机构,团体', '/,ɔ:ɡənai\'zeiʃən, -ni\'z- | ˌɔːɡənaɪ\'zeɪʃn | ,ɔrɡənə\'zeʃən/', 'organization', 3);
INSERT INTO `words` VALUES (35201, 'Evelyn\'s excellent organizational skills were soon spotted by her employers.', 'adj. 组织的', '/,ɔ:ɡənai\'zeiʃənəl, -ni\'z- | ˌɔːɡənaɪˈzeɪʃənl | ˌɔːrɡənəˈzeɪʃənl/', 'organizational', 3);
INSERT INTO `words` VALUES (35202, 'The course was organized by a training company.', 'v. 组织,安排', '/\'ɔ:ɡənaiz | ˈɔ:gənaɪz | ɔrɡənˌaɪz/', 'organize', 3);
INSERT INTO `words` VALUES (35203, 'You will need the time to orient yourself to your new way of eating.', 'v. 使适应,使朝向 n东方', '/\'ɔ:riənt, \'əu-, \'ɔ:rient | \'ɔːrɪənt; \'ɒr- | \'orɪənt/', 'orient', 3);
INSERT INTO `words` VALUES (35204, 'The party has a broadly socialist orientation.', 'n. 方向，目标', '/,ɔ:rien\'teiʃən, əu- | ,ɔːrɪən\'teɪʃ(ə)n; ,ɒr- | orɪɛn\'teʃən/', 'orientation', 3);
INSERT INTO `words` VALUES (35205, 'The tradition has its origins in the Middle Ages.', 'n. 起源,来源', '/\'ɔridʒin, \'ɔ:- | \'ɒrɪdʒɪn | \'ɔrɪdʒɪn/', 'origin', 3);
INSERT INTO `words` VALUES (35206, 'The land was returned to its original owner.', 'adj. 原始的,最初的', '/ə\'ridʒənəl | ə\'rɪdʒɪn(ə)l; ɒ- | ə\'rɪdʒənl/', 'original', 3);
INSERT INTO `words` VALUES (35207, 'Her earlier work shows a lot of originality.', 'n. 独创性', '/ə,ridʒə\'næləti | ə,rɪdʒɪ\'nælɪtɪ | ə\'rɪdʒə\'næləti/', 'originality', 3);
INSERT INTO `words` VALUES (35208, 'The family originally came from France.', 'adv. 最初,原先', '/ə\'ridʒənəli | ə\'rɪdʒɪn(ə)lɪ | ə\'rɪdʒənəli/', 'originally', 3);
INSERT INTO `words` VALUES (35209, 'How did the plan originate?', 'v. 起源于,创始', '/ə\'ridʒəneit | ə\'rɪdʒɪneɪt; ɒ- | əˈrɪdʒəˌnet/', 'originate', 3);
INSERT INTO `words` VALUES (35210, '...the originator of the theory of relativity.', 'n. 创始人, 发起人', '/ə\'ridʒəneitə, -nə- | ə\'rɪdʒɪneɪtə(r) | ə\'rɪdʒənətɚ/', 'originator', 3);
INSERT INTO `words` VALUES (35211, NULL, 'n. 奥尔良[法国]', '/ɔ:\'liənz/', 'orleans', 3);
INSERT INTO `words` VALUES (35212, 'a shelf covered with books and ornaments', 'n&vt. 装饰(品),美化', '/\'ɔ:nəmənt, \'ɔ:nəment | \'ɔːnəm(ə)nt | \'ɔrnəmənt/', 'ornament', 3);
INSERT INTO `words` VALUES (35213, '...an ornamental fountain.', 'adj. 装饰的 n装饰品', '/,ɔ:nə\'mentəl | ɔːnə\'ment(ə)l | ,ɔrnə\'mɛntl/', 'ornamental', 3);
