INSERT INTO `words` VALUES (35883, 'Pine trees predominate in this area of forest.', 'v. 占优势, 支配', '/pri\'dɔmineit | prɪ\'dɒmɪneɪt | prɪ\'dɑmə\'net/', 'predominate', 3);
