INSERT INTO `words` VALUES (35900, 'Similar tales were told by various preliterate peoples in Asia, Africa, and the Americas.', 'adj. 文字出现以前的， 没有文字的', '/ˌpriː\'lɪtərət | pri\'lɪtərɪt/', 'preliterate', 3);
