INSERT INTO `words` VALUES (35904, 'The documentary premiered at the Jerusalem Film Festival.', 'v. 初次公演; n. 初次的演出; adj. 杰出的', '/pri\'miə, prə\'mjer | \'premɪeə | prɪ\'mɪr/', 'premiere', 3);
