INSERT INTO `words` VALUES (36103, 'Here the rich and the poor live in close proximity (= very near to each other ) .', 'n. 接近, 亲近', '/prɒk\'sɪmɪtɪ | prɑk\'sɪməti/', 'proximity', 3);
