INSERT INTO `words` VALUES (36106, 'I don’t want to pry , but I need to ask you one or two questions.', 'v. 探查', '/prai | praɪ/', 'pry', 3);
INSERT INTO `words` VALUES (36107, 'In theory, psychoanalysis is the philosophy of the unconscious mind; in practice it is a means by which mental disorders can be cured.', 'n. 心理分析， 精神分析', '/ˌsaɪkouə\'næləsɪs | \'saɪkoə\'næləsɪs/', 'psychoanalysis', 3);
