INSERT INTO `words` VALUES (36111, '\"Simply being on antipsychotic medications could not have brought about such acceptance, \" she stressed. \"And this acceptance set me free psychologically.', 'adv. 精神上地, 心理上地', '/,psaikə\'lɔdʒikəli | saɪ\'kɒlədʒɪklɪ | saɪkə\'lɑdʒɪkli/', 'psychologically', 3);
INSERT INTO `words` VALUES (36112, 'a clinical psychologist', 'n. 心理学者', '/psai\'kɔlədʒist | saɪ\'kɒlədʒɪst | saɪ\'kɑlədʒɪst/', 'psychologist', 3);
INSERT INTO `words` VALUES (36113, 'I understood the psychology of this, but it still hurt.', 'n. 心理学', '/psai\'kɔlədʒi | saɪ\'kɒlədʒɪ | saɪ\'kɑlədʒi/', 'psychology', 3);
INSERT INTO `words` VALUES (36114, 'It was a fearful cry, but the fox, leaping away in fright, did not drop the ptarmigan.', 'n. 松鸡类', '/\'tɑ:miɡən | \'tɑːmɪg(ə)n | \'tɑrmɪɡən/', 'ptarmigan', 3);
