INSERT INTO `words` VALUES (36118, 'The case has generated enormous publicity in Brazil.', 'n. 公开', '/pʌb\'lisiti | pʌb\'lɪsɪtɪ | pʌb\'lɪsəti/', 'publicity', 3);
