INSERT INTO `words` VALUES (36329, 'Anti-government rebels attacked the town.', 'n. 反叛分子; v. 反叛；反对', '/\'rebəl, ri\'bel | \'reb(ə)l | rɪ\'bɛl/', 'rebel', 3);
INSERT INTO `words` VALUES (36330, 'an armed rebellion', 'n. 反叛，反抗', '/ri\'beljən | rɪ\'beljən | rɪ\'bɛljən/', 'rebellion', 3);
INSERT INTO `words` VALUES (36331, 'rebellious teenagers', 'adj. 反抗的，难控制的', '/ri\'beljəs | rɪ\'beljəs | rɪ\'bɛljəs/', 'rebellious', 3);
INSERT INTO `words` VALUES (36332, 'the cycle of birth, death and rebirth', 'n. 复活, 新生', '/,ri:\'bə:θ, \'ri:b- | riː\'bɜːθ | ,ri\'bɝθ/', 'rebirth', 3);
INSERT INTO `words` VALUES (36333, 'I caught the ball on the rebound.', 'n. /v回弹', '/,ri:\'baund | rɪ\'baʊnd/', 'rebound', 3);
INSERT INTO `words` VALUES (36334, 'The church was completely rebuilt in the last century.', 'v. 重建, 改造', '/,ri:\'bild, \'ri:,bild | riː\'bɪld | ,ri\'bɪld/', 'rebuild', 3);
INSERT INTO `words` VALUES (36335, 'You don’t happen to recall his name, do you?', 'v. 回忆,记起; n. 召回', '/ri\'kɔ:l, \'ri:kɔ:l | rɪ\'kɔːl | \'rikɔl/', 'recall', 3);
INSERT INTO `words` VALUES (36336, 'The flood waters finally began to recede in November.', 'v. 后退', '/rɪ\'siːd | rɪ\'sid/', 'recede', 3);
INSERT INTO `words` VALUES (36337, 'All the children will receive a small gift.', 'v. 接到,收到,接待', '/ri\'si:v | rɪ\'siːv | rɪ\'siv/', 'receive', 3);
INSERT INTO `words` VALUES (36338, 'Auto-tuning VHF receivers are now common in cars.', 'n. 接受者, 接收器, 收信机', '/ri\'si:və | rɪ\'siːvə | rɪ\'sivɚ/', 'receiver', 3);
INSERT INTO `words` VALUES (36339, 'Irving’s most recent book', 'adj. 近来的,新近的', '/\'ri:sənt | \'riːs(ə)nt | \'risnt/', 'recent', 3);
INSERT INTO `words` VALUES (36340, 'a trash receptacle', 'n. 容器', '/ri\'septəkl | rɪ\'septək(ə)l | rɪ\'sɛptəkl/', 'receptacle', 3);
INSERT INTO `words` VALUES (36341, 'It’s an ideal location for a wedding reception .', 'n. 招待会；接受', '/ri\'sepʃən | rɪ\'sepʃ(ə)n | rɪ\'sɛpʃən/', 'reception', 3);
INSERT INTO `words` VALUES (36342, 'You might find them in a more receptive mood tomorrow.', 'adj. 善于接受的,能容纳的', '/ri\'septiv | rɪ\'septɪv | rɪ\'sɛptɪv/', 'receptive', 3);
INSERT INTO `words` VALUES (36343, 'Group intelligence is correlated, Malone and his colleagues found, with the average social sensitivity — the openness, and receptiveness, to others — of a group\'s constituents.', 'n. 感受性,接受能力', '/ri\'septivnis/', 'receptiveness', 3);
INSERT INTO `words` VALUES (36344, '...the information receptors in our brain.', 'n. 接受器', '/ri\'septə | rɪ\'septə | rɪ\'sɛptɚ/', 'receptor', 3);
INSERT INTO `words` VALUES (36345, 'the deep recesses of the cave', 'n. (墙壁等的)凹进处; v. 使凹进,休假', '/ri\'ses, \'ri:ses | rɪ\'ses; \'riːses | \'risɛs/', 'recess', 3);
INSERT INTO `words` VALUES (36346, 'the economic recession of the early 1980s', 'n. 衰退， 衰退时期， 萧条时期； 撤回， 退回', '/rɪ\'seʃn | rɪ\'sɛʃən/', 'recession', 3);
INSERT INTO `words` VALUES (36347, 'In normal seedlings the deleterious recessive genes are not expressed.', 'adj. 隐性的', '/rɪ\'sesɪv | rɪ\'sɛsɪv/', 'recessive', 3);
INSERT INTO `words` VALUES (36348, 'I’m going to spend a week in the mountains to recharge my batteries.', 'v. 再充电,再进攻,恢复精力', '/ri:\'tʃɑ:dʒ, \'ri:tʃɑ:dʒ | riː\'tʃɑːdʒ/', 'recharge', 3);
INSERT INTO `words` VALUES (36349, 'Large-scale inflation is a recipe for disaster.', 'n. 处方', '/\'resɪpɪ | \'rɛsəpi/', 'recipe', 3);
INSERT INTO `words` VALUES (36350, '...the largest recipient of U.S. foreign aid.', 'n. 接受者，接收者', '/ri\'sipiənt | rɪ\'sɪpɪənt/', 'recipient', 3);
INSERT INTO `words` VALUES (36351, 'He spoke of the necessity for a reciprocal relationship that would be useful for all sides.', 'adj. 相互的；互惠的；相应的；', '/rɪ\'sɪprəkl/', 'reciprocal', 3);
INSERT INTO `words` VALUES (36352, NULL, 'v. 互换, 交换', '/ri\'siprəkeit | rɪ\'sɪprəkeɪt | rɪ\'sɪprəket/', 'reciprocate', 3);
INSERT INTO `words` VALUES (36353, 'They said they would press for reciprocity with Greece in the issuing of visas.', 'n. 互惠， 互助； 互惠主义', '/ˌresɪ\'prɑːsəti | ,rɛsɪ\'prɑsəti/', 'reciprocity', 3);
INSERT INTO `words` VALUES (36354, 'a piano recital', 'n. 朗诵, 背诵, 独奏会', '/ri\'saitəl | rɪ\'saɪt(ə)l | rɪ\'saɪtl/', 'recital', 3);
INSERT INTO `words` VALUES (36355, 'He was accused of causing death by reckless driving .', 'adj. 不计后果的,鲁莽的', '/\'reklis | \'reklɪs | \'rɛkləs/', 'reckless', 3);
INSERT INTO `words` VALUES (36356, 'The expression ‘full moon’ means the fourteenth day of the moon reckoned from its first appearance.', 'v. 计算,估计', '/\'rekən | \'rek(ə)n | \'rɛkən/', 'reckon', 3);
INSERT INTO `words` VALUES (36357, 'You may be entitled to reclaim some tax.', 'v. 要回,开垦,回收', '/ri\'kleim | rɪ\'kleɪm | rɪ\'klem/', 'reclaim', 3);
INSERT INTO `words` VALUES (36358, '...centuries of seawall construction and the reclamation of dry land from the marshes.', 'n. 开垦,改造', '/,reklə\'meiʃən | ,reklə\'meɪʃən | ,rɛklə\'meʃən/', 'reclamation', 3);
INSERT INTO `words` VALUES (36359, 'She proceeded to recline on a chaise longue.', 'v. 向后倚靠， 斜倚', '/rɪ\'klaɪn/', 'recline', 3);
INSERT INTO `words` VALUES (36360, 'He stared at her, but there was no sign of recognition .', 'n. 识别,确认', '/,rekəg\'niʃən | rekəg\'nɪʃ(ə)n | ,rɛkəɡ\'nɪʃən/', 'recognition', 3);
INSERT INTO `words` VALUES (36361, 'The vault was opened and the body found to be well preserved, his features easily recognizable.', 'adj. 可辨认的,可认识的', '/\'rekəɡnaizəbl, ,rekəɡ\'nai- | ,rɛkəɡ\'naɪzəbl/', 'recognizable', 3);
INSERT INTO `words` VALUES (36362, 'I didn’t recognize you in your uniform.', 'v. 认出,确认,意识到', '/\'rekəɡnaiz | \'rekəɡnaɪz | ˈrɛkəɡˌnaɪz/', 'recognize', 3);
INSERT INTO `words` VALUES (36363, '...his small body jerking in recoil from the volume of his shouting.', 'n. 畏缩, 弹回 vi退却, 畏缩', '/ri\'kɔil, \'ri:kɔil | rɪ\'kɒɪl | \'rikɔɪl/', 'recoil', 3);
INSERT INTO `words` VALUES (36364, 'My earliest recollections are of my mother bending over my cot.', 'n. 记忆力； 回忆， 记忆； 回想起来的事', '/ˌrekə\'lekʃn | ,rɛkə\'lɛkʃən/', 'recollection', 3);
INSERT INTO `words` VALUES (36365, 'Doctors strongly recommend that fathers should be present at their baby’s birth.', 'v. 推荐,劝告', '/,rekə\'mend | rekə\'mend | \'rɛkə\'mɛnd/', 'recommend', 3);
INSERT INTO `words` VALUES (36366, 'Try to get letters of recommendation from bosses and colleagues.', 'n. 推荐, 介绍(信)', '/,rekəmen\'deiʃən | ,rekəmen\'deɪʃ(ə)n | ,rɛkəmɛn\'deʃən/', 'recommendation', 3);
INSERT INTO `words` VALUES (36367, 'Jonah and his youngest son were, on the surface at least, reconciled.', 'vt. 使协调； 使和解； 使顺从', '/\'rekənsaɪl | \'rɛkənsaɪl/', 'reconcile', 3);
INSERT INTO `words` VALUES (36368, 'The committees will be reconstituted after the election.', 'v. 重新组成, 重新设立', '/,ri:\'kɔnstitju:t | riː\'kɒnstɪtjuːt | ,ri\'kɑnstətut/', 'reconstitute', 3);
INSERT INTO `words` VALUES (36369, 'The task ahead is to reconstruct the building.', 'v. 重建, 改造', '/,ri:kən\'strʌkt | riːkən\'strʌkt | ,rikən\'strʌkt/', 'reconstruct', 3);
INSERT INTO `words` VALUES (36370, '...America\'s part in the postwar reconstruction of Germany.', 'n. 重建, 改造', '/,ri:kən\'strʌkʃən | riːkən\'strʌkʃn | ,rikən\'strʌkʃən/', 'reconstruction', 3);
INSERT INTO `words` VALUES (36371, 'Data recorders also pinpoint mechanical faults rapidly, reducing repair times.', 'n. 记录员, 记录器', '/ri\'kɔ:də | rɪ\'kɔːdə | rɪ\'kɔrdɚ/', 'recorder', 3);
INSERT INTO `words` VALUES (36372, 'He then recounted the story of the interview for his first job.', 'v. 叙述', '/ri\'kaunt | rɪ\'kaʊnt/', 'recount', 3);
INSERT INTO `words` VALUES (36373, 'The movie will have to be a huge hit to recoup its cost.', 'vt. 收回， 弥补', '/rɪ\'kuːp | ri\'ku:p/', 'recoup', 3);
INSERT INTO `words` VALUES (36374, 'After a few days of fever, she began to recover.', 'v. 恢复,复原,重获', '/ri\'kʌvə | rɪ\'kʌvə | rɪ\'kʌvɚ/', 'recover', 3);
INSERT INTO `words` VALUES (36375, 'Hopes of economic recovery are fading.', 'n. 恢复, 痊愈', '/ri\'kʌvəri | rɪ\'kʌv(ə)rɪ | rɪ\'kʌvəri/', 'recovery', 3);
INSERT INTO `words` VALUES (36376, 'You can never recreate the feeling of winning for the first time.', 'v. (使)得到休养, (使)得到娱乐', '/\'rekrieit, -kri:- | riːkrɪ\'eɪt | ,rikrɪ\'et/', 'recreate', 3);
INSERT INTO `words` VALUES (36377, 'His only recreations are drinking beer and watching football.', 'n. 消遣, 娱乐', '/,rekri\'eiʃən, -kri:- | ,rekrɪ\'eɪʃ(ə)n | ,rɛkrɪ\'eʃən/', 'recreation', 3);
INSERT INTO `words` VALUES (36378, '...parks and other recreational facilities.', 'adj. 娱乐的, 消遣的', '/,rekri\'eiʃənəl, -kri:- | rekrɪ\'eɪʃənl | ,rɛkri\'eʃənəl/', 'recreational', 3);
INSERT INTO `words` VALUES (36379, 'We’re having difficulty recruiting enough qualified staff.', 'v. 招募,吸收; n. 新成员, 新兵', '/ri\'kru:t | rɪ\'kruːt | rɪ\'krut/', 'recruit', 3);
INSERT INTO `words` VALUES (36380, NULL, 'n. 征募新兵, 补充', '/ri\'kru:tmənt | rɪ\'kruːtm(ə)nt | rɪ\'krʊtmənt/', 'recruitment', 3);
INSERT INTO `words` VALUES (36381, 'After the die, it takes some time for polymer molecules to get reoriented to a random manner again, and to recrystallize.', 'v. ( 使) 再结晶', '/ri:\'kristəlaiz/', 'recrystallize', 3);
INSERT INTO `words` VALUES (36382, 'Suppose the width of a rectangle is x metres.', 'n. 长方形, 矩形', '/\'rek,tæŋɡl | \'rektæŋg(ə)l | \'rɛktæŋɡl/', 'rectangle', 3);
INSERT INTO `words` VALUES (36383, '...a rectangular table.', 'adj. 长方形的，矩形的', '/\'rek\'tæŋɡjulə | rek\'tæŋgjʊlə | rɛk\'tæŋgjəlɚ/', 'rectangular', 3);
INSERT INTO `words` VALUES (36384, 'I did my best to rectify the situation, but the damage was already done.', 'v. 矫正, 调整', '/\'rektifai | \'rektɪfaɪ | \'rɛktɪfaɪ/', 'rectify', 3);
INSERT INTO `words` VALUES (36385, 'There is a danger that the disease may recur.', 'v. 再发生，重现', '/ri\'kə: | rɪ\'kɜː | rɪ\'kɝ/', 'recur', 3);
INSERT INTO `words` VALUES (36386, 'If you have a recurrence, talk to your doctor about getting a new biopsy before settling on treatment.', 'n. 复发, 重现', '/ri\'kʌrəns, -\'kə:- | rɪ\'kʌrəns | rɪ\'kɝəns/', 'recurrence', 3);
INSERT INTO `words` VALUES (36387, 'recurrent minor illnesses', 'adj. 再发生的, 周期性的', '/ri\'kʌrənt, -\'kə:- | rɪ\'kʌr(ə)nt | rɪ\'kɝənt/', 'recurrent', 3);
INSERT INTO `words` VALUES (36388, NULL, 'adj. 往复的， 反复的， 再次发生的', '/rɪ\'kɜːrɪŋ | rɪ\'kɝɪŋ/', 'recurring', 3);
INSERT INTO `words` VALUES (36389, 'We take all our bottles to be recycled.', 'v. 使再循环, 反复应用 n再循环, 再生, 重复利用', '/,ri:\'saikl | riː\'saɪk(ə)l | ,ri\'saɪkl/', 'recycle', 3);
INSERT INTO `words` VALUES (36390, 'I like the way the artist uses red in this painting.', 'n&a. 红色(的),', '/red | rɛd/', 'red', 3);
INSERT INTO `words` VALUES (36391, 'The production of flowers and fruits on the older branches or trunks of woody plants, such as the redbud, and many mostly tropical plants, including cacao.', 'n. 紫荆属植物', '/\'redbʌd | \'rɛd,bʌd/', 'redbud', 3);
INSERT INTO `words` VALUES (36392, 'reddish-brown lipstick', 'adj. 微红的', '/\'rediʃ | \'redɪʃ | \'rɛdɪʃ/', 'reddish', 3);
INSERT INTO `words` VALUES (36393, 'Olivier’s performance redeemed an otherwise second-rate play.', 'vt. 赎回； 偿清， 付清； 兑换； 弥补， 补偿； 履行， 遵守', '/rɪ\'diːm | rɪ\'dim/', 'redeem', 3);
INSERT INTO `words` VALUES (36394, 'Feminists have redefined the role of women.', 'v. 重新定义', '/,ri:di\'fain | riːdɪ\'faɪn | ,ridɪ\'faɪn/', 'redefine', 3);
INSERT INTO `words` VALUES (36395, 'The hotel has recently been redesigned and redecorated.', 'v&n. 重新设计', '/,ri:di\'zain | riːdɪ\'zaɪn | ,ridɪ\'zaɪn/', 'redesign', 3);
INSERT INTO `words` VALUES (36396, '...a one-time rebel who had rediscovered his faith.', 'v. 重新发现', '/,ri:di\'skʌvə | riːdɪ\'skʌvə | ,ridɪ\'skʌvɚ/', 'rediscover', 3);
INSERT INTO `words` VALUES (36397, 'The governor announced a new plan to reduce crime.', 'v. 减少,缩小', '/ri\'dju:s, -\'du:s | rɪ\'djuːs | rɪ\'dʊs/', 'reduce', 3);
INSERT INTO `words` VALUES (36398, 'strategies for noise reduction', 'n. 减少,缩影', '/rɪ\'dʌkʃ(ə)n | rɪ\'dʌkʃən/', 'reduction', 3);
INSERT INTO `words` VALUES (36399, 'the removal of redundant information', 'adj. 多余的； 累赘的', '/rɪ\'dʌndənt/', 'redundant', 3);
INSERT INTO `words` VALUES (36400, 'Hunting of song and mistle thrushes and their cousin the redwing is not illegal, but the methods used are, despite attempts by legislators to introduce exceptions.', 'n. [动](欧洲产的)红翼鸫', '/\'redwiŋ | \'redwɪŋ | \'rɛdwɪŋ/', 'redwing', 3);
INSERT INTO `words` VALUES (36401, 'Members of the group stand atop the stump of a giant redwood tree.', 'n. [植]红杉', '/\'redwud | \'redwʊd | \'rɛdwʊd/', 'redwood', 3);
INSERT INTO `words` VALUES (36402, 'Reeds grew in clumps all along the river bank.', 'n. 芦苇', '/ri:d | riːd | rid/', 'reed', 3);
INSERT INTO `words` VALUES (36403, 'a proposal to protect several miles of thousand-year-old coral reef', 'n. 礁,暗礁', '/ri:f | riːf | rif/', 'reef', 3);
INSERT INTO `words` VALUES (36404, 'a cotton reel', 'n. 卷轴 vt卷，绕', '/ri:l, riəl | riːl | ril/', 'reel', 3);
INSERT INTO `words` VALUES (36405, 'There are some objections to the proposal to reelect the chairman.', 'v. 重选, 改选', '/,ri:i\'lekt | ,riə\'lɛkt/', 'reelect', 3);
INSERT INTO `words` VALUES (36406, 'After they finished their commission business, Chernomyrdin came to see me to brief me on events in Russia and Yeltsin’s prospects for reelection.', 'n. 再选, 改选', '/,ri:i\'lekʃən | ,riə\'lɛkʃən/', 'reelection', 3);
INSERT INTO `words` VALUES (36407, 'After waiting a while, and with a fresh canary, the miners could safely reenter the mine.', 'n. 重进入, 再加入; v. 重返', '/,riː\'entə | ri\'ɛntɚ/', 'reenter', 3);
INSERT INTO `words` VALUES (36408, NULL, 'v. 复试', '/,ri:iɡ\'zæmin, -eɡ- | ,riːɪɡ\'zæmɪn | ,riɛɡ\'zæmɪn/', 'reexamine', 3);
INSERT INTO `words` VALUES (36409, 'In his speech, he referred to a recent trip to Canada.', 'v. 提到， 谈及； 查阅， 参考', '/rɪ\'fɜːr | rɪ\'fɝ/', 'refer', 3);
INSERT INTO `words` VALUES (36410, NULL, 'n. 裁判员 v裁判, 仲裁', '/,refə\'ri: | refə\'riː | ,rɛfə\'ri/', 'referee', 3);
INSERT INTO `words` VALUES (36411, 'He made no reference to any agreement.', 'n. 提及,涉及,参考', '/\'refərəns | \'ref(ə)r(ə)ns | \'rɛfrəns/', 'reference', 3);
INSERT INTO `words` VALUES (36412, NULL, 'n. 指示物', '/\'refərənt | \'ref(ə)r(ə)nt | \'rɛfərənt/', 'referent', 3);
INSERT INTO `words` VALUES (36413, 'The waitress refilled our coffee cups.', 'v. 再装满,再充填', '/,ri:\'fil | riː\'fɪl | \'rifɪl/', 'refill', 3);
INSERT INTO `words` VALUES (36414, 'Oil is refined to remove naturally occurring impurities.', 'v. 精炼, 精制', '/ri\'fain | rɪ\'faɪn/', 'refine', 3);
INSERT INTO `words` VALUES (36415, 'Her mother is a woman with great refinement.', 'n. 精致, 文雅', '/ri\'fainmənt | rɪ\'faɪnm(ə)nt | rɪ\'faɪnmənt/', 'refinement', 3);
INSERT INTO `words` VALUES (36416, 'The refiner defined a definite confine with her fine finger.', 'n. 精炼者, 精炼机', '/ri\'fainə | rɪ\'faɪnɚ/', 'refiner', 3);
INSERT INTO `words` VALUES (36417, '...an oil refinery.', 'n. 精炼厂', '/ri\'fainəri | rɪ\'faɪn(ə)rɪ | rɪ\'faɪnəri/', 'refinery', 3);
INSERT INTO `words` VALUES (36418, 'The drop in consumer spending reflects concern about the economy.', 'v. 反映,反射', '/rɪ\'flekt | rɪ\'flɛkt/', 'reflect', 3);
INSERT INTO `words` VALUES (36419, 'A moment’s reflection will show the stupidity of this argument.', 'n. 反映,考虑', '/re\'flekʃən | rɪ\'flekʃ(ə)n | rɪ\'flɛkʃən/', 'reflection', 3);
INSERT INTO `words` VALUES (36420, 'Stick reflective tape on your school bag.', 'adj. 反射的,反映的,沉思的', '/ri\'flektiv | rɪ\'flektɪv | rɪ\'flɛktɪv/', 'reflective', 3);
INSERT INTO `words` VALUES (36421, 'With these layers downloaded, you can combine them with the base reflectivity image to produce a more easily readable image map.', 'n. 反射率', '/,ri:flek\'tiviti/', 'reflectivity', 3);
INSERT INTO `words` VALUES (36422, 'plans to radically reform the tax system', 'vt&n. 改革, 革新', '/ri\'fɔ:m | rɪ\'fɔːm | rɪ\'fɔrm/', 'reform', 3);
INSERT INTO `words` VALUES (36423, 'a great social reformer', 'n. 改革家, 改革运动者', '/ri\'fɔ:mə | rɪ\'fɔːmə | rɪ\'fɔrmɚ/', 'reformer', 3);
INSERT INTO `words` VALUES (36424, 'The sonobuoy permits recording a refraction profile with only one ship.', 'n. 折射', '/rɪ\'frækʃn | rɪ\'frækʃən/', 'refraction', 3);
INSERT INTO `words` VALUES (36425, '...refractory priests who refused to side with the king.', 'adj. 难控制的,耐火的', '/ri\'fræktəri | rɪ\'frækt(ə)rɪ | rɪ\'fræktəri/', 'refractory', 3);
INSERT INTO `words` VALUES (36426, 'Mrs. Hardie refrained from making any comment.', 'v. 抑制； 戒除; n. 反复句，副歌', '/rɪ\'freɪn | rɪ\'fren/', 'refrain', 3);
INSERT INTO `words` VALUES (36427, 'In this process the water can refreeze, creating additional cracks in the more vulnerable warm ice, according to the study.', 'vt. 再结冰, 重新冻结', '/ri:\'fri:z/', 'refreeze', 3);
INSERT INTO `words` VALUES (36428, 'A shower will refresh you.', 'v. (使)精神振作,(使)恢复活力', '/ri\'freʃ, ri:- | rɪ\'freʃ | ri\'frɛʃ/', 'refresh', 3);
INSERT INTO `words` VALUES (36429, 'It made a refreshing change to talk to someone new.', 'adj. 使人耳目一新的； 提神的， 使人精神振作的', '/rɪ\'freʃɪŋ | ri\'frɛʃɪŋ/', 'refreshing', 3);
INSERT INTO `words` VALUES (36430, 'Refreshments will be served after the meeting.', 'n. 点心, 精力恢复', '/ri\'freʃmənt, ri:- | rɪ\'freʃm(ə)nt | ri\'frɛʃmənt/', 'refreshment', 3);
INSERT INTO `words` VALUES (36431, 'Refrigerate the mixture overnight.', 'v. 使冷冻, 使冷藏', '/ri\'fridʒəreit, ri:- | rɪ\'frɪdʒəreɪt | rɪ\'frɪdʒəret/', 'refrigerate', 3);
INSERT INTO `words` VALUES (36432, 'Mold can grow even under refrigeration, and aging cheese is a good example of that.', 'n. 冷藏, 致冷', '/ri,fridʒə\'reiʃən, ri:- | rɪ,frɪdʒə\'reɪʃən | rifrɪdʒə\'reʃən/', 'refrigeration', 3);
INSERT INTO `words` VALUES (36433, 'My refrigerator suddenly started kicking up yesterday.', 'n. 电冰箱', '/ri\'fridʒəreitə, ri:- | rɪ\'frɪdʒəreɪtə | rɪ\'frɪdʒəretɚ/', 'refrigerator', 3);
INSERT INTO `words` VALUES (36434, 'a wildlife refuge', 'n. 庇护, 避难所', '/\'refju:dʒ | \'refjuːdʒ | \'rɛfjʊdʒ/', 'refuge', 3);
INSERT INTO `words` VALUES (36435, 'They refused to give me a refund .', 'n. 偿还额； 退款; vt. 退还， 偿付', '/ˈriːfʌnd | ˈrifʌnd/', 'refund', 3);
INSERT INTO `words` VALUES (36436, 'We have spent money on refurbishing the offices.', 'v. 再磨光, 刷新', '/,ri:\'fə:biʃ | riː\'fɜːbɪʃ | ,ri\'fɝbɪʃ/', 'refurbish', 3);
INSERT INTO `words` VALUES (36437, 'She asked him to leave, but he refused.', 'v. 拒绝', '/ri\'fju:z, ri:- | rɪ\'fjuːz | ri\'fjʊz/', 'refuse', 3);
INSERT INTO `words` VALUES (36438, 'It was the kind of rumour that it is impossible to refute.', 'v. 驳斥，驳倒', '/ri\'fju:t, ri:- | rɪ\'fjuːt | ri\'fjʊt/', 'refute', 3);
INSERT INTO `words` VALUES (36439, 'The family never quite regained its former influence.', 'v. 收回；恢复', '/ri\'ɡein, ri:- | rɪ\'geɪn | rɪ\'ɡen/', 'regain', 3);
INSERT INTO `words` VALUES (36440, 'Burt had high regard for his old law professor, Dr. Finch (= he respected him a lot ) .', 'n. 尊敬; v. 看待,当作', '/ri\'ɡɑ:d, ri:- | rɪ\'gɑːd | rɪ\'ɡɑrd/', 'regard', 3);
INSERT INTO `words` VALUES (36441, 'The fields give high and stable yields regardless of climatic circumstances.', 'adj. 不管,不顾', '/rɪ\'gɑːdlɪs | rɪ\'ɡɑrdləs/', 'regardless', 3);
INSERT INTO `words` VALUES (36442, 'Small nodules form as the liver cells regenerate.', 'v. 使新生, 重建 a新生的, 更新的', '/ri\'dʒenəreit, ri:- | rɪ\'dʒenəreɪt | rɪ\'dʒɛnəret/', 'regenerate', 3);
INSERT INTO `words` VALUES (36443, 'But they can definitely determine how they plan to grow as more people move in, and also how they want to rehabilitate areas that need regeneration.', 'n. 再生, 重建', '/ri,dʒenə\'reiʃən, ri:- | rɪdʒenə\'reɪʃn | ridʒɛnə\'reʃən/', 'regeneration', 3);
INSERT INTO `words` VALUES (36444, 'The regime got rid of most of its opponents.', 'n. 政权制度,政权', '/rei\'ʒi:m, ri-, ri\'dʒi:m | reɪ\'ʒiːm | re\'ʒim/', 'regime', 3);
INSERT INTO `words` VALUES (36445, 'They deserted from their regiment.', 'n. (军队的)团；大量 vt严格地管制', '/\'redʒimənt | \'redʒɪm(ə)nt | \'rɛdʒɪmənt/', 'regiment', 3);
INSERT INTO `words` VALUES (36446, 'Democracy is incompatible with excessive, bureaucratic regimentation of social life.', 'n. 管辖,严格控制', '/,redʒimen\'teiʃən/', 'regimentation', 3);
INSERT INTO `words` VALUES (36447, 'efforts to bring peace to the region', 'n. 层； 地区， 区域； 范围', '/\'riːdʒən | \'ridʒən/', 'region', 3);
INSERT INTO `words` VALUES (36448, 'local and regional government', 'adj. 整个地区的,地域性地', '/\'ri:dʒənəl | \'riːdʒənl | \'ridʒənl/', 'regional', 3);
INSERT INTO `words` VALUES (36449, NULL, 'n. 地方主义者, 地方主义作家', '/\'ri:dʒənəlist/', 'regionalist', 3);
INSERT INTO `words` VALUES (36450, NULL, 'n. 分成地区, 按地区安排', '/,ri:dʒənəlai\'zeiʃən/', 'regionalization', 3);
INSERT INTO `words` VALUES (36451, 'Have you signed the hotel register ?', 'n& vt. 登记(表)，注册', '/\'redʒistə | \'redʒɪstə | \'rɛdʒɪstɚ/', 'register', 3);
INSERT INTO `words` VALUES (36452, 'Millions of megawatts (terawatts) of electric power will be generated on the Moon by solar arrays that have been constructed from lunar regolith materials.', 'n. [地质]风化层, 土被', '/\'regəlɪθ | \'rɛgə,lɪθ/', 'regolith', 3);
INSERT INTO `words` VALUES (36453, 'Larry said he had no regrets about retiring.', 'n. /v遗憾, 抱歉,后悔', '/ri\'ɡret | rɪ\'gret | rɪ\'ɡrɛt/', 'regret', 3);
INSERT INTO `words` VALUES (36454, 'This was a very regrettable error.', 'adj. 可惜的, 遗憾的', '/ri\'ɡretəbl | rɪ\'gretəb(ə)l | rɪ\'ɡrɛtəbl/', 'regrettable', 3);
INSERT INTO `words` VALUES (36455, 'The company holds regular meetings with employees.', 'adj. 规则的,定期的', '/\'reɡjulə | \'regjʊlə | \'rɛgjəlɚ/', 'regular', 3);
INSERT INTO `words` VALUES (36456, 'Climate change is disrupting the regularity of the seasons.', 'n. 规律性,规则性', '/,reɡju\'lærəti | reɡjʊ\'lærətɪ | ˌrɛɡjəˈlærətɪ/', 'regularity', 3);
INSERT INTO `words` VALUES (36457, 'Cohabiting couples would regularize their unions, they said.', 'v. 使有规则, 使有秩序', '/\'reɡjuləraiz | \'regjʊləraɪz | \'rɛɡjələraɪz/', 'regularize', 3);
INSERT INTO `words` VALUES (36458, 'strict rules regulating the use of chemicals in food', 'v. 管理,控制,调整', '/\'reɡjuleit | \'regjʊleɪt | \'rɛɡjulet/', 'regulate', 3);
INSERT INTO `words` VALUES (36459, 'There seem to be so many rules and regulations these days.', 'n. 规则', '/,reɡju\'leiʃən | regjʊ\'leɪʃ(ə)n | ˌrɛɡjəˈleʃən/', 'regulation', 3);
INSERT INTO `words` VALUES (36460, 'a heat regulator', 'n. 调整者,调整器', '/\'regjʊleɪtə | \'rɛɡjuletɚ/', 'regulator', 3);
INSERT INTO `words` VALUES (36461, 'Partially, that has to do with our regulatory framework, which is built on the idea that medicine is all about disease.', 'adj. 管理的, 控制的', '/\'reɡjulətəri/', 'regulatory', 3);
INSERT INTO `words` VALUES (36462, 'Some birds and animals regurgitate food to feed their young.', 'v. 反刍,（液体）回流', '/ri\'ɡə:dʒiteit, ri:- | rɪ\'gɜːdʒɪteɪt | rɪ\'ɡɝdʒɪtet/', 'regurgitate', 3);
INSERT INTO `words` VALUES (36463, 'A lot of the older houses have now been rehabilitated.', 'v. 修复, 改造', '/,ri:hə\'biliteit | riːə\'bɪlɪteɪt | ,riə\'bɪlə,tet/', 'rehabilitate', 3);
INSERT INTO `words` VALUES (36464, 'A second evaluation at the end of this period determines the length of time a detainee must spend in community rehabilitation.', 'n. 复原', '/\'ri:hə,bili\'teiʃən | \'riːhə,bɪlɪ\'teɪʃən | ˌriːəˌbɪlɪ\'teʃn/', 'rehabilitation', 3);
INSERT INTO `words` VALUES (36465, 'I think we need to rehearse the first scene again.', 'v. 预演， 排练； 默诵； 照搬， 重复', '/rɪ\'hɜːrs | rɪ\'hɝs/', 'rehearse', 3);
INSERT INTO `words` VALUES (36466, 'I reheated some soup for lunch.', 'v. 再热', '/ri:\'hi:t | riː\'hiːt/', 'reheat', 3);
INSERT INTO `words` VALUES (36467, NULL, 'v. [化] 再水化, 再水合', '/,riːhaɪ\'dreɪt | ri:\'haidreit/', 'rehydrate', 3);
INSERT INTO `words` VALUES (36468, '...Queen Victoria\'s reign.', 'n. 君主统治; v. 统治, 支配', '/rein | reɪn | ren/', 'reign', 3);
INSERT INTO `words` VALUES (36469, '...a herd of reindeer.', 'n. 驯鹿', '/\'rein\'diə | \'reɪndɪə | \'rendɪr/', 'reindeer', 3);
INSERT INTO `words` VALUES (36470, 'The film reinforces the idea that women should be pretty and dumb.', 'v. 增强，加强', '/,ri:in\'fɔ:s | riːɪn\'fɔːs | ,riɪn\'fɔrs/', 'reinforce', 3);
INSERT INTO `words` VALUES (36471, 'This new perspective -- that a certain unremitting flux is the norm -- has illuminated past data for reinterpretation.', 'n. 重新解释', '/ri:in,tə:pri\'teiʃən/', 'reinterpretation', 3);
INSERT INTO `words` VALUES (36472, 'Let me reiterate the most important points.', 'vt. 反复说， 重申', '/ri\'ɪtəreɪt | rɪ\'ɪtəret/', 'reiterate', 3);
INSERT INTO `words` VALUES (36473, 'Sarah rejected her brother’s offer of help.', 'v. 拒绝,退回', '/ri\'dʒekt | rɪ\'dʒekt | rɪ\'dʒɛkt/', 'reject', 3);
INSERT INTO `words` VALUES (36474, 'They sent me a rejection letter.', 'n. 拒绝', '/ri\'dʒekʃən | rɪ\'dʒekʃ(ə)n | rɪ\'dʒɛkʃən/', 'rejection', 3);
INSERT INTO `words` VALUES (36475, 'The prime minister of Fiji has said Fiji is in no hurry to rejoin the Commonwealth.', 'v. 再结合, 再加入', '/,ri:\'dʒɔin, ri- | riː\'dʒɒɪn | ,ri\'dʒɔɪn/', 'rejoin', 3);
INSERT INTO `words` VALUES (36476, 'plans to rejuvenate the inner city areas', 'vt. 使年轻； 使恢复活力', '/rɪ\'dʒuːvəneɪt | rɪ\'dʒuvənet/', 'rejuvenate', 3);
INSERT INTO `words` VALUES (36477, 'There are fears that the series could rekindle animosity between the two countries.', 'vt. 重新点燃； 使振作', '/ˌriː\'kɪndl | ,ri\'kɪndl/', 'rekindle', 3);
INSERT INTO `words` VALUES (36478, 'I don’t understand how the two ideas relate.', 'v. 叙述,使有联系,有关联', '/ri\'leit | rɪ\'leɪt | rɪ\'let/', 'relate', 3);
INSERT INTO `words` VALUES (36479, 'The price the meat is sold for bears no relation to (= is not connected to ) the price the farmer receives.', 'n. 关系,联系', '/ri\'leiʃən | rɪ\'leɪʃ(ə)n | rɪ\'leʃən/', 'relation', 3);
INSERT INTO `words` VALUES (36480, 'One of these tables contains only traditional relational columns, while the second contains relational columns and one XML column.', 'adj. 有关系的, 亲属的', '/ri\'leiʃənəl | rɪ\'leɪʃ(ə)n(ə)l | rɪ\'leʃənl/', 'relational', 3);
INSERT INTO `words` VALUES (36481, 'The relative merits of both approaches have to be considered.', 'adj. 相对的,相关的; n. 亲属', '/\'relətiv | \'relətɪv | \'rɛlətɪv/', 'relative', 3);
INSERT INTO `words` VALUES (36482, 'I just want to sit down and relax.', 'v. 放松,休息', '/ri\'læks | rɪ\'læks/', 'relax', 3);
INSERT INTO `words` VALUES (36483, 'I play the piano for relaxation.', 'n. 松弛, 放宽', '/,ri:læk\'seiʃən | riːlæk\'seɪʃ(ə)n | \'rilæk\'seʃən/', 'relaxation', 3);
INSERT INTO `words` VALUES (36484, 'the 100 metres relay', 'n. 接力赛；中继转播(设备) vt转述；转播', '/\'ri:lei, ri\'lei | \'riːleɪ | rɪ\'le/', 'relay', 3);
INSERT INTO `words` VALUES (36485, 'Police arrested several men, who were later released.', 'vt&n. 释放,解脱', '/ri\'li:s | rɪ\'liːs | rɪ\'lis/', 'release', 3);
INSERT INTO `words` VALUES (36486, 'Might it not be better to relegate the king to a purely ceremonial function?', 'vt. 使贬职， 使降级； 放逐， 贬谪', '/\'relɪgeɪt | \'rɛlɪɡet/', 'relegate', 3);
INSERT INTO `words` VALUES (36487, 'I think we can all appreciate the relevance of that now.', 'n. 中肯, 适当', '/\'relivəns | \'reləvəns | \'rɛləvəns/', 'relevance', 3);
INSERT INTO `words` VALUES (36488, 'Relevant documents were presented in court.', 'adj. 相关的, 切题的', '/ˈreləvənt | \'rɛləvənt/', 'relevant', 3);
INSERT INTO `words` VALUES (36489, 'I can assure you of the reliability of the information.', 'n. 可靠性', '/ri,laiə\'biləti | rɪ,laɪə\'bɪlətɪ | rɪ,laɪə\'bɪləti/', 'reliability', 3);
INSERT INTO `words` VALUES (36490, 'a birth control method that is cheap and reliable', 'adj. 可靠的,可信赖的', '/ri\'laiəbl | rɪ\'laɪəb(ə)l | rɪ\'laɪəbl/', 'reliable', 3);
INSERT INTO `words` VALUES (36491, 'the country’s heavy reliance on trade', 'n. 信任,信心,依靠', '/ri\'laiəns | rɪ\'laɪəns/', 'reliance', 3);
INSERT INTO `words` VALUES (36492, 'These people are not wholly reliant on Western charity.', 'adj. 信赖的, 依靠的', '/ri\'laiənt | rɪ\'laɪənt/', 'reliant', 3);
INSERT INTO `words` VALUES (36493, 'Roman relics found in a field', 'n. 遗物, 废墟', '/\'relik | \'relɪk | \'rɛlɪk/', 'relic', 3);
INSERT INTO `words` VALUES (36494, NULL, 'n. 残遗物', '/\'relikt, ri\'likt | \'relɪkt | \'rɛlɪkt/', 'relict', 3);
INSERT INTO `words` VALUES (36495, 'I felt a huge surge of relief and happiness.', 'n. 轻松，缓解', '/rɪ\'liːf | rɪ\'lif/', 'relief', 3);
INSERT INTO `words` VALUES (36496, 'Drugs helped to relieve the pain.', 'v. 减轻, 解除', '/ri\'li:v | rɪ\'liːv | rɪ\'liv/', 'relieve', 3);
INSERT INTO `words` VALUES (36497, NULL, 'n. 救济者； 缓解物', '/rɪ\'liːvər | rɪ\'livɚ/', 'reliever', 3);
INSERT INTO `words` VALUES (36498, 'The U.S. Constitution promises freedom of religion.', 'n. 宗教,信仰', '/ri\'lidʒən | rɪ\'lɪdʒ(ə)n | rɪ\'lɪdʒən/', 'religion', 3);
INSERT INTO `words` VALUES (36499, 'I don’t share her religious beliefs .', 'adj. 宗教的', '/ri\'lidʒəs | rɪ\'lɪdʒəs/', 'religious', 3);
INSERT INTO `words` VALUES (36500, 'Do these exercises religiously every day.', 'adv. 虔诚地, 笃信地', '/rɪ\'lɪdʒəsli/', 'religiously', 3);
INSERT INTO `words` VALUES (36501, 'If the company was to relocate, most employees would move.', 'v. 重新部署', '/,ri:ləu\'keit, ri:\'ləukeit | riːlə(ʊ)\'keɪt | ,ri\'loket/', 'relocate', 3);
INSERT INTO `words` VALUES (36502, 'Wells finally agreed, but with reluctance.', 'n. 不愿, 勉强', '/ri\'lʌktəns | rɪ\'lʌkt(ə)ns | rɪ\'lʌktəns/', 'reluctance', 3);
INSERT INTO `words` VALUES (36503, 'She gave a reluctant smile.', 'adj. 不情愿的, 勉强的', '/ri\'lʌktənt | rɪ\'lʌkt(ə)nt | rɪ\'lʌktənt/', 'reluctant', 3);
INSERT INTO `words` VALUES (36504, 'The mistress of the house reluctantly installed the two refugees in a spare room.', 'adj. 不情愿地；勉强地', '/ri\'lʌktəntli | rɪ\'lʌktəntlɪ | rɪ\'lʌktəntli/', 'reluctantly', 3);
INSERT INTO `words` VALUES (36505, 'They relied heavily on the advice of their professional advisers.', 'v. 依赖,依靠', '/ri\'lai | rɪ\'laɪ/', 'rely', 3);
INSERT INTO `words` VALUES (36506, 'The remainder must be paid by the end of June.', 'n. 残余, 剩余物; adj. 剩余的', '/ri\'meində | rɪ\'meɪndə | rɪ\'mendɚ/', 'remainder', 3);
INSERT INTO `words` VALUES (36507, 'extensive Roman remains (= of ancient buildings ) at Arles', 'n. 剩余物， 残留物； 古代遗物， 遗迹， 遗址； 遗骸', '/rɪ\'meɪnz | rɪ\'menz/', 'remains', 3);
INSERT INTO `words` VALUES (36508, 'Unfortunately, a local journalist overheard the remark.', 'n. 备注,评论 vt评论', '/ri\'mɑ:k | rɪ\'mɑːk | rɪ\'mɑrk/', 'remark', 3);
INSERT INTO `words` VALUES (36509, 'She has made remarkable progress.', 'adj. 非凡的,显著的', '/ri\'mɑ:kəbl | rɪ\'mɑːkəb(ə)l | rɪ\'mɑrkəbl/', 'remarkable', 3);
INSERT INTO `words` VALUES (36510, 'Remarkably, all of the passengers survived the crash.', 'adv. 非凡地；显著地', '/ri\'ma:kəbli | rɪ\'mɑːkəblɪ | rɪ\'mɑkəblɪ/', 'remarkably', 3);
INSERT INTO `words` VALUES (36511, 'If you do find an infected machine, the jury is out about how best to do remediation.', 'n. 补习,补救', '/ri,mi:di\'eiʃən | rɪ,miːdɪ\'eɪʃ(ə)n | rɪ,midɪ\'eʃən/', 'remediation', 3);
INSERT INTO `words` VALUES (36512, 'Do you remember Rosa Davies?', 'v. 回忆起,记得', '/ri\'membə | rɪ\'membə | rɪ\'mɛmbɚ/', 'remember', 3);
INSERT INTO `words` VALUES (36513, 'Yes, I’ll be there. Thanks for reminding me.', 'v. 提醒, 使想起', '/ri\'maind | rɪ\'maɪnd/', 'remind', 3);
INSERT INTO `words` VALUES (36514, 'The last thing you\'d want is a constant reminder of a bad experience.', 'n. 提醒物；暗示', '/ri\'maində | rɪ\'maɪndə | rɪ\'maɪndɚ/', 'reminder', 3);
INSERT INTO `words` VALUES (36515, 'Beneath the present church were remnants of Roman flooring.', 'n. 残余, 剩余', '/\'remnənt | \'rɛmnənt/', 'remnant', 3);
INSERT INTO `words` VALUES (36516, 'Workmen were hired to remodel and enlarge the farm buildings.', 'v. 重新塑造, 改造', '/,ri:\'mɔdəl | riː\'mɒd(ə)l | ,ri\'mɑdl/', 'remodel', 3);
INSERT INTO `words` VALUES (36517, 'a remote border town', 'adj. 遥远的, 偏僻的', '/ri\'məut | rɪ\'məʊt | rɪ\'mot/', 'remote', 3);
INSERT INTO `words` VALUES (36518, 'stain removal', 'n. 除去，移动', '/ri\'mu:vəl | rɪ\'muːv(ə)l | rɪ\'muvl/', 'removal', 3);
INSERT INTO `words` VALUES (36519, 'Remove the old wallpaper and fill any holes in the walls.', 'v. 移开,去除', '/ri\'mu:v | rɪ\'muːv | rɪ\'muv/', 'remove', 3);
INSERT INTO `words` VALUES (36520, 'high rates of remuneration', 'n. 报酬', '/ri,mju:nə\'reiʃən | rɪ,mjuːnə\'reɪʃ(ə)n | rɪ,mjunə\'reʃən/', 'remuneration', 3);
INSERT INTO `words` VALUES (36521, '...the Renaissance masterpieces in London\'s galleries.', 'n. 文艺复兴(时期)', '/\'rɛnəsɑns | rɪ\'neɪsəns/', 'renaissance', 3);
INSERT INTO `words` VALUES (36522, 'Tel Aviv\'s Kings Square was renamed Yitzhak Rabin Square.', 'v. 重新命名, 改名', '/,ri:\'neim | riː\'neɪm | ,ri\'nem/', 'rename', 3);
INSERT INTO `words` VALUES (36523, NULL, 'v. 撕裂，猛拉', '/rend | rɛnd/', 'rend', 3);
INSERT INTO `words` VALUES (36524, 'an obligation to render assistance to those in need', 'v. 使得,提供', '/\'rendə | \'rɛndɚ/', 'render', 3);
INSERT INTO `words` VALUES (36525, 'He gave a moving rendition of Lennon’s ‘Imagine’.', 'n. 表演， 演唱； 提供， 给予； 翻译', '/ren\'dɪʃn | rɛn\'dɪʃən/', 'rendition', 3);
INSERT INTO `words` VALUES (36526, 'The window frames need to be renewed.', 'v. 更新, 恢复', '/rɪ\'njuː | rɪ\'nʊ/', 'renew', 3);
INSERT INTO `words` VALUES (36527, 'It’s a six-month lease but it’s renewable.', 'adj. 可更新的, 可再生的', '/ri\'nju:əbl | rɪ\'njuːəbəl | rɪ\'nuəbl/', 'renewable', 3);
INSERT INTO `words` VALUES (36528, 'Mark’s contract comes up for renewal at the end of this year.', 'n. 更新, 恢复', '/ri\'nju:əl | rɪ\'njuːəl | rɪ\'nuəl/', 'renewal', 3);
INSERT INTO `words` VALUES (36529, NULL, 'n. 高血压蛋白原酶', '/\'renin | \'renɪn/', 'rennin', 3);
INSERT INTO `words` VALUES (36530, 'Edward renounced his claim to the French throne.', 'v. 宣布放弃,断绝关系', '/ri\'nauns | rɪ\'naʊns/', 'renounce', 3);
INSERT INTO `words` VALUES (36531, 'The hotel has been renovated and redecorated.', 'vt. 修复； 更新， 翻新', '/\'renəveɪt | \'rɛnəvet/', 'renovate', 3);
INSERT INTO `words` VALUES (36532, 'He achieved some renown as a football player.', 'n. 名望， 声誉', '/rɪ\'naun | rɪ\'naʊn/', 'renown', 3);
INSERT INTO `words` VALUES (36533, 'The area is renowned for its Romanesque churches.', 'adj. 有名的, 有声誉的', '/ri\'naund | rɪ\'naʊnd/', 'renowned', 3);
INSERT INTO `words` VALUES (36534, 'Most students rent rooms in their second year.', 'v. 租用,出租; n. 租金', '/rent | rɛnt/', 'rent', 3);
INSERT INTO `words` VALUES (36535, 'Taller buildings also tended to taper inwards, further reducing rentable space; the cost of moving materials and people also soars.', 'adj. 可出租的', '/\'rentəbl/', 'rentable', 3);
INSERT INTO `words` VALUES (36536, 'Video rental is usually £3.', 'n. 租金额', '/\'rentəl | \'rent(ə)l | \'rɛntl/', 'rental', 3);
INSERT INTO `words` VALUES (36537, 'He considers himself fortunate to be a renter in the Detroit area, where the “for sale” signs are multiplying.', 'n. 租贷人', '/\'rentə | \'rɛntɚ/', 'renter', 3);
INSERT INTO `words` VALUES (36538, 'The talks were dependent on a renunciation of terrorism.', 'n. 放弃，抛弃', '/ri,nʌnsi\'eiʃən | rɪnʌnsɪ\'eɪʃ(ə)n | rɪ,nʌnsɪ\'eʃən/', 'renunciation', 3);
INSERT INTO `words` VALUES (36539, 'The swimming pool will reopen in May.', 'v. 重开,再开始', '/,ri:\'əupən | riː\'əʊp(ə)n | ,ri\'opən/', 'reopen', 3);
