INSERT INTO `words` VALUES (36541, NULL, 'v. 重定的方向(或方位)', '/ri:\'ɔ:rient | riː\'ɔːrɪent; -\'ɒr- | ,ri\'ɔrɪɛnt/', 'reorient', 3);
INSERT INTO `words` VALUES (36542, 'The church tower is in need of repair .', 'n. 修理 vt修理(补)', '/ri\'pεə | rɪ\'peə | rɪ\'pɛr/', 'repair', 3);
INSERT INTO `words` VALUES (36543, 'I’d like to buy them something to repay all their kindness.', 'v. 偿还, 报答', '/ri:\'pei, ri- | riː\'peɪ; rɪ- | ri\'pɛi/', 'repay', 3);
