INSERT INTO `words` VALUES (36545, 'Both men have repeatedly denied the allegations.', 'adv. 重复地, 再三地', '/ri\'pi:tidli | rɪ\'piːtɪdlɪ | rɪ\'pitɪdli/', 'repeatedly', 3);
