INSERT INTO `words` VALUES (36548, 'a repertory company', 'n. 仓库', '/\'repətəri | \'repət(ə)rɪ | \'rɛpɚtɔri/', 'repertory', 3);
INSERT INTO `words` VALUES (36549, 'Children used to learn by repetition.', 'n. 重复，反复', '/,repi\'tiʃən | repɪ\'tɪʃ(ə)n | \'rɛpə\'tɪʃən/', 'repetition', 3);
INSERT INTO `words` VALUES (36550, 'The song was dreary and repetitive.', 'adj. 重复的,反复的', '/ri\'petətiv | rɪ\'petɪtɪv | rɪ\'pɛtətɪv/', 'repetitive', 3);
INSERT INTO `words` VALUES (36551, 'Again, the executive rephrased the question.', 'v. 改述', '/ri:\'freiz | riː\'freɪz | ,ri\'frez/', 'rephrase', 3);
INSERT INTO `words` VALUES (36552, 'I’m replacing Sue on the team.', 'v. 取代,替换,放回原处', '/ri\'pleis | rɪ\'pleɪs | rɪ\'ples/', 'replace', 3);
INSERT INTO `words` VALUES (36553, 'Our old car is badly in need of replacement.', 'n. 代替，更换', '/ri\'pleismənt | rɪ\'pleɪsm(ə)nt | rɪ\'plesmənt/', 'replacement', 3);
INSERT INTO `words` VALUES (36554, 'she replanted the bulbs that the dog had dug up', 'v. 再植, 改种', '/,ri:\'plɑ:nt, -\'plænt/', 'replant', 3);
INSERT INTO `words` VALUES (36555, 'More vaccines are needed to replenish our stocks.', 'v. 补充', '/ri\'pleniʃ | rɪ\'plenɪʃ | rɪ\'plɛnɪʃ/', 'replenish', 3);
INSERT INTO `words` VALUES (36556, 'There is a concern about replenishment of the population.', 'n. 补给, 补充', '/ri\'pleniʃmənt | rɪ\'plenɪʃmənt | rɪ\'plɛnɪʃmənt/', 'replenishment', 3);
INSERT INTO `words` VALUES (36557, 'replica guns', 'n. 复制品', '/\'replikə | \'replɪkə | \'rɛplɪkə/', 'replica', 3);
INSERT INTO `words` VALUES (36558, 'There is a need for further research to replicate these findings.', 'v. 复制; adj. 复制的', '/\'replikit, \'replikeit | \'replɪkeɪt | \'rɛplɪket/', 'replicate', 3);
INSERT INTO `words` VALUES (36559, 'I tried calling, but there was no reply.', 'n. 答复, 答辩v答复, 回击', '/ri\'plai | rɪ\'plaɪ | rɪ\'plai/', 'reply', 3);
INSERT INTO `words` VALUES (36560, 'According to recent news reports , two of the victims are Americans.', 'n. 报告; v. 报导,汇报', '/ri\'pɔ:t | rɪ\'pɔːt | rɪ\'pɔrt/', 'report', 3);
INSERT INTO `words` VALUES (36561, 'Her husband’s assets are reportedly worth over $15 million.', 'adv. 据传说, 据传闻', '/ri\'pɔ:tidli | rɪ\'pɔːtɪdlɪ | rɪ\'pɔrtɪdli/', 'reportedly', 3);
INSERT INTO `words` VALUES (36562, 'Mr Kobayashi was chosen to represent the company at the conference.', 'v. 代表,表现,描绘', '/,repri\'zent | reprɪ\'zent | ,rɛprɪ\'zɛnt/', 'represent', 3);
INSERT INTO `words` VALUES (36563, 'Puerto Ricans are U.S. citizens but they have no representation in Congress.', 'n. 表示法,表现,陈述', '/,reprizen\'teiʃən | ,reprɪzen\'teɪʃ(ə)n | \'rɛprɪzɛn\'teʃən/', 'representation', 3);
INSERT INTO `words` VALUES (36564, 'a union representative', 'n. 代表 a典型的, 有代表性的', '/,repri\'zentətiv | reprɪ\'zentətɪv | \'rɛprɪ\'zɛntətɪv/', 'representative', 3);
INSERT INTO `words` VALUES (36565, 'He had long ago repressed the painful memories of his childhood.', 'v. 抑制，镇压', '/ri\'pres | rɪ\'pres | rɪ\'prɛs/', 'repress', 3);
INSERT INTO `words` VALUES (36566, '{\"COLLOINEXA\":[\"sexual repression\"]}', 'n. 镇压, 抑制', '/ri\'preʃən | rɪ\'preʃən | rɪ\'prɛʃən/', 'repression', 3);
INSERT INTO `words` VALUES (36567, 'Fourteen people, waiting to be hanged for the murder of a former prime minister, have been reprieved.', 'n& v. 缓刑，暂时解救', '/ri\'pri:v | rɪ\'priːv | rɪ\'priv/', 'reprieve', 3);
INSERT INTO `words` VALUES (36568, 'It remained an exceptionally rare book until it was reprinted in 1918.', 'v. 再版', '/,ri:\'print, \'ri:print | riː\'prɪnt | ,ri\'prɪnt/', 'reprint', 3);
INSERT INTO `words` VALUES (36569, '‘You don’t need me,’ she said quietly, without reproach.', 'v&n. 指责， 斥责， 批评', '/rɪ\'proutʃ | rɪ\'protʃ/', 'reproach', 3);
INSERT INTO `words` VALUES (36570, 'Klimt’s artwork is reproduced in this exquisite book.', 'v. 再生,复制', '/,ri:prə\'dju:s | riːprə\'djuːs | ,riprə\'dus/', 'reproduce', 3);
INSERT INTO `words` VALUES (36571, '...a reproduction of a popular religious painting.', 'n. 再现,复制品', '/,ri:prə\'dʌkʃən | riːprə\'dʌkʃ(ə)n | ,riprə\'dʌkʃən/', 'reproduction', 3);
INSERT INTO `words` VALUES (36572, 'the human reproductive system', 'adj. 生殖的,再生的,复制的', '/,ri:prə\'dʌktiv | ,riːprə\'dʌktɪv | ,riprə\'dʌktɪv/', 'reproductive', 3);
INSERT INTO `words` VALUES (36573, 'Bird evolved from reptiles, so the first bird must have come out of an egg--laid by a reptile.', 'n. 爬虫动物', '/\'reptail, -til | \'reptaɪl | \'rɛptaɪl/', 'reptile', 3);
INSERT INTO `words` VALUES (36574, 'A man who switches on his emotions is more likely to go into a reptilian mode and lash out vocally or become aggressive.', 'n. 爬行类动物', '/rep\'tiliən | rep\'tɪlɪən | rɛp\'tɪlɪən/', 'reptilian', 3);
