INSERT INTO `words` VALUES (36576, 'What made you decide to become a Republican, as opposed to a Democrat?', 'a&n. 共和政体的,共和党人(的)', '/ri\'pʌblikən | rɪ\'pʌblɪk(ə)n | rɪ\'pʌblɪkən/', 'republican', 3);
INSERT INTO `words` VALUES (36577, 'If you wish to switch the query mode for a package, you must republish the package with the desired setting.', 'v. 再版, 重新发表', '/,ri:\'pʌbliʃ | riː\'pʌblɪʃ | ri\'pʌblɪʃ/', 'republish', 3);
INSERT INTO `words` VALUES (36578, 'Leaders urged people to turn out in large numbers to repudiate the violence.', 'v. 批判', '/ri\'pju:dieit | rɪ\'pjuːdɪeɪt | rɪ\'pjudɪet/', 'repudiate', 3);
INSERT INTO `words` VALUES (36579, 'Alice Munro has a reputation for being a very depressing writer.', 'n. 名誉, 名声', '/,repju\'teiʃən | repjʊ\'teɪʃ(ə)n | ,rɛpju\'teʃən/', 'reputation', 3);
INSERT INTO `words` VALUES (36580, 'Under his leadership, the U.N.\'s repute has risen immeasurably.', 'n. 名誉, 名声 v认为', '/ri\'pju:t | rɪ\'pjuːt | rɪ\'pjut/', 'repute', 3);
INSERT INTO `words` VALUES (36581, 'To request more information, please call our toll free number.', 'v. 请求, 要求', '/ri\'kwest | rɪ\'kwest | rɪ\'kwɛst/', 'request', 3);
