INSERT INTO `words` VALUES (36585, 'The starlight he ats up the dust grains, which then reradiate this energy at far-infrared wavelengths.', 'vt. 再辐射(转播)', '/riː\'reɪdɪeɪt | ri\'redɪ,et/', 'reradiate', 3);
