INSERT INTO `words` VALUES (36587, 'Since I\'ll be away, I\'d like to reschedule the meeting.', 'vt. 重新计划， 重订…的时间表', '/ˌriː\'skedʒuːl | ,ri\'skɛdʒul/', 'reschedule', 3);
INSERT INTO `words` VALUES (36588, 'Survivors of the crash were rescued by helicopter.', 'v. ／ n营救，救援', '/\'reskju: | \'reskjuː | \'rɛskju/', 'rescue', 3);
