INSERT INTO `words` VALUES (36590, 'There was a remarkable resemblance between him and Pete.', 'n. 相似，形似', '/ri\'zembləns | rɪ\'zembl(ə)ns | rɪ\'zɛmbləns/', 'resemblance', 3);
