INSERT INTO `words` VALUES (36597, 'She was careful to reset the alarm before she left the office.', 'v. 重新安排', '/,ri:\'set, \'ri:set | riː\'set | \'risɛt/', 'reset', 3);
INSERT INTO `words` VALUES (36598, 'The area was resettled in the latter half of the century.', 'v. (使)重新定居,再坐下来', '/ri:\'setl/', 'resettle', 3);
