INSERT INTO `words` VALUES (36602, 'He applied for Canadian residency.', 'n. 居住, 住所', '/\'rezidənsi | \'rezɪd(ə)nsɪ | \'rɛzɪdənsi/', 'residency', 3);
INSERT INTO `words` VALUES (36603, 'As one local resident put it in May, \"By day there is government.', 'n. 居民', '/ˈrɛzɪdənt | \'rɛzɪdənt/', 'resident', 3);
