INSERT INTO `words` VALUES (36608, 'People showed remarkable resilience during the war.', 'n. 弹性，弹力', '/ri\'ziliəns, -jəns | rɪ\'zɪlɪəns | rɪˈzɪliəns/', 'resilience', 3);
