INSERT INTO `words` VALUES (36615, 'a resolution calling for a ban on dumping nuclear waste', 'n. 决心,决议', '/,rezə\'lu:ʃən, -,lju:- | rezə\'luːʃ(ə)n | ,rɛzə\'luʃən/', 'resolution', 3);
INSERT INTO `words` VALUES (36616, 'Barnet was desperate for money to resolve his financial problems.', 'v. 解决, 决定', '/ri\'zɔlv | rɪ\'zɒlv | rɪ\'zɑlv/', 'resolve', 3);
INSERT INTO `words` VALUES (36617, 'a tradition that has little resonance in the 21st century', 'n. 共鸣, 反响', '/\'rezənəns | \'rez(ə)nəns | \'rɛznəns/', 'resonance', 3);
INSERT INTO `words` VALUES (36618, NULL, 'n. 共鸣器', '/\'rezəneitə | \'rez(ə)neɪtə | \'rɛzə\'netɚ/', 'resonator', 3);
INSERT INTO `words` VALUES (36619, 'His punishing work schedule had made him resort to drugs.', 'vi& n. 求助，采用', '/ri\'zɔ:t | rɪ\'zɔːt | rɪ\'zɔrt/', 'resort', 3);
INSERT INTO `words` VALUES (36620, 'Canada’s vast mineral resources', 'n. 资源', '/ri\'sɔ:s, -\'zɔ:s, \'ri:s-, \'ri:z- | rɪ\'sɔːs; rɪ\'zɔːs | \'risɔrs/', 'resource', 3);
INSERT INTO `words` VALUES (36621, 'What stories can you relay that show your passion, initiative and resourcefulness?', 'n. 足智多谋', '/ri\'sɔ:sfəlnis/', 'resourcefulness', 3);
