INSERT INTO `words` VALUES (36623, '...investments that offer respectable and highly attractive rates of return.', 'adj. 可敬的；有身价的', '/ri\'spektəbl | rɪ\'spektəb(ə)l | rɪ\'spɛktəbl/', 'respectable', 3);
INSERT INTO `words` VALUES (36624, 'We all went back to our respective homes to wait for news.', 'adj. 分别的, 各自的', '/ri\'spektiv | rɪ\'spektɪv | rɪ\'spɛktɪv/', 'respective', 3);
INSERT INTO `words` VALUES (36625, 'The cups and saucers cost £5 and £3 respectively.', 'adv. 分别地, 各个地', '/ri\'spektivli | rɪ\'spektɪvlɪ | rɪ\'spɛktɪvli/', 'respectively', 3);
INSERT INTO `words` VALUES (36626, 'His respiration grew fainter throughout the day.', 'n. 呼吸, 呼吸作用', '/,respə\'reiʃən | respɪ\'reɪʃ(ə)n | ,rɛspə\'reʃən/', 'respiration', 3);
INSERT INTO `words` VALUES (36627, 'Fish generally respire through gills.', 'v. 呼吸', '/rɪ\'spaɪər | rɪ\'spaɪɚ/', 'respire', 3);
