INSERT INTO `words` VALUES (36629, 'Upon receipt of a copy of the arbitration application, the respondent shall, within the time limit prescribed by the Arbitration Rules, submit its defence to the arbitration commission.', 'n. 应答者, 被告', '/ri\'spɔndənt | rɪ\'spɒnd(ə)nt | rɪ\'spɑndənt/', 'respondent', 3);
INSERT INTO `words` VALUES (36630, 'His immediate response was one of disbelief.', 'n. 回答,响应,反应', '/ri\'spɔns | rɪ\'spɒns | rɪ\'spɑns/', 'response', 3);
INSERT INTO `words` VALUES (36631, 'Kelly’s promotion means more money and more responsibility.', 'n. 责任,职责', '/ri.spɔnsə\'biliti | rɪˌspɒnsəˈbɪlətɪ | rɪˌspɑːnsəˈbɪləti/', 'responsibility', 3);
INSERT INTO `words` VALUES (36632, 'We are determined to bring the people responsible to justice.', 'adj. 有责任的,负责的', '/ri\'spɔnsəbl | rɪ\'spɒnsɪb(ə)l | rɪ\'spɑnsəbl/', 'responsible', 3);
INSERT INTO `words` VALUES (36633, 'a car with highly responsive steering', 'adj. 响应的,应答的', '/ri\'spɔnsiv | rɪ\'spɒnsɪv | rɪ\'spɑnsɪv/', 'responsive', 3);
INSERT INTO `words` VALUES (36634, 'Performance testing to gauge the scalability and responsiveness of new services should always be part of the plan.', 'n. 响应能力,有同情心', '/ri\'spɔnsivnis | rɪ\'spɑnsɪvnɪs/', 'responsiveness', 3);
INSERT INTO `words` VALUES (36635, 'You look exhausted! Why don’t you take a rest?', 'n&v. 休息', '/rest | rɛst/', 'rest', 3);
