INSERT INTO `words` VALUES (36637, 'He took her out for a five-course dinner in a fancy restaurant.', 'n. 餐馆, 饭店', '/\'restərɔŋ, -rɔnt, -rənt | ˈrɛstəˌrɒŋ; ˈrɛstrɒŋ; -rɒnt | ˈrɛstəˌrɑnt; ˈrɛstərənt; ˈrɛsˌtrɑnt/', 'restaurant', 3);
INSERT INTO `words` VALUES (36638, 'restful music', 'adj. 宁静的', '/\'restful | \'res(t)fʊl; -f(ə)l | \'rɛstfl/', 'restful', 3);
INSERT INTO `words` VALUES (36639, 'After a few weeks in Marseille, I grew restless and decided to move on.', 'adj. 得不到休息的, 不安宁的', '/\'restlis | ˈrestləs | \'rɛstləs/', 'restless', 3);
INSERT INTO `words` VALUES (36640, NULL, 'n. 辗转不安, 烦躁不安', '/\'restlisnis | ˈrestlɪsnɪs | rɛstlɪsnɪs/', 'restlessness', 3);
INSERT INTO `words` VALUES (36641, 'You have control over the restoration of objects.', 'n. 恢复, 归还', '/,restə\'reiʃən | restə\'reɪʃ(ə)n | \'rɛstə\'reʃən/', 'restoration', 3);
INSERT INTO `words` VALUES (36642, 'She was hoping that the Mediterranean climate would restore her to full health.', 'v. 恢复,重建', '/ri\'stɔ: | rɪ\'stɔː | rɪ\'stɔr/', 'restore', 3);
INSERT INTO `words` VALUES (36643, 'Renwick restrained a feeling of annoyance.', 'v. 抑制, 制止', '/ri\'strein | rɪ\'streɪn | rɪ\'stren/', 'restrain', 3);
INSERT INTO `words` VALUES (36644, 'The police were praised for their restraint in handling the demonstrators.', 'n. 抑制, 制止', '/ri\'streint | rɪ\'streɪnt | rɪ\'strent/', 'restraint', 3);
INSERT INTO `words` VALUES (36645, 'The new law restricts the sale of hand guns.', 'v. 限制,约束', '/ri\'strikt | rɪ\'strɪkt/', 'restrict', 3);
INSERT INTO `words` VALUES (36646, 'a 50 mph speed restriction', 'n. 限制, 约束', '/ri\'strikʃən | rɪ\'strɪkʃ(ə)n | rɪ\'strɪkʃən/', 'restriction', 3);
INSERT INTO `words` VALUES (36647, 'Many members thought the rules were too restrictive.', 'adj. 限制性的', '/ri\'striktiv | rɪ\'strɪktɪv/', 'restrictive', 3);
INSERT INTO `words` VALUES (36648, 'She hopes to resume work after the baby is born.', 'v. (中断后)继续 n摘要；简历', '/rezju:\'mei, ri\'zju:m; -\'zu:m | rɪˈzjuːm; ˈrɛzjʊmeɪ/', 'resume', 3);
INSERT INTO `words` VALUES (36649, 'a retail price of £8.99', 'n. ／v／ad零售', '/\'ri:teil | \'riːteɪl | \'ritel/', 'retail', 3);
INSERT INTO `words` VALUES (36650, 'Furniture and carpet retailers are among those reporting the sharpest annual decline in sales.', 'n. 零售商人', '/\'ri:teilə | \'riːteɪlə/', 'retailer', 3);
INSERT INTO `words` VALUES (36651, 'You have the right to retain possession of the goods.', 'v. 保持,保留', '/ri\'tein | rɪ\'teɪn | rɪ\'ten/', 'retain', 3);
INSERT INTO `words` VALUES (36652, 'Continuing violence will retard negotiations over the country\'s future.', 'v. 延迟, 妨碍; n. 延迟', '/ri\'tɑ:d | \'rɪtɑːd | \'rɪtɑrd/', 'retard', 3);
INSERT INTO `words` VALUES (36653, 'Luke had an amazingly retentive memory.', 'adj. 有记忆力的', '/ri\'tentiv | rɪ\'tentɪv | rɪ\'tɛntɪv/', 'retentive', 3);
INSERT INTO `words` VALUES (36654, 'At the age when most people retire, he is ready to face a new career.', 'v. 退休', '/ri\'taiə | rɪ\'taɪə | rɪ\'taɪɚ/', 'retire', 3);
INSERT INTO `words` VALUES (36655, 'She took early retirement (= retired at an earlier age than usual ) last year.', 'n. 退休', '/ri\'taiəmənt | rɪ\'taɪəm(ə)nt | rɪ\'taɪɚmənt/', 'retirement', 3);
INSERT INTO `words` VALUES (36656, 'The College Board has retooled the admission exams.', 'v. 将机械重新整备, 重组', '/ri:\'tu:l | riː\'tuːl | ,ri\'tul/', 'retool', 3);
INSERT INTO `words` VALUES (36657, 'He confessed to the murder but later retracted his statement.', 'v. 缩回, 撤销', '/ri\'trækt | rɪ\'trækt/', 'retract', 3);
INSERT INTO `words` VALUES (36658, 'One solution is to retrain the long-term unemployed.', 'v. 重新教育, 再教育', '/ri:\'trein/', 'retrain', 3);
INSERT INTO `words` VALUES (36659, 'The rebels retreated to the mountains.', 'v. 撤退,退却', '/ri\'tri:t | rɪ\'triːt | rɪ\'trit/', 'retreat', 3);
INSERT INTO `words` VALUES (36660, '...electronic storage and retrieval systems.', 'n. 取回，补偿', '/ri\'tri:vəl | rɪ\'triːvl | rɪ\'trivl/', 'retrieval', 3);
INSERT INTO `words` VALUES (36661, 'She bent down to retrieve her earring.', 'v. 恢复,挽回,取回', '/ri\'tri:v | rɪ\'triːv | rɪ\'triv/', 'retrieve', 3);
INSERT INTO `words` VALUES (36662, 'In retrospect, I wonder if we should have done more.', 'n. 回顾', '/\'retrəuspekt | \'retrəspekt | \'rɛtrəspɛkt/', 'retrospect', 3);
INSERT INTO `words` VALUES (36663, 'a retrospective study of 110 patients', 'adj. 回顾的， 追想的； 有追溯效力的', '/ˌretrə\'spektɪv | ,rɛtrə\'spɛktɪv/', 'retrospective', 3);
INSERT INTO `words` VALUES (36664, 'It was forty five minutes before she returned.', 'v. 返回,恢复,归还', '/ri\'tə:n | rɪ\'tɜːn | rɪ\'tɝn/', 'return', 3);
INSERT INTO `words` VALUES (36665, 'an annual reunion', 'n. 团圆, 重聚', '/riː\'juːnjən; -ɪən/', 'reunion', 3);
INSERT INTO `words` VALUES (36666, 'The bottles are designed to be reused up to 20 times.', 'v. 再使用 n重新使用', '/,ri:\'ju:z, ,ri:\'ju:s, \'ri:ju:s | riː\'juːz | ,ri\'jʊs/', 'reuse', 3);
INSERT INTO `words` VALUES (36667, 'He may be prosecuted for revealing secrets about the security agency.', 'v. 揭露,显示', '/ri\'vi:l | rɪ\'viːl | rɪ\'vil/', 'reveal', 3);
INSERT INTO `words` VALUES (36668, NULL, 'adv. 启发人地,袒胸露肩地', '/ri\'vi:liŋli/', 'revealingly', 3);
INSERT INTO `words` VALUES (36669, 'advertising revenue', 'n. 收入,税收', '/\'revənju:, -nu: | \'revənjuː | \'rɛvənu/', 'revenue', 3);
INSERT INTO `words` VALUES (36670, 'The Chinese revered corn as a gift from heaven.', 'v. 尊敬,敬畏', '/ri\'viə | rɪ\'vɪə | rɪ\'vɪr/', 'revere', 3);
INSERT INTO `words` VALUES (36671, 'He spoke reverently about colleges and loved walking around the Stanford campus.', 'adv. 恭敬地, 虔诚地', '/\'revərəntli/', 'reverently', 3);
INSERT INTO `words` VALUES (36672, 'Some Internet firms have suffered a painful reversal of fortune (= they were successful but now they are not ) .', 'n. 翻转, 倒转, 反转', '/ri\'və:səl | rɪ\'vɜːs(ə)l | rɪ\'vɝsl/', 'reversal', 3);
INSERT INTO `words` VALUES (36673, 'Reverse the paper in the printer.', 'v. 颠倒,倒转', '/ri\'və:s | rɪ\'vɜːs | rɪ\'vɝs/', 'reverse', 3);
INSERT INTO `words` VALUES (36674, 'A lot of chemical reactions are reversible.', 'adj. 可逆的， 可翻转的； 正反两用的； 可恢复原状的', '/rɪ\'vɜːrsəbl | rɪ\'vɝsəbl/', 'reversible', 3);
INSERT INTO `words` VALUES (36675, 'Jackson said her boss became increasingly depressed and reverted to smoking heavily.', 'v. 回复', '/ri\'və:t, \'ri:və:t | rɪ\'vɜːt | rɪ\'vɝt/', 'revert', 3);
