INSERT INTO `words` VALUES (36677, '...the reviewer for Atlantic Monthly.', 'n. 批评家,评论家', '/ri\'vju:ə | rɪ\'vjuːə | rɪ\'vjuɚ/', 'reviewer', 3);
INSERT INTO `words` VALUES (36678, 'A couple of sections of the book will need to be revised.', 'v. 修订,校订', '/ri\'vaiz, \'ri:vaiz | rɪ\'vaɪz/', 'revise', 3);
INSERT INTO `words` VALUES (36679, 'The phase of writing that is actually most important is revision.', 'n. 修订,修正,修订本', '/ri\'viʒən | rɪ\'vɪʒ(ə)n | rɪ\'vɪʒən/', 'revision', 3);
INSERT INTO `words` VALUES (36680, 'Such bioactive mushroom metabolites are believed to have the capability to helping revitalization of our immune system against a large number of pathogenic and non-pathogenic diseases.', 'n. 新生 复兴', '/ri:,vaitəlai\'zeiʃən, -li\'z- | riːˌvaɪtəlaɪ\'zeɪʃən | ˌrivaɪtlɪ\'zeʃən/', 'revitalization', 3);
INSERT INTO `words` VALUES (36681, 'They hope to revitalize the neighborhood by providing better housing.', 'v. 新生', '/,ri:\'vaitəlaiz | ,ri\'vaɪtəlaɪz/', 'revitalize', 3);
INSERT INTO `words` VALUES (36682, 'The US and the UK have expectations of economic revival.', 'n. 复兴, 复活', '/ri\'vaivəl | rɪ\'vaɪv(ə)l | rɪ\'vaɪvl/', 'revival', 3);
INSERT INTO `words` VALUES (36683, 'Local people have decided to revive this centuries-old tradition.', 'v. 苏醒, (使)复兴', '/ri\'vaiv | rɪ\'vaɪv/', 'revive', 3);
