INSERT INTO `words` VALUES (36685, 'The prime minister is now facing a revolt by members of his own party.', 'v& n. 反抗,反叛', '/ri\'vəult, -\'vɔ:lt | rɪ\'vəʊlt | rɪ\'volt/', 'revolt', 3);
INSERT INTO `words` VALUES (36686, 'the French Revolution of 1789', 'n. 革命', '/,revə\'lu:ʃən | revə\'luːʃ(ə)n | \'rɛvə\'lʊʃən/', 'revolution', 3);
INSERT INTO `words` VALUES (36687, 'The new cancer drug is a revolutionary breakthrough.', 'adj. 革命的', '/,revə\'lju:ʃənəri | revə\'luːʃ(ə)n(ə)rɪ | \'rɛvə\'lʊʃə\'nɛri/', 'revolutionary', 3);
INSERT INTO `words` VALUES (36688, 'The wheel began to revolve.', 'v. 旋转', '/ri\'vɔlv, -\'vɔ:lv | rɪ\'vɒlv | rɪ\'vɔlv/', 'revolve', 3);
INSERT INTO `words` VALUES (36689, 'The school has a system of rewards and punishments to encourage good behaviour.', 'n. 报酬; v. 酬劳', '/ri\'wɔ:d | rɪ\'wɔːd | rɪ\'wɔrd/', 'reward', 3);
INSERT INTO `words` VALUES (36690, 'I’ll have to rewrite most of the essay.', 'v. 重写, 改写', '/,ri:\'rait, \'ri:rait | riː\'raɪt | \'riraɪt/', 'rewrite', 3);
INSERT INTO `words` VALUES (36691, 'He has built a comfortable life in Reykjavik with his family. They vacation abroad.', 'n. 雷克雅末(冰岛首都)', '/\'reikjəvik; -vi:k/', 'Reykjavik', 3);
INSERT INTO `words` VALUES (36692, 'The speech was dismissed by some people as merely political rhetoric .', 'n. 雄辩言辞,修辞学', '/\'retərik | \'retərɪk | \'rɛtərɪk/', 'rhetoric', 3);
INSERT INTO `words` VALUES (36693, 'a speech full of rhetorical phrases', 'adj. 带修辞色彩的', '/ri\'tɔrikəl, -\'tɔ:- | rɪ\'tɒrɪk(ə)l | rɪ\'tɔrɪkl/', 'rhetorical', 3);
INSERT INTO `words` VALUES (36694, 'In this island is also found the rhinoceros, an animal less than the elephant, but larger than the buffalo.', 'n. [动]犀牛', '/rai\'nɔsərəs, ri- | raɪ\'nɒs(ə)rəs | raɪ\'nɑsərəs/', 'rhinoceros', 3);
INSERT INTO `words` VALUES (36695, 'The song has rhyming couplets (= pairs of lines that end in words that rhyme ) .', 'v. 押韵；和…同韵; n. 押韵； 同韵词， 押韵词', '/raɪm/', 'rhyme', 3);
INSERT INTO `words` VALUES (36696, 'Topaz occurs in the igneous rock rhyolite.', 'n. [地]流纹岩', '/\'raiəlait | \'raɪəlaɪt | \'raɪə,laɪt/', 'rhyolite', 3);
INSERT INTO `words` VALUES (36697, 'Drums are basic to African rhythm.', 'n. 节奏,韵律', '/\'riðəm, \'riθəm | \'rɪð(ə)m | \'rɪðəm/', 'rhythm', 3);
INSERT INTO `words` VALUES (36698, 'the rhythmic thud of the bass drum', 'adj. 节奏的, 合拍的', '/\'riðmik, \'riθ-/', 'rhythmic', 3);
