INSERT INTO `words` VALUES (36700, 'Metal rollers clank rhythmically inside the Imperial Distributors warehouse, as employees slide boxes packed with health and beauty products down the lines.', 'adv. 有节奏地', '/\'riðmikli/', 'rhythmically', 3);
