INSERT INTO `words` VALUES (37359, 'a sneaky little trick', 'adj. 偷偷摸摸的， 鬼鬼祟祟的', '/\'sniːki | \'sniki/', 'sneaky', 3);
INSERT INTO `words` VALUES (37360, 'There was a loud sneeze from someone in the back of the audience.', 'n. 喷嚏 vi打喷嚏', '/sni:z | sniːz | sniz/', 'sneeze', 3);
INSERT INTO `words` VALUES (37361, 'He made a snide comment about her weight.', 'adj. 伪造的； 不诚实的； 讽刺的， 挖苦的， 含沙射影的', '/snaɪd/', 'snide', 3);
INSERT INTO `words` VALUES (37362, 'I propose that every time an American bags a snipe, the federal government should pay him or her $100.', 'n. [鸟]鹬', '/snaip | snaɪp/', 'snipe', 3);
