INSERT INTO `words` VALUES (37366, 'Weller was once a stranded motorist himself. Driving in an Illinois blizzard when he was 16, he got stuck in a snowdrift.', 'n. 雪堆', '/\'snəudrift | \'snəʊdrɪft | \'snodrɪft/', 'snowdrift', 3);
INSERT INTO `words` VALUES (37367, 'Heavy snowfalls are forecast.', 'n. 降雪,降雪量', '/\'snəufɔ:l | \'snəʊfɔːl | \'snofɔl/', 'snowfall', 3);
INSERT INTO `words` VALUES (37368, 'Star join supports snowflake schema as well.', 'n. 雪花', '/\'snəufleik | \'snəʊfleɪk | \'snoflek/', 'snowflake', 3);
INSERT INTO `words` VALUES (37369, 'The snowstorm added to our difficulties.', 'n. 暴风雪', '/\'snəustɔ:m | \'snəʊstɔːm | \'snostɔrm/', 'snowstorm', 3);
INSERT INTO `words` VALUES (37370, 'the snowy fields', 'adj. 雪的, 多雪的', '/\'snəui | \'snəʊɪ | \'snoɪ/', 'snowy', 3);
