INSERT INTO `words` VALUES (37375, 'Adam’s smile sent her spirits soaring .', 'v. 高飞,昂扬; n. 高涨程度', '/sɔ: | sɔː | sɔr/', 'soar', 3);
INSERT INTO `words` VALUES (37376, 'He’s a nice guy when he’s sober.', 'adj. 清醒的，未醉的；持重的，冷静的；素净的; v. 清醒； 变得冷静', '/\'soubər | \'sobɚ/', 'sober', 3);
