INSERT INTO `words` VALUES (37380, 'She was, and remained, extremely sociable, enjoying dancing, golf, tennis, skating, and bicycling.', 'adj. 好交际的， 合群的； 友善的， 友好的', '/\'souʃəbl | \'soʃəbl/', 'sociable', 3);
INSERT INTO `words` VALUES (37381, 'Two women in widow\'s black touch his arm sociably as he passes the street corner where they sit singing folk songs to each other.', 'adv. 和蔼可亲地', '/\'səuʃəbli/', 'sociably', 3);
INSERT INTO `words` VALUES (37382, 'Schools play an important part in the socialization of our children.', 'n. 社会化, 社会主义化', '/,səuʃəlai-\'zeiʃən, -li\'z- | ,səʊʃəlaɪ\'zeɪʃən | ,soʃələ\'zeʃən/', 'socialization', 3);
INSERT INTO `words` VALUES (37383, '...an open meeting, where members socialized and welcomed any new members.', 'v. 使社会化, 使社会主义化', '/\'səuʃəlaiz | ˈsəʊʃəlaɪz | \'soʃəlaɪz/', 'socialize', 3);
INSERT INTO `words` VALUES (37384, NULL, 'adv. 社交上；社会上', '/\'səuʃəli | \'səʊʃəlɪ | \'soʃəli/', 'socially', 3);
INSERT INTO `words` VALUES (37385, 'The social science middle-ground, lately known as sociobiology, claims that we learn at least some specific cultural behaviors on the basis of biological need and evolution.', 'n. 生物社会学', '/,səusiəubai\'ɔlədʒi, -ʃi- | ,səʊsɪəʊbaɪ\'ɒlədʒɪ; ,səʊʃɪəʊ-/', 'sociobiology', 3);
INSERT INTO `words` VALUES (37386, 'The findings of this sociologist are very interesting because they illustrate once again the relationship that exists between what we do in the present and the results we obtain in the future.', 'n. 社会学家', '/,səusi\'ɔlədʒist, -ʃi- | ,səʊsɪ\'ɒlədʒɪst | ,sosɪ\'ɑlədʒɪst/', 'sociologist', 3);
INSERT INTO `words` VALUES (37387, 'Out with every theory of human behavior, from linguistics to sociology.', 'n. 社会学', '/,səusi\'ɔlədʒi, -ʃi- | səʊsɪ\'ɒlədʒɪ; səʊʃɪ- | ,sosɪ\'ɑlədʒi/', 'sociology', 3);
INSERT INTO `words` VALUES (37388, 'But why cover your car in sod?', 'n. 草地', '/sɔd | sɒd | sɑd/', 'sod', 3);
