INSERT INTO `words` VALUES (37393, 'Use moisturizer to soften your skin.', 'v. (使)变柔软,(使)变柔和', '/\'sɔfən, \'sɔ:- | \'sɒf(ə)n | \'sɔfn/', 'soften', 3);
