INSERT INTO `words` VALUES (37398, 'Each sculptural planter is made-to-order with handmade glass and lead-free solder and comes with everything you need but the plants.', 'n. 焊料; v. 焊接', '/\'sɔldə | \'səʊldə; \'sɒldə | \'sɑdɚ/', 'solder', 3);
