INSERT INTO `words` VALUES (37416, 'In the somber archives of a sedate museum a large archaic volume is somewhat conspicuously displayed.', 'adj. 昏暗的； 忧郁的', '/\'sɑːmbər | ˈsɑːmbər/', 'somber', 3);
