INSERT INTO `words` VALUES (37817, 'Michael Owen had to be substituted after 20 minutes on the field.', 'v. 代替,替换', '/\'sʌbstitju:t, -tu:t | \'sʌbstɪtjuːt | \'sʌbstɪtut/', 'substitute', 3);
