INSERT INTO `words` VALUES (37834, 'She wanted to be the first woman to climb Mount Qomolangma, and she almost succeeded.', 'v. 成功, 继承, 接着发生', '/sək\'si:d | sək\'siːd | sək\'sid/', 'succeed', 3);
