INSERT INTO `words` VALUES (37849, 'I suddenly realized that there was someone following me.', 'adv. 突然地', '/\'sʌdnli | \'sʌd(ə)nlɪ | \'sʌdənli/', 'suddenly', 3);
INSERT INTO `words` VALUES (37850, 'At least he died suddenly and didn’t suffer.', 'v. 遭受, 经历', '/\'sʌfə | \'sʌfɚ/', 'suffer', 3);
