INSERT INTO `words` VALUES (37864, 'The major components of PM are sulfate, nitrates, ammonia, sodium chloride, carbon, mineral dust and water.', 'n. 硫酸盐', '/\'sʌlfeit | \'sʌlfeɪt | \'sʌl,fet/', 'sulfate', 3);
INSERT INTO `words` VALUES (37865, '\"Show them a metal sulfide deposit on the seafloor and they think it\'s a six-course banquet, \" he joked.', 'n. <美>[化]硫化物', '/\'sʌlfaid | \'sʌlfaɪd | \'sʌl,faɪd/', 'sulfide', 3);
