INSERT INTO `words` VALUES (37879, 'Even if the air stays bitterly cold, these sunbaked rocks can warm enough to melt whatever tiny patches of snow have escaped the thirsty wind.', 'adj. 晒干的', '/\'sʌnbeikt | \'sʌnbeɪkt/', 'sunbaked', 3);
