INSERT INTO `words` VALUES (37897, 'belief in the supernatural', 'a&n. 超自然(的), 神奇(的)', '/,sju:pə\'nætʃərəl | ,suːpə\'nætʃ(ə)r(ə)l; ,sjuː- | ,supɚ\'nætʃrəl/', 'supernatural', 3);
INSERT INTO `words` VALUES (37898, 'In fact, the superorganism scenario is in a sense just the cosmic flip side of the diagnosis offered by Carr and other techno-skeptics.', 'n. [生]超个体(指群居昆虫等的群体)', '/,sjuːpə\'rɔːɡənɪzəm | ,sju:pə\'rɔ:ɡənizəm/', 'superorganism', 3);
INSERT INTO `words` VALUES (37899, 'we\'re being lured away by other people — people on Facebook, people in our inbox, people who write columns about giant superorganisms.', 'n. [生]超个体(指群居昆虫等的群体)', '/,sjuːpə\'rɔːɡənɪzəm | ,sju:pə\'rɔ:ɡənizəm/', 'superorganisms', 3);
INSERT INTO `words` VALUES (37900, 'Their map has since been superseded by photographic atlases.', 'v. 代替, 取代', '/,sju:pə\'si:d | ,suːpə\'siːd; ,sjuː- | ,supɚ\'sid/', 'supersede', 3);
