INSERT INTO `words` VALUES (37903, 'Griffiths closely supervised the research.', 'v. 监督, 管理', '/\'sju:pəvaiz | \'suːpəvaɪz; \'sjuː- | \'sʊpɚ\'vaɪz/', 'supervise', 3);
