INSERT INTO `words` VALUES (37905, '...a full-time job as a supervisor at a factory.', 'n. 管理人；监督人', '/\'sju:pəvaizə | \'suːpəvaɪzə; \'sjuː | \'supɚvaɪzɚ/', 'supervisor', 3);
