INSERT INTO `words` VALUES (37917, 'His version of events is pure supposition .', 'n. 假定, 想象', '/,sʌpə\'ziʃən | ,sʌpə\'zɪʃ(ə)n | ,sʌpə\'zɪʃən/', 'supposition', 3);
INSERT INTO `words` VALUES (37918, 'The uprising was ruthlessly suppressed.', 'v. 镇压,抑制', '/sə\'pres | sə\'prɛs/', 'suppress', 3);
INSERT INTO `words` VALUES (37919, 'Japan’s unchallenged supremacy in the field of electronics', 'n. 地位最高的人,至高,霸权', '/sju\'preməsi, sə- | s(j)uː\'preməsɪ | su\'prɛməsi/', 'supremacy', 3);
INSERT INTO `words` VALUES (37920, 'the Supreme Allied Commander in Europe', 'adj. 最高的, 至上的', '/sju\'pri:m, sə- | suː\'priːm | suˈprim/', 'supreme', 3);
INSERT INTO `words` VALUES (37921, NULL, 'adv. 无上地, 崇高地', '/su:\'pri:mli | su\'primli/', 'supremely', 3);
INSERT INTO `words` VALUES (37922, 'No person shall prior to leaving the paid area fail or refuse to pay any fare surcharge or other sum leviable in accordance with these by-laws .', 'n. 额外费用，增收费，附加费; vt. 收取额外费用', '/\'sɜːrtʃɑːrdʒ | \'sɝtʃɑrdʒ/', 'surcharge', 3);
INSERT INTO `words` VALUES (37923, '‘That’s Sarah’s cousin.’ ‘Are you sure?’', 'adj. 对有把握 ad的确, 当然', '/ʃuə, ʃɔ: | ʃɔ:(r) | ʃʊər; ʃʊr/', 'sure', 3);
INSERT INTO `words` VALUES (37924, 'She could feel anger surging inside her.', 'n&v. (波涛)汹涌,涌起', '/sɜːdʒ | sɝdʒ/', 'surge', 3);
INSERT INTO `words` VALUES (37925, '...a heart surgeon.', 'n. 外科医生', '/\'sə:dʒən | \'sɜːdʒ(ə)n | \'sɝdʒən/', 'surgeon', 3);
INSERT INTO `words` VALUES (37926, 'Dr. Hanson is in surgery.', 'n. 外科手术； 外科学； 手术室， 诊疗室', '/\'sɜːrdʒəri | \'sɝdʒəri/', 'surgery', 3);
INSERT INTO `words` VALUES (37927, 'There\'s so little to go on, we can only surmise what happened.', 'v. 猜测', '/\'sə:maiz, sə:\'maiz | sə\'maɪz | sɝ\'maɪz/', 'surmise', 3);
INSERT INTO `words` VALUES (37928, 'He has had to surmount immense physical disabilities.', 'v. 克服；置于…顶上', '/sə:\'maunt | sə\'maʊnt | sɚ\'maʊnt/', 'surmount', 3);
INSERT INTO `words` VALUES (37929, 'He had surpassed all our expectations .', 'v. 超越, 胜过', '/sə\'pɑ:s, -\'pæs | sə\'pɑːs | sə\'pæs/', 'surpass', 3);
INSERT INTO `words` VALUES (37930, 'Any surplus can be trimmed away.', 'n. 剩余,过剩', '/\'sə:plʌs, -pləs | \'sɜːpləs | \'sɝpləs/', 'surplus', 3);
INSERT INTO `words` VALUES (37931, 'The man had a look of surprise on his face.', 'n. 惊奇; v. 使惊奇', '/sə\'praiz | sə\'praɪz | sɚ\'praɪz/', 'surprise', 3);
INSERT INTO `words` VALUES (37932, 'Germany surrendered on May 7th, 1945.', 'v&n. 放弃, 投降', '/sə\'rendə | sə\'rɛndɚ/', 'surrender', 3);
INSERT INTO `words` VALUES (37933, 'He glared at the people who surrounded the tent.', 'v. 包围,环绕', '/sə\'raund | sə\'raʊnd/', 'surround', 3);
INSERT INTO `words` VALUES (37934, NULL, 'n. 围绕物,环境 a周围的', '/sə\'raundiŋ | sə\'raʊndɪŋ/', 'surrounding', 3);
INSERT INTO `words` VALUES (37935, 'Of the 100 companies surveyed, 10% had a turnover of £50 m to £99 m.', 'n&vt. 调查', '/sə:\'vei, \'sə:vei, sə- | ˈsəːveɪ; (for v.) səˈveɪ | ˈsɝˌve; (for v.) sɝˈve/', 'survey', 3);
INSERT INTO `words` VALUES (37936, '...the surveyor\'s maps of the Queen Alexandra Range.', 'n. 测量员, 检查员', '/sə\'veiə, sə:- | sə\'veɪə | sɚ\'veɚ/', 'surveyor', 3);
INSERT INTO `words` VALUES (37937, 'It is an important improvement in the survivability of the crew while maintaining the dynamics and payload of the aircrafts.', 'n. 残存性', '/,səvaivə\'biliti/', 'survivability', 3);
INSERT INTO `words` VALUES (37938, 'The doctors gave him a one in ten chance of survival .', 'n. 幸存,生存', '/sə\'vaivəl | sə\'vaɪv(ə)l | sɚ\'vaɪvl/', 'survival', 3);
INSERT INTO `words` VALUES (37939, 'Only 12 of the 140 passengers survived.', 'v. 活着,幸存', '/sə\'vaiv | sə\'vaɪv | sɚ\'vaɪv/', 'survive', 3);
INSERT INTO `words` VALUES (37940, 'Don’t worry about Kurt; he’s a survivor.', 'n. 生还者, 残存物', '/sə\'vaivə | sə\'vaɪvə | sɚ\'vaɪvɚ/', 'survivor', 3);
INSERT INTO `words` VALUES (37941, 'A lot of TV advertising is aimed at susceptible young children.', 'adj. 易受外界影响的,易受感染的', '/sə\'septəbl | sə\'septɪb(ə)l | sə\'sɛptəbl/', 'susceptible', 3);
INSERT INTO `words` VALUES (37942, 'She strongly suspected he was lying to her.', 'v. 推测,怀疑', '/sə\'spekt, \'sʌspekt | ˈsʌspekt; (for v.) səˈspekt | sʌspɛkt; (for v.) səˈspɛkt/', 'suspect', 3);
INSERT INTO `words` VALUES (37943, 'Sales of the drug will be suspended until more tests are completed.', 'v. 暂停,悬，挂', '/sə\'spend | sə\'spɛnd/', 'suspend', 3);
INSERT INTO `words` VALUES (37944, 'He also wore a pair of suspenders.', 'n. 吊裤带, 悬挂物, 吊杆, 袜吊', '/sə\'spendə | sə\'spɛndɚ/', 'suspender', 3);
INSERT INTO `words` VALUES (37945, 'Come on then, tell me what happened; the suspense is killing me (= I feel very excited or anxious because I do not know what will happen next ) .', 'n. 担心， 焦虑； 悬念， 不确定', '/sə\'spens | sə\'spɛns/', 'suspense', 3);
INSERT INTO `words` VALUES (37946, 'He received a six-month suspension for unprofessional behaviour.', 'n. 暂停, 中止', '/sə\'spenʃən | sə\'spenʃ(ə)n | sə\'spɛnʃən/', 'suspension', 3);
INSERT INTO `words` VALUES (37947, 'His conduct roused the suspicion of the police.', 'n. 猜疑, 怀疑', '/sə\'spiʃən | sə\'spɪʃ(ə)n | sə\'spɪʃən/', 'suspicion', 3);
INSERT INTO `words` VALUES (37948, 'His reluctance to answer my questions made me suspicious .', 'adj. 可疑的,多疑的', '/sə\'spiʃəs | sə\'spɪʃəs/', 'suspicious', 3);
INSERT INTO `words` VALUES (37949, 'She found it difficult to sustain the children’s interest.', 'v. 支撑,维持', '/sə\'stein | sə\'steɪn | sə\'sten/', 'sustain', 3);
INSERT INTO `words` VALUES (37950, 'The government should do more to promote sustainable agriculture.', 'adj. 不破坏生态平衡的， 可持续的； 足可支撑的； 可忍受的', '/sə\'steɪnəbl | sə\'stenəbl/', 'sustainable', 3);
INSERT INTO `words` VALUES (37951, 'Without sustenance, the animals will soon die.', 'n. 食物, 生计, (受)支持', '/\'sʌstenəns | \'sʌst(ə)nəns; -tɪn- | \'sʌstənəns/', 'sustenance', 3);
INSERT INTO `words` VALUES (37952, 'He swallowed the last of his coffee and asked for the bill.', 'n&v. 吞下,咽下', '/\'swɔləu | \'swɒləʊ | \'swɑlo/', 'swallow', 3);
INSERT INTO `words` VALUES (37953, 'I spent one whole night by a swamp behind the road listening to frogs.', 'n. 沼泽,湿地', '/swɔmp, swɔ:mp | swɒmp | swɑmp/', 'swamp', 3);
INSERT INTO `words` VALUES (37954, 'Alternatively, the dead could have been killed on the spot in \"the swampy valley environment\", the paper concludes.', 'adj. 沼泽的，似沼泽的', '/\'swɔmpi, \'swɔ:- | \'swɒmpɪ | \'swɔmpi/', 'swampy', 3);
INSERT INTO `words` VALUES (37955, 'Do you want to swap umbrellas?', 'v. 交换，掉换; n. 交换， 掉换； 交换物， 被调换者', '/swɑːp | swɑp/', 'swap', 3);
INSERT INTO `words` VALUES (37956, '...a swarm of locusts.', 'n. 蜂群, 一大群', '/swɔ:m | swɔːm | swɔrm/', 'swarm', 3);
INSERT INTO `words` VALUES (37957, 'The trees swayed gently in the breeze.', 'v&n. 摇摆, 支配', '/swei | sweɪ | swe/', 'sway', 3);
INSERT INTO `words` VALUES (37958, 'I never touched your purse, I swear!', 'v. 宣誓, 发誓', '/swεə | sweə | swɛr/', 'swear', 3);
INSERT INTO `words` VALUES (37959, 'Ian came off the squash court dripping with sweat .', 'n. 汗 v(使)出汗', '/swet | swɛt/', 'sweat', 3);
INSERT INTO `words` VALUES (37960, 'Her boy has never been to a doctor or a dentist, and last bathed when he was 2, so a sweatshop job by comparison would be far more pleasant and less dangerous.', 'n. 血汗工厂(指工人劳动条件差,工作时间长,工资低的工场或工厂)', '/\'swetʃɔp | \'swetʃɒp | \'swɛtʃɑp/', 'sweatshop', 3);
INSERT INTO `words` VALUES (37961, 'We came home hot and sweaty after the day’s work.', 'adj. 出汗的, 吃力的', '/\'sweti | \'swetɪ | \'swɛti/', 'sweaty', 3);
INSERT INTO `words` VALUES (37962, 'Sweden borders Norway and Finland.', 'n. 瑞典', '/\'swi:dən | \'swidən/', 'Sweden', 3);
INSERT INTO `words` VALUES (37963, 'Bert swept the path in front of the house.', 'v. 打扫, 清扫', '/swi:p | swiːp | swip/', 'sweep', 3);
INSERT INTO `words` VALUES (37964, 'sweeping generalizations about women drivers', 'adj. 彻底的，广泛的；〈贬〉笼统的，一概而论的; n. 清扫， 扫除； 垃圾', '/\'swiːpɪŋ | \'swipɪŋ/', 'sweeping', 3);
INSERT INTO `words` VALUES (37965, 'This tea is too sweet.', 'adj. 甜的', '/[swi:t] | swiːt | swit/', 'sweet', 3);
INSERT INTO `words` VALUES (37966, 'The river was swollen with melted snow.', 'v. (使)膨胀, 增大', '/swel | swɛl/', 'swell', 3);
INSERT INTO `words` VALUES (37967, 'My letter received a swift reply.', 'adj. 迅速的,敏捷的', '/swɪft/', 'swift', 3);
INSERT INTO `words` VALUES (37968, 'As I looked swiftly away, it seemed to me that his glance held some kind of unmet expectation.', 'adv. 很快地, 即刻', '/\'swiftli | \'swɪftli/', 'swiftly', 3);
INSERT INTO `words` VALUES (37969, 'The current financial and economic crisis is difficult to appreciate, not only for the drop in elevation, but because of the swiftness of the declines.', 'n. 迅速，敏捷', '/\'swiftnis/', 'swiftness', 3);
INSERT INTO `words` VALUES (37970, 'Let’s go swimming this afternoon.', 'n&v. 游泳', '/swim | swɪm/', 'swim', 3);
INSERT INTO `words` VALUES (37971, 'You don\'t have to worry about me. I\'m a good swimmer.', 'n. 游泳者', '/\'swimə | \'swɪmə | \'swɪmɚ/', 'swimmer', 3);
INSERT INTO `words` VALUES (37972, 'a big tax swindle', 'vt&n. 诈骗， 骗取', '/\'swɪndl | swɪndl/', 'swindle', 3);
INSERT INTO `words` VALUES (37973, 'Let your arms swing as you walk.', 'v. 摇摆, 摆动', '/swiŋ | swɪŋ/', 'swing', 3);
INSERT INTO `words` VALUES (37974, '...small swirls of chocolate cream.', 'n&v. 旋转，漩涡', '/swə:l | swɜːl | swɝl/', 'swirl', 3);
INSERT INTO `words` VALUES (37975, NULL, 'n. / a瑞士(的), 瑞士人(的)', '/swis | swɪs/', 'Swiss', 3);
INSERT INTO `words` VALUES (37976, 'Where’s the light switch ?', 'n. 开关 vt转换, 转变', '/switʃ | swɪtʃ/', 'switch', 3);
INSERT INTO `words` VALUES (37977, 'The River Rhine rises in Switzerland.', 'n. 瑞士(欧洲中部国家)', '/\'switsələnd | ˈswɪtsələnd | \'swɪtsələnd/', 'Switzerland', 3);
INSERT INTO `words` VALUES (37978, 'Virtually every woman in the \'20s swooned over Valentino.', 'vi&n. 昏厥， 昏倒； 痴迷', '/swu:n | swuːn/', 'swoon', 3);
INSERT INTO `words` VALUES (37979, 'The eagle hovered, ready to swoop at any moment.', 'v. 猛扑； 突然袭击; n. 突然行动', '/swuːp | swup/', 'swoop', 3);
INSERT INTO `words` VALUES (37980, 'The treaty hung like a sword of Damocles over French politics.', 'n. 剑', '/sɔ:d | sɔːd | sɔːrd/', 'sword', 3);
INSERT INTO `words` VALUES (37981, '...grilled swordfish with a yoghurt dressing.', 'n. 旗鱼', '/\'sɔːdfɪʃ | \'sɔrdfɪʃ/', 'swordfish', 3);
INSERT INTO `words` VALUES (37982, 'The accent falls on the third syllable.', 'n. 音节', '/\'siləbl | \'sɪləb(ə)l | \'sɪləbl/', 'syllable', 3);
INSERT INTO `words` VALUES (37983, 'The course syllabus consisted mainly of novels by African-American authors, male and female.', 'n. 教学大纲， 课程提纲', '/\'sɪləbəs/', 'syllabus', 3);
INSERT INTO `words` VALUES (37984, '...the link between bacteria, symbiosis, and the evolution of plants and animals.', 'n. [生]共生(现象),合作关系', '/,simbi\'əusis, -bai- | ,sɪmbɪ\'əʊsɪs; -baɪ- | ,sɪmbaɪ\'osɪs/', 'symbiosis', 3);
INSERT INTO `words` VALUES (37985, '...fungi that have a symbiotic relationship with the trees of these northwestern forests.', 'adj. 共生的', '/simbi\'ɔtik, -bai- | sɪmbaɪ\'ɒtɪk | sɪmbaɪ\'ɑtɪk/', 'symbiotic', 3);
INSERT INTO `words` VALUES (37986, 'The symbol on the packet is a guarantee that the food has been produced organically.', 'n. 符号,记号,象征', '/\'simbəl | \'sɪmb(ə)l | \'sɪmbl/', 'symbol', 3);
INSERT INTO `words` VALUES (37987, 'Each element of the ceremony has a symbolic meaning .', 'adj. 象征的,符号的', '/sim\'bɔlik | sɪm\'bɒlɪk | sɪm\'bɑlɪk/', 'symbolic', 3);
INSERT INTO `words` VALUES (37988, 'Say I have an online resource that I want you to symbolically pay for.', 'adv. 象征(性)地', '/sim\'bɔlikəli/', 'symbolically', 3);
INSERT INTO `words` VALUES (37989, 'religious symbolism', 'n. 象征主义', '/\'simbəlizəm | \'sɪmbəlɪz(ə)m | \'sɪmbəlɪzəm/', 'symbolism', 3);
INSERT INTO `words` VALUES (37990, 'Crime often symbolizes a wider social problem.', 'v. 象征', '/\'simbəlaiz | \'sɪmbəlaɪz/', 'symbolize', 3);
INSERT INTO `words` VALUES (37991, 'The pattern was perfectly symmetrical.', 'adj. 匀称的，对称的', '/si\'metrikəl | sɪ\'metrɪk(ə)l | sɪ\'mɛtrɪkl/', 'symmetrical', 3);
INSERT INTO `words` VALUES (37992, 'There was a certain symmetry to coming back to New York, where I started my artistic life all those years ago.', 'n. 对称； 相似， 相仿', '/\'sɪmətri/', 'symmetry', 3);
INSERT INTO `words` VALUES (37993, 'a sympathetic friend', 'adj. 同情的', '/,simpə\'θetik | sɪmpə\'θetɪk | ,sɪmpə\'θɛtɪk/', 'sympathetic', 3);
INSERT INTO `words` VALUES (37994, 'Our sympathies are with the families of the victims.', 'n. 同情, 同情心', '/\'simpəθi | \'sɪmpəθɪ | \'sɪmpəθi/', 'sympathy', 3);
INSERT INTO `words` VALUES (37995, 'Of course, anyone knows that it is impossible to play a symphonic work with just three strings.', 'adj. 交响乐的, 和声的', '/sim\'fɔnik | sɪm\'fɒnɪk | sɪm\'fɑnɪk/', 'symphonic', 3);
INSERT INTO `words` VALUES (37996, 'Bruckner’s Fifth Symphony', 'n. 交响乐, 交响曲', '/\'simfəni | \'sɪmf(ə)nɪ | \'sɪmfəni/', 'symphony', 3);
INSERT INTO `words` VALUES (37997, 'One of the most common symptoms of schizophrenia is hearing imaginary voices.', 'n. 症状, 征兆', '/\'simptəm | \'sɪm(p)təm | \'sɪmptəm/', 'symptom', 3);
INSERT INTO `words` VALUES (37998, NULL, 'n. [生]染色体结合, 突触', '/si\'næpsis | sɪ\'næpsɪs/', 'synapsis', 3);
INSERT INTO `words` VALUES (37999, 'What happens to systems not under the control of the synchronization service?', 'n. 同步化', '/,siŋkrənai\'zeiʃən, ,sin-, -ni\'z- | ,sɪŋkrənaɪ\'zeɪʃən | ,sɪnkrənaɪ\'zeʃən/', 'synchronization', 3);
INSERT INTO `words` VALUES (38000, 'It was virtually impossible to synchronize our lives so as to take vacations and weekends together.', 'v. 同步', '/\'siŋkrənaiz | \'sɪŋkrənaɪz/', 'synchronize', 3);
INSERT INTO `words` VALUES (38001, 'I created a background synchronizer that used RestKit as it seemed to have everything I needed.', 'n. 同步装置', '/\'siŋkrənaizə, \'sin- | \'sɪŋkrənaɪzər/', 'synchronizer', 3);
INSERT INTO `words` VALUES (38002, 'The synchrotron accelerator was built at Fermilab and the first patients were treated in 1990.', 'n. 同步加速器', '/\'siŋkrəutrɔn, \'sin- | \'sɪŋkrə(ʊ)trɒn/', 'synchrotron', 3);
INSERT INTO `words` VALUES (38003, 'people who suffer from irritable bowel syndrome', 'n. 综合病症', '/\'sɪndrəʊm | \'sɪndrəm/', 'syndrome', 3);
INSERT INTO `words` VALUES (38004, 'The term \"industrial democracy\" is often used as a synonym for worker participation.', 'n. 同义字', '/\'sinənim | \'sɪnənɪm | ˈsɪnənɪm/', 'synonym', 3);
INSERT INTO `words` VALUES (38005, '\"Getting fit\" became synonymous not just with healthier living, but with a leaner, meaner body, and the ground was laid for a burgeoning gym industry.', 'adj. 同义的', '/si\'nɔniməs | sɪ\'nɒnɪməs | sɪ\'nɑnɪməs/', 'synonymous', 3);
INSERT INTO `words` VALUES (38006, 'syntactic structure', 'adj. 句法的； 按照句法的', '/sɪn\'tæktɪk/', 'syntactic', 3);
INSERT INTO `words` VALUES (38007, 'His grammar and syntax, both in oral and written expression, were much better than the average.', 'n. 语法, 句法', '/\'sintæks | \'sɪntæks/', 'syntax', 3);
INSERT INTO `words` VALUES (38008, 'DDT is a pesticide that was first synthesized in 1874.', 'v. 综合, 合成', '/\'sinθisaiz | \'sɪnθəsaɪz/', 'synthesize', 3);
INSERT INTO `words` VALUES (38009, 'Now he can only communicate through a voice synthesizer.', 'n. 综合者, [电子]合成器', '/\'sinθisaizə | \'sɪnθəsaɪzɚ/', 'synthesizer', 3);
INSERT INTO `words` VALUES (38010, 'synthetic chemicals', 'adj. 合成的, 综合的', '/sin\'θetik | sɪn\'θetɪk | sɪn\'θɛtɪk/', 'synthetic', 3);
INSERT INTO `words` VALUES (38011, 'ice cream and maple syrup', 'n. 糖浆, 果汁', '/\'sirəp, \'sə:- | \'sɪrəp/', 'syrup', 3);
INSERT INTO `words` VALUES (38012, 'What about all other systematic knowledge?', 'adj. 系统的,体系的', '/sɪstə\'mætɪk | \'sɪstə\'mætɪk/', 'systematic', 3);
INSERT INTO `words` VALUES (38013, 'Rumours of possible human cases in other parts of the country have been systematically followed up.', 'adv. 有系统地, 有条理地', '/,sistə\'mætikəli | ,sɪstə\'mætɪklɪ | ,sɪstə\'mætɪkl/', 'systematically', 3);
INSERT INTO `words` VALUES (38014, 'This basic plugin is undoubtedly one of the important plugins to systematize the archives.', 'v. 系统化', '/\'sistimətaiz | \'sɪstəmə,taɪz | \'sɪstəmətaɪz/', 'systematize', 3);
INSERT INTO `words` VALUES (38015, 'The food was served on long tables.', 'n. 桌子,表格', '/\'teibl | \'teɪb(ə)l | \'tebl/', 'table', 3);
INSERT INTO `words` VALUES (38016, 'The northwestern tableland area has a continental plateau climate with long and chilly winter and cool humid summer.', 'n. 高原', '/teibllænd | \'teɪb(ə)llænd | \'tebllænd/', 'tableland', 3);
INSERT INTO `words` VALUES (38017, 'She took a couple of headache tablets .', 'n. 药片', '/\'tæblɪt | \'tæblət/', 'tablet', 3);
INSERT INTO `words` VALUES (38018, 'Rape is a taboo subject .', 'adj. 忌讳的; n. 禁忌，忌讳；禁止，避讳', '/tə\'buː | tə\'bu/', 'taboo', 3);
INSERT INTO `words` VALUES (38019, 'Results for the test programme haven\'t been tabulated.', 'v. 把制成表格', '/\'tæbjuleit, \'tæbju-lit, -leit | \'tæbjʊleɪt | \'tæbjulet/', 'tabulate', 3);
INSERT INTO `words` VALUES (38020, 'There is more than one way to tackle the problem.', 'v. 对付，处理；阻截；抢球; n. 拦截； 用具', '/\'tækl/', 'tackle', 3);
INSERT INTO `words` VALUES (38021, NULL, 'n. 机智, 手法', '/tækt/', 'tact', 3);
INSERT INTO `words` VALUES (38022, 'You have probably heard of this tactic before.', 'n. 策略, 战略', '/\'tæktik | \'tæktɪk/', 'tactic', 3);
