INSERT INTO `words` VALUES (38491, 'It was decided by a unanimous vote that the school should close.', 'adj. 全体一致的， 一致同意的', '/ju\'nænɪməs | jʊ\'nænəməs/', 'unanimous', 3);
INSERT INTO `words` VALUES (38492, 'Many other questions remain unanswered.', 'adj. 未答复的,无反应的', '/ʌn\'a:nsəd | ʌn\'ɑːnsəd | ʌn\'ɑnsɚd/', 'unanswered', 3);
INSERT INTO `words` VALUES (38493, 'an unanticipated increase in inflation', 'adj. 不曾预料到的', '/\'ʌnæn\'tisipeitid/', 'unanticipated', 3);
INSERT INTO `words` VALUES (38494, 'an unattractive man', 'adj. 无魅力的, 无吸引力的', '/,ʌnə\'træktiv | ʌnə\'træktɪv | ,ʌnə\'træktɪv/', 'unattractive', 3);
INSERT INTO `words` VALUES (38495, 'Funding for the new school is unavailable.', 'adj. 难以获得的', '/\'ʌnə\'veiləbl | ʌnə\'veɪləb(ə)l | \'ʌnə\'veləbl/', 'unavailable', 3);
INSERT INTO `words` VALUES (38496, 'There are now fears that war is unavoidable.', 'adj. 不可避免的', '/,ʌnə\'vɔidəbl | ʌnə\'vɒɪdəb(ə)l | ,ʌnə\'vɔɪdəbl/', 'unavoidable', 3);
INSERT INTO `words` VALUES (38497, 'The conflict of the class interests results in the pitiless class-struggle that unavoidably leads to the victory of the most numerous and most wronged class, the proletariat.', 'adv. 不可避免地,不得已地', '/,ʌnə\'vɔidəbli/', 'unavoidably', 3);
INSERT INTO `words` VALUES (38498, 'Many people are unaware of just how much food and drink they consume.', 'adj. 不知道的, 没觉察到的', '/,ʌnə\'wεə | ʌnə\'weə | ,ʌnə\'wɛr/', 'unaware', 3);
INSERT INTO `words` VALUES (38499, 'He banged against the cupboard, unbalancing a pile of books.', 'v. 使失衡,使精神紊乱n失衡', '/,ʌn\'bæləns | ʌn\'bæl(ə)ns | \'ʌn\'bæləns/', 'unbalance', 3);
INSERT INTO `words` VALUES (38500, 'It is unbelievable, but I like that.', 'adj. 难以置信的', '/,ʌnbi\'li:vəbl | ʌnbɪ\'liːvəb(ə)l | ,ʌnbɪ\'livəbl/', 'unbelievable', 3);
INSERT INTO `words` VALUES (38501, 'We aim to provide a service that is balanced and unbiased.', 'adj. 公正的', '/,ʌn\'baiəst | ʌn\'baɪəst/', 'unbiased', 3);
INSERT INTO `words` VALUES (38502, 'She unbound her hair and let it flow loose in the wind.', 'v. 解开, 解放', '/,ʌn\'baind | ʌn\'baɪnd/', 'unbind', 3);
INSERT INTO `words` VALUES (38503, 'unbreakable glass', 'adj. 不易破碎的, 牢不可破的', '/un\'breikəbəl | ʌn\'breɪkəb(ə)l | ʌn\'brekəbl/', 'unbreakable', 3);
INSERT INTO `words` VALUES (38504, '...the so-called unbridgeable gap between the world of humans and that of chimpanzees.', 'adj. 不能架桥的,不能逾越的', '/\'ʌn\'bridʒəbl/', 'unbridgeable', 3);
INSERT INTO `words` VALUES (38505, 'their unbroken record of success', 'adj. 不间断的', '/,ʌn\'brəukən | ʌn\'brəʊk(ə)n | ʌn\'brokən/', 'unbroken', 3);
INSERT INTO `words` VALUES (38506, 'an uncanny coincidence', 'adj. 神秘的； 易乎寻常的', '/ʌn\'kæni/', 'uncanny', 3);
INSERT INTO `words` VALUES (38507, 'One day, a man named He Shi of the State of Chu got a piece of uncarved jade in a hill. He quickly went to present it to King Li of the State of Chu.', 'adj. 没雕刻的', NULL, 'uncarved', 3);
INSERT INTO `words` VALUES (38508, 'My whole future now seemed uncertain.', 'adj. 不确定的,不稳定的,', '/,ʌn\'sə:tən | ʌn\'sɜːt(ə)n; -tɪn | ʌn\'sɝtn/', 'uncertain', 3);
INSERT INTO `words` VALUES (38509, '...a period of political uncertainty.', 'n. 无常, 不确定', '/,ʌn\'sə:tənti | ʌn\'sɜːt(ə)ntɪ; -tɪntɪ | ʌn\'sɝtnti/', 'uncertainty', 3);
INSERT INTO `words` VALUES (38510, 'The doctrine is unchangeable.', 'adj. 不变的,不能改变的', '/ʌn\'tʃeindʒəbl | ʌn\'tʃeɪn(d)ʒəb(ə)l/', 'unchangeable', 3);
INSERT INTO `words` VALUES (38511, '...eternal and unchanging truths.', 'adj. 不变的', '/ʌn\'tʃeindʒiŋ | ʌn\'tʃeɪn(d)ʒɪŋ | ʌn\'tʃendʒɪŋ/', 'unchanging', 3);
INSERT INTO `words` VALUES (38512, 'an uncharted island', 'adj. 地图上没标明的,未知的', '/,ʌn\'tʃɑ:tid | ʌn\'tʃɑːtɪd | ,ʌn\'tʃɑrtɪd/', 'uncharted', 3);
INSERT INTO `words` VALUES (38513, 'I went to stay with my uncle and aunt for a few days.', 'n. 伯父,叔父,援助者', '/\'ʌŋkl | \'ʌŋk(ə)l/', 'uncle', 3);
INSERT INTO `words` VALUES (38514, 'The terms of the contract are very unclear.', 'adj. 不清楚的', '/ʌn\'kliə | ʌn\'klɪə | ,ʌn\'klɪr/', 'unclear', 3);
INSERT INTO `words` VALUES (38515, 'This sofa is so uncomfortable.', 'adj. 不舒服的，不自在的', '/,ʌn\'kɔmfətəbl | ʌn\'kʌmf(ə)təb(ə)l | ʌn\'kʌmftəbl/', 'uncomfortable', 3);
INSERT INTO `words` VALUES (38516, 'Violent crimes against the elderly are fortunately very uncommon.', 'adj. 不凡的, 难得的', '/,ʌn\'kɔmən | ʌn\'kɒmən | ʌn\'kɑmən/', 'uncommon', 3);
INSERT INTO `words` VALUES (38517, NULL, 'adj. 非竞争性的', '/,ʌnkəm\'petitiv | ʌnkəm\'petɪtɪv/', 'uncompetitive', 3);
INSERT INTO `words` VALUES (38518, 'He unconsciously switched a tree with his cane when he talked to her.', 'adv. 无意识地；不觉察地', '/ʌn\'kɔnʃəsli | ʌn\'kɑnʃəsli/', 'unconsciously', 3);
INSERT INTO `words` VALUES (38519, 'A series of defects exist in the cup circulation pack sand control tools and slip filling sand control tools currently used in Binnan unconsolidated sandstone reservoir.', 'adj. 松散的， 疏松的', '/\'ʌnkən\'sɔlideitid | ˌʌnkən\'sɑːlɪdeɪtɪd/', 'unconsolidated', 3);
INSERT INTO `words` VALUES (38520, 'After an uncontested divorce, Peggy married Charlie.', 'adj. 无争论的, 无异议的', '/\'ʌnkən\'testid | ʌnkən\'testɪd | ,ʌnkən\'tɛstɪd/', 'uncontested', 3);
INSERT INTO `words` VALUES (38521, 'This means your blood does not clot and you will bleed uncontrollably.', 'adj. 无法管束的, 控制不住的', '/,ʌnkən\'trəuləbli/', 'uncontrollably', 3);
INSERT INTO `words` VALUES (38522, 'Linus Pauling is an unconventional genius.', 'adj. 非传统的, 不合惯例的', '/,ʌnkən\'venʃənəl | ʌnkən\'venʃ(ə)n(ə)l | ,ʌnkən\'vɛnʃənl/', 'unconventional', 3);
INSERT INTO `words` VALUES (38523, 'Always wash your hands after handling uncooked meat.', 'adj. 未煮过的', '/,ʌn\'kukt | ʌn\'kʊkt | ,ʌn\'kʊkt/', 'uncooked', 3);
INSERT INTO `words` VALUES (38524, 'She became uncooperative: unwilling to do her homework or help with any household chores.', 'adj. 不合作的, 不配合的', '/\'ʌnkəu\'ɔpərətiv | ʌnkəʊ\'ɒp(ə)rətɪv | ,ʌnko\'ɑpərətɪv/', 'uncooperative', 3);
INSERT INTO `words` VALUES (38525, 'We filmed there this summer, and it is deeply touching to see that Collins not only ran a rare, uncorrupt and democratic camp, but had put up a schoolhouse, a library and a meeting hall.', 'adv. 不腐败的;廉洁的', '/\'ʌnkə\'rʌpt/', 'uncorrupt', 3);
INSERT INTO `words` VALUES (38526, 'This arrangement is no different from one where the voter casts a symbolic vote, a vote that remains uncounted, with the outcome already determined by the whims of the tyrant.', 'adj. 无数的,没有数过的', '/,ʌn\'kauntid | ʌn\'kaʊntɪd/', 'uncounted', 3);
INSERT INTO `words` VALUES (38527, 'Customs officials uncovered a plot to smuggle weapons into the country.', 'v. 揭露，揭示', '/,ʌn\'kʌvə | ʌn\'kʌvə | ʌn\'kʌvɚ/', 'uncover', 3);
INSERT INTO `words` VALUES (38528, '...the conventional notion of women as uncritical purchasers of heavily advertised products.', 'adj. 无批判力的,不加批判的', '/,ʌn\'kritikəl | ʌn\'krɪtɪk(ə)l | ,ʌn\'krɪtɪkl/', 'uncritical', 3);
INSERT INTO `words` VALUES (38529, NULL, 'vt. 去掉…的皱纹,使回复到平整状态', '/ʌn\'krʌmpl/', 'uncrumple', 3);
INSERT INTO `words` VALUES (38530, 'After college she was still undecided as to what career she wanted to pursue.', 'adj. 未定的, (天气等)不稳定的', '/,ʌndi\'saidid | ʌndɪ\'saɪdɪd | ,ʌndɪ\'saɪdɪd/', 'undecided', 3);
INSERT INTO `words` VALUES (38531, 'undeniable proof', 'adj. 不可否认的, 无可辩驳的', '/,ʌndi\'naiəbl | ʌndɪ\'naɪəb(ə)l | \'ʌndɪ\'naɪəbl/', 'undeniable', 3);
INSERT INTO `words` VALUES (38532, 'Fourteen percent may be an underestimate.', 'vt& n. 估计不足，低估', '/,ʌndə\'estimeit | ʌndər\'estɪmeɪt | /ˌʌndərˈestɪmeɪt//', 'underestimate', 3);
INSERT INTO `words` VALUES (38533, '...a room, high and square with carpet underfoot and tapestries on the walls.', 'adv. 在脚下面, 踩着地', '/,ʌndə\'fut | ʌndə\'fʊt | ,ʌndɚ\'fʊt/', 'underfoot', 3);
INSERT INTO `words` VALUES (38534, 'The country has undergone massive changes recently.', 'v. 经历,遭受', '/,ʌndə\'ɡəu | ʌndə\'gəʊ | ,ʌndɚ\'ɡo/', 'undergo', 3);
INSERT INTO `words` VALUES (38535, 'second-year undergraduates', 'n. (尚未取得学位的)大学生', '/,ʌndə\'ɡrædjuət | ʌndə\'grædjʊət | ,ʌndɚ\'ɡrædʒuət/', 'undergraduate', 3);
INSERT INTO `words` VALUES (38536, 'an underground passage', 'adj. 地下的,地面下的', '/\'ʌndəɡraund | ʌndə\'graʊnd | ʌndɚˈɡraʊnd/', 'underground', 3);
INSERT INTO `words` VALUES (38537, 'the one basic principle that underlies all of the party’s policies', 'v. 位于之下, 成为的基础', '/,ʌndə\'lai | ʌndə\'laɪ | ,ʌndɚ\'laɪ/', 'underlie', 3);
INSERT INTO `words` VALUES (38538, 'Try to figure out what feeling underlies your anger.', 'v. 位于之下, 成为的基础', '/,ʌndə\'lai | ʌndə\'laɪ | ,ʌndɚ\'laɪ/', 'underlies', 3);
INSERT INTO `words` VALUES (38539, 'To stop a problem you have to understand its underlying causes.', 'adj. 潜在的； 基础的', '/ˌʌndər\'laɪɪŋ | ,ʌndɚ\'laɪɪŋ/', 'underlying', 3);
INSERT INTO `words` VALUES (38540, 'The continued fighting threatens to undermine efforts to negotiate an agreement.', 'v. 破坏', '/,ʌndə\'main | ʌndə\'maɪn | \'ʌndɚ\'maɪn/', 'undermine', 3);
INSERT INTO `words` VALUES (38541, 'He has on his jeans and a long-sleeved blue denim shirt with a white T-shirt underneath.', 'adv. 在下面 prep在的下面', '/,ʌndə\'ni:θ | ʌndə\'niːθ | ,ʌndɚ\'niθ/', 'underneath', 3);
INSERT INTO `words` VALUES (38542, 'Does this mean that all GM foods are fated never to solve the undernutrition of the poor?', 'n. 营养不良', '/,ʌndənjuː\'trɪʃən | ,ʌndənʊ\'trɪʃən; ,ʌndənjʊ\'trɪʃən/', 'undernutrition', 3);
INSERT INTO `words` VALUES (38543, 'The Labour Department figures underscore the shaky state of the economic recovery.', 'v. 画底线', '/,ʌndə\'skɔ:, \'ʌndəskɔ: | ʌndə\'skɔː | ,ʌndɚ\'skɔr/', 'underscore', 3);
INSERT INTO `words` VALUES (38544, 'It is understandable that parents are angry, and looking for someone to blame.', 'adj. 可理解的,能够懂的', '/,ʌndə\'stændəbl | ʌndə\'stændəbl | \'ʌndɚ\'stændəbl/', 'understandable', 3);
INSERT INTO `words` VALUES (38545, 'Some parents, understandably, have a very hard time with this one. They may feel that anything their kids do is their business.', 'adv. 可理解地', '/,ʌndə\'stændəbli/', 'understandably', 3);
INSERT INTO `words` VALUES (38546, 'The press have tended to understate the extent of the problem.', 'v. 打着折扣说,有意轻描淡写', '/,ʌndə\'steit | ʌndə\'steɪt | \'ʌndɚ\'stet/', 'understate', 3);
INSERT INTO `words` VALUES (38547, 'Wild sarsaparilla, wild oats, Solomon\'s seal and a host of understory plants die off;', 'n. 林下叶层', '/\'ʌndə,stɔ:ri | \'ʌndɚ,stɔri; \'ʌndɚ,stori/', 'understory', 3);
INSERT INTO `words` VALUES (38548, 'She undertook the task of monitoring the elections.', 'v. 承担,采取', '/,ʌndə\'teik | ʌndə\'teɪk | ,ʌndɚ\'tek/', 'undertake', 3);
INSERT INTO `words` VALUES (38549, 'Starting a new business can be a risky undertaking.', 'n. 任务， 项目； 事业， 企业； 承诺， 保证', '/ˌʌndər\'teɪkɪŋ | \'ʌndɚ\'tekɪŋ/', 'undertaking', 3);
INSERT INTO `words` VALUES (38550, '...underwater exploration.', 'adj. 在水中生长的', '/\'ʌndə\'wɔ:tə | ʌndə\'wɔːtə | ,ʌndɚ\'wɔtɚ/', 'underwater', 3);
INSERT INTO `words` VALUES (38551, NULL, 'n. 后翅, 后翅色彩瑰丽的蛾', '/\'ʌndəwiŋ | \'ʌndəwɪŋ/', 'underwing', 3);
INSERT INTO `words` VALUES (38552, 'New York’s criminal underworld', 'n. 黑社会', '/\'ʌndəwə:ld | \'ʌndəwɜːld | \'ʌndɚ\'wɝld/', 'underworld', 3);
INSERT INTO `words` VALUES (38553, 'punishment of undesirable behaviour', 'adj. 令人不悦的，讨厌的', '/,ʌndi\'zaiərəbl | ʌndɪ\'zaɪərəb(ə)l | ,ʌndɪ\'zaɪərəbl/', 'undesirable', 3);
INSERT INTO `words` VALUES (38554, 'an undeveloped stretch of coastline', 'adj. 不发达的, 未开发的', '/,ʌndi\'veləpt | ʌndɪ\'veləpt | ,ʌndɪ\'vɛləpt/', 'undeveloped', 3);
INSERT INTO `words` VALUES (38555, 'shows aimed at large undifferentiated groups of people', 'adj. 无差别的, 一致的', '/,ʌndifə\'renʃieitid | ,ʌndɪfə\'renʃɪeɪtɪd | \'ʌndɪfə\'rɛnʃɪ\'etɪd/', 'undifferentiated', 3);
INSERT INTO `words` VALUES (38556, 'The name Vulcan was given to the undiscovered planet.', 'adj. 未被发现的', '/\'ʌndis\'kʌvəd | ʌndɪ\'skʌvəd/', 'undiscovered', 3);
INSERT INTO `words` VALUES (38557, 'Doctors found undisputed evidence of nerve damage.', 'adj. 无可置辩的', '/,ʌndis\'pju:tid | ʌndɪ\'spjuːtɪd | ,ʌndɪ\'spjutɪd/', 'undisputed', 3);
INSERT INTO `words` VALUES (38558, 'At last I was able to work undisturbed.', 'adj. 未受干扰的', '/,ʌndi\'stə:bd | ʌndɪ\'stɜːbd | ,ʌndɪ\'stɝbd/', 'undisturbed', 3);
INSERT INTO `words` VALUES (38559, NULL, 'adv. 无庸置疑地,的确地', '/ʌn\'daʊtɪdlɪ | ʌn\'daʊtɪdli/', 'undoubtedly', 3);
INSERT INTO `words` VALUES (38560, 'The abolition of incomes unearned by work.', 'adj. 不劳而获的', '/,ʌn\'ə:nd | ʌn\'ɜːnd | ,ʌn\'ɝnd/', 'unearned', 3);
INSERT INTO `words` VALUES (38561, 'Farmers still sometimes unearth human bones here.', 'v. 掘出', '/,ʌn\'ə:θ | ʌn\'ɜːθ | ʌn\'ɝθ/', 'unearth', 3);
INSERT INTO `words` VALUES (38562, 'a largely uneducated workforce', 'adj. 没受教育的；文盲的', '/,ʌn\'edjukeitid | ʌn\'edjʊkeɪtɪd | ʌn\'ɛdʒuketɪd/', 'uneducated', 3);
INSERT INTO `words` VALUES (38563, 'an unemployed actor', 'adj. 失业的, 未被利用的', '/,ʌnim\'plɔid | ʌnɪm\'plɒɪd; -em- | ,ʌnɪm\'plɔɪd/', 'unemployed', 3);
INSERT INTO `words` VALUES (38564, 'a town where there is high unemployment', 'n. 失业, 失业人数', '/,ʌnim\'plɔimənt | ʌnɪm\'plɒɪm(ə)nt; -em- | ,ʌnɪm\'plɔɪmənt/', 'unemployment', 3);
INSERT INTO `words` VALUES (38565, 'an unending stream of people', 'adj. 不断的, 不断重复的', '/ʌn\'endiŋ | ʌn\'endɪŋ | ʌn\'ɛndɪŋ/', 'unending', 3);
INSERT INTO `words` VALUES (38566, 'an unequal contest', 'adj. 不同的， 不相等的； 不平等的， 不相称的； 不胜任的', '/ʌn\'iːkwəl | ʌn\'ikwəl/', 'unequal', 3);
INSERT INTO `words` VALUES (38567, 'She walked back carefully over the uneven ground.', 'adj. 不平坦的,不均匀的', '/,ʌn\'i:vən | ʌn\'iːv(ə)n | ʌn\'ivən/', 'uneven', 3);
INSERT INTO `words` VALUES (38568, NULL, 'adv. 不平坦地, 不均衡地', '/\'ʌn\'i:vənli | ʌn\'ivənli/', 'unevenly', 3);
INSERT INTO `words` VALUES (38569, 'The experiment produced some unexpected results.', 'adj. 想不到的,意外的', '/,ʌnik\'spektid | ʌnɪk\'spektɪd; ʌnek- | \'ʌnɪk\'spɛktɪd/', 'unexpected', 3);
INSERT INTO `words` VALUES (38570, NULL, 'adv. 出乎意料地,意外地', '/\'ʌnik\'spektidli/', 'unexpectedly', 3);
INSERT INTO `words` VALUES (38571, 'unexplored planets', 'adj. [地质] 未勘查过的', '/\'ʌniks\'plɔ:d | ʌnɪk\'splɔːd; ʌnek- | ,ʌnɪk\'splɔrd/', 'unexplored', 3);
INSERT INTO `words` VALUES (38572, NULL, 'adv. 无穷尽地, 可靠地', '/ʌn\'feiliŋli/', 'unfailingly', 3);
INSERT INTO `words` VALUES (38573, 'an unfair advantage', 'adj. 不公平的', '/,ʌn\'fεə | ʌn\'feə | \'ʌn\'fɛr/', 'unfair', 3);
INSERT INTO `words` VALUES (38574, 'And that\'s going to require some very hard choices. And we\'re going to have to do that in a way that does not add unfairly to the burdens that the average American already faces.', 'adv. 不公平地,不正当地', '/ʌn\'fɛəli/', 'unfairly', 3);
INSERT INTO `words` VALUES (38575, 'a crowd of unfamiliar faces', 'adj. 不熟悉的', '/,ʌnfə\'miljə | ʌnfə\'mɪlɪə | ,ʌnfə\'mɪlɪɚ/', 'unfamiliar', 3);
INSERT INTO `words` VALUES (38576, NULL, 'adv. 不利地,不适宜地', '/ʌn\'feivərəbli/', 'unfavorably', 3);
INSERT INTO `words` VALUES (38577, 'an unfertilized ovum', 'adj. 未施肥的, 未受精的', '/ʌn\'fɜːtɪlaɪzd/', 'unfertilized', 3);
INSERT INTO `words` VALUES (38578, 'The discussion was becom­ing unfocused.', 'adj. 未聚焦的,无焦点的', '/,ʌn\'fəukəst/', 'unfocused', 3);
INSERT INTO `words` VALUES (38579, 'As the story unfolds, we learn more about Max’s childhood.', 'v. 展开,显露，展现', '/,ʌn\'fəuld | ʌn\'fəʊld | ʌn\'fold/', 'unfold', 3);
INSERT INTO `words` VALUES (38580, 'Radiation may damage cells in a way that was previously unforeseen.', 'adj. 无法预料的', '/,ʌnfɔ:\'si:n | ʌnfɔː\'siːn | ,ʌnfɔr\'sin/', 'unforeseen', 3);
INSERT INTO `words` VALUES (38581, 'When we entered the room, the teacher was yelling at some unfortunate student.', 'adj. 不幸的', '/,ʌn\'fɔ:tʃənət | ʌn\'fɔːtʃ(ə)nət | ʌn\'fɔrtʃənət/', 'unfortunate', 3);
INSERT INTO `words` VALUES (38582, 'Unfortunately, you were out when we called.', 'adv. 不幸地, 遗憾地', '/ʌn\'fɔ:tʃənətli | ʌnˈfɔːtʃənətli | ʌn\'fɔrtʃənətli/', 'unfortunately', 3);
INSERT INTO `words` VALUES (38583, 'If you’re so unhappy, why don’t you change jobs?', 'adj. 不幸的, 不快乐的', '/,ʌn\'hæpi | ʌn\'hæpɪ | ʌn\'hæpi/', 'unhappy', 3);
INSERT INTO `words` VALUES (38584, 'he could proceed unhindered', 'adj. 无阻的, 不受阻碍的', '/ʌn\'hindəd | ʌn\'hɪndəd | ʌn\'hɪndɚd/', 'unhindered', 3);
INSERT INTO `words` VALUES (38585, 'The police wear dark blue uniforms.', 'n. 制服; v. 使统一', '/\'ju:nifɔ:m | \'juːnɪfɔːm | \'junɪfɔrm/', 'uniform', 3);
INSERT INTO `words` VALUES (38586, NULL, 'n. [地质]均变论', '/,juːnɪfɔːmɪ\'teərɪənɪʒ(ə)m | ,jʊnə,fɔrmə\'tɛrɪən,ɪzm/', 'uniformitarianism', 3);
INSERT INTO `words` VALUES (38587, 'There seems to be no uniformity among the various systems.', 'n. 一致,均匀', '/,ju:ni\'fɔ:məti | juːnɪ\'fɔːmɪtɪ | ,jʊnə\'fɔrməti/', 'uniformity', 3);
INSERT INTO `words` VALUES (38588, 'Strong support for the war has unified the nation.', 'v. 统一,使成一体', '/\'ju:nifai | \'juːnɪfaɪ | \'junɪfaɪ/', 'unify', 3);
INSERT INTO `words` VALUES (38589, 'unimaginable wealth', 'adj. 不能想象的, 想象不到的', '/,ʌni\'mædʒinəbl | ʌnɪ\'mædʒɪnəb(ə)l | ,ʌnɪ\'mædʒɪnəbl/', 'unimaginable', 3);
INSERT INTO `words` VALUES (38590, 'unimportant details', 'adj. 不重要的', '/,ʌnim\'pɔ:tnt | ʌnɪm\'pɔːt(ə)nt | \'ʌnɪm\'pɔrtnt/', 'unimportant', 3);
