INSERT INTO `words` VALUES (38592, 'Much of the country is uninhabitable because it is desert.', 'adj. 不适宜居住的', '/,ʌnin\'hæbitəbl | ʌnɪn\'hæbɪtəb(ə)l | ,ʌnɪn\'hæbɪtəbl/', 'uninhabitable', 3);
INSERT INTO `words` VALUES (38593, 'an uninhabited island', 'adj. 无人居住的,杳无人迹的', '/\'ʌnin\'hæbitid | ʌnɪn\'hæbɪtɪd | ,ʌnɪn\'hæbɪtɪd/', 'uninhabited', 3);
INSERT INTO `words` VALUES (38594, NULL, 'adv. 无意地,非故意地', '/,ʌnin\'tenʃənəli | ʌnɪnˈtɛnʃ(ə)n(ə)li | ˌʌnɪn\'tenʃənəli/', 'unintentionally', 3);
INSERT INTO `words` VALUES (38595, 'Their media have earned the reputation for being rather dull and uninteresting.', 'adj. 无趣味的，乏味的', '/\'ʌn\'intristiŋ | ʌn\'ɪnt(ə)rɪstɪŋ | ʌn\'ɪntrəstɪŋ/', 'uninteresting', 3);
INSERT INTO `words` VALUES (38596, 'uninterrupted sleep', 'adj. 不停的, 连续的', '/\'ʌn,intə\'rʌptid | ,ʌnɪntə\'rʌptɪd | ,ʌn,ɪntə\'rʌptɪd/', 'uninterrupted', 3);
INSERT INTO `words` VALUES (38597, 'the British Golf Union', 'n. 联合,联盟', '/\'ju:niən | \'juːnjən; -ɪən | \'junɪən/', 'union', 3);
INSERT INTO `words` VALUES (38598, 'During the past 40 years, the fraction of unionized civilian workers fell steeply-and not only in the United States- while the unionization of government workers fell only a little.', 'n. 联合, 结合', '/,ju:njənai\'zeiʃən, -ni\'z-/', 'unionization', 3);
INSERT INTO `words` VALUES (38599, 'a unique opportunity to study these rare creatures', 'adj. 唯一的,独特的', '/ju:\'ni:k | juː\'niːk | jʊ\'nik/', 'unique', 3);
INSERT INTO `words` VALUES (38600, NULL, 'adv. adv独特地, 唯一地', '/ju:\'ni:kli/', 'uniquely', 3);
INSERT INTO `words` VALUES (38601, 'Creativity and uniqueness often depends on how well you hide your sources.', 'n. 唯一性, 独特性', '/ju:\'ni:knis | jʊ\'niknɪs/', 'uniqueness', 3);
INSERT INTO `words` VALUES (38602, 'a Russian army unit', 'n. 个体,(计量)单位', '/\'ju:nit | \'juːnɪt | \'junɪt/', 'unit', 3);
INSERT INTO `words` VALUES (38603, 'economic unity', 'n. 团结, 联合', '/\'ju:niti | ˈjuːnəti | \'junəti/', 'unity', 3);
INSERT INTO `words` VALUES (38604, 'free universal healthcare', 'adj. 普遍的,全体的', '/,ju:ni\'və:səl | juːnɪ\'vɜːs(ə)l | \'jʊnə\'vɝsl/', 'universal', 3);
INSERT INTO `words` VALUES (38605, 'Secondly, the relationship between universality and specificity.', 'n. 普遍性, 一般性', '/,ju:nivə:\'sæləti | ,juːnɪvɜː\'sælətɪ | ,jʊnəvɝ\'sæləti/', 'universality', 3);
INSERT INTO `words` VALUES (38606, '...a universally accepted point of view.', 'adv. 普遍地', '/,ju:ni\'və:səli | juːnɪ\'vɜːsəlɪ | ,junɪ\'vɝsəli/', 'universally', 3);
INSERT INTO `words` VALUES (38607, 'Einstein\'s equations showed the universe to be expanding.', 'n. 宇宙,万物', '/\'ju:nivə:s | \'juːnɪvɜːs | \'junɪvɝs/', 'universe', 3);
INSERT INTO `words` VALUES (38608, 'He teaches Esperanto at that university.', 'n. (综合)大学', '/,ju:ni\'və:səti | juːnɪ\'vɜːsɪtɪ | ,junɪ\'vɝsəti/', 'university', 3);
INSERT INTO `words` VALUES (38609, 'unjust laws', 'adj. 不公平的', '/,ʌn\'dʒʌst | ʌn\'dʒʌst | \'ʌn\'dʒʌst/', 'unjust', 3);
INSERT INTO `words` VALUES (38610, 'Some governments have been victims and perhaps unknowing accomplices in the bank\'s activities.', 'adj. 没查觉的, 无知的', '/,ʌn\'nəuiŋ | ʌn\'nəʊɪŋ | ʌn\'noɪŋ/', 'unknowing', 3);
INSERT INTO `words` VALUES (38611, 'The murderer’s identity remains unknown.', 'adj. 不知道的,未知的', '/\'ʌn\'nəun | ʌn\'nəʊn | ,ʌn\'non/', 'unknown', 3);
INSERT INTO `words` VALUES (38612, 'Unless some extra money is found, the theatre will close.', 'conj. 如果不,除非', '/ʌn\'les | ən\'lɛs/', 'unless', 3);
INSERT INTO `words` VALUES (38613, 'Now I see that, unlike her, they were my positive models.', 'adj. 不同的; prep. 不象…', '/,ʌn\'laik | ʌn\'laɪk | \'ʌn\'laɪk/', 'unlike', 3);
INSERT INTO `words` VALUES (38614, 'The system can support an unlimited number of users.', 'adj. 无限的；过渡的', '/,ʌn\'limitid | ʌn\'lɪmɪtɪd/', 'unlimited', 3);
INSERT INTO `words` VALUES (38615, 'Unload everything from the boat and clean it thoroughly.', 'v. 卸货; v. 摆脱之负担', '/,ʌn\'ləud | ʌn\'ləʊd | \'ʌn\'lod/', 'unload', 3);
INSERT INTO `words` VALUES (38616, 'People were visiting the house every day, sometimes in unmanageable numbers.', 'adj. 难处理的, 难控制的', '/ʌn\'mænidʒəbl | ʌn\'mænɪdʒəb(ə)l | ʌn\'mænɪdʒəbl/', 'unmanageable', 3);
INSERT INTO `words` VALUES (38617, 'unmarried mothers', 'adj. 未婚的, 单身的', '/,ʌn\'mærid | ʌn\'mærɪd | ,ʌn\'mærɪd/', 'unmarried', 3);
INSERT INTO `words` VALUES (38618, 'a woman of unmatched beauty', 'adj. 无与伦比的,不相配的', '/,ʌn\'mætʃt | ʌn\'mætʃt | \'ʌn\'mætʃt/', 'unmatched', 3);
INSERT INTO `words` VALUES (38619, 'the unmistakable sound of gunfire', 'adj. 明显的,不会弄错的', '/,ʌnmi\'steikəbl | ʌnmɪ\'steɪkəb(ə)l | ,ʌnmɪ\'stekəbl/', 'unmistakable', 3);
INSERT INTO `words` VALUES (38620, 'It was very cold, which seemed unnatural for late spring.', 'adj. 不自然的, 反常的', '/,ʌn\'nætʃərəl | ʌn\'nætʃ(ə)r(ə)l | ʌn\'nætʃrəl/', 'unnatural', 3);
INSERT INTO `words` VALUES (38621, 'What you should not do is prevent or override it unnecessarily.', 'adv. 不必要地, 徒然', '/ʌn\'nesisərili/', 'unnecessarily', 3);
INSERT INTO `words` VALUES (38622, 'There’s no point in taking unnecessary risks.', 'adj. 不必要的,多余的', '/,ʌn\'nesəsəri | ʌn\'nesəs(ə)rɪ | ʌn\'nɛsə\'sɛri/', 'unnecessary', 3);
INSERT INTO `words` VALUES (38623, 'They might kill people slowly in a way that\'s unnoticeable, taking effect over perhaps 10 - 30 years by accelerating degenerative diseases.', 'adj. 不引人注意的(', '/\'ʌn\'nəutisəbl | ʌn\'nəʊtɪsəb(ə)l/', 'unnoticeable', 3);
INSERT INTO `words` VALUES (38624, 'Elsa stood unnoticed at the edge of the crowd.', 'adj. 不被注意的, 被忽视的', '/,ʌn\'nəutist | ʌn\'nəʊtɪst | ,ʌn\'notɪst/', 'unnoticed', 3);
INSERT INTO `words` VALUES (38625, 'It basically means that you have a theory about the unobservable psychological states that are governing — or causing — other people\'s behaviors.', 'adj. 不可见的', '/\'ʌnəb\'zə:vəbl | ʌnəb\'zɜːvəb(ə)l/', 'unobservable', 3);
INSERT INTO `words` VALUES (38626, 'Fresh fruit was unobtainable in the winter.', 'adj. 无法得到的,难获得的', '/,ʌnəb\'teinəbl | ʌnəb\'teɪnəb(ə)l | ,ʌnəb\'tenəbl/', 'unobtainable', 3);
INSERT INTO `words` VALUES (38627, 'However, to do so, it must find an unoccupied territory and a member of the opposite sex with which to mate.', 'adj. 空闲的,未占领的', '/,ʌn\'ɔkjupaid | ʌn\'ɒkjʊpaɪd | ,ʌn\'ɑkjupaɪd/', 'unoccupied', 3);
INSERT INTO `words` VALUES (38628, 'The unpalatable truth is that the team isn’t getting any better.', 'adj. 味道差的,难吃的', '/,ʌn\'pælətəbl | ʌn\'pælətəb(ə)l | ʌn\'pælətəbl/', 'unpalatable', 3);
INSERT INTO `words` VALUES (38629, 'an achievement unparalleled in sporting history', 'adj. 无比的, 空前的', '/,ʌn\'pærəleld | ʌn\'pærəleld | ʌn\'pærəlɛld/', 'unparalleled', 3);
INSERT INTO `words` VALUES (38630, 'an unplanned pregnancy', 'adj. 意外的,在计划外的', '/\'ʌn\'plænd | ,ʌn\'plænd/', 'unplanned', 3);
INSERT INTO `words` VALUES (38631, 'an unpleasant experience', 'adj. 不愉快的；不合意的', '/,ʌn\'plezənt | ʌn\'plez(ə)nt | ʌn\'plɛznt/', 'unpleasant', 3);
INSERT INTO `words` VALUES (38632, 'an unpopular choice', 'adj. 不流行的, 不受欢迎的', '/,ʌn\'pɔpjulə | ʌn\'pɒpjʊlə | ʌn\'pɑpjəlɚ/', 'unpopular', 3);
INSERT INTO `words` VALUES (38633, 'He took the unprecedented step of stating that the rumours were false.', 'adj. 空前的, 前所未有的', '/,ʌn\'presidəntid | ʌn\'presɪdentɪd | ʌn\'prɛsɪdɛntɪd/', 'unprecedented', 3);
INSERT INTO `words` VALUES (38634, 'The danger lies in its unpredictability. Yet that may also be a reason for hope.', 'n. 不可预测性', '/,ʌnpri,diktə\'biliti | ˌʌnprɪˌdɪktə\'bɪlətɪ/', 'unpredictability', 3);
INSERT INTO `words` VALUES (38635, 'He is utterly unpredictable.', 'adj. 不可预知的', '/,ʌnpri\'diktəbl | ʌnprɪ\'dɪktəb(ə)l | ,ʌnprɪ\'dɪktəbl/', 'unpredictable', 3);
INSERT INTO `words` VALUES (38636, 'Because the cave fish may not need less sleep—they may need to stay awake to forage more in an environment where food can be scarce and appear unpredictably.', 'adv. 不可预见地, 不能预料地', '/,ʌn\'pridiktəbəl | ˌʌnprɪˈdɪktəblɪ/', 'unpredictably', 3);
INSERT INTO `words` VALUES (38637, 'Reduce packaging by eating more whole, unprocessed foods and using the bulk bins for items that have a long shelf-life.', 'adj. 未被加工的', '/ʌn\'prəusest/', 'unprocessed', 3);
INSERT INTO `words` VALUES (38638, 'an unproductive meeting', 'adj. 不生产的, 徒劳的', '/,ʌnprə\'dʌktiv | ʌnprə\'dʌktɪv | \'ʌnprə\'dʌktɪv/', 'unproductive', 3);
INSERT INTO `words` VALUES (38639, 'unprofitable businesses', 'adj. 没有利润的, 无益的', '/,ʌn\'prɔfitəbl | ʌn\'prɒfɪtəb(ə)l | ʌn\'prɑfɪtəbl/', 'unprofitable', 3);
INSERT INTO `words` VALUES (38640, 'In fact, his business career had distinctly unpromising beginnings.', 'adj. 没有希望的(结果未必良好的)', '/,ʌn\'prɔmisiŋ | ʌn\'prɒmɪsɪŋ | ʌn\'prɑmɪsɪŋ/', 'unpromising', 3);
INSERT INTO `words` VALUES (38641, 'Thieves often target unprotected vehicles.', 'adj. 无保护的, 未做防护措施的', '/\'ʌnprə\'tektid | ʌnprə\'tektɪd | ,ʌnprə\'tɛktɪd/', 'unprotected', 3);
