INSERT INTO `words` VALUES (38644, 'The Eiffel Tower is unquestionably one of Paris’s most familiar landmarks.', 'adv. 无可非议地,确凿地', '/ʌn\'kwestʃənəbli | ʌn\'kwɛstʃənəbli/', 'unquestionably', 3);
INSERT INTO `words` VALUES (38645, 'an unquestioning belief in God', 'adj. 无条件的, 不犹豫的', '/ʌn\'kwestʃəniŋ | ʌn\'kwestʃ(ə)nɪŋ | ʌn\'kwɛstʃənɪŋ/', 'unquestioning', 3);
INSERT INTO `words` VALUES (38646, 'He could unravel a knot that others wouldn\'t even attempt.', 'v. 拆开,拆开', '/,ʌn\'rævəl | ʌn\'rævl/', 'unravel', 3);
INSERT INTO `words` VALUES (38647, 'Objects that are unmarked at the end of the mark phase are unreachable by the application (dead) because there\'s no path from the root set through any series of references to find them.', 'adj. 不能到达的, 不能得到的', '/ʌn\'ri:tʃəbl/', 'unreachable', 3);
INSERT INTO `words` VALUES (38648, NULL, 'adj. 没有人看的, 无学问的', '/,ʌn\'red | ʌn\'red | ,ʌn\'rɛd/', 'unread', 3);
INSERT INTO `words` VALUES (38649, 'It seemed unreal to be sitting and talking to someone so famous.', 'adj. 不真实的, 虚幻的', '/,ʌn\'riəl | ʌn\'rɪəl/', 'unreal', 3);
INSERT INTO `words` VALUES (38650, 'I hadn’t been to the city for 20 years and it was almost unrecognizable.', 'adj. 未被承认的, 无法识别的', '/,ʌnrekəg\'naizəbl | ,ʌnrɛkəɡ\'naɪzəbl/', 'unrecognizable', 3);
INSERT INTO `words` VALUES (38651, 'The car’s becoming very unreliable.', 'adj. 不可靠的', '/,ʌnri\'laiəbl | ʌnrɪ\'laɪəb(ə)l | ,ʌnrɪ\'laɪəbl/', 'unreliable', 3);
INSERT INTO `words` VALUES (38652, 'the unresolved issue of who will pay for the project', 'adj. 未解决的，未决定的', '/\'ʌnri\'zɔlvd | ʌnrɪ\'zɒlvd | ,ʌnrɪ\'zɑlvd/', 'unresolved', 3);
INSERT INTO `words` VALUES (38653, 'Freedom to pursue extracurricular activities is totally unrestricted.', 'adj. 自由的,无限制的', '/,ʌnri\'striktid | ʌnrɪ\'strɪktɪd | ,ʌnrɪ\'strɪktɪd/', 'unrestricted', 3);
INSERT INTO `words` VALUES (38654, 'The building is unsafe.', 'adj. 不安全的', '/,ʌn\'seif | ʌn\'seɪf | ʌn\'sef/', 'unsafe', 3);
INSERT INTO `words` VALUES (38655, 'an unsatisfactory situation', 'adj. 不令人满意的,不满足的', '/\'ʌn,sætis\'fæktəri | ,ʌnsætɪs\'fækt(ə)rɪ | ,ʌn,sætɪs\'fæktəri/', 'unsatisfactory', 3);
INSERT INTO `words` VALUES (38656, '...unskilled work done by unschooled people.', 'adj. 天生的,未受学校教育的', '/,ʌn\'sku:ld | ʌn\'skuːld/', 'unschooled', 3);
INSERT INTO `words` VALUES (38657, 'Raj crept out of the house unseen.', 'adj. 未见过的', '/,ʌn\'si:n | ʌn\'siːn | ,ʌn\'sin/', 'unseen', 3);
INSERT INTO `words` VALUES (38658, 'A term given to viewers who are unselective about the content they watch.', 'adj. 非选择性的', NULL, 'unselective', 3);
INSERT INTO `words` VALUES (38659, 'She started to get a reputation as an unselfish girl with a heart of gold.', 'adj. 无私的,慷慨的', '/,ʌn\'selfiʃ | ʌn\'selfɪʃ | ʌn\'sɛlfɪʃ/', 'unselfish', 3);
INSERT INTO `words` VALUES (38660, 'The sudden changes unsettled Judy.', 'v. 不安', '/,ʌn\'setl | ʌn\'set(ə)l | ,ʌn\'sɛtl/', 'unsettle', 3);
INSERT INTO `words` VALUES (38661, 'companies employing unskilled labour', 'adj. 不熟练的,拙劣的', '/,ʌn\'skild | ʌn\'skɪld | ,ʌn\'skɪld/', 'unskilled', 3);
INSERT INTO `words` VALUES (38662, 'an unsophisticated audience', 'adj. 不谙世故的, 不复杂的', '/,ʌnsə\'fistikeitid | ʌnsə\'fɪstɪkeɪtɪd | ,ʌnsə\'fɪstɪketɪd/', 'unsophisticated', 3);
INSERT INTO `words` VALUES (38663, 'The meeting will take place at an unspecified date in the future.', 'adj. 未详细说明的', '/,ʌn\'spesifaid | ʌn\'spesɪfaɪd | ,ʌn\'spɛsɪfaɪd/', 'unspecified', 3);
