INSERT INTO `words` VALUES (38665, 'The political situation is still very unstable.', 'adj. 不牢固的, 不稳定的', '/,ʌn\'steibl | ʌn\'steɪb(ə)l | ʌn\'stebl/', 'unstable', 3);
INSERT INTO `words` VALUES (38666, 'unsubstantiated allegations of child abuse', 'adj. 未经证实的,无事实根据的', '/,ʌnsəb\'stænʃieitid | ʌnsəb\'stænʃɪeɪtɪd | ,ʌnsəb\'stænʃɪetɪd/', 'unsubstantiated', 3);
INSERT INTO `words` VALUES (38667, 'an unsuccessful attempt to climb Qomolangma', 'adj. 不成功的,失败的', '/,ʌnsək\'sesful | ʌnsək\'sesfʊl; -f(ə)l | ,ʌnsək\'sɛsfl/', 'unsuccessful', 3);
INSERT INTO `words` VALUES (38668, 'unsuitable housing', 'adj. 不适宜的, 不合适的', '/,ʌn\'sju:təbl | ʌn\'suːtəb(ə)l; -\'sjuːt- | ʌn\'sutəbl/', 'unsuitable', 3);
INSERT INTO `words` VALUES (38669, 'one of the unsung heroes of French politics', 'adj. 未唱的,未赞颂的', '/,ʌn\'sʌŋ | ʌn\'sʌŋ/', 'unsung', 3);
INSERT INTO `words` VALUES (38670, 'Chris seemed nervous and unsure of herself.', 'adj. 没有自信的, 不确定的', '/,ʌn\'ʃuə | ʌn\'ʃʊə | ,ʌn\'ʃʊr/', 'unsure', 3);
INSERT INTO `words` VALUES (38671, 'The public psychosocial status is mostly affected by the unsureness of information in the event of epidemic outbreak.', 'n. 不确定, 缺乏自信', NULL, 'unsureness', 3);
