INSERT INTO `words` VALUES (38673, 'This is the issue for Socrates, how to channel this wild and untamed passion of spirit or heart, how to channel this to some kind of common good.', 'adj. 未驯服的， 难驾驭的', '/ˌʌn\'teɪmd | ,ʌn\'temd/', 'untamed', 3);
INSERT INTO `words` VALUES (38674, 'Older people are an untapped resource in the employment market.', 'adj. 塞子未开的, 未使用的', '/ʌn\'tæpt | ,ʌn\'tæpt/', 'untapped', 3);
INSERT INTO `words` VALUES (38675, 'Peter untied his shoelaces.', 'v. 解开, 松开', '/,ʌn\'tai | ʌn\'taɪ/', 'untie', 3);
INSERT INTO `words` VALUES (38676, NULL, 'a&ad. 不适时的, 不合时宜的', '/,ʌn\'taimli | ʌn\'taɪmlɪ | ʌn\'taɪmli/', 'untimely', 3);
INSERT INTO `words` VALUES (38677, 'The rumours will do untold damage to his reputation.', 'adj. 未说过的,未透露的', '/,ʌn\'təuld | ʌn\'təʊld | ,ʌn\'told/', 'untold', 3);
INSERT INTO `words` VALUES (38678, 'Several papers lay untouched on the desk.', 'adj. 未触及的, 未改变的', '/,ʌn\'tʌtʃt | ʌn\'tʌtʃt/', 'untouched', 3);
INSERT INTO `words` VALUES (38679, 'He moved to New York and performed an untraditional roster of penniless actor jobs – yoga instructor, manure shoveller, railroad-loader.', 'adj. 非传统的,不符合传统的', NULL, 'untraditional', 3);
INSERT INTO `words` VALUES (38680, 'untreated sewage', 'adj. 未经处理的, 未经治疗的', '/\'ʌn\'tri:tid | ,ʌn\'tritɪd/', 'untreated', 3);
INSERT INTO `words` VALUES (38681, 'allegations that are totally untrue', 'adj. 不真实的, 不正确的', '/,ʌn\'tru: | ʌn\'truː | ʌn\'tru/', 'untrue', 3);
INSERT INTO `words` VALUES (38682, 'Allow any part of the subtle bodies that is twisted to untwist and separate from any other that one is intertwined with.', 'v. 拆开(搓合的绳,线等), 解开', '/,ʌn\'twist | ʌn\'twɪst/', 'untwist', 3);
INSERT INTO `words` VALUES (38683, 'Bombing had made roads and railways unusable.', 'adj. 不能用的,与众不同的', '/,ʌn\'ju:zəbl | ,ʌn\'juzəbl/', 'unusable', 3);
INSERT INTO `words` VALUES (38684, 'unused land', 'adj. 不用的；未消耗的', '/,ʌn\'ju:zd | ,ʌn\'juːzd | \'ʌn\'jʊzd/', 'unused', 3);
INSERT INTO `words` VALUES (38685, 'an unusual feature', 'adj. 异常的,独特的', '/,ʌn\'ju:ʒuəl | ʌn\'juːʒʊəl | ʌn\'jʊʒʊəl/', 'unusual', 3);
